INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(179212, 'ع', '<span class=\"hlight\">ع .</span> (حرف ) حرف بیست ویکم است از حروف الفبای فارسی و حرف هیجدهم از الفبای «ابتثی » عربی پس از ظ و پیش از غ، و حرف شانزدهم از الفبای ابجدی پس از س و پیش از ف، و نام آن عین است و به حساب جُمّل نماینده ٔ عدد هفتاد بود. (فرهنگ نظام ) (آنندراج ). و از حروف ششگانه ٔ حلق و از حروف تُرابیه یا أرضیه است . (برهان ). و از حروف مصمته است . (آنندراج ). <BR><font color=\"Blue\">◄</font> رمزی است علیه السلام را که صورت دیگر آن «<span class=\"hlight\" dir=\"rtl\">٤</span>» است . <BR><font color=\"Blue\">◄</font> در فرهنگها علامت عربی بودن کلمه است . <BR><font color=\"Blue\">◄</font> و در هیئت علامت تربیع است . <BR><font color=\"Blue\">◄</font> و نیز علامت مصراع است یعنی نصف بیت . <BR><font color=\"Blue\">◄</font> در معجم های جغرافیائی رمز است موضع را. <BR><font color=\"Blue\">◄</font> و رمزی است عین بمعنی چشمه را. <BR><font color=\"Blue\">◄</font> این حرف در تمام زبانهای سامی بوده و نامش در تهجی عبرانی عین است بمعنی چشم چه شکل حرف مذکور در آن زبان شباهت بچشم دارد اما این تطبیق لفظ و معنی بر سبیل اتفاق است و الا حروف عربی از عبرانی بدون ملاحظه ٔ معنی گرفته شده است . (فرهنگ نظام ) (آنندراج ). <BR><font color=\"Blue\">◄</font> این حرف از حروف مخصوص کلمات عربی است و در زبان فارسی صدای همزه دارد و در کلماتی دیده میشود که فارسیان از زبان عربی گرفته اند مانند عمر، عالی، عارض و یا از کلماتی که عربها در آن تصرف کرده اند مانند عاقرقرحا و نعناع و جز آن . (ناظم الاطباء).<br />ابدالها:<br />> در عربی بدل به ح شود:<br />ضعیف = نحیف <br />ضعف = نحف <br />طلع= طلح <br />طماع = طماح <br />عدس = حدس <br />نفاع = نفاح <br />عنی = حتی . (از منتهی الارب ).<br /><BR><font color=\"Blue\">◄</font> «ع <span class=\"hlight\" dir=\"rtl\">١</span>» رمز است ربیعالاول و«ع <span class=\"hlight\" dir=\"rtl\">٢</span>» رمز است ربیعالثانی را.<br /></font></div>'),
(179213, 'عا', '<span class=\"hlight\">عا.</span> (ع اِ صوت ) کلمه ای است که بدان بز را زجر کنند و رانند. (ناظم الاطباء) (منتهی الارب ).<br /></font></div>'),
(179214, 'عاب', '<span class=\"hlight\">عاب .</span> (ع اِ) آهو. عیب . (منتهی الارب ) (آنندراج ). رجوع به عیب شود.<br /></font></div>'),
(179215, 'عابث', '<span class=\"hlight\">عابث .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) بازی کننده . (آنندراج ) (غیاث اللغات ) <span class=\"hlight\">:</span> <br />آدمی داند که خانه حادث است <br />عنکبوتی نی که در وی عابث است .<br /><font color=\"Red\">مولوی .</font><br />روی به دفع حوادث و تدارک خطوب روزگار عابث آریم . (جهانگشای جوینی ).<br /></font></div>'),
(179216, 'عابد', '<span class=\"hlight\">عابد.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن عمربن مخزوم . پدر عبداﷲبن سائب عابدی صحابی و عبداﷲبن مسیب عابدی محدث است . (از منتهی الارب ).<br /></font></div>'),
(179217, 'عابد', '<span class=\"hlight\">عابد.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) بیرمی لاری . از شعرا است . هدایت نویسد: نامش زین العابدین و معروف به شاه زند است . اشعار بطریق عرفا بسیار دارد از آن جمله است :<br />آستین برمیفشاندم در سماع <br />دست یار آمد بدستم یللی .<br /> <font color=\"Red\">(مجمع الفصحاء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٩</span>).</font><br />او راست : روضة المؤمنین . (الذریعه ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦٢</span>) (صبح گلشن ص <span class=\"hlight\" dir=\"rtl\">٢٦٥</span>).<br /></font></div>'),
(179218, 'عابد', '<span class=\"hlight\">عابد.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) کوهی است . (منتهی الارب ). کوهی است در اطراف مصر... (معجم البلدان ).<br /></font></div>'),
(179219, 'عابد', '<span class=\"hlight\">عابد.</span><font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) پرستنده ٔ خدا و ملتزم به شرائع دین . (از اقرب الموارد). پرستنده . عبادت کننده <span class=\"hlight\">:</span> <br />عابدان را پرده این خواهد درید<br />زاهدان را توبه آن خواهد شکست .<br /> <font color=\"Red\">خاقانی .</font><br />خدا از عابدان آنها گزیند<br />که در راه خدا آن را نبیند.<br /> <font color=\"Red\">نظامی .</font><br />چه گویی در حق فلان عابد که دیگران به طعنه سخنها گفته اند. (گلستان سعدی ).<br />گفتم میان عالم و عابد چه فرق بود<br />تا اختیار کردی از آن این فریق را.<br /> <font color=\"Red\">سعدی (گلستان ).</font><br /><BR><font color=\"Blue\">◄</font> موحد. (ذیل اقرب الموارد بنقل از تاج العروس ). <BR><font color=\"Blue\">◄</font> خادم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد با ننگ و عار. و گفته اند بدین معنی است قول خداوند تعالی <span class=\"hlight\">:</span> ان کان للرحمن ولد فانا اول العابدین . (قرآن <span class=\"hlight\" dir=\"rtl\">٨١/٤٣</span>). أی اول الاَّنفین . (از منتهی الارب ).<br /></font></div>'),
(179220, 'عابد بخاری', '<span class=\"hlight\">عابد بخاری .</span> <font color=\"DarkGreen\"><b>[ ب ِ دِ ب ُ ]</font></b> (اِخ ) راقم . شاعر فارسی زبان و معاصر نصرآبادی است . شعرش در تذکره ٔ نصرآبادی ص <span class=\"hlight\" dir=\"rtl\">٤٣٩</span> آمده است .<br /></font></div>'),
(179221, 'عابدآباد', '<span class=\"hlight\">عابدآباد.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) قریه ای است به سه فرسنگی میانه ٔ شمال و مغرب شهر خفر شهرستان جهرم . (فارسنامه ). دهی است از دهستان بخش خفر شهرستان جهرم واقع در <span class=\"hlight\" dir=\"rtl\">٣٢</span> هزارگزی شمال باختری باب انار و یک هزارگزی راه عمومی خفر به کوار. در دامنه واقع و هوای آن معتدل و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">١٦٧</span> تن سکنه دارد. آب آن از رودخانه ٔ قره آغاج تأمین میشودو محصول آن غلات، برنج، بادام و میوه است . شغل اهالی زراعت و باغبانی و صنعت دستی زنان گلیم بافی میباشد.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(179222, 'عابدالاوثان', '<span class=\"hlight\">عابدالاوثان .</span> <font color=\"DarkGreen\"><b>[ ب ِ دُل ْ اَ ]</font></b> (ع ص مرکب ) بت پرست . (مهذب الاسماء).<br /></font></div>'),
(179223, 'عابدفریب', '<span class=\"hlight\">عابدفریب .</span> <font color=\"DarkGreen\"><b>[ ب ِ ف ِ <span class=\"hlight\" dir=\"rtl\">/</span> ف َ ]</font></b> (نف مرکب ) فریبنده ٔ عابد. که عابد رااز عبادت خدا باز دارد. سخت زیبا چنانکه عابد تارک دنیا را نیز بفریبد و شیفته ٔ خویش سازد <span class=\"hlight\">:</span> <br />از این مه پاره ٔ عابدفریبی <br />ملائک سیرتی خورشیدزیبی .<br /> <font color=\"Red\">سعدی .</font><br />گوئی دو چشم جادوی عابدفریب او<br />بر چشم من بسحر ببستند خواب را.<br /> <font color=\"Red\">سعدی .</font><br />آن چشم آهوانه ٔ عابدفریب بین <br />کش کاروان سحر بدنباله میرود.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(179224, 'عابدی', '<span class=\"hlight\">عابدی .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ص نسبی ) نسبت است به عابدبن عمروبن مخزوم . (الانساب سمعانی ).<br /></font></div>'),
(179225, 'عابدین', '<span class=\"hlight\">عابدین .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) از مزارع قریه ٔ طالقان قم است . (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٢</span>).<br /></font></div>'),
(179226, 'عابدین', '<span class=\"hlight\">عابدین .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) (زین العابدین ) لقب علی بن الحسین است . (از الاعلام زرکلی ). رجوع به علی بن الحسین شود.<br /></font></div>'),
(179227, 'عابر', '<span class=\"hlight\">عابر.</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) عبورکننده و راه گذرنده . (آنندراج ) (منتهی الارب ) (غیاث اللغات ).<BR><font color=\"HotPink\">♦ </font>عابر سبیل ؛ راه گذر. مسافر. (منتهی الارب ) (آنندراج ). رجوع به همین ترکیب شود. <BR><font color=\"Blue\">◄</font> با اشک، گویند رجل عابر و امراءة عابر. (منتهی الارب ).<br /></font></div>'),
(179228, 'عابر', '<span class=\"hlight\">عابر.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) ابن شالخ بن ارفخشدبن سام بن نوح . (آنندراج ) (منتهی الارب ). در لباب الانساب عابربن ارفخشدبن سام بن نوح، ضبط شده است .<br /></font></div>'),
(179229, 'عابرسبیل', '<span class=\"hlight\">عابرسبیل .</span> <font color=\"DarkGreen\"><b>[ ب ِ رِ س َ ]</font></b> (ترکیب اضافی، اِ مرکب ) رهگذر. مسافر. (منتهی الارب ) <span class=\"hlight\">:</span> <br />ساکن خانه ٔ علوم توئی <br />غیر تو عابر سبیل آمد.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(179230, 'عابری', '<span class=\"hlight\">عابری .</span> <font color=\"DarkGreen\"><b>[ب ِ ]</font></b> (ص نسبی ) منسوب به عابِر. رجوع به عابر شود.<br /></font></div>'),
(179231, 'عابری', '<span class=\"hlight\">عابری .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ص نسبی ) نسبت است به عابربن ارفخشدبن سام . (لباب الانساب ). رجوع به عابَربن شالخ شود.<br /></font></div>'),
(179232, 'عابس', '<span class=\"hlight\">عابس .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ع ص ) ترشروی . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) شیر بیشه . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(179233, 'عابس', '<span class=\"hlight\">عابس .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) نام شمشیرعبدالرحمان بن سلیم کلبی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179234, 'عابس', '<span class=\"hlight\">عابس .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (اِخ ) ابن سعید المرادی . قاضی و ازوالیان و پیشوایان بود. مسلمةبن مخلد به سال <span class=\"hlight\" dir=\"rtl\">٤٩</span> هَ . ق . وی را شرطگی مصر سپس ولایت دریا داد و عابس در مرزها غزو کرد. دیگر بار وی را مسلمة به سال <span class=\"hlight\" dir=\"rtl\">٥٧</span> بشرطگی بازگرداند و به سال <span class=\"hlight\" dir=\"rtl\">٦٠</span> خلیفتی خویش در فسطاط بدو گذاشت . آنگاه قضاوت و شرطگی با هم یافت و بدان دو شغل بود تا به سال <span class=\"hlight\" dir=\"rtl\">٦٨</span> هَ . ق . درگذشت . (الاعلام زرکلی ).<br /></font></div>'),
(179235, 'عابسی', '<span class=\"hlight\">عابسی .</span> <font color=\"DarkGreen\"><b>[ ب ِ ]</font></b> (ص نسبی ) نسبت است به بنی عابس از بکربن وائل . (از الانساب سمعانی ). مؤلف لباب الانساب نویسد: صحیح این نسبت عایشی است نه عابسی .<br /></font></div>'),
(179236, 'عابیة', '<span class=\"hlight\">عابیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) زن نیکوروی حسنة. (منتهی الارب ) (آنندراج ). زن زیبا. گویند: جاریة عابیة. (اقرب الموارد).<br /></font></div>'),
(179237, 'عات', '<span class=\"hlight\">عات .</span> <font color=\"DarkGreen\"><b>[ ت ِ ن ْ ]</font></b> (ع ص ) متکبر و درگذرنده از حد.(منتهی الارب ) (آنندراج ). عاتی . رجوع به عاتی شود.<br /></font></div>'),
(179238, 'عاتب', '<span class=\"hlight\">عاتب .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (ع ص ) ملامت کننده . سرزنش کننده . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آنکه یک پای وی بریده بود و بر دیگر پای رود. (مهذب الاسماء).<br /></font></div>'),
(179239, 'عاتر', '<span class=\"hlight\">عاتر.</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (اِخ ) شهری است در ساحل یهودا صحیفه ٔ یوشع <span class=\"hlight\" dir=\"rtl\">١٩</span> : <span class=\"hlight\" dir=\"rtl\">٧</span> که آن را توکن نیز گویند کتاب اول تواریخ ایام <span class=\"hlight\" dir=\"rtl\">٤</span> : <span class=\"hlight\" dir=\"rtl\">٣٢</span> و بعضی را گمان چنان است که عاتر همان تل آثار است و دیگران آن را عتاره گویند و بعضی گمان دارند که عطره میباشد. (قاموس کتاب مقدس ).<br /></font></div>'),
(179240, 'عاتر', '<span class=\"hlight\">عاتر.</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (ع ص ) مضطرب . (مهذب الاسماء). به اهتزاز درآینده . گویند: عنده سیف باتر و رمح عاتر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> فرج دروا کرده از شهوت . (تاج العروس ) (منتهی الارب ). فرج گشاده از تیزی شهوت . (منتهی الارب ).<br /></font></div>'),
(179241, 'عاتق', '<span class=\"hlight\">عاتق .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (ع ص ) آزاد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> می کهنه که مهر از آن برداشته باشند. <BR><font color=\"Blue\">◄</font> خیک فراخ . <BR><font color=\"Blue\">◄</font> دختر نوجوان یا دختر نوبالغ یا زن بی نکاح یا زن جوانی که در خانه ٔ پدر مانده . <BR><font color=\"Blue\">◄</font> (اِ) دوش و جای چادر پوشیدن از دوش . مابین کتف و بن گردن . ج، عُتُق . <BR><font color=\"Blue\">◄</font> (ص ) کمان کهنه ٔ سرخ رنگ . <BR><font color=\"Blue\">◄</font> (اِ) چوزه ٔ مرغ که قوت گرفته و به پریدن رسیده باشد. <BR><font color=\"Blue\">◄</font> چوزه ٔ سنگخواره . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بچه کبوتر که هنوز قوت نگرفته باشد. ج، عواتق . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179242, 'عاتق الثریا', '<span class=\"hlight\">عاتق الثریا.</span> <font color=\"DarkGreen\"><b>[ ت ِ ق ُث ْث ُ رَی ْ یا ]</font></b> (اِخ ) ستاره ای است . (اقرب الموارد).<br /></font></div>'),
(179243, 'عاتم', '<span class=\"hlight\">عاتم .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (ع ص ) مهمان شبانگاه آینده . یقال : جائنا ضیف عاتم . (منتهی الارب ) (آنندراج ). جاءَ نا ضیف عاتم ؛ ای بطی ٔ ممس . (اقرب الموارد).<br /></font></div>'),
(179244, 'عاتمات', '<span class=\"hlight\">عاتمات .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b>(ع ص ) النجوم العاتمات ؛ ستارگان که از تیرگی هوا تاریک و پوشیده گردند. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(179245, 'عاتن', '<span class=\"hlight\">عاتن .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (ع ص ) توانا. (منتهی الارب ).<br /></font></div>'),
(179246, 'عاتک', '<span class=\"hlight\">عاتک .</span> <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> (ع ص ) بی آمیغ از رنگها. (منتهی الارب ). خالص از هر رنگ و از هرچیز. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> جوانمرد. (منتهی الارب ). کریم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ستیهنده . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> از حالی بحالی گردنده . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> کمان کهنه ٔ سرخ . (شرح قاموس ) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نبیذ صاف و پاکیزه . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179247, 'عاتی', '<span class=\"hlight\">عاتی .</span> (ع ص ) (از: عتو). متکبر و از حد درگذرنده . (آنندراج ). <BR><font color=\"Blue\">◄</font> مردی درشونده در فساد که پند هیچکس نپذیرد. (مهذب الاسماء).<br /></font></div>'),
(179248, 'عاتیة', '<span class=\"hlight\">عاتیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) مؤنث عاتی . رجوع به عاتی شود. <BR><font color=\"Blue\">◄</font> سخت وزنده . (از اقرب الموارد) <span class=\"hlight\">:</span> و اما عاد فاهلکوا بریح صرصر عاتیة. (قرآن <span class=\"hlight\" dir=\"rtl\">٦/٦٩</span>).<br /></font></div>'),
(179249, 'عاثر', '<span class=\"hlight\">عاثر.</span> <font color=\"DarkGreen\"><b>[ ث ِ ]</font></b> (ع ص ) شکوخنده . لغزنده . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> دروغگو. (اقرب الموارد).<br /></font></div>'),
(179250, 'عاثره', '<span class=\"hlight\">عاثره .</span> <font color=\"DarkGreen\"><b>[ ث ِ رَ ]</font></b> (ع ص ) مؤنث عاثر. رجوع به عاثر شود. <BR><font color=\"Blue\">◄</font> (اِ) حادثه که موجب عثور شود. (از اقرب الموارد).<br /></font></div>'),
(179251, 'عاثور', '<span class=\"hlight\">عاثور.</span> (ع اِ) جای هلاک . گویند: وقع فی عاثور شر و عافور شر. (منتهی الارب ). المهلکة من الارضین . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بدی . (منتهی الارب ). شر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گوی که جهت شکار شیر و جز آن کنند. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گو و مانند آن که آماده شود تا کسی در آن افتد. و آن فاعول است از عثار. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه بدان لغزند. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> چاه . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(179252, 'عاج', '<span class=\"hlight\">عاج .</span> <font color=\"DarkGreen\"><b>[ عاج ج ]</font></b> (ع ص ) طریق عاج ؛راه پر از روندگان . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(179253, 'عاج', '<span class=\"hlight\">عاج .</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (ع اِ) مبنی بر کسر زجری است مر ناقه را. (منتهی الارب ).<br /></font></div>'),
(179254, 'عاج', '<span class=\"hlight\">عاج .</span> (ع اِ) استخوان پشت دابه ٔ دریائی است یا آن باخه ای است که از آن دست برنجن و شانه ها سازند. و عامه عاج را دندان فیل گویند. (منتهی الارب ). لیث گوید: تنها دندان فیل را عاج گویند. (اقرب الموارد). عاج از جمله متاعهای عمده ٔ تجارت صور. وتخت سلیمان از عاج بود و در بناء خانه ها و اسباب و اثاث البیت مستعمل بود. و بعضی را گمان چنان است که مقصود از قصرهای عاج که در کتاب مزامیر مسطور است ظرفی چوبی است که به هیئت قصر از عاج تشکیل یافته یا با عاج مرصع گشته بود که از برای محافظت عطریات میساختند. و دور نیست که مقصود از قصری باشد که بیشتر اسبابهایش از عاج باشد. (قاموس کتاب مقدس ) <span class=\"hlight\">:</span> <br />بامدادان که صبح زرین عاج <br />کرسی از زر نهاد و تخت از عاج .<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">تخت عاج </span> ؛ تختی که در آن عاج بکار رفته باشد <span class=\"hlight\">:</span> <br />ببوسیدم این پایه ٔ تخت عاج <br />دلم گشت روشن بدین فر و تاج .<br /> <font color=\"Red\">فردوسی .</font><br />چو کاوس را دید بر تخت عاج <br />ز یاقوت رخشنده بر سرش تاج .<br /> <font color=\"Red\">فردوسی .</font><br />یکی تخت عاج و یکی تخت چغ<br />یکی جای شاه و یکی جای مغ.<br /><font color=\"Red\">اسدی .</font><br /></font></div>'),
(179255, 'عاج', '<span class=\"hlight\">عاج .</span> (ع ص ) ناقه ٔ نرم و رام . (منتهی الارب ).<br /></font></div>'),
(179256, 'عاج عاج', '<span class=\"hlight\">عاج عاج .</span> <font color=\"DarkGreen\"><b>[ ج ِ ج ِ ]</font></b> (ع اِ صوت مرکب ) کلمه ای که بدان شتر ماده را زجر کنند. (منتهی الارب ).<br /></font></div>'),
(179257, 'عاجز', '<span class=\"hlight\">عاجز.</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (ع ص ) سست و ناتوان . ج، عواجز و عجزة. (منتهی الارب ) (آنندراج ) (اقرب الموارد). درمانده . ج، عاجزون . (مهذب الاسماء) <span class=\"hlight\">:</span> <br />روستائی زمین چو کردشیار<br />گشت عاجز که بود بس ناهار.<br /> <font color=\"Red\">دقیقی .</font><br />و قویترین سببی در کارهای دنیا مشارکت مشتی دون عاجز است . (کلیله و دمنه ). مردم دو گروه اند: حازم و عاجز. (کلیله و دمنه ).<br />عاجز باشدکه دست قوت یابد<br />برخیزد و دست عاجزان برتابد.<br /> <font color=\"Red\">سعدی (گلستان ).</font><br /><BR><font color=\"Blue\">◄</font> کوتاه . (مهذب الاسماء) (اقرب الموارد).<br /></font></div>'),
(179258, 'عاجز آمدن', '<span class=\"hlight\">عاجز آمدن .</span> <font color=\"DarkGreen\"><b>[ ج ِ م َ دَ ]</font></b> (مص مرکب ) ناتوان ماندن . قادر نبودن . توانا نبودن <span class=\"hlight\">:</span> چنان نبشتی که از آن نیکوتر نبودی چنانکه دبیران استاد در انشاء آن عاجز آمدندی . (تاریخ بیهقی ).<br />آن را که مصطفی چو همه عاجز آمدند<br />در حرب روز بدر بدو داد رایتش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />رشته تایکتاست آن را زور زالی بگسلد<br />چون دو تا شد عاجز آید از گسستن زال زر.<br /> <font color=\"Red\">سنائی .</font><br />دعوی طبابت کردند و از معالجه ها عاجز آمدند. (مجالس سعدی ص <span class=\"hlight\" dir=\"rtl\">١٤</span>). جمالی که زبان فصاحت از بیان صباحت عاجزآمدی . (گلستان ). رجوع به عاجز شود.<br /></font></div>'),
(179259, 'عاجز سرابی', '<span class=\"hlight\">عاجز سرابی .</span> <font color=\"DarkGreen\"><b>[ ج ِ زِ س َ ]</font></b> (اِخ ) شاعری است و دیوان او به چاپ رسیده است . رجوع به دانشمندان آذربایجان و نگارستان و الذریعه ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦٢</span> شود.<br /></font></div>'),
(179260, 'عاجز شدن', '<span class=\"hlight\">عاجز شدن .</span> <font color=\"DarkGreen\"><b>[ ج ِ ش ُ دَ ]</font></b> (مص مرکب ) درماندن . فروماندن <span class=\"hlight\">:</span> <br />بفعل نکو جمله عاجز شدند<br />فرومایه دیوان ز پر مایه جم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />نبینی که چون گربه عاجز شود<br />برآرد به چنگال چشم پلنگ .<br /> <font color=\"Red\">سعدی .</font><br />مرو زیر بار گنه ای پسر<br />که حمال عاجز شود در سفر.<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />چنان در حصارش کشیدند تنگ <br />که عاجز شد از تیرباران و سنگ .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />و رجوع به عاجز شود.<br /></font></div>'),
(179261, 'عاجز ماندن', '<span class=\"hlight\">عاجز ماندن .</span> <font color=\"DarkGreen\"><b>[ ج ِ دَ ]</font></b> (مص مرکب ) ناتوان شدن . درماندن <span class=\"hlight\">:</span> <br />قامتی داری که سحری میکند<br />کاندران عاجز بماند سامری .<br /> <font color=\"Red\">سعدی .</font><br />جهان آن تو و تو مانده عاجز<br />ز تو محروم تر کس دیده هرگز.<br /><font color=\"Red\">شبستری .</font><br /></font></div>'),
(179262, 'عاجز مرندی', '<span class=\"hlight\">عاجز مرندی .</span> <font color=\"DarkGreen\"><b>[ ج ِ زِ م َ رَ ]</font></b> (اِخ ) شاعری آذربایجانی است ونام او حاج میرزا یوسف است . تربیت او را در دانشمندان آذربایجان معرفی کرده است . (الذریعه ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦٢</span>).<br /></font></div>'),
(179263, 'عاجز کردن', '<span class=\"hlight\">عاجز کردن .</span> <font color=\"DarkGreen\"><b>[ ج ِ ک َ دَ ]</font></b>(مص مرکب ) درمانده کردن . ناتوان ساختن <span class=\"hlight\">:</span> <br />کمالت عاجزم کرد و عجب نیست <br />که تو هم عاجزی اندر کمالت .<br /> <font color=\"Red\">خاقانی .</font><br />موران به اتفاق شیر را عاجز کنند. (مجالس سعدی ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>).<br /></font></div>'),
(179264, 'عاجزانه', '<span class=\"hlight\">عاجزانه .</span> <font color=\"DarkGreen\"><b>[ ج ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص نسبی، ق مرکب ) بحالت عجز. بحالت ناتوانی . مانند عاجز <span class=\"hlight\">:</span> گفت کلمتی عاجزانه بگویم باشد که آب حلم شاه آتش غضب او را سکون دهد. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">١٥٨</span>). و رجوع به عاجز شود.<br /></font></div>'),
(179265, 'عاجزنواز', '<span class=\"hlight\">عاجزنواز.</span> <font color=\"DarkGreen\"><b>[ ج ِ ن َ ]</font></b> (نف مرکب ) نوازنده ٔ عاجز. تیمارخوار ناتوان . که ناتوانان را نوازد و دستگیری کند <span class=\"hlight\">:</span> <br />زمین بوس شه تازه تر کرد باز<br />چنین گفت کای شاه عاجزنواز.<br /> <font color=\"Red\">نظامی .</font><br />تواند که بانوی عاجزنواز<br />گشاید بما بر در گنج باز.<br /> <font color=\"Red\">نظامی .</font><br />و رجوع به عاجز شود.<br /></font></div>'),
(179266, 'عاجزنوازی', '<span class=\"hlight\">عاجزنوازی .</span> <font color=\"DarkGreen\"><b>[ ج ِ ن َ ]</font></b> (حامص مرکب ) عمل عاجزنواز <span class=\"hlight\">:</span> <br />زمانه چو عاجزنوازی کند<br />به تند اژدها مور بازی کند.<br /> <font color=\"Red\">نظامی .</font><br />و رجوع به عاجز و عاجزنواز شود.<br /></font></div>'),
(179267, 'عاجزوار', '<span class=\"hlight\">عاجزوار.</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (ق مرکب ) بمانند عاجز. ناتوان وار. ناتوان <span class=\"hlight\">:</span> <br />چو عاجزوار باید عاقبت مرد<br />چه افلاطون یونانی چه آن کرد.<br /> <font color=\"Red\">نظامی .</font><br />و رجوع به عاجز شود.<br /></font></div>'),
(179268, 'عاجزی', '<span class=\"hlight\">عاجزی .</span> <font color=\"DarkGreen\"><b>[ ج ِ]</font></b> (حامص ) عمل عاجز. ناتوانی . درماندگی <span class=\"hlight\">:</span> <br />نهنگی که او پیل را پی کند<br />ز آهوبره عاجزی کی کند.<br /> <font color=\"Red\">نظامی .</font><br />و رجوع به عاجز شود.<br /></font></div>'),
(179269, 'عاجف', '<span class=\"hlight\">عاجف .</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (اِخ ) موضعی است در شق بنی تمیم . (از معجم البلدان ) (منتهی الارب ).<br /></font></div>'),
(179270, 'عاجل', '<span class=\"hlight\">عاجل .</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (ع ص ) مقابل آجل و منه لاتبع العاجل بالاَّجل . (اقرب الموارد). دنیا. (غیاث اللغات ). این جهان . (منتهی الارب ) <span class=\"hlight\">:</span> <br />نعمت عاجل و آجل بتوداد از ملکان <br />زآنکه ضایع نشود آنچه بجای تو کند.<br /> <font color=\"Red\">منوچهری .</font><br />این مرادعاجلش حاصل کند بی اجتهاد<br />وآن هوای آجلش حاصل کند بی انتظار.<br /> <font color=\"Red\">منوچهری .</font><br />زیرا که نادان جز به عذاب عاجل از معاصی باز نیاید. (کلیله و دمنه ). راحت عاجل را به تشویش محنت آجل منغص کردن خلاف رای خردمند است . (گلستان ). <BR><font color=\"Blue\">◄</font> شتاب کننده و آنچه به شتاب باشد. (غیاث اللغات ). بی مهلت . (غیاث اللغات ) (منتهی الارب ). سریع. (منتهی الارب ) <span class=\"hlight\">:</span> <br />زهر نزدیک خردمندان اگرچه قاتل است <br />چون ز دست دوست میگیری شفای عاجل است .<br /> <font color=\"Red\">سعدی (کلیات چ فروغی ص <span class=\"hlight\" dir=\"rtl\">٤٣٩</span>).</font><br /><BR><font color=\"Blue\">◄</font> شتاب .(منتهی الارب ).<br /></font></div>'),
(179271, 'عاجل الحال', '<span class=\"hlight\">عاجل الحال .</span> <font color=\"DarkGreen\"><b>[ ج ِ لُل ْ ]</font></b> (ع اِ مرکب ) فوراً. درساعت . بدون درنگ <span class=\"hlight\">:</span> یک چیز مانده است که اگر آن کرده آید بعاجل الحال این کار را لختی تسکین توان کرد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٢٩</span>). ولی در عاجل الحال آب این مرد بوبکر حصیری ریخته شد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٥٦</span>).<br /></font></div>'),
(179272, 'عاجلة', '<span class=\"hlight\">عاجلة.</span> <font color=\"DarkGreen\"><b>[ ج ِ ل َ ]</font></b> (ع ص ) مؤنث عاجل . رجوع به عاجل شود.<br /></font></div>'),
(179273, 'عاجم', '<span class=\"hlight\">عاجم .</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (ع ص، اِ) واحد عواجم که بمعنی دندانهاست . (از منتهی الارب ). در اقرب الموارد مفرد عواجم، عاجمة آمده است .<br /></font></div>'),
(179274, 'عاجن', '<span class=\"hlight\">عاجن .</span> <font color=\"DarkGreen\"><b>[ ج ِ ]</font></b> (ع ص ) ناقه ای که بچه در شکمش قرار نگیرد. <BR><font color=\"Blue\">◄</font> پیری که از ضعف تکیه بر زمین کرده برخیزد. (منتهی الارب ) (اقرب الموارد) (آنندراج ).<br /></font></div>'),
(179275, 'عاجنة', '<span class=\"hlight\">عاجنة.</span> <font color=\"DarkGreen\"><b>[ ج ِ ن َ ]</font></b> (ع اِ) عاجنة المکان ؛ میانه ٔ جای . (منتهی الارب ). وسط مکان .<br /></font></div>'),
(179276, 'عاجی', '<span class=\"hlight\">عاجی .</span> (ص نسبی ) چیزی که از عاج ساخته شده باشد. (آنندراج ). چیزها که از عاج سازند. رجوع به عاج شود.<br /></font></div>'),
(179277, 'عاد', '<span class=\"hlight\">عاد.</span> (ع اِ) مردم . یقال : ماأدری أی عاد هو؛ أی أی ّ الناس ؛ یعنی ندانم که چه مردست او. (منتهی الارب ) (مهذب الاسماء).<br /></font></div>'),
(179278, 'عاد', '<span class=\"hlight\">عاد.</span> (اِخ ) قومی که هود (ع ) به رسالت ایشان آمد و ایشان از نسل عادبن نوح بودند از باعث نافرمانی حق بطوفان باد هلاک شدند. (از آنندراج ) (غیاث اللغات ). و اولین قبیله ٔ عرب بائده را عاد گفته اند و آنان فرزندان عادبن عوص بن ارم بن سام بن نوح (ع ) بودند و محل مأوای آنان به أحقاف (بین یمن و عمان ) از بحرین تا حضر موت بوده است . (صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٣</span>) (عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٣</span>) (مجمل التواریخ صص <span class=\"hlight\" dir=\"rtl\">١٤٦</span> - <span class=\"hlight\" dir=\"rtl\">١٤٨</span>) (عیون الاخبار ص <span class=\"hlight\" dir=\"rtl\">١١٤</span>) (مهذب الاسماء) (منتهی الارب ) <span class=\"hlight\">:</span> <br />چو عادند و ترکان چو باد عقیم <br />بدین بادگشتند ریگ هبیر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />لشکر عادند و کلک من چو صرصر از صریر<br />نسل مأجوجند و نطق من چو صور اندر صدا.<br /> <font color=\"Red\">خاقانی .</font><br />گرنبودی واقف از حق جان باد<br />فرق چون کردی میان قوم عاد.<br /> <font color=\"Red\">مولوی .</font><br />قصه ٔ عاد و ثمود از بهر چیست <br />تا بدانی کانبیا را نازکیست .<br /> <font color=\"Red\">مولوی .</font><br />نیکبختان بخورند و غم دنیا نخورند<br />که نه بر عوج عنق ماند و نه بر عاد و ثمود.<br /> <font color=\"Red\">سعدی .</font><br />و رجوع به عادبن عوص شود.<br /></font></div>'),
(179279, 'عاد', '<span class=\"hlight\">عاد.</span> <font color=\"DarkGreen\"><b>[ عادد ]</font></b> (ع ص، اِ) عددی که عدد دگر را تجزیه کننده باشد. مانند سه که عاد نه است، و چهار که عاد دوازده است و پنج که عاد پانزده است . (نفائس الفنون ).<br /></font></div>'),
(179280, 'عاد', '<span class=\"hlight\">عاد.</span> (اِخ ) ابن عوص بن ارم بن سام بن نوح . جدی جاهلی است .گویند وی در بابل بود سپس با عائله ٔ خود به یمن رفت و در احقاف بین یمن و عمان از بحرین تا حضرموت اقامت کرد. او و فرزندان او در آن سرزمین تمدنی بوجود آوردند. از آثار آنان اطلال «جش » و بناهای سنگی است که ویرانه های آن در حضرموت موجود است . (الاعلام زرکلی ).<br /></font></div>'),
(179281, 'عادات', '<span class=\"hlight\">عادات .</span> (ع اِ) ج ِ عادة. رجوع به عادت و عادة شود <span class=\"hlight\">:</span> <br />در این دخمه خفته ست شداد و عاد<br />کزو رنگ و رونق گرفت این سواد.<br /> <font color=\"Red\">نظامی .</font><br />برانداختم دخمه ٔ عاد را<br />گشادم در قصر شداد را.<br /> <font color=\"Red\">نظامی .</font><br />و رجوع به عاد شود.<br /></font></div>'),
(179282, 'عادانیون', '<span class=\"hlight\">عادانیون .</span> (معرب، اِ)به یونانی نباتی است که خار آن شبیه به سوزن است .<br /></font></div>'),
(179283, 'عادت', '<span class=\"hlight\">عادت .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (ع اِ) عادة. فارسیان به معنی رسم و آئین نیز استعمال کنند و با لفظ گردانیدن، نهادن، برداشتن، کردن، دادن و گرفتن مستعمل نمایند. (آنندراج ) <span class=\"hlight\">:</span> <br />عادت و رسم این گروه ظلوم <br />نیک ماند چه بنگری به ظلیم .<br /> <font color=\"Red\">ابوحنیفه ٔ اسکافی (از تاریخ بیهقی ).</font><br />اما ایزد عز ذکره بفضل خود مارا بر عادت خود بداشت . (تاریخ بیهقی ). غلامان و ستوران افزون از عادت رسم خریدن گرفتند. (تاریخ بیهقی ). بخدمت پادشاه نبوده است و عادت و خوی و اخلاق ایشان پیش چشم نمیدارد. (تاریخ بیهقی ).<br />همی تا کند پیشه عادت همی کن <br />جهان مر جفا را تو مر صابری را.<br /> <font color=\"Red\">ناصرخسرو.</font><br />نه او برعادت و اخلاق ایشان وقوف دارد. (کلیله و دمنه ). و تجارب متقدمان را نمودار عادت خویش گردان . (کلیله و دمنه ).<br />عادت بود که هدیه ٔ نوروز آورند<br />آزداگان بخدمت بانوی شهریار.<br /><font color=\"Red\">خاقانی .</font><br />مگر آنکه سخن گفته شود به عادت مألوف .<br />(گلستان ).<br />هر زمینی سعادتی دارد<br />هر دهی رسم و عادتی دارد.<br /> <font color=\"Red\">اوحدی .</font><br /> <BR><font color=\"Blue\">◄</font> حیض . عادت زنان <span class=\"hlight\">:</span> <br />صاحب حالت شدن حله بتن سوختن <br />خارج عادت شدن عده ٔ غم داشتن .<br /> <font color=\"Red\">خاقانی .</font><br /><BR><font color=\"Blue\">◄</font> (اصطلاح روانشناسی ) استعداد اکتسابی صدور حرکات یا تحمل تأثیراتی معین . (علم النفس سیاسی ص <span class=\"hlight\" dir=\"rtl\">٤٢٨</span>).<br /></font></div>'),
(179284, 'عادت داشتن', '<span class=\"hlight\">عادت داشتن .</span> <font color=\"DarkGreen\"><b>[ دَ ت َ ]</font></b> (مص مرکب ) خو گرفتن به چیزی <span class=\"hlight\">:</span> چنان دانم که بسیار خوردن عادت داری . (گلستان ).<br /></font></div>'),
(179285, 'عادت پذیر', '<span class=\"hlight\">عادت پذیر.</span> <font color=\"DarkGreen\"><b>[ دَ پ َ ]</font></b> (نف مرکب ) خوی پذیرنده . آنکه از کسی یا چیزی عادت پذیرد. آنکه خوی دیگری را قبول کند <span class=\"hlight\">:</span> <br />کجا چون طبع مردم خوی گیر است <br />ز هر کس آدمی عادت پذیر است .<br /><font color=\"Red\">عطار.</font><br /></font></div>'),
(179286, 'عادت کردن', '<span class=\"hlight\">عادت کردن .</span> <font color=\"DarkGreen\"><b>[ دَ ک َ دَ ]</font></b> (مص مرکب ) خوی گرفتن . معتاد شدن <span class=\"hlight\">:</span> <br />چشم عادت کرده با دیدار دوست <br />حیف باشد بعد از او بر دیگری .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(179287, 'عادت گرفتن', '<span class=\"hlight\">عادت گرفتن .</span> <font color=\"DarkGreen\"><b>[ دَ گ ِ رِ ت َ ]</font></b> (مص مرکب ) خوی پذیرفتن . خوی کردن . معتاد شدن <span class=\"hlight\">:</span> <br />گر عقابی بگیر عادت جغد<br />ور پلنگی بگیر خوی گراز.<br /></font></div>'),
(179288, 'عادر', '<span class=\"hlight\">عادر.</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b>(ع ص ) نیک دروغگوی . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(179289, 'عادق', '<span class=\"hlight\">عادق .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (ع ص ) رجل عادق الرأی ؛ کسی که تدبیر صائب ندارد. (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br /></font></div>'),
(179290, 'عادل', '<span class=\"hlight\">عادل .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) نامی از نامهای خدا.<br /></font></div>'),
(179291, 'عادل', '<span class=\"hlight\">عادل .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (ع ص ) داددهنده . ج، عدول . (منتهی الارب ) (آنندراج ). مقابل فاسق . <BR><font color=\"Blue\">◄</font> مشرک که غیر حق تعالی را به حق برابر و شریک سازد. (مهذب الاسماء). و منه قول امراءة للحجاج انک لقاسط عادل ؛ أی مشرک . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> راست . درست . مستقیم ؛ میزان عادل یعنی ترازوئی راست، مقابل میزان مایل . (مهذب الاسماء).<br /></font></div>'),
(179292, 'عادل', '<span class=\"hlight\">عادل .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) لقب انوشروان است <span class=\"hlight\">:</span> <br />همی نازد بعهد میر مسعود<br />چو پیغمبربه نوشروان عادل .<br /> <font color=\"Red\">منوچهری .</font><br />به آنچه ملک عادل انوشروان کسری بن قباد سعادت ذات ... (کلیله و دمنه ).<br /></font></div>'),
(179293, 'عادل', '<span class=\"hlight\">عادل .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) ابن علی بن عادل حافظ معلم . از شعرای سده ٔ دهم . کتاب «ترجمان » علامه ٔ جرجانی را به ترتیب حروف هجا مرتب کرده است . رجوع شود به الذریعه ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦٣</span>.<br /></font></div>'),
(179294, 'عادل آباد', '<span class=\"hlight\">عادل آباد.</span><font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ بخش مرکزی شهرستان شیراز. واقع در چهارهزارگزی جنوب باختری شیراز. این ده در جلگه واقع شده و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> تن سکنه دارد، آب آن از قنات تأمین میشود و محصول آن غلات، چغندر، کنجد و صیفی است . شغل اهالی زراعت وراه آن فرعی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(179295, 'عادل آباد', '<span class=\"hlight\">عادل آباد.</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) دهی است از دهستان کامفیروز بخش اردکان شهرستان شیراز. این ده در <span class=\"hlight\" dir=\"rtl\">٦٢</span> هزارگزی خاور اردکان کنار راه فرعی پل خان به خانی من واقع و منطقه ای است جلگه با هوای معتدل و مالاریائی و سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٩٦</span> تن است . آب آن از رودخانه ٔ کر تأمین میشود. محصولش غلات و برنج است و اهالی آن به کشاورزی اشتغال دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(179296, 'عادل آباد', '<span class=\"hlight\">عادل آباد.</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) دهی است از دهستان حسنوند بخش سلسله ٔشهرستان خرم آباد. در <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی شمال باختری الشتر و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی شمال باختر شوسه ٔ خرم آباد به الشتر واقع، جلگه و سردسیر و مالاریایی است و <span class=\"hlight\" dir=\"rtl\">١١٠</span> تن سکنه دارد. آب آن از رود امیری تأمین میشود. محصولاتش غلات، برنج، حبوبات، لبنیات و پشم است اهالی آن به کشاورزی و گله داری مشغولند. راه آن مالرو است و مردم آن از طایفه ٔحسنوند میباشند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(179297, 'عادل اول', '<span class=\"hlight\">عادل اول .</span> <font color=\"DarkGreen\"><b>[ دِ ل ِ اَوْ وَ ]</font></b> (اِخ ) لقب سیف الدین ابوبکر ایوبی برادر سلطان صلاح الدین است . رجوع به سیف الدین ابوبکر شود.<br /></font></div>'),
(179298, 'عادل صفوی', '<span class=\"hlight\">عادل صفوی .</span> <font color=\"DarkGreen\"><b>[ دِ ل ِ ص َ ف َ ]</font></b> (اِخ ) تخلص شاه طهماسب صفوی است . رجوع به طمهاسب شاه اول در این لغت نامه و الذریعه ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦٣</span> شود.<br /></font></div>'),
(179299, 'عادلة', '<span class=\"hlight\">عادلة.</span> <font color=\"DarkGreen\"><b>[ دِ ل َ ]</font></b> (ع ص ) مؤنث عادل . رجوع به عادل شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">حکومت عادلة</span> ؛ حکومتی که اساس آن بر عدالت بود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">فریضة عادلة</span> ؛ یعنی عدل در قسمت . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">قیمت عادلة در تداول </span> ؛ قیمت متعارف به نرخ معمول بازار.<br /></font></div>'),
(179300, 'عادلی', '<span class=\"hlight\">عادلی .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) تخلص شاه اسماعیل دوم است . رجوع به اسماعیل صفوی و الذریعه ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦٣</span> شود.<br /></font></div>'),
(179301, 'عادن', '<span class=\"hlight\">عادن .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (ع ص ) ناقه ٔ بر یک جای باشنده از علف . <BR><font color=\"Blue\">◄</font> پیوسته شورگیاه چرنده . (منتهی الارب ).<br /></font></div>'),
(179302, 'عادکار', '<span class=\"hlight\">عادکار.</span> (اِخ ) تیره ای از طایفه ٔ محمود صالح ایل چهار لنگ بختیاری . (جغرافیای سیاسی کیهان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٥</span>).<br /></font></div>'),
(179303, 'عادگان', '<span class=\"hlight\">عادگان .</span> (اِخ ) دهی است از دهستان چادگان بخش داران شهرستان فریدن . واقع در <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی جنوب داران و متصل به راه کوهرنگ، منطقه ای است جلگه و سردسیر. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٩٥٧</span> تن است . آب آن از چشمه و محصولاتش غلات و حبوبات و سیب زمینی، شغل اهالی زراعت و گله داری و صنایع زنان قالی و جاجیم بافی و راه آن شوسه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(179304, 'عادی', '<span class=\"hlight\">عادی .</span> (ع ص ) دیرینه . (منتهی الارب ) (مهذب الاسماء) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) شیر بیشه . <BR><font color=\"Blue\">◄</font> عادیا اللوح ؛ هر دو طرف کرانه ٔ آن . <BR><font color=\"Blue\">◄</font> دزد. <BR><font color=\"Blue\">◄</font> (ص ) ستمکار. <BR><font color=\"Blue\">◄</font> دشمن . (منتهی الارب ).<br /></font></div>'),
(179305, 'عادی', '<span class=\"hlight\">عادی .</span> <font color=\"DarkGreen\"><b>[ دی ی ]</font></b> (ع ص نسبی ) نسبت است به عادت . هر چیزی که عادت شود. بحالت الحاق یاء نسبت تاء مصدر از آن افتاده است . (از غیاث اللغات ).<br /></font></div>'),
(179306, 'عادی', '<span class=\"hlight\">عادی .</span> (ص نسبی ) نسبت است به عاد. رجوع به عاد و عادبن عوص شود.<br /></font></div>'),
(179307, 'عادیات', '<span class=\"hlight\">عادیات .</span> (اِخ ) سوره ٔ صدمین از قرآن است و آن یازده آیه ٔ است پس از سوره ٔ زلزله و پیش از قارعه .<br /></font></div>'),
(179308, 'عادیان', '<span class=\"hlight\">عادیان .</span> (اِخ ) کسانی که منسوب به قوم عاد بودند. (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> و قصه ٔ جالوت چنان بود که وی مردی بود از فرزندان عمالقه و از جمله ٔ عادیان . (قصص الانبیاء ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span>). رجوع به عاد شود.<br /></font></div>'),
(179309, 'عادیة', '<span class=\"hlight\">عادیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) شتران سخت دونده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شتران ماننده (مانده ؟) در طاقستان که به شور گیاه میل نکنند. <BR><font color=\"Blue\">◄</font> کاری که باز دارد ترا از چیزی . <BR><font color=\"Blue\">◄</font> گروهی از قوم که جهت کارزار بدوند یا آنکه پیشتر حمله کنند از پیادگان . (منتهی الارب ).<br /></font></div>'),
(179310, 'عاذ', '<span class=\"hlight\">عاذ.</span> <font color=\"DarkGreen\"><b>[ ذِن ْ ]</font></b> (ع ص ) مکان عاذ؛ یعنی مکانی که دور از آب است . (منتهی الارب ).<br /></font></div>'),
(179311, 'عاذب', '<span class=\"hlight\">عاذب .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع ص ) آنکه میان او و آسمان چیزی حائل نباشد. <BR><font color=\"Blue\">◄</font> بازمانده از خوردن از شدت تشنگی . <BR><font color=\"Blue\">◄</font> ستور ایستاده که آب و علف نخورد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179312, 'عاذر', '<span class=\"hlight\">عاذر.</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع ص ) مرد عذرخواه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) رگ خون استحاضه . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نشان خستگی و پلیدی . (منتهی الارب ) (مهذب الاسماء).<br /></font></div>'),
(179313, 'عاذر', '<span class=\"hlight\">عاذر.</span> <font color=\"DarkGreen\"><b>[ ذَ ]</font></b> (اِخ ) نام مردی که بی ایمان مرده بود، عیسی (ع ) بعد از چهل سال او را زنده کرده مسلمان ساخته بود. (غیاث ). و رجوع به عازر شود.<br /></font></div>'),
(179314, 'عاذریة', '<span class=\"hlight\">عاذریة.</span><font color=\"DarkGreen\"><b>[ ذِ ری ْ ی َ ]</font></b> (اِخ ) گروهی از فرقه ٔ نجدات میباشند که مردم را به نادانی در فروع مذهب معذور میشناسند. (اقرب الموارد) (ملل و نحل شهرستانی چ مصر ص <span class=\"hlight\" dir=\"rtl\">١٨٧</span>).<br /></font></div>'),
(179315, 'عاذف', '<span class=\"hlight\">عاذف .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع ص ) چشنده . مازلت عاذفاً منذ الیوم ؛ یعنی نچشیدم چیزی را. (منتهی الارب ).<br /></font></div>'),
(179316, 'عاذل', '<span class=\"hlight\">عاذل .</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ع ص )ملامت کننده . ج، عَذَله، عُذّال، عاذِلات، عَواذل . (منتهی الارب ) (مهذب الاسماء) (غیاث اللغات ) <span class=\"hlight\">:</span> <br />مرا گفت ای ستمکاره بجانم <br />به کام حاسدم کردی و عاذل .<br /> <font color=\"Red\">منوچهری .</font><br /><BR><font color=\"Blue\">◄</font> (اِ) رگ خون استحاضه که از آن خون سیلان پیدا میکند. (منتهی الارب ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> نام ماه شعبان یا شوال در جاهلیت . (منتهی الارب ) (آنندراج ) (مهذب الاسماء) (السامی فی الاسامی ).<br /></font></div>'),
(179317, 'عاذور', '<span class=\"hlight\">عاذور.</span> (ع اِ) بدی و فساد. و منه : لقیت منه عاذوراً؛ أی شراً. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خطی است در شتر و اسب . (منتهی الارب ). نشان . (اقرب الموارد).<br /></font></div>'),
(179318, 'عار', '<span class=\"hlight\">عار.</span> (ع اِ) عیب و ننگ . (منتهی الارب ) (مهذب الاسماء) (غیاث اللغات ) <span class=\"hlight\">:</span> تا قیامت آن عار از خاندان ما دور نشود. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٢٩</span>). <BR><font color=\"Blue\">◄</font> فضیحت و هر چه در آن عیب لازم باشد. (منتهی الارب ) <span class=\"hlight\">:</span> <br />شعر تو شعر است لیکن باطنش پر عیب و عار<br />کرم بسیاری بود در باطن دُرِّ ثمین .<br /> <font color=\"Red\">منوچهری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عار آمدن </span> ؛ ننگ داشتن <span class=\"hlight\">:</span> <br />پیاده نگردد که عار آیدش <br />ز شاهی تن خویش خوار آیدش .<br /> <font color=\"Red\">فردوسی .</font><br />ز جهل خویش چون عارت نیاید<br />چرا داری همی زآموختن عار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />بجز غلامی دلدار خویش سعدی را<br />ز کار و بار جهان گر شهی است عار آید.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عار بودن </span> ؛ ننگ بودن <span class=\"hlight\">:</span> <br />فخر دانا بدین بود وینها<br />عیب دینند و علم را عارند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />با این همه از عالم عار است مراواﷲ<br />یاران مرا فخر است این عار که من دارم .<br /> <font color=\"Red\">خاقانی .</font><br />مرا نیست زآهنگری ننگ و عار<br />خرد باید و مردی ای بادسار.<br /> <font color=\"Red\">سعدی .</font><br />وگر بی تکلف زید مالدار<br />که زینت بر اهل تمیز است عار.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عار داشتن </span> ؛ ننگ داشتن <span class=\"hlight\">:</span> <br />ابر و دریا سخی بوند به طبع<br />دستش از هر دو ننگ دارد و عار.<br /> <font color=\"Red\">فرخی .</font><br />عدلش از آسمان ندارد عار<br />سلسله زآسمان درآویزد.<br /> <font color=\"Red\">خاقانی .</font><br />ساقی بیار جامی کز زهد توبه کردم <br />مطرب بزن نوائی کز توبه عار دارم .<br /> <font color=\"Red\">سعدی .</font><br />متابع توام ای دوست گر نداری ننگ <br />مطاوع توام ای یار گر نداری عار.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(179319, 'عارب', '<span class=\"hlight\">عارب .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b>(ع ص ) نهر بسیارآب . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(179320, 'عاربة', '<span class=\"hlight\">عاربة.</span><font color=\"DarkGreen\"><b>[ رِ ب َ ]</font></b> (ع ص ) عرب خالص را گویند. عرب عاربة، مقابل عرب مستعربه است . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(179321, 'عارج', '<span class=\"hlight\">عارج .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص ) بالا برآینده . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> پوشیده و غایب . (منتهی الارب ).<br /></font></div>'),
(179322, 'عارد', '<span class=\"hlight\">عارد.</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص ) برآینده . <BR><font color=\"Blue\">◄</font> کنار و یکسو شونده . (منتهی الارب ).<br /></font></div>'),
(179323, 'عارض', '<span class=\"hlight\">عارض .</span><font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص ) عرض دهنده ٔ لشکر. شمارکننده ٔ لشکر. بخشی فوج یا سالار فوج . (غیاث اللغات ) (از منتهی الارب ) (آنندراج ) (ناظم الاطباء). آنکه سان سپاه دهد. آنکه سان سپان بیند. (مهذب الاسماء) <span class=\"hlight\">:</span> و عارض را فرمان داد تا نامهاشان به دیوان عرض بنوشت . (تاریخ سیستان ). وزیر و عارض و صاحبدیوان و ندما حاضر آمدند. (تاریخ بیهقی ). این مرد مدتی دراز کدخدا و عارض امیر نصر سپهسالار بود. (تاریخ بیهقی ). و عارض بیامد و چهارهزار سوار با وی نامزد کرد. (تاریخ بیهقی ). همه لشکر را گرد آوردند، وی عارض را فرمود که شمار کنند هزارهزار و پانصدهزار سوار جنگی بودند. (اسکندرنامه ).<br />خبرداد عارض که سیصد هزار<br />برآمد دلیران مفرد سوار.<br /> <font color=\"Red\">نظامی .</font><br />شده برعارض لشکر جهان تنگ <br />که شاهنشه کجا میدارد آهنگ .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِ) باران <span class=\"hlight\">:</span> <br />تا هلاک قوم نوح و قوم هود<br />عارض رحمت بجان ما نمود.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> (ص ) شتر ماده ٔ بیمار یا شکسته ٔ آفت رسیده . <BR><font color=\"Blue\">◄</font> (اِ) دندان . دندان که درعرض دهن است و آن بعد از ثنایا است . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ابر که سایه افکند. (مهذب الاسماء) (ترجمان عادل بن علی ). ابر پراکنده در افق . (غیاث اللغات ). ابربر پهنای کرانه ٔ آسمان . (منتهی الارب ). ابر. (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> کوه . عارض الیمامه ؛ کوه یمامه را گویند. <BR><font color=\"Blue\">◄</font> هرچه پیش آید ترا از پرده و جز آن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> صفحه ٔ گردن . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> هر دو طرف روی . <BR><font color=\"Blue\">◄</font> هر دو جانب دهن . <BR><font color=\"Blue\">◄</font> ملخ بسیار. <BR><font color=\"Blue\">◄</font> عطا. <BR><font color=\"Blue\">◄</font> در تداول، شاکی و متظلم . دادخواه . <BR><font color=\"Blue\">◄</font> صفحه ٔ رخسار مردم .(منتهی الارب ). روی . رخسار. گونه <span class=\"hlight\">:</span> <br />غره مشو به عارض عنبرنبات خویش <br />واندر نگر به عارض کافوربار من .<br /> <font color=\"Red\">ناصرخسرو (دیوان چ مینوی ص <span class=\"hlight\" dir=\"rtl\">٢٩٨</span>).</font><br />آن زلف سر افکنده بدان عارض خرم <br />از بهر چه آراست بدان بوی و بدان خم .<br /> <font color=\"Red\">عنصری .</font><br />ای عارض چو ماه تو را چاکر آفتاب <br />یک بنده ٔ تو ماه سزد دیگر آفتاب .<br /> <font color=\"Red\">خاقانی .</font><br />چو مویش دیده بان بر عارض افکند<br />جوانی را ز دیده موی برکند.<br /> <font color=\"Red\">نظامی .</font><br />آنکه نبات عارضش آب حیات میخورد.<br /> <font color=\"Red\">(گلستان ).</font><br />گه عارض سیمین یکی را طپانچه زدی . (گلستان ).<br />گل سرخش چو عارض خوبان .<br /> <font color=\"Red\">(گلستان ).</font><br />عارض نتوان گفت که قرص قمر است این <br />بالا نتوان گفت که سرو چمن است این .<br /> <font color=\"Red\">سعدی .</font><br /><BR><font color=\"Blue\">◄</font> (اصطلاح فلسفه ) محمول خارج از ذات چیزی را عارض برآن گویند و آن اعم از عرض است زیرا شامل صورت هم میشود و صورت جوهر است زیرا عارض بر هیولی میشود. عارض وجود؛ آنچه در ظرف وجود عارض شود که وجود معروض را مدخلیت در عروض عارض باشد.عارض ماهیت ؛ آنچه منشاء عروض ذات و یا ماهیت باشد مانند عروض وجود بر ماهیت . عارض لازم ؛ آنچه ممتنعالانفکاک باشد از معروض در مقابل عارض مفارق . (تعریفات ) (شرح منظومه ص <span class=\"hlight\" dir=\"rtl\">٢٧</span>) (شرح حکمة الاشراق ص <span class=\"hlight\" dir=\"rtl\">٤٦</span>). <BR><font color=\"Blue\">◄</font> از نظر عرفا عبارت از کشف نور ایمان و فتح ابواب عرفان و رفع حجب از جمال حقیقت و عیان و هرچه در فتح و فتوح باشد. صاحب لمع گوید: عارض چیزی است که عارض شود و بر قلوب و اسرار از القاء عدو و نفس و هوا و مقابل خاطر است . (لمع ص <span class=\"hlight\" dir=\"rtl\">٣٤٣</span>).<br /></font></div>'),
(179324, 'عارض', '<span class=\"hlight\">عارض .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) نام شاعری است اصفهانی . مؤلف مجمع الفصحاء درباره ٔ وی نویسد: نامش آقابابا و شغلش پاره دوزی بود. و طبع خوشی داشته و از اشعار اوست :<br />بود بجانب من چشم و سوی غیر نگاهت <br />ندانم این گنه از تست یا ز چشم سیاهت .<br />حاشا مکن ز بردن این دل که زار تست <br />غیر از تو دل که میبرد این کار، کار تست .<br />و باز گوید:<br />گرنه برگردن پروانه کمندیست ز شمع<br />میکشد از چه سراسیمه به هر انجمنش .<br /><font color=\"Red\">(از مجمع الفصحاء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٥</span>).</font><br /></font></div>'),
(179325, 'عارض افروختن', '<span class=\"hlight\">عارض افروختن .</span> <font color=\"DarkGreen\"><b>[ رِ اَ ت َ ]</font></b> (مص مرکب ) کنایه از غضبناک شدن و خشمگین گشتن .<br /></font></div>'),
(179326, 'عارض شدن', '<span class=\"hlight\">عارض شدن .</span> <font color=\"DarkGreen\"><b>[ رِ ش ُ دَ ]</font></b> (مص مرکب ) شکایت کردن . متظلم شدن . دادخواهی کردن . قصه به قاضی برداشتن . رفع دعوی کردن به حاکم . <BR><font color=\"Blue\">◄</font> روی دادن . رخ دادن . پدید شدن .<br /></font></div>'),
(179327, 'عارض لشکر', '<span class=\"hlight\">عارض لشکر.</span> <font color=\"DarkGreen\"><b>[ رِ ض ِ ل َ ک َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آنکه سپاه را عرض دهد. رجوع به عارض شود.<br /></font></div>'),
(179328, 'عارضان', '<span class=\"hlight\">عارضان .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص، اِ) تثنیه ٔ عارض (در حالت رفعی ). رجوع به عارض شود.<br /></font></div>'),
(179329, 'عارضی', '<span class=\"hlight\">عارضی .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ص نسبی ) نسبت است به عارض، مقابل اصلی، چنانکه گویند سکون عارضی، حرکت عارضی، حوادث و آفات عارضی و آنچه لاحق شود به چیزی . (آنندراج ) (غیاث اللغات ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(179330, 'عارضی', '<span class=\"hlight\">عارضی .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (حامص ) شغل عارض داشتن . لشکرنویسی . عرض دادن لشکر.عارض بودن <span class=\"hlight\">:</span> روز دیگر شنبه بوالفتح را به جامه خانه بردند و خلعت عارضی پوشید. (تاریخ بیهقی ). و بوالقاسم کثیر معزول شد از شغل عارضی . (تاریخ بیهقی ). بوسهل حمدوی مردی کافی است وی را عارضی باید کردو ترا وزارت . (تاریخ بیهقی ). و رجوع به عارض شود.<br /></font></div>'),
(179331, 'عارضی', '<span class=\"hlight\">عارضی .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) قمی . صادقی کتابدار نویسد: شاعرپیشه است و به اردوی معلا رفت و آمد داشت طبع خوبی دارد و شعرش چنین است :<br />یک شب نشد که درغم عشقت ز چشم و دل <br />خونابها نیامد و سیلاب ها نرفت .<br /><font color=\"Red\">(مجمع الخواص ص <span class=\"hlight\" dir=\"rtl\">٣٠٩</span>).</font><br /></font></div>'),
(179332, 'عارضین', '<span class=\"hlight\">عارضین .</span> <font color=\"DarkGreen\"><b>[ رِ ض َ ]</font></b> (ع اِ) تثنیه ٔ عارض (در حالت نصبی و جری ). رجوع به عارض شود <span class=\"hlight\">:</span> <br />همه شکرلب و بادام چشم و پسته دهان <br />بنفشه زلف و سیمین عارضین و گل رخسار.<br /> <font color=\"Red\">امیرمعزی .</font><br />گر شاهد است سبزه بر اطراف گلستان <br />بر عارضین شاهد گلروی خوشتر است .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خفیف العارضین </span> ؛مردی که بر دو خد موی تنک دارد.<br /></font></div>'),
(179333, 'عارف', '<span class=\"hlight\">عارف .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص ) دانا و شناسنده . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اصطلاح عرفانی ) آنکه خدا او را بمرتبت شهود ذات و اسماء و صفات خود رسانیده باشد و این مقام بطریق حال و مکاشفه بر او ظاهر شده باشد نه بمجرد علم و معرفت حال . جنید گوید: عارف کسی است که حق از سر او گویا و خود ساکت باشد. (کشاف اصطلاحات الفنون ص <span class=\"hlight\" dir=\"rtl\">٩٩٧</span>). ابوتراب نخشبی گوید: عارف کسی است که چیزی او را مکدر نگرداند و گفته شده است که عارف کسی است که از وجود مجازی خویش محو و فانی گشته باشد. (شرح کلمات باباطاهر ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>) (لمع صص <span class=\"hlight\" dir=\"rtl\">٣٥</span> - <span class=\"hlight\" dir=\"rtl\">٣٩</span>). و گفته شده است که عارف کسی است که عبادت حق را ازآن جهت انجام میدهد که او را مستحق عبادت میداند نه از جهت امید ثواب و خوف از عقاب . (مصباح الهدایة ص <span class=\"hlight\" dir=\"rtl\">٨٥</span>). و گفته شده است که عارف کسی است که دنیا بر او تنگ باشد. (کشاف اصطلاحات الفنون ص <span class=\"hlight\" dir=\"rtl\">٩٩٧</span>) <span class=\"hlight\">:</span> <br />عارفان خامش و سر بر سر زانو چو ملخ <br />نه چو زنبور کزو شورش و غوغا شنوند.<br /> <font color=\"Red\">خاقانی .</font><br />چون نظر از بینش توفیق ساخت <br />عارف خود گشت و خدا را شناخت .<br /> <font color=\"Red\">نظامی .</font><br />صورت حال عارفان دلق است <br />اینقدر بس چو روی در خلق است .<br /> <font color=\"Red\">سعدی (گلستان ).</font><br />عابدان از گناه توبه کنند<br />عارفان از عبادت استغفار.<br /> <font color=\"Red\">سعدی (گلستان ).</font><br />تمنا کند عارف پاکباز<br />بدریوزه از خویشتن ترک آز.<br /> <font color=\"Red\">سعدی (بوستان ).</font><br /> <BR><font color=\"Blue\">◄</font> مقابل عامی <span class=\"hlight\">:</span><br />بساط سبزه لگدکوب شد بپای نشاط<br />ز بسکه عارف و عامی به رقص برجستند.<br /> <font color=\"Red\">سعدی .</font><br /><BR><font color=\"Blue\">◄</font> شکیبا. (مهذب الاسماء) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179334, 'عارف', '<span class=\"hlight\">عارف .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) (احمد...الزین ) یکی از نویسندگان و ادباء بزرگ عرب در قرن <span class=\"hlight\" dir=\"rtl\">١٤</span> هجری و صاحب مجله ٔ عرفان صیداست . او دارای تألیفاتی مانند تاریخ صیدا وتاریخ شیعه میباشد. (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٥٩</span>).<br /></font></div>'),
(179335, 'عارف آباد', '<span class=\"hlight\">عارف آباد.</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) دهی است از دهستان بالاولایت بخش حومه ٔ شهرستان کاشمر. واقع در <span class=\"hlight\" dir=\"rtl\">٦٨</span> هزارگزی جنوب خاوری کاشمر جلگه و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٩٧٤</span> تن سکنه دارد، آب آن از قنات و محصول آن غلات، باغات انگور، زیره و پنبه است . اهالی به کشاورزی گذران میکنند. راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179336, 'عارف اردبیلی', '<span class=\"hlight\">عارف اردبیلی .</span> <font color=\"DarkGreen\"><b>[ رِ ف ِ اَ دَ ]</font></b> (اِخ ) یکی از شعرای قرن هشتم و معاصر سلطان اویس جلایری بوده است . او راست : دیوانی بنام فرهادنامه . و از اشعار اوست :<br />در این گفتن چه جاری گشت خامه <br />نهادم نام آن فرهاد نامه .<br /><font color=\"Red\">(الذریعه جزء دوم ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦٥</span>).</font><br /></font></div>'),
(179337, 'عارف اندرون', '<span class=\"hlight\">عارف اندرون .</span> <font color=\"DarkGreen\"><b>[ رِ اَ دَ ]</font></b> (ص مرکب ) عارف دل . کسی که ضمیر او بنورعرفان روشن است <span class=\"hlight\">:</span> <br />خانه آبادان برون باید نه بیرون پر نگار<br />مردی عارف اندرون را گو برون ویرانه باش .<br /><font color=\"Red\">سعدی (خواتیم ).</font><br /></font></div>'),
(179338, 'عارف اندیش', '<span class=\"hlight\">عارف اندیش .</span> <font color=\"DarkGreen\"><b>[ رِ اَ ]</font></b> (نف مرکب ) کسی که اندیشه ٔ عارفانه دارد. عارف دانا <span class=\"hlight\">:</span> <br />عارف اندیش بود وراه شناس <br />پارسائیش را نبود قیاس .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(179339, 'عارف ایگی', '<span class=\"hlight\">عارف ایگی .</span> <font color=\"DarkGreen\"><b>[ رِ ف ِ ]</font></b> (اِخ ) سراج حسن بن غیاث الدین علی معروف به حکیم عارف . پدر وی از کلانتران قصبه ٔ ایگ (ایجه ) بود. در ریحانة الادب آرد: در زمان اکبر شاه هندی به هندوستان رفت و در عظیم آباد ساکن گشت . وی به سال <span class=\"hlight\" dir=\"rtl\">٩٧٦</span> هَ . ق . متولد شد. وفاتش به سال <span class=\"hlight\" dir=\"rtl\">١٠٣٥</span> در بنگاله اتفاق افتاد. دیوان اشعارش حاوی <span class=\"hlight\" dir=\"rtl\">٢٠٠٠</span> بیت شعر است . و او راست : مثنوی اندرزنامه حاوی <span class=\"hlight\" dir=\"rtl\">٢٣٠٠</span> بیت و از جمله اشعار اوست :<br />این عمر که از نیمه ٔ هشتاد گذشت <br />یادش چه کنی که شاد و ناشاد گذشت .<br />(الذریعه ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦٦</span>) (ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤٧</span>).<br /></font></div>'),
(179340, 'عارف شهابی', '<span class=\"hlight\">عارف شهابی .</span> <font color=\"DarkGreen\"><b>[ رِ ف ِ ش َ ]</font></b> (اِخ ) عارف بن سعید شهابی از شعراء و خطبا و نویسندگان بود و به سال <span class=\"hlight\" dir=\"rtl\">١٣٠٧</span> هَ . ق . در حاصبیا از حوالی دمشق متولد شد وپس از پایان تحصیل به منشیگری والی بیروت برگزیده شد و سپس بوکالت دادگستری رسید و مقالاتی در روزنامه ٔ المفید نوشت و آنگاه تصدی آن روزنامه را به عهده گرفت و سرانجام مقامات انتظامی او را تبعید کردند و به سال <span class=\"hlight\" dir=\"rtl\">١٣٣٤</span> محکوم به اعدام گردید. (از الاعلام زرکلی ).<br /></font></div>'),
(179341, 'عارف شوشتری', '<span class=\"hlight\">عارف شوشتری .</span> <font color=\"DarkGreen\"><b>[ رِ ف ِ ت َ ]</font></b> (اِخ ) حاج محمد طاهر. یکی از شعراء قرن چهاردهم بوده، وفات وی به سال <span class=\"hlight\" dir=\"rtl\">١٣٢٢</span> هَ . ق . اتفاق افتاد و او راست دیوان شعر و از جمله اشعار اوست :<br />ای که تو بودی و وجودی نبود<br />آدم خاکی و سجودی نبود<br />مزرعه ٔ عالم ایجاد را<br />بی گل روی تو نمودی نبود.<br /><font color=\"Red\">(از الذریعه ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦٨</span>).</font><br /></font></div>'),
(179342, 'عارف شیرازی', '<span class=\"hlight\">عارف شیرازی .</span><font color=\"DarkGreen\"><b>[ رِ ف ِ ]</font></b> (اِخ ) میرزا آقا علی اکبر پسر میرزا ابوالحسن شاعر و ادیب کامل بود. مدتی در کربلا اقامت کرد و آنگاه به حیدرآباد و بمبای شتافت و عاقبت به لکهنورفت و با فقر و فاقه میگذراند تا از طرف محمد علی شاه حاکم «اود» برای او راه معاشی معین کردند وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٦١</span> در لکهنو وفات یافت و از جمله اشعار اوست :<br />کمندگردن جان گشت زلف عنبرین بویی <br />ز یکدانه بدام آورد دل را خال هندویی <br />نه یادم کرد آن نامهربان نی رفت از یادم <br />سرو کارم فتاده با عجب بدکیش و بدخویی .<br />(از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٧٤</span>). و رجوع به قاموس الاعلام ترکی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٣٩</span> شود.<br /></font></div>'),
(179343, 'عارف عجمی', '<span class=\"hlight\">عارف عجمی .</span> <font color=\"DarkGreen\"><b>[ رِ ف ِ ع َ ج َ ]</font></b> (اِخ ) فتح اﷲ عجمی ازشعرای عهد سلطان سلیمان خان عثمانی قانونی است و وقایعنگار او بوده و اشعار بسیاری درباره ٔ اسفار و محاربات وی سروده است . و از آن جمله است در مدح سلطان :<br />همه موج حلمی و عز و علا<br />همه چشمه ٔ علم و بذل همم .<br />وی به سال <span class=\"hlight\" dir=\"rtl\">٩٦٩</span> هَ . ق . درگذشت . (ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٧</span>). و رجوع به قاموس الاعلام ترکی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٣٩</span> شود.<br /></font></div>'),
(179344, 'عارف قزوینی', '<span class=\"hlight\">عارف قزوینی .</span> <font color=\"DarkGreen\"><b>[ رِ ف ِ ق َ ]</font></b> (اِخ ) نام وی میرزا ابوالقاسم معروف به عارف قزوینی فرزند ملاهادی وکیل است . به سال <span class=\"hlight\" dir=\"rtl\">١٣٠٠</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٢٦٢</span> هَ . ش . در قزوین متولد شد. تحصیلات مقدماتی معمول عصر خود را که عبارت از فارسی و صرف و نحو عربی و دیگر مسائل ادبی بود در قزوین به پایان رسانید. خود گوید: در اوان طفولیت با یکی از دوستان خود بنام مرتضی خان نوه ٔ حاج ملاعبدالوهاب بهشتی هم کلاس و در یک مدرسه درس میخواندیم و پدر من آنطور که باید در تربیت من راه و روش درستی انتخاب نکرد ولکن آن مقدار که گنجایش فکری او بود بنده را تربیت کرد او بدو موضوع اهمیت میداد یکی حسن خط و دیگری موسیقی، و از این جهت من را در طفولیت به چند مکتب فرستاد و پیش سه نفر از معلمان خوش خط تعلیم گرفتم از جمله شیخ رضا خوش نویس و شیخ علی شالی معروف به سکاک که علاوه بر حسن خط ذوق هنری خوبی داشت . در سن سیزده سالگی نزد اولین معلم موسیقی مرحوم حاج صادق خرّازی که در عداد محترمین قزوین بود تعلیم موسیقی گرفتم و چهارده ماه در خدمت او تلمذکردم و چون آواز خوشی داشتم پدرم به طمع افتاد که روضه خوان شوم و از این جهت تمام کارهای خود را به من سپرد و حتی مرا وصی خود قرار داد. عارف با ذوق و استعداد سرشاری که داشت در سنین جوانی بسرودن شعر پرداخت و بسن <span class=\"hlight\" dir=\"rtl\">١٧</span>سالگی قصیده ای سرود که مطلع آن این است :<br />باز از افق هلال محرم شد آشکار<br />باز ابر گریه خیمه فکن شد به جویبار.<br />و در همین سنین بود که تحصیلات خود را رها کرد. در این اوان عاشق دختر یکی از ملاّکان قزوین گردید و چون والدین دختر با وصلت آنان مخالف بودند و او را تهدید به قتل کردند ناچار به رشت گریخت . و چون پس از مدتی به قزوین بازگشت در عقیده ٔ خانواده ٔ دختر تغییری ندید. لذا شبی بدون اراده و بر حسب تقاضای دوستان رهسپار تهران گردید و با اعیان و رجال و درباریان مظفرالدین شاه و محمدعلی شاه آشنا شد. و پس از چندی چنانکه خود گوید بااکراه در سلک ملازمان وثوق الدوله درآمد، و از طریق او با علی اصغرخان اتابک اعظم آشنا شد و برای او آوازمیخواند و در نتیجه به دربار راه یافت و بارها بحضور شاه رسید و مورد توجه خاص قرار گرفت تا آنکه بر حسب امر شاه خواستند او را در سلک فراش خلوت دربار درآورند، ولی وی لباس خود را بر کلاه فراش خلوتی دربار ترجیح داد و زیر بار این سمت نرفت . عارف یکی از شعرای آزادیخواه ایران بوده و از روزی که انقلاب مشروطیت در این سرزمین روی داد تا مدت شانزده سال با ملت در تمام انقلابات همقدم و همگام بود و بواسطه ٔ خطابه ها و نطق های مهیج و بیان خواسته های ملت در لباس شعر، نارضایی خود و مردم را از اوضاع نمودار میکرد، و از تهییج احساسات ملت به مخالفت با دستگاه ظلم و بیدادگری حکام و زمامداران کشور که از نزدیک دیده بود کوتاهی نمیکرد مخصوصاً موقعی که مشروطیت ایران بدست محمدعلی میرزا تعطیل شد و عده ای از رجال نیز با وی همقدم شدند و بدستور بیگانگان کاخ آمال و آرزوی مردم را در هم ریختند طوفانی در روح وی پدیدار گردید چنانکه گوید:<br />پارتی زلف تو از بسکه ز دلها دارد<br />روز و شب بی سببی عربده با ما دارد<br />کاش کابینه ٔ زلفت شود از شانه پریش <br />کو پریشانی ما جمله مهیا دارد<br />با که این درد توان گفت که والا حضرت <br />در نیابت روش حضرت والا دارد.<br />عارف به علت سر پرشور و بی باکی خاصی که داشت بیشتر اوقات متواری و در حال مسافرت و تردد مابین اصفهان و تهران بود او در همین مسافرتها با رجال آزادیخواه تماس میگرفت و مردم را به مخالفت با دستگاه فرعونی حکام وقت میشورانید. او بنواحی غرب و بغداد و کرمانشاهان و استانبول نیز مسافرت و مدتی در آن شهرها با آزادیخواهان همکاری کرد و در قیام آذربایجان با ملت همگام شد و به خراسان نیز مسافرت کرد. در مورد اتحاداسلامی نیز اقداماتی نمود. ولی این راه را ادامه نداد. او دارای خصائصی بود از قبیل وطن دوستی، آزادگی، شوریدگی، صمیمیت، حساسیت شدید و به تندخویی نیز مشهوربود. از جمله اشعار وطن دوستانه ٔ اوست :<br />مرا ز عشق وطن دل به این خوشست که گر<br />ز عشق هر که شود کشته زاده ٔ وطن است .<br />از جمله اشعار انقلابی عارف غزلی است که گوید:<br />لباس مرگ بر اندام عالمی زیباست <br />چه شد که کوته و زشت این قبا به قامت ماست <br />تا آنجاکه گوید:<br />ز حد گذشت تعدی کسی نمی پرسد<br />حدود خانه ٔ بی خانمان ما ز کجاست <br />برای ریختن خون فاسد این خلق <br />خبر دهید که چنگیز پی خجسته کجاست .<br />عمده ٔ هنر او در ساختن تصنیف بود. عارف بعد از یک سلسله کشمکشها و ناراحتی ها به همدان مسافرت کرد و بنابر قولی تبعید شد و تا آخر عمر در آن سامان به حال انزوا و فلاکت زندگی کرد. به سال <span class=\"hlight\" dir=\"rtl\">١٣١٢</span> هَ . ش . وفات نمود و درجوار آرامگاه ابوعلی سینا مدفون گردید. (از دیوان عارف و مقدمه ٔ شفق ).<br /></font></div>'),
(179345, 'عارفة', '<span class=\"hlight\">عارفة.</span> <font color=\"DarkGreen\"><b>[ رِ ف َ ]</font></b> (ع ص ) مؤنث عارف : امراءة عارفة؛ زن شکیبا. (ناظم الاطباء). و رجوع به عارف شود. <BR><font color=\"Blue\">◄</font> (اِمص ) مهربانی . (غیاث ) (آنندراج ). نیکویی . ج، عوارف . <BR><font color=\"Blue\">◄</font> (ص ) شناخته شده . (منتهی الارب ).<br /></font></div>'),
(179346, 'عارفی', '<span class=\"hlight\">عارفی .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) مولا محمود عارفی هم عصر خاقانی و ملقب به سلمان ثانی است وفات او در حدود سال <span class=\"hlight\" dir=\"rtl\">٨٤٠</span> هَ . ق . در هرات اتفاق افتاد. دیوان غزلیاتش مشهور است . و از جمله اشعار اوست :<br />عهد کردم که نیایم بدر از میخانه <br />تابه آن دم که مرا پر نشود پیمانه .<br />(مجالس النفائس ص <span class=\"hlight\" dir=\"rtl\">١٩٤</span>). و رجوع به رجال حبیب السیر ص <span class=\"hlight\" dir=\"rtl\">١١٤</span> شود.<br /></font></div>'),
(179347, 'عارم', '<span class=\"hlight\">عارم .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص ) سخت و شدید. <BR><font color=\"Blue\">◄</font> سخت سرد: یوم عارم ؛ روز سخت سرد. <BR><font color=\"Blue\">◄</font> پلید. رجل عارم ؛ مرد پلید. <BR><font color=\"Blue\">◄</font> شوخ . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> صبی عارم ؛ کودک شادمان . (ناظم الاطباء).<br /></font></div>'),
(179348, 'عارم', '<span class=\"hlight\">عارم .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) نام مردی است . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نام اسب منذربن اعلم . <BR><font color=\"Blue\">◄</font> سجن عارم ؛ زندانی است در کوفه که عبداﷲبن زبیر را در آن زندانی کردند. (منتهی الارب ).<br /></font></div>'),
(179349, 'عارم', '<span class=\"hlight\">عارم .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) لقب ابوعثمان محمدبن فضل بصری .<br /></font></div>'),
(179350, 'عارم', '<span class=\"hlight\">عارم .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (اِخ ) ابن ابی سلم . بطنی از مرهبة بن دعام از صعب بن دوْمان بن بَکیل از قحطانیه است . (معجم قبائل العرب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٠١</span>).<br /></font></div>'),
(179351, 'عارمة', '<span class=\"hlight\">عارمة.</span> <font color=\"DarkGreen\"><b>[ رِ م َ ]</font></b> (ع ص ) مؤنث عارم . زن شوخ . (مهذب الاسماء).<br /></font></div>'),
(179352, 'عارن', '<span class=\"hlight\">عارن .</span><font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179353, 'عارنة', '<span class=\"hlight\">عارنة.</span> <font color=\"DarkGreen\"><b>[ رِ ن َ ]</font></b> (ع ص ) دور. دیار عارنة؛ دیار دور. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(179354, 'عارک', '<span class=\"hlight\">عارک .</span> <font color=\"DarkGreen\"><b>[ رِ ]</font></b> (ع ص ) شتر که از خراش آرنج بازویش بریده باشد. (آنندراج ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زن حائض . (آنندراج ) (منتهی الارب ) (مهذب الاسماء).<br /></font></div>'),
(179355, 'عاری', '<span class=\"hlight\">عاری .</span> (ع ص ) برهنه . ج، عُراة. (منتهی الارب ) (آنندراج ) (غیاث اللغات ). رجل عاری الاشاجع؛ مردی که گوشت ندارد. (مهذب الاسماء). کسی که به بیماری «عروا» مبتلا شود. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مبرا و بی مو. <BR><font color=\"Blue\">◄</font> صاف . <BR><font color=\"Blue\">◄</font> معاف . <BR><font color=\"Blue\">◄</font> ساده . نادان . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> جوینده و آهنگ کننده ٔ احسان از کسی . <BR><font color=\"Blue\">◄</font> امر عارض شونده . نازل شونده . (اقرب الموارد).<br /></font></div>'),
(179356, 'عاری', '<span class=\"hlight\">عاری .</span> (اِخ ) محمدبن ابراهیم بن عبدالرحمان الاریحاوی عاری در سالهای <span class=\"hlight\" dir=\"rtl\">١٠١٨</span> - <span class=\"hlight\" dir=\"rtl\">١١٩٩</span> هَ . ق . می زیست و یکی از فقها و مفتیان بود. (الاعلام زرکلی ).<br /></font></div>'),
(179357, 'عاریات', '<span class=\"hlight\">عاریات .</span> (ع اِ) ج ِ عاریة. (ناظم الاطباء).<br /></font></div>'),
(179358, 'عاریة', '<span class=\"hlight\">عاریة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع اِ) عاریت . هر چیز عاریتی ومنسوب به عار است از جهت آنکه طلب کردنش عار و ننگ است . (منتهی الارب ) (آنندراج ) (از غیاث اللغات ). <BR><font color=\"Blue\">◄</font> (اصطلاح فقهی ) در اصطلاح فقهی عبارت از تملیک منفعت است بدون بدل و عوض . در ترجمه ٔ النهایه آرد: عاریت بر دو ضرب است ضربی از وی مضمون است بر همه حالی اگر بشرط کنند و اگر بشرط نکنند مانند زر و سیم وغیره، و ضرب دیگر آنکه گیرنده ٔ عاریت ضامن نبود الا که خداوندش با وی ضمان کند و یا در نگه داشتن مسامحه یا تفریط کند. (النهایه شیخ طوسی صص <span class=\"hlight\" dir=\"rtl\">٢٩٦</span>- <span class=\"hlight\" dir=\"rtl\">٢٩٧</span>). و رجوع به تعریفات جرجانی و کشاف اصطلاحات الفنون شود.<br />در شرح لمعه نویسد که : عاریه از عقوده ٔ جائزه است که موجب جواز تصرف در عین است جهت انتفاع بردن با شرط بقاء اصل و آن از عقودی است که ایجاب و قبول آن رابا هر لفظی میتوان انجام داد. آنکه عاریه دهد مُعیرگویند و باید متصف به صفت کمال و عقل بوده بالغ و جائز التصرف باشد و آن که عاریه کند مُستعیرگویند و باید به کمال عقل آراسته و بالغ باشد. و احکام و شرائط آن از این قرار است :<br /><span class=\"hlight\" dir=\"rtl\">١</span> - مال مستعاره در دست عاریه کننده امانت است و در صورت تلف ضمانی بعهده ٔ او نیست مگر آنکه از روی قصد اسباب تلف آن را فراهم کرده باشد. و یا در نگاه داشتن آن مسامحه کرده باشد و یا از حدود اجازه ٔ تصرفات خود تجاوز کرده باشد. <span class=\"hlight\" dir=\"rtl\">٢</span> - اگر نقصی در عین مستعار پدید آید ضمانی بر عاریه کننده نمی باشد مگر آنکه نقص بواسطه ٔ تجاوز از حدود اجازه تصرفات محدود باشد. <span class=\"hlight\" dir=\"rtl\">٣</span> - اگر در ضمن عقد عاریه شرط ضمان شود عاریه کننده در هر حال ضامن خواهد بود. <span class=\"hlight\" dir=\"rtl\">٤</span> - عاریه کننده نتواند مال مستعاره را به دیگری عاریه دهد مگر به اجاره ٔ عاریه دهنده که مالک آن است . (از شرح لمعه ج <span class=\"hlight\" dir=\"rtl\">١</span> مبحث عاریه ).<br /></font></div>'),
(179359, 'عاریت', '<span class=\"hlight\">عاریت .</span><font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص، اِ) عاریة. آنچه بدهند و بگیرند. (غیاث اللغات ) (منتهی الارب ) (آنندراج ). آنچه از کسی ستانند برای رفع حاجتی و چون رفع حاجت کنند بازدهند. آنچه در اختیار انسان بود از مال خود و با خواستن، گرفتن، دادن، کردن و شدن و سپردن ترکیب شود <span class=\"hlight\">:</span> <br />این همی گوید که دارم ملک از تو عاریت <br />وان همی گوید که دارم دولت از تو مستعار.<br /> <font color=\"Red\">منوچهری .</font><br />چون میگذرد کار چه آسان و چه سخت <br />این یکدم عاریت چه ادبار و چه بخت .<br /> <font color=\"Red\">عنصری .</font><br />گرچه بسیار دهد شاد نبایدت شدن <br />بعطاهاش که جز عاریتی نیست عطاش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />عاریت داشتم این از تو تا یک چند<br />پیش تو بفگنم این داشته پیراهن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />خدای راست بزرگی و ملک بی انباز<br />به دیگران که تو بینی به عاریت داده ست .<br /> <font color=\"Red\">سعدی .</font><br />این جان عاریت که به حافظ سپرده دوست <br />روزی رخش ببینم و تسلیم وی کنم .<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">پای عاریت </span> ؛ پای مصنوعی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چشم عاریت </span> ؛ چشم مصنوعی که بواسطه ٔ عمل جراحی بجای چشم معیوب گذارند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">حیات عاریت </span> ؛ زندگی ناپایدار. (ناظم الاطباء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دندان عاریت </span> ؛ دندان مصنوعی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">گیس عاریت </span> ؛ گیس مصنوعی . کلاه گیس .<br /></font></div>'),
(179360, 'عاریت خواستن', '<span class=\"hlight\">عاریت خواستن .</span> <font color=\"DarkGreen\"><b>[ ی َ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ت َ ]</font></b> (مص مرکب ) به عاریت طلبیدن . (منتهی الارب ) <span class=\"hlight\">:</span> <br />کهن جامه ٔ خویش پیراستن <br />به از جامه ٔ عاریت خواستن .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(179361, 'عاریت دادن', '<span class=\"hlight\">عاریت دادن .</span> <font color=\"DarkGreen\"><b>[ ی َ دَ ]</font></b> (مص مرکب ) به عاریت دادن . <BR><font color=\"Blue\">◄</font> عاریت دادن شترکسی را تا بدان ناقه ٔ خود را دوشد. (منتهی الارب ).<br /></font></div>'),
(179362, 'عاریت سرا', '<span class=\"hlight\">عاریت سرا.</span> <font color=\"DarkGreen\"><b>[ ی َ س َ ]</font></b> (اِ مرکب ) کنایه از دنیای فانی و عالم سفلی باشد. (برهان ) (آنندراج ) <span class=\"hlight\">:</span> <br />از عافیت مپرس که کس را نداده اند<br />در عاریت سرای جهان عافیت عطا.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(179363, 'عاریت شش روزه', '<span class=\"hlight\">عاریت شش روزه .</span> <font color=\"DarkGreen\"><b>[ ی َ ت ِ ش ِ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از آسمان و زمین و هر چه در اوست . (انجمن آرای ناصری ).<br /></font></div>'),
(179364, 'عاریتی', '<span class=\"hlight\">عاریتی .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ص نسبی ) منسوب است به عاریت و آنچه به عاریت باشد و آنچه به عاریت ستانند و آنچه را بقاء نباشد چون زندگی و غیره <span class=\"hlight\">:</span> <br />به عمر عاریتی هیچ اعتماد مکن <br />که پنج روز دگر میرود به استعجال .<br /> <font color=\"Red\">سعدی .</font><br />وعاقل به جاه عاریتی مغرور نگردد. (مجالس سعدی ). رجوع به عاریت و عاریة شود.<br /></font></div>'),
(179365, 'عاز', '<span class=\"hlight\">عاز.</span><font color=\"DarkGreen\"><b>[ زز ]</font></b> (ع ص، اِ) کوه طویل و دراز. (منتهی الارب ).<br /></font></div>'),
(179366, 'عازب', '<span class=\"hlight\">عازب .</span> <font color=\"DarkGreen\"><b>[ زِ]</font></b> (ع ص ) آب و گیاه دوردست . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (ص ) شتران که شب در حی نیایند. (منتهی الارب ). شاة عازب ؛ گوسپندان دور در چراگاه . (ناظم الاطباء) (آنندراج ). <BR><font color=\"Blue\">◄</font> مرد بی زن و بی اهل . ج، عزاب . <BR><font color=\"Blue\">◄</font> غایب و پنهان . (ناظم الاطباء).<br /></font></div>'),
(179367, 'عازب', '<span class=\"hlight\">عازب .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (اِخ ) کوهی است . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179368, 'عازبة', '<span class=\"hlight\">عازبة.</span> <font color=\"DarkGreen\"><b>[زِ ب َ ]</font></b> (ع ص، اِ) زن مرد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شتر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زنی که در هنگام طهر شویش غایب باشد. ج، عَوازِب . (ناظم الاطباء).<br /></font></div>'),
(179369, 'عازر', '<span class=\"hlight\">عازر.</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِخ ) نام آن مردی است که عیسی (ع ) او را بعد ازمرگ زنده کرد. (منتهی الارب ) (آنندراج ) <span class=\"hlight\">:</span> <br />عازر ثانی منم یافته از وی حیات <br />عیسی دلها وی است داده تنم را شفا.<br /> <font color=\"Red\">خاقانی .</font><br />و رجوع به آزر شود.<br /></font></div>'),
(179370, 'عازر', '<span class=\"hlight\">عازر.</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (اِخ ) آزر. دوست ابراهیم . (عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٩٠</span>). و همان است که در قرآن آزر و پدر ابراهیم معرفی شده است : و اذ قال ابراهیم لابیه آزر أتتخذ أصناماً آلهة. (قرآن <span class=\"hlight\" dir=\"rtl\">٧٤/٦</span>). برخی از مفسرین گویند عموی ابراهیم بوده است . در تفسیر تبیان است که آزر جد مادری و یا عموی ابراهیم بوده است زیرا پدر ابراهیم از مؤمنان بوده است و از گفتار مجاهد نقل کند که آزر نام بت است . (تفسیر تبیان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٢٦</span>).<br /></font></div>'),
(179371, 'عازریة', '<span class=\"hlight\">عازریة.</span> <font color=\"DarkGreen\"><b>[ زَ ری ْ ی َ ]</font></b> (اِخ ) قریه ٔ بیت المقدس است و در آنجاست قبرعازر که او را عیسی علیه السلام زنده کرد. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٩٥</span>).<br /></font></div>'),
(179372, 'عازف', '<span class=\"hlight\">عازف .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (ع ص ) چغانه زننده که نوعی از رودچامه هاست . (منتهی الارب ). مرد معازف باز. سرودگوی . (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(179373, 'عازف', '<span class=\"hlight\">عازف .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (اِخ ) موضعی است . (آنندراج ) (منتهی الارب ). عزیف یعنی صوت و ممکن است محل مخصوص راکه در اثر وزش باد صوت ایجاد میکند عازف گویند. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٩٥</span>).<br /></font></div>'),
(179374, 'عازم', '<span class=\"hlight\">عازم .</span> <font color=\"DarkGreen\"><b>[ زِ ]</font></b> (ع ص ) آهنگ کننده . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> کوشش کننده . (ناظم الاطباء). کسی که اراده ٔ حتمی به انجام کاری کند. (فرهنگ نظام ).<br /></font></div>'),
(179375, 'عازم شدن', '<span class=\"hlight\">عازم شدن .</span> <font color=\"DarkGreen\"><b>[ زِ ش ُ دَ ]</font></b> (مص مرکب ) آهنگ کردن . قصد کردن <span class=\"hlight\">:</span> <br />یارب بفضل خویش ببخشای بنده را<br />آن دم که عازم سفر آن جهان شود.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(179376, 'عاس', '<span class=\"hlight\">عاس .</span> <font color=\"DarkGreen\"><b>[ عاس س ]</font></b> (ع ص، اِ) شبگردنده ٔ گرد شهر. (منتهی الارب ). پاسبان . ج، عَسَس و عَسیس . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179377, 'عاس', '<span class=\"hlight\">عاس .</span> (اِخ ) بطنی است از آل عمران از آل کثیر.یکی از قبائل حضرموت . (معجم قبائل العرب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٠١</span>).<br /></font></div>'),
(179378, 'عاسر', '<span class=\"hlight\">عاسر.</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (ع ص ) شتر ماده ٔ دم برداشته ٔ دونده . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179379, 'عاسف', '<span class=\"hlight\">عاسف .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (ع ص ) ناقة عاسف ؛ شتر ماده ٔ طاعون زده که به مرگ نزدیک شده باشد. (مهذب الاسماء) (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(179380, 'عاسل', '<span class=\"hlight\">عاسل .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (ع ص ) انگبین گیرنده . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نیزه ٔ سخت لرزان . (منتهی الارب ) (آنندراج ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> مرد نیک و صالح . ج، عُسُل . <BR><font color=\"Blue\">◄</font> مرد ستوده کردار و نیک عمل که بدان ستایش و ذکر او را بیارایند و مانند انگبین شیرین گردانند. <BR><font color=\"Blue\">◄</font> (اِ) گرگ . ج، عُسَّل . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179381, 'عاسلة', '<span class=\"hlight\">عاسلة.</span> <font color=\"DarkGreen\"><b>[ س ِ ل َ ]</font></b> (ع ص ) خلیة عاسلة؛ کبت پر از انگبین . (منتهی الارب ) (آنندراج ). کندوی پر از عسل . (ناظم الاطباء).<br /></font></div>'),
(179382, 'عاسم', '<span class=\"hlight\">عاسم .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (ع ص ) رنج و سختی رساننده بر عیال . (منتهی الارب ) (آنندراج ). زحمت کشنده جهت عیال بود. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد طامع. (منتهی الارب ) (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٩٥</span>).<br /></font></div>'),
(179383, 'عاسم', '<span class=\"hlight\">عاسم .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) نام موضعی است یا ریگ توده ای به عالج . (منتهی الارب ). نام آبی است مر کلب را در سرزمین شام نزدیک خُرّ. نصر گوید عاسم رمل بنی سعد است . طِرّماح گوید: رمل نافذبن سعد المعنی است . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٩٥</span>).<br /></font></div>'),
(179384, 'عاسم آباد', '<span class=\"hlight\">عاسم آباد.</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) دهی است از دهستان بزچلو بخش کمیجان شهرستان اراک . واقع در <span class=\"hlight\" dir=\"rtl\">١٥</span>هزارگزی باختر کمیجان و شش هزارگزی راه عمومی . ناحیه ای است کوهستانی و سردسیر و <span class=\"hlight\" dir=\"rtl\">١١٠</span> تن سکنه دارد. اراضی آن از قنات مشروب میشود. محصولاتش، غلات وبنشن است . اهالی به کشاورزی گذران میکنند از خسروبیگ اتومبیل میرود. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(179385, 'عاسمین', '<span class=\"hlight\">عاسمین .</span> <font color=\"DarkGreen\"><b>[ س ِ م َ ]</font></b> (اِخ ) در معجم البلدان است که اگر تثنیه ٔ عاسم نباشد جایگاه دیگر است و این کلمه در یکی از اشعار راعی به کار رفته <span class=\"hlight\">:</span> <br />و یقلن بعاسمین و ذات رمح <br />اذا حان المقیل و یرتعینا.<br /><font color=\"Red\">(معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٩٥</span>).</font><br /></font></div>'),
(179386, 'عاسن', '<span class=\"hlight\">عاسن .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (ع ص ) مکان عاسن ؛ جای تنگ . (منتهی الارب ).<br /></font></div>'),
(179387, 'عاسی', '<span class=\"hlight\">عاسی .</span> (ع اِ) خرمابن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شاخه ٔ درشت و خشک . (ناظم الاطباء)(آنندراج ). <BR><font color=\"Blue\">◄</font> شاخ خرما. (منتهی الارب ).<br /></font></div>'),
(179388, 'عاش', '<span class=\"hlight\">عاش .</span> <font color=\"DarkGreen\"><b>[ ش ِن ْ ]</font></b> (ع ص ) مرد شبانگاه خورنده ٔ آهنگ کننده . (منتهی الارب ).<br /></font></div>'),
(179389, 'عاشب', '<span class=\"hlight\">عاشب .</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (ع ص ) بلد عاشب ؛ شهر گیاه ناک . (منتهی الارب ). زمین گیاه ناک . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بعیر عاشب ؛ شتر گیاه تر چرنده . (منتهی الارب ) (آنندراج ) (مهذب الاسماء).<br /></font></div>'),
(179390, 'عاشبة', '<span class=\"hlight\">عاشبة.</span> <font color=\"DarkGreen\"><b>[ ش ِ ب َ ]</font></b> (ع ص ) مؤنث عاشب . أرض عاشبة؛ زمین گیاهناک . (منتهی الارب ).<br /></font></div>'),
(179391, 'عاشج', '<span class=\"hlight\">عاشج .</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (اِخ ) بطنی است معروف به بو عاشج . (معجم قبائل العرب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٠١</span>).<br /></font></div>'),
(179392, 'عاشر', '<span class=\"hlight\">عاشر.</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (ع ص ) ده یک گیرنده . (منتهی الارب )(آنندراج ). <BR><font color=\"Blue\">◄</font> آنکه بر راه گمارند که از اموال بازرگانان صدقه گیرد. (تعریفات ). در شرع عاشر کسی را گویند که امام او را برای گرفتن عشر از تجار مأمور طرق و شوارع کرده تا وجه مأخوذه از آنها را هزینه ٔ امنیت راهها و جاده ها کنند. (کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> دهم . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179393, 'عاشرات', '<span class=\"hlight\">عاشرات .</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (ع ص، اِ) ج ِ عاشرة.<br /></font></div>'),
(179394, 'عاشق', '<span class=\"hlight\">عاشق .</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (ع ص ) عشق آرنده . ج، عُشّاق . (منتهی الارب ) (مهذب الاسماء) (آنندراج ). آنکه در دوستی کسی یا چیزی به نهایت رسیده باشد. دل شیفته . شیفته دل . دلداده . دلشده . دل سوخته . دلباخته . دل از دست داده . دل از دست رفته <span class=\"hlight\">:</span> اورا حاسدان و عاشقان خاستند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٨٢</span>).<br />تو هم معشوق و هم عاشق تو هم مطلوب و هم طالب <br />تو هم منظور و هم ناظر تو هم شاهی و هم دربان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />عاشقان جان فشان کنند همه <br />شاهدان کار جان کنند همه .<br /> <font color=\"Red\">خاقانی .</font><br />بقا دوستان را فنا عاشقان را<br />من آن عاشقم کز بقا میگریزم .<br /> <font color=\"Red\">خاقانی .</font><br />عاشقان کشتگان معشوقند<br />برنیاید ز کشتگان آواز.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(179395, 'عاشق', '<span class=\"hlight\">عاشق .</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (اِخ ) دهی است از دهستان ترگور بخش سلوانا شهرستان ارومیه واقع در هشت هزارو پانصدگزی شمال باختر سلوانا و چهارهزارو پانصدگزی باختر راه ارابه رو موانا به ارومیه محلی کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">١٢٠</span> تن سکنه دارد. آب آن از چشمه و محصول آن غله و شغل اهالی زراعت و گله داری و صنایع دستی آنان جاجیم بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(179396, 'عاشق آباد', '<span class=\"hlight\">عاشق آباد.</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (اِخ ) دهی است از دههای ماربین بخش سده ٔ شهرستان اصفهان واقع در هفت هزارگزی شمال خاوری سده و یک هزارگزی راه شوسه ٔ اصفهان به تهران . واقع در جلگه و آب و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٢٩٧٥</span> تن سکنه دارد. آب آن از قنات تأمین میشود و محصول آن غله، پنبه، حبوب و تنباکو است . شغل اهالی زراعت و صنایع دستی زنان آنجا کرباس بافی است راه ماشین روو دبستان دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(179397, 'عاشق آزار', '<span class=\"hlight\">عاشق آزار.</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (نف مرکب ) معشوقی که به عاشق خود اذیت و آزار رساند. (ناظم الاطباء).<br /></font></div>'),
(179398, 'عاشق اصفهانی', '<span class=\"hlight\">عاشق اصفهانی .</span> <font color=\"DarkGreen\"><b>[ ش ِ ق ِ اِ ف َ ]</font></b> (اِخ ) مؤلف مجمع الفصحاء آرد: نام او آقامحمد و شغل وی خیاطت و حالتش قناعت طبعش عالی و اشعارش حالی در شیوه ٔ غزل سرایی طرزی دلپسند دارد. معاصر هاتف و آذر بوده است و او راست : دیوان غزلیات . گویند اشعار او به ده هزار رسیده است در غزلیات مضامین عاشقانه دارد از آن جمله است :<br />تاجر عشقم به کف مایه و سودم وفا<br />تا که شود مشتری تا چه دهد در بها<br />ما و دل بی نصیب هر دو فقیر و غریب <br />تا که شود مهربان تا که شود آشنا.<br />وفات وی به سال <span class=\"hlight\" dir=\"rtl\">١١٨١</span> هَ . ق . اتفاق افتاده است . (از مجمع الفصحاء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٦</span>). و رجوع به الذریعه ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٦٧٢</span> شود.<br /></font></div>'),
(179399, 'عاشق باره', '<span class=\"hlight\">عاشق باره .</span> <font color=\"DarkGreen\"><b>[ ش ِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (ص مرکب ) عاشق دوست . هواخواه عاشق خود <span class=\"hlight\">:</span> <br />چون سبو تا هست غم از زندگی در پیکرت <br />دستگیری کن می آشامان عاشق باره را.<br /><font color=\"Red\">صائب .</font><br /></font></div>'),
(179400, 'عاشق حصار', '<span class=\"hlight\">عاشق حصار.</span> <font color=\"DarkGreen\"><b>[ ش ِ ح ِ ]</font></b> (اِخ ) دهی است جزء دهستان قازان بخش ضیأآباد شهرستان قزوین واقع در <span class=\"hlight\" dir=\"rtl\">١٤٠٠</span>گزی راه شوسه واقع در جلگه آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٢٠٩</span> تن سکنه دارد. اراضی آنجا از قنات و چشمه سار مشروب میشود.محصولات آن غلات و انگور و شغل اهالی زراعت و گله داری است . راه مالرو دارد و از طریق تاکستان میتوان ماشین برد. کردهای این ده از طائفه ٔ کاکاوند هستند و تغییر مکان نمیکنند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(179401, 'عاشق خشک', '<span class=\"hlight\">عاشق خشک .</span> <font color=\"DarkGreen\"><b>[ ش ِ ق ِ خ ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایت ازعاشق خسیس و رذل و بی صدق است . (برهان ) (آنندراج ).<br /></font></div>'),
(179402, 'عاشق سمرقندی', '<span class=\"hlight\">عاشق سمرقندی .</span> <font color=\"DarkGreen\"><b>[ ش ِ ق ِ س َ م َ ق َ ]</font></b> (اِخ ) یا خوارزمی، مکنی به ابوالخیر. از شعرای قرن دهم هجری است که محل توجه سلاطین وقت بود و مدتی در هرات اقامت نمود و مورد عنایات سلطان حسین بایقرا گردید. وی به سال <span class=\"hlight\" dir=\"rtl\">٩٥٧</span> هَ . ق . در ماوراءالنهر درگذشت . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٧</span>).<br /></font></div>'),
(179403, 'عاشق سگ جان', '<span class=\"hlight\">عاشق سگ جان .</span> <font color=\"DarkGreen\"><b>[ ش ِ ق ِ س َ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایت از دنیاطلبان و طالبان دنیا باشد. (برهان ) (آنندراج ).<br /></font></div>'),
(179404, 'عاشق شدن', '<span class=\"hlight\">عاشق شدن .</span> <font color=\"DarkGreen\"><b>[ ش ِ ش ُ دَ ]</font></b> (مص مرکب )شیفته شدن . دوستی شدید به کسی یا چیزی <span class=\"hlight\">:</span> <br />خود که باشد که تو را بیند و عاشق نشود<br />مگرش هیچ نباشدکه خریدار تو نیست .<br /> <font color=\"Red\">سعدی .</font><br />عشق ورزیدم و عقلم به ملامت برخاست <br />هرکه عاشق شد از او حکم سلامت برخاست .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(179405, 'عاشق لو', '<span class=\"hlight\">عاشق لو.</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (اِخ ) دهی است از دهستان منجوان بخش خداآفرین شهرستان تبریز واقع در <span class=\"hlight\" dir=\"rtl\">٢٦</span>هزار و پانصدگزی جنوب باختری خداآفرین و <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارو پانصد گزی شوسه ٔ اهر به کلیبر. محلی کوهستانی گرمسیر و مالاریایی است و <span class=\"hlight\" dir=\"rtl\">٣٠٥</span> تن سکنه دارد. آب آن از رودخانه ٔ قره سو و ارس و چشمه تأمین میشود و محصول عمده ٔ آن غلات و پنبه و شغل اهالی زراعت و گله داری است وراه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(179406, 'عاشق نواز', '<span class=\"hlight\">عاشق نواز.</span> <font color=\"DarkGreen\"><b>[ ش ِ ن َ ]</font></b> (نف مرکب ) نوازنده ٔ عاشق . آنکه به عاشق لطف کند. آنکه دل عاشق را استمالت کند <span class=\"hlight\">:</span> <br />بیا ساقی از شادی نوش و ناز<br />یکی شربت از میر عاشق نواز.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(179407, 'عاشق و معشوق', '<span class=\"hlight\">عاشق و معشوق .</span> <font color=\"DarkGreen\"><b>[ ش ِق ُ م َ ]</font></b> (ترکیب عطفی، اِ مرکب ) دو تن که شیفته ٔ یکدیگر باشند. <BR><font color=\"Blue\">◄</font> دو نگین متغایر اللون که دریک خانه ٔ انگشتری باشد. (غیاث اللغات ) (آنندراج ).<br /></font></div>'),
(179408, 'عاشق وش', '<span class=\"hlight\">عاشق وش .</span> <font color=\"DarkGreen\"><b>[ ش ِ وَ ]</font></b> (ص مرکب ) بمانند عاشق . همانند عاشق <span class=\"hlight\">:</span> <br />در هر چمن عاشق وشان بر ساقی و می جانفشان <br />پیر خرد ز انصافشان با می مواسا داشتن .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(179409, 'عاشق پرانی', '<span class=\"hlight\">عاشق پرانی .</span> <font color=\"DarkGreen\"><b>[ ش ِ پ َ ]</font></b> (حامص مرکب ) هر روز عاشق نوی به هم رسانیدن . مقابل معشوق پرانی <span class=\"hlight\">:</span> <br />از گل عاشق پرانی جلوه می بالد به خود<br />سرو از بالای قمری بر سرناز ایستد.<br /><font color=\"Red\">(آنندراج ).</font><br /></font></div>'),
(179410, 'عاشق پسند', '<span class=\"hlight\">عاشق پسند.</span> <font color=\"DarkGreen\"><b>[ ش ِ پ َ س َ ]</font></b> (ن مف مرکب ) آنچه عاشق پسندد. آنچه عاشق را شیدا کند <span class=\"hlight\">:</span> <br />به مرغوبی جور عاشق پسند<br />به دل کوبی لطف ارباب پند.<br /><font color=\"Red\">ظهوری (آنندراج ).</font><br /></font></div>'),
(179411, 'عاشق پیشه', '<span class=\"hlight\">عاشق پیشه .</span> <font color=\"DarkGreen\"><b>[ ش ِ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص مرکب ) کسی که کار او عاشقی است .<br /></font></div>'),
(179412, 'عاشق کش', '<span class=\"hlight\">عاشق کش .</span> <font color=\"DarkGreen\"><b>[ ش ِ ک ُ ]</font></b> (نف مرکب ) کشنده ٔ عاشق <span class=\"hlight\">:</span> <br />تیر عاشق کش ندانم بر دل حافظ که زد<br />اینقدر دانم که از شعر ترش خون میچکید.<br /><font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> آنکه عاشق خود را به محبتی ننوازد و بر وی ستم کند. جفا کننده در حق عاشق <span class=\"hlight\">:</span> <br />ای نسیم سحر آرامگه یار کجاست <br />منزل آن مه عاشق کش عیار کجاست .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(179413, 'عاشق کشی', '<span class=\"hlight\">عاشق کشی .</span> <font color=\"DarkGreen\"><b>[ ش ِ ک ُ ]</font></b> (حامص مرکب ) عمل عاشق کش . عاشق آزاری . جفا کردن عاشق را <span class=\"hlight\">:</span> <br />رسم عاشق کشی و شیوه ٔ شهرآشوبی <br />جامه ای بود که بر قامت او دوخته بود.<br /> <font color=\"Red\">حافظ.</font><br />زآنجا که رسم و عادت عاشق کشی تست <br />با دشمنان قدح کش و با ما عتاب کن .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(179414, 'عاشقان', '<span class=\"hlight\">عاشقان .</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (اِخ ) دهی است از میان ولایت بخش حومه ٔ شهرستان مشهد واقع در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی شمال باختری مشهد درکنار کشف رود واقع در جلگه و آب و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">١٣٢</span> تن سکنه دارد. محصول آن غله و شغل اهالی زراعت و مالداری است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179415, 'عاشقان', '<span class=\"hlight\">عاشقان .</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (اِخ ) دهی است از دهستان گوران شهرستان شاه آباد واقع در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی خاور گهواره و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی قله ٔ امیرخان . ناحیه ای است کوهستانی، سردسیر و <span class=\"hlight\" dir=\"rtl\">١٦٠</span> تن سکنه دارد. آب آن از چشمه و محصولاتش غلات، حبوب، توتون، صیفی، لبنیات است و اهالی به کشاورزی و گله داری گذران میکنند. راه آن مالرو است . در دو محل بفاصله ٔ دوهزارگز واقع به عاشقان سید کاکا و عاشقان علی مشهور است ساکنان آن از تیره ٔگهواره ای هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(179416, 'عاشقان', '<span class=\"hlight\">عاشقان .</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (اِخ ) ده کوچکی است از دهستان دلفارد بخش ساردوئیه شهرستان جیرفت واقع در <span class=\"hlight\" dir=\"rtl\">٤٣</span>هزارگزی جنوب خاوری ساردوئیه - جیرفت و <span class=\"hlight\" dir=\"rtl\">٧</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179417, 'عاشقانه', '<span class=\"hlight\">عاشقانه .</span> <font color=\"DarkGreen\"><b>[ ش ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص نسبی، ق مرکب ) عاشق وار. از روی عشق . از کمال محبت . با نهایت میل <span class=\"hlight\">:</span> <br />دعوت عاشقانه میکردم <br />بخت درهای آسمان بگشاد.<br /> <font color=\"Red\">خاقانی .</font><br />در آن صحرای خرم رخش میراند<br />سرود عاشقانه باز میخواند.<br /> <font color=\"Red\">نظامی .</font><br />صائب اگر بیار سخن فهم میرسید<br />میشد جهان پر از غزل عاشقانه اش .<br /><font color=\"Red\">صائب .</font><br /></font></div>'),
(179418, 'عاشقبا', '<span class=\"hlight\">عاشقبا.</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (اِ مرکب ) نام طعامی است ترش <span class=\"hlight\">:</span> <br />پیش از آن دم که مزعفر شکفد همچون گل <br />داغ او چون حبشی بر رخ عاشقبا بود.<br /><font color=\"Red\">بسحاق اطعمه (دیوان ص <span class=\"hlight\" dir=\"rtl\">٥١</span>).</font><br /></font></div>'),
(179419, 'عاشقه', '<span class=\"hlight\">عاشقه .</span> <font color=\"DarkGreen\"><b>[ ش ِ ق َ ]</font></b> (اِخ ) دهی است از دهستان رستاق بخش خمین شهرستان محلات واقع در <span class=\"hlight\" dir=\"rtl\">٦٦</span> هزارگزی شمال باختری خمین کنار راه شوسه ٔ خمین به اراک . این ده واقع در جلگه و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">١٧٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود و محصولات آن غلات، چغندرقند، پنبه و انگور و شغل مردمش زراعت است . صنایع دستی زنان قالی بافی است و راه شوسه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(179420, 'عاشقی', '<span class=\"hlight\">عاشقی .</span><font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (اِخ ) میرعلیشیر آرد: مولانا عاشقی از شهر هرات بود و قصیده را پخته میگفت از جمله اشعار اوست :<br />این منظری که طاق چو ابروی دلبر است <br />از خاک برگرفته ٔ دارای کشور است .<br />که در تعریف عمارت آق سرای که به دستور بوسعید بنا شده است سرود. (مجالس النفائس ص <span class=\"hlight\" dir=\"rtl\">٤١</span>).<br /></font></div>'),
(179421, 'عاشقی', '<span class=\"hlight\">عاشقی .</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (حامص ) عمل عاشق . شیفتگی . دلدادگی . عشق ورزیدن <span class=\"hlight\">:</span> <br />عاشقی پیداست از زاری دل <br />نیست بیماری چو بیماری دل .<br /> <font color=\"Red\">مولوی .</font><br />ز چشم خلق فتادم هنوز و ممکن نیست <br />که چشم شوخ من ازعاشقی حذر گیرد.<br /> <font color=\"Red\">سعدی .</font><br />نازپرورد تنعم نبرد راه به دوست <br />عاشقی شیوه ٔ رندان بلاکش باشد.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(179422, 'عاشقیت', '<span class=\"hlight\">عاشقیت .</span> <font color=\"DarkGreen\"><b>[ ش ِ قی ی َ ]</font></b> (ع مص جعلی ) عاشق شدن و اظهار دوستی و دلبستگی کردن . (ناظم الاطباء).<br /></font></div>'),
(179423, 'عاشم', '<span class=\"hlight\">عاشم .</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (ع اِ) یک نوع درخت است . (از ناظم الاطباء). و صاحب اقرب الموارد ذیل عُشُم آرد: درختی است، یکی آن عاشم و عَشِم . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) نام ریگ توده ای . (ناظم الاطباء).<br /></font></div>'),
(179424, 'عاشور', '<span class=\"hlight\">عاشور.</span> (اِخ ) بطنی است از شمر الطائیه . (معجم قبائل العرب ).<br /></font></div>'),
(179425, 'عاشور', '<span class=\"hlight\">عاشور.</span> (ع اِ) عاشور و عاشوراء و عاشوری و عشوری : دهم محرم و به قولی نهم آن و مشهور آن است که عاشوراء دهم و تاسوعاء نهم محرم است . (از اقرب الموارد). رجوع به عاشورا شود.<br /></font></div>'),
(179426, 'عاشورآباد', '<span class=\"hlight\">عاشورآباد.</span> (اِخ ) دهی است از دهستان دیلمان بخش سیاهکل دیلمان شهرستان لاهیجان واقع در <span class=\"hlight\" dir=\"rtl\">١١</span>هزارگزی خاور دیلمان نزدیک دیارجان . ناحیه ای است کوهستانی، سردسیر و <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه دارد. آب آن از چشمه سار و محصول آن غلات، حبوبات، پشم و لبنیات است و اهالی به کشاورزی و گله داری اشتغال دارند. راه آن مالرو است . اکثر سکنه در زمستان برای تأمین معاش به گیلان میروند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(179427, 'عاشورا', '<span class=\"hlight\">عاشورا.</span> (اِخ ) روز دهم محرم و آن روزی است که حسین بن علی (ع ) شهید شد. (غیاث اللغات )(التفهیم ص <span class=\"hlight\" dir=\"rtl\">٢٩١</span>). و رجوع به عاشور و عاشوراء شود.<br /></font></div>'),
(179428, 'عاشوروند', '<span class=\"hlight\">عاشوروند.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِخ ) تیره ای از طایفه ٔ کیومرسی ایل چهارلنگ بختیاری . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>).<br /></font></div>'),
(179429, 'عاشوری', '<span class=\"hlight\">عاشوری .</span> <font color=\"DarkGreen\"><b>[ را ]</font></b> (ع اِ) رجوع به عاشور و عاشورا و عاشوراء شود.<br /></font></div>'),
(179430, 'عاشوری', '<span class=\"hlight\">عاشوری .</span> (اِ) نام آشی که در کرمان و بعضی ولایات دیگر به نذر در روز عاشورا پزند و هر نوع حبوب در آن ریزند. (یادداشت مؤلف ).<br /></font></div>'),
(179431, 'عاشی', '<span class=\"hlight\">عاشی .</span> (ع ص ) رجل عاش ؛ مرد شبانگاه خورنده . <BR><font color=\"Blue\">◄</font> مرد آهنگ کننده . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> قاصد و یا قصدکننده . (از تاج العروس ).<br /></font></div>'),
(179432, 'عاشیة', '<span class=\"hlight\">عاشیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) شتر در شبانگاه چرنده . (منتهی الارب )(آنندراج ). شتر عشا خورنده . و در مثل است : العاشیة تهیج الاَّبیة، یعنی هر گاه ببیند کسی را که از خوردن غذای شب امتناع میورزد از او پیروی میکند و غذای شب را با وی میخورد. (از اقرب الموارد) (تاج العروس ).<br /></font></div>'),
(179433, 'عاص', '<span class=\"hlight\">عاص .</span> (اِخ ) ابن هشام . ابوالبختری عاص بن هشام بن خالد المخزومی از قریش و یکی از بزرگان و دلیران عرب جاهلیت و برادر ابوجهل است که اسلام را درک کرد و هم اوست که مردم را از گرویدن به حضرت رسول باز میداشت و سرانجام در جنگ بدر به سال دوم هجری به قتل رسید. (الاعلام زرکلی ).<br /></font></div>'),
(179434, 'عاص', '<span class=\"hlight\">عاص .</span> (اِخ ) ابن واثل سهمی پدر عمرو. (معجم قبائل العرب ).<br /></font></div>'),
(179435, 'عاص', '<span class=\"hlight\">عاص .</span> (اِخ ) ابن امیه . بطنی است از قریش عدنانیه معروف به ابی العاص . (معجم قبائل العرب ).<br /></font></div>'),
(179436, 'عاص', '<span class=\"hlight\">عاص .</span> (اِخ ) بطنی است از عمروبن مازن از غسان از عشام از ازد از قحطانیه . (معجم قبائل العرب ).<br /></font></div>'),
(179437, 'عاص', '<span class=\"hlight\">عاص .</span> (اِخ ) رودباری است در میان حرمین . (منتهی الارب ). و یاقوت آرد: عاص و عویص دو رودبارند میان مکه و مدینه . رجوع به معجم البلدان شود.<br /></font></div>'),
(179438, 'عاص', '<span class=\"hlight\">عاص .</span> <font color=\"DarkGreen\"><b>[ صِن ْ ]</font></b> (ع ص ) عاصی . نافرمان . (منتهی الارب ) (آنندراج ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(179439, 'عاصب', '<span class=\"hlight\">عاصب .</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (ع ص ) سخت گرسنه که از شدت آن سنگ بر کمر بسته باشد. <BR><font color=\"Blue\">◄</font> افق عاصب ؛ افق سرخ غبارناک . (منتهی الارب ).<br /></font></div>'),
(179440, 'عاصر', '<span class=\"hlight\">عاصر.</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (ع ص، اِ) عبارت است از داروئی که تناول آن باعث بیرون ساختن مواد فاسده از تجاویف و اندرون عضو گردد مانند اهلیلج . (قانون بوعلی ص <span class=\"hlight\" dir=\"rtl\">١٥٠</span>).<br /></font></div>'),
(179441, 'عاصر', '<span class=\"hlight\">عاصر.</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (ع ص ) فشارنده ٔ انگور و غیره . (المنجد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> رجل عاصر؛ مرد اندک خیر و ممسک . (المنجد) (اقرب الموارد). ج، عَصَرة و عاصرون . (اقرب الموارد).<br /></font></div>'),
(179442, 'عاصف', '<span class=\"hlight\">عاصف .</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (ع ص ) مایل و خمیده هر چه باشد. سهم عاصف ؛ تیر کج و مائل از نشانه . <BR><font color=\"Blue\">◄</font> سخت : ریح عاصف ؛ باد سخت . یوم عاصف ؛ روز باد تند.ج، عواصف . (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(179443, 'عاصفة', '<span class=\"hlight\">عاصفة.</span> <font color=\"DarkGreen\"><b>[ ص ِ ف َ ]</font></b> (ع ص ) مؤنث عاصف : ریح عاصفة؛ باد سخت . لیل عاصفة؛ شب با باد سخت تند. ج، عاصفات و عواصف . (ناظم الاطباء) (المنجد) (منتهی الارب ) (غیاث اللغات ). رجوع به عاصف شود.<br /></font></div>'),
(179444, 'عاصم', '<span class=\"hlight\">عاصم .</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (اِخ ) شهری است در جنوب یهودا و بعد از تقسیم اول به سبط یهودا داده شد. (قاموس کتاب مقدس ).<br /></font></div>'),
(179445, 'عاصم', '<span class=\"hlight\">عاصم .</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (ع ص ) بازدارنده . (غیاث اللغات ). منعکننده . (از اقرب الموارد). نگاه دارنده . (غیاث اللغات ) (آنندراج ). حفظکننده . (از اقرب الموارد) <span class=\"hlight\">:</span> <br />گفت من رفتم بر آن کوه بلند<br />عاصم است آن که مرا از هر گزند.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(179446, 'عاصم', '<span class=\"hlight\">عاصم .</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (اِخ ) موضعی است به بلاد هذیل . (معجم البلدان ) (منتهی الارب ).<br /></font></div>'),
(179447, 'عاصم', '<span class=\"hlight\">عاصم .</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (اِخ ) نام دو وادی است از وادیهای عقیق . (منتهی الارب ).<br /></font></div>'),
(179448, 'عاصم', '<span class=\"hlight\">عاصم .</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (اِخ ) ابن ایوب، مکنی به ابوبکر. نحوی . وی یکی از علماء و لغویان بود و او را آثاری است از جمله : شرح معلقات و شرح دیوان امروءالقیس .وی به سال <span class=\"hlight\" dir=\"rtl\">١٦٤</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(179449, 'عاصم', '<span class=\"hlight\">عاصم .</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (اِخ ) ابن بهدلة الکوفی الاسدی . کنیه ٔ او ابوبکر و یکی از قراء سبعه بود و به سال <span class=\"hlight\" dir=\"rtl\">١٢٨</span> هَ . ق . درگذشت . او شاگرد ابوعبدالرحمان السلمی و زراربن حبیش بود. (الاعلام زرکلی ).<br /></font></div>'),
(179450, 'عاصم', '<span class=\"hlight\">عاصم .</span><font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (اِخ ) ابن ثابت . تابعی است . (منتهی الارب ).<br /></font></div>'),
(179451, 'عاصم', '<span class=\"hlight\">عاصم .</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (اِخ ) ابن خلیفةبن معفل الضبی . یکی از سواران عرب جاهلی و از شعرای مخضرمین بود. وی اسلام را درک کرد و در بصره ساکن بود و به سال <span class=\"hlight\" dir=\"rtl\">٣٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(179452, 'عاصم', '<span class=\"hlight\">عاصم .</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (اِخ )ابن سلیمان الاحول البصری . یکی از محدثان و معتمدان بصره بود. وی در کوفه عمل حسبه و در مدائن منصب قضا داشت و به سال <span class=\"hlight\" dir=\"rtl\">١٤٢</span> هَ . ق . درگذشت . (الاعلام زرکلی ).<br /></font></div>'),
(179453, 'عاصم', '<span class=\"hlight\">عاصم .</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (اِخ ) ابن عدی عجلانی . از بزرگان بنی عجلان و از صحابه بود و حضرت رسول خلافت خویش را در مدینه به وی داد. او به سال <span class=\"hlight\" dir=\"rtl\">٤٥</span> هَ . ق . درگذشت . (الاعلام زرکلی ). و رجوع به امتاع الاسماع ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٩٤</span>، <span class=\"hlight\" dir=\"rtl\">٤٤٧</span>، <span class=\"hlight\" dir=\"rtl\">٤٨١</span> شود.<br /></font></div>'),
(179454, 'عاصم', '<span class=\"hlight\">عاصم .</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (اِخ ) ابن علی بن عاصم بن صهیب التیمی . یکی از حافظان حدیث و از ثقات بود. وی مردم را حدیث میکرد و در مجلس او هزار تن حاضر میشد و به سال <span class=\"hlight\" dir=\"rtl\">٢٢١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(179455, 'عاصم', '<span class=\"hlight\">عاصم .</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (اِخ )ابن عمربن الخطاب القرشی العدوی . جد عمربن عبدالعزیز و از شعراست . و به سال <span class=\"hlight\" dir=\"rtl\">٧٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ). و رجوع به امتاع الاسماع ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٨</span> شود.<br /></font></div>'),
(179456, 'عاصم', '<span class=\"hlight\">عاصم .</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (اِخ ) ابن عمیرالسعدی . وی از شجاعان عرب است که شاهد وقایع ماوراءالنهر با نصربن سیار بود و به سال <span class=\"hlight\" dir=\"rtl\">١٣١</span> هَ . ق . در نهاوند کشته شد. (از الاعلام زرکلی ).<br /></font></div>'),
(179457, 'عاصم افندی', '<span class=\"hlight\">عاصم افندی .</span> <font color=\"DarkGreen\"><b>[ ص ِ اَ ف َ ]</font></b> (اِخ ) ابوالکمال احمد. از مشاهیر علما و مؤلفان قرن سیزدهم هجری است . وی در ادبیات و لغات عربی و فارسی و ترکی بصیرتی داشت و در اسلامبول تدریس میکرد: از آثار اوست : الاقیانوس البسیط در ترجمه ٔقاموس المحیط. (ترجمه ٔ قاموس اللغه ٔ فیروزآبادی به ترکی ) - ترجمه ٔ برهان قاطع به ترکی - وقایع سلیمة. وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٣٥</span> هَ . ق .<span class=\"hlight\" dir=\"rtl\">١٨١٩/</span> م . در اسلامبول درگذشت . (از ریحانة الادب ). و رجوع به قاموس الاعلام ترکی شود.<br /></font></div>'),
(179458, 'عاصمة', '<span class=\"hlight\">عاصمة.</span> <font color=\"DarkGreen\"><b>[ ص ِ م َ ]</font></b> (اِخ ) لقب مدینه است . (منتهی الارب ) (آنندراج ) (اقرب الموارد).<br /></font></div>'),
(179459, 'عاصمة', '<span class=\"hlight\">عاصمة.</span> <font color=\"DarkGreen\"><b>[ ص ِ م َ ]</font></b> (ع اِ) ام بلاد. قاعده ٔ کشور. (اقرب الموارد). در تداول کشورهای عربی پایتخت .<br /></font></div>'),
(179460, 'عاصمی', '<span class=\"hlight\">عاصمی .</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (اِخ ) احمدبن محمدبن عاصم بن عبداﷲ.اصل او از کوفه و مسکن وی بغداد بود. از ثقات و معتمدان محدثان امامیه و خواهرزاده یا برادرزاده ٔ علی بن عاصم محدث و استاد کلینی است . (ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>). و رجوع به امل الاَّمل و هدیة الاحباب ص <span class=\"hlight\" dir=\"rtl\">١٩٧</span> شود.<br /></font></div>'),
(179461, 'عاصمی', '<span class=\"hlight\">عاصمی .</span> <font color=\"DarkGreen\"><b>[ ص ِ ]</font></b> (اِخ ) مولانا عاصمی . یکی از ادباء و شعراء است و از جمله اشعار اوست :<br />چون آتشم ز هجر تو بر سر زند علم <br />سازم روان چو شمع ز گرداب دیده نم .<br /><font color=\"Red\">(مجالس النفائس ص <span class=\"hlight\" dir=\"rtl\">٧٨</span>).</font><br /></font></div>'),
(179462, 'عاصمیة', '<span class=\"hlight\">عاصمیة.</span> <font color=\"DarkGreen\"><b>[ ص ِ می ی َ ]</font></b> (اِخ ) نام دهی است نزدیک رأس عین اطراف خانور. (معجم البلدان ص <span class=\"hlight\" dir=\"rtl\">٩٦</span>).<br /></font></div>'),
(179463, 'عاصی', '<span class=\"hlight\">عاصی .</span> (اِخ ) نام نهر حماة و حمص است معروف به میماس که از دریاچه ٔ قدس سرچشمه میگیرد و به دریاچه ٔ انطاکیه میریزد. (از معجم البلدان ص <span class=\"hlight\" dir=\"rtl\">٩٦</span>).<br /></font></div>'),
(179464, 'عاصی', '<span class=\"hlight\">عاصی .</span> (اِخ ) شیخ محمد حسن بن شیخ محمد رفیع رشتی اصفهانی، متخلص به عاصی . از دانشمندان قرن سیزدهم هجری بود و از آثار اوست : جامع المصائب و وسیلة النجاة. (ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>). و رجوع به الذریعه ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٧٠</span> شود.<br /></font></div>'),
(179465, 'عاصی', '<span class=\"hlight\">عاصی .</span> (ع ص ) گناهکار و نافرمان . ج، عُصاة. (آنندراج ) (غیاث اللغات ) <span class=\"hlight\">:</span> <br />بدانسته بودم همه پیش ازین <br />که عاصی بخواهد شد او همچنین .<br /> <font color=\"Red\">فردوسی .</font><br />چون کند سی ساله عاصی را عذاب جاودان <br />این چنین حکم و قضای ایزد دادار نیست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />عاصیان از گناه توبه کنند<br />عارفان از عبادت استغفار.<br /> <font color=\"Red\">سعدی (گلستان ).</font><br />عاصی که دست بخدا بردارد به از عابدی که کبر در سر دارد. (گلستان ).<br /><BR><font color=\"Blue\">◄</font> (اِ) رگی که خون آن نایستد. (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> کره شتر که دنبال مادر خود نرود و از او بی نیاز باشد. ج، عَواصی . (اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> در اصطلاح اطباء معده ای که اثر مسهل نپذیرد. <BR><font color=\"Blue\">◄</font> ابر سیاه که بارش نکند. (از غیاث اللغات ).<br /></font></div>'),
(179466, 'عاصی شدن', '<span class=\"hlight\">عاصی شدن .</span> <font color=\"DarkGreen\"><b>[ ش ُدَ ]</font></b> (مص مرکب ) عصیان کردن . طغیان ورزیدن . تمرد کردن . متمرد شدن . گناه کردن . نافرمانی کردن . (ناظم الاطباء) <span class=\"hlight\">:</span> چون سلیمان برفت از دنیا وی را پسری بود... خلق به وی عاصی شدند. (قصص الانبیاء ص <span class=\"hlight\" dir=\"rtl\">١٧٨</span>).<br /></font></div>'),
(179467, 'عاض', '<span class=\"hlight\">عاض .</span> <font color=\"DarkGreen\"><b>[ عاض ض ]</font></b> (ع ص ) با دندان گزنده . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> شتری که خار خورد. (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(179468, 'عاضد', '<span class=\"hlight\">عاضد.</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ع ص ) یاری کننده . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> به جانب ستور رونده . <BR><font color=\"Blue\">◄</font> شتر که بازوی ناقه گیرد و بخواباند. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> خر که مادیان را از اطراف و جوانب فراهم آرد. (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> سهم عاضد؛ تیری که بطرف راست یا چپ نشانه افتد. (ناظم الاطباء).<br /></font></div>'),
(179469, 'عاضد', '<span class=\"hlight\">عاضد.</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (اِخ ) (الَ ...) الدین اﷲ، محمدبن الفائزبنصراﷲ، مکنی به ابوعبداﷲ. وی آخرین خلیفه ٔ علوی اسماعیلیه بود و به سال <span class=\"hlight\" dir=\"rtl\">٥٤٦</span> هَ . ق . متولد شد و بعد ازوفات فائز پسر عم خود به کمک و معاونت ارکان دولت به مرتبت خلافت رسید و در حکومت او کفار فرنگ عازم تسخیر مصر شدند و مسلمانان را وحشتی عظیم فراگرفت و به صلح راضی گشتند و مقرر شد که مبلغ هزارهزار دینار به فرنگان دهند تا باز گردند. مسلمانان را گران آمد و اتفاق نمودند که به نورالدین محمودبن عمادالدین زنگی والی شام توسل جویند و شاپور وزیری نامه ای بنورالدین نوشت و از او کمک خواست . نورالدین اسدالدین شیرکوه را با هشتاد هزار سوار بدان سو فرستاد و فرنگان بازگردیدند. عاضد به جود و کرم معروف و به مکارم و محاسن اخلاق مشهور بود و به سال <span class=\"hlight\" dir=\"rtl\">٥٦٧</span> هَ . ق . درگذشت . (ازوفیات الاعیان چ تهران ج <span class=\"hlight\" dir=\"rtl\">١</span> س <span class=\"hlight\" dir=\"rtl\">٢٩٢</span>). و رجوع به حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">٤٥٩</span> - <span class=\"hlight\" dir=\"rtl\">٤٦٠</span> و ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٩</span> شود.<br /></font></div>'),
(179470, 'عاضدان', '<span class=\"hlight\">عاضدان .</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ع اِ) دو رشته ٔ خرمابن بر دو لب جوی . (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(179471, 'عاضر', '<span class=\"hlight\">عاضر.</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (ع ص ) بازدارنده و مانع. (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(179472, 'عاضه', '<span class=\"hlight\">عاضه .</span> <font color=\"DarkGreen\"><b>[ ض ِه ْ ]</font></b> (ع ص ) شتر عضاه خوار. ج، عَواضه ؛ بعیر عاضه و ناقة عاضه و عاضهة و حیة عاضه و عاضهة. (ناظم الاطباء) (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مار که گزیده اش در حال بمیرد.(منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> جادوگر. (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(179473, 'عاضهة', '<span class=\"hlight\">عاضهة.</span> <font color=\"DarkGreen\"><b>[ ض ِ هََ ]</font></b> (ع ص ) مؤنث عاضه . رجوع به عاضه شود.<br /></font></div>'),
(179474, 'عاضی', '<span class=\"hlight\">عاضی .</span> (ع ص ) مرد نیک مرفه الحال . (ناظم الاطباء).<br /></font></div>'),
(179475, 'عاطر', '<span class=\"hlight\">عاطر.</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص ) دوست دارنده ٔ عطر. عطردوست . (اقرب الموارد) (آنندراج ) (ناظم الاطباء). ج، عُطُر. <BR><font color=\"Blue\">◄</font> بوی خوش دهنده . بوی خوش دارنده . (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> <br />من که باشم که بر آن خاطر عاطر گذرم <br />لطفها میکنی ای خاک درت تاج سرم .<br /> <font color=\"Red\">حافظ.</font><br />و از خاطر عاطر اصحاب فضل و هنر استمداد همت نمود. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(179476, 'عاطس', '<span class=\"hlight\">عاطس .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص ) عطسه دهنده . <BR><font color=\"Blue\">◄</font> آهوئی که پیش آید ترا. <BR><font color=\"Blue\">◄</font> (اِ) صبح . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179477, 'عاطش', '<span class=\"hlight\">عاطش .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص ) آنکه تشنه بود. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179478, 'عاطف', '<span class=\"hlight\">عاطف .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص ) مهربانی کننده . <BR><font color=\"Blue\">◄</font> برگرداننده . (غیاث اللغات ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آهو که گردن کج کند وقت نشستن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) چادر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اسب ششم رهان . از جمله ده اسب که بدان گروبسته دوانند. (از غیاث اللغات ) (از مهذب الاسماء).<br /></font></div>'),
(179479, 'عاطفة', '<span class=\"hlight\">عاطفة.</span> <font color=\"DarkGreen\"><b>[ طِ ف َ ]</font></b> (ع ص ) (حروف ...) در عربی ده حرف است که مابین دو جمله یا کلمه واقعشده و جمله یا کلمه ٔ بعد از خود را به ماقبل خود ربط دهد. جمله یا کلمه ای که بعد از حروف عاطفه است معطوف و جمله و یا کلمه ٔ ماقبل را معطوف ٌ علیه نامند. وآن حروف عبارتند از: و، ف، أم، أما، أو، بل، ثم، حتی، لا، لکن . رجوع به حروف عاطفه و حروف ربط شود.<br /></font></div>'),
(179480, 'عاطفة', '<span class=\"hlight\">عاطفة.</span> <font color=\"DarkGreen\"><b>[ طِ ف َ ]</font></b> (ع اِمص ) عاطفه . عاطفت . مهر. <BR><font color=\"Blue\">◄</font> خویشی و قرابت . (منتهی الارب ). رجوع به عاطفت شود.<br /></font></div>'),
(179481, 'عاطفت', '<span class=\"hlight\">عاطفت .</span> <font color=\"DarkGreen\"><b>[ طِ ف َ ]</font></b> (ع اِمص ) عاطفة.عاطفه . مهربانی . مهر <span class=\"hlight\">:</span> پادشاه باید خدمتگذاران را از عاطفت و کرامت خویش چندان محروم نگرداند که بیکبارگی برمند و نومید گردند. (کلیله و دمنه ).<br />یکی عاطفت سیرت خویش کرد<br />درم داد و تیمار درویش کرد.<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />و رجوع به عاطفه شود.<br /></font></div>'),
(179482, 'عاطل', '<span class=\"hlight\">عاطل .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص ) بیکاره . بیهوده . تهی . فارغ <span class=\"hlight\">:</span> آن دیگر که از پیرایه ٔ خردی عاطل نبود. (کلیله و دمنه ). چون سریر دولت از منصب شاهی خالی و عاطل ماند... دشمن قصد این دیار کند. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٨٠</span>). <BR><font color=\"Blue\">◄</font> زن بی گردن بند. بی زیور. بی پیرایه . (مهذب الاسماء) (آنندراج ). ج، عَواطل و عُطَّل . (ناظم الاطباء).<br /></font></div>'),
(179483, 'عاطم', '<span class=\"hlight\">عاطم .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b>(ع ص ) هلاک شده . ج، عُطُم . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179484, 'عاطن', '<span class=\"hlight\">عاطن .</span> <font color=\"DarkGreen\"><b>[ طِ ]</font></b> (ع ص ) شتران سیراب فروخفته در خوابگاه . ج، عَواطن . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(179485, 'عاطنة', '<span class=\"hlight\">عاطنة.</span> <font color=\"DarkGreen\"><b>[ طِ ن َ ]</font></b> (اِخ ) لنگرگاهی است در بحر یمن . (منتهی الارب ).<br /></font></div>'),
(179486, 'عاطنة', '<span class=\"hlight\">عاطنة.</span> <font color=\"DarkGreen\"><b>[ طِ ن َ]</font></b> (ع ص ) مؤنث عاطن . شتران سیراب فروخفته در خوابگاه . (اقرب الموارد) (آنندراج ). و رجوع به عاطن شود.<br /></font></div>'),
(179487, 'عاطوس', '<span class=\"hlight\">عاطوس .</span> (ع اِ) آنچه بدان عطسه دهند. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> جانوری است که بدان فال بد گیرند. (منتهی الارب ).<br /></font></div>'),
(179488, 'عاطوف', '<span class=\"hlight\">عاطوف .</span> (ع اِ) مصیدة که چوب کج داشته باشد. (منتهی الارب ).<br /></font></div>'),
(179489, 'عاطی', '<span class=\"hlight\">عاطی .</span> (ع ص ) گیرنده . و در مثل است که عاط بغیر أنواط؛ أی یتناول ما لامطمع فیه و لامتناول ؛ یعنی کاری میکند که فائده ندارد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179490, 'عاظب', '<span class=\"hlight\">عاظب .</span> <font color=\"DarkGreen\"><b>[ ظِ ]</font></b> (ع ص ) عَظِب . در جای خشک فرو آینده . (منتهی الارب ) (آنندراج ). و رجوع به عظب شود.<br /></font></div>'),
(179491, 'عاظل', '<span class=\"hlight\">عاظل .</span> <font color=\"DarkGreen\"><b>[ ظِ ]</font></b> (ع ص ) جراد عاظل ؛ ملخ دو سه بر هم نشسته . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179492, 'عاف', '<span class=\"hlight\">عاف .</span> (ع ص ) (از: ع وف ) سهل و نرم . (منتهی الارب ).<br /></font></div>'),
(179493, 'عافط', '<span class=\"hlight\">عافط.</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (ع ص ) رجل عافط؛ مرد گوززن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179494, 'عافق', '<span class=\"hlight\">عافق .</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (ع ص ) کل راجع مختلف کثیر التردد. (اقرب الموارد). بسیار آمد و شد کننده . و هر وارد و صادر و راجع مختلف . هر طرف آمد و رفت نماینده . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179495, 'عافل', '<span class=\"hlight\">عافل .</span> <font color=\"DarkGreen\"><b>[ ف ِ ]</font></b> (ع ص ) آنکه جامه ٔ کوتاه بر جامه ٔ دراز پوشد. (منتهی الارب ).<br /></font></div>'),
(179496, 'عافور', '<span class=\"hlight\">عافور.</span> (ع اِ) وقع فی عافور شر و عاثوره ؛ یعنی در بدی و جای هلاک و سختی افتاد. (منتهی الارب ) (آنندراج ). لغتی است در عاثور. (از اقرب الموارد). و رجوع به عاثور شود.<br /></font></div>'),
(179497, 'عافون', '<span class=\"hlight\">عافون .</span> (ع ص، اِ) ج ِ عافی (در حالت رفع). رجوع به عافی شود.<br /></font></div>'),
(179498, 'عافی', '<span class=\"hlight\">عافی .</span> (ع ص ) عفوکننده . (اقرب الموارد). بخشنده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> رائد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خواهنده ٔ رزق و فضل و غیره . (منتهی الارب ) (اقرب الموارد) (ناظم الاطباء). طالب معروف و احسان . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> ناپدید و نیست و مندرس کننده . (منتهی الارب ) (ناظم الاطباء) (آنندراج ). <BR><font color=\"Blue\">◄</font> وارد. فرودآینده . <BR><font color=\"Blue\">◄</font> درازموی . (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) مهمان . (اقرب الموارد) (منتهی الارب ). شوربای در دیگ عاریتی باز انداخته . (منتهی الارب ) (آنندراج ) (ناظم الاطباء). آنچه در دیگ عاریتی بجا گذارند از مرق و آن اجرت گونه بود دیگ عاریتی را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> باقی طعام در دیگ . (منتهی الارب ) (آنندراج ). ج، عُفاة و عفی و عافیة. (اقرب الموارد).<br /></font></div>'),
(179499, 'عافیات', '<span class=\"hlight\">عافیات .</span> (ع اِ) ج ِ عافیة. (ناظم الاطباء). رجوع به عافیة شود.<br /></font></div>'),
(179500, 'عافیة', '<span class=\"hlight\">عافیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع اِمص ) عافیت . صحت کامل . بهبود کامل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> دور کردن خدای از بنده مکروه را. سلامت از بیماری و مکروهات در بدن و باطن دردین و دنیا و آخرت . <BR><font color=\"Blue\">◄</font> (ص ) خواهنده ٔ رزق از طیور و سباع و جز آن . ج، عَوافی . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عافیة الماء</span> ؛ در آب آینده . (منتهی الارب ) (از اقرب الموارد).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کثیرالعافیة</span> ؛ بسیارمهمان . (منتهی الارب ) (اقرب الموارد). و رجوع به عافیت شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ناقة عافیة اللحم </span> ؛ ناقه ٔ بسیارگوشت . (منتهی الارب ). ج، عافیات و عَوافی . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(179501, 'عافیت', '<span class=\"hlight\">عافیت .</span> <font color=\"DarkGreen\"><b>[ ی َ]</font></b> (ع اِمص ) عافیة. صحت . سلامت . تندرستی <span class=\"hlight\">:</span> <br />توبه سگالی که نیز باز نگردی <br />سوی بلا گرت عافیت دهد این بار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />عافیت را نشان نمی یابم <br />از بلاها امان نمی یابم .<br /> <font color=\"Red\">خاقانی .</font><br />از عافیت مپرس که کس را نداده اند<br />در عاریت سرای جهان عافیت عطا.<br /> <font color=\"Red\">خاقانی .</font><br />همچنین قدر عافیت کسی داندکه به مصیبتی گرفتار آید. (گلستان ). و رجوع به عافیة شود. <BR><font color=\"Blue\">◄</font> پارسایی . زهد. (آنندراج ) <span class=\"hlight\">:</span> <br />آنان که به کنج عافیت بنشستند<br />دندان سگ و دهان مردم بستند.<br /> <font color=\"Red\">سعدی (گلستان ).</font><br />عافیت چشم مدار از من میخانه نشین <br />که دم از خدمت رندان زده ام تاهستم .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(179502, 'عافیت خواهی', '<span class=\"hlight\">عافیت خواهی .</span> <font color=\"DarkGreen\"><b>[ ی َ خوا <span class=\"hlight\" dir=\"rtl\">/</span>خا ]</font></b> (حامص مرکب ) سلامت خواهی . سلامت طلبی <span class=\"hlight\">:</span> <br />شه چو از فتنه یافت آگاهی <br />در بلا دید عافیت خواهی .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(179503, 'عافیت گاه', '<span class=\"hlight\">عافیت گاه .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِ مرکب ) جای امن . جای سلامت . مأمن . محل عافیت و سلامت <span class=\"hlight\">:</span> <br />پس ز هر منزلی وهر راهی <br />باز می جست عافیت گاهی .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(179504, 'عافین', '<span class=\"hlight\">عافین .</span> (ع ص، اِ) ج ِ عافی (در حال نصبی و جری ). درگذرندگان از تقصیرات : و الکاظمین الغیظ و العافین عن الناس . (قرآن <span class=\"hlight\" dir=\"rtl\">١٣٤/٣</span>).<br /></font></div>'),
(179505, 'عاق', '<span class=\"hlight\">عاق .</span> <font color=\"DarkGreen\"><b>[ عاق ق ]</font></b> (ع ص ) ناخوش دارنده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آزاردهنده ٔ پدر و مادر و نافرمان . (منتهی الارب ) (آنندراج ). سرکش با مادر و پدر. (غیاث اللغات ). ج، عاقون و عَقَقه و اَعقّه و این نادر است . (از اقرب الموارد) <span class=\"hlight\">:</span> <br />فرزند عاق ریش پدر گیرد ابتدا<br />فحل نبهره دست به مادر برد نخست .<br /> <font color=\"Red\">خاقانی .</font><br />همان مقامات پیش آمد که آن گازر را از پسر ناخلف و فرزند عاق پیش آمد. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">١١٣</span>).<br />رنگ کفران و شک و شرک و نفاق <br />تا ابد باقی بود بر جان عاق .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(179506, 'عاق عاق', '<span class=\"hlight\">عاق عاق .</span> (ع اِ صوت مرکب ) حکایت آواز زاغ . (منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(179507, 'عاقب', '<span class=\"hlight\">عاقب .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (ع ص، اِ) نائب مهتر و قائم مقام آن بعد از وی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نائب و خلیفه ٔ پیشینیان در امر نیکو، و منه قول النبی (ص ) و أنا العاقب ؛ أی آخر الانبیاء. کسی که جانشین بزرگی شود و رتبت او بعد از آن است، و منه جاءالسید و العاقب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) هر چیز که جانشین شی ٔ پیشین خود شود. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شتر ماده که بقیه ٔ گیاه خورد. (ناظم الاطباء) (منتهی الارب ).<br /></font></div>'),
(179508, 'عاقب', '<span class=\"hlight\">عاقب .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) واپسین پیغامبران یعنی محمد (ص ). (مهذب الاسماء). نام پیغمبر مسلمانان . (اقرب الموارد).<br /></font></div>'),
(179509, 'عاقبة', '<span class=\"hlight\">عاقبة.</span><font color=\"DarkGreen\"><b>[ ق ِ ب َ ]</font></b> (ع اِ) پایان هر چیزی <span class=\"hlight\">:</span> و ﷲ عاقبة الامور. (قرآن <span class=\"hlight\" dir=\"rtl\">٤١/٢٢</span>). رجوع به عاقبت شود. <BR><font color=\"Blue\">◄</font> فرزند، یقال لیس له عاقبة؛ أی ولد. (منتهی الارب ). نسل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> تأمل در آخر کاری . (منتهی الارب ). ج، عَواقب . (اقرب الموارد).<br /></font></div>'),
(179510, 'عاقبت', '<span class=\"hlight\">عاقبت .</span> <font color=\"DarkGreen\"><b>[ ق ِ ب َ]</font></b> (ع اِ) عاقبة. پایان هر چیزی . (منتهی الارب ) (اقرب الموارد). فرجام . سرانجام <span class=\"hlight\">:</span> وی هشیار بود و سوی عاقبت نیکو نگاه کردی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٥٧</span>).<br />بد نسگالد به خلق بد نبود هرگزش <br />وانکه بدی کرد هست عاقبتش بر ندم .<br /> <font color=\"Red\">منوچهری .</font><br />و اگر در عاقبت کارها و هجرت سوی گور فکرت شافی واجب داری . (کلیله و دمنه ).<br />عاقبتی هست بیا پیش از آن <br />کرده ٔ خود بین و بیندیش از آن .<br /> <font color=\"Red\">نظامی .</font><br />یارب از لطف و کرم عاقبت خاقانی <br />خیر گردان تو که ما در طلبش خواب و خوریم .<br /> <font color=\"Red\">خاقانی .</font><br />که از چنگال گرگم در ربودی <br />چو دیدم عاقبت گرگم تو بودی .<br /> <font color=\"Red\">سعدی (گلستان ).</font><br />گفت پیغمبر که چون کوبی دری <br />عاقبت زان در برون آید سری .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(179511, 'عاقبت اندیش', '<span class=\"hlight\">عاقبت اندیش .</span> <font color=\"DarkGreen\"><b>[ ق ِ ب َ اَ ]</font></b> (نف مرکب ) دوراندیش . (آنندراج ) (ناظم الاطباء). آخربین . مآل اندیش . آنکه از آغاز، پایان کار را نگرد <span class=\"hlight\">:</span> <br />بباید عاقبت اندیش بودن <br />برون از خویش و هم با خویش بودن .<br /> <font color=\"Red\">ناصرخسرو.</font><br />عاقبت اندیش ترین کودکی <br />دشمن او بود در ایشان یکی .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(179512, 'عاقبت اندیشی', '<span class=\"hlight\">عاقبت اندیشی .</span> <font color=\"DarkGreen\"><b>[ ق ِ ب َ اَ ]</font></b> (حامص مرکب ) دوراندیشی .<br /></font></div>'),
(179513, 'عاقبت بخیر', '<span class=\"hlight\">عاقبت بخیر.</span> <font color=\"DarkGreen\"><b>[ ق ِ ب َ ب ِ خ َ <span class=\"hlight\" dir=\"rtl\">/</span> خ ِ ]</font></b> (ص مرکب ) آنکه پایان کار یا زندگی او بخوبی انجامد. آنکه عاقبت حال یا کار او به خیر ختم شود. در تداول است : او عاقبت بخیر مرد.<br /></font></div>'),
(179514, 'عاقبت بین', '<span class=\"hlight\">عاقبت بین .</span> <font color=\"DarkGreen\"><b>[ ق ِ ب َ ]</font></b> (نف مرکب ) دوربین و کسی که عاقبت و سرانجام هر کاری را نگاه کند. (ناظم الاطباء). عاقبت اندیش . رجوع به عاقبت اندیش شود.<br /></font></div>'),
(179515, 'عاقبت بینی', '<span class=\"hlight\">عاقبت بینی .</span> <font color=\"DarkGreen\"><b>[ ق ِ ب َ ]</font></b> (حامص مرکب ) رجوع به عاقبت بین شود.<br /></font></div>'),
(179516, 'عاقبت نگر', '<span class=\"hlight\">عاقبت نگر.</span> <font color=\"DarkGreen\"><b>[ ق ِ ب َ ن ِ گ َ ]</font></b> (نف مرکب ) عاقبت اندیش . آنکه پایان کار را نگرد. عاقبت بین <span class=\"hlight\">:</span> بونصر مردی بود عاقبت نگر. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٧٦</span>).<br /></font></div>'),
(179517, 'عاقد', '<span class=\"hlight\">عاقد.</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (ع ص ) عقدکننده . <BR><font color=\"Blue\">◄</font> گره زننده . (غیاث اللغات ). استوارکننده . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> جاء عاقداً عنقه ؛ آمد خم کننده گردن خود را از روی تکبر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> در اصطلاح فقها، اجراکننده ٔ صیغه در معامله . <BR><font color=\"Blue\">◄</font> کسی که عقد نکاح بندد. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آهوی گردن کج کرده یا گردن بر سرین نهاده . (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناقه ای که گره کند دم خود را و آن علامت آبستنی است از وی . (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br /></font></div>'),
(179518, 'عاقر', '<span class=\"hlight\">عاقر.</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (ع ص ) نحرکننده ٔ شتر و کسی که دست و پای شتر با شمشیر زند. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> زن که آبستن نشود. (منتهی الارب ) (آنندراج ) (اقرب الموارد). زن که نمیزاید <span class=\"hlight\">:</span> و کانت امرأتی عاقراً. (قرآن <span class=\"hlight\" dir=\"rtl\">٥/١٩</span>). ج، عُقّر و عَواقر. <BR><font color=\"Blue\">◄</font> مرد که او را فرزند نشود. <BR><font color=\"Blue\">◄</font> قاتل : و صمم اًذا أیقنت َ أنک عاقره ؛ أی قاتله . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ریگ که هیچ نرویاند. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ریگ توده . (ناظم الاطباء) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زن بی نظیر و عدیل . (منتهی الارب ) (اقرب الموارد) (مهذب الاسماء).<br /></font></div>'),
(179519, 'عاقر', '<span class=\"hlight\">عاقر.</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) ریگزاری است در منازل جریرالشاعر، و بعضی گویند عاقر ریگ های بزرگ را گویند. (معجم البلدان ).<br /></font></div>'),
(179520, 'عاقرالثریا', '<span class=\"hlight\">عاقرالثریا.</span> <font color=\"DarkGreen\"><b>[ ق ِ رُث ْ ث ُ رَی ْ یا ]</font></b> (اِخ ) کوهی است . (معجم البلدان ).<br /></font></div>'),
(179521, 'عاقرالنجبة', '<span class=\"hlight\">عاقرالنجبة.</span> <font color=\"DarkGreen\"><b>[ ق ِ رُن ْن ُ ب َ ]</font></b> (اِخ ) کوهی است سلول را. (معجم البلدان ).<br /></font></div>'),
(179522, 'عاقرقرحا', '<span class=\"hlight\">عاقرقرحا.</span> <font color=\"DarkGreen\"><b>[ ق ِ ق َ ]</font></b> (معرب، اِ) نباتی است که در دمشق عود القرح خوانند و به یونانی فوریون و به شیرازی اکر. و نیکوترین او آن بود که تیز و محرق بود و زبان را به غایت بسوزاند و فربه بود و طاهر و غلیظ و چون بشکند اندرون وی سپید بود و آن بیخ طرخون رومی است و گویند جبلی است و طبیعت آن گرم و خشک بود در سیم و چون سحق کنند و با زیت بر بدن مسح کنند عرق براند و استرخاء اعضاء و مزاج رانافع بود و منع تولد کزاز بکند و سده مصفاة بگشاید و بلغم که در معده بود زائل کند و چون در دندان گیرند درد دندان که از سردی بود ساکن گرداند و چون با سرکه پزند و بدان مضمضه کنند سودمند بود جهت درد دندان و موافق اعضائی بود که سردی بر وی غلبه کرده باشد وحس آن باطل شده باشد از حرکت و مفلوج و مصروع را نافع بود. (از اختیارات بدیعی ). بیخ طرخون را عاقرقرحاگویند و باز در صیدنه است که ارجانی گوید: عاقرقرحاگرم و خشک است در سه درجه و درد دندان را که ماده ٔ آن از سردی بود رفع کند و دمیدگی دهان را سود دارد چون از رطوبت باشد و اگر با زیت سوده شود و پیش از نوبت بر اندامها مالیده آید لرزه را که در تبهاء نوبت باشد دفع کند. (از ترجمه ٔ صیدنه ٔ ابوریحان ). و آن مقوی باه مبرد و مسهل است . و رجوع به نزهة القلوب و غیاث اللغات و تحفه ٔ حکیم مؤمن و اقرب الموارد شود.<br /></font></div>'),
(179523, 'عاقرقوفا', '<span class=\"hlight\">عاقرقوفا.</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) مرکب است از عاقر و قوفا. یاقوت گوید: من گمان میکنم که این موضع همان عقرقوف است و از دهات سیلحین به بغداد است و آن تل بزرگی است که از مسافت یکروز دیده میشود لکن دیگران گویند تل ریگ بزرگ متراکم است . (معجم البلدان ).<br /></font></div>'),
(179524, 'عاقف', '<span class=\"hlight\">عاقف .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (ع ص ) شاة عاقف ؛ گوسپند عقاف زده که او را مرض عُقاف باشد. (منتهی الارب ) (آنندراج ) (اقرب الموارد).<br /></font></div>'),
(179525, 'عاقل', '<span class=\"hlight\">عاقل .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (ع ص )خردمند. دانا. هوشیار و زیرک . (ناظم الاطباء). ج، عقلاء و عُقّال و عاقلون . (منتهی الارب ) (مهذب الاسماء) (آنندراج ) (اقرب الموارد). مقابل دیوانه <span class=\"hlight\">:</span> <br />حکیمان زمانه راست گفتند<br />که جاهل گردد اندر عشق عاقل .<br /> <font color=\"Red\">منوچهری .</font><br />عاقل کامل تأمل در این حکایت کند. (کلیله و دمنه ). و بدین مقامات و مقدمات هرگاه که حوادث بر عاقل محیط شود باید که در پناه صواب رود. (کلیله و دمنه ).<br />دو عاقل را نباشد کین و پیکار<br />نه داناخود ستیزد با سبکبار.<br /> <font color=\"Red\">سعدی (گلستان ).</font><br />از این به نصیحت نگوید کست <br />اگر عاقلی یک اشارت بست .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br /><BR><font color=\"Blue\">◄</font> آهو و آهوئی که بر کوه بلند رود. (اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> دهنده ٔ دیه ٔ کشته شده . (ناظم الاطباء) (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عصبه ٔ مرد که وارث او شوند مانند پدر و جد تا هر طبقه که بالا رود و فرزند فرزندتا هر طبقه که پائین رود. (منتهی الارب ).<br /></font></div>'),
(179526, 'عاقل', '<span class=\"hlight\">عاقل .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) وادیی است که اِمَرة در بالای آن و رمه در پائین آن است و پر از طلح بود. (معجم البلدان ).<br /></font></div>'),
(179527, 'عاقل', '<span class=\"hlight\">عاقل .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) ابن کلبی گوید کوهی است که حارث بن آکل المرار جد امری ءالقیس بدان ساکن بود. (معجم البلدان ).<br /></font></div>'),
(179528, 'عاقل', '<span class=\"hlight\">عاقل .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) وادیی است بنی ابان بن دارم را. (معجم البلدان ). آبی است بنی ابان بن دارم را و گفته اند وادیی است پایین بطن الرمة و گفته شده است که وادیی است به نجد... (معجم البلدان ).<br /></font></div>'),
(179529, 'عاقل', '<span class=\"hlight\">عاقل .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) موضعی است به بلاد قیس . (معجم البلدان ).<br /></font></div>'),
(179530, 'عاقل', '<span class=\"hlight\">عاقل .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) نصر گوید ریگی است بین مکه و مدینه . (معجم البلدان ).<br /></font></div>'),
(179531, 'عاقل', '<span class=\"hlight\">عاقل .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) کوهی است به نجد. (معجم البلدان ).<br /></font></div>'),
(179532, 'عاقل', '<span class=\"hlight\">عاقل .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) دهی است از دهستان کله بوز بخش مرکزی شهرستان میانه واقع در <span class=\"hlight\" dir=\"rtl\">٣٥</span>هزارگزی جنوب باختری میانه و <span class=\"hlight\" dir=\"rtl\">٣٥</span>هزارگزی راه شوسه ٔ تبریز و میانه و <span class=\"hlight\" dir=\"rtl\">٢٠</span>هزارگزی راه آهن میانه - مراغه . این ده کوهستانی و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">١٢٩</span> تن سکنه دارد. اراضی آن از چشمه مشروب میشود. محصول آن غلات و برنج و شغل اهالی زراعت و گله داری است و راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(179533, 'عاقل آباد', '<span class=\"hlight\">عاقل آباد.</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) دهی است از دهستان سرشیو بخش مرکزی شهرستان سقز واقع در <span class=\"hlight\" dir=\"rtl\">٢٨</span>هزارگزی جنوب باختری سقز و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی باختر دره آبی . شغل اهالی زراعت است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(179534, 'عاقل عاقل', '<span class=\"hlight\">عاقل عاقل .</span> <font color=\"DarkGreen\"><b>[ ق ِ ل ِ ق ِ ]</font></b> (ص مرکب ) خردمند کامل عیار. تمام عاقل . عاقل که از قانون خرد بهیچوجه یکسو نشود <span class=\"hlight\">:</span> <br />خاقانی از این راه دورنگی بکران باش <br />یا عاقل عاقل زی یا غافل غافل .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(179535, 'عاقل فریب', '<span class=\"hlight\">عاقل فریب .</span> <font color=\"DarkGreen\"><b>[ق ِ ف ِ <span class=\"hlight\" dir=\"rtl\">/</span> ف َ ]</font></b> (نف مرکب ) فریب دهنده ٔ عاقل . آنکه خردمند را بفریبد مفتون سازنده . سخت فربینده <span class=\"hlight\">:</span> <br />اگرچه نار سیمین گشت سیبم <br />همان عاشق کش عاقل فریبم .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(179536, 'عاقل مرد', '<span class=\"hlight\">عاقل مرد.</span> <font color=\"DarkGreen\"><b>[ ق ِ م َ ]</font></b> (ص مرکب، اِ مرکب ) در تداول عامه کسی را گویند که دوران جوانی را گذرانده باشد.<br /></font></div>'),
(179537, 'عاقلات', '<span class=\"hlight\">عاقلات .</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (ع ص، اِ) ج ِ عاقلة. رجوع به عاقله شود.<br /></font></div>'),
(179538, 'عاقلان', '<span class=\"hlight\">عاقلان .</span> (اِخ ) دهی است از دهستان ملکاری بخش سردشت شهرستان مهاباد. واقع در <span class=\"hlight\" dir=\"rtl\">١٧</span>هزارگزی شمال باختری سردشت و <span class=\"hlight\" dir=\"rtl\">١١</span>هزارگزی باختر شوسه سردشت به مهاباد کوهستانی و جنگلی است هوای آن معتدل و سالم است و <span class=\"hlight\" dir=\"rtl\">١٨٩</span> تن سکنه دارد. آب آن از چشمه تأمین میشود محصول آن غلات و توتون و مازوج و کتیرا و شغل اهالی زراعت و گله داری و صنایع دستی آنان جاجیم بافی است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(179539, 'عاقلانه', '<span class=\"hlight\">عاقلانه .</span> <font color=\"DarkGreen\"><b>[ ق ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص نسبی، ق مرکب ) خردمندانه . زیرکانه . (ناظم الاطباء). بمانند عاقلان . عاقل وار <span class=\"hlight\">:</span> دیوانه ... آغاز سخن عاقلانه کرد چنانکه مردم را گمان افتاد که وی بهتر گشت از دیوانگی . (نوروزنامه ).<br /></font></div>'),
(179540, 'عاقلة', '<span class=\"hlight\">عاقلة.</span> <font color=\"DarkGreen\"><b>[ ق ِ ل َ ]</font></b> (ع ص ) مؤنث عاقل . ج، عاقلات و عَواقل . رجوع به عاقل شود. <BR><font color=\"Blue\">◄</font> زن مشاطه . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> عاقلة الرجل ؛ خویشان و نزدیکان مرد کشنده ٔ غیر مکلف (بخاطر سفاهت یا عدم بلوغ و غیره ) که دیت بر ایشان قسمت کنند. (منتهی الارب ) (آنندراج ) (اقرب الموارد) (از مهذب الاسماء) <span class=\"hlight\">:</span> <br />خون بهای جرم نفس قاتله <br />هست بر حملش دیت برعاقله .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> در تداول عامه عاقله زن زنی است نه پیر و نه جوان بل میان سال . <BR><font color=\"Blue\">◄</font> قوه ٔ عاقله ؛ قوتی است از قوای نفس ناطقه که قوت ملکیه نیز گویند و گاه بر نفس ناطقه نیز اطلاق شود. چنانکه در شرح هدایة الحکمه در فصل حیوان است که : و قوای دراکه عبارت از نفس و آلات نفس است . (از کشاف اصطلاحات الفنون ). شیخ الرئیس آرد: و هر نفس انسانی را قوتی هست و آن عقل نظری است و این قوت در اول کار عقل هیولائی است و او عقلی است به قوت نه به فعل یعنی که صورت معقولات در نفس به قوت است نه به فعل پس هر آینه حاجت باشد به چیزی تا این صورت را از حد قوت به حد فعل آرد و آن چیز همچنین اگر بقوت باشد بضرورت او را حاجت باشد نیز به چیزی دیگر که در او صور معقولات به فعل باشد پس نفس مردم چون از قوت به فعل آید در او صور معقولات به چیزی آید که وی عقل باشد به فعل و صور معقولات در او موجود باشد و این جوهری است که وی را عقل فعال خوانند. (رساله ٔ نفس صص <span class=\"hlight\" dir=\"rtl\">٦٤</span> - <span class=\"hlight\" dir=\"rtl\">٦٥</span>) <span class=\"hlight\">:</span> <br />گفتم مقام عاقله نفس است بیگمان <br />گفتا مقام نفس حیات است بی مگر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />چون عقل و جان عزیز و غریب است لاجرم <br />جاندار عقل و عاقله ٔ جان شناسمش .<br /> <font color=\"Red\">خاقانی .</font><br />بجان عاقله ٔ کائنات یعنی تو<br />که کائنات قشورست و حضرت تو لباب .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(179541, 'عاقور', '<span class=\"hlight\">عاقور.</span> (ع ص ) سرج عاقور؛ زین ریش کن پشت ستور. (منتهی الارب ) (شرح قاموس ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> حمار عاقور؛ خر گزنده . (منتهی الارب ) (ناظم الاطباء). خر هار.<br /></font></div>'),
(179542, 'عاقول', '<span class=\"hlight\">عاقول .</span> (ع اِ) معظم دریا یا موج آن . (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> اطراف وادی و نهر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> رودبار کژ. (منتهی الارب ) (اقرب الموارد). جوی کژ. <BR><font color=\"Blue\">◄</font> ریگ توده . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> کار پوشیده . <BR><font color=\"Blue\">◄</font> زمین بی علم و نشان . <BR><font color=\"Blue\">◄</font> گیاهی است که شتر خورد. (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نوعی از خرنوب است که کبر باشد و بعضی گویند درخت ساج است . (برهان ).<br /></font></div>'),
(179543, 'عاقول', '<span class=\"hlight\">عاقول .</span> (اِخ ) شهری است در مغرب . (منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(179544, 'عاقول', '<span class=\"hlight\">عاقول .</span> (اِخ ) دهی است در موصل . (ناظم الاطباء) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دیر عاقول ؛ شهری است بین مدائن و نعمانیه و فاصله ٔ آن تا بغداد <span class=\"hlight\" dir=\"rtl\">١٥</span> فرسنگ است . (منتهی الارب ). رجوع به دیرعاقول شود.<br /></font></div>'),
(179545, 'عاقولی', '<span class=\"hlight\">عاقولی .</span> (ص نسبی ) منسوب است به دیر عاقول که شهری است در پانزده فرسنگی بغداد. (الانساب سمعانی ). رجوع به عاقول و به دیرعاقول شود.<br /></font></div>'),
(179546, 'عال', '<span class=\"hlight\">عال .</span> <font color=\"DarkGreen\"><b>[ عال ل ]</font></b> (ع ص ) رجل ٌ عال ؛ آنکه شتران او دوباره آب خورده باشند. (منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(179547, 'عالة', '<span class=\"hlight\">عالة.</span> <font color=\"DarkGreen\"><b>[ عال ل َ ]</font></b> (ع ص ) مؤنث عال . (اقرب الموارد). ابل عالة؛ شتران دوباره آب خورنده . و منه المثل عرض علی سوم عالة؛ أی لم یبالغ بیعی، که فروشنده ٔ کالا در وی مبالغه نکند. (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(179548, 'عالة', '<span class=\"hlight\">عالة.</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (ع اِ) ج ِ عائل . رجوع به عائل شود. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) شتر مرغ . (المنجد) (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> هر پوششی که از باران در زیر آن پناه آورند. (اقرب الموارد). باران گریز. (آنندراج ) (ناظم الاطباء) (المنجد).<br /></font></div>'),
(179549, 'عالج', '<span class=\"hlight\">عالج .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) جائی است به بادیه و در آن ریگستانی است . (منتهی الارب ). ابوعبداﷲ سکونی گوید عالج رمال است میان فَید و قریات . (از معجم البلدان ).<br /></font></div>'),
(179550, 'عالج', '<span class=\"hlight\">عالج .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع اِ) ریگ توبرتو. (منتهی الارب ). و ریگی که بر تمام عربستان احاطه دارد. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (ص ) شتری که «علجان » خورد. (مهذب الاسماء) (اقرب الموارد) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِخ ) ریگی است معروف ببادیه . (اقرب الموارد).<br /></font></div>'),
(179551, 'عالز', '<span class=\"hlight\">عالز.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) موضعی است . (منتهی الارب ). یاقوت آرد: نام موضعی است که در شعر شماخ آمده است . (معجم البلدان ).<br /></font></div>'),
(179552, 'عالط', '<span class=\"hlight\">عالط.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) شاعر که سخنان را آراسته گرداند. (منتهی الارب ) (از اقرب الموارد).<br /></font></div>'),
(179553, 'عالق', '<span class=\"hlight\">عالق .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) شتر «علقی »خوار. شتر عضاه خوار. ج، عوالق وعالقات . (اقرب الموارد) (آنندراج ) (مهذب الاسماء).<br /></font></div>'),
(179554, 'عالم', '<span class=\"hlight\">عالم .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (ع اِ) کلیه ٔ مخلوقات . بعضی گویند آنچه در بطن فلک است و هر صنفی ازاصناف خلق . و گفته شده است که ویژه ٔ ذوی العقول است .ج، عالَمون و علالم و عوالم . (اقرب الموارد). چیزی است که بدان امری شناخته شود و علامت گذارده شود. (تعریفات جرجانی ). <BR><font color=\"Blue\">◄</font> در اصطلاح فلسفه، عبارت از ماسوی اﷲ است یعنی جهان و آنچه آسمان محیط به آن است از آن جهت که دانسته شود به آن خدا از جهت اسماء و صفات آن . ج، عوالم . (از منتهی الارب ) (تعریفات ) (آنندراج ) (از اقرب الموارد). و بمعنی انواع مخلوقات آید. (غیاث اللغات ) (آنندراج ). بعضی گفته اند نام است برای آنچه دانسته شود بدان چیزی دیگر و بعد نامگذارده اند بر آنچه دانسته شود بدان خالق از هر نوعی از فلک و آنچه را در بردارد از جواهر و اعراض <span class=\"hlight\">:</span> <br />زمین است و آب است و آنگه هوا<br />و باز آتش آمد به ترتیب راست <br />کهین عالم این را نهد فیلسوف <br />که زندان جان است و دام بلاست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />باز در عواقب کارهای عالم تفکری کردم . (کلیله و دمنه ). و بباید دانست که اطراف عالم پر بلا و عذاب است . (کلیله و دمنه ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عالم جبروت </span> . عالم سفلی . عالم عقلی . عالم علوی . عالم ملکوت . عالم لاهوت . رجوع به این کلمات شود.<br /></font></div>'),
(179555, 'عالم', '<span class=\"hlight\">عالم .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) خردمند. دانا. کسی که او را دانش باشد. مقابل جاهل . ج، عُلاّم و عالمون . (از اقرب الموارد) (از المنجد) (از منتهی الارب ) <span class=\"hlight\">:</span> <br />چنین که کرد تواند مگر خدای بزرگ <br />که قادر است و حکیم است و عالم و جبار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />عالم که به جهل خود مقر شد<br />از جمله ٔ صادقین شمارش .<br /> <font color=\"Red\">خاقانی .</font><br />اقوال پسندیده مدروس گشته و عالم غدار و زاهد مکار. (کلیله و دمنه ).<br />گفتم میان عالم وعابد چه فرق بود<br />تا اختیار کردی از آن این فریق را.<br /><font color=\"Red\">سعدی (گلستان ).</font><br /></font></div>'),
(179556, 'عالم آب', '<span class=\"hlight\">عالم آب .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) نشأه ٔ شراب و عالم شراب و حالت می نوشی . (غیاث اللغات ) (آنندراج ). حالت باده گساری . حالت می خوری . (از ناظم الاطباء) <span class=\"hlight\">:</span> <br />نیست باکم ازفلک امشب که با او می خورم <br />عالم آب است پندارم که آبش برده است .<br /> <font color=\"Red\">آشوب مازندرانی (از آنندراج ).</font><br />ترا که عالم آئینه عالم آب است <br />چه احتیاج به تحصیل باده ٔ ناب است .<br /> <font color=\"Red\">صائب .</font><br />ساقی چه دهی پند من این بزم شراب است <br />از گریه مرا منع مکن عالم آب است .<br /> <font color=\"Red\">محمد قلی سلیم (از آنندراج ).</font><br />هیچ منظوری ببزم می کشان چون شیشه نیست <br />عالم آب است آنجا سبزه ٔ مینا خوشست .<br /><font color=\"Red\">کلیم (از آنندراج ).</font><br /></font></div>'),
(179557, 'عالم آباد', '<span class=\"hlight\">عالم آباد.</span> <font color=\"DarkGreen\"><b>[ل ِ ]</font></b> (اِخ ) دهی است جزء دهستان حومه ٔ بخش مرکزی شهرستان محلات واقع در <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی جنوب محلات متصل به جاده ٔ دلیجان خمین، جلگه و آب و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٥٣</span> تن سکنه دارد. آب آن از قنات تأمین میشود و محصولات آن غلات، پنبه، صیفی است و شغل اهالی زراعت و سر راه ماشین رو واقع شده . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(179558, 'عالم آباد', '<span class=\"hlight\">عالم آباد.</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِخ ) دهی است از دهستان کاغه بخش دورود شهرستان بروجرد. واقع در <span class=\"hlight\" dir=\"rtl\">٢٥</span>هزارگزی شمال دورود کنار راه مالرو کاغه به همیانه . ناحیه ای است واقع در جلگه معتدل . دارای <span class=\"hlight\" dir=\"rtl\">٢٧٩</span> تن سکنه . آب آن از قنات تأمین میشود. محصول آن غلات است اهالی به کشاورزی و گله داری اشتغال دارند. راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(179559, 'عالم آرا', '<span class=\"hlight\">عالم آرا.</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (نف مرکب )عالم آرای . آرایش دهنده ٔ عالم . پیراینده ٔ جهان و زینت دهنده ٔ آن . (ناظم الاطباء) <span class=\"hlight\">:</span> اگر رأی عالم آرای ملک اشارت فرماید بگویم . (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٢٧٦</span>).<br />بی جمال عالم آرای تو روزم چون شب است <br />با کمال عشق تو در عین نقصانم چو شمع.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(179560, 'عالم آشوب', '<span class=\"hlight\">عالم آشوب .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (نف مرکب ) برهم زننده ٔ عالم . بمجاز آنکه مردمان را فریفته ٔ زیبائی خود سازد. بغایت زیبا. سخت خوش صورت و دلفریب <span class=\"hlight\">:</span> <br />پری پیکری بود محبوب من <br />بدو گفتم ای عالم آشوب من .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />گر در قیامتت هست این ناز عالم آشوب <br />خوش آفتی است در پیش هنگامه ٔ جزا را.<br /><font color=\"Red\">عرفی .</font><br /></font></div>'),
(179561, 'عالم ارواح', '<span class=\"hlight\">عالم ارواح .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ اَرْ ]</font></b> (ترکیب اضافی، اِ مرکب ) مقام و منزل ارواح . (ناظم الاطباء).<br /></font></div>'),
(179562, 'عالم اسباب', '<span class=\"hlight\">عالم اسباب .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ اَ ]</font></b> (ترکیب اضافی، اِ مرکب ) دنیا و مافیها. (آنندراج ).<br /></font></div>'),
(179563, 'عالم امر', '<span class=\"hlight\">عالم امر.</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ اَ ]</font></b> (ترکیب اضافی، اِ مرکب ) عالم ارواح و عالم ملائکه . (از غیاث اللغات ). آنچه موجود شد. بدون سبب عالم امر گویند و گاه بجای عالم ملکوت عالم امر گویند. (تعریفات جرجانی ).<br /></font></div>'),
(179564, 'عالم امکان', '<span class=\"hlight\">عالم امکان .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِاِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آنچه غیر ذات خداست .<br /></font></div>'),
(179565, 'عالم بالا', '<span class=\"hlight\">عالم بالا.</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آسمان . (ناظم الاطباء).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(179566, 'عالم بالا', '<span class=\"hlight\">عالم بالا.</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) دهی است از دهستان یوسف وند بخش سلسله شهرستان خرم آباد. واقع در <span class=\"hlight\" dir=\"rtl\">٢٢</span> هزارگزی باختری الشتر و هفت هزارگزی باختر. ناحیه ای است واقع در جلگه ٔسردسیر و مالاریائی . <span class=\"hlight\" dir=\"rtl\">١٨٠</span> تن سکنه دارد. از سراب و رمزیار مشروب میشود. محصولاتش غلات، حبوبات، لبنیات است و اهالی به کشاورزی و گله داری گذران میکنند. راه آن مالرو است و ساکنان ده از طایفه ٔ یوسف وندند و زمستان به قشلاق میروند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(179567, 'عالم برزخ', '<span class=\"hlight\">عالم برزخ .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ب َ زَ ]</font></b> (ترکیب اضافی، اِ مرکب ) مقام ارواح که مابین موت و قیامت است . (از غیاث اللغات ) (آنندراج ). رجوع به برزخ شود.<br /></font></div>'),
(179568, 'عالم تربیت', '<span class=\"hlight\">عالم تربیت .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ت َ ی َ ]</font></b> (ترکیب اضافی، اِ مرکب ) زمان تربیت و تأدیب . (ناظم الاطباء).<br /></font></div>'),
(179569, 'عالم جان', '<span class=\"hlight\">عالم جان .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) عالم ارواح . <BR><font color=\"Blue\">◄</font> کنایه از دنیا و عالم سفلی . <BR><font color=\"Blue\">◄</font> عناصر اربعه را نیز گویند. (برهان ) (آنندراج ).<br /></font></div>'),
(179570, 'عالم جبروت', '<span class=\"hlight\">عالم جبروت .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ج َ ب َ ]</font></b> (ترکیب اضافی، اِ مرکب ) عالم ذات قدیم را عالم جبروت گویند و عالم صفات حق را ملکوت نامند. (از کشاف اصطلاحات الفنون ). مقام ملائکه و عرش . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> حالت بزرگی و تکبر. <BR><font color=\"Blue\">◄</font> عالم عظمت و جلال اسمای صفات الهی . <BR><font color=\"Blue\">◄</font> مرتبه ٔ وحدت که حقیقت محمدی است و تعلق به مرتبت صفات دارد. (ناظم الاطباء).<br /></font></div>'),
(179571, 'عالم جسمانی', '<span class=\"hlight\">عالم جسمانی .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ج ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) عالم طبیعت و ماده است . (شرح حکمة الاشراق ص <span class=\"hlight\" dir=\"rtl\">١٥٧</span>).<br /></font></div>'),
(179572, 'عالم حسی', '<span class=\"hlight\">عالم حسی .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ح ِس ْ سی ]</font></b> (ترکیب وصفی، اِ مرکب ) عالم شهود و شهادت، در مقابل عالم غیب و عالم معقول . (شرح حکمة الاشراق صص <span class=\"hlight\" dir=\"rtl\">١٤٥</span> - <span class=\"hlight\" dir=\"rtl\">١٧٥</span>).<br /></font></div>'),
(179573, 'عالم خاک', '<span class=\"hlight\">عالم خاک .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ]</font></b> (ترکیب اضافی، اِ مرکب )کنایه از دنیا باشد. (برهان ) (آنندراج ). <BR><font color=\"Blue\">◄</font> جسد آدمی . (برهان ) (آنندراج ) (از ناظم الاطباء).<br /></font></div>'),
(179574, 'عالم خلق', '<span class=\"hlight\">عالم خلق .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ خ َ ]</font></b> (ترکیب اضافی، اِ مرکب ) کائنات و موجودات عالم جسمانی که در معرض کون و فساد و خلع و لبس اند و آن را عالم شهادت هم میگویند. (تعریفات جرجانی ) (از کشاف اصطلاحات الفنون ).<br /></font></div>'),
(179575, 'عالم دورنگ', '<span class=\"hlight\">عالم دورنگ .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ دُ رَ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از عالم دنیا است به اعتبار شب و روز. (برهان ) (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از مردم منافق و دوروو غدار است . (برهان ) (آنندراج ) (از ناظم الاطباء).<br /></font></div>'),
(179576, 'عالم دگر', '<span class=\"hlight\">عالم دگر.</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ دِ گ َ ]</font></b> (ترکیب وصفی، اِ مرکب ) عالم دیگر. عالم آخرت . مقابل دنیا.<br /></font></div>'),
(179577, 'عالم دیگر', '<span class=\"hlight\">عالم دیگر.</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ گ َ ]</font></b> (ترکیب وصفی، اِ مرکب ) عالم دگر. جز این جهان . (ناظم الاطباء).<br /></font></div>'),
(179578, 'عالم ذوق', '<span class=\"hlight\">عالم ذوق .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ذَ <span class=\"hlight\" dir=\"rtl\">/</span> ذُو ]</font></b> (ترکیب اضافی، اِ مرکب ) حالت شادمانی و خرمی . (ناظم الاطباء).<br /></font></div>'),
(179579, 'عالم ربوبی', '<span class=\"hlight\">عالم ربوبی .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ رُ ]</font></b> (ترکیب وصفی، اِ مرکب ) عالم عقل و معقولات است . (شرح حکمة الاشراق ص <span class=\"hlight\" dir=\"rtl\">٢٠</span>).<br /></font></div>'),
(179580, 'عالم روحانی', '<span class=\"hlight\">عالم روحانی .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ]</font></b> (ترکیب وصفی، اِمرکب ) عالم اشباح برزخی . (شرح حکمة الاشراق ص <span class=\"hlight\" dir=\"rtl\">٢٤٣</span>).<br /></font></div>'),
(179581, 'عالم زمین', '<span class=\"hlight\">عالم زمین .</span> <font color=\"DarkGreen\"><b>[ ل َ زَ ]</font></b> (اِخ ) ده کوچکی است از بخش کرج شهرستان تهران . واقع در <span class=\"hlight\" dir=\"rtl\">٤١</span>هزارگزی شمال باختری کرج و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی شمال راه شوسه ٔ کرج به قزوین . کوهستانی و هوای آن سردسیر است . <span class=\"hlight\" dir=\"rtl\">١٨</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(179582, 'عالم شهادت', '<span class=\"hlight\">عالم شهادت .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ش َ دَ ]</font></b> (ترکیب اضافی، اِ مرکب ) جهان جسمانی و اجسام و مادیات است که عالم ملک و ناسوت هم گویند. (اسفار ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>). عالم خلق که عبارت است از عالم مادی مانند افلاک و عناصر و موالید که عالم ملک هم گویند. (از کشاف اصطلاحات الفنون ). این جهان که مشهود و محسوس است . (ناظم الاطباء).<br /></font></div>'),
(179583, 'عالم صباوت', '<span class=\"hlight\">عالم صباوت .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ص َ وَ ]</font></b> (ترکیب اضافی، اِ مرکب ) سن طفولیت . (ناظم الاطباء).<br /></font></div>'),
(179584, 'عالم صغیر', '<span class=\"hlight\">عالم صغیر.</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ص َ ]</font></b> (ترکیب وصفی، اِ مرکب ) مراد انسان است که جهان کوچکی است و منطوی است در آن جهان بزرگ و مقابل عالم کبیر است . (غیاث اللغات ) (آنندراج ). مؤلف کشاف اصطلاحات الفنون آرد که : در تفسیر عالم کبیر و صغیر اختلاف است، بعضی گویند عالم کبیر عالم فوق آسمانها است و عالم صغیر زیر آسمانها است و بعضی گویند عالم کبیر ملکوت سماوات است و عالم صغیر ملکوت زمین است و بعضی گویند عالم کبیر قلب و عالم صغیر نفس است و جمهور فلاسفه گویند عالم کبیر جهان وجود از آسمانها و زمین و مافیها است . و عالم صغیر انسان است چرا که هر چه در جهان امر است همان در عالم خلق است و هرچه در مجموع عالم خلق و امر است همان در ذات انسان است که عالم صغیرش خوانند زیرا که قالبش از عالم خلق است و روحش از عالم امر. (از کشاف اصطلاحات الفنون ). صدرا گوید: موجودات جهان شهادت کلاً با یکدیگر ارتباط دارند و بعضی از بعضی دیگر متأثر و منتفع میشوندو همبستگی و ارتباط اشیاء آنها را مانند موجود واحدی کرده است (که هر چیزی بجای خویش نیکوست ) و جهان بزرگ عالم کبیر است و مضاهی عالم صغیر است که انسان باشد و همانطور که اعضای انسان همه با یکدیگر بستگی دارند و مانند یک موجودند و موجودات جهان وجود بواسطه ٔارتباطی که دارند مانند یک موجودند و اعضاء و جوارح و حواس ظاهره را معادلی است در عالم شهادت و عالم غیب معادل با مشاعر و قوای باطنه ٔ انسان است . از عالم صغیر که انسان باشد به مملکت آدمیت و انسانیت و دارالخلافة ربانی تعبیر شده است . (از رسائل ملاصدرا ص <span class=\"hlight\" dir=\"rtl\">٢٩٠</span>، <span class=\"hlight\" dir=\"rtl\">٢٩٢</span>، <span class=\"hlight\" dir=\"rtl\">٢٩٤</span>). و رجوع به اسفار ج <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">١٢٦</span> - <span class=\"hlight\" dir=\"rtl\">١٢٧</span> شود.<br /></font></div>'),
(179585, 'عالم صور', '<span class=\"hlight\">عالم صور.</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ص ُ وَ ]</font></b> (ترکیب اضافی، اِ مرکب ) موطن صور مقداری که اشباح برزخی است . عالم صور گویند و گاه مراد صور حسی است . (از اسفار ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٧٤</span> - <span class=\"hlight\" dir=\"rtl\">٢٩٣</span>).<br /></font></div>'),
(179586, 'عالم صوری', '<span class=\"hlight\">عالم صوری .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) این دنیا. (ناظم الاطباء).<br /></font></div>'),
(179587, 'عالم طبیعی', '<span class=\"hlight\">عالم طبیعی .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ طَ ]</font></b> (ترکیب وصفی، اِ مرکب ) مراد از عالم طبیعی مقابل مجردات و عقول است که عالم شهادت باشد. (از مبداء ومعاد ملاصدرا ص <span class=\"hlight\" dir=\"rtl\">٣٠٢</span>). و رجوع به اسفار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٧</span> شود.<br /></font></div>'),
(179588, 'عالم طفولیت', '<span class=\"hlight\">عالم طفولیت .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ طُ لی ی َ ]</font></b> (ترکیب اضافی، اِ مرکب ) حالت بچگی . (ناظم الاطباء).<br /></font></div>'),
(179589, 'عالم ظلمانی', '<span class=\"hlight\">عالم ظلمانی .</span><font color=\"DarkGreen\"><b>[ ل َ م ِ ظُ ]</font></b> (ترکیب وصفی، اِ مرکب ) اصطلاح اشراقی است و مقابل عالم نورانی است و مراد عالم برازخ و اجسام و ماهیات است . (شرح حکمة الاشراق صص <span class=\"hlight\" dir=\"rtl\">١٥٧</span> - <span class=\"hlight\" dir=\"rtl\">٢٧٧</span>).<br /></font></div>'),
(179590, 'عالم عقلی', '<span class=\"hlight\">عالم عقلی .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ع َ ]</font></b> (ترکیب وصفی، اِ مرکب ) فلاسفه قائل به سه عالمند: <span class=\"hlight\" dir=\"rtl\">١</span> - عالم عقل که گاه در مقابل عالم خارج است و در این صورت مراد عالم ذهن است و گاه در مقابل عالم ماده و یا نفس است که مراد عالم عقول مجرده است از عقل اول تا عقل دهم . <span class=\"hlight\" dir=\"rtl\">٢</span> - عالم نفس که گاه نفس انسان و سایر قوای نفسانی است و گاه مراد نفوس فلکیه وکواکب است . <span class=\"hlight\" dir=\"rtl\">٣</span> - عالم جرم که عالم ماده است اعم از فلکی و ارضی و زمان و زمانیات . (از اسفار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٣</span> ومبداء و معاد ملاصدرا ص <span class=\"hlight\" dir=\"rtl\">٣٢٠</span> و رسائل ملاصدرا ص <span class=\"hlight\" dir=\"rtl\">١٥١</span>).<br /></font></div>'),
(179591, 'عالم علوی', '<span class=\"hlight\">عالم علوی .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) آسمان و عالم بالا. (ناظم الاطباء). مقابل عالم سفلی است و مراد افلاک و اجرام فلکی و سماویات بطور مطلق است . (از شرح حکمة الاشراق صص <span class=\"hlight\" dir=\"rtl\">٢٧٨</span> - <span class=\"hlight\" dir=\"rtl\">٢٧٦</span>).<br /></font></div>'),
(179592, 'عالم عنصری', '<span class=\"hlight\">عالم عنصری .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ع ُ ص ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) مراد عالم عناصر و جسمانیات است که عالم عناصر گویند. (از شرح حکمة الاشراق ص <span class=\"hlight\" dir=\"rtl\">٢٤٤</span>، <span class=\"hlight\" dir=\"rtl\">١٣٧</span>، <span class=\"hlight\" dir=\"rtl\">٢٦٦</span>، <span class=\"hlight\" dir=\"rtl\">٢٩٠</span>).<br /></font></div>'),
(179593, 'عالم غیب', '<span class=\"hlight\">عالم غیب .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ غ َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آن جهان و جهان آینده . (ناظم الاطباء). مقابل عالم شهادت است . و مراد جهان معقول و مجردات نوریه است که غایب از عالم شهادت است و بالجمله عالم عقول و مجردات و اسماء و صفات حق تعالی است . و عالم آخرت را نیز عالم غیب گویند. (از کشاف اصطلاحات الفنون ).<br /></font></div>'),
(179594, 'عالم قدس', '<span class=\"hlight\">عالم قدس .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ق ُ ]</font></b> (ترکیب اضافی، اِ مرکب )عالم اسماء و صفات حق است . (از کشاف اصطلاحات الفنون ). صدرا گوید: عالم قدس عالم مجردات و عالم الهی است . رجوع به اسفار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٨</span> و رسائل ملاصدرا ص <span class=\"hlight\" dir=\"rtl\">٢٩٢</span> شود.<br /></font></div>'),
(179595, 'عالم لاهوت', '<span class=\"hlight\">عالم لاهوت .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) دربار آسمانی . (ناظم الاطباء). عالم صقع الهی و عالم سرمد و مرتبت ذات و احدیت است . رجوع شود به شرح منظومه ٔ حاجی ص <span class=\"hlight\" dir=\"rtl\">١٨٣</span>.<br /></font></div>'),
(179596, 'عالم مثال', '<span class=\"hlight\">عالم مثال .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ م ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) عالمی است لطیف تر نسبت به عالم اجسام و هر چه در این عالم به نظر می آید نظیر آن در عالم مثال موجود است . (از غیاث اللغات ) (از آنندراج ). صدرالدین شیرازی آرد: عالم مثال عبارت از عالم روحانی و جوهر نورانی است و شبیه به جواهر جسمانی است از جهت محسوس بودن و ذومقدار بودن و شبیه به جواهر مجرده است از جهت نورانی بودن و نه از جنس اجسام مرکب از مواد است و نه از جواهر مجرده ٔ عقلی است . (از اسفار ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٣</span>). عالم برزخ . (ناظم الاطباء).<br /></font></div>'),
(179597, 'عالم مجردات', '<span class=\"hlight\">عالم مجردات .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ م ُ ج َرْ رَ ]</font></b> (ترکیب اضافی، اِمرکب ) عالم عقول و نفوس . رجوع به عالم ملکوت شود.<br /></font></div>'),
(179598, 'عالم معقول', '<span class=\"hlight\">عالم معقول .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ م َ ]</font></b> (ترکیب وصفی، اِ مرکب ) آنچه متعلق به ذهن و ادراک عقل باشد. (ناظم الاطباء).<br /></font></div>'),
(179599, 'عالم معنی', '<span class=\"hlight\">عالم معنی .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ م َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آنچه متعلق به معنی و حقیقت باشد و ناپدید و مخفی بود. (ناظم الاطباء). در مقابل عالم صور است و در اصطلاح صوفیه عبارت از ذات و صفات و اسماء است . (از آنندراج ) (از کشاف اصطلاحات الفنون ).<br /></font></div>'),
(179600, 'عالم مفارقات', '<span class=\"hlight\">عالم مفارقات .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ م ُ رِ ]</font></b> (ترکیب اضافی، اِ مرکب ) عالم مجردات . رجوع به اسفار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٤</span> و مبداء و معاد ص <span class=\"hlight\" dir=\"rtl\">٣٤٣</span> شود.<br /></font></div>'),
(179601, 'عالم مقدار', '<span class=\"hlight\">عالم مقدار.</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ م ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) مراد عالم مثال است . رجوع به عالم مثال شود. (از شرح حکمة الاشراق ص <span class=\"hlight\" dir=\"rtl\">٢٤٣</span> و اسفار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٤</span> و مبداء و معاد ملاصدرا ص <span class=\"hlight\" dir=\"rtl\">٣٤٣</span>).<br /></font></div>'),
(179602, 'عالم ملک', '<span class=\"hlight\">عالم ملک .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ م ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) عالم اجسام و شهادت است و گاه عالم وجود بطور مطلق و کلی اراده میشود. رجوع به اسفار ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥</span> و به عالم شهادت شود.<br /></font></div>'),
(179603, 'عالم ملکوت', '<span class=\"hlight\">عالم ملکوت .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ م َ ل َ ]</font></b> (ترکیب اضافی، اِ مرکب )عالم جبروت و عالم مجردات است . (ناظم الاطباء). ملاصدرا گوید: عالم شهادت مانند قشر است نسبت به عالم ملکوت و مانند قالب است به قیاس به عالم روح . عالم ملکوت مقابل عالم شهادت است . (از اسفار ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦</span> و شرح منظومه ٔ سبزواری ص <span class=\"hlight\" dir=\"rtl\">١٨٣</span> و رسائل ملاصدرا ص <span class=\"hlight\" dir=\"rtl\">١٥١</span> و <span class=\"hlight\" dir=\"rtl\">٢٨٣</span>).<br /></font></div>'),
(179604, 'عالم ملکوت اسفل', '<span class=\"hlight\">عالم ملکوت اسفل .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ م َ ل َ ت ِ اَ ف َ ]</font></b> (ترکیب اضافی، اِمرکب ) عالم مثل معلقه و صور مقداری است . (رسائل ملاصدرا ص <span class=\"hlight\" dir=\"rtl\">١٥١</span>، <span class=\"hlight\" dir=\"rtl\">٢٨٣</span>). و رجوع به شرح منظومه ص <span class=\"hlight\" dir=\"rtl\">١٨٣</span> شود.<br /></font></div>'),
(179605, 'عالم ملکوت اعلی', '<span class=\"hlight\">عالم ملکوت اعلی .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ م َ ل َ ت ِ اَ لا ]</font></b> (ترکیب اضافی، اِ مرکب ) عالم غیب و عالم مجردات محض و عقول است . (از شرح منظومه ص <span class=\"hlight\" dir=\"rtl\">١٨٣</span> و رسائل ملاصدرا ص <span class=\"hlight\" dir=\"rtl\">١٥١</span>). و رجوع به عالم غیب شود.<br /></font></div>'),
(179606, 'عالم ناسوت', '<span class=\"hlight\">عالم ناسوت .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) دنیای فانی و این جهان که ناپایدار است . (ناظم الاطباء).<br /></font></div>'),
(179607, 'عالم نفسی', '<span class=\"hlight\">عالم نفسی .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ن َ ]</font></b> (ترکیب وصفی، اِ مرکب ) مقابل عالم عقلی و هم عالم حسی است . (از رسائل ملاصدرا ص <span class=\"hlight\" dir=\"rtl\">١٥١</span>).<br /></font></div>'),
(179608, 'عالم نورانی روحانی', '<span class=\"hlight\">عالم نورانی روحانی .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ی ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) عالم مجردات است . (از شرح حکمة الاشراق ص <span class=\"hlight\" dir=\"rtl\">١٥٧</span>).<br /></font></div>'),
(179609, 'عالم هیولی', '<span class=\"hlight\">عالم هیولی .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ هََ لا ]</font></b> (ترکیب اضافی، اِ مرکب ) عالم اجسام است . (از غیاث اللغات ) (از آنندراج ).<br /></font></div>'),
(179610, 'عالم پایین', '<span class=\"hlight\">عالم پایین .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b>(اِخ ) دهی است از دهستان یوسف وند بخش سلسله ٔ شهرستان خرم آباد. واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی باختر الشتر و هفت هزارگزی باختر اتومبیل رو خرم آباد به کرمانشاه . ناحیه ای است واقع در جلگه هوای آن سرد و مالاریائی است . <span class=\"hlight\" dir=\"rtl\">١٢٠</span> تن سکنه دارد. آب آن از رودخانه ٔ رمزیار تأمین میشود محصولاتش غلات، حبوبات، لبنیات و اهالی، به کشاورزی و گله داری اشتغال دارند راه آن مالرو است . ساکنان از طایفه ٔ یوسف وندند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(179611, 'عالم کبیر', '<span class=\"hlight\">عالم کبیر.</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ک َ ]</font></b> (ترکیب وصفی، اِ مرکب ) مراد جهان وجود است . روزگار و دهر و همه ٔ جهان . (ناظم الاطباء). رجوع به عالم صغیر شود.<br /></font></div>'),
(179612, 'عالم کون و فساد', '<span class=\"hlight\">عالم کون و فساد.</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ک َ ن ُف َ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از دنیای فانی وعالم سفلی است . (برهان ) (آنندراج ). و از آن جهت عالم کون و فساد گویند که در معرض خلع و لبس صور است .<br /></font></div>'),
(179613, 'عالمانه', '<span class=\"hlight\">عالمانه .</span> <font color=\"DarkGreen\"><b>[ ل ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص نسبی، ق مرکب )عاقلانه و خردمندانه و دانشمندانه . (ناظم الاطباء).<br /></font></div>'),
(179614, 'عالمة', '<span class=\"hlight\">عالمة.</span> <font color=\"DarkGreen\"><b>[ ل ِ م َ ]</font></b> (ع ص ) مؤنث عالم . رجوع به عالم شود.<br /></font></div>'),
(179615, 'عالمتاب', '<span class=\"hlight\">عالمتاب .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (نف مرکب ) تابنده و روشن کننده ٔ جهان . (ناظم الاطباء).<br /></font></div>'),
(179616, 'عالمون', '<span class=\"hlight\">عالمون .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (ع اِ) ج ِ عالم (در حالت رفع).<br /></font></div>'),
(179617, 'عالمی', '<span class=\"hlight\">عالمی .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (ص نسبی ) منسوب به عالم .<br /></font></div>'),
(179618, 'عالمیان', '<span class=\"hlight\">عالمیان .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِ مرکب ) ج ِ عالَمی، جهانیان . آنچه در جهان است <span class=\"hlight\">:</span> و جناح انعام و احسان او بر عالمیان گسترده . (کلیله و دمنه ). تا عالمیان بدانند که چون با جگرگوشه و قرة العین ... (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span>).<br />چون علم لشکر دل یافتم <br />روی خود از عالمیان تافتم .<br /> <font color=\"Red\">نظامی .</font><br />حق تعالی او را به کرامت آن مخصوص گردانید و عالمیان در کنف عدل و رأفت و پناه احسان و عاطفت او آسوده گشتند. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٢١</span>). رحمت عالمیان و صفوت آدمیان . (گلستان ). شخصم به چشم عالمیان خوب منظر است .<br /><font color=\"Red\">(گلستان ).</font><br /></font></div>'),
(179619, 'عالمین', '<span class=\"hlight\">عالمین .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (ع اِ) ج ِ عالم (در حالت نصبی و جری ). رجوع به عالم و عالمون شود.<br /></font></div>'),
(179620, 'عاله', '<span class=\"hlight\">عاله .</span> <font color=\"DarkGreen\"><b>[ ل ِه ْ ]</font></b> (ع اِ) زن سبک وزن که آهنگ مختلف نماید و بر یک راه نرود. (ناظم الاطباء) (منتهی الارب ). طیاشه . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) شترمرغ . (منتهی الارب ). نعامه . (اقرب الموارد).<br /></font></div>'),
(179621, 'عالونی', '<span class=\"hlight\">عالونی .</span> (اِخ ) تیره ای از طایفه ٔ عُکاّشه ٔ هفت لنگ بختیاری . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٧٤</span>).<br /></font></div>'),
(179622, 'عالک', '<span class=\"hlight\">عالک .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (ع ص ) طعام عالک ؛ طعام سخت در خائیدن . (منتهی الارب ) (آنندراج ) (اقرب الموارد).<br /></font></div>'),
(179623, 'عالی', '<span class=\"hlight\">عالی .</span> (ع ص ) بلند، مقابل سافل . و منه أتیته من عال . (منتهی الارب ) (آنندراج ) (ناظم الاطباء) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> رفیع و بلند. (ناظم الاطباء) (مهذب الاسماء). کلان . (مهذب الاسماء) (ناظم الاطباء). رجل عالی الکعب ؛ مرد شریف . (منتهی الارب ) <span class=\"hlight\">:</span> <br />اندک اندک علم یابد نفس چون عالی بود<br />قطره قطره جمع گردد و آنگهی دریا شود.<br /> <font color=\"Red\">ناصرخسرو.</font><br />و آن درجت شریف و رتبت عالی . (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> (اِخ ) نامی از نامهای خدای متعال . <BR><font color=\"Blue\">◄</font> (ص ) بزرگوار و فاضل . سرافراز. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> در اصطلاح درایت و نزد محدثان عبارت است از سندی که در آن علو باشد و مقابل او نازل است . (از کشاف اصطلاحات الفنون ). سندی که سلسله ٔ آن کوتاه تر از دیگر اسناد باشد و با واسطه ٔ کمتر نقل شود. <BR><font color=\"Blue\">◄</font> در اصطلاح معانی و بیان و نزد بلغا آن است که شاعر الفاظ فصیح در ترکیب چنان به جزالت ربط دهد که پنداشته آید که کلمه کلمه لطافت درجه درجه پذیرفته و پایه پایه در خوبی ارتقاء یافته و وی را اشعار از اشعار مردمان به مرتبت عالی تر بود که فصحاء به علو مرتبت او اقرار کنند.کذا فی مجمع الصنایع. (کشاف اصطلاحات الفنون ص <span class=\"hlight\" dir=\"rtl\">١٠٧٧</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">باب عالی </span> ؛ درگاه سلطان عثمانی را میگفتند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">جاه عالی </span> ؛ عالی جاه . پایه و مرتبه ٔ بلند. و رجوع به عالیجاه شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">درگاه عالی </span> ؛ درگاه شاه <span class=\"hlight\">:</span> قضات و صاحب بریدان درگاه عالی یا وی و نائبان وی باشند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٦٤</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دیوان عالی کشور</span> ؛ عالیترین مرجع قضائی . رجوع به دیوان ... شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">رأی عالی </span> ؛ رأی ثاقب و صائب و بلند <span class=\"hlight\">:</span> و رأی عالی چنین اقتضا میکند که ... (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٧١</span>). و آنچه را رأی عالی بفرماید. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٥٨</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">فرمان عالی </span> ؛ فرمان که از مافوق صادر شود <span class=\"hlight\">:</span> فرمان عالی رسید به خط بونصر مشکان . (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">لفظ عالی </span> ؛ لفظ و گفتار شاه <span class=\"hlight\">:</span> و مثالها از لفظ عالی بشنود. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٧٢</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مجلس عالی </span> ؛ مجلس سلطان .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">همت عالی </span> ؛ همت بلند.<br /></font></div>'),
(179624, 'عالی', '<span class=\"hlight\">عالی .</span> (اِخ ) ده کوچکی است از دهستان بیضا بخش اردکان شهرستان شیراز. واقع در <span class=\"hlight\" dir=\"rtl\">٢٨</span>هزارگزی جنوب خاوراردکان و سه هزارگزی راه فرعی زرقان به بیضا و دارای <span class=\"hlight\" dir=\"rtl\">٣٦</span> تن سکنه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(179625, 'عالی', '<span class=\"hlight\">عالی .</span> (اِخ ) دهی است از دهستان برخون شهرستان بوشهر بخش خورموج شهرستان بوشهر. واقع در <span class=\"hlight\" dir=\"rtl\">١٢٦</span>هزارگزی جنوب خورموج در ساحل خلیج فارس . ناحیه ای است جلگه ای و گرمسیر، مرطوب و مالاریایی و <span class=\"hlight\" dir=\"rtl\">٨١</span> تن سکنه دارد. اهالی فارسی زبانند آب آن از چاه تأمین میشود و محصولاتش غلات و خرما است، و مردم آن به کشاورزی اشتغال دارند. راه آن شوسه ٔ سابق بوشهر - لنگه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(179626, 'عالی آوازه', '<span class=\"hlight\">عالی آوازه .</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (ص مرکب ) خوش آواز. خوش خوان <span class=\"hlight\">:</span> <br />که دیدت بر هیچ رنگین گلی <br />ز من عالی آوازه تر بلبلی .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> نامور. مشهور. بلندنام <span class=\"hlight\">:</span> <br />نظامی بدوعالی آوازه باد<br />به نظمی چنین نام او تازه باد.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(179627, 'عالی اثر', '<span class=\"hlight\">عالی اثر.</span> <font color=\"DarkGreen\"><b>[ اَ ث َ ]</font></b> (ص مرکب ) بلند. رفیع. والا <span class=\"hlight\">:</span> مساحت مملکت اسکندر در نظر همت عالی اثرش تنگ تر از حوصله ٔمردم بخیل است . (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٤</span> از مجلد <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٢</span>).<br /></font></div>'),
(179628, 'عالی احمدان', '<span class=\"hlight\">عالی احمدان .</span> <font color=\"DarkGreen\"><b>[ اَ م َ ]</font></b> (اِخ ) دهی است از دهستان فرامرزان بخش بستک شهرستان لار. واقع در <span class=\"hlight\" dir=\"rtl\">٤٥</span>هزارگزی جنوب باختری بستک در دامنه ٔ جنوبی کوه میرعباس . محلی است گرمسیر و مالاریایی و <span class=\"hlight\" dir=\"rtl\">٥١٥</span> تن سکنه دارد. آب آن از باران تأمین میشود. محصولاتش غلات و خرما دیمی است . اهالی به کشاورزی گذران میکنند. راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(179629, 'عالی انور', '<span class=\"hlight\">عالی انور.</span> <font color=\"DarkGreen\"><b>[ اَن ْ وَ ]</font></b> (اِخ ) تیره ای از طایفه ٔ بابادی هفت لنگ بختیاری . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٧٤</span>).<br /></font></div>'),
(179630, 'عالی بخت', '<span class=\"hlight\">عالی بخت .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ص مرکب ) بلندبخت . کسی که بخت با وی باشد و در کارها موفق گردد.<br /></font></div>'),
(179631, 'عالی بر', '<span class=\"hlight\">عالی بر.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) دهی است از دهستان ماهیدشت پایین بخش مرکزی شهرستان کرمانشاهان . واقع در <span class=\"hlight\" dir=\"rtl\">١١</span>هزارگزی جنوب ماهیدشت و <span class=\"hlight\" dir=\"rtl\">٤</span>هزارگزی جنوب خزل . ناحیه ای است واقع در دامنه ٔ سردسیر و <span class=\"hlight\" dir=\"rtl\">١٧٥</span> تن سکنه دارد. آب آن از چشمه تأمین میشود. محصولاتش غلات، حبوبات، دیم و لبنیات است و اهالی به کشاورزی و گله داری اشتغال دارند. راه مالرو دارد و در تابستان از خزل اتومبیل میتوان برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(179632, 'عالی بلاغ', '<span class=\"hlight\">عالی بلاغ .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) دهی است از دهستان قلعه کری بخش سنقر کلیائی شهرستان کرمانشاهان . واقع در <span class=\"hlight\" dir=\"rtl\">١٤</span>هزارگزی شمال خاوری سنقر واقع در کنار راه عمومی سنقر - خسروآباد. ناحیه ای است کوهستانی سردسیر و <span class=\"hlight\" dir=\"rtl\">١٤٠</span> تن سکنه دارد. آب آن از چشمه تأمین میشود و محصولاتش غلات وحبوبات دیمی و توتون . اهالی به کشاورزی اشتغال دارند و صنایع دستی آنان قالیچه، جاجیم، پلاس بافی میباشد.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(179633, 'عالی بیگی', '<span class=\"hlight\">عالی بیگی .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) تیره ای از طایفه ٔ ملکشاهی است در پشتکوه . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٦٨</span>).<br /></font></div>'),
(179634, 'عالی تبار', '<span class=\"hlight\">عالی تبار.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (ص مرکب ) عالی نسب . آنکه نسب عالی دارد.<br /></font></div>'),
(179635, 'عالی جعفری', '<span class=\"hlight\">عالی جعفری .</span> <font color=\"DarkGreen\"><b>[ ج َ ف َ ]</font></b> (اِخ ) تیره ای از طایفه ٔ کیومرسی ایل چهارلنگ بختیاری . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>).<br /></font></div>'),
(179636, 'عالی جناب', '<span class=\"hlight\">عالی جناب .</span> <font color=\"DarkGreen\"><b>[ ج َ <span class=\"hlight\" dir=\"rtl\">/</span> ج ِ ]</font></b> (اِ مرکب ) لقبی است احتراماً که وزیران و بزرگان را بدان خطاب کنند.<br /></font></div>'),
(179637, 'عالی حسینی', '<span class=\"hlight\">عالی حسینی .</span> <font color=\"DarkGreen\"><b>[ ح ُ س َ ]</font></b> (اِخ ) دهی است از دهستان باغک بخش اهرم شهرستان بوشهر واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی جنوب اهرم . ناحیه ای است واقع در جلگه، گرمسیر و مالاریایی . <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن سکنه دارد. آب آن از چاه تأمین میشود. محصولاتش : غلات، خرما و دیمی است . اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(179638, 'عالی حضرت', '<span class=\"hlight\">عالی حضرت .</span> <font color=\"DarkGreen\"><b>[ ح َ رَ ]</font></b> (اِ مرکب ) آنکه مقام بالا دارد. (ناظم الاطباء). رجوع به عالیجناب شود.<br /></font></div>'),
(179639, 'عالی ذکر', '<span class=\"hlight\">عالی ذکر.</span> <font color=\"DarkGreen\"><b>[ ذِ ]</font></b> (ص مرکب ) آنکه همواره نام او بخوبی برده شود <span class=\"hlight\">:</span> و دائم موقر و محترم و عالی الذکر و نافذ الامر و مهیب و مطاع و سرور و دین پرور باد. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(179640, 'عالی رتبه', '<span class=\"hlight\">عالی رتبه .</span> <font color=\"DarkGreen\"><b>[ رُ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (ص مرکب ) عالی مرتبت . آنکه را مقام بالا و برتر باشد.<br /></font></div>'),
(179641, 'عالی سر', '<span class=\"hlight\">عالی سر.</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِخ ) دهی است جزء دهستان پائین بخش طالقان شهرستان تهران . واقع در <span class=\"hlight\" dir=\"rtl\">٢١</span>هزارگزی باختری شهرک، کنار راه عمومی مالرو قزوین . کوهستانی و سردسیر. <span class=\"hlight\" dir=\"rtl\">٨٢</span> تن سکنه دارد. آب آن از چشمه تأمین میشود. محصولاتش غلات، لوبیا، سیب زمینی، شغل اهالی زراعت صنایع دستی کرباس و گلیم وجاجیم بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(179642, 'عالی سرای', '<span class=\"hlight\">عالی سرای .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِ مرکب ) قصرسلطنتی و سرای پادشاهی و حرم خانه . (ناظم الاطباء).<br /></font></div>'),
(179643, 'عالی شاخ', '<span class=\"hlight\">عالی شاخ .</span>(ص مرکب ) شاخ بلند. دارای شاخه های دراز <span class=\"hlight\">:</span> <br />به که با این درخت عالی شاخ <br />نشود دست هر کسی گستاخ .<br /> <font color=\"Red\">نظامی .</font><br />به درختی سطبر و عالی شاخ <br />سبز و پاکیزه و بلند و فراخ .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(179644, 'عالی شرف', '<span class=\"hlight\">عالی شرف .</span> <font color=\"DarkGreen\"><b>[ ش َ رَ ]</font></b> (اِخ ) نامش میرزا محمد حسین خلف صدق میرزا محمد. کلانتر سابق فارس و از اجله ٔ سادات آن سامان است . او را اخلاق نیکو بود و محضرش مجمع شعرا و عرفا و فضلاء و در حدود <span class=\"hlight\" dir=\"rtl\">١٢٣٦</span>هَ . ق . درگذشت . و به قول صاحب آثار العجم در <span class=\"hlight\" dir=\"rtl\">١٢٤٣</span> در قید حیات بود. غالب اشعارش غزل بود و از جمله اشعار اوست در وصف قلعه ٔ شریفه ٔ مشهد مقدس حضرت حسین :<br />این نغز باره چیست که از بس شکوه و فر<br />گوئی برون نموده ز جیب سپهر سر<br />این سد طرفه چیست که از غایت علو<br />کیوان بدامنش بود از فرق بی سپر.<br /> <font color=\"Red\">(مجمعالفصحاء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥١</span>).</font><br />و رجوع به ریحانة الادب شود.<br /></font></div>'),
(179645, 'عالی شرف', '<span class=\"hlight\">عالی شرف .</span> <font color=\"DarkGreen\"><b>[ ش َ رَ ]</font></b> (ص مرکب ) آنکه شرف عالی دارد <span class=\"hlight\">:</span> <br />صانع زرین عمل مهتر عالی شرف <br />در ید بیضا رسید دست عمل ران او.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(179646, 'عالی شیرازی', '<span class=\"hlight\">عالی شیرازی .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) میرزا محمد شیرازی متخلص به عالی و ملقب به نعمت خان و بعد به دانشمندخان . یکی از شعرای قرن <span class=\"hlight\" dir=\"rtl\">١٢</span> هجری و معاصر سلطان اورنگ زیب و پسر او بهادر شاه بوده است . او به امر محمدبهادر شاه شاهنامه را در احوال وی بنظم درآورد که در ابتداء آن پنج رباعی سروده است . حاوی تاریخ وفات اورنگ زیب و مدت سلطنت و عمر وی . نعمت خان در تاریخ <span class=\"hlight\" dir=\"rtl\">١١٢٠</span> درگذشت . و او راست اشعار بسیار و دیوان و رسائلی چند مانند: نعمت عظمی، جنگنامه، حسن و عشق، و دو نامه ٔ محاصره ٔ حیدرآباد و غیره . (الذریعة ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٦٧٧</span>).<br /></font></div>'),
(179647, 'عالی طیب', '<span class=\"hlight\">عالی طیب .</span> <font color=\"DarkGreen\"><b>[ طَی ْ ی ِ ]</font></b> (اِخ ) تیره ای از ایل طیبی از ایلات کوه گیلویه ٔ فارس . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٨٩</span>).<br /></font></div>'),
(179648, 'عالی قاپو', '<span class=\"hlight\">عالی قاپو.</span> (اِخ ) نام قصری است از قصور صفویه واقع در میدان شاه اصفهان . و دارای بنای عالی و مرتفع و تاریخی است که همه ساله مسافران و سیاحان خارجی از آن دیدن میکنند و بنابر مشهور تکمیل آن به دست شاه عباس بوده است . رجوع به اصفهان شود.<br /></font></div>'),
(179649, 'عالی قدر', '<span class=\"hlight\">عالی قدر.</span> <font color=\"DarkGreen\"><b>[ ق َ ]</font></b> (ص مرکب ) بلندمرتبت . والامقام . بزرگوار. از القاب احترام که در اول نوشتجات و در سر پاکتها نویسند. (ناظم الاطباء).<br /></font></div>'),
(179650, 'عالی محل', '<span class=\"hlight\">عالی محل .</span> <font color=\"DarkGreen\"><b>[ م َ ح َ ]</font></b> (ص مرکب ) آنکه او را محل و مقام بالا است . والاجاه <span class=\"hlight\">:</span> <br />نگه کرد سلطان عالی محل <br />خودش در بلا دید و خر در وحل .<br /><font color=\"Red\">سعدی (بوستان ).</font><br /></font></div>'),
(179651, 'عالی محمود', '<span class=\"hlight\">عالی محمود.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) علی محمد خانی . یکی از طوائف هفت لنگ بختیاری که در مال امیر سوسن سکنی دارند. (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٧٤</span>).<br /></font></div>'),
(179652, 'عالی مرتبت', '<span class=\"hlight\">عالی مرتبت .</span> <font color=\"DarkGreen\"><b>[ م َ ت َ ب َ ]</font></b> (ص مرکب ) آنکه مرتبت عالی دارد.<br /></font></div>'),
(179653, 'عالی مرتبت گردیدن', '<span class=\"hlight\">عالی مرتبت گردیدن .</span> <font color=\"DarkGreen\"><b>[ م َ ت َ ب َ گ َ دی دَ ]</font></b> (مص مرکب ) مقام عالی و رفیع بدست آوردن .<br /></font></div>'),
(179654, 'عالی مرد', '<span class=\"hlight\">عالی مرد.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (ص مرکب، اِ مرکب ) طالب مولی که دنیا و عقبی را در خیال هم نیارد. (آنندراج ).<br /></font></div>'),
(179655, 'عالی مشرب', '<span class=\"hlight\">عالی مشرب .</span> <font color=\"DarkGreen\"><b>[ م َ رَ ]</font></b> (ص مرکب )آنکه مشرب خوب دارد. خوش مشرب . بلندنظر <span class=\"hlight\">:</span> <br />حافظ ار بر صدر ننشیند زعالی مشربیست <br />عاشق دردی کش اندر بند مال و جاه نیست .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(179656, 'عالی مقام', '<span class=\"hlight\">عالی مقام .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (ص مرکب ) عالیجاه . بلندمرتبت . آنکه مقام رفیع و بالا دارد <span class=\"hlight\">:</span> در سلک سایر خدام عالی مقام تنظیم گردید. (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٢</span>).<br />راز درون پرده ز رندان مست پرس <br />کاین حال نیست زاهد عالی مقام را.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(179657, 'عالی مقدار', '<span class=\"hlight\">عالی مقدار.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ص مرکب ) بزرگوار. از القاب احترام است که در اول نامه و پاکتها نویسند. (ناظم الاطباء).<br /></font></div>'),
(179658, 'عالی منزلت', '<span class=\"hlight\">عالی منزلت .</span> <font color=\"DarkGreen\"><b>[ م َ زِ ل َ ]</font></b> (ص مرکب ) آنکه منزلت شریف دارد. بزرگوار <span class=\"hlight\">:</span> یعنی حضرت عالی منزلت ممالک مدار متعال منقبت معالی دثار. (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(179659, 'عالی مکان', '<span class=\"hlight\">عالی مکان .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (ص مرکب ) آنکه منزلت و مقام رفیع دارد. آنکه مکان شریف دارد. عالیقدر. عالیجاه <span class=\"hlight\">:</span> <br />بگشا ز بال همت عالی مکان گره <br />تا کی شوی چو بیضه در این آشیان گره .<br /><font color=\"Red\">صائب (از آنندراج ).</font><br /></font></div>'),
(179660, 'عالی نسب', '<span class=\"hlight\">عالی نسب .</span> <font color=\"DarkGreen\"><b>[ ن َ س َ ]</font></b> (ص مرکب ) آنکه او را نسب عالی باشد. عالی تبار <span class=\"hlight\">:</span> نظر همت این پادشاه عالی نسب متعالی حسب . (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٢٤٤</span>).<br />اصل گهر از خلیفه داریم <br />عالی نسبیم اگر یتیمیم .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(179661, 'عالی نژاد', '<span class=\"hlight\">عالی نژاد.</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ص مرکب ) آنکه اصل و نسب عالی دارد. عالی گهر. عالی تبار <span class=\"hlight\">:</span> <br />امیر جهانگیر عالی نژاد<br />چون پا بر سریر ایالت نهاد.<br /><font color=\"Red\">(حبیب السیر ص <span class=\"hlight\" dir=\"rtl\">١٢٥</span>).</font><br /></font></div>'),
(179662, 'عالی همت', '<span class=\"hlight\">عالی همت .</span> <font color=\"DarkGreen\"><b>[ هَِ م ْ م َ ]</font></b> (ص مرکب ) آنکه همت عالی دارد. بلندهمت و شریف . بزرگوار. کریم و سخی . جوانمرد. (ناظم الاطباء) <span class=\"hlight\">:</span> <br />گر از شمشیر برگردی نه عالی همتی سعدی <br />تو کز نیشی بیازردی نخواهی انگبین رفتن . <br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(179663, 'عالی همتی', '<span class=\"hlight\">عالی همتی .</span><font color=\"DarkGreen\"><b>[ هَِ م م َ ]</font></b> (حامص مرکب ) بلندهمتی . جوانمردی . سخاوت . (ناظم الاطباء). رجوع به عالی همت شود <span class=\"hlight\">:</span> <br />ز عالی همتی گردن برافراز<br />طناب هرزه از گردن بینداز.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(179664, 'عالی و جمالی', '<span class=\"hlight\">عالی و جمالی .</span> <font color=\"DarkGreen\"><b>[ وَ ج َ ]</font></b> (اِخ ) جزء طائفه ٔ هفت لنگ از ایل بختیاری ایران است . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(179665, 'عالی ود', '<span class=\"hlight\">عالی ود.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِخ ) شعبه ای از طایفه ٔ عالی انور هفت لنگ بختیاری . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٧٤</span>).<br /></font></div>'),
(179666, 'عالی چنگی', '<span class=\"hlight\">عالی چنگی .</span> <font color=\"DarkGreen\"><b>[ چ َ ]</font></b> (اِخ ) دهی است از دهستان باغک بخش اهرم شهرستان بوشهر. واقع در <span class=\"hlight\" dir=\"rtl\">٢٣</span>هزارگزی شمال باختر اهرم و کنار راه فرعی بوشهر به اهرم . واقع در جلگه، گرمسیر، مرطوب و مالاریایی است و <span class=\"hlight\" dir=\"rtl\">٧٤٢</span> تن سکنه دارد. آب آن از چاه تأمین میشود. محصولاتش غلات، خرما و تنباکو و مردم به کشاورزی اشتغال دارند. راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(179667, 'عالی کردستانی', '<span class=\"hlight\">عالی کردستانی .</span> <font color=\"DarkGreen\"><b>[ ی ِ ک ُ دِ ]</font></b> (اِخ ) میرزا محمد حسین عالی کردستانی . یکی از شعرای عرفان مشرب بود و از اشعار اوست :<br />دل رفت و کسی نیست مرا واقف اسرار<br />جزآنکه چو من نوسفری داشته باشد.<br /><font color=\"Red\">(مجمع الفصحاء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥١</span>).</font><br /></font></div>'),
(179668, 'عالی گهر', '<span class=\"hlight\">عالی گهر.</span> <font color=\"DarkGreen\"><b>[ گ ُ هََ ]</font></b> (ص مرکب ) پاک نژاد. شریف نسب <span class=\"hlight\">:</span> منظورنظر صاحبقران عالی گهر گشت . (حبیب السیر ص <span class=\"hlight\" dir=\"rtl\">١٢٥</span>). <BR><font color=\"Blue\">◄</font> (اِ مرکب ) گوهر گران بها. (ناظم الاطباء).<br /></font></div>'),
(179669, 'عالیات', '<span class=\"hlight\">عالیات .</span> (ع ص، اِ) ج ِ عالیة. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> چیزهای بلند و رفیع. (ناظم الاطباء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عتبات عالیات </span> ؛ آستانه های بلند که مراد قبور ائمه ٔ عراق باشد. (ناظم الاطباء).<br /></font></div>'),
(179670, 'عالیة', '<span class=\"hlight\">عالیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) مؤنث عالی . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) نوک سرنیزه یا سر آن یا نصفش که متصل به سنان است . (المنجد) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> (اِخ ) زمین مافوق نجد تا متصل به تهامه و تا سرحد مکه ٔ معظمه و آن حجاز است و دِه هاست بر سواد مدینه و آن را عوالی خوانند. نسبت بسوی عالی و عُلوی از جهت آنکه «عالیة الشی ٔ» بلندترین از چیزی را گویند. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> سرزمین حجاز که مشتمل است بر بلاد واسعه و مواضع شریفه، و یا آن قسمتی که از رمه تجاوز میکند تا مکه و یا مشتمل است بر همه ٔ آن قسمتی از قریه ها و آبادیهای مدینه که از طرف نجد تا تهامه یافت میشود و قسمت واقعه در مابین را سافله گویند. (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٠</span>). <BR><font color=\"Blue\">◄</font> (ص ) حروف عالیه و عالیات عقول و نفوس طولیه و عرضیه اند که کلمات اﷲ التامات هم گویند. (از کشاف اصطلاحات الفنون ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٧</span>). رجوع به حروف عالیه شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مدارج عالیه </span> ؛ درجه های بالا.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مدارس عالیه </span> ؛ دانشکده ها و دانشگاهها.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مقامات عالیه </span> ؛ مقامات بالا.<br /></font></div>'),
(179671, 'عالیة', '<span class=\"hlight\">عالیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) مؤلف حبیب السیر آرد که : بقولی نام دختر علی النقی (ع ) عالیة بوده است . (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩٨</span>).<br /></font></div>'),
(179672, 'عالیة', '<span class=\"hlight\">عالیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) نام دختر هارون الرشید بود. (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٦</span>).<br /></font></div>'),
(179673, 'عالیجاه', '<span class=\"hlight\">عالیجاه .</span> (ص مرکب ) عالی شأن . عالی رتبت . عالی قدر. آنکه مرتبت بلند و مقام بالا دارد. <BR><font color=\"Blue\">◄</font> از القاب احترام که اکثر در اول نوشته ها و نامه هایا در سرپاکتها نویسند. (ناظم الاطباء) <span class=\"hlight\">:</span> <br />اطهر اشرف شه آل حسین بن علی <br />آنکه عالی جاه او هر روز عالیتر سزد.<br /> <font color=\"Red\">سوزنی .</font><br />پادشاه عالیجاه یک دو هفته آنجا به اسب تاختن و... پرداخت . (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٢</span>).<br /></font></div>'),
(179674, 'عالیشان', '<span class=\"hlight\">عالیشان .</span> (ص مرکب ) عالیشأن . خداوندِ مرتبت اعلی . <BR><font color=\"Blue\">◄</font> از القاب پادشاهی . <BR><font color=\"Blue\">◄</font> بسیار نجیب . <BR><font color=\"Blue\">◄</font> باجلال . بلند مرتبت . (ناظم الاطباء). عالی مقام و دانشمند بزرگ <span class=\"hlight\">:</span> مورخان عالیشأن بر این منوال مسطور گردانید. (حبیب السیر ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span>).<br /></font></div>'),
(179675, 'عالیشان', '<span class=\"hlight\">عالیشان .</span> (اِخ ) دهی است از دهستان چری بخش حومه ٔ شهرستان قوچان . واقع در <span class=\"hlight\" dir=\"rtl\">٣٦</span>هزارگزی جنوب باختری قوچان . ناحیه ای است کوهستانی و سردسیر که <span class=\"hlight\" dir=\"rtl\">٧٢</span> تن سکنه دارد. آب آن از چشمه تأمین میشود. محصولاتش غلات و اهالی به کشاورزی و مالداری اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179676, 'عالیوند', '<span class=\"hlight\">عالیوند.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِخ ) تیره ای از طایفه ٔ کیومرسی ایل چهارلنگ بختیاری . رجوع به تل ریزی شود. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(179677, 'عام', '<span class=\"hlight\">عام .</span> (ع اِ) سال . ج، اَعوام . (مهذب الاسماء) (اقرب الموارد)(غیاث اللغات ) (آنندراج ) (منتهی الارب ) <span class=\"hlight\">:</span> <br />تا عام نام سال بود شهر نام ماه <br />اقبال را نظر بسوی شهر و عام نیست .<br /></font></div>'),
(179678, 'عام', '<span class=\"hlight\">عام .</span> <font color=\"DarkGreen\"><b>[ عام م ]</font></b> (ع ص، اِ) مقابل خاص . (منتهی الارب )(المنجد) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> همگانی . همگان . تمام مردم . (منتهی الارب ) (آنندراج ) <span class=\"hlight\">:</span> <br />ناممکن است این سخن بر خاص <br />لفظی است این در میانه ٔ عام .<br /> <font color=\"Red\">فرخی .</font><br />مجوی از وحدت محضش برون از ذات او چیزی <br />که او عامست و ماهیات خاص اندر همه اشیاء.<br /> <font color=\"Red\">ناصرخسرو.</font><br />و آگاه کن ای برادر از غدرش <br />دور و نزدیک و خاص و عامش را.<br /> <font color=\"Red\">ناصرخسرو.</font><br />در آن مجلس که بهر عام کردند<br />میی همچون شفق در جام کردند.<br /> <font color=\"Red\">نظامی .</font><br />تکاپوی ترکان و غوغای عام <br />تماشاکنان بر در و کوی و بام .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> تمام، هرچه باشد. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نادان . در تداول مردم عوام یعنی مردم جاهل و نادان <span class=\"hlight\">:</span> <br />سلام کن ز من ای باد مر خراسان را<br />مر اهل فضل و خرد را نه عام و نادان را.<br /> <font color=\"Red\">ناصرخسرو.</font><br />عام نادان پریشان روزگار<br />به ز دانشمند ناپرهیزکار.<br /><font color=\"Red\">سعدی (گلستان ).</font><br />اندر آیینه چه بیند مرد عام <br />که نبیند پیر اندر خشت خام .<br /> <font color=\"Red\">مولوی .</font><br />با زاهد بی ذوق مگو سر انا الحق <br />اسرار سلاطین چو به عامان نتوان گفت .<br /> <font color=\"Red\">اسیری لاهیجی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">اسم عام </span> ؛ در مقابل اسم خاص که در عربی علم گویند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بار عام </span> ؛ ملاقات عمومی . اجازه ٔ همگانی <span class=\"hlight\">:</span> <br />زمین را زیرتخت آرام داده <br />برسم خاص بار عام داده .<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">شارع عام </span> ؛ راه عمومی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">وقف عام </span> ؛ در مقابل وقف خاص . رجوع به وقف شود.<br /></font></div>'),
(179679, 'عام ارمل', '<span class=\"hlight\">عام ارمل .</span> <font color=\"DarkGreen\"><b>[ م ِ اَ م َ ]</font></b> (ترکیب وصفی، اِ مرکب ) سال اندک باران . (مهذب الاسماء).<br /></font></div>'),
(179680, 'عام المجاعة', '<span class=\"hlight\">عام المجاعة.</span> <font color=\"DarkGreen\"><b>[ مُل م َ ع َ ]</font></b> (ع اِ مرکب ) سال قحط.<br /></font></div>'),
(179681, 'عامة', '<span class=\"hlight\">عامة.</span> <font color=\"DarkGreen\"><b>[ م م َ ]</font></b> (ع اِ) مردم بی علم و فرومایه . <BR><font color=\"Blue\">◄</font> هر چیز که شامل همه گردد و عمومیت داشته باشد. (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> چوبهای بهم بسته که بدان از دریا و جوی گذرند و صواب عامَه است . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مقابل خاصه . همه ٔ مردم . (منتهی الارب ) (ناظم الاطباء). قیامت بدان جهت که همه را فراگیرد. <BR><font color=\"Blue\">◄</font> جماعة و فی حدیث عثمان انّک امام عامة؛ ای امام الجماعة. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بیخ دستار.<br /></font></div>'),
(179682, 'عامد', '<span class=\"hlight\">عامد.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) قصدکننده . آهنگ کننده . (اقرب الموارد) (المنجد).<br /></font></div>'),
(179683, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن عبدری یا عامربن عمروبن وهب القرشی العبدری یکی از رجال شریف و بزرگوار و ادیب اندلس بوده و مقبره ٔ عامر را به قرطبه بدو نسبت دهند. وی به سال <span class=\"hlight\" dir=\"rtl\">١٣٨</span> هَ . ق . بدست یوسف بن عبدالرحمان الفهری به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(179684, 'عامر', '<span class=\"hlight\">عامر.</span><font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن عبداﷲ، مکنی به ابوبرده از قضات کوفه بود و او را کرم و جود و محاسن بسیاری بوده است .وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(179685, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[م ِ ]</font></b> (اِخ ) ابن ظرب العدوانی حکیم و خطیب و از رؤسای جاهلیت بوده و او را ذوالحلم نیز میگفتند وی در میان اعراب نفوذ خاصی داشته است . (از الاعلام زرکلی ).<br /></font></div>'),
(179686, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن عبداﷲبن شراحیل الشعبی الحمیری . مولد و منشاء آن کوفه و از یاران و ندمای عبدالملک بن مروان و از رجال حدیث و ثقات و فقهاء و شعرا بود. وی را عمربن عبدالعزیز به قضاوت برگزید. تولد وی سال <span class=\"hlight\" dir=\"rtl\">١٩</span> هَ . ق . بود و به سال <span class=\"hlight\" dir=\"rtl\">١٠٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(179687, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن عبداﷲبن عبداﷲ ملقب به ابوعبیدة جراح . رجوع به ابوعبیده ٔ جراح شود.<br /></font></div>'),
(179688, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن ربیعةبن عامربن صعصعة از هوازن از عدنانیة. جد جاهلی است . (از الاعلام زرکلی ).<br /></font></div>'),
(179689, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن طُفیل بن مالک بن جعفر العامری از بنی عامربن صعصعة. از شعرا و بزرگان عرب در جاهلیت بود. مولد و منشاء او به نجد بوده است . او مردی بود با جود و کرم که به امر او همواره در بازار عکاظ بواسطه ٔ جارچی آمادگی خود را جهت هرگونه خدمت به مردم اعلام میداشت او در سنین پیری اسلام را درک نمود و در مدینه خدمت حضرت رسول رسید حضرت او را به اسلام دعوت کرد او شرائطی داشت که از جمله بعد از حضرت ولی امور باشد و آخر الامر تسلیم نشده و بدون نتیجه بازگشت و در ضمن راه در سال <span class=\"hlight\" dir=\"rtl\">١١</span> هَ . ق . وفات یافت و در ریحانة الادب است که در سال <span class=\"hlight\" dir=\"rtl\">٦٣٢</span> م . درگذشت . (از الاعلام زرکلی ). و رجوع به ریحانة الادب شود.<br /></font></div>'),
(179690, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن ضُبارة المری . از قائدان و سواران بود. مروان بن محمد برای جنگ با شیبان خارجی او را نزد خود طلبید و هفت هزار تن را در اختیار وی گذاشت عامر با لشکر مزبور به پیکار شیبان رفت و شیبان پس از چندین نبرد منهزم شد آنگاه عامر برای پیکار باعبداﷲبن معاویة الطالبی به دستور ابن هبیره با <span class=\"hlight\" dir=\"rtl\">٥٠</span> هزار سوار بجنگ قحطبةبن شیب به اصفهان وارد و از لشکران قحطبه که <span class=\"hlight\" dir=\"rtl\">٢٠</span> هزار تن بودند شکست خورد. وی عاقبت در سال <span class=\"hlight\" dir=\"rtl\">١٣١</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(179691, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن صعصعةبن معاویةبن بکر از قیس عیلان از عدنانیة. جد جاهلی است . از فرزندان او بطون بسیاری یاد کرده اند. (از الاعلام زرکلی ).<br /></font></div>'),
(179692, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن صالح بن عبداﷲ الزبیدی فقیه و عالم به حدیث و انساب و ایام و اشعار عرب بوده شعر هم می سرود. وی زادگاهش مدینه و ساکن بغداد بود و به سال <span class=\"hlight\" dir=\"rtl\">١٥٢</span> هَ . ق . در همانجا درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(179693, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن سعدبن مالک بن النخع از قحطان جد جاهلی است . (از الاعلام زرکلی ).<br /></font></div>'),
(179694, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) یکی از قبایل عشیرالکبیرة است . (از معجم قبائل العرب ).<br /></font></div>'),
(179695, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن عبدالوهاب . رجوع به ظافرصلاح الدین عامر الظافر در این لغت نامه و الاعلام زرکلی شود.<br /></font></div>'),
(179696, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن عبدی مناة بطنی است . از کنانةبن خزیمه از عدنانیه که به نام بنوعامربن عبدمناةبن کنانةبن خزیمةبن مدرکةبن الیاس خوانده میشدند. (ازمعجم قبائل العرب ).<br /></font></div>'),
(179697, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن عُذرةبن زید از بنی کلب از قحطانیه جد جاهلی است . (از الاعلام زرکلی ).<br /></font></div>'),
(179698, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ )ابن علی بن محمد الحسینی الزیدی . امیر یمانی از فضلاءو شجعان و ساکن شبام یمن بود با پسر برادر خود قاسم بن محمد قیام کرد و با ترکان جنگید و پیکارهای وی باترکان در کوکبان مشهور است و آخرالامر بدست یاران کدخدا سنان افتاد و به امر وی پوست او را کندند و پر از کاه کردند و در کوکبان و شبام گرداندند. قتل وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٠٨</span> هَ . ق . اتفاق افتاد. (از الاعلام زرکلی ).<br /></font></div>'),
(179699, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن عَمارةبن خزیم الناعم بن عمروبن الحارث الغطفانی المری، مکنی به ابوالهیذام . رئیس مضریه در شام و یکی از سواران عرب بوده است . ابن اثیر از او داستانها آورده است . وفات وی به سال <span class=\"hlight\" dir=\"rtl\">١٨٢</span> هَ . ق . افتاد. (از الاعلام زرکلی ).<br /></font></div>'),
(179700, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن عوف بن بکر از بنی عذرة از کلب از قحطان و جدجاهلی است و فرزندان وی را بنو المزمم گویند. (از الاعلام زرکلی چ <span class=\"hlight\" dir=\"rtl\">١</span>). و رجوع به معجم قبائل العرب شود.<br /></font></div>'),
(179701, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن عوف بن کعب، از کنانة از عدنان جد جاهلی است . (از الاعلام زرکلی ).<br /></font></div>'),
(179702, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن عوف بن مالک از بنی عامربن صعصعه از هوازن از عدنان جد جاهلی است . مسکن خاندان وی در نواحی بصره بود و در اواسط قرن <span class=\"hlight\" dir=\"rtl\">٧</span> هَ . ق . مالک سرزمین بحرین و یمامة شدند. (از الاعلام زرکلی ).<br /></font></div>'),
(179703, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن غیلان بن سلمةبن ثقفی یکی از صحابیان است که بعد از فتح طائف اسلام آورد و به همراهی خالدبن ولید به شام رفت و یکی از سواران قبیله ٔ ثقیف بود و به سال <span class=\"hlight\" dir=\"rtl\">١٨</span> هَ . ق . به مرض طاعون مرد. (از الاعلام زرکلی ).<br /></font></div>'),
(179704, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن وائله . رجوع به ابوطفیل در این لغت نامه و الاعلام زرکلی شود.<br /></font></div>'),
(179705, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن هِلال بن صعصعةبن عامر از قیس عیلان از عدنانیه . جد جاهلی است، بطون رفاعه و بنوحجیر و بنوغریر از نسل وی بودند، که مسکن آنان در بعضی از قراء اخمیمیه از دیار مصر بود. (از الاعلام زرکلی ). و رجوع به معجم قبائل العرب شود.<br /></font></div>'),
(179706, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) آبادکننده . (اقرب الموارد) (آنندراج ) (مهذب الاسماء) (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> آباد و معمور. (ناظم الاطباء). و بر این تقدیر عامر به معنی معمور باشد چون دافق بمعنی مدفوق . (منتهی الارب ) (آنندراج ) (غیاث ). <BR><font color=\"Blue\">◄</font> زیارت کننده . ج، عمار. (آنندراج ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اقامت کننده در محل معمور. (اقرب الموارد) (المنجد). <BR><font color=\"Blue\">◄</font> ساکن خانه . (منتهی الارب ). زیاد عمر کننده . <BR><font color=\"Blue\">◄</font> بسیار و فراوان .(ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ) بچه ٔ کفتار. ام عامر. (منتهی الارب ) (آنندراج ) (اقرب الموارد) (المنجد). <BR><font color=\"Blue\">◄</font> مار از جهت طول عمر. عوامر البیوت : هی الحیات . (المنجد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نام مردی است . (مهذب الاسماء) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179707, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) بطنی است از آل ربیعه به شام و منزل و مأوای آنان در بادیة الشام است . (از معجم قبائل العرب ).<br /></font></div>'),
(179708, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) جد جاهلی است پسران او بطنی از لواثه از قیس عیلان یا از بربرند و منزل و مأوای آنان به بهنسا از دیار مصر بوده است . (از الاعلام زرکلی ).<br /></font></div>'),
(179709, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) بطنی است بزرگ از بنی کلب . (معجم قبائل العرب ).<br /></font></div>'),
(179710, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) از قبائل عرب در جزائرند و مرکز آنها میان و هران و تلمسان است . (معجم قبائل العرب ).<br /></font></div>'),
(179711, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) عشیره ای است که در زمانهای قدیم به ناحیه کورة به منطقه ٔ عجلون سکونت داشته و اکنون در قراء رحابا و کفرالماء پراکنده اند. (از معجم قبائل العرب ).<br /></font></div>'),
(179712, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) عشیره ای است معروف به بوعامر، در اماکن متعدد در عراق که در نجف و رزازة و یوسفیه پراکنده اند و شغل آنان تربیت گاومیش است عده ٔ نفوس آنها بالغ بر شش هزار است . (از معجم قبائل العرب ).<br /></font></div>'),
(179713, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) عشیره ٔ درزیه است مقیم در جبل حوران . اصل آن عشیره از آل ایوب به جبل اعلی از توابع حلب بوده است . (از معجم قبائل العرب ).<br /></font></div>'),
(179714, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) عشیره ای است که معروف به عیال عامرند. (از معجم قبائل العرب ).<br /></font></div>'),
(179715, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) بطنی است از قبیله سُبَیع مقیم عارض . (از معجم قبائل العرب ).<br /></font></div>'),
(179716, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) عشیره ٔ بزرگی است از فضل از طوقه از بنی صخره یکی از قبائل بادیه ٔ شرق اردن . (از معجم قبائل العرب ).<br /></font></div>'),
(179717, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) بطنی است از کلاب بن ربیعةبن عامربن صعصعةبن معاویةبن بکربن هوازن منصوربن عکرمةبن خصفةبن قیس بن عَیلان از عدنانیه . (از معجم قبائل العرب ).<br /></font></div>'),
(179718, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن ذُهل بن ثعلبة، از بنی بکربن وائل از عدنان . جد جاهلی است . (از الاعلام زرکلی ).<br /></font></div>'),
(179719, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) بطنی است از سعدبن عمربن خُزاعةبن ربیعةبن حارثةبن عمرو مُزَیقیاء از غسان از ازد از قحطانیه . (از معجم قبائل العرب ).<br /></font></div>'),
(179720, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) قبیله ای است از بنی ضَیّه از عدنانیه . (از معجم قبائل العرب ).<br /></font></div>'),
(179721, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) عشیره ای است از آل عمر از آل کثیر یکی از قبائل حضرموت . (از معجم قبائل العرب ).<br /></font></div>'),
(179722, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) بطنی است از خفاجةبن عمربن عُقیل بن کعب بن ربیعةبن عامربن صعصعةبن معاویةبن بکربن هوازن بن منصوربن عکرمةبن خصفةبن قیس بن عیلان از عدنانیه . (از معجم قبائل العرب ).<br /></font></div>'),
(179723, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) (متوفی به سال <span class=\"hlight\" dir=\"rtl\">٧</span> هَ . ق .) ابن الاکوع یا عامربن سنان الاکوع بن عبداﷲبن بشیر الاسلمی . از شعرای عرب بود و او راصحبتی بود و تا جنگ خیبر بزیست . در آن جنگ یکی از یهودیان را به قتل رساند و به واسطه ٔ جراحتی که از روی خطا به خود وارد آورد درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(179724, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) مکنی به ابوعبیدةبن جراح صحابی است که نامش عامربن عبیداﷲبن الجراح است منسوب بجد. (منتهی الارب ). رجوع به ابوعبید جراج شود.<br /></font></div>'),
(179725, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن ثعلبة. بطنی است از کنانة از عدنانیة و آنان بنوعامربن ثعلبةبن حارث بن مالک بن کنانةبن خُزیمة معدبن عدنان بودند. (از معجم قبائل العرب ). و رجوع به الاعلام زرکلی شود.<br /></font></div>'),
(179726, 'عامر', '<span class=\"hlight\">عامر.</span><font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن حارثةبن الغطریف الازدی ... ملقب به ماء السماء بوده . از یمن مهاجرت کرد و در بادیة الشام سکونت گزید و پسران او را بنوماء السماء نامند. (از الاعلام زرکلی ). و رجوع به معجم قبائل العرب شود.<br /></font></div>'),
(179727, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن حفص ابوالیقظان ملقب به سحیم . عالم به انساب بود. او راست : اخبار تمیم و کتاب النسب الکبیر. وی به سال <span class=\"hlight\" dir=\"rtl\">١٩٠</span> هَ . ق . وفات یافته است . (از الاعلام زرکلی ).<br /></font></div>'),
(179728, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن حنیفةبن لجیم از بنی بکربن وائل از عدنان . جد جاهلی است . (از الاعلام زرکلی ).<br /></font></div>'),
(179729, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن داود از بنی طاهر. امیرعدن و از بقایای بنی طاهر بود که در یمن فرمانروایی داشتند و به سال <span class=\"hlight\" dir=\"rtl\">٩٤٥</span> هَ . ق .بدست سلیمان پاشا به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(179730, 'عامر', '<span class=\"hlight\">عامر.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابن ذَبیان بطنی است از بکربن وائل از عدنانیه و آنان بنوعامربن ذبیان بن کنانةاند. (از معجم قبائل العرب ).<br /></font></div>'),
(179731, 'عامر عنزی', '<span class=\"hlight\">عامر عنزی .</span> <font color=\"DarkGreen\"><b>[ م ِ رِ ع َ ]</font></b> (اِخ ) عامربن ربیعةبن کعب العنزی از صحابیان و ولات است . وی در تمام جنگها حضرت رسول را همراهی کرد و هم او را عثمان بن عفان در موقع مسافرت به مکه جانشین خود قرار داد. و او راست : <span class=\"hlight\" dir=\"rtl\">٢٢</span>حدیث در صحیحین مسلم و بخاری و از صحابیانی است که ناظر شورش مردم بر ضد عثمان بود و چند روزی بعد از قتل عثمان در <span class=\"hlight\" dir=\"rtl\">٣٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(179732, 'عامری', '<span class=\"hlight\">عامری .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) دهی است از دهستان ساحل بخش اهرم شهرستان بوشهر. واقع در <span class=\"hlight\" dir=\"rtl\">٣٣</span> هزارگزی جنوب باختر اهرم در ساحل دریا، کنار راه ساحلی سابق . محلی است جلگه ٔ گرمسیر، مرطوب و مالاریایی . <span class=\"hlight\" dir=\"rtl\">٤١٦</span> تن سکنه دارد. آب آن از چاه تأمین میشود و محصولات آن غلات دیمی و خرماست . اهالی به کشاورزی و صید ماهی اشتغال دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(179733, 'عامری', '<span class=\"hlight\">عامری .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) دهی است از دهستان لیراوی بخش دیلم شهرستان بوشهر. واقع در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی شمال دیلم و شش هزارگزی ساحل در کنار راه فرعی دیلم به هندیجان . محلی است جلگه ٔ گرمسیر، مرطوب و مالاریایی و <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> تن سکنه دارد. آب آن از چاه تأمین میشود. محصولات آن غلات دیم و سبزیجات است و اهالی به کشاورزی اشتغال دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(179734, 'عامری', '<span class=\"hlight\">عامری .</span> <font color=\"DarkGreen\"><b>[م ِ ]</font></b> (اِخ ) یحیی بن بکر عامری یمنی ملقب به عمادالدین و مکنی به ابوزکریا از فضلاء و محدثان عامه بود. وی به سال <span class=\"hlight\" dir=\"rtl\">٨٩٣</span> هَ . ق . درگذشت . از تألیفات او است : بهجة المحافل فی السیر و المعجزات و الشمائل . (ریحانةالادب ). و رجوع به معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٦١</span> شود.<br /></font></div>'),
(179735, 'عامری', '<span class=\"hlight\">عامری .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) لبیدبن ربیعةبن مالک . رجوع به لبید شود.<br /></font></div>'),
(179736, 'عامری', '<span class=\"hlight\">عامری .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ص نسبی ) منسوب به قبیله ٔ بنی عامر از قبائل عرب است که سرسلسله ٔ ایشان عامربن صعصعةبن معاویةبن بکربن هوازن بودو این عنوان عامری در رجال لقب ابان بن کثیر و احمدبن رشید و اسماعیل بن جعفر و حاشدبن مهاجربن و حبةبن بعلبک و حسین بن عثمان و عبیدبن کثیر و عثمان بن عیسی وجمع بسیاری دیگر است . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٥١</span>).<br /></font></div>'),
(179737, 'عامریه', '<span class=\"hlight\">عامریه .</span> <font color=\"DarkGreen\"><b>[ م ِ ری ی َ ]</font></b> (اِخ ) ده کوچکی است از بخش راین شهرستان بم، واقع در <span class=\"hlight\" dir=\"rtl\">٢٠</span>هزارگزی جنوب خاوری راین و <span class=\"hlight\" dir=\"rtl\">١٥</span>هزارگزی باختر راه شوسه ٔ بم به کرمان . <span class=\"hlight\" dir=\"rtl\">٢٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179738, 'عامریون', '<span class=\"hlight\">عامریون .</span> <font color=\"DarkGreen\"><b>[ م ِ ری یو ]</font></b> (اِخ ) منسوب به عامربن کنانةاند. (از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥١</span>). و رجوع به عامری شود.<br /></font></div>'),
(179739, 'عامص', '<span class=\"hlight\">عامص .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع اِ) خامیز که نوعی از طعام باشد که از گوشت و پوست گوساله ترتیب دهند یا شوربای سکباج که سرد نموده روغن دور سازند. (منتهی الارب ) (آنندراج ). و صاحب اقرب الموارد آرد: عامص طعامی است .<br /></font></div>'),
(179740, 'عامق', '<span class=\"hlight\">عامق .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) بعیر عامق ؛ شتر که گیاه «عمقی » خورد. (منتهی الارب ) (آنندراج ) (مهذب الاسماء).<br /></font></div>'),
(179741, 'عامل', '<span class=\"hlight\">عامل .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ع ص ) کارکن و صنعتگر. <BR><font color=\"Blue\">◄</font> کسی که با دست کار کند. (منتهی الارب ) (ناظم الاطباء). هر که با دست کار گل ساختمان و بناء آن کند. (از اقرب الموارد) (المنجد) گلکار. <BR><font color=\"Blue\">◄</font> کسی که متصدی کارهای دیگر شوددر امور مالی و غیره . (المنجد). ضابط. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> دیوانی . نوکر. دولت . رئیس . والی . حاکم . (المنجد). ج، عمال و عاملون و عمله <span class=\"hlight\">:</span> <br />به معزولی به چشمم در نشستی <br />چو عامل گشتی از من چشم بستی .<br /><font color=\"Red\">نظامی .</font><br />نهد عامل سفله بر خلق رنج <br />که تدبیر ملک است و توفیر گنج .<br /> <font color=\"Red\">سعدی (بوستان چ یوسفی ص <span class=\"hlight\" dir=\"rtl\">١٥٧</span>).</font><br />نیاورده عامل غش اندر میان <br />نیندیشد از رفع دیوانیان .<br /> <font color=\"Red\">سعدی .</font><br />تا نگویی که عاملان حریص <br />نیکخواهان دولت شاهند.<br /> <font color=\"Red\">سعدی .</font><br /><BR><font color=\"Blue\">◄</font> دانا. زبردست در هر کاری . <BR><font color=\"Blue\">◄</font> وکیل و کارگزار. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> کلمه ای که بدان اعراب کلمه ٔ دیگر تغییر می کند. ج، عوامل . (منتهی الارب ) (ناظم الاطباء) (تعریفات ) (مهذب الاسماء).و رجوع به عوامل شود.<br /></font></div>'),
(179742, 'عامل الرمح', '<span class=\"hlight\">عامل الرمح .</span> <font color=\"DarkGreen\"><b>[ م ِ لُرْ رُ ]</font></b> (ع اِ مرکب ) قسمت نزدیک سنان نیزه را گویند. آنچه نزدیک سنان است و از پس آن واقع شده است . (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(179743, 'عامل جان', '<span class=\"hlight\">عامل جان .</span> <font color=\"DarkGreen\"><b>[ م ِ ل ِ ]</font></b> (اِخ ) اشارت به ذات پاک باری تعالی است و کنایه از عناصر اربعه هم هست . (برهان ).<br /></font></div>'),
(179744, 'عامل دریا و کان', '<span class=\"hlight\">عامل دریا و کان .</span> <font color=\"DarkGreen\"><b>[ م ِ ل ِ دَرْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وُ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از آفتاب عالمتاب است . (برهان ).<br /></font></div>'),
(179745, 'عامل سماعی', '<span class=\"hlight\">عامل سماعی .</span> <font color=\"DarkGreen\"><b>[ م ِ ل ِ س َ ]</font></b> (ترکیب وصفی، اِ مرکب ) کلماتی که در زبان عربی موجب تغییر اعراب آخر کلمات دیگر شوند عامل گویند و بر دو قسمند سماعی و قیاسی . سماعی عواملی هستند که مضبوط و از عرب شنیده شده، و قیاسی عواملی میباشند که مطابق قواعدی خاص در موارد مشابه میتوانند عمل کنند، مانند عمل مضاف در مضاف ٌالیه که در تمام موارد قیاس میشود. (از تعریفات ).<br /></font></div>'),
(179746, 'عامل صدقات', '<span class=\"hlight\">عامل صدقات .</span> <font color=\"DarkGreen\"><b>[ م ِ ل ِ ص َ دَ ]</font></b> (ترکیب اضافی، اِ مرکب ) آنکه صدقات را جمعآوری کند. (منتهی الارب ) (ناظم الاطباء) (آنندراج ) (مهذب الاسماء). من یتولی امور رجل فی ماله و ملکه و عمله . (المنجد). ج، عُمال . عَمَله . عاملون <span class=\"hlight\">:</span> <br />تا به حدی که عامل صدقات <br />آنچه ماند از منش ستد به زکات .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(179747, 'عامل طبع', '<span class=\"hlight\">عامل طبع.</span> <font color=\"DarkGreen\"><b>[ م ِ ل ِ طَ ]</font></b> (ترکیب اضافی، اِ مرکب ) روح و دل و نفس، و عاملان طبع یعنی سیارات و عناصر اربعه . (آنندراج ). کنایه از روح حیوانی است . (برهان ).<br /></font></div>'),
(179748, 'عامل قیاسی', '<span class=\"hlight\">عامل قیاسی .</span> <font color=\"DarkGreen\"><b>[ م ِ ل ِ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به عامل سماعی شود.<br /></font></div>'),
(179749, 'عامل معنوی', '<span class=\"hlight\">عامل معنوی .</span> <font color=\"DarkGreen\"><b>[ م ِ ل ِ م َ ن َ ]</font></b> (ترکیب وصفی، اِ مرکب ) درمقابل عامل لفظی مانند عاملیت ابتداء است در خبر که همان مجرد بودن از عوامل لفظی است . (از تعریفات ).<br /></font></div>'),
(179750, 'عامل نامه', '<span class=\"hlight\">عامل نامه .</span> <font color=\"DarkGreen\"><b>[ م ِم َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ مرکب ) حکم یا فرمانی که در تصرف کردن اراضی و جز آن به شخص داده میشود. (ناظم الاطباء).<br /></font></div>'),
(179751, 'عاملان دریا و کان', '<span class=\"hlight\">عاملان دریا و کان .</span> <font color=\"DarkGreen\"><b>[ م ِ ن ِ دَرْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وُ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از سیارات است که زحل و مشتری و مریخ و آفتاب و زهره و عطارد و قمر باشدکه ماه است . (برهان ) (آنندراج ) (از مهذب الاسماء).<br /></font></div>'),
(179752, 'عاملة', '<span class=\"hlight\">عاملة.</span> <font color=\"DarkGreen\"><b>[ م ِ ل َ ]</font></b> (اِخ ) ابن سبأبن یشجب بن یعرب بن قحطان، جد جاهلی است که برادر حمیر و کهلان است . (از الاعلام زرکلی ).<br /></font></div>'),
(179753, 'عاملة', '<span class=\"hlight\">عاملة.</span> <font color=\"DarkGreen\"><b>[ م ِ ل َ ]</font></b> (اِخ ) بنت مالک بن ودیعةبن عفیربن عدی از کهلان از قحطانیه . ام جاهلی است که خاندان او از پسران او حارث بن مالک بن ودیعةبن عفیرند و از آنهاست : عدی الرقاع العاملی شاعر. (از الاعلام زرکلی ). و رجوع به عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٢</span> شود.<br /></font></div>'),
(179754, 'عاملة', '<span class=\"hlight\">عاملة.</span> <font color=\"DarkGreen\"><b>[ م ِ ل َ ]</font></b>(ع ص، اِ) مؤنث عامل . رجوع به عامل شود. عاملة الرمح ؛ سینه ٔ نیزه که نزدیک سنان باشد. ج، عاملات و عوامل . (منتهی الارب ) (تاج العروس ) (آنندراج ) (المنجد).<br /></font></div>'),
(179755, 'عامله', '<span class=\"hlight\">عامله .</span> <font color=\"DarkGreen\"><b>[ م ِ ل َ ]</font></b>(اِخ ) دهی است از دهستان چمچال بخش صحنه ٔ شهرستان کرمانشاهان . واقع در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی جنوب صحنه و <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی جنوب راه شوسه ٔ کرمانشاه به همدان . محلی است دشت و سردسیر و دارای هوای معتدل و <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه دارد. آب آن از رودخانه ٔگاماسیاب تأمین میشود و محصولاتش غلات، حبوبات، توتون است و اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(179756, 'عاملی', '<span class=\"hlight\">عاملی .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) ابراهیم بن یحیی . از افاضل علمای اوایل قرن سیزدهم هجرت بود که در حدود <span class=\"hlight\" dir=\"rtl\">١٢٣٠</span> هَ . ق . درگذشت . وی از شاگردان سید بحرالعلوم بود و از آثار اوست تخمیس قصیده ٔ میمیه ٔ ابوفراس حمدانی حاوی <span class=\"hlight\" dir=\"rtl\">٥٤</span> بیت که همه ٔ آنها بهمان روش تخمیس شده است و در منن الرحمان شیخ جعفر نقدی مندرج است . (از ریحانة الادب ).<br /></font></div>'),
(179757, 'عاملی', '<span class=\"hlight\">عاملی .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) محمدحسن . رجوع به حر عاملی شود.<br /></font></div>'),
(179758, 'عاملی', '<span class=\"hlight\">عاملی .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) بدرالدین بن سید احمدبن زین العابدین حسنیی عاملی انصاری، ساکن طوس و یکی از مدرسین آنجا بود. او مردی فقیه و محدث و ادیب و شاعر بوده و از معاصرین شیخ حر عاملی ونوه ٔ دختری میرداماد بود. و از تألیفات اوست : حجیةالاخبار و شرح زبده ٔ شیخ بهائی . (از ریحانة الادب ).<br /></font></div>'),
(179759, 'عاملی', '<span class=\"hlight\">عاملی .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) احمد. رجوع به حر عاملی شود.<br /></font></div>'),
(179760, 'عامه', '<span class=\"hlight\">عامه .</span> <font color=\"DarkGreen\"><b>[ م ِه ْ ]</font></b> (ع ص ) سرگشته در گمراهی . متردد درراه و منازعت . ج، عُمّه . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179761, 'عامه پسند', '<span class=\"hlight\">عامه پسند.</span> <font color=\"DarkGreen\"><b>[ م م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ پ َ س َ ]</font></b> (ن مف مرکب ) آنچه را مردم معمولی پسندند. آنچه را عرف پسندد.<br /></font></div>'),
(179762, 'عامود', '<span class=\"hlight\">عامود.</span> (ع اِ) ستون خانه و رکن . (منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(179763, 'عامورا', '<span class=\"hlight\">عامورا.</span> (اِخ ) یکی از شهرهای قوم لوط است . (از معجم البلدان ).<br /></font></div>'),
(179764, 'عاموس', '<span class=\"hlight\">عاموس .</span> (اِخ ) (به عبری یار) نبی، شخصی شبانی بود از ساکنان تقوع که بدرجه ٔ نبوت مفتخر گشته سومین انبیاء اصغر محسوب گردید. تقوع قصبه ای است در یهودا که تخمیناً به مسافت دوازده میل بطرف جنوبی اورشلیم واقع بود او تقریباً <span class=\"hlight\" dir=\"rtl\">٧٥٠</span> ق . م . مسیح در ایام عزیا پادشاه یهودا و یربعام دوم پادشاه اسرائیل در بیت ایل درباره ٔ اسرائیل نبوت فرمود امثال سلیمان . بنابراین آن حضرت با هوشع ویوئیل معاصر بود و او اولاد یکی از شبانان بود موضوع مخصوص نبوات آوده سبط اسرائیل است . او کتاب خود را با کلمات فرح آمیز و تسلی انگیز ختم مینماید. وضع عبارت عاموس میان نبیین مقام و مرتبت اعلی دارد و همواره از پیشه ٔ فلاحی سخن میراند. و در عهد جدید دو مرتبه از کتاب او اقتباس شده است . (از قاموس کتاب مقدس ).<br /></font></div>'),
(179765, 'عاموص', '<span class=\"hlight\">عاموص .</span> (اِخ ) عاموس . شهری است نزدیک بیت اللحم که گویند حضرت عیسی پس از مردن در آنجا دیده شده و خود را به حواریون نموده . (منتهی الارب ) (ناظم الاطباء). رجوع به معجم البلدان شود.<br /></font></div>'),
(179766, 'عامی', '<span class=\"hlight\">عامی .</span> <font color=\"DarkGreen\"><b>[ عامی ی می ی ]</font></b> (ع ص ) نبت ٌ عامی ؛ گیاه خشک یکساله . (منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(179767, 'عامی', '<span class=\"hlight\">عامی .</span> <font color=\"DarkGreen\"><b>[ عام می ]</font></b> (ع ص نسبی ) منسوب است به عامه، ضد خاصه . (منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(179768, 'عامی', '<span class=\"hlight\">عامی .</span> (ص نسبی ) جاهل و بی سواد. (غیاث ) (آنندراج ) <span class=\"hlight\">:</span> <br />عشق تو بکشت عالم و عامی را<br />زلف تو برانداخت نکونامی را.<br /> <font color=\"Red\">خاقانی .</font><br />ای عشق تو کشته عارف و عامی را<br />سودای تو گم کرده نکونامی را<br />ذوق لب میگون تو آورده برون <br />از صومعه بایزید بسطامی را.<br /> <font color=\"Red\">بایزیدبسطامی .</font><br />بساط سبزه لگدکوب شد بپای نشاط<br />ز بسکه عارف و عامی برقص برجستند.<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> مقابل عَلوی . سید <span class=\"hlight\">:</span> <br />غریق منت احسان بیشمار تواند<br />ز لشکری و رعیت ز عامی و علوی .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(179769, 'عامی اصفهانی', '<span class=\"hlight\">عامی اصفهانی .</span> <font color=\"DarkGreen\"><b>[ ی ِ اِ ف َ ]</font></b> (اِخ )هدایت گوید: وی از عوام الناس اصفهان و فروشنده ٔ کرباس بوده و گاهی شعر میگفته و از جمله اشعار اوست :<br />هر جا فتاد سایه ٔ سرو قدت بخاک <br />آنجا هزار قمری دل آشیان گرفت <br />آنچه در جان و دلم صبر و قرارش خوانند<br />برده از یک نظر آن شوخ که یارش خوانند.<br /><font color=\"Red\">(از مجمع الفصحاء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٦</span>).</font><br /></font></div>'),
(179770, 'عامیانه', '<span class=\"hlight\">عامیانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص نسبی، ق مرکب ) منسوب به عوام و مردم بیسواد و فرومایه و پست . (ناظم الاطباء) <span class=\"hlight\">:</span> <br />عامیانه چه ملامت میکنی <br />بخل بر خوان خداوند غنی .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(179771, 'عامیة', '<span class=\"hlight\">عامیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) زن سخت گریه و زاری کننده . (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(179772, 'عان', '<span class=\"hlight\">عان .</span> <font color=\"DarkGreen\"><b>[ نِن ْ ]</font></b> (ع ص ) عانی . اسیر و بندی . (منتهی الارب ) (ناظم الاطباء). رجوع به عانی شود.<br /></font></div>'),
(179773, 'عان', '<span class=\"hlight\">عان .</span> <font color=\"DarkGreen\"><b>[ عان ن ]</font></b>(ع اِ) رسن دراز. (از منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(179774, 'عان عان', '<span class=\"hlight\">عان عان .</span> (اِ صوت ) حکایت صوت خر. عرعر. نهیق <span class=\"hlight\">:</span> <br />بترنم هجای من خوانی <br />سرد و ناخوش بود ترنم خر<br />چو به عان عان رسی فرومانی <br />ای مه عان عان خر نه عم عم خر <font color=\"DarkGreen\"><b>[ کذا ]</font></b><br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(179775, 'عانات', '<span class=\"hlight\">عانات .</span> (اِخ ) موضعی است از ناحیه ٔ جزیره . (مهذب الاسماء). و رجوع به عانة و عانیة شود.<br /></font></div>'),
(179776, 'عانات', '<span class=\"hlight\">عانات .</span> (ع اِ) ج ِ عانة. رجوع به عانة شود.<br /></font></div>'),
(179777, 'عانب', '<span class=\"hlight\">عانب .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ع ص ) خداوندانگور. (منتهی الارب ) (ناظم الاطباء). دارنده ٔ عنب .<br /></font></div>'),
(179778, 'عانة', '<span class=\"hlight\">عانة.</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (ع اِ) خر ماده . گله ٔ خر. گله ٔ گورخر. (از المنجد) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> موی زهار. (منتهی الارب ) (آنندراج ). بانه و پشت زهار. رنبه در تداول عامه . ج، عون .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">استخوان عانه </span> ؛ استخوان پشت زهار. (ناظم الاطباء).<br /></font></div>'),
(179779, 'عانة', '<span class=\"hlight\">عانة.</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) دهی است بر فرات و او را قلعه ٔ محکمی است و ابن الجهم العانی منسوب بدانجاست . (از معجم البلدان ). چند ستاره ٔروشن است در پایین سعود. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179780, 'عانت', '<span class=\"hlight\">عانت .</span><font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ع ص ) دختری که بی شوی تا دیر در خانه مانده باشد و شوی ندیده باشد. ج، عَوانت . (ناظم الاطباء).<br /></font></div>'),
(179781, 'عاند', '<span class=\"hlight\">عاند.</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) وادیی است واقع در میان مکه و مدینه به مسافت یک میل، پیش از سقیا که عایذ هم گویند. (از معجم البلدان ).<br /></font></div>'),
(179782, 'عاند', '<span class=\"hlight\">عاند.</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (اِخ ) (وَجْرة) روزی از روزهای عرب است . (از معجم البلدان ).<br /></font></div>'),
(179783, 'عاند', '<span class=\"hlight\">عاند.</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ع ص ) شتر از راه برگردنده و میل کننده ج، عُنّد. (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> سرکش و به باطل ستیهنده . ردکننده ٔ حق . <BR><font color=\"Blue\">◄</font> طعن عاند؛ نیزه ای که به چپ و راست زده شود. (منتهی الارب ) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> عرق عاند؛ خوی روان . (منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(179784, 'عانس', '<span class=\"hlight\">عانس .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (ع ص ) عانت . دختری که بی شوی تا دیر در خانه مانده باشد.ج، عَوانس و عُنس و عُنّس و عُنوس . (منتهی الارب ) (آنندراج ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> مرد تا دیر نکاح ناکرده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نیکوروی . <BR><font color=\"Blue\">◄</font> فربه تمام اندام . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179785, 'عانسة', '<span class=\"hlight\">عانسة.</span> <font color=\"DarkGreen\"><b>[ ن ِ س َ ]</font></b> (ع ص ) مؤنث عانس . رجوع به عانس شود. (منتهی الارب ).<br /></font></div>'),
(179786, 'عانق', '<span class=\"hlight\">عانق .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (اِخ ) یوم عانق ؛ روزی است مر عربان را. (منتهی الارب ) (آنندراج ) (از معجم البلدان ).<br /></font></div>'),
(179787, 'عانک', '<span class=\"hlight\">عانک .</span> <font color=\"DarkGreen\"><b>[ ن ِ]</font></b> (ع ص ) ریگ توده ٔ بر هم نشسته و سخت گردیده و در برچسبنده . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> لازم چیزی . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> زن فربه و سرخ . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> خون سرخ رنگ . (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(179788, 'عانی', '<span class=\"hlight\">عانی .</span> (ع ص ) عان . اسیر. بندی . (منتهی الارب ) (آنندراج ) (ناظم الاطباء). دستگیر کرده . (مهذب الاسماء). یقال رجل عان و قوم عناة و نسوة عَوان . <BR><font color=\"Blue\">◄</font> خون روان . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179789, 'عانی', '<span class=\"hlight\">عانی .</span> (ص نسبی ) حمار عانی ّ و حمرٌ عانیة، منسوب به ده عانة. (ناظم الاطباء). رجوع به عانة شود.<br /></font></div>'),
(179790, 'عانیة', '<span class=\"hlight\">عانیة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) مؤنث عانی . یقال : امراءة عانیه ؛ زن اسیر و بندی . (منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(179791, 'عانیة', '<span class=\"hlight\">عانیة.</span> <font color=\"DarkGreen\"><b>[ نی ی َ ]</font></b> (ص نسبی ) مؤنث عانی منسوب به عانة است که دهی است بر فرات . رجوع به عانة شود. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شرابی است منسوب به عانات و هی موضع من ناحیة الجزیره . (مهذب الاسماء).<br /></font></div>'),
(179792, 'عانیر', '<span class=\"hlight\">عانیر.</span> (اِخ ) (در عبری به معنی طفل ) شهری است منسوب به لاویان که در قسمت منسی در مغرب اردن واقع بود. کتاب اول تواریخ ایام داوران :<span class=\"hlight\" dir=\"rtl\">٢</span> بعضی را گمان چنان است که آن مثل تعنک بود. صحیفه یوشع <span class=\"hlight\" dir=\"rtl\">٢١</span>:<span class=\"hlight\" dir=\"rtl\">٢٥</span> سفر داوران <span class=\"hlight\" dir=\"rtl\">١</span>:<span class=\"hlight\" dir=\"rtl\">٢٧</span>. (قاموس کتاب مقدس ).<br /></font></div>'),
(179793, 'عانیم', '<span class=\"hlight\">عانیم .</span> (اِخ ) (در عبری به معنی دو چشمه ) شهری منسوب به لاویان که درقسمت یساکار واقع بود اول تواریخ ایام <span class=\"hlight\" dir=\"rtl\">٦</span>:<span class=\"hlight\" dir=\"rtl\">٧٣</span> و بعضی را گمان چنان است که عانیم همان عین جنیم است . صحیفه ٔ یوشع <span class=\"hlight\" dir=\"rtl\">١٩</span>:<span class=\"hlight\" dir=\"rtl\">٢١</span> و <span class=\"hlight\" dir=\"rtl\">١</span>:<span class=\"hlight\" dir=\"rtl\">٢٩</span>. یعنی جنین که بجانب چمن بنی عمیر واقع است ملاحظه در عین جنیم . (قاموس کتاب مقدس ).<br /></font></div>'),
(179794, 'عانیم', '<span class=\"hlight\">عانیم .</span> (اِخ ) شهری در کوهستان یهودا صحیفه ٔ یوشع <span class=\"hlight\" dir=\"rtl\">١٥</span>:<span class=\"hlight\" dir=\"rtl\">٥</span> و بعضی برآنند که همان خرابة الجیف است و دیگران برآنند که الغوین است که به مسافت <span class=\"hlight\" dir=\"rtl\">١٠</span> میل بجنوب غربی حبرون الخلیل مانده واقع است . (قاموس کتاب مقدس ).<br /></font></div>'),
(179795, 'عاه', '<span class=\"hlight\">عاه .</span> (اِخ ) موضعی است که در آن حمیدبن حریث بن بجدل کلبی با بنی فزاره برخورد و نبرد کرد. (از معجم البلدان ).<br /></font></div>'),
(179796, 'عاه', '<span class=\"hlight\">عاه .</span> (اِخ ) کوهی است در سرزمین فزارة. (از معجم البلدان ). <BR><font color=\"Blue\">◄</font> و یوم العاه از ایام عرب است .<br /></font></div>'),
(179797, 'عاه عاه', '<span class=\"hlight\">عاه عاه .</span> (ع اِ صوت مرکب ) کلمه ای است که بدان شتران را زجر کنند تا باز ایستند، عیه عیه کذلک . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179798, 'عاهات', '<span class=\"hlight\">عاهات .</span> (ع اِ) آفتهاو سختیها. (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(179799, 'عاهر', '<span class=\"hlight\">عاهر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص ) زناکار. الولد للفراش و للعاهر الحجر (حدیث )؛ أی لصاحب ام الولد و هو زوجها أو مولاها. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179800, 'عاهرات', '<span class=\"hlight\">عاهرات .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص، اِ) ج ِ عاهرة.<br /></font></div>'),
(179801, 'عاهرون', '<span class=\"hlight\">عاهرون .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص، اِ) ج ِ عاهر (در حالت رفع).<br /></font></div>'),
(179802, 'عاهل', '<span class=\"hlight\">عاهل .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص ) پادشاه بزرگ . (منتهی الارب ) (آنندراج ). آن پادشاه که زور دست اوهیچ دست نبود. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> زن که شوی ندارد. (منتهی الارب ) (آنندراج ) (ناظم الاطباء). آن زن که شوی نبود او را. (مهذب الاسماء). ج، عَواهل .<br /></font></div>'),
(179803, 'عاهن', '<span class=\"hlight\">عاهن .</span><font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) نام وادیی است . (از معجم البلدان ).<br /></font></div>'),
(179804, 'عاهن', '<span class=\"hlight\">عاهن .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ع ص ) نیازمند و درویش . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> درویش . (مهذب الاسماء). ج، عواهن . <BR><font color=\"Blue\">◄</font> حاضر و مقیم ثابت . <BR><font color=\"Blue\">◄</font> فروهشته اندام سست . <BR><font color=\"Blue\">◄</font> (اِ) شترخانه زاد. <BR><font color=\"Blue\">◄</font> شاخ خرمابن که نزدیک تنه باشد. (منتهی الارب ) (آنندراج ). زلو خرما. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> رگ زهدان ماده شتر. <BR><font color=\"Blue\">◄</font> عضوو جوارح مردم . (منتهی الارب ) (آنندراج ). ج، عواهن .<br /></font></div>'),
(179805, 'عاهنة', '<span class=\"hlight\">عاهنة.</span> <font color=\"DarkGreen\"><b>[ هَِ ن َ ]</font></b> (ع اِ) یک شاخه خرمابن که نزدیک تنه باشد. (ناظم الاطباء).<br /></font></div>'),
(179806, 'عاوز', '<span class=\"hlight\">عاوز.</span> <font color=\"DarkGreen\"><b>[ وِ ]</font></b> (ع ص ) فقیر. (ناظم الاطباء).<br /></font></div>'),
(179807, 'عاوی', '<span class=\"hlight\">عاوی .</span> (ع ص ) سگ یا گرگ با بانگ . (ناظم الاطباء).<br /></font></div>'),
(179808, 'عاویات', '<span class=\"hlight\">عاویات .</span> (ع ص، اِ) ج ِ عاویة.<br /></font></div>'),
(179809, 'عاویة', '<span class=\"hlight\">عاویة.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (ع ص ) مؤنث عاوی . رجوع به عاوی شود.<br /></font></div>'),
(179810, 'عاکارعاکان', '<span class=\"hlight\">عاکارعاکان .</span> (اِخ ) (به عبری تنگ آمده ). پسر کرمی از سبط یهودا بود که بعضی از غنیمت اریحا را در حالی که برخلاف امر حضرت اقدس الهی بود مخفی داشت صحیفه ٔ یوشع <span class=\"hlight\" dir=\"rtl\">٦</span>:<span class=\"hlight\" dir=\"rtl\">١٨</span> و <span class=\"hlight\" dir=\"rtl\">٧</span>:<span class=\"hlight\" dir=\"rtl\">١</span> سفر اول تاریخ ایام <span class=\"hlight\" dir=\"rtl\">٢</span>:<span class=\"hlight\" dir=\"rtl\">٧</span>. بدین لحاظ غضب خداوند بر ایشان افروخته شد. در مقابل شهر عای منهزم شدند صحیفه ٔ یوشع <span class=\"hlight\" dir=\"rtl\">٧</span>:<span class=\"hlight\" dir=\"rtl\">١٨</span>. بنابراین عخان با استصواب قرعه گرفتار آمده اسرائیل وی را با خانواده اش سنگسار نمودند و تمامی آنها را در خارج از شهر سوزانیدند. صحیفه ٔ یوشع <span class=\"hlight\" dir=\"rtl\">٧</span>:<span class=\"hlight\" dir=\"rtl\">٣٤</span> و <span class=\"hlight\" dir=\"rtl\">٢٥</span>. (قاموس کتاب مقدس ).<br /></font></div>'),
(179811, 'عاکب', '<span class=\"hlight\">عاکب .</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (ع ص ) انبوه . (منتهی الارب ) (آنندراج ) (اقرب الموارد). ج، عُکوب . <BR><font color=\"Blue\">◄</font> مرد ایستاده . متوقف . <BR><font color=\"Blue\">◄</font> شتران گردآمده بر حوض . (ناظم الاطباء).<br /></font></div>'),
(179812, 'عاکف', '<span class=\"hlight\">عاکف .</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (ع ص ) به جایی مقیم شونده . (منتهی الارب ) (اقرب الموارد) (آنندراج ). ج، عاکفون و عُکف ّ و عکوف . (اقرب الموارد) <span class=\"hlight\">:</span> و المسجد الحرام الذی جعلناه للناس سواءالعاکف فیه و الباد. (قرآن <span class=\"hlight\" dir=\"rtl\">٢٥/٢٢</span>)؛ و مسجد الحرام را برای مردم قرار دادیم که یکسان باشد مقیم در آن و وارد از خارج . <BR><font color=\"Blue\">◄</font> گوشه گیرنده در مسجد. (منتهی الارب ) (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> عاکفان کعبه ٔ جلالش به تقصیر عبادت معترف . (گلستان ). <BR><font color=\"Blue\">◄</font> نگاه دارنده خود را. <BR><font color=\"Blue\">◄</font> اصلاح کننده . <BR><font color=\"Blue\">◄</font> دیری ورزنده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> عاکف و عاکفان ملأ اعلا؛ فرشتگان که در مقام بالا جای دارند. (ناظم الاطباء).<br /></font></div>'),
(179813, 'عاکل', '<span class=\"hlight\">عاکل .</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (ع ص ) کوتاه بالا. زفت بدفال . ج، عُکُل . (منتهی الارب ). کوتاه بالای بخیل . (اقرب الموارد).<br /></font></div>'),
(179814, 'عاکوب', '<span class=\"hlight\">عاکوب .</span>(ع اِ) گرد و غبار. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(179815, 'عاکی', '<span class=\"hlight\">عاکی .</span> (ع ص ) مرده . (منتهی الارب )(آنندراج ). <BR><font color=\"Blue\">◄</font> کسی که قاووت فروشد. (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آزمند قاووت . (منتهی الارب ) (اقرب الموارد). ج، عُکاة.<br /></font></div>'),
(179816, 'عای', '<span class=\"hlight\">عای .</span> (اِخ ) یکی از شهرهای عمونیان که در نزدیکی حشبان واقع بود. کتاب ارمیا <span class=\"hlight\" dir=\"rtl\">٤٩</span>:<span class=\"hlight\" dir=\"rtl\">٣</span>. (قاموس کتاب مقدس ).<br /></font></div>'),
(179817, 'عای', '<span class=\"hlight\">عای .</span> (اِخ ) (در عبری بمعنی کومه ٔ خرابی ) یکی از شهرهای کنعانیان که یوشعآن را مفتوح گردانید ابراهیم نیز چادر خود را در میانه ٔ عای و بیت ایل بر پا نمود و مسافت میانه ٔ این دو شهر بقدری بود که امکان داشت کمینگاهی به طرف غربی عای فراهم کرده که مردان و اهالی بیت ایلش نتوانند دید. عای در مشرق بیت ایل و به مسافت نه میل به شمال اورشلیم واقع و محل موضعش فعلاً به خرابه ٔ حیان معروف است و عای <span class=\"hlight\" dir=\"rtl\">٣٨</span> مرتبه در کتاب مقدس وارد گشته است .<br /></font></div>'),
(179818, 'عایب', '<span class=\"hlight\">عایب .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) عائب . دارای عیب .رجوع به عائب شود. <BR><font color=\"Blue\">◄</font> شیر خفته و دفزک .<br /></font></div>'),
(179819, 'عایث', '<span class=\"hlight\">عایث .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع اِ) رجوع به عائث شود. (ناظم الاطباء).<br /></font></div>'),
(179820, 'عایج', '<span class=\"hlight\">عایج .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) ایستاده و متوقف . (ناظم الاطباء). رجوع به عائج شود.<br /></font></div>'),
(179821, 'عاید', '<span class=\"hlight\">عاید.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به عائد شود.<br /></font></div>'),
(179822, 'عایذ', '<span class=\"hlight\">عایذ.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) نوزاینده از آهو و اسب و شتر و گوسپند و جز آن . ج، عوذ و عوذان . (ناظم الاطباء). رجوع به عائذ شود.<br /></font></div>'),
(179823, 'عایذ', '<span class=\"hlight\">عایذ.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) کوهی است در جهت قبله و مقابل آن کوه دیگری است پشت به قبله . (از معجم البلدان ).<br /></font></div>'),
(179824, 'عایر', '<span class=\"hlight\">عایر.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به عائر شود.<br /></font></div>'),
(179825, 'عایس', '<span class=\"hlight\">عایس .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به عائس شود.<br /></font></div>'),
(179826, 'عایش', '<span class=\"hlight\">عایش .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به عائش شود.<br /></font></div>'),
(179827, 'عایشه دول', '<span class=\"hlight\">عایشه دول .</span> <font color=\"DarkGreen\"><b>[ ی ِ ش َ دُ ]</font></b> (اِخ ) دهی است از دهستان جوانرود بخش پاوه ٔ شهرستان سنندج، واقع در <span class=\"hlight\" dir=\"rtl\">٤١</span> هزارگزی جنوب خاور پاوه و <span class=\"hlight\" dir=\"rtl\">١٥٠٠</span>گزی جنوب باختر راه اتومبیل رو کرمانشاه به پاوه . ناحیه ای است کوهستانی و سردسیر. <span class=\"hlight\" dir=\"rtl\">٥٣</span> تن سکنه دارد. آب آن از چشمه تأمین میشود. محصولاتش : غلات، توتون، لبنیات است و اهالی به کشاورزی و گله داری اشتغال دارند. راه فرعی به قلعه جوانرود از این آبادی میگذرد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(179828, 'عایص', '<span class=\"hlight\">عایص .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به عائص شود.<br /></font></div>'),
(179829, 'عایض', '<span class=\"hlight\">عایض .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به عائض شود.<br /></font></div>'),
(179830, 'عایط', '<span class=\"hlight\">عایط.</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به عائط شود.<br /></font></div>'),
(179831, 'عایف', '<span class=\"hlight\">عایف .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به عائف شود.<br /></font></div>'),
(179832, 'عایق', '<span class=\"hlight\">عایق .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به عائق شود.<br /></font></div>'),
(179833, 'عایل', '<span class=\"hlight\">عایل .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به عائل شود.<br /></font></div>'),
(179834, 'عایلة', '<span class=\"hlight\">عایلة.</span> <font color=\"DarkGreen\"><b>[ ی ِ ل َ ]</font></b> (ع ص ) مؤنث عایل .<br /></font></div>'),
(179835, 'عایم', '<span class=\"hlight\">عایم .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) عائم . شناور. <BR><font color=\"Blue\">◄</font> (اِخ )نام بتی است . (ناظم الاطباء). و رجوع به عائم شود.<br /></font></div>'),
(179836, 'عاین', '<span class=\"hlight\">عاین .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (ع ص ) رجوع به عائن شود.<br /></font></div>'),
(179837, 'عایهه', '<span class=\"hlight\">عایهه .</span> <font color=\"DarkGreen\"><b>[ ی ِ هََ ]</font></b> (ع اِ) فریاد و خروش . (ناظم الاطباء). و رجوع به عائهة شود.<br /></font></div>'),
(179838, 'عب', '<span class=\"hlight\">عب .</span> <font color=\"DarkGreen\"><b>[ ع َب ب ]</font></b> (ع مص ) آب خوردن یا جرعه جرعه خوردن آن یا پی درپی خوردن . (منتهی الارب ) (آنندراج ) (غیاث اللغات ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> به دهان خوردن آب از جوی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آواز کردن دلو وقت آب گرفتن در چاه . (منتهی الارب ) (از اقرب الموارد) (آنندراج ). <BR><font color=\"Blue\">◄</font> دراز و انبوه شدن گیاه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بالا رفتن و بسیار شدن موج دریا. (از اقرب الموارد). پرتو خورشید. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) اسم است سرما را. (از اقرب الموارد).<br /></font></div>'),
(179839, 'عب', '<span class=\"hlight\">عب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب ب ]</font></b> (ع اِ) تریز و بن آستین . (منتهی الارب ) (از اقرب الموارد).<br /></font></div>'),
(179840, 'عبا', '<span class=\"hlight\">عبا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) عباء. رجوع به عباء شود.<br /></font></div>'),
(179841, 'عباء', '<span class=\"hlight\">عباء.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) پوششی است از پشم پیش شکافته که بر روی لباس پوشند. (از اقرب الموارد) (آنندراج ) (منتهی الارب ) (غیاث اللغات ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">آل عباء</span> ؛ اصحاب کساء. پنج تن . و آنان پیغمبر اسلام (ص )، علی (ع )، فاطمه (ع ) حسن (ع ) و حسین (ع )اند. رجوع به آل عبا شود.<br /><BR><font color=\"Blue\">◄</font> گلیم خطدار. (منتهی الارب ) (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> (ص ) گول گران و ثقیل الجسم فربه . (منتهی الارب ). الاحمق الثقیل الوخیم . (اقرب الموارد).<br /></font></div>'),
(179842, 'عباآت', '<span class=\"hlight\">عباآت .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عَباءَة. نوعی از گلیم . (منتهی الارب ). رجوع به عباءة شود.<br /></font></div>'),
(179843, 'عباب', '<span class=\"hlight\">عباب .</span><font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (ع ص ) بسیار آشامنده . (ناظم الاطباء).<br /></font></div>'),
(179844, 'عباب', '<span class=\"hlight\">عباب .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (ع مص ) آب آشامیدن و از آن باب است اًذا أصابت الظباء الماء فلا عباب و اًن لم تصبه فلا أباب ؛ اگر آب را یافت نیاشامید و اگر نیافت برای طلب و آشامیدن آن آماده نشد، برای کسی مثل زنند که به چیزی دست یافت و به سبب بی نیازی از آن اعراض کرد. (از اقرب الموارد) (از آنندراج ) (از منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(179845, 'عباب', '<span class=\"hlight\">عباب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) توجبه ٔ بزرگ بسیار دور. (آنندراج ) (از منتهی الارب ). معظم سیل و ارتفاع و کثرت آن . (از اقرب الموارد) (از غیاث اللغات ). <BR><font color=\"Blue\">◄</font> برگ خرما. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) پری آب و بسیاری آن . (منتهی الارب ) (از اقرب الموارد) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) موج سیل . (منتهی الارب ) (از اقرب الموارد) (آنندراج ). <BR><font color=\"Blue\">◄</font> اعلای هر چیزی .(منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> اول هر چیزی .(منتهی الارب ) (از غیاث اللغات ). <BR><font color=\"Blue\">◄</font> (اِمص ) بالا برآمدن آب . (از اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(179846, 'عباب', '<span class=\"hlight\">عباب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) نبرد کردن در فخر و فزونی . (منتهی الارب ) (ناظم الاطباء).معابة مثله . (ناظم الاطباء). و رجوع به معابة شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(179847, 'عبابر', '<span class=\"hlight\">عبابر.</span> <font color=\"DarkGreen\"><b>[ ع َ ب ِ ]</font></b> (ع اِ) ج ِ عَبور. بره گوسفند. (منتهی الارب ). رجوع به عَبور شود.<br /></font></div>'),
(179848, 'عبابی', '<span class=\"hlight\">عبابی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) عبداﷲبن عامربن حجیة. یکی از بنی عباب است . (اللباب ).<br /></font></div>'),
(179849, 'عبابی', '<span class=\"hlight\">عبابی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) قیس بن عباب . یکی از کسانی است که در یوم قادسیة نیک امتحان داد. (اللباب ).<br /></font></div>'),
(179850, 'عبابی', '<span class=\"hlight\">عبابی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) حرث بن ربیعةبن عجل عبابی . (از اللباب ).<br /></font></div>'),
(179851, 'عبابی', '<span class=\"hlight\">عبابی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (ص نسبی ) منسوب به عباب که نام مردی است و آن قیس بن عباب است . (از انساب سمعانی ).<br /></font></div>'),
(179852, 'عبابی', '<span class=\"hlight\">عبابی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (ص نسبی ) نسبت است به عباب . رجوع به عبابی و قیس بن عباب شود. (اللباب ).<br /></font></div>'),
(179853, 'عبابید', '<span class=\"hlight\">عبابید.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) عبادید. گروه های مردم . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء) (آنندراج ). <BR><font color=\"Blue\">◄</font> گروه درگذشته و پریشان و متفرق شده و دونده به هرسوی، یقال : صار القوم عبابید؛ ای متفرقین . (منتهی الارب ) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> راههای دور. (از اقرب الموارد) (منتهی الارب ) (ناظم الاطباء). و فی اللسان : الاطراف البعیده . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بیشه ها. (منتهی الارب ) (آنندراج ). عبابید و عبادید دو جمعند که مفردی از لفظ آنها نیامده است . (از اقرب الموارد).<br /></font></div>'),
(179854, 'عبابید', '<span class=\"hlight\">عبابید.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) موضعی است که پیغمبر (ص ) در شب هجرت با ابوبکر از آن عبور کردند. این کلمه را ابن هشام عبابید خوانده است .<br /></font></div>'),
(179855, 'عبابید', '<span class=\"hlight\">عبابید.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) عشیره ای است از ذوی عیاض از قبیله ٔ عوازم که مسکن آنها نزدیک مُطیر و عُجمان بین کویت و ساحل خلیج فارس است . (از معجم قبائل العرب ).<br /></font></div>'),
(179856, 'عباثر', '<span class=\"hlight\">عباثر.</span> <font color=\"DarkGreen\"><b>[ ع َ ث ِ ]</font></b> (ع اِ) گیاهی است خوشبو. (از اقرب الموارد). ج، عبثران . یاقوت آرد: گیاهی است مانند قیصوم . (از معجم البلدن ).<br /></font></div>'),
(179857, 'عباثر', '<span class=\"hlight\">عباثر.</span> <font color=\"DarkGreen\"><b>[ ع َ ث ِ ]</font></b> (اِخ ) نقبی است که سرازیر میشود از جبل جهینه که هر کس از اضم به ینبع برود باید از آن عبور کند. (از معجم البلدان ).<br /></font></div>'),
(179858, 'عباد', '<span class=\"hlight\">عباد.</span> <font color=\"DarkGreen\"><b>[ع ِ ]</font></b> (ع اِ) ج ِ عبد. بندگان . (اقرب الموارد) (منتهی الارب ) (ناظم الاطباء) (آنندراج ). رجوع به عبد شود.<br /></font></div>'),
(179859, 'عباد', '<span class=\"hlight\">عباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن یعقوب البخاری الرواجنی، مکنی به ابوسعید. از فضلای کوفه بود بخاری و جز او از وی روایت کنند و او را کتبی است از جمله اخبار المهدی المنتظر و المعرفة فی الصحابه .وی به سال <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(179860, 'عباد', '<span class=\"hlight\">عباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است به مرو که اهل محل آن را شنک عباد نامند و محدثان سِنج عباد نویسند.فاصله ٔ آن تا مرو <span class=\"hlight\" dir=\"rtl\">٤</span> فرسخ است . (از معجم البلدان ).<br /></font></div>'),
(179861, 'عباد', '<span class=\"hlight\">عباد.</span> <font color=\"DarkGreen\"><b>[ ع ُب ْ با ]</font></b> (ع ص، اِ) ج ِ عابد. (ناظم الاطباء). رجوع به عابد شود.<br /></font></div>'),
(179862, 'عباد', '<span class=\"hlight\">عباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) قبیله های پراکنده از تازیان که در حیره بر نصرانیت مجتمع شدند. (منتهی الارب )(از اقرب الموارد) (ناظم الاطباء) (از معجم قبائل العرب ). و نسبت به آن عبادی است . رجوع به عبادی شود.<br /></font></div>'),
(179863, 'عباد', '<span class=\"hlight\">عباد.</span> <font color=\"DarkGreen\"><b>[ع َب ْ با ]</font></b> (اِخ ) ابن عوام بن عبداﷲ کلابی واسطی، مکنی به ابوسهل از رجال حدیث و ثقات بود وی به تشیع تظاهر میکرد. هارون الرشید وی را به زندان افکند و به سال <span class=\"hlight\" dir=\"rtl\">١٨٥</span> هَ . ق . در بغداد درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(179864, 'عباد', '<span class=\"hlight\">عباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن عبادبن حبیب بن مهلب بن صفر العتکی الازدی المهلبی البصری، مکنی به ابومعاویه . وی از حفاظ حدیث و از ثقات بود و به سال <span class=\"hlight\" dir=\"rtl\">١٨١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(179865, 'عباد', '<span class=\"hlight\">عباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن زیادبن ابیه برادر عبداﷲبن زیاد ومکنی به ابوحرب . وی از جانب معاویه ولایت سیستان یافت و به سال <span class=\"hlight\" dir=\"rtl\">١٠٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(179866, 'عباد', '<span class=\"hlight\">عباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن محمدبن حیان البلخی، مکنی به ابونصر از موالی کنده بود وی به سال <span class=\"hlight\" dir=\"rtl\">١٩٦</span> هَ . ق . از جانب مأمون ولایت مصر یافت سپس امین از وی آزرده گشت و ربیعةبن قیس را مأمور دستگیری وی ساخت و سرانجام به دستور امین به سال <span class=\"hlight\" dir=\"rtl\">١٩٨</span>هَ . ق . در بغداد به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(179867, 'عباد', '<span class=\"hlight\">عباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن الحصین بن یزیدبن عمرو الحبطی التمیمی، مکنی به ابوجهضم و در عصر خود از فرسان بنی تمیم بود. وی از جانب ابن زبیر به ریاست شرطه ٔ بصره منصوب گردید و در ایام قتل مختار از همراهان مصعب بود.او از کسانی است که با عبداﷲبن عامر در فتح کابل حضور داشت و فتنه ٔ ابن اشعث را نیز درک کرد و به سال <span class=\"hlight\" dir=\"rtl\">٨٥</span> هَ . ق . در کابل به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(179868, 'عباد', '<span class=\"hlight\">عباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن اخضربن علقمةبن عباد المازنی التمیمی و اخضر شوی مادر اوست وی یکی از مردان مشهور عصر اموی است و به امر عبداﷲبن زیاد با چهارهزار مرد جنگی به جنگ مرداس بن حدیر رفت و مرداس را بکشت و سر او را به نزد پسر زیاد فرستاد. وی به سال <span class=\"hlight\" dir=\"rtl\">٦١</span> هَ . ق . در بصره به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(179869, 'عبادات', '<span class=\"hlight\">عبادات .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ عبادة. رجوع به عبادت و عبادة شود.<br /></font></div>'),
(179870, 'عبادات', '<span class=\"hlight\">عبادات .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) ده کوچکی است از دهستان غبوه بخش رامهرمز شهرستان اهواز واقع در <span class=\"hlight\" dir=\"rtl\">٥٠</span> هزارگزی شمال باختری رامهرمز و کنار راه اتومبیل رو ویس به هفتگل . <span class=\"hlight\" dir=\"rtl\">١٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(179871, 'عبادالعتکی', '<span class=\"hlight\">عبادالعتکی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دُل ْ ع َ ]</font></b> (اِخ ) رجوع به عباد (ابن عبادبن حبیب ) شود.<br /></font></div>'),
(179872, 'عباداللهی', '<span class=\"hlight\">عباداللهی .</span> <font color=\"DarkGreen\"><b>[ ع ِ دُل ْلا ]</font></b> (اِخ ) دهی است از دهستانهای بخش هندیجان شهرستان خرمشهر. این ده در جنوب خاوری شهرستان خرمشهر و درساحل غربی رود زهره است هوای آن گرمسیر و مالاریایی است . آب آن از رود زهره تأمین میگردد و محصول عمده ٔآن گندم و جو دیمی است . از پنج قریه بزرگ و کوچک تشکیل شده و <span class=\"hlight\" dir=\"rtl\">٦٠٠</span> تن سکنه دارد و از قراء مهم آن غرالی <span class=\"hlight\" dir=\"rtl\">٢</span> است که قریب <span class=\"hlight\" dir=\"rtl\">١٧٠</span> تن سکنه دارد و ساکنان آن از طایفه ٔ شعبانی هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(179873, 'عباداللهی', '<span class=\"hlight\">عباداللهی .</span> <font color=\"DarkGreen\"><b>[ ع ِدُل ْ لا ]</font></b> (اِخ ) دهی است از دهستان مرکزی عباداللهی بخش هندیجان شهرستان خرمشهر. واقع در <span class=\"hlight\" dir=\"rtl\">٩</span>هزارگزی جنوب باختری هندیجان، کنار راه اتومبیل رو به ساحل خلیج فارس . آب آن از رودخانه ٔ زهره تأمین میشود و محصولات آن غلات دیمی است اهالی به کشاورزی و گله داری اشتغال دارند راه در تابستان اتومبیل رو است و ساکنان از طایفه ٔ شعبانی هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(179874, 'عبادان', '<span class=\"hlight\">عبادان .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) رجوع به آبادان در این لغت نامه و معجم البلدان و ریحانة الادب شود.<br /></font></div>'),
(179875, 'عبادانی', '<span class=\"hlight\">عبادانی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (ص نسبی ) نسبت است به عبادان (آبادان ) که شهری است بنواحی بصره . رجوع به عبادان شود. (از اللباب ).<br /></font></div>'),
(179876, 'عبادانی', '<span class=\"hlight\">عبادانی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) یا آبادانی . ابوبکر احمدبن سلیمان بن ایوب بن اسحاق بن عبدةبن ربیع العبادانی ساکن بغداد بود و از علی بن حرب طائی روایت کند و حاکم ابوعبداﷲ و ابوعلی بن شاذان از وی روایت دارند. (از اللباب ).<br /></font></div>'),
(179877, 'عبادت', '<span class=\"hlight\">عبادت .</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ ]</font></b> (ع مص ) عبادة. پرستش کردن . بندگی کردن . (منتهی الارب ) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> طاعت و نهایت تعظیم برای خدای متعال . (از اقرب الموارد) <span class=\"hlight\">:</span> <br />جان تو از بهر عبادت شده ست <br />بسته در این خانه ٔ پراستخوان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گفتم عبادتی که به یک حرف باشد آن <br />گفتا که عابدونی فی النار والسقر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />پس اگرچند روزی صبر باید کرد در رنج عبادت . (کلیله و دمنه ).<br />نان از برای کنج عبادت گرفته اند<br />صاحبدلان نه کنج عبادت برای نان .<br /> <font color=\"Red\">سعدی (گلستان ).</font><br />عبادت بجز خدمت خلق نیست <br />به تسبیح و سجاده و دلق نیست .<br /><font color=\"Red\">سعدی (گلستان ).</font><br /></font></div>'),
(179878, 'عبادت نمای', '<span class=\"hlight\">عبادت نمای .</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ ]</font></b> (نف مرکب ) ریاکار. آنکه عبادت در پیش دیده ٔ خلق کند. آنکه عبادت به دیگران نماید <span class=\"hlight\">:</span> <br />گنه کار اندیشه ناک از خدای <br />به از پارسای عبادت نمای .<br /><font color=\"Red\">سعدی (بوستان ).</font><br /></font></div>'),
(179879, 'عبادت کردن', '<span class=\"hlight\">عبادت کردن .</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ ک َ دَ ]</font></b> (مص مرکب ) پرستش کردن <span class=\"hlight\">:</span> یکی از معبدان شام سالها در بیشه عبادت کردی . (گلستان ).<br /></font></div>'),
(179880, 'عبادتخانه', '<span class=\"hlight\">عبادتخانه .</span> <font color=\"DarkGreen\"><b>[ ع ِدَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) مکان عبادت و پرستش . (ناظم الاطباء) (آنندراج ). آنجا که در آن ستایش و پرستش خداکنند. عبادتگاه . و رجوع به عبادت و عبادتگاه شود.<br /></font></div>'),
(179881, 'عبادتکار', '<span class=\"hlight\">عبادتکار.</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ ]</font></b> (ص مرکب ) پارسا و زاهد. متدین و عابد. (ناظم الاطباء). آنکه پرستش خدای شغل شاغل او است . و رجوع به عبادت شود.<br /></font></div>'),
(179882, 'عبادتگاه', '<span class=\"hlight\">عبادتگاه .</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ ]</font></b> (اِ مرکب ) عبادتگه . جای پرستش و عبادت . سجده گاه . معبد. مزگت . (ناظم الاطباء). عبادتخانه . آنجا که خدا را در آن بپرستند <span class=\"hlight\">:</span> و عبادتگاهی ساخت و مردم را خداپرستی آموخت . (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٢٨</span>).<br />ز سمرقند بسی کس به دعای تو شدند<br />به زیارتگه کاشان و عبادتگه اوش .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(179883, 'عبادلة', '<span class=\"hlight\">عبادلة.</span> <font color=\"DarkGreen\"><b>[ ع َ دِ ل َ ]</font></b> (اِخ ) جمعی از اصحاب رسول (ص ) که دو صد و بیست کس اند و اگر مطلق گویند مراد چهار کس باشند: عبداﷲبن عباس، عبداﷲبن عمر، عبداﷲبن زبیر وعبدالله بن عمروبن عاص . (از منتهی الارب ). و نزد اصحاب ابوحنیفه عبارتند از عبداﷲبن مسعود، عبداﷲبن عُمر، عبداﷲبن عباس . و بعضی ابن مسعود را از عبادله خارج کرده و عبداﷲبن عمروبن عاص و عبداﷲبن زبیر را داخل دانند. (از کشاف اصطلاحات الفنون ) (از اقرب الموارد).<br /></font></div>'),
(179884, 'عبادلة', '<span class=\"hlight\">عبادلة.</span> <font color=\"DarkGreen\"><b>[ ع َ دِل َ ]</font></b> (اِخ ) بطنی است از جَد. (معجم قبائل العرب ).<br /></font></div>'),
(179885, 'عبادلة', '<span class=\"hlight\">عبادلة.</span> <font color=\"DarkGreen\"><b>[ ع َ دِ ل َ ]</font></b>(اِخ ) بطنی است از جریدة. (از معجم قبائل العرب ).<br /></font></div>'),
(179886, 'عبادی', '<span class=\"hlight\">عبادی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) سلیمان بن ابوصالح مولای حصین بن عبدالرحمان تجیبی عبادی است . (از اللباب ).<br /></font></div>'),
(179887, 'عبادی', '<span class=\"hlight\">عبادی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ص نسبی ) نسبت است به قاضی ابوعاصم محمدبن احمدبن محمدبن عبداﷲبن عبادی الهروی . (از اللباب ). و رجوع به عبادی ابوعاصم محمدبن احمد و امیر ابومنصور مظفر عبادی شود.<br /></font></div>'),
(179888, 'عبادی', '<span class=\"hlight\">عبادی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) محمدبن احمدبن محمدبن محمدبن عبداﷲبن عبادی الهروی ملقب به قاضی ابوعاصم وی از پیشوایان و مفتیان صاحب نظر بود فقه را در هرات نزد قاضی ابومنصور و در نیشابور نزد قاضی ابوعمر بسطامی آموخت و کتابهایی در فقه تألیف کرد از جمله مبسوط و هادی است و حدیث نیز روایت میکرد. وی به سال <span class=\"hlight\" dir=\"rtl\">٣٧٥</span> هَ . ق . متولد شد وبه سال <span class=\"hlight\" dir=\"rtl\">٤٥٨</span> هَ . ق . درگذشت . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٩</span>).<br /></font></div>'),
(179889, 'عبادی', '<span class=\"hlight\">عبادی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) امیر ابومنصور مظفربن ابی الحسین عبادی فرزند ابوالحسن اردشیر. یکی از واعظان مشهور و دارای بلاغت کلام و فصاحت بیان بود و احادیث بسیار از نصراﷲبن خشنامی و ابوعبدﷲ اسماعیل بن عبدالفاخر فارسی استماع کرد. ابوسعید سمعانی گوید: وی در دین خود موثق نبود، و رساله ای به خط او در مباح بودن شراب دیدم . وی به سال <span class=\"hlight\" dir=\"rtl\">٥٤٠</span> و اندی درگذشت . (از اللباب ).<br /></font></div>'),
(179890, 'عبادی', '<span class=\"hlight\">عبادی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابراهیم بن حرث بن مصعب بن ولیدبن عبادةبن صامت العبادی، مکنی به ابواسحاق بغدادی . یکی از روات حدیث بود که از علی بن مدینی روایت کندو از وی ابوبکربن ابوداود روایت دارد. او احمدبن حنبل را درک کرد و از اهل مجلس او بود. (از اللباب ).<br /></font></div>'),
(179891, 'عبادی', '<span class=\"hlight\">عبادی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با]</font></b> (اِخ ) ابوالحسن اردشیربن ابوالمنصور العبادی ملقب به امیر. یکی از وعاظ بنام و دارای ملاحت سخن و حسن سیرت بود و قبول عامه داشت . از ابوعبداﷲ محمدبن حسن هربند شانی روایت کند و ابوبکر عتیق بن علی غازی از او روایت دارد. وی در حدود سال <span class=\"hlight\" dir=\"rtl\">٤٩٠</span> هَ . ق . درگذشت . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٠</span>). و رجوع به ریحانة الادب شود.<br /></font></div>'),
(179892, 'عبادی', '<span class=\"hlight\">عبادی .</span> <font color=\"DarkGreen\"><b>[ ع ُب ْ با ]</font></b> (ص نسبی ) نسبت است به عبادبن ضبیعةبن عبداﷲ محمدالعبادی . رجوع به عبادی عبداﷲبن محمد العبادی شود. صوری گوید عبادی به تشدید باء است و ابونصربن ماکولا گوید عبادی را به تخفیف نمی شناسم . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١</span>).<br /></font></div>'),
(179893, 'عبادی', '<span class=\"hlight\">عبادی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ص نسبی ) نسبت است به عبادبن صامت . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٠</span>). رجوع به ابواسحاق ابراهیم بن حرث بن مصعب بن ولیدبن عبادةبن صامت عبادی بغدادی شود.<br /></font></div>'),
(179894, 'عبادی', '<span class=\"hlight\">عبادی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ص نسبی ) نسبت است به عبادبن ضبیعةبن قیس بن ثعلبةبن عکابةبن صعب بن علی بن بکر. رجوع به عبداﷲبن محمد العبادی شود. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٠</span>).<br /></font></div>'),
(179895, 'عبادی', '<span class=\"hlight\">عبادی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ص نسبی ) نسبت است به عباد که بطنی از تجیب و نزیل مصرند. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١١</span>).<br /></font></div>'),
(179896, 'عبادیة', '<span class=\"hlight\">عبادیة.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دی ی َ ]</font></b> (اِخ ) دهی است به مرج . (از اللباب ) (از منتهی الارب ).<br /></font></div>'),
(179897, 'عبادید', '<span class=\"hlight\">عبادید.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) عبابید در همه ٔ معانی . رجوع به عبابید شود.<br /></font></div>'),
(179898, 'عبادیدی', '<span class=\"hlight\">عبادیدی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (ص نسبی ) منسوب به عبادید و عبابید. (منتهی الارب ) (ناظم الاطباء). رجوع به عبادید و عبابید شود.<br /></font></div>'),
(179899, 'عبادیه', '<span class=\"hlight\">عبادیه .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی َ ]</font></b> (اِخ ) فرقه ای از اباضیه اند. (اقرب الموارد). رجوع به اباضیه شود.<br /></font></div>'),
(179900, 'عبار', '<span class=\"hlight\">عبار.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (ع ص ) شتر نر توانا که از هر زمین گذرد و همیشه سفر کند. (منتهی الارب ) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> تعبیر و تفسیرکننده ٔ خواب . (المنجد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> مبالغه ٔ عابر. (المنجد).<br /></font></div>'),
(179901, 'عبارات', '<span class=\"hlight\">عبارات .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ عبارة. رجوع به عبارت و عبارة شود.<br /></font></div>'),
(179902, 'عبارت', '<span class=\"hlight\">عبارت .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (ع اِمص، اِ) عبارة. <BR><font color=\"Blue\">◄</font> تفسیر و تأویل . <BR><font color=\"Blue\">◄</font> شرح . <BR><font color=\"Blue\">◄</font> ترجمه . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بیان و تعبیر کردن . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> تکلم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> طرز بیان . طریقه ٔ ادای سخن . (ناظم الاطباء) <span class=\"hlight\">:</span> آنجا که عبادت باید عبارت سود ندارد. (کشف المحجوب ). تکرار کلام نکردی و اگر همان لفظ اتفاق افتاد به عبارت دیگر بگفتی . (گلستان ).<br />حدیث عشق ز حافظ شنو نه از واعظ<br />اگرچه صنعت بسیار در عبارت کرد.<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عبارت رؤیا</span> ؛ تعبیر کردن و خبر دادن از فرجام آنچه خواب بدان باز می گردد. (از اقرب الموارد). بیان کردن خواب را و خبر دادن از مآل کار. (منتهی الارب ) (ناظم الاطباء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عبارت کلام </span> ؛ تفسیر کردن سخن را. (منتهی الارب ) (ناظم الاطباء).<br /><BR><font color=\"Blue\">◄</font> عبارة طیر؛ زجر آن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> قصد و مراد. اراده . <BR><font color=\"Blue\">◄</font> انشاء. (ناظم الاطباء).<br /></font></div>'),
(179903, 'عبارت آرای', '<span class=\"hlight\">عبارت آرای .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (نف مرکب ) ترتیب دهنده ٔ عبارت و آرایش کننده ٔ سخن . (ناظم الاطباء).<br /></font></div>'),
(179904, 'عبارت آرایی', '<span class=\"hlight\">عبارت آرایی .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (حامص مرکب ) عمل عبارت آرا. آرایش سخن به الفاظ نغز و شیوا <span class=\"hlight\">:</span> <br />بعد چندین عبارت آرائی <br />گفت با اوستاد کیپائی .<br /><font color=\"Red\">شیخ بهائی (نان و حلوا).</font><br /></font></div>'),
(179905, 'عبارت سنج', '<span class=\"hlight\">عبارت سنج .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ س َ ]</font></b> (نف مرکب ) انشاپرداز. (ناظم الاطباء).<br /></font></div>'),
(179906, 'عبارت پرداز', '<span class=\"hlight\">عبارت پرداز.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ پ َ ]</font></b> (نف مرکب ) عبارت آرای . آنکه مقصودخود را با عبارت شیوا بیان کند. رجوع بعبارت شود.<br /></font></div>'),
(179907, 'عبارت کردن', '<span class=\"hlight\">عبارت کردن .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ک َ دَ ]</font></b> (مص مرکب ) تعبیر کردن . <BR><font color=\"Blue\">◄</font> کنایه از سخن گفتن به کنایت است . (آنندراج ).<br /></font></div>'),
(179908, 'عبارد', '<span class=\"hlight\">عبارد.</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (ع ص ) جاریة عبارد؛ دختر سپیدرنگ و تازه بدن نازک و لرزان اندام . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> شاخ نرم و نازک . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(179909, 'عباری', '<span class=\"hlight\">عباری .</span> <font color=\"DarkGreen\"><b>[ ع َ را ]</font></b> (ع ص، اِ) ج ِ عبری . (ناظم الاطباء). رجوع به عبری شود.<br /></font></div>'),
(179910, 'عباریم', '<span class=\"hlight\">عباریم .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) (مخاضات ) سفر اعداد <span class=\"hlight\" dir=\"rtl\">٢٧</span>:<span class=\"hlight\" dir=\"rtl\">١٢</span> و <span class=\"hlight\" dir=\"rtl\">٣٣</span>:<span class=\"hlight\" dir=\"rtl\">٤٧</span> سفر تثنیه <span class=\"hlight\" dir=\"rtl\">٣٢</span>:<span class=\"hlight\" dir=\"rtl\">٤٩</span> کتاب ارمیا <span class=\"hlight\" dir=\"rtl\">٢٢</span>:<span class=\"hlight\" dir=\"rtl\">٢</span> اسم سلسله کوههایی است که از شمال به جنوب شرقی اردن که سلسله قله های موآب شمالی است واقع است از جمله قله های این سلسله در سفر اعداد <span class=\"hlight\" dir=\"rtl\">٢١</span>:<span class=\"hlight\" dir=\"rtl\">١</span> عییی عباریم یعنی کومه ٔ عباریم خوانده شده است . (قاموس کتاب مقدس ).<br /></font></div>'),
(179911, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن فرج الریاشی البصری . از لغویان و روات و مورخان عرب بود. وی به سال <span class=\"hlight\" dir=\"rtl\">١٧٧</span> هَ . ق . در بصره متولدشد و به سال <span class=\"hlight\" dir=\"rtl\">٢٥٧</span> در فتنه ٔ صاحب الزنج به قتل رسید. او راست : کتاب الخیل و کتاب الابل و ما اختلف اسماؤه من کلام العرب، و کتابهای دیگر. (از الاعلام زرکلی ).<br /></font></div>'),
(179912, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (ع ص ) صیغه ٔ مبالغه . بسیار ترش روی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) شیر بیشه . (ناظم الاطباء) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شیری که شیران از او بگریزند. (از اقرب الموارد).<br /></font></div>'),
(179913, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) شاه عباس اول . رجوع به عباس اول شود.<br /></font></div>'),
(179914, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) شاه عباس دوم . رجوع به عباس دوم شود.<br /></font></div>'),
(179915, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن موسی بن عیسی العباسی الهاشمی . به سال <span class=\"hlight\" dir=\"rtl\">١٩٨</span> هَ . ق . از جانب مأمون ولایت مصر یافت و به سال <span class=\"hlight\" dir=\"rtl\">١٩٩</span> بدانجا رفت و مستقر شد... و در همان سال مسموم گردید و درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(179916, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن ملک المجاهد علی بن مؤید داودبن المظفر یوسف الرسولی الغسانی الجفنی ملقب به الملک الافضل . از پادشاهان دولت رسولی یمن و از مورخان بزرگ است و لقب ضرغام الدین یافت . وی بعد از مرگ پدر خود به سال <span class=\"hlight\" dir=\"rtl\">٧٦٤</span> هَ . ق . ولایت یافت و از علم و ادب و تاریخ بهره کافی داشت . او را تألیفاتی است، از جمله : بغیة ذوی الهمم فی التعریف بانساب العرب و العجم، نزهة العیون فی معرفة الطوایف و القرون، العطایا السنیه فی المناقب الیمنیه، نزهة الابصار فی اختصار کنز الاخبار. وی به سال <span class=\"hlight\" dir=\"rtl\">٧٧٨</span> هَ . ق . در زبید درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(179917, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن مرداس بن ابی عامر السلمی . از مردم مضرو از شعرا و فرسان عرب و از عقیق بود. جاهلیت و اسلام را درک کرد. و پیش از فتح مکه اسلام آورد و در جنگهای اسلام شرکت کرد. سپس به قوم خود بازگشت و به سال <span class=\"hlight\" dir=\"rtl\">١٨</span> هَ . ق . در زمان خلافت عمر درگذشت . (از الاعلام زرکلی ). و رجوع به منتهی الارب و تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٢٤٦</span> شود.<br /></font></div>'),
(179918, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن محمدالهاشمی . ازحفاظ حدیث و ثقات است . او را کتابی است در رجال که از یحیی بن معین حکایت کرده است . (از الاعلام زرکلی ).<br /></font></div>'),
(179919, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن فضل الانصاری الواقفی . یکی از قضاة و رجال حدیث و عالم به قراآت و شعر بود. مولد او بصره است و در زمان خلافت رشید قضاوت موصل یافت . وی به سال <span class=\"hlight\" dir=\"rtl\">١٨٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ). و رجوع به موشح ص <span class=\"hlight\" dir=\"rtl\">٢٦٨</span> شود.<br /></font></div>'),
(179920, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن فرناس . از مخترعین اندلس و از مردم قرطبه است و ظاهراً وی درعصر خلیفه عبدالرحمان دوم می زیسته است . (قرن نهم میلادی ). وی اولین کسی است که صنعت شیشه و سنگ تراشی رادر اندلس بوجود آورد و آلتی درست کرد بنام المثقال لمعرفة الاوقات و نقشه ٔ آسمان را با ستارگان و ابرها و برق و رعد در منزل خود نصب کرد، و تصمیم داشت که به آسمانها پرواز کند، و از این جهت برای خود پرها و بالهائی ساخت و به هوا پرید و مسافت زیادی را نیز طی کرد و بر زمین افتاد و مجروح شد. او راست : اشعاری در وصف نقشه ٔ آسمان و پرواز خود. (از الاعلام زرکلی ).<br /></font></div>'),
(179921, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با]</font></b> (اِخ ) ابن عبادةبن نضله از بنی سالم بن عوف . یکی از<span class=\"hlight\" dir=\"rtl\">٧٠</span> تن است که در عقبه با حضرت رسول بیعت کرد. وی درجنگ احد شهید شد. (از تاریخ گزیده صص <span class=\"hlight\" dir=\"rtl\">٢٣٦</span> - <span class=\"hlight\" dir=\"rtl\">٢٣٨</span>).<br /></font></div>'),
(179922, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن عبدالمطلب بن هاشم بن عبدمناف . از بزرگان قریش در عصر جاهلیت و اسلام بود و جد خلفای عباسی است . پیغمبر (ص ) در وصف وی گوید که وی بخشنده ترین مردم قریش بود. با خویشان خود حسن سلوک داشت و در عقل و ذکاوت معروف بود. با بردگی و برده داری مخالفت میکرد و عده ٔ زیادی از بردگان را آزاد نمود. منصب سقایة الحاج و عمارت بیت الحرام به وی رسید. قبل از هجرت رسول در خفا اسلام آورد و در مکه بماند و اخبار مشرکین را به پیغمبر گزارش میداد سپس به مدینه مهاجرت کرد و در واقعه ٔ حنین و فتح مکه شرکت داشت، وی در اواخر عمر از بینائی محروم شد. در صحیح بخاری و مسلم <span class=\"hlight\" dir=\"rtl\">٣٥</span> حدیث از او نقل شده است . عباس به سال <span class=\"hlight\" dir=\"rtl\">٣٢</span> هَ . ق . در زمان خلافت عثمان درگذشت و در بقیع مدفون گردید. (از الاعلام زرکلی ) و رجوع به دائرةالمعارف فرید وجدی و قاموس الاعلام ترکی و تاریخ گزیده شود.<br /></font></div>'),
(179923, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن عبداﷲ شیبانی . یکی از والیان هرات بعد از درگذشت عبداﷲ طاهر است . (تاریخ خاندان طاهری ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span>).<br /></font></div>'),
(179924, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْبا ]</font></b> (اِخ ) ابن عبداﷲ المأمون بن هارون الرشید. وی به سال <span class=\"hlight\" dir=\"rtl\">٢١٣</span> هَ . ق . از جانب پدر خود ولایت جزیرة و سرحدات را یافت و بعد از مرگ مأمون با خلافت معتصم مخالفت کرد و به دست وی گرفتار شد و تحت شکنجه قرار گرفت و در سال <span class=\"hlight\" dir=\"rtl\">٢٢٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(179925, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن عبدالجلیل بن عبدالرحمان التغلبی . امیر یمانی . اصل او از جبل ذخر است و امارت زبید و عدن یافت . وی را همت عالی بود و ثروت بسیاری داشت از جمله آثار نیک او مسجدی است در ابیات حسین و مسجد قریه ٔ سلامه و مدرسه ای در ذخر. وی به سال <span class=\"hlight\" dir=\"rtl\">٦٦٤</span> هَ . ق . به زبید درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(179926, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) شاه عباس سوم . رجوع به عباس سوم شود.<br /></font></div>'),
(179927, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن احنف بن اسود الحنفی الیمامی، مکنی به ابوالفضل . یمانی الاصل است . او راست : دیوانی معروف به دیوان احنف . رجوع به ابوالفضل ابی احنف شود.<br /></font></div>'),
(179928, 'عباس', '<span class=\"hlight\">عباس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ابن سهل بن سعد تابعی است . (منتهی الارب ). و رجوع به مجمل التواریخ ص <span class=\"hlight\" dir=\"rtl\">٣٠٦</span> شود.<br /></font></div>'),
(179929, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان کنبگی بخش فهرج شهرستان بم . واقع در <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی جنوب خاوری فهرج و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی جنوب راه فرعی بم برگیان . ناحیه ای است جلگه ای و گرمسیر و مالاریایی با <span class=\"hlight\" dir=\"rtl\">١٩٨</span> تن سکنه . آب آن از قنات تأمین میشود. محصولات آن غلات، حنا، مرکبات و خرما است . اهالی به کشاورزی اشتغال دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179930, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان برج اکرم بخش فهرج شهرستان بم . واقع در <span class=\"hlight\" dir=\"rtl\">٢٠</span>هزارگزی باختر فهرج، کنار شوسه ٔ بم به زاهدان . <span class=\"hlight\" dir=\"rtl\">٢٢</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179931, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان کوه پنج بخش مرکزی شهرستان سیرجان . واقع در <span class=\"hlight\" dir=\"rtl\">٨١</span>هزارگزی شمال خاوری سعیدآباد در مسیر راه مالرو گوداحمر به ده کوسه . ناحیه ای است کوهستانی و سردسیر. <span class=\"hlight\" dir=\"rtl\">٢٧٤</span> تن سکنه داردزبان آنها فارسی است و آب آن از قنات تأمین میشود محصولات آن غلات و حبوبات است . شغل اهالی کشاورزی است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179932, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان نوق شهرستان رفسنجان . واقع در <span class=\"hlight\" dir=\"rtl\">٦٥</span>هزارگزی شمال باختری رفسنجان و سه هزارگزی خاور راه مالرو رفسنجان به بافق . شامل دو خانواده است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179933, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان ابراهیم آباد بخش مرکزی شهرستان سیرجان . واقع در سی هزارگزی جنوب سعیدآباد. سر راه شوسه ٔ بندرعباس به سیرجان . <span class=\"hlight\" dir=\"rtl\">١٥</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179934, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْبا ]</font></b> (اِخ ) دهی است از دهستان شقان بخش اسفراین شهرستان بجنورد. واقع در <span class=\"hlight\" dir=\"rtl\">١١٠</span>هزارگزی شمال باختری اسفراین و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی جنوب شوسه ٔ عمومی بجنورد به شقان . ناحیه ای است جلگه ای و سردسیر با <span class=\"hlight\" dir=\"rtl\">١١١</span> تن سکنه . آب آن از قنات تأمین میشود. محصولات آن غلات است اهالی به کشاورزی اشتغال دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179935, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از بخش راین شهرستان بم . واقع در هفت هزارگزی جنوب خاروی راین و هشت هزارگزی جنوب راه فرعی راین به نی بید. دو خانوار در آن زندگی میکنند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179936, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان کوهبنان بخش راور شهرستان کرمان . واقع در <span class=\"hlight\" dir=\"rtl\">٦٥</span>هزارگزی شمال باختری راور و هیجده هزارگزی شمال راه فرعی راور به کوهبنان . <span class=\"hlight\" dir=\"rtl\">٤٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179937, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ )ده کوچکی است از بخش شهداد شهرستان کرمان . واقع در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی خاور شهداد سر راه مالرو شهداد به نمکزار.<span class=\"hlight\" dir=\"rtl\">٥</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179938, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان طغرالجرد بخش زرند شهرستان کرمان . واقع در <span class=\"hlight\" dir=\"rtl\">٤٩</span>هزارگزی شمال زرند و ششهزارگزی خاور فرعی راور به زرند. <span class=\"hlight\" dir=\"rtl\">١٢</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179939, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان میلانلو بخش شیروان شهرستان قوچان . واقع در <span class=\"hlight\" dir=\"rtl\">٦٢</span>هزارگزی جنوب باختری شیروان و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی جنوب مالرو عمومی امیران . ناحیه ای است جلگه ای، آب و هوای آن معتدل و <span class=\"hlight\" dir=\"rtl\">١٩٨</span> تن سکنه دارد. آب آن از قنات تأمین میشود و محصولات آن غلات، پنبه توتون و انگور است . اهالی به کشاورزی و مالداری اشتغال دارند و صنایع دستی آنان قالیچه بافی است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179940, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی از دهستان حومه ٔ بخش خاش شهرستان زاهدان . واقع در <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی شمال خاش کنار شوسه ٔ خاش به زاهدان . ناحیه ای است جلگه ای و گرمسیر و مالاریایی با <span class=\"hlight\" dir=\"rtl\">٨٠</span> تن سکنه . آب آن از قنات تأمین میشود. محصولات آن غلات و لبنیات است اهالی به کشاورزی و گله داری اشتغال دارند. راه شوسه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179941, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان کوه پنج بخش مرکزی شهرستان سیرجان . واقع در <span class=\"hlight\" dir=\"rtl\">١٠٠</span>هزارگزی شمال خاروی سعیدآباد به سر راه مالرو خانه سرخ به گود احمر. <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179942, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span><font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان ساردوئیه بخش بافت شهرستان سیرجان . واقع در <span class=\"hlight\" dir=\"rtl\">١٦</span>هزارگزی جنوب بافت و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی باختر راه فرعی دولت آباد به ده سرد. <span class=\"hlight\" dir=\"rtl\">٢٤</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179943, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان رودخانه ٔ بخش میناب شهرستان بندرعباس . واقع در <span class=\"hlight\" dir=\"rtl\">٩٤</span>هزارگزی شمال میناب و پنج هزارگزی باختر راه مالرو گلاشکرد به میناب . <span class=\"hlight\" dir=\"rtl\">٢٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179944, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان دراگاه بخش سعادت آباد شهرستان بندرعباس واقع در <span class=\"hlight\" dir=\"rtl\">٣٠</span>هزارگزی شمال حاجی آباد و <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی خاور راه شوسه ٔ کرمان به بندرعباس . <span class=\"hlight\" dir=\"rtl\">٢٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179945, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان بهرآسمان بخش ساردوئیه شهرستان جیرفت . واقع در <span class=\"hlight\" dir=\"rtl\">٣٨</span>هزارگزی جنوب خاوری ساردوئیه و <span class=\"hlight\" dir=\"rtl\">٢٠</span>هزارگزی باختر راه مالرو جیرفت به ساردوئیه .<span class=\"hlight\" dir=\"rtl\">٣</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179946, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان هنزا بخش ساردوئیه شهرستان جیرفت . واقع در <span class=\"hlight\" dir=\"rtl\">١٦</span>هزارگزی باختر ساردوئیه و سه هزارگزی باختر شمال راه مالرو بافت به ساردوئیه با <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179947, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان رودبار بخش کهنوج شهرستان جیرفت . واقع در سی هزارگزی شمال خاوری کهنوج و <span class=\"hlight\" dir=\"rtl\">١٥</span>هزارگزی خاور راه فرعی کهنوج به سبزواران . ناحیه ای است جلگه ای و گرمسیر با <span class=\"hlight\" dir=\"rtl\">٥٥٠</span> تن سکنه . آب آن از رودخانه تأمین میشود. محصولات آن غلات است اهالی به کشاورزی اشتغال دارندراه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179948, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است ازدهستان سبزواران بخش مرکزی شهرستان جیرفت . واقع در یازده هزارگزی جنوب خاوری سبزواران و یک هزارگزی راه فرعی سبزواران به عنبرآباد. ناحیه ای است جلگه ای و گرمسیر و مالاریایی با <span class=\"hlight\" dir=\"rtl\">٦٣٠</span> تن سکنه . آب آن از رودخانه ٔ هلیل تأمین میشود. محصولات آن غلات است اهالی به کشاورزی اشتغال دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179949, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان قلعه گنج بخش کهنوج شهرستان جیرفت . واقع در <span class=\"hlight\" dir=\"rtl\">٣٢</span>هزارگزی جنوب رودخانه ٔ هلیل . ناحیه ای است جلگه ای و گرمسیر با <span class=\"hlight\" dir=\"rtl\">٨٠</span> تن سکنه . آب آن از رودخانه تأمین میشود. محصولات آن غلات و حبوبات است . اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179950, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ بخش زرند شهرستان کرمان . واقع در <span class=\"hlight\" dir=\"rtl\">١٥</span>هزارگزی باختر زرند و <span class=\"hlight\" dir=\"rtl\">٥</span>هزارگزی جنوب راه مالرو بافق به زرند. ناحیه ای است جلگه ای و آب و هوای معتدل و <span class=\"hlight\" dir=\"rtl\">٦٩</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات و پنبه است . اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179951, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان گوهرکوه بخش خاش شهرستان زاهدان . واقع در <span class=\"hlight\" dir=\"rtl\">٥٠</span> هزارگزی باختر خاش و <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی جنوب نرماشیر به خاش . شامل سه خانواده است . راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179952, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است جزءدهستان فراحان بالا بخش فرمهین شهرستان اراک . واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی جنوب خاوری فرمهین . ناحیه ای است کوهستانی . <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه دارد زبان آنها فارسی است آب آن از قنات تأمین میشود محصولات آن غلات، بنشن . اهالی به کشاورزی اشتغال دارند. راه مالرو دارد و از داودآباد اتومبیل میتوان برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(179953, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان مؤمن آباد بخش درمیان شهرستان بیرجند. واقع در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی جنوب درمیان و <span class=\"hlight\" dir=\"rtl\">٥</span>هزارگزی خاور راه مالرو عمومی درمیان به سربیشه . ناحیه ای است دامنه . هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">١١</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، شلغم، لبنیات است و اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179954, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان کرون بخش نجف آباد شهرستان اصفهان . واقع در <span class=\"hlight\" dir=\"rtl\">٣٥</span>هزارگزی باختر نجف آباد و <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی شوسه ٔ نجف آباد به دامنه . ناحیه ای است جلگه ای . هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٤١</span> تن سکنه دارد. آب آن از رودخانه تأمین میشود. محصولات آن غلات است اهالی به کشاورزی اشتغال دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(179955, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ بخش شهربابک شهرستان یزد. واقع در <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی باختر شهربابک کنار راه فرعی شهربابک به هرات خوره . ناحیه ای است جلگه ای . آب و هوای آن معتدل و مالاریایی است . <span class=\"hlight\" dir=\"rtl\">٣٧٤</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات است اهالی به کشاورزی اشتغال دارند. صنایع دستی زنان قالیبافی است . راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(179956, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده مخروبه ای است از دهستان سمیرم پایین بخش سمیرم شهرستان شهرضا. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(179957, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان دیناوران بخش اردل شهرستان شهرکرد. واقع در <span class=\"hlight\" dir=\"rtl\">٢٥</span>هزارگزی باختر اردل و <span class=\"hlight\" dir=\"rtl\">٤٢</span>هزارگزی راه اردل . ناحیه ای است جلگه ای . آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">١٧٦</span> تن سکنه دارد. آب آن از ارتفاعات تأمین میگردد. محصولات آن غلات است . اهالی به کشاورزی و گله داری اشتغال دارند. راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(179958, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان گلمکان بخش طرقبه ٔ شهرستان مشهد. واقع در <span class=\"hlight\" dir=\"rtl\">٢٦</span>هزارگزی شمال باختری طرقبه . ناحیه ای است کوهستانی هوای آن معتدل است، <span class=\"hlight\" dir=\"rtl\">٢٦</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، بنشن و میوه جات است اهالی به کشاورزی اشتغال دارند راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179959, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان یوسف آباد پایین ولایت باخرز بخش طیبات شهرستان مشهد. واقع در <span class=\"hlight\" dir=\"rtl\">٣٣</span>هزارگزی شمال باختری طیبات . ناحیه ای است جلگه ای . هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٦٩</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات و زیره است . اهالی به کشاورزی و مالداری اشتغال دارند صنایع دستی آنهاقالیچه بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179960, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان کندکلی بخش سرخس شهرستان مشهد. واقع در چهارهزارگزی شمال باختری سرخس و سه هزارگزی خاور اتومبیل رو سرخس به چهل کمان . ناحیه ای است جلگه ای و گرمسیر، <span class=\"hlight\" dir=\"rtl\">٣٨٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن بنشن و اهالی به کشاورزی و مالداری اشتغال دارند و صنایع دستی آنها قالیچه، کرباس و شال بافی است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179961, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان چناران بخش حومه ٔ اراک شهرستان مشهد. واقع در <span class=\"hlight\" dir=\"rtl\">٦٦</span> هزارگزی شمال باختری مشهد کنار راه قدیمی مشهد به قوچان . ناحیه ای است جلگه ای و آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٩٨</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات چغندر و کنجداست . اهالی به کشاورزی و مالداری اشتغال دارند. راه اتومبیل رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179962, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با]</font></b> (اِخ ) دهی است از دهستان چولائی خانه بخش حومه ٔ ارداک شهرستان مشهد. واقع در <span class=\"hlight\" dir=\"rtl\">٣٨</span>هزارگزی شمال مشهد و <span class=\"hlight\" dir=\"rtl\">٧</span>هزارگزی باختر راه مشهد به کلات . ناحیه ای است دامنه و سردسیر. <span class=\"hlight\" dir=\"rtl\">٢٧</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات است اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179963, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان سرولایت بخش سرولایت شهرستان نیشابور. واقع در <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی شمال باختری چکنه بالا. ناحیه ای است کوهستانی . هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٦٤٨</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات است . اهالی به کشاورزی اشتغال دارند صنایع دستی کرباس بافی است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179964, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان شاخنات بخش درمیان شهرستان بیرجند. واقع در <span class=\"hlight\" dir=\"rtl\">١٠٢</span>هزارگزی شمال باختری بیرجند و <span class=\"hlight\" dir=\"rtl\">٢١</span>هزارگزی شمال خاروی شاخن . ناحیه ای است کوهستانی . هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">١٥٧</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات و لبنیات است . اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179965, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان اصفهک بخش طبس شهرستان فردوس . واقع در <span class=\"hlight\" dir=\"rtl\">٢٥</span>هزارگزی جنوب خاوری طبس و یکهزارگزی جنوب اصفهک . ناحیه ای است جلگه ای و گرمسیر با <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه . آب آن از قنات تأمین میشود. محصولات آن غلات است اهالی به کشاورزی اشتغال دارند. راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(179966, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span><font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان نیمبلوک بخش قاین شهرستان بیرجند واقع در <span class=\"hlight\" dir=\"rtl\">٥٥</span>هزارگزی شمال باختری قاین . ناحیه ای است جلگه ای و گرمسیر. <span class=\"hlight\" dir=\"rtl\">٤٨</span> تن سکنه دارد.آب آن از قنات تأمین میشود. محصولات آن غلات است . اهالی به کشاورزی، مالداری و قالیچه بافی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179967, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان ذهان بخش قاین شهرستان بیرجند واقع در <span class=\"hlight\" dir=\"rtl\">٦٢</span>هزارگزی جنوب خاوری قاین و <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی باختر اتومبیل رو اسفدان به اسغج . ناحیه ای است جلگه ای و گرمسیر، <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات و پنبه است اهالی به کشاورزی مالداری، قالیچه بافی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179968, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان نهارجانات بخش حومه ٔ شهرستان بیرجند. واقع در سی هزارگزی جنوب خاوری بیرجند. ناحیه ای است دامنه . آب و هوای آن معتدل است، <span class=\"hlight\" dir=\"rtl\">٤٢</span> تن سکنه دارد. زبان آنها فارسی است . آب آن از قنات تأمین میشود محصولات آن غلات و بنشن است . اهالی به کشاورزی و کرباس بافی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179969, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان طبس مینا بخش درمیان شهرستان بیرجند. واقع در <span class=\"hlight\" dir=\"rtl\">٣٤</span>هزارگزی جنوب خاوری درمیان سر راه مالرو عمومی درمیان به درح . ناحیه ای است کوهستانی آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">١٤</span> تن سکنه دارد. آب آن از قنات تأمین میشود محصولات آن غلات، شلغم و چغندر است اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179970, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان القورات بخش حومه ٔ شهرستان بیرجند. واقع در سی هزارگزی شمال خاوری بیرجند. ناحیه ای است کوهستانی . آب و هوای آن معتدل است . سه تن سکنه دارد. آب آن از قنات تأمین میشود محصولات آن غلات است . اهالی به کشاورزی اشتغال دارندراه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179971, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان مرکزی بخش خوسف شهرستان بیرجند. واقع در <span class=\"hlight\" dir=\"rtl\">٣٤</span>هزارگزی جنوب خوسف . ناحیه ای است کوهستانی و گرمسیر. <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود محصولات آن غلات است . اهالی به کشاورزی و بوته فروشی اشتغال دارند. راه مالرو دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179972, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان بالاخواف بخش خواف شهرستان تربت حیدریه . واقع در <span class=\"hlight\" dir=\"rtl\">٤٣</span>هزارگزی شمال باختری رود و سه هزارگزی شوسه ٔ عمومی تربت حیدریه . ناحیه ای است جلگه ای و گرمسیر با <span class=\"hlight\" dir=\"rtl\">٢٦٧</span> تن سکنه . آب آن از قنات تأمین میشود. محصولات آن غلات، پنبه و زیره است اهالی به کشاورزی و گله داری اشتغال دارند. صنایع دستی آنها قالیچه بافی است . راه اتومبیل رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179973, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان بالاولایت بخش حومه شهرستان تربت حیدریه . واقع در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی شمال تربت حیدریه، سرراه شوسه ٔ عمومی مشهد به بیرجند. ناحیه ای است دامنه ای، آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٦٨</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات و میوه است اهالی به کشاورزی، گاوداری، گله داری اشتغال دارند، راه اتومبیل رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179974, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان سنگان بخش رشخوار شهرستان تربت حیدریه . واقع در <span class=\"hlight\" dir=\"rtl\">١٥</span>هزارگزی شمال باختری رشخوار و سه هزارگزی جنوب شوسه ٔ عمومی تربت به رشخوار. ناحیه ای است جلگه ای و گرمسیر با <span class=\"hlight\" dir=\"rtl\">٣٨٠</span> تن سکنه . آب آن از قنات تأمین میشود محصولات آن غلات و پنبه است اهالی به کشاورزی و گله داری اشتغال دارند صنایع دستی قالیچه و برک بافی است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179975, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان مصعبی بخش حومه ٔ شهرستان فردوس . واقع در <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی خاور فردوس سر راه مالرو عمومی نوغاب به فردوس . ناحیه ای است کوهستانی . آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، زعفران، میوه، بنشن و زیره است و اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(179976, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است جزء دهستان رودبار بخش طرخوران شهرستان اراک . واقع در <span class=\"hlight\" dir=\"rtl\">٤٢</span>هزارگزی شمال باختری طرخوران و <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی راه عمومی . ناحیه ای است جلگه ای معتدل <span class=\"hlight\" dir=\"rtl\">١١٧</span> تن سکنه دارد. آب آن از رود قره چای و در بهار از رود آرزومند تأمین میشود. محصولات آن غلات، بنشن، پنبه . اهالی به زراعت گذران میکنند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(179977, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان گاودول بخش مرکزی شهرستان مراغه . واقع در <span class=\"hlight\" dir=\"rtl\">٢٩</span>هزاروپانصد گزی جنوب باختر مراغه و <span class=\"hlight\" dir=\"rtl\">٤</span>هزارگزی باختر شوسه ٔ مراغه به میاندوآب . جلگه با آب و هوای معتدل و <span class=\"hlight\" dir=\"rtl\">١٧٦</span> تن سکنه . آب آن از مردی چای و چاه تأمین میشود. محصولات آن غلات، چغندر، کشمش و نخود است . شغل اهالی کشاورزی است و صنایع دستی جاجیم بافی است راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span> و <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(179978, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان آختاچی بوکان بخش بوکان شهرستان مهاباد. واقع در <span class=\"hlight\" dir=\"rtl\">١٤</span>هزاروپانصد گزی شمال بوکان و یکهزاروپانصد گزی باختر راه شوسه ٔ بوکان به میاندوآب . جلگه با آب و هوای معتدل و مالاریایی و <span class=\"hlight\" dir=\"rtl\">٨٠</span> تن سکنه دارد. آب آن از رودخانه ٔ تاتائو تأمین میشود و محصولات آن غلات، توتون و حبوبات است . شغل اهالی زراعت و گله داری است صنایع دستی آنها جاجیم بافی است . راه شوسه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span> و <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(179979, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است جزء دهستان ابرغان بخش مرکزی شهرستان سراب . واقع در <span class=\"hlight\" dir=\"rtl\">٣٨</span>هزارگزی باختر سراب و <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی راه شوسه ٔ سراب تبریز. کوهستانی با آب و هوای معتدل . <span class=\"hlight\" dir=\"rtl\">١٠</span> تن سکنه دارد. آب آن از چشمه تأمین میشود محصولات آن غلات و نخود و شغل اهالی زراعت است . راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span> و <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(179980, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با]</font></b> (اِخ ) دهی است از دهستان مواضعخان بخش ورزقان شهرستان اهر واقع در <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی جنوب ورزقان و <span class=\"hlight\" dir=\"rtl\">١٣</span>هزارگزی شوسه ٔ تبریز به اهر. ناحیه ای است کوهستانی با آب و هوای معتدل . <span class=\"hlight\" dir=\"rtl\">٤٨٩</span> تن سکنه دارد. آب آن از چشمه ٔ تأمین میشود. محصولات آن غلات و حبوبات است . شغل اهالی زراعت و گله داری است . صنایع دستی آنها گلیم بافی است . راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span> و <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(179981, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان مرکزی بخش آستارا شهرستان اردبیل واقع در <span class=\"hlight\" dir=\"rtl\">١١</span>هزارگزی جنوب آستارا و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی راه شوسه ٔ آستارا و بندر انزلی . جنگل، گرمسیر، مرطوب و مالاریایی است . <span class=\"hlight\" dir=\"rtl\">٢٩٥</span> تن سکنه دارد. آب آن از رودخانه و چشمه تأمین میشود محصولات آن برنج و صیفی است . شغل اهالی زراعت و گله داری است اهالی به کشاورزی اشتغال دارند. راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span> و <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(179982, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان میان دورود بخش مرکزی شهرستان ساری . واقع در <span class=\"hlight\" dir=\"rtl\">٢٠</span>هزارگزی شمال خاوری ساری . ناحیه ای است واقع در دشت آب و هوای آن معتدل و مرطوب و مالاریایی است . <span class=\"hlight\" dir=\"rtl\">٨</span> تن سکنه دارد. آب آن از چاه تأمین میشود و محصولات آن لبنیات است شغل اهالی گوسفند و گاوداری است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(179983, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان کتول بخش علی آباد شهرستان گرگان . واقع در <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی جنوب باختری علی آباد. دامنه و آب و هوای آن معتدل ومرطوب و مالاریایی است . <span class=\"hlight\" dir=\"rtl\">١٨٥</span> تن سکنه دارد. آب آن از رودخانه ٔ کفش گیری تأمین میشود. محصولات آن برنج، غلات، توتون، سیگار و مختصری ابریشم و شغل اهالی زراعت وگله داری است . صنایع دستی زنان کرباس و شال بافی است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(179984, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است ازدهستان حومه بخش حومه ٔ شهرستان دامغان . واقع در <span class=\"hlight\" dir=\"rtl\">٦</span>هزارگزی جنوب خاوری دامغان و <span class=\"hlight\" dir=\"rtl\">٣</span>هزارگزی ایستگاه . جلگه وآب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٤٨</span> تن سکنه دارد. آب آن ازچشمه علی و قنات تأمین میشود و محصولات آن غلات، پنبه، پسته، انگور و بنشن است . شغل اهالی زراعت و گاوداری است . از طریق ایستگاه راه فرعی دارد. از کویر نمک استخراج میکنند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(179985, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) قصبه ٔ مرکزی دهستان لنگا شهرستان شهسوار واقع در <span class=\"hlight\" dir=\"rtl\">٢١</span>هزارگزی جنوب خاوری شهسوار در سر راه شوسه ٔ شهسوار به چالوس . ناحیه ای است در دشت و هوای آن معتدل و مرطوب و مالاریایی است . <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> تن سکنه دارد. آب آن از رودخانه ٔ کاظم رود تأمین میشود و محصولات آن برنج و لبنیات است .شغل اهالی زراعت است . دارای صندوق پست، پاسگاه نگهبانی و بهداری و دبستان است و در حدود <span class=\"hlight\" dir=\"rtl\">٢٠</span> باب دکان درکنار شوسه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(179986, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان فرومد بخش میامی شهرستان شاهرود واقع در <span class=\"hlight\" dir=\"rtl\">٧٢١</span>هزارگزی خاور میامی سر راه شوسه ٔ شاهرود به سبزوار. دامنه و آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٧٥٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات و میوه جات است . در حوالی این آبادی معدن مس وجود دارد کارخانه ٔ ذوب مس در آنجاست دارای دبستان است یک کاروانسرای معروف به شاه عباسی در آنجا است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(179987, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان راستوبی بخش سوادکوه شهرستان شاهی واقع در <span class=\"hlight\" dir=\"rtl\">٢٧</span>هزارگزی جنوب پل سفید و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی ایستگاه ورسک . کوهستانی و سردسیر و <span class=\"hlight\" dir=\"rtl\">٨٠٠</span> تن سکنه دارد. آب آن از سفیدچشمه تأمین میشود و محصولات آن غلات و لبنیات است . شغل اهالی زراعت است صنایع دستی آنها شال و کرباس بافی است راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(179988, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْبا ]</font></b> (اِخ ) دهی است جزء دهستان کزاز بالا بخش سربند شهرستان اراک . واقع در <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی شمال خاوری آستانه و <span class=\"hlight\" dir=\"rtl\">٣</span>هزارگزی راه آهن . ناحیه ای است کوهستانی معروف به سرآب . <span class=\"hlight\" dir=\"rtl\">٤٤٨</span> تن سکنه دارد. آب آن از چشمه تأمین میشود. محصولات آن غلات، انگور، میوه جات، بنشن و مختصر چغندرقند. اهالی به کشاورزی اشتغال دارند. از شاه زند اتومبیل میتوان برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(179989, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از بخش پشت آب شهرستان زابل . واقع در <span class=\"hlight\" dir=\"rtl\">١٩</span>هزارگزی شمال بنجار و شش هزارگزی راه مالرو خمک به زابل . ناحیه ای است جلگه ای و گرم و هوای آن معتدل است با <span class=\"hlight\" dir=\"rtl\">١٧٠</span> تن سکنه . آب آن از رود هیرمند تأمین میشود. محصولات آن غلات و لبنیات است . اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(179990, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است جزء دهستان سربند بالا بخش سربند شهرستان اراک نام قدیمی آن قره دره بوده . واقع در <span class=\"hlight\" dir=\"rtl\">٣٨</span>هزارگزی جنوب باختری سربند. و <span class=\"hlight\" dir=\"rtl\">٥٦</span> تن سکنه دارد. آب آن از قنات تأمین میشود محصولات آن غلات، انگور و میوه جات دیگر است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(179991, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان سلطانیه بخش مرکزی شهرستان زنجان . واقع در <span class=\"hlight\" dir=\"rtl\">٤٢</span>هزارگزی قیدار و <span class=\"hlight\" dir=\"rtl\">٦</span>هزارگزی راه عمومی . ناحیه ای است کوهستانی سردسیر. <span class=\"hlight\" dir=\"rtl\">١٩٦</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، بنشن . اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(179992, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان طارم پائین بخش سیردان شهرستان زنجان . واقع در <span class=\"hlight\" dir=\"rtl\">٢٦</span>هزارگزی جنوب سیردان و <span class=\"hlight\" dir=\"rtl\">١٥</span>هزارگزی راه عمومی . ناحیه ای است کوهستانی سردسیر و <span class=\"hlight\" dir=\"rtl\">٥٤٠</span> تن سکنه دارد مردم آن ترک زبانند. آب آن از چشمه سار تأمین میشود و محصولات آن غلات، بنشن است و اهالی به کشاورزی اشتغال دارند. راه مالرو و صعب العبور دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(179993, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان رستاق بخش خمین شهرستان محلات واقع در <span class=\"hlight\" dir=\"rtl\">٣٠٠٠</span>گزی شمال خمین و <span class=\"hlight\" dir=\"rtl\">١٠٠٠</span>گزی راه خمین به اراک . جلگه ای و آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">١٤٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود و محصولات آن غلات، چغندرقند، پنبه و انگور و شغل اهالی زراعت است . راه ماشین رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(179994, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است جزء دهستان حومه ٔ بخش زرند شهرستان ساوه واقع در <span class=\"hlight\" dir=\"rtl\">١١٠٠٠</span>گزی شمال باختر زرند جلگه ای آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٢٤٩</span> تن سکنه دارد. آب آن از قنات تأمین میشود محصولات آن غلات چغندرقند پنبه پیاز انگور بادام و انواع میوه جات است . شغل اهالی زراعت و گله داری است . صنایع دستی گلیم و جوال بافی است . راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(179995, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با]</font></b> (اِخ ) دهی است جزء دهستان خرقان شرقی بخش آوج شهرستان قزوین واقع در <span class=\"hlight\" dir=\"rtl\">٢٧٠٠٠</span>گزی شمال خاور آوج و <span class=\"hlight\" dir=\"rtl\">٤٠٠٠</span>گزی راه عمومی . جلگه ای و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٨٨٩</span> تن سکنه دارد. آب آن از رودخانه تأمین میشود و محصولات آن غلات، باغات و قلمستان است . شغل اهالی زراعت است . صنایع دستی قالی و جاجیم بافی است راه مالرو دارد ولی ماشین میتوان برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(179996, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از بخش دلیجان شهرستان محلات و <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(179997, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b>(اِخ ) ده کوچکی است از بخش مرکزی شهرستان دماوند و <span class=\"hlight\" dir=\"rtl\">١٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(179998, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است جزء دهستان بهنام پازکی بخش ورامین حومه شهرستان تهران واقع در <span class=\"hlight\" dir=\"rtl\">٢١٠٠٠</span>گزی شمال خاور ورامین کنار راه خراسان . جلگه ای آب و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه دارد. آب آن از رودخانه ٔ جاجرود تأمین میشود. محصولات آن غلات، صیفی، چغندرقند و شغل اهالی زراعت است . راه مالرو دارد و از طریق فیلستان ماشین رو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(179999, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است جزء دهستان حومه ٔ بخش کرج شهرستان تهران .واقع در <span class=\"hlight\" dir=\"rtl\">١٤٠٠٠</span>گزی جنوب باختر کرج و <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی راه فرعی کرج به اشتهارد، جلگه ای و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٩٣</span>تن سکنه دارد. آب آن از رودخانه ٔ کرج تأمین میشود محصولات آن غلات صیفی، بنشن، چغندرقند، قلمستان و شغل اهالی زراعت است . راه ماشین رو دارد. مزرعه ٔ امین آبادجزء این ده است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180000, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است جزء دهستان افشاریه ٔ ساوج بلاغ بخش کرج شهرستان تهران واقع در <span class=\"hlight\" dir=\"rtl\">٢٥٠٠٠</span> گزی باختر کرج و <span class=\"hlight\" dir=\"rtl\">٦٠٠٠٠</span> گزی جنوب راه شوسه ٔ کرج به قزوین . جلگه ای و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٣٥٥</span> تن سکنه دارد. آب آن از رود کردان تأمین میشود محصول آن غلات، صیفی، بنشن، انگور، لبنیات و شغل اهالی زراعت و گله داری است . راه فرعی از طریق قهوه خانه ٔ پل کردان دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180001, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان هیر بخش مرکزی شهرستان اردبیل . واقع در <span class=\"hlight\" dir=\"rtl\">٣٠</span>هزارگزی جنوب خاوری اردبیل و <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی راه شوسه ٔ خلخال اردبیل . کوهستانی با آب و هوای معتدل و <span class=\"hlight\" dir=\"rtl\">١٧٨</span> تن سکنه . آب آن از چشمه تأمین میشود محصولات آن غلات و حبوبات است اهالی به کشاورزی و گله داری اشتغال دارند. راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span> و <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(180002, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان خفرک بخش زرقان شهرستان شیراز. واقع در <span class=\"hlight\" dir=\"rtl\">٥٤</span> هزارگزی شمال خاوری زرقان و کنار راه فرعی خفرک به توابعارسنجان . ناحیه ای است جلگه ای با آب و هوای معتدل و مالاریایی و <span class=\"hlight\" dir=\"rtl\">٩٠</span> تن سکنه دارد. آب آنجا از چشمه تأمین میشود و محصولات آن غلات و چغندر است . اهالی به کشاورزی اشتغال دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(180003, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان رامجرد بخش اردکان شهرستان شیراز. واقع در <span class=\"hlight\" dir=\"rtl\">٦٧</span> هزارگزی جنوب خاور اردکان و چهارهزارگزی راه فرعی پل خان به کامفیروز. ناحیه ای است جلگه ای با هوای معتدل و <span class=\"hlight\" dir=\"rtl\">١٦٥</span> تن سکنه دارد. آب آن از رودخانه ٔ کر تأمین میشود. محصولات آن غلات و چغندر است . اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(180004, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان کامفیروز بخش اردکان شهرستان شیراز. واقع در <span class=\"hlight\" dir=\"rtl\">٤٥</span>هزارگزی خاور اردکان و یک هزارگزی راه فرعی پل خان به خانی من . <span class=\"hlight\" dir=\"rtl\">١٢</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(180005, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است ازدهستان حومه ٔ بخش مرکزی شهرستان آباده . واقع در <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی جنوب خاور آباده و کنار شوسه ٔ اصفهان بشیراز.ناحیه ای است جلگه ای و معتدل و <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات و جالیزکاری است صنایع دستی آنها گیوه بافی است . اهالی به کشاورزی اشتغال دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(180006, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است ازدهستان قنقری پائین (سفلا) بخش بوانات و سرچهان شهرستان آباده . واقع در <span class=\"hlight\" dir=\"rtl\">٣٠</span>هزارگزی باختر سوریان و شش هزارگزی شوسه ٔ شیراز به اصفهان . ناحیه ای است جلگه ای و سردسیر با <span class=\"hlight\" dir=\"rtl\">٢١٢</span> تن سکنه . آب آن از چشمه تأمین میشود. محصولات آن غلات، حبوبات و میوه جات است . اهالی به کشاورزی و باغبانی اشتغال دارند. صنایع دستی قالیبافی است . راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(180007, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان رونیز جنگل بخش مرکزی شهرستان فسا. واقع در <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی شمال فسا و <span class=\"hlight\" dir=\"rtl\">١٢</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180008, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان آبسرده بخش چقلوندی شهرستان خرم آباد. واقع در <span class=\"hlight\" dir=\"rtl\">٢١</span>هزارگزی شمال باختری چقلوندی و <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی باختر اتومبیل رو چقلوندی به بروجرد. ناحیه ای است دامنه ای و سردسیر مالاریایی با <span class=\"hlight\" dir=\"rtl\">٩٠</span> تن سکنه . آب آن از چشمه تأمین میشود. محصولات آن غلات، لبنیات و پشم و اهالی به کشاورزی و گله داری اشتغال دارند. از صنایع دستی زنان سیاه چادربافی است . راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180009, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان حسنوند بخش سلسله شهرستان خرم آباد. واقع در سه هزارگزی خاور الشتر و سه هزارگزی خاور شوسه ٔ خرم آباد به الشتر. ناحیه ای است جلگه ای و سردسیر و مالاریایی با <span class=\"hlight\" dir=\"rtl\">١٢٠</span> تن سکنه . آب آن از رود سراب رود تأمین میشود. محصولات آن غلات لبنیات و پشم است . اهالی به کشاورزی و گله داری اشتغال دارند. راه اتومبیل رو دارد. ساکنین از طایفه ٔ حسنوند هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180010, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان کاکاوند بخش دلفان شهرستان خرم آباد. واقع در سی هزارگزی شمال باختری نورآباد و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی خاور راه شوسه ٔ خرم آباد به کرمانشاه . ناحیه ای است تپه ماهور و سردسیر مالاریایی . <span class=\"hlight\" dir=\"rtl\">١٨٠</span> تن سکنه دارد. آب آن از چشمه و رود زاینده رود تأمین میشود محصولات آن غلات، لبنیات و پشم است . اهالی به کشاورزی و گله داری اشتغال دارند. راه مالرو دارد. ساکنین از طایفه غیب غلام هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180011, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span><font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان بروجرد بخش الیگودرز شهرستان بروجرد. واقع در <span class=\"hlight\" dir=\"rtl\">٨</span>هزارگزی شمال باختری الیگودرز به ازنا. ناحیه ای است جلگه ای با هوای معتدل و <span class=\"hlight\" dir=\"rtl\">٣٥١</span> تن سکنه . آب آن از قنات تأمین میشود و محصولات آن غلات، لبنیات، پنبه و چغندر است شغل اهالی زراعت و گله داری است صنایع دستی زنان جاجیم بافی است راه اتومبیل رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180012, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان والابخرد شهرستان بروجرد. واقع در <span class=\"hlight\" dir=\"rtl\">١٩</span>هزارگزی جنوب بروجرد و <span class=\"hlight\" dir=\"rtl\">١٣</span>هزارگزی خاور اتومبیل رو بروجرد. ناحیه ای است جلگه ای با آب و هوای معتدل و <span class=\"hlight\" dir=\"rtl\">٤٠٥</span> تن سکنه . آب آن از قنات تأمین میشود و محصولات آن غلات است و اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180013, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان جاپلق بخش الیگودرزشهرستان بروجرد. واقع در <span class=\"hlight\" dir=\"rtl\">٣٦</span>هزارگزی شمال باختر الیگودرز و ده هزارگزی باختر شوسه ٔ شاه زند به ازنا. ناحیه ای است جلگه با آب و هوای معتدل و <span class=\"hlight\" dir=\"rtl\">٢٧١</span> تن سکنه . آب آن از قنات و چاه تأمین میشود. محصولات آن غلات و لبنیات است اهالی به کشاورزی و گله داری اشتغال دارند. صنایع دستی زنان قالیبافی است . راه مالرو دارد اتومبیل هم میتوان برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180014, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان منجوان بخش خداآفرین شهرستان تبریز. واقع در <span class=\"hlight\" dir=\"rtl\">٢٥</span>هزارگزی جنوب خداآفرین و <span class=\"hlight\" dir=\"rtl\">١٧</span>هزارگزی راه شوسه ٔ اهر - کلیبر. کوهستانی با آب و هوای معتدل و <span class=\"hlight\" dir=\"rtl\">٢٦١</span> تن سکنه . آب آن از چشمه تأمین میشود. محصولات آن غلات است شغل اهالی زراعت و گله داری است . راه مالرو دارد و دارای محضر رسمی ازدواج و طلاق است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span> و <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(180015, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b>(اِخ ) دهی است از بخش دره شهرستان ایلام . واقع در <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی شمال باختری دره شهر و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی جنوب راه مالرو دره به ایلام . ناحیه ای است جلگه ای و گرمسیر با <span class=\"hlight\" dir=\"rtl\">٤٨٥</span>تن سکنه . آب آن از رودخانه ٔ صمیره تأمین میشود. محصولات آن غلات و لبنیات است . اهالی به کشاورزی و گله داری اشتغال دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180016, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان گاورود بخش کامیاران شهرستان سنندج . واقع در <span class=\"hlight\" dir=\"rtl\">٣٥</span>هزارگزی شمال کامیاران و یکهزارگزی خاور شوسه ٔ کرمانشاه به سنندج . ناحیه ای است کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه . آب آن از رودخانه و چشمه تأمین میشود. محصولات آن غلات و لبنیات است و شغل اهالی کشاورزی و گله داری است راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180017, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان لک بخش قروه ٔ شهرستان سنندج . واقع در <span class=\"hlight\" dir=\"rtl\">٣٦</span>هزارگزی شمال باختری قروه نزدیک پل فرهادآباد. <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180018, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان اورامان بخش زراب شهرستان سنندج واقع در <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی جنوب باختر زراب و دوهزارگزی نوین . ناحیه ای است کوهستانی . آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٣٧</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180019, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان پهلویدژ بخش بانه ٔشهرستان سنقر واقع در <span class=\"hlight\" dir=\"rtl\">١٦</span>هزارگزی جنوب خاوری بانه و شش هزارگزی مرز ایران و عراق . ناحیه ای است کوهستانی وسردسیر و <span class=\"hlight\" dir=\"rtl\">١٤٠</span> تن سکنه دارد. زبان آنها کردی است آب آن از چشمه و رودخانه ٔ پهلویدژ تأمین میشود. محصولات آن غلات، توتون و ماذوج است . راه مالرو دارد. شغل اهالی زراعت است در تابستان از بانه اتومبیل میتوان برد. نام قدیم آن کیله بوده چون در جنگهای سال <span class=\"hlight\" dir=\"rtl\">١٣٢٣</span> هَ. ش . بین افراد نظامی و یاغیان، سرباز وظیفه عباس نام در این آبادی کشته شده لذا به این مناسبت عباس آبادنامیده شده است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180020, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان نجف آباد شهرستان بیجار واقع در شش هزارگزی باختر نجف آباد. کنار راه شوسه ٔ بیجار به سنندج . ناحیه ای است کوهستانی وسردسیر. <span class=\"hlight\" dir=\"rtl\">٣٢٧</span> تن سکنه دارد. آب آن از چشمه تأمین میشود. محصولات آن غلات و لبنیات است . اهالی به کشاورزی و گله داری اشتغال دارند. صنایع دستی زنان قالیچه، گلیم و جاجیم بافی است راه مالرو دارد. به این ده حصارسفید هم میگویند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180021, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) نام محلی است از بخش سنجابی شهرستان کرمانشاهان . واقع در سه هزارگزی باختر گوزران . تابستان در حدود <span class=\"hlight\" dir=\"rtl\">٤٠</span> خانوار از طایفه ٔ کل کل سنجابی در آنجا زراعت کرده و اقامت دارند و در زمستان به اطراف قصرشیرین کوچ مینمایند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180022, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان کلیایی بخش سنقر کلیایی شهرستان کرمانشاهان . واقع در <span class=\"hlight\" dir=\"rtl\">١١</span>هزارگزی جنوب باختری سنقر و چهار هزارگزی باختر راه شوسه ٔ سنقر به کرمانشاه . ناحیه ای است دامنه ای سردسیر با <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه . آب آن از چشمه و قنات تأمین میشود. محصولات آن غلات، حبوبات و توتون است . اهالی به کشاورزی اشتغال دارند صنایع دستی قالیچه، جاجیم و پلاس بافی است راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180023, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان کنگاور بخش کنگاور شهرستان کرمانشاهان . واقع در <span class=\"hlight\" dir=\"rtl\">٥</span>هزارگزی جنوب کنگاور. ناحیه ای است واقع در دشت آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٢٥٥</span> تن سکنه دارد. آب آن از فاضل آب رودخانه ٔ فشن و کبوتر لانه و چشمه تأمین میشود. محصولات آن غلات دیمی و آبی، چغندرقند، پنبه است . و اهالی به کشاورزی اشتغال دارند. راه اتومبیل رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180024, 'عباس آباد', '<span class=\"hlight\">عباس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان چمچال صحنه شهرستان کرمانشاهان . واقع در <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی باختر صحنه و شش هزارگزی راه کرمانشاه به همدان . ناحیه ای است واقع در دامنه سردسیر هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٢٢٥</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، توتون، چغندرقند و حبوبات است . اهالی به کشاورزی اشتغال دارند. از راه صحنه و هاشم آباد اتومبیل میتوان برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180025, 'عباس آباد الویر', '<span class=\"hlight\">عباس آباد الویر.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با اَ ]</font></b> (اِخ ) دهی است از دهستان بخش خرقان شهرستان ساوه . واقع در <span class=\"hlight\" dir=\"rtl\">٦٠٠٠</span>گزی ساوه و <span class=\"hlight\" dir=\"rtl\">١٠٠٠</span>گزی راه عمومی فرقان . کوهستانی و سردسیر. <span class=\"hlight\" dir=\"rtl\">٤١١</span> تن سکنه دارد. آب آن از چشمه سار و قنات و رودخانه ٔ محلی تأمین میشود. محصولات آن غلات و سیب زمینی، بنشن، باغات، گردو وبادام است . شغل اهالی زراعت و گله داری است . صنایع دستی آنها جاجیم و گلیم بافی است . عده ای برای تأمین معاش به تهران میروند. راه در غیر مواقع بارندگی ماشین رو است . در <span class=\"hlight\" dir=\"rtl\">٣٠٠٠</span>گزی جنوب باختری آن قلعه خرابه ٔ قدیمی معروف به آق قلعه واقع شده و در نتیجه ٔ کاوش، آثار قدیم در آن دیده شده است . مزرعه ٔ اردونشین و چکان دره جزء این ده است . نزدیک به آق قلعه معادن خاک سفید و گچ دیده میشود. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180026, 'عباس آباد امین', '<span class=\"hlight\">عباس آباد امین .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ اَ ]</font></b> (اِخ ) دهی است از دهستان کشکوئیه شهرستان رفسنجان . واقع در <span class=\"hlight\" dir=\"rtl\">٧٢</span>هزارگزی شمال باختری رفسنجان و هفت هزارگزی خاور شوسه ٔ رفسنجان به یزد. ناحیه ای است جلگه ای و سردسیر. <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، پسته و پنبه است . اهالی به کشاورزی اشتغال دارند. راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180027, 'عباس آباد انار', '<span class=\"hlight\">عباس آباد انار.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ اَ ]</font></b> (اِخ ) دهی است از دهستان انار شهرستان رفسنجان . واقع در <span class=\"hlight\" dir=\"rtl\">٨٢</span>هزارگزی شمال باختری رفسنجان و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی شوسه ٔ رفسنجان به یزد. ناحیه ای است جلگه ای و سردسیر. <span class=\"hlight\" dir=\"rtl\">٥٥</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات و پنبه است . اهالی به کشاورزی اشتغال دارند. صنایع دستی آنها گلیم بافی است . راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180028, 'عباس آباد بالا', '<span class=\"hlight\">عباس آباد بالا.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ]</font></b> (اِخ ) دهی است از دهستان ابهررود بخش ابهررود شهرستان زنجان . واقع در <span class=\"hlight\" dir=\"rtl\">٢٧</span>هزارگزی جنوب باختری ابهر و <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی راه عمومی . ناحیه ای است کوهستانی سردسیر، <span class=\"hlight\" dir=\"rtl\">٢٣٦</span> تن سکنه دارد. آب آن از رودخانه ٔ قزلجه تأمین میشود. محصولات آن : غلات و عسل است اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(180029, 'عباس آباد بالا', '<span class=\"hlight\">عباس آباد بالا.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ]</font></b> (اِخ ) دهی است از دهستان بلوک شرقی بخش مرکزی شهرستان دزفول . واقع در <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی جنوب باختری دزفول و <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی جنوب باختر شوسه ٔ دزفول . <span class=\"hlight\" dir=\"rtl\">٤٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180030, 'عباس آباد بالا', '<span class=\"hlight\">عباس آباد بالا.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ]</font></b> (اِخ ) ده کوچکی است از دهستان حومه ٔ بخش زرند شهرستان کرمان . واقع در سی هزارگزی شمال باختری زرند و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی جنوب راه مالرو زرند بافق .<span class=\"hlight\" dir=\"rtl\">٤</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180031, 'عباس آباد بی نیاز', '<span class=\"hlight\">عباس آباد بی نیاز.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ]</font></b> (اِخ ) ده کوچکی است از بخش شهریار شهرستان تهران . واقع در <span class=\"hlight\" dir=\"rtl\">٢٨٠٠</span>گزی علیشاه عوض و <span class=\"hlight\" dir=\"rtl\">٢٠٠٠</span>گزی راه ماشین رو فرعی کرج به اشتهارد. <span class=\"hlight\" dir=\"rtl\">٢٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180032, 'عباس آباد جدید', '<span class=\"hlight\">عباس آباد جدید.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ج َ ]</font></b> (اِخ ) دهی است از دهستان سنگان بخش رشخوار شهرستان تربت حیدریه . واقع در <span class=\"hlight\" dir=\"rtl\">١٦</span>هزارگزی شمال باختری رشخوار و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی جنوب شوسه ٔ عمومی تربت به رشخوار. ناحیه ای است جلگه ای و گرمسیر. <span class=\"hlight\" dir=\"rtl\">٦١٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات وپنبه و بنشن است و اهالی به کشاورزی و گله داری اشتغال دارند. صنایع دستی آنها قالیچه و کرباس بافی است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180033, 'عباس آباد جلگه', '<span class=\"hlight\">عباس آباد جلگه .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ج ُ گ َ ]</font></b> (اِخ ) دهی است از دهستان دستگردان بخش طَبس شهرستان فردوس . واقع در <span class=\"hlight\" dir=\"rtl\">١١٠</span>هزارگزی شمال طبس دشت، گرمسیر و خشک . <span class=\"hlight\" dir=\"rtl\">١٨</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180034, 'عباس آباد حاجی', '<span class=\"hlight\">عباس آباد حاجی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ]</font></b> (اِخ ) دهی است از دهستان حومه خاوری رفسنجان . واقع در <span class=\"hlight\" dir=\"rtl\">٥</span>هزارگزی شمال خاوری شهرستان رفسنجان و <span class=\"hlight\" dir=\"rtl\">٦</span>هزارگزی شمال شوسه ٔ رفسنجان به کرمان . ناحیه ای است جلگه ای و سردسیر. <span class=\"hlight\" dir=\"rtl\">٥٣٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، پسته، پنبه و لبنیات است . اهالی به کشاورزی و گله داری اشتغال دارند. راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180035, 'عباس آباد حجازی', '<span class=\"hlight\">عباس آباد حجازی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ح ِ ]</font></b> (اِخ ) ده کوچکی است از دهستان فراهان بالا بخش فرمهین شهرستان اراک . واقع در <span class=\"hlight\" dir=\"rtl\">١٥</span>هزارگزی شمال باختری فرمهین و سه هزارگزی راه فرمهین به بلوک ضیاءالملک . آب آن از قنات تأمین میشود. محصولات آن غلات و بنشن است و اهالی به کشاورزی اشتغال دارند راه مالرو دارد. <span class=\"hlight\" dir=\"rtl\">١٨</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(180036, 'عباس آباد ده نو', '<span class=\"hlight\">عباس آباد ده نو.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ دِه ْ ن َ ]</font></b> (اِخ ) دهی است از دهستان برج اکرم بخش فهرج شهرستان بم . واقع در <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی باختر فهرج، کنار شوسه ٔ بم به زاهدان . ناحیه ای است جلگه ای و گرمسیر و مالاریائی . <span class=\"hlight\" dir=\"rtl\">٩٢</span>تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، خرما، حنا است اهالی به کشاورزی اشتغال دارند. راه شوسه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180037, 'عباس آباد زواره', '<span class=\"hlight\">عباس آباد زواره .</span> <font color=\"DarkGreen\"><b>[ع َب ْ با دِ زَ رَ ]</font></b> (اِخ ) ده کوچکی است از دهستان گرمسیر شهرستان اردستان . واقع در <span class=\"hlight\" dir=\"rtl\">١٩</span>هزارگزی شمال خاوری اردستان و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی راه فرعی زواره به اردستان . <span class=\"hlight\" dir=\"rtl\">٤٢</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(180038, 'عباس آباد زیگان', '<span class=\"hlight\">عباس آباد زیگان .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ]</font></b> (اِخ ) دهی است از دهستان زیگان بخش فهرج شهرستان بم . واقع در <span class=\"hlight\" dir=\"rtl\">٣٥</span>هزارگزی جنوب خاوری فهرج و سه هزارگزی شمال راه فرعی بم به خاش . ناحیه ای است جلگه ای و گرمسیر. <span class=\"hlight\" dir=\"rtl\">٢٢١</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، خرما و حنا است . اهالی به کشاورزی اشتغال دارند. راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180039, 'عباس آباد سناورد', '<span class=\"hlight\">عباس آباد سناورد.</span> <font color=\"DarkGreen\"><b>[ ع َ ب بادِ وُ ]</font></b> (اِخ ) دهی است جزء دهستان شراء بالا بخش کمیجان شهرستان اراک . واقع در <span class=\"hlight\" dir=\"rtl\">٦١</span>هزارگزی جنوب کمیجان، سر راه عمومی شراء. ناحیه ای است کوهستانی و سردسیر. <span class=\"hlight\" dir=\"rtl\">٤٤٠</span> تن سکنه دارد. آب آن از رودخانه ٔ شراء تأمین میشود. محصولات آن غلات، بنشن و انگور است و اهالی به کشاورزی اشتغال دارند. راه مالرو دارد و از پل دوآب اتومبیل میتوان برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(180040, 'عباس آباد سیف', '<span class=\"hlight\">عباس آباد سیف .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ س َ ]</font></b> (اِخ ) ده کوچکی است از بخش خرقان شهرستان ساوه . <span class=\"hlight\" dir=\"rtl\">٢٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180041, 'عباس آباد سیف الدینی', '<span class=\"hlight\">عباس آباد سیف الدینی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ س َ فُدْ دی ]</font></b> (اِخ ) دهی است از دهستان عزیزآباد بخش فهرج شهرستان بم . واقع در <span class=\"hlight\" dir=\"rtl\">١٣</span>هزارگزی جنوب باختری فهرج و یکهزارگزی راه فرعی به برج اکرم . ناحیه ای است جلگه و گرمسیر و مالاریایی . <span class=\"hlight\" dir=\"rtl\">٢٥٣</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، پنبه و خرما است . اهالی به کشاورزی اشتغال دارند. راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180042, 'عباس آباد شجاع لشکر', '<span class=\"hlight\">عباس آباد شجاع لشکر.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ش ُ ل َ ک َ ]</font></b> (اِخ ) دهی است از دهستان دستگران بخش طبس شهرستان فردوس . واقع در <span class=\"hlight\" dir=\"rtl\">١٢٣</span>هزارگزی شمال طبس . ناحیه ای است جلگه ای گرمسیر. <span class=\"hlight\" dir=\"rtl\">٣٤</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، پنبه و گاورس است اهالی به کشاورزی اشتغال دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180043, 'عباس آباد ضرغام', '<span class=\"hlight\">عباس آباد ضرغام .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ض َ ]</font></b> (اِخ ) دهی است از دهستان بهنام سوخته بخش ورامین شهرستان تهران . واقع در <span class=\"hlight\" dir=\"rtl\">٣١٠</span>هزارگزی شمال خاور ورامین کنار راه خراسان . ناحیه ای است جلگه ای . آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه دارد. آب آن از رودخانه ٔ جاجرود تأمین میشود. محصولات آن غلات، صیفی و چغندرقند است . شغل اهالی زراعت است . راه ماشین رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180044, 'عباس آباد ضرغامی', '<span class=\"hlight\">عباس آباد ضرغامی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ض َ ]</font></b> (اِخ ) دهی است ازدهستان کنار رودخانه ٔ وفرقان بخش مرکزی شهرستان ساوه . واقع در <span class=\"hlight\" dir=\"rtl\">١٥٠٠٠</span>گزی جنوب ساوه و <span class=\"hlight\" dir=\"rtl\">٤٠٠٠</span>گزی جنوب ساوه به قم . ناحیه ای است جلگه ای . آب و هوای آن معتدل است .<span class=\"hlight\" dir=\"rtl\">٢٦٥</span> تن سکنه دارد. آب آن از رودخانه ٔ وفرقان تأمین میشود. محصولات آن چغندرقند و انار است . شغل اهالی زراعت و گله داری است . صنایع دستی آنها گلیم و جاجیم بافی است . راه مالرو دارد. این ده قشلاق چند خانوار ازایل بغدادی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180045, 'عباس آباد عرب', '<span class=\"hlight\">عباس آباد عرب .</span> <font color=\"DarkGreen\"><b>[ ع َب ْبا دِ ع َ رَ ]</font></b> (اِخ ) دهی است از دهستان نقاب بخش جغتای شهرستان سبزوار. واقع در <span class=\"hlight\" dir=\"rtl\">٤٥</span>هزارگزی خاور جغتای . ناحیه ای است جلگه ای . آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٤٤٦</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات و پنبه است . اهالی به کشاورزی اشتغال دارند. راه اتومبیل رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180046, 'عباس آباد غفور', '<span class=\"hlight\">عباس آباد غفور.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ غ َ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ خاوری شهرستان رفسنجان . واقع در <span class=\"hlight\" dir=\"rtl\">٩</span>هزارگزی شمال رفسنجان و <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی شمال شوسه ٔ رفسنجان به کرمان . ناحیه ای است جلگه ای و سردسیر. <span class=\"hlight\" dir=\"rtl\">٣٢٣</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، پسته و پنبه است . اهالی به کشاورزی اشتغال دارند راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180047, 'عباس آباد قندی', '<span class=\"hlight\">عباس آباد قندی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ق َ ]</font></b> (اِخ ) دهی است از دهستان خسروشیر بخش جغتای شهرستان سبزوار. واقع در <span class=\"hlight\" dir=\"rtl\">٢٥</span>هزارگزی شمال خاوری جغتای سر راه شوسه ٔ عمومی سبزوار. ناحیه ای است جلگه ای آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">١٧٥</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، پنبه و زیره است، اهالی به کشاورزی اشتغال دارند. راه اتومبیل رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(180048, 'عباس آباد معصومه', '<span class=\"hlight\">عباس آباد معصومه .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ م َ م ِ ]</font></b> (اِخ ) دهی است از دهستان بهنام عرب بخش ورامین شهرستان تهران . واقع در <span class=\"hlight\" dir=\"rtl\">٢٤٠٠٠</span>گزی ورامین و <span class=\"hlight\" dir=\"rtl\">٦٠٠٠</span>گزی راه حاجی آباد سالاری . جلگه ای آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">١٢٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات و صیفی است . شغل اهالی زراعت است . راه مالرو دارد. مزرعه ٔ قاسم آباد و علی آبادجزء این ده است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180049, 'عباس آباد ملک', '<span class=\"hlight\">عباس آباد ملک .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ م َ ل ِ ]</font></b> (اِخ ) دهی است ازدهستان نقاب بخش جغتای شهرستان سبزوار. واقع در <span class=\"hlight\" dir=\"rtl\">٤١</span>هزارگزی خاور جغتای سر راه شوسه ٔ عمومی جغتای . ناحیه ای است جلگه ای . آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٣١١</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، پنبه و کنجد است . اهالی به کشاورزی اشتغال دارند. راه اتومبیل رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180050, 'عباس آباد ملکان', '<span class=\"hlight\">عباس آباد ملکان .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ م َ ل ِ ]</font></b> (اِخ ) ده مخروبه ای از دهستان جندق بیابانک بخش خوربیابانک شهرستان نائین است . (از فرهنگ جغرافیائی ایران ج ص <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180051, 'عباس آباد موقوفه', '<span class=\"hlight\">عباس آباد موقوفه .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ م َ ف َ ]</font></b> (اِخ ) دهی است جزء دهستان غار بخش ری شهرستان تهران . واقع در <span class=\"hlight\" dir=\"rtl\">١٦٠٠٠</span>گزی ری و <span class=\"hlight\" dir=\"rtl\">٢٠٠٠</span>گزی جنوب راه خراسان . ناحیه ای است جلگه ای، آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">١١٢</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، صیفی و چغندرقند است . شغل اهالی زراعت است . راه ماشین رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180052, 'عباس آباد نارباغی', '<span class=\"hlight\">عباس آباد نارباغی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ]</font></b> (اِخ ) دهی است از دهستان بخش حومه ٔ شهرستان ساوه . واقع در <span class=\"hlight\" dir=\"rtl\">٢٤٠٠٠</span>گزی ساوه و <span class=\"hlight\" dir=\"rtl\">٩٠٠٠</span>گزی راه عمومی و راه آهن . ناحیه ای است جلگه ای . آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٩٥</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، انار، انجیر است . شغل اهالی زراعت است و صنایع دستی جاجیم و پلاس بافی است . راه مالرو دارد. این ده قشلاق چند خانوار از طایفه ٔ شاهسون بغدادی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180053, 'عباس آباد پایین', '<span class=\"hlight\">عباس آباد پایین .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ]</font></b> (اِخ ) دهی است از دهستان ابهررود بخش ابهر شهرستان زنجان . واقع در<span class=\"hlight\" dir=\"rtl\">٢٧</span> هزارگزی جنوب باختری ابهر و <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی راه عمومی . ناحیه ای است کوهستانی و سردسیر. <span class=\"hlight\" dir=\"rtl\">٦٤٩</span> تن سکنه دارد. آب آن از رودخانه ٔ قزلجه تأمین میشود. محصولات آن عسل و قلمستان است و اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(180054, 'عباس آباد پایین', '<span class=\"hlight\">عباس آباد پایین .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ]</font></b> (اِخ ) ده کوچکی است از دهستان بلوک شرقی بخش مرکزی شهرستان دزفول . واقع در <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی جنوب باختری دزفول و <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی جنوب باختری شوسه ٔ دزفول به شوشتر. <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180055, 'عباس آباد پیش', '<span class=\"hlight\">عباس آباد پیش .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ]</font></b> (اِخ ) ده کوچکی است از دهستان زیدآباد بخش مرکزی شهرستان سیرجان . واقع در <span class=\"hlight\" dir=\"rtl\">١٥</span>هزارگزی شمال سعیدآباد و سر راه مالرو خیرآباد به زیدآباد. <span class=\"hlight\" dir=\"rtl\">١٥</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180056, 'عباس آباد چهاردانگه', '<span class=\"hlight\">عباس آباد چهاردانگه .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ چ َ گ َ ]</font></b> (اِخ ) ده کوچکی است از بخش ری شهرستان تهران . واقع در <span class=\"hlight\" dir=\"rtl\">٩٥٠٠</span>گزی باختر ری و <span class=\"hlight\" dir=\"rtl\">٤٠٠٠</span>گزی جنوب راه تهران به رباطکریم . جلگه ای و آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180057, 'عباس آباد کرده', '<span class=\"hlight\">عباس آباد کرده .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ک َ دِ ]</font></b> (اِخ ) دهی است از بخش خرقان شهرستان ساوه . واقع در <span class=\"hlight\" dir=\"rtl\">٢٤٠٠٠</span>گزی راه قدیمی شاه عباسی . ناحیه ای است جلگه ای . <span class=\"hlight\" dir=\"rtl\">٧٥</span> تن سکنه دارد. آب و هوای آن معتدل است . آب آن از قنات کوچک تأمین میشود. شغل اهالی زراعت و گله داری است . راه مالرو دارد از ساوه و زرند ماشین میتوان برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180058, 'عباس آباد کسب', '<span class=\"hlight\">عباس آباد کسب .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ک ِ ]</font></b> (اِخ ) دهی است از دهستان آورزمان شهرستان ملایر. واقع در <span class=\"hlight\" dir=\"rtl\">٢١</span>هزارگزی شمال شهر ملایر و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی خاور راه شوسه ٔ ملایر به همدان . ناحیه ای است جلگه ای آب و هوای آن معتدل و مالاریایی است، <span class=\"hlight\" dir=\"rtl\">٢٧٤</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات است . اهالی به زراعت اشتغال دارند. صنایع دستی زنان قالی بافی است . راه اتومبیل رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180059, 'عباس آباد کنار جاده', '<span class=\"hlight\">عباس آباد کنار جاده .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ک ِ رِ دَ ]</font></b> (اِخ ) دهی است از دهستان دربقاضی بخش حومه ٔ شهرستان نیشابور. واقع در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی خاور نیشابور. ناحیه ای است جلگه ای، آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٤٠٥</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات است . اهالی به کشاورزی اشتغال دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180060, 'عباس آباد گچی', '<span class=\"hlight\">عباس آباد گچی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ گ َ ]</font></b> (اِخ ) ده کوچکی است از بخش حومه ٔ شهرستان نائین . واقع در <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی باختر نائین و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی شوسه ٔ اردستان به نائین . <span class=\"hlight\" dir=\"rtl\">٢٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(180061, 'عباس آبادآورزمان', '<span class=\"hlight\">عباس آبادآورزمان .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ وَ زَ ]</font></b> (اِخ ) دهی است از دهستان آورزمان شهرستان ملایر. واقع در <span class=\"hlight\" dir=\"rtl\">٣٦</span>هزارگزی جنوب باختری شهرستان ملایر و سه هزارگزی باختر راه اتومبیل رو آورزمان به کرتیل آباد. ناحیه ای است کوهستانی آب و هوای آن معتدل و مالاریایی است . <span class=\"hlight\" dir=\"rtl\">١٤٦</span> تن سکنه دارد. آب آن از چشمه تأمین میشود. محصولات آن غلات و انگور است . اهالی به کشاورزی اشتغال دارند صنایع دستی زنان قالیبافی است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180062, 'عباس آبادخان', '<span class=\"hlight\">عباس آبادخان .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ]</font></b>(اِخ ) دهی است از دهستان دربقاضی بخش حومه ٔ شهرستان نیشابور. واقع در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی جنوب خاوری نیشابور. ناحیه ای است جلگه ای، آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٢٠٦</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات است . اهالی به کشاورزی و مالداری اشتغال دارند راه اتومبیل رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180063, 'عباس آبادخان', '<span class=\"hlight\">عباس آبادخان .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با دِ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ باختری شهرستان رفسنجان . واقع در <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی جنوب باختری رفسنجان کنار شوسه ٔ رفسنجان به یزد. ناحیه ای است جلگه ای و سردسیر. <span class=\"hlight\" dir=\"rtl\">١٨٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، پسته و پنبه است . اهالی به کشاورزی اشتغال دارند. راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180064, 'عباس آبادی', '<span class=\"hlight\">عباس آبادی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) حاج عبدالمطلب بن محمد حسین اصفهانی . از علماء اواسط قرن سیزدهم هجری قمری و از شاگردان شیخ احمد احسائی است . او را تألیفاتی است از جمله حجیة الظنة به فارسی، و الحجة البالغة من اسرار الاعتقادات الاحمدیة. (از ریحانة الادب ) (از الذریعة).<br /></font></div>'),
(180065, 'عباس ابوتراب', '<span class=\"hlight\">عباس ابوتراب .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با اَ ت ُ ]</font></b> (اِخ ) دهی است از دهستان مرکزی بخش قاین شهرستان بیرجند. واقع در <span class=\"hlight\" dir=\"rtl\">٣٦</span> هزارگزی جنوب باختر شوسه ٔ عمومی بیرجند. ناحیه ای است واقع در دامنه . آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">١٧</span>تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات و چغندر است . اهالی به کشاورزی گذران میکنند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180066, 'عباس افندی', '<span class=\"hlight\">عباس افندی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با اَ ف َ ]</font></b> (اِخ ) معروف به عبدالبهاء پسر ارشد میرزا حسین علی نوری معروف به بهاء اﷲ. بهائیان او را غصن اعظم خوانند. عباس افندی همراه پدر از ایران به بغداد و از آنجا به عکا رفت پس از مرگ پدر ریاست بهائیان بدو محول شد و بر مخالفان خود یعنی طرفداران میرزا محمدعلی تفوق جست و از آنجا به سویس و سپس به لندن و پس از آن به پاریس رفت و مجدداً به مصر بازگشت و در اوایل سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٩١٢</span>م . از مصر به طرف آمریکای شمالی حرکت کرد و در اواخر سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٩١٢</span> به اروپا مراجعت نمود و در <span class=\"hlight\" dir=\"rtl\">١٤</span> دسامبر ازسنه ٔ مذکور به لیورپول وارد شد و از آنجا در جریان <span class=\"hlight\" dir=\"rtl\">١٩١٣</span> م . به آلمان و اطریش و مجارستان رفت و بسیاری دیگر از بلاد اروپا را سیاحت نمود و از آنجا در اواسط <span class=\"hlight\" dir=\"rtl\">١٩١٣</span> به مصر و از آنجا به حیفا برگشت و آنجا را از این تاریخ به بعد مقر نهائی خود قرار داد. وفات عباس افندی در <span class=\"hlight\" dir=\"rtl\">٢٧</span> ربیع الاول سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٣٤٠</span> هَ . ق . مطابق <span class=\"hlight\" dir=\"rtl\">٢٨</span> نوامبر <span class=\"hlight\" dir=\"rtl\">١٩٢١</span> م . در حیفا بوده است و در جبل گرمل بالای حیفا و شرف سران مدفون شد. (تلخیص از یادداشت معاصرین مرحوم قزوینی مجله ٔ یادگار سال <span class=\"hlight\" dir=\"rtl\">٥</span> شماره ٔ <span class=\"hlight\" dir=\"rtl\">٦</span> - <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(180067, 'عباس اقبال', '<span class=\"hlight\">عباس اقبال .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با س ِ اِ ]</font></b> (اِخ ) رجوع به اقبال ... شود.<br /></font></div>'),
(180068, 'عباس اول', '<span class=\"hlight\">عباس اول .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با س ِ اَوْ وَ ]</font></b> (اِخ ) (شاه ...) معروف به شاه عباس کبیر، فرزند سلطان محمد صفوی معروف به خدابنده فرزند بزرگ شاه طهماسب اول و نواده ٔ شاه اسماعیل اول، سرسلسله ٔخاندان صفوی است . مادر وی خیر النساء بیگم دختر میرعبداﷲخان والی مازندران بوده است و نسبت او به سید قوام الدین مشهور به میر می رسد. شاه عباس به سال <span class=\"hlight\" dir=\"rtl\">٩٧٨</span> هَ . ق . در شهر هرات مرکز حکومت خراسان متولد شد و در<span class=\"hlight\" dir=\"rtl\">٩٨٠</span> به سن یکسال و نیمی به میرزائی هرات رسید و شاهقلی سلطان با عنوان لله گی او در مقام امیر الامرائی خراسان ماند و از وی سرپرستی کرد و به سال <span class=\"hlight\" dir=\"rtl\">٩٩٦</span> هَ . ق . مطابق با <span class=\"hlight\" dir=\"rtl\">١٥٨٨</span> م . در سن شانزده سالگی سلطنت یافت .<br />تحصیلات : شاه عباس خواندن و نوشتن میدانست ولی معلومات فراوانی نداشته است و در مقابل از فراست و کیاست ذاتی برخوردار و دارای ذوق ادبی و هنری بود اشعاری بدو نسبت میدهند از جمله غزل زیر است :<br />محبت آمد و زد حلقه بر دل و جانم <br />درش گشودم و شد تا به حشر مهمانم <br />نه هست هستم ونه نیستم نمیدانم <br />که من کیم چه کنم کافرم مسلمانم .<br />صفات و اخلاق : وی در جوانی به شراب میل فراوانی داشت و هرگاه از کار جنگ فارغ میشد به شراب خواری و مجالس بزم و نشاط می پرداخت . او مردی دلیر و جنگجو و بی باک و پردل و زورمند و متحمل بود. در سواری و شمشیر زنی و تیراندازی مهارت و زبردستی خاصی داشت و حسن عطوفت و گذشت و قدردانی داشت و در عین حال انتقام جو و کینه توز بود. در زندگی عادی بی تکلف بود.<br />فرزندان : شاه عباس پنج پسر داشت که به ترتیب سن عبارت بودند از: محمد باقر میرزا مشهور به صفی میرزا، حسن میرزا، خدابنده میرزا، اسماعیل میرزا و امامقلی میرزا. حسن میرزا و اسماعیل میرزا در کودکی مردند و دو پسر دیگر او را به امر وی کور کردند.<br />نیروی نظامی : شاه عباس با قزلباشان که مردمان مقتدری بودند و درتمام امور لشکری و کشوری دخالت میکردند و داعیه ٔ فرمانروایی داشتند از در ستیز درآمد و آنها را از میان برد. نیروئی که شاه عباس در اختیار داشت رویهمرفته شامل شصت هزار سوار قزلباش بود که جز از رؤسای خود از هیچ کس اطاعت نمیکردند و در نتیجه شاه نمیتوانست جز به رؤسای قزلباش به دیگری فرمان دهد و در نتیجه قدرت کلی در دست آنها بود. او برای رفع این اشکال افراد و دستجات قبیله یعنی عده ٔ نفراتی که هر قبیله مسئول بود تحویل بدهد دو قسمت کرد و نیروئی که شامل ده هزار سوار نظام و دوازده هزار پیاده نظام بود و بوسیله ٔ شخص شاه اداره میشد تشکیل داد. سپس با کمک برادران شرلی صنف توپخانه بوجود آورد و پیاده نظام آماده شد و بالاخره در نظام ایران انقلابی با همراهی برادران شرلی بوقوع پیوست، و بجای نیروی اسب سوار دوران ملوک الطوائفی، ایران دارای ارتش منظمی شد که میتوانست با ارتش عثمانی در میدان جنگ مقابله کند. شاه عباس نیروی دیگری هم در مقابل قزلباش گردنکش بوجود آورد بدین ترتیب که شاه از اعضاء تمام قبائل دعوت کرد که برای اسم نویسی آزاد به نام شاهسون یا دوستان شاه فراهم آیند؛ و بدین طریق شاه از نیروی قزلباش بی نیاز و آسوده خاطر شد. او از انگلیس ها مشاق و معلم نظام خواست و کارخانه ٔ توپ ریزی تهیه کرد.<br />حقوق و امتیازات به خارجی ها: شاه عباس به تجار مسیحی که مایل به تجارت با ایران بودند حقوق و امیتازاتی داد که فوق العاده رضایت بخش بود و عوارض و رسومی را نسبت به آنها ملغی کرد و دستور داد که کسی حق تعرض به آنان را ندارد و بدین وسیله پایه ٔ اتحاد دوستی میان ایران و دول اروپائی را ریخت .<br />مقر حکومت : تا سال <span class=\"hlight\" dir=\"rtl\">١٠٠٦</span> هَ. ق . مقر حکومت و مرکز کشور قزوین بود و از سال <span class=\"hlight\" dir=\"rtl\">١٠٠٧</span> شاه عباس رسماً پایتخت خود را به اصفهان انتقال داد و قبل از آن نیز بعضی از زمستانها را در آنجا بسر میبرد.<br />جنگهای وی : او در ابتدای سلطنت از طرفی متوجه سرکوب مدعیان سلطنت و امرا بود و از طرفی در دفع ازبکان که به قسمت های مهمی از ولایات ایران از جمله خراسان و گنجه دست یافته بودند کوشید و چون در جنگ با عثمانی ها شکست خورد ناچار به امضای قراردادی شد. سپس در سال <span class=\"hlight\" dir=\"rtl\">١٠١١</span> هَ . ق . توانست ارتش عثمانی را مغلوب کند شهر تبریز را پس از <span class=\"hlight\" dir=\"rtl\">١٨</span> سال به خاک ایران بازگرداند، آنگاه به طرف ایروان حرکت کرد و آنجارا پس از شش ماه محاصره به تصرف درآورد و شیروان و قارص را نیز تصرف کرد. در همین اوان سلطان محمد سوم درگذشت و پسرش با سپاه عظیمی برای جنگ با ایران رهسپار شد ولی از قوای ایران شکست خورد و نه تنها آذربایجان و کردستان بلکه بغداد و موصل و نجف و کربلا نیز به ایران ملحق شد. از آن پس نیز در چند جنگ دیگر شکست نصیب سپاه عثمانی شد. اما در <span class=\"hlight\" dir=\"rtl\">٩٩٥</span> هَ . ق . در جنگی که نزدیکی بغداد بین دو دولت رخ داد، نیروی ایران شکست خورد و به دنبال آن شهرتبریز و ولایات غربی ایران یعنی عراق عجم، خوزستان، شکی، شماخی، تفلیس با قسمتی از لرستان به عثمانیان واگذار شد و مقرر شد که حکومت ایران لعن خلفای ثلاث را ممنوع دارد و حیدر میرزا به عنوان گروگان در اختیار آنان باشد. این معاهده در سال <span class=\"hlight\" dir=\"rtl\">٩٩٨</span> هَ . ق . بسته شد.<br />روابط با اروپائیان :شاه عباس به منظور مقابله با عثمانیان و دفع ازبکان ناچار با خارجیان روابط حسنه برقرار کرد، روابط اقتصادی و تجاری را با خارجیان تشویق کرد و با مسیحیان خوش رفتاری و حتی در اعیاد مذهبی و ملی آنها شرکت میجست اجتماعات آنان را به رسمیت شناخت در بنای کلیسا در جلفای اصفهان به آنها کمک کرد و بالاخره آنچه ممکن بود در حق عیسویان عطوفت و مهربانی کرد و این کار درآن زمان جلب توجه اروپائیان را نمود و باب اتحاد و هم بستگی را گشودند به طوری که صحبت اتحاد میان ایران و انگلیس بر ضد عثمانیها بمیان آمد. با آلمان و اسپانیا نیز روابط سیاسی برقرار کرد و نمایندگانی بدان کشورها فرستاد. با کشور هندوستان که از زمانهای قدیم نیز روابطی وجود داشت تجدید روابط کرد. در سال <span class=\"hlight\" dir=\"rtl\">٩٩٧</span> هَ . ق . هیأتی را بریاست بوداق بیک روانه ٔ مسکو کرد که حامل پیامی از طرف شاه به امپراطور روسیه بود. و از سال <span class=\"hlight\" dir=\"rtl\">١٠٠١</span> هَ . ق . رسماً میان ایران و روس روابط سیاسی برقرار گردید.<br />کارهای او: مهمترین آثار و کارهای او از این قرار است : ساختمان مسجد شیخ لطف اﷲ، ساختمان عمارت چهل ستون، ساختمان و یا تکمیل بنای عالی قاپو، احداث خیابان چهارباغ که به سبک خیابانهای اروپا دو طرفه ساخته شده است، پل بزرگ <span class=\"hlight\" dir=\"rtl\">٣٣</span> پل مشهور به پل چهارباغ، ساختمان عمارت هشت بهشت، آباد کردن دهکده ٔ نجف آباد و وقف آن به نجف اشرف، ایجاد و ساختن کاروانسراهای متعدد در طرق و راه ها، سعی و کوشش در راه بهبود وضع طرق ارتباطی، تعمیر مرقد و گبند مطهر حضرت رضا (ع )، جاری ساختن آب فرات تا مسجد کوفه، تعمیر مرقد مطهر حضرت امیر (ع )، مرتب کردن وضع نظام ایران، کوچ دادن ارامنه از جلفای ارس به جلفای جدید نزدیک اصفهان، تأسیس کارخانه ٔ توپ ریزی، ترویج هنر و صنایع ظریفه و تشویق هنرمندان، منظم کردن وضع اداری کشور و تقسیم مشاغل .<br />از جمله اتفاقات زمان وی کناره گیری سه روزه ٔ او از سلطنت است . موضوع چنین بود که او به اخترشناسی و طالع بینی ایمان کامل داشت و در توجیه حوادث و اتفاقات از منجم باشی خود ملا جلال استمداد می جست . در سال <span class=\"hlight\" dir=\"rtl\">١٠٠٢</span> هَ . ق . ستاره ٔ دنباله داری در آسمان پدیدار شد منجمان گفتند که این حادثه دلالت بر مرگ شاه دارد و در مقام چاره اندیشی بنا شد شاه برای مدت سه روز از سلطنت استعفا و دیگری را بجای خود برگزیند. وی تصمیم گرفت که یوسفی ترکش دوز درویش معروف را که مشغول فتنه انگیزی علیه شاه بود و مریدان زیادی داشت بدین سمت برگزیند، باشد که با یک تیر دو نشان زده باشد از این جهت درویش بیچاره را روز پنجشنبه هفتم ذیقعده تا دهم به پادشاهی انتخاب و روز یکشنبه دهم او را بدار زدند. شاه عباس در شب پنجشنبه بیست و چهارم جمادی الاولی سال <span class=\"hlight\" dir=\"rtl\">١٠٣٨</span> هَ . ق . در مازندران درگذشت جنازه اش را بر دوش تا کاشان آوردند و در پشت مدفن امام زاده حبیب بن موسی به امانت سپردند و در همان سال صفی میرزا ولیعهد بجای پدر به تخت سلطنت نشست . (از روضة الصفا ج <span class=\"hlight\" dir=\"rtl\">٦</span>). و رجوع شود به : زندگانی شاه عباس نصراﷲ فلسفی، احسن التواریخ، اکبرنامه، تاریخ ادبیات ایران ادوارد برون، تاریخ الفی و تاریخ سایکس .<br /></font></div>'),
(180069, 'عباس اول', '<span class=\"hlight\">عباس اول .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با س ِ اَوْ وَ ]</font></b> (اِخ ) (پاشا) عباس بن طولون بن محمدعلی پاشاالکبیر. سومین خدیو مصر است و به سال <span class=\"hlight\" dir=\"rtl\">١٢٢٨</span> هَ . ق . در قاهره متولد و بعد از مرگ عموی خود ابراهیم پاشا ولایت مصر یافت . وی با سلطه ٔ اروپائیان بر سرزمین عربستان سخت مخالفت ورزید و در جنگ ترک با روس به آنها کمک کرد. او اولین کسی است که مدارس نظام و دانشگاه جنگ در عباسیه ٔ قاهره تأسیس کرد. وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٧٠</span> هَ . ق . درگذشت . (الاعلام زرکلی ).<br /></font></div>'),
(180070, 'عباس بلاغی', '<span class=\"hlight\">عباس بلاغی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ب ُ ]</font></b> (اِخ ) دهی است از دهستان چهاردولی بخش مرکزی شهرستان مراغه . واقع در <span class=\"hlight\" dir=\"rtl\">٨١٠٠٠</span> گزی جنوب خاور مراغه و یکهزارگزی خاور شوسه ٔ شاهین دژ به میاندوآب . ناحیه ای است جلگه، آب و هوای آن معتدل و مالاریایی است . <span class=\"hlight\" dir=\"rtl\">٢٩٦</span> تن سکنه دارد. آب آن از چشمه سار تأمین میشود. محصولات آن غلات، بادام، حبوبات، کرچک و چغندر است . اهالی به کشاورزی و جاجیم بافی اشتغال دارند. راه شوسه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(180071, 'عباس بلاغی', '<span class=\"hlight\">عباس بلاغی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ب ُ ]</font></b> (اِخ ) دهی است از دهستان به به جیک بخش سیه چشمه ٔ شهرستان ماکو واقع در <span class=\"hlight\" dir=\"rtl\">٤٢</span> هزارگزی جنوب خاوری سیه چشمه و سه هزارگزی راه ارابه رو ایشکه به سوبه کران پایین . ناحیه ای است جلگه وآب و هوای آن معتدل و سالم است و <span class=\"hlight\" dir=\"rtl\">٤٩</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات است و اهالی به کشاورزی و گله داری و جاجیم بافی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(180072, 'عباس جوب', '<span class=\"hlight\">عباس جوب .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان ییلاق بخش قروه ٔ شهرستان سنندج . واقع در <span class=\"hlight\" dir=\"rtl\">٥٥</span> هزارگزی خاور سنندج و هشت هزارگزی خاور دهکلان و چهارهزارگزی شمال شوسه ٔ قروه . ناحیه ای است جلگه و سردسیر. <span class=\"hlight\" dir=\"rtl\">١٧٥</span> تن سکنه دارد.آب آن از چشمه و رودخانه ٔ طهماسب قلی تأمین میشود. محصولات آن غلات و لبنیات است . اهالی به کشاورزی و گله داری اشتغال دارند. راه مالرو دارد و در تابستان اتومبیل میتوان برد. از صنایع دستی زنان : قالیچه، جاجیم و گلیم بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180073, 'عباس خان', '<span class=\"hlight\">عباس خان .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان قره باشلو بخش چاپشلو شهرستان مشهد. واقع در <span class=\"hlight\" dir=\"rtl\">٦٩</span>هزارگزی شمال باختری مشهد و کنار کشف رود. ناحیه ای است واقع در جلگه و آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٢٨</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، چغندر و کنجد است . اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180074, 'عباس خان', '<span class=\"hlight\">عباس خان .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از بخش شیب آب شهرستان زابل . واقع در <span class=\"hlight\" dir=\"rtl\">٢٢</span>هزارگزی شمال باختری سکوهه و <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی باختر شوسه ٔ زاهدان به زابل . ناحیه ای است جلگه ای با آب و هوای گرم و معتدل و <span class=\"hlight\" dir=\"rtl\">٣٦٠</span> تن سکنه . آب آن از رودخانه ٔ هیرمند تأمین میشود. محصولات آن غلات، لبنیات است . اهالی به کشاورزی، گله داری اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180075, 'عباس دوس', '<span class=\"hlight\">عباس دوس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ باس ِ دَ ]</font></b> (اِخ ) نام مردی که به لطائف الحیل مشهور بودچنانکه در جامع الحکایات قصه ٔ او مسطور است و دوس قبیله ای است از یمن و ابن عباس از همان قبیله بود. درلطائف الحیل است که عباس دَوس ْ نام گدائی که بسیار مکار و مضحک بود. (غیاث اللغات ). رجوع به دوس شود:<br />گفت خدمت آنکه بهر ذل نفس <br />خویش را سازی تو چون عباس دیس .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(180076, 'عباس دوم', '<span class=\"hlight\">عباس دوم .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با س ِ دُوْ وُ ]</font></b> (اِخ ) (شاه ...) فرزند شاه صفی صفوی بن صفی میرزابن شاه عباس اول وی در <span class=\"hlight\" dir=\"rtl\">١٨</span> جمادی الثانیه ٔ سال <span class=\"hlight\" dir=\"rtl\">١٠٤٣</span> هَ . ق . متولدشد و پس از مرگ پدر خود شاه صفی در سال <span class=\"hlight\" dir=\"rtl\">١٠٥٢</span> شب جمعه شانزدهم صفر به سن نه سالگی در کاشان به تخت سلطنت نشست . او سفری به مکه و مشهد کرد. در دوران کودکی وی وزیر اعظم میرزاتقی عمادالدوله زمام کار را بدست داشت و چون شاه بسن رشد رسید خود به کارها رسیدگی میکرد. در عهد وی قندهار که صفی میرزا از دست داده بود فتح شد و کوشش اورنگ زیب برای استرداد آن بجائی نرسید.او مانند شاه عباس اول نسبت به کلیه ٔ مذاهب به دیده ٔ احترام مینگریست و از علما و دانشمندان تفقد میکرددر عهد وی امنیت خاصی بر ایران حکمفرما بود. وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٧٨</span> هَ . ق . در قصر خسروآباد دامغان پس از بیست وپنج سال سلطنت درگذشت . رجوع شود به تاریخ ایران فروغی و روضة الصفا ج <span class=\"hlight\" dir=\"rtl\">٦</span> و تاریخ ایران بعد از اسلام و تاریخ ایران عباس پرویز و عباسنامه چ ابراهیم دهگان .<br /></font></div>'),
(180077, 'عباس رقه', '<span class=\"hlight\">عباس رقه .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با رَ ق َ ]</font></b> (اِخ ) ده کوچکی است از دهستان گل تپه فیض اﷲ بیکی شهرستان سقز. واقع در <span class=\"hlight\" dir=\"rtl\">٥٨</span> هزارگزی شمال خاور سقز و سه هزارگزی جنوب رودخانه ٔ سقز. <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180078, 'عباس سوم', '<span class=\"hlight\">عباس سوم .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با س ِ س ِوْ وُ ]</font></b> (اِخ ) فرزند شاه طهماسب، بعد از عزل طهماسب در سال <span class=\"hlight\" dir=\"rtl\">١١٤٥</span> هَ . ق . در سن <span class=\"hlight\" dir=\"rtl\">٨</span> ماهگی از طرف نادرشاه اسماً بجای پدر بر تخت سلطنت نشست . و نادرشاه نایب السلطنه گردید و این عنوان ظاهری (سلطنت عباس سوم ) تا سال <span class=\"hlight\" dir=\"rtl\">١١٤٨</span> که تاجگذاری نادر است باقی بود. شاه عباس به سن چهارسالگی درگذشت . (از فرهنگ امیر کبیر و قاموس الاعلام ترکی ).<br /></font></div>'),
(180079, 'عباس علیلو', '<span class=\"hlight\">عباس علیلو.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ع َ ]</font></b> (اِخ ) دهی است از دهستان انگوت بخش گرمی شهرستان اردبیل . واقع در <span class=\"hlight\" dir=\"rtl\">٢٤</span>هزارگزی باختر تازه کند انگوت و <span class=\"hlight\" dir=\"rtl\">٢٧</span>هزارگزی راه شوسه ٔ گرمی، اردبیل . ناحیه ای است واقع درجلگه هوای آن معتدل و گرمسیر است . <span class=\"hlight\" dir=\"rtl\">١٤٨</span> تن سکنه دارد. آب آن از چشمه تأمین میشود. و محصولات آن غلات و حبوبات است . اهالی به کشاورزی و گله داری اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(180080, 'عباس غنوی', '<span class=\"hlight\">عباس غنوی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با غ َ ن َ ]</font></b> (اِخ ) عباس بن عمرو الغنوی . از امرای عباسی است که ولایت فارس یافت و به سال <span class=\"hlight\" dir=\"rtl\">٢٨٧</span> هَ . ق . المعتضد او را عزل گرداند و یمامه و بحرین را به اقطاع بدو داد. وی به امر المعتضد به جنگ قرامطه رفت و بدست آنها گرفتار شد سپس آزاد گردید و به بغداد رفته و مورد انعام و اکرام المعتضد واقع شد.وی به سال <span class=\"hlight\" dir=\"rtl\">٣٠٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180081, 'عباس قلعه', '<span class=\"hlight\">عباس قلعه .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ق َ ع َ ]</font></b> (اِخ ) دهی است از دهستان قره باشلو بخش چاپشلو شهرستان دره گز. واقع در هشت هزارگزی شمال باختری قره باشلو و <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی باختری راه شوسه ٔ عمومی قوچان به دره گز. ناحیه ای است واقع در جلگه . آب و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٢٩٠</span>تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات و بنشن است و اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180082, 'عباس هزارآباد', '<span class=\"hlight\">عباس هزارآباد.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با هََ ]</font></b> (اِخ ) دهی است از دهستان مرکزی بخش صفی آباد شهرستان سبزوار. واقع در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی شمال خاوری صفی آباد و <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی خاور اتومبیل رو راه صفی آباد به بام . ناحیه ای است کوهستانی . هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٢٥٤</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، زیره و بنشن است . اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180083, 'عباس کتی', '<span class=\"hlight\">عباس کتی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ک ُ ]</font></b> (اِخ ) مزرعه ٔ کوچکی است از دهستان پائین خیابان بخش مرکزی شهرستان آمل نزدیک به آبادی انجپل . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(180084, 'عباس کلا', '<span class=\"hlight\">عباس کلا.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ک َ ]</font></b> (اِخ ) دهی است ازدهستان قشلاق کلارستاق بخش چالوس شهرستان نوشهر. واقعدر <span class=\"hlight\" dir=\"rtl\">١٥٠٠</span>گزی شمال باختر چالوس و یکهزارگزی جنوب راه شوسه ٔ چالوس به شهسوار. ناحیه ای است واقع در دشت، هوای آن معتدل و مرطوب است . <span class=\"hlight\" dir=\"rtl\">٨٠</span> تن سکنه دارد. آب آن ازرودخانه ٔ مرداب رود تأمین میشود. محصولات آن برنج، لبنیات و مرکبات است و اهالی به کشاورزی اشتغال دارند. راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(180085, 'عباس کندی', '<span class=\"hlight\">عباس کندی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْبا ک َ ]</font></b> (اِخ ) دهی است از دهستان چالدران بخش سیه چشمه ٔ شهرستان ماکو واقع در <span class=\"hlight\" dir=\"rtl\">٥٥٠٠</span> گزی جنوب خاروی سیه چشمه و یکهزاروپانصد گزی جنوب شوسه ٔ سیه چشمه به قره ضیاءالدین . ناحیه ای است کوهستانی . هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">١٥٥</span> تن سکنه دارد. آب آن از چشمه تأمین میشود. محصول آن غلات است . اهالی به کشاورزی و گله داری و جاجیم بافی اشتغال دارند. راه ارابه رو دارد. از سیه چشمه میتوان اتومبیل برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(180086, 'عباس کندی', '<span class=\"hlight\">عباس کندی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ک َ ]</font></b> (اِخ ) دهی است از دهستان به به جیک بخش سیه چشمه ٔ شهرستان ماکو. واقع در <span class=\"hlight\" dir=\"rtl\">٢٣٥٠٠</span> گزی خاور سیه چشمه و <span class=\"hlight\" dir=\"rtl\">٧٥٠</span>گزی شمال شوسه ٔ سیه چشمه به قره ضیاءالدین . ناحیه ای است واقع در جلگه . هوای آن معتدل و سالم است . <span class=\"hlight\" dir=\"rtl\">٩٤</span> تن سکنه دارد.آب آن ازچشمه تأمین میشود. محصول آن غلات است . اهالی به کشاورزی و گله داری و جاجیم بافی اشتغال دارند. راه ارابه رو دارد. از راه شوسه ٔ سیه چشمه به قره ضیاءالدین میتوان اتومبیل برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(180087, 'عباس کهریزی', '<span class=\"hlight\">عباس کهریزی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ک َ ]</font></b> (اِخ ) دهی است از دهستان اوشق بخش مرکزی شهرستان خیاو. واقع در <span class=\"hlight\" dir=\"rtl\">٤٥</span>هزارگزی خاوری خیاو و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی راه شوسه ٔ گرمی و اردبیل . ناحیه ای است کوهستانی هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">١٠</span> تن سکنه دارد. آب آن از چشمه تأمین میشود.محصولات آن غلات است . اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(180088, 'عباس کور', '<span class=\"hlight\">عباس کور.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از بخش شیب آب شهرستان زابل . واقع در <span class=\"hlight\" dir=\"rtl\">١٩</span>هزارگزی شمال باختری سر کوهه و <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی شوسه ٔ زاهدان به زابل . ناحیه ای است واقع در جلگه، هوای آن گرم و معتدل است و <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه دارد. آب آن از رودخانه ٔ هیرمند تأمین میشود.محصولات آن غلات است . اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180089, 'عباس کوه', '<span class=\"hlight\">عباس کوه .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان ماسوله بخش مرکزی شهرستان فومن واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی باختر فومن . ناحیه ای است کوهستانی، هوای آن معتدل و مرطوب است و <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> تن سکنه دارد. آب آن از چشمه ٔ عباس کوه تأمین میشود. محصولات آن برنج، پشم، لبنیات، عسل و ابریشم است . اهالی به کشاورزی و گله داری اشتغال دارند. راه مالرو دارد. در تابستان عموماً به ییلاقات لشکرگاه وگردسایه میروند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(180090, 'عباس یالس', '<span class=\"hlight\">عباس یالس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ل ِ ]</font></b> (اِخ ) دهی است از دهستان نهرهاشم بخش مرکزی شهرستان اهواز. واقع در <span class=\"hlight\" dir=\"rtl\">٢٧</span>هزارگزی باختر اهواز و هشت هزارگزی شمال راه شوسه ٔ اهواز به هویزه - کنار کرخه کور. ناحیه ای است واقعدر دشت، هوای آن گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٩٠</span> تن سکنه دارد. و آب آن از چاه تأمین میشود. محصولاتش غلات است . و اهالی به کشاورزی و گله داری اشتغال دارند. در تابستان راه اتومبیل رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180091, 'عباسعلی کش', '<span class=\"hlight\">عباسعلی کش .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ع َ ک ُ ]</font></b> (اِخ ) دهی است از دهستان شهرخواست . بخش مرکزی شهرستان ساری . واقع در <span class=\"hlight\" dir=\"rtl\">٣٢</span> هزارگزی شمال باختری ساری کناردریا. واقع در دشت، هوای آن معتدل و مرطوب و مالاریایی است . <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن سکنه دارد. آب آن از رودخانه ٔ تجن تأمین میشود. محصولاتش برنج، غلات، کنف و پنبه است . اهالی به کشاورزی و گله داری و صید مرغابی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(180092, 'عباسعلی کندی', '<span class=\"hlight\">عباسعلی کندی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ع َ ک َ ]</font></b> (اِخ ) دهی است از دهستان خروسلو بخش گرمی شهرستان اردبیل . واقع در <span class=\"hlight\" dir=\"rtl\">٣٦</span> هزارگزی جنوب باختری گرمی و <span class=\"hlight\" dir=\"rtl\">٢٠</span> هزارگزی راه شوسه ٔ گرمی به اردبیل . ناحیه ای است واقع در جلگه . آب و هوای آن معتدل و گرمسیراست . <span class=\"hlight\" dir=\"rtl\">١١</span> تن سکنه دارد. آب آن از چشمه تأمین میشود.محصولاتش غلات است . و اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(180093, 'عباسقلی خان', '<span class=\"hlight\">عباسقلی خان .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ق ُ ]</font></b> (اِخ ) تیره ای از ایل بیرانوند است . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٦٧</span>).<br /></font></div>'),
(180094, 'عباسلو', '<span class=\"hlight\">عباسلو.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) طائفه ای از ایل بچاقچی کرمان . (از جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">١٩٥</span>).<br /></font></div>'),
(180095, 'عباسلو', '<span class=\"hlight\">عباسلو.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان قشلاقات افشاریه ٔ بخش قیدار شهرستان زنجان . واقع در <span class=\"hlight\" dir=\"rtl\">٣٤</span>هزارگزی باختر قیدار و <span class=\"hlight\" dir=\"rtl\">٢٣</span>هزارگزی راه عمومی . ناحیه ای است کوهستانی و سردسیر و <span class=\"hlight\" dir=\"rtl\">٨٣</span> تن سکنه دارد. آب آن از رودخانه ٔ محلی تأمین میشود. محصول آن غلات است . اهالی به کشاورزی اشتغال دارند. راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(180096, 'عباسه', '<span class=\"hlight\">عباسه .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با س َ ]</font></b> (اِخ ) دهی است از دهستان برج اکرم بخش فهرج شهرستان بم . واقع در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی جنوب باختری فهرج و یکهزارگزی راه فرعی بم به برج اکرم . ناحیه ای است واقع در جلگه . هوای آن گرمسیر است . <span class=\"hlight\" dir=\"rtl\">١٠٨</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات و خرماست . و اهالی به کشاورزی اشتغال دارند. راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180097, 'عباسه', '<span class=\"hlight\">عباسه .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با س َ ]</font></b> (اِخ ) شهر کوچکی است و اولین اقامتگاه بریدان بود که از شام بمصر میرفتند. آن را درختان بلند خرما بوده . و در زمان ملک عادل بن ایوب شد. وی آن مکان را محل تفریح خود قرار داد. نزدیک آن مصید و شکارگاه زیادی است زیرا در پانزده فرسنگی قاهره واقع است . (از معجم البلدان ).<br /></font></div>'),
(180098, 'عباسوند', '<span class=\"hlight\">عباسوند.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ باس ْ وَ ]</font></b> (اِخ ) نام بلوکی است از بخش سنجابی شهرستان کرمانشاهان . این بلوک شامل <span class=\"hlight\" dir=\"rtl\">١٢</span> آبادی کوچک است که در ارتفاعات جنوب غربی سنجابی واقع شده است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180099, 'عباسویه', '<span class=\"hlight\">عباسویه .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ی َ <span class=\"hlight\" dir=\"rtl\">/</span> س َ وَی ْه ْ ]</font></b> (اِخ ) عباس بن یزید بحرانی بصری، مکنی به ابوالفضل . قاضی و از حفاظ حدیث بود و او را تألیفاتی است در حدیث . مدتی قضاوت همدان یافت و در همدان و بغداد و اصفهان حدیث میکرد. به سال <span class=\"hlight\" dir=\"rtl\">٢٥٨</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180100, 'عباسک', '<span class=\"hlight\">عباسک .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با س َ ]</font></b> (اِخ )دهی است از دهستان رودبار بخش معلم کلایه ٔ شهرستان قزوین . واقع در <span class=\"hlight\" dir=\"rtl\">٢٤٠٠٠</span>گزی شمال باختری معلم کلایه و <span class=\"hlight\" dir=\"rtl\">٦٠٠٠٠</span>گزی راه عمومی . کوهستانی و سردسیر است . <span class=\"hlight\" dir=\"rtl\">١٤٨</span> تن سکنه دارد. آب آن از چشمه سار تأمین میشود و محصول آن غلات، گردو و لوبیا است . شغل اهالی زراعت و گله داری است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180101, 'عباسکلا', '<span class=\"hlight\">عباسکلا.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ک َ ]</font></b> (اِخ )دهی است از دهستان ناتل رستاق بخش نور شهرستان آمل .واقع در <span class=\"hlight\" dir=\"rtl\">٩</span>هزارگزی جنوب خاوری سولده . ناحیه ای است واقع در دشت . هوای آن معتدل و مرطوب است و <span class=\"hlight\" dir=\"rtl\">١٨٠</span> تن سکنه دارد. آب آن از لاویج رود تأمین میشود. محصولات آن برنج مختصر و غلات است . اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(180102, 'عباسی', '<span class=\"hlight\">عباسی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) تیره ای از ایل بویراحمدی کوه کیلویه ٔ فارس . (از جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٨٨</span>).<br /></font></div>'),
(180103, 'عباسی', '<span class=\"hlight\">عباسی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) (<span class=\"hlight\" dir=\"rtl\">٩٩٦</span> - <span class=\"hlight\" dir=\"rtl\">١٠٣٨</span> هَ . ق .) علیرضا. از مشاهیر خطاطان و خوش نویسان رسمی دربار شاه عباس کبیرو از نقاشان و هنرمندان عصر خود بود. آثار هنری او گران بها و در موزه های بزرگ اروپا یافت میشود. وی در انواع خط ثلث و نسخ و نستعلیق وقوف کامل داشت . و در نقاشی و طراحی و تذهیب کاری کم نظیر بود. وی اهل تبریزبود و در زمان شاه عباس اول به اصفهان رفت و مورد عنایات و توجه شاه عباس واقع گردید و نگاشتن بعضی از کتبیه های مساجد و عمارات بدو محول شد. و به نقاشی و تذهیب کاری کتابخانه ٔ همایونی پرداخت . کتبیه های دربهای مسجد شاه و مسجد شیخ لطف اﷲ و مسجد مقصود بیک به خطاوست . و اکنون غیر از کتبیه های معدود چیزی از او باقی نمانده است . وی شعر نیز میگفت و از اشعار اوست :<br />من خانه ٔ دل خراب کردم ز غمت <br />تو خانه نشین شدی و من خانه خراب .<br />(از ریحانة الادب و پیدایش خط و خطاطان ص <span class=\"hlight\" dir=\"rtl\">١٨٠</span>).<br /></font></div>'),
(180104, 'عباسی', '<span class=\"hlight\">عباسی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) نام یکی از دهستان های چهارگانه بخش بستان آباد شهرستان تبریز است، این دهستان در جنوب خاوری بخش واقع و دارای آب و هوای نسبتاً سرد و سالم است . راه شوسه ٔ تهران و تبریز از این دهستان عبور میکند. آب آن از قنوات و رودخانه های کوچک محلی باسم رود شهری تأمین میشود. مرکز دهستان قره چمن (سیاه چمن ) است که <span class=\"hlight\" dir=\"rtl\">١٢٩٨</span> تن سکنه دارد و از <span class=\"hlight\" dir=\"rtl\">٤٤</span> آبادی بزرگ و کوچک تشکیل شده . و جمعیت قراء از <span class=\"hlight\" dir=\"rtl\">١٧٤٩</span> تن تشکیل یافته . و مهمترین دهات آن تکمه داش شنگول آباد، چونخوران بالا، قپچاق، قرانقیه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(180105, 'عباسی', '<span class=\"hlight\">عباسی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ )عبدالرحیم بن عبدالرحمان مصری قاهری اسلامبولی عبادی عباسی شافعی . از بزرگان علمای مصر است . وی در تفسیر و حدیث و ادب و تاریخ و اشعار عرب وحید عصر خود بود.از تألیفات اوست : شرح خزرجیه در علم عروض و شرح صحیح بخاری و شرح مقامات حریری و کتابهای دیگر. و به سال <span class=\"hlight\" dir=\"rtl\">٩٦٣</span> هَ . ق . در اسلامبول درگذشت . (ریحانة الادب ).<br /></font></div>'),
(180106, 'عباسی', '<span class=\"hlight\">عباسی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) در رجال لقب ابراهیم بن هاشم و هشام بن ابراهیم راشدی و جمعی دیگر است و نسبت بعضی ایشان به جد و بعضی دیگر به مکان و محل است . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(180107, 'عباسی', '<span class=\"hlight\">عباسی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) بنی عباس یا آل عباس . رجوع به آل عباس شود.<br /></font></div>'),
(180108, 'عباسی', '<span class=\"hlight\">عباسی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِ) واحد پول معادل چهارشاهی . دوصددینار. دوصنار. رجوع به صنار و صددینار شود.<br /></font></div>'),
(180109, 'عباسی', '<span class=\"hlight\">عباسی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (ص نسبی ) منسوب به عباس . رجوع به عباس شود. <BR><font color=\"Blue\">◄</font> سرخ به کبودی مایل . <BR><font color=\"Blue\">◄</font> کنایت از رنگ سیاه است چرا که خلفای عباسی لباس سیاه رامقبول خود ساخته بودند. (غیاث اللغات ) (آنندراج ).<br /></font></div>'),
(180110, 'عباسی', '<span class=\"hlight\">عباسی .</span> <font color=\"DarkGreen\"><b>[ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان بارمعدن بخش سرولایت شهرستان نیشابور. واقع در <span class=\"hlight\" dir=\"rtl\">٤٨</span>هزارگزی جنوب باختری چکنه بالا. ناحیه ای است کوهستانی و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٢</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصول آن غلات است . اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180111, 'عباسی', '<span class=\"hlight\">عباسی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان زلقی بخش الیگودرز شهرستان بروجرد واقع در <span class=\"hlight\" dir=\"rtl\">٦٨</span>هزارگزی جنوب الیگودرز و کنار راه مالرو توزر به گوشه . ناحیه ای است کوهستانی و سردسیر و <span class=\"hlight\" dir=\"rtl\">٢٨٠</span> تن سکنه دارد. آب آن از قنات و چشمه تأمین میشود. محصولات آن غلات، لبنیات، چغندر و پنبه است . اهالی به کشاورزی و گله داری اشتغال دارند. صنایع دستی زنان قالیچه بافی است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180112, 'عباسی', '<span class=\"hlight\">عباسی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) دهی است از دهستان حیات داود بخش گناوه ٔ شهرستان بوشهر. واقع در <span class=\"hlight\" dir=\"rtl\">١٦</span>هزارگزی شمال خاور گناوه و سه هزارگزی شوسه ٔ گناوه به گچساران . ناحیه ای است واقع در جلگه . هوای آن گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٣٤٠</span>تن سکنه دارد. آب آن از چاه تأمین میشود. محصولات آن غلات دیمی و خرماست . اهالی به کشاورزی اشتغال دارند. راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(180113, 'عباسیة', '<span class=\"hlight\">عباسیة.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با سی ی َ ]</font></b> (اِخ ) شهری است که ابراهیم بن اغلب امیر افریقا نزدیک قیروان بنا کردو آن را به بنی عباس نسبت داد. (از معجم البلدان ).<br /></font></div>'),
(180114, 'عباسیة', '<span class=\"hlight\">عباسیة.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با سی ی َ ]</font></b> (اِخ ) دهی است به کوره ٔ حَرجة از صعید. (از معجم البلدان ).<br /></font></div>'),
(180115, 'عباسیة', '<span class=\"hlight\">عباسیة.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با سی ی َ ]</font></b> (اِخ ) دهی است به نهر الملک . (منتهی الارب ).<br /></font></div>'),
(180116, 'عباسیة', '<span class=\"hlight\">عباسیة.</span> <font color=\"DarkGreen\"><b>[ ع َب ْبا سی ی َ ]</font></b> (اِخ ) شهری است به مصر. (منتهی الارب ).<br /></font></div>'),
(180117, 'عباسیة', '<span class=\"hlight\">عباسیة.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با سی ی َ ]</font></b> (اِخ ) دهی است از دهستان برکال بخش خلیل آباد شهرستان کاشمر. واقع در <span class=\"hlight\" dir=\"rtl\">٣٢</span>هزارگزی جنوب خلیل آباد سر راه شوسه ٔ عمومی بردسکن این ده در جلگه واقع و هوای آن معتدل و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١٣٩</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، پنبه و زیره ٔ سبز است . اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180118, 'عباسیة', '<span class=\"hlight\">عباسیة.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با سی ی َ ]</font></b> (ص نسبی ) نسبت است به مردی که نام او عباس است و اغلب عباس بن عبدالمطلب را خواهند. (از معجم البلدان ).<br /></font></div>'),
(180119, 'عباسیة', '<span class=\"hlight\">عباسیة.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با سی ی َ ]</font></b> (اِخ ) کوهی است از رمل غربی خُزیمه به راه مکه تا بطن اغّر. ابوعبید سَکونی گوید بین سمیرا و حاجر الحسینیه است . (معجم البلدان ).<br /></font></div>'),
(180120, 'عباسیة', '<span class=\"hlight\">عباسیة.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با سی ی َ ]</font></b> (اِخ ) محله ای است در بغداد که گمان میرود اکنون خراب شده باشد و مابین دوراه و جلو قصر منصور و نزدیک محله ای که الآن معروف به باب البصره است واقع شده و آن منسوب است به عباس بن محمدبن علی بن عبداﷲبن العباس . (از معجم البلدان ).<br /></font></div>'),
(180121, 'عباسیه', '<span class=\"hlight\">عباسیه .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با ی ی َ ]</font></b> (اِخ ) دهی است از دهستان حسین آباد بخش شوش شهرستان دزفول واقع در <span class=\"hlight\" dir=\"rtl\">٦</span>هزارگزی خاور خط آهن تهران به اهوازو <span class=\"hlight\" dir=\"rtl\">٥</span>هزارگزی خاور شوسه ٔ اهواز به دزفول . ناحیه ای است واقع در دشت گرمسیر و مالاریایی است . <span class=\"hlight\" dir=\"rtl\">٥٥٠</span> تن سکنه دارد. آب آن از رودخانه ٔ کرخه تأمین میشود. محصولات آن غلات، برنج و کنجد است . اهالی به کشاورزی اشتغال دارند. راه آن در تابستان اتومبیل رو میباشد. ساکنین از طایفه ٔ لر هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180122, 'عباسیه', '<span class=\"hlight\">عباسیه .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با سی ی َ ]</font></b> (اِخ ) رجوع به نعمیه شود. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180123, 'عباسیه', '<span class=\"hlight\">عباسیه .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ با سی ی َ ]</font></b> (اِخ ) دهی است از دهستان میان آب (بلوک عنا) بخش مرکزی شهرستان اهواز. واقع در <span class=\"hlight\" dir=\"rtl\">٢٨</span>هزارگزی شمال خاوری اهواز و <span class=\"hlight\" dir=\"rtl\">١٧</span>هزارگزی خاور راه آهن (کنار کارون ). ناحیه ای است واقع در دشت . گرمسیر. <span class=\"hlight\" dir=\"rtl\">١٧٥</span> تن سکنه دارد. آب آن از رود کارون تأمین میشود. محصولات آن غلات است . اهالی به کشاورزی و گله داری اشتغال دارند. صنایع دستی آنان قالیچه بافی است . راه در تابستان اتومبیل رو میباشد. در این آبادی آثار نهر بسیار قدیمی مشاهده میشود. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180124, 'عباسیه', '<span class=\"hlight\">عباسیه .</span> <font color=\"DarkGreen\"><b>[ ع َب ْبا سی ی َ ]</font></b> (اِخ ) دهی است از بخش شیب آب شهرستان زابل واقع در <span class=\"hlight\" dir=\"rtl\">١٤</span>هزارگزی شمال سکوهه و یکهزارگزی خاوری شوسه ٔ زاهدان به زابل . ناحیه ای است واقع در جلگه . هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٥٤٧</span> تن سکنه دارد. آب آن از رودخانه ٔ هیرمند تأمین می شود. محصولات آن غلات، لبنیات، صیفی و پنبه است . اهالی به کشاورزی و گله داری اشتغال دارند. صنایع دستی آنان قالیچه، گلیم و کرباس بافی است . راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180125, 'عباط', '<span class=\"hlight\">عباط.</span><font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) خورش . (المنجد) (از اقرب الموارد).<br /></font></div>'),
(180126, 'عباعب', '<span class=\"hlight\">عباعب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ع َ ]</font></b> (اِخ ) آبی است مر بنی قیس بنی ثعلبه را. (از معجم البلدان ).<br /></font></div>'),
(180127, 'عباعب', '<span class=\"hlight\">عباعب .</span> <font color=\"DarkGreen\"><b>[ ع ُع ِ ]</font></b> (اِخ ) علم مرتجل است که اصل آن شناخته نشده است . یوم عباعب از ایام عرب است . (از معجم البلدان ).<br /></font></div>'),
(180128, 'عباقر', '<span class=\"hlight\">عباقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ]</font></b> (اِخ ) آبی است مر بنی فزاره را. (منتهی الارب ) (از معجم البلدان ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(180129, 'عباقر', '<span class=\"hlight\">عباقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ]</font></b> (ع اِ) رجوع به عَبقر شود.<br /></font></div>'),
(180130, 'عباقل', '<span class=\"hlight\">عباقل .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ]</font></b> (اِخ ) موطنی است مر بنی فریر را از طی به رمل . (از معجم البلدان ).<br /></font></div>'),
(180131, 'عباقیة', '<span class=\"hlight\">عباقیة.</span> <font color=\"DarkGreen\"><b>[ ع َ ی َ ]</font></b> (ع مص ) عباقه . بوی خوش در کسی گرفتن . (تاج المصادر) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بوی خوش به کسی یا چیزی چسبیدن . <BR><font color=\"Blue\">◄</font> منتشر شدن بوی خوش در مکان . <BR><font color=\"Blue\">◄</font> اقامت کردن در مکان . <BR><font color=\"Blue\">◄</font> حریص شدن به چیزی . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص، اِ) دزد سخت دزدنده . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> و انف له عباقیة؛ یعنی عار و ننگ است او را. (منتهی الارب ) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> مرد مکار و سگ زیرک . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شی ٔ عباقیة؛ چیز لازم . (منتهی الارب ) (از ناظم الاطباء) (تاج العروس ). <BR><font color=\"Blue\">◄</font> شی ٔ له عباقیة؛ یعنی او را اثری است باقی . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> اثر زخم در بهترین جای صورت . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درختی است خاردار. <BR><font color=\"Blue\">◄</font> باقی مانده ٔ بوی در چیزی . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(180132, 'عباقیس', '<span class=\"hlight\">عباقیس .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (ع اِ) باقی مانده از بقیه ٔ طعام و پسین چیزها.(منتهی الارب ). بقایا عقب الاشیاء. (اقرب الموارد).<br /></font></div>'),
(180133, 'عباقیل', '<span class=\"hlight\">عباقیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) باقی مانده از بیماری و محبت . (منتهی الارب ).<br /></font></div>'),
(180134, 'عبال', '<span class=\"hlight\">عبال .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) نوعی از درخت ورد کوهی بزرگ که از آن عصا سازند و قیل کان منه عصا موسی . گل کوهی و آن سخت و بزرگ است چندانکه از آن عصا سازند. (منتهی الارب ) (اقرب الموارد). گل کوهی . (مهذب الاسماء).<br /></font></div>'),
(180135, 'عبالة', '<span class=\"hlight\">عبالة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل ل َ ]</font></b> (ع اِمص ) عبالة. ثقل و گرانی . (منتهی الارب ). گرانی . یقال : القی علیه عبالته ؛ ای ثقله . (منتهی الارب ).<br /></font></div>'),
(180136, 'عبالة', '<span class=\"hlight\">عبالة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع مص ) سطبر و تمام اندام گردیدن . (منتهی الارب ). عبلت الفرس ؛ درشت و سطبر پا گردید. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بزرگ شدن . (تاج المصادر). <BR><font color=\"Blue\">◄</font> (اِمص ) ثقل و گرانی . (اقرب الموارد). رجوع به عَبالَّه شود.<br /></font></div>'),
(180137, 'عبام', '<span class=\"hlight\">عبام .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) آب بسیار. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(180138, 'عبام', '<span class=\"hlight\">عبام .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) گران جسم . <BR><font color=\"Blue\">◄</font> عاجز و درمانده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> گران زبان شده . (مهذب الاسماء). العی الثقیل . (اقرب الموارد).<br /></font></div>'),
(180139, 'عبامة', '<span class=\"hlight\">عبامة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع مص ) احمق شدن . گول گردیدن . (منتهی الارب ) (از اقرب الموارد).<br /></font></div>'),
(180140, 'عبامة', '<span class=\"hlight\">عبامة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (اِخ ) آبی است مر عوف بن عبد راکه از بهترین آبهای آنان است . (از معجم البلدان ).<br /></font></div>'),
(180141, 'عباهر', '<span class=\"hlight\">عباهر.</span> <font color=\"DarkGreen\"><b>[ ع َ هَِ ]</font></b> (ع ص ) عظیم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خوش اندام دراز از هر چیزی . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آکنده گوشت . (ناظم الاطباء).<br /></font></div>'),
(180142, 'عباهل', '<span class=\"hlight\">عباهل .</span> <font color=\"DarkGreen\"><b>[ ع َ هَِ <span class=\"hlight\" dir=\"rtl\">/</span> هََ ]</font></b> (ع ص ) شتران بر سرگذاشته . (لسان العرب ) (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ابل عباهلة؛ ای مهملة مسیبة. (اقرب الموارد).<br /></font></div>'),
(180143, 'عباهلة', '<span class=\"hlight\">عباهلة.</span> <font color=\"DarkGreen\"><b>[ ع َ هَِ ل َ ]</font></b> (اِخ ) ملوک حمیر که در اسلام هم بر ملک خود گذاشته شدند. (از لسان العرب ) (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> الاقیال المقرون علی ملکهم فلم یزالوا عنه . (اقرب الموارد) (لسان العرب ).<br /></font></div>'),
(180144, 'عبایة', '<span class=\"hlight\">عبایة.</span> <font color=\"DarkGreen\"><b>[ ع َ ی َ ]</font></b> (ع اِ) نوعی از گلیم . (منتهی الارب ). نوعی از پوشیدنی که روی جامه ها پوشند. (اقرب الموارد). عباء. <BR><font color=\"Blue\">◄</font> (ص ) مرد جافی گران جسم . (آنندراج ) (منتهی الارب ).<br /></font></div>'),
(180145, 'عبایة', '<span class=\"hlight\">عبایة.</span> <font color=\"DarkGreen\"><b>[ ع َ ی َ ]</font></b> (اِخ ) اسبی است . (منتهی الارب ).<br /></font></div>'),
(180146, 'عبایی', '<span class=\"hlight\">عبایی .</span> <font color=\"DarkGreen\"><b>[ ع َ یی ی ]</font></b> (اِخ ) محمدبن یحیی العبایی سمرقندی، مکنی به ابواحمد. وی از عبدالعزیزبن مرزبان روایت کند و علی بن ابراهیم بن نصرویه سمرقندی از وی روایت کند. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١١</span>).<br /></font></div>'),
(180147, 'عبب', '<span class=\"hlight\">عبب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب ُ ]</font></b> (ع اِ) آب جهجهان - ریزان . (منتهی الارب ) (آنندراج ). آبهای جهنده .(اقرب الموارد). <BR><font color=\"Blue\">◄</font> درختی است که آن را الراء نامند. ابن سکیت گوید: عبب درخت کوچکی است که از حمی آب خورد و او را میوه های ریز بدی است که مربع الشکل است . (از معجم البلدان ). دانه ٔ کاکنج است و گفته اند عنب الثعلب است و گفته اند «راء» است و گفته انداز درختان تلخ است . (اقرب الموارد) (لسان العرب ).<br /></font></div>'),
(180148, 'عبب', '<span class=\"hlight\">عبب .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِ) میوه و ثمره ٔ کاکنج است که عروس در پرده باشد و آن راعبعب نیز گویند. (برهان ). رجوع به ماده ٔ بعد شود.<br /></font></div>'),
(180149, 'عبث', '<span class=\"hlight\">عبث .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b>(ع ص، اِ) هزل . (اقرب الموارد). هرز. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (مص ) کاری کردن که فایده آن معلوم نباشد یا فاعل آن را غرض درستی نبود. (اقرب الموارد).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عبث گفتن </span> ؛ بی معنی و لاطائل حرف زدن . (ناظم الاطباء).<br /></font></div>'),
(180150, 'عبثه', '<span class=\"hlight\">عبثه .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ث َ ]</font></b>(ع مص ) یکبار بازی کردن . (آنندراج ) (منتهی الارب ).<br /></font></div>'),
(180151, 'عبد', '<span class=\"hlight\">عبد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) بنده . غلام . خلاف حُرّ از مردم . (منتهی الارب ) (اقرب الموارد) (آنندراج ). ج، عَبدون و عَبید و آن نادر است و اَعْبُد و عِباد و عُبدان و عِبدان و عِبّدان و عُبُد و عُبود و عِبَّدة و عَبَدة. و جمعالجمع آن اَعابد و مَعابد و اعَبَدَة و اسم جمع عِبدَّی و عِبدّاءو مَعبوداء و مَعبَدة. (اقرب الموارد) <span class=\"hlight\">:</span> <br />سعدی رضای دوست طلب کن نه حظ خویش <br />عبد آن کند که رأی خداوندگار اوست .<br /> <font color=\"Red\">سعدی (بدایع).</font><br />کسی را که درج طمع درنوشت <br />نباید به کس عبد چاکر نوشت .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عبد مدبر</span> ؛ برده ای است که مولایش بشرط مرگ خود و بعد از آن آزادش کرده باشد به جمله ٔ «أنت حرّ بعدوفاتی » یا «اًذا مت ّ فأنت حرا و عَتیق أو معتق ».(شرایع صص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span> - <span class=\"hlight\" dir=\"rtl\">٢٠٨</span>). و چنین عبدی به مرگ مولایش آزاد میشود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عبد مکاتب </span> ؛ برده ای است که با مولایش در مورد آزادیش قراردادی بسته باشد که هرگاه بها و قیمت خود را بدهد آزاد شود به جمله ٔ «اًن أدّیت فانت حرﱡ» و آن یا مطلق است یا مشروط. مطلق آن است که اکتفا شود به عقد و مدت و عوض و نیت، و مشروط آن است که شرط کند اگر نتوانست بهای خود را بدهد برده شود. در مکاتب مطلق عبد هر اندازه از قیمت خود را بدهد به همان اندازه آزاد میشود و در مکاتب مشروط مادام که تمام بها و قیمت را نپرداخته است عبد است : اذا مات المکاتب و کان مشروطاً بطلت الکتابة و کان ما ترکه لمولاه و أولاده رق ّو اًن لم یکن مشروطاً تحرَّر منه بقدر ما أداه و کان الباقی رقاً لمولاه . (شرایع صص <span class=\"hlight\" dir=\"rtl\">٢٠٩</span> - <span class=\"hlight\" dir=\"rtl\">٢١٣</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عبدقن </span> ؛ برده ٔ خالص را گویند که به هیچ وجه در معرض آزادی نباشد. رجوع شود به شرح لمعه .<br /><BR><font color=\"Blue\">◄</font> انسان اعم از آزاد و برده . (اقرب الموارد) (لسان العرب ). <BR><font color=\"Blue\">◄</font> نام گیاهی است خوشبوی که شتر را خورانند برای آنکه او را فربه کند و به شیرش بیفزاید. (اقرب الموارد) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> پیکان کوتاه پهن . (منتهی الارب ) (اقرب الموارد) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> سیماب و جیوه . (ناظم الاطباء).<br /></font></div>'),
(180152, 'عبد', '<span class=\"hlight\">عبد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) کوه کوچک سیاهی است که دو کوه کوچک تر دیگر او را احاطه کرده اند که ثدیین نامند. (معجم البلدان ).<br /></font></div>'),
(180153, 'عبد', '<span class=\"hlight\">عبد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) کوهی است مر بنی اسد را. (معجم البلدان ).<br /></font></div>'),
(180154, 'عبد', '<span class=\"hlight\">عبد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) موضعی است به سبعان در بلاد طی . (معجم البلدان ).<br /></font></div>'),
(180155, 'عبد', '<span class=\"hlight\">عبد.</span> <font color=\"DarkGreen\"><b>[ ع َ ب ِ ]</font></b> (ع ص ) مرد با ننگ و عار. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> غضبان . (اقرب الموارد).<br /></font></div>'),
(180156, 'عبد', '<span class=\"hlight\">عبد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن قصی بن کلاب بن مرة، جدجاهلی است پسران وی از قبائل «قریش البطاح » اند. مسکن و مأوای آنان در بطحه ٔ مکه بود. این طایفه در حدود سال <span class=\"hlight\" dir=\"rtl\">١٨٥</span> هَ . ق . منقرض شدند. (از الاعلام زرکلی ).<br /></font></div>'),
(180157, 'عبد', '<span class=\"hlight\">عبد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمدبن عبداﷲبن عُفَیر ملقب به ابوذر انصاری هروی از فقهاء مالکی بود. او را تألیفات زیاد است از جمله : تفسیر قرآن و مستدرک بر صحیحین . السنة و الصفات . معجمان . (از الاعلام زرکلی ). و رجوع به ابوذر هروی شود.<br /></font></div>'),
(180158, 'عبد', '<span class=\"hlight\">عبد.</span> <font color=\"DarkGreen\"><b>[ ع َ ب ُ ]</font></b> (ع اِ) جمع عبد. (منتهی الارب ). رجوع به عبد شود.<br /></font></div>'),
(180159, 'عبد', '<span class=\"hlight\">عبد.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِ) خشم . (تاج العروس ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> گر سخت . (منتهی الارب ). جرب سخت که درمان نپذیرد. (لسان العرب ) (تاج العروس ). جرب . (تاج العروس ). <BR><font color=\"Blue\">◄</font> عار. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پشیمانی و ملامت نفس . (منتهی الارب ) (تاج العروس ) (لسان العرب ). <BR><font color=\"Blue\">◄</font> آز. حرص . <BR><font color=\"Blue\">◄</font> ابا و انکار. (منتهی الارب ) (تاج العروس ).<br /></font></div>'),
(180160, 'عبد شمس', '<span class=\"hlight\">عبد شمس .</span> <font color=\"DarkGreen\"><b>[ ع َ دِ ش َ ]</font></b> (اِخ ) ابن عبدمناف از فرزندان اوست . بنوامیه، که بنوامیه ٔ اکبر و بنوامیه ٔ اصغراند و آنها قبیله ٔاول از عبدمناف بن قصی اند. (صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٧</span>).<br /></font></div>'),
(180161, 'عبد ضخم', '<span class=\"hlight\">عبد ضخم .</span> <font color=\"DarkGreen\"><b>[ ع َ دِ ض َ ]</font></b> (اِخ ) قبیله ٔ ششم از عرب بادیه است و آنان بنو عبد ضخم بن ارم بن سام بن نوح اند. مسکن آنان طائف بود سپس نابود شدند. گویند آنان اولین کس اندکه بخط عربی نوشته اند. (از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٤</span>).<br /></font></div>'),
(180162, 'عبدآباد', '<span class=\"hlight\">عبدآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است جزء بخش شهریار شهرستان تهران . واقع در <span class=\"hlight\" dir=\"rtl\">٥٠٠٠</span> گزی جنوب شهریار و راه عمومی .ناحیه ای است جلگه ای هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٣٢٣</span> تن سکنه دارد. آب آن از قنات و رود کرج تأمین میشود. محصولات آن غلات، صیفی، چغندرقند، انگور و میوه جات است . شغل اهالی زراعت است راه مالرو دارد و از طریق علیشاه عوض ماشین میرود. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180163, 'عبدآباد', '<span class=\"hlight\">عبدآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است از دهستان زوارم بخش شیروان شهرستان قوچان . واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی جنوب باختری شیروان و <span class=\"hlight\" dir=\"rtl\">٥</span>هزارگزی جنوب مالرو عمومی شیروان - سبزوار. ناحیه ای است کوهستانی آب و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٦٢٣</span> تن سکنه دارد. آب آن از چشمه و رودخانه تأمین میشود. محصولات آن غلات و انگور است . اهالی به کشاورزی، مالداری و قالیچه بافی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180164, 'عبدآباد', '<span class=\"hlight\">عبدآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است از دهستان پائین رخ بخش کدکن شهرستان تربت حیدریه . واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزار گزی خاور کدکن سر راه مالرو عمومی کدکن . ناحیه ای است دامنه ای . آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٤١</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات و چغندرقند است . اهالی به کشاورزی و گله داری اشتغال دارند و از جوادیه میتوان ماشین برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180165, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن الحسین معروف به ابن ناقیا. رجوع به ابن ناقیا و به الاعلام زرکلی شود.<br /></font></div>'),
(180166, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن سید رای بن عبدالوهاب بن وزیر القیسی معروف به ابن وزیر از امراء مغرب بود. پس از پدر خود ولایت قصر الفتح و حدود غربی آن را یافت لکن ولایتش چندی نپایید و فرنگان به سال <span class=\"hlight\" dir=\"rtl\">٦١٤</span> هَ . ق . بر وی غالب شدند و او را اسیر کردند. وی با حیله ای خود را رها کرد و به مراکش رفت و بدانجا مناصبی یافت سپس به اشبیلیه شد. محمدبن یوسف بن هود در <span class=\"hlight\" dir=\"rtl\">٦٢٧</span> هَ . ق . او را به مارده به قتل رساند. (از الاعلام زرکلی ).<br /></font></div>'),
(180167, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن حکم بن سهل بن عبداﷲبن محمدبن حکم باقشیر معروف به ابن باقشیر. وی فقیه و از مردم حضرموت است . از تألیفات اوست : قلائد الخرائد و فوائد الفوائد در فقه . القول الموجز المبین . السعادة و الخیر فی مناقب السادة بنی قشیر.وی به سال <span class=\"hlight\" dir=\"rtl\">٩٥٨</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180168, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن خصیب معروف به ابن خصیب . یکی از قضاة مصر ومردی قوی النفس و فاضل بود او را کتبی است در رد بعضی علما. وی به سال <span class=\"hlight\" dir=\"rtl\">٢٧٢</span> هَ . ق . به اصبهان متولد شد ودر <span class=\"hlight\" dir=\"rtl\">٣٤٧</span> هَ . ق . به مصر درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180169, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن زیاد النیشابوری . حافظ حدیث و امام شافعیه ٔ عراق بود. او را تصانیفی است . (از الاعلام زرکلی ).<br /></font></div>'),
(180170, 'عبدا', '<span class=\"hlight\">عبدا.</span><font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن سعیدبن سنان الخفاجی . رجوع به ابن سنان خفاجی و به الاعلام زرکلی شود.<br /></font></div>'),
(180171, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن سید، مکنی به ابومحمد و معروف به بطلیوس . رجوع به ابن سید ابومحمد عبداﷲ و به الاعلام زرکلی شود.<br /></font></div>'),
(180172, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمد. رجوع به ابن السید ابومحمد عبداﷲبن محمدبن السید شود.<br /></font></div>'),
(180173, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن جعفربن حیان الاصبهانی، مکنی به ابومحمد. از حفاظ حدیث است . نسبت او به جدش حیان است از تألیفات اوست : کتاب السنة.وی به سال <span class=\"hlight\" dir=\"rtl\">٤٦٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180174, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن احمدبن خلف المطری الخزرجی العبادی المدنی معروف به المطری . حافظ حدیث و مورخ بود.او راست : تاریخ المدینة. وی به سال <span class=\"hlight\" dir=\"rtl\">٦٩٨</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">٧٦٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180175, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن علان، مکنی به ابواحمد و معروف به ابن ابی علان . قاضی اهواز و معتزلی بود.او را تصانیفی نیک است . به سال <span class=\"hlight\" dir=\"rtl\">٣٢١</span> هَ . ق . متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٤٠٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180176, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن ابی عصرون، مکنی به ابوسعید. رجوع به ابن ابی عصرون ابوسعید شود.<br /></font></div>'),
(180177, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن ابی شیبة العبسی . حافظ حدیث بود وکتبی در احادیث نوشته است . از جمله : المسند المصنف .وی به سال <span class=\"hlight\" dir=\"rtl\">٢٣٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180178, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن ابی بکر العیاشی معروف به عیاشی مغربی . از افاضل مغرب است . مدتی دراز در مشرق سفر کرد و «رحله ای » در چند مجلد بنوشت . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٩٠</span> هَ . ق . به مغرب درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180179, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َدُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن علی بن عبداﷲبن العباس بن عبدالمطلب، مکنی به ابوالعباس سفاح . نخستین خلیفه ٔ عباسی است . ابومسلم خراسانی به سال <span class=\"hlight\" dir=\"rtl\">١٣٢</span> هَ . ق . با وی به خلافت بیعت کرد و مردم را به اطاعت او خواند. وی مردی سخت عقوبت و بزرگ انتقام بود. بقایای امویان را بکشت و به دار زد و بسوخت تا آنجا که جز اطفال و کسانی که به اندلس گریختند کسی از آنان نماند. و بدان جهت او را سفاح گفتند که بسیاری از بنی امیه را بکشت وخون ایشان را بریخت . سفاح هاشمیه را بنا کرد و مقر حکومت خود ساخت . او نخستین کسی است که وزارت را در اسلام بوجود آورد و پیش از او امویان مردانی را جهت مشورت برمیگزیدند. وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٤</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٣٦</span> هَ . ق . به انبار درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180180, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن صارة البکری الاندلسی معروف به شَنْتَرینی . وی شاعرو کاتب بعضی امراء بود سپس به وراقت پرداخت . او راست دیوانی در شعر و شعر او را رقتی است .وی به سال <span class=\"hlight\" dir=\"rtl\">٥١٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180181, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن عامر الشبراوی . فقیه و از مردم مصر است . او را نظمی است . وی ریاست الازهر یافت . از تألیفات اوست : دیوان شعر. مفتاح الالطاف فی مدائح الاشراف و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٩١</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١١٧٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180182, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن عبدالرحمان بن الحکم بن هشام . از ملوک بنی امیه به اندلس است . به سال <span class=\"hlight\" dir=\"rtl\">٢٧٥</span> هَ . ق . روز مرگ برادرش منذر مردم قرطبه با وی بیعت کردند. مورخان وی را از صلحای بنی امیه ٔ مغرب میدانند. او به سال <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> هَ. ق . در قرطبه درگذشت . در عهد وی شورشهایی بپا گشت .وی مردی مقتصد بود و اسراف را خوش نداشت . صدقات و مبرات بسیار میداد و مردی پرهیزگار و متفنن در علوم بود و به لغات عربی آشنایی داشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180183, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن عبداﷲبن جعفربن الیمان الجعفی، مکنی به ابوجعفر. حافظ حدیث و ثقه بود. وی نخستین کسی است که مسند صحابه را به ماوراءالنهر جمع کرد، و بدان جهت مسندی لقب یافت . وی امام حدیث در ماوراء النهر بود. به سال <span class=\"hlight\" dir=\"rtl\">٢٢٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180184, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن عبداﷲبن حسن بن الحسن بن علی بن ابی طالب شریف معروف به اشتر العلوی . از دعاة و پیشوایان شورش ضد عباسیان بود به همراهی پدرش در مدینه بر منصور عباسی خروج کرد. پدرش او را به بصره فرستاد تا اسبانی بخرد و او پس از خریدن اسب به سند رفت و از عمربن حفص امیر آن ناحیت خلوت خواست و از فرماندهان وی برای پدر خویش بیعت گرفت . هنگامی که عمربن حفص عازم حرکت بود خبر مرگ ابوالاشتر به وی رسید. عمر این خبر را از عبداﷲ مخفی داشت و او را نزد یکی از ملوک سند فرستاد و او در آنجا به اکرام بزیست . منصور او را طلبید ولی عمر اجابت نکرد سپس یکی از عمال منصور بر وی دست یافت و او را به سال <span class=\"hlight\" dir=\"rtl\">١٥١</span> هَ . ق . در شاطی مهران به قتل رساند. (از الاعلام زرکلی ).<br /></font></div>'),
(180185, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن عبداﷲبن عاصم الانصاری . از بنی ضبیعة و شاعری هجاگوی و از طبقه ٔ جمیل بن معمر و نصیب بود و معاصر جریر و فرزدق و از مردم مدینه بود. ولیدبن عبدالملک او را به یمن تبعید کرد. حماد راویه او را در نسیب بر شعرای زمان وی مقدم میداشت عبداﷲ بخاطر تنگی گوشه ٔ چشمش به احوص ملقب شد.وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180186, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن عبداﷲبن عبدالرحمان السعدی معروف به الغالب باﷲ. از ملوک دولت سعدیان مراکش است . به سال <span class=\"hlight\" dir=\"rtl\">٩٦٥</span> هَ . ق . به سلطنت مراکش رسید. وی مردی فاضل بود و به آبادانی و ترقی زراعت و صناعت رغبتی عظیم داشت . در عصر وی مراکش به پیشرفتهایی نائل شد. وی به سال <span class=\"hlight\" dir=\"rtl\">٩٣٣</span> هَ . ق . متولد شد و <span class=\"hlight\" dir=\"rtl\">٩٨١</span> هَ . ق . به مراکش درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180187, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن عبدالمعین بن عون معروف به عبداﷲ پاشا. از امراء مکه است که لقب پاشا و وزارت یافت و سپس به سال <span class=\"hlight\" dir=\"rtl\">١٢٧٤</span> هَ . ق . بعد از مرگ پدربه امارت رسید. وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٣٧</span>هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٢٩٤</span> هَ . ق . به طائف درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180188, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابی محمدبن عبیدبن سفیان معروف به ابن ابی الدنیا. رجوع به ابن ابی الدنیا و به الاعلام زرکلی شود.<br /></font></div>'),
(180189, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن عبیداﷲ معروف به ابن الخاقان . رجوع به ابن خاقان شود.<br /></font></div>'),
(180190, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن عبید قرشی . رجوع به ابن ابی الدنیا شود.<br /></font></div>'),
(180191, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن علی بن ابوطالب، مکنی به ابوهاشم . رجوع به ابوهاشم عبداﷲبن محمد و نیز به الاعلام زرکلی و خاندان نوبختی شود.<br /></font></div>'),
(180192, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن علی بن عباس، مکنی به ابوجعفر و معروف به منصور. وی دومین خلیفه ٔ عباسی و نخستین کس از ملوک عرب است که به علوم توجه کرد.وی عارف به فقه و ادب بود و در فلسفه و علم فلک تقدمی داشت و به علما محبت میکرد و پس از مرگ برادرش سفاح به سال <span class=\"hlight\" dir=\"rtl\">١٣٦</span> هَ . ق . به خلافت رسید. شهر بغداد را به سال <span class=\"hlight\" dir=\"rtl\">١٤٥</span> هَ . ق . او بنا کرد. در زمان او اعراب به علوم یونان و ایران توجه کردند. در عهد او محمدبن ابراهیم فزاری نخستین اسطرلاب را ساخت . منصور از لهو و لعب گریزان و مردی جدی و متفکر بود. توقیعات او در کمال بلاغت است . به سال <span class=\"hlight\" dir=\"rtl\">٩٥</span> هَ . ق . متولد شد. و در <span class=\"hlight\" dir=\"rtl\">١٥٨</span>هَ . ق . به بئر میمون در مکه درگذشت . وی مدت <span class=\"hlight\" dir=\"rtl\">١٢</span> سال خلافت کرد. رجوع به آل عباس شود. (از الاعلام زرکلی ).<br /></font></div>'),
(180193, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن مطیعبن الاسود الکعبی القرشی العدوی . وی از قریش و مردی شجاع بود. در حیات رسول خدا (ص ) متولد شد و در یوم الحرة علیه قریش جنگید. و چون یارانش شکست خوردنددر مدینه پنهان شد. سپس به مکه رفت و ساکن شد. ابن زبیر او را به عنوان عامل خود به کوفه فرستاد. مختاربن عبیده وی را اخراج کرد. به مکه بازگشت . و سرانجام به سال <span class=\"hlight\" dir=\"rtl\">٧٣</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180194, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عوف، مکنی به ابومسلم . رجوع به ابومسلم خولانی تمیمی عبداﷲ شود.<br /></font></div>'),
(180195, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن علی بن محمدبن سلیمان بن حمائل مشهور به ابن غانم . شاعر است و به حدیث اشتغال داشت . ولادت و وفات او به دمشق بود. ولایت دیوان انشاء دمشق یافت و با صلاح الدین صفدی مراسلات داشت . از کتب او است : الفائق فی الکلام الرائق . تولد او به سال <span class=\"hlight\" dir=\"rtl\">٧١١</span> هَ . ق . است . و در <span class=\"hlight\" dir=\"rtl\">٧٤٤</span> هَ . ق .درگذشت . (از الاعلام زرکلی ). رجوع به ابن غانم شود.<br /></font></div>'),
(180196, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن علی بن مکتفی المعتضدمعروف به المستکفی باﷲ. از خلفاء دولت عباسی عراق است . بعد از خلع المتقی باﷲ به سال <span class=\"hlight\" dir=\"rtl\">٣٣٣</span> هَ . ق . با اوبیعت کردند و مدت یکسال و چهار ماه خلافت کرد. به امر او القاب معزالدوله، عمادالدوله، رکن الدوله را درپولها سکه زدند. سرانجام معزالدوله دو تن از دیلمیان را فرمود تا او را از تخت فرود آوردند و عمامه ٔ وی را به گردنش بسته کشان کشان نزد معزالدوله بردند و چشم او را میل کشیدند سپس او را زندانی کردند و به سال <span class=\"hlight\" dir=\"rtl\">٣٣٨</span> هَ . ق . در زندان درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180197, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عمر، مکنی به ابوسعید و ملقب به بیضاوی . رجوع به بیضاوی شود.<br /></font></div>'),
(180198, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عمربن بدربن عبداﷲبن جعفر. از سلاطین حضرموت بود به سال <span class=\"hlight\" dir=\"rtl\">١٠٣١</span> هَ . ق . پس از مرگ پدر ولایت یافت . پس از چندی از سلطنت کناره گرفت و به مکه رفت و عزلت گزید و به سال <span class=\"hlight\" dir=\"rtl\">١٠٤٥</span> هَ . ق . به مکه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180199, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عمربن خطاب العدوی . صحابی و از معززترین خانواده های قریش در جاهلیت بود. با پدر خود به مدینه هجرت کرد و در فتح مکه حاضر بود. مدت <span class=\"hlight\" dir=\"rtl\">٦</span> سال در اسلام فتوی داد پس از قتل عثمان گروهی نزد وی آمدندکه با او به خلافت بیعت کنند نپذیرفت . وی دوبار در جنگ افریقا شرکت کرد. نخست به همراهی ابن ابی سرح و بار دوم با معاویةبن حدیج . وی به سال <span class=\"hlight\" dir=\"rtl\">٧٣</span> هَ . ق . درگذشت . او آخرین صحابی است که به مکه درگذشت . از او <span class=\"hlight\" dir=\"rtl\">٢٦٣٠</span>حدیث در صحیحین روایت شده است . (از الاعلام زرکلی ).<br /></font></div>'),
(180200, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عمربن عبداﷲبن احمد ملقب به بامخرمة. مفتی یمن و علامه ٔ عصر خود بود. به حضرموت و زبید و الشحر و عدن و تعز و حرمین تدریس کرد و به سال <span class=\"hlight\" dir=\"rtl\">٩٤٣</span> هَ . ق . قضاوت الشحر را یافت سپس استعفا کرد و به عدن رفت . تولد او به سال <span class=\"hlight\" dir=\"rtl\">٩٠٧</span> هَ . ق . بود و در <span class=\"hlight\" dir=\"rtl\">٩٧١</span> هَ . ق . به عدن درگذشت . او راست : المصباح فی شرح العدة و السلاح . الدرة الزهیه فی شرح الرحییة. حقیقة التوحید فی الرد علی طائفة ابن عربی . الفتاوی . تألیفی در معرفت اوقات و سمت قبله و معرفت ساعات . رساله ای در علم حساب . تألیفی در علم مساحت . تکمیل و تذییل برطبقات اسنوی . رسالة فی العمل بالربع المجیب . رسالة فی ظل الاستواء، الجداول المحققة المحررة فی علم الهیئة. و او راست : ارجوزه ها و شعر. (از الاعلام زرکلی ).<br /></font></div>'),
(180201, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عمربن عثمان بن عفان الاموی القرشی . شاعری ظریف طبع و سخاوت مند بود. در جنگهائی که مسلمةبن عبدالملک به روم کرد با وی بود. بخاطر سکونت او در قریه العرج وی را عرجی لقب دادند. او به اتهام قتل بنده ٔ خویش به امر محمدبن هشام والی مکه به زندان افتاد و در زندان در حدود سال <span class=\"hlight\" dir=\"rtl\">١٢٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180202, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عمربن عیسی، مکنی به ابویزید دبوسی . نخستین کس است که علم خلاف را بوجود آورد. نسبت او به «بوسیه » بین بخاری و سمرقند است . مردی فقیه بود و به سال <span class=\"hlight\" dir=\"rtl\">٤٢٠</span> هَ . ق . به بخاری درگذشت . او راست تأسیس النظر. (از الاعلام زرکلی ).<br /></font></div>'),
(180203, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عمربن غانم بن شرحبیل الرعینی . قاضی، فقیه و پادشاه بود و ازمردم افریقیه است . برای کسب علم به شام و عراق رفت .هارون الرشید به سال <span class=\"hlight\" dir=\"rtl\">١٧١</span> هَ . ق . وی را قضاء افریقیه کرد و بدان شغل بود تا به سال <span class=\"hlight\" dir=\"rtl\">١٩٠</span> هَ . ق . در قیروان درگذشت . اخبار او بسیار است . (از الاعلام زرکلی ).<br /></font></div>'),
(180204, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َدُل ْ لاه ]</font></b> (اِخ ) ابن عمربن محمد مشهور به الافیونی . از ادباء و شعراء عصر خود بود. مولد او طرابلس شام است و به مصر رفت و سپس به شام بازگشت و تا پایان عمردر دمشق سکونت جست . وی به سال <span class=\"hlight\" dir=\"rtl\">١١٥٤</span> هَ . ق . به دمشق درگذشت . از تألیفات اوست : العقود الدریة فی رحلة الدیار المصریة الزهرالبسام فی فضائل الشام . رنة المثانی فی حکم الاقتباس القرآنی . المنحة القدسیه فی الرحلة القدسیه . دیوان شعر و جز آن . (از الاعلام زرکلی ).<br /></font></div>'),
(180205, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عمروبن حرام بن ثعلبه . از بزرگان صحابه و از نقباء اثناعشر است . وی با <span class=\"hlight\" dir=\"rtl\">٧٠</span> تن از انصار در عقبه و جنگ بدر شرکت کرد و به سال <span class=\"hlight\" dir=\"rtl\">٣</span> هَ . ق . در جنگ احد به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180206, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عمروبن عاص از قریش و صحابی است . در جاهلیت کتابت میکرد و سریانی را نیک میدانست . او پیش از پدر اسلام آورد و ازحضرت رسول اجازه خواست تا آنچه او گوید بنویسد. وی مردی کثیرالعبادة بود چندانکه پیغمبر او را فرمود جسد ترا بر تو حقی است و زن تو را بر تو حقی است و دو چشم تو را بر تو حقی است . در غزوات حاضر بود و به سال <span class=\"hlight\" dir=\"rtl\">٦٥</span> هَ . ق . در آخر خلافت عمر به طائف درگذشت . در صحیحین از او <span class=\"hlight\" dir=\"rtl\">٧٠٠</span> روایت آمده است . (از الاعلام زرکلی ).<br /></font></div>'),
(180207, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عمروالنهدی . از اصحاب مختار ثقفی است . در جنگ صفین با علی (ع ) حاضر بود و در جنگهای مختار حضور داشت و در جنگ مصعب بن زبیر در نزدیکی کوفه به سال <span class=\"hlight\" dir=\"rtl\">٦٧</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180208, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عودةبن عبداﷲ صوفان بن عیسی القدومی . فقیه حنبلی و از مردم فلسطین است . از تألیفات اوست : المنهج الاحمد فی دره ٔ المثالب التی تنمی لمذهب الامام احمد. بغیة النساک و العباد فی البحث عن ماهیة الصلاح و الفساد. هدایة الراغب الاجوبة الدریه فی دفع الشبه و المطاعن الواردة علی الملة الاسلامیة.الرحلة الحجازیة و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٤٦</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٣٣١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180209, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن مبارک بن واضح المروزی . رجوع به ابن مبارک ابوعبدالرحمان و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180210, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عیسی بن بختویه . رجوع به ابن بختویه ابوالحسن عبداﷲبن عیسی شود.<br /></font></div>'),
(180211, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عیسی الاصفهانی ثم التبریزی مشهور به افندی . در حدود سال <span class=\"hlight\" dir=\"rtl\">١١٣٠</span> هَ . ق . به تبریز درگذشت . عالم امامی است . از تألیفات اوست : ریاض العلماء در چند مجلد که دو مجلد آن به خط مؤلف در کتابخانه ٔ دانشکده ادبیات تهران موجود است . (از الاعلام زرکلی ) (از فهرست نسخ خطی دانشکده ادبیات تهران ).<br /></font></div>'),
(180212, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن غانم الدراجی الهذالی النجاعی . از مردم جزائر و فقیه و متصوف است . تولد و تعلیم او در قسطنطنیه بود، سپس به تونس و مدینه رفت و در مدینه سکونت جست . از تألیفات اوست : ارشاد اهل الهمم العلیة فی الادعیة النبویة. وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٩٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180213, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن فروخ الفارسی . فقیه و عالم به احادیث و از مردم افریقا بود. روح بن حاتم قضاوت بروی عرضه کرد و او نپذیرفت . به سال <span class=\"hlight\" dir=\"rtl\">١٧٦</span> هَ . ق . به مصر درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180214, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن فیصل بن ترکی . از امراء نجد است بعد از پدر به اتفاق آل سعود ولایت نجد یافت . و در آغاز کار سیاستی نیکو پیش گرفت . سپس با بنی اعمام خویش بدرفتاری کرد و آنان وی را به سال <span class=\"hlight\" dir=\"rtl\">١٢٧٧</span> هَ . ق . خلع کردند و او در حائل اقامت جست سپس در حدود سال <span class=\"hlight\" dir=\"rtl\">١٣٠٥</span> هَ . ق . به ریاض آمد و به رسیدن بدانجا درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180215, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن قاسم بن مظفربن علی شهرزوری ملقب به المرتضی . مردی فاضل بود و او را شعری رائق است . مدتی به بغداد اقامت کرد سپس به موصل رفت و تا پایان عمر قضاوت آنجا را بعهده داشت . وی به سال <span class=\"hlight\" dir=\"rtl\">٤٦٥</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">٥١١</span> هَ . ق . به موصل درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180216, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن قحطان بن اسعدبن ابی یعفر. به سال <span class=\"hlight\" dir=\"rtl\">٣٣٣</span> هَ . ق . در عهد عباسیان ولایت یمن را مستقلاً بعهده داشت و خطبه ٔ عباسیان را قطع کرد و به نام ممالیک مصر خطبه خواند به سال <span class=\"hlight\" dir=\"rtl\">٣٨٧</span> هَ . ق . به زبید درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180217, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن قیس . رجوع به ابوخمیصه عبداﷲبن قیس شود.<br /></font></div>'),
(180218, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َدُل ْ لاه ]</font></b> (اِخ ) ابن قیس بن سلیم بن حضاربن حرب . رجوع به ابوموسی اشعری عبداﷲبن قیس و الاعلام زرکلی شود.<br /></font></div>'),
(180219, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن کثیر الداری المکی .رجوع به ابن کثیرعبداﷲبن کثیر و الاعلام زرکلی شود.<br /></font></div>'),
(180220, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن کعب بن عمروالانصاری . صحابی است . در جنگ بدر شرکت کرد. وی به سال <span class=\"hlight\" dir=\"rtl\">٣٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180221, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن لهیعةبن فرعان الحضرمی المصری، مکنی به ابوعبدالرحمان . رجوع به ابن لهیعة ابوعبدالرحمان و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180222, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن مالک بن نصر. از مردم شنوءة از ازد قحطانیه و جدی جاهلی است . از نسل اوست : ماسخةبن حارث . (از الاعلام زرکلی ).<br /></font></div>'),
(180223, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن هارون الرشید. رجوع به مأمون عباسی شود.<br /></font></div>'),
(180224, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن مسعودبن غافل بن جبیب الهذلی . رجوع به ابن مسعود و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180225, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن مسلم بن قتیبة الدینوری معروف به ابن قتبیه . رجوع به ابن قتیبه ابومحمد عبداﷲ و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180226, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن مسملةبن قعنب الحارثی . از رجال حدیث و ثقات و از مردم مدینه است . در بصره سکونت جست و به سال <span class=\"hlight\" dir=\"rtl\">٢٢١</span> هَ . ق . بدانجا درگذشت . بخاری از وی <span class=\"hlight\" dir=\"rtl\">١٢٣</span> و مسلم <span class=\"hlight\" dir=\"rtl\">٧٠</span> حدیث آورده است . (از الاعلام زرکلی ).<br /></font></div>'),
(180227, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن مصعب بن ثابت بن عبداﷲبن زبیر. امیر یمامه است . در زمان خلافت مهدی عباسی و هادی ولایت یمامه را یافت و به سال <span class=\"hlight\" dir=\"rtl\">١٨٥</span> هَ . ق . به بغداد درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180228, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن وداع بن زیار. رجوع به ابن وداع عبداﷲ شود.<br /></font></div>'),
(180229, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن مظعون الجمحی معروف به ابن مظعون . صحابی بدری و از شجعان صاحب رأی و تقدم و از طرف مادر برادر عثمان بن عفان بود. وی به سال <span class=\"hlight\" dir=\"rtl\">٣٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180230, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن معاویةبن عبداﷲبن جعفربن ابی طالب . از رؤسای طالبیان و شعراء آنان بود. به سال <span class=\"hlight\" dir=\"rtl\">١٧٧</span> هَ . ق . در کوفه خروج کردو از اطاعت بنی مروان سر باز زد و مردم را به بیعت با خود خواند. مردم کوفه با او بیعت کردند سپس مردم مدائن نیز بیعت خود را اعلام داشتند. عبداﷲبن عمر والی کوفه با وی نبرد کرد. اصحاب عبداﷲ پراکنده شدند. و او به مدائن رفت و جمعی از مردم کوفه بدو پیوستند. عبداﷲ بیاری آنان بر حلوان و جبال و همدان و ری و اصفهان تسلط یافت و خراج فارس و توابع آن را بدو فرستادند. عبداﷲ در اصطخر اقامت کرد و ابن هبیره امیر عراق لشکریانی به جنگ او فرستاد عبداﷲ نخست مقاومت کرد سپس شکست خورد و به شیراز گریخت و از آنجا به هرات شدعامل هرات او را بگرفت و به امر ابومسلم خراسانی به سال <span class=\"hlight\" dir=\"rtl\">١٢٩</span> هَ . ق . به قتل رساند. (از الاعلام زرکلی ).<br /></font></div>'),
(180231, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن معمر الیشکری . امیری شجاع و از والیان عصر مروانی است . و آخرین ولایت او قهستان و نواحی آن بود که از جانب یزیدبن مهلب بدان شغل گماشته شد. مردم آن سامان بر وی شوریدند و او را به سال <span class=\"hlight\" dir=\"rtl\">٩٨</span> هَ . ق . بکشتند و لشکریانش را متفرق کردند. (از الاعلام زرکلی ).<br /></font></div>'),
(180232, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن مغفل المزنی . صحابی و از اصحاب «الشجره » است به مدینه سکونت کرد و سپس به بصره رفت و به سال <span class=\"hlight\" dir=\"rtl\">٥٧</span> هَ . ق . بدانجا درگذشت . در صحیحین از او <span class=\"hlight\" dir=\"rtl\">٤٣</span> حدیث آمده است . (از الاعلام زرکلی ).<br /></font></div>'),
(180233, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن مقفع. رجوع به ابن مقفع عبداﷲ و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180234, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن منصور ملقب به المستنصر باﷲبن الظاهربن الناصر، مکنی به ابو احمد و معروف به المستعصم باﷲ. رجوع به المستعصم باﷲ و ابواحمد و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180235, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن وهب مولی خزاعه معروف به سیاط. وی از مردم مکه و از مقدمان در صنعت غنا و استاد ابراهیم موصلی بود. به سال <span class=\"hlight\" dir=\"rtl\">١٦٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180236, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن وهب بن مسلم الفهری، مکنی به ابومحمد. فقیه و از ائمه است . وی دارای فقاهت و عبادت و حدیث بوده . ازکتب او است : الموطاء کبیر و صغیر در حدیث . عبداﷲ حافظ، ثقه و مجتهد بود. به سال <span class=\"hlight\" dir=\"rtl\">١٢٠</span> هَ . ق . به مصر متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٩٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180237, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن وهب راسبی . از مردم ازد و از ائمه ٔ اباضیه است . رجوع به راسبی عبداﷲبن وهب شود. و نیز رجوع به الاعلام زرکلی شود.<br /></font></div>'),
(180238, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن مسعدةبن مسعود الفزاری . مورخان او را صاحب الجیوش لقب داده اند چه وی در عصر معاویه در جنگ با رومیان فرمانده ٔ سپاهیان بود و در خانه ٔ فاطمه دختر رسول اﷲ تربیت یافت و سپس نزد علی بن ابی طالب بماند معاویه او را استمالت کرد و او از دشمنان سرسخت علی (ع ) گشت . عبداﷲ تا زمان خلافت مروان بزیست و به سال <span class=\"hlight\" dir=\"rtl\">٦٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180239, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن هاشم بن محمد عبدالمطلب بن الحسن بن نمی شریف حسینی . از امراء مکه بود. به سال <span class=\"hlight\" dir=\"rtl\">١١٠٥</span> هَ .ق . ولایت مکه را یافت و به سال <span class=\"hlight\" dir=\"rtl\">١١٠٦</span> هَ . ق . شریف سعدبن زید بر او غالب شد و او بدیار روم رفت و تا سال <span class=\"hlight\" dir=\"rtl\">١١١٣</span> هَ . ق . بدانجا بماند و در این سال بدانجا درگذشت . وی مدت چهار ماه امارت کرد. (از الاعلام زرکلی ).<br /></font></div>'),
(180240, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َدُل ْ لاه ]</font></b> (اِخ ) ابن هلال بن عامربن صعصعه . جدی جاهلی از نسل میمونه بنت الحارث است . (از الاعلام زرکلی ).<br /></font></div>'),
(180241, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن یحیی، مکنی به ابومحمد. رجوع به ابن کناسه شود.<br /></font></div>'),
(180242, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن یحیی الحضرمی . رجوع به طالب الحق عبداﷲبن یحیی و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180243, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن یزیدبن حاتم المهلبی الازدی . وی از جانب ابن عم خود فضل بن روح امارت تونس را یافت و پس از آنکه بدانجا رسید به سال <span class=\"hlight\" dir=\"rtl\">٧٨</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180244, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن یزیدبن زید، مکنی به ابوموسی . از بنی خطمة الاوسی انصاری است . از اصحاب علی بن ابی طالب بود و در جنگ های حدیبیه و جمل و صفین شرکت کرد. ابن زبیر او را ولایت مکه و سپس امارت کوفه داد در حدود سال <span class=\"hlight\" dir=\"rtl\">٧٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180245, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن یزید المعافری الافریقی، مکنی به ابوعبدالرحمان . تابعی و از فضلاء بوده . در فتح اندلس با موسی بن نصیر شرکت کرد. و در قیروان سکونت جست و خانه و مسجدی در آنجا بنا کرد. وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٠</span> هَ . ق . به قیروان درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180246, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن یعقوب المنصوربن یوسف بن عبدالمؤمن ملقب به العادل فی احکام اﷲ. از ملوک دولت موحدین مراکش بود. به سال <span class=\"hlight\" dir=\"rtl\">٦٢١</span> هَ . ق . در مرسیه با وی بیعت کردند و در اواخر همان سال درمراکش خطبه به نام او خوانده شد و سرانجام به سال <span class=\"hlight\" dir=\"rtl\">٦٢٤</span> هَ . ق . به مرض خناق درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180247, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن یوسف بن الحافظ لدین اﷲ العلوی الفاطمی معروف به العاضد لدین اﷲ. از ملوک دولت فاطمیه ٔ مصر و مغرب بود. به سال <span class=\"hlight\" dir=\"rtl\">٥٥٥</span> هَ . ق . پس از مرگ الفائز به خلافت رسید. در زمان خلافت وی سلطان صلاح الدین قوت یافت و خطبه ٔ عاضد را ترک کرد. اوبه نام المستضی ٔ باﷲ عباسی خطبه خواند در این هنگام عاضد در مرض مرگ بود و کسی او را از این آگاه نکرد.وی به سال <span class=\"hlight\" dir=\"rtl\">٥٤٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180248, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن یوسف بن عبداﷲبن یوسف بن هشام ملقب به جمال الدین، مکنی به ابومحمد. رجوع به ابن هشام جمال الدین عبداﷲ و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180249, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن یوسف بن محمد ملقب به جمال الدین و معروف به الزیلعی . فقیه و عالم بحدیث بود. اصل او از مردم زیلع و به سال <span class=\"hlight\" dir=\"rtl\">٧٦٢</span> هَ . ق . به قاهره درگذشت . او راست : تخریج احادیث الهدایه در مذهب حنفی . تخریج احادیث الکشاف . (از الاعلام زرکلی ).<br /></font></div>'),
(180250, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن یوسف بن محمد الجوینی . از علماء تفسیر و لغت و فقه بود. وی از مردم جوین از نواحی نیشابور است او راست : تفسیر کبیر. التبصرة و التذکرة در فقه . الجمع و الفرق در فقه شافعی و او را رسائلی است از جمله اثبات الاستواء. وی به سال <span class=\"hlight\" dir=\"rtl\">٤٣٨</span> هَ . ق . به نیشابور درگذشت . (از الاعلام زرکلی ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(180251, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) بلیانی بن ضیاءالدین مسعود بلیانی کازرونی فارسی . از اولاد شیخ ابوعلی دقاق است . به سال <span class=\"hlight\" dir=\"rtl\">٦٧٣</span> هَ . ق . درگذشت . از اشعار اوست :<br />تا حق بدو چشم سر نبینم هرگز<br />از پای طلب می ننشینم هرگز<br />گویند که حق به چشم سر نتوان دید<br />آن ایشانند و من چنینم هرگز.<br /><font color=\"Red\">(مجمعالفصحاء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٨</span>).</font><br /></font></div>'),
(180252, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمد بخاری، مکنی به ابومحمد. رجوع به ابومحمد عبداﷲبن محمد بخاری شود.<br /></font></div>'),
(180253, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْلاه ]</font></b> (اِخ ) ابن محمدبن علی کلبی . از امراء کلبیان اصحاب صقلیه است که خطبه بنام ملوک فاطمیه ٔ مصر میکردند. به سال <span class=\"hlight\" dir=\"rtl\">٣٧٥</span> هَ . ق . بعد از مرگ برادر خود جعفر به امارت رسید. او مردی ادیب و دوستدار علم و علماء بود. به سال <span class=\"hlight\" dir=\"rtl\">٣٧٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180254, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن علی هروی . از ذریه ٔ ابی ایوب انصاری معروف به شیخ الاسلام و حافظ حدیث و از ائمه بوده است . او راست : منازل السائرین درحدیث . ذم الکلام و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">٤١٠</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">٤٨٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180255, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن عیسی المروزی، مکنی به ابومحمد و معروف به عبدان . وی حافظ حدیث و مفتی مرو بود. مدتی در مصر اقامت کرد و سپس به مرو رفت . او نخستین کسی است که مذهب شافعی را در خراسان نشر داد. از تألیفات اوست . المعرفة در یک صد جزء. الموطاء. وی به سال <span class=\"hlight\" dir=\"rtl\">٦٢٠</span> هَ . ق . متولد شد ودر <span class=\"hlight\" dir=\"rtl\">٦٩٣</span> هَ . ق . به مرو درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180256, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن فرحون الیعمری المالکی . فقیه و از علماء حدیث بود. اصل او از مردم تونس و مولد و منشأاش مدینه است . از تألیفات او است : الدر المخلص من التفصی و الملخص در حدیث . کشف الغطافی شرح مختصر الموطاً در چهار مجلد. العدة. وی به سال <span class=\"hlight\" dir=\"rtl\">٦٩٢</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">٧٦٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180257, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن قائم بن المقتدر، مکنی به ابوالقاسم و ملقب به المقتدی بامراﷲ. رجوع به ابوالقاسم عبداﷲ مقتدی و مقتدی و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180258, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن محمدبن عبداﷲ، مکنی به ابوسعید و معروف به عبداﷲ استرآبادی . وی حافظ حدیث و مورخ بود. اصل او از استرآباد از نواحی طبرستان است . در سمرقند اقامت کرد و تاریخ سمرقند را نوشت . ابن اثیر از آن تاریخ یاد کرده است . وی به سال <span class=\"hlight\" dir=\"rtl\">٤٠٥</span> هَ . ق . به سمرقند درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180259, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن منازل، مکنی به ابومحمد و معروف به ابن منازل . صوفی و از اجله ٔ مشایخ نیشابور است . طریقه ای مخصوص به خود داشت . به علوم ظاهر (شریعت ) نیز عالم بود. حدیث بسیار مینوشت و روایت میکرد. وی به سال <span class=\"hlight\" dir=\"rtl\">٣٢٩</span> هَ . ق . به نیشابور درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180260, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن ناجیة البربری الاصل البغدادی از حفاظ حدیث و مردی ثقه بود. او راست : مسند.وی به سال <span class=\"hlight\" dir=\"rtl\">٣٠١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180261, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن نافعبن مکرم، مکنی به ابوالعباس . مردی زاهد و از صلحا بود و از نشابور پیاده به مکه رفت مدت <span class=\"hlight\" dir=\"rtl\">٧٠</span> سال عمر کرد.وی به سال <span class=\"hlight\" dir=\"rtl\">٣٨٤</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180262, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ )ابن محمدبن ناقیا، مکنی به ابوالقاسم و معروف به ابن ناقیا. رجوع به ابن ناقیا ابوالقاسم عبداﷲ شود.<br /></font></div>'),
(180263, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن هبةاﷲ ملقب به شرف الدین و معروف به ابن ابی عصرون . رجوع به ابن ابی عصرون و الاعلام زرکلی شود.<br /></font></div>'),
(180264, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن یوسف بن نصرالازدی، مکنی به ابوالولید و معروف به ابن فَرَضی . رجوع به ابن فرضی ابوالولید و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180265, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن یوسف زوزنی . مردی ادیب و از شعراء ظرفاء بود. پادشاهان خراسان او را جهت ندیمی خویش و تربیت و تعلیم فرزندانشان برگزیدند. وی مردی بسیار بذله گو و حاضرجواب و کوتاه قامت بود و قیافه ای مضحک داشت . سال <span class=\"hlight\" dir=\"rtl\">٤٣١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180266, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمد اندلسی، مکنی به ابومحمد. رجوع به ابن زهره ابومحمد عبداﷲ شود.<br /></font></div>'),
(180267, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن علی عجمی الشنشوری . وی فرضی و از فقهاء شافعیه و خطیب جامعه الازهر مصر بود. از تألیفات او است : قرة العینین فی مساحة ظرف القلتین در فقه . الفوائد الشنشوریه فی شرح منظومةالرحبیه در فرائض . الفوائد المرضیه فی شرح الملقبات الوردیه .وی به سال <span class=\"hlight\" dir=\"rtl\">٩٩٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180268, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمد بدری دمشقی مصری وفائی ملقب به تقی الدین و معروف به عبداﷲ البدری . ادیب، عارف به تاریخ و شعر بود. از تألیفات اوست . راحة الارواح فی الحشیش و الراح . مجموعه ٔ شعر و نوادر. عرة الصباح فی وصف الوجوه الصباح . المطالع البدریه فی المنازل القمریه . نزهة الانام فی محاسن الشام .وی به سال <span class=\"hlight\" dir=\"rtl\">٨٨٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180269, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن بطلیوسی . رجوع به ابن السید شود.<br /></font></div>'),
(180270, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن بغدادی، مکنی به ابوالقاسم معروف به ابن ناقیا. رجوع به ابن ناقیا شود.<br /></font></div>'),
(180271, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن بلخی، مکنی به ابوعلی . محدث بلخ بود از کتب اوست : العلل، التاریخ .وی به سال <span class=\"hlight\" dir=\"rtl\">٢٩٤</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180272, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن بلیغبن عبداﷲبن محمد معروف به عبداﷲ پاشا فکری . وزیر مصر و از متأدبان بود او را نظمی است . وی در الازهر علم آموخت و مناصبی یافت و به اتهام شرکت در انقلاب عربی به زندان افتاد و سپس تبرئه شد. از تألیفات اوست : الفوائد الفکریه . المملکة الباطنیه و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٥٠</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٣٠٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180273, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمد حجازی بن عبدالقادربن محمد مشهور به ابن قضیب البان . رجوع به ابن قضیب البان و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180274, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ )ابن محمدبن ذهبی، مکنی به ابومحمد و معروف به ابن الذهبی . رجوع به ابن الذهبی شود. (از الاعلام زرکلی ).<br /></font></div>'),
(180275, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمد عبدالعزیزبن المرزبان . حافظ حدیث و ازعلماء بود. از مردم بغشور (بین هراة و مرو الروذ) است تولد و وفات او به بغداد و در عصر خویش محدث عراق بود. او راست : معالم التنزیل در تفسیر. معجم الصحابة. الجعدیات در حدیث . وی به سال <span class=\"hlight\" dir=\"rtl\">٢١٣</span> هَ . ق . متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٣١٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180276, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمد کردی البیتوشی . مردی فاضل بود. به سال <span class=\"hlight\" dir=\"rtl\">١١٦١</span> هَ . ق . به بیتوش متولد و به بغداد مهاجرت کرد و به سال <span class=\"hlight\" dir=\"rtl\">١٢٢١</span> هَ . ق . به احساء درگذشت . از کتب اوست : شرح الفاکهی علی قطربن هشام . منظومه ٔ کفایة المعانی . (از الاعلام زرکلی ).<br /></font></div>'),
(180277, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمد معتز باﷲ ابن المتوکل بن المعتصم بن الرشید معروف به ابن المعتز. رجوع به ابن معتز ابوالعباس عبداﷲ و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180278, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمد ناشی الانباری . شاعری نیک و در عداد ابن رومی و بحتری است . و اصل او از انبار است . مدتی در بغداد ماند و سپس به مصر رفت و در آنجا به سال <span class=\"hlight\" dir=\"rtl\">٢٩٢</span> هَ . ق . درگذشت . در علم دین و ادب عالم بود و در علم منطق براعتی داشت کتابهائی تصنیف کرده است . (از الاعلام زرکلی ).<br /></font></div>'),
(180279, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمودبن مودودالموصلی ملقب به مجدالدین و مکنی به ابوالفضل . از بزرگان فقهای حنفی است .به سال <span class=\"hlight\" dir=\"rtl\">٥٩٩</span> هَ . ق . به موصل متولد شد و به دمشق و بغداد رفت و به سال <span class=\"hlight\" dir=\"rtl\">٦٨٣</span> هَ . ق . به بغداد درگذشت . او راست : الاختیار لتعالیل المختار. (از الاعلام زرکلی ).<br /></font></div>'),
(180280, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن مخارق بن سلیم بن حضیرةبن قیس معروف به النابغة الشیبانی . رجوع به نابغه ٔ شیبانی شود.<br /></font></div>'),
(180281, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن بریدةبن الحصیب الاسلمی، مکنی به ابوسهل . تولد او به سال <span class=\"hlight\" dir=\"rtl\">١٤</span> هَ . ق . است . وی قاضی و از رجال حدیث است . اصل وی از کوفه بود و در بصره سکونت جست . قضاوت مرو یافت و به سال <span class=\"hlight\" dir=\"rtl\">١١٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180282, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن جعفربن محمدبن درستویه . رجوع به ابن درستویه ابومحمد و نیز به الاعلام زرکلی و سیره ٔ عمربن عبدالعزیز ص <span class=\"hlight\" dir=\"rtl\">٤٣</span> و روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٤٨</span> شود.<br /></font></div>'),
(180283, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن جعفربن ابیطالب بن عبدالمطلب الهاشمی القرشی . وی صحابی است و به سال <span class=\"hlight\" dir=\"rtl\">١</span> هَ . ق . در حبشه متولد شد. او نخستین مولود مسلمانان در حبشه است . مردی کریم بود و شعراء وی را مدح میگفتند. در جنگ صفین از امیران لشکر علی (ع ) بود. به سال <span class=\"hlight\" dir=\"rtl\">٩٠</span>هَ . ق . درگذشت . (از الاعلام زرکلی ) (از عقدالفرید ص <span class=\"hlight\" dir=\"rtl\">١٤٤</span>) (از تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٩٠</span>).<br /></font></div>'),
(180284, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن جد عان التیمی القرشی . وی رسول اکرم (ص ) را قبل از بعثت درک کرد. (از الاعلام زرکلی ) (از عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٥</span>).<br /></font></div>'),
(180285, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن جحش بن ریاب بن یعمر الاسدی . وی صحابی و از کسانی است که در آغاز به اسلام گرویدند. به بلاد حبشه و مدینه مهاجرت کرد. وی از امراءسرایا بود. در جنگ احد به سال <span class=\"hlight\" dir=\"rtl\">٣</span> هَ . ق . کشته شد و با حمزه در یک قبر مدفون گردید. (از الاعلام زرکلی ).<br /></font></div>'),
(180286, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن جبیربن نعمان الانصاری .صحابی است در عقبه و بدر حاضر شد و در جنگ احد امیرتیراندازان بود و در همین جنگ به سال <span class=\"hlight\" dir=\"rtl\">٣</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی و تاریخ الخلفاء ص <span class=\"hlight\" dir=\"rtl\">٧٥</span>).<br /></font></div>'),
(180287, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن بشربن عمرو البغدادی . وی سید عبدالقیس و مردی شجاع و فصیح و صاحب رأی بود. قوم خود را برای جنگ با حجاج ثقفی در بصره فراهم آورد و مردم با او بیعت کردند. لیکن عبداﷲ در جنگ به سال <span class=\"hlight\" dir=\"rtl\">٧٥</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180288, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن بسطام الازدی . وی همراه جنید در نبرد با ترک در نزدیکی سمرقند شرکت کرد و در آن نبرد به سال <span class=\"hlight\" dir=\"rtl\">١١٢</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180289, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن بسر المازنی از بنی مازن بن منصور. وی صحابی و از کسانی است که به هر دو قبله نماز گزارد. او آخرین صحابی است که به سال <span class=\"hlight\" dir=\"rtl\">٨٨</span> هَ . ق . به شام درگذشت . در صحیحین <span class=\"hlight\" dir=\"rtl\">٥٠</span> حدیث از او روایت شده است . (از الاعلام زرکلی ).<br /></font></div>'),
(180290, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن جعفر الکثیری از سلاطین یمن بود و سیرتی پسندیده داشت . به سال <span class=\"hlight\" dir=\"rtl\">٩١٠</span> هَ . ق . در شحر درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180291, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن بری بن عبدالجبار المقدسی الاصل المصری، مکنی به ابومحمد و معروف به ابن بری . رجوع به ابن بری و ابومحمد عبداﷲ و رجوع به الاعلام زرکلی و روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٥٢</span> شود.<br /></font></div>'),
(180292, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن بدیل بن ورقاء الخزاعی . صحابی است و سیادت خزاعه را یافت . در یوم الفتح اسلام آورد و در جنگ صفین و طائف و تبوک شرکت کرد. در صفین با علی (ع ) بود و در این جنگ به سال <span class=\"hlight\" dir=\"rtl\">٣٧</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180293, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن ایوب المنصوربن یوسف المظفر. از بنی رسول است . وی چندی با الملک المجاهد به ستیزه برخاست و سرانجام مغلوب و زندانی شد و به سال <span class=\"hlight\" dir=\"rtl\">٧٣٤</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180294, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن اسید الجهنی . از اشراف کوفه بود. در جنگ با حسین بن علی شرکت جست . مختار ثقفی وی را به سال <span class=\"hlight\" dir=\"rtl\">٦٦</span> هَ . ق . بکشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180295, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن اسماعیل بن الشریف محمدبن علی الحسینی العلوی معروف به مولی عبداﷲ. از ملوک دولت اشراف علویین مراکش بود. بعد از مرگ برادرش احمد به سال <span class=\"hlight\" dir=\"rtl\">١١٤١</span> هَ . ق . باوی بیعت کردند. وی مردی جبار و با قساوت نفس بود. مردم مغرب چهار بار بر وی بشوریدند و او را خلع کردندو او دیگر بار بازگشت و تا سال <span class=\"hlight\" dir=\"rtl\">١١٧١</span> هَ . ق . که سال مرگ او است به امارت باقی بود. (از الاعلام زرکلی ).<br /></font></div>'),
(180296, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن اسعد التمیمی الیافعی المکی ملقب به عفیف الدین و مکنی به ابوالسعادات . رجوع به بابوالسعادات عبداﷲ بن اسعد و به روضات ص <span class=\"hlight\" dir=\"rtl\">٤٥٧</span> شود.<br /></font></div>'),
(180297, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن اسعدبن علی معروف به ابن الدهان . رجوع به ابن دهان ابوالفرج عبداﷲ و به الاعلام زرکلی شود.<br /></font></div>'),
(180298, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حسن بن احمد الانصاری القرطبی المالقی . از حفاظ حدیث و از کتاب و لغویان و شعراء بود. به سال <span class=\"hlight\" dir=\"rtl\">٥٥٦</span> هَ . ق . به مالقه متولد شد و در <span class=\"hlight\" dir=\"rtl\">٦١١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180299, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حکیم بن حزام الاسدی القرشی . صحابی و از شجعان بود. روز فتح مکه اسلام آوردو در جنگ جمل همراه عایشه پرچم دار قریش بود و در همان جنگ <span class=\"hlight\" dir=\"rtl\">٣٦</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180300, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حشرج بن اشهب بن ورد. والی و از بزرگان و شعرای قیس است . در زمان عبدالملک بن مروان ولایت بیشتر شهرهای خراسان و پاره ای از شهرهای فارس و کرمان را یافت . وی محمدبن مروان را مدح گفت صاحب اغانی قصیده ای از او نقل کرده است . در حدود سال <span class=\"hlight\" dir=\"rtl\">٩٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180301, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حسین یزدی . از علماء اصبهان است . از تألیفات او است : حاشیه ٔ بر شرح التلخیص در بلاغت . شرح تهذیب المنطق . شرح القواعد در فقه . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠١٥</span> هَ . ق . به اصبهان درگذشت . (از الاعلام زرکلی ) (از روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٣٦٣</span>).<br /></font></div>'),
(180302, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حسین تستری . ساکن اصفهان و صاحب مدرسه ٔ نقش جهان اصفهان است . وی یکی از علما و مجتهدان و مردی صالح و پرهیزکار بود. اصلش از شهر تُستر (شوشتر) است . به نجف رفت و مدتی نزد مقدس اردبیلی تلمذ کرد سپس به اصفهان رفت و مدتی در آنجا ماند هم آنگاه به مشهد رفت . در آن جا شاه عباس وی راملاقات کرد و مجدداً به اصفهان بازگشت . وی در بسیاری از کارها از جمله موقوفات چهارده معصوم و بناء مدرسه ٔ نقش جهان و مدرسه ٔ شیخ لطف اﷲ راهنمای شاه بود. وی را تألیفاتی است از جمله، التتیمم لشرح الشیخ نورالدین علی قواعد در هفت مجلد. به سال <span class=\"hlight\" dir=\"rtl\">١٠٢١</span> هَ . ق . به اصفهان درگذشت . (از روضات الجنات صص <span class=\"hlight\" dir=\"rtl\">٣٦٥</span> - <span class=\"hlight\" dir=\"rtl\">٣٦٨</span>).<br /></font></div>'),
(180303, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حسین بن مرعی بن ناصرالدین البغدادی . فقیه و متأدب و از اعیان عراق بود. به سال <span class=\"hlight\" dir=\"rtl\">١١٠٤</span> هَ . ق . به کرخ بغداد متولد شد به بلاد شام و حجاز مسافرت کرد و به سال <span class=\"hlight\" dir=\"rtl\">١١٧٤</span> هَ . ق . به بغداد درگذشت . از تألیفات اوست : انفع الرسائل فی شرح دلائل الخیرات . حاشیة علی المغنی . دیوان شعر و جز آن . (از الاعلام زرکلی ).<br /></font></div>'),
(180304, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حسین بن عبداﷲالعکبری البغدادی، مکنی به ابوالبقاء معروف به العکبری . رجوع به ابوالقباء محب الدین و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180305, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حسن صیدلانی . منجم معروف . در هندسه و احکام نجوم وحساب و جبر و مقابله بارع بود. از مؤلفات وی : شرح کتاب جبر محمدبن یونس خوارزمی در جمع و تفریق و ضرب و تقسیم است . تاریخ وفاتش به تحقیق معلوم نیست ولی چون ابن ندیم از وی یاد میکند قطعاً قبل از سالهای <span class=\"hlight\" dir=\"rtl\">٣٧٧</span> که هَ . ق . زمان تألیف الفهرست است بوده و از طرفی هم چون شرح کتاب خوارزمی را نموده بعد از سنین <span class=\"hlight\" dir=\"rtl\">٢٥٩</span>هَ . ق . است و در این مدت <span class=\"hlight\" dir=\"rtl\">١١٨</span> سال میانه ٔ ابن ندیم و خوارزمی حیات داشته و از طرفی دیگر میدانیم که اگربه زمان ابن ندیم نزدیک بود قطعاً سال وفاتش را بدست می آورد پس باید به خوارزمی نزدیکتر باشد از اینرو در آخر مائه ٔ سوم هجری میزیسته است . (از گاهنامه ).<br /></font></div>'),
(180306, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حسن بن حسن بن علی بن ابیطالب الهاشمی القرشی . تابعی است . نزد عمربن عبدالعزیز منزلتی داشت . وی به سال <span class=\"hlight\" dir=\"rtl\">٧٠</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٤٥</span> هَ. ق . در زندان منصور عباسی درگذشت . (از الاعلام زرکلی ) (از تاریخ الخلفاء ص <span class=\"hlight\" dir=\"rtl\">١٤٢</span>) (از تاریخ بیهق ص <span class=\"hlight\" dir=\"rtl\">١٤٢</span>).<br /></font></div>'),
(180307, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن اسحاق بن ابراهیم . از آل زیادبن ابیه و امیر یمن بود. به سال <span class=\"hlight\" dir=\"rtl\">٣٧١</span> هَ . ق . بعد از مرگ پدر ازجانب آل عباس ولایت یافت و در زمان امارت وی دولت آل زیاد در یمن به ضعف گرایید و بندگان آنان و والیان اطراف قیام کردند. امارت عبداﷲ <span class=\"hlight\" dir=\"rtl\">٤</span> سال دوام یافت و به سال <span class=\"hlight\" dir=\"rtl\">٣٧٥</span> هَ . ق . به زبید درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180308, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حسن بن نمی الثانی، از امراء مکه است که به سال <span class=\"hlight\" dir=\"rtl\">١٠٤٠</span> ولایت یافت .و به سال <span class=\"hlight\" dir=\"rtl\">١٠٤١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180309, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حجاج الازدی . از شجعان صدر اسلام است . به سال <span class=\"hlight\" dir=\"rtl\">٣٦</span>هَ . ق . در جنگ صفین کشته شد. (از الاعلام زرکلی ).<br /></font></div>'),
(180310, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حجاج بن محصن بن جندب المازنی الثعلبی الغطفانی، مکنی به ابوالاقرع . وی شاعر و از سواران نامبردار دولت اموی است و بر عبدالملک بن مروان خروج کرد و به نجدةبن عامر الحنفی و سپس به عبداﷲبن زبیر پیوست و چون ابن زبیر کشته شد ناشناس نزد عبدالملک رفت و شعر خود بر او خواند. عبدالملک وی را امان داد. شعر او نیک و اخبار او بسیار داشت . وی در حدود سال <span class=\"hlight\" dir=\"rtl\">٩٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180311, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حجاج . رجوع به ابن یاسمین شود.<br /></font></div>'),
(180312, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حارث بن نوفل الهاشمی القرشی . از اشراف قوم خویش و مردی پرهیزکار و ظاهر الصلاح بود. ابن زبیر وی را ولایت بصره داد و چون فتنه ٔ ابن اشعث پدید شد. به عمان گریخت و به سال <span class=\"hlight\" dir=\"rtl\">٨٤</span> هَ . ق . بدانجا درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180313, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حارث بن قیس السهمی القرشی . شاعر و صحابی است . وی را به خاطر شعری که از جمله ٔ آن . «اذا انالم ابرق ...» آورده بود مبرق میگفتند. به سال <span class=\"hlight\" dir=\"rtl\">١١</span> هَ . ق . در یمامه و به قولی در طائف کشته شد. (از الاعلام زرکلی ).<br /></font></div>'),
(180314, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حارث بن جزء الزبیدی صحابی است . در بصره اقامت کرد. وی قبل از مرگش نابینا شد و به سال <span class=\"hlight\" dir=\"rtl\">٨٦</span> هَ . ق . به مصر درگذشت . وی آخرین کس از صحابه است که به مصر درگذشتند. مصریان از وی احادیثی روایت کنند. (از الاعلام زرکلی ).<br /></font></div>'),
(180315, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن ابراهیم الاصیلی نسب وی باصیلة (شهری به مغرب ) است . مردی فاضل بود و به سال <span class=\"hlight\" dir=\"rtl\">٣٩٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180316, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمدبن اسماعیل الرسولی . وی از ملوک دولت رسولیه یمن است که به سال <span class=\"hlight\" dir=\"rtl\">٨٢٧</span> هَ . ق . بعد از مرگ پدر به امارت رسید. وی به سال <span class=\"hlight\" dir=\"rtl\">٨٣٠</span> هَ . ق . به صنعا درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180317, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن ابی قحافه عثمان بن عمروبن کعب التیمی القرشی، مکنی به ابوبکر. رجوع به ابوبکربن ابی قحافه شود.<br /></font></div>'),
(180318, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن ابی فرج . رجوع به ابن مارستانیه ابوبکر عبداﷲ شود.<br /></font></div>'),
(180319, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن ابی زید عبدالرحمان قیروانی، مکنی به ابومحمد معروف به ابن ابی زید. رجوع به ابن ابی زید ابومحمد شود.<br /></font></div>'),
(180320, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن ابی حصین الازدی . صحابی و از فرسان عرب در صدر اسلام بود. وی به سال <span class=\"hlight\" dir=\"rtl\">٣٦</span> هَ. ق . در جنگ صفین به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180321, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن ابی بکر الصدیق . رجوع به عبداﷲبن عبداﷲبن عثمان التیمی شود.<br /></font></div>'),
(180322, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن ابی بکربن عثمان التیمی القرشی . صحابی بود و در وقعه ٔ طائف شرکت داشت و تیری بدو رسید که در اثر همان به سال <span class=\"hlight\" dir=\"rtl\">١١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180323, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْلاه ]</font></b> (اِخ ) ابن ابی بکربن عبداﷲبن عبدالرحمان باشمیلة. از افاضل یمن بود و شعر میگفت . او را دیوانی است .وی به سال <span class=\"hlight\" dir=\"rtl\">٩١٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180324, 'عبدا', '<span class=\"hlight\">عبدا.</span><font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمدبن امیر اسحاق بن المقتدر العباسی، مکنی به جعفر و ملقب به القائم بامراﷲ.رجوع به قائم بن القادر و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180325, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن ابراهیم بن عبداﷲ الخبری . از علمای عربیت و فرائض و حساب بود. او راست : شرح الحماسة. شرح دیوان البحتری .وی به سال <span class=\"hlight\" dir=\"rtl\">٤٧٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180326, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن ابراهیم بن اغلب التمیمی . امیر افریقا و از اغالبه بود.امارت از آن او بود و خطبه به نام بنی عباس میخواندند. و به سال <span class=\"hlight\" dir=\"rtl\">١٩٦</span> هَ . ق . پس از پدر امارت یافت و در عهد وی در قیروان و حوالی آن ایام سکون و آرامش بود.وی به سال <span class=\"hlight\" dir=\"rtl\">٢٠١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180327, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن ابراهیم بن احمد الاغلبی التیمی . وی امیر تونس و قیروان و مردی ادیب، شجاع و عاقل بود. پس از مرگ پدر امارت یافت و به سال <span class=\"hlight\" dir=\"rtl\">٢٩٠</span> هَ . ق . به تدبیر فرزندش زیادة اﷲ بدست سه تن از صقالبه به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180328, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن اباض المقاعسی المری التمیمی . از بنی مرةبن عبیدبن مقاعس و رئیس فرقه ٔ اباضیه و معاصر معاویه بود. و تا اواخر خلافت عبدالملک بن مروان میزیست . شماخی او را از تابعیان داند و گوید: وی عبدالملک بن مروان را اندرز میداد. در مورد تاریخ تولد و وفات او اختلاف است، برخی گویند وی ازابناء نیمه ٔ دوم سده ٔ اول هجرت بعد از جابربن یزید است و برخی گویند: نشأت وی در زمان معاویةبن ابی سفیان است و تا زمان عبدالملک بن مروان میزیست . و برخی وفات او را <span class=\"hlight\" dir=\"rtl\">١٣٠</span> هَ . ق . نوشته اند. (از الاعلام زرکلی ).<br /></font></div>'),
(180329, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لا ]</font></b> (اِخ ) دهی است از دهستان مؤمن آباد بخش درمیان شهرستان بیرجند. واقع در <span class=\"hlight\" dir=\"rtl\">٣٩</span>هزارگزی شمال باختری درمیان و <span class=\"hlight\" dir=\"rtl\">٥</span>هزارگزی شمال شوسه ٔ عمومی بیرجند به شاه رخت . ناحیه ای است واقع در دامنه، معتدل و <span class=\"hlight\" dir=\"rtl\">١٤</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولاتش غلات است . اهالی به کشاورزی اشتغال دارندراه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180330, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) دهی است از دهستان پشتکوه بخش نیر شهرستان یزد. واقع در <span class=\"hlight\" dir=\"rtl\">٤٢</span>هزارگزی جنوب باختر نیر و <span class=\"hlight\" dir=\"rtl\">٣٣</span>هزارگزی جنوب خاوری راه فرعی نیربه ابرقو. ناحیه ای است کوهستانی هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٥١٤</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولاتش : غلات، ذرت، حبوبات، انجیر و بادام است . اهالی به کشاورزی اشتغال دارند و شغل زنان کرباس بافی است . راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(180331, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمدبن محمودالکعبی، مکنی به ابوالقاسم و معروف به کعبی وی از بنی کعب و از ائمه ٔ معتزله است و رئیس طائفه ٔ کعبیه بود. او راست : آراء و مقالاتی در کلام . اصل او از بلخ است و به سال <span class=\"hlight\" dir=\"rtl\">٣١٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180332, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن ارقم بن عبد یغوث القرشی الزهری . صحابی و از کتاب و خال پیغمبر (ص ) است . در فتح مکه اسلام آورد و رسول (ص ) و ابوبکر و عمر وی را به کتابت گماردند سپس در باقی خلافت عمر و دو سال از خلافت عثمان متصدی بیت المال بود و استعفا کرد. عثمان وی را <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزار درهم جایزت داد نپذیرفت . وی به سال <span class=\"hlight\" dir=\"rtl\">٤٤</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180333, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن ادریس الاودی الکوفی . وی از اعلام حفاظ حدیث و مردی فاضل و عابد بود و در آنچه روایت کند حجت است . رشید خواست وی را قضاوت دهد نپذیرفت و صله ٔ او را رد کرد. مذهب او در فتوی، مذهب مردم مدینه است . وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٠</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٩٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180334, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمد مالقی ملقب به ضیاءالدین و معروف به ابن البیطار. رجوع به ابن بیطار و نیز به الاعلام زرکلی و روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٥١</span> شود.<br /></font></div>'),
(180335, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمد فاکهی المکی . رجوع به فاکهی عبداﷲبن احمد شود.<br /></font></div>'),
(180336, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b>(اِخ ) ابن احمدالمروزی القفال . رجوع به قفال شود.<br /></font></div>'),
(180337, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمدالاصفهانی معروف به ابن لبان . رجوع به عبداﷲبن محمد شود.<br /></font></div>'),
(180338, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمدبن موسی بن زیاد العسکری الاهوازی الجوالیقی معروف به عبیدان . از علماء حدیث است .از تألیفات اوست : الفوائد. وی به سال <span class=\"hlight\" dir=\"rtl\">٢١٦</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">٣٠٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180339, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمدبن محمود النسفی . وی فقیه و مفسری حنفی مذهب و از مردم ایذج (از حوالی اصفهان ) بود. از تألیفات اوست : المدارک در تفسیر قرآن . کنز الدقائق در اصول فقه . المنار در اصول . الوافی درفروع . الکافی فی شرح الوافی . المستصفی در فقه . به سال <span class=\"hlight\" dir=\"rtl\">٧١٠</span> هَ . ق . در ایذج درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180340, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حمدان بن حمدون التغلبی العدوی، مکنی به ابوالهیجاء. رجوع به ابوالهیجاء و عبداﷲبن حمدان و نیز به الاعلام زرکلی و مجمل التواریخ ص <span class=\"hlight\" dir=\"rtl\">٣٧٤</span> شود.<br /></font></div>'),
(180341, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمدبن محمدبن قدامة المقدسی ثم الدمشقی الحنبلی، مکنی به ابومحمد و ملقب به موفق الدین و معروف به ابن قدامه . رجوع به ابن قدامه موفق الدین و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180342, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمدبن محمدبن حنبل الشیبانی البغدادی حافظ حدیث و از مردم بغداد بود. از کتابهای او است : الزوائد علی کتاب الزهدلابیه . زوائد المسند.وی به سال <span class=\"hlight\" dir=\"rtl\">٢٩٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180343, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمدبن علی بن مخرمة الحمیری الشیبانی الهجرانی الحضرمی العدنی . فقیه و مدرس و مفتی عدن بوده . به سال <span class=\"hlight\" dir=\"rtl\">٨٠٣</span> به الهجرین متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٩٠٣</span> هَ . ق . به عدن درگذشت . او را تصانیفی است از جمله : شرح الملحمة للحریری . رسائل فی علم الهندسة. (از الاعلام زرکلی ).<br /></font></div>'),
(180344, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمدبن سلیمان بن ابراهیم بن بردة الفزاری . یگانه ٔ جهان بود در علم و ورع . و از بنی فزاره یکی از قبائل عرب است . وی هشتاد پاره تألیف دارد. قضاء پارس و کرمان یافت . (از فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١١٧</span>).<br /></font></div>'),
(180345, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمدبن خشاب، مکنی به ابومحمد. رجوع به خشاب و الاعلام زرکلی شود.<br /></font></div>'),
(180346, 'عبدا', '<span class=\"hlight\">عبدا.</span><font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمدبن حسین الشاماتی، مکنی به ابوالحسین . مردی فاضل بود. از تألیفات اوست : شرح دیوان المتنبی . شرح الحماسه . شرح امثال ابی عبید.وی به سال <span class=\"hlight\" dir=\"rtl\">٤٧٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180347, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمدبن بشیربن ذکوان البهرانی . از بزرگان قراء بود. به سال <span class=\"hlight\" dir=\"rtl\">١٧٣</span> هَ . ق . متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٣٤٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180348, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عبدالرحمان بن ابی بکر بافضل الحضرمی السعدی المذحجی . فقیه و رئیس فقیهان بلاد خود بود. از تألیفات او است : المقدمة الحضرمیة فی فقه الشافعیه . الحجج القواطع فی الواصل و القاطع. رسالة فی علم الفلک و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">٨٥٠</span> هَ . ق . متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٩١٨</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180349, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عبدالظاهربن نشوان الجذامی ملقب به محی الدین و معروف به ابن عبدالظاهر. رجوع به عبدالظاهر محی الدین ابوالفضل و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180350, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عبدالرزاق بن عبدالعظیم العثمانی . فقیه مالکی است . از تألیفات او است : سلاح الایمان فی الصلاة و تلاوة القرآن . بدایة السلوک «منظومه است ». تنبیه الغافل الی مرتبة العاقل . وی به سال <span class=\"hlight\" dir=\"rtl\">٩٤٥</span> هَ . ق . متولد شدو در سال <span class=\"hlight\" dir=\"rtl\">١٠٢٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180351, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b>(اِخ ) ابن عبدالرحمان ناصر الاموی معروف به ابن الناصر. امیر و از نجباء خلفاء اندلس و از دوستداران علم و علماء بود. او را تصنیف ها است از جمله : کتاب العلیل و القتیل که اخبار بنی عباس را تا خلافت الراضی بن المقتدر در آن فراهم کرده است . المسکتة در فضائل بقی بن مخلد. پدرش وی را به توطئه بر خلع خود متهم کرد و به سال <span class=\"hlight\" dir=\"rtl\">٣٣٩</span> هَ . ق . او را بکشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180352, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عبدالرحمان ابی زید النفراوی القیروانی، مکنی به ابومحمد معروف به ابن ابی زید. رجوع به ابن ابی زید ابومحمد عبداﷲ و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180353, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ )ابن عبدالرحمان بن معاویةبن هشام الاموی البلنسی . بعداز مرگ پدر خود زمام کار اندلس را بدست گرفت و سپس به سال <span class=\"hlight\" dir=\"rtl\">١٧١</span> هَ . ق . برادر وی هشام که ولایت عدن داشت از مارده بیامد. عبداﷲ با وی بیعت کرد هشام به سال <span class=\"hlight\" dir=\"rtl\">١٨٠</span> هَ . ق . درگذشت و فرزند او حکم ولایت یافت عبداﷲ به قصبه ٔ بلنسیه رفت و بر حکم عاصی شد، آنگاه به اطاعت او درآمد چون حکم فرزند عبدالرحمان را ولایت عهد ساخت عبداﷲ لشکری فراهم کرد تا بر او خروج کند، لیکن بیمار شد و فلج گشت و لشکر او پراکنده شدند و عبداﷲ در<span class=\"hlight\" dir=\"rtl\">٢٠٨</span> هَ . ق . در بلنسیه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180354, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عبدالرحمان بن معاویةبن حدیج بن التجیبی . به سال <span class=\"hlight\" dir=\"rtl\">١٥٢</span> هَ . ق . منصور عباسی وی را ولایت داد. او نخستین کس است که با رداء سیاه خطبه خواند. وی تا پایان عمر خویش در ولایت باقی بود و به سال <span class=\"hlight\" dir=\"rtl\">١٥٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180355, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاْ ]</font></b> (اِخ ) ابن عبدالرحمان بن فضل بن بهرام التمیمی الدارمی السمرقندی، مکنی به ابومحمد. رجوع به ابومحمدبن عبداﷲبن عبدالرحمان و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180356, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عبدالرحمان بن عقیل القرشی الهاشمی العقیلی ملقب به بهاءالدین . رجوع به ابن ابومحمد بهاءالدین و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180357, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عبدالعزیزبن محمد البکری الاندلسی، مکنی به ابوعبید بکری . رجوع به ابوعبید بکری عبداﷲ... و به الاعلام زرکلی شود.<br /></font></div>'),
(180358, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عبدالحکم بن اعین بن لیث بن رافع معروف به ابن عبدالحکم . رجوع به ابن عبدالحکم ابومحمد عبداﷲ و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180359, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عباس بن عبدالمطلب القرشی الهاشمی . رجوع به ابن عباس عبداﷲبن عباس و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180360, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عامر یحصبی الشامی، مکنی به ابوعمران . رجوع به ابن عامر، مکنی به ابوعمران و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180361, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عامربن کریزبن ربیعة الاموی، مکنی به ابوعبدالرحمان . به سال <span class=\"hlight\" dir=\"rtl\">٤</span> هَ . ق . به مکه متولد شد. در خلافت عثمان ولایت بصره یافت و لشکری به سیستان فرستاد و داور و دارابجرد و مروالروز و سرخس و ابرشهر طوس و طخارستان و نیشابور و ابیورد و بلخ و طالقان و فاریاب ورساتیق هرات و آمل و بست و کابل را فتح کرد. وی به سال <span class=\"hlight\" dir=\"rtl\">٥٩</span> هَ . ق . به بصره درگذشت . عبداﷲ مردی شجاع و سخاوتمند بود. عمران و آبادی را دوست میداشت . بسیاری از خانه های بصره را خرید و ویران ساخت و راه عمومی کرد. وی کسی است که در عرفه حوض ها ساخت و چشمه ها بدانجا جاری ساخت و مردم را آب داد. (از الاعلام زرکلی ).<br /></font></div>'),
(180362, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َدُل ْ لاه ]</font></b> (اِخ ) ابن طیب، مکنی به ابوالفرج . رجوع به ابن الطیب ابوالفرج و و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180363, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن طفیل الدوسی از فضلاء صحابه و قدیم الاسلام است . به حبشه مهاجرت کرد و در فتوحات ابوبکر شرکت داشت . به سال <span class=\"hlight\" dir=\"rtl\">١٣</span> هَ .ق . در واقعه ٔ اجنادین کشته شد. (از الاعلام زرکلی ).<br /></font></div>'),
(180364, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن طاهربن الحسین بن مصعب الخزاعی . امیر خراسان و از مشهورترین والیان عصر عباسی است . وی مدتی ولایت شام یافت سپس به سال <span class=\"hlight\" dir=\"rtl\">٢١١</span> هَ . ق . به مصر رفت و مدت یک سال بدانجابماند آنگاه به دینور رسید و مأمون او را ولایت خراسان داد و عبداﷲ از خود کفایتی نشان داد. بدان جهت طبرستان و کرمان و ری و حوالی آنها ضمیمه ٔ حکمرانی وی شد. تولد عبداﷲ به سال <span class=\"hlight\" dir=\"rtl\">١٨٢</span> هَ . ق . بود و به سال <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> هَ . ق . به نیشابور درگذشت . ابن اثیر نویسد: عبداﷲطاهر مردی بسیار بخشنده و عالم و باتجربه بود و شعراء برای او مرثیه گفته اند. ابن خلکان نویسد: عبداﷲ مردی بزرگ و عالی همت و مورد اعتماد مأمون بود. ذهبی گوید عبداﷲ از بزرگان ملوک است . (از الاعلام زرکلی ).<br /></font></div>'),
(180365, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عجلان بن عبدالاجب بن عامر النهدی . شاعر جاهلی است . شعر وی عذوبت خاصی دارد و در حدود سال <span class=\"hlight\" dir=\"rtl\">٥٠</span> قبل از هجرت درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180366, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن علی بن جارود النشابوری، مکنی به ابومحمد معروف به ابن الجارود. مجاور مکة و از حفاظ حدیث بود. او راست : المنتقی فی الاحکام .وی به سال <span class=\"hlight\" dir=\"rtl\">٣٠٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180367, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن علی معروف بشیخ سدید. شیخ طب دیار مصر بود. به خدمت العاضد درآمد و عمری دراز یافت .وی به سال <span class=\"hlight\" dir=\"rtl\">٥٩٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180368, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن علوی بن احمد المهاجربن عیسی الحسینی الحضرمی . معروف به حداد فاضل و از مردم تریم (حضرموت ) است .از تألیفات اوست : المعاونة و المؤازرة اللراغبین فی طریق الاخرة. اتحاف السائل باجوبة المسائل . النصائح الدینیة و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٤٤</span> هَ . ق . متولد شدو به سال <span class=\"hlight\" dir=\"rtl\">١١٣٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180369, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن علقمة الاسلمی . آخرین صحابی است که به سال <span class=\"hlight\" dir=\"rtl\">٨٧</span> هَ . ق . به کوفه درگذشت . در صحیحین <span class=\"hlight\" dir=\"rtl\">٩٥</span> حدیث از وی روایت شده است . (از الاعلام زرکلی ).<br /></font></div>'),
(180370, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْلاه ]</font></b> (اِخ ) ابن عکیم . رجوع به ابومعبد عبداﷲ شود.<br /></font></div>'),
(180371, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عزیزبن الکنانی . تابعی است و مقامی رفیع داردو در زمره ٔ توابین است . عبداﷲ از مردم کوفه بود و در جنگهای کوفیان با بنی امیه و بعضی وقایع دیگر شرکت جست . به سال <span class=\"hlight\" dir=\"rtl\">٦٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180372, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عزبن نصراﷲ انصاری الوزان ملقب به موفق الدین . فاضل بود و در طب معرفتی داشت . مقصوره ٔ ابن درید را تخمیس کرده است . مدتی در بعلبک اقامت کرد و به سال <span class=\"hlight\" dir=\"rtl\">٦٧٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180373, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عروة الهروی . از حفاظ حدیث است . او راست : کتاب الاقضیة.وی به سال <span class=\"hlight\" dir=\"rtl\">٣١١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180374, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن طاوس بن کیسان الهمدانی . از عابدان یمن و فقهاء مشهور و از رجال حدیث و ثقه است .وی به سال <span class=\"hlight\" dir=\"rtl\">١٣٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180375, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b>(اِخ ) ابن عثمان بن جبلة الازدی العتکی ... حافظ حدیث و ثقه بود. از جانب عبداﷲبن طاهر قضاوت جوزخان بدو داده شد و او نپذیرفت . وی به سال <span class=\"hlight\" dir=\"rtl\">١٤٥</span> هَ . ق . متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٢٢١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180376, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ )ابن عبیداﷲبن ابی ملیکةبن التیمی المکی . قاضی و از رجال حدیث و ثقه است و از جانب زبیر قضاوت طائف یافت .وی به سال <span class=\"hlight\" dir=\"rtl\">١١٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180377, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عبیداﷲ، مکنی به ابوالسری و ملقب به ابن الدمینه . از بنی عامربن تیم اﷲ از خثعم است و دمینه مادر او است . وی شاعری بدوی است بیشتر اشعارش غزل و نسیب و فخر است . او را دیوان شعری است . وی در حدود سال <span class=\"hlight\" dir=\"rtl\">١٤٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(180378, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عبد عمروبن صیفی بن نعمان معروف به ابن حنظلة. از مردم اوس و از اعلام تابعین است . هنوزمتولد نشده بود که پدرش کشته شد. چون در وقعه ٔ یوم حرة مردم مدینه شورش کردند و عمال بنی امیه را خارج کردند، با او به امیری بیعت کردند و پیمان مرگ بستند.عبداﷲ با لشکر یزیدبن معاویه جنگی سخت کرد و سرانجام سپاهیان بنی امیه وارد مدینه شده و ابن حنظله و بسیاری از اصحاب وی را بکشتند. تولد او به سال <span class=\"hlight\" dir=\"rtl\">٢</span> هَ . ق . بود و در سال <span class=\"hlight\" dir=\"rtl\">٦٣</span> به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180379, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عبدالواحد احمدبن محمدبن عبدالرحمان بن معاویةبن حدیج . یکی از والیان اسکندریه است که در فتنه ٔ اندلسیان و صوفیان به سال <span class=\"hlight\" dir=\"rtl\">١٩٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180380, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عبدالمطلب بن هاشم الهاشمی القرشی ملقب به الذبیح پدر رسول (ص ) است . به سال <span class=\"hlight\" dir=\"rtl\">٨١</span> قبل از هجرت مدینه متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٥٣</span> قبل از هجرت درگذشت . وی کوچکترین پسران عبدالمطلب بود پدرش نذر کرد که هرگاه خدا ده فرزند به او عطا کند و در زندگی او بحد شباب برسند یکی از آنان را در مقابل کعبه قربانی کند و چون حاجتش برآمد فرزندان را در مقابل هبل که بزرگترین بتان بود برده و قرعه کشید به نام عبداﷲ آمد و عبدالمطلب وی را بغایت دوست داشت بدین جهت یکصد شتر بجای او فدیه کرد بدین جهت معروف به الذبیح شد زوجه ٔ وی آمنه بنت وهب مادر حضرت محمد بود. عبداﷲ در زمانی که آمنه آبستن بود به قصد تجارت به غزه رفت و در مراجعت چون به مدینه رسید مریض شده و درگذشت . و بعضی گویند به الابواء (بین مکه و مدینه ) درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180381, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن عبدالمدان الحارثی . صحابی و از سادات عرب یمن است و از جانب علی (ع ) ولایت یمن یافت و در جنگی که با لشکریان معاویه به سرکردگی بسربن ارطاة کرد به سال <span class=\"hlight\" dir=\"rtl\">٤٠</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180382, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن ذکوان القرشی المدنی محدث است . سفیان وی را در حدیث امیرالمؤمنین نامید. وی در حدیث ثقه بود. لیث گفت سیصد تن دنبال ابوالزناد دیدم که از او فقه و علم و شعر و صرف فرامیگرفتند. وی به سال <span class=\"hlight\" dir=\"rtl\">١٣١</span> هَ . ق . به مرگ مفاجاةدرگذشت . (از الاعلام زرکلی ) (از تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">٧٩٩</span>).<br /></font></div>'),
(180383, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن سعدبن ابی جمرة الازدی الاندلسی . از علماء حدیث است . از تألیفات او است : جمع النهایة مختصر صحیح بخاری که به مختصر ابن ابی جمرة مشهور است . بهجة النفوس در شرح مختصر المراثی الحسان، در حدیث . وی به سال <span class=\"hlight\" dir=\"rtl\">٦٩٥</span> هَ . ق . به مصر درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180384, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن زیدبن عمرو الجرمی . از مردم بصره و عالم به قضاء و احکام و از رجال حدیث و ثقه بود. وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٤</span> هَ . ق . به شام درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180385, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ )ابن زیدبن عاصم بن کعب البخاری الانصاری . صحابی و از مردم مدینه است . مردی شجاع بود مسیلمة الکذاب را بکشت . او را در الصحیحین <span class=\"hlight\" dir=\"rtl\">٤٨</span> حدیث است . وی به سال <span class=\"hlight\" dir=\"rtl\">٦٣</span> هَ . ق . در وقعه ٔ حرة به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180386, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن زبیر الحمیدی معروف به الحمیدی . از ائمه ٔ حدیث و از مردم مکه بود. وی شیخ بخاری و رئیس اصحاب ابن عیینة است . او را مسندی است . به سال <span class=\"hlight\" dir=\"rtl\">٢١٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180387, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن زبیربن العوام القرشی الاسدی . رجوع به ابن زبیر ابوبکر عبداﷲ و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180388, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن زبعری بن قیس السهمی القرشی، مکنی به ابوسعد. رجوع به ابن زبعری و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180389, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْلاه ]</font></b> (اِخ ) ابن رؤبةبن لبیدبن صخرالتمیمی . از شعراء جاهلی است . در جاهلیت متولد شد سپس اسلام آورد و تازمان خلافت ولیدبن عبدالملک بزیست . سرانجام زمین گیر شد و به سال <span class=\"hlight\" dir=\"rtl\">٩٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180390, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ )ابن رواحةبن ثعلبة. از مردم خزرج و صحابی و در شمارامراء و شعراء راجزین است . در جاهلیت کتابت میکرد. وی در بیعت عقبه با هفتاد تن از انصار حاضر بود. در جنگ بدر و احد و خندق و حدیبیة حضور یافت . رسول (ص ) در یکی از غزوات وی را در مدینه جانشین خود فرمود. وی در وقعه ٔ مؤتة یکی از امیران بود و به سال <span class=\"hlight\" dir=\"rtl\">٨</span> هَ .ق . در همان واقعه به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180391, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن سعدبن ابی سرح . از بنی عامر و فاتح افریقاست و در لشکری که حسن و حسین فرزندان علی (ع ) و عبداﷲبن عباس و عقبةبن نافع در آن بودند به افریقا رفت و طرابلس غرب تا طنجه را فتح کرد و سراسر افریقا را تحت فرمان آورد و به سال <span class=\"hlight\" dir=\"rtl\">٣٧</span> هَ . ق . به مرگ ناگهانی در عسقلان درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180392, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن داود الزبیری . فقیه و از مردم زبیر بود. از تألیفات او است : الصواعق والرعود فی الرد علی بن سعود. وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٢٥</span> هَ . ق .درگذشت . (از الاعلام زرکلی ) (از عقدالفرید ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">٨٦</span>).<br /></font></div>'),
(180393, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن دارم بن مالک بن حنظلة. از تمیم از عدنان جد جاهلی است . (از الاعلام زرکلی ) (از عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤١</span>).<br /></font></div>'),
(180394, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن خلیدبن سعد، مکنی به ابوالعمیثل . رجوع به ابوالعمیثل عبداﷲبن خلید و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180395, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َدُل ْ لاه ]</font></b> (اِخ ) ابن خالد، مکنی به ابوهفان المهزمی (یا محضرمی ). رجوع به ابوهفان المهزمی عبداﷲ شود.<br /></font></div>'),
(180396, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن خازم بن اسمأبن الصلت السلمی البصری، مکنی به ابوصالح . از جانب بنی امیه امارت خراسان یافت و چون ابن زبیر قیام کرد عبداﷲ خازم اطاعت خویش را بدو نوشت و او وی را همچنان به حکومت خراسان بداشت . عبدالملک وی را به اطاعت خویش خواند، و او نپذیرفت . چون مصعب کشته شد عبدالملک سر وی را نزد ابن خازم فرستاد. او سر را بشست و بر آن نماز گزارد، سپس مردم خراسان بر او بشوریدند و او را بکشتند و سر او را نزد عبدالملک فرستادند. قتل وی به سال <span class=\"hlight\" dir=\"rtl\">٧٢</span> هَ . ق . بود و مدت <span class=\"hlight\" dir=\"rtl\">١٠</span> سال امارت کرد. (از الاعلام زرکلی ).<br /></font></div>'),
(180397, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حیدربن ابوالقاسم قزوینی . فقیه و از رجال حدیث است . به سال <span class=\"hlight\" dir=\"rtl\">٥٨٢</span> هَ . ق . به همدان درگذشت . از تألیفات اوست : کتاب مشیخة که در آن ترجمه ٔ شیوخ خود را که از آنان حدیث شنیده است و یا بدو اجازت داده اند آورده است . (از الاعلام زرکلی ).<br /></font></div>'),
(180398, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن حمزةبن سلیمان بن حمزة. یکی از ائمه ٔ یمن بود. در زمان ملک مسعود بر صنعاء و ذمار استیلا یافت و به سال <span class=\"hlight\" dir=\"rtl\">٦١٢</span> هَ . ق . با ملک مسعود نبرد کرد و به سال <span class=\"hlight\" dir=\"rtl\">٦١٤</span> هَ . ق . در کوکبان درگذشت . وی از علماء زیدی است و در مذهب تصنیفاتی دارد. او را دیوان شعری است . (از الاعلام زرکلی ).<br /></font></div>'),
(180399, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن سلیمان بن اشعث الازدی السجستانی معروف به ابن ابی داود. رجوع به ابن ابی داود ابوبکربن سلیمان و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180400, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن صفوان الجمحی . در روزگار منصور عباسی امارت مدینه یافت و به سال <span class=\"hlight\" dir=\"rtl\">١٦٠</span> هَ . ق . به مدینه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180401, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن صفوان بن امیةبن خلف . مردی شجاع و از اصحاب ابن زبیر بود و حجاج بن یوسف با وی جنگ کرد. وی به سال <span class=\"hlight\" dir=\"rtl\">٧٣</span> هَ . ق . در روزی که ابن زبیر به قتل رسید کشته شد. حجاج سر او را نزد عبدالملک بن مروان فرستاد. (از الاعلام زرکلی ).<br /></font></div>'),
(180402, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن صالح بن جمعةبن شعبان السماهیجی البحرانی . از فقها و ادبا بود. از تألیفات او است . جواهر البحرین فی احکام الثقلین . الصحیفة العلویة. مصائب الشهداء و مناقب السعداء در پنج مجلد. ریاض الجنان المشحون باللؤلؤ والمرجان، که به روش و سبک کشکول شیخ بهایی نوشته . کتاب الخطب . منیة الممارسین فی اجوبة الشیخ یاسین . المسائل الحسینیة و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">١١٣٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180403, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن شهاب حسین یزدی الشهابادی . رجوع به عبداﷲبن حسین یزدی شود.<br /></font></div>'),
(180404, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن شداد. رجوع به ابن شداد عزالدین ابوعبداﷲ و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180405, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن سلیمان بن وهب الکاتب .از وزراء عباسی و از بزرگان آن دولت بود. <span class=\"hlight\" dir=\"rtl\">١٠</span> سال وزارت المعتضد باﷲ را یافت . تولد او به سال <span class=\"hlight\" dir=\"rtl\">٢٢٦</span> هَ . ق . است و در <span class=\"hlight\" dir=\"rtl\">٢٨٨</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180406, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن سلیمان بن داود الاندی . قاضی، فقیه، اصولی و حافظ حدیث و مایل به اجتهاد بود. تولد او به سال <span class=\"hlight\" dir=\"rtl\">٥٤٩</span> در «انده » از بلاد اندلس بود. قضاوت اشبیلیه و قرطبه و مرسیه و دیگر شهرها یافت و کتابها تصنیف کرد. به سال <span class=\"hlight\" dir=\"rtl\">٦١٢</span> هَ . ق . به غرناطه درگذشت . (از الاعلام زرکلی ) (از روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٥٣</span>).<br /></font></div>'),
(180407, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن سلیمان بن داود، مکنی به ابومحمد و معروف به ابن حوطاﷲ. رجوع به ابن حوطاﷲ ابومحمد عبداﷲ شود.<br /></font></div>'),
(180408, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن علی بن عبداﷲبن خلف اللخمی المری الرشاطی معروف به رشاطی . از علماء حدیث و از مردم (مریه ) اندلس است . او راست : کتاب الاعلام بما فی المؤتلف و المختلف اللدارقطنی من الابهام .وی به سال <span class=\"hlight\" dir=\"rtl\">٥٤٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180409, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن سلام بن الحارث الاسرائیلی . صحابی است، هنگامی که حضرت رسول به مدینه رفت اسلام آورد و در شأن اوست آیه ٔ «... شهد شاهد من بنی اسرائیل » (قرآن <span class=\"hlight\" dir=\"rtl\">١٠/٤٦</span>). و آیه ٔ «من عنده علم الکتاب ». (قرآن <span class=\"hlight\" dir=\"rtl\">٤٣/١٣</span>). وی با عمر در فتح بیت المقدس و جابیه حاضر بود و به سال <span class=\"hlight\" dir=\"rtl\">٤٣</span> هَ . ق . بمدینه درگذشت . از او در الصحیحین <span class=\"hlight\" dir=\"rtl\">٢٥</span> حدیث است . (از الاعلام زرکلی ).<br /></font></div>'),
(180410, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن سعیدبن مهدی الخوافی، مکنی به ابومنصور خوافی . وی کاتب و فرضی ومحاسب بود و او را نظمی است . از تألیفات اوست : خلق الانسان . رجمة العفریت، که رد بر معری است . وی به سال <span class=\"hlight\" dir=\"rtl\">٤٨٠</span> هَ . ق . به بغداد درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180411, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن سعیدبن عبداﷲ باقشیر. فقیه، متأدب و از علماء مکه بود. او را نظمی است . همه ٔ کتابهای او شروح وحواشی و مختصرات است، از جمله : اختصار نظم عقیدة اللقانی . اختصار تصریف الزنجانی . نظم الحکم و شرح آن . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٧٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180412, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن سعیدبن سعدبن زیدبن محسن . از اشراف مکه بود بعد از مرگ پدر به سال <span class=\"hlight\" dir=\"rtl\">١١٢٩</span> هَ . ق . امارت مکه یافت . مدت یکسال و سه ماه حکومت کرد سپس او را عزل کردند و به یمن رفت و تا سال <span class=\"hlight\" dir=\"rtl\">١١٣٦</span> هَ . ق . بدانجا بود دیگر بار به امارت مکه رسیدو به سال <span class=\"hlight\" dir=\"rtl\">١١٤٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180413, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن سعیدبن حصین الکندی الکوفی، مکنی به ابوسعید. محدث کوفه بود. او را تفسیر و تصانیفی است .وی به سال <span class=\"hlight\" dir=\"rtl\">٢٥٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180414, 'عبدا', '<span class=\"hlight\">عبدا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن سعودبن عبدالعزیزبن محمد. رجوع به ابن سعود عبداﷲبن سعود و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180415, 'عبدا', '<span class=\"hlight\">عبدا.</span><font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ]</font></b> (اِخ ) ابن سعدبن نفیل الازدی . از مردم ازدشنوءة و از رؤسای کوفه است با سلیمان بن صرد به خونخواهی حسین (ع ) برخاست و با بنی امیه جنگ کرد. و به سال <span class=\"hlight\" dir=\"rtl\">٦٥</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180416, 'عبدال آباد', '<span class=\"hlight\">عبدال آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است از دهستان بشاریات بخش آبیک شهرستان قزوین . واقع در <span class=\"hlight\" dir=\"rtl\">٣٠</span>هزارگزی باختر آبیک ونه هزارگزی راه عمومی و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">١٨٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، چغندرقند، پنبه و جالیزکاری است شغل اهالی زراعت است صنایع دستی آنها گلیم و جاجیم بافی است راه مالرو دارد. (از فرهنگ جغرافیائی ایران استان مرکزی ).<br /></font></div>'),
(180417, 'عبدال تپه', '<span class=\"hlight\">عبدال تپه .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َپ ْ پ َ ]</font></b> (اِخ ) دهی است جزء دهستان بشاریات بخش آبیک شهرستان قزوین . واقع در <span class=\"hlight\" dir=\"rtl\">٢٦٠٠٠</span> گزی باختر آبیک و <span class=\"hlight\" dir=\"rtl\">٦٠٠٠</span>گزی راه عمومی . جلگه ای هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٧٤</span> تن سکنه دارد. آب آن از رودخانه ٔ یانس آباد و چاه تأمین میشود. محصولات آن غلات است و صنایع دستی گلیم و جاجیم بافی است .اهالی به زراعت اشتغال دارند راه مالرو دارد. از مقبره ٔ شیخ الاسلامی میتوان ماشین برد. سکنه ٔ آن از طایفه ٔ شاهسون هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180418, 'عبدال ده', '<span class=\"hlight\">عبدال ده .</span> <font color=\"DarkGreen\"><b>[ ع َ دِ ]</font></b> (اِخ ) دهی است جزء دهستان ناتل رستاق بخش نور شهرستان آمل .واقع در <span class=\"hlight\" dir=\"rtl\">١٩</span>هزارگزی جنوب خاوری سولده . این دهکده در دشت قرار دارد. آب و هوای آن معتدل و مرطوب است و <span class=\"hlight\" dir=\"rtl\">٦٠</span>تن سکنه دارد. آب آن از رودخانه تأمین میشود. محصولات آن برنج و غلات است . اهالی به زراعت اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(180419, 'عبدال محمد', '<span class=\"hlight\">عبدال محمد.</span> <font color=\"DarkGreen\"><b>[ ع َ م ُ ح َم ْ م َ ]</font></b> (اِخ ) دهی است از دهستان دینور بخش صحنه ٔ شهرستان کرمانشاهان . واقع در <span class=\"hlight\" dir=\"rtl\">٢٩</span>هزارگزی باختر صحنه و <span class=\"hlight\" dir=\"rtl\">١٥</span>هزارگزی باختر راه شوسه ٔ کرمانشاهان به سنقر. ناحیه ای است کوهستانی و <span class=\"hlight\" dir=\"rtl\">٣١٥</span>تن سکنه دارد. آب آن از چشمه تأمین میشود. محصولات آن غلات و توتون است . اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180420, 'عبدالاشهل', '<span class=\"hlight\">عبدالاشهل .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ اَ هََ ]</font></b> (اِخ ) ابن جشم بن الحارث . از بنی نبیت از اوس از قحطان، جد جاهلی است سعدبن معاذ وبسیاری از صحابه از نسل وی اند. (از الاعلام زرکلی ).<br /></font></div>'),
(180421, 'عبدالاعلی', '<span class=\"hlight\">عبدالاعلی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ اَ لا ]</font></b> (اِخ ) ابن مسهر الغسانی الدمشقی، مکنی به ابومسهر. از حفاظ حدیث بود. او را ابن ابی دارمه نیز خوانده اند. وی از بزرگان شام و عالم به احادیث و جنگ ها و ایام مردم و انساب شامیان بود. به سال <span class=\"hlight\" dir=\"rtl\">١٤٠</span> هَ . ق . متولد شد و در سال <span class=\"hlight\" dir=\"rtl\">٢١٨</span> هَ . ق . در بغداد درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180422, 'عبدالاعلی', '<span class=\"hlight\">عبدالاعلی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ اَ لا ]</font></b> (اِخ ) ابن السمح المعافری . پیشوای فرقه ٔ اباضیه ٔ افریقا و از شجاعان بود که به سال <span class=\"hlight\" dir=\"rtl\">١٤١</span> هَ . ق . برتمام آفریقا تسلط یافت . منصور عباسی پنجاه هزار سوار بفرماندهی محمدبن الاشعث به سرکوبی وی فرستاد و ابن اشعث بر وی دست یافت . و او و یاران وی را بکشت . (سال <span class=\"hlight\" dir=\"rtl\">١٤٤</span> هَ . ق .) (الاعلام زرکلی ).<br /></font></div>'),
(180423, 'عبدالباسط', '<span class=\"hlight\">عبدالباسط.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ س ِ ]</font></b> (اِخ ) ابن خلیل بن شاهین الملطی . وی از مورخان است که فقه حنفی نیز آموخت . تولد او به ملطیه بود. در دمشق و قاهره علم آموخت به سال <span class=\"hlight\" dir=\"rtl\">٩٢٠</span> هَ . ق . بمرض سل درگذشت . از تألیفات اوست : الروض الباسم فی حوادث العمر و التراجم که تاریخ بزرگی است، و نیل الامل فی ذیل الدول که ذیل تاریخ ذهبی است و در آن وقایع سال <span class=\"hlight\" dir=\"rtl\">٨٤٤</span> تا <span class=\"hlight\" dir=\"rtl\">٨٩٦</span> هَ . ق . را متذکر شده است . (از الاعلام زرکلی ). و رجوع به کشف الظنون شود.<br /></font></div>'),
(180424, 'عبدالباقی', '<span class=\"hlight\">عبدالباقی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b> (اِخ ) سرور نعیم . نویسنده ٔ مصری است که پس از پایان تحصیلات خود در الازهر قاهره متصدی روزنامه ٔ الافکار گردید و به اتهام تحریک علیه دولت بریتانیا به زندان افتاد و همانجا به مرض سل دچار و به سال <span class=\"hlight\" dir=\"rtl\">١٣٤٧</span> هَ . ق . درگذشت . از تألیفات اوست : الاسلام ماضیه و حاضره . تنزیه القرآن الشریف عن التغییر و التحریف . (از الاعلام زرکلی ).<br /></font></div>'),
(180425, 'عبدالباقی', '<span class=\"hlight\">عبدالباقی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b> (اِخ ) ابن عبدالرحمان بن علی الخزرجی مشهور به امام الاشرفیه، وی مقدسی الاصل بود و منشاء و وفات او مصر بود. او را تصانیفی است از جمله روضة الاَّداب در چهار مجلد. الرمز فی شرح الکنز. او به سال <span class=\"hlight\" dir=\"rtl\">١٠٧٨</span> هَ . ق . به مصر درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180426, 'عبدالباقی', '<span class=\"hlight\">عبدالباقی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b> (اِخ ) مواهبی بن ابوالمواهب بن عبدالباقی الباقی الحنبلی الدمشقی . از فضلاء بود و از تألیفات اوست : نظم الشافیه در صرف و شرح آن، ارجوزه ای در عروض . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٧٩</span> به دمشق متولد و در <span class=\"hlight\" dir=\"rtl\">١١١٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180427, 'عبدالباقی', '<span class=\"hlight\">عبدالباقی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b> (اِخ ) از خطاطان معروف عصر شاه عباس کبیر و از اهالی تبریز بود. وی دانشمند تخلص می جست و به امر شاه عباس کتیبه ٔ مسجد جامع اصفهان را نوشت . از تألیفات او است : شرح بر نهج البلاغه به نام منهاج الولایه . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٣٩</span> هَ . ق . درگذشت . (از فهرست سپهسالار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣١</span>) (از الذریعه ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span>).<br /></font></div>'),
(180428, 'عبدالباقی', '<span class=\"hlight\">عبدالباقی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b> (اِخ ) ابن قانعبن مرزوق بن واثق الاموی ... از حفاظ حدیث و اصحاب رای بود و او راست کتاب فی معرفة الصحابة. وی به سال <span class=\"hlight\" dir=\"rtl\">٢٦٦</span> هَ . ق . متولد و به سال <span class=\"hlight\" dir=\"rtl\">٣٥١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180429, 'عبدالباقی', '<span class=\"hlight\">عبدالباقی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b> (اِخ ) ابن سلیمان بن احمد العمری الفاروقی الموصلی . از شعرا و مورخان است . در سال <span class=\"hlight\" dir=\"rtl\">١٢٠٤</span> هَ. ق . در موصل متولد شد و ابتدا ولایت زادگاه خود یافت و بعد در بغداد از کارمندان حکومتی بود و به سال <span class=\"hlight\" dir=\"rtl\">١٢٧٨</span> هَ . ق . در بغداد درگذشت . از تألیفات اوست : التریاق الفاروقی که دیوان شعر اوست، نزهة الدهر فی تراجم فضلاء العصر، الباقیات الصالحات و غیره . (از الاعلام زرکلی ). و رجوع به معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٩</span> شود.<br /></font></div>'),
(180430, 'عبدالباقی', '<span class=\"hlight\">عبدالباقی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b>(اِخ ) نبیره ٔ شاه نعمت اﷲ ولی بود از اشعار اوست :<br />تا پریشان نشود کار بسامان نشود<br />شرط دور است که تا این نشود آن نشود.<br />(از مجالس النفائس ص <span class=\"hlight\" dir=\"rtl\">١١٣٧</span>).<br />و رجوع شود به الذریعه ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٤</span>.<br /></font></div>'),
(180431, 'عبدالباقی', '<span class=\"hlight\">عبدالباقی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b> (اِخ ) ابن عبدالمجیدبن عبداﷲ الیمنی المخزومی ملقب به تاج الدین . از فضلاء و ادباء و مورخان بود. در سال <span class=\"hlight\" dir=\"rtl\">٦٨٠</span> در مکه متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٧٤٣</span> هَ . ق . به مصر درگذشت . از تألیفات اوست : تاریخ النحاة و ذیل تاریخ ابن خلکان . (الاعلام زرکلی ). و رجوع به فوات الاعیان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٥</span> شود.<br /></font></div>'),
(180432, 'عبدالباقی', '<span class=\"hlight\">عبدالباقی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b> (اِخ ) ابن عبدالباقی بن عبدالقادر البعلی الازهری الدمشقی مشهور به ابن فقیه فصة. به سال <span class=\"hlight\" dir=\"rtl\">١٠٠٥</span> هَ . ق . در بعلبک متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">١٠٢٩</span> به مصر رفت و تحصیلات خود را در الازهر بپایان رسانید و به دمشق بازگشت و به سال <span class=\"hlight\" dir=\"rtl\">١٠٧١</span> هَ . ق . درگذشت . از تألیفات اوست : العین و الاثر فی عقائد اهل الاثر، و فیض الرزاق فی تهذیب الاخلاق . (از الاعلام زرکلی ).<br /></font></div>'),
(180433, 'عبدالباقی', '<span class=\"hlight\">عبدالباقی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b> (اِخ ) معروف به شیخ الاسلام از احفاد میرسیدی رضی و اهل تویسرکان است . او را دیوانی است شامل قصائد و غزلیات در حدود <span class=\"hlight\" dir=\"rtl\">٧٠٠</span> بیت، از اشعار او است :<br />ای یافته ز قدر تو هر بی بها بها<br />تشریف تو است بر قد هر نارسا رسا.<br /><font color=\"Red\">(الذریعه ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span>).</font><br /></font></div>'),
(180434, 'عبدالباقی', '<span class=\"hlight\">عبدالباقی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b> (اِخ ) ابن احمد المعروف به ابن السمان . ادیب و از شعراء بود. مولد وی دمشق و ابتدا در زادگاه خود و بعد در مصر تحصیلات خود را بپایان رسانید. وی به بلاد ترک مسافرت و به دربار سلطان محمود عثمانی راه یافت و مقامی ارجمند احراز کرد از تألیفات اوست : شرح شواهد جامی و شرح اسماء الحسنی و مختصر التهذیب درمنطق و غیره . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٥٥</span> هَ . ق . به دمشق متولدو در <span class=\"hlight\" dir=\"rtl\">١٠٨٨</span> در قسطنطنیه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180435, 'عبدالباقی', '<span class=\"hlight\">عبدالباقی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b> (اِخ ) ابن احمد الموصلی . تألیفاتی دارداز جمله منظومه ای در نحو. وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٩٣</span> هَ . ق . در موصل متولد و در <span class=\"hlight\" dir=\"rtl\">١١٣٧</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180436, 'عبدالباقی', '<span class=\"hlight\">عبدالباقی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b> (اِخ ) ابن حمزة الحسین الحداد، مکنی به ابوالفضل . وی در سال <span class=\"hlight\" dir=\"rtl\">٤٢٥</span> هَ . ق . در بغداد متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٤٩٣</span> هَ . ق . درگذشت . او را کتابی است به نام الایضاح در فرائض . (از الاعلام زرکلی ).<br /></font></div>'),
(180437, 'عبدالباقی', '<span class=\"hlight\">عبدالباقی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b> (اِخ ) زرقانی بن یوسف بن احمد. فقیه مالکی بود. به سال <span class=\"hlight\" dir=\"rtl\">١٠٢٠</span> هَ . ق . به مصر متولد و در <span class=\"hlight\" dir=\"rtl\">١٠٩٩</span> درگذشت . از تألیفات اوست : شرح مختصرسیدی خلیل در فقه در چهار جزء. (از الاعلام زرکلی ).<br /></font></div>'),
(180438, 'عبدالبر', '<span class=\"hlight\">عبدالبر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ب َرر ]</font></b> (اِخ ) ابن عبدالقادربن محمدالعوفی معروف به فیومی . وی ادیب بود و به مکه و شام سفر کرد و در حدود دو سال در دمشق بماند. سپس به بلاد روم رفت و درآنجا منصبها یافت و به سال <span class=\"hlight\" dir=\"rtl\">١٠٧١</span> هَ . ق . در قسطنطنیه درگذشت . از تألیفات اوست : حسن الصنیع فی علم البدیع القول الوافی بشرح الکافی . منتزه العیون و الالباب فی بعض المتأخرین من اهل الاَّداب . اللطائف المنیفه فی فضائل الحرمین . بدیعیة علی حرف النون . بلوغ الارب و السول، بالتشرف بذکر نسب الرسول . (الاعلام زرکلی ).<br /></font></div>'),
(180439, 'عبدالبر', '<span class=\"hlight\">عبدالبر.</span><font color=\"DarkGreen\"><b>[ ع َ دُل ْ ب َرر ]</font></b> (اِخ ) ابن محمد، مکنی به ابوالبرکات . رجوع به ابن شحنه قاضی القضات عبدالبر... شود.<br /></font></div>'),
(180440, 'عبدالتاجدین', '<span class=\"hlight\">عبدالتاجدین .</span> <font color=\"DarkGreen\"><b>[ ع َ دُت ْ تا ج ِ ]</font></b> (اِخ ) دهی است از دهستان کنگاور بخش کنگاور شهرستان کرمانشاهان . واقع در <span class=\"hlight\" dir=\"rtl\">١٣</span>هزارگزی شمال باختر کنگاور - خاور کوه شمشیره . ناحیه ای است کوهستانی و سردسیر و <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> تن سکنه دارد، آب آن از چشمه تأمین میشود. محصولات آن غلات و لبنیات است . اهالی به کشاورزی و گله داری اشتغال دارند زمستان عده ای گله دار به حدود باوندپور میروند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180441, 'عبدالجبار', '<span class=\"hlight\">عبدالجبار.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ج َب ْ با ]</font></b> (اِخ ) ابن عبدالرحمان الازدی . وی امیری شجاع بود. به سال <span class=\"hlight\" dir=\"rtl\">١٠٤</span> هَ . ق . منصور وی را امارت خراسان داد و او بدانجا بسیاری مردم را به تهمت دوستی با آل علی بکشت، سپس از طاعت منصور بیرون شد، منصور سپاهیان بدفع او فرستاد و وی را اسیر کردند و نزد منصور آوردند منصور بفرمود دو پای او را بریدند و او را گردن زدند و فرزندان و کسان او را نفی بلد کردند. (از الاعلام زرکلی ).<br /></font></div>'),
(180442, 'عبدالجبار', '<span class=\"hlight\">عبدالجبار.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ج َب ْ با ]</font></b> (اِخ ) ابن عبداﷲبن احمد قرطبی قیروانی، مکنی به ابوطالب . به ادب و عربیت و تاریخ معرفتی داشت . او را شعری است و تاریخی تصنیف کرد.وی به سال <span class=\"hlight\" dir=\"rtl\">٥١٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180443, 'عبدالجبار', '<span class=\"hlight\">عبدالجبار.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ج َب ْ با ]</font></b> (اِخ ) دهی است از دهستان بدوستان بخش هریس شهرستان اهر. واقع در <span class=\"hlight\" dir=\"rtl\">٣١</span>هزارگزی باختر هریس و دوهزارگزی شوسه ٔ تبریز به اهر. کوهستانی و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٥٨٢</span> تن سکنه دارد. آب آن از چشمه تأمین میشود. محصولات آن غلات و حبوبات است . شغل اهالی زراعت و گله داری است، صنایع دستی گلیم بافی است . راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(180444, 'عبدالجبار', '<span class=\"hlight\">عبدالجبار.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ج َب ْ با ]</font></b> (اِخ ) ابن احمدبن عبدالجبار الهمدانی الاسدآبادی، مکنی به ابوالحسین، قاضی بود و در علم اصول و کلام تبحر داشت، و در عصر خویش شیخ معتزلیان بود و آنان وی را قاضی القضاة می گفتند. و جز وی کسی را بدین لقب نمی خواندند. از تألیفات اوست : تنزیه القرآن عن المطاعن، والامالی . وی به سال <span class=\"hlight\" dir=\"rtl\">٤١٥</span> هَ . ق . به ری درگذشت . (از الاعلام زرکلی ). و رجوع به خاندان نوبختی شود.<br /></font></div>'),
(180445, 'عبدالجبار', '<span class=\"hlight\">عبدالجبار.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ج َب ْ با ]</font></b> (اِخ ) ابن احمدبن عمر الطر سوسی، مکنی به ابوالقاسم . وی عالم به قراآت بود و کتابی بنام المجتبی الجامع در علم قرائت تألیف کرده است . او به سال <span class=\"hlight\" dir=\"rtl\">٣٣١</span> متولد شد ودر <span class=\"hlight\" dir=\"rtl\">٤٢٠</span> هَ . ق . به مصر درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180446, 'عبدالجبار', '<span class=\"hlight\">عبدالجبار.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ج َب ْ با ]</font></b> (اِخ ) ابن خالدبن بن عمران السرتی، مکنی به ابوحفض . وی فقیهی فاضل و زاهد و در فضل ودینداری ضرب المثل بود. به سال <span class=\"hlight\" dir=\"rtl\">١٩٤</span> هَ . ق . متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٢٨١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180447, 'عبدالجلیل', '<span class=\"hlight\">عبدالجلیل .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ج َ ]</font></b> (اِخ ) مردی نیک است شعر را نیز نیک میگوید از اوست این مطلع:<br />ز بس که کاست مه از میل طاق ابرویش <br />شد آن چنان که نمود استخوان پهلویش .<br /><font color=\"Red\">(از مجالس النفائس ص <span class=\"hlight\" dir=\"rtl\">١٥٥</span>).</font><br /></font></div>'),
(180448, 'عبدالجلیل', '<span class=\"hlight\">عبدالجلیل .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ج َ ]</font></b> (اِخ ) ابن فیروزبن الحسین الغزنوی النحوی . از بزرگان و اعیان غزنه بود. او راست : کتاب الهدایة فی النحو. لباب التصریف . معانی الحروف . مونس الانسان و مذهب الاحزان . (از روضات ص <span class=\"hlight\" dir=\"rtl\">٤٢٢</span>).<br /></font></div>'),
(180449, 'عبدالجلیل', '<span class=\"hlight\">عبدالجلیل .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ج َ]</font></b> (اِخ ) ابن محمدبن احمد العمری فلکی معروف به ابن عبدالهادی . از مردم دمشق است و متصوف بود. او راست : الربع الجامع، و الربع لمقنطر. کتاب الهندسه . الممتنع السهل فی علم الرمل . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٥٥</span> هَ . ق . متولدشد و در <span class=\"hlight\" dir=\"rtl\">١٠٨٧</span> به مدینه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180450, 'عبدالجلیل', '<span class=\"hlight\">عبدالجلیل .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ج َ ]</font></b> (اِخ ) ابن محمدبن عبدالباقی البعلی الدمشقی . وی عالم به نحو و از مردم بعلبک است به دمشق متولد شد و هم بدانجا درگذشت . او راست : نظم الشافیه در علم صرف، شرح آن، تشطیر الفیه ٔ ابن مالک، و او را شعری است . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٧٩</span> هَ . ق . متولد شدو به سال <span class=\"hlight\" dir=\"rtl\">١١١٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180451, 'عبدالجلیل', '<span class=\"hlight\">عبدالجلیل .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ج َ ]</font></b> (اِخ ) ابن محمدبن عبدالجلیل الانصاری القرطبی، مکنی به ابومحمد. ازعلماء علم عربیت بود و قضاوت جزیره ٔ خضراء یافت و در حدود سال <span class=\"hlight\" dir=\"rtl\">٦٠٠</span> هَ . ق . درگذشت . (از روضات ص <span class=\"hlight\" dir=\"rtl\">٤٢٢</span>).<br /></font></div>'),
(180452, 'عبدالجلیل', '<span class=\"hlight\">عبدالجلیل .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ج َ ]</font></b> (اِخ ) رشیدالدین وطواط. رجوع به رشیدالدین وطواط شود.<br /></font></div>'),
(180453, 'عبدالجمیل', '<span class=\"hlight\">عبدالجمیل .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْج َ ]</font></b> (اِخ ) در سلک دانشمندان متعین انتظام داشت . و چند گاه در دارالسیاده ٔ سلطانی بقلم دانش نقش افاده بر صحیفه ٔ خاطر طلبه مینگاشت وی به سال <span class=\"hlight\" dir=\"rtl\">٩٢١</span> هَ . ق . درگذشت . وی معاصر امیر سلطان ابراهیم بود. (رجال حبیب السیر ص <span class=\"hlight\" dir=\"rtl\">١٩٢</span>). و رجوع به حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٦</span> شود.<br /></font></div>'),
(180454, 'عبدالجنة', '<span class=\"hlight\">عبدالجنة.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ج ِن ْن َ ]</font></b> (ع اِ مرکب ) کابوس . (غیاث اللغات از منتخب ).<br /></font></div>'),
(180455, 'عبدالجواد', '<span class=\"hlight\">عبدالجواد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ج َ ]</font></b> (اِخ ) ابن شعیب بن احمد القنائی بصری از فضلا بود. او راست : القهوة المدارة فی تقسیم الاستعاره . النسیم العاطر فی تقسیم الخاطر. العظة الوفیة فی یقظة الصوفیة. وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٧٣</span> هَ . ق . درگذشت . (الاعلام زرکلی ).<br /></font></div>'),
(180456, 'عبدالجواد', '<span class=\"hlight\">عبدالجواد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ج َ ]</font></b> (اِخ ) ابن عبداللطیف القایاتی از فقهاء شافعی و متصوفان بود. مولد و وفات او شهر قایات مصر بود. او را مجموع فتاوی و رسائلی است فی الانتصار لاهل الطریق فی امور انکرت علیهم . وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٢٩</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">١٢٨٧</span> هَ . ق . درگذشت . (الاعلام زرکلی ).<br /></font></div>'),
(180457, 'عبدالجواد', '<span class=\"hlight\">عبدالجواد.</span><font color=\"DarkGreen\"><b>[ ع َ دُل ْ ج َ ]</font></b> (اِخ ) رجوع به ادیب نیشابوری شود.<br /></font></div>'),
(180458, 'عبدالحاکم', '<span class=\"hlight\">عبدالحاکم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ک ِ ]</font></b> (اِخ ) ابن سعید الفارقی . فاضل بود و قضاوت طرابلس و مصر یافت . وی از قاضیان مصر در روزگار فاطمیان است و به سال <span class=\"hlight\" dir=\"rtl\">٤٣٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی چ <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٧٧</span>).<br /></font></div>'),
(180459, 'عبدالحسن', '<span class=\"hlight\">عبدالحسن .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ س َ ]</font></b> (اِخ ) ده کوچکی است از دهستان خیران بخش مرکزی شهرستان شوشتر. واقع در <span class=\"hlight\" dir=\"rtl\">٦٤</span>هزارگزی جنوب خاوری شوشتر کنار شوسه ٔ مسجدسلیمان به اهواز. <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180460, 'عبدالحسین', '<span class=\"hlight\">عبدالحسین .</span> <font color=\"DarkGreen\"><b>[ع َ دُل ْ ح ُ س َ ]</font></b> (اِخ ) دهی است از دهستان خاوه بخش دلفان شهرستان خرم آباد واقع در <span class=\"hlight\" dir=\"rtl\">١٥</span>هزارگزی خاور نورآباد و هفت هزارگزی جنوبی راه اتومبیل رو خرم آباد به کرمانشاه . ناحیه ای است جلگه ای، سردسیر، مالاریائی . <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> تن سکنه دارد. آب آن از سراب نیاز تأمین میشود. محصولات آن غلات، لبنیات، و توتون است اهالی به کشاورزی و گله داری اشتغال دارند. راه مالرو دارد. ساکنین از طایفه ٔ خاوه هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180461, 'عبدالحفیظ', '<span class=\"hlight\">عبدالحفیظ.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) ابن حسن بن محمد الحسنی العلوی، مکنی به ابوالمواهب . از سلاطین دولت علویه ٔ مغرب اقصی است . وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٨٠</span> هَ . ق . در فاس متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">١٣٥٦</span> هَ . ق . درگذشت و در فاس به خاک سپرده شد. از تألیفات اوست : منظومة فی مصطلح الحدیث . الجواهر اللوامع فی نظم جمع الجوامع. یاقوتة الحکام فی مسائل القضاء و الاحکام . العذب السلسبیل فی حل الفاظ الخلیل در فقه مالکی . کشف القناع عن اعتقاد طوائف الابتداع در رد بر بعض متصوفه . نیل النجاح و الفلاح فی علم ما به القرآن و الاسلام . (از الاعلام زرکلی ).<br /></font></div>'),
(180462, 'عبدالحق', '<span class=\"hlight\">عبدالحق .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َق ق ]</font></b> (اِخ ) ابن محمد الحمصی الاصل الدمشقی ملقب به زین الدین . از فضلاء بود و او را شعری است رقیق . وی به سال <span class=\"hlight\" dir=\"rtl\">٩٦٢</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">١٠٢٠</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180463, 'عبدالحق', '<span class=\"hlight\">عبدالحق .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َق ق ]</font></b> (اِخ ) ابن غالب بن عبدالرحیم . رجوع به ابن عطیه شود.<br /></font></div>'),
(180464, 'عبدالحق', '<span class=\"hlight\">عبدالحق .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َق ق ]</font></b> (اِخ ) ابن محبوب بن ابی بکربن حمامةبن محمدالمرینی ملقب به ابومحمد. وی مؤسس دولت مرینیه در مغرب اقصی است و ریاست بنی مرین را داشت . عبدالحق به سال <span class=\"hlight\" dir=\"rtl\">٥٩٢</span> هَ. ق . حکومت یافت و به سال <span class=\"hlight\" dir=\"rtl\">٦١٤</span> در نبرد با بنی العسکربه قتل رسید. (از الاعلام زرکلی ) (از معجم الانساب ).<br /></font></div>'),
(180465, 'عبدالحق', '<span class=\"hlight\">عبدالحق .</span> <font color=\"DarkGreen\"><b>[ع َ دُل ْ ح َق ق ]</font></b> (اِخ ) استرابادی . جوانی خوش طبع و خوش محاوره و اخلاق حمیده و اخلاق پسندیده داشت . و میگویند که قاضی جرجان خری به رشوت به قاضی عسکر داده تا قاضی گشته و سید عبدالحق جهة او این قطعه گفته است :<br />همی گشت در شهر شخصی ز جرجان <br />که قاضی شود صدر راضی نمیشد<br />بدادش خری رشوه و گشت قاضی <br />اگر خر نمی بود قاضی نمیشد.<br /><font color=\"Red\">(مجالس النفائس ص <span class=\"hlight\" dir=\"rtl\">٢٢٠</span> و <span class=\"hlight\" dir=\"rtl\">٤٧</span>).</font><br /></font></div>'),
(180466, 'عبدالحق', '<span class=\"hlight\">عبدالحق .</span> <font color=\"DarkGreen\"><b>[ع َ دُل ْ ح َق ق ]</font></b> (اِخ ) ابن عثمان بن احمد، مکنی به ابومحمد المرینی آخرین پادشاه بنی مرین از بنی عبدالحق به مغرب است سلاوی گفته است : وی را حکومت دراز بود. و به سال <span class=\"hlight\" dir=\"rtl\">٨٢٢</span> هَ . ق . بحکومت فاس رسید. در زمان حکومت وی پرتغالیان بر قصر المجاز دست یافتند، و سرانجام به سال <span class=\"hlight\" dir=\"rtl\">٨٦٩</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180467, 'عبدالحق', '<span class=\"hlight\">عبدالحق .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َق ق ]</font></b> (اِخ ) ابن عبدالرحمان بن عبداﷲ الازدی الاشبیلی، مکنی به ابومحمد ومعروف به ابن خراط. از علماء اندلس و فقیه و حافظ وعالم بحدیث و رجال بود. از جمله تألیفات اوست : المعتل من الحدیث در شش مجلد. الاحکام الشرعیة الکبری درشش مجلد. الاحکام الصغری . الاحکام الوسطی . الجامع الکبیر در حدود بیست مجلد. کتاب الزهد. العاقبة و ذکر الموت تلقین الولید، و کتابی بزرگ در غریب قرآن و حدیث و الجمع بین الصحیحین . وی به سال <span class=\"hlight\" dir=\"rtl\">٥١٠</span> هَ . ق . متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٥٨١</span> هَ . ق . درگذشت . (الاعلام زرکلی ).<br /></font></div>'),
(180468, 'عبدالحق', '<span class=\"hlight\">عبدالحق .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َق ق ]</font></b> (اِخ ) ابن ابراهیم بن محمدبن نصربن سبعین الاشبیلی المرسی . رجوع به ابن سبعین ابومحمد عبدالحق شود.<br /></font></div>'),
(180469, 'عبدالحلیم', '<span class=\"hlight\">عبدالحلیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) ابن عبداﷲالنابلسی الشویکی . مردی فاضل بود وبه ادب اشتغال داشت . در الازهر به تحصیل پرداخت و درنابلس سکونت جست سپس به عکا رفت و نزد حاکم عکا مکانتی یافت و به سال <span class=\"hlight\" dir=\"rtl\">١١٨٥</span> هَ . ق . درگذشت . او را رساله ای است در علم کلام و شرح سنوسی . (از الاعلام زرکلی ).<br /></font></div>'),
(180470, 'عبدالحمید', '<span class=\"hlight\">عبدالحمید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) ابن عبدالرحمان بن زیدبن الخطاب ملقب به عدوی و مکنی به ابوعمر. وی از مردم مدینه و در حدیث ثقه بود عمربن عبدالعزیز او را ولایت کوفه داد و در حدود سال <span class=\"hlight\" dir=\"rtl\">١١٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180471, 'عبدالحمید', '<span class=\"hlight\">عبدالحمید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) زهراوی . از زعمای نهضت سیاسی سوریه است به سال <span class=\"hlight\" dir=\"rtl\">١٢٧٢</span> هَ . ق . در حمص متولد شد هنگامی که حکومت عثمانی با رژیم استبدادی اداره می شد با سلطان عبدالحمید به مخالفت برخاست و روزنامه ای به نام «المنیر» انتشار داد که آن را با ژلاتین چاپ میکرد و محرمانه منتشر میساخت . حکومت عثمانی او را به دمشق تبعید کرد و در آنجا برای جریده ٔ «المقطم » مصر مقاله مینوشت ناظم پاشا والی دمشق مطلع شد و او را تحت الحفظ به آستانه فرستاد سپس به وساطت ابوالهدی صیادی به حمص بازگشت و تا اعلام مشروطیت عثمانی به سال <span class=\"hlight\" dir=\"rtl\">١٣٢٧</span> هَ . ق . بدانجا ماند و سپس به سوریه و از آنجا به آستانه رفت و جریده ٔ هفتگی «الحضارة» را منتشر کرد. در جنگ بین المللی اول دستگیر شد و در دیوان عالی کشور محاکمه و محکوم به اعدام گردید. از تالیفات اوست : رسالة فی الفقه و التصوف، و کتاب خدیجه ام المؤمنین . (از الاعلام زرکلی ).<br /></font></div>'),
(180472, 'عبدالحمید', '<span class=\"hlight\">عبدالحمید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْح َ ]</font></b> (اِخ ) ابن ابراهیم بن خلیل از آل ابوهیف بود به سال <span class=\"hlight\" dir=\"rtl\">١٣٠٥</span> هَ . ق . در اسکندریه متولد شد، و بدانجا به تحصیل پرداخت، سپس به مدرسه ٔ حقوق اسکندریه و دانشگاه تولوز رفت . وی به سال <span class=\"hlight\" dir=\"rtl\">١٣٤٤</span> هَ . ق . درگذشت . او راست : المعرافعات المدنیه و التجاریه . النظام القضائی فی مصر و القانون الدولی الخاص . (از الاعلام زرکلی ).<br /></font></div>'),
(180473, 'عبدالحمید', '<span class=\"hlight\">عبدالحمید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) ابن ابی الحدید.رجوع به ابن ابی الحدید و روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٢٢</span> شود.<br /></font></div>'),
(180474, 'عبدالحمید', '<span class=\"hlight\">عبدالحمید.</span><font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) ابن عامربن عبدالبر... معروف به عبدالحمید بک . وی طبیب است و از خاندان عبدالبر در منوفیه مصر است به سال <span class=\"hlight\" dir=\"rtl\">١٣٠٠</span> هَ . ق . متولد شد و درسال <span class=\"hlight\" dir=\"rtl\">١٣٤٤</span> درگذشت . او راست : الطب الشرعی فی حصر مبادی . الطب الشرعی فی مصر و جز آن . (از الاعلام زرکلی ).<br /></font></div>'),
(180475, 'عبدالحمید', '<span class=\"hlight\">عبدالحمید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) ابن یحیی بن سعد العامری . رجوع به کاتب عبدالحمیدبن یحیی شود.<br /></font></div>'),
(180476, 'عبدالحمید', '<span class=\"hlight\">عبدالحمید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) ابن عبدالعزیز ملقب به ابوخازم . قاضی شام و کوفه و کرخ و بغداد بود. از تألیفات اوست : ادب القاضی و الفرائض ...وی به سال <span class=\"hlight\" dir=\"rtl\">٢٩٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180477, 'عبدالحمید', '<span class=\"hlight\">عبدالحمید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) ابن عبدالعزیزبن عبداﷲبن عمرالخطاب العمری ملقب به ابوعبدالرحمان . وی شجاع بود و در مصر میزیست، در عصر احمدبن طولون بود لشکری به جنگ وی فرستاد، عبدالحمید بر آنان غالب آمد و ابن طولون وی را به حال خود گذاشت سرانجام دو غلام سر او رابریدند و به نزد ابن طولون بردند. ابن طولون به خونخواهی عبدالحمید آن دو غلام را بکشت . قتل عبدالحمید به سال <span class=\"hlight\" dir=\"rtl\">٢٥٩</span> هَ . ق . اتفاق افتاد. (از الاعلام زرکلی ).<br /></font></div>'),
(180478, 'عبدالحمید', '<span class=\"hlight\">عبدالحمید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) ابن عبدالغنی بن احمد الرافعی . شاعر با استعداد بود. وی اسلوبهای قدیم و جدید را اصلاح کرد. در زمان حکومت عثمانی مناصبی احراز و دراوائل جنگ بین المللی اول به مدینه تبعیدش کردند. ازتألیفات اوست : ذکری یوبیل بلبل سوریه حاوی خطب و قصائد او. الافلاک الزبرجدیة و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٧٥</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">١٣٥٠</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180479, 'عبدالحمید', '<span class=\"hlight\">عبدالحمید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) ابن عبدالمجید مولی قیس بن ثعلبه ملقب به ابوخطاب و مکنی به اخفش . رجوع به اخفش ابوالخطاب شود.<br /></font></div>'),
(180480, 'عبدالحمید', '<span class=\"hlight\">عبدالحمید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) ابن عیسی بن عمرویه، مکنی به ابومحمد و ملقب به شمس الدین از علماء کلام بود. وی از مردم خسروشاه یکی از قراء تبریز است . در دمشق و کرک اقامت گزید از تألیفات اوست : اختصار المهذب در فقه شافعی و اختصار الشفاء ابن سینا و تلخیص الاَّیات البینات فخر رازی . وی به سال <span class=\"hlight\" dir=\"rtl\">٥٨٠</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">٦٥٢</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180481, 'عبدالحمید', '<span class=\"hlight\">عبدالحمید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) ابن محمد المصطفی بن مکی مشهور به ابن بادیس . رئیس جمعیت مسلمین به الجزائر بود. تحصیلات خود رادر مدرسه ٔ الزیتونة پایان داد. وی مجله ٔ الشهاب را که مجله ای دینی و علمی بود منتشر کرد. حکومت فرانسه در الجزائر درصدد فریفتن وی برآمد. وی از قبول پیشنهادات آنها امتناع ورزید او مدارس زیادی تأسیس کرد. از تألیفات اوست : تفسیرالقران الکریم . وی به سال <span class=\"hlight\" dir=\"rtl\">١٣٥٩</span> هَ . ق . در قسطنطنیه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180482, 'عبدالحمیدی', '<span class=\"hlight\">عبدالحمیدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) دهی است از دهستان نیگنان بخش بشرویه شهرستان فردوس واقع در <span class=\"hlight\" dir=\"rtl\">٤٢</span>هزارگزی شمال باختری بشرویه و چهارهزارگزی نیگنان ناحیه ای است واقع در دامنه، گرمسیر. <span class=\"hlight\" dir=\"rtl\">٢٢</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، پنبه و ارزن است و اهالی به کشاورزی گذران میکنند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180483, 'عبدالحکیم', '<span class=\"hlight\">عبدالحکیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) ابن اسحاق بن ابراهیم . رجوع به ابواسحاق عراقی شود.<br /></font></div>'),
(180484, 'عبدالحکیم', '<span class=\"hlight\">عبدالحکیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) الافغانی القندهاری، فقیه حنفی و از زهاد بود. وی به دمشق ساکن شد. و از عمل خویش ارتزاق میکرد. عمری دراز یافت و به سال <span class=\"hlight\" dir=\"rtl\">١٣٢٦</span> هَ . ق . به دمشق درگذشت .او را شروح و حواشی چند است از جمله : شرح الکنز در فقه حنفی . شرح بخاری . شرح الهدایه . شرح المنار. شرح الشاطبیه و حاشیه بر شرح بخاری . (از الاعلام زرکلی ).<br /></font></div>'),
(180485, 'عبدالحکیم', '<span class=\"hlight\">عبدالحکیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َ ]</font></b> (اِخ ) ابن شمس الدین الهندی السیالکوتی از فضلاء سیالکوت لاهور هندوستان . او راست : عقاید السیالکوتی . حاشیه بر تفسیر بیضاوی که ناقص است . زبدة الافکار. حاشیه بر شرح عقاید نسفیه . حاشیه بر جرجانی در منطق . حاشیه بر قطب بر شمسیه منطق . حاشیه بر مطول و حاشیه بر شرح تصریف العزی . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٦٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180486, 'عبدالحی', '<span class=\"hlight\">عبدالحی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َی ْی ]</font></b> (اِخ ) منشی، از خطاطان مشهور و در خط نستعلیق سرآمد بود، در زمان سلطان سعید مدتی صاحب دیوان انشاء بود مناشیر مینوشت وبعد از واقعه ٔ قراباغ منظور نظر تربیت امیرحسن بیک شده تا آخر حیات در ملازمت سلاطین آق قوینلو به همان منصب اشتغال داشت . (از حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٤</span> چ دوم ص <span class=\"hlight\" dir=\"rtl\">١٠٨</span>).<br /></font></div>'),
(180487, 'عبدالحی', '<span class=\"hlight\">عبدالحی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َی ْی ]</font></b> (اِخ )بعلی بن ابی بکر البعلی معروف به طرزالریحان . عالم به ادب بود، او را دیوانی است . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٣٤</span> م . به دمشق متولد و در <span class=\"hlight\" dir=\"rtl\">١٠٩٩</span> م . درگذشت . (از الاعلام زرکلی ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(180488, 'عبدالحی', '<span class=\"hlight\">عبدالحی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َی ْی ]</font></b> (اِخ ) ابن احمدبن محمدبن العماد العکری الحنبلی، مکنی به ابوالفلاح مورخ، فقیه، عالم به ادب بود. از تالیفات اوست : شذرات الذهب فی اخبار من ذهب در هشت جزء و غیره . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٣٢</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">١٠٨٩</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180489, 'عبدالحی', '<span class=\"hlight\">عبدالحی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح َی ْی ]</font></b> (اِخ ) ابن علی بن محمد الطالوی الحنفی الدمشقی . او را دیوان شعر و کتابی است در ادب به نام مرور الصبا و الشمول . وی به سال <span class=\"hlight\" dir=\"rtl\">١١١٧</span> هَ . ق . به دمشق درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180490, 'عبدالخالق', '<span class=\"hlight\">عبدالخالق .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ل ِ ]</font></b> (اِخ ) ابن عیسی بن احمد ملقب به ابوجعفر معروف به الشریف الهاشمی وی امام حنابله به بغداد بود از تألیفات اوست رؤوس المسائل، ادب الفقه و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">٤١١</span> هَ . ق . متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٤٧٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180491, 'عبدالدار', '<span class=\"hlight\">عبدالدار.</span> <font color=\"DarkGreen\"><b>[ ع َ دُدْ دا ]</font></b> (اِخ ) ابن قصی بن کلاب بن قره از قریش جد جاهلی است . وی از طرف پدر پرده دار کعبه بود و پسران او نیز این منصب را داشتند سپس بنی عبدمناف بن قصی بن کلاب درصدد اشغال آن منصب برآمدند و سرانجام سقایت و رفادت مکه به بنی عبدمناف واگذار و پرده داری به بنی عبدالدار رسید. (از الاعلام زرکلی ) (از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٦</span>).<br /></font></div>'),
(180492, 'عبدالرافع', '<span class=\"hlight\">عبدالرافع.</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ را ف ِ ]</font></b> (اِخ ) ابن ابوالفتح الجدوی . مؤلف مجمع الفصحاء نویسد: حکیم ضیاءالدین عبدالرافع فاضلی است جلیل القدرو کاملی منشرح الصدر، شاعری است و استاد در حکمت نظری و عملی مدتها در خدمت سلطان ملک خسرو بود در نهایت احترام میزیست او را اشعاری است . از آنجمله است :<br />گلبن حکایت از بت کشمیر میکند<br />سوسن نشان ز لعبت فرخار میدهد<br />گردون لاژوردی از شاخ سیم رنگ <br />شنگرف میدماند و زنگار میدهد.<br />(از مجمعالفصحاء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٦</span>) (از لباب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٧</span>).<br /></font></div>'),
(180493, 'عبدالرب آباد', '<span class=\"hlight\">عبدالرب آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) دهی است از دهستان دشتابی بخش بوئین قزوین واقع در <span class=\"hlight\" dir=\"rtl\">٣٠٠٠٠</span>گزی بوئین و <span class=\"hlight\" dir=\"rtl\">٢١٠٠٠</span>گزی جاده تاکستان ناحیه ای است جلگه ای و هوای آن معتدل است، <span class=\"hlight\" dir=\"rtl\">١٤٠</span> تن سکنه دارد. آب آن از قنات و رودخانه ٔ خررود تأمین میشود محصولات آن پنبه، کرچک و چغندرقند است . شغل اهالی زراعت است صنایع دستی آنان گلیم و جاجیم بافی است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(180494, 'عبدالرب آبادی', '<span class=\"hlight\">عبدالرب آبادی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) یکی از هشت تن نویسندگان نامه ٔ دانشوران است . رجوع به محمد مهدی شود.<br /></font></div>'),
(180495, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن حسین بن عبداﷲ البکری الفاروثی فقیه متصوف واز مردم دمشق بود و شعر نیکو میگفت . به سال <span class=\"hlight\" dir=\"rtl\">٧١١</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">٧٧٦</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180496, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن حسن الاصبهانی معروف به ابوسعد النیشابوری . از حفاظ حدیث بود. او راست : کتاب شرف المصطفی و جز آن وی به سال <span class=\"hlight\" dir=\"rtl\">٣٠٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180497, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن حسن بن سعید الخزرجی القرطبی، مکنی به ابوالقاسم . عالم به قراآت بود. او راست : کتاب القاصد در علم قرائت .وی به سال <span class=\"hlight\" dir=\"rtl\">٤٤٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180498, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن حسل الجمحی . شاعر هجاگوی و صحابی بود اصل او از یمن و مولد او مکه است . و در فتح دمشق حاضر بود. وی عثمان بن عفان را در زمان خلافتش هجا گفت . و بدان جهت او را در خیبر زندانی کرد. سپس با وساطت حضرت علی (ع ) آزاد شد. وی در رکاب علی (ع ) در جنگ جمل و صفین حاضر بود، و در صفین به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180499, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span><font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن حسان العنزی . مردی شجاع واز اصحاب علی بن ابی طالب بود، در کوفه اقامت کرد و مردم را بر ضد بنی امیه برانگیخت . زیادبن ابیه وی را بگرفت و به شام فرستاده، معاویه او را بفرمود تا از علی (ع ) تبرّی جوید او در جواب سخنان ناهموار گفت . معاویه دیگر بار او را نزد زیاد فرستاد و زیاد به سال <span class=\"hlight\" dir=\"rtl\">٥١</span> هَ . ق . او را بکشت . (از سیره ٔ عمربن عبدالعزیز ص <span class=\"hlight\" dir=\"rtl\">٥١</span>) (الاعلام زرکلی ) (تاریخ الخلفاء صص <span class=\"hlight\" dir=\"rtl\">١٣٥</span> - <span class=\"hlight\" dir=\"rtl\">١٦٤</span>).<br /></font></div>'),
(180500, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن حسان بن ثابت الانصاری الخزرجی شاعر و شاعرزاده و مقیم مدینه بود. در زمان پدر خود به شاعری شهرت یافت . به سال <span class=\"hlight\" dir=\"rtl\">١٠٤</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180501, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن حجیرة الخولانی المصری، مکنی به ابوعبداﷲ. از قضات و امین خزانه ٔ مصر و از رجال حدیث بود. عبدالعزیزبن مروان او را به قضاوت برگزید... وی به سال <span class=\"hlight\" dir=\"rtl\">٨٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180502, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن حبیب الفهری معروف به صقلی . بخاطر درازی قامت و کبودی چشم و سرخ و سپیدی رنگ به صقلی معروف شد. هنگام استیلای عبدالرحمان معروف به «الداخل الاموی » بر اندلس با وی مخالفت کرد و به یاری عباسیان برخاست مردم اندلس به جنگ او درآمدند. وی به کوهی در ناحیه ٔ بلنسیه پناه برد الداخل برای سر او هزار دینار جایزه معین کرد و مردی از بربر وی را گرفت و به سال <span class=\"hlight\" dir=\"rtl\">١٦٢</span> غیلةً او را بکشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180503, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن حبیب بن ابی عبیدةبن عقبةبن نافع الفهری . وی امیری شجاع و زیرک بود و با پدر خود در افریقیه میزیست پس از قتل پدرش به سال <span class=\"hlight\" dir=\"rtl\">١٢٢</span> هَ . ق . به اندلس رفت سپس به تونس بازگشت و تا سال <span class=\"hlight\" dir=\"rtl\">١٢٦</span> در آنجا اقامت کرد و مردم تونس با وی بیعت کردند و به همراهی آنان به قیروان رفت و آنجا را تصرف کرد و با مردم تلمسان و صقلیه و مردانیه نبرد کرد وغنائم زیادی بدست آورد. و غلغله در مغرب انداخت . وی به سال <span class=\"hlight\" dir=\"rtl\">١٣٧</span> هَ . ق . به دست برادرانش عبدالوارث و الیاس در قصر قیروان به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180504, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن حارث بن هشام المخزومی القرشی المدنی . از تابعیان و ثقات حدیث و اشراف جلیل القدر قریش بود. وی یکی از چهار تن است که عثمان بن عفان استنساخ مصاحف را به آنان واگذار کرد. وی به سال <span class=\"hlight\" dir=\"rtl\">٤٣</span> هَ . ق . در مدینه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180505, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن جبلة الانباری . از بزرگان و پیشوایان عصر عباسی است . محمدامین وی را با بیست هزار تن به جنگ مأمون فرستاد او بلاد خراسان را فتح کرد و در همدان با لشکریان مأمون جنگید و به سال <span class=\"hlight\" dir=\"rtl\">١٩٥</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180506, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن حسن بن عمر الاجهوری فقیه مالکی و از مردم مصر بود و به حلب مسافرت کرد. وی از مدرسین الازهر بود. از تألیفات اوست : مشارق الانوار فی آل البیت الاخیار. شرح علی تشنیف السمع للعیدروس . به سال <span class=\"hlight\" dir=\"rtl\">١١٩٨</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180507, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ )ابن احمدبن محمدالعطار. از فضلاء و عالم به حدیث و ادب بود و شعر نیز گفته است . وی خط نیکو داشت و به سال <span class=\"hlight\" dir=\"rtl\">٥٤٨</span> هَ . ق . به شیراز درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180508, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن بدر معروف به ابن بکار النابلسی رشیدالدین . شاعری خوش سخن بود، او را مدائحی در وصف ناصر و اولاد اوست .وی به سال <span class=\"hlight\" dir=\"rtl\">٦١٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180509, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن البارزی بن ابراهیم بن هبة اﷲ الجهنی الحموی الشافعی . از قضات و فقهاء اصولی و شعراء و از اهل حماة بود. به سال <span class=\"hlight\" dir=\"rtl\">٦٠٨</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">٦٨٣</span> به مدینه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180510, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن اسماعیل بن عثمان الصفراوی . رجوع به صفراوی عبدالرحمان بن اسماعیل شود.<br /></font></div>'),
(180511, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن اسماعیل بن عبدکلال . وی از بنی حمیر و شاعری رقیق الغزل بود. به سال <span class=\"hlight\" dir=\"rtl\">٩٠</span> هَ. ق . به امر ولید به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180512, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن اسماعیل بن ابراهیم المقدسی الدمشقی ملقب به شهاب الدین و مکنی به ابوالقاسم و معروف به ابوشامة. رجوع به ابوشامة شود.<br /></font></div>'),
(180513, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن اسحاق النهاوندی الزجاجی، مکنی به ابوالقاسم . در عصر خود از شیوخ عربیت بود. مولد وی نهاوند است و در بغداد نشأت یافت و به سال <span class=\"hlight\" dir=\"rtl\">٣٣٩</span> هَ . ق . در طبریه ٔ سوریه درگذشت . از تألیفات اوست : الجمل الکبری . الایضاح الکافی . این هر دو در نحو است . شرح الالف و اللام مازنی . شرح خطبة ادب الکاتب . المخترع فی القوافی و الامالی . (از الاعلام زرکلی ).<br /></font></div>'),
(180514, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن اسحاق بن محمدالسدوسی معروف به جوهری . قاضی وفقیه و عالم به حساب بود. قضاوت مصر یافت . او را کتابی است در حساب . وی به سال <span class=\"hlight\" dir=\"rtl\">٢٥١</span> هَ . ق . به سامرا متولد شد و در <span class=\"hlight\" dir=\"rtl\">٣٢٠</span> به مصر درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180515, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span><font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن ارطاةبن سیحان المحاربی . از شعراء بود بنی امیه را مدح گفته است . بیشتر اشعار او در وصف شراب، غزل و فخر است . (از الاعلام زرکلی ).<br /></font></div>'),
(180516, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن ادریس بن مننجری ادریسی الحسنی التلمسانی . وی به مغرب از شیوخ عصر خود بود. از تألیفات او است : حاشیه ٔ علی الجعبری . حاشیة علی فتح المنان . حاشیة علی المرادی . وی به سال <span class=\"hlight\" dir=\"rtl\">١١٧٩</span> هَ . ق . به فاس درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180517, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن ادریس بن محمد العراقی الحسینی، مکنی به ابن ابوالعلا فاضل مالکی و از مردم فاس بود. از تألیفات او است : مختصر فی الصحابه . الجرح و التعدیل . وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٣٤</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180518, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن احمد الصنادیقی الشافعی وی از فقهاء بود از تألیفات اوست : شرح البردة. شرح الشمائل . وی به سال <span class=\"hlight\" dir=\"rtl\">١١٦٤</span> هَ . ق . به دمشق درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180519, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن احمدبن یونس بن عبدالاعلی، مکنی به ابوسعید معروف به الصدفی منسوب به قبیله ٔ صدف از قبائل حمیریه است . رجوع به صدفی عبدالرحمان شود.<br /></font></div>'),
(180520, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) جدی جاهلی است و فرزندان او بطنی از زهیر از جذامند. خانه های آنان در دقهلیه و مرتاحیة از دیار مصر بود. (از الاعلام زرکلی ).<br /></font></div>'),
(180521, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b>(اِخ ) ابن احمدبن محمد الجامی . رجوع به جامی شود.<br /></font></div>'),
(180522, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن احمدبن علی، مکنی به ابوالفضل المیکالی . ادیب و از امراء میکالیین خراسان بود. او را شعری رقیق است و تألیفاتی دارد از جمله مخزون البلاغة. ملح الخواطر و منح الجواهر. دیوان رسائل و دیوان شعر.وی به سال <span class=\"hlight\" dir=\"rtl\">٤٣٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180523, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن احمدبن عطیة العنسی المذحجی، مکنی به ابوسلیمان و معروف به دارائی و از مردم داریا است . رجوع به ابوسلیمان دارائی شود.<br /></font></div>'),
(180524, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن احمدبن عبدالغفار الایجی معرف به عضدالدین ایجی عالم به اصول و معانی و عربیت و از اهل ایج فارس بود وی قضاوت یافت و شاگردان بزرگ تربیت کرد. از تألیفات اوست : مواقف در اصول دین . اشرف التواریخ . جواهرالکلام . مختصر المواقف . شرح مختصر ابن حاجب و فوائد الغیاثیه در معانی و بیان . وی به سال <span class=\"hlight\" dir=\"rtl\">٧٥٦</span> هَ . ق . درگذشت . (ازالاعلام زرکلی ). و رجوع به روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٣٠</span> شود.<br /></font></div>'),
(180525, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن احمدبن رجب سلامی بغدادی دمشقی . حافظ حدیث و از علماء بود. به سال <span class=\"hlight\" dir=\"rtl\">٧٠٦</span> هَ . ق . به بغداد متولد شد و در <span class=\"hlight\" dir=\"rtl\">٧٩٥</span> هَ . ق . به دمشق درگذشت از تألیفات اوست : شرح جامع الترمذی وشرح الاربعین للنووی، فتح الباری فی شرح البخاری، شرح علل الترمذی، طبقات الحنابله . (از الاعلام زرکلی ).<br /></font></div>'),
(180526, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن احمدبن حمودةبن مامش باش تارزی از فضلاء متصوفه بود وی در قسطنطنیه طریقه رحمانیه را منتشر کرد و از تألیفات اوست : عمدة المرید در طریقت و منظومة الرحمانیة و غنیة المرید. وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٢٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180527, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن احمدبن الحسن بن بندار العجلی الرازی، مکنی به ابوالفضل . فاضل و عارف به ادب بود وی به سال <span class=\"hlight\" dir=\"rtl\">٤٥٤</span> هَ . ق . درگذشت .از تألیفات اوست : جامع الوقوف . (از اعلام زرکلی ).<br /></font></div>'),
(180528, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن احمد، مکنی به ابوعمر معروف به ابی ذکوان . عالم به قراآت و از شیوخ قراء شام بود. وی به سال <span class=\"hlight\" dir=\"rtl\">١٧٣</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">٢٠٢</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180529, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن ابی زنادبن عبداﷲبن ذکوان القرشی ... از حفاظ حدیث بود. ولایت خراج مدینه را یافت، و به بغداد سفر کرد. وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٠</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٧٤</span> در بغداد درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180530, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن ابراهیم بن عمرو الاموی . محدث شام بود و قضاوت اردن و فلسطین یافت . وی به سال <span class=\"hlight\" dir=\"rtl\">١٧٠</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">٢٤٥</span> به دمشق درگذشت . (از الاعلام زرکلی ). و رجوع به تاریخ الخلفاء ص <span class=\"hlight\" dir=\"rtl\">٢٦٠</span> شود.<br /></font></div>'),
(180531, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن ابراهیم بن عبدالرحمان موصلی از بزرگان شعرا در عصر خود بود.او را دیوانی است در شعر. وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٣١</span> هَ . ق . به دمشق متولد و در <span class=\"hlight\" dir=\"rtl\">١١١٨</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180532, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن ابراهیم بن احمد مشهور به ابن عبدالرزاق . از فضلاء دمشق بود و او را کتابی است به نظم، به نام قلائد المنظوم که در حدود <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> بیت و در فرائض است و نیز او راست : مفتاح الاسرار فی شرح الدرالمختار. وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٧٥</span> هَ .ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١١٢٨</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180533, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن عبدالرحمان العلیمی ملقب به زین الدین و مکنی به ابوالیمن الُعلیمی . وی مورخ و قاضی القضاة قدس بود. از تألیفات اوست : الانیس الجلیل فی تاریخ القدس و الخلیل در دو مجلد. المنهج الاحمد فی تراجم اصحاب الامام احمد. فتح الرحمان فی تفسیر قرآن . وی به سال <span class=\"hlight\" dir=\"rtl\">٨٦٠</span> هَ . ق . متولد و به سال <span class=\"hlight\" dir=\"rtl\">٩٢٨</span> به قدس درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180534, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن عیسی بن فطیس بن اصبغ. عالم به تفسیر، حدیث، تاریخ، رجال و از مردم اندلس بود. به سال <span class=\"hlight\" dir=\"rtl\">٣٤٨</span> هَ . ق . به قرطبه متولد و به سال <span class=\"hlight\" dir=\"rtl\">٣٩٤</span> هَ . ق . قضاوت آنجا را یافت و به سال <span class=\"hlight\" dir=\"rtl\">٣٩٤</span> معزول شد. وی را شش تن وراق بود که همیشه احادیث و اخباری را که املاء میکرد مینوشتند. از تألیفات اوست : القصص و الاسباب التی نزل من اجلها القرآن زیاده بر یکصد جزء. المصابیح فی تراجم الصحابه در حدود <span class=\"hlight\" dir=\"rtl\">١٠٠</span> جزء. فضائل التابعین در <span class=\"hlight\" dir=\"rtl\">١٥٠</span> جزء. الناسخ و المنسوخ در <span class=\"hlight\" dir=\"rtl\">٣٠</span> جزء. فاسعاالاخوة من المحدثین من الصحابة و التابعین و من بعدهم من الخالفین در <span class=\"hlight\" dir=\"rtl\">٤٠</span> جزء. الاعلام النبوة و دلالات المرسلات در <span class=\"hlight\" dir=\"rtl\">١٠</span> جزء. وی به سال <span class=\"hlight\" dir=\"rtl\">٤٠٢</span> هَ . ق . به قرطبه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180535, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن علی الانصاری الاسیدی معروف به دباغ و مکنی به ابوزید. مورخ و فقیه و از مردم قیروان بود. از تألیفات اوست : معالم الایمان فی معرفة اهل القیروان در چهار جزء. تاریخ ملوک الاسلام . جلاء الافکار فی مناقب الانصار و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">٦٠٥</span> هَ . ق . به قیروان متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٦٩٩</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180536, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن علی معروف به ابویزید البسطامی . رجوع به ابویزید طیفور شود.<br /></font></div>'),
(180537, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن عسکر البغدادی، مکنی به ابوزید یا ابومحمد ملقب به شهاب الدین . وی فقیه مالکی و از مدرسان مدرسه ٔ مستنصریه بود. از تألیفات اوست : ارشاد السالک . جامع الخیرات فی الاذکار والدعوات . المعتمد و النورالمقتبس من فوائد مالک بن انس . وی به سال <span class=\"hlight\" dir=\"rtl\">٦٤٤</span> هَ . ق .متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٧٣٢</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180538, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن عزیز. وی عالم به عربیت و از مردم خراسان و گوش او کر بود. از تألیفات اوست : رد علی الزجاجی فیما استدرکه علی ابن السکیت فی اصلاح المنطق .وی به سال <span class=\"hlight\" dir=\"rtl\">٤٣١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180539, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن عبیداﷲ الانصاری، مکنی به ابوالبرکات و ملقب به کمال الدین و معروف به ابن انباری . رجوع به ابن انباری کمال الدین شود.<br /></font></div>'),
(180540, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن عبدالملک بن عبدالرحمان الناصر الاموی معروف به المرتضی الاموی وی امیر بود و در قرطبه اقامت داشت و چون سلیمان بن حکم به قتل رسید و علی بن حمود بر ملک استیلا یافت عبدالرحمان پوشیده از قرطبه بیرون شد و بعضی از مخالفان ابن حمود با وی بیعت کردند و او را مرتضی لقب دادند وبا وی به صنهاجه و سپس به غرناطه رفتند لکن زاوی بن زیزی حاکم قرطبه با آنان نبرد کرد. سپس پیروان عبدالرحمان با وی ازدر مخالفت برآمدند و کسی را معین کردند و ناگهان او را بکشت، وی به سال <span class=\"hlight\" dir=\"rtl\">٣٦٨</span> هَ . ق . متولدو در <span class=\"hlight\" dir=\"rtl\">٤٠٨</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180541, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن عبداﷲبن یوسف بن عیسی بن حبیش الانصاری الاندلسی المرسی . رجوع به عبدالرحمان محمدبن عبداﷲ انصاری شود.<br /></font></div>'),
(180542, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن عبداﷲبن محمدبن عبدالرحمان بن الحکم بن هشام بن عبدالرحمان الداخل، مکنی به ابوالمطرف . وی نخستین کسی از امویان اندلس است که لقب خلافت یافت . تولد او به قرطبه بود و <span class=\"hlight\" dir=\"rtl\">٢١</span> روز از عمر وی گذشته بود که پدرش را بکشتند و جد او تربیت وی را بعهده گرفت و چون جدش به سال <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> هَ . ق . درگذشت اعمام وی به خاطرمحبتی که جد عبدالرحمان نسبت بدو داشت با او به امارت اندلس بیعت کردند. عبدالرحمان مردی زیرک و جاه طلب بود. وی از ابتدا آرامش ملک را فراهم آورد و چون ازضعف المقتدر باﷲ آگاه شد مردمان را فراهم آورد و آنان را خطبه خواند و سبقت بنی امیه را در خلافت فرایاد ایشان آورد. سرانجام به سال <span class=\"hlight\" dir=\"rtl\">٣١٦</span> هَ . ق . مردم با وی به خلافت بیعت کردند و الناصرلدین اﷲ لقب یافت . گویندعبدالرحمان بزرگترین و عظیم الشأن ترین امراء بنی امیه در اندلس بود و به برآوردن بنا سخت مولع بود و قصرالزهرا را برآورد. وی <span class=\"hlight\" dir=\"rtl\">٥٠</span> سال و شش ماه حکومت کرد درحکومت بغایت آگاه و سختگیر بود چنانکه وی را فرزندی بود به نام عبداﷲ که دعوی خلافت کرد و گروهی با او بیعت کردند عبدالرحمان او را در عید قربان سال <span class=\"hlight\" dir=\"rtl\">٣٣٩</span> هَ. ق . بدست خود بکشت و گفت این قربانی من است و شما را نیز قربانی باید سپس هر یک از آنها یک تن از اصحاب عبداﷲ را قربانی کردند. وی به سال <span class=\"hlight\" dir=\"rtl\">٢٧٧</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180543, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن عبداﷲ معروف به ابن امام و مکنی به ابوزید. فقیه و مجتهد و از مردم تلمسان و از علماء مغرب بود. در تونس علم آموخت و به الجزایر رفت سپس به تلمسان بازگشت و از خواص سلطان ابوالحسن مرینی شد. وی به سال <span class=\"hlight\" dir=\"rtl\">٧٤٣</span> هَ . ق . به تلمسان درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180544, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن عبداﷲ الانصاری الاندلسی . مورخ و عالم به عربیت و از حفاظ حدیث بود. وی قضاوت جزیره ٔ شقر و مرسیه را یافت . به سال <span class=\"hlight\" dir=\"rtl\">٥٨٤</span> هَ . ق . به مرسیه درگذشت .او راست : المغازی در چند مجلد. (از الاعلام زرکلی ).<br /></font></div>'),
(180545, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن عبدالعزیز اللخمی مشهور به ارزنجانی و ملقب به وجیه الدین . از فضلا بود. او راست : حدائق الازهار فی شرح مشارق الانوار. وی به سال <span class=\"hlight\" dir=\"rtl\">٥٥٥</span> هَ . ق . متولد و به سال <span class=\"hlight\" dir=\"rtl\">٦٤٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180546, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن کمال الدین محمد الحسینی معروف به ابن النقیب . در عصر خود ادیب دمشق بود و شعر نیکو میگفت . به سال <span class=\"hlight\" dir=\"rtl\">١٠٤٨</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٠٨١</span> هَ . ق . به دمشق درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180547, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن سلیمان معروف به شیخی زاده . فقیه حنفی بود.از تألیفات اوست : مجمع الابهر فی شرح ملتقی الابحر. وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٧٨</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180548, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َدُرْ رَ ]</font></b> (اِخ ) ابن محمدبن سلم الرازی . از حفاظ حدیث و امام جامع اصفهان بود. او راست : مسند و تفسیری .وی به سال <span class=\"hlight\" dir=\"rtl\">٢٩١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180549, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن رشیدالقیروانی . مورخ، فقیه، حافظ حدیث و شاعر بود. از تألیفات اوست : المستوعب لزیادات مسائل المبسوط ممالیس فی المدونة.وی به سال <span class=\"hlight\" dir=\"rtl\">٣٨٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180550, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن حسن معروف به ابن عساکر. رجوع به ابن عساکر ابومنصور عبدالرحمان شود.<br /></font></div>'),
(180551, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن امیرویه الکرمانی فقیه حنفی بود که ریاست مذهب حنفی در خراسان بدو پایان یافت . وی به سال <span class=\"hlight\" dir=\"rtl\">٤٥٧</span> هَ . ق . به کرمان متولد و در <span class=\"hlight\" dir=\"rtl\">٥٤٣</span> به مرو درگذشت . از تألیفات اوست : التجرید در فقه . الایضاح در شرح الجامع الکبیر و غیره . (از الاعلام زرکلی ).<br /></font></div>'),
(180552, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن الاشعث ابن قیس الکندی . امیر و از سران شجعان عرب بود. او را حجاج با لشکری به نبردبا بلاد رتبیل (سجستان ) فرستاد چون به سجستان رسید با سرکردگان لشکر اتفاق کرد تا حجاج را از سرزمین عراق خارج کنند اما سران لشکریان پیمان خود را با وی نقض و میان آنها نبردی درگرفت که به پیروزی عبدالرحمان پایان یافت و سرانجام ملک سجستان و کرمان و بصره و فارس را جز خراسان تصرف کرد اما سپس بصره را از دست داد و کوفه را متصرف شد و میان او و حجاج نبردی در دیرالجماجم درگرفت که مدت <span class=\"hlight\" dir=\"rtl\">١٠٣</span> روز بطول انجامید سرانجام ابن اشعث از کوفه رانده شد لشکریان او که بالغ بر<span class=\"hlight\" dir=\"rtl\">٦٠</span> هزار نفر بودند پی در پی شکست خوردند و از دور او پراکنده شده وی با عده ٔ کمی از یاران خود به رتبیل پناه برد و مدتی در آنجا بماند در این موقع نامه هائی از حجاج برای رتبیل میرسید که ابن اشعث را بدو سپارند تا آنکه سرانجام رتبیل او را به سال <span class=\"hlight\" dir=\"rtl\">٨٥</span> هَ . ق . به قتل رساند و سر او را برای حجاج فرستاد. (از الاعلام زرکلی ). و رجوع به کامل ابن اثیر ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٠</span> شود.<br /></font></div>'),
(180553, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span><font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن ادریس بن المنذر التمیمی الحنظلی الرازی . حافظ حدیث و از بزرگان آنان بود منزل و مأوای وی در درب حنظله به ری بود. از تألیفات او است : الجرح و التعدیل در <span class=\"hlight\" dir=\"rtl\">٦</span> مجلد. التفسیر در چند مجلد. الرد علی الجهمیة. علل الاحادیث . المسندالکبیر. الکنی و الفوائد الکبری . (از الاعلام زرکلی ).<br /></font></div>'),
(180554, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن اسحاق بن منده العبدی الاصبهانی . از بزرگان علماء دین بود وی را اصحاب و یاران زیادی بود و کتب زیادی تألیف کرده است . مولد وی اصفهان و به سال <span class=\"hlight\" dir=\"rtl\">٤٧٠</span> هَ . ق . در همانجا درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180555, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ]</font></b> (اِخ ) ابن محمدبن احمدبن قدامه المقدسی ... معروف به ابن قدامه . رجوع به ابن قدامه ابوعمر محمد شود.<br /></font></div>'),
(180556, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن احمدبن فوران . فقیه و از علماء اصول و فروع و پیشوای فقهای شافعی به مرو بود دراصول و ملل و نحل کتابهائی نوشته است . از جمله کتب او الابانة در مذهب شافعی است . وی به سال <span class=\"hlight\" dir=\"rtl\">٣٨٨</span> به مرو متولد و در <span class=\"hlight\" dir=\"rtl\">٤٦١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180557, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َدُرْ رَ ]</font></b> (اِخ ) ابن محمدبن ابراهیم العتائقی . از علماء حله بود و فلسفه و تاریخ نیز آموخت . به بلاد فارس و غیره مسافرت کرد، مدت زیادی به اصفهان اقامت گزید و به نجف رفت . از تألیفات اوست : کتاب الاعمار مختصر تفسیر علی بن ابراهیم . صفوة الصفوة. شرح منظومه در هیئت و شرح ایلامی در طب و غیره . وی به سال <span class=\"hlight\" dir=\"rtl\">٦٩٩</span> هَ . ق . متولد و در حدود <span class=\"hlight\" dir=\"rtl\">٧٩٠</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180558, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َدُرْ رَ ]</font></b> (اِخ ) ابن محلی . فقیه شافعی مصری بود. به دمیاط سکونت جست . او راست : کشف القناع عن متن و شرح ابی شجاع در فقه و حاشیه بر تفسیر بیضاوی . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٩٨</span> هَ . ق . به دمیاط درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180559, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن مسلم بن عمرو الباهلی شریفی از شجعان بود. وی برادر قتیبةبن مسلم است و به سال <span class=\"hlight\" dir=\"rtl\">٩٦</span> هَ . ق . بابرادرش به فرغانه به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180560, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن یزیدبن جاریة الانصاری المدنی . وی تابعی و از رجال حدیث بود. در حیات رسول (ص ) متولد شد. عمربن عبدالعزیز او را قضاوت داد. به سال <span class=\"hlight\" dir=\"rtl\">٩٨</span> هَ . ق . به مدینه درگذشت . (از الاعلام زرکلی ) (سیره ٔ عمربن عبدالعزیز) (عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٢</span>).<br /></font></div>'),
(180561, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span><font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن هشام بن عبداﷲبن اسماعیل بن شریف از ملوک دولت اشراف علویین مراکش بود که به سال <span class=\"hlight\" dir=\"rtl\">١٢٣٨</span> هَ . ق . مردم با وی بیعت کردند. وی مردی عالم و علم دوست بود و در نشر علوم و صنعت و فلاحت همت گماشت به سال <span class=\"hlight\" dir=\"rtl\">١٢٧٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180562, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن یزیدبن المهلب الازدی . از امراء ازد و از شجعان و موالی بنی امیه بود. به سال <span class=\"hlight\" dir=\"rtl\">١٣٣</span> هَ . ق . با آنکه عباسیان به وی خطامان داده بودند او را بکشتند. (از الاعلام زرکلی ).<br /></font></div>'),
(180563, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ثقفی بن ابی بکر ثقفی از اعیان تابعین بود. زیاد امیر بصره او را پاره ای شغلها داد. وی به سال <span class=\"hlight\" dir=\"rtl\">٩٦</span> هَ . ق . در بصره درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180564, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن خواجه کلان . از قضاة هرات در زمان حکومت محمدخان شیبانی است که در مدرسه ٔ گوهرشادآغا تدریس میکرد. (از حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٩</span>).<br /></font></div>'),
(180565, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن هشام بن عبدالجباربن عبدالرحمان الناصر ملقب به المستظهر الاموی .وی هنگامی که خلافت عباسیان بضعف گرائید به امارت قرطبه رسید و مردم به سال <span class=\"hlight\" dir=\"rtl\">٤١٤</span> هَ . ق . با وی به خلافت بیعت کردند. محمدبن عبدالرحمان بن عبیداﷲبن عبدالرحمان الناصر بهمراهی گروهی بر وی طاغی شد و پس از <span class=\"hlight\" dir=\"rtl\">٧٤</span> روزخلافت او را به سال <span class=\"hlight\" dir=\"rtl\">٤١٤</span> بکشتند. (از الاعلام زرکلی ).<br /></font></div>'),
(180566, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن وهیب بن عبداﷲ القوصی . وی شاعری سبک و در زمره ٔ کتاب بود. وزارت المظفر یافت . سپس مغضوب و زندانی شد و به فرمان وی در حدود سال <span class=\"hlight\" dir=\"rtl\">٦٤٥</span> هَ . ق . خفه شد. (از الاعلام زرکلی ).<br /></font></div>'),
(180567, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن نُفَیعبن الحارث الثقفی البصری، مکنی به ابوبحر. وی تابعی و از رجال حدیث بود. از جانب علی بن ابی طالب (ع ) ولایت بیت المال یافت . سپس زیادبن ابیه او را بدین سمت برگزید. وی به سال <span class=\"hlight\" dir=\"rtl\">١٤</span> هَ . ق . متولد شد و در سال <span class=\"hlight\" dir=\"rtl\">٩٦</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180568, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن مهدی بن حسان العنبری البصری اللؤلؤی . از ائمه ٔ حفاظ و داناترین کس به حدیث در عصر خود بود. او را در حدیث تصنیفاتی است . وی به سال <span class=\"hlight\" dir=\"rtl\">١٣٥</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٩٨</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180569, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن موسی . یکی از فرزندان امام موسی کاظم است . (از حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨١</span>).<br /></font></div>'),
(180570, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن ملجم المرادی التدؤلی الحمیری . رجوع به ابن ملجم عبدالرحمان شود.<br /></font></div>'),
(180571, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن معاویةبن هشام بن عبدالملک بن مروان ملقب به صقر قریش و معروف به الداخل الاموی . وی مؤسس دولت امویان به اندلس است .در کودکی پدر خود را از دست داد و در دارالخلافه تربیت شد هنگامی که سلطنت امویان در شام منقرض گشت عبدالرحمان در دهی نزدیک فرات سکونت جست و چون او را تعقیب کردند قصد مغرب کرد و به افریقا رفت . عبدالرحمان بن حبیب فهری به طلب وی خاست . وی به مکناسه میان قوم مادر خود رفت و مدتی بماند و با امویان اندلس مکاتبه کرد و آنان کشتی با جماعتی از بزرگان خویش فرستادندو اطاعت خود را نسبت به وی اعلام کردند و او را به اندلس بازگرداندند والی اندلس یوسف بن عبدالرحمان فهری با وی جنگ کرد. عبدالرحمان پیروز شد و مقر حکومت خود را به قرطبه برد و در آنجا قصری و چند مسجد ساخت وخطبه به نام منصور عباسی خواند و چون کار او استوارشد امارت خود را مستقل اعلام کرد. منصور عباسی نخستین کسی است که او را صقرقریش لقب داد وی مردی شجاع، سخی، شاعر و عالم بود و به سال <span class=\"hlight\" dir=\"rtl\">١١٣</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">١٧٢</span> هَ . ق . به قرطبه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180572, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن مأمون النیشابوری، مکنی به ابوسعد. فقیه و عالم به اصول بود. به سال <span class=\"hlight\" dir=\"rtl\">٤٢٦</span> هَ . ق . به نیشابور متولد شد و درس وعلم آموخت و سمت مدرسی مدرسه ٔ نظامیه ٔ بغداد یافت . از تألیفات اوست : تتمة الابانة للفورانی در فقه شافعی و کتابی در الفرائض و کتابی در اصول دین . وی به سال <span class=\"hlight\" dir=\"rtl\">٤٧٨</span> هَ . ق . به بغداد درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180573, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن مسلم معروف به ابومسلم خراسانی . رجوع به ابومسلم خراسانی در این لغت نامه و الاعلام زرکلی شود.<br /></font></div>'),
(180574, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن مخنف الازدی . قائد و از شجعان دولت مروانیه بود. ریاست از دشنوءة و از دعمان به وی رسید و به سال <span class=\"hlight\" dir=\"rtl\">٧٥</span> هَ . ق . به کازرون کشته شد. (از الاعلام زرکلی ).<br /></font></div>'),
(180575, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span><font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمد فراسی . شاعری بذله گوو هجاگوی و شریر بود و در بنی فراس از قراء تونس متولد شد و در تونس ادب آموخت و به سال <span class=\"hlight\" dir=\"rtl\">٤٠٨</span> هَ . ق . در حال مستی از بام بیفتاد و بمرد. (از الاعلام زرکلی ).<br /></font></div>'),
(180576, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمد السلمی الاندلسی . او را رسائل و مقامات و شعر است . وی به سال <span class=\"hlight\" dir=\"rtl\">٥٩١</span> هَ . ق . به مراکش درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180577, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ )ابن محمد الذهبی معروف به ابن شاشو. از فضلاء و از مردم دمشق بود. او راست : تراجم بعض اعیان دمشق . وی درحدود سال <span class=\"hlight\" dir=\"rtl\">١١٢٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180578, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدالتمنارتی المغربی . وی فقیه مالکی و از مردم تارودانت بود.از تألیفات اوست : الفوائد الجمة باسناد علوم الامة.وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180579, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن یوسف القصری الفاسی معروف به القصری . وی فقیه و عالم به لغت و اصول و حدیث بود. از تألیفات اوست : حاشیة علی البخاری و حاشیة علی الجلالین . حاشیه ای بر شرح صغری سنوسی و حواشی دیگر. وی به سال <span class=\"hlight\" dir=\"rtl\">٩٧٢</span> هَ . ق . متولد شد. و به سال <span class=\"hlight\" dir=\"rtl\">١٠٣٦</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180580, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن مخلوف الثعالبی جزائری مکنی به ابوزید. مفسر و از اعیان جزائر بود. از اوست : الجواهرالحسان فی تفسیر قرآن در چهار مجلد. الانوار فی المعجزات النبویة. روضة الانوار و نزهة الاخیار. جامع الامهات فی احکام العبادات . الذهب الابریر فی غریب القرآن . الارشاد فی مصالح العباد. ریاض الصالحین . وی به سال <span class=\"hlight\" dir=\"rtl\">٧٨٦</span> هَ . ق .متولد شد و در سال <span class=\"hlight\" dir=\"rtl\">٨٧٥</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180581, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن محمد خلدون، مکنی به ابوزید. رجوع به ابن خلدون ابوزید عبدالرحمان در این لغت نامه و الاعلام زرکلی شود.<br /></font></div>'),
(180582, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ]</font></b> (اِخ ) ابن محمدبن محمدبن عمادالدین معروف به عمادی مفتی دمشق و از بزرگان و شیوخ آن سامان بود. از تألیفات اوست : الروضة الریا فی من دفن بداریا در تراجم . المستطاع من الزاد در فقه حنفی . تحریر التأویل در تفسیر. و او را شعری است . وی به سال <span class=\"hlight\" dir=\"rtl\">٩٧٨</span> هَ . ق . متولد شد. و در سال <span class=\"hlight\" dir=\"rtl\">١٠٥١</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180583, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن محمدبن الحسین بن محمدبن جابربن خلدون . رجوع به ابن خلدون شود.<br /></font></div>'),
(180584, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن صخرة الدوسی ملقب به ابوهریره . رجوع به ابوهریره عبدالرحمان شود.<br /></font></div>'),
(180585, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن کمال الدین ابی بکربن ناصرالدین محمد سیوطی . از علماء علم عربیت و ادبا، بزرگ عصرخود بود. سیوطی را تألیفات متعددی است از جمله کتاب الاتقان در علوم قرآن . کتاب الجامع الکبیر. الجامع الصغیر. المسلسلات . الکلم الطیب . الدرر فی الادعیه و الاحراز. انموذج اللبیب فی خصائص الحبیب . کتاب ذخائر العقبی فی مناقب اولی القربی . الدرر المنتشره فی احادیث المشتهره . جمع الجوامع. کتاب بهجة المرضیه . ارجوزه در تلخیص مفتاح سکاکی . مختصر نهایه ٔ ابن اثیر. التذکرة، المقامات و کتابهای زیاد دیگر. مؤلف روضات وفات او را به سال <span class=\"hlight\" dir=\"rtl\">٩١٠</span> و مؤلف کشف الظنون به سال <span class=\"hlight\" dir=\"rtl\">٩١١</span> هَ . ق . نوشته اند. رجوع به روضات الجنات چ <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣٢</span> به بعد و رجوع به کشف الظنون ذیل الجامع الصغیر شود.<br /></font></div>'),
(180586, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عبداﷲبن حارت الهمدانی . رجوع به اعشی همدانی شود.<br /></font></div>'),
(180587, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عبداﷲبن بشربن الصارم معروف به الغافقی، مکنی به ابوسعید. اصل او از غافق (از قبائل یمن ) است وی به نزد سلیمان بن عبدالملک اموی رفت و به موسی بن نصیرو فرزند او عبدالعزیز پیوست و ریاست شاطی ٔ شرقی اندلس یافت و چون سمح بن مالک به سال <span class=\"hlight\" dir=\"rtl\">١٠٢</span> هَ . ق . کشته شد به اربویه رفت مسلمانان آنجا وی را به امیری برگزیدند سپس معزول گردید و به سال <span class=\"hlight\" dir=\"rtl\">١١٢</span> هَ . ق . هشام بن عبدالملک او را امارت اندلس داد. در آن وقت از مردم یمن و شام و مصر و افریقا یاری خواست و شهرهای زیادی را فتح کرد و به کمک آنان به لشکریان شارل مارتل حمله کرد و آنان را شکست داد و دیگر بار در نزدیکی نهراللواز با وی نبرد کرد و سرانجام شارل دیگر بار لشکری بزرگ فراهم آورد و پس از جنگهای خونینی عبدالرحمان به سال <span class=\"hlight\" dir=\"rtl\">١١٤</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180588, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عبداﷲبن احمد الخثعمی السهیلی، مکنی به ابوالقاسم و معروف به سُهیلی وی از لغویان بود به سال <span class=\"hlight\" dir=\"rtl\">٥٠٨</span>هَ . ق . در مالقه متولد شد و چون شهرتی یافت مورد لطف پادشاه مراکش واقع گشت از تألیفات اوست : الروض الانف در شرح سیره ٔ نبویه ابن هشام . التعریف و الاعلام فی ماابهم فی القرآن من الاسماء و الاعلام . نتائج الفکر.وی به سال <span class=\"hlight\" dir=\"rtl\">٥٨١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180589, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عبداﷲبن احمد البعلی الخلوتی الحنبلی معروف به عبدالرحمان البعلی به سال <span class=\"hlight\" dir=\"rtl\">١١١٠</span> هَ . ق . به دمشق متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">١١٩٢</span> هَ . ق . در حلب درگذشت او راست : شرح اخصر المختصرات در فقه . و او را اشعاری است . (از الاعلام زرکلی ).<br /></font></div>'),
(180590, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عبداﷲبن احمدبن اصبغبن جیش ...، مکنی به ابوالقاسم سهبلی ... وی عالم به عربیت و لغت و قراآت و جامع بین روایت و درایت و از نحویان متقدم و ادبای عالیمقام و عالم به تفسیر و حدیث و رجال و انساب و کلام و اصول و تاریخ بود. از ابن غربی و ابن طاهر و ابن طراوة روایت کند. او را مؤلفاتی است . (از روضات الجنات چ <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢٩</span>).<br /></font></div>'),
(180591, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َدُرْ رَ ]</font></b> (اِخ ) ابن عبداﷲبن ابی عقیل ثقفی معروف به ام الحکم . یکی از امراء عصر اموی بود. مادر او ام حکم خواهر معاویةبن ابوسفیان است . وی در زمان پیغمبر (ص ) متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٥٣</span> هَ . ق . در جنگ روم شرکت جست . از طرف معاویه ولایت کوفه یافت، و در اثر بدرفتاری وی مردم کوفه او را بیرون کردند آنگاه به شام رفت و ولایت مصر یافت . ابن خدیج از ورود او ممانعت کرد، سپس به شام برگشت، و ولایت جزیره یافت در سال <span class=\"hlight\" dir=\"rtl\">٦٦</span> هَ . ق .در آغاز خلافت عبدالملک درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180592, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عبداﷲ ابی بکربن الصدیق بن ابوقحافة القرشی التیمی صحابی و ابن صحابی است . نام او در جاهلیت عبدالکعبه بود حضرت رسول (ص ) او را عبدالرحمان نامید وی از اشجع قریش و از تیراندازن ماهر بود، به یمامه رفت و در جنگ افریقیه شرکت داشت و در واقعه ٔ جمل حاضر بود. هنگامی که معاویه درصدد اخذ بیعت برای یزید برآمد، عبدالرحمان گفت مگر خلافت اسلامی هرقلی است که چون قیصری مرد قیصری دیگر بجای او نشیند، معاویه صدهزار درهم برای او فرستاد و عبدالرحمان آن را نپذیرفت، سپس به مکه رفت و پیش از آنکه کار بیعت یزید تمام شود درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180593, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْرَ ]</font></b> (اِخ ) ابن عبدالقاری . از بزرگان تابعین مدینه بود. در عهد عمر بیت المال را به عهده داشت . وی به سال <span class=\"hlight\" dir=\"rtl\">٨٨</span> هَ . ق . به مدینه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180594, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span><font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عبدالقادر المالکی . فقیه است . از تألیفات او است : کتاب «المغارسة» و شرح آن که در آن مسائل و احکام مربوط به غرس را نوشته است . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٢٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180595, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عبدالقادر الفاسی . فقیهی متفنن بود او را در حدود هفتادو اندی تألیف است از آن جمله، مفتاح الشفا، که ذیل کتاب شفاست . ازهارالبستان و الاقنوم فی مباحث العلوم . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٤٠</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">١٠٩٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180596, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عبدالرزاق معروف به ابن مکانس . رجوع به به ابن مکانس فخرالدین شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(180597, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عبداﷲبن حسین سویدی بغدادی مورخ و از خانواده های قدیمی بغداد بود از تألیفات او است : حدیقة الزوراء در سه جزء در تاریخ بغداد. حاشیة علی شرح القطر عصامی . وی به سال <span class=\"hlight\" dir=\"rtl\">١١٣٤</span> هَ . ق . متولد و در<span class=\"hlight\" dir=\"rtl\">١٢٠٠</span> هَ . ق . به بغداد درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180598, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن سمرةبن حبیب بن شمس القرشی، مکنی به ابوسعید. صحابی است که روز فتح مکه اسلام آورد و در بصره ساکن شد. وی سجستان و کابل و نواحی دیگر را فتح کرد و ولایت سجستان (سیستان ) یافت و در خراسان فتوحاتی کرد. سپس به بصره بازگشت . و در صحیحین از وی <span class=\"hlight\" dir=\"rtl\">١٤</span> حدیث نقل شده است . و به سال <span class=\"hlight\" dir=\"rtl\">٥٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ) (تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٨٥</span> و <span class=\"hlight\" dir=\"rtl\">٨٤</span>).<br /></font></div>'),
(180599, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن سعیدبن قیس الهمدانی . مردی شجاع و از اشراف یمن بود. وی به همراهی گروه بسیاری از مردم یمن با مختار ثقفی نزدیک کوفه نبرد کرد و در یکی از نبردها به سال <span class=\"hlight\" dir=\"rtl\">٦٦</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180600, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ]</font></b> (اِخ ) ابن زیدبن الخطاب العدوی القرشی . زوجه ٔ وی دختر عمربن خطاب بود و از طرف یزیدبن معاویه ولایت یافت . وی در حدود سال <span class=\"hlight\" dir=\"rtl\">٦٥</span> هَ . ق . به مکه درگذشت . (از الاعلام زرکلی ) (سیره ٔ عمربن عبدالعزیز صص <span class=\"hlight\" dir=\"rtl\">٨١</span> - <span class=\"hlight\" dir=\"rtl\">١٧٨</span>).<br /></font></div>'),
(180601, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن زید معروف به ابن البیلمانی . اصل او از یمن و مسکن او حران . شاعری مجید بود. ولید اموی را مدح گفت . و در حدود سال <span class=\"hlight\" dir=\"rtl\">٩٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180602, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن زیادبن انعم المعافری افریقی، مکنی به خالد قاضی و از علماء بود و به جرأت، بر ملوک و ممانعت آنان از جور و ستم شهرت داشت . وی به سال <span class=\"hlight\" dir=\"rtl\">٧٥</span> هَ . ق . به برقه متولد شد و نخستین کس از مسلمانان است که در افریقا متولد شد. او دوبار قضاوت قیروان یافت . سپس به بغداد رفت و سپس در خلافت منصور عباسی بدو پیوست و مورد توجه او واقع شد. پس از آنکه منصور به خلافت رسید او را به قیروان فرستاد. و به سال <span class=\"hlight\" dir=\"rtl\">١٦١</span> هَ . ق . در همانجا درگذشت . (از الاعلام زرکلی ) (الوزراء و الکتاب ص <span class=\"hlight\" dir=\"rtl\">١٨</span>) (تاریخ مصر ص <span class=\"hlight\" dir=\"rtl\">١٢١</span>).<br /></font></div>'),
(180603, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن ربیعةبن یزیدالباهلی ملقب به ذالنور بود. وی از جانب عمربن الخطاب قضاء لشکریانی که به قادسیه میرفتند یافت . سپس او را ولایت باب وقتال، با ترکان و خزران داد. وی به سال <span class=\"hlight\" dir=\"rtl\">٣٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ). و رجوع به ذوالنور شود.<br /></font></div>'),
(180604, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع ِ دُرْ رَ ]</font></b> (اِخ ) ابن رافع التنوخی المصری . قاضی افریقاو از رجال حدیث بود. یکی از یازده تن است که عمربن عبدالعزیز آنان را برای تعلیم فقه به افریقا فرستاد.وی به سال <span class=\"hlight\" dir=\"rtl\">١١٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180605, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن داود الدمشقی الصالحی . فاضل و از مردم دمشق بود. از تألیفات اوست : الکنز الاکبر فی الامر بالمعروف و النهی عن المنکر در دو مجلد. فتح الاغلاق فی الحث علی مکارم الاخلاق . مواقع الانوار و مآثر المختار. تحفة العباد فی ادلة الاوراد و نزهة النفوس و الافکار فی خواص الحیوانات و النبات و الاحجار در سه مجلد. وی به سال <span class=\"hlight\" dir=\"rtl\">٧٨٢</span> متولد و در <span class=\"hlight\" dir=\"rtl\">٨٥٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180606, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن داود اعرج، حافظ و قاری . از مردم مدینه بود. وی دوست ابوهریره و نخستین کس است که علوم عربیت را در مدینه منتشر کرد و عالم به انساب قریش وثقه بود. به سال <span class=\"hlight\" dir=\"rtl\">١١٧</span> هَ . ق . به اسکندریه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180607, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن خالدبن ولید المخزومی القرشی از تابعین است . در فتح شام و صفین با معاویه بود. و در خلافت معاویه با رومیان جنگید. ابن اثال طبیب به سال <span class=\"hlight\" dir=\"rtl\">٤٦</span> هَ . ق . به امر معاویه وی را زهر داد. (از تاریخ خلفاء ص <span class=\"hlight\" dir=\"rtl\">١٥٣</span>) (الوزراء و الکتاب صص <span class=\"hlight\" dir=\"rtl\">١٦</span> - <span class=\"hlight\" dir=\"rtl\">١٧</span>) (کامل ابن اثیر ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span>) (الاعلام زرکلی ) (تاریخ مصر ص <span class=\"hlight\" dir=\"rtl\">١٢١</span>).<br /></font></div>'),
(180608, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن خالدبن مسافر الفهمی المصری . والی مصر و از رجال حدیث و ثقات بود.وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180609, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ]</font></b> (اِخ ) ابن حکم بن هشام بن عبدالرحمان الاموی، مکنی به ابوالمطرف . چهارمین پادشاه بنی امیه اندلس است . پدروی والی طلیطلة بود. وی پس از مرگ پدر در قرطبه از مردم بیعت گرفت و مساجدی در اندلس بنا کرد، عصر وی عصر سکون و سلامت بود. عبدالرحمان مردی ثروتمند و بلندهمت بود، جنگهای بسیاری کرد، شعر میگفت و از علوم شرعی و بعضی فنون فلسفی بهره داشت <span class=\"hlight\" dir=\"rtl\">٣١</span> سال حکومت کرد و به سال <span class=\"hlight\" dir=\"rtl\">٢٣٨</span> هَ . ق . به قرطبه درگذشت . (از تاریخ خلفاء ص <span class=\"hlight\" dir=\"rtl\">٣٤٨</span>) (الاعلام زرکلی ) (کامل ابن اثیر ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧</span>).<br /></font></div>'),
(180610, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عبدالوهاب بن خلیفة العلامی المصری الشافعی . وزیر و فقیه و شاعر بود از خانواده ٔ علم و قضاء بود وی سمت قضاء و ولایت مصر یافت و سپس استعفاء کرد و به زیارت حج رفت و به سال <span class=\"hlight\" dir=\"rtl\">٦٩٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180611, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن قاسم المکناسی الاصل الفاسی المالکی . فقیه و فاضل بود.او راست : تقاییدی در طبقات الصوفیه . الفجرالساطع فی شرح الدرر اللوامع. وی به سال <span class=\"hlight\" dir=\"rtl\">٩٩٩</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">١٠٨٢</span> هَ . ق . به فاس درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180612, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن قاسم بن محمدبن ابی بکر الصدیق التیمی القرشی از بزرگان فقه و علم و دیانت مدینه بود. وی حافظ حدیث بود و به سال <span class=\"hlight\" dir=\"rtl\">١٢٦</span> هَ . ق . به شام درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180613, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span><font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن قاسم بن خالد العتقی المصری . رجوع به ابن قاسم ابوعبداﷲ در این لغتنامه شود.<br /></font></div>'),
(180614, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن غنم بن کریز الاشعری شیخ اهل فلسطین و فقیه شام در عصر خود بود. وی در زمان حیات حضرت رسول متولد و به دستور عمربن خطاب به شام رفت و امور دینی مسلمین آنجا را عهده دار شد. او از بزرگان تابعین بود و به سال <span class=\"hlight\" dir=\"rtl\">٧٨</span> هَ . ق . درگذشت . (از الاعلام زرکلی ) (تاریخ الخلفاء ص <span class=\"hlight\" dir=\"rtl\">٣٥</span>) (تاریخ مصر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٨٩</span>).<br /></font></div>'),
(180615, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن غنائم الکنانی العسقلانی، مکنی به ابوالقاسم و معروف به ابن المسجف . شاعر و از متأدبین و ظرفا بود به سال <span class=\"hlight\" dir=\"rtl\">٥٨٣</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">٦٣٥</span> درگذشت .<br /></font></div>'),
(180616, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b>(اِخ ) ابن عیسی بن مرشد العمری، مکنی به ابوالوجاهة المرشدی . مفتی حرم، مکی و یکی از شعراء و علماء حجازبود. وی در زمان ولایت شریف محسن بن الحسین ولایت دیوان انشاء یافت و بعد از مرگش به دست جانشین شریف محمد(شریف احمدبن عبدالمطلب ) به قتل رسید. از تألیفات اوست : توصیف التصریف . الوافی فی شرح الکافی در عروض و غیره . وی به سال <span class=\"hlight\" dir=\"rtl\">٩٧٥</span> متولد و در <span class=\"hlight\" dir=\"rtl\">١٠٣٧</span> هَ . ق . کشته شد. (از الاعلام زرکلی و کامل ابن اثیر ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">١١٩</span>).<br /></font></div>'),
(180617, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عوف بن عبدعوف الزهری القرشی . یکی از بزرگان صحابه و از عشره مبشره و اصحاب شوری و از سابقین در اسلام است . گویند وی هشتمین کس بود که اسلام آورد نام او در جاهلیت عبدالکعبه بود پیغمبر (ص ) او را عبدالرحمان نامید در جنگهای بدر و احد شرکت کرد و درجنگ احد <span class=\"hlight\" dir=\"rtl\">٢١</span> جراحت بر او وارد شد. او در یک روز سه برده آزاد کرد. شغل وی تجارت و خرید و فروش بود و از این راه ثروت بسیاری اندوخت . وصیت کرد که پس از مرگش هزار اسب و پنجاه هزار دینار در راه خدا بدهند. از او در صحیحین <span class=\"hlight\" dir=\"rtl\">٦٥</span> حدیث روایت شده است . وی به سال <span class=\"hlight\" dir=\"rtl\">٤٤</span> قبل از هجرت متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٣٢</span> هَ . ق . به مدینه درگذشت . (از الاعلام زرکلی ). و رجوع به عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٢</span> و سیره ٔ عمربن عبدالعزیز صص <span class=\"hlight\" dir=\"rtl\">١٤</span> - <span class=\"hlight\" dir=\"rtl\">١٥</span> و جوالیقی ص <span class=\"hlight\" dir=\"rtl\">٣٥</span> و تاریخ الخلفاء ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>، <span class=\"hlight\" dir=\"rtl\">١٠٥</span> و الاصابه ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٦</span> شود.<br /></font></div>'),
(180618, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عمرو، مکنی به ابوعمرو معروف به اوزاعی . رجوع به ابوعمرو اوزاعی شود.<br /></font></div>'),
(180619, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عمرو ملقب به رحمان الاشقر. از موالی لیث بن عبدمناة و از مغنیان مشهور زمان عباسی است . وی کنیزان خلیفه مهدی را غنا می آموخت و به سال <span class=\"hlight\" dir=\"rtl\">١٦٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180620, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عمربن سهل الصوفی الرازی، مکنی به ابوالحسین صوفی . عالم به هیئت و افلاک و از مردم ری و منجم عضدالدوله بود. از تألیفات اوست : الکواکب الثابتة. مطارح الشعاعات . ارجوزه ای در فلک . وی به سال <span class=\"hlight\" dir=\"rtl\">٢٩١</span> متولد و در <span class=\"hlight\" dir=\"rtl\">٣٧٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180621, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عمربن رسلان الکنانی العسقلانی المصری معروف به ابی البلقیمی . از علمای حدیث مصر بود. پس از مرگ پدر ریاست فتوی بدو منتهی گشت وی چندین بار قضاوت مصر یافت . از تألیفات او است : مجالس الوعظ و حواشی و تعلیق بر بخاری به نام الافهام لما فی البخاری من الابهام . وی به سال <span class=\"hlight\" dir=\"rtl\">٧٦٣</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">٨٢٤</span> هَ . ق . به قاهره درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180622, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عمربن ابوالقاسم البصری الحنبلی . فقیه، مفسر و از علماء بود به سال <span class=\"hlight\" dir=\"rtl\">٦٢٤</span> هَ . ق . به بصره متولد شد تحصیلات خودرا در آنجا پایان داد و به سال <span class=\"hlight\" dir=\"rtl\">٦٣٤</span> هَ . ق . اجازه ٔ فتوی یافت و در سال <span class=\"hlight\" dir=\"rtl\">٦٥٧</span> به بغداد رفت و در مدرسه بشیریه و مستنصریه به تدریس پرداخت . از تألیفات او است : جامع العلوم فی التفسیر در چهار مجلد. الحاوی در فقه . وی به سال <span class=\"hlight\" dir=\"rtl\">٦٨٤</span> هَ . ق . درگذشت . (الاعلام زرکلی ).<br /></font></div>'),
(180623, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عمربن ابراهیم السفر جلانی الشافعی الدمشقی . از مفسران بود. از تألیفات اوست : حاشیة علی البیضاوی . شرح علی حزب البحر. وی به سال <span class=\"hlight\" dir=\"rtl\">١١٥٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180624, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن علی شیرازی ملقب به ظهیرالدین . رجوع به ظهیرالدین عبدالرحمان شود.<br /></font></div>'),
(180625, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن علی بن مؤید الاماسی . فقیه حنفی واز مردم اماسیه بود وی شهرهای حلب و بلاد عجم را دیدو به روم رفت و در آنجا منصب قضا و تدریس یافت . او راست : فتاوی مؤیدزاده و رسائل دیگر. وی به سال <span class=\"hlight\" dir=\"rtl\">٨٦٠</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">٩٢٢</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180626, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن علی بن محمد الشیبانی الزبیدی معروف به الدیبع و دیبع به لغت مردم مردال سپید بود. مورخ و اهل زبید یمن بود. از تألیفات اوست : بغیة المستفید فی اخبار مدینة زبید. الفضل المزید فی تاریخ زبید. قرة العیون فی اخبار الیمن المأمون . احسن السلوک فی من ولی زبید من الملوک . ارجوزة.تمیز الطیب من الخبیث در حدیث . وی سال <span class=\"hlight\" dir=\"rtl\">٨٦٦</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">٩٤٤</span> به زبید درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180627, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن علی بن محمد الجوزی القرشی البغدادی . رجوع به ابن جوزی ابوالفرج در این لغت نامه شود.<br /></font></div>'),
(180628, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن علی بن محمدبن علی الحنبلی البغدادی الصدیقی ملقب به ابن جوزی . رجوع به جوزی در این لغت نامه و روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٢٦</span> شود.<br /></font></div>'),
(180629, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن علی بن عباس المقری از وزراء دولت اشرفیه رسولیه ٔ یمن بود منصب قاضی القضاتی دولت اشرفیه و مدتی وزارت یافت و به سال <span class=\"hlight\" dir=\"rtl\">٧٩٠</span> هَ . ق . در زبید درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180630, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن علی بن صالح المکودی . از علماء عربیت بود از تألیفات اوست : شرح الفیه ٔ ابن مالک در نحو. شرح مقدمه ٔ ابن اجروم . البسط و التعریف فی علم التصریف . شرح مقصور و ممدود ابن مالک . وی به سال <span class=\"hlight\" dir=\"rtl\">٨٠٧</span> هَ . ق . به فاس درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180631, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن علی بن شیخ نجیب الدین . رجوع به ظهیرالدین عبدالرحمان شود.<br /></font></div>'),
(180632, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ )ابن علی بن الحسین الاموی الاسنائی القوصی . به سال <span class=\"hlight\" dir=\"rtl\">٥٥٠</span>هَ . ق . متولد شد. مولد او در اسنا و نشأت او در قوص بود. دیوان الانشاء اسکندریه و قدس ... یافت و به سال <span class=\"hlight\" dir=\"rtl\">٦٢٥</span> هَ . ق . به دمشق درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180633, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عدیس بن عمرالبلوی . از کسانی است که تحت الشجرة بیعت کرد و شاهد فتح مصر بود سپس فرماندهی لشکری را یافت که ابن ابی خذیفه والی مصر برای خلع عثمان روانه ٔ مدینه کرد پس از قتل عثمان به مصر رفت سپس به امر معاویه دستگیر و گرفتار و زندانی شد و از زندان گریخت و به سال <span class=\"hlight\" dir=\"rtl\">٣٦</span> هَ . ق . والی فلسطین او را دستگیر کرد وبکشت . (از الاعلام زرکلی ) (از تاریخ مصر ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٩٨</span>).<br /></font></div>'),
(180634, 'عبدالرحمان', '<span class=\"hlight\">عبدالرحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عتیق بن خلف الصقلی معروف به ابن الفحام . در عصر خود از شیوخ اسکندریه و عالم به قراآت، بود. او راست : التجرید. وی به سال <span class=\"hlight\" dir=\"rtl\">٤٢٢</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">٥١٦</span> در اسکندریه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180635, 'عبدالرحمان لو', '<span class=\"hlight\">عبدالرحمان لو.</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) نام طایفه ای است از طوائف قشقائی . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٨٥</span>).<br /></font></div>'),
(180636, 'عبدالرحیم', '<span class=\"hlight\">عبدالرحیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن عبدالرحمان بن احمد السید الشریف العباسی . وی فاضل و عالم به لغت و حدیث بود. به سال <span class=\"hlight\" dir=\"rtl\">٨٦٧</span> هَ . ق . به قاهره متولد و به سال <span class=\"hlight\" dir=\"rtl\">٩٦٣</span> هَ . ق . درگذشت . از تألیفات اوست : فیض الباری در شرح غریب صحیح البخاری . (از الاعلام زرکلی ).<br /></font></div>'),
(180637, 'عبدالرحیم', '<span class=\"hlight\">عبدالرحیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن ابوالقاسم قشیری، مکنی به ابونصر. رجوع به ابونصر عبدالرحیم بن ابوالقاسم عبدالکریم بن هوازن القشیری در این لغتنامه و الاعلام زرکلی شود.<br /></font></div>'),
(180638, 'عبدالرحیم', '<span class=\"hlight\">عبدالرحیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن علی بن السعید اللخمی . رجوع به قاضی فاضل عبدالرحیم بن علی بن حسین ... شود.<br /></font></div>'),
(180639, 'عبدالرحیم', '<span class=\"hlight\">عبدالرحیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن احمد حرانی . رجوع به حرانی عبدالرحیم بن احمد، مکنی به ابوالطبیب شود.<br /></font></div>'),
(180640, 'عبدالرحیم', '<span class=\"hlight\">عبدالرحیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن حسن بن علی الاسنوی الشافعی ملقب به جمال الدین . در اسنا متولد شد. وی فقیه، اصولی و عالم به عربیت بود. سپس به سال <span class=\"hlight\" dir=\"rtl\">٧٢١</span> هَ . ق . به قاهره آمدو ریاست شافعیان و ولایت حسبه وکالت بیت المال یافت .از تألیفات او است : المبهمات علی الروضة. الهدایة الی اوهام الکفایة. الاشباه و النظائر. جواهر البحرین . طراز المحافل . مطالع الدقائق . الکواکب الدریة. نهایة السؤل فی شرح مناهج الاصول . وی به سال <span class=\"hlight\" dir=\"rtl\">٧٠٤</span> هَ . ق . به اسنا متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٧٧٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ). و رجوع به روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٣٩</span> شود.<br /></font></div>'),
(180641, 'عبدالرحیم', '<span class=\"hlight\">عبدالرحیم .</span> <font color=\"DarkGreen\"><b>[ ع َدُرْ رَ ]</font></b> (اِخ ) ابن حسین بن عبدالرحمان معروف به حافظ عراقی و مکنی به ابوالفضل . از بزرگان حفاظ حدیث واز نژاد کرد است . به سال <span class=\"hlight\" dir=\"rtl\">٧٢٥</span> هَ . ق . به رازنا از اعمال اربل متولد شد. و در خردسالی با پدر خود به مصررفت و در آنجا نبوغ یافت . سپس به مکه و مدینه و قدس و دمشق و بعلبک رفت و به سال <span class=\"hlight\" dir=\"rtl\">٨٠٦</span> به قاهره درگذشت . از تألیفات اوست : المغنی عن حمل الاسفار فی الاسفار. نکت منهاج البیضاوی فی الاصول . ذیل علی المیزان . الالفیه فی غریب الحدیث . نظم السیرة النبویه . تخریج احادیث الاحیاء. تقریب الاسانید. ذیل علی ذیل العبرللذهبی . معجم که در آن ترجمه ٔ گروهی از کسانی که در قرن هشتم هجری میزیسته اند آمده است . التقیید. الایضاح فی مصطلح الحدیث . شرح التقریب و جز آن . (از الاعلام زرکلی ).<br /></font></div>'),
(180642, 'عبدالرحیم', '<span class=\"hlight\">عبدالرحیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن علی معروف به ابن دخوار. رجوع به ابن دخوار ابو محمدعبدالرحیم ... شود.<br /></font></div>'),
(180643, 'عبدالرحیم', '<span class=\"hlight\">عبدالرحیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) دهی است از دهستان شراء پایین بخش وفس شهرستان اراک واقع در <span class=\"hlight\" dir=\"rtl\">٣٠</span>هزار گزی جنوب باختر کمیجان و هشت هزار گزی راه عمومی . ناحیه ای است کوهستانی . سردسیر. <span class=\"hlight\" dir=\"rtl\">١١٦٥</span> تن سکنه دارد. آب آن از قنات و چشمه تأمین میشود. محصولاتش غلات و انگور است . اهالی به کشاورزی اشتغال دارند. راه مالرو دارد و در فصل خشکی از طریق کارخانه اتومبیل میتوان برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(180644, 'عبدالرحیم', '<span class=\"hlight\">عبدالرحیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن علی بن مرزبان . رجوع به ابن مرزبان ابواحمد عبدالرحیم در این لغتنامه و الاعلام زرکلی شود.<br /></font></div>'),
(180645, 'عبدالرحیم', '<span class=\"hlight\">عبدالرحیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن اسماعیل ابن نباتة الفارقی، مکنی به ابویحیی . رجوع به ابن نباته عبدالرحیم بن محمد در این لغتنامه و الاعلام زرکلی شود.<br /></font></div>'),
(180646, 'عبدالرحیم', '<span class=\"hlight\">عبدالرحیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن محمدبن عبدالرحیم عزالدین، مکنی به ابن الفرات . مردی فاضل و از مردم مصر بود از تألیفات اوست : تذکرة الانام فی النهی عن القیام و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">٧٥٩</span> هَ . ق . به قاهره متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٨٥١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180647, 'عبدالرحیم', '<span class=\"hlight\">عبدالرحیم .</span> <font color=\"DarkGreen\"><b>[ ع َدُرْ رَ ]</font></b> (اِخ ) ابن محمدبن عثمان الخیاط پیشوای فرقه ٔ خیاطیه است که در اواخر قرن سوم و اوائل قرن چهارم میزیسته است . وی استاد ابوالقاسم کعبی و مؤلف کتاب الانتصار است . (از تاریخ ادبیات صفا ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٨</span>).<br /></font></div>'),
(180648, 'عبدالرحیم', '<span class=\"hlight\">عبدالرحیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن مصطفی بن احمد الدمشقی الصالحی، مکنی به ابن شقده . وی مردی فاضل بود و به تاریخ سخت عنایت داشت . از تألیفات اوست : المنتخب . مختصر شذرات الذهب عسکری . وی در حدود <span class=\"hlight\" dir=\"rtl\">٩٠</span> سالگی به سال <span class=\"hlight\" dir=\"rtl\">١١٦٠</span> هَ . ق . به صالحیه ٔ دمشق درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180649, 'عبدالرحیم خلخالی', '<span class=\"hlight\">عبدالرحیم خلخالی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ م ِ ]</font></b> (اِخ )وفاتش در <span class=\"hlight\" dir=\"rtl\">١٣٢١</span> هَ . ش . است . مرحوم سید عبدالرحیم ازآزادی خواهان و مشروطه طلبان قدیم و همکار مرحوم سید محمدرضا شیرازی است . در تحریر و نشر روزنامه ٔ مساوات که از جراید مشهور بود همکاری داشت . مرحوم خلخالی طابع قدیم ترین نسخه ٔ دیوان حافظ بود. دیوان حافظ را از روی نسخه ٔ خطی قدیمی به طبع رساند و در پنجم جمادی الاخر <span class=\"hlight\" dir=\"rtl\">١٣٦١</span> هَ . ق . در حدود هفتادسالگی در تهران وفات یافت . وی در سال <span class=\"hlight\" dir=\"rtl\">١٣٢٠</span> هَ . ش . یعنی فقط یکسال قبل از وفات خود رساله ٔ نفیسی موسوم به «حافظنامه » در شرح احوال حافظ و وصف اشعار او و مقایسه ٔ آن اشعار با اشعار شعرای دیگر و تفؤلات بدیوان او و وصف اشعار الحاقی که در دیوان او داخل شده و کیفیت طبع خود او دیوان خواجه را و سایر جزئیات راجع به دیوان حافظ تألیف و منتشر نموده است که بغایت مفید و دلکش است و دارای <span class=\"hlight\" dir=\"rtl\">١١٠</span> صفحه به قطع وزیری کوچک است . (وفیات معاصرین به قلم قزوینی مجله ٔ یادگار سال سوم شماره پنجم ).<br /></font></div>'),
(180650, 'عبدالرحیم خوافی', '<span class=\"hlight\">عبدالرحیم خوافی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَم ِ خا ]</font></b> (اِخ ) ملقب به نظام الدین . وی به هرات میزیست و از علماء عصر ملک معزالدین حسین و مورد توجه او بود. وی ایمان را که علماء دیگر به تصدیق تفسیر کرده بودند به تسلیم تعبیر کرد و بدین سبب او را در هرات پیر تسلیم گویند. وی به سال <span class=\"hlight\" dir=\"rtl\">٧٣٨</span> هَ . ق . بدست عده ای در هرات به قتل رسید. (از رجال حبیب السیر ص <span class=\"hlight\" dir=\"rtl\">٥٦</span>).<br /></font></div>'),
(180651, 'عبدالرزاق', '<span class=\"hlight\">عبدالرزاق .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَزْ زا ]</font></b> (اِخ ) دهی است از دهستان گرمادوز بخش کلیبر شهرستان اهر واقع در <span class=\"hlight\" dir=\"rtl\">٣١</span>هزار گزی کلیبر و <span class=\"hlight\" dir=\"rtl\">٣١</span>هزار گزی شوسه اهر - کلیبر. ناحیه ای است کوهستانی آب و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٣٣٠</span> تن سکنه دارد. آب آن از رودخانه ٔ گوی آغاج و چشمه تأمین میشود.محصولات آن غلات است اهالی به زراعت و گله داری اشتغال دارند. صنایع دستی آنان فرش و گلیم بافی است . راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٨</span>).<br /></font></div>'),
(180652, 'عبدالرزاق', '<span class=\"hlight\">عبدالرزاق .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَزْ زا ]</font></b> (اِخ ) ابن احمدبن محمد الصابونی . رجوع به ابن الصابونی کمال الدین عبدالرزاق در این لغتنامه و الاعلام زرکلی شود.<br /></font></div>'),
(180653, 'عبدالرزاق', '<span class=\"hlight\">عبدالرزاق .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَزْ زا ]</font></b> (اِخ ) ابن احمدمیمندی . از وزراء سلطان مودود به غزنین بود و به سال <span class=\"hlight\" dir=\"rtl\">٤٤١</span> هَ . ق . درگذشت . (از حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٩٣</span>).<br /></font></div>'),
(180654, 'عبدالرزاق', '<span class=\"hlight\">عبدالرزاق .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَزْ زا ]</font></b> (اِخ ) ابن خواجه شهاب الدین فضل اﷲ. از مردم باشتین از دهات بیهق و سرسلسله ٔ سربداران است . او دومین فرزند شهاب الدین فضل اﷲ است . وی مردی شجاع بود. سلطان ابوسعید بهادرخان او را به معرفی برادرش امیر امین الدین جهت کشتی گرفتن با ابومسلم پهلوان عصر به خراسان دعوت کرد. به امر سلطان با ابومسلم پهلوان در مسابقه ٔ تیرانداری شرکت جست و در نتیجه گوی سبقت را ربود. سلطان بفرمود تا عبدالرزاق را شغلی پرسود دهند. دیوانیان تحصیل مالیات کرمان را که مبلغ صدوبیست هزار دینار بود به وی دادند مقرر آنکه بیست هزار دینار را جهة خاصه ٔ خود تصرف نماید و صدهزار دینار آن را برای خزانه ٔ عامره بفرستد. عبدالرزاق تمامی آن وجوه را به کرمان صرف خود نمود. وقتی متوجه شد که یک دینار از آن وجوه نمانده بود در بحر اندیشه فرورفت . بر حسب اتفاق در همان ایام خبر مرگ سلطان ابوسعید بهادرخان شایع شد. عبدالرزاق روی به وطن معهود آورده چون به باشتین آمد دید فتنه ای حادث شده است . سبب آن بود که در آن زمان ایلچی به باشتین آمده از حسن حمزه و حسین حمزه که دو برادر بودند شراب و شاهد طلب کرده بودند و چون در باب شاهد عذری آورده بودند ایلچی خواست که متعرض عورات ایشان شود برادران شمشیر کشیده گفتند ما سربداریم تحمل این رسوائی را نداریم و ایلچی را به قتل رساندند. خواجه علاءالدین محمدکه در آن زمان وزیر خراسان بود و در قریه ٔ فریومد اقامت داشت کسان به طلب حسن و حسین فرستاد آندو در رفتن تعلل کردند. امیر عبدالرزاق چون بر حقیقت واقعه اطلاع یافت جمعی را با خود متفق کرد و نوکران وزیر را برگردانید. خواجه علاءالدین نوبت دیگر زیاده از پنجاه کس جهت همان امر به باشتین فرستاد امیر عبدالرزاق در مقام خلاف آمد. جنگ درگرفت چند نفر از نوکران علاءالدین کشته و باقی منکوب و مخذول شدند. پس از آن عبدالرزاق مردم آن قریه را جمع آورده گفت فتنه ای عظیم در این دیار بوقوع پیوست و اگر مساهله کنیم کشته شویم وبه مردی سر خود بردار دیدن هزاربار بهتر که به نامردی به قتل رسیدن . از این جهت و سخن آن دو برادر آنان سربدار شدند. امیرعبدالرزاق با جمع لشکریان خود جهت پاسخ به عمل علاءالدین رهسپار خراسان شدند. در آن موقع خواجه علاءالدین جهت امری متوجه استراباد شده بود امیر عبدالرزاق خبردار شد. از عقبش شتافت و در دره ٔ شهرک نو به او رسید نبردی سخت در گرفت خواجه علاءالدین به قتل رسید و امیر عبدالرزاق با غنائم و اموال زیاد به باشتین مراجعت کرد. سربداران به سال <span class=\"hlight\" dir=\"rtl\">٧٣٨</span> هَ . ق . به سبزوار رفتند و آنجا را تصرف کردند و امیرعبدالرزاق رسماً بر مسند حکومت نشست . و در همین سال امیرعبدالرزاق بدست برادرش امیر وجیه الدین مسعود به قتل رسید. رجوع به حبیب السیر چ طهران ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٧</span> شود.<br /></font></div>'),
(180655, 'عبدالرزاق', '<span class=\"hlight\">عبدالرزاق .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَزْ زا ]</font></b> (اِخ ) ابن رزق اﷲبن ابی بکربن خلف، مکنی به ابومحمد و معروف به الرسعنی . مفسر واز فقهاء حنابله بود. از تألیفات اوست : رموز الکنوز. تفسیر در چهار مجلد و جز آن . (از الاعلام زرکلی ).<br /></font></div>'),
(180656, 'عبدالرزاق', '<span class=\"hlight\">عبدالرزاق .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَزْ زا ]</font></b> (اِخ ) ابن علی بن الحسین اللاهیجی الجیلانی ثم القمی معروف به ملاعبدالرزاق . از فضلاء و متکلمان و حکماء متشرع و از محققان و عالم به علم منطق و کلام بود و شعر میسرود. وی از شاگردان مبرز صدرالدین شیرازی (ملاصدرا) و داماد او بود. وی در قم تدریس میکرد از تألیفات اوست : حاشیه جواهر و اعراض شرح تجرید قوشچی . حاشیه بر حاشیه خفری . حاشیه بر حاشیه ملاعبداﷲیزدی بر تهذیب المنطق . حاشیه شرح اشارات خواجه . حدوث عالم . دیوان شعر به فارسی که به گفته ٔ مجمع الفصحاء قریب به چهار الی پنج هزار بیت است . سرمایه ٔ ایمان فی اثبات اصول العقاید بطریق البرهان . شرح تجرید خواجه (شوارق و مشارق ). شرح هیاکل النور در حکمت اشراق .شرح گلشن راز شبستری موسوم به مفاتیح الاعجاز. شرح الکلمات الطیبه . گوهر مراد و جز آن . از اشعار اوست :<br />علی را قدر پیغمبر شناسد<br />که هر کس خویش را بهتر شناسد.<br />سنگ بالین کن و وانگه مزه ٔ خواب ببین <br />تا ببینی که چه در زیر سر مردان است .<br />جنون تکلیف کوه و دشت و صحرا میکند ما را<br />اگر تن در دهیم دیگر که پیدا میکند ما را.<br />وی بنابر قولی به سال <span class=\"hlight\" dir=\"rtl\">١٠٥١</span> هَ . ق . در قم درگذشت . (از ریحانة الادب و الذریعه ).<br /></font></div>'),
(180657, 'عبدالرزاق', '<span class=\"hlight\">عبدالرزاق .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَزْ زا ]</font></b> (اِخ ) ابن همام بن نافع الحمیری . رجوع به صفانی عبدالرزاق بن همام شود.<br /></font></div>'),
(180658, 'عبدالرزاق بیهقی', '<span class=\"hlight\">عبدالرزاق بیهقی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَزْ زا ق ِ ب َ هََ ]</font></b> (اِخ )رجوع به عبدالرزاق بن خواجه شهاب الدین فضل اﷲ شود.<br /></font></div>'),
(180659, 'عبدالرزاق سمرقندی', '<span class=\"hlight\">عبدالرزاق سمرقندی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَزْ زا ق ِ س َ م َ ق َ ]</font></b> (اِخ ) کمال الدین فرزند جلال الدین اسحاق . وی مردی مورخ و فاضل بود. از طرف شاهرخ سفارت هند و گیلان یافت و به خدمت امیرزادگان مانند میرزا عبداللطیف و میرزا عبداﷲ و جز آن درآمده و عاقبت به خدمت سلطان ابوسعید پیوست . پس از آن زندگی انزوا اختیار کرد و در خانقاه شاهرخیه در هرات سمت شیخی یافت . وی به سال <span class=\"hlight\" dir=\"rtl\">٨٨٧</span> هَ . ق . در هرات درگذشت . (ازتاریخ ادبیات ادوارد برون ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤٨٠</span>) (از رجال حبیب السیر ص <span class=\"hlight\" dir=\"rtl\">١٧٢</span>) (از سبک شناسی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٢</span>، <span class=\"hlight\" dir=\"rtl\">١٨٥</span>، <span class=\"hlight\" dir=\"rtl\">١٩٥</span>).<br /></font></div>'),
(180660, 'عبدالرزاق منیعی', '<span class=\"hlight\">عبدالرزاق منیعی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَزْ زا ق ِ م َ ]</font></b> (اِخ ) ابن ابوعلی حسان، مکنی به ابوالفتح . از محدثان و فقهای مشهور زمان خود بود و عده ٔ کثیری از محدثان از او روایت کرده اند. وی به سال <span class=\"hlight\" dir=\"rtl\">٤٩١</span> هَ . ق . درگذشت . (از تاریخ ادبیات ایران صفا ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٤</span>).<br /></font></div>'),
(180661, 'عبدالرشید', '<span class=\"hlight\">عبدالرشید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن ابی حنیفةبن عبدالرزاق، مکنی به ابوالفتح و ملقب به ظهیرالدین معروف به الولوالجی . وی فقیه حنفی بود. و او راست : فتاوی الولوالجیه . وی به سال <span class=\"hlight\" dir=\"rtl\">٤٦٧</span> هَ . ق . در الولوالجی متولد و سال <span class=\"hlight\" dir=\"rtl\">٥٤٥</span> در همانجا درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180662, 'عبدالرشید', '<span class=\"hlight\">عبدالرشید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن احمدبن ابی یوسف هروی، مکنی به ابومنصور. رجوع به ابومنصور عبدالرشید در این لغتنامه و الاعلام زرکلی شود.<br /></font></div>'),
(180663, 'عبدالرشید', '<span class=\"hlight\">عبدالرشید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُرْ رَ ]</font></b> (اِخ ) ابن مسعودبن سلطان محمود و به قول صاحب گزیده فرزند محمودبن سبکتکین بود. کنیت او ابومنصور وملقب به مجدالدوله است . وی مردی شجاع، فاضل و عاقل بود لکن شجاعتی که لازمه ٔ سلطنت باشد نداشت و تحت نفوذ یکی از حاجبان (طغرل برادرزاده ٔ مودود) میزیست و چون استبداد طغرل در کارها بالا گرفت عبدالرشید به خیال دور کردن او وی را به سیستان به جنگ سلاجقه فرستاد.طغرل پس از فتوحاتی که نصیبش شد به غزنه برگشت و برعبدالرشید عاصی شد او را گرفت و با نه تن دیگر از شاهزادگان غزنوی به سال <span class=\"hlight\" dir=\"rtl\">٤٤٤</span> بکشت . (از حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٢</span>ص <span class=\"hlight\" dir=\"rtl\">٣٩٥</span>) (از تاریخ ایران سال چهارم صص <span class=\"hlight\" dir=\"rtl\">٢٦٧</span> - <span class=\"hlight\" dir=\"rtl\">٢٦٨</span>).<br /></font></div>'),
(180664, 'عبدالسلام', '<span class=\"hlight\">عبدالسلام .</span> <font color=\"DarkGreen\"><b>[ ع َ دُس ْ س َ ]</font></b> (اِخ ) ابن عبدالوهاب بن عبدالقادر الجیلی . والی و از علماء بغداد بود. او را متهم به مذهب فلاسفه کردند و کتابهای او را بسوختند. وی مناصب و مقاماتی یافت و به سال <span class=\"hlight\" dir=\"rtl\">٦١١</span> هَ . ق . به بغداد درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180665, 'عبدالسلام', '<span class=\"hlight\">عبدالسلام .</span> <font color=\"DarkGreen\"><b>[ ع َ دُس ْ س َ ]</font></b> (اِخ ) ابن محمد الجبائی، مکنی به ابوهاشم معتزلی . رجوع به ابوهاشم عبدالسلام بن محمد در این لغت نامه و الاعلام زرکلی شود.<br /></font></div>'),
(180666, 'عبدالسلام', '<span class=\"hlight\">عبدالسلام .</span> <font color=\"DarkGreen\"><b>[ ع َ دُس ْ س َ ]</font></b> (اِخ ) ابن علی بن عمربن سیدالناس، مکنی به ابومحمد الزواوی المالکی . وی نخستین کسی است که به دمشق ولایت قضاءمالکیه را یافت . از تألیفات اوست : التنبیهات علی معرفة مایخفی من الوقوفات فی القراآت . به سال <span class=\"hlight\" dir=\"rtl\">٥٨٩</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">٦١١</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180667, 'عبدالسلام', '<span class=\"hlight\">عبدالسلام .</span> <font color=\"DarkGreen\"><b>[ ع َ دُس ْ س َ ]</font></b> (اِخ ) ابن ابراهیم القانی المصری وی شیخ مالکیان بقاهره بود. از تألیفات اوست : شرح المنظومة الجزائریة فی العقاید. ثلاثة شروح علی الجوهرة. السراج الوهاج فی الکلام علی الاسراء و المعراج . وی به سال <span class=\"hlight\" dir=\"rtl\">٩٧١</span> متولد شدو به سال <span class=\"hlight\" dir=\"rtl\">١٠٧٨</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180668, 'عبدالسلام', '<span class=\"hlight\">عبدالسلام .</span> <font color=\"DarkGreen\"><b>[ ع َ دُس ْ س َ ]</font></b> (اِخ ) ابن محمد القزوینی . شیخ معتزله بود. از تألیفات او است :تفسیری بزرگ که ذهبی گوید در <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> جزء است . وی به سال <span class=\"hlight\" dir=\"rtl\">٤٨٨</span> هَ . ق . به بغداد درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180669, 'عبدالسلام', '<span class=\"hlight\">عبدالسلام .</span> <font color=\"DarkGreen\"><b>[ ع َ دُس ْ س َ ]</font></b> (اِخ )ابن مفرج الربعی . از سران لشکریان افریقا بود. سپس به شورش برخاست و به باجه رفت و در آنجا بماند تا فضل بن ابی العنبر در جزیره خروج کرد. عبدالسلام بدو پیوست و با زیادةاﷲبن اغلب نبرد کرد و سرانجام در همان جنگ به سال <span class=\"hlight\" dir=\"rtl\">٢١٨</span> هَ . ق . کشته شد. (از الاعلام زرکلی ).<br /></font></div>'),
(180670, 'عبدالسلام', '<span class=\"hlight\">عبدالسلام .</span> <font color=\"DarkGreen\"><b>[ ع َ دُس ْ س َ ]</font></b> (اِخ ) ابن هاشم الیشکری . از رجال عهد مهدی عباسی است . او را پیروان بسیار بود و بالشکر مهدی نبرد کرد و آنان را شکست داد و سرانجام به سال <span class=\"hlight\" dir=\"rtl\">١٦٢</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180671, 'عبدالسلام', '<span class=\"hlight\">عبدالسلام .</span> <font color=\"DarkGreen\"><b>[ ع َ دُس ْ س َ ]</font></b> (اِخ )ابن عبداﷲبن الخضربن محمدبن تیمیة الحرانی ملقب به مجدالدین و معروف به ابن تیمیه . وی فقیهی حنبلی و محدث و مفسر است . مولد او حران بود و در بغداد سکونت داشت در مذهب حنبلی یگانه ٔ عصر خویش بود. از تألیفات اوست : تفسیرالقرآن العظیم . المنتقی فی احادیث الاحکام . المحرر فی الفقه . وی جد امام بن تیمیه ٔ مشهور است .او به سال <span class=\"hlight\" dir=\"rtl\">٦٥٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180672, 'عبدالسلام', '<span class=\"hlight\">عبدالسلام .</span> <font color=\"DarkGreen\"><b>[ ع َ دُس ْ س َ ]</font></b> (اِخ ) ابن عبدالرحمان اللخمی الاشبیلی . رجوع به لخمی ابوالحکم عبدالسلام بن عبدالرحمان در این لغت نامه و الاعلام زرکلی شود.<br /></font></div>'),
(180673, 'عبدالسلام', '<span class=\"hlight\">عبدالسلام .</span> <font color=\"DarkGreen\"><b>[ ع َ دُس ْ س َ ]</font></b> (اِخ ) ابن الطیب بن محمد القادری الحسنی المغربی الفاسی، مکنی به ابومحمد. از بزرگان شیوخ عصر خود بود و در حدود سی کتاب تألیف کرد. ازجمله تألیفات اوست : الدرالسنی فی من بفاس اهل النسب الحسنی . العرف العاطر فی من بفاس من ابناء الشیخ عبدالقادر، و تألیفات دیگر. وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٥٨</span> هَ . ق . متولد شدو به سال <span class=\"hlight\" dir=\"rtl\">١١١٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180674, 'عبدالسلام', '<span class=\"hlight\">عبدالسلام .</span> <font color=\"DarkGreen\"><b>[ ع َ دُس ْ س َ ]</font></b> (اِخ ) ابن الحسین معروف به ابوطالب مأمونی . شاعر و عالم به ادب بود. نسبت وی به مأمون عباسی میرسد. وی صاحب بن عباد را مدح گفت و نزد او مقام و منزلتی یافت و چون حسودان علیه او سعایت کردند به نیشابور و سپس به بخارا رفت و به سال <span class=\"hlight\" dir=\"rtl\">٣٨٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180675, 'عبدالسلام', '<span class=\"hlight\">عبدالسلام .</span> <font color=\"DarkGreen\"><b>[ ع َ دُس ْ س َ ]</font></b> (اِخ ) ابن حبیب، مکنی به ابوسعید. رجوع به ابوسعید عبدالسلام در این لغت نامه و الاعلام زرکلی شود.<br /></font></div>'),
(180676, 'عبدالسلام', '<span class=\"hlight\">عبدالسلام .</span> <font color=\"DarkGreen\"><b>[ ع َ دُس ْ س َ ]</font></b> (اِخ ) ابن احمدبن غانم المقدسی عزالدین . رجوع به غانم عزالدین عبداﷲ در این لغت نامه و الاعلام زرکلی شود.<br /></font></div>'),
(180677, 'عبدالسید', '<span class=\"hlight\">عبدالسید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُس ْ س َی ْ ی ِ ]</font></b> (اِخ ) ابن محمدبن عبدالواحد، مکنی به ابونصر و معروف به ابن الصباغ . رجوع به ابن الصباغ ابونصر عبدالسید در این لغتنامه و الاعلام زرکلی شود.<br /></font></div>'),
(180678, 'عبدالصمد', '<span class=\"hlight\">عبدالصمد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُص ْ ص َ م َ ]</font></b>(اِخ ) ابی عبداﷲ با کثیرالیمنی . وی شاعر و کاتب انشاء سلطان عمربن بدر بود. او را دیوانی است . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٢٥</span> هَ . ق . به الشحر درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180679, 'عبدالصمد', '<span class=\"hlight\">عبدالصمد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُص ْ ص َ م َ ]</font></b> (اِخ ) ابن المعدل بن غیلان از شعراء دولت عباسی است و شاعری هجاگوی بود. مولد و منشاء او بصره بود. و به سال <span class=\"hlight\" dir=\"rtl\">٢٤٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ). و رجوع به ابن المعدل شود.<br /></font></div>'),
(180680, 'عبدالصمد', '<span class=\"hlight\">عبدالصمد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُص ْ ص َ م َ ]</font></b> (اِخ ) ابن منصوربن الحسن بن بابک . رجوع به ابن بابک عبدالصمد در این لغت نامه و الاعلام زرکلی شود.<br /></font></div>'),
(180681, 'عبدالصمد', '<span class=\"hlight\">عبدالصمد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُص ْ ص َ م َ ]</font></b> (اِخ ) بدخشی در هراة به امر سلطان ابوسعید تاریخ او میگفته و از شعرای عصر او بود. از اشعار اوست :<br />ز ماهی هیاهوی تا ماه بود<br />سر آوازشان جانم اﷲ بود.<br /><font color=\"Red\">(از مجالس النفائس ص <span class=\"hlight\" dir=\"rtl\">٢١٠</span>).</font><br /></font></div>'),
(180682, 'عبدالصمد', '<span class=\"hlight\">عبدالصمد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُص ْ ص َ م َ ]</font></b> (اِخ ) ابن علی بن عبداﷲبن عباس . وی عم منصور و به سال <span class=\"hlight\" dir=\"rtl\">١٤٧</span> هَ . ق . عامل او به مکه و طائف بود سپس ولایت مدینه یافت و به سال <span class=\"hlight\" dir=\"rtl\">١٥٩</span>هَ . ق .المهدی او را عزل کرد و به سال <span class=\"hlight\" dir=\"rtl\">١٦٢</span> هَ . ق . وی را ولایت جزیره داد و در <span class=\"hlight\" dir=\"rtl\">١٦٣</span> او را دیگر بار معزول ساخت وتا سال <span class=\"hlight\" dir=\"rtl\">١٦٦</span> به زندان افکند. وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٤</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">١٨٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180683, 'عبدالصمد', '<span class=\"hlight\">عبدالصمد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُص ْ ص َ م َ ]</font></b> (اِخ ) ابن ابراهیم بن الخلیل البغدادی . وی یکی از چهل تن مشایخ است که شهید اول از آنان روایت کند. از تألیفات اوست : الاکسیر فی التفسیر. مختصر رموز الکنوز. عیون العین فی الاربعین . کمال الاَّمال فی بیان حال المآل . زین القصص فی تفسیر احسن القصص (در تفسیر سوره ٔ یوسف ). (از روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">١٤٤٠</span>).<br /></font></div>'),
(180684, 'عبدالصمد', '<span class=\"hlight\">عبدالصمد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُص ْ ص َ م َ ]</font></b> (اِخ ) ابن عبدالوهاب بن الحسن بن محمدبن عساکر الدمشقی ثم المکی . رجوع به ابن عساکر ابوالیمن امین الدین عبدالصمد و نیز رجوع به الاعلام زرکلی شود.<br /></font></div>'),
(180685, 'عبدالصمد همدانی', '<span class=\"hlight\">عبدالصمد همدانی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُص ْ ص َ م َ دِ هََ م َ ]</font></b> (اِخ ) از فقها و لغویان و حکما و متکلمان و از شاگردان بهبهانی و صاحب ریاض المسائل بود. از تألیفات اوست : کتابی بزرگ در لغت که ناقص مانده . وی به سال <span class=\"hlight\" dir=\"rtl\">١٢١٦</span> هَ . ق . به کربلا درگذشت . (از روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٣٥٢</span>).<br /></font></div>'),
(180686, 'عبدالظاهر', '<span class=\"hlight\">عبدالظاهر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُظْ ظا هَِ ]</font></b> (اِخ ) ابن فضل معروف به ابن العجمی . وی از وزراء فاطمیان مصر و ملقب به خلیل امیرالمؤمنین بود. چند بار وزارت یافت سرانجام به دست تاج الملوک به سال <span class=\"hlight\" dir=\"rtl\">٤٦٥</span> هَ . ق . به قاهره کشته شد. (از الاعلام زرکلی ).<br /></font></div>'),
(180687, 'عبدالعالی', '<span class=\"hlight\">عبدالعالی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b> (اِخ ) ابن شیخ نورالدین علی بن عبدالعال الکرکی . وی فقیه و محدث و متکلم بود. از تألیفات اوست : شرح بر الفیه ٔ شهید در فقه . شرح بر ارشاد علامه تا کتاب حج . تعلیقات بر مختصر نافع تا پایان کتاب وقف . مناظرات با میرزا مخسوم الشریفی در مباحث امامت و جز آن .وی به سال <span class=\"hlight\" dir=\"rtl\">٩٩٣</span> هَ . ق . درگذشت . (از روضات ص <span class=\"hlight\" dir=\"rtl\">٣٥٤</span>).<br /></font></div>'),
(180688, 'عبدالعزی', '<span class=\"hlight\">عبدالعزی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع ُزْ زا ]</font></b> (اِخ ) بطنی است از عبدمناف از قریش از عدنانیه فرزندان عبدالعزی بن عبد شمس بن عبدمناف . (از معجم قبائل العرب ).<br /></font></div>'),
(180689, 'عبدالعزی', '<span class=\"hlight\">عبدالعزی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع ُزْ زا ]</font></b> (اِخ ) ابن عبدالشمس بن عبدمناف از قریش از عدنان . جد جاهلی است . (از الاعلام زرکلی ).<br /></font></div>'),
(180690, 'عبدالعزی', '<span class=\"hlight\">عبدالعزی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع ُزْ زا ]</font></b> (اِخ ) ابن عبدالمطلب بن هاشم . رجوع به ابولهب عبدالعزی بن عبدالمطلب در این لغتنامه و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180691, 'عبدالعزی', '<span class=\"hlight\">عبدالعزی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع ُزْ زا ]</font></b> (اِخ ) ابن قصی بن کلاب از قریش از عدنان جد جاهلی از عقبه ٔ هباربن الاسود است . (از الاعلام زرکلی ) (صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٣٥٦</span>- <span class=\"hlight\" dir=\"rtl\">٣٥٧</span>).<br /></font></div>'),
(180692, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن عمربن عبدالعزیزبن مروان بن الحکم الاموی . یزیدبن ولید وی را امارت مکه و مدینه داد و مروان بن محمد نیز وی را در آن شغل ابقا کرد. در حدود سال <span class=\"hlight\" dir=\"rtl\">١٤٨</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180693, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن محمدبن عبیدالدراوردی جهنی . محدث است و گروهی بسیار از جمله سفیان از وی روایت کنند. نسبت او به دراورد قراء خراسان است . به سال <span class=\"hlight\" dir=\"rtl\">١٨٦</span> هَ . ق . به مدینه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180694, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن محمدبن عبدالمحسن الانصاری الاوسی معروف به ابن قاضی حماة. شاعر و فقیه بود. او راست : لزوم مالایلزم در مجلدی بزرگ . به سال <span class=\"hlight\" dir=\"rtl\">٥٨٦</span> هَ . ق . به دمشق متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٦٦٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180695, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن محمدبن سعود. از امراء نجد سعودیین است . رجوع به ابن سعود و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180696, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن محمدبن ابراهیم بن جماعة الکنانی الحموی معروف به ابن جماعة. رجوع به ابن جماعة و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180697, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن متعب بن عبداﷲ الرشید. رجوع به ابن الرشید (چند تن از امرای وهابیان ...) و به الاعلام زرکلی شود.<br /></font></div>'),
(180698, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن فهدالهاشمی . رجوع به ابن فهد و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180699, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن عمروبن الحجاج الزبیدی . با یزیدبن مهلب به عراق رفت و از جانب او شغلها یافت . چون یزید کشته شد وی گرفتار گشت و شکنجه شد. به سال <span class=\"hlight\" dir=\"rtl\">١٠٢</span> هَ . ق . کشته شد. (از الاعلام زرکلی ).<br /></font></div>'),
(180700, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن عمربن محمدبن نباته السعدی التمیمی، مکنی به ابونصر و ملقب به ابن نباته . رجوع به ابن نباته (ابونصر عبدالعزیز) و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180701, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن علی المصری ملقب به سعدالدین . وی طبیب و از علماء و ادباء بود. به سال <span class=\"hlight\" dir=\"rtl\">٥٧٠</span> هَ . ق . به مصر متولد شد و به خدمت ملک مسعودبن الکامل پیوست ومدتی با وی به یمن بود. به سال <span class=\"hlight\" dir=\"rtl\">٦٣٠</span> هَ . ق . به دمشق آمد. از تألیفات اوست : نوادر الالباء فی امتحان الاطباء که آن را برای الکامل ایوبی تصنیف کرد. وی به سال <span class=\"hlight\" dir=\"rtl\">٦٣٥</span> هَ . ق . به قاهره درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180702, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ]</font></b> (اِخ ) ابن محمدبن علی الطوسی ملقب به ضیاءالدین . از فقهاء شافعی است . به سال <span class=\"hlight\" dir=\"rtl\">٧٠٦</span> هَ . ق . به دمشق درگذشت . از تألیفات اوست : مصباح الحاوی و مفتاح الفتاوی که شرح حاوی صغیر قزوینی است . (از الاعلام زرکلی ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(180703, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َدُل ْ ع َ ]</font></b> (اِخ ) ابن محمدبن نعمان بن حیون . وی از علماء امامیه و قاضی القضاة مصر و شام و حرمین و مغرب بود. از مردم قیروان است . به سال <span class=\"hlight\" dir=\"rtl\">٣٩٤</span> هَ . ق . قضاوت مصر یافت حاکم مصر و مغرب به سال <span class=\"hlight\" dir=\"rtl\">٣٩٨</span> وی را عزل کرد و به سال <span class=\"hlight\" dir=\"rtl\">٤٠١</span> او را غیلةً بکشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180704, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن محمد المغربی معروف به القشتالی و مکنی به ابوفارس . وزیر منصور احمد (سلطان مغرب ) بود. به سال <span class=\"hlight\" dir=\"rtl\">١٠٣٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180705, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن مروان بن الحکم بن ابی العاص بن امیه، مکنی به ابوالاصبغ. امیر مصر بود. به مدینه متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٦٥</span> هَ . ق . از جانب پدر خود ولایت مصر یافت سپس به حلوان ساکن شد و آن را بپسندید و بدانجا خانه هاو مسجدها بنا کرد و درختان خرما و انگور کاشت . به سال <span class=\"hlight\" dir=\"rtl\">٨٦</span> هَ . ق . به حلوان درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180706, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن موسی بن نصیر. وی از جانب پدر امارت اندلس یافت و مدائن را فتح کرد. چون سلیمان بن عبدالملک بر پدر او موسی بن نصیر خشم گرفت و بفرمود تا عبدالعزیز را به قتل رسانند. لشکریان سلیمان عبدالعزیز را هنگامی که در محراب نمازصبحگاهان میگذارد گردن زدند و به نزد سلیمان بردند.قتل او به سال <span class=\"hlight\" dir=\"rtl\">٩٧</span> هَ . ق . بود. (از الاعلام زرکلی ).<br /></font></div>'),
(180707, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن واثق . رجوع به ابن واثق ابومحمد عبدالعزیز شود.<br /></font></div>'),
(180708, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َدُل ْ ع َ ]</font></b> (اِخ ) ابن الوزیر الجروی در روزگار مطلب بن عبداﷲ الخزاعی والی شرطه ٔ مصر بود. وی با <span class=\"hlight\" dir=\"rtl\">٥٠</span>هزار تن به اسکندریه رفت و آنجا را به صلح بگرفت . به سال <span class=\"hlight\" dir=\"rtl\">٢٠٥</span> هَ . ق . در نبردی که با سری بن حکم داشت سنگی از منجنیق بر او فرود آمد و درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180709, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن یحیی بن عبدالعزیز الکنانی المکی . وی فقیه و اهل مناظره و از شاگردان امام شافعی بود. در ایام خلافت مأمون به بغداد شد و میان او و بشرالمریسی مناظره ای در قرآن درگرفت . او را تصنیفاتی است از جمله کتاب الحیدة.وی به سال <span class=\"hlight\" dir=\"rtl\">٢٤٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180710, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن یعقوب العباسی ملقب به المتوکل علی اﷲ. از خلفاء دولت عباسیان دوم مصر بود. به سال <span class=\"hlight\" dir=\"rtl\">٨٨٤</span> هَ . ق . مردم با وی بیعت کردند. تولد او به سال <span class=\"hlight\" dir=\"rtl\">٨١٩</span> هَ . ق . است و به سال <span class=\"hlight\" dir=\"rtl\">٩٠٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180711, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) خراسانی، مکنی به ابوزید. رجوع به ابوزید عبدالعزیز خراسانی شود.<br /></font></div>'),
(180712, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْع َ ]</font></b> (اِخ ) ابن احمدبن محمد البخاری . فقیهی حنفی است . او راست : شرح اصول البزدوی . شرح المنتخب الحسامی .وی به سال <span class=\"hlight\" dir=\"rtl\">٧٣٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180713, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن علی الاشبیلی، مکنی به ابوالاصبغ و معروف به ابن الطحان . رجوع به ابن الطحان شود.<br /></font></div>'),
(180714, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن ابان بن محمد الاموی السعیدی . وی فقیه و از رجال حدیث و مقیم کوفه بود و در زمان خلافت مأمون عباسی قضاوت واسط را یافت . وی به سال <span class=\"hlight\" dir=\"rtl\">٢٠٧</span> هَ . ق . به بغداد درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180715, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن بیان بن داود، مکنی به ابوالحسین معروف به ابن حاجب النعمان . رجوع به ابن حاجب النُعمان شود.<br /></font></div>'),
(180716, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن ابی حازم . رجوع به عبدالعزیزبن سلمة شود.<br /></font></div>'),
(180717, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن احمد اصفهانی حزری . رجوع به حزری ابوالحسن عبدالعزیز شود.<br /></font></div>'),
(180718, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن احمدبن نصربن صالح الحلوانی البخاری ملقب به شمس الائمة فقیه حنفی است . در عصر خویش امام اهل رأی به بخاری بود. نسبت او به صنعت حلواست . از تالیفات اوست : المبسوط فی الفقه . النوادر. وی به سال <span class=\"hlight\" dir=\"rtl\">٤٤٨</span> هَ . ق . در کش درگذشت و به بخارا بخاک سپرده شد. (الاعلام زرکلی ).<br /></font></div>'),
(180719, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن بحر یا جریر یا نحریربن عبدالعزیز مشهور به ابن براج . رجوع به ابن براج عبدالعزیز و نیز به روضات الجنات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٥</span> شود.<br /></font></div>'),
(180720, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن حامدبن الخضر، مکنی به ابوطاهر. وی شاعر و از مردم واسط و معروف به سیدوک بود. به سال <span class=\"hlight\" dir=\"rtl\">٣٦٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180721, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن حسین بن الحباب الاغلبی السعدی الصقلی معروف بالقاضی الجلیس . وی شاعر، ادیب و متولی دیوان انشاء فائز بود. به سال <span class=\"hlight\" dir=\"rtl\">٤٩٠</span> هَ . ق . متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٥٦١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180722, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن زراة الکلابی . در عصرمعاویه میزیست و مردی شجاع بود و در غزوه ٔ قسطنطنیه حاضر بود و در یکی از وقایع به قتل رسید. او را شعری است . ابن اثیر چند بیتی از او را نقل کرده است . (از الاعلام زرکلی ).<br /></font></div>'),
(180723, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن سرایابن علی بن القاسم السنبسی الطائی معروف به صفی الدین حلی . رجوع به صفی الدین حلی شود.<br /></font></div>'),
(180724, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن علی بن ابی العزالبکری التیمی القرشی البغدادی المقدسی . وی قاضی و فقیه بود. به بغداد متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٧٩٥</span> هَ . ق . به دمشق آمد. سپس مدتی در بیت المقدس سکونت جست و قضاوت آنجا بعهده ٔ او محول گشت و به سال <span class=\"hlight\" dir=\"rtl\">٨١٢</span> به بغداد بازگشت . سه سال قضاوت آنجا را بعهده داشت سپس سفرها کرد. تولد او به سال <span class=\"hlight\" dir=\"rtl\">٧٦٨</span> است و به سال <span class=\"hlight\" dir=\"rtl\">٨٤٦</span> هَ . ق . به دمشق درگذشت . از تألیفات اوست : عمدة الناسک فی معرفة المناسک . سلک البررة فی معرفة القراآت العشرة. بدیع المعانی فی علم البیان و المعانی . الصبر و التوکل . القمر المنیر فی احادیث البشیر النذیر. الخلاصة مختصر مغنی ابن قدامه . (از الاعلام زرکلی ).<br /></font></div>'),
(180725, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن عثمان بن ابراهیم النسفی . فقیه حنفی و امام بخاری در عصر خویش بوده . از کتب اوست : المنقذ من الزلل فی مسائل الجدل کفایة. الفحول فی الاصول . الفصول فی الفتاوی .وی به سال <span class=\"hlight\" dir=\"rtl\">٥٦٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180726, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن عبدالواحدبن محمدبن موسی المغربی المکناسی . وی شیخ قراء مدینه بود نسبت او به مکناسه از بلاد مغرب است . وی به سال <span class=\"hlight\" dir=\"rtl\">٩٥١</span> هَ . ق . به حلب و دمشق رفت سپس به مدینه سکونت جست . او راست شعری و اراجیزی و منظومه هائی در <span class=\"hlight\" dir=\"rtl\">٢٨</span> علم، از جمله نظم جواهر السیوطی فی التفسیر. منهج الوصول فی اصول الدین منظومة فی البلاغة.وی به سال <span class=\"hlight\" dir=\"rtl\">٩٦٤</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180727, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span><font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن عبدالواحدبن اسماعیل الجیلی . وی طبیب و از مردم جیلان بود. در علم فلسفه و طب و دین تبحر یافت و به دمشق سکونت جست و قضاوت بعلبک بدو محول شد. سپس به سال <span class=\"hlight\" dir=\"rtl\">٦٣٨</span> هَ . ق . قضاوت دمشق یافت و سپس وی را بگرفتند و به سال <span class=\"hlight\" dir=\"rtl\">٦٤١</span> هَ . ق . نزدیک بعلبک به قتل رساندند از تألیفات اوست : شرح الاشارت والتنبیهات که آن را برای مظفر ایوبی نوشته است، اختصار الکلیات از قانون ابن سینا. (از الاعلام زرکلی ).<br /></font></div>'),
(180728, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن عبداﷲبن ابی سلمة التیمی مدنی . وی فقیه و از حفاظحدیث و مردی ثقه بود. اصل او از اصفهان است . در مدینه سکونت جست و سپس به بغداد رفت . او را تألیفاتی است . به سال <span class=\"hlight\" dir=\"rtl\">١٦٤</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180729, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن عبدالسلام سلمی دمشقی ملقب به سلطان العلماء. وی فقیهی شافعی بود ولایت قضای مصر یافت سپس از آن شغل استعفا خواست . به سال <span class=\"hlight\" dir=\"rtl\">٥٧٧</span> متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٦٦٠</span> هَ . ق . درگذشت . از تألیفات اوست : الفوائد. الغایة فی اختصار النهایة. القواعد الکبری . القواعد الصغری . الفرق بین الایمان و الاسلام . مقاصد الرعایة. درباره ٔ علم وی این مثل بین مصریان سائر است : که ما أنت الا من العوام و لو کنت ابن عبدالسلام . (از الاعلام زرکلی ).<br /></font></div>'),
(180730, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ )ابن عبدالرحمان بن فیصل بن ترکی بن عبداﷲبن محمدبن مسعود. رجوع به ابن سعود عبدالعزیزبن عبدالرحمان شود.<br /></font></div>'),
(180731, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان بن ابی عامر. وی یکی از سلاطین دولت عامریه ٔ اندلس است و در حدود سال <span class=\"hlight\" dir=\"rtl\">٤٥٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180732, 'عبدالعزیز', '<span class=\"hlight\">عبدالعزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن سلمةبن دینار المدنی، مکنی به ابوتمام فقیه و محدث بود. ابن خلیل درباره ٔ او گوید: پس از مالک بمدینه کسی افقه از ابن ابی حازم بن سلمه نبود. وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٧</span> متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">١٨٤</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180733, 'عبدالعظیم', '<span class=\"hlight\">عبدالعظیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن عبدالقوی بن عبداﷲ المنذری . از بزرگان علماء حدیث و فقیه و عالم به عربیت بود. از تألیفات اوست : الترغیب و الترهیب . مختصر صحیح مسلم . مختصر سنن ابی داود. وی به سال <span class=\"hlight\" dir=\"rtl\">٥٨١</span> هَ . ق .به مصر متولد و در <span class=\"hlight\" dir=\"rtl\">٦٥٦</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180734, 'عبدالعظیم', '<span class=\"hlight\">عبدالعظیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b> (اِخ ) ابن عبداﷲبن حسن بن زیدبن الامام حسن، مکنی به ابوالقاسم . از اصحاب امام جواد و ابوالحسن الهادی (ع ) بود. وی مردی متقی و پرهیزگار و از راویان و ثقات مورد اعتماد علی بن محمد النقی بود. اخبار و روایاتی درباره ٔ اعتماد بدو از ائمه روایت شده است . مرقد او در یک فرسنگی تهران به شهرری (معروف به شاهزاده عبدالعظیم ) واقع است و زیارتگاه مسلمانان شیعی است .<br /></font></div>'),
(180735, 'عبدالعظیم', '<span class=\"hlight\">عبدالعظیم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ع َ ]</font></b>(اِخ ) ابن عبدالواحدبن ظافربن ابی الاصبع العدوانی المصری . رجوع به ابن ابی الاصبع و به الاعلام زرکلی شود.<br /></font></div>'),
(180736, 'عبدالغافر', '<span class=\"hlight\">عبدالغافر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ف ِ ]</font></b> (اِخ ) ابن اسماعیل الفارسی، مکنی به ابوالحسن الفارسی . رجوع به ابوالحسن عبدالغافر و به الاعلام زرکلی شود.<br /></font></div>'),
(180737, 'عبدالغفار', '<span class=\"hlight\">عبدالغفار.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ غ َف ْ فا ]</font></b> (اِخ ) مکنی به ابوسعید و ملقب به حمید امیر المؤمنین . رجوع به ابوسعید عبدالغفار شود.<br /></font></div>'),
(180738, 'عبدالغفار', '<span class=\"hlight\">عبدالغفار.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ غ َف ْ فا ]</font></b> (اِخ ) ابن عبدالکریم بن عبدالغفار القزوینی ملقب به نجم الدین . وی فقیه شافعی است . از کتب اوست : الحاوی الصغیر، العجایب فی شرح اللباب .وی به سال <span class=\"hlight\" dir=\"rtl\">٦٦٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180739, 'عبدالغفار', '<span class=\"hlight\">عبدالغفار.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ غ َف ْ فا ]</font></b> (اِخ ) ابن عبدالواحدبن وهب ملقب به أخرس . از فحول شعرای متأخر است . او را دیوانی است بنام الطرازالانفس فی شعرالاخرس . وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٢٥</span> هَ . ق . به موصل متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٢٩٠</span> هَ . ق . به بصره درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180740, 'عبدالغفار', '<span class=\"hlight\">عبدالغفار.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ غ َف ْفا ]</font></b> (اِخ ) جمال الدین بن مولانا جلال الدین اسحاق سمرقندی . وی مردی مورخ بود. (از رجال حبیب السیر ص <span class=\"hlight\" dir=\"rtl\">٩٨</span>).<br /></font></div>'),
(180741, 'عبدالغفور', '<span class=\"hlight\">عبدالغفور.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ غ َ ]</font></b> (اِخ ) ابن لقمان بن محمدالکردری . از ائمه ٔ حنفی و از مردم کردر (از دهات خوارزم ) بود. وی قضاوت حلب یافت و به سال <span class=\"hlight\" dir=\"rtl\">٥٦٢</span> هَ . ق . به حلب درگذشت . از تألیفات اوست : اصول الفقه . شرح التجرید. شرح الجامع الصغیر. شرح الجامع الکبیر. حیرة الفقهاء. (از الاعلام زرکلی ).<br /></font></div>'),
(180742, 'عبدالغنی', '<span class=\"hlight\">عبدالغنی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ غ َ نی ی ]</font></b> (اِخ ) ابن شاکربن محمد السادات . وی فقیهی حنفی و از مردم دمشق بود. از تألیفات اوست : الفتاوی . به سال <span class=\"hlight\" dir=\"rtl\">١٢١٠</span> هَ . ق . متولد شدو به سال <span class=\"hlight\" dir=\"rtl\">١٢٦٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180743, 'عبدالغنی', '<span class=\"hlight\">عبدالغنی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْغ َ نی ی ]</font></b> (اِخ ) فضلی دمشقی . طبیبی ماهر بود. و او را تألیفاتی است که بعضی از آنها به طبع رسیده است . وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٨٨</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180744, 'عبدالغنی', '<span class=\"hlight\">عبدالغنی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ غ َ نی ی ]</font></b> (اِخ ) عریسی . روزنامه نگار و از شهداء عرب است .مولد وی بیروت بود. وی روزنامه ٔ یومیه ٔ المفید را که از قدیمی ترین روزنامه های سوریه است منتشر کرد و به سال <span class=\"hlight\" dir=\"rtl\">١٣٣٤</span> هَ . ق . در دیوان عالی محکوم و اعدام شد. از تألیفات اوست : کتاب البنین . (از الاعلام زرکلی ).<br /></font></div>'),
(180745, 'عبدالغنی', '<span class=\"hlight\">عبدالغنی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ غ َ نی ی ]</font></b> (اِخ ) ابن سعید ازدی، مکنی به ابومحمد. شیخ حفاظ حدیث بمصر و عالم به انساب و متفنن بود. وی به سال <span class=\"hlight\" dir=\"rtl\">٣٣٢</span> هَ . ق . به قاهره متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٤٠٩</span> درگذشت . از تألیفات اوست : مشتبه النسبة. المؤتلف و المختلف . (از الاعلام زرکلی ).<br /></font></div>'),
(180746, 'عبدالغنی', '<span class=\"hlight\">عبدالغنی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ غ َ نی ی ]</font></b> (اِخ ) ابن اسماعیل بن عبدالغنی النابلسی . وی شاعر و عالم به علم دین و ادب بود و به بغداد وفلسطین و لبنان و مصر و حجاز سفر کرد. مولد او به سال <span class=\"hlight\" dir=\"rtl\">١٠٥٠</span> هَ . ق . به دمشق بود و به سال <span class=\"hlight\" dir=\"rtl\">١١٤٣</span> هَ . ق . بدانجا درگذشت . از تألیفات اوست : الحضرة الانسیه فی الرحلة القدسیة. تعطیر الانام فی تعبیر المنام . علم الفلاحة. نفحات الازهار علی نسمات الاسحار. ایضاح الدلالات فی سماع الاَّلات . ذیل نفحة الریحانة. حلة الذهب الابریز فی الرحلة الی بعلبک و بقاع العزیز. الحقیقة و المجاز فی رحلة الشام و المصر و الحجاز. قلائد المرجان فی عقاید اهل الایمان . کنزالحق المبین فی احادیث سید المرسلین . اباحة الدخان . شرح المقدمة سید السنوسیة. رشحات الاقلام فی شرح کفایة الغلام . (از الاعلام زرکلی ).<br /></font></div>'),
(180747, 'عبدالغنی', '<span class=\"hlight\">عبدالغنی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ غ َ نی ی ]</font></b> (اِخ ) ابن عبدالواحدبن علی بن مسرور المقدسی الجماعیلی الدمشقی حافظ حدیث بود. در جماعیل (نزدیک نابلس ) متولد شد و به دمشق سکونت جست . او راست : الکمال فی اسماءالرجال در دو مجلد. الدرة المضیة فی السیرة النبویة. العمدة فی الاحکام . النصیحة فی الادعیة الصحیحة. اشراطالساعة و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">٥٤١</span> هَ . ق . متولد و به سال <span class=\"hlight\" dir=\"rtl\">٦٠٠</span> هَ . ق . به مصر درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180748, 'عبدالفتاح', '<span class=\"hlight\">عبدالفتاح .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ف َت ْ تا ]</font></b> (اِخ ) ابن درویش التمیمی الحنفی النابلسی، فقیه و ساکن قدس بود. از تألیفات اوست : الفوائد الفتاحیه فی فقه الحنفیه . کتاب فتاوی . وی به سال <span class=\"hlight\" dir=\"rtl\">١١٣٨</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180749, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ ]</font></b> (اِخ ) ابن محمدبن یحیی بن مکرم الحسینی . وی مردی فاضل و از علماء حجاز بود و انشائی نیکو داشت و از تألیفات اوست : عیون المسائل من اعیان الرسائل . المقصورة الدریدیه . وی به سال <span class=\"hlight\" dir=\"rtl\">٩٧٦</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">١٠٣٣</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180750, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ ]</font></b> (اِخ ) راشدی . قاضی و مفتی قسطنطنیة و از فقهاء مغرب بود. از تألیفات اوست : حاشیة علی شرح السید للمواقف العضدیة. عائلات قسطنطنیة و قبائلها و عربها و بربرها. رسالة فی تحریم الدخان، و جز آن . وی درحدود سال <span class=\"hlight\" dir=\"rtl\">١١١٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180751, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ ]</font></b> (اِخ ) جیلانی، ابن ابی صالح موسی بن عبداﷲبن یحیی الجیلانی ملقب به محیی الدین . مولد و مدفن وی بغداد است . امام سلسله ٔقادریه و صوفیه است که اغلب در بلاد هند و ممالک عثمانی و بلاد اسلامی مذهبش رواج دارد. بگفته ٔ قاموس الاعلام و طبقات شعرانی نسبت او به حضرت حسن مجتبی (ع ) میرسد. وی از بزرگان صوفیه و مشایخ طریقت و مؤسس مذهب قادریه است . او ابتدا نزد ابوزکریای تبریزی علوم عربیت را فراگرفت . فقه و اصول را نیز در بغداد آموخت . سپس به وعظ و تدریس پرداخت و شهرتی پیدا کرد. در زمان تحصیل از دسترنج خود ارتزاق میکرد. فتاوی او موافق هر دو مذهب شافعی و حنبلی است . در فقه و تصوف تألیفاتی دارد از جمله : بشائر الخیرات . دیوان اشعار. الغنیة الطالبی . طریق الحق . الفتح الربانی و الفیض الرحمانی . فتوح الغیب . الفیوضات الربانیة. ملفوظات قادریه . ملفوظات گیلانی و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">٤٧٠</span> یا <span class=\"hlight\" dir=\"rtl\">٤٩٠</span> متولد و به سال <span class=\"hlight\" dir=\"rtl\">٥٦٠</span> یا <span class=\"hlight\" dir=\"rtl\">٥٦١</span> هَ . ق . به بغداد درگذشت . (ازروضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٣٢</span>) (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩٤</span>).<br /></font></div>'),
(180752, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ ]</font></b> (اِخ ) ابن یوسف النقیب الحلبی . وی فقیهی فاضل بود و به سال <span class=\"hlight\" dir=\"rtl\">١١٠٧</span> هَ . ق . به مدینه درگذشت . از تألیفات اوست : لسان الحکام فی فقه الحنفیة. معرفة الرمی بالسّهام . (از الاعلام زرکلی ).<br /></font></div>'),
(180753, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ ]</font></b> (اِخ ) ابن الناصر. از فرزندان امام یحیی شرف الدین حسینی امیر یمن است . وی مردی فاضل و عارف به ادب بود. او را شعری است و به سال <span class=\"hlight\" dir=\"rtl\">١٠٩٧</span> هَ . ق . به کوکبان که مرکز امارت او بود درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180754, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ ]</font></b> (اِخ ) ابن میمی البصری . مردی فاضل و از مردم بصره است . از تألیفات اوست : رسائل فی المنطق و العروض و الصرف، و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٨٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180755, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ع َ دُل ْ دِ ]</font></b> (اِخ ) ابن محیی الدین بن مصطفی الحسنی الجزائری . وی در زمره ٔ امرا و علما و شعرا بود و اصل او از وهران الجزائر است که به سال <span class=\"hlight\" dir=\"rtl\">١٢٤٦</span> هَ . ق . که فرانسویان به الجزائر درآمدند مردم الجزائر بدو پیوستند، عبدالقادر مدت پانزده سال با فرانسویان جنگید وسرانجام به سال <span class=\"hlight\" dir=\"rtl\">١٢٦٣</span> با شرائطی تسلیم آنان شد. فرانسویان ابتدا او رابه طولون و سپس به انبواز تبعید کردند. سرانجام ناپلئون دوم وی را آزاد کرد بدان شرط که دیگر به الجزائر بازنگردد. از تألیفات اوست : ذکری العاقل . رسالة فی العلوم و الاخلاق . وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٢٢</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">١٣٠٠</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180756, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َدُل ْ دِ ]</font></b> (اِخ ) ابن محمدبن عمربن محمدبن یوسف بن عبداﷲبن نعیم، مکنی به ابوالمفاخر. در عصر خود مورخ دمشق بوده است . وی به سال <span class=\"hlight\" dir=\"rtl\">٨٤٥</span> هَ . ق . به دمشق متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٩٢٧</span> درگذشت . از تألیفات اوست : الدارس فی تواریخ المدارس که خلاصه ٔ آن به فرانسه ترجمه شده است . العنوان فی ضبط الموالید و الوفیات لاهل الزمان . تذکرة الاخوان فی حوادث الزمان . التبیین فی تراجم العلماء و الصالحین . تحفة البررة فی الاحادیث المعتبرة. افادة النقل فی الکلام علی العقل . (از الاعلام زرکلی ).<br /></font></div>'),
(180757, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ ]</font></b> (اِخ ) ابن محمدبن عبدالقادربن محمد الانصاری الجزیری . وی فاضل و باحث و از مردم مصر بود. از تألیفات اوست : درر الفوائد المنتظمة. فی اخبار الحاج و طریق مکة المعظمة. خلاصة الذهب فی فضل العرب . عمدة الصفوة فی حل القسوة. مجموعه ای شامل اشعار و مراسلات و فوائد. و نسبت او به جزیره ٔ فیل از اعمال مصر است . وی به سال <span class=\"hlight\" dir=\"rtl\">٨٨٠</span> هَ . ق . متولد شد و در حدود <span class=\"hlight\" dir=\"rtl\">٩٧٧</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180758, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ ]</font></b> (اِخ ) ابن محمدبن زین الفیومی . وی از مردم مصر و فقیه و عارف و عالم به فرائض و هیئت و میقات و موسیقی بود. از تألیفات اوست : شرح منهاج النووی در فقه شافعی . شرح النزهة فی الحساب . المقنع فی الجبر و المقابله و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٢٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180759, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ ]</font></b> (اِخ ) ابن القاسم بن احمد الانصاری السعدی العبادی المالکی . از علماء عربیت بود. به سال <span class=\"hlight\" dir=\"rtl\">٨١٤</span> هَ . ق . به مکه متولد شد و در <span class=\"hlight\" dir=\"rtl\">٨٨٠</span> هَ . ق . درگذشت . وی قضاوت مالکیه ٔ مکه را یافت . از تصنیفات اوست : هدایة السبیل فی شرح التسهیل . حاشیة علی التوضیح .حاشیة علی شرح الالفیة للمکودی . (از الاعلام زرکلی ).<br /></font></div>'),
(180760, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ ]</font></b> (اِخ ) ابن شیخ بن عبداﷲبن شیخ بن عبداﷲ العیدروس . وی مورخ و باحث و از مردم یمن بود. در حضرموت سکونت جست . سپس به احمدآبادهند رفت . مولد او به سال <span class=\"hlight\" dir=\"rtl\">٩٧٨</span> هَ . ق . است و به سال <span class=\"hlight\" dir=\"rtl\">١٠٣٨</span> هَ . ق . به احمدآباد درگذشت . از تألیفات اوست :النورالسافر فی اخبار القرن العاشر. الروض الناضر فی من اسمه عبدالقادر من اهل القرنین التاسع و العاشر. الفتوحات القدسیة فی الخرقة العیدروسیة. الحدائق الحضرة فی سیرة النبی و اصحابه العشرة. الحضرة العزیزة بعیون السیرة الوجیزة. الانموذج فی مناقب اهل بدر. الدرالثمین فی بیان المهم من علم الدین . غایة القرب فی شرح نهایة الطلب . الروض الاریض . و آن مجموعه ٔ منظومه های او است . قرة العین فی مناقب الولی با حسین . الزهر الباسم من روض الاستاذ حاتم . (از الاعلام زرکلی ).<br /></font></div>'),
(180761, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ ]</font></b> (اِخ ) ابن صالح بن عبدالرحمان الحلمی البانقوسی . وی فقیهی حنفی و فاضل و از مردم حلب بود. از تألیفات اوست : سلک النضار. تعلیق علی اوائل صحیح البخاری و شروحی دیگر. وی به سال <span class=\"hlight\" dir=\"rtl\">١١٤٢</span> متولد شدو به سال <span class=\"hlight\" dir=\"rtl\">١١٩٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180762, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ ]</font></b> (اِخ )ابن عبدالکریم الوردیغی المغربی . فقیهی مالکی و نحوی فاضل بود. از تألیفات اوست : سعدالشموس و الاقمار و زبد شریعة النبی المختار که در فقه و مذاهب اربعه است . بغیة المشتاق لاصول الدیانة و الاذواق . سلوة الاخوان فی الرد علی اهل الجحود و العدوان و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">١٣١٣</span> هَ . ق . به مصر درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180763, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ ]</font></b> (اِخ ) ابن عبداﷲبن اسماعیل العبدلانی . وی فقیهی متصوف و کردی الاصل است . به سال <span class=\"hlight\" dir=\"rtl\">١١٦٤</span> هَ. ق . به حلب متولد شد و سپس به دمشق رفت و به سال <span class=\"hlight\" dir=\"rtl\">١١٧٨</span> درگذشت . از تألیفات اوست : سلاح السفرفیما یوجب الظفر. رحلة الی الحجاز. الجمع الاوفی فی الصلاة علی المصطفی . رغبة الزوار فی الارتحال لزیارة الابرار. تحفة الاحباب فیمایجب به الخطاب . فردوس التدریس فی شرح قصیده ٔ محمدبن ادریس . زبدة اللیالی فی شرح عقیدة الامام غزالی . جود الموجود فی جحودالوجود. الکنز الاسنی فی شرح اسماء اﷲ الحسنی . المواضحة القویمة الفتح الربانی فی آداب طریقة الگیلانی . عین الصحو فی عوامل النحو. تحفة الاحبة فی علم اصول الحدیث . (از الاعلام زرکلی ).<br /></font></div>'),
(180764, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ ]</font></b> (اِخ ) ابن عثمان القاهری مشهور به الطوری . وی مفتی حنفیه ٔ مصر بود. در الازهر فتوی میداد و درس میگفت . از تألیفات اوست : شرح الکنز در فقه . الفوا که الطوریه در ادب . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٣٠</span> هَ . ق . به قاهره درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180765, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْدِ ]</font></b> (اِخ ) ابن علی بن یوسف بن محمد المغربی الفاسی المالکی . از بزرگان و شیوخ عصرخود بود. وی به تألیف نپرداخت و به جواب مسائل اکتفا میکرد. به سال <span class=\"hlight\" dir=\"rtl\">١٠٠٧</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">١٠٩١</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180766, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ ]</font></b> (اِخ ) ابن عمر البغدادی . وی عالم به ادب و تاریخ و اخباربود به سال <span class=\"hlight\" dir=\"rtl\">١٠٣٠</span> هَ . ق . به بغداد متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">١٠٩٣</span> به قاهره درگذشت . از تألیفات اوست : خزانة الادب . شرح کافیه ٔ استرابادی . شرح شواهد الشافیه . شرح شواهد. شرح تحفة الوردیة در نحو. (از الاعلام زرکلی ).<br /></font></div>'),
(180767, 'عبدالقادر', '<span class=\"hlight\">عبدالقادر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ ]</font></b> (اِخ ) ابن محمد معروف به ابن قضیب . رجوع به ابن قضیب و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180768, 'عبدالقادر گوینده', '<span class=\"hlight\">عبدالقادر گوینده .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ دِ رِ ی َ دَ ]</font></b> (اِخ ) از شعراء هرات و عالم به قراآت بود. از موسیقی اطلاعی کامل داشت و خط نیکو می نوشت . ابتدا به دارالسلام بغداد در مصاحبت سلطان احمد جلایر بسر می برد و مورد توجه و الطاف او بود، سپس از ملازمان میرزا میرانشاه شد. وی به سال <span class=\"hlight\" dir=\"rtl\">٨٣٨</span> هَ . ق . درگذشت . (از رجال حبیب السیر ص <span class=\"hlight\" dir=\"rtl\">١٠٦</span>).<br /></font></div>'),
(180769, 'عبدالقاهر', '<span class=\"hlight\">عبدالقاهر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ هَ ]</font></b> (اِخ ) ابن حاج عبدالرجب بن المخلص العبادی . وی مردی فاضل، عالم، متکلم و فقیه بود و شعر میگفت . از تألیفات اوست : عقاید الدینیه علی البراهین العقلیه المستمسکات القطعیة الیقینیة. ریاض الجنان و حدائق الغفران . نیلوفریه (که ناقص است ). فرائد الصافیة علی الفوائد الوافیة. (حاشیه بر شرح جامی ). رفع الغوایة (شرح الهدایة) وجز آن، و او را دیوان شعری است . (از روضات ص <span class=\"hlight\" dir=\"rtl\">٣٦٠</span>).<br /></font></div>'),
(180770, 'عبدالقاهر', '<span class=\"hlight\">عبدالقاهر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ هَِ ]</font></b> (اِخ ) ابن شعیب، مکنی به ابورفاعة. رجوع به ابورفاعه عبدالقاهر شود.<br /></font></div>'),
(180771, 'عبدالقاهر', '<span class=\"hlight\">عبدالقاهر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ هَِ ]</font></b> (اِخ ) ابن طاهربن محمدبن عبداﷲ البغدادی التمیمی الاسفراینی، مکنی به ابومنصور. رجوع به ابومنصور بغدادی و به الاعلام زرکلی شود.<br /></font></div>'),
(180772, 'عبدالقاهر', '<span class=\"hlight\">عبدالقاهر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ هَِ ]</font></b> (اِخ ) ابن طاهر التمیمی، مکنی به ابوسعید. رجوع به ابوسعید عبدالقاهر شود.<br /></font></div>'),
(180773, 'عبدالقاهر', '<span class=\"hlight\">عبدالقاهر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ هَِ ]</font></b> (اِخ ) ابن عبداﷲبن الحسین الحلبی، مکنی به ابوالفرج شاعر مجید بود. او راست : شرح بر دیوان المتنبی .وی به سال <span class=\"hlight\" dir=\"rtl\">٥٥١</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180774, 'عبدالقاهر', '<span class=\"hlight\">عبدالقاهر.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ هَِ ]</font></b> (اِخ ) ابن عبدﷲبن محمد البکری الصدیقی، مکنی به ابوالنجیب و معروف به سهروردی .رجوع به ابوالنجیب سهروردی و به الاعلام زرکلی شود.<br /></font></div>'),
(180775, 'عبدالقاهر تبریزی', '<span class=\"hlight\">عبدالقاهر تبریزی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ هَِ رِ ت َ ]</font></b> (اِخ ) ابن محمدبن عبدالواحد التبریزی الحرانی الدمشقی . اصل او از تبریز و مولد وی حران و نشأتش به دمشق بود و قضاوت صفد و دمیاط یافت . وی به سال <span class=\"hlight\" dir=\"rtl\">٦٤٨</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">٧٤٠</span> درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180776, 'عبدالقاهر جرجانی', '<span class=\"hlight\">عبدالقاهر جرجانی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ هَِ رِ ج ُ ]</font></b> (اِخ ) ابن عبد الرحمان شافعی اشعری . ادیب، نحوی و لغوی است . از پیشوایان نحو و عربیت است . وی علم معانی و بیان را بنیان گذارد و تألیفات بسیار دارد از جمله : اسرار البلاغة در معانی و بیان . اعجاز القرآن (صغیر). اعجاز القرآن (کبیر).التلخیص در علم معانی . الجمل . دلائل الاعجاز. شرح الفاتحة. العروض . العمدة فی الصرف . العوامل المائة المفتاح فی شرح الصحاح . و المقصد. وی اشعاری نیز سروده است و به سال <span class=\"hlight\" dir=\"rtl\">٤٧١</span> هَ . ق . به جرجان درگذشت . (از الاعلام زرکلی ) (از روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٤٣</span>) (از ریحانة الادب ).<br /></font></div>'),
(180777, 'عبدالقدوس', '<span class=\"hlight\">عبدالقدوس .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ق ُدْ دو ]</font></b> (اِخ ) ابن حبیب الدمشقی . رجوع به ابوسعید عبدالقدوس شود.<br /></font></div>'),
(180778, 'عبدالقیس', '<span class=\"hlight\">عبدالقیس .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ق َ ]</font></b> (اِخ ) ابن اقصی . قبیله ای است بزرگ منسوب به عبدالقیس بن اقصی بن دعمی بن جدیلةبن اسدبن ربیعه ... جماعتی بسیار از آن قبیله ازصحابیان بودند. مسکن آنها ابتدا تهامه و سپس به بحرین بود. قراء جار، قمادی، جبلة، بیضا و جز آن از آن ایشان است . در عهد رسول (ص ) عده ای از آنان او را یاری کردند. (از معجم قبائل العرب ) (از الاعلام زرکلی ).<br /></font></div>'),
(180779, 'عبداللطیف', '<span class=\"hlight\">عبداللطیف .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ل َ ]</font></b> (اِخ ) انسی قاضی مستعرب و متأدب بود و انشاء نیک مینوشت . و او راست شعری . وی از موالی روم بود و قضاء رکب و محاسبت اوقاف مصر یافت به روم رفت و ولایت قضاء طرابلس شام یافت . و سپس قضاوت کوتاهیه و مرعش و جیزه و جز آن یافت . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٧٥</span> هَ . ق . به دمشق درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180780, 'عبداللطیف', '<span class=\"hlight\">عبداللطیف .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ل َ ]</font></b> (اِخ ) ابن یوسف بن محمدبن علی البغدادی معروف به ابن اللباد. از فلاسفه ٔ اسلام و یکی از علما است . در حکمت و علم النفس و طب و تاریخ و جغرافیا و ادب کتابهای بسیار تألیف کرد. وی را حافظه ای قوی بود. و از کتب اوست : الافادة و الاعتبار بما فی مصر من الاَّثار. قوانین البلاغة. الانصاف بین ابن بری و ابن الخشاب . الجامع الکبیر در منطق و طبیعی در ده مجلد. بلغة الحکیم . الکلمة فی الربوبیة. تهذیب کلام افلاطون . القیاس در چهار مجلد. السماع الطبیعی . غریب الحدیث . شرح احادیث ابن ماجه و کتابهای بسیاری را خلاصه کرده است . از جمله : الحیوان للجاحظ. کتاب العمدة و او را رسائل کوچکی نیز هست که مقالات نامیده است ازجمله : النفس . العلم الالهی . الماء. الحرکات المعتاصة. العادات . الحواس و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">٥٥٥</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">٦٢٩</span> به بغداد درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180781, 'عبداللطیف', '<span class=\"hlight\">عبداللطیف .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ل َ ]</font></b> (اِخ ) ابن علی بن احمدبن ابی جامع العاملی . فقیه، فاضل و از شاگردان شیخ بهائی و شیخ حسن بن الشهید الثانی و غیره بود. از تألیفات اوست : الرجال . جامع الاخبار فی ایضاح الاستبصار و جز آن . (از روضات ص <span class=\"hlight\" dir=\"rtl\">٣٦٣</span>).<br /></font></div>'),
(180782, 'عبداللطیف', '<span class=\"hlight\">عبداللطیف .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ل َ ]</font></b> (اِخ ) ابن عبدالمنعم بن الصیقل الحرانی الحنبلی، مکنی به ابوالفرج . عالم به حدیث و از مسانید مصر در زمان خود بود. از کتب اوست : السباعیات در حدیث .وی به سال <span class=\"hlight\" dir=\"rtl\">٦٧٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180783, 'عبداللطیف', '<span class=\"hlight\">عبداللطیف .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ل َ ]</font></b> (اِخ ) ابن ابی بکربن احمد الیمانی الزبیدی . از علماء عربیت است . از تألیفات اوست : شرح ملحة الاعراب . مقدمة فی علم النحو. نظم مقدمه ٔ ابن بایشاذ. (از الاعلام زرکلی ).<br /></font></div>'),
(180784, 'عبداللطیف', '<span class=\"hlight\">عبداللطیف .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ل َ ]</font></b> (اِخ ) ابن عبدالعزیزبن ملک . فقیه حنفی است . از آثار اوست : مبارق الازهار فی شرح مشارق الانوار فی الحدیث . شرح المنار فی الاصول و جز آن . وی در حدود سال <span class=\"hlight\" dir=\"rtl\">٨٨٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180785, 'عبداللهی بالا', '<span class=\"hlight\">عبداللهی بالا.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لاه ی ِ ]</font></b> (اِخ ) دهی است از دهستان رستم بخش فهلیان و ممسنی شهرستان کازرون واقع در هشت هزارگزی شمال خاور فهلیان کنار شوسه ٔ کازرون به بهبهان . ناحیه ای است واقع در دامنه . گرمسیر و مالاریایی است <span class=\"hlight\" dir=\"rtl\">١١٩</span> تن سکنه دارد. آب آن از رودخانه فهلیان و چشمه تأمین میشود محصولاتش : غلات، برنج، حبوبات است اهالی به کشاورزی اشتغال دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(180786, 'عبداللهی شرف الدین', '<span class=\"hlight\">عبداللهی شرف الدین .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ لا ی ِ ش َ رَ فِدْ دی ]</font></b> (اِخ ) دهی است از دهستان رستم بخش فهلیان و ممسنی شهرستان کازرون . واقع در <span class=\"hlight\" dir=\"rtl\">٩</span>هزارگزی شمال باختری فهلیان کنار شوسه ٔ کازرون به بهبهان . ناحیه ای است در دامنه گرمسیر و مالاریایی . <span class=\"hlight\" dir=\"rtl\">١٠٠</span>تن سکنه دارد. آب آن از رودخانه ٔ فهلیان تأمین میشود. محصولاتش غلات، برنج و حبوبات است . اهالی به کشاورزی اشتغال دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(180787, 'عبدالمجید', '<span class=\"hlight\">عبدالمجید.</span> <font color=\"DarkGreen\"><b>[ع َ دُل ْ م َ ]</font></b> (اِخ ) ابن علی المنالی الزیادی الحسنی الادریسی . مردی فاضل بود و او را نظم و مؤلفاتی است . از اوست : بلوغ المرام بالرحلة الی بیت اﷲ الحرام . وی به سال <span class=\"hlight\" dir=\"rtl\">١١٦٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180788, 'عبدالمجید', '<span class=\"hlight\">عبدالمجید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ]</font></b> (اِخ ) دهی است از دهستان احمدآباد بخش فریمان شهرستان مشهد واقع در <span class=\"hlight\" dir=\"rtl\">٤٠</span>هزارگزی شمال باختری فریمان . جلگه ای و گرمسیر است . <span class=\"hlight\" dir=\"rtl\">٢٥٩</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات، و چغندر است . اهالی به زراعت اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180789, 'عبدالمجید', '<span class=\"hlight\">عبدالمجید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ]</font></b> (اِخ ) ابن اسماعیل بن محمد القیسی الهروی . قاضی بلاد روم و ثقه بود. در ماوراء النهر فقه آموخت و در بغداد و بصره و همدان و بلاد روم تدریس کرد. وی به سال <span class=\"hlight\" dir=\"rtl\">٥٣٤</span> هَ . ق . به دمشق شد و به سال <span class=\"hlight\" dir=\"rtl\">٥٣٧</span> هَ . ق . به قیساریه درگذشت . او را کتبی است در فروع و اصول . (از الاعلام زرکلی ).<br /></font></div>'),
(180790, 'عبدالمجید', '<span class=\"hlight\">عبدالمجید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ]</font></b> (اِخ ) ابن عبدون الفهری، مکنی به ابومحمد. رجوع به عبدون ابومحمد عبدالمجید و الاعلام زرکلی شود.<br /></font></div>'),
(180791, 'عبدالمجید', '<span class=\"hlight\">عبدالمجید.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ]</font></b> (اِخ ) ابن محمدبن المستنصر باﷲ العبیدی ملقب به الحافظ لدین اﷲ. از خلفاءفاطمیه ٔ مصر است . به سال <span class=\"hlight\" dir=\"rtl\">٤٦٧</span> هَ . ق . به عسقلان متولد و به سال <span class=\"hlight\" dir=\"rtl\">٥٢٤</span> هَ . ق . بر دیار مصر تسلط یافت و به سال <span class=\"hlight\" dir=\"rtl\">٥٤٤</span> هَ . ق . به مصر درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180792, 'عبدالمحسن', '<span class=\"hlight\">عبدالمحسن .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م ُ س ِ]</font></b> (اِخ ) ابن حمود التنوخی الحلبی . ادیب و شاعر و کاتب و وزیر عزالدین آپبک صاحب صرخد بود. از تألیفات اوست : مفتاح الافراح فی امتداح الراح . الاخبار و النوادر. دیوان شعر و دیوان ترسل . وی به سال <span class=\"hlight\" dir=\"rtl\">٥٧٠</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">٦٤٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180793, 'عبدالمحسن', '<span class=\"hlight\">عبدالمحسن .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م ُ س ِ ]</font></b> (اِخ ) ابن علی الاشیقری . فقیه حنبلی بود. وی در زبیر نزدیکی بصره تصدی افتاء یافت . از مردم اشیقر ازقرای وشم است . او را تألیفی است . وی به سال <span class=\"hlight\" dir=\"rtl\">١١٨٧</span> هَ . ق . به بیماری طاعون درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180794, 'عبدالمحسن', '<span class=\"hlight\">عبدالمحسن .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م ُس ِ ]</font></b> (اِخ ) ابن محمدبن احمد الصوری . شاعر و در الفاظ او رقتی است و معانی نکو دارد. او را دیوان شعری است . به سال <span class=\"hlight\" dir=\"rtl\">٤١٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180795, 'عبدالمسیح', '<span class=\"hlight\">عبدالمسیح .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ]</font></b> (اِخ ) ابن عسلة الشیبانی . شاعری جاهلی است . صاحب مفضلیات قطعاتی از اشعار او را انتخاب کرده است . (از الاعلام زرکلی ).<br /></font></div>'),
(180796, 'عبدالمطلب', '<span class=\"hlight\">عبدالمطلب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م ُطْ طَ ل ِ ]</font></b> (اِخ ) ابن حسن بن ابی نمی شریف حسنی . از امراء مکه و مردی شجاع، عاقل و جوانمرد بود در زمان پدر خود بکارهای مکه پرداخت و بعد از مرگ پدر نیز مدت کمی امارت آنجا را داشت و به سال <span class=\"hlight\" dir=\"rtl\">١٠١٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180797, 'عبدالمطلب', '<span class=\"hlight\">عبدالمطلب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م ُطْ طَ ل ِ ]</font></b> (اِخ ) ابن ربیعةبن الحارث بن عبدالمطلب بن هاشم . صحابی و ساکن مدینه بود. در خلافت عمر به شام رفت و به سال <span class=\"hlight\" dir=\"rtl\">٦٢٠</span> هَ . ق . به دمشق درگذشت . از او در صحیحین دو حدیث نقل شده است . (از الاعلام زرکلی ).<br /></font></div>'),
(180798, 'عبدالمطلب', '<span class=\"hlight\">عبدالمطلب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م ُطْ طَ ل ِ ]</font></b> (اِخ ) ابن غالب بن مساعد الحسنی . از امراء مکه و مولد و وفات او بدانجا است . به سال <span class=\"hlight\" dir=\"rtl\">١٢٤٣</span> هَ . ق . امارت مکه یافت و پس از <span class=\"hlight\" dir=\"rtl\">٥</span> ماه معزول شد و به شرق و آستانه رفت و تا سال <span class=\"hlight\" dir=\"rtl\">١٢٦٧</span> هَ . ق . بدانجا بود. سپس به امارت مکه رسید و تا سال <span class=\"hlight\" dir=\"rtl\">١٢٧٢</span> هَ . ق . در آن شغل باقی ماند و چون در مکه بر سر منع برده فروشی فتنه پدید آمد حکومت ترک او را معزول کرد. مجدداً وی به آستانه رفت و تا سال <span class=\"hlight\" dir=\"rtl\">١٢٩٧</span> هَ . ق . بدانجا بماند سپس دیگر بار حکومت ترک وی را به امارت مکه فرستاد و تا سال <span class=\"hlight\" dir=\"rtl\">١٢٩٩</span> هَ . ق . امارت کرد. تولد او به سال <span class=\"hlight\" dir=\"rtl\">١٢٠٩</span> هَ . ق . بود و درحدود سال <span class=\"hlight\" dir=\"rtl\">١٣٠٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180799, 'عبدالمطلب', '<span class=\"hlight\">عبدالمطلب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م ُطْ طَ ل ِ ]</font></b> (اِخ ) ابن فضل الهاشمی الحلبی .فقیه حنفی است . او راست : شرح الجامع الکبیر در فقه .وی به سال <span class=\"hlight\" dir=\"rtl\">٦١٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180800, 'عبدالمطلب', '<span class=\"hlight\">عبدالمطلب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م ُطْ طَ ل ِ ]</font></b> (اِخ ) ابن هاشم بن عبدمناف، مکنی به ابوالحارث . بزرگ قریش در زمان جاهلیت و از بزرگان عرب بود. وی مردی عظیم الشأن و رفیعمنزلت و متصف به اوصاف حمیده و مشتهربه افعال پسندیده بود. فصیح اللسان، حاضرالقلب بود.وی جد پدری حضرت رسول و علی بن ابی طالب است . قوم قریش ریاست و تقدم او را قبول و به وجودش افتخار و مباهات مینمودند. در روضة الصفاست که چون عبدالمطلب متولد شد مویهای سفید بر سر داشت بدین جهت او را شیبه خواندند و بعد از آنکه به سن رشد رسید و به کثرت محامدموصوف گشت شیبة الحمدش خواندند. بعضی از اعاظم گویند که پس از درگذشت هاشم پدر عبدالمطلب مطلب بن عبدمناف برادر هاشم از پریشان حالی برادرزاده ٔ خود آگاه شد به مدینه رفت و شیبة الحمد را با خود به مکه برد و در اثناء راه هر کس از مطلب میپرسید که شیبة الحمد رابا تو چه نسبت است میگفت «عبدی » و بدانجهت اسم عبدالمطلب بر شیبة الحمد بماند و وجوه دیگری نیز گفته اند. پس از فوت مطلب بن مناف ریاست قریش به عبدالمطلب رسید و کلیددار خانه ٔ کعبه شد و منصب پرده داری را نیز بعهده گرفت و اهالی مسجد الحرام وی را بزرگ و مکرم میداشتند و در حوادث بدو متوسل میشدند. از جمله آثار عبدالمطلب حفر چاه زمزم است . عبدالمطلب نذر کرد که هرگاه خدای متعال بدو ده پسر کرامت کند یکی از آن جمله را به سنت جدش ابراهیم قربان کند. خدای حاجتش برآورد او را بیش از ده پسر عنایت کرد به نامهای حارث، ابوطالب، زبیر، حمزه، ابولهب، غیداق، مقوم، ضرار، عباس، قشم، عبدالکعبه، حجل، عبداﷲ. عبدالمطلب بر آن شد که نذرش ادا کند قرعه به نام عبداﷲ پدر حضرت رسول افتاد و چون خواست او را قربان کند خویشان مادری او ممانعت کردند. عبدالمطلب واقعه را به سجام کاهنه بگفت سجام گفت دیت در میان شما چند است گفت ده شتر. بدستور او میان عبداﷲ و ده شتر قرعه زدند و همین طور ده ده قرعه زدند تا به صد شتر رسید و عبداﷲ از ذبح نجات یافت . عبدالمطلب را شش دختر نیز بود. به نامهای صفیه، عاتکه، بیضاء، بره، میمه، اروی . در تعداد و نام فرزندان عبدالمطلب اختلاف است . (از حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٢٨٦</span>- <span class=\"hlight\" dir=\"rtl\">٢٨٨</span>) (از الاعلام زرکلی ) (از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٨</span>).<br /></font></div>'),
(180801, 'عبدالمعطی', '<span class=\"hlight\">عبدالمعطی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م ُ ]</font></b> (اِخ ) ابن حسن بن عبداﷲ باکثیر المکی الحضرمی . وی عارف به تفسیر و حدیث بود به سال <span class=\"hlight\" dir=\"rtl\">٩٠٥</span> هَ . ق . به مکه متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٩٨٩</span> هَ. ق . به احمدآباد هند درگذشت . از تصانیف او است : اسماء رجال البخاری که مجلدی ضخیم از آن نوشت و به اتمام نرسید او را نظم بسیاری است . (از الاعلام زرکلی ).<br /></font></div>'),
(180802, 'عبدالمعطی', '<span class=\"hlight\">عبدالمعطی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م ُ ]</font></b> (اِخ ) ابن محی الدین الخلیلی . فقیه شافعی است . مولد وی به فلسطین بودو در قدس سکونت جست و تولی افتاء مذهب شافعی را یافت و به سال <span class=\"hlight\" dir=\"rtl\">١١٥٤</span> هَ . ق . درگذشت . او راست : مجموعه ٔ فتاوی و رسائل و او را نظمی است . (از الاعلام زرکلی ).<br /></font></div>'),
(180803, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن حسین بن عبدالملک المکی العصامی . مورخ و از مردم مکه است . به مکه متولد شد و هم در آنجا درگذشت . او راست : سمط النجوم . العوالی فی انباء الاوائل و التوالی . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٤٩</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١١١١</span> هَ . ق . به مکه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180804, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن عبداﷲبن یوسف بن جوینی ملقب به امام الحرمین . رجوع به ابوالمعالی جوینی عبدالملک و امام الحرمین شود.<br /></font></div>'),
(180805, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن احمدبن عبدالملک بن شهید القرطبی، مکنی به ابومروان و ملقب به ابن شهید.رجوع به ابن شهید ابوعامر و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180806, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن احمدبن یوسف بن احمد الجذامی . از بنی هود و از امراء دولت هودیه در سرقسطة اندلس بود. پس از مرگ پدر به سال <span class=\"hlight\" dir=\"rtl\">٥٠٣</span> هَ . ق . ولایت سرقسطةرا یافت و مدتی در آن سمت بود. سپس به سال <span class=\"hlight\" dir=\"rtl\">٥١٢</span> هَ .ق . الفونس ششم پادشاه اراغون بر او غالب شد و عبدالملک به قلعه ای به نام روطه پناه برد و تا سال <span class=\"hlight\" dir=\"rtl\">٥١٣</span> هَ. ق . که درگذشت در آنجا بماند. (از الاعلام زرکلی ).<br /></font></div>'),
(180807, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن اسماعیل بن الشریف محمدبن علی العلوی، مکنی به ابومروان . از ملوک دولت اشراف علویین در مغرب اقصی است به سال <span class=\"hlight\" dir=\"rtl\">١١٤٠</span> هَ . ق . به فاس با وی بیعت کردند و او به مکناسه رفت و در آنجا یاران وی برادر او احمد ذهبی را دستگیر کرده بودند عبدالملک او را بند نهاد و به سجلماسه فرستاد پیروان ذهبی بر خلع او اتفاق کردند عبدالملک بدانست و بفاس رفت . ذهبی بازگشت و بامردم فاس جنگ کرد تا آنکه عبدالملک را به وی تسلیم کردند ذهبی او را به مکناسه آورد و بفرمود تا او را به سال <span class=\"hlight\" dir=\"rtl\">١١٤١</span> هَ . ق . خفه کردند. (از الاعلام زرکلی ).<br /></font></div>'),
(180808, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن جمال العصامی الاسفرایینی . از بزرگان علماء عربیت است . او راست : الحاشیة علی شرح الکافیة. الاطول (عارض به المطول ). بلوغ الارب من کلام العرب .الکافی فی العروض و القوافی . شرح ایساغوجی التسهیل فی العروض . رسالة فی تحریم الدخان و جز آن از شروح وحواشی . وی به سال <span class=\"hlight\" dir=\"rtl\">٩٧٨</span> هَ . ق . به مکه متولد شد و در<span class=\"hlight\" dir=\"rtl\">١٠٣٧</span> هَ . ق . به مدینه درگذشت . (از الاعلام زرکلی ).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(180809, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن حبیب بن سلیمان بن هارون السلمی، مکنی به ابومروان . رجوع به ابن حبیب ابومروان و الاعلام زرکلی شود.<br /></font></div>'),
(180810, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن عمربن مروان بن الحکم . قعید و فارس آل مروان بود. وی به سال <span class=\"hlight\" dir=\"rtl\">١٤٠</span> هَ . ق . از مصر به اندلس شد و ولایت اشبیلیه را یافت . از یاوران عبدالرحمان الداخل بود. عبدالرحمان وی را نصیبی فراوان بخشید و دختر خویش کثرة را به پسر او هشام بزنی داد و فرزندان او را وزیر خود کرد. وی در حدود سال <span class=\"hlight\" dir=\"rtl\">١٦٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180811, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span><font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن دثار الباهلی . از اشراف و شجعان عرب است . در جنگهای اشرس بن عبداﷲ با مردم سمرقند و ماوراءالنهر حاضر بود و در یکی از همان وقایع به سال <span class=\"hlight\" dir=\"rtl\">١١٠</span> هَ . ق . کشته شد. (از الاعلام زرکلی ).<br /></font></div>'),
(180812, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن زهربن عبدالملک بن محمدبن مروان بن زهر. رجوع به ابن زهر چند تن از دانشمندان خاندان اندلسی شود. و نیز رجوع شود به الاعلام زرکلی .<br /></font></div>'),
(180813, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن زیدان بن احمد المنصور السعدی . از ملوک دولت اشراف سعدیین مراکش است . پس از مرگ پدرش به سال <span class=\"hlight\" dir=\"rtl\">١٠٣٧</span> هَ . ق . با وی به خلافت بیعت کردند. برادرانش ولید و احمد بر او شوریدند و سرانجام یکی از مردم مراکش به تحریک ولید وی را به سال <span class=\"hlight\" dir=\"rtl\">١٠٤٠</span> هَ . ق . بکشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180814, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن صالح بن علی بن عبداﷲبن عباس . امیری از بنی عباس بود. به سال <span class=\"hlight\" dir=\"rtl\">١٦٩</span> هَ . ق . الهادی وی را امارت موصل داد.و به سال <span class=\"hlight\" dir=\"rtl\">١٧١</span> هَ . ق . رشید او را عزل کرد سپس او راوالی مدینه و طائف کرد. در این هنگام رشید را خبر دادند که عبدالملک طالب خلافت است رشید او را به بغدادزندانی کرد. پس از مرگ رشید امین او را از زندان آزاد کرد و به سال <span class=\"hlight\" dir=\"rtl\">١٩٦</span> هَ . ق . ولایت جزیره و شام را بدو داد و تا سال <span class=\"hlight\" dir=\"rtl\">١٩٦</span> هَ . ق . که درگذشت در رقه بود. عبدالملک مردی سخت فصیح و خطیب و بامهابت و صلابت بود.چون رشید عبدالملک را ولایت مدینه داد یحیی بن خالد برمکی را پرسیدند چگونه رشید یحیی را از بین عمال خویش برگزید. گفت خواست تا بر قریش ببالد و به آنان بیاموزد که در بنی عباس همچون عبدالملک مردی است و این توصیف تحریضی است علیه عبدالملک . (از الاعلام زرکلی ).<br /></font></div>'),
(180815, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ]</font></b> (اِخ ) ابن عبدالسلام بن عبدالحفیظبن دعسین الاموی القرشی . وی از ائمه ٔ یمن و عالم به کتاب و سنت و مطلع به تاریخ و ادب بود. از تصنیفات اوست : منحة الملک الوهاب بشرح ملحة الاعراب . قرةالعین بمعرفة بنی دعسین، واو را نظمی است . وی به سال <span class=\"hlight\" dir=\"rtl\">٩٥٢</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٠٠٦</span> هَ . ق . به یمن درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180816, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن عبدالعزیزبن جریح، مکنی به ابوالولید. رجوع به ابن جریح ابوخالد عبدالملک و الاعلام زرکلی شود.<br /></font></div>'),
(180817, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن عبدالعزیز السلولی . از شعراء و فصحائی است که به خلفا نپیوست و امرا را مدح نگفت . وی در حدود سال <span class=\"hlight\" dir=\"rtl\">١٠٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180818, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن عبداﷲبن محمدبن امیةبن یزیدبن ابی حوثرة، مکنی به ابومروان . از وزراء دولت اموی اندلس بود. منصب وزارت و کتابت امیر محمدبن عبدالرحمان و منذربن محمد را یافت و در عهد عبداﷲبن محمد وزارت و فرماندهی سپاه بعهده ٔ او محول گشت و در حالی که فرماندهی سپاهیان خود را بعهده داشت مظرف بن عبداﷲ در دو میلی اشبیلیه به سال <span class=\"hlight\" dir=\"rtl\">٢٨٢</span> هَ . ق . وی را بکشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180819, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن قریب بن علی بن اصمع الباهلی، مکنی به ابوسعید و معروف به اصمعی . رجوع به اصمعی و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180820, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن قطن الفهری . امیر اندلس بود.به سال <span class=\"hlight\" dir=\"rtl\">١١٤</span> هَ . ق . پس از قتل عبدالرحمان غافقی ولایت اندلس را یافت و شهرهائی را که از جمله آنها جلیقیه (در شمال شرقی اندلس ) است فتح کرد. به سال <span class=\"hlight\" dir=\"rtl\">١١٧</span> هَ . ق . ابن الحبحاب امیر افریقیه او را معزول ساخت و بجای او عقبةبن حجاج را گماشت لکن عبدالملک نپذیرفت تا آنکه به سال <span class=\"hlight\" dir=\"rtl\">١٢٣</span> هَ . ق . عقبة درگذشت و مردم اندلس او را به امیری خود برگزیدند. وی نیز کار اندلس را منظم کرده در این هنگام بلج بن بشر به میهمانی بر او وارد شد عبدالملک او را اکرام کرد و پس از ماندن او ترسید و از او خواست تا آنجا را ترک گوید بلج و یاران او بر وی بشوریدند و او را بکشتند (<span class=\"hlight\" dir=\"rtl\">١٢٣</span> هَ . ق .). مولد او به سال <span class=\"hlight\" dir=\"rtl\">٣٣</span> هَ . ق . بود. (از الاعلام زرکلی ).<br /></font></div>'),
(180821, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن محمدبن ابراهیم النیشابوری، مکنی به ابوسعید. واعظ و از علماء نیشابور بود از تألیفات او است : شرف المصطفی در هشت جزء.وی به سال <span class=\"hlight\" dir=\"rtl\">٤٠٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180822, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ]</font></b> (اِخ ) ابن محمدبن اسماعیل، مکنی به ابومنصور و معروف به ثعالبی . رجوع به ثعالبی و الاعلام زرکلی شود.<br /></font></div>'),
(180823, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن محمدبن عدی الجرجانی الاسترآبادی، مکنی به ابونعیم . فقیه، حافظ حدیث و از مردم استرآباد بود. از تصنیفات او است : کتاب الضعفاء فی رجال الحدیث در ده جزء. وی به سال <span class=\"hlight\" dir=\"rtl\">٢٤٢</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">٣٢٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180824, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن محمدبن عطیة السعدی . از مردم سعدهوازن است . مروان بن محمد او را با چهارهزار سوار به جنگ ابوحمزه و طالب الحق فرستاد. عبدالملک ابوحمزه را در وادی القری از اعمال مدینه بدید و بکشت و سپاهیانش را پراکنده ساخت سپس قصد یمن کرد و به سر وقت طالب الحق که در یمن با وی به خلافت بیعت کرده بودند رفت . وی طالب الحق را بکشت و سر او را به شام فرستاد و خود به صنعاء رفت و در آنجا اقامت گزید. مروان بدو نوشت که فوراً بازگردد و با مردم حج کند. عبدالملک سپاهیان خود را در صنعاء گذارد و با عده ٔ اندک براه افتاد در راه جمعی از بنی مراد بدو رسیدند و اورا به سال <span class=\"hlight\" dir=\"rtl\">١٣٠</span> هَ . ق . بکشتند. (از الاعلام زرکلی ).<br /></font></div>'),
(180825, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن محمد شیخ بن القائم بامراﷲ، مکنی به ابومروان ملقب به المعتصم السعدی . رجوع به ابن زهر و الاعلام زرکلی شود.<br /></font></div>'),
(180826, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن مروان الحکم الاموی . به سال <span class=\"hlight\" dir=\"rtl\">٢٠</span> هَ . ق . متولد شد. وی از بزرگان خلفای اموی است . پس از مرگ پدر به سال <span class=\"hlight\" dir=\"rtl\">٦٥</span> هَ . ق . به خلافت رسید عمروبن سعد را که در زمان خلافت پدرش مروان حاکم دمشق بود به نیابت خود برگزید و خود بقصدنبرد با مصعب متوجه عراق عرب شد. عمرو در غیاب او داعیه ٔ خلافت و استقلال کرد عبدالملک در اثناء راه از این امر آگاه شد دفع دشمن خانگی اولی دید بازگشت عمرودر دمشق متحصن گردید. عبدالملک او را محاصره کرد پس از گذشت چهارماه به مصالحه انجامید بر این موجب که عبدالملک به امامت پردازد و عمرو ضبط اموال دیوانی را بعهده گیرد. سرانجام به سال <span class=\"hlight\" dir=\"rtl\">٦٨</span> - <span class=\"hlight\" dir=\"rtl\">٦٩</span> هَ . ق . عمرو به دست عبدالملک به قتل رسید و با فراغت خاطر به سال <span class=\"hlight\" dir=\"rtl\">٧١</span> هَ . ق . لشکریان فراهم و به عراق عرب سپس به کوفه رفت و با لشکریان مصعب در نواحی قرقیا نبرد کرد و سرانجام مصعب به قتل رسید و سرش را نزد عبدالملک بردند. و بدین ترتیب عراق عرب به تصرف عبدالملک درآمد. وی مملکت فارس و اهواز و عراق عجم را نیز تسخیر کرد.در عصر او دیوانهائی از فارسی و رومی به عربی ترجمه شد. وی نخستین کسی است که در اسلام به دینار سکه زد و پیش از وی عمربن خطاب درهم ها را سکه زده بود. عبدالملک به حزم شهرت داشت چنانکه معاویه به حکم . در حدیث و شعر وارد بود. وی به سال <span class=\"hlight\" dir=\"rtl\">٨٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ) (از حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">١٤٧</span> - <span class=\"hlight\" dir=\"rtl\">١٤٨</span>).<br /></font></div>'),
(180827, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن مهلب بن ابی صفرة الازدی . از شجعان عرب و اشراف بود. با برادرش یزید بر بنی مروان خروج کرد. سرانجام با برادرش مفضل به سال <span class=\"hlight\" dir=\"rtl\">١٠٢</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180828, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن نوح بن نصربن احمد السامانی، مکنی به ابوالفوارس . پس از مرگ نوح پسر ارشدش امیر رشید عبدالملک به امیری رسید و او پس از جلوس، ابومنصور محمدبن عزیر را به وزارت خویش برداشت و ابوسعید بکربن مالک فرغانی را که پدرش بجای ابوعلی چغانی نامزد سپهسالاری خراسان کرده بود در آن مقام ابقاء نمود. ابوعلی چغانی که از عزل خود سخت ناراضی بود موفق شد که به دستیاری آل بویه از طرف مطیع خلیفه ٔ عباسی فرمان ایالت خراسان را بگیرد و مدعی بوسعید گردد. ابوعلی چغانی و رکن الدوله و حسن فیروزان به گرگان حمله بردند و تا جاجرم خراسان پیش آمدند لیکن حریف اردوی سامانی نشدند و منهزماً به طبرستان برگشتند و از آنجا به ری آمدند و کمی بعد یعنی در رجب سال <span class=\"hlight\" dir=\"rtl\">٣٤٤</span> هَ . ق . ابوعلی چغانی در وبای عمومی ری مرد. و سامانیان از جانب او خلاص یافتند. ابوسعید برای آنکه از طریقی دیگر مزاحم رکن الدوله شود سپاهی گران به سرداری محمدبن ماکان از راه بیابان بفتح اصفهان که سپرده به مؤیدالدوله بود روانه نمود و محمد مؤیدالدوله را شکست داد. اصفهان را فتح کرد و بر اموال و عیال رکن الدوله دست یافت و رکن الدوله وزیر خود ابوالفضل بن العمید را به اصفهان فرستاد و ابن العمید محمدبن ماکان را دستگیر ساخت و سپاهیان او را منهزم و پراکنده کرد عاقبت رکن الدوله و ابوسعید صلح نمودند و قرار شد رکن الدوله بر جمیع بلاد جبل و ری مسلط بماند و در عوض هر سال <span class=\"hlight\" dir=\"rtl\">٢٠٠</span>هزار دینار به بخارا پیش عبدالملک سامانی بفرستد. بعد از ختم غائله ٔ خراسان و ری ابوسعید به بخارا احضار شد چه جمعی ازسپاهیان ترک از او خشنود نبودند و بهمین جهت او را ترک گفته و بشکایت پیش عبدالملک آمدند و از بدرفتاریهای او گله کردند. عبدالملک هم امر به قتل او داد البتکین حاجب او را در سال <span class=\"hlight\" dir=\"rtl\">٣٤٥</span> هَ . ق . بر در سرای عبدالملک بر زمین زد و کشت و متعاقب آن محمدبن عزیز نیزاز وزارت به زندان افتاد و مقام او نصیب ابوجعفر احمدبن حسین عتبی گردید. و سپهسالاری خراسان هم بکفایت ابوالحسن محمدبن ابراهیم بن سیمجور سپرده شد. وزارت عتبی و سپهسالاری ابوالحسن سیمجور هیچکدام طولی نکشید چه عتبی را عبدالملک در <span class=\"hlight\" dir=\"rtl\">٣٤٨</span> هَ . ق . بر اثر اسراف اودر خرج و بدگوئیهای مردم، از وزارت برداشت و ابوالحسن سیمجور را هم در <span class=\"hlight\" dir=\"rtl\">٣٤٩</span> هَ . ق . به علت تعدی و اجحاف به اهل خراسان معزول نمود و ابومنصور محمدبن عبدالرزاق طوسی را به سپهسالاری آن کشور برگزید. وزیر و سپهسالار جدید را نیز ساعیان و متنفذین درباری در کارهای خود آسوده نگذاشتند. مخصوصاً البتکین حاجب سالار عبدالملک که قدرتی فوق العاده یافته بود با ابوعلی محمدبن محمد بلعمی پسر بلعمی اول اتفاق کرد تا خود مقام ابومنصور را بگیرد و بلعمی وزارت عبدالملک را. بالاخره هم همین توطئه به نتیجه رسید و ابوعلی بلعمی به وزارت عبدالملک و البتکین در سال <span class=\"hlight\" dir=\"rtl\">٣٤٩</span> هَ . ق . به سپهسالاری خراسان اختیار شدند و جمیع کارهای کشوری و لشکری عبدالملک در دست این دو تن همدست افتاد. امیر رشید عبدالملک در یازدهم شوال سال <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> هَ . ق . در ضمن گوی بازی از اسب بزمین افتاد و هلاک شد. (حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٢</span> صص <span class=\"hlight\" dir=\"rtl\">٣٦٣</span> - <span class=\"hlight\" dir=\"rtl\">٣٦٩</span>) (تاریخ دیالمه و غزنویان صص <span class=\"hlight\" dir=\"rtl\">١٥٢</span>-<span class=\"hlight\" dir=\"rtl\">١٨٥</span>).<br /></font></div>'),
(180829, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ابن هشام بن ایوب الحمیری المعافری . رجوع به ابن هشام عبدالملک و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180830, 'عبدالملک', '<span class=\"hlight\">عبدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) ولی العبلات از مولدین بربر و از مغنیان مشهور صدر اسلام و از حاذق ترین آنان در صنعت غناست . وی به مکه سکونت گزید. از جهت جمالی که داشت الغریض میگفتند. وی به سال <span class=\"hlight\" dir=\"rtl\">٥٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180831, 'عبدالملکی', '<span class=\"hlight\">عبدالملکی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (ص نسبی ) نسبت است به عبدالملک العبد الملکی پسر دختر عماربن رجاء استرابادی متوفی به سال <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> هَ . ق . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٣</span>).<br /></font></div>'),
(180832, 'عبدالملکی', '<span class=\"hlight\">عبدالملکی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) دهی است از دهستان میان دربند بخش مرکزی کرمانشاهان، واقع در <span class=\"hlight\" dir=\"rtl\">٦٨</span>هزارگزی شمال باختری کرمانشاه و سه هزارگزی باختری راه شوسه ٔ سنندج در دامنه ای و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٢٥</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180833, 'عبدالملکی', '<span class=\"hlight\">عبدالملکی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ل ِ ]</font></b> (اِخ ) دهی است از دهستان خزل شهرستان نهاوند واقع در <span class=\"hlight\" dir=\"rtl\">٢٩</span> هزارگزی شمال باختری شهر نهاوند. کنار رودخانه ٔ تویسرکان واقع در جلگه و سردسیر و مالاریایی است و <span class=\"hlight\" dir=\"rtl\">٤٧٩</span> تن سکنه دارد. آب آن از رودخانه تأمین میشود محصول آن : غلات دیمی، حبوبات، توتون است . اهالی به کشاورزی اشتغال دارند. راه مالرو دارد در فصل خشکی ارابه رو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180834, 'عبدالمناف', '<span class=\"hlight\">عبدالمناف .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م َ ]</font></b> (اِخ ) دهی است از دهستان نمارستاق بخش نور شهرستان آمل واقع در <span class=\"hlight\" dir=\"rtl\">٤٧</span>هزارگزی جنوب باختری آمل و <span class=\"hlight\" dir=\"rtl\">١١</span>هزارگزی باختر شوسه ٔ آمل به لاریجان . کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٧٠</span> تن سکنه دارد. زبان آنها مازندرانی فارسی است . آب آن از چشمه تأمین میشود. محصولاتش غلات و لبنیات است . شغل اهالی زراعت و گله داری است . راه مالرو دارد.زیارتگاهی بنام عبدالمناف که بنای آن قدیمی است در این ده واقع است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(180835, 'عبدالمنعم', '<span class=\"hlight\">عبدالمنعم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م ُ ع ِ ]</font></b> (اِخ ) ابن عبدالعزیزبن ابی بکربن عبدالمؤمن القرشی العبدری معروف به ابن النطرونی . رجوع به ابن النطرونی و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180836, 'عبدالمنعم', '<span class=\"hlight\">عبدالمنعم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م ُ ع ِ ]</font></b> (اِخ ) ابن عبیداﷲبن غلبون . وی عالم به قرآات بود و در آن کتابی به نام الارشاد نوشته است .وی به سال <span class=\"hlight\" dir=\"rtl\">٣٨٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180837, 'عبدالمنعم', '<span class=\"hlight\">عبدالمنعم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ م ُ ع ِ ]</font></b> (اِخ )ابن عمربن عبداﷲ الجیانی الغسانی الاندلسی، مکنی به ابوالفضل . وی طبیب، شاعر، ادیب و متصوف بود. به سال <span class=\"hlight\" dir=\"rtl\">٥٣١</span> هَ . ق . به وادی آش اندلس متولد شد. سپس به بغداد رفت و در دمشق اقامت گزید و به سال <span class=\"hlight\" dir=\"rtl\">٦٠٢</span> هَ . ق . بدانجا درگذشت . وی مورد اکرام و احترام سلطان صلاح الدین بود و عبدالمنعم او را در قصائد خویش فراوان ستوده است . مشهورترین قصائد وی مدیحات است . او راست : روضة المآثر و المفاخر فی خصائص الملک الناصر. منادح الممادح و دیوان که حاوی انواع شعر است . (از الاعلام زرکلی ). و رجوع به جیان شود.<br /></font></div>'),
(180838, 'عبدالنافع', '<span class=\"hlight\">عبدالنافع.</span> <font color=\"DarkGreen\"><b>[ ع َ دُن ْ نا ف ِ ]</font></b> (اِخ ) ابن عمرالحموی . وی فاضل و از مردم حماة است . در طرابلس شام سکونت گزید و به سال <span class=\"hlight\" dir=\"rtl\">١٠١٦</span> هَ . ق . به ادلب درگذشت . او راست : الرسالة الهادیة الی اعتقاد الفرقة الناحیة. منظومة فی العقایده . تفسیر سورة الاخلاص و او راست نظمی . وی شاعر هجاگوی بود. (از الاعلام زرکلی ).<br /></font></div>'),
(180839, 'عبدالنبی', '<span class=\"hlight\">عبدالنبی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُن ْ ن َ بی ی ]</font></b> (اِخ ) ابن علی بن مهدی الحمیری . صاحب زبید. وی پس از مرگ برادرش مهدی به سال <span class=\"hlight\" dir=\"rtl\">٥٥٩</span> هَ . ق . به امارت رسید و با ملوک یمن جنگ کرده و تمام اموال و ذخایر یمن بدو منتقل گردید وی سپاهیانی را که در جنگ میگریختند میکشت . عبدالنبی عالم به ادب بود و او را شعری است . اسبان و سلاحهای جنگی را در اصطبل ها و مخزنهای خود نگهداری میکرد و هیچ یک از افراد نمیتوانستند اسبی و سلاحی نزد خود داشته باشند و در مواقع ضرورت به اندازه ٔ حاجت بدانها اسب و سلاح میداد. همواره جنگهائی میان او و بلوک یمن ادامه داشت و سرانجام سلطان علی بن حاتم بر وی ظفر یافت و به سال <span class=\"hlight\" dir=\"rtl\">٥٧٠</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180840, 'عبدالهادی', '<span class=\"hlight\">عبدالهادی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b> (اِخ ) ابن رضوان نجا الابیاری المصری . وی کاتب و ادیب بوده و او را نظمی است . در الازهر علم آموخت و خدیو اسماعیل پاشا او را به تعلم فرزندان خود گماشت . سپس توفیق اسماعیل او را امام خاصه ٔ خود و مفتی ساخت . در حدود چهل تألیف دارد از آن جمله است : سعود المطالع فی الادب . النجم الثاقب . المسائل الادبیه . نفخ الاکمام . الباب المفتوح لمعرفة احوال الروح . زکاة الصیام بارشاد العوام و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٣٦</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٣٠٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180841, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b>(اِخ ) ابن احمدبن ابوالقاسم بن محمد الملیحی الهروی .اهل ادب و حدیث بود. از کتب او است : الرد علی ابی عبید فی غریب القرآن . الروضة که حاوی یکهزار حدیث صحیح و هزار حدیث غریب و هزار حکایت و هزار بیت شعر است .وی به سال <span class=\"hlight\" dir=\"rtl\">٤٦٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180842, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b> (اِخ ) ابن ابراهیم بن الحسن معروف به ابن فقیه . فاضل و از مردم موصل بود او را شعری است . وی به سال <span class=\"hlight\" dir=\"rtl\">٥٦١</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">٦٣٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180843, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b> (اِخ ) ابن ابی بکر الانصاری الشافعی . معروف به قاضی القنفذة. از مردم حجاز و قاضی و رئیس قنفذه و نواحی آن بود. یکی از اشراف او رادستگیر کرد و سپس رها ساخت . وی به شرق حجاز رفت و در محله ٔ موطف به سال <span class=\"hlight\" dir=\"rtl\">١٠٨٩</span> هَ . ق . درگذشت . از تصنیفات او است : شرح الرحبیه فی الفرائض . منظومة فی اصول الدین و او را نظم و رسائلی است . (از الاعلام زرکلی ).<br /></font></div>'),
(180844, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b> (اِخ ) ابن ابی هاشم البغدادی، مکنی به ابوعمر و معروف به غلام ثعلب . وی لغوی، زاهد و از حفاظ حدیث بود سی هزار ورقه حدیث از حفظ املا کرد و او راست : فضائل معاویه و غریب الحدیث . وی به سال <span class=\"hlight\" dir=\"rtl\">٢٦١</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">٣٤٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180845, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b> (اِخ ) ابن محمدبن احمد معروف به عبدالواحد الفاسی . از مردم فاس است به سال <span class=\"hlight\" dir=\"rtl\">١١٧٢</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٢١٣</span> هَ . ق . درگذشت . از کتب اوست : ارتقاء الرتب العلیه فی ذکر الانساب الصقلیه و نظم و رسائلی . (از الاعلام زرکلی ).<br /></font></div>'),
(180846, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b> (اِخ ) ابن احمدبن علی بن عاشر الانصاری . فقیه بود و او را نظمی است . اصل او از اندلس است و در فاس متولد شد و هم بدانجا نشأت یافت . او را تصنیفاتی است، از جمله : منظومة فی الفقه المالکی . شرح مورد الظمآن فی علم رسم القرآن . ارجوزة فی عمل الربع المجیب . المرشد المعین علی الضروری من علوم الدین و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٤٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180847, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b> (اِخ ) ابن ادریس المأمون بن یعقوب المنصور. سلطان مغرب و از بنی عبدالمؤمن الکومی است . بعد از مرگ پدرش به سال <span class=\"hlight\" dir=\"rtl\">٦٣٠</span> هَ .ق . ولایت وادی العبید یافت و به مراکش رفت و بیعت گرفت در زمان حکومت او فرنگیان بر قرطبه استیلا یافتند.وی به سال <span class=\"hlight\" dir=\"rtl\">٦٤٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180848, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b> (اِخ ) ابن اسماعیل بن احمد، مکنی به ابوالمحاسن و معروف به عبدالواحد الرویانی . فقیهی شافعی و از مردم رویان است به بخاری و غزنه و نیشابور رفت و به آمل طبرستان مدرسه ای بنا کرد و سپس به ری و اصفهان شد دیگر بار به آمل بازگشت، جماعتی از مردم آنجا از روی تعصب او را به قتل رساندند. از تصنیفات او است : بحر المذهب که از بزرگترین کتب شافعی است . مناصیص الامام الشافعی .الکافی . حلیة المؤمن و جز آن . (از الاعلام زرکلی ).<br /></font></div>'),
(180849, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b> (اِخ ) ابن محمدبن علی الاموی المالقی . عالم به قراآت و از مردم مالقه بود. از کتب اوست : شرح التیسیر فی القراآت .وی به سال <span class=\"hlight\" dir=\"rtl\">٧٠٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180850, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b> (اِخ ) ابن عبداﷲبن کعب النصر الدمشقی، مکنی به ابوبشر النصری . تابعی و از رجال حدیث و ثقه بود. به سال <span class=\"hlight\" dir=\"rtl\">١٠٤</span> هَ . ق . ولایت مدینه و مکه و طائف یافت و مدت یکسال و هشت ماه ولایت داشت و به سال <span class=\"hlight\" dir=\"rtl\">١٠٦</span> هَ . ق . به امر هشام بن عبدالملک از ولایت معزول شد.وی به سال <span class=\"hlight\" dir=\"rtl\">١١٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180851, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b> (اِخ ) ابن علی التمیمی المراکشی معروف به مراکشی . مورخ است . به سال <span class=\"hlight\" dir=\"rtl\">٥٨١</span> هَ . ق . به مراکش متولد شد و در فاس و اندلس علم آموخت و به سال <span class=\"hlight\" dir=\"rtl\">٦١٣</span> هَ . ق . به مصر رفت و مجاور مکه ٔ معظمه گشت او راست : المعجب فی تلخیص اخبار المغرب .وی به سال <span class=\"hlight\" dir=\"rtl\">٦٢٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180852, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b> (اِخ ) ابن علی الحلبی لغوی، مکنی به ابوالطیب معروف به عبدالواحد الحلبی . رجوع به ابوالطیب عبدالواحد و الاعلام زرکلی شود.<br /></font></div>'),
(180853, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span><font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b> (اِخ ) ابن نصربن محمد المخزومی معروف به ببغاء. رجوع به ببغاء و نیز الاعلام زرکلی شود.<br /></font></div>'),
(180854, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b> (اِخ ) ابن یحیی بن عمر، مکنی به ابومحمد. پدر وی از رجال بنی عبدالمؤمن کومی است و عبدالواحد بین آنان نشأت یافت و به الناصرالدین اﷲ (محمدبن یعقوب ) پیوست و او به سال <span class=\"hlight\" dir=\"rtl\">٦٠٣</span> هَ . ق . وی را ولایت داد. وی افریقیه را ضبط کرد و شورش آنجا را خوابانید و تا به سال <span class=\"hlight\" dir=\"rtl\">٦١٨</span> هَ . ق . که در تونس درگذشت بدان شغل باقی بود. (از الاعلام زرکلی ).<br /></font></div>'),
(180855, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b> (اِخ ) ابن یزیدالهواری المدغمی . از امراء الصفریه و مردی شجاع بود. وی با جمعی از مردم بربر در قیروان خروج کرد و به سال <span class=\"hlight\" dir=\"rtl\">١٢٤</span> هَ . ق . در وقعه ٔ اصنام به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180856, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b> (اِخ ) ابن یوسف بن محمدبن یعقوب . ازملوک دولت مؤمنیه کومیه است . بر مغرب اقصی جز قسمتی از وی حکومت داشت . به سال <span class=\"hlight\" dir=\"rtl\">٦٢٠</span> هَ . ق . به مراکش باوی بیعت کردند و پس از دو ماه خلع شد و به همان سال یعنی <span class=\"hlight\" dir=\"rtl\">٦٢٠</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(180857, 'عبدالواحد', '<span class=\"hlight\">عبدالواحد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ح ِ ]</font></b> (اِخ ) الرشیدی . فاضلی مصری است و به ادب و تاریخ معرفتی داشت . او راست : نزهة السامرة فی اخبار مصر و القاهرة. وی به سال <span class=\"hlight\" dir=\"rtl\">١٠٢٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180858, 'عبدالوارث', '<span class=\"hlight\">عبدالوارث .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ رِ ]</font></b> (اِخ ) ابن سعید، مکنی به ابوعبیدالعنبری التنوری البصری . از فصحاء و ائمه ٔ حدیث بود. به سال <span class=\"hlight\" dir=\"rtl\">١٠٢</span> هَ . ق . متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">١٨٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180859, 'عبدالوهاب', '<span class=\"hlight\">عبدالوهاب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ وَهَْ ها ]</font></b> (اِخ ) ابن احمدبن علی الحنفی الشعرانی، مکنی به ابومحمد. از علماء متصوف است . به سال <span class=\"hlight\" dir=\"rtl\">٨٩٩</span> هَ . ق . در قلقشنده ٔ مصر متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٩٧٣</span> هَ . ق . به قاهره درگذشت و حنفی نسب اوست به محمدبن حنفیه و شعرانی نسب اوست به قریه ای که در آن متولد شده است . از کتب او است : الدار المنثورة فی زبد العلوم المشهورة. لواقح الانوار فی طبقات الاخیار. مختصر تذکرة القرطبی . الیواقیت و الجواهر فی بیان عقاید الاکابر. المیزان . المیزان الکبری . مشارق الانوار. ادب القضاة. لطائف المنن . البدر المنیر در حدیث . مختصر الفتوحات . البحر المورود فی المواثیق و العهود. کشف الغمه عن جمیع الامة. المنهج المبین فی ادلة المجتهدین . تنبیه المغترین فی آداب الدین منح المنة و جز آن . (از الاعلام زرکلی ).<br /></font></div>'),
(180860, 'عبدالوهاب', '<span class=\"hlight\">عبدالوهاب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ وَهَْ ها ]</font></b> (اِخ ) ابن محمد الازدی معروف به المثقال . شاعری هجاگوی و لاابالی بود و در اشعار او رقتی است و او را اخباری است . و در حدود سال <span class=\"hlight\" dir=\"rtl\">٥٠٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180861, 'عبدالوهاب', '<span class=\"hlight\">عبدالوهاب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ وَهَْ ها ]</font></b> (اِخ ) ابن محمدبن عبداﷲبن فیروز التمیمی الاحسائی . فقیهی حنبلی و از علماء احساء (بحرین ) است . به سال <span class=\"hlight\" dir=\"rtl\">١١٧٢</span> هَ. ق . متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">١٢٠٥</span> هَ . ق . در جوانی در بلدة الزیارة در ساحل بحر عمان درگذشت . از کتب اوست : حواشی علی شرح المنتهی در فقه . حاشیة علی شرح المقنعکه آن را تمام نکرد. شرح الجوهر المکنون اخضری در معانی و بیان . و او را نظمی است . (از الاعلام زرکلی ).<br /></font></div>'),
(180862, 'عبدالوهاب', '<span class=\"hlight\">عبدالوهاب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ وَهَْ ها ]</font></b> (اِخ ) ابن محمدبن اسحاق بن مندة العبدی، مکنی به ابوعمرو معروف به ابن منده . از حفاظ حدیث بود. به سال <span class=\"hlight\" dir=\"rtl\">٤٧٤</span> هَ . ق . به اصفهان درگذشت . از کتب او است : الفوائد فی الحدیث . (از الاعلام زرکلی ).<br /></font></div>'),
(180863, 'عبدالوهاب', '<span class=\"hlight\">عبدالوهاب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ وَهَْ ها ]</font></b> (اِخ ) ابن فضل اﷲ العمری القرشی ملقب به شرف الدین . نویسنده ای مترسل و از مردم مصر است . خدمت ملک اشرف و ملک ناصر و سیف الدین تنکز کرد. ملک ناصر او را به شام فرستاد و به سال <span class=\"hlight\" dir=\"rtl\">٧١٧</span> هَ . ق . بدانجا درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180864, 'عبدالوهاب', '<span class=\"hlight\">عبدالوهاب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ وَهَْ ها ]</font></b> (اِخ ) ابن علی بن نصر، مکنی به ابومحمد. قاضی و فقیه بود و او را نظمی است . وی به ادب معرفتی داشت . به سال <span class=\"hlight\" dir=\"rtl\">٣٦٢</span> هَ . ق . به بغداد متولد شد. ولایت قضاء بدو رسید. سپس بشام رفت و در بصره با ابوالعلاء ملاقات کرد.آنگاه به مصر رفت و شهرت او فراوان گشت و به سال <span class=\"hlight\" dir=\"rtl\">٤٢٣</span> هَ . ق . به مصر درگذشت . از کتب اوست : بالتلقین در فقه مالکیان . عیون المسائل . النصرة لمذهب مالک . شرح المدونة. الادلة فی مسائل الخلاف . (از الاعلام زرکلی ).<br /></font></div>'),
(180865, 'عبدالوهاب', '<span class=\"hlight\">عبدالوهاب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ وَهَْ ها ]</font></b> (اِخ ) ابن علی بن عبدالکافی، مکنی به ابونصر و معروف به تاج الدین السبکی . رجوع شود به تاج الدین سبکی علی بن ... وسبکی و نیز ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٨</span> و الاعلام زرکلی .<br /></font></div>'),
(180866, 'عبدالوهاب', '<span class=\"hlight\">عبدالوهاب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ وَهَْ ها ]</font></b> (اِخ )ابن سلیمان بن علی بن مشرف التمیمی النجدی . وی فقیهی حنبلی و از مردم عیینة نجد و والد محمدبن الوهاب امام حنابله ٔ نجد است . به سال <span class=\"hlight\" dir=\"rtl\">١١٥٣</span> هَ . ق . درگذشت . در بعض مسائل فقهی نوشته هایی دارد. (از الاعلام زرکلی ).<br /></font></div>'),
(180867, 'عبدالوهاب', '<span class=\"hlight\">عبدالوهاب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ وَهَْ ها ]</font></b> (اِخ ) ابن داودبن طاهر. سلطان یمن بوده . به سال <span class=\"hlight\" dir=\"rtl\">٨٨٣</span> هَ . ق . به امارت رسید. وی مردی بردبار و صاحب رأی بود او را در یمن آثاری است . وی به سال <span class=\"hlight\" dir=\"rtl\">٨٦٦</span> هَ . ق . متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٨٩٤</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180868, 'عبدالوهاب', '<span class=\"hlight\">عبدالوهاب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ وَهَْ ها ]</font></b> (اِخ ) ابن احمدبن وهبان الدمشقی . فقیهی حنفی و در ادب ماهر بود. ولایت قضاء حماة یافت . از کتب اوست : قیدالشرائد که منظومه ای است در هزار بیت متضمن مسائل غریب در فقه و شرح آن منظومه در دو مجلد.وی به سال <span class=\"hlight\" dir=\"rtl\">٧٦٨</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180869, 'عبدالوهاب', '<span class=\"hlight\">عبدالوهاب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ وَهَْ ها ]</font></b> (اِخ ) ابن احمدبن سحنون معروف به ابی سحنون . طبیبی است و او را ادب و شعری است . وی خطیب یثرب و طبیب بیمارستان جبل بود. به سال <span class=\"hlight\" dir=\"rtl\">٦١٩</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">٦٩٤</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180870, 'عبدالوهاب', '<span class=\"hlight\">عبدالوهاب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ وَهَْ ها ]</font></b> (اِخ ) ابن ابراهیم الامام . از بنی عباس است . به سال <span class=\"hlight\" dir=\"rtl\">١٤٠</span> هَ . ق . عم وی منصور او را با هفتاد هزار تن به مکه فرستاد و حسن بن قحطبه را همراه او کرد. مردم روم از ایشان ترسیدند وآنان ملیطه را که بدست فرنگیان ویران شده بود آباد کردند. وی به سال <span class=\"hlight\" dir=\"rtl\">١٥١</span> - <span class=\"hlight\" dir=\"rtl\">١٥٢</span> هَ . ق . به غزاء صائفه پرداخت و در <span class=\"hlight\" dir=\"rtl\">١٥٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180871, 'عبدالوهاب', '<span class=\"hlight\">عبدالوهاب .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ وَهَْ ها ]</font></b> (اِخ ) ابن ابراهیم بن عبدالوهاب الخزرجی الزنجانی . از علمای عربیت است . او راست : تصریف العزی در صرف . الهادی در نحو. معیار النظار فی علوم الاشعار. وی به سال <span class=\"hlight\" dir=\"rtl\">٦٥٥</span> هَ . ق . به بغداد درگذشت .<br /></font></div>'),
(180872, 'عبدالکافی', '<span class=\"hlight\">عبدالکافی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ]</font></b> (اِخ ) ده کوچکی است از دهستان حومه ٔ بخش انارک شهرستان نائین . واقع در هشت هزار گزی شمال انارک متصل به راه حاجی مهدی به انارک . ناحیه ای است واقع در جلگه و گرمسیر و <span class=\"hlight\" dir=\"rtl\">١١</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولاتش غلات است . اهالی به کشاورزی اشغال دارند. راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(180873, 'عبدالکریم', '<span class=\"hlight\">عبدالکریم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ک َ ]</font></b> (اِخ ) ابن عبدالنوربن المنبر الحلبی المصری . وی صاحب تاریخ مصر و شرح صحیح بخاری است . به سال <span class=\"hlight\" dir=\"rtl\">٧٣٥</span> هَ . ق . درگذشت . (از رجال حبیب السیر ص <span class=\"hlight\" dir=\"rtl\">٥٤١</span>) (از الاعلام زرکلی ).<br /></font></div>'),
(180874, 'عبدالکریم', '<span class=\"hlight\">عبدالکریم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ک َ ]</font></b> (اِخ ) ابن عبدالصمدبن محمد القطان الطبری شافعی، مکنی به ابومعشر شیخ اهل مکه و عالم به قراآت بود.از تألیفات اوست : التلخیص فی القراآت الثمان . سوق العروس فی القراآت . عیون المسائل فی التفسیر. وی به سال <span class=\"hlight\" dir=\"rtl\">٤٧٨</span> هَ . ق . به مکه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180875, 'عبدالکریم', '<span class=\"hlight\">عبدالکریم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ک َ ]</font></b> (اِخ ) ابن عطایابن عبدالکریم القرشی الزهری الاسکندرانی . وی در قرافه ٔ کبرای مصر سکونت جست . از تألیفات اوست : شرح ابیات الجمل . زیارة قبور الصالحین .وی به سال <span class=\"hlight\" dir=\"rtl\">٦١٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180876, 'عبدالکریم', '<span class=\"hlight\">عبدالکریم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ک َ ]</font></b> (اِخ ) ابن فضل المطیع ﷲبن المقتدرالعباسی معروف به الطائعﷲ. رجوع به الطائع ﷲ شود.<br /></font></div>'),
(180877, 'عبدالکریم', '<span class=\"hlight\">عبدالکریم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ک َ ]</font></b> (اِخ ) ابن مالک الخزرجی، مکنی به ابوسعید. رجوع به ابوسعید عبدالکریم بن مالک شود.<br /></font></div>'),
(180878, 'عبدالکریم', '<span class=\"hlight\">عبدالکریم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ک َ ]</font></b> (اِخ ) ابن محمدبن عبدالکریم الرافعی القزوینی الشافعی . وی عالم دینی بود و در قزوین درس تفسیر و حدیث میگفت . از تألیفات اوست : المحرر. فتح العزیز فی شرح الوجیز للغزالی . شرح مسند الشافعی . الامالی الشارحة لمفردات الفاتحه . به سال <span class=\"hlight\" dir=\"rtl\">٦٢٣</span> هَ . ق . بقزوین درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180879, 'عبدالکریم', '<span class=\"hlight\">عبدالکریم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ک َ ]</font></b> (اِخ ) ابن محمدبن منصور التمیمی سمعانی مروزی، مکنی به ابوسعد. رجوع به ابوسعد عبدالکریم و نیز به الاعلام زرکلی شود.<br /></font></div>'),
(180880, 'عبدالکریم', '<span class=\"hlight\">عبدالکریم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ک َ ]</font></b> (اِخ ) ابن محمد الهارونی دیباجی، مکنی به ابونصر. رجوع به ابونصر عبدالکریم شود.<br /></font></div>'),
(180881, 'عبدالکریم', '<span class=\"hlight\">عبدالکریم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ک َ ]</font></b> (اِخ ) ابن هوازن بن عبدالملک بن طلحة النیشابوری قشیری اشعری شافعی صوفی، مکنی به ابوالقاسم وملقب به زین الاسلام از بنی قشیر و شیخ خراسان بود. وی مردی زاهد و عالم به دین بود. او از اعرابی است که به خراسان رفتند و نسبت او به قشربن کعب میرسد. در کودکی پدرش را از دست داد. از محضر استادانی معروف همچون علی بن حسین نیشابوری معروف به دقاق و محمدبن ابی بکر طوسی و ابی بکر فورک فقه و اصول آموخت . وی از بزرگان و شیوخ اهل تصوف و عرفان است و مورد توجه سلطان آلب ارسلان بود. از تألیفات اوست : تفسیر کبیر به نام التیسیر فی علم التفسیر. رسالة فی رجال الطریقة. مختصر المحصل فی الکلام . المنتخب فی علوم الحدیث . لطائف الاشارات . رسالة القشیریه . مختصر الهدایة و جز آن . وی به سال <span class=\"hlight\" dir=\"rtl\">٣٧٦</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">٤٦٥</span> به نیشابور درگذشت . (از الاعلام زرکلی و روضات الجنات صص <span class=\"hlight\" dir=\"rtl\">٤٤٤</span> - <span class=\"hlight\" dir=\"rtl\">٤٤٦</span>).<br /></font></div>'),
(180882, 'عبدالکریم', '<span class=\"hlight\">عبدالکریم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ک َ ]</font></b> (اِخ ) ابن عبدالحاکم بن سعید الفارقی . از وزراء دولت فاطمیه ٔ مصر بود.وی به سال <span class=\"hlight\" dir=\"rtl\">٤٥٤</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180883, 'عبدالکریم', '<span class=\"hlight\">عبدالکریم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ک َ ]</font></b> (اِخ ) ابن احمدبن موسی بن طاوس العلوی الحسنی معروف به ابن طاوس .رجوع به ابن طاوس غیاث الدین ابوالمظفر در این لغت نامه و الاعلام زرکلی و نامه ٔ دانشوران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١١</span> شود.<br /></font></div>'),
(180884, 'عبدالکریم', '<span class=\"hlight\">عبدالکریم .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ک َ ]</font></b> (اِخ ) ابن احمدبن عبدالرحمان بن عیسی النائب الاوسی الانصاری . فقیه و ادیب بود. او را شعری نکو است . وی از مردم طرابلس عرب است و به سال <span class=\"hlight\" dir=\"rtl\">١١٨٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180885, 'عبدالکریم جیلی', '<span class=\"hlight\">عبدالکریم جیلی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ک َ م ِ ]</font></b> (اِخ ) ابن ابراهیم، سبط عبدالقادر الجیلانی از علماء متصوف است . از تألیفات اوست : الانسان الکامل فی معرفة الاواخر و الاوائل . الناموس الاعظم . وی به سال <span class=\"hlight\" dir=\"rtl\">٨٢٦</span> هَ . هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180886, 'عبدالکریمی', '<span class=\"hlight\">عبدالکریمی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ ک َ ]</font></b> (اِخ ) دهی است از دهستان کربال بخش زرقان شهرستان شیراز. واقع در <span class=\"hlight\" dir=\"rtl\">١٩</span>هزارگزی خاور زرقان و کنار راه فرعی بند امیر به سلطان آباد. ناحیه ای است واقع در جلگه، هوای آن معتدل و <span class=\"hlight\" dir=\"rtl\">٥٣</span> تن سکنه دارد. آب این ده از رود کُر تأمین میشود. محصولاتش غلات و چغندر است . اهالی به کشاورزی اشتغال دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(180887, 'عبدان', '<span class=\"hlight\">عبدان .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (اِخ ) ناحیه ای است به یمن . (از معجم البلدان ).<br /></font></div>'),
(180888, 'عبدان', '<span class=\"hlight\">عبدان .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) موضعی است به یمن . (از معجم البلدان ).<br /></font></div>'),
(180889, 'عبدان', '<span class=\"hlight\">عبدان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) یکی از دهات مرو است که بوالقاسم عبدالحمیدبن عبدالرحمان بن احمد العبدانی منسوب است بدان . (از معجم البلدان ).<br /></font></div>'),
(180890, 'عبدان', '<span class=\"hlight\">عبدان .</span> <font color=\"DarkGreen\"><b>[ ع َ ب ُ ]</font></b>(اِخ ) نهر عبدان، نهری است به بصره در جانب فرات منسوب به مردی است از اهل بحرین . (از معجم البلدان ).<br /></font></div>'),
(180891, 'عبدان', '<span class=\"hlight\">عبدان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ اَعْبُد. (لسان العرب ).<br /></font></div>'),
(180892, 'عبدان', '<span class=\"hlight\">عبدان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ب ِدْ دا ]</font></b> (ع اِ) ج ِ اَعبد. (السان العرب ).<br /></font></div>'),
(180893, 'عبدانی', '<span class=\"hlight\">عبدانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) عبدالحمیدبن عبد الرحمان بن احمد العبدانی، مکنی به ابوالقاسم . خواهرزاده ٔ یکی از فضلاء و ائمه است که از خال خود قاضی ابوالحسن علی بن الحسن دهقان، مکنی به ابن عبدالرزاق الکشمیهنی و جز آنان روایت کند. (از معجم البلدان ).<br /></font></div>'),
(180894, 'عبدری', '<span class=\"hlight\">عبدری .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ری ی ]</font></b> (اِخ ) محمدبن محمد. رجوع به ابن الحجاح شود.<br /></font></div>'),
(180895, 'عبدری', '<span class=\"hlight\">عبدری .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ری ی ]</font></b> (اِخ ) علی بن سعیدبن عبدالرحمان بن محرزبن ابی عثمان ملقب به عبدری . از بزرگان علمای شافعیه است . از تألیفات او است : مختصر الکفایه در خلافیات علماء. وی به سال <span class=\"hlight\" dir=\"rtl\">٤٩٣</span> هَ . ق . درگذشت . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>).<br /></font></div>'),
(180896, 'عبدری', '<span class=\"hlight\">عبدری .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ری ی ]</font></b> (اِخ ) رزین بن معاویةبن عمار سرقسطی عبدری، مکنی به ابوالحسن و معروف به امام الحرمین . از بزرگان علماء اهل سنت است . از تألیفات او است : جمع بین الصحاح الستة. وی از محدثین است . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>).<br /></font></div>'),
(180897, 'عبدری', '<span class=\"hlight\">عبدری .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ری ی ]</font></b> (ص نسبی ) نسبت است به عبدالداربن قصی . (از اللباب فی تهذیب الانساب ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br /></font></div>'),
(180898, 'عبدری', '<span class=\"hlight\">عبدری .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ری ی ]</font></b> (اِخ ) در اصطلاح رجال لقب سویبطبن حرمله ٔ فرشی عبدری و جمعی دیگر است و نسبت آن به قبیله ٔ بنی عبدالدار (از بلاد اندلس ) است . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>).<br /></font></div>'),
(180899, 'عبدری', '<span class=\"hlight\">عبدری .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ری ی ]</font></b> (اِخ ) عبدالحمیدبن زکریای بن الجهم العبدری . (اللباب ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br /></font></div>'),
(180900, 'عبدسی', '<span class=\"hlight\">عبدسی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (اِخ ) حمزه گوید این کلمه معرب افداسهی است و آن نام مصنعه ای است که در بازار کسکر بوده است . عرب آن بازار را ویران کرد و این نام بر عمارتهای اطراف مانده است . (معجم البلدان ).<br /></font></div>'),
(180901, 'عبدشی', '<span class=\"hlight\">عبدشی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ص نسبی ) نسبت است به عبد شریه که نام مردی است و آن محمدبن عبدالملک بن سلمة العبدشی نیشابوری است که معروف به ابن عبد شریه است . (اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢١</span>).<br /></font></div>'),
(180902, 'عبدقیس', '<span class=\"hlight\">عبدقیس .</span> <font color=\"DarkGreen\"><b>[ ع َ دِ ق َ ]</font></b> (اِخ ) بطنی است از جدیله و آنان بنوعبدالقیس بن اقصی بن دعمی بن جدیله اند. سرزمین مسکونی آنان تهامه بود سپس به بحرین رفتند و با قبیله ٔ بکربن وائل تصادم کردند و آن سرزمین را تقسیم نمودند. (از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٧</span>).<br /></font></div>'),
(180903, 'عبدل', '<span class=\"hlight\">عبدل .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ع اِ) عبد مملوک . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(180904, 'عبدل', '<span class=\"hlight\">عبدل .</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (اِخ ) نام شهرحضرموت است . (معجم البلدان ). رجوع به حضرموت شود.<br /></font></div>'),
(180905, 'عبدل آباد', '<span class=\"hlight\">عبدل آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (اِخ ) دهی است از دهستان نهارجانات بخش حومه ٔ شهرستان بیرجند. واقع در <span class=\"hlight\" dir=\"rtl\">٣٣</span>هزارگزی جنوب خاوری بیرجند. ناحیه ای است در دامنه . هوای آن معتدل است <span class=\"hlight\" dir=\"rtl\">٥</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولاتش غلات است . اهالی به کشاورزی اشتغال دارندراه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180906, 'عبدل آباد', '<span class=\"hlight\">عبدل آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (اِخ ) دهی است ازدهستان میان ولایت بخش حومه ٔ شهرستان بیرجند. واقع در<span class=\"hlight\" dir=\"rtl\">٤١</span>هزارگزی باختر مشهد و یکهزارگزی شمال راه شوسه ٔ مشهد به قوچان . جلگه ای و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٢٤١</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولاتش غلات است . اهالی به کشاورزی و مالداری اشتغال دارند. راه اتومبیل رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180907, 'عبدل آباد', '<span class=\"hlight\">عبدل آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (اِخ ) دهی است از دهستان پائین رخ بخش کدکن شهرستان تربت حیدریه . واقع در <span class=\"hlight\" dir=\"rtl\">٣٧</span>هزارگزی شمال کدکن کنار کال چغوکی . ناحیه ای است در دشت . هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٢٢٣</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولاتش غلات و پنبه است . اهالی به کشاورزی و گله داری و کرباس بافی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180908, 'عبدل آباد', '<span class=\"hlight\">عبدل آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (اِخ ) دهی است از دهستان فیض آباد بخش فیض آباد محولات شهرستان تربت حیدریه . واقع در شش هزارگزی شمال خاوری فیض آباد. ناحیه ای است واقع در دشت و <span class=\"hlight\" dir=\"rtl\">٢٨٣٦</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولاتش غلات، خشکبار، پنبه است . اهالی به کشاورزی و گله داری اشتغال دارند. صنایع دستی، چادرشب ابریشمی بافی است راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180909, 'عبدل آباد', '<span class=\"hlight\">عبدل آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (اِخ ) دهی است از دهستان آزادوار بخش جغتای شهرستان سبزوار. واقع در <span class=\"hlight\" dir=\"rtl\">٤٧</span>هزارگزی شمال باختری جغتای، سر راه اتومبیل رو نقاب . ناحیه ای است واقع درجلگه . هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">١١٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولاتش غلات است . اهالی به کشاورزی اشتغال دارند. راه آن اتومبیل رو میباشد و یک باب دبستان دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180910, 'عبدل آباد', '<span class=\"hlight\">عبدل آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (اِخ ) دهی است از دهستان حلوان بخش طبس شهرستان فردوس . واقع در <span class=\"hlight\" dir=\"rtl\">٨٤</span>هزارگزی شمال طبس ناحیه ای است کوهستانی . گرمسیر <span class=\"hlight\" dir=\"rtl\">١٨</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولاتش غلات است . اهالی به کشاورزی اشتغال دارند. راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180911, 'عبدل آباد', '<span class=\"hlight\">عبدل آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (اِخ ) دهی است از دهستان خسروشیرین بخش جغتای شهرستان سبزوار، واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی شمال جغتای . ناحیه ای است واقع در جلگه . هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">١١٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولاتش غلات، پنبه و زیره است و اهالی به کشاورزی اشتغال دارند. راه اتومبیل رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180912, 'عبدل آباد', '<span class=\"hlight\">عبدل آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (اِخ ) دهی است از دهستان مهران بخش کبودرآهنگ شهرستان همدان . واقع در <span class=\"hlight\" dir=\"rtl\">٣٣</span>هزارگزی شمال باختر قصبه ٔ کبودرآهنگ، کنار راه قافله روقدیم زنجان - همدان . ناحیه ای است واقع در دشت و سردسیر است . آب آن از قنات تأمین میشود و <span class=\"hlight\" dir=\"rtl\">١٤٠</span> تن سکنه دارد. محصولاتش غلات دیم و لبنیات است و اهالی به کشاورزی و گله داری اشتغال دارند. صنایع دستی زنان قالی بافی است . در خشکسالی از طریق کبودرآهنگ و داس قلعه اتومبیل میتوان برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(180913, 'عبدل آباد', '<span class=\"hlight\">عبدل آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (اِخ ) دهی است از دهستان لک بخش قروه ٔ شهرستان سنندج . واقع در <span class=\"hlight\" dir=\"rtl\">٤٠</span>هزارگزی شمال باختر قروه کنار رودخانه بایتمر. تپه ماهور و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه دارد. آب آن از رودخانه تأمین میشود. محصولاتش غلات ولبنیات است . اهالی به کشاورزی و گله داری اشتغال دارند. صنایع دستی زنان قالیچه، جاجیم و گلیم بافی است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(180914, 'عبدل آباد', '<span class=\"hlight\">عبدل آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ خاوری شهرستان رفسنجان، واقع در هفت هزارگزی جنوب رفسنجان . کنار راه شوسه ٔ رفسنجان به کرمان . واقع در جلگه و هوای آن سردسیر است . <span class=\"hlight\" dir=\"rtl\">٢٢٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولاتش غلات، پسته و پنبه است . اهالی به کشاورزی اشتغال دارند. راه آن شوسه میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180915, 'عبدل آباد', '<span class=\"hlight\">عبدل آباد.</span> <font color=\"DarkGreen\"><b>[ع َ دُ ]</font></b> (اِخ ) ده کوچکی است از دهستان سبزواران بخش مرکزی شهرستان جیرفت . واقع در <span class=\"hlight\" dir=\"rtl\">٣٧</span>هزارگزی جنوب خاوری سبزواران و هفت هزارگزی راه عنبرآباد - سبزواران و <span class=\"hlight\" dir=\"rtl\">٤٩</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180916, 'عبدل آباد', '<span class=\"hlight\">عبدل آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (اِخ ) ده کوچکی است از دهستان حومه ٔ بخش زرند شهرستان کرمان . واقع در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزار گزی شمال باختری زرند و <span class=\"hlight\" dir=\"rtl\">٢</span>هزار گزی خاور راه مالرو زرند - بافق و <span class=\"hlight\" dir=\"rtl\">٤٦</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180917, 'عبدل آباد', '<span class=\"hlight\">عبدل آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (اِخ ) ده کوچکی است از دهستان جوپار بخش ماهان شهرستان کرمان . واقع در <span class=\"hlight\" dir=\"rtl\">١٤</span> هزارگزی باختر ماهان و <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی راه ماهان جوپار. آب آن از قنات حکیم آباد تأمین میشود و <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180918, 'عبدل آباد', '<span class=\"hlight\">عبدل آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (اِخ ) دهی است از دهستان میربیگ بخش دلفان شهرستان خرم آباد. واقع در <span class=\"hlight\" dir=\"rtl\">٥٦</span>هزارگزی باختر نورآباد و <span class=\"hlight\" dir=\"rtl\">٣٢</span>هزارگزی باختر نورآباد به کرمانشاه . واقع در جلگه و تپه ماهور هوای آن سردسیر و مالاریایی است . <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> تن سکنه دارد.آب آن از رودخانه ٔ کاویار و چشمه تأمین میشود. محصولاتش غلات، لبنیات و پشم است . اهالی به کشاورزی و گله داری اشتغال دارند. از صنایع دستی زنان قالی بافی است . راه مالرو دارد. ساکنین از طایفه ٔ قیطول بوده، زمستان قشلاق میروند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180919, 'عبدل آباد', '<span class=\"hlight\">عبدل آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (اِخ ) دهی است از دهستان کنارشهر بخش بردسکن شهرستان کاشمر. واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی جنوب خاوری بردسکن به نیگنان . این ده در جلگه واقع و هوای آن گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٣١٣</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولاتش غلات و زیره ٔ سبز است . اهالی به کشاورزی اشتغال دارند.راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180920, 'عبدل آباد بادیز', '<span class=\"hlight\">عبدل آباد بادیز.</span> <font color=\"DarkGreen\"><b>[ ع َ دُ دِ ]</font></b> (اِخ ) دهی است از دهستان سبلوئیه بخش زرند شهرستان کرمان واقع در <span class=\"hlight\" dir=\"rtl\">٣٥</span>هزارگزی جنوب باختری زرند و <span class=\"hlight\" dir=\"rtl\">١١</span>هزارگزی خاور راه مالرو زرند به رفسنجان . کوهستانی و سردسیر است، <span class=\"hlight\" dir=\"rtl\">٢٩٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولاتش غلات و حبوبات است . اهالی به کشاورزی اشتغال دارند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180921, 'عبدل آباد بهزادی', '<span class=\"hlight\">عبدل آباد بهزادی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُ دِ ب ِ ]</font></b> (اِخ ) دهی است از دهستان برج اکرم بخش فهرج شهرستان بم . واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی راه فرعی بم به ریگان . واقع در جلگه و گرمسیر است و مالاریایی <span class=\"hlight\" dir=\"rtl\">١١٣١</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولاتش غلات، مرکبات، خرما است . اهالی به کشاورزی اشتغال دارند. راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180922, 'عبدل بیگی', '<span class=\"hlight\">عبدل بیگی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ب َ ]</font></b> (اِخ ) دهی است از دهستان رومشگان بخش طرهان شهرستان خرم آباد. واقعدر <span class=\"hlight\" dir=\"rtl\">٣٢</span>هزارگزی جنوب خاوری کوهدشت و <span class=\"hlight\" dir=\"rtl\">١٩</span>هزارگزی جنوب اتومبیل رو خرم آباد به کوهدشت دامنه ای و گرمسیر است، <span class=\"hlight\" dir=\"rtl\">١٨٠</span> تن سکنه دارد آب آن از چاه مشروب میشود محصولاتش غلات، لبنیات و پشم است . اهالی به کشاورزی و گله داری اشتغال دارند، از صنایع دستی زنان سیاه چادربافی است . راه اتومبیل رو دارد. ساکنین از طایفه ٔ امرائی بوده وچادرنشین هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180923, 'عبدلی', '<span class=\"hlight\">عبدلی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (اِخ ) دهی است از دهستان میان آب (بلوک شعبه ) بخش مرکزی شهرستان اهواز. واقع در <span class=\"hlight\" dir=\"rtl\">٦٢</span>هزارگزی شمال خاوری اهواز و ساحل باختری رودخانه شطیطبین دو رودخانه ٔ شطیط و دز واقع و در جلگه است . هشتاد تن سکنه دارد. آب آن از رودخانه ٔ شطیط تأمین میشود و محصولاتش غلات است . اهالی به کشاورزی و گله داری اشتغال دارند. راه مالرو دارد. و از طریق شوشتر بدانجا اتومبیل میرود. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180924, 'عبدلی', '<span class=\"hlight\">عبدلی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُ لی ی ]</font></b> (اِخ ) علی بن محمدبن عبداﷲبن عمروبن کعب بن سلمة الخولانی العبدلی . از یوسف بن عبدالاعلی و محمدبن عبداﷲبن عبدالحکیم روایت کند وی مردی صالح و ثقه بود به سال <span class=\"hlight\" dir=\"rtl\">٣٢٩</span> هَ . ق . به مصر درگذشت . (اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br /></font></div>'),
(180925, 'عبدلی', '<span class=\"hlight\">عبدلی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُ لی ی ]</font></b> (اِخ ) محمودبن علی بن اسماعیل البخاری الصوفی العبدلی، مکنی به ابوالقاسم . ساکن قریه ٔ عبداﷲ به عراق بود و در بغداد و واسط موعظه میکرد از ابوالخطاب بن البطروحین بن طلحة الثعالبی حدیث شنید و ابوسعد سمعانی از او روایت کند وی به سال <span class=\"hlight\" dir=\"rtl\">٤٨٠</span> هَ . ق . متولد شد. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br /></font></div>'),
(180926, 'عبدلی', '<span class=\"hlight\">عبدلی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُ لی ی ]</font></b> (ص نسبی ) نسبت است به عبداﷲ که بطنی از خولان است . (اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br /></font></div>'),
(180927, 'عبدلی', '<span class=\"hlight\">عبدلی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُ لی ی ]</font></b> (ص نسبی ) نسبت است بدهی در سرزمین واسط عراق که قریه عبداﷲ نام دارد. (اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br /></font></div>'),
(180928, 'عبدلی', '<span class=\"hlight\">عبدلی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُ لی ی ]</font></b> (ص نسبی ) نسبت است به ابوعبداﷲبن کرام صاحب مقالة الکرامیة که جماعتی از اصحابش به کتب او نسبت داده شده اند. (اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br /></font></div>'),
(180929, 'عبدلی', '<span class=\"hlight\">عبدلی .</span> <font color=\"DarkGreen\"><b>[ ع َ دُ لی ی ]</font></b> (اِخ ) واحد عبادله است . نسبت به عبداﷲ منحوت . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص نسبی، اِ) نام خربزه ای است به مصر. (اقرب الموارد).<br /></font></div>'),
(180930, 'عبدلیه', '<span class=\"hlight\">عبدلیه .</span> <font color=\"DarkGreen\"><b>[ ع َ دُ لی ی َ ]</font></b> (اِخ ) دهی است از دهستان جراحی بخش شادکان شهرستان خرمشهر. واقع در <span class=\"hlight\" dir=\"rtl\">٧٠</span>هزارگزی شمال خاوری شادکان و <span class=\"hlight\" dir=\"rtl\">٥٠</span>هزارگزی باختر راه تابستانی خلف آباد به بهبهان در دشت واقع است . هوای آن گرمسیر است، <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه دارد آب آن از چاه تأمین میشود شغل اهالی زراعت و گله داری است . راه آن در تابستان اتومبیل رو است . ساکنان از طایفه ٔ رفیع هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(180931, 'عبدمناف', '<span class=\"hlight\">عبدمناف .</span> <font color=\"DarkGreen\"><b>[ ع َ دُ م َ ]</font></b> (اِخ ) ابن قصی بن کلاب از قریش از عدنان است و بنی عبدمناف از اشراف طایفه ٔ قریش بودند چنانکه شاعر گوید <span class=\"hlight\">:</span> <br />اذا فخرت یوماً قریش بمفخر<br />فعبد مناف اصلها و صمیمها.<br />(از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٧</span>) (از الاعلام زرکلی ).<br /></font></div>'),
(180932, 'عبدوس', '<span class=\"hlight\">عبدوس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زید. طبیب بود و در بغداد شهرت یافت و المعتضدباﷲ العباسی را معالجه کرد. او راست : کتاب التذکرة فی الطب . وی در حدود سال <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(180933, 'عبدوسی', '<span class=\"hlight\">عبدوسی .</span> <font color=\"DarkGreen\"><b>[ ع َ سی ی ]</font></b> (اِخ ) عبداﷲبن العباس بن ابی یحیی بن ابی منصوربن عبداﷲبن عبدوس سرخسی معروف به قاضی عبدوسی و مکنی به ابوالقاسم . وی مردی فقیه، متفنن، فاضل، اهل مناظره و حافظ مذهب بود. نزد ابوسفیان محمدبن محمدبن فضل قاضی فقه آموخت . ابونصر محمدبن محمود و جز آن از وی روایت کند. به سال <span class=\"hlight\" dir=\"rtl\">٤٦١</span> هَ . ق . درگذشت . (اللباب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٣</span>).<br /></font></div>'),
(180934, 'عبدوسی', '<span class=\"hlight\">عبدوسی .</span> <font color=\"DarkGreen\"><b>[ ع َ سی ی ]</font></b> (ص نسبی ) نسبت است به عبدوس . (لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٣</span>).<br /></font></div>'),
(180935, 'عبدویی', '<span class=\"hlight\">عبدویی .</span> <font color=\"DarkGreen\"><b>[ ع َ یی ی ]</font></b> (اِخ ) محمدبن ابراهیم بن عبدویه بن سدوس بن علی بن عبداﷲبن عبیداﷲبن عبداﷲبن مسعود الهذلی العبدویی، مکنی به ابوعبداﷲ عم ابوحازم العبدویی است . از ابوعبداﷲ البوشجی و احمدبن نجده و اباخلیفة القاضی و جز آنان به خراسان و عراق و حجاز و جزیره و شام و مصر درس آموخت و ابواسحاق المزکی و جز وی از او روایت کند. وی به سال <span class=\"hlight\" dir=\"rtl\">٣٢٣</span> هَ . ق . بر اثر جراحتی که برداشت درگذشت . (اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٣</span>).<br /></font></div>'),
(180936, 'عبدویی', '<span class=\"hlight\">عبدویی .</span> <font color=\"DarkGreen\"><b>[ ع َ یی ی ]</font></b> (اِخ ) عمربن احمدبن ابراهیم بن عبدویه العبدویی، مکنی به ابوحازم . وی امام بود. از ابوبکر اسماعیل و جمعی دیگر حدیث آموخت و خطیب ابوبکر از وی روایت کند. به سال <span class=\"hlight\" dir=\"rtl\">٤١٧</span> هَ. ق . به روز عید فطر درگذشت . (اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٣</span>).<br /></font></div>'),
(180937, 'عبدکی', '<span class=\"hlight\">عبدکی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ کی ی ]</font></b> (اِخ ) در رجال لقب محمدبن علی بن عبدک است . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>).<br /></font></div>'),
(180938, 'عبدکی', '<span class=\"hlight\">عبدکی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ کی ی ]</font></b> (ص نسبی ) نسبت است به عبدک پدر علی بن عبدک . (اللباب ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br /></font></div>'),
(180939, 'عبدکی', '<span class=\"hlight\">عبدکی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ کی ی ]</font></b> (اِخ ) احمدبن محمدبن علی بن عبدک الشیعی العبدکی الجرجانی . از مقدمین شیعه است . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br /></font></div>'),
(180940, 'عبدی', '<span class=\"hlight\">عبدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) در اصطلاح رجال لقب ابراهیم بن خالد عطار و ابراهیم بن نعیم و ادهم بن امیة و جز ایشان است . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٠</span>).<br /></font></div>'),
(180941, 'عبدی', '<span class=\"hlight\">عبدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) هرم بن حیان عبدی . از اتقیاء زهاد ثمانیه و از خواص اصحاب علی علیه السلام و مصاحب اویس قرنی بود. (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٨</span>).<br /></font></div>'),
(180942, 'عبدی', '<span class=\"hlight\">عبدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (ص نسبی ) نسبت است به عبد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نسبت است به عبدالقیس، و عبقی نیز گویند.(اقرب الموارد). منسوب به عبدالقیس و بطنی از جدیله است . (صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٧</span>). <BR><font color=\"Blue\">◄</font> نسبت است به عبدالقیس از ربیعةبن نزار. (اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٣</span>).<br /></font></div>'),
(180943, 'عبدی', '<span class=\"hlight\">عبدی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است از دهستان کابریک بخش جاسک شهرستان بندرعباس . واقع در <span class=\"hlight\" dir=\"rtl\">١٠٠</span>هزارگزی خاور جاسک، جنوب راه مالرو جاسک - چاه بهار. <span class=\"hlight\" dir=\"rtl\">٢٥</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(180944, 'عبدی', '<span class=\"hlight\">عبدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) احمدبن بکربن احمدبن بقیه ٔ فسوی نحوی لغوی . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤٠</span>). و رجوع به احمدبن ابی بکر العبدی شود.<br /></font></div>'),
(180945, 'عبدی', '<span class=\"hlight\">عبدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) سفیان بن مصعب، مکنی به ابومحمد. از شعراء کوفه بود. از اشعار اوست :<br />و قالوا رسول اﷲ ما اختار بعده <br />اماماً و لکنا لانفسنا اخترنا<br />اقمنا اماماً ان أقام علی الهدی <br />أطعنا و ان ضل الهدایة قومنا.<br /><font color=\"Red\">(از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٠</span>).</font><br /></font></div>'),
(180946, 'عبدی غوث', '<span class=\"hlight\">عبدی غوث .</span> <font color=\"DarkGreen\"><b>[ ع َ ی َ غ َ ]</font></b> (اِخ ) ابن صلاءةبن ربیعة، از بنی الحارث بن کعب از قحطان . شاعری جاهلی و یمانی است . وی صاحب قصیده ای است که مطلع آن این است :<br />ألا لاتلومانی کفی اللوم مابیا.<br />وی به سال <span class=\"hlight\" dir=\"rtl\">٤٠</span> هَ . ق . در جنگی اسیر شد و چون او را در کیفیت مردن مخیر کردند اوخوردن شراب خالص را گزید. دو رگ خود را زد و بمرد. (از الاعلام زرکلی ).<br /></font></div>'),
(180947, 'عبدی قیسی', '<span class=\"hlight\">عبدی قیسی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ سی ی ]</font></b> (ص نسبی ) نسبت است به بنی عبدالقیس بطنی از جدیله . (از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٧</span>).<br /></font></div>'),
(180948, 'عبدیا', '<span class=\"hlight\">عبدیا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان حومه ٔ بخش مرکزی شهرستان دامغان است در <span class=\"hlight\" dir=\"rtl\">٩</span>هزارگزی جنوب دامغان در دشت واقع است . آب و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">١١٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولاتش غلات، پسته، انگور و حبوبات است . شغل اهالی زراعت و گله داری است . راه فرعی از طریق امامزاده جعفر دارد. مزرعه ٔ کریم آبادجزء این ده است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(180949, 'عبدیة', '<span class=\"hlight\">عبدیة.</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی َ ]</font></b> (ص نسبی ) مؤنث عبدی . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ع اِمص ) طاعت چنانکه کلمه ٔ عبودیت است . (اقرب الموارد). تقول هو بیّن العبدیة. (اقرب الموارد)؛ یعنی طاعت او آشکار است . <BR><font color=\"Blue\">◄</font> (ص نسبی ) الدراهم العبدیة؛ درهمها بود که از درهمهائی که پس از آن ساختند فاضل تر و راجح تر بود. (اقرب الموارد). نوعی از دراهم جید و اعلا. (ناظم الاطباء).<br /></font></div>'),
(180950, 'عبر', '<span class=\"hlight\">عبر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب ُ ]</font></b> (ع ص، اِ) ج ِ عَبور. رجوع به عَبور شود.<br /></font></div>'),
(180951, 'عبر', '<span class=\"hlight\">عبر.</span> <font color=\"DarkGreen\"><b>[ ع ِ ب َ ]</font></b> (ع اِ) ج ِ عبرة. (منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(180952, 'عبر', '<span class=\"hlight\">عبر.</span> <font color=\"DarkGreen\"><b>[ ع َ ب ِ ]</font></b> (ع ص ) رجل عَبر؛ مرد با اشک . (منتهی الارب ). ذوالعبرة و الحزن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سهم عبر؛ تیر که پر فراوان دارد. (اقرب الموارد).<br /></font></div>'),
(180953, 'عبر', '<span class=\"hlight\">عبر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص )عبرت گرفتن . (اقرب الموارد): اللهم اجعلنا ممن یعبرالدنیا و لایعبر؛ ای ممن یعتبرها و لایموت سریعاً حتی یرضیک بالطاعة. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گرمی چشم . (اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> تذکر. اتعاظ. <BR><font color=\"Blue\">◄</font> تکریم و تعظیم و احترام . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> أبوالعبر؛ بیهوده گوی افسوس کننده . (منتهی الارب ) (اقرب الموارد). أبوعُبیر.<br /></font></div>'),
(180954, 'عبر', '<span class=\"hlight\">عبر.</span> <font color=\"DarkGreen\"><b>[ع ُ ]</font></b> (اِخ ) قبیله ای است . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(180955, 'عبر', '<span class=\"hlight\">عبر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) بسیار از هر چیزی . (ناظم الاطباء) (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زن بی فرزند.زن فرزندمرده . (اقرب الموارد) (منتهی الارب ) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ابر سخت روان . <BR><font color=\"Blue\">◄</font> عقاب . <BR><font color=\"Blue\">◄</font> گرمی چشم . (اقرب الموارد) (منتهی الارب ) (آنندراج ): أری فلانا عبر عینیه . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> کیش عبر؛ قچقار یکسال فریزنا کرده . (منتهی الارب ) (آنندراج ) (اقرب الموارد).<br /></font></div>'),
(180956, 'عبر', '<span class=\"hlight\">عبر.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) کناره ٔ رودبار. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بنات عبر؛ دروغ و باطل . <BR><font color=\"Blue\">◄</font> (ص ) مجلس عبر؛ مجلس بسیار اهل . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه در خور بود کاری را از مردیا زن یا شتر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناقة عبر اسفار بفتح یا ضم اول ؛ ناقه ٔ قوی که قطع کند به هر زمین که آب بگذرد. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(180957, 'عبر', '<span class=\"hlight\">عبر.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) آنچه ازغربی فرات تا بریه ٔ عرب است . (منتهی الارب ). ما اُخذعلی غربی الفرات الی بریة العرب . (اقرب الموارد).<br /></font></div>'),
(180958, 'عبر', '<span class=\"hlight\">عبر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (مص ) عبور کردن و گذشتن از وادی و نهر و جوی . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بیان کردن خواب و خبر دادن مآل کار. (منتهی الارب ). تعبیرکردن خواب و خبردادن از آنچه پایان بدان می انجامد. (اقرب الموارد). تعبیر گفتن خواب . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> درگذشتن و مردن . <BR><font color=\"Blue\">◄</font> شکافتن راه را. <BR><font color=\"Blue\">◄</font> جاری کردن اشک . <BR><font color=\"Blue\">◄</font> اندوهگین شدن . (اقرب الموارد) (منتهی الارب ). فریز ناکرده گذاشتن قچها را. (منتهی الارب ). واگذاشتن پشم را بر قچها در یکسال . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> درگذشتن از آب بچیزی . <BR><font color=\"Blue\">◄</font> تأمل کردن در وزن و ماهیت متاع و درهم . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> با اندیشه خواندن نامه را بدون آواز. (اقرب الموارد) (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ) کنار وادی و ناحیت آن . <BR><font color=\"Blue\">◄</font> (ص ) مجلس عَبر؛ که مردم بسیار در آن بود. (اقرب الموارد).<br /></font></div>'),
(180959, 'عبرات', '<span class=\"hlight\">عبرات .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِ) ج ِ عَبرة. (منتهی الارب ) (از ناظم الاطباء) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) یوم العبرات ؛ از روزهای اعراب است . (ناظم الاطباء).<br /></font></div>'),
(180960, 'عبران', '<span class=\"hlight\">عبران .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) مرد بااشک . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> اندوهگین . (اقرب الموارد).<br /></font></div>'),
(180961, 'عبران', '<span class=\"hlight\">عبران .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) موضعی است . (منتهی الارب ).<br /></font></div>'),
(180962, 'عبرانی', '<span class=\"hlight\">عبرانی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ص نسبی، اِ) لغت جهودان . زبان یهود. (اقرب الموارد) (منتهی الارب ) (آنندراج ) <span class=\"hlight\">:</span> <br />سخن کز روی دین گویی چه عبرانی چه سریانی <br />مکان کز بهر حق جوئی چه جابلقا چه جابلسا.<br /> <font color=\"Red\">سنائی .</font><br />و رجوع به عبرانیان شود.<br /></font></div>'),
(180963, 'عبرانیان', '<span class=\"hlight\">عبرانیان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) این کلمه از عابر مشتق است که بمعنی گذر کردن از نهر یا مکانی دیگر میباشد، و یا اینکه از عابر مشتق است که جد ابراهیم خلیل بود. چون ابراهیم از گذرگاه فرات گذشته به اراضی فلسطین درآمد کنعانیان وی را به عبرانی ملقب نمودند، و از پس این لقب در خانواده ٔاو باقی ماند. در نزد مصریان و فلسطینیان نیز بدین لقب معروف گشتند. اما اصل و منشاء این قوم آنکه اولاًیزدان پاک ابرام را که در آور کلدانیان سکونت داشت اختیار فرمود او را برحسب مسمای اسمش پدر طوایف بسیار و مخصوصاً پدر قوم برگزیده ٔ خود قرار داد و دیانت آنها اصل و اصول دیانت عبادت خدائی است که متصف بصفت توحید است . (قاموس کتاب مقدس ). رجوع به یهود شود.<br /></font></div>'),
(180964, 'عبرانیة', '<span class=\"hlight\">عبرانیة.</span> <font color=\"DarkGreen\"><b>[ ع ِ نی ی َ]</font></b> (ص نسبی، اِ) لغت یهود. (اقرب الموارد). زبان عبری . (ناظم الاطباء). رجوع به عبرانی و عبرانیان شود.<br /></font></div>'),
(180965, 'عبرانیون', '<span class=\"hlight\">عبرانیون .</span> <font color=\"DarkGreen\"><b>[ ع ِ نی یو ]</font></b> (اِخ ) رجوع به عبرانیان و الجماهر ص <span class=\"hlight\" dir=\"rtl\">١٤٠</span> شود.<br /></font></div>'),
(180966, 'عبرانیین', '<span class=\"hlight\">عبرانیین .</span> <font color=\"DarkGreen\"><b>[ ع ِ نی ی ]</font></b> (اِخ ) رجوع به عبرانیان شود.<br /></font></div>'),
(180967, 'عبرب', '<span class=\"hlight\">عبرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) تتم که نوعی از بر درخت ترش است که در طعام اندازند. مقوی احشای حار و قابض و رافع صفراء است . (منتهی الارب ) (آنندراج ). سماق . (اقرب الموارد) (ناظم الاطباء).<br /></font></div>'),
(180968, 'عبربیة', '<span class=\"hlight\">عبربیة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ بی ی َ ]</font></b> (ع ص نسبی ) دیگ که در آن تتم انداخته باشند. (آنندراج ). قدرٌ عبربیة؛ أی سماقیة. (اقرب الموارد) (از ناظم الاطباء).<br /></font></div>'),
(180969, 'عبرت', '<span class=\"hlight\">عبرت .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (ع مص ) عبرة. پند گرفتن . (غیاث اللغات ) (از صراح ) (ناظم الاطباء). عبرة <span class=\"hlight\">:</span> سه بیت شعر یاد داشتم از آن ابوالعتاهیه ... که اندر آن عبرتهاست . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٣٨</span>).<br />خاقانیا به عبرت ناپاکی فلک <br />بر خاک آن شهنشه کشور گذشتنی است .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> نوع . (اقرب الموارد) <span class=\"hlight\">:</span> و اگر توبه نکند او را بعبرتی باید کشت که جهانیان را بدان اعتبار باشد. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>). <BR><font color=\"Blue\">◄</font> سنجیدن . مقیاس گرفتن . (معجم متن اللغة). منقول از مال رؤوس که آن بر سبیل شمار سرهااست نه بمساحت و این گرد فناخسرو اکنون مزرعتی است که عبرت آن دویست و پنجاه دینار بیشتر نباشد. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>). عبرت سه هزاروپانصدوپنجاه درهم است . (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span>). و آن مواضع که فراموش کرده باشند و بعد از مساحت و عبرت معلوم شود از آن عشر خراج بستاند. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١٠٨</span>). رجوع به عبرة شود. <BR><font color=\"Blue\">◄</font> عبور کردن طبیعت است از غفلت بسوی آگاهی . (غیاث اللغات ) (ناظم الاطباء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عبرت دیگران گردانیدن </span> ؛ کسی را سخت تنبیه کردن که دیگران پند گیرند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عبرتگه </span> ؛ دنیا است که از حوادث آن عبرت خیزد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عبرت نما</span> ؛ آنچه موحب اعجاب شود. شگفت انگیز <span class=\"hlight\">:</span> <br />بوقت هندسه عبرت نمائی <br />مجسطی دان و اقلیدس گشائی .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(180970, 'عبرت آمیز', '<span class=\"hlight\">عبرت آمیز.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (ن مف مرکب ) آمیخته به پند. آنچه موجب تنبه و آگاهی گردد. آنچه موجب پند شود. رجوع به عبرت شود.<br /></font></div>'),
(180971, 'عبرت انگیز', '<span class=\"hlight\">عبرت انگیز.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ اَ ]</font></b> (نف مرکب ) عبرت کده . عبرت آور. عبرت گیر. عبرت بین . عبرت پذیر.<br /></font></div>'),
(180972, 'عبرت بین', '<span class=\"hlight\">عبرت بین .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (نف مرکب ) عبرت گیر <span class=\"hlight\">:</span> <br />هان ای دل عبرت بین از دیده نظر کن هان <br />ایوان مدائن را آئینه ٔ عبرت دان . <br /> <font color=\"Red\">خاقانی .</font><br />چو ما را چشم عبرت بین تباه است <br />کجا دانیم کاین گل یا گیاه است .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(180973, 'عبرت شش روزه', '<span class=\"hlight\">عبرت شش روزه .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ت ِ ش ِ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (ترکیب وصفی، اِ مرکب )کنایه از آسمان و زمین و آنچه در مابین آسمان و زمین و روی زمین است از مخلوقات . <BR><font color=\"Blue\">◄</font> کنایه است از آنچه در میان آوریم و از ما بفعل آید. <BR><font color=\"Blue\">◄</font> کنایه به آنچه از حوادث بفعل می آید. (برهان ).<br /></font></div>'),
(180974, 'عبرت پذیر', '<span class=\"hlight\">عبرت پذیر.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ پ َ ]</font></b> (نف مرکب ) عبرت پذیرنده . که عبرت بپذیرد. عبرت بین . عبرت گیر <span class=\"hlight\">:</span> <br />در آن شهر شد با تنی چند پیر<br />همه غایت اندیش و عبرت پذیر.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(180975, 'عبرت پذیرفتن', '<span class=\"hlight\">عبرت پذیرفتن .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ پ َ رُت َ ]</font></b> (مص مرکب ) کنایه از پند گرفتن و نصیحت گوش کردن باشد. (برهان ) (آنندراج ). عبرت گرفتن <span class=\"hlight\">:</span> <br />گه از لوح ِ ناخوانده عبرت پذیر<br />گه از صُحْف ِ پیشینگان درس گیر.<br /> <font color=\"Red\">نظامی .</font><br />مگر کز خوی ِ نیکان پند گیرند<br />وز انجام ِ بَدان عبرت پذیرند.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(180976, 'عبرت گرفتن', '<span class=\"hlight\">عبرت گرفتن .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ گ ِ رِ ت َ ]</font></b> (مص مرکب ) اعتبار. (تاج المصادر). پند گرفتن .<br /></font></div>'),
(180977, 'عبرتا', '<span class=\"hlight\">عبرتا.</span><font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (اِخ ) مؤلف معجم البلدان آرد: گمان دارم این کلمه اعجمی است و آن ده بزرگی است از نواحی بغداد از نواحی بین بغداد و واسط و در این ده بازار معموری است . بسیاری از روات و ادبا را بدان نسبت دهند از جمله اسعدبن نصربن الاسعدالعبرتی النحوی - انتهی .<br /></font></div>'),
(180978, 'عبرد', '<span class=\"hlight\">عبرد.</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ]</font></b> (ع ص ) عُبَرد. عُبَردة. عُبارِد. دختر سپیدرنگ تازه بدن نازک و لرزان اندام . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> عشب عُبرد؛ گیاه باریک و بد. (اقرب الموارد) (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> غصن عبرد و عبارد؛ شاخ نرم و نازک . (اقرب الموارد)(از منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> پیه جنبان و لرزان . (منتهی الارب ) (اقرب الموارد) (آنندراج ).<br /></font></div>'),
(180979, 'عبره', '<span class=\"hlight\">عبره .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ]</font></b> (از ع، اِ) محصولات که از کشتی نشینان و چادرنشینان گیرند. (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> محصولات راهداری . (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> مجازاً بمعنی خراج آمده . (غیاث اللغات ) <span class=\"hlight\">:</span> <br />مخور عبره ٔ هند بی یاد من <br />که هندوتر از تست پولاد من .<br /> <font color=\"Red\">نظامی .</font><br />چو آری بمن عبره ٔ هفت سال <br />دگر عبره ها بر تو باشد حلال .<br /> <font color=\"Red\">نظامی .</font><br />ز هر عبره کاندر شمار آمدش <br />نمودار عبرت بکار آمدش .<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> (اِمص ) بمعنی عبور نیز آمده است . (غیاث اللغات ) (آنندراج ): و هم با آن قدر لشکریان دریا عبره کرد و جزائر از ایشان بستد. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٦٨</span>). و آن مرد داعی را در شب بر چهارپائی نشاندند و بردند تا از آب فرات عبره کردند. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١١٩</span>). چون به جیحون عبره کرد. (راحة الصدور راوندی ).<br /></font></div>'),
(180980, 'عبرود', '<span class=\"hlight\">عبرود.</span> <font color=\"DarkGreen\"><b>[ع ُ ]</font></b> (ع ص ) شحم عبرود؛ پیه لرزان . (ناظم الاطباء).<br /></font></div>'),
(180981, 'عبرونه', '<span class=\"hlight\">عبرونه .</span> <font color=\"DarkGreen\"><b>[ ع ُ ن َ ]</font></b> (اِخ ) (بعبری معبر) یکی از محلات و منازل بنی اسرائیل است که در جوار عیقول جابر بود و موضعش معلوم نیست . (قاموس کتاب مقدس ).<br /></font></div>'),
(180982, 'عبری', '<span class=\"hlight\">عبری .</span> <font color=\"DarkGreen\"><b>[ ع ُ ری ی ]</font></b> (ع اِ) کنار باساق که بر لب جوی روید. (اقرب الموارد) (منتهی الارب ). کنار باساق که بر لب جوی روید و بزرگ شود. (اقرب الموارد). سدر کنار جوی . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> نزد بعضی کنار بی ساق است . (منتهی الارب ).<br /></font></div>'),
(180983, 'عبری', '<span class=\"hlight\">عبری .</span> <font color=\"DarkGreen\"><b>[ ع َ را ]</font></b> (ع ص ) امراءة عبری ؛ زن با اشک . (منتهی الارب ) (آنندراج ). ج، عباری . <BR><font color=\"Blue\">◄</font> عین عبری ؛ چشم پر اشک . (منتهی الارب ) (آنندراج ) (تاج العروس ) (اقرب الموارد).<br /></font></div>'),
(180984, 'عبس', '<span class=\"hlight\">عبس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) گیاهی است، به فارسی شاپاپک یا سیسنبر و به مصر یرنوف نامند. (منتهی الارب ). رستنی است . فارسی آن سابانک است یا سیسنبر است و در مصر به یرنوف معروف است . (اقرب الموارد). در تحفه ذیل نوف آرد: به فارسی شابانک و معرب از او شاباسنج است . رجوع به شابانج شود.<br /></font></div>'),
(180985, 'عبس', '<span class=\"hlight\">عبس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) ترش کردن روی را. (اقرب الموارد) (منتهی الارب ) (المنجد).<br /></font></div>'),
(180986, 'عبس', '<span class=\"hlight\">عبس .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِمص ) ترشرویی . (غیاث اللغات از لطائف و منتخب ) <span class=\"hlight\">:</span> <br />گر جان شیرین خواهد از تو سائلی <br />هرگز اندر چهره ٔ شیرین تو ناید عبس .<br /> <font color=\"Red\">سوزنی .</font><br />زشت آن زشت است و خوب آن خوب و بس <br />دایم این ضحاک و آن اندر عبس .<br /><font color=\"Red\">(مثنوی ).</font><br /></font></div>'),
(180987, 'عبس', '<span class=\"hlight\">عبس .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِ) سرگین و پشک و جز آن خشک شده بر دنب ستور. (منتهی الارب ). بول و سرگین خشک . (غیاث اللغات ). آنچه از بول و سرگین خشک شده و بر دنب شتر چسبیده . (منتهی الارب ) (اقرب الموارد). وَذَح . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شاش برده در فراش که بدان عادت کرده باشد و اثر آن بر بدن و فراش او نمایان بود. و در حدیث است انه کان أبرد من العبس ؛ أی العبد البوال . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (مص ) خشکیدن سرگین و پشک و جز آن بر دنب ستور. <BR><font color=\"Blue\">◄</font> خشک شدن ریم بر دست و اندام . (منتهی الارب ).<br /></font></div>'),
(180988, 'عبس', '<span class=\"hlight\">عبس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) کوهی است . (معجم البلدان ).<br /></font></div>'),
(180989, 'عبس', '<span class=\"hlight\">عبس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) محله ای است به کوفه وبنی عبس بن بغیض بدانجا منسوب است . (معجم البلدان ).<br /></font></div>'),
(180990, 'عبس', '<span class=\"hlight\">عبس .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (اِخ ) ابن بغیض بن ریث بن غطفان . از عدنان . جد جاهلی است پسران او عبسیون اند و عنترةبن شداد به آن منسوب است . مسکن آنها ابتدا به نجد بود پس از اسلام پراکنده شدند و هیچ یک از آنان بدانجا نماندند. (از الاعلام زرکلی ) (معجم البلدان ).<br /></font></div>'),
(180991, 'عبس', '<span class=\"hlight\">عبس .</span> <font color=\"DarkGreen\"><b>[ ع َب َ ]</font></b> (اِخ ) ابن رفاعةبن الحارث . جدی جاهلی است و عباس بن مرداس السلمی از نسل اوست . (از الاعلام زرکلی ).<br /></font></div>'),
(180992, 'عبس آباد', '<span class=\"hlight\">عبس آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (اِخ ) دهی است از دهستان رشخوار بخش رشخوار شهرستان تربت حیدریه . واقع در <span class=\"hlight\" dir=\"rtl\">٦٥</span>هزارگزی شمال باختری رشخوار و <span class=\"hlight\" dir=\"rtl\">٢٠</span>هزارگزی جنوب شوسه ٔ راه عمومی تربت حیدریه به سلامی جلگه ای و گرمسیر است . <span class=\"hlight\" dir=\"rtl\">٩٩٥</span> تن سکنه دارد. آب آن از قنات تأمین میشود. و محصولات آن غلات، بادام، ابریشم و بنشن و پنبه است اهالی به کشاورزی و گله داری اشتغال دارند. صنایع دستی آنها کرباس بافی است . راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(180993, 'عبسر', '<span class=\"hlight\">عبسر.</span> <font color=\"DarkGreen\"><b>[ ع َ س ُ ]</font></b> (ع ص ) شتر ماده ٔ قوی و تیزرو. (اقرب الموارد) (منتهی الارب ) (آنندراج ). رجوع به عبسور شود.<br /></font></div>'),
(180994, 'عبسقان', '<span class=\"hlight\">عبسقان .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (اِخ ) از دهات مالیز هرات ... است . (از معجم البلدان ).<br /></font></div>'),
(180995, 'عبسور', '<span class=\"hlight\">عبسور.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) شتر ماده ٔ قوی تیزرو. (منتهی الارب ) (اقرب الموارد). رجوع به عبسر شود.<br /></font></div>'),
(180996, 'عبسی', '<span class=\"hlight\">عبسی .</span> <font color=\"DarkGreen\"><b>[ ع َ سی ی ]</font></b> (اِخ ) در اصطلاح رجال لقب احمدبن عائذ و اسماعیل بن یحیی و حبیب بن جری و جز آنها است . (ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦١</span>).<br /></font></div>'),
(180997, 'عبسی', '<span class=\"hlight\">عبسی .</span> <font color=\"DarkGreen\"><b>[ ع َ سی ی ]</font></b> (ص نسبی ) نسبت است به عبس بن بغیض بن ریث بن غطفان بن قیس عیلان بن مضربن نزاربن معدبن عدنان . (اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٤</span>).<br /></font></div>'),
(180998, 'عبسی', '<span class=\"hlight\">عبسی .</span> <font color=\"DarkGreen\"><b>[ ع َ سی ی ]</font></b> (ص نسبی ) نسبت است به عبس الازد. (اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٤</span>).<br /></font></div>'),
(180999, 'عبسی', '<span class=\"hlight\">عبسی .</span> <font color=\"DarkGreen\"><b>[ ع َ ی ی ]</font></b> (ص نسبی ) نسبت است به عبس مراد. (اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٤</span>).<br /></font></div>'),
(181000, 'عبسی', '<span class=\"hlight\">عبسی .</span> <font color=\"DarkGreen\"><b>[ ع َ ی ی ]</font></b> (ص نسبی ) منسوب به عبس بن غطفان ربعی بن خراش العبسی الکوفی تابعی مشهور است . از عمرو علی (ع ) و بسیاری از صحابه روایت کند شعبی و منصوربن المعتمر و جز آن از وی روایت کنند. وی مردی ثقة بود و به سال <span class=\"hlight\" dir=\"rtl\">٤٠٤</span> هَ . ق . درگذشت . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٤</span>).<br /></font></div>'),
(181001, 'عبسی', '<span class=\"hlight\">عبسی .</span> <font color=\"DarkGreen\"><b>[ ع َ سی ی ]</font></b> (اِخ ) عبیداﷲبن موسی العبسی از محدثان است . از اسماعیل بن ابی خالد و اعمش روایت کند و بخاری و مردم عراق و غرباء از وی روایت کنند. وی به سال <span class=\"hlight\" dir=\"rtl\">٢١٢</span> یا <span class=\"hlight\" dir=\"rtl\">٢١٣</span> هَ . ق . درگذشت . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٤</span>).<br /></font></div>'),
(181002, 'عبسی', '<span class=\"hlight\">عبسی .</span> <font color=\"DarkGreen\"><b>[ ع َ سی ی ]</font></b> (اِخ ) علی بن افلح، مکنی به ابوالقاسم و ملقب به جمال الدین . شاعری است ظریف و به بسیاری از شهرها سفر کرد و خلفا و ارباب مناصب را مدح گفت وی به سال <span class=\"hlight\" dir=\"rtl\">٥٣٥</span> هَ . ق . به بغداد درگذشت . در سمت غربی مقابر قربش مدفون است . (ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦١</span>).<br /></font></div>'),
(181003, 'عبسی', '<span class=\"hlight\">عبسی .</span> <font color=\"DarkGreen\"><b>[ ع َ سی ی ]</font></b> (اِخ ) عنترةبن شدادبن عمروبن قرار یا غترةبن عمروبن شدادبن عمروبن معاویةبن قرار نجدی عبسی . از مردم نجد و از قبیله ٔ بنی عبس است . از جهت شکاف لب زیرینش ملقب به فلجاء بود مادرش زبیبه کنیز حبشی بود پدر او ابتدا او را نفی ولد کرد و بعد از آنکه بسن رشد رسید مجدداً به فرزندیش اقرار کرد. فرید وجدی آرد: چون وی از مادر کنیز بدنیا آمد برسم جاهلیت وی ابتدا برده ٔ پدرش بود. و چون بسن رشد رسید و در جنگی از خود شهامت و شجاعت نشان داد او را آزاد کرد و او را به فرزندی گزید. وی یکی از فرسان و از قویترین و اعرف مردم زمان خود به فنون جنگی بود. شاعری فصیح بود قصیده ٔ میمیه او که <span class=\"hlight\" dir=\"rtl\">٧٩</span> بیت است مشهور است و چندین بار در برلن و ایران و جز آن جزء معلقات دیگر بچاپ رسیده است . این قصیده از جهت طراوت خاصی که دارددر میان اعراب به مذهبه موصوف گردیده و دیوانی داردکه اولش همان قصیده است و در بیروت و قاهره چاپ شده است . وی به سال <span class=\"hlight\" dir=\"rtl\">٦١٥</span> م . درگذشت . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">٦١</span> - <span class=\"hlight\" dir=\"rtl\">٦٢</span>) (از دائرة المعارف فرید وجدی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٥٨</span>).<br /></font></div>'),
(181004, 'عبسی', '<span class=\"hlight\">عبسی .</span> <font color=\"DarkGreen\"><b>[ ع َ سی ی ]</font></b> (اِخ ) محمدبن ابی شیبة ابراهیم بن عثمان بن خواستی العبسی . از پدر خود و اسماعیل بن ابی خالد و اعمش و جز آنان حدیث شنید. از وی یزیدبن هارون و پسر او عثمان روایت کنند. وی به سال <span class=\"hlight\" dir=\"rtl\">١٨٢</span> هَ . ق . در سن <span class=\"hlight\" dir=\"rtl\">٧٧</span> سالگی درگذشت . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٥</span>).<br /></font></div>'),
(181005, 'عبسیه', '<span class=\"hlight\">عبسیه .</span> <font color=\"DarkGreen\"><b>[ ع َ سی ی َ ]</font></b> (ص نسبی ) منسوب است به قبیله ٔ عبس . (معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br /></font></div>'),
(181006, 'عبسیه', '<span class=\"hlight\">عبسیه .</span> <font color=\"DarkGreen\"><b>[ ع َ سی ی َ ]</font></b> (اِخ ) آبی است به عریمة بین دو کوه طی . (از معجم البلدان ).<br /></font></div>'),
(181007, 'عبش', '<span class=\"hlight\">عبش .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) اصلاح کردن . <BR><font color=\"Blue\">◄</font> ختنه کردن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) صلاح . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> صلاح در هر چیزی . (اقرب الموارد): یقال، الختان عبش للصبی . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> گولی و کندفهمی .(اقرب الموارد) (منتهی الارب ) (آنندراج ) (المنجد).<br /></font></div>'),
(181008, 'عبش', '<span class=\"hlight\">عبش .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِمص ) غباوت .<br /></font></div>'),
(181009, 'عبشمی', '<span class=\"hlight\">عبشمی .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (ص نسبی ) نسبت است به عبد شمس بن عبدمناف . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٥</span>).<br /></font></div>'),
(181010, 'عبشمی', '<span class=\"hlight\">عبشمی .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (اِخ ) احمدبن محمدبن عبداﷲ فقیه العبشمی نیشابوری . از ابوالعباس اصم و جز وی حدیث شنید و حاکم ابوعبداﷲ و جز او از وی روایت کنند. وی به سال <span class=\"hlight\" dir=\"rtl\">٣٨٧</span> هَ . ق . درگذشت . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٥</span>).<br /></font></div>'),
(181011, 'عبشمی', '<span class=\"hlight\">عبشمی .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (اِخ ) علی بن عبداﷲبن علی العبشمی از بنی عبد شمس است . از پدر خود روایت کند و عمربن سعیدبن ابی حسین از وی روایت دارد. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٥</span>).<br /></font></div>'),
(181012, 'عبط', '<span class=\"hlight\">عبط.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) بی علت کشتن ذبیحه ٔ پرگوشت و جوان را. (منتهی الارب ) (اقرب الموارد) (آنندراج ) (المنجد). <BR><font color=\"Blue\">◄</font> بی علت و جوان کشتن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پنهان و غایب گردیدن . (اقرب الموارد) (منتهی الارب ) (آنندراج ) (المنجد). <BR><font color=\"Blue\">◄</font> عبط الارض عبطاً؛ کندن جای ناکنده را. <BR><font color=\"Blue\">◄</font> دروغ بربستن بی سبب و بهانه . <BR><font color=\"Blue\">◄</font> بی سبب و بی باک انداختن خود را در جنگ . برانگیختن خاک را. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اسب را تاختن چندانکه عرق آورد. (اقرب الموارد) (آنندراج ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خون آلود کردن پستان را. <BR><font color=\"Blue\">◄</font> دریدن جامه ٔ نو و درست را. (اقرب الموارد) (منتهی الارب ) (المنجد). <BR><font color=\"Blue\">◄</font> بی موجب رسیدن بلا کسی را. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شکافتن رستنی زمین را. (اقرب الموارد) (المنجد). شکافتن چیزی را. (اقرب الموارد).<br /></font></div>'),
(181013, 'عبط', '<span class=\"hlight\">عبط.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب ُ ]</font></b> (ع ص، اِ) ج ِعبیط. (ناظم الاطباء) (المنجد). رجوع به عبیط شود.<br /></font></div>'),
(181014, 'عبطه', '<span class=\"hlight\">عبطه .</span> <font color=\"DarkGreen\"><b>[ ع ُ طَ ]</font></b> (ع اِمص ) تازگی وتری . (اقرب الموارد) (منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(181015, 'عبعاب', '<span class=\"hlight\">عبعاب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) مرد درازبالا. (اقرب الموارد) (منتهی الارب ) (آنندراج ) (المنجد). فراخ گلوی بزرگ شکم تمام اندام نیکوسرشت . (منتهی الارب ).<br /></font></div>'),
(181016, 'عبعب', '<span class=\"hlight\">عبعب .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (ع اِمص ) نازکی و تازگی جوانی . (منتهی الارب ) (آنندراج ).نعمة الشباب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص، اِ)جوان پرگوشت . <BR><font color=\"Blue\">◄</font> جامه ٔ وسیع و فراخ . <BR><font color=\"Blue\">◄</font> چادر باریک و نازک از پشم شتر. (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> گلیم پشمین . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> مرد جوان تمام . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> بتخانه . <BR><font color=\"Blue\">◄</font> مرد بلند بالا. (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> آهوی نر. (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181017, 'عبعب', '<span class=\"hlight\">عبعب .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (اِخ ) نام بتی است . (اقرب الموارد).<br /></font></div>'),
(181018, 'عبعبة', '<span class=\"hlight\">عبعبة.</span> <font color=\"DarkGreen\"><b>[ ع َع َ ب َ ]</font></b> (اِخ ) نام مادر درنی شاعر. (منتهی الارب ).<br /></font></div>'),
(181019, 'عبعبة', '<span class=\"hlight\">عبعبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ب َ ]</font></b> (ع مص ) شکست خوردن و گریختن . (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(181020, 'عبعبة', '<span class=\"hlight\">عبعبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ب َ ]</font></b> (ع اِ) پشم سرخ . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> پشم گوسفند سرخ رنگ . (ناظم الاطباء) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181021, 'عبق', '<span class=\"hlight\">عبق .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع مص ) چسبیدن بوی خوش به کسی . خوشبوی شدن . (اقرب الموارد) (منتهی الارب ) (المنجد). <BR><font color=\"Blue\">◄</font> اقامت نمودن در جایی . (اقرب الموارد) (منتهی الارب ) (آنندراج ) (المنجد). <BR><font color=\"Blue\">◄</font> آزمند وحریص بچیزی گردیدن . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181022, 'عبق', '<span class=\"hlight\">عبق .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِ) سختی . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (ص ) سبک و چابک . (مهذب الاسماء).<br /></font></div>'),
(181023, 'عبق', '<span class=\"hlight\">عبق .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (اِخ ) جد اسماعیل بن عمربن حفص بن عبداﷲ عبقی بخاری، مکنی به ابواسحاق است . وی از ابی بکر احمدبن سعدبن بکار و ابوصالح الخیام و جز آن روایت کند. از وی ابوالفضل ابراهیم بن حمزةبن یوسف همدانی و ابوکامل بصیری و جز ایشان روایت دارند. وی به سال <span class=\"hlight\" dir=\"rtl\">٤١٧</span>هَ . ق . به بخارا درگذشت . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٦</span>).<br /></font></div>'),
(181024, 'عبق', '<span class=\"hlight\">عبق .</span> <font color=\"DarkGreen\"><b>[ ع َ ب ِ ]</font></b> (ع ص ) مرد آلوده به بوی خوش از چند روز که هنوز باقی است . (منتهی الارب ) (اقرب الموارد) (تاج المصادر بیهقی ) (غیاث اللغات ).<br /></font></div>'),
(181025, 'عبقان', '<span class=\"hlight\">عبقان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) یقال رجل عبقان ؛ مرد بدخوی . (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181026, 'عبقانة', '<span class=\"hlight\">عبقانة.</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ ]</font></b> (ع ص ) زن بدخوی . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181027, 'عبقر', '<span class=\"hlight\">عبقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (اِخ ) دهی است که هر چیز خوب و نیکو را از مردم و جامه و جز آن به وی نسبت کنند. (از اقرب الموارد) (منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(181028, 'عبقر', '<span class=\"hlight\">عبقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ]</font></b> (اِخ ) موضعی است که اعراب گمان برند پریان بسیار در آنجا هستند. لبید گوید: کهول و شبان کجنة عبقر. (اقرب الموارد) (المنجد). <BR><font color=\"Blue\">◄</font> موضعی است بسیارپری . (منتهی الارب ) (آنندراج ) (از معجم البلدان ).<br /></font></div>'),
(181029, 'عبقر', '<span class=\"hlight\">عبقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ق ُ ]</font></b> (اِخ ) ابن انمار از کهلان از قحطانیه . جدی جاهلی است . (از الاعلام زرکلی ).<br /></font></div>'),
(181030, 'عبقر', '<span class=\"hlight\">عبقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ق ُ ر ر ]</font></b> (ع اِ) ژاله و تگرگ که حب الغمام نیز گویند. یقال : ابرد من عبقر. (منتهی الارب ) (آنندراج ) (ناظم الاطباء) (اقرب الموارد).<br /></font></div>'),
(181031, 'عبقری', '<span class=\"hlight\">عبقری .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ری ی ]</font></b> (ع ص ) سید. (اقرب الموارد). رئیس . (مهذب الاسماء).یقال هو عبقری القوم ؛ یعنی مهتر و قوی . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> قوی . <BR><font color=\"Blue\">◄</font> بهتر وکاملتر از هر چیزی . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> آنچه در حسن و نیکوئی فائق تر باشد. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> سخت . (منتهی الارب ). شدید. (اقرب الموارد). یقال ظلم عبقری . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> دروغ بی آمیغ. (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) نوعی از گستردنی دیبانگارین . (منتهی الارب ) (آنندراج ) (غیاث اللغات ). نوعی از گستردنی فاخر، و منه الحدیث :کان عمر یسجد علی عبقری . (منتهی الارب ) <span class=\"hlight\">:</span> <br />کبکان دری غالیه در چشم کشیدند<br />سروان سهی عبقری سبز خریدند.<br /> <font color=\"Red\">منوچهری .</font><br />برگ گل سپید بمانند عبقری <br />برگ گل دو رنگ به کردار جعفری .<br /> <font color=\"Red\">منوچهری .</font><br />سلسبیل از بهر جان تشنگان دارد خدای <br />خرقه پوشان را بود آنجا مسلم عبقری .<br /> <font color=\"Red\">سنائی .</font><br />بسختی نگشت این نمد بسترم <br />روم زین سپس عبقری گسترم .<br /> <font color=\"Red\">سعدی .</font><br />دامن مکش ز صحبت ایشان که در بهشت <br />دامنکشان سندس خضرند و عبقری .<br /><font color=\"Red\">سعدی .</font><br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(181032, 'عبقری', '<span class=\"hlight\">عبقری .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ری ی ]</font></b> (ص نسبی ) نسبت است به عبقربن انمازبن اراش بن عمروبن المغوث بطنی از بجیلة. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٥</span>).<br /></font></div>'),
(181033, 'عبقس', '<span class=\"hlight\">عبقس .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع اِ) جانورکی است . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181034, 'عبقسی', '<span class=\"hlight\">عبقسی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ سی ی ]</font></b> (ص نسبی ) نسبت است به عبدالقیس . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٦</span>) (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181035, 'عبقسی', '<span class=\"hlight\">عبقسی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) احمدبن ابراهیم فراس المکی العبقسی، مکنی به ابوالحسن، از جعفر دبیکی و ابامحمد مقری و جز آنان حدیث شنید و ابوعلی شافعی و جز وی از او روایت کنند. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٦</span>).<br /></font></div>'),
(181036, 'عبقص', '<span class=\"hlight\">عبقص .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع اِ) عبقس . جانورکی است . (منتهی الارب ) (آنندراج ). لغتی است در عبقس . (اقرب الموارد).<br /></font></div>'),
(181037, 'عبقوس', '<span class=\"hlight\">عبقوس .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) جانورکی است . (اقرب الموارد).<br /></font></div>'),
(181038, 'عبقوص', '<span class=\"hlight\">عبقوص .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) جانورکی است . (منتهی الارب ). عبقوس . (اقرب الموارد).<br /></font></div>'),
(181039, 'عبقی', '<span class=\"hlight\">عبقی .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ قی ی ]</font></b> (ص نسبی ) نسبت است به عبق و آن نام جد اسماعیل بن جعفربن عبداﷲبن عبق بن اسد العبقی البخاری، مکنی به ابواسحاق است . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٦</span>).<br /></font></div>'),
(181040, 'عبل', '<span class=\"hlight\">عبل .</span> <font color=\"DarkGreen\"><b>[ ع َ ب ِ ]</font></b> (ع ص ) درشت و سطبر و سپید از سنگ و جز آن . (منتهی الارب ). سطبر. (اقرب الموارد).<br /></font></div>'),
(181041, 'عبل', '<span class=\"hlight\">عبل .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِ) هر برگ تافته بی پهن (نگسترده ) باریک مانند برگ گز. (منتهی الارب ) (اقرب الموارد). درخت ارطی . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> برگ درخت ارطی که سخت و صالح گردد که به وی دباغت کرده شود. (منتهی الارب ) (اقرب الموارد). برگ باریک دراز باشد یا کوتاه . (منتهی الارب ) (اقرب الموارد). الورق الدقیق . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> برگ از درخت ریخته . <BR><font color=\"Blue\">◄</font> برگ نو درآمده . (از لغات اضداد است ). (منتهی الارب ) (اقرب الموارد). ج، أعبال .<br /></font></div>'),
(181042, 'عبل', '<span class=\"hlight\">عبل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) کلان و سطبر از هر چیزی . (منتهی الارب ) (آنندراج ). سطبر از هر چیزی . یقال : رجل عبل الذراعین ؛ أی ضخمها و فرس عبل الشوی ؛ ای غلیظ القوائم . (اقرب الموارد) (از منتهی الارب ) (المنجد). <BR><font color=\"Blue\">◄</font> تمام اندام . (منتهی الارب ) (آنندراج ). ج ِ، عِبال .<br /></font></div>'),
(181043, 'عبل', '<span class=\"hlight\">عبل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) فروریختن برگ درخت . <BR><font color=\"Blue\">◄</font> پیکان پهن نهادن تیر را. <BR><font color=\"Blue\">◄</font> رد کردن چیزی را. (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> بازداشتن چیزی را. <BR><font color=\"Blue\">◄</font> بریدن چیز را. <BR><font color=\"Blue\">◄</font> بردن . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> انداختن بر وی سنگینی را. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> ریختن برگ درخت . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> برگ برآوردن درخت (از اضداد است ). (منتهی الارب ).<br /></font></div>'),
(181044, 'عبلات', '<span class=\"hlight\">عبلات .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) ج ِ عَبلة. (اقرب الموارد) (منتهی الارب ). رجوع به عبله شود.<br /></font></div>'),
(181045, 'عبلة', '<span class=\"hlight\">عبلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) قلعه ای است بین دو همسایه ٔ غرناطه و مریه . (از معجم البلدان ).<br /></font></div>'),
(181046, 'عبلة', '<span class=\"hlight\">عبلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) بنت عبید. از تمیم مادری جاهلی است . زن عبدشمس بن عبدمناف قرشی بود و فرزندان عبدشمس از این زن اند. و آنها را عَبَلات گویند. و آنان سه بطن اند: امیه، عبدامیه، نوفل . (از الاعلام زرکلی ).<br /></font></div>'),
(181047, 'عبلة', '<span class=\"hlight\">عبلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع ص ) سطبر و تمام اندام . (منتهی الارب ). امراءة عبلة؛ زن تمام اندام . (اقرب الموارد).<br /></font></div>'),
(181048, 'عبلی', '<span class=\"hlight\">عبلی .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ لی ْی ]</font></b> (ص نسبی ) نسبت است به عبل و آن بطنی از رعین است . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١١٦</span>).<br /></font></div>'),
(181049, 'عبم', '<span class=\"hlight\">عبم .</span> <font color=\"DarkGreen\"><b>[ ع ِب ْ ب َ ]</font></b> (ع ص ) بلندبالا تن دار. (منتهی الارب ) (آنندراج ) (اقرب الموارد). رجوع به عبام شود.<br /></font></div>'),
(181050, 'عبن', '<span class=\"hlight\">عبن .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ن ن ]</font></b> (ع ص ) سطبر. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> پرگوشت از کرکس و شتر. (منتهی الارب ) (آنندراج ) (از اقرب الموارد) (مهذب الاسماء).<br /></font></div>'),
(181051, 'عبن', '<span class=\"hlight\">عبن .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) سطبری بدن و درشتی آن . (منتهی الارب )(آنندراج ). غلیظ و خشن بودن جسم . (اقرب الموارد).<br /></font></div>'),
(181052, 'عبن', '<span class=\"hlight\">عبن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب ُ ]</font></b> (ع ص ) مرد ملیح پرگوشت تمام اندام . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181053, 'عبنبل', '<span class=\"hlight\">عبنبل .</span> <font color=\"DarkGreen\"><b>[ ع َ بَم ْ ب َ ]</font></b> (ع ص ) بزرگ . <BR><font color=\"Blue\">◄</font> سخت . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181054, 'عبنة', '<span class=\"hlight\">عبنة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ن َ ]</font></b> (ع اِ) طاقت شتر و ناقه . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181055, 'عبنجر', '<span class=\"hlight\">عبنجر.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ج َ ]</font></b> (ع ص ) سطبر درشت . (منتهی الارب ) (آنندراج ). غلیظ، و نون آن زائده است . (اقرب الموارد).<br /></font></div>'),
(181056, 'عبنقس', '<span class=\"hlight\">عبنقس .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ق َ ]</font></b> (ع ص ) مرد بدخوی . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نازک تن . درازبالا از مردان . (اقرب الموارد) (از منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> کسی که دو جده ٔ او از جانب پدرش عجمی باشند. (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181057, 'عبنک', '<span class=\"hlight\">عبنک .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َن ْ ن َ ]</font></b> (ع ص ) سخت درشت . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181058, 'عبنی', '<span class=\"hlight\">عبنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ن نا ]</font></b> (ع ص ) فربه و سطبر از کرکس و شتر. (منتهی الارب ).<br /></font></div>'),
(181059, 'عبهال', '<span class=\"hlight\">عبهال .</span> <font color=\"DarkGreen\"><b>[ ع ِ]</font></b> (ع مص ) بیکار و بر سر خود گذاشتن ستور را. <BR><font color=\"Blue\">◄</font> خشمگین نمودن . (منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(181060, 'عبهر', '<span class=\"hlight\">عبهر.</span> <font color=\"DarkGreen\"><b>[ ع َ هََ ]</font></b> (ع ص ) پر گوشت و بزرگ از مردم . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اسب آکنده گوشت . (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> دراز و نازک و خوش تن از هر چیزی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) نرگس . <BR><font color=\"Blue\">◄</font> یاسمین . <BR><font color=\"Blue\">◄</font> بستان افروز. (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نرگس که در میان آن زرد باشد به خلاف شهلا که سیاه باشد. (غیاث اللغات ) (مهذب الاسماء) <span class=\"hlight\">:</span> <br />ببوئیدم او را وز آن بوی او<br />برآمد ز هر موی من عبهری .<br /> <font color=\"Red\">منوچهری .</font><br />در آفتاب عبهر تو هست تازه تر<br />کز فر و تازگی برد از عبهر آفتاب .<br /> <font color=\"Red\">خاقانی .</font><br />سوسن او بگونه ٔ سنبل <br />لاله ٔ او برنگ عبهر اوست .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(181061, 'عبهر جانان', '<span class=\"hlight\">عبهر جانان .</span> <font color=\"DarkGreen\"><b>[ ع َ هََ رِ ]</font></b> (ترکیب اضافی، اِ مرکب ) استعاره است از چشم معشوق . (ناظم الاطباء) (آنندراج ).<br /></font></div>'),
(181062, 'عبهر لرزان', '<span class=\"hlight\">عبهر لرزان .</span> <font color=\"DarkGreen\"><b>[ ع َ هََ رِ ل َ ]</font></b> (اِخ ) کنایه است از گیسوی حضرت رسالت . (ناظم الاطباء).<br /></font></div>'),
(181063, 'عبهری', '<span class=\"hlight\">عبهری .</span> <font color=\"DarkGreen\"><b>[ ع َ هََ ری ی ]</font></b> (ع ص ) نازک بدن . <BR><font color=\"Blue\">◄</font> سخت سپید. (ناظم الاطباء).<br /></font></div>'),
(181064, 'عبهری غزنوی', '<span class=\"hlight\">عبهری غزنوی .</span> <font color=\"DarkGreen\"><b>[ ع َ هََ ی ِ غ َ ن َ ]</font></b> (اِخ ) عبدالحمید. مردی حکیم و شاعر و ملازم الب ارسلان و ملکشاه بود با شاعرانی مانند حکیم سنایی و ادیب صابر و سوزنی مصاحبت داشته است . از اشعار اوست :<br />بگردون برین بر شد بفخر مملکت ایران <br />که گسترد از برش سایه خجسته رایت سلطان <br />خداوند جهان الب ارسلان سلطان دین پرور<br />که با عدلش نماید جور یکسر عدل نوشروان .<br /><font color=\"Red\">(از مجمع الفصحاء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٧</span>).</font><br /></font></div>'),
(181065, 'عبهلة', '<span class=\"hlight\">عبهلة.</span> <font color=\"DarkGreen\"><b>[ ع َ هََ ل َ ]</font></b> (ع مص ) بیکار و بر سر خود گذاشتن ستور را. (منتهی الارب ) (ناظم الاطباء) (آنندراج ). <BR><font color=\"Blue\">◄</font> خشمگین نمودن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181066, 'عبو', '<span class=\"hlight\">عبو.</span> <font color=\"DarkGreen\"><b>[ ع َ ب ْ وْ ]</font></b> (ع مص ) آماده کردن رخت . (منتهی الارب ) (آنندراج ) (ناظم الاطباء) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> روشن گردیدن روی .(اقرب الموارد) (منتهی الارب ) (آنندراج ) (المنجد).<br /></font></div>'),
(181067, 'عبوثران', '<span class=\"hlight\">عبوثران .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ث ُ <span class=\"hlight\" dir=\"rtl\">/</span> ث َ ]</font></b> (ع ص، اِ) کافور خوشبوی . (مهذب الاسماء). گیاهی است خوشبو. (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> کار سخت . <BR><font color=\"Blue\">◄</font> شر. <BR><font color=\"Blue\">◄</font> ناخوش . <BR><font color=\"Blue\">◄</font> درخت بسیارخار که کسی که بدان افتد خلاص نیابد. (اقرب الموارد).<br /></font></div>'),
(181068, 'عبود', '<span class=\"hlight\">عبود.</span> <font color=\"DarkGreen\"><b>[ ع َ ب ُ وَ ]</font></b> (اِخ ) کوهی است . (منتهی الارب ). زمخشری گوید عبود و صَغَر دو کوهند بین مدینه و سیاله که یکی بر دیگری نگرد و راه مدینه از میان آن دو رد میشود. ابن مناذر شاعر گوید: عبود کوهی است بشام . ابوبکربن مولی گوید: کوهی است بین سیاله و مَلَل . (از اللباب ) (از معجم البلدان ).<br /></font></div>'),
(181069, 'عبود', '<span class=\"hlight\">عبود.</span> <font color=\"DarkGreen\"><b>[ ع َب ْ بو ]</font></b> (اِخ ) مرد افسانه ای بسیارخواب که هفت سال در جای هیزم کشی خود در خواب بود، و در حدیث آمده است نخستین مردی که وارد بهشت شود مرد سیاهی است بنام عبود. این اشارت به این حکایت است که خدا پیامبری را برای راهنمائی مردم قریه ای بفرستاد هیچ یک بدان نگرویدند مگر مرد سیاهی، از این جهت قومش چاهی بکندند و او را در آن بینداختند و سنگی بزرگ بدرب آن گذاردند آن مرد از چاه بیرون میشد و جهت گذران زندگی هیزم کنده میفروخت و از بهای آن غذا و شراب تهیه ومجدداً بدان چاه میرفت . روزی پس از تهیه ٔ هیزم جهت استراحت نشست و بی اختیار سر او به یک طرف رفت و هفت سال بخواب رفت سپس از خواب بیدار شد در حالی که نمیدانست چه ساعتی از روز بخواب شده است، به ده رفت پیامبر را بدانجا نیافت از حال أسود (مرد سیاه ) پرسید پاسخ دادند نمیدانیم کجا است . از اینجا ضرب المثل شد برای کسی که خواب آن طولانی باشد. (از منتهی الارب ).<br /></font></div>'),
(181070, 'عبود', '<span class=\"hlight\">عبود.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b>(ع اِ) ج ِ عبد. (اقرب الموارد). رجوع به عبد شود.<br /></font></div>'),
(181071, 'عبودی', '<span class=\"hlight\">عبودی .</span> <font color=\"DarkGreen\"><b>[ ع َ ی ی ]</font></b> (ص نسبی ) نسبت است به عبود.<br /></font></div>'),
(181072, 'عبودی', '<span class=\"hlight\">عبودی .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ بو دی ی ]</font></b> (اِخ ) احمدبن عبدالواحدبن عبودبن واقد، مکنی به ابوعبداﷲ. از ولیدبن الولید القلانسی و مروان بن محمد و ابی مسهر عبدالاعلی بن مسهر الدمشقی روایت کند و ابوبکربن ابی داود السجستانی و ابوحاتم الرازی و فرزندش عبدالرحمان از وی روایت کنند. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٧</span>).<br /></font></div>'),
(181073, 'عبودیة', '<span class=\"hlight\">عبودیة.</span><font color=\"DarkGreen\"><b>[ ع ُ دی ی َ ]</font></b> (ع اِمص ) پرستش و بندگی . (منتهی الارب ). عبودة. (اقرب الموارد). رجوع به عبودت و عبودیت شود. <BR><font color=\"Blue\">◄</font> در اصطلاح عرفا وفاء به عهود و حفظ حدود و رضای بموجود و صبر بر مفقود است . (تعریفات ).<br /></font></div>'),
(181074, 'عبودیت', '<span class=\"hlight\">عبودیت .</span> <font color=\"DarkGreen\"><b>[ ع ُ دی ی َ ]</font></b> (ع اِمص ) عبودیة. بندگی کردن . (غیاث اللغات ) (المنجد) <span class=\"hlight\">:</span> و دلهای خواص و عوام بر طاعت و عبودیت بیارامید. (کلیله ص <span class=\"hlight\" dir=\"rtl\">٣٧٧</span>).<br />از ثری تا به ثریا به عبودیت او<br />همه در ذکر مناجات و قیام اند و قعود.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(181075, 'عبور', '<span class=\"hlight\">عبور.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) درگذشتن از نهر و وادی . (اقرب الموارد). گذشتن از نهر و جوی . (منتهی الارب ) (آنندراج ). بر آب گذشتن . (تاج المصادر) (غیاث اللغات ) (المنجد). <BR><font color=\"Blue\">◄</font> شکافتن راه را. (اقرب الموارد) (منتهی الارب ) (آنندراج ) (المنجد). <BR><font color=\"Blue\">◄</font> مطلق گذر کردن از راهی . (غیاث اللغات ).<br /></font></div>'),
(181076, 'عبور', '<span class=\"hlight\">عبور.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) نام ستاره ای است که بعد از جوزا درآید. (غیاث اللغات ). شعری عبور؛ یکی از دو شعری و آن سپس جوزاست . آن را عبور نامند چون از حجره گذرد. (اقرب الموارد). نام ستاره ای که بعد جوزا درآید. (منتهی الارب ).<br /></font></div>'),
(181077, 'عبور', '<span class=\"hlight\">عبور.</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) بره ٔ گوسفند. ج، عبائر. (منتهی الارب )(اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) ختنه ناکرده . ج، عُبُر. (منتهی الارب ) (تاج العروس ) (اقرب الموارد).<br /></font></div>'),
(181078, 'عبور دادن', '<span class=\"hlight\">عبور دادن .</span> <font color=\"DarkGreen\"><b>[ ع ُ دَ ]</font></b> (مص مرکب ) گذر دادن . گذراندن .<br /></font></div>'),
(181079, 'عبور و مرور', '<span class=\"hlight\">عبور و مرور.</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ م ُ ]</font></b> (ترکیب عطفی، اِ مرکب ) آمد و شد: در برخی از معابر نویسند که عبور و مرور ممنوع است .<br /></font></div>'),
(181080, 'عبور کردن', '<span class=\"hlight\">عبور کردن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ک َ دَ ]</font></b> (مص مرکب ) گذشتن . درگذشتن . مرور کردن . پیمودن راه را.<br /></font></div>'),
(181081, 'عبورکرده', '<span class=\"hlight\">عبورکرده .</span> <font color=\"DarkGreen\"><b>[ ع ُ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) مرورکرده . درگذشته . پریده .<br /></font></div>'),
(181082, 'عبورگاه', '<span class=\"hlight\">عبورگاه .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِ مرکب ) محل عبور. معبر. راه .<br /></font></div>'),
(181083, 'عبوس', '<span class=\"hlight\">عبوس .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) روی ترش کردن . (اقرب الموارد) (منتهی الارب ) (ترجمان ) (تاج المصادر) (غیاث اللغات ). رجوع به عبس شود.<br /></font></div>'),
(181084, 'عبوس', '<span class=\"hlight\">عبوس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) بسیار ترش روی . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شیربیشه . <BR><font color=\"Blue\">◄</font> روز بد که از آن روی ترش شود. (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181085, 'عبوس', '<span class=\"hlight\">عبوس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ وَ ]</font></b> (ع اِ) جماعت بسیار. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181086, 'عبوس', '<span class=\"hlight\">عبوس .</span> <font color=\"DarkGreen\"><b>[ ع َب ْ بو ]</font></b> (اِخ ) موضعی است . (معجم البلدان ).<br /></font></div>'),
(181087, 'عبوس بودن', '<span class=\"hlight\">عبوس بودن .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ]</font></b> (مص مرکب ) اخمو بودن . ترش روی بودن . بداخم بودن .<br /></font></div>'),
(181088, 'عبوسی کردن', '<span class=\"hlight\">عبوسی کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ دَ ]</font></b> (مص مرکب ) اخم کردن . ترش روئی کردن . ابرو درهم کشیدن .<br /></font></div>'),
(181089, 'عبول', '<span class=\"hlight\">عبول .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) مرگ . (منتهی الارب ).علم است مرگ را. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) امراءة عبول ؛ گریان در مرگ فرزند. (اقرب الموارد).<br /></font></div>'),
(181090, 'عبک', '<span class=\"hlight\">عبک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) آمیختن چیزی به چیزی .(اقرب الموارد) (منتهی الارب ) (آنندراج ) (المنجد).<br /></font></div>'),
(181091, 'عبی', '<span class=\"hlight\">عبی .</span> <font color=\"DarkGreen\"><b>[ ع َ بی ی ]</font></b> (ع اِ) نصیب . (اقرب الموارد). بخش و بهره . (منتهی الارب ) (آنندراج ). یقال عبیک من الجزور؛ ای نصیبک . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181092, 'عبی', '<span class=\"hlight\">عبی .</span> <font color=\"DarkGreen\"><b>[ ع ُب ْ با ]</font></b> (ع ص ) زنی که فرزندش نمیرد. (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181093, 'عبیبة', '<span class=\"hlight\">عبیبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِ) چیزی است شیرین به شکل صمغ که از درخت عرفط برآید و خورده شود. <BR><font color=\"Blue\">◄</font> عصاره . <BR><font color=\"Blue\">◄</font> چراگاه شتران از شورگیاه درزمین پست . (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(181094, 'عبیة', '<span class=\"hlight\">عبیة.</span> <font color=\"DarkGreen\"><b>[ ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُب ْ بی ی َ ]</font></b> (ع اِمص ) بزرگ منشی . فخر. (منتهی الارب ) (آنندراج ) (ناظم الاطباء) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناز و منه عبیة الجاهلیة؛ ای نخوتها. (منتهی الارب ) (آنندراج ) (ناظم الاطباء). رفع عنکم عبیة الجاهلیة؛ ای نخوتها. (اقرب الموارد).<br /></font></div>'),
(181095, 'عبیة', '<span class=\"hlight\">عبیة.</span><font color=\"DarkGreen\"><b>[ ع ُ ب َی ْ ی َ ]</font></b> (اِخ ) نام زنی است . (منتهی الارب ).<br /></font></div>'),
(181096, 'عبیة', '<span class=\"hlight\">عبیة.</span><font color=\"DarkGreen\"><b>[ ع ُ ب َی ْ ی َ ]</font></b> (اِخ ) دو آب است بنی قیس بن ثعلبه را واقع به بطن فلخ از ناحیه ٔ یمامه . (معجم البلدان ).<br /></font></div>'),
(181097, 'عبیث', '<span class=\"hlight\">عبیث .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) نوعی از ریحان . (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181098, 'عبیث', '<span class=\"hlight\">عبیث .</span> <font color=\"DarkGreen\"><b>[ ع ِب ْ بی ]</font></b> (ع ص ) بسیار بازی کننده . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181099, 'عبیثران', '<span class=\"hlight\">عبیثران .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ث ُ ]</font></b> (ع اِ) گیاهی است خوشبو. (اقرب الموارد) (منتهی الارب ) (آنندراج ) (المنجد). <BR><font color=\"Blue\">◄</font> درختی است بسیار خاردار که زود رهایی نیابد از آن هر که خاری به آن رسد. (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> درامر شدید بدان مثل زنند. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> امر شدید. <BR><font color=\"Blue\">◄</font> اشر. (از اقرب الموارد).<br /></font></div>'),
(181100, 'عبید', '<span class=\"hlight\">عبید.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن مالک بن سوید از جذام از قحطانیه . جدی جاهلی است از اعقاب او هستند بنواسیر. و طائفه ای از ایشان در حوف باف (شرقی مصر) بودند. (از الاعلام زرکلی ).<br /></font></div>'),
(181101, 'عبید', '<span class=\"hlight\">عبید.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن شریة الجرهمی در حکمت و خطابت و ریاست در شمار قدما است و نخستین کس است از اعراب که کتاب تصنیف کرد. اصلش از یمن است و در صنعاء اقامت گزیده جاهلیت را درک کرده معاویه درخلافت خود او را بشام خواند و از اخبار عرب و پادشاهان آن قوم از وی جویا شد وی پاسخ گفت از طرف معاویه او را مأمور تدوین اخبار ساخت و او دو کتاب نوشت یکی کتاب الملوک و الاخبار الماضین و دیگری کتاب الامثال . وی به سال <span class=\"hlight\" dir=\"rtl\">٦٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181102, 'عبید', '<span class=\"hlight\">عبید.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن حصین بن معاویةبن جندل نمیری . از مردم مضر است و شاعر و از فحول محدثین است . وی از شترچرانان و بادیه نشین های بصره بود. با جریر و فرزدق معاصر بود و فرزدق را برتر میدانست و جریر او را سخت هجو کرد. وی در حدود سال <span class=\"hlight\" dir=\"rtl\">٩٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181103, 'عبید', '<span class=\"hlight\">عبید.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن بکربن کلاب از بنی عامربن صعصعه از عدنانیه . جدی جاهلی است . (از الاعلام زرکلی ).<br /></font></div>'),
(181104, 'عبید', '<span class=\"hlight\">عبید.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن احمدبن خردادبه . رجوع به به ابن خرداذبه ابوالقاسم و نیز الاعلام زرکلی شود.<br /></font></div>'),
(181105, 'عبید', '<span class=\"hlight\">عبید.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابرص بن عوف بن جشم الاسدی از مضر. شاعر و از بزرگان و حکمای زمان جاهلیت بوده . وی یکی از اصحاب مجمهرات است که در طبقه دوم از معلقات است . معاصر امراء القیس بود و او را مناظرات و مناقضاتی با وی است . عمری دراز کرد. وی در حدود سال <span class=\"hlight\" dir=\"rtl\">٢٥</span> هَ . ق . بدست نعمان بن منذربه قتل رسید. (از الاعلام زرکلی ) (از ریحانة الادب ).<br /></font></div>'),
(181106, 'عبید', '<span class=\"hlight\">عبید.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است از دهستان یخاب بخش طبس شهرستان فردوس واقع در <span class=\"hlight\" dir=\"rtl\">١٣٠</span>هزارگزی شمال خاوری طبس . ناحیه ای است کوهستانی و گرمسیر و خشک و<span class=\"hlight\" dir=\"rtl\">٣٧</span> تن سکنه دارد آب آن از قنات تأمین میشود و محصولات آن غلات و ذرت است . اهالی به کشاورزی اشتغال دارندراه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(181107, 'عبید', '<span class=\"hlight\">عبید.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عَبد. (آنندراج ) (منتهی الارب ) <span class=\"hlight\">:</span> <br />بنده زاده آن خداوند مجید<br />زاده از پشت جواری و عبید.<br /><font color=\"Red\">(مثنوی ).</font><br /></font></div>'),
(181108, 'عبید', '<span class=\"hlight\">عبید.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b>(اِخ ) ابن عوف بن عمر از اوس از قحطان . جدی جاهلی است و از نسل اوست بعضی از صحابه . (از الاعلام زرکلی ).<br /></font></div>'),
(181109, 'عبید', '<span class=\"hlight\">عبید.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن عدی بن کعب از بنی سلمه از خزرج از قحطان جد جاهلی است . از نسل او است بعضی از صحابه . (از الاعلام زرکلی ).<br /></font></div>'),
(181110, 'عبید', '<span class=\"hlight\">عبید.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن عبرةبن زهران از شنوءة الازد از قحطان . جدی جاهلی و از نسل جنادةبن ابی امیه است . (از الاعلام زرکلی ).<br /></font></div>'),
(181111, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن قیس بن سریح بن مالک . رجوع به ابن قیس الرقیات و نیز الاعلام زرکلی شود.<br /></font></div>'),
(181112, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َدُل ْ لاه ]</font></b> (اِخ ) ابن عمربن حفص بن عاصم بن عمربن الخطاب العدوی المدنی مکنی به ابوعثمان . یکی از فقهاء سبعه و از بزرگان مدینه و از اشراف قریش است . وی به سال <span class=\"hlight\" dir=\"rtl\">١٤٧</span> هَ . ق . به مدینه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181113, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُب َ دُل ْ لاه ]</font></b> (اِخ ) ابن عمروالرقی، مکنی به ابو وهب . از حفاظ حدیث . و مفتی جزیره بود و در عصر خود کسی در فتوی با وی منازعت نداشت . وی به سال <span class=\"hlight\" dir=\"rtl\">١٠١</span> هَ . ق . متولد و در <span class=\"hlight\" dir=\"rtl\">١٨٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181114, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن عمربن هشام الحضرمی الاشبیلی . شاعری فاضل بود. او راست : الافصاح فی اختصار المصباح .وی به سال <span class=\"hlight\" dir=\"rtl\">٥٥٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181115, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن عمربن خطاب العدوی القرشی . صحابی و مردی شجاع بود پس از پدر خویش به اسلام گروید و در مدینه ساکن شد و با عبداﷲبن سعد در جنگ افریقا شرکت کرد و در خلافت علی (ع ) بشام رفت و در جنگ صفین همراه معاویه بود و در همان جنگ به سال <span class=\"hlight\" dir=\"rtl\">٣٧</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(181116, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َدُل ْ لاه ]</font></b> (اِخ ) ابن عبداﷲبن عتبةبن مسعود الهذلی . یکی از فقهاء سبعة مدینه و از اعلاء تابعین بود. او را شعری نیکو است که قطعه ای از آن را ابوتمام در حماسه آورده است . وی مؤدب عمربن عبدالعزیز است . وی به سال <span class=\"hlight\" dir=\"rtl\">٩٨</span> هَ . ق . به مدینه درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181117, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن جروالاسدی، مکنی به ابوالقاسم . معتزلی و از علماء عربیت و از مردم موصل است .و او راست : تفسیر القرآن . الموضح فی العروض . المفصح فی القوافی . الامد فی القراآت . و او را شعری است . وی به سال <span class=\"hlight\" dir=\"rtl\">٣٨٧</span> هَ . ق . درگذشت . (از الاعلام زرکلی و روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٦٥</span>).<br /></font></div>'),
(181118, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدبن جعفر الازدی . نحوی است، و او راست : کتاب الاختلاف . النطق .وی به سال <span class=\"hlight\" dir=\"rtl\">٣٤٨</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181119, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن محمدالفاطمی العلوی از فرزندان امام جعفر صادق (ع ) امام و مؤسس دولت علویین در مغرب و جد فاطمیان مصر است . در نسب وی اختلاف است وی در سلمیه ٔ سوریه سکونت داشت سپس بسیاری از اصحاب خود را در مغرب پراکنده کرد تا ظهور امام زمان (مهدی ) را بشارت دهند و مردم را بدو خوانند. گروه بسیاری دعوت او را پذیرفتند خبر به المکتفی باﷲ رسید و او را بطلبید. عبیداﷲ از سلمیه بگریخت و به عراق و سپس به مصر و اسکندریه و از آنجا به مغرب رفت و سرانجام در قیروان به سال <span class=\"hlight\" dir=\"rtl\">٢٩٧</span> هَ . ق . با وی بیعت کردند. وی والیانی به طرابلس، صقلیه و برقه فرستاد و بر تاهرت استیلا یافت و دوبار قصد تصرف مصر کرد ولکن توفیق نیافت و به سال <span class=\"hlight\" dir=\"rtl\">٣٠٣</span> هَ . ق . شهر مهدیه رادر مغرب بنا کرد و آن را پایتخت خود ساخت . وی پس از<span class=\"hlight\" dir=\"rtl\">٢٤</span> سال حکومت به سال <span class=\"hlight\" dir=\"rtl\">٣٢٢</span> هَ . ق . در آنجا درگذشت . تولد او به سال <span class=\"hlight\" dir=\"rtl\">٢٥٩</span> هَ . ق . بود. (از الاعلام زرکلی ).<br /></font></div>'),
(181120, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن مسعودبن محمودبن احمد المحبوبی البخاری ملقب به صدرالشریعة از علماء حکمت و طبیعیات و اصول فقه و دین است و او راست : تعدیل العلوم . شرح الوقایه تألیف جدش محمود در فقه حنفی . النقایه . مختصر الوقایه . الوشاح فی علم المعانی . وی به سال <span class=\"hlight\" dir=\"rtl\">٧٤٧</span> هَ . ق . به بخاری درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181121, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن مظفربن عبداﷲ الباهلی . ادیب و عالم به طب و هندسه و حکمت بوداو را دیوان شعری نیکو است و اصل وی از مردم مریه ٔ اندلس و مولدش یمن است و در بغداد شهرت یافت . و به سال <span class=\"hlight\" dir=\"rtl\">٥٤٩</span> هَ . ق . به دمشق درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181122, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن معمربن عثمان التیمی القرشی . مردی شجاع و بخشنده بود. عثمان بن عفان او را امارت جیش فتح در اطراف اصطخر بداد و او در یکی از جنگها به سال <span class=\"hlight\" dir=\"rtl\">٢٩</span> هَ . ق . کشته شد. (از الاعلام زرکلی ).<br /></font></div>'),
(181123, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمدبن طیفور، مکنی به ابوالحسن . مورخ و از مردم خراسان است .و تولد و وفاتش به بغداد بود. وی ذیلی بر تاریخ پدرخود در اخبار بغداد نوشت . (تاریخ پدر او تا پایان خلافت المهتدی باﷲ است ) او اخبار المعتضد و المکتفی و المقتدر را بدان افزود و قبل از پایان درگذشت . او راکتاب دیگری است به نام المتظرفات و المتظرفین . وی در حدود سال <span class=\"hlight\" dir=\"rtl\">٣١٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181124, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن سری بن الحکم . امیر مصر بود. به سال <span class=\"hlight\" dir=\"rtl\">٢٠٦</span> هَ . ق . سپاهیان با وی بیعت کردند و مأمون عباسی او را به امارت آنجا بداشت . سپس پاره ای از ولایت مصررا به خالدبن یزید شیبانی سپرد عبیداﷲ او را نپذیرفت و با او نبرد کرد فتنه برخاست و به شکست خالد منتهی شد سپس عبداﷲ طاهر از طرف مأمون بشام برفت و به مصر شد. عبیداﷲ مدتی برابر او بایستاد. تا آنکه به سال <span class=\"hlight\" dir=\"rtl\">٢١١</span> امان نامه ٔ مأمون بدو رسید به صلح با ابن طاهرو چون آن دو با یکدیگر ملاقات کردند. طاهر عبیداﷲ راخلعت پوشاند و او را فرمود تا نزد مأمون شود. عبیداﷲ از مصر بیرون شد و مدتی در عراق بماند و به سال <span class=\"hlight\" dir=\"rtl\">٢٥١</span> هَ . ق . بسر من رأی درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181125, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن حسن بغدادی، مکنی به ابوالقاسم و ملقب به غلام، حاسب و فلکی و از افاضل است از کتب اوست : احکام النجوم . اتسییرات و الشعاعات . الاختیارات . الجامع الکبیر. الاصول المجردة.وی به سال <span class=\"hlight\" dir=\"rtl\">٣٧٦</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181126, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن حسین الکرخی، مکنی به ابوالحسن . وی فقیه بود و ریاست حنفیه عراق بدو منتهی شد. مولد اوسال <span class=\"hlight\" dir=\"rtl\">٢٦٠</span> هَ . ق . به کرخ بود و به سال <span class=\"hlight\" dir=\"rtl\">٣٤٠</span> هَ . ق . به بغداد درگذشت . از تألیفات اوست : المختصر. شرح الجامع الصغیر. شرح الجامع الکبیر. (از الاعلام زرکلی ).<br /></font></div>'),
(181127, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن علی نصر معروف به ابن المارستانیه و مکنی به ابوبکر. رجوع به ابن مارستانیه و نیز الاعلام زرکلی شود.<br /></font></div>'),
(181128, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن حر الجعفی . مردی شجاع و در شرف، صلاح و فضل از بزرگان قوم خود بود. وی از اصحاب عثمان بن عفان است . پس از قتل عثمان به معاویه پیوست و در جنگ صفین با او بود پس ازقتل علی (ع ) بکوفه رفت و در فاجعه ٔ حسین بن علی (ع ) خود را پنهان کرد و در کربلا حاضر نشد و چون ابن زیاددر این باره از وی بازخواست کرد پرخاش کرد و دیگر نزد وی نرفت و در محلی کنار فرات اقامت گزید. چون مصعب بن زبیر خروج کرد بدو پیوست و در جنگ مختار ثقفی باوی بود مصعب از او ترسید او را حبس کرد و پس از مدتی با وساطت عده ای آزاد ساخت . و او خشمناک از نزد وی بیرون شد. مصعب کسانی را برای جنگ و تطمیع او فرستادولی سودی نداد سرانجام کار عبیداﷲ بالا گرفت و <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> تن جنگجو فراهم کرد و تکریت را بگرفت و بکوفه حمله کرد و کار را بر مصعب دشوار ساخت سپس عده ای از سپاهیانش متفرق شدند و او از بیم اسیری به سال <span class=\"hlight\" dir=\"rtl\">٦٨</span> هَ . ق . خود را به فرات انداخت و غرق شد. (از الاعلام زرکلی ).<br /></font></div>'),
(181129, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن الحبحاب الموصل . مدتی والی مصر بود. هشام بن عبدالملک وی را به سال <span class=\"hlight\" dir=\"rtl\">١١٧</span> هَ . ق . به افریقیه فرستاد و او کار آنجا را سامان داد و غازیان به صقلیه و سوسن و سرزمین سودان فرستاد و همه پیروز بازگشتند سپس امر بلاد بر او آشفته گشت و هشام او را نزد خود خواند و به سال <span class=\"hlight\" dir=\"rtl\">١٢٣</span> هَ . ق . از کار برکنارش کرد. وی حدود سال <span class=\"hlight\" dir=\"rtl\">١٢٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181130, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن جبرائیل بن عبیداﷲبن بختیشوع . طبیب باحث و از مردم میافارقین است . از تصنیفات او است مناقب الاطباء. الروضة فی الطب . التواصل الی حفظ التناسل . طبایع الحیوان و خواصها و منافع اعضائها. الخاص فی علم الخواص .وی به سال <span class=\"hlight\" dir=\"rtl\">٤٥٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181131, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن احمدبن عبیداﷲ القرشی الاموی العثمانی الاشبیلی . امام نحو و از مردم اشبیله ٔ اندلس بود. هنگامیکه فرنگیان بر اندلس استیلا یافتند وی به بسنة رفت .از تألیفات اوست : شرح کتاب سیبویه . شرح الجمل در ده مجلد. شرح الایضاح که همه ٔ این کتابها در نحو است . وی به سال <span class=\"hlight\" dir=\"rtl\">٥٩٩</span> هَ . ق . متولد و در سال <span class=\"hlight\" dir=\"rtl\">٦٨٨</span> هَ . ق . درگذشت . (از الاعلام زرکلی ) (از روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٦٤</span>).<br /></font></div>'),
(181132, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن زیادبن ظبیان البکری مردی شجاع و نزد عبدالملک بن مروان مقرب بود. مصعب بن زبیر را او کشت و سر او را برای عبدالملک فرستاد. سپس با همراهی ابن جارود بر حجاج خروج کرد. پس ازقتل ابن جارود به عمان رفت و به ابن جلندی ازدی پناهنده شد. ابن جلندی از او بترسید. و او را مسموم کرد. وی به سال <span class=\"hlight\" dir=\"rtl\">٧٥</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181133, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن حسن بن حصین العنبری . قاضی و از فقهاء و عالم به حدیث و از مردم بصره بود ابن حبان نویسد. او در فقه وعلم از سادات بصره بود. به سال <span class=\"hlight\" dir=\"rtl\">١٥٧</span> هَ . ق . قضاوت بصره یافت و به سال <span class=\"hlight\" dir=\"rtl\">١٦٦</span> هَ . ق . به بصره درگذشت . تولد او به سال <span class=\"hlight\" dir=\"rtl\">١٠٥</span> هَ . ق . است . (از الاعلام زرکلی ).<br /></font></div>'),
(181134, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن سریح، مکنی به ابوبحیی . رجوع به ابن سریح و نیز الاعلام زرکلی شود.<br /></font></div>'),
(181135, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b>(اِخ ) ابن سعد الزهری البغدادی، مکنی به ابوالفضل . وی قاضی و از رجال حدیث و ثقات بود. دوبار قضاوت اصفهان یافت و مدت آن اندک بود. به سال <span class=\"hlight\" dir=\"rtl\">١٨٥</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">٢٦٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181136, 'عبیدا', '<span class=\"hlight\">عبیدا.</span><font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن سعید یحیی، مکنی به ابوقدامه و ملقب به سرخسی . از حفاظ و ثقات و رجال حدیث بود. در سرخس متولد و در نیشابور ساکن گشت . ابن حبان گوید: وی سنت را بسرخس آشکار کرد و مردم را بدان خواند. بخاری از وی <span class=\"hlight\" dir=\"rtl\">١٣</span> حدیث و مسلم <span class=\"hlight\" dir=\"rtl\">٤٨</span> حدیث نقل کند. وی به سال <span class=\"hlight\" dir=\"rtl\">٢٤١</span> هَ . ق . در گذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181137, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن سعیدبن حاتم السجزی الوائلی البکری . از حفاظ حدیث بود. اصلش از سجستان و نسبتش بدانجا است . وی در مکه سکونت کرد و به سال <span class=\"hlight\" dir=\"rtl\">٤٤٤</span> هَ . ق . بدانجا درگذشت . از کتب اوست الابانة عن اصول الدیانة. (از الاعلام زرکلی ).<br /></font></div>'),
(181138, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن سلیمان بن وهب، مکنی به ابوالقاسم . وزیر و از اکابر کتاب بود. المعتمد علی اﷲ وی را به وزارت خود برگزید و بعد از وی المعتضد باﷲ نیز وی را بدان سمت ابقا کرد. وزارت او مدت بیست سال طول کشید و به سال <span class=\"hlight\" dir=\"rtl\">٢٨٨</span> هَ . ق . درگذشت . تولد وی به سال <span class=\"hlight\" dir=\"rtl\">٢٢٦</span> هَ . ق . است . (از الاعلام زرکلی ).<br /></font></div>'),
(181139, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن عبدالرحمان کوفی اشجعی . از حفاظ حدیث و از ثقات و امام بود و اصحاب کتب سته از وی روایت کنند. وی به سال <span class=\"hlight\" dir=\"rtl\">١٨٢</span> هَ . ق . به بغداد درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181140, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن عبدالکریم بن زید المخزومی الرازی، مکنی به ابوزرعه . از حفاظ حدیث است یکصدهزار حدیث از حفظ داشت . گویند هر حدیثی را که ابوزرعه نشناسد بلااصل است . وی به سال <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">٢٦٤</span> هَ . ق . به ری درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181141, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن عبداﷲبن طاهربن الحسین الخزاعی . امیر و از ادبا و شعراء بود. وی ولایت شرطه ٔ بغداد را یافت و به سال <span class=\"hlight\" dir=\"rtl\">٢٢٣</span> هَ . ق . به بغداد متولد شد و در <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> هَ . ق . بدانجا درگذشت و معتضد عباسی او را گرامی میداشت . وی در هندسه و موسیقی بارع بود و ترسل نیکو داشت او را تصانیفی است، از جمله الاشارة فی اخبار الشعرا و السیاسة الملوکیه . البراعة و الفصاحة. و او را مراسلات است با ابن معتز که آن را در کتابی فراهم آورده است . (از الاعلام زرکلی ).<br /></font></div>'),
(181142, 'عبیدا', '<span class=\"hlight\">عبیدا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دُل ْ لاه ]</font></b> (اِخ ) ابن علی بن ابی طالب الهاشمی القرشی . مردی شجاع و عابد بود. در جنگی که مصعب با مختار کرد عبیداﷲ با مصعب بود و به سال <span class=\"hlight\" dir=\"rtl\">٦٧</span> هَ . ق . در یکی از جنگها به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(181143, 'عبیدان', '<span class=\"hlight\">عبیدان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) نام وادی حیه است به ناحیه یمن که گویند در آن مار بزرگی است . که مانع رفت و آمد و چرانیدن حیوانات است . (معجم البلدان ).<br /></font></div>'),
(181144, 'عبیدلی', '<span class=\"hlight\">عبیدلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دِ ]</font></b> (اِخ ) یحیی بن حسن عقیقی بن جعفر الحجةبن عبیداﷲ اعرج بن حسین اصغربن امام السجاد مکنی به الحسن و معروف به عبیدلی از رجال قرن سوم هجری و عالم به انساب است . وی نخستین کس است که در انساب علویین کتاب نوشت . از جمله تألیفات اوست : اخبارالزینبیات که در شرح حال زنان زینب نام است از اولاد ابوطالب . اخبارالمدینة، انساب آل ابی طالب . وی به سال <span class=\"hlight\" dir=\"rtl\">٢٦٦</span> هَ . ق . درگذشت . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦</span>).<br /></font></div>'),
(181145, 'عبیدلی', '<span class=\"hlight\">عبیدلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دِ ]</font></b> (اِخ ) حیدربن علی بن حیدرعلوی حسنی آملی مازندرانی عبیدلی یا عبیدی وی حکیم . عارف، مفسر، صوفی و از اکابر عرفا و علمای امامیه و جامع شریعت و طریقت است . اصل او از آمل مازندران و نشأتش در بغداد بوده و با فخرالمحققین مصاحبت داشت از تألیفات اوست : الارکان فی فروع شرایع اهل الایمان . الامامة. الامانه امثلة التوحید. التأویلات که چهارمین تفسیر او است . التنزیه . جامع الاسرار و منبع الابرار در اسرار انبیاء و اولیاء و علم توحید. جامع الحقایق . رافعة الخلاف فی وجه سکوت امیرالمؤمنین . رسالة العلوم العالیه . شرح فصوص (نص النصوص ). الکشکول فی بیان ماجری علی آل رسول . المحیط الاعظم . منتخب التأویل . (ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٤</span> و الذریعة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٢</span>).<br /></font></div>'),
(181146, 'عبیدلی', '<span class=\"hlight\">عبیدلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دِ ]</font></b> (اِخ ) احمدبن محمدبن مهنابن علی بن مهنای حسینی عبیدلی . مردی عالم و نسابه و از اکابر علمای اواخر قرن هفتم یا اوائل قرن هشتم بود. از شاگردان جلال الدین علی بن عبدالحمیدبن فخار است و بنابر قول اعیان الشیعه استاد احمدبن علی بن حسین بن علی بن مهنا صاحب عمدة الطالب است . از تألیفات اوست : الانساب المشجره یا مشجر النسب . التذکرة فی الانساب المطهرة که در اعیان الشیعه به سید احمد عبیدلی نسبت داده شد. و عنوان همین کتاب است . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٤</span>).<br /></font></div>'),
(181147, 'عبیدلی', '<span class=\"hlight\">عبیدلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دِ ]</font></b> (اِخ ) ابن ابی جعفر محمدبن علی الجوادبن حسن بن علی بن ابراهیم بن علی الصالح بن عبیداﷲ اول اعرج بن حسین الاصغربن الامام السجاد. و عالم به انساب و از جمله ٔ معمرین بود به سال <span class=\"hlight\" dir=\"rtl\">٣٣٥</span> هَ . ق . درگذشت . از تألیفات اوست : تهذیب الانساب . نهایة الاعقاب . (از ریحانة الادب و الذریعه ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠٨</span>).<br /></font></div>'),
(181148, 'عبیدلی', '<span class=\"hlight\">عبیدلی .</span> <font color=\"DarkGreen\"><b>[ ع َ دِ ]</font></b> (اِخ ) نام یکی از دهستان های شش گانه ٔ بخش لنگه ٔ شهرستان بوشهر است . حدود و مشخصات آن بقرار زیر است . از شمال دهستان حمدادی از جنوب ارتفاعات چیرو و خلیج فارس از باختر دهستان بدوی از خاور دهستان چارکی . این دهستان تقریباً در مرکز بخش واقع گردیده و هوای آن گرم و مرطوب است . آب مشروب آن از باران و چاه تأمین میشود. زراعت آنها دیمی است . محصولات آن غلات، خرما، لبنیات و جزئی صیفی است . شغل اهالی زراعت و گله داری است . از <span class=\"hlight\" dir=\"rtl\">٨</span> آبادی تشکیل شده است و در حدود <span class=\"hlight\" dir=\"rtl\">٢٢٠٠</span> تن سکنه دارد. قراءمهم آن عبارتند از بندر چیرویه، نخل خلفان، ارمکی، جزیره ٔ هندورابی . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(181149, 'عبیدی', '<span class=\"hlight\">عبیدی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ دی ی ]</font></b> (ص نسبی ) نسبت است به عبیدبن ثعلبةبن یربوع بن حنظلةبن مالک بن زیدبن مناة بطنی از تمیم است . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٦</span>). <BR><font color=\"Blue\">◄</font> نسبت است به عبیدبن عدی بن غنم بن کعب بن سلمةبن سعدبن علی اسدبن ساردةبن تزیدبن جشم بن الخزرج بطنی از انصار. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٧</span>). <BR><font color=\"Blue\">◄</font> نسبت است به عبیده بن عبرةبن زهران بطنی از ازد. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٧</span>). <BR><font color=\"Blue\">◄</font> نسبت است به عبیدبن سلامةبن زوی مالک بن نهد بطنی از نهد. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٧</span>).<br /></font></div>'),
(181150, 'عبیر', '<span class=\"hlight\">عبیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) نوعی از خوشبوهای خشک که بر جامه پاشند. (آنندراج از صراح ) (غیاث اللغات ). نام خوشبوی که از صندل و گلاب و مشک سازند. (آنندراج از منتخب ) (غیاث اللغات ). زعفران یا بوی خوش با زعفران آمیخته . (منتهی الارب ). اخلاطی است از بوی خوش که با زعفران فراهم گردد. (اقرب الموارد) <span class=\"hlight\">:</span> <br />این حدیث از سر دردیست که من میگویم <br />تا در آتش ننهی بوی نیاید ز عبیر.<br /> <font color=\"Red\">سعدی .</font><br />گفته شده است زعفران به تنهائی را گویند. (از اقرب الموارد) (مهذب الاسماء) <span class=\"hlight\">:</span> <br />کجا برفشانند مشک و عبیر<br />همی گسترانند خز و حریر.<br /> <font color=\"Red\">فرخی .</font><br />بدو گفتم که مشکی یا عبیری <br />که از بوی دلاویز تو مستم .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عبیرآلای </span> ؛ آلوده به عبیر. (از آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عبیرآمیز</span> ؛ عبیرافشان . خوشبوی بمانند عبیر <span class=\"hlight\">:</span> <br />ز مشک افشانی باد طربناک <br />عبیرآمیز گشته نافه ٔ خاک .<br /> <font color=\"Red\">نظامی .</font><br />خیال خال تو با خود بخاک خواهم برد<br />که تاز خال تو خاکم شود عبیرآمیز.<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عبیرافشان </span> ؛ خوش بوی . عطرآگین .که بوی عبیر دهد <span class=\"hlight\">:</span> <br />طبله ٔ عطر گل و زلف عبیرافشانش <br />فیض یک شمه ز بوی خوش عطار من است .<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عبیرسرشت </span> ؛ آمیخته با عبیر <span class=\"hlight\">:</span> <br />خاکش از بوی خوش عبیرسرشت <br />میوه هایش چو میوه های بهشت .<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> (ص ) قوم عبیر؛ گروه بسیار. (منتهی الارب ) (اقرب الموارد) . <BR><font color=\"Blue\">◄</font> سهم عبیر؛ تیر سیاه ناپیراسته . تیر بسیارپر. (منتهی الارب ). تیر بسیار. (اقرب الموارد).<br /></font></div>'),
(181151, 'عبیرآباد', '<span class=\"hlight\">عبیرآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است از دهستان دربقاضی بخش حومه ٔ شهرستان نیشابور، واقع در <span class=\"hlight\" dir=\"rtl\">١٨</span> هزارگزی جنوب خاوری نیشابور. در جلگه واقع است . و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٣٥٤</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات است شغل اهالی زراعت و مالداری است .راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(181152, 'عبیرآباد', '<span class=\"hlight\">عبیرآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ بخش مرکزی شهرستان دامغان، واقع در ده هزارگزی جنوب باختری دامغان . و هفت هزارگزی ایستگاه . هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> تن سکنه دارد. آب آن از قنات و چشمه علی تأمین میشود. محصولات آن غلات، پسته، پنبه، انگور و حبوبات است . شغل اهالی زراعت و گله داری است . صنایع دستی آنها کرباس بافی است . راه فرعی آن از ایستگاه منشعب میشود. دبستان دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(181153, 'عبیط', '<span class=\"hlight\">عبیط.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) شتر فربه و جوان که بی علت و بیماری کشته باشند. ج، عُبُط، عِباط. (از اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> تازه . (از اقرب الموارد) (منتهی الارب ). دم عبیط. لحم عبیط. (آنندراج ). زعفران عبیط. (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> ثوب عبیط؛ جامه ٔ نو دریده . (منتهی الارب ) (آنندراج ). أدیم عبیط، مشقوق . (اقرب الموارد).<br /></font></div>'),
(181154, 'عبیقر', '<span class=\"hlight\">عبیقر.</span><font color=\"DarkGreen\"><b>[ ع َ ب َ ق ُ ]</font></b> (اِخ ) موضعی است . رجوع به عبقر شود.<br /></font></div>'),
(181155, 'عبیک', '<span class=\"hlight\">عبیک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است از بخش جاپلق شهرستان سراوان، واقع در <span class=\"hlight\" dir=\"rtl\">٣٤</span> هزارگزی جنوب جاپلق کنار راه فرعی سراوان بجاپلق ناحیه ای کوهستانی و گرمسیر و مالاریایی است <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن سکنه دارد. آب آن از رودخانه تأمین میشود. محصولاتش غلات، برنج، خرماست . اهالی به کشاورزی اشتغال دارند. راه فرعی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(181156, 'عت', '<span class=\"hlight\">عت .</span> <font color=\"DarkGreen\"><b>[ ع َت ت ]</font></b> (ع مص ) باز بازگردانیدن بر کسی سخن را. (منتهی الارب ) (آنندراج ). رد کردن کلام بر کسی باری پس از بار دیگر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ستیهیدن بر کسی در سؤال . (منتهی الارب ) (آنندراج ) (اقرب الموارد).<br /></font></div>'),
(181157, 'عتاب', '<span class=\"hlight\">عتاب .</span> <font color=\"DarkGreen\"><b>[ ع ُت ْ تا ]</font></b> (اِخ ) نام شخصی است که مخترع خارا بوده و آن پارچه ای است موجدار که از ابریشم میبافند. (برهان ). رجوع به عتابی شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(181158, 'عتاب', '<span class=\"hlight\">عتاب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) خشم گرفتن . <BR><font color=\"Blue\">◄</font> خشم گرفتن همدیگر را. <BR><font color=\"Blue\">◄</font> ناز کردن . <BR><font color=\"Blue\">◄</font> خشمگینی پیدانمودن . <BR><font color=\"Blue\">◄</font> یاد کردن خشم را. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> ملامت کردن . (منتهی الارب ) (اقرب الموارد) <span class=\"hlight\">:</span> <br />با بخت در عتابم و با روزگار هم <br />وز یار در حجابم و از غمگسار هم .<br /> <font color=\"Red\">خاقانی .</font><br />عتاب از حد گذشته جنگ باشد<br />زمین چون سخت گردد سنگ باشد.<br /> <font color=\"Red\">نظامی .</font><br />هر آینه در معرض خطاب آیند و در محل عتاب . (گلستان ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عتاب کردن </span> ؛ سرزنش کردن . ملامت کردن <span class=\"hlight\">:</span> <br />کسان عتاب کنندم که ترک عشق بگوی <br />بنقد اگر بکشد عاشق این سخن بکشد.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(181159, 'عتاب', '<span class=\"hlight\">عتاب .</span> <font color=\"DarkGreen\"><b>[ ع َت ْ تا ]</font></b> (اِخ ) ابن ورقاء الریاحی . از شجاعان و از امیران عرب است و از امرای مصعب بن زبیر است . او را امارت اصفهان داد و به جنگ خوارج ری فرستاد به ری برفت و با خارجیان جنگی سخت کرد و ری را به قهر تصرف کرد و سپس حجاج او را به جنگ شیب بن یزید فرستاد و او با لشکریان بسیار از مردم شام و عراق با شیب نبرد کرد. و سرانجام در جنگی به سال <span class=\"hlight\" dir=\"rtl\">٧٧</span> هَ . ق . به دست عامربن عمر تغلبی کشته شد. (از الاعلام زرکلی ).<br /></font></div>'),
(181160, 'عتاب', '<span class=\"hlight\">عتاب .</span> <font color=\"DarkGreen\"><b>[ ع َت ْ تا ]</font></b> (اِخ ) ابن اسیدبن ابی العیص بن امیة. از والیان اموی و از قریش و از مردم مکه و صحابه است . وی مردی شجاع، عاقل و از اشراف عرب بود. رسول (ص ) در عام الفتح او را بر مکه گماشت و ابوبکر نیز او را ابقاء کرد و تا به سال <span class=\"hlight\" dir=\"rtl\">١٣</span> هَ . ق . که درگذشت بدان شغل بماند. بعض مورخان گویند وی تااواخر خلافت عمر در ولایت مکه باقی بود و بنابر این وفاتش در اوائل سال <span class=\"hlight\" dir=\"rtl\">٢٣</span> بوده است . (از الاعلام زرکلی ).<br /></font></div>'),
(181161, 'عتاب و خطاب', '<span class=\"hlight\">عتاب و خطاب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ب ُ خ ِ ]</font></b> (ترکیب عطفی، اِ مرکب ) سرزنش . ملامت . تندی در سخن . رجوع به عتاب شود.<br /></font></div>'),
(181162, 'عتابة', '<span class=\"hlight\">عتابة.</span> <font color=\"DarkGreen\"><b>[ ع َت ْ تا ب َ ]</font></b>(اِخ ) نامی از نامهای زنان است . (از منتهی الارب ).<br /></font></div>'),
(181163, 'عتابی', '<span class=\"hlight\">عتابی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b>(ص نسبی، اِ) قسمی از خارا که جامه ای معروف است . (غیاث اللغات ) (آنندراج ). خارایی موجدار منسوب به محله ای از بغداد. (دیوان البسه ٔ نظام قاری ص <span class=\"hlight\" dir=\"rtl\">٢٠٢</span>). و در این بیت منوچهری به تشدید تاء آمده است <span class=\"hlight\">:</span> <br />یا چنان زرد یکی جامه ٔ عتابی <br />پرز برخاسته زو چون سر مرغابی .<br /><font color=\"Red\">منوچهری .</font><br />آنجا که چرخ عتبه ٔ اقبال او گشاید<br />دهر سفیدجامه چه باشد یکی عتابی .<br /> <font color=\"Red\">ظهیر.</font><br />گر به دیباهای رنگین آدمی گردد کسی <br />پس در اطلس چیست گرگ و در عتابی سوسمار.<br /><font color=\"Red\">کمال اسماعیل .</font><br /></font></div>'),
(181164, 'عتابی', '<span class=\"hlight\">عتابی .</span> <font color=\"DarkGreen\"><b>[ ع َت ْ تا ]</font></b> (اِخ )لقب کلثوم بن عمرو است . رجوع به کلثوم بن عمرو شود.<br /></font></div>'),
(181165, 'عتابی', '<span class=\"hlight\">عتابی .</span> <font color=\"DarkGreen\"><b>[ ع َت ْ تا ]</font></b> (اِخ ) لقب ابوالعتاهیه است . رجوع به ابوالعتاهیه و محمدابوعبداﷲ شود.<br /></font></div>'),
(181166, 'عتاد', '<span class=\"hlight\">عتاد.</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (ع اِمص، اِ) ساخت . (منتهی الارب ). آنچه آماده باشد از سلاح و چارپا و ساز جنگ . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سامان . <BR><font color=\"Blue\">◄</font> آمادگی . <BR><font color=\"Blue\">◄</font> آنچه جهت سفر و جز آن آماده سازند. (منتهی الارب ).<br /></font></div>'),
(181167, 'عتاد', '<span class=\"hlight\">عتاد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) آماده گردیدن . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181168, 'عتار', '<span class=\"hlight\">عتار.</span> <font color=\"DarkGreen\"><b>[ ع َت ْ تا ]</font></b> (ع ص ) دلاور. <BR><font color=\"Blue\">◄</font> اسب توانا. (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> جای درشت و خالی . (از اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181169, 'عتار', '<span class=\"hlight\">عتار.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) نره . (منتهی الارب ).<br /></font></div>'),
(181170, 'عتاق', '<span class=\"hlight\">عتاق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) آزاد گردیدن . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181171, 'عتاق', '<span class=\"hlight\">عتاق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص، اِ) عتاق الطیر؛ مرغان شکاری . (منتهی الارب ) (اقرب الموارد). عتاق الخیل ؛ اسبان برگزیده و گرامی . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181172, 'عتاق', '<span class=\"hlight\">عتاق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) شراب نیک کهنه . (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181173, 'عتان', '<span class=\"hlight\">عتان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) آبی است مقابل خیبر. (منتهی الارب ).<br /></font></div>'),
(181174, 'عتاه', '<span class=\"hlight\">عتاه .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) سبک عقل گردیدن . (منتهی الارب ) (آنندراج ). ناقص عقل شدن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مدهوش گشتن و رفتن خرد. (منتهی الارب )(آنندراج ). مدهوش گشتن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مدهوش شدن بدون زوال عقل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آزمند علم گردیدن و حریص شدن بر آن . <BR><font color=\"Blue\">◄</font> حریص شدن بر اذیت کسی . <BR><font color=\"Blue\">◄</font> حریص شدن بر حکایت کردن کلام کسی . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181175, 'عتاه', '<span class=\"hlight\">عتاه .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) ناقص شدن عقل بدون جنون . (اقرب الموارد).<br /></font></div>'),
(181176, 'عتاهیة', '<span class=\"hlight\">عتاهیة.</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ی َ ]</font></b> (ع مص ) رجوع به عُتاه شود در همه ٔ معانی <BR><font color=\"Blue\">◄</font> (اِمص ) کم عقلی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> گمراهی . <BR><font color=\"Blue\">◄</font> (ص )مردم بی عقل و احمق . (منتهی الارب ) (اقرب الموارد).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ابوالعتاهیه </span> . رجوع به همین کلمه شود.<br /></font></div>'),
(181177, 'عتاک', '<span class=\"hlight\">عتاک .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) موضعی است . (منتهی الارب ).<br /></font></div>'),
(181178, 'عتب', '<span class=\"hlight\">عتب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) بسیار خشم گیرنده . (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181179, 'عتب', '<span class=\"hlight\">عتب .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ]</font></b> (ع ص، اِ) کار کریه و ناخوش . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> سختی ؛ یقال ما فی هذا الامر رتب ولا عتب ؛ ای شدة. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> میان انگشت سبابه و وسطی یا میانه ٔ وسطی و بنصر. <BR><font color=\"Blue\">◄</font> چوبهای پهن که بر عود نهند تا تارهای عود را بدان دراز کشند. <BR><font color=\"Blue\">◄</font> درشتی زمین . <BR><font color=\"Blue\">◄</font> تباهی . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181180, 'عتب', '<span class=\"hlight\">عتب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) خشم گرفتن . (منتهی الارب ) (آنندراج ). خشم گرفتن بر کسی و انکار کردن چیزی را از قبل او. <BR><font color=\"Blue\">◄</font> ملامت کردن . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> بر سه پای رفتن ستور. (منتهی الارب ) (اقرب الموارد). بر سه پای رفتن شتر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> یک پای برداشته جستن مردم . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پاسپر کردن آستانه را. (منتهی الارب ) (آنندراج ). ماعبت باب فلان ؛ یعنی نسپردم آستانه او را. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) ملامت . (منتهی الارب ). سرزنش .<br /></font></div>'),
(181181, 'عتبات', '<span class=\"hlight\">عتبات .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (ع اِ) ج ِ عتبة. رجوع به عتبه شود. <BR><font color=\"Blue\">◄</font> نام بالغلبه است مشاهد متبرکه را مانند مشهد حضرت علی (ع ) و حضرت حسین (ع ) و دیگر مزارات امامان .<br /></font></div>'),
(181182, 'عتبان', '<span class=\"hlight\">عتبان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن مالک الانصاری الخزرجی السالمی . صحابی و از بدریان است حضرت رسول (ص ) بین او و عمر برادری افکند در صحیحین ده حدیث از او روایت شده است . (از الاعلام زرکلی ).<br /></font></div>'),
(181183, 'عتبان', '<span class=\"hlight\">عتبان .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (ع مص ) رجوع به عتب شود.<br /></font></div>'),
(181184, 'عتبة', '<span class=\"hlight\">عتبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ]</font></b> (اِخ ) ابن ابی سفیان بن حرب بن امیةبن عبدشمس است که معاویه به سال <span class=\"hlight\" dir=\"rtl\">٤٣</span> هَ . ق . وی را ولایت مصر داد سپس به اسکندریه شد و در آنجا برای خود خانه ای بساخت و به سال <span class=\"hlight\" dir=\"rtl\">٤٤</span> هَ . ق . بدانجا درگذشت . (از الاعلام زرکلی ).<br /></font></div>'),
(181185, 'عتبة', '<span class=\"hlight\">عتبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن غزوان بن جابربن وهیب الحارثی . بانی شهر بصره وصحابی و قدیم الاسلام است . وی به حبشه عزیمت کرد و درجنگ بدر و قادسیه حاضر بود. عمر او را ولایت بصره داد در آن وقت بصره را «الابلة» یا «أرض الهند» مینامیدند. عتبه طرح شهر را بیفکند سپس به میسان و ابزقباذبرفت و آنجا را بگشود. عمر او را به مدینه خواند و هنگام بازگشت به سال <span class=\"hlight\" dir=\"rtl\">١٧</span> هَ . ق . در راه بمرد. وی قامتی بلند و چهره ای زیبا داشت و از تیراندازان نامی بود و صحیحین از او چهار حدیث آورده است . (از الاعلام زرکلی ) (نزهة القلوب ص <span class=\"hlight\" dir=\"rtl\">٣٧</span>) (عیون الاخبار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٧</span>).<br /></font></div>'),
(181186, 'عتبة', '<span class=\"hlight\">عتبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن ربیعةبن عبدشمس مکنی به ابوالولید. از بزرگان قریش در عصر جاهلی است . اسلام را دریافت و در جنگ بدر با مشرکان بود و چون سری بزرگ داشت خودی که برای او مناسب باشد یافت نشد و پارچه ای بر سر خود بست . وی در این جنگ به سال <span class=\"hlight\" dir=\"rtl\">٢</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(181187, 'عتبة', '<span class=\"hlight\">عتبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن الحباب انصاری شاعری غزل سرای و از مردم مدینه و از شعرای عصر اموی است . وی نزدیک مدینه به قتل رسید. (از الاعلام زرکلی ).<br /></font></div>'),
(181188, 'عتبة', '<span class=\"hlight\">عتبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع اِ) خم رودبار. (اقرب الموارد).<br /></font></div>'),
(181189, 'عتبة', '<span class=\"hlight\">عتبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ب َ ]</font></b> (ع اِ) آستانه ٔ در یا بالایین ازهر دو. (منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> هر پله از نردبان . یک پایه نردبان . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زن مرد. (منتهی الارب ). زن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) ناخوش . (اقرب الموارد) (آنندراج ) (منتهی الارب ). یقال، حُمِل َ فلان علی عَتَبَة؛ أی امر کریه من البلاء. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِمص ) سختی . (منتهی الارب ).<br /></font></div>'),
(181190, 'عتبی', '<span class=\"hlight\">عتبی .</span> <font color=\"DarkGreen\"><b>[ ع ُ با ]</font></b> (ع اِمص ) خشنودی و رضا. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181191, 'عتبی', '<span class=\"hlight\">عتبی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) رجوع به محمدبن احمد عتبی شود.<br /></font></div>'),
(181192, 'عتبی', '<span class=\"hlight\">عتبی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) اسعدبن مسعودبن علی بن محمدبن حسن عتبی مکنی به ابوابراهیم عالم، شاعر و منشی دوره ٔ سلجوقیان و غزنویان بود. به سال <span class=\"hlight\" dir=\"rtl\">٤٠٤</span> هَ . ق . متولد شده است و تا اواخر ایام نظام الملک میزیسته و تاریخ وفاتش به درستی معلوم نیست . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٧</span>).<br /></font></div>'),
(181193, 'عتبی', '<span class=\"hlight\">عتبی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b>(اِخ ) محمدبن عبدالجبار. رازی الاصل خراسانی النشاءةاست . مکنی به ابونصر از نویسندگان و شاعران قرن پنجم هجری است . اصل او از ری بود و در خراسان نشأت یافت و در نیشابور سکونت جست . او راست : تاریخ آل سبکتکین یا تاریخ عتبی که به تاریخ یمینی مشهور است یمینی آن را شرح کرده و جرزمانی به فارسی درآورده است به سال <span class=\"hlight\" dir=\"rtl\">٤٢٧</span> هَ . ق . درگذشت . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨</span>).<br /></font></div>'),
(181194, 'عتبی', '<span class=\"hlight\">عتبی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) محمدبن عبداﷲ یا عبیداﷲبن عمرو یا عمربن معاویةبن عمروبن عتبةبن ابی سفیان صخربن حرب بن امیةبن عبدشمس قرشی اموی بصری المنشاء بغدادی المسکن و مدفن . ادیبی فصیح اللسان از افاضل و از شعراء مشهور عرب است . از تألیفات اوست الاخلاق . اشعار الاعاریب . اشعارالنساء. الخیل . الذبیح . وی به سال <span class=\"hlight\" dir=\"rtl\">٢٢٨</span> هَ . ق . به بغداد درگذشت . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨</span>). زرکلی بنقل از ابن ندیم وفات او را به سال <span class=\"hlight\" dir=\"rtl\">٢٢٨</span> هَ . ق . نوشته است .<br /></font></div>'),
(181195, 'عتت', '<span class=\"hlight\">عتت .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (ع اِمص ) درشتی در سخن . (منتهی الارب ). غلظت در گفتار و جز آن . (اقرب الموارد).<br /></font></div>'),
(181196, 'عتد', '<span class=\"hlight\">عتد.</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (ع ص ) فرس عتد؛ اسب آماده ٔ رفتن . <BR><font color=\"Blue\">◄</font> اسب توانای تمام اندام . (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181197, 'عتد', '<span class=\"hlight\">عتد.</span> <font color=\"DarkGreen\"><b>[ ع َ ت ِ ]</font></b> (ع ص ) رجوع به عَتَد شود.<br /></font></div>'),
(181198, 'عتر', '<span class=\"hlight\">عتر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) استوار کردن نیزه و جز آن . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> لرزیدن و جنبیدن نیزه . (اقرب الموارد) (منتهی الارب ). برخیزانیدن نیزه و برداشتن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> قربان کردن عتیره، گوسپند قربانی جاهلیت را. (منتهی الارب ).<br /></font></div>'),
(181199, 'عتر', '<span class=\"hlight\">عتر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ت ُ ]</font></b> (ع ص، اِ) ج ِ عاتر. (منتهی الارب ).<br /></font></div>'),
(181200, 'عتر', '<span class=\"hlight\">عتر.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) اصل و در مثل است عادت بعترها. در حق شخصی گویند که به سوی خلق قدیم خود بازگردد، عادت الی عترها؛ یعنی به اصل خود بازگشت در حق کسی گویند که بخوی واگذاشته بازگردد. <BR><font color=\"Blue\">◄</font> گیاهی است که پراکنده روید، یا از درختان خرد است . رستنی است مانند مرزنجوش که بدان مداوا کنندو گفته اند درختان خرد است . <BR><font color=\"Blue\">◄</font> نره . <BR><font color=\"Blue\">◄</font> بت . (منتهی الارب ). بت که برای آن قربانی کنند. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ذبیحه . <BR><font color=\"Blue\">◄</font> هرچه ذبح شود. (منتهی الارب ). گویند که در جاهلیت در ماه رجب جهت خدایان خود میکشتند. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> دسته ٔ بیل و جز آن . یا چوب پهن که بیل آهن دوزند و پای بر او نهند وقت زمین کندن . <BR><font color=\"Blue\">◄</font> (مص ) بیهوده گفتن . (اقرب الموارد) (آنندراج ).<br /></font></div>'),
(181201, 'عتر', '<span class=\"hlight\">عتر.</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (ع اِمص ) سختی . شدت . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> توانایی قوت در حیوان . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181202, 'عتران', '<span class=\"hlight\">عتران .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (ع مص ) استوار گردیدن نیزه و جز آن . <BR><font color=\"Blue\">◄</font> لرزیدن و جنبیدن نیزه . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سخت شدن . (اقرب الموارد).<br /></font></div>'),
(181203, 'عترب', '<span class=\"hlight\">عترب .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ]</font></b> (ع اِ) سماق . (اقرب الموارد). تتم که نوعی از بار درخت ترش است و در طعام اندازند. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181204, 'عترت', '<span class=\"hlight\">عترت .</span> <font color=\"DarkGreen\"><b>[ ع ِرَ ]</font></b> (ع اِ) عترة. خویشاوندان و اقارب <span class=\"hlight\">:</span> <br />ما بر اثر عترت پیغمبر خویشیم <br />اولاد زنا بر اثر رأی و هوی اند.<br /><font color=\"Red\">ناصرخسرو.</font><br />پیش خدای نیست شفیعم مگر رسول <br />دارم شفیع پیش رسول آل و عترتش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />و فرزندان و عترت او را خوار و حقیر دارند. (تاریخ قم ).<br /></font></div>'),
(181205, 'عترس', '<span class=\"hlight\">عترس .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع ص ) مردی استوارخلقت گرداندام . تن دار سطبر بندهای اعضا. (منتهی الارب ). الحادر الغلیظ الخلق العظیم الجسیم العبل المفاصل من الناس . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سطبر و بزرگ سینه از ستور. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) شیر بیشه . <BR><font color=\"Blue\">◄</font> خروس . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181206, 'عترس', '<span class=\"hlight\">عترس .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َرْ رَ ]</font></b> (ع ص، اِ) عَترس . رجوع به عَترس شود.<br /></font></div>'),
(181207, 'عترسان', '<span class=\"hlight\">عترسان .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ]</font></b> (ع اِ) خروس . (اقرب الموارد) (منتهی الارب ). رجوع به عترفان شود.<br /></font></div>'),
(181208, 'عترسة', '<span class=\"hlight\">عترسة.</span> <font color=\"DarkGreen\"><b>[ ع َرَ س َ ]</font></b> (ع مص ) سخت گرفتن . <BR><font color=\"Blue\">◄</font> ستم و درشتی نمودن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِمص ) گرفت سخت و درشت . (منتهی الارب ) (آنندراج ) (اقرب الموارد).<br /></font></div>'),
(181209, 'عترفان', '<span class=\"hlight\">عترفان .</span><font color=\"DarkGreen\"><b>[ ع ُ رُ ]</font></b> (ع اِ) خروس . (اقرب الموارد) (منتهی الارب ). رجوع به عترسان شود. <BR><font color=\"Blue\">◄</font> گیاهی است پهن تابستانی . (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181210, 'عترفة', '<span class=\"hlight\">عترفة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ف َ ]</font></b> (ع اِمص ) سختی . (منتهی الارب ).<br /></font></div>'),
(181211, 'عتروف', '<span class=\"hlight\">عتروف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) رجوع به عتریف شود.<br /></font></div>'),
(181212, 'عتری', '<span class=\"hlight\">عتری .</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ]</font></b>(اِخ ) در اصطلاح رجال لقب حیابن علی و عمروبن علی و صندل بن علی و جز اوست . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨</span>).<br /></font></div>'),
(181213, 'عتریس', '<span class=\"hlight\">عتریس .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) سخت سرکش . خشمناک . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) غول نر. <BR><font color=\"Blue\">◄</font> بلا. <BR><font color=\"Blue\">◄</font> (اِمص ) سختی . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181214, 'عتریف', '<span class=\"hlight\">عتریف .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) پلید. بدکار. بیباک . دلاور. کارگذار ستم کار درشت سخت . <BR><font color=\"Blue\">◄</font> شتر استواراندام . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181215, 'عتریفة', '<span class=\"hlight\">عتریفة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ف َ ]</font></b> (ع ص ) ماده شتر استوار و توانا. ماده شتر کم شیر. <BR><font color=\"Blue\">◄</font> گرامی که از زجر باک ندارد. (اقرب الموارد) (منتهی الارب ). گرامی ذات و بی باک . (آنندراج ).<br /></font></div>'),
(181216, 'عتش', '<span class=\"hlight\">عتش .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) خم دادن و دوتاکردن . (منتهی الارب ) (آنندراج ). ظاهراً مصحف عنش است . (اقرب الموارد از تاج العروس ). رجوع به عنش شود.<br /></font></div>'),
(181217, 'عتص', '<span class=\"hlight\">عتص .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (ع مص ) فعل آن نیامده اما بقول ایشان بمعنی اعتیاص است که دشوار شدن باشد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181218, 'عتعت', '<span class=\"hlight\">عتعت .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (ع اِ) بزغاله ٔ نر. (اقرب الموارد) <BR><font color=\"Blue\">◄</font> (ص ) سخت توانا. (اقرب الموارد) (منتهی الارب ). مرد درازبالا تمام اندام . <BR><font color=\"Blue\">◄</font> مرد دراز مضطرب خلقت .(اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) کلمه ای است که بدان بزغاله را خوانند. (منتهی الارب ).<br /></font></div>'),
(181219, 'عتعت', '<span class=\"hlight\">عتعت .</span> <font color=\"DarkGreen\"><b>[ ع ُ ع ُ ]</font></b> (ع ص، اِ) رجوع به عَتعَت شود به همه ٔ معانی آن .<br /></font></div>'),
(181220, 'عتعتة', '<span class=\"hlight\">عتعتة.</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ت َ ]</font></b> (ع مص ) خواندن بزغاله را به کلمه ٔ عت عت . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) دیوانگی . (اقرب الموارد) (آنندراج ).<br /></font></div>'),
(181221, 'عتف', '<span class=\"hlight\">عتف .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) پاره ای از شب، یقال مضی عتف من اللیل و عدف ؛ أی قطعة منه . (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181222, 'عتف', '<span class=\"hlight\">عتف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) برکندن موی . (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181223, 'عتق', '<span class=\"hlight\">عتق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) آزاد گردیدن بنده از بندگی . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> در اصطلاح شرع قوه ای است حکمیه که برای آدمی حاصل میشود جهت اثبات حق او در اینکه از بردگی و غلامی دیگران بیرون آید و آزاد شود و بالجمله قطع علاقه ٔ مملوکیت آدمی است . (جامع الرموز) (از تعریفات ). در اصطلاح فقه آزاد کردن برده است و یکی از کتب فقه بهمین نام موسوم است .در شرایع آرد: آزاد کردن بردگان مورد اتفاق همه ٔ فقهاست حضرت رسول و ائمه ٔ اطهار مردم را بدین امر تشویق و ترغیب فرموده اند و در روایت است که هر کس برده ای را آزاد کند خدای تعالی به ازاء آن هر عضوی از اعضای او را از آتش جهنم آزاد گرداند و برده شدن را مخصوص کفار حربی دانسته است نه کفار ذمی که بشرایط ذمه عمل کنند. رجوع به عبد و شرایع ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span> شود. <BR><font color=\"Blue\">◄</font> (اِمص ) کَرَم . (اقرب الموارد). جوانمردی و مردمی .(منتهی الارب ). <BR><font color=\"Blue\">◄</font> جمال . <BR><font color=\"Blue\">◄</font> شرف . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آزادی .(اقرب الموارد). آزادی و آزادمردی . (منتهی الارب ).<br /></font></div>'),
(181224, 'عتق', '<span class=\"hlight\">عتق .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (ع مص ) کهنه شدن . (اقرب الموارد).<br /></font></div>'),
(181225, 'عتق', '<span class=\"hlight\">عتق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ عتیق و عاتق . (اقرب الموارد).<br /></font></div>'),
(181226, 'عتق', '<span class=\"hlight\">عتق .</span> <font color=\"DarkGreen\"><b>[ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ]</font></b> (ع اِمص ) قِدَم و گفته اند عتق مخصوص بی جان است چون شراب و خرما و قدم به جاندار و بی جان هر دو گفته شود. (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181227, 'عتق', '<span class=\"hlight\">عتق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ت ُ ]</font></b> (ع اِ) درختی است که از آن کمان سازند. (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181228, 'عتق', '<span class=\"hlight\">عتق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) جوان گردیدن دختر. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بیرون شدن دختر از خدمت پدر و مادر و از مالکیت شوی . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گرامی شدن مرد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نیک و تازه گردیدن بشره سپس درشتی و خشکی آن . <BR><font color=\"Blue\">◄</font> واجب شدن سوگند بر کسی . <BR><font color=\"Blue\">◄</font> کهنه گردیدن و نیکو شدن شراب . <BR><font color=\"Blue\">◄</font> درگذشتن اسب از دیگران . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> دیرینه گشتن و نیکو گردیدن چیزی . (منتهی الارب ). نیکو گردیدن چیزی . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گزیدن چیزی را به دندان . <BR><font color=\"Blue\">◄</font> نیکو گردانیدن مال . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آزاد شدن بنده از بندگی . (اقرب الموارد). آزاد گردیدن . (منتهی الارب ). بابی از ابواب فقه اسلامی است که مقررات و قوانین بردگی و برده فروشی در اسلام در آن جمع شده است .<br /></font></div>'),
(181229, 'عتقی', '<span class=\"hlight\">عتقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) ابن قاسم بن خالدبن جناده ٔ عتقی . فقیهی مالکی و از علماء اواخر قرن دوم هجری است . از امام مالک و جز او فقه آموخت و بیست سال دردرس مالک حاضر بود. پس از مرگ مالک به تدریس پرداخت . وی به سال <span class=\"hlight\" dir=\"rtl\">١٩٥</span> هَ . ق . به مصر درگذشت و در خارج باب قرفه صغری مدفون است . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨</span>).<br /></font></div>'),
(181230, 'عتقیون', '<span class=\"hlight\">عتقیون .</span> <font color=\"DarkGreen\"><b>[ ع ُ ت َ قی یو ]</font></b> (اِخ ) منسوب اند به عُتَقاء، یعنی عبداﷲبن بشر صحابی و حارث بن سعید محدث و عبدالرحمان بن فضل قاضی و عبدالرحمن بن فضل بن قاسم صاحب مالک . و مر او راست : مسجد عتقاء به مصر. و در حدیث است که طلقاء از قریش اند و عتقاء از ثقیف بعض آنان دوستان بعض دیگرند در دنیا و آخرت و نیزعتقاء گروهی است فراهم آمده از جحر حمیر و سعد العشیرة و از بنی کنانه مضر و از غیر آن . (منتهی الارب ).<br /></font></div>'),
(181231, 'عتل', '<span class=\"hlight\">عتل .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (ع ص، اِ) ج ِ عَتلة. <BR><font color=\"Blue\">◄</font> (مص ) شتافتن به سوی بدی . (اقرب الموارد).<br /></font></div>'),
(181232, 'عتل', '<span class=\"hlight\">عتل .</span> <font color=\"DarkGreen\"><b>[ ع َ ت ِ ]</font></b> (ع ص ) مرد شتابنده به بدی . (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181233, 'عتل', '<span class=\"hlight\">عتل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) برداشتن و سخت کشیدن چیزی را. (از منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناقه را کشیدن . (اقرب الموارد) (منتهی الارب ) (تاج العروس ) (تاج المصادر).<br /></font></div>'),
(181234, 'عتل', '<span class=\"hlight\">عتل .</span> <font color=\"DarkGreen\"><b>[ ع ُ ت ُل ل ]</font></b> (ع ص ) بسیارخوار سرکش . (منتهی الارب ) (آنندراج ). الاکول المنوع . (اقرب الموارد). پرخور. <BR><font color=\"Blue\">◄</font> درشت خوی سخت گوی سخت آزار. (منتهی الارب ) (آنندراج ) (ترجمان علامه ) <span class=\"hlight\">:</span> عُتل بعد ذلک زنیم . (قرآن <span class=\"hlight\" dir=\"rtl\">١٣/٦٨</span>). <BR><font color=\"Blue\">◄</font> نیزه ٔ درشت و سطبر. (اقرب الموارد) (منتهی الارب ) (آنندراج ) (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> سخت هر چیزی . (اقرب الموارد).<br /></font></div>'),
(181235, 'عتلة', '<span class=\"hlight\">عتلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ل َ ]</font></b> (ع ص، اِ) کلوخ کلان که از زمین برکنده باشند. (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> آهنی است مانند سر تبر. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> چوب دستی بزرگ از آهن سرپهن که بدان دیوار بشکنند. (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> برمای درودگران . تیشه ٔ چوب کاو. (اقرب الموارد) (منتهی الارب ). عمود آهنین درودگر و چوب کاو و چوب سوراخ کن . (شرح قاموس ). عمود آهنین . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> شتر ماده که هرگز آبستن نشود. <BR><font color=\"Blue\">◄</font> چوب دستی سطبر درشت . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> کمان فارسی . ج، عَتَل . (اقرب الموارد) (منتهی الارب ) (آنندراج ) (مهذب الاسماء).<br /></font></div>'),
(181236, 'عتم', '<span class=\"hlight\">عتم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) نام اسبی است . (منتهی الارب ).<br /></font></div>'),
(181237, 'عتم', '<span class=\"hlight\">عتم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) نام مردی است . (منتهی الارب ).<br /></font></div>'),
(181238, 'عتم', '<span class=\"hlight\">عتم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) حصنی است در کوه و ضرة به یمن . (معجم البلدان ).<br /></font></div>'),
(181239, 'عتم', '<span class=\"hlight\">عتم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ت ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ]</font></b> (ع اِ) زیتون دشتی . (اقرب الموارد) (منتهی الارب ) (آنندراج ) (تاج العروس ).<br /></font></div>'),
(181240, 'عتم', '<span class=\"hlight\">عتم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) بازایستادن از کاری بعد از گذشتن در آن . (اقرب الموارد) (منتهی الارب ) (آنندراج ) <BR><font color=\"Blue\">◄</font> بازماندن از کاری که اراده ٔ آن را داشت . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> دیر نمودن در مهمانی . <BR><font color=\"Blue\">◄</font> گذشتن پاره ای از شب . <BR><font color=\"Blue\">◄</font> کندن موی را. <BR><font color=\"Blue\">◄</font> دوشیده شدن شتران وقت عشاء. (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181241, 'عتمة', '<span class=\"hlight\">عتمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ م َ ]</font></b> (ع اِ) سه یک اول از شب بعد از غیبت شفق . (اقرب الموارد) (منتهی الارب ). و گفته شده است وقت نماز عشاء. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> باقی مانده ٔ شیر که بعد از دوشیدن فرودآرد به پستان یا شیر که وقت عتمه فراهم آرد. (منتهی الارب ). بقیة اللبن یفیق بها النعم تلک الساعة. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> تاریکی شب . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (مص ) بازگشتن شتران از چراگاه وقت شام . (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181242, 'عتمة', '<span class=\"hlight\">عتمة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ت ُ م َ ]</font></b> (اِخ ) حصنی است در کوههای وصاب از نواحی زبید. (معجم البلدان ).<br /></font></div>'),
(181243, 'عتن', '<span class=\"hlight\">عتن .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) سخت راندن کسی را به سوی زندان . (اقرب الموارد) (منتهی الارب ) (آنندراج ) (لسان العرب ) (تاج المصادر).<br /></font></div>'),
(181244, 'عتن', '<span class=\"hlight\">عتن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ت ُ ]</font></b> (ع ص، اِ) ج ِ عاتن و عَتون .<br /></font></div>'),
(181245, 'عته', '<span class=\"hlight\">عته .</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُت ْه ْ ]</font></b> (ع مص ) سبک عقل شدن . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کم عقل شدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> فاقد خرد گشتن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مدهوش گشتن . (منتهی الارب ). و گفته اند مدهوش شدن از جز دیوانگی . (اقرب الموارد). معتوه شدن . <BR><font color=\"Blue\">◄</font> رفتن خرد. (منتهی الارب ) (آنندراج ) (تاج المصادر). <BR><font color=\"Blue\">◄</font> آزمند علم گردیدن . (اقرب الموارد) (لسان العرب ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> حریص شدن بر اذیت کسی . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> حریص شدن بر حکایت و تقلید کردن کلام کسی . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> در اصطلاح علمای اصول عبارت است از اختلال در عقل بنحوی که گفتار صاحب آن بر یک سیاق نباشد گاه سخنان او بر روش سخنان دانایان و گاه بر طریق گفتار دیوانگان باشد. (از کشاف ).<br /></font></div>'),
(181246, 'عتو', '<span class=\"hlight\">عتو.</span> <font color=\"DarkGreen\"><b>[ ع ُ ت ُوو ]</font></b> (ع مص ) بزرگ منشی نمودن و از حد درگذشتن . (اقرب الموارد) (لسان العرب ) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> به غایت پیری رسیدن . (ترجمان علامه ). <BR><font color=\"Blue\">◄</font> سرکشی کردن . (لسان العرب ) (منتهی الارب ). نافرمانی . (تاج المصادر).<br /></font></div>'),
(181247, 'عتوب', '<span class=\"hlight\">عتوب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) آنکه در وی عتاب اثر نکند. (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181248, 'عتود', '<span class=\"hlight\">عتود.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) درخت کنار. (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> درخت بزرگ ریگستانی . (منتهی الارب ) (آنندراج ). طلح . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) بزغاله ٔ یکساله . (اقرب الموارد) <span class=\"hlight\">:</span> بچه گوسفند... چون قویتر گردد عریض گویند پس عتود. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١٧٨</span>). <BR><font color=\"Blue\">◄</font> بزغاله که علف خوار باشد. (اقرب الموارد).<br /></font></div>'),
(181249, 'عتود', '<span class=\"hlight\">عتود.</span> <font color=\"DarkGreen\"><b>[ ع َت ْ تو ]</font></b> (اِخ ) کوهی است بین سیاله و ملل و گفته شده است کوهی است سیاه از جانب نقیع.<br /></font></div>'),
(181250, 'عتود', '<span class=\"hlight\">عتود.</span> <font color=\"DarkGreen\"><b>[ ع َت ْ وَ ]</font></b> (اِخ ) موضعی است به حجاز. عمرانی گوید <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ]</font></b> روایت شده است و آبی است کنانه را.<br /></font></div>'),
(181251, 'عتور', '<span class=\"hlight\">عتور.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص )فرج گشاده از تیزی شهوت . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181252, 'عتور', '<span class=\"hlight\">عتور.</span> <font color=\"DarkGreen\"><b>[ ع ِت ْ وَ ]</font></b> (اِخ ) وادیی است . (منتهی الارب ).<br /></font></div>'),
(181253, 'عتول', '<span class=\"hlight\">عتول .</span> <font color=\"DarkGreen\"><b>[ ع ِت ْ وَ ]</font></b> (ع ص، اِ) آن که او را از زنان غنا نباشد. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آهو. (منتهی الارب ).<br /></font></div>'),
(181254, 'عتوم', '<span class=\"hlight\">عتوم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) شتر ماده که جز وقت شبانگاه شیر ندهد و دوشیده نشود. (اقرب الموارد) (مهذب الاسماء) (منتهی الارب ).<br /></font></div>'),
(181255, 'عتون', '<span class=\"hlight\">عتون .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) توانا. (منتهی الارب ).<br /></font></div>'),
(181256, 'عتوک', '<span class=\"hlight\">عتوک .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) رجوع به عَتک شود در همه ٔ معانی .<br /></font></div>'),
(181257, 'عتک', '<span class=\"hlight\">عتک .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (ع مص ) خواهش نمودن و میل نمودن به سوی موضعی . <BR><font color=\"Blue\">◄</font> بزرگ ومهتر گردیدن زن . <BR><font color=\"Blue\">◄</font> استوار و راست کردن مقصد و مراد خود را. <BR><font color=\"Blue\">◄</font> سرخ شدن کمان از کهنگی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نیک ترش گردیدن شیر و نبیذ. <BR><font color=\"Blue\">◄</font> خشک گردیدن کمیز برران ناقه . <BR><font color=\"Blue\">◄</font> چفسیدن بوی خوش به کسی . <BR><font color=\"Blue\">◄</font> سیاست و حفاظت بلد را. <BR><font color=\"Blue\">◄</font> دو تا داشتن دست را بر سینه . <BR><font color=\"Blue\">◄</font> پاییدن و ثبات ورزیدن بر دلیل خود. <BR><font color=\"Blue\">◄</font> زدن کسی را و از زدن او باز نایستادن . (منتهی الارب ).<br /></font></div>'),
(181258, 'عتک', '<span class=\"hlight\">عتک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) وادیی است به یمامه در دیار بنی عوف بن کعب بن سعدبن زید مناةبن تمیم . (از معجم البلدان ).<br /></font></div>'),
(181259, 'عتک', '<span class=\"hlight\">عتک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) دهر. (اقرب الموارد) (منتهی الارب ). یقال مضی علیه عتک ؛ أی دهر. (اقرب الموارد).<br /></font></div>'),
(181260, 'عتک', '<span class=\"hlight\">عتک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) حمله نمودن در جنگ . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> آهنگ گَزیدن کردن اسب . <BR><font color=\"Blue\">◄</font> دوتا داشتن دست را برسینه . (اقرب الموارد) (منتهی الارب ) (تاج العروس ).<br /></font></div>'),
(181261, 'عتکان', '<span class=\"hlight\">عتکان .</span> <font color=\"DarkGreen\"><b>[ ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ]</font></b> (اِخ ) نام محلی است که در شعر زهیر آمده است . (معجم البلدان ).<br /></font></div>'),
(181262, 'عتکی', '<span class=\"hlight\">عتکی .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ کی ی ]</font></b> (ص نسبی ) منسوب است به بطن عتک از اَزد. (سمعانی ) (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181263, 'عتی', '<span class=\"hlight\">عتی .</span> <font color=\"DarkGreen\"><b>[ ع َت ْی ْ ]</font></b> (ع مص ) بزرگ منشی کردن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> درگذشتن از حد. (منتهی الارب ).<br /></font></div>'),
(181264, 'عتی', '<span class=\"hlight\">عتی .</span> <font color=\"DarkGreen\"><b>[ ع ُ تی ی ]</font></b>(ع ص، اِ) ج ِ عات . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181265, 'عتی', '<span class=\"hlight\">عتی .</span> <font color=\"DarkGreen\"><b>[ع َ تا ]</font></b> (ع مص ) عُتُوّ. (قطرالمحیط) (اقرب الموارد). رجوع به عتو و عتی <font color=\"DarkGreen\"><b>[ ع ِ ی ی ]</font></b> و <font color=\"DarkGreen\"><b>[ ع ُ ی ی ]</font></b> شود.<br /></font></div>'),
(181266, 'عتی', '<span class=\"hlight\">عتی .</span> <font color=\"DarkGreen\"><b>[ ع َ تی ی ]</font></b> (ع ص ) متکبر. درگذرنده از حد. (منتهی الارب ).<br /></font></div>'),
(181267, 'عتی', '<span class=\"hlight\">عتی .</span> <font color=\"DarkGreen\"><b>[ ع َت ْ تا ]</font></b> (ع حرف )لغتی است در حَتّی . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181268, 'عتی', '<span class=\"hlight\">عتی .</span> <font color=\"DarkGreen\"><b>[ ع ِتی ی <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ تی ی ]</font></b> (ع مص ) از حد درگذشتن . (اقرب الموارد) (منتهی الارب ) (آنندراج ) (تاج المصادر). <BR><font color=\"Blue\">◄</font> بزرگ منشی کردن . (اقرب الموارد) (منتهی الارب ) (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> به غایت پیری رسیدن . (تاج المصادر) (غیاث اللغات ). کلانسال شدن و پشت دو تا کردن <span class=\"hlight\">:</span> و قد بلغت من الکبر عتیاً. (قرآن <span class=\"hlight\" dir=\"rtl\">٨/١٩</span>). <BR><font color=\"Blue\">◄</font> نافرمانی کردن . (تاج المصادر). در منتهی الارب بفتح و ضم اول سرکشی کردن . (منتهی الارب ).<br /></font></div>'),
(181269, 'عتیب', '<span class=\"hlight\">عتیب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )پدر قبیله ای است از یمن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181270, 'عتیب', '<span class=\"hlight\">عتیب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِمص ) ممال ِ عتاب <span class=\"hlight\">:</span> <br />در یک سخن آن همه عتیبش بین <br />در یک نظر آن همه فریبش بین .<br /> <font color=\"Red\">خاقانی (دیوان چ سجادی ص <span class=\"hlight\" dir=\"rtl\">٦٥٤</span>).</font><br />خواجه کز مهر با شکیب آمد<br />باسهی سرو در عتیب آمد.<br /> <font color=\"Red\">نظامی .</font><br />رومیانه روی دارد زنگیانه زلف و خال <br />و آن کمان ابروانش بین که باشد پر عتیب .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(181271, 'عتیبة', '<span class=\"hlight\">عتیبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع ص ) کم خیر. (منتهی الارب ) (آنندراج ) (اقرب الموارد).<br /></font></div>'),
(181272, 'عتید', '<span class=\"hlight\">عتید.</span> <font color=\"DarkGreen\"><b>[ ع ُ ت َ ]</font></b> (اِخ ) موضعی است . (منتهی الارب ). موضعی است به یمامه . (معجم البلدان ).<br /></font></div>'),
(181273, 'عتید', '<span class=\"hlight\">عتید.</span> <font color=\"DarkGreen\"><b>[ ع َ ی َ ]</font></b> (اِخ ) موضعی است . (منتهی الارب ).<br /></font></div>'),
(181274, 'عتید', '<span class=\"hlight\">عتید.</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ضرار. شاعری است . (منتهی الارب ).<br /></font></div>'),
(181275, 'عتید', '<span class=\"hlight\">عتید.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) حاضر و آماده . (از اقرب الموارد) (ترجمان عادل بن علی ) (منتهی الارب ) (آنندراج ). حاضر و مهیا. (غیاث اللغات ) <span class=\"hlight\">:</span> و قال قرینه هذا ما لدی عتید. (قرآن <span class=\"hlight\" dir=\"rtl\">٢٣/٥٠</span>).<br />گر بدانی که شقیی یا سعید<br />آن بود بهتر ز هر فکر عتید.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(181276, 'عتیق', '<span class=\"hlight\">عتیق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) آزادشده . ج، عُتُق، عُتقاء. (منتهی الارب ). بنده ٔ آزاد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> قدیم از هر چیزی و گویند رجل عتیق ؛ یعنی قدیم . (اقرب الموارد از ابوعبید). <BR><font color=\"Blue\">◄</font> بهترین از هر چیزی . (اقرب الموارد) <BR><font color=\"Blue\">◄</font> گرامی . آزاد برگزیده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مرد نیکوروی تازه رخسار بعد خشونت و درشتی . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">البیت العتیق </span> ؛ کعبه، چه آن نخستین خانه است که در زمین بنا شد.یا از آن جهت که از جبابره یا حبشه یا عَرق آزاد است یا آنکه آزاد است و کس مالک نشود آنرا. (منتهی الارب ).<br /><BR><font color=\"Blue\">◄</font> (اِ) خرمابن که نخله ٔ او بار نیفشاند. <BR><font color=\"Blue\">◄</font> خرما. علم است آنرا. <BR><font color=\"Blue\">◄</font> پیه . <BR><font color=\"Blue\">◄</font> می . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> می سیکی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شیر. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181277, 'عتیق', '<span class=\"hlight\">عتیق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) دیرینه و کهنه . (اقرب الموارد) (از آنندراج ). <BR><font color=\"Blue\">◄</font> آزاد. (اقرب الموارد) (منتهی الارب ) (آنندراج ). ج، عُتُق، عُتقاء، یقال عبد عتیق و امة عتیق .<br /></font></div>'),
(181278, 'عتیق', '<span class=\"hlight\">عتیق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) لقب ابوبکربن ابی قحافه است . رجوع به ابوبکر شود.<br /></font></div>'),
(181279, 'عتیق', '<span class=\"hlight\">عتیق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ت َ ]</font></b> (اِخ ) ابن احمدبن حامد. محدث است .<br /></font></div>'),
(181280, 'عتیق', '<span class=\"hlight\">عتیق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ت َ ]</font></b> (اِخ ) ابن عامربن سبیع. محدث است . (منتهی الارب ).<br /></font></div>'),
(181281, 'عتیق', '<span class=\"hlight\">عتیق .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن عبداﷲ مصری . محدث است . (منتهی الارب ).<br /></font></div>'),
(181282, 'عتیق', '<span class=\"hlight\">عتیق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ت َ ]</font></b> (اِخ ) ابن محمد جرشی . محدث است . (منتهی الارب ).<br /></font></div>'),
(181283, 'عتیق', '<span class=\"hlight\">عتیق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن موسی . محدث است . (منتهی الارب ).<br /></font></div>'),
(181284, 'عتیق', '<span class=\"hlight\">عتیق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هشام . محدث است . (منتهی الارب ).<br /></font></div>'),
(181285, 'عتیق', '<span class=\"hlight\">عتیق .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یعقوب . محدث است . (منتهی الارب ).<br /></font></div>'),
(181286, 'عتیل', '<span class=\"hlight\">عتیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) تشنه . (غیاث اللغات از لطائف ). <BR><font color=\"Blue\">◄</font> مزدور. (مهذب الاسماء). مزدور و خادم . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> داء عتیل، شدید؛ بیماری سخت . (اقرب الموارد).<br /></font></div>'),
(181287, 'عتیک', '<span class=\"hlight\">عتیک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) روز سخت گرم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سرخ از کهنگی . (اقرب الموارد).<br /></font></div>'),
(181288, 'عتیک', '<span class=\"hlight\">عتیک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن تعلبةبن الدؤلی . از بکر از عدنانیه جد جاهلی است . نسبت بدو عتکی است از فرزندان او محکم الیمامة. (از اعلام زرکلی ).<br /></font></div>'),
(181289, 'عتیک', '<span class=\"hlight\">عتیک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) موضعی است . (معجم البلدان ).<br /></font></div>'),
(181290, 'عتیکیة', '<span class=\"hlight\">عتیکیة.</span> <font color=\"DarkGreen\"><b>[ ع َ کی ی َ ]</font></b> (اِخ ) محلی است به بغداد از جانب غربی بین حربیة و باب البصرة که اکنون ویرانه است .<br /></font></div>'),
(181291, 'عث', '<span class=\"hlight\">عث .</span> <font color=\"DarkGreen\"><b>[ ع َث ث ]</font></b> (ع مص ) خوردن مته پشم را و درافتادن در آن . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ستیهیدن . (منتهی الارب ). الحاح . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گزیدن مار کسی را. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> برگرداندن کلام را بر کسی یا سرزنش کردن او را. (اقرب الموارد).<br /></font></div>'),
(181292, 'عث', '<span class=\"hlight\">عث .</span> <font color=\"DarkGreen\"><b>[ ع ُث ث ]</font></b> (ع ص ) هو عث مال ؛ او تباه کننده ٔ شتران است . (منتهی الارب ).<br /></font></div>'),
(181293, 'عث', '<span class=\"hlight\">عث .</span> <font color=\"DarkGreen\"><b>[ ع ِث ث ]</font></b> (ع اِ) افعی که افعی دیگر را خورد. ج، عِثاث . (اقرب الموارد).<br /></font></div>'),
(181294, 'عثاث', '<span class=\"hlight\">عثاث .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ترنم در غنا. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ج ِ عِث ّ. رجوع بدان کلمه شود.<br /></font></div>'),
(181295, 'عثاجل', '<span class=\"hlight\">عثاجل .</span> <font color=\"DarkGreen\"><b>[ ع ُ ج ِ ]</font></b> (ع ص ) بزرگ شکم . (اقرب الموارد) (منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(181296, 'عثار', '<span class=\"hlight\">عثار.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِمص ) بدی . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) ناخوش آیند. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (مص ) شکوخیدن . بسردرافتادن . (منتهی الارب ) (غیاث اللغات ) <span class=\"hlight\">:</span> <br />ماه چون شد بدر آمد بی عثار<br />شاه پیلان شب به سوی چشمه سار.<br /> <font color=\"Red\">مولوی .</font><br />هر که آخربین تر از مسعودوار<br />نَبْوَدَش هر دم بره رفتن عثار.<br /> <font color=\"Red\">مولوی .</font><br />هر قدم من از سر بینش نهم <br />از عثار و اوفتادن وارهم .<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> به روی درافتادن و خوار گردیدن . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181297, 'عثار', '<span class=\"hlight\">عثار.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) جای هلاک و بدی . (منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(181298, 'عثاری', '<span class=\"hlight\">عثاری .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ج، عثران . (اقرب الموارد).<br /></font></div>'),
(181299, 'عثاری', '<span class=\"hlight\">عثاری .</span> <font color=\"DarkGreen\"><b>[ ع ُ را ]</font></b> (اِخ ) وادیی است . (معجم البلدان ). رودباری است . (منتهی الارب ).<br /></font></div>'),
(181300, 'عثاعث', '<span class=\"hlight\">عثاعث .</span> <font color=\"DarkGreen\"><b>[ ع َ ع ِ ]</font></b> (اِخ ) کوههای کوچک سیاهی است . چپ عرائس . (معجم البلدان ).<br /></font></div>'),
(181301, 'عثاعث', '<span class=\"hlight\">عثاعث .</span> <font color=\"DarkGreen\"><b>[ ع َ ع ِ ]</font></b> (ع ص، اِ) ج ِ عَثعَث . (منتهی الارب ). رجوع به عثعَث شود.<br /></font></div>'),
(181302, 'عثال', '<span class=\"hlight\">عثال .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) وادیی است به سرزمین جذام . (معجم البلدان ). پشته ای است در دشت یا رودباری است در زمین جذام . (منتهی الارب ).<br /></font></div>'),
(181303, 'عثالط', '<span class=\"hlight\">عثالط.</span> <font color=\"DarkGreen\"><b>[ ع ُ ل ِ ]</font></b> (ع ص ) شیر سطبر و دفزک . (منتهی الارب ) (اقرب الموارد) (ناظم الاطباء).<br /></font></div>'),
(181304, 'عثامة', '<span class=\"hlight\">عثامة.</span> <font color=\"DarkGreen\"><b>[ ع ُ م َ ]</font></b> (اِخ ) ابن قیس صحابی است . (منتهی الارب ).<br /></font></div>'),
(181305, 'عثان', '<span class=\"hlight\">عثان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) موضعی است مذکور در کتاب بنی کنانة. (معجم البلدان ).<br /></font></div>'),
(181306, 'عثان', '<span class=\"hlight\">عثان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) غبار. <BR><font color=\"Blue\">◄</font> دود. (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181307, 'عثانة', '<span class=\"hlight\">عثانة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ن َ ]</font></b> (اِخ ) آبی است مر جذیمه را. (منتهی الارب ) (معجم البلدان ).<br /></font></div>'),
(181308, 'عثانین', '<span class=\"hlight\">عثانین .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عُثنون . (منتهی الارب ) (ناظم الاطباء). و رجوع به عثنون شود.<br /></font></div>'),
(181309, 'عثاکل', '<span class=\"hlight\">عثاکل .</span> <font color=\"DarkGreen\"><b>[ ع َ ک ِ ]</font></b> (ع اِ) ج ِعُثکول و عُثکولة و عِثکال . رجوع بدان کلمات شود.<br /></font></div>'),
(181310, 'عثاکیل', '<span class=\"hlight\">عثاکیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عُثکول و عُثکولة و عثکال . رجوع بدان کلمات شود.<br /></font></div>'),
(181311, 'عثج', '<span class=\"hlight\">عثج .</span> <font color=\"DarkGreen\"><b>[ ع َث َ ]</font></b> (ع مص، اِ) به همه ٔ معانی رجوع به عَثج شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(181312, 'عثج', '<span class=\"hlight\">عثج .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) همیشگی نمودن بر اندک اندک نوشیدن چیزی . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) گروه مسافران، مقلوب ثعج . (منتهی الارب ). گروه مردم . <BR><font color=\"Blue\">◄</font> پاره ای از شب . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181313, 'عثجج', '<span class=\"hlight\">عثجج .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b>(ع اِ) گروه بسیار. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181314, 'عثجل', '<span class=\"hlight\">عثجل .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ع ص ) بزرگ شکم . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> فراخ و سطبر از مشک و خنور. (منتهی الارب ). الواسع الضخم من الاوعیة و الاسقیة و نحوها. (اقرب الموارد).<br /></font></div>'),
(181315, 'عثجلة', '<span class=\"hlight\">عثجلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ل َ ]</font></b> (ع مص ) گران بودن . گران برخاستن بر کسی از نهایت پیری یا مرض . (منتهی الارب ).<br /></font></div>'),
(181316, 'عثجلیة', '<span class=\"hlight\">عثجلیة.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ لی ی َ ]</font></b> (اِخ ) زمینی است . (منتهی الارب ).<br /></font></div>'),
(181317, 'عثجلیة', '<span class=\"hlight\">عثجلیة.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ لی ی َ ]</font></b> (اِخ ) آبی است به وادی سُلَیع از سرزمین یمامه مر بنی سُحَیم را. (معجم البلدان ) (منتهی الارب ).<br /></font></div>'),
(181318, 'عثر', '<span class=\"hlight\">عثر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) موضعی است به تهامه . (منتهی الارب ) (معجم البلدان ).<br /></font></div>'),
(181319, 'عثر', '<span class=\"hlight\">عثر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) دروغ گفتن . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شکوخیدن و بسر درافتادن . (منتهی الارب ) (اقرب الموارد). یقال عثر فی ثوبه و عثر به فرسه فسقط. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خوار گردیدن سخت . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> جهیدن رگ . (منتهی الارب ). زدن رگ . (اقرب الموارد).<br /></font></div>'),
(181320, 'عثر', '<span class=\"hlight\">عثر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) کشت دشتی که از باران آب خورد. (منتهی الارب ). آنچه آسمان آن را سیراب سازد از درختان و کشت . (اقرب الموارد).<br /></font></div>'),
(181321, 'عثر', '<span class=\"hlight\">عثر.</span> <font color=\"DarkGreen\"><b>[ ع َ ث َ ]</font></b> (ع اِ) عَثر. رجوع به ماده ٔ قبل شود. <BR><font color=\"Blue\">◄</font> دروغ . (اقرب الموارد).<br /></font></div>'),
(181322, 'عثر', '<span class=\"hlight\">عثر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) عقاب . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دروغ . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) دروغگوی . (منتهی الارب ).<br /></font></div>'),
(181323, 'عثر', '<span class=\"hlight\">عثر.</span> <font color=\"DarkGreen\"><b>[ع َث ْ ث َ ]</font></b> (اِخ ) بیشه ای است شیرناک یا موضعی است . (منتهی الارب ). ابوبکر همدانی گوید: عثر شهری است به یمن میان آن و مکه ده روز راه است . (معجم البلدان ).<br /></font></div>'),
(181324, 'عثرات', '<span class=\"hlight\">عثرات .</span> <font color=\"DarkGreen\"><b>[ ع َ ث َ ]</font></b> (ع اِ) ج ِ عثرة. لغزش . (از غیاث اللغات ). <BR><font color=\"Blue\">◄</font> خطا و سهو. (ناظم الاطباء) <span class=\"hlight\">:</span> تا در حضرت پادشاه عثرات ایشان را شفیع شد. (جهانگشای جوینی ). سلطان عفو و اغضا کرد و از عثرات او تجاوز و اغماض واجب داشت . (جهانگشای جوینی ). رجوع به عثرت و عثرة شود.<br /></font></div>'),
(181325, 'عثران', '<span class=\"hlight\">عثران .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) نام موضعی است . (معجم البلدان ).<br /></font></div>'),
(181326, 'عثرب', '<span class=\"hlight\">عثرب .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ]</font></b> (ع اِ) درختی است مانند درخت انار سرشاخ نرم و سرخ دارد همچو ریباس مقشر کرده میخورند، یکی آن عُثرُبة. (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181327, 'عثربة', '<span class=\"hlight\">عثربة.</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ب َ ]</font></b> (ع اِ) یکی عثرب . (منتهی الارب ).<br /></font></div>'),
(181328, 'عثرت', '<span class=\"hlight\">عثرت .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) عثرة. خطا. گناه <span class=\"hlight\">:</span> چنان اقتضاء نمود که رعایت جانب قرابت و مواصلت را به اقالت عثرت عین فرض داند. (جهانگشای جوینی ).<br /></font></div>'),
(181329, 'عثری', '<span class=\"hlight\">عثری .</span> <font color=\"DarkGreen\"><b>[ ع َ ری ی ]</font></b> (اِخ ) یوسف بن ابراهیم عثری از عبدالرزاق بن همام روایت کند و شعیب بن محمد الذراع از وی حدیث دارد. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span>).<br /></font></div>'),
(181330, 'عثری', '<span class=\"hlight\">عثری .</span> <font color=\"DarkGreen\"><b>[ ع َ ری ی ]</font></b> (ص نسبی ) نسبت است به عثر و آن شهری است به یمن .<br /></font></div>'),
(181331, 'عثری', '<span class=\"hlight\">عثری .</span> <font color=\"DarkGreen\"><b>[ ع َ ث َ ری ی ]</font></b> (ع اِ)کشت دشتی که از باران آب خورد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کشت بر آب باران . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> آنچه آسمان آن را سیراب سازد از درختان و کشت . (اقرب الموارد). و منه فی حدیث الزکاة ماکان بعلا او عثریا ففیه العشر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) کسی که نه در طلب دنیا باشد و نه آخرت . (اقرب الموارد). مرد لاابالی که در پس دنیا و آخرت نرود. (منتهی الارب ). و گاه ثاء را تشدید دهند و صواب تخفیف آن است .<br /></font></div>'),
(181332, 'عثعث', '<span class=\"hlight\">عثعث .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (اِخ ) کوهی است به مدینه بنام سُلَیع که بر آن خانه های اسلم بن اقصی است .<br /></font></div>'),
(181333, 'عثعث', '<span class=\"hlight\">عثعث .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (ع اِ) فساد. (اقرب الموارد). تباهی و فساد. (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> نرم از سرین و از زمین . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پشته ٔ بی گیاه . (اقرب الموارد) (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> نام سرودگوی .(منتهی الارب ). <BR><font color=\"Blue\">◄</font> خاک . (اقرب الموارد). ج، عثاعث . <BR><font color=\"Blue\">◄</font> (اِمص ) سختی . (منتهی الارب ).<br /></font></div>'),
(181334, 'عثق', '<span class=\"hlight\">عثق .</span> <font color=\"DarkGreen\"><b>[ ع َ ث َ ]</font></b> (ع اِ) درختی است . (اقرب الموارد) (منتهی الارب ). یکی آن عَثقَه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شارع عام . (منتهی الارب ) (ناظم الاطباء). جاده . (اقرب الموارد).<br /></font></div>'),
(181335, 'عثل', '<span class=\"hlight\">عثل .</span> <font color=\"DarkGreen\"><b>[ ع ُ ث ُ ]</font></b> (ع اِ) ج ِ عَثول . رجوع به عثول شود.<br /></font></div>'),
(181336, 'عثل', '<span class=\"hlight\">عثل .</span> <font color=\"DarkGreen\"><b>[ ع َ ث َ ]</font></b> (ع ص ) بسیار از هر چیزی . (اقرب الموارد) (منتهی الارب ). بسیار و وافر. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> درشت و پرگوشت . (از اقرب الموارد) (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ) چادر پیه بالای روده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پیه تنک بالای شکنبه . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شکنبه ٔ گوسفند. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شکنبه ٔ گوسفند. (منتهی الارب ) (اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (مص ) بسیار و غلیظ و ضخیم شدن . (اقرب الموارد).<br /></font></div>'),
(181337, 'عثل', '<span class=\"hlight\">عثل .</span> <font color=\"DarkGreen\"><b>[ ع َ ث ِ ]</font></b> (ع ص ) بسیار از هر چیزی . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> درشت و پرگوشت . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> غلیظ و ضخم . (اقرب الموارد).<br /></font></div>'),
(181338, 'عثل', '<span class=\"hlight\">عثل .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) بر پا دارنده ٔ شتران و مصلح آن . (منتهی الارب ) بر پا دارنده ٔ شتران و سیاست کننده ٔ آنها. (ناظم الاطباء).<br /></font></div>'),
(181339, 'عثل', '<span class=\"hlight\">عثل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) درست شدن دست شکسته بطور غیرمستوی . (اقرب الموارد).<br /></font></div>'),
(181340, 'عثلب', '<span class=\"hlight\">عثلب .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) نام آبی است مر غطفان را. (معجم البلدان ).<br /></font></div>'),
(181341, 'عثلبة', '<span class=\"hlight\">عثلبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ب َ ]</font></b> (ع مص )گرفتن چوب آتش زنه را از درخت ناشناخته یعنی ندانستن که آتش میدهد یا نه . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> در خاکستر بریان کردن گندم را یا بضرورت کبیده نمودن آن را. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سخت فروبردن آب را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شورانیدن . <BR><font color=\"Blue\">◄</font> پراکنده ساختن . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> تباه کردن .<br /></font></div>'),
(181342, 'عثلط', '<span class=\"hlight\">عثلط.</span> <font color=\"DarkGreen\"><b>[ ع ُ ث َ ل ِ ]</font></b> (ع ص ) شیر سطبر و دفزک . (منتهی الارب ) (اقرب الموارد) (ناظم الاطباء).<br /></font></div>'),
(181343, 'عثلول', '<span class=\"hlight\">عثلول .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) پی گردن اسب که بر آن یال روید. (اقرب الموارد) (ناظم الاطباء).<br /></font></div>'),
(181344, 'عثلیت', '<span class=\"hlight\">عثلیت .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) قلعه ای است به سواحل شام مشهور به حصن احمر. (منتهی الارب ) (معجم البلدان ).<br /></font></div>'),
(181345, 'عثم', '<span class=\"hlight\">عثم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) کژ بسته شدن استخوان شکسته . یا کژ بسته شدن دست خاصةً. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سست دوختن توشه دان را. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سطبر گردیدن و پوست فراهم آوردن زخم بی آنکه به شود. (منتهی الارب )(از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (ص )استخوان کژ بسته . (منتهی الارب ) (از ناظم الاطباء).<br /></font></div>'),
(181346, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن عمربن موسی التیمی، قاضی و از مردم مدینه است . به سال <span class=\"hlight\" dir=\"rtl\">٧٥</span> هَ . ق . نزد عبدالملک بن مروان رفت و در عهد مروان بن محمد قضاء مدینه را یافت و سپس منصور عباسی او را قضاوت داد و پیش از بناء بغداد با وی در حره بود. و به سال <span class=\"hlight\" dir=\"rtl\">١٤٥</span> هَ . ق . درگذشت . (از اعلام زرکلی ).<br /></font></div>'),
(181347, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن عبدالرحمان بن عثمان شهرزوری ملقب به ابن صلاح . رجوع صلاح در این لغتنامه و اعلام زرکلی شود.<br /></font></div>'),
(181348, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن عبداﷲبن ابراهیم الطرسوسی مکنی به ابوعمرو. قاضی و از کُتّاب ادباء بود. قضاوت معرة النعمان به وی واگذار شد و به سال <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> هَ . ق . به کفر طاب بین حلب و معرة درگذشت . اوراست اخبار الحجاب . (از اعلام زرکلی ).<br /></font></div>'),
(181349, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن عبداﷲبن الحسن الکرمانی مکنی به ابومحمدو معروف به شیخ صفی الدین . عالمی متورع و متبحر بود. به حجاز و عراق مسافرت کرد و با شیخ شهاب الدین سهروردی مصاحبتی داشت . در حدیث و تصوف و کلام و ادبیات وجز آن کتابها نوشته است . او راست : الکنز الخفس من اختیارات الصفی . او <span class=\"hlight\" dir=\"rtl\">١٠٤</span> سال بزیست و <span class=\"hlight\" dir=\"rtl\">٥٠</span> سال در جامع سنقری شیراز خطبه خواند. وی مردی صاحب کشف و فراست بوده و حکایتها از او نقل کنند. (از شدالازار ص <span class=\"hlight\" dir=\"rtl\">٤٠٠</span>).<br /></font></div>'),
(181350, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن عفان بن ابی العاص بن امیة. ملقب به ذوالنورین . سومین از خلفاء راشدین و از عشره ٔ مبشره است . به سال <span class=\"hlight\" dir=\"rtl\">٤٧</span> قبل از هجرت به مکه متولد شد و اندکی پس از بعثت اسلام آورد. وی مردی ثروتمند و از اشراف مکه بود. از کارهای بزرگ او در اسلام مجهز کردن نیمی از «جیش العسرة» است وی سیصد شتر و هزار دینار در این راه داد. پس از عمربن خطاب به سال <span class=\"hlight\" dir=\"rtl\">٢٣</span> هَ . ق .از طریق شورایی که اعضای آن را عمر معین کرد به خلافت رسید. عثمان پس از رسیدن به خلافت تا یک سال والیان عمر را بر کارشان باقی داشت سپس آنان را عزل کرد و بیشتر کسان خود را بجای ایشان فرستاد و معاویة همچنان بر حکومت شام ماند. بدین سبب مورد ملامت عامه ٔ مسلمین واقع شد. رفتار عثمان موجب آزردگی و ناخشنودی مسلمانان شد تا آنجا که گروهی از مردم کوفه و مصر به مدینه رفتند و عزل او را خواستار شدند و عثمان نپذیرفت شورشیان او را در خانه محاصره کردند و مدت محاصره ٔ وی چهل روز طول کشید و سرانجام صبح روز عید اضحی <span class=\"hlight\" dir=\"rtl\">٣٥</span> هَ . ق . به مدینه در خانه اش بقتل رسید. در خلافت عثمان ارمنیه، قفقاز، خراسان، کرمان، سجستان، افریقا و قبرس بتصرف مسلمانان درآمد. در زمان خلافت عثمان برای رفع اختلاف در قراآت مختلف قرآن کریم، بر نسخه ٔ واحدی از بین قرأتها اتفاق نظر حاصل شد و بقیه ٔ نوشته ها معدوم گردید. عثمان مسجدالحرام و مسجد پیغمبر را وسعت داد و در نماز عید خطبه را بر نماز مقدم داشت . وی نخستین کسی است که «شرطه » گرفت . از او نیز در صحیحین <span class=\"hlight\" dir=\"rtl\">١٤٦</span> حدیث نقل شده است . رجوع به طبقات الکبری تألیف ابن سعد و الاصابه و الاعلام زرکلی و کتب تراجم شود.<br /></font></div>'),
(181351, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن علی بن ابی بکربن علی الجبلجیوی (یا جبلجیلوی ) کوه گلوئی ملقب به بهاالدین مکنی به ابوالمحاسن . قاضی شیراز است از عزالدین جماعة حدیث شنید مولدش قبل از قرن هفتم هجری است . نزد لسان الدین نوح بن محمد سمنانی و خطیب شمس الدین مظفربن محمد خطیبی خلخالی فقه آموخت . وی مفتی مذاهب اربعة بود قضاء فارس و نواحی آن را یافت و در مدرسه عضدیه درس میگفت در تبریز با علاءالدین طاوسی و فخرالدین جالردی و شرف الدین طیبی و شمس خطیبی سابق الذکر مصاحبت کرد. از کتب اوست : بیان الفتاوی فی شرح الحاوی، شرح الشامل الصغیر لابن المفسر، شرح المنظومة فی الفرائض، الرسالة البالغة فی الاجتهاد، ایجاز المختصر لابن الحاجب، و او راست : اساتید عالیه . وی به سال <span class=\"hlight\" dir=\"rtl\">٧٨٢</span> هَ . ق . به شیراز درگذشت . (از شدالازار ص <span class=\"hlight\" dir=\"rtl\">٣٦١</span> و حاشیه ٔ آن ).<br /></font></div>'),
(181352, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن علی بن عثمان العمری ملقب به عصام الدین العمری . شاعر و ادیب بود. به سال <span class=\"hlight\" dir=\"rtl\">١١٣٤</span> هَ . ق . به موصل متولد و در <span class=\"hlight\" dir=\"rtl\">١١٩٣</span> بدانجا درگذشت . از اوست : الروض النفرقی، تراجم ادباءالعصر، راحةالروح . (از اعلام زرکلی ).<br /></font></div>'),
(181353, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن علی بن محجن ملقب به الزیلعی . فقیه حنفی است به سال <span class=\"hlight\" dir=\"rtl\">٧٠٥</span> هَ . ق . به قاهره رفت و بدانجا درس گفت و فتوی داد. و به سال <span class=\"hlight\" dir=\"rtl\">٧٤٣</span> هَ . ق . بدانجا درگذشت . از کتب اوست : الحقایق فی شرح کنزالدقایق، برکة الکلام علی احادیث الاحکام، شرح الجامع در فقه . (از اعلام زرکلی ).<br /></font></div>'),
(181354, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن عمربن ابی بکربن یونس مکنی به ابوعمرو جمال الدین و ملقب به ابن حاجب . رجوع به ابن حاجب و رجوع به الاعلام زرکلی و روضات الجنات شود.<br /></font></div>'),
(181355, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن عمربن ادّبن طانجة. جد جاهلی از عدنانیان است . فرزندان او فرقه ای از بنی مزینةاند و از آنان زهیربن ابی سلمی است . (از اعلام زرکلی ).<br /></font></div>'),
(181356, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن طلحةبن طلحة العبدری صحابی و از بنی عبدالدار است . باخالدبن الولید در صلح حدیبیه اسلام آورد. در فتح مکه حاضر بودو رسول (ص ) کلید کعبه را بدو و به پسر عمش شیبةبن عثمان بن ابی طلحة سپرد. وی در حدود سال <span class=\"hlight\" dir=\"rtl\">٤٢</span> هَ . ق . به مکه درگذشت . (از الاعلام زرکلی و الاصابة ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٠</span>).<br /></font></div>'),
(181357, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن عیسی بن درباس مارانی ملقب به ضیاءالدین . از اعلم شافعیان درفقه بود نسبت او به بنی ماران است در مروج (نزدیک موصل ) وی به اربل نشأت یافت و به دمشق شد و سپس به مصر رفت و قضاوت غریبه (از توابع مصر) را یافت و سپس سلطان صلاح الدین قضاوت دیار مصر را در <span class=\"hlight\" dir=\"rtl\">٥٦٦</span> هَ . ق . بدوداد. وی مانده ٔ عمر خود را به قاهره به تدریس پرداخت . او راست : الاستقصاء لمذهب الفقهاء در بیست مجلد، شرح اللمع در اصول فقه . تولد او به سال <span class=\"hlight\" dir=\"rtl\">٥١٦</span> هَ . ق . است و به سال <span class=\"hlight\" dir=\"rtl\">٦٠٢</span> هَ . ق . درگذشت . (از اعلام زرکلی ).<br /></font></div>'),
(181358, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن عیسی بن منصور بلیطی مکنی به ابوالفتح از علمای ادب و اخبار بود و او را شعری است . در شهری نزدیک موصل متولد شد سپس به دمشق و به مصر شد و به سال <span class=\"hlight\" dir=\"rtl\">٥٩٩</span> هَ . ق . بدانجا درگذشت . شعر نیک می گفت . او راست :کتاب العروض یکی بزرگ و دیگری کوچک، العظات و الموقظات المنیر، اختبار المتنبی، علم اشکال الخط، التصحیف والتحریف . (ازاعلام زرکلی و خاندان نوبختی ص <span class=\"hlight\" dir=\"rtl\">٧٢</span>).<br /></font></div>'),
(181359, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن قطن . در عراق با حجاج بن یوسف بود و بفرماندهی برخی از لشکریان او رسید و آخرین بار فرمانده لشکری بود که به جنگ شبیب بن یزید رفت و به سال <span class=\"hlight\" dir=\"rtl\">٧٦</span> هَ . ق . در همان جنگ به دست مصاد برادر شبیب کشته شد. (از اعلام زرکلی ).<br /></font></div>'),
(181360, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن محمدبن ابی شیبة الکوفی . معروف به ابن ابی شیبة و مکنی به ابوالحسن . از حُفّاظ حدیث است . او راست : المسند و التفسیر. وی مردی ثقه و امین بود و به سال <span class=\"hlight\" dir=\"rtl\">١٥٦</span> هَ . ق . متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٢٣٩</span> هَ . ق . درگذشت . (از اعلام زرکلی ).<br /></font></div>'),
(181361, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن محمدبن خالدبن زبیربن العوام معروف به عثمان الزبیری . در مدینه بهمراهی محمدبن عبداﷲبن حسن بر منصور عباسی خروج کرد و پس از قتل محمد به بصره پناه برد و سپس دستگیر شد و او را بنزد منصور عباسی بردند و به سال <span class=\"hlight\" dir=\"rtl\">١٤٥</span> هَ . ق . بقتل رسید. (از اعلام زرکلی ).<br /></font></div>'),
(181362, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b>(اِخ ) ابن مظعون بن حبیب بن وهب الجمحی مکنی به ابوالسائب . صحابی و از حکماء عرب جاهلیت بود. وی سیزدهمین مردی است که اسلام آورد و دوبار به حبشه مهاجرت کرد.در جنگ بدر حاضر شد و به سال دوم هجری درگذشت . موقعی که مرد حضرت رسول او را بوسید. (از اعلام زرکلی ).<br /></font></div>'),
(181363, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن حیان بن معبد المری . ولیدبه سال <span class=\"hlight\" dir=\"rtl\">٩٣</span> هَ . ق . وی را برکنار ساخت و به سال <span class=\"hlight\" dir=\"rtl\">١٠٣</span> عهده دار جنگهای تابستانی شد. به سال <span class=\"hlight\" dir=\"rtl\">١٠٤</span> با قیصر نبرد کرد و در حدود سال <span class=\"hlight\" dir=\"rtl\">١٠٥</span> درگذشت . (از اعلام زرکلی ).<br /></font></div>'),
(181364, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) چوزه ٔشوات . (منتهی الارب ) (اقرب الموارد). فرخ الحباری . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بچه ٔ اژدها. <BR><font color=\"Blue\">◄</font> مار یا بچه ٔ مار. (منتهی الارب ) (اقرب الموارد).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ابوعثمان </span> ؛ کنیت مار. (اقرب الموارد).<br /></font></div>'),
(181365, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) دهی است از دهستان قعله ٔ شاهین بخش پل ذهاب شهرستان قصرشیرین، واقع در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی جنوب خاوری سرپل ذهاب کنار راه فرعی به قلعه شاهین، واقع در دشت . هوای آن گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٧٠</span> تن سکنه دارد. آب آن از سراب قلعه شاهین تأمین می شود. محصول آن غلات و لبنیات است . شغل اهالی زراعت و گله داری است . (از فرهنگ جغرافیایی ایران، ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(181366, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) کوهی است به مدینه بین آن و بین ذی المرة در راه شام از مدینه . (معجم البلدان ).<br /></font></div>'),
(181367, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن ابی العاص بن بشربن عبد دهمان از ثقیف صحابی و از مردم طائف بود در وفد ثقیف اسلام آورد. رسول (ص ) او را عمل طائف داد. عبد عمر بدان سمت بود تا عمر وی را عامل بحرین ساخت و سپس معزول شده به بصره سکونت جست تاسال <span class=\"hlight\" dir=\"rtl\">٥١</span> هَ . ق . در آنجا درگذشت . در بصره محلی است بنام شط عثمان که بدو منسوب است . (از الاعلام زرکلی ).<br /></font></div>'),
(181368, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن احمدبن سعیدبن عثمان معروف به ابن قائد. فقیه و از افاضل نجدیین بود و به سال <span class=\"hlight\" dir=\"rtl\">١٠٩٧</span> هَ . ق . به قاهره درگذشت . او راست : هدایة الراغب فی شر عمدة المطالب در فقه حنبلی، حواشی علی منتهی الارادات، در فقه . رسالة فی الرضاع، نجاةالخلف فی اعتقاد السلف و جز آن . (از اعلام زرکلی ).<br /></font></div>'),
(181369, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن جنی الموصلی مکنی به ابوالفتح و ملقب به ابن جنی . رجوع به الاعلام زرکلی و روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٦٦</span> و نیز ابن جنی شود.<br /></font></div>'),
(181370, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن حمزةبن عبیداﷲبن عمربن الخطاب از اشراف و از کسانی بود که به اندلس رفت و به طلیطلة اقامت گزید چون عبدالرحمن الاموی بر اندلس تسلط یافت عثمان با جماعتی از پذیرفتن او خودداری کرد وعبدالرحمن با آنان نبرد کرد و در نتیجه عثمان گرفتار شد و در قرطبه بدار آویخته شد. (از اعلام زرکلی ).<br /></font></div>'),
(181371, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن حنیف بن وهب الانصاری الاوسی . صحابی است . در جنگ احد و جنگ های پس از آن شرکت کرد. از جانب عمر ولایت سواد و بصره را یافت و هنگامی که فتنه ٔ جمل برخاست یاران عایشه وی را بر ضد علی خواندند و او نپذیرفت پس موی ریش و ابرو و سر وی را کندند و او به علی (ع ) پیوست و در جنگ جمل به سال <span class=\"hlight\" dir=\"rtl\">٣٥</span> هَ . ق . کشته شد. (از اعلام زرکلی ).<br /></font></div>'),
(181372, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن عامربن عمروبن کعب التیمی القرشی . رجوع به ابوقحافه شود.<br /></font></div>'),
(181373, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن ربیعة الاندلسی، ادیب بود. او راست : طبقات الشعراء بالاندلس . وی در حدود سال <span class=\"hlight\" dir=\"rtl\">٣١٠</span> هَ . ق . درگذشت . (از اعلام زرکلی ).<br /></font></div>'),
(181374, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن سعیدبن خالد الدارمی السجستانی . محدث هرات بود. او را مسندی بزرگ و تصانیفی در رد «جهمیه » است . وی به سال <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> هَ . ق . متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٢٨٠</span> به هرات درگذشت . (از اعلام زرکلی ).<br /></font></div>'),
(181375, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن سعیدبن عثمان معروف به ابن صیرفی از موالی بنی امیه و از حُفّاظ حدیث و از ائمه ٔ علم قرآن و روایات و تفسیر بود. وی به سال <span class=\"hlight\" dir=\"rtl\">٣٧٢</span> هَ . ق . بدانیه ٔ اندلس متولد شد و به مشرق رفت و حج گزارد و به مصر شد. سپس بازگشت و به سال <span class=\"hlight\" dir=\"rtl\">٤٤٤</span> به موطن خود درگذشت . اوراست بیشتر از یکصد تصنیف از جمله : التیسیر فی مذاهب القراء السبعة، جامع البیان فی القراآت و طبقات القراء و جز آن . (از اعلام زرکلی ) (روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٦٧</span>).<br /></font></div>'),
(181376, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) (<span class=\"hlight\" dir=\"rtl\">١١٠</span> - <span class=\"hlight\" dir=\"rtl\">١٩٧</span> هَ . ق .) ابن سعیدبن عدی المصری . از قراء بزرگ بود. وی را «ورش » لقب دادند. اصل او از قیروان و مولد و وفاتش به مصر بود. (از اعلام زرکلی ).<br /></font></div>'),
(181377, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) (<span class=\"hlight\" dir=\"rtl\">١١٨٠</span> - <span class=\"hlight\" dir=\"rtl\">١٢٤٢</span> هَ. ق .) ابن سند النجدی الوائلی . معروف به ابن سند البصری ملقب به بدرالدین . مورخ، ادیب و از نوابغ متأخران است . اصلش از عرب عنیزه بود. به نجد متولد و به بصره ساکن شد و به بغداد درگذشت . از کتب اوست : الغررفی وجوه القرآن، مطالع السعود بطیب اخبارالوالی داود، منظم الجوهر فی مدائح حمیر، نظم المغنی اللبیب، نظم الورقات امام الحرمین و شرح آن و سبائک العسجد فی اخبار الاحمد. وی شاعری مکثر بود. (از اعلام زرکلی ).<br /></font></div>'),
(181378, 'عثمان', '<span class=\"hlight\">عثمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) (<span class=\"hlight\" dir=\"rtl\">٥٦٧</span> - <span class=\"hlight\" dir=\"rtl\">٥٩٥</span> هَ . ق .) ابن صلاح الدین یوسف بن ایوب معروف به الملک العزیز. از ملوک ایوبیة مصر بود. از جانب پدر نیابت مصر یافت . به سال <span class=\"hlight\" dir=\"rtl\">٥٨٩</span> پس از مرگ پدر مستقل گشت و بر آن شد که دمشق را از دست برادر خود افضل بیرون سازد ونتوانست . سپس به سال <span class=\"hlight\" dir=\"rtl\">٥٩٢</span> بر دمشق تسلط یافت و عم خود عادل را بدانجا گمارد. وی از فقه و احادیث اطلاعی داشت . تولد و وفاتش در قاهره بود. (از اعلام زرکلی ).<br /></font></div>'),
(181379, 'عثمان اولن', '<span class=\"hlight\">عثمان اولن .</span> <font color=\"DarkGreen\"><b>[ ع ُ اُ ل َ ]</font></b> (اِخ ) دهی است از دهستان آجرلو بخش مرکزی شهرستان مراغه، واقع در <span class=\"hlight\" dir=\"rtl\">٧٠</span> هزارگزی جنوب خاوری مراغه و <span class=\"hlight\" dir=\"rtl\">٢١</span> هزارگزی شمال خاوری راه شوسه ٔ شاهین دژ به میاندوآب . ناحیه ای است کوهستانی و هوای آن معتدل است و <span class=\"hlight\" dir=\"rtl\">٦٧</span> تن سکنه دارد. آب آن از چشمه تأمین می شود. محصولاتش غلات، نخود، بزرک است . شغل اهالی زراعت و صنایع دستی زنها جاجیم بافی است .راه مالرو دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(181380, 'عثمان سرا', '<span class=\"hlight\">عثمان سرا.</span> <font color=\"DarkGreen\"><b>[ ع ُ س َ ]</font></b> (اِخ ) ده کوچکی است از دهستان لنگا شهرستان تنکابن، واقع در <span class=\"hlight\" dir=\"rtl\">٣١</span> هزارگزی جنوب خاوری تنکابن و <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی جنوب راه شوسه ٔ تنکابن به چالوس . <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(181381, 'عثمان مختاری', '<span class=\"hlight\">عثمان مختاری .</span> <font color=\"DarkGreen\"><b>[ ع ُ ن ِ م ُ ]</font></b> (اِخ ) ابوالمفاخر خواجه حکیم سراج الدین ابوعمر عثمان بن عمر (یا محمد) مختاری غزنوی از شاعران بزرگ دربار غزنویان در اواخر قرن پنجم و نیمه ٔ اول قرن ششم هجری است . وی با ابراهیم بن مسعود غزنوی و مسعودبن ابراهیم و عضدالدوله شیرزادبن مسعودبن ابراهیم و جز آنها معاصر بوده است .علاوه بر سلاطین غزنویان قاوردیان کرمان مخصوصاً سلطان ارسلانشاه سلجوقی را مدح گفته است . وی با ابوالفرج رونی و مسعودبن سعد سلمان و سنائی معاصر بوده است و سنائی در مدح او قصیده گفته و در آن مختاری را به معانی شعر بکر ستوده . وفات مختاری را به سال <span class=\"hlight\" dir=\"rtl\">٥٤٤</span> تا <span class=\"hlight\" dir=\"rtl\">٥٤٩</span> هَ . ق . دانسته اند. دیوان او را قریب هشت هزار بیت نوشته اند. از وی مثنوی مشهوری بنام شهریارنامه در دست است و آن را به خواهش سلطان مسعودبن ابراهیم به نظم درآورده است . آخرین ابیات شهریارنامه چنین است :<br />بسر شد کنون نامه ٔ شهریار<br />بتوفیق یزدان پروردگار<br />شها شهریارا سرا سرورا<br />نگهدار تختا جهان داورا<br /><font color=\"Red\">(از تاریخ ادبیات صفا و فهرست سپهسالار).</font><br /></font></div>'),
(181382, 'عثمان کلا', '<span class=\"hlight\">عثمان کلا.</span> <font color=\"DarkGreen\"><b>[ ع ُک َ ]</font></b> (اِخ ) دهی است از دهستان کلاردشت بخش مرکزی شهرستان نوشهر، واقع در پنج هزارگزی خاور حسن کیف کنار راه شوسه ٔ حسن کیف به مرزان آباد. ناحیه کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٧٥</span> تن سکنه دارد. آب آن از چشمه تأمین میشود. محصولات آن غلات، ارزن، لبنیات است و شغل اهالی زراعت و گله داری و تهیه زغال و چوب است . صنایع دستی آنان شال بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(181383, 'عثمانوند', '<span class=\"hlight\">عثمانوند.</span> <font color=\"DarkGreen\"><b>[ ع ُ مان ْ وَ ]</font></b> (اِخ ) یکی از ایل های کرد ایران . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٦٠</span>).<br /></font></div>'),
(181384, 'عثمانوند', '<span class=\"hlight\">عثمانوند.</span> <font color=\"DarkGreen\"><b>[ ع ُ مان ْ وَ ]</font></b> (اِخ ) نام یکی ازدهستانهای بخش حومه ٔ شهرستان کرمانشاهان و حوزه ٔ آمار کنگاور است . این دهستان در منطقه ٔ کوهستانی و در جنوب خاوری کرمانشاهان بین دهستانهای ماهیدشت زردلان و جلالوند است . هوای آن سرد و سالم است و آب آن از چشمه ها و رودخانه ٔ اهوران تأمین میشود. محصولات عمده ٔ آن غلات، لبنیات، و زغال و هیزم است . و شغل اهالی زراعت و گله داری و حمل هیزم و زغال به شهر است . راههای دهستان مالرو است و فقط در تابستان از طریق گردنه ٔ قادرمرز که بین این دهستان و ماهیدشت است اتومبیل تا آبادی سرجوب مرکز این دهستان میتوان برد. این ناحیه از <span class=\"hlight\" dir=\"rtl\">١٥</span> آبادی تشکیل شده و در حدود <span class=\"hlight\" dir=\"rtl\">٥</span> هزار تن سکنه دارد. و قراء مهم آن بشرح زیر است : بوژن، خشکرود، مستعلی، مسکره، سرجوب . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(181385, 'عثمانی', '<span class=\"hlight\">عثمانی .</span> <font color=\"DarkGreen\"><b>[ ع ُ نی ی ]</font></b>(ص نسبی ) نسبت است به عثمان بن عفان نَسَباً و ولاءً یا اتباعاً مانند اهل شام . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span>).<br /></font></div>'),
(181386, 'عثمانی', '<span class=\"hlight\">عثمانی .</span> <font color=\"DarkGreen\"><b>[ ع ُ نی ی ]</font></b> (ص نسبی ) مقابل علوی . آنانکه علی و یاران او را متهم به قتل عثمان بن عفان کردند.<br /></font></div>'),
(181387, 'عثمانی', '<span class=\"hlight\">عثمانی .</span> <font color=\"DarkGreen\"><b>[ ع ُنی ی ]</font></b> (ص نسبی، اِ) سکه ٔ معروف مروجه ٔ دولت عثمانیه . (آنندراج ). لیره ٔ عثمانی . رجوع به عثمانیان شود.<br /></font></div>'),
(181388, 'عثمانی', '<span class=\"hlight\">عثمانی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) عثمان بن محمدبن عثمان بن محمدبن عبدالملک بن عبدالدین عنسةبن عمروبن عثمان بن عفان العثمان البصری . از محمدبن عبدالسلام روایت کند و ابونعیم الحافظ اصفهانی از وی روایت دارد. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span>).<br /></font></div>'),
(181389, 'عثمانی', '<span class=\"hlight\">عثمانی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ممالکی که آل عثمان در آن سلطنت میکردند. (ناظم الاطباء). رجوع به عثمانیان شود.<br /></font></div>'),
(181390, 'عثمانیان', '<span class=\"hlight\">عثمانیان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) یا آل عثمان یا سلاطین عثمانی . پادشاهانی هستند که از <span class=\"hlight\" dir=\"rtl\">٦٩٩</span> تا <span class=\"hlight\" dir=\"rtl\">١٣٤٢</span>هَ . ق . دولتی بزرگ تأسیس کردند. این سلسله بنام جد آنان عثمان بن ارطغرل منسوبند. عثمان به سال <span class=\"hlight\" dir=\"rtl\">٦٥٦</span> هَ. ق . در سکوت متولد شد و در آنجا به تأسیس سلسله ٔ عثمانی موفق گشت . عثمان سرحد ممالک روم شرقی را به سمت مغرب عقب برد و پسرش ارخان شهرهای بروسه و نقیه را گرفت و ممالک امرای کراسی را که با خاک او مجاور بودند متصرف شد و لشکریان مشهور به چری را که مدت چندین قرن وسیله ٔ عمده ٔ فتوحات سلاطین آل عثمان بودند تشکیل داد. در سال <span class=\"hlight\" dir=\"rtl\">٧٥٩</span> هَ . ق . ترکان عثمانی از بوغاز داردانل گذشتند و از طرف خود ساخلوی در محل گالی پولی گذاشته به تسخیر ممالک اروپای شرقی روم شروع کردند. شهرهای ادرنه و فیلی پوپولیس چند سال بعد تسخیر شد و بر اثر فتوحات ماریتزا (<span class=\"hlight\" dir=\"rtl\">١٣٦٤</span> م .) و قوسوه (<span class=\"hlight\" dir=\"rtl\">١٣٨٩</span> م .) و نیکوپولیس و غلبه ٔ ترکان بر سواران جنگی تمام اروپا سراسر شبه جزیره ٔ بالکان به استثنای حوالی قسطنطنیه بواسطه ٔ هجوم ناگهانی امیر تیمور به آسیای صغیر و شکست سخت بایزیدخان اول در سال <span class=\"hlight\" dir=\"rtl\">٨٠٤</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٤٠٢</span> م . در آنقره مدتی به تعویق افتاد. و دولتی که از شط دانوب تا نهر العاصی در شام امتداد پیدا کرده بود بر اثر یک ضربت تا مدتی دچار ضعف و ناتوانی گردید. اگر چه سلطنت سلطان محمد اول تا حدی شکست گذشته را جبران کرد ولی چندان مورد توجه نیست تا آنکه سلطان مرادخان ثانی پس از تحکیم مواقع خود و برقراری صلح موفق گردید که ممالک عثمانی را از حملات هونیادی ملقب به امیرسیف ولایت افلاق خلاص بخشد و بوسیله ٔ فتح قطعی که در محل وارنا (<span class=\"hlight\" dir=\"rtl\">١٤٤٤</span> م .) نصیب او شد از صلیبیون عیسوی که به نقض عهدنامه اقدام کرده بودند انتقام خود را بکشید. این فتح ممالک عثمانی را از طرف شمال آسوده ساخت و از این تاریخ تا دو قرن دیگر دوره ٔ فتوحات درخشان سلاطین آل عثمانی است . قسطنطنیه را سلطان محمدخان ثانی در سال <span class=\"hlight\" dir=\"rtl\">٨٥٧</span> هَ .ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٤٥٣</span> م . مسخر کرد و آخرین باقیمانده ٔ دولت روم شرقی به این ترتیب از میان رفت . شبه جزیره ٔ قرم در سال <span class=\"hlight\" dir=\"rtl\">١٤٧٥</span> م . تسخیر شد و جزایر دریای اژه نیز ضمیمه ٔ خاک عثمانی گردید و بیرق این سلاطین درایتالیا بر فراز قصر اترانتو افراشته گردید. سلطان سلیم خان اول در هشت سال پادشاهی خود ایران را مغلوب کرد و کردستان و دیار بکر را به ممالک عثمانی ملحق ساخت شام و مصر و عربستان را در سال <span class=\"hlight\" dir=\"rtl\">٩٢٣</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥١٧</span> م . به تصرف درآوردند و بعد بر حرمین استیلا یافت وخلیفه ٔ عباسی مصر را مطیع خود ساخت و حق خلافت را به خود اختصاص داد و از این تاریخ سلاطین عثمانی لقب امیرالمؤمنین اختیار نمودند. سلطان سلیمان خان کبیر نیز عملیات درخشانی انجام داد و در سال <span class=\"hlight\" dir=\"rtl\">٩٢٨</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٢٢</span> م . امرای جزیره ردس را براند و در طرف شمال شهرهای بلگراد را بگرفت و <span class=\"hlight\" dir=\"rtl\">٩٣٢</span> در سال هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٥٢٦</span> م .مجارها را در دشت موهاکن شکست سخت داد و پادشاه ایشان لوئی ثانی را با بیست هزار سپاهیان او دستگیر کرد. مجارستان مدت یک قرن و نیم از ایالات عثمانی شد. این پادشاه در سال <span class=\"hlight\" dir=\"rtl\">٩٣٥</span> هَ . ق . شهر وینه را محاصره کردو با گرفتن خراجی دست برداشت و بالجمله ممالک عثمانی در عهد سلطان سلیمان خان از بوداپست و ساحل دانوب تا شلاله ٔ آسوان در مصر و از ساحل فرات تا باب جبل طارق وسعت داشت . بعد از سلطان سلیمان خان ایام نکبت عثمانیان شروع شد و اولین واقعه ٔ آن شکست بحری لپانتو است در سال <span class=\"hlight\" dir=\"rtl\">٩٧٩</span> هَ . ق . به دست دن ژوان امیر اطریش . سلطان مرادخان چهارم در سال <span class=\"hlight\" dir=\"rtl\">١٠٤٨</span> هَ . ق . بغداد را به خاک عثمانی ضمیمه کرد و ترکان جزیره ٔ کرت و بعضی جزایر دیگر را نیز در سال <span class=\"hlight\" dir=\"rtl\">١٦٤٥</span> م . از دست ونیزیها گرفتند لکن در اروپا شکستهائی بدانها وارد آمد و در سال <span class=\"hlight\" dir=\"rtl\">١٠٩٨</span> هَ . ق . سراسر مجارستان از تصرف ایشان خارج شد و در نتیجه ٔ معاهدات <span class=\"hlight\" dir=\"rtl\">١١١١</span> هَ . ق . ولایات مجارستان بکلی از زیر سلطه ٔ عثمانیان خارج گردید. سرحدات عثمانی از این تاریخ تا تجزیه ای که در سال <span class=\"hlight\" dir=\"rtl\">١٢٩٥</span> هَ . ق . اتفاق افتاد تغییرات فاحشی نکرد. دوره ٔ تعرض روسیه به عثمانی از سال <span class=\"hlight\" dir=\"rtl\">١١٥٠</span> هَ . ق . شروع میشود و در این تاریخ اوکزاکف و آزف از تصرف عثمانیان خارج گردید و در سال <span class=\"hlight\" dir=\"rtl\">١٣٠١</span> هَ . ق . شبه جزیره ٔ قرم محصور شد. داخله ٔ عثمانی نیز هرج و مرج شده بود و به سال <span class=\"hlight\" dir=\"rtl\">١٣٠١</span> هَ . ق . مصر تحت لوای محمدعلی پاشا مستقل و از تصرف عثمانی خارج گردید و بترتیب الجزائر در <span class=\"hlight\" dir=\"rtl\">١٠٧٠</span> هَ . ق . و تونس در<span class=\"hlight\" dir=\"rtl\">١١١٧</span> هَ . ق . نیمه استقلالی به دست آوردند و از تصرف عثمانیان خارج گردید. بزرگترین ضربتی که به عثمانی وارد آمد در قطعه ٔ اروپاست که بوسیله ٔ آن یونان در تاریخ <span class=\"hlight\" dir=\"rtl\">١٢٤٤</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٨٣٨</span> م . از آن جدا شد و ولایت رانوبی بنام رومانی در سال <span class=\"hlight\" dir=\"rtl\">١٢٨٣</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٨٦٦</span> م . و صربستان در <span class=\"hlight\" dir=\"rtl\">١٢٨٤</span> هَ . ق . بر عثمانیان شوریدند و در نتیجه رومانی و صربستان هر یک دولتی علی حده شدند. عثمانیه ٔ حالیه در اروپا محدود است به باریکه ٔ خشکی در جنوب جبال بالکان شامل ولایات قدیم تراس و مقدونیه و اپیروس و ایلی ریا. سلاطین عثمانی بترتیب عبارتند از:<br /><span class=\"hlight\" dir=\"rtl\">١</span> - سلطان عثمان خان غازی سال <span class=\"hlight\" dir=\"rtl\">٦٩٩</span> هَ . ق .<br /><span class=\"hlight\" dir=\"rtl\">٢</span> - سلطان غازی ارخان <span class=\"hlight\" dir=\"rtl\">٧٢٦</span><br /><span class=\"hlight\" dir=\"rtl\">٣</span> - غازی سلطان مرادخان <span class=\"hlight\" dir=\"rtl\">٧٦١</span><br /><span class=\"hlight\" dir=\"rtl\">٤</span> - غازی سلطان بایزید <span class=\"hlight\" dir=\"rtl\">٧٩١</span> - <span class=\"hlight\" dir=\"rtl\">٨٠٤</span><BR><font color=\"HotPink\">♦ </font>فترت <span class=\"hlight\" dir=\"rtl\">٨٠٤</span>- <span class=\"hlight\" dir=\"rtl\">٨١٦</span><br /><span class=\"hlight\" dir=\"rtl\">٥</span> - سلطان محمد خان <span class=\"hlight\" dir=\"rtl\">٨١٦</span><br /><span class=\"hlight\" dir=\"rtl\">٦</span> - سلطان غازی مرادخان ثانی <span class=\"hlight\" dir=\"rtl\">٨٢٤</span><br /><span class=\"hlight\" dir=\"rtl\">٧</span> - سلطان محمدخان ثانی <span class=\"hlight\" dir=\"rtl\">٨٥٥</span><br /><span class=\"hlight\" dir=\"rtl\">٨</span> - سلطان بایزدخان ثانی <span class=\"hlight\" dir=\"rtl\">٨٨٦</span><br /><span class=\"hlight\" dir=\"rtl\">٩</span> - سلطان سلیم خان <span class=\"hlight\" dir=\"rtl\">٩١٨</span><br /><span class=\"hlight\" dir=\"rtl\">١٠</span> - سلطان سلیمان خان <span class=\"hlight\" dir=\"rtl\">٩٢٦</span><br /><span class=\"hlight\" dir=\"rtl\">١١</span> - سلطان سلیم خان ثانی <span class=\"hlight\" dir=\"rtl\">٩٧٤</span><br /><span class=\"hlight\" dir=\"rtl\">١٢</span> - سلطان مرادخان ثالث <span class=\"hlight\" dir=\"rtl\">٩٨٢</span><br /><span class=\"hlight\" dir=\"rtl\">١٣</span> - سلطان محمدخان ثالث <span class=\"hlight\" dir=\"rtl\">١٠٠٣</span><br /><span class=\"hlight\" dir=\"rtl\">١٤</span> - سلطان احمدخان <span class=\"hlight\" dir=\"rtl\">١٠١٢</span><br /><span class=\"hlight\" dir=\"rtl\">١٥</span> - سلطان مصطفی خان <span class=\"hlight\" dir=\"rtl\">١٠٢٦</span><br /><span class=\"hlight\" dir=\"rtl\">١٦</span> - سلطان عثمان خان ثانی <span class=\"hlight\" dir=\"rtl\">١٠٢٧</span><br /><span class=\"hlight\" dir=\"rtl\">١٧</span> -سلطان مرادخان رابع <span class=\"hlight\" dir=\"rtl\">١٠٣٢</span><br /><span class=\"hlight\" dir=\"rtl\">١٨</span> - سلطان ابراهیم خان <span class=\"hlight\" dir=\"rtl\">١٠٤٩</span><br /><span class=\"hlight\" dir=\"rtl\">١٩</span> - سلطان محمدخان رابع <span class=\"hlight\" dir=\"rtl\">١٠٥٨</span><br /><span class=\"hlight\" dir=\"rtl\">٢٠</span> - سلطان سلیمان خان ثانی <span class=\"hlight\" dir=\"rtl\">١٠٩٩</span><br /><span class=\"hlight\" dir=\"rtl\">٢١</span> - سلطان احمدخان ثانی <span class=\"hlight\" dir=\"rtl\">١١٠٢</span><br /><span class=\"hlight\" dir=\"rtl\">٢٢</span> - سلطان مصطفی خان ثانی <span class=\"hlight\" dir=\"rtl\">١١٠٦</span><br /><span class=\"hlight\" dir=\"rtl\">٢٣</span> - سلطان احمدخان ثالث <span class=\"hlight\" dir=\"rtl\">١١١٥</span><br /><span class=\"hlight\" dir=\"rtl\">٢٤</span> - سلطان محمدخان <span class=\"hlight\" dir=\"rtl\">١١٤٣</span><br /><span class=\"hlight\" dir=\"rtl\">٢٥</span> - سلطان عثمان خان ثالث <span class=\"hlight\" dir=\"rtl\">١١٦٨</span><br /><span class=\"hlight\" dir=\"rtl\">٢٦</span> - سلطان مصطفی خان ثالث <span class=\"hlight\" dir=\"rtl\">١١٧١</span><br /><span class=\"hlight\" dir=\"rtl\">٢٧</span> -سلطان عبدالحمید خان <span class=\"hlight\" dir=\"rtl\">١١٨٧</span><br /><span class=\"hlight\" dir=\"rtl\">٢٨</span> - سلطان سلیم خان ثالث <span class=\"hlight\" dir=\"rtl\">١٢٠٣</span><br /><span class=\"hlight\" dir=\"rtl\">٢٩</span> - سلطان مصطفی خان رابع <span class=\"hlight\" dir=\"rtl\">١٢٢٢</span><br /><span class=\"hlight\" dir=\"rtl\">٣٠</span> - سلطان محمودخان ثانی <span class=\"hlight\" dir=\"rtl\">١٢٢٣</span><br /><span class=\"hlight\" dir=\"rtl\">٣١</span> - سلطان عبدالمجید خان <span class=\"hlight\" dir=\"rtl\">١٢٥٥</span><br /><span class=\"hlight\" dir=\"rtl\">٣٢</span> - سلطان عبدالعزیزخان <span class=\"hlight\" dir=\"rtl\">١٢٧٧</span><br /><span class=\"hlight\" dir=\"rtl\">٣٣</span> - سلطان مرادخان خامس <span class=\"hlight\" dir=\"rtl\">١٢٩٣</span><br /><span class=\"hlight\" dir=\"rtl\">٣٤</span> - سلطان عبدالحمیدخان ثانی <span class=\"hlight\" dir=\"rtl\">١٢٩٣</span><br /><span class=\"hlight\" dir=\"rtl\">٣٥</span> - سلطان محمد خامس <span class=\"hlight\" dir=\"rtl\">١٣٢٧</span><br /><span class=\"hlight\" dir=\"rtl\">٣٦</span> - سلطان محمد سادس <span class=\"hlight\" dir=\"rtl\">١٣٣٦</span><br /><span class=\"hlight\" dir=\"rtl\">٣٧</span> -سلطان عبدالمجید ثانی <span class=\"hlight\" dir=\"rtl\">١٣٤١</span><br /><span class=\"hlight\" dir=\"rtl\">٣٨</span> - سلطان عبدالعزیز ثانی <span class=\"hlight\" dir=\"rtl\">١٣٤٢</span><br />و رجوع به آل عثمان و معجم الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٩</span>-<span class=\"hlight\" dir=\"rtl\">١٤٠</span> شود.<br /></font></div>'),
(181391, 'عثماوندان', '<span class=\"hlight\">عثماوندان .</span> <font color=\"DarkGreen\"><b>[ ع ُ وَ ]</font></b> (اِخ ) دهی است از دهستان شفت بخش مرکزی شهرستان فومن، واقع در <span class=\"hlight\" dir=\"rtl\">١١</span> هزارگزی خاور فومن . ناحیه ای است جلگه . آب و هوای آن معتدل و مرطوب است . <span class=\"hlight\" dir=\"rtl\">١٠١٣</span> تن سکنه دارد. آب آن از نهر سنگ تأمین میشود. محصولات آن برنج، ابریشم، چای و عسل است . شغل اهالی زراعت است . راه مالرو دارد و از شفت اتومبیل میرود. در حدود ده باب دکان دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(181392, 'عثمثم', '<span class=\"hlight\">عثمثم .</span> <font color=\"DarkGreen\"><b>[ ع َ ث َ ث َ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ) (آنندراج ). شیر و بخاطر گران رفتن وی آن را بدین نام خوانند. <BR><font color=\"Blue\">◄</font> (ص ) شتر سخت اندام دراز. (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181393, 'عثمثمة', '<span class=\"hlight\">عثمثمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ث َ ث َ م َ]</font></b> (ع ص، اِ) مؤنث عثمثم . رجوع به ماده ٔ فوق شود.<br /></font></div>'),
(181394, 'عثمر', '<span class=\"hlight\">عثمر.</span> <font color=\"DarkGreen\"><b>[ ع ُ م ُ ]</font></b> (اِخ ) ریگستانی است نیکوگیاه آسان گذار هموار در بلاد طی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181395, 'عثمی', '<span class=\"hlight\">عثمی .</span> <font color=\"DarkGreen\"><b>[ ع َ می ی ]</font></b> (اِخ ) ابوالحسن مفضل بن عمیربن عثم بن منتجعبن عمیربن منتجعبن صخربن هندبن ریاح بن عبیدبن عوف بن حرام العثمی . مروزی است . از شاذان بن فیاض و حفص بن عمرالحوض و علی بن حجر و جز آنها روایت کند و از وی عبدالرحمن بن فتح السراج و جز آنان روایت کند. وی به سال <span class=\"hlight\" dir=\"rtl\">٢٧٥</span> هَ . ق . به شاش درگذشت . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span>).<br /></font></div>'),
(181396, 'عثمی', '<span class=\"hlight\">عثمی .</span> <font color=\"DarkGreen\"><b>[ ع ُ می ی ]</font></b> (اِخ ) عبدالعزیزبن بدربن زیدبن معاویةبن حسام بن اسعدبن ودیعةبن مبذول بن عدی بن عثم بن الربیعة العثمی منسوب به عثم بن ربیعةبن رشدبن قیس بن جهنیه . بطنی از جهنیةبن زید است . وی از وافدین بر پیغمبر است نام او عبدالعزی بوده رسول (ص ) آن را تغییر داد. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span>).<br /></font></div>'),
(181397, 'عثن', '<span class=\"hlight\">عثن .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) نوعی از برگ خرما که تر و سبز آن را شتر خورد. (منتهی الارب ). ضرب من الخوصة ترعاه المال . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نیکوکن شتران و حافظ آن . (منتهی الارب ) (آنندراج ). مصلح المال سائسه . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> پشم . (ناظم الاطباء) (اقرب الموارد).<br /></font></div>'),
(181398, 'عثن', '<span class=\"hlight\">عثن .</span> <font color=\"DarkGreen\"><b>[ ع َ ث َ ]</font></b> (ع اِ) بت خرد. ج، اَعثان . (منتهی الارب ) (اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> دود. (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181399, 'عثن', '<span class=\"hlight\">عثن .</span> <font color=\"DarkGreen\"><b>[ ع َ ث ِ ]</font></b> (ع ص ) طعام بوی گرفته و تباه از دود. (منتهی الارب ) (ناظم الاطباء). الفاسد من الطعام لدخان خالَطَه ُ. (اقرب الموارد).<br /></font></div>'),
(181400, 'عثن', '<span class=\"hlight\">عثن .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) دود برآوردن آتش . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> برآمدن بر کوه . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بوی دود گرفتن جامه . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181401, 'عثنجج', '<span class=\"hlight\">عثنجج .</span> <font color=\"DarkGreen\"><b>[ ع َ ث َ ج َ ]</font></b> (ع ص ) عَثَوْجَج . شتر دفزک و تیزرو. (آنندراج ) (از منتهی الارب ).<br /></font></div>'),
(181402, 'عثنون', '<span class=\"hlight\">عثنون .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ریش . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> آنچه زائد باشد از ریش بر دو رخسار. (اقرب الموارد) (منتهی الارب ) (آنندراج ). یا آنچه بر زنخ و زیر آن روید. (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> درازای ریش است . (منتهی الارب ) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> موی دراز زیر زنخ شتران . <BR><font color=\"Blue\">◄</font> اول باد. <BR><font color=\"Blue\">◄</font> اول باران . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> باران عام . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> بردر شده میان آسمان و زمین . ج، عثانین . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> باران، مادام که میان ابر و زمین بود. (اقرب الموارد).<br /></font></div>'),
(181403, 'عثو', '<span class=\"hlight\">عثو.</span> <font color=\"DarkGreen\"><b>[ ع َث ْوْ ]</font></b> (ع مص ) تباه کردن . فساد انگیختن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181404, 'عثو', '<span class=\"hlight\">عثو.</span> <font color=\"DarkGreen\"><b>[ ع ُ ث ُوو ]</font></b> (ع مص ) فاسد کردن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) مبالغت در فساد یا کبر یا کفر. (اقرب الموارد).<br /></font></div>'),
(181405, 'عثوثج', '<span class=\"hlight\">عثوثج .</span> <font color=\"DarkGreen\"><b>[ ع َ ث َ ث َ ]</font></b> (ع ص ) عَثَنْثَج . شتر دفزک تیزرو. (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(181406, 'عثوثل', '<span class=\"hlight\">عثوثل .</span> <font color=\"DarkGreen\"><b>[ ع َ ث َ ث َ ]</font></b> (ع ص ) مرد گنگلاج فروهشته گوشت . (منتهی الارب ). الفدم المسترخی . (اقرب الموارد).<br /></font></div>'),
(181407, 'عثوجج', '<span class=\"hlight\">عثوجج .</span> <font color=\"DarkGreen\"><b>[ ع َ ث َ ج َ ]</font></b> (ع ص ) شتر دفزک و تیزرو. (منتهی الارب ).<br /></font></div>'),
(181408, 'عثور', '<span class=\"hlight\">عثور.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) دیده ور شدن . دیده ور شدن بر چیزی . (از تاج المصادر) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> لغزیدن . به رو درافتادن . (اقرب الموارد) <span class=\"hlight\">:</span> <br />از قصور چشم باشد آن عثور<br />که نبیند شیب و بالا را ز دور.<br /><font color=\"Red\">مولوی (مثنوی ).</font><br /></font></div>'),
(181409, 'عثول', '<span class=\"hlight\">عثول .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) گول . (منتهی الارب ). احمق . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) خرمابن سطبر تنه درشت . (آنندراج ). النخلة الجافیة الغلیظة. (اقرب الموارد).<br /></font></div>'),
(181410, 'عثول', '<span class=\"hlight\">عثول .</span> <font color=\"DarkGreen\"><b>[ ع ِث ْ وَ ل ل ]</font></b> (ع ص ) مرد گنگلاج فروهشته گوشت . <BR><font color=\"Blue\">◄</font> مرد بسیارموی سرو بدن . (منتهی الارب ) (ناظم الاطباء) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سطبر و درشت از مردان . <BR><font color=\"Blue\">◄</font> لحیة عثولة؛ ریش بزرگ انبوه موی . (از اقرب الموارد).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(181411, 'عثون', '<span class=\"hlight\">عثون .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) دود برآوردن آتش . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> برآمدن بر کوه . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> دود دادن جامه را به بوی خوش تا خوشبو شود. (اقرب الموارد).<br /></font></div>'),
(181412, 'عثک', '<span class=\"hlight\">عثک .</span> <font color=\"DarkGreen\"><b>[ ع َ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ث َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ث ُ ]</font></b> (ع اِ)ریشه های درخت خرما. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181413, 'عثکال', '<span class=\"hlight\">عثکال .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) خوشه ٔ خرما. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شاخ خرما. <BR><font color=\"Blue\">◄</font> سرشاخ یا شاخ بزرگ . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خرمابن بابار. (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181414, 'عثکلة', '<span class=\"hlight\">عثکلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ل َ ]</font></b> (ع مص ) زینت دادن هودج را، از عُثکولة. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دویدن گران و سست . (ناظم الاطباء) (اقرب الموارد).<br /></font></div>'),
(181415, 'عثکول', '<span class=\"hlight\">عثکول .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) خوشه ٔ خرما. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شاخ خرد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سر شاخ یا شاخ بزرگ . (منتهی الارب ).<br /></font></div>'),
(181416, 'عثکولة', '<span class=\"hlight\">عثکولة.</span> <font color=\"DarkGreen\"><b>[ع ُ ل َ ]</font></b> (ع اِ) رجوع به عُثکول شود. (منتهی الارب )<br /></font></div>'),
(181417, 'عثی', '<span class=\"hlight\">عثی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ثی ی ]</font></b> (ع مص ) تباه کردن . فساد انگیختن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181418, 'عثیان', '<span class=\"hlight\">عثیان .</span> <font color=\"DarkGreen\"><b>[ ع ِث ْ ]</font></b> (ع اِ) کفتار نر. (منتهی الارب ).<br /></font></div>'),
(181419, 'عثیان', '<span class=\"hlight\">عثیان .</span> <font color=\"DarkGreen\"><b>[ ع َ ث َ ]</font></b> (ع مص ) فساد کردن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مبالغت در فساد و یا کبر یا کفر. (اقرب الموارد).<br /></font></div>'),
(181420, 'عثیر', '<span class=\"hlight\">عثیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) شکوخیدن و به سر درافتادن . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181421, 'عثیر', '<span class=\"hlight\">عثیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) موضعی است به شام . (معجم البلدان ).<br /></font></div>'),
(181422, 'عثیر', '<span class=\"hlight\">عثیر.</span> <font color=\"DarkGreen\"><b>[ ع ِ ی َ ]</font></b> (ع اِ) خاک . <BR><font color=\"Blue\">◄</font> گرد. <BR><font color=\"Blue\">◄</font> گل و لای که به اطراف پایها زیر و بالا کرده باشی . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نشان پنهان . (ناظم الاطباء) (اقرب الموارد) <span class=\"hlight\">:</span> واز عثیر عبیربیز ادهم جهانگرد... خاک آن وادی را...خاصیت سرمه ٔ اصفهانی بخشیده . (دره ٔ نادره ص <span class=\"hlight\" dir=\"rtl\">٣٨٨</span>).<br /></font></div>'),
(181423, 'عثیل', '<span class=\"hlight\">عثیل .</span> <font color=\"DarkGreen\"><b>[ ع ِث ْ ی َ ]</font></b> (ع اِ) کفتار نر. <BR><font color=\"Blue\">◄</font> (ص ) آنکه روغن نمالد و آرایش نکند. (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181424, 'عج', '<span class=\"hlight\">عج .</span> <font color=\"DarkGreen\"><b>[ ع َج ج ]</font></b> (ع مص ) برداشتن آواز و بانگ کردن . (اقرب الموارد) (از شرح قاموس ) (منتهی الارب ) (از آنندراج ). أفضل الحج العج والثج . (لسان العرب ). <BR><font color=\"Blue\">◄</font> زجر کردن ناقه را به لفظ عاج عاج . (منتهی الارب )(اقرب الموارد). <BR><font color=\"Blue\">◄</font> نیک ماهر شدن قوم در فنون رکوب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سخت وزیدن باد و برانگیختن گرد و غبار را. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> غریدن تندر. (منتهی الارب ).<br /></font></div>'),
(181425, 'عج عاج', '<span class=\"hlight\">عج عاج .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) با بانگ و فریاد از هر چیزی . (از اقرب الموارد) (منتهی الارب در ماده ٔ عج ) <span class=\"hlight\">:</span> مانند سیل مواج و بحر عجاج و ابر عجعاج و ریح مهداج بجنبش درآمده متعاقب روان شد. (از دره ٔ نادره ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span>). <BR><font color=\"Blue\">◄</font> اسب گرامی نژاد سالخورده . (منتهی الارب ) (از اقرب الموارد).<br /></font></div>'),
(181426, 'عجاب', '<span class=\"hlight\">عجاب .</span> <font color=\"DarkGreen\"><b>[ ع ُج ْ جا ]</font></b> (ع ص ) کار نیک شگفت و درگذرنده از حد در شگفتی . <BR><font color=\"Blue\">◄</font> آنچه از آن تعجب کنند. (اقرب الموارد).<br /></font></div>'),
(181427, 'عجاب', '<span class=\"hlight\">عجاب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) کار نیک شگفت . (منتهی الارب ). آنچه تجاوز کند از حد عجب . (اقرب الموارد) <span class=\"hlight\">:</span> <br />من رآنی فقد رأی ̍ اﷲ گوی <br />کاین نظر بس عجاب دیدستند.<br /> <font color=\"Red\">خاقانی .</font><br /><BR><font color=\"Blue\">◄</font> امر عجاب و شی ٔ عجاب ؛ آنچه از آن تعجب کنند. (اقرب الموارد).<br /></font></div>'),
(181428, 'عجاج', '<span class=\"hlight\">عجاج .</span> <font color=\"DarkGreen\"><b>[ ع َج ْ جا ]</font></b> (ع ص ) با بانگ و فریاد از هر صاحب صوتی . (اقرب الموارد) (از آنندراج ) (شرح قاموس ) (از مهذب الاسماء): نهر عجاج و فحل عحاج . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> روز گردانگیز. (منتهی الارب ). روزی که در آن غبار باشد. (اقرب الموارد).<br /></font></div>'),
(181429, 'عجاج', '<span class=\"hlight\">عجاج .</span> <font color=\"DarkGreen\"><b>[ ع َج ْ جا ]</font></b> (اِخ ) عبداﷲبن روبةبن لبیدبن صخرالسعدی التمیمی معروف به عجاج و مکنی به ابوالشعثاء در جاهلیت متولد شد شعر گفت سپس اسلام آورد و تا خلافت ولیدبن عبدالملک بزیست . در اواخر عمر زمین گیر شده در حدود سال <span class=\"hlight\" dir=\"rtl\">٩٠</span> هَ . ق . درگذشت . (از اعلام زرکلی ).<br /></font></div>'),
(181430, 'عجاج', '<span class=\"hlight\">عجاج .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) گرد. (منتهی الارب ). غبار. (اقرب الموارد) (شرح قاموس ) (غیاث اللغات ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> دود. (منتهی الارب ) (اقرب الموارد) (شرح قاموس ) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> (ص ) مردم نودیده و فرومایه . (آنندراج ) (منتهی الارب ). سفله از مردم است . (شرح قاموس ). رعاء الناس و غوغاهم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گول . (منتهی الارب ). احمق . (اقرب الموارد).<br /></font></div>'),
(181431, 'عجاجیر', '<span class=\"hlight\">عجاجیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) غلوله ٔ خمیر. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) آنکه گلوله خمیر را بخورد. (منتهی الارب ).<br /></font></div>'),
(181432, 'عجاجیل', '<span class=\"hlight\">عجاجیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عِجَّول . (منتهی الارب ). رجوع به عِجَّول شود.<br /></font></div>'),
(181433, 'عجار', '<span class=\"hlight\">عجار.</span> <font color=\"DarkGreen\"><b>[ ع َ ج جا ]</font></b> (ع ص ) آنک گلوله ٔ خمیر را بخورد. (منتهی الارب ) (آنندراج ). آنکه عجاجیر خورد. (اقرب الموارد). رجوع به عجاجیر شود. <BR><font color=\"Blue\">◄</font> کشتی گیری که پهلوی وی را کسی به زمین نتواند کرد. (اقرب الموارد) (منتهی الارب ) (آنندراج ). کشتی گیری که پای خود رابه پای حریف پیچیده و بر زمین افکند او را. (منتهی الارب ) (آنندراج ). المشغزب لصریعه . (اقرب الموارد).<br /></font></div>'),
(181434, 'عجارد', '<span class=\"hlight\">عجارد.</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (ع اِ) نره . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181435, 'عجارف', '<span class=\"hlight\">عجارف .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (ع اِ) سختیهای زمانه . (منتهی الارب ) (آنندراج ). حوادث روزگار. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شدت باران . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181436, 'عجارم', '<span class=\"hlight\">عجارم .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (ع ص ) مرد استواراندام . الرجل الشدید. <BR><font color=\"Blue\">◄</font> کیر سخت . (منتهی الارب ). کیر و گفته اند بیخ کیر و گاهی کیر را بدان وصف کنند.<br /></font></div>'),
(181437, 'عجارم', '<span class=\"hlight\">عجارم .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (ع اِ) فراهم آمدنگاه گره ها بین دو ران چهارپا. (اقرب الموارد).<br /></font></div>'),
(181438, 'عجاری', '<span class=\"hlight\">عجاری .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) بلاها. (منتهی الارب ) (آنندراج ). دواهی . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سرهای استخوان . (اقرب الموارد) (منتهی الارب ) (آنندراج ). و یاء آن در شعر بتخفیف آید. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181439, 'عجاریف', '<span class=\"hlight\">عجاریف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ)عجارف . حوادث روزگار. (اقرب الموارد). سختیهای زمانه . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> شدت باران .(اقرب الموارد) (منتهی الارب ). رجوع به عجارف شود.<br /></font></div>'),
(181440, 'عجاز', '<span class=\"hlight\">عجاز.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) پی که بدان قبضه ٔ شمشیر بندند. (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181441, 'عجاسی', '<span class=\"hlight\">عجاسی .</span> <font color=\"DarkGreen\"><b>[ ع َسا ]</font></b> (ع اِ) عجاساء. گله ٔ بزرگ از شتران . (منتهی الارب ). العظیمة من الابل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> پاره ای از شب . (منتهی الارب ). رجوع به عجاساء شود.<br /></font></div>'),
(181442, 'عجاف', '<span class=\"hlight\">عجاف .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) حنظل . <BR><font color=\"Blue\">◄</font> زمانه . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص، اِ) ج ِ اعجف . (غیاث اللغات از منتخب ) (مهذب الاسماء) (منتهی الارب ). رجوع به اعجف شود.<br /></font></div>'),
(181443, 'عجاف', '<span class=\"hlight\">عجاف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) نوعی از خرما. (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181444, 'عجال', '<span class=\"hlight\">عجال .</span> <font color=\"DarkGreen\"><b>[ ع ُج ْ جا ]</font></b> (ع اِ) مشتی از طعام حَیس و خرما که به شتاب خورده شود. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خرما با سویق شورانیده . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مشتی از خرما. عجول . (منتهی الارب )<br /></font></div>'),
(181445, 'عجال', '<span class=\"hlight\">عجال .</span> <font color=\"DarkGreen\"><b>[ ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ]</font></b> (ع اِ) ج ِ عِجلة. رجوع به عجلة شود. <BR><font color=\"Blue\">◄</font> ج ِ عَجَلة. رجوع به عَجَله شود. <BR><font color=\"Blue\">◄</font> ج ِ عَجیل . رجوع به عَجیل شود. <BR><font color=\"Blue\">◄</font> ج ِ عَجلان . (منتهی الارب ). رجوع به عجلان شود.<br /></font></div>'),
(181446, 'عجالة', '<span class=\"hlight\">عجالة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ل َ]</font></b> (ع اِ) گیاهی است . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181447, 'عجالة', '<span class=\"hlight\">عجالة.</span> <font color=\"DarkGreen\"><b>[ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ل َ ]</font></b> (ع اِ) ماحضر. (منتهی الارب ). ماحضر از طعام . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه زود فراهم آرند مهمان را. (اقرب الموارد) (منتهی الارب ). هر چه به شتاب حاضر آورده شود. (غیاث از منتخب ) (اقرب الموارد). هرچه سردست مهیا آید. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آنچه سوار توشه بردارد از چیزهایی که خوردن آن دشوار نباشد او را مانند خرما و سویق . (اقرب الموارد).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عجالة الراکب </span> ؛ آنچه سوار با خود بردارد ازخرما و سویق . ماحضر. آنچه آماده و در دسترس باشد <span class=\"hlight\">:</span> بقیه ٔ آن فیالق فیل افکن انهزام یافته عجالةالراکب هزار فیل نیک فال از آن اَفیال فِلال به مرابطحصول پیوست . (دره ٔ نادره ص <span class=\"hlight\" dir=\"rtl\">٤٤٨</span>). التمر عجالة الراکب ؛ مثلی است که برای تحریک کسی زنند تا به اندک موجود قناعت کند گاهی که دسترسی به بسیار آن نباشد. <BR><font color=\"Blue\">◄</font> شیر ناشتاشکن که شبان پیش از دوشیدن شتران بیک حلبه در چراگاه دوشیده باشد. (منتهی الارب ). شیر اندک که دوشنده در چراگاه شتابان دوشد آن را برای خود یا جز خود. (اقرب الموارد).<br /></font></div>'),
(181448, 'عجالد', '<span class=\"hlight\">عجالد.</span> <font color=\"DarkGreen\"><b>[ ع ُ ل ِ ]</font></b> (ع ص ) شیر خَفته . (منتهی الارب ). اللبن الخاثر جداً. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شیر دفزک زده و جغرات شده . (منتهی الارب ).<br /></font></div>'),
(181449, 'عجالز', '<span class=\"hlight\">عجالز.</span> <font color=\"DarkGreen\"><b>[ ع ُ ل ِ ]</font></b> (ع ص ) شیر خفته . (منتهی الارب ).<br /></font></div>'),
(181450, 'عجالط', '<span class=\"hlight\">عجالط.</span> <font color=\"DarkGreen\"><b>[ ع ُ ل ِ ]</font></b> (ع ص ) شیر خفته ٔ سطبر. (منتهی الارب ). شیر دفزک شده ٔ سطبر. (اقرب الموارد). اللبن الخاثر الثخین .<br /></font></div>'),
(181451, 'عجالم', '<span class=\"hlight\">عجالم .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ ]</font></b> (اِخ ) گروهی است از اهل یمن، عجلمی منسوب است به وی . (منتهی الارب ).<br /></font></div>'),
(181452, 'عجالی', '<span class=\"hlight\">عجالی .</span> <font color=\"DarkGreen\"><b>[ ع َ لا ]</font></b> (ع ص، اِ) ج ِ عَجلی ̍. (منتهی الارب ). رجوع به عجلی ̍ شود.<br /></font></div>'),
(181453, 'عجالی', '<span class=\"hlight\">عجالی .</span> <font color=\"DarkGreen\"><b>[ ع ُ لا ]</font></b> (ع ص، اِ) ج ِعَجلی ̍. (اقرب الموارد). ج ِ عَجیل . (منتهی الارب ).<br /></font></div>'),
(181454, 'عجام', '<span class=\"hlight\">عجام .</span> <font color=\"DarkGreen\"><b>[ ع َج ْ جا ]</font></b> (ع اِ) شب پره ٔ ستبر. (منتهی الارب ). خفاش . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> فراستوک . (منتهی الارب ).<br /></font></div>'),
(181455, 'عجام', '<span class=\"hlight\">عجام .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) هسته و دانه ٔ هر چیزی . هسته ٔ هر چیزی . (اقرب الموارد).<br /></font></div>'),
(181456, 'عجان', '<span class=\"hlight\">عجان .</span> <font color=\"DarkGreen\"><b>[ ع َج ْ جا ]</font></b> (ع ص ) احمق . (مهذب الاسماء). گول . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خمیرگیر. خمیرکن . (مهذب الاسماء). فعّال است مبالغه را. (اقرب الموارد).<br /></font></div>'),
(181457, 'عجان', '<span class=\"hlight\">عجان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) گردن . (منتهی الارب ). گردن به لغت اهل یمن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سرین . (اقرب الموارد) (منتهی الارب ) (لسان العرب ). <BR><font color=\"Blue\">◄</font> قضیب ممدود از خصیه تا دبر. (منتهی الارب ) (لسان العرب ). القضیب الممدود و مابین السبیلین من الرجل و المراءة. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مابین خصیه و دبر. (منتهی الارب ). مابین خصیه و فَقْحة. (لسان العرب ). <BR><font color=\"Blue\">◄</font> مابین قُبُل و دبر. (لسان العرب ). <BR><font color=\"Blue\">◄</font> زیر زنخ . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181458, 'عجانس', '<span class=\"hlight\">عجانس .</span> <font color=\"DarkGreen\"><b>[ ع َ ن ِ ]</font></b> (ع اِ) گوه گردان . (منتهی الارب ) (آنندراج ). جعلان . مقلوب جعانس . (اقرب الموارد).<br /></font></div>'),
(181459, 'عجاهن', '<span class=\"hlight\">عجاهن .</span> <font color=\"DarkGreen\"><b>[ ع ُ هَِ ]</font></b> (ع اِ) خارپشت . <BR><font color=\"Blue\">◄</font> (ص ) آنکه نسب وی صریح نباشد. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دوست نوشاه (تازه داماد) تا که با زن خود خلوت نکرده باشد. (منتهی الارب ). صدیق الجرل المعرس الذی یجری بین العروس و أهله فی الاعراس بالرسائل فاذا بنی بها فلا عجاهن . (اقرب الموارد). رسول میان عروس و اهل او. (منتهی الارب ). زن دلاله . (مهذب الاسماء). وکیل نکاح . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خادم . <BR><font color=\"Blue\">◄</font> طباخ . ج، عَجاهِنَة. (اقرب الموارد)(منتهی الارب ). <BR><font color=\"Blue\">◄</font> خوان سالار. (آنندراج ).<br /></font></div>'),
(181460, 'عجاهنة', '<span class=\"hlight\">عجاهنة.</span> <font color=\"DarkGreen\"><b>[ ع ُ هَِ ن َ ]</font></b> (ع ص، اِ) مؤنث عجاهن . <BR><font color=\"Blue\">◄</font> زن آرایشگر که جدا نشود از عروس تا او را بشوی برند. (اقرب الموارد). زن مشاطه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زن پیغامبر کدخدائی میان عروس و اهل وی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181461, 'عجاوتان', '<span class=\"hlight\">عجاوتان .</span> <font color=\"DarkGreen\"><b>[ ع ُ وَ ]</font></b>(ع اِ) دو عصب است در باطن دو دست . (بحرالجواهر).<br /></font></div>'),
(181462, 'عجایا', '<span class=\"hlight\">عجایا.</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ]</font></b> (ع اِ) ج ِ عُجیَّه . (اقرب الموارد).<br /></font></div>'),
(181463, 'عجایب', '<span class=\"hlight\">عجایب .</span> <font color=\"DarkGreen\"><b>[ ع َ ی ِ ]</font></b> (ع ص، اِ) عَجائب . شگفتیها <span class=\"hlight\">:</span> <br />کسی کاین پر عجایب صنع و قدرت را نمی بیند<br />سزد گر مرد بینا جز که نابیناش نشمارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />دیدن عجایب و شنیدن غرایب . (گلستان ).<br />رجوع به عَجَب و عجائب شود.<br /></font></div>'),
(181464, 'عجایة', '<span class=\"hlight\">عجایة.</span> <font color=\"DarkGreen\"><b>[ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ی َ ]</font></b> (ع اِ) پَی که در آن سر استخوانهای بند دست ستور ترتیب یافته یا پی دست یا پای یا پی باطن سم اسب و گاو یا پی هر چه باشد. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> عصبی است مرکب در آن نگین ها است از استخوان چون نگین انگشتر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دست و پای ستوران و گفته اند هر عصبی است در دست یا پا و گفته اند عصبی است در داخل خرده گاه ساق و ذراع از اسب و گاو. (از اقرب الموارد).<br /></font></div>'),
(181465, 'عجایة', '<span class=\"hlight\">عجایة.</span> <font color=\"DarkGreen\"><b>[ ع َ ی َ ]</font></b> (ع اِ) عَجوة. خرمائی است نیکو به مدینه . (از اقرب الموارد). <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ]</font></b> المرالمحشی ّ فی وعائه . (المنجد) (از منتهی الارب ). رجوع به عجوة شود.<br /></font></div>'),
(181466, 'عجایز', '<span class=\"hlight\">عجایز.</span> <font color=\"DarkGreen\"><b>[ ع َ ی ِ ]</font></b> (ع ص، اِ) عجائز. پیره زنان <span class=\"hlight\">:</span> و مال ایتام و عجایز چون شیر مادر حلال دانند. (مجالس سعدی ص <span class=\"hlight\" dir=\"rtl\">٢٦</span>). رجوع به عجائز شود.<br /></font></div>'),
(181467, 'عجب', '<span class=\"hlight\">عجب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) بُن ِ دنب . گویند آن نخستین چیزی است که آفریده شده و آخر چیزی است که پوسیده میشود.(منتهی الارب ) (آنندراج ). اصل الذنب عند رأس العصعص . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سپس ِ هر چیزی . (اقرب الموارد) (منتهی الارب ). پایان . <BR><font color=\"Blue\">◄</font> ریگ . (منتهی الارب ). و منه عجب الکثیب و هو آخره المستدق .<br /></font></div>'),
(181468, 'عجب', '<span class=\"hlight\">عجب .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) قبیله ای است . (آنندراج ) (منتهی الارب ).<br /></font></div>'),
(181469, 'عجب', '<span class=\"hlight\">عجب .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ع مص ) ناشناختن چیزی که وارد شود. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> به شگفتی آمدن از کسی . (منتهی الارب ). شگفتگی . (مهذب الاسماء). شگفتی که آدمی را دست دهد هنگام بزرگ شمردن چیزی . کار شگفت . (منتهی الارب ) (آنندراج ) (اقرب الموارد) <span class=\"hlight\">:</span> <br />عجب نیست از رستم نامور<br />که دارد دلیری چو دستان پدر.<br /> <font color=\"Red\">فردوسی .</font><br />گفتا عجب است این که ز چوب است و ز آهن <br />این تیزی و تندی و پریدنْش کجا خاست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />عجب تر زین ندیدم داستانی <br />دو تن ترسد ز بشکسته کمانی .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />عجب نبود گر از قرآن نصیبت نیست جز نقشی <br />که از خورشید جز گرمی نبیند چشم نابینا.<br /> <font color=\"Red\">سنائی .</font><br />ور سایه ز من بریده گردد<br />هم نیست عجب ز روزگارم .<br /> <font color=\"Red\">خاقانی .</font><br />اثر نماند ز من در غم تو این عجب است <br />که در دل تو از این غم اثر نمیگردد.<br /> <font color=\"Red\">خاقانی .</font><br />صیدگری بود عجب تیزبین <br />بادیه پیمای و مراحل گزین .<br /> <font color=\"Red\">نظامی .</font><br />عجب از طبعهوسناک منت می آید<br />من خود از مردم بی طبع عجب میمانم .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ای عجب </span> ؛ شگفتا. عجبا <span class=\"hlight\">:</span> <br />شنید این سخن پیشوای ادب <br />بتندی برآشفت و گفت ای عجب .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">العجب ثم العجب، یا للعجب، بوالعجب </span> ؛ در مقام پدیدار شدن حوادث بعیده و مشاهده ٔ امور غریبه گویند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عجب ٌ عاجب </span> ؛ مبالغه است مانند شعر شاعر. (اقرب الموارد).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عجب ٌ عُجاب </span> ؛ مبالغه است . (اقرب الموارد).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عجب ٌ عجیب </span> ؛ مبالغه است، مانند ظل ظلیل . (اقرب الموارد).<br /></font></div>'),
(181470, 'عجب', '<span class=\"hlight\">عجب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b>(ع اِمص ) ناز. (منتهی الارب ). زهو. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خویشتن بینی . (منتهی الارب ) <span class=\"hlight\">:</span> <br />بچشم عجب و تکبر نگه بخلق مکن <br />که دوستان خدا ممکن اند در اوباش .<br /> <font color=\"Red\">سعدی .</font><br />و در اصطلاح عرفا عبارت از خودبینی و خوشنودی از کردار خویشتن باشد. (کشاف اصطلاحات ) <span class=\"hlight\">:</span> <br />ساقی بیار آیی از چشمه ٔخرابات <br />تا خرقه ها بشوئیم از عجب خانقاهی .<br /> <font color=\"Red\">حافظ.</font><br />بعجب علم نتوان شد ز اسباب طرب محروم <br />بیا ساقی که جاهل را هنی تر میرسد روزی .<br /> <font color=\"Red\">حافظ.</font><br /><BR><font color=\"Blue\">◄</font> رأی خودرا به صواب و از آن دیگران را خطا دیدن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناشناختن چیزی که پیش آید. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> انکار آنچه بر تو وارد آید. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گردن کشی . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> کبر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) آنکه نشستن با زنان و محادثه با ایشان را خوش دارد یا زنان خوش آیند او را. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181471, 'عجب آمدن', '<span class=\"hlight\">عجب آمدن .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ م َ دَ ]</font></b> (مص مرکب ) به شگفت آمدن . تعجب کردن . به شگفت ماندن <span class=\"hlight\">:</span> <br />سختم عجب آید که چگونه بردش خواب <br />آن را که به کاخ اندر یک شیشه شراب است .<br /> <font color=\"Red\">منوچهری .</font><br />عشق پیرانه سر از من عجبت می آید<br />چه جوانی تو که از دست ببردی دل پیر.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(181472, 'عجب داشتن', '<span class=\"hlight\">عجب داشتن .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ت َ ]</font></b> (مص مرکب ) شگفت داشتن . به شگفت بودن . تعجب کردن <span class=\"hlight\">:</span> <br />عجب دارم ار شرم دارد ز من <br />که شرمم نمیآید از خویشتن .<br /> <font color=\"Red\">سعدی .</font><br />عجب دارم از خواب آن سنگدل <br />که خلقی بخسبند از او تنگدل .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />بخندید و بگریست مرد خدای <br />عجب داشت سنگین دل تیره رای .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />عجب میداشتم دیشب ز حافظ جام پیمانه <br />ولی منعش نمیکردم که صوفی وار می آورد.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(181473, 'عجب رود', '<span class=\"hlight\">عجب رود.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (اِ مرکب ) نام سازی است که مینوازند و بعضی گویند از قسم مزامیر است که سازهای نی باشد و بعضی صدا وآواز ساز نی را عجب رود گویند. (برهان ) <span class=\"hlight\">:</span> <br />یکی گوش دارد برود و رباب <br />یکی در عجب رود نوشد شراب .<br /> <font color=\"Red\">امیرخسرو.</font><br />عجب رود از کمین دندان نموده <br />لبش نی و دهن خندان نموده .<br /> <font color=\"Red\">امیرخسرو (از آنندراج ).</font><br />چو هندو نوازد عجب رود خویش <br />بخندد عجب رود بر دست او.<br /><font color=\"Red\">امیرخسرو (از آنندراج ).</font><br /></font></div>'),
(181474, 'عجب شیر', '<span class=\"hlight\">عجب شیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (اِخ ) نام یکی از بخشهای شهرستان مراغه، در شمال باختری شهرستان واقع است . از شمال به بخش دهخوارقان، از جنوب و باختر به دریاچه ٔ ارومیه، از خاور به بخش مرکزی مراغه محدود است، بخش مزبور از یک دهستان به نام دیزجرود که از <span class=\"hlight\" dir=\"rtl\">٢٤</span> آبادی بزرگ و کوچک تشکیل میشود و نفوس آن به اضافه ٔ سکنه ٔ قصبه در حدود <span class=\"hlight\" dir=\"rtl\">٢٠١٠٠</span> تنند. هوای آن معتدل است . آب آن از رودخانه قلعه چای و چشمه سارها تأمین میشود. محصولات عمده ٔ آن غلات، کشمش، بادام و میوه جات و سردرختی است . صنایع دستی آنها جاجیم و گلیم بافی است . شغل اهالی زراعت و کاسبی است . راه ارابه رو دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(181475, 'عجب شیر', '<span class=\"hlight\">عجب شیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (اِخ ) قصبه ٔ مرکزی بخش دهستان دیزجرود از شهرستان مراغه، واقع در <span class=\"hlight\" dir=\"rtl\">٣٥</span> هزارگزی شمال باختری مراغه به دهخوارقان . ناحیه ای است کوهستانی . آب و هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٤٤٦٩</span> تن سکنه دارد. آب آن از رودخانه و چشمه تأمین میشود. محصولات آن کشمش، غلات، بادام، میوه جات وشغل اهالی زراعت و کاسبی و صنایع دستی آنها جاجیم بافی است . راه ارابه رو دارد. مختصات آن : طول <span class=\"hlight\" dir=\"rtl\">٤٥</span> درجه و<span class=\"hlight\" dir=\"rtl\">٥٥</span> دقیقه، عرض <span class=\"hlight\" dir=\"rtl\">٣٧</span> درجه و <span class=\"hlight\" dir=\"rtl\">٢٨</span> دقیقه، ارتفاع <span class=\"hlight\" dir=\"rtl\">١٣٣٠</span> متر، اختلاف ساعت با تهران <span class=\"hlight\" dir=\"rtl\">٢١</span> دقیقه و <span class=\"hlight\" dir=\"rtl\">٣٦</span> ثانیه است . ادارات پست و تلگراف و تلفن و بخشداری و شهرداری و دارائی و کشاورزی و بهداری و آمار و ژاندارمری و محضر رسمی و دبستان دارد. آثار قدیمی یک امامزاده زیبا که زیارتگاه است دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(181476, 'عجب ماندن', '<span class=\"hlight\">عجب ماندن .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ دَ ]</font></b> (مص مرکب ) در شگفت ماندن . به شگفت ماندن . به تعجب ماندن . رجوع به عَجَب شود.<br /></font></div>'),
(181477, 'عجب نمودن', '<span class=\"hlight\">عجب نمودن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ دَ ]</font></b> (مص مرکب ) تکبر کردن . خود را برتر دانستن . رجوع به عُجب شود.<br /></font></div>'),
(181478, 'عجبی', '<span class=\"hlight\">عجبی .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (اِخ ) ابن عثمان سعدبن عبداﷲبن ابی رجاء العجبی الانباری معروف به ابن عجب . از هشام بن عمار و ابی عمرالدوری المقری و جز آنان روایت کند و ابوبکر شافعی و ابوبکر الاسماعیلی و ابن مخلد و جز آنان از وی روایت دارند. وی به سال <span class=\"hlight\" dir=\"rtl\">٢٩٨</span> هَ . ق . در جمادی الاَّخره به انبار درگذشت . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span>).<br /></font></div>'),
(181479, 'عجد', '<span class=\"hlight\">عجد.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ع اِ) ج ِ عجدة. (اقرب الموارد) (منتهی الارب ). رجوع به عجدة شود.<br /></font></div>'),
(181480, 'عجد', '<span class=\"hlight\">عجد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) دانه ٔ مویز یا مویز پست هیچکاره . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> حب انگور. (اقرب الموارد) (آنندراج ). <BR><font color=\"Blue\">◄</font> میوه ای است که به مویز ماند. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181481, 'عجد', '<span class=\"hlight\">عجد.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) مویز یا میوه ای که به مویز ماند. <BR><font color=\"Blue\">◄</font> دانه ٔ انگور. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181482, 'عجر', '<span class=\"hlight\">عجر.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ع مص )درشت گردیدن و پرگوشت گشتن . <BR><font color=\"Blue\">◄</font> بزرگ شکم شدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> درشت و فربه گردیدن اسب . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) مغندگی و بیرون آمدگی هر چیزی . (منتهی الارب ).<br /></font></div>'),
(181483, 'عجر', '<span class=\"hlight\">عجر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) گردن تافتن . (منتهی الارب ) (اقرب الموارد) (آنندراج ). <BR><font color=\"Blue\">◄</font> درگذشتن از بیم و مانند آن . (منتهی الارب ) (آنندراج ). به شتاب درگذشتن از بیم و مانند آن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> دنب برداشتن اسب در دویدن و به شتاب رفتن . <BR><font color=\"Blue\">◄</font> به شمشیر آهنگ کردن بر کسی . <BR><font color=\"Blue\">◄</font> برجستن خر. (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> بازداشتن قاضی کسی را از کاری . (منتهی الارب ) (آنندراج ). حجر کردن قاضی کسی را. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ستیهیدن . (منتهی الارب ) (آنندراج ). ستیهیدن بر کسی در گرفتن مال وی، وبدین معنی جز مجهول استعمال نشود. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سر باز گردانیدن ستور به سوی دیگر بعد ازبرنشستن . (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181484, 'عجر', '<span class=\"hlight\">عجر.</span> <font color=\"DarkGreen\"><b>[ ع َ ج ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ج ُ ]</font></b> (ع ص، اِ) بند ساق و ذراع استوار و درشت . (منتهی الارب ). وظیف عجر؛ سخت و محکم . (اقرب الموارد).<br /></font></div>'),
(181485, 'عجر', '<span class=\"hlight\">عجر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ج َ ]</font></b> (ع اِ) ج ِ عُجرة. (منتهی الارب ). رجوع به عجرة شود.<br /></font></div>'),
(181486, 'عجران', '<span class=\"hlight\">عجران .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) گردن تافتن . <BR><font color=\"Blue\">◄</font> درگذشتن از بیم و مانند آن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181487, 'عجرد', '<span class=\"hlight\">عجرد.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع ص ) سبک سریع. <BR><font color=\"Blue\">◄</font> درشت و سخت . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) نره . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181488, 'عجرد', '<span class=\"hlight\">عجرد.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َرْ رَ ]</font></b> (ع ص ) دلاور. (منتهی الارب ). الجری ٔ. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> برهنه . (منتهی الارب ) (آنندراج ). منجرد. (اقرب الموارد).<br /></font></div>'),
(181489, 'عجردی', '<span class=\"hlight\">عجردی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ دی ی ]</font></b> (ص نسبی ) نسبت است به طائفه ای از خوارج از ازارقه منسوب به عبدالکریم بن عجرد و او از اصحاب عطیة الاسود الحنفی یمامی است . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span>). و رجوع به عجارده شود.<br /></font></div>'),
(181490, 'عجرشیه', '<span class=\"hlight\">عجرشیه .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ شی ی َ ]</font></b> (اِخ ) دهی است از دهستان باوی بخش مرکزی شهرستان اهواز، واقع در <span class=\"hlight\" dir=\"rtl\">٦٠</span> هزارگزی جنوب باختری اهواز و <span class=\"hlight\" dir=\"rtl\">٩</span> هزارگزی باختری راه اهواز به آبادان . دشت و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه دارد. آب آن از رود کارون و موتور آب تأمین میشود. محصولات آن غلات و صیفی و شغل اهالی زراعت است . در تابستان راه اتومبیل رو دارد. ساکنین از طایفه ٔ آل ابوعطی اند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(181491, 'عجرفة', '<span class=\"hlight\">عجرفة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ف َ ]</font></b> (ع اِمص ) درشتی در سخن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شکستگی و ناراستی کار. (منتهی الارب ) (آنندراج ).خرق فی العمل . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتابزدگی و بی باکی . (منتهی الارب ) (آنندراج ). درشدن در کاری بدون اندیشه . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سرعت و قلت مبالات . (منتهی الارب ) (آنندراج ). قلت مبالات .<br /></font></div>'),
(181492, 'عجرفی', '<span class=\"hlight\">عجرفی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ فی ی ]</font></b> (ع ص ) سریع. شتابزده . یقال الجمل عجرفی المشی . (منتهی الارب ) (از اقرب الموارد).<br /></font></div>'),
(181493, 'عجرفیة', '<span class=\"hlight\">عجرفیة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ی ی َ ]</font></b> (ع اِمص ) سرعت و قلت مبالات . (منتهی الارب ). یقال فی الجَمل عجرفیة فی المشی اذا کان لایبالی لسرعته . (المنجد) (اقرب الموارد).<br /></font></div>'),
(181494, 'عجرقب', '<span class=\"hlight\">عجرقب .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ق َ ]</font></b> (ع ص ) متشکی پلید. (منتهی الارب ). المریب الخبیث . (اقرب الموارد) (تاج العروس ). شک آورنده ٔ پلید خبیث .<br /></font></div>'),
(181495, 'عجرم', '<span class=\"hlight\">عجرم .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ]</font></b> (اِخ ) موضعی است و بدو ذو اضافه شود (ذوعجرم ). (معجم البلدان ). رجوع به ذو عجرم شود.<br /></font></div>'),
(181496, 'عجرم', '<span class=\"hlight\">عجرم .</span> <font color=\"DarkGreen\"><b>[ع َ رَ ]</font></b> (ع ص ) مرد سخت استواراندام . (منتهی الارب ). الرجل الشدید. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> کوتاه بالای سخت و استوار و سطبر پرگوشت . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) فراهم آمدنگاه گرههای میان ران . <BR><font color=\"Blue\">◄</font> بن نره ٔ ستور. (منتهی الارب ).<br /></font></div>'),
(181497, 'عجرم', '<span class=\"hlight\">عجرم .</span> <font color=\"DarkGreen\"><b>[ ع ِ رِ ]</font></b> (ع اِ) جانورکی است نیک سخت اندام که بر درخت میباشد. (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181498, 'عجرم', '<span class=\"hlight\">عجرم .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ]</font></b> (ع ص ) شترسخت اندام . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مرد درشت خلقت . (منتهی الارب ). الرجل الشدید. (اقرب الموارد).<br /></font></div>'),
(181499, 'عجرمة', '<span class=\"hlight\">عجرمة.</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ م َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ رِ م َ ]</font></b> (ع اِ) درختی است خاردار بسیارگره . (اقرب الموارد). درختی است بزرگ که آن را گره ها است واز آن کمان سازند. (معجم البلدان ). درختی است . (منتهی الارب ). ج، عُجْرُم و عِجْرِم . <BR><font color=\"Blue\">◄</font> (ص ) ماده شتر درشت سخت . الناقة الشدیدة. (اقرب الموارد).<br /></font></div>'),
(181500, 'عجرمة', '<span class=\"hlight\">عجرمة.</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ م َ ]</font></b> (ع ص ) مؤنث عجرم . رجوع به عجرم شود.<br /></font></div>'),
(181501, 'عجرمة', '<span class=\"hlight\">عجرمة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ م َ ]</font></b> (ع مص ) شتافتن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) صد شتر یا دو صد یا مابین پنجاه تا صد. (اقرب الموارد) (منتهی الارب ). و بدین معنی عُرُمَة و عِجرِمَة نیز آمده است . <BR><font color=\"Blue\">◄</font> (ص ) مؤنث عجرم . رجوع به عجرم شود.<br /></font></div>'),
(181502, 'عجرمی', '<span class=\"hlight\">عجرمی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) حسین بن ابراهیم بن عامربن ابی عجرم المقری الانطاکی العجرمی مکنی به ابوعیسی . از عبداﷲبن محمدبن اسحاق و جز او روایت کند و ابوبکر بن المقری و دیگران از وی روایت دارند. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span>).<br /></font></div>'),
(181503, 'عجرمی', '<span class=\"hlight\">عجرمی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ می ی ]</font></b> (ص نسبی ) نسبت است به عجرم وآن جدّ اَبی عیسی است . رجوع به عجرمی ابی عیسی شود.<br /></font></div>'),
(181504, 'عجرور', '<span class=\"hlight\">عجرور.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) خطی که از باد بر ریگ پیدا گردد. ج، عجاریر. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181505, 'عجروز', '<span class=\"hlight\">عجروز.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) عُجْرور. خطی که از باد بر ریگ پیدا گردد. ج، عَجاریز. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181506, 'عجروف', '<span class=\"hlight\">عجروف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) ناقه ٔ چست سبک . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) جانورکی است . (منتهی الارب ). جانورکی است درازپا.(اقرب الموارد). <BR><font color=\"Blue\">◄</font> مورچه ٔ درازپا تیزرو.(اقرب الموارد) (منتهی الارب ). و قیل النمل الطویل الارجل الذی رفعته عن الارض قوائمه . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گنده پیر. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181507, 'عجروفة', '<span class=\"hlight\">عجروفة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ف َ ]</font></b> (ع اِ) گنده پیر. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181508, 'عجری', '<span class=\"hlight\">عجری .</span> <font color=\"DarkGreen\"><b>[ ع ُ ری ی ]</font></b> (ع ص ) دروغگوی . (منتهی الارب ). کذب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) بلا و سختی . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181509, 'عجز', '<span class=\"hlight\">عجز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) ناتوان گردیدن . (اقرب الموارد) (منتهی الارب ) (آنندراج ). ناتوانی . توانا نبودن . ناتوان بودن <span class=\"hlight\">:</span> <br />بباید مرا شد به آوارگی <br />نهادن به خود عجز و بیچارگی .<br /> <font color=\"Red\">فردوسی (ملحقات شاهنامه داستان جمشید، ص <span class=\"hlight\" dir=\"rtl\">٣٥</span>).</font><br />در همه چیزها که بینی هست <br />خلق را عجز و خواجه را اعجاز.<br /> <font color=\"Red\">فرخی .</font><br />دمنه گفت ای برادر ضعف رأی و عجز من بنگر، عجز پیری و ضعف آن . (کلیله و دمنه ).<br />بودم از عجزچون خران در گل <br />بر جهان اسب تاختم چون برق .<br /> <font color=\"Red\">خاقانی .</font><br />گر ترا آنجا کشد نبود عجب <br />منگر اندر عجز بنگر در طلب .<br /> <font color=\"Red\">مولوی .</font><br />یاران نهایت عجز او بدانستند سفره پیش آوردند. (گلستان ).<br />روی بر خاک عجز میگویم <br />هر سحرگه که باد می آید.<br /> <font color=\"Red\">سعدی (گلستان ).</font><br /><BR><font color=\"Blue\">◄</font> ترک دادن چیزی را که کردن آن واجب بود. <BR><font color=\"Blue\">◄</font> کاهلی کردن . <BR><font color=\"Blue\">◄</font> غالب آمدن بر کسی در معاجزة. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> در اصطلاح معقول ضد قدرت است و بگفته ای عدم قدرت است از باب عدم ملکه . (از کشاف اصطلاحات ). <BR><font color=\"Blue\">◄</font> (اِ) شمشیر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> قبضه ٔ شمشیر. <BR><font color=\"Blue\">◄</font> بیماری است در سرین ستور.(منتهی الارب ) (آنندراج ). داء فی عَجُز الدابة. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> پرنده ای است . (منتهی الارب )(آنندراج ). پرنده ای است آن را زمج گویند. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سرین . (منتهی الارب ). و بدین معنی به کسر و ضم اول هم آمده است . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بن هر چیزی . (منتهی الارب ) (اقرب الموارد). وبضم و کسر اول نیز آمده است . (منتهی الارب ).<br /></font></div>'),
(181510, 'عجز', '<span class=\"hlight\">عجز.</span> <font color=\"DarkGreen\"><b>[ ع َ ج ُ <span class=\"hlight\" dir=\"rtl\">/</span> ج ِ ]</font></b> (ع اِ) سرین و بن هر چیز. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> در اصطلاح عروضیان و شعراء آخر کلمه از بیت یا فقره را گویند که ضرب هم نامند. (از کشاف ص <span class=\"hlight\" dir=\"rtl\">٩٧٥</span>).<br /></font></div>'),
(181511, 'عجز', '<span class=\"hlight\">عجز.</span> <font color=\"DarkGreen\"><b>[ ع ُ ج ُ ]</font></b> (اِخ ) دهی است به حضرموت . (معجم البلدان ).<br /></font></div>'),
(181512, 'عجز', '<span class=\"hlight\">عجز.</span> <font color=\"DarkGreen\"><b>[ ع ُ ج ُ ]</font></b> (ع اِ) ج ِ عجوز.<br /></font></div>'),
(181513, 'عجز', '<span class=\"hlight\">عجز.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ]</font></b> (ع مص ) کلان و بزرگ سرین گردیدن زن . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181514, 'عجز آوردن', '<span class=\"hlight\">عجز آوردن .</span> <font color=\"DarkGreen\"><b>[ ع َ وَ دَ ]</font></b> (مص مرکب ) درماندگی نمودن . ناتوانی کردن . ناتوان بودن <span class=\"hlight\">:</span> <br />ما عشق ترا به یادگار آوردیم <br />بر خاک تو عجز و افتقار آوردیم .<br /></font></div>'),
(181515, 'عجز داشتن', '<span class=\"hlight\">عجز داشتن .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (مص مرکب ) ناتوان بودن . عاجز بودن . توانا نبودن .<br /></font></div>'),
(181516, 'عجز و لابه', '<span class=\"hlight\">عجز و لابه .</span> <font color=\"DarkGreen\"><b>[ ع َ زُ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (ترکیب عطفی، اِ مرکب )تضرع . زاری و ناله و فریاد. گریه و زاری . <BR><font color=\"Blue\">◄</font> خواهش و تمنا. رجوع به عجز و رجوع به لابه شود.<br /></font></div>'),
(181517, 'عجزان', '<span class=\"hlight\">عجزان .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ع مص ) ناتوان گردیدن . <BR><font color=\"Blue\">◄</font> ترک کردن چیزی را که کردن آن واجب شود. <BR><font color=\"Blue\">◄</font> کاهلی کردن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181518, 'عجس', '<span class=\"hlight\">عجس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) بازداشتن کسی را از حاجتش . (ازاقرب الموارد) (منتهی الارب ) (آنندراج ) (تاج المصادر). <BR><font color=\"Blue\">◄</font> بازگردانیدن شتر را از راه جهت نشاط. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> به پنجه گرفتن چیزی را. (منتهی الارب ). به پنجه گرفتن چیزی را یا سخت گرفتن آن را. (از اقرب الموارد). سخت گرفتن چیزی را. (تاج المصادر). <BR><font color=\"Blue\">◄</font> (اِ) میانه ٔ چیزی . (منتهی الارب ) (آنندراج ) (اقرب الموارد).<br /></font></div>'),
(181519, 'عجس', '<span class=\"hlight\">عجس .</span> <font color=\"DarkGreen\"><b>[ ع َج ْ ج َ ]</font></b> (اِخ ) دهی است به مغرب . سمعانی گوید: دهی است از دهات عسقلان که عسقلانی بدان منسوب است . (معجم البلدان ).<br /></font></div>'),
(181520, 'عجس', '<span class=\"hlight\">عجس .</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ]</font></b> (ع اِ) قبضه ٔ کمان . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> پاره ای از میانه ٔ شب یا آخر شب یا پاره ای از شب . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181521, 'عجسة', '<span class=\"hlight\">عجسة.</span> <font color=\"DarkGreen\"><b>[ ع ُ س َ ]</font></b> (ع اِ) ساعتی از شب . (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پگاه . (منتهی الارب ). سُحرة. (از اقرب الموارد).<br /></font></div>'),
(181522, 'عجسمة', '<span class=\"hlight\">عجسمة.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ م َ ]</font></b> (ع اِمص ) سبکی . <BR><font color=\"Blue\">◄</font> شتابی . <BR><font color=\"Blue\">◄</font> (مص ) سبک گردیدن . <BR><font color=\"Blue\">◄</font> شتافتن . (منتهی الارب ).<br /></font></div>'),
(181523, 'عجسمة', '<span class=\"hlight\">عجسمة.</span><font color=\"DarkGreen\"><b>[ ع َ س َ م َ ]</font></b> (اِخ ) دهی است کوچک از دهستان جراحی بخش شادگان شهرستان خرمشهر، واقع در <span class=\"hlight\" dir=\"rtl\">٥٨</span> هزارگزی شمال خاوری شادگان کنار راه اتومبیل رو اهواز به شادگان . <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(181524, 'عجسی', '<span class=\"hlight\">عجسی .</span> <font color=\"DarkGreen\"><b>[ ع َ ج ِ ج َ ]</font></b> (ص نسبی ) نسبت است به عجس، مؤلف لباب آرد: و بگمان من دهی است از دهات عسقلان . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span>).<br /></font></div>'),
(181525, 'عجسی', '<span class=\"hlight\">عجسی .</span> <font color=\"DarkGreen\"><b>[ ع َج ْ ج َ ]</font></b> (اِخ ) ذاکربن شیبة العسقلانی العجسی . از ابی عصام روادبن الجراح روایت کند و ابوالقاسم ابطرانی در ده عجس از وی حدیث شنید. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span>).<br /></font></div>'),
(181526, 'عجف', '<span class=\"hlight\">عجف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) بازداشتن خود را از خوردن با وجود گرسنگی تا دیگری را بخوراند یا سیر خورانیدن طعام خود را. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> صابر داشتن نفس خود را بر تیمار بیمار. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> برداشت نمودن از کسی و مؤاخذه نکردن . <BR><font color=\"Blue\">◄</font> لاغر کردن ستور را. <BR><font color=\"Blue\">◄</font> جدا شدن از کسی و دور ماندن . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بردبار گردانیدن نفس را. (منتهی الارب ).<br /></font></div>'),
(181527, 'عجف', '<span class=\"hlight\">عجف .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ع اِمص ) لاغری . (غیاث اللغات ) (منتهی الارب ) (بحرالجواهر). <BR><font color=\"Blue\">◄</font> (مص ) لاغر شدن . (تاج المصادر) (منتهی الارب ) (از اقرب الموارد).<br /></font></div>'),
(181528, 'عجف', '<span class=\"hlight\">عجف .</span> <font color=\"DarkGreen\"><b>[ ع َ ج ِ ]</font></b> (ع ص ) لاغر. (از اقرب الموارد).<br /></font></div>'),
(181529, 'عجفا', '<span class=\"hlight\">عجفا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دختر علقمة السعدی است . وی از زنان فصیح جاهلیت بود و نخستین کس است که مثل مشهور «کل فتاة بابیها معجبة» بگفت .(از الاعلام زرکلی وفیات الاعیان و امثال المیدانی ).<br /></font></div>'),
(181530, 'عجفاوان', '<span class=\"hlight\">عجفاوان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) شفتان عجفاوان، دو لب باریک . (منتهی الارب ) (از اقرب الموارد).<br /></font></div>'),
(181531, 'عجفی', '<span class=\"hlight\">عجفی .</span> <font color=\"DarkGreen\"><b>[ ع َ فا ]</font></b> (ع ص ) لاغر، یقال قوم عجفی و نسوة عجفی . (منتهی الارب ).<br /></font></div>'),
(181532, 'عجل', '<span class=\"hlight\">عجل .</span> <font color=\"DarkGreen\"><b>[ ع َ ج ِ <span class=\"hlight\" dir=\"rtl\">/</span> ج ُ ]</font></b> (ع ص ) شتاب کننده . (اقرب الموارد). سریع. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آنکه بدین جهان خرسند باشد. (اقرب الموارد).<br /></font></div>'),
(181533, 'عجل', '<span class=\"hlight\">عجل .</span> <font color=\"DarkGreen\"><b>[ ع ُ ج ُ ]</font></b> (ع ص ) ج ِ عجول . (منتهی الارب ) (از اقرب الموارد).<br /></font></div>'),
(181534, 'عجل', '<span class=\"hlight\">عجل .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ع مص ) شتافتن . (اقرب الموارد) (منتهی الارب ) (ترجمان علامه ) <span class=\"hlight\">:</span> <br />حکمت حق مانع آید زین عجل <br />جمعشان دارد به صحبت تا اجل .<br /> <font color=\"Red\">مولوی (مثنوی ).</font><br /><BR><font color=\"Blue\">◄</font> بطی ٔ شمردن امری را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) گل و لای . (آنندراج ) (منتهی الارب ). قال اﷲ <span class=\"hlight\">:</span> خلق الانسان من عجل . (قرآن <span class=\"hlight\" dir=\"rtl\">٣٧/٢١</span>). <BR><font color=\"Blue\">◄</font> لای سیاه بدبو. (منتهی الارب ) (اقرب الموارد) (مهذب الاسماء).<br /></font></div>'),
(181535, 'عجل', '<span class=\"hlight\">عجل .</span> <font color=\"DarkGreen\"><b>[ ع ِ ج َ ]</font></b> (ع اِ) ج ِ عِجلة. (منتهی الارب ). رجوع به عِجله شود.<br /></font></div>'),
(181536, 'عجل', '<span class=\"hlight\">عجل .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) گوساله . (منتهی الارب ) (اقرب الموارد) (آنندراج ). گوساله ٔ اول سال . (اقرب الموارد) (غیاث اللغات ). ج، عُجول <span class=\"hlight\">:</span> آل موسی کو دریغا تا کنون <br />عابدان عجل را ریزند خون .<br /> <font color=\"Red\">مولوی (مثنوی ).</font><br />قد شابَه َ بالوَری ̍ حِمارٌ<br />عِجْلاً جسداً له خُوارٌ.<br /> <font color=\"Red\">سعدی (گلستان ).</font><br />بچه ٔ گاو چون از مادر بزمین آید عجل بود. (از تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٨١٨</span>).<br /></font></div>'),
(181537, 'عجلان', '<span class=\"hlight\">عجلان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن رُمَیثةبن ابی نمی، از امراء مکه است . مولد و وفاتش به مکه بود. پدر وی به سال <span class=\"hlight\" dir=\"rtl\">٧٤٥</span> هَ . ق . ولایت را بدو واگذارد و به سال <span class=\"hlight\" dir=\"rtl\">٧٧٧</span> درگذشت . (از اعلام زرکلی ).<br /></font></div>'),
(181538, 'عجلان', '<span class=\"hlight\">عجلان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) تیزرو و سریع. (منتهی الارب ) (اقرب الموارد). ج، عَجالی ̍ و عِجال و عُجالی ̍. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) ماه شعبان . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) نام مردی . <BR><font color=\"Blue\">◄</font> نام بطنی از انصار. <BR><font color=\"Blue\">◄</font> ام عجلان نام مرغی است . (ناظم الاطباء).<br /></font></div>'),
(181539, 'عجلانی', '<span class=\"hlight\">عجلانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ص نسبی ) نسبت است به بنی عجلان بن زید. رجوع به عجلانی و عجلان بن زید شود.<br /></font></div>'),
(181540, 'عجلانی', '<span class=\"hlight\">عجلانی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ثابت بن اقرم بن ثعلبةبن عدی بن العجلانی .رجوع به ثابت بن اقرم شود. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٥</span>).<br /></font></div>'),
(181541, 'عجلانی', '<span class=\"hlight\">عجلانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) عبدالواحدبن ابی البداح بن عاصم بن عدی الانصاری العجلانی . از مردم مدینه است . از عبدالرحمن بن یزیدبن طرفة روایت کند و ابن اسحاق از وی روایت دارد. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٥</span>).<br /></font></div>'),
(181542, 'عجلانی', '<span class=\"hlight\">عجلانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) عجلان بن زیدبن غنم بن سالم بن عوف بن الخزرج، بطنی از انصار است . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٥</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(181543, 'عجلانیة', '<span class=\"hlight\">عجلانیة.</span> <font color=\"DarkGreen\"><b>[ ع َ نی ی َ ]</font></b> (اِخ ) شهرکی است به ثغور مرج دیباج نزدیک مصیقه . (معجم البلدان ).<br /></font></div>'),
(181544, 'عجلة', '<span class=\"hlight\">عجلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ل َ ]</font></b> (اِخ ) از دهات ذمار به یمن است . (معجم البلدان ).<br /></font></div>'),
(181545, 'عجلة', '<span class=\"hlight\">عجلة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ل َ]</font></b> (اِخ ) موضعی است نزدیک انبار و بنام عجلة دختر عمروبن عدی، جد ملوک لخم موسوم است . (معجم البلدان ).<br /></font></div>'),
(181546, 'عجلة', '<span class=\"hlight\">عجلة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ل َ ]</font></b> (ع اِ) گوساله ٔ ماده .(منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سقاء. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خیک روغن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> دولاب . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> توشه دان . (منتهی الارب ) (آنندراج ). ج، عِجَل، عِجال، عَجال . <BR><font color=\"Blue\">◄</font> نوعی از گیاه . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181547, 'عجلة', '<span class=\"hlight\">عجلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ل َ ]</font></b> (ع اِ) گردون که بر او بار کشند. (منتهی الارب ) (از اقرب الموارد). آلتی که بار بر آن نهند و آن را گاو کشد. (از اقرب الموارد). ج، عَجَل، اَعجال، عِجال . <BR><font color=\"Blue\">◄</font> دولاب . (منتهی الارب ) (ازاقرب الموارد). <BR><font color=\"Blue\">◄</font> چوب بر پهنای سر چاه که دلو بدان آویخته شود. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> چوب با هم بسته که بر آن رخت نهند. (منتهی الارب ). خشب تؤلف، یحمل علیها الاثقال . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گِل . <BR><font color=\"Blue\">◄</font> گِل سیاه . <BR><font color=\"Blue\">◄</font> پایه ای مر خرمابن را و آن چنان باشد که تنه ٔ آن جای جای بکاوند تا بدان بر آن برآیند. (اقرب الموارد) (منتهی الارب ). الدرجة من النخل نحو النقیر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) خفت . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سرعت . (ترجمان ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (مص ) شتاب کردن . (اقرب الموارد).<br /></font></div>'),
(181548, 'عجلد', '<span class=\"hlight\">عجلد.</span> <font color=\"DarkGreen\"><b>[ ع ُ ج َل ِ ]</font></b> (ع ص ) شیر خفته . یا شیر دفزک زده و جغرات شده . (منتهی الارب ). اللبن الخاثر جداً. (اقرب الموارد).<br /></font></div>'),
(181549, 'عجلز', '<span class=\"hlight\">عجلز.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ل ِ ]</font></b> (ع ص ) رجوع به علجزة شود.<br /></font></div>'),
(181550, 'عجله داشتن', '<span class=\"hlight\">عجله داشتن .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ت َ ]</font></b> (مص مرکب ) شتاب داشتن .<br /></font></div>'),
(181551, 'عجله نمودن', '<span class=\"hlight\">عجله نمودن .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ دَ ]</font></b> (مص مرکب ) عجله کردن .<br /></font></div>'),
(181552, 'عجله کردن', '<span class=\"hlight\">عجله کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ک َ دَ ]</font></b> (مص مرکب ) شتاب کردن در کاری . عجله نمودن .<br /></font></div>'),
(181553, 'عجلون', '<span class=\"hlight\">عجلون .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) پادشاه موآبیان که <span class=\"hlight\" dir=\"rtl\">١٨</span> سال بنی اسرائیل رابنده ٔ خود گردانید و با عمونیان و عمالقه معاهده نموده، اریحا را مفتوح ساخته، در آنجا ساکن شد تا وقتی که اهود وی را به قتل رسانید. (قاموس کتاب مقدس ).<br /></font></div>'),
(181554, 'عجلون', '<span class=\"hlight\">عجلون .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) (گوساله مانند) یکی از شهرهای آموریان که در یهودا بود. و فعلاً آن را عجلان گویند و آن تلی است که به مسافت ده میل بشمال شرقی غزه واقع است . (از قاموس کتاب مقدس ).<br /></font></div>'),
(181555, 'عجلی', '<span class=\"hlight\">عجلی .</span> <font color=\"DarkGreen\"><b>[ ع َ لا ]</font></b> (ع ص ) زن شتاب کار. ج، عجالی ̍. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> کمان تیرزودگذر. (منتهی الارب ). قوس عجلی ؛ ای سریعة السهم .<br /></font></div>'),
(181556, 'عجلی', '<span class=\"hlight\">عجلی .</span> <font color=\"DarkGreen\"><b>[ ع َج ْ ج َ ]</font></b> (ص نسبی ) رجوع به عَجْلی ̍ شود.<br /></font></div>'),
(181557, 'عجلی', '<span class=\"hlight\">عجلی .</span><font color=\"DarkGreen\"><b>[ ع َج ْ ج َ ]</font></b> (اِخ ) عثمان بن علی بن شراف العجلی، مکنی به ابوسعد از اهل بنج دیه است . وی فقیهی فاضل بوده .فتوی میداد. نزد قاضی حسین المروالروذی فقه آموخت واز جماعتی حدیث شنید. در حدود سال <span class=\"hlight\" dir=\"rtl\">٤٤٠</span> هَ . ق . متولد شد و در سال <span class=\"hlight\" dir=\"rtl\">٥٢٦</span> درگذشت . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٤</span>).<br /></font></div>'),
(181558, 'عجلی', '<span class=\"hlight\">عجلی .</span> <font color=\"DarkGreen\"><b>[ ع َ لی ی ]</font></b> (ص نسبی ) نسبت است به عجل بن لجیم بن صعب بن علی بن بکربن وائل . رجوع به عجل بن لجیم و اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٤</span> شود.<br /></font></div>'),
(181559, 'عجلیة', '<span class=\"hlight\">عجلیة.</span> <font color=\"DarkGreen\"><b>[ ع ِ لی ی َ ]</font></b> (اِخ ) فرقه ای از زیدیه . اصحاب هارون عجلی اند که از جهت عقایدشبیه به فرقه بتریه اند. (از خاندان نوبختی ص <span class=\"hlight\" dir=\"rtl\">٢٥٩</span>).<br /></font></div>'),
(181560, 'عجم', '<span class=\"hlight\">عجم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) نقطه نهادن بر حرف و اعراب حروف . (غیاث اللغات ) (آنندراج ). نقطه نهادن حروف کتاب را. (منتهی الارب ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دندان فروبردن یا خائیدن جهت خوردن . (از منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> دندان فروبردن در چیزی بخاطر دانستن سختی و سستی آن . <BR><font color=\"Blue\">◄</font> جنبانیدن شمشیر را جهت آزمودن .(منتهی الارب ) (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گویند: ما عجمتک عینی کذا؛ یعنی نگرفت چشم من تراو نیافت . (مهذب الاسماء) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> حرکت دادن گاو، شاخ خود را و زدن به درخت جهت آزمودن . (اقرب الموارد). گویند: الثور یعجم قرنه، هرگاه دو شاخ به درخت زند تا آن را بیازماید. (منتهی الارب ) (از اقرب الموارد) (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(181561, 'عجم', '<span class=\"hlight\">عجم .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (اِخ ) خلاف عرب . (اقرب الموارد). غیر عرب از مردم . (منتهی الارب ) (از ناظم الاطباء). ایران و توران و مردم غیر عرب را نیز عجم گویند. (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> مردم ایران . ایرانی <span class=\"hlight\">:</span> <br />کجا شد فریدون و ضحاک و جم <br />مهان عرب خسروان عجم .<br /> <font color=\"Red\">فردوسی .</font><br />مرغان بر گل کنند جمله به نیکی دعا<br />بر تن و بر جان میر بارخدای عجم .<br /> <font color=\"Red\">منوچهری .</font><br />مرد را چون هنر بباشد کم <br />چه ز اهل عرب چه ز اهل عجم .<br /> <font color=\"Red\">سنایی .</font><br />تا آخر ایام یزدجردبن شهریار که آخر ملوک عجم بود بدین قرار بماند.(کلیله و دمنه ).<br />تو کعبه ٔ عجم شده او کعبه ٔ عرب <br />او و تو هر دو قبله ٔ انسی و جان شده .<br /><font color=\"Red\">خاقانی .</font><br />غم ترکان عجم کان همه ترک ختنند<br />نخورم چون دل شادان به خراسان مانم .<br /> <font color=\"Red\">خاقانی .</font><br />همه ملک عجم خزانه ٔ من <br />در عرب ماند خیلخانه ٔ من .<br /> <font color=\"Red\">نظامی .</font><br />یکی از ملوک عجم طبیبی حاذق به خدمت مصطفی (ص ) فرستاد. (گلستان ).<br />که را دانی از خسروان عجم <br />ز عهد فریدون و ضحاک و جم .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />چنین گفت شوریده ای در عجم <br />به کسری که ای وارث ملک جم .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br /><BR><font color=\"Blue\">◄</font> (ع اِ) هسته ٔ خرما و انگور و مانند آن، عجمة یکی آن است . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتران ریزه . (منتهی الارب ). اشتران خرد. (مهذب الاسماء).<br /></font></div>'),
(181562, 'عجم', '<span class=\"hlight\">عجم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) غیرعرب . (منتهی الارب ) (از آنندراج ) (اقرب الموارد). کندزبانان و باشندگان ملک عجم . (آنندراج ) (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> شتران ریز. (منتهی الارب ) (از اقرب الموارد).<br /></font></div>'),
(181563, 'عجم', '<span class=\"hlight\">عجم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ج ُم م ]</font></b> (ع ص ) ابل ٌ عُجُم ﱡ؛ شتران که بخوردن خار از شوره خورسند شوند. (منتهی الارب ).<br /></font></div>'),
(181564, 'عجما', '<span class=\"hlight\">عجما.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) کسی را گویند که بهیچ خیر وشری وانرسیده باشد. (آنندراج ) (برهان ) <span class=\"hlight\">:</span> <br />صورت مردم عقل است نگاریده ٔ او<br />چو از او عقل جداگشت همانا عجماست .<br /> <font color=\"Red\">محمد عثمان (از لغت فرس، از حاشیه ٔ برهان ).</font><br /><BR><font color=\"Blue\">◄</font> در عربی حیوان غیرذی عقل و زنی که قادر بر سخن کردن نباشد. (برهان ) (آنندراج ). رجوع به عجماء شود.<br /></font></div>'),
(181565, 'عجمات', '<span class=\"hlight\">عجمات .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ع اِ) ج ِ عَجْمة و عَجَمة. رجوع به همان ماده شود.<br /></font></div>'),
(181566, 'عجماوان', '<span class=\"hlight\">عجماوان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) نماز ظهر و عصر بخاطر خفاء قرأت در آن دو نماز. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181567, 'عجمة', '<span class=\"hlight\">عجمة.</span> <font color=\"DarkGreen\"><b>[ ع ُ م َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ م َ ]</font></b> (ع اِ) ریگ بسته، و گویند بسیاری ریگ . (از اقرب الموارد) (منتهی الارب ). آخر ریگ توده . (منتهی الارب ) (اقرب الموارد). عجمةالرمل ؛ آخره . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) ابهام . <BR><font color=\"Blue\">◄</font> خفا. <BR><font color=\"Blue\">◄</font> عدم فصاحت کلام . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) لفظی که از وضع زبان عربی خارج باشد مانند نوح و لوط و عجمة یکی از اسباب منع صرف است . (از کشاف اصطلاحات الفنون ). رجوع به غیرمنصرف شود.<br /></font></div>'),
(181568, 'عجمة', '<span class=\"hlight\">عجمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ م َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ م َ ]</font></b> ( ع ص، اِ) خرمابن که از هسته روید. <BR><font color=\"Blue\">◄</font> سنگ سخت . (اقرب الموارد) (منتهی الارب ). سنگ سخت کلان که ناقه را به وی تشبیه دهند. (منتهی الارب ). ج، عجمات .<br /></font></div>'),
(181569, 'عجمجمة', '<span class=\"hlight\">عجمجمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ج َ م َ ]</font></b> (ع ص ) ماده شتر استوار و توانابر سفر. (منتهی الارب ) (ناظم الاطباء). ج، عجمجمات .<br /></font></div>'),
(181570, 'عجمستان', '<span class=\"hlight\">عجمستان .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ م ِ ]</font></b> (اِخ ) ممالک فارس . (آنندراج ). ممالک عجم و این اطلاق مربوط به بعد از اسلام است و چون زبان مردم غیرعرب را نمی فهمیدند آن را عجم نام نهادند.<br /></font></div>'),
(181571, 'عجمضی', '<span class=\"hlight\">عجمضی .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ضا ]</font></b> (ع اِ) نوعی از خرمای ریزه . (منتهی الارب ) (از اقرب الموارد).<br /></font></div>'),
(181572, 'عجملو', '<span class=\"hlight\">عجملو.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ بخش سلدوز شهرستان ارومیه، دارای <span class=\"hlight\" dir=\"rtl\">٢٨٧</span> تن سکنه . آب آن از رودگذار. محصول، غلات، برنج، توتون، چغندر و حبوبات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(181573, 'عجمی', '<span class=\"hlight\">عجمی .</span> <font color=\"DarkGreen\"><b>[ع َ ج َ ]</font></b> (اِخ ) دهی است از بخش سراسکند شهرستان تبریز. دارای <span class=\"hlight\" dir=\"rtl\">٤٩٧</span> تن سکنه . آب آن از رودخانه . محصول آن غلات و حبوبات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(181574, 'عجمی', '<span class=\"hlight\">عجمی .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (اِخ ) ابومحمد حبیب بن عیسی العجمی . رجوع به حبیب عجمی شود.<br /></font></div>'),
(181575, 'عجمی', '<span class=\"hlight\">عجمی .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ص نسبی ) باشنده ٔ عجم هرچند که از عرب باشد. (منتهی الارب ). منسوب به عجم . (منتهی الارب ) (اقرب الموارد). نسبت است به عجم و بلاد فارس . (لباب ). <BR><font color=\"Blue\">◄</font> آنکه سخن پیدا گفتن نتواند. (منتهی الارب ). من جنسه العجم و ان أفصح . (اقرب الموارد) <span class=\"hlight\">:</span> <br />راهروان عربی را تو ماه <br />تاجوران عجمی را تو شاه .<br /> <font color=\"Red\">نظامی .</font><br />بردی دل من ای جان چون با تو کنم دعوی <br />خود را عجمی سازی انکار کنی حالی .<br /> <font color=\"Red\">عطار.</font><br />پادشاهی با غلام عجمی در کشتی نشسته بود. (گلستان ).<br /></font></div>'),
(181576, 'عجمی کله بوز', '<span class=\"hlight\">عجمی کله بوز.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ک ُ ل َ ]</font></b>(اِخ ) دهی است از دهستان کله بوز بخش مرکزی شهرستان میانه دارای <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن سکنه . آب آن از چشمه، محصول آن غلات و حبوبات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(181577, 'عجمیات', '<span class=\"hlight\">عجمیات .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ می یا ]</font></b> (ع ص نسبی، اِ) از انواع خیل است که براذین باشد و همالیج نیز نامند. (از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٧</span>).<br /></font></div>'),
(181578, 'عجمیان', '<span class=\"hlight\">عجمیان .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (اِ مرکب ) ج ِ عجمی <span class=\"hlight\">:</span> صد سوار را از عجمیان خویش راست کرد و صد غلام ترک، و معتمدی را از آن قاضی . (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١١٩</span>).<br /></font></div>'),
(181579, 'عجن', '<span class=\"hlight\">عجن .</span> <font color=\"DarkGreen\"><b>[ ع َ ج ِ ]</font></b> (ع ص ) شتر فربه پرگوشت . (اقرب الموارد) (منتهی الارب ) (آنندراج ). یقال بعیر عجن و ناقة عجنة. (اقرب الموارد).<br /></font></div>'),
(181580, 'عجن', '<span class=\"hlight\">عجن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ج ُ ]</font></b> (ع اِ) ج ِ عِجان . (منتهی الارب ). رجوع به عجان شود. <BR><font color=\"Blue\">◄</font> ج ِ عجین . (منتهی الارب ). رجوع به عجین شود.<br /></font></div>'),
(181581, 'عجن', '<span class=\"hlight\">عجن .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) آرد سرشتن . (تاج المصادر). بسرشتن آرد را و خمیر کردن آن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> برعجان کسی زدن . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دست زدن شترماده بر زمین در رفتن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تکیه بر زمین نمودن و برخاستن از جهت پیری و ضعف . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181582, 'عجن', '<span class=\"hlight\">عجن .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ع مص ) فربه شدن اشتر. (تاج المصادر) (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آماسیدن میان فرج و دبر ناقه . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181583, 'عجنة', '<span class=\"hlight\">عجنة.</span> <font color=\"DarkGreen\"><b>[ ع َ ج ِ ن َ ]</font></b> (ع ص ) مؤنث عجن، ناقه ٔ آماسیده فرج . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ناقه ٔ فربه بسیارگوشت . رجوع به عجن شود.<br /></font></div>'),
(181584, 'عجنس', '<span class=\"hlight\">عجنس .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َن ْ ن َ ]</font></b> (ع ص ) شتر سطبر نیک استوار. (اقرب الموارد) (منتهی الارب ). ج، عجانس .<br /></font></div>'),
(181585, 'عجنسی', '<span class=\"hlight\">عجنسی .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َن ْ ن َ ]</font></b> (اِخ ) ابومحمد احمدبن محمدالعجنس بن یوسف بن هشام العجنسی البخاری . به بغداد رفت و از محمدبن بشار و ابی مولی الزمن و سلم بن جنادة وجز آنان روایت کند، ابویعلی عبدالمؤمن بن خلف النسفی و ابوبکر محمدبن زکریا و ابوصالح الخیام و جز ایشان از او روایت دارند. از داود الظاهری فقه آموخت و به سال <span class=\"hlight\" dir=\"rtl\">٢٩٠</span> هَ . ق . درگذشت . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٤</span>).<br /></font></div>'),
(181586, 'عجوب', '<span class=\"hlight\">عجوب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عَجب . (منتهی الارب ).<br /></font></div>'),
(181587, 'عجوبه', '<span class=\"hlight\">عجوبه .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (از ع، اِ) چیزی که مردم را به شگفت آرد. و این مخفف اعجوبة است <span class=\"hlight\">:</span> <br />ای شیخ شهر با که توان این عجوبه گفت <br />بی پرده گشت شید نهان از ردای تو.<br /> <font color=\"Red\">محسن تأثیر (از آنندراج ).</font><br />و رجوع به اعجوبة شود.<br /></font></div>'),
(181588, 'عجوز', '<span class=\"hlight\">عجوز.</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (ع ص، اِ) پیره زن . (غیاث اللغات ) (آنندراج ) (ترجمان جرجانی ). زن گنده پیر کلان سال . (منتهی الارب ). المراءة المسنة لعجزها عن اکثر الامور و آن وصف خاص به آن است . (اقرب الموارد). ج، عُجُز، عَجائز <span class=\"hlight\">:</span> <br />عجوز جهان در نکاح فلک شد<br />که جز عذر زادنْش رائی نیابی .<br /> <font color=\"Red\">خاقانی .</font><br />مقعد چندین هزارساله عجوزی <br />بکر کجا ماند این چه نادره حال است .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> زن جوان باشد یا پیر. <BR><font color=\"Blue\">◄</font> هزارهزار از هر چیز. <BR><font color=\"Blue\">◄</font> مرددلیر. <BR><font color=\"Blue\">◄</font> گاو ماده . <BR><font color=\"Blue\">◄</font> گاو نر. <BR><font color=\"Blue\">◄</font> تاجر. <BR><font color=\"Blue\">◄</font> گرسنه . <BR><font color=\"Blue\">◄</font> الاغ وحشی . <BR><font color=\"Blue\">◄</font> کاسه ٔ کلان . <BR><font color=\"Blue\">◄</font> بلا و سختی . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خصلت ذمیمه . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گرگ ماده . <BR><font color=\"Blue\">◄</font> شترماده . <BR><font color=\"Blue\">◄</font> دست راست . <BR><font color=\"Blue\">◄</font> نوعی از خوشبوی . <BR><font color=\"Blue\">◄</font> باد گرم . <BR><font color=\"Blue\">◄</font> شیر بیشه . <BR><font color=\"Blue\">◄</font> تب . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> تحکم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خلافت . <BR><font color=\"Blue\">◄</font> رعشه . <BR><font color=\"Blue\">◄</font> عاجز. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ارز و نرخ چیزی . <BR><font color=\"Blue\">◄</font> پرهیزکاری از گناه .(منتهی الارب ). <BR><font color=\"Blue\">◄</font> توبه . <BR><font color=\"Blue\">◄</font> عافیت . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> چینی . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سوزن . <BR><font color=\"Blue\">◄</font> زمین . <BR><font color=\"Blue\">◄</font> خرگوش . <BR><font color=\"Blue\">◄</font> بینی . <BR><font color=\"Blue\">◄</font> چاه . <BR><font color=\"Blue\">◄</font> روباه . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پارچه . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> دشت . <BR><font color=\"Blue\">◄</font> دریا. (اقرب الموارد)(منتهی الارب ). <BR><font color=\"Blue\">◄</font> تیردان . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> جعبه . <BR><font color=\"Blue\">◄</font> جفنه . <BR><font color=\"Blue\">◄</font> دوزخ . <BR><font color=\"Blue\">◄</font> جنگ . <BR><font color=\"Blue\">◄</font> آلة جنگ . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نیزه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> می . <BR><font color=\"Blue\">◄</font> خیمه . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خرمن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> حب . دانه . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آفتاب . <BR><font color=\"Blue\">◄</font> پیراهن زن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دنیا. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> رایت . <BR><font color=\"Blue\">◄</font> کرکس . <BR><font color=\"Blue\">◄</font> اسب مادیان . <BR><font color=\"Blue\">◄</font> کشتی . <BR><font color=\"Blue\">◄</font> آسمان . <BR><font color=\"Blue\">◄</font> روغن . <BR><font color=\"Blue\">◄</font> سال . <BR><font color=\"Blue\">◄</font> سنگ ترازو. <BR><font color=\"Blue\">◄</font> صومعه . <BR><font color=\"Blue\">◄</font> کفتار. <BR><font color=\"Blue\">◄</font> راه . <BR><font color=\"Blue\">◄</font> ماده ٔ گوره خر. <BR><font color=\"Blue\">◄</font> کژدم . <BR><font color=\"Blue\">◄</font> اسب . <BR><font color=\"Blue\">◄</font> سیم . <BR><font color=\"Blue\">◄</font> قبله . <BR><font color=\"Blue\">◄</font> دیک . <BR><font color=\"Blue\">◄</font> دم شمشیر. <BR><font color=\"Blue\">◄</font> خیک . <BR><font color=\"Blue\">◄</font> کمان . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> لشکر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سگ . <BR><font color=\"Blue\">◄</font> مسافر. <BR><font color=\"Blue\">◄</font> مشگ . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دیگ پایه . <BR><font color=\"Blue\">◄</font> آتش . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خرمابن . <BR><font color=\"Blue\">◄</font> ولایت . <BR><font color=\"Blue\">◄</font> درختی است . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> طعامی است که از تره ٔ دریائی سازند. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ریگستانی است . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> میخی است در قبضه ٔ شمشیر. <BR><font color=\"Blue\">◄</font> گربه . <BR><font color=\"Blue\">◄</font> صحیفه . <BR><font color=\"Blue\">◄</font> عقرب . <BR><font color=\"Blue\">◄</font> قیامت . <BR><font color=\"Blue\">◄</font> کتیبه . <BR><font color=\"Blue\">◄</font> کف . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ملک . (اقرب الموارد) (آنندراج ). <BR><font color=\"Blue\">◄</font> مرگ . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> الدرع للمراءة. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سموم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> غراب . (اقرب الموارد).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بردالعجوز و برد عجوز</span> ؛ سرمای آخر زمستان را گویند که آن را ایام العجوز گویند. و آن هفت روز است در آخر زمستان که سرمای آن سخت شود که چهار روز آن از آخر شباط و سه روز از اوائل آذر است که عامه آن را مستقرضات گویند. (از اقرب الموارد) <span class=\"hlight\">:</span> <br />همچنان ازنهیب برد عجوز<br />طفل ناخورده شیر دایه هنوز.<br /><font color=\"Red\">سعدی (گلستان ).</font><br /></font></div>'),
(181589, 'عجوز', '<span class=\"hlight\">عجوز.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) ناتوان گردیدن . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ترک دادن چیزی را که کردن آن واجب بود. <BR><font color=\"Blue\">◄</font> کاهلی کردن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> عجوز و گنده پیر گردیدن زن . (منتهی الارب ) (از اقرب الموارد).<br /></font></div>'),
(181590, 'عجوز خشک پستان', '<span class=\"hlight\">عجوز خشک پستان .</span> <font color=\"DarkGreen\"><b>[ ع َ زِ خ ُ پ ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از دنیای بی وفا باشد. (برهان ) (آنندراج ). <BR><font color=\"Blue\">◄</font> زنی را گویند که هرگز نزائیده باشد. (برهان ) (آنندراج ).<br /></font></div>'),
(181591, 'عجوس', '<span class=\"hlight\">عجوس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) ابر گران . <BR><font color=\"Blue\">◄</font> باران ریزان پی هم . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181592, 'عجوس', '<span class=\"hlight\">عجوس .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) راه رفتن عَجاساء. (اقرب الموارد). نوعی از رفتار آهسته . (منتهی الارب ).<br /></font></div>'),
(181593, 'عجوف', '<span class=\"hlight\">عجوف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) بازداشتن خود را از خوردن با وجود گرسنگی تا دیگری را بخوراند. (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181594, 'عجول', '<span class=\"hlight\">عجول .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) زن فرزندمرده . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ناقه ٔ بچه گم کرده . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نیک شتابنده . (منتهی الارب ) (آنندراج ) <span class=\"hlight\">:</span> <br />مگر از دیدنم ملول شدی <br />که به مرگم چنین عجول شدی .<br /> <font color=\"Red\">سعدی .</font><br /><BR><font color=\"Blue\">◄</font> واله و سرگشته از زن . <BR><font color=\"Blue\">◄</font> (اِ) شتر ماده بدان جهت که از غایت جزع در حرکات خود شتابی می کند. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مرگ . <BR><font color=\"Blue\">◄</font> ناشتاشکن . (آنندراج ) (منتهی الارب ).<br /></font></div>'),
(181595, 'عجول', '<span class=\"hlight\">عجول .</span> <font color=\"DarkGreen\"><b>[ ع ِج ْ ج َ ]</font></b> (ع اِ) گوساله . ج، عَجاجیل . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مشتی از حَیس و خرما و پسته با خرما آمیخته . (منتهی الارب ).<br /></font></div>'),
(181596, 'عجولة', '<span class=\"hlight\">عجولة.</span> <font color=\"DarkGreen\"><b>[ ع ِج ْ ج َ ل َ ]</font></b> (ع اِ)مؤنث عِجّول . (منتهی الارب ). رجوع به عِجّول شود.<br /></font></div>'),
(181597, 'عجوم', '<span class=\"hlight\">عجوم .</span> <font color=\"DarkGreen\"><b>[ ع ُ]</font></b> (ع اِ) ج ِ عجم . (منتهی الارب ). رجوع به عجم شود.<br /></font></div>'),
(181598, 'عجوم', '<span class=\"hlight\">عجوم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) عَجم به همه ٔ معانی . رجوع به عَجم شود.<br /></font></div>'),
(181599, 'عجومة', '<span class=\"hlight\">عجومة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع ص ) ناقه ٔ توانا بر سفر. (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181600, 'عجی', '<span class=\"hlight\">عجی .</span> <font color=\"DarkGreen\"><b>[ ع ُ جی ی ]</font></b> (ع ص ) کودکی که مادر شیر او را از وقت آن واپس انداخته باشد. (اقرب الموارد). بچه ٔ شیر بدیر یافته . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کودک که به شیر بیگانه پرورش یافته باشد. (منتهی الارب ).<br /></font></div>'),
(181601, 'عجی', '<span class=\"hlight\">عجی .</span> <font color=\"DarkGreen\"><b>[ ع َ جی ی ]</font></b> (ع ص ) بچه ٔ گم کرده مادر از مردم و شتر که به شیر بیگانه غذا یافته . (منتهی الارب ) (اقرب الموارد).<br /></font></div>'),
(181602, 'عجیب', '<span class=\"hlight\">عجیب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) کار شگفت . ج، عِجاب . (منتهی الارب ) (آنندراج ) <span class=\"hlight\">:</span> <br />عجیب نیست که از طین بدر کند گل و نسرین <br />همان که صورت آدم کند سلاطه ٔ طین را.<br /> <font color=\"Red\">سعدی .</font><br /><BR><font color=\"Blue\">◄</font> خوش آیند از هر چیزی . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> امری شگفت آور. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناشناخته .(منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181603, 'عجیب مازندرانی', '<span class=\"hlight\">عجیب مازندرانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ب ِ زَ دَ ]</font></b> (اِخ ) محمد خلیل مردی عاشق پیشه و صوفی منش و اهل عرفان و از مردم عصر محمد شاه بود. با پدر خود از مازندران به تهران آمد و در آن وقت <span class=\"hlight\" dir=\"rtl\">٨</span>ساله بود و بواسطه ٔ طبع روانی که داشت مورد توجه واقع شد. به حضور شاه رسید و مدیحه گفت . وی همچنان از شعرای دربار ناصرالدین شاه بود. از اشعار اوست :<br />عید رمضان شد ای بت دلبر<br />برخیز و بدلخوشی بده ساغر.<br /><font color=\"Red\">(ازمجمع الفصحاء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٠</span>).</font><br /></font></div>'),
(181604, 'عجیبة', '<span class=\"hlight\">عجیبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِ) اسم است آنچه را به شگفت آورد. (اقرب الموارد). کار شگفت . (منتهی الارب ).<br /></font></div>'),
(181605, 'عجیبی', '<span class=\"hlight\">عجیبی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِ) قسمتی از چادر و خیمه . (ناظم الاطباء).<br /></font></div>'),
(181606, 'عجیة', '<span class=\"hlight\">عجیة.</span> <font color=\"DarkGreen\"><b>[ ع ُ جی ی َ ]</font></b> (ع ص ) مؤنث عجی . ج، عُجایا، عَجایا. (اقرب الموارد). عُجْیَة... (ع اِ) پوست خشک شده که آن را پزند و خورند. (اقرب الموارد) (منتهی الارب ). یقال قوت فلان اکل العجی . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> لغتی است در عجاوة. (منتهی الارب ).<br /></font></div>'),
(181607, 'عجیج', '<span class=\"hlight\">عجیج .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (ع مص ) برداشتن آواز را و بانگ کردن . (اقرب الموارد) (آنندراج ) (منتهی الارب ). رجوع به عَجج شود.<br /></font></div>'),
(181608, 'عجیر', '<span class=\"hlight\">عجیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) من الرجال و الخیل الذی لایولد. (اقرب الموارد). نامرد از مردم و اسب . (از منتهی الارب ).<br /></font></div>'),
(181609, 'عجیز', '<span class=\"hlight\">عجیز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) نامرد که بر زن قادر نشود. (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) سرین . (از منتهی الارب ).<br /></font></div>'),
(181610, 'عجیس', '<span class=\"hlight\">عجیس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) گشن که نتواند گشنی کردن . (از اقرب الموارد) (آنندراج ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خرما که گشنی نپذیرد. (آنندراج ) (منتهی الارب ).<br /></font></div>'),
(181611, 'عجیسی', '<span class=\"hlight\">عجیسی .</span><font color=\"DarkGreen\"><b>[ ع ِج ْ جی سا ]</font></b> (ع اِ) نوعی از رفتار آهسته . (آنندراج ). مشیة بطیئة. (اقرب الموارد) (از منتهی الارب ).<br /></font></div>'),
(181612, 'عجیل', '<span class=\"hlight\">عجیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) شتابنده .ج، عُجالی ̍ و عِجالی . (از منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181613, 'عجیل', '<span class=\"hlight\">عجیل .</span> <font color=\"DarkGreen\"><b>[ ع ُ ج َ ]</font></b> (ع اِ) ناشتاشکن یا ماحضری که جهت قوم سازند. (از منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181614, 'عجیلة', '<span class=\"hlight\">عجیلة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ج َ ل َ ]</font></b> (ع اِ) سیرشتاب . (منتهی الارب ).<br /></font></div>'),
(181615, 'عجیلی', '<span class=\"hlight\">عجیلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ج َ لا ]</font></b> (ع اِ) سیرشتاب . (منتهی الارب ). عجیلة.<br /></font></div>'),
(181616, 'عجین', '<span class=\"hlight\">عجین .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) سرشتن و خمیرکردن . (منتهی الارب ) (آنندراج ). آمیختن <span class=\"hlight\">:</span> <br />آبش همه از کوثر و از چشمه ٔ حیوان <br />خاکش همه از عنبر و کافور عجین است .<br /> <font color=\"Red\">منوچهری .</font><br />جان تو بر عالم علوی رسد<br />چون کنی مر علم را با جان عجین .<br /> <font color=\"Red\">ناصرخسرو.</font><br /><BR><font color=\"Blue\">◄</font> بر عجان کسی زدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دست زدن شتر ماده بر زمین در رفتن . <BR><font color=\"Blue\">◄</font> تکیه بر زمین نمودن برای برخاستن از جهت پیری و ضعف . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) خمیر. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) سرشته . (آنندراج ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مخنث . (منتهی الارب ). ج، عُجُن . <BR><font color=\"Blue\">◄</font> نرم و سست از مرد و زن . <BR><font color=\"Blue\">◄</font> گول . <BR><font color=\"Blue\">◄</font> گروه بسیار. (آنندراج ).<br /></font></div>'),
(181617, 'عجین کردن', '<span class=\"hlight\">عجین کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ دَ ]</font></b> (مص مرکب ) خمیر کردن . آمیختن <span class=\"hlight\">:</span> <br />دجله خوناب است زین پس گر نهد سر در نشیب <br />خاک نخلستان بطحا را کند از خون عجین .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(181618, 'عجینة', '<span class=\"hlight\">عجینة.</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ ]</font></b> (ع ص ) مخنث . <BR><font color=\"Blue\">◄</font> نرم سست از مرد و زن . <BR><font color=\"Blue\">◄</font> گول . <BR><font color=\"Blue\">◄</font> گروه . <BR><font color=\"Blue\">◄</font> گروه بسیار. (منتهی الارب ).<br /></font></div>'),
(181619, 'عد', '<span class=\"hlight\">عد.</span> <font color=\"DarkGreen\"><b>[ ع َدد ]</font></b> (ع مص ) شمردن . (ترجمان جرجانی ) (غیاث اللغات ) (منتهی الارب ) (آنندراج ) (تاج المصادر) (فرهنگ نظام ).<br /></font></div>'),
(181620, 'عد', '<span class=\"hlight\">عد.</span> <font color=\"DarkGreen\"><b>[ ع ِدد ]</font></b> (ع ص ) آب جاری که آن را ماده ای باشد که منقطع نشود مانند آب چشمه . (ناظم الاطباء) (اقرب الموارد) (آنندراج ). گویند: ماء عد و میاه اعداد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) بسیاری چیزی . <BR><font color=\"Blue\">◄</font> (ص، اِ) چاه قدیم . (اقرب الموارد) (آنندراج ). <BR><font color=\"Blue\">◄</font> حریف . (ناظم الاطباء).<br /></font></div>'),
(181621, 'عد', '<span class=\"hlight\">عد.</span> <font color=\"DarkGreen\"><b>[ ع ُدد ]</font></b> (ع اِ) آبله ریزه که بر رخسار ملاح برآید. (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181622, 'عد خمیس', '<span class=\"hlight\">عد خمیس .</span> <font color=\"DarkGreen\"><b>[ ع َ خ ُ ]</font></b> (اِخ ) دهی است از دهستان جراحی بخش شادگان شهرستان خرمشهر. دارای <span class=\"hlight\" dir=\"rtl\">١٢٠</span> تن سکنه . آب از چاه . محصول آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(181623, 'عدا', '<span class=\"hlight\">عدا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع حرف ) کلمه ای است که بدان استثنا شود چنانکه گویند: قام القوم عدا زیداً و عدا زید و ماعدا زید. (اقرب الموارد).<br /></font></div>'),
(181624, 'عداب', '<span class=\"hlight\">عداب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ریگ تنگ گسترده برابر یا طرف تنک از ریگ که بزمین درشت و هموار رسیده باشد. واحد و جمعدر وی یکسان است . (منتهی الارب ) (آنندراج ) (غیاث اللغات ). ما استرق من الرمل . (اقرب الموارد). و قیل جانبه الذی یرق و یلی الجدد من الارض . (اقرب الموارد).<br /></font></div>'),
(181625, 'عدابة', '<span class=\"hlight\">عدابة.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِ) زهدان . <BR><font color=\"Blue\">◄</font> زهار یابن آن . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181626, 'عدات', '<span class=\"hlight\">عدات .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِعادی . عداة. دشمنان . رجوع به عداة شود <span class=\"hlight\">:</span> <br />انبیا را امتحان کرده عدات <br />تا شده ظاهر ازیشان معجزات .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(181627, 'عداد', '<span class=\"hlight\">عداد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) همتا. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> حریف . القرن . یقال ؛ هو عدادک ای قرنک . <BR><font color=\"Blue\">◄</font> بخشش . <BR><font color=\"Blue\">◄</font> اثری از دیوانگی . (منتهی الارب ) (از اقرب الموارد) (آنندراج ). <BR><font color=\"Blue\">◄</font> هنگام مرگ . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بانگ کمان .(اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (مص ) پیدا شدن اثر درد گزندگی از مار بعد از سالی . (از اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) درد مطلقا. (اقرب الموارد) (آنندراج ).<br /></font></div>'),
(181628, 'عدار', '<span class=\"hlight\">عدار.</span> <font color=\"DarkGreen\"><b>[ ع َدْ دا ]</font></b> (ع ص ) ملاح . (اقرب الموارد) (آنندراج ).<br /></font></div>'),
(181629, 'عدار', '<span class=\"hlight\">عدار.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) دابه ای است در یمن که گویند مردم را میگاید و نطفه ٔ آن کرم است . (منتهی الارب ). گویند الوطه من عدار. (تاج العروس ).<br /></font></div>'),
(181630, 'عداس', '<span class=\"hlight\">عداس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) ابومحمد حسن بن علی بن موسی العدّاس المصری . عالم باخبار و تواریخ بوده . ولی به سال <span class=\"hlight\" dir=\"rtl\">٣٢٤</span> هَ . ق . درگذشت . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٥</span>).<br /></font></div>'),
(181631, 'عداس', '<span class=\"hlight\">عداس .</span> <font color=\"DarkGreen\"><b>[ ع َدْ دا ]</font></b> (اِخ ) رفتن در زمین . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181632, 'عداف', '<span class=\"hlight\">عداف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) اندک . یقال ما ذقنا عدافاً ای شیئاً. (منتهی الارب ) (آنندراج ) (از قطرالمحیط). اندک و هیچ چیز. (ناظم الاطباء).<br /></font></div>'),
(181633, 'عدال', '<span class=\"hlight\">عدال .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) با چیزی برابر آمدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خمیدن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> بازگردیدن از کسی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اندازه کردن میان دو چیز. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> بازگردیدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> توقف نمودن . <BR><font color=\"Blue\">◄</font> هم وزن کردن و برابر گردانیدن چیزی را به چیزی . <BR><font color=\"Blue\">◄</font> با کسی سوار شدن در کجاوه . <BR><font color=\"Blue\">◄</font> متردد بودن در اختیار یکی از دو امر که پیش آید کسی را. (آنندراج ) (منتهی الارب ).<br /></font></div>'),
(181634, 'عدالة', '<span class=\"hlight\">عدالة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع مص ) به سند گواهی شدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شایسته ٔ گواهی شدن . (آنندراج ). <BR><font color=\"Blue\">◄</font> عدل بودن . (از اقرب الموارد) (آنندراج ). <BR><font color=\"Blue\">◄</font> ضد جور. (قطرالمحیط). انصاف دادن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> داد ستدن . (آنندراج ).<br /></font></div>'),
(181635, 'عدالت', '<span class=\"hlight\">عدالت .</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ل َ ]</font></b> (ع مص ) عدالة. دادگری کردن .عدالت کردن . جرجانی گوید: عدالت در لغت استقامت باشد و در شریعت عبارت از استقامت بر طریق حق است به اجتناب از آنچه محظور است در دین . (تعریفات جرجانی ).<br /></font></div>'),
(181636, 'عدالت پیشه', '<span class=\"hlight\">عدالت پیشه .</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ل َ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص مرکب ) عادل و منصف . (آنندراج ). کسی که کار به عدالت کند.<br /></font></div>'),
(181637, 'عدالت کردن', '<span class=\"hlight\">عدالت کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ل َ ک َ دَ ]</font></b> (مص مرکب ) دادگستر بودن . باعدالت بودن . عادل بودن <span class=\"hlight\">:</span> <br />عدالت کن که در عدل آنچه یک ساعت به دست آید<br />میسر نیست در هفتاد سال اهل عبادت را.<br /><font color=\"Red\">صائب .</font><br /></font></div>'),
(181638, 'عدالت گستر', '<span class=\"hlight\">عدالت گستر.</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ل َ گ ُ ت َ ]</font></b> (نف مرکب ) آنکه از روی انصاف و عدالت با مردم رفتار کند. آنکه شیوه ٔ او عدالت باشد.<br /></font></div>'),
(181639, 'عدامة', '<span class=\"hlight\">عدامة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع مص ) گول گردیدن . احمق شدن . (قطرالمحیط)(منتهی الارب ). گول و احمق گردیدن . (ناظم الاطباء).<br /></font></div>'),
(181640, 'عدامس', '<span class=\"hlight\">عدامس .</span> <font color=\"DarkGreen\"><b>[ ع ُ م ِ ]</font></b> (ع ص ) گیاه خشک بسیار فراهم آمده به جائی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181641, 'عدامل', '<span class=\"hlight\">عدامل .</span> <font color=\"DarkGreen\"><b>[ ع ُ م ِ ]</font></b> (ع ص ) دیرینه و سال خورده از هر چیزی . (قطرالمحیط) (اقرب الموارد)(از منتهی الارب ). <BR><font color=\"Blue\">◄</font> سطبر و کهنه از درخت و سوسمار. (منتهی الارب ) (آنندراج ) (اقرب الموارد).<br /></font></div>'),
(181642, 'عداملی', '<span class=\"hlight\">عداملی .</span> <font color=\"DarkGreen\"><b>[ ع ُم ِ لی ی ]</font></b> (ع ص ) به همه ٔ معانی رجوع به عدامل شود.<br /></font></div>'),
(181643, 'عدان', '<span class=\"hlight\">عدان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ساحل دریا. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> کرانه ٔ نهر. (قطرالمحیط) (منتهی الارب ) (از آنندراج ). <BR><font color=\"Blue\">◄</font> کرانه ٔ نهر. <BR><font color=\"Blue\">◄</font> هر هفت سال از زمان . (قطرالمحیط) (از اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181644, 'عدانات', '<span class=\"hlight\">عدانات .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عَدانة. (ناظم الاطباء). رجوع به عدانة شود.<br /></font></div>'),
(181645, 'عدانة', '<span class=\"hlight\">عدانة.</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ ]</font></b> (ع اِ) گروه مردم . (آنندراج ) (منتهی الارب )(از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پوست پاره ٔ بن دلو.(منتهی الارب ) (از قطر المحیط) (از اقرب الموارد).<br /></font></div>'),
(181646, 'عداوت', '<span class=\"hlight\">عداوت .</span> <font color=\"DarkGreen\"><b>[ ع َ وَ ]</font></b> (ع اِمص ) عداوة. دشمنی <span class=\"hlight\">:</span> با او نهانی عداوتی داشت . (گلستان ).<br />هنر بچشم عداوت بزرگتر عیبی است . (گلستان ).<br /></font></div>'),
(181647, 'عداوت داشتن', '<span class=\"hlight\">عداوت داشتن .</span> <font color=\"DarkGreen\"><b>[ ع َ وَ ت َ ]</font></b> (مص مرکب ) دشمنی کسی را در دل نگاه داشتن .<br /></font></div>'),
(181648, 'عداوت کردن', '<span class=\"hlight\">عداوت کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ وَ ک َ دَ ]</font></b> (مص مرکب ) دشمنی کردن . دشمنی نمودن .<br /></font></div>'),
(181649, 'عداوت گزین', '<span class=\"hlight\">عداوت گزین .</span> <font color=\"DarkGreen\"><b>[ ع َ وَ گ ُ]</font></b> (نف مرکب ) مخالف و ضد و بدخواه . (ناظم الاطباء).<br /></font></div>'),
(181650, 'عدبس', '<span class=\"hlight\">عدبس .</span> <font color=\"DarkGreen\"><b>[ ع َ دَب ْ ب َ ]</font></b> (ع ص ) توانا و استوار محکم اندام از شتر و جز آن . (منتهی الارب ) (آنندراج ) (از اقرب الموارد) (قطرالمحیط). <BR><font color=\"Blue\">◄</font> بدخوی . (منتهی الارب ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سطبر درشت . (منتهی الارب ) (از اقرب الموارد) (از قطرالمحیط).<br /></font></div>'),
(181651, 'عدبی', '<span class=\"hlight\">عدبی .</span> <font color=\"DarkGreen\"><b>[ع َ دَ بی ی ]</font></b> (ع ص ) نیک خوی . (منتهی الارب ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنکه در وی عیبی نباشد. (از اقرب الموارد) (قطرالمحیط) (منتهی الارب ).<br /></font></div>'),
(181652, 'عدت', '<span class=\"hlight\">عدت .</span> <font color=\"DarkGreen\"><b>[ ع ِدْ دَ ]</font></b> (ع اِ)عِدّة. شمار. (آنندراج ). <BR><font color=\"Blue\">◄</font> ایام طلاق زنان که در آن مدت شوهر نکنند. برای مطلقه سه حیض یا سه ماه و برای بیوه چهار ماه و ده روز وعدت زنان حامله وضع حمل است . (آنندراج ) <span class=\"hlight\">:</span> چون مدت عدت بسرآمد عقد نکاحش بستند. (گلستان ). رجوع به عدة شود.<br /></font></div>'),
(181653, 'عدد', '<span class=\"hlight\">عدد.</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ع اِ) شمار. <BR><font color=\"Blue\">◄</font> شمار گروه . <BR><font color=\"Blue\">◄</font> سالهای عمر کسی که بشمارند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (مص ) شمار کردن . (منتهی الارب ). احصاء کل شی ٔ علی سبیل التفصیل . (تعریفات جرجانی ).<br /></font></div>'),
(181654, 'عدد', '<span class=\"hlight\">عدد.</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ ]</font></b> (ع مص ) برانگیخته شدن درد مارگزیده بعد از مدت . (منتهی الارب ). برانگیخته شدن درد مارگزیده پس از یک سال . (از اقرب الموارد).<br /></font></div>'),
(181655, 'عددهیلی', '<span class=\"hlight\">عددهیلی .</span> <font color=\"DarkGreen\"><b>[ ع َ دِ ]</font></b> (اِخ ) دهی است از دهستان جراحی بخش شادگان شهرستان خرمشهر دارای <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه . آب آن از چاه . محصول آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(181656, 'عددی', '<span class=\"hlight\">عددی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ص نسبی )منسوب به عدد. آنچه شمار شود. مقابل وزنی . <BR><font color=\"Blue\">◄</font> آنچه به شمار فروخته شود. (از اقرب الموارد).<br /></font></div>'),
(181657, 'عدر', '<span class=\"hlight\">عدر.</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ]</font></b> (ع اِمص ) دلیری . (منتهی الارب ) (آنندراج ) (قطرالمحیط). <BR><font color=\"Blue\">◄</font> (ص ) باران سخت و بسیار. (منتهی الارب ) (از اقرب الموارد).<br /></font></div>'),
(181658, 'عدر', '<span class=\"hlight\">عدر.</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ع مص ) بسیارآب گردیدن جای . (اقرب الموارد) (از قطرالمحیط).<br /></font></div>'),
(181659, 'عدرج', '<span class=\"hlight\">عدرج .</span> <font color=\"DarkGreen\"><b>[ ع َ دَرْ رَ ]</font></b> (ع ص ) تیزرو و سبک . (از اقرب الموارد) (منتهی الارب ). السریع الخفیف . (قطرالمحیط). <BR><font color=\"Blue\">◄</font> (اِ) ما بالدار من عدرج ؛ یعنی نیست در خانه کسی . (از اقرب الموارد) (از منتهی الارب ).<br /></font></div>'),
(181660, 'عدرنا', '<span class=\"hlight\">عدرنا.</span> <font color=\"DarkGreen\"><b>[ع َ دَ ]</font></b> (اِ) کندش است که آن را به شیرازی چوبک اشنان خوانند و آذربویه همان است . (آنندراج ) (برهان ).<br /></font></div>'),
(181661, 'عدس', '<span class=\"hlight\">عدس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) خدمت کردن . (منتهی الارب ) (از قطر المحیط) (از اقرب الموارد)(آنندراج ). <BR><font color=\"Blue\">◄</font> رفتن در زمین . (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> چرانیدن شتران را. (از اقرب الموارد) (منتهی الارب ) (آنندراج ).عَدَس المال َ؛ رعاه . (قطرالمحیط). <BR><font color=\"Blue\">◄</font> زده گردیدن مرد. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> زجر کردن استر را به لفظ عدس . (منتهی الارب ) (ازاقرب الموارد) (قطرالمحیط). <BR><font color=\"Blue\">◄</font> بردن مرگ کسی را. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سخت پاسپر کردن . (منتهی الارب ) (آنندراج ). عَدَس الشی ٔ؛ وطئه کثیراً. (قطرالمحیط). <BR><font color=\"Blue\">◄</font> سپردن . <BR><font color=\"Blue\">◄</font> کوشیدن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) حدس . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181662, 'عدس', '<span class=\"hlight\">عدس .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ع اِ) نرسک . (منتهی الارب ). دانه ای است که قسمی از آن بیابانی است و خرد و مایل بگردی و قسمی بستانی است و پهن . (از اقرب الموارد) (از قطرالمحیط). در ترجمه ٔ صیدنه است که در پارسی آن را نرسک گویند و به هندی مسوری گویند، ارجانی گوید: سرد است در دو درجه اول و خشگ است در دو درجه ٔ و جرم او قابض است هر طبیعت را وخون را غلیظ گرداند و سیلان خون را قطع کند و ادرار بول را که از حرارت باشد. و دمش دهان را سود دارد و به معده و جمله اعضاء عصبی نیک باشد، و چشم را تاریک گرداند و بیماریهای سودائی را تقویت دهد و آبی که عدس را در او بجوشانند و بخورند اطلاق شکم آرد. (از ترجمه ٔ صیدنه ٔ ابوریحان ). در تحفه است که آن را به فارسی مرجومک گویند. برّی او کوچک است . (تحفه ص <span class=\"hlight\" dir=\"rtl\">١٨١</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدس جبلی یا عدس کوهی </span> ؛ نوعی از عدس است . (از تحفه ٔ حکیم ص <span class=\"hlight\" dir=\"rtl\">١٨١</span>).<br /></font></div>'),
(181663, 'عدس', '<span class=\"hlight\">عدس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ صوت )کلمه ای است که بدان استر را زجر کنند. (از منتهی الارب ) (آنندراج ) (از قطر المحیط) (از اقرب الموارد).<br /></font></div>'),
(181664, 'عدس المر', '<span class=\"hlight\">عدس المر.</span> <font color=\"DarkGreen\"><b>[ ع َ دَ سُل ْ م ُرر ]</font></b> (ع اِ مرکب ) تخم نوعی از سوسن بَرّی است، و گویند اسم علقم است . (تحفه ص <span class=\"hlight\" dir=\"rtl\">١٨١</span>).<br /></font></div>'),
(181665, 'عدس سرخ', '<span class=\"hlight\">عدس سرخ .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ س ِ س ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) نوعی از عدس است و کشک وجو و عدس سرخ به یکجا پزند. (ذخیره ٔ خوارزمشاهی ).<br /></font></div>'),
(181666, 'عدسان', '<span class=\"hlight\">عدسان .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ع مص ) رفتن درزمین . (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br /></font></div>'),
(181667, 'عدسة', '<span class=\"hlight\">عدسة.</span> <font color=\"DarkGreen\"><b>[ ع َ دَ س َ ]</font></b> (ع اِ) آماسی است خرد و سخت که اندر پلک چشم گردآید و بفسرد. (ذخیره ٔ خوارزمشاهی ). <BR><font color=\"Blue\">◄</font> یک دانه نرسک . <BR><font color=\"Blue\">◄</font> سرخکان که بر اندام برآید یا نوعی از جدری که میکشد مردم را. آبله ٔ وبائی است . (منتهی الارب ) (آنندراج ) (از قطرالمحیط). <BR><font color=\"Blue\">◄</font> هر چه شبیه عدس است و مدور و محدب است .<br /></font></div>'),
(181668, 'عدسواری', '<span class=\"hlight\">عدسواری .</span> <font color=\"DarkGreen\"><b>[ ع َ دِ س َ ]</font></b> (اِخ ) دهی است از دهستان جراحی بخش شادگان شهرستان خرمشهر دارای <span class=\"hlight\" dir=\"rtl\">١٧٠</span> تن سکنه . محصولات آن غلات است . شغل اهالی زراعت و گله داری است . ساکنین از آل ابوغیش هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(181669, 'عدسی', '<span class=\"hlight\">عدسی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ سی ی ]</font></b> (ص نسبی، اِ) غذائی است که میپزند <span class=\"hlight\">:</span> <br />اگرْت خواب نگیرد ز بهر چاشت شبی <br />که در تنور نهندت هریسه یا عدسی .<br /> <font color=\"Red\">ناصرخسرو.</font><br /><BR><font color=\"Blue\">◄</font> نزد مهندسان عبارت از سطحی است که دو قوس مختلف التحدب آن را احاطه کرده باشند و هر یک از آن دو قوس بزرگتر از نصف دائره باشد و آن را شلغمی نیز گویند. (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> عدسیها اجسامی هستند که دارای یک یا دو سطح منحنی باشند. عدسیهای کروی، سطح آنها از یک قسمت کره درست شده است و آنها یا محدب اند یا مقعر. (از چشم و بیماریهای آن تألیف باستان ص <span class=\"hlight\" dir=\"rtl\">٥</span>). <BR><font color=\"Blue\">◄</font> مرواریدی است که با وجود استدارت سرهای او مساوی باشد. (جواهرنامه ). <BR><font color=\"Blue\">◄</font> دو دانه از تسبیح که مانند عدس ساخته میشود و در میان رشته ٔ سبحه است و دانه ها را به سه قسمت کند.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(181670, 'عدسیه', '<span class=\"hlight\">عدسیه .</span> <font color=\"DarkGreen\"><b>[ ع َ سی ی َ ]</font></b> (ع اِ) شبیه به عدس است که در مواضعی از بدن برمی آید و از جنس طاعون باشد و میکشد صاحب خود را. در اکثر، گاه اطلاق بر تحجر عین مینمایند. (از جمع الجوامع از بحر الجواهر بنقل فرهنگ نظام ).<br /></font></div>'),
(181671, 'عدعد', '<span class=\"hlight\">عدعد.</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (ع اِ صوت ) کلمه ای است که بدان استر را زجر کنند. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آواز سنگخوار. (قطرالمحیط).<br /></font></div>'),
(181672, 'عدف', '<span class=\"hlight\">عدف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) نوال اندک . (منتهی الارب )(از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خورش ستور اندک . (منتهی الارب ) (آنندراج ). اندک از علف . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اندک از هر چیزی . (منتهی الارب ).<br /></font></div>'),
(181673, 'عدف', '<span class=\"hlight\">عدف .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) پاره ای از شب . <BR><font color=\"Blue\">◄</font> گروه مردم . (منتهی الارب ) (از اقرب الموارد) (قطرالمحیط). <BR><font color=\"Blue\">◄</font> از ده تا پنجاه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اصل از هر چیزی . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181674, 'عدف', '<span class=\"hlight\">عدف .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ع اِ) خاشاک . (اقرب الموارد) (منتهی الارب ) (قطرالمحیط). <BR><font color=\"Blue\">◄</font> اندک از علف و جز آن .(آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ج ِ عِدفة.<br /></font></div>'),
(181675, 'عدفة', '<span class=\"hlight\">عدفة.</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ف َ ]</font></b> (ع اِ) بیخ درخت که رفته است درزیر زمین . ج، عِدَف . (اقرب الموارد) (قطرالمحیط).<br /></font></div>'),
(181676, 'عدفة', '<span class=\"hlight\">عدفة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ف َ ]</font></b> (ع اِ) از ده تا پنجاه مرد یا عام است . (منتهی الارب ). بین ده تا پنجاه مرد. (اقرب الموارد). گروه مردم یا مابین ده تا پنجاه از مردان . (قطرالمحیط). <BR><font color=\"Blue\">◄</font> فراهم آمدگی مردم . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پاره ای از هر چیزی . (منتهی الارب ) (قطر المحیط). <BR><font color=\"Blue\">◄</font> و طره ٔ جامه یعنی ملک کرباس و جز آن مانند صنفة. (منتهی الارب ). کالصنفة من الثوب . <BR><font color=\"Blue\">◄</font> شاماکچه . (منتهی الارب ). الصدرة. (از اقرب الموارد) (قطرالمحیط). <BR><font color=\"Blue\">◄</font> بیخ درخت در زیر زمین . (از منتهی الارب ) (از اقرب الموارد).<br /></font></div>'),
(181677, 'عدق', '<span class=\"hlight\">عدق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) فراهم آوردن چیزی را و گرد کردن . (آنندراج ) (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> انداختن دست خود را در حوض . (منتهی الارب ) (از اقرب الموارد) (قطرالمحیط). <BR><font color=\"Blue\">◄</font> کاری بغالب رای خود کردن که یقین آن نداشته . (از اقرب الموارد) (منتهی الارب ) (از آنندراج ).<br /></font></div>'),
(181678, 'عدق', '<span class=\"hlight\">عدق .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ع اِ) ج ِ عَدقة. (منتهی الارب ).<br /></font></div>'),
(181679, 'عدق', '<span class=\"hlight\">عدق .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ع مص ) عَدق . رجوع به عَدق شود.<br /></font></div>'),
(181680, 'عدق', '<span class=\"hlight\">عدق .</span> <font color=\"DarkGreen\"><b>[ ع ُ دُ ]</font></b> (ع اِ) ج ِ عَودق . (منتهی الارب ). رجوع بدان کلمه شود.<br /></font></div>'),
(181681, 'عدل', '<span class=\"hlight\">عدل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِمص ) مقابل ستم . مقابل بیداد. داد. (دستوراللغة). مقابل جور. ضد جور. نقیض جور. (منتهی الارب ) (اقرب الموارد). مقابل ظلم . نصفت . قسط. عدالت . انصاف . امری بین افراط و تفریط. (از قطرالمحیط) (از اقرب الموارد). مساوات در مکافات به نیکی نیکی، و بد بدی بدی . داوری به حق . مساوی آزرم <span class=\"hlight\">:</span> <br />بدان ای گرامی ّ نیکونهاد<br />بباید که کوشی به عدل و به داد.<br /> <font color=\"Red\">فردوسی .</font><br />همان سهم او سهم اسفندیاری <br />همان عدل او عدل نوشیروانی .<br /> <font color=\"Red\">منوچهری .</font><br />آن رسوم و دامن و عدل ... هیچ جای نیست . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٠٩</span>). اردشیر بابکان ... سنتی از عدل میان ملک بنهاد و پس از وی گروهی بر آن رفتند. (تاریخ بیهقی ). نفس گوینده پادشاه است . مستولی ... بایدکه او را عدلی و سیاستی باشد. (تاریخ بیهقی ).<br />خلق ببینی همه خفته ز علم <br />عدل نهان گشته و فاش اضطراب .<br /> <font color=\"Red\">ناصرخسرو.</font><br />عدل است مراد حق از آن هر کس <br />دلشاد شود چه گویی ای عادل .<br /> <font color=\"Red\">ناصرخسرو.</font><br />دیدن و دانستن عدل خدای <br />کار حکیمان و ره انبیاست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />عدل است اصل خیر که نوشروان <br />اندر جهان به عدل مسمی شد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />هر که را سایه ٔ عدل تو نباشد بر سر<br />آفتاب املش بر لب دیوار بود.<br /> <font color=\"Red\">معزی .</font><br />شیعیان چون زور تو بینند خوانندت علی <br />سنیان چون عدل تو بینند خوانندت عمر.<br /> <font color=\"Red\">معزی .</font><br />هر کجا عدل روی بنموده ست <br />نعمت اندر جهان بیفزوده ست .<br /> <font color=\"Red\">سنائی .</font><br />عدل سلطان به از فراخی سال .<br /> <font color=\"Red\">سنائی .</font><br />عدل بازوی شه قوی دارد<br />قامت ملک مستوی دارد.<br /> <font color=\"Red\">سنائی .</font><br />عدل شمعی بود جهان افروز<br />ظلم شد آتشی ممالک سوز.<br /><font color=\"Red\">سنائی .</font><br />و با آنچه ملک عادل انوشیروان کسری بن قباد را سعادت ذات ... و شمول عدل ... حاصل است می بینیم که کارهای زمانه میل به ادبار دارد. (کلیله و دمنه ). صیت عدل و رأفت او بر روی روزگار باقی است . (کلیله و دمنه ). و پادشاه در سیاست رعیت و بسط عدل و رأفت ... بدان حاجت افتد. (کلیله و دمنه ).<br />امید عدلش ملک را چون عقل در جان پرورد<br />خورشیدفضلش خلق را چون لعل در کان پرورد.<br /> <font color=\"Red\">خاقانی .</font><br />عدل تو تا ز اهتمام حامی آفاق شد<br />بر گل و مل کس دگر خار ندید و خمار.<br /> <font color=\"Red\">خاقانی .</font><br />جور بس کن خامه چون کسری به عدل <br />شاه زنجیر امان آویخته .<br /> <font color=\"Red\">خاقانی .</font><br />جفاپیشگان را بده سر بباد<br />ستم بر ستم پیشه عدل است و داد.<br /> <font color=\"Red\">سعدی .</font><br />عدل یک ساعته ات را به قیاس <br />شصت ساله عمل خیرشناس .<br /> <font color=\"Red\">جامی .</font><br />عدل تو و امن، عروه و عفرا<br />طبع تو و جود، ویسه و رامین .<br /> <font color=\"Red\">قاآنی .</font><br />تعدیل، عدل خواندن . (تاج المصادر).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">اصحاب عدل و توحید</span> ؛ معتزله . رجوع به عدلی مذهب وعدلیه (اوّلی ) شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدل تقدیری </span> . رجوع به این کلمه در ردیف خود شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدل عُمر</span> ؛ عدالت خلیفه ٔ دوم از خلفای راشدین، دادگری او <span class=\"hlight\">:</span> <br />گیتی از عدل بیاراید تا درگذرد<br />عدل و انصاف ملک مسعود از عدل عمر.<br /> <font color=\"Red\">فرخی .</font><br />بریده نیست امید خلاص و راحت من <br />در این زمانه که تازه شده ست عدل عمر بر.<br /> <font color=\"Red\">مسعودسعد (دیوان چ نوریان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٥</span>).</font><br />کهف ملت شاه ترک و چین علاءالدین که او<br />سیرت و نام پیمبر دارد و عدل عمر.<br /> <font color=\"Red\">معزی .</font><br />امروز در این دور دریغی نخورد هیش <br />از عدل تو یک سوخته بر عدل عمر بر.<br /> <font color=\"Red\">سنائی (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٥٢</span>).</font><br />دوری ازجهل همچو علم علی <br />پاکی از جور همچو عدل عمر.<br /> <font color=\"Red\">سنائی .</font><br />فزوده حرمت عدل عمر به دین درست <br />نموده حجت علم علی ز رای مصیب .<br /> <font color=\"Red\">ادیب صابر.</font><br />مکارم را چو برخیزد امل جود علی یابد<br />مظالم را چوبنشیند جهان عدل عمر گیرد.<br /> <font color=\"Red\">سید حسن غزنوی .</font><br />به عمر عدل عمر ورز و جاودان زی زانک <br />به عدل نام عمر زنده ماند جاویدان .<br /> <font color=\"Red\">سوزنی .</font><br />محمد آنکه ز جاهش گرفت ملت و ملک <br />همان نظام که دین زابتدا به عدل عمر.<br /> <font color=\"Red\">انوری .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مذهب عدل </span> ؛ <span class=\"hlight\">:</span> در عهد او مزدک زندیق پدید آمد و اباحت پدید آورد و آن را مذهب عدل نام نهادند. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٨٤</span>). رجوع به عدلی مذهب شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">ظلم به تساوی یا بالسویه عدل است </span> .<br /> <BR><font color=\"Blue\">◄</font> (ص ) مرد راست وپسندیده . (دستوراللغة ادیب نطنزی ). مرد صالح . مرد نیک . (مهذب الاسماء). مرد شایسته ٔ گواهی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گواه راست . (مهذب الاسماء). گواه .ج، عُدول .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ساعت عدل </span> ؛ یک قسمت از بیست و چهار قسمت شبانروز است و این تقسیم راحکمای اسلامی کرده اند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">گواه عدل </span> ؛گواه راست . شاهد عادل .<br /> <BR><font color=\"Blue\">◄</font> حق . (مهذب الاسماء). راست . درست . برابر. تمام ؛ به سنگ عدل، به سنگ تمام . (در تداول فارسی زبانان ) <span class=\"hlight\">:</span> بیاعان معتمد باشند که قیمت عدل بر آن نهند. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١٤٦</span>). <BR><font color=\"Blue\">◄</font> (اِمص ) راستی . برابری . توازن . استقامت . (اقرب الموارد) <span class=\"hlight\">:</span> <br />با همه کم بیش که در عالم است <br />عدل نگوئی که در اینجا کجاست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />دین که قوی دارد بازوت را<br />راست کند عدل ترازوت را.<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> میانه روی . قصد. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) نامی از نامهای خدای تعالی . صفتی است از صفات خدای تعالی، و آن صفتی است که بواسطه ٔ آن دنیا و مافیها قرار و پایدار است . (قاموس کتاب مقدس ). هوالذی لا یمیل به الهوی فیجور فی الحکم . (بحرالجواهر). <BR><font color=\"Blue\">◄</font> (ع ص ) عادل . دادگر. (منتهی الارب ).منصف <span class=\"hlight\">:</span> گواه عدل و خانه ها برجایست . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥١١</span>).<br />اعتقاد تو چنین است ولیکن بزبان <br />گویی آن حاکم عدل است و حکیم الحکماست .<br /><font color=\"Red\">ناصرخسرو.</font><br />روزی است از آن پس که در آن روز نیابد<br />خلق از حکم عدل نه ملجا و نه منجا.<br /> <font color=\"Red\">ناصرخسرو.</font><br />و ترسل و شعر او بر این دعوی دو شاهد عدل اند و دو حاکم راست . (چهارمقاله ٔ نظامی عروضی ). مرافعه ٔ این سخن به قاضی بردیم و به محاکمه ٔ عدل راضی شدیم . (گلستان ). معتمدی صادق القول و شاهدی امین عدل . (ترجمه ٔ محاسن اصفهان ص <span class=\"hlight\" dir=\"rtl\">٧٤</span>). داددهنده . (دستور اللغة) (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> قاضی و حاکمی که در صدور احکام خود مراعات حق کند. (از اقرب الموارد) <span class=\"hlight\">:</span> <br />لیکن نکند حکم عادل عدل <br />تا وقت نیاید فراز و هنگام .<br /> <font color=\"Red\">ناصرخسرو.</font><br /><BR><font color=\"Blue\">◄</font> (اِ) میزان . <BR><font color=\"Blue\">◄</font> رطل . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کیل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> همتا. ج، أعدال و عُدول . (مهذب الاسماء). مانند. مثل . نظیر. مانند از غیر جنس . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> همسر. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> لنگه ٔ بار. تنگ . (زمخشری ). یک طرف بار که بفارسی تنگ گویند. عِکم . تا. تاه .تاچه . بهار. تابار. تای . جزء از دو جزء. بار. نصف بار. (مهذب الاسماء). عب . صندوق : در اصفهان دوازده من تبریز است و حملی و این بیشتر در جامه و قماش مستعمل است ؛ یک عدل چیت، یک عدل ماهوت . مقابل لنگه که در هندوانه و خربزه و امثال آن معمول است ومقابل تنگ که در شکر و مانند آن مصطلح است . <BR><font color=\"Blue\">◄</font> قیمت . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> فدیه . (از قطرالمحیط) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نافله . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> فریضه . (از قطرالمحیط)(از اقرب الموارد). <BR><font color=\"Blue\">◄</font> فریضه . (قطرالمحیط) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) نام مردی است بسیار کشنده و بی رحم . <BR><font color=\"Blue\">◄</font> (ع مص ) داد کردن .(زوزنی ) (دستوراللغة). <BR><font color=\"Blue\">◄</font> برابر کردن باچیزی . (زوزنی ). برابر کردن چیزی با چیزی . (دستور اللغة). برابر کردن چیزی به چیزی . (تاج المصادر). برابر کردن میان دو تنگبار. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> برابر کردن میان کسان . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خمیدن راه و کج گردیدن . <BR><font color=\"Blue\">◄</font> پیمودن . <BR><font color=\"Blue\">◄</font> برابر آمدن چیزی . (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> برابر شدن . مثل شدن . <BR><font color=\"Blue\">◄</font> برابری و بی تفاوت بودن هر دو کفه ٔ ترازو. ( از آنندراج ). <BR><font color=\"Blue\">◄</font> بگردانیدن چیزی . (زوزنی ). <BR><font color=\"Blue\">◄</font> از گشن بازایستادن گشنی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بازگردانیدن ِ ساربان گشنی را. <BR><font color=\"Blue\">◄</font> سوار گردیدن همراه کسی در کجاوه . <BR><font color=\"Blue\">◄</font> راست کردن و برابر نمودن . <BR><font color=\"Blue\">◄</font> هموزن گردانیدن چیزی را. <BR><font color=\"Blue\">◄</font> بیرون آوردن کلمه ای از کلمه ای . رجوع به عدل تقدیری شود. <BR><font color=\"Blue\">◄</font> متردد شدن در اختیار یکی از دو چیز. <BR><font color=\"Blue\">◄</font> پاداش دادن . <BR><font color=\"Blue\">◄</font> شرک کردن با پروردگار خود. (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> میل کردن . (قطرالمحیط). <BR><font color=\"Blue\">◄</font> (اِ) مانند. (اقرب الموارد) (منتهی الارب ). مثل چیزی در وزن و قدر. (از اقرب الموارد) (منتهی الارب ) (آنندراج ). تقول عندی عدل غلامک . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) (اصطلاح اخلاقی ) در مقابل ظلم است و بمعنای احقاق حق و اخراج حق از باطل است و امر متوسط میان تفریط و افراط را گویند چنانکه گویند: قوت غضبیه ٔ انسان در مرتبت افراط تهور، و درمرتبت تفریط جبن و در مرتبت متوسط شجاعت است و قوّت شهوانیه در مرتبت افراط فجور و در مرتبت تفریط جمودو در مرتبت متوسط عفت است و قوت عقلیه در مرتبت افراط جربزة و در مرتبت تفریط بلادت و در مرتبت متوسط حکمت است، و حد متوسط این قوی عدالت است . (از دستور العلماء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٧</span>). <BR><font color=\"Blue\">◄</font> (اصطلاح فقهی ) اجتناب کردن از کبائر و اصرار نکردن بر گناهان صغیره و از کارهای پست رو گرداندن، مانند خوردن در راه و بول درطریق و جز آن . و گفته اند عدل عبارت از اعتدال و استقامت است و آن میل به حق باشد. (از ترجمان علامه ). <BR><font color=\"Blue\">◄</font> (اصطلاح نحوی ) خروج کلمه است از صیغه ٔاصلی خود مانند عُمَر که در اصل عامر و زُفر که در اصل زافر بوده است و آن یکی از اسباب منع صرف باشد. (هدایة فی النحو) (از منتهی الارب ) (از آنندراج ) (از تعریفات جرجانی ). رجوع به عدل تقدیری شود.<br /></font></div>'),
(181682, 'عدل', '<span class=\"hlight\">عدل .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b>(ع اِ) عوض . بدل . معادل . مقابل . برابر <span class=\"hlight\">:</span> <br />گفتم که مرغ نبود دهقان امام را<br />گفتا که مرغ نبود عِدلی دهد خُره .<br /> <font color=\"Red\">سوزنی .</font><br /><BR><font color=\"Blue\">◄</font> هم بار.<br /></font></div>'),
(181683, 'عدل', '<span class=\"hlight\">عدل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) داد دادن . (منتهی الارب ).<br /></font></div>'),
(181684, 'عدل تقدیری', '<span class=\"hlight\">عدل تقدیری .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ ت َ ]</font></b> (ترکیب وصفی، اِ مرکب ) (اصطلاح نحوی ) و خروج اسم از صیغه ٔ اصلی خود است و آن دو قسم است : تحقیقی و تقدیری، تحقیقی خروج آن از اصل محقق باشد و دلالت کند بر وی دلیل بدون منع صرف چون ثلث و مثلث که معدول است از ثلثة ثلثة زیرا که چون یافتند اینها را غیرمنصرف پس محتاج شدند به وجود سببین و یافتند در آن وصف و آن بدون سبب دیگر سبب منع صرف نباشد و سبب دیگر در آن موجود نبود پس دانسته شد اینکه در اینها عدل است و دلالت میکند بر او دلیل دیگر سوای منع صرف و آن این است که چون معنی مکرر باشد لفظ هم مکرر باشد و در اینجا معنی مکرر است نه لفظ پس دانسته شد که اصل اینها لفظ مکرر باشد و آن ثلثة ثلثة است . و عدل تقدیری که خروج اسم باشد از اصل مقید، و دلیل نباشد بر وی غیر منع صرف چون عُمَر که معدول است از عامر و چون یافته شد غیرمنصرف ونبود در وی سببی غیرعَلَمیت و آن کفایت نمیکند فقط در سبب منع صرف پس فرض کرده شد خروج او از عامر. (ازهدایة فی النحو ضمیمه ٔ جامع المقدمات و آنندراج ).<br /></font></div>'),
(181685, 'عدل فرمای', '<span class=\"hlight\">عدل فرمای .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (نف مرکب ) آنکه دستور بعدل دهد. مرد عادل و مجری عدالت <span class=\"hlight\">:</span> رأی جهان آرای مشکل گشای عدل فرمای شاه را بر کلمات صالحات بنده التفاتی نیست . (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">١٦١</span>).دستور عدل فرمای صائب رای گفت . (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">١٥٤</span>).<br /></font></div>'),
(181686, 'عدل فرمایی', '<span class=\"hlight\">عدل فرمایی .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (حامص مرکب ) عمل عدل فرمای . دادگری <span class=\"hlight\">:</span> سنت او عدل فرمایی و سیرت او مملکت آرایی . (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٢٥٠</span>).<br /></font></div>'),
(181687, 'عدل مظفر', '<span class=\"hlight\">عدل مظفر.</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ م ُ ظَف ْ ف َ ]</font></b> (اِخ ) عدالت مظفرالدین شاه قاجار، و این دو کلمه ماده تاریخ مشروطیت ایران است بحساب جُمَّل مطابق <span class=\"hlight\" dir=\"rtl\">١٣٢٤</span> هَ . ق . یعنی تاریخ افتتاح مجلس است، و بر سر درمجلس این جمله را نوشته بودند که نشانه ٔ مشروطیت و نام اولین پادشاه امضا کننده و اجراکننده ٔ آن است .<br /></font></div>'),
(181688, 'عدل نامه', '<span class=\"hlight\">عدل نامه .</span> <font color=\"DarkGreen\"><b>[ ع َم َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ مرکب ) کتاب و نامه ٔ عدل <span class=\"hlight\">:</span> <br />چو دست را به قلم برد و عدل نامه نوشت <br />قلم شود به سر تیغ داد، دست ستم .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(181689, 'عدل ورز', '<span class=\"hlight\">عدل ورز.</span> <font color=\"DarkGreen\"><b>[ ع َ وَ ]</font></b> (نف مرکب ) دادگر. عادل <span class=\"hlight\">:</span> <br />بر هر دو روی سکه ٔ ایام، نام تو<br />خاقان عدل ورز و هنرپرورآمده .<br /> <font color=\"Red\">خاقانی .</font><br />عدل ورزا خسروا پیوند عمرت باد عدل <br />کز جهان عدل است و بس کو را مُعَمَّر ساختند.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(181690, 'عدل ورزی', '<span class=\"hlight\">عدل ورزی .</span> <font color=\"DarkGreen\"><b>[ ع َ وَ ]</font></b> (حامص مرکب ) دادگری .<br /></font></div>'),
(181691, 'عدل ورزیدن', '<span class=\"hlight\">عدل ورزیدن .</span> <font color=\"DarkGreen\"><b>[ ع َ وَ دَ ]</font></b> (مص مرکب ) عدالت کردن . دادگری کردن <span class=\"hlight\">:</span> <br />همه عدل ورز و همه مکرمت کن <br />همه مال بخش و همه مَحمدت خر.<br /><font color=\"Red\">ناصرخسرو (دیوان چ تقوی ص <span class=\"hlight\" dir=\"rtl\">١٦٨</span>).</font><br /></font></div>'),
(181692, 'عدل پرور', '<span class=\"hlight\">عدل پرور.</span> <font color=\"DarkGreen\"><b>[ ع َ پ َرْ وَ ]</font></b> (نف مرکب ) پرورنده ٔ عدل . مربی عدالت . دادپرور <span class=\"hlight\">:</span> <br />ز اقبال عدل پرور او جای آن بود<br />کز ننگ زنگ بازرهد یکسر آینه .<br /> <font color=\"Red\">خاقانی .</font><br />و نسیم خصائل عدل پرور و شمیم شمایل فضل گستر او جماد و موات را چون دم مسیحا حرکت وحیات آورد. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٣٤٢</span>).<br /></font></div>'),
(181693, 'عدل کردن', '<span class=\"hlight\">عدل کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ دَ ]</font></b> (مص مرکب )عدالت کردن . بعدل رفتار کردن . داد دادن . داد کردن . دادگستری . از روی عدل و انصاف عمل کردن <span class=\"hlight\">:</span> <br />عدل کن زانکه درولایت دل <br />درِ پیغمبری زند عادل .<br /> <font color=\"Red\">سنائی .</font><br />حاکمی گر عدل خواهی کرد با ما یا ستم <br />بنده ایم ار صلح خواهی کرد با ما یانبرد.<br /> <font color=\"Red\">سعدی .</font><br />پادشاهی که عدل نکند و نیکنامی توقع دارد بدان ماند که جو همی کارد و امید گندم دارد. (مجالس سعدی ص <span class=\"hlight\" dir=\"rtl\">٢١</span>).<br /></font></div>'),
(181694, 'عدل گستر', '<span class=\"hlight\">عدل گستر.</span> <font color=\"DarkGreen\"><b>[ ع َ گ ُ ت َ ]</font></b> (نف مرکب ) دادگستر. که بسط عدل و داد دهد. عادل <span class=\"hlight\">:</span> <br />تخم اقبال در زمین بقا<br />بانوی عدل گستر افشانده ست .<br /> <font color=\"Red\">خاقانی .</font><br />امثله ٔ قضا بر موجب رضای او موشح برأی انور ملک پرور عدل گستر. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٢٧٤</span>).<br /></font></div>'),
(181695, 'عدل گستری', '<span class=\"hlight\">عدل گستری .</span> <font color=\"DarkGreen\"><b>[ ع َ گ ُ ت َ ]</font></b> (حامص مرکب ) عمل دادگستر. دادگستری <span class=\"hlight\">:</span> <br />مفخر اول البشر، مهدی آخر زمان <br />وحی بجانش آمده آیت عدل گستری .<br /> <font color=\"Red\">خاقانی (دیوان چ سجادی ص <span class=\"hlight\" dir=\"rtl\">٤٢٣</span>).</font><br />اگر عدل گستری در ذات او مفطور بوده است و رعیت پروری ... (ترجمه ٔ محاسن اصفهان ص <span class=\"hlight\" dir=\"rtl\">٨١</span>). از فضیلت استعداد ملک پروری و شرف استبداد عدل گستری ... (ترجمه ٔمحاسن اصفهان ص <span class=\"hlight\" dir=\"rtl\">٦٩</span>).<br /></font></div>'),
(181696, 'عدلام', '<span class=\"hlight\">عدلام .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) (به عبری عدل قوم )، (پنهان کننده )اسم مغاره ای که در حوالی بیت لحم بوده داود در آنجامتواری گردیده و بر حسب تقلید در وادی قریطون در شرق بیت لحم میباشد و طول مغاره <span class=\"hlight\" dir=\"rtl\">٥٥٠</span> قدم و دارای دهلیزهای بسیار است الا آنکه بزعم کاندر در وادی ایله در نزدیکی شهر عدلام بمسافت <span class=\"hlight\" dir=\"rtl\">١٣</span> میل بطرف غربی بیت لحم واقع است و در حوالی این شهر مغاره های بسیار است که فی الحقیقه از برای معاونان داود بسیار مناسب است اما مغاره های بیت جبرین که بزعم بعضی مغاره ٔ عدلام میباشد بسیار مرطوبی و سرد و پر از خفاشها است به حدی که برزگران آن نواحی نیز در آنجا زیست نتوانند کرد بر خلاف مغاره های عدلام که همواره مسکونند و در غایت استحکام و پایداری میباشند و از آن جمله معدودی است که از دویست الی سیصد مرد را گنجایش دهد و اسم مغاره ها عبدالماء است و محتمل است که لفظ مرقوم همان تصحیف عدلام باشد. (قاموس کتاب مقدس ). <BR><font color=\"Blue\">◄</font> شهر بزرگی از کنعانیان است که در قسمت یهودا واقع بود که در رحبعام آن را محصون نمود و در نبوت میکاهی نبی مذکور است و یهود بعد از مراجعت در آنجا سکونت ورزیدند. و کانوو کاندر گمان دارند که در وادی سنط بمسافت دو میل ونصف به جنوبی شوکوه واقع است . (قاموس کتاب مقدس ).<br /></font></div>'),
(181697, 'عدلة', '<span class=\"hlight\">عدلة.</span> <font color=\"DarkGreen\"><b>[ع َ ل َ ]</font></b> (ع ص ) مؤنث عدل و قد یؤنث . یقال رجل عدل و امراءة عدل و عدلة؛ زن داد دهنده . (منتهی الارب ).<br /></font></div>'),
(181698, 'عدلة', '<span class=\"hlight\">عدلة.</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ل َ ]</font></b> (ع ص، اِ) شایستگان گواهی . (منتهی الارب ). المزکّون للشهود. تزکیه شوندگان از شهود. (قطرالمحیط) (از اقرب الموارد). عُدَلة.<br /></font></div>'),
(181699, 'عدلی', '<span class=\"hlight\">عدلی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب به عدل . <BR><font color=\"Blue\">◄</font> (اِ) قسمی از سکه بوده است . پول <span class=\"hlight\">:</span> <br />صد بوسه بر آن خط زد و گفتا که در آنجاست <br />سیصد درم عدلی غلطان و مدور.<br /> <font color=\"Red\">سوزنی .</font><br />اتفاقاً مرا صد دیناری عدلی بود گفتند باقی آن صد دینار عدلی را بیار. (انیس الطالبین ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span>).جوالهای بسیار بود پر از عدلی . (انیس الطالبین ص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span>). و آن عدلی را حضرت خواجه ٔ ما قدس اﷲ روحه خرج کرد... عدلی را بر میان بسته بودم گشاده شد و افتاد. (انیس الطالبین ). این مقدار عدلی بمن خواهد رسید... به کابل میروم که سه هزار دینار عدلی دارم . (انیس الطالبین ص <span class=\"hlight\" dir=\"rtl\">٢١١</span>).<br /></font></div>'),
(181700, 'عدلی', '<span class=\"hlight\">عدلی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) تخلص شعری سلطان بایزیدبن سلطان محمد فاتح است . رجوع به سلطان بایزید شود.<br /></font></div>'),
(181701, 'عدلی مذهب', '<span class=\"hlight\">عدلی مذهب .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ هََ ]</font></b> (اِخ ) معتزلی . پیرو معتزله . پیرو عدلیه . رجوع به عدلیه شود.<br /></font></div>'),
(181702, 'عدلین', '<span class=\"hlight\">عدلین .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع ص، اِ) تثنیه ٔ عدل است . دو گواه عادل . دو مرد صالح شایسته ٔ گواهی . (غیاث اللغات ) (آنندراج ). رجوع به شاهد عدل شود.<br /></font></div>'),
(181703, 'عدلین', '<span class=\"hlight\">عدلین .</span> <font color=\"DarkGreen\"><b>[ ع ِ ل َ]</font></b> (ع اِ) تثنیه ٔ عِدل . دو لنگه بار. (قطرالمحیط).<br /></font></div>'),
(181704, 'عدلیه', '<span class=\"hlight\">عدلیه .</span><font color=\"DarkGreen\"><b>[ ع َ لی ی َ ]</font></b> (اِخ ) معتزله . فرقه ٔ معتزله . «معتزله خود را عدلیه نامند، زیرا گویند چون خداوند حکیم است و از حکیم جز خیر و صلاح نیاید و به حکم عقل رعایت مصالح عباد بر او واجب است، قبیح است بر او که بنده را مجبور کند بر عملی قبیح یا حَسَن، پس او را بدان عمل عقوبت نماید یا ثواب دهد، و این اصل را عدل نامند. بر خلاف اشعریه که گویند از روی عقل بر خداوند چیزی واجب نیست، نه صلاح و نه اصلح، و خدا فعال مایشاء است، اگر همه ٔ بندگان خود را به بهشت برد یا خود همه را به دوزخ فرستد، حیف و جوری نکرده است ». (قزوینی تعلیقات چهارمقاله چ معین ص <span class=\"hlight\" dir=\"rtl\">٥٢</span>) (فرهنگ فارسی معین ).<br /></font></div>'),
(181705, 'عدلیه', '<span class=\"hlight\">عدلیه .</span> <font color=\"DarkGreen\"><b>[ ع َ لی ی َ ]</font></b> (اِ) نام پول است و آن بر دو قسم است : قدیم و جدید، و هر دو نام پول مصری است که از طلا و ارزش آن بر حسب زمان و مکان مختلف بوده است مثلاً عدلیه ٔ جدیده در سال <span class=\"hlight\" dir=\"rtl\">١٢٥٦</span> هَ . ق . شانزده قروش بوده است . عدلیه را مردم عراق عادلی گفته اند (عادلی صائغ و عادلی مکرر). (از نقودالعربیة ص <span class=\"hlight\" dir=\"rtl\">١٧٩</span>).<br /></font></div>'),
(181706, 'عدلیه', '<span class=\"hlight\">عدلیه .</span> <font color=\"DarkGreen\"><b>[ ع َ لی ی َ ]</font></b> (اِخ ) (وزارت ...) وزارت دادگستری . یکی از چند وزارتخانه ٔ کشور ایران . عدلیه نخستین بار در سال <span class=\"hlight\" dir=\"rtl\">١٢٧٥</span> هَ . ق، به امر ناصرالدین شاه تأسیس گردید. طرز کار عدلیه چنین بود که شکایات و دعاوی حقوقی را به حکام شرع ارجاع میکردند و حاکم شرع یعنی روحانی و مجتهد درباره ٔ شکایات حکم میداد این احکام ضمانت اجرائی نداشت . دعاوی غیرحقوقی در ادارات دولتی حل و فصل می شد، در شهرستانها نیز امور شرعی را علما و امور جزائی و انتظامی را حکومت ها حل و فصل میکردند. در سال <span class=\"hlight\" dir=\"rtl\">١٣٢٤</span> هَ . ق . بر طبق قانون اساسی کشور قوه ٔ قضائیه مرجع جداگانه ای پیدا کرد. در سالهای <span class=\"hlight\" dir=\"rtl\">١٣٢٤</span> و <span class=\"hlight\" dir=\"rtl\">١٣٢٥</span> هَ . ق . در وزارت عدلیه محاکمی بنام محکمه ٔجزا، محکمه ٔ تجارت و محاکم دیگر تشکیل شد ولی بعداًبه محاکم صلحیه، ابتدائی، استیناف و تمیز تغییر یافت . محکمه ٔ جزا در سال <span class=\"hlight\" dir=\"rtl\">١٣٢٥</span> هَ . ق . تشکیل شد و در سال <span class=\"hlight\" dir=\"rtl\">١٣٢٨</span> مشیرالدوله قانون تشکیلات عدلیه را به مجلس آورد و پس از مذاکرات و مخالفتهای شدید به تصویب رسید.در سال <span class=\"hlight\" dir=\"rtl\">١٣٠٥</span> هَ . ق . در سلطنت رضاشاه پس از لغو کاپیتولاسیون سازمان موجود عدلیه منحل گردید و اجازه ٔ تشکیل مجدد وزارت عدلیه داده شد و مرحوم داور عدلیه رابر اساس نوینی بنیاد نهاد. فرهنگستان نام عدلیه را به دادگستری تبدیل کرد. سازمان قضائی وزارت دادگستری در حال حاضر بموجب قوانین مصوب تیر ماه <span class=\"hlight\" dir=\"rtl\">١٣٠٧</span> و <span class=\"hlight\" dir=\"rtl\">١٣١٥</span>و لایحه ٔ قانونی اسفند <span class=\"hlight\" dir=\"rtl\">١٣٣٣</span> و قوانین اصلاحی <span class=\"hlight\" dir=\"rtl\">١٣٣٥</span> تشکیلات عدلیه مشتمل است بر دادگاه های عمومی و دادگاه های اختصاصی و دیوان عالی کشور. دادگاههای عمومی از لحاظ ترتیب و ترتب در صلاحیت و اهمیت عبارتند از: دادگاههای استان، دادگاههای شهرستان، دادگاههای بخش . (در سرتاسر کشور <span class=\"hlight\" dir=\"rtl\">٦٦</span> شعبه ٔ دادگاه استان و <span class=\"hlight\" dir=\"rtl\">١٦٩</span> شعبه ٔ دادگاه شهرستان و <span class=\"hlight\" dir=\"rtl\">١٩٢</span> شعبه ٔ دادگاه بخش دائر بوده است ).<br />دادگاههای اختصاصی عبارتند از دادگاه عالی انتظامی قضات دادگاه عالی تجدید نظر انتظامی قضات و دادگاه دیوان کیفر.<br />دادگاه شرع، هیأت های تجدید نظر املاک واگذاری . در مرکز هر شهرستان و یا استان که دادگاه شهرستان و دادگاه استان دایر است یک دادسرای شهرستان و یک دادسرای استان انجام وظیفه می کندو بعلاوه در معیت دادگاه دیوان کیفر و دادگاه عالی انتظامی قضات نیز دادسرای دیوان کیفر و دادسرای انتظامی قضات وجود دارد. مافوق کلیه ٔ محاکم، دیوان عالی کشور است که عالی ترین مرجع قضائی محسوب میشود و تصمیماتش قطعی و نهائی است و پاره ای از تصمیمات آن که در موارد خاص اتخاذ میگردد در حکم قانون تلقی میشود و برای تمام محاکم و مراجع قضائی لازم الاتباع میباشد. دیوان مزبور دارای <span class=\"hlight\" dir=\"rtl\">١٢</span> شعبه و یک دادسرا است و دادستان کل کشور ریاست دادسرای آن را بعهده دارد. برای اداره ٔ امور دادگاهها و دادسراها و دیگر مراجع قضائی تا اول سال <span class=\"hlight\" dir=\"rtl\">١٣٤٧</span> مجموعاً <span class=\"hlight\" dir=\"rtl\">١٦٩٧</span> قاضی شاغل وجود داشته است . علاوه بر مراجع قضائی مذکور با شرکت دادن مردم در حل و فصل امور قضائی <span class=\"hlight\" dir=\"rtl\">١٣٣٧</span> خانه ٔ انصاف و <span class=\"hlight\" dir=\"rtl\">٤٩</span> شورای داوری تا تیرماه <span class=\"hlight\" dir=\"rtl\">١٣٤٧</span> در کشور تشکیل شد.<br /></font></div>'),
(181707, 'عدم', '<span class=\"hlight\">عدم .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ]</font></b> (ع اِمص ) نیستی . (ناظم الاطباء) (منتهی الارب ) (اقرب الموارد). مرگ . فقدان . (ناظم الاطباء) نابودی . مقابل وجود. مقابل هستی <span class=\"hlight\">:</span> وجودش همیشه باد و عدم او هیچ گوش مشنواد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٣٣</span>).<br />اندر مشیمه ٔ عدم از نطفه ٔ وجود<br />هر دو مصورند ولی نامصورند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />برده از آن سوی عدم رخت و تخت <br />مانده از این سوی جهان خان ومان .<br /> <font color=\"Red\">خاقانی .</font><br />دردا که از برای شکست وجود من <br />سوی عدم شد آن خلف روح پیکرم .<br /> <font color=\"Red\">خاقانی .</font><br />آن را که غمگسار تو باشی چه غم خورد<br />وان را که جان توئی چه دریغ عدم خورد.<br /> <font color=\"Red\">خاقانی .</font><br />زین تنگنای وحشت اگر بازرستمی <br />خود را به آستان عدم بازبستمی .<br /> <font color=\"Red\">خاقانی .</font><br />طریق عاشقی چبود، به دست بی خودی خود را<br />به فتراک عدم بستن به دنبال فنا رفتن .<br /> <font color=\"Red\">خاقانی .</font><br />اول کاین عشق پرستی نبود<br />در عدم آوازه ٔ هستی نبود.<br /> <font color=\"Red\">عطار.</font><br />درنگر و خلق جهان را ببین <br />روی نهاده به عدم ای غلام .<br /> <font color=\"Red\">عطار.</font><br />از وجودم می گریزی در عدم <br />در عدم من شاهم و صاحب علم .<br /> <font color=\"Red\">مولوی .</font><br />شرف مرد به جود است و کرامت نه سجود<br />هر که این هر دو ندارد عدمش به ز وجود.<br /> <font color=\"Red\">سعدی .</font><br />گمان مبر که جهان اعتماد را شاید<br />که بی عدم نبود هر چه در وجود آید.<br /><font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">از عدم درشدن </span> ؛ کنایه از مرده زنده شدن . (ناظم الاطباء) (مؤید الفضلاء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">از عدم بگذرد</span> ؛ یعنی از مرده زنده شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم کردن </span> ؛ نابود کردن . معدوم کردن . نیست کردن .<br /><BR><font color=\"Blue\">◄</font> ناقص کردن . بی چیز و محتاج نمودن . (ناظم الاطباء).<br /> <BR><font color=\"Blue\">◄</font> (اصطلاح فلسفه ) در اصطلاح فلسفه، مقابل وجود است . توضیح آن اینکه برای وجود دو اعتبار است یکی وجودِ مطلق و دیگر مطلق ِ وجود. هر گاه عدم مقابل مطلق وجود باشد، مطلق عدم است، و اگر مقابله ٔ آن به اعتبار وجود مطلق باشد، عدم المطلق است، مفاد اول سلب وجود مطلق است . رجوع به وجود و عدم ملکه شود. (از شرح منظومه ص <span class=\"hlight\" dir=\"rtl\">٧٨</span> بشرح فرهنگ علوم عقلی سجادی ص <span class=\"hlight\" dir=\"rtl\">٣٥٢</span>). <BR><font color=\"Blue\">◄</font> کلمه ٔ نفی که چون بر سر اسمی درآید آن را منفی میکند مانند:<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم استحقاق </span> ؛ مستحق نبودن . شایستگی کاری نداشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم استعداد</span> ؛بی استعداد بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم اشتهار</span> ؛ مشهور نبودن . شهرت نداشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم اعتدال </span> ؛ معتدل نبودن . نامعتدل بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم اعتماد</span> ؛ سؤظن . بدگمانی . بی اعتمادی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم التفات </span> ؛ بی ملاحظگی . بی توجهی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم امساک </span> ؛ قناعت نکردن . تبذیر و اسراف کردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم امکان </span> ؛ محال بودن . ممکن نبودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم انحلال </span> ؛ منحل نشدن . بر جا بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم انقطاع </span> ؛قطع نشدن . همواره بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم اهلیت </span> ؛ اهل نبودن . شایسته ٔ کاری نبودن .<BR>۩ اصطلاح حقوقی که حق استفاده از حقوق مدنی نداشته باشد. اهلیت نداشتن برای کاری . ناسزاواری .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم بضاعت </span> ؛ توانائی مالی نداشتن . فقیر بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم تأثیر</span> ؛ بی اثر بودن . تأثیر نکردن . کار نکردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم تداخل </span> ؛ عدم نفوذ اشیاء در یکدیگر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم تساوی </span> ؛ مختلف بودن . مساوی نبودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم تشخیص </span> ؛ تشخیص ندادن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم تماسک </span> ؛ خودداری نکردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم تمکن </span> ؛ فقیر بودن . نادار بودن . استطاعت نداشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم تناهی </span> ؛ نامتناهی بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم توفیق </span> ؛ موفق نبودن . توفیق نداشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم ثبات </span> ؛ بی ثبات بودن . ثابت نبودن . بی ثباتی . ناپایداری . پایدار نبودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم جواز</span> ؛ روا نبودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم حضور</span> ؛ حاضر نبودن ونشدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم خلوص </span> ؛ خلوص نداشتن . خالص نبودن هر چیزی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم دیانت </span> ؛ بی دین بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم ذکاوت </span> ؛ کم هوش و یا بی هوش بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم ذوق </span> ؛ بی ذوق بودن . بی ذوقی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم رأفت </span> ؛ مهربان نبودن . نامهربانی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم رؤیت </span> ؛ رؤیت نکردن . ندیدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم سخاوت </span> ؛ سخی نبودن . بی سخاوتی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم سیاست </span> ؛ بی سیاستی . سیاست نکردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم شهامت </span> ؛ دلیر نبودن . شهامت معنوی نداشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم ضرورت </span> ؛ضروری نبودن . نیازمندی نبودن . نبودن ضرورت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم طهارت </span> ؛ پاک نبودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم عقوبت </span> ؛ جزا نبودن . کیفر نبودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم عنایت </span> ؛ بی توجه بودن . لطف و محبت نداشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم غفلت </span> ؛ غافل نشدن . غفلت نکردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم فرصت </span> ؛ فرصت نکردن . فرصت نداشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم قابلیت </span> ؛قابلیت و لیاقت و شایستگی نداشتن . ناسزاواری .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم کراهت </span> ؛ نبودن ناخوشایندی . کراهت نداشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم کفایت </span> ؛ بی کفایت و بی لیاقت بودن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم لیاقت </span> ؛ شایستگی نداشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم مرکزیت </span> ؛ مرکزیت نداشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم مروت </span> ؛ بی انصاف بودن . جوانمردی نداشتن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم وجاهت </span> ؛ بدگل بودن . خوشگل نبودن .<BR>۩ وجهه نداشتن میان مردم .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدم وجدان </span> ؛ بی وجدانی .<BR>۩ نایافتن ؛ در مثل است که عدم وجدان دلالت بر عدم وجود نمی کند.<br /></font></div>'),
(181708, 'عدم', '<span class=\"hlight\">عدم .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ع مص ) درویش گردیدن .نیازمند شدن . (از قطرالمحیط) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> گول گردیدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> فقدان . (قطرالمحیط). گم گردیدن . (زوزنی ) (منتهی الارب ). و اغلب بر فقدان مال استعمال میشود. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نایافتن . (المصادر زوزنی ). <BR><font color=\"Blue\">◄</font> مقابل ملکه . رجوع به عدم و ملکه شود. <BR><font color=\"Blue\">◄</font> منع کردن، یقال ما یعدمنی هذا الامر؛ یعنی نمی گذارد مراو تجاوز نمی کند. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِمص )فقر. (تاج المصادر). درویشی . (منتهی الارب ). عُدم .<br /></font></div>'),
(181709, 'عدم', '<span class=\"hlight\">عدم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) عَدم . رجوع به عَدَم شود.<br /></font></div>'),
(181710, 'عدم', '<span class=\"hlight\">عدم .</span> <font color=\"DarkGreen\"><b>[ ع ُ دُ ]</font></b> (ع مص ) عَدم . رجوع به عَدَم شود.<br /></font></div>'),
(181711, 'عدم', '<span class=\"hlight\">عدم .</span> <font color=\"DarkGreen\"><b>[ ع َ دِ ]</font></b> (ع ص ) درویش و نیازمند. ج، عُدماء. (از تاج المصادر) (قطرالمحیط) (منتهی الارب ).<br /></font></div>'),
(181712, 'عدم آباد', '<span class=\"hlight\">عدم آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (اِ مرکب )کنایه از دنیای دیگرست . مرگ که خاتمت زندگی است و مرادف با عدم خانه و عدم زار و عدم گاه است <span class=\"hlight\">:</span> <br />کس نیامد به جهان کز غم ابنای جهان <br />کف زنان رقص کنان تا عدم آباد نرفت .<br /> <font color=\"Red\">طالب آملی (از آنندراج ).</font><br />اگر اندک حرکتی ... صادر گشتی عقوبت و تنکیل آن به غیر به عدم آباد فرستادن قناعت نکردی . (ترجمه ٔ محاسن اصفهان ). ظلم و عدوان از اطراف امصار و بلاد روی به عدم آباد آورد. (حبیب السیر چ طهران ص <span class=\"hlight\" dir=\"rtl\">٣٢٢</span>).<br /></font></div>'),
(181713, 'عدم خانه', '<span class=\"hlight\">عدم خانه .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) جهان نیستی . عالم قبل از وجود. <BR><font color=\"Blue\">◄</font> عالم بعد از وجود <span class=\"hlight\">:</span> <br />خلوت خود ساز عدم خانه را<br />بازگذار این ده ویرانه را.<br /> <font color=\"Red\">نظامی .</font><br />هستی او تا به عدم خانه بود<br />نقش وجود از همه بیگانه بود.<br /><font color=\"Red\">امیرخسرو (از آنندراج ).</font><br /></font></div>'),
(181714, 'عدم قنیه', '<span class=\"hlight\">عدم قنیه .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ م ِ ق ُ ی َ ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به عدم و قنیه شود.<br /></font></div>'),
(181715, 'عدم مجامع', '<span class=\"hlight\">عدم مجامع.</span> <font color=\"DarkGreen\"><b>[ ع َ دَ م ِ م ُ م ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) مراد از عدم مجامع مسبوقیت وجود به عدم ذاتی است که از جهت ذاتش «لیس » محض است و از جهت علت و بواسطه ٔآن «ایس » است و در نتیجه حدوث ذاتی مسبوق به عدم مجامع است و بالجمله عدم مجامع آن است که مرتبت عدمش مجامع با وجودش باشد که در عین آنکه بالقوه است مجامعبا مرتبتی خاص از وجود است . (از شرح منظومه ص <span class=\"hlight\" dir=\"rtl\">٧٥</span>).<br /></font></div>'),
(181716, 'عدم مطلق', '<span class=\"hlight\">عدم مطلق .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ م ِ م ُ ل َ ]</font></b> (ترکیب اضافی، اِ مرکب ) عدم مطلق مقابل عدم ملکه است که شأنیت وجود دارد. (از شفا ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٢٧</span>).<br /></font></div>'),
(181717, 'عدم مقابل', '<span class=\"hlight\">عدم مقابل .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ م ِ م ُ ب ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) مسبوقیت زمانیات را به عدم زمان عدم مقابل گویند در مقابل عدم مجامع و بالجمله عدم مقابل عدم زمانی است زیرا هیچ یک از مراتب وجودی حوادث زمانی با یکدیگر جمع نمیشوند و از این جهت عدم فکی در سلسله ٔ عرضیه هم نامند. (از شرح منظومه ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>).<br /></font></div>'),
(181718, 'عدم ملکه', '<span class=\"hlight\">عدم ملکه .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ م ِ م َ ل َ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) یکی از اقسام تقابل است یعنی عدم آنچه در شأنش وجود است و به عبارت دیگر که در شأن شخص یا نوع یک جنس آن باشد که متصف به وجود باشد چنانکه عدم البصر به انسان کور میتوان گفت به اعتبار آنکه از شأن اوست که مبصر باشدو به حیوان بدون شعور میتوان گفت زیرا از شأن جنس او هست که یک نوع از انواعش که انسان است دارای شعورباشد. (از شفا، ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢</span>). رجوع به عدم و قنیه شود.<br /></font></div>'),
(181719, 'عدم و قنیه', '<span class=\"hlight\">عدم و قنیه .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ وَ ق ُن ْ ی َ ]</font></b> (ترکیب عطفی، اِ مرکب ) عدم و ملکه . رجوع به عدم و ملکه شود.<br /></font></div>'),
(181720, 'عدم و ملکه', '<span class=\"hlight\">عدم و ملکه .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ وَ م َ ل َ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (ترکیب عطفی، اِ مرکب ) عدم ملکه . رجوع به عدم ملکه شود.<br /></font></div>'),
(181721, 'عدمل', '<span class=\"hlight\">عدمل .</span> <font color=\"DarkGreen\"><b>[ ع ُ م ُ ]</font></b> (ع ص ) دیرینه و سالخورده از چیزی . <BR><font color=\"Blue\">◄</font> سطبر و کهن از درخت و سوسمار. (منتهی الارب ) (آنندراج ). عدامل . (منتهی الارب ). عدملی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کرکس نر. (منتهی الارب ) (آنندراج ). ج، عدامل . (ناظم الاطباء).<br /></font></div>'),
(181722, 'عدملی', '<span class=\"hlight\">عدملی .</span> <font color=\"DarkGreen\"><b>[ ع ُ م ُ لی ی ]</font></b> (ع ص ) دیرینه و سالخورده از چیزی . (قطرالمحیط) (منتهی الارب )(آنندراج ). عداملی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سطبر و کهنه از درخت و سوسمار. (قطرالمحیط) (منتهی الارب ). عداملی . عدمل . (منتهی الارب ). رجوع به عدمل شود.<br /></font></div>'),
(181723, 'عدمول', '<span class=\"hlight\">عدمول .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) غوک . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (ص ) دیرینه . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181724, 'عدن', '<span class=\"hlight\">عدن .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) جاودان . جاودانی . جنات عدن ای، اقامة. (ناظم الاطباء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">بهشت عدن </span> ؛ بهشت اقامت . جنات عدن <span class=\"hlight\">:</span> <br />یکی چون بهشت عدن، یکی چون هوای دوست <br />یکی چون گلاب تلخ، یکی چون بت بهار.<br /> <font color=\"Red\">فرخی .</font><br />بر دم طاوس خواهی کرد نقشی خوبتر<br />در بهشت عدن خواهی کشت شاخ نارون .<br /> <font color=\"Red\">منوچهری .</font><br />اندرآمد نوبهاری چون مهی <br />چون بهشت عدن شد هر مهمهی .<br /> <font color=\"Red\">منوچهری .</font><br />سوی بهشت عدن یکی نردبان کنم <br />یک پایه از صلات و دگر پایه از صیام .<br /> <font color=\"Red\">ناصرخسرو.</font><br />مهدی آخر زمان المقتفی باﷲ که هست <br />خاک درگاهش بهشت عدن عدنان آمده .<br /> <font color=\"Red\">خاقانی .</font><br />بهشت عدن جای حور باشد<br />چو در دوزخ رود رنجور باشد.<br /> <font color=\"Red\">نظامی .</font><br />بهشت عدن اگر خواهی بیا با ما به میخانه <br />که از پای خُمَت یکسر به حوض کوثر اندازیم .<br /> <font color=\"Red\">حافظ.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">جنات عدن </span> ؛ باغ بهشت <span class=\"hlight\">:</span> <br />جنات عدن خاک در زهرا<br />رضوان ز هشت خلد بود عارش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />سه ماه از تمنای جنات عدن <br />به دست زبانی زبون آمدیم .<br /> <font color=\"Red\">خاقانی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">فردوس عدن </span> ؛ بهشت عدن <span class=\"hlight\">:</span> <br />فردوس عدن گشت روان تا بفرخی <br />باز آمدی به مرکز دارالقرار ملک .<br /><font color=\"Red\">مسعودسعد.</font><br /></font></div>'),
(181725, 'عدن', '<span class=\"hlight\">عدن .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) اقامت کردن . (اقرب الموارد) (منتهی الارب ) (قطرالمحیط). <BR><font color=\"Blue\">◄</font> همیشه بودن به جایی . (قطرالمحیط) (از اقرب الموارد) (منتهی الارب ) (غیاث اللغات ) (فرهنگ نظام ). <BR><font color=\"Blue\">◄</font> نیرو دادن زمین را به سرگین ؛ عدن الارض . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> تباه کردن درخت را به تبر و مانند آن ؛ عدن الشجر. (از اقرب الموارد) (آنندراج ) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> برکندن سنگ . (قطرالمحیط) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دراز شدن خرمابن . (آنندراج ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> همیشگی کردن شتر بر علف و گیاه شور. گوالیدن و لازم گرفتن آن را. (از اقرب الموارد) (از قطرالمحیط) (از منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181726, 'عدن', '<span class=\"hlight\">عدن .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ع اِ) گیاهی است . (اقرب الموارد).<br /></font></div>'),
(181727, 'عدن', '<span class=\"hlight\">عدن .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (اِخ ) شهری است از شهرهای مشهور عربستان واقع بر ساحل دریای هند از جانب یمن . منطقه ای است که تا حدودی کم آب است، آب مشروب آنها از چشمه و رود تأمین میشود. وضع تجارتی خوبی دارد و محل تجمع تجار و مراکب هندی است . از محصولات آن قهوه است که صادر میشود. و مروارید خوب از آنجا حاصل میشود. و به قول ابومحمد الحسن بن احمد الهذانی، عدن قدیم ترین بازارهای عرب است و آن ساحلی است که کوهی بدان احاطه کرده است و راه آن تنها از طریق باب بزبرالحدید به بیان رفت و آمد میشود. بین عدن و صنعاء <span class=\"hlight\" dir=\"rtl\">٦٨</span> فرسخ است . (از معجم البلدان و تاریخ ادبیات ایران ادوارد براون ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٤</span> و حدود العالم ). در منجد آرد:عدن اطلاق بر چند محل شود یکی عدن بمعنی بهشت است و دیگری شهری است، واقع در جنوب غربی جزیره ءالعرب <span class=\"hlight\" dir=\"rtl\">١٩٦٠</span>کیلومتر مساحت تقریبی آن است و یکصد و سی هزار نفر جمعیت دارد و به سال <span class=\"hlight\" dir=\"rtl\">١٩٣٧</span> جزء مستعمرات انگلستان قرار گرفت و اداره ٔ آن به عهده ٔ حاکمی که از طرف دولت بریتانیا معین میشد واگذار شد و سکنه ٔ قسمت عدن شرقی <span class=\"hlight\" dir=\"rtl\">٠٠٠</span>، <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> نفر میباشد، و دیگر اطلاق بر منطقه ٔ حضرموت وجزیره ٔ سقطرة میشود که دارای امارات مستقلی است زیرنفوذ دولت بریتانیا و جمعیت عدن غربی <span class=\"hlight\" dir=\"rtl\">٣٥٠٠٠</span> نفر است بطور تقریب و نیز منطقه ٔ دیگری است در جزیره ٔ عربی، واقع در جنوب غربی بین یمن وحضرموت در تنگه ٔ باب المندب که دارای شیوخ و امارات مستقل است زیر نفوذ دولت بریتانیا و خلیج عدن دریائی بین سواحل سومالی شرقی و مناطق عدن که غرباً به طرف بحر احمر سرازیر میشود و شرقاً به طرف اقیانوس هند. (از المنجد و کیهان سالانه، ص <span class=\"hlight\" dir=\"rtl\">٢٧٠</span>) <span class=\"hlight\">:</span> و چون یمن و حبشه بگرفت قصد عدن کرد و آن را بگرفت . (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٩٦</span>).<br />ای رایت شه نادره لرزانی و قائم <br />بحرعدنی گوئی یا کوه صفائی .<br /> <font color=\"Red\">خاقانی .</font><br />عدن حورپرور و محل لؤلؤ و معدن نقره و فیروزه . (ترجمه ٔ محاسن اصفهان ).<br /></font></div>'),
(181728, 'عدن', '<span class=\"hlight\">عدن .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) (به عبری نعمت دار) موضع آدم و مقر حوا قبل از سقوط. معلوم نیست که درکجا بوده است لکن دو نهر از نهرهای آن یعنی فرات و دجله مشهور است و بعضی برآنند که فیشون همان نهرهندی و جیحون همان رود نیل است . و اکثر رأی این است که باغ عدن در دشت فرات بوده است . (قاموس کتاب مقدس ).<br /></font></div>'),
(181729, 'عدن ابین', '<span class=\"hlight\">عدن ابین .</span> <font color=\"DarkGreen\"><b>[ ع َ اَب ْ ی َ ]</font></b> (اِخ ) جزیره ای است به یمن که ابین بدان اقامت گزیده است . (از اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181730, 'عدن لاعه', '<span class=\"hlight\">عدن لاعه .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ن ُ ع َ ]</font></b> (اِخ ) دهی است از نزدیک عدن ابین . (از اقرب الموارد) (از منتهی الارب ).<br /></font></div>'),
(181731, 'عدنان', '<span class=\"hlight\">عدنان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام یکی از اجداد حضرت رسول است که بسیار فصیح بود. (فرهنگ نظام ) (آنندراج ). در غیاث است که نام یکی از اجداد حضرت رسول است که بغایت فصیح بودند و نسبت عربان تا بعدنان بالاتفاق بثبوت میرسیده . (غیاث اللغات ). نسبت وی را چنین ذکر کرده اند: عدنان بن ازدبن الهمیعبن المقوم بن تارخ بن سرح بن حمل بن قیداربن شالح بن ارفخشدبن سام بن نوح بن لامک بن ادریس بن ماردبن مهلائیل بن قینان بن انوش بن شیث بن آدم .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(181732, 'عدنان', '<span class=\"hlight\">عدنان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) یکی از قبائلی است که انساب عرب بدان منتهی شود. مورخان متفق اند بر آنکه آن از فرزندان اسماعیل بن ابراهیم است و معظم اهل حجاز به عدنان منسوبند بدین ترتیب که عدنان معد، ازمعد نزار و از نزار، ربیعه و مضر پدید آمد و بطون مضر و ربیعة بسیار شدند بدین ترتیب که از ربیعة بنو اسد و عبدقیس و عنزة و بکر و تغلب و وائل و اراقمه و دائل و جز آن منشعب شدند و قبائل مضر بدو شعبه منشعب گردید یکی قیس بن عیلان بن مضر دیگر الیاس بن مضر از قیس بن عیلان غطفان و سلیم و از غطفان بغیض و عبس و ذبیان، و فرع آنها پدید آمد و از سلیم بهتة و هوازن پدیدآمدند از الیاس تمیم و هذیل و اسد و بطون و کنانة منشعب شدند و از کنانة قریش منشعب شد و خود قریش منشعب به شعبی شدند مانند جمح، سهم، عدی، مخزوم، تمیم، زهره، عبدالدار اسدبن عبدالعزی و عبدمناف و از عبدمناف عبدشمس، نوفل، مطّلب و هاشم آمدند و از هاشم رسول اﷲ (ص )، و عباسیون آمدند و از عبد شمس بنو امیه آمدند و بدین وسیله بطون عدنان در سرتاسر حجاز تهامة، نجد، عراق و یمن منتشر شدند حضرت رسول در مقام انتساب وقتی که به یمن رسید توقف کردند و گفتند نسابون دروغ گویند و از عدنان تجاوز نمیکرد. (از اعلام زرکلی ).<br /></font></div>'),
(181733, 'عدنان', '<span class=\"hlight\">عدنان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) موضعی است به یمن . (معجم البلدان ).<br /></font></div>'),
(181734, 'عدنان الموسوی', '<span class=\"hlight\">عدنان الموسوی .</span> <font color=\"DarkGreen\"><b>[ ع َ نُل ْ س َ وی ی ]</font></b> (اِخ ) ابن شریف الرضی محمدبن الحسین الموسوی الحسین الهاشمی نقیب الاشراف بغداد است . پس از وفات عم خود مرتضی به سال <span class=\"hlight\" dir=\"rtl\">٤٣٦</span> هَ . ق . ولایت نقابت یافت و تا مرگ خود به سال <span class=\"hlight\" dir=\"rtl\">٤٤٩</span> بدین سمت بود. (از اعلام زرکلی ).<br /></font></div>'),
(181735, 'عدنانی', '<span class=\"hlight\">عدنانی .</span> <font color=\"DarkGreen\"><b>[ ع َ نی ی ]</font></b> (ص نسبی ) منسوب بعدنان .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">باغ عدنانی </span> ؛ در کوشک باغ عدنانی . (تاریخ بیهقی ).و از سرای عدنانی به باغ فرورود. (تاریخ بیهقی ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">سرای عدنانی </span> ؛ سرایی بوده است بشهر نیشابور <span class=\"hlight\">:</span> از راه بدرگاه آمد و در دهلیز سرای پیشین عدنانی ببست و از این سرای گذشته و از سرای دیگر سخت فراخ و نیکو گذشت . و بودی که سلطان آنجا بودی به سرای عدنانی و آنجا بار دادی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٦</span>). و از سرای عدنانی به باغ فرورود. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span>). و امیر مسعود در صفه ٔ سرای عدنانی نشسته بود با ندیمان . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٢٤</span>).<br /></font></div>'),
(181736, 'عدنانیان', '<span class=\"hlight\">عدنانیان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) اعراب مستعربه را گویند. رجوع به عرب مستعربه شود.<br /></font></div>'),
(181737, 'عدنانیة', '<span class=\"hlight\">عدنانیة.</span> <font color=\"DarkGreen\"><b>[ ع َ نی ی َ ]</font></b> (اِخ ) اراضی ... حجاز و نجدو اراضی مجاور آن از اواسط جزیرةالعرب و آنان را مضریه گویند و معدیه هم نامند. رجوع به قحطانیه شود.<br /></font></div>'),
(181738, 'عدنة', '<span class=\"hlight\">عدنة.</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ن َ ]</font></b> (اِخ ) موضعی است به نجد در جهت شمال . (معجم البلدان ). <BR><font color=\"Blue\">◄</font> پشته ای است نزدیک ملل . (منتهی الارب ).<br /></font></div>'),
(181739, 'عدنة', '<span class=\"hlight\">عدنة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ن َ ]</font></b> (اِخ ) همان عَدنه است که موضعی است به نجد. (معجم البلدان ).<br /></font></div>'),
(181740, 'عدنگ', '<span class=\"hlight\">عدنگ .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ص ) مردم ابله ونامطبوع و نادان را گویند. (از آنندراج ) (برهان ).<br /></font></div>'),
(181741, 'عدنی', '<span class=\"hlight\">عدنی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ نی ی ]</font></b> (ع ص ) مرد کریم الاخلاق، و اصل آن نسبت است به عدن و سپس غلبه یافته است در هر فن عالی . (از اقرب الموارد).<br /></font></div>'),
(181742, 'عدنی', '<span class=\"hlight\">عدنی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ص نسبی ) نسبت است به عدن که شهر مشهوری است به یمن . رجوع به عدنی (ابوعبداﷲ) شود. (از لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٦</span>). <BR><font color=\"Blue\">◄</font> نسبت است به عمل نوعی از لباس که در نیشابور درست کنند به نام الابراد و بر آن سکه ای باشد که آن را سکه ٔ عَدَن نامند. رجوع شود به عدنی (ابوعمر و مکی ...) (از لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٦</span>). جامه ٔ عدنی ... عدنی ... و در نیشابور جامه های عدنی بافد که از آن جمله است ابوسعدمحمدبن ابراهیم حریری نساج که در <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> هَ . ق . در بغداد بمرده است . (از تاج العروس ) (از مهذب الاسماء).<br /></font></div>'),
(181743, 'عدنی', '<span class=\"hlight\">عدنی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (اِخ ) ابوعبداﷲ محمدبن یحیی بن ابی عمر العدنی . ساکن مکه بود. از سفیان بن عیینةوالداروردی و جز آنها روایت کند. و از وی اسحاق بن ابراهیم بن اسماعیل نسفی و ابوالولید الازرقی و جز آنهاروایت دارند. وی مردی ثقه بود. (از لباب الانساب ).<br /></font></div>'),
(181744, 'عدنی', '<span class=\"hlight\">عدنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابوعمرو، مکنی به ابی احمدبن زیادالندی الشاهد نیشابوری .از عبداﷲ بن شیرویه و جز آن حدیث شنید و از وی حاکم ابوعبداﷲ روایت کند. (از لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٦</span>).<br /></font></div>'),
(181745, 'عدنی', '<span class=\"hlight\">عدنی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (اِخ ) نام کوی و محله ای است در نیشابور <span class=\"hlight\">:</span> و میاه از میان آن بیرون آمدی و به خانقاه کوی عدنی فرود آوردند. (اسرارالتوحید). یک روز به کاری به کوی عدنی کویان فروشدم بر در خانقاه انبوهی دیدم پرسیدم که چه بوده است گفتند کسی آمده است . (اسرارالتوحید ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>). از خواجه ابوالفتوح غضایری شنیدم که گفت هر روز نماز دیگر بر در خانقاه شیخ بر سر کوه عدنی کویان دکانی بود آب زدند و برفتند و فرش افکندندی . (اسرارالتوحید ص <span class=\"hlight\" dir=\"rtl\">٨٨</span>). در این کوی، خانقاهی بوده است که در آن خانقاه ابوسعید ابوالخیر در آنجا مجلس میگفت گفتند کسی آمده است از میهنه، شیخ بوسعید ابوالخیرش گویند که پیرو و مقتدای صوفیان است و او را کرامات ظاهر در این خانقاه نزول کرده است و امروز مجلس میگوید. (اسرار التوحید ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>).<br /></font></div>'),
(181746, 'عدو', '<span class=\"hlight\">عدو.</span> <font color=\"DarkGreen\"><b>[ ع َدْوْ ]</font></b> (ع مص ) دویدن اسب . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دویدن خواستن اسب . (منتهی الارب ) (فرهنگ نظام ). <BR><font color=\"Blue\">◄</font> ستم کردن بر کسی . <BR><font color=\"Blue\">◄</font> درگذشتن از حد. <BR><font color=\"Blue\">◄</font> بازگردانیدن و مشغول کردن از کار. <BR><font color=\"Blue\">◄</font> برجستن به سر کسی . <BR><font color=\"Blue\">◄</font> تجاوز کردن . <BR><font color=\"Blue\">◄</font> درگذشتن از کار و ترک دادن . (از اقرب الموارد) (منتهی الارب ). جاوزه و ترکه . <BR><font color=\"Blue\">◄</font> دستبرد زدن دزد بر قماش . و اللص علی القماش . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دشمنی کردن . (از قطرالمحیط).<br /></font></div>'),
(181747, 'عدو', '<span class=\"hlight\">عدو.</span> <font color=\"DarkGreen\"><b>[ ع ِدْوْ ]</font></b> (ع اِ) درازی و پهنای چیزی . <BR><font color=\"Blue\">◄</font> حد و نهایت چیزی . (از منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> سنگ تنک که بدان چیزی را پوشند. (از اقرب الموارد) (از منتهی الارب ) (آنندراج ). ج، عداء.<br /></font></div>'),
(181748, 'عدو', '<span class=\"hlight\">عدو.</span> <font color=\"DarkGreen\"><b>[ ع ُ دُوو ]</font></b> (ع مص ) دویدن اسب . <BR><font color=\"Blue\">◄</font> دویدن خواستن اسب . <BR><font color=\"Blue\">◄</font> ستم کردن بر کسی . <BR><font color=\"Blue\">◄</font> درگذشتن از حد. (از منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> دشمنی کردن . (از قطرالمحیط).<br /></font></div>'),
(181749, 'عدو', '<span class=\"hlight\">عدو.</span> <font color=\"DarkGreen\"><b>[ ع َ دُوو ]</font></b> (ع ص ) دشمن . (از اقرب الموارد) (از منتهی الارب ). و در فارسی بدون تشدید واو بکار رفته است . بدخواه . خلاف صدیق . مقابل دوست . ج، اَعداء <span class=\"hlight\">:</span> <br />کنون کاین سپاه عدو گشت پست <br />از این پس ز کشتن بداریددست .<br /> <font color=\"Red\">دقیقی .</font><br />ز بهرام گردون به بهرام روز<br />ولی را بساز و عدو را بسوز.<br /> <font color=\"Red\">فردوسی .</font><br />به رزم ریزد، ریزد چه چیز، خون عدو<br />به صید گیرد، گیرد چه چیز، شیر ژیان .<br /> <font color=\"Red\">فرخی .</font><br />دولت او غالب است بر عدو و جز عدو<br />طاعت او واجب است بر خدم و جز خدم .<br /> <font color=\"Red\">منوچهری .</font><br />این عاریتی تن، عدوی تست، عدو را؟<br />دانا نگرد خیره چنین تنگ در آغاو.<br /> <font color=\"Red\">ناصرخسرو.</font><br />ابلیس عدوست مر ترا زیرا<br />تو آدم اهل علم و احکامی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گر عدوی من به مشرق است، ز مغرب <br />آسان من نیز خود بدو برسانم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />از دیو وفا چرا طمع داری <br />هرگز جوید کس از عدو دارو؟<br /> <font color=\"Red\">ناصرخسرو.</font><br />از عدوی سگ صفت، حلم و تواضع مجوی <br />زانکه به قول خدای نیست شیاطین امین .<br /> <font color=\"Red\">خاقانی .</font><br />گر به ملک افراسیاب آید عدو<br />شاه، کیخسرومکان باد از ظفر.<br /> <font color=\"Red\">خاقانی .</font><br />گر گذری کند عدو بر طرف ممالکت <br />زحمت او چه کم کند ملک ترا مقرری .<br /> <font color=\"Red\">خاقانی .</font><br />ز هر مقراضه کو چون صبح رانده <br />عدو چون میخ در مقراض مانده .<br /> <font color=\"Red\">نظامی .</font><br />با عدوی خرد مشو گرد کین <br />خرد شوی گر نشوی خرده بین .<br /> <font color=\"Red\">نظامی .</font><br />روی در روی دوست کن بگذار<br />تا عدو پشت دست میخاید.<br /> <font color=\"Red\">سعدی (گلستان ).</font><br />مرا بمرگ عدو جای شادمانی نیست <br />که زندگانی ما نیز جاودانی نیست .<br /> <font color=\"Red\">سعدی .</font><br />عدو زنده سرگشته پیرامنت <br />به از خون او کشته در دامنت .<br /> <font color=\"Red\">سعدی (بوستان ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدوخوار</span> ؛ آنکه دشمن خوار باشد و آنکه دشمن رانابود کند <span class=\"hlight\">:</span> <br />یکی صمصام فرعون کش عدوخواری چو اژدرها<br />که هرگز سیر نبود وی ز مغز و از دل اعدا.<br /> <font color=\"Red\">دقیقی .</font><br />پیش عدوخوار ذوالفقارِ خداوند<br />شخص عدو، روز گیرودار خیار است .<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدوسوز</span> ؛ دشمن سوز. آنکه دشمن را بسوزد و نابودکند <span class=\"hlight\">:</span> <br />درخشنده تیغت عدوسوز باد<br />درفش کیان از تو فیروز باد.<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدوشکنان </span> ؛ دشمن شکن ها. پیروزمندان <span class=\"hlight\">:</span> <br />ای بسا رایت عدوشکنان <br />سرنگون از دعای بیوه زنان .<br /> <font color=\"Red\">(المضاف الی بدایع الازمان ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کید عدو</span> ؛ دشمنی عدو <span class=\"hlight\">:</span> <br />اندرین آرزو همی باشم <br />زانکه ناایمنم ز کید عدو.<br /> <font color=\"Red\">سوزنی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">عدو شود سبب خیر اگر خدا خواهد</span> <br />خمیر مایه ٔ دکان شیشه گر سنگ است .<br /></font></div>'),
(181750, 'عدوات', '<span class=\"hlight\">عدوات .</span> <font color=\"DarkGreen\"><b>[ ع ُ دَ ]</font></b> (ع اِ) ج ِ عُدوة و عِدوة. (منتهی الارب ).<br /></font></div>'),
(181751, 'عدوان', '<span class=\"hlight\">عدوان .</span> <font color=\"DarkGreen\"><b>[ ع َدْ ]</font></b> (اِخ ) حارث بن عمروبن قیس از قیس عیلان از عدنانیه . جدی جاهلی است که مسکن فرزندان آن به طائف بوده بواسطه ٔ غلبه ٔ ثقیف به تهامه کوچ کردند و سپس به افریقیه و جز آن پراکنده شدند. (از اعلام زرکلی ).<br /></font></div>'),
(181752, 'عدوان', '<span class=\"hlight\">عدوان .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ع مص ) دویدن اسب . <BR><font color=\"Blue\">◄</font> دویدن خواستن اسب . (از منتهی الارب ).<br /></font></div>'),
(181753, 'عدوان', '<span class=\"hlight\">عدوان .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ع اِ) ذئب ذوعدوان ؛ گرگی که بر مردم دود و حمله آرد. و منه السلطان ذوعدوان . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص ) الشدید القوی . (قطرالمحیط) (از اقرب الموارد).<br /></font></div>'),
(181754, 'عدوان', '<span class=\"hlight\">عدوان .</span> <font color=\"DarkGreen\"><b>[ ع ُدْ ]</font></b> (ع مص ) بیداد کردن .(ترجمان القرآن ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ستم کردن بر کسی . (منتهی الارب ) (فرهنگ نظام ) <span class=\"hlight\">:</span> <br />ز یأس تو نه عجب در بلاد فرس و عرب <br />که گرگ بر گله یارا نباشدش عدوان .<br /> <font color=\"Red\">سعدی .</font><br /><BR><font color=\"Blue\">◄</font> درگذشتن از حد. (منتهی الارب ) (از فرهنگ نظام ). <BR><font color=\"Blue\">◄</font> دزدیدن چیزی را. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> بازگردانیدن و مشغول کردن از کار. <BR><font color=\"Blue\">◄</font> برجستن بر کسی . <BR><font color=\"Blue\">◄</font> تجاوز کردن و درگذشتن از کار و ترک دادن . <BR><font color=\"Blue\">◄</font> (اِمص، اِ) ستم آشکار. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> طغیان . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> فریاد. (قطرالمحیط). <BR><font color=\"Blue\">◄</font> فساد و بدی . (ناظم الاطباء).<br /></font></div>'),
(181755, 'عدوانی', '<span class=\"hlight\">عدوانی .</span> <font color=\"DarkGreen\"><b>[ ع ُدْ نی ی ]</font></b> (ع ص نسبی ) منسوب به عدوان . <BR><font color=\"Blue\">◄</font> تجاوزکارانه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">تصرف عدوانی </span> ؛ نوعی از غصب است . درفقه در مبحث غصب گفته اند تصرف مال غیر باشد عدواناً. در آئین دادرسی مدنی ص <span class=\"hlight\" dir=\"rtl\">٢٢١</span> آمده است آرد: در هر مورد کسی که مال منقولی را از تصرف متصرفی بدون رضایت او خارج نماید یا مزاحم استفاده ٔ متصرف شود تصرف عدوانی کرده است . دعوی تصرف عدوانی عبارت است از دعوی متصرف سابق که دیگری بدون رضایت او مال غیرمنقول را ازتصرف او خارج کرده و متصرف سابق اعاده ٔ تصرف خود رانسبت به آن مال درخواست نماید. (ص <span class=\"hlight\" dir=\"rtl\">٧٠</span>). در شرایع الاسلام ص <span class=\"hlight\" dir=\"rtl\">٢٣٨</span> آرد: الغصب هوالاستقلال باثبات الید علی مال الغیر عدواناً.<br /></font></div>'),
(181756, 'عدوانی', '<span class=\"hlight\">عدوانی .</span> <font color=\"DarkGreen\"><b>[ ع َدْ ]</font></b> (اِخ ) در رجال لقب ثقیف بن عمرو و سمرةبن ربیعة و جز آنهاست و نسبت آن به بنی محجربن عیاذبن یشکربن عدوان است . (ریحانة الادب ص <span class=\"hlight\" dir=\"rtl\">٦٩٣</span>).<br /></font></div>'),
(181757, 'عدوانی', '<span class=\"hlight\">عدوانی .</span> <font color=\"DarkGreen\"><b>[ ع َدْ ]</font></b> (اِخ ) عبدالعظیم مکنی به ابن ابی الاصبع. رجوع به ابن ابی الاصبع و نیز ریحانة الادب شود.<br /></font></div>'),
(181758, 'عدوانی', '<span class=\"hlight\">عدوانی .</span> <font color=\"DarkGreen\"><b>[ ع َدْ ]</font></b> (اِخ ) یحیی بن یعمر دمشقی عدوانی مکنی به ابوسلیمان . از مشاهیر نحویان بود. از فقه و حدیث و قرائت و لغات اطلاعی داشت . مردی فصیح و بلیغ و عالم به علم ادب بود. نحو را از ابوأسود دوئلی آموخت و حدیث را از عبداﷲبن عباس وعبداﷲبن عمر و جز آنها فرا گرفت . مردی شیعی بود و حجاج بن یوسف او را به خراسان تبعید کرد، در آنجا از طرف یزید بن مهلب قضاوت یافت . وی به سال <span class=\"hlight\" dir=\"rtl\">١١٩</span> یا <span class=\"hlight\" dir=\"rtl\">١٢٩</span> یا <span class=\"hlight\" dir=\"rtl\">١٠٠</span> هَ . ق . درگذشت . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٧٠</span>).<br /></font></div>'),
(181759, 'عدوب', '<span class=\"hlight\">عدوب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) ریگ بسیار. (منتهی الارب ).<br /></font></div>'),
(181760, 'عدوبند', '<span class=\"hlight\">عدوبند.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (نف مرکب ) که عدو را بندد. که عدو را بند کند. که دشمن را به بند آرد. تسخیر و منقاد کننده ٔ دشمن . (از آنندراج ) <span class=\"hlight\">:</span> <br />درشت و تنومند و زورآزمای <br />به تنها عدوبند و لشکرگشای .<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کمند عدوبند</span> ؛ کمند که بدان دشمن بندند <span class=\"hlight\">:</span> <br />کمند عدوبند را شهریار<br />درانداخت چون چنبر روزگار.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(181761, 'عدودنی', '<span class=\"hlight\">عدودنی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ دَ ]</font></b> (ع ص ) شیر شتاب رو و سخت یا منسوب به سوی گشنی یا زمینی . (آنندراج ) (منتهی الارب ).<br /></font></div>'),
(181762, 'عدوس', '<span class=\"hlight\">عدوس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) زن دلیر. (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> رجل عدوس ؛مرد نیک توانا و قوی بر نیروی و رفتار. (از اقرب الموارد) (از منتهی الارب ) (آنندراج ). امراءة عدوس کذلک . <BR><font color=\"Blue\">◄</font> ضبع عدوس ؛ سخت رفتار. (منتهی الارب ).<br /></font></div>'),
(181763, 'عدوس', '<span class=\"hlight\">عدوس .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) به زمین رفتن . (آنندراج ). رفتن آب در زمین .<br /></font></div>'),
(181764, 'عدوف', '<span class=\"hlight\">عدوف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) نیک چشنده . (اقرب الموارد) (منتهی الارب ). ج، عُدف . (منتهی الارب ). یقال ما ذقت عدوفاً و لا عدوفة؛ ای شیئاً. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) خورش ستور. (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> علف . (از قطرالمحیط). علف و این لغت مُضَر است . (منتهی الارب ).<br /></font></div>'),
(181765, 'عدوفة', '<span class=\"hlight\">عدوفة.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b>(ع ص ) تأنیث عدوف . نیک چشنده . <BR><font color=\"Blue\">◄</font> یقال ما ذقت عدوفاً و لا عدوفة؛ أی شیئاً. (منتهی الارب ).<br /></font></div>'),
(181766, 'عدول', '<span class=\"hlight\">عدول .</span><font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) میل کردن از کسی و برگشتن . (از اقرب الموارد) (از منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> بازگردیدن به سوی کسی . <BR><font color=\"Blue\">◄</font> خمیدن راه و کج گردیدن . (از اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> رجوع کردن از رای و عقیده . بازگشت <span class=\"hlight\">:</span> امیرالمؤمنین الطائع باﷲ در مهمات ملک از مشاورت او عدول می جست . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٧٦</span>). از التزام اشارت دوستان که حکم جزم است چون چاره ندید عدول نتوانست . (جهانگشای جوینی ). <BR><font color=\"Blue\">◄</font> بطور کلی عدول از رای در مورد مجتهدی گویند که از مسائل شرعی از رأی و نظر خود عدول کند و آن در موردی است که برخوردبه مدرک و دلائلی خلاف فتوی سابق برای او ظاهر شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدول دادن از رأی </span> ؛ کسی را از رأی و نظرش برگرداندن . رای او رازدن . او را از رأی خود منصرف کردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدول کردن </span> ؛ استنکاف کردن از رأی و نظر و تصمیم خود. اعراض کردن ازکاری که باید انجام دهند.<BR>۩ برگشتن و تخلف کردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدول کردن از</span> ؛ منحرف شدن از <span class=\"hlight\">:</span> و از واجب عدول نشاید کردن . (تفسیر ابوالفتوح ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٢</span>).<br />من آنم ار تو نه آنی که بودی اندر عهد<br />بدوستی که نکردم ز دوستیت عدول .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدول کردن به </span> ؛ بازگشتن به . میل کردن به .<br /></font></div>'),
(181767, 'عدول', '<span class=\"hlight\">عدول .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (اِخ ) نام مردی که کشتی بسیار نیکو می ساخت . (منتهی الارب ) (آنندراج ). عدولی .<br /></font></div>'),
(181768, 'عدول', '<span class=\"hlight\">عدول .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) گواه مقبول . مرد راست گو و بسیار عادل . (آنندراج ) <span class=\"hlight\">:</span> <br />پس فرستاد آن طرف یک دو رسول <br />حاذقان و کافیان بس عدول .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(181769, 'عدول', '<span class=\"hlight\">عدول .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ عادل . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ج ِ عَدل . (آنندراج ). مردم عادل . عادلان <span class=\"hlight\">:</span> تا در حضور جماعتی از اعیان و عدول و ثقات قصه ٔ حال از قبه تارکبه واز اول تا آخر بگویند. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٢٩٦</span>).<br />بیار ساقی و همسایه گو، دو چشم بیند<br />که من دو گوش بیاکندم از کلام عدول .<br /> <font color=\"Red\">سعدی .</font><br />تنی چند از عدول ... که ملازم مجلس او بودند زمین خدمت ببوسیدند. (گلستان ).<br /></font></div>'),
(181770, 'عدولی', '<span class=\"hlight\">عدولی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ لا ]</font></b> (اِخ ) دهی است به بحرین . (از معجم البلدان ) (منتهی الارب ).<br /></font></div>'),
(181771, 'عدولی', '<span class=\"hlight\">عدولی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ لا ]</font></b> (ع اِ) درخت کهنه و بلند. (منتهی الارب ).<br /></font></div>'),
(181772, 'عدولی', '<span class=\"hlight\">عدولی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ لی ی ]</font></b> (ع اِ) ج ِ عدولیة. (منتهی الارب ). رجوع به عدولیة شود.<br /></font></div>'),
(181773, 'عدولی', '<span class=\"hlight\">عدولی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ لی ی ]</font></b> (اِخ ) عَدول . رجوع به عدول شود. <BR><font color=\"Blue\">◄</font> (ع اِ) کشتیبان . (منتهی الارب ).<br /></font></div>'),
(181774, 'عدولیة', '<span class=\"hlight\">عدولیة.</span> <font color=\"DarkGreen\"><b>[ ع َ دَ لی ی َ ]</font></b> (ص نسبی، اِ) کشتی منسوب به عدولی یا به عدول یا به سوی گروهی که وارد هجر بودند. ج، عَدَولی . (منتهی الارب ).<br /></font></div>'),
(181775, 'عدون', '<span class=\"hlight\">عدون .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) اقامت کردن و همیشه بودن به جائی . (منتهی الارب ). عَدن . رجوع به عدن شود.<br /></font></div>'),
(181776, 'عدوی', '<span class=\"hlight\">عدوی .</span> <font color=\"DarkGreen\"><b>[ ع َدْ وا]</font></b> (ع اِ) بیماری که از یکی به دیگری نقل کند مانند خارش و گر و جز آن . (منتهی الارب ). آنچه از یکی به دیگری سرایت کند از جرب و جز آن . (از اقرب الموارد).<br /></font></div>'),
(181777, 'عدوی', '<span class=\"hlight\">عدوی .</span> <font color=\"DarkGreen\"><b>[ ع َ وی ی ]</font></b> (اِخ ) عبداﷲبن مبارک بن مغیرة مکنی به ابوعبدالرحمن از مشاهیر ادباء بود در نحو و لغت دستی داشت از تألیفات اوست : اقامة اللسان علی صواب المناطق، غریب القرآن، الوقف و الابتداء. سال وفات وی بدرستی معلوم نیست . (از ریحانة الارب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(181778, 'عدوی', '<span class=\"hlight\">عدوی .</span> <font color=\"DarkGreen\"><b>[ ع َ وی ی ]</font></b> (ص نسبی ) نسبت است به عدی بن ربیعه . رجوع به عدی بن ربیعةبن معاویه شود. (از لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٦</span>). <BR><font color=\"Blue\">◄</font> نسبت است به عدی بن کعب بن لؤی . رجوع به عدی بن کعب شود. (از لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٦</span>).<br /></font></div>'),
(181779, 'عدوی', '<span class=\"hlight\">عدوی .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ وی ی ]</font></b> (ع اِ) گیاه صیفی که بعد ازگذشتن بهار روید. (از قطرالمحیط). عدویة. (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> درختهای کوچک که شتر خورد. (قطرالمحیط). عدویة. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> گوسفندکوچک چهل روزه . (قطرالمحیط). عدویة. (منتهی الارب ).<br /></font></div>'),
(181780, 'عدوی', '<span class=\"hlight\">عدوی .</span> <font color=\"DarkGreen\"><b>[ ع دْ وا ]</font></b> (ع اِمص ) سرایت بیماری و تجاوز آن از صاحب خود به دیگری و منه الحدیث : لاعدوی و لاطیرة. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> یاری گری، اسم اسب اعداء را. (از منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> خواستن از حاکم که رفع ظلم کند. خواستن از حاکم که انتقام گیرد از ستمکار. (از اقرب الموارد).<br /></font></div>'),
(181781, 'عدوی', '<span class=\"hlight\">عدوی .</span> <font color=\"DarkGreen\"><b>[ ع ُدْ وا ]</font></b> (ع مص ) ستم کردن بر کسی و درگذشتن از حد. (منتهی الارب ) (از اقرب الموارد). عدوّ. عدوه . عَداء. عِدوان . عُداون . (منتهی الارب ).<br /></font></div>'),
(181782, 'عدوی', '<span class=\"hlight\">عدوی .</span> <font color=\"DarkGreen\"><b>[ ع ُدْ وا ]</font></b> (ع اِمص ) تباهی و فساد. (از اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181783, 'عدویة', '<span class=\"hlight\">عدویة.</span> <font color=\"DarkGreen\"><b>[ ع َ وی ْ ی َ ]</font></b> (اِخ ) دختر اسماعیل عدوی قیسی است . یکی از زنان بزرگ جهان اسلام است که در عرفان و تصوف سیری داشت بسیار متزهد و عابد بود. عطار در وصفش گوید آن مخدره ٔ خدر خاص، آن مستوره ٔ ستراخلاص، آن سوخته ٔ عشق و اشتیاق، آن شیفته ٔ قرب و احتراق، آن گم شده ٔ وصال و آن ... بنابر نقل تذکرة الاولیاء وی مدتی بقید رقیت درآمد. رجوع به رابعه ٔ عدویة و به تذکرة الاولیاء شود.<br /></font></div>'),
(181784, 'عدویة', '<span class=\"hlight\">عدویة.</span> <font color=\"DarkGreen\"><b>[ ع َ دَ وی ْ ی َ ]</font></b> (اِخ ) قومی از تمیم و از حنظله اند. (از منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181785, 'عدویة', '<span class=\"hlight\">عدویة.</span> <font color=\"DarkGreen\"><b>[ ع َ دَ وی ْ ی َ]</font></b> (اِخ ) دهی است دارای بستانهای نزدیک مصر به شاطی شرقی نیل . (معجم البلدان ) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181786, 'عدویة', '<span class=\"hlight\">عدویة.</span> <font color=\"DarkGreen\"><b>[ ع َ دَ وی ْ ی َ ]</font></b> (ع ص ) مؤنث عدوی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گیاه که پس از گذشت بهار درختان کوچک سبز کند و شتران خورند. عدوی . (قطرالمحیط). نبات الصیف بعد ذهاب الربیع بخضر صغارالشجر فترعاء الابل، یقال : أصابت الابل عدویة. (از اقرب الموارد) (منتهی الارب ). عدوی . (قطرالمحیط). <BR><font color=\"Blue\">◄</font> گوسفند کوچک چهل روزه . (از اقرب الموارد). عدوی . (قطرالمحیط) (منتهی الارب ).<br /></font></div>'),
(181787, 'عدک', '<span class=\"hlight\">عدک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) پشم زدن به مطرقه . (منتهی الارب ) (آنندراج ) (از قطرالمحیط) (از اقرب الموارد).<br /></font></div>'),
(181788, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن زیدبن مالک بن عدن بن الرقاع از عاملة. شاعری بزرگ و از مردم دمشق است . وی معاصر جریر است از مداحان بنی امیه و از خواص ولیدبن عبدالملک است وی در حدود سال <span class=\"hlight\" dir=\"rtl\">٩٥</span> هَ . ق . بدمشق در گذشت . (از اعلام زرکلی ).<br /></font></div>'),
(181789, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن ربیعةبن معاویة الاکرمین بن الحرث بن معاویةبن مرتعبن معاویةبن کندة بطنی از کنده است . (از لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٨</span>).<br /></font></div>'),
(181790, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن زیدبن حمادبن زید. از تمیم شاعر و از دهاة جاهلی است وی قروی و از مردم حیره بود مردی فصیح بود عربی و فارسی نیکو میدانست در تیراندازی ماهر بود بازی صرلجان که از بازیهای عجمان بود نیک می دانست، وی اولین کسی است در دیوان کسری به عربی نوشت . کسری وی را از خواص خود گردانید و او را مترجم خود قرار داد. پس از مرگ کسری در عهد پسرش بدان سمت باقی ماند و منزلتی رفیعیافت پسر انوشیروان او را با هدایائی نزد ملک روم فرستاد وی شهریاری شام را بدید و مدتی به دمشق بماند.سپس با هدایای قیصر به مدائن باز گشت و با دخت نعمان بن المنذر ازدواج کرد در اثر سعایت دشمنان به زندان نعمان پدر زن خود بیفتاد. و در همان زندان در حدود سال <span class=\"hlight\" dir=\"rtl\">٣٥</span> قبل از هجرت به قتل رسید. (از اعلام زرکلی ).<br /></font></div>'),
(181791, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ )ابن حارث بن مرة. از کهلان از قحطانیه جد جاهلی است فرزندان او عفیر و لخم و جذام اند. (از اعلام زرکلی ).<br /></font></div>'),
(181792, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن ربیعةبن الحارث مکنی به ابولیلی و مشهور به المهلهل از بنی تغلب است، شاعر، از شجعان عرب در جاهلیت بود. از مردم نجد و دائی امری ءالقیس شاعراست . وی را بدان جهت که نخستین بار مو را بافت مهلهل گویند. وی زیباترین و فصیح ترین مردم بود. او را اختبار و عجایب زیادی است . شعر او بسیاری عالی است وی در حدود سال <span class=\"hlight\" dir=\"rtl\">١٠٠</span> هَ . ق . درگذشت . (از اعلام زرکلی ).<br /></font></div>'),
(181793, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن حنیفةغنم از قحطانیه جد جاهلی است از فرزندان اوست سلیمةالمتنبی . (از اعلام زرکلی ) (لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٨</span>).<br /></font></div>'),
(181794, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع ِدْ دی ]</font></b> (ص نسبی )(طلاق ...) در مقابل طلاق غیر عدی . طلاق غیر عدی که زن عده نداشته باشد مانند طلاق قبل از دخول و طلاق زن یائسه . و طلاق عدی طلاقی است که عده داشته باشد و آن یا رجعی است که مرد در حال عده حق رجوع دارد یا بائن است که مرد این حق را ندارد مانند طلاق خلعی . رجوع به طلاق رجعی و نیز به عده و به شرایع صص <span class=\"hlight\" dir=\"rtl\">١٨٤</span> - <span class=\"hlight\" dir=\"rtl\">١٨٦</span> شود.<br /></font></div>'),
(181795, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن زید مناةبن ادبن طایخة از عدنان جد جاهلی است از اعقاب ذوالرمة شاعر است . (از اعلام زرکلی ) (لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٦</span>).<br /></font></div>'),
(181796, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن عدی بن عمیرةبن فروة. از بنی الارقم ازکنده . بزرگ اهل جزیره بود. وی ناسک فقیه بود، سلیمان بن عبدالملک وی را قضاء الجزیره و ارمنیة و آذربایجان بداد. عمربن عبدالعزیز نیز وی را بدان سمت بداشت . وی در سال <span class=\"hlight\" dir=\"rtl\">١٢١</span> هَ . ق . درگذشت . (از اعلام زرکلی ).<br /></font></div>'),
(181797, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن عمروبن ربیعة. از مزیقیا از قحطانیه جد جاهلی است . از نسل اوست بدیل بن ورقاء و جویریة دختر حارث . (از اعلام زرکلی ) (لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span>).<br /></font></div>'),
(181798, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن عمروبن مالک . از بنی نجار. از خزرج از قحطان جد جاهلی است از نسل اوست حسان بن ثابت الانصاری . (از اعلام زرکلی ) (لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٦</span>).<br /></font></div>'),
(181799, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن عَمیرة، مکنی به ابو زراة صحابی است . ساکن کوفه شد و بعد به حران رفت و سپس به سال <span class=\"hlight\" dir=\"rtl\">٤٠</span> هَ . ق . به کوفه درگذشت از او در صحیحین ده حدیث روایت شده است . (از اعلام زرکلی ).<br /></font></div>'),
(181800, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن کعب بن مرة. از لؤی بن غالب از عدنان جد جاهلی است و از اعقاب او است عمروبن الخطاب . (از اعلام زرکلی ) (لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٦</span>).<br /></font></div>'),
(181801, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن مسافربن اسماعیل الهکتاری . از شیوخ متصوفه است طائفه عدویه بدو منسوب اند، وی مردی صالح و ناسک بود به سال <span class=\"hlight\" dir=\"rtl\">٤٦٧</span> هَ . ق . در بیت قار از نواحی بعلبک به دنیا آمد و برای خود زاویه ای در کوه الهکتاریه از نواحی موصل بساخت و در آنجا عزلت گزید. و به سال <span class=\"hlight\" dir=\"rtl\">٥٥٧</span> در همانجا بمرد. (از اعلام زرکلی ).<br /></font></div>'),
(181802, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن حاتم بن عبداﷲبن سعدبن الحشرج الطائی . صحابی و از اجواد عقلاء بود، وی در عصر جاهلی رئیس قوم خود بود. و در جنگ ردة کارهای بزرگ کرد بطوری که ابن اثیر در مورد او گوید. خیر مولود فی أرض طی و أعظمه برکة علیهم، وی به سال <span class=\"hlight\" dir=\"rtl\">٩</span> هَ . ق . به دین اسلام گروید و فتح عراق را درک کرد سپس ساکن کوفه شد و در جنگ جمل و صفین و نهروان با حضرت علی شرکت کرد از او در صحیحین <span class=\"hlight\" dir=\"rtl\">٦٦</span> حدیث نقل شده است وی به سال <span class=\"hlight\" dir=\"rtl\">٦٨</span> هَ . ق . درگذشت . (از اعلام زرکلی ).<br /></font></div>'),
(181803, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع ُ دا <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ دا ]</font></b> (ع ص، اِ) دشمنان . اسم جمع است . یقال هؤلاء قوم عدی ؛أی اعداء. (منتهی الارب ) (از اقرب الموارد) و یقال العِدی الاعداء الذین لانقاتلهم . (از اقرب الموارد).<br /></font></div>'),
(181804, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع ِ دا ]</font></b> (ع اِ) کرانه ٔ وادی . <BR><font color=\"Blue\">◄</font> چوب که میان دو چوب باشد. <BR><font color=\"Blue\">◄</font> سنگ تنک که بدان چیزی را پوشند. <BR><font color=\"Blue\">◄</font> دور شوندگان . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> غرباء. (اقرب الموارد). مسافران . (منتهی الارب ).<br /></font></div>'),
(181805, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (ع اِ) گروه مردم که مهیای قتال باشند. <BR><font color=\"Blue\">◄</font> پیشروان جنگ . و قیل أول من یحمل من الرحالة. (قطرالمحیط) (از اقرب الموارد) (منتهی الارب ). ج، عاد.<br /></font></div>'),
(181806, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (ص نسبی ) نسبت است به عدی بن افلت . رجوع به عدی بن افلت شود. <BR><font color=\"Blue\">◄</font> نسبت است به عدی بن جندب . رجوع به عدی بن جندب شود. <BR><font color=\"Blue\">◄</font> نسبت به عدی بن اسامةبن مالک بن بکربن حبیب است . رجوع به عدی بن اسامة شود. (از لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span>).<br /></font></div>'),
(181807, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) قبیله ای است و عدوی یا عِدی منسوب بدان است . (از اقرب الموارد) (از قطرالمحیط) (منتهی الارب ).<br /></font></div>'),
(181808, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ )جدی جاهلی است . فرزندان او بطنی از نجارند از آنهاست انس بن مالک و جماعتی از صحابه . (از اعلام زرکلی ).<br /></font></div>'),
(181809, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) جدی است جاهلی . فرزندان او بطنی از بنی مزیقیااند. (از اعلام زرکلی ).<br /></font></div>'),
(181810, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) جدی است جاهلی . فرزندان او بطنی از فزارةاند. از جمله بنو بدر است که مسکن آنها به نواحی قلپوبیة به دیار مصر بود. (از اعلام زرکلی ).<br /></font></div>'),
(181811, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) جدی است جاهلی . فرزندان او بطنی از قضاعه اند. (از اعلام زرکلی ).<br /></font></div>'),
(181812, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) جدی است جاهلی . فرزندان او بطنی از لخم از قحطانیه اند. (از اعلام زرکلی ).<br /></font></div>'),
(181813, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن اخزم بن ربیعةبن جرول بن ثعل بن عمروبن الغوث بن طیی ٔ. بطنی از طی است از جمله حاتم بن عبداﷲبن الحشرج بن امری القیس بن عدی است . (از لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span>).<br /></font></div>'),
(181814, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن ارطاة الفزاری امیر و از مردم دمشق است . وی از عقلاء شجعان عرب بود. عمربن عبدالعزیز به سال <span class=\"hlight\" dir=\"rtl\">٩٩</span> هَ . ق . وی را ولایت بصره داد و تا به سال <span class=\"hlight\" dir=\"rtl\">١٠٢</span> که به دست معاویةبن یزیدبن مهلب به قتل رسید بدان سمت بماند. (از اعلام زرکلی ).<br /></font></div>'),
(181815, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن اسامةبن مالک بن حبیب بن عمروبن غنم بن تغلب . بطنی از تغلب است که جمعی بسیار بدو نسبت داده شده اند از جمله امراء بنوحمدان بن حمدون . (از لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span>).<br /></font></div>'),
(181816, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن اقلت بن سلسلة بن عمروبن سلسلةبن غنم بن ثوب بن معنی بن عتودبن عنین بن سلامان . بطنی از طی است که از جمله ٔ آنها عنترةبن الاخرس است . (از لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٨</span>).<br /></font></div>'),
(181817, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن ثابت الانصاری . از علماء امامیه و از صلحاء شیعه ٔ عصر خود بود به سال <span class=\"hlight\" dir=\"rtl\">١١٦</span> هَ . ق . به کوفه درگذشت مولد او نیز به کوفه بود. (از اعلام زرکلی ).<br /></font></div>'),
(181818, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َدی ی ]</font></b> (اِخ ) ابن جناب بن هبل از کنانة عذرة. از قحطان جدی است جاهلی . و از عقبه ٔ اوست لیلی ام عبدالعزیزبن مروان . (از اعلام زرکلی ) (لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٨</span>).<br /></font></div>'),
(181819, 'عدی', '<span class=\"hlight\">عدی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی ]</font></b> (اِخ ) ابن جندب بن العنبربن عمروبن تمیم، بطنی بزرگ از تمیم است . از آنهاست غاضرةبن سمرةبن عمرو. (از لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٨</span>).<br /></font></div>'),
(181820, 'عدیة', '<span class=\"hlight\">عدیة.</span> <font color=\"DarkGreen\"><b>[ ع ُ دَی ْ ی َ ]</font></b> (اِخ ) کنار وادی ؛ هضبةای است که بنوضبیة و بنوعامربن ذهل در آنجا هم قسم شدند. (از معجم البلدان ) (منتهی الارب ).<br /></font></div>'),
(181821, 'عدید', '<span class=\"hlight\">عدید.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) آبی است مر عمیره راکه بطنی از کلب اند. (معجم البلدان ) (منتهی الارب ).<br /></font></div>'),
(181822, 'عدید', '<span class=\"hlight\">عدید.</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (ع اِ) شمار. اسم است از عد. (قطرالمحیط) (اقرب الموارد) (از منتهی الارب ). و منه : هم عدیدالحصی و بنوفلان فی العدید الاکثر. <BR><font color=\"Blue\">◄</font> همتا. ندّ. (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> حریف . (از منتهی الارب ). الِقرن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> همدست در شجاعت . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آنکه از قومی باشد؛ فلان عدیدالقوم، او از ایشان است . <BR><font color=\"Blue\">◄</font> حصة. (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بانگ کمان . (اقرب الموارد) (منتهی الارب ) (قطرالمحیط). <BR><font color=\"Blue\">◄</font> عدید الشی ٔ مثلهم فی العدد، یقال دنانیر فلان عدید دنانیرک . (منتهی الارب ).<br /></font></div>'),
(181823, 'عدیسی', '<span class=\"hlight\">عدیسی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابوالحسین احمدبن عمربن القاسم بن بشربن عصام بن احمدبن النرسی العدیسی معروف به ابن عدیسة از ابی بکر الشافعی و ابی عمروبن السماک و جز آنان روایت کند. وی ثقه بود و به سال <span class=\"hlight\" dir=\"rtl\">٤١٢</span> هَ . ق . درگذشت . (از لباب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span>).<br /></font></div>'),
(181824, 'عدیسی', '<span class=\"hlight\">عدیسی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) نسبت است به عدیسة که لقب جد ابی الحسین ... است . رجوع به عدیس ابوالحسین شود.<br /></font></div>'),
(181825, 'عدیل', '<span class=\"hlight\">عدیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) مثل . مانند. همتا. همانند. (اقرب الموارد) (قطرالمحیط). ج، عُدَلا. <BR><font color=\"Blue\">◄</font> هم کجاوه . (از اقرب الموارد). دو کس که هر دو جانب یک کجاوه نشینند هر یکی مر دیگری را عدیل باشد. (آنندراج ) (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> برابر در قدر و مرتبت . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> هم شأن . هم رتبه . رقیب <span class=\"hlight\">:</span> <br />خرد و جهل کی شوند عدیل <br />برز را نیست آشنا ردّاس .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بارت ز خرد باید و طاعت به سوی آنک <br />او را نه عدیل است و نه فرزند و نه یار است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />تا دهک راه سخت شوریده ست <br />جفت عقل تو و عدیل هنر.<br /> <font color=\"Red\">مسعودسعد.</font><br /> <BR><font color=\"Blue\">◄</font> هم وزن . عدیلک هو الذی یعادلک فی الوزن والقدر. (قطرالمحیط). هم سنگ . ج، عُدلاء. <BR><font color=\"Blue\">◄</font> همسر. (منتهی الارب ) <span class=\"hlight\">:</span> <br />نیم روز اندر بهشت آدم عدیل ملک بود<br />هفتصد سال از جگر خون راند، بر سنگ و گیا.<br /> <font color=\"Red\">سنایی .</font><br /><BR><font color=\"Blue\">◄</font> شوهران دو خواهر.<br /></font></div>'),
(181826, 'عدیل', '<span class=\"hlight\">عدیل .</span><font color=\"DarkGreen\"><b>[ ع ُ دَ ]</font></b> (اِخ ) ابن فرج . شاعر است . (منتهی الارب ).<br /></font></div>'),
(181827, 'عدیلة', '<span class=\"hlight\">عدیلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع اِ) همزاد. دیوی که با انسان زائیده میشود و با او هست . <BR><font color=\"Blue\">◄</font> دعائی است در کتب ادعیه . آن را بر سر مریض هنگام مرگ خوانند که پریان و دیوان و شیاطین از وی دور شوند.<br /></font></div>'),
(181828, 'عدیلتان', '<span class=\"hlight\">عدیلتان .</span> <font color=\"DarkGreen\"><b>[ ع َل َ ]</font></b> (ع اِ) تثنیه ٔ عدیلة. دو تیر یا کمان که هر یک معادل دیگر باشد. (قطرالمحیط) (از اقرب الموارد).<br /></font></div>'),
(181829, 'عدیم', '<span class=\"hlight\">عدیم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) گول . <BR><font color=\"Blue\">◄</font> دیوانه . <BR><font color=\"Blue\">◄</font> نیازمند. درویش . (منتهی الارب ). ج، عُدماء. <BR><font color=\"Blue\">◄</font> معدوم . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> گاه بمنزله ٔ کلمه ٔ نفی است که بر سر اسم معرف به الف و لام درآید و آن را منفی سازد و در حقیقت نوعی صفت مرکب درست کند چون عدیم الخیر، بی خیر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدیم الحرکة</span> ؛ بی حرکت .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدیم الرائحة</span> ؛ بی بو.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدیم الرأس </span> ؛ بی سر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدیم الطعم </span> ؛ بی مزه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدیم الفضل </span> ؛ بی خرد.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدیم المثال </span> ؛ بی مثال . بی مانند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدیم المثل </span> ؛ بی مثل . بی مانند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدیم النظیر</span> ؛بی نظیر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عدیم الوفاء</span> ؛ بی وفا.<br /></font></div>'),
(181830, 'عدیم المثل', '<span class=\"hlight\">عدیم المثل .</span> <font color=\"DarkGreen\"><b>[ ع َ مُل ْ م ِ ]</font></b> (ع ص مرکب ) بی نظیر. بی مانند. عدیم المثال . عدیم النظیر <span class=\"hlight\">:</span> <br />به باب ظلم شدم در جهان عدیم المثل <br />شدم عدیم من و ظلم من نگشت عدیم .<br /> <font color=\"Red\">سوزنی .</font><br />حکیم بود ز اقران خود عدیم المثل <br />چو مثل خویش ز اقران خویش گشت عدیم .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(181831, 'عدیم النظیر', '<span class=\"hlight\">عدیم النظیر.</span> <font color=\"DarkGreen\"><b>[ ع َ مُن ْ ن َ ]</font></b> (ع ص مرکب ) بی نظیر. بی همتا <span class=\"hlight\">:</span> در عهد خویش عدیم النظیر بود. (ترجمه ٔیمینی ص <span class=\"hlight\" dir=\"rtl\">٢٣٨</span>). در فنون آداب و... در سخندانی و سخن آرایی عدیم النظیر و وحیدالدهر است . (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(181832, 'عدینة', '<span class=\"hlight\">عدینة.</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ ]</font></b> (ع اِ) کهنه ای است که در اسفل دلو نهند. (از اقرب الموارد) (از قطرالمحیط). ج، عدائن . چرم پاره، بن دلو. (منتهی الارب ) رقعه ای که در دول نهند. (مهذب الاسماء).<br /></font></div>'),
(181833, 'عذاب', '<span class=\"hlight\">عذاب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) آنچه دشوار باشد بر انسان و او را از قصدش باز دارد. (از اقرب الموارد). ج، اَعذبة. <BR><font color=\"Blue\">◄</font> نکال . (قطرالمحیط). <BR><font color=\"Blue\">◄</font> هر چه به نفس رسد از الم . (منتهی الارب ) (آنندراج ). شکنجه . (از قطرالمحیط) (از اقرب الموارد) (آنندراج ). کل عذاب فی القرآن فهو التعذیب ؛ ألا و لیشهد عذابها طائفة. فان المراد الضرب . (اقرب الموارد). سیاست و عقوبت . (ناظم الاطباء). تنبیه و زدن تازیانه .(ناظم الاطباء). <BR><font color=\"Blue\">◄</font> جفا و بلا <span class=\"hlight\">:</span> <br />خود نبینی مگر عذاب وعنا<br />چون نمایی مرا عنا و عذاب .<br /> <font color=\"Red\">ناصرخسرو (دیوان، چ تقوی ص <span class=\"hlight\" dir=\"rtl\">٣٥</span>).</font><br />و بباید دانست که اطراف عالم پر بلا و عذاب است . (کلیله و دمنه ). و اگر کسی را گویند صد سال دایم در عذاب روزگار باید گذاشت . (کلیله و دمنه ). یا دینداری بودکه از عذاب بترسد یا کریمی که از عار اندیشد. (کلیله و دمنه ).<br />اینکه می بینم به بیداری است یا رب یا بخواب <br />خویشتن را در چنین نعمت پس از چندین عذاب .<br /> <font color=\"Red\">انوری .</font><br />ای مالک سعیر برین راندگان خلد<br />زحمت مکن که زحمت من بس عذابشان .<br /> <font color=\"Red\">خاقانی .</font><br />هر که جز آن خشت نقابش نبود<br />گرچه گنه داشت عذابش نبود.<br /> <font color=\"Red\">نظامی .</font><br />گر هزاران سال باشی در عذاب <br />میتوان گفتن که بس آسان بود.<br /> <font color=\"Red\">عطار.</font><br />اگر تو برفکنی در میان شهر نقاب <br />هزار مؤمن مخلص درافکنی به عذاب .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">به عذاب آوردن </span> ؛ به تنگ آوردن . به ستوه آوردن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عذاب ابد</span> ؛ عذاب همیشگی و دائمی <span class=\"hlight\">:</span> <br />از خطر آتش و عذاب ابد<br />دین و خرد کرد، در حصار مرا.<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عذاب النار</span> ؛ عذاب نار. آتش جهنم . شکنجه ٔ جهنم <span class=\"hlight\">:</span> <br />زینهار از قرین بد زنهار<br />و قنا ربناعذاب النار.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عذاب الیم </span> ؛ رنج وشکنجه ٔ سخت <span class=\"hlight\">:</span> <br />خسته از محنت و بلای حجاز.<br />رسته از دوزخ و عذاب الیم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />مگر کرده بودم گناهی عظیم <br />که بردم در آن شب عذابی الیم .<br /> <font color=\"Red\">سعدی (بوستان ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عذاب بردن </span> ؛ رنج بردن . سختی کشیدن <span class=\"hlight\">:</span> <br />تا کی بری عذاب و کنی ریش را خضاب <br />تا کی فضول گویی و آری حدیث غاب .<br /> <font color=\"Red\">رودکی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عذاب دادن </span> ؛ اذیت کردن . شکنجه دادن <span class=\"hlight\">:</span> <br />بار در افکن که عذابت دهد<br />نان ندهد تا که به آبت دهد.<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عذاب سقر</span> ؛ عذاب جهنم . عذاب آخرت <span class=\"hlight\">:</span> <br />زین پس تو و ترحم روحانیان خلد<br />خاقانیا عذاب سقر کزتو باز ماند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عذاب کده </span> ؛ محل شکنجه ؛ محل اجرای حدود و تعزیرات <span class=\"hlight\">:</span> <br />مثل است این که در عذاب کده <br />حدزده به بود که بیم زده .<br /> <font color=\"Red\">سنائی .</font><BR>۩ کنایه از دنیاست که حضرت امیر فرمودند <span class=\"hlight\">:</span> <br />الدنیا بالبلاء محفوفة.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عذاب کردن </span> ؛ شکنجه دادن <span class=\"hlight\">:</span> <br />چون کند سی ساله عاصی را عذاب جاودان <br />این چنین حکم و قضای ایزد دادار نیست .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گر جمله را عذاب کنی، ور عطا دهی <br />کس را مجال این نه که این چون و آن چرا.<br /> <font color=\"Red\">سعدی .</font><br />نه چنان گناهکارم که به دشمنم سپاری <br />تو به دست خویشتن کن اگرم کنی عذابی .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عذاب کشیدن </span> ؛ شکنجه کشیدن . دشواری کشیدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عذاب نمودن </span> ؛ شکنجه دادن <span class=\"hlight\">:</span> <br />خودنبینی مگر عذاب و عنا<br />چون نمایی مرا عنا و عذاب .<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(181834, 'عذاب', '<span class=\"hlight\">عذاب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص، اِ) ج ِ عذاب .خوش گواردی و گوارا. (از ناظم الاطباء) <span class=\"hlight\">:</span> <br />پاک از آغاز و آخر آن عذاب <br />مانده محرومان ز مهرش در عذاب .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(181835, 'عذاب', '<span class=\"hlight\">عذاب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان ولدیان بخش حومه ٔ شهرستان خوی، واقع در نه هزاروپانصدگزی جنوب خاوری خوی و سه هزارگزی خاور شوسه ٔ خوی به سلماس جلگه . سکنه <span class=\"hlight\" dir=\"rtl\">٢٢٤</span> تن . آب آن از رود قطور و محصولات آن غلات و حبوب و شغل اهالی زراعت و صنایع دستی آنها جوراب بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(181836, 'عذاب الفنج', '<span class=\"hlight\">عذاب الفنج .</span> <font color=\"DarkGreen\"><b>[ ع َ اَ ف َ ]</font></b> (نف مرکب ) که عذاب اندوخته کند و بیلفنجد. و معنی ترکیبی ذخیره کننده واندوزنده ٔ عذاب و کنایه از دل آزار است <span class=\"hlight\">:</span> <br />توانگری به دل است ای گدای با صد گنج <br />چو راحتی نرسانی مشو عذاب الفنج .<br /><font color=\"Red\">میرخسرو (از آنندراج ).</font><br /></font></div>'),
(181837, 'عذاب الهون', '<span class=\"hlight\">عذاب الهون .</span> <font color=\"DarkGreen\"><b>[ ع َ بُل ْ هََ ]</font></b> (ع اِ مرکب ) عذاب خواری . (غیاث اللغات ) (آنندراج ).<br /></font></div>'),
(181838, 'عذاب هدهد', '<span class=\"hlight\">عذاب هدهد.</span> <font color=\"DarkGreen\"><b>[ ع َ ب ِ هَُ هَُ ]</font></b> (اِخ ) در تحفة العراقین این ترکیب واقع شده است چه ظاهراً وقتی حضرت سلیمان بر هدهد قهر کرده باشند. (از آنندراج ).<br /></font></div>'),
(181839, 'عذابة', '<span class=\"hlight\">عذابة.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِ) این کلمه وزناً و معناً مانند عدابة است . (از اقرب الموارد). رجوع به عدابة شود.<br /></font></div>'),
(181840, 'عذار', '<span class=\"hlight\">عذار.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) افسار ستور. (منتهی الارب ) (آنندراج ). آنچه از فسار بر گونه های اسب فرو افتد. ج، عُذُر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نشان فسار بر روی ستور. (آنندراج ) (از منتهی الارب ). داغی است در جای فسار. (از قطرالمحیط) (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خط ریش . (منتهی الارب ) (از غیاث اللغات ). جانب ریش یعنی مویی که محاذی گوش است و بین آن و گوش سفید است .یا قسمتی از صورت که بر آن موی درازی می روید که محاذی نرمه ٔ گوش تا بن ریش است . (از اقرب الموارد) (قطرالمحیط). این معنی مأخوذ از عربی است <span class=\"hlight\">:</span> <br />روی بستان را چون چهره ٔ دلبندان <br />از شکوفه رخ و از سبزه عذار آید.<br /> <font color=\"Red\">ناصرخسرو.</font><br />کافور سپید گشت ناگه <br />این عنبر تر، بر این عذارم .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> رخسار. (منتهی الارب ) (آنندراج ) <span class=\"hlight\">:</span> و سبزه ٔ گلستان عذارش تازه دمیده . (گلستان ).<br />عذر او بر عذار من پیداست <br />بعد از این هم چه عذر باید خواست .<br /><font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">گلعذار</span> ؛ کسی که رخسارش مانند گل است . رجوع به گل شود.<br />معنی اخیر نیز مأخوذ از عربی است . <BR><font color=\"Blue\">◄</font> طعام بناء. <BR><font color=\"Blue\">◄</font> طعام ختنه . <BR><font color=\"Blue\">◄</font> طعامی که در پی هر امر جدیدی بطرز شادمانی ترتیب دهند و دوستان را بر آن خوانند. (از قطرالمحیط) (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> درشتی وغلظت زمین در فضای فراخ . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دوکرانه ٔ پیکان . (از اقرب الموارد) (منتهی الارب ) (قطرالمحیط). <BR><font color=\"Blue\">◄</font> آنچه بدان مهار را خم کنندبه سوی سر شتر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> داغ که بر پس گردن اشتر نهند. (مهذب الاسماء). شرم . (اقرب الموارد) (از قطرالمحیط). <BR><font color=\"Blue\">◄</font> دهنه . من اللجام دواله . (مهذب الاسماء). أی جانباه و هو ما سال علی خد الفرس . (قطرالمحیط) <span class=\"hlight\">:</span> <br />همان جامه و گوهر شاهوار<br />همان اسب تازه به زرین عذار.<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">خلیغ عذار</span> ؛ افسارگسسته . (منتهی الارب ).<br /></font></div>'),
(181841, 'عذاری', '<span class=\"hlight\">عذاری .</span> <font color=\"DarkGreen\"><b>[ ع َ ری <span class=\"hlight\" dir=\"rtl\">/</span> ع َ را ]</font></b> (ع ص، اِ) ج ِ عَذْراء. (منتهی الارب ) (آنندراج ). دوشیزگان . عذارا. (در تداول فارسی ) <span class=\"hlight\">:</span> <br />آن تلخ وش که صوفی ام الخبائثش خواند<br />أحلی لنا و أشهی من قبلة العذارا.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(181842, 'عذاری', '<span class=\"hlight\">عذاری .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) ج ِ عَذراء. رجوع به عذراء شود.<br /></font></div>'),
(181843, 'عذارین', '<span class=\"hlight\">عذارین .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ]</font></b> (ع اِ) تثنیه ٔ عذار. مذکور است در شعر ذوالرمة، دو کوه دراز از ریگ و یا دو دره . (از ناظم الاطباء).<br /></font></div>'),
(181844, 'عذاف', '<span class=\"hlight\">عذاف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) زهر قاتل . (منتهی الارب ) (قطرالمحیط) (از اقرب الموارد).<br /></font></div>'),
(181845, 'عذافر', '<span class=\"hlight\">عذافر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ف ِ ]</font></b> (ع ص ) بزرگ از شتر و ناقه . شتر بزرگ شگرف استوارجثه . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) شیر بیشه . (منتهی الارب ). اسد. ج، عذافرة. (از اقرب الموارد).<br /></font></div>'),
(181846, 'عذاق', '<span class=\"hlight\">عذاق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ عَذق . (قطرالمحیط) (اقرب الموارد). رجوع به عذق شود.<br /></font></div>'),
(181847, 'عذال', '<span class=\"hlight\">عذال .</span> <font color=\"DarkGreen\"><b>[ ع ُذْ ذا ]</font></b> (ع ص، اِ) ج ِ عاذل . رجوع به عاذل شود.<br /></font></div>'),
(181848, 'عذال', '<span class=\"hlight\">عذال .</span> <font color=\"DarkGreen\"><b>[ ع َذْ ذا ]</font></b> (ع ص ) بسیار نکوهش کننده . (قطرالمحیط) (از اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181849, 'عذالة', '<span class=\"hlight\">عذالة.</span> <font color=\"DarkGreen\"><b>[ ع َذْ ذا ل َ ]</font></b> (ع اِ) اِست . (اقرب الموارد). سرین . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص ) بسیار نکوهش کننده . (از اقرب الموارد).<br /></font></div>'),
(181850, 'عذام', '<span class=\"hlight\">عذام .</span> <font color=\"DarkGreen\"><b>[ ع ُذْ ذا ]</font></b> (ع اِ) نوعی از درختان شوره گیاه . (از اقرب الموارد) (منتهی الارب ). عذامة یکی آن .<br /></font></div>'),
(181851, 'عذام', '<span class=\"hlight\">عذام .</span> <font color=\"DarkGreen\"><b>[ ع َذْ ذا ]</font></b> (ع ص ) صیغه ٔ مبالغه از عذم .(اقرب الموارد). رجوع به عذم شود. <BR><font color=\"Blue\">◄</font> (اِ) کیک . ج، عُذُم . (از اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181852, 'عذامة', '<span class=\"hlight\">عذامة.</span><font color=\"DarkGreen\"><b>[ ع ُذْ ذا م َ ]</font></b> (ع اِ) واحد عذام . (ناظم الاطباء).<br /></font></div>'),
(181853, 'عذانة', '<span class=\"hlight\">عذانة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ن َ ]</font></b> (ع اِ) کون . (منتهی الارب ) (آنندراج ). است . (اقرب الموارد).<br /></font></div>'),
(181854, 'عذاویط', '<span class=\"hlight\">عذاویط.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) ج ِ عذیوط. (ناظم الاطباء). رجوع به عذیوط شود.<br /></font></div>'),
(181855, 'عذب', '<span class=\"hlight\">عذب .</span> <font color=\"DarkGreen\"><b>[ ع َ ذَ ]</font></b> (ع اِ) خاشاک . <BR><font color=\"Blue\">◄</font> آنچه از بچه دان برآید بعد ازولادت . <BR><font color=\"Blue\">◄</font> خرقه ٔ زن نوحه سرا که در وقت نوحه بر میان بندد. <BR><font color=\"Blue\">◄</font> کرانه ٔ هر چیزی . <BR><font color=\"Blue\">◄</font> سر قضیب شتر. (از قطرالمحیط) (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> چرم پاره که سپس پالان آویزند. (از قطرالمحیط) (منتهی الارب ). مفرد آن عذبة است . <BR><font color=\"Blue\">◄</font> نام درختی است . (منتهی الارب ).<br /></font></div>'),
(181856, 'عذب', '<span class=\"hlight\">عذب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) ناخوردن از شدت عطش . (از اقرب الموارد) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> بازداشتن کسی را. (از اقرب الموارد). باز ایستادن و گذاشتن . (از منتهی الارب ). امتناع از چیزی یا کسی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بند گذاشتن برای تازیانه . (از اقرب الموارد).<br /></font></div>'),
(181857, 'عذب', '<span class=\"hlight\">عذب .</span> <font color=\"DarkGreen\"><b>[ ع َ ذَ ]</font></b> (ع اِ) ج ِ عذبة. (ناظم الاطباء). رجوع به عذبة شود.<br /></font></div>'),
(181858, 'عذب', '<span class=\"hlight\">عذب .</span> <font color=\"DarkGreen\"><b>[ ع َ ذِ ]</font></b> (ع ص )آب چغزلاوه برآورده . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شراب و طعام گوارا. (ناظم الاطباء).<br /></font></div>'),
(181859, 'عذب', '<span class=\"hlight\">عذب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) خوش گوار. (اقرب الموارد) (قطرالمحیط) (منتهی الارب ) (غیاث اللغات ). پاکیزه از آب و خورش . (منتهی الارب ). آب و طعام گوارا. (از محیط المحیط) (از اقرب الموارد). آب خوش . (مهذب الاسماء). خوردنی و نوشیدنی خوشگوار. (غیاث اللغات ). گوارا. (قطرالمحیط) (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خوش . (ترجمان القرآن جرجانی ) <span class=\"hlight\">:</span> <br />آب عذب دین همی جوشد ازو<br />طالبان را آن حیات است و نمو.<br /> <font color=\"Red\">مولوی .</font><br />اندرآیید ای مسلمانان همه <br />غیرعذب دین عذاب است آن همه .<br /> <font color=\"Red\">مولوی .</font><br />او ز بحر عذب آب شور خورد<br />تا که آب شور او را کور کرد.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> (اِ) نوعی از درخت باشد. (منتهی الارب ) (از قطرالمحیط)(اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) نزد فصحاء کلامی است که الفاظ آن از کلمات وحشی عاری باشد. (از کشاف ).سخنی که لفظ آن سلس و غیر کریه بر ذوق باشد مقابل غیر مأنوس و وحشی . (از اقرب الموارد).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عذب البیان </span> ؛ روان و خوش بیان <span class=\"hlight\">:</span> به انشاء و انشاد اشعاری چند عذب البیان و رطب اللسان گشتند. (ترجمه ٔ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٥٥</span>).<br /></font></div>'),
(181860, 'عذبات', '<span class=\"hlight\">عذبات .</span> <font color=\"DarkGreen\"><b>[ ع َ ذَ ]</font></b> (ع اِ) ج ِ عذبة بمعنی چابق تازیانه <span class=\"hlight\">:</span> در زیر عذبات عذاب و زخم چوب و شکنجه سپری شد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٤١</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">یوم العذبات </span> ؛ از روزهای عربان است . (منتهی الارب ) (اقرب الموارد). و رجوع به عذبةشود.<br /></font></div>'),
(181861, 'عذبات', '<span class=\"hlight\">عذبات .</span> <font color=\"DarkGreen\"><b>[ ع َ ذَ ]</font></b> (اِخ ) نام اسب یزیدبن سبیع. (منتهی الارب ).<br /></font></div>'),
(181862, 'عذبة', '<span class=\"hlight\">عذبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِ) چغزلاوه . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درختی است که شتران را کشد. (از اقرب الموارد) (قطرالمحیط). <BR><font color=\"Blue\">◄</font> دارویی است که سرفه را بر طرف کند. (منتهی الارب ) (قطرالمحیط) (از اقرب الموارد).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">ذات العذبة</span> ؛ موضعی است .(منتهی الارب ).<br /></font></div>'),
(181863, 'عذبة', '<span class=\"hlight\">عذبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ذِ ب َ ]</font></b> (ع اِ) عَذَبة. چغزلاوه . <BR><font color=\"Blue\">◄</font> آنچه از طعام دور ریخته شود. آنچه از گندم برآید و دور کرده شود. (منتهی الارب ) (از قطرالمحیط) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خاشاک . (قطرالمحیط) (اقرب الموارد). خس و خاشاک . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خاک ها که اطراف یک قطعه زمین مزروع را احاطه کند. (از قطرالمحیط). <BR><font color=\"Blue\">◄</font> چابق تازیانه . (از منتهی الارب ).<br /></font></div>'),
(181864, 'عذبة', '<span class=\"hlight\">عذبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (اِخ ) موضعی است که از بصره تا بدانجا دو شب راه است و در آن موضع آبهای خوش است و گویند چون آنجا را بکندند آثار زندگی انسان یافتند. (از معجم البلدان ).<br /></font></div>'),
(181865, 'عذبة', '<span class=\"hlight\">عذبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ذَ ب َ ]</font></b> (ع اِ) چغزلاوه .(منتهی الارب ) (از اقرب الموارد). ج، عذبات . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شمله ٔ دستار. <BR><font color=\"Blue\">◄</font> سر شراک . سربند کفش از دوال . <BR><font color=\"Blue\">◄</font> چابق تازیانه . (منتهی الارب ) (آنندراج ). رشته ٔ تازیانه . (برهان قاطع). گره تازیانه . (مهذب الاسماء) <span class=\"hlight\">:</span> همه را به اسماء و سیما بشناخت در زیر عذبه ٔ تعذیب جمعی را به دست باز داد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٩٩</span>). <BR><font color=\"Blue\">◄</font> سرزبان . (مهذب الاسماء). تیزی زبان . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> سرشاخ درخت . (مهذب الاسماء). شاخ درخت . (منتهی الارب ). ج، عَذَب . <BR><font color=\"Blue\">◄</font> سرنیزه . <BR><font color=\"Blue\">◄</font> رشته ٔ ترازو. (از مهذب الاسماء). رشته ای که میان دسته ٔ ترازو یعنی شاهین ترازو بندند. (برهان قاطع). <BR><font color=\"Blue\">◄</font> دوال که بر گردن سگ افکنند. <BR><font color=\"Blue\">◄</font> طیلسان . (مهذب الاسماء).<br /></font></div>'),
(181866, 'عذبی', '<span class=\"hlight\">عذبی .</span> <font color=\"DarkGreen\"><b>[ ع َ ذَ بی ی ]</font></b> (ع ص ) مرد کریم الخلق . (قطرالمحیط) (اقرب الموارد) (از اقرب الموارد) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> کسی که بی عیب باشد. (از قطرالمحیط) (از اقرب الموارد).<br /></font></div>'),
(181867, 'عذج', '<span class=\"hlight\">عذج .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) نوشیدن آب . (از قطرالمحیط) (از اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181868, 'عذر', '<span class=\"hlight\">عذر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) بهانه . (از منتهی الارب ) (آنندراج ) <span class=\"hlight\">:</span> هیچ عذر نماند و خوارزم به دست ما آمد ناچار ما را این خون بباید خواست تا کشنده ٔ داماد را بکشیم به خون وملک و میراث بگیریم . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٦٩٠</span>).<br />پس آن به که بگریزی از عذر او<br />کزو خیر هرگز نخواهدت خواست .<br /> <font color=\"Red\">ناصرخسرو.</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عذر زنانه </span> ؛ حیض و نفساء و استحاضه . (غیاث اللغات ). و رجوع به عذر داشتن و عذر دیدن شود.<br /> <BR><font color=\"Blue\">◄</font> پوزش رفع کردن گناه و سرزنش . (از قطرالمحیط) (از اقرب الموارد) <span class=\"hlight\">:</span> واسطه شود تا خداوند سلطان عذر من بپذیرد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٥٥</span>).<br />عذر من بین در آخر قرآن <br />لفظ الناس را مکن انکار.<br /> <font color=\"Red\">خاقانی .</font><br />عذر احمق بدتر از جرمش بود<br />عذر نادان زهر هر دانش بود.<br /> <font color=\"Red\">مولوی .</font><br />گر صورتی چنین به قیامت درآورند<br />عاشق هزار عذر بگوید گناه را.<br /> <font color=\"Red\">سعدی .</font><br />آن غضب ناپسند باشد و زشت <br />که چو کردی مجال عذر نهشت .<br /> <font color=\"Red\">اوحدی .</font><br />پیر مغان ز توبه ٔ ما گر ملول شد<br />گو باده صاف ده که به عذر ایستاده ایم .<br /> <font color=\"Red\">حافظ.</font><br />عشق است و مفلسی و جوانی و نوبهار<br />عذرم پذیر و جرم به ذیل کرم بپوش .<br /> <font color=\"Red\">حافظ.</font><br />هر گنه عذری و هر تقصیر دارد توبه ای <br />نیست غیر از روز رفتن عذر بیجا آمدن .<br /> <font color=\"Red\">صائب .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عذر آوردن </span> ؛ بهانه آوردن . علت موجه گفتن ارتکاب گناهی را. جواب مقنع گفتن کار زشت یا ناروائی را <span class=\"hlight\">:</span> <br />تنت از بهر طاعت بُد به عصیانش بفرسودی <br />چه عذر آری اگر فردا بخواهند از تو این تاوان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />عذر میاور نه حیل خواستند<br />این سخن است از تو عمل خواستند.<br /> <font color=\"Red\">نظامی .</font><br />اگر هزار جفا سروقامتی بکند<br />چو خود بیاید عذرش بباید آوردن .<br /> <font color=\"Red\">سعدی .</font><BR>۩ پوزش خواستن <span class=\"hlight\">:</span> <br />سعدیا بسیار گفتن عمر ضایع کردن است <br />وقت عذر آوردن است استغفراﷲ العظیم .<br /> <font color=\"Red\">سعدی .</font><br />بنده همان به که ز تقصیرخویش <br />عذر به درگاه خدا آورد.<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عذر بدتر از گناه </span> ؛ پوزش که از خطا عظیم تر است و آن مثلی است مشهور و برای کسی آرند که در انجام ندادن کاری یا ارتکاب خطایی عذری آورد که از خود گناه نامقبول تر و بدتر باشد <span class=\"hlight\">:</span> <br />عقل تو از بس که آمد خیره سر<br />هست عذرت از گناه تو بتر.<br /> <font color=\"Red\">مولوی .</font><br />عذر خواهی کندم بعد از قتل <br />عذر بدتر ز گناهش نگرید.<br /><font color=\"Red\">محتشم .</font><br /></font></div>'),
(181869, 'عذر', '<span class=\"hlight\">عذر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) بسیار عیب گردیدن . <BR><font color=\"Blue\">◄</font> بسیار گناه گردیدن . <BR><font color=\"Blue\">◄</font> افسار نهادن اسب را. <BR><font color=\"Blue\">◄</font> ختنه کردن کودک را. (از اقرب الموارد) (منتهی الارب ) (از قطرالمحیط). <BR><font color=\"Blue\">◄</font> غالب شدن کسی را خون . <BR><font color=\"Blue\">◄</font> بهانه نمودن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> معذور داشتن . (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بدرد آوردن کودک را. (قطرالمحیط) (اقرب الموارد).<br /></font></div>'),
(181870, 'عذر به دست آوردن', '<span class=\"hlight\">عذر به دست آوردن .</span> <font color=\"DarkGreen\"><b>[ع ُ ب ِ دَ وَ دَ ]</font></b> (مص مرکب ) بهانه پیدا کردن جهت اعتذار. راه فرار یافتن برای گناه که مرتکب شده است .<br /></font></div>'),
(181871, 'عذر تقصیر', '<span class=\"hlight\">عذر تقصیر.</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ت َ ]</font></b> (ترکیب اضافی، اِ مرکب ) پوزش خواهی . از گناه <span class=\"hlight\">:</span> انابت مفید نباشد، نی راه بازگشتن آنگاه مهیا و نه عذر تقصیرات خواستن . (کلیله و دمنه ).<br />عذر تقصیر خدمت آوردم <br />که ندارم به طاعت استظهار.<br /> <font color=\"Red\">سعدی .</font><br />سعدیا در پای جانان گر به خدمت سر نهی <br />همچنان عذرت بباید خواستن تقصیر را.<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(181872, 'عذر خواستن', '<span class=\"hlight\">عذر خواستن .</span> <font color=\"DarkGreen\"><b>[ ع ُ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ت َ ]</font></b> (مص مرکب ) پوزش خواستن . معذرت خواستن . پوزش طلبیدن <span class=\"hlight\">:</span> زن کفشگر تنگدل شد و عذرها خواست . (کلیله و دمنه ). پس از بازگشتن شما بسیار عذر خواست . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٧٠</span>).<br />گهی درّ بارد گهی عذر خواهد<br />همان ابر بدخوی کافوربارش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چو نیکوئی کنی زآن عذر میخواه <br />که نیکوئی دو گردد باش آگاه .<br /> <font color=\"Red\">ناصرخسرو.</font><br />در این کارم اگر دولت بود یار<br />بخواهم هم بزودی عذر بسیار.<br /> <font color=\"Red\">نظامی .</font><br />زمین خدمت ببوسیدم و عذر جسارت خواستم . (گلستان ).<br />ببایست عذر خطا خواستن <br />پس از شیخ صالح دعا خواستن .<br /> <font color=\"Red\">سعدی .</font><br />کسی را نظر سوی شاهد رواست <br />که داندبدین شاهدی عذر خواست .<br /> <font color=\"Red\">سعدی (بوستان ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عذر کس را خواستن </span> ؛ او را اخراج کردن . او را بیرون کردن .<br /></font></div>'),
(181873, 'عذر داشتن', '<span class=\"hlight\">عذر داشتن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ت َ ]</font></b> (مص مرکب ) معذور بودن . <BR><font color=\"Blue\">◄</font> کنایه از حایض بودن است .<br /></font></div>'),
(181874, 'عذر دیدن', '<span class=\"hlight\">عذر دیدن .</span> <font color=\"DarkGreen\"><b>[ ع ُ دی دَ ]</font></b>(مص مرکب ) عادت دیدن . در تداول عامه حائض شدن زن .<br /></font></div>'),
(181875, 'عذر شنیدن', '<span class=\"hlight\">عذر شنیدن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ دَ ]</font></b> (مص مرکب ) پذیرفتن اعتذار. قبول اعتذار. پوزش پذیرفتن <span class=\"hlight\">:</span> <br />مرغ بیوقتی سرت باید برید<br />عذر احمق را نمی باید شنید.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(181876, 'عذر قدم', '<span class=\"hlight\">عذر قدم .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ق َ دَ ]</font></b> (ترکیب اضافی، اِ مرکب ) عذر خواهی از رنجه شدن قدم کسی بسبب آمدن . کنایه از تواضعی است که جهت مردم کنند تا در کوچه مشایعت کنند و نیز کنایه از تواضعی است که با مهمان کنند و عذر قدم رنجه نمودن وی خواهند. (آنندراج ).<br /></font></div>'),
(181877, 'عذر لنگ', '<span class=\"hlight\">عذر لنگ .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ل َ ]</font></b> (ترکیب وصفی، اِ مرکب ) بهانه ٔ ضعیف و سست . بهانه ٔ پوچ و نامسموع . (غیاث اللغات ) (از برهان ). عذری نامقبول . عذری نارسا. عذری ناموجه <span class=\"hlight\">:</span> <br />برد لنگی به راهواری پیش <br />پیشم از بسکه عذر لنگ آورد.<br /> <font color=\"Red\">انوری .</font><br />حدیت لنگی استر به عذر می شاید<br />اگر به نکته بگویم که عذر هم لنگ است .<br /> <font color=\"Red\">ظهیر.</font><br />هدهدش گفت ای چو گوهر جمله رنگ <br />چند لنگی چند آری عذر لنگ .<br /> <font color=\"Red\">عطار.</font><br />اگر سیمت ببخشد سنگ باشد<br />اگر عذرت بخواهد لنگ باشد.<br /> <font color=\"Red\">عطار.</font><br />هر یکی را بودعذری لنگ لنگ <br />این چنین کس کی کند عنقا به چنگ .<br /> <font color=\"Red\">عطار.</font><br />ز ناتوانی پایم به دست عذری هست <br />تو عذر لنگ به نوعی که میتوان برسان .<br /> <font color=\"Red\">سلمان ساوجی .</font><br />به خویش رنج پسندید بهر راحت خلق <br />چو عذر لنگ که در راه دیگران لنگ است .<br /> <font color=\"Red\">محسن (از آنندراج ).</font><br />برای وعده خلافی عبث مخور سوگند<br />که احتیاج عصا نیست عذر لنگ ترا.<br /> <font color=\"Red\">محمدقلی سلیم (از آنندراج ).</font><br />میار عذر که ره دور و مرکبم لنگ است <br />که عذر لنگ نشاید ز رهروان ملنگ .<br /><font color=\"Red\">کاتبی .</font><br /></font></div>'),
(181878, 'عذر مقبول', '<span class=\"hlight\">عذر مقبول .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ م َ ]</font></b> (ترکیب وصفی، اِ مرکب ) عذر پسندیده و موجه . (از آنندراج ).<br /></font></div>'),
(181879, 'عذر ناموجه', '<span class=\"hlight\">عذر ناموجه .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ م ُ وَج ْ ج َه ْ ]</font></b> (ترکیب وصفی ) اعتذار غیرقابل قبول . بهانه ٔ نادرست . عذر نادرست . پوزش ناپذیرفتنی .<br /></font></div>'),
(181880, 'عذر نهادن', '<span class=\"hlight\">عذر نهادن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ دَ ]</font></b> (مص مرکب ) اعتذار. عذر آوردن . بهانه آوردن <span class=\"hlight\">:</span> و عاملی به حضرت خویشتن استدعا کرد صد عذر نهاد. (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> عذر پذیرفتن . عذر خواستن . معذور داشتن <span class=\"hlight\">:</span> <br />صد عذر نهم گر بودش آزاری <br />این جور ترا چه عذر سازم باری .<br /> <font color=\"Red\">مجیر بیلقانی .</font><br />نیکان عهد را به بدی کردن <br />عذری بنه که دسترس آن داری .<br /> <font color=\"Red\">خاقانی .</font><br />تا عذر زلیخا بنهد منکر عشاق <br />یوسف صفت از چهره برانداز نقابی .<br /> <font color=\"Red\">سعدی .</font><br />هر که نامردم بود عذرش بنه <br />چون به چشمش در نیامد مردمی .<br /> <font color=\"Red\">سعدی .</font><br />عذر سعدی ننهد هر که ترا نشناسد<br />حال دیوانه نداند که ندیده ست پری .<br /> <font color=\"Red\">سعدی .</font><br />جنگ هفتاد و دو ملت همه را عذر بنه <br />چون ندیدند حقیقت ره افسانه زدند.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(181881, 'عذر و بهانه', '<span class=\"hlight\">عذر و بهانه .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ب َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ترکیب عطفی، اِ مرکب ) رجوع به عذر و رجوع به بهانه شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عذر و بهانه آوردن </span> ؛ برای انجام ندادن کاری دلیل بی اساس تراشیدن .<br /></font></div>'),
(181882, 'عذر پذیر', '<span class=\"hlight\">عذر پذیر.</span> <font color=\"DarkGreen\"><b>[ ع ُ پ َ ]</font></b> (نف مرکب ) عذرپذیرنده . که پوزش پذیرد و عذر قبول کند. مقابل عذرآور. (آنندراج ).<br /></font></div>'),
(181883, 'عذر پذیرنده', '<span class=\"hlight\">عذر پذیرنده .</span> <font color=\"DarkGreen\"><b>[ ع ُ پ َ رَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف مرکب ) آنکه عذر کس پذیرد. که پوزش قبول کند <span class=\"hlight\">:</span> <br />بپذیر نصیحت بطلب حکمت دین را<br />ای عذر پذیرنده از این گنبد غدار.<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(181884, 'عذر گفتن', '<span class=\"hlight\">عذر گفتن .</span> <font color=\"DarkGreen\"><b>[ ع ُ گ ُ ت َ ]</font></b> (مص مرکب ) معذرت خواستن . پوزش خواستن <span class=\"hlight\">:</span> <br />ولیک عذر توان گفت پای سعدی را<br />در این لجن که فروشد نه اولین پاییست .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(181885, 'عذر گویان', '<span class=\"hlight\">عذر گویان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (نف مرکب، ق مرکب ) پوزش جویان . عذرخواهان . پوزش طلبانه <span class=\"hlight\">:</span> <br />شدم عذر گویان برشخص عاج <br />به کرسی زر کوفت بر تخت ساج .<br /><font color=\"Red\">سعدی (بوستان ).</font><br /></font></div>'),
(181886, 'عذرآوری', '<span class=\"hlight\">عذرآوری .</span> <font color=\"DarkGreen\"><b>[ ع ُ وَ ]</font></b> (حامص مرکب ) بهانه آوری . معذرت خواهی . پوزش خواهی <span class=\"hlight\">:</span> <br />چنان کن که فردا در آن داوری <br />نگیرد زبانت به عذرآوری .<br /> <font color=\"Red\">نظامی .</font><br />بزرگان لشکر به عذرآوری <br />پشیمان شدند از چنان داوری .<br /> <font color=\"Red\">نظامی .</font><br />به عذر آوری خواهش امروز کن <br />که فردا نماند مجال سخن .<br /> <font color=\"Red\">سعدی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">روز عذرآوری </span> ؛ روز قیامت <span class=\"hlight\">:</span> <br />بپرهیزم از روزعذرآوری <br />بپرهیزگاری کنم داوری .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(181887, 'عذرات', '<span class=\"hlight\">عذرات .</span> <font color=\"DarkGreen\"><b>[ ع َ ذِ ]</font></b> (ع اِ) ج ِ عَذرة. (ناظم الاطباء). رجوع به عذرة شود.<br /></font></div>'),
(181888, 'عذراوات', '<span class=\"hlight\">عذراوات .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) ج ِ عذراء. (ناظم الاطباء).<br /></font></div>'),
(181889, 'عذراوش', '<span class=\"hlight\">عذراوش .</span> <font color=\"DarkGreen\"><b>[ ع َ وَ ]</font></b> (ص مرکب ) مانند عذرا. مجازاً، زیبا صورت <span class=\"hlight\">:</span> <br />سرمست عشق سرکشی خاکستری در آتشی <br />در ششدر عذراوشی صد خون عذرا ریخته .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(181890, 'عذرخواه', '<span class=\"hlight\">عذرخواه .</span> <font color=\"DarkGreen\"><b>[ ع ُ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا]</font></b> (نف مرکب ) پوزش خواه . که معذرت خواهد <span class=\"hlight\">:</span> <br />همه پیش کاووس شاه آمدند<br />جگرخسته و عذرخواه آمدند.<br /> <font color=\"Red\">فردوسی .</font><br />اشک من چون زبان خونین هم <br />حیلت عذرخواه میگوید.<br /> <font color=\"Red\">خاقانی .</font><br />فرستادش به دست عذرخواهان <br />چنان نزلی که باشد رسم شاهان .<br /> <font color=\"Red\">نظامی .</font><br />به مهلت ز شب عذرخواه آمدم <br />ز میدان سوی خوابگاه آمدم .<br /> <font color=\"Red\">نظامی .</font><br />جرم دل عذرخواه من چیست <br />جز دوستیت گناه من چیست .<br /> <font color=\"Red\">نظامی .</font><br />آنچه من دادمش بهم پیوست <br />پیشم آورد و عذرخواه نشست .<br /> <font color=\"Red\">نظامی .</font><br />عذرخواه عقل کل و جان توئی <br />جان جان و تابش مرجان توئی .<br /> <font color=\"Red\">مولوی .</font><br />نیامد بدین در کسی عذرخواه <br />که سیل ندامت نشستی گناه .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />عذرخواهان را خطا کاری ببخش <br />زینهاری را بجان ده زینهار.<br /> <font color=\"Red\">سعدی .</font><br />هنوز ار سر صلح داری چه بیم <br />دَرِ عذرخواهان نبندد کریم .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />گرم ترانه ٔ چنگ و صبوح نیست چه باک <br />نوای من به سحر آه عذرخواه من است .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(181891, 'عذرخواهی', '<span class=\"hlight\">عذرخواهی .</span> <font color=\"DarkGreen\"><b>[ ع ُ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (حامص مرکب ) پوزش طلبیدن . پوزش خواستن . پوزش طلبی . بهانه آوری . پوزش خواهی . طلب عفو کردن <span class=\"hlight\">:</span> <br />گرچه موقوف نیست شاهی من <br />بر مدارا و عذرخواهی من .<br /> <font color=\"Red\">نظامی .</font><br />حافظ چو پادشاهت گه گاه میبرد نام <br />رنجش ز بخت منما بازآ به عذرخواهی .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(181892, 'عذرخواهی نمودن', '<span class=\"hlight\">عذرخواهی نمودن .</span> <font color=\"DarkGreen\"><b>[ ع ُ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ن ُ<span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ دَ ]</font></b> (مص مرکب ) پوزش طلبیدن <span class=\"hlight\">:</span> <br />بسی عذرخواهی نمودش که زود<br />گریزان شو و جان ببر همچو دود.<br /><font color=\"Red\">سعدی (بوستان ).</font><br /></font></div>'),
(181893, 'عذرساز', '<span class=\"hlight\">عذرساز.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (نف مرکب ) آنکه عذر آورد. آنکه پوزش و اعتذار آغازد <span class=\"hlight\">:</span> <br />چو شه دید کان خسرو عذر ساز<br />پیاده بنزدیک او شد فراز.<br /> <font color=\"Red\">نظامی .</font><br />و گر پیش اقبال بازآمدی <br />کجا عذر اگر عذرساز آمدی .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(181894, 'عذرسازی', '<span class=\"hlight\">عذرسازی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (حامص مرکب ) عمل عذرساز. حالت و چگونگی عذر ساز. عذرآوری <span class=\"hlight\">:</span> <br />پیر چون دید عذرسازی او<br />کرد رغبت بدلنوازی او.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(181895, 'عذرنیوش', '<span class=\"hlight\">عذرنیوش .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (نف مرکب ) شنونده ٔ عذر. عذرپذیر.<br /></font></div>'),
(181896, 'عذرنیوشا', '<span class=\"hlight\">عذرنیوشا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (نف مرکب ) شنونده ٔ عذر. رجوع به عذر نیوشان شود.<br /></font></div>'),
(181897, 'عذرنیوشان', '<span class=\"hlight\">عذرنیوشان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (نف مرکب ) شنونده ٔ عذر <span class=\"hlight\">:</span> <br />عذرش ز پی جرم بود عذر نیوشان <br />حلمش به گه عفو چنان عذرپذیرست .<br /><font color=\"Red\">انوری (از آنندراج ).</font><br /></font></div>'),
(181898, 'عذری', '<span class=\"hlight\">عذری .</span> <font color=\"DarkGreen\"><b>[ ع ُ را ]</font></b> (ع اِمص ) اسم است به معنی معذرت ؛ حددت و لا عذری لمحدود. (از اقرب الموارد).<br /></font></div>'),
(181899, 'عذط', '<span class=\"hlight\">عذط.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِمص ) اسم است عذیطة را یا مشتق نشود از آن فعل . (منتهی الارب ). رجوع به عذیطة شود.<br /></font></div>'),
(181900, 'عذف', '<span class=\"hlight\">عذف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) خوردن . (از اقرب الموارد) (از قطرالمحیط) (منتهی الارب ).<br /></font></div>'),
(181901, 'عذفوط', '<span class=\"hlight\">عذفوط.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) کرمکی است سپیدنازک که بدان انگشتان دختران ملیح را تشبیه کنند. (از اقرب الموارد) (از قطرالمحیط) (از منتهی الارب ).<br /></font></div>'),
(181902, 'عذق', '<span class=\"hlight\">عذق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) دور کردن گشن را از ماده شتران و فراهم آوردن و فراگرفتن آنها را. <BR><font color=\"Blue\">◄</font> بستن بر گوسفند پشم را بخلاف رنگ آن جهت نشان . (منتهی الارب ) (از اقرب الموارد) (از قطرالمحیط). نشان کردن گوسفند. (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> دشنام دادن کسی را و تهمت کردن . (منتهی الارب ). کسی را بعیبی معروف کردن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> نسبت دادن کسی را به چیزی . <BR><font color=\"Blue\">◄</font> بازآوردن . (منتهی الارب ).بازبیاوردن . (تاج المصادر). <BR><font color=\"Blue\">◄</font> بریدن شاخهای خرما. (منتهی الارب ) (از قطرالمحیط) (تاج المصادربیهقی ). <BR><font color=\"Blue\">◄</font> ریخ زدن شتر. (منتهی الارب ).<br /></font></div>'),
(181903, 'عذق', '<span class=\"hlight\">عذق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) خوشه ٔ خرما. (منتهی الارب ) (از اقرب الموارد) (از قطرالمحیط). <BR><font color=\"Blue\">◄</font> خوشه ٔ انگور یا خوشه ٔ انگورکه باران خورده باشد. (منتهی الارب ). ج، اعذاق، عُذوق . <BR><font color=\"Blue\">◄</font> هر شاخ که بر آن شاخهای ریزه باشد. (از اقرب الموارد) (از قطرالمحیط) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> عزت . (قطرالمحیط) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ارجمندی . ج، عَذق . <BR><font color=\"Blue\">◄</font> (اِخ ) قلعه ای است به مدینه مر بنی امیة زید را. (منتهی الارب ).<br /></font></div>'),
(181904, 'عذق', '<span class=\"hlight\">عذق .</span> <font color=\"DarkGreen\"><b>[ ع َ ذِ ]</font></b> (ع ص ) مرد زیرک هوشیار چرب زبان . (از اقرب الموارد) (از قطرالمحیط) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> طیب عذق ؛ خوشبوی تیز و تند بوی . (منتهی الارب ) (از اقرب الموارد).<br /></font></div>'),
(181905, 'عذق', '<span class=\"hlight\">عذق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) خرمابن با بار. ج، اَعذُق و عِذق ؛ و منه قول الجباب بن المنذر انا عذیقها المرجب . <BR><font color=\"Blue\">◄</font> نوعی از خرما در مدینه . (منتهی الارب ).<br /></font></div>'),
(181906, 'عذق بن طاب', '<span class=\"hlight\">عذق بن طاب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ُ ن ُ ]</font></b> (ع اِ مرکب ) نوعی از خرماست . (از اقرب الموارد).<br /></font></div>'),
(181907, 'عذقانة', '<span class=\"hlight\">عذقانة.</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ ]</font></b> (ع ص ) زن زبان دراز. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زن سلیطه . (از قطرالمحیط). زن سلیطه ٔ دریده (بدسخن ). (از اقرب الموارد).<br /></font></div>'),
(181908, 'عذل', '<span class=\"hlight\">عذل .</span> <font color=\"DarkGreen\"><b>[ ع َ ذَ ]</font></b> (ع اِمص ) سرزنش و ملامت . (از اقرب الموارد). نکوهش . (آنندراج ) (منتهی الارب ) (تاج المصادر بیهقی ). و فی المثل سبق السیف ُ العذل َ، ویقال أول من تکلم بذلک ضبةبن ادر حین قتل رجلا فی الشهر الحرام فعذله الناس فقال المثل . (منتهی الارب ).<br /></font></div>'),
(181909, 'عذل', '<span class=\"hlight\">عذل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) نکوهیدن . (منتهی الارب ) (آنندراج ). ملامت کردن . (تاج المصادر بیهقی ). ملامت کردن کسی را. (از اقرب الموارد).<br /></font></div>'),
(181910, 'عذل', '<span class=\"hlight\">عذل .</span> <font color=\"DarkGreen\"><b>[ ع ُذْ ذَ ]</font></b> (ع ص، اِ) ج ِ عاذل . (منتهی الارب ) (اقرب الموارد). رجوع به عاذل شود.<br /></font></div>'),
(181911, 'عذل', '<span class=\"hlight\">عذل .</span> <font color=\"DarkGreen\"><b>[ ع ُ ذُ ]</font></b> (ع ص ) روزهای نیک گرم . (از قطرالمحیط) (آنندراج ) (منتهی الارب ).<br /></font></div>'),
(181912, 'عذلاج', '<span class=\"hlight\">عذلاج .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) خوش : عیش عذلاج ؛ زندگانی خوش . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181913, 'عذلة', '<span class=\"hlight\">عذلة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ذَ ل َ ]</font></b> (ع ص ) بسیار نکوهنده . (منتهی الارب ) (از آنندراج ). آنکه مردمان را بسیار ملامت کند. (مهذب الاسماء) (تاج المصادر بیهقی ).<br /></font></div>'),
(181914, 'عذلة', '<span class=\"hlight\">عذلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ذَ ل َ ]</font></b> (ع ص، اِ) ج ِعاذل . (منتهی الارب ) (آنندراج ). رجوع به عاذل شود.<br /></font></div>'),
(181915, 'عذلظ', '<span class=\"hlight\">عذلظ.</span> <font color=\"DarkGreen\"><b>[ ع ُ ذَ ل ِ ]</font></b> (ع ص ) شیر دفزک و سطبر. (از اقرب الموارد) (منتهی الارب ) (از آنندراج ).<br /></font></div>'),
(181916, 'عذلوج', '<span class=\"hlight\">عذلوج .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) بچه ٔ خورش وپرورش نیکو یافته . (منتهی الارب ) (آنندراج ). بچه که غذایش نیکو باشد. (از اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181917, 'عذلوق', '<span class=\"hlight\">عذلوق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) کودک سبک روح چست تیزفهم . لغتی است در ذعلوق . (از اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181918, 'عذم', '<span class=\"hlight\">عذم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) گزیدن یا بسختی خوردن اسب . (از قطرالمحیط) (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دور نمودن از خود. (آنندراج ) (منتهی الارب )؛ عذم عن نفسه رأی دفع عن نفسه . (از قطرالمحیط) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نکوهیدن . (قطرالمحیط) (از اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181919, 'عذم', '<span class=\"hlight\">عذم .</span> <font color=\"DarkGreen\"><b>[ ع َ ذَ ]</font></b> (اِخ ) رودباری است به یمن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (ع اِ) گیاهی است . <BR><font color=\"Blue\">◄</font> (مص ) دشنام دادن زن شوی را هرگاه او اراده ٔ وطی از دبر وی کند. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181920, 'عذم', '<span class=\"hlight\">عذم .</span> <font color=\"DarkGreen\"><b>[ ع َ ذِ ]</font></b> (ع ص ) اسب گزنده و بسختی خورنده . (آنندراج ) (منتهی الارب ).<br /></font></div>'),
(181921, 'عذم', '<span class=\"hlight\">عذم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ذُ ]</font></b> (ع اِ) ج ِ عَذّام . (منتهی الارب ). رجوع به عذام شود.<br /></font></div>'),
(181922, 'عذمذم', '<span class=\"hlight\">عذمذم .</span> <font color=\"DarkGreen\"><b>[ ع َ ذَ ذَ ]</font></b> (ع ص ) پیمایش تخمینی . (آنندراج ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مرگ بسیار. (منتهی الارب ).<br /></font></div>'),
(181923, 'عذمهر', '<span class=\"hlight\">عذمهر.</span> <font color=\"DarkGreen\"><b>[ ع َ ذَ هََ ]</font></b>(ع ص ) شهر گشاده و وسیع. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181924, 'عذو', '<span class=\"hlight\">عذو.</span> <font color=\"DarkGreen\"><b>[ ع َذْوْ ]</font></b> (ع مص ) خوش باد گردیدن شهر. (از منتهی الارب ) (از اقرب الموارد).<br /></font></div>'),
(181925, 'عذوات', '<span class=\"hlight\">عذوات .</span> <font color=\"DarkGreen\"><b>[ ع َ ذَ ]</font></b>(ع اِ) ج ِ عذیة. (منتهی الارب ). رجوع به عذیة شود.<br /></font></div>'),
(181926, 'عذوب', '<span class=\"hlight\">عذوب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) کسی که از شدت تشنگی نخورد. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آنکه میان او و میان آسمان حائل نباشد. <BR><font color=\"Blue\">◄</font> ستور ایستاده که آب و علف نخورد. (از اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181927, 'عذوبة', '<span class=\"hlight\">عذوبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع مص ) پاکیزه گردیدن آب . (از اقرب الموارد) (آنندراج ) (منتهی الارب ) (غیاث اللغات ). خوش شدن آب . (تاج المصادر بیهقی ). مجازاً، بمعنی شیرین شدن دیگر اشیاء سوای آب . (آنندراج ) (منتهی الارب ) <span class=\"hlight\">:</span> <br />جز در صفات نجم نخواهد شدن پدید<br />در نثر من عذوبت و در نظم من نظام .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(181928, 'عذوبت', '<span class=\"hlight\">عذوبت .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع مص ) رجوع به عذوبة شود.<br /></font></div>'),
(181929, 'عذور', '<span class=\"hlight\">عذور.</span> <font color=\"DarkGreen\"><b>[ ع َ ذَوْ وَ ]</font></b> (ع ص ) فاحش و فراخ شکم (خر). <BR><font color=\"Blue\">◄</font> مرد بدخوی سنگدل . <BR><font color=\"Blue\">◄</font> پادشاه سخت و درشت . (آنندراج ) (منتهی الارب ).<br /></font></div>'),
(181930, 'عذوف', '<span class=\"hlight\">عذوف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) نیک خورنده . <BR><font color=\"Blue\">◄</font> ذائقه گیرنده . (منتهی الارب ) (آنندراج ). عدوف (الذال لغة ربیعة و بالمهملة لسائر العرب ) (از اقرب الموارد). و رجوع به عدوف شود.<br /></font></div>'),
(181931, 'عذوفر', '<span class=\"hlight\">عذوفر.</span> <font color=\"DarkGreen\"><b>[ ع َ ذَ ف َ ]</font></b> (ع ص ) شتر استوار بزرگ جثه . (از اقرب الموارد) (آنندراج ). عذافر. رجوع به عذافر شود.<br /></font></div>'),
(181932, 'عذوق', '<span class=\"hlight\">عذوق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) عِذق . رجوع به عِذق شود.<br /></font></div>'),
(181933, 'عذول', '<span class=\"hlight\">عذول .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) ملامت کننده . (آنندراج ). بسیار سرزنش کننده مردم را. (از اقرب الموارد).<br /></font></div>'),
(181934, 'عذویة', '<span class=\"hlight\">عذویة.</span> <font color=\"DarkGreen\"><b>[ ع َ ذَ وی ی َ ]</font></b> (ع ص ) ابل عذویة، بمعنی ابل عواذ است . (منتهی الارب ). رجوع به عواذ شود.<br /></font></div>'),
(181935, 'عذی', '<span class=\"hlight\">عذی .</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِذْی ْ ]</font></b> (ع اِ) کشت دشتی که از باران آب خورد. (منتهی الارب ) (از اقرب الموارد) (آنندراج ). <BR><font color=\"Blue\">◄</font> هر شهر که شوره ندارد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181936, 'عذی', '<span class=\"hlight\">عذی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) نام جایی است . (منتهی الارب ). لیث گوید: موضعی است به بادیه و نام است محلی را که در زمستان و تابستان در آن گیاه روید بدون آب . ازهری گوید: موضعی است به بادیه . (از معجم البلدان ).<br /></font></div>'),
(181937, 'عذیب', '<span class=\"hlight\">عذیب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) موضعی است بین قادسیه و مغیثه که فاصله ٔ بین آن وقادسیه چهار میل است و تا مغیثه سی و دو میل میباشدو گفته شده است که عذیب وادیی است از آن بنی تمیم و از منازل حاج کوفه و گویند از سواد است، ابوعبداﷲ الکوفی گوید عذیب محلی است که از قادسیه ٔ کوفه به سوی آن روند و زرادخانه ٔ فرس بوده است و فاصله بین آن و قادسیه دو دیوار متصل بوده که میان آن دو درختان خرما وجود داشته و آن شش میل است . (از معجم البلدان ).<br /></font></div>'),
(181938, 'عذیب', '<span class=\"hlight\">عذیب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) موضعی است به بصره . (از معجم البلدان ).<br /></font></div>'),
(181939, 'عذیب', '<span class=\"hlight\">عذیب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) آبی است بنزدیک فرما از سرزمین مصر در وسط ریگ . (از معجم البلدان ).<br /></font></div>'),
(181940, 'عذیب', '<span class=\"hlight\">عذیب .</span> <font color=\"DarkGreen\"><b>[ ع ُذَ ]</font></b> (اِخ ) آبی است مر بنی تمیم را. (منتهی الارب ).<br /></font></div>'),
(181941, 'عذیبة', '<span class=\"hlight\">عذیبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ذَ ب َ ]</font></b> (اِخ ) آبی است بین ینبع وجار. (جار شهری است بر دریا نزدیک مدینه ) و گفته شده است دهی است بین جار و ینبع. (از معجم البلدان ).<br /></font></div>'),
(181942, 'عذیة', '<span class=\"hlight\">عذیة.</span> <font color=\"DarkGreen\"><b>[ ع َ ی َ ]</font></b> (ع ص ) زمین خوش خاک . (از اقرب الموارد) (آنندراج ). زمین دور ازآب و از شوری و ناگواری . (آنندراج ). عذاة. <BR><font color=\"Blue\">◄</font> (اِ) خاشاک . (منتهی الارب ). رجوع به عذاة شود.<br /></font></div>'),
(181943, 'عذیر', '<span class=\"hlight\">عذیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) طعام بنا. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مهمانی ختنة. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> طعامی که بعد از هر امر جدیدی بطریق شادمانی سازند و قریبان را بر آن خوانند. <BR><font color=\"Blue\">◄</font> (ص ) مرد عذرخواه . (از اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> بهانه آرنده . (اقرب الموارد) (منتهی الارب ) (از آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) حال که جهت عذرخواهی سازند و بر آن معذور دارند. ج، عُذُر. <BR><font color=\"Blue\">◄</font> (ص ) یاری ده . یقال عذیرک من فلان . (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br /></font></div>'),
(181944, 'عذیمة', '<span class=\"hlight\">عذیمة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع اِمص ) نکوهش . <BR><font color=\"Blue\">◄</font> گزیدگی و خاییدگی . ج، عذائم . (از اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (ص ) خرمابن که بار آن خسته نداشته باشد. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181945, 'عذیوط', '<span class=\"hlight\">عذیوط.</span> <font color=\"DarkGreen\"><b>[ ع ِذْ ی َ ]</font></b> (ع ص ) کسی که وقت جماع حدث کند. (منتهی الارب ) (آنندراج ). یا قبل از دخول انزال آیدش . ج، عذیوطون، عذاویط، عذائیط. (آنندراج ) (منتهی الارب ).<br /></font></div>'),
(181946, 'عر', '<span class=\"hlight\">عر.</span> <font color=\"DarkGreen\"><b>[ ع ُرر ]</font></b> گر. عَرّ. عرّه . با فتح اول جرب است و بضم اول قروحی است در اعناق ابل و فصلان . (از منتهی الارب ) (آنندراج ). قرحه هایی در گردن شتر. <BR><font color=\"Blue\">◄</font> جرب . (از اقرب الموارد). گری و جرب . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بیماریی است که از آن پشم گوسپند و شتر برافتد. (منتهی الارب ) (آنندراج ). بیماریی است که از آن پشم شتر بریزد. (از اقرب الموارد). در صحاح است که قروحی است مثل قوباء که بر پاهای شتر ظاهر شوند و از آن آب زرد ریزش کند. (از اقرب الموارد) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> زرق پرنده . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زرق پسر. <BR><font color=\"Blue\">◄</font> کودک . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> طفل که زوداز شیر باز داشته شود. (آنندراج ). <BR><font color=\"Blue\">◄</font> عُرّاالوادی، دو طرف آن را گویند. (از اقرب الموارد).<br /></font></div>'),
(181947, 'عر', '<span class=\"hlight\">عر.</span> <font color=\"DarkGreen\"><b>[ ع َرر ]</font></b> (ع مص ) به بدی انداختن کسی را. (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آلودن کسی را به بدی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> رسانیدن کسی را به مکروهی . <BR><font color=\"Blue\">◄</font> از بیخ برکندن موی . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> باز افکندن زمین را. (از اقرب الموارد) (آنندراج ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> حاجتمند شدن . (از اقرب الموارد) (قطرالمحیط) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نیازمندی نمودن کسی را. <BR><font color=\"Blue\">◄</font> گرگین شدن شتران . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> اندوهگین کردن کسی را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دادن کسی را بی خواست . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> سرگین در زمین کسی کردن . (تاج المصادر). سرگین انداختن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کسی را غمگین کردن . (المصادر زوزنی ) (تاج المصادر). <BR><font color=\"Blue\">◄</font> گشن ناک گردیدن . (منتهی الارب ).<br /></font></div>'),
(181948, 'عر', '<span class=\"hlight\">عر.</span> <font color=\"DarkGreen\"><b>[ ع ُرر ]</font></b> (ع مص ) گشن ناک گردیدن . (منتهی الارب ). عَرّ.<br /></font></div>'),
(181949, 'عر', '<span class=\"hlight\">عر.</span> <font color=\"DarkGreen\"><b>[ ع َرر ]</font></b> (ع اِ) جرب . <BR><font color=\"Blue\">◄</font> عیب . <BR><font color=\"Blue\">◄</font> شر. <BR><font color=\"Blue\">◄</font> آنکه زود از شیر گرفته شود. (از اقرب الموارد). کودکی که زود از شیر باز داشته شود یا عام است . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> کرکس . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> نهیق خر. بانگ خر. رجوع به عرعر و عروعر شود.<br /></font></div>'),
(181950, 'عر زدن', '<span class=\"hlight\">عر زدن .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ دَ ]</font></b> (مص مرکب ) در تداول، گریه کردن کودک است با آواز بلند.<br /></font></div>'),
(181951, 'عر و بوق', '<span class=\"hlight\">عر و بوق .</span> <font color=\"DarkGreen\"><b>[ ع َرْ رُ ]</font></b> (ترکیب عطفی، اِ مرکب )از اتباع است . (یادداشت مرحوم دهخدا). عروتیز. اشتلم و بانگ و فریاد به تظاهر. رجوع به عر و تیز شود.<br /></font></div>'),
(181952, 'عر و تیز', '<span class=\"hlight\">عر و تیز.</span> <font color=\"DarkGreen\"><b>[ ع َرْ رُ ]</font></b> (ترکیب عطفی، اِ مرکب ) هارت و پورت . اشتلم . داد و فریاد به تظاهر. عر و بوق .<br /></font></div>'),
(181953, 'عر و تیز کردن', '<span class=\"hlight\">عر و تیز کردن .</span> <font color=\"DarkGreen\"><b>[ ع َرْ رُ ک َ دَ ]</font></b> (مص مرکب ) سر و صدا و داد و بیداد راه انداختن . هارت و پورت کردن . (از فرهنگ لغات عامیانه ). عربده کشیدن و بد حرفی کردن، و آن بر سبیل استهزاء و تمسخر گفته می شود چنانکه گویند: مرتباً داد میزد و عر و تیز می کرد، می پنداشت من از اوترس دارم . (از فرهنگ عوام ). <BR><font color=\"Blue\">◄</font> هیاهو و اشتلم و اظهار خشم کردن . (از یادداشت مرحوم دهخدا).<br /></font></div>'),
(181954, 'عر و عر', '<span class=\"hlight\">عر و عر.</span> <font color=\"DarkGreen\"><b>[ ع َرْ رُ ع َ ]</font></b> (ترکیب عطفی، اِ مرکب ) حکایت آواز خر. نهیق . عرعر.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">عر و عر کردن </span> ؛ آواز برآوردن خر.<BR>۩ مجازاً و در مقام استخفاف، نسبت ناخوشایندی به آوای کسی دادن .<br /></font></div>'),
(181955, 'عر و عر', '<span class=\"hlight\">عر و عر.</span> <font color=\"DarkGreen\"><b>[ ع ُرْ رُ ع ُ ]</font></b> (ترکیب عطفی، اِ مرکب ) گرفتار استفراغ و غثیان شدن . (فرهنگ لغات عامیانه ).<br /></font></div>'),
(181956, 'عر و عنگ', '<span class=\"hlight\">عر و عنگ .</span> <font color=\"DarkGreen\"><b>[ ع َرْ رُ ع َ ]</font></b> (ترکیب عطفی، اِ مرکب ) آواز خر. (یادداشت مرحوم دهخدا). عرعر.<br /></font></div>'),
(181957, 'عر و عور', '<span class=\"hlight\">عر و عور.</span> <font color=\"DarkGreen\"><b>[ ع َرْ رُ ]</font></b> (ترکیب عطفی، اِ مرکب ) آواز بد. (از فرهنگ لغات عامیانه ). <BR><font color=\"Blue\">◄</font> گریه و زرزر کردن بچه ٔ نحس را نیز گویند. (فرهنگ لغات عامیانه ).<br /></font></div>'),
(181958, 'عر و گوز', '<span class=\"hlight\">عر و گوز.</span> <font color=\"DarkGreen\"><b>[ ع َرْ رُ ]</font></b> (ترکیب عطفی، اِ مرکب ) عر و تیز. شور و غوغای بی محل . (آنندراج ) <span class=\"hlight\">:</span> <br />بر دماغ حسن چون با دختران ریش خورد<br />عشوه با آن عروگوز از خویش نفرت می کند.<br /> <font color=\"Red\">ملا فوقی یزدی (از آنندراج ).</font><br />تا کی این کش وفش تقطیع و عروگوز مال <br />غافلی کآخر تو را صد مایه خجلت داده اند.<br /> <font color=\"Red\">ملا فوقی یزدی (از آنندراج ).</font><br />نگشوده بغیر عروگوزی از وی <br />این کله دراز کرنایی بوده .<br /><font color=\"Red\">ملاطغرا (از آنندراج ).</font><br /></font></div>'),
(181959, 'عر و یان', '<span class=\"hlight\">عر و یان .</span> <font color=\"DarkGreen\"><b>[ ع َرْ رُ ]</font></b> (ترکیب عطفی، اِ مرکب ) به معنی عر وگوز. (آنندراج ). رجوع به عر و گوز شود <span class=\"hlight\">:</span> <br />هرکه عری کرد یا یانی درین حیوان کده <br />عر و یانی بنده هم بر طرز ایشان میزنم .<br /><font color=\"Red\">ملا فوقی یزدی (از آنندراج ).</font><br /></font></div>'),
(181960, 'عراب', '<span class=\"hlight\">عراب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) بار درختی است که از پوست آن رسن سازند. (از اقرب الموارد) (منتهی الارب ). حمل الحزم و هو شجر یفتل من لحائه الحبال . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بانگ اشترمرغ . (مهذب الاسماء).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(181961, 'عراب', '<span class=\"hlight\">عراب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص، اِ) اسب تازی گرامی نژاد. (از اقرب الموارد) (منتهی الارب ). و همچنین است در شتر. <BR><font color=\"Blue\">◄</font> نوع خوب از گاو. (از اقرب الموارد). صاحب صبح الاعشی آرد: عراب یکی از انواع اسب و از بهترین نوع آن است و بالاترین قیمت ها را دارد و آن را برای انجام سبق و لحاق خواهند. پادشاهان به این گونه مراکب اهمیت میدادند و آنها را به بهای گرانی خریداری میکردند و از وسائل مهم جنگهابه حساب می آوردند. اینگونه اسبها در بلاد عرب مانند حجاز و نجد و یمن و عراق و شام و مصر یافت میشود. (از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٧</span>). شتران عربی گرامی نژاد. (از اقرب الموارد) (منتهی الارب ). خیل عراب، ای کرائم سالمة عن الهجنة. واحد آن عربی است . در صحاح است که «الابل العراب و الخیل العراب خلاف البخاتی و البراذین ».<br /></font></div>'),
(181962, 'عراب', '<span class=\"hlight\">عراب .</span> <font color=\"DarkGreen\"><b>[ ع َرْ را ]</font></b> (ع ص ) سازنده ٔ غلاف پستان گوسفند. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نزد نصاری کفیل مورد اعتماد را گویند. و کفیله را عرابه گویند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عامل العرابات ؛ آنکه عرّابه سازد. این کلمه سریانی است . (از اقرب الموارد).<br /></font></div>'),
(181963, 'عرابات', '<span class=\"hlight\">عرابات .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عرابة؛ پستان بند گوسفند. (از اقرب الموارد).<br /></font></div>'),
(181964, 'عرابة', '<span class=\"hlight\">عرابة.</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ب َ ]</font></b> (ع اِ) فحش . <BR><font color=\"Blue\">◄</font> بدگوئی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اسم است اعراب را. (آنندراج ) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> فحش دهنده . (اقرب الموارد). ج، عرابات .<br /></font></div>'),
(181965, 'عرابة', '<span class=\"hlight\">عرابة.</span> <font color=\"DarkGreen\"><b>[ ع َرْ را ب َ ]</font></b> (اِخ ) عرابة طبی از اعمال عکا به ساحل شام است . (معجم البلدان ).<br /></font></div>'),
(181966, 'عرابد', '<span class=\"hlight\">عرابد.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب ِ ]</font></b> (ع ص ) دختر سپیدرنگ تازه بدن نازک و لرزان اندام . (منتهی الارب ).<br /></font></div>'),
(181967, 'عرابض', '<span class=\"hlight\">عرابض .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب ِ ]</font></b> (ع ص ) درشت و استوار. (منتهی الارب ). غلیظ. (از اقرب الموارد).<br /></font></div>'),
(181968, 'عرابه', '<span class=\"hlight\">عرابه .</span> <font color=\"DarkGreen\"><b>[ ع َرْ را ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ) ارابه . وسیله ٔ نقلیه ٔ ساده که با چرخ حرکت کند. عرابه ٔ مصریان شامل صندوقی بود که بر تیره ای از چوب یا آهن قرار داشت . چرخهایش نیز مانند چرخهای حالیه تیره دار نبود بلکه قطعه چوبی را مدور میکردند استوانه شکل نظیرقسمتی از تنه ٔ درخت و بجای چرخ استعمال مینمودند. ودر زمان سلف نه تنها برای جنگ بلکه برای مقاصدی استعمال میشد مثلاً در بازیهای یونانیان و رومیان نیز استعمال میشد و اولین دفعه که در کتاب مقدس نام عرابه برده شده است در حکایت یوسف است پس از آن درباره ٔ خروج بنی اسرائیل از مصر است و نخستین کس که آن را در عساکر اسرائیل داخل نمود داود بود و سلیمان را نیز عرابه بود و شهرهای حصارداری برای آنها مقرر داشت از آن پس یکی از ملزومات عسکریه گردید و آنچه از آیات کتاب مقدس مستفاد میشود اسب عرابه و خود عرابه را از مصر می آوردند اما عرابه ٔ مصری دارای نشیمن گاه بود بهیئت نیم دائره متشکل و از پائین بر زبر چوبی که در طرفینش دارای دو چرخ بود قرار داشت و این عرابه ها را ازآهن نیز درست میکردند و سطح آن از ریسمان مشبک ترتیب میافت و چوبی طویل از جلو عرابه امتداد یافته بود که باسبان میپیوست و جعبه کمان و ترکش را نیز در پهلوی عرابه میساختند. عرابه های آسوریان نیز بر همین شکل بود و گاهی اوقات سه اسب به عرابه می بستند. رؤسای عرابه ها صاحبان رتبه و درجه ٔ عالی بودند. (از قاموس کتاب مقدس ). و رجوع به ارابه در این لغت نامه شود.<br /></font></div>'),
(181969, 'عرابه رو', '<span class=\"hlight\">عرابه رو.</span> <font color=\"DarkGreen\"><b>[ ع َرْ را ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رُ ]</font></b> (ص مرکب ) (راه ...) جاده ای که در آن عرابه سیر تواند کرد. راهی که در آن عرابه تواند رفتن . مقابل راه مالرو و پیاده رو و بزرو و جز آنها. رجوع به ارابه رو شود.<br /></font></div>'),
(181970, 'عرابه چی', '<span class=\"hlight\">عرابه چی .</span> <font color=\"DarkGreen\"><b>[ ع َرْ را ب َ<span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (ص مرکب ) آنکه عرابه راند. متصدی و راننده که عرابه (ارابه ) را هدایت کند. رجوع به عرابه شود.<br /></font></div>'),
(181971, 'عرابه کش', '<span class=\"hlight\">عرابه کش .</span> <font color=\"DarkGreen\"><b>[ ع َرْ را ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب ) آنکه عرابه از جای بجای نقل مکان دهد. حیوانی که عرابه حمل کند و از نقطه ای به نقطه ٔ دیگر برد. رجوع به ارابه کش شود.<br /></font></div>'),
(181972, 'عرابی', '<span class=\"hlight\">عرابی .</span> <font color=\"DarkGreen\"><b>[ ع َ بی ی ]</font></b> (اِخ ) محمدبن عبداﷲبن احمدبن شعیب بن ابی عرابة العرابی . ساکن مصر بود. وی نیک کردار و مورد قبول عام و خاص بود. در شعبان سال <span class=\"hlight\" dir=\"rtl\">٣١٥</span> هَ . ق . درگذشت . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٠</span>).<br /></font></div>'),
(181973, 'عرابی', '<span class=\"hlight\">عرابی .</span> <font color=\"DarkGreen\"><b>[ ع َ بی ی ]</font></b> (اِخ ) ابوعلی المقدام بن ثهل بن المقدام الکنانی العرابی ثم المصری ولد بعرابه طبی . به سال <span class=\"hlight\" dir=\"rtl\">٥١١</span> هَ . ق . متولد شد و به مصر سکونت گزید، روایت حدیث میکرد. (معجم البلدان ).<br /></font></div>'),
(181974, 'عرابی', '<span class=\"hlight\">عرابی .</span> <font color=\"DarkGreen\"><b>[ ع َ بی ی ]</font></b> (اِخ ) ابن معاویة ابوزمعة الحضرمی گفته شده است کنیت او ابوربیعة است از سلیمان بن زیاد حضرمی و عبداﷲ بن هبیرة السبائی روایت دارد. بخاری در تاریخ این کلمه را به غین معجمه ضبط کرده است لکن دارقطنی گوید این کلمه به عین مهمله است . (از اللباب فی تهذیب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٠</span>).<br /></font></div>'),
(181975, 'عرابی پاشا', '<span class=\"hlight\">عرابی پاشا.</span> <font color=\"DarkGreen\"><b>[ ع َ بی ی ]</font></b> (اِخ ) یکی از بزرگان و رجال سیاست و از زعمای حزب قومی مصری بوده است که به مخالفت با نفوذ کشورهای غربی در مصر مخصوصاً دولت انگلستان قیام کرد و در راه آزادی اعراب فداکاریها نمود. (<span class=\"hlight\" dir=\"rtl\">١٨٣٩</span> - <span class=\"hlight\" dir=\"rtl\">١٩١١</span> م .). (از اعلام المنجد).<br /></font></div>'),
(181976, 'عرات', '<span class=\"hlight\">عرات .</span> <font color=\"DarkGreen\"><b>[ ع َرْ را ]</font></b> (ع ص ) درخشنده و لرزنده و جنبنده از نیزه و برق . (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(181977, 'عرات', '<span class=\"hlight\">عرات .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) برهنگان . ج ِ عاریة. (منتهی الارب ) (آنندراج ). و رجوع به عراة شود.<br /></font></div>'),
(181978, 'عراج', '<span class=\"hlight\">عراج .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) کفتار. (منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(181979, 'عراجلة', '<span class=\"hlight\">عراجلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ج ِ ل َ ]</font></b> (ع اِ) ج ِ عرجلة. (از ناظم الاطباء). رجوع به عرجلة شود.<br /></font></div>'),
(181980, 'عراجین', '<span class=\"hlight\">عراجین .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عُرجون . (منتهی الارب ) (آنندراج ). رجوع به عرجون شود.<br /></font></div>'),
(181981, 'عراد', '<span class=\"hlight\">عراد.</span> <font color=\"DarkGreen\"><b>[ ع َرْ را ]</font></b> (ع ص ) کسی که عراده میسازد تا با آن کارکند. در انساب است که این اصطلاح عراده سازی را میرساند و آن آلت سنگ انداختن از قلاع میباشد. (سمعانی ).<br /></font></div>'),
(181982, 'عراد', '<span class=\"hlight\">عراد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) گیاه سطبر. (آنندراج ). گیاهی است سخت . چوب درختی است . (از اقرب الموارد).<br /></font></div>'),
(181983, 'عراد', '<span class=\"hlight\">عراد.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) شهری است در حدود یهودیه که شهریارش بنی اسرائیل را از عبور از مملکتش مانع گشت و برخی از ایشان را به اسیری برد بدین لحاظ اهالی عراد به لعنت خدای گرفتار شدند و شهر ایشان خراب گردید و پس از این واقعه اسم شهر را به حرمه تبدیل نمودند که قصد از محرومی است . (از قاموس کتاب مقدس ).<br /></font></div>'),
(181984, 'عراد', '<span class=\"hlight\">عراد.</span> <font color=\"DarkGreen\"><b>[ ع َرْ را ]</font></b> (اِخ ) ابوعیسی احمدبن محمدبن موسی البغدادی المعروف به ابن العرادی از اباهمام ولیدبن شجاع و یحیی بن اکثم و جز آنان حدیث شنید و ابوبکر الشافعی و جز او از وی روایت دارند. وی به سال <span class=\"hlight\" dir=\"rtl\">٢٢٥</span> هَ . ق . زاده شد وبه سال <span class=\"hlight\" dir=\"rtl\">٣٠٢</span> هَ . ق . بمرد. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٠</span>).<br /></font></div>'),
(181985, 'عرادات', '<span class=\"hlight\">عرادات .</span> <font color=\"DarkGreen\"><b>[ ع َرْ را ]</font></b> (ع اِ) ج ِ عرادة. عراده ها. منجنیقها <span class=\"hlight\">:</span> و عرادات بر جوانب قلعه راست کردند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٤٢</span>).<br /></font></div>'),
(181986, 'عراده', '<span class=\"hlight\">عراده .</span> <font color=\"DarkGreen\"><b>[ ع َرْ را دَ ]</font></b> (ع اِ) نوعی از آلات جنگ و قلعه گیری است و آن آلتی باشد کوچکتر از منجنیق که بدان سنگ بر سر خصم اندازند. (غیاث اللغات ). و آن را حصارگشای نیز گویند <span class=\"hlight\">:</span> <br />نترسد ز عراده و منجنیق <br />نگهبان نباید ورا جاثلیق .<br /> <font color=\"Red\">فردوسی .</font><br />ز عراده و منجنیق و ز گرد<br />زمین نیلگون شد هوا لاجورد.<br /> <font color=\"Red\">فردوسی .</font><br />به هر گوشه عراده برساختند<br />همه ریگ رخشنده انداختند.<br /> <font color=\"Red\">اسدی .</font><br />و منجنیقها و عراده ها بساخت . (تاریخ بخارا ص <span class=\"hlight\" dir=\"rtl\">٨٤</span>).<br />نه عراده بر گرد اوره شناس <br />نه از گردش منجنیقش هراس .<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> گردونه . گردون . گردون دوچرخه . گردون بارکشی . (ناظم الاطباء).<br /></font></div>'),
(181987, 'عراده انداز', '<span class=\"hlight\">عراده انداز.</span> <font color=\"DarkGreen\"><b>[ ع َرْ را دَ اَ ]</font></b> (نف مرکب ) آنکه با عراده جنگ کند و بدان سنگ اندازد <span class=\"hlight\">:</span> بانصر و بوالحسن خلف با عراده انداز گفتند پنجاه دینار و دو پاره جامه بدهیم . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٧٣</span>). غوری عراده انداز زر و جامه بستد. (تاریخ بیهقی ایضاً ص <span class=\"hlight\" dir=\"rtl\">٤٧٤</span>).<br /></font></div>'),
(181988, 'عرادیس', '<span class=\"hlight\">عرادیس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) هر محل اجتماع دو استخوان مردم و جز آن . (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(181989, 'عرار', '<span class=\"hlight\">عرار.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) گناه . <BR><font color=\"Blue\">◄</font> جنایت . (از اقرب الموارد).<br /></font></div>'),
(181990, 'عرار', '<span class=\"hlight\">عرار.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) هر چیزی که به سوی چیزی بازگردد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زنان که همواره پسر زایند. <BR><font color=\"Blue\">◄</font> گیاه خوشبوی یا آن بهار دشتی است زردرنگ . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سختی . <BR><font color=\"Blue\">◄</font> بلندی . <BR><font color=\"Blue\">◄</font> مهتری . <BR><font color=\"Blue\">◄</font> اصل چیزی . <BR><font color=\"Blue\">◄</font> زشتی خوی . <BR><font color=\"Blue\">◄</font> قصاص . (منتهی الارب ) (آنندراج ). هر چیزی که در ازای چیزی کشته شود. <BR><font color=\"Blue\">◄</font> قتل کشنده . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> قود. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) رودباری است . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (ع ص ) بچه ای که زود شیر ترک کند. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) گلی است که آن را گل گاوچشم و بابونه ٔ گاو گویند و به عربی عین البقر و به یونانی قربانیون خوانند. (برهان ).<br /></font></div>'),
(181991, 'عرار', '<span class=\"hlight\">عرار.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام ماده گاوی است . (منتهی الارب ) (اقرب الموارد). و عرب در مثل گوید: بأت عرار بکحل، دو حریف را گویند که هر دو همزور باشند و گویند: آن دو گاو چندان همزور بودند که یکدیگر را سُرو زدند تا هر دو بمردند. و این مثل را درباره ٔ دو حریف برابر گویند. (ناظم الاطباء) (از اقرب الموارد).<br /></font></div>'),
(181992, 'عرار', '<span class=\"hlight\">عرار.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) سختی جرب . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (مص ) بانگ کردن شترمرغ . (تاج المصادر).<br /></font></div>'),
(181993, 'عرار', '<span class=\"hlight\">عرار.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) موضعی است در دیار باهله از سرزمین یمامة. (معجم البلدان ).<br /></font></div>'),
(181994, 'عراز', '<span class=\"hlight\">عراز.</span> <font color=\"DarkGreen\"><b>[ ع ُرْ را ]</font></b> (ع ص، اِ) ج ِ عارز. (از اقرب الموارد). غیبت کنندگان . (منتهی الارب ). غیبت کنندگان از مردم . (ناظم الاطباء).<br /></font></div>'),
(181995, 'عراز', '<span class=\"hlight\">عراز.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) معارزة. با همدیگر ستیهیدن . <BR><font color=\"Blue\">◄</font> دور دور یک جانب بودن . <BR><font color=\"Blue\">◄</font> خلاف کردن و با هم خشم گرفتن . <BR><font color=\"Blue\">◄</font> گرفته و ترنجیده گردیدن . (ناظم الاطباء).<br /></font></div>'),
(181996, 'عراز', '<span class=\"hlight\">عراز.</span> <font color=\"DarkGreen\"><b>[ع ِ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ) (ناظم الاطباء).<br /></font></div>'),
(181997, 'عرازیل', '<span class=\"hlight\">عرازیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) قوم عرازیل، گروه متفق و هم مشرب در دزدی . (از اقرب الموارد).<br /></font></div>'),
(181998, 'عراس', '<span class=\"hlight\">عراس .</span> <font color=\"DarkGreen\"><b>[ ع َرْ را ]</font></b> (ع ص ) شتربچه فروش . (منتهی الارب ).<br /></font></div>'),
(181999, 'عراس', '<span class=\"hlight\">عراس .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) رسنی که بدان گردن شتر را بر بازوی وی بندند. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(182000, 'عراص', '<span class=\"hlight\">عراص .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ عَرصة. (منتهی الارب ). رجوع به عرصه شود <span class=\"hlight\">:</span> حق تعالی عراص عالم را ببقای ذات پادشاه عادل و رونق اسلام ودین حنفی آراسته گرداند. (جهانگشای جوینی ). ارباب آن به آثار عدل شامل وجود فائض او مغمور شدند و عراص آن به آوازه ٔ انصاف وافر معمور. (جهانگشای جوینی ).<br /></font></div>'),
(182001, 'عراص', '<span class=\"hlight\">عراص .</span> <font color=\"DarkGreen\"><b>[ ع َرْ را ]</font></b> (ع ص ) ابر با رعد و برق . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> ابر بسیاردرخش و پراکنده و مضطرب . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> برق مضطرب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نیزه ٔ لرزان . <BR><font color=\"Blue\">◄</font> شمشیر لرزان . (از اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(182002, 'عراصم', '<span class=\"hlight\">عراصم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ص ِ ]</font></b> (ع اِ) شیر بیشه . (ناظم الاطباء).<br /></font></div>'),
(182003, 'عراصیف', '<span class=\"hlight\">عراصیف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ)ج ِ عرصوف . <BR><font color=\"Blue\">◄</font> ج ِ عرصاف . (ناظم الاطباء).<br /></font></div>'),
(182004, 'عراض', '<span class=\"hlight\">عراض .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ارمغان و آنچه به اهل فرستند. (منتهی الارب ). تحفه و هدایا. (از غیاث اللغات ) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آنچه خواربار کن اول پیش کند تا در خواربار او رغبت نمایند. ج، عراضات .<br /></font></div>'),
(182005, 'عراض', '<span class=\"hlight\">عراض .</span> <font color=\"DarkGreen\"><b>[ ع ُ]</font></b> (ع ص ) پهناور. (از اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(182006, 'عراض', '<span class=\"hlight\">عراض .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) داغی یا خطی است پهناور. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سرین ستور. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آهنی است که سم شتر را به وی داغ کنند تا اثر وی شناخته شود. <BR><font color=\"Blue\">◄</font> کرانه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نیزه . <BR><font color=\"Blue\">◄</font> ابر با رعد و برق . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> شکاف . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> عراض الحدیث، معظم و معتبر آن . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بعیر ذوعراض ؛ شترکه با دهن با درخت یا خار معارضه کند. (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> فرزند که پدر خود نشناسد. (از اقرب الموارد) (منتهی الارب ). ج، عُرض .<br /></font></div>'),
(182007, 'عراعر', '<span class=\"hlight\">عراعر.</span> <font color=\"DarkGreen\"><b>[ ع َ ع ِ ]</font></b> (ع اِ) ج ِ عُراعر. <BR><font color=\"Blue\">◄</font> کرانه های کوهان . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِخ ) موضعی است که از آن نمک گیرند و بدو نسبت دهند. یقال : ملح عُراعِری ّ. (از اقرب الموارد).<br /></font></div>'),
(182008, 'عراعر', '<span class=\"hlight\">عراعر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ع ِ ]</font></b> (اِخ ) نام موضعی است در شعر اخطل . و گفته شده است نام آبی است شور مر بنی عمیره را و صاحب تکملة گوید: هی ارضی سبخة. و گفته شده است آب تلخی است به عدنه در شمال شربة. و نصر گوید عراعرآبی است مر کلب را بناحیة الشام . (معجم البلدان ).<br /></font></div>'),
(182009, 'عراعر', '<span class=\"hlight\">عراعر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ع ِ ]</font></b> (ع ص ) بزرگ قدر و شریف . (منتهی الارب ) (از اقرب الموارد) (آنندراج ). <BR><font color=\"Blue\">◄</font> مهتر. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> شتر فربه . (از اقرب الموارد) (آنندراج ).<br /></font></div>'),
(182010, 'عراف', '<span class=\"hlight\">عراف .</span> <font color=\"DarkGreen\"><b>[ ع َرْ را]</font></b> (ع ص ) بسیار شناسنده . <BR><font color=\"Blue\">◄</font> منجم . (از اقرب الموارد). اخترگوی . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> کاهن و فالگوی . (منتهی الارب ). و گفته شده است عراف آن باشد که از گذشته و آینده خبر دهد. (اقرب الموارد).جاحظ گوید عراف پائین تر از کاهن است . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> طبیب . (اقرب الموارد). ج، عرافون .<br /></font></div>'),
(182011, 'عرافة', '<span class=\"hlight\">عرافة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ف َ ]</font></b> (ع اِمص ) عِرافت . عریفی کردن . رجوع به عریف شود.<br /></font></div>'),
(182012, 'عرافة', '<span class=\"hlight\">عرافة.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع مص ) عریف گردیدن . (منتهی الارب ) (آنندراج ). رجوع به عرافت شود.<br /></font></div>'),
(182013, 'عرافت', '<span class=\"hlight\">عرافت .</span> <font color=\"DarkGreen\"><b>[ ع ِ ف َ ]</font></b> (ع اِمص ) (علم ...) عرافة. در اصطلاح استدلال به پاره ای از حوادث گذشته است بر حوادث آینده به مناسبت یا مشابهت خفیه که بین آنهاست و یا اختلاط و ارتباطی که با یکدیگر دارند. رجوع به کهانت شود. عمل عراف نوعی است از کهانت و مخصوص بامور گذشته است و برخی گویند عرافة استدلال از حوادث حالیه بر حوادث آتیه است بمناسبت یا مشابهت . (از بلوغ الارب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٤</span>).<br /></font></div>'),
(182014, 'عرافج', '<span class=\"hlight\">عرافج .</span> <font color=\"DarkGreen\"><b>[ ع َ ف ِ ]</font></b> (ع اِ) ریگستانهاست که راه ندارد. (اقرب الموارد) (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(182015, 'عرافی', '<span class=\"hlight\">عرافی .</span> <font color=\"DarkGreen\"><b>[ ع َرْ را ]</font></b> (حامص ) عرّاف بودن .<br /></font></div>'),
(182016, 'عرافی', '<span class=\"hlight\">عرافی .</span> <font color=\"DarkGreen\"><b>[ ع َرْ را فی ی ]</font></b> (اِخ ) ابوسلیمان عبداﷲبن محمدبن محمدالعرافی . از شیخ ابالحسن روایت کند و حسن بن زیاد از او روایت دارد. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٠</span>).<br /></font></div>'),
(182017, 'عرافیص', '<span class=\"hlight\">عرافیص .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) عرفاص . رجوع به عرفاص شود.<br /></font></div>'),
(182018, 'عراق', 'دوال استخوان با گوشت . <BR><font color=\"Blue\">◄</font> آب صافی . <BR><font color=\"Blue\">◄</font> باران بسیار. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> قطر طناب تنها. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> باقی مانده ٔ گیاه ترش . (منتهی الارب ). بقایای حمض . (از اقرب الموارد). باقی مانده ٔ شور گیاه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> گرداگرد ناخن . (اقرب الموارد)(منتهی الارب ). <BR><font color=\"Blue\">◄</font> کِفاف گوش . اطراف گوش . (ناظم الاطباء) (اقرب الموارد) (منتهی الارب ). و من الاذن کفافها. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیرامون سرای . <BR><font color=\"Blue\">◄</font> درز محیط سفره . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه در شکم است بالای ناف به پهنای شکم . ج، أعرقة، عُرُق . (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اطراف نهر از نزدیک آن تا منتهای آن . (اقرب الموارد). ج، عُرق و عُرُق . (منتهی الارب ).<br /><span class=\"hlight\">عراق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) کرانه ٔ دریا بدرازا. ج، عُرق وعُرُق و اعرقه . (از اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> درون پر مرغ . (منتهی الارب ). جوف الریش . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> کناره ٔ آب . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> درز، دو تا دوخته در زیر توشه دان و مشک . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> پوست پاره که بر ملتقای دو چرم در اسفل توشه دان دوزند. دوال که بدان درزهای مشک را فراگیرند. <br /></font></div>'),
(182019, 'عراق', '<span class=\"hlight\">عراق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) محله ٔ بزرگی است به شهر اخمیم مصر. (معجم البلدان ).<br /></font></div>'),
(182020, 'عراق', '<span class=\"hlight\">عراق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) کشور عراق یا عراق عرب در حال حاضر از ممالک، واقع در جزیرة العرب و همجوار کشور ایران است و حدود آن : از شمال، ترکیه، و از شرق، ایران و از غرب، سوریه و از جنوب، نجد و خلیج فارس است و در حدود <span class=\"hlight\" dir=\"rtl\">٤٤٢</span>، <span class=\"hlight\" dir=\"rtl\">٤٤٢</span> هزارگز مساحت و <span class=\"hlight\" dir=\"rtl\">٧</span> میلیون جمعیت دارد. این سرزمین از دو قسمت تشکیل شده است، یک قسمت کوهستانی و قسمت دیگر بیابان سهل و هموار. در حدود یک هشتم آن کوهستانی است و رودها و انهار و غیره در این ناحیه ٔ کوهستانی است و اغلب این قسمت کردنشین است و مردم آن به کار گله داری و احیاناً زراعت اشتغال دارند و در حدود <span class=\"hlight\" dir=\"rtl\">٦٠٠</span> هزار نفر مردمی باهوش و مستعد و جنگجویند و از لحاظ آداب و عادت و رسوم و زبان آریائی و از اقوام مادی میباشند. در «سرزمین خلافتهای شرقی » و «الموسوعه » آمده است که بین النهرین بدو قسمت مجزا تقسیم شده است قسمت شمالی یعنی سرزمین قدیم آشور و قسمت جنوبی . عربها قسمت شمالی بین النهرین را جزیره و قسمت جنوبی را عراق نامیده اند و حدود آن از بلاد شرق اردن و از کشورهای آسیائی است .بنابر گفته ٔ فرید وجدی <span class=\"hlight\" dir=\"rtl\">٧٥٠</span> کیلومتر طول و سیصد کیلومتر عرض دارد و بگفتار المنجد <span class=\"hlight\" dir=\"rtl\">٥٠٠</span>، <span class=\"hlight\" dir=\"rtl\">٤٥٣</span> کیلومتر مربع است و سکنه ٔ آن در حدود <span class=\"hlight\" dir=\"rtl\">٥</span> میلیون نفرند و حدود آن شرقاً ایران، شمالاً ترکیه، غرباً سوریه و کشور هاشمی اردن و جنوباً کشور سعودی و کویت و خلیج فارس است و در جهت مناطق شرقی کوههای بلند و مرتفعی است که مهمترین آنها کوه های کردستان است . بجز آن منطقه بقیه اراضی وسیعی است که قسمتی از آن ریگ زارست و قسمتی زمین قابل زرع و سرسبز مانند نواحی فرات و دجله و شطعرب .<br />وضع جغرافیائی عراق قدیم : عراق در دوره های گذشته شامل دو قسمت یا مملکت بوده است : بابل، کلده . در سال <span class=\"hlight\" dir=\"rtl\">٣٣</span> قبل از میلاد مسیح اسکندر مقدونی بر آن حکومت میکرد و سپس به سال <span class=\"hlight\" dir=\"rtl\">٣٠٢</span> م . حکومت ساسانیان بر آن خطه مستقر گردید و همچنان مدتها بر آن سرزمین حکومت کردند و هم اکنون آثاری از آن دوران باقی است که از راه حفاری و غیره به دست آمده است .<br />پس از ظهور اسلام و فتوحاتی که نصیب مسلمانان شد عراق نیز مانند بسیاری از کشورهای این منطقه در تسلط و استیلای مسلمین درآمد و شاید شهرت آن به عراق بنا بر گفته ٔ فرید و جدی از همان زمان باشد از طرفی یاقوت گوید: عرض عراق از جهت خط استواء <span class=\"hlight\" dir=\"rtl\">٣١</span> درجه است و طول آن <span class=\"hlight\" dir=\"rtl\">٧٥</span> درجه و <span class=\"hlight\" dir=\"rtl\">٣٠</span> دقیقه است و دورترین شهرهای آن در عرض از خط استواء عکبر است بر طرف غربی دجله و عرض آن <span class=\"hlight\" dir=\"rtl\">٣٢</span> درجه و <span class=\"hlight\" dir=\"rtl\">٣٠</span> دقیقه است و آن آخرین منطقه است که در اقلیم سوم از عراق واقع است و بعداز عُکبرا عراق داخل در اقلیم سوم شود تا حلوان و عرض آن <span class=\"hlight\" dir=\"rtl\">٣٤</span> درجه است که دسکرةالملک جلولاء، و قصر شیرین باشد و بیشتر آن، واقع در اقلیم سوم است مانند قادسیه و حلوان و عذیب نیز از اقلیم سوم اند، حدود آن مورد اختلاف است . حمداﷲ مستوفی گوید: در مسالک است که عراق عرب را دل ایران شهر خوانده اند و چون دل سلطان وجود است ابتداء بشرح آن اولی بود، و در صورالاقالیم گوید که چون عراق عرب در قبله ٔ ایران زمین افتاده است آن را مقدم داشتن اولیتر است ... حدودش تا بیابان نجدو دریای فارس و کردستان پیوسته است . طولش از تکریت تا عبادان صد و بیست و پنچ فرسنگ و عرض از عقبه ٔ حلوان تا قادسیه محاذی بیابان نجد هشتاد فرسنگ و مساحتش ده هزار فرسنگ است، شهرهای آن عبارتند از بغداد. کوفه . بابل . بصره . تکریت، حلوان، حیره و سامره . (از نزهةالقلوب ص <span class=\"hlight\" dir=\"rtl\">٢٨</span> و <span class=\"hlight\" dir=\"rtl\">٤٣</span>). در کتاب سرزمین های خلافت شرقیه آمده است : طبیعت جلگه ٔ پهناور بین النهرین را که فرات و دجله در آن جاری است دو قسمت کرده است قسمت شمالی بین النهرین را جزیره و قسمت جنوبی را عراق مینامیدند. عراق بمعنای کناردریا و بمعنی ساحل نیز آمده است ولی معلوم نیست اصل این کلمه چه بوده است . اصولاً سرزمین رسوبی را اعراب سواد یعنی خاک سیاه نامیده اند. و رفته رفته کلمه ٔ سواد با عراق یکی شد و عبارت بود ازتمام سرزمین بابل . سرحد بین جزیره و عراق در دوره های مختلف تغییر پیدا میکرد در قدیم حد آن خطی بود بطرف شمال از انبار، واقع در ساحل فرات به تکریت در ساحل دجله و بعداً خطی قرار دادند که از تکریت تقریباً بسمت باختر کشیده میشد و بدین ترتیب بسیاری از شهرهای ساحل فرات را که در شمال انبار قرار داشت داخل در منطقه ٔ عراق نمودند. دجله در تورات بنام دیگلات آمده است . چون خلافت از امویان به عباسیان رسید اوضاع چنین اقتضا کرد که پایتخت جدیدی برای دولت تازه انتخاب کنند از این جهت خلیفه ٔ دوم عباسی بغداد را در کنار دجله درست کرد و بعد از مدتی این پایتخت جدید رونق یافت و مرکز خلافت عباسیان شد. در قرون وسطی اوضاع طبیعی عراق با امروز بسیار تفاوت داشت و تغییراتی در مجرای دجله و فرات حاصل گشته که موجب تغییرات این سرزمین شده است . اولین نهری که از فرات جدا میشد و به دجله میریخت نهر عیسی بود که در سال <span class=\"hlight\" dir=\"rtl\">١٤٥</span> هَ . ق . منصور خلیفه عباسی بالای مصب آن در دجله شهر مدور را ساخت که هسته ٔ شهر بغداد شد. از جمله مناطق مهم عراق مدائن بود که ظاهراً از هفت شهر تشکیل میشد. شهر کهنه یعنی طیسفون، اسبانبر، رومیه، بهرسیر که اصل آن اردشیر است و ساباط که ایرانیان آن را بلاس آباد میگفتند. کاخ ساسانیان که هنوز آثاری از آن هست و ایوان کسری نام نهاده اند یکی از آثار مهم ایرانی است . در اواسط قرن دوم هجری منصور مصمم شد که طاق کسری را خراب کند و سنگ و آجر آن را در بنای جدید یعنی بغداد بکار برد لکن منصرف شد. مدائن امروزه که خرابه ای بیش نیست در قرن چهارم شهری پر جمعیت و زیبا بوده است که جغرافیانویسان عجایبی در مورد آن نوشته اند. از جمله شهرهای مهم دیگر عراق قدیم واسط و بطایح که تقریباً ایالت مهمی بوده است و بصره و جز آنها بوده است که بعضی هنوزهم اعتبار خود را حفظ کرده است و بعضی ویران شده است . عربها بین النهرین را بدو ناحیه تقسیم میکردند. یکی ناحیه ٔ سفلی و دیگری ناحیه ٔ علیا. بین النهرین سفلی را عراق مینامیدند و مرز شمالی آن خطی بود از خاور به باختر که از دجله شروع میگردید و به فرات ختم میشد. در زمان عباسیان بغداد بزرگترین شهر عراق بود ولی یک قرن پیش از بنای بغداد سلسله ٔ مسلمانها پس از فتح عراق سه شهر بزرگ عربها که آن را دجیل نامیده اند بنا کردند که واسط، کوفه و بصره باشد این سه شهر تا چندین قرن رونق داشتند. بین النهرین علیا را عربها جزیره مینامیدند زیرا که دشتهای پهناور از آب های فرات ودجله ٔ علیا و جویها و نهرهایی که در جنوب آن دشتهای پهناور به رود مزبور می پیوستند احاطه شده که دو شط بزرگ را بهم وصل میکرد امتداد داشت . در مشرق جزیره یا بین النهرین علیا ایالات آذربایجان واقع بود و از بالا به رود ارس و از پائین به سفیدرود که هر دو به دریای خزر میریزند محدود میگردید از آثار این مناطق ارومیه است . در اقرب الموارد آمده : عراق بلادی است مشهوراز عبادان تا موصل در طول و از قادسیه تا حلوان در عرض و عراق در لغت بمعنی کناره ٔ دریاست و چون عراقین عرب و عجم بر کنار دریااند عراق گویند.<br />مردم عراق : اقوام مختلف این سرزمین عبارتند از عرب و ترک و کرد و فارس . در سنوات متمادی عده ای مردم ایران بدانجا مهاجرت کرده اند و بواسطه ٔ وجود اعتاب مقدسه شیعیان به آن سرزمین مسافرت میکنند. بر روی هم <span class=\"hlight\" dir=\"rtl\">٧٠</span> درصد عرب و <span class=\"hlight\" dir=\"rtl\">٢٠</span> درصد کرد و <span class=\"hlight\" dir=\"rtl\">٤</span> درصد فارس و <span class=\"hlight\" dir=\"rtl\">٥</span> درصد ترک و مردم دیگرند. مذاهب مختلفی وجود دارد مانند اسلام، یهود، مسیحی، و اقلیتهای دیگر آسوری و یزیدیه و صابئیه . در این سرزمین با آنکه زبان رسمی عربی است معذلک بزبان کردی، ترکی و فارسی نیز صحبت میشود و زبانهای دیگر نیز مانند آرامی، عبری و سریانی هست که ویژه ٔ معابد است لکن تمام این ادیان و زبانها در زبان رسمی که عربی است مستهلک گردیده است و مذهب همان اسلام است . شهرهای مهم آن بغداد، مرکز حکومت کشور و کربلا، نجف، موصل، کرکوک، بصره، حله، کوفه، خانقین، سلیمانیه، و جز آنهاست .<br />نهرها: در این سرزمین دو نهربزرگ وجود دارد، یکی دجله و دیگری فرات، دجله در طول <span class=\"hlight\" dir=\"rtl\">١٨٠٠</span> کیلومتر و فرات در <span class=\"hlight\" dir=\"rtl\">٢٣٥٠</span> کیلومتر جریان دارد. نهرهای کوچک بسیار نیز وجود دارد و دو دریاچه ٔ کوچک نیز مانند دریاچه ٔ الحمار بمساحت <span class=\"hlight\" dir=\"rtl\">٥٢٠٠</span> کیلومتر مربع در جنوب بین بصره و ناصریه و دریاچه ٔ حیاتیه بمساحت <span class=\"hlight\" dir=\"rtl\">١٤٠</span> کیلومتر مربع بین رمادی و فلوجه و اهواز وجود دارد.<br />راهها: سه راه آهن بزرگ در عراق وجود دارد. اول بین بغداد و بصره که دو رشته، بموازات هم است، دوم بین بغداد و کرکوک و سوم بین بغداد و موصل و راههای شوسه عبارتند: <span class=\"hlight\" dir=\"rtl\">١</span> - راه بغداد - کویت - عماره - بصره . <span class=\"hlight\" dir=\"rtl\">٢</span> - بغداد - کرکوک - اربل - موصل . <span class=\"hlight\" dir=\"rtl\">٣</span> - بغداد - سامرا - تکریت - موصل . <span class=\"hlight\" dir=\"rtl\">٤</span> - بغداد - نجف - حائل - مدینه . <span class=\"hlight\" dir=\"rtl\">٥</span> - بغداد - رمادی - رطبة - دمشق . <span class=\"hlight\" dir=\"rtl\">٦</span> - بغداد یعقوبیه - خانقین .<br />ملتها و دولتها که بر عراق حکومت داشته اند <span class=\"hlight\">:</span> <br />ملتهای عراق عبارتند: <span class=\"hlight\" dir=\"rtl\">١</span>- سومریها و اکدیها از <span class=\"hlight\" dir=\"rtl\">٤٥٠٠</span> ق . م . تا <span class=\"hlight\" dir=\"rtl\">٢٣٠٠</span> ق . م . که بر قسمتی از عراق حکومت داشتند. <span class=\"hlight\" dir=\"rtl\">٢</span>- عیلامیون و دولت حمورابی از <span class=\"hlight\" dir=\"rtl\">٢٣٠٠</span> ق . م . تا <span class=\"hlight\" dir=\"rtl\">١٨٠٠</span> ق . م . که در نواحی خوزستان و شوشتر و جز آن و بعدها قسمتی از عراق فعلی فرمانروائی کردند. <span class=\"hlight\" dir=\"rtl\">٣</span>- بابلیان از <span class=\"hlight\" dir=\"rtl\">١٨٠٠</span> ق . م . تا <span class=\"hlight\" dir=\"rtl\">١٣٠٠</span> ق . م . <span class=\"hlight\" dir=\"rtl\">٤</span>- پادشاهان فارس و سلاطین ایران و ساسانیان که حکومتشان تا <span class=\"hlight\" dir=\"rtl\">٦٣٩</span> م . بطول انجامید. <span class=\"hlight\" dir=\"rtl\">٥</span>- خلفاءراشدین از <span class=\"hlight\" dir=\"rtl\">١٦</span> تا <span class=\"hlight\" dir=\"rtl\">٤٠</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">٦</span>- امویان از <span class=\"hlight\" dir=\"rtl\">٤١</span> تا <span class=\"hlight\" dir=\"rtl\">١٣٣</span>هَ . ق . <span class=\"hlight\" dir=\"rtl\">٧</span>- عباسیان از <span class=\"hlight\" dir=\"rtl\">١٣٢</span> تا <span class=\"hlight\" dir=\"rtl\">٦٥٦</span> هَ . ق . (آل بویه و سلجوقیان ). <span class=\"hlight\" dir=\"rtl\">٨</span>- ایلخانیان از <span class=\"hlight\" dir=\"rtl\">٦٥٦</span> هَ . ق . تا <span class=\"hlight\" dir=\"rtl\">٧٣٨</span> هَ. ق . <span class=\"hlight\" dir=\"rtl\">٩</span>- جلائریان از <span class=\"hlight\" dir=\"rtl\">٧٣٨</span> تا <span class=\"hlight\" dir=\"rtl\">٨١٣</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">١٠</span>- قره قوینلو و آق قوینلو از <span class=\"hlight\" dir=\"rtl\">٨١٣</span> تا <span class=\"hlight\" dir=\"rtl\">٩١٤</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">١١</span>- صفویان از <span class=\"hlight\" dir=\"rtl\">٩١٤</span> تا <span class=\"hlight\" dir=\"rtl\">٩٤١</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">١٢</span>- فترت و انتقال <span class=\"hlight\" dir=\"rtl\">١٠٣٣</span> تا <span class=\"hlight\" dir=\"rtl\">١٠٤٩</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">١٣</span>- عثمانیان از <span class=\"hlight\" dir=\"rtl\">١٠٤٩</span> تا <span class=\"hlight\" dir=\"rtl\">١٣٣٥</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">١٤</span>- انقلاب عراق <span class=\"hlight\" dir=\"rtl\">١٩١٨</span> م . حکومت موقت <span class=\"hlight\" dir=\"rtl\">١٩٢٠</span> م . (<span class=\"hlight\" dir=\"rtl\">١٣٣٩</span> هَ . ق .). عراق پس از جنگ اول جهانی مستقل شد و در تموز <span class=\"hlight\" dir=\"rtl\">١٩٢١</span> مجلس، ملک فیصل اول را به سلطنت برگزید و سپس غازی سلطان شد و بعد از آن فیصل دوم به سلطنت رسید، در سال <span class=\"hlight\" dir=\"rtl\">١٩٥٨</span> حکومت فیصل واژگون شد و در کشور عراق جمهوری اعلام گردید.<br />وضع اقتصادی عراق : عراق از لحاظ اقتصادی سرزمین متوسطی است . رود دجله قسمتهائی از آن سرزمین را مشروب میکند و از این راه مقداری زراعت غله میشود و نخلستانهای خرما که در کرانه ٔ دجله واقع است منبع درآمدی است برای این سرزمین و قسمت مهمی از لبنیات و گوشت آنها از ناحیه ٔ کردستان تأمین میشود. منبع نفت نیز یکی از پردرآمدترین منابعی است که عراق در اختیار دارد.<br />آب و هوای عراق : در مناطق کوهستانی هوای معتدل و بعضی مناطق سرد و در مناطق هموار و بیابان گرم است و بطور کلی عراق را می توان از مناطق حاره بحساب آورد. هوای شمال معتدل است و جنوب حار است . (از العراق قدیماً و حدیثاً تألیف سید عبدالرزاق حسینی و معجم البلدان ).<br /></font></div>'),
(182021, 'عراق', '<span class=\"hlight\">عراق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) عراق عجم <span class=\"hlight\">:</span> <br />اهل ع-راق در عرقند از حدیث تو<br />شروان به نام تست شرف وان و خیروان .<br /> <font color=\"Red\">خاقانی .</font><br />قدرش عراقیان چه شناسند کز سخن <br />چون آفتاب امیر خراسان شناسمش .<br /> <font color=\"Red\">خاقانی .</font><br />چو طالع مدد کرد و بخت اتفاق <br />گرفتم به بازوی دولت عراق .<br /> <font color=\"Red\">(بوستان ).</font><br />رجوع به عراق عجم شود.<br /></font></div>'),
(182022, 'عراق', '<span class=\"hlight\">عراق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) نام پرده ای است در موسیقی که به وقت چاشت سرایند. (آنندراج ) <span class=\"hlight\">:</span> <br />تا مطربان زنند لبینا و هفت خوان <br />در پرده ٔ عراق و سرزیر و سلمکی .<br /> <font color=\"Red\">میزانی (از حاشیه ٔ فرهنگ اسدی نخجوانی ).</font><br />عراقی وار بانگ از چرخ بگذاشت <br />به آهنگ عراق این بانگ برداشت .<br /> <font color=\"Red\">نظامی .</font><br />آه کز یاد ره و پرده ٔ عراق <br />رفت از یادم دَم تلخ فراق .<br /> <font color=\"Red\">مولوی .</font><br />رجوع به عراقی شود.<br /></font></div>'),
(182023, 'عراق', '<span class=\"hlight\">عراق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) استخوان که گوشت آن خورده شده باشد. (اقرب الموارد). استخوان با گوشت . (منتهی الارب ) <BR><font color=\"Blue\">◄</font> آب صافی . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> باران بسیار. (از اقرب الموارد).<br /></font></div>'),
(182024, 'عراق الغیث', '<span class=\"hlight\">عراق الغیث .</span> <font color=\"DarkGreen\"><b>[ ع ُ قُل ْ غ َ ]</font></b> (ع اِ مرکب ) گیاهی است که از پس باران روید. (منتهی الارب ).<br /></font></div>'),
(182025, 'عراق عجم', '<span class=\"hlight\">عراق عجم .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ ع َ ج َ ]</font></b> (اِخ ) ایالت جبال را در قرون وسطی غالب اوقات عراق عجم نامیده اند تا با عراق عرب اشتباه نشود. ایالات جبال (عراق عجم ) شهرهای بزرگی داشت از قبیل کرمانشاه، همدان و در شمال خاوری آن ری و در جنوب خاوری اصفهان بود. از جمله رودهای این ایالات رود کارون است . نواحی چهارگانه ٔ آن عبارت از قرمیسن یا کرمانشاهان، همدان و ری و اصفهان بود. سرزمینی است کوهستانی، پهناور که یونانیان آن را مدیا گفته اند و از باختر به جلگه های بین النهرین و از خاور به کویر بزرگ محدود است و بنام ایالت جبال معروف بوده است . از زمان سلجوقیان این نواحی را عراق عجم گفته اند که با عراق عرب که قسمت سفلای بین النهرین است اشتباه نشود بدان جهت که در نیمه ٔ دوم قرن پنجم سلجوقیان بر تمام مغرب ایران تسلط یافتند و همدان را پایتخت خود قرار دادند و استیلای آنها تا بین النهرین گسترش یافت و از مقر خلافت لقب سلطان العراقین به آنها اعطا شد و از آن مستفاد میشود که مقصود از عراق دومی ایالت جبال است که مقر حکومت سلجوقی بوده است و پس از حمله ٔ مغول اسم جبال بر این ناحیه دیگر استعمال نشد و چنانکه اشاره شد مهمترین مناطق عراق عجم کرمانشاه که عرب آن را قرمیسن نامیده اند بود و اصفهان و همدان . رجوع به کرمانشاهان و اصفهان و همدان و جغرافیای تاریخی سرزمینهای خلافت شرقیه ص <span class=\"hlight\" dir=\"rtl\">١٦٢</span> تا <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> شود. حمداﷲ مستوفی در نزهةالقلوب آرد: باب دوم در ذکر ولایت عراق عجم و آن نه تومان است و در او چهل پاره شهر است و اکثر بلادش هوای معتدل دارد. و بعضی به گرمی و بعضی به سردی مایل است . حدودش ولایات آذربایجان و کردستان و خوزستان و فارس و مفاغزه و قومس و به جیلانات پیوسته است . و طولش از سفیدرود تا یزد صد و شصت فرسنگ است، و عرض از جیلانات تا خوزستان صد فرسنگ در گذشته ... بلاد عراق عجم را چهارشهر معتبر بوده است ... و سپس بطور تفصیل به ذکر اوضاع مالیاتی و درآمد و خراج شهرهای مهم عراق عجم پرداخته و هر یک را با ذکر ارقام خاص بیان داشته است .<br />فرید وجدی گوید: عراق عجم عبارت از ولایتی است در وسط بلاد عجم به مساحت <span class=\"hlight\" dir=\"rtl\">٣٥٧/٠٠٠</span> کیلومتر مربع و آن قلب بلاد فرس است و شامل شهرهائی مانند همدان، اصفهان و غیره میشود.<br /></font></div>'),
(182026, 'عراق عرب', '<span class=\"hlight\">عراق عرب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ ع َ رَ ]</font></b> (اِخ ) رجوع به عراق (کشور عراق ) شود.<br /></font></div>'),
(182027, 'عراقان', '<span class=\"hlight\">عراقان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) تثنیه ٔ عراق (در حالت رفع). بصره و کوفه . (معجم البلدان ) (اقرب الموارد) (منتهی الارب ).<br /></font></div>'),
(182028, 'عراقی', '<span class=\"hlight\">عراقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) چوب چنبر دلو. (منتهی الارب ) (آنندراج ).<br /></font></div>'),
(182029, 'عراقی', '<span class=\"hlight\">عراقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ قی ی ]</font></b> (ص نسبی ) از مردم عراق . اهل عراق . منسوب به عراق . عراق عرب یا عجم .<br /></font></div>'),
(182030, 'عراقی', '<span class=\"hlight\">عراقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) ابن منصوربن مسلم فقیه شافعی . کنیت او ابواسحاق مصری است . مولد و منشاء و مدفن او مصر بود. به بغداد سکونت گزید. از فضلای فقهاء شافعی است . شرحی بر کتاب مهذب شیخ ابواسحاق شیرازی نوشته و در بغداد به مصری معروف گشته است و پس از مراجعت به مصر او را عراقی گفتند. وی به سال <span class=\"hlight\" dir=\"rtl\">٥٩٦</span> به مصر درگذشت . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١١٥</span>).<br></font></div>'),
(182031, 'عراقی', '<span class=\"hlight\">عراقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) فخرالدین عراقی . رجوع به فخرالدین عراقی همدانی شود.<br></font></div>'),
(182032, 'عراقی', '<span class=\"hlight\">عراقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) ابوالحسن، یکی از دبیران سلطان مسعود غزنوی و از ملازمان وی بود. تولد وی بدرستی معلوم نیست . وفات وی به سال <span class=\"hlight\" dir=\"rtl\">٤٩٢</span> روز دوشنبه ششم شعبان میباشد.مدفن وی مشهدالرضا است . در تاریخ بیهقی آمده است : که گفتند زنان او را دارو دادند و مردی سخت بدخو بود و باریک گیر. رجوع به تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٣٩</span> چ فیاض شود.<br></font></div>'),
(182033, 'عراقی', '<span class=\"hlight\">عراقی .</span> <font color=\"DarkGreen\"><b>[ع ِ ]</font></b> (اِخ ) رجوع به عبدالرحیم بن حسین عراقی شود.<br></font></div>'),
(182034, 'عراقی', '<span class=\"hlight\">عراقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) رجوع به ابراهیم بن شهریار شود.<br></font></div>'),
(182035, 'عراقی', '<span class=\"hlight\">عراقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) تاج الدین . رجوع به تاج الدین عراقی و تاریخ گزیده شود.<br></font></div>'),
(182036, 'عراقی', '<span class=\"hlight\">عراقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) ابوجعفر. رجوع به ابوجعفر عراقی و تاریخ گزیده شود.<br></font></div>'),
(182037, 'عراقی', '<span class=\"hlight\">عراقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) صدرالدین . رجوع به صدرالدین عراقی و تاریخ گزیده شود.<br /></font></div>'),
(182038, 'عراقی', '<span class=\"hlight\">عراقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) دهی است از دهستان میان آباد بخش اسفراین شهرستان بجنورد. <span class=\"hlight\" dir=\"rtl\">٣٦٢</span> تن سکنه دارد. آبش از رودخانه، محصولش غلات، بنشن، پنبه و میوه جات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(182039, 'عراقی', '<span class=\"hlight\">عراقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ص نسبی ) (پرده ٔ عراقی )، از آهنگهای موسیقی است . پرده ٔ عراق <span class=\"hlight\">:</span> <br />بعد از عراق جائی خوش نایدم هوائی <br />مطرب بزن نوایی زان پرده ٔ عراقی .<br /> <font color=\"Red\">سعدی .</font><br />رجوع به عراق و پرده ٔ عراقی شود.<br /></font></div>'),
(182040, 'عراقی', '<span class=\"hlight\">عراقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ص نسبی ) منسوب به عراق . نقد عراقی . در بیت ذیل از نظامی پول رایج و متداول در عراق معنی میدهد <span class=\"hlight\">:</span> <br />چرا گشتی در این بیغوله پابست <br />چنین نقد عراقی بر کف دست .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(182041, 'عراقی قادلو', '<span class=\"hlight\">عراقی قادلو.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) تیره ای از ایلات خمسه ٔ فارس . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٧٨</span>).<br></font></div>'),
(182042, 'عراقیب', '<span class=\"hlight\">عراقیب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) معدنی است و دهی است بزرگ نزدیک حمای ضربه مرضباب را. (از معجم البلدان ).<br></font></div>'),
(182043, 'عراقیب', '<span class=\"hlight\">عراقیب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) بینی های کوه . (منتهی الارب ) (آنندراج )، ج ِ عُرقوب . خیاشم الجبال . مرکب . <BR><font color=\"Blue\">◄</font> راههای تنگ و دشوار گذار در پشت کوه . (منتهی الارب ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کارهای سترگ و دشوار. <BR><font color=\"Blue\">◄</font> کارهای درهم . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> پاشنه ٔ پشت نعلین باشد و منه قول النبی (ص ): ویل للعراقیب من النار. (از معجم البلدان ).<br></font></div>'),
(182044, 'عراقیة', '<span class=\"hlight\">عراقیة.</span> <font color=\"DarkGreen\"><b>[ ع ِ قی ی َ ]</font></b> (ع ص نسبی ) شتران که گیاه باقی مانده را خورند. (از اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(182045, 'عراقیة', '<span class=\"hlight\">عراقیة.</span> <font color=\"DarkGreen\"><b>[ ع َ قی ی َ ]</font></b> (اِخ ) دهی است از دهستان فراهان بالا بخش فرمهین اراک، واقع در دامنه . سردسیر <span class=\"hlight\" dir=\"rtl\">١٨٣</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولاتش غلات وبنشن و پنبه و شغل اهالی زراعت است . از فرمهین بدانجا اتومبیل میرود. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(182046, 'عراقیل', '<span class=\"hlight\">عراقیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) سختی ها و کارهای دشوار و سخت و دشواریها. (منتهی الارب ) (ناظم الاطباء). داهیة. (مهذب الاسماء).<br></font></div>'),
(182047, 'عراقین', '<span class=\"hlight\">عراقین .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق َ ]</font></b> (اِخ ) تثنیه ٔ عراق (در حالت نصبی ) چرا که عراق دواند یکی عراق عرب و دیگری عراق عجم و در منتخب نوشته اند که عراقین کوفه و بصره نیزباشند. (از غیاث اللغات ) (از اقرب الموارد) (منتهی الارب ) (آنندراج ). و رجوع به عراقان شود <span class=\"hlight\">:</span> <br>بانگ آهنگ او به نصرت و فتح <br>در عراقین و در خراسان باز.<br> <font color=\"Red\">مسعودسعد.</font><br>شاه عراقین طراز کز پی توقیع او<br>کاغذ شامیست صبح خامه ٔ مصری شهاب .<br> <font color=\"Red\">خاقانی .</font><br>عمربن عبدالعزیز وصیت کرده است به عبدالرحمن ابن عبدالحمید به وقتی که او را به عراقین روانه میگرداندند. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١٨٤</span>).<br></font></div>'),
(182048, 'عراقیک', '<span class=\"hlight\">عراقیک .</span> <font color=\"DarkGreen\"><b>[ ع ِ ی َ ]</font></b> (ص مصغر) مصغر عراقی، منسوب به عراق بقصد تحقیر. <BR><font color=\"Blue\">◄</font> خطابی تحقیرآمیز «عراقی » را <span class=\"hlight\">:</span> و این نابکار عراقیک رادست کوتاه کنی از کرد و عرب . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٢٧</span>).<br></font></div>'),
(182049, 'عراقیین', '<span class=\"hlight\">عراقیین .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) منسوبان به عراق . <BR><font color=\"Blue\">◄</font> پیروان مذهب اهل رأی و مذهب ابی حنیفه را گویند. رجوع به حنفی شود. در مقابل اهل مدینه که اهل حدیث و اتباع سلف صالح معروف بودند.<br></font></div>'),
(182050, 'عرام', '<span class=\"hlight\">عرام .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) استخوان گوشت از وی باز کرده . <BR><font color=\"Blue\">◄</font> درخت پوست رفته . (از اقرب الموارد) (منتهی الارب ). درخت خائیده . <BR><font color=\"Blue\">◄</font> آنچه بر افتد از پوست . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> برگ عوسج . (از اقرب الموارد) (منتهی الارب ). ماسقط من قشر العوسج . <BR><font color=\"Blue\">◄</font> (اِمص ) شوخی . <BR><font color=\"Blue\">◄</font> بدخوئی . (منتهی الارب ). الشراسة و الاذی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نشاط و شادمانی . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> بسیاری . <BR><font color=\"Blue\">◄</font> عرام الرجل ؛ حدت و اشتداد مرد. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> عُرام الجیش ؛ تیزی و سختی لشکر. (از اقرب الموارد) <BR><font color=\"Blue\">◄</font> (مص ) شدید و سخت گردیدن . <BR><font color=\"Blue\">◄</font> شوخ شدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شوخی کردن کودک . (المصادر).<br></font></div>'),
(182051, 'عرام النحوی', '<span class=\"hlight\">عرام النحوی .</span> <font color=\"DarkGreen\"><b>[ ع َ مُن ْ ن َ ]</font></b> (اِخ ) ابوالفضل عباس بن محمد النحوی . رجوع به ابوالفضل عباس ... و روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">١٣</span> شود.<br></font></div>'),
(182052, 'عرامة', '<span class=\"hlight\">عرامة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع مص ) شدید و سخت گردیدن . (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شوخ شدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> احمق شدن . (تاج المصادر).<br></font></div>'),
(182053, 'عرامی', '<span class=\"hlight\">عرامی .</span><font color=\"DarkGreen\"><b>[ ع َ می ی ]</font></b> (اِخ ) لقب رجالی عبدالصمد بشیر و کثیربن احمد و چندتن دیگر است . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٧٥</span>).<br></font></div>'),
(182054, 'عران', '<span class=\"hlight\">عران .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) بیماریی است که موی پائین پای ستور برافکند. <BR><font color=\"Blue\">◄</font> کفتگی پای ستور. (از اقرب الموارد) (از منتهی الارب ) (از آنندراج ). <BR><font color=\"Blue\">◄</font> درشتی است که در خرده گاه دست و پای اسب برآید. (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> چوب بینی شتر. (منتهی الارب ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ابن السکیت گوید: و قرح یأخذه ؛ أی البعیر فی عنقه فیحتک منه و ریما برک الی اصل الشجرة و احتک بها. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> عران البکرة، چوب بکرة. (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> القرن . (اقرب الموارد). شاخ حیوان . <BR><font color=\"Blue\">◄</font> میخ . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مسمار که بین سنان و نیزه است . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> دیار دور.(از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کله ٔکفتار (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (مص ) دور گردیدن .(منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> کشش کردن و کارزار نمودن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اتصال یافتن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سخت و درشت گشتن . <BR><font color=\"Blue\">◄</font> پی پیچیدن بر تیر. (منتهی الارب ).<br></font></div>'),
(182055, 'عران', '<span class=\"hlight\">عران .</span> <font color=\"DarkGreen\"><b>[ ع َرْ را ]</font></b> (ع ص ) آنکه درخت عران فروشد. (از اقرب الموارد).<br></font></div>'),
(182056, 'عرانیة', '<span class=\"hlight\">عرانیة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ی َ ]</font></b> (ع اِ) آب خیز. (منتهی الارب ). مدالسیل . (اقرب الموارد) (از آنندراج ). <BR><font color=\"Blue\">◄</font> میانه ٔ دریا. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> آنچه موج از تک آب برآرد. (اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> بسیاری آب . (منتهی الارب ) (از آنندراج ).<br></font></div>'),
(182057, 'عرانین', '<span class=\"hlight\">عرانین .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عرنین . (منتهی الارب ). رجوع به عرنین شود.<br></font></div>'),
(182058, 'عراهل', '<span class=\"hlight\">عراهل .</span> <font color=\"DarkGreen\"><b>[ ع ُ هَِ ]</font></b> (ع ص ) تمام اندام . (منتهی الارب ) (آنندراج ). اسب تمام اندام . (آنندراج ).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(182059, 'عراهم', '<span class=\"hlight\">عراهم .</span> <font color=\"DarkGreen\"><b>[ ع ُ هَِ ]</font></b> (ع ص ) نرم و نازک از هر چیزی . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتر سطبر. (منتهی الارب ). القوی الشدید. و هی عراهمة. (و قیل کلاهما للمذکر دون المؤنث ) (از اقرب الموارد). اشتر بزرگ . (مهذب الاسماء).<br></font></div>'),
(182060, 'عراهمة', '<span class=\"hlight\">عراهمة.</span> <font color=\"DarkGreen\"><b>[ ع ُهَِ م َ ]</font></b> (ع ص ) مؤنث ِ عراهم . رجوع به عراهم شود.<br></font></div>'),
(182061, 'عراهن', '<span class=\"hlight\">عراهن .</span> <font color=\"DarkGreen\"><b>[ ع ُ هَِ ]</font></b> (ع ص ) شتر دفزک شگرف . (از اقرب الموارد). شتر بزرگ . (مهذب الاسماء).<br></font></div>'),
(182062, 'عراهیل', '<span class=\"hlight\">عراهیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) گروه بر سر خودگذاشته و بیکار. (منتهی الارب ) (آنندراج ). الجماعة المهملة. (اقرب الموارد). ج ِ عرهول . (ناظم الاطباء).<br></font></div>'),
(182063, 'عراک', '<span class=\"hlight\">عراک .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِمص ) ازدحام و انبوهی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> یقال أئرد ابله العراک، یعنی همه ٔ شتران را بر آب آورد. (قطر المحیط) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (مص ) انبوهی کردن . (آنندراج ) (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> کارزار کردن . (ناظم الاطباء).<br></font></div>'),
(182064, 'عراک', '<span class=\"hlight\">عراک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) حائض گردیدن . (منتهی الارب ).<br></font></div>'),
(182065, 'عراک', '<span class=\"hlight\">عراک .</span> <font color=\"DarkGreen\"><b>[ ع َرْ را ]</font></b> (ع ص ) سخت مالنده و گوشمال دهنده . (از اقرب الموارد) (منتهی الارب ) (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> کارزارکننده . (آنندراج ) (غیاث اللغات ) <span class=\"hlight\">:</span> <br>هست شعرم بلند بی دعوی <br>شاعرم بذله سنج نی عراک .<br><font color=\"Red\">طالب آملی (از آنندراج ).</font><br></font></div>'),
(182066, 'عرای', '<span class=\"hlight\">عرای .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) عَراء. صحرای بیدرخت و گیاه که بهیچ چیز در آن پناه نتوان برد. (غیاث ). <BR><font color=\"Blue\">◄</font> در اصطلاح شطرنج بازان مهره که میان شاه خود و رخ حریف حائل سازند برای حفاظت شاه از کشت و بعضی مردم که بجای عرای لفظ عراب گویند به زیادت باء موحدة خطاست .(غیاث اللغات ) (آنندراج ). آچمز (در تداول امروز).<br></font></div>'),
(182067, 'عرایا', '<span class=\"hlight\">عرایا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) بطنی است از بطون هوّاره . (صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦٣</span>).<br></font></div>'),
(182068, 'عرایا', '<span class=\"hlight\">عرایا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج عریة. رجوع به عریة شود.<br></font></div>'),
(182069, 'عرایس', '<span class=\"hlight\">عرایس .</span> <font color=\"DarkGreen\"><b>[ ع َ ی ِ ]</font></b> (ع اِ) عرائس . ج ِ عروس . رجوع به عروس شود.<br></font></div>'),
(182070, 'عرایض', '<span class=\"hlight\">عرایض .</span> <font color=\"DarkGreen\"><b>[ ع َ ی ِ ]</font></b> (ع اِ) عَرائِض . ج ِ عریضة. رجوع به عریضة شود.<br></font></div>'),
(182071, 'عرایض', '<span class=\"hlight\">عرایض .</span> <font color=\"DarkGreen\"><b>[ ع َ ی ِ ]</font></b> (اِخ ) دهی است از دهستان خین بخش مرکزی شهرستان خرمشهر، واقع در دشت . گرمسیر و مرطوب است . <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> تن سکنه دارد. آب آن از شطالعرب تأمین میشود. محصولات آن خرما است . شغل اهالی زراعت است . صنایع دستی آنها حصیربافی است . ساکنین از طایفه ٔ عرایضی هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(182072, 'عرب', '<span class=\"hlight\">عرب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) گیاه بهمی خشک . (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br></font></div>'),
(182073, 'عرب', '<span class=\"hlight\">عرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع مص ) شادمان گردیدن . <BR><font color=\"Blue\">◄</font> آماسیدن و ریمناک گردیدن . <BR><font color=\"Blue\">◄</font> باقی ماندن نشان زخم بعد به شدن . (از اقرب الموارد) (منتهی الارب ) (از آنندراج ). <BR><font color=\"Blue\">◄</font> تباه گردیدن . (از اقرب الموارد) (منتهی الارب ) (تاج المصادر). <BR><font color=\"Blue\">◄</font> بسیار آب گردیدن چشمه و چاه . (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> تغییر یافتن و تباه گردیدن . <BR><font color=\"Blue\">◄</font> نکس پیدا کردن زخم . (از اقرب الموارد).<br></font></div>'),
(182074, 'عرب', '<span class=\"hlight\">عرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِمص ) شادمانی . (آنندراج ). عَرب . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> فساد معده . <BR><font color=\"Blue\">◄</font> (ص، اِ) آب صافی بسیار. (منتهی الارب ).<br></font></div>'),
(182075, 'عرب', '<span class=\"hlight\">عرب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) عَرَب . مردم تازی شهرباش، یا عام است خلاف عجم، یؤنث . (منتهی الارب ). رجوع به عَرَب و عربستان شود.<br></font></div>'),
(182076, 'عرب', '<span class=\"hlight\">عرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دسته ای از مردم خلاف عجم، و مراداز عجم هر کسی است که غیر عرب باشد از فرس و ترک و فرنگ و جز آنها و لفظ عرب مؤنث است بر تأویل طائفه : یقال عرب العاربة و العرب العرباء. ج، اَعرُب، عُروب . و گفته شده است عرب شهرنشینانند، و گفته شده است عام است و شامل سکّان شهرها و بادیه ها هر دو شود. (از اقرب الموارد) (از قطر المحیط). مردم تازی شهرباش یا عام است و مؤنث آید. (منتهی الارب ) <span class=\"hlight\">:</span> <br>نامدار و مفتخر شد بقعه ٔ یمگان به من <br>چون بفضل مصطفی شد مفتخر دشت عرب .<br><font color=\"Red\">ناصرخسرو.</font><br>گرچه بده ست پیش از این در عرب و عجم روان <br>شعر شهید و رودکی نظم لبید وبحتری .<br> <font color=\"Red\">خاقانی .</font><br>شب عربی وار بود بسته نقابی بنفش <br>از چه سبب چون عرب نیزه کشید آفتاب .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">قوم عرب </span> ؛ مراد از عرب اکنون سکنه ٔ جزیرةالعرب و عراق و شام و سودان و مغرب است لکن قبل از اسلام مراد از عرب مردمی بوده اند که در جزیرةالعرب ساکن بوده اند زیرا مردم عراق و شام از ملتهای سریانی و کلدانی و نبطی و یهود و یونان و مردم مصر قبطی بوده اند و مردم مغرب ازبربران بوده اند و بالجمله مراد از قوم عرب قبل از اسلام، مردم بادیه نشین در جزیرةالعرب است که در جهت شمال جزیرةالعرب و شرق وادی نیل سکونت داشته اند. و لفظعرب مساوی بوده است با بدو یا بادیه و جزیره ٔ عرب بنام عربة نامیده میشد. لکن پس از آنکه حجاز و یمن مسکن آنها شد دیگر لفظ عرب مساوی با بادیه نبود و کلمه ٔ حضری و بدوی بکار رفت . مردم شهرنشین را که اصولاً موطن آنها حجاز و یمن بوده است عرب حضری نامیده اند و صحرانشین را بدوی .<br>در تاریخ عرب قبل از اسلام، عرب بدو قسم منقسم میشود یکی عرب بائده و دیگری عرب باقیه . مراد از عرب بائده قبائل قدیم اند که قبل از اسلام از میان رفته اند و عرب باقیه نیز بر دو قسم اند یکی عرب قحطانیه و دیگری عرب عدنانیه . عرب قحطانیه عبارتنداز حیرة و اهل یمن و فروع آنها، و عرب عدنانیه در حجاز و نواحی آن سکونت داشته اند. بنابراین اصل عرب به سه طبقه منقسم میشوند: عرب بائده یا عرب شمال، عرب قحطانیه یا دولتهای جنوبی و عدنانیه یا عرب شمال در طور سینا. اعراب شمال شامل عاد و ثمود و عمالقه و طسم و جدیس و امیم شده اند که آنها را عرب عاریه نامیده اند و از ابناء سامند. عرب قحطان یا جنوب شامل حکومتهای یمن بوده است و یونانیان آنان را عرب سعید نامیده اند از جهت وفور نعمت و زندگانی مرفهی که داشته اند.بسیاری از شهرهای قدیم یمن اکنون ویران شده است که احیاناً آثاری از آنها باقی نمانده است . در این منطقه حکومتهای مهمی در طول اعصار بوجود آمده بوده است . طبقه ٔ سوم که عرب عدنانیه باشد یا عرب شمال مسکن و منزل آنها شمال بلاد یمن بوده است در سرزمین تهامه و حجاز و نجد و جز آنها که انساب آنها به ابراهیم بن اسماعیل میرسد. رجوع به عربستان و رجوع به تاریخ العرب قبل الاسلام جرجی زیدان و ترجمه ٔ محاسن اصفهان ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>، <span class=\"hlight\" dir=\"rtl\">٥٩</span>، <span class=\"hlight\" dir=\"rtl\">٧٠</span> و تاریخ گزیده ص <span class=\"hlight\" dir=\"rtl\">١١</span>، <span class=\"hlight\" dir=\"rtl\">١٨</span> شود.<br>تاریخ تمدن اسلامی آرد: مردمان شبه جزیره ٔ عربستان بدو قسمت عمده تقسیم میشوند. <span class=\"hlight\" dir=\"rtl\">١</span> - قحطانی ها که در خاک یمن و زمینهای مجاور آن سکونت داشته اند و نسبت آنان به قحطان یا یقطان بن عامر و ارفحشاد وسام منتهی میگردد. <span class=\"hlight\" dir=\"rtl\">٢</span> - اسماعیلی یا عدنانی که در حجاز و نجد و اراضی میانه ٔ جزیره ٔ عربستان سکونت دارند و چون خاک یمن حاصلخیز بوده است قحطانیها زودتر از عدنانیها متمدن شده اند و دولتهای حمیر، سبا، کهلان و غیره از میان اقوام قحطانی برخاسته اند و یا فراعنه ٔ مصر و پادشاهان بابل و آشور همزمان بوده اند. اقوام دیگری از عرب بوده اند که اکنون از بین رفته اند و فقط نامی از آنها باقی است و آنان قوم عاد، ثمود، طسم، جدیس و عمالقه میباشند. بنابراین تمدن اسلامی نخستین تمدن عرب نبوده است، پیش از اسلام مردم حمیر، کهلان، سبا، واسطه ٔ تجارتی شرق و غرب بوده اند و علت عمده ٔ پیشرفت بازرگانی آنها یکی موقعیت جغرافیائی آنها بوده است و در قرن بیستم پیش از میلاداز کشور کلده به کشور سوریه و فینیقیه و عربستان آمد و شد داشته اند. عربهای حمیر و سبا (قحطانی ) که بعداز عاد و ثمود بودند تمدن بزرگی داشتند که اکنون خرابه هائی از آنها باقی است . عمالقه نیز از اقوام متمدن عرب و مردم سلحشور و سختگیر و با اقوام دیگر همواره در جنگ بوده اند.<br>مردم حجاز که در وسط عربستان میزیسته اند به حال بدوی باقی مانده بودند، زیرا سرزمین آنها خشک و بد آب و هوا بود و بواسطه ٔ سختی و بدی راه با مردم متمدن دیگرکمتر آمد و شد داشتند. در قرن پنجم میلادی سرخاندان قریش قصی بن کلاب بن مرة بود. که بواسطه ٔ هوش و عقل و فکر صائب شهرت بسیاری بهم زد و در آن زمان فرمانروایی مکه با طائفه ٔ خزاعه بود. پس از مرگ هاشم پسرش عبدالمطلب جدّ پیغمبر اسلام جانشین پدر گشت . در آن زمان طائفه ٔ قریش مزیتهائی بر سائر طوائف داشتند. حکومت حجاز در دوران جاهلیت سبک ملوک الطوائفی بوده است بدین معنی که امیر هر طائفه و قومی فرمانروا و قاضی و رئیس دارائی قوم خود بودند. این وضع بادیه نشینان حجاز بود لکن در شهر مکه مردم تابع پرده دار کعبه بوده اند زیرا حکومت مکه به دست وی بوده است . در شهر مکه و طائف بازارهای تجارتی بسیاری وجود داشت و قوم قریش عهده دار کارهای مهم بازرگانی بودند. کعبه یکی از مهمترین ممر معاش مردم مکه بود. مشاغل و مؤسسات کعبه تا زمان اسلام عبارت بودند از: <span class=\"hlight\" dir=\"rtl\">١</span> - دربانی و پرده داری . <span class=\"hlight\" dir=\"rtl\">٢</span> - آب دادن به حجاج . <span class=\"hlight\" dir=\"rtl\">٣</span> - رفاه یا مهمانداری . <span class=\"hlight\" dir=\"rtl\">٤</span> - پرچم داری . <span class=\"hlight\" dir=\"rtl\">٥</span> - خانه شوری . <span class=\"hlight\" dir=\"rtl\">٦</span> - مؤسسه ٔ مشورتی . <span class=\"hlight\" dir=\"rtl\">٧</span> - مؤسسه ٔ پرداخت دیه و غرامت . <span class=\"hlight\" dir=\"rtl\">٨</span> - قبه یا اسلحه خانه . <span class=\"hlight\" dir=\"rtl\">٩</span> - اعنه یا اداره کردن ستوران . <span class=\"hlight\" dir=\"rtl\">١٠</span> - سفارت . <span class=\"hlight\" dir=\"rtl\">١١</span> - ایسار یامؤسسه ٔ قمار و فالگیری . <span class=\"hlight\" dir=\"rtl\">١٢</span> - دادرسی یا حکومت . <span class=\"hlight\" dir=\"rtl\">١٣</span> - اموال . <span class=\"hlight\" dir=\"rtl\">١٤</span> - نگاهبانی مسجد الحرام .<br>سخنوران مشهوری در حدود یک قرن قبل از اسلام در میان اعراب پدید آمدند و نهضت ادبی خاصی بوجود آوردند و این نهضت جنبه ٔ دینی و مذهبی نیز داشت زیرا از نظر دینی یکنوع هیجان میان اعراب پیدا شده بود، عده ای بت پرست، عده ای آتش پرست و عده ای موحد بودند. این در هم ریختگی اوضاع علت اصلی این نهضت شد که عده ای اصلاح طلب در فکر اصلاح اوضاع اجتماعی برآیند. رجوع به عربستان شود.<br></font></div>'),
(182077, 'عرب', '<span class=\"hlight\">عرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) شعبه ای ازهفت لنگ بختیاری است . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٧٣</span>).<br></font></div>'),
(182078, 'عرب', '<span class=\"hlight\">عرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی است از بخش حومه ٔ شهرستان بجنورد. کوهستانی و معتدل و <span class=\"hlight\" dir=\"rtl\">٥٦٣</span> تن سکنه دارد. آب آن از چشمه و محصول آن غلات بنشن، انگور و شغل مردم مالداری است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(182079, 'عرب', '<span class=\"hlight\">عرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی است از دهستان گوکلان بخش مرکزی شهرستان گنبد قابوس ناحیه ای است کوهستانی هوای آن معتدل است <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> تن سکنه دارد. آب آن از چشمه تأمین میشود. محصولاتش غلات . حبوبات . لبنیات ابریشم است . شغل اهالی زراعت و گله داری است . صنایع دستی زنان پارچه ابریشم بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(182080, 'عرب', '<span class=\"hlight\">عرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی است از دهستان اربعه بالا (علیا) بخش مرکزی شهرستان فیروزآباد. ناحیه ای است کوهستانی . هوای آن معتدل است <span class=\"hlight\" dir=\"rtl\">١٨٢</span> تن سکنه دارد. آب آن از رودخانه فیروزآباد تأمین میشود. محصولات آن غلات و برنج است . شغل اهالی زراعت است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(182081, 'عرب', '<span class=\"hlight\">عرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (ع اِمص ) تیزی معده . (منتهی الارب ).<br></font></div>'),
(182082, 'عرب', '<span class=\"hlight\">عرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) آب بسیار صافی .(از اقرب الموارد) (منتهی الارب ) (از قطر المحیط).<br></font></div>'),
(182083, 'عرب', '<span class=\"hlight\">عرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) میرزا صالح بن سیدحسن موسوی حائری تهرانی مشهور به عرب و داماد. فقیه و از سوی علماء امامیه ٔ اوائل قرن چهارده بود. به سال <span class=\"hlight\" dir=\"rtl\">١٣٠٣</span> هَ . ق . درگذشت . کتابی در اجتهاد و تقلید نگاشته است . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٧٥</span>).<br></font></div>'),
(182084, 'عرب', '<span class=\"hlight\">عرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) طایفه ای از طوائف فارس است . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">١٠٤</span>).<br></font></div>'),
(182085, 'عرب', '<span class=\"hlight\">عرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) از ایلات خمسه ٔ فارس است . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٨٦</span>).<br></font></div>'),
(182086, 'عرب آباد', '<span class=\"hlight\">عرب آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی است از دهستان فعله کری بخش سنقر کلیائی شهرستان کرمانشاهان . ناحیه ای است، واقع در دامنه و سردسیر است و <span class=\"hlight\" dir=\"rtl\">١٤٥</span> تن سکنه دارد و آب آن از قنات تأمین میشود. محصولات آن غلات و حبوبات و توتون و شغل اهالی زراعت است . صنایع دستی زنان قالیچه و جاجیم بافی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(182087, 'عرب آباد', '<span class=\"hlight\">عرب آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی است از دهستان یهود بخش طبس شهرستان فردوس . <span class=\"hlight\" dir=\"rtl\">١٥١</span> تن سکنه دارد. آب آن از قنات و شغل اهالی زراعت است . (از فرهنگ جغرافیائی ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(182088, 'عرب آباد', '<span class=\"hlight\">عرب آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی از بخش ماهان شهرستان کرمان . ناحیه ای است کوهستانی و سردسیر. <span class=\"hlight\" dir=\"rtl\">١٨٠</span> تن سکنه دارد. آب آن از چشمه و قنات تأمین میشود. محصولاتش : غلات حبوبات و صیفی است . اهالی بکشاورزی و مکاری و ریسندگی گذران میکنند. راه فرعی به شوسه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(182089, 'عرب آباد', '<span class=\"hlight\">عرب آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی است از دهستان بالارخ بخش کدکن شهرستان تربت حیدریه . واقع است در دشت . هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">١٩٨</span> تن سکنه دارد. آب آن از قنات تأمین میشود. شغل اهالی زراعت و گله داری است . صنایع دستی کرباس بافی است . از اسدآباد میتوان اتومبیل برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(182090, 'عرب آباد', '<span class=\"hlight\">عرب آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی از دهستان فشند بخش کرج شهرستان تهران . ناحیه ای است کوهستانی . سردسیر و <span class=\"hlight\" dir=\"rtl\">٢١٨</span> تن سکنه دارد. آب آن از قنات و چشمه سار تأمین میشود. محصولات آن غلات و بنشن، صیفی و باغات میوه و قلمستان و لبنیات است . شغل اهالی زراعت و گله داری است . صنایع دستی آنها کرباس بافی است . امامزاده ای دارد بنام هاشم . از کاروان سرای عرب آباد کنار شوسه بدانجا ماشین میرود. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(182091, 'عرب آباد افشار', '<span class=\"hlight\">عرب آباد افشار.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی است از دهستان افشاریه ساوجبلاغ بخش کرج شهرستان تهران . ناحیه ای است جلگه ای . آب و هوای معتدل دارد. آب آن از قنات و رود کردان تأمین میشود. محصولات آن غلات .بنشن . لبنیات . صیفی . چغندرقند. باغات میوه و قلمستان است . شغل اهالی زراعت و گله داری است . از طریق قهوه خانه ٔ علیخان سلطانی کنار خط شوسه کرج به قزوین ماشین میرود. (از فرهنگ جغرافیائی ایران استان مرکزی ).<br></font></div>'),
(182092, 'عرب اوغلو', '<span class=\"hlight\">عرب اوغلو.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ اُ ]</font></b> (اِخ ) دهی است از دهستان کل تپه فیض اﷲ بیکی بخش مرکزی سقز ناحیه ای است کوهستانی . سردسیر <span class=\"hlight\" dir=\"rtl\">١٦٥</span> تن سکنه دارد. آب آن از رودخانه و چشمه تأمین میشود محصولات آن غلات و لبنیات و توتون و تنباکو و قلمستان است . شغل اهالی زراعت و گله داری است . دبستان دارد. در دو محل بفاصله <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی بنام عرب اوغلو پائین و بالا قرار گرفته و سکنه ٔ بالا <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> نفرست . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(182093, 'عرب بکر', '<span class=\"hlight\">عرب بکر.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب َ ک ِ ]</font></b> (اِخ ) دهی است از دهستان اربعه پایین (سفلی ) بخش مرکزی شهرستان فیروزآباد. ناحیه ای است جلگه ای و گرمسیر، <span class=\"hlight\" dir=\"rtl\">٥٥٠</span> تن سکنه دارد. آب آن از قنات تأمین میشود. محصولات آن غلات و خرما و لیموست . شغل اهالی زراعت و باغبانی است و راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(182094, 'عرب حاجی آقا سلطانی', '<span class=\"hlight\">عرب حاجی آقا سلطانی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِ س ُ ]</font></b> (اِخ ) از ایلات اطراف تهران است . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">١١١</span>).<br></font></div>'),
(182095, 'عرب حسن', '<span class=\"hlight\">عرب حسن .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ح َ س َ ]</font></b>(اِخ ) دهی است از دهستان میان آب بخش مرکزی شهرستان شوشتر، واقع در <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی جنوب خاوری شوشتر کنار راه تابستانی شوشتر به بند قیر کنار شمال خاوری رود شطیط، واقع در دشت و گرمسیر است . <span class=\"hlight\" dir=\"rtl\">١٢٠٠</span> تن سکنه دارد. آب آن از رود شطیط تأمین میشود. محصولات آن غلات و شغل اهالی زراعت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(182096, 'عرب خانه', '<span class=\"hlight\">عرب خانه .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ن َ ]</font></b> (اِخ ) نام یکی از دهستانهای بخش درمیان، شهرستان بیرجند و محدود است از طرف شمال خاوری به دهستان مؤمن آباد از باختر به دهستان قیس آباداز شمال به دهستان گل فریز. جلگه ای و کوهستانی و معتدل و محصول غلات است، مردم آن از ایلات خوزستانند که در زمان نادرشاه به این محل کوچانده شده اند. شغل اهالی زراعت و گله داری است و صنایع دستی آنان قالیبافی . این دهستان از <span class=\"hlight\" dir=\"rtl\">١٩</span> آبادی کوچک و بزرگ تشکیل شده است و <span class=\"hlight\" dir=\"rtl\">١٠٥٩٨</span> تن تقریبی نفوس دارد. قراء مهم آن دهکده سهل آباد و مختاران است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(182097, 'عرب خیل', '<span class=\"hlight\">عرب خیل .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ خ َ ]</font></b> (اِخ ) دهی است از دهستان قشلاق کلارستاق بخش چالوس شهرستان نوشهر. ناحیه ٔ دشتی است و هوای آن معتدل است دویست تن سکنه دارد. آب آن از رودخانه ٔ سردآب رود تأمین میشود. محصولاتش برنج و لبنیات است . شغل اهالی زراعت است . راه مالرو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(182098, 'عرب خیل', '<span class=\"hlight\">عرب خیل .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ خ َ ]</font></b> (اِخ ) دهی است از دهستان ناتل رستاق بخش نور شهرستان آمل، واقعدر دشت . هوای آن معتدل است یکصد و پنج تن سکنه دارد. آب آن از وازرود تأمین میشود. محصولات آن برنج و مختصر غلات و شغل اهالی زراعت است . تابستان به ییلاق دهستان لاریج میروند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(182099, 'عرب دیزه سی', '<span class=\"hlight\">عرب دیزه سی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ زَ ]</font></b> (اِخ ) دهی است از دهستان آواجیق بخش حومه ٔ شهرستان ماکو در مسیر شوسه ٔ کلیساکندی . ناحیه ای است جلگه ای . هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٧٠٠</span> تن سکنه دارد. آب آن از کوهستان تأمین میشود. محصولاتش غلات و بزرک و حبوبات است . صنایع دستی جاجیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(182100, 'عرب راشد', '<span class=\"hlight\">عرب راشد.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ش ِ ]</font></b> (اِخ ) دهی است از دهستان باوی بخش مرکزی شهرستان اهواز کنار راه لوله ٔ نفت اهواز به هفتگل، واقع در دشت و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن سکنه دارد. آب آن از چاه تأمین میشود. محصولات آن غلات است . شغل اهالی زراعت و گله داری است . در تابستان راه اتومبیل رو دارد. پاسگاه ژاندارمری و تلفن در <span class=\"hlight\" dir=\"rtl\">٦</span> کیلومتری آبادی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(182101, 'عرب سرنگ', '<span class=\"hlight\">عرب سرنگ .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ س ُ رَ ]</font></b> (اِخ ) دهی از دهستان اقابای بخش مرکزی شهرستان گنبد قابوس از محله هائی بنام کسلخه، امان قراجه، بهلکه تشکیل شده است، سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٢٠٠</span> تن . محصولات آنجا غلات، حبوب، لبنیات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(182102, 'عرب صحنانی', '<span class=\"hlight\">عرب صحنانی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِ ص َ ]</font></b> (اِخ ) از ایلات اطراف تهران است . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">١١١</span>).<br></font></div>'),
(182103, 'عرب عاربه', '<span class=\"hlight\">عرب عاربه .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِ رِ ب َ ]</font></b> (اِخ ) نست شناسان همه ٔ اقوام عرب را بدو شجره ٔ بزرگ تقسیم کرده اند: عربهای جنوبی (از یمن ) و عربهای شمالی . عربهای یمن یا قحطانی که از یک شاخه ٔ اصلی یا یک شجره انداعم از حمیریها و سبائیها و معینی ها و قتبانیها و حضرموتیها باضافه ٔ بنوکهلان که عرب بائده نامیده شده اند و اکنون تنها نامی از آنها در زبانها هست عرب عاربه و همچنین طوائف و اقوام عاد ثمود، طسم، جدیس و عملاق . و عربهای شمالی یا عدنانی عرب مستعربه اند یعنی اصلاً از نژاد عرب نبودند و در عرب مستهلک شدند. عرب شمالی را اسماعیلی، عدنانی، معدی نیز می نامند. (از پرویز تا چنگیز تألیف تقی زاده صص <span class=\"hlight\" dir=\"rtl\">٢٥</span> - <span class=\"hlight\" dir=\"rtl\">٢٦</span>). و نیز رجوع شود به صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٥</span> و اعراب قبل الاسلام ص <span class=\"hlight\" dir=\"rtl\">٥١</span>.<br></font></div>'),
(182104, 'عرب عدنانی', '<span class=\"hlight\">عرب عدنانی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِ ع َ نی ی ]</font></b> (اِخ ) عرب مستعربه . و رجوع به عربستان و عرب عاربه و عدنان شود.<br></font></div>'),
(182105, 'عرب قحطانی', '<span class=\"hlight\">عرب قحطانی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِق َ نی ی ]</font></b> (اِخ ) رجوع به عربستان و عرب عاربه شود.<br></font></div>'),
(182106, 'عرب قری حاجی', '<span class=\"hlight\">عرب قری حاجی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) دهی از دهستان گوگلان بخش مرکزی شهرستان گنبدقابوس . <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه دارد. شغل اهالی زراعت و گله داری، صنایع دستی زنان ابریشم بافی و نمدمالی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(182107, 'عرب لاله گون', '<span class=\"hlight\">عرب لاله گون .</span> <font color=\"DarkGreen\"><b>[ ع َ ب ِ ل َ ]</font></b> (اِخ ) دهی است از دهستان گوگلان بخش مرکزی شهرستان گنبدقابوس، ناحیه ای است کوهستانی سردسیر. <span class=\"hlight\" dir=\"rtl\">٢٢٠</span> تن سکنه دارد. شغل اهالی زراعت و گله داری است، صنایع دستی زنان بافتن پارچه های ابریشمی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(182108, 'عرب لنگ', '<span class=\"hlight\">عرب لنگ .</span><font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) یا پلنگ دژ فعلی . دهی است از دهات سرشیو شهرستان سقز. کوهستانی، سردسیر. <span class=\"hlight\" dir=\"rtl\">١٨٠</span> تن سکنه دارد. آب آن از چشمه و رودخانه تأمین میشود. محصولات آنجا غلات، لبنیات، توتون و حبوبات است . شغل اهالی زراعت و گله داری است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(182109, 'عرب مستعربه', '<span class=\"hlight\">عرب مستعربه .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِ م ُ ت َ رِ ب َ ]</font></b> (ترکیب وصفی، اِ مرکب )بگفته ٔ قلقشندی در صبح الاعشی عرب مستعربه که متعربه هم گویند فرزندان اسماعیل بن ابراهیم اند زیرا زبان اسماعیل عبرانی یا سریانی بود و چون به جرهم وارد شد و با آنها ازدواج کرد او و فرزندانش را مستعرب گفتند. (از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">١</span> صص <span class=\"hlight\" dir=\"rtl\">٣٣٦</span> - <span class=\"hlight\" dir=\"rtl\">٣٥٨</span>). و صاحب اقرب الموارد آرد: عرب دخیل غیر خالص و آنان باشند که بزبان اسماعیل بن ابراهیم تکلم کنند و آن لغات حجاز و اطراف آن باشد. رجوع به عرب و عربستان و عرب عاربه شود. صاحب العرب قبل الاسلام آرد: عرب مستعربه عبارتند از عدنانیان که ابناء عدنان بن اسماعیل بن ابراهیم اند و ابراهیم نخستین کسی از آنان است که بسرزمین عربستان وارد شد و با فرزندان خود در مکه سکونت گزید و در آنجا رشد کردند و علاوه بر مکه شبه جزیره را نیز از نسل خود پر کردند و آنگاه در واقعه ٔ بختنصر، عدنان از بین رفت و فرزندانش با اصحاب و یارانش به حران رفتند و از آنجا به مکه کوچ کردند. (از العرب قبل الاسلام ص <span class=\"hlight\" dir=\"rtl\">٥١</span>).<br></font></div>'),
(182110, 'عرب مضری', '<span class=\"hlight\">عرب مضری .</span> <font color=\"DarkGreen\"><b>[ ع َ ب ِ م ُ ض َ ری ی ]</font></b> (اِخ ) رجوع به عرب عدنانیه شود.<br></font></div>'),
(182111, 'عرب معدی', '<span class=\"hlight\">عرب معدی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِ م َ دی ی ]</font></b> (اِخ ) رجوع به عرب عدنانیه شود.<br></font></div>'),
(182112, 'عرب میش مست', '<span class=\"hlight\">عرب میش مست .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِ م َ ]</font></b> (اِخ ) از ایلات اطراف تهران است . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">١١١</span>).<br></font></div>'),
(182113, 'عرب پرورد', '<span class=\"hlight\">عرب پرورد.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ پ َرْ وَ ]</font></b> (ن مف مرکب ) عرب پرورده . تربیت کرده و ساخته ٔ دست عرب . به دست عرب فرهنگ و ادب گرفته <span class=\"hlight\">:</span> <br>کان بیابانی عرب پرورد<br>کار ملک عجم نداند کرد.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(182114, 'عرب پوران', '<span class=\"hlight\">عرب پوران .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی است از دهستان کوکلان بخش مرکزی شهرستان گنبد قابوس ناحیه ای دشتی است . هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه دارد. آب آن از رودخانه ٔ پنج ارخ تأمین میشود.محصولاتش برنج و غلات و حبوبات است . شغل اهالی زراعت و گله داری است . صنایع دستی زنان بافتن پارچه های ابریشی و نمدمالی است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(182115, 'عرب کشی', '<span class=\"hlight\">عرب کشی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِ ک َ شی ی ]</font></b> (اِخ ) از ایلات اطراف تهران است . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">١١١</span>).<br></font></div>'),
(182116, 'عرب کلو', '<span class=\"hlight\">عرب کلو.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) دهی است از دهستان کوهساران بخش مینودشت شهرستان گرگان . ناحیه ای است کوهستانی . <span class=\"hlight\" dir=\"rtl\">١١٥</span> تن سکنه دارد. شغل اهالی زراعت و گله داری است . صنایع دستی زنان بافتن پارچه ابریشمی و چادرشب است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(182117, 'عرب کوشکلی', '<span class=\"hlight\">عرب کوشکلی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِ ]</font></b> (اِخ ) از ایلات اطراف تهران است . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br></font></div>'),
(182118, 'عرب کوه پنج', '<span class=\"hlight\">عرب کوه پنج .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِ پ َ ]</font></b> (اِخ ) از ایلات کرمان و بلوچستان است . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٩٣</span>).<br></font></div>'),
(182119, 'عربات', '<span class=\"hlight\">عربات .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) کشتیهای بسته در دجله که بجای پل باشد. (منتهی الارب ).<br></font></div>'),
(182120, 'عربات', '<span class=\"hlight\">عربات .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) ج ِ عربة و آن بلاد عرب باشد. <BR><font color=\"Blue\">◄</font> و راهی است در کوه بطریق مصر. <BR><font color=\"Blue\">◄</font> عربة بلغت اهل جزیره سفینه ای باشد که در آن آسیائی در میان آب جاری مثل دجله و فرات و غیره سازند و این لغت ظاهراً مولدة است . (معجم البلدان ).<br></font></div>'),
(182121, 'عرباتی', '<span class=\"hlight\">عرباتی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ تی ی ]</font></b> (اِخ ) ساکنین عربه را گویند که موضعی است به فلسطین . (از قاموس کتاب مقدس ).<br></font></div>'),
(182122, 'عرباض', '<span class=\"hlight\">عرباض .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) عربض . درشت و استوار. توانا از مردم و شتر. (منتهی الارب ). الغلیظ الشدید من الناس و من الابل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شیر گران و بزرگ جثه ٔ پهن سینه . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(182123, 'عربان', '<span class=\"hlight\">عربان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است ازدهستان مرکزی بخش صومعه سرا شهرستان فومن جلگه است وهوای معتدل و <span class=\"hlight\" dir=\"rtl\">١٢٣٠</span> تن سکنه دارد. آب از رودخانه ٔ ماسوله و استخر و چشمه تأمین میشود. محصولاتش برنج، توتون مختصر ابریشم و چای است . شغل اهالی زراعت است . دو مسجد قدیم دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(182124, 'عربان', '<span class=\"hlight\">عربان .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b>(ع اِ) اربان . (زیراگاه عین آن تبدیل به همزه شود).بیعانه . (منتهی الارب ). رجوع به ربون و اربون شود.<br></font></div>'),
(182125, 'عربان', '<span class=\"hlight\">عربان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) شهر کوچکی است به خابور ازسرزمین جزیره، سالم بن منصوربن عبدالحمید ملقب به ابوالغنائم امقری بدانجا نسبت دارد. (معجم البلدان ).<br></font></div>'),
(182126, 'عربان', '<span class=\"hlight\">عربان .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی است از دهستان چالانچولان شهرستان بروجرد. ناحیه ای است، واقع در جلگه . هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">٣٠٧</span> تن سکنه دارد. آب آن از چشمه تأمین میشود. محصولات آنجا غلات است . شغل اهالی زراعت است . راه اتومبیل رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(182127, 'عربانة', '<span class=\"hlight\">عربانة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ن َ ]</font></b> (اِ) دف و دائره باشد و بعضی دائره ٔ حلقه دار را گویند. (آنندراج ).<br></font></div>'),
(182128, 'عربب', '<span class=\"hlight\">عربب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب ُ ]</font></b> (ع اِ) آب صافی بسیار. <BR><font color=\"Blue\">◄</font> باقی نشان جراحت . <BR><font color=\"Blue\">◄</font> (اِخ ) ناحیه ای است به مدینه . (منتهی الارب ).<br></font></div>'),
(182129, 'عربة', '<span class=\"hlight\">عربة.</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ب َ ]</font></b> (ع ص ) خالص از عرب . (منتهی الارب ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زن بسیار خندنده . (منتهی الارب ). عروب از نساء. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زن حریص بر بازی و لهو. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> معده ٔ تباه شده . <BR><font color=\"Blue\">◄</font> چاه بسیار آب . (از اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(182130, 'عربة', '<span class=\"hlight\">عربة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب َ ]</font></b> (ع اِ) نهری که آبش سخت تیز رود. <BR><font color=\"Blue\">◄</font> نفس . (از اقرب الموارد) (منتهی الارب ) (آنندراج ).<br></font></div>'),
(182131, 'عربة', '<span class=\"hlight\">عربة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب َ ]</font></b> (اِخ )دهی است در اول وادی نخله از طرف مکة. (از معجم البلدان ). ناحیه ای است نزدیک مدینه، قریش بدانجا اقامت کرد و عرب بدان نسبت داده میشود. (از منتهی الارب ).<br></font></div>'),
(182132, 'عربة', '<span class=\"hlight\">عربة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب َ ]</font></b> (اِخ ) در اصل نام شهرهای عرب است . <BR><font color=\"Blue\">◄</font> موضعی است به فلسطین . (معجم البلدان ).<br></font></div>'),
(182133, 'عربة', '<span class=\"hlight\">عربة.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) (به عبری معنی سوخته دارد) وادیی است که از جبل شیخ به خلیج عربه ممتد است طولش <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> میل و شامل حوله و بحرالجلیل و بحرالملح یا مرداب میباشد و گاهی این اسم به الغور که فیمابین دریای مرداب و دریای احمر واقع است صدق کند. و در غیر این موضع گاهی اشاره به الغور قصد از شمال دریای مرداب مذکور است اما قسمتی که از شمال دریای مرداب به خلیج عقبه ممتد است . طولش <span class=\"hlight\" dir=\"rtl\">١٠٠</span> میل و عرضش از <span class=\"hlight\" dir=\"rtl\">٤</span> - <span class=\"hlight\" dir=\"rtl\">١٤</span> میل و ارتفاع دیوارهای آهکی و کلسیه اش بمغرب دشت از <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> الی <span class=\"hlight\" dir=\"rtl\">١٨٠٠</span> قدم و ارتفاع کوه هور <span class=\"hlight\" dir=\"rtl\">٥٠٠٠</span> قدم و سنگهای طرف شرقی غالباً پورفیری و باسلت میباشد و سطح دشت مرقوم پورفیری و ریگهای از سنگهای مختلفه فراهم آمده پوشیده است . و سبزه و علف کمیاب و حرارت هوایش در غایت شدت میباشد ولی قضیه ٔ این که درزمان قدیم رود اردن در عربه جاری بوده است از جمله آراء سخیف و بی اعتباری است . (از قاموس کتاب مقدس ).<br></font></div>'),
(182134, 'عربج', '<span class=\"hlight\">عربج .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب ُ ]</font></b> (ع ص ) سگ سطبرفربه . (از اقرب الموارد) (آنندراج ) (منتهی الارب ).<br></font></div>'),
(182135, 'عربد', '<span class=\"hlight\">عربد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ب َدد <span class=\"hlight\" dir=\"rtl\">/</span> ب ِدد ]</font></b> (ع ص ) درشت از هر چیزی . <BR><font color=\"Blue\">◄</font> (اِ) خوی و عادت . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> دأب و عادت، و گفته شده است صحیح آن در دأب و عادت عرید است ؛ یقال مازال عریده ؛ کذا ای دأبه و هجیره . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ماری است که در دمد و نگزد. <BR><font color=\"Blue\">◄</font> یا ماری است خبیث سرخ رنگ . (از اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(182136, 'عربد', '<span class=\"hlight\">عربد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ب ِ ]</font></b> (ع اِ) مار. <BR><font color=\"Blue\">◄</font> (ص ) زمین درشت . (از اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(182137, 'عربد', '<span class=\"hlight\">عربد.</span> <font color=\"DarkGreen\"><b>[ ع ُرَ ب ِ ]</font></b> (ع ص ) عُرَبِدَة. عُبْرُد. عُبَرِد. عُبارِد. جاریةٌ عُرَبِد؛ دختر سپیدرنگ، تازه بدن نازک و لرزان اندام . (از منتهی الارب، ذیل ماده ٔ «ع ب ر د»).<br></font></div>'),
(182138, 'عربده جوی', '<span class=\"hlight\">عربده جوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف مرکب ) کنایه از جنگجوی و جنگ آور باشد. (آنندراج ). پرخاشجوی . ستیزه جوی و هنگامه جوی . (ناظم الاطباء) (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از چاپلوس و فریب دهنده و کنایه از بازیگر و حقه باز هم هست . (آنندراج ) <span class=\"hlight\">:</span> <br>هر آنکه بر رخ منظور ما نظردارد<br>بترک خویش بگوید که یار عربده جوست .<br> <font color=\"Red\">سعدی .</font><br>ز چرخ عربده جویش خدنگ تیر جفا<br>نخست در دل مردان هوشیار آید.<br> <font color=\"Red\">سعدی .</font><br>نرگسش عربده جوی و لبش افسون کنان <br>نیم شب دوش ببالین من آمد بنشست .<br> <font color=\"Red\">حافظ.</font><br>روزگاری من و دل ساکن کوئی بودیم <br>ساکن کوی بت عربده جوئی بودیم .<br><font color=\"Red\">وحشی .</font><br></font></div>'),
(182139, 'عربده جویی', '<span class=\"hlight\">عربده جویی .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص مرکب ) عمل عربده جو. پرخاشجویی . مجادله .<br></font></div>'),
(182140, 'عربده زدن', '<span class=\"hlight\">عربده زدن .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ زَ دَ ]</font></b> (مص مرکب ) فریادکشیدن . فریاد ناهنجار برآوردن . بدمستی کردن . بانگ وفریاد کردن . بانگ زدن بر روی کسی از خشم یا مستی .<br></font></div>'),
(182141, 'عربده کار', '<span class=\"hlight\">عربده کار.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب ) کس که به دوستان و هم پیالگان خود ستیزه کند.<br></font></div>'),
(182142, 'عربده کردن', '<span class=\"hlight\">عربده کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ک َ دَ ]</font></b> (مص مرکب ) بدمستی کردن . فریاد کردن <span class=\"hlight\">:</span> <br>شحنه بود مست که آن خون کند<br>عربده با پیرزنی چون کند.<br> <font color=\"Red\">نظامی .</font><br>هر که می با تو خورد عربده کرد<br>هر که روی تو دید عشق آورد.<br> <font color=\"Red\">سعدی .</font><br>پسرش خمر خورد و عربده کرد. (گلستان ).<br></font></div>'),
(182143, 'عربده کشیدن', '<span class=\"hlight\">عربده کشیدن .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ ]</font></b> (مص مرکب ) بدمستی کردن . داد و بیداد کردن . داد و بیداد راه انداختن . بانگ داشتن از خشم یا بدخویی یا مستی .<br></font></div>'),
(182144, 'عربده گر', '<span class=\"hlight\">عربده گر.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ گ َ ]</font></b> (ص مرکب ) فریادگر. داد و بیداد کننده .<br></font></div>'),
(182145, 'عربرب', '<span class=\"hlight\">عربرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ رَ ]</font></b> (ع اِ) عربربیة. سماق . تتم . عبرب . (از اقرب الموارد) (از منتهی الارب ).<br></font></div>'),
(182146, 'عربربیة', '<span class=\"hlight\">عربربیة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ رَ بی ی َ ]</font></b> (ع اِ) عربرب . عبرب . سماق . (اقرب الموارد). رجوع به عربرب شود.<br></font></div>'),
(182147, 'عربس', '<span class=\"hlight\">عربس .</span> <font color=\"DarkGreen\"><b>[ ع ِ ب ِ ]</font></b> (ع اِ) پشته ٔ بلند هموار از زمین سهل و نرم جهت فرود آمدن آخر شب . (منتهی الارب ) (آنندراج ). المتن المستوی من الأرض السهل ... (اقرب الموارد).<br></font></div>'),
(182148, 'عربستان', '<span class=\"hlight\">عربستان .</span> <font color=\"DarkGreen\"><b>[ع َ رَ ب ِ ]</font></b> (اِخ ) نام یکی از دهستانهای حومه ٔ شهرستان گلپایگان است . این دهستان در جنوب خاوری شهرستان گلپایگان واقع شده است و حدود آن به شرح زیر است : ازشمال به جلگه . از جنوب به خاک اصفهان از خاور به قم از باختر به خونسار. موقعیت طبیعی آن، واقع در جلگه است . هوای آن گرم و سالم است . این دهستان از <span class=\"hlight\" dir=\"rtl\">٨</span> آبادی بزرگ و کوچک تشکیل شده است و جمعیت آن در حدود <span class=\"hlight\" dir=\"rtl\">٦٤٩٤</span> تن است . قراء مهم آن عبارتند از رحمت آباد. خم و پیچ، ورزنه، درتجره . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(182149, 'عربستان', '<span class=\"hlight\">عربستان .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِ ]</font></b> (اِخ ) عربستان شبه جزیره ای است که از طرف جنوب به خلیج عدن و تنگه ٔ باب المندب و اقیانوس هند و دریای عمان و از مغرب به دریای سرخ (قلزم ) و ترعه ٔ سوئز و از مشرق به دریای عمان و خلیج فارس و عراق عرب و از شمال غربی به طرف جنوب شرقی شبیه شکل ذوزنقه ٔ غیر منتظم است از طرف شمال میان شامات و نجد و در طرف جنوب میان نجد و حضرموت و عمان و یمن دو کویر بسیار وسیع واقع شده است (کویر نفود و کویرالربع الخالی ). در شمال غربی میان مدیترانه و فلسطین و خلیج عقبه و ترعه ٔ سوئز شبه جزیره ٔ سینا واقع است . در مشرق این شبه جزیره و در جنوب بحر میت و فلسطین خطه ٔ سرحدی بین حجاز و فلسطین است معروف به وادی العریة که مملکت نبطی های قدیم و پای تخت آنها بوده است که در مآخذ رومی و یونانی پترا مینامیدند. در جنوب این خطه و در امتداد سواحل عقبه و دریای سرخ از شمال غربی به جنوب شرقی، خاک حجازممتد میشود. و باز در امتداد ساحل و به همان قرار ولایت کوچک عسیر و در جنوب عسیر خطه ٔ یمن واقع است که تا دریای سرخ و تنگه ٔ باب المندب کشیده میشود. و پس از آن در انتهای جنوب عربستان و ساحل دریای عربستان و اقیانوس هند و از مشرق به مغرب ابتداء ناحیه ٔ عدن است و در مشرق آن حضرموت و در مشرق حضرموت خطه ٔ ساحلی مهره است، در ساحل غربی خلیج فارس رو به شمال غربی ولایت لحساء است، در شمال این ولایت و جنوب بصره ناحیه ٔ کویت است و در وسط قطعه ٔ عربستان میان عمان از طرف مشرق حجاز و از طرف مغرب کویر دهناء است، از جنوب کویر، نفود، و از شمال مملکت نجد و یمامه واقعاند.<br>دولت : در سرزمین عربستان از زمان بسیار قدیم و عهد ماقبل از تاریخ شعبه ای از اقوام سامی ساکن بودند. این قوم که اکنون عرب خوانده میشوند اغلب صحرانشین بودند و بجز در مناطق ساحلی آن و عراق تمدنی وجود نداشت، در این قطعه از قرون بسیار قدیم شاهراهی برای تجارت هند با مصر و سوریه و بابل بود و با دول بزرگی مانند مصر، بابل، فینیقیه و یهود مراوده داشتند و امتعه ٔ ممالک دوردست را بخود جلب میکردند و بدین طریق عمان، شرق عربستان، حضرموت و سواحل جنوبی یمن راه تجارتی بود و بدین جهت در جنوب و جنوب غربی عربستان در عصر بسیار قدیم دول متمدن عربی نژاد تشکیل شدند مانند سلطنتهای معین و سبا و حضرموت و قتبان و بویژه معین مرکز عمده تجارت بود و برای تأمین راه تجارت به شمال در خط تجارت خود نفوذی پیدا کرده بودند.<br>سلطنت معینی ظاهراً قدیمترین دول متمدن عربستان بوده است و پیش از قرن هشتم قبل از میلاد تمدنی کافی داشتند.و دولت مهمی تأسیس کرده بودند که کتیبه ها و آثار زیادی از آن به دست آمده است . این مملکت عبارت از قسمت شمالی و شرقی یمن و قسمت جنوبی عربستان و مشرق آن خطه بود و شهر عمده آن معین (معان ) و پایتخت آن شهرهای قرنا (قرنه = سوداء) و یثیل (براقش ) بوده است که در شمال شرقی صنعاء امروزی واقع بود، ابتداء و انتهای این دولت بدرستی معلوم نیست، برخی ابتدای آن را ازدو هزار سال قبل از میلاد میدانند و انقراض آن را درقرن نهم قبل از میلاد و برخی ابتدای آن را قرن دوازدهم و انتهای آن را قرن نهم قبل از میلاد میدانند. در جنوب شرقی مملکت معین سلطنت قتبان بوده است که با حکومت معین هم عصر بود. این دولت تا استیلای حمیریها درسال <span class=\"hlight\" dir=\"rtl\">١١٥</span> ق . م . وجود داشت و پایتخت آنها تِمنَع یا تمناء در جنوب شرقی یا غربی مأرب بوده است . سلطنت حضرمَوْت نیز با معین هم عهد بوده آنان در اقصی نقاط جنوب عربستان حکومت میکردند. باری پای تخت این دولت ثبوه بود این دولت تا <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> ق . م . به دست حمیریها برافتاد. سلطنت سبا بدو دوره تقسیم میشود. ابتدا از سال تأسیس تا <span class=\"hlight\" dir=\"rtl\">٥٥٠</span> ق . م . که سلطنت در دست کهنه بود و دوم از اواسط قرن ششم ق . م . تا انقراض که سلاطین مقتدر حقیقی بودند. در دوره اول پایتخت آنها صرواح بوده است . در سال <span class=\"hlight\" dir=\"rtl\">١١٥</span> ق . م . قوم حمیر که از اقصای جنوب عربستان بودند ابتدا بر ممالک قتبانی و بعد بر سبا تسلط یافتند و سلاطین آنها را تبع نامیدند و بعدها سلاطین حضرموت سباویمنه نامیده شدند.<br>در قرن دوم مسیحی حبشیها به ممالک حمیریها استیلا یافتند و مبشرین مسیحی مسیحیت را داخل در یمن کردند و کلیساها بنا کردند و در این مدت تحولاتی نیز پدید آمد. حمیریها که از تسلط حبشیهای مسیحی و بیگانه به خاک خود ناراضی بودند به دربار ایران استغاثه و از نوشروان استمداد نمودند دولت ایران درحدود سال <span class=\"hlight\" dir=\"rtl\">٥٧٠</span> م . به یمن لشکرکشی کرد و حبشی ها را شکست داد و سرانجام ایرانیان در یمن حکمرانی کردند. دربعضی از نواحی دیگر سرزمین عربستان نیز حکومتهائی بودند مثلاً در تمام خلیج عقبه و شمال شرقی شبه جزیره سینا از قرن چهارم ق . م . نبطی ها دولت متمدنی داشتند و این مملکت مرکز تجارت بود و بعدها بتمام اراضی سرحدی میان شامات و عربستان از فرات تا دریای سرخ اسم نبطی داده شد و پایتخت آن پترا بود و دارای زبانی خاص بودند. و در شمال العلاء تمدن ثمودی واقع بود در شمال شرقی حجر در <span class=\"hlight\" dir=\"rtl\">١٤</span> فرسخی تیما واقع است که مرکز تمدنی بسیار قدیم بود که نفوذ بابلی و آرامی در آنجا پیدااست و در سال <span class=\"hlight\" dir=\"rtl\">١٩٢</span> - <span class=\"hlight\" dir=\"rtl\">٢١١</span> م . شهر تدمر به دست امپراطور روم بود و پس از شکست روم از شاپور اول پادشاه ساسانی در سال <span class=\"hlight\" dir=\"rtl\">٢٦٠</span> م . ایرانیان شمال سوریه و آسیای صغیررا گرفتند. گذشته از دول و نواحی متمدن عربی، مردم عربستان بر دو نوع بودند، بادیه نشین و حضری . حضریها اگرچه شهر و قصبه داشتند ولی در درجه ٔ ابتدائی بودندو بدویها از هر جهت آنها را احاطه کرده بودند و با آنها مخلوط بودند در سرحدات عربستان این حضریها تحت نفوذ دول متمدن بزرگ دولی نیم متمدن بوجود آوردند تااعراب بدوی را تحت نفوذ خود آرند و بطور کلی خطه ٔ عربستان در تحت نفوذ سه دولت ایران، روم و حبشه بود. مشرق و شمال شرقی آن زیر حمایت دولت ایران و شمال غربی تابع روم و قطعات مرکزی و جنوب زیر نفوذ حبشه بودند و بالجمله از مجاورت و معاشرت با این دول، دول نیمه متمدنی بوجود آمد که هر کدام تابع دولت متمدنی بود بدین طریق حیره و غسان و کنده تحت نفوذ ایران و روم و یمن بودند، مملکت حیره از اواخر قرن سوم تا <span class=\"hlight\" dir=\"rtl\">٦٠٢</span> م . ادامه داشت سدی میان ایران و اعراب بادیه بود و در زیر سلطنت ملوک لخمی ها بودند این مملکت بتدریج وسعت یافت و از فرات تا نجد امتداد یافت و قریب <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> سال لخمی ها سلطنت کردند، سلاطین حیره که دست نشانده ٔ ایرانیان بودند غالباً با دولت روم و ملوک غسان که تابعروم بودند زد و خورد داشتند سلاطین غسان حدود <span class=\"hlight\" dir=\"rtl\">٦٠٠</span> م .در سرزمین حوران و جنوب غربی آن در اراضی بلقاء و جولان سلطنت داشتند و تحت حمایت روم بودند آنان بعداً بواسطه ٔ پیش آمدهائی با ایرانیان همدست شدند و در سال <span class=\"hlight\" dir=\"rtl\">٦١٤</span> م . که خسروپرویز دمشق را گرفت سلطنت غسانیان پایان یافت . ملوک کنده در مرکز عربستان و نجد و یمامه سلطنت داشتند و در <span class=\"hlight\" dir=\"rtl\">٤٨٠</span> م . تمام قبائل نجد از جنوب تاشمال در زیر لوای کنده متحد شدند. قسمت مهم سرزمین عربستان در طول تاریخ موطن بابلیان، آشوریان فینیقیان و عبرانیان و سپس عناصر یهود و مسیحیت بوده است و بنا بر تحقیق عرب همان نژاد سامی است پس از ظهور اسلام مهد و محل تمدن اسلامی گردید و دگرگونی خاص در اوضاع اجتماعی آنجا پدید آمد. برخی گویند موطن اصلی نژادسامی افریقای شرقی است و برخی دیگر گویند موطن اصلی این نژاد عراق است . ولکن قول محقق این است که موطن اصلی این نژاد شبه جزیره ٔ عرب است و چنانکه از منابعتاریخی به دست آید در حوالی سال <span class=\"hlight\" dir=\"rtl\">٣٥٠٠</span> ق . م . مردمی از نژاد سامی از راه شرق افریقا مهاجرت کردند. و به طرف شمال سرازیر شدند و با سکنه ٔ مصر که حامی نژاد بودند اختلاط پیدا کردند و در حوالی نیمه ٔ هزاره سوم ق .م . مردم سامی نژاد مهاجرت دیگر را شروع کردند.<br>مردم عربستان : مردم عربستان دو دسته اند یک دسته شهرنشین و دسته دیگر بادیه نشین، و این امر از قدیم الایام حتی تاکنون موجب شده است که حدود حقیقی مردم عربستان معلوم نگردد. شغل مردم عربستان زراعت و تربیت شتر و تجارت بوده است البته خصوصیات روحی و اقتصادی آنها برحسب مناطق مختلف فرق میکند. بسیار از مردم سرزمین عربستان هنوز در حالت نیم بداوت زندگی میکنند و آثار تمدن کمتر در آنجا نفوذ کرده است . باستثنای مردم شهرنشین مکه و مدینه و یمن و صنعا وعدن که تا اندازه ای باز هم بتفاوت با اوضاع تمدن امروزی آشنائی دارند و تحت تأثیر و نفوذ تمدن واقع شده اند. مردم ده و بادیه نشین اغلب همان حالت و روحیات بداوت را حفظ کرده اند مردم قصیم از لحاظ اخلاقی نرم ترو ملایمترند تا مردم حوالی یمن و عدن و مردم ریاض ازبعضی جهات دارای ظرافت خاصی میباشند. بطورکلی مردم عربستان بافتخار گذشته ٔ خود و نژاد خود هنوز هم میبالند و حتی برخی از آن نواحی مانند قصیم خود را از سایرین برتر و مقدم میدارند و مردم عارض خود را از لحاظ شجاعت مقدم میدارند و مردم بحرین خود را از مردم کویت برتر می دارند.<br>زندگی بدوی : گذشته از مراکز مهم و شهرهای عربستان مردم بدوی هنوز هم به زندگانی بدوی خود و چادرنشینی آن چنان عادت کرده اند که حاضر بترک آن نمی باشند. زندگی بادیه نشینی که شامل بسیاری از سکنه ٔ عربستان است بدین طریق است که مردم همواره در سیر آفاق اند و طبق فصول مختلف منطقه هائی را که مناسب با زیست و زندگی آنها و احشام آنها است انتخاب مینمایند بدانجا کوچ میکنند و هر سرزمین که در فصول مختلف مستعد زندگی باشد اشغال میکنند یک منطقه ٔ مستعد برای زندگی مردم بادیه نشین منطقه ای است که مرتع کافی برای احشام و اغنام آنان داشته باشد این مردم علاوه بر تربیت مواشی و احشام در گذشته از راه چپاول و غارت اموال دیگران نیز زندگی میکردند. سر و کار مردم بادیه نشین با شتر، بیابان قفر و خرماست مردم بادیه نشین در حفظ رسوم و عادات قومی خود سخت پایبند میباشند. بجز قسمتی از جزیرةالعرب بقیه ٔ نقاط آن مسکونی است و مع ذلک اکثر مناطق آن حاره است و مردم آن سرزمین بواسطه ٔ زیادی حرارت که موجب از بین رفتن میکربهاست دارای عمر درازی هستند. بویژه در مناطق سرسبز و حاصل خیز آن که عمرهای مردم درازتر است .<br>بارندگی و آب : بارندگی درحجاز بسیار کم است و درجه ٔ حرارت آن سرزمین زیاد است . حد متوسط حرارت سرزمین یمن <span class=\"hlight\" dir=\"rtl\">٨٠</span> - <span class=\"hlight\" dir=\"rtl\">٩٠</span> است و هوای آن مرطوب است . در مدینه حرارت از <span class=\"hlight\" dir=\"rtl\">٧٠</span> تجاوز نمی کند و طائف بهترین مناطق حجاز است از لحاظ آب و هوا، در سرزمین عربستان انهار بمعنی معروف در کشورهای دیگر وجود ندارد. لکن بعضی از مجاری یا نهرهای کوچک دائم الجریان در یمن و عدن، و لحساء و عمان و نجد و جز آنها وجود دارد که در آنها آب جریان دارد. این گونه نهرها طولانی ولی کم عمق اند و طولانی ترین آنها وادی الرمة است که از نزدیک مدینه شروع میشود و از قصیم میگذرد. و دیگر وادی حنیفه است که از آب ریزهای کوههای غربی آب گرفته و به نزدیکهای خلیج فارس منتهی میشود، اما وادی هائی که به طرف بحر احمر جریان دارند عمق زیادتری دارند.<br>نسب : در میان اعراب مسأله ٔ نسب اهمیتی عظیم داشته و هنوز هم تا حدی دارد و دانستن نسب قبائل و اشخاص فن مهمی در میان آنها بود، دست نسب شناسان عرب تمام قبایل و تیره ها وشاخه های آنها را شرح میدادند و ضبط میکردند و اگرچه نسب نامه بعد از اسلام مدون گردید، لکن قسمت عمده ٔ آنها از محفوظات و روایات سینه به سینه بوده است . بطورکلی نسب شناسان، اعراب را بدو شجره ٔ بزرگ تقسیم کنند: عربهای جنوبی از یمن و عربهای شمالی، که اول را به قحطان و دوم را به عدنان میرسانند و عربهای قحطانی و عدنانی می نامند. عربهای یمن اعم از حمیریها سبائیها و معینی ها و قتبانیها و حضرموتیها و عربهای بدوی آن مملکت که به بنوکهلان معروف هستند عرب اصلی بوده اند (عرب عاریه ). و همین طور طوائف منقرض شده عاد و ثمود، طسم، عرب مستعربه اند یعنی اصلاً از نژاد عرب نمی باشند و در عرب مستهلک شده اند. بطور کلی قبائل قدیم عرب عبارت بوده اند از: غسانیها، لخمیها، کندیها، طی، عامله، جذام، ازد، تنوخ، خزاعه، بنوجرهم، خزرج، که عربهای جنوبی و قحطانی اند. بعضی مردم و سکنه ٔ عربستان را به چند دسته و طبقه تقسیم کرده اند: <span class=\"hlight\" dir=\"rtl\">١</span> - عرب بائده . <span class=\"hlight\" dir=\"rtl\">٢</span> - عرب عاریه . <span class=\"hlight\" dir=\"rtl\">٣</span> - عرب مستعربه . و از لحاظ نسبت ابتداء به دو قسم قحطانیه و عدنانیه تقسیم کرده اند، مسکن قحطانیه یمن و عدنانیه حجاز است و گویند عرب قحطانی اصل اند و عدنانیه فرعند که عربیت را از قحطانیه گرفته اند. شکی نیست که عرب جاهلیت اهمیت خاصی به انساب میدادند و آن یکی از افتخارات عرب و قبائل بشمارمیرفت، مستشرقین به این موضوع که عرب را به قحطانیه و عدنانیه تقسیم کرده اند توجهی خاص کرده اند. نسابون اقدم طبقات عرب را به ابناء سام نسبت داده اند و اسماء ابناء سام را از تورات نقل کرده اند. در مسأله ٔ انساب و طبقات عرب از کتاب مقدس عهد عتیق بسیار استفاده شده است . از جمله قبائل عرب قدیم که در قرآن و تورات آمده است : عاد، ثمود، طسم، جدیس، امیم، جاسم، هود، عبیل، عبدضخم، عمالقه، قوم نوح اند ولی اکثر در وجود این طبقات شک کرده اند.<br>قبیله : نظام قبیله در اجتماعات بدوی اصل اجتماع آنها را تشکیل میدهد چند خیمه را حی نامیده اند و اعضاء یک حی را قوم نامند. افراد یک قوم مردم خود را یک خون دانسته و نسبت بیک رئیس که از میان خود برمیگزیده اند خاضع بودند، معمولاً رئیس مسن ترین آنها بود و هر قومی با اضافه کردن کلمه ٔ بنی به اسم، مشخص میشدند. هرخیمه بامتاع مختصری که در آن هست ملک یک فرد است لکن آب و مرتع و زمین زراعی ملک مشاع برای قبیله است . رئیس را شیخ مینامیدند و او مسن ترین اعضاء قبیله بوده و سمت زعامت داشته است . علاوه بر رعایت سن باید دارای صفات بارز شجاعت و درایت و شخصیت خاص و مورد پسندباشد. وی موظف بود در کلیه شؤون افراد قبیله از امور قضا و جنگ و دفع منازعات دخالت کند، و باید قبل از تصمیم با زعماء قوم مشورت کند و مادام که مردم از او راضی بودند بدان سمت باقی می ماند.<br>عصبیت : یکی از امور مهمی که در قبائل بدوی رعایت آن میشده است روح عصبیت در افراد قبیله بوده است، بطوری که هر فرد خود را فدای قبیله میدانست و بالاخره اصل، قبیله بوده است و افراد مستهلک در قبائل بوده اند البته در این مورد تحولاتی نیز پیدا شده است .<br>قصاص : اعراب بدوی از قدیم الایام بر این بودندکه خون را باید با خون شست و هیچ نوع کیفر دیگری راقبول نداشتند و در این میان بعد از قاتل نزدیک ترین فرد به قاتل مسؤول بوده است و گاه اقرباء مقتول تا <span class=\"hlight\" dir=\"rtl\">٤٠</span> سال دست از خونخواهی برنمی داشتند و در فکر انتقام بودند.<br>دین اعراب قدیم : دین عرب مکه اصلاً ستاره پرستی و رب النوع پرستی و بظاهر بت پرستی بود و بتهای سنگی و چوبی که هر یک مظهری از امور معنوی بودند میپرستیدند مانند «ود» که مظهر ماه بود و هبل خدای بزرگ مکه و بعل، لات، منات، سواع، یعوق، یغوث، نصر. این وضع البته به دست توانای حضرت رسول اکرم (ص ) درهم ریخته شد و مردم را به یهوه خدای یگانه که اﷲ گفته شد دعوت فرمودند و مهمترین مبارزات اولیه ٔ حضرت رسول همین بود.<br>خدایان قدیم : خدایان قدیم عربستان عبارتند از صدی، ضرا، صمو، هباء، عزا، طوطمیه، ذات انواط که درخت معروفی است، ذوالخلصة که خانه ای بوده در قریه ٔ ثروق که عرب مانند مکه آن را متبرک میدانستند، سعد که سنگ بزرگی بوده است بساحل جده، بعل، مردوخ وأنو که ارباب بابلیان بوده است و نیز هبا، ثالوث، ینبو، عشتار، لاتو، مامناتو.<br>خدایان یهود: خدایان عرب یهود مذهب عبارتند از خدای یمن، استار، ود، نانکروب، شمس، انومائی، هوباس، و ... از خدایان بزرگ آنها هبل (بت بزرگ ) لات مناة، ودّ، قزح است ... (از الاساطیر العربیة. محمد عبدالسعیدخان ).<br>محصولات : خشکی هوای عربستان و شوره زار بودن خاک آن مانع اساسی برای سرسبز شدن این سرزمین است . مهمترین محصولات عربستان بدین قرار است، حجاز: خرما. یمن : گندم و جو. عمان ولحساء: برنج و ذرت و صمغ عربی و قهوه و زغال . شام : انگور، کشمش، زیتون، انار، سیب، زردآلو، پرتقال، لیمون، نی شکر، خربوزه، موز. و میوه های دیگر که هر یک مخصوص منطقه ای معین است . در بین اعراب مهمترین درختها درخت خرماست چنانکه مهمترین حیوانات شتر است .<br>حیوانات : بطورکلی از امثله و اخبار عرب برمی آیددر سرزمین عربستان پلنگ، گرگ، روباه، شیر، کرگدن، عقاب، باز، بوم، کلاغ، هدهد، قبرة، بلبل، کبوتر، کبک، قطا، شتر، الاغ، سگ، اردک، گوسفند، قاطر، ملخ و جز آنها وجود دارد و اسبان عربی مشهور است .<br>خانه ٔ کعبه و ولایت آن : ولایت کعبه را ابتدا اسماعیل بن ابراهیم بعهده داشت و بعد از مرگ او ثابت بن اسماعیل و سپس بترتیب مفاض بن عمروالجرهمی، عمروبن حارث الغسان، خلیل بن حبضه، غوی بن مربن اد، قصی بن کلاب، عبدالدار، هاشم بن عبدمناف، عبدالمطلب، عباس بن عبدالمطلب، عهده دار ولایت کعبه بودند. (رجوع به تاریخ ادبیات ایران ص <span class=\"hlight\" dir=\"rtl\">٦٢</span>، <span class=\"hlight\" dir=\"rtl\">١٠٥</span>، ایران در زمان ساسانیان، صص <span class=\"hlight\" dir=\"rtl\">٨٠</span> -<span class=\"hlight\" dir=\"rtl\">١٠٣</span>، عرب قبل از اسلام تقی زاده و مقدمه ٔ ابن خلدون شود.)<br>صنایع: صنایع آنها عبارت است از ریخته گری، تجارت، آهنگری، بیطاری، حجامت، فصد و جز آن . مردم عربستان بطور عموم اشتغال به صنعت را زشت میدانستند و کسانی که بدین گونه کارها اشتغال داشته اند یا از ملت غیرعرب بوده اند یا از مردمی که رعایت اصول نژادی را نکرده اند و این گونه افراد مورد سرزنش و حقارت بوده اند. از صناعات و اشتغالات مشهوری که عرب بدوی بدان اشتغال داشته است غواصی لؤلؤ است که قواعدی خاص برای این کار داشته و نظامات معینی مقرر بوده است که از حد آن تجاوزنمی شد.<br>طب و بهداشت : مردم عربستان کمتر توجه به طب داشتند و مطابق همان اصول قدیم مریضهای خود را معالجه میکردند و البته در میان مردم صحرانشین از قدیم الایام نوعی از بهداشت و طبابت خانگی وجود داشته است که ظاهراً اصالت عربی دارد. گو اینکه قسمتهای بسیاری از آن را در اثر رفت و آمد و معاشرت با مردم دیگری از ملت های بیگانه گرفته اند، البته اکنون در بسیاری از شهرهای عربستان مدارس طب تأسیس شده است و به طب جدید هم آشنائی دارند.<br>علوم و معارف : چنانکه از بعضی از خانواده های علمی نجد و احساء صرف نظر کنیم میتوانیم بگوئیم بلاد عرب خالی از مدارس بمعنی خاص بوده است و در دوران بسیار قدیم و قبل از اسلام اصولاً توجهی به این قسمتها نمی شده است و مجموعه ٔ هنر آنها تفاخر به ملیت و سرودن اشعار ملی بوده است که حاکی از برتری نژادی و قومی میباشد و بجز بعضی از نواحی آن که از پرتو علوم و معارف ایرانی مستفیض بوده اند، خود دارای مدارس قابل توجهی نبوده اند. پس از ظهور اسلام و تحریض و تحریک بر علم و معرفت به این قسمتها نیز توجه شد و بوسیله ٔملتهای دیگر بویژه ایرانیان اقدام به تأسیس مدارس و مساجدی گردید که علوم دینی و تفسیر و فقه و حدیث در آنها تدریس میشد در دوره های اخیر نیز با کوشش زیادی مدارس به سبک جدید کم و بیش رایج گردید و در این راه قدمهای مؤثری برداشته شده است .<br>علماء عربستان : علماء عربستان در دوره ٔ اسلامی مانند سایر کشورهای اسلامی عبارت بوده اند از علماء دینی که عمده اشتغالات آنها تفسیر و فقه و حدیث و اصول بوده است و احیاناً در میان آنها دیده میشودکه کسانی به فلسفه و علوم ریاضی نیز توجه داشته اند همزمان با تحولاتی که در دنیا بوجود آمد و در رشته های مختلف نیازمندیهایی پیدا شد متدرجاً و به طور آرام نیز ثمره ٔ تمدن علمی امروزی در کشورهای عربی کم و بیش نمودار شده است نهایت آنکه آنان را در مراتب تمدن با ملل همجوار خود به سبب تفاوت مناطق اختلافاتی مشاهده میشود.<br>کرم : یکی ازصفات بارز و نمودار مردم عربستان در عرب جاهلیت و به نحو عاقلانه تری در اسلام کرم و جود و جوانمردی و مهمان نوازی بوده است که عرب همواره بدان افتخار میکند مضیف های متعدد در تمام مناطق و شهرها و حتی میان چادرنشین ها وجود داشته است که در آنها از واردین پذیرائی میشده است . مردم عربستان سخی و دست و دل باز و منیعالطبع و جوانمرد بوده اند و این صفت یکی از صفات بارزه و ممتازه ٔ آنها به حساب می آید. در این مورد قصه ها و حکایتهای شیرین وجود دارد که نمودار کرم و اخلاق و فتوت آنهاست .<br>زن : در سرزمین عربستان توجه خاصی به آموزش زن حتی در دوره ٔ اسلام نداشته اند و بجز قرائت قرآن و فرا گرفتن مسائل مذهبی علوم و فنون دیگررا برای زن مجاز نمی دانستند این وضع کم و بیش در کشورهای دیگر مسلمان نیز وجود داشته است .<br>القاب : ق یکی از مسائل مورد توجه و مهم عرب جاهلی انتخاب القاب و انتسابات است که مایه فخر آنها محسوب میشد و هر طایفه و قومی را لقبی بوده است، اشخاص سرشناس و رجال آنها نیز برای خود القابی داشته اند و در این مورد وضع خاصی داشتند که بطور آزادانه هر نوع لقب و کنیتی را بدیگری میدادند و برخی را فقط به نام میخواندند و امرا و ملوک خود را به القاب و اسماء خاص نام میبردند مانند ملک، عبدالعزیز، طویل العمر، شیخ، امام، و از جمله القاب عبدالعزا، عبدمناف، عبدالدار و غیره بوده است . کنیه ها معمولاً با اب و ام شروع میشود. مانند ابوعبداﷲ، ابودرداء ابوجعفر و ام لیلی، و ام سکینه ... و نمودار انتساب خاص است .<br>مساوات : اگر تفاخر و تفاضل و انتسابات اقوام عرب را ندیده بگیریم تقریباً مردم عربستان از لحاظطبقاتی خود را مساوی یکدیگر میدانستند نهایت خود رااز سایر نژادها برتر می شمردند ولکن فضل و برتری در میان خود آنها نبود برتری خاصی برای افراد و مقامات قائل نبودند اعم از حاکم و رعیت و حتی در دوره های اسلامی این معنی محقق شد که بموجب آیه ٔ شریفه «ان أکرمکم عنداﷲ اتقی̍کم » (قرآن <span class=\"hlight\" dir=\"rtl\">١٣/٤٩</span>)، هیچ فردی اعم از مالک و مملوک، حاکم و امیر و جز آنها بر دیگری برتری نداشت و چنانکه حاکمی اجحاف میکرد مانند افراد عادی مورد سیاست شرعی واقع میشد البته این وضع تا اندازه ای از ثمرات تساوی خاص اسلامی است .<br>نظر اجمالی به اوضاع عربستان بعد از اسلام : مقارن با ظهور اسلام آشفتگی خاصی در خطه ٔ عربستان حکومت میکرد ظهور اسلام یکی از حوادث مهمی است که تاریخ ملت عرب و بلکه بسیاری از ملل دیگر را دگرگون کرد و سرزمین های زیادی را از نظر جغرافیائی و اجتماعی واژگون نمود. بسیاری از سرزمین ها که از لحاظ زبان و عادات و رسوم با اعراب تفاوت کلی داشت بر اثر تعالیم اسلامی و تسلط اعراب بر آنها رنگ عربیت به خود گرفت بطوری که در قرون و اعصار بعدی آنها را جزء کشورهای عربی به جساب آوردند. اسلام برای ملت عرب با رهبری ملتهای دیگر چون ملت ایران تمدنی بساخت و آنان را به نظم و ترتیب اداری و کشورداری آشنا ساخت . (از الاساطیر العربیة تألیف محمد عبدالسعیدخان، تاریخ العرب محمد مبرول نافع -مصر <span class=\"hlight\" dir=\"rtl\">١٩٥٣</span> م .) (از پرویز تا چنگیز تألیف تقی زاده ) (تاریخ العرب قبل از اسلام جواد علی بغداد <span class=\"hlight\" dir=\"rtl\">١٩٥١</span>) (جزیرةالعرب فی القرن العشرین حافظ و هب مصر <span class=\"hlight\" dir=\"rtl\">١٩٥٦</span>) (العراق قدیماً و حدیثاً تألیف سیدعبدالرزاق حتی چ صیدا <span class=\"hlight\" dir=\"rtl\">١٩٤٨</span> م .).<br></font></div>'),
(182150, 'عربستان سعودی', '<span class=\"hlight\">عربستان سعودی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِ ن ِ س َ ]</font></b> (اِخ ) عربستان سعودی یا حجاز در تقسیمات اداری و جغرافیائی امروز به خطه ٔ ساحلی غربی عربستان اطلاق میشود که در کنار دریای سرخ از عسیر (در جنوب )تا منتهی الیه خلیج عقبه (در شمال ) تقریباً بطول هزار و سیصد کیلومتر ممتد شده و عرض آن در پشت ساحل به طرف داخله ٔ عربستان تقریباً از <span class=\"hlight\" dir=\"rtl\">١٨٠</span> تا <span class=\"hlight\" dir=\"rtl\">٢٧٥</span> هزار گز است و محدود است از خاور به خلیج فارس و از باختر به دریای سرخ و از شمال به اردن و عراق و از جنوب به یمن و حضرموت و عمان و <span class=\"hlight\" dir=\"rtl\">٨٩٥</span> هزار میل مربع مساحت دارد. خطه ٔ حجاز یا عربستان مرکب از دو منطقه ٔ طبیعی است : قسمت شرقی که کوهستانی است به عربی، نجد گفته میشود و دیگری غربی که پست و هموار است در طول ساحل، تهامه نامیده میشود. شهرهای مکه و مدینه در قسمت هموار واقع است . حجاز دارای سلسله کوهها است و آنجا بارندگی بسیار کم است ولکن در سواحل آن نسبةً باران زیاد است . آبگیر شهرهای آن همه از سیل های زمستانی است . شهرهای مهم این کشور: ریاض، ظهران، مدینه است . این کشور دارای منابع نفت سرشار است و نفت مهمترین منبع درآمد آن محسوب میشود و از راه حاج ّ که به زریات مکه ٔ معظمه میروند نیز سالیانه درآمد قابل توجهی دارد. در نواحی شمالی عربستان سعودی به سبب بودن آب، باغها و قراء مسکونی بسیار است و آنجا حبوب و سبزیجات نیز کاشته می شود. شغل مردم نواحی دیگر تربیت احشام و گله داری و شترداری است . نوع حکومت این کشور اکنون سلطنتی موروثی است و از خانواده ٔ شریف اند. منصب شریف مکه از مناصب محترم دولت عثمانی بود. در سال <span class=\"hlight\" dir=\"rtl\">١٩٠٨</span> م . که دولت عثمانی به صورت حکومت مشروطه سلطنتی درآمد. شریف حسین بن علی را حاکم مکه نمود و سرانجام به سال <span class=\"hlight\" dir=\"rtl\">١٩١٦</span> استقلال یافت و شریف حسین بعنوان پادشاه آن سرزمین شناخته شد لکن دیری نپائید که حکومت وی به دست عبدالعزیزبن سعود منقرض گردید و خود رسماً پادشاه آن سرزمین شدو در تاریخ <span class=\"hlight\" dir=\"rtl\">١٩٣٢</span> بر تمام سرزمین حجاز تسلط یافت و سرزمین خود را بنام المملکة العربیة السعودیة اعلام کرد وی فرزند خود امیرسعود را در <span class=\"hlight\" dir=\"rtl\">١٣٥٢</span> هَ . ق . به ولایت عهد منصوب کرد و در هشتم ربیعالاول <span class=\"hlight\" dir=\"rtl\">١٣٧٣</span> هَ . ق . درگذشت و ولی عهد او بنام «ملک سعود» بر تخت نشست و بعداز او ملک فیصل، برادر او. جمعیت این کشور در حدود دو میلیون و نیم است که عده ای از آنها شهرنشین اند اما زندگی اکثر آنها هنوز بر اساس صحرانشینی است و اینان طوائف و قبائل مختلفی تشکیل میدهند که مهمترین آنها عبارتند از: مطیر، عتیبة، بنی سلیم، قریش، هذیل، ثقیف، البقوم، عدوان، بنی حارث، بنی لحیان، بنی سعد، جحادلة، نخاولة. رجوع به عربستان و رجوع به حجاز شود.<br></font></div>'),
(182151, 'عربسوس', '<span class=\"hlight\">عربسوس .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (اِخ ) شهری است سرحدی، بنزدیک مصیصة، سیف الدولةبن حمدان به غزو آنجا شده است . (از معجم البلدان ).<br></font></div>'),
(182152, 'عربسیس', '<span class=\"hlight\">عربسیس .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ب َ]</font></b> (ع اِ) عربس . (اقرب الموارد) (منتهی الارب ). رجوع به عربس شود. <BR><font color=\"Blue\">◄</font> داهیة. (اقرب الموارد).<br></font></div>'),
(182153, 'عربشاه', '<span class=\"hlight\">عربشاه .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) ابن محمد حسین . رجوع به این عربشاه و فهرست کتابخانه ٔ مدرسه ٔ سپهسالار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨٣</span> شود.<br></font></div>'),
(182154, 'عربشاه', '<span class=\"hlight\">عربشاه .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی از دهستان سیاه منصور شهرستان بیجار، کوهستانی . سکنه آن <span class=\"hlight\" dir=\"rtl\">٨٥</span> تن . محصولات آنجا غلات، لبنیات . صنایع دستی زنان قالیبافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(182155, 'عربشاه', '<span class=\"hlight\">عربشاه .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی از دهستان چهار اویماق بخش قره آغاج، شهرستان مراغه . ناحیه ای است کوهستانی <span class=\"hlight\" dir=\"rtl\">٢٤٦</span> تن سکنه دارد. شغل اهالی زراعت است . صنایع دستی جاجیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(182156, 'عربشاه خان', '<span class=\"hlight\">عربشاه خان .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی است از دهستان گرمادوز، بخش کلیبر شهرستان اهر. ناحیه ای است کوهستانی .هوای آن معتدل مایل به گرمی است . با <span class=\"hlight\" dir=\"rtl\">٥٠١</span> تن سکنه . شغل اهالی زراعت و گله داری است . صنایع دستی آنها گلیم و جاجیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(182157, 'عربشاه خرگوشان', '<span class=\"hlight\">عربشاه خرگوشان .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ خ َ ]</font></b> (اِخ ) دهی است از دهستان گرمادوز بخش کلیبر شهرستان اهر. ناحیه ای است کوهستانی <span class=\"hlight\" dir=\"rtl\">٤١٨</span> تن سکنه دارد. آب آن از دو رشته چشمه تأمین میشود. شغل اهالی زراعت و گله داری است . صنایع دستی فرش و گلیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(182158, 'عربشه', '<span class=\"hlight\">عربشه .</span> <font color=\"DarkGreen\"><b>[ ع َرَ ش َ ]</font></b> (اِخ ) دهی است از دهستان لک بخش قروه ٔ شهرستان سنندج، ناحیه ای است جلگه، <span class=\"hlight\" dir=\"rtl\">١٦٠</span> تن سکنه دارد. شغل اهالی زراعت و گله داری است . صنایع دستی زنان قالیچه و جاجیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(182159, 'عربض', '<span class=\"hlight\">عربض .</span> <font color=\"DarkGreen\"><b>[ ع ِ ب َ ]</font></b> (ع ص ) شیر گران جسم تندار. (منتهی الارب ). شیر گران و بزرگ جثه ٔ پهن سینه . عرباض . <BR><font color=\"Blue\">◄</font> درشت و استوار و توانا از مردم و شتر. (منتهی الارب ) (از اقرب الموارد). عرباض . (اقرب الموارد). و رجوع به عرباض شود. <BR><font color=\"Blue\">◄</font> عریض . (اقرب الموارد). پهن از هر چه باشد. (منتهی الارب ).<br></font></div>'),
(182160, 'عربلو', '<span class=\"hlight\">عربلو.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی است از دهستان چهاربلوک بخش سیمینه رود شهرستان همدان، کوهستانی . <span class=\"hlight\" dir=\"rtl\">٢٤٤</span> تن سکنه دارد. شغل اهالی زراعت و گله داری است . صنایع دستی قالیبافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(182161, 'عربلو', '<span class=\"hlight\">عربلو.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی است از بخش سراسکند شهرستان تبریز. کوهستانی، <span class=\"hlight\" dir=\"rtl\">١٩٢</span> تن سکنه دارد، آب آن از چشمه تأمین میشود. شغل اهالی زراعت و گله داری است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(182162, 'عربلو', '<span class=\"hlight\">عربلو.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است از دهستان باراندوزچای . بخش حومه ٔ شهرستان ارومیه . هوای آن معتدل است . <span class=\"hlight\" dir=\"rtl\">١٨٦</span> تن سکنه دارد. شغل اهالی زراعت است . صنایع دستی آنها جوراب بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(182163, 'عربلودره', '<span class=\"hlight\">عربلودره .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ دَرْ رَ ]</font></b> (اِخ ) دهی است از دهستان نازلو بخش حومه ٔ شهرستان ارومیه <span class=\"hlight\" dir=\"rtl\">١٢٥</span> تن سکنه دارد. شغل اهالی زراعت است . صنایع دستی آنها جوراب بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(182164, 'عربلوکندی', '<span class=\"hlight\">عربلوکندی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ک َ ]</font></b> (اِخ ) (نهرسولدوز) دهی است از دهستان مشکین باختری . بخش مرکزی شهرستان خیاو. کوهستانی، <span class=\"hlight\" dir=\"rtl\">١٦٠</span> تن سکنه دارد. شغل اهالی زراعت و گله داری است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(182165, 'عربلوی آقاعلی', '<span class=\"hlight\">عربلوی آقاعلی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ی ِ ع َ ]</font></b> (اِخ )دهی است از دهستان نازلو بخش حومه ٔ شهرستان ارومیه، <span class=\"hlight\" dir=\"rtl\">٧٠</span> تن سکنه دارد. محصولات آن غلات، توتون، کشمش، حبوبات و چغندر است . شغل اهالی زراعت است . صنایع دستی آنها جوراب بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(182166, 'عربلوی میشه', '<span class=\"hlight\">عربلوی میشه .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ی ِ ؟ ]</font></b> (اِخ ) دهی است از دهستان نازلو بخش حومه ٔ شهرستان ارومیه . <span class=\"hlight\" dir=\"rtl\">١١٦</span> تن سکنه دارد. شغل اهالی زراعت است . صنایع دستی آنها جوراب بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(182167, 'عربنة', '<span class=\"hlight\">عربنة.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ن َ ]</font></b> (ع مص ) ربون دادن . (منتهی الارب ) (آنندراج ). بیعانه دادن . عطا کردن عربون . (از اقرب الموارد). رجوع به عربون شود.<br></font></div>'),
(182168, 'عربون', '<span class=\"hlight\">عربون .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ربون . عَربَون . عُربان . (منتهی الارب ). بیعانه . ربون . رجوع به ربون و زبون شود.<br></font></div>'),
(182169, 'عربی', '<span class=\"hlight\">عربی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) محمدبن السائح الرباطی الشرقی العمری التیجانی از مردم قرن سیزدهم هجری است و او راست بغیةالمستفید بشرح منیةالمرید و آن شرحی است بر منیةالمرید شیخ احمد تیجانی در تصوف . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(182170, 'عربی', '<span class=\"hlight\">عربی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) محمد الفاسی . رجوع به عربی ابوحامدبن یوسف ... و معجم المطبوعات شود.<br></font></div>'),
(182171, 'عربی', '<span class=\"hlight\">عربی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) محمدبن عبداﷲ حاتمی طائی است . (منتهی الارب ).<br></font></div>'),
(182172, 'عربی', '<span class=\"hlight\">عربی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) ابوعبداﷲ محمدبن علی بن محمدالعربی . از مردم سمنان و شیخ صوفیه بود. از ابوالقاسم قشیری سماع حدیث کرد و به سال <span class=\"hlight\" dir=\"rtl\">٥٢٨</span> تا <span class=\"hlight\" dir=\"rtl\">٥٢٧</span> درگذشت . (اللباب فی تهذیب الانساب ).<br></font></div>'),
(182173, 'عربی', '<span class=\"hlight\">عربی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) یحیی بن حبیب بن عربی بصری از محدثان بود. از معتمر روایت دارد. عبدالرحمان بن مهدی و جز او از وی روایت کرده اند. (از اللباب ).<br></font></div>'),
(182174, 'عربی', '<span class=\"hlight\">عربی .</span> <font color=\"DarkGreen\"><b>[ع َ رَ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ بخش خورموج شهرستان بوشهر، جلگه و گرمسیر <span class=\"hlight\" dir=\"rtl\">٣٣٢</span> تن سکنه دارد. شغل اهالی زراعت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(182175, 'عربی', '<span class=\"hlight\">عربی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ بی ی ]</font></b> (ص نسبی ) منسوب به عرب . از عرب . عرب عربی، ای بین العروبة و العروبیة. (منتهی الارب ). کسی که نسبت صحیح دارد درعرب هرچند که به شهر آرام گیرد. رجوع به عرب شود.<br>- <span class=\"hlight\">یاء عربی </span> ؛ یاء معروف، مقابل یاء فارسی، یاء مجهول . (یادداشت مؤلف ).<br> <BR><font color=\"Blue\">◄</font> زبان عرب . (یادداشت مؤلف ). یکی از السنه ٔ سامی . (ایران باستان ص <span class=\"hlight\" dir=\"rtl\">١٢</span>). <BR><font color=\"Blue\">◄</font> جوسپید. <BR><font color=\"Blue\">◄</font> خوشه ٔ جو سپید. (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> واحد عِراب . (اقرب الموارد). رجوع به عراب شود. <BR><font color=\"Blue\">◄</font> (اِ) در تداول عامه بگفته ٔ صاحب آنندراج نوعی از پاافزار که تمام پا را می پوشاند و آنرا اجلاف ولایت میپوشند و گوید از اهل زبان بتحقیق پیوسته است . (آنندراج ) <span class=\"hlight\">:</span> <br>عجم است آن عربی دوز و منش هندویم <br>چون کنم یاد از آن مه، عربی میگویم <br>گاه همچون عربی سینه ٔ من سازد چاک <br>سختیان وار گهی تیغ کشد بر رویم <br>بسکه غلطید براهش در اشکم چون گوی <br>تکمه ها بر عربی بست قطار از کویم <br>آبخورد عربی را چو رساند برلب <br>حسرتی میخورم و دست ز جان میشویم .<br><font color=\"Red\">سیفی .</font><br></font></div>'),
(182176, 'عربی', '<span class=\"hlight\">عربی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) نبی عربی . محمد رسول اﷲ (ص ) و فی الحدیث «لاتنقشوا فی خواتیمکم عربیا» یعنی در نگین خود نقش لفظ محمد رسول اﷲ کنده نکنید ... (منتهی الارب ).<br></font></div>'),
(182177, 'عربی', '<span class=\"hlight\">عربی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) ابوحامد عربی بن یوسف بن محمد احمدی . فاضل و از مردم فاس مراکش بود. او راست : عقدالدرر، شرح نخبةالفکر، الطرفة. (از الاعلام زرکلی ).<br></font></div>'),
(182178, 'عربی', '<span class=\"hlight\">عربی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) ابراهیم بن عربی کوفی . راوی است واعمش از وی روایت کند. (اللباب فی تهذیب الانساب ).<br></font></div>'),
(182179, 'عربی', '<span class=\"hlight\">عربی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) قاضی ابوبکر مالکی است . (منتهی الارب ) (لباب الانساب ).<br></font></div>'),
(182180, 'عربی', '<span class=\"hlight\">عربی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) ابوسلمة الزبیربن عربی البصری . وی از ابن عمر روایت دارد و حمادبن زید و معمر ازو روایت کنند. (اللباب فی تهذیب الانساب ).<br></font></div>'),
(182181, 'عربی', '<span class=\"hlight\">عربی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) عبداﷲبن محمدبن سعیدبن عربی الطائفی، راوی است .<br></font></div>'),
(182182, 'عربی', '<span class=\"hlight\">عربی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) حسین بن عربی بصری راوی است . (از لباب الانساب ).<br></font></div>'),
(182183, 'عربی', '<span class=\"hlight\">عربی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) الدرقاوی . ابوعبداﷲ محمدالعربی احمدالحسینی نزیل قبیله ٔ از والیه . متوفی به سال <span class=\"hlight\" dir=\"rtl\">١٣٢٩</span> هَ . ق . از دانشمندان است . (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(182184, 'عربی دان', '<span class=\"hlight\">عربی دان .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (نف مرکب )داننده ٔ عربی . عالم به علوم عرب . واقف به لغت عرب . که فنون و علوم عرب و لغت آن داند. زبان عرب شناس . زبان عرب دان . دانا به لغت تازی . دانشمند به لغت عرب .<br></font></div>'),
(182185, 'عربی دانی', '<span class=\"hlight\">عربی دانی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (حامص مرکب ) عمل عربی دان . دانایی به لغت و ادب و علم عرب . <BR><font color=\"Blue\">◄</font> دانش لغت و علوم و فنون عرب .<br></font></div>'),
(182186, 'عربی زاده', '<span class=\"hlight\">عربی زاده .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب، اِ مرکب ) آنکه نژاد از عرب دارد. زاده ٔ عرب . فرزند عرب <span class=\"hlight\">:</span> <br>مولای من است آن عربی زاده ٔ حُر<br>کاخر بدهان ِ حلو میگوید مر.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(182187, 'عربی وار', '<span class=\"hlight\">عربی وار.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ص مرکب ) همچون عرب . به سان عرب . عرب مانند. عرب کردار. همانند عرب <span class=\"hlight\">:</span> <br>شب عربی وار بود بسته نقاب بنفش <br>از چه سبب چون عرب نیزه کشید آفتاب .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(182188, 'عربی پاشا', '<span class=\"hlight\">عربی پاشا.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) پیشوای انقلاب عربی است . به سال <span class=\"hlight\" dir=\"rtl\">١٢٥٠</span> هَ . ق . در یکی از دهات مصر متولد شد.تحصیلات خود را در مدرسه ٔ الازهر بپایان رسانید. به سال <span class=\"hlight\" dir=\"rtl\">١٢٨١</span> وارد نظام شد و به درجه ٔ قائمقامی رسید در زمان توفیق پاشا فرمانده ٔ قوای جهاد علیه بیگانگان گردید. وی بر خدیو مصر بشورید و سرانجام به دست عوامل انگلستان گرفتار آمد و در محکمه ٔ نظامی به اعدام محکوم گردید و لکن با وساطت خدیو به جزیره ٔ سیلان تبعیدش کردند و در حدود <span class=\"hlight\" dir=\"rtl\">١٩</span> سال در تبعید بود و به سال <span class=\"hlight\" dir=\"rtl\">١٩١١</span> درگذشت . رجوع به اعرابی پاشا و معجم المطبوعات شود.<br></font></div>'),
(182189, 'عربیة', '<span class=\"hlight\">عربیة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ بی ی َ ]</font></b> (ص نسبی ) مؤنث عربی . رجوع به عربی شود. <BR><font color=\"Blue\">◄</font> لغت عرب . زبان عرب . <BR><font color=\"Blue\">◄</font> آنچه عرب بدان سخن گوید و تکلم کند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گاه در کتابهای فارسی پیش از نقل بیت یا قطعه از شعر عرب عربیة نویسند، مقصود از آن شعری عربی یا قطعه ای عربی است . (یادداشت مؤلف ).<br>- <span class=\"hlight\">علوم عربیة</span> ؛ علوم عربی . دانشها که عرب را بود. ادب عرب . ادبیات عرب .<br>- <span class=\"hlight\">نقود عربیة</span> ؛ مسکوک قوم عرب یا ممالک عرب . سکه که نقش کلمات عرب دارد. یا در سرزمین عرب نقش شود یا در سرزمینی که حکومت عرب دارد زده شود. و نیز رجوع به النقود العربیة ص <span class=\"hlight\" dir=\"rtl\">٩٢</span> شود.<br></font></div>'),
(182190, 'عربیة', '<span class=\"hlight\">عربیة.</span> <font color=\"DarkGreen\"><b>[ ع َ بی ی َ ]</font></b> (اِخ ) (بمعنی خشک و بی آب و علف در عبری ) در قاموس کتاب مقدس این کلمه را بجای عربستان و سرزمین عرب آورده است و گوید شبه جزیره ای است که در قسمت جنوبی آسیا فیمابین دریای احمر و دریای هند و خلیج فارس واقع است طولش از جنوب بشمال <span class=\"hlight\" dir=\"rtl\">١٣٠٠</span> میل و عرضش در عریضترین قسمتهایش <span class=\"hlight\" dir=\"rtl\">١٥٠٠</span> میل و در اماکنی که عرضش بدین درجه نرسد تخمیناً <span class=\"hlight\" dir=\"rtl\">٩٠٠</span>میل است و از جمیع اطراف جز شمال، دریا آنرا احاطه کرده است . رجوع به عربستان و قاموس کتاب مقدس شود.<br></font></div>'),
(182191, 'عربیت', '<span class=\"hlight\">عربیت .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ بی ی َ ]</font></b> (ع مص جعلی، اِمص ) عرب بودن . متصف به صفات عرب بودن . <BR><font color=\"Blue\">◄</font> در اصطلاح علوم و ادبیات و زبان عرب گویند: عربیت فلان خوب است یعنی به لغت و علوم عرب آشنا است .<br></font></div>'),
(182192, 'عربیت دان', '<span class=\"hlight\">عربیت دان .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ بی ی َ ]</font></b> (نف مرکب ) این ترکیب را مترجم تاریخ قم بکار برده است بجای عربی دان . مرادف با عالم به ادبیات و علوم عرب و متبحر و حاذق در فنون عربی است <span class=\"hlight\">:</span> ازین بنده ٔ ضعیف نحیف فقیر درخواه کرد که آنرا از تازی با فارسی نقل کند تا چنانچه عربیت دانان از آن مستفید شوند، فارسی خوانان نیز از آن مستفید شوند. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(182193, 'عربید', '<span class=\"hlight\">عربید.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) آنکه بسیار عربده کند. کثیر العربدة. <BR><font color=\"Blue\">◄</font> آنکه جلیس خود را اذیت کند از مستی . (از اقرب الموارد). ستمکار جلیس خود، وقت مستی . (آنندراج ) (منتهی الارب ). و رجل عربید و معربد؛ مردشریر مشاربها. (از اقرب الموارد). بدخوی جنگجوی که شر طلب باشد. و رجوع به عربد و عرابد و معربد شود.<br></font></div>'),
(182194, 'عربیدیه', '<span class=\"hlight\">عربیدیه .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی َ ]</font></b> (اِخ ) دهی است از دهستان خیران بخش مرکزی شهرستان خرمشهر، واقع در یک هزارگزی باختری خرمشهر. خیابان اسفالت گمرک از کنار آن میگذرد. <span class=\"hlight\" dir=\"rtl\">٤٠٠</span>تن سکنه دارد. شغل اهالی تربیت نخل است . صنایع دستی آنها حصیربافی است . راه اتومبیلرو دارد. ساکنین از طایفه ٔ لالات هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(182195, 'عربیلی', '<span class=\"hlight\">عربیلی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) الدکتور ابراهیم یوسف . او راست : حل العقدة بملخص الافادةفی انتاج الاولاد حسب الارادة. (معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(182196, 'عرت', '<span class=\"hlight\">عرت .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) سخت گردیدن نیزه و جنبیدن و لرزیدن . (از اقرب الموارد). درخشیدن . <BR><font color=\"Blue\">◄</font> جنبیدن و لرزیدن و درخشیدن برق . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مالیدن بینی کسی را. (منتهی الارب ) (از اقرب الموارد) (آنندراج ).<br></font></div>'),
(182197, 'عرتبة', '<span class=\"hlight\">عرتبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ب َ ]</font></b> (ع اِ) بینی یا نوک بینی یا گوشه ٔ لب بالایین یا جانب تیزی بینی . (منتهی الارب ) (از اقرب الموارد) (آنندراج ).<br></font></div>'),
(182198, 'عرتم', '<span class=\"hlight\">عرتم .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (ع اِ) نوک بینی . (منتهی الارب ). مابین بینی و لب یا گوشه ٔ لب بالایین . (منتهی الارب ) (آنندراج ). عرتمة. رجوع به عرتمة شود.<br></font></div>'),
(182199, 'عرتمة', '<span class=\"hlight\">عرتمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ م َ ]</font></b> (ع اِ) عرتم . (منتهی الارب ). نوک بینی یا مابین بینی و لب یا گوشه ٔ لب بالایین . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> یقال فعله علی عرتمته ؛ أی علی رغم أنفه . (منتهی الارب ).<br></font></div>'),
(182200, 'عرتن', '<span class=\"hlight\">عرتن .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ت َ ]</font></b> (ع اِ) عَرْتن . رجوع به عرتن شود.<br></font></div>'),
(182201, 'عرتن', '<span class=\"hlight\">عرتن .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ت ُ ]</font></b> (ع اِ) عَرْتن . رجوع به عرتن شود.<br></font></div>'),
(182202, 'عرتن', '<span class=\"hlight\">عرتن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ت َ ]</font></b> (ع اِ) عَرْتن . رجوع به عرتن شود.<br></font></div>'),
(182203, 'عرتن', '<span class=\"hlight\">عرتن .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (ع اِ) عَرَتن . عُرتُن . (منتهی الارب ). گیاهی است که بدان دباغت کننداصل آن عرنتُن و عَرَنتَن بوده است و حرف تاء کلمه سه حرکت گرفته و نون آن حذف شده و به حال خود مانده است . (منتهی الارب ) (آنندراج ). عرتون . (منتهی الارب ). درختی است که بدان دباغت کنند. (از اقرب الموارد).<br>- <span class=\"hlight\">ادیم معرتن </span> ؛ پوست پیراسته به گیاه عرتن که به عرتن دباغت شده باشدو آنرا معرتن گویند و عامل آنرا مُعرتِن . (از اقرب الموارد).<br></font></div>'),
(182204, 'عرتنة', '<span class=\"hlight\">عرتنة.</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ن َ ]</font></b> (ع مص ) پیراستن پوست با گیاه . عرتن . (ناظم الاطباء).<br></font></div>'),
(182205, 'عرتون', '<span class=\"hlight\">عرتون .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) گیاهی است که بدان پوست پیرایند. (ناظم الاطباء). عرتن . رجوع به عرتن شود.<br></font></div>'),
(182206, 'عرث', '<span class=\"hlight\">عرث .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) برکندن . <BR><font color=\"Blue\">◄</font> مالیدن . <BR><font color=\"Blue\">◄</font> برکنده شدن . (منتهی الارب ).<br></font></div>'),
(182207, 'عرج', '<span class=\"hlight\">عرج .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع مص ) رسیدن در پای کسی پس لنگیدن . لنگیدن خلقی نه عارضی . (منتهی الارب ) (از اقرب الموارد). عرجان . لنگی غیرخلقی . (منتهی الارب ). لنگی . (دهار). عَرج . عَرُج . (منتهی الارب ).ماأشد عرجه ؛ یعنی چه لنگ است او، و لایقال ما أعرجه فی التعجب لأن ماکان لوناً أو خلقةً فی الجسد لایقال منه ماأفعله الا مع «أشدّ». <BR><font color=\"Blue\">◄</font> غروب شدن آفتاب یا میل کردن آن به سوی مغرب . (منتهی الارب ).پنهان شدن آفتاب در افق و میل کردن آفتاب به مغرب . (ناظم الاطبا). فروشدن آفتاب . (تاج المصادر بیهقی ).<br></font></div>'),
(182208, 'عرج', '<span class=\"hlight\">عرج .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) کفتار. معرفة ممنوعة الصرف است و آنرا بمنزله ٔ قبیله قرار داده اند. (منتهی الارب ) (از اقرب الموارد). عُراج . (منتهی الارب ). ضبع.<br></font></div>'),
(182209, 'عرج', '<span class=\"hlight\">عرج .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) عَرج . (منتهی الارب ). رجوع به عَرج شود.<br></font></div>'),
(182210, 'عرج', '<span class=\"hlight\">عرج .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) نهر. <BR><font color=\"Blue\">◄</font> وادی بسبب انعراج آن . <BR><font color=\"Blue\">◄</font> (اِمص ) بلندی پا ولنگی آن . بلندی پا نسبت به پای دیگر، یا بسبب برخورد چیزی با آن، جمع کردن آن را. (از اقرب الموارد).<br></font></div>'),
(182211, 'عرج', '<span class=\"hlight\">عرج .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) گله ای از شتران مقدار هشتاد عدد یا از هشتاد تا نود یا گله ٔ صد و پنجاه شتر و اندک بالای آن یا از پانصد تا یکهزار. (از اقرب الموارد) (منتهی الارب ) (از ناظم الاطباء). ج، اَعراج، عُروج . (آنندراج ) (از اقرب الموارد). عِرج . (ناظم الاطباء).<br></font></div>'),
(182212, 'عرج', '<span class=\"hlight\">عرج .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ اَعرج . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ج ِ عَرجاء. (منتهی الارب ). و رجوع به اَعرج و عَرجاء شود.<br></font></div>'),
(182213, 'عرج', '<span class=\"hlight\">عرج .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع ص ) شتر که کمیز کج اندازد. (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(182214, 'عرج', '<span class=\"hlight\">عرج .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) شهری است به یمن . (از منتهی الارب ).<br></font></div>'),
(182215, 'عرج', '<span class=\"hlight\">عرج .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) وادیی است به حجاز که نخلستان بسیار دارد. (منتهی الارب ).<br></font></div>'),
(182216, 'عرج', '<span class=\"hlight\">عرج .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) موضعی است در بلاد هذیل . (منتهی الارب ).<br></font></div>'),
(182217, 'عرج', '<span class=\"hlight\">عرج .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) منزلی است در راه مکه از آن منزل است عبداﷲبن عمروبن عثمان العرجی شاعر. (منتهی الارب ). موضعی است بین مکه و مدینه و عرجی شاعر منسوب بدانجاست .<br></font></div>'),
(182218, 'عرجان', '<span class=\"hlight\">عرجان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ أعرج . (منتهی الارب ) (از اقرب الموارد) (آنندراج ) (ناظم الاطباء). رجوع به اعرج و عُرج شود. <BR><font color=\"Blue\">◄</font> ج ِ عارج . پوشیده . (آنندراج ). رجوع به عارج شود.<br></font></div>'),
(182219, 'عرجان', '<span class=\"hlight\">عرجان .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع مص ) لنگان رفتگی . (منتهی الارب ) (آنندراج ). مشی اعرج . (از اقرب الموارد). رفتار بلنگی . لنگان رفتن . (یادداشت مؤلف ). قزلان . (تاج المصادر بیهقی ). لنگیدن به لنگی خلقی . عَرَج . (ناظم الاطباء). رجوع به عَرج شود.<br></font></div>'),
(182220, 'عرجد', '<span class=\"hlight\">عرجد.</span> <font color=\"DarkGreen\"><b>[ ع ُ ج ُ ]</font></b> (ع اِ) عُرجَد. شاخ کج نخل . (منتهی الارب ). عرجون نخل . عُرجُدّ. عرجود. (اقرب الموارد).<br></font></div>'),
(182221, 'عرجد', '<span class=\"hlight\">عرجد.</span> <font color=\"DarkGreen\"><b>[ ع ُ ج ُدد ]</font></b> (ع اِ) عُرجُد. عرجود. (اقرب الموارد). رجوع به عُرجد شود.<br></font></div>'),
(182222, 'عرجد', '<span class=\"hlight\">عرجد.</span> <font color=\"DarkGreen\"><b>[ ع ُ ج َدد ]</font></b> (ع اِ) عُرجُدَ. شاخ کج خرمابن . عرجون . (ناظم الاطباء). رجوع به عرجون شود.<br></font></div>'),
(182223, 'عرجد', '<span class=\"hlight\">عرجد.</span> <font color=\"DarkGreen\"><b>[ ع ُ ج َ ]</font></b> (ع اِ) شاخ کج نخل . عُرجُد. (منتهی الارب ).<br></font></div>'),
(182224, 'عرجلة', '<span class=\"hlight\">عرجلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ل َ ]</font></b> (ع اِ) گله ٔ اسبان . <BR><font color=\"Blue\">◄</font> گله ٔ بز. <BR><font color=\"Blue\">◄</font> گروه پیادگان روان . (منتهی الارب ) (آنندراج ). گروهی پیادگان . (مهذب الاسماء). گروه مردم . ج، عَراجلة. (ناظم الاطباء).<br></font></div>'),
(182225, 'عرجموس', '<span class=\"hlight\">عرجموس .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b>(اِخ ) دهی است در بقاع بعلبک . (از معجم البلدان ).<br></font></div>'),
(182226, 'عرجنة', '<span class=\"hlight\">عرجنة.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ن َ ]</font></b> (ع مص ) نگار کردن جامه را به نگار عرجون . (منتهی الارب ) (آنندراج ) (ازلسان العرب ). صورتهای عرجون در جامه تصویر کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زدن کسی را به عرجون .(منتهی الارب ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آلودن و طلا نمودن به خون یا به زعفران یا خضاب کردن . (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br></font></div>'),
(182227, 'عرجود', '<span class=\"hlight\">عرجود.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) شاخ کژ نخل . (منتهی الارب ) (آنندراج ). عُرجُدّ. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه از انگور مانند اژخ برآید. (ناظم الاطباء) (از اقرب الموارد). اول آنچه از انگور برآید مانند اژخ . (منتهی الارب ).<br></font></div>'),
(182228, 'عرجوف', '<span class=\"hlight\">عرجوف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) شترماده ٔ درشت تندار. (منتهی الارب ) (آنندراج ) (از اقرب الموارد).<br></font></div>'),
(182229, 'عرجول', '<span class=\"hlight\">عرجول .</span> <font color=\"DarkGreen\"><b>[ ع ِ ج َ ]</font></b> (ع اِ) گروه . (منتهی الارب ) (آنندراج ). گروه و جماعت . (ناظم الاطباء).<br></font></div>'),
(182230, 'عرجوم', '<span class=\"hlight\">عرجوم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) شترماده ٔ درشت استواراندام . (منتهی الارب ) (از اقرب الموارد).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(182231, 'عرجون', '<span class=\"hlight\">عرجون .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) چوب خوشه ٔ خرما. (دهار) (مهذب الاسماء). ج، عَراجین . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> خوشه . خوشه ٔ خرما یا خوشه ٔ خرما که خشک و کج گردد، یابن آن . یا چوب خوشه ٔ خرما. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شاخ خشک شده <span class=\"hlight\">:</span> <br>گر در آبی نخل یا عرجون نمود<br>جز ز عکس نخله ٔ بیرون نبود.<br> <font color=\"Red\">مولوی .</font><br> <BR><font color=\"Blue\">◄</font> بن خوشه ٔخرما. (زمخشری ). شکاوه . (یادداشت مؤلف ). انگون . انگول . (یادداشت مؤلف ). <BR><font color=\"Blue\">◄</font> چوب خوشه ٔ خرما که بشکل داس خمیده میباشد. (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> چوب خوشه ٔ انگور. <BR><font color=\"Blue\">◄</font> درخت کژ شده . (منتهی الارب ) <span class=\"hlight\">:</span> و القمر قدرناه منازل حتی عاد کالعرجون القدیم . (قرآن <span class=\"hlight\" dir=\"rtl\">٣٩/٣٦</span>).<br>ور ز نور آفتابش بهره گیرد خاطرات <br>پیش روشن خاطرت مر ماه را عرجون کنی .<br> <font color=\"Red\">ناصرخسرو.</font><br>رنگ بربسته ترا گلگون نکرد<br>شاخ بربسته فن عرجون نکرد.<br> <font color=\"Red\">مولوی .</font><br><BR><font color=\"Blue\">◄</font> شاخهای بریده از درخت کژ شده .(از منتهی الارب ). ج، عراجین . <BR><font color=\"Blue\">◄</font> گیاهی است شبیه به سماروغ سپید، یا نوعی از سماروغ . (منتهی الارب ) (آنندراج ).<br></font></div>'),
(182232, 'عرجی', '<span class=\"hlight\">عرجی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) شاعری از امویان معاصر ولیدبن یزید. و او راست بیت معروف :<br>أضاعونی و أی فتی أضاعوا<br>لیوم کریهة و سداد ثغر.<br><font color=\"Red\">(یادداشت مؤلف ).</font><br></font></div>'),
(182233, 'عرجی', '<span class=\"hlight\">عرجی .</span> <font color=\"DarkGreen\"><b>[ ع َ جی ی ]</font></b> (ص نسبی ) نسبت است به عرج که موضعی است به مکه . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣١</span>). منسوب است به عرج که دهی است از نواحی طائف و در ابتدای تهامه واقع، و میان آن و مدینه هفتاد و هشت میل است و در بلاد هذیل واقع است . (از معجم البلدان ).<br></font></div>'),
(182234, 'عرجی', '<span class=\"hlight\">عرجی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) عبداﷲبن عمربن عبداﷲبن عمروبن عثمان بن عفان اموی عرجی . شاعر و از مردم عرج است از نواحی طائف . (از معجم البلدان ) (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣١</span>).<br></font></div>'),
(182235, 'عرخو', '<span class=\"hlight\">عرخو.</span> <font color=\"DarkGreen\"><b>[ ع َرْ رَ ]</font></b> (اِ صوت ) آواز گربه و سگ هنگام خشم . (غیاث ) (آنندراج ).<br></font></div>'),
(182236, 'عرد', '<span class=\"hlight\">عرد.</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) سخت . (منتهی الارب ). صلب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ایستاده . (منتهی الارب ). راست ایستاده . (از اقرب الموارد). برپا شونده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) خر. (منتهی الارب ) (از اقرب الموارد). حمار. (البیان والتبیین ). <BR><font color=\"Blue\">◄</font> شرم مرد ایستاده . (از منتهی الارب ). اندام مرد. انگیز نعوظ کرده . ذکر. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> بن و بیخ گردن . (منتهی الارب ). جای پیوند گردن . (از اقرب الموارد).<br></font></div>'),
(182237, 'عرد', '<span class=\"hlight\">عرد.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع مص ) گریختن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نیرو گرفتن جسم پس از بیماری . (از اقرب الموارد).<br></font></div>'),
(182238, 'عرد', '<span class=\"hlight\">عرد.</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (ع ص ) سخت عُرُدّ.<br></font></div>'),
(182239, 'عرد', '<span class=\"hlight\">عرد.</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ دد ]</font></b> (ع ص ) سخت . عَرِد. (منتهی الارب ) (از اقرب الموارد). عَرد. (منتهی الارب ).<br></font></div>'),
(182240, 'عردات', '<span class=\"hlight\">عردات .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) ج ِ عردة، بمعنی صلابت و قوت . (از معجم البلدان ). رجوع به عردة شود.<br></font></div>'),
(182241, 'عردات', '<span class=\"hlight\">عردات .</span> <font color=\"DarkGreen\"><b>[ ع َرَ ]</font></b> (اِخ ) وادیی است مر بجیله را. (منتهی الارب ). وادیی است از آن بنی بجیلة. مسیر آن نصف روزه راه امتداد دارد. بالای آن عقبه ٔ تهامه و پایین آن تربة است ومیان یمن و نجد واقع شده است . (از معجم البلدان ).<br></font></div>'),
(182242, 'عرداد', '<span class=\"hlight\">عرداد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) پیل . (منتهی الارب ) (از اقرب الموارد). به عربی اسم فیل است . (تحفه ٔ حکیم مؤمن ). <BR><font color=\"Blue\">◄</font> (ص ) سخت . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شجاع . (ناظم الاطباء). دلاور. (منتهی الارب ). در اقرب الموارد مرد شجاع و سخت، یک معنی دانسته شده است . <BR><font color=\"Blue\">◄</font> (اِ) چوبی است بزرگ که بدان اسب و شتر را بندند. (از اقرب الموارد) (منتهی الارب ) (ناظم الاطباء).<br></font></div>'),
(182243, 'عردام', '<span class=\"hlight\">عردام .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) شاخی که در آن خوشه ها باشد. (منتهی الارب ) (آنندراج ). شاخه ای که بر آن خوشه ها باشد. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> شاخ بزرگی که بر آن شاخه های ریزه باشد. (منتهی الارب ) (آنندراج ). شاخ بزرگی که بر آن شاخه های ریزه و کوچک باشد. (ناظم الاطباء) (از اقرب الموارد). چوب خوشه ٔ خرما. (مهذب الاسماء).<br></font></div>'),
(182244, 'عردسة', '<span class=\"hlight\">عردسة.</span> <font color=\"DarkGreen\"><b>[ ع َ دَس َ ]</font></b> (ع مص ) به زمین افکندن کسی را. (منتهی الارب ) (از ناظم الاطباء). بر زمین زدن . (از اقرب الموارد).<br></font></div>'),
(182245, 'عردل', '<span class=\"hlight\">عردل .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ع ص ) سخت درشت و درازقامت . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(182246, 'عردلة', '<span class=\"hlight\">عردلة.</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ل َ ]</font></b> (ع مص ) سستی و فروهشتگی در رفتار. (منتهی الارب ). سستی در رفتار. (از اقرب الموارد) (از قاموس ). سست و فروهشته رفتن و سستی کردن در رفتار. (از ناظم الاطباء).<br></font></div>'),
(182247, 'عردم', '<span class=\"hlight\">عردم .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ع ص ) سطبر تمام اندام . درشت کم گوشت . (از اقرب الموارد) (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> سخت از هر چیزی . <BR><font color=\"Blue\">◄</font> (اِ) گردن . (از اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(182248, 'عردمان', '<span class=\"hlight\">عردمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ دُ ]</font></b> (ع ص ) درشت سخت اندام بدخوی . (آنندراج ). سخت جفاکار. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سطبرگردن . (آنندراج ). درشت گردن . (از اقرب الموارد).<br></font></div>'),
(182249, 'عردمة', '<span class=\"hlight\">عردمة.</span> <font color=\"DarkGreen\"><b>[ ع َدَ م َ ]</font></b> (ع اِمص ) سختی و درشتی . (منتهی الارب ) (از ناظم الاطباء). صلابت و شدت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (مص ) سخت و درشت گردیدن . (از ناظم الاطباء).<br></font></div>'),
(182250, 'عرر', '<span class=\"hlight\">عرر.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) گر. (منتهی الارب ). جرب . (اقرب الموارد). خارش . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> به یونانی اسم قنطوریون است . (تحفه ٔ حکیم مؤمن ).<br></font></div>'),
(182251, 'عرر', '<span class=\"hlight\">عرر.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِمص ) خردی کوهان شتر و بقولی کمی یا رفتگی آن . (از اقرب الموارد) (منتهی الارب ). کوچکی کوهان شتر. خردی و رفتگی کوهان . (ازناظم الاطباء). <BR><font color=\"Blue\">◄</font> (مص ) مبتلی گردیدن به جرب . <BR><font color=\"Blue\">◄</font> خردکوهان گردیدن . (ناظم الاطباء).<br></font></div>'),
(182252, 'عرز', '<span class=\"hlight\">عرز.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع مص ) درشت و سخت گردیدن . (از اقرب الموارد) (منتهی الارب ) (از ناظم الاطباء).<br></font></div>'),
(182253, 'عرز', '<span class=\"hlight\">عرز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) نکوهیدن کسی را و سرزنش نمودن . (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> درشت و سطبر گردیدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> گرفته و ترنجیده گردیدن و منقبض شدن . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> سخت کشیدن . (منتهی الارب ) (از اقرب الموارد) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> در کف گرفتن چیزی را و چسبانیدن انگشتان را بر آن، به اینکه می نماید از آن برخی و ننماید تمام آنرا تا که مشتاق دیدنش گردد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(182254, 'عرز', '<span class=\"hlight\">عرز.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) نوعی از درخت یز، خرد و باریکتر از آن . و گویند آن مصحف است و درست آن غرز است به غین معجمه . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(182255, 'عرزال', '<span class=\"hlight\">عرزال .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) خوابگاه شیر. <BR><font color=\"Blue\">◄</font> جای خواب پالیزبان در پالیز بر سر درخت و جز آن از ترس درندگان . (منتهی الارب ) (از اقرب الموارد). سقیفه ٔ ناطور. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گردآورده ٔ شیر درنده در جای باش خویش جهت بچگان مانند آشیانه ٔ مرغ . (از اقرب الموارد) (منتهی الارب ). و جائی که شیر درجای باش خویش جهت بچگان گردآورده فراهم میکند مانندآشیانه ای که مرغان میسازند. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> دهن توشه دان . (منتهی الارب ). دهنه ٔ مزاد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> امری که بدان مردم را اختیار نمایند و خاص کنند. (منتهی الارب ). مزیتی که بدان انسان را برگزینند و خاص کنند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گردآورده ٔ صیاد در کازه از صید قدید وجز آن . (منتهی الارب ). آنچه را صیاد از صید قدید و جز آن در کازه فراهم می کند. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> باقی مانده ٔ گوشت . (از اقرب الموارد) (منتهی الارب ) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> چیزی است مانند جوال . (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خانه ٔ خرد است که وقت کارزار در جنگ گاه جهت پادشاه سازند. (از اقرب الموارد) (منتهی الارب ) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> خانه ای مر «سماروغ چینی » را. (منتهی الارب ). خانه ای که سماروغ چینی برای خود میسازد. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> سوراخ مار. (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> رخت اندک . (منتهی الارب ). متاع کم . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شاخ درخت . (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دکان . (منتهی الارب ). حانوت . (اقرب الموارد). دکان می فروش . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> گروه مردم . <BR><font color=\"Blue\">◄</font> (ص ) گران . ثقیل . <BR><font color=\"Blue\">◄</font> حقیر و خوار. ذلیل و کوچک . (منتهی الارب ) (از اقرب الموارد). <br></font></div>'),
(182256, 'عرزام', '<span class=\"hlight\">عرزام .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) شیر بیشه . (ناظم الاطباء). رجوع به عرزم شود.<br></font></div>'),
(182257, 'عرزب', '<span class=\"hlight\">عرزب .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (اِخ ) نام نیای ضحاک بن عبدالرحمان است که تابعی بود. (از منتهی الارب ).<br></font></div>'),
(182258, 'عرزب', '<span class=\"hlight\">عرزب .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ زَ ]</font></b> (ع ص ) درشت و سخت و توانا و رُست . (منتهی الارب ).<br></font></div>'),
(182259, 'عرزبی', '<span class=\"hlight\">عرزبی .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ بی ی ]</font></b> (ص نسبی ) منسوب است به عرزب که نام مردی است . (از سمعانی ). رجوع به عرزب شود.<br></font></div>'),
(182260, 'عرزلی', '<span class=\"hlight\">عرزلی .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (اِخ ) در رجال لقب حسین بن علی بن خضربن صالح است . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>).<br></font></div>'),
(182261, 'عرزم', '<span class=\"hlight\">عرزم .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (اِخ ) نام گورستان و مقبره ای است به کوفه و گفته اند نام محلی است به کوفه معروف به جبانة عرزم . بلاذری گوید: بطنی است از نهد، و گویند مردی است از نهد بنام عرزم . (از معجم البلدان ). کلبی گوید: جبانة (گورستان ) منسوب به عرزم است مولای بنی اسد یا بنی عبس . (از معجم البلدان ).<br></font></div>'),
(182262, 'عرزم', '<span class=\"hlight\">عرزم .</span> <font color=\"DarkGreen\"><b>[ ع ِ زَم م ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ) (ناظم الاطباء). اسد. (اقرب الموارد).<br></font></div>'),
(182263, 'عرزم', '<span class=\"hlight\">عرزم .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (ع ص ) سخت . چیزی گرد سخت . (از اقرب الموارد) (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِخ ) علم است و منه جبانة عرزم، منزلی در کوفه که فرودآمد در آن عبدالملک ابی میسر عرزمی . (منتهی الارب ) (آنندراج ). رجوع به عرزمی شود.<br></font></div>'),
(182264, 'عرزم', '<span class=\"hlight\">عرزم .</span> <font color=\"DarkGreen\"><b>[ ع ِ زِ ]</font></b> (ع اِ) مار دیرینه . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(182265, 'عرزمی', '<span class=\"hlight\">عرزمی .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ می ی ]</font></b> (ص نسبی ) نسبت است به عرزم و به گمان صاحب الانسان بطنی است از فزارة. و جبانه ٔ (گورستان ) عرزم به کوفه معروف است . و شاید این بطن به عرزم وارد شده و بدان نسبت داده شده باشد. (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣١</span>).<br></font></div>'),
(182266, 'عرزمی', '<span class=\"hlight\">عرزمی .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (اِخ ) او راست کتاب الادب . (از الفهرست ابن الندیم ).<br></font></div>'),
(182267, 'عرزمی', '<span class=\"hlight\">عرزمی .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (اِخ ) ابوعبدالرحمان محمدبن عبیداﷲبن ابی سلیمان العرزمی . وی از عطار روایت دارد و عراقیان از وی . به سال <span class=\"hlight\" dir=\"rtl\">١٥٥</span> هَ . ق . در سن <span class=\"hlight\" dir=\"rtl\">٧٨</span> سالگی درگذشته است . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>).<br></font></div>'),
(182268, 'عرزمی', '<span class=\"hlight\">عرزمی .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (اِخ )ابوعبدالﷲ عبدالمک بن ابی سلیمان العرزمی . عموی محمدبن عبیداﷲ و نام ابی سلیمان میسرة است . وی از سعیدبن جبیر و عطا روایت کند. و ثوری و یارانش و یحیی بن سعیدالقطان و جز آنها از او روایت دارند وی در ذی الحجة سال <span class=\"hlight\" dir=\"rtl\">١٤٥</span> هَ . ق . درگذشته است . مردی ثقه بود ولکن در بعضی از احادیث خطا کرده است . (از اللباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣١</span>).<br></font></div>'),
(182269, 'عرس', '<span class=\"hlight\">عرس .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ]</font></b> (اِخ ) جایگاهی است در بلاد هذبل . (از معجم البلدان ).<br></font></div>'),
(182270, 'عرس', '<span class=\"hlight\">عرس .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ]</font></b> (ع اِ) نکاح و عروسی . (ناظم الاطباء). زفاف . (اقرب الموارد). عُرس . رجوع به عُرس شود. <BR><font color=\"Blue\">◄</font> مهمانی عروسی . (منتهی الارب ). طعام ولیمه . (از اقرب الموارد). رجوع به عُرس شود. <BR><font color=\"Blue\">◄</font> ج ِ عَروس . رجوع به عروس شود.<br></font></div>'),
(182271, 'عرس', '<span class=\"hlight\">عرس .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) شتر بچه ٔ خردسال . (ناظم الاطباء) (منتهی الارب ). فصیل کوچک و صغیر. (از اقرب الموارد). عَرس . رجوع به عَرس شود. ج، اَعراس . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گائیدن . (از منتهی الارب ). نکاح و عروسی . (ناظم الاطباء). زفاف . (اقرب الموارد). عُرُس . رجوع به عُرُس شود. <BR><font color=\"Blue\">◄</font> مهمانی عروسی . (منتهی الارب ). طعام ولیمه و مهمانی . (از اقرب الموارد). به صورت مذکر و مؤنث به کار رود. ج، أعراس وعُرُسات . (از منتهی الارب ) (از اقرب الموارد). و عُرَسات . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> مجازاً، به معنی مجلس طعام فاتحه ٔ بزرگان است، که به روز وفات بعد ازسالی کنند. چرا که رحلت از غمکده ٔ دنیا بمنزله ٔ شادی عروسی است . الحق عاشقان حق . چنانکه سعدی فرموده :<br>عروسی بود نوبت ماتمت <br>اگر نیک روزی بود خاتمت .<br> <font color=\"Red\">(آنندراج ).</font><br><BR><font color=\"Blue\">◄</font> در هند به مراسمی اطلاق شودکه برای تجلیل عارفان و حکیمان بزرگ اسلامی بر پا کنند. در این مراسم که معمولاً از سه تا پنج روز طول میکشد چند سخنرانی درباره ٔ مقام و شخصیت کسی که بیاد او جشن میگیرند ایراد میگردد و سپس گروه نوازندگان (قوّالان ) به قوالی میپردازند و آوازها و سرودهای مذهبی میخوانند. (فرهنگ فارسی معین ).<br></font></div>'),
(182272, 'عرس', '<span class=\"hlight\">عرس .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) زن باشوی . (منتهی الارب ). همسر و زن مرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد با زن . (منتهی الارب ). شوهر زن . (از اقرب الموارد). گویند هی عرسه، و هو عرسها. و زن و شوهر را عِرسان گویند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شیر ماده یا نر. (منتهی الارب ). ماده شیر و لبوءة. (از اقرب الموارد). ج، أعراس . (منتهی الارب ). و گاهی شیر نر و ماده را عِرسَین گویند. (از منتهی الارب ).<br>- <span class=\"hlight\">ابن عرس </span> ؛ راسو، که خرد گوش و برگردیده پلک باشد، گویا که گوشش از بیخ بریده است . (منتهی الارب ). چارپای کوچکی است چون موش، که اشتر و اصلم و اسک می باشد. (از اقرب الموارد). ج، بنات عرس، برای مذکر و مؤنث . (از اقرب الموارد) (از منتهی الارب ). و گویند بنوعرس . (از منتهی الارب ). و رجوع به ابن عرس در همین لغت نامه شود.<br></font></div>'),
(182273, 'عرس', '<span class=\"hlight\">عرس .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (ع ص ) سرگشته . (منتهی الارب ). مدهوش و حیران . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> لازم گیرنده ٔ چیزی . <BR><font color=\"Blue\">◄</font> ترسنده . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ) شیر بیشه . (منتهی الارب ). اسد. (اقرب الموارد).<br></font></div>'),
(182274, 'عرس', '<span class=\"hlight\">عرس .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع مص ) متحیر و سرگشته گردیدن . (از منتهی الارب ) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بازداشتن . (از منتهی الارب ). خودداری کردن و بخل ورزیدن . (از اقرب الموارد). گویند: عرس علی َّ ماعنده، یعنی بخل ورزیدنسبت به من آنچه را نزد او بود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تکبر نمودن و فیریدن . (منتهی الارب ). بطر و تکبر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بیخود شدن و دهشت داشتن . (منتهی الارب ). در شگفت شدن و مدهوش گشتن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ملازم چیزی بودن . (منتهی الارب ). ملازم گشتن و الفت یافتن . (از اقرب الموارد). گویند عرس الصبی بامه، یعنی کودک به مادر خود انس گرفت و ملازم او گشت . (از اقرب الموارد).<br></font></div>'),
(182275, 'عرس', '<span class=\"hlight\">عرس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ستونی است در میان خیمه . (منتهی الارب ). عمودی است در وسط «فسطاط». (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> رسن . (منتهی الارب ). حبل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتربچه ٔ خردسال . (منتهی الارب ). فصیل کوچک . (از اقرب الموارد). عُرس . رجوع به عُرس شود. <BR><font color=\"Blue\">◄</font> دیواری که مابین دو دیوار خانه ٔ سرمائی نهند و به نهایت نرسانند و مسقف سازند تا آن خانه گرمتر شود. و آنرا به فارسی بیچه گویند. (منتهی الارب ). دیواری است بین دو دیوار خانه ٔ زمستانی که پیش ازاینکه به انتها برسد آنرا مسقف میکنند تا آن خانه گرمتر باشد. و این کار را در شهرهای سردسیر انجام میدهند. و چنین خانه ای را مُعَرَّس نامند. (از اقرب الموارد). ج، أعراس . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(182276, 'عرس', '<span class=\"hlight\">عرس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) بستن گردن شتر را به بازوی وی . (از منتهی الارب ). عرس البعیر؛ گردن آن شتر را به بازویش بست در حالی که شتر سینه ٔ خود را بر زمین زده باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> برگشتن از کسی . (از منتهی الارب ). عدول کردن و منصرف شدن از کسی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پاییدن و پیوسته بودن در شادمانی . (از منتهی الارب ). پیوسته بودن در شادمانی . (از ناظم الاطباء). اقامت کردن و ماندن در فرح و شادی . (از اقرب الموارد).<br></font></div>'),
(182277, 'عرسات', '<span class=\"hlight\">عرسات .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ <span class=\"hlight\" dir=\"rtl\">/</span>ع ُ رَ ]</font></b> (ع اِ) ج ِ عُرس، عُرُس . رجوع به عرس شود.<br></font></div>'),
(182278, 'عرسان', '<span class=\"hlight\">عرسان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) تثنیه ٔ عِرس . رجوع به عرس شود. <BR><font color=\"Blue\">◄</font> شیر نر و شیر ماده . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> زن و شوهر. (از اقرب الموارد).<br></font></div>'),
(182279, 'عرسی', '<span class=\"hlight\">عرسی .</span> <font color=\"DarkGreen\"><b>[ ع ِ سی ی ]</font></b> (ص نسبی ) رنگ ابن عرس و راسو. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> رنگی است . (منتهی الارب ). رنگی شبیه به رنگ راسو. (ناظم الاطباء). رنگی است به رنگ ابن عرس . (از اقرب الموارد).<br></font></div>'),
(182280, 'عرش', '<span class=\"hlight\">عرش .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) ساختن بنا را از چوب . (از منتهی الارب ). ساختن خانه را از چوب . (از ناظم الاطباء). ساختمانی از چوب ساختن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تا صید رسیدن نتوانستن سگ از خوی کردن . (از منتهی الارب ) (آنندراج ). مانده شدن سگ و نتوانستن به صید. (از ناظم الاطباء) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سرگشته گردیدن و متحیر شدن . (از منتهی الارب ) (آنندراج ). سرمست شدن و مبهوت گشتن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بنا کردن خانه را. (از منتهی الارب ) (آنندراج ). ساختن و بنا کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> وادیج بستن رز را. (از منتهی الارب )(آنندراج ). جفته کردن . (دهار). انگور درخت رز را برچوب قرار دادن . (از اقرب الموارد). عُروش . رجوع به عروش شود. <BR><font color=\"Blue\">◄</font> گرد گرفتن چاه را بقدر یک قامت زیرین از سنگ و تمامه ٔ بالائین از چوب . (از منتهی الارب ) (آنندراج ). چاه را به اندازه ٔ یک قامت از قسمت زیرین آن از سنگ ساختن و باقی آن را از چوب ساختن، و در اینصورت چنین چاهی را «معروشة» گویند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زدن کسی را به «عُرش » گردن .رجوع به عُرش شود. <BR><font color=\"Blue\">◄</font> اقامت نمودن در مکان . (از منتهی الارب ) (آنندراج ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیوسته افروخته ماندن آتش هیزم . (از منتهی الارب ) (آنندراج ). عُرش الوقود (به صیغه ٔ مجهول )، هیزم افروخته شد و پیوسته ماند. (از اقرب الموارد).<br></font></div>'),
(182281, 'عرش', '<span class=\"hlight\">عرش .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) تخت و سریر پادشاه . (منتهی الارب ) (از اقرب الموارد). اورنگ . گاه . گه . سریر <span class=\"hlight\">:</span> اًنی وجدت امراءة تملکهم و اوتیت من کل شی ٔ و لها عرش عظیم (قرآن <span class=\"hlight\" dir=\"rtl\">٢٣/٢٧</span>)؛ من زنی را یافتم که بر ایشان پادشاهی میکند، و همه چیز او را داده شده و او راست تخت و سریری بزرگ . فلما جأت قیل أهکذا عرشک، قالت کأنه هو. (قرآن <span class=\"hlight\" dir=\"rtl\">٤٢/٢٧</span>)؛ پس چون آمد گفته شد آیا تخت تو این چنین است ؟ گفت گویا خود آن است . قال یا أیها الملأ أیکم یأتینی بعرشها قبل أن یأتونی مسلمین . (قرآن <span class=\"hlight\" dir=\"rtl\">٣٨/٢٧</span>)؛ گفت ای جماعت کدام یک از شما تخت او را برای من میاورد پیش از آنکه تسلیم شده نزد من بیایند؟<br>ورچون تو جسم نیست چه باید همیش تخت <br>معنی تخت و عرش یکی باشد و سریر.<br> <font color=\"Red\">ناصرخسرو.</font><br>عرش تست این خاک و افلاک و کواکب گرد او<br>روز و شب جولان همی همواره بر دوران کنند.<br> <font color=\"Red\">ناصرخسرو.</font><br>عرش این عرش کسی بود که در حرب، رسول <br>چو همه عاجز گشتند بدو داد لواش .<br> <font color=\"Red\">ناصرخسرو.</font><br>- <span class=\"hlight\">عرش بلقیس </span> ؛ تخت بلقیس . رجوع به عرش بلقیس در ردیف خود شود.<br> <BR><font color=\"Blue\">◄</font> تخت رب العالمین که تعریفش کرده نشود و کیفیت آن و بیان حد آن در شرع جایز نباشد. و گویند یاقوت سرخ است که از نور حق تعالی می درخشد. (از منتهی الارب ) (از آنندراج ). آسمانی که بالای همه آسمانها باشد. (ناظم الاطباء). جسم محیطبه عالم را که فلک الافلاک باشد، عرش گویند. و فلک ثوابت را کرسی نامند. (فرهنگ علوم عقلی ). فلک الافلاک رادر اصطلاح شرع عرش گویند، و در اصطلاح حکما فلک الافلاک نامیده میشود. (از کشاف اصطلاحات الفنون ). آن جسم که محیط بر جمیع اجسام است . و بسبب ارتفاعش بدین نام خوانده شده است و یا بجهت تشبیه به تخت پادشاه است درجایگزین شدن بر آن هنگام حکم . و احکام قضا و قدر خداوند از آنجا نازل شده است . و بدانجا نه صورت و نه جسم یافت شود. (از تعریفات جرجانی ). فلک الافلاک . منبر نه پایه . بام بدیع. بام رفیع. بام رواق . بحر وسیع. چرخ فلک . چرخ اطلس . چرخ برین . (آنندراج ). فلک اعظم . فلک اطلس . (یادداشت مرحوم دهخدا). آسمان نهم . گرزمان وپژِ آسمان . تهم . تهمتن . خاوند. محدد الجهات . (ناظم الاطباء) <span class=\"hlight\">:</span> و یحمل عرش ربک فوقهم یومئذ ثمانیة (قرآن <span class=\"hlight\" dir=\"rtl\">١٧/٦٩</span>)؛ و در آن روز هشت فریشته عرش پروردگار ترا به بالای خود بردارند. و هوالذی خلق السماوات و الارض فی ستة أیام و کان عرشه علی الماء (قرآن <span class=\"hlight\" dir=\"rtl\">٧/١١</span>)؛ اوست که آسمانها و زمین را در شش روز آفرید و عرش او بر آب بود. الذین یحملون العرش و من حوله یسبحون بحمد ربهم . (قرآن <span class=\"hlight\" dir=\"rtl\">٧/٤٠</span>)؛ آنانکه عرش را حمل میکنندو آنانکه پیرامون آنند به ستایش پروردگار خود تسبیح میکنند. ان ربکم اﷲ الذی خلق السماوات والارض فی ستةایام ثم استوی علی العرش . (قرآن <span class=\"hlight\" dir=\"rtl\">٥٤/٧</span>)؛ پروردگار شما خدائی است که آسمانها و زمین را در شش روز آفرید سپس بر عرش مستوی شد و قرار گرفت .<br>خدای عرش جهان را چنین نهاد نهاد<br>که گاه مردم از او شادمان و گه ناشاد.<br> <font color=\"Red\">کسائی .</font><br>ز خاشاک ناچیز تا عرش راست <br>سراسر به هستی یزدان گواست .<br> <font color=\"Red\">فردوسی .</font><br>ز هامون به چرخ برین شد سوار<br>سخن گفت بر عرش با کردگار.<br> <font color=\"Red\">اسدی .</font><br>گر ندیدی عرش را و حاملان عرش را<br>تا بگردش بر چسان هموار می جولان کنند.<br> <font color=\"Red\">ناصرخسرو.</font><br>از طواف همه ملائکیان <br>یادکردی به گرد عرش عظیم .<br> <font color=\"Red\">ناصرخسرو.</font><br>مرکب او را چو روی سوی عدو کرد<br>نصرت و فتح از خدای عرش نثار است .<br> <font color=\"Red\">ناصرخسرو.</font><br>مدح خدایگان و ثنای خدای عرش <br>جز بر زبان نراند و جز اندر دهان نداشت .<br> <font color=\"Red\">مسعودسعد.</font><br>تا هست ملایک را عرش آینه ٔ نوری <br>باد آینه ٔ عرش رخسار تو عالم را.<br> <font color=\"Red\">خاقانی .</font><br>زان نفس استوی زنند علی العرش <br>کز بر عرش آمد استوای صفاهان .<br><font color=\"Red\">خاقانی .</font><br>چارپای منبرش را هشت حمالان عرش <br>بر کتف دارند کاین مرکز ندارد قدر آن .<br> <font color=\"Red\">خاقانی .</font><br>بلبل عرشند سخن پروران <br>باز چه مانند به آن دیگران .<br> <font color=\"Red\">نظامی .</font><br>هر که سر از عرش برون میبرد<br>گوی ز میدان درون میبرد.<br> <font color=\"Red\">نظامی .</font><br>شعر و عرش و شرع از هم خاستند<br>هر دو عالم  زین سه حرف آراستند.<br> <font color=\"Red\">عطار (مصیبت نامه ص <span class=\"hlight\" dir=\"rtl\">٤٦</span>).</font><br>کسی کو هر چه دید از چشم جان دید<br>هزاران عرش در موئی عیان دید.<br> <font color=\"Red\">عطار.</font><br>تا نلرزد عرش از ناله ٔ یتیم <br>تا نگردد از ستم جانی سقیم .<br> <font color=\"Red\">مولوی .</font><br>خنک روز محشر تن دادگر<br>که در سایه ٔ عرش دارد مقر.<br> <font color=\"Red\">سعدی .</font><br>شعر نوری ز عرش زاینده ست <br>زان چو عرش استوار و پاینده ست .<br> <font color=\"Red\">اوحدی .</font><br>- <span class=\"hlight\">رب العرش العظیم </span> ؛ ملک العظیم . (ناظم الاطباء). پروردگار و صاحب عرش عظیم .<br>- <span class=\"hlight\">عرش آشیان </span> ؛ عرش نشین . که آشیان و جایگاه بر عرش دارد <span class=\"hlight\">:</span> فرشتگان عرش آشیان پیرامن وی صف اندر صف عاکف . (ترجمه تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٤٨</span>).<br>- <span class=\"hlight\">عرش و فرش </span> ؛ آسمان و زمین . (ناظم الاطباء).<br>- <span class=\"hlight\">مرغ عرش </span> ؛کنایه از روح و جان است <span class=\"hlight\">:</span> <br>این مرغ عرش ار طلب دانه ای کند<br>آن دانه جز ز سنبله ٔ آسمان مخواه .<br> <font color=\"Red\">خاقانی .</font><br>حقه ٔ گوهر ار چه در خاک است <br>مرغ عرش است آنچه گوهر اوست .<br> <font color=\"Red\">خاقانی .</font><br><BR><font color=\"Blue\">◄</font> (اصطلاح عرفا) عرش محل استقرار اسماء مقید الهی است . و آسمان را عرش گویند. و فلک الافلاک را نیز عرش گویند. و نفس کلیه را که محیط است بر اشیاء بر وجه تفصیل، عرش کریم و لوح قدر و لوح محفوظ و کتاب مبین و ورقاء و زمرد و یاقوت حمراء نامند. (فرهنگ مصطلحات عرفا). <BR><font color=\"Blue\">◄</font> در تداول فارسی، از آن آسمان اراده کنند.مقابل فرش که از آن دنیا یا زمین خواهند. (یادداشت مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> جاه . (منتهی الارب ). عز. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> قوام امر، و از آن جمله است که گویند: «ثل ّ عرشه » (بصیغه ٔ مجهول ) یعنی سست گردید کار او و از بین رفت عزت وی . <BR><font color=\"Blue\">◄</font> رکن چیزی . <BR><font color=\"Blue\">◄</font> سقف خانه . (منتهی الارب ) (از اقرب الموارد). سقف . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> خیمه . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سایبان، و هر پوشش که سایه افکند. (منتهی الارب ). بیتی که از سایه ٔ آن استفاده کنند و یا شبه بیتی است از شاخه های درخت که بر بالای آن گیاه «ثمام » قرار دهند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خانه ٔ مکه . (منتهی الارب ). عروش مکه ؛ بیوت آن . (از اقرب الموارد). مکه ٔ معظمه یا سراهای پیشین آن . (منتهی الارب ). عُرش . ج، عُروش و عُرُش و أعرش و عَرَشة. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> رئیس و مدبر قوم . (منتهی الارب )(از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کوشک . (منتهی الارب ). قصر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) چهار ستاره ٔ خرد، پایین عواء، که آنرا عرش السماک و عجزالاسدنامند. (از اقرب الموارد) (از منتهی الارب ). رجوع به عرش السماک شود. <BR><font color=\"Blue\">◄</font> نام دیگر ذات الکرسی است که صورتی است از صور فلکی . رجوع به ذات الکرسی شود. <BR><font color=\"Blue\">◄</font> (اِ) جنازه . و گویند از آن جمله است «اهتزالعرش لموت سعد» که منظور از اهتزاز، شادی است . (از منتهی الارب ) (از اقرب الموارد). جنازه، و آن سریر و تخت مرده است . (از تاج العروس ). <BR><font color=\"Blue\">◄</font> مُلک . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> چوب که بدان سر چاه را گیرند، بعد برآوردن سنگ باندازه ٔ یک قد مردم . (منتهی الارب ). چوبی که چاه را بدان سازند، پس از اینکه به اندازه ٔ یک قامت از انتهای آنرا با سنگ ساختند. (از اقرب الموارد). رجوع به عرش (مصدر) شود. <BR><font color=\"Blue\">◄</font> پشت پای . (منتهی الارب ). آنچه از ظهر قدم برآمده است، و انگشتان در آن جای دارند.(از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سایبان از نی ساخته . (منتهی الارب ). چتر و سایبان، و غالباً آنرا گویندکه از نی ساخته باشند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چوبی که بر آن آبکش ایستاده شود. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بنایی که بر دهانه ٔ چاه باشد و شخص آب کشنده بر آن می ایستد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آشیانه ٔ مرغ . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) مکه ٔ معظمه یا سراهای پیشین آن . (منتهی الارب ). مکه و یا بیوت قدیم آن . (از اقرب الموارد). و آنرا به فتح اول نیز خوانند. و برخی به فتح اول را مکه، و به ضم آنرا بیوت مکه دانسته اند. (از اقرب الموارد) (از منتهی الارب ). نامی است از برای خود مکه، و ظاهراً وجه تسمیه ٔ آن فراوانی عریش است در آن . (از معجم البلدان ).<br></font></div>'),
(182282, 'عرش', '<span class=\"hlight\">عرش .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع مص ) سرگشته گشتن و متحیرگردیدن . (از منتهی الارب ) (آنندراج ). سرمست شدن و مبهوت گشتن . (از اقرب الموارد). عَرش و رجوع به عَرش شود. <BR><font color=\"Blue\">◄</font> سخت گرفتن غریم را. (از منتهی الارب ). سخت گرفتن بر وام دار خود. (از ناظم الاطباء). ملازم گشتن غریم را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> برگشتن از کسی . (از منتهی الارب ). عدول کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> قوی گردیدن کسی بر چیزی که نزد اوست . (آنندراج ) (از منتهی الارب ). متعذر بودن بر کسی، آنچه نزد دیگری موجود است . (از اقرب الموارد).<br></font></div>'),
(182283, 'عرش', '<span class=\"hlight\">عرش .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) گوشتپاره ٔ دراز در یک سوی گردن یا در بن گردن . یا جای شیشه ٔ حجامت . (منتهی الارب ). یکی از دو عرش گردن است، و آنها دو گوشت مستطیل شکل هستند در دو طرف گردن ویا در انتهای آن و گویند آنها محل و موضع دو محجمه و وسیله ٔ حجامت هستند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> استخوان نزدیک حلق که زبان را برپا دارد، و آندورا «عرشان » گویند. (از منتهی الارب ). یکی از دو عرش لهاة است، و آنها دو استخوان هستند که زبان بر آنها برپاست . (از اقرب الموارد). استخوان نزدیک حلق که زبان را برپا دارد و به اصطلاح تشریح «عظم لامی » میگویند. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> موی پایین یال اسب . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گوش . (منتهی الارب ) (آنندراج ) (ناظم الاطباء) (از تاج العروس ). <BR><font color=\"Blue\">◄</font> (ص ) شتر ماده ٔ سطبر بزرگ سینه، گویا بالای سینه اش تخت انداخته شده . (منتهی الارب ) (آنندراج ) (از ناظم الاطباء). ستبر از شترهای ماده، که گویی بالای سینه ٔ او معروش و سایه بان زده شده است . (شرح قاموس ) (از تاج العروس ) (از اقرب الموارد) . <BR><font color=\"Blue\">◄</font> مابین تندی پشت پای و انگشتان پای . به این معنی به فتح اول نیز خوانده شود.ج، عِرَشة، أعراش . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(182284, 'عرش', '<span class=\"hlight\">عرش .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) شهری است در یمن بر ساحل . (از معجم البلدان ).<br></font></div>'),
(182285, 'عرش', '<span class=\"hlight\">عرش .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ]</font></b> (ع اِ) ج ِ عَرش . رجوع به عَرش شود. <BR><font color=\"Blue\">◄</font> ج عَریش . رجوع به عریش شود.<br></font></div>'),
(182286, 'عرش آشیان', '<span class=\"hlight\">عرش آشیان .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (ص مرکب ) دارای آشیانی به بلندی عرش . آنکه به عرش خانه و آشیانه دارد. (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> وصفی رحمت آمیز که از پس ذکر نام مرده کنند.<br></font></div>'),
(182287, 'عرش آشیانی', '<span class=\"hlight\">عرش آشیانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (حامص مرکب ) در عرش آشیان داشتن . عرش آشیان بودن . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> (اِخ ) لقبی است که به اکبرشاه هندی پس از مرگ وی داده اند. (ناظم الاطباء).<br></font></div>'),
(182288, 'عرش اعظم', '<span class=\"hlight\">عرش اعظم .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ِ اَ ظَ ]</font></b> (ترکیب وصفی، اِ مرکب ) عرش بزرگ . عرش بزرگتر <span class=\"hlight\">:</span> <br>ای ذره ای از نور تو بر عرش اعظم تافته <br>وز عرش اعظم درگذربر هر دو عالم تافته .<br><font color=\"Red\">عطار.</font><br></font></div>'),
(182289, 'عرش اعلی', '<span class=\"hlight\">عرش اعلی .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ِ اَ لا ]</font></b> (ترکیب وصفی، اِ مرکب ) کرسی خداوند عالمیان که گرزمان نیز گویند. (ناظم الاطباء). عرش رحمان . عرش شریف .<br></font></div>'),
(182290, 'عرش السماک', '<span class=\"hlight\">عرش السماک .</span> <font color=\"DarkGreen\"><b>[ ع َ شُس ْ س ِ ]</font></b> (اِخ ) چهار ستاره است خرد و پایین تر از عوا، که آنرا عجزالاسد نیز گویند. رجوع به عرش شود. <BR><font color=\"Blue\">◄</font> نام صورتی از صور فلکیه از ناحیه ٔ جنوبی است و آنرا بر مثال عرشی توهم کرده اند. کوکب آن هفت است و نام دیگر آن غراب باشد. (از جهان دانش ). عرش سماک .<br></font></div>'),
(182291, 'عرش اکبر', '<span class=\"hlight\">عرش اکبر.</span> <font color=\"DarkGreen\"><b>[ ع َ ش ِ اَ ب َ ]</font></b> (ترکیب وصفی، اِ مرکب ) عرش بزرگتر. <BR><font color=\"Blue\">◄</font> در اصطلاح صوفیه، دل انسان کامل را نامند. (از کشاف اصطلاحات الفنون ). کنایه از دل آدمی زاد باشد و به عربی قلب خوانند. (برهان ) (آنندراج ). کنایه از دل انبیاء و اولیاء است . (انجمن آرا).<br></font></div>'),
(182292, 'عرش بلقیس', '<span class=\"hlight\">عرش بلقیس .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ِ ب ِ ]</font></b> (اِخ ) تخت بلقیس، ملکه ٔ سبا، که داستان آن در قرآن کریم مذکور است <span class=\"hlight\">:</span> <br>نشستم از برش چون عرش بلقیس <br>بجست او چون یکی عفریت هایل .<br><font color=\"Red\">منوچهری .</font><br></font></div>'),
(182293, 'عرش بلقیس', '<span class=\"hlight\">عرش بلقیس .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ِ ب ِ ]</font></b> (اِخ ) جایگاهی است در یک روزه راه از ذمار. از آثارش فقط شش ستون رخام باقی مانده و کنار آن آبهای جاری بسیاری یافت شود، و آبگیرهایی دارد که هر کس وارد آنها شود به قول اهالی آنجا غرق شود، و کسی را یارای آن نیست که به آن ستونها برسد. اهالی آن بلاد را عقیده براین است که آن عرش و تخت بلقیس بوده است . (از معجم البلدان ).<br></font></div>'),
(182294, 'عرش ثانی', '<span class=\"hlight\">عرش ثانی .</span><font color=\"DarkGreen\"><b>[ ع َ ش ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) عبارت است از کرسیی که بر آن همه ٔ ستارگان هستند. (غیاث ) (آنندراج ).<br></font></div>'),
(182295, 'عرش جسمانی', '<span class=\"hlight\">عرش جسمانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ِ ج ِ ]</font></b> (ترکیب وصفی، اِ مرکب )مراد فلک اعلی است . (فرهنگ علوم عقلی از مصنفات ).<br></font></div>'),
(182296, 'عرش جناب', '<span class=\"hlight\">عرش جناب .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ص مرکب ) بلندآستان . که آستانی به بلندی عرش دارد. عنوانی که پس از نام صاحب مقامی آرند توقیر و بزرگداشت او را <span class=\"hlight\">:</span> <br>تخت زین پایه گشت عرش جناب .<br><font color=\"Red\">طالب کلیم (از آنندراج ).</font><br></font></div>'),
(182297, 'عرش رحمان', '<span class=\"hlight\">عرش رحمان .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ِ رَ ]</font></b> (ترکیب اضافی، اِ مرکب ) کرسی خداوند عالمیان که گرزمان نیز گویند. (ناظم الاطباء). عرش اعلی . عرش شریف .<br></font></div>'),
(182298, 'عرش روان', '<span class=\"hlight\">عرش روان .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِ مرکب ) بر عرش روندگان . کنایه از انبیاء و اولیاء است . (انجمن آرا). کنایه از انبیاء و اولیاء و اهل اﷲ و اهل دل باشد. (برهان ) (آنندراج ). عرش وران <span class=\"hlight\">:</span> <br>سدره نشینان سوی او پر زنند<br>عرش روان نیز همین در زنند.<br> <font color=\"Red\">نظامی .</font><br>عرش روانی که ز تن رسته اند<br>شهپر جبریل بدل بسته اند.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(182299, 'عرش شریف', '<span class=\"hlight\">عرش شریف .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ِ ش َ ]</font></b> (ترکیب وصفی، اِ مرکب ) کرسی خداوند عالمیان که گرزمان نیز گویند. (ناظم الاطباء). عرش اعلی . عرش رحمان .<br></font></div>'),
(182300, 'عرش ظلال', '<span class=\"hlight\">عرش ظلال .</span> <font color=\"DarkGreen\"><b>[ ع َ ظِ ]</font></b> (ص مرکب ) عرش سایه . که سایه در عرش افکند <span class=\"hlight\">:</span> <br>چو صبح صادق دین را نهفت ظل ابد<br>برآمد از پس صبح آفتاب عرش ظلال .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(182301, 'عرش عقلی', '<span class=\"hlight\">عرش عقلی .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ِ ع َ ]</font></b> (ترکیب وصفی، اِ مرکب ) مراد عقل اول است . (فرهنگ علوم عقلی از مصنفات ).<br></font></div>'),
(182302, 'عرش فرسا', '<span class=\"hlight\">عرش فرسا.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (نف مرکب ) ظاهراً کنایه از فرشته و ملائک <span class=\"hlight\">:</span> <br>هر سحرگاهش دعای صدق ران <br>پس به سوی عرش فرسائی فرست .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(182303, 'عرش لوا', '<span class=\"hlight\">عرش لوا.</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ ]</font></b> (ص مرکب ) که لوای آن عرش باشد. که لوایی بلند دارد <span class=\"hlight\">:</span> <br>عقل که دید طلعتش حرز بر اودمید و گفت <br>اینت شه ملک سپه، عرش لوای مملکت .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(182304, 'عرش منزل', '<span class=\"hlight\">عرش منزل .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ زِ ]</font></b> (ص مرکب ) دارای منزلی چون عرش . عرش آشیان . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> (اِخ ) لقبی است که به عالم گیر شاه دوم، پادشاه هند پس از مرگ وی داده اند. (ناظم الاطباء).<br></font></div>'),
(182305, 'عرش نفسی', '<span class=\"hlight\">عرش نفسی .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ِ ن َ ]</font></b> (ترکیب وصفی، اِ مرکب ) مراد نفس فلک اول است . (فرهنگ علوم عقلی از مصنفات ).<br></font></div>'),
(182306, 'عرش وران', '<span class=\"hlight\">عرش وران .</span> <font color=\"DarkGreen\"><b>[ ع َ وَ ]</font></b> (اِ مرکب ) کنایه از انبیاء و اولیاء و اهل اﷲ و اهل دل باشد. (برهان قاطع) (آنندراج ). عرش روان . رجوع به عرش روان شود.<br></font></div>'),
(182307, 'عرش پایه', '<span class=\"hlight\">عرش پایه .</span> <font color=\"DarkGreen\"><b>[ ع َ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (ص مرکب ) عرش پایگاه . که مقامی بلند دارد <span class=\"hlight\">:</span> <br>سبوح زنان عرش پایه <br>از نور تو کرده عرش سایه .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(182308, 'عرش پایگاه', '<span class=\"hlight\">عرش پایگاه .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص مرکب ) دارای مرتبه و مقامی بلند. (فرهنگ فارسی معین ). عنوانی که پس ازنام مردی صاحب مقام آرند توفیر و بزرگداشت او را.<br></font></div>'),
(182309, 'عرشان', '<span class=\"hlight\">عرشان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) تثنیه ٔ عرش (در حال رفع). دو استخوان نزدیک حلق . رجوع به عُرش شود.<br></font></div>'),
(182310, 'عرشان', '<span class=\"hlight\">عرشان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )شهری است در پایین تَعکُر در یمن . و علی بن ابی بکر فقیه و محدث، و نیز فرزند او صفی الدین احمدبن علی، قاضی یمن در آن میزیستند. رجوع به معجم البلدان شود.<br></font></div>'),
(182311, 'عرشستان', '<span class=\"hlight\">عرشستان .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ِ]</font></b> (اِ مرکب ) جایی که در آن عرش ها باشد <span class=\"hlight\">:</span> <br>از قدر تو کرده زایرانت <br>عرشستانها بر آستانت .<br><font color=\"Red\">درویش واله هروی (از آنندراج ).</font><br></font></div>'),
(182312, 'عرشه', '<span class=\"hlight\">عرشه .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (از ع، اِ) سطحی که مرتفعتر از اطراف خود باشد. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عرشه ٔ کشتی </span> ؛ سطح بالای کشتی . (از فرهنگ فارسی معین ). مرتفعترین جزء از کشتی که مردم در آنجا بنشینند. (از ناظم الاطباء).<br></font></div>'),
(182313, 'عرشی', '<span class=\"hlight\">عرشی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب به عرش . آسمانی . (ناظم الاطباء). رجوع به عرش شود.<br></font></div>'),
(182314, 'عرشی', '<span class=\"hlight\">عرشی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) تخلص شاعری است .(آنندراج ) (غیاث اللغات ). نامش طهماسب قلی بیگ، و در سلسله ٔ شاه خلیل اﷲ ولد میر میران کاکلتاش محرم است . وی در خدمت شاه طهماسب صفوی بوده است . و ابیاتی ازاشعار او در آتشکده ٔ آذر و مجمع الخواص ضبط شده است . رجوع به مجمع الخواص ص <span class=\"hlight\" dir=\"rtl\">٦١</span> و آتشکده ٔ آذر ص <span class=\"hlight\" dir=\"rtl\">١٩</span> شود.<br></font></div>'),
(182315, 'عرشیان', '<span class=\"hlight\">عرشیان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِ مرکب ) جمع فارسی عرشی، منسوب به عرش . کنایه از ملائکه ٔ مقربین و حاملان عرش باشد. (آنندراج ) (برهان ). روحانیان . ملائک <span class=\"hlight\">:</span> <br>عرشیان بانگ و ﷲ علی الناس زنند<br>پاسخ از خلق سمعنا و اطعنا شنوند.<br> <font color=\"Red\">خاقانی .</font><br>عرشیان سایه ٔ حقش دانند<br>اختران نور مطلقش دانند.<br> <font color=\"Red\">خاقانی .</font><br>تا به دور دولت او گشت شروان خیروان <br>عرشیان فیض روان بر خیروان افشانده اند.<br> <font color=\"Red\">خاقانی .</font><br>ز بند جهان داد خود راخلاص <br>به معشوقی عرشیان گشت خاص .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(182316, 'عرشین القصور', '<span class=\"hlight\">عرشین القصور.</span> <font color=\"DarkGreen\"><b>[ ع َ نُل ْ ق ُ ]</font></b> (اِخ ) قریه ای است از قرای جَزر از نواحی حلب . و نام آن در شعر حمدان بن عبدالرحیم آمده است . (از معجم البلدان ).<br></font></div>'),
(182317, 'عرص', '<span class=\"hlight\">عرص .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) پیوسته با درخش و رعد ماندن هوا. (از منتهی الارب ). پیوسته با درخش و تندر گردیدن هوا. (از ناظم الاطباء). دوام یافتن برق آسمان . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مضطرب گردیدن شتر. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بستن گردن شتر را بر بازوی آن . (منتهی الارب ) (از ناظم الاطباء).<br></font></div>'),
(182318, 'عرص', '<span class=\"hlight\">عرص .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) تیر که بر آن چوبهای کوچک انداخته، خانه را بدان سقف نمایند و آنرا با سین نیز نوشته اند. (ازمنتهی الارب ). به معنی عرس است . (از اقرب الموارد). رجوع به عرس شود. <BR><font color=\"Blue\">◄</font> (ص ) برق پراکنده و مضطرب و درخشنده . (منتهی الارب ) (ناظم الاطباء). برق مضطرب . (از اقرب الموارد). عَرِص . رجوع به عَرِص شود.<br></font></div>'),
(182319, 'عرص', '<span class=\"hlight\">عرص .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (ع مص ) پراکنده درخشیدن برق . (از منتهی الارب ). مضطرب شدن برق . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نشاط و شادمانی نمودن . (از منتهی الارب ). فعال و بانشاط شدن . (از اقرب الموارد). نشاطی شدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> بوی نم گرفتن خانه و گیاه . (از منتهی الارب ). تغییر یافتن بوی خانه و گیاه از نمناکی . (از اقرب الموارد). دم گرفتن خانه از نم . (تاج المصادر بیهقی ).<br></font></div>'),
(182320, 'عرص', '<span class=\"hlight\">عرص .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (ع ص ) شادمان . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> برق پراکنده و مضطرب . (از اقرب الموارد). عَرص . رجوع به عَرص شود.<br></font></div>'),
(182321, 'عرصات', '<span class=\"hlight\">عرصات .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) ج ِ عَرصة. رجوع به عرصة شود.<br>- <span class=\"hlight\">عرصات جنت </span> ؛ گشادگیهای بهشت . (یادداشت مرحوم دهخدا).<br> <BR><font color=\"Blue\">◄</font> (از ع، اِ) صحرای قیامت . (ناظم الاطباء). قیامت . (آنندراج ) <span class=\"hlight\">:</span> علوی او را گفت شرم نداری که با خون فرزند پیغمبر سوی عرصات آئی .(مجمل التواریخ والقصص ).<br>روز قیامت که برات آورند<br>بادیه را در عرصات آورند.<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">روز عرصات </span> ؛ روز قیامت . (ناظم الاطباء).<br>- <span class=\"hlight\">امثال </span> :<br><span class=\"hlight\">عرصات و خرگائی </span> ؛ عرصات و خر گائیدن، این هر دو مثل وقتی میگویند که کسی حرفی را که در خلوت باید گفت در انجمن گوید. و در مصطلحات «خرگاهی » به هاء آمده است . (از آنندراج ).<br></font></div>'),
(182322, 'عرصاف', '<span class=\"hlight\">عرصاف .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) عرصاف الاًکاف، چوبی که میان دو «حِنو» مقدم بسته شود. (منتهی الارب ) (از اقرب الموارد). عُرصوف . عُصفور. رجوع به عرصوف و عصفور شود. <BR><font color=\"Blue\">◄</font> تازیانه از پی . <BR><font color=\"Blue\">◄</font> پی دراز، یا یک نوک از پی . <BR><font color=\"Blue\">◄</font> تسمه . <BR><font color=\"Blue\">◄</font> میخ رحل که بر سر حِنو پالان زنند، و آن چهارتا باشد، بر سر هر حنو دو تا. (منتهی الارب ). یا دو چوب که میان واسط و آخر رحل به چپ و راست بسته شود. <BR><font color=\"Blue\">◄</font> عرصاف من سنام البعیر؛ اطراف مهره ٔ پشت شتر. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عرصاف الخرطوم ؛ استخوانهای دوتای اندرون بینی . (منتهی الارب ).استخوانهایی است در خیشوم که خم میشود. (از اقرب الموارد). ج، عَراصیف . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(182323, 'عرصام', '<span class=\"hlight\">عرصام .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ). اسد. (اقرب الموارد). عَراصِم . عَرصم . رجوع به عراصم و عرصم شود.<br></font></div>'),
(182324, 'عرصتان', '<span class=\"hlight\">عرصتان .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ]</font></b> (ع اِ) تثنیه ٔ عرصة (در حال رفع). رجوع به عرصة شود. <BR><font color=\"Blue\">◄</font> (اِخ ) دو فضاء است در عقیق مدینه که آنرا عصة الصغری و عرصة الکبری گویند. (از منتهی الارب ). دو بقعه است در عقیق مدینه، کبری و صغری . (از اقرب الموارد). در عقیق است از نواحی مدینه و آن افضل و اکرم بقاع مدینه میاشد. بنی امیه از ایجاد ساختمان در آنجا جلوگیری میکردند و سلطان مدینه جز به امر خلیفه از آنجا به کسی اقطاع نمیداد. رجوع به معجم البلدان شود.<br></font></div>'),
(182325, 'عرصف', '<span class=\"hlight\">عرصف .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ]</font></b> (ع اِ) حشیشی است که آنرا به شیرازی ماش دارو و به یونانی کمافیطوس خوانند. (برهان ). نباتی است . (از اقرب الموارد). گیاهی است یونانی مانند مافیطوس که ورقش با آب عسل چهل روز نوشیدن، دافع عرق النساء است و هفت روز، دافع یرقان . (منتهی الارب ). و رجوع به مخزن الادویه و تحفه ٔ حکیم مؤمن و جامع المفردات ابن البیطار شود.<br></font></div>'),
(182326, 'عرصفة', '<span class=\"hlight\">عرصفة.</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ف َ ]</font></b> (ع مص ) کشیدن و به درازا دوباره کردن . (از منتهی الارب ). جذب کردن و کشیدن چیزی و آن را از طول شکافتن و پاره کردن . (از اقرب الموارد).<br></font></div>'),
(182327, 'عرصم', '<span class=\"hlight\">عرصم .</span> <font color=\"DarkGreen\"><b>[ ع ِ ص ِ ]</font></b> (ع اِ) به لغت اهل یمن باذنجان صحرائی باشد. (برهان قاطع) (آنندراج ). بادنجان بری . (تحفه ٔ حکیم مؤمن ) (مخزن الادویه ). اسم یمنی است بادنجان بری را، بعضی حَدَق خوانند. (اختیارات بدیعی ). رجوع به بادنجان بری و تذکره ٔ ضریر انطاکی شود.<br></font></div>'),
(182328, 'عرصم', '<span class=\"hlight\">عرصم .</span> <font color=\"DarkGreen\"><b>[ ع ِ ص َ م م ]</font></b> (ع ص ) نزار و نرم تن . (منتهی الارب ). ضعیف جسم . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> توانای درشت گوشت . قوی و سخت گوشت . و آن از اضداد است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) شیر بیشه . (منتهی الارب ). اسد. (اقرب الموارد). عِرصام . عُراصِم . رجوع به عرصام و عراصم شود.<br></font></div>'),
(182329, 'عرصم', '<span class=\"hlight\">عرصم .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ]</font></b> (ع ص ) بسیار خورنده . (منتهی الارب ). أکول . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خرم و شادمان . (منتهی الارب ). نشیط. (اقرب الموارد).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(182330, 'عرصه', '<span class=\"hlight\">عرصه .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ]</font></b> (از عربی، اِ) عرصة.میدان و صحرا. (ناظم الاطباء). میدان . (غیاث ). فارسیان، عرصه را به معنی مطلق میدان استعمال نمایند و لهذا عرصه ٔ شطرنج و عرصه ٔ آفاق و عرصه ٔ بزم آمده است . (از آنندراج ). پهنه . فراخنا. ساحت . فضا <span class=\"hlight\">:</span> <br>کهینه عرصه ای از جاه او فزون ز فلک <br>کمینه جزوی ازقدر او مه از کیوان .<br> <font color=\"Red\">رودکی .</font><br>چندانت بود فتح که در عرصه ٔ عالم <br>هر روز بگویند به هرجا خبر فتح .<br> <font color=\"Red\">مسعودسعد.</font><br>صبح صادق عرصه ٔ گیتی را به نورجمال خویش منور گردانید. (کلیله و دمنه ) و گردانیدن پای از عرصه ٔ یقین . (کلیله و دمنه ). عرصه ٔ امید بر ایشان فراخ میدار. (کلیله و دمنه ).<br>پندار سر خر و بن خار<br>در عرصه ٔ بوستان ببینم .<br> <font color=\"Red\">خاقانی .</font><br>دوم آنکه عرصه ٔ عربیت فسحتی تمام و اتساعی کامل دارد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٨</span>). خوف و رعب عرصه ٔ سینه ٔ ایشان را فرا گرفت . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٧٤</span>).<br>عرصه ای کش خاک زر دَه دَهی است <br>زر به هدیه بردن آنجا ابلهی است .<br> <font color=\"Red\">مولوی (مثنوی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣١١</span>).</font><br>عرصه ٔ دنیا مجال همت او نیست <br>روز قیامت نگر مجال محمد.<br> <font color=\"Red\">سعدی .</font><br>خسروا گوی فلک در خم چوگان تو باد<br>ساحت کون و مکان عرصه ٔ میدان تو باد.<br> <font color=\"Red\">حافظ.</font><br>ای مگس عرصه ٔ سیمرغ نه جولانگه تست <br>عرض خود میبری و زحمت ما میداری .<br> <font color=\"Red\">حافظ.</font><br>عرصه ٔ بزمگاه خالی ماند<br>از حریفان و جام مالامال .<br> <font color=\"Red\">حافظ.</font><br>مرد مصاف در همه جا یافت می شود<br>در هیچ عرصه مرد تحمل ندیده ام .<br> <font color=\"Red\">صائب .</font><br>میدان، عرصه ٔ اسب دوانی وچوگان بازی . (از منتهی الارب ).<br>- <span class=\"hlight\">به عرصه ٔ ظهور رسیدن </span> ؛ متولد شدن . پدید آمدن . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">پا به عرصه ٔ ظهور نهادن </span> ؛ متولد شدن . پدید آمدن . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عرصه ٔ اسب دوانی </span> ؛ محل و میدان اسب دوانی . اسپریس .<br>- <span class=\"hlight\">عرصه ٔ بزم </span> ؛ میدان و فضا و ساحت جشن .<br>- <span class=\"hlight\">عرصه ٔ پیکار</span> ؛ میدان جنگ . رزمگاه .<br>- <span class=\"hlight\">عرصه ٔ جنگ </span> ؛ رزمگاه . میدان جنگ .<br>- <span class=\"hlight\">عرصه را بر کسی تنگ گرفتن </span> ؛ او را در تنگنا و در مضیقه قرار دادن . بر کسی سخت گرفتن . (از فرهنگ عوام ). او را زبون و مستأصل کردن .<br>- <span class=\"hlight\">عرصه ٔ رزم </span> ؛ میدان پیکار. رزمگاه .<br>- <span class=\"hlight\">عرصه ٔ زمین </span> ؛ سطح زمین . (ناظم الاطباء).<br>- <span class=\"hlight\">عرصه ٔ کارزار</span> ؛ رزمگاه . میدان نبرد.<br>- <span class=\"hlight\">عرصه ٔ محشر</span> ؛ صحرای قیامت . (ناظم الاطباء). آنجا که حساب اعمال مردمان را رسند. آنجا که مردمان حشر کنند.<br>- <span class=\"hlight\">عرصه ٔ هیجا</span> ؛ میدان نبرد. رزمگاه .<br> <BR><font color=\"Blue\">◄</font> سرزمین <span class=\"hlight\">:</span> از عرصه ٔ خراسان بر بایدخاستن و به قهستان ... (ترجمه ٔ تاریخ یمینی ). رسول را بر جمله ٔ طاعات باز گردانید و از عرصه ٔ ملک خراسان برخاست . (ترجمه ٔ تاریخ یمینی ). ناحیت ناردین در عرصه ٔ اسلام افزود. (ترجمه ٔ تاریخ یمینی ). <BR><font color=\"Blue\">◄</font> جنگ گاه . (منتهی الارب ). باهة. (منتهی الارب ). میدان نبرد. رزمگاه . میدان . (غیاث ) <span class=\"hlight\">:</span> <br>زود بینی ز عرض مرکب او<br>عرصه ها تنگتر ز حلقه ٔ میم .<br> <font color=\"Red\">ابوالفرج رونی .</font><br>در تضاعیف این حالات هنوز «کیوک » باز نرسیده بود و عرصه خالی می نمود. (جهانگشای جوینی ). <BR><font color=\"Blue\">◄</font> بساط شطرنج . (غیاث ) (ناظم الاطباء). صفحه ٔ نرد و شطرنج و غیره . (یادداشت مرحوم دهخدا). رقعه ٔ شطرنج . صفحه ٔ شطرنج . نطع. بساط نرد. سفره <span class=\"hlight\">:</span> <br>پس عرصه بیفکند و فروچیدش مهره <br>هر زخم که او میزد بس کارگر آمد.<br> <font color=\"Red\">سوزنی .</font><br>که شاه ارچه در عرصه زورآور است <br>چو ضعف آمد از بیدقی کمتر است .<br> <font color=\"Red\">سعدی .</font><br>بازی به کنار عرصه بهتر پیداست .<br> <font color=\"Red\">واعظ قزوینی .</font><br>- <span class=\"hlight\">عرصه ٔ شطرنج </span> ؛ بساط شطرنج . نطع. صفحه ٔ شطرنج . رقعه ٔ شطرنج <span class=\"hlight\">:</span> <br>بر عرصه ٔ شطرنج ثنا گفتن تو صدر<br>من سوزنیم بیدق و صاحب شرفان شاه .<br> <font color=\"Red\">سوزنی .</font><br>یا للعجب پیاده ٔ عاج عرصه ٔ شطرنج بسر میبرد و فرزین میشود. (گلستان سعدی ).<br>تا چه بازی رخ نماید بیدقی خواهیم راند<br>عرصه ٔ شطرنج رندان را مجال شاه نیست .<br> <font color=\"Red\">حافظ.</font><br> <BR><font color=\"Blue\">◄</font> آن قسمت از زمین که بر آن بنائی نباشد. مقابل بنا. (یادداشت مرحوم دهخدا). زمین . مقابل اعیان . زمینی . مقابل هوایی <span class=\"hlight\">:</span> به وقت نهضت فرموده بود تا از بهر مسجد جامع به غزنه عرصه ای اختیار کنند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٢٠</span>). زید همگی و تمامی شش دانگ خانه ٔ، واقع در فلان کوچه را از عرصه و بنا فروخت به ... (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">عرصه ٔ خانه </span> ؛ زمین خانه . در مقابل اعیان .<br>- <span class=\"hlight\">عرصه و اعیان </span> ؛ مجموع زمین و بنای متعلق به آن زمین . زمین و ساختمان .<br><BR><font color=\"Blue\">◄</font> در مجمل التواریخ گلستانه دو جا این کلمه در معنی فاصله ٔ زمانی بکار رفته است مرادف عرض (اگر مصحف عرض نباشد) <span class=\"hlight\">:</span> در عرصه ٔ یک ماه در هفت جا نمود سنگر کرده بفاصله ٔ یک میدان تفاوت سنگرها از یکدیگر بود. (مجمل التواریخ گلستانه ). کریم خان به استعداد لشکر پرداخته اسب و سرانجام طلبیده در عرصه ٔ دو ماه خود را ساخته . (مجمل التواریخ گلستانه ).<br></font></div>'),
(182331, 'عرصه افکندن', '<span class=\"hlight\">عرصه افکندن .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ<span class=\"hlight\" dir=\"rtl\">/</span> ص ِ اَ ک َ دَ ]</font></b> (مص مرکب ) گستردن نطع <span class=\"hlight\">:</span> <br>پس عرصه بیفکند و فروچیدش مهره <br>هر زخم که او میزد بس کارگر آمد.<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(182332, 'عرصه دوگاه', '<span class=\"hlight\">عرصه دوگاه .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ دُ ]</font></b> (اِخ ) دهی از دهستان گنجگاه، بخش سنجید، شهرستان هروآباد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢٦٢</span> تن . آب آن از چشمه و محصول آن غلات و حبوب است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(182333, 'عرصه گاه', '<span class=\"hlight\">عرصه گاه .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ <span class=\"hlight\" dir=\"rtl\">/</span> ص ِ ]</font></b> (اِ مرکب ) میدانگاه . فراخنای . فضا و ساحت . جای گشاده و با وسعت <span class=\"hlight\">:</span> <br>هم او عرصه گاهی است شیب و فراز<br>معلق جهانبانش گسترده باز.<br><font color=\"Red\">اسدی .</font><br></font></div>'),
(182334, 'عرصوف', '<span class=\"hlight\">عرصوف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) عرصوف الاًکاف ؛ چوبی که میان دو حِنو مقدم بسته شود. (منتهی الارب ) (از اقرب الموارد). عِرصاف . عُصفور. رجوع به عرصاف و عصفور شود. ج، عَراصیف . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(182335, 'عرصوفان', '<span class=\"hlight\">عرصوفان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) تثنیه ٔ عرصوف . رجوع به عرصوف شود. <BR><font color=\"Blue\">◄</font> دو چوب که در دو چوب فدان داخل نمایند. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(182336, 'عرصوم', '<span class=\"hlight\">عرصوم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) زفت ناکس . (منتهی الارب ). بخیل .(اقرب الموارد). بخیل و زفت ناکس . (ناظم الاطباء).<br></font></div>'),
(182337, 'عرصی', '<span class=\"hlight\">عرصی .</span> <font color=\"DarkGreen\"><b>[ ع َ صی ی ]</font></b> (ص نسبی ) منسوب به عرصة. و بنواسحاق یعنی فرزندان اسحاق بن عبداﷲبن جعفربن ابی طالب بن عبدالمطلب بدانجا منسوبند. (از معجم البلدان ).<br></font></div>'),
(182338, 'عرض', '<span class=\"hlight\">عرض .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) کوهی است مشرف بر شهر «فاس » در المغرب . (از معجم البلدان ).<br></font></div>'),
(182339, 'عرض', '<span class=\"hlight\">عرض .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) وادیی است به مدینه . (منتهی الارب ). علم است وادی خیبر را، و اکنون از آن عنزة است و در آن آبها و نخل و کشتها است . (از معجم البلدان ).<br></font></div>'),
(182340, 'عرض', '<span class=\"hlight\">عرض .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) اندام . (منتهی الارب ). جسد. (اقرب الموارد). تن مردم . (مهذب الاسماء). بدن و جسد.(غیاث اللغات ). <BR><font color=\"Blue\">◄</font> هر عضو که از آن خوی آید. (منتهی الارب ). هر موضعی که از آن، یعنی از مسام آن، عرق خارج شود. ج، أعراض . (اقرب الموارد). و از آن جمله است حدیث در ذکر اهل بهشت : لایبولون و لایتغوطون، اًنما هو عرق یجری من أعراضهم مثل المسک . (از منتهی الارب ). یعنی بول و غایط نمی کنند و آن به صورت عرقی چون مشک از اعضای آنان خارج میگردد. <BR><font color=\"Blue\">◄</font> بوی اندام، خوش یا ناخوش . (منتهی الارب ). رایحه و بوی جسد خواه نیکو و طیب باشد یا بد و خبیث . (از اقرب الموارد). گویند: «فلان طیب العرض، و منتن العرض ». نفس . گویند: أکرمت عنه عرضی ؛ یعنی نفس خود را از وی محفوظ داشتم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناموس، وآبروی مرد که از نقصان و رخنه نگاه دارد. یا آبرو، خواه در نفس مرد باشد یا در آباء و اجداد یا در تبعه و لحقه، یا جای مدح و ذم از وی . یا آنچه بدان فخر کنند از حسب و شرف . و گاهی از آن آباء و اجداد مراد گیرند. (منتهی الارب ). جانب شخص که آنرا مصون و محفوظ دارد، و آن نفس او باشد یا سلف وی یا کسی که تابع وی باشد یا موضع مدح و ذم، یا آنچه بدان افتخار کند ازحسب و شرف . و گاهی منظور، پدران و نیاکان است . (از اقرب الموارد). آنچه بستایند و بنکوهند از مردم . (السامی ) (مهذب الاسماء). ناموس و آبرو. (غیاث اللغات ) (ناظم الاطباء). اموری که مدح آن آدمی را بردارد و ذم آن فرود آرد <span class=\"hlight\">:</span> <br>گنگ باد آنکس که اندر طعن تو گوید سخن <br>کور باد آنکس که اندر عرض تو جوید عوار.<br> <font color=\"Red\">فرخی .</font><br>نزد او عرض او عزیزترست <br>از گرامی تن و عزیز روان .<br> <font color=\"Red\">فرخی .</font><br>چنان بلرزد بر نام و عرض خویش همی <br>که شادکام و جهان دوست بر گرامی جان .<br> <font color=\"Red\">فرخی .</font><br>برد خواهی پیش او ناپروریده شعر خویش <br>کرد خواهی در ملامت عرض خود را مرتهن .<br> <font color=\"Red\">منوچهری .</font><br>عرض تو نپوشد مگر لباس <br>کز فخر و شرف پود و تار دارد.<br> <font color=\"Red\">مسعودسعد.</font><br>هم برون آرمش ز آهن و سنگ <br>عرضم ار در شود به باب عظیم .<br> <font color=\"Red\">مسعودسعد (دیوان چ رشید یاسمی ص <span class=\"hlight\" dir=\"rtl\">٦١٦</span>).</font><br>برون کنندش از خانه چون سگ ازمسجد<br>خسیس مرتبت و خوارعرض و بی مقدار.<br> <font color=\"Red\">کمال الدین اسماعیل (دیوان ص <span class=\"hlight\" dir=\"rtl\">٣٩٢</span>).</font><br>پس قیامت روز عرض اکبر است <br>عرض او خواهد که با زیب و فر است .<br> <font color=\"Red\">مولوی .</font><br>حافظ افتادگی از دست مده زانکه حسود<br>عرض و مال و دل و دین در سر مغروری کرد.<br> <font color=\"Red\">حافظ.</font><br>عرض و مال از در میخانه نشاید اندوخت <br>هر که این آب خورد رخت به دریا فکنش .<br> <font color=\"Red\">حافظ.</font><br>ای مگس عرصه ٔ سیمرغ نه جولانگه تست <br>عرض خود میبری و زحمت ما میداری .<br> <font color=\"Red\">حافظ.</font><br>از عشق بدعت است تمنای خون بها<br>ای خودفروش عرض شهیدان چه میبری .<br> <font color=\"Red\">میرزا صائب (از آنندراج ).</font><br>- <span class=\"hlight\">عرض و ناموس </span> ؛ از اتباع است . (یادداشت مرحوم دهخدا). به عرض و ناموس کسی دشنام گفتن، او را ناسزا و دشنام سخت دادن . رجوع به عرض و رجوع به ناموس شود.<br><BR><font color=\"Blue\">◄</font> طبیعت و خوی محمود. (منتهی الارب ). خوی پسندیده و نیکو. (از اقرب الموارد). پوست . (منتهی الارب ). جیش . (از اقرب الموارد). عَرض . رجوع به عَرض شود. <BR><font color=\"Blue\">◄</font> رودبار که در آن دهها وآبها باشد. (از منتهی الارب ). وادی و دره که در آن قری و آبها و یا نخلستان باشد. و گویند هر وادیی که در آن درخت باشد. ج، عُرضان . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شوره گیاه . (منتهی الارب ). حمض . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اراک . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گیاه تلخ شورمزه . (منتهی الارب ). اَثْل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> کرانه ٔ وادی و شهر. (منتهی الارب ) (از اقرب الموارد). کناره ٔ رود. (از مهذب الاسماء). <BR><font color=\"Blue\">◄</font> نواحی وادی و شهر. (از منتهی الارب ). ناحیه ٔ وادی و شهر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ابر بزرگ . (منتهی الارب ). بزرگ و عظیم از ابرها. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ملخ بسیار. (منتهی الارب ). تعداد بسیار از ملخ . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنکه به باطل و ناچیز فریبد مردم را. (منتهی الارب ). آنکه با مردم بباطل روبرو شود.(از اقرب الموارد).<br></font></div>'),
(182341, 'عرض', '<span class=\"hlight\">عرض .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) پیدا و آشکارا گردیدن . (از منتهی الارب ). ظاهر شدن و آشکار گردیدن، در حالی که دوام نیابد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیدا و ظاهر ساختن . (از منتهی الارب ). ظاهر کردن . (از اقرب الموارد). آشکارا کردن . (تاج المصادر بیهقی ) (دهار) (زوزنی ). و از آن جمله است گفته ٔ خداوند <span class=\"hlight\">:</span> و عرضنا جهنم یومئذ للکافرین عر<br>ضا. (قرآن <span class=\"hlight\" dir=\"rtl\">١٠٠/١٨</span>). (از منتهی الارب )؛ نمودار کردیم در آنروز جهنم را برای کافران نمودار کردنی . <BR><font color=\"Blue\">◄</font> بنمودن وپیش کردن کسی را. (از منتهی الارب ). نشان دادن . (از اقرب الموارد).<br>- <span class=\"hlight\">روز عرض </span> ؛ روز نمودار کردن . روز قیامت . یوم العرض . روز رستاخیز <span class=\"hlight\">:</span> <br>پس قیامت روز عرض اکبر است <br>عرض او خواهد که با زیب و فر است .<br> <font color=\"Red\">مولوی .</font><br>بس ملامتها که خواهد برد جان نازنین <br>روز عرض از دست جور نفس ناپرهیزگار.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">یوم العرض </span> ؛ روز قیامت . (از ناظم الاطباء) یوم الدین . (اقرب الموارد).<br> <BR><font color=\"Blue\">◄</font> نمایان گردیدن و پیش آمدن . (از منتهی الارب ). پیش آمدن . (تاج المصادر بیهقی ) (المصادر زوزنی ). گویند عرضت له الغول ؛ یعنی نمایان گردید او را غول و پیش آمد. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> رسیدن ناقه را شکستی و آفتی . (از منتهی الارب ). شکستگی و آفت به ناقه رسیدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیش آمدن کسی را حاجت . (از منتهی الارب ). عُروض .رجوع به عروض شود. <BR><font color=\"Blue\">◄</font> درآمدن عروض را. (از منتهی الارب ). آمدن به «عروض » یعنی به مکه و مدینه و آنچه در اطراف آن دو است . (از اقرب الموارد). یعنی به مکه و مدینه و یمن و آنچه در حول آنهاست . (از تاج العروس ). <BR><font color=\"Blue\">◄</font> جامه دادن کسی را به عوض حقش . (از منتهی الارب ): عرض له من حقه ثوبا؛ لباس بجای حقش بوی داد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بر یک پهلو گذشتن اسب . <BR><font color=\"Blue\">◄</font> رسیدن بر کنار چیزی . <BR><font color=\"Blue\">◄</font> مبادله نمودن از متاع خود. (از منتهی الارب ). مبادله کردن کالای خویش را، یعنی دادن آن و گرفتن دیگری . (از اقرب الموارد). بدل دادن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> کشتن . (از منتهی الارب ): عرض القوم علی السیف ؛ آن قوم را بوسیله ٔ شمشیر کشت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> به تازیانه زدن . (از منتهی الارب ): عرض القوم علی السوط؛ آن قوم را بوسیله ٔ تازیانه زد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پر کردن . (منتهی الارب ). مملو کردن . آکندن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> به بیماری مردن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> از اطراف درخت خوردن . (از منتهی الارب ): عرض البعیر؛ شتر از اَعراض درخت که قسمتهای بالای آن است، خورد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اراده کردن به سوی چیزی . (از منتهی الارب ). رفتن به سوی کسی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اراده کردن به سوی چیزی . (از منتهی الارب ). رفتن به سوی کسی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیش کردن لشکر را بر کسی و نگریستن حال آنرا. (از منتهی الارب ): عرض الجند عرض عین ؛ گذر داد سپاهیان را بر خویش و حال آنانرا نگریست، یعنی آنانرا بر دیده ٔ خود گذر داد تا حاضر و غایب آنها بشناسد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیش داشتن نامه و نبشته را. <BR><font color=\"Blue\">◄</font> عرضه داشتن سخن و جز آن . پیش آمدن ناخوشی . <BR><font color=\"Blue\">◄</font> نشان کردن بر سرین ستور. (از منتهی الارب ). داغ کردن شتر را بداغ عراض . (ناظم الاطباء). نشان کردن شتربه عِراض . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سر و گردن کج نموده رفتن اسب در دویدن . (از منتهی الارب ). روان گشتن اسب در دویدن در حالیکه سر و گردن خود را متمایل و خم کرده باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مغبون شدن در خرید و فروخت . (از منتهی الارب ): عارضه فعرضه ؛ معارضه کرد او را در خریدن پس مغبون کرد او را. (ناظم الاطباء). غلبه کرد او را در معارضه . (ازاقرب الموارد). <BR><font color=\"Blue\">◄</font> دیوانگی . (منتهی الارب ). مجنون و دیوانه شدن، و فعل آن به صیغه ٔ مجهول به کار رود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بی بیماری مردن مردم . (منتهی الارب ). بی علت و بیماری درگذشتن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیدا شدن . (منتهی الارب ). عارض گشتن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عرضه کردن چیری را بر کسی به فروختن . در مثل گویند «عرض سابری » و آن جامه ای است نیکو که با اولین عرضه داشتن، به فروش میرود و احتیاجی به مبالغه در آن نیست . (از منتهی الارب ). عرضه کردن . (تاج المصادر بیهقی ) (المصادر زوزنی ). عرضه کردن کالا بر راغبان تا آن را بخرند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بر پهنای نهادن چوب را بر خنور، و شمشیر را بر ران و نیزه را. (از منتهی الارب ). از عرض و پهنا قرار دادن چوب را بر ظرف و شمشیر را بر ران . (از اقرب الموارد). شمشیر به پهنا بر ران نهادن . چوب به پهنا نهادن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> خواندن ازبر، گویند عرض الکتاب ؛یعنی آنرا از بر خواند. (از اقرب الموارد). مقابله، چنانکه کتابی را با کتابی . (یادداشت مرحوم دهخدا): دخلت علی سعیدبن جبیر و بیده مصحف فقال اًنی قد عرضت هذا فأقمت سقطه . (المصاحف سجستانی ). <BR><font color=\"Blue\">◄</font> در نزد محدثان، خواندن حدیث است بر شیخ، و سبب تسمیه ٔ آن عرضه داشتن آن است بر شیخ خواه او خود بخواند، یا دیگری بخواند و او گوش دهد. و آنرا عرض القراءة نیز گویند. (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> در نزد محدثان، قسمی از «مناوله » را نیز عرض گویند وآن این است که طالب، کتاب شیخ را (خواه اصل آن باشد و خواه نسخه ای که با آن مقابله شده است باشد) بر او عرضه دارد. (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> (اِمص ) اظهار شخص کوچکتر مطلبی را به بزرگتر. (فرهنگ فارسی معین ). گفتگو و مکالمه ٔ شخص کوچک یا شخص بزرگ . (ناظم الاطباء). عرض کردن . رجوع به عرض کردن شود <span class=\"hlight\">:</span> <br>به عرض بندگی دیر آمدم دیر<br>وگر دیر آمدم شیرآمدم شیر.<br> <font color=\"Red\">نظامی .</font><br>در تمام عمر بی حاصل که با جانان گذشت <br>حرف رخصت بود آن عرضی که از ما گوش کرد.<br> <font color=\"Red\">میریحیی شیرازی (از آنندراج ).</font><br>- <span class=\"hlight\">به عرض رسانیدن (رساندن )</span> ؛ گفتن و بیان کردن شخص کوچکتر به بزرگتر. (از فرهنگ فارسی معین ).<br>- <span class=\"hlight\">به معرض عرض رسانیدن (رساندن )</span> ؛ به نظر شاه یا امیر رساند. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عرض داشتن </span> ؛ عارض بودن و التماس داشتن و درخواست کردن . (ناظم الاطباء).<br>- <span class=\"hlight\">عرض کردن </span> ؛ به سمع بزرگی یا صاحب مقامی رسانیدن مطلبی را. رجوع به عرض کردن در ردیف خود شود.<br>- <span class=\"hlight\">عرض و فرض </span> ؛ از اتباع . (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> خود را در آن عرصه و عداد نمی دیدم که اخراج و ازعاج من موقوف، این همه تحریر و تقدیر و عرض و فرض و وسائط و روابط باشد. (منشآت میرزا ابوالقاسم قائم مقام ).<br> <BR><font color=\"Blue\">◄</font> مکالمه از روی تضرع و خضوع . <BR><font color=\"Blue\">◄</font> استدعا از شخص بزرگ بطور فروتنی و درخواست و التماس . <BR><font color=\"Blue\">◄</font> تظلم در نزد حاکم . (ناظم الاطباء).<br>- <span class=\"hlight\">عرض داشتن </span> ؛ تظلم کردن در نزد حاکم . (از ناظم الاطباء). دادخواهی . رفع قصه . قصه برداشتن .<br>- <span class=\"hlight\">عرض عارض </span> ؛ درخواست و التماس و تظلم عارض . اظهار کسی که تظلم میکند. (از ناظم الاطباء).<br> <BR><font color=\"Blue\">◄</font> پیشداشت نامه . (ناظم الاطباء). پیش کردن نامه . <BR><font color=\"Blue\">◄</font> گزارش و بیان . (ناظم الاطباء). شرح و بیان . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عرض اندام </span> ؛ خودنمایی . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عرض دیدار کردن </span> ؛ نمودن و نمایش دادن . (ناظم الاطباء).<br>- <BR><font color=\"Blue\">◄</font> روی بنمودن و روی خود را ظاهر ساختن . (ناظم الاطباء).<br>- <span class=\"hlight\">عرض مراد کردن </span> ؛ شرح مراد دادن . (ناظم الاطباء).<br>- <span class=\"hlight\">عرض وجود</span> ؛ عرض اندام . خودنمایی . (فرهنگ فارسی معین ).<br> <BR><font color=\"Blue\">◄</font> سان . (از ناظم الاطباء). مانور. دفیله . رژه <span class=\"hlight\">:</span> <br>این چو روز بار لشکر پیش میر میرزاد<br>وان چو روز عرض پیلان پیش شاه شهریار.<br> <font color=\"Red\">منوچهری .</font><br>هیچ سالی نیست کز دینار سیصد چارصد<br>از پی عرض حشم کمتر کنی در آستین .<br> <font color=\"Red\">منوچهری .</font><br>ز بهر عرض آن مشکین نقابان <br>به نزهت سوی میدان شد شتابان .<br> <font color=\"Red\">نظامی .</font><br>زمین را عرض نیزه تنگ داده <br>هوا را موج بیرق رنگ داده .<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">عرض دادن </span> ؛ سان دادن . در معرض بازدید امیری یا فرماندهی قرار دادن سپاهیان را. رجوع به عرض دادن در ردیف خود شود.<br>- <span class=\"hlight\">عرض لشکر کردن </span> ؛ سان لشکر دیدن و نگریستن مر حال لشکر را. (ناظم الاطباء). عرض جند.<br> <BR><font color=\"Blue\">◄</font> (اِ) لشکر. (منتهی الارب ). لشکر بزرگ . (از اقرب الموارد). و آنرا عِرض نیز خوانده اند. (از منتهی الارب ) (از اقرب الموارد). ج، أعراض . (منتهی الارب ). و ماهو الاّ عرض ٌ من الأعراض ؛ نیست او مگر لشکری از لشکریان . (از منتهی الارب ).<br>- <span class=\"hlight\">دیوان عرض </span> ؛ وزارت جنگ . (از فرهنگ فارسی معین ). دستگاهی که به کار لشکریان پردازد. دیوان که کار سپاهیان از محاسبه و شمارش و غیره کند <span class=\"hlight\">:</span> <br>بدو داد دیوان عرض سپاه <br>بفرمود تا پیش درگاه شاه .<br> <font color=\"Red\">فردوسی .</font><br>خواجه بوالقاسم کثیر نیز به دیوان عرض می نشست . (تاریخ بیهقی <span class=\"hlight\" dir=\"rtl\">٢٨٧</span>). امیر مسعود ... با خواجه احمد حسن وزیر خلوت کرد به حدیث دیوان عرض . (تاریخ بیهقی ). خواجه بزرگ بوسهل را بخواند، نائبان دیوان عرض و شمارها بخواست . (تاریخ بیهقی ).<br> <BR><font color=\"Blue\">◄</font> دفتر محاسبه ٔ سپاه <span class=\"hlight\">:</span> نام او فرمود تا در دیوان عرض فارس الفرسان نبشتند. (تاریخ سیستان ).<br>- <span class=\"hlight\">شغل عرض </span> ؛ کار مربوط به لشکر و محاسبه ٔ سپاه <span class=\"hlight\">:</span> بوسهل را نیز به شغل عرض مشغول کردیم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٣٤</span>). فرمودیم تا دست وی را از شغل عرض کوتاه کردند. (تاریخ بیهقی ). پیغام داد پوشیده به امیر، که شغل عرض با خلل است . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٥٤</span>).<br></font></div>'),
(182342, 'عرض', '<span class=\"hlight\">عرض .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) پهنا، خلاف طول . (منتهی الارب ). خلاف طول . (از اقرب الموارد). و عادت مردمان چنان رفته است که درازترین بعدی را طول نام کنند، ای درازا، و آنکه از او کمتر است، عرض، أی پهنا. (از التفهیم ). پهنا. (کشاف اصطلاحات الفنون ). یکی از ابعاد سه گانه که از طول کوتاه تر است . (یادداشت مرحوم دهخدا). پهنا. پهنی . فراخنا. انزن <span class=\"hlight\">:</span> و جنَّة عرضها کعرض السماء و الارض . (قرآن <span class=\"hlight\" dir=\"rtl\">٢١/٥٧</span>)؛ و بهشتی که عرض آن چون عرض آسمان و زمین است . و جنّة عرضها السماوات و الأرض اُعدت للمتقین . (قرآن <span class=\"hlight\" dir=\"rtl\">١٣٣/٣</span>)؛ و بهشتی که عرض آن آسمانها و زمین است و برای پرهیزکاران آماده شده است .<br>نه طول است او را نه عرض و نه عمق <br>نه اندر سطوح و نه در انتهاست .<br> <font color=\"Red\">ناصرخسرو.</font><br>گر طول و عرض همت او داردی سپهر<br>خورشید کی رسیدی هرگز به باختر.<br> <font color=\"Red\">مسعودسعد.</font><br>اینک مواقف عرفاتست بنگرش <br>طولش چو عرض جنت و صد عرض اکبرش .<br> <font color=\"Red\">خاقانی .</font><br>ذکر مقامات در نصرت دین و اثارت معالم یقین از عرض دریا بگذشت و تا دریاء مصر برسید. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٦٢</span>).<br>- <span class=\"hlight\">در عرض فلان بودن </span> ؛ برابر و مساوی و کفوآن بودن . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">عرض انسان یا حیوان </span> ؛ بعد اوست از سمت راست تا چپ . و برخی گویند عرض حیوان، از سر اوست تا دم . (از کشاف اصطلاحات الفنون ).<br>- <span class=\"hlight\">عرض بلد</span> ؛ عرض جغرافیایی . رجوع به ترکیب عرض جغرافیایی شود.<br>- <span class=\"hlight\">عرض جغرافیایی </span> ؛ یا عرض بلد، در اصطلاح نجوم و جغرافیا، بعد آن باشد از خط استواء.(یادداشت مرحوم دهخدا). دوری بود از منطقة البروج سوی شمال یا جنوب . (از التفهیم ). فاصله ٔ هر نقطه یا شهر را از خط استوا بحسب درجه، عرض جغرافیایی آن نقطه گویند. بنابراین مبداء عرض جغرافیایی خط استوا است .و آنرا اگر در شمال خط استوا باشد عرض شمالی یا مثبت، و اگر در جنوب خط استوا باشد عرض جنوبی یا منفی گویند. عرض استوا را صفر و نقطه ٔ قطبی را <span class=\"hlight\" dir=\"rtl\">٩٠</span> درجه گیرند. پس عرض جغرافیایی مابین صفر و <span class=\"hlight\" dir=\"rtl\">٩٠</span> خواهد بود. (فرهنگ فارسی معین ). و رجوع به کشاف اصطلاحات الفنون شود.<br>- <span class=\"hlight\">عرض دادن </span> ؛ عریض کردن . پهن کردن . اتساع دادن .<br>- <BR><font color=\"Blue\">◄</font> به معرض سان و رژه درآوردن . گذرانیدن افراد سپاهی و غیره برای ملاحظه ٔ فرمانده یا امیر.<br>- <span class=\"hlight\">عرض داشتن </span>؛ پهناور بودن . (ناظم الاطباء). عریض بودن . پهنا داشتن .<br>- <span class=\"hlight\">عرض و طول </span> ؛ پهنائی و درازی . (ناظم الاطباء).<br> <BR><font color=\"Blue\">◄</font> با شهرت و نام آور، در امتداد زمان <span class=\"hlight\">:</span> اسکندر مردی بوده است با طول و عرض و بانگ و برق و صاعقه . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٩١</span>). <BR><font color=\"Blue\">◄</font> متاع و رخت، و آنرا عَرَض نیز خوانده اند. (از منتهی الارب ). متاع . (از اقرب الموارد). متاع، و آن چیزی است که کیل و وزن در آن داخل نشود و حیوان و عقار نیز نباشد. (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> هر چیز جز زر و سیم . (منتهی الارب ). هر چیز جز دو نقد، یعنی درهم و دینار. و گویند دینار و درهم «عین » است و آنچه غیر از آن است «عرض » می باشد. (از اقرب الموارد). آنچه غیر نَقَدین است از مال . (از کشاف اصطلاحات الفنون ). ج، عُروض . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> کوه، یا روی کوه، یا کرانه ٔ آن، یا جائی که از آن بر کوه برآیند. (منتهی الارب ). کوه و جبل، و یا دامنه ٔ آن، ویا کنار و جانب آن، و یا محلی که کوه از آنجا برآمده است . (از اقرب الموارد). کوه . و کنار کوه . و روی کوه . (کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> ملخ بسیار.(منتهی الارب ) (کشاف اصطلاحات الفنون ). تعداد بسیار از ملخ . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> فراخی . (از منتهی الارب ) (از کشاف اصطلاحات الفنون ). سعت . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> وادی . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ساعتی از شب . (منتهی الارب ). عرض من اللیل ؛ ساعتی از شب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ابر. یا ابر که کرانه ٔ آسمان را فراگیرد. (منتهی الارب ). ابر، و یا آنچه افق را سد کند و بپوشاند. (از اقرب الموارد). ج، عُروض و عِراض و أعراض . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> قصد و همت . عُرض . <BR><font color=\"Blue\">◄</font> روستا. (منتهی الارب ). ج، أعراض و از آن است أعراض الحجاز، یعنی رساتیق آن . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> میان و اطراف . (از ناظم الاطباء). معظم یا میان یا جانب ؛ رأیته فی عرض الناس ؛ او را در معظم مردم یا در میان آنان یا در طرف و جانب آنان دیدم . (ازاقرب الموارد). عُرُض . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> عریضه . (ناظم الاطباء).<br>- <span class=\"hlight\">عرض داشتن </span> ؛ عریضه داشتن . (ناظم الاطباء). مطلبی گفتنی داشتن .<br> <BR><font color=\"Blue\">◄</font> در اصطلاح اهل عربیت، طلب فعل است بنرمی و تأدب، و ادات آن «ألا» باشد. مانند ألاتنزل عندنا فتصیب خیراً، نزد ما فرود آی تا به خیر برسی . و منظور سخنی است که بر طلب فعل و عمل دلالت کند و آن نوعی از انشاء است . (از کشاف اصطلاحات الفنون ) (از اقرب الموارد).و رجوع به مغنی اللبیب شود. <BR><font color=\"Blue\">◄</font> در اصطلاح حکما، سطح . و آن چیزی است که آنرا دو امتداد باشد. واز این معنی است که گویند هر سطحی فی نفسه عریض است . (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> در اصطلاح حکما، امتداد مفروض ثانی است که امتداد مفروض اول رابر پایه هایی قطع کند. و آن بعد دوم از ابعاد سه گانه ٔ جسم است . (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> در اصطلاح حکما، امتداد اقصر و کوتاه تر است . (از کشاف اصطلاحات الفنون ).<br>- <span class=\"hlight\">از عرض دور کردن </span> ؛ کشتن و هلاک کردن . (ناظم الاطباء).<br>- <BR><font color=\"Blue\">◄</font> آزار دادن ورنج رساندن . (ناظم الاطباء).<br>- <BR><font color=\"Blue\">◄</font> دشنام دادن . (ناظم الاطباء).<br>- <BR><font color=\"Blue\">◄</font> فانی کردن . (ناظم الاطباء).<br></font></div>'),
(182343, 'عرض', '<span class=\"hlight\">عرض .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (از ع، ص، اِ) مخفف عارض . عرض دهنده ٔ لشکر. شمارکننده ٔ سپاهیان . سان دهنده . (فرهنگ فارسی معین ). مفتش . لشکرنویس <span class=\"hlight\">:</span> <br>و از آن جایگه شد به پرده سرای <br>عرض پیش او رفت با رهنمای .<br> <font color=\"Red\">فردوسی .</font><br>عرض را بخوان تا بیارد شمار<br>که چند است مردم که آید بکار.<br> <font color=\"Red\">فردوسی .</font><br>عرض با جریده بنزدیک شاه <br>بیامد بیاورد مرّ سپاه .<br> <font color=\"Red\">فردوسی .</font><br>نوشتی عرض نام و دیوان اوی <br>بیاراستی کاخ و میدان اوی .<br><font color=\"Red\">فردوسی .</font><br></font></div>'),
(182344, 'عرض', '<span class=\"hlight\">عرض .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) آنچه لاحق گردد مردم را از بیماری و جز آن . و گزند. (منتهی الارب ). آنچه از مرض و غیره بر انسان عارض شود. (از اقرب الموارد). بیماری و رنجی که بسبب رنجی حادث شود چنانکه صداع که بسبب تب حادث شود و تب که بسبب وجعی پیدا گردد. (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> مال دنیا. (منتهی الارب ). حطام دنیا. (اقرب الموارد). گویند: الدنیا عرض حاضر، یأکل منها البر و الفاجر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مال، اندک باشد یا بسیار. (منتهی الارب ) (ازاقرب الموارد). از آن جمله است که گویند: لیس الغنی عن کثرة العرض اًنما الغنی غنی النفس . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> متاع و کالا. عَرض . رجوع به عَرض شود. کالا. (انصاب ) <span class=\"hlight\">:</span> یأخذون عرض هذا الادنی و یقولون سیغفر لنا، و اًن یأتهم عرض مثله یأخذوه . (قرآن <span class=\"hlight\" dir=\"rtl\">١٦٩/٧</span>)؛ میگیرند متاع و کالای این ادنی راو میگویند آمرزیده خواهیم شد، اگر ایشان را متاعی مانند آن آید آن را می گیرند. تریدون عرض الدنیا و اﷲ یرید الاَّخرة. (قرآن <span class=\"hlight\" dir=\"rtl\">٦٧/٨</span>)؛ متاع و کالای این دنیا را میخواهید و خداوند آخرت را میخواهد. لتبتغوا عرض الحیاة الدنیا. (قرآن <span class=\"hlight\" dir=\"rtl\">٣٣/٢٤</span>)؛ تا متاع زندگی دنیا را به دست آرید. لو کان عرضا قریبا و سفرا قاصدا لاتبعوک . (قرآن <span class=\"hlight\" dir=\"rtl\">٤٢/٩</span>)؛ اگر کالایی قریب الوصول و یا سفری آسان بود هر آینه پیروی میکردند ترا. تبتغون عرض الحیاة الدنیا. (قرآن <span class=\"hlight\" dir=\"rtl\">٩٤/٤</span>)؛ کالای زندگی دنیا را میخواهید.<br>گوهری اندر خرابه بی عرض <br>خون دل بر رخ فشانده از مرض .<br> <font color=\"Red\">مولوی .</font><br> <BR><font color=\"Blue\">◄</font> غنیمت . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> لشکر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آز. (منتهی الارب ). طمع. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> چیزی که پیوسته نباشد، اسم است آنرا. (از منتهی الارب ). اسم است آنچه را دوام نداشته باشد. (از اقرب الموارد). و از آن جمله است که گویند: الدنیا عرض حاضر، یأکل منه البر و الفاجر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> هر چیز که به غفلت رسد و بی آهنگ به هوی و عشق کسی درآویخته شود. (ناظم الاطباء) (از منتهی الارب ) . آنچه بناگهان به چیزی برسد. (از اقرب الموارد). گویند علقتها عرضا (به صیغه ٔ مجهول ). یعنی غفلةً به من رسید پس بدون آهنگ و قصد عاشق آن شدم . (از منتهی الارب ) (از ناظم الاطباء) (از اقرب الموارد). و گویند أصابه سهم ُ عرض (به اضافه ) و نیز حجرُ عرض، یعنی تیر یا سنگ که به دیگری انداخته باشند بر وی آمد. (از منتهی الارب ) (از ناظم الاطباء) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> در اصطلاح منطق، هر چه قائم به چیزی دیگر باشد. (از منتهی الارب ). نزد حکما و متکلمان و غیره، موجودی است که برای وجود داشتن، احتیاج به موضع و محلی دارد که در آن بپای ایستد. ج، أعراض . (اقرب الموارد). چیزی است که بدان تمییز دهند چیزی را از چیزی نه فی ذاته . مثل سپیدی و سیاهی و گرمی وسردی و مانند آنها. (از مفاتیح العلوم ). ممکن که دربقاء وجود محتاج باشد به غیری . (یادداشت مرحوم دهخدا). آنچه قائم به غیر باشد چون الوان و صفات . (یادداشت مرحوم دهخدا). موجودی که برای وجود داشتن احتیاج به موضع یعنی محلی دارد که در آن قائم باشد و یا احتیاج به جسمی دارد که در آن حلول کند و اعراض بردو نوعند: قارالذات، و آن عرضی است که اجزاء آن در وجود گرد آید، مثل سپیدی و سیاهی، و غیر قارالذات، و آن عرضی است که اجزاء آن در وجود گرد نیاید، مانند حرکت وسکون . (از تعریفات جرجانی ). چیزی است که مقابل جوهرباشد. و نیز بر کلی محمول بر شی ٔ خارج از آن، اطلاق میشود. و آنرا عرضی نیز نامند در مقابل ذاتی . (از کشاف اصطلاحات الفنون ). چیزی که قائم به چیزی باشد. مثل رنگ بر جامه و حروف بر کاغذ، پس جامه و کاغذ جوهر باشد چرا که به ذات خود قایم است، و رنگ و حروف عرض، چرا که قیام آن بوسیله ٔ جامه و کاغذ است . (غیاث اللغات ). عرض عبارت از موجودی است که وجود آن فی نفسه عین وجودش برای غیر و در غیر باشد. و گفته اند «العرض هو موجود فی شی ٔ غیرمتقوم به لاکجزء منه، ولایصح قوامه دون ماهوفیه » مانند بیاض و سواد و غیره که وجود آنهافی نفسه عین وجود آنها است برای غیر و در غیر خود. و یا چیزی است که حال در غیر و شایع در آن باشد. و یا ماهیتی است که وجودش فی نفسه عبارت از وجودش در موضوع باشد. شیخ الرئیس گوید: «عرض آن بود که هستی وی اندر چیزی دیگر ایستاده بود که آن چیز بی وی هستیش خود تمام بود». بنابراین عرض موجودی است که هرگاه در خارج موجود شود ناچار وجودش در موضوعی از موضوعات خواهد بود. و مقولات عرضی نه مقوله اند: فعل، انفعال، أین، متی، کیف، کم، وضع، ملک، اضافه . (از فرهنگ علوم عقلی، از تهافت التهافت و تفسیر کشاف و اسفار و درةالتاج و دانشنامه ٔ الهی ) <span class=\"hlight\">:</span> <br>چنین بود پدری کش چنین بود فرزند<br>چنین بود عرضی کش چنین بود گوهر.<br> <font color=\"Red\">عنصری .</font><br>مردمی چیست مردمی عرض است <br>جز دل پاک اوش جوهر نیست .<br> <font color=\"Red\">عنصری .</font><br>آن از پی آن نیست که تا نیست شود خلق <br>و آن هست عرض طالع عالم سرطان را.<br> <font color=\"Red\">ناصرخسرو.</font><br>بود قابل عرض بی شک فنا را<br>ولی جوهربود قابل بقا را.<br> <font color=\"Red\">ناصرخسرو.</font><br>چو تنت از عرض جامه دارد بدان <br>که مرجانت را جامه ٔ جوهریست .<br> <font color=\"Red\">ناصرخسرو.</font><br>قضا ز دست تو اندر عرض نشاند تیغ<br>قدر زشست تو اندر عدم نشاند تیر.<br> <font color=\"Red\">ابوالفرج رونی .</font><br>هست ممکن که قوت و حرکت <br>عرض پنجه ٔ چنار شود.<br> <font color=\"Red\">مسعودسعد.</font><br>درچه خصمی داشت این دعوی کجا معنی بود<br>در همه معنی عرض کی دعوی جوهر گرفت .<br> <font color=\"Red\">مسعودسعد.</font><br>بشمشیر او باز بسته ست گیتی <br>عرض باز بسته ست لابد به جوهر.<br> <font color=\"Red\">ازرقی .</font><br>نه جود را غرضی حاصل است بی کف تو<br>نه در جهان عرضی ممکن است بی جوهر.<br> <font color=\"Red\">ادیب صابر.</font><br>نباشد جدا از کف او سخاوت <br>عرض را جدائی نباشد ز جوهر.<br> <font color=\"Red\">ادیب صابر.</font><br>گر به انواع فضل خود نگری <br>عرضند اهل فضل و تو جوهر.<br> <font color=\"Red\">سوزنی .</font><br>اگر خواستی میان جوهر و عرض تفرقه افکندی . (ترجمه تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٤٠</span>).<br>دیدن او بی عرض و جوهر است <br>کز عرض و جوهر از آنسوتر است .<br> <font color=\"Red\">نظامی .</font><br>ظلمتیان را بنه بی نور کن <br>جوهریان را ز عرض دورکن .<br> <font color=\"Red\">نظامی .</font><br>جمله اجزای جهان را بی غرض <br>درنگر حاصل نشد جز از عرض .<br> <font color=\"Red\">مولوی .</font><br>که غرض اظهار سر جوهر است <br>وصف باقی و این عرض بر معبر است .<br> <font color=\"Red\">مولوی .</font><br>زانکه عقلت جوهر است این دو عرض <br>این دو در تکمیل آن شد مفترض .<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">عرض خاص </span> ؛ عرض که مختص به یک طبیعت واحد، یعنی یک حقیقت باشد. (از کشاف اصطلاحات الفنون ). عرض که مختص به افراد یک حقیقت باشد. عرض خاص اعم از آنکه لحوقش بلاواسطه باشد مانند تعجب برای انسان، و یا با واسطه مانند ضحک که با واسطه ٔ تعجب عارض بر انسان شود. و حرکت ارادی که لحوق آن بر انسان بواسطه ٔ جزء ذاتی آن که حیوانیت است میباشد. (از فرهنگ علوم عقلی ). و رجوع به عرض ذاتی شود.<br>- <span class=\"hlight\">عرض ذاتی </span> ؛ عرضی است که منشاء آن ذات باشد و از ملحقات و عوارض ذاتی اشیاء باشد. مانند تعجب که عارض و لاحق ذات انسان است . (فرهنگ علوم عقلی ). و رجوع به عرض خاص شود.<br>- <span class=\"hlight\">عرض روح </span> ؛ آنچه بر روح عارض شده باشد. عارضه که روح را افتد <span class=\"hlight\">:</span> <br>حذق تو چنان است که بی نبض و دلیلی <br>می بازنمائی عرض روح بهنجار.<br> <font color=\"Red\">سنایی (دیوان چ مدرس رضوی ص <span class=\"hlight\" dir=\"rtl\">١٩٤</span>).</font><br>- <span class=\"hlight\">عرض عام </span> ؛ عرض که مختص طبیعت واحدی نباشد. عرض که شامل بیش از یک طبیعت باشد. مانند «ماشی » برای انسان . (از کشاف اصطلاحات الفنون ). به اصطلاحات منطقیان، کلیی است که صادق می آید بر کثیرین که مختلف باشد در حقیقت و جزو و افراد نباشد. چنانکه ماشی که صادق است بر انسان و فرس و بقر، که مختلف اند در حقیقت و جزو ایشان نیست . (غیاث اللغات ) (آنندراج ).یکی از کلیات خمس است و آن عرضی است مشترک بین افراد حقایق مختلف .<br>- <span class=\"hlight\">عرض لازم </span> ؛ عرض که انفکاک آن از ماهیت ممتنع باشد. مانند خندیدن بالقوه، برای انسان و کاتب بالقوه، نسبت به انسان . (ازتعریفات جرجانی ) (از کشاف اصطلاحات الفنون ). عرض که انفکاک آن از معروض خود محال باشد مانند کتابت بالقوة، برای انسان . و عوارض لازمه را عوارض محموله هم گویند. مانند سفیدی و سیاهی برای جسم . (از فرهنگ علوم عقلی ).<br>- <span class=\"hlight\">عرض محمول </span> ؛ عرض لازم . عوارض محموله . عوارض لازمه . رجوع به عرض لازم شود.<br>- <span class=\"hlight\">عرض مُفارق </span> ؛ یا عرض غیر لازم، عرض که انفکاک آن از ماهیت ممتنع نباشد، مانند خندیدن بالفعل، برای انسان . (از کشاف اصطلاحات الفنون ).آن است که انفکاک آن از شی ٔ ممتنع نباشد. و آن یا سریع الزوال است چون سرخی شرم و خجل، و زردی بیم و ترس ؛ و یا بطی ءالزوال است چون پیری و جوانی . (از تعریفات جرجانی ). عرض که انفکاک آن از معروض خود ممکن باشد، چه آنکه بالفعل زائل شود و یا بالقوه، و زوال آن بسرعت باشد و یا به طور کندی و بطؤ، مانند زردی و سرخی برای خجول و ترسان . (از فرهنگ علوم عقلی ).<br>- <span class=\"hlight\">عرض ناپذیر</span> ؛ غیرقابل عرض بودن . که عرض را نپذیرد. که قبول عرض نکند<span class=\"hlight\">:</span> <br>نه قائم به ذات است و نی جایگیر<br>عرض ناپذیر است و بی التقاست .<br> <font color=\"Red\">ناصرخسرو.</font><br><BR><font color=\"Blue\">◄</font> نزد معتزله، احوال جوهر است . چون حرکت در متحرک و سفیدی در سفید و سیاهی در سیاه . (یادداشت مرحوم دهخدا). آنچه در جوهر، عارض شود. چون الوان و طعم ها و ذوق و لمس و غیره که بقای آنها پس از وجود جوهر مستحیل است . (از تعریفات جرجانی ).<br></font></div>'),
(182345, 'عرض', '<span class=\"hlight\">عرض .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع مص ) بس فربه و پرگوشت شدن از کثرت گیاه . (از منتهی الارب ). شکافته شدن گوسفند از کثرت علف، یعنی از چرا کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیدا و آشکار گردیدن . <BR><font color=\"Blue\">◄</font> نمایان گردیدن و پیش آمدن، چنانکه گویند عرضت له الغول . <BR><font color=\"Blue\">◄</font> شکستگی و آفت رسیدن . (از منتهی الارب ). عَرض . رجوع به عَرض شود.<br></font></div>'),
(182346, 'عرض', '<span class=\"hlight\">عرض .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) مزارع است در حوالی مسجد قبلتین . (منتهی الارب ).<br></font></div>'),
(182347, 'عرض', '<span class=\"hlight\">عرض .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ]</font></b> (ع اِ) گوشه ٔ چشم . گویند: نظر اًلیه من عرض ؛ نگریست به وی از گوشه ٔ چشم . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> نوعی سیر و حرکت که در اسب ستوده است و در شتر نکوهیده . (از اقرب الموارد). عُرض و رجوع به عُرض شود.<br></font></div>'),
(182348, 'عرض', '<span class=\"hlight\">عرض .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) نخلستان و رودباری است در یمامة. (منتهی الارب ). عرض الیمامة، وادی یمامه است که از مهب شمال به سوی مهب جنوب جاری شود. و قرایی که در اطراف آن است «سفوح » نامیده میشود. و تمام این عرض از آن بنی حنیفه است و اندکی از آن متعلق به بنی امرج از بنی سعدبن زید مناةبن تمیم . (از معجم البلدان ). <BR><font color=\"Blue\">◄</font> یوم العرض، از ایام و جنگهای عرب است، که عمروبن صابر، فارس ربیعه به دست جزٔبن علقمه تمیمی در آن روز کشته شد. (از معجم البلدان ).<br></font></div>'),
(182349, 'عرض', '<span class=\"hlight\">عرض .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (ع مص ) پهن گردیدن . (از منتهی الارب ). پهن شدن، ضد دراز گشتن .(از اقرب الموارد). انبساط و گسترش در خلاف جهت طول .(از تعریفات جرجانی ). عَراضة. رجوع به عراضة شود.<br></font></div>'),
(182350, 'عرض', '<span class=\"hlight\">عرض .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) بن کوه . (منتهی الارب ). دامنه ٔ کوه . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> روی کوه . <BR><font color=\"Blue\">◄</font> کرانه . (منتهی الارب ).جانب . (اقرب الموارد). کرانه و جانب . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> طرف . (منتهی الارب ). ناحیه . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> میانه ٔ جوی و دریا، میانه ٔ هر چیز. (منتهی الارب ). وسط نهر و بحر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> حدیث بهتر و بزرگ . (از منتهی الارب ). معظم و بیشتر از حدیث و سخن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مردم بزرگ و شریف . (منتهی الارب ). معظم و بیشتر مردم . (از اقرب الموارد). عَرض . <BR><font color=\"Blue\">◄</font> رخسار شمشیر. (منتهی الارب ). پهنای شمشیر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> هر دو جانب گردن . (منتهی الارب ). جانب گردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نوعی از رفتار که به نسبت اسب نیکو و به نسبت شتر بد است . (از منتهی الارب ). نوعی حرکت و سیر که در اسب ستوده است و در شتر نکوهیده و صحیح آن عُرُض است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> هو من عرض الناس : او از عامه ٔ مردم است . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناقة عرض أسفار؛ شتر ماده ٔ توانا بر سیر. (منتهی الارب ). (اقرب الموارد). <BR><font color=\"Blue\">◄</font> عرض هذالبعیر السفر، و الحجر؛ یعنی همّه و قصده . (منتهی الارب ). یعنی این شتر بر سفر و حجر قوی است . (از اقرب الموارد). یعنی بر پیمودن آن توانا است . (از تاج العروس ). <BR><font color=\"Blue\">◄</font> کل الجبن عرضا؛ یعنی پیش آر و بجو از هر که بیابی و بخور آنرا و مپرس از سازنده ٔ آن .(منتهی الارب ). عَرض . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نظر اًلیه عن عرض ؛ یعنی نگریست از گوشه ٔ چشم . (از منتهی الارب ). یعنی از کناری او را نگریست . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> هم یضربون الناس عن عرض یعنی میزنند و باک و اندیشه ندارند که کرا زدند و چگونه زدند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اِضرب ْ به عرض الحائط؛ یعنی بر پهنای دیوار یا وسط آن و نیمه و جانب . (منتهی الارب ). یعنی معترض او شو هر جای را از او یافتی، یعنی هر ناحیه و جانب از نواحی او را. (از اقرب الموارد). ج، عِراض . (منتهی الارب ).<br></font></div>'),
(182351, 'عرض', '<span class=\"hlight\">عرض .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) شهری است به شام . (منتهی الارب ). شهرکی است در بیابان شام که اکنون از اعمال حلب است . و آن بین تدمر و الرصافة الهشامیة قرار دارد. و تعدادی از بزرگان بدانجا نسبت دارند. رجوع به معجم البلدان شود.<br></font></div>'),
(182352, 'عرض افتادن', '<span class=\"hlight\">عرض افتادن .</span> <font color=\"DarkGreen\"><b>[ ع َ اُ دَ ]</font></b> (مص مرکب ) نمایان شدن . عرضه شدن . ارائه گردیدن . <BR><font color=\"Blue\">◄</font> به عرض رسیدن مطلبی . <BR><font color=\"Blue\">◄</font> پیشنهاد شدن . (فرهنگ فارسی معین ).<br></font></div>'),
(182353, 'عرض الحال', '<span class=\"hlight\">عرض الحال .</span> <font color=\"DarkGreen\"><b>[ ع َ ضُل ْ ]</font></b> (ع اِ مرکب ) در اصطلاح کاتبان و دبیران، نامه ای است که بر والی امر عرضه شود، خواه برای تظلم باشدو خواه برای درخواست کمک و نعمت . ج، عُروض الاحوال . (از اقرب الموارد). عرض حال . رجوع به عرض حال شود.<br></font></div>'),
(182354, 'عرض بیگی', '<span class=\"hlight\">عرض بیگی .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (اِمرکب ) کسی که سؤال و حاجات مردم را به عرض پادشاه رساند. (آنندراج ) (غیاث اللغات ) (از ناظم الاطباء).<br></font></div>'),
(182355, 'عرض حال', '<span class=\"hlight\">عرض حال .</span> <font color=\"DarkGreen\"><b>[ ع َ ض ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) درخواست و استدعا. (ناظم الاطباء). دادخواست .شکایت . <BR><font color=\"Blue\">◄</font> ورقه ای که درخواست یا شکایت خود را در آن نویسند. (فرهنگ فارسی معین ). درخواست نامه . عریضه . قسه . شکوائیه . و رجوع به عرض الحال شود.<br></font></div>'),
(182356, 'عرض حیات', '<span class=\"hlight\">عرض حیات .</span> <font color=\"DarkGreen\"><b>[ ع َ ض ِح َ ]</font></b> (ترکیب اضافی، اِ مرکب ) به خوبی و خوشی گذشتن ایام زندگانی . (آنندراج ) (غیاث اللغات ) <span class=\"hlight\">:</span> <br>از آب زندگی به شراب التفات کن <br>از طول عمر صلح به عرض حیات کن .<br><font color=\"Red\">میرزا صائب (از آنندراج ).</font><br></font></div>'),
(182357, 'عرض دادن', '<span class=\"hlight\">عرض دادن .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (مص مرکب ) نشان دادن . نمودن . ارائه دادن . به معرض نهادن <span class=\"hlight\">:</span> قریب صد و پنجاه هزار سوار لشکر سلطان عرض داده بودند بیرون پیاده که صدهزار دیگر بودند. (تاریخ سیستان ). نسختی که ... خود نبشته بود بر رای سلطان عرض داد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤١٣</span>).<br>سبزه ٔ سر نهاده عرض دهد<br>هر نمی کز سحاب می چکدش .<br> <font color=\"Red\">خاقانی .</font><br>عضدالدوله خواست تا خود را بر نظر اعتبار ایشان عرض دهد از جهت آنچه راجع بود به او از استظهار و استیلاء و ... (ترجمه ٔ محاسن اصفهان آوی ).<br>- <span class=\"hlight\">عرض سخن دادن </span> ؛ بیان کردن مطلب . بازگفتن سخن <span class=\"hlight\">:</span> <br>دهم چه عرض سخن بر سیه دلان صائب <br>به خاک تیره چه ریزم شراب بی غش را.<br> <font color=\"Red\">میرزاصائب (از آنندراج ).</font><br> <BR><font color=\"Blue\">◄</font> سان دادن . دفیله دادن . رژه دادن از برای معاینه و ملاحظه از برابر کسی گذراندن <span class=\"hlight\">:</span> پس رسول باز آمد و گفت هزاز هزار فیل گوش عرض دادند و تا سه روز دیگر اینجا رسند. (اسکندرنامه، نسخه ٔ مرحوم سعید نفیسی ). و اسپان گزیده کی هر جای بر طویله ها و آخرها بسته بودند، بوقتی کی عرض دادی میگویند هشتاد هزار سر برآمد. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١٠٣</span>). و گودرز اصفهبد خراسان بود و فرمود تا لشکر را عرض دهد. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٤٥</span>).<br>تا عرض دهد لشکر پیروزه سلب را<br>بر پشته و بالای زمین راجل و راکب .<br> <font color=\"Red\">سوزنی .</font><br>داد نقیب صبا عرض سپاه بهار<br>کز دو گروهی بدید یاوگیان خزان .<br> <font color=\"Red\">خاقانی (دیوان چ سجادی ص <span class=\"hlight\" dir=\"rtl\">٣٣٢</span>).</font><br>شاهی که عرض لشکر منصور اگر دهد<br>از قیروان سپاه کشد تا به قیروان .<br><font color=\"Red\">سعدی (دیوان، چ مصفا، ص <span class=\"hlight\" dir=\"rtl\">٧١٩</span>).</font><br></font></div>'),
(182358, 'عرض داشتن', '<span class=\"hlight\">عرض داشتن .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (مص مرکب ) نمایاندن . آشکار کردن . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>آئینه ٔ سکندر جام جم است بنگر<br>تا بر تو عرض  دارد احوال ملک دارا.<br> <font color=\"Red\">حافظ (از آنندراج ).</font><br><BR><font color=\"Blue\">◄</font> به عرض رسانیدن، مطلبی را. <BR><font color=\"Blue\">◄</font> تظلم کردن، نزد قاضی و حاکم . <BR><font color=\"Blue\">◄</font> درخواست کردن . (فرهنگ فارسی معین ).<br></font></div>'),
(182359, 'عرض دیدن', '<span class=\"hlight\">عرض دیدن .</span> <font color=\"DarkGreen\"><b>[ ع َ دی دَ ]</font></b> (مص مرکب ) درعرف حال معنی موجودات گرفتن است . اعم از آنکه سپاه باشند یا چیز دیگر از نقد و جنس . (آنندراج ). <BR><font color=\"Blue\">◄</font> سان دیدن . رژه دیدن . دفیله گرفتن <span class=\"hlight\">:</span> <br>چو پاس عصمت خود فرض می دید<br>سپاه ناز خود را عرض می دید.<br><font color=\"Red\">آصف خان جعفر (از آنندراج ).</font><br></font></div>'),
(182360, 'عرض شدن', '<span class=\"hlight\">عرض شدن .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ُ دَ ]</font></b> (مص مرکب ) معروض شدن . (از آنندراج ) <span class=\"hlight\">:</span> <br>گر ز صد آرزوی وصل یکی بشماری <br>تا قیامت نشود عرض تمنای دلم .<br><font color=\"Red\">حسین ثنائی (از آنندراج ).</font><br></font></div>'),
(182361, 'عرض عمر', '<span class=\"hlight\">عرض عمر.</span> <font color=\"DarkGreen\"><b>[ ع َ ض ِ ع ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه ازلذت عمر است . (غیاث اللغات ). کیفیت عمر، مقابل طول عمر، که مدت و درازی زندگانی است . به معنی عرض حیات است . و از شیخ بوعلی نقل می کنند که در حرص بر آرمیدن با زنان او را گفتند که ترک آرمیدن با زن عمر می افزاید، او گفت که من عرض عمر می خواهم . (از آنندراج ).<br></font></div>'),
(182362, 'عرض وار', '<span class=\"hlight\">عرض وار.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ق مرکب ) مانند عَرَض <span class=\"hlight\">:</span> <br>وانگه کزین مزاج مهیا جدا شوند<br>چیزند یا نه چیز عرض واربگذرند.<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(182363, 'عرض کار', '<span class=\"hlight\">عرض کار.</span> <font color=\"DarkGreen\"><b>[ ع َ ض ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) جلوه دادن کار. نمایش دادن کار <span class=\"hlight\">:</span> <br>تا به وقتی که عرض کار بود<br>گر چه درویش تاجدار بود.<br><font color=\"Red\">نظامی .</font><br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(182364, 'عرض کردن', '<span class=\"hlight\">عرض کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ دَ ]</font></b> (مص مرکب ) نشان دادن . آشکار کردن . (فرهنگ فارسی معین ). نمودن . ارائه کردن . عرضه داشتن . عرضه کردن . معروض داشتن . پیش نهادن . تقدیم کردن . نمایش دادن . به معرض درآوردن <span class=\"hlight\">:</span> امیر فرمود تا زندانهای غزنی و آن نواحی عرض کنند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٧٣</span>). بگیر از نفس خود پیمان ...بهمراهی این آورنده نبشته و آنرا بر همه ٔ مردم خود عرض کن . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣١٣</span>). استادم چون نامه بخواندپیش امیر شد و نامه عرض کرد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٧١</span>).<br>ز هرگونه نو جانور صدهزار<br>کند عرض هزمان درین عرضه زار.<br> <font color=\"Red\">اسدی .</font><br>به هر شهرکی ببردندی و خط بیاع بدان عرض کردندی به سود بازخریدندی ناگشاده . (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١٤٦</span>). روزی بر سلیمان علیه السلام اسب عرض کردند، وی گفت شکر خدای تعالی را که دو باد را فرمان بردار من کرد. (نوروزنامه ). من میخواهم که در این فرصت خویشتن رابر شیر عرض کنم . (کلیله و دمنه ).<br>به ما بر خدمت خود عرض کردی <br>جزای آن بخود بر فرض کردی .<br> <font color=\"Red\">نظامی .</font><br>یک چندی شحنه ٔزندان را بفرماید عرض زندانیان کردن تا بی گناه را خلاص کند. (نصیحة الملوک سعدی ).<br>بازی چرخ بشکندش بیضه در کلاه <br>زیرا که عرض شعبده با اهل راز کرد.<br> <font color=\"Red\">حافظ.</font><br>پسر خود را محمد مهدی بر ما عرض کرد و او را بما نمود. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٢٠٥</span>). بَور؛ عرض کردن شترماده بر شتر نر تا دانسته شود که آبستن است یا نه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سان دیدن . رژه گرفتن . ملاحظه و معاینه ٔ افراد سپاهی هنگام عبور از برابر <span class=\"hlight\">:</span> خبر به مروان بن محمد شد، مردمان را گرد کرد فزون از چهل هزار مرد عرض کرد، و بزمین بلنجر شد. (ترجمه ٔ طبری بلعمی ). نجاشی سپاه عرض کرد هفتاد هزار مرد مقاتل بیرون کرد و به یمن فرستاد. (ترجمه ٔ طبری بلعمی ).<br>همه لشکر رومیان عرض کن <br>هر آنکس که هستند نو یا کهن .<br> <font color=\"Red\">فردوسی .</font><br>پیلان را عرض کردند، هزار و ششصد و هفتاد نر و ماده بپسندیدند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٨٥</span>). فرموده بودیم تا پیلان را برانند و به کابل آرند تا عرض کرده آید، کدام وقت رسند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٨٣</span>). همه لشکر را عرض کردند و مال ایشان بدادند.(تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٦٨</span>). <BR><font color=\"Blue\">◄</font> بیان کردن و گفتن . (ناظم الاطباء). بیان کردن . و شرح دادن، کوچکتر به بزرگتر. (فرهنگ فارسی معین ). گستردن سخن . گسترانیدن سخن را نزد کسی، ابراز کردن . اظهار کردن .<br>- <span class=\"hlight\">عرض کردن دُر</span> ؛ عرضه داشتن مروارید. پیش داشتن در <span class=\"hlight\">:</span> <br>دریا سر بوسیدن پایت دارد<br>در آمده عرض می کند بر گوشت .<br> <font color=\"Red\">ملاتجلی بخاری (از آنندراج ).</font><br> <BR><font color=\"Blue\">◄</font> تطبیق کردن . سنجیدن . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>عرض کردیم همه کشته ٔ بی حاصل خویش <br>هرچه برماست بدانستیم اکنون کز ماست .<br> <font color=\"Red\">مسعودسعد.</font><br> <BR><font color=\"Blue\">◄</font> التماس نمودن از روی خضوع و فروتنی . درخواست کردن و استدعا نمودن . <BR><font color=\"Blue\">◄</font> برگزار کردن . <BR><font color=\"Blue\">◄</font> شرح حال گفتن . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>پادشاها گرچه گستاخی است لیکن واجب است <br>عرض حال خود مرا پیشت علی الاجمال کرد.<br><font color=\"Red\">خواجه جمال الدین سلمان (از آنندراج ).</font><br></font></div>'),
(182365, 'عرضان', '<span class=\"hlight\">عرضان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) دو وادی است در یمامة یکی عرض شَمام است و دیگری عرض حَجر. رجوع به معجم البلدان شود.<br></font></div>'),
(182366, 'عرضان', '<span class=\"hlight\">عرضان .</span> <font color=\"DarkGreen\"><b>[ ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ]</font></b> (ع ص، اِ) ج ِ عَریض . (منتهی الارب ) (اقرب الموارد). رجوع به عریض شود.<br></font></div>'),
(182367, 'عرضدار', '<span class=\"hlight\">عرضدار.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (نف مرکب ) عریض . پهنادار. فراخ . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) سان لشکر. <BR><font color=\"Blue\">◄</font> عارضه و هر چیز اتفاقی و ناگهانی، مانند بیماری . (ناظم الاطباء).<br></font></div>'),
(182368, 'عرضداشت', '<span class=\"hlight\">عرضداشت .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِ مرکب ) در هندوستان پادشاه زادگان و امرا به جناب عالی، و خردان به خدمت بزرگان نویسند، بمعنی «عرض داشتن » است مثل بازخواست به معنی بازخواستن . و مضاف میباشد به طرف شخص عرض دارنده، یعنی آنچه پیشتر مذکور خواهد شد معروض داشتن فلانی است . و بنابراین اگر مصدر، به معنی مفعول اراده کرده شود نیز موجه می گردد. (از آنندراج ). خطابی که شاهزادگان و امرا به پادشاه نویسند. عریضه . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>به عرضداشت نوشتم که خون بنده بریز<br>خطش نمود به قتل لبش ستاند نفس .<br><font color=\"Red\">خواجه کمال خجند (از آنندراج ).</font><br></font></div>'),
(182369, 'عرضنات', '<span class=\"hlight\">عرضنات .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (ع ص، اِ) ج ِ عِرَضنة. (ناظم الاطباء). رجوع به عرضنة شود.<br></font></div>'),
(182370, 'عرضنة', '<span class=\"hlight\">عرضنة.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ن َ ]</font></b> (ع ص ) ناقة. عرضنة؛ شتر ماده یک رویه رونده به نشاط. (منتهی الارب ). ناقه ای که عادت دارد با نشاط راه رود. (از اقرب الموارد). ج، عرضنات . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِمص ) هو یمشی العرضنة؛ یعنی از نشاط سرکشی میکند در رفتار. (منتهی الارب ). راه رفتن او آنچنان است که در آن نوعی سرکشی، از چابکی وجوددارد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نظرالیه عرضنة؛ أی بمؤخر عینه . (منتهی الارب ) (اقرب الموارد)، یعنی بگوشه ٔ چشم نگریست به سوی او. (ناظم الاطباء).<br></font></div>'),
(182371, 'عرضنی', '<span class=\"hlight\">عرضنی .</span> <font color=\"DarkGreen\"><b>[ ع َرَ نا ]</font></b> (ع اِمص ) سرکشی . و گویند هو یمشی العرضنی ؛ یعنی در رفتار آن سرکشی و اعتراض است از نشاط. (منتهی الارب ) (آنندراج ). سرکشی در راه رفتن از چابکی . (ازاقرب الموارد). <BR><font color=\"Blue\">◄</font> نظر الیه عرضنی ؛ یعنی نگریست بدنبال چشم . (منتهی الارب ). و در تصغیر آن عُرَیِضن گویند با اثبات نون چون ملحق است، و به حذف یاء چون غیرملحق است . (از منتهی الارب ) (از آنندراج ).<br></font></div>'),
(182372, 'عرضه دادن', '<span class=\"hlight\">عرضه دادن .</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ض ِ دَ ]</font></b> (مص مرکب ) به معرض گذاشتن . ارائه دادن . عرض کردن . عرضه کردن <span class=\"hlight\">:</span> <br>گنجها بر دل خاقانی اگر عرضه دهند<br>نه فلک ده یک آن چیز بود کو بدهد.<br> <font color=\"Red\">خاقانی .</font><br>هر روز مهر پیلبانان جمله پیلان بر وی عرضه دادی . (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٥٦</span>).<br>خلق جزای هر عمل بر در کبریای تو<br>عرضه همی دهند و ما قصه ٔ بی وفائیت .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(182373, 'عرضه داشت', '<span class=\"hlight\">عرضه داشت .</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ض ِ ]</font></b> (اِ مرکب ) تظلم و دادخواست از روی عجز و فروتنی . (ناظم الاطباء) <span class=\"hlight\">:</span> چون بدانجا رسید عرضه داشتی ارسال نمود. (حبیب السیر چ طهران ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٩</span>).<br></font></div>'),
(182374, 'عرضه داشتن', '<span class=\"hlight\">عرضه داشتن .</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ض ِ ت َ ]</font></b> (مص مرکب ) اظهار کردن و بیان کردن، از طرف کوچکتر به بزرگتر. (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> صورت حال عرضه داشت . (مجالس سعدی ).<br>حسب حالم سخنی بس خوش و موجز یاد است <br>عرضه دارم اگرم رخصت اطناب دهی .<br><font color=\"Red\">ابن یمین .</font><br>آن قصه غلبه ٔ گرگ را عرضه داشتم . (انیس الطالبین ص <span class=\"hlight\" dir=\"rtl\">١٥٤</span>). <BR><font color=\"Blue\">◄</font> ارائه دادن . نشان دادن . (فرهنگ فارسی معین ). عرض .(از منتهی الارب ) (آنندراج ). عرض کردن . عرضه کردن . به معرض درآوردن . از مدنظر کسی گذراندن . فرا پیش کسی داشتن <span class=\"hlight\">:</span> گفت ... مواضعه نویسم تا فردا بر رای عالی زاده اﷲ علوا عرضه دارند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٤٧</span>). خدمتگاری را که انیس انس و عیبه ٔ اسرار زن تواند بود تهدید و تشدیدی عرضه داشت . (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">١٠٠</span>).<br>که دارد در همه آفاق زهره <br>که عرضه دارد این نقد نبهره .<br> <font color=\"Red\">شیخ عطار (از آنندراج ).</font><br>ای سهی سرو روان آخر نگاهی باز کن <br>تا به خدمت عرضه دارم افتقار خویش را.<br><font color=\"Red\">سعدی (خواتیم ).</font><br></font></div>'),
(182375, 'عرضه داشتن', '<span class=\"hlight\">عرضه داشتن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ض ِ ت َ ]</font></b> (مص مرکب ) لیاقت داشتن و سزاوار بودن . (ناظم الاطباء). لیاقت داشتن . قابلیت داشتن . (فرهنگ فارسی معین ).<br></font></div>'),
(182376, 'عرضه زار', '<span class=\"hlight\">عرضه زار.</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ض ِ ]</font></b> (اِ مرکب ) جایگاه عرضه . محل جلوه دادن . تجلیگاه . جلوه گاه <span class=\"hlight\">:</span> <br>ز هر گونه نو جانور صد هزار<br>کند عرض <font color=\"DarkGreen\"><b>[ زمین ]</font></b> هزمان در این عرضه زار.<br><font color=\"Red\">اسدی .</font><br></font></div>'),
(182377, 'عرضه ساختن', '<span class=\"hlight\">عرضه ساختن .</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ض ِ ت َ ]</font></b> (مص مرکب ) نشان دادن . ارائه دادن . عرضه کردن . عرضه دادن <span class=\"hlight\">:</span> <br>چون بیابد برده ای را خواجه ای <br>عرضه سازد از هنر دیباچه ای .<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(182378, 'عرضه کردن', '<span class=\"hlight\">عرضه کردن .</span> <font color=\"DarkGreen\"><b>[ع َ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ض ِ ک َ دَ ]</font></b> (مص مرکب ) ارائه دادن . نشان دادن . نمودن . در معرض نظر قرار دادن . (از فرهنگ فارسی معین ). عرض کردن . پیش داشتن . پیش نهادن . پیشنهاد کردن . فراپیش داشتن . به معرض درآوردن . عَرض <span class=\"hlight\">:</span> <br>کی بر او زر و سیم عرضه کنم <br>خویشتن را به گفت راد کنم .<br> <font color=\"Red\">حکاک (از فرهنگ اسدی ص <span class=\"hlight\" dir=\"rtl\">٢٤٧</span>).</font><br>مشافهه ای دیگر است با وی <font color=\"DarkGreen\"><b>[ ابوالقاسم ]</font></b> در بابی مهمتر که اگر اندر آن باب سخن نرود عرضه نکند و پس اگر رود ناچار عرضه کند تا اغراض بحاصل شود. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٠٩</span>). نام این قوم بباید نبشت و بر اعیان عرضه کرد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٧٣</span>). نخست آن به رشید عرضه کردند سخت شاد شد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٢٤</span>).<br>نار چو بیمار توئی خود بخور<br>عرضه مکن بر دگران نار خویش .<br> <font color=\"Red\">ناصرخسرو.</font><br>چون به صادق حاکمی حاجت نیاید خلق را<br>مدعی را عرضه کردن گاه حاجت چیست پس .<br> <font color=\"Red\">ناصرخسرو.</font><br>ترادیبای عنبر بوی گلرنگ است در خاطر<br>همی کن عرضه بر دانای عطاری و بزازی .<br> <font color=\"Red\">ناصرخسرو.</font><br>بهشتم همی عرضه کرد و مرا<br>حقیقت که دوزخ جزآن چه نبود.<br> <font color=\"Red\">مسعودسعد.</font><br>فخرالدوله آن رقعه را بر شمس المعالی عرضه کرد قابوس وشمگیر زیر آن نبشت . (نوروزنامه ). اگر به همه نوع خویشتن را بر او عرضه نکنیم ... به کفران نعمت منسوب شویم . (کلیله و دمنه ).<br>دردِ دل بر که کنم عرضه که درمان دلم <br>کیمیائی است کز او هیچ اثر کس را نی .<br> <font color=\"Red\">خاقانی (دیوان چ سجادی ص <span class=\"hlight\" dir=\"rtl\">٨٠٦</span>).</font><br>شب خلوت که موجودات بر وی عرضه میکردند.<br>جهان چون ذره ای در دیده ٔ بینای او آمد.<br> <font color=\"Red\">خاقانی .</font><br>مصری کلکت چو سحر عرضه کند گاه وجود<br>مصر و عزیزش بود بر دل و بر چشم خوار.<br> <font color=\"Red\">خاقانی .</font><br>چو قاصد عرضه کرد آن نامه ٔ نو<br>بجوشید از سیاست خون خسرو.<br> <font color=\"Red\">نظامی .</font><br>در این تقاضا ده قطعه بیش نظم افتد<br>که عرضه کردن هر یک از آن بود ناچار.<br> <font color=\"Red\">کمال الدین اسماعیل (دیوان ص <span class=\"hlight\" dir=\"rtl\">٣٩٢</span>).</font><br>هر ساعت از نو قبله ای با بت پرستی میرود<br>توحید بر ما عرضه کن تا بشکنیم اصنام را.<br> <font color=\"Red\">سعدی .</font><br>هر که بی موجبش خراب کند<br>خویش را عرضه ٔ عذاب کند.<br> <font color=\"Red\">اوحدی .</font><br>مروت گرچه نامی بی نشان است <br>نیازی عرضه کن بر نازنینی .<br> <font color=\"Red\">حافظ.</font><br>استعراض ؛ عرضه کردن خواستن . (تاج المصادر بیهقی ).<br></font></div>'),
(182379, 'عرضه گاه', '<span class=\"hlight\">عرضه گاه .</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ض ِ ]</font></b> (اِ مرکب ) معرض .نمایشگاه . عرضگاه . رجوع به عرضگاه شود <span class=\"hlight\">:</span> <br>خدائی که هست آفرینش پناه <br>چو بیند نیازی در این عرضه گاه .<br> <font color=\"Red\">نظامی .</font><br><BR><font color=\"Blue\">◄</font> عرضگاه و فراهم آمدنگاه دشمن . (ناظم الاطباء). رجوع به عرضگاه شود.<br></font></div>'),
(182380, 'عرضگاه', '<span class=\"hlight\">عرضگاه .</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ رَ ]</font></b> (اِ مرکب ) جای عرض دادن چیزی . (آنندراج ). جای عرض و نمایش چیزی . محل عرضه . (فرهنگ فارسی معین ). معرض . نمایشگاه . عرضه گاه . عرضگه . رجوع به عرضگه و عرضه گاه شود. <BR><font color=\"Blue\">◄</font> میدان شمار کردن سپاه . (غیاث اللغات ) (آنندراج ) (فرهنگ فارسی معین ). فراهم آمدنگاه دشمن . (ناظم الاطباء). میدان سان . جای سان دادن سپاه . عرضگه . عرضه گاه . لشکرگاه . رجوع به عرضگه و عرضه گاه شود <span class=\"hlight\">:</span> روز چهارم بابک به عرضگاه بنشست و سپاه گرد آمد. (ترجمه ٔ طبری بلعمی ).<br>سپه گرد کرد اندران، رشنواد<br>عرضگاه بنهاد و روزی بداد.<br> <font color=\"Red\">فردوسی .</font><br>عرضگاه و دیوان بیاراستند<br>کلید در گنجها خواستند.<br> <font color=\"Red\">فردوسی .</font><br>سپهبد بشد تا عرضگاه شاه <br>بفرمود تا پیش او شد سپاه .<br> <font color=\"Red\">فردوسی .</font><br>به عرضگاه تو لشکر چنانکه پار نبود<br>هزار و هفتصد و اند پیل بد به شمار.<br> <font color=\"Red\">فرخی .</font><br>گفت این فراخ و پهنا دشت گشاده چیست <br>گفتم که عرضگاه بشد بی عدد سپاه .<br> <font color=\"Red\">فرخی .</font><br>لشکرگه سفاهت من عرض داد دیو<br>من ایستاده همره عارض به عرضگاه .<br> <font color=\"Red\">سوزنی .</font><br>عرضگاه دشت موقف عرض جنات است از آنک <br>مصنع او کوثر و سقاش رضوان دیده اند.<br> <font color=\"Red\">خاقانی .</font><br>فردا که عرضگاه محشر و هول و فزع اکبر باشد. این اهمال و امهال را چه حجت آرد. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٢١٧</span>).<br>ز بس غارت آوردن از بهر شاه <br>غنیمت نگنجیددر عرضگاه .<br> <font color=\"Red\">نظامی .</font><br>شها منم که بلا را بجز فضای دلم <br>بگاه عرض سپه نیست عرضگاه سپاه .<br><font color=\"Red\">عرفی (از آنندراج ).</font><br></font></div>'),
(182381, 'عرضگه', '<span class=\"hlight\">عرضگه .</span> <font color=\"DarkGreen\"><b>[ ع َ گ َه ْ ]</font></b> (اِ مرکب ) مخفف عرضگاه . جای عرضه داشتن و نمایش دادن چیزی . رجوع به عرضگاه و عرضه گاه شود. <BR><font color=\"Blue\">◄</font> میدان شمار کردن سپاه و سان . عرضه گاه .عرضگاه . رجوع به عرضگاه و عرضه گاه شود <span class=\"hlight\">:</span> <br>گفتا که پیش عرضگه استاده است او<br>گفتم به پیش گاه بود جای پیشگاه .<br> <font color=\"Red\">فرخی .</font><br>در عرضگه عشقش فتنه سپه انگیزد<br>در رزمگه حسنش گردون سپر اندازد.<br> <font color=\"Red\">خاقانی .</font><br>و عرضگه و شمار لشکر را وضعی ساخته اند که دفترعرض را بدان منسوخ کرده اند، و اصحاب و نواب آنرا معزول . (جهانگشای جوینی ).<br></font></div>'),
(182382, 'عرضی', '<span class=\"hlight\">عرضی .</span> <font color=\"DarkGreen\"><b>[ ع َ ضا ]</font></b> (ع اِ) نوعی از جامه . (منتهی الارب ). یکی نوع جامه . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بعضی مرافق سرای و خانه . (لغت عراقی است ). (منتهی الارب ). آن چیز که در خانه موجب آسایش باشد مانند آبریز. (ناظم الاطباء).<br></font></div>'),
(182383, 'عرضی', '<span class=\"hlight\">عرضی .</span> <font color=\"DarkGreen\"><b>[ ع َ ضی ی ]</font></b> (ص نسبی ) منسوب به عَرض .افقی . مقابل طولی . رجوع به عرض شود. <BR><font color=\"Blue\">◄</font> عرضه داشت و تذکار و اظهار عاجزانه . (ناظم الاطباء).<br></font></div>'),
(182384, 'عرضی', '<span class=\"hlight\">عرضی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ضی ی ]</font></b> (ص نسبی ) منسوب به عَرَض .رجوع به عَرَض شود. <BR><font color=\"Blue\">◄</font> در اصطلاح منطق، عارضی . مقابل جوهری . مقابل ذاتی . مقابل غریزی . مقابل طبیعی . کلی یا ذاتی بود یا عرضی، نه بر اطلاق، بل به اضافت با موضوعی که فرض کنند، و ممکن باشد که یک کلی به اضافت با موضوعی ذاتی بود و به واضافت با موضوعی دیگر عرضی، مانند ضاحک که به اضافت با انسان عرضی است و به اضافت به این ضاحک ذاتی . (از فرهنگ فارسی معین از اساس الاقتباس ص <span class=\"hlight\" dir=\"rtl\">٢١</span>). عرضی اخص از عرض است، زیرا بیاض مثلاً عرض است و حال آنکه عرضی نیست . و ابیض عرض و عرضی است چنانکه شیخ الرئیس گوید. عرض مقابل جوهر است و غیر از عرضی است که مقابل ذاتی است . وجود اعراض غیر از موضوعات است و متأخر از آنها است . و عرضیت از صفات عقلیه است . (فرهنگ علوم عقلی، به نقل از دستورالعلماء و مجموعه ٔ دوم مصنفات باباافضل ): و فیه رطوبة عرضیة <font color=\"DarkGreen\"><b>[ فی الحماض ]</font></b> . (مفردات ابن البیطار).<br>- <span class=\"hlight\">مقولات عرضی </span> ؛ نه مقوله اند در عرض . رجوع به عَرَض شود.<br></font></div>'),
(182385, 'عرضی', '<span class=\"hlight\">عرضی .</span> <font color=\"DarkGreen\"><b>[ ع ِ رِض ْ ضا ]</font></b> (ع اِمص ) شادمانی . (منتهی الارب ).نوعی راه رفتن با میل و عدول . (از اقرب الموارد).<br></font></div>'),
(182386, 'عرضی', '<span class=\"hlight\">عرضی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ضی ی ]</font></b> (ع ص نسبی ) آنکه بر زین نشستن و ثبات نتواند. (منتهی الارب ). کسی که بر روی زین سست نشسته باشد. (ناظم الاطباء). کسی که بر زین، محکم ننشیند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتر که در رفتار سرکشی کند، بدان جهت که ریاضتش کامل نشده . گویند بعیر عرضی، یعنی صعب و سخت . (از منتهی الارب ). سرکش و گردنکش . (ناظم الاطباء). شتر که در راه رفتن خود خم شود، بدان جهت که تربیتش هنوز کامل نشده است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتری که به یک طرف تکیه کرده باشد بواسطه ٔ شکستگی . (ناظم الاطباء).<br></font></div>'),
(182387, 'عرضی', '<span class=\"hlight\">عرضی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ص نسبی ) نسبت است به عرض، که آن شهر کوچکی است در صحرا بین فرات و دمشق، از اعمال حلب . و چند تن از دانشمندان بدانجا منسوبند که از آن جمله است ابوالحارث عبدالوهاب بن ضحاک عرضی . (از اللباب فی تهذیب الانساب ). و رجوع به معجم البلدان شود.<br></font></div>'),
(182388, 'عرضی', '<span class=\"hlight\">عرضی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) عمربن عبدالواهاب بن ابراهیم عرضی شافعی قادری . مفتی و محدث و فقیه عصر خویش در حلب وی به سال <span class=\"hlight\" dir=\"rtl\">٩٥٠</span> هَ . ق . متولد شد. و سمت افتاء شافعی ها را به عهده داشت . کتابهای چندی تألیف کرد که از آن جمله است : فتح الغفار بما أکرم اﷲ به نبیةالمختار، که شرح کتاب شفا است، شرح رساله ٔ قشیری، تاریخ . عرضی به سال <span class=\"hlight\" dir=\"rtl\">١٠٢٤</span> ق . در حلب درگذشت . (از اعلام زرکلی از خلاصةالاثر و سلک الدرر).<br></font></div>'),
(182389, 'عرضی', '<span class=\"hlight\">عرضی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) محمدبن عمربن عبدالوهاب حلبی عرضی، مکنی به ابوالوفاء. مفتی شافعی ها در حلب . وی به سال <span class=\"hlight\" dir=\"rtl\">٩٩٣</span> هَ . ق . در این شهر متولد شد. و علاوه بر افتاء، در علم تاریخ و در نظم شعر نیز دست داشت . او راست : معادن الذهب فی الاعیان المشرفة بهم حلب، طریق الهدی، فتح المانح البدیع. عرضی به سال <span class=\"hlight\" dir=\"rtl\">١٠٧١</span> هَ . ق . در حلب درگذشت . (از الاعلام زرکلی از خلاصة الاثر).<br></font></div>'),
(182390, 'عرضیة', '<span class=\"hlight\">عرضیة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ضی ی َ ]</font></b> (ع ص نسبی ) ناقة عرضیة؛ أی صعبة. (منتهی الارب ). ماده شتر که در او سختی و صعوبت باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) فیه عرضیة؛ یعنی در او بی باکی و سختی و سرکشی است . (منتهی الارب ). نخوت و صعوبت و قلت مبالات . (ناظم الاطباء). یعنی در او بی مبالاتی و تکبر و سختگیری است . (از اقرب الموارد).<br></font></div>'),
(182391, 'عرط', '<span class=\"hlight\">عرط.</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ]</font></b> (ع ص، اِ) ج ِ عَروط. رجوع به عَروط شود.<br></font></div>'),
(182392, 'عرط', '<span class=\"hlight\">عرط.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) خوردن ناقه درخت را چندانکه ریخته شود دندان او.(از منتهی الارب ). عرطت الناقة الشجر؛ آن ماده شتر درخت را خورد تا آنکه دندان او از بین رفت . و چنین ناقه ای را عَروط نامند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> معیوب کردن آبروی کسی از غیبت . (از منتهی الارب ). غیبت کردن از عرض و آبروی کسی . (از اقرب الموارد).<br></font></div>'),
(182393, 'عرطب', '<span class=\"hlight\">عرطب .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) حَسَک است که به هندوی کوکهرو نامند. (از تحفه ٔ حکیم مؤمن ) (از مخزن الادویه ). رجوع به حسک شود.<br></font></div>'),
(182394, 'عرطبة', '<span class=\"hlight\">عرطبة.</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ طُ ب َ ]</font></b> (ع اِ) رود یا طنبور یا طبل یا طبل حبشی . (منتهی الارب ) عود، که از ملاهی است . و گویند طنبور. و گویند طبل . و گویند طبل حبشه . (از اقرب الموارد). کوبه . طبلک . (السامی ). و آنرا معرب از فارسی دانند. (از المعرب جوالیقی ).<br></font></div>'),
(182395, 'عرطسة', '<span class=\"hlight\">عرطسة.</span> <font color=\"DarkGreen\"><b>[ ع َ طَ س َ ]</font></b> (ع مص ) یک سو شدن و کناره گزیدن از قوم . (منتهی الارب ). دور شدن از قوم . (از اقرب الموارد). عَطرزة. و رجوع به عطرزة شود. <BR><font color=\"Blue\">◄</font> ذلیل و نرم گردیدن از جنگ و منازعت قوم . (از منتهی الارب ). خوار گشتن از ستیزه و نزاع با قوم . (از اقرب الموارد) .<br></font></div>'),
(182396, 'عرطل', '<span class=\"hlight\">عرطل .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (ع ص ) دفزک . ضخم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نیک دراز. (منتهی الارب ). آنکه در طول فاحش و افزون باشد. (از اقرب الموارد). عَرطَلیل . و رجوع به عرطلیل شود.<br></font></div>'),
(182397, 'عرطلیل', '<span class=\"hlight\">عرطلیل .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (ع ص ) دفزک . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نیک دراز. (منتهی الارب ). عَرطل . و رجوع به عرطل شود.<br></font></div>'),
(182398, 'عرطنیثا', '<span class=\"hlight\">عرطنیثا.</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (ع اِ) بیخ درخت بخور مریم . (منتهی الارب ). اصل و ریشه ٔ درخت بخور مریم . (از اقرب الموارد). بیخی است که آنرا به شیرازی چوبک اشنان خوانند. از آب آن دو قطره در بینی چکانند درد دندان را سود دارد. و صاحب مؤید الفضلاء گوید خربزه ٔ سرخ که میان او سفید باشد. (برهان قاطع). در بعضی جایگاه عرطنیثا را گلیم شوی میگویند و بعضی جایگاه قلادر گویند. و بعضی بخور مریم گویند. (ازذخیره ٔ خوارزمشاهی ). ریشه ٔ بخور مریم . (بحر الجواهر). اسم سریانی آذربو است . (تحفه ٔ حکیم مؤمن ). آذربواست که به فارسی چوبک نامند. (مخزن الادویه ). مزاج را گرم کند و خشک گرداند و او در سه درجه گرم است و بیشتر بیخ او را استعمال کنند. و به لغت یونانی او راتیموس گویند. (از تذکره ٔ ضریر انطاکی ). معرب «ارتنیتا»ی آرامی است و آن بخور مریم و گل نگونسار است . (از فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> فیلگوش، که گیاهی است . (از فرهنگ فارسی معین ). رجوع به فیلگوش شود.<br></font></div>'),
(182399, 'عرطوج', '<span class=\"hlight\">عرطوج .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) نام پادشاهی . (منتهی الارب ) (ناظم الاطباء). ملکی است از ملوک . (از تاج العروس ).<br></font></div>'),
(182400, 'عرطویل', '<span class=\"hlight\">عرطویل .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (ع ص ) نیکوجوانی خوش قد. (منتهی الارب ). نیکوئی جوانی و نیکوئی قد. (ناظم الاطباء). نیکو در جوانی و در قد. (ازاقرب الموارد). نیکوجوانی و نیکوقد. (شرح قاموس ).<br></font></div>'),
(182401, 'عرعار', '<span class=\"hlight\">عرعار.</span> <font color=\"DarkGreen\"><b>[ ع َرْ رِ ]</font></b> (ع اِ) بازیی است مر کودکان را. و مبنی بر کسر می باشد. و آن معدول از عَرعرة است چنانکه قرقار معدول از قرقرة میباشد. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> و نیز بدین لفظ کودکان آواز کنند تا دیگران بیرون آیند. (منتهی الارب ).<br></font></div>'),
(182402, 'عرعر', '<span class=\"hlight\">عرعر.</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (اِ صوت ) بانگ خر.صدای الاغ . (فرهنگ فارسی معین ). بانگ درازگوش . آواز خر. (فرهنگ لغات عامیانه ). اسم صوت خر. حکایت صوت خر. نقل صوت خر. نهیق . غان غان . <BR><font color=\"Blue\">◄</font> در فارسی به معنی مطلق آواز نیز هست . (آنندراج ) <span class=\"hlight\">:</span> <br>صوفی است خر و مرید صوفی خرخر<br>نبود عجب ار خری بود رهبر خر<br>از عرعر صوفی که بود عرعر خر<br>در رقص آیند صدهزاران سر خر.<br> <font color=\"Red\">میرمحمد زمان طاهری (از آنندراج ).</font><br>عرعر او زینت باغ جهان <br>مغز سرش ماحضر خواجگان .<br><font color=\"Red\">محمد قلی سلیم (از آنندراج ).</font><br></font></div>'),
(182403, 'عرعر', '<span class=\"hlight\">عرعر.</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (ع اِ) درخت سرو کوهی است . گویند میان آن درخت و نخل خرما عداوت است و یک جا نرویند. (برهان قاطع). درخت سرو پیوسته سبز، فارسی است . (منتهی الارب ). درختی است از قسم سرو، و این در اصل فارسی است . (آنندراج ). درختی است که قسمی از سرو باشد و آن سرو کوهی است . و به هندی آنرا چیر گویند که روغن چوب آن معروف است . (غیاث اللغات ). درخت سرو و آن فارسی است . یک دانه ٔ آن عرعرة است و گویند آن «ساسم » است . و برخی گویند درختی است که از آن قطران بعمل آید. (از اقرب الموارد). درختی است شبیه به صنوبر و در دشت روید و در عربه و وادی موسی یافت میشود. و بسا میشود که بز آنرا نمی چرد.(قاموس کتاب مقدس ). سرو. (دهار) (مهذب الاسماء). ناژ. سرو جبلی . (زمخشری ). آنرا سرو کوهی و قزاونه و اورس گویند. میوه اش مانند زعرور است بلکه سیاه تر بود. وبوی خوش دارد و آنرا ابهل خوانند. (نزهة القلوب ) نوعی پیرو که بنام سروکوهی نیز معروف است . و معمولاً دردهات ایران و نقاط جنگلی شمال در تداول عامه آنچه را که بنام عرعر مینامند اقسام مختلف سروکوهی و پیرو میباشد. که از تیره ٔ کوپرساسه  هستند. (از فرهنگ فارسی معین ). به تازی درخت سرو را گویند و به هندی هوه گویند. ارجانی گوید دانه ٔ او گرم و خشک است در سه درجه . و بول از مثانه و خون حیض از رحم براند. و معده را پاکیزه کند. و علتی را که آنرا اختناق الرحم گویند منفعت کند. (از تذکره ٔ ضریرانطاکی ). سرو کوهی است و او از سرو کوتاه تر و کوچکتر، و ثمرش بقدر فندقی و با اندک شیرینی، غیر ابهل است . گویند نگاه داشتن هشت عدد ثمر او در سر باعث قبول و عظمت در نظرها است . (از تحفه ٔ حکیم مؤمن ). در قدیم، سرو کوهی یعنی پیرو باشد، و آنرا در لاتین ژونی پروس  و در فرانسوی ژنوریه گویند. و عرعر که در شعرشاعران آمده است این درخت است نه بمعنی درخت عرعر امروزی . (از یادداشتهای مرحوم دهخدا) <span class=\"hlight\">:</span> و اندروی <font color=\"DarkGreen\"><b>[ شهر بوشنگ ]</font></b> درخت عرعر است . (حدود العالم ).<br>بزرگ بتکده ای پیش و در میانش بتی <br>به حسن ماه و لیکن به قامت عرعر.<br> <font color=\"Red\">فرخی .</font><br>ز عرعر تراشند منبرش ازیرا<br>نریزد ز باد خزان برگ عرعر.<br> <font color=\"Red\">عنصری .</font><br>تو گوئی به باغ اندر آنروز برف <br>صف ناژ بود و صف عرعران .<br> <font color=\"Red\">منوچهری .</font><br>خجسته خواجه سید در آن نیکو بهارستان <br>گرازان زیر سنبلها و نازان زیر عرعرها.<br> <font color=\"Red\">منوچهری .</font><br>چون فاخته ٔ دلبر، برتر پرد از عرعر<br>گویی که به زیر پر، بربسته یکی جلجل .<br> <font color=\"Red\">منوچهری .</font><br>و آنت گوید بر سر هفتم فلک <br>جوی آب و باغ ناژ و عرعر است .<br> <font color=\"Red\">ناصرخسرو.</font><br>اگر چیز از مراد خویش بودی <br>نگشتی خار بُن جز ناژ و عرعر.<br> <font color=\"Red\">ناصرخسرو (دیوان چ تقوی ص <span class=\"hlight\" dir=\"rtl\">١٨٢</span>).</font><br>جزیره ٔ خراسان چو بگرفت شیطان <br>در و خار بنشاند و برکند عرعر.<br><font color=\"Red\">ناصرخسرو.</font><br>تا عرعر از باد نوان است همی باد<br>حضرت به تو آراسته چون باغ به عرعر.<br> <font color=\"Red\">ناصرخسرو (دیوان چ تقوی ص <span class=\"hlight\" dir=\"rtl\">١٧٧</span>).</font><br>تا بتابد ز آسمان پروین <br>تا بروید به بوستان عرعر.<br> <font color=\"Red\">مسعودسعد.</font><br>رایات او چو دید نقیبت بهشت گفتا<br>زین راست تر به باغ بقا عرعری ندارم .<br> <font color=\"Red\">خاقانی .</font><br>کاریز برده کوثر در حوضهای ماهی <br>پیوند کرده طوبی با شاخهای عرعر.<br> <font color=\"Red\">خاقانی .</font><br>یاسمین رویی که سرو قامتش <br>طعنه بر بالای عرعر میزند.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">حب العرعر</span> ؛ ابهل است، و آن گرم و خشک در دوم است . (ازمنتهی الارب ). رجوع به ابهل شود.<br> <BR><font color=\"Blue\">◄</font> اقسام مختلف «پیرو» است که گیاهی باشد. (از فرهنگ فارسی معین ). رجوع به پیرو شود. <BR><font color=\"Blue\">◄</font> ابهل، که گیاهی باشد. (از فرهنگ فارسی معین ). رجوع به ابهل شود. <BR><font color=\"Blue\">◄</font> نامی است که امروز در باغهای تهران به غلط به الانتوس گلاندولوزا دهند. و آن بومی چین و ژاپن است و اخیراً به ایران آورده شده و در نقاط خشک انتشار یافته است . درختی است با برگهای دراز وگنده و بدبوی و چوبی سخت سست که بسرعت با پاجوشها که زند بسیار شود. و امروز مردم عرب ترجمه ٔ نامهای فرهنگی آنرا بر آن نهاده اند، از قبیل شجرةاﷲ و شجرةالسماء. (از یادداشتهای مرحوم دهخدا). درختی است از تیره ٔ عرعرها، که دارای برگهای مرکب و برگچه های بسیار است . اصل این گیاه از چین و ژاپن است و بتازگی به ایران آورده شده و در باغها و پارکها و کنار خیابانها کاشته میشود. ارتفاع این درخت تا بیست متر نیز میرسد. انساج این گیاه دارای ترشح صمغی میباشد که بسیار متعفن و بدبو است . در لمس، بوی آن استشمام میشود. رویهمرفته درخت عرعر درختی است زیبا و تنومند که در هر شرایطی حتی مناطق معتدله ٔ سرد نیز تکثیر و انتشار مییابد. ازدیاد این درخت به طور طبیعی و به سهولت توسط اعضای زیرزمینی آن صورت میگیرد به طوری که غالباً به علت سرعت ازدیاد و انتشار، مانع بزرگی برای درخت کاری در باغها میگردد. برگهایش بزرگ به درازی شصت تا هفتاد سانتیمتر و مرکب از پانزده تا بیست زوج برگچه میباشد، به اضافه ٔ یک برگچه ٔ انتهایی . گلهایش در برخی انواع نرماده، ولی گیاه دو پایه است، به طوری که گلهای نر فقط شامل ده پرچم در دو ردیف و مادگی تحلیل یافته ای است . و گل ماده دارای چند پرچم عقیم و مادگیش مرکب از پنج برچه است . میوه اش خشک و ناشکوفا و بالدار است . پوست درخت عرعر دارای اثر ضدکرم تنیا است . توضیح اینکه در برخی کتب عرعر را جزو تیره ٔ سماقیان ذکر کرده اند و این خطاست . و شاید این اشتباه از اینجا ناشی شده که عرعر را مرادف با <span class=\"hlight\" dir=\"rtl\">Vermix</span> <span class=\"hlight\" dir=\"rtl\">Rhus</span> تصور کرده اند و این گیاه از تیره ٔسماقیان است . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> در تونس این نام را به سندروس اطلاق کنند. (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">تیره ٔ عرعرها</span> ؛ تیره ای از گیاهان دو لپه یی جدا گلبرگ که اکثر به صورت درختان تنومند و عظیمند. برگهای گیاهان این تیره معمولاً منفرد و غالباً مرکب است و شامل برگچه های منقسم و یا تغییر شکل یافته به صورت خار میباشند. گلهای این تیره منفرد و کوچک ونر ماده و دو پایه و یا یک پایه است . میوه ٔ آنها ناشکوفا و غالباً به صورت شفت و دارای دانه ٔ آلبومن داراست . (فرهنگ فارسی معین ). نمونه ٔ این تیره درخت الانتوس گلاندولوزا میباشد که امروزه به نام عرعر در باغها کاشته میشود.<br></font></div>'),
(182404, 'عرعر', '<span class=\"hlight\">عرعر.</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (اِخ ) موضعی است . (منتهی الارب ). نام جایگاهی است در شعر اخطل . و گویند آن کوهی است . و گمان میرود که یک وادی باشد و برخی گفته اند که آن موضعی است از نعمان در بلاد هذیل . (از معجم البلدان ).<br></font></div>'),
(182405, 'عرعر', '<span class=\"hlight\">عرعر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ع ُ ]</font></b> (ع اِ) مابین دوسوراخ بینی . (منتهی الارب ) . <BR><font color=\"Blue\">◄</font> زهار، و بن آن . (منتهی الارب ). مابین زهار و بن آن . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> خوی زشت وناپسند. (از اقرب الموارد). گویند رکب عرعره ؛ یعنی زشت گردید خوی او. (از منتهی الارب ) (از اقرب الموارد). کما اینکه گویند رکب رأسه . (از اقرب الموارد).<br></font></div>'),
(182406, 'عرعر بری', '<span class=\"hlight\">عرعر بری .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ رِ ب َرْ ری ی ]</font></b> (ترکیب وصفی، اِ مرکب ) قسم کوچک شربین است . (تحفه ٔ حکیم مؤمن ).<br></font></div>'),
(182407, 'عرعر تلخ', '<span class=\"hlight\">عرعر تلخ .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ رِ ت َ ]</font></b> (ترکیب وصفی، اِ مرکب ) درختی است از تیره ٔ عرعرها به ارتفاع بیست تا بیست و پنج متر که پوست تنه اش مایل به خاکستری و چوبش سبک ومایل به سفید و کم مقاومت است . برگهایش متناوب و شامل سه تا ده زوج برگچه ٔ بی کرک و شفاف و گلهایش کوچک و یک پایه و مایل به سفید و شامل پنج کاسبرگ پیوسته و نامساوی و پنج گلبرگ بزرگتر از کاسبرگ است . گل نر آن دارای ده پرچم ولی گل ماده منحصراً دارای چند پرچم سترون و مادگی است . میوه اش مرکب از پنج کپسول بیضوی و دارای پوستی نازک و شکننده است . و در درون هر یک از آنها نیز یک دانه دیده میشود. این گیاه در اراضی شنی و مرطوب نواحی گویان و برزیل روییده میشود. در ریشه ٔ این گیاه موادی به نام سیماروبین  و سیماروبئین  وجود دارد. پوست ریشه اش از مقویات تلخ بشمار میرود. و بعلاوه بعنوان قابض و برای رفع ذوسنطاریا و تنظیم کننده ٔ انقباضات ماهیچه های صاف دستگاه گوارش و نیز بعنوان ضدتب به کار میرود. (از فرهنگ فارسی معین ).<br></font></div>'),
(182408, 'عرعر کردن', '<span class=\"hlight\">عرعر کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ک َ دَ ]</font></b> (مص مرکب ) آواز برآوردن خر. بانگ کردن درازگوش . <BR><font color=\"Blue\">◄</font> آواز خر دادن . ادا کردن صوت خر را. نهیق . غان غان . رجوع به عرعر شود. <BR><font color=\"Blue\">◄</font> کنایه است از بدآواز خواندن . (فرهنگ لغات عامیانه ).<br></font></div>'),
(182409, 'عرعرو', '<span class=\"hlight\">عرعرو.</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (ص نسبی ) متصف به صفت عرعر کردن، یعنی ناهنجار و بی هنگام بانگ ناموزون برآوردن . <BR><font color=\"Blue\">◄</font> مجازاً، بچه ٔ نحس و بداخلاق و زرزری . (فرهنگ لغات عامیانه ).<br></font></div>'),
(182410, 'عرعری', '<span class=\"hlight\">عرعری .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (ص نسبی ) منسوب به عرعر. مانند عرعر. بسان درخت عرعر.<br>- <span class=\"hlight\">قامت عرعری </span> ؛ قامت آخته و راست <span class=\"hlight\">:</span> <br>ترا ره نمایم که چنبر که را کن <br>به سجده مر این قامت عرعری را.<br> <font color=\"Red\">ناصرخسرو (دیوان چ تقوی ص <span class=\"hlight\" dir=\"rtl\">١٤</span>).</font><br> <BR><font color=\"Blue\">◄</font> بچه ٔ نحس و بداخلاق . عرعرو. (از فرهنگ لغات عامیانه ). رجوع به عرعرو شود.<br>- <span class=\"hlight\">عرعری کردن </span> ؛ خاصیت و جلوه ٔ درخت عرعر داشتن .<br>بید ار چه سبز و نغز و لطیف است در بهار<br>کی در چمن به جلوه کند بید عرعری .<br><font color=\"Red\">مجد همگر.</font><br></font></div>'),
(182411, 'عرف', '<span class=\"hlight\">عرف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) بریدن یال اسب را. (منتهی الارب ). پش اسب بریدن . (المصادر زوزنی ). فش اسب بریدن . (دهار). «عرف » اسب را بریدن . واز آن جمله است که گویند «هو یعرف الخیل ». (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> صبر گزیدن . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> اقرار به گناه کردن و پذیرفتن . (از منتهی الارب ). عِرفان . رجوع به عرفان شود. <BR><font color=\"Blue\">◄</font> پاداش دادن کسی را. و از آن جمله است که گویند «أنا أعرف للمحسن و المسی ٔ»؛ یعنی عمل شخص نیکوکار و زشت کار، و آنچه را موافق آن در مقابل عملش باید کرد، بر من مخفی نباشد. (از منتهی الارب ). و کسائی «عرف بعضه ...» را بتخفیف خوانده است یعنی پاداش داد حفصة رضی اﷲ عنها را نسبت به قسمتی از آنچه انجام داده است، و یا به این معنی است که به قسمتی از آن اقرار کرد و از قسمتی دیگر اعراض کرد. (از منتهی الارب ). عِرفان . رجوع به عرفان شود. <BR><font color=\"Blue\">◄</font> ریش برآوردن کف دست . (فعل آن به صیغه ٔ مجهول به کار رود). (از منتهی الارب ). «عرفة» یعنی قرحه و زخم در شخص پدیدار شدن، و چنین شخص را «معروف » گویند. (از اقرب الموارد).<br></font></div>'),
(182412, 'عرف', '<span class=\"hlight\">عرف .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ]</font></b> (ع اِ) ریگ توده ٔ بلند. و جای بلند. (منتهی الارب ). رمل، و مکان مرتفع. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> فش اسب . (منتهی الارب ). موی گردن اسب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تاج خروس . (منتهی الارب ) (ناظم الاطباء). عُرف . رجوع به عُرف شود.<br></font></div>'),
(182413, 'عرف', '<span class=\"hlight\">عرف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) بوی خوش و ناخوش، و بیشتر در مورد بوی خوش بکار رود. (منتهی الارب ) (از اقرب الموارد). بوی خوش و ناخوش . (دهار). بوی خوش . (غیاث اللغات ). گویند ما أطیب عرفه . (از منتهی الارب ) (از اقرب الموارد). یعنی بوی او چه نیکو است . <BR><font color=\"Blue\">◄</font> در مثل گویند «لایعجز مسک السوء عن عرف السوء» یعنی پوست و چرم پلید و بد، خالی از بو نیست . آن را در حق کسی گویند که از فعل شنیع خود بازنایستد. گوئی وی را به چرمی تشبیه کرده اندکه قابل دباغت نباشد. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گیاهی است، یا یزبن، یا گیاهی است که از جنس حمض  و عضاه نیست . (منتهی الارب ). نباتی است، و گویند آن همان ثمام ویز است . و برخی گویند آن نباتی است غیر از حمض و عضاه . (از اقرب الموارد). قسب است . (مخزن الادویه ).<br></font></div>'),
(182414, 'عرف', '<span class=\"hlight\">عرف .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع مص ) بسیار کردن بوی خوش را. (از منتهی الارب ). بسیار کردن طیب را. (از اقرب الموارد).<br></font></div>'),
(182415, 'عرف', '<span class=\"hlight\">عرف .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِمص ) به درنگ شناختن . دیری در شناختگی . (منتهی الارب ). گویند ما عرف عرفی اًلا بأخرة؛ یعنی مرا نشناخت مگر اخیراً. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شکیبائی . (منتهی الارب ). صبر. (اقرب الموارد) (دهار).<br></font></div>'),
(182416, 'عرف', '<span class=\"hlight\">عرف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) شناخته . (منتهی الارب ). معروف . (اقرب الموارد). معروف و مشهور و شناخته . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آنچه که در میان مردم معمول و متداول است . در مقابل شرع . (فرهنگ فارسی معین ). آنچه بشناسند در شریعت و روا باشد کردن آن . (دهار). آنچه از نظر شهادت عقول در نفس ها جایگزین شود، و طبعهای سالم آنرا مورد قبول قرار دهند. و آن نیز حجت باشد ولی برای فهم و «عادت » چیزی است که مردم هنگام حکم عقل، بر آن استمرار کنند و پی در پی به سوی آن بازگردند، و از اینجاست قول فقهاء که «العادة محکمة و العرف قاض ». (از اقرب الموارد) (از تعریفات جرجانی ). عادت است، و آن شامل عرف عام و عرف خاص است . و معمولاً عرف عام را «عرف » گویند. (از کشاف اصطلاحات الفنون ). قاعده ٔ حقوقی است که مولود تکرار عمل جمعیتی است و قانونگذار در تعبیرات قانونی خود ذکر خاص از آن نکرده ولی آنرا به نحوی از انحاء مورد حمایت خود (یعنی مشمول ضمانت اجراء) قرار داده است . عرف به حسب آنکه در تمام کشور یا در محل خاصی از کشور نفوذ داشته باشد «عرف مملکتی » و«عرف محلی » نام دارد. و اگر ناشی از افکار و اعمال مذهبی باشد آنرا «عرف مذهبی » نامند. و اگر ناشی از راه حلهای قضائی باشد آنرا «عرف قضات » یا «عرف قضائی »یا «رویه قضائی » گویند. و در غیر این صورت آنرا «عرف عام » نامند. (از فرهنگ حقوقی ). پیروی کردن افراد از مسأله ٔ معینی به نحو خاص در صورتی که مبنی بر اعتقاد بوده و میان آن افراد شایع گردد عرف نامیده میشود. به تعبیر دیگر روش خاصی را که افراد در مسأله ٔ معینی پیروی میکنند، بدون آنکه در قانون ذکری از آن رفته باشد عرف گویند. عرف که گاه نیز به عادت از آن تعبیر میشود سرچشمه ٔ اولی و اساسی بسیاری از قوانین در قدیم و جدید بوده است . با این فرق که در عصر حاضر عرف در درجه ٔ دوم اهمیت از لحاظ عمل، قرار دارد و درجائی به عرف تمسک می شود که قانون وجود نداشته باشد.و به هر حال هرچند در قانون به طور تصریح و اختصاصی از عرف ذکری به میان نمی آید لیکن به نحوی مورد حمایت و ملاک عمل قرار داده شده و ضمانت اجرائی برای آن تعیین می شود. اساس بیشتر قوانین عرف بوده و بخصوص قسمت اعظم قوانین انگلوساکسون را عرف تشکیل میدهد. و درفقه اسلام در تعیین موضوع معاملات و احکام عرف معتبر است . و بطور کلی فرق عرف با قانون در این است که اولاً واضع عرف اجتماع میباشد و در واقع آن را واضع معین و مشخصی نیست . ثانیاً مانند قانون، مدون نمی باشد.<br>- <span class=\"hlight\">بعرف </span> ؛ عرفاً. عادةً <span class=\"hlight\">:</span> <br>تا شرط شغل سوزن و سوزنگری بعرف <br>آخر بود به مثقبه اول به مطرقه .<br> <font color=\"Red\">سوزنی .</font><br>- <span class=\"hlight\">عرف شرع </span> ؛ آنچه پیشوایان و حاملان شرع، از شرع درک کنند و آن رامبنای احکام قرار دهند. (از اقرب الموارد). رجوع به عرف شود.<br>- <span class=\"hlight\">عرف عام </span> ؛ عرف که عمومیت داشته باشد. رجوع به عرف شود.<br>- <span class=\"hlight\">عرف عملی </span> ؛ در مقابل عرف لفظی و قولی . رجوع به عرف قولی شود.<br>- <span class=\"hlight\">عرف قضائی </span> ؛ عرف و رویه ای که ناشی از راه حلهای قضائی باشد. رجوع به عرف شود.<br>- <span class=\"hlight\">عرف قولی یا لفظی </span> ؛ آن است که مردم بر اطلاق لفظ بر آن آشنا باشند، در مقابل عرف عملی، که بر دو شی ٔ اطلاق لفظ میکنند ولی یکی را غیر از دیگری در نظر میگیرند. عرف عملی مختص نیست ولی عرف لفظی مختص میباشد. عرف لفظی مانند «لحم خنزیر» از «لحم » و عرف عملی مانندلفظ «دابة» که برسم داران اطلاق شود. (از اقرب الموارد).<br>- <span class=\"hlight\">عرف لسان </span> ؛ آنچه از لفظ درک شود و فهمیده گردد به حسب وضع لغوی آن . (از اقرب الموارد).<br>- <span class=\"hlight\">عرف محلی </span> ؛ عرفی که در محلی از مملکت معمول باشد. رجوع به عرف شود.<br>- <span class=\"hlight\">عرف مذهبی </span> ؛ عرفی که ناشی از افکار و عقاید مذهبی باشد رجوع به عرف و عرف شرعی شود.<br>- <span class=\"hlight\">عرف مملکتی </span> ؛ عرفی که در یک مملکت متداول و معمول باشد. رجوع به عرف شود.<br> <BR><font color=\"Blue\">◄</font> آیین . رسم . عادت . دأب . خو <span class=\"hlight\">:</span> <br>از نکوئی که عرف و عادت اوست <br>نرسد در صفات او اوهام .<br> <font color=\"Red\">فرخی .</font><br>تذکره ای به عرف او به دیوان عرض کردند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٨٣</span>). و رجوع به آیین شود. <BR><font color=\"Blue\">◄</font> نیکوئی و جوانمردی و سخاوت و دهش . (از منتهی الارب ). نیکویی . (دهار). نکوئی و احسان . (غیاث اللغات ). جود. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نام آنچه بذل و بخشش کردی . (منتهی الارب ). آنچه بذل و بخشش کرده شود. (ناظم الاطباء). اسم و نام چیزی است که می بخشی و بذل میکنی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شناختگی . (غیاث اللغات ) (ناظم الاطباء). ضد نکر، یعنی هر چه را از نیکی که نفس بشناسد و بدان اطمینان کند. گویند «أولاه عرفا»؛ یعنی برای او معروف و نیکی ساخت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اسم است اعتراف را. گویند. «علی َّ ألف ٌ عرفاً»؛ یعنی بر من است هزارتا، به اعتراف . و آن مفعول مطلق است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> موج دریا. (منتهی الارب ). موج بحر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> فش اسب . (منتهی الارب ) (ناظم الاطباء). موی گردن اسب، یعنی مویی که درقسمت محدب گردن اسب میروید. (از اقرب الموارد). بش اسب . (دهار). یال و بش . (زمخشری ). فژ. عُرُف . رجوع به عرف شود. <BR><font color=\"Blue\">◄</font> تاج خروس . (منتهی الارب ) (ناظم الاطباء). قطعه گوشتی است مستطیل بر بالای سر خروس، و «عرف الدیک » که گیاهی است به مناسبت شباهت بدان چنین خوانده شده است . (از اقرب الموارد). خوژه . خواجه . <BR><font color=\"Blue\">◄</font> ریگ توده ٔ بلند. و جای بلند. (منتهی الارب ). رمل و مکان مرتفع. (از اقرب الموارد). عُرُف و اَعراف . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مناره ای . (منتهی الارب ). مناره . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> نوعی از خرمابن . یا خرمابنی که نخستین بارش رسد. یا خرمابنی است به بحرین که برشوم نامندش . (منتهی الارب ). نوعی از نخل . یا اولین میوه ای است که میدهد. و گویند نخلی است در بحرین که برشوم نامیده میشود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درخت ترنج . (منتهی الارب ). درخت اترج . (از اقرب الموارد). پیاپی . (دهار). گویند «طارالقَطا عرفاً»؛ یعنی مرغان سنگخوار در پی یکدیگر پریدند. و نیز «جاءالقوم ُ عِفاً»؛ یعنی آن قوم پشت سر هم آمدند. (از منتهی الارب ) (از اقرب الموارد). و از آن جمله است قوله تعالی « <span class=\"hlight\">:</span> والمرسلات عرفا» . یعنی سوگند به فرستاده شده هایی که متتابع و پی درپی فرستاده شدند. و یا منظور این است که با «معروف » فرستاده میشوند. (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِخ ) از اعلام است . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (از ع، ص، اِ) در نه معنی ذیل مؤلف ناظم الاطباء «عرف » را مأخوذ از عربی دانسته است : جواز. <BR><font color=\"Blue\">◄</font> معلوم . <BR><font color=\"Blue\">◄</font> عمومی . <BR><font color=\"Blue\">◄</font> اصطلاح عامه . <BR><font color=\"Blue\">◄</font> هرچیز صحیح مشروع و مخصوص و مطبوع . <BR><font color=\"Blue\">◄</font> شایسته . <BR><font color=\"Blue\">◄</font> کلانی و بزرگی . <BR><font color=\"Blue\">◄</font> اسمی که به آن چیزی و یا کسی به طور عموم نامیده میشود. <BR><font color=\"Blue\">◄</font> حکم ثانوی .<br></font></div>'),
(182417, 'عرف', '<span class=\"hlight\">عرف .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (اِخ ) گویند سه چاه مشهور است : عرفة ساق، عرفة صارة، عرفة الاملح . (از معجم البلدان ). و رجوع به عرفة ساق و عرفة صارة و عرفة الاملح شود.<br></font></div>'),
(182418, 'عرف', '<span class=\"hlight\">عرف .</span><font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (ع اِ) ج ِ عُرفة. رجوع به عرفة شود. <BR><font color=\"Blue\">◄</font> ج ِ عُرف . (منتهی الارب ). رجوع به عرف شود.<br></font></div>'),
(182419, 'عرف', '<span class=\"hlight\">عرف .</span> <font color=\"DarkGreen\"><b>[ ع ُ]</font></b> (اِخ ) موضعی است . (منتهی الارب ). از مخلاف های یمن است که با صنعاء ده فرسخ فاصله دارد. و نیز آن را به صورت العرف الاعلی و العرف الاسفل ذکر کرده اند، و هر دو را «عرف عمروبن کلاب » نوشته اند، و بین آن دو، چهار یا پنج  فاصله است . و نیز گویند عرف جایگاهی است در دیار کلاب که در آن آبک شوری است از گواراترین آبهای نجد. (از معجم البلدان ).<br></font></div>'),
(182420, 'عرف', '<span class=\"hlight\">عرف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ عَروف . رجوع به عروف شود. <BR><font color=\"Blue\">◄</font> ج ِ أعرف . رجوع به اعراف شود. <BR><font color=\"Blue\">◄</font> ج ِ عَرفاء. (منتهی الارب ). رجوع به عرفاء شود.<br></font></div>'),
(182421, 'عرف', '<span class=\"hlight\">عرف .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (اِخ ) آبی است مر بنی اسد را. <BR><font color=\"Blue\">◄</font> موضعی است . (منتهی الارب ).<br></font></div>'),
(182422, 'عرف الاسد', '<span class=\"hlight\">عرف الاسد.</span> <font color=\"DarkGreen\"><b>[ ع ُ فُل ْ اَ س َ ]</font></b> (اِخ )جای جبهه است نزد منجمین . (یادداشت مرحوم دهخدا).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(182423, 'عرفات', '<span class=\"hlight\">عرفات .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) آنجا که حج کنند. (السامی ). موقف حاج است در روز نهم ذی الحجة به فاصله ٔ دوازده میلی مکه . (از مقدمه ٔ لغت میرسید شریف جرجانی ). جای توقف کردن حاجیان به منی . (یادداشت مؤلف ). نام جای ایستاده شدن حاجیان به روز عرفه که روز حج است . وآن صحرائی است . فراخ به فاصله ٔ نه کروه از مکه . حاجیان در آنجا ایستاده شوند و لبیک وادعیه خوانند و نماز ظهر و عصر در آنجا گزارند و به مکه بازگردند. (آنندراج ) (غیاث اللغات ). موقف حاج است بر دوازده میلی مکه . و آن اسمی است در لفظ جمع لذا به صورت معرفه جمع بسته نشود زیرا اماکن زایل نگردد. و گوئی یک شی ٔ واحد شده است . و اعراب آن چون اعراب «مسلمات و مؤمنات » است . و تنوین آن شبیه به تنوین مقابله است چنانکه در باب مسلمات وجود دارد. بدین سبب الف و لام بر آن داخل نشود و برخی گویند «عرفة» کوهی است و «عرفات » جمع عرفة است تقدیراً، زیرا گویند «وقفت بعرفة» همانطور که گویند «وقفت بعرفات ». (از اقرب الموارد). جای وقوف حاجیان روز نهم ذی الحجة و دوازده کروه از مکه ٔ معظمه بدین نام خوانده شده است زیرا آدم و حوا در آنجا آشنا گشتند و یا بجهت این است که جبرئیل علیه السلام چون به ابراهیم علیه السلام مناسک را آموخت به وی گفت «أعرفت ؟» و او جواب داد «عرفت ». و یا بسبب مقدس و معظم بودن آن است، گوئی به طیب و بوی خوش اندوده باشد. و آن اسمی است در لفظ جمع لذا بجهت معرفه بودن جمع نگردد. و اینکه میگویند «نزلنا عرفة» به صورت مفرد، شبیه مولد است و عربی خالص و محض نباشد. و آن اسمی است مصروف چنانکه در قرآن کریم آمده است <span class=\"hlight\">:</span> «فاذاافضتم من عرفات <font color=\"DarkGreen\"><b>[ ت ِ ن ْ ]</font></b>». (قرآن <span class=\"hlight\" dir=\"rtl\">١٩٨/٢</span>). در سبب آن گویند چون تاء آن بمنزله ٔ یاء و واو است در مسلمین و مسلمون، زیرا آن برای تذکیر است و تنوین بمنزله ٔ نون شده است . لذا اگر آن را به صورت نام بکار برند به حال خود گذاشته میشود چنانکه «مسلمون » را نیز در حالی که نام باشد به حال خود میگذارند. و بصورت مطلق، تنوین میگیرد و گویند هذه عرفات ٌ و رأیت عرفات ِ و مررت بعرفات ِ و حالت سومی نیز دارد و آن این است که اعراب پیش از نام بودن آن ظاهر گردد و تنوین آن مطلقاً ترک گردد و گفته شود: هذه عرفات ُ و رأیت عرفات ِ و مررت بعرفات ِ و نسبت بدان عَرَفی شود. (ازمنتهی الارب ). واحد است به لفظ جمع. و برخی گویند آن را مفرد نیست . و اینکه «یوم عرفة» گویند لغتی جدید است و عربی محض نباشد. و سبب آن این است که عرفة و عرفات نام یک جایگاه است و حال اینکه اگر «عرفات » جمعمی بود با عرفة هم معنی نمیگشت . بنابراین عرفة و عرفات نامی است از برای یک جایگاه و آن محدود است از کوه مشرف بر بطن عُرَنة تا جبال عرفة. و گویند حد آن ازکوه مشرف بر بطن عُرَنة است تا کوههای عرفه تا قصر آل مالک و وادی عرفة. و برخی گفته اند: عرفه قریه ای است که در آن مزارع و سبزه زارها و جالیزهای خربزه یافت شود. و اهل مکه را در آنجا خانه های زیبائی است که در روز عرفه بدانجا فرود میایند. و وجه تسمیه ٔ آن راچنین گفته اند که جبرائیل علیه السلام، هنگامی که مناسک را به ابراهیم علیه السلام می آموخت، چون به عرفة رسید به وی گفت «عرفت ؟» و او جواب گفت آری . لذا بدین نام خوانده شده است . و برخی در سبب تسمیه ٔ آن گفته اند آدم و حواء پس از خروج از بهشت در این نقطه با هم آشنا شدند و «تعارف » حاصل کردند. و نیز گفته اند سبب آن این است که مردم در این جایگاه به گناه خود «اعتراف » می کنند و بعضی آن را بجهت تحمل و صبر بر رنجی میدانند که برای رسیدن به آن باید متحمل شد، چه یکی ازمعانی «عِرف » صبر و شکیبائی و تحمل است . (از معجم البلدان ) <span class=\"hlight\">:</span> فاذا أفضتم من عرفات فاذکروا اﷲعند المشعر الحرام . (قرآن <span class=\"hlight\" dir=\"rtl\">١٩٨/٢</span>)؛ و هرگاه از عرفات برگشتید خداوند را در مشعرالحرام یاد کنید. و نهم روز <font color=\"DarkGreen\"><b>[ از ذی الحجة ]</font></b> عرفه، که حاجیان به عرفات باشند وحج یابند. (التفهیم ص <span class=\"hlight\" dir=\"rtl\">٢٥٢</span>). چون نزدیک عرفات برسیدنددرویشی همی آمد. (قابوسنامه، منتخب، ص <span class=\"hlight\" dir=\"rtl\">٢١</span>). روز دوشنبه به عرفات بودیم، مردم پر خطر بودند از عرب . چون از عرفات بازگشتم دو روز به مکه بایستادم . (سفرنامه ٔ ناصرخسرو، چ دبیرسیاقی ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>). روز چهارشنبه به یاری حق سبحانه و تعالی به عرفات حج بگزاردیم و دو روز به مکه بودیم . (سفرنامه ص <span class=\"hlight\" dir=\"rtl\">٧٥</span>). به دو روز و نیم ایشان رابه عرفات رسانیدند و زر بستاندند. (سفرنامه ص <span class=\"hlight\" dir=\"rtl\">٧٧</span>).<br>آمده سوی مکه از عرفات <br>زده لبیک عمره از تعظیم .<br> <font color=\"Red\">ناصرخسرو.</font><br>گفت نی گفتمش چو در عرفات <br>ایستادی و یافتی تقدیم .<br> <font color=\"Red\">ناصرخسرو.</font><br>به زمزم و عرفات و حطیم و رکن و مقام <br>به عمره و حجر و مروه و صفا و منی .<br> <font color=\"Red\">ادیب صابر.</font><br>به منی و عرفاتم زخدا درخواهید<br>که هم از کعبه پرستان خدائید همه .<br> <font color=\"Red\">خاقانی .</font><br>بینی به موقف عرفات آمده مسیح <br>از آفتاب جامه ٔ احرام در برش .<br> <font color=\"Red\">خاقانی (دیوان چ سجادی ص <span class=\"hlight\" dir=\"rtl\">٢١٦</span>).</font><br>پریر نوبت حج بود و مهد خواجه هنوز<br>از آنسوی عرفات است چشم بر فردا.<br> <font color=\"Red\">خاقانی .</font><br>مُعرَّف ؛ جای وقوف به عرفات . (منتهی الارب ).<br></font></div>'),
(182424, 'عرفات', '<span class=\"hlight\">عرفات .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی از دهستان به به جیک، بخش سیه چشمه، شهرستان ماکو. سکنه آن <span class=\"hlight\" dir=\"rtl\">١٧٠</span> تن . آب آن از چشمه و محصول آن غلات و عسل است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(182425, 'عرفاتی', '<span class=\"hlight\">عرفاتی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ تی ی ]</font></b> (ص نسبی ) منسوب است به عرفات . (از انساب سمعانی ). و رجوع به عرفات و عرفی شود.<br></font></div>'),
(182426, 'عرفاس', '<span class=\"hlight\">عرفاس .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) ناقه ٔ نیک شکیبا بر سیر و سفر. (منتهی الارب ). ماده شتر صبور در حرکت و سیر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ)شیر بیشه . و یا اینکه به این معنی عِفراس بتقدیم فاء صحیح باشد. (از منتهی الارب ). رجوع به عفراس شود.<br></font></div>'),
(182427, 'عرفاص', '<span class=\"hlight\">عرفاص .</span> <font color=\"DarkGreen\"><b>[ ع ِ]</font></b> (ع اِ) تازیانه ای که بدان ادب نمایند و سلطان عقاب نماید. (منتهی الارب ). سوط، که سلطان بوسیله ٔ آن مجازات کند. (از اقرب الموارد). تازیانه . (دهار). <BR><font color=\"Blue\">◄</font> توک  پی دراز. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> توک پی که بدان سرهای چوب کجاوه بندند. (منتهی الارب ). خصله و دسته ٔ موی که سرهای چوبهای هودج را بدان بندند. (از اقرب الموارد). ج، عَرافیص . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(182428, 'عرفان', '<span class=\"hlight\">عرفان .</span> <font color=\"DarkGreen\"><b>[ ع ِ رِف ْ فا ]</font></b> (ع مص ) شناختن و دانستن بعد از نادانی . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> درک کردن به یکی از حواس خمسه . <BR><font color=\"Blue\">◄</font> اقرار کردن به گناه . <BR><font color=\"Blue\">◄</font> پاداش دادن کسی را. (از اقرب الموارد) (ناظم الاطباء). عِرفان . معرفة. عرفة. رجوع به عِرفان شود.<br></font></div>'),
(182429, 'عرفان', '<span class=\"hlight\">عرفان .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُف ْ فا ]</font></b> (اِخ ) نام کوهی است . (معجم البلدان ). کوهی است . (منتهی الارب ).<br></font></div>'),
(182430, 'عرفان', '<span class=\"hlight\">عرفان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) معلی بن عرفان . تبع تابعی است . (منتهی الارب ).<br></font></div>'),
(182431, 'عرفان', '<span class=\"hlight\">عرفان .</span> <font color=\"DarkGreen\"><b>[ ع ِ رِف ْ فا ]</font></b> (اِخ ) گویند جایگاهی است به عینة. (از معجم البلدان ).<br></font></div>'),
(182432, 'عرفان', '<span class=\"hlight\">عرفان .</span> <font color=\"DarkGreen\"><b>[ ع ِ رِف ْ فا ]</font></b> (اِخ ) نام صاحب آن راعی و چوپان که در حق صاحب خود چنین گفته است :<br>کفانی عرفان لکری و کفیته <br>کلوء النجوم و النعاس معانقه .<br><font color=\"Red\">(از منتهی الارب ) (از اقرب الموارد).</font><br></font></div>'),
(182433, 'عرفان', '<span class=\"hlight\">عرفان .</span> <font color=\"DarkGreen\"><b>[ ع ِ رِف ْ فا <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ رُف ْ فا ]</font></b> (ع اِ) جندب کلان و بزرگ مانند ملخ . و آن جز در گیاه «رمث » و «عنظوان » یافت نشود. ویا کرمکی است که در رمل و شنهای «عالج » یا «دهناء» موجود میباشد. (از اقرب الموارد) (از منتهی الارب ).<br></font></div>'),
(182434, 'عرفان', '<span class=\"hlight\">عرفان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) نام زنی سرودگوی که در این فن ید طولی داشت . (منتهی الارب ). یکی از مغنیه ها و آوازه خوانهای عصر عباسی، و معاصر عریب المأمونیة بوده است . (از اعلام النساء از الاغانی ).<br></font></div>'),
(182435, 'عرفان', '<span class=\"hlight\">عرفان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) شناختن و دانستن بعد از نادانی . (منتهی الارب ) (ناظم الاطباء). شناختن . (زوزنی ) (آنندراج ) (غیاث اللغات ). شناختن . بازشناختن . معرفت . (فرهنگ فارسی معین ). شناخت . شناسائی . آگاهی . درایت . اطلاع <span class=\"hlight\">:</span> به مدد و معاونت اوکمر بستند و یکدیگر را بر عرفان قدرخانه قدیم و کرم عمیم او تحریض کردند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٨٦</span>).<br>- <span class=\"hlight\">اهل عرفان </span> ؛ دانشمندان و حکما. (ناظم الاطباء) <span class=\"hlight\">:</span> <br>هر مؤمن که ز اهل عرفان باشد<br>خورشید سپهر فضل واحسان باشد.<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">به عرفان بیرون بردن </span> ؛ عمداً تحمل کردن . دیده و دانسته چشم پوشی کردن . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عرفان بخشیدن </span> ؛ آموختن .<br>- <span class=\"hlight\">عرفان در امری دادن </span> ؛ اعلام کردن .<br> <BR><font color=\"Blue\">◄</font> شناختن و معرفت حق تعالی . (غیاث اللغات ) (آنندراج ). معرفت حق تعالی . (ناظم الاطباء). نام علمی است از علوم الهی که موضوع آن شناخت حق و اسماء از علوم الهی که موضوع آن شناخت حق و اسماء و صفات اوست . و بالجمله راه و روشنی که اهل اﷲ برای شناسائی حق انتخاب کرده اند عرفان مینامند. عرفان و شناسائی حق به دو طریق میسر است یکی به طریق استدلال از اثر به مؤثر و از فعل به صفت و از صفات به ذات، و این مخصوص علماء است . دوم طریق تصفیه ٔ باطن و تخلیه ٔ سر از غیر و تخلیه ٔ روح، و آن طریق معرفت خاصه ٔ انبیاء و اولیا و عرفا است . و این معرفت کشفی و شهودی را غیر از مجذوب مطلق هیچ کس را میسر نیست مگر به سبب طاعت و عبادت قالبی و نفسی و قلبی و روحی و سری و خفی، و غرض از ایجاد عالم معرفت شهودی است . عرفا عقیده دارند برای رسیدن به حق و حقیقت بایستی مراحلی را طی کرد تا نفس بتواند از حق و حقیقت بر طبق استعداد خود آگاهی حاصل کند. و تفاوت آنها با حکما این است که تنها گرد استدلال عقلی نمیگردند بلکه مبنای کار آنها بر شهود و کشف است . (از فرهنگ مصطلحات عرفاء از شرح گلشن راز) <span class=\"hlight\">:</span> <br>اگر بشناختی خود را به تحقیق <br>هم از عرفان حق یابی تو توفیق .<br> <font color=\"Red\">ناصرخسرو.</font><br>شفای درد دلها گشت عرفان <br>ز عرفان روشن آمد جاودان جان .<br> <font color=\"Red\">ناصرخسرو.</font><br>مفصل صورت جسم است ومجمل صورت ذاتت <br>بهم این هر دو نفس آمد سزای حکمت و عرفان .<br> <font color=\"Red\">ناصرخسرو (دیوان چ تقوی ص <span class=\"hlight\" dir=\"rtl\">٣٥٨</span>).</font><br> <BR><font color=\"Blue\">◄</font> به مفهوم عام، وقوف به دقایق و رموز چیزی است . مقابل علم سطحی و قشری . مثلاً گویند فلان طبیب عارفی است، یعنی غور رس و موی شکاف است و بظواهر نپرداخته است یا فلان عارف سخن و سخندان عارفی است یعنی فقط به تقلید سطحی قانعنشده و دقایق سخن و سخندانی را فرا گرفته است . (از فرهنگ فارسی معین ) و رجوع به جلوه های عرفان ایران ازآقای همائی، مجله ٔ رادیو شماره ٔ <span class=\"hlight\" dir=\"rtl\">٤٤</span>-<span class=\"hlight\" dir=\"rtl\">١٦</span>-<span class=\"hlight\" dir=\"rtl\">١٧</span> شود. <BR><font color=\"Blue\">◄</font> به مفهوم خاص، یافتن حقایق اشیاء به طریق کشف و شهود. و به این جهت تصوف یکی از جلوه های عرفان است . توضیح اینکه در اصل تصوف یکی از شعب و جلوه های عرفان است . تصوف یک نحله و طریقه ٔ سیر و سلوک عملی است که از منبع عرفان سرچشمه گرفته است . اما عرفان یک مفهوم عام کلی تری است که شامل تصوف و سایر نحله ها نیز میشود. به عبارت دیگر نسبت مابین تصوف و عرفان به قول منطقیان، عموم و خصوص من وجه است . به این معنی که ممکن است شخص عارف باشد اما صوفی نباشد، چنانکه ممکن است به ظاهر داخل طریقه ٔ تصوف باشد، اما از عرفان بهری نبرده باشد. و گاهی دیده ایم کلمه ٔ عارف را درمعنی فاضلتر و عالی تر از لفظ درویش و صوفی استعمال کرده اند. در کتاب اسرارالتوحید آمده «خواجه امام مظفر فوقانی به شیخ ابوسعید گفت : آن بود که او گوید.» بعضی عرفان را جنبه ٔ علمی و ذهنی تصوف دانند و تصوف را جنبه ٔ عملی عرفان . (فرهنگ فارسی معین ) و رجوع به جلوه های عرفان ایران، همایی، مجله ٔ رادیو شماره ٔ <span class=\"hlight\" dir=\"rtl\">٤٤</span> -<span class=\"hlight\" dir=\"rtl\">١٧</span> - <span class=\"hlight\" dir=\"rtl\">١٦</span> شود. <BR><font color=\"Blue\">◄</font> به مفهوم اخص، تصوف . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> درک کردن به یکی از حواس . (از ناظم الاطباء). دانستن چیزی را به وسیله ٔ حسی از حواس خمسه، و چنین شخصی را عارف و عریف و عروفةگویند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اقرار به گناه کردن . و از آن جمله است که گویند «ما أعرف لأحد یصرعنی »؛ یعنی اقرار نمی کنم بر کسی که مرا بزمین زند. (از اقرب الموارد) (از ناظم الاطباء). عَرف . و رجوع به عَرف شود. <BR><font color=\"Blue\">◄</font> پاداش دادن . و از آن جمله است که گویند «أنا أعرف للمحسن والمسی ٔ». (از اقرب الموارد) (ناظم الاطباء). عَرف . و رجوع به عرف شود. <BR><font color=\"Blue\">◄</font> صبر و شکیبائی کردن بر کاری . (از اقرب الموارد) (از ناظم الاطباء). عَرف . عرفة. مَعرِفة.عرفان . رجوع به عرف و عرفان و عرفة و معرفة شود. <BR><font color=\"Blue\">◄</font> (اِمص ) شرم و حیا. (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> بی حجابی . (آنندراج ) <span class=\"hlight\">:</span> <br>کی گمان میبرد دل کان شمع فانوس حجاب <br>چون ز عرفان دم زند صد دودمان برهم خورد.<br><font color=\"Red\">محتشم کاشی (از آنندراج ).</font><br></font></div>'),
(182436, 'عرفان کده', '<span class=\"hlight\">عرفان کده .</span> <font color=\"DarkGreen\"><b>[ ع ِ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِمرکب ) خانه ٔ عرفان . مرکز عرفان . جایگاه عرفان . آنجاکه مجمع عرفان و جایگاه معرفت اﷲ باشد <span class=\"hlight\">:</span> <br>روز تعطیل به عرفان کده ٔ مشرب نیست (؟)<br>صبح شنبه خجل است از شب آدینه ٔ ما.<br><font color=\"Red\">صائب (آنندراج ).</font><br></font></div>'),
(182437, 'عرفانی', '<span class=\"hlight\">عرفانی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ص نسبی ) منسوب به عرفان . رجوع به عرفان شود.<br></font></div>'),
(182438, 'عرفة', '<span class=\"hlight\">عرفة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ف َ ]</font></b> (اِخ ) روز نهم از ذی الحجة. گویند هذا یوم عرفة (بدون تنوین و بدون ال ). (از منتهی الارب ). روز نهم ذی حجة، چرا که روز استاده شدن حاجیان است در مقام عرفات . و به سکون ثانی خطا است . عوام هند که یک روز پیشتر شب برات و عیدالفطر و نهم ماه محرم را نیز عرفه گویند خطا است . (غیاث اللغات ).<br>- <span class=\"hlight\">یوم عرفة</span>؛ روز نهم از ذی حجة. (از اقرب الموارد). مَشهود؛ روز عرفه . وَتر و وِتر؛ روز عرفة. (منتهی الارب ).<br><BR><font color=\"Blue\">◄</font> نام جایگاهی است در مکه که آن را «عرفات » نیز گویند. رجوع به عرفات شود.<br></font></div>'),
(182439, 'عرفة', '<span class=\"hlight\">عرفة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ف َ ]</font></b> (اِخ ) ابن الحارث، مکنی به ابوالحارث . صحابی است . (یادداشت مرحوم دهخدا).<br></font></div>'),
(182440, 'عرفة', '<span class=\"hlight\">عرفة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ف َ ]</font></b> (اِخ ) نام جایگاهی است که در شعر ذی الرمة آمده است . (از معجم البلدان ).<br></font></div>'),
(182441, 'عرفة', '<span class=\"hlight\">عرفة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ف َ ]</font></b> (ع اِ) زمین برآمده ونمایان دراز رویاننده ٔ گیاه . (منتهی الارب ). زمینی است بالا آمده و بارز و مستطیل شکل که رویاننده است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ریگ توده ٔ بلند و جای بلند. (منتهی الارب ). رمل و مکان مرتفع. (از اقرب الموارد). ج، عُرَف . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> حد فاصل میان دو چیز. (منتهی الارب ). حد بین دو شی ٔ. (ازاقرب الموارد). ج، عُرَف، (منتهی الارب ) (اقرب الموارد)، اَعراف . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِخ ) سیزده موضعاند: عرفة صارة، عرفةالقبان، عرفة ساق، عرفةالاملح، عرفة القزوین، عرفة خجا، عرفة نبات، عرفة ضربه، عرفة منعج، عرفة الاجبال و غیرذلک . (منتهی الارب ). رجوع به هر یک از ترکیبات فوق در ردیف خود شود.<br></font></div>'),
(182442, 'عرفة', '<span class=\"hlight\">عرفة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ف َ ]</font></b> (ع اِمص ) شناخت و شناختن . (منتهی الارب ). شناخت و شناسائی . <BR><font color=\"Blue\">◄</font> سؤال . (ناظم الاطباء). اسم است اعتراف بمعنی سؤال را. (منتهی الارب ). اسم است از «اعتراف » بمعنی استخبار. (از اقرب الموارد). عَرفَة. رجوع به عَرفَة شود.<br></font></div>'),
(182443, 'عرفة', '<span class=\"hlight\">عرفة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ف َ ]</font></b> (ع مص ) شناختن و دانستن بعد از نادانی . (از منتهی الارب ). به معانی عِرفان است . (از اقرب الموارد). رجوع به عرفان (مص ) شود.<br></font></div>'),
(182444, 'عرفة', '<span class=\"hlight\">عرفة.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع اِ) باد. (منتهی الارب ). ریح . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ریش کف دست . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زخمی است که در سپیدی کف دست پدید آید.(از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) اسم است اعتراف را در معنی سؤال . (از منتهی الارب ). سؤال عاقلانه . (ناظم الاطباء). اسم است از «اعتراف » بمعنی استخبار. (از اقرب الموارد). عِرْفة. رجوع به عرفة شود.<br></font></div>'),
(182445, 'عرفج', '<span class=\"hlight\">عرفج .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (اِخ ) نام مردی است . (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br></font></div>'),
(182446, 'عرفج', '<span class=\"hlight\">عرفج .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع اِ) درختی که در ریگزار روید. درختی است ریگی . (منتهی الارب ). درختی است بیابانی، و گویند همان قتاد است . ج، عَراِفج . یکدانه ٔ آن عرفجة. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نوعی از یتوعات است . و گفته اند اسم نباتی است که بر شطوط انهار میروید و پنج شاخه میدارد و لهذا آن را ذوخمسة الاغصان می نامند، و گفته اند درختی است شبیه به سماق . (از تحفه ٔ حکیم مؤمن ). بارهنگ آبی . (فرهنگ فارسی معین ). ابوسریع. بکمون . ذوخمسة اغصان . شورطاق . حلبة.<br></font></div>'),
(182447, 'عرفج بری', '<span class=\"hlight\">عرفج بری .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ج ِ ب َرْ ری ی ]</font></b> (ترکیب وصفی، اِ مرکب ) بکمون است . (مخزن الادویه ). رجوع به عرفج شود.<br></font></div>'),
(182448, 'عرفسیس', '<span class=\"hlight\">عرفسیس .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع ص ) درشت سطبر از شتران و زنان . (منتهی الارب ). زن و یا ناقه ٔ تنومند و قوی . گویندناقة عرفسیس و امراءة عرفسیس . (از اقرب الموارد).<br></font></div>'),
(182449, 'عرفشی', '<span class=\"hlight\">عرفشی .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ شی ی ]</font></b> (ع اِ)به معنی عرفشة است . (از دزی ). رجوع به عرفشه شود.<br></font></div>'),
(182450, 'عرفضان', '<span class=\"hlight\">عرفضان .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع اِ) گیاهی است که آن را ذُرَق نامند. حندقوقا. عرقصان . عریفضان . عرنفضان . رجوع به ذرق در همین لغت نامه شود.<br></font></div>'),
(182451, 'عرفط', '<span class=\"hlight\">عرفط.</span> <font color=\"DarkGreen\"><b>[ ع ُ ف ُ ]</font></b> (ع اِ) نوعی از درخت خاردار. (منتهی الارب ). درختی است از عضاه که «مغفور» میتراود و شکوفه ٔ آن سفید و غلطان است . یکدانه ٔ آن عرفطة. (از اقرب الموارد). عِض ّ و عُض ّ، درخت عرفط. (از منتهی الارب ). عَبیبة، چیزی است شیرین بر شکل صمغ که از درخت عرفط برآید و خورده شود. (منتهی الارب ).<br></font></div>'),
(182452, 'عرفطی', '<span class=\"hlight\">عرفطی .</span><font color=\"DarkGreen\"><b>[ ع ُ ف ُ ی ی ]</font></b> (اِخ ) نسبت است به عرفطة. و او جد طالوت بن ابی بکربن خالدبن عرفطه ٔ عرفطی، حلیف و هم پیمان بنی زهرة بوده است . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182453, 'عرفه', '<span class=\"hlight\">عرفه .</span> <font color=\"DarkGreen\"><b>[ ع ُ ف َ ]</font></b> (اِخ ) (گردنه ٔ...) گردنه ای است در راه شیراز به جهرم . رجوع به گردنه ٔ عرفه در ردیف خود شود.<br></font></div>'),
(182454, 'عرفی', '<span class=\"hlight\">عرفی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ می ی ]</font></b> (ص نسبی ) منسوب به عرفات . (منتهی الارب ). رجوع به عرفات شود.<br></font></div>'),
(182455, 'عرفی', '<span class=\"hlight\">عرفی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ص نسبی ) منسوب به عرف . رجوع به عرف شود. مقابل شرعی . (یادداشت مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> آنچه بر فعل متوقف باشد چون مدح و ثنا. (از تعریفات جرجانی ). <BR><font color=\"Blue\">◄</font> مبالغه شده . <BR><font color=\"Blue\">◄</font> معروف . <BR><font color=\"Blue\">◄</font> جمعشده و زیاد گشته . <BR><font color=\"Blue\">◄</font> متجاوز. <BR><font color=\"Blue\">◄</font> عمومی . (ناظم الاطباء).<br></font></div>'),
(182456, 'عرفی', '<span class=\"hlight\">عرفی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) زَنفَل بن شداد عرفی . از روات حجاز و ساکن عرفه بود. وی از ابن ابی مُلَیکة روایت کرده است و ابوالحجاج و نصربن طاهر از او روایت کرده اند. (از معجم البلدان ). و رجوع به اللباب فی تهذیب الانساب شود.<br></font></div>'),
(182457, 'عرفی شیرازی', '<span class=\"hlight\">عرفی شیرازی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ی ِ ]</font></b> (اِخ ) محمدبن بدرالدین، ملقب به جمال الدین . از شاعران مشهور ایران در قرن دهم هجری است که زندگانیش بیشتر درهندوستان گذشت . ولادتش به سال <span class=\"hlight\" dir=\"rtl\">٩٦٣</span> هَ . ق . در شیراز اتفاق افتاد و در جوانی به هندوستان رفت و به دربار جلال الدین اکبرشاه (<span class=\"hlight\" dir=\"rtl\">٩٦٣</span>-<span class=\"hlight\" dir=\"rtl\">١٠١٤</span> هَ ق .) امپراطور مغولی هند راه یافت و در آن سامان بود تا اینکه به سال <span class=\"hlight\" dir=\"rtl\">٩٩٩</span> در شهر لاهور درگذشت . عرفی در سرودن قصیده و غزل و قطعه و ترجیع و ترکیب قدرت داشت و او را میتوان در ردیف بهترین شاعران سبک معروف به «هندی » درآورد. علاوه براین در مثنوی نیز دست داشت و دو منظومه ٔ مخزن الاسرارو خسرو و شیرین نظامی را استقبال کرده است . و رساله ای صوفیانه بنام نفسیه نیز دارد. و رجوع به گنج سخن و تذکره ٔ مخزن الغرائب و صحف ابراهیم و مقدمه ٔ کلیات عرفی شیرازی، بکوشش غلامحسین جواهری شود <span class=\"hlight\">:</span> <br>هزار حیف که عرفی و نوعی و سنجر<br>نیند جمع به دارالعیار برهان پور.<br> <font color=\"Red\">صائب .</font><br>درسخن از عرفی و طالب ندارد کوتهی <br>عیب صائب این بود کز زمره ٔ اسلاف نیست .<br><font color=\"Red\">صائب .</font><br></font></div>'),
(182458, 'عرفیة', '<span class=\"hlight\">عرفیة.</span> <font color=\"DarkGreen\"><b>[ ع ُ فی ی َ ]</font></b> (ص نسبی ) مؤنث عرفی، منسوب به عُرف . رجوع به عرف شود.<br>- <span class=\"hlight\">تکالیف عرفیه </span> ؛ تحمیلات عمومی . و خراج فوق العاده . (ناظم الاطباء).<br>- <span class=\"hlight\">حقیقت عرفیه </span> ؛ علوم متعارفی و بدیهیات .<br>- <span class=\"hlight\">عرفیه ٔ خاصه در منطق </span> ؛ همان عرفیه ٔ عامه است مقید به قید «لادوام » و غیردائمی بودن به حسب ذات . و آن گاهی موجبه است مانند: هر کاتبی انگشتان وی متحرک است تا وقتی کاتب باشد، نه دائما، که ترکیب آن از موجبه ٔ عرفیه ٔ عامه (جزء اول ) و سالبه ٔمطلقه ٔ عامه (مفهوم لادوام ) است . و گاهی سالبه میباشد مانند: هیچ چیز از کاتب، ساکن الاصابع نیست، مادام که کاتب است، نه دائما. که جزء اول آن عرفیه ٔ عامه ٔ سالبه است و جزء دوم آن موجبه ٔ مطلقه ٔ عامه میباشد. (از تعریفات جرجانی ) (کشاف اصطلاحات الفنون ).<br>- <span class=\"hlight\">عرفیه ٔ دائمه </span> ؛ درمنطق، قضیه ای است که محمول آن به حسب ذات و هم به حسب وصف دائم بود. (از فرهنگ علوم عقلی از اساس الاقتباس ص <span class=\"hlight\" dir=\"rtl\">١٤٩</span>).<br>- <span class=\"hlight\">عرفیه ٔ دائمه ٔ لاضروریه </span> ؛ در منطق، قضیه ای است که محمول در آن به حسب ذات لادائم لاضروری باشد. مانند «کل فلک متحرک دائما، لاضرورة». (از فرهنگ علوم نقلی از اساس الاقتباس ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span>).<br>- <span class=\"hlight\">عرفیه ٔ ضروریه </span> ؛ در منطق، قضیه ای است که بحسب ذات ضروری باشد. یعنی مادام که ذات آن موجود باشد. نسبت محمول بدان ضروری باشد. (از فرهنگ علوم عقلی از اساس الاقتباس ص <span class=\"hlight\" dir=\"rtl\">١٤٤</span>).<br>- <span class=\"hlight\">عرفیه ٔ عامه </span> ؛ قضیه ٔ موجبه ای است که حکم در آن به دوام ثبوت محمول برای موضوع باشد مادام که ذات موضوع متصف به وصف عنوانی است . (فرهنگ فارسی معین از اساس الاقتباس ). آن است که در آن به داوم ثبوت محمول برای موضوع، یا سلب آن حکم شده باشد مادام که ذات موضوع متصف به عنوان باشد. مثال ایجابی آن چون : هر کاتبی انگشتان وی متحرک است تا وقتی کاتب باشد. و مثال سلبی آن چون : هیچ چیز از کاتب، ساکن الاصابع نیست مادام که کاتب است . (از تعریفات جرجانی ). و رجوع به کشاف اصطلاحات النفون و دستور العلماء شود.<br>- <span class=\"hlight\">عرفیه ٔ لادائمه </span> ؛ در منطق، قضیه ای است که به حسب وصف دائم بوده و به حسب ذات لادائم . (از فرهنگ علوم عقلی از اساس الاقتباس ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span>).<br>- <span class=\"hlight\">عرفیه ٔ لاضروریه </span> ؛ در منطق، قضیه ای است که محمول آن در آن به حسب وصف دائم بوده و به حسب ذات لاضروری . (از فرهنگ علوم عقلی از اساس الاقتباس ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span>).<br>- <span class=\"hlight\">معانی عرفیه </span>؛ یا منقول عرفی، معنایی است که توسط عامه ٔ مردم برای لغتی، غیر از معنی لغوی آن، وضع شود.<br></font></div>'),
(182459, 'عرفیل', '<span class=\"hlight\">عرفیل .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) به عربی صفرة بیض است . (مخزن الادویه ).<br></font></div>'),
(182460, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) استخوان که گوشت از وی رندیده و خورده باشند. (منتهی الارب ). استخوانی که گوشت از وی باز کرده باشند. (غیاث اللغات ). استخوانی که قسمت اعظم گوشت لخم آن را گرفته باشند و پاره های گوشت نازک و لذیذ بر آن مانده باشد. (از اقرب الموارد). ج، عِراق، و نیز عُراق به ضم به طور نادر آمده است، چه جمع بر وزن فُعال جز کلمه ای چند در لغت عرب به کار نرفته است و از آن جمله است : تُؤام، ج ِ توام . رُباب، ج رُبَّی . ظؤار، ج ظئر. عُراق، ج ِ عرق . رُخال، ج ِ رخِل . و فُرار، ج ِ فَریر. و برخی چند کلمه ٔ دیگر بر آن افزوده اند. (از منتهی الارب ) (از اقرب الموارد). و یا اینکه عرق استخوان با گوشت است، وعراق استخوانی است که گوشت از وی رندیده و خورده باشند و یا هر دو لفظ جهت هر دو معنی است، و از آن جمله است حدیث «تناول النبی (ص ) عرقا ثم صلی و لم یتوضاء». (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> راه پاسپرده و مسلوک . (منتهی الارب ). راهی که مردم آن را بپیمایند تا واضح و آشکار گردد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بوریا از برگ خرما بافته که هنوز زنبیل نساخته باشند. و یا زنبیل از برگ خرما. (منتهی الارب ). سفیفه ای که از «خوص » و غیره بافته باشند و هنوز آن را «زبیل » نکرده اند. و یا خود زبیل . و گویند پانزده صاع گنجایش دارد. (از اقرب الموارد). عَرَق . رجوع به عرق شود.<br></font></div>'),
(182461, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) جایگاهی است در نزدیکی بصره . (از معجم البلدان ). دو موضع است در بصره . (منتهی الارب ). رجوع به عرقان و عرق ناهق شود.<br></font></div>'),
(182462, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ )جایگاهی است در چندفرسخی هیت . (از معجم البلدان ).<br></font></div>'),
(182463, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) مهل اهل عراق است و آن حد بین نجد و تهامه باشد. و گویند عرق کوهی است در راه مکه، و ذات العرق از آن مأخوذ است . (از معجم البلدان ). میقات اهل عراق است و آن در حدود دو مرحله از مکه فاصله دارد. (از اقرب الموارد). جای احرام اهل عراق در حج، و آن بادیه ای است . (منتهی الارب ). نام جایی در بادیه که محل احرام اهل عراق است در حج .(ناظم الاطباء). رجوع به ذات عرق در ردیف خود شود.<br></font></div>'),
(182464, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) لقب حسین بن عبدالجبار است . (از منتهی الارب ).<br></font></div>'),
(182465, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) نام جد ابراهیم بن محمدبن عرق حمصی است که محدث بود. (منتهی الارب ).<br></font></div>'),
(182466, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) رگ . (منتهی الارب ) (آنندراج ) (مهذب الاسماء). رگ بدن . (غیاث اللغات ). وریدهای بدن که خون در آن جاری است، چون عرق اکحل و عرق قیفال و غیره . (از اقرب الموارد). ج، عُروق، أعراق، عِراق . (منتهی الارب ) (اقرب الموارد). رگ جهنده . (ناظم الاطباء). رگ ناجهنده . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>قوت عرق عراق از مادت نطق من است <br>گرچه شریان دل شروانیان را نشترم .<br> <font color=\"Red\">خاقانی .</font><br>حق چو خواهد زلزله ٔ شهری مرا<br>امر فرماید که جنبان عرق را.<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">عرق الریة</span> ؛ نای حلقوم . (ناظم الاطباء).<br>- <span class=\"hlight\">عرق عظیم </span> ؛ شریانی است بر صلب کشیده نازل به اسفل بدن . (یادداشت مرحوم دهخدا).<br> <BR><font color=\"Blue\">◄</font> رگه . گویند فی الشراب عرق من الحموضة؛ یعنی رگ است، و فی فلان عرق من العبودیة؛ أی خلط. (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> اصل و بن هر چیزی . (منتهی الارب ). اصل هرچیزی . (آنندراج ) (از اقرب الموارد). اصل مردم . (مهذب الاسماء). و از آن جمله است حدیث «من أحیا أرضا میتة فهی له و لیس لعرق ظالم فیها حق » که منظور از عرق ظالم این است که شخص در زمینی که دیگری آن را احیاکرده است بدون رضای صاحب آن، کشت کند یا درخت بکاردتا مستحق آن زمین گردد. و آن با حذف مضاف خوانده شده است . یعنی :... لذی عرق ظالم . (از منتهی الارب ) (از اقرب الموارد) <span class=\"hlight\">:</span> این خاندان را عرقی است ازخاندان طاهریان که ملوک خراسان بوده اند. (تاریخ بیهقی ).<br>کامروز ترا مادحی است جز من <br>کز عرق نبوت تبار دارد.<br> <font color=\"Red\">مسعودسعد.</font><br>بر عرق طاهر و محتد زاهر وی فضایل ذات او دلیلی قاطع و برهانی ساطع بود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٩٦</span>).<br>عرق عرب و فضل عجم ساز سفر کرد<br>دل زو مژه آرا چه عرب را چه عجم را.<br> <font color=\"Red\">درویش واله هروی (از آنندراج ).</font><br>- <span class=\"hlight\">عرق پدری </span> ؛ رگ پیوند پدر بودن <span class=\"hlight\">:</span> <br>چون در پدران رفته دیدم <br>عرق پدری زدل بریدم .<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">عرق حمیت </span> ؛ خوی عصبیت . خوی مردانگی .<br>- <span class=\"hlight\">عرق سبعیت </span> ؛ خوی درندگی که در کمون انسانی مضمر است . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> عرق سبعیت او به حرکت آمده وی را به قتل آورد. (جهان آرا ص <span class=\"hlight\" dir=\"rtl\">٤١٨</span>). و رجوع به یادداشتهای قزوینی ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨</span> شود.<br>- <span class=\"hlight\">عرق فتنه </span> ؛ رگ حادثه و شر <span class=\"hlight\">:</span> سلطان از کار سجستان بپرداخت و عرق فتنه که در آن نواحی نابض بود سکون یافت . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٥٧</span>).<br>- <span class=\"hlight\">عرق مردی </span>؛ رگ مردانگی . رگ جوانمردی . عرق مردانگی <span class=\"hlight\">:</span> <br>عرق مردی آنگهی پیدا شود<br>که مسافر همره اعدا شود.<br> <font color=\"Red\">مولوی .</font><br><BR><font color=\"Blue\">◄</font> ریشه و بیخ درخت . (منتهی الارب ) (آنندراج ). بیخ درخت باریک . (غیاث اللغات ). ریشه های باریک . (ناظم الاطباء). بیخ درخت . (مهذب الاسماء).اصل درخت . (از اقرب الموارد). ج، عُروق . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زمین شوره که هیچ نرویاند. (منتهی الارب ). زمین شور که نبات ندهد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زمین شوره که گز رویاند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کوه درشت گذار که جهت صعوبت بر آن برآمدن نتوانند. (منتهی الارب ). کوه بزرگ که بجهت سختی آن، بر آن بالا نروند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کوه خرد (از اضداد است ). (منتهی الارب ). جبل صغیر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> کوه تنک از ریگ به درازا گسترده . یا جای بلند. (منتهی الارب ). کوه رقیق، و باریک از رمل، مستطیل شکل بر زمین، و گویند مکان مرتفع. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کرانه و حد کوه . (منتهی الارب ). قطر و حد جبل . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تن . (منتهی الارب ). جسد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شیر. (منتهی الارب ). لبن . (اقرب الموارد). گویند: لبن حدیث العرق ؛ یعنی بتازگی از پستان دوشیده شده است و طعم آن تغییر نیافته است . <BR><font color=\"Blue\">◄</font> بچگان بسیار. (منتهی الارب ). نتاج بسیار. (از اقرب الموارد). جای بسیار درخت . <BR><font color=\"Blue\">◄</font> گیاهی است که بدان رنگ کنند. <BR><font color=\"Blue\">◄</font> باقی مانده ٔ گیاه ترش . (منتهی الارب ). بقایای حَمض . (از اقرب الموارد). ج، عُروق . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(182467, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (ع ص ) لبن عرق ؛ شیر مزه برگردانیده از خوی شتر که بر آن بار است . (منتهی الارب ). شیری که مزه ٔ وی از خوی شتری که بر آن بار کرده باشند برگردیده باشد. (ناظم الاطباء). شیری که طعمش به سبب عرق شتری که بر آن بار شده است، فاسد شده باشد. (از اقرب الموارد). و آن چنان است که شیر را در مشکی قرار میدهند و بر شتر می بندند حال اگر بین مشک و پهلوی شتر، حائلی نباشد و عرق شتر بدان شیر رسد، طعم آن فاسد میشود و بوی آن تغییر می یابد. (از اقرب الموارد) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> مکان عرق، جای برابر. (منتهی الارب ). جای هموار. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> عرق دار و خوی دار. (ناظم الاطباء).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(182468, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) خوی حیوان . و گاهی در غیر حیوان هم به استعاره آید. (منتهی الارب ).خوی اندام . (غیاث اللغات ). خوی . (دهار).خوی انسان ودیگر حیوانات و تری که از تن آنان تراوش کند. و گاه در غیر حیوان هم گویند. (ناظم الاطباء).آب پوست است که از ریشه ٔ مویها جاری گردد. و آن اسم جنس است و جمع نگردد. و اصل آن برای حیوان است و در غیر آن، به صورت استعاره به کار رود. (از اقرب الموارد). رطوبت که از مسام حیوان تراود در گرما و پاره ای بیماریها. (یادداشت مرحوم دهخدا). خوی که از مسامات درآید، و اطلاق آن بر رِشح کوزه و مانند آن مجاز است . و پاک و بیدار، از صفات آن است ؛ و انجم، ستاره، اختر، سهیل، سیماب، قایم النار، باران، شبنم، گوهر، انجم دانه، دیده بان، چشم، حباب و جام شراب از تشبیهات اوست . و با لفظ نشستن و ریختن و آمدن و کردن و افشاندن و برانداختن مستعمل است . (از آنندراج ). مایعی شفاف و بی رنگ (باستثنای مواقع غیرطبیعی و مرضی که گاهی رنگی میشود) ودارای بوی مخصوص که نسبت به نواحی مختلف بدن مانند تنه و زیر بغل ها و کف دستها و پاها و پوست بیضه، فرق میکند. بوی مخصوص عرق بعلت وجود اسیدهای چربی فرار است که در ترکیب عرق وجود دارد. وزن مخصوص عرق <span class=\"hlight\" dir=\"rtl\">١/٠٠٤</span>و واکنش آن اسید است . ولی عرق زیر بغل و عرق بعضی حیوانات دارای فعل و انفعالات قلیایی است . عرق از تمام سطح پوست بدن توسط غدد مخصوص عرق که در داخل جلد قرار دارند ترشح میشود و تعداد غدد مترشحه ٔ عرق را در بدن انسان به دو میلیون تخمین زده اند. ترشح عرق از بدن دایمی است به طوری که در هوای سرد نیز مقداری عرق ترشح میشود. نرمی و لطافت جلد و رطوبت پوست بدن به واسطه ٔ همین ترشح دائمی است . به طور متوسط ترشح عرق در هر ساعت در یک انسان بالغ بین <span class=\"hlight\" dir=\"rtl\">٣٠</span> تا <span class=\"hlight\" dir=\"rtl\">٤٠</span> گرم است . عرق در هر هزار گرم <span class=\"hlight\" dir=\"rtl\">٩٩٠</span> گرم آب دارد و <span class=\"hlight\" dir=\"rtl\">١٠</span> گرم بقیه مواد معدنی و آلی است . مهمترین ماده ٔ آلی عرق اوره است که در حدود <span class=\"hlight\" dir=\"rtl\">٠/٤٤</span> گرم تا یک گرم در هر هزار گرم عرق موجود است . (فرهنگ فارسی معین ). حِمَّه . حَمیم مَسیح . هَجم <span class=\"hlight\">:</span> چون به خادم رسیدم به حالی بودم عرق بر من نشسته . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٧٢</span>). امیرالمؤمنین چون مرا بدید بر آن حال، به بزرگی خویش فرمود خادمی را که عرق از روی من پاک کند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٧٣</span>).<br>غذا به طعم لعاب عسل رسد به گلو<br>عرق به بوی گلاب و عرق چکد زمسام .<br> <font color=\"Red\">ابوالفرج رونی .</font><br>با موکبش آب شور دریا<br>ماند عرق تکاوران را.<br> <font color=\"Red\">خاقانی .</font><br>برگُل ِ سرخ از نم اوفتاده لاَّلی <br>همچو عرق بر عذار شاهد غضبان .<br> <font color=\"Red\">سعدی .</font><br>آمد از پرده به مجلس عرقش پاک کنید<br>که چرا دختر رز توبه زمستوری کرد.<br> <font color=\"Red\">حافظ (از آنندراج ).</font><br>ز تاب آتش دوری شدم غرق عرق چون گل <br>بیار ای باد شبگیری نسیمی زان عرق چینم .<br> <font color=\"Red\">حافظ.</font><br>هر آش به آب میتوان پخت <br>لیکن عرق است آب منتو.<br><font color=\"Red\">بسحاق .</font><br>عرق که بر رخت از گرمی شراب آید<br>شفق به ساغرزرین آفتاب آید.<br> <font color=\"Red\">صائب (از آنندراج ).</font><br>تخم قابل در زمین پاک گوهر میشود<br>دانه ٔ یاقوت میسازد عرق را روی تو.<br> <font color=\"Red\">صائب (از آنندراج ).</font><br>از آن زمان که رخ از باده برفروخته ای <br>عرق به روی تو سیماب قائم النار است .<br> <font color=\"Red\">بهار (از آنندراج ).</font><br>به وصال او خوش آن دم که چو می رسیده باشم <br>چو حیا از آن گل روعرقی کشیده باشم .<br> <font color=\"Red\">ملامفید بلخی (از آنندراج ).</font><br>- <span class=\"hlight\">با عرق جبین </span> ؛ با کثرت کار و رنج و تعب . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">در عرق بودن </span> ؛ کنایه است از خجلت و شرمساری <span class=\"hlight\">:</span> <br>اهل عراق در عرقند از حدیث تو<br>شروان بنام تست شرف وان و خیروان .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">در عرق شدن </span> ؛ کنایه از خجلت و شرمساری است . (لغت محلی شوشتر خطی ).<br>- <span class=\"hlight\">عرق آفتاب </span> ؛ خوی خورشید. عرق خورشید. صاحب آنندراج این ترکیب را آورده و گوید: و مانند آن ادعای محض است . و شاهد ذیل را از طالب آملی آورده است <span class=\"hlight\">:</span> <br>کی گفتمت که چهره به آب گلاب شوی <br>گفتم به شبنم عرق آفتاب شوی .<br>- <span class=\"hlight\">عرق انفعال </span> ؛ عرق شرم . عرق خجلت <span class=\"hlight\">:</span> <br>در روز حشر شسته شود پاک نامها<br>گر نم برون دهد عرق انفعال من .<br> <font color=\"Red\">میرزا صائب (از آنندراج ).</font><br>- <span class=\"hlight\">عرق برآوردن </span> ؛ عرق کردن . خوی کردن <span class=\"hlight\">:</span> <br>هر ساعت از لطیفی رویت عرق برآرد<br>چون بر شکوفه بارد باران نوبهاری .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">عرق برانداختن </span> ؛ عرق کردن . خوی کردن <span class=\"hlight\">:</span> <br>بر انداخت بیچاره چندان عرق <br>که شبنم برآرد بهشتی ورق .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">عرق به روی کسی ریختن </span> ؛ مرادف آب بر چهره ریختن است . (از آنندراج ) <span class=\"hlight\">:</span> <br>غضب آلوده چو خواهند که خیزد از خواب <br>گلعذاران عرق فتنه برویش ریزند.<br> <font color=\"Red\">میرزا ابوطالب (از آنندراج ).</font><br>- <span class=\"hlight\">عرق تب </span> ؛ عرق و خوی که بر اثر تب و حمی عارض شود. ملال . (منتهی الارب ).<br>- <span class=\"hlight\">عرق جبین </span> ؛ عرق پیشانی . خوی جبین . عرق که ازرنج و خستگی بر پیشانی ظاهر گردد.<br>- <span class=\"hlight\">عرق جبین و کدیمین </span> ؛ خوی پیشانی و رنج دست . با زحمت و تعب بسیار. و رجوع به عرق الجبین شود.<br>- <span class=\"hlight\">عرق حیا</span> ؛ عرق شرم . عرق انفعال . عرق و خوی که بجهت شرم و حیا بر بدن نشیند <span class=\"hlight\">:</span> <br>مرو ای نگه به گلشن که به روی هر گل اینجا<br>ز هجوم چشم شبنم عرق حیانشسته .<br> <font color=\"Red\">میرزاصائب (از آنندراج ).</font><br>- <span class=\"hlight\">عرق خجلت </span>؛ عرق شرم . عرق انفعال . عرق حیا. عرق و خوی که از خجلت و شرم بر اندام آدمی نشیند <span class=\"hlight\">:</span> <br>حاصل دل شکنی غیرپشیمانی نیست <br>مومیای عرق خجلت سنگ است اینجا.<br> <font color=\"Red\">میرزا صائب (از آنندراج ).</font><br>- <span class=\"hlight\">عرق <font color=\"DarkGreen\"><b>[ کسی را ]</font></b> درآوردن </span> ؛ او راخجالت دادن . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عرق سرد</span> ؛ خویی که از تراوش آن شخص احساس سرما کند (به هنگام ترس و خجلت ) <span class=\"hlight\">:</span> <br>چون به تب لرزه آفتاب در است <br>عرق سرد چون سحاب کند.<br> <font color=\"Red\">خاقانی .</font><br>قطرات عرق سرد جبینش را پوشانده بود. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عرق سعی </span> ؛ عرقی که از تردد بسیار یا برداشتن بار گران و مانند آن پدید آید. (آنندراج ).<br>- <span class=\"hlight\">عرق شرم </span> ؛ عرق و خوی که از احساس خجلت و شرم بر بدن انسان پدید آید. عرق انفعال . عرق خجلت . عرق حیا <span class=\"hlight\">:</span> <br>غافل ازاختر شوق عرق شرم مشو<br>این جگر گوشه ٔ گلزار حیا را دریاب .<br> <font color=\"Red\">میرزا صائب (از آنندراج ).</font><br>از گل روی توغافل که تواند گل چید<br>که ز شبنم عرق شرم تو بیدارتر است .<br> <font color=\"Red\">میرزا صائب (از آنندراج ).</font><br>طالعی چون عرق شرم تمنا دارم <br>که به صد چشم تماشای جمال تو کنم .<br> <font color=\"Red\">میرزا صائب (از آنندراج ).</font><br>- <span class=\"hlight\">عرق شعله </span> ؛ مرادف عرق آفتاب . (آنندراج ). رجوع به عرق آفتاب شود <span class=\"hlight\">:</span> <br>آب در دیده ٔ ماکسوت آتش پوشید<br>عرق شعله زند جوش ز فواره ٔما.<br> <font color=\"Red\">طالب آملی (از آنندراج ).</font><br>زجام دل عرق شعله خورده ام طالب <br>از آن دماغ ز بوی شراب سیرترم .<br> <font color=\"Red\">طالب آملی (از آنندراج ).</font><br>- <span class=\"hlight\">عرق صحت </span> ؛ عرقی را گویند که در امراض حاره برآمدن آن موجب خفت طبیعت میگردد. (آنندراج ) <span class=\"hlight\">:</span> <br>دیده ٔ هجران زده را روز وصل <br>گریه شادی عرق صحت است .<br> <font color=\"Red\">میرزا رضی دانش (از آنندراج ).</font><br>- <span class=\"hlight\">عرق مستی </span> ؛ عرقی که در حال مستی شراب از گرمی کل کند. (آنندراج ). خوی که بر اثر مستی بر اندام نشیند.<br>- <span class=\"hlight\">عرق نشستن بر کسی </span> ؛ خوی آوردن او. (یادداشت مرحوم دهخدا). عرق کردن . خوی کردن . رجوع به عرق کردن شود <span class=\"hlight\">:</span> <br>تا عرق از می بر آن رخسار جان پرور نشست <br>در بهشت از جوش دعوی چشمه ٔ کوثر نشست .<br> <font color=\"Red\">صائب (از آنندراج ).</font><br>با روی آتشین چو گذشتی به بوستان <br>گل را زانفعال عرق بر جبین نشست .<br> <font color=\"Red\">امیرشاهی سبزواری (از آنندراج ).</font><br>- <span class=\"hlight\">عرق ننگ </span> ؛ عرق که از تحمل ننگ بر انسان نشیند <span class=\"hlight\">:</span> <br>بی تو گر هستی من صورت تمثالی داشت <br>چهره ٔ آینه ها را عرق ننگ شدم .<br> <font color=\"Red\">میرزا بیدل (از آنندراج ).</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">حمام بی عرق نمی شود</span> ؛ در این کار دادن رشوتی ضرور است . (امثال و حکم دهخدا).<br> <BR><font color=\"Blue\">◄</font> آبی که از بخار طبخ ادویه حاصل کنند. (غیاث اللغات ). آب مقطر و غالباً معطر که از پاره ای گیاهان و گلها که بوسیله ٔ قرع و انبیق گیرند. (از یادداشتهای مرحوم دهخدا). آنچه از حبوبات و گلها و ادویه ٔ یابسه و مایعه تقطیر کنند مسمی به این اسم است . سریع النفوذ و لطیف تر از اصل آن چیز. و عرق نانخواه و دارچینی بهتر از اکثر عرقها است . و عرق شکر و عرق شراب و خرما و امثال آن قوی تر از اصل او و سریعالاثر. و اکثار آن محرق خون و مورث امراض حاره و مهلک است . (از تحفه ٔ حکیم مؤمن ). محصول مقطری که از تقطیر مایعات درقرع و انبیق و جز آن به دست می آید. (ناظم الاطباء). آبی را گویند که داروها و خوشبویها در آن انداخته ازقرع و انبیق کشند. از این جا است که شراب مقطر را نیز عرق خوانند، و این از اهل زبان بتحقیق پیوسته است . لیکن از این بیت میرزا ملک مشرقی معلوم میشود که عرق غیرشراب مقطر است <span class=\"hlight\">:</span> <br>خون جگر به صافی خوناب دیده نیست <br>کیفیت عرق چو شراب رسیده نیست .<br>و در این مصرعه «شراب چکیده » نیز دیده شده است . و ظاهراً مراد از شراب چکیده آن است که از نمد بگذارنند. (آنندراج ). در اصطلاح پزشکی قدیم، آبی است که داروها و خوشبویها در آن انداخته از قرع و انبیق کشند. مانند گلاب و عرق بادیان . و عطری که به طرز تقطیر از گرفتن عصاره ٔ نباتات خوشبو یا چیزهای معطر به عمل آورند. (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>زین پیش گلاب و عرق و باده ٔ احمر<br>در شیشه ٔ عطار بد و در خم خمار.<br> <font color=\"Red\">منوچهری .</font><br>غذا به طعم لعاب عسل رسد به گلو<br>عرق به بوی گلاب و عرق چکد زمسام .<br> <font color=\"Red\">ابوالفرج رونی .</font><br>همچو گلاب و عرق شده مه آزار<br>بوده چو کافور سوده در مه آذر.<br> <font color=\"Red\">مسعودسعد (دیوان چ نوریان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٢</span>).</font><br>گرچه همه دلکشند از همه گل نغزتر<br>کوعرق  مصطفاست وین دگران خاک و آب .<br> <font color=\"Red\">خاقانی .</font><br>شب خلوت که وقت عشرت بود<br>عرق و عود کرد و مشک اندود.<br> <font color=\"Red\">سعدی .</font><br>روی زیبا و جامه ٔ دیبا<br>عرق و عود و رنگ و بوی و هوس <br>اینهمه زینت زنان باشد<br>....<br> <font color=\"Red\">(گلستان سعدی ).</font><br>- <span class=\"hlight\">عرق استخوان </span> ؛ هر چیز خائیده و جاویده شده . (ناظم الاطباء).<br>- <span class=\"hlight\">عرق بادرنجبویه </span> ؛ مایعی که از تقطیر جوشانده ٔ بادرنجبویه در آب حاصل میشود. این مایع دارای مقادیری نسبةً زیاد از اسانس و آلکالوئیدهای بادرنجبویه است . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عرق بهار</span> ؛ مایعی خوشبو که از تقطیر بهار نارنج و دیگرمرکبات با آب بواسطه ٔ دیگ و نیچه کشند. (ناظم الاطباء). اسم فارسی عرق شکوفه ٔ نارنج است . (تحفه ٔ حکیم مؤمن ). عرقی که از گل نارنج و ترنج بطور گلاب کشند. (غیاث اللغات ). عرق خوش بو که از گل نارنج و ترنج کشند. و بهترین آن از گل کرنه است که به فارسی بهارنارنج گویند و بویش نهایت تند میباشد. (از آنندراج ) <span class=\"hlight\">:</span> <br>ریحان ترا نگار بستند<br>گل از عرق بهار بستند.<br> <font color=\"Red\">شیخ ابوالفیض فیاضی (از آنندراج ).</font><br>بر جامه ٔ شاهدان بستان <br>شبنم عرق بهار افشان .<br> <font color=\"Red\">محمدقلی سلیم (از آنندراج ).</font><br>و رجوع به عرق بهار نارنج شود.<br>- <BR><font color=\"Blue\">◄</font> بمعنی شراب نیز آمده است . (از آنندراج ) (از غیاث اللغات ).<br>- <span class=\"hlight\">عرق بهارنارنج </span> ؛ مایعی که از تقطیر جوشانده ٔ غنچه ها و گلهای درخت نارنج به دست می آید. (فرهنگ فارسی معین ). و رجوع به عرق بهار شود.<br>- <span class=\"hlight\">عرق بید</span> ؛ مایعی که از تقطیر جوشانده ٔ گلها و ساقه های جوان وگل بید حاصل میشود. (فرهنگ فارسی معین ). ماءالخلاف است . (تحفه ٔ حکیم مؤمن ).<br>- <span class=\"hlight\">عرق بیدمشک </span> ؛ مایعی که از تقطیر جوشانده ٔ برگها و ساقه های جوان و گل بیدمشک حاصل میشود. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عرق پودنه </span> ؛مایعی که از تقطیر جوشانده ٔ برگها و ساقه ٔ پودنه درآب به دست میاید که محتوی اسانس پودنه است . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عرق شکر</span> ؛ شراب قندی که رائج هندوستان است . (آنندراج ) <span class=\"hlight\">:</span> <br>ریخت در اشک لعل او اشک ز چشم تر مرا<br>مست نمود و بی خبر این عرق شکر مرا.<br> <font color=\"Red\">میرزا طاهر وحید (از آنندراج ).</font><br>بشرطی که باشد عرق از شکر<br>کزو نیست می خواره را دردسر.<br> <font color=\"Red\">طغرا (از آنندراج ).</font><br>- <span class=\"hlight\">عرق فتنه </span> ؛ عرقی که از گل سنجد گیرند. (آنندراج ). شواهد ذیل را صاحب آنندراج برای معنی فوق آورده است، اما به نظر می آید که مراد بروز آشوب و فتنه حاصل از به کار بردن عرق باشد <span class=\"hlight\">:</span> <br>چون عرقناک شود روی تو از گرمی مل <br>شیشه ها از عرق فتنه توان پر کردن .<br> <font color=\"Red\">میرزاجلال اسیر (از آنندراج ).</font><br>اهل میخانه گلاب از گل صهبا گیرند<br>عرق فتنه ز دردانه ٔ مینا گیرند.<br> <font color=\"Red\">محمدقلی سلیم (از آنندراج ).</font><br>- <span class=\"hlight\">عرق گاوزبان </span> ؛ عرقی که از گل گاوزبان گیرند <span class=\"hlight\">:</span> <br>بیدرد سخنهای تو بیمار مرا کرد<br>هر چند کلامت عرق گاوزبان است .<br> <font color=\"Red\">میرزا عبدالغنی قبول (از آنندراج ).</font><br>- <span class=\"hlight\">عرق گُل </span> ؛ گلاب . (آنندراج ) (ناظم الاطباء). رجوع به گلاب شود.<br>- <span class=\"hlight\">عرق گوشت </span> ؛ ماءاللحم است . (از تحفه ٔ حکیم مؤمن ). رجوع به ماءاللحم شود.<br>- <span class=\"hlight\">عرق گوگرد</span> ؛ در اصطلاح شیمی، اسیدسولفوریک را گویند. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عرق نعناع </span> ؛ مایعی که از تقطیر جوشانده ٔ برگ و ساقه و گل نعناع حاصل شود.<br> <BR><font color=\"Blue\">◄</font> چیزی است که از شراب یا ثفل و دردی آن و غیره میگیرند، و آن بسیار مست کننده است . (از اقرب الموارد). مایع مسکری که از تقطیر انگور و یا کشمش و یا خرمای تخمیر شده به دست آرند و آن راعرق انگور و عرق خرما و تاهور نیز نامند. (ناظم الاطباء). ماده ٔ مسکر تند و قوی و سفید رنگ (برنگ آب ) که از انگور و مویز و کشمش و چیزهای دیگر گیرند و آن قسمی الکل از درجه ٔ کم است و شبیه به وتکای روسی میباشد. و با فعل «خوردن » صرف شود. (یادداشتهای مؤلف ). محلول الکلی که از تقطیر شرابهای انگور، کشمش، سیب، گلابی یا خرمای تخمیر شده حاصل شود. و میزان الکلش بین <span class=\"hlight\" dir=\"rtl\">٥٠</span> تا <span class=\"hlight\" dir=\"rtl\">٧٠</span> درصد میباشد. گاهی عرق را هم با افزودن آب در الکل اتیلیک <span class=\"hlight\" dir=\"rtl\">٩٦</span> درجه به دست می آورند. و معمولا\" افزودن آب تا حدی است که درجه ٔ الکل مطلوب درصد قسمت حاصل شود. معمولا\" در پزشکی بمنظور تداوی، مقداری مواد مقوی و مشهی به عرق اضافه میکنند و تحت نام لیکورهای مختلف تجویز مینمایند. (فرهنگ فارسی معین ). نام این مشروب الکلی نخستین بار در تاریخ ایران بمناسبت مرگ امیرتیمور بنظر رسیده است . در ذیلی که لطف اﷲ عبداﷲبن عبدالرشید معروف به «حافظ ابرو» بر تاریخ ظفرنامه ٔ شامی نگاشته به این واقعه و این مشروب اشاره میکند. و عین عبارت او چنین است : «در دوازدهم رجب المرجب سنه ٔ سبع و ثمانمائة به بلده ٔ اترار فرود آمد. درین مابین رغبت به عرق نمود. حاضر گردانیدند. جوهری که عین آتش بود در صورت آب، و از غایت لطافت چون هوا مدرک بصر نمیشد، و از کمال رقت با خاک کثیف نمی آمیخت .و ساقی چون نرگس ساغر زرین بر دست سیمین نهاده بوده، و اقداح مالامال چون قمر در منازل خویش روان کرده، و بندگی «صاحبقرانی » دو شبانه روز دیگر بر این عرق مشغول شد که قطعاً التفات به هیچ غذائی نفرمود. روز دیگر مزاج مبارک اندک تغییری پیدا کرد. گفتند ورا مگرخمار است . بجهت تداوی، بحکم «واخری تداویت منهابها»یک دو جرعه دیگر نوش کرد. و بسبب خنکی ظاهر آن تسکین حرارتی تصور کردند. و چون در معده گرم شد حرارت زیادت و تتمه ٔ آن مقدمه ٔ نامرادی گشت، و سپهر بی مهر از پس نوش نیش کین آورد، و دهر بی وفا سرور به شیون و سور به ماتم بدل گردانید. و همین سرگذشت را ابن عربشاه در عجائب المقدور چنین آورده است : «و جعل تیمور یواصل التسیار حتی وصل کورة تدعی اترار و لما کان بظاهره من البرد آمنا، أرادأن یجعل له ما یرد الا بردة عنه باطناً. فأمر أن یستقطر له من عرق الخمر المعمول فیها الادویة الحارة و الاقاویة و البهارات النافعة... فجعل یتناول من ذلک العرق و یتفوق أفاویقه من غیرفرق . فأثر ذلک العرق من أمعائه و کبده فترنح بنیان جسمه ... فطلب الاطباءو عرض علیهم هذا الداء فعالجوه فی ذلک البرد، بأن وضعوا علی بطنه و جنبیه الجمد. فانقطع ثلاث لیال و عکم أحمال الانتقال الی دارالخری و النکال ». (از سعدی تا جامی، ادوارد براون، حاشیه ٔ ص <span class=\"hlight\" dir=\"rtl\">٢٣٢</span>). خوندمیر در تاریخ حبیب السیر نیز به واقعه ٔ مذکور چنین اشاره میکند: «... و هر شب مجلس همایون از فروغ باده ٔ حمرا و شعاع صاغر صهبا صفت روشنی پذیرفت . در آن اثناء رغبت عرق فرمود، جوهری آوردند به رنگ مانند آب و به صفت آتش وش و به صورت بلور مذاب . دو شبانه روز دیگر صاحبقران والاگهر چنان به عرق مشغول نمود که اصلا\" میل طعام نفرمود. بنابرآن مزاج همایون متغیر شده عشرت اندیشه در آن تغییر را حمل بر خمار کردند، و یک دو جام دیگر به صورت دادند، و لحظه ای حرارت تسکین یافته، چون مدبر طبیعت در آن شراب اثرکرد تب اشتداد پذیرفت و در روز چهارشنبه عاشر شعبان سنه ٔ سبع و ثمانمائة مرضی صعب روی نمود...» . تاهو؛ عرق شراب . (برهان قاطع). و رجوع به تاهو شود.<br>- <span class=\"hlight\">عرق دوآتشه </span> ؛ نوع قوی تر عرق، از لحاظ درجه ٔ الکل . رجوع به عرق شود.<br><BR><font color=\"Blue\">◄</font> تری دیوار. (منتهی الارب ). نم دیوار. (شرح قاموس ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آبی که از درون کوزه و جز آن بیرون تراود. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> هر مایعی که مانند قطرات خرد بر سطح چیزی می نشیند. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ثواب و پاداش، یا اندک از آن . گویند: «اتخذت عنده یدا بیضاء و اخری خضراء، فما نلت منه عرقاً»؛ أی ثواباً. (از اقرب الموارد) (از متن اللغة) (از لسان العرب ) (از تاج العروس ). <BR><font color=\"Blue\">◄</font> شیر، بدان جهت که نخستین در عروق روان گردد سپس آن در پستان فرود آید. (منتهی الارب ) (از اقرب الموارد). شیر و لبن . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> رسته ٔ خرمابنان و رسته ٔ خشت خام و رسته ٔ خشت دیوار و رسته ٔ بنا. (منتهی الارب ). هر صف و ردیف و رگ از خشت و آجر یا سنگ در دیوار. (از اقرب الموارد). گویند قدبنی البانی عرقا أو عرقین ؛ یعنی بنا یک ردیف و رگ یا دو رگ بنا کرد. (از منتهی الارب ) (از اقرب الموارد). یک رسته نورد. یک رده از خشت گل . یک رسته نورده . (زمخشری ). <BR><font color=\"Blue\">◄</font> صف اسبان و مرغان و هرچه صف زده باشد. (منتهی الارب ). سطر و ردیف از اسبان و از طیور و از هر چه ردیف شده باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> راه کوه و بینی آن . (منتهی الارب ). راههاو طرق در کوهها. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آثار پیروی شتران مر یکدیگر را. (از منتهی الارب ). آثار دنبال کردن شتران هم دیگر را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مویز. (منتهی الارب ). زبیب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> انجیر. (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بوریا از برگ خرما بافته که هنوز زنبیل نساخته باشند. یا زنبیل از برگ خرما. (منتهی الارب ). «سفیفه » که از برگ درخت خرما و «خوص » بافته باشند پیش از اینکه از آن «زبیل » بسازند. و یا خود زبیل .و گویند حجم آن پانزده صاع است . (از اقرب الموارد).عَرق . و رجوع به عرق شود. <BR><font color=\"Blue\">◄</font> تک اسب . (منتهی الارب ). شَوط و طَلَق و خیز. (از اقرب الموارد). گویند جری الفرس عرقا أو عرقین ؛ یعنی اسب یک یا دو شوط دوید. (از اقرب الموارد) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> عرق التمر؛ دوشاب خرما. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دبس و شیره ٔ خرما. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عرق القربة؛ کنایه از سختی خجالت و کوشش و مشقت است . و در سبب این کنایه گفته اند که قربه و مشک هرگاه عرق کند بدبوی میشود. و یا اینکه چون مشک را عرق نیست، گویی امر محال را به عهده گرفته است . و یا اینکه منظور از عرق القربة، منفعت و سود قربة است، گویی که وی آنقدر رنج برده است که به عرق قربة یعنی آب آن محتاج گشته است . و یا عرق القربة، بوریا و سفیفه ای است که حامل مشک آن را بر سینه ٔ خود می نهد. و یا معنی آن به عهده گرفتن مشقتی است چون مشقت و رنج حامل مشک، که از سنگینی بار آن عرق بریزد. و گویند عرق ازآن شخص است نه مشک و قربه، و سبب این کنایه این است که مشکها را کنیزان و اشخاصی که فاقد خدم هستند برمیدارند و اگر شخصی بزرگزاده دچار تنگدستی و فقر شود ناچار مشک را خود حمل میکند و از خستگی و نیز از شرم و خجلت از مردم عرق میکند. (از منتهی الارب ) (از ناظم الاطباء) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عرق الخِلال، آنچه به نظر دوستی دهند از عطیه . (منتهی الارب ). آنچه شخص برای تو بتراود، یعنی به خاطر دوستی ترا دهد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ما أکثر عرق اًبله ؛ چه بسیارند نتایج و بچه های شتران وی . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> ج ِ عَرَقة. (منتهی الارب ) (اقرب الموارد). رجوع به عَرَقة شود.<br></font></div>'),
(182469, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع مص ) سست گردیدن . (از منتهی الارب ). کسل و تنبل شدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سود کردن . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بچه گرفتن از شتران . (منتهی الارب ) (دهار). <BR><font color=\"Blue\">◄</font> عرق الرجل ؛ پوست آن مرد ترشح کرد، و چنین شخصی را عَرقان گویند. (از اقرب الموارد).خوی گرفتن . (تاج المصادر بیهقی ) (المصادر زوزنی ).<br></font></div>'),
(182470, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) باز کردن و خوردن گوشت را که بر استخوان بود. (از منتهی الارب ). گوشت از استخوان باز کردن و بخوردن . (تاج المصادر بیهقی ) (المصادر زوزنی ). برکندن گوشتی را که بر استخوان بود و خوردن آن را. (از ناظم الاطباء). عرق العظم ؛ آنچه از گوشت بر استخوان بود، خورد و تمام آن را گرفت . چنین شخصی را «عارق » گویند. (از اقرب الموارد). مَعَرق . و رجوع به معرق شود. <BR><font color=\"Blue\">◄</font> رفتن در زمین . (از منتهی الارب ) (از ناظم الاطباء). عرق فی الارض، در زمین رفت . (ازاقرب الموارد). عُروق . و رجوع به عروق شود. <BR><font color=\"Blue\">◄</font> «عِراق » ساختن مرتوشه دان را. (از منتهی الارب ). عراق ساختن برای توشه دان . (ناظم الاطباء). عرق المزادة؛ برای مزادة و توشه دان، عراق قرار داد. (از اقرب الموارد). عُروق . رجوع به عروق . <BR><font color=\"Blue\">◄</font> کم گوشت گردیدن . (از منتهی الارب ) (از ناظم الاطباء). عُرق الرجل (بصیغه ٔ مجهول )؛ آن مرد قلیل اللحم و کم گوشت شد، و چنین شخصی را «معرق » گویند. (از اقرب الموارد).<br></font></div>'),
(182471, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) موضعی است . (منتهی الارب ). جایگاهی است در زبید و نام آن در شعر ابی عقامة آمده است . (از معجم البلدان ).<br></font></div>'),
(182472, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) کوهی است خرد در راه مکه . (منتهی الارب ). گویند کوهی است در راه مکه، که «ذات عرق » از آن مأخوذ است . (از معجم البلدان ). و رجوع به عرق (ذات ...) شود.<br></font></div>'),
(182473, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) وادیی است از آن بنی حنظلةبن مالک بن زید مناةبن تمیم . (از معجم البلدان ). رودباری است مربنی حنظلةبن مالک را. (از منتهی الارب ).<br></font></div>'),
(182474, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) نام پدر عبدالرحمان بن عرق و پسرش محمد است که تابعیان بودند. (از منتهی الارب ).<br></font></div>'),
(182475, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ رُ ]</font></b> (ع اِ) ج ِ عِراق . (منتهی الارب ) (اقرب الموارد). رجوع به عراق شود.<br></font></div>'),
(182476, 'عرق', '<span class=\"hlight\">عرق .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (ع ص ) رجل عرق ؛ مرد بسیارخوی . (منتهی الارب ). مردی که بسیار عرق کند. (ناظم الاطباء). بسیارعرق . (از اقرب الموارد). عُرَقة. رجوع به عرقة شود.<br></font></div>'),
(182477, 'عرق آصف', '<span class=\"hlight\">عرق آصف .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ ص ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) بیخ کبر است . (مخزن الادویه ). <br></font></div>'),
(182478, 'عرق آلود', '<span class=\"hlight\">عرق آلود.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ن مف مرکب ) پوشیده شده از خوی و عرق . (ناظم الاطباء). آنکه عرق کرده باشد. (آنندراج ). آلوده به عرق . خوی آلوده <span class=\"hlight\">:</span> <br>ای بسا خانه ٔ تقوی که رسیده ست به آب <br>تا ز منزل عرق آلود برون تاخته ای .<br> <font color=\"Red\">صائب .</font><br>نقصان نکرد خضر ز سر چشمه ٔ حیات <br>جان را به جبه ٔ عرق آلود یار بخش .<br> <font color=\"Red\">میرزا صائب (از آنندراج ).</font><br>و رجوع به عرق آلوده شود.<br></font></div>'),
(182479, 'عرق آلوده', '<span class=\"hlight\">عرق آلوده .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) پوشیده شده از خوی و عرق . (ناظم الاطباء). عرق آلود. رجوع به عرق آلود شود.<br></font></div>'),
(182480, 'عرق آور', '<span class=\"hlight\">عرق آور.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ وَ ]</font></b> (نف مرکب ) آنچه باعث خارج شدن عرق گردد. دواها که تولید خوی و عرق کنند. مثلا\" گویند: آسپرین عرق آور است . (یادداشت مرحوم دهخدا). مُعِّرق .<br></font></div>'),
(182481, 'عرق آوردن', '<span class=\"hlight\">عرق آوردن .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ وَ دَ ]</font></b> (مص مرکب ) خارج کردن عرق و خوی .مُعِّرق شدن . مثلا\" گویند آسپرین عرق میآورد. (از یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> اندر یاد کردن تدبیرهای عرق آوردن، یعنی تدبیر خوی آوردن . (ذخیره ٔ خوارزمشاهی ). <BR><font color=\"Blue\">◄</font> عرق کردن . خوی کردن <span class=\"hlight\">:</span> <br>عرق بر عارضین آرد چو شبنم .<br> <font color=\"Red\">سعدی .</font><br>ضحی ؛ عرق آوردن . امطار؛ عرق آوردن پیشانی کسی . (منتهی الارب ).<br></font></div>'),
(182482, 'عرق افشان', '<span class=\"hlight\">عرق افشان .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ اَ ]</font></b> (نف مرکب ) عرق افشاننده . مرادف عرق ریز. (آنندراج ) <span class=\"hlight\">:</span> <br>از عرق افشان بناگوش وی <br>چشمه ٔ خورشید یکی قطره خوی .<br> <font color=\"Red\">میرخسرو (از آنندراج ).</font><br>در پرده هر آن جرعه که چون ابر کشیدی <br>یک یک ز عذار عرق افشان تو گل کرد.<br><font color=\"Red\">میرزا صائب (از آنندراج ).</font><br></font></div>'),
(182483, 'عرق افشاندن', '<span class=\"hlight\">عرق افشاندن .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ اَ دَ ]</font></b> (مص مرکب ) مرادف عرق ریختن . (آنندراج ). خوی ریختن <span class=\"hlight\">:</span> <br>عرق افشاندی از رخ آب شد دلهای مشتاقان <br>قیامت میشود چون انجم از افلاک می ریزد.<br><font color=\"Red\">میرزا صائب (از آنندراج ).</font><br></font></div>'),
(182484, 'عرق الانجبار', '<span class=\"hlight\">عرق الانجبار.</span> <font color=\"DarkGreen\"><b>[ ع ِ قُل ْ اَ ج َ ]</font></b> (ع اِ مرکب ) بیخ انجبار. (تحفه ٔ حکیم مؤمن ) (مخزن الادویه ). رجوع به انجبار شود.<br></font></div>'),
(182485, 'عرق الجبال', '<span class=\"hlight\">عرق الجبال .</span> <font color=\"DarkGreen\"><b>[ ع ِ قُل ْ ج ِ ]</font></b> (ع اِ مرکب ) قفر است .(تحفه ٔ حکیم مؤمن ). مومیایی است . (مخزن الادویه ).<br></font></div>'),
(182486, 'عرق الجبین', '<span class=\"hlight\">عرق الجبین .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ قُل ْ ج ِ ]</font></b> (ع اِ مرکب ) گویند «لقیت منه عرق الجبین » وآن مثلی است به معنی اینکه در کار او به اندازه ای رنج بردم و خسته شدم که پیشانی من عرق کرد. (از اقرب الموارد). و رجوع به ترکیب عرق جبین شود. <BR><font color=\"Blue\">◄</font> شدت سکرات موت . یا مشقت طلب حلال . (منتهی الارب ).<br></font></div>'),
(182487, 'عرق الحجر', '<span class=\"hlight\">عرق الحجر.</span> <font color=\"DarkGreen\"><b>[ ع ِ قُل ْ ح َ ج َ ]</font></b> (ع اِ مرکب ) به اصطلاح اکسیریان، مقطر موی سر انسان است . (مخزن الادویه ).<br></font></div>'),
(182488, 'عرق الذهب', '<span class=\"hlight\">عرق الذهب .</span> <font color=\"DarkGreen\"><b>[ ع ِ قُذْ ذَ هََ ]</font></b> (ع اِ مرکب ) دارپلپل . دارفلفل . فلفل دراز. (یادداشت مرحوم دهخدا). رجوع به دارفلفل و فلفل دراز شود.<br></font></div>'),
(182489, 'عرق الزبیب', '<span class=\"hlight\">عرق الزبیب .</span> <font color=\"DarkGreen\"><b>[ ع ِ قُزْ زَ ]</font></b> (ع اِ مرکب ) مویز آب است . (مخزن الادویه ).<br></font></div>'),
(182490, 'عرق الزعفران', '<span class=\"hlight\">عرق الزعفران .</span> <font color=\"DarkGreen\"><b>[ ع ِ قُزْ زَ ف َ ]</font></b> (ع اِ مرکب ) عروق الصفر است که عروق الصباغین و به فارسی زردچوبه و به هندی هلدی گویند. (مخزن الادویه ).<br></font></div>'),
(182491, 'عرق السوس', '<span class=\"hlight\">عرق السوس .</span> <font color=\"DarkGreen\"><b>[ ع ِ قُس ْ س ]</font></b> (ع اِمرکب ) اصل السوسه است . (مخزن الادویه ) (تحفه ٔ حکیم مؤمن ). ریشه ٔ شیرین بیان . رجوع به شیرین بیان شود.<br>- <span class=\"hlight\">عرق السوس البلدی </span> ؛ بَطَرة. (یادداشت مرحوم دهخدا). رجوع به بطرة شود.<br></font></div>'),
(182492, 'عرق الشجر', '<span class=\"hlight\">عرق الشجر.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ قُش ْ ش َ ج َ ]</font></b> (ع اِ مرکب ) صمغاست . (مخزن الادویه ). علک . (یادداشت مرحوم دهخدا).<br></font></div>'),
(182493, 'عرق الصباغین', '<span class=\"hlight\">عرق الصباغین .</span> <font color=\"DarkGreen\"><b>[ ع ِ قُص ْ ص َب ْ با ]</font></b> (ع اِ مرکب ) فوت الصبغ است . و گویند اسم عروق الصفر. (تحفه ٔ حکیم مؤمن ). رجوع به عرق الزعفران شود.<br></font></div>'),
(182494, 'عرق الطیب', '<span class=\"hlight\">عرق الطیب .</span> <font color=\"DarkGreen\"><b>[ ع ِ قُطْ طی ]</font></b> (ع اِ مرکب ) زرنباد است . (تحفه ٔ حکیم مؤمن ). اسرار است و زرنباد را نیز گفته اند. (مخزن الادویه ).<br></font></div>'),
(182495, 'عرق العروس', '<span class=\"hlight\">عرق العروس .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ قُل ْ ع َ ]</font></b> (ع اِ مرکب ) طلق است، که آن سنگی است براق . (از مخزن الادویه ) (از تحفه ٔ حکیم مؤمن ). کوکب الارض . رجوع به طَلق در ردیف خود شود.<br></font></div>'),
(182496, 'عرق الفالوذج', '<span class=\"hlight\">عرق الفالوذج .</span> <font color=\"DarkGreen\"><b>[ ع ِ قُل ْ ذَ ]</font></b> (ع اِ مرکب ) ابوخلسااست که به فارسی هوه جویه نامند. (مخزن الادویه ). به لغت بغداد صنف اول ابوخلسا است . (تحفه ٔ حکیم مؤمن ). هوجویه . رجوع به ابوخلسا و انخوسا و هوجویه شود.<br></font></div>'),
(182497, 'عرق المدنی', '<span class=\"hlight\">عرق المدنی .</span> <font color=\"DarkGreen\"><b>[ ع ِ قُل ْ م َ دَ ]</font></b> (ع اِ مرکب ) عرق مدنی، مرضی است . رشته . پیوک (در تداول مردم جنوب ایران ). رجوع به عرق مدنی و نیز رجوع به رشته و پیوک در ردیفهای خود شود.<br></font></div>'),
(182498, 'عرق النسا', '<span class=\"hlight\">عرق النسا.</span> <font color=\"DarkGreen\"><b>[ ع ِ قُن ْ ن َ ]</font></b> (ع اِ مرکب ) نام رگی است که از سرین تا شتالنگ آمده و علت دردی که در رگ مذکور بهم رسد آن را نیز عرق النسا گویند. وبه هندی رانگهن  نامند. (غیاث اللغات ) (آنندراج ). دردی است از دردهای مفاصل . و از مفصل و رگ آغاز شود و به جانب پشت فرودآید به بالای ران و تا زانو امتداد یابد. و بسا باشد تا قوزک پا برسد. و نسا، بفتح نون و قصر الف ؛ رگی باشد مخصوص و آن وریدی است که بر ران کشیده میشود از وحشی تا قوزک پا. پس قیاس بر آن است که بگویند «وجع نسا» لکن بر سبیل عادت به «عرق النسا» تبدیل و مستعمل گردیده است . و تقدیر کلام، درد رگی است که به نسا نامیده شده، پس اضافه ٔ عرق به نسا، بیانیه است . و نیز گویند آنچه از سرین فرودآید سوی پس شتالنگ و انگشت خرد آن را عرق النسا گویند. و نسا نام رگی است . (از کشاف اصطلاحات الفنون ) (از اقرب الموارد). صاحب منتهی الارب به نقل از الزجاج گوید، گفتن عرق النسا صحیح نیست زیرا شی ٔ به نفس خود اضافه نگردد. بیماریی که کجوک و قوین و کهنکو نیز گویند. (ناظم الاطباء). آنچه <font color=\"DarkGreen\"><b>[ درد ]</font></b> در سرین به ران فرودآید از سوی پس و تا به شتالنگ و انگشت خردک فرود آید آن را عرق النسا گویند. و نسا نام آن رگی است که از سرین تا شتالنگ و انگشت خردک فرود آمده است . (ذخیره ٔ خوارزمشاهی ). سیاتیک . رجوع به سیاتیک شود. <BR><font color=\"Blue\">◄</font> مجازاً، شرم مرد <span class=\"hlight\">:</span> <br>مرا عرق النسا آمد به جنبش .<br><font color=\"Red\">ایرج میرزا.</font><br></font></div>'),
(182499, 'عرق الکافور', '<span class=\"hlight\">عرق الکافور.</span> <font color=\"DarkGreen\"><b>[ ع ِ قُل ْ ]</font></b> (ع اِ مرکب ) زرنباد است . (تحفه ٔ حکیم مؤمن ). به لغت اهل مکه ٔ مشرفه زرنباد است . (مخزن الادویه ). رجوع به زرنباد شود.<br></font></div>'),
(182500, 'عرق انگلیسی', '<span class=\"hlight\">عرق انگلیسی .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ق ِ اِ گ ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) در اصطلاح پزشکی، ناخوشی عفونی خاصی است که با بثورات پوستی خاص پاپولی  و وزیکوکی  و با تب و لرز و تهوع و سرفه و سردرد و ترشح عرق فراوان همراه است . و به طور بومی در انگلستان و قسمتی از فرانسه وجود دارد و گاهی به صورت مرضی همه گیر درمی آید. عامل این مرض هنوز ناشناخته است و به نظر می آید که ویروسی باشد که در خاک موجود است و در افرادی که کثیف هستند و کمتر استحمام میکنند و آلودگی زیاد با خاک و گرد و غبار دارند این ویروس نشو و نما میکند و تولید ناخوشی مینماید وبیشتر در دهاتیها دیده میشود. از اختصاصات این مرض ظهور بثورات پوستی است که پس از پنج تا شش روز از شروع تب در نواحی گردن و سینه و پهلوها ظاهر میشوند و در این صورت پیش آگهی مرض خوب است و مریض روبه بهبودمیرود. و در صورت عدم ظهور بثورات نوع وخیم مرض است که احتمال بهبود مریض بسیار کم است . عرق خبیث . حمای عرق گز. تب عرق گزی . تب گزی . (فرهنگ فارسی معین ).<br></font></div>'),
(182501, 'عرق بار', '<span class=\"hlight\">عرق بار.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (نف مرکب ) عرق بارنده . آنکه عرق کرده باشد. (آنندراج ). که خوی آرد <span class=\"hlight\">:</span> <br>عید دیدار مبارک به جگر سوختگان <br>که عجب نقش از آن روی عرق بار زدند.<br><font color=\"Red\">شیخ العارفین (از آنندراج ).</font><br></font></div>'),
(182502, 'عرق بر', '<span class=\"hlight\">عرق بر.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ُ ]</font></b> (نف مرکب ) خوی بره . داروئی که عرق باز دارد. (یادداشت مرحوم دهخدا).<br></font></div>'),
(182503, 'عرق ثادق', '<span class=\"hlight\">عرق ثادق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ دِ ]</font></b> (اِخ ) یکی از دو عرق بصره است . رجوع به عرق ناهق شود.<br></font></div>'),
(182504, 'عرق جوش', '<span class=\"hlight\">عرق جوش .</span> <font color=\"DarkGreen\"><b>[ ع َرَ ]</font></b> (اِ مرکب ) نوعی جوشهای کوچک که آن را عرق گز نامند. (از فرهنگ فارسی معین ). رجوع به عرق گز شود.<br></font></div>'),
(182505, 'عرق خانه', '<span class=\"hlight\">عرق خانه .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) حمام . (آنندراج ) <span class=\"hlight\">:</span> <br>مغز عشقی که میشود در پوست <br>در عرق خانه ٔ محبت اوست .<br><font color=\"Red\">حکیم زلالی (از آنندراج ).</font><br></font></div>'),
(182506, 'عرق خبیث', '<span class=\"hlight\">عرق خبیث .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ق ِ خ َ ]</font></b> (ترکیب وصفی، اِ مرکب ) عرق انگلیسی، که نوعی مرض است . رجوع به عرق انگلیسی شود.<br></font></div>'),
(182507, 'عرق خور', '<span class=\"hlight\">عرق خور.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ ]</font></b> (نف مرکب ) عرق خورنده . آنکه عرق نوشد. (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> آنکه معتاد به عرق خوردن است . (یادداشت مرحوم دهخدا). باده نوش . می گسار. (فرهنگ فارسی معین ).<br></font></div>'),
(182508, 'عرق خوردن', '<span class=\"hlight\">عرق خوردن .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ دَ ]</font></b> (مص مرکب ) نوشیدن عرق . (فرهنگ فارسی معین ). نوشیدن باده . خوردن می <span class=\"hlight\">:</span> <br>گه عرق خوردم و گه بنگ زدم <br>تا که تریاکی و الدنگ شدم .<br><font color=\"Red\">ملک الشعراء بهار (از فرهنگ فارسی معین ).</font><br></font></div>'),
(182509, 'عرق خوری', '<span class=\"hlight\">عرق خوری .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ خوَ <span class=\"hlight\" dir=\"rtl\">/</span> خ ُ ]</font></b> (حامص مرکب ) عرق خوردن . (از فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> باده نوشی . می گساری . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> عمل عرق خور.<br>- <span class=\"hlight\">گیلاس عرق خوری </span> ؛ ظرفی شیشه ای یا بلوری یا چینی کوچک و ظریف که با آن عرق نوشند. (فرهنگ فارسی معین ). ظرف خاص برای آشامیدن عرق . (یادداشت مرحوم دهخدا).<br></font></div>'),
(182510, 'عرق دار', '<span class=\"hlight\">عرق دار.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (نف مرکب ) عرق دارنده .دارای عرق . (ناظم الاطباء). کسی که عرق کرده باشد. دارای عرق . (فرهنگ فارسی معین ). آنکه خوی کرده است . (از یادداشت مرحوم دهخدا). که بر اندام خوی آورده باشد. <BR><font color=\"Blue\">◄</font> (ق مرکب ) در حالت عرق . (ناظم الاطباء). در حال عرق داشتن . (یادداشت مرحوم دهخدا): عرق دارآب سرد نباید خورد. عرقدار آب یخ خوردن خوب نیست .<br></font></div>'),
(182511, 'عرق راندن', '<span class=\"hlight\">عرق راندن .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ دَ ]</font></b> (مص مرکب ) شرمنده شدن . (از آنندراج ). عرق ریختن . <BR><font color=\"Blue\">◄</font> سعی در کاری کردن . (از آنندراج ) <span class=\"hlight\">:</span> <br>به حیرتم که قدم سودگان دشت حجاز<br>به راه کعبه چه گرم اند در عرق رانی .<br> <font color=\"Red\">طالب آملی (از آنندراج ).</font><br>عرق ریختن . رجوع به عرق ریختن شود.<br></font></div>'),
(182512, 'عرق ریختن', '<span class=\"hlight\">عرق ریختن .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ت َ ]</font></b> (مص مرکب ) بسیار خوی کردن . (یادداشت مرحوم دهخدا). خوی از چهره چکیدن . <BR><font color=\"Blue\">◄</font> شرمنده شدن . (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> <br>عشق میریزد عرق چون دل شود صید هوس <br>هر که میمیرد طبیبش میکشد شرمندگی .<br> <font color=\"Red\">ناظم هروی (از آنندراج ).</font><br> <BR><font color=\"Blue\">◄</font> سعی در کاری کردن . (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> <br>از پی شادابی معنی عرقها ریختم <br>فیضها ده در زمین شعر باران مرا.<br><font color=\"Red\">رائج (از آنندراج ).</font><br></font></div>'),
(182513, 'عرق ریز', '<span class=\"hlight\">عرق ریز.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (نف مرکب ) عرق ریزنده . کسی که از بدن او عرق بریزد. (آنندراج ). که خوی از اندامش برود. به معنی عرق افشان . (از آنندراج ) <span class=\"hlight\">:</span> <br>شد آن فصل کز جوش بازار گل <br>عرق ریز گردد خریدار گل .<br> <font color=\"Red\">ملاطغرا (از آنندراج ).</font><br>از مسامات بدن خوی بسته می ریزد کنون <br>پیکر مرد عرق ریز است ابر برف بار.<br> <font color=\"Red\">محمد سعید اشرف (از آنندراج ).</font><br>از عرق ریز خیال شعله ٔ طبعم زند<br>طعنه بر فواره ٔ آتش مسام زمهریر.<br> <font color=\"Red\">طالب آملی (از آنندراج ).</font><br> <BR><font color=\"Blue\">◄</font> (اِ مرکب ) جائی که عرق چیزی در آنجا بکشند. (آنندراج ). جای ریختن عرق <span class=\"hlight\">:</span> <br>از آن گل که اوتازه دارد نفس <br>عرق ریز او در عراق است و بس .<br> <font color=\"Red\">خواجه نظامی (از آنندراج ).</font><br> <BR><font color=\"Blue\">◄</font> (نف مرکب ) خادم . (غیاث اللغات ). خادم و شاگرد و ورزش کننده و اهل بخیه . (آنندراج ) <span class=\"hlight\">:</span> <br>زخم امر تو به جان و دل راندن کاریست <br>تا عرق ریز تو و حکم تو بر ما جاریست .<br> <font color=\"Red\">میرنجات (از آنندراج ).</font><br> <BR><font color=\"Blue\">◄</font> خجلت دهنده . (غیاث اللغات ). شرمنده <span class=\"hlight\">:</span> <br>رخی چون تازه گلهای دلاویز<br>گلاب از شرم آن گلها عرق ریز.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(182514, 'عرق ریزان', '<span class=\"hlight\">عرق ریزان .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ق مرکب ) خوی ریزان . در حال عرق ریختن . در حال خوی ریختن . (یادداشت مرحوم دهخدا).<br></font></div>'),
(182515, 'عرق زدن', '<span class=\"hlight\">عرق زدن .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ زَ دَ]</font></b> (مص مرکب ) عرق گل یا گلاب به خود زدن <span class=\"hlight\">:</span> <br>تو خود به کمال و لطف آراسته ای <br>پیرایه مکن عرق مزن عود مسوز.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(182516, 'عرق سوز', '<span class=\"hlight\">عرق سوز.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِ مرکب ) سرخی یا بثوری که در تابستان بعلت کثرت خوی و عرق بر بشره پدید آید. (از یادداشتهای مرحوم دهخدا). خشک رنده .<br>- <span class=\"hlight\">عرق سوز شدن </span> ؛ پیدا شدن سوزه ها یعنی بثوری از کثرت خوی بر پوست، بر اثر گرما. (از یادداشتهای مرحوم دهخدا).<br></font></div>'),
(182517, 'عرق سوزه', '<span class=\"hlight\">عرق سوزه .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (اِ مرکب )جوش خرد سرخ که از اثر خوی بر اندام بادید شود. (یادداشت مرحوم دهخدا). عرق سوز. رجوع به عرق سوز شود.<br></font></div>'),
(182518, 'عرق فروش', '<span class=\"hlight\">عرق فروش .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ف ُ ]</font></b> (نف مرکب ) عرق فروشنده . آنکه عرق و مشروبات دیگر فروشد. (فرهنگ فارسی معین ).<br></font></div>'),
(182519, 'عرق فروشی', '<span class=\"hlight\">عرق فروشی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ف ُ ]</font></b> (حامص مرکب ) عمل و شغل عرق فروش . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> (اِ مرکب ) دکان و مغازه ٔ عرق فروش . (فرهنگ فارسی معین ).<br></font></div>'),
(182520, 'عرق مدنی', '<span class=\"hlight\">عرق مدنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ م َ دَ ]</font></b> (ترکیب وصفی، اِ مرکب ) نام بیماریی است که به فارسی آن را رشته نامند و به هندی نارو گویند. (آنندراج ) (غیاث اللغات ). آن است که بر بدن آدمی دانه ای تولید و سپس بصورت تاولی گردد، و آبی در زیر پوست جمع شود. آنگاه تاول بترکد و از میانه ٔ آن شیئی مانند رگی بیرون آید واندک اندک آن دراز شود. و بسا باشد که آن رگ را در زیر پوست جنبشی نمودار گردد شبیه به جنبش کرم . قرشی گوید: و این شی ٔ رگ حقیقی نیست بلکه حیوانی است که در بدن تولید میگردد مانند دیگر کرمها که در بدن آدمی تولید میشوند. فارسی آن بیماری رشته است . (از کشاف اصطلاحات الفنون ). کرمی است مانند قیطان که زیرپوست وروی عضلات در مواضعی که عصب زیادتر است تولید شود. وطول آن گاهی به <span class=\"hlight\" dir=\"rtl\">٥٧</span> سانتیمتر میرسد. سلمانیها و قصابان محلی (سواحل جنوب ایران ) مهارت دارند که آن را بدون پاره شدن کرم از زیرپوست خارج کنند. بدین ترتیب که وقتی از محلی که سر این کرم در زیر پوست واقع است، روی پوست جوش یا تاولی ایجاد شود، آن جوش یا تاول را شکافند و سر کرم را از روی پوست به اندازه ٔ یکی دوسانتیمتر خارج کنند و آن را در چوب کبریتی پیچیده وچوب کبریت را بهمان حالی که کرم دور آن پیچیده شده روی زخم گذارند تا روز بعد مجدداً آن را باز کنند و چند سانتیمتر از آن را بیرون کشند، و باز دور همان چوب کبریت پیچند و رها کنند. این عمل چند روز تکرار شود تا بتدریج همه ٔ کرم از زیرپوست خارج شود. اگر در حین عمل یا بی دقتی مریض، کرم که قسمتی از آن خارج شده، پاره شود و سر پارگی آن زیر پوست باشد بعلت ترشحاتی که از بدن کرم زیر پوست خارج گردد، محل کرم باد کند و بسیار دردآور و خطرناک باشد. این کرم در بدن ساکنان بنادر جنوب ایران مخصوصاً اطراف لارستان و بندر لنگه و بندرعباس شیوع دارد. (فرهنگ فارسی معین ). عرق مدنی . رشته . دوده ٔ مدنیه . پیو. پیوک . نارو. فرتیت . فرنتیت . و رجوع به پیو و رشته در ردیفهای خود شود.<br></font></div>'),
(182521, 'عرق مدینی', '<span class=\"hlight\">عرق مدینی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ م َ ]</font></b> (ترکیب وصفی، اِ مرکب ) رشته . (مهذب الاسماء). پیوک . عرق مدنی . رجوع به عرق مدنی شود.<br></font></div>'),
(182522, 'عرق ناهق', '<span class=\"hlight\">عرق ناهق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ هَِ ]</font></b> (اِخ ) در بصره دو «عرق » و زمین اختصاص به شتران سلطان و به در راه ماندگان داشت و آن دو عرق ناهق و عرق ثادق بوده اند. اما عرق ناهق در قرق اهل بصره بود. و هر یک از اهالی بصره که قصد حج میکرد شتران خود را به این «عرق » می سپرد تا فصل حج فرارسد. (از معجم البلدان ).<br></font></div>'),
(182523, 'عرق پوش', '<span class=\"hlight\">عرق پوش .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ن مف مرکب ) پوشیده از عرق . پوشیده از خوی . آلوده به عرق <span class=\"hlight\">:</span> <br>شبنم غصه تراود ز رگ و ریشه ٔ گل <br>صبح از نشئه ٔ می چهره عرق پوش مکن .<br><font color=\"Red\">علی خراسانی (از آنندراج ).</font><br></font></div>'),
(182524, 'عرق چین', '<span class=\"hlight\">عرق چین .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (نف مرکب، اِ مرکب ) عرقچین . عرق چیننده . آنچه عرق و خوی را جمع کند. که جذب عرق کند <span class=\"hlight\">:</span> <br>ز تاب آتش دوری شدم غرق عرق چون گل <br>بیار ای باد شبگیری نسیمی زان عرق چینم .<br> <font color=\"Red\">حافظ.</font><br> <BR><font color=\"Blue\">◄</font> نوعی از کلاه است و آن را توبی نیز گویند. (برهان ). نوعی از کلاه که در زیر دستار پوشند. (غیاث اللغات ). در قوسی طاقه که زیرکلاه و دستار پوشند. (آنندراج ). نوعی از کلاه نازک که نوعاً در زیر کلاه بر سر گذارند. (ناظم الاطباء). نوعی کلاه از پارچه یا منسوج نازک که در زیر کلاه یا عمامه و رکن گذارند و یا به تنهایی در خانه به سر نهند. (فرهنگ فارسی معین ). کلاهی از جامه ٔ تنک که پیش از این کسبه و آخوندها زیر کلاه یا عمامه می پوشیدند. (یادداشت مرحوم دهخدا). عرقیة. عراقیة. طاقیة. شب کلاه . کله پوش . نوعی کلاه بی لبه از پارچه ٔ نازک یا بافته که فقط قسمتی از فرق سر را پوشاند <span class=\"hlight\">:</span> <br>زهی دولت زهی طالع زهی بخت <br>که شب پوش و عرقچین تو دارد.<br> <font color=\"Red\">عبید (از آنندراج ).</font><br>منه واعظ دگر زینگونه دستار کلان بر سر<br>که آخر چون عرقچین در ته دستار میمانی .<br> <font color=\"Red\">ملاطغرا (از آنندراج ).</font><br>عرقچین نمی دوزد آن گلعذار<br>که شاخ گلش می فشاند به بار.<br> <font color=\"Red\">میرزاطاهر وحید (از آنندراج ).</font><br>کلاه و عرقچین و مسحی و موزه <br>چو ارواح بگزیده دوری ز قالب .<br> <font color=\"Red\">نظام قاری .</font><br>ز بهر عرقچین واعظ از این پیش <br>شدندی برهنه سران جمله تائب .<br> <font color=\"Red\">نظام قاری .</font><br>صد عرقچین فدای طاقیه باد<br>هیچ از قالبش نیاید یاد.<br> <font color=\"Red\">نظام قاری (دیوان البسه ص <span class=\"hlight\" dir=\"rtl\">٥٥</span>).</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">سر کچل وعرقچین </span> !؛ نظیر وسمه بر ابروی کور. (امثال و حکم دهخدا).<br><BR><font color=\"Blue\">◄</font> قطیفه و هر چیز که بدان عرق پاک کنند. (برهان ) (ناظم الاطباء). رومال . (آنندراج ) (غیاث اللغات ).<br></font></div>'),
(182525, 'عرق کردن', '<span class=\"hlight\">عرق کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ک َ دَ ]</font></b> (مص مرکب ) عرق برآوردن . (آنندراج ). خوی کردن . (ناظم الاطباء). بیرون آمدن عرق از بدن . (فرهنگ فارسی معین ).خوی آوردن . استحمام . تعریق . ترشح کردن <span class=\"hlight\">:</span> <br>آن خواجه که سعی حرص آرامش برد<br>گردید زبان بخیل اگر نامش برد<br>دانست دو معنی است عرق کردن  را<br>نتوان به صد ابرام به حمامش برد.<br> <font color=\"Red\">(از آنندراج ).</font><br>- <span class=\"hlight\">پشت لب کسی تازه عرق کردن </span>؛ تعدادی کم بر پشت لب کسی موی برآمدن . کمی تازه بروت دمیدن . (از یادداشتهای مرحوم دهخدا).<br> <BR><font color=\"Blue\">◄</font> کنایه از چیزی دادن باشد. (برهان قاطع) (از انجمن آرا) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> پرداخت پول و مال با اکراه . (فرهنگ فارسی معین ). عطا دادن مردی بخیل به کره . چیزی بخشیدن مردی ممسک . (یادداشتهای مرحوم دهخدا). هر گاه ممسکی به کسی چیزی میدهد البته به جوش می آید، در آن مقام گویند امروز فلانی عرق کرد. (آنندراج ). بعلت زفتی با رنج و تعبی تمام چیز کمی به کسی دادن . (امثال و حکم دهخدا). به بی میلی چیزی به کسی دادن . وقتی خسیسی تحت تأثیر فشار و اجبار چیزی به کسی دهد، این اصطلاح مثلی در مورد او ایراد میشود. مثلا\" گویند: سرانجام تحت تأثیر فشار و با کمال اکراه اعانه ای را که از او خواسته بودند عرق کرد و پرداخت . (از فرهنگ عوام ) <span class=\"hlight\">:</span> <br>شبی به مجلس میراردشیر دررفتم <br>به بنده بود یکی قطعه بهتر از طبقی <br>از او شراب طلب داشتم من بیمار<br>تبش گرفت و نکرد از فسردگی عرقی .<br> <font color=\"Red\">کاتبی (از امثال و حکم دهخدا).</font><br> <BR><font color=\"Blue\">◄</font> کنایه از رشوه دادن . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> خجالت کشیدن . (آنندراج ) (غیاث اللغات ). خجل شدن .(انجمن آرا). کنایه است از خجل شدن و خجالت کشیدن . (برهان ) (از ناظم الاطباء) (از فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>فهمیدن قباحتم آزار می کند<br>تا چند کی زجانب مردم عرق کنم .<br> <font color=\"Red\">نورالدین ظهوری (از آنندراج ).</font><br>نه چهره اش عرق از گرمی هوا کرده ست <br>نگاه را رخ او آب از حیا کرده ست .<br> <font color=\"Red\">میرزا صائب (از آنندراج ).</font><br>گهر ز شرم عرق می کند به بازارش <br>چگونه آب نگردد دل خریدارش .<br> <font color=\"Red\">میرزا صائب (از آنندراج ).</font><br><BR><font color=\"Blue\">◄</font> در اصطلاح لوطیان، تب کردن . (از آنندراج ). <BR><font color=\"Blue\">◄</font> در اصطلاح لوطیان، تقلید کردن . (از آنندراج ). <BR><font color=\"Blue\">◄</font> مرادف عرق چکیدن . (آنندراج ).<br></font></div>'),
(182526, 'عرق کرده', '<span class=\"hlight\">عرق کرده .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) آن که عرق از بدنش جاری شده باشد. خوی کرده . (فرهنگ فارسی معین ). خوی آورده <span class=\"hlight\">:</span> <br>ژاله بر لاله فرود آمده هنگام سحر<br>راست چون عارض گلگون عرق کرده ٔ یار.<br> <font color=\"Red\">سعدی .</font><br>نشست از خجالت عرق کرده روی <br>که آیا خجل گشتم از شیخ کوی .<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> کنایه از اسبی باشد که او را به کثرت سواری چنان کرده باشند که از دوانیدن و تردد فرمودن بسیار، عرق بر بدن او ننشیند ونفسش تنگ نشود. (برهان ). اسبی که او را به کثرت سواری چنان استعمال کرده باشند که از دوانیدن و تردد نمودن بسیار عرق بر بدنش ننشیند و نفسش تنگ نشود. (آنندراج ).<br></font></div>'),
(182527, 'عرق کش', '<span class=\"hlight\">عرق کش .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب ) عرق کشنده . آنکه عرق گیرد. آنکه عرق کشمش کشد. (یادداشتهای مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> آنکه عرق گل و بیدمشک و کاسنی و شاهتره و امثال آن با قرع و انبیق کشد. (یادداشت مرحوم دهخدا).<br></font></div>'),
(182528, 'عرق کشی', '<span class=\"hlight\">عرق کشی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (حامص مرکب ) عمل عرق کش . رجوع به عرق شود. <BR><font color=\"Blue\">◄</font> (اِمرکب ) جای عرق کشیدن . محلی که در آنجا عرق گیرند.<br></font></div>'),
(182529, 'عرق کشیدن', '<span class=\"hlight\">عرق کشیدن .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ ]</font></b> (مص مرکب ) عرق گرفتن .<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(182530, 'عرق گرفتن', '<span class=\"hlight\">عرق گرفتن .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ گ ِ رِ ت َ ]</font></b> (مص مرکب ) با قرع و انبیق، عطر یا جوهر گیاهی را گرفتن، چنانکه از بیدمشک و کاسنی و شاه تره و غیره . <BR><font color=\"Blue\">◄</font> مرادف عرق چکیدن . (آنندراج ) <span class=\"hlight\">:</span> <br>چون عرق گیرد تو گویی سیل در وادیستی <br>چون سبق جوید تو گویی باد در صحراستی .<br><font color=\"Red\">میرمعزی (در تعریف اسب، از آنندراج ).</font><br></font></div>'),
(182531, 'عرق گز', '<span class=\"hlight\">عرق گز.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ گ َ ]</font></b> (اِ مرکب ) در اصطلاح پزشکی، جوشهای کوچکی که بر اثر ترشح زیاد عرق بر سطح پوست عارض میشوند. عرق جوش . (از فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عرق گز شدن </span> ؛ بر اثر خوی کردن، بثورات خرد در تن پیدا آمدن .<br></font></div>'),
(182532, 'عرق گزی', '<span class=\"hlight\">عرق گزی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ گ َ ]</font></b> (ص نسبی ) (تب ...) عرق انگلیسی . (فرهنگ فارسی معین ). رجوع به عرق انگلیسی شود.<br></font></div>'),
(182533, 'عرق گیر', '<span class=\"hlight\">عرق گیر.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (نف مرکب ) عرق گیرنده . آنکه عرق نباتات معطر یا دوائی به تقطیر گیرد، چون عرق بیدمشک و عرق کاسنی و عرق بید، یا گلاب از گل و جز آن . (یادداشت مرحوم دهخدا). کسی که عرق از چیزی میگیرد. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آنکه عرق شراب و الکل کشد. <BR><font color=\"Blue\">◄</font> آنکه عصاره ٔ میوه ها را گیرد. عصار. (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> کنایه از شرمنده و منفعل . (آنندراج ). کنایه از خجل و شرمنده . (برهان ). <BR><font color=\"Blue\">◄</font> عرق آلود. (آنندراج ) <span class=\"hlight\">:</span> <br>بینی رخ اختران ز تشویر<br>از فر عراقیان عرق گیر.<br> <font color=\"Red\">خاقانی (از آنندراج ).</font><br><BR><font color=\"Blue\">◄</font> (اِ مرکب ) پارچه ای که بدان عرق از بدن پاک سازند. (برهان قاطع). جامه ای که بدان عرق از بدن پاک کنند. دستمال . رومال . (از فرهنگ فارسی معین ) (ناظم الاطباء). عرقیه . (آنندراج ). عرقچین . <BR><font color=\"Blue\">◄</font> جامه ای که بر پشت اسب در زیر زین اندازند. (ناظم الاطباء). جامه که بر اسب پوشند آنگاه که عرق کرده است . جامه که برای خشک کردن عرق اسب بر او پوشند. جامه ای که بر پشت اسب افکنند برچیدن عرق را. آنچه بر اسب پوشند آنگاه که متوقف گردد پس رفتن بسیار و عرق کردن . جامه ای که اسب را پوشند که پس از عرق کردن سقو نکند. خوی گیر. خوی چین . لبد. غما. قُرطان . مِرشَح . مرشحة. (از یادداشتهای مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> نمد زین، پارچه یا نمد که زیر زین نهندکه بهنگام حرکت اسب چون خوی کند، چیده شود و مانع نفوذ هوا و بروز سرما شود. <BR><font color=\"Blue\">◄</font> آن جامه که آن را عرقچین میگویند. (آنندراج ). کلاهکی از پارچه به شکل نیم کره . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> جامه ای نازک که برای خشک کردن عرق بدن پوشند. زیرپیراهنی . (فرهنگ فارسی معین ).<br></font></div>'),
(182534, 'عرق گیری', '<span class=\"hlight\">عرق گیری .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (حامص مرکب ) کار عرق گیر. رجوع به عرق گیر شود. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) محل و جای گرفتن عرق . جایی که عرق میگیرند. رجوع به عرق و عرق گیر شود.<br></font></div>'),
(182535, 'عرق یابس', '<span class=\"hlight\">عرق یابس .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ق ِ ب ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) قلفونیا است، که به فارسی زنگباری نامند. (مخزن الادویه ).<br></font></div>'),
(182536, 'عرقا', '<span class=\"hlight\">عرقا.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) نام قصبه ای در حوالی دمشق . (ناظم الاطباء). ظاهراً همان عِرقة است . رجوع به عِرقة شود.<br></font></div>'),
(182537, 'عرقات', '<span class=\"hlight\">عرقات .</span><font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) چوب نخستین دلو. (منتهی الارب ) (ناظم الاطباء). عرقاة. رجوع به عرقاة شود. <BR><font color=\"Blue\">◄</font> ج ِ عَرَقة. (منتهی الارب ). رجوع به عرقة شود. <BR><font color=\"Blue\">◄</font> ج ِ عَرَق . (ناظم الاطباء). رجوع به عرق شود.<br></font></div>'),
(182538, 'عرقال', '<span class=\"hlight\">عرقال .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) مرد کج رو که به راه مستقیم نیاید و ثبات نورزد. (منتهی الارب ). آنکه بر رشد و راه راست خود، مستقیم نگردد. (از اقرب الموارد).<br></font></div>'),
(182539, 'عرقان', '<span class=\"hlight\">عرقان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) جائی است . (منتهی الارب ). منظور دو عرق بصره است که عرق ناهق و عرق ثادق می باشد. (از معجم البلدان ). رجوع به عرق ناهق شود.<br></font></div>'),
(182540, 'عرقان', '<span class=\"hlight\">عرقان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) عرق دار و خوی دار. (ناظم الاطباء). آنکه پوستش ترشح کرده باشد. (از اقرب الموارد). رجوع به عَرَق (مص ) شود.<br></font></div>'),
(182541, 'عرقبة', '<span class=\"hlight\">عرقبة.</span><font color=\"DarkGreen\"><b>[ ع َ ق َ ب َ ]</font></b> (ع مص ) پی پاشنه بریدن تا بیفتد. (منتهی الارب ). عرقوب ستور را بریدن تا بیفتد. (از ناظم الاطباء). عرقب الدابة؛ عرقوب دابه را قطع کرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> برداشتن هر دو پاشنه را تا ایستاده گردد. (منتهی الارب ). برداشتن هر دو عرقوب ستور را تا ایستاده گردد. (از ناظم الاطباء). عرقب الدابة؛ دو عرقوب دابه را بالا برد تا بایستد، از اضداداست . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> حیله نمودن . (منتهی الارب ) (از ناظم الاطباء) (از اقرب الموارد).<br></font></div>'),
(182542, 'عرقبة', '<span class=\"hlight\">عرقبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ب َ ]</font></b> (اِخ ) جایگاهی است و نام آن در اخبار آمده است . (از معجم البلدان ).<br></font></div>'),
(182543, 'عرقد', '<span class=\"hlight\">عرقد.</span><font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِ) گیاهی است از تیره ٔ بادنجانیان جزو دسته ٔ شابیزک ها. دارای برگهای کامل . گلهایش برنگهای سفید و بنفش کم رنگ و قرمز و صورتی و زرد دیده میشود. در حدود هفتاد نوع از این گیاه شناخته شده که همگی در نواحی معتدل و گرم میرویند. دیو خار. عوسج . حضض .فیل زهرج . فیل زهره . آسه . (از فرهنگ فارسی معین ).<br></font></div>'),
(182544, 'عرقص', '<span class=\"hlight\">عرقص .</span> <font color=\"DarkGreen\"><b>[ع ُ ق ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ رَ ق ِ ]</font></b> (ع اِ) گیاهی است . و گویند همان حندقوق است . یکدانه ٔ آن عرقصة. (از ذیل اقرب الموارد از لسان ). عَرنقَص . عرقصاء. رجوع به عرقصاء شود.<br></font></div>'),
(182545, 'عرقصاء', '<span class=\"hlight\">عرقصاء.</span> <font color=\"DarkGreen\"><b>[ ع ُ ق ُ ]</font></b> (ع اِ) ذرق یا یربطو، و آن گیاهی است که ساقش مانند ساق رازیانه باشد و دسته ٔ کلان و انبوه، عظیم النفع در جمیع اقسام وبا و درد دندان کرم خورده و گوش و سپرز و دردسر کهنه و نزله و جز آن . (منتهی الارب ). حندقوقی یا یربطو است و آن همان ذرق باشد. گویند آن نباتی است که ساقه هایش به ساق رازیانه میماند. و یک دسته ٔ آن بسیار و انبوه است، و در جمیع انواع وبا و درد دندان کرم خورده، به وسیله ٔ غرغره کردن با آبی که این گیاه در آن جوشانده شده است، و نیز برای درد گوش و طحال و صداع مزمن و نزله ها و غیره بسیار سودمند است . (از تاج العروس ). حندقوقی، واحد آن عرقصاءة. (از اقرب الموارد). نام گیاهی مانند رازیانه که در طب استعمال می کنند. (ناظم الاطباء). اسم حندقوقی است، یا یربطوره است . (مخزن الادویه ). عَرقَصان . عَرَنقصان . عُریقِصاء.عُریقِصانة. رجوع به عرقصان و عرنقصان و عریقصاء و عریقصانة شود.<br></font></div>'),
(182546, 'عرقصان', '<span class=\"hlight\">عرقصان .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) عرقصاء، که گیاهی است . (از منتهی الارب ) (از اقرب الموارد). اسم حندقوقی است یابربطور است . (مخزن الادویه ). رجوع به عرقصاء شود.<br></font></div>'),
(182547, 'عرقطو', '<span class=\"hlight\">عرقطو.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی از دهستان آتش بیک، بخش سراسکند، شهرستان تبریز. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٥٥٦</span> تن . آب آن از چشمه و رودخانه و محصول آن غلات وحبوب و پنبه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(182548, 'عرقطی', '<span class=\"hlight\">عرقطی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق ُ طی ی ]</font></b> (ص نسبی ) منسوب به عرقطة، که نام جدی است . (از الانساب سمعانی ).<br></font></div>'),
(182549, 'عرقل', '<span class=\"hlight\">عرقل .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) ابن خطیم . مردی است . (منتهی الارب ). شاعری است مشهور از عرقلة. (از تاج العروس ).<br></font></div>'),
(182550, 'عرقلة', '<span class=\"hlight\">عرقلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ل َ ]</font></b> (ع مص ) میل کردن از توسط. (از منتهی الارب ). جور کردن به طور قصد و میل کردن از توسط. (از ناظم الاطباء). دور شدن از قصد وعدل . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> راست نگفتن سخن را. (از منتهی الارب ). عرقل علیه کلامه ؛ سخن خود رابر او کج کرد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> کج نمودن بر کسی کار و سخن را. (از منتهی الارب ). عرقل علی فلان ؛ کردار و سخن را بر فلان کج کرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دائر نمودن بر کسی کلام غیرمستقیم را. (از منتهی الارب ). وادار کردن کسی را بر لازم داشتن کلامی غیر مستقیم و نادرست را. (از اقرب الموارد).<br></font></div>'),
(182551, 'عرقلی', '<span class=\"hlight\">عرقلی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ لا ]</font></b> (ع اِمص ) خرامش و رفتار به تکبر. (منتهی الارب ). راه رفتنی که در آن تبختر و به خود بالیدن باشد. (از اقرب الموارد).<br></font></div>'),
(182552, 'عرقناک', '<span class=\"hlight\">عرقناک .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ص مرکب ) دارای عرق و پوشیده از عرق . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>مرا افکنده رخسار عرقناکش به دریائی <br>که دارد هر حبابش در گره طوفان خودرائی .<br> <font color=\"Red\">میرزا صائب (از آنندراج ).</font><br>چون عرقناک شود روی تو از گرمی مل <br>شیشه ها از عرق فتنه توان پر کردن .<br> <font color=\"Red\">میرزا جلال اسیر (از آنندراج ).</font><br>أرش الفرس ؛ عرقناک گردانیدن اسب را بدوانیدن . (منتهی الارب ).<br>- <span class=\"hlight\">عرقناک بودن </span> ؛ ازعرق پوشیده بودن . (ناظم الاطباء).<br></font></div>'),
(182553, 'عرقه', '<span class=\"hlight\">عرقه .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ]</font></b> (ص ) در اصطلاح عامه ٔ مردم، آدم ناقلا و بدجنس و زرنگ . (فرهنگ لغات عامیانه ). ارقه . (فرهنگ فارسی معین ). رجوع به ارقه شود.<br></font></div>'),
(182554, 'عرقوب', '<span class=\"hlight\">عرقوب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) پی سطبر پاشنه ٔ مردم . (منتهی الارب ). پی پاشنه . (دهار).پی ستبر در بالای پاشنه ٔ آدمی . (ناظم الاطباء). عصبی است غلیظ و موتّر در بالای عقب و پاشنه ٔ انسان . (از اقرب الموارد). عصب ضخیم بالای پاشنه ٔ پا. (فرهنگ فارسی معین ). ج، عَراقیب . (اقرب الموارد) (ناظم الاطباء).و در مثل گویند: شرما أجأک الی مخّة العرقوب، که منظور پی پا است زیرا آن را مخ و مغز نباشد. و این مثل را در حق شخصی گویند که از لئیم چیزی بخواهد. (ازمنتهی الارب ) (از اقرب الموارد) (از ناظم الاطباء).<br>- <span class=\"hlight\">عرقوب الدابة</span> ؛ پی پای ستور، و گویند دو عرقوب هر چارپایی در پایش است و دو رکبه ٔ او در دستهایش . (از منتهی الارب ). عرقوب در پای دابة، بمنزله ٔ رکبه و زانوی اوست در دست، یعنی بین محل اتصال وظیف و ساق . (از اقرب الموارد).<br>- <span class=\"hlight\">عرقوب القطا</span> ؛ ساق آن . (منتهی الارب ) (از اقرب الموارد). ساق مرغ سنگخوارک . (ناظم الاطباء). گویند: یوم أقصر من عرقوب القطا؛ یعنی روزی کوتاه تر از ساق قطا، زیرا ساق او را در کوتاهی مثل زنند. (از ذیل اقرب الموارد) (از لسان ).<br><BR><font color=\"Blue\">◄</font> خم رودبار. (منتهی الارب ). خم وادی . (ناظم الاطباء). منحنی و پیچ وادی . گویند: نزلنا فی عرقوب الوادی ؛ یعنی در خم و پیچ وادی فرود آمدیم . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> راهی است در کوه . (منتهی الارب ). طریقی است در جبل . (از اقرب الموارد). عرقوب الجبل ؛ دماغه ٔ کوه و راه تنگ در روی کوه . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> حیله . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شناخت حجت . (منتهی الارب ). شناختن و عرفان حجت و دلیل . (از اقرب الموارد). گویند: أخذ عرقوبه ؛ یعنی شناخت حجت او را. <BR><font color=\"Blue\">◄</font> امور مشکله و عظیمه . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِخ ) اسبی است . (منتهی الارب ).<br></font></div>'),
(182555, 'عرقوب', '<span class=\"hlight\">عرقوب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) (یوم الَ ...) از ایام و جنگهای عرب است . (از معجم البلدان ).<br></font></div>'),
(182556, 'عرقوب', '<span class=\"hlight\">عرقوب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ابن صخر، یا عرقوب بن معبدبن اسد. ازعمالقه است و او کاذب ترین مردم زمان خود بود و در اِخلاف وعده بدو مثل زنند. (از منتهی الارب ). از اعراب جاهلی بود و در خلف وعده به وی مثل زنند. نسب او را ابن سعدبن زید مناةبن تمیم گفته اند. و برخی وی را ازاوس و خزرج دانند. و بعضی او را از اهالی خیبر یا مدینه دانسته اند. درباره ٔ خلف وعده ٔ وی اخبار بسیاری نقل کرده اند از جمله گویند به برادرش وعده ٔ «طلع» نخلی را داد و چون طلع گشت، از او خواست صبر کند تا «بلح » گردد و هنگامی که بلح شد گفت منتظر باش تا «رطب »شود و سرانجام چون رطب گشت خود آن را چید و به برادر چیزی نداد. کعب بن زهیر در حق وی گوید <span class=\"hlight\">:</span> <br>کانت مواعید عرقوب لها مثلاً<br>و ما مواعیدها الا الاباطیل .<br> <font color=\"Red\">(از الاعلام زرکلی از الشریشی و ثمار القلوب و مجمعالامثال ).</font><br>جبیها اًلاشجعی گوید <span class=\"hlight\">:</span> <br>وَعَدْت َ وکان الخلف منک سجیة<br>مواعید عرقوب أخاه بیترب .<br> <font color=\"Red\">(از منتهی الارب ).</font><br>- <span class=\"hlight\">مواعید عرقوب </span> ؛ وعده های عرقوب . اشاره است به عرقوب که در خلف وعده مشهور بود <span class=\"hlight\">:</span> او در آن باب به قولی مکذوب و مواعید عرقوب نوح را معزور می داشت . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٨٨</span>).<br></font></div>'),
(182557, 'عرقوب الاسد', '<span class=\"hlight\">عرقوب الاسد.</span> <font color=\"DarkGreen\"><b>[ ع ُ بُل ْ اَ س َ ]</font></b> (اِخ ) بقار. برد. صیاح . عوا. عواء. (یادداشت مرحوم دهخدا). صورتی است از فلک . رجوع به عواء و بقار شود.<br></font></div>'),
(182558, 'عرقوب الرامی', '<span class=\"hlight\">عرقوب الرامی .</span> <font color=\"DarkGreen\"><b>[ ع ُ بُرْ را ]</font></b> (اِخ ) کوکبی است . (از اقرب الموارد). ستاره ای که پس از رکبةالرامی در صورت قوس از دیگر ستارگان روشن تر است و بر خرده گاه دست اسب واقع است . (یادداشت مرحوم دهخدا).<br></font></div>'),
(182559, 'عرقوبی', '<span class=\"hlight\">عرقوبی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ص نسبی ) منسوب به عرقوب . رجوع به عرقوب (اِخ ) شود.<br>- <span class=\"hlight\">وعده یا مواعید عرقوبی </span> ؛ نوید دروغین <span class=\"hlight\">:</span> ایشان را به مواعید عرقوبی مستظهر گردانید. (جهانگشای جوینی ). و به مواعید عرقوبی سلطان را مغرور کرد. (جهانگشای جوینی ).<br></font></div>'),
(182560, 'عرقوتان', '<span class=\"hlight\">عرقوتان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق ُ وَ ]</font></b> (ع اِ) تثنیه ٔ عرقوة. رجوع به عرقوة شود. <BR><font color=\"Blue\">◄</font> دو چوب بر پهنای دلو نهاده مانند صلیب . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دو چوب با هم منضم در مابین واسط رحل و مؤخر آن . (منتهی الارب ). دو چوب که پیوسته میگردند مابین اواسط رحل و مؤخرة. (از اقرب الموارد). ج، عَراقی . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(182561, 'عرقون', '<span class=\"hlight\">عرقون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b>(اِ) نباتی است که برگ آن شبیه به برگ شقایق النعمان است و شکافته و طولانی . و بیخ آن مستدیر و آن را میخورند. و صنف دیگر نیز می شود و شاخه های آن باریک و برگ آن شبیه به برگ ملوخیاء، و در اطراف شاخه های آن چیزی برآمده شبیه به سر مرغی و منقار آن . و این در طب غیر ممد و بلکه در صناعت دیگر است . (مخزن الادویه ).<br></font></div>'),
(182562, 'عرقچین دوز', '<span class=\"hlight\">عرقچین دوز.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (نف مرکب ) عرقچین دوزنده . دوزنده ٔ عرقچین . آنکه حرفه ٔ او دوختن عرقچین و شبکلاه باشد. رجوع به عرقچین شود.<br></font></div>'),
(182563, 'عرقچین دوزی', '<span class=\"hlight\">عرقچین دوزی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ]</font></b> (حامص مرکب ) شغل و حرفه ٔ عرقچین دوز. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) محل دوختن عرقچین . رجوع به عرقچین شود.<br></font></div>'),
(182564, 'عرقی', '<span class=\"hlight\">عرقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ قی ی ]</font></b> (ص نسبی ) منسوب است به عِرقة که آن شهرکی است در مشرق طرابلس شام . وجماعتی از بزرگان بدانجا منسوبند. (از اللباب فی تهذیب الانساب ) (از معجم البلدان ). رجوع به عرقة شود.<br></font></div>'),
(182565, 'عرقی', '<span class=\"hlight\">عرقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) لقب محمدبن حمزةبن احمد عرقی، مکنی بابوالبرکات است . وی محدث بود و به سال <span class=\"hlight\" dir=\"rtl\">٤٦٥</span> هَ . ق . در مصر متولد شد و حدیث را نزد خلعی و ابن ابی داود سلفی، و لغت را نزد ابن قطاع آموخت . او به سال <span class=\"hlight\" dir=\"rtl\">٥٥٧</span> هَ . ق . درگذشت . (از معجم البلدان ).<br></font></div>'),
(182566, 'عرقی', '<span class=\"hlight\">عرقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) لقب عروةبن مروان جزری عرقی محدث و ساکن شهر عرقة بوده که از عبیداﷲبن عمر ورقی و موسی بن اعین و دیگران روایت دارد و ایوب بن محمد وزان و دیگران از او روایت کرده اند. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182567, 'عرقی', '<span class=\"hlight\">عرقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) لقب عروةبن مروان عرقی حرار است . وی محدث و امی بود و از عبیداﷲبن عمر رقی و موسی بن اعین روایت کرده است . و ایوب بن محمد وزان و خیربن عرفة و یونس بن عبدالاعلی و سعیدبن عثمان تنوخی از او روایت کرده اند. (از معجم البلدان ).<br></font></div>'),
(182568, 'عرقی', '<span class=\"hlight\">عرقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) لقب حسین بن عیسی انصاری خزرجی عرقی، مکنی به ابوالرضا است . وی محدث بود و از یوسف بن یحیی و محمدبن عبده و عبداﷲبن احمدبن ابی مسلم طرطوسی و محمدبن اسماعیل صائغ و دیگران روایت کرده است . و ابوالحسین بن جمیع و ابوالمفضل محمدبن عبداﷲبن محمد شیبانی و دیگران از او روایت کرده اند. (از معجم البلدان ).<br></font></div>'),
(182569, 'عرقی', '<span class=\"hlight\">عرقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) لقب بشربن نصربن منصور عرقی، مکنی به ابوالقاسم است . وی فقیه شافعی مذهب بود و نسبت او به «عرق » یکی از خادمان سلطان، که برید مصر را به عهده داشت، می باشد. تولدبشر در بغداد بود سپس به مصر رفت و به سال <span class=\"hlight\" dir=\"rtl\">٣٠٢</span> هَ .ق . در آنجا درگذشت . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182570, 'عرقی', '<span class=\"hlight\">عرقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) لقب احمدبن محمدبن حارث بن محمدبن عبدالرحمان بن عرق حمصی یحصبی عرقی است، و نسبت به جد دارد. او محدث بود و از پدر روایت دارد و ابوالقاسم طبرانی ازاو روایت کرده است . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182571, 'عرقی', '<span class=\"hlight\">عرقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) لقب احمدبن سلیمان عرقی، مکنی به ابوبکر است . وی محدث بود و از سعیدبن منصور و مهدی بن جعفر و دیگران روایت کرده است . و محمدبن یوسف بن بشر حافظ هروی، ازوی روایت کرده است . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182572, 'عرقی', '<span class=\"hlight\">عرقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) لقب احمدبن حمزةبن احمد تنوخی عرقی، مکنی به ابوالحسن است . وی محدث و شافعی مذهب بود و در اسکندریه نزد سلفی حدیث آموخت . تولد او را سال <span class=\"hlight\" dir=\"rtl\">٤٦٢</span> هَ . ق . نوشته اند. او در اسکندریه درگذشت و جسد او به مصر حمل شد. (از معجم البلدان ).<br></font></div>'),
(182573, 'عرقی', '<span class=\"hlight\">عرقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) لقب واثلةبن حسن عرقی، مکنی به ابوالفیاض است . وی محدث بود و از کثیربن عبید و عمروبن عثمان حمصی و یحیی بن عثمان روایت کرده است . و طبرانی و عبیداﷲبن علی جرجانی از او روایت کرده اند. (از معجم البلدان ).<br></font></div>'),
(182574, 'عرقی', '<span class=\"hlight\">عرقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ )خانواده ای از اهل کنعان که در عرقة ساکن بودند، و عرقة در نزد تل عرقة به شمال طرابلس واقع، که پرستندگان عشتاروت در اینجا بودند. (از قاموس کتاب مقدس ).<br></font></div>'),
(182575, 'عرقی', '<span class=\"hlight\">عرقی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ص نسبی ) منسوب به عَرَق . رجوع به عرق شود. <BR><font color=\"Blue\">◄</font> در تداول عامه، آنکه معتاد به بسیار عرق خوردن است . (یادداشت مرحوم دهخدا).<br></font></div>'),
(182576, 'عرقی', '<span class=\"hlight\">عرقی .</span> <font color=\"DarkGreen\"><b>[ ع َ قی ی ]</font></b> (ع ص نسبی ) منسوب است به عرقوة. (ناظم الاطباء). رجوع به عرقوة شود.<br></font></div>'),
(182577, 'عرقیل', '<span class=\"hlight\">عرقیل .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) زردی بیضه . (منتهی الارب ). زردی تخم مرغ و بیض . (از اقرب الموارد) (از ناظم الاطباء).<br></font></div>'),
(182578, 'عرقیه', '<span class=\"hlight\">عرقیه .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ قی ی َ ]</font></b> (اِ) دستارچه و روپاک ابریشمین . (از برهان ). رومال کوچک که به آن عرق پاک کنند. (غیاث اللغات ) (آنندراج ). دستارچه و روپاک ابریشمین که بدان عرق برچینند. (آنندراج ). پارچه ٔ کوچکی که بدان عرق از بدن پاک کنند. دستمال و رومال . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>در عرقیه قطرات عرق (؟)<br>شبنم گل بود بروی ورق .<br><font color=\"Red\">میرخسرو (از آنندراج ).</font><br></font></div>'),
(182579, 'عرم', '<span class=\"hlight\">عرم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) چربش . (منتهی الارب ). دسم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> باقی مانده در دیگ . (منتهی الارب ). بقیه ٔ دیگ . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گوی که فراهم آمدنگاه آب باشد. (منتهی الارب ). ج، عُرمان .<br></font></div>'),
(182580, 'عرم', '<span class=\"hlight\">عرم .</span> <font color=\"DarkGreen\"><b>[ ع َرَ ]</font></b> (ع مص ) نرم و سست گردیدن استخوان . (از منتهی الارب ). عرم العظم ؛ دود و بوی آن استخوان برخاست از پختن . (از اقرب الموارد). <br></font></div>'),
(182581, 'عرم', '<span class=\"hlight\">عرم .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) سیاهی سپیدی آمیخته، در هر چه باشد. یا خجک زدن از سیاهی و سپیدی . (منتهی الارب ). سیاهیی که با سپیدی مخلوط باشد، در هر چه باشد. و یا اینکه نقطه نقطه باشد از آنها بی آنکه نقطه ها وسیع گردد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سپیدی است بر لب گوسپند. <BR><font color=\"Blue\">◄</font> گوشت ناپخته . (منتهی الارب ). لحم و گوشت . (از اقرب الموارد). گوشت بی استخوان . (برهان ). <BR><font color=\"Blue\">◄</font> بیضه ٔ سنگخوار. (منتهی الارب ). <br></font></div>'),
(182582, 'عرم', '<span class=\"hlight\">عرم .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (ع اِ) نوعی از ماهی باشد که اهل مغرب آن را سردین و به یونانی سماریس خوانند. (برهان قاطع) (آنندراج ). ماهیی است که اهل مغرب سردین، و بیونانی دبس نامند. (تحفه ٔ حکیم مؤمن ). سماریس است . (مخزن الادویه ). و رجوع به ساردین و سردین شود.<br></font></div>'),
(182583, 'عرم', '<span class=\"hlight\">عرم .</span> <font color=\"DarkGreen\"><b>[ ع َرِ ]</font></b> (ع ص ) سخت و درشت از هر چیزی . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ) هرچه حاجز باشد میان دو چیز. (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ج ِ عَرِمة. (منتهی الارب ) (از اقرب الموارد). رجوع به عرمة شود. بندآب . (دهار). رودخانه و سدی که پیش آب رودخانه گرفته راه آب مسدود سازند. (غیاث اللغات ).<br></font></div>'),
(182584, 'عرم', '<span class=\"hlight\">عرم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) شدید و سخت گردیدن . (از منتهی الارب ) (از ناظم الاطباء). عرامة. عرام . رجوع به عرامة و عرام شود. <BR><font color=\"Blue\">◄</font> شوخ شدن . (از منتهی الارب ) (از ناظم الاطباء). عرامة. عرام . رجوع به عرامة وعرام شود. <BR><font color=\"Blue\">◄</font> ناز کردن و خرامیدن و شاد گردیدن و فیریدن و یا سرگشته شدن و تباه گشتن . (از منتهی الارب ) (از ناظم الاطباء). عرام . عرامة. رجوع به عرام و عرامة شود. <BR><font color=\"Blue\">◄</font> خوردن چیزی از طعام . (از منتهی الارب ). گویند عرم من الطعام، یعنی چیزی ازآن طعام را خورد. (از منتهی الارب ) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> گوشت از استخوان بازکردن . (از منتهی الارب ). گوشت بازکردن از استخوان . (تاج المصادر بیهقی ). برکندن از استخوان همه ٔ گوشت را و خوردن آن را. (از ناظم الاطباء). عرم العظم ؛ آنچه از گوشت بر استخوان بود جدا کرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درخت خاییدن و چریدن ستور. (از منتهی الارب ). چریدن شتران درخت را. (از ناظم الاطباء). عرم الابل الشجر؛ شتران از آن درخت برگرفتند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شیر مادر خوردن پسر. (منتهی الارب ). عرم الصبی امه ؛ آن کودک شیر مادر خود را خورد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> رنج و اذیت رسانیدن کسی را. (از منتهی الارب ). آزار و اذیت رسانیدن . (از اقرب الموارد).<br></font></div>'),
(182585, 'عرم', '<span class=\"hlight\">عرم .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (ع اِ) ج ِ عُرمة.(اقرب الموارد) (ناظم الاطباء). رجوع به عرمة شود.<br></font></div>'),
(182586, 'عرم', '<span class=\"hlight\">عرم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ أعرم . (منتهی الارب ) (اقرب الموارد). رجوع به اَعْرَم شود. <BR><font color=\"Blue\">◄</font> ج ِ عَرْماء. (اقرب الموارد). رجوع به عَرْماء شود. <BR><font color=\"Blue\">◄</font> (اِ) تخم قطا. (از اقرب الموارد). تخم مرغ و تخم قطا. (ناظم الاطباء).<br></font></div>'),
(182587, 'عرم', '<span class=\"hlight\">عرم .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (اِخ ) وادیی است که از ینبع سرازیر می گردد و نام آن در شعر کثیر آمده است . و گویند آن نام کوهی است . (از معجم البلدان ).<br></font></div>'),
(182588, 'عرم', '<span class=\"hlight\">عرم .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b>(اِخ ) نام وادیی است در عینة. (از معجم البلدان ).<br></font></div>'),
(182589, 'عرم', '<span class=\"hlight\">عرم .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (اِخ ) نام استخر و آبگیری بوده که اهل سبا آن را با سنگ و قیر بسته بوده اند. (برهان قاطع) (آنندراج ). عرم نام بندی است که بلقیس کرده بود و در میان دو کوه به سنگ و قیر تا آب باران جمع شدی . و آن را سه در کرد یکی از بالای دیگری . و در زیر آن برکه ای عظیم بود و آن را دوازده راه کرده بود بعدد جویهای ایشان . چون باران آمدی و سیلاب در پس آن بند جمع شدی آنگه در پائین بگشادی و چون کمتر شدی در زیرین بگشادی . چون آب در برکه شدی آن برکه آب قسمت کردی در جویها. و این همچنین می بود تا آنگه که بلقیس درگذشت و مدتی برین برآمد. ایشان طاغی شدند و از حد درگذشتند. خدای سبحانه و تعالی موشان بزرگ را بر ایشان مسلط گردانید، بیامدند وآن بند را سوراخ کردند. آب درافتاد و آن بند را خراب کرد و سیل در شهر ایشان افتاد و بوستانها و زمینهاو سراهای ایشان خراب کرد و ایشان بعضی هلاک شدند و بعضی در عالم متفرق گشتند. (تفسیر ابوالفتوح رازی ) <span class=\"hlight\">:</span> فأرسلنا علیهم سیل العرم . (قرآن <span class=\"hlight\" dir=\"rtl\">١٦/٣٤</span>).<br>جائی که تیغ قهر برآرد مهابتت <br>ویران کند به سیل عرم جنت سبا.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(182590, 'عرم', '<span class=\"hlight\">عرم .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (اِخ ) (سیل ...) سیلی که دفع آن ممکن نباشد. (ناظم الاطباء).<br></font></div>'),
(182591, 'عرما', '<span class=\"hlight\">عرما.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع حرف استفتاح ) بمعنی «أما» است . رجوع به عَرمی ̍ و أما شود.<br></font></div>'),
(182592, 'عرماض', '<span class=\"hlight\">عرماض .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) چغزلاوه . (منتهی الارب ). جل وزغ و چغزلاوه . (ناظم الاطباء). طحلب . (اقرب الموارد). خزه . بزغسمه .<br></font></div>'),
(182593, 'عرماض', '<span class=\"hlight\">عرماض .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) چغرلاوه برآوردن آب . (از منتهی الارب ) (از ناظم الاطباء). دارای طحلب و خزه گردیدن آب . (از اقرب الموارد). عرمضة. رجوع به عرمضة شود.<br></font></div>'),
(182594, 'عرمان', '<span class=\"hlight\">عرمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ أعرم . (منتهی الارب ) (اقرب الموارد). رجوع به أعرم شود. <BR><font color=\"Blue\">◄</font> ج ِ عَرم . (منتهی الارب ). رجوع به عرم شود. <BR><font color=\"Blue\">◄</font> ج ِ عَریم . (اقرب الموارد). رجوع به عریم شود.<br></font></div>'),
(182595, 'عرمان', '<span class=\"hlight\">عرمان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) پدر قبیله ای است . (منتهی الارب ).<br></font></div>'),
(182596, 'عرمان', '<span class=\"hlight\">عرمان .</span> <font color=\"DarkGreen\"><b>[ع َرْ رَ ]</font></b> (ع ص ) از قرای صرخد است، که آن از عمل حَوران، از اعمال دمشق بوده است . (از معجم البلدان ).<br></font></div>'),
(182597, 'عرمة', '<span class=\"hlight\">عرمة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع اِ) فراهم آمدنگاه ریگ . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> عرمةالرجل ؛ قبیله و گروه مردم . (منتهی الارب ).<br></font></div>'),
(182598, 'عرمة', '<span class=\"hlight\">عرمة.</span> <font color=\"DarkGreen\"><b>[ ع ُ م َ ]</font></b> (ع اِ) بمعنی عَرَم است در همه ٔ معانی . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> سیاهی سپیدی آمیخته در هر چه باشد. (ناظم الاطباء) (از اقرب الموارد). خجک زدن از سیاهی و سپیدی . (ناظم الاطباء). منقط شدن سیاهی و سپیدی بودن آنکه نقطه ها وسیع گردد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سپیدی بر لب گوسپند. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> گوشت ناپخته . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> تخم قطا. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> خرمن کوفته ٔ گرد کرده و پاک نانموده . (ناظم الاطباء). خرمن از طعام که کوفته می شود آنگاه به باد داده می شود. (اقرب الموارد). ج، عُرَم . (اقرب الموارد) (ناظم الاطباء). عَرَمة. رجوع به عَرمة شود.<br></font></div>'),
(182599, 'عرمة', '<span class=\"hlight\">عرمة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ م َ ]</font></b> (اِخ ) زمینی است سخت در کنار صمان، و نام آن در شعر رؤبه ٔ عجاج آمده است . و گویند آن عارضی است در یمامة. (از معجم البلدان ). زمینی است سخت درشت بر سر حد دهنا و مقابل عارض یمامة. (منتهی الارب ).<br></font></div>'),
(182600, 'عرمة', '<span class=\"hlight\">عرمة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ م َ ]</font></b> (ع اِ) بوی طبیخ . (منتهی الارب ). بوی طبیخ و چیز پخته شده . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خرمن کوفته ٔ گرد کرده از باد صاف و پاک نانموده . (منتهی الارب ). خرمن که پس از کوفتن جمع شده باشد تا آن را به باد دهند. (از اقرب الموارد). عُرمة. رجوع به عرمة شود. <BR><font color=\"Blue\">◄</font> ریگ توده . (منتهی الارب ). مجتمع و انبوه از رمل . (از اقرب الموارد).<br></font></div>'),
(182601, 'عرمة', '<span class=\"hlight\">عرمة.</span> <font color=\"DarkGreen\"><b>[ ع َ رِ م َ ]</font></b> (ع اِ) بند آب و حاجز میان دو چیز. (منتهی الارب ). سد و بندی که در جلو سیل می بندند، و حاجز میان دو چیز. (ناظم الاطباء). سدی که در عرض وادی قرار دهند. (از اقرب الموارد). ج، عَرِم و یا آن جمعی است بدون واحد، و برخی گویند واحد آن عرمة است . (از منتهی الارب ). ج، عَرِم مثل کلمة و کلم . ویا عرم جمعی است بدون واحد، و گویند آنها احباس و گویهایی است که در وادیها ساخته می شود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> باران سخت . (منتهی الارب ) (از اقرب الموارد). ذهب بهم سیل العرم ؛ یعنی سیل عرم آنها را از بین برد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کلاکموش نر. (منتهی الارب ). جرذ نر. (از اقرب الموارد). جرذ ذکر است، یعنی موش دشتی نر. (تحفه ٔ حکیم مؤمن ).<br></font></div>'),
(182602, 'عرمة', '<span class=\"hlight\">عرمة.</span> <font color=\"DarkGreen\"><b>[ ع َ رِ م َ ]</font></b> (اِخ ) وادیی است . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(182603, 'عرمرم', '<span class=\"hlight\">عرمرم .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ رَ ]</font></b> (ع ص ) سخت، هرچه باشد. (منتهی الارب ). شدید. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> لشکر بسیار. (منتهی الارب ). جیش کثیر. (از اقرب الموارد). بمعنی لشکر نوشته اند، و بعضی گویند که ترکی است و در بعضی اقسام ترکی عین مهمله هم می آید، واﷲ اعلم بالصواب . (غیاث اللغات ) (آنندراج ).<br></font></div>'),
(182604, 'عرمس', '<span class=\"hlight\">عرمس .</span> <font color=\"DarkGreen\"><b>[ ع ِ م ِ ]</font></b> (ع ص، اِ)سنگ بزرگ . (منتهی الارب ). صخره . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناقه ٔ استوار. (منتهی الارب ). ماده شتر سخت و قوی، از جهت تشبیه به صخره . (از اقرب الموارد).<br></font></div>'),
(182605, 'عرمس', '<span class=\"hlight\">عرمس .</span> <font color=\"DarkGreen\"><b>[ ع َ رَم ْ م َ ]</font></b> (ع ص ) مرد درگذرنده و رسا در امور و دانا. (منتهی الارب ). ماضی و گذرنده و ظریف، از مردم . (از اقرب الموارد).<br></font></div>'),
(182606, 'عرمسة', '<span class=\"hlight\">عرمسة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ س َ ]</font></b> (ع مص ) استوار گردیدن اندام کسی سپس نرمی و فروهشتگی . (از منتهی الارب ). سخت گردیدن بدن پس از سست بودن . (از اقرب الموارد).<br></font></div>'),
(182607, 'عرمش', '<span class=\"hlight\">عرمش .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) خوشه ٔ انگور بدون دانه . عرموش . ج، عرامیش . (از دزی ). و رجوع به عرموش شود.<br></font></div>'),
(182608, 'عرمض', '<span class=\"hlight\">عرمض .</span> <font color=\"DarkGreen\"><b>[ ع ِ م ِ ]</font></b> (ع اِ) از درختان عضاه است . (از اقرب الموارد). عَرمض رجوع به عَرمض شود.<br></font></div>'),
(182609, 'عرمض', '<span class=\"hlight\">عرمض .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع اِ) درخت با خار. (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> درخت خرد کنار و پیلو. و هر درخت که گاهی کلان نگردد. (منتهی الارب ). خرد و کوچک از سدر و اراک، و گویند خرد و کوچک هر درختی که هرگز بزرگ نشود. (از اقرب الموارد). نوعی از درخت کنار است و آن را خارها مانند قلاب و منقار مرغان می باشد و هرگز بار و میوه ندهد. (برهان قاطع). نوعی از سدر بری است که به فارسی کنار بری نامند، و اراک کوچک را دانسته اند. (از تحفه ٔ حکیم مؤمن ). اسم درخت سدر بری است . (مخزن الادویه ). صنفی از سدر که بلند نشود و برگهای آن مجعد است و خارش مانند نوک مرغان باشد. و یا اراک خرد و صغار اندک . (یادداشت مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> عضاه خرد و صغار عضاه . (از یادداشت مرحوم دهخدا). از درختان عضاه است . (از اقرب الموارد). عِرمِض . رجوع به عِرْمِض شود. <BR><font color=\"Blue\">◄</font> حب الغار. (از تحفه ٔ حکیم مؤمن ) (از مخزن الادویه ). <BR><font color=\"Blue\">◄</font> چغزلاوه . (منتهی الارب ). طحلب، و واحد آن عرمضة است . (از اقرب الموارد). جامه ٔ غوک را گویند و آن چیزی باشد سبز که در روی آبهای ایستاده بهم رسد و طحلب سبزی است که در زیر آب می باشد و بالای آب می آید. (تحفه ٔ حکیم مؤمن ). غلفق سبز که روی آب پوشد، آنگاه که در اطراف و کناره های آب باشد آن را طحلب نامند. (یادداشت مرحوم دهخدا). خزه . طحلب . گاو آب . غوک جامه . ثورالماء. جل وزق . جامه ٔ غوک . خبزالضفادع . هنمد. سیرند. فرزد. چم . سرید. جلبک . چغربازه . چغروازه . برغمه . بزغسمه .<br></font></div>'),
(182610, 'عرمضان', '<span class=\"hlight\">عرمضان .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع اِ) اسم عربی حندقوقا و بخورالاکراد است . (تحفه ٔ حکیم مؤمن ) (مخزن الادویه ).<br></font></div>'),
(182611, 'عرمط', '<span class=\"hlight\">عرمط.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) حوش عرمط؛ دربار شاهی و محل تجمع. (از دزی ).<br></font></div>'),
(182612, 'عرموش', '<span class=\"hlight\">عرموش .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) خوشه ٔ انگور بدون دانه . عرمش . ج، عرامیش . (از دزی ). و رجوع به عرمش شود.<br></font></div>'),
(182613, 'عرموط', '<span class=\"hlight\">عرموط.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) تلفظ عامیانه است عُمروط را. (از دزی ). رجوع به عمروط شود.<br></font></div>'),
(182614, 'عرموی', '<span class=\"hlight\">عرموی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) دزی در فرهنگ آرد که باید نام نوعی پارچه باشد، و گوید ریشه ٔ آن معلوم نشده است و شاهد ذیل را نیز نقل کرده : و علی رأسها معجر عرموی مسبل علی وجهها.<br></font></div>'),
(182615, 'عرمی', '<span class=\"hlight\">عرمی .</span> <font color=\"DarkGreen\"><b>[ع َ ما ]</font></b> (ع حرف استفتاح )عَرْما لغتی است در «أما». گویند عرمی و اﷲ، به معنی أما و اﷲ. (از اقرب الموارد) (از منتهی الارب ).<br></font></div>'),
(182616, 'عرن', '<span class=\"hlight\">عرن .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) آب بسیار. (منتهی الارب ). غَمَر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بوی طبیخ . (منتهی الارب ) (اقرب الموارد). عِرن . رجوع به عِرن شود. <BR><font color=\"Blue\">◄</font> دود. (منتهی الارب ). دخان . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> درختی است که بدان پوست پیرایند. (منتهی الارب ). درختی است به وسیله ٔ آن دباغی کنند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گوشت پخته . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ریش گردن ستور. (منتهی الارب ). «عران » که مرضی است . (از اقرب الموارد). رجوع به عِران شود. <BR><font color=\"Blue\">◄</font> بیماریی است که در پایین پای ستور برآیدو موی برافکند. یا کفتگی دست و پای ستور. یا درشتی است که در خردگاه دست و پای اسب پیدا گردد. (منتهی الارب ). شقاق، و آن ترکیدگی دست و پای آدمی و اسب و حیوانات دیگر است . (از برهان ). عِران، و آن مرضی است که انتهای پای ستور را فرامیگیرد و وی را از بین می برد؛ و گویند تشقق و شکافتگی است در دستها و پاهای ستور؛ و گویند آن سختی و ضخامتی است که در بندگاه پای اسب پدیدار گردد. (از اقرب الموارد). عُرنة. (منتهی الارب ). رجوع به عُرنة و نیز به عَرن شود <span class=\"hlight\">:</span> <br>دست را چون مرکب تیغ و قلم کردی مدار<br>نیست غم گر مرکب تن لنگ باشد یا عرن .<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(182617, 'عرن', '<span class=\"hlight\">عرن .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِ) چیزی است در پهلوی دست و پای اسب نزدیک به زانو بمانند چرم می شود و روزبروز بلندتر می گردد. و عرب آن را اعظم السبق می گوید. بخور آن تب ربع را نافع است . (از برهان ).اسم عربی زوایدی است که در حوالی سم و زانوی اسب و شتر باشد. در مزاج و افعال مانند سم است . و سائیده ٔ او بقدر نیم درهم با سرکه جهت صرع رطوبی، و با آب سرد جهت جمیع سموم، و بخور او جهت اختناق رحم مفید است . و گویند چون صاحب تب ربع او را به قصد رفع تب از حیوان جدا کند، رفع تب او می شود. (مخزن الادویه ). <BR><font color=\"Blue\">◄</font> به لغت اهل شام، نوع سفید یوفاریقون است . (از مخزن الادویه ). یوفاریقون ابیض . اوفاریقون ابیض .<br></font></div>'),
(182618, 'عرن', '<span class=\"hlight\">عرن .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) «عران » نهادن بر بینی شتر. (از منتهی الارب ). برس اندر بینی شتر کردن . (تاج المصادر بیهقی ). برس در بینی شتر کردن . (المصادر زوزنی ). عرن البعیر؛ در بینی شتر «عران »چوب قرار داد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بدرد آمدن بینی از عران . (از منتهی الارب ). عُرن البعیر (بصیغه ٔ مجهول )؛ شتر از درد بینی خود شکایت کرد بجهت «عران ». (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پی پیچیدن تیر را. (از ناظم الاطباء). عرن السهم ؛ پی پیچید بر آن تیر. (از اقرب الموارد). رصف . رجوع به رصف شود.<br></font></div>'),
(182619, 'عرن', '<span class=\"hlight\">عرن .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع مص ) «عرن » برآمدن در پای ستور. (از ناظم الاطباء). عرنت الدابة، آن چارپا دچار «عرنة» شد. (از اقرب الموارد).<br></font></div>'),
(182620, 'عرن', '<span class=\"hlight\">عرن .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (ع ص ) هر که لازم گیرد جزار یا قسمت کننده را، چندانکه او را بخوراند گوشت شتر را. (منتهی الارب ). کسی که لازم گیرد یاسر را تابخورد از گوشت جزور. (ناظم الاطباء). کسی که «یاسر» و قسمت کننده ٔ گوشت شتر را ملازم شود تا از «جزور» و شتر کشتنی بهره برگیرد. (از اقرب الموارد) (از تاج العروس ). <BR><font color=\"Blue\">◄</font> ستور دست و پای کفیده و موی رفته . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> اسب مبتلی به بیماری عرن . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِخ ) اسب عدی بن امیه ضبی . یا اسب عمیربن جبل بجلی . (منتهی الارب ).<br></font></div>'),
(182621, 'عرن', '<span class=\"hlight\">عرن .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) بوی طبیخ . (منتهی الارب ) (ازاقرب الموارد). بوی طبیخ یا بطیخ . (ناظم الاطباء).<br></font></div>'),
(182622, 'عرن', '<span class=\"hlight\">عرن .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ]</font></b> (ع اِ) ج ِ عَرین . (منتهی الارب ) (اقرب الموارد). رجوع به عرین شود. <BR><font color=\"Blue\">◄</font> ج ِ عرینة. (ناظم الاطباء). رجوع به عرینة شود.<br></font></div>'),
(182623, 'عرناس', '<span class=\"hlight\">عرناس .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) مرغی است مانند کبوتر، و انسان متوجه آن نمی گردد مگر هنگامی که از پیش پای انسان پرواز کند و باعث ترس او شود. (از منتهی الارب ) (از اقرب الموارد). عُرنوس . رجوع به عرنوس شود. <BR><font color=\"Blue\">◄</font> بینی کوه . (منتهی الارب ) (ازاقرب الموارد). ج، عرانیس . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> جای باغنده ٔ پنبه زنان . (منتهی الارب ). محل و جای نواله های پنبه زن . (از ذیل اقرب الموارد از تاج ).<br></font></div>'),
(182624, 'عرناس', '<span class=\"hlight\">عرناس .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) جایگاهی است در حمص . و در شعر ابوحصینة آمده است . (از معجم البلدان ).<br></font></div>'),
(182625, 'عرنان', '<span class=\"hlight\">عرنان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) کوهی است . (منتهی الارب ). کوهی است مابین تیماء و دو کوه طی ٔ. و گویند در دنباله ٔ جبال صبح، از بلاد فزارة است . و گویند رملی است در بلاد عقیل . و گویند نام وادیی است مشهور. و نیز گویند آن کوهی است در جناب در پایین وادی القری به سوی فَید. و این سرزمین به کثرت وحوش و ددان وصف می گردد. (از معجم البلدان ).<br></font></div>'),
(182626, 'عرنة', '<span class=\"hlight\">عرنة.</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ن َ ]</font></b> (اِخ ) (بطن ...) وادیی است که در کنار عرفات . و گویندآن مسجد عرفه و تمام مسیل است . (از معجم البلدان ). جایی است در عرفات، و آن موقف نیست . (منتهی الارب ).<br></font></div>'),
(182627, 'عرنة', '<span class=\"hlight\">عرنة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ن َ ]</font></b> (ع اِ) عَرن . عِران . بیماری مذکور در «عرن ». (از منتهی الارب ) (از اقرب الموارد). رجوع به عَرَن شود.<br></font></div>'),
(182628, 'عرنة', '<span class=\"hlight\">عرنة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ن َ ]</font></b>(ع اِ) رگهای بینی . (منتهی الارب ). رگها و عروق عرتن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چوب درخت ظمخ . (منتهی الارب ). واحد «عرن » و آن درخت ظِمح می باشد که به شکل درخت دلب و چنار است و چوب گازران را از آن می برند و در زمین فرومی کنند تا لباس را بر آن بکوبند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بیخ درخت که به وی دهند پوست را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص ) مرد پلید و افتاده از بی طاقتی . (منتهی الارب ). صریع و خبیث که قابل تحمل نباشد؛ رجل عرنة. (از اقرب الموارد).<br></font></div>'),
(182629, 'عرنة', '<span class=\"hlight\">عرنة.</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ن َ ]</font></b> (ع ص ) ستور کفیده پا و موی رفته پا. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> اسب عرن زده . (منتهی الارب ) (آنندراج ).<br></font></div>'),
(182630, 'عرنتن', '<span class=\"hlight\">عرنتن .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ رَ ت ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ رَ ت ُ ]</font></b> (ع اِ) یک نوع گیاهی است که بدان پوست پیرایند. (ناظم الاطباء).درختی است که به وسیله ٔ آن دباغی شود. (از اقرب الموارد). عَرتَن . عَرتون . رجوع به عرتن و عرتون شود.<br></font></div>'),
(182631, 'عرنجج', '<span class=\"hlight\">عرنجج .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ج َ ]</font></b> (اِخ ) نام حمیربن سبا است، و نون آن زائد باشد. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(182632, 'عرند', '<span class=\"hlight\">عرند.</span> <font color=\"DarkGreen\"><b>[ ع ُرْ رُ ن َدد ]</font></b> (اِخ ) قلعه ای است به صنعای یمن . (منتهی الارب ). <br></font></div>'),
(182633, 'عرند', '<span class=\"hlight\">عرند.</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ رَ ]</font></b> (ع ص ) صلب و شدید. (از اقرب الموارد). درشت و رست، گویند وتر عرند. و هم وزن آن جز کلمه ٔ «ترنج » یافت نشود. (از منتهی الارب ). عَرِد. عُرُدّ. عَرندند. رجوع به عرد و عرندد شود.<br></font></div>'),
(182634, 'عرندد', '<span class=\"hlight\">عرندد.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ دَ ]</font></b> (ع ص ) سخت و رست . (منتهی الارب ). صلب و شدید. (از اقرب الموارد). عَرِد.عُرُدّ. عُرُند. عُرَند. رجوع به عرد و عرند شود.<br></font></div>'),
(182635, 'عرندس', '<span class=\"hlight\">عرندس .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ دَ ]</font></b> (ع ص ) شتر سخت و توانا. (منتهی الارب ). سخت و طویل القامت از شتران، گویند بعیر عرندس و ناقة عرندس و عرندسة. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> توجبه ٔ بسیار آب . (منتهی الارب ). سیل بسیار. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) شیر بیشه . (منتهی الارب ). اسد بزرگ و عظیم . (از اقرب الموارد).<br></font></div>'),
(182636, 'عرندسة', '<span class=\"hlight\">عرندسة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ دَ س َ ]</font></b> (ع ص ) تأنیث عرندس . گویند ناقة عرندسة؛ ماده شتر سخت و توانا. (منتهی الارب ) (از اقرب الموارد). و رجوع به عرندس شود.<br></font></div>'),
(182637, 'عرندل', '<span class=\"hlight\">عرندل .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ دَ ]</font></b> (اِخ ) نام قریه ای است از سرزمین شَراة از شام . و آن در عهد خلیفه ٔ دوم پس از یرموک فتح شد. (از معجم البلدان ).<br></font></div>'),
(182638, 'عرندل', '<span class=\"hlight\">عرندل .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ دَ ]</font></b> (ع ص ) سخت درشت . (منتهی الارب ). صلب و شدید. (از اقرب الموارد). عَردَل . رجوع به عردل شود. <BR><font color=\"Blue\">◄</font> دراز قامت . (منتهی الارب ). طویل . (اقرب الموارد).<br></font></div>'),
(182639, 'عرنش', '<span class=\"hlight\">عرنش .</span> <font color=\"DarkGreen\"><b>[ ع ِ ن ِ]</font></b> (اِخ ) ابن سعدبن خولان خولانی است . (منتهی الارب ).<br></font></div>'),
(182640, 'عرنقصان', '<span class=\"hlight\">عرنقصان .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ق ُ ]</font></b> (ع اِ) عرقصاء. (منتهی الارب ). اسم حندقوقی است یا یربطوره است . (مخزن الادویه ). عُرقُصات . عَرقَصان . عریقصاء. رجوع به عرقصاء شود.<br></font></div>'),
(182641, 'عرنوس', '<span class=\"hlight\">عرنوس .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b>(ع اِ) پرنده ای است شبیه به کبوتر، که عرناس نیز نامیده شود. (از اقرب الموارد). رجوع به عِرناس شود.<br></font></div>'),
(182642, 'عرنی', '<span class=\"hlight\">عرنی .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ نی ی ]</font></b> (ص نسبی ) نسبت است به عرینةبن نذیربن قسربن عبقربن انماربن أراش، که بطنی است از بجیلة. و آن عده که بنزد رسول خداوند (ص ) در مدینه وارد شدند و اقامت در آنجا را نپسندیدند، از این بطن بوده اند. (از اللباب فی تهذیب الانساب ). ج، عُرَنیّون . (ناظم الاطباء).<br></font></div>'),
(182643, 'عرنی', '<span class=\"hlight\">عرنی .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (اِخ ) حسن بن عبداﷲ عرنی . محدث بود و از ابن عباس روایت کرده است . و سلمةبن سهیل و حکم بن عتیبة از او روایت کرده اند. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182644, 'عرنی', '<span class=\"hlight\">عرنی .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (اِخ ) قاسم بن حکم عرنی . قاضی و محدث شهر همدان در قرن دوم هجری . رجوع به قاسم عرنی شود.<br></font></div>'),
(182645, 'عرنیة', '<span class=\"hlight\">عرنیة.</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ نی ی َ ]</font></b> (ع ص ) زن زناکار. <BR><font color=\"Blue\">◄</font> زن گنده ٔ تنومند. (ناظم الاطباء).<br></font></div>'),
(182646, 'عرنین', '<span class=\"hlight\">عرنین .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) بینی، یا استخوان درشت آن، یا بن بینی نزدیک ابرو. (منتهی الارب ). بن بینی . (مهذب الاسماء). تمام بینی و یا استخوان سخت آن، و یا زیر محل اتصال دو ابرو، یعنی ابتدای بینی که «شمم » در آن قرار دارد. (از اقرب الموارد).<br>گر ناصبی مثل مگسی گردد<br>بگذشت نارد از در عرنینم .<br> <font color=\"Red\">ناصرخسرو.</font><br><BR><font color=\"Blue\">◄</font> اول و بهترین هر چیزی . (منتهی الارب ). اول هر چیزی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سردار و شریف قوم . (منتهی الارب ). سید شریف . (اقرب الموارد). ج، عَرانین . (اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(182647, 'عره', '<span class=\"hlight\">عره .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) شهرکی است به شام از فلسطین بر حد میان شام و مصر. (حدود العالم ).<br></font></div>'),
(182648, 'عرهان', '<span class=\"hlight\">عرهان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) نام جایگاهی است . و کلمه ٔ آن در عربی شناخته نیست . (از معجم البلدان ).<br></font></div>'),
(182649, 'عرهضان', '<span class=\"hlight\">عرهضان .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ)اسم حندقوقی است، یا یربطوره است . (مخزن الادویة).<br></font></div>'),
(182650, 'عرهل', '<span class=\"hlight\">عرهل .</span> <font color=\"DarkGreen\"><b>[ ع ِ هََ ل ل ]</font></b> (ع ص ) شتر استوار. (منتهی الارب ). شدید و سخت و قوی از شتران . (از اقرب الموارد).<br></font></div>'),
(182651, 'عرهم', '<span class=\"hlight\">عرهم .</span> <font color=\"DarkGreen\"><b>[ ع َ هََ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ هََ م م ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ). اسد. <BR><font color=\"Blue\">◄</font> (ص ) قوی و شدید و سخت . (از اقرب الموارد).<br></font></div>'),
(182652, 'عرهول', '<span class=\"hlight\">عرهول .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) واحد عراهیل . (ناظم الاطباء). مفرد عَراهیل است بمعنی جماعت و گروه مهمل و بی کار. (از اقرب الموارد). رجوع به عراهیل شود.<br></font></div>'),
(182653, 'عرهوم', '<span class=\"hlight\">عرهوم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) نازک و نرم ازهر چیزی . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> قوی و سخت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) باران . <BR><font color=\"Blue\">◄</font> درخت گز خشک شده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> عُرجون . (اقرب الموارد) (منتهی الارب ). خوشه ٔ خشک خرما. <BR><font color=\"Blue\">◄</font> درخت انگور وقتی که ظاهر شده باشد سر آن . (منتهی الارب ). فطر <font color=\"DarkGreen\"><b>[ ف ِ <span class=\"hlight\" dir=\"rtl\">/</span> ف ُ ]</font></b> و انگور که سر آن آشکار شود. (از اقرب الموارد).<br></font></div>'),
(182654, 'عرهون', '<span class=\"hlight\">عرهون .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) گیاهی است، یا آن سماروغ سپید است . (منتهی الارب ). سماروغ سپید یا گیاهی دیگر. (ناظم الاطباء). فطر است . (مخزن الادویة). فطر <font color=\"DarkGreen\"><b>[ ف ُ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ]</font></b> که نوعی است از قارچ و سماروغ . (از اقرب الموارد). ج، عَراهین . (اقرب الموارد) (منتهی الارب ).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(182655, 'عرو', '<span class=\"hlight\">عرو.</span> <font color=\"DarkGreen\"><b>[ ع َرْوْ]</font></b> (ع ص ) خالی و پری . (منتهی الارب ). أنا عرو منه ؛ خالی از او هستم . فلان عرو من الذنوب ؛ بر او گناهی نیست . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنکه اهتمام امور نکند. (منتهی الارب ). کسی که به امر توجه نکند و اهتمام نورزد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) کرانه . (منتهی الارب ). ناحیه . (اقرب الموارد). ج، أعراو. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(182656, 'عرو', '<span class=\"hlight\">عرو.</span> <font color=\"DarkGreen\"><b>[ ع َرْوْ ]</font></b> (ع مص )فروگرفتن کسی را. (از منتهی الارب ) (آنندراج ). فروگرفتن کاری را. (ناظم الاطباء). المام و فروگرفتن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آمدن حالی که احسان و نیکوئی می خواست . (از منتهی الارب ). قصد کردن کسی را جهت طلب احسان و نیکوئی . (از ناظم الاطباء). آمدن نزد کسی به طلب نیکی و معروف وی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> فرود آمدن چیزی به کسی . (از منتهی الارب ). رسیدن کاری کسی را. (ناظم الاطباء). دچار شدن کسی به امری، و عارض شدن آن امر بر او. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> فروگرفتن مهمان میزبان را. (از منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> قصد کردن کسی را. سردی زده گردیدن از تب . (از منتهی الارب ). «عرواء» دست دادن به شخص . (از اقرب الموارد). رجوع به عرواء شود. <BR><font color=\"Blue\">◄</font> اندوهگین شدن سپس فروختن چیزی . (از منتهی الارب ). فروختن شخص چیزی را سپس دلتنگ شدن برای آن . (از اقرب الموارد).<br></font></div>'),
(182657, 'عروان', '<span class=\"hlight\">عروان .</span> <font color=\"DarkGreen\"><b>[ ع َرْ ]</font></b> (اِخ ) همان عُروان است جز آنکه به فتح اول خوانده شده . و گویند آن کوهی است در فلاتی بنام عَروی ̍. و برخی آن را کوهی در مکه دانسته اند که طائف بر بالای آن واقع شده است و قبایل هذیل در آنجا ساکنند. و در حجاز محلی مرتفعتر از این کوه یافت نشود بدین سبب آب و هوای طائف معتدل شده است . و گویند در این محل آب یخ می بندد و آن را تنها نقطه ای از حجاز دانسته اند که یخبندان آب در آن موجود است . (از معجم البلدان ). و رجوع به عُروان شود.<br></font></div>'),
(182658, 'عروان', '<span class=\"hlight\">عروان .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ ]</font></b> (اِخ ) ابن کنانةبن خزیمة. از اجداد جاهلی است . رجوع به عروانی شود.<br></font></div>'),
(182659, 'عروان', '<span class=\"hlight\">عروان .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ ]</font></b> (اِخ ) ابن جشم بن عبدشمس وائل بن الغوث . از اجداد جاهلی است . رجوع به عروانی شود.<br></font></div>'),
(182660, 'عروان', '<span class=\"hlight\">عروان .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ ]</font></b> (اِخ ) نام کوهی است . وگویند نام جایگاهی است . و آن را به فتح اول نیز خوانده اند. (از معجم البلدان ). و رجوع به عَروان شود.<br></font></div>'),
(182661, 'عروان', '<span class=\"hlight\">عروان .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ ]</font></b> (ع اِ) گیاهی است، یا آنچه در زمستان برگش نیفتد. (منتهی الارب ). نام گیاهی که در زمستان برگش نیفتد و سبز بماند. (ناظم الاطباء).<br></font></div>'),
(182662, 'عروانی', '<span class=\"hlight\">عروانی .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ نی ی ]</font></b> (ص نسبی ) نسبت است به عروان، و آن از انساب کندة باشد. و او عروان بن جشم بن عبدشمس وائل بن الغوث است . و نیز عروان بن کنانةبن خزیمد کنیز برة دختر هراست . و برخی آن را غزوان بن کنانة، باغین معجم وزاء خوانده اند. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182663, 'عروب', '<span class=\"hlight\">عروب .</span> <font color=\"DarkGreen\"><b>[ ع َرْ رو ]</font></b> (اِخ ) نام دو قریه است در ناحیه ٔ قدس . و در آنجا دو چشمه ٔ عظیم و دو برکه و باغهای باصفایی موجود است . (از معجم البلدان ).<br></font></div>'),
(182664, 'عروب', '<span class=\"hlight\">عروب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) زن صاحب جمال شوی دوست، یا زن نافرمان، یا عاشق شوی، یا به ستم دوست دارنده شوی را و آشکارکننده ٔ آن، یا زن رخسار خنده . (منتهی الارب ). زنی که شوهرش او را دوست دارد، و زنی خنده رو، و زنی که او شوهر خود را دوست دارد. (آنندراج ). زن شوی دوست . (دهار). شوهردوست . (نصاب ). زن دوست دارنده زوج خود را، و گویند زن عاصی، و گویند زن ضحاکه و بسیارخنده . گویند: خیرالنساء اللعوب العروب . (از اقرب الموارد). ج، عُرُب . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(182665, 'عروبة', '<span class=\"hlight\">عروبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع ص ) به معنی عروب است . (از منتهی الارب ) (از اقرب الموارد). رجوع به عروب شود. <BR><font color=\"Blue\">◄</font> (اِ) با لام و بدون آن و هو الافصح، روز جمعه . (منتهی الارب ).عروبة و العروبة و یوم العروبة، روز جمعه و آدینه، و آن از اسماء قدیم است و معرب از اَرُبا که نبطی است و یا عَروبتا که سریانی است . ابوالمعالی لغوی گوید، معرفه است و کم اتفاق می افتد که «ال » بر آن داخل شود. و سیبویه گوید بدون «أل » آوردن آن خطاست . و قول سیبویه مورد تأیید یونس بن حبیب نیز واقع شده است . (از اقرب الموارد). اصمعی گوید عروبة، جمعه است و آن را در نبطی «أذینا» گویند. (از المعرب جوالیقی ).<br></font></div>'),
(182666, 'عروبة', '<span class=\"hlight\">عروبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن ابی عروبة، از اعلام است و صحیح آن به لام است و ترک آن غلط، یا قلیل الاستعمال . (از منتهی الارب ).<br></font></div>'),
(182667, 'عروبة', '<span class=\"hlight\">عروبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع مص ) عرب زبان شدن . (تاج المصادر بیهقی ) (منتهی الارب ). عرب خالص شدن و دچار لحن نشدن، و فعل آن از باب ششم است، و گویند عروبة و عروبیة از مصادر بدون فعل می باشند. (از اقرب الموارد). عُروبیّة. رجوع به عروبیة شود.<br></font></div>'),
(182668, 'عروبت', '<span class=\"hlight\">عروبت .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ]</font></b> (ع مص ) عرب زبان شدن . عروبة. رجوع به عروبة شود.<br></font></div>'),
(182669, 'عروبیة', '<span class=\"hlight\">عروبیة.</span> <font color=\"DarkGreen\"><b>[ ع ُ بی ی َ ]</font></b>(ع مص ) به معنی عروبة است . (از منتهی الارب ) (از اقرب الموارد). عرب زبان شدن . عروبة. رجوع بعروبة شود.<br></font></div>'),
(182670, 'عروج', '<span class=\"hlight\">عروج .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) بلند گردیدن و برآمدن . (از منتهی الارب ). بر آمدن و به بالا برشدن، و با لفظ «کردن » مستعمل است . (از آنندراج ). به بالا بر شدن . (دهار) (ترجمان القرآن جرجانی ). به بالا برشدن و به آسمان برشدن . (المصادر زوزنی ) (تاج المصادر بیهقی ). بالا رفتن . (از اقرب الموارد). برآمدن . بر شدن . هوا گرفتن . مقابل نزول . مقابل هبوط. (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">عروج کردن </span> ؛ برآمدن . برشدن .<br> <BR><font color=\"Blue\">◄</font> عرج فی الدرجة أو السلم ؛ از نردبان بالا رفت . (از اقرب الموارد). برآمدن بر نردبان و بلند گردیدن . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> عُرج به (صیغه ٔ مجهول )، او را بالا برد. (از اقرب الموارد). برد او را. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> رسیدن در پای کسی، پس لنگیدن . (منتهی الارب ). چیزی به پای کسی خوردن، پس مانند اشخاص لنگ راه رفتن، در حالی که این لنگی از خلقت او نباشد. اما اگر لنگی از خلقت او باشد، آن را عَرَج گویند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) صعود و ترقی . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>مکان علم است نفست را زبان اندیشه ٔ رهرو<br>نزولت پایه ٔ ادنی عروجت منزل ایقان .<br> <font color=\"Red\">ناصرخسرو.</font><br>بلکه در هاروت و ماروت این شراب <br>از عروج چرخشان شد سد باب .<br> <font color=\"Red\">مولوی .</font><br>که کمینه ٔ این کمین باشد بقا<br>تا ابد اندرعروج و ارتقاء.<br> <font color=\"Red\">مولوی .</font><br><BR><font color=\"Blue\">◄</font> (اِ) ج ِ عرج <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ]</font></b>. (منتهی الارب ) (اقرب الموارد). رجوع به عرج شود.<br></font></div>'),
(182671, 'عرود', '<span class=\"hlight\">عرود.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) روئیدن و بلند گردیدن گیاه و دندان . (ازمنتهی الارب ). برآمدن نبات و دندان . (تاج المصادر بیهقی ). عردالناب ؛ همه ٔ ناب خارج شد و سخت گردید، و چنین است عردالنبات . و گویند آن بمعنی خارج شدن از نرمی و سخت شدن است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پدید آمدن نبات . (المصادر زوزنی ). عردت الشجرة؛ درخت پدید آمد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دور انداختن . (از منتهی الارب ). عرد الحجر؛ سنگ را به دور افکند. (از اقرب الموارد). <br></font></div>'),
(182672, 'عرور', '<span class=\"hlight\">عرور.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) گرگین شدن شتران . (از منتهی الارب ). عرت الابل ؛ گر و اجرب شدند شتران . (از اقرب الموارد). عَرّ. رجوع به عر شود.<br></font></div>'),
(182673, 'عروس', '<span class=\"hlight\">عروس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) (وادی الَ ...) موضعی است نزدیک مدینه . (منتهی الارب ).<br></font></div>'),
(182674, 'عروس', '<span class=\"hlight\">عروس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) قلعه ای است به یمن . (از منتهی الارب ). از قلعه ها و حصون بحار است در یمن . (از معجم البلدان ).<br></font></div>'),
(182675, 'عروس', '<span class=\"hlight\">عروس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) (تیم ...) نام تیمی بوده است ظاهراً به بخارا. (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> <br>دریغ تیم عروس و دریغ تیم ملک <br>که این و آن سفط جبه بود و دستارم .<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(182676, 'عروس', '<span class=\"hlight\">عروس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام منجنیقی بود از آن حجاج بن یوسف، که پانصد مرد آن را می گرداندند. و محمدبن قاسم به سال <span class=\"hlight\" dir=\"rtl\">٨٩</span> هَ . ق . آن را برای جنگ با پادشاه هند فرستاد و یکی از اصنام هندیان را بوسیله ٔ آن ویران ساخت . (از تمدن اسلام جرجی زیدان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٣</span>) <span class=\"hlight\">:</span> برابر ارگ منجنیقی عروس برنهاد و بینداخت و پاره ای از خضراء ارگ فروافکندند. محمود <font color=\"DarkGreen\"><b>[ غزنوی ]</font></b> گفت به فال نیک آمد. (تاریخ سیستان ).<br></font></div>'),
(182677, 'عروس', '<span class=\"hlight\">عروس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) مرد و زن نوخواسته یکدیگر را. (منتهی الارب ). زن نوکدخدا و مرد نوکدخدا، مگر در عرف اطلاق این بیشتر بر زن کنند، و به ضمتین خواندن خطاست . (آنندراج ) (غیاث اللغات ). مرد و زن نوخواسته یکدیگر را. (ناظم الاطباء). مرد و زن مادام که در اِعراس و عروسی باشند. (از اقرب الموارد). مرد و زن که تازه خواستگاری شده است مادامی که در سور گردند. (شرح قاموس ). ج، عُرُس، عَرائس ؛ گویند هم عُرُس و هن عرائس . (منتهی الارب ) (از اقرب الموارد). یعنی جمع آن در مرد عرس، و درزن عرایس است . (از شرح قاموس ). هدی . هدیة. مهدیة.<br>در مثل گویند: کاد العروس یصیر أمیرا. (اقرب الموارد) (منتهی الارب ). لاعطر بعد عروس لامخباء لعطر بعد عروس، این مثل در حق شخصی گویند که اجناس خوب و نیکو از وی پوشیده نباشد. (منتهی الارب ) (ناظم الاطباء). آن را برای کسی گویند که ذخیره کرده نمی شود از او چیزی گرانبها. (شرح قاموس ). آن را در حق کسی گویند که چیز نفیس از وی پنهان نشود، و یا در مذمت پنهان کردن چیزی در وقت حاجت، به کار برند. (از اقرب الموارد). اصل مثل این است که اسماء عذریة بنت عبداﷲ را شوهری بود عروس نام که پس از خواستگاری از او مرد. پس مردی از او خواستگاری کرد که بی چیز و بخیل و زشت بود و دهانی بدبوی داشت و چون خواست پیش اسماء برود اسماء او را گفت اگر اجازه دهی پسر عم مرده ٔ خود را بستایم . مرد گفت بکن . اسماء گفت : بر تو می گریم ای عروس عروسها، ای کسی که میان اهل خود در آرامی چون روباه بودی و در وقت سختی ها و گرفتاری هاچون شیر بودی و اوصافی در تو بود که مردم بر آن آگاه نیستند. مرد گفت آن اوصاف چیست ؟ اسماء گفت : در همت و عزیمت سستی نمی کرد و در بامدادهای سختی و گرفتاری، شمشیر به کار می برد، سپس افزود: ای عروس روی سپید و تابان و نیکو و بزرگوار، که در تو چیزهایی بود که یاد کرده نشود. مرد گفت آن چیزها چه بود؟ اسماء گفت :وی از ناسزا و زشتی دور بود و دهانی خوش بوی داشت و او را بوی بد در دهان نبود، توانگر بود و تنگدست نمی بود، آنگاه مرد پی برد به اینکه منظور اسماء کنایه زدن بر اوست . و چون بنزد اسماء رفت به وی گفت خود را به بوی خوش بیالاید، ولی عطردان او را افکنده دید، اسماء در جواب گفت «لاعطر بعد عروس » یعنی عطر و بوی خوشی پس از عروسی نیست . و اصل این مثل را چنین نیز گفته اند که مردی با زنی ازدواج کرد و چون زن را بنزد او بردند دید که عطر بخود نزده است به او گفت پس عطر و بوی خوش تو کجاست ؟ زن جواب داد آن را پنهان کرده ام . پس مرد گفت «لامخباء لعطر بعد عروس » یعنی پس از عروسی، پنهان کردن برای عطر نباشد. و رجوع به شرح قاموس شود: اجتلاء؛ جلوه دادن عروس را بر شوهر. ازفاف ؛ فرستادن عروس به خانه ٔ شوهر. اهتداء؛ به شوهر فرستادن عروس را. (از منتهی الارب ). تقیین ؛ عروس بیاراستن . (تاج المصادر بیهقی ). زَف ّ؛ عروس به خانه ٔ شوهر فرستادن . (دهار). فودج ؛ مرکب عروس . مجلوة؛ عروس جلوه داده . هداء؛ عروس را به خانه آوردن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زن داماد. (برهان ). زنی که تازه زناشویی کرده، در مقابل داماد. (فرهنگ فارسی معین ). زن نوکدخدا و زن داماد. (ناظم الاطباء). زن به خانه ٔ شوی رفته . (یادداشت مرحوم دهخدا). دختر نو شوی کرده . بانو. بیو. بیوگ . بیوگان . پیوگ . پیوگان . خوازنده . دغد. سنار. سنه . سنهار. نیوک . ویو <span class=\"hlight\">:</span> <br>زمانی برق پرخنده زمانی رعد پرناله <br>چنان مادر ابر سوک عروس سیزده ساله .<br> <font color=\"Red\">رودکی .</font><br>عروس جوان گفت با پیر شاه <br>که موی سپید است مار سیاه .<br> <font color=\"Red\">بدایعی بلخی .</font><br>جهانی شده فرتوت چون پاغنده سر و گیس <br>کنون گشت سیه موی و عروسی شد جماش . <br> <font color=\"Red\">بوشعیب .</font><br>عروسم نباید که رعنا شوم <br>بنزد خردمند رسوا شوم .<br> <font color=\"Red\">فردوسی .</font><br>جهان چون عروسی رسیده جوان <br>پراز چشمه و باغ و آب روان .<br> <font color=\"Red\">فردوسی .</font><br>دل پادشا سرد گشت از عروس <br>فرستاد بازش بر فیلقوس .<br> <font color=\"Red\">فردوسی .</font><br>ملک چون کشت گشت و تو باران <br>این جهان چون عروس و تو داماد.<br> <font color=\"Red\">فرخی .</font><br>گشت نگارین تذرو پنهان در مرغزار<br>همچو عروس غریق در بن دریای چین .<br> <font color=\"Red\">منوچهری .</font><br>بسیار شمع و مشعل افروختند تا عروس را ببردند به کوشک شاه . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٩٤</span>). جهان عروسی آراسته را مانست در آن روزگار مبارکش . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٥٢</span>). قلعت همچنین عروس بکر بود. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٤٣</span>).<br>رده در رده زان گل لعلگون <br>که خوانی عروسش به پرده درون .<br> <font color=\"Red\">اسدی (گرشاسب نامه ص <span class=\"hlight\" dir=\"rtl\">٩٥</span>).</font><br>کس عروسی در جهان هرگز ندید<br>گیسویش پر نور و رویش پر ظلام .<br> <font color=\"Red\">ناصرخسرو.</font><br>این دهر یکی عروس پر مکراست <br>ای قوم حذر کنید از این حره .<br> <font color=\"Red\">ناصرخسرو.</font><br>عالم بمثل بدخوی و ناساز عروسی ست <br>وز خلق جهان نیست جز او شوی حلالش .<br> <font color=\"Red\">ناصرخسرو.</font><br>هر کجا محنتی عروس برند<br>دلم آنجا شود بدامادی .<br> <font color=\"Red\">مسعودی .</font><br>نرم نرمک چو عروسی که غرند آمده بود<br>باز از آن سوی برندش که از آن آمد باز.<br> <font color=\"Red\">ابوالعباس .</font><br>ای برادر گر عروس خوبت آبستن شده ست <br>اندرین مدت که بودی غایب از نزد عروس .<br> <font color=\"Red\">علی شطرنجی .</font><br>خاتون دار ملک فریدونش خوان که نیست <br>کابین این عروس کم از گنج کاویان .<br> <font color=\"Red\">خاقانی .</font><br>و آن کعبه چون عروس که هر سال تازه روی <br>بوده مشاطه ای بسزا پور آزرش .<br> <font color=\"Red\">خاقانی .</font><br>ثنای او بدل ما فرونیاید از آنک <br>عروس سخت شگرف است و حجله نازیبا.<br> <font color=\"Red\">خاقانی .</font><br>تا من <font color=\"DarkGreen\"><b>[ علی بن الحسن ]</font></b> به مشاطگی این عروس قیام نمایم . (ترجمه ٔ تاریخ یمینی ).<br>مجو درستی عهد از جهان سست نهاد<br>که این عجوز عروس هزار دامادست .<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">بیت العروس </span>؛ حجله . حجله گاه . خانه ٔ عروس . عروس خانه <span class=\"hlight\">:</span> <br>فرو شست عالم چو بیت العروس .<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">تازه عروس </span> ؛زن که تازه عروسی کرده باشد. زن که اخیراً زناشوئی کرده است . نوعروس . زن نوشوی کرده .<br>- <span class=\"hlight\">خواهر عروس </span> ؛ نام قضیه ٔ عکس قضیه ٔ فیثاغورس است . رجوع به ترکیب شکل عروس شود.<br>- <span class=\"hlight\">شکل عروس در هندسه </span> ؛ همان قضیه ٔ فیثاغورس است که :در هر مثلث قائم الزاویه مجموع مربعات اضلاع زاویه ٔ قائمه مساوی است با مربع وتر. و این از اکتشافات فیثاغورس است . و آن را در هندسه به نام کرسی عروس خوانند. و قضیه ٔ عکس آن مشهور به «خواهر عروس » است . (از بحثی در قضیه ٔ فیثاغورس، ترجمه ٔ احمد آرام ).<br>- <span class=\"hlight\">عروسان باغ </span> ؛ کنایه از گلها و میوه ها و نهالهای نوبرآمده و درخت میوه دار باشد. (برهان ) (آنندراج ). کنایه از گلها و میوه هاست .(انجمن آرا). عروسان چمن . عروسان مرغزار.<br>- <span class=\"hlight\">عروسان بیابان </span> ؛ کنایه از شتر بارکش باشد عموماً، و شتران راه مکه خصوصاً. (آنندراج ) (برهان ). کنایه از شتران راه مکه . (انجمن آرا).<br>- <span class=\"hlight\">عروسان چمن </span> ؛ بمعنی عروسان باغ است، که کنایه از نهالها و گلها و میوه های نورسیده باشد. (برهان ) (از آنندراج ) (از انجمن آرا).عروسان باغ . عروسان مرغزار.<br>- <span class=\"hlight\">عروسان خُلد</span> ؛ کنایه ازحوران بهشتی باشد. (برهان ) (از انجمن آرا) <span class=\"hlight\">:</span> یکی از آن کنیزکان ... در جمال رشک عروسان خلد بود.(کلیله و دمنه ).<br>- <span class=\"hlight\">عروسان درخت </span> ؛ کنایه از شاخه های نورسته باشد. (از ناظم الاطباء).<br>- <span class=\"hlight\">عروسان عور</span> ؛ کنایه از ستارگان <span class=\"hlight\">:</span> <br>این عروسان عور رعنا را<br>بر سر از آب چادر اندازد.<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عروسان مَرغزار</span> ؛ کنایه از گلها و شکوفه ها و نهالها باشد. عروسان باغ . عروسان چمن <span class=\"hlight\">:</span> <br>نوروز پیش از آنکه سراپرده زد به در<br>با لعبتان باغ و عروسان مرغزار.<br> <font color=\"Red\">منوچهری .</font><br>- <span class=\"hlight\">عروس اَرغنون زَن </span> ؛ کنایه از ستاره ٔ زهره (ربة النوع طرب ) است و آسمان سوم جای اوست . (برهان ) (آنندراج ) (از انجمن آرا).<br>- <span class=\"hlight\">عروس تاک </span> ؛ شراب . (آنندراج ).<br>- <span class=\"hlight\">عروس جَهان </span> ؛کنایه از جهان باشد به طریق اضافه، یعنی عروسی که آن جهان است . (برهان ) (آنندراج ). این جهان . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>چو ترک حصاری ز کار اوفتاد<br>عروس جهان در حصار اوفتاد.<br> <font color=\"Red\">نظامی .</font><br>- <BR><font color=\"Blue\">◄</font> کنایه از کوکب زهره . (از برهان ) (آنندراج ).<br>- <BR><font color=\"Blue\">◄</font> کنایه از ماه . (آنندراج ).<br>- <span class=\"hlight\">عروس چرخ </span> ؛ کنایه از آفتاب جهان گرد است . (برهان ) (آنندراج ). عروس چهارم فلک . عروس خاوری . عروس روز. عروس نه فلک .<br>- <span class=\"hlight\">عروس چمن </span> ؛ کنایه از گل است . (فرهنگ فارسی معین ). عروسان چمن . رجوع به عروسان چمن شود.<br>- <span class=\"hlight\">عروس چهارم </span> ؛ کنایه از آفتاب است . (فرهنگ فارسی معین ) (ناظم الاطباء).<br>- <span class=\"hlight\">عروس چهارم فلک </span> ؛ کنایه از خورشید جهان آرا باشد. (برهان ) (آنندراج ). بمناسبت این که خورشید را در فلک چهارم فرض میکردند. عروس چرخ . عروس خاوری . عروس روز. عروس نه فلک .<br>- <span class=\"hlight\">عروس خاوری </span> ؛ به معنی عروس چرخ است که آفتاب جهان تاب باشد. (برهان ) (آنندراج ) <span class=\"hlight\">:</span> <br>در ده از آن چکیده خون زآبله ٔ تن رزان <br>کآبله ٔ رخ فلک برد عروس خاوری .<br><font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عروس خشک پستان </span> ؛ زنی که عقیمه بود یعنی هرگز نزاییده باشد. (برهان ) (آنندراج ). زن نازا. (ناظم الاطباء).<br>- <BR><font color=\"Blue\">◄</font> کنایه از دنیای بی بقا باشد. (برهان ) (آنندراج ). کنایه از دنیاست . (انجمن آرا). دنیای بی بقا و جهان فانی . (فرهنگ فارسی معین ). عروس شوی مرده . عروس مرده شوی .<br>- <span class=\"hlight\">عروس روز</span> ؛ به معنی عروس خاوری است که خورشید عالم افروز باشد. (برهان )(آنندراج ). عروس چهارم . عروس چرخ . عروس خاوری . عروس فلک . عروس نه فلک .<br>- <span class=\"hlight\">عروس زَر</span> ؛ کنایه ازآتش است <span class=\"hlight\">:</span> <br>از حجره ٔسنگ آمد در جلوه عروس زر <br>در حجله ٔ آهن شد گلنار همی پوشد.<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عروس سبا</span> ؛ اشاره به بلقیس ملکه ٔ سبا است <span class=\"hlight\">:</span> <br>بهر آوردن عروس سبا<br>رای جز آصفی نمی شاید.<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عروس شام </span> ؛ لقب شهر عسقلان است . عروس الشام . رجوع به عروس الشام شود.<br>- <span class=\"hlight\">عروس شوی مرده </span> ؛ کنایه از دنیای فانی باشد. (برهان ) (آنندراج ). عروس مرده شوی . عروس خشک پستان .<br>- <span class=\"hlight\">عروس صحرا</span> ؛شتر بارکش . (آنندراج ). رجوع به ترکیب عروسان بیابان شود.<br>- <span class=\"hlight\">عروس عَدن </span> ؛ کنایه از ماه باشد. و به عربی قمر خوانند. (برهان ) (آنندراج ).<br>- <BR><font color=\"Blue\">◄</font> کنایه از ستاره های آسمانی است . (برهان ) آنندراج ).<br>- <BR><font color=\"Blue\">◄</font> پرستار و خدمتکاری را گویند که شبها با او دخول توان کرد. (برهان ) (آنندراج ).<br>- <span class=\"hlight\">عروس عرب </span> ؛ کنایه از مکه ٔ معظمه است . (برهان ) (آنندراج ) (انجمن آرا). کعبه ٔ معظمه . (غیاث اللغات ) <span class=\"hlight\">:</span> <br>به خال و زلف ولب و حجله ٔ عروس عرب <br>که سنگ کعبه و حلقه ست و آستان و حجاب .<br> <font color=\"Red\">خاقانی (دیوان چ سجادی ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>).</font><br>- <span class=\"hlight\">عروس فلک </span> ؛ کنایه از آفتاب جهان آراست . (برهان ) (آنندراج ). عروس نه فلک . عروس چرخ . عروس چهارم . عروس روز <span class=\"hlight\">:</span> <br>بل عروس فلک ببرّد دست <br>کان نی مصر یوسف دگر است .<br> <font color=\"Red\">خاقانی .</font><br>ششم عروس فلک را امید دامادی <br>ز بخت بالغ بیدار خواب دیده ٔ اوست .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عروس قلندرها</span> ؛ زن که از آشنا و غریب روی نپوشد. (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">کرسی عروس </span> ؛ نام قضیه ٔ فیثاغورس است در هندسه . رجوع به شکل عروس شود.<br>- <span class=\"hlight\">گنج عروس </span> ؛ در موسیقی، نام یکی از تصنیفات باربد است . (برهان ). و رجوع به گنج عروس در ردیف خود شود.<br>- <span class=\"hlight\">لباس عروس </span> ؛ لباس که در هنگام زفاف پوشند. لباس که در جشن عروسی در برکنند. و رجوع به لباس عروسی شود <span class=\"hlight\">:</span> <br>بهر ولی تو ساخت وز پی خصم تو کرد<br>صبح لباس عروس شام پلاس مصاب .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">نوعروس </span> ؛ زن که تازه زناشوئی کرده باشد. تازه عروس <span class=\"hlight\">:</span> <br>دگر عادت آن بود کآتش پرست <br>همه ساله بانوعروسان نشست .<br> <font color=\"Red\">سعدی .</font><br>شکایت کند نوعروس جوان <br>به پیری ز داماد نامهربان .<br> <font color=\"Red\">سعدی .</font><br>بارها نوعروس جانفرسای <br>دست در دامنش زدی که درآی .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">حالا چند کلمه از مادر عروس بشنو</span> ؛ نظیر حالا دیگر این دول را بگیر. (امثال و حکم دهخدا).<br> <span class=\"hlight\">عروس از مهد ابخاز بستند</span> ؛ اشاره به آن است که روسیان دختران و زنان قوم ابخاز را گرفتند و کدبانوی خانه ٔ خود ساختند. (آنندراج، از شرح اسکندرنامه ).<br> <span class=\"hlight\">عروس بی جهاز روزه ٔ بی نماز دعای بی نیاز قورمه ٔ بی پیاز</span> . (امثال و حکم دهخدا).<br> <span class=\"hlight\">عروس تعریفی آخرش شلخته درمی آید</span> . (امثال و حکم دهخدا). عروس تعریفی عاقبت شلخته درآمد (یا از آب درآمد)؛ شخص مورد تحسین یاشی ٔ مورد تمجید فاسد و معیوب درآمد. عوام گویند: عروس تعریفی گوزار درآمد. (فرهنگ عوام ).<br> <span class=\"hlight\">عروس تنبانش دو تا است </span>، یا عروس چهار تنبان دارد مفت کپل گنده ش . نظیر: أیهاالممتن علی نفسک فلیکن المن علیک . (امثال و حکم دهخدا). عروس نه تنبان دارد مفت کون گنده اش ؛ اگر ثروت و نعمتی دارد فایده اش عاید خودش می شود، ما چرا زیر بار منت یا کبرفروشی او باشیم . (فرهنگ عوام ).<br> <span class=\"hlight\">عروس جوان داماد پیر</span> <br>سبد را بیار جوجه بگیر.<br> <font color=\"Red\">(امثال و حکم دهخدا).</font><br> <span class=\"hlight\">عروس حمام بر است </span> ؛ نسیجی بی دوام لکن خوش ظاهر است . (امثال و حکم دهخدا). پارچه ای خوش نما و بی دوام است . (فرهنگ عوام ). رجوع به «عروس حمام بر» در ردیف خود شود.<br> <span class=\"hlight\">عروس خانم ما هیچ عیبی نداره سرش کچله کونش کپه داره </span> . (فرهنگ عوام ).<br> <span class=\"hlight\">عروس خیلی خوب بود گرهم درآمد</span>، همانند احمدک خوشگل بود آبله هم درآورد. (فرهنگ عوام ).<br> <span class=\"hlight\">عروس را به پیرایه ٔ همسایه یک شب بیش نتوان پیراست </span> . (امثال و حکم دهخدا، از مقامات حمیدی ).<br> <span class=\"hlight\">عروس سر خودش را نمی توانست ببندد میرفت سر همسایه را ببندد</span> . (امثال و حکم دهخدا).<br> <span class=\"hlight\">عروس شدم خلاص شدم </span> ؛ اختیارم با خود شد و از قیدی که داشتم رستم . (فرهنگ عوام ).<br> <span class=\"hlight\">عروس که به ما رسید شب کوتاه شد</span> ؛ مدت بهره مندی از این نعمت بسیار کوتاه بود. (فرهنگ عوام ).<br> <span class=\"hlight\">عروس ماعیبی ندارد کور است کچل است سرگیجه دارد</span> . نظیر: نجنب که گنجی . عنز بها داء. (امثال و حکم دهخدا).<br> <span class=\"hlight\">عروس مردنی را گردن خارسو نگذارید</span> ؛ این چیز خود معیوب است، عیبش را متوجه دیگری نسازید. (فرهنگ عوام ).<br> <span class=\"hlight\">عروس می آید وسمه بکشد نه وصله بکند</span> . (امثال و حکم دهخدا).<br> <span class=\"hlight\">عروس نمی توانست برقصد می گفت اتاق کج است </span> . (امثال و حکم دهخدا).<br> <span class=\"hlight\">عروسی که خارسو ندارد، اهل محل خارسوی اویند</span> ؛ زنی با بچه ای که صاحب و سالار ندارد همه کس در کار او مداخله و فضولی می کند. (امثال و حکم دهخدا).<br> <span class=\"hlight\">عروسی را که مادر زن تعریف کند لایق گیس خودش است </span> . (فرهنگ عوام ).<br> <span class=\"hlight\">عروسی را که مادرش تعریف کند، یا تمجید کند برای آقادائیش خوب است </span> . (امثال و حکم دهخدا).<br> <BR><font color=\"Blue\">◄</font> کنایه از هر چیز زیبا و آراسته .(فرهنگ فارسی معین ):<br>چون عروس ؛ بسان عروس . مثل عروس .سخت زیبا. نیک آراسته . (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> <br>یکی خوب کشتی بسان عروس <br>بر آراسته همچو چشم خروس .<br> <font color=\"Red\">فردوسی .</font><br>یکی لشکر آراسته چون عروس <br>به شیران جنگی و آوای کوس .<br> <font color=\"Red\">فردوسی .</font><br> <BR><font color=\"Blue\">◄</font> در تداول عامه، بسیار محجوب . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> منکوحه ٔ پسر. (از ناظم الاطباء). زن پسر شخص . (فرهنگ فارسی معین ). زن نسبت به پدر شوهر و مادر شوهر، چنانکه : فاطمه (ع ) عروس ابی طالب است . (یادداشت مرحوم دهخدا). زن نسبت به خویشان شوهر، و آن را به عربی کنّه گویند. <BR><font color=\"Blue\">◄</font> (اِخ ) نام گنج اول است از گنجهای خسروپرویز. (برهان ). گنج عروس . رجوع به گنج عروس در ردیف خود شود <span class=\"hlight\">:</span> <br>نخستین که بنهاد گنج عروس <br>ز چین و ز برطاس و از هند و روس .<br> <font color=\"Red\">فردوسی .</font><br> <BR><font color=\"Blue\">◄</font> یکی از گنجهای کیکاوس است، که به طوس داده بود.کیخسرو آن را به گودرز سپرد که به زال و رستم و گیوبدهد. (برهان ) <span class=\"hlight\">:</span> <br>دگر گنج کش خواندندی عروس <br>که آکند کاوس در شهر طوس .<br> <font color=\"Red\">فردوسی .</font><br><BR><font color=\"Blue\">◄</font> نام آسمان هشتم . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (ع اِ) گوگرد زرد، که اهل عمل آن را نفس خوانند. (از برهان ). به لغت اکسیریان، کبریت است . (تحفه ٔ حکیم مؤمن ). کبریت زرد. (مخزن الادویه ). <BR><font color=\"Blue\">◄</font> قاتل النحل است، که نیلوفر باشد. (مخزن الادویه ). اهل شیراز، آب مقطر از معصفر در اول مرتبه را عروس، و آب سرخ بعد از آن را داماد نامند. (مخزن الادویه ). <BR><font color=\"Blue\">◄</font> چوبی که زه کمان خراط بدان پیچیده کشند. (از آنندراج ).<br></font></div>'),
(182678, 'عروس آرا', '<span class=\"hlight\">عروس آرا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (نف مرکب ) عروس آرای . عروس آراینده . مشاطه . رجوع به عروس آرای شود.<br></font></div>'),
(182679, 'عروس آرای', '<span class=\"hlight\">عروس آرای .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (نف مرکب ) عروس آرا. عروس آراینده . آنکه عروس را بیاراید و زینت دهد. مشّاطه . (دهار). ماشطة <span class=\"hlight\">:</span> که تو باغبان سروپیرایی و مشاطه ٔ عروس آرایی . (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>).<br></font></div>'),
(182680, 'عروس الشام', '<span class=\"hlight\">عروس الشام .</span> <font color=\"DarkGreen\"><b>[ ع َ سُش ْ شا ]</font></b> (اِخ ) لقب شهر عسقلان است . (از منتهی الارب ). رجوع به عسقلان شود.<br></font></div>'),
(182681, 'عروس باز', '<span class=\"hlight\">عروس باز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (نف مرکب ) شخص خوش ظاهر خودآرا. (آنندراج ). <BR><font color=\"Blue\">◄</font> عروسک باز. رجوع به عروسک باز و عروس بازی شود.<br></font></div>'),
(182682, 'عروس بازی', '<span class=\"hlight\">عروس بازی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (حامص مرکب ) بازی دختران با عروسک ها (لعبت ها). (یادداشت مرحوم دهخدا). عروسک بازی . رجوع به عروسک بازی شود. <BR><font color=\"Blue\">◄</font> نوعی بازی است میان دو تا چهار نفر، با چهار مهره از یک رنگ و یک مهره به رنگی دیگر در عرصه ٔ نرد. (از یادداشت مرحوم دهخدا).<br></font></div>'),
(182683, 'عروس بر', '<span class=\"hlight\">عروس بر.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (نف مرکب ) ساقدوش . (ناظم الاطباء).<br></font></div>'),
(182684, 'عروس بری', '<span class=\"hlight\">عروس بری .</span> <font color=\"DarkGreen\"><b>[ع َ ب َ ]</font></b> (حامص مرکب ) زن گرفتن . ازدواج <span class=\"hlight\">:</span> شاه جواب داد که مرا عروس بری به کار نیست که من خود عروسان بسیار دارم . (اسکندرنامه نسخه ٔ سعید نفیسی ).<br></font></div>'),
(182685, 'عروس بینی', '<span class=\"hlight\">عروس بینی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (حامص مرکب ) خواستگاری . رفتن مادر و خواهر و دیگر کسان زنانه ٔ داماد به خانه ٔ کسان دختردار، برای گزیدن یکی از آنان پسر یا برادر یا کس دیگر خود را. رفتن زنان مرد خواستگار برای دیدن و پسندیدن یا رد کردن دختری یا زنی . (یادداشت مرحوم دهخدا).<br></font></div>'),
(182686, 'عروس خانه', '<span class=\"hlight\">عروس خانه .</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) جایی که محل عروسی است . خانه ای که در آن عروسی برپاست . (فرهنگ فارسی معین ). خانه ٔ عروس . بیت العروس . رجوع به بیت العروس شود.<br></font></div>'),
(182687, 'عروس خفه کن', '<span class=\"hlight\">عروس خفه کن .</span> <font color=\"DarkGreen\"><b>[ ع َ خ َ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ک ُ ]</font></b> (نف مرکب ) عروس خفه کننده . آنچه عروس را خفه کند. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) در اصطلاح عامه، استخوان نرم و غضروف . (فرهنگ فارسی معین ).<br></font></div>'),
(182688, 'عروس درپرده', '<span class=\"hlight\">عروس درپرده .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ پ َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) دوایی است که آن را کاکنج گویند. تخم آن را تا هفت روز هر روز هفت عدد هر زنی که بخورد هرگز آبستن نگردد. (برهان ) (آنندراج ). کاکنج .(منتهی الارب ). حب اللهو. (یادداشت مرحوم دهخدا). گیاهی است که میوه ٔ سرخ رنگ دارد. عروس پرده . عروس پشت پرده . عروسک پس پرده . رجوع به کاکنج شود <span class=\"hlight\">:</span> <br>به مُرز بی رزتو مرغکی درون بپرید<br>سرش به لعلی همچون عروس درپرده .<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(182689, 'عروس دریایی', '<span class=\"hlight\">عروس دریایی .</span> <font color=\"DarkGreen\"><b>[ ع َ س ِ دَرْ ]</font></b> (ترکیب وصفی، اِ مرکب ) جانوری است سخت پوست از شاخه ٔ بندپاییان و از رده ٔ سخت پوستان و جزو راسته ٔ ده پاییان، که دارای شکم نسبةً بزرگی است و انتهای بدنش به یک پره ٔ شنای قوی بنام تلسن  ختم میشود. این جانور کاملاً شبیه خرچنگهای دراز رودخانه ای است و بسیار شکیل و زیباست و وجه تسمیه اش نیز بهمین علت است . انبرکهایش بسیار قوی است بطوری که با یک ضربت سریعاً سخت ترین استخوانهای جانورانی را که شکار می کند و یا صدف حیوانات دریایی را قطع می کند و در شنا نیز بسیار سریع حرکت می کند. طول بدنش تا <span class=\"hlight\" dir=\"rtl\">٥٠</span> سانتی متر میرسد و وزنش تا <span class=\"hlight\" dir=\"rtl\">٥</span> کیلوگرم نیز مشاهده شده است . این جانور گوشتش مورد توجه اروپائیان است و بهمین جهت در دریاهای شمال صید میشود. خرچنگ دریایی . <BR><font color=\"Blue\">◄</font> مِدوز، که نوعی جانور کیسه تن است . (از فرهنگ فارسی معین ). رجوع به مِدوز شود.<br></font></div>'),
(182690, 'عروس شدن', '<span class=\"hlight\">عروس شدن .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ُ دَ ]</font></b> (مص مرکب ) به همسری مردی درآمدن دختر یا زن . (فرهنگ فارسی معین ).<br></font></div>'),
(182691, 'عروس محله', '<span class=\"hlight\">عروس محله .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ح َل ْ ل َ ]</font></b> (اِخ ) دهی جزء دهستان حومه ٔ بخش مرکزی شهرستان لاهیجان . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢١٦</span> تن . محصول آن برنج و مختصری چای . آب آن از پلرود است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(182692, 'عروس وار', '<span class=\"hlight\">عروس وار.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص مرکب، ق مرکب ) چون عروس . چون بیوک . عروس مانند <span class=\"hlight\">:</span> <br>گاهی عروس وار به پیش آید<br>با گوشوار و یاره و با افسر.<br> <font color=\"Red\">ناصرخسرو.</font><br>تو هفت طوف کرده و مکه عروس وار<br>هرهفت کرده پیش تو و عشق دان شده .<br> <font color=\"Red\">خاقانی .</font><br>آراسته کن عروس وارم <br>بسپار به خاک پرده دارم .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(182693, 'عروس پرده', '<span class=\"hlight\">عروس پرده .</span> <font color=\"DarkGreen\"><b>[ ع َ س ِ پ َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ترکیب اضافی، اِ مرکب ) کاکنج، که نوعی گیاه است . عروس پشت پرده . عروسک پس پرده . عروسک پشت پرده . عروس در پرده . رجوع به کاکنج شود. قسمی از گل سرخ یاقوتی رنگ و هر چیز که به رنگ آن بود. (ناظم الاطباء).<br></font></div>'),
(182694, 'عروس پرست', '<span class=\"hlight\">عروس پرست .</span> <font color=\"DarkGreen\"><b>[ ع َ پ َ رَ ]</font></b> (نف مرکب ) عروس پرستنده . دوستدارنده ٔ عروس <span class=\"hlight\">:</span> <br>نوعروسان گرفته شمع به دست <br>شاه نوتخت شد عروس پرست .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(182695, 'عروس پشت پرده', '<span class=\"hlight\">عروس پشت پرده .</span> <font color=\"DarkGreen\"><b>[ع َ س ِ پ ُ ت ِ پ َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ترکیب اضافی، اِ مرکب ) کاکنج، که نوعی گیاه است . عروس پرده . عروس در پرده . عروسک پس پرده . عروسک پشت پرده . رجوع به کاکنج شود.<br></font></div>'),
(182696, 'عروس کردن', '<span class=\"hlight\">عروس کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ دَ ]</font></b> (مص مرکب ) زن یا دختری راشوی دادن . زن یا دختری را به خانه ٔ شوهر فرستادن .<br></font></div>'),
(182697, 'عروسافارس', '<span class=\"hlight\">عروسافارس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِ مرکب ) سلخ الحیة است . (مخزن الادویة).<br></font></div>'),
(182698, 'عروسان', '<span class=\"hlight\">عروسان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) دهی است از دهستان جندق بیابانک بخش خوربیابانک شهرستان نائین . سکنه <span class=\"hlight\" dir=\"rtl\">١٠٥</span> تن . آب آن از قنات و محصول آنجا غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(182699, 'عروسانه', '<span class=\"hlight\">عروسانه .</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص نسبی، ق مرکب ) مانند عروس . بیوک مانند. (ناظم الاطباء). عروس مانند <span class=\"hlight\">:</span> <br>خاک را جای عروسی است که دردانه در اوست <br>نونوش عقد عروسانه به بر بربندیم .<br> <font color=\"Red\">خاقانی .</font><br>دگر روز چون آفتاب بلند<br>عروسانه سر برکشید از پرند.<br> <font color=\"Red\">نظامی .</font><br>عروسانه برشد بر آن جلوه گاه <br>پرندی سیه بسته بر گرد ماه .<br> <font color=\"Red\">نظامی .</font><br>بعمدا زیوری بربستش آن ماه <br>عروسانه فرستادش برِ شاه .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(182700, 'عروسه', '<span class=\"hlight\">عروسه .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (از ع، اِ) بمعنی عروس، که زن نوکدخدا باشد. (آنندراج ). بیوک و عروس . (ناظم الاطباء).<br></font></div>'),
(182701, 'عروسک', '<span class=\"hlight\">عروسک .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (اِ مصغر) تصغیر عروس .(برهان ). عروس کوچک . عروس خرد. رجوع به عروس شود. <BR><font color=\"Blue\">◄</font> لعبتی که دخترکان سازند. (برهان ). لعبت که دختران به آن بازی کنند. (غیاث اللغات ). لعبت را گویند که دختران بدان بازی کنند، و آن را بفارسی لهفت خوانند. (از آنندراج ) (از ناظم الاطباء). لعبتی که کودکان (مخصوصاً دخترکان ) بدان بازی کنند. (فرهنگ فارسی معین ). لعبت . دمیة. ملعبه . آدمک . بازیچه . آنچه از پارچه یا موم یا پلاستیک و دیگر چیزها بشکل دخترکان زیبا سازند برای بازیچه . تندیسهای خرد از پارچه و غیره برای بازی کودکان مادینه <span class=\"hlight\">:</span> حالت قشنگی که بخودش گرفته بود بیشتر او را شبیه یک آدم مصنوعی یا یک عروسک کرده بود. (سایه روشن صادق هدایت ص <span class=\"hlight\" dir=\"rtl\">١٣</span>).<br>- <span class=\"hlight\">عروسک پس ِ پرده </span> ؛ اسم فارسی حب کاکنج است . (تحفه ٔ حکیم مؤمن ). اسم فارسی عامه ٔ فرس، کاکنج است . (مخزن الادویة). عروس پشت پرده . عروس درپرده . عروسک پشت پرده . رجوع به کاکنج شود.<br>- <span class=\"hlight\">عروسک پشت پرده </span> ؛ کاکنج، که نوعی گیاه است . عروس پس پرده . عروس پشت پرده . عروس درپرده . عروسک پس پرده . رجوع به کاکنج شود.<br>- <span class=\"hlight\">عروسک پهلوان کچل بودن </span> ؛ بی عرضه بودن . ازخود اراده و فکر نداشتن : وزیران دوره ٔ استبداد حکم عروسک های پهلوان کچل را داشتند و نمی توانستند از خوددارای فکر و اراده ای باشند. (فرهنگ عوام ).<br>- <span class=\"hlight\">عروسک خیمه شب بازی </span> ؛ عروسکی که در خیمه شب بازی بکار رود و با سیم یا نخی آنها را به حرکت درآرند و یک تن از داخل خیمه بزبان آنها سخن میگوید. رجوع به خیمه شب بازی شود.<br>- <BR><font color=\"Blue\">◄</font> کنایه از شخص بی اراده که آلت دست دیگران شود.<br>- <span class=\"hlight\">عروسک درپرده </span> ؛ کاکنج، که گیاهی است . عروسک پس پرده . عروسک پشت پرده . عروس پس پرده . عروس پشت پرده . عروس درپرده . رجوع به کاکنج شود.<br> <BR><font color=\"Blue\">◄</font> دختر نابالغ که او را به شوهر دهند. (برهان ). <BR><font color=\"Blue\">◄</font> منجنیق کوچک را گویند، و آن آلتی باشد که در قلعه ها سازند و بدان سنگ و آتش و خاکستر به جانب دشمن اندازند.(برهان ). منجنیق کوچک، و آن از آلات جنگ قلعه گیری است . (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> نام پرنده ای است که شبها بیدار باشد و بانگ کند. (برهان ). <BR><font color=\"Blue\">◄</font> اسم فارسی طینوس است . (مخزن الادویة). اسم فارسی طنبوث است . (تحفه ٔ حکیم مؤمن ). <BR><font color=\"Blue\">◄</font> کرم شب تاب . (برهان ). حباحب است که بفارسی کرم شب تاب نامند. (مخزن الادویة). ذروح . (از دهار). کاغنه . (از زمخشری ). ذرجدح . (از دهار). واحد ذراریح که جمع ذرّوح است . گوژخار. باغوجه . مگسک . واغنه . رجوع به ذروح شود. <BR><font color=\"Blue\">◄</font> بوم ماده را گویند، و آن پرنده ای است منحوس . (برهان ). <BR><font color=\"Blue\">◄</font> رنگ لعلی . (برهان ). <BR><font color=\"Blue\">◄</font> میوه ای است از اقسام زردآلو. (آنندراج ) (از غیاث اللغات ) <span class=\"hlight\">:</span> <br>وصف زردآلو ار کنم بنیاد<br>سازم اول ازو عروسک شاد.<br><font color=\"Red\">شرف الدین علی یزدی (در صفت فواکه، از آنندراج ).</font><br></font></div>'),
(182702, 'عروسک انداز', '<span class=\"hlight\">عروسک انداز.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ اَ ]</font></b> (نف مرکب ) عروسک اندازنده . آنکه عروسک (منجنیق ) می اندازد. آنکه عروسک و منجنیق را بکار می اندازد. رجوع به عروسک شود <span class=\"hlight\">:</span> <br>بر قلعه ٔ آن عروس طناز<br>غضبان فلک عروسک انداز.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(182703, 'عروسک باز', '<span class=\"hlight\">عروسک باز.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (نف مرکب ) عروسک بازنده . دختری که با عروسک بازی کند یعنی با لعبت بازی کند. (آنندراج ). رجوع به عروسک شود <span class=\"hlight\">:</span> <br>عروسک باز با طفل خیالش <br>هراسان مردم دیده ز خالش .<br><font color=\"Red\">حکیم زلالی (در حکایت دختر زال، از آنندراج ).</font><br></font></div>'),
(182704, 'عروسک بازی', '<span class=\"hlight\">عروسک بازی .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (حامص مرکب ) عمل عروسک باز. بازی با عروسک . (فرهنگ فارسی معین ). سرگرمی دختران با چیدن اتاق و اسباب عروسک . (یادداشت مرحوم دهخدا). رجوع به عروسک شود.<br></font></div>'),
(182705, 'عروسک زن', '<span class=\"hlight\">عروسک زن .</span><font color=\"DarkGreen\"><b>[ ع َ س َ زَ ]</font></b> (نف مرکب ) عروسک زننده . آنکه مباشر «عروسک » و منجنیق باشد. (از آنندراج ). آنکه عروسک (منجنیق ) را بکار اندازد. رجوع به عروسک شود <span class=\"hlight\">:</span> <br>عروسک زنانی چو دیوان شموس <br>خجل گشته زآن قلعه ٔ چون عروس .<br> <font color=\"Red\">نظامی .</font><br>بر آن شد که رو در حصارش زند<br>عروسک زنان زیر خاکش کند.<br><font color=\"Red\">میرخسرو (از آنندراج ).</font><br></font></div>'),
(182706, 'عروسک فرنگی', '<span class=\"hlight\">عروسک فرنگی .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ک ِ ف َ رَ ]</font></b> (ترکیب وصفی، اِ مرکب ) عروسک منسوب به فرنگ . که در فرنگ ساخته شده باشد. که ساخت فرنگ باشد.<br>- <span class=\"hlight\">مِثل ِ عروسک فرنگی </span> ؛ با چشمان زاغ و چهره ٔ سرخ و سفید. (یادداشت مرحوم دهخدا).<br></font></div>'),
(182707, 'عروسک نخودی', '<span class=\"hlight\">عروسک نخودی .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ک ِ ن ُ خ ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) مثل عروسک نخودی ؛ سخت خُرد و جمعوجور.<br></font></div>'),
(182708, 'عروسی', '<span class=\"hlight\">عروسی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (حامص ) همسری دختر یا زنی با مردی . بیوکانی . (فرهنگ فارسی معین ). دیبار. میزاد. نیوکانی . (ناظم الاطباء). کدخدایی . اًملاک . زفاف .<br>- <span class=\"hlight\">شب عروسی </span> ؛ لیلةالزفاف . شب که عروس بخانه ٔ داماد رود و مراسم زفاف صورت گیرد.<br> <BR><font color=\"Blue\">◄</font> شادی نکاح . (آنندراج ) (غیاث اللغات ). جشنی که به هنگام ازدواج برپا کنند. (فرهنگ فارسی معین ). میزد. رجوع به میزد شود <span class=\"hlight\">:</span> تکلفی فرمود امیر محمود عروسیی را که مانند آن کس یاد نداشت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٤٩</span>). دختر سالار بکتغدی رابه پرده ٔ این پادشاه زاده آوردند... و عروسیی کردند که کس مانند آن یاد نداشت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٣٥</span>). در عقد نکاح و عروسی وی طغرل تکلفها بی محل نمود. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٥٤</span>).<br>در عروسی ّ گل عجب نبود<br>گر به حنّا کنند دست چنار.<br> <font color=\"Red\">خاقانی .</font><br>وقت عروسی شود شاه حکایت کنند<br>هرکه به موی دروغ زلف نهد بر عذار.<br> <font color=\"Red\">خاقانی .</font><br>آن درد دل که برده ای آنگه عروسی است <br>در جنب محنتی که ز هجران کنون بری .<br> <font color=\"Red\">خاقانی .</font><br>چه خوش گفت آن نهاوندی به طوسی <br>که مرگ خر بود سگ را عروسی .<br> <font color=\"Red\">نظامی .</font><br>عروسی بود نوبت ماتمت <br>گرت نیکروزی بود خاتمت .<br> <font color=\"Red\">سعدی .</font><br>چنانکه رسم عروسی بود مهیا کرد.<br> <font color=\"Red\">(گلستان ).</font><br>اُدبة؛ طعام عروسی و کدخدائی . ذِمّة؛ طعام عروسی . (از منتهی الارب ).<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">خرکی را به عروسی خواندند</span> <br>خر بخندید و شد از قهقهه سست .<br> <font color=\"Red\">خاقانی .</font><br> <span class=\"hlight\">عروسی بچشم تماشائی آسان است </span> . (امثال و حکم دهخدا).<br>اکنون چه خوشی و گر خوشی دست دهد<br>صد کاسه به نانی چو عروسی بگذشت .<br> <font color=\"Red\">انوری (از امثال و حکم دهخدا).</font><br> <span class=\"hlight\">عروسی چون کنی بردار بانگی </span> .<br> <span class=\"hlight\">قرض عروسی را خدا می دهد</span> .<br> <span class=\"hlight\">مرغ را در عروسی و عزا هر دو سر میبرند</span> .<br> <span class=\"hlight\">هر جا عروسی است پاچه ورمی مالد، هر جا عزا است یخه می درد</span> . (امثال و حکم دهخدا).<br> <span class=\"hlight\">هرکه عروسی رفت عزا هم میرود</span> . (امثال و حکم دهخدا).<br>- <span class=\"hlight\">شمع عروسی </span> ؛ مشعل و چراغهائی که در شب زفاف روشن می کنند. (ناظم الاطباء).<br>- <span class=\"hlight\">عروسی قریش </span> ؛ مجلس تعزیه ٔ زنانه که هنوز مراسم آن در میان زنان تهران و برخی از شهرستانها متداول است، و در آن عروسی دختری از قبیله ٔ قریش و عروسی فاطمه دختر رسول خدا (ص ) را تجسم دهند. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">لباس عروسی </span> ؛ لباس که هنگام جشن زفاف پوشند. لباس عروس .<br></font></div>'),
(182709, 'عروسی', '<span class=\"hlight\">عروسی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) احمدبن موسی بن داود عروسی، ملقب به شهاب الدین . از فضلای مصر بود و در منیة عروس، از توابع منوفیه ٔ مصر متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">١٢٠٨</span> هَ .ق . درگذشت . او راست : حاشیة علی الملوی علی السمرقندیة، و شرح علی نظم التنویر فی اسقاط التدبیر. (از الاعلام زرکلی ).<br></font></div>'),
(182710, 'عروسی', '<span class=\"hlight\">عروسی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام او مصطفی بن محمدبن احمدبن موسی عروسی است . او فقیه شافعی مذهب مصری بود و به سال <span class=\"hlight\" dir=\"rtl\">١٢١٣</span> هَ .ق . متولد شد و در سال <span class=\"hlight\" dir=\"rtl\">١٢٨١</span> عهده دار مشیخه ٔ الازهر گشت، و بسبب برخی مقررات جدید که ابداع کرد (از آن جمله برقرار کردن امتحان مدرسان ازهر بوده است ) به سال <span class=\"hlight\" dir=\"rtl\">١٢٨٧</span> هَ .ق . بطورناگهانی از سمت خود عزل شد. او را کتابهائی است، ازجمله : <span class=\"hlight\" dir=\"rtl\">١</span>- احکام المفاکهات فی أنواع الفنون المتفرقات . <span class=\"hlight\" dir=\"rtl\">٢</span>- الانوار البهیة فی بیان أحقیة مذهب الشافعیة.<span class=\"hlight\" dir=\"rtl\">٣</span>- العقود الفرائد فی بیان معانی العقائد. <span class=\"hlight\" dir=\"rtl\">٤</span>- کشف الغمة فی تقیید معانی أدعیة سیدالامة. <span class=\"hlight\" dir=\"rtl\">٥</span>- نتائج الافکار القدسیة، که حاشیه ای است بر شرح زکریا انصاری بر رساله ٔ قشیریة در تصوف، در چهار جزء. (از الاعلام زرکلی از تاریخ الازهر و خطط مبارک و الازهر فی الف عام ).<br></font></div>'),
(182711, 'عروسی رفتن', '<span class=\"hlight\">عروسی رفتن .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ت َ]</font></b> (مص مرکب ) حضور یافتن در جشن عروسی کسی (بنابه دعوت قبلی ). شرکت در جشن عروسی . (فرهنگ فارسی معین ).<br></font></div>'),
(182712, 'عروسی کردن', '<span class=\"hlight\">عروسی کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ دَ ]</font></b> (مص مرکب ) زن گرفتن . (ناظم الاطباء). همسر اختیار کردن . (فرهنگ فارسی معین ). ازدواج . عرس . <BR><font color=\"Blue\">◄</font> شوی کردن دختر. بخانه ٔ شوی رفتن دختر یا زن .<br>- <span class=\"hlight\">امثال </span> :<br><span class=\"hlight\">عروسی نکرده بچه در گهواره خواباندن </span>، نظیر: گاو یا خر نخریده آخُر بستن . چاه نکنده منار دزدیدن . (فرهنگ عوام ).<br></font></div>'),
(182713, 'عروسین', '<span class=\"hlight\">عروسین .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (اِخ ) قلعه ای است به یمن . (منتهی الارب ). قلعه و حصنی است ازآن ِ عبداﷲبن سعید ربیعی کردی در یمن . (از معجم البلدان ).<br></font></div>'),
(182714, 'عروش', '<span class=\"hlight\">عروش .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) (دارالَ ...) قریه یا آبی است در یمامه . (از معجم البلدان ).<br></font></div>'),
(182715, 'عروش', '<span class=\"hlight\">عروش .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) وادیج بستن رَز را. (منتهی الارب ) (آنندراج ). قرار دادن شاخه های درخت رَز بر چوب . (از اقرب الموارد). داربست ساختن رز را. چفته بندی کردن برای درخت رز. <BR><font color=\"Blue\">◄</font> اقامت نمودن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گرد گرفتن چاه را بقدر یک قامت زیرین، از سنگ و تمامه ٔ بالایین از چوب . (از ناظم الاطباء) (آنندراج ). عَرش . رجوع به عرش شود.<br></font></div>'),
(182716, 'عروش', '<span class=\"hlight\">عروش .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عَرش . (منتهی الارب ) (اقرب الموارد). رجوع به عرش شود <span class=\"hlight\">:</span> همی بینید که عروش و بارگاه دواوین او مهدوم و مهدود... (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٥٤</span>). <BR><font color=\"Blue\">◄</font> خانه های مکه . (ناظم الاطباء). بیوت مکه . (اقرب الموارد). رجوع به عرش شود.<br></font></div>'),
(182717, 'عروص', '<span class=\"hlight\">عروص .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) ناقه ای که عرقش بوی خوش دارد. (منتهی الارب ). ماده شتر خوش بو، آنگاه که عرق و خوی کند. (از اقرب الموارد).<br></font></div>'),
(182718, 'عروض', '<span class=\"hlight\">عروض .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عَرض . (منتهی الارب ) (اقرب الموارد). رجوع به عرض شود.<br></font></div>'),
(182719, 'عروض', '<span class=\"hlight\">عروض .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) پیش آمدن کسی را حاجت . (از منتهی الارب ). عارض شدن . ظهور. (آنندراج ) (غیاث اللغات ). طاری شدن . سانح شدن . عَرض . رجوع به عرض شود.<br></font></div>'),
(182720, 'عروض', '<span class=\"hlight\">عروض .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) نام اسب قره ٔ اسدی است . (از منتهی الارب ).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(182721, 'عروض', '<span class=\"hlight\">عروض .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) شتر ماده ٔ ریاضت نایافته . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> کرانه و گوشه . (منتهی الارب ). ناحیه . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> راه در کوه . (منتهی الارب ). راه که در دامنه ٔ کوه و در تنگنا باشد. ج، عُرُض . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مضمون کلام . (منتهی الارب ). فحوی و معنای کلام . (از اقرب الموارد): عرفت فی عروض کلامه ؛ از فحوی و معنی کلام او دانستم . (منتهی الارب ) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> جایی که پیش آید کسی را وقت رفتن . (منتهی الارب ). مکانی که هنگام حرکت به پیش تو درآید. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بسیار از چیزی . (منتهی الارب ). کثیر از شی ٔ. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ابر. (منتهی الارب ). غیم و سحاب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> طعام . (از منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گوسپند و شتر که خار خورد از بی علفی، یا عام است . (منتهی الارب ). آنچه از گوسفند و غنم که به خار روی بیاورد و آن را بچرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> حاجت . و از آن جمله است که گویند: هورکوض بلا عروض ؛ یعنی او دونده و حرکت کننده ای است بدون حاجتی که برای او پیش آمده باشد. (از منتهی الارب ) (از اقرب الموارد). و آن را بصورت هو ربوض بلاعروض نیز گفته اند. <BR><font color=\"Blue\">◄</font> نظیر و مانند، گویند: هذه المسألة عروض هذه ؛ یعنی این مسأله نظیر این یکی است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عروض خیمه ؛ چوبی باشد که خیمه بدان قائم ماند. (المعجم ). <BR><font color=\"Blue\">◄</font> (اصطلاح عروض ) جزو آخر مصراع اول از شعر، اسم است، آن را سالم باشد یا متغیر، و مؤنث آید. (منتهی الارب ). جزء اخیر از شعر اول، سالم باشد یا متغیر، و مؤنث است . (از اقرب الموارد). آخرین جزء از شطر اول بیت . (از تعریفات جرجانی ). رکن آخر از مصراع اول بیت . (از کشاف اصطلاحات الفنون ). جزء آخرین ِ مصراع اول به اصطلاح عروضیان، عروض باشد. (المعجم ). جزء اخیر از نصف اول از بیتی . (یادداشت مؤلف ). جزو اخیر مصرعه ٔ اول هر بیت را عروض گویند. (از غیاث اللغات ) (از آنندراج ). ج، اَعاریض، و آن جمع بر غیر قیاس باشد و گویی که جمع اعریض است . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> علمی است معروف که بدان اوزان بحور دریافته میشوند. (غیاث اللغات ) (آنندراج ). میزان شعر.(منتهی الارب ) (اقرب الموارد) (قاموس ). ترازوی شعر. (تفلیسی ). علمی است که میزان شعر از آن موزون کنند. (از کشاف اصطلاحات الفنون ). معرفت اصولی چند که از آنجا احوال بحور و اوزان شعر معلوم کنند. (از نفایس الفنون ). میزان کلام منظوم است همچنانکه نحو میزان کلام منثور است . (المعجم ). و آن مؤنث است . ج، أعاریض . (از منتهی الارب ) (از اقرب الموارد). فن شناختن وزنها وبحرهای اشعار. میزان سخن منظوم که از اشعار بحث کند. (فرهنگ فارسی معین ). نام علمی از دوازده قسم علم نزد عرب که در این دو بیت نام آنها را گنجانیده اند:<br>صرف و نحو، عروض بعده لغة<br>ثم اشتقاق و قرض الشعر، انشاء<br>علم المعانی، بیان، الخط، قافیة<br>تاریخ، هذا لعلم العرب احصاء.<br>وجه تسمیه : سبب نامیدن آن را به «عروض » چنین گفته اند که موزون از ناموزون بوسیله ٔ آن شناخته میشود، و یا چون آن ناحیه و قسمتی از علوم است، و یا بسبب آنکه صعب و سخت می باشد، و یا به این جهت است که شعر را بر آن عرضه میدارند، و یا اینکه چون در مکه  بر خلیل بن احمد الهام شد بدین نام خوانده شده است . (از منتهی الارب ). سیفی در وجه تسمیه ٔ آن وجوه بسیار نوشته است، مِن جمله ٔ آن، دو وجه است که خلیل بن احمد در مکه ٔ مبارکه به این علم ملهم شده، یکی از اسمای مکه عروض است، این علم را به اسم مکه خوانند تیمناً. یا آنکه عروض به معنی معروض است، این علم نیز معروض ٌعلیه شعر است که شعر را بر آن عرض می کنند تا موزون از ناموزون جدا شود.(از غیاث اللغات ) (از آنندراج ). آن را <font color=\"DarkGreen\"><b>[ عروض را ]</font></b> ازبهر آن عروض خواندند که معروض ٌعلیه شعر است، یعنی شعر را بر آن عرض کنند تا موزون آن از ناموزون پدید آید و مستقیم از نامستقیم ممتاز گردد، و آن فعولی است به معنی مفعول، چنانکه رَکوب به معنی مرکوب و حَلوب به معنی محلوب . (المعجم ).<br>مخترع یا مدوِّن علم عروض : مشهور چنان است که علم عروض را اول بار خلیل بن احمد عروضی (متوفی بسال <span class=\"hlight\" dir=\"rtl\">١٧٠</span> یا <span class=\"hlight\" dir=\"rtl\">١٧٥</span> هَ .ق .) از روی علم موسیقی و ایقاع استخراج کرد وآن را در پنج دایره شامل پانزده بحر تدوین کرد. پس از وی ابوالحسن سعید بلخی ملقب به اخفش اوسط (متوفی بسال <span class=\"hlight\" dir=\"rtl\">٢١٥</span> هَ .ق .) یک بحر بر آن افزود (بحر متدارک ). و شعرای فارسی زبان سه وزن یا بحر دیگر استخراج کردندو بر بحور افزودند (قریب و جدید و مُشاکِل ) تا شماره ٔ بحرها یا وزنهای اصلی عروض به نوزده رسید. و همچنان این علم به دست ادبای ایران و عرب کامل گردید. اما تألیف این فن به فارسی از قرن چهارم هجری آغاز شده است . از مؤلفان قدیم این علم ابوالحسن علی بهرامی سرخسی و بزرجمهر قاینی (یا قسیمی ) و منشوری سمرقندی را می توان نام برد که بحور و دوایر تازه ای اختراع کردند، و بتدریج عروض فارسی بصورتی درآمد که با عروض عربی متغایر گشت .<br>بنای اوزان و افاعیل عروض : بنای اوزان عروض بر فاء و عین و لام (فعل ) نهادند همچنانکه بناء لغت عرب، تا تصریف اوزان لغوی و شعری بر یک نسق باشد، و چنانکه لغویان گویند «ضرب » بر وزن فعل است و «ضارب » بر وزن فاعل و «مضروب » بر وزن مفعول، عروضیان گویند «نگارینا» بر وزن مفاعیلن است و «نازنینا» بر وزن فاعلاتن و «دلدار من » بر وزن مستفعلن . و نون تنوین در افاعیل عروض بنویسندتا مکتوب و ملفوظ اوزان در حرف یکسان باشد و در فک اجزاء بحور از یکدیگر اشتباه نیفتد. (از المعجم ). خلیل بن احمد اوزان عروض را از اشعار عرب تتبع نموده مقرر در پانزده بحر ساخته است، و ادعای حصر درین اوزان نمودن دور از کار است . و این بحور را در لفظی چند منتظم و مضبوط ساخته اند و آن الفاظ را اصول و افاعیل و تفاعیل گویند و ارکان نیز نامند، و آن ده است و نزد بعضی هشت . این افاعیل نزد اکثر از دو جزو ترکیب یافته است : سبب و وتد. سبب، در لغت ریسمان است و در اصطلاح عروض، کلمه ٔ دوحرفی را گویند، مانند: بر، همه . و وتد، در لغت میخ را گویند و به اصطلاح عروض، کلمه ٔ سه حرفی است، مانند: چمن، لاله . و برخی از عروضیان، بنای افاعیل عروض را بر سه رکن نهاده اند: سبب و وتد وفاصله . فاصله که در لغت بمعنی ستون است در اصطلاح عروض به صغری و کبری تقسیم میشود. فاصله ٔ صغری کلمه ٔ چهارحرفی است که سه حرف اولش متحرک باشد، مانند: نکنی . و فاصله ٔ کبری کلمه ٔ پنج حرفی است که چهار حرف اول آن متحرک باشد: شکنمش .<br>افاعیل عروض : افاعیل عروض که ده است، بعضی خماسی است و بعضی سباعی . خماسی آنها دو باشد: فعولن و فاعلن، که هر یک مرکب از وتد مجموع و سبب خفیف است . و سباعی آنها هشت است : مفاعیلن، فاعلاتن، مستفعلن که هریک مرکب از یک وتد مجموع و دو سبب خفیف است . متفاعلن، مفاعلتن که هر یک مرکب از یک وتد مجموع و یک فاصله ٔ صغری است . مس تَف ْعلن، فاع ِلاتن، مفعولات ُ که هر یک مرکب از دو سبب خفیف و یک وتد مفروق است .<br>بحور عروض : بحوری که از تکرار بعضی افاعیل، یا از ترکیب بعضی با بعضی حاصل میشود، نوزده است که بصورت غیرمرتب بدین قرار است :<br>رَجَز، خفیف و رَمَل، منسرح، دگر مجتث <br>بسیط و وافر و کامل، هَزَج، طویل و مدید<br>مُشاکِل و متقارب، سریع و مقتضَب است <br>مضارع و متدارک، قریب نیز و جدید.<br>و بعضی عروضیان پارسی یازده بحر دیگر استخراج کرده اند که عبارتند از: عریض، عمیق، صریم، کبیر، مذیل، قلیب، حمید، صغیر، اصم، سلیم و حمیم . اماخلیل بن احمد بنای عروض را بر این پانزده بحر گذاشته بود: طویل، مدید، بسیط، کامل، وافر، رمل، هزج، رجز، منسرح، مضارع، سریع، خفیف، مجتث، مقتضب و متقارب . وبعد از او ابوالحسن اخفش بحر شانزدهم، یعنی متدارک را پیدا کرد. و بعد از او بحر قریب و جدید و مشاکل از طرف محدثان متأخر یافت شد. از بحور فوق، طویل و مدید و بسیط و وافر و کامل مخصوص شعر عرب است و شاعران فارسی زبان در این پنج بحر کمتر شعر گفته اند. و جدید و قریب و مشاکل مخصوص شعر فارسی است . و یازده بحر باقی بین فارسی و عربی مشترک است .<br>بیت شعر در بحر طویل به چهار «فعولن مفاعلین » تمام میشود، و مدید از چهار بار «فاعلاتن فاعلن »، و بسیط از چهار «مستفعلن فاعلن »، و وافر هشت بار مفاعلتن، و کامل هشت بار متفاعلن، و هزج از هشت مفاعیلن، و رجز از هشت مستفعلن، و رمل از هشت فاعلاتن، و سریع از دو بار «مستفعلن مستفعلن مفعولات ُ»، و منسرح از چهار بار «مستفعلن مفعولات ُ»، و خفیف از دو بار «فاعلاتن مستفعلن فاعلاتن »، و مضارع از چهار بار «مفاعیلن فاعلاتن »، و مقتضب از چهار بار «مفعولات ُ مستفعلن »، و مجتث از چهار بار «مستفعلن فاعلاتن »، و متقارب از هشت فعولن، و متدارک از هشت فاعلن، و قریب از دو بار «مفاعیلن مفاعیلن فاعلاتن »، و جدید از دو بار «فاعلاتن مستفعلن »، و مشاکل از دو بار «فاعلاتن مفاعیلن مفاعیلن ». هفت بحر متقارب، رمل، هزج، رجز، کامل، وافر و متدارک را که از تکرار یکی از اجزاء حاصل میشود بحور متفق ارکان نامند، و دوازده بحر باقی که از ترکیب اجزاء مختلف با یکدیگر تشکیل میگردد، بحور مختلف ارکان نامیده میشود.<br>سالم و غیرسالم و زحاف : هرگاه در اجزاء بحور تغییری راه نیابد آن را جزوسالم نامند و بحر را نیز بحر یا وزن سالم گویند، چون بیت ذیل :<br>خداوندا تو دانایی بهر رازی <br>تو مر درماندگان را چاره می سازی <br>که از شش بار مفاعیلن تشکیل شده لذا هزج مسدس سالم است . و هرگاه در جزوی با کم و زیاد کردن حروف و حرکات تغییری رخ دهد آن را جزو غیرسالم گویند و خود تغییر را زحاف گویند و بحر را غیرسالم یا مزاحف خوانند، چون این بیت :<br>خداوندا در توفیق بگشای <br>نظامی را ره تحقیق بنمای <br>که هر مصراع آن از «مفاعیلن مفاعیلن مفاعیل ْ» تشکیل شده است لذا بحر هزج مسدس مزاحف می باشد .<br>انفکاک بحور و دوایر عروض : در عروض هر چند بحر متناسب را جزو یک دستگاه کرده آن را دایره نامیده اند و برای هر دایره اسمی مخصوص وضع کرده اند. و ترتیب رسم این دوایر چنین است که دایره را بوسیله ٔ رسم کردن اقطار، بر چند بخش قسمت کرده و بر محیط دایره در هر بخش یکی از ارکان سبب و وتد و فاصله را با حرف «ف ع ل » نوشته اند سپس مبداء انشعاب هر بحری را تعیین کرده اند، چنانکه از هر کدام از ارکان آغاز شود یکی از بحور مربوط به آن دایره استخراج میشود. دوایر مشهور بحور عروض شش دایره است که از هر کدام آنها چند بحر از نوزده بحر استخراج میگردد: <span class=\"hlight\" dir=\"rtl\">١</span>- دایره ٔ متفقه که دو بحر متقارب و متدارک از آن استخراج میشود. <span class=\"hlight\" dir=\"rtl\">٢</span>- دایره ٔ مختلفه که سه بحر طویل و مدید و بسیط از آن بیرون می آید. <span class=\"hlight\" dir=\"rtl\">٣</span>-دایره ٔ مؤتلفه که مشتمل بر دو بحر وافر و کامل است . <span class=\"hlight\" dir=\"rtl\">٤</span>- دایره ٔ مجتلبه که سه بحر رجز و هزج و رمل از آن جدا میشود. <span class=\"hlight\" dir=\"rtl\">٥</span>- دایره ٔ مشتبهه مشتمل بر چهار بحر منسرح و مضارع و مجتث ّ و مقتضب . <span class=\"hlight\" dir=\"rtl\">٦</span>- دایره ٔ منتزعه که پنج بحر خفیف و سریع و جدید و قریب و مشاکل از آن استخراج میشود . (از غیاث اللغات ) (از آنندراج ) (از المعجم ) (از بدیع و عروض و قافیه ). و رجوع به نفایس العلوم شود <span class=\"hlight\">:</span> <br>عروض و قافیه معنی نسنجد<br>که هر ظرفی در او معنی نگنجد.<br> <font color=\"Red\">شبستری .</font><br>- <span class=\"hlight\">علم عروض </span> ؛ علم وزن شعر. رجوع به عروض شود <span class=\"hlight\">:</span> <br>علم عروض از قیاس بسته حصاریست <br>نفس سخن گوی من کلید حصار است .<br> <font color=\"Red\">ناصرخسرو.</font><br><BR><font color=\"Blue\">◄</font> (اصطلاح فقه ) بجز نقدینه را در فقه در باب معاملات عروض گویند. (فرهنگ علوم نقلی از الفقه علی ص <span class=\"hlight\" dir=\"rtl\">٤٨٦</span>) <span class=\"hlight\">:</span> یاقوت و مرجان و جامه و همه عروض از اقمشه و امتعه نیست الا زکوة تجارت . (از تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١٧٦</span>).<br></font></div>'),
(182722, 'عروض', '<span class=\"hlight\">عروض .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) مدینه و مکه و یمن است . و گویند مکه و یمن باشد. و برخی آن را مکه و طایف و حومه ٔ آنها دانسته اند. و آن را خلاف عراق نیز گفته اند و حکایت کنند که چون «جدیس » به قصد برادران خود از بابل حرکت کرد و به طَسم که در «عروض » فرودآمده بود پیوست، او نیز در قسمت پایین و اسفل عروض فرودآمد. و آن را بدان جهت عروض خوانده اند که در عرض بلاد یمن و عرب قرار گرفته است مابین تخوم فارس تا اقصای سرزمین یمن، و آن مستطیل شکل بوده در امتداد ساحل میباشد. و نیز گویند عروض عبارت از بلاد یمامه و بحرین و توابع آنها باشد. (از معجم البلدان ). مکه و مدینه حرمهما اﷲ تعالی، و حوالی هر دو. (منتهی الارب ).<br></font></div>'),
(182723, 'عروض البلد', '<span class=\"hlight\">عروض البلد.</span> <font color=\"DarkGreen\"><b>[ ع َ ضُل ْ ب َ ل َ ]</font></b> (ع اِ مرکب ) (اصطلاح موسیقی ) قسمی از قول و حراره و تصنیف و کخ کخ و شرقی و زجل و موشح و موشحه و کاری و کان وکان و موالیا و قوما و ملعبه . (یادداشت مرحوم دهخدا). و رجوع به کُخکُخ شود.<br></font></div>'),
(182724, 'عروضی', '<span class=\"hlight\">عروضی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب است به عروض که از اوزان شعر بحث میکند. (از الانساب سمعانی ). رجوع به عروض شود.<br>- <span class=\"hlight\">وزن عروضی </span> ؛ وزن کلمه است ازنظر حرکات و سکنات، بدون در نظر گرفتن نوع حرکت، و آن در مقابل وزن صرفی است که در آن نوع حرکت و نیز نوع حرف زائد مورد نظر قرار میگیرد.<br><BR><font color=\"Blue\">◄</font> آنکه عروض داند. عالم عروض . (از فرهنگ فارسی معین ). عروض دان . و رجوع به عروض شود.<br></font></div>'),
(182725, 'عروضی', '<span class=\"hlight\">عروضی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام او محمدبن منصوربن حسن عروضی برجی، مکنی به ابوسهل است .وی از اهالی اصفهان و محدث بود و حدیث را نزد ابونعیم حافظ و دیگران فراگرفت و اهالی اصفهان و دیگران از او روایت کرده اند. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182726, 'عروضی', '<span class=\"hlight\">عروضی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام وی رزین بن زندور، و ملقب به عروضی و مکنی به ابونصر است . او شاعری است که اوزان تازه و غریبی از عروض را بکار میبرد و در این راه از استاد خود عبداﷲبن هارون پیروی میکرد.رزین از موالی طیفوربن منصور حمیری، خال مهدی خلیفه بشمار میرفت و در بغداد سکونت داشت . او را با «عنان » شاعره اخبار و معارضاتی است . وی بسال <span class=\"hlight\" dir=\"rtl\">٢٤٧</span> هَ .ق . درگذشت . (از الاعلام زرکلی از ارشاد الاریب و الورقة).<br></font></div>'),
(182727, 'عروضی سمرقندی', '<span class=\"hlight\">عروضی سمرقندی .</span> <font color=\"DarkGreen\"><b>[ ع َ ی ِ س َ م َ ق َ ]</font></b> (اِخ ) ابوالحسن نظام الدین یا نجم الدین احمدبن عمربن علی سمرقندی، معروف به نظامی عروضی . از شعرا و نویسندگان قرن ششم هجری، و مصنف کتاب چهارمقاله است . از شرح حال و تاریخ تولد و وفات او اطلاع صحیحی در دست نیست . گویا در اواخر قرن پنجم در سمرقند ولادت یافته و مدتی از جوانی خود را در مولد خویش سمرقند به کسب علوم مشغول بوده، سپس بین سالهای <span class=\"hlight\" dir=\"rtl\">٥٠٤</span> و <span class=\"hlight\" dir=\"rtl\">٥٠٦</span> هَ .ق . به خراسان رفته است، زیرا در سال <span class=\"hlight\" dir=\"rtl\">٥٠٤</span> هَ .ق . در سمرقند از دهقان ابورجا اطلاعاتی درباره ٔ رودکی کسب کرده و در سال <span class=\"hlight\" dir=\"rtl\">٥٠٦</span> هَ .ق . در بلخ به خدمت عمر خیام رسیده و در سال <span class=\"hlight\" dir=\"rtl\">٥١٠</span> هَ .ق . در طروق طوس خدمت معزی را دریافته و شعر خود بر او عرضه داشته است، و در همین اوان گویا به خدمت آل شنسب اختصاص یافته و بعد از این تاریخ گاه بخراسان نیز سفر کرده است، از جمله در سال <span class=\"hlight\" dir=\"rtl\">٥٣٠</span> هَ .ق . مجدداً به نیشابور رفته و قبر عمر خیام را زیارت کرده است . و به سال <span class=\"hlight\" dir=\"rtl\">٥٤٧</span> که مابین سلطان سنجر سلجوقی و سلطان علاءالدین غوری در صحرای اوبه در حدود هرات محاربه واقع شده نظامی نیز در لشکر غوریان حضور داشته و پس از شکست غوریه مدتی طویل در هرات مخفی گشته است .<br>اثر مشهور او کتاب مجمعالنوادر، مشهور به چهارمقاله است که اطلاع وی را در باب دبیری (انشاء)، شاعری، نجوم و طب که موضوع کتاب و مقالات چهارگانه ٔ آن است، نشان میدهد. عروضی خود نیز شاعر بود، از جمله این چند بیت از اوست :<br>در جهان سه نظامییم ای شاه <br>که جهانی ز ما به افغانند<br>من به ورساد پیش تخت شهم <br>وآن دو در مرو پیش سلطانند<br>بحقیقت که در سخن امروز<br>هر یکی مفخر خراسانند<br>گرچه همچون روان سخن گویند<br>ورچه همچون خرد سخن دانند<br>من شرابم که شان چو دریابم <br>هر دو از کار خود فرومانند.<br>برای اطلاع بیشتر از شرح حال نظامی عروضی و اثر او، رجوع به کتاب چهارمقاله به کوشش محمد معین و نیز به تاریخ ادبیات در ایران از ذبیح اﷲ صفا ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩٦١</span> شود.<br></font></div>'),
(182728, 'عروضیة', '<span class=\"hlight\">عروضیة.</span> <font color=\"DarkGreen\"><b>[ ع َ ضی ی َ ]</font></b> (اِخ ) وی زنی ادیب و از اهالی اندلس بود و مولای ابوالمطرف عبدالرحمان بن غلبون کاتب بشمار میرفت . بسبب مهارتی که در فن عروض داشت این نام بر وی نهاده و نام اصلی او به دست فراموشی سپرده شد. او امالی قالی و الکامل مبرد را از حفظ داشت و شرح میگفت . عروضیة در بلنسیة ساکن بود و به سال <span class=\"hlight\" dir=\"rtl\">٤٥٠</span> هَ .ق . در دانیة درگذشت . (از الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٦</span> از الدر المنثور و نفح الطیب ). و رجوع به اعلام النساء شود.<br></font></div>'),
(182729, 'عروط', '<span class=\"hlight\">عروط.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) ناقه ای که به خوردن درخت دندان ریخته باشد. (منتهی الارب ). ماده شتری که آنقدر درخت بخورد تا دندانهای او از بین برود. (اقرب الموارد). ج، عُرُط. (از منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(182730, 'عروعیر', '<span class=\"hlight\">عروعیر.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) بمعنی خرابه ها. و آن نام چند مکان است :<br><span class=\"hlight\" dir=\"rtl\">١</span>- شهری که در شمال نهر ارنون در موآب واقع و بر أوبین داده شد، که در اول متعلق به سیحون پادشاه آموریان بود، پس از آن حزائیل پادشاه سوریه آن را مفتوح ساخت . و خرابه ها بر محل مرتفعی است که به مسافت <span class=\"hlight\" dir=\"rtl\">١٢</span> میل به مشرق دریای مردآب واقع است و آن را عراعیر گویند.<br><span class=\"hlight\" dir=\"rtl\">٢</span>- شهری است در برابر ربه، که همان عمان حالیه باشد، و جادیان آن را بنا کردند.<br><span class=\"hlight\" dir=\"rtl\">٣</span>- موضعی است در حوالی دمشق .<br><span class=\"hlight\" dir=\"rtl\">٤</span>- شهری است در قسمت جنوبی یهودیه، و این همان عرعاره ٔ حالیه است که بر راه غزه و وادی موسی که به جنوب بئر شبع واقع، و در آنجا چهار چاه است . (از قاموس کتاب مقدس ).<br></font></div>'),
(182731, 'عروف', '<span class=\"hlight\">عروف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) مرد دانا و کارشناس و ماهر. (ناظم الاطباء). عارف و دانا. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد نیک شکیبا. (از منتهی الارب ). صبور. (اقرب الموارد). ج، عُرف . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(182732, 'عروفة', '<span class=\"hlight\">عروفة.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع ص ) مرد دانا و نیک ماهر و کارشناس . (منتهی الارب ). دانا به چیزی، گویند: رجل عروف و عروفة بالامور؛ یعنی مردی که به امور دانا باشد و هرگاه کسی را یک بار دیده باشد، او را بشناسد (و تاء کلمه برای مبالغه است ). (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(182733, 'عروق', '<span class=\"hlight\">عروق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عِرق . رگهای بدن . (غیاث اللغات ). جمع عِرق است و شامل عروق بدن و شجر هر دو است . (از مخزن الادویة). رگهای بدن یعنی ورید و شریان . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>پس فرشته وْ دیو کشته عرضه دار<br>بهر تحریک عروق اختیار.<br> <font color=\"Red\">مولوی .</font><br>من به هر شهری رگی دارم نهان <br>بر عروقم بسته اطراف جهان .<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">عروق جذّابه </span> ؛ (اصطلاح پزشکی ) مجموعه ٔ سپیدرگهارا گویند. (فرهنگ فارسی معین ). رگهای لنفی . لمفاتیک . رجوع به سپیدرگ شود.<br>- <span class=\"hlight\">عروق جذّابه ٔکیلوس </span> ؛ (اصطلاح پزشکی ) قسمتی از سپیدرگهای احشائی است که از داخل خمهای روده مواد غذائی را جذب می کنند. سپیدرگهای کیلوس . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عروق خشنه </span> ؛ اقسام قصبةالریه . (یادداشت مؤلف ).<br>- <span class=\"hlight\">عروق داخله </span> ؛ آن رگها که در جانب اِنسی باشند، چون ابطی در دست و صافن در پای . (یادداشت مؤلف ).<br>- <span class=\"hlight\">عروق ساکنه </span> ؛ مقابل عروق ضوارب است . (یادداشت مؤلف ). وریدها. اورده . عروق سواکن . رگهای ناجهنده .<br>- <span class=\"hlight\">عروق شَعْریه </span> ؛ مویرگها. (فرهنگ فارسی معین ). رجوع به رگ و مویرگ شود.<br>- <BR><font color=\"Blue\">◄</font> چیزهای باریک و دراز که در بول دیده می شود. (تذکره ٔ ضریر انطاکی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٩</span>).<br>- <span class=\"hlight\">عروق ضوارب </span> ؛ شرائین را گویند. (یادداشت مؤلف ). در مقابل عروق سواکن . رگهای جهنده .<br>- <span class=\"hlight\">عروق لنفاتیکیه </span> ؛ رگهای لنفی . سپیدرگ . (فرهنگ فارسی معین ). رجوع به سپیدرگ شود.<br>- <span class=\"hlight\">عروق نابضه </span> ؛ شرائین و رگهای جهنده . (ناظم الاطباء).عروق ضوارب .<br> <BR><font color=\"Blue\">◄</font> ج ِ عِرق . بیخهای درخت . (غیاث اللغات ). بیخهای درخت و ریشه های باریک آن . (ناظم الاطباء). رجوع به عِرق شود <span class=\"hlight\">:</span> و قد تبراء به القروح مع الجلنار و العروق و نحوها. (ابن البیطار): طُنُب ؛ عروق درخت . (منتهی الارب ).<br>- <span class=\"hlight\">عروق أبیض </span> ؛ بوزیدان . عروق بیض . رجوع به عروق بیض شود.<br>- <span class=\"hlight\">عروق أحمر</span> ؛ فوه الصباغین است که به فارسی روناس و به هندی منجیت و مجیت نیز نامند. (مخزن الادویة). رودنگ . (یادداشت مرحوم دهخدا). رَوین . عروق الحمر. رجوع به عروق حمر شود.<br>- <span class=\"hlight\">عروق أصف </span> ؛ بیخ کَبَر است . (مخزن الادویة). عرق اصف . عرق الاصف . رجوع به عرق الاصف و کبر شود.<br>- <span class=\"hlight\">عروق أصفر</span> ؛ زردچوبه . (ذخیره ٔ خوارزمشاهی ). عروق صفر.رجوع به عروق صفر شود.<br>- <span class=\"hlight\">عروق بیض </span> ؛عروق البیض . العروق البیض . گیاهی است که زنان را فربه کند، و مستعجله نیز نامندش . (منتهی الارب ). مستعجله است . (تحفه ٔ حکیم مؤمن ). مستعجله، و بعضی بوزیدان که به هندی ستاوری نامند، دانسته اند. (مخزن الادویة). گیاهی است که زنان جهت فربهی استعمال می کنند. (ناظم الاطباء). گیاهی است فربه کننده زنان را، و آن را مستعجله نیز نامند. (از اقرب الموارد).<br>- <span class=\"hlight\">عروق حُمر</span> ؛ رَوین . (منتهی الارب ). روناس . (ناظم الاطباء). فوه الصبغ است . (تحفه ٔ حکیم مؤمن ). فوة. (تاج العروس ) (اقرب الموارد). روغناس . عروق الحمر. العروق الحمر. عروق احمر. و رجوع به عروق احمر شود.<br>- <span class=\"hlight\">عروق دارهرم </span> ؛ عرق سوس . ریشه ٔ شیرین بیان . (یادداشت مؤلف ). عرق السوس . رجوع به عرق سوس شود.<br>- <span class=\"hlight\">عروق سفر</span> ؛ مستعجله است . (مخزن الادویة). عروق بیض .رجوع به عروق بیض شود.<br>- <span class=\"hlight\">عروق صفر</span> ؛ العروق الصفر. عروق الصفر. زردچوبه، یا هُرد، یا مامیران، یا کرکم خرد است . (منتهی الارب ). گیاهی است صباغان و رنگرزان را، و گویند آن هُرد است، و نیز گویند آن مامیران یا کُرکُم صغیر است . (از اقرب الموارد). عروق الزعفران است . (مخزن الادویة). بقلةالخطاطیف . ریشه ٔ شجرةالخطاطیف . خالیدوینون کبیر. (یادداشتهای مرحوم دهخدا). به فارسی زردچوبه گویند، و آن بیخ نباتی است برگش شبیه به برگ گشنیز و مایل به کبودی و ساقش بقدر ذرعی و باریک و پرشعبه و پربرگ، و گل او مایل به سفیدی و زردی، و آب برگش مایل به سرخی و ثمرش مثل خشخاش، و قسم صغیر او مامیران است . در سیُم گرم و خشک و جالی و مفتح سده ٔ جگر است . و گویند فوةالصبغ است . (از تحفه ٔ حکیم مؤمن ). گیاهی است از تیره ٔ کوکناریان به ارتفاع <span class=\"hlight\" dir=\"rtl\">٣٠</span>تا <span class=\"hlight\" dir=\"rtl\">٨٠</span> سانتیمتر که معمولاً بر روی دیوارها و اماکن مخروبه میروید. برگهایش دارای <span class=\"hlight\" dir=\"rtl\">٥</span> تا <span class=\"hlight\" dir=\"rtl\">٧</span> قسمت مشخص است . جام گلش زردرنگ و کاسه ٔ گل آن نیز به رنگ جام است . بر اثر خراشی که بر برگها یا ساقه ٔ این گیاه وارد آیدشیرابه ٔ نارنجی رنگ تلخ و سوزنده ای خارج میشود که دارای اثر مسهلی است . انساج این گیاه شامل آلکالوئیدهائی نظیر کلیدونین و سانگینارین و کلریترین و اسید کلیدونیک می باشند. عصاره ٔ این گیاه را گاهی جهت از بین بردن زگیل تجویز میکنند. و نیز سابقاً برای از بین بردن تومورهای سرطانی تجویز میشده است . مامیران . مامیران کبیر. مامیرون . ممران . بقلةالخطاطیف . شجرةالخطاطیف . خلیدونیون . خالدونیون . خالدونیون . کالیدونیون . عروق الصباغین . حشیشةالخطاف . حشیشةالصفراء. عروق الزعفران . قیرلانغج اوتی . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عروق فالوذَج </span> ؛ ابوخلسا است، که شنجار نامند. (مخزن الادویة). رجوع به ابوخلسا شود.<br><BR><font color=\"Blue\">◄</font> برخی عروق را چهار دانسته اند، دو عرق ظاهر یکی غرس و کاشتن و دیگر بناء و ساختمان، و دو عرق باطن و پنهان، یکی چاه و دیگر معدن . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> عروق الصباغین را نامند، که به فارسی زردچوبه گویند. و بعضی گفته اند نباتی است زرد که بفارسی اسپرک و به هندی تن نامند. (مخزن الادویة). آن را به تازی گویند، و به پارسی زردچوبه گویند و به هندوی مسله گویند. (از تذکره ٔ ضریر انطاکی ). رجوع به عروق الصباغین و عروق الصبغ شود.<br></font></div>'),
(182734, 'عروق', '<span class=\"hlight\">عروق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) در زمین رفتن . (تاج المصادر) (از ناظم الاطباء): عرق فی الارض ؛ در زمین رفت . (از اقرب الموارد). عَرق . رجوع به عَرْق شود.<br></font></div>'),
(182735, 'عروق', '<span class=\"hlight\">عروق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) تل ها و تپه هایی است سرخ رنگ در نزدیکی سجا، و سجا آبی است به نجد در دیار بنی کلاب . (از معجم البلدان ) (از تاج العروس ). ریگ توده های سرخ رنگ نزدیک سجا . (منتهی الارب ).<br></font></div>'),
(182736, 'عروق الزعفران', '<span class=\"hlight\">عروق الزعفران .</span> <font color=\"DarkGreen\"><b>[ ع ُ قُزْ زَ ف َ ]</font></b> (ع اِ مرکب ) عروق الصفر است . (تحفه ٔ حکیم مؤمن ). زردچوبه . عروق صُفر. عروق صباغین . رجوع به عروق صباغین و عروق صفر شود.<br></font></div>'),
(182737, 'عروق السوس', '<span class=\"hlight\">عروق السوس .</span> <font color=\"DarkGreen\"><b>[ ع ُ قُس ْ سو ]</font></b> (ع اِ مرکب ) اصل السوس است . (مخزن الادویة). عرق السوس . رجوع به عرق السوس و سوس شود.<br></font></div>'),
(182738, 'عروق الشجر', '<span class=\"hlight\">عروق الشجر.</span> <font color=\"DarkGreen\"><b>[ ع ُ قُش ْ ش َ ج َ ]</font></b> (ع اِ مرکب ) علک . (منتهی الارب ).<br></font></div>'),
(182739, 'عروق الشحم', '<span class=\"hlight\">عروق الشحم .</span> <font color=\"DarkGreen\"><b>[ ع ُ قُش ْ ش َ ]</font></b> (ع اِ مرکب )اسم جنس صموغ است . و گویند مخصوص علک البطم است، و جمعی مخصوص فلقونیا دانسته اند. (تحفه ٔ حکیم مؤمن ). ظاهراً همان عروق الشجر است . رجوع به عروق الشجر شود.<br></font></div>'),
(182740, 'عروق الصباغین', '<span class=\"hlight\">عروق الصباغین .</span> <font color=\"DarkGreen\"><b>[ ع ُ قُص ْ ص َب ْ با]</font></b> (ع اِ مرکب ) زردچوبه . (ناظم الاطباء). عروق صفر. بقلةالخطاطیف . مامیران . (یادداشت مرحوم دهخدا). عروق .رجوع به عروق و ترکیب «عروق صفر» ذیل «عروق » شود.<br></font></div>'),
(182741, 'عروق الصبغ', '<span class=\"hlight\">عروق الصبغ.</span> <font color=\"DarkGreen\"><b>[ ع ُ قُص ْص ِ ]</font></b> (ع اِ مرکب ) عروق الصباغین است . (مخزن الادویة).رجوع به عروق و ترکیب «عروق صفر» ذیل «عروق » شود.<br></font></div>'),
(182742, 'عروق الطیب', '<span class=\"hlight\">عروق الطیب .</span> <font color=\"DarkGreen\"><b>[ ع ُ قُطْ طی ]</font></b> (ع اِ مرکب ) زرنباد است . (مخزن الادویة). رجوع به زرنباد شود.<br></font></div>'),
(182743, 'عروق الکافور', '<span class=\"hlight\">عروق الکافور.</span> <font color=\"DarkGreen\"><b>[ ع ُ قُل ْ ]</font></b> (ع اِ مرکب ) زرنباد.(منتهی الارب ) (مخزن الادویة). رجوع به زرنباد شود.<br></font></div>'),
(182744, 'عروقا', '<span class=\"hlight\">عروقا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) چیزی است که اهل نصیبین در سیاهی موی مستعمل دارند. و گفته اند که اشراس است . (مخزن الادویة).<br></font></div>'),
(182745, 'عرون', '<span class=\"hlight\">عرون .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) ستور کفیده و موی رفته دست و پا. و اسب «عرون »زده . (منتهی الارب ). ستور کفیده دست و پای و موی رفته . اسب «عرنة»زده . (ناظم الاطباء). دابه که به بیماری «عِران » دچار شده باشد. (از اقرب الموارد). و رجوع به عَرَن شود.<br></font></div>'),
(182746, 'عرونة', '<span class=\"hlight\">عرونة.</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ ]</font></b> (ع اِ) رعاد، که قسمی ماهی دارای الکتریسیته است . (از یادداشت مرحوم دهخدا). سمکةالرعد. رجوع به رعاد و رعد در ردیفهای خود و نیز المنجد شود.<br></font></div>'),
(182747, 'عروند', '<span class=\"hlight\">عروند.</span> <font color=\"DarkGreen\"><b>[ ع ُرْ رُ وَ ]</font></b> (اِخ )از قلاع و حصون صنعاء یمن است . (از معجم البلدان ).<br></font></div>'),
(182748, 'عروک', '<span class=\"hlight\">عروک .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) حائض گردیدن . (منتهی الارب ). حیض افتادن زن . (المصادر زوزنی ) (از تاج المصادر بیهقی ). عَرک . عَراک . و رجوع به عرک شود.<br></font></div>'),
(182749, 'عروک', '<span class=\"hlight\">عروک .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عَرکی ّ. (منتهی الارب ). جج ِ عرکی، که صیاد ماهی باشد. و از آن جمله است «علیکم ما صادت عروککم ». (از اقرب الموارد).<br></font></div>'),
(182750, 'عروی', '<span class=\"hlight\">عروی .</span> <font color=\"DarkGreen\"><b>[ ع َرْ وا ]</font></b> (اِخ )از اعلام عربی است . (از منتهی الارب ) (از آنندراج ).<br></font></div>'),
(182751, 'عروی', '<span class=\"hlight\">عروی .</span> <font color=\"DarkGreen\"><b>[ ع َرْ وا ]</font></b> (اِخ ) فلاتی است در شَمام، و گویند آن آبی است ازآن ِ بنی ابی بکربن کلاب . و نیز آن را کوهی در دیار ربیعةبن عبداﷲبن کلاب وکوهی در دیار خثعم دانسته اند. (از معجم البلدان ).<br></font></div>'),
(182752, 'عرویا', '<span class=\"hlight\">عرویا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) سریانی است، به فارسی گزانگبین است . (مخزن الادویة).<br></font></div>'),
(182753, 'عرک', '<span class=\"hlight\">عرک .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ]</font></b> (ع اِ) ج ِ عَروکة. (منتهی الارب ). ج ِ عَروک . (اقرب الموارد). رجوع به عروک و عروکة شود.<br></font></div>'),
(182754, 'عرک', '<span class=\"hlight\">عرک .</span><font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (ع ص ) مرد نیک اندازنده اقران خود را در حرب و جز آن . (منتهی الارب ). مرد نیک اندازنده اقران و همسران خود را در جنگ و جز آن . (ناظم الاطباء). رجل عرک ؛ مرد سخت و به زمین افکننده . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد آزموده و سخت توانا در کارزار. (منتهی الارب ) (ناظم الاطباء). ج، عَرِکون . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> رمل عرک ؛ ریگ در یکدیگر درآمده . (منتهی الارب ). ریگ متداخل و درهم شده . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) آواز میانه ٔ دریا و معظم آن . (منتهی الارب ). صوت . (اقرب الموارد).<br></font></div>'),
(182755, 'عرک', '<span class=\"hlight\">عرک .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِمص ) اسم مصدر است عَرک را. (منتهی الارب ). رها کردگی شتران را در شورگیاه . (ناظم الاطباء). اسم است از مصدر عَرک . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) آواز. (منتهی الارب ).صوت و آواز. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ج ِ عَرَکی . (منتهی الارب ) (اقرب الموارد). رجوع به عرکی شود.<br></font></div>'),
(182756, 'عرک', '<span class=\"hlight\">عرک .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع مص ) نیک اندازنده ٔ همسران گردیدن . (از منتهی الارب ). نیک افگندن همسران خود را در جنگ . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> سخت افکنده شدن در حرب . (از منتهی الارب ). سخت افکنده شدن در جنگ . (از ناظم الاطباء). عَرِک و سخت پیکار و سخت حمله شدن در جنگ . (از اقرب الموارد).<br></font></div>'),
(182757, 'عرک', '<span class=\"hlight\">عرک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) گذاشتن شتررا در گیاه ترش تا بچرد از آن بقدر حاجت و خواهش . (از منتهی الارب ). عرک الابل فی الحمض ؛ شتران را در میان گیاه حمض رها کرد تا به اندازه ٔ حاجت خود از آن بخورند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> حائض گردیدن زن . (از منتهی الارب ). عَراک . عُروک . و رجوع به عراک وعروک شود. <BR><font color=\"Blue\">◄</font> سخت شدن جنگ بر کسی . (از منتهی الارب ). عرک القوم الحرب ؛ جنگ آن قوم را فراگرفت .(از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مالیدن پوست و جز آن . (از منتهی الارب ). عرک الادیم ؛ پوست را مالش داد. (اقرب الموارد). مالیدن گوش و ادیم و آنچه بدان ماند. (تاج المصادر بیهقی ) (المصادر زوزنی ). <BR><font color=\"Blue\">◄</font> گوشمال دادن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خراشیدن چیزی را چندان که محو و ناچیز گردد. (منتهی الارب ). تراشیدن چیزی را تا محو شود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> برانگیختن بدی و زمانه کسی را. (از منتهی الارب ). حمل کردن شر و داهیه بر کسی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بریدن بازوی شتر را آرنج او، چندان که بگوشت رسد. (منتهی الارب ). خراشیدن شتر پهلوی خود را با آرنج خود، چندان که بگوشت رسد. (ناظم الاطباء).عرک البعیر جنبه بمرفقه ؛ شتر پهلوی خود را بوسیله ٔ آرنج خویش خراشید و خط انداخت تا بگوشت رسید. و چنین شتری را عارک و عرکرک نامند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> استوارخرد گردانیدن کسی را زمانه . (منتهی الارب ). عرک الدهر فلانا؛ آزموده کرد او را روزگار. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چریدن ستور گیاه را.(منتهی الارب ). خوردن ماشیه نبات را. (از اقرب الموارد). لمس کردن کوهان را تا ببینند آیا چربی دارد یا ندارد. (از ناظم الاطباء). کسی را در حرب و کوهان برمچیدن تا فربه هست یا نه . (تاج المصادر بیهقی ). عرک السنام ؛ سنام را لمس کرد تا ببیند آیا در او پیه و چربی هست یا نه . (از اقرب الموارد) (از منتهی الارب ).<br></font></div>'),
(182758, 'عرک', '<span class=\"hlight\">عرک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) پلیدی ددگان . (منتهی الارب ). پلیدی سباع و ددگان . (ناظم الاطباء). خُرء و پلیدی سباع . (از اقرب الموارد).<br></font></div>'),
(182759, 'عرکات', '<span class=\"hlight\">عرکات .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) ج ِ عَرَکة. (منتهی الارب ) (اقرب الموارد). رجوع به عرکة شود.<br></font></div>'),
(182760, 'عرکانیه', '<span class=\"hlight\">عرکانیه .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ نی ی َ ]</font></b> (ع ص ) زن زناکار. (ناظم الاطباء). زن فاجر. (از اقرب الموارد). عَرکیّة. رجوع به عرکیة شود. <BR><font color=\"Blue\">◄</font> زن ستبر گنده . (ناظم الاطباء). زن غلیظ و بزرگ جثه . (از اقرب الموارد). عرکیة. رجوع به عرکیة شود.<br></font></div>'),
(182761, 'عرکرک', '<span class=\"hlight\">عرکرک .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ رَ ]</font></b> (ع ص ) شرم سطبر. (از منتهی الارب ) (ازناظم الاطباء) (از آنندراج ). <BR><font color=\"Blue\">◄</font> شتر نر قوی درشت . (منتهی الارب ). شتر قوی و درشت، و مؤنث آن عرکرکة باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد تندار و شکیبا. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> شتر که از خراش آرنج، بازویش بریده باشد. (منتهی الارب ). شتری که پهلوی او بوسیله ٔ آرنجش خط افتاده و بریده باشد و تا گوشت رسیده باشد. (از اقرب الموارد).<br></font></div>'),
(182762, 'عرکسة', '<span class=\"hlight\">عرکسة.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ س َ ]</font></b> (ع مص ) بر یکدیگر نهادن چیزی را.(از منتهی الارب ). بر هم قرار گرفتن و تراکب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گرد آوردن . (از منتهی الارب ). جمع کردن بعضی را بر بعضی . (از اقرب الموارد).<br></font></div>'),
(182763, 'عرکل', '<span class=\"hlight\">عرکل .</span><font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (ع اِ) دف و طبل . <BR><font color=\"Blue\">◄</font> (اِخ ) نام مردی است . (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br></font></div>'),
(182764, 'عرکون', '<span class=\"hlight\">عرکون .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (ع ص، اِ) ج ِ عَرِک . (منتهی الارب ) (اقرب الموارد). رجوع به عرک شود.<br></font></div>'),
(182765, 'عرکی', '<span class=\"hlight\">عرکی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ کی ی ]</font></b> (ع اِ) ماهیگیر. (منتهی الارب ). صاید ماهی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کشتیبان . (منتهی الارب ). ملاح . (از اقرب الموارد). ج، عَرَک، و جمع الجمع عُروک . (اقرب الموارد) (منتهی الارب ). <br></font></div>'),
(182766, 'عرکی', '<span class=\"hlight\">عرکی .</span><font color=\"DarkGreen\"><b>[ ع َ رَ کی ی ]</font></b> (اِخ ) اسمی است شبیه به نسبت . و آن نام کسی است که از پیامبر (ص ) در مورد وضو ساختن با آب دریا استفسار کرد. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182767, 'عرکیة', '<span class=\"hlight\">عرکیة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ کی ی َ ]</font></b> (ع اِ) زن زناکار. (از منتهی الارب ).فاجرة. (اقرب الموارد). عَرکانیة. رجوع به عرکانیة شود. <BR><font color=\"Blue\">◄</font> زن سطبر درشت . (منتهی الارب ). غلیظة. (اقرب الموارد). عرکانیة. رجوع به عرکانیة شود.<br></font></div>'),
(182768, 'عرکین', '<span class=\"hlight\">عرکین .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (ع اِ) (ذوالَ ...) ستاره ای است . (ناظم الاطباء).<br></font></div>'),
(182769, 'عرگوزی', '<span class=\"hlight\">عرگوزی .</span> <font color=\"DarkGreen\"><b>[ ع ُرر ]</font></b> (حامص مرکب ) به گوز سرگین برآوردن، چه «عر»بالضم بمعنی سرگین است . (آنندراج ) (غیاث اللغات ).<br></font></div>'),
(182770, 'عرگوزی', '<span class=\"hlight\">عرگوزی .</span> <font color=\"DarkGreen\"><b>[ ع َرر ]</font></b> (حامص مرکب ) شور و غوغای بی محل . (آنندراج ) (غیاث اللغات ). صورتی از عر وگوز و آن اشاره است به تیز دردادن خر هنگام نهیق .<br></font></div>'),
(182771, 'عری', '<span class=\"hlight\">عری .</span> <font color=\"DarkGreen\"><b>[ ع َ ری ی ]</font></b>(ع اِ) باد سرد. (منتهی الارب ) (از اقرب الموارد). عَریّة. رجوع به عریة شود. <BR><font color=\"Blue\">◄</font> صاحب لرزه که پیش از تب آید. ج، عُراة. (یادداشت مرحوم دهخدا).<br></font></div>'),
(182772, 'عری', '<span class=\"hlight\">عری .</span> <font color=\"DarkGreen\"><b>[ ع َ را <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ را ]</font></b> (ع اِ) تکمه ٔ جامه . (منتهی الارب ). دکمه ٔ جامه، مقابل مادگی . <BR><font color=\"Blue\">◄</font> گوشه . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> دسته ٔ دَلوو کوزه و جز آن، و جای گرفت آنها. (ناظم الاطباء).<br></font></div>'),
(182773, 'عری', '<span class=\"hlight\">عری .</span> <font color=\"DarkGreen\"><b>[ ع َ را ]</font></b> (ع اِ) کرانه و ناحیه . (منتهی الارب ). ناحیه . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ساحت سرای . (منتهی الارب ). ساحة. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سختی سرما. (منتهی الارب ).<br></font></div>'),
(182774, 'عری', '<span class=\"hlight\">عری .</span> <font color=\"DarkGreen\"><b>[ ع َرْی ْ ]</font></b> (ع مص ) پوشیدن چیزی را. (از منتهی الارب ). پوشاندن کسی را. (از اقرب الموارد): عراه الامر، پوشید او را آن کار. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آمدن کسی را. (از منتهی الارب ) (از ناظم الاطباء).<br></font></div>'),
(182775, 'عری', '<span class=\"hlight\">عری .</span> <font color=\"DarkGreen\"><b>[ ع ُ را ]</font></b> (ع اِمص ) برهنگی . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ) ج ِ عُروة. (منتهی الارب ) (اقرب الموارد). رجوع به عروة شود. <BR><font color=\"Blue\">◄</font> فرماندهان سپاه . (از اقرب الموارد).<br></font></div>'),
(182776, 'عری', '<span class=\"hlight\">عری .</span> <font color=\"DarkGreen\"><b>[ ع ُرْی ْ ]</font></b> (ع اِمص ) برهنگی . خلاف لبس . (منتهی الارب ). برهنگی و بی پوشاکی . (ناظم الاطباء) <span class=\"hlight\">:</span> و یستحب <font color=\"DarkGreen\"><b>[ فی الفرس ]</font></b> عری الناهضین، و هما عظمان فی الخد، و ذلک من علامة العتق . (صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١</span>). <BR><font color=\"Blue\">◄</font> (اِ) آنچه در مقابل دکمه است از لباس، یعنی آنجا که دکمه در هنگام بستن، داخل آن میشود، و آن را بکسر اول نیز خوانند. (از اقرب الموارد). سوراخ تکمه . جای دکمه . دکمه جای . <BR><font color=\"Blue\">◄</font> (ص ) فرس عری ؛ اسب بی زین . (منتهی الارب ). اسب زین نشده، و آن وصف به مصدر است که بصورت اسم درآمده است . (از اقرب الموارد). ج، أعراء. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(182777, 'عری', '<span class=\"hlight\">عری .</span> <font color=\"DarkGreen\"><b>[ ع ُرْی ْ ]</font></b> (ع مص ) برهنه گردیدن . (منتهی الارب ). برهنه گردیدن و کندن پوشاک خود را. (از ناظم الاطباء). برهنه شدن . (المصادر زوزنی ) (دهار): عری الرجل من ثیابه ؛ آن مرد لباسهای خود را کند، و در این صورت وی را عار و عُریان گویند و تأنیث آن عاریة و عریانة باشد. (از اقرب الموارد). عُریة. رجوع به عریة شود. <BR><font color=\"Blue\">◄</font> عری من العیب ؛ از عیب ایمن گشت، و چنین شخصی را عَر گویند. (از اقرب الموارد).<br></font></div>'),
(182778, 'عری', '<span class=\"hlight\">عری .</span> <font color=\"DarkGreen\"><b>[ ع ِ را ]</font></b> (ع اِ) در اصطلاح شطرنج آن است که شاه شطرنج در برابر مهره ٔ حریف افتد. (براهین العجم ). شطرنج عری، یا مات عری ؛ آن است که مهره ای میان شاه و رخ افتد که اگر آن را بردارند شاه کشت شود.(یادداشت مرحوم دهخدا). مهره ای که در میان شاه خود و رخ حریف حایل سازند برای حفاظت شاه از کشت، و برخاستن آن مشکل است . و چون شاه شطرنج در خانه ٔ خود بی حرکت شده باشد گویند شاه درعری است . آچمز. (از فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>با بیدقیم و مات عری گشته شاه ما<br>میر اجل نظاره ٔاحوال دان ماست .<br> <font color=\"Red\">خاقانی .</font><br>شه وقت عری شکار باشد<br>بیدق همه زخم خوار باشد.<br> <font color=\"Red\">خاقانی (تحفةالعراقین ص <span class=\"hlight\" dir=\"rtl\">٢٠١</span>).</font><br>کنون برآمد این ماه از وبال محاق <br>کنون برون جست این شاه از بلای عری .<br><font color=\"Red\">میرزا محمدتقی سپهر.</font><br></font></div>'),
(182779, 'عری', '<span class=\"hlight\">عری .</span> <font color=\"DarkGreen\"><b>[ ع ِرْی ْ ]</font></b> (ع اِ) سوراخ تکمه . جای وارد شدن دکمه در لباس . عُری . (از اقرب الموارد). رجوع به عُرْی شود.<br></font></div>'),
(182780, 'عریان', '<span class=\"hlight\">عریان .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ ]</font></b> (اِخ ) قلعه ای است به مدینه و ریگ توده ای . (منتهی الارب ). نام ریگ توده ای و قلعه ای در مدینه . (ناظم الاطباء). قلعه و کوشکی است در مدینه ازآن ِ بنی النجار از خزرج، در صقعالقبلة از آل النضر، از قوم انس بن مالک . (از معجم البلدان ).<br></font></div>'),
(182781, 'عریان', '<span class=\"hlight\">عریان .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ ]</font></b> (ع ص ) برهنه . (منتهی الارب ) (دهار). آنکه لباسهای خود را کنده باشد. (از اقرب الموارد). عاری . عار. عور. لخت . لوت . روت . رود. روده . روخ . تهمک . ورت . ج، عریانون . (منتهی الارب ) <span class=\"hlight\">:</span> <br>ز علم و طاعت جانت ضعیف و عریانست <br>بعلم کوش و بپوش این ضعیف عریان را.<br> <font color=\"Red\">ناصرخسرو.</font><br>زنهار چنانک آمده ای اول از آنجا<br>خیره نروی گُرْسنه و تشنه و عریان .<br> <font color=\"Red\">ناصرخسرو.</font><br>نیست پوشیده که شاه حیوانی تو<br>که نه عریانی و ایشان همگان عریان .<br> <font color=\"Red\">ناصرخسرو.</font><br>وقت پیکار نقش خانه ٔ فتح <br>نفس آن حله پوش عریان باد.<br> <font color=\"Red\">مسعودسعد.</font><br>چون صفر و الف تهی و تنها<br>چون تیر و قلم نحیف و عریان .<br> <font color=\"Red\">خاقانی .</font><br>عریان ز حوض ماهی سوی بره روان شد<br>همچون بره برآمد پوشیده صوف اصفر.<br> <font color=\"Red\">خاقانی .</font><br>تو زین احرام و زین کعبه چه دانی کز برون چشمت <br>ز کعبه پوشش دیده ست و از احرام عریانی .<br> <font color=\"Red\">خاقانی .</font><br>از برونم پرده ٔ اطلس چه سود<br>چون برون پرده عریان میزیَم .<br> <font color=\"Red\">عطار.</font><br>قفاخورد و گریان و عریان نشست <br>جهاندیده ای گفتش ای خودپرست .<br> <font color=\"Red\">سعدی .</font><br>سفر کرد بامدادان، دیدند عرب را گریان و عریان . (گلستان سعدی ).<br>کشته از بس که فزون است کفن نتوان کرد<br>فکر خورشید قیامت کن و عریانی چند.<br><font color=\"Red\">نظیری .</font><br>از نور مهر و ماه چه میکاهد<br>گر کسوتی ببخشد عریان را.<br> <font color=\"Red\">قاآنی .</font><br>از لعاب سنگ تابد شعله ٔ عریان عشق <br>پرده چون پوشد کسی بر سوزش پنهان عشق .<br> <font color=\"Red\">صائب (از آنندراج ).</font><br>- <span class=\"hlight\">عریان النَّجی ّ</span> ؛ زن و نیز مردی که راز را نتواند پوشید. (منتهی الارب ). آنکه سرّ و راز را کتمان نکند. (از اقرب الموارد).<br> <BR><font color=\"Blue\">◄</font> بمجاز، بری . دور. محروم <span class=\"hlight\">:</span> <br>بسان آدم دور اوفتاده ایم از خلد<br>از آن ز لهو و نشاط و سرور عریانیم .<br> <font color=\"Red\">مسعودسعد.</font><br><BR><font color=\"Blue\">◄</font> ریگستانی که هیچ نرویاند. (منتهی الارب ): رمل عریان ؛ قطعه ای از ریگ است که بصورت محدب حرکت کند، و یا توده ای از ریگ که درختی بر آن نباشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اسب دراز. (منتهی الارب ). اسب خرامان و درازدست وپا. (از اقرب الموارد).<br></font></div>'),
(182782, 'عریان', '<span class=\"hlight\">عریان .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ ]</font></b> (اِخ ) لقب باباطاهر، عارف و شاعر معروف همدان در قرن پنجم است . رجوع به باباطاهر شود.<br></font></div>'),
(182783, 'عریان', '<span class=\"hlight\">عریان .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ]</font></b> (اِخ ) النذیر العریان . مردی از خثعم معروف به دیانت . (ناظم الاطباء). مردی از خثعم که در واقعه ٔ ذی الخلصة، عوف بن عامر بر او حمله برد و دست او و همسرش راقطع کرد. (از اقرب الموارد). و رجوع به نذیر شود.<br></font></div>'),
(182784, 'عریان', '<span class=\"hlight\">عریان .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ ]</font></b> (اِخ ) (بنوالَ ...) نام بطنی از حمیر است . (از ناظم الاطباء).<br></font></div>'),
(182785, 'عریان', '<span class=\"hlight\">عریان .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ ]</font></b> (اِخ ) دهی از دهستان خورشید بخش ششتمد شهرستان سبزوار. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٦٣٥</span> تن . آب آن از قنات . محصول آن غلات، پنبه، گردو و بادام است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(182786, 'عریان تپه', '<span class=\"hlight\">عریان تپه .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ ت َپ ْ پ َ ]</font></b> (اِخ ) دهی جزء دهستان هرزندات بخش زنوز شهرستان مرند. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٩٣٥</span> تن . آب آن از چشمه و قنات . محصول آن غلات و نخود و زردآلو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(182787, 'عریان شدن', '<span class=\"hlight\">عریان شدن .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ ش ُ دَ ]</font></b> (مص مرکب ) لخت شدن . برهنه شدن . عور شدن . و رجوع به عریان شود <span class=\"hlight\">:</span> <br>مگر درخت شکفته گناه آدم کرد<br>که از لباس چو آدم همی شود عریان .<br> <font color=\"Red\">فرخی .</font><br>گفتم ار عریان شود او در عیان <br>نی تو مانی نی کنارت نی میان .<br> <font color=\"Red\">مولوی .</font><br>صبح تیغش تا بباغ سینه عریان میشود<br>خون ز زخمم همچو رنگ از گل نمایان میشود.<br> <font color=\"Red\">بیدل (از آنندراج ).</font><br>حسن چون بی پرده شد زنهار گرد او مگرد<br>بوی خون می آید از تیغی که عریان می شود.<br> <font color=\"Red\">صائب (از آنندراج ).</font><br> <BR><font color=\"Blue\">◄</font> مبری شدن . دور شدن <span class=\"hlight\">:</span> <br>از نعمت تو گردد پوشیده <br>هر کس که از خلاف توشد عریان .<br><font color=\"Red\">فرخی .</font><br></font></div>'),
(182788, 'عریان نمودن', '<span class=\"hlight\">عریان نمودن .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ دَ ]</font></b> (مص مرکب ) لخت کردن . برهنه کردن . عاری نمودن <span class=\"hlight\">:</span> <br>بخندد چو پسته درون پوست وآنگه <br>چو بادام از آن پوست عریان نماید.<br> <font color=\"Red\">خاقانی .</font><br>و رجوع به عریان و عریان کردن شود.<br></font></div>'),
(182789, 'عریان وش', '<span class=\"hlight\">عریان وش .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ وَ ]</font></b> (ص مرکب ) بسان عریان . عریان مانند. برهنه مانند <span class=\"hlight\">:</span> <br>چنگ است عریان وش سرش صدره ٔبریشم در برش <br>بسته پلاسین میزرش زانوش پنهان بین در او.<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(182790, 'عریان کردن', '<span class=\"hlight\">عریان کردن .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ ک َ دَ ]</font></b> (مص مرکب ) برهنه کردن . عاری کردن . لخت کردن . مکشوف کردن . دور کردن پوشش از... <span class=\"hlight\">:</span> <br>بخواب ماند نوک سنان او گر خواب <br>چو در تن آید تن را ز جان کند عریان .<br> <font color=\"Red\">فرخی .</font><br>گر در لباس جهل دلم خفته بود<br>اکنون از آن لباسش عریان کنم .<br> <font color=\"Red\">ناصرخسرو.</font><br>که را عقل از فضایل خلعت دینی بپوشاند<br>نتاند کرد ازین خلعت هگرز این دیو عریانش .<br> <font color=\"Red\">ناصرخسرو.</font><br>سنگ بر قندیل ما زد تا بهنگام صلاح <br>جان ما را از خرد عریان مادرزاد کرد.<br> <font color=\"Red\">سنائی .</font><br>و رجوع به عریان شود.<br></font></div>'),
(182791, 'عریانة', '<span class=\"hlight\">عریانة.</span> <font color=\"DarkGreen\"><b>[ ع ُرْ ن َ ]</font></b> (ع ص ) مؤنث عریان، چه هر کلمه ای که بر وزن فُعلان باشد مؤنث آن با تاء آید. (از منتهی الارب ). زن که جامه هابرآورده باشد، و زنان لخت را عاریات و عَوار گویند. عاریة. (از اقرب الموارد). و رجوع به عریان شود.<br></font></div>'),
(182792, 'عریانی', '<span class=\"hlight\">عریانی .</span> <font color=\"DarkGreen\"><b>[ ع ُرْ ]</font></b> (حامص ) برهنگی و بی پوشاکی . (ناظم الاطباء). لختی و برهنگی . (فرهنگ فارسی معین ). تجرد <span class=\"hlight\">:</span> <br>عریان همه خلق و از بسی سختی <br>کس را نبود خبر ز عریانی .<br> <font color=\"Red\">ناصرخسرو.</font><br>احرام که گیری چو قدح گیر که دارد<br>عریانی بیرون و درون لعل قبائی .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(182793, 'عریب', '<span class=\"hlight\">عریب .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (ع اِ) گویند: ما بالدّار عریب ؛ یعنی احدی و کسی در خانه نیست . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) نام اسبی است . (منتهی الارب ).<br></font></div>'),
(182794, 'عریب', '<span class=\"hlight\">عریب .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (اِخ ) ابن جشم بن حاشد، از بنی همدان، از قحطان . جدی جاهلی و یمانی بود. فرزندان او بطن هایی را تشکیل داده اند که ازجمله ٔ آنها حجوربن اسلم بن عریب میباشد. (از الاعلام زرکلی از الاکلیل ج <span class=\"hlight\" dir=\"rtl\">١٠</span> ص <span class=\"hlight\" dir=\"rtl\">٩٧</span>).<br></font></div>'),
(182795, 'عریب', '<span class=\"hlight\">عریب .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (اِخ ) ابن حیدان (یا حدان ) بن عمرو، از قضاعة، از قحطانیة. جدی است جاهلی . (از الاعلام زرکلی از النویری و السبائک و نهایةالارب و جمهرةالانساب ).<br></font></div>'),
(182796, 'عریب', '<span class=\"hlight\">عریب .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (اِخ ) ابن زهیربن أبین (یا أیمن ) بن الهمیسع، از حمیر، از قحطانیة. جدی است جاهلی . و قبایل صنهاجة و جنادة و زناتة، که از قبایل مشهور مغرب هستند از نسل او میباشند. (از الاعلام زرکلی از طرفةالاصحاب و نهایة الارب ).<br></font></div>'),
(182797, 'عریب', '<span class=\"hlight\">عریب .</span><font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (اِخ ) ابن زیدبن کهلان، از قحطانیة. جدی است جاهلی . و لخم و جذام و کندة و عاملة و طی ٔ و اشعریون و مذحج و مرة از نسل او باشند. (از الاعلام زرکلی از ابن خلدون و الاکلیل و طرفةالاصحاب و نهایةالارب ).<br></font></div>'),
(182798, 'عریبة', '<span class=\"hlight\">عریبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع اِ) نام قومی که موکل راه هستند. (غیاث اللغات ) (آنندراج ).<br></font></div>'),
(182799, 'عریبی', '<span class=\"hlight\">عریبی .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (ص نسبی ) منسوب به عُریب که از اعلام است . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182800, 'عریة', '<span class=\"hlight\">عریة.</span> <font color=\"DarkGreen\"><b>[ع ُرْ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِرْ ی َ ]</font></b> (ع اِ) جاریة حسنة بالعریة؛ دختر نیکو جای برهنگی از روی و دست و پا. (منتهی الارب ).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(182801, 'عریة', '<span class=\"hlight\">عریة.</span> <font color=\"DarkGreen\"><b>[ ع ِرْی َ ]</font></b> (ع اِمص ) نوع و هیئت برهنگی . (ناظم الاطباء).<br></font></div>'),
(182802, 'عریة', '<span class=\"hlight\">عریة.</span> <font color=\"DarkGreen\"><b>[ ع َ ری ی َ ]</font></b> (ع ص، اِ) خرمابن بی بار. و خرمابن که بار آن خورده باشند. (منتهی الارب ).نخلی که آنچه بر آن است خورده باشند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درخت که میوه ٔ آن را به محتاجی دهند. (منتهی الارب ). نخلی که صاحب آن میوه ٔ یک سال آن را به دیگری هبه کند تا میوه ٔ آن را بخورد، و آن فعیل به معنی مفعول است و هاء آن بجهت این است که اسم بحساب آید، چون نطیحة و أکیلة، لذا هرگاه آن را صفت نخل قرار دهند هاء را حذف نمایند و نخل عری گویند، چنانکه امراءة قتیل . (از اقرب الموارد). ج، عَرایا. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه جدا دارند از مساومت وقت فروختن خرمابن . (منتهی الارب ). آنچه از نخل وقت فروختن از قیمت گذاری جدا کنند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مکیل . (منتهی الارب ). مکتل . (اقرب الموارد).  <BR><font color=\"Blue\">◄</font> باد سرد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(182803, 'عریة', '<span class=\"hlight\">عریة.</span> <font color=\"DarkGreen\"><b>[ ع ُرْ ی َ ]</font></b>(ع مص ) برهنه گردیدن . (از منتهی الارب ). کندن لباس خود را. (از اقرب الموارد). عُری . رجوع به عری شود.<br></font></div>'),
(182804, 'عریتنات', '<span class=\"hlight\">عریتنات .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ت ِ ]</font></b> (اِخ ) موضعی است .(منتهی الارب ). نام وادیی است . (از معجم البلدان ).<br></font></div>'),
(182805, 'عریج', '<span class=\"hlight\">عریج .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) نااستوار: امر عریج ؛ کار نااستوار. (منتهی الارب ). امری که محکم نشده باشد. (از اقرب الموارد).<br></font></div>'),
(182806, 'عریج', '<span class=\"hlight\">عریج .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (اِخ ) ابن عبدرضابن جبیل بن عامربن عمروبن عوف کلبی . از اجداد است و نسبت بدو عریجی شود. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182807, 'عریج', '<span class=\"hlight\">عریج .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (اِخ ) ابن سعدبن جمح . از اجداد جاهلی است و نسبت بدو عریجی شود. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182808, 'عریج', '<span class=\"hlight\">عریج .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (اِخ ) ابن بکربن عبدمناةبن کنانة. از اجداد جاهلی است و نسبت بدو عریجی شود. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182809, 'عریجی', '<span class=\"hlight\">عریجی .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (ص نسبی ) منسوب به عُریج که از اعلام است . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182810, 'عرید', '<span class=\"hlight\">عرید.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص )دور. (منتهی الارب ). بعید. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) خوی . (منتهی الارب ). دأب و عادت، گویند: هذا عریده ؛ یعنی این عادت اوست . (از اقرب الموارد).<br></font></div>'),
(182811, 'عریدن', '<span class=\"hlight\">عریدن .</span><font color=\"DarkGreen\"><b>[ ع َرْ ری دَ ]</font></b> (مص جعلی ) در تداول عامه، عرعر کردن . (یادداشت مرحوم دهخدا). آواز برآوردن خر. <BR><font color=\"Blue\">◄</font> تعبیری طنزآمیز از آوای ناهنجار برآوردن کسی .<br></font></div>'),
(182812, 'عریر', '<span class=\"hlight\">عریر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) مسافر و بیگانه ٔ قوم . (منتهی الارب ). غریب در قوم . <BR><font color=\"Blue\">◄</font> غریب در حدیث . (از اقرب الموارد).<br></font></div>'),
(182813, 'عریرا', '<span class=\"hlight\">عریرا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) نانخواه است، و عوشه را نیز نامند. (مخزن الادویة).<br></font></div>'),
(182814, 'عریزالصغیر', '<span class=\"hlight\">عریزالصغیر.</span> <font color=\"DarkGreen\"><b>[ ؟ زُص ْ ص َ ]</font></b> (ع اِ مرکب ) قنطوریون صغیر است . (از برهان ). رجوع به قنطوریون شود.<br></font></div>'),
(182815, 'عریزالکبیر', '<span class=\"hlight\">عریزالکبیر.</span> <font color=\"DarkGreen\"><b>[ ؟ زُل ْ ک َ ]</font></b> (ع اِ مرکب ) قنطوریون کبیر است . (از برهان ). رجوع به قنطوریون شود.<br></font></div>'),
(182816, 'عریس', '<span class=\"hlight\">عریس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) عروس . (ناظم الاطباء). رجوع به عروس شود. <BR><font color=\"Blue\">◄</font> واحد عُرس، به معنی ریسمانها. (از اقرب الموارد).<br></font></div>'),
(182817, 'عریس', '<span class=\"hlight\">عریس .</span> <font color=\"DarkGreen\"><b>[ ع ِرْ ری ]</font></b> (ع اِ) خوابگاه شیر. (منتهی الارب ). مأوای شیر و اسد. (از اقرب الموارد). کنام شیر. عریسة. و رجوع به عریسة شود.<br></font></div>'),
(182818, 'عریس السیل', '<span class=\"hlight\">عریس السیل .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ مرکب ) به لغت مصر بشنین است . (مخزن الادویة).<br></font></div>'),
(182819, 'عریسة', '<span class=\"hlight\">عریسة.</span> <font color=\"DarkGreen\"><b>[ ع ِرْ ری س َ ]</font></b> (ع اِ) خوابگاه شیر. (منتهی الارب ). مأوای شیر و اسد. (از اقرب الموارد). کنام شیر. عریس . و رجوع به عریس شود.<br></font></div>'),
(182820, 'عریسی', '<span class=\"hlight\">عریسی .</span><font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (اِخ ) عبدالغنی بن محمد عریسی . از روزنامه نگاران و شهیدان معاصر عرب . رجوع به عبدالغنی شود.<br></font></div>'),
(182821, 'عریش', '<span class=\"hlight\">عریش .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) کزابه . (منتهی الارب ). کجاوه و چیزی شبیه به هودج . (ناظم الاطباء). مرکبی چون هودج که آن را ازبرای زنان سازند تا بر شترنشینند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> وادیج رَز. (منتهی الارب ). آنچه برای درخت رز ساخته شود تا شاخه های آن را بر وی قرار دهند. (از اقرب الموارد). نی بستی که بر آن شاخه های انگور افتاده می مانند. (آنندراج ) (غیاث اللغات ). چفته ٔ رز. چفت انگور <span class=\"hlight\">:</span> <br>حلقه گرد او چو رز گرد عریش <br>همچنانکه بت پرستان بر کشیش .<br> <font color=\"Red\">مولوی .</font><br>انواع اعناب حدایق چون احداق کواعب اتراب برعرش عریش بسان حورات قاصرات الطرف گردن ملاحت افراشته و تتق سبز مکلل به در و عقیق فروگذاشته . (ترجمه ٔ محاسن اصفهان آوی ). <BR><font color=\"Blue\">◄</font> خانه از چوب و یز ساخته، و کازه . (منتهی الارب ). کازه و کلبه . (غیاث اللغات ) (آنندراج ). چیزی است شبیه خیمه که از چوب و ثمام سازند. (از اقرب الموارد). خانه از چوب و گیاه ساخته . کومه . کلبه . (فرهنگ فارسی معین ). ج، عُرُش . (منتهی الارب ) (اقرب الموارد). و خانه های مکه را که عرش نامند از همین معنی است چه آنها بصورت چوبهایی هستند که سایه بانی بر آنها قرار دارد. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> هر پوشش که سایه افکند وسایه بان . (منتهی الارب ). بیت که در سایه ٔ آن قرار گیرند. (از اقرب الموارد) <span class=\"hlight\">:</span> <br>در عریش او را یکی زایربیافت <br>کو بهر دو دست خود زنبیل بافت .<br> <font color=\"Red\">مولوی .</font><br><BR><font color=\"Blue\">◄</font> بودن چهار یا پنج درخت خرما از یک بیخ . (منتهی الارب ). در یک ریشه چهار یا پنج نخل بودن . (از اقرب الموارد).<br></font></div>'),
(182822, 'عریش', '<span class=\"hlight\">عریش .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) (الَ ...) شهری است که اولین عمل مصر از ناحیه ٔ شام بر ساحل دریای روم و در میان رمل و ریگستان بوده است . و در وجه تسمیه ٔ آن گویند آنگاه که برادران یوسف (ع ) بر اثر قحطسالی شام به مصر روی آوردند در این ناحیه از جانب مأموران یوسف (ع ) دستگیر شدند و در مدتی که آنان به انتظار اجازه ٔ یوسف برای ورود آنها به داخل مصر در آنجا ماندند، برای خود سایه بان و عریشی ساختند تا از گرمای آفتاب در امان باشند، لذا بدین نام شهرت یافته است . و گویند فاصله ٔ آن تا وَرّادة سه فرسخ است . و در وصف آن نوشته اند که شهری است بزرگ و مهم و در روزگار فرعون جزو حرس مصر بود و آن آخرین شهر از اعمال مصر است که به شام متصل می باشد. و والی «جفار» حکومت آن را به دست دارد و مقر وی نیز در این شهر است . عریش را دو جامع و مسجد و دو منبر است، هوای آن سالم و خوش و آب آن شیرین و گواراست . و در آن بازاری است بزرگ و نخلهای بسیار دارد و انواع خرما و انار در آنجا بعمل می آیدو تاجران و سوداگران را نمایندگان و وکلائی در این شهر میباشد. اهالی این شهر از بنی جذام هستند. و فاصله ٔ آن تا هر یک از دو چاه ابواسحاق شش میل است و نیز با هر یک از شجرتین (که اولین اعمال شام است ) و برمکیه و رفح، شش میل فاصله دارد. (از معجم البلدان ). شهری بر ساحل بحرالروم بر مغرب غزه . (از ابن بطوطه ).<br></font></div>'),
(182823, 'عریشی', '<span class=\"hlight\">عریشی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) احمدبن ابراهیم بن فتح عریشی، مکنی به ابوالعباس . شاعر و فقیه و محدث بود، و نسبت وی به شهر عریش مصر است . پسرش ابوالفضل شعیب بن احمد و نوه اش ابواسحاق ابراهیم بن شعیب از او روایت حدیث کرده اند. (از معجم البلدان ).<br></font></div>'),
(182824, 'عریض', '<span class=\"hlight\">عریض .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) تپه ای است بسوی نیر بنی غاضرة. و گویند کوهی است . و گویند نام یک وادی است . و گویند جایگاهی است در نجد. (از معجم البلدان ).<br></font></div>'),
(182825, 'عریض', '<span class=\"hlight\">عریض .</span> <font color=\"DarkGreen\"><b>[ ع َ رِی ْ ی ِ ]</font></b> (اِخ ) دهی از دهستان میربچه ٔ بخش رامهرمز شهرستان اهواز. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١١٠</span> تن . آب آن ازرودخانه ٔ گوپال . محصول آن غلات، برنج، کنجد و بزرک است . ساکنان این ده از طایفه ٔ زبید هستند و آن را «بنه زبید» هم نامند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(182826, 'عریض', '<span class=\"hlight\">عریض .</span> <font color=\"DarkGreen\"><b>[ ع ِرْ ری ]</font></b> (ع ص ) کسی که شر و فساد پیش آرد مردم را، و آنکه کار بی فایده کند و در پی باطل رود. (منتهی الارب ). آنکه برای مردم شر پیش آورد. (از اقرب الموارد).<br></font></div>'),
(182827, 'عریض', '<span class=\"hlight\">عریض .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (اِخ ) وادیی است به مدینه و در آن شتران اهل مدینه باشند. (منتهی الارب ). یک وادی است در مدینه و نام آن در غزوات آمده است . (از معجم البلدان ). دیهی است از دیههای مدینه به یک فرسخی آن، و این ده ملک باقر علیه السلام بوده است و صادق علیه السلام این ده را وصیت کرد در حق پسرش علی، و او در وقت وفات صادق دوساله بوده است و چون بزرگ شد بدان دیه رفت و ساکن گشت و فرزندان او را عریضیة بدین سبب میخوانند. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٢٢٤</span>).<br></font></div>'),
(182828, 'عریض', '<span class=\"hlight\">عریض .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) پهناور. (منتهی الارب ). خلاف طویل . (از اقرب الموارد). باپهنا. دارای عرض زیاد. پهن . پهناور. (فرهنگ فارسی معین ). عُراض . (اقرب الموارد). و رجوع به عُراض شود. ج، عِراض . (اقرب الموارد) (ناظم الاطباء) <span class=\"hlight\">:</span> به تخته های عریض ترتیب داده و به علاقات محکم کرده . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٧٥</span>). <BR><font color=\"Blue\">◄</font> کنایه از چیز بسیار و کثیر است .پهن، یعنی بسیار و همیشه . (ترجمان القرآن جرجانی ): دعاء عریض ؛ دعاء بسیار. (منتهی الارب ). دعای کثیر، و آن مجاز است از عرض و پهنای جسم . (از اقرب الموارد) <span class=\"hlight\">:</span> و اذا مسه الشر فذو دعاء عریض (قرآن <span class=\"hlight\" dir=\"rtl\">٥١/٤١</span>)؛ و چون او را شر رسد، پس صاحب دعایی بسیار است .<br>از پی عرض نگه داشتن و جاه عریض <br>خواسته بر دل او خوارتر از خاک و حصاست .<br> <font color=\"Red\">فرخی .</font><br>از پی نام بلند و از پی جاه عریض <br>ملک او و مال او را نزد او مقدار نیست .<br> <font color=\"Red\">فرخی .</font><br>امیرمکرم مفضل جمال اهل کرم <br>سزا و اهل بجاه عریض و فضل عمیم .<br> <font color=\"Red\">سوزنی .</font><br><BR><font color=\"Blue\">◄</font> فراخ و گشاد و وسیع. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> رجل عریض البطان ؛ مرد توانگر. (منتهی الارب ). مثری و غنی . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بزغاله ٔ یک ساله که جهت گشنی در بانگ و حرکت آمده، یا به عرض کنج دهن گیاه را تناول نماید. (منتهی الارب ). عریض از مَعز، آنکه یک سال بر او گذشته باشد و گیاه را با گوشه ٔ کنج دهان خود خورد. (از اقرب الموارد). ج، عرضان <font color=\"DarkGreen\"><b>[ ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ]</font></b> . (اقرب الموارد) (منتهی الارب ) <span class=\"hlight\">:</span> بچه ٔ گوسفند چون چهارماهه باشد و از بز بود... و چون قوی تر گردد عریض گویند. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١٧٨</span>). <BR><font color=\"Blue\">◄</font> خصی از گوسفند. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اصطلاح عروض ) نام بحری است مقلوب طویل، و وزنش مفاعیلن فعولن است . (از کشاف اصطلاحات الفنون ). و رجوع به طویل شود. <BR><font color=\"Blue\">◄</font> در طب، قسمی از نبض، و آن قوی و در پهنای ساعد باشد. (یادداشت مرحوم دهخدا). ضد طویل . و رجوع به طویل شود.<br></font></div>'),
(182829, 'عریض شدن', '<span class=\"hlight\">عریض شدن .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ُ دَ ]</font></b> (مص مرکب ) پهن شدن . پهناور شدن . فسیح شدن . عرض پیدا کردن . اتساع یافتن . متسع شدن . باپهنا گشتن . و رجوع به عریض شود.<br></font></div>'),
(182830, 'عریض کردن', '<span class=\"hlight\">عریض کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ دَ ]</font></b> (مص مرکب ) پهن کردن . باوسعت کردن . واسع کردن .متسع ساختن . توسعه دادن . اتساع دادن . سعه دادن . وسعت دادن . فسیح کردن . عرض دادن . و رجوع به عریض شود.<br></font></div>'),
(182831, 'عریضجات', '<span class=\"hlight\">عریضجات .</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ض ِ ]</font></b> (از ع، اِ) (از: عریضه + جات هندی ) بمعنی قوم . (از یادداشت مرحوم دهخدا). جمع غیرفصیح عریضه است درتداول فارسی زبانان، به معنی نوشته های کوچکتران به بزرگتران . (از فرهنگ فارسی معین ). عریضه ها. عرایض . درخواستها و مستدعیات <span class=\"hlight\">:</span> هرچه عرایض است که فقطبه ملاحظه ٔ مخصوص است در حضور ضبط میشود. سایر عرایض را عضدالملک به دفترخانه ٔ عریضجات خواهد برد. (دستخط ناصرالدین شاه به عضدالملک از فرهنگ فارسی معین ).<br></font></div>'),
(182832, 'عریضن', '<span class=\"hlight\">عریضن .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ض ِ ]</font></b> (ع اِ) تصغیر عِرَضْنی ̍ است . (از اقرب الموارد). و نون آن چون غیرملحق است باقی میماند. (از منتهی الارب ).<br></font></div>'),
(182833, 'عریضه نگار', '<span class=\"hlight\">عریضه نگار.</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ض ِ ن ِ ]</font></b> (نف مرکب ) عریضه نگارنده . آنکه عریضه نویسد. آنکه عرض حال نویسد.<br></font></div>'),
(182834, 'عریضی', '<span class=\"hlight\">عریضی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب به عریض . رجوع به عریض شود. <BR><font color=\"Blue\">◄</font> (حامص ) پهنائی و پهناوری . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> وسعت و گشادگی . (ناظم الاطباء).<br></font></div>'),
(182835, 'عریضیة', '<span class=\"hlight\">عریضیة.</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ضی ی َ ]</font></b> (ص نسبی ) منسوب به عُریض که از دیهای مدینه باشد <span class=\"hlight\">:</span> دیگر از فرزندان علی بن جعفر صادق و از فرزندان محمدبن علی جعفر سادات، عریضیه اند. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٢٢٤</span>).<br></font></div>'),
(182836, 'عریط', '<span class=\"hlight\">عریط.</span> <font color=\"DarkGreen\"><b>[ ع ِرْ ی َ ]</font></b> (ع اِ) کژدم . (منتهی الارب ). عقرب . (اقرب الموارد) (مخزن الادویة). ام عِریط. ام العِریط. و رجوع به ام عریط و ام العریط شود.<br></font></div>'),
(182837, 'عریف', '<span class=\"hlight\">عریف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) دانا و شناسنده . (منتهی الارب ). عالم به چیزی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنکه بشناسد یاران خود را. (منتهی الارب ). کسی که اصحاب و یاران خود را بشناسد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کارگزار قوم، و آن پایین تر از رئیس است . و یا رئیس قوم، زیرا بدان شناخته شده است . و در حدیث «العرفاء فی النار» منظور عرفا و رؤسائی است که قصور می کنند و آنچه جایزنباشد مرتکب می شوند. (از منتهی الارب ). مهتر مردمان .(زمخشری ). قیم و کارگزار کارهای قوم که در آن امر مشهورشده و شناخته باشد. و گویند بمعنی نقیب است که آن پایین تر از رئیس باشد. و گویند عریف رئیس است بر نُفَیر، و منکب رئیس پنج عریف است، آنگاه امیر است که بالاتر از همه ٔ اینها باشد. و از آن جمله است عریف در مکتبها، و او پسری است که مراقبت سایر بچه های مکتب را بعهده دارد. (از اقرب الموارد). ج، عُرفاء. (منتهی الارب ) (اقرب الموارد) <span class=\"hlight\">:</span> فقال یا فلان لسنا نأکل من طعامک فانک عریف تأکل السحت . (الکنی للدولابی ). دیگر آنکه ما را عریف کرده آید که ودیعتی از اینجانب یا نامزد یکی از فرزندان سلطان شود. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥١٨</span>). عَرافة؛ عریف گردیدن . (منتهی الارب ).<br></font></div>'),
(182838, 'عریف', '<span class=\"hlight\">عریف .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (اِخ )ابن ابد. در قبیله ٔ حضرموت است . (از منتهی الارب ).<br></font></div>'),
(182839, 'عریف', '<span class=\"hlight\">عریف .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ]</font></b> (اِخ ) ابن ابراهیم . محدث بود. (از منتهی الارب ).<br></font></div>'),
(182840, 'عریف', '<span class=\"hlight\">عریف .</span> <font color=\"DarkGreen\"><b>[ ع ُرَ ]</font></b> (اِخ ) ابن ادهم . محدث بود. (از منتهی الارب ).<br></font></div>'),
(182841, 'عریف', '<span class=\"hlight\">عریف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جشم . شاعر فارسی است . (منتهی الارب ).<br></font></div>'),
(182842, 'عریف', '<span class=\"hlight\">عریف .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سریع. تابعی است . (منتهی الارب ).<br></font></div>'),
(182843, 'عریف', '<span class=\"hlight\">عریف .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مازن . تابعی است . (منتهی الارب ).<br></font></div>'),
(182844, 'عریف', '<span class=\"hlight\">عریف .</span> <font color=\"DarkGreen\"><b>[ ع ُرَ ]</font></b> (اِخ ) ابن مدرک . محدث بود. (از منتهی الارب ).<br></font></div>'),
(182845, 'عریفاضانة', '<span class=\"hlight\">عریفاضانة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ن َ ]</font></b> (ع اِ) گیاهی است که آن را ذُرَق نامند. رجوع به ذرق و عریفضان شود.<br></font></div>'),
(182846, 'عریفضان', '<span class=\"hlight\">عریفضان .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ف َ ]</font></b> (ع اِ) گیاهی است که آن را ذُرَق نامند. رجوع به ذرق و عریفاضانة شود.<br></font></div>'),
(182847, 'عریفطان', '<span class=\"hlight\">عریفطان .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ف ِ ]</font></b> (اِخ ) وادیی است . (منتهی الارب ). عریفطان مَعن ؛ وادیی است بین مکه و مدینه، و آن را آب و سبزه نیست و در برابر آن کوههایی است بنام اُبلی، و نیز تپه ای در برابر آن است بنام السودة ازآن ِ بنی خفاف . (از معجم البلدان ).<br></font></div>'),
(182848, 'عریفی', '<span class=\"hlight\">عریفی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (حامص ) شغل و خدمت ریاست . (ناظم الاطباء): عِرافة؛ عریفی کردن . (منتهی الارب ).<br></font></div>'),
(182849, 'عریفی', '<span class=\"hlight\">عریفی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب است به عریف بن جشم . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182850, 'عریفی', '<span class=\"hlight\">عریفی .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (ص نسبی ) منسوب به عُریف که بطنی است از حضرموت، از صدف . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182851, 'عریق', '<span class=\"hlight\">عریق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) مرد صاحب عِرق و اصل در کرم و در لؤم . (منتهی الارب ). در مردمان و در اسبان، آنکه او را رگی در کرم و در پستی باشد، و مقصود آن است که او کریم یا لئیم است . (از اقرب الموارد). اصیل . نجیب . <BR><font color=\"Blue\">◄</font> غلام عریق ؛ پسری نحیف جسم و سبک روح . (از اقرب الموارد).<br></font></div>'),
(182852, 'عریق', '<span class=\"hlight\">عریق .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (اِخ ) موضعی است میان بصره و بحرین . (منتهی الارب ). جایگاهی است مابین بصره و بحرین . (از معجم البلدان ).<br></font></div>'),
(182853, 'عریقصانة', '<span class=\"hlight\">عریقصانة.</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ق ِ ن َ ]</font></b> (ع اِ) حندقوقی . (اقرب الموارد) (از منتهی الارب ). اسم حندقوقی است، یا یربطوره است . (مخزن الادویة). و رجوع به عرقصاء شود.<br></font></div>'),
(182854, 'عریقطان', '<span class=\"hlight\">عریقطان .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ق ِ ]</font></b> (ع اِ) به معنی عریقطة است . (از منتهی الارب ) (از اقرب الموارد). رجوع به عریقطة شود.<br></font></div>'),
(182855, 'عریقیة', '<span class=\"hlight\">عریقیة.</span> <font color=\"DarkGreen\"><b>[ ع َ قی ی َ ]</font></b> (اِخ ) از آبهای بنی عجلان است و آن را نخل بسیار باشد. (از معجم البلدان ).<br></font></div>'),
(182856, 'عریم', '<span class=\"hlight\">عریم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) بلا و سختی . (منتهی الارب ). داهیة. (اقرب الموارد). ج، عُرمان . (اقرب الموارد).<br></font></div>'),
(182857, 'عریمة', '<span class=\"hlight\">عریمة.</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ م َ ]</font></b> (اِخ ) ریگ توده ای است مربنی فزارة را، و یا موضعی است . (منتهی الارب ). رملی است و آن را آبی است بنام عَبسیّة و گویند آن رمله ای است ازآن ِ بنی سعد و برخی آن را برای بنی فزاره دانسته اند. و نیز گویند آن شهری است . (از معجم البلدان ).<br></font></div>'),
(182858, 'عریمة', '<span class=\"hlight\">عریمة.</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ م َ ]</font></b> (اِخ ) پدر قبیله ای از قضاعة است . (از منتهی الارب ).<br></font></div>'),
(182859, 'عرین', '<span class=\"hlight\">عرین .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (اِخ ) ابن ابی جابربن زهیربن جناب بن هبل، از بنی عذرة، از قضاعة. جدّی است جاهلی . و توبل بن بشربن حنظلة که در جنگ صفین از همراهان معاویه بود، از فرزندان او بشمار آید. (از الاعلام زرکلی از اللباب ).<br></font></div>'),
(182860, 'عرین', '<span class=\"hlight\">عرین .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ثعلبةبن یربوع بن حنظلة. جدی است جاهلی و فرزندان او بطنی از تمیم، از عدنانیه را تشکیل دهند. و نسبت بدو عرینی شود. ابوریحانه عبداﷲبن مطر بصری محدث از نسل او است . (از الاعلام زرکلی از نهایةالارب و السبائک ).<br></font></div>'),
(182861, 'عرین', '<span class=\"hlight\">عرین .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) جدی است جاهلی و فرزندان او بطنی از زهیربن جذام، از قحطانیة را تشکیل میدهند و مسکن آنان دقهلیة و مرتاحیة در مصر بوده است . (از الاعلام زرکلی از نهایة الارب ).<br></font></div>'),
(182862, 'عرین', '<span class=\"hlight\">عرین .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) بطنی است از تمیم . (منتهی الارب ). حیی است از تمیم . (از اقرب الموارد).<br></font></div>'),
(182863, 'عرین', '<span class=\"hlight\">عرین .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) بیشه و درختستان که جای شیر و کفتار و گرگ و مار باشد. (منتهی الارب ). بیشه . (دهار). جایگاه شیر. آرامگاه شیر.خانه ٔ شیر. (زمخشری ). مأوای اسد و کفتار و گرگ و مار. (از اقرب الموارد). بیشه و صحرایی پردرخت، و شیررا اکثر به آن نسبت کنند چنانکه گویند شیر عرین، و بعضی که از ناواقفی بجای عین مهمله غین معجمه خوانندخطاست . (غیاث اللغات ) (آنندراج ). کنام شیر. عرینة. ج، عُرُن . (منتهی الارب ) (اقرب الموارد) <span class=\"hlight\">:</span> <br>پیشت بشمندو بی روان گردند<br>شیران عرین چو شیر شادرْوان .<br> <font color=\"Red\">منجیک .</font><br>شده تند کاووس و چین در جبین <br>شده راست مانند شیر عرین .<br> <font color=\"Red\">فردوسی .</font><br>ایزد او را ز پی آنکه عدو نیست کند<br>قوت پیل دمان داد و دل شیر عرین .<br> <font color=\"Red\">فرخی .</font><br>چنان به رای و بتدبیر بی سلیح و سپاه <br>هزبر و پیل برون آرد از میان عرین .<br> <font color=\"Red\">فرخی .</font><br>آنکه با همت او چرخ برین همچو زمین <br>آنکه با هیبت او شیر عرین همچو شکال .<br> <font color=\"Red\">فرخی .</font><br>بدیع لفظ تو درّ است و افتخار صدف <br>بزرگ بأس تو شیر است و روزگار عرین .<br> <font color=\"Red\">عنصری .</font><br>حاسدم گویدچرا تو خدمت خسرو کنی <br>روبهان را کرد باید خدمت شیر عرین .<br> <font color=\"Red\">منوچهری .</font><br>عرین بود دین محمد ولیکن <br>علی بود شیر عرین محمد.<br> <font color=\"Red\">ناصرخسرو.</font><br>علم کجاباشد جز نزد او<br>شیر کجا باشد جز در عرین .<br> <font color=\"Red\">ناصرخسرو.</font><br>لرز لرزنده غضنفر در عرین <br>ترس ترسنده عقاب اندر وکن .<br> <font color=\"Red\">ناصرخسرو.</font><br>شیری و میدان رزمگاه عرینت <br>تیغی و خفتان و مغفر است نیامت .<br> <font color=\"Red\">مسعودسعد.</font><br>نه چو تو گاه بزم ابر بهار<br>نه چو تو گاه رزم شیر عرین .<br> <font color=\"Red\">مسعودسعد.</font><br>چنگ باز هوا ندارد کبک <br>دل شیر عرین ندارد رنگ .<br> <font color=\"Red\">مسعودسعد.</font><br>مهر تابان را در پایه ٔ جاه تو شرف <br>شیر گردون را در سایه ٔ امن تو عرین .<br> <font color=\"Red\">مختاری .</font><br>چون تو گردند حاسدانت اگر<br>شیر رایت شود چو شیر عرین .<br> <font color=\"Red\">انوری .</font><br>آهوی ماده با سیاست تو<br>در عرین دایگان شیران است .<br> <font color=\"Red\">رفیع لنبانی .</font><br>نیست صیادی و عالم پرصید<br>صید را شیر عرین بایستی .<br> <font color=\"Red\">خاقانی .</font><br>چرخ بهر سان که هست زاده ٔ شمشیر اوست <br>گربه بهر حال هست عطسه ٔ شیر عرین .<br> <font color=\"Red\">خاقانی .</font><br>آن نبینی تاز شر شور مور<br>می چه بیند بچه ٔ شیر عرین .<br> <font color=\"Red\">خاقانی .</font><br>ون برآمد چهار سال بر این <br>گور عیار گشت شیر عرین .<br> <font color=\"Red\">نظامی .</font><br>نبود آدمی بلکه شیر عرین .<br> <font color=\"Red\">نظامی .</font><br>باز بفرستادت آن شیر عرین <br>سوی من از مکر ای بئس القرین .<br> <font color=\"Red\">مولوی .</font><br>گفت آخر تو چه میترسی از این <br>چون نمیترسی تو از شیر عرین .<br> <font color=\"Red\">مولوی .</font><br>از نظرْشان کله ٔ شیر عرین <br>واشکافد تا کند آن شیر انین .<br> <font color=\"Red\">مولوی .</font><br>ز گوسفند بدوزد رعایت عدلش <br>دهان گرگ و بدرّد دهان شیر عرین .<br> <font color=\"Red\">سعدی .</font><br>چو شیر رایت او را کند صبا متحرک <br>مجال حمله نماند ز هول شیر عرین را.<br> <font color=\"Red\">سعدی .</font><br>کهن جامه اندر صف آخرین <br>بغرش درآمد چو شیر عرین .<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> سوراخ سوسمار. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خشک و پوسیده ٔ درخت عضاه . (منتهی الارب ). هشیم و پوسیده از عضاه . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درختان بسیار. (منتهی الارب ). جماعت و مقدار بسیار از درخت و خار و عضاه . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خار. (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> گوشت . (منتهی الارب ). لحم . (اقرب الموارد) (مخزن الادویة). <BR><font color=\"Blue\">◄</font> شکار یا شکار گردن شکسته . (منتهی الارب ). فریسة و طعمه ٔ حیوان درنده . <BR><font color=\"Blue\">◄</font> صوت و آواز. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آواز فاخته . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیرامون سرای و شهر. (منتهی الارب ). فِناء و اطراف خانه و شهر، چنانکه گویند: دفن بعرین مکة؛ یعنی در پیرامون و اطراف مکه دفن گشت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ارجمندی . (منتهی الارب ). عِزّ. (اقرب الموارد). ارجمندی و عزت، چنانکه گویند: لایصل أحد الی عرینه ؛ یعنی کسی به عزت و مناعت وی نمیرسد. (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِخ ) کانی است . (منتهی الارب ). نام معدنی است . (ناظم الاطباء). اسم علم است برای معدنی در تُربة. (از معجم البلدان ).<br></font></div>'),
(182864, 'عرینة', '<span class=\"hlight\">عرینة.</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ن َ ]</font></b> (اِخ ) ابن ثوربن کلب بن وبرة، از تغلب، از قضاعة. جدّی است جاهلی . و نسبت بدو عُرَنی شود. (از الاعلام زرکلی از النویری ).<br></font></div>'),
(182865, 'عرینة', '<span class=\"hlight\">عرینة.</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ن َ ]</font></b> (اِخ ) جایگاهی است در بلاد فزارة، و گویند دههایی است در مدینه . (از معجم البلدان ).<br></font></div>'),
(182866, 'عرینة', '<span class=\"hlight\">عرینة.</span> <font color=\"DarkGreen\"><b>[ ع ُ رَن َ ]</font></b> (اِخ ) قبیله ای است . (از اقرب الموارد). قبیله ای از تازیان که در عهد رسول اﷲ (ص ) ارتداد آوردند. و منسوب بدان عُرَنی شود. (از ناظم الاطباء). بطن و طایفه ای بودند از بنی بجیله که در زمان پیغمبر (ص ) مرتد شدند و پیامبر (ص ) تا یک ماه ایشان را در قنوت لعن کرد. رجوع به تاریخ بغداد ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٣</span> شود <span class=\"hlight\">:</span> <br>ازخفاجه بسر راه معونت یابند<br>وز عرینه بلب چاه مواسا بینند.<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(182867, 'عرینة', '<span class=\"hlight\">عرینة.</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ ]</font></b> (ع اِ) بیشه و درختستان که جای شیر و کفتار و گرگ و مار باشد. (منتهی الارب ). مأوای اسد و کفتار و گرگ و مار که در آن الفت کنند. گویند: لیث عرینة و لیث غابة. (از اقرب الموارد). عَرین .رجوع به عرین شود. ج، عَرائن . (از اقرب الموارد).<br></font></div>'),
(182868, 'عرینة', '<span class=\"hlight\">عرینة.</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ن َ ]</font></b> (اِخ ) ابن نذیربن قسربن عبقربن أنمار، از بجیلة، از کهلان، از قحطانیة. جدّی است جاهلی . و تنی چند از نسل او در عهد پیامبر (ص ) به مدینه وارد شدند ولی اقامت در آنجا را نپسندیدند، و برخی دیگر از آنان مرتد شدند و بعضی از شتران را دزدیدند وچوپانان را کور کردند. پیامبر (ص ) نیز دستور داد چشمان آنان را کور کنند. (از الاعلام زرکلی از التاج ).<br></font></div>'),
(182869, 'عرینی', '<span class=\"hlight\">عرینی .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (ص نسبی ) منسوب به عرین بن ابی جابربن زهیربن جناب بن هبل بن عبداﷲبن کنانةبن بکربن عوف بن عذرة، که بطنی است از قضاعة، از عذرة. <BR><font color=\"Blue\">◄</font> منسوب به عرین بن ثعلبةبن یربوع، که بطنی است از تمیم . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(182870, 'عریک', '<span class=\"hlight\">عریک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) مرد درآمده خلقت . (منتهی الارب ): رجل عریک ؛ مرد متداخل گرداندام . (ناظم الاطباء): رمل عریک ؛ ریگ که قسمتی از آن در قسمتی دیگر متداخل باشد. (از اقرب الموارد).<br></font></div>'),
(182871, 'عز', '<span class=\"hlight\">عز.</span> <font color=\"DarkGreen\"><b>[ ع َزز ]</font></b> (ع ص ) رجل عز؛ مرد ارجمند. (ناظم الاطباء). مرد قوی و عزیز. (از اقرب الموارد). عزیز. گرامی . رجوع به عزیز شود.<br></font></div>'),
(182872, 'عز', '<span class=\"hlight\">عز.</span> <font color=\"DarkGreen\"><b>[ ع ِزز ]</font></b> (اِخ ) قلعه ای است به روستای بردعة. (منتهی الارب ). قلعه ای است در رستاق بردعة از نواحی اَران . (از معجم البلدان ).<br></font></div>'),
(182873, 'عز', '<span class=\"hlight\">عز.</span> <font color=\"DarkGreen\"><b>[ع ِزز ]</font></b> (اِخ ) نام دختر هیثم بن محمدبن هیثم، که از زنان محدث و صالح قرن ششم هجری بوده است . وی حدیث را نزد سلیمان بن ابراهیم حافظ آموخت، و سمعانی نام او را آورده است . (از اعلام النساء از التحبیر سمعانی ).<br></font></div>'),
(182874, 'عز', '<span class=\"hlight\">عز.</span> <font color=\"DarkGreen\"><b>[ ع ِزز ]</font></b> (ع اِمص ) ارجمندی . مقابل ذل . (از منتهی الارب ). خلاف ذل . (اقرب الموارد). عزت و ارجمندی . (غیاث اللغات ) <span class=\"hlight\">:</span> <br>دریغ فر جوانی و عز اوی دریغ<br>عزیز بودم از این پیش همچنان سپریغ.<br> <font color=\"Red\">شهید بلخی .</font><br>بماناد جاوید در عز و ناز<br>ازو دور چشم بد و بی نیاز.<br> <font color=\"Red\">فردوسی .</font><br>همه پاک با لشکر و ساز راه <br>همه نامداران ِ با عز و جاه .<br> <font color=\"Red\">فردوسی .</font><br>این عز تو را خواسته ز ایزد<br>وآن عمر تو را خواسته ز یزدان .<br> <font color=\"Red\">فرخی .</font><br>تا چرخ کمان دارد تاکوه کمر دارد<br>از فخر کمان داری وز عز کمر داری .<br> <font color=\"Red\">فرخی .</font><br>ای مرا سایه ٔ درگاه تو سرمایه ٔ عز<br>وز بلاها و جفاهای جهان پشت و پناه .<br> <font color=\"Red\">فرخی .</font><br>خدایگان خراسان و آفتاب کمال <br>که وقف کرد بر او ذوالجلال عز و جلال .<br> <font color=\"Red\">عنصری .</font><br>شاها هزار سال به عز اندرون بزی <br>وآنگه هزار سال بملک اندرون ببال .<br> <font color=\"Red\">عنصری .</font><br>یا رب هزار سال ملک را بقا دهی <br>در عز و در سلامت و در یمن و در یسار.<br> <font color=\"Red\">منوچهری .</font><br>رسم بهمن گیر و از نو تازه کن بهمنجنه <br>ای درخت ملک بارت عز و بیداری تنه .<br> <font color=\"Red\">منوچهری .</font><br>این عز و این کرامت و این فضل و این هنر<br>زآن اصل ثابتست و از آن گوهر اثیر.<br> <font color=\"Red\">منوچهری .</font><br>تیر او باد عز و نعمت و ناز<br>تا بتابد بر آسمان بر تیر.<br> <font color=\"Red\">؟ (از فرهنگ اسدی نخجوانی ).</font><br>و هم بر این خویشتن داری و عز گذشته شد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٦٥</span>). در عز و دولت سالها بزیاد. (تاریخ بیهقی ).<br>نبینی خوب را زشتی مقابل <br>نبینی عزّ را خواری موازی .<br> <font color=\"Red\">ناصرخسرو.</font><br>که را جامه ٔ عزّ ببْرید دنیا<br>بدین بازگردد بدو اعتزازش .<br> <font color=\"Red\">ناصرخسرو.</font><br>اگر خوار است و بی مقدار یمگان <br>مرا اینجا بسی عز است و مقدار.<br> <font color=\"Red\">ناصرخسرو.</font><br>و یک چندی به مقر عز مقام کرد. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٨٢</span>).<br>ای فلک همتی که هرچه کنی <br>مایه ٔ عز و افتخار شود.<br> <font color=\"Red\">مسعودسعد.</font><br>بادا در بوستان عز قرارت <br>بادا اندر سرای ملک مقامت .<br> <font color=\"Red\">مسعودسعد.</font><br>بر سر دولت هنرمندان <br>سایه ٔ عز جاودان تو باد.<br> <font color=\"Red\">مسعودسعد.</font><br>عز دنیا با عز آخرت موصول و مقرون گرداناد. (کلیله و دمنه ). رفتن بر درجات شرف بسیارمؤونت است و فرودآمدن از مراتب عز اندک عوارض . (کلیله و دمنه ). آخر ایشان در نبوت ... را برای عز نبوت و خاتمت رسالت برگزید. (کلیله و دمنه ).<br>عنقا به باغ بخت و سلیمان به تخت عز<br>با جاه نو رسید و به امکان نو نشست .<br> <font color=\"Red\">خاقانی .</font><br>به عز عز مهیمن به حق حق مهین <br>به جان جان پیمبر به سر سر کتاب .<br> <font color=\"Red\">خاقانی .</font><br>عاقلان دیدند آب عز شروان خاک ذل <br>بر هری و بلخ و مرو شاهجان افشانده اند.<br> <font color=\"Red\">خاقانی .</font><br>سلطان ازبهر شرف دین و عز اسلام بدین مصالحت راضی شد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٩٣</span>). در عز چون افریدون بودند و در همت چون گردون . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٩٧</span>). درویشی را شنیدم که به غاری در نشسته بود... به عز قناعت . (گلستان ). و به عز اجابت مقرون . (گلستان ).<br>خدایا به عزت که خوارم مکن <br>به ذل گنه شرمسارم مکن .<br> <font color=\"Red\">سعدی .</font><br>عز ناخفتن ار تو هستی کس <br>نص یا أیها المزمل بس .<br> <font color=\"Red\">اوحدی .</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عز الادب خیر من شرف النسب </span> (امثال و حکم دهخدا)؛ یعنی ارجمندی ادب به از شرافت نسب است .<br>عز الدنیا بالمال و عز الاَّخرة بالاعمال (حدیث )؛ عزت دنیا در مال است و عزت آخرت به کردار.<br>- <span class=\"hlight\">أدام اﷲ عزه </span> ؛ خداوند عزت و ارجمندی وی را پایدار سازد <span class=\"hlight\">:</span> و بشنوده باشد خان أدام اﷲ عزه که چون پدر ما... گذشته شد ما غایب بودیم از تخت ملک . (تاریخ بیهقی ).<br>- <span class=\"hlight\">عز وصول بخشیدن </span> ؛ در تداول نامه نگاری، به معنی رسیدن نامه است، و آن تعبیری است احترام آمیز و بزرگداشت نویسنده را.<br><BR><font color=\"Blue\">◄</font> (ص، اِ) باران سخت . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(182875, 'عز', '<span class=\"hlight\">عز.</span> <font color=\"DarkGreen\"><b>[ ع ِزز ]</font></b> (ع مص ) ارجمندگردیدن . (از منتهی الارب ). ارجمند شدن . (المصادر زوزنی ). عزیز شدن . (تاج المصادر بیهقی ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> قوی شدن بعدِ خواری . (از منتهی الارب ) (از اقرب الموارد). قوی شدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> ضعیف شدن . (تاج المصادر بیهقی ) (از اقرب الموارد). از اضداد است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کمیاب شدن . (از منتهی الارب ). نایافت شدن . (تاج المصادر بیهقی ) (المصادر زوزنی ): عز الشی ٔ؛ کم و قلیل شد آن چیز آنچنانکه به آسانی به دست نیاید، وچنین چیزی را عزیز گویند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> روان گردیدن آب . (از منتهی الارب ): عز الماء؛آب جاری شد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> روان شدن آنچه در زخم بود. (از منتهی الارب ): عزت القرحة؛ آنچه در زخم بود جاری گشت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عز علی َّ أن تفعل کذا؛ ثابت و درشت شد و لازم گردید و دشوار شد بر من چنین کردن تو. (منتهی الارب ). لازم و سخت شد بر من که چنین کنی . (از اقرب الموارد). سخت آمدن کسی از چیزی . (المصادر زوزنی ). و نیز: عزّ علی َّ أن أراک کذا؛ دشوار است بر من اینکه تو راچنین ببینم . (از منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> گرامی شدن . (از منتهی الارب ) (از اقرب الموارد). گویند: عززت ُ علیه ؛ یعنی گرامی شدم نزد او. (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> چون گویند: تُحبنی ؟ در جواب آرند لعزّما؛ یعنی نیک دوست میدارم تو را. (از منتهی الارب ). چون بکسی بگوئی : اء تُحبنی، یعنی آیا مرا دوست داری ؟ در جواب گوید: لعزما، یا لشدّما، یا لحق ّما؛ یعنی حق است آنچه گفته ام . (از اقرب الموارد).<br></font></div>'),
(182876, 'عز', '<span class=\"hlight\">عز.</span> <font color=\"DarkGreen\"><b>[ ع َزْزَ ]</font></b> (ع فعل ) کلمه ٔ فعل که بیشتر در دعا استعمال کنند، یعنی باجلال و مجلل و سربلند باد. (ناظم الاطباء).و این فعل در ترکیب بکار رود چون عز اسمه و عز نصره و عز و جل . رجوع به این ترکیبات در ردیف خود شود.<br></font></div>'),
(182877, 'عز', '<span class=\"hlight\">عز.</span> <font color=\"DarkGreen\"><b>[ ع َزز ]</font></b> (ع مص ) غالب آمدن بر کسی درمعازّة. (از منتهی الارب ). در معارضه ٔ ارجمندی و بزرگی، بر کسی غالب شدن . (از اقرب الموارد). غلبه کردن .(تاج المصادر بیهقی ) (المصادر زوزنی ). <BR><font color=\"Blue\">◄</font> با هم چیرگی کردن در خطاب . (از منتهی الارب ). غلبه کردن کسی را در خطاب و احتجاج . (از اقرب الموارد). گویند: اذا عز أخوک فهُن ؛ یعنی هرگاه برادرت چیره گردد و در پاداشش نتوانی، نرمی و ملاطفت کن . (منتهی الارب ). یعنی اگر برادرت بر تو غلبه کرد و برابری با او نتوانی، پس با او نرمی کن . (از اقرب الموارد). و در مثل گویند: مَن ْ عَزَّ بَزّ؛ یعنی هرکه غالب آمد بُرد.(منتهی الارب ). یعنی هرکه غلبه کند می رباید. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گویند: جی ٔ به عزاً بزاً؛ یعنی بی شک . (منتهی الارب ). یعنی لامحاله او را آوردند. <BR><font color=\"Blue\">◄</font> قوی و توانا کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تنگ شدن سوراخ پستان شتر. (تاج المصادر بیهقی ). عُزوز. عِزاز. رجوع به عزوز و عزاز شود.<br></font></div>'),
(182878, 'عز', '<span class=\"hlight\">عز.</span> <font color=\"DarkGreen\"><b>[ ع َ زِن ْ ]</font></b> (ع ص ) شکیبا و صابر. (منتهی الارب ). آنکه بر پیش آمدی که بدو رسیده است، شکیبائی کند. (از اقرب الموارد). عَزی . رجوع به عزی شود.<br></font></div>'),
(182879, 'عز اسمه', '<span class=\"hlight\">عز اسمه .</span> <font color=\"DarkGreen\"><b>[ ع َزْ زَس ْ م ُه ْ <span class=\"hlight\" dir=\"rtl\">/</span> م ُ هَُ ]</font></b> (ع جمله ٔفعلیه ٔ دعایی ) جمله ٔ دعائی مرکب از فعل و فاعل، به معنی نام او عزیز و ارجمند باد. جمله ٔ دعایی که معمولاً پس از ذکر نام خداوند آرند. ثنائی که پس از بردن نام خدای تعالی آرند. ذکری که پس از بردن نامی از نامهای خدای تعالی آرند. و رجوع به عَزَّ شود <span class=\"hlight\">:</span> <br>که کرد جز خدای عَزَّ اًسمُه ُ<br>رضا رضای او قضا قضای او.<br> <font color=\"Red\">منوچهری .</font><br>بر او ایزد عز اسمه این کرامت پاینده داراد. (فارسنامه ٔ ابن البلخی ).<br>در ذات تو نهاد ملک عَزَّ اًسمُه ُ<br>ذهن و ذکاء و فطنت وفرهنگ و هوش و هنگ .<br> <font color=\"Red\">سوزنی .</font><br>هست امّیدم بصنع و لطف حق عز اسمه <br>کاتصالی باشدم با مجلس عالی بکام .<br> <font color=\"Red\">انوری .</font><br>تقدیر حق عز اسمه چنین بود. (گلستان ). شکر نعمت باری عز اسمه همچنان بر من افزونتر است . (گلستان ). ثروت و دستگاه او باری عز اسمه تمام و مکمل گرداناد. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٤</span>). تا لاجرم حق عز اسمه ... (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(182880, 'عز المقدسی', '<span class=\"hlight\">عز المقدسی .</span><font color=\"DarkGreen\"><b>[ ع ِزْ زُل ْ م َ دِ ]</font></b> (اِخ ) عبدالعزیزبن علی بن ابی العز بکری تیمی قرشی بغدادی مقدسی . قاضی و فقیه دمشق در قرن هشتم و نهم هجری . رجوع به عبدالعزیز... شود.<br></font></div>'),
(182881, 'عز ذکره', '<span class=\"hlight\">عز ذکره .</span> <font color=\"DarkGreen\"><b>[ ع َزْ زَ ذِ رُه ْ ]</font></b> (ع جمله ٔ فعلیه ٔ دعایی ) مرکب از فعل عز + فاعل آن (ذکر). گرامی است یاد او. عزیز است نام او. تسبیحی است که پس از نام خدای تعالی آرند <span class=\"hlight\">:</span> توفیق صلح خواهیم از ایزد عز ذکره . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٧٢</span>). وصیت کنم شما را که خدای عز ذکره به یگانگی شناسید. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٣٨</span>). سیاوش خدای را عز ذکره سجده ٔ شکر برد که او را زنده یافت . (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٤٦</span>). عبادت ایزدی عز ذکره از مردم برداشت .(فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٨٥</span>). و رجوع به عَزَّ شود.<br></font></div>'),
(182882, 'عز علیه', '<span class=\"hlight\">عز علیه .</span> <font color=\"DarkGreen\"><b>[ ع َزْزَ ع َ ل َی ْه ْ ]</font></b> (ع جمله ٔ فعلیه ) عزت بر او باد، و در شاهد ذیل بطور تمسخر به کار رفته است <span class=\"hlight\">:</span> <br>منم از قاضیان مشارالیه <br>وآن دگر ... ماست عز علیه .<br><font color=\"Red\">انوری .</font><br></font></div>'),
(182883, 'عز علیک', '<span class=\"hlight\">عز علیک .</span> <font color=\"DarkGreen\"><b>[ ع َزْ زَ ع َ ل َ ]</font></b> (ع جمله ٔ فعلیه ) عزت بر تو باد <span class=\"hlight\">:</span> <br>نیش بگرفت و گفت عز علیک <br>این چنین دست را که یارد خست .<br><font color=\"Red\">عنصری .</font><br></font></div>'),
(182884, 'عز نصره', '<span class=\"hlight\">عز نصره .</span> <font color=\"DarkGreen\"><b>[ ع َزْ زَ ن َ رُه ْ]</font></b> (ع جمله ٔ فعلیه ٔ دعایی ) (از: فعل عزّ + فاعل، نصر+ ه ) ارجمند است یاری او. و آن را پس از نام شاهان و سلاطین آرند <span class=\"hlight\">:</span> ﷲ المنة که ... بدولت مخدوم عز نصره نوائب بسلامت میگذارد. (عتبةالکتبة ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span>).<br>تو شدی زنده دار جان ملوک <br>عز نصره خدایگان ملوک .<br> <font color=\"Red\">نظامی .</font><br>فکیف در نظر اعیان خداوندی عز نصره که مجمع اهل دل است و مرکز علمای متبحر. (گلستان سعدی ).<br></font></div>'),
(182885, 'عز و جاه', '<span class=\"hlight\">عز و جاه .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُ ]</font></b> (ترکیب عطفی، اِ مرکب ) ارجمندی و جاه . (یادداشت مرحوم دهخدا).<br></font></div>'),
(182886, 'عز و جز', '<span class=\"hlight\">عز و جز.</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُ ج ِزز<span class=\"hlight\" dir=\"rtl\">/</span> ج ِ ]</font></b> (اِ مرکب، از اتباع ) رجوع به عز و چز شود.<br>- <span class=\"hlight\">عزوجز کردن </span> ؛ رجوع به ترکیب «عزوچز کردن » ذیل «عز و چز» شود.<br></font></div>'),
(182887, 'عز و جل', '<span class=\"hlight\">عز و جل .</span> <font color=\"DarkGreen\"><b>[ ع َزْ زَ وَ ج َل ل ]</font></b> (ع جمله ٔ فعلیه ٔ دعایی ) (از: دو فعل عزّ + جل ّ) هر دو صیغه ٔ ماضی است بمعنی غالب شد و بزرگ شد. و این ماضی برای دوام است . (غیاث اللغات ) (آنندراج ). عزیز است وبزرگ و ارجمند. جمله ای است که عقیب نام خدای تعالی آرند <span class=\"hlight\">:</span> تا آنگه که بگویند که خدای عزوجل یکی است و بجز از وی خدای نیست . (ترجمه ٔ تفسیر طبری ).<br>جهان بکام تو دارد خدای عزوجل <br>بودمساعد تو ذو الجلال و الاکرام .<br> <font color=\"Red\">فرخی .</font><br>خدای عزوجل از تنش بگرداناد<br>مکاره دو جهان و وساوس خناس .<br> <font color=\"Red\">منوچهری .</font><br>عالم را خاک کف پای تو کرده ست <br>عزوجل ایزد مهیمن مُتْعال .<br> <font color=\"Red\">منوچهری .</font><br>ایزد عزوجل مدت ... بپایان آورد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٩١</span>). خدای عزوجل ایشان را ازبهر تأیید دولت خداوند مانده است . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٣٢</span>). و بر آن خدای عزوجل واقف است . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٧٤</span>).<br>گفتارشان بدان و بگفتار کار کن <br>تا از خدای عزوجل وحیت آورند.<br> <font color=\"Red\">ناصرخسرو.</font><br>گفتند این اسپ فرشته ای بود کی خدای عزوجل به صورت اسپی گماشت . (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٧٤</span>).<br>حفظ و عون خدای عزوجل <br>بر سر و تَنْش خود و خفتان باد.<br> <font color=\"Red\">مسعودسعد.</font><br>غمین نباشم ازیرا خدای عزوجل <br>دری نبندد تا دیگری بنگشاید.<br> <font color=\"Red\">مسعودسعد.</font><br>آنکه او را خدای عزوجل <br>داد علم علی و عدل عمر.<br> <font color=\"Red\">مسعودسعد.</font><br>کیست ماهی چیست دریا در مثل <br>تا بدان ماند خدا عزوجل .<br> <font color=\"Red\">مولوی .</font><br>قاضی به کشتنم فتوی داد و سلطان مصالح خویش اندر هلاک من همی بیند، بجز خدای عزوجل پناه نمی بینم . (گلستان سعدی ). گفتم سپاس و منت خدای را عزوجل که از برکت درویشان محروم نماندم . (گلستان ).<br>کریم عزوجل غیب دان و مطلع است <br>گرش به جهر بخوانی و گر به خفیه و راز.<br> <font color=\"Red\">سعدی .</font><br>بر خدای عزوجل توکل کرد. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(182888, 'عز و علا', '<span class=\"hlight\">عز و علا.</span> <font color=\"DarkGreen\"><b>[ ع َزْ زَ وَ ع َ ]</font></b> (ع جمله ٔ فعلیه ٔ دعایی ) (از دو فعل عز + علا) عزیز و گرامی است و بلندمرتبه، و آن را پس از ذکر نام خداوند آرند: ایزد عز و علا. حضرت عز و علا.<br></font></div>'),
(182889, 'عز و لابه', '<span class=\"hlight\">عز و لابه .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ مرکب، از اتباع ) عجز و لابه . عز و جز. (فرهنگ لغات عامیانه ). رجوع به عز و جز شود.<br></font></div>'),
(182890, 'عز و ناز', '<span class=\"hlight\">عز و ناز.</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُ ]</font></b> (ترکیب عطفی، اِ مرکب ) ارجمندی و ناز. عزت و نعمت <span class=\"hlight\">:</span> <br>عمر تو بادا بیکران، سود تو بادا بی زیان <br>همواره پای و جاودان، درعز و ناز و عافیه .<br> <font color=\"Red\">منوچهری .</font><br>بر من ز فرت ارجو آن عز و ناز باشد<br>کز فر میر ماضی، بوده ست با غضاری .<br> <font color=\"Red\">منوچهری .</font><br>میگفتند آن نعمتهاکجا شد و آن عز و ناز کجا شد، میرفتند تا به دهی رسیدند. (قصص ص <span class=\"hlight\" dir=\"rtl\">١٣٨</span>).<br>ز خلق تو پرورده ٔ عز و نازند<br>که تو اصل و سرمایه ٔ عز و نازی .<br> <font color=\"Red\">سوزنی .</font><br>شاه عالم را بقا و عز و ناز<br>باد و هر چیزی که باشد زین قبیل .<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(182891, 'عز و چز', '<span class=\"hlight\">عز و چز.</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُ چ ِزز <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِ مرکب، از اتباع ) عز و جز. ظاهراً کلمه ٔ اول تلفظ شکسته ٔ عجز است، بمعنی لابه و زاری . لابه و تضرع و اظهار بیچارگی . (از فرهنگ عوام ). عجز و لابه کردن و از در التماس و درخواست و خواهش و تمنی درآمدن . ظاهراً کلمه ٔ اول صورت تحریف شده ٔ عجز، و دومی از توابع آن است . این ترکیب را گاه به صورت عیز و چیز نیز بکار برند. (از فرهنگ لغات عامیانه ).<br>- <span class=\"hlight\">عز و چز کردن </span> ؛ زاریدن . موییدن .از در التماس و خواهش برآمدن .<br></font></div>'),
(182892, 'عزآباد', '<span class=\"hlight\">عزآباد.</span> <font color=\"DarkGreen\"><b>[ ع ِزز ]</font></b> (اِخ ) دهی از دهستان رستاق بخش اشکذر شهرستان یزد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١١٧٠</span> تن . آب آن از قنات . محصول آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(182893, 'عزآباد', '<span class=\"hlight\">عزآباد.</span> <font color=\"DarkGreen\"><b>[ ع ِزز ]</font></b> (اِخ ) دهی از دهستان مرودشت بخش زرقان شهرستان شیراز. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٢٤</span> تن . آب آن از قنات . محصول آن غلات و حبوب و چغندر است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(182894, 'عزآباد', '<span class=\"hlight\">عزآباد.</span> <font color=\"DarkGreen\"><b>[ ع ِزز ]</font></b> (اِخ ) قریه ای است نیم فرسنگی جنوب ابرقوه . <BR><font color=\"Blue\">◄</font> قریه ای است چهار فرسنگ و نیمی جنوبی جشنیان . <BR><font color=\"Blue\">◄</font> قریه ای است سه فرسخ پیشتر مشرقی فتح آباد. (فارسنامه ).<br></font></div>'),
(182895, 'عزا', '<span class=\"hlight\">عزا.</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زا ]</font></b> (اِخ ) (کفر...) ناحیه ای است از اعمال موصل . و احتمال میرود که آن مأخوذ از عز بمعنی باران شدید باشد و الف آن تأنیث راست . و در این صورت مفهوم آن چیزی شبیه «سرزمین بارانی » خواهد بود. (از معجم البلدان ).<br></font></div>'),
(182896, 'عزا', '<span class=\"hlight\">عزا.</span> <font color=\"DarkGreen\"><b>[ ؟زْ زا ]</font></b> (اِخ ) (بمعنی قوه ) صاحب بوستانی است که در نزدیکی اورشلیم بود و همانجا که قبر منسی و پسرش آمون شهریار یهودا واقع بوده است . و موضع آن بوستان معلوم نیست . (از قاموس کتاب مقدس ).<br></font></div>'),
(182897, 'عزا', '<span class=\"hlight\">عزا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ماتم . مصیبت . تعزیت . زاری . سوکواری . سوک . (ناظم الاطباء). صبر بر مصیبت و صبر کردن و در آن استقامت ورزیدن و شکایت کردن، و در عرف حال مجازاً بمعنی ماتم پرسی . (غیاث اللغات ). و با لفظ گرفتن و افگندن بمعنی ماتم استعمال نمایند، و همچنین با لفظ خانه و دار، چون عزاخانه و عزادار. (آنندراج ). و رجوع به عزاء شود <span class=\"hlight\">:</span> <br>از عزا چون بگذردیک چند روز<br>کم شود آن آتش و آن عشق و سوز.<br> <font color=\"Red\">مولوی .</font><br>قسم بداد به سی پاره درزیان شمط<br>که گر عزا بودت پیش زین عزا مگذر.<br> <font color=\"Red\">نظام قاری (دیوان ص <span class=\"hlight\" dir=\"rtl\">١٧</span>).</font><br>- <span class=\"hlight\">از عزادرآوردن </span> ؛ مصیبت زده را به پوشیدن جامه ای جز رنگ سیاه داشتن . عزاداری را برحسب رسم، بزرگی از خانواده یا جز آن، جامه ای غیر سیاه فرستادن تا به عزای خود خاتمه دهد. (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">ایام عزا</span> ؛ روزهای ماتم و سوگواری و سوک . (ناظم الاطباء).<br>- <span class=\"hlight\">شکمی از عزا درآوردن </span> ؛ پس از گرسنگی طعامی لذیذ و به کفایت خوردن . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">عزا افکندن </span> ؛ سوکواری برپا کردن . ماتم و شیون پدید آوردن <span class=\"hlight\">:</span> <br>تاکنون شخصی که باشد قابل ماتم نمرد<br>من از آن مُردم که در عالم عزائی افگنم .<br> <font color=\"Red\">حکیم رکنای کاشی (از آنندراج ).</font><br>- <span class=\"hlight\">لباس عزا</span> ؛ لباس سیاه . (آنندراج ). لباس که در حال عزا گرفتن پوشند. لباس سوک .<br></font></div>'),
(182898, 'عزا داشتن', '<span class=\"hlight\">عزا داشتن .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (مص مرکب ) ماتم داشتن پس از مرگ کسی . (فرهنگ فارسی معین ). سوکوار بودن .<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(182899, 'عزا گرفتن', '<span class=\"hlight\">عزا گرفتن .</span> <font color=\"DarkGreen\"><b>[ ع َ گ ِ رِ ت َ ]</font></b> (مص مرکب ) زاری و شیون کردن و به حالت ماتم زدگان درآمدن و برای سوک و مصیبت لباس سیاه در بر کردن . (ناظم الاطباء). مجلس ماتم گرفتن در مرگ عزیزی . (فرهنگ عوام ). اقامه ٔ سوکواری بسبب مرگ کسی . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>گر ماه و آفتاب بمیرد عزا مگیر<br>گر تیر و زهره کشته شود نوحه خوان مخواه .<br> <font color=\"Red\">عرفی (از آنندراج ).</font><br>سازد بخیل دشمن خود کائنات را<br>تا کس به مرگ او نتواند عزا گرفت .<br> <font color=\"Red\">میر یحیی شیرازی (از آنندراج ).</font><br>نی همدمی که پرسد در محنتم خبر<br>نی دوستی که گیرددر مردنم عزا.<br><font color=\"Red\">سنجر کاشی (از آنندراج ).</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">نمرده عزا نگیرد</span>، نظیر: پیش از مرگ واویلا. (امثال و حکم دهخدا).<br><BR><font color=\"Blue\">◄</font> در تداول امروز فارسی زبانان، برای رفع مشکلی دستخوش حیرت شدن : عزا گرفته ام (یعنی متحیرم ) که این همه قرض خود را از کجا بدهم . عزا گرفته ام که این مشکل خود را چگونه حل کنم . (از فرهنگ عوام ). حالت ماتمزده بخود گرفتن از واقعه ٔ ناگواری یا وامی یا از دست دادن چیزی یا از بیم به دست نیاوردن چیزی .<br></font></div>'),
(182900, 'عزاب', '<span class=\"hlight\">عزاب .</span> <font color=\"DarkGreen\"><b>[ ع ُزْ زا ]</font></b> (ع ص، اِ) ج ِ عَزَب . (اقرب الموارد) (منتهی الارب ). رجوع به عزب شود. <BR><font color=\"Blue\">◄</font> ج ِ عَزَبة. (منتهی الارب از کسائی ) (آنندراج ). رجوع به عزبة شود.<br></font></div>'),
(182901, 'عزاخانه', '<span class=\"hlight\">عزاخانه .</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) ماتم خانه و خانه ای که در آن عزا برپا می کنند. (ناظم الاطباء). جایی که در آن مراسم عزا برپا دارند. (فرهنگ فارسی معین ). ماتم سرا. مصیبت سرا. مَناحة <span class=\"hlight\">:</span> <br>به دارالشفا چون درآید طبیب <br>عزاخانه گردد ز مرگ غریب .<br><font color=\"Red\">ملاطغرا (از آنندراج ).</font><br></font></div>'),
(182902, 'عزادار', '<span class=\"hlight\">عزادار.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (نف مرکب ) ماتم زده و آنکه بحالت عزا و سوگواری باشد. (ناظم الاطباء). شخصی که بمناسبت فوت یکی از نزدیکان سوکوار باشد. (فرهنگ فارسی معین ). ماتمی . مصیبت زده . سوکوار.<br>شادی و عیش عالم در خاطر دل افکار<br>شرمنده تر ز عید است در خانه ٔ عزادار.<br> <font color=\"Red\">محمدسعید اشرف (از آنندراج ).</font><br>دوستان را نبود بس که بهم یکرنگی <br>پوشش مرده سفید است و عزادار سیاه .<br><font color=\"Red\">میرزا اسماعیل ایما (از آنندراج ).</font><br></font></div>'),
(182903, 'عزاداری', '<span class=\"hlight\">عزاداری .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (حامص مرکب ) سوکواری .زاری . عزاپرستی . اشتغال به سوک . مصیبت . تعزیت . (ناظم الاطباء). اقامه ٔ مراسم عزا. (فرهنگ فارسی معین ).<br></font></div>'),
(182904, 'عزاداری کردن', '<span class=\"hlight\">عزاداری کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ دَ ]</font></b> (مص مرکب ) برپا داشتن مراسم عزا. سوکواری کردن . (فرهنگ فارسی معین ). ماتم گرفتن .<br></font></div>'),
(182905, 'عزاز', '<span class=\"hlight\">عزاز.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) تنگ پستان شدن ناقه . (از منتهی الارب ). «عَزوز» بودن ناقه . (از اقرب الموارد). رجوع به عَزوز شود. عُزوز. <BR><font color=\"Blue\">◄</font> معازّه و چیرگی جستن بر یکدیگر در خطاب و نبرد کردن در ارجمندی . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (ص، اِ) ج ِ عَزیز. (اقرب الموارد) (منتهی الارب ). رجوع به عزیز شود.<br></font></div>'),
(182906, 'عزاز', '<span class=\"hlight\">عزاز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) جایگاهی است در یمن . (از معجم البلدان ) (از منتهی الارب ).<br></font></div>'),
(182907, 'عزاز', '<span class=\"hlight\">عزاز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) شهری است نزدیک حلب که خاکش چون بر کژدم پاشند بمیرد. (منتهی الارب ). شهرکی است در فاصله ٔ یک روزه ٔ شمال حلب، و آن را رستاقی است . آب و هوائی گوارا دارد و در آنجا عقرب یافت نشود و مشهور چنان است که اگر از خاک آن بر عقرب بریزند آن را میکشد. (از معجم البلدان ).<br></font></div>'),
(182908, 'عزاز', '<span class=\"hlight\">عزاز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) زمین درشت . (منتهی الارب ). سرزمین صلب و سخت، که سیل در آن بسرعت جاری شود. (از اقرب الموارد). عَزَز. و رجوع به عزز شود.<br></font></div>'),
(182909, 'عزازی', '<span class=\"hlight\">عزازی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابوالعباس احمد ابن عمر عزازی، منسوب به عزاز حلب . وی محدث بود و از ابوالحسن علی بن احمدبن مرزبان روایت کرده است . (از معجم البلدان ).<br></font></div>'),
(182910, 'عزازیل', '<span class=\"hlight\">عزازیل .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) (معرب از عبری ) طبق روایات، یکی از سه فرشته (هاروت، ماروت، عزازیل ) است که خدا آنان را به کره ٔ زمین فرستاد تا مانند آدمیان زندگی کنند و ازمحرمات بپرهیزند والا تنبیه شوند. عزازیل پس از چندی چون دانست که از عهده ٔ این امتحانات برآمدن مشکل است اظهار عجز نمود و معاف شد، ولی دو تن دیگر به مأموریت خود ادامه دادند و فریب زنی (زهره = ناهید) را خوردند، شراب نوشیدند و اسم اعظم را بدان زن گفتند وبه پادافراه این کردار در چاه بابل معلق شدند و تا روز رستاخیز بدین حال خواهند ماند. (از فرهنگ فارسی معین ). و رجوع به «ستاره ٔ ناهید» از محمد معین شود. <BR><font color=\"Blue\">◄</font> از نامهای قدیمی شیطان . (از اقرب الموارد). نام شیطان . (غیاث اللغات ) (آنندراج ). شیطان . (قاموس کتاب مقدس ). ابلیس . ابوخلاف . ابوالعیزار. ابومرة. ابولبینی . بلأز. خناس . دیو. شیخ نجدی <span class=\"hlight\">:</span> <br>کشوری گیر بیک حمله که آن کشور را<br>پادشاهست عزازیل و مهاکال وزیر.<br> <font color=\"Red\">سوزنی .</font><br>بد ز گستاخی کسوف آفتاب <br>شد عزازیلی ز جرأت رد باب .<br> <font color=\"Red\">مولوی .</font><br>شد عزازیلی از این مستی بلیس <br>که چرا آدم شود بر من رئیس .<br> <font color=\"Red\">مولوی .</font><br>وگر دردهد یک صلای کرم <br>عزازیل گوید نصیبی برم .<br> <font color=\"Red\">سعدی .</font><br>تکبر عزازیل را خوار کرد.<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> (اِ) روح پلید. <BR><font color=\"Blue\">◄</font> نام مرغی است کوچک . (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> اشاره به بزی است که در وادی غیرذی زرع فرستاده میشد. <BR><font color=\"Blue\">◄</font> اشاره است به انفصال خطایای قوم، و مختصراً بر ذبح شده اشاره به کفاره ٔ خطایای قوم است . <BR><font color=\"Blue\">◄</font> (اِخ ) اسم محلی است که بز را در آنجا میفرستادند. (قاموس کتاب مقدس ).<br></font></div>'),
(182911, 'عزاف', '<span class=\"hlight\">عزاف .</span> <font color=\"DarkGreen\"><b>[ ع َزْ زا ]</font></b> (اِخ )کوهی است از کوههای دهناء، و گویند رملی است ازآن ِ بنی سعد که آن را أبرق العزاف گویند و در کوه کوچکی که در آنجا است قرار دارد. و گویند آن در سمت چپ راه کوفه از زَرود واقع است و فاصله ٔ آن را تا مدینه دوازده میل دانسته اند. وجه تسمیه ٔ آن چنین است که عزیف و صوت جن از آنجا شنیده میشود. (از معجم البلدان ).<br></font></div>'),
(182912, 'عزاف', '<span class=\"hlight\">عزاف .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص، اِ) ج ِ عَزوف . (اقرب الموارد). رجوع به عزوف شود.<br></font></div>'),
(182913, 'عزاف', '<span class=\"hlight\">عزاف .</span><font color=\"DarkGreen\"><b>[ ع َزْ زا ]</font></b> (ع ص ) ابر باآواز. (منتهی الارب ). ابری که در آن صدا و آواز رعد باشد. (از اقرب الموارد).<br></font></div>'),
(182914, 'عزاقری', '<span class=\"hlight\">عزاقری .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ]</font></b> (اِخ ) ابن الندیم در الفهرست گوید که وی در صنعت کیمیا بحث کرده و گویند به عمل اکسیر تام دست یافته است .<br></font></div>'),
(182915, 'عزاقریة', '<span class=\"hlight\">عزاقریة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ری ی َ ]</font></b> (اِخ ) پیروان ابن العزاقر ابوجعفر محمدبن علی شَلمَغانی میباشند. وی ازجمله ٔ کسانی است که در قرن چهارم هجری به مخالفت با حسین بن روح برخاست و مذهب جدیدی تأسیس کرد و پیروان او به عزاقریه یا شلمغانیه شهرت دارند. مهمترین عقاید عزاقریه عبارتست از: <span class=\"hlight\" dir=\"rtl\">١</span>- خداوند در هر چیزی به اندازه ٔ تحمل آن چیز حلول می کند، و شلمغانی کسی است که روح خداوند در او بتمامه حلول کرده است . و اصلاً خدا اسمی است جهت معانی و خاطره هایی که به قلب مردم خطور می کند و آنچه را بر مردم پنهان است متصوَّر مینماید تا آنجا که گوئی مردم آن را به مشاهده درمی یابند. هر کس که مردم به او احتیاج پیدا می کنند خدای ایشان است بهمین جهت هر فردی از افراد بشر می تواند استحقاق مقام الوهیت حاصل کند و بنام خدائی خوانده شود. <span class=\"hlight\" dir=\"rtl\">٢</span>- عزاقریه امام حسن و امام حسین را به علی بن ابی طالب منسوب نمیدانستند و میگفتندمقام الوهیت در شخصی جمع می آید که نه فرزند کسی و نه او را فرزندی باشد. موسی (ع ) و محمدبن عبداﷲ (ص ) را خائن میشمردند و میگفتند که هارون موسی را و علی بن ابی طالب محمدبن عبداﷲ را به رسالت فرستادند و این دو نسبت به فرستندگان خود خیانت ورزیدند. علی بن ابی طالب بتصور ایشان به شماره ٔ ایام اصحاب کهف که <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> سال است به محمدبن عبداﷲ مهلت داد و چون این مدت منقضی گردیده شریعت اسلام نیز برمیگردد، و گویا غرض ایشان از این شمارش این بوده است که <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> سال بعد از بعثت حضرت رسول که مقارن ایام ظهور دعوت شلمغانی است مذهب اسلام منسوخ و مذهب شلمغانی جای آن برقرار میشود. <span class=\"hlight\" dir=\"rtl\">٣</span>- ملائکه به عقیده ٔ آنان کسانی هستند که زمام نفس خود رادر دست داشته و حق را بشناسند و ببینند، و بهشت شناختن ایشان و پیروی از مذهب آنان است و آتش نشناختن آن جمع و برگشت از مسلک ایشان . <span class=\"hlight\" dir=\"rtl\">٤</span>- عزاقریه به ترک نماز و روزه و غسل معتقد بودند و بر روش سنت ازدواج نمیکردند و عموم زنان را بر خود مباح میدانستند و نزدیکی با زنان محارم و زنان دوستان و حرم پسران در صورتی که در دین شلمغانی آمده باشند اشکالی ندارد. <span class=\"hlight\" dir=\"rtl\">٥</span>- از مهمترین عقاید عزاقریه اعتقاد آنان به ضد بوده است به این معنی که شلمغانی میگفته است خداوند وجود ضد راخلق کرده است تا بوسیله ٔ آن پی به مخالف آن برده شود و تا اضداد در برگزیدگان خدا طعن نزنند فضیلت ایشان ظاهر نمیگردد و بهمین جهت اضداد از اولیأاﷲ مقامشان برتر است . <span class=\"hlight\" dir=\"rtl\">٦</span>- بعقیده ٔ عزاقریه، خداوند وقتی که درجسدی ناسوتی حلول میکند آنچنان قدرت و معجزه در او بظهور میرسد که با خداوند یکی میشود، چنانکه این حال در هفت آدم (هر آدمی مطابق با یک عالم ) ظاهر شد و بعد از آدم هفتمین در جسد پنج وجود ناسوتی دیگر و پنج ضد ایشان که عنوان ابلیس داشتند حلول کرد، بعد در ادریس و ابلیس او، سپس در نوح و ابلیس او نمرود، بعد در هارون و ابلیس او فرعون، سپس در داود و ابلیس او جالوت، بعد در سلیمان و ابلیس او، بعد در عیسی و ابلیس او، بعد در علی بن ابی طالب و ابلیس او. و بعد از علی بن ابی طالب در شلمغانی و ابلیس او جمع آمد. <span class=\"hlight\" dir=\"rtl\">٧</span>- در باب قائم آل محمد که بعقیده ٔ امامیه از فرزندان امام یازدهم است و در موقع مناسب قیام خواهد کرد، عزاقریه میگفتند این همان ابلیس است که در قرآن به آن اشاره شده «فسجد الملائکة کلهم أجمعون الا ابلیس » (<span class=\"hlight\" dir=\"rtl\">٣٠/١٥</span> -<span class=\"hlight\" dir=\"rtl\">٣١</span>) و چون ابلیس سجود نکرد و گفت که «لأقعدن لهم صراطک المستقیم » (<span class=\"hlight\" dir=\"rtl\">١٦/٧</span>) از اینجا معلوم می شود که در موقع امر به سجود او قائم بوده و بعد نشسته است، و اینکه شیعه میگویند که قائم قیام خواهد کرد این همان ابلیس است که در موقع امر به سجود قائم بوده و از سجده ابا نموده است . <span class=\"hlight\" dir=\"rtl\">٨</span>- عزاقریه از آل ابی طالب و بنی عباس نفرت داشتند و هلاک ایشان را واجب میشمردند. (از خاندان نوبختی صص <span class=\"hlight\" dir=\"rtl\">٢٢٢</span> - <span class=\"hlight\" dir=\"rtl\">٢٣٨</span>). و رجوع به شلمغانی شود.<br></font></div>'),
(182916, 'عزال', '<span class=\"hlight\">عزال .</span> <font color=\"DarkGreen\"><b>[ ع ُزْ زا ]</font></b> (اِ) نام پرده ای از موسیقی است که آن شعبه ای از زنگوله باشد. و آن را به تخفیف زاء نیز خوانده اند. (از غیاث اللغات ) (از آنندراج ).<br></font></div>'),
(182917, 'عزال', '<span class=\"hlight\">عزال .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِمص ) ضعف . (اقرب الموارد). سستی و ضعف . (ناظم الاطباء). سست . (منتهی الارب ).<br></font></div>'),
(182918, 'عزالان', '<span class=\"hlight\">عزالان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) دو پر کلان در طرف دنب عقاب . (منتهی الارب ). دو پری که در سمت دم عقاب است . (از اقرب الموارد).<br></font></div>'),
(182919, 'عزالدولة', '<span class=\"hlight\">عزالدولة.</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دَ ل َ ]</font></b> (ع اِ مرکب ) ارجمندی دولت . آنچه یا آنکه سبب ارجمندی و عزت دولت است، و آن از القاب اشخاص بوده است .<br></font></div>'),
(182920, 'عزالدوله', '<span class=\"hlight\">عزالدوله .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دَ ل َ ]</font></b> (اِخ ) سعدبن منصور اسرائیلی، مشهور به ابن کمونه . صاحب شبهه ٔ مشهوره است . رجوع به ابن کمونه شود.<br></font></div>'),
(182921, 'عزالدوله', '<span class=\"hlight\">عزالدوله .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دَ ل َ ]</font></b> (اِخ ) عبدالرشیدبن محمود غزنوی، مکنی به ابومنصور. از پادشاهان غزنوی، و شخصی بی جرأت بود و زیر نفوذ یکی از درباریان خود بنام طغرل (طغرل کافرنعمت ) قرار داشت . و سرانجام به سال <span class=\"hlight\" dir=\"rtl\">٤٤٤</span> هَ .ق . به دست همین طغرل بقتل رسید. (از فرهنگ فارسی معین ).<br></font></div>'),
(182922, 'عزالدوله', '<span class=\"hlight\">عزالدوله .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دَ ل َ ]</font></b> (اِخ ) عبدالعزیزبن محمد بکری، مکنی به ابوزید. حاکم شلطیس  و ولبة در اندلس . حکومت این دو ناحیه بسال <span class=\"hlight\" dir=\"rtl\">٤٠٣</span> هَ .ق . پس از مرگ پدرش بوی رسید. به سال <span class=\"hlight\" dir=\"rtl\">٤٤٣</span> هَ .ق . چون المعتضد عباد بر ولبة دست یافت عزالدوله به قرطبه رفت و تا زمان مرگ درحمایت ابن جهور بود و در حدود سال <span class=\"hlight\" dir=\"rtl\">٤٥٠</span> درگذشت . وی پدر ابوعبید بکری صاحب المسالک و الممالک میباشد. (ازالاعلام زرکلی از البیان المغرب و معجم ما استعجم ).<br></font></div>'),
(182923, 'عزالدوله', '<span class=\"hlight\">عزالدوله .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دَ ل َ ]</font></b> (اِخ ) بختیاربن معزالدوله ابوالحسین احمدبن بویه دیلمی . از دیالمه ٔ عراق و اهوازو کرمان (<span class=\"hlight\" dir=\"rtl\">٣٥٦</span> - <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> هَ .ق .). وی پس از مرگ پدر بر متصرفات او دست یافت . شخصی قوی و توانا بود و گویند وی گاوی بزرگ را از دو شاخ میگرفت و آن را بزمین می افکند. عزالدوله با پسرعمش عضدالدوله بر سر برخی سرزمین ها رقابتهائی داشتند که به جنگ آن دو انجامید و در روز چهارشنبه هجدهم شوال سال <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> هَ .ق . در میدان جنگ با هم روبرو شدند و عزالدوله که در آن هنگام سی وشش سال داشت به دست سپاهیان پسرعمش کشته شد. (از وفیات الاعیان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٢</span>). و رجوع به طبقات سلاطین اسلام شود.<br></font></div>'),
(182924, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) عبدالحمیدبن محمدبن محمدبن حسین مداینی، مشهور به ابن ابی الحدید. شارح نهج البلاغة در قرن هفتم هجری . رجوع به ابن ابی الحدید شود.<br></font></div>'),
(182925, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) علی بن ابی الکرم محمدبن محمدبن عبدالکریم شیبانی جزری، مکنی به ابوالحسن . مورخ معروف قرن ششم و هفتم هجری . رجوع به ابن اثیر و علی (ابن محمدبن محمدبن عبدالکریم ...) شود.<br></font></div>'),
(182926, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ع ِزْ زُدْ دی ]</font></b> (اِخ ) عبدالعزیزبن محمدبن ابراهیم، مکنی به ابوعمر و مشهور به ابن جماعة. قاضی مصر در قرن هشتم هجری . رجوع به ابن جماعة و عبدالعزیز شود.<br></font></div>'),
(182927, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) عبدالسلام بن احمدبن غانم مقدسی . رجوع به ابن غانم و عبدالسلام شود.<br></font></div>'),
(182928, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) عبدالرحیم بن محمدبن الفرات قاهری، مشهور به ابن فرات . رجوع به عبدالرحیم (ابن محمد...) شود.<br></font></div>'),
(182929, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) طغرل طغان خان . هشتمین از حکام بنگاله . رجوع به طغان خان و به طبقات سلاطین اسلام شود.<br></font></div>'),
(182930, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) طغرل تکین . رجوع به طغرل بک در همین لغت نامه و تاریخ بیهق چ تهران ص <span class=\"hlight\" dir=\"rtl\">٢٢٦</span> شود.<br></font></div>'),
(182931, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ )طغرل بک (امیر اس-فهسالار...). رجوع به طغرلبک شود.<br></font></div>'),
(182932, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) محمد شیران بن محمد بختیار خلجی . از حکام بنگاله است و از سال <span class=\"hlight\" dir=\"rtl\">٦٠٢</span> تا <span class=\"hlight\" dir=\"rtl\">٦٠٥</span> هَ .ق . در آنجا حکومت کرده است . (از طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">٢٧٥</span>).<br></font></div>'),
(182933, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) علی بن محمدبن آیدمر جلدکی، ملقب به عزالدین . شیمیدان (کیمیاگر) قرن هشتم هجری . رجوع به علی جلدکی شود.<br></font></div>'),
(182934, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) طاهربن زنگی بن طاهر فریومدی جوینی، مکنی به ابوطیب . از رجال اواسط قرن هفتم هجری . وی به سال <span class=\"hlight\" dir=\"rtl\">٦٥١</span>هَ .ق . از جانب امیر ارغون مغول به نیابت حکومت خراسان و مازندران تعیین شد و تا سال <span class=\"hlight\" dir=\"rtl\">٦٥٦</span> هَ .ق . در منصب خود باقی بود و در این سال هلاکو او را معزول کرد. وی شخصی ادب دوست و شاعرپرور بود و سعدالدین سعید هروی شاعر از مداحان مخصوص اوست . (فرهنگ فارسی معین ).<br></font></div>'),
(182935, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) بلبن بن جلال الدین مسعود ملک جانی . از حکام بنگاله است و از سال <span class=\"hlight\" dir=\"rtl\">٦٥٧</span> تا <span class=\"hlight\" dir=\"rtl\">٦٥٩</span> هَ .ق . حکومت کرده است . (از طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">٢٧٥</span>).<br></font></div>'),
(182936, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) بلبان بن محمدالمنصور. از شاهان ارمینیه است که از سال <span class=\"hlight\" dir=\"rtl\">٦٠٣</span> تا <span class=\"hlight\" dir=\"rtl\">٦٠٤</span> هَ .ق . حکومت کرد. (از طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">١٥٢</span>).<br></font></div>'),
(182937, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) اعظم الملک (ست گائون ) بن قدرخان . از حکام بنگاله است و از سال <span class=\"hlight\" dir=\"rtl\">٧٢٤</span> تا <span class=\"hlight\" dir=\"rtl\">٧٤٠</span> هَ .ق . در آنجا حکومت کرده است . (از طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">٢٧٦</span>).<br></font></div>'),
(182938, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) ارسلان شاه بن مسعودبن مودودبن زنگی بن آق سنقر، مشهور به اتابک و ملقب به الملک العادل . ششمین از اتابکان موصل . رجوع به ارسلانشاه شود.<br></font></div>'),
(182939, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) احمدبن محمدبن عبدالرحمان شریف حسینی مصری، مکنی به ابوالعباس و ملقب به عزالدین . رجوع به احمد (ابن محمد...) شود.<br></font></div>'),
(182940, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) احمدبن فیومی قرصی، مشهور به عزالدین بن قراصه . رجوع به احمد (ابن فیومی ...) شود.<br></font></div>'),
(182941, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) ابن حسن بن علی المؤید. از امامان و پیشوایان زیدیه در یمن . وی بسال <span class=\"hlight\" dir=\"rtl\">٨٤٥</span> هَ .ق . متولد شد و بسال <span class=\"hlight\" dir=\"rtl\">٨٧٩</span> مردم برخی از شهرهای یمن با وی بیعت کردند و او را لقب الهادی الی الحق دادند. و سرانجام بسال <span class=\"hlight\" dir=\"rtl\">٩٠٠</span> در صنعاء درگذشت . او را کتابهایی است که از آن جمله المعراج فی شرح المنهاج، و الفتاوی، و دیوان شعر وی را میتوان نام برد. (از الاعلام زرکلی از العقیق الیمانی و البدر الطالع).<br></font></div>'),
(182942, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) آی بیک . از ممالیک بحری . رجوع به آی بیک عزالدین در همین لغت نامه و به طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">٧١</span> شود.<br></font></div>'),
(182943, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) دهی جزء دهستان رودبار بخش طرخوران شهرستان اراک .سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> تن . آب آن از قره چای . محصول آن غلات و بنشن و پنبه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(182944, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (ع اِ مرکب ) ارجمندی دین . آنکه یا آنچه سبب عزت وارجمندی دین گردد، و آن از القاب اشخاص بوده است .<br></font></div>'),
(182945, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْزُدْ دی ]</font></b> (اِخ ) قلج ارسلان ثانی ابن مسعود اول . از سلاجقه ٔ روم (آسیای صغیر) است و از سال <span class=\"hlight\" dir=\"rtl\">٥٥١</span> تا <span class=\"hlight\" dir=\"rtl\">٥٨٤</span> هَ .ق . حکومت کرده است . (از طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">١٣٧</span>).<br></font></div>'),
(182946, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) مسعود اول ابن قطب الدین مودود. از اتابکان موصل (آقسنقریان ) و از سال <span class=\"hlight\" dir=\"rtl\">٥٧٦</span> تا <span class=\"hlight\" dir=\"rtl\">٥٨٩</span> هَ .ق . در موصل و شام و سنجار و الجزیره حکومت کرده است . (از طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">١٤٤</span>) (از فرهنگ فارسی معین ).<br></font></div>'),
(182947, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) مسعود ثانی ابن نورالدین ارسلانشاه، مکنی به ابوالفتح و ملقب به الملک القاهر. از اتابکان موصل (آقسنقریان ) و از سال <span class=\"hlight\" dir=\"rtl\">٦٠٧</span> تا <span class=\"hlight\" dir=\"rtl\">٦١٥</span> هَ .ق . در موصل و شام و سنجار و الجزیره حکومت کرد و اقبالنامه ٔ نظامی بنام او مصدّر است .(از طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">١٤٤</span>) (فرهنگ فارسی معین ).<br></font></div>'),
(182948, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b> (اِخ ) کیکاوس اول ابن کیخسرو اول . از سلاجقه ٔ روم (آسیای صغیر) است و از سال <span class=\"hlight\" dir=\"rtl\">٦٠٧</span> تا <span class=\"hlight\" dir=\"rtl\">٦١٦</span> هَ .ق . در آنجا حکومت کرده است . (از طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">١٣٨</span>).<br></font></div>'),
(182949, 'عزالدین', '<span class=\"hlight\">عزالدین .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ]</font></b>(اِخ ) کیکاوس ثانی ابن غیاث الدین کیخسرو ثانی . از سلاجقه ٔ روم (آسیای صغیر) است و از سال <span class=\"hlight\" dir=\"rtl\">٦٤٣</span> تا <span class=\"hlight\" dir=\"rtl\">٦٥٥</span> هَ .ق . حکومت کرده است . (از طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">١٣٨</span>).<br></font></div>'),
(182950, 'عزالدین زنجانی', '<span class=\"hlight\">عزالدین زنجانی .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ن ِ زَ ]</font></b> (اِخ ) عبدالوهاب بن ابراهیم، مکنی به ابوالمعالی و ملقب به عزالدین . از ادبا و علمای مشهور صرف و نحو. وی قسمت اخیر عمر خود را در بغداد میگذرانده و تا مقارن فتح آن شهر به دست هلاکو در آنجا میزیسته و گویا در واقعه ٔ بغداد مقتول شده است . رجوع به عبدالوهاب در همین لغت نامه و به تاریخ مغول عباس اقبال شود.<br></font></div>'),
(182951, 'عزالدین قسام', '<span class=\"hlight\">عزالدین قسام .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ن ِ ق َس ْ سا ]</font></b> (اِخ ) محمد عزالدین بن عبدالقادر قسام . از مجاهدان عرب بود. وی به سال <span class=\"hlight\" dir=\"rtl\">١٣٠٠</span> هَ .ق . متولد شد و در سال <span class=\"hlight\" dir=\"rtl\">١٩١٨</span>م . با گروهی از شاگردان خود علیه فرانسویان که سوریه را اشغال کرده بودند قیام کرد. مدتی در حیفا (فلسطین ) اقامت گزید و عهده دار امامت جامع الاستقلال گشت . در این اوان شیخ محمد کامل القصاب را برای تألیف کتاب النقد و البیان یاری کرد. آنگاه در قیام مردم فلسطین علیه انگلیسی ها شرکت کرد و شجاعتهای بسیاری از خود نشان داد و سرانجام بسال <span class=\"hlight\" dir=\"rtl\">١٣٥٤</span> هَ .ق . شهید شد و درقریه ٔ الشیخ نزدیک حیفا دفن گشت . (از الاعلام زرکلی از مجلة الفتح و الاعلام الشرقیة و فلسطین المجاهدة).<br></font></div>'),
(182952, 'عزالدین قطبی', '<span class=\"hlight\">عزالدین قطبی .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ن ِ ق ُ ]</font></b> (اِخ ) ابن احمدبن دریب . از امیران یمانی است . او را برادرش مهدی (حاکم جازان ) به سرداری یا رهنمایی سپاهیان مصر فرستاد و آنان شهر زبید را گشودند. سپس عزالدین به سال <span class=\"hlight\" dir=\"rtl\">٩٢٤</span> هَ .ق . برادر خود را دستگیر کرد و خود بر جازان مستولی گشت و به سال <span class=\"hlight\" dir=\"rtl\">٩٣٠</span> به دست اسکندر قرمانی بقتل رسید. (ازالاعلام زرکلی از العقیق الیمانی و الطائف السنیة).<br></font></div>'),
(182953, 'عزالدین کاشانی', '<span class=\"hlight\">عزالدین کاشانی .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زُدْ دی ن ِ ]</font></b> (اِخ ) وزیر سلطان طغرل سلجوقی بود. آنگاه که سلطان به اتابکان مظنون گشت عزالدین را که سوابق اخلاص با آنان داشت، همراه پسرش در قلعه ٔ همدان بقتل رساند. (از دستور الوزراء ص <span class=\"hlight\" dir=\"rtl\">٢٢٠</span>).<br></font></div>'),
(182954, 'عزالی', '<span class=\"hlight\">عزالی .</span> <font color=\"DarkGreen\"><b>[ ع َ لا <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ]</font></b> (ع اِ) ج ِ عَزلاء. (منتهی الارب ) (اقرب الموارد). رجوع به عزلاء شود.<br></font></div>'),
(182955, 'عزام', '<span class=\"hlight\">عزام .</span> <font color=\"DarkGreen\"><b>[ ع َزْ زا ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ). اسد. (اقرب الموارد).<br></font></div>'),
(182956, 'عزان', '<span class=\"hlight\">عزان .</span> <font color=\"DarkGreen\"><b>[ ع َزْ زا ]</font></b> (اِخ ) ابن قیس بن عزان بن قیس بن احمدبن سعید بوسعیدی . از امامان عمان . بسال <span class=\"hlight\" dir=\"rtl\">١٢٨٥</span> هَ .ق . پس از خلع سلطان سالم بن ثوینی، با وی در مسقط بیعت شد و رایتهای سپید که شعار خاندان او بود برافراشته گشت . امامت وی بیست وهشت ماه و نیم بطول انجامید و در این مدت وی غالب متصرفاتی را که به دست امیرزادگان افتاده بود بازستاند و مردم در عصر کوتاه امامت او در راحتی میزیستند و سرانجام بسال <span class=\"hlight\" dir=\"rtl\">١٢٨٧</span> هَ .ق . به دست ترکی بن سعیدبن سلطان بقتل رسید. (از الاعلام زرکلی از تحفةالاعیان ج <span class=\"hlight\" dir=\"rtl\">٢</span> و عمان و الساحل الجنوبی للخلیج الفارسی ص <span class=\"hlight\" dir=\"rtl\">٣٨</span>).<br></font></div>'),
(182957, 'عزان', '<span class=\"hlight\">عزان .</span> <font color=\"DarkGreen\"><b>[ ع َزْ زا ]</font></b> (اِخ ) ابن تمیم خروصی ازدی . از پیشوایان اباضیه در عمان بود. بسال <span class=\"hlight\" dir=\"rtl\">٢٧٧</span> هَ .ق . پس از خلع شدن راشدبن نضر، در نزوی با وی بیعت شد. در ایام حکومت پیوسته با فتنه ها و حوادث دست بگریبان بود و سرانجام به سال <span class=\"hlight\" dir=\"rtl\">٢٨٠</span> هَ .ق . به دست محمدبن بور، عامل معتضد عباسی در بحرین، بقتل رسید و سر او به بغداد فرستاده شد. (از الاعلام زرکلی از تحفةالاعیان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٣</span>).<br></font></div>'),
(182958, 'عزان', '<span class=\"hlight\">عزان .</span> <font color=\"DarkGreen\"><b>[ ع َزْ زا ]</font></b> (اِخ ) از قلاع ریمة است در یمن . (از معجم البلدان ).<br></font></div>'),
(182959, 'عزان', '<span class=\"hlight\">عزان .</span><font color=\"DarkGreen\"><b>[ ع َزْ زا ]</font></b> (اِخ ) قلعه ای است بر فرات . (منتهی الارب ). شهری است بر رود فرات ازآن ِ زباء، و خواهر او شهری در مقابل آن داشت بنام عدان . (از معجم البلدان ).<br></font></div>'),
(182960, 'عزان خبت', '<span class=\"hlight\">عزان خبت .</span> <font color=\"DarkGreen\"><b>[ ع َزْ زا ن ُ خ َ ]</font></b> (اِخ ) از قلعه های تعز است در کوه صَبِر در یمن . (از معجم البلدان ).<br></font></div>'),
(182961, 'عزان ذخر', '<span class=\"hlight\">عزان ذخر.</span> <font color=\"DarkGreen\"><b>[ ع َزْ زا ذَ خ ِ ]</font></b> (اِخ ) از قلعه های تعز است در کوه صَبِر در یمن . (از معجم البلدان ).<br></font></div>'),
(182962, 'عزاه', '<span class=\"hlight\">عزاه .</span> <font color=\"DarkGreen\"><b>[ ع َ هِن ْ ]</font></b> (ع ص، اِ) عَزاهی . رجوع به عزاهی شود.<br></font></div>'),
(182963, 'عزاهل', '<span class=\"hlight\">عزاهل .</span> <font color=\"DarkGreen\"><b>[ ع ُ هَِ ]</font></b> (ع ص ) به معنی عُراهل است . (از منتهی الارب ). اسب خوش ترکیب و زیبا. (ناظم الاطباء). و رجوع به عراهل شود. <BR><font color=\"Blue\">◄</font> (اِخ ) نام موضعی است . (از منتهی الارب ).<br></font></div>'),
(182964, 'عزاهی', '<span class=\"hlight\">عزاهی .</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ هی ی ]</font></b> (ع ص، اِ) عزاه . عِزهون . ج ِ عزه <font color=\"DarkGreen\"><b>[ ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ زِ ]</font></b> و عزهی <font color=\"DarkGreen\"><b>[ ع ِ ها <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ هی ی ]</font></b> و عزهاء و عزهاة و عِنزهو و عِنزَهوة و عُنْزُهانی . (اقرب الموارد). رجوع به هر یک از لغات فوق شود.<br></font></div>'),
(182965, 'عزاهیل', '<span class=\"hlight\">عزاهیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عُزهول . (منتهی الارب ) (اقرب الموارد). رجوع به عزهول شود. <BR><font color=\"Blue\">◄</font> به معنی عَراهیل است . (از منتهی الارب ). رجوع به عراهیل شود.<br></font></div>'),
(182966, 'عزاپرستی', '<span class=\"hlight\">عزاپرستی .</span> <font color=\"DarkGreen\"><b>[ ع َ پ َ رَ ]</font></b> (حامص مرکب ) به معنی عزاداری . (آنندراج ). سوکواری و زاری و اندوه و غصه و غم . (ناظم الاطباء). و رجوع به عزا شود.<br></font></div>'),
(182967, 'عزب', '<span class=\"hlight\">عزب .</span><font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (ع ص ) مرد بی زن، و آن به سبب انفراد و تنهایی اوست . و زن بی شوی . (از منتهی الارب ). آنکه او راخانواده و اهل نباشد، از مردان و از زنان . و گویند عزب، مرد بی خانواده و اهل است و عزبة زن بی شوی . (ازاقرب الموارد). جمع آن در مذکر عُزّاب به اعتبار اصل آن که عازب است، و أعزاب به اعتبار لفظ آن . (از اقرب الموارد) (از منتهی الارب ). در تداول فارسی زبانان، مرد بی زن . (دهار). مرد ناکدخدا و مجرد و آنکه زن اختیار نکرده باشد. (ناظم الاطباء). مجرد <span class=\"hlight\">:</span> <br>نه یکی و نه دو و نه سه و هشتاد و دویست <br>هرگز این دخت بسودن نتواند عزبی .<br> <font color=\"Red\">منوچهری .</font><br>ای پسر گیتی زنی رعناست بس غرچه فریب <br>فتنه سازد خویشتن را چون به دست آرد عزب .<br> <font color=\"Red\">ناصرخسرو.</font><br>فارغ از آبستنی روز و شب <br>نامیه عنین و طبیعت عزب .<br> <font color=\"Red\">نظامی .</font><br>من گُرْسنه در برابرم سفره ٔ نان <br>همچون عزبم بر در حمام زنان .<br> <font color=\"Red\">سعدی .</font><br>عزب را نکوهش کند خرده بین <br>که میرنجد از خفت وخیزش زمین .<br> <font color=\"Red\">سعدی .</font><br>نسبتی سخت قریب است خدا خیر کناد<br>دختر رز عزب است و پسر حرص عزب .<br> <font color=\"Red\">درویش واله هروی (از آنندراج ).</font><br>تعزب ؛ عزب شدن . (تاج المصادر بیهقی ) (المصادر زوزنی ). تأبد؛ عزب بنشستن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> محاسب و مستوفی درجه ٔ سیُم که از او زیردست تر نباشد. (از یادداشت مرحوم دهخدا). و رجوع به عزب باشی و عزب دفتر و عزب نویس شود.<br></font></div>'),
(182968, 'عزب', '<span class=\"hlight\">عزب .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (ع مص ) غایب شدن شوی زن در ایام طهر. (از منتهی الارب ): عزب طهر المراءة؛ همسر آن زن از وی غایب شد. (از اقرب الموارد). عُزوب . رجوع به عزوب شود. <BR><font color=\"Blue\">◄</font> خالی و ویران گردیدن زمین . (از منتهی الارب ): عزبت الارض ؛ آن سرزمین خالی از سکنه شد، خواه حاصلخیز باشد و خواه بی حاصل و خشک . (از اقرب الموارد). عُزوب . رجوع به عزوب شود.<br></font></div>'),
(182969, 'عزب باشی', '<span class=\"hlight\">عزب باشی .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (اِ مرکب ) رئیس محاسبان و منشیان <span class=\"hlight\">:</span> وی <font color=\"DarkGreen\"><b>[ عزب باشی ]</font></b> ریش سفید عزبان و فراشان دفتر است، و دفاتر که در خارج انبار است به تحویل او، و اگر دفاتر مفقود گردد بازخواست آن از مشارالیه میشده . و به دستور دفتر از ارقام و احکام بخط او میرسید. (تذکرةالملوک چ دبیرسیاقی ص <span class=\"hlight\" dir=\"rtl\">٤٣</span>).<br></font></div>'),
(182970, 'عزب خانه', '<span class=\"hlight\">عزب خانه .</span> <font color=\"DarkGreen\"><b>[ ع َزَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) جایی که مردان مجرد گرد آیند و با زنان بطور مشروع یا نامشروع مباشرت کنند. (فرهنگ فارسی معین ). خانه ٔ نهانی که جوانان زن ناکرده دارند عیش های نهانی را. خلوت خانه ٔ پسران مجرد. خانه ٔ بی اغیار عزبی را. (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> <br>با ثنای تو عقد بسته بهم <br>در عزب خانه عیسی مریم .<br> <font color=\"Red\">سنائی .</font><br>نفس نباتی ار به عزب خانه بازشد<br>عیبش مکن که مادر بستان سترون است .<br> <font color=\"Red\">انوری .</font><br>باد ازو ناردانه کرده جدا<br>چون عزب خانه های زنبور است .<br><font color=\"Red\">؟ (از تاج المآثر).</font><br>برسم جوانان نوخاسته <br>عزب خانه و خلوت آراسته .<br><font color=\"Red\">نزاری قهستانی .</font><br></font></div>'),
(182971, 'عزب دفتر', '<span class=\"hlight\">عزب دفتر.</span> <font color=\"DarkGreen\"><b>[ ع َ زَ دَ ف َ ]</font></b> (اِ مرکب ) محرر و نویسنده ٔ دفتر، و آنکه در دفتر محاسبات شغل مخصوصی ندارد. (ناظم الاطباء). کلمه ٔ عزب در اینجا اصلش همان کلمه ٔ عربی است که به ترکی عثمانی رفته و بمعنی تازه کار و شاگرد و شبیه آن بکار برده اند در نظام، و سپس درفارسی از ترکی گرفته شده و در معنی محاسب و مستوفی درجه ٔ سوم که از آن زیردست تر نیست بکار رفته است . ماده ای از قانون سلطان سلیم عثمانی این است : عزبلو توفنک اتمن علمنده کامل و ماهر اولوپ اغالیری دائم امتحان ایدوب توفنک اتمن بیلمینلره ادمان ایتوره لر . (یادداشت بخط مرحوم دهخدا).<br></font></div>'),
(182972, 'عزب نویس', '<span class=\"hlight\">عزب نویس .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ن ِ ]</font></b> (نف مرکب ) دفترنویس و کسی که نام عزبان را نویسد. و رجوع به عزب شود. <BR><font color=\"Blue\">◄</font> محاسب .<br></font></div>'),
(182973, 'عزب پیشه', '<span class=\"hlight\">عزب پیشه .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص مرکب ) کسی که همواره عزب می گردد و زن اختیار نمی کند. (ناظم الاطباء) <span class=\"hlight\">:</span> <br>سپاهی عزب پیشه و تنگ یاب <br>چو دیدند روئی چنان بی نقاب .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(182974, 'عزبة', '<span class=\"hlight\">عزبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع مص ) بی خانواده و اهل شدن . (از اقرب الموارد). عُزوبة.رجوع به عزوبة شود. <BR><font color=\"Blue\">◄</font> (اِمص ) بی زنی و بی شوئی . (منتهی الارب ). اسم است عزب بودن را. (از اقرب الموارد). عزبت . عزوبة. رجوع به عزبت و عزوبة شود.<br></font></div>'),
(182975, 'عزبة', '<span class=\"hlight\">عزبة.</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ب َ ]</font></b> (ع ص ) زن بی شوی . (آنندراج ) (ناظم الاطباء) (از اقرب الموارد). و رجوع به عَزَب شود. ج، عُزّاب . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> زن دوشیزه . (ناظم الاطباء).<br></font></div>'),
(182976, 'عزبت', '<span class=\"hlight\">عزبت .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع اِمص ) عزبة. بی زنی و بی شوئی . رجوع به عزبة شود.<br></font></div>'),
(182977, 'عزبی', '<span class=\"hlight\">عزبی .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (حامص ) عزب بودن و مجرد بودن . (فرهنگ فارسی معین ).<br></font></div>'),
(182978, 'عزت', '<span class=\"hlight\">عزت .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زَ ]</font></b> (ع اِمص ) عظمت و بزرگواری و ارجمندی و ارج و سرافرازی . (ناظم الاطباء). ارجمندی . (المصادر زوزنی ). کرامت . (زمخشری ). بزرگی . عزة.رجوع به عزة شود <span class=\"hlight\">:</span> عزت این خاندان بزرگ سلطان محمود را نگاه باید کرد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٩٢</span>).<br>آن را که چاربالش عزت میسر است <br>گو پنج نوبه زن که شه هفت کشور است .<br> <font color=\"Red\">اخسیکتی .</font><br>ستاره گفت منم پیک عزت از در او<br>از آن بمشرق و مغرب همیشه سیارم .<br> <font color=\"Red\">خاقانی .</font><br>وحدت من داده ز دولت خبر<br>عزلت من کرده بعزت ضمان .<br> <font color=\"Red\">خاقانی .</font><br>از سراین کلاه عزت رفت <br>«سر دریغا» کلاه میگوید.<br> <font color=\"Red\">خاقانی .</font><br>امیر نصر عزت و مکنت را به وراثت از پدر بزرگوار دریافت . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٤٧</span>). بناء عزت منقوض و لواء مجدت مخفوض . (ترجمه ٔتاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٤٤</span>). شخص عزت و غلا زیر قرضه ٔ وحشت وبلا یگانه و تنها فروشد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٥٢</span>).<br>خداوندا بدان تشریف و عزت <br>که دادی انبیا و اولیا را.<br> <font color=\"Red\">سعدی .</font><br>شاهد آنجا که رود حرمت و عزت بیند.<br> <font color=\"Red\">سعدی .</font><br>گفتا به عزت عظیم و صحبت قدیم دم برنیارم . (سعدی ).<br>عزت اندر عزلت آمد ای فلان <br>تو چه جوئی زاختلاط این و آن .<br> <font color=\"Red\">شیخ بهائی .</font><br>گر تو خواهی عزت دنیا و دین <br>عزلتی از مردم دنیا گزین .<br> <font color=\"Red\">شیخ بهائی .</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عزت ز قناعت است و خواری ز طمع</span> <br>با عزت خود بساز و خواری مطلب .<br> <font color=\"Red\">؟ (از جامع التمثیل ).</font><br> <span class=\"hlight\">عزت هر کس به دست آن کس است </span> .<br> <font color=\"Red\">؟ (از امثال و حکم دهخدا).</font><br>- <span class=\"hlight\">بی عزتی </span> ؛ بی اعتباری . نامعززی .<br>- <BR><font color=\"Blue\">◄</font> بی احترامی <span class=\"hlight\">:</span> <br>چو بی عزتی پیشه کرد آن حرون <br>شدند آن عزیزان خراب اندرون .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">بی عزتی نمودن </span> ؛ بی احترامی کردن . نگاه نداشتن عزت کسی <span class=\"hlight\">:</span> ملوک آنطرف قدر چنان بزرگوار ندانسته و بی عزتی نمودند. (گلستان ).<br>- <span class=\"hlight\">عزت آثار</span> ؛ صاحب علامات افتخار و شرف . (ناظم الاطباء).<br>- <span class=\"hlight\">عزت تپان کردن، عزت چپان کردن </span> ؛ به مزاح، بسیار اعزاز و اکرام کردن . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">عزت خواه </span> ؛ دوست و رفیق و مصاحب . (ناظم الاطباء).<br>- <BR><font color=\"Blue\">◄</font> پیرو و بسته به جلال دیگری . (ناظم الاطباء).<br>- <span class=\"hlight\">عزت طلب </span> ؛ آنکه خواهان ارج و قدر است . جاه طلب . مقام دوست . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عزت طلبی </span> ؛ حالت و کیفیت عزت طلب . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عزت قرار</span> ؛ مشهور و باجلال، و آن را غالباً در القاب شاهان بکار برند. (از ناظم الاطباء).<br>- <span class=\"hlight\">عزت موفور</span> ؛ مجلل و باجلال و محترم . (ناظم الاطباء).<br>- <span class=\"hlight\">عزت نشان </span> ؛ با آثار بزرگواری و بزرگی : عالیشان عزت نشان .<br>- <span class=\"hlight\">عزت نفس </span> ؛ مناعت . شرافت . (فرهنگ فارسی معین ). استکبار. مناعت طبع. عالیجنابی <span class=\"hlight\">:</span> و فایده در تعلم حرمت ذات و عزت نفس است . (کلیله و دمنه ).<br>در قناعت که تو را دست رس است <br>گر همه عزت نفس است بس است .<br> <font color=\"Red\">جامی .</font><br>گر تو خواهی عزت نفس ای فلان <br>رو نهان شو چون پری از مردمان .<br> <font color=\"Red\">شیخ بهائی .</font><br>- <span class=\"hlight\">عزت و اعتبار داشتن </span> ؛ به اصطلاح فارسیان، پشم در کلاه داشتن، بدین قیاس پشم در کلاهش نیست و پشم در کلاه ندارد نیز کنایه از آن است که بغایت مفلس و بی نواست . وقع نهادن و وقر نهادن . پیش کسی ریش داشتن . (آنندراج از مجموعه ٔ مترادفات ).<br>- <span class=\"hlight\">عزت همراه </span> ؛ که ملازم عزت باشد. خداوند عزت : عالیجاه عزت همراه .<br> <BR><font color=\"Blue\">◄</font> کمیابی . (ناظم الاطباء). بی همتائی . (مهذب الاسماء). دیریابی . دشواریابی . ندرت . شذوذ. <BR><font color=\"Blue\">◄</font> حمیت جاهلیت . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> (اِخ ) از نامهای باری تعالی <span class=\"hlight\">:</span> پیوسته در رعایت بندگان حضرت عزت عز شأنه ناقص الغایه سعی فرموده اند. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٧٤</span>).<br>ثنای حضرت عزت نمیتوانم گفت <br>که ره نمیبرد آنجا قیاس و وهم و خیال .<br> <font color=\"Red\">سعدی .</font><br>از حضرت عزت جلت قدرته درخواهیم . (انیس الطالبین ص <span class=\"hlight\" dir=\"rtl\">١١٨</span>).<br></font></div>'),
(182979, 'عزت آباد', '<span class=\"hlight\">عزت آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زَ ]</font></b> (اِخ ) دهی از دهستان مغان بخش گرمی شهرستان اردبیل . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١١٧</span> تن . آب آن از چشمه . محصول آن غلات و حبوب است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(182980, 'عزت آباد', '<span class=\"hlight\">عزت آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زَ ]</font></b> (اِخ ) دهی از دهستان کشکوئیه ٔ شهرستان رفسنجان . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٦٠٠</span> تن . آب آن از دو رشته قنات . محصول آن غلات، لبنیات، پسته، پنبه و صیفی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(182981, 'عزت آباد', '<span class=\"hlight\">عزت آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زَ ]</font></b> (اِخ ) دهی از دهستان دابو از بخش مرکزی شهرستان آمل . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١١٠</span>تن . آب آن از رودخانه ٔ هراز. محصول آن برنج، کنف، نی شکر و صیفی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(182982, 'عزت آباد', '<span class=\"hlight\">عزت آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زَ ]</font></b> (اِخ ) دهی جزء دهستان کزاز پائین بخش سربند شهرستان اراک . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٠٠</span>تن . آب آن از چشمه ٔ محلی و رودخانه ٔ طوره . محصول آن غلات و چغندرقند و انگور است . نام قدیمی این آبادی پنجه علی بوده است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(182983, 'عزت العابد', '<span class=\"hlight\">عزت العابد.</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زَ تُل ْ ب ِ ]</font></b> (اِخ ) احمد عزت بن محیی الدین ابوالهول (مسمی به هولوپاشا) ابن عمربن عبدالقادر عابد (<span class=\"hlight\" dir=\"rtl\">١٢٧٢</span> - <span class=\"hlight\" dir=\"rtl\">١٣٤٣</span> هَ .ق .). از سیاستمداران مشهور دولت عثمانی بود. پس از فراغ از تحصیل روزنامه ای به زبان عربی و ترکی بنام دمشق منتشر ساخت .سپس به اسلامبول سفر کرد و از ملازمان سلطان عبدالحمید ثانی گشت، و با اتخاذ سیاستی خاص مانع اتحاد دول اروپا بر ضد دولت عثمانی شد. وی در تأسیس خط آهن حجاز سهم بسزائی داشت . پس از انقلاب سال <span class=\"hlight\" dir=\"rtl\">١٣٢٦</span> هَ .ق . به لندن رفت . سپس در مصر سکونت اختیار کرد و در آنجا درگذشت . (از الاعلام زرکلی از تاریخ الصحافة العربیة).<br></font></div>'),
(182984, 'عزت الفاروقی', '<span class=\"hlight\">عزت الفاروقی .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زَ تُل ْ ]</font></b> (اِخ ) احمد عزت بن محمود فاروقی عمری . (<span class=\"hlight\" dir=\"rtl\">١٢٤٤</span>-<span class=\"hlight\" dir=\"rtl\">١٣١٠</span> هَ .ق .). شاعر و از اهالی موصل بود. وی به اسلامبول رفت و برخی از مناصب دولتی را عهده دار گشت . او راست : العقود الجوهریة، رحلة الی النجد، أحکام الاراضی دیوان شعر. (از الاعلام زرکلی از تاریخ الموصل ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٢</span>).<br></font></div>'),
(182985, 'عزت جستن', '<span class=\"hlight\">عزت جستن .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زَ ج ُ ت َ ]</font></b> (مص مرکب ) جستجوی ارجمندی . سرافرازی خواستن . (فرهنگ فارسی معین ).<br></font></div>'),
(182986, 'عزت ملک', '<span class=\"hlight\">عزت ملک .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زَ م َل ِ ]</font></b> (اِخ ) وی همسر امیر شیخ حسن چوپانی (کوچک ) و اصلاً رومی بود. او را با امیر یعقوب شاه روابط عاشقانه بود، و به سال <span class=\"hlight\" dir=\"rtl\">٧٤٤</span> هَ .ق . امیر شیخ حسن قشونی به سرکردگی سلیمان خان و امیر یعقوب شاه از امرای روم به تسخیر آن بلاد فرستاد و ایشان شکست خورده برگشتند. امیر شیخ حسن که امیر یعقوب شاه را در این شکست مسؤول میشمرد او را گرفت و محبوس ساخت . عزت ملک به توهم اینکه شوهرش بمناسبت اطلاع از روابط عاشقانه ٔ آن دو، وی را محبوس کرده است با دو سه تن از زنان خدمتکار همدست شد و در شب سه شنبه <span class=\"hlight\" dir=\"rtl\">٢٧</span> رجب سال <span class=\"hlight\" dir=\"rtl\">٧٤٤</span> امیر شیخ حسن را بطرز فجیعی کشتند. و پس از دو روز چون امرا و درباریان از این واقعه آگاه شدند عزت ملک را با خواری تمام و بطرزی فجیع بقتل رساندند. (از تاریخ عصر حافظ ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>). و رجوع به تاریخ مغول عباس اقبال ص <span class=\"hlight\" dir=\"rtl\">٣٦٢</span> و رجال حبیب السیر ص <span class=\"hlight\" dir=\"rtl\">٣٣</span> و تاریخ ادوارد براون ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨</span> شود.<br></font></div>'),
(182987, 'عزت یافتن', '<span class=\"hlight\">عزت یافتن .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زَ ت َ ]</font></b> (مص مرکب ) ارجمند شدن . عزیز گشتن . دارای قدر و ارزش شدن . حرمت و اعتبار یافتن <span class=\"hlight\">:</span> <br>عزیزی که هر کز درش سر بتافت <br>به هر در که شد هیچ عزت نیافت .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(182988, 'عزتمند', '<span class=\"hlight\">عزتمند.</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زَ م َ ]</font></b> (ص مرکب ) آنکه دارای عزت است . (فرهنگ فارسی معین ). ارجمند. بزرگ . بزرگوار.<br></font></div>'),
(182989, 'عزتمندی', '<span class=\"hlight\">عزتمندی .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ زَ م َ ]</font></b> (حامص مرکب ) حالت و کیفیت عزتمند. (فرهنگ فارسی معین ). ارجمندی . بزرگواری . رجوع به عزتمند شود.<br></font></div>'),
(182990, 'عزج', '<span class=\"hlight\">عزج .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) دور کردن . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گائیدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> به بیل برگردانیدن زمین را. (منتهی الارب ): عزج الارض بالمسحاة؛ زمین را با بیل زیرورو کرد. (از اقرب الموارد).<br></font></div>'),
(182991, 'عزد', '<span class=\"hlight\">عزد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) آرمیدن با زن . (از منتهی الارب ). نزدیکی با زن .<br></font></div>'),
(182992, 'عزر', '<span class=\"hlight\">عزر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(ع اِ) بهای گیاه، هرگاه دروده علفزار فروخته شود. (منتهی الارب ). قیمت علف، هرگاه درو شود و مزارع آن فروخته گردد. (از اقرب الموارد). بهای علفزار، هرگاه علف مزارع آن را بدروند و بفروشند. (ناظم الاطباء).<br></font></div>'),
(182993, 'عزر', '<span class=\"hlight\">عزر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) نکوهیدن . (منتهی الارب ). ملامت کردن .(از اقرب الموارد). <BR><font color=\"Blue\">◄</font> یاری نمودن . (منتهی الارب ). کمک کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بازداشتن . (منتهی الارب ). منع کردن و رد کردن . (از اقرب الموارد). رد و منع. (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> گائیدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> به ستم بر کاری داشتن . (منتهی الارب ). مجبور کردن بر کاری . (از تاج العروس ).  <BR><font color=\"Blue\">◄</font> آگاه گردانیدن بر باب دین و فرائض و احکام . (منتهی الارب ): عزر الرجل علی الفرائض و الاحکام ؛ آن شخص را بر فرائض و احکام واقف کرد. (از اقرب الموارد).<br></font></div>'),
(182994, 'عزرا', '<span class=\"hlight\">عزرا.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) (لغت عبری است بمعنی یاری و امداد). و آن نام کاهن و رهبرعبرانیان و کاتب دینی یهود در قرن پنجم ق .م . است که در دربار ایران صاحب جاه و مقام بود. وی معاصر اردشیر درازدست هخامنشی بود. وی در سال <span class=\"hlight\" dir=\"rtl\">٤٥٧</span> ق .م . به سرکردگی و پیشوایی عده ٔ بسیاری از اسیران یهود که از بابل به اورشلیم بازمیگشتند (در حدود <span class=\"hlight\" dir=\"rtl\">١٧٧٥</span> تن ) برگزیده شد و در اورشلیم به اصلاح دین و تلاوت متون مقدس اشتغال داشت و همچنین به نوشتن تاریخ و کتاب معروف « عزرا» و قسمتی از «نحمیا» سرگرم بود. گویند همه ٔ کتب عهدعتیق را وی جمعآوری و تدوین کرده است . عزرا در نویسندگی مهارت داشت و در آیین یهود اصلاحاتی کرده و کنیسه هایی تأسیس نموده است . و مسلمانان او را بنام عُزَیر خوانند و از انبیای بنی اسرائیل شمارند. (فرهنگ فارسی معین ). و رجوع به قاموس کتاب مقدس و عزیر شود.<br></font></div>'),
(182995, 'عزرار', '<span class=\"hlight\">عزرار.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) از اعلام است . (منتهی الارب ).<br></font></div>'),
(182996, 'عزری', '<span class=\"hlight\">عزری .</span> <font color=\"DarkGreen\"><b>[ع َ ری ی ]</font></b> (ص نسبی ) منسوب به باب عزرة که محله ای بزرگ است در نیشابور. و چند تن از فاضلان بدان منسوبند. (از اللباب فی تهذیب الانساب ). و رجوع به عزرة شود.<br></font></div>'),
(182997, 'عزری', '<span class=\"hlight\">عزری .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام او ابراهیم بن حسن و مکنی به ابواسحاق . فقیه حنفی و محدث قرن چهارم هجری است . وی بسال <span class=\"hlight\" dir=\"rtl\">٣٤٧</span> هَ .ق . درگذشته است . (از اللباب فی تهذیب الانساب ) (معجم البلدان ).<br></font></div>'),
(182998, 'عزریا', '<span class=\"hlight\">عزریا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) عزریاهو (کسی که خداوند او را کمک میفرماید). وی نوه ٔ صادوق کاهن است که در ایام سلیمان کاهن اعظم بود. و بیست ودو تن دیگر بهمین نام در کتاب مقدس ذکر شده اند. (از قاموس کتاب مقدس ).<br></font></div>'),
(182999, 'عزز', '<span class=\"hlight\">عزز.</span> <font color=\"DarkGreen\"><b>[ ع ُ زُ ]</font></b> (ع ص، اِ) ج ِ عَزوز. (منتهی الارب ) (اقرب الموارد). رجوع به عزوز شود.<br></font></div>'),
(183000, 'عزط', '<span class=\"hlight\">عزط.</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (ع مص ) نکاح و گائیدن . (منتهی الارب ) (آنندراج ).<br></font></div>'),
(183001, 'عزعز', '<span class=\"hlight\">عزعز.</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ]</font></b> (ع اِ صوت ) زجر است مر بز را. (منتهی الارب ). اسم است که بزان را بدان زجر کنند. (از اقرب الموارد).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(183002, 'عزف', '<span class=\"hlight\">عزف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) پائیدن بر اکل و شرب . (از منتهی الارب ). ادامه دادن به خوردن و آشامیدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> جهیدن نای گلوی شتر وقت مرگ . (از منتهی الارب ): عزف البعیر؛ حنجره ٔشتر هنگام مردن جهید. <BR><font color=\"Blue\">◄</font> زهد پیشه کردن نفس از چیزی و منصرف شدن از آن، و یا روی گردان شدن ازچیزی . (از اقرب الموارد). عُزوف . رجوع به عزوف شود. <BR><font color=\"Blue\">◄</font> آواز دادن قوس و کمان . (از اقرب الموارد). عَزیف . رجوع به عزیف شود. <BR><font color=\"Blue\">◄</font> طنبور زدن و جز آن . (تاج المصادر بیهقی ) (المصادر زوزنی ).<br></font></div>'),
(183003, 'عزف', '<span class=\"hlight\">عزف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) آواز پری، و آن جرسی است که شبانه در صحراها شنیده میشود. (از منتهی الارب ). صوت جن . (اقرب الموارد).<br>- <span class=\"hlight\">عزف الریاح </span> ؛ آوازهای باد. (منتهی الارب ) (از اقرب الموارد).<br><BR><font color=\"Blue\">◄</font> بازی و لعب . (منتهی الارب ).<br></font></div>'),
(183004, 'عزف', '<span class=\"hlight\">عزف .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) آبی است ازآن ِ بنی نصربن معاویه، که بین آن و شَعفَین مسافت چهار میل است . (از معجم البلدان ).<br></font></div>'),
(183005, 'عزف', '<span class=\"hlight\">عزف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) کبوتر طورانی . (منتهی الارب ). حمام و کبوتر طورانی، یعنی وحشی . (از اقرب الموارد).<br></font></div>'),
(183006, 'عزفی', '<span class=\"hlight\">عزفی .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (اِخ ) محمدبن یحیی بن عبداﷲبن ابی القاسم عزفی . امیر سبتة در اندلس . به سال <span class=\"hlight\" dir=\"rtl\">٦٩٩</span> هَ .ق . در سبتة متولد شد و در سال <span class=\"hlight\" dir=\"rtl\">٧١٩</span> به امارت آنجا رسید و پس از شش ماه از حکومت خلع گشت و به فاس رفت و در سال <span class=\"hlight\" dir=\"rtl\">٧٦٨</span> درگذشت . وی مردی فقیه و شاعر بود و او آخرین تن از بنی عزی است که بر سبتة حکومت کردند. (از الاعلام زرکلی از ازهار الریاض و جذوة الاقتباس ).<br></font></div>'),
(183007, 'عزفی', '<span class=\"hlight\">عزفی .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (اِخ ) یحیی بن عبداﷲبن محمدبن احمدبن محمد لخمی عزفی، مکنی به ابوعمر. از امیران سبتة بود و به سال <span class=\"hlight\" dir=\"rtl\">٦٧٧</span> هَ .ق . متولد شد و در سال <span class=\"hlight\" dir=\"rtl\">٧١٠</span> با او بیعت شد و بسال <span class=\"hlight\" dir=\"rtl\">٧١٩</span> درگذشت .عزفی مردی فقیه و فاضل و شجاع بود و خطی خوش داشت . (از الاعلام زرکلی از ازهارالریاض و الدرر الکامنة).<br></font></div>'),
(183008, 'عزفی', '<span class=\"hlight\">عزفی .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (اِخ ) محمدبن احمدبن محمدبن حسین عزفی، مکنی به ابوالقاسم، از نسل ابن ابی عزفه ٔ لخمی . نخستین کس از بنی ابی عزفة است که به امارت سبتة رسید. او بر طنجه و اصیلا نیز حکمرانی کرد و مدت حکومت وی سی سال و دو ماه و شانزده روز بطول انجامید و به سال <span class=\"hlight\" dir=\"rtl\">٦٧٧</span> هَ .ق . در سبتة درگذشت (مولدش بسال <span class=\"hlight\" dir=\"rtl\">٦٠٧</span>بوده است ). عزفی مردی فقیه و فاضل بود و در نظم نیزدست داشت و کتاب «الدر المنظوم فی مولد النبی المعظم » را که از تألیفات پدرش ابوالعباس احمد است تکمیل کرده است . (از الاعلام زرکلی از ازهار الریاض ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(183009, 'عزفی', '<span class=\"hlight\">عزفی .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (اِخ ) عبدالرحمان بن عبداﷲبن محمدبن احمد لخمی، مکنی به ابوالقاسم (<span class=\"hlight\" dir=\"rtl\">٦٨٥</span>-<span class=\"hlight\" dir=\"rtl\">٧٧٠</span> هَ .ق .). از محدثان و فاضلان مغرب، و اصل او از سبتة بود و در فاس در گذشت . او راست : الاشادة بذکر المشتهرین من المتأخرین بالافادة، که کتابی است در تراجم .(از الاعلام زرکلی از ازهار الریاض و جذوةالاقتباس ).<br></font></div>'),
(183010, 'عزفی', '<span class=\"hlight\">عزفی .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (اِخ )عبداﷲبن محمدبن احمد عزفی، مکنی به ابوطالب (<span class=\"hlight\" dir=\"rtl\">٦٣٨</span>-<span class=\"hlight\" dir=\"rtl\">٧١٣</span> هَ .ق .). وی بسال <span class=\"hlight\" dir=\"rtl\">٦٧٨</span> هَ .ق . به ولایت سبتة رسید و مدت <span class=\"hlight\" dir=\"rtl\">٢٧</span> سال در آنجا حکمرانی کرد و سرانجام بسال <span class=\"hlight\" dir=\"rtl\">٧٠٥</span> بوسیله ٔ امیر فرج بن اسماعیل از حکومت خلع گشت . او شخصی فقیه و حدیث دان بود و در علم تاریخ نیز دست داشت .(از الاعلام زرکلی از ازهار الریاض و جذوةالاقتباس ).<br></font></div>'),
(183011, 'عزق', '<span class=\"hlight\">عزق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) زمین شکافتن . (از منتهی الارب ): عزق الارض ؛ زمین را شکافت و آن را زیرورو کرد. و این فعل فقط برای زمین بکار میرود. (از اقرب الموارد). نعت آن أرض معزوقة باشد. <BR><font color=\"Blue\">◄</font> شتابی نمودن در دویدن . (از منتهی الارب ). سرعت کردن در دویدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بازداشتن، چنانکه گویند: عزق الخیر عنی ؛ یعنی بازداشت نیکوئی را از من . (از منتهی الارب ): عزق الخبر عنی ؛ خبر را از من بازداشت . (از اقرب الموارد) (از تاج العروس ). <BR><font color=\"Blue\">◄</font> مبالغه کردن در زدن . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183012, 'عزق', '<span class=\"hlight\">عزق .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (ع مص ) چَفسیدن به کسی و لازم گرفتن . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183013, 'عزق', '<span class=\"hlight\">عزق .</span><font color=\"DarkGreen\"><b>[ ع َ زِ ]</font></b> (ع ص ) دشوارخوی دون همت ناکس . (منتهی الارب ). سخت اخلاق و بدخوی . ج، عُزَق . (از اقرب الموارد).<br></font></div>'),
(183014, 'عزق', '<span class=\"hlight\">عزق .</span> <font color=\"DarkGreen\"><b>[ ع ُ زُ ]</font></b> (ع ص، اِ) به باد صاف کننده ٔ گندم . (منتهی الارب ). کسانی که گندم را با باد پاک میکنند. (ناظم الاطباء). به باد صاف کنندگان طعام . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بدخوی از مردم و شتر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ج ِ عَزِق . (اقرب الموارد). رجوع به عَزِق شود.<br></font></div>'),
(183015, 'عزل', '<span class=\"hlight\">عزل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) آنچه پیشکی در بیت المال درآید بی وزن و بی انتقاد تا وقت اداء. (منتهی الارب ).آنچه پیشکی در بیت المال وارد شود در صورتی که غیرموزون و غیرمنتقد باشد. (ناظم الاطباء). آنچه وزن نشده وسره از ناسره جدانشده، قبل از موعد به بیت المال وارد شود تا وقت ادای دین فرارسد. (از اقرب الموارد).<br></font></div>'),
(183016, 'عزل', '<span class=\"hlight\">عزل .</span> <font color=\"DarkGreen\"><b>[ ع ُزْ زَ ]</font></b> (ع ص، اِ) ج ِ أعزل . (منتهی الارب ) (اقرب الموارد). رجوع به اعزل شود.<br></font></div>'),
(183017, 'عزل', '<span class=\"hlight\">عزل .</span> <font color=\"DarkGreen\"><b>[ ع ُ زُ ]</font></b> (ع ص ) مرد بی سلاح . (منتهی الارب ). آنکه سلاح با او نباشد. (از اقرب الموارد). ج، اَعزال . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(183018, 'عزل', '<span class=\"hlight\">عزل .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِمص ) ضعف . (اقرب الموارد). ضعف و سستی . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بیکاری . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بی سازی و بی سلاحی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص، اِ) ج ِ أعزل . (منتهی الارب ) (اقرب الموارد). رجوع به اعزل شود.<br></font></div>'),
(183019, 'عزل', '<span class=\"hlight\">عزل .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (ع اِمص ) بیکاری . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بی سازی و بی سلاحی (اسم مصدر است ). (منتهی الارب ). اسم است أعزل را که بمعنی کسی است که سلاح با وی نباشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) مؤخر خر: اقرع عزل حمارک ؛ یعنی بر مؤخر و قسمت عقب الاغ خود بزن . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183020, 'عزل', '<span class=\"hlight\">عزل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِمص ) بیکاری . (غیاث اللغات ). بیغی و بازداشت از کار و شغل و منصب . (از ناظم الاطباء). معزولی . پیاده کردن از عمل . برکناری از کار <span class=\"hlight\">:</span> <br>ستم نامه ٔ عزل شاهان بود<br>چو درد دل بیگناهان بود.<br> <font color=\"Red\">فردوسی .</font><br>خداوندا مرا معزول کردی <br>سرانجام همه عمال عزل است <br>به توقیع تو ایمن بودم از عزل <br>ندانستم که توقیع تو هزل است .<br> <font color=\"Red\">؟ (از ترجمان البلاغه ٔ رادویانی ).</font><br>در خدمت تونیز شکستم ندهد عزل <br>در دولت تو بیش گرانم نکند وام .<br> <font color=\"Red\">مسعودسعد.</font><br>بر قد همت قبای عزل بریدم <br>گرچه ببالای روزگاردراز است .<br> <font color=\"Red\">خاقانی .</font><br>چون عز عزل هست غم زور و زر مخور<br>چون فر فقر هست دم مال و مل مران .<br> <font color=\"Red\">خاقانی .</font><br>یک درم سیم بخویشتن فرانگرفت مگر به عزل و حبس .(ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٥٩</span>).<br>- <span class=\"hlight\">عزل و نصب </span> ؛ به معنی تغییر و بجایی (؟) است، و اینکه مردم بضم عین و فتح صاد خوانند خطا است . (از غیاث اللغات ) (از آنندراج ).<br>- <BR><font color=\"Blue\">◄</font> از کار برکنار ساختن و به کار گماشتن .<br> <BR><font color=\"Blue\">◄</font> (اصطلاح فقه ) بازداشتن آب منی را از زن و نخواستن که فرزند آرد.(منتهی الارب ). بازداشتن جماع کننده کنیز خود را از آب منی، یعنی نزدیک انزال خود را عقب کشیدن و در بیرون فرج انزال کردن و نخواستن که فرزند آورد. (از ناظم الاطباء). عزل کردن آب از زن . (المصادر زوزنی ) (از تاج المصادر بیهقی ). دور کردن آب از زن از بیم بارداری . (از تعریفات جرجانی ). در حدیث است که نهی النبی (ص ) عن العزل عن الحرة اًلا باذنها (منتهی الارب )؛ یعنی پیغمبر (ص ) عزل کردن زن آزاده را منع کرده است مگربا اذن و رضای خود زن . <BR><font color=\"Blue\">◄</font> نزد بعضی از بلغا، آن است که کلام بزبان نرسد، چون این بیت :<br>هان ای امام امین هان ای همام مهین <br>مائیم و آن مه ما با ما بیا و ببین .<br>و این از مخترَعات امیرخسرو دهلوی است . (از کشاف اصطلاحات الفنون ).<br></font></div>'),
(183021, 'عزل', '<span class=\"hlight\">عزل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) یکسو نمودن و جدا کردن و بیکار ساختن . (از منتهی الارب ). جدا کردن . (دهار). جدا کردن و معزول کردن . (المصادر زوزنی ) (تاج المصادر بیهقی ). بازداشتن چیزی را از غیر و یکسو نمودن و اخراج کردن . (از ناظم الاطباء). دور کردن چیزی را به کناری و جدا کردن آن . (از اقرب الموارد). از کار انداختن . بیکار کردن . معزول کردن . مقابل نصب . مقابل تولیت . پیاده کردن از عمل . از کار برکنار کردن .<br></font></div>'),
(183022, 'عزل', '<span class=\"hlight\">عزل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام ناحیه ای است، و آبی است بین بصره و یمامه، که در شعر امروءالقیس آمده است . (از معجم البلدان ).<br></font></div>'),
(183023, 'عزل شدن', '<span class=\"hlight\">عزل شدن .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ُ دَ ]</font></b> (مص مرکب ) معزول گشتن . جدا شدن . برکنار شدن از کار. پیاده شدن از عمل . از کار افتادن .<br></font></div>'),
(183024, 'عزل پذیر', '<span class=\"hlight\">عزل پذیر.</span> <font color=\"DarkGreen\"><b>[ ع َ پ َ ]</font></b> (نف مرکب ) عزل پذیرنده . قابل عزل شدن . شایسته ٔ برکناری . درخور عزل . <BR><font color=\"Blue\">◄</font> قبول برکناری کننده . که عزل و برکناری را بپذیرد <span class=\"hlight\">:</span> <br>تا بر این است ره و سیرت تو<br>نیست این دولت تو عزل پذیر.<br> <font color=\"Red\">سوزنی .</font><br>سپه آورد رُخَت، مورچه ٔ مشکین پر<br>تا تو از مملکت حسن شوی عزل پذیر.<br> <font color=\"Red\">سوزنی .</font><br>به وزارت نشسته خوشدل و شاد<br>وز امارت نگشته عزل پذیر.<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(183025, 'عزل کردن', '<span class=\"hlight\">عزل کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ دَ ]</font></b> (مص مرکب ) ازکار انداختن . معزول کردن . کسی را از شغل و منصب بازداشتن . (ناظم الاطباء). خلع کردن . (فرهنگ فارسی معین ). مقابل نصب کردن . از عمل پیاده کردن . ابطال کردن .<br></font></div>'),
(183026, 'عزل گشتن', '<span class=\"hlight\">عزل گشتن .</span> <font color=\"DarkGreen\"><b>[ ع َ گ َ ت َ ]</font></b> (مص مرکب ) معزول گشتن . عزل شدن . برکنار شدن از شغل . از عمل پیاده گشتن . از کار افتادن . از شغل به یک سو شدن <span class=\"hlight\">:</span> <br>مروت عزل گردیده ست در دیوان ناز او<br>عجب گر اینقدر بی مهری از صد بی وفا آید.<br><font color=\"Red\">ظهوری (از آنندراج ).</font><br></font></div>'),
(183027, 'عزلان', '<span class=\"hlight\">عزلان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ أعزل . (منتهی الارب ) (اقرب الموارد). رجوع به اعزل شود.<br></font></div>'),
(183028, 'عزلبة', '<span class=\"hlight\">عزلبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ب َ]</font></b> (ع مص ) نکاح و گائیدن . (منتهی الارب ) (آنندراج ).<br></font></div>'),
(183029, 'عزلة', '<span class=\"hlight\">عزلة.</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ل َ ]</font></b> (ع اِ) استخوان سر سرین که به زمین رسد. (منتهی الارب ). حَرقَفة و استخوان سر سرین . (اقرب الموارد). و رجوع به حرقفة شود. <BR><font color=\"Blue\">◄</font> (ص، اِ) ج ِ عازل . (اقرب الموارد). رجوع به عازل شود.<br></font></div>'),
(183030, 'عزلة', '<span class=\"hlight\">عزلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دهی است به یمن از اعمال بَحرانة. (منتهی الارب ). عزلة بحرانة؛ از قرای یمن است . (از معجم البلدان ).<br></font></div>'),
(183031, 'عزلة', '<span class=\"hlight\">عزلة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ]</font></b> (ع اِمص ) دوری و گوشه نشینی، و از آن جمله است حدیث <span class=\"hlight\">:</span> العزلة عبادة. (از منتهی الارب ). اسم است اعتزال را. (از اقرب الموارد). جدائی . (دهار). گوشه گرفتن ازبرای عبادت، و جدا شدن از زن و فرزند. (آنندراج ). خارج شدن از مخالطت و آمیزش با خلق بوسیله ٔ انزواء و انقطاع . (از تعریفات جرجانی ). عزلت . و رجوع به عزلت شود.<br></font></div>'),
(183032, 'عزلت', '<span class=\"hlight\">عزلت .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ]</font></b> (ع اِمص ) عزلة. گوشه نشینی و خانه نشینی . (ناظم الاطباء). جدا شدن از زن و فرزند و گوشه نشینی برای عبادت . (غیاث اللغات ). کناره گرفتن از خلق . انزوا.گوشه گیری . اعتزال . و رجوع به عزلة شود <span class=\"hlight\">:</span> <br>بود پرهیز تو پاکی و طاعت راز با ایزد<br>چو خلوت هست تنهائی و عزلت حضرت سلطان .<br> <font color=\"Red\">ناصرخسرو.</font><br>گر از زحمت همی ترسی ز نااهلان ببُر صحبت <br>که از دام زبون گیران به عزلت رسته شد عنقا.<br> <font color=\"Red\">سنائی .</font><br>کسی که عزت عزلت نیافت هیچ نیافت <br>کسی که روی قناعت ندید هیچ ندید.<br> <font color=\"Red\">سنائی .</font><br>دار عزلت گزید خاقانی <br>که به از دار ملک خاقان است .<br> <font color=\"Red\">خاقانی .</font><br>وحدت من داده ز دولت خبر<br>عزلت من کرده به عزت ضمان .<br> <font color=\"Red\">خاقانی .</font><br>دفتر آز از بر من برگرفت <br>مصحف عزلت عوض آن نهاد.<br><font color=\"Red\">خاقانی .</font><br>جملگی امور ملک به رأی او بقطع میرسیدی و وزارتی در پرده ٔ عزلت میراندی . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٦٤</span>).<br>چو مشک از ناف عزلت بو گرفتم <br>بتنهائی چو عنقا خو گرفتم .<br> <font color=\"Red\">نظامی .</font><br>تا درین زندان فانی زندگانی باشدت <br>کنج عزلت گیر تا گنج معانی باشدت .<br> <font color=\"Red\">عطار.</font><br>نیستت بر وفق من مهر و مهار<br>کرد باید از تو عزلت اختیار.<br> <font color=\"Red\">مولوی .</font><br>مصلحت آن دیدم که در نشیمن عزلت نشینم . (گلستان سعدی ). ترک صحبت گفتیم و طریق عزلت گرفتیم . (گلستان ).<br>سلاطین عزلت گدایان حی <br>منازل شناسان گم کرده پی .<br> <font color=\"Red\">سعدی .</font><br>کنج عزلت که طلسمات عجایب دارد<br>فتح آن در نظر رحمت درویشان است .<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عزت اندر عزلت آمد ای فلان </span> <br>تو چه جوئی زاختلاط این و آن .<br> <font color=\"Red\">شیخ بهائی (از امثال و حکم دهخدا).</font><br><BR><font color=\"Blue\">◄</font> در تصوف و عرفان، یکی از مراتب است . مشایخ طریقت عزلت و خلوت و انقطاع و انزوا را ازآن جهت اختیار کرده اند تا حواس ظاهر بسته شود و از اعمال خود معزول گردند که هر حجابی که به روح انسان رسد او را از مشاهده ٔ جمال مولی محجوب گرداند. و بواسطه ٔ عزلت امداد نفسانی کم شود و حجاب مرتفع گردد و به مقام شهود جمال او برسد، و سالک را قبل از وصول به مقام توحید که مقصود اصلی تمام عبادات و سلوک و ریاضات است، انواع حالات دست دهد. (فرهنگ مصطلحات عرفاءاز شرح گلشن راز ص <span class=\"hlight\" dir=\"rtl\">٦٢٩</span> و مقدمه ٔ نفحات الانس ص <span class=\"hlight\" dir=\"rtl\">١٢٠</span>).<br></font></div>'),
(183033, 'عزلت دوست', '<span class=\"hlight\">عزلت دوست .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ]</font></b> (ص مرکب ) آنکه عزلت و تنهائی و گوشه نشینی و خلوت را دوست میدارد. (ناظم الاطباء). خواهان گوشه گیری . گوشه خواه . <BR><font color=\"Blue\">◄</font> عابد و مرتاض . (آنندراج ). عزلت گزین . عزلت گزیده . و رجوع به عزلت گزین و عزلت گزیده شود.<br></font></div>'),
(183034, 'عزلت نشین', '<span class=\"hlight\">عزلت نشین .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َن ِ ]</font></b> (نف مرکب ) گوشه گیر. منزوی . معتزل <span class=\"hlight\">:</span> <br>به عزلت نشینان صحرای درد<br>به ناخن کبودان سرمای سرد.<br> <font color=\"Red\">نظامی .</font><br>گروهی عمل دار عزلت نشین <br>قدمهای خاکی دم آتشین .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(183035, 'عزلت کشیده', '<span class=\"hlight\">عزلت کشیده .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) که رنج عزلت تحمل کرده باشد. در گوشه گیری به سر برده <span class=\"hlight\">:</span> مردم سختی دیده و عزلت کشیده را خدمت فرماید. (مجالس سعدی ).<br></font></div>'),
(183036, 'عزلت گرفتن', '<span class=\"hlight\">عزلت گرفتن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َگ ِ رِ ت َ ]</font></b> (مص مرکب ) گوشه نشینی . کناره گرفتن . کناره گیری کردن . گوشه گیری کردن . گوشه گرفتن <span class=\"hlight\">:</span> خردمندان ... از جنگ عزلت گرفته اند. (کلیله و دمنه ).<br>مرا که عزلت عنقا گرفتمی همه عمر<br>چنان اسیر گرفتی که باز تیهو را.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(183037, 'عزلت گزیدن', '<span class=\"hlight\">عزلت گزیدن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ گ ُ دَ ]</font></b> (مص مرکب ) گوشه نشینی اختیار کردن . ترک مراوده با مردمان نمودن و به عبادت پروردگار مشغول شدن . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>چون شترمرغی ّ ما سیمرغ دید<br>لاجرم ازننگ ما عزلت گزید.<br> <font color=\"Red\">عطار.</font><br>بقیه ٔ عمر در گوشه ای نشینم و عزلت گزینم . (گلستان ).<br>به کنج غاری عزلت گزینم از همه خلق <br>گر آن لطیف جهان یار غار ما باشد.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(183038, 'عزلت گزیده', '<span class=\"hlight\">عزلت گزیده .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ گ ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) آنکه تنهائی و گوشه نشینی و خلوت را دوست میدارد. (ناظم الاطباء). عزلت دوست . عزلت گزین . و رجوع به عزلت دوست شود.<br></font></div>'),
(183039, 'عزلت گزین', '<span class=\"hlight\">عزلت گزین .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ گ ُ ]</font></b> (نف مرکب ) عزلت گزیننده . آنکه عزلت و تنهائی و گوشه نشینی و خلوت را دوست میدارد. (ناظم الاطباء). گوشه نشین . معتزل . منزوی . <BR><font color=\"Blue\">◄</font> عابد و مرتاض . (آنندراج ). عزلت دوست . و رجوع به عزلت دوست شود.<br></font></div>'),
(183040, 'عزلت گزینی', '<span class=\"hlight\">عزلت گزینی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ گ ُ ]</font></b> (حامص مرکب ) گوشه گیری و انزوا. (فرهنگ فارسی معین ).<br></font></div>'),
(183041, 'عزلتی', '<span class=\"hlight\">عزلتی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ]</font></b> (ص نسبی ) که عزلت اختیار کند. گوشه نشین و زاهد. (ناظم الاطباء).<br></font></div>'),
(183042, 'عزلتی', '<span class=\"hlight\">عزلتی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ]</font></b> (اِخ ) تخلص ادهم واعظ است . رجوع به ادهم واعظ شود.<br></font></div>'),
(183043, 'عزلتیان', '<span class=\"hlight\">عزلتیان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ]</font></b> (اِخ ) نام طایفه ای از صوفیه است . (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> یکی رادیدم که چون مرغ می پرید، چون با او رسیدم گفتم صحبت عزلتیان را چون گذاشتی . (انیس الطالبین بخاری ). جماعتی از عزلتیان به عبادت حضرت ایشان آمدند. (انیس الطالبین ص <span class=\"hlight\" dir=\"rtl\">١٥٧</span>). به چه سبب از میان عزلتیان جدا شده ای . (انیس الطالبین ص <span class=\"hlight\" dir=\"rtl\">١٦٤</span>). نقل کردند از برکةالزمان قطب عزلتیان عبدالقدوس الوهاب . (انیس الطالبین ص <span class=\"hlight\" dir=\"rtl\">٢٢٧</span>).<br></font></div>'),
(183044, 'عزلی', '<span class=\"hlight\">عزلی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (حامص ) معزولی . استعفا. (ناظم الاطباء).<br></font></div>'),
(183045, 'عزم', '<span class=\"hlight\">عزم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) قصد و آهنگ . (منتهی الارب ). اراده . (غیاث اللغات ). نیت . (نصاب ). اراده و قصد و آهنگ و هنگ . (ناظم الاطباء). اراده ٔ پیشین است برای واداشتن نفس بر انجام دادن کاری که در نظر گرفته شده است، لذا آن برای خداوند جایز نباشد. و گویند عزم و نیت، در معنی متحدند. (از اقرب الموارد). در فارسی، بالجزم، سبک عنان، سبک سر، سپهرسیر، زمان سیر، تندسیر، متین، کامکار از صفات اوست و با لفظ داشتن و کردن و برآراستن و آمدن و افتادن مستعمل است . (آنندراج )<span class=\"hlight\">:</span> و لقد عهدنا الی آدم من قبل فنسی و لم نجد له عزماً (قرآن <span class=\"hlight\" dir=\"rtl\">١١٥/٢٠</span>)؛ از پیش با آدم عهد بستیم ولی او آن را فراموش کرد و مر او را عزمی نیافتیم .<br>بدان کین و داد و بدان رزم و بزم <br>بدان امر و نهی و بدان رای و عزم .<br> <font color=\"Red\">فردوسی .</font><br>تاش بدان عزم است که حالی طوفی کند تا حشمتی افتد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٦٧</span>). اگر مرد از قوه ٔ عزم خویش مساعدتی تمام نیابد...(تاریخ بیهقی ).<br>چو دید عزم مرا بر سفر درست شده <br>فروشکست به لؤلؤ کناره ٔ عناب .<br> <font color=\"Red\">مسعودسعد.</font><br>ارکان و حدود آن را به ثبات حزم و نفاذ عزم چنان مستحکم و استوار گردانید که چهارصد و اند سال بگذشت . (کلیله و دمنه ). و آن را به ثبات عزم و حسن قصد نام نکند. (کلیله و دمنه ). و ثبات عزم صاحب شرع بدان پیوست . (کلیله و دمنه ).<br>آب خضر و نار موسی یافت شاه <br>عزم و حزمش این و آن بینی بهم .<br> <font color=\"Red\">خاقانی .</font><br>عزم او چون مهره ای خواهد نشاند<br>ششدر هفت آسمان خواهد گشاد.<br> <font color=\"Red\">خاقانی .</font><br>به دلی قوی و عزمی ذکی با حفظه ٔ آن قلعه جنگ آغاز نهاد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٧٤</span>). دواعی همت و بواعث نهمت ایشان محرک عزم و محرض قصد سلطان شده . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٠٨</span>). او از سر شطط و تجاهل حرکت کرد و به هراة رفت بر عزم غزنه . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٠٠</span>).<br>وز آنجا برون شد به عزم درست <br>بفرمان ایزد میان بست چست .<br> <font color=\"Red\">نظامی .</font><br>کعبه روی عزم ره آغاز کرد<br>قاعده ٔ کعبه روان ساز کرد.<br> <font color=\"Red\">نظامی .</font><br>چون دید که به نزدیک او عزم آمدن دارد بگریست . (گلستان سعدی ). جول ؛ عزم . (منتهی الارب ).<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عزم جفت طلب است و طلب آبستن یافت </span> <br>یافت را در طلب امکان به خراسان یابم .<br> <font color=\"Red\">خاقانی .</font><br>پای بر مرکب عزیمت آر<br>زآنکه عزم درست توست براق .<br> <font color=\"Red\">مغربی .</font><br>- <span class=\"hlight\">اولوالعزم </span> ؛ صاحبان عزم . دارندگان عزم و اراده . و در مورد اولوالعزم در قرآن کریم «فاصبر کما صبر اولوالعزم من الرسل » (قرآن <span class=\"hlight\" dir=\"rtl\">٣٥/٤٦</span>) ده قول آمده است و مشهورتر آن است که آنان نوح و ابراهیم و موسی و عیسی علیهم السلام باشند. (از اقرب الموارد). از پیغامبران آنان که بر امور عهدنموده ٔ خود و سپرده ٔ خدای تعالی آهنگ و کوشش کردند. یا آنها نوح و ابراهیم و موسی و محمد علیهم الصلاة و السلام هستند. و نزد زمخشری آنان صاحبان کوشش و ثبات و صبرند. یا نوح و ابراهیم و اسحاق و یعقوب ویوسف و موسی و داود و عیسی علیهم الصلاة و السلام . (منتهی الارب ) (آنندراج ). آنان پنج تن از پیغمبرانند: نوح و ابراهیم و موسی و عیسی و محمد علیهم السلام، زیراهر یک دارای عزم و شریعتی بودند که ناسخ شریعت پیش بود. و گفته اند اولوالعزم شش نفرند: نوح که صبر کرد بر اذیت قوم خود و ابراهیم که صبر نمود بر آتش، و اسحاق که صبر بر ذبح نمود، و یعقوب که صبر بر فراق فرزند و کوری نمود، و یوسف که در چاه و زندان صبر کرد، و ایوب که صبر بر ضرر نمود. و نیز گفته اند مراد نوح و ابراهیم و اسحاق و یعقوب و موسی علیهم السلام باشند.(ناظم الاطباء). و رجوع به اولوالعزم در ردیف خود شود.<br>- <span class=\"hlight\">باعزم </span> ؛ بااراده . مصمم . کسی که ایفای به عهد نماید و بر قول خود راسخ بماند. (ناظم الاطباء) <span class=\"hlight\">:</span> مرد خردمند باعزم و حزم آن است که وی به رأی روشن خویش به دل یکی بود با جمعیت . (تاریخ بیهقی ).<br>- <span class=\"hlight\">به عزم ِ... (لازم الاضافه )</span> ؛ بمنظور. بقصد: بعزم دیدار دوست خود حرکت کرد. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">بی عزم </span> ؛ بی اراده . بی تصمیم .<br>- <span class=\"hlight\">جزم کردن عزم </span> ؛ تصمیم قطعی گرفتن . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">سست عزم </span> ؛سست اراده . ضعیف اراده .<br>- <span class=\"hlight\">عزم بزم رفتن </span> ؛ رفتن به مهمانی و بزم . (ناظم الاطباء).<br>- <span class=\"hlight\">عزم جزم </span> ؛ قصد و آهنگ استوار و محکم .(ناظم الاطباء).<br>- <span class=\"hlight\">عزم درست </span> ؛ کسی که در اراده ٔ خود ثابت و جازم باشد. (ناظم الاطباء).<br>- <span class=\"hlight\">عزم راه کردن </span> ؛ اظهار مسافرت نمودن . (ناظم الاطباء). و رجوع به عزم کردن شود.<br>- <span class=\"hlight\">عزم سفر گرفتن </span> ؛ عزیمت سفر کردن و بجد عازم مسافرت گشتن . (ناظم الاطباء).<br>- <span class=\"hlight\">عزم کاری کردن </span> ؛ به جد و کوشش بسیارمرتکب آن کار شدن . (ناظم الاطباء). و رجوع به عزم کردن شود.<br>- <span class=\"hlight\">مصطفی عزم </span> ؛که عزمی چون عزم مصطفی دارد. استوار و متین <span class=\"hlight\">:</span> <br>مصطفی عزم و علی رزمی که هست <br>ذوالفقارش پاسبان مملکت .<br> <font color=\"Red\">خاقانی .</font><br><BR><font color=\"Blue\">◄</font> در اصطلاح صوفیه و عرفا، بناء حال و تحقیق قصد است در انجام عبادات و ریاضات و حمل نفس بر آنها و تحمل سختیهای سلوک راه حق و استغراق در لوائح مشاهدات و استجماع قوای استقامت بحکم «فاذا عزمت فی الامور فتوکل علی اﷲ»، و بالجمله تا سالک را در کارها و ریاضات و اعمال عزم نباشد ره به مقصود نبرد، و باید توجه خود را از کل مخلوق قطع کند و تمام قوای خود را متوجه محبوب کند. (فرهنگ مصطلحات عرفاء). <BR><font color=\"Blue\">◄</font> (اصطلاح فلسفه ) جزم اراده است، یعنی میل بعد از تردد که حاصل از دواعی مختلف باشد. (فرهنگ علوم عقلی از کشاف ). <BR><font color=\"Blue\">◄</font> (اصطلاح روانشناسی ) آنچه بعد از تصور غرض وهدف معین و در پایان تأمل (یعنی معارضه ٔ دلایل موافق و مخالف آن هدف و غرض ) صورت می پذیرد، عزم یا تصمیم نامیده می شود. (فرهنگ فارسی معین از روانشناسی علی اکبر سیاسی ). <BR><font color=\"Blue\">◄</font> (اصطلاح مکانیک ) قوه ای نسبت به یک نقطه، از شدت این قوه در مسافتی مستقیم که طبق آن قوه اعمال میشود حاصل میگردد. گشتاور. (از فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> کنجاره ٔ مویز. (منتهی الارب ). ثجیر و ثفل مویز. (از اقرب الموارد). ج، عُزُم . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(183046, 'عزم', '<span class=\"hlight\">عزم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) آهنگ نمودن بر کاری و دل نهادن وکوشش کردن . (از منتهی الارب ). دل به کاری نهادن . (دهار) (زمخشری ) (از تاج المصادر بیهقی ) (از المصادر زوزنی ): عزم الامر و عزم علی الامر؛ دل خود را بر انجام آن کار بست و تصمیم بر آن گرفت و آن را بدون تردید ودودلی انجام داد. (از اقرب الموارد). سر آن داشتن . بر آن بودن . اراده کردن . عُزم . عُزمان . عَزیم . عَزیمة. مَعزَم . مَعزِم . <BR><font color=\"Blue\">◄</font> آهنگ نموده شدن بر امر. (از منتهی الارب ): عزم الامرُ نفسُه ؛ یعنی بر آن کار قصد شد (به صورت مجهول )، و آن از نوع قلب است مبالغه را، چنانکه گوین : هلک الرجل، که بمعنی اُهلِک باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سوگند دادن کسی را. (از منتهی الارب ): عزم فلان علی الرجل، فلان ؛ آن مرد را سوگند داد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عزائم و افسون خواندن . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سخت دویدن . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> بر جاده راه رفتن . (آنندراج ). <BR><font color=\"Blue\">◄</font> واجب گردانیدن . (منتهی الارب ) (آنندراج ).<br></font></div>'),
(183047, 'عزم', '<span class=\"hlight\">عزم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) عَزم (در تمام معانی ). رجوع به عَزم شود.<br></font></div>'),
(183048, 'عزم', '<span class=\"hlight\">عزم .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (ع ص ) مردم استوار در دوستی و صحیح و ثابت در آن . (منتهی الارب ). ج، عَزَمة. (ناظم الاطباء). رجوع به عزمة شود.<br></font></div>'),
(183049, 'عزم', '<span class=\"hlight\">عزم .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ام العزم ؛ کون و اِست . (ناظم الاطباء). اِست . (اقرب الموارد). عزمة. ام عزمة. و رجوع به عزمة و ام عزمة شود.<br></font></div>'),
(183050, 'عزم', '<span class=\"hlight\">عزم .</span> <font color=\"DarkGreen\"><b>[ ع ُ زُ ]</font></b> (ع اِ) ج ِ عَزم . (منتهی الارب ) (اقرب الموارد). رجوع به عَزم شود.<br></font></div>'),
(183051, 'عزم', '<span class=\"hlight\">عزم .</span> <font color=\"DarkGreen\"><b>[ ع ُ زَ ]</font></b> (ع اِ) ج ِ عُزمة. (منتهی الارب ) (اقرب الموارد). رجوع به عزمة شود.<br></font></div>'),
(183052, 'عزم آمدن', '<span class=\"hlight\">عزم آمدن .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ دَ ]</font></b> (مص مرکب ) عزم حاصل شدن <span class=\"hlight\">:</span> <br>چو عزم آمد آن گوهر پاک را.<br><font color=\"Red\">؟ (از آنندراج ).</font><br></font></div>'),
(183053, 'عزم آوردن', '<span class=\"hlight\">عزم آوردن .</span> <font color=\"DarkGreen\"><b>[ ع َ وَ دَ ]</font></b> (مص مرکب ) تصمیم گرفتن . اراده کردن <span class=\"hlight\">:</span> <br>بر آنم میاور که عزم آورم <br>به هم پنجه ای با تو رزم آورم .<br><font color=\"Red\">نظامی .</font><br>کجا عزم راه آورد راهجوی <br>نراند چو آشفتگان پوی پوی .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(183054, 'عزم افتادن', '<span class=\"hlight\">عزم افتادن .</span> <font color=\"DarkGreen\"><b>[ ع َ اُ دَ ]</font></b> (مص مرکب ) عزم فتادن . عازم شدن . قصد کردن <span class=\"hlight\">:</span> <br>نه پایه قدر او ز نهم آسمان گذشت <br>هرگاه عزم او بسوی آسمان فتاد.<br><font color=\"Red\">علی خراسانی (از آنندراج ).</font><br></font></div>'),
(183055, 'عزم داشتن', '<span class=\"hlight\">عزم داشتن .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (مص مرکب ) قصد داشتن . تصمیم داشتن . بر آن بودن <span class=\"hlight\">:</span> درویش دید که شاهزاده بجانب او عزم آمدن دارد. (گلستان ).<br>عزم دارم کز دلت بیرون کنم <br>وَاندرون جان بسازم مسکنت .<br> <font color=\"Red\">سعدی .</font><br>گر این خیال محقق شدی به بیداری <br>که روی عزم همایون ازین طرف داری .<br> <font color=\"Red\">سعدی .</font><br>عزم دیدار تو دارد جان برلب آمده <br>بازگردد یا برآید چیست فرمان شما.<br><font color=\"Red\">حافظ (از آنندراج ).</font><br></font></div>'),
(183056, 'عزم کردن', '<span class=\"hlight\">عزم کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ دَ ]</font></b> (مص مرکب ) قصد کردن . آهنگ کردن <span class=\"hlight\">:</span> <br>ز بعد یوسف ایوب صابر آمد باز<br>بدهر بد صدوهفتاد و کرد عزم سفر.<br> <font color=\"Red\">ناصرخسرو.</font><br>گر کردی این عزم کسی را ز تفکر<br>نفرین کندی هر کس بر آزر بتگر.<br> <font color=\"Red\">ناصرخسرو.</font><br>نکند باز رأی صید ملخ <br>نکند شیر عزم زخم شکال .<br> <font color=\"Red\">؟ (از کلیله ودمنه ).</font><br>همه سر عقلم و چون عزم کنم <br>همه تن جان شوم ان شأاﷲ.<br> <font color=\"Red\">خاقانی .</font><br>چون نیست وجه زر نکنم عزم مکه باز<br>جلباب نیستی به سر و تن درآورم .<br> <font color=\"Red\">خاقانی .</font><br>چون ملکان عزم شدآمد کنند<br>نقل بنه پیشتر از خود کنند.<br> <font color=\"Red\">نظامی .</font><br>بعد از آن برخاست عزم شاه کرد<br>شاه را زآن شمه ای آگاه کرد.<br> <font color=\"Red\">مولوی .</font><br>عزم کردم و نیت جزم که بقیت عمرفرش هوس درنوردم . (گلستان سعدی ).<br>من همه قصد وصالش میکنم <br>وآن ستمگر عزم هجران میکند.<br> <font color=\"Red\">سعدی .</font><br>وگر نه عزم سیاحت کند نه یاد وطن <br>کسی که بر سر کویت مجاوری آموخت .<br> <font color=\"Red\">سعدی .</font><br>از خیال عشق دل عزم رمیدن میکند<br>حمد بر نقاش این شیر از کشیدن میکند.<br> <font color=\"Red\">میرزا شریف الهام تخلص (از آنندراج ).</font><br>اجماع ؛ عزم کردن بر کاری . (تاج المصادر بیهقی ) (منتهی الارب ).<br></font></div>'),
(183057, 'عزمات', '<span class=\"hlight\">عزمات .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (ع اِ) ج ِ عزمة. (آنندراج ) (غیاث اللغات ). رجوع به عزمة شود.<br></font></div>'),
(183058, 'عزمان', '<span class=\"hlight\">عزمان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) عَزم است در تمام معانی . رجوع به عَزم شود.<br></font></div>'),
(183059, 'عزمة', '<span class=\"hlight\">عزمة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع اِ) واجب و ثابت : عزمة من عزمات اﷲ؛ یعنی حقی از حقوق خداوند، یعنی واجبی از آنچه واجب کرده است . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) ثبات و پایداری : ما لَه عزمة و لا عزیمة؛ او را ثبات وصبری نیست در آنچه قصد میکند. (از اقرب الموارد).<br></font></div>'),
(183060, 'عزمة', '<span class=\"hlight\">عزمة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع مص ) عَزم (در تمامی معانی ). (از ناظم الاطباء). رجوع به عزم شود.<br></font></div>'),
(183061, 'عزمة', '<span class=\"hlight\">عزمة.</span> <font color=\"DarkGreen\"><b>[ ع َ زَ م َ ]</font></b> (ع ص ) مرد استوار در دوستی و ثابت قدم . (ناظم الاطباء). درست مودت . (از اقرب الموارد). ج، عُزَم . (ناظم الاطباء).<br></font></div>'),
(183062, 'عزمة', '<span class=\"hlight\">عزمة.</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ]</font></b> (ع اِ) کون . (منتهی الارب ). اِست . (اقرب الموارد). ام عزمة. عَزم .<br>- <span class=\"hlight\">ام عزمة</span>؛ کون . اِست . (از اقرب الموارد) (از منتهی الارب ). عِزم . عِزمة.<br></font></div>'),
(183063, 'عزمة', '<span class=\"hlight\">عزمة.</span> <font color=\"DarkGreen\"><b>[ ع ُ م َ ]</font></b> (ع اِ) نزدیکان و قبیله ٔ مرد. (منتهی الارب ). خانواده و قبیله ٔ شخص . (از اقرب الموارد). ج، عُزَم . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(183064, 'عزموت', '<span class=\"hlight\">عزموت .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) (بمعنی تا بموت قوی ) نام موضعی است در بن یامین . وبرخی آن را همان حزمه دانسته اند که در شمال عناثوث یعنی عناثای تازه واقع است . (از قاموس کتاب مقدس ).<br></font></div>'),
(183065, 'عزمی', '<span class=\"hlight\">عزمی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب به عزم، مرد که ایفای عهد نماید. (منتهی الارب ). وفاکننده ٔ به عهد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کنجاره فروش . (منتهی الارب ). فروشنده ٔ عزم یعنی ثفاله ٔ مویز. (از اقرب الموارد). و رجوع به عزم شود.<br></font></div>'),
(183066, 'عزمی زاده', '<span class=\"hlight\">عزمی زاده .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (اِخ ) مصطفی بن محمد، مشهور به عزمی زاده (<span class=\"hlight\" dir=\"rtl\">٩٧٧</span>-<span class=\"hlight\" dir=\"rtl\">١٠٤٠</span> هَ .ق .). از فقهای حنفی است و بترتیب قضای دمشق و مصر و بروسه و ادرنه را بعهده داشت . اصل او از ترکان است . او راست : نتائج الافکار، حاشیه بر درر الحکام، دیوان الانشاء، حاشیه بر هدایة. و نیز اشعاری بزبان عربی و رباعیاتی بزبان ترکی دارد. (از الاعلام زرکلی از خلاصةالاثر و کشف الظنون و هدیة العارفین ).<br></font></div>'),
(183067, 'عزه', '<span class=\"hlight\">عزه .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) پسر ابوناداب که تابوت عهد در حوالی خانه ٔ او که در قرب یعاریم بود توقف نمود و چون وی دستش را به صندوق عهد دراز کرد بدان واسطه خداوند او را کشت زیرا که این مطلب مخالف امر حضرت اقدس الهی بود، چه شغل حمل صندوق بر بنی قهاث موکول بود. (قاموس کتاب مقدس ).<br></font></div>'),
(183068, 'عزه', '<span class=\"hlight\">عزه .</span> <font color=\"DarkGreen\"><b>[ ع ِزْه ْ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ زِه ْ ]</font></b> (ع ص ) مرد که طرب و جماع رادوست ندارد و بازگردنده از آن . یا ناکس . یا آن که نپوشد کینه ٔ صاحب خود را. (منتهی الارب ): رجل عزه ؛ مرد روی گردان از لهو و از زنان که از آنها بطرب نیاید و از آنها دوری جوید. و گویند شخص لئیم و پست . و گویندآنکه بغض و کینه ٔ دوست خود را کتمان نکند. (از اقرب الموارد). عِزهاء. عِزهاة. عزهی <font color=\"DarkGreen\"><b>[ ع ِ ها <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ هی ی ]</font></b>. عُنزُهانی . عِنزَهو. عِنزَهوة. ج، عَزاه، عَزاهی، و عزِهون . (اقرب الموارد). و رجوع به عزهات شود.<br></font></div>'),
(183069, 'عزهات', '<span class=\"hlight\">عزهات .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) سست و ناتوان در آرامش با زنان . (یادداشت بخط مرحوم دهخدا). سست، یعنی کسی که قوت باه او زایل شده باشد. (غیاث اللغات ) (آنندراج ). عِزهاة. عزه <font color=\"DarkGreen\"><b>[ ع ِزْه ْ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ زِه ْ ]</font></b> . رجوع به عزه شود.<br></font></div>'),
(183070, 'عزهل', '<span class=\"hlight\">عزهل .</span> <font color=\"DarkGreen\"><b>[ ع ِ هََ ل ل ]</font></b> (ع ص ) فارغ از هر چیزی . (منتهی الارب ). فارغ . (اقرب الموارد).<br></font></div>'),
(183071, 'عزهل', '<span class=\"hlight\">عزهل .</span> <font color=\"DarkGreen\"><b>[ ع ِ هَِ ]</font></b> (ع ص، اِ) مرد دودله و مضطرب . (منتهی الارب ). مرد مضطرب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کبوتر یا چوزه ٔ آن . (منتهی الارب ). ذکر و نر از کبوتر، و گویند جوجه ٔ آن . (از اقرب الموارد). عَزهَل . و رجوع به عَزْهَل شود. <BR><font color=\"Blue\">◄</font> درگذرنده و پیشی گیرنده ٔ شتاب رو. (منتهی الارب ). سریع. (اقرب الموارد).<br></font></div>'),
(183072, 'عزهل', '<span class=\"hlight\">عزهل .</span> <font color=\"DarkGreen\"><b>[ ع َ هََ ]</font></b> (ع ص، اِ) مرد دودله و مضطرب . (منتهی الارب ). مرد مضطرب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کبوتر نر، یا چوزه ٔ آن . (منتهی الارب ). ذکر و نر از کبوتر، و گویند جوجه ٔ آن . (از اقرب الموارد). حمام ذکر، یعنی کبوتر نر. (مخزن الادویة). عِزهِل . و رجوع به عِزْهِل شود. <BR><font color=\"Blue\">◄</font> (اِخ ) از اعلام است . (از منتهی الارب ).<br></font></div>'),
(183073, 'عزهول', '<span class=\"hlight\">عزهول .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) درگذرنده و پیشی گیرنده ٔ شتاب رو. (منتهی الارب ). سبقت گیرنده ٔ سریع. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تیزرو و چست و سبکروح . (منتهی الارب ). سریع خفیف . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتر نر برسرخودگذاشته و شتر به چرا رهاکرده . (منتهی الارب ). جمل و شتر اهمال شده . (از اقرب الموارد). ابل . (مخزن الادویه ). ج، عَزاهیل . (اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(183074, 'عزهون', '<span class=\"hlight\">عزهون .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص، اِ) عَزاهی . رجوع به عزاهی شود.<br></font></div>'),
(183075, 'عزهی', '<span class=\"hlight\">عزهی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ها <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ هی ی ]</font></b> (ع ص ) بمعنی عزه <font color=\"DarkGreen\"><b>[ ع ِزْه ْ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ زِه ْ ]</font></b> است . (ازاقرب الموارد) (از منتهی الارب ). رجوع به عزه شود.<br></font></div>'),
(183076, 'عزو', '<span class=\"hlight\">عزو.</span> <font color=\"DarkGreen\"><b>[ ع َزْوْ ]</font></b> (ع مص ) نسبت کردن به چیزی . (آنندراج ) (غیاث اللغات ). نسبت دادن به کسی . (از ناظم الاطباء) (از اقرب الموارد). به کسی بازخواندن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> نسبت پذیرفتن . (از ناظم الاطباء). منتسب شدن به کسی، براست یا به دروغ . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شکیبائی کردن بر مصیبت . (غیاث اللغات ) (آنندراج ). و رجوع به عَزاء شود.<br></font></div>'),
(183077, 'عزوان', '<span class=\"hlight\">عزوان .</span> <font color=\"DarkGreen\"><b>[ ع َزْ ]</font></b> (اِخ ) (بنو...) گروهی از جن . (ناظم الاطباء). حیی از جن . (از اقرب الموارد).<br></font></div>'),
(183078, 'عزوب', '<span class=\"hlight\">عزوب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) پنهان گردیدن و دور رفتن و دور شدن . (از منتهی الارب ) (آنندراج ). دور شدن . (دهار). دور شدن و غایب گشتن و مخفی شدن . (از اقرب الموارد): عزب عنه حلمه ؛ بردباریش از وی دور شد و بردباری نکرد. (از اقرب الموارد) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> رفتن . (از اقرب الموارد) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بازایستادن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> عزب طهر المراءة؛ غایب شد شوی زن در ایام طهر وی . (ناظم الاطباء) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عزبت الارض ؛ کسی در آن زمین نبود، خواه حاصلخیز باشد یا غیرحاصلخیز. عَزب . و رجوع به عزب شود.<br></font></div>'),
(183079, 'عزوبة', '<span class=\"hlight\">عزوبة.</span> <font color=\"DarkGreen\"><b>[ع ُ ب َ ]</font></b> (ع مص ) بی زن و بی شوهر شدن . (تاج المصادر بیهقی ) (دهار): عزب الرجل ؛ آن مرد را اهل و خانواده نبوده است . (از اقرب الموارد). عُزبة. و رجوع به عزبة شود. <BR><font color=\"Blue\">◄</font> (اِمص ) بی زنی و بی شوئی . (منتهی الارب ). بی همسری . مجردی . عزوبت . و رجوع به عزوبت شود.<br></font></div>'),
(183080, 'عزوبة', '<span class=\"hlight\">عزوبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع ص ) زمین دورچراگاه و درازراه بسوی گیاه . (منتهی الارب ). زمینی که از علف و گیاه دور باشد. (از اقرب الموارد).<br></font></div>'),
(183081, 'عزوبت', '<span class=\"hlight\">عزوبت .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع اِمص ) عزوبة. بی زنی و مجردی . (ناظم الاطباء). بی همسری . مجرد بودن . رجوع به عزوبة شود.<br></font></div>'),
(183082, 'عزور', '<span class=\"hlight\">عزور.</span> <font color=\"DarkGreen\"><b>[ ع َزْ وَ ]</font></b> (ع ص ) بدخلق و بی غیرت در حق زن خود. (منتهی الارب ). سیی ءالخلق . (اقرب الموارد).<br></font></div>'),
(183083, 'عزور', '<span class=\"hlight\">عزور.</span> <font color=\"DarkGreen\"><b>[ ع َزْ وَ ]</font></b> (اِخ ) پشته ٔ جحفه که بر آن راه است . (منتهی الارب ). جایگاهی است یا آبی است، و گویند آن راه و «ثنیه ٔ» اهالی مدینه است بسوی بطحاء مکه . و برخی آن را ثنیه ٔ جحفة دانسته اند که راه بین مکه و مدینه بر آن قرار دارد. و نیز آن را کوهی دانسته اند در سمت راست طریق حجاج بسوی معدن بنی سلیم، که بین آنها ده میل فاصله است . و بعضی آن را کوهی نوشته اند در مقابل رضوی . (از معجم البلدان ). و رجوع به عزورة شود.<br></font></div>'),
(183084, 'عزوری', '<span class=\"hlight\">عزوری .</span> <font color=\"DarkGreen\"><b>[ ع َزْ وَ ری ی ]</font></b> (ص نسبی ) نسبت است به عزورة که جد ابومحمد سلیمان بن ربیعبن هشام بن عزوربن مهلهل نهدی عزوری کوفی است . وی به سال <span class=\"hlight\" dir=\"rtl\">٢٧٤</span> هَ .ق . درگذشته است . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(183085, 'عزوز', '<span class=\"hlight\">عزوز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) ناقه ای که سوراخ پستانش تنگ باشد، و نیز گوسفند. (از منتهی الارب ). ماده شتر تنگ احلیل، چنانکه گویند: ما العزوز کالفتوح ؛ یعنی ناقه ٔ تنگ احلیل چون ناقه ٔ گشاداحلیل نیست . (از اقرب الموارد). ج، عُزُز. (منتهی الارب ) (اقرب الموارد).<br>- <span class=\"hlight\">فلان عنز عزوز لها درجم </span> ؛ یعنی او بسیارمال و شحیح و بخیل است . (از اقرب الموارد).<br></font></div>'),
(183086, 'عزوز', '<span class=\"hlight\">عزوز.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) تنگ پستان شدن ناقه . (ازمنتهی الارب ). «عَزوز» گشتن ماده شتر. (از اقرب الموارد). عِزاز. و رجوع به عزاز شود. <BR><font color=\"Blue\">◄</font> قوی گردیدن . (از منتهی الارب ). عِزاز. رجوع به عزاز شود.<br></font></div>'),
(183087, 'عزوز حفصی', '<span class=\"hlight\">عزوز حفصی .</span> <font color=\"DarkGreen\"><b>[ ع َزْ زو زِ ح َ ]</font></b> (اِخ ) عبدالعزیزبن احمدبن محمدبن ابی بکر حفصی هنتابی، مکنی به ابوفارس و مشهور به عزوز (<span class=\"hlight\" dir=\"rtl\">٧٦١</span>-<span class=\"hlight\" dir=\"rtl\">٨٣٧</span> هَ .ق .). وی از بزرگان حفصی ها که از ملوک تونس بوده اند بشمار میرفت و بسال <span class=\"hlight\" dir=\"rtl\">٧٩٦</span> هَ .ق . پس از درگذشت پدرش با وی بیعت شد، و دو شهر تلمسان و فاس را ضمیمه ٔ قلمرو خود کرد. (از الاعلام زرکلی از الخلاصة النقیه و لقط الفرائد و الضوء اللامع).<br></font></div>'),
(183088, 'عزوزا', '<span class=\"hlight\">عزوزا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) موضعی است بین حرمین شریفین . (منتهی الارب ). جایگاهی است بین مکه و مدینه، که ذکر آن در اخبار آمده است . و نیز ممکن است تصحیفی از «عزور» باشد که قبلاً ذکر شد. (از معجم البلدان ).<br></font></div>'),
(183089, 'عزوزی', '<span class=\"hlight\">عزوزی .</span> <font color=\"DarkGreen\"><b>[ ع َ زا ]</font></b> (اِخ ) عزوزا. رجوع به عزوزا شود.<br></font></div>'),
(183090, 'عزوف', '<span class=\"hlight\">عزوف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(ع ص ) دلتنگ و برتافته روی از چیزی . (منتهی الارب ): رجل عزوف ؛ شخصی که بر خوی دوست خود پایداری نتواند. ج، عِزاف . (از اقرب الموارد). و رجوع به عُزوف شود.<br></font></div>'),
(183091, 'عزوف', '<span class=\"hlight\">عزوف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) ناخواهانی نمودن و ملول شدن نفس از کسی . (از منتهی الارب ): عزفت النفس عن الشی ٔ؛ دل از آن چیز پرهیز کرد و از آن دور شد و یا از آن اکراه داشت، و آن را «عزوف عنه » گویند. (از اقرب الموارد). عَزف . و رجوع به عزف شود. <BR><font color=\"Blue\">◄</font> بازداشتن نفس از دنیا. (از منتهی الارب ). بازداشتن تن خویش را از کاری . (تاج المصادر بیهقی ).<br></font></div>'),
(183092, 'عزوفة', '<span class=\"hlight\">عزوفة.</span> <font color=\"DarkGreen\"><b>[ ع َف َ ]</font></b> (ع ص ) به معنی عزوف است، و تاء آن مبالغه راست نه تأنیث . (از اقرب الموارد). رجوع به عَزوف شود.<br></font></div>'),
(183093, 'عزوق', '<span class=\"hlight\">عزوق .</span> <font color=\"DarkGreen\"><b>[ ع َزْ وَ ]</font></b> (ع اِ) بار درخت پسته در حال بی مغزیش، و آن در دباغت بکار آید. یا بار درختی بدمزه ٔ زبان گز. (منتهی الارب ). بار درخت پسته را گویند و بپارسی پسته گویند، چون مغز نباشد دردهد و پوستها را برآیند، و پارسیان او را قزغند گویند و بزغند نیز گویند. (تذکره ٔ ضریر انطاکی ). بار درخت پسته است در سالی که مغز آن منعقد و بسته نشود، و آن دباغت راست . و گویند آن بار درختی است که مزه ای ناپسند دارد. (از اقرب الموارد).<br></font></div>'),
(183094, 'عزوم', '<span class=\"hlight\">عزوم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) کسی که بر عزم و قصد خود پایداری کند تا به هدف خویش برسد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گنده پیر. (منتهی الارب ). پیره زال . (ناظم الاطباء). عجوز. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شترماده ٔ مسن که درآن اندکی قوت باشد. (منتهی الارب ). ناقه ٔ سالخورده که در آن بقیه ای از جوانی باشد. (از اقرب الموارد).<br></font></div>'),
(183095, 'عزومة', '<span class=\"hlight\">عزومة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع اِ)جشن در باغستانها معمول ِ دهقانها. (ناظم الاطباء).<br></font></div>'),
(183096, 'عزومة', '<span class=\"hlight\">عزومة.</span><font color=\"DarkGreen\"><b>[ ع ُ م َ ]</font></b> (ع اِ) ضیافت و مهمانی . (ناظم الاطباء).<br></font></div>'),
(183097, 'عزون', '<span class=\"hlight\">عزون .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ عِزَة در حال رفع. (از منتهی الارب ). گروهی مجتمع از مردم . (آنندراج ). عِزین . و رجوع به عزة و عزین شود.<br></font></div>'),
(183098, 'عزون', '<span class=\"hlight\">عزون .</span><font color=\"DarkGreen\"><b>[ ع ُزْ زو ]</font></b> (اِخ ) از اعلام است . (از منتهی الارب ).<br></font></div>'),
(183099, 'عزوی', '<span class=\"hlight\">عزوی .</span> <font color=\"DarkGreen\"><b>[ ع َزْ وا ]</font></b> (ع اِ) کلمه ای است جهت عطوفت و مهربانی خواستن . (منتهی الارب ). کلمه ای است که بدان عطوفت و مهربانی میخواهند. (ناظم الاطباء). عزوی و تَعزی ̍ دو کلمه اند استعطاف را در لغت اهل «شحر»، و آنان چنین گویند: عزوی تعزی لقد کان کذا و کذا، و آن را در مقام تلطف و استعطاف گویند، چنانکه ما گوئیم : لعمری کان کذا و کذا. (از اقرب الموارد).<br></font></div>'),
(183100, 'عزویت', '<span class=\"hlight\">عزویت .</span> <font color=\"DarkGreen\"><b>[ ع ِزْ ]</font></b> (اِخ ) موضعی است . (منتهی الارب ). نام شهری است . (از معجم البلدان ).<br></font></div>'),
(183101, 'عزی', '<span class=\"hlight\">عزی .</span> <font color=\"DarkGreen\"><b>[ ع َزْ زا ]</font></b> (اِخ ) (حَفر...) ناحیه ای است به موصل . (منتهی الارب ).<br></font></div>'),
(183102, 'عزی', '<span class=\"hlight\">عزی .</span> <font color=\"DarkGreen\"><b>[ ع َ زی ی ]</font></b> (ع ص ) شکیبا و صابر. (ناظم الاطباء). صبور. (اقرب الموارد).<br></font></div>'),
(183103, 'عزی', '<span class=\"hlight\">عزی .</span> <font color=\"DarkGreen\"><b>[ ع ِ زا <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ زَن ْ ]</font></b> (ع اِ) ج ِ عِزة.(اقرب الموارد) (منتهی الارب ). رجوع به عِزَة شود.<br></font></div>'),
(183104, 'عزی', '<span class=\"hlight\">عزی .</span> <font color=\"DarkGreen\"><b>[ ع ُزْ زا ]</font></b> (ع ص ) زن ارجمند و کمیاب و زن دوست داشته . (منتهی الارب ). زن عزیز و شریف . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ن تف ) مؤنث أعزّ. (منتهی الارب ) (از اقرب الموارد). رجوع به اعز شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(183105, 'عزی', '<span class=\"hlight\">عزی .</span> <font color=\"DarkGreen\"><b>[ ع ُزْ زا ]</font></b> (اِخ ) بت . (دهار). یکی از دو بت معروف طایفه ٔ قریش (عرب ) در عهد جاهلیت، و دیگری لات نام داشته و اعراب بت پرست آنها را دختران خدا میدانستند. (فرهنگ فارسی معین ). بتی است یا درخت طلح که قوم غطفان می پرستیدند. نخستین کسی که آن را به پرستش اتخاذ کرد ظالم بن اسعد بود که در نه میلی بالای ذات عرق بسوی البستان، بر آن خانه ای بساخت و آن را بُس ّ نامید، و مردم از آن اصواتی می شنیدند. رسول خدا (ص ) خالدبن ولید را بفرستاد و آن خانه را واژگون ساخت و آن درخت سَمُرة را بسوزاند. (از منتهی الارب ). بت و صنمی بود قریش و بنی کنانة را، و گویند آن درخت سمره ای بود بنی غطفان را که آن را می پرستیدند و بر آن خانه ای ساخته بودند و سدنه و خادمانی بر آن گماشته بودند. (از اقرب الموارد). لات صنمی بود ازآن ِ ثقیف، و عزی درخت سمره ای ازآن ِ بنی غطفان که مورد پرستش آنان بود. وآن تأنیث أعز است مثل کبری مؤنث اکبر. و گویند عزی درختی بود که در نخله ای قرار داشت و آن را بتی بود که غطفان آن را می پرستیدند و خدمه و سدنه ٔ آن از بنی صرمةبن مرة بوده اند، و عزی را جدیدتر از لات و مناةدانند، و آن عظیم ترین ِ اصنام قریش است و آن را زیارت میکردند و هدیه میدادند و بوسیله ٔ ذبح قربانی، بدان تقرب می جستند. و قریش مردمی از وادی حُراض برای حمایت آن قرار داده بودند که آنان را سُقام میگفتند. واین بت را منحری بود که هدایا را در آن نحر میکردندو آن را غبغب میگفتند. و آخرین تن از سدنه ٔ آن دبیةبن حزمی سلمی است . اهمیت بتها در نزد اعراب جاهلیت بترتیب ازآن ِ عزی و لات و مناة بود. و قریش عزی را مهمتر از آن دو میدانست و ثقیف لات را و اوس و خزرج مناةرا. (از معجم البلدان ) <span class=\"hlight\">:</span> اء فرأیتم الللات و العزی (قرآن <span class=\"hlight\" dir=\"rtl\">١٩/٥٣</span>)؛ پس آیا لات و عزی را دیدید؟<br>ز بان و ارغوان و اقحوان و ضیمران نو<br>جهان گشته ست از خوشی بسان لات و العزی .<br> <font color=\"Red\">منوچهری .</font><br>از میان خانه ٔ کعبه فروآویختند<br>شعر نیکو را به زرین سلسله پیش عزی .<br> <font color=\"Red\">منوچهری .</font><br>اینکه می بینی بتانند ای پسر<br>کرد باید نامشان عزی و لات .<br> <font color=\"Red\">ناصرخسرو.</font><br>همچنان کو گفت میگوید سخن <br>دیو در عزی و لات اندر منات .<br> <font color=\"Red\">ناصرخسرو.</font><br>گذر من بسوی دیر افتاد<br>لات را دیدم آگه از عزی .<br> <font color=\"Red\">(منسوب به ناصرخسرو).</font><br>بیا کعبه ٔ عزت دل ز عزی <br>تهی کن کز این به غزائی نیابی .<br> <font color=\"Red\">خاقانی .</font><br>بت پرست صورتی در خانه ٔ مکر و حیل <br>با منات و با سواع و لات و با عزی منم .<br> <font color=\"Red\">سعدی .</font><br>به لا قامت لات بشکست خرد<br>به اعزاز دین آب عزی ببرد<br>نه از لات و عزی برآورد گرد<br>که تورات و انجیل منسوخ کرد.<br> <font color=\"Red\">سعدی .</font><br>اگر نقش رخت ظاهر نبودی در همه اشیا<br>مغان هرگز نکردندی پرستش لات و عزی را.<br><font color=\"Red\">سلمان ساوجی .</font><br></font></div>'),
(183106, 'عزیا', '<span class=\"hlight\">عزیا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) (عزت یهوه ) پسر امصیا و جانشین او که در سن شانزده سالگی از سال <span class=\"hlight\" dir=\"rtl\">٧٨٦</span> تا <span class=\"hlight\" dir=\"rtl\">٧٣٤</span> ق .م . به تخت سلطنت جلوس نمود و <span class=\"hlight\" dir=\"rtl\">٥٢</span> سال سلطنت کرد. وی ابتدا بر اعدای خود مظفر و پیروز بود ولی این ظفر سبب به خود بالیدن او گردید و خواست به عمل مختص کهانت دست اندازی کند و بخور بر مذبح بخور سوزاند، لذا خداوند او را به آفت برص مبتلی کرد و تا آخر عمر در خانه ای که مخصوص مبروصان بود میزیست . در عهد او زلزله ٔ عظیمی حادث شد. نام او را عزریا نیز خوانده اند. (از قاموس کتاب مقدس ).<br></font></div>'),
(183107, 'عزیب', '<span class=\"hlight\">عزیب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام شهری است و در شعر خالدبن زهیر هذلی آمده است . (از معجم البلدان ).<br></font></div>'),
(183108, 'عزیب', '<span class=\"hlight\">عزیب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) مرد بی زن . (منتهی الارب ). مردی که او را اهل و خانواده نباشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد که از اهل و مال خود دور شود. (منتهی الارب ) (از اقرب الموارد). ج، اعزاب . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> شتر و گوسپند که از صاحب خود دور رود در چراگاه . <BR><font color=\"Blue\">◄</font> ج ِ عازِب . (از اقرب الموارد) (منتهی الارب ). گویند: ابل عزیب ؛ شترانی که بشب برنگردند بر حی و قبیله . (از اقرب الموارد).<br></font></div>'),
(183109, 'عزیة', '<span class=\"hlight\">عزیة.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دختر محمدبن عبدالملک بن یوسف مقدسی . از زنان محدث بود و در نقل احادیث نام او آمده است . (از اعلام النساء از مخطوطات دار الکتب الظاهریة).<br></font></div>'),
(183110, 'عزیة', '<span class=\"hlight\">عزیة.</span> <font color=\"DarkGreen\"><b>[ ع ِزْ ی َ ]</font></b> (ع اِمص ) انتساب . (اقرب الموارد). نسبت و دعوی نسبت . (ناظم الاطباء). عِزوة. رجوع به عزوة شود.<br></font></div>'),
(183111, 'عزیر', '<span class=\"hlight\">عزیر.</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) بهای گیاه دروده که علف زار فروخته شود. (منتهی الارب ). بهای گیاه دروده ٔ از علف زار. (ناظم الاطباء). بهای گیاه و علف هرگاه درو شود و مزارع آن فروخته شود. گویند: هل أخذت عزیر هذا الحصید؛ یعنی آیا بهای علف زار این حصید را گرفته ای ؟ (از اقرب الموارد). عَزْر. عَزائر. و رجوع به عزائر و عزر شود.<br></font></div>'),
(183112, 'عزیر', '<span class=\"hlight\">عزیر.</span> <font color=\"DarkGreen\"><b>[ ع ُ زَ ]</font></b> (اِخ ) نام پیغمبری، و آن منصرف است جهت خفتش، هرچند اعجمی است . (از اقرب الموارد) (از منتهی الارب ). کاهن ورهبر عبرانیان در قرن پنجم ق .م . که نزد مسلمانان بعنوان پیغمبر مشهور است و نام اصلی او عِزْرا میباشد.(از فرهنگ فارسی معین ). نام پیغمبری است که صد سال مرده بود، پس خدای تعالی او را زنده گردانید. (ترجمان القرآن علامه جرجانی ). نام پیغامبری که در احیاء موتی شک کرد و خدای جان او و خرش بستد و پس از صد سال از نو زنده کرد و هنوز میوه های چیده ٔ او تازه مانده بود. و یهود او را پسر خدای گفتندی . (یادداشت مرحوم دهخدا). و در سبب اینکه یهود او را پسر خدای دانسته اند روایاتی چند است که در تفسیر ابوالفتوح رازی نقل شده است . رجوع به عزرا و تفسیر ابوالفتوح رازی ج <span class=\"hlight\" dir=\"rtl\">٥</span> صص <span class=\"hlight\" dir=\"rtl\">١٦٠</span> - <span class=\"hlight\" dir=\"rtl\">١٦٤</span> شود <span class=\"hlight\">:</span> و قالت الیهود عُزَیرٌ ابن اﷲ (قرآن <span class=\"hlight\" dir=\"rtl\">٣٠/٩</span>)؛ و یهود گفتند عزیر پسر خدا است .<br>چو دوزخ بدانست و راه بهشت <br>عزیر و مسیح و ره زردهشت .<br> <font color=\"Red\">فردوسی .</font><br>چو راه فریدون شود نادرست <br>عزیرو مسیحا و هم زند و اُست .<br> <font color=\"Red\">فردوسی .</font><br>چو خر سوار شوم  جز خر عزیر و مسیح <br>همه خران به یکی  چوب رانم از سودا.<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(183113, 'عزیری', '<span class=\"hlight\">عزیری .</span> <font color=\"DarkGreen\"><b>[ ع ُ زَ ]</font></b> (اِخ ) محمدبن عزیر سجستانی . مصنف کتاب غریب القرآن . نسبت او به پدرش است، و به دو زاء خواندن آن خطا باشد. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(183114, 'عزیری', '<span class=\"hlight\">عزیری .</span> <font color=\"DarkGreen\"><b>[ ع ُ زَ ]</font></b> (اِخ ) احمدبن عبداﷲبن عمار کاتب عزیری، مکنی به ابوالعباس و مشهور به حمار العزیری . محدث بود و از ابن ابی شیبة و دیگران روایت دارد. او شیعی مذهب و از غُلات بود. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(183115, 'عزیری', '<span class=\"hlight\">عزیری .</span> <font color=\"DarkGreen\"><b>[ ع ُ زَ ]</font></b> (ص نسبی ) منسوب به عزیر، که پیامبری او مورد اختلاف است . (از اللباب فی تهذیب الانساب ). و رجوع به عزیر شود.<br></font></div>'),
(183116, 'عزیز', '<span class=\"hlight\">عزیز.</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن هبةاﷲبن علی علوی حسینی . جد او نقیب النقبای خراسان بود و نقابت علویان و وزارت سلطان به او پیشنهاد شد اما او از شدت زهد و تقوی از پذیرفتن آن امتناع ورزید و به سال <span class=\"hlight\" dir=\"rtl\">٥٢٧</span> هَ .ق . بطور ناگهانی در نیشابور درگذشت . (از الاعلام زرکلی از ابن الاثیر).<br></font></div>'),
(183117, 'عزیز', '<span class=\"hlight\">عزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبداﷲبن بُرْزال زناتی، ملقب به المستظهر. دومین تن از ملوک بنی برزال در قرمونة و توابع آن در اندلس . وی به سال <span class=\"hlight\" dir=\"rtl\">٤٣٤</span> هَ .ق . والی آنجا گشت و پس از <span class=\"hlight\" dir=\"rtl\">٢٥</span> سال حکومت از المعتضدبن عباد شکست خورد و به اشبیلیه گریخت و به سال <span class=\"hlight\" dir=\"rtl\">٤٥٩</span> هَ .ق . درآنجا درگذشت . (از الاعلام زرکلی از البیان المغرب ).<br></font></div>'),
(183118, 'عزیز', '<span class=\"hlight\">عزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) (الملک الَ ...) لقب عثمان بن یوسف، ملقب به عمادالدین، دومین از امرای ایوبی مصر است . رجوع به عمادالدین ایوبی و به الاعلام زرکلی شود.<br></font></div>'),
(183119, 'عزیز', '<span class=\"hlight\">عزیز.</span>  <font color=\"DarkGreen\"><b>[ ع ُ زَ ]</font></b> (ع اِ) سرمه ای است .(منتهی الارب ). کحلی است معروف . (مخزن الادویة) (از اقرب الموارد). نام سرمه ای است که تاریکی چشم و خشک کردن رطوبات آن را سود دارد. (یادداشت مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> (اِخ ) از اعلام است . (از منتهی الارب ).<br></font></div>'),
(183120, 'عزیز', '<span class=\"hlight\">عزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالملک بن محمدبن خطاب ازدی، مشهور به ابن خطاب . از امرای اندلس و از اهالی مرسیه . وی از جانب ابن هود المتوکل والی اندلس بود و پس از ادعای استقلال بسال <span class=\"hlight\" dir=\"rtl\">٦٣٦</span> هَ .ق . با وی بیعت شد و پس از نه ماه به دست زبان بن مدافع بقتل رسید. (از الاعلام زرکلی از الحلة السیراء).<br></font></div>'),
(183121, 'عزیز', '<span class=\"hlight\">عزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) (الملک الَ ...)لقب محمدبن غازی بن یوسف بن ایوب (<span class=\"hlight\" dir=\"rtl\">٦١١</span>-<span class=\"hlight\" dir=\"rtl\">٦٣٤</span> هَ .ق .) ازایوبیان شام و صاحب حلب است و درگذشت او نیز در حلب بود. (از الاعلام زرکلی از ابن الوردی و ابن الشحنة).<br></font></div>'),
(183122, 'عزیز', '<span class=\"hlight\">عزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) جدّی است جاهلی، و فرزندان او بطنی از بنی هلال بن عامر از عدنانیه اند. مساکن آنان در ساقیة قلتة، از عمل اخمیم، درصعید مصر بوده است . (از الاعلام زرکلی به نقل از نهایة الارب و البیان و الاعراب و خطط مبارک و السبائک ).<br></font></div>'),
(183123, 'عزیز', '<span class=\"hlight\">عزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) (المک الَ ...) لقب عثمان بن عادل ایوبی، از ایوبیان شام است . رجوع به عمادالدین ایوبی و به الاعلام زرکلی شود.<br></font></div>'),
(183124, 'عزیز', '<span class=\"hlight\">عزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن فضل بن فضالة، مکنی به ابوالاشعث . رجوع به ابوالاشعث (عزیز...) شود.<br></font></div>'),
(183125, 'عزیز', '<span class=\"hlight\">عزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) (الملک الَ ...) (<span class=\"hlight\" dir=\"rtl\">٨٢٧</span>-<span class=\"hlight\" dir=\"rtl\">٨٦٨</span> هَ .ق .) لقب یوسف بن برسبای دقماقی ظاهری، مکنی به ابوالمحاسن و ملقب به جمال الدین، از ملوک دولت چرکسیان در مصر و شام است . تولد او در قاهره بود و به سال <span class=\"hlight\" dir=\"rtl\">٨٤١</span> هَ .ق . پادشاه خوانده شد و در سال <span class=\"hlight\" dir=\"rtl\">٨٤٢</span> ممالیک جقمق او را از سلطنت خلع کردند و در برج اسکندریه زندانی ساختند. و در سال <span class=\"hlight\" dir=\"rtl\">٨٦٥</span> هَ .ق . در زمان دولت الظاهر خشقدم از زندان آزاد شد و در اسکندریه سکنی گزید و در همین شهر درگذشت . (از الاعلام زرکلی از الضوء اللامع و شذرات الذهب ).<br></font></div>'),
(183126, 'عزیز', '<span class=\"hlight\">عزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) ارجمند. (منتهی الارب ) (مهذب الاسماء) (المصادر زوزنی ). ارجمند وبزرگوار و خطیر. (زمخشری ). شریف و بزرگوار و باعزت .(از ناظم الاطباء). گرانمایه و محترم . (از فرهنگ فارسی معین ). منیع. گران . ج، عِزاز، أعزّة، أعزّاء، عِزازة. (از اقرب الموارد) (منتهی الارب ) <span class=\"hlight\">:</span> <br>دریغ فر جوانی و عز اوی دریغ<br>عزیز بودم از این پیش همچنان سپریغ.<br> <font color=\"Red\">شهید بلخی .</font><br>بس عزیزم بس گرامی شاد باش <br>اندرین خانه بسان نو بیوگ .<br> <font color=\"Red\">رودکی .</font><br>من اینجا دیر ماندم خوار گشتم <br>عزیزاز ماندن دائم شود خوار.<br> <font color=\"Red\">دقیقی .</font><br>بدینار و دیبا و اسب و کنیز<br>مکن خوار ای پور جان عزیز.<br> <font color=\"Red\">فردوسی .</font><br>دو شهزاده بد نزد لهراسب نیز<br>که بودند هر دو چو جان عزیز.<br> <font color=\"Red\">فردوسی .</font><br>عزیزتر ز همه خلق یار نیک بود<br>بکارتر ز همه کار خدمت سلطان .<br> <font color=\"Red\">فرخی .</font><br>کشان کشان همی آورد هر کسی سوی او<br>مبارزان و عزیزان آن سپه را خوار.<br> <font color=\"Red\">فرخی .</font><br>عزیز نبودآنکس که تو عزیز کنی <br>زبهر آنکه عزیز تو زود گردد خوار<br>عزیز آنکس باشد که کردگار جهان <br>کند عزیزش بی سیر کوکب سیار.<br> <font color=\"Red\">ابوحنیفه ٔ اسکافی .</font><br>هیچ چیز عزیزتر از جان نباشد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٥٧</span>). اکنون فرزند حاجب را... نواختی تمام ارزانی داشتیم و حاجبی یافت و پیش ما عزیز باشد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٣٥</span>).<br>منزل توست جهان ای سفری جان عزیز<br>سفرت سوی سرائیست که آن جای بقاست .<br> <font color=\"Red\">ناصرخسرو.</font><br>تو بی هنری چرا عزیزی <br>او بی گنهی چراست مضطر.<br> <font color=\"Red\">ناصرخسرو.</font><br>عزیز الهی به سعی بدخواه ذلیل نگردد. (اندرزنامه ٔ منسوب به خواجه نظام الملک ).<br>زآن عزیز است آفتاب که او<br>گاه پیدا و گاه ناپیداست .<br> <font color=\"Red\">مسعودسعد.</font><br>گفتمش ای روی تو عزیزتر از جان <br>دیدن رویت ز زندگانی خوشتر.<br> <font color=\"Red\">مسعودسعد.</font><br>چون فتح ز تیغ تو عزیز است برِ ملک <br>تیغ تو همه ساله عزیز است برِ فتح .<br> <font color=\"Red\">مسعودسعد.</font><br>اقوال پسندیده مدروس گشته ... و مظلوم محق ذلیل و ظالم مبطل عزیز. (کلیله و دمنه ).<br>ای خدایت عزیز کرده ز خلق <br>بنده را هست میهمان عزیز.<br> <font color=\"Red\">انوری .</font><br>ای به تو دین عزیز و دنیا خوار<br>خوار شد هرکه ت او نخواست عزیز.<br> <font color=\"Red\">انوری .</font><br>عزیز باشد نوباوه هر کجا که رسد<br>شکوفه ٔ دل ما را چنان گرامی دار.<br> <font color=\"Red\">جمال الدین عبدالرزاق .</font><br>هر فروتر به بزرگی است عزیز<br>هر پیمبر به خدا محترم است .<br> <font color=\"Red\">خاقانی .</font><br>خواجه ای وعده ٔ نوالم داد<br>بر زبان عزیزتر مردی .<br> <font color=\"Red\">خاقانی .</font><br>مهجور هفت ماهه منم زآن دوهفته ماه <br>کز نیکوئی چو عید عزیز است منظرش .<br> <font color=\"Red\">خاقانی .</font><br>از تقریب و ترحیب بهره ای تمام یافت و مدتی عزیز و مکرم ملازم خدمت بود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٤٠</span>).<br>چون به از جان نیست جان باشد عزیز<br>چون به آمد نام جان شدچیزلیز.<br> <font color=\"Red\">مولوی .</font><br>مسکین خر اگرچه بی تمیز است <br>چون بار همی برد عزیز است .<br> <font color=\"Red\">سعدی .</font><br>در او فضل دیدند و عقل و تمیز<br>نهادند رختش به جائی عزیز.<br> <font color=\"Red\">سعدی .</font><br>جریده رو که گذرگاه عافیت تنگ است <br>پیاله گیر که عمر عزیز بی بدل است .<br> <font color=\"Red\">حافظ.</font><br>بگیتی درون ای به رخ نوبهار<br>عزیز است آنکس که زر کرد خوار.<br> <font color=\"Red\">ادیب (از امثال و حکم دهخدا).</font><br>منتطق، منیع؛ عزیز. <BR><font color=\"Blue\">◄</font> کمیاب و ناموجود. (منتهی الارب ). قلیل و نادر که کمتر یافت شود. (از اقرب الموارد). کمیاب و نادر. (فرهنگ فارسی معین ). بی همتا. (مهذب الاسماء) (ترجمان القرآن جرجانی ). آنچه کمتر بدان دسترسی باشد. دشواریافت . دشواریاب . غریب . غریبه . طریف <span class=\"hlight\">:</span> <br>که بار نمک هست آنجا عزیز<br>بقیمت از آن به ندارند چیز.<br> <font color=\"Red\">فردوسی .</font><br>در نشابور دهی بود محمدآبادنام و به شادیاخ پیوسته وجائی عزیز است . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٦٢١</span>).<br>من در سخن عزیز جهانم به شرق و غرب <br>کز شرق و غرب نام سخنور نکوتر است .<br> <font color=\"Red\">خاقانی .</font><br>چون عقل و جان عزیز و غریب است لاجرم <br>جاندار عقل و عاقله ٔ جان شناسمش .<br> <font color=\"Red\">خاقانی .</font><br>مکن عمر ضایع به افسوس و حیف <br>که فرصت عزیز است و الوقت سیف .<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> گرامی و محبوب . (فرهنگ فارسی معین ). مکرم . (اقرب الموارد). گرامی . (منتهی الارب ). نازنین . نیازی <span class=\"hlight\">:</span> به نهادهای عزیزان و خداوندزاده ها که به قلعتهای سپنج بودندبه غزنین بازآمدند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٥٤٤</span>).<br>- <span class=\"hlight\">عزیز بی جهت </span> ؛ در تداول عامه، کسی که خود را به غلط محبوب دیگران پندارد. (فرهنگ فارسی معین ). آنکه پندارد که مقبول خاطر دیگران است . آنکه برای خویشتن حرمتی و محبوبیتی نزد خلق تصور کند و نه چنان باشد: مثل گربه عزیز بی جهت . (امثال و حکم دهخدا).<br>- <span class=\"hlight\">عزیز پدر و مادر</span> ؛ محبوب پدر و مادر. آنکه پدر و مادر، او را بسیار گرامی دارند.<br>- <BR><font color=\"Blue\">◄</font> به طنز حمالان را گویند، و تعبیریست که با آن منع از گرامی داشتن فرزندان و تحریض به سعی در تربیت و تعلیم آنان کنند. (امثال و حکم دهخدا).<br>ای عزیز مادر و جان پدر تا کی ترا<br>این بزیر پنبه دارد وآن بزیر دوکدان .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عزیز نازنین </span> ؛ عزیزدردانه . (از یادداشت مرحوم دهخدا). رجوع به ماده ٔ عزیزدردانه شود.<br> <BR><font color=\"Blue\">◄</font> بزرگان صوفیان . مرشدان و رهبران تصوف <span class=\"hlight\">:</span> <br>پی از هر خسی سایه پرورد بگسل <br>نظر بر عزیزان جان پرور افکن .<br> <font color=\"Red\">خاقانی .</font><br>از عزیزان سؤال دل کردم <br>هیچ شافی جواب نشنیدم .<br> <font color=\"Red\">خاقانی .</font><br>الا ای که بر خاک ما بگذری <br>به خاک عزیزان که یاد آوری .<br> <font color=\"Red\">سعدی .</font><br>سر نه که در راه عزیزان بود<br>بار گران است کشیدن به دوش .<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> (اِخ ) صفتی از صفات باری تعالی . (منتهی الارب ). از نامهای خداوندتعالی است و آن منیعی است که درک نگردد و مغلوب نشود و چیزی او را عاجز نکند و او را مانند نباشد. (از اقرب الموارد). نامی از نامهای خدای تعالی . (مهذب الاسماء). یکی از اسماء حسنی .<br>- <span class=\"hlight\">عزیزالانتقام </span> ؛ خداوند عالم که منتقم حقیقی است . (ناظم الاطباء).<br>- <span class=\"hlight\">عزیز مقتدر</span> ؛خداوند تبارک و تعالی . (ناظم الاطباء).<br> <BR><font color=\"Blue\">◄</font> (ص ) چیره . (منتهی الارب ). قوی . (اقرب الموارد). غالب . پیروز <span class=\"hlight\">:</span> کذبوا بآیاتنا کلها فأخذناهم أخذ عزیز مقتدر (قرآن <span class=\"hlight\" dir=\"rtl\">٤٢/٥٤</span>)؛ پس تمامی آیات ما را تکذیب کردند و آنها را گرفتیم گرفتن شخص غالب مقتدر. و لولا رهطک لرجمناک و ما أنت علینا بعزیز (قرآن <span class=\"hlight\" dir=\"rtl\">٩١/١١</span>)؛ و اگر قوم و جماعت تو نبودند، هرآینه تو را سنگسار میکردیم وتو بر ما غالب نیستی . و من یهد اﷲ فما له من مضل اءلیس اﷲ بعزیز ذی انتقام (قرآن <span class=\"hlight\" dir=\"rtl\">٣٧/٣٩</span>)؛ و هر کس را خداوند هدایت کند او را گمراه کننده ای نباشد، آیا خداوند غالب و صاحب انتقام نیست ؟<br>پیل باشد عزیز پس همه کس <br>مغزش از آهنی بفرساید.<br> <font color=\"Red\">خاقانی .</font><br>عزیزی  که هر کز درش سر بتافت <br>بهر در که شد هیچ عزت نیافت .<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> سخت . (ترجمان القرآن جرجانی ) <span class=\"hlight\">:</span> اًن یشاء یذهبکم ویأت بخلق جدید و ما ذلک علی اﷲ بعزیز (قرآن <span class=\"hlight\" dir=\"rtl\">١٦/٣٥</span>-<span class=\"hlight\" dir=\"rtl\">١٧</span>)؛ اگر بخواهد شما را از بین میبرد و خلقی تازه و جدید می آورد و آن بر خداوند سخت و دشوار نیست . <BR><font color=\"Blue\">◄</font> در علم حدیث، حدیثی است به روایت یکی از روات، که بروایت او دو یا سه کس منفرد شده باشند. (از نفائس الفنون ص <span class=\"hlight\" dir=\"rtl\">١٣٩</span>). در تعریف آن بین محدثان اختلاف است، برخی را عقیده بر این است که آن حدیثی است که دویا سه تن روایت کنند، بدین ترتیب بین آن و بین مشهور، عموم من وجه است، چه مشهور آن است که بیش از دو تن روایت کرده باشند. و برخی گویند آن است که حداقل دوتن از دو تن روایت کرده باشند. و بعضی گویند عزیز آن حدیثی است که دو یا سه تن از کسی که عدالتش مورد اجماع باشد روایت کرده باشند و بدین ترتیب آن در عدد رجال و اشاعه پایین تر از مشهور میباشد، چه مشهور آن است که جماعتی که به حد تواتر نرسد آن را از کسی نقل کنند که عدالت او مورد اجماع باشد. (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> (اِ) پادشاه، از جهت غالب بودن وی بر اهل مملکتش . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> لقب آنکه پادشاه مصر یا اسکندریه گردد. (منتهی الارب ). لقب آنکه بر مصر و اسکندریه پادشاهی کند. (از اقرب الموارد). لقب پادشاه مصر، به زمانه ٔ قدیم وزیران مصر را عزیز لقب می بود. (غیاث اللغات ). پادشاه مصر را گویند، و پیش از این وزیر مصر را می گفتند. (از آنندراج ). لقب عام ملوک مصر. (آثار الباقیة).<br></font></div>'),
(183127, 'عزیز', '<span class=\"hlight\">عزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) شوهر زلیخا. (آنندراج ). در قرآن کریم، به منزله ٔ صفتی است برای شخصی بنام پوتیفار (معرب، فطیفر) که در دستگاه فرعون معاصر موسی (ع ) بسیار مقتدر و بانفوذ بود. (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> و قال نسوة فی المدینة امراءة العزیز تراود فتاها (قرآن <span class=\"hlight\" dir=\"rtl\">٣٠/١٢</span>)؛ و زنانی در آن شهر گفتند که زن عزیز با غلام خود رفت و آمد میکند. قالت امراءة العزیز الآن حصحص الحق انا راوَدْتُه عن نفسه و اًنه لمن الصادقین (قرآن <span class=\"hlight\" dir=\"rtl\">٥١/١٢</span>)؛ زن عزیز گفت اکنون حق ثابت شد، من برخلاف میل او از وی کامجو شدم و او از راست گویان است . قالوا یا أیها العزیز ان له أباً شیخاً کبیراً (قرآن <span class=\"hlight\" dir=\"rtl\">٧٨/١٢</span>)؛ گفتند ای عزیز او را پدری است مسن و سالخورده .<br>عزیزو قیصر و فغفور را بمان که برت <br>نه شار ماند و نه شیر و نه رای ماند و نه رام .<br> <font color=\"Red\">روحانی .</font><br>من عزیزم مصر حرمت را و این نامحرمان <br>غرزنان برزنند و غرچکان روستا.<br> <font color=\"Red\">خاقانی .</font><br>مصری کلکت چو سحر عرضه کند گاه جود<br>مصر و عزیزش بود بر دل و برچشم خوار.<br> <font color=\"Red\">خاقانی .</font><br>بلکه تا زآن عزیز ری مصراست <br>خوار صد قاهره ست و قاهره خوار.<br> <font color=\"Red\">خاقانی .</font><br>دو امیرزاده در مصر بودند... یکی علامه ٔ عصر گشت و دیگری عزیز مصر شد. (گلستان سعدی ).<br>که در مصر چون من عزیزی نبود.<br><font color=\"Red\">سعدی .</font><br>عزیز مصر چمن شد جمال یوسف گل <br>صبا به شهر درآورد بوی پیرهنش .<br> <font color=\"Red\">سعدی .</font><br>درین زمانه خریدار گشته است عزیز<br>نشسته یوسف ما خوار در دکان تنها.<br><font color=\"Red\">سالک یزدی (از آنندراج ).</font><br></font></div>'),
(183128, 'عزیز', '<span class=\"hlight\">عزیز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مالک بن عوف، از بنی اوس، از قحطانیه . جدی جاهلی است و از نسل او جرول بن مالک بن عمرو را که از صحابیان است میتوان نام برد. (از الاعلام زرکلی از جمهرةالانساب و التاج ).<br></font></div>'),
(183129, 'عزیز الصغیر', '<span class=\"hlight\">عزیز الصغیر.</span> <font color=\"DarkGreen\"><b>[ ع َ زُص ْ ص َ ]</font></b> (ع اِ مرکب ) قنطوریون صغیر است . (تحفه ٔ حکیم مؤمن ). رجوع به قنطوریون شود.<br></font></div>'),
(183130, 'عزیز الکبیر', '<span class=\"hlight\">عزیز الکبیر.</span> <font color=\"DarkGreen\"><b>[ ع َ زُل ْ ک َ ]</font></b> (ع اِ مرکب ) قنطوریون کبیر است . (تحفه ٔ حکیم مؤمن ). رجوع به قنطوریون شود.<br></font></div>'),
(183131, 'عزیز با', '<span class=\"hlight\">عزیز با.</span> <font color=\"DarkGreen\"><b>[ ع َ زی زُ بِل ْ لاه ]</font></b> (اِخ ) (الَ ...) نزاربن معدبن منصور عبیدی فاطمی، مکنی به ابومنصور و ملقب به العزیز باﷲ. صاحب مصر و مغرب . وی به سال <span class=\"hlight\" dir=\"rtl\">٣٤٤</span> هَ .ق . در المهدیة متولد شد و بسال <span class=\"hlight\" dir=\"rtl\">٣٦٥</span> پس از درگذشت پدرش با وی بیعت شد. در عهد او فتنه ها و جنگهایی رخ داد و قصرالبحر و قصرالذهب و جامع القرافة از ساخته های عصر اوست . نزار شخصی نیکواخلاق و بردبار و ادیب و فاضل بود و به سال <span class=\"hlight\" dir=\"rtl\">٣٨٦</span>که به قصد جنگ با رومیان به شهر بلبیس رسیده بود دراین شهر درگذشت . (از الاعلام زرکلی از ابن خلکان و خطط مقریزی و ابن خلدون و بلغة الظرفاء و ابن الاثیر).<br></font></div>'),
(183132, 'عزیز بابدی', '<span class=\"hlight\">عزیز بابدی .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (اِخ ) دهی از بخش میان کنگی شهرستان زابل . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢٨٩</span> تن . آب آن از رودخانه ٔ هیرمند. محصول آن غلات و لبنیات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(183133, 'عزیز داشتن', '<span class=\"hlight\">عزیز داشتن .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (مص مرکب ) گرامی داشتن . ارجمند داشتن . احترام کردن <span class=\"hlight\">:</span> طغرل را گفت شاد باش ای کافرنعمت ازبهر این تو را پروردم و از فرزندان عزیز داشتم تا بر من چنین ساختی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٥٢</span>). مثال نبشت به امیر گوزگانان تا وی را عزیز دارد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٦٤</span>). به روی اندازد دشمنان او را و عزیز دارد دوستان او را. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣١٩</span>).<br>تا به شعر و ادب عزیزت داشت <br>خویش و بیگانه و صغیر و کبیر.<br> <font color=\"Red\">ناصرخسرو.</font><br>من مدح تورا بس عزیز دارم <br>هرچند مرا سخت خوار دارد.<br> <font color=\"Red\">مسعودسعد.</font><br>دانم سخن من عزیز داری <br>داری سخن من عزیز دانم .<br> <font color=\"Red\">مسعودسعد.</font><br>آنچه یابی بشکر باش بشکر<br>وآنچه داری عزیز دار عزیز.<br> <font color=\"Red\">مسعودسعد.</font><br>چو من بنوازم و دارم عزیزش <br>صواب آید که بنوازی تو نیزش .<br> <font color=\"Red\">نظامی .</font><br>کند مرد را نفس اماره خوار<br>اگر هوشمندی عزیزش مدار.<br> <font color=\"Red\">سعدی .</font><br>اگر بنده کوشش کند بنده وار<br>عزیزش بدارد خداوندگار.<br> <font color=\"Red\">سعدی .</font><br>اگر بنده چابک نیاید بکار<br>عزیزش ندارد خداوندگار.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(183134, 'عزیز شدن', '<span class=\"hlight\">عزیز شدن .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ُ دَ ]</font></b> (مص مرکب ) گرامی شدن . ارجمندشدن . اعتزاز. تعزّز. عِزّ. عزازة. عزة <span class=\"hlight\">:</span> <br>تا شوی از جمله ٔ عالم عزیز<br>جهد تو می بایدو توفیق نیز.<br> <font color=\"Red\">نظامی .</font><br>تو آنگه شوی پیش مردم عزیز<br>که مر خویشتن را نگیری به چیز.<br> <font color=\"Red\">سعدی .</font><br>مرا قبول شما نام در جهان رفته ست <br>مرا به صاحب دیوان عزیز شد دیوان .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">میخواهی عزیز شوی، یا دور شو یا کور شو</span> . (امثال و حکم دهخدا).<br><BR><font color=\"Blue\">◄</font> گرانبها شدن . گران شدن <span class=\"hlight\">:</span> نرخها عزیزشد یک من گندم به هشت درم . (تاریخ سیستان ). در این سال بود که نرخها عزیز شد، من گندم به دویست درم نقدشد و جو به صدوهشتاد درم ... همچنان غله عزیز میشد تا منی گندم در ناحیه ٔ سیستان به هزارودویست درم رسمی شد. (تاریخ سیستان ).<br></font></div>'),
(183135, 'عزیز کردن', '<span class=\"hlight\">عزیز کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ دَ ]</font></b> (مص مرکب ) گرامی داشتن . احترام کردن . اعزاز. (فرهنگ فارسی معین ). تعزیز. (از دهار). ارجمندی دادن . عزت دادن <span class=\"hlight\">:</span> <br>عزیز نبود آنکس که تو عزیز کنی <br>زبهر آنکه عزیز تو زود گردد خوار.<br> <font color=\"Red\">ابوحنیفه ٔ اسکافی .</font><br>آنکس که چنین عزیز کردت <br>ازبهر تو کرد گوهر و زر.<br> <font color=\"Red\">ناصرخسرو.</font><br>تا عزیزم مرا عزیز کنی <br>چون شدم خوار خوار انگاری .<br> <font color=\"Red\">خاقانی .</font><br>هر ذلیلی که حق عزیز کند<br>در عزیزیش منکری منگر.<br> <font color=\"Red\">خاقانی .</font><br>هر یکی را کرد اندر سِر عزیز<br>هرچه آن را گفت این را گفت نیز.<br> <font color=\"Red\">مولوی .</font><br>دعائی گر نمیگوئی بدشنامی عزیزم کن <br>که گر تلخست شیرینست از آن لب هرچه فرمائی .<br> <font color=\"Red\">سعدی .</font><br>چو ما را بدنیا تو کردی عزیز<br>به عقبی همین چشم داریم نیز.<br> <font color=\"Red\">سعدی .</font><br>خدای یوسف صدیق را عزیز نکرد<br>به خوبروئی لیکن به خوبکرداری .<br> <font color=\"Red\">سعدی .</font><br>آنکه را کردگار کرد عزیز<br>نتواند زمانه خوار کند.<br> <font color=\"Red\">قاآنی .</font><br>ای خدایت عزیز کرده ز خلق <br>بنده را هست میهمان عزیز.<br><font color=\"Red\">انوری .</font><br></font></div>'),
(183136, 'عزیز گردانیدن', '<span class=\"hlight\">عزیز گردانیدن .</span> <font color=\"DarkGreen\"><b>[ ع َ گ َ دَ ]</font></b> (مص مرکب ) عزیز کردن . گرامی داشتن . اعزاز. رجوع به عزیز و عزیز کردن و عزیز داشتن شود.<br></font></div>'),
(183137, 'عزیز گشتن', '<span class=\"hlight\">عزیز گشتن .</span> <font color=\"DarkGreen\"><b>[ ع َ گ َ ت َ ]</font></b> (مص مرکب ) عزیز شدن . ارجمند شدن <span class=\"hlight\">:</span> <br>گر سوی من آئی عزیز گردی <br>پیوسته بود با تو قیل و قالم .<br><font color=\"Red\">ناصرخسرو.</font><br>به چل سال باید که گردد عزیز.<br> <font color=\"Red\">سعدی .</font><br>مناعة؛ عزیز گشتن . (منتهی الارب ). رجوع به عزیز و عزیز شدن شود.<br></font></div>'),
(183138, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان سیلاخور بخش الیگودرز شهرستان بروجرد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٣١٤</span> تن . آب آن از قنات و چاه . محصول آن غلات، پنبه، انگور و چغندر است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(183139, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان آتش بیک بخش سراسکند شهرستان تبریز. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٣١٦</span> تن . آب آن از چشمه و رودخانه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(183140, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان خدابنده لو از بخش صحنه ٔ شهرستان کرمانشاه . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٧٠</span> تن . آب آن از چشمه . محصول آن غلات و میوه و حبوب است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(183141, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان رومشکان بخش طرهان شهرستان خرم آباد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٨٠</span> تن . آب آن از چاه . محصول آن غلات و لبنیات و پشم است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(183142, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان سملقان بخش مانه ٔ شهرستان بجنورد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢١٢</span> تن . آب آن از قنات . محصول آن غلات، بنشن، پنبه، برنج و میوه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183143, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان چهاردولی بخش اسدآباد شهرستان همدان . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٣١</span> تن . آب آن از قنات . محصول آن غلات و لبنیات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(183144, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) دهی جزء دهستان فشافویه از بخش ری شهرستان تهران . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٢١</span> تن . آب آن از قنات . محصول آن غلات و باغات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(183145, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان میربیگ بخش دلفان شهرستان خرم آباد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن . آب آن از چشمه ٔ شنهابار. محصول آن غلات و لبنیات و پشم است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(183146, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از بخش راور شهرستان کرمان . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٦٠٠</span> تن . آب آن از قنات . محصول آن غلات و پسته است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(183147, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی جزء دهستان فراهان بالا از بخش فرمهین شهرستان اراک . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٧٧٠</span> تن . آب آن از قنات . محصول آن بنشن و پنبه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(183148, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان نورعلی بخش دلفان شهرستان خرم آباد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> تن . آب آن از چشمه ها. محصول آن غلات، توتون، لبنیات و پشم است . ساکنان این ده از طایفه ٔنورعلی می باشند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(183149, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان دیناران بخش اردل شهرستان شهرکرد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٣٩</span> تن . آب آن از رودخانه ٔ غراب . محصول آن غلات و برنج و روغن است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(183150, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان گوکلان بخش مرکزی شهرستان گنبد قابوس . نام اصلی آن کُروک است . رجوع به کروک و فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span> شود.<br></font></div>'),
(183151, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی جزء دهستان بهنام وسط بخش ورامین شهرستان تهران . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٣٣٢</span> تن . آب آن از قنات . محصول آن غلات و صیفی و چغندرقند است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(183152, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) دهی از دهستان کنارشهر بخش بردسکن شهرستان کاشمر. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٩٧</span> تن . آب آن از قنات . محصول آن غلات و پنبه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183153, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان خورخوره ٔ بخش دیواندره ٔ شهرستان سنندج . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١١٥</span> تن . آب آن از چشمه . محصول آن غلات و حبوب است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(183154, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان دینور بخش صحنه ٔ شهرستان کرمانشاه . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٧٠</span> تن . آب آن از رودخانه ٔ کنگرشاه . محصول آن غلات، حبوب، چغندرقند و توتون است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(183155, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) مرکز دهستان عزیزآباد بخش فهرج شهرستان بم . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٥٨٦</span> تن . آب آن از قنات . محصول آن غلات، خرما، حنا و لبنیات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(183156, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان کرون بخش نجف آباد شهرستان اصفهان . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٤٦٢</span> تن . آب آن از قنات . محصول آن غلات، بادام، صیفی، انگور، سیب زمینی و گردو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(183157, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) یکی از دهستانهای شش گانه ٔ بخش فهرج شهرستان بم . این دهستان در جنوب باختری فهرج واقع، و حدود آن به شرح زیر است : از شمال به دهستان پشت رود، از خاور به دهستان برج اکرم، از جنوب به دهستان عزیزآباد گنبکی و شهرستان جیرفت، از باختر به دهستان رودآب . هوای دهستان گرمسیر است و آب قرای آن از قنوات تأمین میشود. محصول عمده ٔ این دهستان غلات، حنا، پنبه، خرما، لبنیات و انواع مرکبات است . این دهستان از <span class=\"hlight\" dir=\"rtl\">٢٢</span> آبادی بزرگ و کوچک تشکیل شده و جمعیت آن در حدود <span class=\"hlight\" dir=\"rtl\">٥٣٠٠</span> تن است و مرکز دهستان قصبه ٔ عزیزآباد است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(183158, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان عشق آباد بخش فدیشه ٔ شهرستان نیشابور. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٧٤</span>تن . آب آن از قنات . محصول آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183159, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان کاغه ٔ بخش دورودشهرستان بروجرد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٢٧</span> تن . آب آن از قنات . محصول آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(183160, 'عزیزآباد', '<span class=\"hlight\">عزیزآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از بخش ارکواز شهرستان ایلام . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٩٠</span> تن . آب آن از چشمه . محصول آن غلات و لبنیات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(183161, 'عزیزآباد سرمزار', '<span class=\"hlight\">عزیزآباد سرمزار.</span> <font color=\"DarkGreen\"><b>[ ع َ دِ س َ م َ ]</font></b> (اِخ ) دهی از دهستان کیذقان بخش ششتمد شهرستان سبزوار. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٤٩٧</span> تن . آب آن از قنات . محصول آن غلات، پنبه، بادام و بنشن است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183162, 'عزیزالدولة', '<span class=\"hlight\">عزیزالدولة.</span> <font color=\"DarkGreen\"><b>[ع َ زُدْ دَ ل َ ]</font></b> (اِخ ) فاتک بن عبداﷲ رومی، مکنی به ابوشجاع و ملقب به عزیزالدوله . از مأموران الحاکم بامر اﷲ فاطمی . رجوع به فاتک و به الاعلام زرکلی شود.<br></font></div>'),
(183163, 'عزیزالدین', '<span class=\"hlight\">عزیزالدین .</span> <font color=\"DarkGreen\"><b>[ ع َ زُدْ دی ]</font></b> (اِخ ) احمدبن حامدبن محمدبن عبداﷲ، مکنی به ابونصر. عم عمادکاتب اصفهانی . رجوع به احمد (ابن حامدبن ...) شود.<br></font></div>'),
(183164, 'عزیزالنفس', '<span class=\"hlight\">عزیزالنفس .</span> <font color=\"DarkGreen\"><b>[ ع َ زُن ْ ن َ ]</font></b> (ع ص مرکب ) دارنده ٔ نفسی عزیز و ابی . بامناعت . رجوع به عزیزنفس شود.<br></font></div>'),
(183165, 'عزیزالوجود', '<span class=\"hlight\">عزیزالوجود.</span> <font color=\"DarkGreen\"><b>[ ع َ زُل ْ وُ ]</font></b> (ع ص مرکب ) کمیاب و نادر. (ناظم الاطباء).<br></font></div>'),
(183166, 'عزیزاوان', '<span class=\"hlight\">عزیزاوان .</span> <font color=\"DarkGreen\"><b>[ ع ُ زَ ]</font></b> (ع اِ) تثنیه ٔ عُزَیزاء. (منتهی الارب ) (از اقرب الموارد). رجوع به عزیزاء شود.<br></font></div>'),
(183167, 'عزیزخان', '<span class=\"hlight\">عزیزخان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از بخش گوران شهرستان شاه آباد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٦٠</span> تن . آب آن از رودخانه ٔ شاهمار. محصول آن غلات، مختصری حبوب، توتون، صیفی و لبنیات است .نام اصلی این ده بان زلان است ولی بنام کدخدای محل عزیزخان مشهور است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(183168, 'عزیزخان', '<span class=\"hlight\">عزیزخان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان منگره ٔ بخش اندیمشک شهرستان دزفول . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن . آب آن از چشمه . محصول آن غلات و انار و انجیر است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(183169, 'عزیزخور', '<span class=\"hlight\">عزیزخور.</span> <font color=\"DarkGreen\"><b>[ ع َ خوَرْ<span class=\"hlight\" dir=\"rtl\">/</span> خُرْ ]</font></b> (نف مرکب ) خورنده ٔ عزیز. که گرامی و ارجمندی را از میان بردارد و بخورد و فروبرد <span class=\"hlight\">:</span> <br>وی خاک عزیزخور به خواری <br>تن را عوض از جفات جویم .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(183170, 'عزیزداشت', '<span class=\"hlight\">عزیزداشت .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (مص مرکب مرخم، اِمص مرکب ) عزیز داشتن . گرامی داشتن <span class=\"hlight\">:</span> گفت تا ایشان را فرودآورند و آنچه عزیزداشت و شرط مراقبت حرمت پادشاه باشد بجای آرند. (تاریخ طبرستان ). و رجوع به عزیز داشتن و عزیز شود.<br></font></div>'),
(183171, 'عزیزدردانه', '<span class=\"hlight\">عزیزدردانه .</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص مرکب ) بطر. سخت گرامی و عزیز. (یادداشت مرحوم دهخدا). در تداول عامه، کسی که والدین و اقوام او بیش از حد وی را مورد محبت و نوازش قرار دهند. (فرهنگ فارسی معین ). بچه ٔ خیلی عزیز و مورد محبت پدر و مادر. (فرهنگ عوام ): عزیزدردانه، یکی یه دانه . <BR><font color=\"Blue\">◄</font> توسعاً، لوس . ننر.<br></font></div>'),
(183172, 'عزیزمرده', '<span class=\"hlight\">عزیزمرده .</span> <font color=\"DarkGreen\"><b>[ ع َ م ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ص مرکب ) که گرامی فرزندی یا خویشی ازو مرده باشد. کسی که دوست یا عزیز و خویش او بمیرد. (آنندراج ). <BR><font color=\"Blue\">◄</font> در تداول مردم قزوین، نفرینی که زنان کنند. نفرینی است مترادف «صاحب مرده »، و این دعای بد است که در ولایت رواج دارد وظاهراً مقوله ٔ زنان است . (از آنندراج ) <span class=\"hlight\">:</span> <br>ز فوت مال ندارند عاشقان پروا<br>عزیزمرده دعائی بودزلیخا را.<br><font color=\"Red\">مخلص کاشی (از آنندراج ).</font><br></font></div>'),
(183173, 'عزیزنفس', '<span class=\"hlight\">عزیزنفس .</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ ]</font></b> (ص مرکب ) عزیزالنفس .دارنده ٔ نفسی عزیز و ارجمند. با مناعت <span class=\"hlight\">:</span> <br>فرزند گوهری را عز از نسب نباشد<br>عیسی عزیزنفس است ارچه پدر ندارد.<br> <font color=\"Red\">سیف اسفرنگ .</font><br>و رجوع به عزیزالنفس شود.<br></font></div>'),
(183174, 'عزیزوار', '<span class=\"hlight\">عزیزوار.</span> <font color=\"DarkGreen\"><b>[ ع َ زیزْ ]</font></b> (ق مرکب ) عزیزسان . گرامی وار. همانند مردم ارجمند <span class=\"hlight\">:</span> <br>من داشته ام عزیزوارش <br>تو نیز چو من عزیز دارش .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(183175, 'عزیزک', '<span class=\"hlight\">عزیزک .</span> <font color=\"DarkGreen\"><b>[ ع َ زی زَ ]</font></b> (اِخ ) دهی از دهستان بانصر بخش بابلسر شهرستان بابل . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١١٨٥</span> تن . آب آن از رودخانه ٔ بابل . محصول آن برنج، پنبه، صیفی، مختصری غلات، کنف و کنجد است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(183176, 'عزیزکند', '<span class=\"hlight\">عزیزکند.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) دهی از دهستان آختاچی بخش حومه ٔ شهرستان مهاباد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٣٥٨</span> تن . آب آن از چشمه . محصول آن غلات و توتون و حبوبات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(183177, 'عزیزکندی', '<span class=\"hlight\">عزیزکندی .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) دهی از بخش سراسکند شهرستان تبریز. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١١٧</span> تن . آب آن از چشمه و رودخانه . محصول آن غلات و حبوبات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(183178, 'عزیزگرامی', '<span class=\"hlight\">عزیزگرامی .</span> <font color=\"DarkGreen\"><b>[ ع َ گ ِ ]</font></b> (ص مرکب ) سوگلی . (یادداشت مرحوم دهخدا). عزیزدردانه . عزیز و گرامی . رجوع به «عزیز» و «گرامی » شود.<br></font></div>'),
(183179, 'عزیزی', '<span class=\"hlight\">عزیزی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (حامص ) عزت . گرامی بودن . ارجمندی . احترام . (از فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>هر ذلیلی که حق عزیز کند<br>در عزیزیش منکری منگر.<br> <font color=\"Red\">خاقانی .</font><br>و اما دلیل بر عزیزی و گرامیی دانش آنکه دانش در سرشت ماست و تمام کننده ٔ ما اوست . (مصنفات باباافضل از فرهنگ فارسی معین ).<br>عزیزی خواری و خواری عزیزی بار می آرد<br>در آغوش پدر از چاه و زندان بیش میلرزم .<br> <font color=\"Red\">صائب .</font><br>- <span class=\"hlight\">به عزیزی </span> ؛ به عزت . معزز. قرین ارجمندی <span class=\"hlight\">:</span> هر دوپسرش را خلعت داد و به عزیزی بخانه بازفرستاد. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٦٢٥</span>).<br></font></div>'),
(183180, 'عزیزی', '<span class=\"hlight\">عزیزی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) لقب علی بن احمدبن محمدبن ابراهیم عزیزی، فقیه و محدث قرن یازدهم هجری است . رجوع به علی عزیزی شود.<br></font></div>'),
(183181, 'عزیزی', '<span class=\"hlight\">عزیزی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) فرزند عبدالملک بن منصور جیلی، مکنی به ابوالمعالی و مشهور به شیذلة. واعظ و از فقهای شافعی مذهب در قرن پنجم هجری و از اهالی جیلان بود و مدتی سمت قضاء را در بغداد بعهده داشت و به سال <span class=\"hlight\" dir=\"rtl\">٤٩٤</span> هَ .ق . در همین شهر درگذشت . او راست : البرهان فی مشکلات القرآن، دیوان الانس، لوامع أنوار القلوب . (از الاعلام زرکلی از وفیات الاعیان و هدیة العارفین و خزائن الاوقاف ).<br></font></div>'),
(183182, 'عزیزی', '<span class=\"hlight\">عزیزی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب به عزیز. رجوع به عزیز شود.<br></font></div>'),
(183183, 'عزیزی', '<span class=\"hlight\">عزیزی .</span> <font color=\"DarkGreen\"><b>[ ع ُ زَ زا ]</font></b> (ع اِ) سرین اسب و طرف آن . (منتهی الارب ).عُزیزاء. (از اقرب الموارد). رجوع به عزیزاء شود.<br></font></div>'),
(183184, 'عزیزی', '<span class=\"hlight\">عزیزی .</span> <font color=\"DarkGreen\"><b>[ ع ُ زَ ]</font></b> (اِخ ) لقب محمدبن عزیز سجستانی عزیزی، مکنی به ابوبکر مفسر است . شهرت او بیشتر بواسطه ٔ کتاب «غریب القرآن » اوست که آن را بترتیب حروف معجم در مدت پانزده سال تصنیف کرده است . اقامت او در بغداد بود و نام پدرش را عزیر به راء مهمله نیز نقل کرده اند. (از اعلام زرکلی از سیرالنبلاء).<br></font></div>'),
(183185, 'عزیزی', '<span class=\"hlight\">عزیزی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان بویراحمد سرحدی بخش کهکیلویه ٔ شهرستان بهبهان . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن . آب آن از چشمه و رودخانه . محصول آن غلات و پشم و لبنیات است . این آبادی را زی زی هم می نامند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(183186, 'عزیزی', '<span class=\"hlight\">عزیزی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) لقب علی بن علی بن علی بن علی بن مطاوع عزیزی، فقیه قرن دوازدهم هجری است . رجوع به علی عزیزی شود.<br></font></div>'),
(183187, 'عزیزی', '<span class=\"hlight\">عزیزی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) تیره ای از شعبه ٔ جباره ٔ ایل عرب، از ایلات خمسه ٔ فارس . (از جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٨٧</span>).<br></font></div>'),
(183188, 'عزیزیان', '<span class=\"hlight\">عزیزیان .</span> <font color=\"DarkGreen\"><b>[ ع ُ زَ زَ ]</font></b> (ع اِ) تثنیه ٔ عُزَیْزی ̍. (منتهی الارب ) (اقرب الموارد). رجوع به عزیزاء و عزیزی شود.<br></font></div>'),
(183189, 'عزیزیان', '<span class=\"hlight\">عزیزیان .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) نام خاندانی قدیم به ناحیت بیهق، و آنان دوگروه بودند، یکی علویان که رهط ایشان را عزیزی خوانند و دیگر عزیزیان که فرزندان عزیزبن مغیرةبن عبدالرحمان بن عوف صاحب رسول اﷲ (ص ) باشند، و اصل ایشان از علی بن حسین بن علی عزیز است . (از تاریخ بیهق ص <span class=\"hlight\" dir=\"rtl\">١١٩</span>).<br></font></div>'),
(183190, 'عزیزیة', '<span class=\"hlight\">عزیزیة.</span> <font color=\"DarkGreen\"><b>[ ع َ زی ی َ ]</font></b> (اِخ ) نام پنج قریه است در مصر، منسوب به عزیزبن معز ملک مصر. (از معجم البلدان ).<br></font></div>'),
(183191, 'عزیف', '<span class=\"hlight\">عزیف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) آواز پری و آن آواز خفی و پستی است که به شب در بیابان شنیده شود و گویندآن صوت بادها در جو است که اهل بادیه آن را صوت جن تصور کنند. (از منتهی الارب ). صوت جن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> توسعاً، مطلق آواز یا آواز که از چیزی برآید <span class=\"hlight\">:</span> آواز تکبیر از صف سلطان و عزیف مزمار و صفیر از قبل آن شیطان ... (جهانگشای جوینی ).<br></font></div>'),
(183192, 'عزیف', '<span class=\"hlight\">عزیف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) آواز کردن جن . (از منتهی الارب ). بانگ کردن . (تاج المصادر بیهقی ): عزفت الجن ؛ جن در بیابانها آواز داد. <BR><font color=\"Blue\">◄</font> بازی کردن جن . <BR><font color=\"Blue\">◄</font> بانگ دادن کمان . (از اقرب الموارد). عَزف . و رجوع به عزف شود.<br></font></div>'),
(183193, 'عزیف', '<span class=\"hlight\">عزیف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام رملی است در عینة از آن بنی سعد. (از معجم البلدان ).<br></font></div>'),
(183194, 'عزیق', '<span class=\"hlight\">عزیق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) زمین نرم و هموار و پست . (منتهی الارب ). زمین مطمئن، و آن لغتی است یمانی . (از اقرب الموارد).<br></font></div>'),
(183195, 'عزیقه', '<span class=\"hlight\">عزیقه .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) شهری است در یهودا در نزدیکی شوکره، که بعضی بر آنند که همان تل زکریه میباشد، و دیگران بر آنند که همان دیرالسوشک است که بمسافت <span class=\"hlight\" dir=\"rtl\">٨</span> میل در شمال شوکره واقع است . (قاموس کتاب مقدس ).<br></font></div>'),
(183196, 'عزیلة', '<span class=\"hlight\">عزیلة.</span> <font color=\"DarkGreen\"><b>[ ع ُ زَ ل َ ]</font></b> (اِخ ) نام موضعی است . (از منتهی الارب ) (از معجم البلدان ).<br></font></div>'),
(183197, 'عزیم', '<span class=\"hlight\">عزیم .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) آهنگ نمودن بر امر و دل نهادن . کوشش کردن . (از منتهی الارب ). عزم <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ]</font></b> . معزم <font color=\"DarkGreen\"><b>[ م َزَ <span class=\"hlight\" dir=\"rtl\">/</span> م َ زِ ]</font></b> . عُزمان . عَزیمة. رجوع به عزم شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(183198, 'عزیم', '<span class=\"hlight\">عزیم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) دشمن سخت وقوی . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) ج ِ عزیمة. (منتهی الارب ). رجوع به عزیمة شود.<br></font></div>'),
(183199, 'عزیمة', '<span class=\"hlight\">عزیمة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع مص ) آهنگ نمودن بر امر و دل نهادن و کوشش کردن . (از منتهی الارب ). دل بر کاری نهادن . (تاج المصادر بیهقی ) (ترجمان القرآن جرجانی ). عزم <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ]</font></b> . عَزیم . معزم <font color=\"DarkGreen\"><b>[ م َ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> . عُزمان . و رجوع به عَزم شود.<br></font></div>'),
(183200, 'عزیمة', '<span class=\"hlight\">عزیمة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع اِمص، اِ) اراده ٔ مؤکد.(از اقرب الموارد) (از تعریفات جرجانی ). صریمة. مَریر. مریرة <font color=\"DarkGreen\"><b>[ م َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> م ِرْ ری رَ ]</font></b> . اندیشه . آهنگ . عزیمت . رجوع به عزیمت شود. <BR><font color=\"Blue\">◄</font> تعویذ. (ناظم الاطباء). رقیة. (اقرب الموارد). افسون . (دهار). عزیمت . رجوع به عزیمت شود. <BR><font color=\"Blue\">◄</font> آیه ای از قرآن مجید که بر آفت رسیده به امید به شدن میخوانند. (ناظم الاطباء). ج، عَزائم (اقرب الموارد)، عَزیم . (ناظم الاطباء). رجوع به عزائم شود. <BR><font color=\"Blue\">◄</font> (اصطلاح اصول ) لفظی است که در برابر رخصت ایراد شود و آن شامل فرض و واجب و سنت و نفل و مباح و حرام و مکروه باشد. و برخی گفته اند فقط شامل فرض و واجب و حرام و مکروه است، زیرا سنت برای تکمیل فرایض و تبع آن وضع شده و همچنین نفل برای جبران نقص در تمکن عزیمت وضع گردیده، و آن فرض باشد. (از کشاف اصطلاحات الفنون ). احکام کلی است که ابتدا مشروع شده است، و مخصوص به بعضی از مکلفان دون بعضی دیگر، یا حالی دون حالی نمی باشد مانند نماز و روزه . (از فرهنگ علوم عقلی از موافقات ). اسم است آنچه را اصل مشروعات باشد بدون تعلق به عوارض . (از تعریفات جرجانی ). <BR><font color=\"Blue\">◄</font> (اصطلاح فلسفه ) اراده ٔ مؤکده است که اجماع نامیده میشود. (از فرهنگ علوم عقلی ). رجوع به اجماع شود. <BR><font color=\"Blue\">◄</font> (اصطلاح حقوق ) آنچه قانوناً افراد ملزم به ارتکاب آن هستند، در برابر رخصت که ارتکاب آن بسبب عذر قانونی مجاز باشد. و آن را در حقوق جدید با اصطلاح تکلیف  بیان میکنند. (از فرهنگ حقوقی ).<br></font></div>'),
(183201, 'عزیمت', '<span class=\"hlight\">عزیمت .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع، اِمص، اِ) عزیمة. دل نهادگی و قصد و آهنگ . (غیاث اللغات ). اراده و نیت و عزم . آهنگ از روی استواری و بطور جزم . (ناظم الاطباء). تصمیم . رجوع به عزیمة شود <span class=\"hlight\">:</span> ما امیرالمؤمنین را از عزیمت خویش آگاه کردیم و عهد خراسان و جمله مملکت پدر را بخواستیم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٣٢</span>). آنکه مددکار باشد او رادر عزیمتهاش . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣١٣</span>). عزیمت ما بر آن قرار گرفت که خواجه ٔ عمید بوسهل حمدوی را با فوجی لشکر قوی و مقدمی فرستاده آید. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٠٥</span>).<br>بیشتر کن عزیمت چون برق <br>در زمانه فکن چو رعد آواز.<br> <font color=\"Red\">مسعودسعد.</font><br>در عالم شیر عزیمت تو<br>چون چرخ دوصد مرغزار دارد.<br> <font color=\"Red\">مسعودسعد.</font><br>بضرورت عزیمت مصمم گشت بر آنکه علمای هر صنف را بینم . (کلیله و دمنه ). اگر رای تو بر این کار مقرر است و عزیمت در امضای آن مصمم، باری نیک برحذر باید بود. (کلیله و دمنه ). مرغان ... عزیمت بر توختن کین مصمم گردانیدند. (کلیله و دمنه ). به وقت حضور من نوشته های جماعتی که از ظاهر مرو هزیمت شده بودند برسید از استعداد و عزیمت معاودت حرب اعلامی کرده بودند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٣٩</span>).<br>دل عاشق سکونت پیشه باید<br>عزیمت را نخست اندیشه باید.<br> <font color=\"Red\">اوحدی (ده نامه ).</font><br>- <span class=\"hlight\">فسخ عزیمت </span> ؛ انصراف و بازگشتن از عقیده و تصمیمی . (فرهنگ فارسی معین ).<br> <BR><font color=\"Blue\">◄</font> کوچ و رحلت و روانگی . (ناظم الاطباء).<br>- <span class=\"hlight\">عنان عزیمت </span> ؛ لگام رحلت . (ناظم الاطباء).<br>- <span class=\"hlight\">نقطه ٔ عزیمت </span> ؛ نقطه ای که از آنجا شروع به حرکت کنند. (فرهنگ فارسی معین ).<br> <BR><font color=\"Blue\">◄</font> تعویذ و افسون . (ناظم الاطباء). افسونی که افسونگر خواند. (فرهنگ فارسی معین ). هیپنوتیزم . (یادداشت مرحوم دهخدا). رجوع به عزیمة شود <span class=\"hlight\">:</span> <br>نادان گمان بری و نه آگاهی <br>از تنبل و عزیمت و نیرنگش .<br> <font color=\"Red\">طاهر فضل .</font><br>همگان از وی <font color=\"DarkGreen\"><b>[ جمشید ]</font></b> نفور شدند و عزیمتها که دیوان را بدان بسته بود گشاده شد. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٣٣</span>).<br>هَجْوَم عزیمت است که آن دیوزاده را<br>برخواندنی زبون و مسخر همی کنم <br>تا سر بخط نیارد و نَدْهد به بند دست <br>هر ساعتی عزیمتش از سر همی کنم .<br> <font color=\"Red\">سوزنی .</font><br>آمد آن مار اجل هیچ عزیمت دانید<br>که بخوانید و بدان مار فسائید همه .<br> <font color=\"Red\">خاقانی .</font><br>این عزیمت چو بشر بر وی خواند<br>هم در آن دیو بوالفضولی ماند.<br> <font color=\"Red\">نظامی .</font><br>چون مخبط شد اعتدال مزاج <br>نه عزیمت اثر کند نه علاج .<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> (اصطلاح اصول ) مقابل رخصت است . اجماع . رجوع به عزیمة شود <span class=\"hlight\">:</span> قدم بر جاده ٔ شریعت و استقامت امر و نهی می باید نهادو عمل به عزیمت و سنت می باید کرد و از رخصت و بدعت دور می باید بود. (انیس الطالبین بخاری ).<br></font></div>'),
(183202, 'عزیمت کردن', '<span class=\"hlight\">عزیمت کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ک َ دَ ]</font></b> (مص مرکب ) اراده کردن و قصد نمودن و نیت کردن . (ناظم الاطباء). آهنگ کردن . عزم کردن . مصمم شدن . عازم شدن . رجوع به عزیمت و عزیمة شود <span class=\"hlight\">:</span> <br>چو تو عزیمت پیکار و قصد رزم کنی <br>روند با تو برابر دو لشکر آتش و آب .<br> <font color=\"Red\">مسعودسعد.</font><br>روزی عزیمت خدمت ایشان کردم . (مجالس سعدی ). <BR><font color=\"Blue\">◄</font> آهنگ سفر کردن و کوچ کردن . (ناظم الاطباء). کوچ کردن . حرکت کردن . سفر کردن . (فرهنگ فارسی معین ).<br></font></div>'),
(183203, 'عزیمت گر', '<span class=\"hlight\">عزیمت گر.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ گ َ ]</font></b> (ص مرکب ) افسون خوان . تعویذخوان <span class=\"hlight\">:</span> <br>عقل عزیمت گر ما دیو دید<br>نقره ٔ آن کار به آهن کشید.<br> <font color=\"Red\">نظامی .</font><br>و رجوع به عزیمت و عزیمة شود.<br></font></div>'),
(183204, 'عزیمه', '<span class=\"hlight\">عزیمه .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (از ع، اِ) عزیمة. عزیمت . تعویذ و افسون . (ناظم الاطباء). رجوع به عزیمة و عزیمت شود. <BR><font color=\"Blue\">◄</font> آیه ای از قرآن مجید که بر آفت رسیده به امید به شدن خوانند. (ناظم الاطباء). عزیمة. رجوع به عزائم و عزیمة شود.<br></font></div>'),
(183205, 'عزیمه خوان', '<span class=\"hlight\">عزیمه خوان .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) افسون خوان . عزایم خوان . کسانی که مدعی بودند بر اینکه ارواح خبیثه را از اشخاص یا اماکن بواسطه ٔ خواندن عزائم اخراج مینمایند. و از انجیل چنین برمی آید که عده ٔ آنها بسیار بود و قوم را اعتقاد این بود که آنان این صفت را بواسطه ٔ تحصیل و متصف گشتن به صفات سلیمان و استعمال ادویه و بخوربه دست می آورند. (از قاموس کتاب مقدس ). و رجوع به عزیمه و عزیمة و عزیمت و عزائم و عزیمه خواندن شود.<br></font></div>'),
(183206, 'عزیمه خواندن', '<span class=\"hlight\">عزیمه خواندن .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا دَ]</font></b> (مص مرکب ) تعویذ خواندن . افسون خواندن . (ناظم الاطباء). رجوع به عزیمة و عزیمه و عزیمت و عزائم شود.<br></font></div>'),
(183207, 'عزیمه کردن', '<span class=\"hlight\">عزیمه کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ک َ دَ ]</font></b> (مص مرکب ) افسون کردن و جادوی کردن و بکار بردن جادوی را. (از ناظم الاطباء). رجوع به عزیمة و عزیمه و عزیمت و عزائم شود.<br></font></div>'),
(183208, 'عزین', '<span class=\"hlight\">عزین .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ عِزة در حال نصب و جر. گروه مجتمع از مردم . عِزون . رجوع به عِزَة و عزون شود <span class=\"hlight\">:</span> عن الیمین و عن الشمال عزین (قرآن <span class=\"hlight\" dir=\"rtl\">٣٧/٧٠</span>)؛ از راست و از چپ متفرقند.<br></font></div>'),
(183209, 'عزین آباد', '<span class=\"hlight\">عزین آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )دهی از دهستان کیلخواران بخش مرکزی شهرستان شاهی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٦٠</span> تن . آب آن از چاه . محصول آن پنبه، غلات، کنجد و صیفی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(183210, 'عس', '<span class=\"hlight\">عس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) زرنیخ است . (فهرست مخزن الادویة).<br></font></div>'),
(183211, 'عس', '<span class=\"hlight\">عس .</span> <font color=\"DarkGreen\"><b>[ ع َس س ]</font></b> (ع مص ) به شب گردیدن به پاسبانی . (از منتهی الارب ). بشب گشتن ازبرای احتراز از دزدان . (تاج المصادر بیهقی ) (دهار) (از المصادر زوزنی ). طواف کردن درشب برای حفظ و حراست مردمان و یافتن اشخاص مشکوک . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> برآمدن  خبر کسی . (از منتهی الارب ): عس خبره ؛ خبر او دیر آمد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چیزاندک خورانیدن قوم را. (از منتهی الارب ). طعامی سبک دادن کسی را. (از تاج المصادر بیهقی ) (از دهار): عس القوم ؛ قوم را طعامی اندک خورانید. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تنها چریدن ناقه . (از منتهی الارب ) (از اقرب الموارد). تنها چرا کردن شتر. (تاج المصادر بیهقی ) (از دهار). <BR><font color=\"Blue\">◄</font> شیر نادادن ناقه پیش کسی . (از منتهی الارب ). عَسَس . و رجوع به عسس شود.<br></font></div>'),
(183212, 'عس', '<span class=\"hlight\">عس .</span> <font color=\"DarkGreen\"><b>[ ع َس س ]</font></b> (ع اِ) گویند: جی ٔ بالمال من عسک و بسک ؛ یعنی با جد و جهدخود، و آن لغتی است در «حسک ». (از منتهی الارب ): جاءبه من عسه و بسه ؛ یعنی آن را از جائی که بود و نبودآورد، و این دو از اتباع هستند و از هم جدا نمی گردند. (از اقرب الموارد). و رجوع به حَس ّ و عَش ّ شود.<br></font></div>'),
(183213, 'عس', '<span class=\"hlight\">عس .</span> <font color=\"DarkGreen\"><b>[ ع َ سِن ْ ]</font></b> (ع ص ) سزاوار و خلیق . (از منتهی الارب )(از اقرب الموارد). عَسی . عسی ّ. رجوع به عسی شود.<br></font></div>'),
(183214, 'عس', '<span class=\"hlight\">عس .</span> <font color=\"DarkGreen\"><b>[ ع ُس س ]</font></b> (ع اِ) کاسه ٔ بزرگ . (منتهی الارب ). قدح بزرگ . (آنندراج ) (غیاث اللغات ). قدح بزرگ، و رَفد از آن بزرگتر است . ج، عِساس، عِسَسة، أعساس . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ذکر و نره . (از ناظم الاطباء) (از منتهی الارب ).<br></font></div>'),
(183215, 'عسا', '<span class=\"hlight\">عسا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِ) ملج است، و کشوث را نیز نامند. (فهرست مخزن الادویة).<br></font></div>'),
(183216, 'عساب', '<span class=\"hlight\">عساب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) جایگاهی است به نزدیکی مکه، و نام آن در شعر فضل بن عباس بن عتبةبن ابی لهب آمده است . (از معجم البلدان ).<br></font></div>'),
(183217, 'عسابر', '<span class=\"hlight\">عسابر.</span> <font color=\"DarkGreen\"><b>[ ع َ ب ِ ]</font></b> (ع اِ) ج ِ عُسبُر. (اقرب الموارد). رجوع به عسبر شود.<br></font></div>'),
(183218, 'عساجر', '<span class=\"hlight\">عساجر.</span> <font color=\"DarkGreen\"><b>[ ع َ ج ِ ]</font></b> (ع اِ)ج ِ عَیسَجور. (ناظم الاطباء). رجوع به عیسجور شود.<br></font></div>'),
(183219, 'عسار', '<span class=\"hlight\">عسار.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِمص ) درویشی و تنگدستی . (غیاث اللغات ) (آنندراج ). مفلسی و درویشی و زهد و تنگدستی . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ) ذهب است . (فهرست مخزن الادویة).<br></font></div>'),
(183220, 'عسارت', '<span class=\"hlight\">عسارت .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِمص ) عسارة. مسکنت و درویشی و فقر و عیلت وبؤس . (یادداشت مرحوم دهخدا). رجوع به عسارة شود.<br></font></div>'),
(183221, 'عسارو', '<span class=\"hlight\">عسارو.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) ذهب است . (فهرست مخزن الادویة).<br></font></div>'),
(183222, 'عساری', '<span class=\"hlight\">عساری .</span> <font color=\"DarkGreen\"><b>[ ع ُ را ]</font></b> (ع ص، ق ) بر اثر یکدیگر: جاؤوا عساری ؛ بر اثر یکدیگر آمدند. (از منتهی الارب ) (از اقرب الموارد). عساریات . و رجوع به عساریات شود.<br></font></div>'),
(183223, 'عساریات', '<span class=\"hlight\">عساریات .</span><font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (ع ص، ق ) بر اثر یکدیگر: جاؤوا عساریات ؛بر اثر یکدیگر آمدند. (از منتهی الارب ) (از اقرب الموارد). عُساری ̍. و رجوع به عساری شود. <BR><font color=\"Blue\">◄</font> پراکنده و پریشان : ذهبوا عساریات ؛ رفتند پراکنده و پریشان . (از منتهی الارب ). یعنی رفتند در حالی که در هر راهی متفرق و پراکنده بودند. (از اقرب الموارد).<br></font></div>'),
(183224, 'عساس', '<span class=\"hlight\">عساس .</span> <font color=\"DarkGreen\"><b>[ ع َس ْ سا ]</font></b> (ع ص ) وزن فعال است مبالغه را. بسیار طواف کننده در شب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) گرگ . (منتهی الارب ). ذئب، چه او در شب میگردد و جستجو میکند. (از اقرب الموارد).<br></font></div>'),
(183225, 'عساس', '<span class=\"hlight\">عساس .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) اکراه و اجبار: درّت الناقة عساساً؛ آن ماده شتر با اکراه شیر داد. (از اقرب الموارد) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ج ِ عُس ّ. (اقرب الموارد) (منتهی الارب ). رجوع به عس ّ شود.<br>- <span class=\"hlight\">بنی عساس </span> ؛ نام بطنی است از تازیان . (ناظم الاطباء) (از اقرب الموارد).<br></font></div>'),
(183226, 'عساعس', '<span class=\"hlight\">عساعس .</span> <font color=\"DarkGreen\"><b>[ ع َ ع ِ ]</font></b> (ع اِ) ج ِ عَسعَس . (منتهی الارب ). گرگ و خارپشت، بدان جهت که شبگرد میباشند. (آنندراج ). قنافذ است، و آن را بدان نام بجهت آن موسوم نموده اند که در شب رفتار بسیار می نماید. (مخزن الادویة). قنافذ و خارپشتان است بجهت کثرت رفت وآمد آنها در شب، گویی مفرد آن عسعس است . (از اقرب الموارد).<br></font></div>'),
(183227, 'عساف', '<span class=\"hlight\">عساف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) نزدیک به مرگ رسیدن شتر از غده و طاعون، پس لرزیدن ْ گرفتن ِ گلوی آن و دم سخت برآوردن بشتاب . (از منتهی الارب ) (از ناظم الاطباء). عُسوف . عُسوفة. رجوع به عسوف و عسوفة شود.<br></font></div>'),
(183228, 'عساف', '<span class=\"hlight\">عساف .</span> <font color=\"DarkGreen\"><b>[ ع َس ْ سا ]</font></b> (ع ص ) سخت گیرنده . (ناظم الاطباء). شدیدالعسف، یعنی سخت ظلم و ستم . (از اقرب الموارد).<br></font></div>'),
(183229, 'عساف', '<span class=\"hlight\">عساف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) ناقه ٔ طاعون زده .(منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِمص ) بیماریی است که شتران را از غده دچار میشود، و گویند آن هنگامی است که حنجره ٔ شتر از نفس کشیدن بلرزد، و آن در شتر مانند نزع است در انسان . (از اقرب الموارد).<br></font></div>'),
(183230, 'عساقب', '<span class=\"hlight\">عساقب .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ]</font></b> (ع اِ) ج ِ عِسْقِبة.(منتهی الارب ) (اقرب الموارد). رجوع به عسقبة شود.<br></font></div>'),
(183231, 'عساقل', '<span class=\"hlight\">عساقل .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ]</font></b> (ع اِ)ج ِ عَسقَل . (اقرب الموارد) (ناظم الاطباء). رجوع به عسقل شود. <BR><font color=\"Blue\">◄</font> پاره های ابر جداگانه . (منتهی الارب ). قطعات پراکنده از ابر. <BR><font color=\"Blue\">◄</font> سراب . (از اقرب الموارد). عَساقیل . و رجوع به عساقیل شود.<br></font></div>'),
(183232, 'عساقلی', '<span class=\"hlight\">عساقلی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) نوعی از کماءة است . (مخزن الادویة). رجوع به کماءة شود.<br></font></div>'),
(183233, 'عساقیل', '<span class=\"hlight\">عساقیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عُسقول . (ناظم الاطباء). نوعی از سماروغ و قارچ سپید بزرگ که آن را شحمةالارض نیز گویند، و واحد آن عَسقَل و عُسقول است . <BR><font color=\"Blue\">◄</font> سراب . (از منتهی الارب ) (از اقرب الموارد). عَساقل . رجوع به عساقل شود. <BR><font color=\"Blue\">◄</font> پاره های جداگانه ٔ ابر. (منتهی الارب ). قطعات پراکنده ٔ ابر.(از اقرب الموارد). عَساقل . و رجوع به عساقل شود.<br></font></div>'),
(183234, 'عساقیل', '<span class=\"hlight\">عساقیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) جایگاهی است، و نام آن در شعرجامعبن عمرو آمده است . رجوع به معجم البلدان شود.<br></font></div>'),
(183235, 'عسال', '<span class=\"hlight\">عسال .</span> <font color=\"DarkGreen\"><b>[ ع َس ْ سا ]</font></b> (ع ص ) مبالغه است مصدر عَسَل را. (از اقرب الموارد). رجوع به عسل شود. <BR><font color=\"Blue\">◄</font> منسوب به عسل . (از الانساب سمعانی ). <BR><font color=\"Blue\">◄</font> انگبین گیرنده . (منتهی الارب ). انگبین چین . (ملخص اللغات حسن خطیب کرمانی ). چیننده ٔ عسل از جای آن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> انگبین فروش . (ملخص اللغات حسن خطیب کرمانی ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> شکرریز. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> نیزه ٔ سخت جنبان . (منتهی الارب ). رمح و نیزه که از نرمی به اهتزاز آید. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ)انجیر سیاه و یا سپید بسیار شیرین . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> گرگ . (ناظم الاطباء) (از تاج العروس ).<br></font></div>'),
(183236, 'عسال', '<span class=\"hlight\">عسال .</span> <font color=\"DarkGreen\"><b>[ ع َس ْ سا ]</font></b> (اِخ ) (<span class=\"hlight\" dir=\"rtl\">٢٦٩</span>-<span class=\"hlight\" dir=\"rtl\">٣٤٩</span> هَ . ق .) نام او محمدبن احمدبن ابراهیم اصفهانی و مکنی به ابواحمد و مشهور به عسال است . قاضی و محدث و از اهالی اصفهان بود، و مسند قضاوت را در این شهر بعهده داشت . از جمله کتابهای اوست : أحادیث مالک، الامثال، التاریخ، التفسیر، الرقائق، الشیوخ، غریب الحدیث، المسند، المعرفة. (از الاعلام زرکلی از ذکر اخبار اصبهان و سیرالنبلاء).<br></font></div>'),
(183237, 'عسال', '<span class=\"hlight\">عسال .</span> <font color=\"DarkGreen\"><b>[ ع َس ْ سا ]</font></b> (اِخ ) نام او محمدبن موسی عسال نیشابوری و مکنی به ابوعبداﷲ است . ازفقیهان و زاهدان بود و حدیث را از ابن عیینه و هشیم و ابن مبارک شنیده است و احمدبن حرب و ایوب بن حسن از او روایت کرده اند. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(183238, 'عسالة', '<span class=\"hlight\">عسالة.</span> <font color=\"DarkGreen\"><b>[ ع َس ْ سا ل َ ]</font></b> (ع اِ) کبت انگبین . و زنبور عسل . (از منتهی الارب ). نحل . (اقرب الموارد). مُنج . منج انگبین . <BR><font color=\"Blue\">◄</font> شوره، و جای انگبین . (از منتهی الارب ). خلیة و کندوی زنبور عسل . <BR><font color=\"Blue\">◄</font> چینندگان عسل . (از اقرب الموارد). رجوع به عسال شود.<br></font></div>'),
(183239, 'عسالج', '<span class=\"hlight\">عسالج .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ ]</font></b> (ع اِ) ج ِ عُسلُج و عِسلاج و عُسلوج . (منتهی الارب ) (اقرب الموارد). رجوع به عُسْلُج و عِسلاج و عُسلوج شود.<br></font></div>'),
(183240, 'عسالق', '<span class=\"hlight\">عسالق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل ِ ]</font></b> (ع ص ) طویل و سبک، و گویند زشت اخلاق . (از اقرب الموارد). عسلق <font color=\"DarkGreen\"><b>[ ع ِ ل ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ س َل ْ ل َ ]</font></b>. رجوع به عسلق شود.<br></font></div>'),
(183241, 'عسالق', '<span class=\"hlight\">عسالق .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ ]</font></b> (ع اِ) ج ِ عسلق <font color=\"DarkGreen\"><b>[ ع َ ل َ<span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ل ِ ]</font></b> . (منتهی الارب ). رجوع به عسلق شود. <BR><font color=\"Blue\">◄</font> ج ِ عَسلقة. (آنندراج ). رجوع به عسلقة شود.<br></font></div>'),
(183242, 'عسالنج', '<span class=\"hlight\">عسالنج .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ ]</font></b> (ع اِ) برگ درخت انگور است، و آن را به عربی کف الکرم خوانندو به شیرازی پنجه ٔ رَز گویند. (برهان ) (آنندراج ).<br></font></div>'),
(183243, 'عسالیج', '<span class=\"hlight\">عسالیج .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عُسلوج و عُسلُج و عِسلاج . (اقرب الموارد). شاخه های تازه روئیده ٔاشجار است که هنوز مستحکم نشده باشد. (تحفه ٔ حکیم مؤمن ). بمعنی قضبان دقاق یعنی شاخه ها و بیخهای درخت کرم و کدو و خیار و امثال اینها که بر درخت و غیر آن پیچد و بالا رود، و به معنی شاخه های درخت باریک و بیخ درخت نیز آمده، و گویند لفایف مراد از آنها است . (مخزن الادویة). رجوع به عُسْلُج و عسلاج و عسلوج شود.<br></font></div>'),
(183244, 'عسامة', '<span class=\"hlight\">عسامة.</span> <font color=\"DarkGreen\"><b>[ ع َس ْ سا م َ ]</font></b> (اِخ ) ابن عمروبن علقمه ٔ مَعافری، مکنی به ابوداجن . از امرای مصر بود و چند بار شرطه ٔ آنجا را بعهده گرفت . و موسی بن مصعب او را به نیابت خود امیر آنجا کرد و چون بسال <span class=\"hlight\" dir=\"rtl\">١٦٨</span> هَ .ق . مصعب بقتل رسید مهدی عباسی او را امارت مصر بداد. عسامة بسال <span class=\"hlight\" dir=\"rtl\">١٧٦</span> در مصر درگذشت . (از الاعلام زرکلی از النجوم الزاهرة، و الولاة و القضاة).<br></font></div>'),
(183245, 'عسامة', '<span class=\"hlight\">عسامة.</span> <font color=\"DarkGreen\"><b>[ ع َس ْ سا م َ ]</font></b> (اِخ ) شعبه ای از قبیله ٔ بنی رکب، منشعب از بنی اشعر. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٢٨٣</span>).<br></font></div>'),
(183246, 'عسان', '<span class=\"hlight\">عسان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) بطنی است از صدف، و منسوب بدان عسانی شود. (از اللباب فی تهذیب الانساب ). و رجوع به عسانی شود.<br></font></div>'),
(183247, 'عسان', '<span class=\"hlight\">عسان .</span><font color=\"DarkGreen\"><b>[ ع َس ْ سا ]</font></b> (اِخ ) قریه ای است از نواحی حلب و در حدود یک فرسخ با حلب فاصله دارد. (از معجم البلدان ).<br></font></div>'),
(183248, 'عسانی', '<span class=\"hlight\">عسانی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ص نسبی ) منسوب به عسان، که آن بطنی است از صدف، و از آنها است دحین و ربیعة دو فرزند عسان که هر کدام از آنها به «عسانی » ملقب شده اند. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(183249, 'عساود', '<span class=\"hlight\">عساود.</span> <font color=\"DarkGreen\"><b>[ ع َ وِ ]</font></b> (ع اِ) ج ِ عِسوَدّة. (منتهی الارب ) (اقرب الموارد). رجوع به عسودّة شود.<br></font></div>'),
(183250, 'عساکب', '<span class=\"hlight\">عساکب .</span> <font color=\"DarkGreen\"><b>[ ع َ ک ِ ]</font></b> (ع اِ) ج ِ عِسکِبة. (ناظم الاطباء). رجوع به عسکبة شود.<br></font></div>'),
(183251, 'عساکر', '<span class=\"hlight\">عساکر.</span> <font color=\"DarkGreen\"><b>[ ع َ ک ِ ]</font></b> (ع اِ) ج ِ عَسکر. (منتهی الارب ) (از اقرب الموارد). لشکرها. (غیاث اللغات ) (آنندراج ). رجوع به عسکر شود.<br>- <span class=\"hlight\">عساکر منصوره، عساکر نصرت مآثر</span> ؛ سپاه فیروزمند و مظفر. (ناظم الاطباء).<br><BR><font color=\"Blue\">◄</font> (اِخ ) از اعلام است . (از منتهی الارب ).<br></font></div>'),
(183252, 'عسب', '<span class=\"hlight\">عسب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) برجستن گشن بر ماده . (از منتهی الارب ). گشنی کردن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> به کرایه دادن گشن به جهت گشنی، و کرایه ٔ فحل دادن . (از منتهی الارب ). به مزد دادن گشن . (تاج المصادر بیهقی ) (از المصادر زوزنی ). و پیغمبر اکرم (ص ) عسب فحل را نهی کرده است . (از منتهی الارب ).<br></font></div>'),
(183253, 'عسب', '<span class=\"hlight\">عسب .</span> <font color=\"DarkGreen\"><b>[ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ س ُ ]</font></b> (ع اِ) ج ِ عسیب .(اقرب الموارد). شاخه های خرمابن که راست و بی برگ باشد. (ناظم الاطباء): و العرب تکتب فی أکتاف الابل و اللخاف و فی العسب عسب النخل . (الفهرست ابن الندیم ).<br></font></div>'),
(183254, 'عسب', '<span class=\"hlight\">عسب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) آب گشن و نسل آن و فرزند. (منتهی الارب ). نسل : قطع اﷲ عسبه ؛ خداوند نسل او را قطع کناد! (از اقرب الموارد).<br></font></div>'),
(183255, 'عسب', '<span class=\"hlight\">عسب .</span> <font color=\"DarkGreen\"><b>[ ع َ س ِ ]</font></b> (ع ص ) رأس عسب ؛ سر از دیر شانه ناکرده . (منتهی الارب ). سری که از دیر شانه ناکرده باشند.(ناظم الاطباء). فرس عسب ؛ اسب که بر ترجیل و فروهشتن موی او زمانی دیر گذشته باشد. (از اقرب الموارد).<br></font></div>'),
(183256, 'عسبار', '<span class=\"hlight\">عسبار.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) کفتاربچه از گرگ . (منتهی الارب ). بچه ٔ کفتار از گرگ . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بچه گرگ . (منتهی الارب ) (از اقرب الموارد). بچه ٔ گرگ از ماده سگ . (یادداشت مرحوم دهخدا). عِسبارة. رجوع به عسبارة شود.<br></font></div>'),
(183257, 'عسبان', '<span class=\"hlight\">عسبان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عَسیب . (منتهی الارب ) (اقرب الموارد). جرید نخل . (مخزن الادویة). رجوع به عسیب شود.<br></font></div>'),
(183258, 'عسبة', '<span class=\"hlight\">عسبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِ) اسم مَرّه است برای مصدر عسب . (از اقرب الموارد). رجوع به عسب شود. <BR><font color=\"Blue\">◄</font> کفتگی در کوه . (منتهی الارب ). شق و شکاف در کوه . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) موضعی است، و آن را عشبة به شین معجم نیز نقل کرده اند. (از منتهی الارب ).<br></font></div>'),
(183259, 'عسبر', '<span class=\"hlight\">عسبر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب ُ ]</font></b>(ع اِ) پلنگ . (منتهی الارب ). نمر. (اقرب الموارد). نمر نر. (مخزن الادویة). ج، عَسابر. <BR><font color=\"Blue\">◄</font> (ص ) ناقة عسبر؛ ناقه ٔ شدید و سخت و سریع. (از اقرب الموارد). عُسبور. عسبرة. و رجوع به عسبرة و عسبور شود.<br></font></div>'),
(183260, 'عسبق', '<span class=\"hlight\">عسبق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ب ِ ]</font></b> (ع اِ) درختی است تلخ که در تداوی جراحت بکار آید. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183261, 'عسبلة', '<span class=\"hlight\">عسبلة.</span> <font color=\"DarkGreen\"><b>[ ع َب َ ل َ ]</font></b> (ع مص ) همدیگر آمدوشد مردمان و تردد ایشان .(از منتهی الارب ). آمدوشد کردن مردمان و مراوده کردن آنها با هم . (از ناظم الاطباء) (از اقرب الموارد).<br></font></div>'),
(183262, 'عسبور', '<span class=\"hlight\">عسبور.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) بچه ٔ سگ از گرگ ماده . (منتهی الارب ) (از اقرب الموارد). عسبورة. و رجوع به عسبورة شود.<br></font></div>'),
(183263, 'عسج', '<span class=\"hlight\">عسج .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) گردن دراز کردن در رفتار. (ازمنتهی الارب ). گردن یازیدن در وقت رفتن . (تاج المصادر بیهقی ). دراز کردن گردن در هنگام راه رفتن . عَسَجان . عَسیج . و رجوع به عسیج شود. <BR><font color=\"Blue\">◄</font> به شتاب رفتن . (از ناظم الاطباء). دویدن . (المصادر زوزنی ).<br></font></div>'),
(183264, 'عسج', '<span class=\"hlight\">عسج .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع مص ) بیمار گردیدن شتران از چریدن خار عوسج . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183265, 'عسجان', '<span class=\"hlight\">عسجان .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ]</font></b> (ع مص ) عَسْج . عسیج . رجوع به عَسْج و عسیج شود.<br></font></div>'),
(183266, 'عسجد', '<span class=\"hlight\">عسجد.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (اِخ ) نام جایگاهی است در عینة، و نام آن در شعر رِزاخ بن ربیعه ٔ عُذری آمده است و شتران عسجدی بدانجا منسوبند. و آن را عسجر، به راء نیز خوانده اند. (از معجم البلدان ).<br></font></div>'),
(183267, 'عسجد', '<span class=\"hlight\">عسجد.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ع اِ) زر، و جوهر هر قسم که باشد مانند مروارید و یاقوت . (منتهی الارب ). زر. (دهار). زر و طلا، و بمعنی جواهر چون دُر ویاقوت . (غیاث اللغات ) (آنندراج ). طلا، و گویند هر نوع جوهر چون یاقوت و درّ. (از اقرب الموارد). اسحاق بن ابراهیم فارابی نیز در کتاب دیوان الادب آن را زر دانسته، سپس میگوید آن جامع همه ٔ جواهر است از درّ و یاقوت، ابوریحان بیرونی قول او را رد کرده و گوید عسجد فقط بر زر اطلاق میشود، و ظاهراً اشتباه اسحاق بن ابراهیم از آنجا ناشی میشود که گویند «تاج من عسجد» و او فکر کرده است عسجد بر هر یک از جواهر تاج اطلاق میشود، و حال آنکه همان را میتوان «تاج من ذهب » گفت، چه منظور از عسجد یا ذهب جنس خود تاج است و تاج در هرحال خالی از ترصیع نیست . رجوع به الجماهر بیرونی ص <span class=\"hlight\" dir=\"rtl\">٢٣٢</span> شود. زر. طلا. تبر. عقیان . عین . نضر <span class=\"hlight\">:</span> <br>اگر به مدح تو چون عسجدی شود مادح <br>وگر دوات زبرجد شود قلم عسجد.<br> <font color=\"Red\">سوزنی .</font><br><BR><font color=\"Blue\">◄</font> (ص ) شتر درشت تن دار. (منتهی الارب ). شتر ضَخم . (از اقرب الموارد). شتر درشت تنومند. (ناظم الاطباء).و آن جزو چند کلمه ٔ چهارحرفی است که بدون حرف «ذولقی » آمده است . (از منتهی الارب ).<br></font></div>'),
(183268, 'عسجدی', '<span class=\"hlight\">عسجدی .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (از ع، ص نسبی ) منسوب به عسجد. زرین . و رجوع به عسجد شود. <BR><font color=\"Blue\">◄</font> شیوه ای از خط <span class=\"hlight\">:</span> و این آلت <font color=\"DarkGreen\"><b>[ یعنی قلم ]</font></b> که یاد کرده آمد سه گونه نهاده اند، یکی محرف تمام، و آن خط کز آن قلم آید آن را لجینی خوانند یعنی خط سیمین . دیگر مستوی، و آن خط کز آن قلم آید آن را عسجدی خوانند یعنی خط زرین . (نوروزنامه ).<br></font></div>'),
(183269, 'عسجدی', '<span class=\"hlight\">عسجدی .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (اِخ ) ابونظر عبدالعزیزبن منصور عسجدی . هدایت در مجمع الفصحاء، او را مروزی قزوینی دانسته و دولتشاه در تذکرةالشعراء، وی راهروی شمرده است و صحت این هر دو قول مورد تردید است . از احوال او اطلاعی در دست نیست لیکن مسلم است که از معاصران محمود غزنوی و مداح او بوده و در خدمتش تقرب داشته است و قصیده ای در فتح سومنات، که بسال <span class=\"hlight\" dir=\"rtl\">٤١٦</span> هَ .ق . صورت گرفته بود، ساخته بوده است بدین مطلع:<br>تا شاه خسروان سفر سومنات کرد<br>کردارخویش را علم معجزات کرد.<br>دولتشاه او را ازجمله ٔ شاگردان عنصری دانسته که صحت این قول نیز مورد تردید است . هدایت وفات او را در سال <span class=\"hlight\" dir=\"rtl\">٤٣٢</span> هَ .ق . نوشته است و اگر چنین باشد او فقط بایست دوره ٔ سلطنت محمود و مسعود را درک کرده باشد و حال آنکه بنابر شاهد دیگری میدانیم که او در دوره ٔ سلطنت سلطان مودودبن مسعود (<span class=\"hlight\" dir=\"rtl\">٤٣٢</span>-<span class=\"hlight\" dir=\"rtl\">٤٤٠</span> هَ .ق .) زنده بوده، و آن اشاره در قصیده ای از معزی است که در مدح تاج الدین نصیرالملک مجدالدوله ابومحمد منیعبن مسعود از خاندان منیعی نیشابور گفته و خطاب به ممدوح خود چنین آورده است <span class=\"hlight\">:</span> <br>به مجلس پدرت عسجدی زبهر طمع<br>مدیح برد به ایام جغری و مودود<br>به مجلس تو من آورده ام زبهر شرف <br>عزیز عقدی بگزیده از میان عقود.<br>و مراد از جغری ابوسلیمان داود جغری بیک برادر طغرل اول سلجوقی است که از <span class=\"hlight\" dir=\"rtl\">٤٢٩</span> تا <span class=\"hlight\" dir=\"rtl\">٤٥٠</span> هَ .ق . بر خراسان امارت داشت، بنابراین باید عسجدی بعد از سال <span class=\"hlight\" dir=\"rtl\">٤٣٢</span> فوت کرده باشد. از اشعار عسجدی ابیاتی در لباب الالباب و مجمعالفصحا و برخی از کتب دیگر مانند ترجمان البلاغه و حدائق السحر و المعجم و لغت فرس و فرهنگ جهانگیری آمده است و یک قصیده ٔ مصنوع او را به مطلع:<br>باران قطره قطره همی بارم ابروار<br>هر روز خیره خیره ازین چشم سیل بار<br>مرحوم عباس اقبال از یک جُنگ خطی در حواشی کتاب حدائق السحر آورده است . (ازتاریخ ادبیات در ایران تألیف صفا ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٧٧</span>).<br></font></div>'),
(183270, 'عسجدیة', '<span class=\"hlight\">عسجدیة.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ دی ی َ ]</font></b> (اِخ ) نام آن در شعر أعشی آمده است و آن را بازار طلافروشان و زرگران دانسته اند، و برخی آن را آبی دانسته اند ازآن ِ بنی سعد. (از معجم البلدان ).<br></font></div>'),
(183271, 'عسجدیة', '<span class=\"hlight\">عسجدیة.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ دی ی َ ]</font></b> (ع اِ) شتربچگان بزرگ . (منتهی الارب ). فصیل های بزرگ . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتر زربار. (منتهی الارب ). شترانی که بار طلا و زر دارند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> برنشستنی ملوک، و آن شترانند که جهت نعمان بن منذر بیاراستندی . (منتهی الارب ). رکاب و شتران پادشاهان، و آن در اصل شترانی بودند که برای نعمان زیور میشدند. (از اقرب الموارد). و رجوع به عسجد شود. <BR><font color=\"Blue\">◄</font> (اِخ ) فَرَسی است . (از اقرب الموارد). اسبی است از اولاد دیناری . (منتهی الارب ).<br></font></div>'),
(183272, 'عسجر', '<span class=\"hlight\">عسجر.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (اِخ ) جایگاهی است در نزدیکی مکه . و برخی آن را محرف عسجد دانسته اند. (از معجم البلدان ). و رجوع به عسجد (اِخ ) شود.<br></font></div>'),
(183273, 'عسجر', '<span class=\"hlight\">عسجر.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ع اِ) نمک . (منتهی الارب ). ملح . (اقرب الموارد) (مخزن الادویة).<br></font></div>'),
(183274, 'عسجل', '<span class=\"hlight\">عسجل .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (اِخ ) موضعی است به حره ٔ بنی سلیم . (منتهی الارب ). جایگاهی است در حرة بنی سلیم، و نام آن در شعر عباس بن مرداس آمده است . (از معجم البلدان ).<br></font></div>'),
(183275, 'عسجمة', '<span class=\"hlight\">عسجمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ م َ ]</font></b> (ع مص ) سبک گشتن و شتاب کردن . (از اقرب الموارد). سبکی و شتابی . (منتهی الارب ). <br></font></div>'),
(183276, 'عسد', '<span class=\"hlight\">عسد.</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (ع مص ) سیر کردن و رفتن . <BR><font color=\"Blue\">◄</font> سخت تافتن رسن را. (از منتهی الارب ): عسد الحبل ؛ ریسمان را به سختی تافت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گائیدن . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) ببر، و برخی آن را به این معنی صحیح نمیدانند. (از اقرب الموارد).<br></font></div>'),
(183277, 'عسر', '<span class=\"hlight\">عسر.</span> <font color=\"DarkGreen\"><b>[ ع َ س ِ ]</font></b> (ع ص ) کار درپیچان و دشوار. (منتهی الارب ). صعب . (اقرب الموارد). مشکل . عویص . سخت . دشخوار. عسیر: حاجة عسر؛ نیاز دشوار. (منتهی الارب ). یوم عسر؛ روز سخت یا روز بد. (منتهی الارب ). روز شدید و سخت یا روز شوم . (از اقرب الموارد) <span class=\"hlight\">:</span> یقول الکافرون هذا یوم عسر (قرآن <span class=\"hlight\" dir=\"rtl\">٨/٥٤</span>)؛ کافران گویند این روزی است سخت و دشوار. همچنانکه علاج سرطان عسر است علاج جذام عسرتر است . (ذخیره ٔ خوارزمشاهی ). هرکه را آواز بگردد و باطل شود زود به علاج مشغول باید شد، چه اگر روزگار برآید علاج به دشخواری پذیرد و عسرگردد. (ذخیره ٔ خوارزمشاهی ). لکن بر هر حال که باشد تب هاء مرکب عسرتر و دیرگذرتر باشد. (ذخیره ٔ خوارزمشاهی ). <BR><font color=\"Blue\">◄</font> رجل عَسِر بین العَسَر؛ نیک بدخوی . (از منتهی الارب ). مرد شَکِس و بدخوی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بعیر عسر؛ شتر که پیش از رام شدن سوار شوند او را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شتر ماده ای که در وقت دویدن دنب بردارد. (منتهی الارب ).<br>- <span class=\"hlight\">عسرالانهضام </span> ؛ دشوارگوار. دیرگوار. دیرگوارد. (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">عسرالهضم </span> ؛ دشوارگوار. (یادداشت مرحوم دهخدا). عسرالانهضام . دشوارگوارد.<br></font></div>'),
(183278, 'عسر', '<span class=\"hlight\">عسر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) وام خواستن از غریم به وقت تنگدستی او. (از منتهی الارب ). وام خواستن در حال تنگی دست . (المصادر زوزنی ). وام خواستن در وقت تنگدستی غریم . (تاج المصادر بیهقی ): عسر فلان الغریم ؛ فلان در وقت عسرت و تنگدستی خود از مدیون دین خود را خواست، و در این صورت او را «عاسر» گویند. (از اقرب الموارد).  <BR><font color=\"Blue\">◄</font> از سوی چپ آمدن . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> به دشواری زادن بچه را. (از منتهی الارب ): عسرت المراءة؛ زادن آن زن دشوار و سخت گشت . (از اقرب الموارد). عَسَران . و رجوع به عَسَران شود. <BR><font color=\"Blue\">◄</font> به قهرو ناپسندی گرفتن مال را از کسی . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> دم برداشتن شتر ماده در دویدن . (از منتهی الارب ) (از اقرب الموارد). دنبال برداشتن شتر. (تاج المصادر بیهقی ). عَسَران . و رجوع به عَسَران شود.<br></font></div>'),
(183279, 'عسر', '<span class=\"hlight\">عسر.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) آن را نام قبیله ای از جن دانسته اند، و برخی گویند سرزمینی است که جن در آن سکنی دارد. و برخی آن را نام جایگاهی دانسته اند. و آن را «عشر» به شین معجمه نیز نوشته اند. و نام آن در شعر ابن احمر و زهیر آمده است . (از معجم البلدان ).<br></font></div>'),
(183280, 'عسر', '<span class=\"hlight\">عسر.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع اِمص ) دشواری . <BR><font color=\"Blue\">◄</font> بدخوئی و زفتی . (منتهی الارب ).<br></font></div>'),
(183281, 'عسر', '<span class=\"hlight\">عسر.</span> <font color=\"DarkGreen\"><b>[ ع ُ س ُ ]</font></b> (ع اِمص ) دشواری . خلاف یُسر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> قلت و کمی ذات الید و مال . (از اقرب الموارد). عُسر. و رجوع به عسر شود.<br></font></div>'),
(183282, 'عسر', '<span class=\"hlight\">عسر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِمص ) دشواری . خلاف یسر. (منتهی الارب ). دشواری . (دهار) <span class=\"hlight\">:</span> یرید اﷲ بکم الیسر و لایرید بکم العسر (قرآن <span class=\"hlight\" dir=\"rtl\">١٨٥/٢</span>)؛ خداوند برای شما آسانی را میخواهد و برای شما دشواری را نمیخواهد. قال لاتؤاخذنی بما نسیت و لاترهقنی من أمری عسراً (قرآن <span class=\"hlight\" dir=\"rtl\">٧٣/١٨</span>)؛ گفت بسبب آنچه فراموش کرده ام مرا مؤاخذه مکن و مرا در کارم دشواری مرسان . سیجعل اﷲ بعد عسر یسراً (قرآن <span class=\"hlight\" dir=\"rtl\">٧/٦٥</span>)؛ خداوند پس از دشواری آسانی قرار خواهد داد. فان مع العسر یسراً(قرآن <span class=\"hlight\" dir=\"rtl\">٥/٩٤</span> و <span class=\"hlight\" dir=\"rtl\">٦</span>)؛ پس همانا با دشواری، آسانی است .<br>درد عسر افتاد و صافش یسر آن <br>صاف چون خرما و دُردی یسر آن .<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عسر الامور مقدمة الیسر</span> (علی «ع » از امثال و حکم دهخدا)؛ تنگی و سختی کارهاسرآغاز گشادگی آنهاست .<br> <BR><font color=\"Blue\">◄</font> کمی و قلت مال و ذات الید. (از اقرب الموارد). تنگدستی و فقر و تهیدستی . (فرهنگ فارسی معین ). عُسُر. و رجوع به عُسُر شود. <BR><font color=\"Blue\">◄</font> (اِ) نوعی بازی است، و آن این است که چوبی را برپای میدارند و از نشانه ای به نشانه ٔ دیگر پرتاب میکنند و هر کس بتواند بر آن بزند، برنده است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص، اِ) ج ِ عَسراء. (اقرب الموارد). رجوع به عسراء (ع ص ) شود.<br>- <span class=\"hlight\">عسرالبلع</span> ؛ سختی و دشواری بلعیدن . سختی اوباردن . دشواری بلع.<br>- <span class=\"hlight\">عسرالبول </span> ؛ دشخواری آب تاختن . (التفهیم ). سختی و دشواری که در کمیز انداختن بهم رسد. (ناظم الاطباء). بازگرفتن بول و دشخواری بیرون آمدن او. و اسباب عسرالبول یا آماس بود یا بادی غلیظ و یا ریش و یا ریم گردآمده یا خون بود که در مثانه بسته شود، یا جراحت قرحه ای بود که رسته شود، یا گوشتی فزونی که برآید، یا رطوبتی لزج یا سنگی در مثانه .(ذخیره ٔ خوارزمشاهی ). دشواری میختن . تقطیرالبول . و رجوع به تقطیرالبول شود.<br>- <span class=\"hlight\">عسرالطمث </span> ؛ دشواری طمث . رجوع به طمث شود.<br>- <span class=\"hlight\">عسرالنفس </span> ؛ نفس تنگی . تاسه . (ناظم الاطباء). تنگی نفس . رَبْو.<br>- <span class=\"hlight\">عسروحرج </span> ؛ (اصطلاح فقه ) در لغت یعنی سختی و دشواری، و در احکام اسلام به موجب قاعده ٔ نفی عسروحرج در مواردی رفع احکام اولیه شود چنانکه اگر کسی نتواند نماز قائماً بخواند میتواند قاعداً بخواند و یا نتواند روزه بگیرد میتواند در ماه دیگر بگیرد و یا اصولاً روزه نگیرد. و مستند این قاعده آیه ٔ شریفه ٔ «لیس علی الاعمی حرج و لا علی الاعرج حرج و لا علی المریض حرج » (قرآن <span class=\"hlight\" dir=\"rtl\">٦١/٢٤</span>) و «یرید اﷲ بکم الیسر و لایرید بکم العسر» (قرآن <span class=\"hlight\" dir=\"rtl\">١٨٥/٢</span>) و حدیث رفع است . (از فرهنگ علوم بنقل از قوانین ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>).<br></font></div>'),
(183283, 'عسر', '<span class=\"hlight\">عسر.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع مص ) درپیچان شدن بر کسی کار. (از منتهی الارب ). دشوار شدن کار. (دهار). سخت شدن کار. ضد یَسر. (از اقرب الموارد). عسر <font color=\"DarkGreen\"><b>[ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُس ُ ]</font></b> . و رجوع به عُسْر و عُسُر شود. <BR><font color=\"Blue\">◄</font> برابر نمودن کار را هر دو دست . (از منتهی الارب ). أعسر و چپ دست بودن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مشکل و سخت شدن کار. <BR><font color=\"Blue\">◄</font> کم شدن سماحت شخص در کارها و در دشواری افتادن وی . (از ناظم الاطباء).<br></font></div>'),
(183284, 'عسر', '<span class=\"hlight\">عسر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) دشوار گردیدن . (از منتهی الارب ). دشخوار شدن . (المصادر زوزنی ). دشخوار شدن کار. (تاج المصادر بیهقی ). دشوار شدن . (ترجمان علامه جرجانی ). ضد یسر. (از اقرب الموارد). دشوار شدن شیر و باران و علم و کار. (دهار). عَسارة. و رجوع به عسارة شود. <BR><font color=\"Blue\">◄</font> در وقت تنگدستی از مدیون و غریم وام خود را خواستن . (از اقرب الموارد). عَسر. رجوع به عَسر شود. <BR><font color=\"Blue\">◄</font> تنگ و سخت گردیدن روزگار. (از منتهی الارب ) (از اقرب الموارد). عَسارة. و رجوع به عسارة شود. <BR><font color=\"Blue\">◄</font> دشوار شدن زن را زادن بچه . (از منتهی الارب ). عَسارة. و رجوع به عسارة شود. <BR><font color=\"Blue\">◄</font> بیرون نیامدن آنچه در شکم است . (از منتهی الارب ) (از اقرب الموارد). عَسارة. و رجوع به عسارة شود. <BR><font color=\"Blue\">◄</font> مخالفت کردن با کسی . (از منتهی الارب )(از اقرب الموارد). عَسارة. و رجوع به عسارة شود.<br></font></div>'),
(183285, 'عسران', '<span class=\"hlight\">عسران .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع مص ) دم برداشتن شتر ماده در دویدن . (از منتهی الارب ). دنبال برداشتن شتر. (تاج المصادر بیهقی )(از اقرب الموارد). عَسر. و رجوع به عَسْر شود. <BR><font color=\"Blue\">◄</font> از سوی چپ آمدن . (از منتهی الارب ). عَسر. ورجوع به عَسْر شود. <BR><font color=\"Blue\">◄</font> سخت شدن زادن بر زن . (از اقرب الموارد). عَسر. و رجوع به عَسْر شود.<br></font></div>'),
(183286, 'عسران', '<span class=\"hlight\">عسران .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ عَسراء. (اقرب الموارد). رجوع به عسراء (ع ص ) شود.<br></font></div>'),
(183287, 'عسرب', '<span class=\"hlight\">عسرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ). اسد. (اقرب الموارد).<br></font></div>'),
(183288, 'عسرت', '<span class=\"hlight\">عسرت .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (ع اِمص ) عسرة. دشواری . (غیاث اللغات ) (مجمل اللغة). دشواری و سختی و زحمت و اشکال . (ناظم الاطباء). دشخواری . و رجوع به عسرة شود.<br>- <span class=\"hlight\">باعسرت </span> ؛ مشکل و دشوار. (ناظم الاطباء).<br>- <span class=\"hlight\">بی عسرت </span> ؛ آسان و سهل . (ناظم الاطباء).<br><BR><font color=\"Blue\">◄</font> تنگدستی و درویشی . (مجمل اللغة). دست تنگی . فاقه . فقر. نیاز. نیازمندی . ضرورت . حاجت .<br></font></div>'),
(183289, 'عسرت داشتن', '<span class=\"hlight\">عسرت داشتن .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ت َ ]</font></b> (مص مرکب ) مشکل بودن و دشوار بودن . (ناظم الاطباء). سخت بودن .<br></font></div>'),
(183290, 'عسرت کشیدن', '<span class=\"hlight\">عسرت کشیدن .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ ]</font></b> (مص مرکب ) سختی کشیدن . تحمل سختی و دشواری کردن <span class=\"hlight\">:</span> <br>می کشد عسرت هفتادودو ملت صائب <br>هرکه چون اهل خرابات ز خوش مشربهاست .<br> <font color=\"Red\">صائب (از آنندراج ).</font><br>هرچند کشی ز فاقه عسرت <br>از خلق مگیر غیر عزلت .<br><font color=\"Red\">درویش واله هروی (از آنندراج ).</font><br></font></div>'),
(183291, 'عسری', '<span class=\"hlight\">عسری .</span> <font color=\"DarkGreen\"><b>[ ع ُ را ]</font></b> (ع ن تف ) تأنیت أعسر. (از اقرب الموارد). رجوع به اعسر شود. <BR><font color=\"Blue\">◄</font> (اِمص ) تنگی و دشواری . خلاف یُسری ̍. (منتهی الارب ). دشواری . (دهار). اسم است عُسر را. نقیض یُسری ̍. (از اقرب الموارد). عُسرة. و رجوع به عسرة شود. <BR><font color=\"Blue\">◄</font> (اِ) عذاب یا امر دشوار. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> تره است . (منتهی الارب ). بقله ای است . (از اقرب الموارد). عَسری ̍. و رجوع به عَسری ̍ شود.<br></font></div>'),
(183292, 'عسری', '<span class=\"hlight\">عسری .</span> <font color=\"DarkGreen\"><b>[ ع َ را ]</font></b> (ع اِ)تره است . (منتهی الارب ). بقله ای است . (مخزن الادویة) (از اقرب الموارد). عُسری ̍. و رجوع به عُسری ̍ شود.<br></font></div>'),
(183293, 'عسس', '<span class=\"hlight\">عسس .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع اِ) ج ِ عاس ّ. (منتهی الارب ). ج ِ عاس است بمعنی شبگرد و حارس، آن را اسم جمع برای عاس نیز گفته اند، زیرا جمع مکسر «فاعل » بر وزن فَعَل نیامده است . (از اقرب الموارد). جمع عاس ّ است که به معنی شحنه ٔ شب باشد ودر فارسی بر مفرد اطلاق کنند. (غیاث اللغات ) (از آنندراج ). پاسبانان که به شب گردند. (دهار). کسی که به محافظت شهر به شب گردد. (غیاث اللغات ). شبگرد. شبگردان . کوتوال . نوبتی . گزمه . داروغه . شبرو <span class=\"hlight\">:</span> <br>یکی مواجر و بی شرم و ناخوشی که تو را<br>هزار بار خرانبار بیش کرده عسس .<br> <font color=\"Red\">لبیبی .</font><br>از خاک سر کویت خالی نشوم یک شب <br>گر بر سر هر سنگی حالی عسسی باشد.<br> <font color=\"Red\">خاقانی .</font><br>ماه سی روزه به از چارده شب <br>گرنه سگ نه عسسش نشناسد.<br> <font color=\"Red\">خاقانی .</font><br>شحنه ٔ شب خون عسس ریخته <br>بر شکرش پرّمگس ریخته .<br> <font color=\"Red\">نظامی .</font><br>بر در او گر نداری حرمتی <br>چون توانی رفت راه پرعسس ؟<br> <font color=\"Red\">عطار.</font><br>چون موکل آن ملایک پیش وپس <br>بوده پنهان گشته پیدا چون عسس .<br> <font color=\"Red\">مولوی .</font><br>اندر آن بودیم کآن شخص از عسس <br>راند اندر باغ از خوفی فرس .<br> <font color=\"Red\">مولوی .</font><br>هست او اندر کمین ای بوالهوس <br>تا نگردی فارغ از شب ای عسس .<br> <font color=\"Red\">مولوی .</font><br>اگر نیک مردی نماید عسس <br>نیارد بشب خفتن از دزد کس .<br> <font color=\"Red\">سعدی .</font><br>من مفلسم در کاروان گوهر که خواهد قصد کن <br>نگذاشت مطرب در برم چندان که بستاند عسس .<br> <font color=\"Red\">سعدی .</font><br>خونیان را بود ز شحنه هراس <br>شبروان را غم از عسس باشد.<br> <font color=\"Red\">سعدی .</font><br>محتسب مست و عسس هم مست و شحنه بود مست <br>جمله ٔ اصناف مست و کوچه و بازارمست .<br> <font color=\"Red\">اسیری لاهیجی (از آنندراج ).</font><br>گر عسس کرد رها محتسبم میگیرد<br>تا ز کیفیت چشم تو خبر یافته ام .<br> <font color=\"Red\">طالب کلیم (از آنندراج ).</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عسس بیا مرا بگیر</span>، همانند و به معنی : سری که درد نمی کند دستمال نمی بندند: مگر من بیکارم که خودم را وارد این معرکه بکنم، عسس بیا مرا بگیر که نیست .(فرهنگ عوام ). نظیر: أنت فی مثل صاحب البقرة. (امثال و حکم دهخدا).<br> <span class=\"hlight\">عسس را به یاددهد که مرا بگیر</span> ؛ این مثل را در جایی زنند که کسی از زبان خود حرفی بگوید که بدان حرف در بلا و تهلکه افتد. (آنندراج ).<br> <span class=\"hlight\">عسس را چو با دزد یاری بود</span> <br>به گنجینه چون استواری بود؟<br> <font color=\"Red\">امیرخسرو.</font><br> <span class=\"hlight\">عشرت شبگیر کن می نوش کاندر راه عشق </span> <br>شب روان را آشنائیهاست با میر عسس .<br> <font color=\"Red\">حافظ.</font><br>لقمه ٔ مردان نمی شاید به طفلی بار داد<br> <span class=\"hlight\">سرّ سلطان را نشاید گفت هرگز با عسس </span> .<br> <font color=\"Red\">مغربی .</font><br> <span class=\"hlight\">در کشوری که دزد رفیق عسس بود</span> <br>بیچاره رهروی که به خواب هوس بود.<br><font color=\"Red\">وحید قزوینی .</font><br></font></div>'),
(183294, 'عسس', '<span class=\"hlight\">عسس .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع مص ) عَس ّ است در تمام معانی . (از منتهی الارب ) (از اقرب الموارد). رجوع به عَس ّ شود.<br></font></div>'),
(183295, 'عسس باشی', '<span class=\"hlight\">عسس باشی .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ص مرکب، اِ مرکب ) رئیس عسسان . رئیس شبگردان . (فرهنگ فارسی معین ). و رجوع به عسس شود.<br></font></div>'),
(183296, 'عسطرتج', '<span class=\"hlight\">عسطرتج .</span> <font color=\"DarkGreen\"><b>[ ع ِ طَ رَ ت َ ]</font></b> (معرب، اِ) فرمانده چهل نفر مرد. (ناظم الاطباء) <span class=\"hlight\">:</span> و قومس کم از او <font color=\"DarkGreen\"><b>[ از فسطیار ]</font></b> باشد و او را دویست فرمان بردار، و عسطرتج کم از او باشد و او را چهل مرد در فرمان . (بیان الادیان ).<br></font></div>'),
(183297, 'عسطس', '<span class=\"hlight\">عسطس .</span> <font color=\"DarkGreen\"><b>[ ع ِ طِ ]</font></b> (ع اِ) نام گیاهی است . (ناظم الاطباء). و رجوع به عسطوس شود.<br></font></div>'),
(183298, 'عسطلة', '<span class=\"hlight\">عسطلة.</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ل َ]</font></b> (ع مص ) تکلم کردن به سخن ناآراسته و بی نظم . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ) سخن ناآراسته . (منتهی الارب ). کلام که آن را نظم نباشد. (از اقرب الموارد).<br></font></div>'),
(183299, 'عسطوس', '<span class=\"hlight\">عسطوس .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َس ْ س َ ]</font></b> (ع اِ)درختی است مانند درخت خیزران که در جزیره میروید. (منتهی الارب ). نوعی درخت است شبیه به خیزران . (مخزن الادویة). درختی است چون خیزران، و گویند خود خیزران است، و گویند درختی است در الجزیره که شاخه های نرم دارد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مهتر ترسایان در لغت رومیان . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183300, 'عسطوسة', '<span class=\"hlight\">عسطوسة.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ س َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َس ْ س َ س َ ]</font></b> (ع اِ) آب خنک و گوارا. <BR><font color=\"Blue\">◄</font> برف . (ناظم الاطباء).<br></font></div>'),
(183301, 'عسعاس', '<span class=\"hlight\">عسعاس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) گرگ . (منتهی الارب ). ذئب . (فهرست مخزن الادویة) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سراب . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(183302, 'عسعس', '<span class=\"hlight\">عسعس .</span> <font color=\"DarkGreen\"><b>[ ع ُ ع ُ ]</font></b> (ع اِ) بازرگانان آزمندو حریص . <BR><font color=\"Blue\">◄</font> آوندهای کلان . (منتهی الارب ).<br></font></div>'),
(183303, 'عسعس', '<span class=\"hlight\">عسعس .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (اِخ ) ابن سلامة، مکنی به ابوصعدة. صحابی است . (از منتهی الارب ). و رجوع به ابوصعدة شود.<br></font></div>'),
(183304, 'عسعس', '<span class=\"hlight\">عسعس .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (از ع، ص ) صیغه ٔ ماضی از مصدر عسعسة است به معنی تاریکی درآوردن شب . (از غیاث اللغات ). و در فارسی با توجه به مورد استعمال آن در قرآن کریم، بعنوان صفتی برای شب بکار رفته است <span class=\"hlight\">:</span> <br>ایمان به وجود تو جدا گشت ز کفران <br>چون روز درخشنده جدا از شب عَسْعَس .<br> <font color=\"Red\">ناصرخسرو.</font><br>و رجوع به عسعسة شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(183305, 'عسعس', '<span class=\"hlight\">عسعس .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (ع اِ) گرگ . (منتهی الارب ). ذئب . (فهرست مخزن الادویة). گرگ که در جستجوی شکار باشد در شب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خارپشت، بدان جهت که شبگرد میباشد. (منتهی الارب ). گوئی مفرد عَساعِس است بمعنی خارپشتان . (از اقرب الموارد). ج، عَساعِس . (منتهی الارب ).<br></font></div>'),
(183306, 'عسعس', '<span class=\"hlight\">عسعس .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (اِخ ) جایگاهی است در بادیه . و گویند کوهی است طویل دریک فرسخی ماورای ضریة ازآن ِ بنی عامر. و آن را کوهی ازآن ِ بنی دُبَیر در بلاد بنی جعفربن کلاب دانسته اند که در پایه ٔ آن آب ناصفة واقع است . (از معجم البلدان ).<br>- <span class=\"hlight\">دارة عسعس </span> ؛ ازآن ِ بنی جعفر است . (از معجم البلدان ).<br></font></div>'),
(183307, 'عسعسة', '<span class=\"hlight\">عسعسة.</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ س َ ]</font></b> (ع مص ) تاریکی درآوردن شب، و از آن جمله است آیه ٔ شریفه ٔ <span class=\"hlight\">:</span> و اللیل اذا عسعس . (قرآن <span class=\"hlight\" dir=\"rtl\">١٧/٨١</span>). تاریک شدن شب . (از دهار) (ترجمان القرآن جرجانی ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سپری شدن شب، از لغات اضداد است، و آیه ٔ فوق را به هر دو وجه تفسیر کرده اند. (از منتهی الارب ). پشت بدادن شب . (از دهار) (از ترجمان القرآن جرجانی ). رفتن شب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نزدیک آمدن شب . (ترجمان القرآن جرجانی ). نزدیک آمدن در کار به شب . (دهار). <BR><font color=\"Blue\">◄</font> به شب گشتن گرگ . (منتهی الارب ): عسعس الذئب ؛ گرگ درشب طواف کرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بزمین نزدیک گردیدن ابر. (از منتهی الارب ) (از اقرب الموارد). و گویند: عسعست السحابة؛ یعنی ابر در شب نزدیک زمین گشت در تاریکی و برق . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> مشتبه و آمیخته کردن کار را. (منتهی الارب ) (ازاقرب الموارد). <BR><font color=\"Blue\">◄</font> جنبانیدن چیزی را. (منتهی الارب ). حرکت دادن چیزی را. (از اقرب الموارد).<br></font></div>'),
(183308, 'عسف', '<span class=\"hlight\">عسف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) میل نمودن، و بیراه رفتن، و دست و پا زدن بر زمین، و سیر کردن بی راهه و بی فکر و بی هدایت . (از منتهی الارب ): عسف الطریق و عن الطریق ؛ از راه دور شد و از آن عدول کرد، و گویند یعنی آن را بدون رهنمایی و هدایت طی کرد. (از اقرب الموارد). از راه بگردیدن . (المصادر زوزنی ). <BR><font color=\"Blue\">◄</font> عسف المفازة؛ بیابان را بدون هدف و بدون رهنمایی طی کرد و راه پیموده شده توسط دیگران را نپیمود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> انجام دادن کار را بدون تدبیر. (از تاج المصادر بیهقی ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ستم کردن . (از منتهی الارب ) (از اقرب الموارد). اعتساف . تعدی . تطاول . جور. <BR><font color=\"Blue\">◄</font> خدمت خواستن از کسی . (از منتهی الارب ). استخدام کردن کسی را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عسف ضیعتهم ؛ نگاهبانی نمود ضیعت و آبادی ایشان را و کافی و بسنده شد ایشان را در امر آن . <BR><font color=\"Blue\">◄</font> کار کردن جهت کسی .(از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شب گشتن به طلب مطلوب . (از منتهی الارب ): بات فلان یعسف اللیل و باللیل ؛ فلان شب را به راه رفتن گذراند در طلب خواسته ٔ خود. <BR><font color=\"Blue\">◄</font> عسف الدمع الجفون َ؛ اشک بسیار گشت و در غیر مجرای خویش جاری شد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بزور و قوت گرفتن چیزی را. (از اقرب الموارد) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> عسف البعیر؛ آن شتر مشرف بر مرگ شد از غده ای که در او پدید آمد، و در موقع تنفس حنجره ٔ او لرزیدن گرفت . (از اقرب الموارد). مشرف بر مرگ شدن شتر از بیماری طاعون . (از ناظم الاطباء). عُسوف . و رجوع به عسوف شود.<br></font></div>'),
(183309, 'عسف', '<span class=\"hlight\">عسف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) دم مرگ . (منتهی الارب ). مرگ : فرّق بینهما العسف ؛ مرگ بین آن دو جدایی انداخت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> قدح بزرگ . (منتهی الارب ). قدح ضخیم و ستبر. ج، عُسوف . (از اقرب الموارد) <span class=\"hlight\">:</span> قال زید <font color=\"DarkGreen\"><b>[ بن ثابت ]</font></b> فواﷲ لنقل جبل من الجبال ماکان أثقل علی ّ من الذی أمرنی به من جمع القرآن أجمع من الرقاع و اللخاف و العسف  و صدور الرجال . (الفهرست ابن الندیم ).<br></font></div>'),
(183310, 'عسفات', '<span class=\"hlight\">عسفات .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع اِ) ج ِ عسفة. (ناظم الاطباء): ناقة بها عسفات ؛ شتر ماده ٔ طاعون زده ٔ قریب به مرگ رسیده . (منتهی الارب ). به معنی عُساف است یعنی بیماریی که شتر بوسیله ٔ غده دچار آن میشود. (از اقرب الموارد). و رجوع به عُساف شود.<br></font></div>'),
(183311, 'عسفان', '<span class=\"hlight\">عسفان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) گویند منهله ای است از مناهل راه بین جحفة و مکه . و برخی آن را بین المسجدین دانسته اند بفاصله ٔ دومرحله ای مکه . و برخی گویند آن قریه ٔ جامعی است و در آن منبر و نخیل و مزارع است در فاصله ٔ <span class=\"hlight\" dir=\"rtl\">٣٦</span>میلی مکه در مرز تهامة. و برخی آن را در دومرحله ای مکه در راه مدینه دانسته اند که تا جحفة سه مرحله فاصله دارد. و پیامبر (ص ) در سال پنجم هجرت در عسفان با بنی لحیان غزو کرده است . (از معجم البلدان ). و رجوع به امتاع الاسماع ص <span class=\"hlight\" dir=\"rtl\">٢٥٦</span> و <span class=\"hlight\" dir=\"rtl\">٢٥٧</span> شود.<br></font></div>'),
(183312, 'عسفة', '<span class=\"hlight\">عسفة.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع اِ) یک مرتبه لرزیدن گلوی شتر به مرگ رسیده از غده و طاعون .ج، عسفات . (ناظم الاطباء). و رجوع به عَسَفات شود.<br></font></div>'),
(183313, 'عسق', '<span class=\"hlight\">عسق .</span> <font color=\"DarkGreen\"><b>[ ع َس ِ ]</font></b> (ع ص ) رجل عسق ؛ مرد دشوارخوی . (منتهی الارب ).<br></font></div>'),
(183314, 'عسق', '<span class=\"hlight\">عسق .</span> <font color=\"DarkGreen\"><b>[ ع ُ س ُ ]</font></b> (ع ص، اِ) سخت گیرندگان بر غریم . (منتهی الارب ). سخت گیرندگان بر غریمان و مدیونان خویش در تقاضای دین . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گشنی دهندگان خرمابن و شتر وجز آن . (منتهی الارب ). لقاح ها. (از اقرب الموارد).<br></font></div>'),
(183315, 'عسق', '<span class=\"hlight\">عسق .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع اِمص ) درپیچیدگی . (منتهی الارب ). اِلتواء. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> دشوارخوئی و تنگ خوئی . (منتهی الارب ) (از اقرب الموارد). تنگ حوصلگی . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ) تاریکی اول شب . (منتهی الارب ). ظلمت و تاریکی، به معنی غسق . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شاخ کژ خشک هیچکاره . (منتهی الارب ). شاخه ٔ درخت کج شده ٔ بیکاره . (ناظم الاطباء). عرجون ردی وبی فایده، و آن لغتی است اسدی . (از اقرب الموارد).<br></font></div>'),
(183316, 'عسق', '<span class=\"hlight\">عسق .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع مص ) آزمند گردیدن . (از منتهی الارب ). حریص گشتن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چسفیدن به کسی و لازم گردیدن . (از منتهی الارب ). ملازم گشتن و چسبیدن به کسی . (از اقرب الموارد). دردوسیدن و ملازم گرفتن . (تاج المصادر بیهقی ) (از المصادر زوزنی ). <BR><font color=\"Blue\">◄</font> ستیهیدن در طلب چیزی . (از منتهی الارب ). اصرار و الحاح کردن در آنچه میخواهد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نزدیک گشن آمدن . (از منتهی الارب ).<br></font></div>'),
(183317, 'عسق', '<span class=\"hlight\">عسق .</span><font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) (به معنی دشمنی ) چاهی است در وادی جرار که شبانان اسحاق حفر نمودند. (از قاموس کتاب مقدس ).<br></font></div>'),
(183318, 'عسقب', '<span class=\"hlight\">عسقب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ ]</font></b> (ع اِ) ج ِ عِسقِبة.(منتهی الارب ) (اقرب الموارد). رجوع به عسقبة شود.<br></font></div>'),
(183319, 'عسقبة', '<span class=\"hlight\">عسقبة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ ب َ ]</font></b> (ع اِ) خوشه ٔ خرد انگور منفرد پیوسته در بن خوشه ٔ کلان .(منتهی الارب ). خوشه ٔ کوچک چسبیده به ریشه ٔ خوشه و عنقود. (از اقرب الموارد). ج، عِسقِب، عَساقِب . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(183320, 'عسقبة', '<span class=\"hlight\">عسقبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ب َ ]</font></b> (ع مص ) بی اشک گردیدن و بسته و سخت شدن چشم وقت گریه . (منتهی الارب ). جامد گشتن و خشک شدن چشم هنگام گریستن . (از اقرب الموارد).<br></font></div>'),
(183321, 'عسقد', '<span class=\"hlight\">عسقد.</span> <font color=\"DarkGreen\"><b>[ ع ُ ق ُ ]</font></b> (ع ص ) دراز گول . (منتهی الارب ). طویل احمق . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> پرگوشت درشت اندام . (منتهی الارب ). شخص تارّ و پرگوشت و درشت آفرینش . (از اقرب الموارد).<br></font></div>'),
(183322, 'عسقفة', '<span class=\"hlight\">عسقفة.</span> <font color=\"DarkGreen\"><b>[ ع َق َ ف َ ]</font></b> (ع مص ) بستگی و سختگی چشم، خلاف گریه، و بی آب شدن چشم، یا اراده ٔ گریه کردن و نتوانستن . (منتهی الارب ). خلاف بکاء، و گویند خواستن گریه را و نتوانستن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آهنگ نمودن بر خیر و نکردن آن را. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183323, 'عسقل', '<span class=\"hlight\">عسقل .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع اِ) یکی عَساقیل . (منتهی الارب ). واحد عَساقل . (از اقرب الموارد). نوعی از سماروغ بزرگ . (آنندراج ). نوعی از کماة است . (فهرست مخزن الادویة). عُسقول . رجوع به عساقل و عساقیل و عسقول شود.<br></font></div>'),
(183324, 'عسقلان', '<span class=\"hlight\">عسقلان .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) دهی است به بلخ، یا محله ای است . (منتهی الارب ). قریه ای است از قرای بلخ، یا محله ای است از محله های آنجا. (از معجم البلدان ). نام محله ای است از محله های بلخ، و آنکه آن را از قرای آنجا دانسته است خطا است . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(183325, 'عسقلان', '<span class=\"hlight\">عسقلان .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) از لغات دخیل است . (از المعرب ). شهری است از شام بر کران دریای روم، و اندر وی مسلمانانند. شهری است با نعمت بسیار و کشت و برز بسیار و خواسته های بسیار. (حدودالعالم ). شهری است بزرگ بر کنار دجله ٔ شام و روم، وسوری استوار دارد از سنگ، بازارها به رخام گسترده . و در شهر چشمه ای است که ابراهیم بیرون آورده . (نفائس الفنون ). شهری است به شام، و نام رود نیز نوشته اند.(غیاث اللغات ). شهری است به ساحل شام و آن را عروس الشام هم گویند و ترسایان حج آن کردندی و آمدوشد داشتندی در آن . (منتهی الارب ). شهری است در شام از اعمال فلسطین بر ساحل دریا بین غزه و بیت جِبرین، و آن را عروس شام لقب داده اند (عروس شام لقب دمشق نیز باشد).در بیست وهفتم جمادی الاَّخره ٔ سال <span class=\"hlight\" dir=\"rtl\">٥٤٨</span> هَ .ق . فرنگیان بر آن دست یافتند و مدت <span class=\"hlight\" dir=\"rtl\">٣٥</span> سال این شهر در اشغال آنان بود تا اینکه بسال <span class=\"hlight\" dir=\"rtl\">٥٨٣</span> هَ .ق . صلاح الدین ایوبی آن را بازستاند. سپس فرنگیان شهر عکا را فتح کردند و خیال تصرف عسقلان داشتند که صلاح الدین از بیم آنان، بسال <span class=\"hlight\" dir=\"rtl\">٥٨٧</span> هَ .ق . این شهر را ویران ساخت . این شهر را در عهد اسلام اول بار معاویةبن ابی سفیان در عهد خلافت خلیفه ٔ دوم فتح کرد. و در فضایل آن احادیث بسیاری از پیامبر (ص ) نقل شده است . (از معجم البلدان ) <span class=\"hlight\">:</span> <br>تازیانش کابل و بلغار دارند آبخور<br>گرد پی زآن سوی نیل و عسقلان افشانده اند.<br> <font color=\"Red\">خاقانی .</font><br>سگبانْت شه فرنگ یابم <br>دربان شه عسقلان ببینم .<br> <font color=\"Red\">خاقانی .</font><br>فرضه ٔ عسقلان و نیل از شط مفلحان و کر<br>هست خراس و پارگین از سمت مزوری .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(183326, 'عسقلان', '<span class=\"hlight\">عسقلان .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع اِ) عسقلان الرأس ؛ قسمت اعلی و بالای سر. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183327, 'عسقلانی', '<span class=\"hlight\">عسقلانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) محمدبن المتوکل بن أبی السری عسقلانی . از راویان است و از ابن عیینة و معتمربن سلیمان روایت کرده و ابوالعباس محمدبن حسن ابن قتیبه ٔ بلخی از او روایت کرده است . عسقلانی به سال <span class=\"hlight\" dir=\"rtl\">٢٣٨</span> هَ .ق . درگذشت . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(183328, 'عسقلانی', '<span class=\"hlight\">عسقلانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) عیسی بن احمدبن عیسی بن وردان عسقلانی بلخی، مکنی به ابویحیی . محدث بود و از عبداﷲبن وهب و بقیةبن ولید حدیث آموخت و ابوعبدالرحمان نسائی و ابوحاتم رازی از اوروایت کرده اند. نسبت او به عسقلان بلخ است . (از اللباب فی تهذیب الانساب ). و رجوع به معجم البلدان شود.<br></font></div>'),
(183329, 'عسقلانی', '<span class=\"hlight\">عسقلانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) حسن بن عبدالصمدبن شخباء. از شاعران قرن پنجم هجری در مصر. رجوع به حسن عسقلانی شود.<br></font></div>'),
(183330, 'عسقلانی', '<span class=\"hlight\">عسقلانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) احمدبن علی بن محمد کنانی عسقلانی، مکنی به ابوالفضل و ملقب به شهاب الدین و مشهور به ابن حجر. فقیه و محدث و مورخ مصری در قرن نهم هجری . رجوع به ابن حجر و مآخذ ذیل شود: الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٣</span>، التبر المسبوک ص <span class=\"hlight\" dir=\"rtl\">٢٣٠</span>، الضوء اللامع ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>، البدرالطالع ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٨٧</span>، خطط مبارک ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧</span>، آداب اللغة العربیة ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٦</span>، لسان المیزان ج <span class=\"hlight\" dir=\"rtl\">٦</span>، الدرر الکامنة ج <span class=\"hlight\" dir=\"rtl\">٤</span>، بدائع الزهور ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢</span>، دائرة المعارف الاسلامیة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٣١</span>.<br></font></div>'),
(183331, 'عسقلانی', '<span class=\"hlight\">عسقلانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ]</font></b> (اِخ ) احمدبن ابراهیم بن نصراﷲ کنانی عسقلانی، مکنی به ابوالبرکات و ملقب به عزالدین (<span class=\"hlight\" dir=\"rtl\">٨٠٠</span>-<span class=\"hlight\" dir=\"rtl\">٨٧٦</span> هَ .ق .).فقیه و مورخ و آخرین تن از رؤسای حنبلی ها در مصر بود. مدتی سمت قاضی القضاتی را بعهده داشت . تولد و وفات او در قاهره رخ داد. او را تألیفات بسیاری است که از آن جمله است : طبقات الحنابلة در بیست جلد، نظم اصول ابن الحاجب، صفوةالخلاصة در نحو، شفاء القلوب فی مناقب بنی ایوب، منظومه ای در جبر و مقابله، منظومه ای در مساحة، شرح الفیه ٔ ابن مالک، ارجوزه ای در قضاة مصر. (از الاعلام زرکلی از نظم العقیان و الضوء اللامع).<br></font></div>'),
(183332, 'عسقلانی', '<span class=\"hlight\">عسقلانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) آدم ابن أبی ایاس عسقلانی . از راویان است و اصل او از خراسان بود و مدتی ساکن عسقلان شام شد سپس به عراق و حجاز و شام سفر کرد. وی از شعبةو حمادبن سلمة روایت کرده است و محمدبن اسماعیل بخاری و ابوحاتم رازی از او روایت دارند. عسقلانی به سال <span class=\"hlight\" dir=\"rtl\">٢٢٠</span> هَ .ق . درگذشت . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(183333, 'عسقلانی', '<span class=\"hlight\">عسقلانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ص نسبی ) منسوب به عسقلان، که آن شهری است در ساحل شام از فلسطین . (از اللباب فی تهذیب الانساب ). و رجوع به عسقلان شود. <BR><font color=\"Blue\">◄</font> منسوب به عسقلان بلخ که آن ناحیه و محله ای است از بلخ، و سمعانی گوید من بدانجا رفتم و نزد جماعتی حدیث آموختم . (از اللباب فی تهذیب الانساب ). و رجوع به عسقلان شود.<br></font></div>'),
(183334, 'عسقلانی', '<span class=\"hlight\">عسقلانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) علی بن محمدبن محمدبن علی عسقلانی مصری کنانی، مشهور به ابن حجر. فقیه قرن هشتم هجری . رجوع به علی عسقلانی شود.<br></font></div>'),
(183335, 'عسقلة', '<span class=\"hlight\">عسقلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ل َ ]</font></b> (ع اِ) جائی که در آن سختگی و سنگهای سپید باشد. (منتهی الارب ). جائی که در آن سختی و صلابت و سنگهای سپید بود. (ناظم الاطباء) (از اقرب الموارد). سنگریزه ٔ سفید. (فهرست مخزن الادویة).<br></font></div>'),
(183336, 'عسقلة', '<span class=\"hlight\">عسقلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ل َ ]</font></b> (ع مص ) درخشیدن سراب . (منتهی الارب ). نمایان و ناپدید شدن سراب . (از اقرب الموارد).<br></font></div>'),
(183337, 'عسقول', '<span class=\"hlight\">عسقول .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) یکی عَساقیل . (منتهی الارب ) (از اقرب الموارد). سماروغ سپید بزرگ که عسقل نیز گویند. (ناظم الاطباء). و رجوع به عساقیل شود. <BR><font color=\"Blue\">◄</font> پاره ٔ جداگانه ٔ ابر. ج، عساقیل . (ناظم الاطباء). رجوع به عساقیل شود.<br></font></div>'),
(183338, 'عسل', '<span class=\"hlight\">عسل .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع مص ) چشیدن . (از منتهی الارب ): عسل من طعامه ؛ از طعام خود چشید. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دوست نمودن کسی را پیش مردم . (از منتهی الارب ). عَسْل . و رجوع به عَسْل شود. <BR><font color=\"Blue\">◄</font> مضطرب گردیدن آب از جنبانیدن باد. (از ناظم الاطباء). عَسْل . و رجوع به عَسْل شود. <BR><font color=\"Blue\">◄</font> هلاکی : عسلاً له ؛ أی تعساً. (از منتهی الارب ). عَسْل . و رجوع به عَسْل شود. <BR><font color=\"Blue\">◄</font> شتابی نمودن . (از ناظم الاطباء). سرعت کردن و شتافتن : عسل الدلیل بالمفازة؛ راهنما در بیابان سرعت گرفت . و گویند از آن جمله است حدیث : «کذب علیک العسل »؛ یعنی بر تو لازم است سرعت در راه رفتن . و «عسل » را در این جمله میتوان منصوب خواند بعنوان مفعول به بودن برای اسم فعل «علیک »، و میتوان آن را مرفوع خواندبعنوان فاعل بودن برای فعل کذب به معنی وجب . (از اقرب الموارد) (از منتهی الارب ). و رجوع به عَسْل شود.<br></font></div>'),
(183339, 'عسل', '<span class=\"hlight\">عسل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) ماده شتر تیزرو. (ناظم الاطباء). ناقه ٔ سریع. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) هلاکی و نگونساری : عسلاً له ؛ نگونساری و هلاکی باد او را! (از اقرب الموارد).<br></font></div>'),
(183340, 'عسل', '<span class=\"hlight\">عسل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) خوردنی ساختن به انگبین . (از منتهی الارب ). آمیختن طعام به انگبین . (از ناظم الاطباء). انگبین در طعام کردن . (تاج المصادر بیهقی ) (المصادر زوزنی ) (دهار): عسل الطعام َ؛ طعام را ساخت و آن را با عسل مخلوط کرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> توشه دادن کسی را به انگبین . (از منتهی الارب ). کسی را انگبین دادن . (المصادر زوزنی ): عسل القوم َ؛ آنان را با عسل توشه داد و عسل بدانها خورانید. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خوش ستودن . (از منتهی الارب ). ثنای نیکو کردن کسی را. <BR><font color=\"Blue\">◄</font> محبوب کردن نزد مردم : عسل اﷲ فلاناً؛ خداوند فلان را نزد مردم محبوب کرد. (از اقرب الموارد). عَسَل . و رجوع به عسل شود. <BR><font color=\"Blue\">◄</font> آرمیدن با زن . (از منتهی الارب ). مجامعت کردن . (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> پریشان دویدن و سر جنبانیدن و پویه دویدن گرگ و اسب و مردم . (از منتهی الارب ). پویه دویدن . (دهار). پوئیدن . (تاج المصادر بیهقی ). مضطرب گشتن گرگ یا اسب در دویدن، و حرکت دادن سر خود را. (از اقرب الموارد).عَسَلان . و رجوع به عسلان شود. <BR><font color=\"Blue\">◄</font> مضطرب گردیدن آب از جنبانیدن باد. (از منتهی الارب ). عَسَلان . و رجوع به عسلان شود. <BR><font color=\"Blue\">◄</font> شتابی نمودن : عسل الدلیل ُ بالمفازة؛ راهنما در بیابان شتابی نمود. (ازمنتهی الارب ). و رجوع به عَسَل شود. <BR><font color=\"Blue\">◄</font> سخت جنبیدن نیزه . (از ناظم الاطباء): عسل الرمح ؛ جنبیدن و اهتزاز آن نیزه سخت شد و مضطرب گشت . (از اقرب الموارد). عُسول . عَسَلان . و رجوع به عسول و عسلان شود.<br></font></div>'),
(183341, 'عسل', '<span class=\"hlight\">عسل .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع اِ) انگبین . (منتهی الارب ) (دهار). شهد. (غیاث اللغات ). لعاب زنبور عسل، مذکر و مؤنث آید و تذکیر آن بیشتر است . (از اقرب الموارد). شَوب . تصغیر آن عُسَیلة است . (دهار). أری . طِرم . مجاج النحل . ج، أعسال، عسل <font color=\"DarkGreen\"><b>[ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ س ُ ]</font></b>، عُسلان، عُسول . (منتهی الارب ) (اقرب الموارد). بپارسی انگبین و به هندوی ناکهو و مده هم گویند. و آن گرم و خشک است در دو درجه و لطیف است و امعاء را بشوید و بزداید و بادها را تحلیل کند. و در او حدتی است که بواسطه ٔ آن شکم براند. (از تذکره ٔ ضریر انطاکی ). بهترین آن صاف مایل بسرخی و قوام دار است که با اندک حدت و خوش طعمی و بی موم باشد و بعد از آن سفید، و زبون ترین او سبز و سیاه و خشک و تلخ و کهنه است که زیاده بر دو سال مانده باشد. (از تحفه ٔ حکیم مؤمن ). مایع کم وبیش غلیظ و شربتی شکل و شیرینی که زنبوران عسل بر اثر جمعآوری نوش  گلها در کندو بمنظور تغذیه ٔ افراد کندو تهیه میکنند. معمولاً عسل بوسیله ٔ زنبوران ماده ٔ عقیمی که کارگر نامیده میشوند از شیره ٔ گلها و برگها و دم برگهای نباتات جمعآوری میشود. زنبور کارگر شیره ٔ گیاهان را وارد دهانش کرده با آب دهان مخلوط میسازد و فرومیبرد و آن وارد محفظه ای بنام کیسه ٔ عسل که در شکمش قرار دارد، میگردد. قسمتی از این شیره ٔ گیاهی وارد روده ٔ زنبور شده به مصرف تغذیه ٔ خود زنبور میرسد و قسمت دیگر هم با انقباض کیسه ٔ عسل دوباره به دهان زنبور برمیگردد و زنبور آن را در حجره های خالی کندو که بهمین منظور ساخته است خالی میکند. این عسل بسیار رقیق است لیکن بر اثر حرارت کندو و مجاورت با هوا غلیظ میشود، و بعلاوه اختلاط آب دهان زنبور با شیره ٔ گل تغییرات شیمیائی در آن میدهد. این فعل وانفعالات هنوز کاملاً شناخته نشده است . پس از آنکه عسل در حجرات مسدسی شکل کندو حالت طبیعی بخود گرفت زنبور کارگر روی آن را ازیک طبقه موم می پوشاند. عسل بزحمت به دست می آید و فقط کوشش و پشت کار زنبوران کارگر است که موجب جمعآوری آن در مدتی بالنسبه کوتاه میشود. برای تهیه ٔ یک کیلوگرم عسل یک زنبور باید روی <span class=\"hlight\" dir=\"rtl\">٢</span>میلیون گل اقاقیا یا <span class=\"hlight\" dir=\"rtl\">٥</span>میلیون گل اسپرس بنشیند و <span class=\"hlight\" dir=\"rtl\">١٨٠</span>هزار مرتبه کیسه ٔ عسل خودرا پر و خالی کند. (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>هرچند حقیرم سخنم عالی و شیرین <br>آری عسل شیرین ناید مگر ازمنج .<br> <font color=\"Red\">منجیک .</font><br>بگوش در سخن حجت ای پسر عسلست <br>جز از سخن نخورد کس ز راه گوش عسل .<br> <font color=\"Red\">ناصرخسرو.</font><br>شهد کز حلق بگذرد زهر است <br>نام آن زهر پس عسل منهید.<br> <font color=\"Red\">خاقانی .</font><br>چون شمع ریزم از مژه سیلاب آتشین <br>زآن لب که آتش است و عسل میدهدبرت .<br> <font color=\"Red\">خاقانی .</font><br>آخر نامه نام تاج کنم <br>که عسل باشد آخر انهار.<br> <font color=\"Red\">خاقانی .</font><br>شیرینتر از این لب نشنیدم که سخن گفت <br>تو خود شکری یا عسل است آب دهانت ؟<br> <font color=\"Red\">سعدی .</font><br>باز بر خمره دوشاب زن و روغن خوش <br>آن زمان دست بسوی عسل و چربه درآر.<br> <font color=\"Red\">بسحاق .</font><br>جَث ّ؛ عسل که دارای شکافتگی باشد و موم و خاشاک و پرهای زنبور و ابدان زنبور در آن بود. خافة؛ خریطه ای که در آن عسل نهند. (از منتهی الارب ).<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عسل گوئی، دهان شیرین نگردد</span>، نظیر: از حلوا گفتن دهان کسی شیرین نشود. (فرهنگ عوام ). و رجوع به امثال و حکم دهخدا شود.<br>عسل نیست که انگشتش بزنند؛ این زن یا این دختر آنقدر هم سست عنصر نیست که کسی بتواند دامن شرافتش را لکه دار کند. (فرهنگ عوام ).<br> <span class=\"hlight\">عسل نیست که انگشت کنند</span> ؛ چرا نمی گذارید بدانجا برود. (امثال و حکم دهخدا).<br> <span class=\"hlight\">هرکه کاوش عسل کند انگشتی لیسد</span> (جامع التمثیل )، نظیر: هرکه گل کند گل خورد. (امثال و حکم دهخدا).<br> <span class=\"hlight\">عسل در باغ هست و غوره هم هست </span> <br>زلیخا هست و جان و جان کوره هم هست .<br> <font color=\"Red\">؟ (از امثال و حکم دهخدا).</font><br>زنش گفت بازی کنان شوی را<br> <span class=\"hlight\">عسل تلخ باشد ترشروی را</span> .<br> <font color=\"Red\">؟ (از امثال و حکم دهخدا).</font><br>- <span class=\"hlight\">زنبوربی عسل </span> ؛ زنبور که عسل ندهد <span class=\"hlight\">:</span> یکی راگفتند عالم بی عمل به چه ماند، گفت به زنبور بی عسل . (گلستان سعدی ).<br>- <span class=\"hlight\">زنبور عسل </span> ؛ منج . منج انگبین . منگ انگبین . زنبور انگبین . نحل . ذباب . (از منتهی الارب ). حشره ای است از راسته ٔ نازک بالان که دارای نژادهای مختلف است و از روی رنگشان تمیز داده میشوند. و از فواید آن تهیه ٔ عسل و موم است . (از فرهنگ فارسی معین ). و رجوع به زنبور شود <span class=\"hlight\">:</span> <br>از خانه ٔ مار آید زنبور عسل بیرون <br>گر یک رقم همت بر مار کشد عدلش .<br> <font color=\"Red\">خاقانی .</font><br>جَحل ؛ مهتر زنبوران عسل . (منتهی الارب ).<br>- <span class=\"hlight\">ماه عسل </span> ؛ در تداول امروز، آن یک ماه است که عروس و داماد بلافاصله پس از ازدواج به مسافرت روند و بگردش و تفریح پردازند، و آن از آداب و رسوم ممالک غربی است . (از فرهنگ فارسی معین ).<br><BR><font color=\"Blue\">◄</font> شبنم و تری اندک که بر شکوفه و جز آن گرد آید و زنبور عسل برگیرد، و آن بخاری است که برآید و در جوّ آسمان پخته گردد و مستحیل و درشت و سطبر گردد و عسل شده فروافتد، و گاهی در حقیقت انگبین گردیده و مردم برگیرند و بخورند و آن را ترنجبین و شیرخشت گویند. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> طبرزد و شیره ٔ قند و شیره ٔ نبات . (مخزن الادویة). <BR><font color=\"Blue\">◄</font> نی بوریا، که گیاهی است . (از فرهنگ فارسی معین ). رجوع به بوریا شود. <BR><font color=\"Blue\">◄</font> غوزه ٔ آب روان و خط آن . (منتهی الارب ). حباب آب آنگاه که حرکت میکند. (از اقرب الموارد). ژاله . <BR><font color=\"Blue\">◄</font> ذکر جمیل و طیب ثناء. (منتهی الارب ). ثنای نیکو بر شخص .(از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتر ماده ٔ تیزرو. عَسْل . و رجوع به عَسْل شود. <BR><font color=\"Blue\">◄</font> دوشاب خرمای تر. (منتهی الارب ). صقر و دوشاب رطب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> صیغ عرفط. (منتهی الارب ) (اقرب الموارد). رجوع به عرفط شود.<br></font></div>'),
(183342, 'عسل', '<span class=\"hlight\">عسل .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (اِخ ) ابن سفیان . رجوع به ابوقره شود.<br></font></div>'),
(183343, 'عسل', '<span class=\"hlight\">عسل .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (اِخ ) ابن ذَکوان عسکری، مکنی به ابوعلی . محدث و از اهالی عسکر مکرم بود. وی از مازنی و ریاشی و داماد روایت دارد. و در ایام مبرد در قید حیات بوده است . سال مرگ او به دست نیامد. او راست کتاب الجواب المسکت، و کتاب اقسام العربیة. (از معجم الادباء چ اروپا ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٥٦</span>).<br></font></div>'),
(183344, 'عسل', '<span class=\"hlight\">عسل .</span> <font color=\"DarkGreen\"><b>[ ع ُس ْ س َ ]</font></b> (ع ص، اِ) ج ِ عاسِل . (منتهی الارب ) (اقرب الموارد). رجوع به عاسل شود.<br></font></div>'),
(183345, 'عسل', '<span class=\"hlight\">عسل .</span> <font color=\"DarkGreen\"><b>[ ع ُ س ُ ]</font></b> (ع ص، اِ) ج ِ عاسِل . (منتهی الارب ). مردان صالح . واحد آن عاسل و عَسول . (از اقرب الموارد). رجوع به عاسل شود. <BR><font color=\"Blue\">◄</font> ج ِ عَسَل . (منتهی الارب ) (اقرب الموارد). رجوع به عسل شود. <BR><font color=\"Blue\">◄</font> ج ِ عَسول . (منتهی الارب ). رجوع به عَسول شود. <BR><font color=\"Blue\">◄</font> ج ِ عَسیل . (منتهی الارب ) (اقرب الموارد). رجوع به عسیل شود.<br></font></div>'),
(183346, 'عسل', '<span class=\"hlight\">عسل .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عَسَل .(منتهی الارب ) (اقرب الموارد). رجوع به عَسَل شود.<br></font></div>'),
(183347, 'عسل', '<span class=\"hlight\">عسل .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص، اِ) هو عسل مال ؛ یعنی او مقابل و برابر و قیم مال است .(منتهی الارب ). یعنی او خوب رعایت کننده است آن مال را. (از اقرب الموارد). ج، أعسال . (اقرب الموارد).<br></font></div>'),
(183348, 'عسل', '<span class=\"hlight\">عسل .</span> <font color=\"DarkGreen\"><b>[ ع َ س ِ ]</font></b> (ع ص ) سخت زننده و سبک دست . (منتهی الارب ). شخص شدیدالضرب، که دست او هنگام زدن بسرعت بازگردد. (از اقرب الموارد).<br></font></div>'),
(183349, 'عسل البلادر', '<span class=\"hlight\">عسل البلادر.</span> <font color=\"DarkGreen\"><b>[ ع َ س َلُل ْ ب َ دُ ]</font></b> (ع اِ مرکب ) رطوبت سیاهی است که در جوف بلادر است . (مخزن الادویة). ماده ٔ لزجی که در درون بلادر است به رنگ خون . رجوع به عسل بلادر و بلادر شود.<br></font></div>'),
(183350, 'عسل الحاج', '<span class=\"hlight\">عسل الحاج .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ لُل ْ ]</font></b> (ع اِ مرکب ) ترنجبین است . (فهرست مخزن الادویة). رجوع به ترنجبین شود.<br></font></div>'),
(183351, 'عسل الخلاف', '<span class=\"hlight\">عسل الخلاف .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ لُل ْ خ ِ ]</font></b> (ع اِ مرکب ) شیرخشتی است که از درخت بید بعمل می آید. (مخزن الادویة).<br></font></div>'),
(183352, 'عسل الرمث', '<span class=\"hlight\">عسل الرمث .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ لُرْ رِ ]</font></b> (ع اِ مرکب ) سپیدئی است مانند مروارید. (منتهی الارب ). چیزی است سپیدمانند جُمان و مروارید. (از اقرب الموارد). شبنمی است که بر درخت رمث نشیند، و آن چیزی است سفید و شیرین، و گفته اند که آن شکر تیغال است . (مخزن الادویة).<br></font></div>'),
(183353, 'عسل الطبرزد', '<span class=\"hlight\">عسل الطبرزد.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ لُطْ طَ ب َ زَ ]</font></b> (ع اِ مرکب ) شیره ٔ نبات . عسل طبرزد. رجوع به عسل طبرزد شود.<br></font></div>'),
(183354, 'عسل القسب', '<span class=\"hlight\">عسل القسب .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ لُل ْ ق َ ]</font></b> (ع اِ مرکب ) عسلی است که از خرمای خشک به طبخ و فشردن و به قوام آوردن بعمل آورند. (مخزن الادویة).<br></font></div>'),
(183355, 'عسل القصب', '<span class=\"hlight\">عسل القصب .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ لُل ْق َ ص َ ]</font></b> (ع اِ مرکب ) آب نیشکر. (تحفه ٔ حکیم مؤمن ) (فهرست مخزن الادویة). شکر. سکر. افشرده ٔ نیشکر. ماء قصب السکر. (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> و منهم من یغش المهلبیة بعسل القصب . (معالم القربة ص <span class=\"hlight\" dir=\"rtl\">١٠٧</span>).<br></font></div>'),
(183356, 'عسل اللبنی', '<span class=\"hlight\">عسل اللبنی .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ لُل ْ ل ُ نا ]</font></b> (ع اِ مرکب ) خوشبوئی است که عوام آن را حصی لبان و میعه ٔ سائلة نامند، و از درختی برآید و از آن بخار سازند. (منتهی الارب ). حصی لبان است، و بعضی گفته اندمیعه ٔ سائله است . (مخزن الادویة). طیب و عطری است که از درختی میتراود و بدان بخور کنند، و عامه آن را حصی البان گویند. (از اقرب الموارد از قاموس ). میعة. (اقرب الموارد). و رجوع به عسل لبن و عسل لبنی شود.<br></font></div>'),
(183357, 'عسل النحل', '<span class=\"hlight\">عسل النحل .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ لُن ْ ن َ ]</font></b> (ع اِ مرکب ) شهد است، که به هندی مده نامند. (فهرست مخزن الادویة). عسل زنبور عسل . عسل نحل . رجوع به عسل شود <span class=\"hlight\">:</span> <br>نزدیک عاقلان عسل النحلم <br>وَاندر گلوی جاهل غسلینم .<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(183358, 'عسل املج', '<span class=\"hlight\">عسل املج .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ اَ ل َ ]</font></b> (ترکیب اضافی، اِ مرکب ) عسل مربی به املج است . (از فهرست مخزن الادویة). و رجوع به املج شود.<br></font></div>'),
(183359, 'عسل انقردیا', '<span class=\"hlight\">عسل انقردیا.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ اَ ق َ ]</font></b> (ترکیب اضافی، اِ مرکب ) عسل بلادر. عسل البلادر. رجوع به عسل بلادر و عسل البلادر شود.<br></font></div>'),
(183360, 'عسل بلادر', '<span class=\"hlight\">عسل بلادر.</span> <font color=\"DarkGreen\"><b>[ ع َس َ ل ِ ب َ دُ ]</font></b> (ترکیب اضافی، اِ مرکب ) رطوبت سیاه چسبنده است که از بلادر برمی آید در حین فشار، و آن را دهن بلادر نیز نامند. (از مخزن الادویة). شیره ٔ بلادر. عسل البلادر. عسل انقردیا. رجوع به عسل البلادر و بلادر شود <span class=\"hlight\">:</span> و عسل بلادر برباید نهاد تا ریش گردد و پس ریش را به مرهم علاج کردن . (ذخیره ٔ خوارزمشاهی ).<br></font></div>'),
(183361, 'عسل بلیلج', '<span class=\"hlight\">عسل بلیلج .</span> <font color=\"DarkGreen\"><b>[ ع َ س َل ِ ب َ لی ل َ ]</font></b> (ترکیب اضافی، اِ مرکب ) مربی به بلیلج است . (فهرست مخزن الادویة). و رجوع به بلیلج شود.<br></font></div>'),
(183362, 'عسل تمر', '<span class=\"hlight\">عسل تمر.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ ت َ ]</font></b> (ترکیب اضافی، اِ مرکب ) سیلان تمر است، یعنی دوشاب خرما. (فهرست مخزن الادویة). و رجوع به تمر شود.<br></font></div>'),
(183363, 'عسل حاشا', '<span class=\"hlight\">عسل حاشا.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) عسلی که زنبور آن بر درخت حاشا نشسته باشد، و از ادویه ٔ تریاق اکبر است . و محرورین را مضر است . (از مخزن الادویة).<br></font></div>'),
(183364, 'عسل خشک', '<span class=\"hlight\">عسل خشک .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ خ ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) خشک انجبین است . (تحفه ٔ حکیم مؤمن ).و رجوع به عسل یابس و خشک انجبین و خشک انگبین شود.<br></font></div>'),
(183365, 'عسل دادن', '<span class=\"hlight\">عسل دادن .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ دَ ]</font></b> (مص مرکب ) عسل ساختن . به عمل آوردن عسل . تولید عسل کردن <span class=\"hlight\">:</span> <br>زنبور درشت بی مروت را گوی <br>باری چو عسل نمیدهی نیش مزن .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(183366, 'عسل داود', '<span class=\"hlight\">عسل داود.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ وو ]</font></b> (ترکیب اضافی، اِ مرکب ) روغنی باشد که از ساق درختی حاصل میشود و طعم آن شیرین است و به عربی دهن العسل و به یونانی اورمالی خوانند. (برهان ) (آنندراج ). دهن عسلی است که اولی نامند، و توهم کرده کسی که اورمالی و اومالی دانسته . (مخزن الادویة). اومالی . (تحفه ٔ حکیم مؤمن ). ماده ٔ کم وبیش لزج و شربتی شکل که در اواخر تابستان از تنه ٔ درختان خانواده ٔ زیتونیان درنتیجه ٔ نیش حشرات یا خراش پوست درخت خارج میشود. این ماده در برابر هوا منجمد شده شکل صمغمانند بخود میگیرد و محتوی <span class=\"hlight\" dir=\"rtl\">٥٢</span> درصد مواد قندی شیرین از قبیل ساکارز و لولز و گلوکز میباشد. اومالی . عسل درخت زیتون . عسل زیتون . (فرهنگ فارسی معین ).<br></font></div>'),
(183367, 'عسل درخت زیتون', '<span class=\"hlight\">عسل درخت زیتون .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ دِ رَ ت ِ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (ترکیب اضافی، اِ مرکب ) عسل داود. عسل زیتون . رجوع به عسل داود شود.<br></font></div>'),
(183368, 'عسل زا', '<span class=\"hlight\">عسل زا.</span><font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (نف مرکب ) عسل زاینده . ایجادکننده ٔ عسل .<br></font></div>'),
(183369, 'عسل زنجبیل', '<span class=\"hlight\">عسل زنجبیل .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ زَ ج َ ]</font></b> (ترکیب اضافی، اِ مرکب ) مربی به زنجبیل است . (از فهرست مخزن الادویة). و رجوع به زنجبیل شود.<br></font></div>'),
(183370, 'عسل زیتون', '<span class=\"hlight\">عسل زیتون .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (ترکیب اضافی، اِ مرکب )عسل داود. عسل درخت زیتون . رجوع به عسل داود شود.<br></font></div>'),
(183371, 'عسل شوکران', '<span class=\"hlight\">عسل شوکران .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> شُو ک َ ]</font></b> (ترکیب اضافی، اِ مرکب ) از ادویه است و محرورین را مضر است . (از فهرست مخزن الادویة).<br></font></div>'),
(183372, 'عسل صعتر', '<span class=\"hlight\">عسل صعتر.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ ص َ ت َ ]</font></b> (ترکیب اضافی، اِ مرکب ) از ادویه است و محرورین را مضر است . (از مخزن الادویة).<br></font></div>'),
(183373, 'عسل طبرزد', '<span class=\"hlight\">عسل طبرزد.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ طَ ب َ زَ ]</font></b> (ترکیب اضافی، اِ مرکب ) عسل الطبرزد. شیره ٔ نبات . (مخزن الادویة) (بحر الجواهر) (برهان قاطع) (آنندراج ). مایه ٔ نبات . آب نبات .<br></font></div>'),
(183374, 'عسل قصب', '<span class=\"hlight\">عسل قصب .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ ق َ ص َ ]</font></b> (ترکیب اضافی، اِ مرکب ) آب نیشکر به قوام آورده . (یادداشت مرحوم دهخدا). عسل القصب . و رجوع به عسل القصب شود.<br></font></div>'),
(183375, 'عسل لبن', '<span class=\"hlight\">عسل لبن .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ ل َ ب َ ]</font></b> (ترکیب اضافی، اِ مرکب ) نوعی از صمغ باشد که آن را مانند کندر بسوزانند، و بعربی میعه ٔ سائله خوانند. (برهان قاطع) (آنندراج ). عسل اللبنی . رجوع به عسل اللبنی شود.<br></font></div>'),
(183376, 'عسل لبنی', '<span class=\"hlight\">عسل لبنی .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِل ُ نا ]</font></b> (ترکیب اضافی، اِ مرکب ) میعه ٔ سائله . (تحفه ٔ حکیم مؤمن ). عسل اللبنی . رجوع به عسل اللبنی شود.<br></font></div>'),
(183377, 'عسل ماذی', '<span class=\"hlight\">عسل ماذی .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) عسل نحل .(مخزن الادویة). انگبین سفید. و رجوع به ماذی شود.<br></font></div>'),
(183378, 'عسل مصفی', '<span class=\"hlight\">عسل مصفی .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ م ُ ص َف ْ فا ]</font></b> (ترکیب وصفی، اِ مرکب ) عسل موم گرفته ٔ صاف کرده . (ناظم الاطباء). عسلی که مومش را گرفته و تصفیه کرده باشند. عسل پالوده . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> فیها انهار من ماء غیر آسن ... و انهار من عسل مصفی . (قرآن <span class=\"hlight\" dir=\"rtl\">١٥/٤٧</span>)؛ در آن است انهاری از آب نامتغیر و انهاری از عسل تصفیه شده .<br></font></div>'),
(183379, 'عسل هلیلج', '<span class=\"hlight\">عسل هلیلج .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ هََ لی ل َ ]</font></b> (ترکیب اضافی، اِ مرکب ) عسل مربی به هلیلج است . (از فهرست مخزن الادویة). و رجوع به هلیلج شود.<br></font></div>'),
(183380, 'عسل وار', '<span class=\"hlight\">عسل وار.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ص مرکب ) مانند عسل . (از فرهنگ فارسی معین ). چون عسل <span class=\"hlight\">:</span> تا از مفردات اجزاء آن مرکبی بفرط امتزاج عسل وار حاصل آمد. (مرزبان نامه ص <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(183381, 'عسل پالوده', '<span class=\"hlight\">عسل پالوده .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ترکیب وصفی، اِ مرکب ) عسل مصفی . (فرهنگ فارسی معین ). رجوع به عسل مصفی شود.<br></font></div>'),
(183382, 'عسل چین', '<span class=\"hlight\">عسل چین .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ]</font></b> (نف مرکب ) عسل چیننده . آنکه عسلهای ساخته شده را برمیدارد: خافة؛ جبه ٔ چرمین عسل چینان . (منتهی الارب ).<br></font></div>'),
(183383, 'عسل یابس', '<span class=\"hlight\">عسل یابس .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل ِ ب ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) خشکنگبین است، و طعام طیب رقیق را نامند. (مخزن الادویة). و رجوع به عسل خشک و خشک انگبین شود.<br></font></div>'),
(183384, 'عسلان', '<span class=\"hlight\">عسلان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عَسَل . (منتهی الارب ) (اقرب الموارد). رجوع به عسل شود.<br></font></div>'),
(183385, 'عسلان', '<span class=\"hlight\">عسلان .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع مص ) سخت جنبیدن نیزه . (از منتهی الارب ). جنبیدن نیزه . (المصادر زوزنی ). جنبانیدن نیزه . (تاج المصادر بیهقی ): عسل الرمح ؛ اهتزاز و جنبیدن نیزه سخت شد و مضطرب گشت . (از اقرب الموارد). عَسْل . عُسول . و رجوع به عَسْل و عُسول شود. <BR><font color=\"Blue\">◄</font> پریشان دویدن و سر جنبانیدن و پویه دویدن گرگ و اسب و مردم . (از منتهی الارب ). دویدن گرگ . (المصادر زوزنی ). پوئیدن . (تاج المصادربیهقی ): عسل الذئب أو الفرس ؛ گرگ یا اسب در دویدن خود مضطرب گشت و سر خود را در حال حرکت تکان داد. (از اقرب الموارد). عَسْل . و رجوع به عَسْل شود. <BR><font color=\"Blue\">◄</font> مضطرب گردیدن آب از جنبانیدن باد. (از منتهی الارب ): عسل الماء؛ باد آب را حرکت داد و آن مضطرب گشت . (از اقرب الموارد). عَسَل . و رجوع به عسل شود.<br></font></div>'),
(183386, 'عسلة', '<span class=\"hlight\">عسلة.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ل َ ]</font></b> (ع اِ) پاره ای از شهد، و آن اخص از عسل است . (منتهی الارب ). قطعه ای از عسل، چون ذهبة که قطعه ای است از زر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بیخ و بن : ما أعرف له مضرب عسلة، و ما لفلان مضرب عسلة؛ یعنی اصل و نسب او را، و آن فقط در نفی بکار رود. (از اقرب الموارد) (از منتهی الارب ).<br></font></div>'),
(183387, 'عسلة', '<span class=\"hlight\">عسلة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ل َ ]</font></b> (ع اِ) أبوعسلة؛ گرگ و ذئب . (از اقرب الموارد) (از ناظم الاطباء).<br></font></div>'),
(183388, 'عسلة', '<span class=\"hlight\">عسلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) از قرای یمن است از اعمال بَعدانیة. (از معجم البلدان ).<br></font></div>'),
(183389, 'عسلج', '<span class=\"hlight\">عسلج .</span> <font color=\"DarkGreen\"><b>[ ع َ س َل ْ ل َ ]</font></b>(اِخ ) قریه ای است دارای نخل و کشت که شعبه ای از چشمه ٔ مُحَلَّم آن را سیراب میکند. (از معجم البلدان ).<br></font></div>'),
(183390, 'عسلج', '<span class=\"hlight\">عسلج .</span> <font color=\"DarkGreen\"><b>[ ع َ س َل ْ ل َ ]</font></b> (ع ص ) طیب و نیکو از طعام، و گویند رقیق آن . (از اقرب الموارد).<br></font></div>'),
(183391, 'عسلج', '<span class=\"hlight\">عسلج .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل ُ ]</font></b> (ع ص ) قَوام عسلج ؛ قد نازک و نرم . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شباب عسلج ؛ جوان تمام و کامل . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) شاخ نرم و خمیده و سبز و آنچه نخستین برآید. (منتهی الارب ). آنچه نرم و سبز باشد از شاخه های درخت و رَز و آنچه ابتدا روئیده باشد، و گویندآن گیاهی است بر ساحل رودها که از شدت نرمی خمیده میگردد. (از اقرب الموارد). شاخ سبز و نرم و خمنده . ترکه . شولان . (یادداشت مرحوم دهخدا). عِسلاج . عُسلوج . عُسلوجة. ج، عَسالج، عَسالیج . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اسم مصری بیخ عرطنیثا است، و صنف اخیر بخور مریم را نیز نامند. (تحفه ٔ حکیم مؤمن ). صنف اخیر بخور مریم . (از فهرست مخزن الادویة). سلعی . کف الاسد.<br></font></div>'),
(183392, 'عسلق', '<span class=\"hlight\">عسلق .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ س َل ْ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ل ِ ]</font></b> (ع اِ) سراب . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گرگ . (منتهی الارب ). ذئب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شیر بیشه . <BR><font color=\"Blue\">◄</font> هر درنده ٔ شکاری . (منتهی الارب ). هر سَبُعی که بر صید و شکار جرأت کند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شترمرغ نر. <BR><font color=\"Blue\">◄</font> روباه . (منتهی الارب ). ثعلب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) بدسرشت و زشت . (منتهی الارب ). زشت آفرینش . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چست و چالاک . (منتهی الارب ). خفیف . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> درازگردن . (منتهی الارب ) (از اقرب الموارد). عُسالق . و رجوع به عُسالق شود. ج، عَسالق . (منتهی الارب ).<br></font></div>'),
(183393, 'عسلما', '<span class=\"hlight\">عسلما.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ س ِ ]</font></b> (ع اِ) درختچه ای است مشهور به کُتوس . رجوع به کتوس شود.<br></font></div>'),
(183394, 'عسلمیا', '<span class=\"hlight\">عسلمیا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام یکی از یاران کهف است . رجوع به مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">٢٢٠</span> شود.<br></font></div>'),
(183395, 'عسلوج', '<span class=\"hlight\">عسلوج .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) آنچه نرم و سبز باشد از شاخه های درخت و رَز و آنچه ابتدا روئیده باشد، و گویند آن گیاهی است بر ساحل رودها که از شدت نرمی خمیده گردد. (از اقرب الموارد). گویند: مات العسلوج ؛ یعنی شاخه خشک شد. (از اقرب الموارد). عُسلُج . عِسلاج . ج، عَسالج، عَسالیج . (اقرب الموارد). و رجوع به عسلج شود.<br></font></div>'),
(183396, 'عسلویه', '<span class=\"hlight\">عسلویه .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ی َ ]</font></b> (اِخ ) بندر و دهی از دهستان ثلاث بخش کنگان شهرستان بوشهر. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٩٠٠</span> تن . آب آن از چاه . محصول آن غلات، خرما، تنباکو و پیاز است . لنگرگاه این آبادی در داخل خلیج نای بند و پنج کیلومتر و نیمی ساحل به عمق پنج متر است و برای کشتی های کوچک مناسب میباشد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(183397, 'عسلی', '<span class=\"hlight\">عسلی .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ص نسبی ) منسوب به عسل . رجوع به عسل شود. <BR><font color=\"Blue\">◄</font> شبیه به عسل . (فرهنگ فارسی معین ). چون عسل .<br>- <span class=\"hlight\">تخم مرغ عسلی </span> ؛ تخم مرغ که اندکی پخته باشند تا سفیده و زرده ٔ آن به قوام آمده باشد. رجوع به تخم مرغ شود.<br> <BR><font color=\"Blue\">◄</font> به رنگ عسل . (از فرهنگ فارسی معین ). آنچه به رنگ عسل باشد. (از اقرب الموارد).<br>- <span class=\"hlight\">پشم عسلی </span> ؛ پشم زردفام و همرنگ عسل . (فرهنگ فارسی معین ).<br> <BR><font color=\"Blue\">◄</font> (اِ) علامت و نشان جهودان . (منتهی الارب ). پارچه ٔ زردی که یهودیان بجهت امتیاز بردوش جامه ٔ خود بدوزند. (از برهان ) (از غیاث اللغات ). پارچه ٔ زردی که یهودیان بجهت امتیاز از فریق دیگر بر دوش اندازند، و این لفظ عربی الاصل است، و آن را غیار گویند و لباس عسلی و جامه ٔ عسلی هم گویند. (از آنندراج ). نشان جهودان . (تفلیسی ). نشان یهود. (السامی ). پارچه ٔ زردی که اهل ذمه (مخصوصاً یهودیان ) جهت امتیاز بر دوش جامه میدوختند. (فرهنگ فارسی معین ). عسلی الیهود؛ علامتی است به رنگ عسل که یهودیان در قدیم برای مشخص بودن بر سر میگذاشتند. (از اقرب الموارد). آنچه یهود بر رخت خود دوزند امتیاز را. (فرهنگ خطی ) <span class=\"hlight\">:</span> <br>بی عسل و روغن است نانت و خوانْت <br>تا بستانی جهود را عسلی .<br> <font color=\"Red\">ناصرخسرو.</font><br>از غزل و می چو تیر و گُل نشود<br>پشت چو چوگان و روی چون عسلی .<br> <font color=\"Red\">ناصرخسرو.</font><br>چون عسلی شد رخانْت زرد چرا<br>با غزل و می بطبع چون عسلی .<br> <font color=\"Red\">ناصرخسرو.</font><br>پس بفرمود <font color=\"DarkGreen\"><b>[ متوکل ]</font></b> تا اهل ذمت را غیار برنهند و عسلی دارند جهود و ترسا. (مجمل التواریخ ).<br>ماخولیاگرفته و مصروع و گنده مغز<br>زرداب خورده چون عسلی پیس چون زنار.<br> <font color=\"Red\">سوزنی .</font><br>با برک گفت که دوزم عسلی ّ تو بدوش <br>که به سرما نکنم حرب بگاه پیکار.<br> <font color=\"Red\">نظام قاری .</font><br>طیلسان صوفی ارمک بُوَد از بندقیش <br>وز گلیم عسلی نیز ردائی دارد.<br> <font color=\"Red\">نظام قاری .</font><br>میان ما و مرقع محبت ازلیست <br>گوه ملمع رنگین و خرقه ٔ عسلیست .<br> <font color=\"Red\">نظام قاری .</font><br> <BR><font color=\"Blue\">◄</font> جامه ای که مخصوص گبران است . (برهان ) (آنندراج ). جامه ای است مخصوص گبران . (فرهنگ خطی ). اما ظاهراً بسط متساهلانه ٔ همان معنی اول است و عنایت به زنار، و در شواهد نیز <span class=\"hlight\">:</span> <br>آن حلاوت که تو داری چه عجب کز دستت <br>عسلی پوشد و زنار ببندد زنبور.<br> <font color=\"Red\">سعدی .</font><br>تو آن مبین که چو زنبور جامه ام عسلی است <br>که من ز بدو ازل بازبسته زنارم .<br> <font color=\"Red\">خواجه جمال الدین سلمان (از آنندراج ).</font><br><BR><font color=\"Blue\">◄</font> رنگی است که بیشتر فقیران هند و گبران بدان رنگ جامه پوشند. (برهان ) (آنندراج ). <BR><font color=\"Blue\">◄</font> در اصطلاح امروزین، چهارپایه ای بی پشت و دستگیره، نشستن را. (یادداشت مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> میز کوچک . (فرهنگ فارسی معین ).<br></font></div>'),
(183398, 'عسلی', '<span class=\"hlight\">عسلی .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (اِخ ) نام او شکری (بک )بن علی بن محمدبن عبدالکریم بن طالب عسلی است که از زعمای نهضت جدید عربی و از شهیدان راه آزادی بوده است . وی بسال <span class=\"hlight\" dir=\"rtl\">١٢٨٥</span> هَ .ق . در دمشق متولد شد و از مدارس آنجا و آستانه فارغ التحصیل گشت . سپس به نمایندگی مجلس شورای عثمانی از طرف مردم دمشق انتخاب شد. آنگاه وکیل مدافع گشت و مدتی نیز روزنامه ٔ «القبس » را منتشر ساخت . و درجنگ بین المللی اول محکوم به اعدام گردید و به سال <span class=\"hlight\" dir=\"rtl\">١٣٣٤</span> هَ .ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٩١٦</span> م . این حکم اجرا شد. او نخستین کسی است که در مجلس شورای عثمانی از فعالیت های صهیونیها پرده برداشت و تمبرهایی را نشان داد که در پست خودبکار میبرده اند. او راست : القضاة و النواب، الخراج فی الاسلام، المأمون العباسی که داستانی است . (از الاعلام زرکلی از منتخبات التواریخ لدمشق، و ایضاحات عن المسائل السیاسیة، و نبذة من وقائع الحرب الکونیة).<br></font></div>'),
(183399, 'عسلی رنگ', '<span class=\"hlight\">عسلی رنگ .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ رَ ]</font></b> (ص مرکب ) آنچه به رنگ عسل باشد. رجوع به عسلی شود. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) جامه ٔ درویشان . (ناظم الاطباء).<br></font></div>'),
(183400, 'عسم', '<span class=\"hlight\">عسم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) طمع کردن و آز داشتن . و گویند: هذا الامر لایعسم فیه ؛ یعنی در غلبه کردن و چیره شدن بر این امر طمعی نیست .(از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ورزیدن . (از منتهی الارب ). جمع کردن و کسب کردن . (تاج المصادر بیهقی ). ورزیدن و کسب کردن . (ناظم الاطباء). کسب کردن . (از اقرب الموارد). عُسوم . و رجوع به عسوم شود. <BR><font color=\"Blue\">◄</font> اشک افکندن و فروخوابیدن چشم، یابر هم نشستن پلک . (منتهی الارب ): عسمت عینه ؛ چشم او اشک ریخت، و گویند بر هم گذاشته شد، و گویند پلکهای آن بر یکدیگر فروافتاد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کوشش کردن در کار. (از منتهی الارب ): عسم فی الامر؛ در آن کار کوشید و خود را بر آن واداشت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بی باکانه در آمدن در قوم و آمیختن با آنها، عام است از جنگ و غیر آن . (از منتهی الارب ): عسم الرجل بنفسه وسط القوم ؛ آن شخص وارد آن قوم شد بطوری که با آنان درآمیخت بدون توجه و اهمیت، در جنگ یا غیر جنگ . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) ج ِ عَسمة. (منتهی الارب ). رجوع به عسمة شود.<br></font></div>'),
(183401, 'عسم', '<span class=\"hlight\">عسم .</span> <font color=\"DarkGreen\"><b>[ ع ُ س ُ ]</font></b> (ع ص، اِ) ج ِ عَسوم . (منتهی الارب ) (از اقرب الموارد). رجوع به عسوم شود. <BR><font color=\"Blue\">◄</font> ج ِ عاسِم . (ناظم الاطباء). رجوع به عاسم شود.<br></font></div>'),
(183402, 'عسم', '<span class=\"hlight\">عسم .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع مص ) خشک شدن دست و قدم و کج گردیدن آن . (از منتهی الارب ): عسم القدم و الکف ؛ مفصل و پیوندگاه دست یا پا خشک شد آنچنانکه کف قدم یا پا کج گردید، و چنین شخصی را در مذکر اعسم و در مؤنث عَسماء گویند. (از اقرب الموارد).<br></font></div>'),
(183403, 'عسم', '<span class=\"hlight\">عسم .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع اِمص ) خشکی است در بند دست و پا که از آن دست و پا کژ گردد. (منتهی الارب ) (از اقرب الموارد). اسم است مصدر عسم را، گویند: فی یده أو قدمه عسم . (از اقرب الموارد). و رجوع به عسم (ع مص ) شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(183404, 'عسمان', '<span class=\"hlight\">عسمان .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b>(ع اِمص ) «خَبَب » ستور که نوعی از دویدن است . (منتهی الارب ). خبب ستور و یورتمه ٔ ستور. (ناظم الاطباء).<br></font></div>'),
(183405, 'عسمان', '<span class=\"hlight\">عسمان .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع مص ) یورتمه رفتن ستور. (از ناظم الاطباء) (از اقرب الموارد).<br></font></div>'),
(183406, 'عسمة', '<span class=\"hlight\">عسمة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع اِ) یک خوردنی، هرچه باشد. (منتهی الارب ). أکلة. (اقرب الموارد): ماذاق الا عسمة؛ نچشید مگر یک خوردنی را. (از اقرب الموارد) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> پاره ٔ نان خشک . (منتهی الارب ). ج، عَسْم، و عُسوم . (منتهی الارب ).<br></font></div>'),
(183407, 'عسمة', '<span class=\"hlight\">عسمة.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ م َ ]</font></b> (ع اِ) ریزه ٔ نان خشک . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183408, 'عسمی', '<span class=\"hlight\">عسمی .</span> <font color=\"DarkGreen\"><b>[ ع َ می ی ]</font></b> (ع ص نسبی ) نیکوکننده ٔ امور خود. (منتهی الارب ). مصلح امور خویش را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کج و خراب کننده امور خود را. از لغات اضداد است . <BR><font color=\"Blue\">◄</font> فریبنده . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183409, 'عسن', '<span class=\"hlight\">عسن .</span> <font color=\"DarkGreen\"><b>[ ع ُس ُ ]</font></b> (ع مص ) گواریدن آب و علف و درخوردن آن در ستور. (منتهی الارب ). گوارائی آب و علف و درخور آن برای ستور. (ناظم الاطباء). سود رساندن علف برای چارپا. (ازاقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) پیه کهنه . (غیاث اللغات ). پیه دیرینه . (منتهی الارب ). شحم قدیم . اُسُن . (از اقرب الموارد): سمنت الدابة علی عسن ؛ آن چارپابر شحم و پیهی که پیش ازین بوده است فربه گشت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> فربهی . (منتهی الارب ).<br></font></div>'),
(183410, 'عسن', '<span class=\"hlight\">عسن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) فربهی و پیه . (منتهی الارب ). سمن و شحم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیه دیرینه . (منتهی الارب ): سمنت الدابة علی عسن ؛ آن چارپا بر شحم و پیهی که پیش ازین بوده است، فربه گشت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> همتا و مانند. (منتهی الارب ).<br></font></div>'),
(183411, 'عسن', '<span class=\"hlight\">عسن .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) نام جایگاهی است مشهور. (از معجم البلدان ).<br></font></div>'),
(183412, 'عسن', '<span class=\"hlight\">عسن .</span> <font color=\"DarkGreen\"><b>[ع َ س ِ ]</font></b> (ع ص ) ستور به اندک علف بسندکننده و اندک پذیر. (منتهی الارب ). دابه ٔ شکور. (از اقرب الموارد).<br></font></div>'),
(183413, 'عسن', '<span class=\"hlight\">عسن .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) همتا و مانند. (منتهی الارب ). مثل و نظیر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیه . (منتهی الارب ). شحم . (اقرب الموارد). ج، أعسان . (منتهی الارب ): سمنت الدابة علی عسن ؛ آن چهارپا بر شحم و پیهی که پیش ازین بوده است فربه گشت . (از اقرب الموارد).<br></font></div>'),
(183414, 'عسن', '<span class=\"hlight\">عسن .</span><font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع مص ) گواریدن آب و علف و درخوردن آن درستور. (منتهی الارب ). گوارائی آب و علف و درخور آن برای ستور. (ناظم الاطباء). عُسُن . رجوع به عسن شود.<br></font></div>'),
(183415, 'عسن', '<span class=\"hlight\">عسن .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) درازی با خوبی موی و حسن سپیدی . (منتهی الارب ). طول همراه با حسن موی و سپیدی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیه . (منتهی الارب ). شحم . (اقرب الموارد). پیه کهنه . (مخزن الادویة). <BR><font color=\"Blue\">◄</font> همتا و مانند. (منتهی الارب ).<br></font></div>'),
(183416, 'عسن', '<span class=\"hlight\">عسن .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع مص ) گوارا شدن آب و علف شتران را و فربه شدن آنها. (از ناظم الاطباء): عسن الکلأ و الرعی فی الدابة؛ علف و چرا در آن چهارپا سود بخشید و فربه گشت . (از اقرب الموارد).<br></font></div>'),
(183417, 'عسنب', '<span class=\"hlight\">عسنب .</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ ]</font></b> (ع اِ) گیاهی است از رده ٔ دولپه ایهای پیوسته گلبرگ که سردسته ٔ گل استکانیها میباشد. در حدود <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> نوع از این گیاه شناخته شده است که در نیمکره ٔ شمالی زمین در مناطق کوهستانی و معتدل پراکنده اند. برگهای آن متناوب و گلهایش بشکل زنگوله و غالباً سفیدرنگ و پنج قسمتی است . تعداد پرچمها نیز پنج عدد است . ساقه ٔ زیرزمینی این گیاه جزو سبزیهای خوراکی است و به مصرف تغذیه میرسد. این گیاه را بعنوان یک گل زینتی در باغچه ها نیز میکارند. یکی از انواع گیاه مذکور گل کف مریم است که ساقه ٔ زیرزمینی آن را در سالاد ریز کرده میخورند و بعلاوه یکی از گلهای زینتی زیبا میباشد که گلهایی به رنگ های آبی و سفید و بنفش دارد. گل استکانی . گل زنگوله . سریس . خبزالعقاب . (از فرهنگ فارسی معین ).<br></font></div>'),
(183418, 'عسنج', '<span class=\"hlight\">عسنج .</span> <font color=\"DarkGreen\"><b>[ ع َ س َن ْ ن َ ]</font></b> (ع اِ) شترمرغ نر. (منتهی الارب ). ظلیم . (اقرب الموارد).<br></font></div>'),
(183419, 'عسنق', '<span class=\"hlight\">عسنق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ن ُ ]</font></b> (ع ص ) تمام اندام نیکو و خوب روی . (منتهی الارب ). تام و کامل در حسن . (از اقرب الموارد).<br></font></div>'),
(183420, 'عسنی', '<span class=\"hlight\">عسنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) محمدبن اسعدبن عبداﷲبن سعید مذحجی عسنی . از قاضیان و فقیهان یمن بود و مدتی قضاوت عدن را نیز بعهده داشت و به سال <span class=\"hlight\" dir=\"rtl\">٦٦١</span> هَ .ق . در این شهر درگذشت . او را کتابی در اصول فقه و کتابی در فروع فقه است . (از الاعلام زرکلی از العقود اللؤلؤیة).<br></font></div>'),
(183421, 'عسو', '<span class=\"hlight\">عسو.</span> <font color=\"DarkGreen\"><b>[ ع ُ س ُوو ]</font></b> (ع مص ) کلانسال گردیدن . (منتهی الارب ) (از اقرب الموارد). کلانسال گردیدن و پیر شدن و سست و ناتوان گردیدن از بسیاری ِ عمر. (ناظم الاطباء). عَسْو. عُسی ّ. عَساء. عَسْوة. و رجوع به عَسْو و عُسی ّ و عَساء و عَسْوة شود. <BR><font color=\"Blue\">◄</font> درشت و خشک گردیدن نبات و سطبر شدن . (از منتهی الارب ). سخت خشک شدن و زفت شدن نبات . (تاج المصادر بیهقی ). ضخیم و سخت شدن گیاه . (از اقرب الموارد). عُساء. و رجوع به عُساء شود. <BR><font color=\"Blue\">◄</font> درشت شدن دست از کار. (از منتهی الارب ) (تاج المصادر بیهقی ). ضخیم شدن دست از کار. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نیک تاریک گشتن شب . (از منتهی الارب ). سخت شدن تاریکی شب . (از اقرب الموارد). تاریک شدن شب . (تاج المصادر بیهقی ).<br></font></div>'),
(183422, 'عسو', '<span class=\"hlight\">عسو.</span> <font color=\"DarkGreen\"><b>[ ع َس ْوْ ]</font></b> (ع اِ) شمع. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شمع مومی . <BR><font color=\"Blue\">◄</font> موم . (ناظم الاطباء).<br></font></div>'),
(183423, 'عسو', '<span class=\"hlight\">عسو.</span> <font color=\"DarkGreen\"><b>[ع َس ْوْ ]</font></b> (ع مص ) کلانسال گردیدن . (از منتهی الارب ). مسن شدن . (از اقرب الموارد). عُسوّ. عُسی ّ. عَساء. عَسْوه . رجوع به عسوّ و عُسی ّ و عَساء و عَسْوة شود.<br></font></div>'),
(183424, 'عسوب', '<span class=\"hlight\">عسوب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) سردار کلان . (منتهی الارب ). سردار کلان و سید و رئیس . (ناظم الاطباء). رئیس کبیر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پادشاه زنبوران عسل و یعسوب . (ناظم الاطباء). و رجوع به یعسوب شود.<br></font></div>'),
(183425, 'عسود', '<span class=\"hlight\">عسود.</span> <font color=\"DarkGreen\"><b>[ ع ِس ْ وَدد ]</font></b> (ع اِ) کربسه ٔ نر.(منتهی الارب ). چلپاسه ٔ نر. (ناظم الاطباء). نر و عضرفوط از کربسه و عظاء، و گویند دساس و کرمی خبیث است که در استخوانها یافت شود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مار. (منتهی الارب ). حیة. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) درشت و توانا و استوار از مردم و جز آن . (منتهی الارب ). قوی و شدید. (از اقرب الموارد).<br></font></div>'),
(183426, 'عسودات', '<span class=\"hlight\">عسودات .</span> <font color=\"DarkGreen\"><b>[ ع ِس ْ وَدْ دا ]</font></b> (ع اِ) ج ِ عِسودّة. (منتهی الارب ) (از اقرب الموارد). رجوع به عسودة شود.<br></font></div>'),
(183427, 'عسوس', '<span class=\"hlight\">عسوس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) شتر ماده ٔ تنهاچرنده . (منتهی الارب ).ناقه ای که به تنهائی بچرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناقه ٔ کم شیر، یا شتر ماده که تا از مردمان دور نشود شیر ندهد. <BR><font color=\"Blue\">◄</font> ناقه ای که هرگاه برانگیخته شود بگردد، سپس آن شیر دهد. <BR><font color=\"Blue\">◄</font> ناقه ٔ بدخوی در دوشیدن . <BR><font color=\"Blue\">◄</font> ناقه ای که استخوان طلب کند و آن را بخورد. <BR><font color=\"Blue\">◄</font> ناقه ای که بیازمایند او را که آیا شیر دارد یا نه . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زن بی باک از مردان . (منتهی الارب ). زنی که اهمیت نمیدهد از اینکه به مردان نزدیک شود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد کم خیر. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد به شب جوینده شکار و گشت کننده . (منتهی الارب ). طالب صید. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گرگ . (منتهی الارب ). گرگ طلب کننده ٔ صید. (از اقرب الموارد).<br></font></div>'),
(183428, 'عسوف', '<span class=\"hlight\">عسوف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) سخت ستمکار. (منتهی الارب ). ظَلوم . (اقرب الموارد). بیدادگر. <BR><font color=\"Blue\">◄</font> گیرنده به سختی و قوت، گویند: سلطان عسوف و عَسّاف . (از اقرب الموارد). سخت گیرنده . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بیراه . (منتهی الارب ).<br></font></div>'),
(183429, 'عسوفة', '<span class=\"hlight\">عسوفة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ف َ ]</font></b> (ع مص ) قریب به مرگ رسیدن شتر از غده و طاعون، پس لرزیدن ْ گرفتن ِ گلوی او و دم سخت برآوردن بشتاب . (از منتهی الارب ): عسف البعیر؛ آن شتر مشرف به مرگ شد از غده، پس در حال نفس کشیدن حنجره ٔ او لرزیدن گرفت . (از اقرب الموارد). عَسف . عُساف . رجوع به عسف و عساف شود.<br></font></div>'),
(183430, 'عسول', '<span class=\"hlight\">عسول .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عَسَل . (منتهی الارب ) (اقرب الموارد). رجوع به عسل شود.<br></font></div>'),
(183431, 'عسول', '<span class=\"hlight\">عسول .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) سخت جنبیدن نیزه . (از منتهی الارب ): عسل الرمح ؛ اهتزاز آن نیزه شدید شد. (از اقرب الموارد). عَسْل . عَسَلان . و رجوع به عَسْل و عسلان شود.<br></font></div>'),
(183432, 'عسول', '<span class=\"hlight\">عسول .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) نیزه ٔ جنبان . (منتهی الارب ). سخت اهتزاز. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد نیک صالح . (منتهی الارب ). واحد عُسُل یعنی مردان صالح . (از اقرب الموارد). ج، عُسُل . (منتهی الارب ).<br></font></div>'),
(183433, 'عسوم', '<span class=\"hlight\">عسوم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ریزه ٔ نان خشک . (منتهی الارب ). تکه های نان خشک . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) قلت و کمی . (منتهی الارب ): قلّت بِه عسوم ؛ دراو قلت و کمی است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) ج ِ عَسَمة. (منتهی الارب ). رجوع به عسمة شود.<br></font></div>'),
(183434, 'عسوم', '<span class=\"hlight\">عسوم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) ورزیدن . (از منتهی الارب ). کسب کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اشک افکندن و فروخوابیدن چشم، یا بر هم نشستن پلک . (از منتهی الارب ): عسمت عینه ؛ چشم او اشک ریخت، و گویند بر هم گذاشته شد، و گویند پلکهای آن بر یکدیگر فروافتاد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کوشش کردن در کار. (از منتهی الارب ): عسم فی الامر؛ در آن کار کوشید و خود را بر آن واداشت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بی باکانه درآمدن در قوم و آمیختن با آنها، عام است از جنگ و غیر آن . (از منتهی الارب ): عسم الرجل بنفسه وسط القوم ؛ آن شخص وارد آن قوم شد بطوری که با آنان درآمیخت بدون توجه و اهمیت دادن، در جنگ یا غیر جنگ . (از اقرب الموارد). عَسم . و رجوع به عسم شود.<br></font></div>'),
(183435, 'عسوم', '<span class=\"hlight\">عسوم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) رنج و سختی رساننده بر عیال . (منتهی الارب ). زحمت کشنده بر عیال و خانواده ٔ خود. (از اقرب الموارد). ج، عُسُم . <BR><font color=\"Blue\">◄</font> شتر ماده ٔ بسیاربچه . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183436, 'عسک', '<span class=\"hlight\">عسک .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع مص ) چسبیدن و لازم شدن . (از منتهی الارب ). ملازم گشتن و ملتصق شدن به چیزی . (از اقرب الموارد).<br></font></div>'),
(183437, 'عسکبة', '<span class=\"hlight\">عسکبة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ک ِ ب َ ]</font></b> (ع اِ) خوشه ٔ خرد انگور به خوشه ٔ بزرگ پیوسته، و گویند که در آن ده حبه است . (از منتهی الارب ). عسقبة است و گویند ده حبه در آن است . (از اقرب الموارد). و رجوع به عِسْقِبة شود.<br></font></div>'),
(183438, 'عسکر', '<span class=\"hlight\">عسکر.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (معرب، اِ) لشکر، و کلمه ٔ فارسی است . (از دهار) (از اقرب الموارد) (از منتهی الارب ). معرب لشکر است . (آنندراج ) (غیاث اللغات ). جند. سپاه . اصل آن لشکر است . (جمهره ٔ ابن درید از سیوطی ). ابن قتیبه، عسکر را فارسی دانسته است و ابن درید آن را همان «لشکر» فارسی نوشته است بمعنی مجتمع و گروه سپاهیان . (از المعرب جوالیقی ). ج، عساکر <span class=\"hlight\">:</span> <br>طبع کافی که عسکر هنر است <br>چون نی عسکری همه شکر است .<br> <font color=\"Red\">خاقانی .</font><br>بالای هفت خیمه ٔ فیروزه دان ز قدر<br>میدانگهی که هست در آن عسکر سخاش .<br> <font color=\"Red\">خاقانی .</font><br><BR><font color=\"Blue\">◄</font> گروه . (منتهی الارب ). جمع. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بسیار از هر چیزی . <BR><font color=\"Blue\">◄</font> تاریکی شب . (منتهی الارب ) (از اقرب الموارد). ج، عَساکر. (اقرب الموارد) (دهار).<br></font></div>'),
(183439, 'عسکر', '<span class=\"hlight\">عسکر.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) ابن حصین (یا ابن محمدبن حسین ) نخشبی، مکنی به ابوتراب . از مشایخ خراسان در قرن سوم هجری . رجوع به ابوتراب (عسکربن ...) و مآخذ ذیل شود: الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٥</span>، الکواکب الدریة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٢</span>، مفتاح السعادة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٤</span>.<br></font></div>'),
(183440, 'عسکر', '<span class=\"hlight\">عسکر.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) شهری است به خوزستان . (منتهی الارب ) <span class=\"hlight\">:</span> <br>ششتر چو رخ تو ندید دیبا<br>عسکر چو لب تو ندید شکّر<br>با دو رخ و با دو لب تو ما را<br>ایوان همه چون ششتر است و عسکر.<br> <font color=\"Red\">قطران .</font><br>بگفتار خیر و بدیدار حق <br>زبان عسکر و چشمها شوش کن .<br> <font color=\"Red\">ناصرخسرو.</font><br>زین پس خراج عیدی و نوروزی آورند<br>از بیضه ٔ عراق و ز بیضای عسکرش .<br> <font color=\"Red\">خاقانی .</font><br>فتح آنچنان کند ید بیضای عسکرش <br>کآسیب آن به عسکر و بیضا برافکند.<br> <font color=\"Red\">خاقانی .</font><br>و رجوع به عسکر مکرم و عسکری شود.<br>- <span class=\"hlight\">نی عسکر</span> ؛ نیشکر عسکری . نی که از عسکر آرند <span class=\"hlight\">:</span> <br>نی نی بدولت تو امیر سخن منم <br>عسکرکش من این نی عسکر نکوتر است .<br> <font color=\"Red\">خاقانی .</font><br> <BR><font color=\"Blue\">◄</font> در بیت ذیل از سوزنی بمناسبت شکرخیز بودن خوزستان و شهر عسکر یا عسکر مکرم آنجا کلمه ٔ عسکر در مصراع دوم ظاهراً معنی شکر دارد <span class=\"hlight\">:</span> <br>بارگه عسکریست دو لب شیرینْت <br>پاره ٔ عسکر مگر به لب زده داری . <br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(183441, 'عسکر ابی جعفر', '<span class=\"hlight\">عسکر ابی جعفر.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ رِ اَ ج َ ف َ ]</font></b> (اِخ ) منظور ابوجعفر منصور عبداﷲبن محمد است، و آن اشاره به شهر اوست که در بغداد ساخته است و امروزه باب البصره در جانب غربی، و نواحی آن است . منصور با لشکر خود در آنجا فرودآمده است لذا بدین نام منسوب گشت . (از معجم البلدان ).<br></font></div>'),
(183442, 'عسکر المهدی', '<span class=\"hlight\">عسکر المهدی .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ رُل ْ م َ دی ی ]</font></b> (اِخ ) منظور محمدبن منصور خلیفه است، و آن اکنون مشهوربه رصافة است از محله های جانب شرقی در بغداد. و به سال <span class=\"hlight\" dir=\"rtl\">١٥١</span> هَ .ق . که المهدی بقصد ری لشکرکشی میکرد در این محله فرودآمد لذا بدین نام شهرت یافت . (از معجم البلدان ). جانب خاوری بغداد در آغاز امر به عسکر مهدی یعنی اردوگاه مهدی موسوم بود زیرا به امر مهدی خلیفه ٔ عباسی پسر منصور آن را ساختند و در آنجا قصری برای وی ساخته شد و مسجد جامعی نیز در آن محل بنا گردید. (از جغرافیای تاریخی سرزمینهای خلافت شرقی ص <span class=\"hlight\" dir=\"rtl\">٣٣</span>).<br></font></div>'),
(183443, 'عسکر مکرم', '<span class=\"hlight\">عسکر مکرم .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ رِ م ُ رَ ]</font></b> (اِخ ) شهری است مشهور از نواحی خوزستان، منسوب به مکرم بن معزاء حارث، یکی از افراد بنی جَعْوَنةبن حارث بن نُمَیربن عامربن صعصعة. (از معجم البلدان ). شهری است معروف، و گویا معرب است . (از المعرب جوالیقی ). شهری است <font color=\"DarkGreen\"><b>[ از شهرهای ناحیت خوزستان ]</font></b> با سواد بسیار و خرم و آبادان و بانعمت، و همه ٔ شکرهای جهان سرخ و سپید و قند از آنجا افتد. (حدود العالم چ دانشگاه ص <span class=\"hlight\" dir=\"rtl\">١٣٨</span>). و آن اندر میان دو رود شوشتر و مَسرُقان واقع است . (از حدود العالم ص <span class=\"hlight\" dir=\"rtl\">٤٥</span> و <span class=\"hlight\" dir=\"rtl\">٤٦</span>). یکی ازنه قریه و ده اهواز، واقع میان شوشتر و رامهرمز. (یادداشت مرحوم دهخدا). وجه تسمیه ٔ عسکر مکرم این است که حجاج عامل معروف بنی امیه در عراق یکی از سرکردگان عرب را بنام مکرم برای خاموش کردن فتنه ای به خوزستان گسیل داشت و سردار مزبور نزدیک خرابه های شهری که به فارسی رستم گواد نام داشت و اعراب آن را «رستاقباذ» نامیدند مستقر شد و این مکان بعدها به عسکر مکرم، یعنی اردوگاه مکرم، معروف گردید. اکنون نام عسکر مکرم در نقشه ها دیده نمیشود ولی بجای آن خرابه های بندقیر است که در آنجا آب گرگر (مسرقان ) به کارون میریزد.در قرن چهارم هجری عسکر مکرم شهری بود بر دو جانب نهر مسرقان و جانب غربی آن بزرگتر بود و بوسیله ٔ دو جسر بزرگ که از قایق های بهم بسته تعبیه شده بود به جانب دیگر اتصال داشت . شهر دارای بازاری باشکوه بود که با مسجد جامع هر دو در جانب غربی واقع بودند. ازجمله ٔ عیوب عسکر مکرم وجود عقربهای سمی در آن شهر بود که هیچکس از گزند آنان بی نصیب نمی ماند. حمداﷲ مستوفی گوید: «شاپور ذوالاکتاف تجدید عمارتش کرد و برج شاپور خوانند بر دو جانب آب دودانگه ٔ تستر نهاده است و در اول به لفظ لشکر خواندند و لشکربن طهمورث دیوبند ساخته، شهری بزرگ است، از همه ٔ ولایت خوزستان هوای آن خوشتر است ». و در این شهر از ابریشم خام مقنعه و دستمال و پارچه میساختند. (جغرافیای تاریخی سرزمینهای خلافت شرقی ص <span class=\"hlight\" dir=\"rtl\">٢٥٥</span> و <span class=\"hlight\" dir=\"rtl\">٢٦٥</span>). و رجوع به عسکر و عسکری شود.<br></font></div>'),
(183444, 'عسکر نیشابور', '<span class=\"hlight\">عسکر نیشابور.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ رِ ن َ]</font></b> (اِخ ) محله ای بوده است به نیشابور، شهر مشهور قدیم خراسان . (از معجم البلدان ). و رجوع به عسکر شود.<br></font></div>'),
(183445, 'عسکرآباد', '<span class=\"hlight\">عسکرآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) دهی از دهستان تحت جلگه ٔ بخش فدیشه ٔ شهرستان نیشابور. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٢٧</span> تن . آب آن از قنات . محصول آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183446, 'عسکرآباد', '<span class=\"hlight\">عسکرآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) دهی از دهستان جعفرآباد فاروج بخش حومه ٔ شهرستان قوچان . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٤٩٧</span> تن . آب آن از چشمه . محصول آن غلات و بنشن است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>)<span class=\"hlight\" dir=\"rtl\">٠</span><br></font></div>'),
(183447, 'عسکرآباد', '<span class=\"hlight\">عسکرآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) دهی از دهستان نورعلی بخش دلفان شهرستان خرم آباد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٢٠</span> تن . آب آن از چشمه ها. محصول آن غلات و توتون است . ساکنان این ده از طایفه ٔ نورعلی هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(183448, 'عسکرآباد', '<span class=\"hlight\">عسکرآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) دهی از دهستان سلگی شهرستان نهاوند. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٣٢٠</span> تن . آب آن از چشمه . محصول آن غلات، توتون، حبوب و لبنیات است . (از فرهنگ جغرافیای ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(183449, 'عسکرآباد', '<span class=\"hlight\">عسکرآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) دهی از دهستان اواوغلی بخش حومه ٔ شهرستان خوی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٥٤</span> تن . آب آن از چشمه . محصول آن غلات و انگور و زردآلو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(183450, 'عسکرآباد', '<span class=\"hlight\">عسکرآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) دهی از دهستان ملایعقوب بخش مرکزی شهرستان سراب . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٨١٧</span> تن . آب آن از رودخانه و قنات . محصول آن غلات و بزرک است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(183451, 'عسکرآباد', '<span class=\"hlight\">عسکرآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) دهی از دهستان قره طقان بخش بهشهر شهرستان ساری . سکنه ٔ <span class=\"hlight\" dir=\"rtl\">١٧٠</span> تن . آب آن از رودخانه ٔ نکا و چشمه . محصول آن برنج و غلات و پنبه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>)<span class=\"hlight\" dir=\"rtl\">٠</span><br></font></div>'),
(183452, 'عسکرآباد', '<span class=\"hlight\">عسکرآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) دهی جزء دهستان بهنام عرب بخش ورامین شهرستان تهران . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢٩١</span> تن . آب آن از قنات . محصول آن غلات و صیفی و چغندرقند است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(183453, 'عسکران', '<span class=\"hlight\">عسکران .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) دهی از دهستان کرون . بخش نجف آباد. شهرستان اصفهان . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٣٥٧</span> تن . آب آن از قنات . محصول آن غلات، انگور، سیب زمینی، پنبه، بادام، گردو و کتیراست . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(183454, 'عسکران', '<span class=\"hlight\">عسکران .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (ع اِ) تثنیه ٔ عسکر. رجوع به عسکر شود. <BR><font color=\"Blue\">◄</font> (اِخ ) عَرَفه و مِنی ̍. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(183455, 'عسکرکش', '<span class=\"hlight\">عسکرکش .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب )لشکرکش . لشکرکشنده . سپاه کش . سائق الجیش <span class=\"hlight\">:</span> <br>نی نی به دولت تو امیر سخن منم <br>عسکرکش من این نی عسکر نکوتر است .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(183456, 'عسکرگاه', '<span class=\"hlight\">عسکرگاه .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِ مرکب ) لشکرگاه . (آنندراج ) (ناظم الاطباء). و رجوع به عسکر شود.<br></font></div>'),
(183457, 'عسکری', '<span class=\"hlight\">عسکری .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b>(اِخ ) محمدبن علی عسکری . مفتی اهالی عسکر در مصر. او فقیهی شافعی بود و کتب شافعی را از ربیعبن سلیمان و یونس بن عبدالاعلی روایت کرد. (از اللباب فی تهذیب الانساب ). و رجوع به معجم البلدان ذیل عسکر مصر شود.<br></font></div>'),
(183458, 'عسکری', '<span class=\"hlight\">عسکری .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) محمدبن عبداﷲ عسکری، مکنی به ابوبکر. از فقیهان حنفی و معتزلی بود. وی قاضی عسکر خلیفه المهدی بشمار میرفت و نسبت او به عسکر المهدی است . (از اللباب فی تهذیب الانساب ). ورجوع به معجم البلدان ذیل ماده ٔ عسکر المهدی شود.<br></font></div>'),
(183459, 'عسکری', '<span class=\"hlight\">عسکری .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) علی بن محمد عسکری . رجوع به علی عسکری شود.<br></font></div>'),
(183460, 'عسکری', '<span class=\"hlight\">عسکری .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) علی بن محمدبن علی بن موسی علیهم السلام . دهمین امام از ائمه ٔ شیعه ٔ اثناعشریه و نسبت او به عسکر سرمن رأی است . رجوع به ابوالحسن (علی النقی ...) و مآخذ ذیل شود: الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٥</span>، ابن خلکان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٢</span>، منهاج السنة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٩</span>، یعقوبی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٥</span>، نورالابصار ص <span class=\"hlight\" dir=\"rtl\">١٥٨</span>، تاریخ بغداد ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٦</span>، نزهةالجلیس ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٢</span>، اللباب فی تهذیب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span>.<br></font></div>'),
(183461, 'عسکری', '<span class=\"hlight\">عسکری .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) علی بن محمدبن جعفر حداد عسکری، مکنی به ابوالحسن . از علمای قرن چهارم هجری . رجوع به علی حداد شود.<br></font></div>'),
(183462, 'عسکری', '<span class=\"hlight\">عسکری .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) علی بن سعید عسکری، مکنی به ابوالحسن . از محدثان بود و نسبت او به عسکر سامراء میباشد. وی بسال <span class=\"hlight\" dir=\"rtl\">٢٩٨</span> هَ .ق . به اصفهان رفت، سپس عازم نیشابور گشت و به سال <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> هَ .ق . در این شهر درگذشت .از جمله کتابهای اوست : الشیوخ و المسند. (از الاعلام زرکلی از اخبار اصبهان ). و رجوع به علی عسکری شود.<br></font></div>'),
(183463, 'عسکری', '<span class=\"hlight\">عسکری .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) علی بن سعدبن عبداﷲ عسکری، مکنی به ابوالحسن . محدث و رحاله ٔ قرن سوم هجری . رجوع به علی عسکری شود.<br></font></div>'),
(183464, 'عسکری', '<span class=\"hlight\">عسکری .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) حسن بن عبداﷲبن سهل بن سعیدبن مهران عسکری، مکنی به ابوهلال . از فضلای قرن چهارم هجری . رجوع به ابوهلال عسکری و مآخذ ذیل شود: الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١١</span>، خزانةالادب بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>، معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٧</span>، دمیةالقصر، ارشاد الاریب، البعثة المصریة، معجم البلدان ذیل ماده ٔ عسکر مکرم .<br></font></div>'),
(183465, 'عسکری', '<span class=\"hlight\">عسکری .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) حسن بن عبداﷲبن سعیدبن اسماعیل بن حکیم، مکنی به ابواحمد. فقیه و ادیب بلاد خوزستان در قرن چهارم هجری بود. وی خال حسن بن عبداﷲبن سهل عسکری میباشد. و نسبت او به عسکر مکرم است . رجوع به حسن عسکری و مآخذ ذیل شود: الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٢</span>، خزانةالادب بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٩٧</span>، سیرالنبلاء، ابن خلکان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>، انباء الرواة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٠</span>، اللباب فی تهذیب الانساب، معجم البلدان ذیل ماده ٔ عسکر مکرم .<br></font></div>'),
(183466, 'عسکری', '<span class=\"hlight\">عسکری .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) حسن بن رشیق عدل عسکری، مکنی به ابومحمد. محدث و از اهالی عسکر مصر بود. از نسائی و یموت بن مزرع روایت کرد و دارقطنی از وی روایت دارد. تولد وی در چهارم صفر سال <span class=\"hlight\" dir=\"rtl\">٣٨٣</span> هَ .ق . روی داد. (از اللباب فی تهذیب الانساب ). و رجوع به معجم البلدان ذیل ماده ٔ عسکر مصر شود.<br></font></div>'),
(183467, 'عسکری', '<span class=\"hlight\">عسکری .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b>(اِخ ) دهی از دهستان تمیمی بخش کنگان شهرستان بوشهر. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن . آب آن از چاه . محصول آن غلات و خرما و تنباکو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(183468, 'عسکری', '<span class=\"hlight\">عسکری .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) دهی از دهستان رودحله ٔ بخش گناوه ٔ شهرستان بوشهر. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٣٧٠</span> تن . آب آن از رود حله . محصول آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(183469, 'عسکری', '<span class=\"hlight\">عسکری .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (ص نسبی ) منسوب به عسکر. لشکری . سپاهی . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> جنگی و بهادر. (ناظم الاطباء). و رجوع به عسکر شود. <BR><font color=\"Blue\">◄</font> منسوب به عسکر مکرم، که شهری است از کوره ٔ اهواز. (از اللباب فی تهذیب الانساب ). منسوب به عسکر که شهری است از خوزستان و اهواز، میان بصره و فارس، و گویند دهی است میان حرمین . (غیاث اللغات ) (آنندراج ). و رجوع به عسکر و عسکر مکرم شود.<br>- <span class=\"hlight\">انگور عسکری </span> ؛ نوعی انگور نازک پوست و خردهسته . قسمی انگور نهایت لطیف و پوست نازک و بی دانه . و رجوع به انگور شود.<br>- <span class=\"hlight\">شکر عسکری </span> ؛ شکر که از عسکر مکرم آرند <span class=\"hlight\">:</span> <br>به داروی علم درون علم دین <br>ز بس منفعت شکّر عسکریست .<br> <font color=\"Red\">ناصرخسرو.</font><br>چون شکر عسکری آور سخن <br>شاید اگر تو نبوی عسکری .<br> <font color=\"Red\">ناصرخسرو.</font><br>- <span class=\"hlight\">نی عسکری </span> ؛ نیشکر عسکری . نیشکر که از عسکر مکرم آرند <span class=\"hlight\">:</span> <br>طبع کافی که عسکر هنر است <br>چون نی عسکری همه شکر است .<br> <font color=\"Red\">خاقانی .</font><br>و رجوع عسکر و عسکر مکرم شود.<br><BR><font color=\"Blue\">◄</font> نوعی شراب که از شکر سازند. (غیاث اللغات ) (آنندراج ).<br></font></div>'),
(183470, 'عسکری', '<span class=\"hlight\">عسکری .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ )حسن بن علی بن محمدبن علی بن موسی الرضا علیهم السلام (امام ...)، مکنی به ابومحمد. امام یازدهم شیعه ٔ اثناعشریه . نسبت او به عسکر سرمن رأی است . رجوع به حسن عسکری و اللباب فی تهذیب الانساب و حسن بن علی ... شود.<br></font></div>'),
(183471, 'عسکریان', '<span class=\"hlight\">عسکریان .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ری یا ]</font></b> (ع ص نسبی ) تثنیه ٔ عسکری در حال رفع. رجوع به عسکری شود. <BR><font color=\"Blue\">◄</font> (اِخ ) امام علی النقی امام دهم و امام حسن عسکری امام یازدهم شیعه علیهماالسلام . (از ناظم الاطباء). رجوع به عسکری (علی ... و حسن ...) شود.<br></font></div>'),
(183472, 'عسکریه', '<span class=\"hlight\">عسکریه .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ری ی َ ]</font></b> (اِخ ) دهی از دهستان میان ولایت بخش حومه ٔ شهرستان مشهد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٤٢١</span> تن . آب آن از قنات . محصول آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183473, 'عسکریین', '<span class=\"hlight\">عسکریین .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ری ی َی ْ ]</font></b> (اِخ ) نام دیگر شهر سامره بمناسبت آنکه مرقد امام دهم و امام یازدهم شیعه علیهماالسلام است . (از ناظم الاطباء).<br></font></div>'),
(183474, 'عسکریین', '<span class=\"hlight\">عسکریین .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ری ی َی ْ ]</font></b> (اِخ ) دو عسکری، و مراد امام علی النقی امام دهم و امام حسن عسکری امام یازدهم شیعه علیهماالسلام است . رجوع به عسکری (علی ... و حسن ...) و عسکریان شود.<br></font></div>'),
(183475, 'عسی', '<span class=\"hlight\">عسی .</span> <font color=\"DarkGreen\"><b>[ ع ُ سی ی ]</font></b> (ع مص ) به غایت پیری رسیدن . (تاج المصادر بیهقی ). مسن گشتن . (از اقرب الموارد). عسو <font color=\"DarkGreen\"><b>[ ع َس ْوْ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ س ُوو ]</font></b> . عَساء. عَسْوة. رجوع به عسو شود.<br></font></div>'),
(183476, 'عسی', '<span class=\"hlight\">عسی .</span><font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ سی ی ]</font></b> (ع ص ) سزاوار: هو عسی به ؛ او سزاوار آن است . بالعسی أن یفعل کذا؛ سزاوار و شایسته است که چنین کند. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183477, 'عسی', '<span class=\"hlight\">عسی .</span> <font color=\"DarkGreen\"><b>[ ع َ سا ]</font></b> (ع فعل ) فعل مقاربه بمعنی باشد که . (منتهی الارب ). قریب است و نزدیک است که چنین شود، و بمعنی یقین و شاید هم آمده است . (غیاث اللغات ). شاید بود. (ترجمان القرآن علامه ٔ جرجانی ). شاید بود که آن مرد، و مگر. و این فعلی است از افعال ناقص، و از او چهارده وجه ماضی بیش مستعمل نیست . (دهار). فعلی است مطلق از افعال مقاربت، معنیش «باشد او». از آن انواع ماضی آید فقط. عسی زید أن یخرج و عست هند أن تخرج، زید فاعل عسی است و«أن یخرج » مفعولش بمعنی خروج . و خبرش گاهی اسم نیاید، پس عسی زید مطلقاً گفتن درست نباشد. و یا حرفی است مطلق . و نیز می آید جهت ترجی در مطلوب و اشفاق و تخویف در مکروه، که به هر دو معنی در آیه ٔ «و عسی أن تکرهوا شیئاً و هو خیر لکم و عسی أن تحبوا شیئاً وهو شر لکم » (قرآن <span class=\"hlight\" dir=\"rtl\">٢١٦/٢</span>) آمده است . و می آید جهت شک و یقین . و گاهی مشابه یکاد میباشد، پس فعلش بدون آن مستعمل گردد. (از آنندراج ). از افعال مقاربه است و معنای آن ترجی است در امر محبوب و اشفاق است در امری مکروه مانند عسی أن تکرهوا شیئاً... که هر دو معنی در این آیه جمع شده است . و اکثر پس از عسی فعل مضارع واقع شود که مقرون به أن و سین و سوف باشد، و گاه مفرد آید مانند عسی زید أن یقوم و عسی زید سیقوم و عسی زید قائماً. و گاه مجرد از سین و سوف و أن آید:عسی زید یقوم . (از فرهنگ علوم عقلی از المغنی ص <span class=\"hlight\" dir=\"rtl\">٧٨</span>). از اخوات کادَ است و آن فعلی است مطلقاً، و غیرمتصرف است . و مضارع و اسم فاعل نیز برای آن ذکر کرده اند. و آن برای ترجی است در امر دلخواه و برای اشفاق است در امر مکروه . و گاهی بجای «کان َ» آید. و هرگاه به ضمیر رفع متحرک متصل شود، کسر و فتح سین آن هر دو جایز باشد: عسیت <font color=\"DarkGreen\"><b>[ ع َ س َ ت ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ت ُ ]</font></b>، ولی فتح آن أشهر است . (از اقرب الموارد) <span class=\"hlight\">:</span> فعسی أن تکرهوا شیئاً و یجعل اﷲ فیه خیراً کثیراً (قرآن <span class=\"hlight\" dir=\"rtl\">١٩/٤</span>)؛ شاید که اکراه داشته باشید از چیزی و خداوند در آن خیر بسیاری قرار دهد. فعسی اﷲ أن یأتی بالفتح (قرآن <span class=\"hlight\" dir=\"rtl\">٥٢/٥</span>)؛ پس شاید خداوند فتح و گشایش آرد. فعسی اولئک أن یکونوا من المهتدین (قرآن <span class=\"hlight\" dir=\"rtl\">١٨/٩</span>)؛ شاید آنها از هدایت شوندگان باشند. فعسی ربی أن یؤتین خیراً من جنتک (قرآن <span class=\"hlight\" dir=\"rtl\">٤٠/١٨</span>)؛ شاید خدای من نیکوتر از بوستان تو مرا بدهد. فعسی أن یکون من المفلحین (قرآن <span class=\"hlight\" dir=\"rtl\">٦٧/٢٨</span>)؛ شاید از رستگاران بوده باشد. قال هل عسیتم ان کتب علیکم القتال ألاتقاتلوا (قرآن <span class=\"hlight\" dir=\"rtl\">٢٤٦/٢</span>)؛ گفت آیا باشید شما اگر جنگیدن بر شما نوشته شود که نجنگید. فهل عسیتم أن تولیتم أن تفسدوا فی الارض (قرآن <span class=\"hlight\" dir=\"rtl\">٢٢/٤٧</span>)، آیا باشید شما که اگر والی شوید فساد کنید در زمین .<br>وامروز و فردا میگفت و به لعل و عسی تزجیه ٔ وقت میکرد. (جهانگشای جوینی ).<br>باد طوفان بود و آن کشتی عَسی ̍<br>هست از این طوفان و این کشتی بسا.<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(183478, 'عسی', '<span class=\"hlight\">عسی .</span>  <font color=\"DarkGreen\"><b>[ ع َسا ]</font></b> (ع اِ) شاخ خرما. (منتهی الارب ). بلح، و آن را با شین معجمه نیز ضبط کرده اند. (از اقرب الموارد).<br></font></div>'),
(183479, 'عسی', '<span class=\"hlight\">عسی .</span> <font color=\"DarkGreen\"><b>[ ع َ سا <span class=\"hlight\" dir=\"rtl\">/</span> ع َ سَن ْ ]</font></b> (ع مص ) سخت کلان سال گردیدن . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> سخت شدن و ضخیم گشتن گیاه . (از اقرب الموارد).<br></font></div>'),
(183480, 'عسیب', '<span class=\"hlight\">عسیب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) کوهی است در بالای نجد. گویند هذیل را کوهی بنام کبکب و کوهی بنام خنثل و کوهی دیگر بنام عسیب بود. و در مثل گویند «لاأفعل ذلک ما أقام عسیب »، و این مثل در شعر امروءالقیس نیز آمده است . (از معجم البلدان ). نام کوهی است . (از اقرب الموارد). کوهی است به بلاد روم، و در برابر آن قبر امرؤالقیس است . و کوهی است نزدیک مدینه . (منتهی الارب ).<br></font></div>'),
(183481, 'عسیب', '<span class=\"hlight\">عسیب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) استخوان دنب و بن آن، یا روئیدن گاه موی آن . (منتهی الارب ) (از اقرب الموارد). استخوان ذَنَب . (مخزن الادویة) <span class=\"hlight\">:</span> یستحب ّ فی الفرس قصر العسیب و هو عظم الذنب و جلده، و لذلک قال بعض الاعراب «اختره طویل الذنب قصیرالذَّنَب » یعنی طویل الشعر، قصیرالعسیب . (صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢</span>). <BR><font color=\"Blue\">◄</font> پشت پای . (منتهی الارب ). ظاهر و خارج قدم . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پشت پر به درازی . (منتهی الارب ). ریش و پر از درازا. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شاخ خرما برگ دورکرده که راست و باریک باشد. (منتهی الارب ). جرید از نخل که باریک و مستقیم باشد و خوص و برگ آن جدا شده باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شاخ خرما که برگ نیاورده باشد، و آن اندکی بالاتر از کَرب است . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه خوص و برگ آن روئیده باشد، پس آن همان سَعَف است .  <BR><font color=\"Blue\">◄</font> کفتگی در کوه . (منتهی الارب ). شق و شکاف در کوه . (از اقرب الموارد). ج، عُسبان (منتهی الارب ) (اقرب الموارد)، عسب <font color=\"DarkGreen\"><b>[ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ س ُ ]</font></b> . (اقرب الموارد).<br></font></div>'),
(183482, 'عسیبة', '<span class=\"hlight\">عسیبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِ) استخوان دنب و بن آن . (منتهی الارب ). استخوان دم و ذَنَب . (از اقرب الموارد). عصعص . عسیب . و رجوع به عسیب (ع اِ) شود. <BR><font color=\"Blue\">◄</font> یکی عسیب . (منتهی الارب ). رجوع به عسیب (ع اِ) شود.<br></font></div>'),
(183483, 'عسیر', '<span class=\"hlight\">عسیر.</span>  <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) چاهی است در مدینه ازآن ِ ابوامیه ٔ مخزومی، و پیامبر (ص ) آن را الیسیرة نامیده است . (از معجم البلدان ).<br></font></div>'),
(183484, 'عسیر', '<span class=\"hlight\">عسیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) دشوار. (منتهی الارب ) (غیاث اللغات ) (دهار). صعب . (اقرب الموارد).دشخوار. سخت . عَسِر. مشکل . مقابل یسیر <span class=\"hlight\">:</span> <br>وَرْمان همی بباید او را شناختن <br>بی چون و بی چگونه طریقیست بس عسیر.<br> <font color=\"Red\">ناصرخسرو.</font><br>- <span class=\"hlight\">حاجة عسیر</span> ؛ نیاز دشوار. (منتهی الارب ). حاجت متعسر و سخت . (از اقرب الموارد).<br>- <span class=\"hlight\">عسیرالعلاج </span> ؛ بیماری که چاره ٔ آن دشوارباشد: مرض عسیرالعلاج . (ناظم الاطباء).<br>- <span class=\"hlight\">عسیرالمرور</span> ؛ راهی که عبورومرور از آن با زحمت و عسرت بود: راه عسیرالمرور. (ناظم الاطباء).<br>- <span class=\"hlight\">عسیرالمضغ</span> ؛ آنچه جویدن آن سخت باشد. دشوارمضغ. دشوارخای .<br>- <span class=\"hlight\">یوم عسیر</span> ؛ روز دشوار و سخت، یا روز بد. (منتهی الارب ). روز دشوار. (دهار).روز شدید یا شوم . (از اقرب الموارد) <span class=\"hlight\">:</span> فذلک یومئذ یوم عسیر (قرآن <span class=\"hlight\" dir=\"rtl\">٩/٧٤</span>)؛ و آن روز روزی است دشوار. و کان یوماً علی الکافرین عسیراً (قرآن <span class=\"hlight\" dir=\"rtl\">٢٦/٢٥</span>)؛و بوده است روزی بر کافران دشوار.<br>چنان ماند قاضی به جورش اسیر<br>که گفت ان هذا لیوم عسیر.<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> ناقة عسیر؛ شتر که در اول ریاضت سوار شده باشند او را. (منتهی الارب ) (از اقرب الموارد). شتر نارام کرده . (دهار). <BR><font color=\"Blue\">◄</font> شتر ماده که بسال نخست بار نگیرد. (منتهی الارب ). ماده شتر که سال نخستش فرارسیده باشد و حامل نگردد.(از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتر ماده ٔ دم برداشته ٔ دونده . (ناظم الاطباء). ناقه ای که در هنگام دویدن دم خود را بلند کرده باشد. (از اقرب الموارد).<br></font></div>'),
(183485, 'عسیس', '<span class=\"hlight\">عسیس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) ج ِ عاس ّ. (منتهی الارب ) (اقرب الموارد). رجوع به عاس ّ شود.<br></font></div>'),
(183486, 'عسیف', '<span class=\"hlight\">عسیف .</span> <font color=\"DarkGreen\"><b>[ع ِس ْ سی ]</font></b> (ع ص ) آنکه راهها را بدون دلیل و راهنما و بدون هدف و رهنمایی بپیماید. (از اقرب الموارد).<br></font></div>'),
(183487, 'عسیف', '<span class=\"hlight\">عسیف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) مزدور و بنده ٔ مستعان به . (منتهی الارب ). اجیر، و گویند مملوک و برده ٔ حقیرداشته شده . (از اقرب الموارد).  <BR><font color=\"Blue\">◄</font> پیر فانی . ج، عُسفاء. (منتهی الارب ). جمع آن عسفاء است بر قیاس، و عِسَفة است برخلاف قیاس . (از اقرب الموارد).<br></font></div>'),
(183488, 'عسیل', '<span class=\"hlight\">عسیل .</span> <font color=\"DarkGreen\"><b>[ ع ُ س َ ]</font></b> (اِخ ) ابن عقبةبن صمعةبن عاصم بن مالک بن قیس بن مالک سامی . از اجداد جاهلی است و بطنی از سامةبن لؤی را بنام عسیلی تشکیل می دهد. (از اللباب فی تهذیب الانساب ). و رجوع به عسیلی شود.<br></font></div>'),
(183489, 'عسیل', '<span class=\"hlight\">عسیل .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (ع ص، اِ) مرد سخت زننده ٔ سبک دست . (منتهی الارب ). عَسِل . و رجوع به عَسِل شود. <BR><font color=\"Blue\">◄</font> جاروب عطار. (منتهی الارب ). جاروب عطار که آنچه با صلایه مشک سایند بدان واهم آورند. (السامی فی الاسامی ). مکنسه ٔ عطار که عطر را بدان جمع آورند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پر که از آن غالیه بردارند. (منتهی الارب ).ریش و پری که بوسیله ٔ آن غالیه را برکنند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نره ٔ پیل . (منتهی الارب ). قضیب فیل . (مخزن الادویة). <BR><font color=\"Blue\">◄</font> نره ٔ شتر. (منتهی الارب ). ج، عُسُل . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(183490, 'عسیلة', '<span class=\"hlight\">عسیلة.</span> <font color=\"DarkGreen\"><b>[ ع ُ س َ ل َ ]</font></b> (ع اِ مصغر) تصغیر عَسَل . (دهار). رجوع به عسل شود. <BR><font color=\"Blue\">◄</font> کنایه است لذت جماع را. (از دهار). نطفه وآب مرد، یا حلاوتی است در جماع که به لذت انگبین تشبیه دهند، و در تصغیر با تاء آمده است، چون کلمه ٔ «عسل » غالباً بصورت مؤنث بکار رود. (از منتهی الارب ).<br></font></div>'),
(183491, 'عسیلة', '<span class=\"hlight\">عسیلة.</span> <font color=\"DarkGreen\"><b>[ ع ُ س َ ل َ ]</font></b> (اِخ ) آبی است در کوه قَنان در شرق سمیراء، و نام آن در شعر قحیف بن حمیر عقیلی آمده است . (از معجم البلدان ). آبی است شرقی ِ سمیراء. (منتهی الارب ). نام موضعی است به نجد به یک روز راه از وادی العروس . (از ابن جبیر) <span class=\"hlight\">:</span> <br>زآب شور نقره و ریگ عسیله زاعتقاد<br>سالکان از نقره کان و از عسل شان دیده اند.<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(183492, 'عسیلی', '<span class=\"hlight\">عسیلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ س َ ]</font></b> (ص نسبی ) منسوب به عسیل، که بطنی است از سامةبن لؤی، و او عسیل بن عقبة است . (از اللباب فی تهذیب الانساب ). و رجوع به عُسَیل شود.<br></font></div>'),
(183493, 'عسیلی', '<span class=\"hlight\">عسیلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ س َ ]</font></b> (اِخ ) علی بن محمد عسیلی، ملقب به نورالدین . ادیب و فقیه قرن دهم هجری . رجوع به علی عسیلی شود.<br></font></div>'),
(183494, 'عسیلی', '<span class=\"hlight\">عسیلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ س َ ]</font></b> (اِخ ) محمدبن موسی بن علاءالدین عسیلی . از فاضلان قدس بود و به سال <span class=\"hlight\" dir=\"rtl\">١٠٣١</span> هَ .ق . درگذشت . او راست : الخصائص النبویة که نظم است و شرح آن را نیز نوشته است . و القطر که منظومه ای است در نحو. (از الاعلام زرکلی از خلاصةالاثر).<br></font></div>'),
(183495, 'عش', '<span class=\"hlight\">عش .</span> <font color=\"DarkGreen\"><b>[ ع ُش ش ]</font></b> (اِخ ) (ذوالَ ...) از وادیهای عقیق، از نواحی مدینه است، و گویند آن در راه بین صنعاء و مکه است در نجد، در پایین راه تهامه، و آن منزلی است بین مکانی که مشهور به قبورالشهداء است و بین کُتنة. و نیز گفته اند عُشّان از منازل خولان است . (از معجم البلدان ).<br></font></div>'),
(183496, 'عش', '<span class=\"hlight\">عش .</span> <font color=\"DarkGreen\"><b>[ ع ُش ش ]</font></b> (اِخ ) ابن لبیدبن عداء. شاعری است . (منتهی الارب ). ابن لبیدبن عدبن امیةبن عبداﷲبن رزاخ بن ربیعةبن حرام بن ضنةبن سعدبن هذیم بن أسلم بن الحاف بن قضاعة. جدّی است جاهلی، و حریث و عاطف دو فرزند سلیم بن عش ازنسل او بشمار آیند. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(183497, 'عش', '<span class=\"hlight\">عش .</span> <font color=\"DarkGreen\"><b>[ع َش ش ]</font></b> (ع ص ) اندک، و بخشش اندک . (از منتهی الارب ). عطاء قلیل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گشن که به خواهش ناقه بر وی جهد و ستم نکند. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) آشیانه ٔ مرغ . (از منتهی الارب ) (از اقرب الموارد). عُش ّ. رجوع به عُش ّ شود. <BR><font color=\"Blue\">◄</font> جد و جهد و کوشش، گویند: جاء به من عشه و بشه ؛ یعنی آن را به تمام کوشش آورد. (از منتهی الارب )(از اقرب الموارد). عَس ّ. رجوع به عَس ّ و حَس ّ شود. <BR><font color=\"Blue\">◄</font> (ص ) مرد کم گوشت درازقامت، یا باریک استخوان دست و پا. (منتهی الارب ): رجل عش ؛ مرد طویل کم گوشت، و یا آنکه استخوانهای دست و پایش دقیق و باریک باشد. و تأنیث آن عَشّة باشد. (از اقرب الموارد).<br></font></div>'),
(183498, 'عش', '<span class=\"hlight\">عش .</span> <font color=\"DarkGreen\"><b>[ ع َش ش ]</font></b> (ع مص ) کم شاخ و باریک تنه گردیدن درخت . (از منتهی الارب ): عشت النخلة؛ شاخه های آن نخل کم شد و انتهای آن باریک گشت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> جستن . (منتهی الارب ). طلب کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گرد کردن . (منتهی الارب ). جمع کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ورزیدن . (منتهی الارب ). کسب کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زدن . (منتهی الارب ). ضرب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درپی نهادن پیراهن را. (منتهی الارب ): عش القمیص ؛ پیراهن را وصله کرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کم کردن دهش را. (از منتهی الارب ): عش المعروف ؛ نیکی و بخشش خود را کم کرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> لازم گرفتن پرنده آشیانه را. (از منتهی الارب ): عش الطائر؛ آن پرنده ملازم آشیانه ٔ خود شد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> به منزل دیگر فرودآمدن تا جای بر ایشان تنگ گردد و از آنجا کوچ نمایند. (از منتهی الارب ): عش فلان القوم ؛ او در منزلی فرودآمد که پیش از وی قوم در آنجا منزل کرده بودند و آن منزل آنها را ناراحت کرده بود لذا از آنجا کوچ کرده اند. (از ناظم الاطباء) (از اقرب الموارد).<br></font></div>'),
(183499, 'عش', '<span class=\"hlight\">عش .</span><font color=\"DarkGreen\"><b>[ ع ُش ش ]</font></b> (ع اِ) آشیانه ٔ مرغ از هیمه و حطب که بر شاخ درخت باشد، و اگر در دیوار یا عمارت و یا در کوه باشد آن را وکر و وَکن گویند، و اگر آشیانه ٔ او در زمین باشد اُدحی ّ و اُفحوص نامیده میشود. ج، عِشَشة، عِشاش، أعشاش . (از منتهی الارب ) (از اقرب الموارد). خانه ٔ مرغ بر درخت که آنجا خایه نهد. (دهار). آشیانه ٔ مرغ بر درخت و در پوشش . (زمخشری ). آشیانه ٔ مرغ . (غیاث اللغات ). لانه ٔ مرغان بر درخت که از خرده ٔ چوب و جز آن کنند. (یادداشت مرحوم دهخدا). عش الطائر؛ خانه ٔطیور است که به فارسی آشیان پرنده گویند. (مخزن الادویة). فِراش . لانه . آشیان . آشیانه . عَش ّ <span class=\"hlight\">:</span> <br>مرغ جذبه ناگهان پرّد ز عش <br>چون بدیدی صبح، شمعآنگه بکش .<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">امثال </span> :<br><span class=\"hlight\">لیس بعشک فادرجی </span> ؛ یعنی نیست تو را حقی در آن، پس بگذر از آن . (منتهی الارب ) (از اقرب الموارد). و آن مثلی است در مورد کسی که آنچه راشایسته ٔ او نیست بگیرد، و یا در مورد کسی گویند که خود را بالاتر از منزلت خویش بنماید، و یا کسی که بر آنچه ازآن ِ او نیست روی آورد. و آن را به کسی که بیجا و در غیر وقت خود، مطمئن باشد گویند تا وی را بر کوشش و جنبش وادار نمایند. (از اقرب الموارد).<br></font></div>'),
(183500, 'عش', '<span class=\"hlight\">عش .</span> <font color=\"DarkGreen\"><b>[ ع َ شِن ْ ]</font></b> (ع ص ) عشی . شبکور، و آنکه شب و روز سوءالبصر باشد اورا، یا نابینا. (منتهی الارب ). و رجوع به عشی شود.<br></font></div>'),
(183501, 'عشا', '<span class=\"hlight\">عشا.</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (ع مص ) شبکور گردیدن و ضعیف شدن بینائی . (از ناظم الاطباء). ضعیف شدن بینائی در شب و روز، و گویند نابینا شدن، و گویند بینا بودن در روز و نابینا شدن در شب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> در شبانگاه چریدن شتر. (از ناظم الاطباء). شام خوردن شتران، و دراین صورت آنان را عاشیة گویند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خوردن شام را: عشی العشاء؛ شام را خورد، و چنین شخصی را عشیان نامند. (از اقرب الموارد).<br></font></div>'),
(183502, 'عشا', '<span class=\"hlight\">عشا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) شب کوری، و یا عام است . (منتهی الارب ). شب کوری . (غیاث اللغات ). سوء بصر در شب و در روز، و گویند دیدن در روز و ندیدن در شب، و یا کوری و نابینایی . (از اقرب الموارد). از عیوب اسب است در آفرینش، و آن این است که در شب نبیند و در واقع بصورت نیم اسب درآید زیرا جز در روز نمیتوان از آن استفاده ای کرد. (ازصبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤</span>). عَشاوة. و رجوع به عشاوة شود.<br></font></div>'),
(183503, 'عشا', '<span class=\"hlight\">عشا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (از ع، اِ) عَشاء. طعامی که بشب خورند. (غیاث اللغات ). غذای شب <span class=\"hlight\">:</span> یکی تحریمه ٔ عِشا بسته و دیگری منتظر عَشا نشسته . (گلستان سعدی ). رجوع به عَشاء شود.<br></font></div>'),
(183504, 'عشا', '<span class=\"hlight\">عشا.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (از ع، اِ) عِشاء. شبانگاه . (زمخشری ). تاریکی شب که وقت نماز شب است . (غیاث اللغات ) <span class=\"hlight\">:</span> یکی تحریمه ٔ عِشا بسته و دیگری منتظر عَشا نشسته . (گلستان سعدی ). رجوع به عِشاء شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(183505, 'عشاب', '<span class=\"hlight\">عشاب .</span> <font color=\"DarkGreen\"><b>[ ع َش ْ شا ]</font></b> (اِخ ) احمدبن محمدبن ابراهیم مرادی قرطبی، مکنی به ابوالعباس و مشهور به عشاب . مقری ٔ و از اهالی قرطبه بود و به سال <span class=\"hlight\" dir=\"rtl\">٦٤٩</span> هَ .ق . متولد شد. صاحب تونس او را به وزارت گماشت . سپس به اسکندریه رفت و در آنجا بسال <span class=\"hlight\" dir=\"rtl\">٧٣٦</span> هَ .ق . درگذشت . او را کتابی است در تفسیر و کتابی در معانی و بیان . (از الاعلام زرکلی از غایة النهایة و الدرر الکامنة و شذرات الذهب ).<br></font></div>'),
(183506, 'عشاب', '<span class=\"hlight\">عشاب .</span> <font color=\"DarkGreen\"><b>[ ع َش ْ شا ]</font></b> (ع ص ) گیاه شناس . نباتی . حشائشی . حشاش . شجار. (یادداشت مرحوم دهخدا).<br></font></div>'),
(183507, 'عشابة', '<span class=\"hlight\">عشابة.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِمص ) گیاهناکی . (منتهی الارب ). فراوانی عشب و گیاه . (از اقرب الموارد).<br></font></div>'),
(183508, 'عشابة', '<span class=\"hlight\">عشابة.</span><font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع مص ) گیاه تر برآوردن . (از ناظم الاطباء): عشبت الارض ؛ عشب زمین رویید. (از اقرب الموارد).<br></font></div>'),
(183509, 'عشار', '<span class=\"hlight\">عشار.</span> <font color=\"DarkGreen\"><b>[ ع َش ْ شا ]</font></b> (ع ص ) ده یک گیرنده . (منتهی الارب ). عُشرگیرنده و جمعکننده ٔ آن . ج، عشارون . (از اقرب الموارد). ده یک ستان .راهبان . (ملخص اللغات حسن خطیب ). باژبان . مکاس . (زمخشری ). باژران . (دهار). راه دار. باجگیر. ده یک گیر. خراج ستان . باژستان . محصل مالیات . عامل زکات . گمرکچی .<br></font></div>'),
(183510, 'عشار', '<span class=\"hlight\">عشار.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص، اِ) ج ِعُشَراء. (منتهی الارب ) (اقرب الموارد) (دهار). رجوع به عشراء شود: و اذا العشار عطّلت (قرآن <span class=\"hlight\" dir=\"rtl\">٤/٨١</span>)؛ و هرگاه شتران باردار، بار نهند. <BR><font color=\"Blue\">◄</font> شترمادگان که بعضی بچه آورده باشد و بعضی منتظر آن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِخ ) موضعی است . (منتهی الارب ).<br></font></div>'),
(183511, 'عشار', '<span class=\"hlight\">عشار.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِ) از درختان کائوچوکی ایران است که بنام اِستَبْرَق مشهور است . رجوع به استبرق شود.<br></font></div>'),
(183512, 'عشار', '<span class=\"hlight\">عشار.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، ق ) دهگان، و آن معدول است از عشرة: جاؤوا عشارعشار؛ دهگان دهگان . (منتهی الارب ). دهگان دهگان . (دهار). معدول است از عشرةعشرة، بصورت نکره، و آن غیرمنصرف است بجهت وصف و عدل . گویند: جاء القوم عشار؛ یعنی آن گروه ده ده آمدند. (از اقرب الموارد).<br></font></div>'),
(183513, 'عشارب', '<span class=\"hlight\">عشارب .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ). اسد. <BR><font color=\"Blue\">◄</font> (ص ) رجل عشارب ؛ مردی باجرأت و دلیر و اقدام کننده . (از اقرب الموارد).<br></font></div>'),
(183514, 'عشارق', '<span class=\"hlight\">عشارق .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (اِخ ) از اعلام است . (از منتهی الارب ).<br></font></div>'),
(183515, 'عشارم', '<span class=\"hlight\">عشارم .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ). اسد. (اقرب الموارد). عشارب . عشرم . و رجوع به عشارب و عشرم شود. <BR><font color=\"Blue\">◄</font> (اِخ ) از اعلام است . (از منتهی الارب ).<br></font></div>'),
(183516, 'عشاره', '<span class=\"hlight\">عشاره .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) نام زمینی است از دهستان میان آب بخش مرکزی شهرستان اهواز. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٨٠٠</span> تن . آب آن از رودخانه ٔ شاهور. محصول آن غلات است . ساکنان این آبادی در دو محل بنام کعب فرج اﷲ و کعب کرم اﷲ ساکنند و چادرنشین میباشند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(183517, 'عشاری', '<span class=\"hlight\">عشاری .</span> <font color=\"DarkGreen\"><b>[ ع َری ی ]</font></b> (ع اِ) ج ِ عَشراویّة. رجوع به عشراویة شود.<br></font></div>'),
(183518, 'عشاری', '<span class=\"hlight\">عشاری .</span> <font color=\"DarkGreen\"><b>[ ع ُ ری ی ]</font></b> (ع ص ) هر چیز که درازای آن ده ذراع باشد. (ناظم الاطباء): ثوب عشاری ؛ پارچه ٔ ده دستی . (منتهی الارب ). پیراهنی که طول آن ده ذراع باشد. غلام عشاری ؛ پسر ده ساله، و در تأنیث عشاریة شود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نام صنعت شعری . (غیاث اللغات ) (آنندراج ).<br></font></div>'),
(183519, 'عشاری', '<span class=\"hlight\">عشاری .</span> <font color=\"DarkGreen\"><b>[ ع ُ ری ی ]</font></b> (اِخ ) نام او حسین بن علی بن حسن بن محمد عشاری است . وی فقیه و اصولی و از اهالی بغداد بود. بسال <span class=\"hlight\" dir=\"rtl\">١١٥٠</span> هَ .ق . متولد شد و در فقه شافعی تسلط بسیار یافت بطوری که او را شافعی صغیر لقب دادند. بسال <span class=\"hlight\" dir=\"rtl\">١١٩٤</span> هَ .ق . برای تدریس از بغداد به بصره رفت و به سال <span class=\"hlight\" dir=\"rtl\">١١٩٥</span> هَ .ق . در آنجا درگذشت . او راست : دیوان شعر، حاشیه به شرح حضرمیه ٔ ابن حجر، تعلیقات بر جمع الجوامع محلی . او را خطی خوش بود و کتابهای بسیاری استنساخ کرده است . نسبت وی به عُشارة شهری از خابور است . (از الاعلام زرکلی از المسک الاذفر).<br></font></div>'),
(183520, 'عشاری', '<span class=\"hlight\">عشاری .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ص نسبی ) منسوب به ابوطالب محمدبن علی بن فتح بن محمدبن علی حربی، مشهور به ابن العشاری بغدادی، و آن لقب جد او بود. وی به سال <span class=\"hlight\" dir=\"rtl\">٣٦٦</span> هَ .ق . متولد شد و در سال <span class=\"hlight\" dir=\"rtl\">٤٥١</span> درگذشت . (از اللباب فی تهذیب الانساب ). و رجوع به الانساب سمعانی شود.<br></font></div>'),
(183521, 'عشاریات', '<span class=\"hlight\">عشاریات .</span><font color=\"DarkGreen\"><b>[ ]</font></b> (ع اِ) نوع کشتی بود که در رود نیل حرکت میکرد. (از تاریخ التمدن الاسلامی جرجی زیدان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٦١</span>).<br></font></div>'),
(183522, 'عشاریات', '<span class=\"hlight\">عشاریات .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ ]</font></b> (ع ص، ق ) ذهبوا عشاریات ؛ یعنی رفتند پریشان و متفرق . (منتهی الارب ). به معنی عساریات است بسین مهمل . (از اقرب الموارد). رجوع به عساریات شود.<br></font></div>'),
(183523, 'عشاریة', '<span class=\"hlight\">عشاریة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ری ی َ ]</font></b> (ع ص ) تأنیث عشاری . (از اقرب الموارد). رجوع به عشاری شود.<br></font></div>'),
(183524, 'عشازن', '<span class=\"hlight\">عشازن .</span> <font color=\"DarkGreen\"><b>[ ع َ زِ ]</font></b> (ع اِ) ج ِ عَشَوزن .(منتهی الارب ) (اقرب الموارد). رجوع به عشوزن شود.<br></font></div>'),
(183525, 'عشاش', '<span class=\"hlight\">عشاش .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ عُش ّ. (منتهی الارب ) (دهار) (اقرب الموارد). رجوع به عش شود.<br></font></div>'),
(183526, 'عشاق', '<span class=\"hlight\">عشاق .</span> <font color=\"DarkGreen\"><b>[ ع ُش ْ شا ]</font></b> (ع ص، اِ) ج ِ عاشِق . (تاج العروس ) (آنندراج ). مردمان عاشق و عاشقها. (ناظم الاطباء). شیفتگان، و دوستداران معشوق . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>بتان راپیش بنشاندی بهم با عاشقان یک جا<br>بلای زلف معشوقان جدا کردی ز عشاقش .<br> <font color=\"Red\">منوچهری .</font><br>گهی ز چشم زند تیر بر دل عشاق <br>گهی ز دست زند تیغ بر سر اعدا.<br> <font color=\"Red\">معزی .</font><br>یعنی از روی دلبران خط سبز دل عشاق بیشتر جوید. (گلستان سعدی ).<br>کمان ابروی ترکان به تیر غمزه ٔ جادو<br>گشاده بر دل عشاق مستمند کمین را.<br> <font color=\"Red\">سعدی .</font><br>عشاق به درگهت اسیرند بیا.<br> <font color=\"Red\">سعدی .</font><br>شهر خالی است ز عشاق مگر کز طرفی <br>دستی از غیب برون آید و کاری بکند.<br> <font color=\"Red\">حافظ.</font><br>راه دل عشاق زد آن چشم خماری <br>پیداست ازین شیوه که مستست شرابت .<br> <font color=\"Red\">حافظ.</font><br>چو دام طره افشاند ز گرد خاطر عشاق <br>به غماز صبا گویدکه راز ما نهان دارد.<br> <font color=\"Red\">حافظ.</font><br>هُیّام ؛ عشاق . (منتهی الارب ).<br>- <span class=\"hlight\">عشاق سگ جان </span> ؛ طالبان دنیا و مردم حریص . (ناظم الاطباء).<br> <BR><font color=\"Blue\">◄</font> (اصطلاح موسیقی ) نام مقامی است از دوازده مقام موسیقی که آن را دو گهری روز باقی مانده می سرایند. (غیاث اللغات ) (آنندراج ). آوازی است ایرانی، و آن در آوازهای متعدد نواخته میشود. در پایان راست پنجگاه، عشاق رامی نوازند و راست پنجگاه توسط آن تبدیل به «نوا» میشود. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">پرده ٔ عشاق </span> ؛ پرده ای از دوازده پرده ٔ موسیقی . رجوع به عشاق شود <span class=\"hlight\">:</span> <br>بونصر تو در پرده ٔ عشاق رهی زن <br>بوعمرو تو اندر صفت گل غزلی گوی .<br> <font color=\"Red\">فرخی .</font><br>بر سرِ سروزند پرده ٔ عشاق، تذرو<br>ورشان نای زند، بر سر هر مغروسی .<br> <font color=\"Red\">منوچهری .</font><br>نوا را پرده ٔ عشاق آراست <br>درافکند این غزل را در ره راست .<br> <font color=\"Red\">نظامی .</font><br>ور پرده ٔ عشاق و صفاهان و حجاز است <br>از حنجره ٔ مطرب مکروه نزیبد.<br> <font color=\"Red\">سعدی .</font><br>سعدی از پرده ٔ عشاق چه خوش مینالید<br>ترک من پرده برانداز که هندوی توام .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(183527, 'عشاق', '<span class=\"hlight\">عشاق .</span> <font color=\"DarkGreen\"><b>[ ع ُش ْ شا ]</font></b> (اِخ ) (جزیرةالَ ...) شهر سینوپ که در آسیای صغیر در کنار دریای سیاه واقع شده و دارای پنجهزار تن جمعیت است . (ناظم الاطباء).<br></font></div>'),
(183528, 'عشاق', '<span class=\"hlight\">عشاق .</span><font color=\"DarkGreen\"><b>[ ع ُش ْ شا ]</font></b> (اِخ ) دهی از دهستان ترک شهرستان ملایر.سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٢٧٧</span> تن . آب آن از چشمه . محصول آن غلات و انگور و صیفی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(183529, 'عشان', '<span class=\"hlight\">عشان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) آنچه افتاده باشد از خرما بی قیمت و رایگان . (منتهی الارب ). افتاده های خرما، و آن خرماهایی است که پس از درویدن، از شاخه های ضخیم آن چیده میشود.(از اقرب الموارد). عُشانة. و رجوع به عشانة شود.<br></font></div>'),
(183530, 'عشانة', '<span class=\"hlight\">عشانة.</span><font color=\"DarkGreen\"><b>[ ع ُ ن َ ]</font></b> (ع اِ) آنچه افتاده باشد از خرما بی قیمت و رایگان . (منتهی الارب ). افتاده های خرما، و آن خرمایی است که پس از درویدن، از شاخه های ضخیم آن چیده می شود. (از اقرب الموارد). عُشان . و رجوع به عشان شود. <BR><font color=\"Blue\">◄</font> تنه ٔ درخت . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اصل و ریشه ٔ شاخه ٔ درخت خرما. (از اقرب الموارد).<br></font></div>'),
(183531, 'عشانط', '<span class=\"hlight\">عشانط.</span> <font color=\"DarkGreen\"><b>[ ع َ ن ِ ]</font></b> (ع ص، اِ) ج ِ عَشنَّط. (منتهی الارب ) (اقرب الموارد). رجوع به عشنط شود.<br></font></div>'),
(183532, 'عشانق', '<span class=\"hlight\">عشانق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ن ِ ]</font></b> (ع ص ) درازبالای کم گوشت . (از منتهی الارب ). شخص طویل که ضخیم و سنگین نباشد. و تأنیث آن عشانقة است . (از اقرب الموارد). ج، عَشانقة. (از اقرب الموارد). عَشنَّق . و رجوع به عشنق شود.<br></font></div>'),
(183533, 'عشاوت', '<span class=\"hlight\">عشاوت .</span> <font color=\"DarkGreen\"><b>[ ع َ وَ ]</font></b> (ع اِمص ) شبکوری و ضعف بینائی . عشاوة. رجوع به عشاوة شود.<br></font></div>'),
(183534, 'عشاوز', '<span class=\"hlight\">عشاوز.</span> <font color=\"DarkGreen\"><b>[ ع َ وِ ]</font></b> (ع ص، اِ) ج ِ عَشَوزن .(منتهی الارب ) (اقرب الموارد). رجوع به عشوزن شود.<br></font></div>'),
(183535, 'عشایا', '<span class=\"hlight\">عشایا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عَشیة. (اقرب الموارد) (دهار). رجوع به عشیة شود. <BR><font color=\"Blue\">◄</font> ج ِ عَشی ّ. (منتهی الارب ). رجوع به عشی شود.<br></font></div>'),
(183536, 'عشب', '<span class=\"hlight\">عشب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) گیاه تر. (منتهی الارب ) (دهار) (مخزن الادویة) (غیاث اللغات ). گیاه تر در آغاز بهار. واحد آن عُشبة است . ج، أعشاب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> یونجه ٔ وحشی . (فرهنگ فارسی معین ). رجوع به یونجه شود.<br></font></div>'),
(183537, 'عشب', '<span class=\"hlight\">عشب .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (ع مص ) خشک گردیدن . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> روییدن گیاه در مکانی . (از اقرب الموارد).<br></font></div>'),
(183538, 'عشب', '<span class=\"hlight\">عشب .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (ع ص ) عیال عشب ؛ عیال بزرگ که صغیر نباشد. (منتهی الارب ). عیال که در بین آنها صغیر نباشد. (از اقرب الموارد).<br></font></div>'),
(183539, 'عشب', '<span class=\"hlight\">عشب .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ِ ]</font></b> (ع ص ) بسیارگیاه . (ناظم الاطباء). گیاه دار. و در تأنیث عَشِبة گویند. (از اقرب الموارد).<br></font></div>'),
(183540, 'عشبة', '<span class=\"hlight\">عشبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع اِ) واحد عُشب . (از اقرب الموارد). یک گیاه تر.(ناظم الاطباء). رجوع به عُشب شود. <BR><font color=\"Blue\">◄</font> عشبه ٔ مغربیه  است که ظیان نامند. (فهرست مخزن الادویة). مخفف عشبةالنار لغت اندلسی است، و آن یاسمین بری است، و مغربی او قوی تر و یا سیمین بری سایر ولایات ضعیف الاثرند. و جهت مفاصل مزمن و صاحبان مزاج بسیار سرد، قوی تر از چوب چینی است . (از تحفه ٔ حکیم مؤمن ). گیاهی است که پیش از این با چینی میخوردند، معالجه ٔ بعضی امراض را. (یادداشت مرحوم دهخدا). نوعی «اَزْمَلَک » است که دارای ساقه ٔ زیرزمینی ضخیم و گره دار است . و میوه اش به بزرگی یک گیلاس میرسد و قرمزرنگ است و یک تا سه دانه دارد. ریشه اش درطب عوام بعنوان معرق و مدر و تصفیه کننده ٔ خون مصرف میشود، بعلاوه در رفع بیماریهای جلدی از قبیل سودا و تفلس پوست بدن مورد مصرف دارد. عشبه ٔ طبی . عشبه ٔ مغربیه . صبرینه . صبرینه ٔ طبی . (از فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عشبةالساع </span> ؛ کراث است . (تحفه ٔ حکیم مؤمن ) (فهرست مخزن الادویة). رجوع به کراث شود.<br>- <span class=\"hlight\">عشبةالنار</span> ؛ ظیان است . (فهرست مخزن الادویة). رجوع به ظیان و عشبة شود.<br>- <span class=\"hlight\">عشبه ٔ بیابان </span> ؛ عشبه ٔ بری . رجوع به عشبه ٔ بری شود.<br>- <span class=\"hlight\">عشبه ٔ خاردار</span> ؛ اَزْمَلَک که نوعی گیاه است . (از فرهنگ فارسی معین ). رجوع به ازملک شود.<br>- <span class=\"hlight\">عشبه ٔ طبی </span> ؛ عشبه که نوعی گیاه است . (از فرهنگ فارسی معین ). رجوع به عشبة شود.<br>- <span class=\"hlight\">عشبه ٔ مغربیه </span> ؛ عشبه که نوعی گیاه است . (از فرهنگ فارسی معین ). رجوع به عشبة شود.<br></font></div>'),
(183541, 'عشبة', '<span class=\"hlight\">عشبة.</span><font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (اِخ ) نام موضعی است . (از منتهی الارب ).<br></font></div>'),
(183542, 'عشبة', '<span class=\"hlight\">عشبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ب َ ]</font></b> (ع ص ) شتر ماده ٔ کلان سال . (منتهی الارب ). ناب . شتر بزرگ سال . (از اقرب الموارد).عَشَمة. و رجوع به عشمة شود. <BR><font color=\"Blue\">◄</font> مرد کوتاه بالا. (منتهی الارب ). رجل قصیر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زن پست قامت زشت روی . (منتهی الارب ). زن کوتاه و قصیر با زشتی روی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیر پشت دوتا از پیری، و مرد پیر فانی، و گنده پیر. (منتهی الارب ). پیرمرد و پیرزن فانی که از بزرگسالی خمیده پشت باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بز پیر و مسن . (از اقرب الموارد) (از منتهی الارب ).<br></font></div>'),
(183543, 'عشبة', '<span class=\"hlight\">عشبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ش ِ ب َ]</font></b> (ع ص ) مؤنث عَشِب . (از اقرب الموارد): أرض عشبة؛ زمین بسیارگیاه . (منتهی الارب ). رجوع به عشب شود.<br></font></div>'),
(183544, 'عشتاروت', '<span class=\"hlight\">عشتاروت .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) عشتروت . رجوع به عشتروت شود.<br></font></div>'),
(183545, 'عشتاروت قرنایم', '<span class=\"hlight\">عشتاروت قرنایم .</span><font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) (یعنی عشتاروت صاحب دو شاخ ) یکی ازشهرهای رفائیان است در باشان، و بعضی را گمان چنان است که قصد از دو بت میباشد یا قناتها، لکن قول صحیح آن است که تل عشرة میباشد. (از قاموس کتاب مقدس ).<br></font></div>'),
(183546, 'عشتان', '<span class=\"hlight\">عشتان .</span> <font color=\"DarkGreen\"><b>[ ع َش ْ ش َ ]</font></b> (اِخ ) شهری است در یمن از سرزمین صعدة، که ابراهیم بن محمدبن حَدوبة صنعانی از آنجا بوده است . (از معجم البلدان ).<br></font></div>'),
(183547, 'عشترا', '<span class=\"hlight\">عشترا.</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (اِخ ) جایگاهی است در حوران، از اعمال دمشق . (از معجم البلدان ).<br></font></div>'),
(183548, 'عشتروت', '<span class=\"hlight\">عشتروت .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (اِخ ) عشتاروت . خدای صیدونیان، که بت آن بصورت مخصوصی بود و عبادت این بت در سوریه و فنیقیه معمول بوده است . سلیمان عبادت وی را در بنی اسرائیل نیز شیوع داد که یونانیان و رومانیان آن را استرتی نامند و یوشیا این عبادت را که فی الحقیقه خلاعتی در صورت و پیرایه ٔ تقوی و دین داری بود از میان برداشت، و عشتاروت را ملکةالسماء می نامیدند و غالباً عبادت او با عبادت بعل مذکور است و بسیاری از علماء بر آنند که قصد ازبعل آفتاب و قصد از عشتاروت ماهتاب میباشد یا اینکه بعل قوه ٔ ذکور و عشتاروت قوه ٔ اناثیه است و گمان میرود که بیشه های مذکور در میان اسرائیلیان محل عبادت همین خدائی مؤنث بوده است . (از قاموس کتاب مقدس ).<br></font></div>'),
(183549, 'عشتروت', '<span class=\"hlight\">عشتروت .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (اِخ ) عشتاروت . شهری است در باشان در مشرق اردن، و آن همان بعشرة میباشد که نامش در «یوشع» مذکور است، و برخی را عقیده بر آن است که تل عشرة در جولان واقع است . (از قاموس کتاب مقدس ) (از فرهنگ فارسی معین ).<br></font></div>'),
(183550, 'عشتق الصبیان', '<span class=\"hlight\">عشتق الصبیان .</span> <font color=\"DarkGreen\"><b>[ ؟ قُص ْ ص ِب ْ ]</font></b> (ع اِ مرکب ) شوکةالسودا است . (فهرست مخزن الادویة).<br></font></div>'),
(183551, 'عشج', '<span class=\"hlight\">عشج .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ِ ]</font></b> (ع اِ) شبانگاه، و آن لغتی است در عشی . (ناظم الاطباء).<br></font></div>'),
(183552, 'عشجب', '<span class=\"hlight\">عشجب .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ع ص ) مرد فروهشته اندام . (منتهی الارب ). مرد مسترخی و سست . (از اقرب الموارد).<br></font></div>'),
(183553, 'عشد', '<span class=\"hlight\">عشد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) گرد آوردن چیزی را. (از منتهی الارب ). جمع کردن . (از اقرب الموارد).<br></font></div>'),
(183554, 'عشر', '<span class=\"hlight\">عشر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) ده یک اموال را گرفتن . (از ناظم الاطباء): عشر القوم ؛ عُشر اموال آن قوم را گرفت . (از اقرب الموارد). ده یک بستدن . (تاج المصادر بیهقی ) (المصادر زوزنی ). دهم حصه از چیزی گرفتن . (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> یکی از ده گرفتن، یا یک بر نُه زیاده نمودن . (از منتهی الارب ) (از اقرب الموارد). ده بکردن . (تاج المصادر بیهقی ) (دهار). <BR><font color=\"Blue\">◄</font> دهم قوم گردیدن : عشر القوم ؛ دهم آن قوم شد. (از منتهی الارب ) (از اقرب الموارد). دهم شدن . (تاج المصادر بیهقی ) (دهار). <BR><font color=\"Blue\">◄</font> عُشَراء گردیدن ناقه . (از منتهی الارب ) (از اقرب الموارد). رجوع به عُشَراء شود. <BR><font color=\"Blue\">◄</font> بیست گردانیدن چیزی را، و آن نادراست . (از منتهی الارب ). <br></font></div>'),
(183555, 'عشر', '<span class=\"hlight\">عشر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع عدد، ص، اِ) ده زن . (منتهی الارب ) (دهار). اسم است عدد ده را در صورتی که مضاف الیه آن مؤنث بود. (ناظم الاطباء). از اعداد مفرد اصلی است که با معدود مؤنث، بدون تاء و با معدود مذکربا تاء تأنیث بکار رود، و تمییز آن جمع و مجرور باشد <span class=\"hlight\">:</span> من جاء بالحسنة فله عشر أمثالها (قرآن <span class=\"hlight\" dir=\"rtl\">١٦٠/٦</span>)؛ کسی که نیکی بیاورد پس او را ده چندان آن است . قل فأتوا بعشر سور مثله مفتریات (قرآن <span class=\"hlight\" dir=\"rtl\">١٣/١١</span>)؛بگو پس بیاورید ده سوره مثل آن که بربافته و دروغ باشد. و لیال عشر (قرآن <span class=\"hlight\" dir=\"rtl\">٢/٨٩</span>)؛ سوگند به شبهای ده گانه . و واعَدْنا موسی ثلاثین لیلة و أتممناها بعشر (قرآن <span class=\"hlight\" dir=\"rtl\">١٤٢/٧</span>)؛ و وعده دادیم موسی را به سی شب و کامل کردیم آن را به ده . <BR><font color=\"Blue\">◄</font> دهه : عشر اول محرم . عشر اول رمضان ؛ دهه ٔ اول آن . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">اصطرلاب عشر</span> ؛ برای هر ده درجه در اصطرلاب معمول است . رجوع به اصطرلاب شود.<br> <BR><font color=\"Blue\">◄</font> هر ده آیه از قرآن مجید. (ناظم الاطباء). ده آیت قرآن مجید، که در زمان قدیم رسم قاریان این بود که شاگرد خود را هر روز ده آیت سبق میدادند. (غیاث اللغات ) (آنندراج ). نشان که بر سر ده آیت در قرآن کنند. (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> <br>برگ بنفشه بخم، چو پشت درم زن <br>نرگس چون عشر در میان مجلد.<br> <font color=\"Red\">منوچهری .</font><br>نرگس میان باغ تو گویی درم زنیست <br>اوراق عشرهای مجلد کند همی .<br> <font color=\"Red\">منوچهری .</font><br>عشرهای مصحف مجد تو را<br>بیشتر باید ز گردون لاجورد.<br> <font color=\"Red\">عمادی شهریاری .</font><br>ثم یخطب خطبته الاخیرة بقراءة هؤلاء الاَّیات «یا عبادی الذین أسرفوا علی أنفسهم ... اًلی تمام العشر». (سیره ٔ عمربن عبدالعزیز ص <span class=\"hlight\" dir=\"rtl\">٢١٣</span>).<br>- <span class=\"hlight\">عشر زرین </span> ؛ اشاره است به کلمه ٔ «عشر»که در حاشیه ٔ قرآنهای قدیم بخط زرین آن را بر سر هرده آیت می نوشتند. (از فرهنگ فارسی معین ).<br></font></div>'),
(183556, 'عشر', '<span class=\"hlight\">عشر.</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (ع اِ) جزء دوم اعداد مرکب عربی است چون أحدعشر، یازده و اثناعشر، دوازده و تسعةعشر، نوزده . و گاهی در اعداد مفرد نیز بکار رود چون عشر کلمات، یعنی ده کلمه . (از ناظم الاطباء).<br></font></div>'),
(183557, 'عشر', '<span class=\"hlight\">عشر.</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (اِخ ) قلعه ای است استوار در سرزمین اندلس از ناحیه ٔ شرق، از اعمال أشِقة، و آن ازآن ِ فرنگی ها است . (از معجم البلدان ).<br></font></div>'),
(183558, 'عشر', '<span class=\"hlight\">عشر.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) یک قطعه از هر چیزی که به ده قسمت شده باشد. (از اقرب الموارد). ده یک پاره ٔ چیز شکسته . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> قطعه ای که از قدح یا دیگ می شکند، گوئی که آن قطعه ای است از ده پاره . ج، أعشار. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مابین دو نوبت آب شتر که هشت روز باشد بدان جهت که روز اول و دهم آب دهند و به آب آمدن شتر روز دهم باشد یا روز نهم . (منتهی الارب ) (از اقرب الموارد). و بعد از عشر، نامی نیست جز عشرین، و اگر در روز بیستم به آب برسند گویند «ظمؤها عشران » که آن هجده روز باشد. (از اقرب الموارد) (از منتهی الارب ).<br></font></div>'),
(183559, 'عشر', '<span class=\"hlight\">عشر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َ ]</font></b> (ع اِ) سه شب از هر ماه که بعداز شب نهم آید. (منتهی الارب ). سه شب از شبهای ماه، که پس از تُسَع واقع است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> هر نباتی را گویند که در وقت شکستن شاخ آن یابرکندن برگ آن شیری از وی برآید. (برهان قاطع). <BR><font color=\"Blue\">◄</font> نام رستنیی است که ثمر و میوه ٔ آن را بعربی خرفع گویند که کاویشه باشد و عصفر نیز خوانند. و بعضی گویند نوعی از حرشف است که کنگر باشد، و کنگرماست چیزی است مشهور. و بعضی دیگر گویند درختی است که آن را در هندوستان آگ خوانند و به لغت اهل عمان سنای مکی باشد. (برهان قاطع). هر نباتی که شیر دهد، خصوصاً درخت آک . (غیاث اللغات )(آنندراج ). به هندوی جس گویند، و آن را صمغ باشد شیرین و طعم او شیرین بود و میوه ٔ او مجوف باشد و در میان میوه ٔ او به شبه پنبه چیزی باشد، چون جرم او شکافته شود آن چیز که در میان او بود به شبه پنبه نمایدو در زیر پنبه سر دانه باشد و از آن دانه شکر و عشرسازند، و در خزاین ملوک باشد و با او بعضی علتها رادارو کنند، و آن پنبه را خرفع گویند. (از تذکره ٔ ضریر انطاکی ). درختی است که آتش زود درگیرد و مردم از آن بهترین به چقماق آتش نگیرند، و از آن نازبالش سازند، و شکری مشهور که از شکوفه و شاخ آن برآید و در آن یک گونه تلخی باشد. (منتهی الارب ). درختی است با خاصیت سوزندگی و مردم آتش زنه ای نیکوتر از آن نگیرند، وداخل مخده ها و بالش ها را از آن پر کنند و از شکوفه و شاخه های آن شکری تلخ مزه بیرون آید، و گویند آن از عضاه، و از درختان بزرگ است و آن را صمغی شیرین مزه باشد و برگهائی عریض و رو به آسمان دارد و از شاخه ها و محل شکوفه های آن شیره ای خارج میشود. یک دانه ٔ آن عُشَرة و جمع آن عُشَر و عُشَرات است . (از اقرب الموارد). درختی است عرابی ازجمله ٔ یتوعات . (ذخیره ٔ خوارزمشاهی ). درخت خرک، و به هندی آک نامند. (از مخزن الادویة). درختی است بزرگ که نوعی من ّ و صمغی شیرین در گل و شاخه های آن است که کمی به تلخی زند، برگ پهن دارد و قسمی قَو در آن است که بهترین اقسام قو باشد. (یادداشت مرحوم دهخدا). بعضی گفته اند که ثمره ٔ آن را حرمع خوانند و از یتوعات سبعه است . (نزهةالقلوب ). استبرق . آک . آگ . کاجیره . کاچیره . کافشه . کرک . اشخر. رجوع به اشخر و استبرق و کاجیره و آگ و سکرالعشر شود.<br></font></div>'),
(183560, 'عشر', '<span class=\"hlight\">عشر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ده یک . (منتهی الارب ) (دهار). یک جزء از ده . (از اقرب الموارد). ده یوده، یعنی یک پاره از ده پاره ٔ هر چیزی . (ناظم الاطباء). ج، عُشور. أعشار. (منتهی الارب ) (اقرب الموارد) <span class=\"hlight\">:</span> <br>سقراط اگر برجعت بازآید<br>عشری گمان بریش ز عشرینم .<br> <font color=\"Red\">ناصرخسرو.</font><br>آن عطا کز ملوک یافته ام <br>عشر آن وقت اهتزاز فرست .<br> <font color=\"Red\">خاقانی .</font><br>همه اقرار کردند که آن جنس در حوصله ٔ ظنون نگنجد و خزانه ٔ قارون به عشر آن نرسد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٧٥</span>). <BR><font color=\"Blue\">◄</font> (اصطلاح فقه ) یک دهمی که به تمام محصولات زمینی تعلق میگرفت .در بین فقها اختلاف است در این که کدام محصول از پرداخت عشر معاف است، و نیز در مورد نصاب عشر میان فقیهان اتفاق آراء وجود ندارد. نرخی که برحسب آن میبایست عشر وصول شود مختلف و عبارت بود از نیم دهم، یک دهم، یک ونیم دهم و مضاعف عشر. بطور کلی در صدر اسلام از زمینهائی که با آب جاری مشروب میشد یک دهم و از زمینهایی که با وسایل مصنوعی آبیاری میگشت نیم دهم بعنوان عشر میگرفتند، و مجوز این عمل را میتوان در معامله ای که حضرت رسول (ص ) با مردم «بیشه » کرد، سراغ نمود. معمولاً عشر را مسلمانان می پرداختند. (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>دل به رصدگاه دهر بیش بها گوهریست <br>دخل ابد عشر او فیض ازل کان او.<br> <font color=\"Red\">خاقانی .</font><br>عاشقان را هر زمان سوزیدنیست <br>برده ویران خراج و عشر نیست .<br> <font color=\"Red\">مولوی .</font><br>مَکس ؛ عشرکه در جاهلیت در بازار از بایع میگرفتند. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اصطلاح فقه ) آنچه گرفته میشد از زکات زمین قبول کنندگان اسلام و یا زمینی که مسلم آن را احیاء کرده بود. (یادداشت مرحوم دهخدا). ده یک زکاتی که از محصولاتی که زکات بر آنها تعلق میگیرد گرفته میشود بشرط آنکه محصولات مزبور بدون هزینه آبیاری شود. (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> (ص ) ناقه ای که شیر اندک فرودآیدش بی فراهم آمدگی . (منتهی الارب ). شتران که شیر آنها بدون اینکه جمع شود، اندک فرودآید. (از اقرب الموارد).<br></font></div>'),
(183561, 'عشر', '<span class=\"hlight\">عشر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) ده یک گرفتن از اموال کسی . (از منتهی الارب ). ده یک بستدن . (دهار). عَشر. و رجوع به عَشر شود.<br></font></div>'),
(183562, 'عشر', '<span class=\"hlight\">عشر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َ ]</font></b> (اِخ ) (ذو...) وادیی است بین بصره و مکه از دیار تمیم، سپس ازآن ِ بنی مازن بن مالک بن عمرو، از نواحی نجد. و نام آن در شعر مزاحم عقیلی آمده است . (از معجم البلدان ).<br></font></div>'),
(183563, 'عشر', '<span class=\"hlight\">عشر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َ ]</font></b> (اِخ ) شعب و آبراهه ای است ازآن ِ هذیل که از داعة فرومیریزد، و آن کوهی است محصور بین دو نخله . و گویند آن وادیی است در حجاز. و گویند شعبی است ازآن ِ هذیل در نزدیکی مکه نزدیک نخلةالیمانیة. (از معجم البلدان ).<br></font></div>'),
(183564, 'عشر ادب', '<span class=\"hlight\">عشر ادب .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ اَ دَ ]</font></b> (ترکیب اضافی، اِ مرکب ) سبق ادب، و عشر ده آیت را هم گویند. (آنندراج ). رجوع به عُشر شود <span class=\"hlight\">:</span> <br>عشر ادب خوانده ز سبع سما<br>عذر قدم خواسته از انبیا.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(183565, 'عشر عشیر', '<span class=\"hlight\">عشر عشیر.</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ع َ ]</font></b> (ترکیب اضافی، اِ مرکب ) حصه ٔ دهم از دهم حصه ٔ چیزی، پس آن صدم حصه میشود از مجموعه ٔ اول، چنانکه عشیر صدده است و عشر ده یک . (غیاث اللغات ) (آنندراج ). یک جزء از صد جزء هر چیزی . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>یافت احمد به چهل سال مکانی که نیافت <br>به نود سال براهیم از آن عشر عشیر.<br> <font color=\"Red\">ناصرخسرو.</font><br>ازین قدر کامروز دارم به علم <br>نبودستم آن روز عشر عشیر.<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(183566, 'عشرا', '<span class=\"hlight\">عشرا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) (پرده ٔ...) نوائی است از موسیقی . (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> <br>گاه کوه بیستون و گنج بادآور زنند<br>گاه دست سلمکی و پرده ٔ عشرا برند.<br><font color=\"Red\">ضمیری .</font><br></font></div>'),
(183567, 'عشرات', '<span class=\"hlight\">عشرات .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َ ]</font></b> (ع اِ) ج ِ عُشَرة. (از اقرب الموارد) (از منتهی الارب ). رجوع به عشرة شود.<br></font></div>'),
(183568, 'عشرات', '<span class=\"hlight\">عشرات .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (ع اِ) ج ِ عشرة. رجوع به عشرة شود.<br>- <span class=\"hlight\">دعای عشرات </span> ؛ یکی از ادعیه ٔ مشهور است که آغاز میشود به «سبحان اﷲ و الحمد ﷲ و لااله الااﷲ و اﷲاکبر...». رجوع به کتب ادعیه شود.<br> <BR><font color=\"Blue\">◄</font> (اصطلاح حساب ) آن را دهائی گویند و دهائی همه نه اند چنانکه ده و بیست و سی و چهل و پنجاه و شصت و هفتاد و هشتاد و نود. (غیاث اللغات ) (آنندراج ). مرتبه ٔ بعد از آحاد از اعداد را گویند که از ده تا نود باشد، و دهاک نیز گویند. (ناظم الاطباء). دهگان . (التفهیم ). مرتبه ٔبعد از آحاد که از ده تا نودونُه را شامل است . دهگان در اصطلاح فرهنگستان . (از فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>آن نبینی که یکی ده گردد<br>چون ز آحاد رسد در عشرات .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(183569, 'عشراوات', '<span class=\"hlight\">عشراوات .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َ ]</font></b> (ع ص، اِ) ج ِ عُشَراء.(منتهی الارب ) (اقرب الموارد). رجوع به عشراء شود.<br></font></div>'),
(183570, 'عشراوان', '<span class=\"hlight\">عشراوان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َ ]</font></b> (ع ص، اِ)مثنای عُشَراء. (منتهی الارب ). رجوع به عشراء شود.<br></font></div>'),
(183571, 'عشراویة', '<span class=\"hlight\">عشراویة.</span> <font color=\"DarkGreen\"><b>[ ع َ وی ی َ ]</font></b> (ع اِ) نوعی نسبت است به «عشرة»، وآن از سکه های نقره ای رایج در شرق اردن بوده است (ازسال <span class=\"hlight\" dir=\"rtl\">١٨٠٠</span> تا <span class=\"hlight\" dir=\"rtl\">١٩٢٥</span> م .)، و آن را انواعی بوده است . ج، عَشاری ّ. رجوع به النقود العربیة ص <span class=\"hlight\" dir=\"rtl\">٩٤</span> و <span class=\"hlight\" dir=\"rtl\">١٨٠</span> شود.<br></font></div>'),
(183572, 'عشرب', '<span class=\"hlight\">عشرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ش َرْ رَ ]</font></b> (ع ص ) تیر درگذرنده . (منتهی الارب ). سهم ماضی، و برخی آن را شهم به شین معجم ضبط کرده اند. <BR><font color=\"Blue\">◄</font> خشن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شیر بیشه . (منتهی الارب ). اسد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سخت روان، هرچه باشد. (منتهی الارب ). سخت و باجرأت، و برخی آن را سخت جریان نوشته اند. (از اقرب الموارد).<br></font></div>'),
(183573, 'عشرت', '<span class=\"hlight\">عشرت .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (ع اِمص ) عِشْرة. مصاحبت کردن . معاشرت کردن . (فرهنگ فارسی معین ). الفت و مصاحبت . (ناظم الاطباء). خوش زندگانی کردن با هم . (غیاث ). سازگاری . (تاریخ بیهقی ). رجوع به عشرة شود <span class=\"hlight\">:</span> <br>چرا از یار بدعشرت سگالی <br>ز مدح شاه نیک اختر سگالا.<br> <font color=\"Red\">عنصری .</font><br>با که کردستی این صحبت و این عشرت <br>بر تن خویش نبوده ست تو را حَمْیت .<br> <font color=\"Red\">منوچهری .</font><br>اما بنده امیدوار میباشد که به عشرت صالحان تربیت پذیرد. (گلستان ). مدتها در حلقه ٔ عشرت مابود. (گلستان ). <BR><font color=\"Blue\">◄</font> خوشدلی . (غیاث اللغات ). عیش و نشاط. (آنندراج ). خوش دلی و عیش و شادی و زندگانی خوش و خوشگذرانی و کامرانی و خرسندی و خرمی . (ناظم الاطباء) <span class=\"hlight\">:</span> مردی بود به هراة که او را قاضی منصور گفتندی در فضل و هر علم دستی تمام داشت و شراب و عشرت دوست داشت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>).<br>وقت طرب است و روز عشرت <br>ایام گل است و فصل نیسان .<br> <font color=\"Red\">خاقانی .</font><br>پارسا را چه لذت از عشرت <br>خنفسا را چه نسبت از عطار.<br> <font color=\"Red\">خاقانی .</font><br>چو روزی چند از عشرت برآسود<br>چو سیر آمد ز عشرت کوچ فرمود.<br><font color=\"Red\">نظامی .</font><br>مجلس افروخته چون نوبهار<br>عشرتی آسوده تر از روزگار.<br> <font color=\"Red\">نظامی .</font><br>یکی از ملوک را شنیدم که شبی در عشرت به روز آورده بود. (گلستان ).<br>عشرت خوش است و بر طرف جوی خوشتر است <br>می برسماع بلبل خوشگوی خوشتر است .<br> <font color=\"Red\">سعدی .</font><br>شبی در خرقه رندآسا گذر کردم به میخانه <br>ز عشرت می پرستان را منور گشت کاشانه .<br> <font color=\"Red\">سعدی .</font><br>چنگ خمیده قامت میخواندت به عشرت <br>بشنو که پند پیران هیچت زیان ندارد.<br> <font color=\"Red\">حافظ.</font><br>شکر آن را که تو در عشرتی ای مرغ چمن <br>به اسیران قفس مژده ٔ گلزار بیار.<br> <font color=\"Red\">حافظ.</font><br>فکر شنبه تلخ داردجمعه ٔ اطفال را<br>عشرت امروز بی اندیشه ٔ فردا خوش است .<br> <font color=\"Red\">صائب .</font><br>- <span class=\"hlight\">به عشرت </span> ؛ به خوشی و شادی . شادمانه <span class=\"hlight\">:</span> <br>فردا که رود جان تو از تن بیرون <br>اعدا همه آن مال به عشرت بخورند.<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عشرت امروز به فردا افکندن </span> ؛ عبارت است از عیش نقد به نسیه فروختن . (آنندراج ) <span class=\"hlight\">:</span> <br>ساقیا عشرت امروز به فردا مفکن <br>یا ز دیوان قضا خط امانی به من آر.<br> <font color=\"Red\">حافظ.</font><br>ای دل ار عشرت امروز به فردا فکنی <br>مایه ٔ نقد بقا را که ضمان خواهد شد.<br> <font color=\"Red\">حافظ.</font><br>حافظا تکیه برایام چو سهو است و خطا<br>من چرا عشرت امروز به فردا فکنم .<br> <font color=\"Red\">حافظ (از آنندراج ).</font><br>میَفکن نوبت عشرت به فردا<br>چو اسباب مهیا داری امروز.<br><font color=\"Red\">فقیهی مروزی .</font><br></font></div>'),
(183574, 'عشرت آباد', '<span class=\"hlight\">عشرت آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (اِخ ) دهی جزء دهستان قزل گچیلو از بخش ماه نشان شهرستان زنجان . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٤٠</span> تن . آب آن از چشمه . محصول آن غلات و انگور است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(183575, 'عشرت آباد', '<span class=\"hlight\">عشرت آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (اِخ ) (قصر...) از باغهای مشهور اطراف شهر تهران در طرف شمال، که فعلاً سربازخانه ٔ دولتی است . و رجوع به مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٦</span> و سه سال در دربار ایران ترجمه ٔ عباس اقبال ص <span class=\"hlight\" dir=\"rtl\">١٩٠</span> و <span class=\"hlight\" dir=\"rtl\">١٩١</span> شود.<br></font></div>'),
(183576, 'عشرت آباد', '<span class=\"hlight\">عشرت آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (اِخ ) دهی جزء دهستان زهرا ازبخش بوئین شهرستان قزوین . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٣٧٢</span> تن . آب آن از قنات . محصول آن غلات، چغندرقند، یونجه، انگور، سردرختی و بادام است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(183577, 'عشرت آباد', '<span class=\"hlight\">عشرت آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (اِخ ) دهی از دهستان مرکزی بخش حومه ٔ شهرستان کاشمر. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٨٦٠</span> تن . آب آن از قنات . محصول آن غلات، میوه های باغ، انگور، پنبه و زیره است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183578, 'عشرت آباد', '<span class=\"hlight\">عشرت آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (اِخ ) دهی از دهستان سراجو از بخش مرکزی شهرستان مراغه . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> تن . آب آن از رودخانه ٔ چکان و چشمه . محصول آن غلات، پنبه، نخود، کشمش، بادام، کرچک و زردآلو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(183579, 'عشرت آباد', '<span class=\"hlight\">عشرت آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (اِخ ) دهی از دهستان رشخوار بخش رشخوار شهرستان تربت حیدریه . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢٥٥</span> تن . آب آن از قنات . محصول آن غلات وبنشن و پنبه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183580, 'عشرت آباد', '<span class=\"hlight\">عشرت آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (اِخ ) دهی از بخش حومه ٔ شهرستان نائین . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢٧٤</span> تن . آب آن از قنات . محصول آن غلات، حبوب، بادام، پسته و پنبه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(183581, 'عشرت آباد', '<span class=\"hlight\">عشرت آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (اِخ ) دهی از دهستان دربقاضی بخش حومه ٔ شهرستان نیشابور. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٤٦٣</span> تن . آب آن از قنات . محصول آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183582, 'عشرت افروز', '<span class=\"hlight\">عشرت افروز.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ اَ ]</font></b> (نف مرکب ) عشرت افروزنده . باعث شادی و خوشی و خوشدلی و کامرانی <span class=\"hlight\">:</span> <br>گروهی تازه روی و عشرت افروز<br>بگاه خوشدلی روشن تر از روز.<br> <font color=\"Red\">نظامی .</font><br>و رجوع به عشرت شود.<br></font></div>'),
(183583, 'عشرت انگیختن', '<span class=\"hlight\">عشرت انگیختن .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ اَ ت َ ]</font></b> (مص مرکب ) عشرت کردن . شادی و کامرانی کردن <span class=\"hlight\">:</span> <br>خیز تا عشرتی برانگیزیم <br>یک زمان از زمانه بگریزیم .<br> <font color=\"Red\">مولوی (از آنندراج ).</font><br>و رجوع به عشرت شود.<br></font></div>'),
(183584, 'عشرت انگیز', '<span class=\"hlight\">عشرت انگیز.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ اَ ]</font></b> (نف مرکب ) عشرت انگیزنده . برانگیزنده ٔ عشرت و کامرانی <span class=\"hlight\">:</span> <br>زگال ارمنی بر آتش تیز<br>سیاهانی چو زنگی عشرت انگیز.<br> <font color=\"Red\">نظامی .</font><br>پگه تر زآن بتان عشرت انگیز<br>میان دربست شاپور سحرخیز.<br> <font color=\"Red\">نظامی .</font><br>و رجوع به عشرت شود.<br></font></div>'),
(183585, 'عشرت زای', '<span class=\"hlight\">عشرت زای .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (نف مرکب ) عشرت زاینده . زاینده و ایجادکننده ٔ عشرت و طرب و کامرانی <span class=\"hlight\">:</span> <br>حامله ست اقبال مادرزاد او<br>قابله ش ناهید عشرت زای باد.<br> <font color=\"Red\">خاقانی .</font><br>و رجوع به عشرت شود.<br></font></div>'),
(183586, 'عشرت ساز', '<span class=\"hlight\">عشرت ساز.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (نف مرکب ) عشرت سازنده . سازنده ٔ عشرت و کامرانی <span class=\"hlight\">:</span> <br>لعبتان آمدند عشرت ساز<br>آسمان بازگشت لعبت ساز.<br> <font color=\"Red\">نظامی .</font><br>چنان کن کز تو دلخوش بازگردم <br>به دیدار تو عشرت ساز گردم .<br> <font color=\"Red\">نظامی .</font><br>و رجوع به عشرت شود.<br></font></div>'),
(183587, 'عشرت سرای', '<span class=\"hlight\">عشرت سرای .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ س َ ]</font></b> (اِ مرکب ) عشرت سرا. عشرتخانه . عشرتگاه . محل عشرت و کامرانی <span class=\"hlight\">:</span> <br>بس شخص بینوا که ورا از علوّ قدر<br>عشرت سرای جنت اعلی مکان شود.<br> <font color=\"Red\">سعدی .</font><br>و رجوع به عشرت شود.<br></font></div>'),
(183588, 'عشرت فزا', '<span class=\"hlight\">عشرت فزا.</span> <font color=\"DarkGreen\"><b>[ ع ِ رَف َ ]</font></b> (نف مرکب ) عشرت فزای . عشرت فزاینده <span class=\"hlight\">:</span> <br>همیشه تا صفت بزم و رزم باشد خوش <br>بگوش مردم عشرت فزای و جنگ آغال .<br> <font color=\"Red\">سوزنی .</font><br>اگرچه با شما عشرت فزایم <br>نمی سازد درین آب و هوایم .<br> <font color=\"Red\">نظامی .</font><br>و رجوع به عشرت شود.<br></font></div>'),
(183589, 'عشرت کده', '<span class=\"hlight\">عشرت کده .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) عشرتخانه . عشرتگاه . عشرت سرا. محل عیش و عشرت <span class=\"hlight\">:</span> <br>باغ و عشرتکده ایوان به ملوک ارزانی <br>ما فقیریم و گدا کوی بتان ما را بس .<br> <font color=\"Red\">حافظ (از آنندراج ).</font><br>رشک عشرتکده غمخانه ٔ درویشان است <br>آسمان کاشی کاشانه ٔ درویشان است .<br><font color=\"Red\">ظهوری (از آنندراج ).</font><br></font></div>'),
(183590, 'عشرت کردن', '<span class=\"hlight\">عشرت کردن .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ک َ دَ ]</font></b> (مص مرکب ) عیش کردن . شادی کردن . کامرانی کردن . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>تا بوستان چنین است از گل سزد که تو<br>گر عشرتی کنی همه در بوستان کنی .<br><font color=\"Red\">مسعودسعد.</font><br>شه آنجا روز و شب عشرت همی کرد<br>می تلخ و غم شیرین همی خورد.<br> <font color=\"Red\">نظامی .</font><br>بپوش چشم ز وضع جهان و عشرت کن <br>ببند در به رخ کائنات و وحدت کن .<br> <font color=\"Red\">صائب (از آنندراج ).</font><br>بهار آمد ازبهر دفع خزان <br>که عشرت توان کرد در بوستان .<br> <font color=\"Red\">ملاطغرا (از آنندراج ).</font><br>فال فردا میزنم وِامروز عشرت میکنم .<br> <font color=\"Red\">؟</font><br>و رجوع به عشرت شود.<br></font></div>'),
(183591, 'عشرتخانه', '<span class=\"hlight\">عشرتخانه .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) محل شادی و خوشگذرانی . عشرت گاه . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> نوای نشاط و خرمی به عشرتخانه ٔ ناهید رسانید. (حبیب السیر چ تهران ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٥</span>). در بعضی از منزهات بستانها و عشرتخانه ها به عیش و نشاط و طرب مشغول بود. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span>).<br></font></div>'),
(183592, 'عشرتستان', '<span class=\"hlight\">عشرتستان .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ت ِ ]</font></b> (اِ مرکب ) عشرتخانه . عشرت گاه . محل عیش و عشرت <span class=\"hlight\">:</span> <br>ز هند دیده ٔ بد دور عشرتستان است .<br><font color=\"Red\">طالب کلیم (از آنندراج ).</font><br></font></div>'),
(183593, 'عشرتگاه', '<span class=\"hlight\">عشرتگاه .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ]</font></b> (اِ مرکب ) عشرتگه . محل شادی و خوشگذرانی . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>از گلستان تا به عشرتگاه مستان میکشد<br>ذوق رنگ آمیزی گلهای رسوائی مرا.<br><font color=\"Red\">میرزا رضی دانش (از آنندراج ).</font><br></font></div>'),
(183594, 'عشرتگه', '<span class=\"hlight\">عشرتگه .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ گ َه ْ ]</font></b> (اِ مرکب ) عشرتگاه . محل عشرت و طرب <span class=\"hlight\">:</span> <br>نیروده توست ناف خرچنگ <br>عشرتگه تو دهان ضیغم .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(183595, 'عشرخوان', '<span class=\"hlight\">عشرخوان .</span> <font color=\"DarkGreen\"><b>[ ع َ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) عشرخواننده . طفل نوآموز قرآن خوان، چرا که طفل را اول ده آیت بطریق تبرک سبق دهند. (غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> <br>وز چوب زدن رباب فریاد<br>چون کودک عشرخوان برآورد.<br> <font color=\"Red\">خاقانی .</font><br>از شجر من شعرا میوه چین <br>وز صحف من فضلا عشرخوان .<br> <font color=\"Red\">خاقانی .</font><br>زآن پس که چار صحف قناعت بخوانده ای <br>خود را ز لوح بوالطمعی عشرخوان مخواه .<br> <font color=\"Red\">خاقانی .</font><br><BR><font color=\"Blue\">◄</font> قاری قرآن، که قرأت کننده و حافظ کلام اﷲباشد. (برهان قاطع). قاری کلام اﷲ شریف . <BR><font color=\"Blue\">◄</font> شخصی که بر گور مرده قرآن خواند. (آنندراج ) (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> مردم معزول شده . (برهان قاطع). معزول . (آنندراج ) (غیاث اللغات ). معزول از شغل و عمل . (ناظم الاطباء).<br></font></div>'),
(183596, 'عشرستان', '<span class=\"hlight\">عشرستان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َ رِ ]</font></b> (اِ مرکب ) جای انبوه از گیاه عُشَر. (ناظم الاطباء). رجوع به عُشَر شود.<br></font></div>'),
(183597, 'عشرق', '<span class=\"hlight\">عشرق .</span> <font color=\"DarkGreen\"><b>[ ع ِ رِ ]</font></b> (ع اِ) گیاهی است از قسم اغلاث، دانه ٔ آن نافع بواسیر است و نیز شیر زیاده پیدا کند و موی را سیاه گرداند. (منتهی الارب ). تخمی است دوائی که آن را به عربی بزرالمرو و بفارسی تخم مرو گویند. (برهان قاطع). از جنس حشایش است و برگ اوبه برگ درخت غار مشابهت دارد، و بار درخت عشرق به هیئت بزرگتر باشد و او را جهت زینت بکار برند و موی را سیاه کند، و بعضی گفته اند او را ساق باشد اما ساق او کوتاه باشد و طعم او تیز است و علت بواسیر را سوددارد. (از تذکره ٔ ضریر انطاکی ). به لغت حجاز سناء عریض الورق است و بعضی گویند مرو است و برخی آن را گیاهی دانند که برگش شبیه به برگ غار و سرخ و خوشبو است، و عروسان استعمال میکنند. (از تحفه ٔ حکیم مؤمن ). نباتی است از اغلاث، یکی آن عِشْرِقة. و گویند نباتی است سرخ رنگ که عروسان بکار برند، و گویند درختی است به اندازه ٔ یک ذراع دارای دانه های کوچکی که چون خشک شوند به وزش باد، بصدا می آیند. (از اقرب الموارد).<br></font></div>'),
(183598, 'عشرم', '<span class=\"hlight\">عشرم .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع ص ) سخت درشت . (منتهی الارب ). خشن شدید. (از اقرب الموارد).<br></font></div>'),
(183599, 'عشرم', '<span class=\"hlight\">عشرم .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َرْ رَ ]</font></b> (ع ص، اِ) تیر درگذرنده . (منتهی الارب ) . رجوع به عشرب شود. <BR><font color=\"Blue\">◄</font> شیر بیشه . (منتهی الارب ). اسد. (اقرب الموارد).<br></font></div>'),
(183600, 'عشرون', '<span class=\"hlight\">عشرون .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع عدد، ص، اِ) بیست . (منتهی الارب ) (دهار). اسم است مر عدد بیست را، و مذکر و مؤنث در وی یکسان است . (ناظم الاطباء). درحال رفع با واو و در حال نصب و جر با یاء می آید، و در حال اضافه جایز است نون آن حذف شود از جهت شباهت به نون جمع، و گفته شود عشرو زید، و عشری زید (با قلب واو آن به یاء و ادغام دو یاء). (از اقرب الموارد). از اعداد عقود اصلی و ترتیبی است در حالت رفعی، و در فارسی رعایت این حالت نگردد <span class=\"hlight\">:</span> اًن یکن منکم عشرون صابرون یغلبوا مائتین (قرآن <span class=\"hlight\" dir=\"rtl\">٦٥/٨</span>)؛ اگر از شما بیست تن شکیبا باشند بر دویست تن فائق آیند.<br>- <span class=\"hlight\">عشرون ألفاً</span> ؛ بیست هزار. (دهار).<br></font></div>'),
(183601, 'عشرون', '<span class=\"hlight\">عشرون .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) نام جایگاهی است در عینة. (از معجم البلدان ).<br></font></div>'),
(183602, 'عشری', '<span class=\"hlight\">عشری .</span> <font color=\"DarkGreen\"><b>[ ع ُ ری ی <span class=\"hlight\" dir=\"rtl\">/</span> ری ]</font></b> (از ع، ص نسبی ) قابل زکات . (ناظم الاطباء). منسوب به عُشر در معنی فقهی <span class=\"hlight\">:</span> و اندر عراق هیچ ناحیت نیست عشری مگر بصره . (حدود العالم ).<br></font></div>'),
(183603, 'عشری', '<span class=\"hlight\">عشری .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َ ری ی ]</font></b> (ع ص نسبی ) منسوب به عُشَر: لبن عشری ؛ شیر شترانی که از درخت عشر چرا کرده باشند. (از اقرب الموارد). و رجوع به عُشَر شود.<br></font></div>'),
(183604, 'عشری', '<span class=\"hlight\">عشری .</span> <font color=\"DarkGreen\"><b>[ ع ِ ری ی َ ]</font></b> (ع اِ مرکب ) (از: عشرین + ی، ضمیر متکلم ) بیست عدد من . (از ناظم الاطباء).<br></font></div>'),
(183605, 'عشریة', '<span class=\"hlight\">عشریة.</span> <font color=\"DarkGreen\"><b>[ ؟ ری ی َ ]</font></b> (اِخ )از فِرَق مشبهه ٔ شیعه هستند. (خاندان نوبختی عباس اقبال ص <span class=\"hlight\" dir=\"rtl\">٢٥٩</span>). یکی از پنج فرقه ٔ اصحاب حدیث باشند. (بیان الادیان ). و رجوع به خطط مقریزی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٠</span> شود.<br></font></div>'),
(183606, 'عشرین', '<span class=\"hlight\">عشرین .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع عدد، ص، اِ) بیست . از اعداد عقود اصلی و ترتیبی، در حالت نصب و جر، که در زبان فارسی رعایت این حالت نشود. رجوع به عشرون شود <span class=\"hlight\">:</span> <br>سقراط اگر به رجعت بازآید<br>عشری گمان بریش ز عشرینم .<br> <font color=\"Red\">ناصرخسرو.</font><br>بر در تسعین کنند جنگ شبانروز<br>درگه عشرین ز جنگ هر دو معاف است .<br> <font color=\"Red\">خاقانی .</font><br>از در عشرین کتابش خواندمی <br>وز ره تسعین حسابش کردمی .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(183607, 'عشرین', '<span class=\"hlight\">عشرین .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ ن ِ ]</font></b> (ع اِ) مثنای عِشر، یعنی شانزده روز فاصله . (از ناظم الاطباء). رجوع به عِشر شود.<br></font></div>'),
(183608, 'عشرینات', '<span class=\"hlight\">عشرینات .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) انجمنهای بیستائی . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> در اصطلاح امروزین عرب زبانان، دهه ٔ بیست .<br></font></div>'),
(183609, 'عشرینیة', '<span class=\"hlight\">عشرینیة.</span> <font color=\"DarkGreen\"><b>[ ع ِ نی ی َ ]</font></b> (ع ص نسبی، اِ مرکب ) ماهانه ای که در روز دوازدهم از ماه بپردازند. (ناظم الاطباء). بیستگانی . (مهذب الاسماء). رزق . (یادداشت مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> ترجمه ای است از کلمه ٔ ترکی «یکرمیلک » به معنی بیستائی، و آن نام یکی از سکه های نقره ای بود که در حدود یک قرن پیش در مصر رواج داشت . (از النقود العربیة ص <span class=\"hlight\" dir=\"rtl\">٨٦</span> و <span class=\"hlight\" dir=\"rtl\">١٨٠</span>).<br></font></div>'),
(183610, 'عشز', '<span class=\"hlight\">عشز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِمص ) درشت اندام پرگوشت، فعلش نیامده . (منتهی الارب ).فعلی است متروک، و آن بمعنای درشتی جسم است . (از اقرب الموارد). درشتی و ستبری اندام . (ناظم الاطباء).<br></font></div>'),
(183611, 'عشزان', '<span class=\"hlight\">عشزان .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (ع مص ) به رفتار بریده پا رفتن . (از منتهی الارب ). راه رفتن بسان شخص بریده پای . (از اقرب الموارد) (از تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> بر چوب دستی تکیه نمودن . (از منتهی الارب ): عشز علی عصاه ؛ بر عصای خود تکیه کرد. (از اقرب الموارد).<br></font></div>'),
(183612, 'عشزب', '<span class=\"hlight\">عشزب .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ش َزْ زَ ]</font></b> (ع ص ) شیر بیشه ٔ درشت اندام . (منتهی الارب ) (از اقرب الموارد).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(183613, 'عشزن', '<span class=\"hlight\">عشزن .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َزْ زَ ]</font></b> (ع ص ) دشوار و پیچیده از هر چیزی . <BR><font color=\"Blue\">◄</font> درشت خلقت . (منتهی الارب ).<br></font></div>'),
(183614, 'عشزنة', '<span class=\"hlight\">عشزنة.</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ن َ ]</font></b> (ع مص ) خلاف کردن . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183615, 'عشش', '<span class=\"hlight\">عشش .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (ع مص ) لاغر و باریک گردیدن اندام . (از منتهی الارب )(از اقرب الموارد). عَشاشة. و رجوع به عشاشة شود.<br></font></div>'),
(183616, 'عشط', '<span class=\"hlight\">عشط.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) سخت کشیدن . (از منتهی الارب ). کشیدن چیزی را در حال جدا کردن آن . (از اقرب الموارد).<br></font></div>'),
(183617, 'عشعش', '<span class=\"hlight\">عشعش .</span> <font color=\"DarkGreen\"><b>[ ع ُ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ع َ ]</font></b> (ع اِ) آشیانه ٔمرغ زیر یکدیگر. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183618, 'عشق', '<span class=\"hlight\">عشق .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (ع مص ) عشق آوردن و چیره گردیدن دوستی بر کسی . (از منتهی الارب ). عاشق شدن . (المصادر زوزنی ). نیک شگفت داشتن . (تاج المصادر بیهقی ). تعلق قلب به کسی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چسبیدن . (از منتهی الارب ). التصاق به چیزی . (از اقرب الموارد). عِشق . مَعشَق . و رجوع به عشق و معشق شود.<br></font></div>'),
(183619, 'عشق', '<span class=\"hlight\">عشق .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (ع اِ) ج ِ عَشَقة. (منتهی الارب ) (اقرب الموارد). رجوع به عشقة شود.<br></font></div>'),
(183620, 'عشق', '<span class=\"hlight\">عشق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) عَشَق است درتمام معانی . (از منتهی الارب ) (از اقرب الموارد). به حد افراط دوست داشتن . (فرهنگ فارسی معین ). بسیار دوست داشتن چیزی . (غیاث اللغات ). رجوع به عَشَق شود.<br></font></div>'),
(183621, 'عشق', '<span class=\"hlight\">عشق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِمص ) شگفت دوست به حسن محبوب، یا درگذشتن ازحد در دوستی، و آن عام است که در پارسایی باشد یا در فسق، یا کوری حس از دریافت عیوب محبوب، یا مرضی است وسواسی که میکشد مردم را بسوی خود جهت خلط، و تسلیط فکر بر نیک پنداشتن بعضی صورتها. (منتهی الارب ). یامرضی است از قسم جنون که از دیدن صورت حسن پیدا میشود، و گویند که آن مأخوذ از عَشَقه است و آن نباتی است که آن را لبلاب گویند، چون بر درختی بپیچد آن را خشک کند، همین حالت عشق است بر هر دلی که طاری شود صاحبش را خشک و زرد کند. (از غیاث اللغات ). اسم است از مصدر عشق <font color=\"DarkGreen\"><b>[ ع َ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ]</font></b>، و آن بمعنی افراط است درحب از روی عفاف و یا فسق، و گویند اشتقاق آن از عشقه است بمعنی لبلاب که بر درخت می پیچد و ملازم آن میباشد. (از اقرب الموارد). بیماریی است که مردم آن را خود به خویشتن کشد و چون محکم شد بیماری باشد با وسواس مانند مالیخولیا. و خود کشیدن آن به خویشتن، چنان باشد که مردم اندیشه همه اندر خوبی و پسندیدگی صورتی بندد و امید اصل او اندر دل خویشتن محکم کند و قوت شهوانی او را بر آن مدد میدهد تا محکم گردد. (ذخیره ٔ خوارزمشاهی ). به معنی بسیار دوست داشتن است، و گران سنگ، بلنداقبال، بلندبالادست، چابک دست، آتش دست، جوانمرد، دریادل، دل افروز، بنده نواز، گره گشای، سخت بازو، سرکش، بی پروا، بی قرار، ستم پیشه، غیور، شورانگیز، شعله خوی، هستی سوز، جگرسوز، عالم سوز، خانه سوز، خانه پرداز، خونخوار و خون آشام از صفات اوست . و با لفظ باختن، سنجیدن، ورزیدن، خاستن، روئیدن و نشاندن مستعمل است . (از آنندراج ). بسیاری ِ محبت . (تاج المصادر بیهقی ). دوستی مفرط و محبت تام، و آن در روانشناسی یکی از عواطف است که مرکب میباشد از تمایلات جسمانی، حس جمال، حس اجتماعی، تعجب، عزت نفس و غیره . علاقه ٔ بسیار شدید و غالباً نامعقولی است که گاهی هیجانات کدورت انگیز را باعث میشود، و آن یکی از مظاهر مختلف تمایل اجتماعی است که غالباً جزو شهوات بشمار آید. (فرهنگ فارسی معین ). پشک و اشتیاق و محبت و دوستی بسیار، و مهر و بیقراری و دوستاری صورت خوب و خوشگل . (ناظم الاطباء).<br> <BR><font color=\"Blue\">◄</font> (اصطلاح تصوف و عرفان ) عشق به معبود حقیقی، اساس و بنیاد هستی بر عشق نهاده شده و جنب وجوشی که سراسر وجود را فراگرفته بهمین مناسبت است . پس کمال واقعی را در عشق باید جستجو کرد. (فرهنگ فارسی معین ).جمعیت کمالات را گویند که در یک ذات باشد، و این جز حق را نبود. (آنندراج ). تعریف آن نزد اهل سلوک آن است که آنچه تو را از متاع دنیا سودمند باشد ببخشائی بدیگران، و آنچه از دیگران بر تو رسد و زیان آور باشد به بردباری بپذیری و تحمل آن کنی . و عشق آخرین پایه ٔمحبت است و فرط محبت را عشق گویند. و گویند عشق آتشی است که در دل آدمی افروخته میشود و بر اثر افروختگی آن آنچه جز دوست است سوخته گردد. و نیز گفته اند که عشق دریائی است پر از درد و رنج . دیگری گوید عشق سوزش و کشته شدن است، اما بعد از شهادت با لطف ایزدی عاشق را زندگانی جاویدان نصیب گردد بطریقی که فنا و نیستی را در پیرامون او ره نباشد. و هم گفته اند عشق جنونی الهی است که بنیان خود را ویران سازد. و نیز گفته اند ثبات و استواری دل با معشوق باشد بلاواسطه . و گویند عشق مأخوذ است از عشقه، و آن گیاهی است که بر تنه ٔ هر درختی که پیچد آن را خشک سازد و خود به طراوت خویش باقی ماند، پس عشق بر هر تنی که برآید جز محبوب را خشک کند و محو گرداند و آن تن را ضعیف سازد و دل و روح را منور گرداند. و گویند در مقام عشق گاه باشد که عاشق از خود بیخود و بیخبر شود بنحوی که معشوق را در حال حضور نشناسد و جویای او باشد همچنانکه از مجنون لیلی حکایت کنند که روزی لیلی از جانب مجنون میگذشت، خواست با مجنون صحبت کند، او را بخواند، مجنون چندان در فکر و یاد لیلی فرورفته بود که او را نشناخت و گفت عذر من بپذیر و دست از من بازدار که یادلیلی مرا از ذکر و اندیشه ٔ هر موجودی فارغ و به یادخویش مشغول داشته و مرا سخن گفتن با غیر نیست . و این مرتبه پایان مقامات وصول و قرب باشد. و در این مقام است که معروف و عارف متحد شوند و دوئی از میانه برخیزد و عاشق و معشوق یکی گردند، و جز عشق هیچ باقی نماند. پس عشق ذاتیست صِرف و خالص که تحت اسم و رسمی و لغت و وصفی داخل نشود. و در آغاز پیدایش عاشق را به وادی فنای محض کشاند بنحوی که نام و نشان و وصفی از او باقی نگذارد و ذات او را محو کند و در پایان امر نه عاشقی و نه معشوقی در کار باشد، و آنجاست که عشق به هر دو صورت جلوه گر گردد و به هر دو وصف متصف شود، زمانی بصورت عاشق و زمانی بصورت معشوق درآید. و مراتب آن را پنج درجه نوشته اند: اول، فقدان دل که «من لیس بمفقود القلب لیس بعاشق ». دوم تأسف، عاشق درین مقام بی معشوق خویش هر دم از حیات متأسف بود. سوم وجد. چهارم بی صبری، چنانکه گویند:<br>الصبر عندک مذموم عواقبه <br>و الصبر فی سائر الاشیاء محمود.<br>پنجم صبابت، عاشق درین مقام مدهوش بود و از غلبه ٔ عشق بیهوش .<br>و عشق را جمعیت کمالات نیز گفته اند، و این جز حق را نبود. و آن را ذات احدیت نیز ذکر کرده اند. و عاشق آن را گویند که اثر عقل در او نباشد و خبر از سر و پا ندارد و خواب خود بر خود حرام گرداند، زبان به ذکر و دل بفکر و جان به مشاهده ٔ او مشغول دارد. (از کشاف اصطلاحات الفنون ). عشق چون به کمال خود رسد قوا را ساقط گرداند و حواس را از کار بیندازد و طبع را از غذا بازدارد و میان محب و خلق ملال افکند و از صحبت غیر دوست ملول شود یا بیمار گردد و یا دیوانه شود و یا هلاک گردد. و گویند عشق آتشی است که در قلب واقع شود و محبوب را بسوزد، عشق دریای بلا است و جنون الهی است و قیام قلب است با معشوق بلاواسطه . عشق مهمترین رکن طریقت است که آخرین مرتبت آن عشق پاک است و این مقام را تنها انسان کامل که مراتب ترقی و تکامل را پیموده است درک می کند. و شکی نیست که محبت و عشق و علاقه پایه و اساس زندگی و بقاء موجودیت عالم است زیرا تمام حرکات و سکنات و جوش و خروش جهانیان بر اساس محبت و علاقه و عشق است و بس .و عرفا گویند حتی وجود افلاک و حرکات آنها بواسطه ٔ عشق و محبت است . و گویند سلطان عشق خواست که خیمه به صحرا زند، درِ خزائن بگشود گنج بر عالم پاشید، ورنه عالم با بود و نابود خود آرمیده بود و در خلوتخانه ٔ شهود آسوده، «کان اﷲ و لم یکن معه شی ٔ». (از فرهنگ مصطلحات عرفاء از لمعات و طرائق و کشاف و شرح تعرف و مقدمه ٔ نفحات الانس و محبت نامه ).<br> <BR><font color=\"Blue\">◄</font> (اصطلاح فلسفه ) مسأله ٔ عشق یکی از مسائلی است که در فلسفه ٔ افلاطون و افلاطونیان اخیر و فلسفه ٔ اشراقی ایران و فلسفه ٔ باطنیه مورد توجه و بحث قرار گرفته است . بعضی عشق را رذیلت و بعضی فضیلت میدانند. اخوان الصفا و صدرالدین شیرازی گویند: عشق به معنی عام خود ساری در تمام موجودات و ذرات عالم بوده و هیچ موجودی در عالم وجود نیست مگر آنکه به حکم عشق فطری ساری در موجودات در جریان و حرکت است، و آن را به سه قسمت تقسیم کرده اند: عشق اصغر، عشق اوسط وعشق اکبر. و نیز از جهت دیگر آن را به عفیف و عقلی و وضیع تقسیم کرده اند. و از دیدگاه دیگر به حقیقی و مجازی تقسیم شده است (رجوع به هر یک از این ترکیبات شود). اما فلاسفه در مورد عشق به زیبارویان اختلاف کرده اند که آیا این نوع عشق ممدوح است یا مذموم . بعضی آن را مذمت کرده اند و بعضی خوب دانسته اند، و بعضی از رذایل دانند و بعضی از فضایل شمرند، بعضی گویند مرض نفسانی است و بعضی گویند جنون الهی است . صدرالدین و اخوان الصفا را عقیده بر آن است که این نوع عشق که نتیجه ٔ آن التذاذ به صورتهای زیبا است و محبت مفرط به زیبارویان است که در نفوس اکثر ملت ها و امم موجود است . نیز از قراردادهای الهیه است که تابع مصالح و حکم خاصی است و از این جهت مستحسن و ممدوح است و اینگونه عشق ها اکثر منشاء صنایع ظریفه است . عشق به زیبارویان منشاء نکاح و زواج و بقای نوع است . عشق به صبیان و غلمان که در میان بزرگان علم و حکمت است جهت تعلیم و تأدیب و آموختن علم و صنعت است و عنایت حق تعالی ایجاب میکند که این نوع عشقها باشد تا معلم به متعلم خود توجه کند، و محبت و علاقه میان افراد عامل مهم است که آنها را بیکدیگر پیوند داده و نظام خاص اجتماعی و تعاونی را مستقر میدارد و هیچ نوع عشقی اعم از عشق اناث به ذکور و ذکور به اناث و ذکور به ذکور بیهوده نیست و تمام عشقها از امور ممدوحه اند و برای مصالح خاص میباشند. معشوقات نیز برحسب توجه و نظر اشخاص متفاوت و متکثرند از این قرار:<br><span class=\"hlight\" dir=\"rtl\">١</span>- محبت نفوس حیوانیه به نکاح . <span class=\"hlight\" dir=\"rtl\">٢</span>- محبت رؤساء برای ریاسات و حفظ آن . <span class=\"hlight\" dir=\"rtl\">٣</span>- محبت و عشق تجار برای جمعآوری ثروت و مال . <span class=\"hlight\" dir=\"rtl\">٤</span>- محبت علماء و حکما در اندوختن علوم و معارف و احکام و مسائل علمی . <span class=\"hlight\" dir=\"rtl\">٥</span>- محبت و عشق اهل صنعت بر اظهار صنع خود و به وجود آوردن مصنوعات خوب .<br>عشق مجرد از شوق مخصوص عقول مجرده است که از هر جهت بالفعلند و درموجوداتی که از جهتی بالفعل و از جهتی دیگر بالقوه اند عشق و شوق غریزی هر دو موجود است و بالاخره عشق ساری در تمام موجودات است، «کل واحد من البسائط الغیرالحیة قرین عشق غریزی لایتخلی عنه البتة». «فی بیان طریق آخر فی سریان معنی العشق فی کل الاشیاء». تمام ارتباطات صور و اتصالات ترکیبات و تألیفات موجودات از عشق و شوق خاصی است که آنها را به طرف کمال میکشاند وهمان عشق و شوق است که مبداء حرکات و تحولات آنها است . و ذات حق خود عاشق ذات خود است و معشوق ذات خود است و عشق کل و منبع تمام عشقها است که از او عشق به تمام موجودات افاضه میشود و در تمام کائنات سریان یابد. (از فرهنگ علوم عقلی از اخوان الصفا و رسائل فلسفیه ٔ رازی ). از حد درگذشتن دوستی . شیفتگی . شیفتن . مهربانی . دلشدگی . دوستگانی . هوی . دل دوستی . کام . کامه . بیدلی . شعف . شغف . غرام . شیدائی . خاطرخواهی . خواهانی . صبابة.<br>شواهد ذیل راجع به عشق است در همه ٔ معانی <span class=\"hlight\">:</span> <br>عشق او عنکبوت را ماند<br>بتنیده ست تفنه گرد دلم .<br> <font color=\"Red\">شهید.</font><br>ای آنکه من از عشق تو اندر جگر خویش <br>آتشکده دارم صد و بر هر مژه ای ژی .<br> <font color=\"Red\">رودکی .</font><br>روی مرا هجر کرد زردتر از زر<br>گردن من عشق کرد نرمتر ازدخ .<br> <font color=\"Red\">شاکر بخاری .</font><br>چه مایه زاهد پرهیزکار صومعگی <br>که نسک خوان شد از عشقش و ایارده گوی .<br> <font color=\"Red\">خسروانی .</font><br>یا رب مرا به عشق شکیبا کن <br>یا عاشقی به مرد شکیبا ده .<br> <font color=\"Red\">اورمزدی .</font><br>پدید آید آنگاه باریک و زرد<br>چو پشت کسی کو غم عشق خورد.<br> <font color=\"Red\">فردوسی .</font><br>دل زال یکباره دیوانه گشت <br>خرد دور شد عشق فرزانه گشت .<br><font color=\"Red\">فردوسی .</font><br>بخندد بگوید که ای شوخ چشم <br>ز عشق توگویم نه از درد و خشم .<br> <font color=\"Red\">فردوسی .</font><br>نباید که برخیره از عشق زال <br>نهال سرافکنده گردد همال .<br> <font color=\"Red\">فردوسی .</font><br>عشق خوش است ار مساعدت بود از یار<br>یار مساعد نه اندک است نه بسیار.<br> <font color=\"Red\">فرخی .</font><br>وای آنکو بدام عشق آویخت <br>خنک آنکو ز دام عشق رهاست <br>عشق برمن در عنا بگشاد<br>عشق سرتابسر عذاب و عناست .<br> <font color=\"Red\">فرخی .</font><br>به دلْشان نماند از غم عشق تیو<br>به یک ره زهر دو برآمد غریو.<br> <font color=\"Red\">عنصری .</font><br>حکیمان زمانه راست گفتند<br>که جاهل گردد اندر عشق عاقل .<br><font color=\"Red\">منوچهری .</font><br>چنان کز سال و مه تنین شود مار<br>شود عشق از ملامت صعب و دشوار.<br> <font color=\"Red\">(ویس و رامین ).</font><br>نبرّد عشق راجز عشق دیگر<br>چرا یاری نگیری زو نکوتر.<br> <font color=\"Red\">(ویس و رامین ).</font><br>عشق محالست و نباشد هگرز<br>خاطر پرنورمحل محال .<br> <font color=\"Red\">ناصرخسرو.</font><br>ای عشق به خویشتن بلا خواسته ام <br>آنگه که به آرزو تو را خواسته ام .<br> <font color=\"Red\">ابوالفرج رونی .</font><br>بیخودان را ز عشق فایده ایست <br>عشق و مقصود خویش بیهده ایست <br>نیست در عشق خط خود موجود<br>عاشقان را چه کار با مقصود<br>عشق و مقصود کافری باشد<br>عاشق از کام خود بری باشد.<br> <font color=\"Red\">سنائی .</font><br>پشت بنفشه از غم پیری بخم بماند<br>گوئی که عشق و مفلسی او را بهم گرفت .<br> <font color=\"Red\">ادیب صابر.</font><br>تو خورشیدی و خورشیدی جوانی <br>ز عشقت بر سر دیوار دارم .<br> <font color=\"Red\">عمادی .</font><br>عشق مهمان دل است و جان و دل مهمان تو<br>من دل و جان پیش مهمان درکشم هر صبحدم .<br> <font color=\"Red\">خاقانی .</font><br>صورت عین شین قاف در سر یعنی که عشق <br>نقش الف لام میم در دل یعنی الم .<br> <font color=\"Red\">خاقانی .</font><br>دولت عشق تو آمد عالم جان تازه کرد<br>عقل کافر بود آن رخ دید و ایمان تازه کرد.<br> <font color=\"Red\">خاقانی .</font><br>عشق خوبان و سینه ٔ اوباش !<br>نور خورشید و دیده ٔ خفاش !<br> <font color=\"Red\">ظهیر فاریابی .</font><br>در لغت عشق سخن جان ماست <br>ما سخنیم این طلل ایوان ماست .<br> <font color=\"Red\">نظامی .</font><br>عشق مغز کاینات آمد مدام <br>لیک نبود عشق بی دردی تمام (کذا)<br>قدسیان را عشق هست و درد نیست <br>درد را جز آدمی درخورد نیست .<br> <font color=\"Red\">عطار.</font><br>مرد را بی عشق کاری چون بود<br>این چنین خر بی فساری چون بود.<br> <font color=\"Red\">عطار.</font><br>تو به یک خاری گریزانی ز عشق <br>تو بجز نامی چه میدانی ز عشق <br>عشق را صد ناز و استکبار هست <br>عشق با صد ناز می آید به دست <br>عشق چون وافی است وافی میخرد<br>در حریف بیوفا می ننگرد.<br> <font color=\"Red\">مولوی .</font><br>عشق گر زیبا بود معشوق گو زیبا مباش <br>عشق را با صورت زیبا و نازیبا چه کار<br>تا نپنداری که سلمان را نظر بر شاهد است <br>مست جام عشق را با شاهدرعنا چه کار.<br> <font color=\"Red\">شیخ فخرالدین عراقی (از آنندراج ).</font><br>سعدیا عشق نیامیزد و شهوت با هم <br>پیش تسبیح ملایک نرود دیو رجیم .<br> <font color=\"Red\">سعدی .</font><br>چه نغز آمد این نکته در سندباد<br>که عشق آتش است و هوس تندباد.<br> <font color=\"Red\">سعدی .</font><br>ما را نظربه خیر است از عشق خوبرویان <br>آنکو به شر کند میل او خود بشر نباشد.<br> <font color=\"Red\">سعدی .</font><br>عذرم پذیر و جرم بذیل کرم بپوش <br>عشق است و مفلسی و جوانی و نوبهار.<br> <font color=\"Red\">حافظ.</font><br>لطیفه ای است نهانی که عشق ازو خیزد<br>که نام آن نه لب لعل و خط زنگاریست .<br> <font color=\"Red\">حافظ (از آنندراج ).</font><br>عشق که رقص فلک از نور اوست <br>خوان سخن را نمک از شور اوست .<br> <font color=\"Red\">جامی .</font><br>عشقت بمیان جان نهادم <br>مهر همه بر کران نشاندم .<br> <font color=\"Red\">صائب (از آنندراج ).</font><br>میرساند چو ضعیفان تهیدست ز دور<br>ماه نو عشق بلندی خم ابروی تو را.<br> <font color=\"Red\">سالک یزدی (از آنندراج ).</font><br>ناتوانی عاقبت دلدار ما خواهد شدن <br>دوستان عشقی که غم غمخوار ما خواهد شدن .<br> <font color=\"Red\">عبداﷲ سلطان (از آنندراج ).</font><br>عشق خسرو کرد شکّر را به شیرینی مثل <br>ورنه شکّرنام بسیارستی اندر اصفهان .<br> <font color=\"Red\">قاآنی .</font><br>جنس شما آدمیان کم بقاست <br>عشق بود باقی و باقی فناست .<br> <font color=\"Red\">ایرج میرزا.</font><br>استهاءة؛ نیکو نمودن عشق را بر کسی . جَوی ̍؛ اندوه عشق . شَعَف ؛ عشق که دل برد. عَلَق ؛ عشق و محبت دائمی . غاش ؛ عاشقی که عشق او بدرجه ٔ کمال رسیده باشد. هُوام ؛ نوعی از جنون و عشق . هَوی ̍؛ عشق، در خیر باشد یا در شر: هوی لاعج ؛ عشق سوزان و مولم . (از منتهی الارب ).<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عشق است و هزار بدگمانی </span> .<br> <span class=\"hlight\">عشق بر مرده نباشد پایدار</span> .<br> <span class=\"hlight\">عشق پیری گر بجنبد سر به رسوائی زند</span> .<br> <span class=\"hlight\">عشق را بنیاد بر ناکامی است </span> .<br> <span class=\"hlight\">عشق و رشک جدا نمی شود</span> .<br> <span class=\"hlight\">عشق و مشک پنهان نمی ماند</span> .<br> <span class=\"hlight\">عشق و جنون همسایه ٔ دیوار به دیوارند</span> .<br> <span class=\"hlight\">گر عشق حرم باشد سهل است بیابانها</span> .<br> <span class=\"hlight\">به عشق شیطان در چاه چهل ذرعی افعی گرفتن </span>، به عشق عمر یا معاویه از چاه چهل گزی مار گرفتن ؛ به دلخواه ناکسی بی مزدی، یا بامزدی ناچیز کاری دشوار و خطیر انجام دادن . (امثال و حکم دهخدا).<br> <span class=\"hlight\">عشقهایی کز پی رنگی بود</span> <br>عشق نبودعاقبت ننگی بود.<br> <font color=\"Red\">مولوی .</font><br> <span class=\"hlight\">ای بی خبر از سوخته و سوختنی </span> <br>عشق آمدنی بود نه آموختنی .<br> <font color=\"Red\">سنائی .</font><br>نظیر: لیس فی الحب مشورة؛ و کاکای امیر اعظم است عاشق است بهر کس که شما صلاح بدانید.<br>گرچه تفسیر زبان روشنگر است <br>لیک عشق بیزبان روشن تر است .<br> <font color=\"Red\">مولوی .</font><br>شرع را دست عقل کی سنجد<br>عشق در ظرف حرف کی گنجد.<br> <font color=\"Red\">سنائی .</font><br>بایدم دایم به راه او سِتاد<br>عشق شاگرد است و حسنش اوستاد.<br> <font color=\"Red\">عطار.</font><br>عشق و پس التفات زی دگران !<br>سوی غیری به غافلی نگران !<br> <font color=\"Red\">سنائی .</font><br>هنوز اول عشق است اضطراب مکن <br>تو هم به مطلب خود میرسی شتاب مکن .<br> <font color=\"Red\">؟</font><br>مصراع ثانی را به مزاح به دخترانی که از جهاز یا شوهر رفتن عروسی حکایت کنند، گویند. (امثال و حکم دهخدا).<br>- <span class=\"hlight\">عشق است </span> ؛ در اصطلاح عامیانه، خوشیم . شادیم . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">فلان را عشق است </span> ؛ در اصطلاح متصوفه، مورد کمال توجه است و شایان احترام است، مثلاً گویند: جمال مولی را عشق است . (از فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عشقم نیست </span> ؛ در اصطلاح عامیانه، دلم نمیخواهد. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عشق کسی دبه کردن </span> ؛ دگرباره خواهانی کردن . خواهش مجدد و طمع زیادت کردن وی . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عشق کسی کشیدن </span> ؛ در اصطلاح عامیانه، دلش خواستن . (فرهنگ فارسی معین ). تمایل پیدا کردن . میل کردن . (از فرهنگ عوام ).<br><BR><font color=\"Blue\">◄</font> در مصطلحات به معنی سلام و وداع آمده است، چه اصطلاح آزادان است که بجای سلام، علیک عشق اﷲ گویند. (از غیاث اللغات ). رجوع به عشق زدن و عشق گفتن شود. <BR><font color=\"Blue\">◄</font> معشوق . (فرهنگ فارسی معین ).<br></font></div>'),
(183622, 'عشق', '<span class=\"hlight\">عشق .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ُ ]</font></b> (ع اِ) نیکو و برابر کنندگان در نشاندن درختهای ریاحین را. (منتهی الارب ). اصلاح کنندگان و صاف کنندگان غرسهای ریاحین، مفرد آن عَشیق یا عَشوق است . (از اقرب الموارد).<br></font></div>'),
(183623, 'عشق آباد', '<span class=\"hlight\">عشق آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) دهی از دهستان کاکاوند بخش دلفان شهرستان خرم آباد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن . آب آن از چشمه . محصول آن غلات و لبنیات و پشم است . ساکنان این ده از طایفه ٔ غیب غلام چادرنشین هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(183624, 'عشق آباد', '<span class=\"hlight\">عشق آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) دهی از دهستان میان ولایت بخش حومه ٔ شهرستان مشهد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٢٤</span> تن . آب آن از قنات . محصول آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183625, 'عشق آباد', '<span class=\"hlight\">عشق آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) یکی از دهستانهای بخش فدیشه ٔ شهرستان نیشابور. آب مزروعی آن از قنوات تأمین میشود. ساکنان آن از طوایف عرب، قاضی، طاقارشکم، غضنفری میباشند. این دهستان از <span class=\"hlight\" dir=\"rtl\">٦٩</span> آبادی بزرگ و کوچک تشکیل میگردد و مجموع نفوس آن در حدود <span class=\"hlight\" dir=\"rtl\">١٦٣٩٤</span> تن است . قرای مهم آن اردمه و احمدآباد است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183626, 'عشق آباد', '<span class=\"hlight\">عشق آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) دهی مرکز بخش دهستان عشق آباد بخش فدیشه ٔ شهرستان نیشابور. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٤٦٣</span> تن . آب آن از قنات . محصول آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183627, 'عشق آباد', '<span class=\"hlight\">عشق آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) دهی از دهستان ریوند بخش حومه ٔ شهرستان نیشابور. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢٢٨</span> تن . آب آن از قنات . محصول آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183628, 'عشق آباد', '<span class=\"hlight\">عشق آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) دهی از دهستان مرکزی بخش فریمان شهرستان مشهد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٩٨٦</span> تن . آب آن از قنات . محصول آن غلات و میوه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183629, 'عشق آباد', '<span class=\"hlight\">عشق آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) شهری است در اتحاد جماهیر شوروی (سابق ) واقع در نزدیکی مرز ایران و شوروی، در کنار راه آهن، کرسی ترکمنستان . این شهر یکصدوهفتادهزار تن سکنه دارد و دارای دانشگاه است و تولیدات آن صنایع نساجی از قبیل پنبه و ابریشم و نیز مواد غذائی است . عشق آباد در قدیم جزو خراسان بوده است . (از فرهنگ فارسی معین ).<br></font></div>'),
(183630, 'عشق آباد', '<span class=\"hlight\">عشق آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) دهی از دهستان سرولایت بخش سرولایت شهرستان نیشابور. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢١٤</span> تن . آب آن از قنات . محصول آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>)<span class=\"hlight\" dir=\"rtl\">٠</span><br></font></div>'),
(183631, 'عشق آباد', '<span class=\"hlight\">عشق آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) دهی جزء دهستان غار بخش ری شهرستان تهران . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٤١</span> تن . آب آن از قنات . محصول آن غلات و صیفی و چغندرقند است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(183632, 'عشق آباد', '<span class=\"hlight\">عشق آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) دهی از دهستان اهلمرستاق بخش مرکزی شهرستان آمل . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٧٠</span> تن . آب آن از چشمه ٔ محلی و رود هراز. محصول آن برنج و کنف ومختصری غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(183633, 'عشق آباد خدابخش', '<span class=\"hlight\">عشق آباد خدابخش .</span> <font color=\"DarkGreen\"><b>[ ع ِ دِ خ ُ ب َ ]</font></b> (اِخ ) دهی از دهستان دستگردان بخش طبس شهرستان فردوس . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢٣١</span> تن . آب آن از قنات . محصول آن غلات وپنبه و ذرت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183634, 'عشق آباد کهنه', '<span class=\"hlight\">عشق آباد کهنه .</span> <font color=\"DarkGreen\"><b>[ ع ِدِ ک ُ ن ِ ]</font></b> (اِخ ) دهی از دهستان درب قاضی بخش حومه ٔ شهرستان نیشابور. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٠٦</span> تن . آب آن از قنات . محصول آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183635, 'عشق آرنده', '<span class=\"hlight\">عشق آرنده .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف مرکب ) عاشق، عِشّیق ؛ بسیار عشق آرنده . (منتهی الارب ).<br></font></div>'),
(183636, 'عشق آفرین', '<span class=\"hlight\">عشق آفرین .</span> <font color=\"DarkGreen\"><b>[ ع ِ ف َ ]</font></b> (نف مرکب ) عشق آفریننده . آنکه با زیبائی خود در کسان تولید عشق کند. (فرهنگ فارسی معین ).<br></font></div>'),
(183637, 'عشق آمیز', '<span class=\"hlight\">عشق آمیز.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ن مف ) آمیخته به عشق <span class=\"hlight\">:</span> در اثنای رقعه کلمات دلاویز و سخنان عشق آمیز درج کرد. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">١٠٣</span>).<br></font></div>'),
(183638, 'عشق آوردن', '<span class=\"hlight\">عشق آوردن .</span> <font color=\"DarkGreen\"><b>[ ع ِ وَ دَ ]</font></b> (مص مرکب ) عاشق شدن . عشق ورزیدن . عاشقی کردن . شیفته شدن <span class=\"hlight\">:</span> به این خوبی که آفتابست نشنیده ایم که کسی او را دوست گرفته باشد و عشق آورده . (گلستان سعدی ).<br>هرکه می با تو خوردعربده کرد<br>هرکه روی تو دید عشق آورد.<br> <font color=\"Red\">سعدی .</font><br>قضاء لازمست آن را که بر خورشید عشق آرد<br>که همچون ذره در مهرش گرفتار هوا ماند.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(183639, 'عشق اصغر', '<span class=\"hlight\">عشق اصغر.</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ اَ غ َ ]</font></b> (ترکیب وصفی، اِ مرکب ) (اصطلاح فلسفه ) عشق ظاهری . (از فرهنگ علوم عقلی ).<br></font></div>'),
(183640, 'عشق افلاطونی', '<span class=\"hlight\">عشق افلاطونی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ اَ ]</font></b> (ترکیب وصفی، اِ مرکب ) (اصطلاح فلسفه ) اشاره به عقیده ٔ افلاطون است که گوید: روح انسان در عالم مجردات قبل از ورود به دنیا، حقیقت زیبایی و حسن مطلق یعنی خیر را بدون پرده و حجاب دیده است . پس در این دنیا چون حسن ظاهری و نسبی و مجازی را می بیند از آن زیبایی مطلق که سابقاً درک نموده یاد میکند، غم هجران به او دست میدهد و هوای عشق او را برمیدارد، فریفته ٔ جهان میشود و مانند مرغی که در قفس است میخواهد بسوی او پرواز کند. عواطف و عوالم محبت همه همان شوق لقای حق است، اما عشق جسمانی مانند حسن صوری مجازی است و عشق حقیقی سودائی است که به سر حکیم میزند، و همچنانکه عشق مجازی سبب خروج جسم از عقیمی و مولد فرزند و مایه ٔ بقای نوع است، عشق حقیقی هم روح و عقل را از عقیمی رهایی داده مایه ٔ ادراک اشراقی و دریافتن زندگی جاودانی یعنی نیل به معرفت جمال حقیقت و خیر مطلق و حیات روحانی است و انسان به کمال علم وقتی میرسد که به حق واصل و به مشاهده ٔجمال او نائل شود و اتحاد عالم و معلوم و عاقل و معقول حاصل گردد. (فرهنگ فارسی معین از سیر حکمت در اروپا). و رجوع به عشق و عشق حقیقی و عشق مجازی شود.<br></font></div>'),
(183641, 'عشق انگیز', '<span class=\"hlight\">عشق انگیز.</span> <font color=\"DarkGreen\"><b>[ ع ِ اَ ]</font></b> (نف مرکب ) عشق انگیزنده . برانگیزنده ٔ عشق و شیفتگی <span class=\"hlight\">:</span> <br>شقایقهای عشق انگیز پیشاپیش طاووسان <br>بسان قطره های قیر باریده براخگرها.<br><font color=\"Red\">منوچهری .</font><br></font></div>'),
(183642, 'عشق اوسط', '<span class=\"hlight\">عشق اوسط.</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ اَ <span class=\"hlight\" dir=\"rtl\">/</span> اُو س َ ]</font></b> (ترکیب وصفی، اِ مرکب ) (اصطلاح فلسفه ) عشق حکماء و علماء است به تفکر و تعمق در صنع خدای متعال و حقایق موجودات . (از فرهنگ علوم عقلی ).<br></font></div>'),
(183643, 'عشق اکبر', '<span class=\"hlight\">عشق اکبر.</span> <font color=\"DarkGreen\"><b>[ع ِ ق ِ اَ ب َ ]</font></b> (ترکیب وصفی، اِ مرکب ) (اصطلاح فلسفه )اشتیاق به لقای حق تعالی و معرفت ذات و شهود صفات درذات است . فلاسفه و ظرفا گویند اگر عشق عالی و اکبر نمی بود موجودات طراً مضمحل میشدند و آنچه حافظ ممکنات و معلولات نازله است عشق عالی است که ساری در تمام ممکنات و موجودات جهان هستی میباشد زیرا تمام موجودات عالم طالب و عاشق کمالند و غایت این مرتبه از عشق تشبه به ذات خدای متعال است . (از فرهنگ علوم عقلی ).<br></font></div>'),
(183644, 'عشق باخت', '<span class=\"hlight\">عشق باخت .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (مص مرکب مرخم، اِمص مرکب ) عشق باختن . (فرهنگ فارسی معین ). رجوع به عشق شود <span class=\"hlight\">:</span> <br>آفتی نبود بتر از ناشناخت <br>تو برِ یار و ندانی عشق باخت .<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(183645, 'عشق باختن', '<span class=\"hlight\">عشق باختن .</span> <font color=\"DarkGreen\"><b>[ ع ِ ت َ ]</font></b> (مص مرکب ) اظهار عشق ودوستی شدید کردن . عشقبازی کردن . عشق ورزیدن . (فرهنگ فارسی معین ). تغازل با یکدیگر. مغازله <span class=\"hlight\">:</span> <br>سعدی همه روزه عشق میباز<br>تا در دو جهان شوی به یک رنگ .<br> <font color=\"Red\">سعدی .</font><br>کسی بعیب من از خویشتن نپردازد<br>که هرکه مینگرم با تو عشق میبازد.<br> <font color=\"Red\">سعدی .</font><br>عشقبازی چیست سر در پای جانان باختن <br>با سر اندر کوی دلبر عشق نتوان باختن .<br> <font color=\"Red\">سعدی .</font><br>نیست آسان عشق با خوبان نوخط باختن <br>تخته ٔ مشق عتاب و ناز می باید شدن .<br><font color=\"Red\">صائب (از آنندراج ).</font><br></font></div>'),
(183646, 'عشق باره', '<span class=\"hlight\">عشق باره .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b>(ص مرکب ) کسی که عشق را دوست دارد. عاشق پیشه . (فرهنگ فارسی معین ). عشق پرداز. (از آنندراج ) <span class=\"hlight\">:</span> <br>دلی که عشق نبازد ز سنگ خاره بود<br>چه دولتی بود آن دل که عشقباره بود.<br><font color=\"Red\">شرف شفروه (از آنندراج ).</font><br></font></div>'),
(183647, 'عشق بازی', '<span class=\"hlight\">عشق بازی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (حامص مرکب ) عمل عشقباز. عاشقی . غَزَل . (منتهی الارب ). عشق ورزی . معاشقه . مغازله . تصابی . مهرورزی <span class=\"hlight\">:</span> <br>عشقبازی کن و سیکی خور و برخند بر آن <br>که تو را گوید سیکی مخور و عشق مباز.<br> <font color=\"Red\">فرخی .</font><br>دل دوش هزار چاره سازی میکرد<br>با وعده ٔ دوست عشق بازی میکرد.<br> <font color=\"Red\">عسجدی .</font><br>تا ز حسن عهد تو آوازه شد در شرق و غرب <br>آسمان با عشقبازی عهد وپیمان تازه کرد.<br> <font color=\"Red\">خاقانی .</font><br>گفتا زبرای عشقبازی <br>ببْریدستند موی بهمان .<br> <font color=\"Red\">خاقانی .</font><br>چو مجنون سر مکش در عشقبازی <br>چو لیلی پاک شو در چاره سازی .<br> <font color=\"Red\">نظامی .</font><br>چنین فصلی بدین عاشق نوازی <br>خطا باشد خطا، بی عشقبازی .<br> <font color=\"Red\">نظامی .</font><br>جهان عشق است و دیگر زرق سازی <br>همه بازیست الاّ عشقبازی .<br> <font color=\"Red\">نظامی .</font><br>هین مکش هر مشتری را تو به دست <br>عشقبازی با دو معشوقه بد است .<br> <font color=\"Red\">مولوی .</font><br>هر کسی را نتوان گفت که صاحب نظراست <br>عشقبازی دگر ونفس پرستی دگر است .<br> <font color=\"Red\">سعدی .</font><br>عشقبازی چیست سردر پای جانان باختن <br>با سر اندر کوی دلبر عشق نتوان باختن .<br> <font color=\"Red\">سعدی .</font><br>که سعدی راه و رسم عشقبازی <br>چنان داند که در بغداد تازی .<br> <font color=\"Red\">سعدی .</font><br>اگرچه حسن تو از عشق غیر مستغنی است <br>من آن نیَم که ازاین عشقبازی آیم باز.<br> <font color=\"Red\">حافظ.</font><br>گه چون نسیم با گل راز نهفته گفتن <br>گه سرّ عشقبازی از بلبلان شنیدن .<br> <font color=\"Red\">حافظ.</font><br>در طریق عشقبازی امن و آسایش بلاست <br>ریش باد آن دل که با درد تو خواهد مرهمی .<br> <font color=\"Red\">حافظ.</font><br>تغنّی، تغنیة؛ عشقبازی کردن با زنان . دعفشة؛ عشقبازی کردن . مهانغة؛ عشقبازی کردن با زن . (منتهی الارب ).<br></font></div>'),
(183648, 'عشق جسمانی', '<span class=\"hlight\">عشق جسمانی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ ج ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) عشقی که مبنای آن بر شهوت باشد. در مقابل عشق معنوی و عشق روحانی . (فرهنگ فارسی معین ).<br></font></div>'),
(183649, 'عشق حقیقی', '<span class=\"hlight\">عشق حقیقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ ح َ ]</font></b> (ترکیب وصفی، اِ مرکب ) در اصطلاح فلاسفه و متصوفه، محبة اﷲ و صفات و افعال اوست . (از فرهنگ علوم عقلی ). الفت رحمانی و الهام شوقی است و ذات حق که واجد تمام کمالات است و عاقل و معقول بالذات است عاشق و معشوق است . و بالجمله عشق حقیقی عشق به لقاء محبوب حقیقی است که ذات احدیت باشد. (از فرهنگ مصطلحات عرفاء). و رجوع به عشق و عشق افلاطونی شود.<br></font></div>'),
(183650, 'عشق خدا', '<span class=\"hlight\">عشق خدا.</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ خ ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) در اصطلاح فلاسفه ومتصوفه، عشق به حق تعالی است . (فرهنگ فارسی معین ).<br></font></div>'),
(183651, 'عشق داشتن', '<span class=\"hlight\">عشق داشتن .</span> <font color=\"DarkGreen\"><b>[ ع ِ ت َ ]</font></b> (مص مرکب ) مشتاق بودن . بسیار دوست داشتن . عاشق بودن . صورت خوب و خوشگل دوست داشتن . (ناظم الاطباء). عشق ورزیدن .بسیار دوست داشتن . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>بنال سعدی اگر عشق دوستان داری <br>که هیچ بلبل ازین ناله در قفس نکند.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(183652, 'عشق رسانیدن', '<span class=\"hlight\">عشق رسانیدن .</span> <font color=\"DarkGreen\"><b>[ ع ِ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ دَ ]</font></b> (مص مرکب ) سلام رسانیدن . (ناظم الاطباء). رجوع به عشق و عشق زدن و عشق گفتن شود.<br></font></div>'),
(183653, 'عشق روحانی', '<span class=\"hlight\">عشق روحانی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) عشقی که هدف آن لذت روحی باشد. عشق معنوی . مقابل عشق جسمانی . (فرهنگ فارسی معین ).<br></font></div>'),
(183654, 'عشق زدن', '<span class=\"hlight\">عشق زدن .</span> <font color=\"DarkGreen\"><b>[ ع ِ زَ دَ ]</font></b> (مص مرکب ) در اصطلاح رنود، به منزله ٔ سلام گفتن بود که گاه بمعنی مشهور آید که فعل شرعی است و گاه بجای الوداع استعمال کنند. (آنندراج ).عشق گفتن . رجوع به عشق و عشق گفتن شود <span class=\"hlight\">:</span> <br>عشق زد شمع که ای سوختگان خوش باشید<br>شعله هم آب بقائی است که من می دانم .<br><font color=\"Red\">میرزا عبدالقادر بیدل (از آنندراج ).</font><br></font></div>'),
(183655, 'عشق سنجی', '<span class=\"hlight\">عشق سنجی .</span> <font color=\"DarkGreen\"><b>[ ع ِ س َ ]</font></b> (حامص مرکب ) سنجش و قیاس شیفتگی و دلدادگی <span class=\"hlight\">:</span> <br>مرا در عشق سنجی با برهمن <br>سزد زین غم اگر زنار بندم .<br><font color=\"Red\">صائب (ازآنندراج ).</font><br></font></div>'),
(183656, 'عشق ظاهری', '<span class=\"hlight\">عشق ظاهری .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ هَِ ]</font></b> (ترکیب وصفی، اِ مرکب ) همان عشق مجازی است . (از فرهنگ فارسی معین ). رجوع به عشق مجازی شود.<br></font></div>'),
(183657, 'عشق عفیف', '<span class=\"hlight\">عشق عفیف .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ ع َ ]</font></b> (ترکیب وصفی، اِمرکب ) (اصطلاح فلسفه ) عشقی است که سرچشمه ٔ آن حس زیبایی مطلق باشد مِن حیث الذات، و آن اعلی درجه ٔ عشق انسان است . در مقابل عشق وضیع. (از فرهنگ علوم عقلی ).<br></font></div>'),
(183658, 'عشق عقلی', '<span class=\"hlight\">عشق عقلی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ ع َ ]</font></b> (ترکیب وصفی، اِ مرکب ) (اصطلاح فلسفه ) عشقی است که مبداء آن توجه به ذات حق تعالی باشد و مخصوص مقربان درگاه اوست . (فرهنگ علوم عقلی ).<br></font></div>'),
(183659, 'عشق مجازی', '<span class=\"hlight\">عشق مجازی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ م َ ]</font></b> (ترکیب وصفی، اِ مرکب ) عشق ظاهری . ابتدای محبت و هوی و بعد علاقه و بعد وجد و عشق است که منشاء آن هوی و حب مجازی است و پس از مرتبت عشق شغف است که سوزاننده ٔ قلب است . (از فرهنگ مصطلحات عرفاء). و آن یا نفسانی است و یا حیوانی . قسم اول مبداء و منشاء مشاکلت نفس عاشق است با معشوق خود در جوهر ذات، و قسم دوم مبداء شهوت حیوانی است . (از فرهنگ علوم عقلی ). عشق غیرحقیقی و موقت و زودگذر. عشق مجازی یا ظاهری مانند عشقی که در موجودات زنده سبب جلب و جذب یکی دیگری را میشود و نتیجه ٔ این جذب و انجذاب بقای نسل و نوع است . (فرهنگ فارسی معین ). و رجوع به عشق و عشق افلاطونی شود.<br></font></div>'),
(183660, 'عشق معنوی', '<span class=\"hlight\">عشق معنوی .</span> <font color=\"DarkGreen\"><b>[ ع ِق ِ م َ ن َ ]</font></b> (ترکیب وصفی، اِ مرکب ) همان عشق روحانی است . (فرهنگ فارسی معین ). رجوع به عشق روحانی شود.<br></font></div>'),
(183661, 'عشق نامه', '<span class=\"hlight\">عشق نامه .</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ مرکب ) نامه ٔ عاشقانه . (فرهنگ فارسی معین ). شیفتگی نامه . محبت نامه <span class=\"hlight\">:</span> <br>بالای هزار عشق نامه <br>آراسته شد به نوک خامه .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(183662, 'عشق نمودن', '<span class=\"hlight\">عشق نمودن .</span> <font color=\"DarkGreen\"><b>[ع ِ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ دَ ]</font></b> (مص مرکب ) عشق ورزیدن . عشق کردن . تعشّق . (تاج المصادر بیهقی ). تغزّل . (تاج المصادر بیهقی ): تعاشق ؛ همدیگر عشق نمودن . (منتهی الارب ).<br></font></div>'),
(183663, 'عشق نوازی', '<span class=\"hlight\">عشق نوازی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ن َ ]</font></b> (حامص مرکب )زمزمه ٔ عاشقی کردن . نوای عاشقی دردادن <span class=\"hlight\">:</span> <br>رموز عشق نوازی  نه کار هرمرغی است <br>بیا و نوگل این بلبل غزلخوان باش .<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(183664, 'عشق ورزی', '<span class=\"hlight\">عشق ورزی .</span> <font color=\"DarkGreen\"><b>[ ع ِ وَ ]</font></b> (حامص مرکب ) عشق ورزیدن . تعشق . تصابی .<br></font></div>'),
(183665, 'عشق ورزیدن', '<span class=\"hlight\">عشق ورزیدن .</span> <font color=\"DarkGreen\"><b>[ ع ِ وَ دَ ]</font></b> (مص مرکب ) عشقبازی کردن . عشق باختن . (فرهنگ فارسی معین ). تعشق . تغازل <span class=\"hlight\">:</span> <br>در خاطر من که عشق ورزد<br>عالم همه حبه ای نیرزد.<br> <font color=\"Red\">نظامی .</font><br>غم دو زلف تو بر لاله حلقه بر حلقه <br>به سنگ خاره درآموخت عشق ورزیدن .<br> <font color=\"Red\">سعدی .</font><br>عافیت میبایدت چشم از نکورویان بدوز<br>عشق میورزی بساط نیکنامی درنورد.<br> <font color=\"Red\">سعدی .</font><br>عشق ورزیدم و عقلم به ملامت برخاست <br>هرکه عاشق شد ازو حکم سلامت برخاست .<br> <font color=\"Red\">سعدی .</font><br>عشق می ورزم و امّید که این فن شریف <br>چون هنرهای دگر مایه ٔ حرمان نشود.<br> <font color=\"Red\">حافظ.</font><br>چنین سبزتلخی ندیده ست کس <br>که با نکهتش عشق ورزد نفس .<br><font color=\"Red\">ظهوری .</font><br></font></div>'),
(183666, 'عشق وضیع', '<span class=\"hlight\">عشق وضیع.</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ وَ ]</font></b> (ترکیب وصفی، اِ مرکب ) (اصطلاح فلسفه ) عشقی حیوانی است . در مقابل عشق عفیف . این عشق از انواع عشق پست حیوانی است که غرض عمده ٔ آن اطفاء شهوات حیوانی است . (فرهنگ علوم عقلی ).<br></font></div>'),
(183667, 'عشق پاک', '<span class=\"hlight\">عشق پاک .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ ]</font></b> (ترکیب وصفی ) عشقی که آلوده به خواهشهای جسمانی نباشد. عشق افلاطونی . (یادداشت مرحوم دهخدا). پاکبازی . رجوع به عشق و عشق افلاطونی و پاکبازی شود.<br></font></div>'),
(183668, 'عشق پرداز', '<span class=\"hlight\">عشق پرداز.</span> <font color=\"DarkGreen\"><b>[ ع ِ پ َ ]</font></b> (نف مرکب ) عاشق پیشه . عشق باره <span class=\"hlight\">:</span> <br>خوشا تغافل رسوای عشق پردازان <br>برای دیدن پنهان بهانه میخواهند.<br><font color=\"Red\">ظهوری (از آنندراج ).</font><br></font></div>'),
(183669, 'عشق پرستی', '<span class=\"hlight\">عشق پرستی .</span> <font color=\"DarkGreen\"><b>[ ع ِ پ َ رَ ]</font></b> (حامص مرکب ) عشقبازی به حد افراط. پرستش عشق . دلدادگی مفرط <span class=\"hlight\">:</span> <br>اول کاین عشق پرستی نبود<br>در عدم آوازه ٔ هستی نبود.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(183670, 'عشق پیچا', '<span class=\"hlight\">عشق پیچا.</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) یاسمن ینگی دنیائی . (ناظم الاطباء).<br></font></div>'),
(183671, 'عشق پیچان', '<span class=\"hlight\">عشق پیچان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) نباتی است که بر درخت پیچد، گل آن سرخ باشد، و در عرف آن را عشق پیچه گویند. (غیاث اللغات ). نباتی است بیاره دار، و در هندوستان بغایت شهرت دارد. (آنندراج ). لبلاب . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>صید نخچیر بیابان تا کند در دام زلف <br>شاخ آهو بر سرش چون عشق پیچان سبز شد.<br><font color=\"Red\">حاذق (از آنندراج ).</font><br></font></div>'),
(183672, 'عشق پیچه', '<span class=\"hlight\">عشق پیچه .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق ِچ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) عشق پیچان که نباتی است . (از غیاث اللغات ). رجوع به عشق پیچان شود.<br></font></div>'),
(183673, 'عشق گفتن', '<span class=\"hlight\">عشق گفتن .</span> <font color=\"DarkGreen\"><b>[ ع ِ گ ُ ت َ ]</font></b> (مص مرکب ) سلام کردن . (ناظم الاطباء). به معنی مصدر عشق زدن است . (از آنندراج ). رجوع به عشق و عشق زدن شود <span class=\"hlight\">:</span> <br>ز من عشقی بگو دیوانگان عشق راوحشی <br>که من زنجیر کردم پاره از دارالشفا رفتم .<br> <font color=\"Red\">وحشی (از آنندراج ).</font><br>به بوستان تو عشقی بلند میگویم <br>چو شبنم از گل رویت نبود میشویم .<br> <font color=\"Red\">صائب (از آنندراج ).</font><br>شدم پائین نافش گام چندی <br>حیا را گفته ام عشقی بلندی .<br><font color=\"Red\">حکیم زلالی (در تعریف دختر زال، از آنندراج ).</font><br></font></div>'),
(183674, 'عشقباز', '<span class=\"hlight\">عشقباز.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (نف مرکب ) عشق بازنده . آنکه عشقبازی کند. عاشق پیشه . (فرهنگ فارسی معین ). مرد شهوت پرست و عاشق و زن دوست . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>عشقبازان که به دست آرند آن حلقه ٔ زلف <br>دست در سلسله ٔ مسجداقصی بینند.<br> <font color=\"Red\">خاقانی .</font><br>شهری بفتنه شد که فلانی ازآن ِ ماست <br>ما عشقباز صادق و او عشقدان ماست .<br> <font color=\"Red\">خاقانی .</font><br>عشقبازان را برای سر بریدن سنت است <br>بر سر نطع ملامت پای کوبان آمدن .<br> <font color=\"Red\">خاقانی .</font><br>شکّر و بادام بهم نکته ساز<br>زهره و مریخ بهم عشقباز.<br> <font color=\"Red\">نظامی .</font><br>ز چنگ ابریشم دستان نوازان <br>دریده پرده های عشق بازان .<br> <font color=\"Red\">نظامی .</font><br>مه و خورشید را دیدندنازان <br>قران کرده به برج عشقبازان .<br> <font color=\"Red\">نظامی .</font><br>تو که در بند خویشتن باشی <br>عشقبازی دروغزن باشی .<br> <font color=\"Red\">سعدی .</font><br>به کوی لاله رخان هرکه عشقباز آید<br>امید نیست که هرگز بعقل بازآید.<br> <font color=\"Red\">سعدی .</font><br>دلم تا عشقباز آمد در او جز غم نمی بینم <br>دلی بیغم کجا جویم که در عالم نمی بینم .<br> <font color=\"Red\">سعدی .</font><br>لاف عشق و گله از یار زهی لاف دروغ <br>عشقبازان چنین مستحق هجرانند.<br> <font color=\"Red\">حافظ.</font><br><BR><font color=\"Blue\">◄</font> در هندوستان، اصطلاحاً کبوترباز را گویند، چنانکه شیخ ابوالفضل در جواب نامه ٔ عبداﷲخان ازبک نوشته است : و فرستادن کبوتران پری پرواز و آمدن حبیب عشقباز... (از آنندراج ).<br></font></div>'),
(183675, 'عشقدان', '<span class=\"hlight\">عشقدان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِ مرکب ) مجمر عشق . جایگاه عشق . کنایه از معشوق <span class=\"hlight\">:</span> <br>شهری به فتنه شد که فلانی ازآن ِ ماست <br>ما عشقباز صادق و او عشقدان ماست .<br> <font color=\"Red\">خاقانی .</font><br>یک شب به دو آفتاب بگذار<br>یک دل به دو عشقدان برافروز.<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(183676, 'عشقناک', '<span class=\"hlight\">عشقناک .</span> <font color=\"DarkGreen\"><b>[ ع ِ]</font></b> (ص مرکب ) دارای عشق . عاشق . (فرهنگ فارسی معین ).<br></font></div>'),
(183677, 'عشقه', '<span class=\"hlight\">عشقه .</span> <font color=\"DarkGreen\"><b>[ ع َش َ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ]</font></b> (از ع، اِ) نوعی از لبلاب است به عربی، و بفارسی عشق پیچان خوانند. گویند لبن آن یعنی شیر آن موی را بسترد و شپش رابکشد. (برهان ) (آنندراج ). نباتی است مثل لبلاب و بسیار کم برگ و شاخه های او بغایت از لبلاب قوی تر و درازتر، و بهر درختی که پیچد خشک کند لهذا عشق مشتق از اوست، و تخمش شبیه به حلبه و از آن کوچکتر، و در تنکابن لو نامند، و بعضی از اطبای این زمان تخم او را کشوت دانسته اند. (تحفه ٔ حکیم مؤمن ). گیاهی است بالارونده از تیره ٔ عشقه ها که از گیاهان نزدیک به تیره ٔ چتریان می باشد و جزو دولپه ایهای جداگلبرگ است . این گیاه از دیوار یا گیاهان اطراف خود بالا میرود و معمولاً دورتکیه گاه خود می پیچد. برگهایش متناوب و گلهایی به رنگ زرد مایل به سبز دارد. میوه اش پس از رسیدن به رنگ سیاه درآید و درون آن نیز بتعداد متغیر دانه وجود دارد. میوه ٔ عشقه دارای اثر مسهلی است ولی خالی از سمیت هم نیست . در نقاط گرم نواحی بحرالرومی از ساقه ٔ مسن این گیاه بطور خودبخود یا با ایجاد شکاف رِزین مخصوصی خارج میگردد که سابقاً تحت نام صمغ عشقه  بعنوان قاعده آور مصرف میگردید. در انساج این گیاه گلوکز یدی بنام هدرین  موجود است که دارای اثر قی آور و مسهل است . دم کرده ٔ برگ آن نیز اثر قاعده آور دارد. این گیاه در اکثر نقاط ایران خصوصاً نواحی شمالی بوفور میروید. توضیح اینکه در برخی کتب کلمه ٔ لبلاب را مرادف باعشقه ذکر کرده اند ولی اشتباه است و لبلاب فقط مرادف با انواع نیلوفر باغی و نیلوفر صحرایی است که جزو تیره ٔ پیچک ها و جزو دولپه ایهای پیوسته گلبرگ است . (فرهنگ فارسی معین ). درختی است که سبز گردد سپس ِ آنکه باریک و زرد گردد. ج، عَشَق . (منتهی الارب ) (از اقرب الموارد). پاپیتال . پاپیتال معمولی . حبل المساکین . برشن .بقلةالباردة. تال . اخفاک . قسوس . داردوست . دردوس . تویجه لی . ولگ . ولگم . بلگم . تبج . لشک . ولو. بلو. بلوه . لکو. صارمشق . چاندنی بیل . لبلاب کبیر. حلبلاب . مهربانک .عشق پیچان . پویچه . و رجوع به پیچک و داردوست شود.<br>- <span class=\"hlight\">تیره ٔ عشقه ها</span> ؛ تیره ای از گیاهان دولپه ای جداگلبرگ که دارای گل آذینی باچترهای ساده و برگهای پهن و پنجه ای و ساقه ٔ قلابدار است که معمولاً به درختان دیگر می پیچند و از آنها بالامیروند و چون در محل اتکا به درخت پایه ریشه ٔ فرعی خارج میکنند و مواد غذائی درخت پایه را می مکند از اینجهت مضرند زیرا درختان پایه را خشک میکنند و نیز اگر بدیوار بچسبند چون ریشه های فرعی آن در دیوار فرومیروند دیوار را خراب میکنند. نوع مهم گیاهان این تیره عشقه است . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عشقه ٔ استرالیائی </span> ؛ نوعی عشقه که برخلاف عشقه ٔ معمولی پیچ نیست و به دور گیاهان نمی پیچد.<br>- <span class=\"hlight\">عشقه ٔ زمینی </span> ؛ گیاهی است که آن را علف چای و هزارچشم نامند. (از فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عشقه ٔ معمولی </span> ؛ عشقه که نوعی گیاه است . (از فرهنگ فارسی معین ). رجوع به عشقه شود.<br><BR><font color=\"Blue\">◄</font> اراکة، و یک درخت اراک . (از اقرب الموارد).<br></font></div>'),
(183678, 'عشقوان', '<span class=\"hlight\">عشقوان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق َ ]</font></b> (اِخ ) دهی از دهستان خاروطوران بخش بیارجمند شهرستان شاهرود. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٦٠</span> تن . آب آن از قنات کم آب . محصول آن مختصری غلات و پنبه و تنباکو و لبنیات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(183679, 'عشقی', '<span class=\"hlight\">عشقی .</span><font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) (میرزاده ٔ...) نام او محمدرضابن حاج سیدابوالقاسم کردستانی، و از شعرای قرن اخیر ایران بوده است . وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٧٢</span> هَ .ش . در همدان متولد شد و به آموختن ادب و شعر پرداخت . ذوق و احساسات ادبی او آمیخته با احساسات وطن پرستی و آزادیخواهی و اصلاح طلبی بود. در جسارت و ازخودگذشتگی و بی باکی کم نظیر بود. عشقی در دوران جنگ بین المللی اول به کشور عثمانی رفت و در دارالفنون آنجا تحصیل کرد. وی روزنامه ٔ «قرن بیستم » را که حاوی مقالات و اشعار تند ضد هیئت حاکمه بود در تهران انتشار داد، و ظاهراً بسبب همین مقالات بسال <span class=\"hlight\" dir=\"rtl\">١٣٠٣</span> هَ .ش . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٣٤٢</span> هَ .ق . به دست دو تن ناشناس کشته شد و جسد او را در ابن بابویه تهران بخاک سپردند. عشقی در اپرای معروف «رستاخیز»، رستاخیز شاهان بزرگ ایران را نشان میدهد که یکایک به صحنه می آیند و بحال کشور ایران افسوس میخورند و افتخارات دوره های گذشته را بیاد می آورند. تابلوهای «ایده آل » و «کفن سیاه » او هر یک شامل انتقاد اوضاع اجتماعی ایران است . دیوان وی مکرر بطبع رسیده است . (از فرهنگ فارسی معین ).ملک الشعراء بهار در رثاء وی سروده است <span class=\"hlight\">:</span> <br>وه که عشقی در شباب زندگی <br>از خدنگ دشمن شب رو بمرد<br>شاعری نو بود و شعرش نیز نو<br>شاعر نو مرد و شعر نو بمرد.<br></font></div>'),
(183680, 'عشقی', '<span class=\"hlight\">عشقی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ص نسبی ) منسوب به عشق . رجوع به عشق شود.<br>- <span class=\"hlight\">غزل عشقی </span> ؛ غزل که مطالب عشقی را شامل باشد.<br><BR><font color=\"Blue\">◄</font> در اصطلاح عامیانه، آنکه بمیل و هوی و هوس خود کار کند، مثلاً گویند: فلانی آدمی عشقی است . (از فرهنگ فارسی معین ).<br></font></div>'),
(183681, 'عشقیات', '<span class=\"hlight\">عشقیات .</span> <font color=\"DarkGreen\"><b>[ ع ِ قی یا ]</font></b> (ع اِ مرکب ) ج ِ عشقیة، مؤنث عشقی . (از فرهنگ فارسی معین ). آنچه به عشق بستگی و انتساب و تعلق دارد <span class=\"hlight\">:</span> تاهر وصف که خواهند از فنون عشقیات و انواع تشوّقات تقدیم کنند. (المعجم فی معاییر اشعار العجم ص <span class=\"hlight\" dir=\"rtl\">٣٨٥</span>).<br></font></div>'),
(183682, 'عشقیة', '<span class=\"hlight\">عشقیة.</span> <font color=\"DarkGreen\"><b>[ ع ِ قی ی َ ]</font></b> (ع ص نسبی ) مؤنث عشقی . (فرهنگ فارسی معین ). ج، عشقیات . رجوع به عشقی و عشقیات شود.<br></font></div>'),
(183683, 'عشم', '<span class=\"hlight\">عشم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص )فربه شدن گرفتن شتر. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خشک گردیدن . (از ناظم الاطباء).<br></font></div>'),
(183684, 'عشم', '<span class=\"hlight\">عشم .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (ع مص ) خشک گردیدن . (ازمنتهی الارب ) (از اقرب الموارد). عُشوم . و رجوع به عشوم شود. <BR><font color=\"Blue\">◄</font> حریص شدن . (از منتهی الارب ).<br></font></div>'),
(183685, 'عشم', '<span class=\"hlight\">عشم .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (ع اِمص ) امید و آزمندی . (منتهی الارب ). طمع. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص )نان خشک و تباه : خبز عشم ؛ نان خشک و فاسد. (منتهی الارب ). نان خشک یا فاسد و تباه . (از اقرب الموارد).<br></font></div>'),
(183686, 'عشم', '<span class=\"hlight\">عشم .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ِ ]</font></b> (ع اِ) یکی عُشُم . (منتهی الارب ) (از اقرب الموارد). عاشِم . رجوع به عُشم و عاشم شود.<br></font></div>'),
(183687, 'عشم', '<span class=\"hlight\">عشم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش ُ ]</font></b> (ع اِ) درختی است، و واحد آن عاشم و عَشِم است . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183688, 'عشمة', '<span class=\"hlight\">عشمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ م َ ]</font></b> (ع اِمص ) آزمندی . (منتهی الارب ). طمع. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) خشک از لاغری . <BR><font color=\"Blue\">◄</font> پاره ٔ نان خشک . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) پیری و خرفی . <BR><font color=\"Blue\">◄</font> (ص ) پیر کلانسال از مرد و زن، و پشت دوتای گام نزدیک نهنده . (منتهی الارب ). شیخ فانی، برای مذکر و مؤنث، و یا آنکه گام نزدیک بهم نهد و خمیده پشت باشد، گویند: شیخ عشمة و عجوز عشمة. (از اقرب الموارد).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(183689, 'عشن', '<span class=\"hlight\">عشن .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) به خواست خود گفتن و تخمین نمودن . (از منتهی الارب ). با رأی و نظر خود گفتن و تخمین زدن . (از اقرب الموارد).<br></font></div>'),
(183690, 'عشنج', '<span class=\"hlight\">عشنج .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َن ْ ن َ ]</font></b> (ع ص ) ترشروی زشتخوی . (منتهی الارب ). آنکه چهره اش گرفته باشد و بدمنظره باشد از مردان . (از اقرب الموارد).<br></font></div>'),
(183691, 'عشنزر', '<span class=\"hlight\">عشنزر.</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ زَ ]</font></b> (ع ص ) سخت و درشت اندام و بزرگ از هر چیزی . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183692, 'عشنزن', '<span class=\"hlight\">عشنزن .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ زَ ]</font></b> (ع ص ) دشوار و پیچیده و درشت خلقت . (ناظم الاطباء).شدید و سخت در خلقت و آفرینش . (از اقرب الموارد).<br></font></div>'),
(183693, 'عشنط', '<span class=\"hlight\">عشنط.</span> <font color=\"DarkGreen\"><b>[ ع َ ش َن ْ ن َ ]</font></b> (ع ص ) نیک دراز، یا مرد پرگوشت نازک و نیکو اندام زیرک . ج، عشنطون . عَشانط. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183694, 'عشنق', '<span class=\"hlight\">عشنق .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َن ْ ن َ]</font></b> (ع ص ) درازقد سبک و کم گوشت . (منتهی الارب ) (از اقرب الموارد). عُشانِق . ج، عَشانقة. (اقرب الموارد).<br></font></div>'),
(183695, 'عشو', '<span class=\"hlight\">عشو.</span> <font color=\"DarkGreen\"><b>[ ع َش ْوْ ]</font></b> (ع اِ) عشواللیل ؛ تاریکی شب . (دهار). عشوة. رجوع به عشوة شود.<br></font></div>'),
(183696, 'عشو', '<span class=\"hlight\">عشو.</span> <font color=\"DarkGreen\"><b>[ ع ِش ْوْ ]</font></b> (ع اِ) کاسه ٔ شیر که شبانگاه وقت بازگشتن گوسپندان یا بعد آن نوشند. (منتهی الارب ). قدح شیر و لبن که در ساعت بازگشتن گوسفندان از چرا، و یا بعد از آن نوشیده شود. (از اقرب الموارد).<br></font></div>'),
(183697, 'عشو', '<span class=\"hlight\">عشو.</span> <font color=\"DarkGreen\"><b>[ ع ُ ش ُوو ]</font></b> (ع مص ) در شب از دور دیدن آتش را و آهنگ روشنی نمودن . (از منتهی الارب ). آتش را در شب از دور دیدن و قصد روشنائی آن کردن به امید رهنمایی یا مهمانی . (از اقرب الموارد). عَشْو. رجوع به عَشْو شود. <BR><font color=\"Blue\">◄</font> طعام شبانگاهی خوردن . (از منتهی الارب ). عَشْو. رجوع به عَشْو شود.<br></font></div>'),
(183698, 'عشو', '<span class=\"hlight\">عشو.</span> <font color=\"DarkGreen\"><b>[ ع َش ْوْ ]</font></b> (ع مص ) در شب از دور دیدن آتش را و آهنگ روشنی آن نمودن . (از منتهی الارب ). نزدیک آتش شدن برای بردن . (تاج المصادر بیهقی ) (المصادر زوزنی ): عشا النار، عشا اًلی النار؛ آتش را در شب از دور دیدو قصد روشنائی آن را کرد به امید رهنمایی و یا مهمانی . (از اقرب الموارد). عُشوّ. رجوع به عشوّ شود. <BR><font color=\"Blue\">◄</font> طعام شبانگاهی خوردن . (از منتهی الارب ). شام خوردن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> طعام شبانگاهی خورانیدن کسی را. (از منتهی الارب ). شام دادن . (تاج المصادر بیهقی ). عشاء و شام خورانیدن کسی را.(از اقرب الموارد). عَشْی . و رجوع به عَشْی شود. <BR><font color=\"Blue\">◄</font> در شب قصد کسی کردن، سپس بصورت عام بکار رفته و هر قصدکننده ای را «عاشی » گفته اند. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> از کسی اعراض کردن . (تاج المصادر بیهقی ) (از المصادر زوزنی ) (از دهار). اعراض کردن از کسی و روی آوردن به دیگری . (ازاقرب الموارد) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> راه جستن بسوی کسی . (از منتهی الارب ). به نزدیک کسی به امید احسان رفتن . (المصادر زوزنی ). طلب کردن فضل کسی را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شب چرانیدن شتران را. <BR><font color=\"Blue\">◄</font> مانند نابینا کردن کاری را. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بد شدن بینائی در شب و روز، و یا نابینا شدن، و یا بینا بودن در روز و نابینا بودن در شب . (از اقرب الموارد).<br></font></div>'),
(183699, 'عشوان', '<span class=\"hlight\">عشوان .</span> <font color=\"DarkGreen\"><b>[ ع ُش ْ ]</font></b> (ع اِ) نوعی از تمر است، یا خرمابنی . (منتهی الارب ). خرما، و گویند نخلی است . (از اقرب الموارد).<br></font></div>'),
(183700, 'عشواوان', '<span class=\"hlight\">عشواوان .</span> <font color=\"DarkGreen\"><b>[ ع َش ْ ن ِ ]</font></b> (ع ص، اِ) تثنیه ٔ عشواء: امرأتان عشواوان ؛ دو زن شبکور. (از ناظم الاطباء). رجوع به عشواء شود.<br></font></div>'),
(183701, 'عشور', '<span class=\"hlight\">عشور.</span> <font color=\"DarkGreen\"><b>[ ع ُ]</font></b> (ع مص ) ده یک گرفتن از اموال کسی . (از منتهی الارب )(از اقرب الموارد). عَشر. رجوع به عشر شود. <BR><font color=\"Blue\">◄</font> عشر و ده یک مال را ستدن . (از اقرب الموارد).<br></font></div>'),
(183702, 'عشور', '<span class=\"hlight\">عشور.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b>(ع اِ) ج ِ عُشر. (منتهی الارب ) (اقرب الموارد). رجوع به عُشر شود. آنچه از تجار بر معابر بحار بطریق باج گیرند. (آنندراج ) <span class=\"hlight\">:</span> از تجار و مترددین بنادر عشور گرفته قلیلی به والی مذکور میدادند. (عالم آرای عباسی از آنندراج ). وجوه عشور بنادر رسد فرنگان وانگلیس و پرتکال . (تذکرةالملوک چ دبیرسیاقی ص <span class=\"hlight\" dir=\"rtl\">٩٦</span>).<br>- <span class=\"hlight\">عشور جنگلی </span> ؛ عوارض که بر مبنای بهای چوب از خداوند آن گیرند.<br><BR><font color=\"Blue\">◄</font> ج ِ عَشیر. (منتهی الارب ). رجوع به عشیر شود.<br></font></div>'),
(183703, 'عشورا', '<span class=\"hlight\">عشورا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (از ع، اِ) عشوراء. (از ناظم الاطباء). رجوع به عشوراء شود <span class=\"hlight\">:</span> به وقت طلوع صبح پنجشنبه روز عشورا بر دواتدار و ابن کنز زدند. (رشیدی ).<br></font></div>'),
(183704, 'عشوز', '<span class=\"hlight\">عشوز.</span> <font color=\"DarkGreen\"><b>[ ع َش ْ وَ ]</font></b> (ع ص ) سخت و درشت از راه زمین . (منتهی الارب ). راه و یازمینی که پیمودن آن دشوار و صعب باشد. ج، عَشاوز. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درشت و قوی از شتران . (منتهی الارب ). سخت و درشت در آفرینش . (از اقرب الموارد). عَشَوّز. و رجوع به عَشَوّز شود. <BR><font color=\"Blue\">◄</font> گوشت بسیار. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183705, 'عشوز', '<span class=\"hlight\">عشوز.</span> <font color=\"DarkGreen\"><b>[ ع َ ش َوْ وَ ]</font></b> (ع ص ) درشت و قوی از شتران . (منتهی الارب ). سخت و درشت در آفرینش . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گوشت بسیار. (منتهی الارب ) (از اقرب الموارد). عَشوَز. و رجوع به عَشْوَز شود.<br></font></div>'),
(183706, 'عشوزن', '<span class=\"hlight\">عشوزن .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ زَ ]</font></b> (ع ص ) دشوار و پیچیده از هر چیزی . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درشت خلقت . (منتهی الارب ). سخت و شدید در خلقت و آفرینش . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد سخت و درشت اندام . (منتهی الارب ). سخت و غلیظ. <BR><font color=\"Blue\">◄</font> اماکنی که پیمودن آنها صعب و دشوار باشد. (از اقرب الموارد). ج، عَشازن، عَشاوز. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتر سطبراندام . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِخ ) نام جایگاهی است . (از معجم البلدان ).<br></font></div>'),
(183707, 'عشوزنة', '<span class=\"hlight\">عشوزنة.</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ زَ ن َ ]</font></b> (ع ص ) مؤنث عشوزن . (منتهی الارب ) (از اقرب الموارد): قناة عشوزنة؛ نیزه ٔ سخت . (از اقرب الموارد). رجوع به عشوزن شود.<br></font></div>'),
(183708, 'عشوف', '<span class=\"hlight\">عشوف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) درخت خشک . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183709, 'عشوق', '<span class=\"hlight\">عشوق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) بسیار عشق کننده و صاحب عشق . (غیاث اللغات ).<br></font></div>'),
(183710, 'عشوم', '<span class=\"hlight\">عشوم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) خشک گردیدن . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آزمند و حریص شدن . (از منتهی الارب ). عَشَم . و رجوع به عشم شود.<br></font></div>'),
(183711, 'عشوند', '<span class=\"hlight\">عشوند.</span> <font color=\"DarkGreen\"><b>[ ع ُش ْ وَ ]</font></b> (اِخ )دهی از دهستان بالا از شهرستان نهاوند. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٦٥٠</span>تن . آب آن از قنات و چشمه . محصول آن غلات، انگور، صیفی و لبنیات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(183712, 'عشوه', '<span class=\"hlight\">عشوه .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْوَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b> (از ع، اِ) وعده ٔ دروغ . (دهار). فریب . (ناظم الاطباء) (غیاث اللغات ) <span class=\"hlight\">:</span> برادر ما را بر آن داشتند که رسول ما را بازگردانید و رسولی با وی نامزد کردند با مشتی عشوه و پیغام که ولیعهد پدر ویست . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١١٨</span>). باید که جوابی جزم قاطع دهید نه عشوه و بیکار چنانکه بر آن اعتماد توان کرد. (تاریخ بیهقی ). وزیر مرا گفت اینهمه عشوه است که دانند ما نتوانیم قصد ایشان کرد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٦٢٠</span>).<br>زنا و مسخره جور و محال و غیبت و دزدی <br>دروغ و مکر و عشوه کبر و طراری و غمازی .<br> <font color=\"Red\">ناصرخسرو.</font><br>با واقعه ٔ عشقم و یا حادثه ٔ هجر<br>در عشوه ٔ وسواسم و در قبضه ٔ سودا.<br> <font color=\"Red\">مسعودسعد.</font><br>نه دم کدیه ای همی گویم <br>نه دم عشوه ای همی دارم .<br> <font color=\"Red\">مسعودسعد.</font><br>جاه دنیای فریبنده ... مانند... عشوه ٔ سرابست . (کلیله و دمنه ).<br>هرچه از مجلس او خواسته شد یافته شد<br>که ندارد دل او عشوه و زرق و تلبیس .<br> <font color=\"Red\">سوزنی .</font><br>بسیارسخن گفته شد از وعده و عشوه <br>تا رام شد آن توسن بدمهر به زر بر.<br> <font color=\"Red\">سوزنی .</font><br>عشوه و زرق بسوی دل بی تلبیسش <br>ره نیابد چو سوی جنت اعلی ابلیس .<br> <font color=\"Red\">سوزنی .</font><br>از سر جوی عشوه آب ببند<br>بیش ازین گرد پای حوض مگرد.<br> <font color=\"Red\">انوری .</font><br>از عشوه ٔ آسمان مرا بس <br>از چاشنی جهان مرا بس .<br> <font color=\"Red\">خاقانی .</font><br>خود را به دست عشوه ٔ ایام وامده <br>کز باد کس امید ندارد وفای خاک .<br> <font color=\"Red\">خاقانی .</font><br>دل منه بر عشوه های آسمان زیرا که هست <br>بی سر و بن کارهای آسمان چون آسمان .<br> <font color=\"Red\">خاقانی .</font><br>کرده ابلیس را به عشوه تباه <br>دله  را داده بازی روباه .<br> <font color=\"Red\">ظهیر فاریابی .</font><br>او بر امید آن عشوه بر صوب بخارا رحلت کرد.(ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٩٢</span>). دیو عشوه ای که او را به قطع مال مقاطعه وسوسه میدهد به صلیل شمشیر هندی در قاروره های قهر مقید گرداند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٣٦</span>).<br>که گر شه گوید او را دوست دارم <br>بگو کاین عشوه ناید در شمارم .<br> <font color=\"Red\">نظامی .</font><br>بدین عشوه دادند شه را شکیب <br>یکی بر دلیری یکی بر فریب .<br> <font color=\"Red\">نظامی .</font><br>بسا ابرا که بندد کله ٔ مشک <br>به عشوه باغ دهقان را کند خشک .<br> <font color=\"Red\">نظامی .</font><br>بدین عشوه و خدیعت گورخان را در چاه غرور افکند. (جهانگشای جوینی ). بدین عشوه و غرور می پنداشت که دفع مقدر تواند کرد. (جهانگشای جوینی ).<br>تو بمخراش به عشوه رخ نیکی را زآنک <br>هرکه او عشوه کند نیکی او پنهانست .<br>بدر جاجرمی (در ترجمه ٔ عنوان الحکم بستی ).<br> <BR><font color=\"Blue\">◄</font> ناز و حرکت معشوق که دل عاشق بدان فریفته شود. (غیاث اللغات ). ناز و کرشمه .(آنندراج ). حرکت نازنینان که بدان دل عاشقان را مجذوب کنند. کرشمه . ناز. دلفریبی . پخس . تیباش . شکنه . خودنمائی . (ناظم الاطباء). اصلاً بمعنی فریب است اما در عرف عام بمعنی غنج و دلال و کرشمه و دلبری استعمال میشود. گاه نیز آن را به «عور» به همین معنی عطف میکنند. (از فرهنگ لغات عامیانه ) <span class=\"hlight\">:</span> <br>من درس عشق خواندم واو درس دلبری <br>گل کرد مشق عشوه و بلبل ترانه را.<br> <font color=\"Red\">کمالی .</font><br>گره بر سینه زن بی رنج مخروش <br>ادب کن عشوه را یعنی که خاموش .<br> <font color=\"Red\">نظامی .</font><br>خیال از ناجوانمردی همه روز<br>به عشوه میفزاید بر دلم سوز.<br> <font color=\"Red\">نظامی .</font><br>ای مطرب از آن حریف پیغامی ده <br>وین دلشده را به عشوه آرامی ده .<br> <font color=\"Red\">سعدی .</font><br>عشوه ای از لب شیرین تو دل خواست بجان <br>به شکرخنده لبت گفت مزادی طلبیم .<br> <font color=\"Red\">حافظ.</font><br>کام جان تلخ شد از صبر که کردم بی دوست <br>عشوه ای زآن لب شیرین شکربار بیار.<br> <font color=\"Red\">حافظ.</font><br>تا آسمان ز حلقه بگوشان ما شود<br>کو عشوه ای ز ابروی همچون هلال تو.<br> <font color=\"Red\">حافظ.</font><br>چشم ساقی عشوه ای بر طاعت و تقوی گماشت <br>دست مستی دامن زلف شکن پرور گرفت .<br> <font color=\"Red\">ظهوری (از آنندراج ).</font><br>- <span class=\"hlight\">عشوه و عور</span> ؛ از اتباع . (از فرهنگ لغات عامیانه ). رجوع به عشوه شود.<br>- <span class=\"hlight\">عشوه و غمزه </span> ؛ ناز و کرشمه . از اتباع است .<br>- <span class=\"hlight\">عشوه و ناز</span> ؛ کرشمه و ناز.از اتباع است .<br>- <span class=\"hlight\">عشوه های لاجوردی </span> ؛ کنایه از نازهای متنوع و رنگارنگ است . (از آنندراج ). کرشمه های گوناگون . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>گرچه چشم شوخ زرین ابروَم باشد کبود<br>از نگاهش عشوه های لاجوردی خوشنماست .<br> <font color=\"Red\">محمدسعید اشرف (از آنندراج ).</font><br>اگرصورت ظرف چینی به پله ٔ معنی جلوه سر می کشید به رنگ عشوه ٔ لاجوردی هزار من طلا نثار می دید. (از رقعه ٔ ملاطغرا به آقامحمدخان، از آنندراج ).<br>- <span class=\"hlight\">عشوه های مرمری </span> ؛ کنایه از نازهای ساده و بیرنگ است، چه مرمر سفید می باشد و سفید از الوان نیست . (آنندراج ). ناز و کرشمه های ساده . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>آن یکی چشمک زند کاینک بیا از من بخر<br>نازهای نیمرنگ و عشوه های مرمری .<br> <font color=\"Red\">ملا فوقی یزدی (از آنندراج ).</font><br><BR><font color=\"Blue\">◄</font> در اصطلاح عاشقان، تجلی جمال . (از کشاف اصطلاحات الفنون ).<br></font></div>'),
(183713, 'عشوه آمیز', '<span class=\"hlight\">عشوه آمیز.</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b>(ن مف مرکب ) آمیخته به عشوه و فریب <span class=\"hlight\">:</span> همگان عشوه آمیز سخن میگفتند و کاری بزرگ افتاده سهل میکردند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٩٥</span>). بر آن سخنان عشوه آمیز و غرورانگیز ایشان دل نباید نهاد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٩٩</span>).<br></font></div>'),
(183714, 'عشوه آگین', '<span class=\"hlight\">عشوه آگین .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b> (ص مرکب ) نازآلود. دارای ناز. باکرشمه .دلفریب . (فرهنگ فارسی معین ). و رجوع به عشوه شود.<br></font></div>'),
(183715, 'عشوه انگیز', '<span class=\"hlight\">عشوه انگیز.</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ اَ ]</font></b> (نف مرکب ) عشوه انگیزنده . فریبنده . کرشمه انگیز <span class=\"hlight\">:</span> خنجر سرتیزش چون مژگان خوبان عشوه انگیز، خونریز. (حبیب السیر جزو <span class=\"hlight\" dir=\"rtl\">٤</span> از ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٢</span>).<br></font></div>'),
(183716, 'عشوه خر', '<span class=\"hlight\">عشوه خر.</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ خ َ ]</font></b> (نف مرکب ) خریدار عشوه . طالب عشوه . و رجوع به عشوه خریدن شود <span class=\"hlight\">:</span> <br>گر دهد خصم خواب خرگوشت <br>مصلحت را بخر که عشوه خر است .<br><font color=\"Red\">انوری .</font><br></font></div>'),
(183717, 'عشوه خری', '<span class=\"hlight\">عشوه خری .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ خ َ ]</font></b> (حامص مرکب ) عمل و حالت عشوه خر. رجوع به عشوه خریدن شود <span class=\"hlight\">:</span> <br>یک زبان داری و صد عشوه گری <br>من و صدجان ز پی عشوه خری .<br> <font color=\"Red\">خاقانی .</font><br>- عشوه خری کردن، پذیرای عشوه شدن <span class=\"hlight\">:</span> <br>عشوه گری میکند لعل تو و طرفه آنک <br>عقل چو خاقانئی عشوه خری میکند.<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(183718, 'عشوه خریدن', '<span class=\"hlight\">عشوه خریدن .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ خ َ دَ ]</font></b> (مص مرکب ) پذیرفتن عشوه . خریداری ناز و کرشمه . فریب خوردن . گول خوردن <span class=\"hlight\">:</span> و طغرل را گفت شاد باش ای کافر نعمت ازبهر این ترا پروردم و از فرزندان عزیزتر داشتم تا بر من چنین ساختی به عشوه ای که خریدی برسد بتو آنچه سزاوار آنی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٥٢</span>). سالاری محتشم ... فرستاده آید... تا آن دیار را که گرفته بودیم ضبط کند... تا خواب نبینند و عشوه نخرند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٩٠</span>).<br>ز مرگ امن مجوی و به عمر تکیه مکن <br>به سیم دین مفروش و ز دیو عشوه مخر.<br><font color=\"Red\">ناصرخسرو.</font><br>زبهر خسرو سیارگان همی خواهد<br>که عشوه ای بخرم وآن لباچه بفروشم .<br> <font color=\"Red\">انوری .</font><br>این دم بخورد و این عشوه بخرید و نقد به نسیه بفروخت . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٦٠</span>).<br>مفروش چنان بر آنکه پیر است <br>عشوه خرد از تو هر زمانی .<br> <font color=\"Red\">عطار.</font><br>نوشته اند برایوان جنةالمأوی <br>که هرکه عشوه ٔ دنیا خرید وای به وی .<br> <font color=\"Red\">حافظ.</font><br>عشوه دادند که بر ما گذری خواهی کرد<br>دیدی آخر که چنین عشوه خریدیم و برفت .<br> <font color=\"Red\">حافظ.</font><br>مقصود ازین معامله بازار تیز نیست <br>نی جلوه میفروشم و نی عشوه میخرم .<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(183719, 'عشوه خوردن', '<span class=\"hlight\">عشوه خوردن .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ دَ ]</font></b> (مص مرکب ) فریب خوردن .گول خوردن <span class=\"hlight\">:</span> حمدونه این عشوه ها چون شکر بخورد و بر آب کار سوی ماهی رفت . (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٤٨</span>).<br>کسی را بود کیمیا در نورد<br>که او عشوه ٔ کیمیاگر نخورد.<br> <font color=\"Red\">نظامی .</font><br>گر صادقی تو عشوه از آن قرص ِ خور مخور<br>ور مرد رهروی دم ازین ره دگر مزن .<br><font color=\"Red\">بدر چاچی (از آنندراج ).</font><br></font></div>'),
(183720, 'عشوه خیز', '<span class=\"hlight\">عشوه خیز.</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b>(نف مرکب ) عشوه خیزنده . فریب ده . پرفریب <span class=\"hlight\">:</span> <br>عیب جز این نیستمان که ما نه چو ایشان <br>بدکنش و عشوه خیز و زشت مقالیم .<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(183721, 'عشوه دادن', '<span class=\"hlight\">عشوه دادن .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ دَ ]</font></b> (مص مرکب ) فریب دادن . فریفتن . گول زدن <span class=\"hlight\">:</span> من ندانستم که کار این قوم بدین منزلت است و عشوه دادند مرا به حدیث ایشان و راست نگفتند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٨٥</span>). پس اگر عشوه دهد کسی که حیلتی باید ساخت که مسعود بر جناح سفر است ... نباید خرید. (تاریخ بیهقی ). خردمند آن است که به نعمتی وعشوه ای که زمانه دهد فریفته نشود. (تاریخ بیهقی ).<br>گفتی که چو وقت آید کارت به ازین سازم <br>این عشوه مده کآنگه افسوس گرت خوانم .<br> <font color=\"Red\">خاقانی .</font><br>گر فلکت عشوه ٔ آبی دهد<br>تا نفریبی که سرابی دهد.<br> <font color=\"Red\">نظامی .</font><br>سیره ای دارد عجب در دلبری <br>عشوه پیدا بوسه پنهان میدهد.<br> <font color=\"Red\">عطار.</font><br>لاجرم هیچ کدام شخص بر امیر و پیشوای خویش دلال نتواند و دیگری او را عشوه ندهد. (جهانگشای جوینی ).<br>خوابست همی که مینماید<br>یا عشوه همی دهد خیالم .<br><font color=\"Red\">سعدی .</font><br>دوش لعلش عشوه ای میداد حافظ را ولی <br>من نه آنم کز وی این افسانه ها باور کنم .<br> <font color=\"Red\">حافظ.</font><br>عشوه دادند که بر ما گذری خواهد کرد<br>دیدی آخر که چنین عشوه خریدیم و برفت .<br> <font color=\"Red\">حافظ.</font><br>عشوه میداد که از کوی وفایت نروم <br>دیدی آخر که چنان عشوه خریدیم و برفت .<br><font color=\"Red\">حافظ (از آنندراج ).</font><br></font></div>'),
(183722, 'عشوه دان', '<span class=\"hlight\">عشوه دان .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b> (نف مرکب ) عشوه داننده . ناز و غمزه دان . آشنا بطریق کرشمه و عشوه <span class=\"hlight\">:</span> <br>کو بتی کز عشق او یک شهر جان افشانده اند<br>زرّ و سر بر عشوه ٔ آن عشوه دان افشانده اند.<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(183723, 'عشوه ده', '<span class=\"hlight\">عشوه ده .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ دِه ْ ]</font></b> (نف مرکب ) عشوه دهنده . فریب دهنده . فریبکار <span class=\"hlight\">:</span> <br>شه وزیری داشت رهزن عشوه ده <br>کاو بر آب از مکر بربستی گره .<br> <font color=\"Red\">مولوی .</font><br>بگو آنچه دانی که حق گفته به <br>نه رشوت ستانی و نه عشوه ده .<br> <font color=\"Red\">سعدی .</font><br>دنیا زنیست عشوه ده ودلستان ولیک <br>با کس همی بسر نبرد عهد شوهری .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(183724, 'عشوه زن', '<span class=\"hlight\">عشوه زن .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ زَ ]</font></b> (نف مرکب ) عشوه زننده . کسی که دلربائی میکند. برانگیزنده ٔ شهوت . (ناظم الاطباء). عشوه ساز. عشوه کار.<br></font></div>'),
(183725, 'عشوه زنی', '<span class=\"hlight\">عشوه زنی .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ زَ ]</font></b> (حامص مرکب ) عمل و حالت عشوه زن . عشوه سازی . عشوه کاری . (فرهنگ فارسی معین ).<br></font></div>'),
(183726, 'عشوه ساختن', '<span class=\"hlight\">عشوه ساختن .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ت َ ]</font></b> (مص مرکب ) فریب ساختن . فریب در کار آوردن <span class=\"hlight\">:</span> <br>چو نان طلب کنم از شاه عشوه سازد قوتم <br>چو آب خواهم از ایام زهر دارد پیشم .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(183727, 'عشوه ساز', '<span class=\"hlight\">عشوه ساز.</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b> (نف مرکب ) عشوه سازنده .دلربا و دلفریب . (ناظم الاطباء). آنکه عشوه بکار برد. عشوه کار. عشوه زن . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>هفت و نه این صنم عشوه ساز<br>عقل فریب آمد و برنانواز.<br><font color=\"Red\">امیرخسرو.</font><br></font></div>'),
(183728, 'عشوه سازی', '<span class=\"hlight\">عشوه سازی .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b> (حامص مرکب ) عمل و حالت عشوه ساز. عشوه زنی . عشوه کاری . (فرهنگ فارسی معین ). کرشمه و دلفریبی . (ناظم الاطباء).<br></font></div>'),
(183729, 'عشوه فروختن', '<span class=\"hlight\">عشوه فروختن .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ف ُ ت َ ]</font></b> (مص مرکب ) عشوه نشان دادن . فریب آوردن . فریفتن <span class=\"hlight\">:</span> <br>دل عشوه میفروخت که من مرغ زیرکم <br>اینک فتاده در سر زلف چو دام اوست .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(183730, 'عشوه نمای', '<span class=\"hlight\">عشوه نمای .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ ]</font></b> (نف مرکب ) عشوه نماینده . عشوه ساز. عشوه گر <span class=\"hlight\">:</span> <br>با دل خویش هر زمان گویم <br>کآن بت عیب جوی عشوه نمای ...<br><font color=\"Red\">اشرفی سمرقندی .</font><br></font></div>'),
(183731, 'عشوه پرداز', '<span class=\"hlight\">عشوه پرداز.</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ پ َ ]</font></b> (نف مرکب ) عشوه پردازنده . دارای ناز و کرشمه . (ناظم الاطباء). آنکه ناز و کرشمه کند. دارای ناز و غمزه . (فرهنگ فارسی معین ).<br></font></div>'),
(183732, 'عشوه پردازی', '<span class=\"hlight\">عشوه پردازی .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ پ َ ]</font></b> (حامص مرکب ) عمل و حالت عشوه پرداز. (فرهنگ فارسی معین ). ناز و کرشمه کردن . عشوه کردن .<br></font></div>'),
(183733, 'عشوه کردن', '<span class=\"hlight\">عشوه کردن .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ک َ دَ ]</font></b> (مص مرکب ) ناز و غمزه کردن . کرشمه کردن . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> اگر نیامدند و سخن نشنودند و عشوه کردند آنگاه بحکم مشاهده کار خویش می باید کرد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٦٥٨</span>).<br>تو بمخراش به عشوه رخ نیکی را زآنک <br>هرکه او عشوه کند نیکی او پنهانست .<br><font color=\"Red\">بدر جاجرمی (در ترجمه ٔ عنوان الحکم بستی ).</font><br></font></div>'),
(183734, 'عشوه گر', '<span class=\"hlight\">عشوه گر.</span> <font color=\"DarkGreen\"><b>[ ع ِش ْوَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ گ َ ]</font></b> (ص مرکب ) آنکه عشوه بکار برد. عشوه کار. عشوه ساز. (فرهنگ فارسی معین ). شوخ چشم و دلفریب و دارای ناز و کرشمه . (ناظم الاطباء). زراق <span class=\"hlight\">:</span> <br>بالابلند عشوه گر نقش باز من <br>کوتاه کرد قصه ٔ زهد دراز من .<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(183735, 'عشوه گری', '<span class=\"hlight\">عشوه گری .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ گ َ ]</font></b> (حامص مرکب ) عمل و حالت عشوه گر. عشوه سازی . عشوه کاری . (فرهنگ فارسی معین ). دلفریبی و شوخ چشمی . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>یک زبان داری و صد عشوه گری <br>من و صدجان ز پی عشوه خری .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عشوه گری کردن </span> ؛ عشوه سازی کردن <span class=\"hlight\">:</span> <br>عشوه گری میکند لعل تو و طرفه آنک <br>عقل چو خاقانئی عشوه خری میکند.<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(183736, 'عشوی', '<span class=\"hlight\">عشوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ وی ی ]</font></b> (ع ص نسبی ) منسوب به عَشیّه . (از اقرب الموارد) (ناظم الاطباء). رجوع به عشیة شود.<br></font></div>'),
(183737, 'عشویة', '<span class=\"hlight\">عشویة.</span> <font color=\"DarkGreen\"><b>[ ع َ وی ی َ ]</font></b> (ع اِ) جای تاریک . (ناظم الاطباء).<br></font></div>'),
(183738, 'عشی', '<span class=\"hlight\">عشی .</span>  <font color=\"DarkGreen\"><b>[ ع َ شا ]</font></b> (ع مص ) ستم کردن بر کسی . شبانگاه چریدن شتران . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شب کور گشتن و ضعیف شدن بینائی . (از ناظم الاطباء) (از اقرب الموارد). و رجوع به عَشا شود.<br></font></div>'),
(183739, 'عشی', '<span class=\"hlight\">عشی .</span> <font color=\"DarkGreen\"><b>[ع َ شا ]</font></b> (ع اِمص ) شبکوری . (ناظم الاطباء). عشاوة یا نابینایی . (از اقرب الموارد). و رجوع به عَشا شود.<br></font></div>'),
(183740, 'عشی', '<span class=\"hlight\">عشی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) عَش . شبکور، و آنکه در شب و روز هر دو بد بیند. (ناظم الاطباء). دارنده ٔ عشاوة. (از اقرب الموارد). رجوع به عشاوة شود.<br></font></div>'),
(183741, 'عشی', '<span class=\"hlight\">عشی .</span> <font color=\"DarkGreen\"><b>[ ع َ شی ی ]</font></b> (ع اِ) آخر روز. (منتهی الارب ). شبانگاه . (ترجمان القرآن جرجانی ). شبانگاه، أی از وقت نماز شام تا وقت نماز خفتن . (دهار). از زوال آفتاب تا صبح . (ناظم الاطباء). آخر روز، و گویند از نماز مغرب تا عتمة. و تصغیر آن عُشیّان است برخلاف مکبرآن، و گوئی آن تصغیر عَشیان است . و جمع آن عُشیّانات شود. مصغر آن را عُشَیشیان و جمعش را عُشَیشیانات نیز گفته اند. (از اقرب الموارد) (از منتهی الارب ) <span class=\"hlight\">:</span> و سبح بالعشی و الابکار (قرآن <span class=\"hlight\" dir=\"rtl\">٤١/٣</span>)؛ و ستایش کن در شبانگاه و بامداد. یسبحن بالعشی و الاشراق (قرآن <span class=\"hlight\" dir=\"rtl\">١٨/٣٨</span>)؛ ستایش میکنند او را در شبانگاه و هنگام طلوع آفتاب . و لاتطرد الذین یدعون ربهم بالغداة و العشی (قرآن <span class=\"hlight\" dir=\"rtl\">٥٢/٦</span>)؛ و مران کسانی را که در بامداد و شبانگاه خدای خود را دعا میکنند. فأوحی الیهم أن سبحوابکرةً و عشیاً (قرآن <span class=\"hlight\" dir=\"rtl\">١١/١٩</span>)؛ پس بدانان وحی کرد که بامداد و شبانگاه ستایش کنید. و له الحمد فی السماوات و الارض و عشیاً و حین تظهرون (قرآن <span class=\"hlight\" dir=\"rtl\">١٨/٣٠</span>)؛ او را ستایش است در آسمانها و زمین و شبانگاه و هنگامی که ظهر می کنید. النار یعرضون علیها غدواً و عشیاً (قرآن <span class=\"hlight\" dir=\"rtl\">٤٦/٤٠</span>)؛ در صبحگاه و شبانگاه بر آتش عرضه میشوند.<br>- <span class=\"hlight\">صلاتاالعشی </span> ؛ نماز ظهر و عصر. (منتهی الارب ) (از اقرب الموارد).<br><BR><font color=\"Blue\">◄</font> ابر.(منتهی الارب ). سحاب . (اقرب الموارد). ج، عَشایا، عَشیّات . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (ص ) بعیر عشی ؛ شتر که شب تا دیر چرد، و در مؤنث عشیة شود. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183742, 'عشی', '<span class=\"hlight\">عشی .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْی ْ ]</font></b> (ع اِ) طعام شبانگاهی . (منتهی الارب ). طعام عَشی ّ و شبانگاه . (از اقرب الموارد). ج، أعشیة. (ناظم الاطباء).<br></font></div>'),
(183743, 'عشی', '<span class=\"hlight\">عشی .</span> <font color=\"DarkGreen\"><b>[ ع ُش ْی ْ ]</font></b> (ع ص، اِ) ج ِ أعشی ̍. (ناظم الاطباء). رجوع به اعشی شود.<br></font></div>'),
(183744, 'عشی', '<span class=\"hlight\">عشی .</span> <font color=\"DarkGreen\"><b>[ ع ُش ْ شی ]</font></b> (ص نسبی ) منسوب به عُش ّ، و آن بطنی است از قضاعة. (از اللباب فی تهذیب الانساب ). و رجوع به عش (ابن لبید...) شود.<br></font></div>'),
(183745, 'عشی', '<span class=\"hlight\">عشی .</span> <font color=\"DarkGreen\"><b>[ ع َش ْی ْ ]</font></b> (ع مص ) طعام شبانگاهی خورانیدن کسی را. (از منتهی الارب ). عشاء و شام دادن کسی را. (از اقرب الموارد). عَشْو. و رجوع به عشو شود. <BR><font color=\"Blue\">◄</font> در شب قصد کردن کسی را. (از منتهی الارب ). عَشو. و رجوع به عشو شود. <BR><font color=\"Blue\">◄</font> به شب چرانیدن شتران را. (از ناظم الاطباء). عَشو.و رجوع به عشو شود. <BR><font color=\"Blue\">◄</font> مانند نابینا کار کردن . (از ناظم الاطباء). عَشو. و رجوع به عشو شود.<br></font></div>'),
(183746, 'عشیات', '<span class=\"hlight\">عشیات .</span> <font color=\"DarkGreen\"><b>[ ع َ شی یا ]</font></b> (ع اِ) ج ِ عَشی ّ. (منتهی الارب ). ج، عَشیّة. (اقرب الموارد). رجوع به عَشی ّ و عشیة شود.<br></font></div>'),
(183747, 'عشیان', '<span class=\"hlight\">عشیان .</span> <font color=\"DarkGreen\"><b>[ ع َش ْ ]</font></b> (ع ص ) طعام شبانگاهی خورنده . (منتهی الارب ). آنکه عشاء و شام خورده است . (از اقرب الموارد).<br></font></div>'),
(183748, 'عشیان', '<span class=\"hlight\">عشیان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َی ْ یا ]</font></b> (ع اِمصغر) مصغر عَشی ّ. (منتهی الارب ) (از اقرب الموارد). شام کوتاه . (ناظم الاطباء). رجوع به عَشی ّ شود.<br></font></div>'),
(183749, 'عشیانات', '<span class=\"hlight\">عشیانات .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َی ْ یا ]</font></b> (ع اِ) ج ِ عُشیّان که مصغر عَشی ّ است . (از منتهی الارب ) (از اقرب الموارد). رجوع به عَشی ّ شود.<br></font></div>'),
(183750, 'عشیب', '<span class=\"hlight\">عشیب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) مکان عشیب ؛ جای گیاهناک . (منتهی الارب ). محلی که عشب و علف در آن بسیار باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد کوتاه بالا. (منتهی الارب ). رجل قصیر. (از اقرب الموارد).<br></font></div>'),
(183751, 'عشیبة', '<span class=\"hlight\">عشیبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع ص ) مؤنث عشیب : أرض عشیبة؛ زمین که گیاهش نمایان و بسیار باشد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183752, 'عشیة', '<span class=\"hlight\">عشیة.</span> <font color=\"DarkGreen\"><b>[ ع َ شی ی َ ]</font></b> (ع اِ) آخر روز. (منتهی الارب ). شبانگاه . (زمخشری ) (دستور اللغة). شبانگاه، از نماز شام تا نماز خفتن . (دهار). به معنی «عشی ّ» است، چنانکه گویند: أتیته عشیة أمس یا عشی أمس، و برخی گویند عشیة مؤنث عشی است و عرب آن را به معنی عشی بکار میبرد، و برخی گویند عشیة واحد است و جمع آن عَشی ّ و عَشایا و عشیّات شود، و تصغیر آن عُشَیشیة است که جمعش عُشَیشیات شود. و منسوب به عشیة، عَشَوی ّ باشد. (از اقرب الموارد). وقتی است که هنوز هوا روشن است و میتوان به روشنائی روز چیزی خواندن . شب . شام . (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> کأنهم یوم یرونها لم یلبثوا الاّ عشیةً أو ضحاها (قرآن <span class=\"hlight\" dir=\"rtl\">٤٦/٧٩</span>)؛ گویی روزی که آن را می بینند درنگ نکرده اند جز یک شبانگاه یا چاشتگاه آن . قال حمید الطویل توفی الحسن <font color=\"DarkGreen\"><b>[ حسن بصری ]</font></b> عشیة الخمیس و أصبحنا یوم الجمعة و فرغنا من أمره و حملناه بعدصلاة الجمعة و دفناه . (ابن خلکان ). فتبعناه <font color=\"DarkGreen\"><b>[ أی تبعنا الثعلب ]</font></b> فی تلک العشیة (بعد الایاب عن الجامع، بعد صلاة العصر) الی أن صرنا الی درب قد أسماه بناحیة باب الشام ... و کان <font color=\"DarkGreen\"><b>[ الثعلب ]</font></b> فی تلک العشیة بیده دفتر ینظر فیه و قد شغله عما سواه . (معجم الادباء چ اروپا ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>). <BR><font color=\"Blue\">◄</font> ابر. (منتهی الارب ). سحاب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) مؤنث عشی . (منتهی الارب ): ناقة عشیة؛ ماده شتر که در شب تا دیرگاه چرا کند. (از اقرب الموارد). و رجوع به عَشی ّ شود.<br></font></div>'),
(183753, 'عشیر', '<span class=\"hlight\">عشیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ده یک . (منتهی الارب ) (دهار). دهم حصه از چیزی . (غیاث اللغات ). یک جزء از ده، مانند عُشر. (از اقرب الموارد). ج، أعشِراء (اقرب الموارد) (منتهی الارب )، عُشور. أعشار. (منتهی الارب ).<br>- <span class=\"hlight\">عُشر عشیر</span> ؛ یک جزء از صد جزء هر چیزی . و رجوع به عُشر شود.<br><BR><font color=\"Blue\">◄</font> قبیله . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خویش . (منتهی الارب ). خویش نزدیک . (دهار). خویشاوند.(غیاث اللغات ). قریب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> دوست . (منتهی الارب ). یار. (دهار). صدیق . (از اقرب الموارد). ج، عُشَراء. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شوی زن . (منتهی الارب ). زوج زن . (از اقرب الموارد). و از آن جمله است حدیث : اًنکن تکثرن اللعن و تکفرن العشیر، که منظور از عشیر زوج است، چه با هم معاشرت دارند. (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> معاشر. (منتهی الارب ) (اقرب الموارد). هم عشرت . (دهار).کسی که به کسی به یک جا زندگی کند. (غیاث اللغات ). همساز. سازگار <span class=\"hlight\">:</span> یدعو لمن ضرّه أقرب من نفعه لبئس المولی و لبئس العشیر (قرآن <span class=\"hlight\" dir=\"rtl\">١٣/٢٢</span>)؛ میخواندکسی را که زیانش نزدیکتر از سودش است و او بد خداوندگار و بد معاشری است . <BR><font color=\"Blue\">◄</font> ده یک حصه ٔ قفیز (جریب ) در حساب غله ٔ زمین . (منتهی الارب ). عشر قفیز، در حساب زمین . (از اقرب الموارد). عشر قفیز است، آن سی وشش ذراع مکسره باشد. (یادداشت مرحوم دهخدا). یکدهم قفیز یا <span class=\"hlight\" dir=\"rtl\">٣٦</span> ذرع مربع. (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> قفیزی عبارت از ده عشیر است و عشیری سی وشش گز است . (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١٠٩</span>). <BR><font color=\"Blue\">◄</font> آواز کفتار. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183754, 'عشیرا', '<span class=\"hlight\">عشیرا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِ) شعبه ای است از پرده های موسیقی . عشیران . عشرا. (از فرهنگ فارسی معین ). رجوع به عشیران شود.<br></font></div>'),
(183755, 'عشیران', '<span class=\"hlight\">عشیران .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِ) (اصطلاح موسیقی ) نام شعبه ای از بوسلیک، که یکی از پرده های موسیقی است . (از غیاث اللغات ). <BR><font color=\"Blue\">◄</font> شعبه ٔ پنجم از شعب بیست وچهارگانه ٔ موسیقی که قدما آن را جزو «حسینی » میدانستند، ولی حسینی امروزه از قطعات «نوا» است . (فرهنگ فارسی معین از مجمعالادوار). عشیرا. عشرا. و رجوع به عشیرا شود.<br></font></div>'),
(183756, 'عشیرت', '<span class=\"hlight\">عشیرت .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) عشیرة. خویشان . برادران قبیله . تبار. نزدیکان از جانب آباء. کس و کار. قبیله و تبارمردم <span class=\"hlight\">:</span> والی در ممالک ایران چهار است ... اول والی عربستان که به اعتبار سیادت و شجاعت و زیادتی ایل و عشیرت از والیهای دیگر بزرگتر و عظیم الشأن تر است . (تذکرةالملوک چ <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤</span>). و رجوع به عشیرة شود.<br></font></div>'),
(183757, 'عشیره زامل', '<span class=\"hlight\">عشیره زامل .</span><font color=\"DarkGreen\"><b>[ ع َ رِ م ِ ]</font></b> (اِخ ) دهی از دهستان چنانه بخش شوش شهرستان دزفول . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٧٠٠</span> تن . آب آن از چاه . محصول آن غلات دیمی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(183758, 'عشیش', '<span class=\"hlight\">عشیش .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) لاغر و باریک گردیدن، بمعنی مصدر عَشاشة است . (از ناظم الاطباء). رجوع به عشاشة شود.<br></font></div>'),
(183759, 'عشیشات', '<span class=\"hlight\">عشیشات .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َ ]</font></b> (ع اِ) ج ِ عُشَیشان . (منتهی الارب ). ج ِ، عُشَیشیة. (ناظم الاطباء). رجوع به عشیشان و عشیشیة شود.<br></font></div>'),
(183760, 'عشیشان', '<span class=\"hlight\">عشیشان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َ ]</font></b> (ع اِمصغر) مصغر عشی ّ. (منتهی الارب ). شام کوتاه . (ناظم الاطباء). و رجوع به عَشی ّ شود.<br></font></div>'),
(183761, 'عشیشیات', '<span class=\"hlight\">عشیشیات .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َ شیا ]</font></b> (ع اِ) ج ِ عُشَیشیة است که تصغیر عَشیّة باشد. (از اقرب الموارد). رجوع به عشیة شود.<br></font></div>'),
(183762, 'عشیشیان', '<span class=\"hlight\">عشیشیان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َ شیا ]</font></b> (ع اِمصغر) مصغر عَشی ّ. (منتهی الارب ) (اقرب الموارد). شام کوتاه . (ناظم الاطباء). رجوع به عَشی ّ شود.<br></font></div>'),
(183763, 'عشیشیانات', '<span class=\"hlight\">عشیشیانات .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َ شیا ]</font></b> (ع اِ) ج ِ عُشیشیان، که مصغر عَشی ّ است . (از منتهی الارب ) (از اقرب الموارد). رجوع به عَشی ّ شود.<br></font></div>'),
(183764, 'عشیشیة', '<span class=\"hlight\">عشیشیة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ش َ شی َ ]</font></b> (ع اِمصغر) مصغر عَشی ّ. (منتهی الارب ). شام کوتاه . ج، عشیشیات . (از ناظم الاطباء). مصغر عَشیّة است و جمعش عشیشیات شود. (از اقرب الموارد). رجوع به عشی و عشیة شود.<br></font></div>'),
(183765, 'عشیق', '<span class=\"hlight\">عشیق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) عشق ورزنده و عاشق . (فرهنگ فارسی معین ). گویند: فلان عشیق و هی عشیقته ؛ یعنی نسبت بهم عشق میورزند. (از منتهی الارب ) <span class=\"hlight\">:</span> <br>ورنه باشد آن تو بنگر این فریق <br>بر غم و رنجندمفتون و عشیق .<br> <font color=\"Red\">مولوی .</font><br>مولعیم اندر سخنهای دقیق <br>بر گرهها باز کردن ما عشیق .<br><font color=\"Red\">مولوی .</font><br>چه محل دارد به پیش آن عشیق <br>لعل و یاقوت و زمرد یا عقیق .<br> <font color=\"Red\">مولوی .</font><br>زآنکه او سنگ سیه بد این عقیق <br>آن عدوی نور بود و این عشیق .<br><font color=\"Red\">مولوی .</font><br><BR><font color=\"Blue\">◄</font> معشوق . محبوب . حبیب . دوست <span class=\"hlight\">:</span> <br>غرابا مزن بیشتر زین نعیقا<br>که مهجور کردی مرا از عشیقا<br>نعیق تو بسیار و ما را عشیقی <br>نباید به یک دوست چندین نعیقا.<br><font color=\"Red\">منوچهری .</font><br></font></div>'),
(183766, 'عشیق', '<span class=\"hlight\">عشیق .</span> <font color=\"DarkGreen\"><b>[ ع ِش ْ شی ]</font></b> (ع ص ) بسیار عشق آرنده . (منتهی الارب ). کثیرالعشق . (اقرب الموارد).<br></font></div>'),
(183767, 'عص', '<span class=\"hlight\">عص .</span> <font color=\"DarkGreen\"><b>[ ع َص ص ]</font></b> (ع مص ) سخت گردیدن و درشت شدن . (از منتهی الارب ). سخت و شدید شدن . (از اقرب الموارد). عَصَص . و رجوع به عصص شود.<br></font></div>'),
(183768, 'عص', '<span class=\"hlight\">عص .</span> <font color=\"DarkGreen\"><b>[ ع َص ص ]</font></b> (ع اِ) بن هر چیزی و بیخ و نژاد آن . (منتهی الارب ). اصل، چنانکه گویند: هو کریم العص . (از اقرب الموارد).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(183769, 'عصا', '<span class=\"hlight\">عصا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) چوب . (منتهی الارب ). عود. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> چوب دستی، مؤنث آید. (منتهی الارب ) (دهار) (غیاث اللغات ) (ترجمان القرآن جرجانی ). نوعی از چوبدستی متوسط در سطبری و باریکی که بعضی از آن سرکج بود، و در فارسی بزیادت یاء (عصای ) نیز استعمال کنند. (ازآنندراج ) چوبدستی که در موقع راه رفتن بدان تکیه کنند. (فرهنگ فارسی معین ). چوبی که بر آن تکیه کنند و بوسیله ٔ آن بزنند، و تثنیه ٔ آن عَصَوان شود. (از اقرب الموارد). از آلات سلاح است، و آن چوبی باشد سودمند در کارزار و فایده ٔ آن چون فایده ٔ دبوس و چماق است . (از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٥</span>). ج، أعص، أعصاء، عُصی ّ، عَصی ّ. (منتهی الارب ) (اقرب الموارد). پاده . پاشو. تختله . تخله . ختور. دستوار. دستواره . سنان . قرضوف . کتک .منساءة. منساة. هادیة. هرباس <span class=\"hlight\">:</span> اضرب بعصاک الحجر (قرآن <span class=\"hlight\" dir=\"rtl\">٦٠/٢</span> و <span class=\"hlight\" dir=\"rtl\">١٦٠/٧</span>)؛ با چوبدست خود آن سنگ را بزن . فأوحینا اًلی موسی أن اضرب بعصاک البحر (قرآن <span class=\"hlight\" dir=\"rtl\">٦٣/٢٦</span>)؛ و به موسی وحی کردیم که با چوبدست خود دریا را بزن . قال هی عصای أتوکاء علیها (قرآن <span class=\"hlight\" dir=\"rtl\">١٨/٢٠</span>)؛ گفت آن چوبدست من است که بر آن تکیه میکنم . و ألق عصاک (قرآن <span class=\"hlight\" dir=\"rtl\">١١٧/٧</span> و <span class=\"hlight\" dir=\"rtl\">١٠/٢٧</span>)؛ و بینداز عصا و چوبدست خود را. فألقی عصاه فاذا هی ثعبان مبین (قرآن <span class=\"hlight\" dir=\"rtl\">١٠٧/٧</span>و <span class=\"hlight\" dir=\"rtl\">٣٢/٢٦</span>)، پس عصای خود را انداخت و ناگهان آن به اژدهائی آشکار تبدیل شد. فألقی موسی عصاه فاذا هی تلقف ما یأفکون (قرآن <span class=\"hlight\" dir=\"rtl\">٤٥/٢٦</span>)؛ و موسی عصای خود را انداخت و ناگهان آنچه را آنان به دروغ می نمودند؛ ربود.<br>بشد پیرمردی عصائی به دست <br>بدو گفت کای شاه یزدان پرست .<br> <font color=\"Red\">فردوسی .</font><br>زمام او طریق او و راهبر<br>ستام او و دست او عصای او.<br> <font color=\"Red\">منوچهری .</font><br>باز بر پشت و قفا و سفت سیلی و عصا.<br> <font color=\"Red\">عسجدی .</font><br>گفتم بیاریدش، درآمد و خالی خواست و این عصایی که داشت برشکافت و رقعتی خرد... برون گرفت و به من داد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٢٦</span>).<br>کز عصا مار توانست همی کرد کلیم .<br> <font color=\"Red\">(از تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٩</span>).</font><br>کلیم آمده خود با نشان معجز حق <br>عصا و لوح و کلام و کف و رخ انور.<br> <font color=\"Red\">ناصرخسرو.</font><br>بی عصا رفتن نباید چون همی بینی که سگ <br>مر غریبان را همی جامه بدرّد بی عصا.<br> <font color=\"Red\">ناصرخسرو.</font><br>فردا به عصا همیت باید رفت <br>امروز چنین چو کبک چه خْرامی ؟<br> <font color=\"Red\">ناصرخسرو.</font><br>آن گوی مر مرا که توانی ز من شنود<br>این پند مر تو را به ره راست چون عصاست .<br> <font color=\"Red\">ناصرخسرو.</font><br>چون عصا خشک، و رفت نتواند<br>در دو گام ای عجب مگر به عصا.<br> <font color=\"Red\">مسعودسعد.</font><br>من اهل مزاح و ضحکه و رنجم <br>مرد سفر و عصا و انبانم .<br> <font color=\"Red\">مسعودسعد.</font><br>جز در کف کلیم عصا کی شود چو مار<br>جز در انامل تو قلم کی شود صدف .<br> <font color=\"Red\">معزی .</font><br>صاحب دلق و عصا چون خضر و چون کلیم <br>گنج روان زیر دلق مار نهان در عصا.<br> <font color=\"Red\">خاقانی .</font><br>گریزد ز شکل عصا مار و گوید<br>عصاشکلم و از عصا می گریزم .<br> <font color=\"Red\">خاقانی .</font><br>همه فرعون و گرگ پیشه شدند<br>من عصا و شبان نمی یابم .<br> <font color=\"Red\">خاقانی .</font><br>بدل به رجوع تو کان پیر دین را<br>بجز استقامت عصائی نیابی .<br> <font color=\"Red\">خاقانی .</font><br>دلق و عصا را بسوز کین نه نکو مذهبیست <br>از پی دیدار حق دلق و عصا ساختن .<br> <font color=\"Red\">عطار.</font><br>پیری که ز جای خویش نتواند خاست <br>الاّ به عصا، کیَش عصا برخیزد.<br> <font color=\"Red\">(گلستان ).</font><br>تکیه چه آری به عصای کسان <br>زنده نشد کس به بقای کسان .<br> <font color=\"Red\">امیرخسرو.</font><br>رندیست که اسباب وی آسان ندهد دست <br>سرمایه ٔ تزویر عصائی و ردائی .<br> <font color=\"Red\">صائب .</font><br>گذشته اند ز چه بی عصا سبک پایان <br>تو میروی به ته چاه بی عصای که چه .<br> <font color=\"Red\">صائب (از آنندراج ).</font><br>که کور را خطری همچو بی عصائی نیست .<br> <font color=\"Red\">وحید قزوینی .</font><br>اعتصاء؛ عصا در دست گرفتن ازبهر تکیه . (تاج المصادر بیهقی ). تعصیة؛ عصا دادن کسی را. (منتهی الارب ). صم، عفج ؛ به عصا زدن . (تاج المصادر بیهقی ). عُکّازة؛ عصا با آهن (دهار)، عصای با سنان . مِعصال ؛ عصای سرکج که بدان شاخه های درخت را گیرند. مِنجدة؛ عصای سبک که بدان ستور رانند. مَوبِل، مَیبِل، وَبیل، وَبیلة؛ عصای سطبر. هِراوة؛ عصای سطبر. چوب دستی گنده . (از منتهی الارب ).<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عصا الجبان أطول </span> ؛ چوب دست ترسنده و بددل بلندتر باشد. (امثال و حکم دهخدا).<br>جوی بازدارد بلای درشت <br> <span class=\"hlight\">عصائی شنیدی که عوجی بکشت </span> ؟<br> <font color=\"Red\">سعدی .</font><br>نظیر: یک کلوج پنبه هم آدم میکشد.یک دست خیر است یک دست شر. (امثال و حکم دهخدا).<br> <span class=\"hlight\">عصای پیر بجای پیر</span> . (مجموعه ٔ امثال فارسی چ هند).<br> <span class=\"hlight\">عصای حضرت خضر به آن خورده </span> ؛ همیشه هست و جاودانی است . آن را در مورد اشخاص سالدار و هر چیز که عمری دراز از آن گذشته باشد گویند. (از فرهنگ عوام ).<br> <span class=\"hlight\">اینجاموش با عصا راه میرود</span> ؛ با عصا راه رفتن مطلقاً حزم و احتیاط فراوان بکار بردن است . (امثال و حکم دهخدا). و رجوع به «دست به عصا راه رفتن » در ترکیبات شود.<br> <span class=\"hlight\">صد سر را کلاهست و صد کور را عصا</span> ؛ نهایت گربز و یا کاریست . (امثال و حکم دهخدا).<br>الناس عبیدالعصا؛ مردم بردگان عصا هستند، منظور اینست که از کسی که آنها را بیازارد میترسند و از او اطاعت می کنند. (از اقرب الموارد).<br> <span class=\"hlight\">لیس فی العصا سیر</span> ؛ مثلی است در مورد شخصی که بر آنچه میخواهد توانایی نداشته باشد. (از اقرب الموارد).<br> <span class=\"hlight\">مار بمیرد و عصا نشکند</span> . (مثل هندی، از شاهد صادق ).<br>- <span class=\"hlight\">دست به عصا رفتن (راه رفتن )</span> ؛ کنایه است از با احتیاط و حذر بسیار در کاری پیش رفتن . نهایت احتیاط درگفتار یا کردار خود کردن . (یادداشت مرحوم دهخدا). ورجوع به «اینجا موش با عصا راه میرود» در امثال شود.<br>- <span class=\"hlight\">شق عصا کردن، شق عصای مسلمین کردن </span> ؛ خلاف آوردن . (امثال و حکم دهخدا). و رجوع به شق العصا و عصا شود.<br>- <span class=\"hlight\">عصا برگرفتن </span> ؛ عصا به دست گرفتن <span class=\"hlight\">:</span> <br>عصا برگرفتن نه معجز بود<br>همی اژدها کرد بایدعصا.<br> <font color=\"Red\">غضائری .</font><br>- <span class=\"hlight\">عصا بَقّاریّة</span> ؛ عصای سخت . (منتهی الارب ).<br>- <span class=\"hlight\">عصا غورت دادن </span> ؛ فروبردن عصا به دهان . (فرهنگ فارسی معین ).<br>- <BR><font color=\"Blue\">◄</font> کنایه از شق و رق راه رفتن است . (فرهنگ فارسی معین ). با قد کشیده و گردن آخته حرکت کردن .<br>- <span class=\"hlight\">عصاموسی </span> ؛ عصاالراعی . (فهرست مخزن الادویة) رجوع به ماده ٔ عصاالراعی شود.<br>- <span class=\"hlight\">عصا و پاافزار پیش نهادن </span> ؛ کنایه از تهیه ٔ سفر کردن و عازم سفر بودن است . (آنندراج ).<br>- <span class=\"hlight\">عصای آفتاب </span> ؛ کنایه از خطوط شعاعی آفتاب است . (از آنندراج ) <span class=\"hlight\">:</span> <br>ز نور رای تو روشن شده ست روی سپهر<br>وگرنه کی رَوَدی آفتاب جز به عصا.<br><font color=\"Red\">انوری .</font><br>- <span class=\"hlight\">عصای پیری </span> ؛ کنایه از فرزند خلف . (ازفرهنگ فارسی معین ). فرزند برومندی که در موقع کهولت و پیری به درد شخص بخورد. (فرهنگ عوام ). یار و یاوردوران سالخوردگی کسی از فرزند و جز او <span class=\"hlight\">:</span> <br>ادیب عشق تو در غورگی مویزم کرد<br>عصای پیری من بود چوب حرفی من .<br> <font color=\"Red\">تأثیر (از آنندراج ).</font><br>- <span class=\"hlight\">عصای سه حرفی </span> ؛ از قبیل چوب سه حرفی و چوب حرفی است، و آن چوبی باریک است که در دست اطفال دهند تا آن را روی سطور کتاب گذاشته بخوانند برای محافظت سطور کتاب از آفت انگشت . (از آنندراج ) <span class=\"hlight\">:</span> <br>نموده اند قلم را عصای سه حرفی <br>بودطبیعت ایشان ز بس که کورسواد.<br> <font color=\"Red\">میر افضل ثابت (از آنندراج ).</font><br>این طایفه چون کورسوادان جهان <br>محتاج عصای سه حرفی اند همه .<br> <font color=\"Red\">محمدسعید اشرف (از آنندراج ).</font><br>- <span class=\"hlight\">عصای کلیم، عصای موسی، عصای دست موسی </span> ؛ اشاره به چوبدست موسای نبی (ع ) است که بفرمان خداوند تبدیل به اژدها شد. و از معجزات او بشمار میرفت <span class=\"hlight\">:</span> <br>کاژدهائی شد این عصای کلیم . (از تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٨٨</span>).<br>حیدر عصای موسی دور است و تازه روی <br>اسلام را به موسی دور از عصا شده ست .<br> <font color=\"Red\">ناصرخسرو.</font><br>حیدر زی ما عصای موسی دور است <br>موسی ما را جز او که کرد عصائی .<br> <font color=\"Red\">ناصرخسرو.</font><br>عصای کلیم ار به دستم بدی <br>به چوبش ادب را ادب کردمی .<br> <font color=\"Red\">خاقانی .</font><br>به دست آرم عصای دست موسی <br>بسازم زآن عصا شکل چلیپا.<br> <font color=\"Red\">خاقانی .</font><br>عصای کلیمند بسیارخوار<br>بظاهر نمایند زرد و نزار.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">رأس العصا</span> ؛ به کسی گویند که سر کوچک و خردی داشته باشد. (از اقرب الموارد).<br><BR><font color=\"Blue\">◄</font> دسته . هراوة: عصاالرمح ؛ دسته ٔ نیزه . عصاالفأس ؛ دسته ٔ تیشه . (از اقرب الموارد).<br>- <span class=\"hlight\">عصای آسیا</span> ؛ میل آسیا که آن را به دست می گیرند و آسیا را می گردانند. (آنندراج ) <span class=\"hlight\">:</span> <br>بود آوازه ٔ دولت ز روزی اهل دنیا را<br>صدای کوس اقبال از عصای آسیا خیزد.<br> <font color=\"Red\">سراج المحققین (از آنندراج ).</font><br> <BR><font color=\"Blue\">◄</font> در تداول فارسی، چماق . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ألقی عصاه ؛ رسید به جای خود و اقامت کرد، یا میخ در زمین فروکوفت و خیمه زد (منتهی الارب )، یعنی به موضع و جای خود رسید و اقامت گزید و آرام گرفت و سفر را ترک گفت، و آن مثل است . (از اقرب الموارد). و رجوع به ماده ٔ عصاالقرار شود. <BR><font color=\"Blue\">◄</font> اًنه لضعیف العصا؛ یعنی او نیکوچراننده ٔ شتران است . و هو لیّن العصا؛ یعنی نرم خو و نیکو سیاست کننده ٔ شتران است، یا سست سیاست کم زننده شتران را. (منتهی الارب ). گویند: راع لیّن العصا و ضعیف العصا؛ یعنی چوپان مداراکننده و نرم و خوب سیاست . و راع شدیدالعصا و صُلب العصا؛ یعنی چوپان عنیف و سخت گیر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> لاترفع عصاک عن أهلک ؛ منظور ادب است، یعنی از تأدیب خانواده ٔ خود غافل مباش . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> هو لایضع عصاه عن عاتقه ؛ یعنی او همواره اهل خود را ادب میدهد، یا پیوسته در سفر میباشد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> قشر له العصا؛ یعنی آنچه در دل داشت برای او آشکار ساخت . <BR><font color=\"Blue\">◄</font> فلان یصلی عصا فلان ؛ یعنی امر اورا اداره و تدبیر میکند. <BR><font color=\"Blue\">◄</font> قرع له العصا؛ او را متوجه و متنبه ساخت . و از آن جمله است که درحق کسی که با رفیق خود موافقت کند و برابری نماید گویند «مثلک لاتقرع له العصا»، و نیز در مورد کسی که هرگاه او را متنبه کنند متوجه شود، گویند «اًن العصاقرعت لذی الحلم ». (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زبان . (منتهی الارب ). لسان . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> استخوان ساق . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مِعجَر و سربند زنان . (منتهی الارب ). خِمار که ازبرای زن است . <BR><font color=\"Blue\">◄</font> اجتماع و ائتلاف . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گروه مسلمانان . (منتهی الارب ). جماعت اسلام . (از اقرب الموارد).<br>- <span class=\"hlight\">شق ّالعصا</span> ؛ خلاف ورزیدن جماعتی از اسلام، و از آن جمله است که در مورد خوارج گویند: شقّوا عصا المسلمین، که منظور اجماع و اتفاق مسلمانان است . و در حدیث است : «اًیاک و قتیل العصا»؛ یعنی زنهار که قاتل یا مقتول باشی در شق عصای مسلمین .(از منتهی الارب ). و رجوع به ترکیب «شق عصا کردن » شود.<br>انشقت العصا؛ یعنی اختلاف افتاد. (از منتهی الارب ) (از اقرب الموارد).<br> <BR><font color=\"Blue\">◄</font> آلتی که در گرفتن ارتفاع بکار میبرند. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> استخوان جناح . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> صیغه ٔ ماضی است از عصیان بمعنی بی فرمانی کرد، و اشاره است به آیت : «و عصی آدم ربه فغوی » (قرآن <span class=\"hlight\" dir=\"rtl\">١٢١/٢٠</span>). (از غیاث اللغات ) (از آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از آلت تناسل است . (از آنندراج )(از غیاث اللغات ) (از ناظم الاطباء) <span class=\"hlight\">:</span> <br>پیری که ز جای خویش نتواند خاست <br>الاّ به عصا، کیَش عصا برخیزد.<br> <font color=\"Red\">سعدی (گلستان ).</font><br>چنانکه رسم عروسی بود مهیا کرد<br>ولی به حمله ٔ اول عصای شیخ بخفت .<br> <font color=\"Red\">سعدی (گلستان ).</font><br><BR><font color=\"Blue\">◄</font> آلت فلکی که کره و اسطرلاب را در خطی نهاده اند، و واضع آن شیخ شرف الدین طوسی است . (از تاریخ ابن خلکان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٠</span>).<br></font></div>'),
(183770, 'عصا', '<span class=\"hlight\">عصا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) جایگاهی است بر ساحل فرات بین هیت و رحبة، و اسب جذیمه ٔ ابرش بدانجا منسوب است . (از معجم البلدان ).<br>- <span class=\"hlight\">یوم العصاء و خیفق </span> ؛ از جنگهای عرب است . (از معجم البلدان ).<br></font></div>'),
(183771, 'عصا', '<span class=\"hlight\">عصا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام اسب جذیمة الابرش است . (از منتهی الارب ). نام اسبی است ازآن جذیمة الابرش که آنقدر از او سواری گرفت تا نیرویی در وی نماند. و عُصیّةمادر آن اسب باشد، و در مثل گویند: اًن العصا من العصیة؛ یعنی اسب عصا از مادیان عصیة زاده است، و منظور اینکه امور زاده ٔ یکدیگرند. (از اقرب الموارد).<br></font></div>'),
(183772, 'عصا', '<span class=\"hlight\">عصا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) عصا به دست گرفتن . (از ناظم الاطباء) (از اقرب الموارد). عصا برگرفتن . <BR><font color=\"Blue\">◄</font> مانند چوب دستی گرفتن شمشیر را، و به شمشیر زدن کسی را به ضرب چوب دستی . (از منتهی الارب ). گرفتن شمشیر را مانند عصا، یا زدن با شمشیر مانند زدن به عصا. (از اقرب الموارد). ریشه ٔ آن هم واوی و هم یایی آمده است، و برخی گویند واوی آن در ضرب شمشیر، و یائی آن در ضرب عصا بکار رود، و بعضی عکس آن را ذکر کرده اند، و برخی هر دو حالت را در هر دو معنی مستعمل دانسته اند. (از اقرب الموارد) (از منتهی الارب ).<br></font></div>'),
(183773, 'عصا زدن', '<span class=\"hlight\">عصا زدن .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ دَ ]</font></b> (مص مرکب ) با تکیه دادن سر عصا بر زمین حرکت کردن . رفتن با تکیه دادن عصا بر زمین .<br></font></div>'),
(183774, 'عصاالراعی', '<span class=\"hlight\">عصاالراعی .</span>  <font color=\"DarkGreen\"><b>[ ع َ صَرْ را ]</font></b> (ع اِ مرکب ) درخت بطباط. (از اقرب الموارد). کبیر و صغیر می باشد و کبیر نر و صغیر ماده است و بفارسی کبیر را سرخ مرز نامند. تخم و ساقش سرخ و برگش مایل به بنفشی و در باغها بسیار است . و صغیر او را در تنکابن خاک تره گویند، برگ و ساقش سبز و کوچک تر از کبیر، و تخمش سفید و گویاخاکستر بر برگهای او پاشیده اند و تخم هر دو قسم او در زیر برگها و انبوه . و در افعال، کبیر او از صغیر قوی تر، و در اول خشک و در سیُم سردند. (از تحفه ٔ حکیم مؤمن ). داروئی است . (نزهة القلوب ). عصافیرالراعی .(تذکره ٔ ضریر انطاکی ). عصا موسی . (فهرست مخزن الادویة). هزاربَندَک . (بحر الجواهر). برشیان دارو. شبطباط.سطیاط. (الابنیة). جُنجُر. نوعی صدپیوند که گیاهی است، و آن را هفت بند نیز نامند. (فرهنگ فارسی معین ).<br></font></div>'),
(183775, 'عصاالقرار', '<span class=\"hlight\">عصاالقرار.</span> <font color=\"DarkGreen\"><b>[ ع َ صَل ْ ق َ ]</font></b> (ع اِ مرکب ) عصای قرار: عصاالقرار در جایی انداختن ؛ کنایه از اقامت کردن در جایی و ترک سفر نمودن است، زیرا مسافر چون به منزل فرودآید عصای سفر به یک سو اندازد و از رنج راه بیاساید. (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> و اینک چهار سال شد که عصاالقرار دراین دارالقرار... انداخته ام . (نفثةالمصدور ص <span class=\"hlight\" dir=\"rtl\">١١٦</span>).<br></font></div>'),
(183776, 'عصاب', '<span class=\"hlight\">عصاب .</span> <font color=\"DarkGreen\"><b>[ ع َص ْ صا ]</font></b> (ع ص ) ریسمان بر و ریسنده . (از منتهی الارب ). ریسمان گر و ریسنده . (آنندراج ). بسیار ریسنده . (ناظم الاطباء). غزّال . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ریسمان فروش . (ناظم الاطباء). گلابه ریسمان فروش . (دهار). <BR><font color=\"Blue\">◄</font> کلاه فروش . (ملخص اللغات حسن خطیب ).<br></font></div>'),
(183777, 'عصاب', '<span class=\"hlight\">عصاب .</span> <font color=\"DarkGreen\"><b>[ ع َص ْ صا ]</font></b> (اِخ ) نام او حسن بن عبداﷲبن میسره ٔ عصاب است . وی محدث بود و از نافع مولای ابن عمر روایت دارد. و فضل بن موسی سینانی از او روایت کرده است . (از اللباب فی تهذیب الانساب ) (از منتهی الارب ).<br></font></div>'),
(183778, 'عصاب', '<span class=\"hlight\">عصاب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) به پنجه گرفتن چیزی را. (منتهی الارب ). گرفتن . (از اقرب الموارد). عَصب . و رجوع به عصب شود. <BR><font color=\"Blue\">◄</font> فرض و واجب کردن : عصب اﷲ بکم کذا. (از اقرب الموارد). عَصب . و رجوع به عصب شود.<br></font></div>'),
(183779, 'عصاب', '<span class=\"hlight\">عصاب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b>(ع اِ) آنچه بدان بدن بسته شود جز سر. <BR><font color=\"Blue\">◄</font> سربند. (منتهی الارب ). سربند و عمامه . (ناظم الاطباء). آنچه بر سر بسته شود از قبیل مندیل و غیره . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> رسن که ران های ناقه را بندند برای دوشیدن . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183780, 'عصاب', '<span class=\"hlight\">عصاب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) اسم بربری شیطرج است . (تحفه ٔ حکیم مؤمن ) (از فهرست مخزن الادویة). به لغت بربری دوائی است که آن را شاهتره گویند و معرب آن شیطرج باشد، وبه یونانی لبیدیون خوانند. اگر دندان طرف راست درد کند قدری از آن به دست چپ باید گرفت و دست را در زیروی بجانبی که دندان درد میکند باید گذاشت، درد را ساکن کند، و همچنین برعکس . (برهان قاطع) (آنندراج ).<br></font></div>'),
(183781, 'عصابات', '<span class=\"hlight\">عصابات .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) در تداول امروز عرب زبانان، ج ِ عِصابة است به معنی گروه از مردمان، و اصطلاحاً بر چریکها اطلاق شود.<br>- <span class=\"hlight\">حرب العصابات </span> ؛ جنگهای چریکی .<br></font></div>'),
(183782, 'عصابة', '<span class=\"hlight\">عصابة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ب َ ]</font></b> (ع اِ) آنچه بدان بسته شود، و سربندو دستار سر. (منتهی الارب ). آنچه بسته شود از مندیل و عمامه و غیره . (از اقرب الموارد). سربند و دستار. (دهار). پیچه بند. (صحاح الفرس ). نوعی از جامه که بدان سر بندند. (غیاث اللغات ). سربند. (مهذب الاسماء). پیشانی بند<font color=\"DarkGreen\"><b>[ <span class=\"hlight\">:</span> انوشیروان ]</font></b> هوذه را بسیار چیز داد و خلعتها داد و یکی عصابه دادش از زر و گوهر ویاقوت و مروارید اندروی نشانده تا بر پیشانی بربندد. (ترجمه ٔ طبری بلعمی ). کمان اوهرز هیچکس زه نتوانستی کردن، پس چون کمان بزه کرد عصابه بخواست و بر پیشانی بست، و چشمش ضعیف شده بود. (ترجمه ٔ طبری بلعمی ).<br>سوسن سیمین وقایه برگرفت از پیش روی <br>نرگس مشکین عصابه برگرفت از پیش سر.<br> <font color=\"Red\">فرخی (از آنندراج ).</font><br>بر یاسمین عصابه ٔ زرّ مرصع است <br>بر ارغوان طویله ٔ یاقوت معدنی .<br> <font color=\"Red\">منوچهری .</font><br>و اسود را کشتند و آگاهی به رسول آمد و شاد گشت و از بیماری قوت گرفت و از خانه بیرون آمد، عصابه برپیشانی بست از دردسر. (قصص الانبیاء ص <span class=\"hlight\" dir=\"rtl\">٢٣٤</span>). عصابه ٔ عصیان به پیشانی بازبستند و شهری که دارالاماره بود به دست بازگرفتند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span>). تقدیر آسمانی عصابه ٔ ادبار به روی او بازبست . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٤٢</span>). افعال ایشان عصابه ٔ ادبار بر چشم همه بست . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٧٤</span>).<br>چو شد بسته نقش نخستین طراز<br>عصابه ز چشم خرد کرد باز.<br> <font color=\"Red\">نظامی .</font><br>آن سر که عصابه های زر بست <br>خود را به عصابه ٔ دگربست .<br> <font color=\"Red\">نظامی .</font><br>آفتاب ار بر او فکندی نور<br>دیده را در عصابه بستی حور.<br> <font color=\"Red\">نظامی .</font><br>وقتی در بادیه میرفتم مجرد، پیرزنی دیدم که می آمد عصابه ای بربسته و عصائی در دست گرفته، گفتم مگر از قافله بازمانده است . (تذکرةالاولیاء عطار). نقلست که وقتی یکی را دید که عصابه ای بر سر بسته بود، گفت چرا عصابه بسته ای، گفت سرم درد میکند، رابعه گفت ... سی سال تن درست داشتی هرگز عصابه ٔ شکر بر سر نبستی، به یک شب که دردسر داد عصابه ٔ شکایت می بندی . (تذکرةالاولیاء عطار). عصائی در دست و عصابه ای بر سر. (مجالس سعدی ص <span class=\"hlight\" dir=\"rtl\">١٥</span>). پیشانی از نیمه ٔ عصابه کلاه از مروحه نخودی و گرهی چون چین قبا در او. (نظام قاری ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br>قطیفه ز خیلش یکی چتردار<br>ز والا عصابه علم زرنگار.<br> <font color=\"Red\">نظام قاری .</font><br>اکلیل ؛ عصابه مانندی است مرصع به جواهر. (منتهی الارب ). تعصیب ؛ عصابه به سر بازبستن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> رگ بند. (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> قطعه چرم مکعبی است که در وقت نماز بر پیشانی یابازوی چپ بندند. و این قطعه چرم دارای چهار آیه است که هر آیه را بر قطعه ای از پوست یا کاغذ نوشته در آنجا قرار میدهند. (قاموس کتاب مقدس ). <BR><font color=\"Blue\">◄</font> نوعی از ابر سرخ که در خشک سال حادث گردد. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> از ده تا چهل عدداز مرد و اسب و مرغ . (منتهی الارب ). جماعت از مردان و اسبان و پرندگان، و گویند ده عدد از آنها، و گویندمابین ده تا چهل . (از اقرب الموارد). ج، عَصائب . (منتهی الارب ) (اقرب الموارد) <span class=\"hlight\">:</span> در میان عصابه ای از رجاله ٔ خویش روی به مخارم کوهها نهاده . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٥٩</span>). <BR><font color=\"Blue\">◄</font> دردی که در دو ابرو پیدا آید متصل به بالای دو ابرو و به استخوان مأق . (یادداشت مرحوم دهخدا).<br></font></div>'),
(183783, 'عصات', '<span class=\"hlight\">عصات .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) عصاة. ج ِ عاصی . (غیاث اللغات ). سرکشان و نافرمانان و یاغیان . رجوع به عاصی و عصاة شود <span class=\"hlight\">:</span> <br>کی بدیدندی عصات آن معجزات <br>معصیت طاعت شد ای قوم عصات .<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(183784, 'عصاثج', '<span class=\"hlight\">عصاثج .</span> <font color=\"DarkGreen\"><b>[ ع ُ ث ِ ]</font></b> (ع ص ) سخت و درشت و سطبر فربه . (منتهی الارب ).<br></font></div>'),
(183785, 'عصار', '<span class=\"hlight\">عصار.</span> <font color=\"DarkGreen\"><b>[ ع َص ْ صا ]</font></b> (ع ص ) شپلنده ٔ انگور و جز آن . (منتهی الارب ). روغنگر. (غیاث اللغات ). منسوب به عصر که روغن کشی از حبوب را میرساند. (از الانساب سمعانی ) (آنندراج ). روغنگر و کسی که از بذور مانند کرچک و کنجدو جز آن روغن گیرد. (ناظم الاطباء). شیره گر. (مهذب الاسماء). روغن گیر. روغن کش . زیات . افشرگر <span class=\"hlight\">:</span> <br>چو گاوی که عصار چشمش ببست <br>دوان تا بشب شب همانجا که هست .<br> <font color=\"Red\">سعدی .</font><br>سر گاو عصاراز آن در کَه است <br>که از کنجدش ریسمان کوته است .<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> پادشاه و ملک ملجاء و پناهگاه . (از اقرب الموارد). ملک و ملجاء، و آن لقب گروهی است . (از متن اللغة).<br></font></div>'),
(183786, 'عصار', '<span class=\"hlight\">عصار.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) غبار بسیار. (منتهی الارب ). غبار و گرد شدید. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گند. (منتهی الارب ). گند، و تیز بی صدا و بدبو. (ناظم الاطباء). فساء. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> حین و وقت : جاء عَلَی َّ عصار من الدهر؛ وقتی از روزگار بر من آمد. <BR><font color=\"Blue\">◄</font> (اِخ ) مخلاف و روستائی است در یمن . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183787, 'عصار', '<span class=\"hlight\">عصار.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b>(ع اِ) آنچه به فشاردن برآید مانند آب و مایع و جز آن . (منتهی الارب ). آنچه خارج شود از آنچه فشرده شود.(از اقرب الموارد). عُصارة. و رجوع به عصارة شود.<br></font></div>'),
(183788, 'عصار', '<span class=\"hlight\">عصار.</span> <font color=\"DarkGreen\"><b>[ ع َص ْ صا ]</font></b> (اِخ ) نام محمدبن عبداﷲبن حسن عصار جرجانی، مکنی به ابوعبداﷲ است . وی از محدثان و از همراهان احمدبن حنبل در سفرش به یمن بوده است . و اولین شخصی است که مذهب حدیث را در جرجان اظهار کرد. عصار از عبدالرزاق روایت کرده است و ابواسحاق عمران بن موسی سختیانی از او روایت دارد. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(183789, 'عصار تبریزی', '<span class=\"hlight\">عصار تبریزی .</span> <font color=\"DarkGreen\"><b>[ ع َص ْ صا رِ ت َ ]</font></b> (اِخ ) خواجه محمد عصار تبریزی . از مداحان شیخ اویس ایلکانی است، و غیر از این پادشاه امرای دیگر را نیز مدح گفته بود و قصاید بسیار در مدیحه داشت و عاقبت از این طرزسخن سرائی ملول شد و انزوا اختیار کرد و در آن حال بخواهش دوستی یک مثنوی به وزن خسرو و شیرین نظامی بنام مهر و مشتری در سال <span class=\"hlight\" dir=\"rtl\">٧٧٨</span> هَ .ق . منظوم کرد. وفاتش بسال <span class=\"hlight\" dir=\"rtl\">٧٨٤</span> رخ داد. (از تاریخ مغول عباس اقبال ص <span class=\"hlight\" dir=\"rtl\">٥٥٣</span>).<br></font></div>'),
(183790, 'عصارات', '<span class=\"hlight\">عصارات .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عُصارة. افشره ها. اجزای مایه ٔ متخرجه از نبات است خواه از گلها و یا از اوراق و یا از اغصان و یا اصول و لحای آنها باشد که کوبیده فشرده اخذ نمایند، خواه همان قسم مایع استعمال نمایند و خواه خشک سوده . (مخزن الادویة). و رجوع به عصارة شود <span class=\"hlight\">:</span> <br>آب است و نبیذ است <br>عصارات زبیب است <br>سمیه روسبیذ است .<br>یزیدبن مفرغ (از سبک شناسی بهارج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> و الاغانی ).<br></font></div>'),
(183791, 'عصارخانه', '<span class=\"hlight\">عصارخانه .</span> <font color=\"DarkGreen\"><b>[ ع َص ْ صا ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) جایی است که در آن عصاران بسیار می باشند. (از آنندراج ). جای اجتماع عصاران . <BR><font color=\"Blue\">◄</font> جایی که در آن عصاری کنند. محلی که در آن شیره ٔ انگور یا روغن نباتی گیرند. (فرهنگ فارسی معین ). دکّه و کارگاه عصاری .<br></font></div>'),
(183792, 'عصاره', '<span class=\"hlight\">عصاره .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (از ع، اِ) عصارة. آب افشرده ٔ نباتات است، اعم از آنکه خشک کنند یا نکنند. (تحفه ٔ حکیم مؤمن ). به معنی عصیر است اما در آنچه به آتش و آفتاب منعقد کرده باشند استعمال می نمایند. (مخزن الادویة). افشره . (تفلیسی ). افشاره . فشاره . فشرده . افشرده . شیره . رُب . چکیده . آب <span class=\"hlight\">:</span> و از ری کرباس و برد وپنبه و عصاره و روغن و نبیذ خیزد. (حدود العالم ).<br>ز ما اینجا همی کنجاره ماند<br>چو روغنگر گرفت از ما عصاره .<br> <font color=\"Red\">ناصرخسرو.</font><br>ازبهر آنکه اندر قنطوریون و اندر عصاره ٔ او یعنی افشره ٔ او این قوتها و این منفعتها از او <font color=\"DarkGreen\"><b>[ از خشکی و قبض ]</font></b> بحاصل آید. (ذخیره ٔ خوارزمشاهی ). عصاره ٔ نایی بقدرتش شهد فایق گشته . (گلستان سعدی ).<br>- <span class=\"hlight\">عصاره ٔ آرغیس </span> ؛ عصاره ٔ پوست انبرباریس است و در امراض مستعمل و بهتر از مامیران چینی است . (مخزن الادویة).<br>- <span class=\"hlight\">عصاره ٔ افسنتین </span> ؛افشرده ٔ افسنتین است و صفت آن مانند غافث است . (از اختیارات بدیعی ) (از الفاظ الادویة). رجوع به افسنتین شود.<br>- <span class=\"hlight\">عصاره ٔ املج </span> ؛ سُک ّ است . (فهرست مخزن الادویة). رجوع به سُک شود.<br>- <span class=\"hlight\">عصاره ٔ انبرباریس </span> ؛ افشرده ٔ زرشک است . و برای ساختن آن زرشک تر خوب رسیده را گرفته آب آن بگیرند و بجوشانند تا غلیظشود و بر روی کاغذ کنند تا رطوبت که باقی مانده نشف کند و یا در آفتاب نهند تا تمام شود یا به آتش چنانکه گفته شد. (از اختیارات بدیعی ) (الفاظ الادویة).<br>- <span class=\"hlight\">عصاره ٔ خشخاش اسود</span> ؛ افیون است . (الفاظ الادویة) (تحفه ٔ حکیم مؤمن ).<br>- <span class=\"hlight\">عصاره ٔ سوس </span> ؛ رب سوس است . (تحفه ٔ حکیم مؤمن ). رجوع به عصارةالسوس شود.<br>- <span class=\"hlight\">عصاره ٔ شجرةالجوز</span> ؛ افشرده ٔ درخت گردکان است و بدل آن مرزنجوش است . (از الفاظ الادویة) (ازاختیارات بدیعی ).<br>- <span class=\"hlight\">عصاره ٔ شقائق النعمان </span> ؛ افشرده ٔ لاله است و بدل آن عصاره ٔ بخور مریم . (از اختیارات بدیعی ) (الفاظ الادویة).<br>- <span class=\"hlight\">عصاره ٔ طرانیث </span> ؛ افشرده ٔ طرانیث است و بدل آن عصاره ٔ قرط وایل است . (از الفاظ الادویة).<br>- <span class=\"hlight\">عصاره ٔ لحیةالتیس </span> ؛ افشرده ٔ درخت سوس است، و بهترین آن تازه بود و صفت آن مانند غافث است . (از الفاظ الادویة) (از اختیارات بدیعی ).<br>- <span class=\"hlight\">عصاره ٔ مامیثا</span> ؛ شیاف مامیثا است . (الفاظ الادویة) (از تحفه ٔ حکیم مؤمن ). رجوع به عصارةالمامیثا شود.<br>- <span class=\"hlight\">عصاره ٔ هوقیفصداس </span> ؛ عصاره ٔ لحیةالتیس است . (فهرست مخزن الادویة). رجوع به عصاره ٔ لحیةالتیس شود.<br> <BR><font color=\"Blue\">◄</font> کنایه از خلاصه و برگزیده ٔ هر چیزی است . (از فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> کنجاره . (دهار) (تفلیسی ). ثفل چیزی که افشرده شود. (غیاث اللغات ) <span class=\"hlight\">:</span> <br>خری که آبخورش زیر ناودان عصیر<br>علف عصاره ٔ بکنی و بخسم و شوشو.<br><font color=\"Red\">سوزنی .</font><br><BR><font color=\"Blue\">◄</font> (اصطلاح شیمی ) دارویی که از غلظت محلولهای استخراجی که با مواد دارویی حیوانی و نباتی تهیه شده اند به دست می آید. (فرهنگ فارسی معین ).<br></font></div>'),
(183793, 'عصاره کشیدن', '<span class=\"hlight\">عصاره کشیدن .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ ]</font></b> (مص مرکب ) خارج کردن عصاره ٔ چیزی . فشردن بذر یا میوه ای تا آب آن خارج شود. کشیدن شیره ٔ چیزی . <BR><font color=\"Blue\">◄</font> کنایه از ناتوان ساختن شخص از بسیاری ِ تحمیل کردن کاری بر او. شیره ٔ کسی را کشیدن .<br></font></div>'),
(183794, 'عصاره گرفتن', '<span class=\"hlight\">عصاره گرفتن .</span> <font color=\"DarkGreen\"><b>[ ع ُ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ گ ِ رِ ت َ ]</font></b> (مص مرکب ) شیره کشیدن . عصاره کشیدن . افشردن چیزی را تا عصاره ٔ آن خارج شود.<br></font></div>'),
(183795, 'عصاری', '<span class=\"hlight\">عصاری .</span> <font color=\"DarkGreen\"><b>[ ع َص ْ صا ]</font></b> (حامص ) شغل و عمل عصار. روغنگری . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) دکانی که در آن روغن گیرند و فروشند. (فرهنگ فارسی معین ). دکان عصاری .<br>- <span class=\"hlight\">اسب (گاو) عصاری </span> ؛ اسب یا گاوی که با چشم بسته دور دستگاه روغنگری گردانند تا آن را بکار اندازد. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">چرخ عصاری </span> ؛ دستگاهی است برای روغن کشی، و آن مرکب است از استوانه ای چوبین به قطر <span class=\"hlight\" dir=\"rtl\">٢</span> تا <span class=\"hlight\" dir=\"rtl\">٣</span> متر و ارتفاع یک متر که در زمین نصب کنند. سطح فوقانی استوانه بطور محدب (بشکل قیف ) تراشیده شده . تیری ضخیم به ارتفاع <span class=\"hlight\" dir=\"rtl\">٦</span> تا <span class=\"hlight\" dir=\"rtl\">٧</span> متر که انتهای آن تراشیدگی دارد و مطابق دهانه ٔ پایین استوانه است در آن استوانه قرار میدهند. به انتهای تیر رشته ای چرمین می بندند و سر رشته را بگردن اسبی یا گاوی که در کنار استوانه ایستاده، بندند. اسب یا گاو را به حرکت دورانی وامیدارند. تیر بطور منحنی در داخل استوانه بگردش درمی آید و دانه ها (مانند خشخاش و کنجد و پنبه دانه یا چیز دیگر) را که در اطراف دهانه ریخته خردمیکند و روغن آنها را میگیرد. در ته دهانه ٔ استوانه سوراخی است که انتهای آن سطح خارجی استوانه است . روغن از آن سوراخ خارج میشود و در ظرفی که زیر آن قراردارد ذخیره میگردد. وقتی ظرف پر شد آن را برمیدارند. (فرهنگ فارسی معین ).<br></font></div>'),
(183796, 'عصازنان', '<span class=\"hlight\">عصازنان .</span> <font color=\"DarkGreen\"><b>[ ع َ زَ ]</font></b> (ق مرکب ) در حال عصا زدن . رفتن با تکیه دادن سر عصا بر زمین استعانت را. رجوع به عصا زدن شود.<br></font></div>'),
(183797, 'عصاشمشیر', '<span class=\"hlight\">عصاشمشیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (اِ مرکب ) تیغ راست که بجای عصا در دست دارند، و آن دو قسم است یکی تیغه ٔ او گرد باشد و آن را در عرف هند گپتی گویند، و آنچه یک طرف یا هر دو طرف دم داشته باشد و پهن بود آن را دُمهوپ گویند. (آنندراج ) <span class=\"hlight\">:</span> <br>چرخ از آه من استادبپا چون سالک <br>آه من در کف این پیر عصاشمشیر است .<br><font color=\"Red\">سالک یزدی (از آنندراج ).</font><br></font></div>'),
(183798, 'عصاشکل', '<span class=\"hlight\">عصاشکل .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص مرکب ) به شکل عصا. چون عصا. بسان چوبدست <span class=\"hlight\">:</span> <br>گریزد ز شکل عصا مار و گوید<br>عصاشکلم و از عصا می گریزم .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(183799, 'عصاعص', '<span class=\"hlight\">عصاعص .</span> <font color=\"DarkGreen\"><b>[ ع َ ع ِ ]</font></b> (ع اِ) ج ِ عصعص . (اقرب الموارد). رجوع به عصعص شود.<br></font></div>'),
(183800, 'عصاعیص', '<span class=\"hlight\">عصاعیص .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عصعص . (اقرب الموارد). رجوع به عصعص شود.<br></font></div>'),
(183801, 'عصافة', '<span class=\"hlight\">عصافة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ف َ ]</font></b> (ع اِ) آنچه برافتد از خوشه از برگ و کاه . (منتهی الارب ): عصافةالتبن ؛ خرده ها و ریزه های کاه . (از اقرب الموارد). عَصف . عَصیفة. و رجوع به عصف و عصیفة شود.<br></font></div>'),
(183802, 'عصافیر', '<span class=\"hlight\">عصافیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عُصفور. (منتهی الارب ) (اقرب الموارد) (دهار). گنجشکان . سبکبالان . (فرهنگ فارسی معین ). و رجوع به عصفور شود. <BR><font color=\"Blue\">◄</font> نَقّت (طارت ) عصافیرُ بطنه ؛ گرسنه شد. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> طارت عصافیر رأسه ؛ کنایه از بزرگسالی و سالمندی است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عصافیرالقَتَب ؛ میخهای پالان شتر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> عصب ها و پی ها که بر استخوانهای سِنسِن است . (از اقرب الموارد). رجوع به سنسن شود. <BR><font color=\"Blue\">◄</font> عصافیرالمنذر؛ شتران نیکو و نجیب که پادشاه نعمان بن منذر را بود. (منتهی الارب ) (از اقرب الموارد): وهب النعمان للنابغة مائة من عصافیره . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> درختی است مسمی به «من رأی مثلی » و مر او را صورتی است مانند عصافیر، و در پارس بسیار میشود. (منتهی الارب ) (از اقرب الموارد).<br>- <span class=\"hlight\">لسان العصافیر</span> ؛ درخت زبان گنجشک . (ناظم الاطباء). رجوع به لسان العصافیر شود.<br></font></div>'),
(183803, 'عصافیرالراعی', '<span class=\"hlight\">عصافیرالراعی .</span> <font color=\"DarkGreen\"><b>[ ع َ رُرْ را ]</font></b> (ع اِ مرکب ) درخت عصاالراعی است .(از تذکره ٔ ضریر انطاکی ). رجوع به عصاالراعی شود.<br></font></div>'),
(183804, 'عصافیری', '<span class=\"hlight\">عصافیری .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) قسمی از زیتون . (ناظم الاطباء).<br></font></div>'),
(183805, 'عصاقیة', '<span class=\"hlight\">عصاقیة.</span> <font color=\"DarkGreen\"><b>[ ع َ ی َ ]</font></b> (ع اِ) شور و فریاد و خروش . (منتهی الارب ) (از اقرب الموارد). عصاقیاء. و رجوع به عصاقیاء شود.<br></font></div>'),
(183806, 'عصاقیل', '<span class=\"hlight\">عصاقیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عُصقول . (منتهی الارب ) (اقرب الموارد). رجوع به عصقول شود. <BR><font color=\"Blue\">◄</font> گردبادها. (منتهی الارب ). اعاصیر:هبت العصاقیل ؛ گردبادها وزید. (از اقرب الموارد).<br></font></div>'),
(183807, 'عصال', '<span class=\"hlight\">عصال .</span> <font color=\"DarkGreen\"><b>[ ع َص ْ صا ]</font></b> (ع ص ) بغایت و بسیار خمنده و کج کننده . (ناظم الاطباء).<br></font></div>'),
(183808, 'عصال', '<span class=\"hlight\">عصال .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص، اِ) ج ِ أعصَل . (منتهی الارب ). رجوع به اعصل شود. <BR><font color=\"Blue\">◄</font> ج ِعَصَل . (اقرب الموارد) (ناظم الاطباء). رجوع به عصل شود. <BR><font color=\"Blue\">◄</font> کج، و تیر کج . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِخ ) نام جایگاهی است . (از منتهی الارب ).<br></font></div>'),
(183809, 'عصام', '<span class=\"hlight\">عصام .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) حلقه ای که در گردن سگ باشد. ج، أعصام . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183810, 'عصام', '<span class=\"hlight\">عصام .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) بند مشک و دوال که به وی بردارند مشک را. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> رسن محمل که بر تصدیر وسینه بند و تنگ شتر بندند تا سپس نرود. (از منتهی الارب ). شکال، در محمل . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> رسن دلو و مشک و آبدستان که بدان بندند. <BR><font color=\"Blue\">◄</font> دسته ٔ آوند که بدان آویزند. (منتهی الارب ). عروه و دسته ٔ ظرف که بوسیله ٔ آن آویخته شود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سرمه . (منتهی الارب ). کحل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> جای باریک یک طرف دنب . (منتهی الارب ). قسمت باریک انتهای دم . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مجازاً، عهد و پیمان . (از اقرب الموارد). ج، أعصِمة، عُصم، عِصام، که لفظ اخیر با مفردش یکسان است . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زره تابان و نرم . <BR><font color=\"Blue\">◄</font> معصم و موضعدستبند از ساعد. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ج ِ عِصام بر لفظ مفرد. (منتهی الارب ) (از اقرب الموارد).<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">کن عصامیاً و لاتکن عظامیاً</span> .<br>و ماورأک یا عصام . رجوع به عصام (ابن شهبر...)شود.<br></font></div>'),
(183811, 'عصام', '<span class=\"hlight\">عصام .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) (ملا...) نام او عبدالملک بن جمال الدین عصامی و مشهور به ملا عصام است . رجوع به عبدالملک (ابن جمال العصامی ...) شود.<br></font></div>'),
(183812, 'عصام', '<span class=\"hlight\">عصام .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) ابن عمرو بغدادی، مکنی به ابوحمید. تابعی است . رجوع به ابوحمید شود.<br></font></div>'),
(183813, 'عصام', '<span class=\"hlight\">عصام .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) ابن شهبربن حارث بن ذبیان بن عذرة. از سواران و فصیحان عرب در دوره ٔ جاهلیت . در مورد کسانی که شرافت را با اکتساب و نه به اصل و نسب به دست آورده اند، به وی مثل زنند و گویند: «کن عصامیاً و لاتکن عظامیاً»؛ یعنی به شرافت خود فخر و مباهات کن نه به نیاگان بزرگت . عصام حاجب نعمان بن منذربوده است . (از الاعلام زرکلی از اللباب و القاموس و مجمع الامثال و ثمارالقلوب و تاج العروس ). این مثل به این معنی است که چون عصام، شرافت را به نفس خود به دست آر نه بوسیله ٔ پدرانت که عِظام و استخوان شده اند.و از این مثل این بیت را در نظر دارند <span class=\"hlight\">:</span> <br>نفس عصام سوّدت عصاما<br>و علمته الکرّ و الاقداما.<br>یعنی نفس عصام او را سروری داد و شجاعت و حمله را به وی آموخت . (از منتهی الارب ) (از اقرب الموارد).<br>ما ورأک یا عصام ؟ مثلی است که برای استخبار از چیزی بکار برند. (از اقرب الموارد) (از ناظم الاطباء) (از منتهی الارب ). این مثل در کتاب اعلام النساء به عصام کندیة نسبت داده شده است که از زنان فصیح و تیزهوش عهد حارث بن عمرو پادشاه کنده بود. و گوید حارث او را برای دیدار دختر عوف بن محلم شیبانی فرستاد تا اگر او را شایسته بیند از وی خواستگاری کند، و چون عصام بازگشت حارث به وی گفت «ما ورأک یا عصام » و عصام باجملاتی فصیح و بلیغ و پرشکوه وصف زیبایی و کمال دخترعوف را کرد که این جملات در اعلام النساء مذکور است . رجوع به اعلام النساء ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٣</span> و مجمع الامثال میدانی و الفاخر مفضل کوفی و جمهرةالامثال و فرائداللاَّل ِ أحدب شود.<br></font></div>'),
(183814, 'عصام اسفرایینی', '<span class=\"hlight\">عصام اسفرایینی .</span> <font color=\"DarkGreen\"><b>[ ع ِ م ِ اِ ف َ ]</font></b> (اِخ ) ابراهیم بن محمدبن عربشاه اسفرایینی، ملقب به عصام الدین . وی بسال <span class=\"hlight\" dir=\"rtl\">٨٧٣</span>هَ .ق . در اسفرایین از قرای خراسان متولد شد. پدرش از قضات آنجا بود. و او به آموختن علم پرداخت و در اواخر عمر به سمرقند رفت و به سال <span class=\"hlight\" dir=\"rtl\">٩٤٥</span> هَ .ق . در این شهر درگذشت . او راست : الاطول، در شرح تلخیص المفتاح قزوینی، در علوم بلاغت و میزان الادب . و نیز شرحها و حواشیی در منطق و توحید و نحو دارد. (از الاعلام زرکلی چ <span class=\"hlight\" dir=\"rtl\">٢</span> از کشف الظنون و شذرات الذهب و معجم المطبوعات ).<br></font></div>'),
(183815, 'عصام کندیة', '<span class=\"hlight\">عصام کندیة.</span> <font color=\"DarkGreen\"><b>[ ع ِ م ِ ک ِ دی ی َ ]</font></b> (اِخ ) از زنان صاحب رای و خرد و فصیح و بلیغ و فاضل و ادیب، در عهد حارث بن عمروملک کنده است . رجوع به عصام (ابن شهبربن ...) شود.<br></font></div>'),
(183816, 'عصامی', '<span class=\"hlight\">عصامی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ص نسبی ) منسوب به عصام بن شهبر صاحب نعمان . آنکه به نفس خود بالد نه به پدران . مقابل عظامی . (یادداشت مرحوم دهخدا). در مثل گویند: کن عصامیاً و لاتکن عظامیاً. رجوع به عصام (ابن شهبربن ...)شود <span class=\"hlight\">:</span> در این عصامی و عظامی از جریر و متنبی چند شعر یاد داشتم نبشتم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤١٥</span>).<br>مثل زنند که در مهتری عصامی باش <br>که فضل داد بر اهل عصام نفس عصام .<br> <font color=\"Red\">ادیب صابر.</font><br>و رجوع به عظامی شود.<br></font></div>'),
(183817, 'عصامی', '<span class=\"hlight\">عصامی .</span> <font color=\"DarkGreen\"><b>[ ع ِ]</font></b> (اِخ ) لقب عبدالملک بن جمال الدین عصامی اسفرایینی، مشهور به ملا عصام است . از علمای قرن دهم و یازدهم هجری . رجوع به عبدالملک (ابن جمال العصامی ...) شود.<br></font></div>'),
(183818, 'عصامی', '<span class=\"hlight\">عصامی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) لقب عبدالملک بن حسین بن عبدالملک مکی عصامی، از مورخان قرن دوازدهم هجری . رجوع به عبدالملک (ابن حسین بن ...) شود.<br></font></div>'),
(183819, 'عصامی', '<span class=\"hlight\">عصامی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) لقب علی بن اسماعیل بن ابراهیم بن محمد اسفرایینی عصامی، از رجال بلاغت در قرن دهم هجری است . رجوع به علی عصامی شود.<br></font></div>'),
(183820, 'عصامیر', '<span class=\"hlight\">عصامیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عُصمور.(منتهی الارب ) (اقرب الموارد). رجوع به عصمور شود.<br></font></div>'),
(183821, 'عصامیم', '<span class=\"hlight\">عصامیم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عُصموم . (دهار). رجوع به عصموم شود.<br></font></div>'),
(183822, 'عصاول', '<span class=\"hlight\">عصاول .</span> <font color=\"DarkGreen\"><b>[ ع َ وَ ]</font></b> (اِ) قاصد پادشاهی و دولتی . (ناظم الاطباء).<br></font></div>'),
(183823, 'عصاوید', '<span class=\"hlight\">عصاوید.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) ج ِ عِصواد. (منتهی الارب ) (اقرب الموارد). رجوع به عصواد شود. <BR><font color=\"Blue\">◄</font> تشنگان، گویند: ابل عصاوید؛ یعنی شتران تشنه . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ابر سطبر درهم پیوسته . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> درهم افتاده . گویند: جأت الابل و الخیل عصاوید؛ هرگاه بر همدیگر سوار باشند. (از منتهی الارب ) (ازاقرب الموارد). <BR><font color=\"Blue\">◄</font> تاریکی بسیار و توبرتو. <BR><font color=\"Blue\">◄</font> عصاوید الکلام ؛ آنچه پیچیده باشد از کلام . (منتهی الارب ). سخن درهم افتاده . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> قوم عصاوید فی الحرب ؛ گروه درهم پیوسته همه اقران خود را. (منتهی الارب ). گروهی که در جنگ با اقران خود در هم پیچیده باشند. (ناظم الاطباء).<br></font></div>'),
(183824, 'عصاکش', '<span class=\"hlight\">عصاکش .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب ) عصاکشنده . آنکه با گرفتن عصای نابینا او را راهبری کند. (از آنندراج ). امیر. (از منتهی الارب ) <span class=\"hlight\">:</span> <br>زآنکه بینائی که نورش بازغ است <br>ازعصا و از عصاکش فارغ است .<br> <font color=\"Red\">مولوی .</font><br>در عصای حزم و استدلال نیست <br>بی عصاکش بر سر هر ره مایست .<br> <font color=\"Red\">مولوی .</font><br>کوری نمیرود به عصاکش برون ز چشم <br>خود خوب شو چه در پی خوبان فتاده ای ؟<br> <font color=\"Red\">صائب (از آنندراج ).</font><br>آن عصاکش که گزیدی در سفر<br>بازبین کو هست از تو کورتر.<br> <font color=\"Red\">مولوی .</font><br>گفته ایشان بی تو ما را نیست نور<br>بی عصاکش چون بود احوال کور؟<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(183825, 'عصاکشی', '<span class=\"hlight\">عصاکشی .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (حامص مرکب ) عمل عصاکش . به دست گرفتن سر چوبدست و عصای کسی را رهنمایی او را. رجوع به عصاکش و عصا شود.<br></font></div>'),
(183826, 'عصایدی', '<span class=\"hlight\">عصایدی .</span> <font color=\"DarkGreen\"><b>[ ع َ ی ِ ]</font></b> (ص نسبی ) منسوب به عَصیده . سازی است . (از الانساب سمعانی ).<br></font></div>'),
(183827, 'عصایدی', '<span class=\"hlight\">عصایدی .</span> <font color=\"DarkGreen\"><b>[ ع َ ی ِ ]</font></b> (اِخ ) اسماعیل بن عبدالرحمان، مکنی به ابوعثمان . محدث بودو به سال <span class=\"hlight\" dir=\"rtl\">٤٦٥</span> هَ .ق . تولد یافت . حدیث را نزد ابوبکرمحمدبن یحیی بن ابراهیم مزکی و ابوسعد عبدالرحمان بن منصوربن دامش آموخت . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(183828, 'عصب', '<span class=\"hlight\">عصب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) پیچیدن و تافتن . (منتهی الارب ). پیچاندن چیزی را و تاب دادن آن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیوستن و ضم نمودن . (منتهی الارب ). بستن و محکم کردن . (از ناظم الاطباء) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> فراهم آوردن شاخ متفرق درخت را به عصا تا برگ آن ریخته شود. (منتهی الارب ): عصب الشجرة؛ شاخه های پراکنده ٔ درخت را بدور آن گرد آورد و آنها رازد تا برگهایش بریزد. (از اقرب الموارد). شاخه های درخت بهم وابستن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> بستن خصیه ٔ تکه و کبش چندان که بی کشیدن بیفتد. (منتهی الارب ) (از اقرب الموارد). بستن خایه ٔ گشن تا بیفتد. (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> بستن هر دو ران ناقه جهت دوشیدن . (منتهی الارب ) (از اقرب الموارد).بستن ران شتر تا شیر دهد. (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> عصابه به سر بستن . (منتهی الارب ). سر وابستن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> سرخ گردیدن افق . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چرکناک گردیدن دندان از غبار و مانند آن . (منتهی الارب ): عصبت الاسنان ؛ دندانها چرک شد از غبار و مانند آن از قبیل شدت تشنگی یا ترس و بیم . (از اقرب الموارد). عُصوب . و رجوع به عصوب شود. <BR><font color=\"Blue\">◄</font> رشتن . (منتهی الارب ). غزل . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گرفتن به پنجه چیزی را. (منتهی الارب ). قبض و گرفتن . (ازاقرب الموارد). عِصاب . و رجوع به عصاب شود. <BR><font color=\"Blue\">◄</font> خشک شدن آب دهن در آن از تشنگی و جز آن . (منتهی الارب ): عصب الریق بالفم ؛ آب دهان خشک شد. (از اقرب الموارد). خدو بر دهن خشک شدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> عصب الریق فاه ؛ آب دهان، دهان او را خشک کرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> احاطه کردن . گویند: عصب القوم بفلان ؛ یعنی مردم گرد آن شخص درآمدند برای کارزار و یا حمایت کردن . و عصبة به معنی قوم شخص، از همین معنی است . (از اقرب الموارد) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> لازم گرفتن چیزی را. (منتهی الارب ). ملازم گشتن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> قدرت یافتن بر چیزی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> عصبت الابل بالماء؛ دور زدند شتران بر آب و آن را احاطه کردند. (از اقرب الموارد) (از ناظم الاطباء) (از منتهی الارب ). گرد آمدن شتر بر آب . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> فرض و واجب نمودن . (از اقرب الموارد).<br></font></div>'),
(183829, 'عصب', '<span class=\"hlight\">عصب .</span> <font color=\"DarkGreen\"><b>[ع َ ص َ ]</font></b> (ع مص ) پی ناک شدن گوشت . (از منتهی الارب ): عصب اللحم ؛ عصب و پی گوشت بسیار شد. (از اقرب الموارد). بسیارپی شدن گوشت . (تاج المصادر بیهقی ) (دهار). <BR><font color=\"Blue\">◄</font> فراهم آمدن و گرد آمدن . (از اقرب الموارد) (از ناظم الاطباء). عَصْب . و رجوع به عَصْب شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(183830, 'عصب', '<span class=\"hlight\">عصب .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ]</font></b> (ع اِ) پی مفاصل .(منتهی الارب ). پی زرد. (السامی فی الاسامی ) (مهذب الاسماء) (دهار). پی . (نصاب الصبیان ). تارهای سپیدرنگی که مرتبط میکند دماغ را با اجزاء مختلف بدن حیوانی . (ناظم الاطباء). پی مفاصل، و آن چیزی است سفید که حس و حرکت و مضبوطی اعضا بدان است . (از غیاث اللغات ) (از آنندراج ). اصل عضله عصب است و عصب را بپارسی پی گویند و این سه نوع است و هر نوعی را بنزدیک طبیبان نامی است، یک نوع آن است که از دماغ رسته است یا از نخاع که خلیفت دماغ است آن را عصب گویند، دوم از سر استخوانها رسته است و آن عصب را رباط گویند، سوم از بیرون عضله رسته است آن را وتر گویند. (ذخیره ٔ خوارزمشاهی ). نسج رشته ای شکل سفیدرنگی که از مراکز اعصاب به اعضای مختلف کشیده شده و انفلوی عصبی را هدایت می کندو بالنتیجه موجب احساس یا حرکت در عضو مربوط میشود.هر عصب از چند رشته ٔ آکسون سلولهای عصبی تشکیل شده و بنابراین هر قدر تعداد آکسونها در ساختمان رشته ٔ عصب بیشتر باشد آن عصب ضخامت بیشتر پیدا میکند. هر رشته عصب از خارج از یک غلاف فیبری پوشیده شده است . یک رشته عصب ممکن است حساس باشد در صورتی که تحریکات رابه مراکز عصبی منتقل سازد، و ممکن است محرک باشد درصورتی که از مراکز عصبی فرامین را به عضو مربوط برساند، و ممکن است مختلط باشد در صورتی که حاوی هر دو نوع رشته های مختلف حساس و محرک باشد. (فرهنگ فارسی معین ). و رجوع به جواهرالتشریح میرزا علی ص <span class=\"hlight\" dir=\"rtl\">٨١٦</span> و ذخیره ٔ خوارزمشاهی چ دانشگاه ص <span class=\"hlight\" dir=\"rtl\">٩١</span> و <span class=\"hlight\" dir=\"rtl\">١٣١</span> شود <span class=\"hlight\">:</span> <br>دوسر اندر شکم هر یک نه بیش و نه کم <br>نه در ایشان ستخوانی نه رگی نه عصبی .<br> <font color=\"Red\">منوچهری .</font><br>- <span class=\"hlight\">عصب اشتیاقی </span> ؛ عصبی است محرک که فقط عضله ٔ مایل بزرگ چشم را عصب میدهد. این عصب با رشته عصب نظیر خود چهارمین زوج اعصاب دماغی را به وجود می آورد، و آن از نقطه ای در دماغ مبداء میگیرد که در پایین و دنبال مبداء عصب محرکه ٔ عمومی چشم است . عصب دعا. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب باصره </span> ؛ هر یک از دو رشته عصب زوج دوم اعصاب دماغی است که مبداء آنها سلولهای حسی شبکیه اند. الیاف این زوج عصب که با هم مجتمع شده اند از جدار کره ٔ چشم عبور مینمایند و در داخل کاسه ٔ سر به مجمعالنورین که در نزدیکی «زین ترکی » است منتهی میگردد. عصب باصره مخلوطی از تارهای عصبی نوار باصره ٔ راست و چپ است . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب تعادلی </span> ؛ رشته ای است از عصبهای دوگانه ای که در تشکیل عصب سامعه شرکت دارد. عصب دهلیزی . (فرهنگ فارسی معین ). و رجوع به عصب سامعه در همین ترکیبات شود.<br>- <span class=\"hlight\">عصب حجاب حاجز</span> ؛ عصبی است که از شبکه ٔ گردنی متفرع میشود و از گردن و قفسه ٔ سینه عبور میکند و به حجاب حاجز ختم میشود. این عصب دارای یک ریشه ٔ ثابت و دو ریشه ٔ فرعی غیرثابت است . ریشه ٔ ثابت عصب مذکور از چهارمین عصب گردنی مجزا میشود و دو ریشه ٔفرعی از سومین و پنجمین عصب گردنی یا از سومین قوس و پیوند بین چهارمین و پنجمین عصب گردنی متفرع میگردند. عصب فرنیک . عصب حجاب حاجزی . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب حساس </span> ؛ عصبی است که تحریکات را از اعضاء به مراکز عصبی هدایت میکند. پی حساس . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب حلزونی </span> ؛ یکی از رشته عصب های دوگانه ای که در تشکیل عصب سامعه شرکت دارد. (فرهنگ فارسی معین ).رجوع به عصب سامعه در همین ترکیبات شود.<br>- <span class=\"hlight\">عصب دعا</span> ؛ عصب اشتیاقی . (فرهنگ فارسی معین ). رجوع به عصب اشتیاقی درهمین ترکیبات شود.<br>- <span class=\"hlight\">عصب دهلیزی </span> ؛ عصب تعادلی .(فرهنگ فارسی معین ). رجوع به عصب تعادلی و عصب سامعه در همین ترکیبات شود.<br>- <span class=\"hlight\">عصب ریوی - معدی </span> ؛ عصبی است مختلط و مهمترین ِ اعصاب بدن است و اعمال فیزیولوژی آن بسیار اهمیت دارد، زیرااعمال قلب و تنفس و جهاز هاضمه و حنجره و حلق و قصبةالریه و مری مربوط بدان است . این عصب با رشته عصب نظیر خود دهمین زوج اعصاب دماغی را میسازد. مرکز آن در بصل النخاع است و پس از خروج از این قسمت از سوراخ پاره ٔ خلفی از کاسه ٔ سر خارج میشود و بگردن می آید و در گردن همراه شاه رگ و ورید و داج داخلی تشکیل دسته ٔرگ و پی گردن را میدهد. این عصب وارد سینه میشود و پس از انشعاب به قلب و ریه به لوله ٔ مری اتصال می یابد و به شکم میرود و از آنجا به احشاء مختلف منتشر میگردد (کبد، معده، کلیه ها و روده ها) و چون مخالف دستگاه سمپاتیک کار میکند از این جهت آن را عصب پاراسمپاتیک میخوانند. عصب پنوموگاستریک . عصب واگ . (از فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب زبانی - حلقی </span> ؛ عصبی است مختلط که دارای رشته عصب های دستگاه نباتی نیز میباشد و با رشته عصب نظیرش زوج نهم اعصاب دماغی را میسازد. این عصب برای حس زبان و قسمتی از حلق است و احساسات ذائقه ٔ ثلث خلفی زبان را به مغز میرساند. عصب مزبور از قسمت فوقانی شیار جانبی خلفی بصل النخاع در بالای عصب دهم و پایین عصب سامعه مبداء میگیرد. (از فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب زیرزبانی </span> ؛ عصبی است کاملاً محرک که برای حرکت عضلات زبان قسمتی از عضلات زیر چانه است .این عصب با رشته عصب نظیر خود دوازدهمین زوج اعصاب دماغی را به وجود می آورد و الیافش از سلولهایی به وجود می آیند که در بصل النخاع قرار گرفته است . عصب بزرگ زیرزبانی . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب سامعه </span> ؛ عصبی است حسی که از اجتماع دو عصب یکی بنام عصب حلزونی و دیگری بنام عصب دهلیزی تشکیل شده است . این عصب با رشته عصب نظیرش زوج هشتم اعصاب دماغی را میسازد. عصب حلزونی که جهت شنیدن اصوات بکار میرود به گوش داخلی منتهی میشود واز عقده ٔ کورتی که خارج از مغز است مبداء میگیرد و در دماغ در نقطه ای جلو پایه ٔ مخچه ای تحتانی ختم میگردد. عصب دهلیزی که بنام عصب تعادلی نیز موسوم است ازعقده ٔ اسکارپا واقع در عمق گوش داخلی مبداء میگیرد و در دماغ به کف بطن چهارم به منطقه ٔ دهلیزی ختم میشود. (از فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب سه توأم </span> ؛ عصبی است مختلط که باعث حساسیت صورت و نصف قدامی سر میباشد و عضلات ماضغه را عصب میدهد. مبداء الیاف حسی این عصب از عقده ٔ گاسر است (عقده ٔ گاسر توده ٔ عصبی هلالی شکلی است که از بالا به پایین مسطح و در روی سطح قدامی فوقانی استخوان خاره در یک فرورفتگی بنام فضای مکل قرار دارد) مبداء ریشه ٔ محرک این عصب از دو نقطه است : یکی اصلی که در ماده ٔ خاکستری پل دماغی واقعاست، و دیگری فرعی که در بالای این نقطه در مزانسفال قرار دارد. وجه تسمیه ٔ آن اینست که این عصب به سه شاخه ٔ انتهائی عصب عینی و عصب فک اسفل و عصب فک اعلی تقسیم میشود. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب سیاتیک </span> ؛ عصبی است که از رأس مثلث شبکه ٔ خاجی مبداء میگیرد و در حقیقت دنباله ٔ این رأس است و الیافش ازهمه ٔ شاخه های کمری و خاجی که در تشکیل شبکه ٔ خاجی شرکت دارند به وجود می آید. این عصب درشت ترین عصب بدن است . عصب مزبور در سرین بوسیله ٔ عضله ٔ سرینی بزرگ پوشیده میشود و در ناودانی که بین استخوان «ورگ » و برآمدگی بزرگ استخوان رانی است پایین می آید و یکی از نقاط دردناک عرق النسا یا سیاتیک در همین ناحیه است . انشعابات عصب سیاتیک همراه با عضلات و استخوانهای پا پایین می آید و تا نوک انگشتان پا میرسد، بهمین جهت دردهای سیاتیکی در انگشتان پا بخصوص شست پا نیز محسوس است . عرق النسا. عصب نسائی بزرگ . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب سیما</span> ؛ عصب صورتی است . (فرهنگ فارسی معین ). رجوع به عصب صورتی در همین ترکیبات شود.<br>- <span class=\"hlight\">عصب شامّه </span> ؛ عصبی است حسی و جهت حس شامه است . اولین زوج اعصاب دماغی را با رشته عصب نظیر خود تشکیل می دهد و از سلولهای عصبی زیر مخاط شامه بوجود می آید و در کاسه ٔ سر به یک برجستگی موسوم به پیاز شامه منتهی میشود که روی صفحه ٔ غربالی استخوان پرویزنی قرار دارد. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب شوکی </span> ؛ عصبی است محرک که دارای الیاف حسی و نباتی نیز میباشد و قسمتی از آن با عصب دهم یکی میشود و قسمت دیگرش به عضلات جناغی چنبری پستانی و ذوزنقه منتهی میشود. این عصب با رشته عصب نظیرش یازدهمین زوج اعصاب دماغی را میسازد. عصب مذکور دارای دو ریشه ٔ نخاعی و بصل النخاعی است . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب صورتی </span> ؛ عصبی است محرک که تمام عضلات پوستی سر و گردن و عضله ٔ رکابی و بعضی از عضلات شراع الحنک را عصب میدهد و در ضمن شامل دستگاه نباتی نیز میباشد و در تحریک اشک دخالت دارد. این عصب با رشته عصب نظیر خود هفتمین زوج اعصاب دماغی را تشکیل میدهد. عصب مزبور از هسته ٔ صورتی که در توده ٔ خاکستری پل دماغی قرار دارد مبداء میگیرد و بطرف بالا و خارج و جلو متوجه شده وارد مجرای گوش داخلی میشود، سپس از مجرای فالوپ عبور کرده پس از عبور از سوراخ نیزه ای پستانی داخل غده ٔ بناگوش میشود. عصب سیما.(فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب عینی </span> ؛ شاخه ٔ عصب سه توأم است که از قسمت داخلی کنار قدامی عقده ٔ گاسر (رجوع به عصب سه توأم شود) شروع شده و در ضخامت جدار خارجی جیب کهفی بطرف جلو و بالا متوجه می گردد و در انتها به سه شاخه ٔ عصب بینی و عصب پیشانی و عصب اشکی تقسیم می شود. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب فک اسفل </span> ؛ عصبی است مختلط که از اجتماع دو ریشه به وجود می آید: یکی ریشه ٔ حسی که از کنار قدامی خارجی عقده ٔ گاسر (رجوع به عصب سه توأم شود) شروع میشود، و دیگری ریشه ٔ محرک که کوچک است و از زیر عقده ٔ گاسر عبور می نماید. این دو ریشه ابتدا از هم مجزایندولی در مقابل سوراخ بیضی با هم یکی شده و از آن عبور کرده وارد ناحیه ٔ رجلی فکی میشود. شاخه های انتهائی این عصب هفت تا میباشند که از دو تنه ٔ انتهائی قدامی و خلفی مبداء میگیرند. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب فک اعلی </span> ؛ عصبی است حسی که یکی از شاخه های عصب سه توأم است و از کنار قدامی خارجی عقده ٔ گاسر (رجوع به عصب سه توأم شود) شروع و در روی سطح درون سری بال بزرگ شب پره بطرف جلو ممتد میشود و پس از عبور از سوراخ گرد بزرگ وارد قعر حفره ٔ رجلی فکی میگردد. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب مجوف </span> ؛ عبارت از دو عصب که از دماغ رسته و به دو چشم درآمده در هریکی یکی، و وی را عصب نوری نیز گویند. و غیر این دوعصب و اعصاب قضیب، هیچ عصبی مجوف نیست . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">عصب محرک </span> ؛ عصبی است که فرامین را از مراکز عصبی به اعضای مربوط منتقل میسازد. پی محرک .(فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب محرک خارجی چشم </span> ؛ عصبی است محرک و فقط عضله ٔ راست خارجی چشم را عصب میدهد، و با رشته عصب نظیر خود ششمین زوج اعصاب دماغی را به وجود می آورد. این عصب از نقطه ای واقع در پل دماغی روی کف بطن چهارم مبداء میگیرد و از کنار فوقانی استخوان خاره وارد جیب کهفی میشود، سپس از قسمت پهن شکاف شب پره گذشته به انتهای خلفی عضله ٔ راست خارجی چشم منتهی میگردد. این عصب با شبکه ٔ سمپاتیک دورسباتی پیوندمیشود. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب محرک مشترک چشم </span> ؛ این عصب با رشته عصب نظیر خود زوج سوم اعصاب دماغی را تشکیل میدهد. عصبی است محرک که عضلات کاسه ٔ چشم را به استثنای مایل بزرگ و راست خارجی عصب میدهد و همچنین به واسطه ٔ الیافی که جزودستگاه نباتی میباشد عضلات تنگ کننده ٔ عنبیه و قسمت مدور عضله ٔ مژگانی را عصب میدهد، عصب مذکور از نزدیکی تکمه ٔ چهارتوأم در قسمت قدامی طرفی ماده ٔ خاکستری مبداء میگیرد. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب مختلط</span> ؛ عصبی است که هم حاوی رشته های حساس است و هم حاوی رشته های محرک . پی مختلط. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب نسائی بزرگ </span> ؛ عصب سیاتیک است . (فرهنگ فارسی معین ). رجوع به عصب سیاتیک در همین ترکیبات شود.<br>- <span class=\"hlight\">عصب نوری </span> ؛ عصب مجوف . رجوع به عصب مجوف درهمین ترکیبات شود.<br>- <span class=\"hlight\">عصب واسطه ای وریسبرگ </span> ؛ عصبی است حسی که در ساختمان عصب صورتی وارد است و با آن در تشکیل هفتمین زوج اعصاب دماغی شرکت میکند. این عصب شامل الیاف دستگاه نباتی است و غده های زبانی را عصب میدهد. عصب مزبور از عقده ٔ زانوئی مبداء میگیرد (عقده ٔ زانویی گره کوچک عصبی است که در مقابل انتهای خارجی اولین قسمت مجرای فالوپ بر روی سطح قدامی عصب صورتی واقع است ). (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصب واگ </span> ؛ عصب ریوی - معدی . (فرهنگ فارسی معین ). رجوع به عصب ریوی - معدی در همین ترکیبات شود.<br>- <span class=\"hlight\">ورم عصب </span> ؛ التهاب و تورم و عفونت عصب . (فرهنگ فارسی معین ).<br><BR><font color=\"Blue\">◄</font> درخت پیچک ولبلاب . (از منتهی الارب ) (از اقرب الموارد). رجوع به لبلاب و عَصْب شود. <BR><font color=\"Blue\">◄</font> برگزیدگان قوم . (منتهی الارب ) (از اقرب الموارد). ج، أعصاب . (منتهی الارب ) (اقرب الموارد) (دهار).<br></font></div>'),
(183831, 'عصب', '<span class=\"hlight\">عصب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) درخت پیچک و لبلاب . (از منتهی الارب ) (از اقرب الموارد). عصب <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ص َ ]</font></b> . رجوع به عَصْب و لبلاب شود.<br></font></div>'),
(183832, 'عصب', '<span class=\"hlight\">عصب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ص َ ]</font></b> (اِ) خاری که از آن کتیرا میگیرند.(ناظم الاطباء). خاری است که صمغ آن کتیرا باشد، و به شیرازی کم و به یونانی نوارس خوانند و به عربی مسواک العباد و مسواک المسیح گویند. خوردن آن چارپایان رافربه سازد. (برهان ). نوارس است . (تحفه ٔ حکیم مؤمن )(از اختیارات بدیعی ). درخت خارداری است که صمغ آن کتیرا است و به یونانی نوارس نامند. (مخزن الادویة).<br></font></div>'),
(183833, 'عصب', '<span class=\"hlight\">عصب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ص ُ ]</font></b> (ع اِ) ج ِ عَصیب . (منتهی الارب ) (اقرب الموارد). رجوع به عصیب شود.<br></font></div>'),
(183834, 'عصب', '<span class=\"hlight\">عصب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) درخت پیچک و لبلاب . (از منتهی الارب ) (از ناظم الاطباء) (از اقرب الموارد). داردوست . مهربانک . پیچه . عشق پیچان . عشقه . عَصَب . عُصْب . و رجوع به عصب شود. <BR><font color=\"Blue\">◄</font> نوعی از چادر، واحد و جمع در وی یکسان است . (منتهی الارب ). نوعی از بُرد، و گویند آن بردی است که ابتدا رشته ٔ آن را رنگ میکنند سپس میبافند. و آن قابل تثنیه و جمع بستن نیست لذا مضاف آن را تثنیه و جمع بندند و گویند برد عصب و برود عصب، و جایز است که به صورت وصف بکار رود و گفته شود: شریت ثوباً عصباً. (از اقرب الموارد) (از ناظم الاطباء). و گویند آن نام صبغ و رنگی است که جز در یمن نروید. (از اقرب الموارد) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> نوعی از ابر سرخ که در خشک سال حادث گردد. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گزیده : هو من عصب القوم . <BR><font color=\"Blue\">◄</font> نورد سخت پیچیده . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> عمامه . <BR><font color=\"Blue\">◄</font> امراءة حسنةالعصب ؛ زنی دست و پای باریک و محکم . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اصطلاح عروض ) ساکن کردن لام مُفاعِلَتُن در عروض ِبحر وافر، و رد کردن جزوی را بدان جهت بسوی مَفاعیلُن . (منتهی الارب ). اسکان لام مَفاعَلَتُن از وافر. (از اقرب الموارد). ساکن کردن حرف پنجم متحرک، چون اسکان لام مَفاعِلَتُن تا مَفاعِلْتُن شود و آن را به مَفاعیلُن تغییر دهند و آنگاه مَعصوب نامند. (از تعریفات جرجانی ) (از کشاف اصطلاحات الفنون ) (از المعجم ).<br></font></div>'),
(183835, 'عصب', '<span class=\"hlight\">عصب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ص َ ]</font></b> (ع اِ) ج ِ عُصبة. (منتهی الارب ) (اقرب الموارد). رجوع به عصبة شود.<br></font></div>'),
(183836, 'عصبات', '<span class=\"hlight\">عصبات .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ]</font></b> (ع اِ) ج ِ عَصَبة. (منتهی الارب ) (اقرب الموارد). پسران و خویشان که در شرع برای ایشان فریضه ای مقرر نباشد و در صورت تنهایی همه مال را وارث باشند. رجوع به عصبة شود <span class=\"hlight\">:</span> چون نوبت به سلطان محمود رسید آن ظلم برانداخت و رضا نداد که هر کجا وارث بودی از اصحاب فرایض و عصبات و اولوالارحام هیچ طلب کردندی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٣٠</span>). رجوع به عصبة شود.<br></font></div>'),
(183837, 'عصبانی', '<span class=\"hlight\">عصبانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ]</font></b> (ص نسبی ) منسوب به عصب، با زیادت الف و نون برای تأکید، مثل ربانی و لحیانی و برانی و روحانی و جسمانی و صمدانی . (یادداشت مرحوم دهخدا). عصب دار. دارای عصب و پی <span class=\"hlight\">:</span> اعالی معده را فم معده خوانند، در جرم او قوت عصبانی بیشتر از لحمانی است ... و اسافل او را قعر معده گویند و در جرمش قوت لحمانی بیشتر از عصبانی است . (نزهةالقلوب حمداﷲ مستوفی ). و جرم مشیمیه نیز عصبانی است . (نزهة القلوب ). <BR><font color=\"Blue\">◄</font> (اصطلاح پزشکی ) آنکه روحاً ناراحت است . کسی که تعادل قوای ارادی و تسلط خود را بر اثر ناراحتی و خشم از دست داده است . <BR><font color=\"Blue\">◄</font> عصبی مزاج . (فرهنگ فارسی معین ). رجوع به عصبی مزاج شود. <BR><font color=\"Blue\">◄</font> آنکه خشمگین باشد. غضبناک . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصبانی شدن </span> ؛ خشمگین شدن . چیره شدن حالت عصبانیت و خشم بر کسی .<br>- <span class=\"hlight\">عصبانی کردن </span> ؛ خشمگین کردن . چیره کردن حالت خشم و عصبانیت بر کسی .<br></font></div>'),
(183838, 'عصبانیت', '<span class=\"hlight\">عصبانیت .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ نی ی َ ]</font></b> (از ع، مص جعلی، اِمص ) حالت و کیفیت عصبانی . (فرهنگ فارسی معین ). خشم .<br></font></div>'),
(183839, 'عصبة', '<span class=\"hlight\">عصبة.</span><font color=\"DarkGreen\"><b>[ ع َ ص َ ب َ ]</font></b> (اِخ ) ابن هصیص بن حی بن وائل بن جشم بن مالک بن کعب بن قین بن جسر. جدّی است جاهلی و بطنی از قضاعه را تشکیل میدهد. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(183840, 'عصبة', '<span class=\"hlight\">عصبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع اِ) از ده تا چند عدد از مرد و اسب ومرغ . (منتهی الارب ). گروه . (نصاب ). گروه از ده تا چهل . (دهار) (ترجمان القرآن جرجانی ). بمعنی عصابة است در مردان و اسبان و مرغان . (از اقرب الموارد) <span class=\"hlight\">:</span> اذ قالوا لَیوسف و أخوه أحب ّ اًلی أبینا منا و نحن عصبة (قرآن <span class=\"hlight\" dir=\"rtl\">٨/١٢</span>)؛ آنگاه که گفتند یوسف و برادرش نزد پدرمان عزیزتر از ماست و حال آنکه ما عصبه ای هستیم . قالوا لئن أکله الذئب و نحن عصبة اًنا اًذن لخاسرون (قرآن <span class=\"hlight\" dir=\"rtl\">١٤/١٢</span>)؛ گفتند اگر گرگ او را بخورد در حالیکه ما گروهی از جوانان هستیم ما زیانکار خواهیم بود. اًن الذین جاؤوا بالافک عصبة منکم (قرآن <span class=\"hlight\" dir=\"rtl\">١١/٢٤</span>)؛ کسانی که دروغ بزرگ آوردند گروهی از شما بودند. و آتیناه من الکنوز ما اًن مفاتحه لتنوء بالعصبة اولی القوة (قرآن <span class=\"hlight\" dir=\"rtl\">٧٦/٢٨</span>)؛ و او را گنجهایی دادیم که کلیدهای آن بر گروهی از نیرومندان سنگینی میکرد.<br>آنکس که تو را نداشت طاعت <br>در عصبه ٔ تو نمود عصیان .<br> <font color=\"Red\">خاقانی .</font><br>کَلالة؛ عصبه ای که با ایشان برادران مادری وارث باشند. <BR><font color=\"Blue\">◄</font> چیزکی است که بر درخت با خار پیچیده شود و به آسانی دور کرده نشود. (منتهی الارب ).چیزی است که بر درخت قناد پیچد و جز با کوشش از آن جدا نشود. (از اقرب الموارد). ج، عُصَب . (منتهی الارب ) (اقرب الموارد).<br>عِطفة؛ درخت عصبة. (منتهی الارب ).<br></font></div>'),
(183841, 'عصبة', '<span class=\"hlight\">عصبة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ب َ ]</font></b> (ع اِ) هیئت عمامه بستن . (منتهی الارب ). اسم الهیئة است از فعل اعتصب، بمعنی بستن عصابة، چون عِمّة است در وزن و معنی . (از اقرب الموارد).<br></font></div>'),
(183842, 'عصبة', '<span class=\"hlight\">عصبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ص َ ب َ ]</font></b> (اِخ ) منزلی است غربی ِ مسجد قبا. مُعَصّب نیز نامند آنرا. (از منتهی الارب ). نام قلعه ای است و آن جایگاهی است در قُباء، و آن را معصب نیز گفته اند. (از معجم البلدان ).<br></font></div>'),
(183843, 'عصبة', '<span class=\"hlight\">عصبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ب َ ]</font></b> (اِ) ریحانی است که آن را جم اسفرم خوانند، و بعضی گویند لبلاب است که عشق پیچان باشد. (برهان ). جم سفرم است، و گویند لبلاب است که به یونانی فسوس گویند. (از اختیارات بدیعی ). ریحان سلیمان، و گویند لبلاب است . (الفاظ الادویة). جم اسپرم . (مهذب الاسماء). ریحان سلیمان است، و گویند فسوس است . (تحفه ٔ حکیم مؤمن ). یک نوع لبلابی است که به یونانی فسوس نامند. (مخزن الادویة).<br></font></div>'),
(183844, 'عصبة', '<span class=\"hlight\">عصبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ب َ ]</font></b> (ع اِ) واحد عَصَب . (از منتهی الارب ) (از اقرب الموارد). رجوع به عصب شود. <BR><font color=\"Blue\">◄</font> پسران و خویشان نرینه از جانب پدر، و آنان را عصبة بدین جهت نامیده اند که او را احاطه میکنند، پدر یک طرف و فرزند یک طرف و عم یک طرف و برادر طرفی دیگر. و قوم مرد که جهت او تعصب کنند. (از منتهی الارب ). قوم مرد که بر وی تعصب بخرج دهند، و فرزندان و خویشان پدری شخص، و گویی آن جمع عاصب است هرچند مفردی برای آن دیده نشده است، و همان لفظ عصبة برای مذکر و مؤنث و مثنی و جمع بکار رود، و مصدر آن را برخی عُصوبة دانسته اند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اصطلاح فقه ) آنان که وارث شوند شخص را از خویشان بعیدالنسب از غیر پدری و پسری . و اما از ذوی الفرائض آنان که حصه ٔ ایشان مقرر نباشد و آنچه باقی باشد بعد حصه فریضه بگیرند. (منتهی الارب ). وارثان از سوی پدر. (دهار). هر کس از ترکه ٔ میت که سهمی برد، یعنی آنچه از سهام ذی الفروض باقی ماند، و آنها یا نسبی باشد یا سببی . و در نزد شیعه میراثی ازین باب به عصبه نخواهد رسید بنابر فرض زیادی از سهم ذی الفروض . (فرهنگ علوم نقلی از شرح لمعه و کشاف ). پسران و خویشان که در شرع برای ایشان فریضه ای مقرر نباشد و در صورت تنهائی همه ٔ مال را وارث باشند. (از یادداشت مرحوم دهخدا). هر کس که آنچه را صاحبان فرائض از ارث باقی گذارند بدو رسد، خواه یک تن و خواه بیشتر باشد، و آن بر دو نوع است، نسبی مانند فرزند، و سببی، که مولی و غلام آزاده شده است، خواه مذکر باشد و خواه مؤنث . و نسبی آن بر سه قسم است : عصبه بنفسه، و عصبه بغیره، و عصبه مع غیره . عصبه بنفسه، هر ذکوری است که در نسبت او با شخص متوفی از اناث داخل نباشد. و عصبه بغیره، کسی است که با غیر عصبه شود، مانند زنان که آنان را نصف و ثلثین است که با خواهران خود عصبه شوند. و عصبه مع غیره، هر زنی است که با زنی دیگر عصبه شود، چون خواهر با دختر. و فرق دو تای اخیر در اینست که غیر و دیگری در عصبه بغیره، خود عصبه بنفسه است لذا بسبب آن، عصوبت به انثی هم خواهد رسید. اما در عصبه مع غیره، غیر، خود عصبه ٔاصلی نیست . (از کشاف اصطلاحات الفنون ) (از تعریفات جرجانی ). ج، عَصَبات . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(183845, 'عصبصب', '<span class=\"hlight\">عصبصب .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ص َ ]</font></b> (ع ص ) یوم عصبصب ؛ روز سخت گرم، یا روز سخت . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183846, 'عصبی', '<span class=\"hlight\">عصبی .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ]</font></b> (ص نسبی ) منسوب به عصب . بسیارپی . رجوع به عَصَب شود. <BR><font color=\"Blue\">◄</font> (اصطلاح پزشکی )مربوط به عصب و سیستم اعصاب . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">حالت عصبی </span> ؛ فشار روحی شدید بر اثر ناراحتی بسیار. افتادن بحالت بیهوشی و اغماء بسبب ضربه ٔ روحی ناگهانی و شدید. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">حرکت عصبی </span> ؛ مقابل حرکت تسخیری . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">حمله ٔ عصبی </span> ؛ صرع . (فرهنگ فارسی معین ). رجوع به صرع شود.<br><BR><font color=\"Blue\">◄</font> عصبانی . (فرهنگ فارسی معین ). خشمگین . خشمناک . رجوع به عصبانی شود. <BR><font color=\"Blue\">◄</font> عصبی مزاج . (فرهنگ فارسی معین ). رجوع به عصبی مزاج شود.<br></font></div>'),
(183847, 'عصبی', '<span class=\"hlight\">عصبی .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ بی ی ]</font></b> (ص نسبی ) منسوب به عصبةبن هصیص بن حی است که بطنی از قضاعة باشند. رجوع به عصبة (ابن هصیص ...) و اللباب فی تهذیب الانساب شود.<br></font></div>'),
(183848, 'عصبی مزاج', '<span class=\"hlight\">عصبی مزاج .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ م ِ ]</font></b> (ص مرکب ) کسی که زود عصبانی میشود. کسی که شدیدالتأثر و زودرنج است و در برابر ناملایمات زود از حالت عادی خارج میگردد و تعادل قوای عصبی را از دست میدهد. از نظر پزشکی بیشتر افراد سمپاتیکوتونیک جزو افراد عصبی مزاج هستند. تندمزاج . (فرهنگ فارسی معین ).<br></font></div>'),
(183849, 'عصبیت', '<span class=\"hlight\">عصبیت .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ بی ی َ ]</font></b> (ع اِمص ) عَصَبیّة. حمایت و طرفداری و مدافعه از کسی که خود را به شخص بستگی داده و یا شخص بدان بستگی دارد. (ناظم الاطباء). تعصب، و اصل آن، خصلتی است منسوب به عَصَبة که آن خویشان شخص باشند از جانب پدر، و در واقع آنان کسانی هستند که از حریم جد اعلای خود دفاع کنند: نَبض َ منه عرق ُ العصبیة؛ عصبیت او شعله ور شد و به هیجان آمد. (از اقرب الموارد). طرفداری و استواری و خویشاوندی . (غیاث اللغات ). حمیت و تعصب . (فرهنگ فارسی معین ). حمیت و طرفداری و سختی و میل و رغبت و تعصب و اشتیاق و حب وطن و حب خویشاوندی و قرابت و نسبت، و دستگیری و معاونت و حب مذهب و غیرت و عقاید مذهبی . (ناظم الاطباء) <span class=\"hlight\">:</span> دانی که عداوت و عصبیت میان ایشان تا کدام جایگاهست، افشین و بودلف عجلی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٧٠</span>).<br>چون عصبیت کمر کین گرفت <br>خانه ز پرداختن آیین گرفت .<br> <font color=\"Red\">نظامی .</font><br>عصبیت دین و غیرت پادشاهانه باعث آن شد که حضرت صاحبقرانی عزم گرجستان جزم فرمود. (ظفرنامه ٔ یزدی، از فرهنگ فارسی معین ). تعصب ؛ عصبیت کردن . (منتهی الارب ) (تاج المصادر بیهقی ).<br></font></div>'),
(183850, 'عصد', '<span class=\"hlight\">عصد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) پیچیدن . (از منتهی الارب ) (المصادر زوزنی ). پیچانیدن . (تاج المصادر بیهقی ) (دهار): عصد الشی ٔ؛ آن چیز را پیچاند، درین صورت آن را عصید و مَعصود گویند.(از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آرمیدن با زن . <BR><font color=\"Blue\">◄</font> به ستم گماشتن کسی را بر کاری . (از منتهی الارب ). به اکراه کسی را بر کاری واداشتن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) آب مرد. (منتهی الارب ).<br></font></div>'),
(183851, 'عصد', '<span class=\"hlight\">عصد.</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ص َ ]</font></b> (اِخ ) کوهی است در راه خیبر. (منتهی الارب ).<br></font></div>'),
(183852, 'عصر', '<span class=\"hlight\">عصر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) فشار دادن، و به دست خود فشوردن چیزی را. (از منتهی الارب ). افشردن انگور و زیتون و جز آن . (تاج المصادر بیهقی ). افشردن انگور و جز آن و شیره کردن . (دهار). فشردن و شیره کردن . (ترجمان القرآن جرجانی ): عَصرَ العنب ؛ آب انگور را بیرون آورد. عصر الثوب ؛ آب آن لباس را بوسیله ٔ پیچاندن آن بیرون آورد. عصر الدمل ؛ چرک و ریم دمل را بیرون آورد. (از اقرب الموارد). فشردن .گرفتن آب میوه و جز آن را. (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> بازداشتن . (منتهی الارب ). منع کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پناه گرفتن . و از آن جمله است گفته ٔ خداوندتعالی : «فیه یغاث الناس و فیه یعصرون » (قرآن <span class=\"hlight\" dir=\"rtl\">٤٩/١٢</span>)؛ یعنی نجات می یابند، و آن از عصرة است به معنی منجاة. (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> رستن . (منتهی الارب ) (دهار). <BR><font color=\"Blue\">◄</font> دوشیدن شتر وجز آن . <BR><font color=\"Blue\">◄</font> عطیه دادن . (از منتهی الارب ): عصر فلاناً؛ او را عطیه داد. <BR><font color=\"Blue\">◄</font> به عرق آوردن : عصر الرکض ُ الفرس َ؛ دویدن اسب را عرقناک کرد. <BR><font color=\"Blue\">◄</font> خشک گردانیدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> حبس کردن . (از اقرب الموارد) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِمص ) فشارش . (فرهنگ فارسی معین ).<br></font></div>'),
(183853, 'عصر', '<span class=\"hlight\">عصر.</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ]</font></b> (اِخ ) ابن عوف بن عمرو، از بنی أفصی بن عبدالقیس . جدی است جاهلی و بسیاری به وی نسبت دارند، از آن جمله است منذربن عائذ صحابی، که به أشج عصری شهرت دارد، و خلیدبن حسان عصری . (از الاعلام زرکلی از اللباب ).<br></font></div>'),
(183854, 'عصر', '<span class=\"hlight\">عصر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) سوره ٔ صدوسوم از قرآن کریم . مکیه است و دارای سه آیت . پس از سوره ٔ تکاثر و پیش از سوره ٔ هُمَزة قرار دارد و آغاز میشود به «و العصر...».<br></font></div>'),
(183855, 'عصر', '<span class=\"hlight\">عصر.</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ]</font></b> (ع اِ) بامداد. <BR><font color=\"Blue\">◄</font> شبانگاه . (منتهی الارب ). از عَشی ّ تا سرخ شدن آفتاب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نماز دیگر. <BR><font color=\"Blue\">◄</font> زندان . <BR><font color=\"Blue\">◄</font> گروه و قبیله . <BR><font color=\"Blue\">◄</font> باران ریزان . عطیه . (منتهی الارب ). عَصْر. و رجوع به عَصْر شود. <BR><font color=\"Blue\">◄</font> پناه جای و جای رهایی . (منتهی الارب ). ملجاء ومنجاة. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گرد. (منتهی الارب ). غبار. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ما بینهماعصر و لا یصر و لا أعصر و لا أیصر؛ مابین آنها دوستی و مودت است نه خویشی و قرابت . (از اقرب الموارد).<br>- <span class=\"hlight\">بنوعصر</span> ؛ نام قبیله ای از تازیان است . (ناظم الاطباء).<br></font></div>'),
(183856, 'عصر', '<span class=\"hlight\">عصر.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) روزگار و دهر و زمانه . (از منتهی الارب ) (از اقرب الموارد). عصر <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ص ُ ]</font></b> . رجوع به عصر شود. <BR><font color=\"Blue\">◄</font> نماز دیگر. (منتهی الارب ). نماز عصر. <BR><font color=\"Blue\">◄</font> وقت عصر. رجوع به عَصر شود.<br></font></div>'),
(183857, 'عصر', '<span class=\"hlight\">عصر.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) کوهی است میان مدینه و وادی فرع . (منتهی الارب ). جبلی است بین مدینه و وادی الفرع . و گویند پیامبر (ص ) هنگامی که از مدینه به خیبر برای غزو میرفت راه عصر را پیمود و در آنجا مسجدی نیز دارد. (از معجم البلدان ).<br></font></div>'),
(183858, 'عصر', '<span class=\"hlight\">عصر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) روزگار و دهر و زمانه . (از منتهی الارب ) (از اقرب الموارد). عصر <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ص ُ ]</font></b> .رجوع به عصر شود. <BR><font color=\"Blue\">◄</font> نماز دیگر. (منتهی الارب ). نماز عصر. رجوع به عَصر شود. <BR><font color=\"Blue\">◄</font> جای پناه و رهائی . (منتهی الارب ). منجاة. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> جاء لکن کلم یجی ٔ لعصر؛ آمد ولی آنگاه که باید بیاید نیامد. نام ما نام لعصر؛ پیوسته و هنوز خفته است . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183859, 'عصر', '<span class=\"hlight\">عصر.</span><font color=\"DarkGreen\"><b>[ ع ُ ص ُ ]</font></b> (ع اِ) روزگار و زمانه . (از منتهی الارب ).عصر <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ]</font></b> . رجوع به عَصْر شود. <BR><font color=\"Blue\">◄</font> ج ِ عصر. (منتهی الارب ) (اقرب الموارد). رجوع به عَصر شود. <BR><font color=\"Blue\">◄</font> نماز دیگر. (منتهی الارب ). نماز عصر. <BR><font color=\"Blue\">◄</font> وقت عصر. رجوع به عَصر شود.<br></font></div>'),
(183860, 'عصر', '<span class=\"hlight\">عصر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبیدبن وائلةبن جاریةبن ضبیعة. جدی است جاهلی و بطنی از بلی را تشکیل میدهد. و آن را بکسر «ع » و ایضاً بفتح «ع » و«ص » نیز خوانده اند. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(183861, 'عصر', '<span class=\"hlight\">عصر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) روز. (منتهی الارب ). یوم .(اقرب الموارد). <BR><font color=\"Blue\">◄</font> شب . (منتهی الارب ). لیل . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آخر روز تا سرخ شدن آفتاب . (منتهی الارب ). عَشی ّ تا سرخ شدن آفتاب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آخر روز تا هنگام غروب . (فرهنگ فارسی معین ). پسین . (ملخص اللغات حسن خطیب کرمانی ). دیگر. (مهذب الاسماء). آخر روز. (غیاث اللغات ) (دهار). دشم . (ناظم الاطباء). عبرانیان برای هر روز دو عصر قرار میدادند، عصر اول وقتی است که آفتاب شروع به فرورفتن مینماید یعنی از ساعت نهم از روز شروع میشود، و شروع عصر دوم حقیقی از غروب صحیح آفتاب است . (از قاموس کتاب مقدس ) <span class=\"hlight\">:</span> و العصر، اًن الانسان لفی خسر (قرآن <span class=\"hlight\" dir=\"rtl\">١/١٠٣</span> و <span class=\"hlight\" dir=\"rtl\">٢</span>)؛ سوگند به عصر که انسان در زیانکاری است .<br>چو از شب گشت مشکین روی آن عصر<br>ز مشکو رفت شیرین سوی آن قصر.<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">صلاة (نماز) عصر</span> ؛ نماز دیگر. (مهذب الاسماء). نماز پسین . نماز دوم . (ناظم الاطباء). نماز بعد پیشین . (یادداشت مرحوم دهخدا). در حدیث است : «صلاة العصر حین صار ظل کل شی ٔ مثله »؛ یعنی نماز عصر وقتی است که سایه ٔهر چیز مانند خود آن چیز شود. و در حدیث دیگر: «آخروقت الظهر ان یصیر ظل کل شی ٔ مثله و لایکون ذلک وقتاً للعصر حتی یزید الظل أقل زیادة»؛ یعنی آخرین وقت ظهر اینست که سایه ٔ هر چیز به اندازه ٔ خود آن چیز شود، و وقت عصر موقعی است که سایه ٔ آن اندکی افزوده گردد. (از منتهی الارب ).<br>- <span class=\"hlight\">عصر تنگ </span> ؛ در اصطلاح عامیانه، عصر، آن وقت که هوا تاریک شود. (فرهنگ فارسی معین ).<br> <BR><font color=\"Blue\">◄</font> بامداد. (منتهی الارب ). غداة. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نماز دیگر. (منتهی الارب ) (دهار). نمازی که در عصر خوانند. صلاة عصر. (فرهنگ فارسی معین ). اسم است نماز را، و با کلمه ٔ «صلاة» مؤنث بکار رود و بدون آن تذکیر و تأنیث آن هر دو جایز است . گویند: هذه العصر، و آن توسعاً به معنی صلاة العصر است . (از اقرب الموارد). ج، أعْصُر، عُصور. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> روزگار. (منتهی الارب ) (دهار). دهر. (اقرب الموارد). زمانه . (دستور اللغه ). روزگار و زمانه . (غیاث اللغات ). زمان و روزگار و دوره : عنصری از شاعران عصر غزنوی است . (فرهنگ فارسی معین ). عصر <font color=\"DarkGreen\"><b>[ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ص ُ ]</font></b> . ج، عُصور، أعصُر، عُصُر، أعصار. (منتهی الارب ) (اقرب الموارد). و جمعاعصار، أعاصر باشد. (از اقرب الموارد) <span class=\"hlight\">:</span> <br>ز گیتی پرستنده ٔ فر نصر<br>زیَد شاد در سایه ٔ شاه عصر.<br> <font color=\"Red\">فردوسی .</font><br>جهاندار سالار او میر نصر<br>کزو شادمان است گردنده عصر.<br> <font color=\"Red\">فردوسی .</font><br>پس از این عصر مردمان دیگر عصرها به آن رجوع کنند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٨٧٠</span>). جالینوس بزرگتر حکمای عصر خویش بود. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٤٥</span>). غرض من نه آن است که مردم این عصر را بازنمایم حال سلطان مسعود... که وی را دیده اند.(تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٦٥</span>).<br>ز اهل عصر چه خواهم که اهل عصر همه <br>به خوی و طبع ستوران ماده را مانند.<br> <font color=\"Red\">مسعودسعد.</font><br>علوم عالم دانم ولیکن اندر عصر<br>اگر دو مردم دانم بدان که نادانم .<br> <font color=\"Red\">مسعودسعد.</font><br>دیگر سلاطین دولت میمون را که خداوند عالم پادشاه عصر... فضایل و مناقب بسیار است . (کلیله و دمنه ).<br>تو مرفه عیش و بدخواهان تو<br>یافته از نائبات عصر عصر.<br> <font color=\"Red\">سوزنی .</font><br>دادن تشریف تو از پی تعریف شاه <br>بر سر ابنای عصر کرده مرا نامدار.<br> <font color=\"Red\">خاقانی .</font><br>اهل خواهی ز اهل عصر ببُر<br>انس خواهی میان انس مپوی .<br> <font color=\"Red\">خاقانی .</font><br>خاقانیا وفا مطلب زَاهل عصر از آنک <br>در تنگنای دهر وفا تنگیاب شد.<br> <font color=\"Red\">خاقانی .</font><br>یکی علامه ٔ عصر گشت و دیگری عزیز مصر شد. (گلستان ). من او را از فضلای عصر... میدانم . (گلستان ). <BR><font color=\"Blue\">◄</font> هر یک از تقسیمات کوچکتر از دوران (عهد) در زمین شناسی که شامل چندین طبقه میباشد، و آن دارای آثار و بقایای گیاهی و جانوری مشخص است و اغلب رسوباتش در نقاط مختلف مشابهند. دوره . توضیح اینکه گاهی کلمه ٔ عصر را در برخی نوشته ها و کتب جهت تقسیمات کوچکتر از دوره و حتی تقسیمات کوچکتر بکار برده اند و به این ترتیب برای کلمه ٔ عصر، یک زمان مشخص زمین شناسی نمیتوان قائل شد، به این جهت میتوان کلمه ٔ عصر را در زمین شناسی مرادف با تقسیمات مختلف ذکر کرد از قبیل عصر حجر قدیم و یا عصر حجر جدید که هر دو تقسیماتی کوچکتر از عصر حجر هستند و یا عصر آهن و عصر مفرغ که هر دو تقسیماتی کوچکتر از دوره ٔ فلزات میباشند. (از فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصر آهن </span> ؛ قسمتی از دوره ٔ فلزات است که شامل زمان کنونی نیز میشود. این عصر از زمان پیدایش آهن که تقریباً یکهزاروپانصد سال قبل از میلاد مسیح است شروع میشود و تاکنون ادامه دارد. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصر اتم </span> ؛ مقصود زمان کنونی است و شروعش از زمان استفاده از نیروی اتمی در صنایع بشر است که تقریباً ازسال <span class=\"hlight\" dir=\"rtl\">١٩٤٥</span> م . شروع میشود. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصر حجر</span> ؛ قسمت اعظم دوران چهارم زمین شناسی متعلق به این عصر است که از طبقات فوقانی دوره ٔ اول دوران چهارم شروع و به ابتدای عصرفلزات ختم می شود. این عصر به دو دوره ٔ حجر قدیم (پارینه سنگی ) و حجر جدید (نوسنگی ) تقسیم می شود. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصر طلایی </span> ؛ دوره ای در تاریخ یک کشور که ادبیات و علوم و صنایع و عوامل دیگر تمدن ترقی کامل کرده باشد، مثل دوره ٔ «پریکلیس » در یونان قدیم . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصر مفرغ </span> ؛ قسمت ابتدائی دوره ٔ فلزات است که از زمان پیدایش فلزات شروع و به دوره ٔ آهن ختم میشود. ابتدای این عصر قریب پنج هزار سال قبل از میلاد مسیح است . (فرهنگ فارسی معین ).<br> <BR><font color=\"Blue\">◄</font> زندان . (منتهی الارب ) <span class=\"hlight\">:</span> <br>گرچه دزد از منکری دم میزند<br>شحنه آن از عصر پیدا میکند.<br> <font color=\"Red\">مولوی .</font><br> <BR><font color=\"Blue\">◄</font> گروه و قبیله . (منتهی الارب ). رهط و عشیره . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> باران ریزان . (منتهی الارب ). باران که از ابرهای معصرات بارد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عطیه . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نسب، گویند: فلان کریم العصر؛ یعنی بزرگ نسب است . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> جأنی فلان عصراً؛ یعنی او بطی ٔ و دیر نزد من آمد. (از اقرب الموارد) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> فشار. (ناظم الاطباء) (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>تو مرفه عیش و بدخواهان تو<br>یافته از نائبات عصر عصر.<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(183862, 'عصرآباد', '<span class=\"hlight\">عصرآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان سرشیو بخش مریوان شهرستان سنندج . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> تن . آب آن از چشمه . محصول آن غلات، حبوب، لبنیات و توتون است . این ده در دو محل نزدیک بهم بنام عصرآباد جدید و عصرآباد کهنه واقع است . سکنه ٔ عصرآباد جدید <span class=\"hlight\" dir=\"rtl\">٢٤٠</span> تن است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(183863, 'عصرآباد', '<span class=\"hlight\">عصرآباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان رستاق بخش اشکذر شهرستان یزد. سکنه <span class=\"hlight\" dir=\"rtl\">١٨٩</span> تن . آب آن از قنات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(183864, 'عصراد', '<span class=\"hlight\">عصراد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) مرد دشوارخوی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> امر بزرگ و دشوار، و آن لغتی است در عصواد. (از منتهی الارب ). رجوع به عصواد شود.<br></font></div>'),
(183865, 'عصران', '<span class=\"hlight\">عصران .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) مثنای عصر (در حالت رفعی ). رجوع به عصر شود. <BR><font color=\"Blue\">◄</font> شب و روز. (منتهی الارب ). لیل و نهار. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بامداد و شبانگاه . (منتهی الارب ).غداة و عَشی ّ. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نماز ظهر و عصر. (ناظم الاطباء). نماز فجر و نماز عصر، که از آن جمله است «حافظ علی العصرین ». (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> طعام چاشت و طعام شام . (آنندراج ).<br></font></div>'),
(183866, 'عصرانه', '<span class=\"hlight\">عصرانه .</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) غذائی که هنگام عصر خورند. (فرهنگ فارسی معین ).میوه و نقل که عصر خورند. (یادداشت مرحوم دهخدا).<br></font></div>'),
(183867, 'عصری', '<span class=\"hlight\">عصری .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب به عَصر. آخر روز و پسین و نزدیک شبانگاه . (ناظم الاطباء). رجوع به عصر شود. <BR><font color=\"Blue\">◄</font> منسوب به عصربن عبیدبن وائله است که بطنی از بلی را تشکیل می دهند. رجوع به عصر (ابن عبید...) و اللباب فی تهذیب الانساب شود.<br></font></div>'),
(183868, 'عصری', '<span class=\"hlight\">عصری .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ]</font></b> (ص نسبی ) منسوب به قبیله ٔ بنی عصر. (ناظم الاطباء). رجوع به عصر (ابن عبیدبن ...) و عَصَر شود.<br></font></div>'),
(183869, 'عصص', '<span class=\"hlight\">عصص .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ]</font></b> (ع مص ) سخت و شدید شدن . (از اقرب الموارد). عَص ّ. رجوع به عص شود.<br></font></div>'),
(183870, 'عصص', '<span class=\"hlight\">عصص .</span> <font color=\"DarkGreen\"><b>[ ع ُ ص َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ص ُ ]</font></b> (ع اِ) بن دم و اصل آن . (ناظم الاطباء) (از اقرب الموارد). عصعص . (منتهی الارب ). رجوع به عصعص شود.<br></font></div>'),
(183871, 'عصعص', '<span class=\"hlight\">عصعص .</span> <font color=\"DarkGreen\"><b>[ ع ُ ص َ ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ع َ ]</font></b> (ع اِ) عُصعُص است به معنی استخوان دنب . (از اقرب الموارد) (از منتهی الارب ). رجوع به عُصعص شود.<br></font></div>'),
(183872, 'عصعص', '<span class=\"hlight\">عصعص .</span> <font color=\"DarkGreen\"><b>[ ع ُ ع ُ ]</font></b> (ع اِ) گوشت باطن الیه ٔ گوسپند یا بن دم و استخوان دمغزه . (منتهی الارب ). استخوان مابین هر دو سرین قریب از مقعد. (غیاث اللغات ) (آنندراج ). عَجب و استخوان دم . (از اقرب الموارد). مهره هاست که نشستن مردم بر آن باشد... و عدد آن سه است، و این سه مهره نرمتر از استخوان است و مانند غضروفی است . (ذخیره ٔ خوارزمشاهی ). استخوان تیز که نشست مردم بدان بود. (مهذب الاسماء). آن از سه فقره ٔ غضروفی تشکیل شده که زوائد ندارد و عصب از سوراخ مشترکی که در آن است خارج میشود همانطور که در گردن است . و اما از انتهای فقره ٔ سوم آن عصبی فرد خارج میگردد. (از قانون ). استخوانی است کوچک مثلث واقع در انتهای تحتانی عجز که نسبت به آن حکم دنباله دارد و تا مدتی بعد از ولادت هم قطعات آن ملتئم نمیشوند و به جهت آن دو سطح و دو ضلع و قاعده و نقطه معین است . سطح قدامی آن مقعر است و از رباط عجز و عصعصی مقدم پوشیده شده و سه خط عرضی درآن مشاهده میشود که موضع التیام قطعاتی اند که در ابتدای فقره بوده اند. سطح خلفی محدب و بهمین قسم خطوط عرضیه در آن مرئی میگردند و عضله ٔ سرین و رباط عجزی عصعص خلفی به آن متصل میشوند، در دو کنار آن فزونیهااست بجهت اتصال رباطهای عجزی نسائی و عضلات ورکی عصعصی، قاعده ٔ آن دارای سطحی است بیضی و در آن دو قرن دیده میشود که با عظم عجز اتصال مفصلی دارند. در نقطه ٔ آن زائده ای است که عضله ٔ مضیقه شرج به آن متصل میشود. (تشریح میرزا علی ص <span class=\"hlight\" dir=\"rtl\">٤٣</span>). آخرین استخوان ستون مهره ای که در انسان از التیام چهار یا پنج مهره به وجود آمده . وجود این استخوان در انسان بجای دم در حیوانات میباشد. در جانوران تعداد مهره های استخوان دنبالچه متعدد است و آنها اسکلت دم را تشکیل میدهند. (فرهنگ فارسی معین ). عصعص <font color=\"DarkGreen\"><b>[ ع َ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ص َ ع ِ ]</font></b> . عُصعوص . عَجب . عجم . عسیب . عسیبة. غازه . دنبالچه . دنبلچه . دنبلیچه . دمبلچه . دمبلیچه . دم غازه . دم غزه . دنب غازه . دمغزه . دمچه . ج، عَصاعِص، عَصاعیص . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) مرد کم خیر دشوارخوی . <BR><font color=\"Blue\">◄</font> گرداندام استوارخلقت . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183873, 'عصعوص', '<span class=\"hlight\">عصعوص .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) استخوان بن دم و دمغزه . (از منتهی الارب ) (از اقرب الموارد). عُصعص . رجوع به عصعص شود.<br></font></div>'),
(183874, 'عصف', '<span class=\"hlight\">عصف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) سخت وزیدن باد. (از منتهی الارب ) (دهار). باد سخت جستن . (تاج المصادر بیهقی ). سخت جستن باد. (المصادر زوزنی ): عصفت الریح ؛ باد سخت شد، و چنین بادی را عاصف و عاصفة گویند. (از اقرب الموارد). عُصوف . و رجوع به عصوف شود <span class=\"hlight\">:</span> فالعاصفات عصفاً (قرآن <span class=\"hlight\" dir=\"rtl\">٢/٧٧</span>)؛ و تندوزنده ها تندوزیدنی . <BR><font color=\"Blue\">◄</font> نارسیده درودن کشت را. (از منتهی الارب ): عصف الزرع ؛ کشت را قبل از اینکه برسد، برید. (ازاقرب الموارد). <BR><font color=\"Blue\">◄</font> کسب کردن جهت عیال . (از منتهی الارب ): عصف فلان عیاله ؛ او برای خانواده ٔ خودکسب کرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بردن و هلاک کردن جنگ گروهی را. (از منتهی الارب ): عصفت الحرب بالقوم ؛ جنگ آن قوم را از بین برد و هلاک کرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خمیدن . (از منتهی الارب ). مایل شدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بشتافتن و سرعت نمودن . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183875, 'عصف', '<span class=\"hlight\">عصف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) سبزه و برگ کشت .(منتهی الارب ). برگ کشت . (دهار) (ترجمان القرآن جرجانی ). برگ درخت و گیاه . (مخزن الادویة). ورق زرع . (اقرب الموارد) <span class=\"hlight\">:</span> و الحب ذو العصف و الریحان (قرآن <span class=\"hlight\" dir=\"rtl\">١٢/٥٥</span>)؛ و دانه دارای برگ و رستنیی خوشبوی . فجعلهم کعصف مأکول (قرآن <span class=\"hlight\" dir=\"rtl\">٥/١٠٥</span>)؛ قرار داد آنان را مانند کشتی که دانه ٔ آن را خورده باشند و کاه آن مانده باشد، و یا مانند برگی که دانه های آن را گرفته باشند و بدون دانه مانده باشد، و یا مانند برگی که چهارپایان خورده باشند، و یا مانند ریزه های گیاه که از آن شکسته باشد. (از منتهی الارب ) (از اقرب الموارد). مانند برگ کشت شنگرف زده . (دهار). <BR><font color=\"Blue\">◄</font> کاه . (منتهی الارب ). حطام و ریزه های کاه . (از اقرب الموارد).<br></font></div>'),
(183876, 'عصفة', '<span class=\"hlight\">عصفة.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع اِ) اسم المرة است از مصدر عصف . (از اقرب الموارد). رجوع به عصف شود. <BR><font color=\"Blue\">◄</font> عصفةالخمر؛ بوی شراب . (منتهی الارب ). گویند: للخمر عصفة؛یعنی آن شراب را رایحه ای است . (از اقرب الموارد).<br></font></div>'),
(183877, 'عصفر', '<span class=\"hlight\">عصفر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ف ُ ]</font></b> (ع اِ) گیاهی است که گوشت درشت را زرد و نرم سازد، و تخم آن را قرطم نامند. (منتهی الارب ). نباتی است که گوشت رانرم میکند، و آن را بهرمان نیز نامند و تخم آن قرطم است . (از اقرب الموارد). گل کاجیره که به هندی کسنبه گویند، و جامه ای که به رنگ آن سرخ شود، آن را معصفر گویند. (غیاث اللغات ) (آنندراج ). به پارسی خسق خوانند و به اصفهانی گل کاویشه، و رنگ زعفران نیز گویند، گل کاجیره هم خوانند و آن دو نوع است، بری و بستانی، و طبیعت بستانی گرم است در اول و خشک در دوم، و بری گرم و خشک بود در سوم . (از اختیارات بدیعی ). آن را به لغت تازی احریض و خوبع نیز گویند. (از تذکره ٔ ضریر انطاکی ). شکوفه ای است . (نزهةالقلوب ). احریض است .(تحفه ٔ حکیم مؤمن ). گیاهی است یک ساله یا دوساله ازتیره ٔ مرکبان که دارای ساقه ای به ارتفاع <span class=\"hlight\" dir=\"rtl\">٥٠</span> سانتیمتر است . منشاء اولیه ٔ این گیاه را عربستان ذکر کرده اند ولی امروزه در نقاط دیگر نیز کشت میشود. برگهای این گیاه نرم و دندانه دار و پوشیده از تیغهای ظریف و نازک است . در سطح پهنک آن (مخصوصاً سطح تحتانی پهنک ) رگبرگهای برجسته مشاهده میشود. گلهایش منفرد و شامل برگه های خاردار در پائین کاسه و گلهای لوله ای به رنگ زرد یا ارغوانی بر روی نهنج است . میوه اش فندقه و دارای دسته ٔ تار نازک در قسمت انتهائی است . از گلبرگهای این گیاه ماده ای به رنگ زرد زیبا و محلول در آب و ماده ٔ دیگری به رنگ قرمز بنام کارتامین که آن نیز درآب محلول است به دست آورده اند. دانه ٔ این گیاه که به کافشه موسوم است شامل <span class=\"hlight\" dir=\"rtl\">٣٠</span> تا <span class=\"hlight\" dir=\"rtl\">٣٧</span> درصد از مواد پروتیدی و <span class=\"hlight\" dir=\"rtl\">٤٥</span> تا <span class=\"hlight\" dir=\"rtl\">٤٦</span> درصد از مواد چربی است که پس از تصفیه می تواند مورد مصرف قرار گیرد. گل و مخصوصاً دانه های آن دارای اثر مسهلی است که به صورت جوشانده <span class=\"hlight\" dir=\"rtl\">١٢</span> تا <span class=\"hlight\" dir=\"rtl\">٢٤</span> در هزار مصرف می شود. از دانه های این گیاه روغنی استخراج می کنند که دارای اثر مسهلی است و سابقاً بصورت مالیدن بر روی عضو در روماتیسم و فلج مورد استفاده قرار می گرفت . این گیاه در اکثر نقاط جنوبی اروپا و مناطق بحرالرومی و آسیای صغیر و شمال افریقا و ایران میروید (در خراسان و تبریز و تفرش فراوان است ). توضیح اینکه دانه ٔ این گیاه را خسک دانه و حب العصفر نیز نامند و آن بعنوان مسهل در طب قدیم مصرف میشده است و در بازار بنام تخم کاجیره نیز عرضه میشود. و ماده ٔ رنگین که از گلبرگهای این گیاه استخراج میشود بنام زردج و ماءالعصفر مشهور است . (فرهنگ فارسی معین : کاجیره ). احریض . اصبور. اصفور. اطرقطوس . بهرام . بهرامن . بهرامة. بهرم . بهرمان . پالان زعفران . تاقالا. ترباض . خریع. خسک . خسک دانه . زرد. زردج . زردک . زرده . زعفران کاذب . سکری . فنیفس . قرطم . قنطادوس . کابیج . کاجره . کاجیر. کاچره . کاچوره . کاچیره . کازیره . کاژیره . کاغاله . کافشه . کافیشه . کرکم . گل رنگ . گل زردک . گل قرطم . گل کاغاله . مریق . نقده . و رجوع به کاجیره و قرطم شود.<br>- <span class=\"hlight\">عصفر بری </span> ؛ نوع بادآورد آن است . (از فهرست مخزن الادویة و تحفه ٔ حکیم مؤمن ).خلاف بلخی . بهرامج البر. رنف . (الجماهر بیرونی ). یکی از گونه های کاجیره است که بطور خودرو در مزارع میروید و برگهایش دارای کرک میباشد. زعفران بیابانی . قرطم بری . کاجیره ٔ صحرایی . (فرهنگ فارسی معین ).<br><BR><font color=\"Blue\">◄</font> رنگ سرخ . (منتهی الارب ) (فرهنگ فارسی معین ). رنگی است . (از اقرب الموارد).<br></font></div>'),
(183878, 'عصفری', '<span class=\"hlight\">عصفری .</span> <font color=\"DarkGreen\"><b>[ ع ُ ف ُ ]</font></b> (اِخ ) خلیفةبن خیاطبن خلیفه ٔ شیبانی عصفری بصری، مکنی به ابوعمر و مشهور به شباب . محدث و نسابه و اخباری بود و به سال <span class=\"hlight\" dir=\"rtl\">٢٤٠</span> هَ .ق . درگذشت . او را کتاب تاریخی است در ده جزء، و کتاب الطبقات در هشت جزء. (از الاعلام زرکلی از تذکرةالحفاظ و الوفیات ).<br></font></div>'),
(183879, 'عصفری', '<span class=\"hlight\">عصفری .</span> <font color=\"DarkGreen\"><b>[ ع ُ ف ُ ]</font></b> (اِخ ) نام اسب محمدبن یوسف برادر حجاج است که از نسل حرون بوده است . (از منتهی الارب ).<br></font></div>'),
(183880, 'عصفور', '<span class=\"hlight\">عصفور.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) نام او حسین بن محمدبن احمدبن عصفور شاخوری بحرانی است . او فقیه قرن دوازدهم هجری می باشد. رجوع به حسین عصفوری و عصفوری (حسین بن ...) شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(183881, 'عصفور', '<span class=\"hlight\">عصفور.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) گنجشک . (منتهی الارب ) (دهار). گنجشک نر. (ناظم الاطباء). پرنده ای است . (از اقرب الموارد). بفارسی گنجشک و به ترکی سرچه نامند. (از تحفه ٔ حکیم مؤمن ). بپارسی گنجشک خوانند و نیکوترین آن فربه بود و آنچه در خانه فربه شود بد بود، اولی آن بود اجتناب کنند در خوردن آن . (از اختیارات بدیعی ). ماده ٔ آن را عصفورة گویند، و کنیه ٔ آن ابوالصَّفْو و ابومحرز و ابومزاحم و ابویعقوب است، و آن را عصفور گویند لأنه عَصی و فرّ (عصیان کرد و فرار کرد). آن را انواع بسیار است، مشهورتر آن «دوری » است . و آشیانه ٔ او در آبادیها و زیر سقفها است و آن از بیم جوارح و پرندگان شکاری است، لذا هرگاه شهری خالی از سکنه شود گنجشکان نیز آنجا را تخلیه می کنند. فضله انداختن او بسیار است و گاه به یکصد بار در ساعت میرسد. (از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٤</span>). چغک . (بحر الجواهر). بنجشک . ج، عَصافیر. (منتهی الارب ) (اقرب الموارد). رجوع به گنجشک شود <span class=\"hlight\">:</span> <br>طعمه ٔ شیر کی شود راسو<br>مسته ٔ چرغ کی شود عصفور.<br> <font color=\"Red\">مسعودسعد.</font><br>برگ نارنج و شاخ پنداری <br>پر طوطی و ساق عصفور است .<br> <font color=\"Red\">مسعودسعد.</font><br>عقابان تیزچنگالند و بازان آهنین پنجه <br>ترا باری چنین بهتر که با عصفور بنشینی .<br> <font color=\"Red\">سعدی .</font><br>اگر سیمرغی اندر دام زلفی <br>بماند تاب عصفوری ندارد.<br> <font color=\"Red\">سعدی .</font><br>آخر ز هلاک ما چه خیزد<br>سیمرغ چه میکند به عصفور.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">عصفور ملکی </span> ؛ نوعی گنجشک که از همه ٔ انواع خردتر است . پرنده ای است که از آن خردتر هیچ پرنده نباشد. صفراغون . رجوع به صفراغون شود.<br><BR><font color=\"Blue\">◄</font> هر پرنده که از کبوتر کوچکتر باشد. (ازاقرب الموارد). هر پرنده ٔ کوچک جثه ٔ پرصفیر. (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> ملخ نر. (منتهی الارب ) (دهار) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چوبی است در هوده که اطراف چوبها بدان جمع شود. <BR><font color=\"Blue\">◄</font> چوبهای پالان که سرهای احناء بدان بندند. <BR><font color=\"Blue\">◄</font> چوبی که سر پالانها به آن بسته گردد. <BR><font color=\"Blue\">◄</font> اصل روئیدنگاه موی پیشانی . <BR><font color=\"Blue\">◄</font> استخوان برآمده درپیشانی اسب . (منتهی الارب ) (از اقرب الموارد). استخوان تند بر روی اسب . (دهار). و چپ و راست آن را عصفوران گویند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پاره ای از مغز سر که در میانش پوستکی است که از هم جدا دارد آنرا. (منتهی الارب ) (از اقرب الموارد). پاره از دماغ . (دهار). <BR><font color=\"Blue\">◄</font> سفید باریک فروریخته از غره ٔاسب . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کتاب . <BR><font color=\"Blue\">◄</font> میخ کشتی . (منتهی الارب ) (دهار) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پادشاه . (منتهی الارب ) (دهار). ملک . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مهتر.(منتهی الارب ). سید. <BR><font color=\"Blue\">◄</font> ولد و فرزند، و آن لغتی است یمانی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گرسنگی . <BR><font color=\"Blue\">◄</font> نوعی از درخت که او را صورتی همچو صورت گنجشک بود. (دهار).<br>- <span class=\"hlight\">لسان العصفور</span> ؛ تخم شنگ . (دهار).<br></font></div>'),
(183882, 'عصفورالاکاف', '<span class=\"hlight\">عصفورالاکاف .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُل ْ اِ ]</font></b> (ع اِ مرکب ) چوبی است که در میان پشم آگند بندند. (منتهی الارب ).<br></font></div>'),
(183883, 'عصفورالجنة', '<span class=\"hlight\">عصفورالجنة.</span> <font color=\"DarkGreen\"><b>[ ع ُ رُل ْ ج َن ْ ن َ ]</font></b> (ع اِ مرکب ) خطاف . (تحفه ٔ حکیم مؤمن ) (فهرست مخزن الادویة). فراشتوک . چلچله . رجوع به خطاف و چلچله شود.<br></font></div>'),
(183884, 'عصفورالسیاح', '<span class=\"hlight\">عصفورالسیاح .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُس ْ س َی ْ یا ]</font></b> (ع اِ مرکب ) (الَ ...) صفراغون . (تحفه ٔ حکیم مؤمن ). عصفورالشوک . طرغلودیس . رجوع به طرغلودیس شود.<br></font></div>'),
(183885, 'عصفورالشوک', '<span class=\"hlight\">عصفورالشوک .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُش ْ ش َ ]</font></b> (ع اِ مرکب ) نُغَر. (تحفه ٔ حکیم مؤمن ). صفراغون . (مخزن الادویة). عصفورالسیاح . (اختیارات بدیعی ). دم جنبانک . (فرهنگ فارسی معین ). طرغلودیس . رجوع به طرغلودیس شود.<br></font></div>'),
(183886, 'عصفورالصباغ', '<span class=\"hlight\">عصفورالصباغ .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُص ْ ص َب ْ با ]</font></b> (ع اِ مرکب ) (الَ ...) صفراغون . (فهرست مخزن الادویة). رجوع به صفراغون شود.<br></font></div>'),
(183887, 'عصفوران', '<span class=\"hlight\">عصفوران .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) مثنای عصفور. رجوع به عصفور شود. <BR><font color=\"Blue\">◄</font> دو استخوان از دو طرف روی اسب . (منتهی الارب ) (از اقرب الموارد). رجوع به عصفور شود.<br></font></div>'),
(183888, 'عصفوری', '<span class=\"hlight\">عصفوری .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ص نسبی )منسوب به عصفور. رجوع به عصفور شود. <BR><font color=\"Blue\">◄</font> گنجشک فروش . <BR><font color=\"Blue\">◄</font> شتری است دوکوهان . (منتهی الارب ): جمل عصفوری ؛ شتر دوکوهان . (از اقرب الموارد).<br></font></div>'),
(183889, 'عصفوری', '<span class=\"hlight\">عصفوری .</span> <font color=\"DarkGreen\"><b>[ع ُ ]</font></b> (اِخ ) ابوالحسن بن شیبةبن صلت بن عصفور سدوسی عصفوری . از محدثان ساکن بغداد بود و از یزیدبن هارون و حسن بن موسی اشیب روایت کرده است . وی در ربیعالاول سال <span class=\"hlight\" dir=\"rtl\">٢٧٢</span> هَ .ق . درگذشت . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(183890, 'عصفوری', '<span class=\"hlight\">عصفوری .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) حسین بن محمدبن احمد شاخوری بحرینی . محدث و فقیه قرن دوازدهم هجری . رجوع به حسین عصفوری و الاعلام زرکلی و شهداء الفضیلة شود.<br></font></div>'),
(183891, 'عصفوری', '<span class=\"hlight\">عصفوری .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) یعقوب بن شیبةبن صلت عصفوری بصری، مکنی به ابویوسف . محدث بود و حدیث را نزد یزیدبن هارون و عنان بن مسلم و ابونعیم آموخت . وی در ربیعالاول سال <span class=\"hlight\" dir=\"rtl\">٢٦٢</span> هَ .ق . درگذشت . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(183892, 'عصقول', '<span class=\"hlight\">عصقول .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) نره ٔ ملخ . (منتهی الارب ). ذکر جراد. ج، عَصاقیل . (اقرب الموارد).<br></font></div>'),
(183893, 'عصل', '<span class=\"hlight\">عصل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) خمیدن . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> کژ گردانیدن، گویند: عصل العود؛ یعنی کژ گردانید چوب را، و اگر کجیش سرشتی باشد فعلش از باب سمع آید. (از منتهی الارب ). کژ گردانیدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شاش کردن . (از ناظم الاطباء): عصل الصبی ؛ آن کودک ادرار و بول کرد. (از اقرب الموارد). آب تاختن .<br></font></div>'),
(183894, 'عصل', '<span class=\"hlight\">عصل .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ]</font></b> (ع مص ) کج گردیدن با سختی و صلابت و خشکی سرشتی . (از اقرب الموارد) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> عصل الفرس ؛ بن دم آن اسب کج گردید و تا بالای ران او رسید، و چنین اسبی را عَصِل و أعصَل گویند. <BR><font color=\"Blue\">◄</font> عصل السهم ؛ آن تیر در پرتاب خمیده شد. (از اقرب الموارد).<br></font></div>'),
(183895, 'عصل', '<span class=\"hlight\">عصل .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ]</font></b> (ع اِ) روده . (منتهی الارب ). مِعی ̍. (اقرب الموارد). عِصل . ج، أعصال . (منتهی الارب ) (اقرب الموارد). و رجوع به عِصل شود. <BR><font color=\"Blue\">◄</font> گیاه دفلی . (منتهی الارب ) (از اقرب الموارد). خرزهره و دفلی . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِمص ) کژی و التواء درهر چیز. (از اقرب الموارد). کجی با صلابت . <BR><font color=\"Blue\">◄</font> کژی است در بن دم اسب که تا گوشت بالای ران رسیده باشد. (منتهی الارب ). خمیدگی و کژی در عسیب دم اسب که به کادة و فائله ٔ او برسد. (از اقرب الموارد). از عیوب سرشتی در اسب است و آن پیچش بن دم است آنچنانکه داخل آن که مویی ندارد آشکار شود. و بیش از آن را «کشف » گویند. (از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦</span>). <BR><font color=\"Blue\">◄</font> کژی دندان و ساق . <BR><font color=\"Blue\">◄</font> (اِ) درختی است که به خوردن آن شتر را شکم روان شود. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> رمل و ریگ کج و پیچیده . (از اقرب الموارد).<br></font></div>'),
(183896, 'عصل', '<span class=\"hlight\">عصل .</span> <font color=\"DarkGreen\"><b>[ ع َ ص ِ ]</font></b> (ع ص ) کج با سختی و صلابت . <BR><font color=\"Blue\">◄</font> کج دم . (منتهی الارب ). اسبی که او را عَصَل باشد. (از اقرب الموارد). رجوع به عَصَل شود.<br></font></div>'),
(183897, 'عصل', '<span class=\"hlight\">عصل .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ)روده . (منتهی الارب ). مِعی ̍. (اقرب الموارد). عَصَل .ج، أعصال . (اقرب الموارد). و رجوع به عَصَل شود.<br></font></div>'),
(183898, 'عصل', '<span class=\"hlight\">عصل .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ أعصل . (منتهی الارب ) (اقرب الموارد). رجوع به اعصل شود. <BR><font color=\"Blue\">◄</font> سهام عصل ؛ تیرهای کج . (منتهی الارب ).<br></font></div>'),
(183899, 'عصلان', '<span class=\"hlight\">عصلان .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) خنثی است، و گویند اسقیل است . (تحفه ٔ حکیم مؤمن ). عنصل است . (فهرست مخزن الادویة).<br></font></div>'),
(183900, 'عصلب', '<span class=\"hlight\">عصلب .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع ص ) توانای درشت اندام بزرگ جثه . (منتهی الارب ). مرد قوی و سخت خلقت و بزرگ و عظیم . (از اقرب الموارد). عُصلُب .<br></font></div>'),
(183901, 'عصلب', '<span class=\"hlight\">عصلب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل ُ ]</font></b> (ع ص ) توانای درشت اندام بزرگ جثه . (منتهی الارب ). مرد قوی و سخت خلقت و بزرگ و عظیم . (از اقرب الموارد). عَصلَب . عصلبی ّ. <BR><font color=\"Blue\">◄</font> درازبالای مضطرب خلقت . (منتهی الارب ). طویل مضطرب . (اقرب الموارد).<br></font></div>'),
(183902, 'عصلبة', '<span class=\"hlight\">عصلبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ب َ ]</font></b> (ع مص ) سختی خشم .(منتهی الارب ). سخت عَصَب بودن . (از اقرب الموارد).<br></font></div>'),
(183903, 'عصلبی', '<span class=\"hlight\">عصلبی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ بی ی <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ل ُ بی ی ]</font></b> (ع ص نسبی ) منسوب به عصلب و به معنای آن . (از منتهی الارب ) (از اقرب الموارد). رجوع به عصلب <font color=\"DarkGreen\"><b>[ ع َ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ل ُ ]</font></b> شود.<br></font></div>'),
(183904, 'عصلة', '<span class=\"hlight\">عصلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ل َ ]</font></b> (ع اِ) یکی عَصَل . (منتهی الارب ). واحد عصل، یعنی یک درخت دفلی . (از اقرب الموارد). رجوع به عَصَل شود.<br></font></div>'),
(183905, 'عصلة', '<span class=\"hlight\">عصلة.</span> <font color=\"DarkGreen\"><b>[ع َ ص ِ ل َ ]</font></b> (ع ص ) شجرة عصلة؛ درخت کژ. (منتهی الارب ). مؤنث عَصِل، یعنی اسبی که دچار عَصَل است . ج، عِصال و عُصل . (از اقرب الموارد). رجوع به عَصِل شود.<br></font></div>'),
(183906, 'عصلج', '<span class=\"hlight\">عصلج .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َل ْ ل َ ]</font></b> (ع ص ) مرد کج ساق . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183907, 'عصلد', '<span class=\"hlight\">عصلد.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع ص ) درشت سخت . (منتهی الارب ). صلب شدید. (اقرب الموارد). عُصلود. و رجوع به عصلود شود.<br></font></div>'),
(183908, 'عصلوب', '<span class=\"hlight\">عصلوب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) بمعنای عصلب <font color=\"DarkGreen\"><b>[ ع َ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ل ُ ]</font></b> است . (از منتهی الارب ) (از اقرب الموارد). رجوع به عصلب <font color=\"DarkGreen\"><b>[ ع َ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ل ُ ]</font></b> شود.<br></font></div>'),
(183909, 'عصلود', '<span class=\"hlight\">عصلود.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) درشت سخت . (منتهی الارب ). صلب شدید. (اقرب الموارد). عَصلَد. و رجوع به عصلد شود.<br></font></div>'),
(183910, 'عصم', '<span class=\"hlight\">عصم .</span> <font color=\"DarkGreen\"><b>[ ع ُ]</font></b> (اِخ ) ابن وهب بن ابی ابراهیم تمیمی برجمی، مکنی به ابوشبل . شاعر و از اهالی بصره بود. وی در زمان مأمون خلیفه می زیست و او را عمری طولانی بود و در حدود سال <span class=\"hlight\" dir=\"rtl\">٢٢٠</span> هَ .ق . درگذشت . (از الاعلام زرکلی از الامدی ).<br></font></div>'),
(183911, 'عصم', '<span class=\"hlight\">عصم .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ]</font></b> (ع اِمص ) سپیدی است در دستهای چهارپایان . (از اقرب الموارد).<br></font></div>'),
(183912, 'عصم', '<span class=\"hlight\">عصم .</span> <font color=\"DarkGreen\"><b>[ ع ِ ص َ ]</font></b> (ع اِ) ج ِ عِصمة. (منتهی الارب ) (اقرب الموارد). رجوع به عِصمة شود. <BR><font color=\"Blue\">◄</font> ج ِ عُصمة. (منتهی الارب ). رجوع به عُصمة شود.<br></font></div>'),
(183913, 'عصم', '<span class=\"hlight\">عصم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) باقیمانده ٔ هر چیزی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> باقی مانده ٔ اثر حنا و قطران و خضاب و مانند آن در دست و پا. (منتهی الارب ). اثر خضاب و قطران و مانند آن . (از اقرب الموارد). عُصُم . و رجوع به عُصُم شود. <BR><font color=\"Blue\">◄</font> سپیدی بازوی آهو و مانند آن . ج، أعصام . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ج ِ عِصام . (اقرب الموارد). رجوع به عصام شود.<br></font></div>'),
(183914, 'عصم', '<span class=\"hlight\">عصم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ص ُ ]</font></b> (ع اِ) باقیمانده ٔ هر چیزی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> باقی مانده ٔ اثر حنا و قطران و خضاب و مانند آن در دست و پا. (منتهی الارب ). اثر خضاب و قطران و مانند آن . (از اقرب الموارد). عُصم . و رجوع به عُصم شود. <BR><font color=\"Blue\">◄</font> ج ِ عِصام . (منتهی الارب ). رجوع به عصام شود.<br></font></div>'),
(183915, 'عصم', '<span class=\"hlight\">عصم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) نام جبلی است ازآن ِ هذیل . <BR><font color=\"Blue\">◄</font> قلعه ای است ازآن ِ بنی زبید در یمن، و آن را عُصُم نیز گویند. (از معجم البلدان ) (از منتهی الارب ).<br></font></div>'),
(183916, 'عصم', '<span class=\"hlight\">عصم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) ورزیدن . (از منتهی الارب ). اکتساب و کسب کردن . (از اقرب الموارد). کسب . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> چنگ زدن به کسی . (از منتهی الارب ). اعتصام . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عصام ساختن مَشک را. (از منتهی الارب ): عصم القربة؛ برای مشک عصام و بند قرار داد و بوسیله ٔ عصام آن را بست . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بازداشتن کسی را از گرسنگی . (منتهی الارب ): عصم الطعام آکله ؛ آن طعام، خورنده ٔ خود را از گرسنگی حفظ کرد و منع نمود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عصم اﷲ فلاناً من المکروه ؛ خداوند او را از ارتکاب زشتی و گناه محفوظ داشت . (از اقرب الموارد) (از ناظم الاطباء).<br></font></div>'),
(183917, 'عصم', '<span class=\"hlight\">عصم .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ]</font></b> (ع مص ) سپید گردیدن دست آهو. (از منتهی الارب ). «اعصم » شدن آهوو بز کوهی . (از اقرب الموارد). رجوع به اعصم شود.<br></font></div>'),
(183918, 'عصمات', '<span class=\"hlight\">عصمات .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ]</font></b> (ع ا) ج ِ عِصمة. (ناظم الاطباء). رجوع به عصمة شود.<br></font></div>'),
(183919, 'عصمة', '<span class=\"hlight\">عصمة.</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ]</font></b> (اِخ ) ابن حی بن السیدبن مالک ضبی . از شاعران جاهلیت . وی ارقم بن جون را بقتل رسانده است و درباره ٔ او شعری دارد. (از الاعلام زرکلی از المرزبانی ).<br></font></div>'),
(183920, 'عصمة', '<span class=\"hlight\">عصمة.</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ]</font></b>(ع مص ) بازداشتن و نگاه داشتن از گناه و جز آن . (ازمنتهی الارب ). نگاه داشتن . (دهار) (المصادر زوزنی ) (ترجمان القرآن جرجانی ). منع. (تاج المصادر بیهقی ).<br></font></div>'),
(183921, 'عصمة', '<span class=\"hlight\">عصمة.</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ]</font></b> (ع اِ) گردن بند و حمیل . (منتهی الارب ). قلاده و گردن بند و حمایل . (ناظم الاطباء). قلاده . (اقرب الموارد). رسن . (دهار) (مهذب الاسماء). عُصمة. و رجوع به عُصمة شود. ج ِ، عِصَم، أعصُم، و عِصَمة، أعصام . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بازداشتگی از گناه و جز آن . (ناظم الاطباء). منع و خودداری، و گویند آن ملکه ٔ اجتناب از گناهان است با وجود امکان ارتکاب گناه . (از اقرب الموارد) (از تعریفات جرجانی ). عصمت . رجوع به عصمت شود.<br>- <span class=\"hlight\">عصمة المقوِّمة (الَ ...)</span> ؛ عصمتی است که بوسیله ٔ آن قیمت انسان ثابت گردد، و هر کس آن را هتک کند قصاص یا دیه بر او خواهد بود. (از تعریفات جرجانی و اقرب الموارد).<br>- <span class=\"hlight\">عصمةالمؤثِّمة (الَ...)</span> ؛ عصمتی است که هر کس آن را هتک کند گناهکار و آثم خواهد بود. (از تعریفات جرجانی و اقرب الموارد).<br></font></div>'),
(183922, 'عصمة', '<span class=\"hlight\">عصمة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ص َ م َ ]</font></b> (ع اِ) ج ِ عِصمة. (اقرب الموارد). جج ِ عِصْمة و عُصْمة. (منتهی الارب ). رجوع به عصمة شود.<br></font></div>'),
(183923, 'عصمة', '<span class=\"hlight\">عصمة.</span> <font color=\"DarkGreen\"><b>[ ع ُ م َ ]</font></b> (ع اِمص ) سپیدی بازوی آهو و مانند آن، و سپیدشدگی دست و پای آهو و بز کوهی . (منتهی الارب ). اسم مصدر است از صفت اعصم . (از اقرب الموارد). رجوع به اعصم شود. <BR><font color=\"Blue\">◄</font> (اِ) قلاده . (اقرب الموارد). عِصمة. رجوع به عصمة شود. <BR><font color=\"Blue\">◄</font> حمیل و حلقه ای که در گردن سگ باشد. (منتهی الارب ).عذبة و شمله ٔ دستار که در گردن سگ باشد. (از اقرب الموارد). ج، أعصام . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(183924, 'عصمة', '<span class=\"hlight\">عصمة.</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ]</font></b> (اِخ ) مکنی به ابوحکیمة و مشهوربه عصمة البصری . محدث است . رجوع به ابوحکیمة شود.<br></font></div>'),
(183925, 'عصمة', '<span class=\"hlight\">عصمة.</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ]</font></b> (اِخ ) مکنی به ابوعاصم . تابعی است . رجوع به ابوعاصم شود.<br></font></div>'),
(183926, 'عصمة', '<span class=\"hlight\">عصمة.</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ]</font></b> (اِخ ) دختر محمدبن رشیدالدین دختر شمس ابرقوهی . از زنان محدث بود. و در رجب سال <span class=\"hlight\" dir=\"rtl\">٧١١</span> هَ .ق . متولد شد و عمری طولانی کرد. طاووسی <br>بعضی کتب حدیث را نزد او فراگرفته است . (از اعلام النساء از الضوء اللامع سخاوی ).<br></font></div>'),
(183927, 'عصمة', '<span class=\"hlight\">عصمة.</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ]</font></b> (اِخ ) ابن جشم بن معاویه ٔ هوازنی عدنانی . جدّی است جاهلی، و فرزندان او بطنی از جشم را تشکیل می دهند. ابوالاحوص عوف بن مالک تابعی از نسل او بوده است . (از الاعلام زرکلی از نهایة الارب و السبائک و جمهرةالانساب ).<br></font></div>'),
(183928, 'عصمة', '<span class=\"hlight\">عصمة.</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ]</font></b> (اِخ ) ابن حدرةبن قیس یربوعی تمیمی . شاعر و سوارکار عهد جاهلیت . بنی عبس، پسرعم او را بقتل رساندند و او نذر کرد که تا هفتادتن از آنان را بقتل نرساند لب به خمر و گوشت نزند، و چون به نذر خود وفا کرد رجزی سرود که المرزبانی آن را ذکر کرده است . (از الاعلام زرکلی از المرزبانی ).<br></font></div>'),
(183929, 'عصمت', '<span class=\"hlight\">عصمت .</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ]</font></b> (اِخ ) (خواجه ...) نام او خواجه عصمةاﷲ بخاری، مشهور به خواجه عصمت است . وی شاعری ایرانی بود و در عهد تیموری میزیست . در نظم اشعار پیرو امیرخسرو دهلوی بود و مضامین و معانی او را عیناً در اشعار خود نقل میکرد. یکی از فاضلان درباره ٔ او چنین گفته است <span class=\"hlight\">:</span> <br>میرخسرو را علیه الرحمه شب دیدم بخواب <br>گفتمش : عصمت تو را یک خوشه چین خرمن است <br>شعر او چون بیشتر از شعر تو شهرت گرفت ؟<br>گفت : باکی نیست شعر او همان شعر من است .<br>عصمت قصیده ای در رثای امیر تیمور ساخته است به مطلع ذیل :<br>ای فلک خرگاه ویران کن که سلطان غایبست <br>تخت گو بر خاک بنشین، چون سلیمان غایبست .<br>میرزا خلیل سلطان بجهت این قصیده او را انعام و احسان فراوان کرد. وفات خواجه عصمت بسال <span class=\"hlight\" dir=\"rtl\">٨٢٩</span> هَ .ق . رخ داد. (از فرهنگ فارسی معین ). و رجوع به رجال حبیب السیر و مجالس النفائس شود.<br></font></div>'),
(183930, 'عصمت', '<span class=\"hlight\">عصمت .</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ]</font></b> (ع اِمص ) عصمة. پاکدامنی و نبناد و ناآلودگی به گناه . (ناظم الاطباء). نگاهداری نفس از گناه . (فرهنگ فارسی معین ). بازداشتن خود را از گناه، و به اصطلاح اطلاق این لفظ بر پاکی است که از ابتدای وجود تا انتهای عمر گناه کبیره خصوصاً زنا نکرده باشد. (غیاث اللغات ) (آنندراج ). در مورد عصمت ملائکه اختلاف نظر است و برخی آن را موجود می دانند و برخی آن را نفی می کنند، و هر یک از دو فرقه را دلایلی است . اما در مورد وجوب عصمت انبیا، جمیع ملل و شریعت ها اتفاق نظر دارند، جز اینکه آن را در برخی امور لازم می دانند و در برخی جایز، و هر کدام را دلایلی است . رجوع به کشاف اصطلاحات الفنون وشرح مواقف و شرح طوالع شود. بی گناهی . عفاف . عفت . خودداری . خویشتن داری . و رجوع به عصمة شود <span class=\"hlight\">:</span> <br>یونان که بود مادر یونس ز بطن حوت <br>یادی نکرد و کرد ز عصمت جهان بخود.<br> <font color=\"Red\">دقیقی .</font><br>ایزد عز ذکره ما را و همه ٔ مسلمانان را در عصمت خویش نگاه دارد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٥٤</span>).<br>ز رحمت مصور ز حکمت مقدر<br>به نسبت مطهر به عصمت مشهر.<br> <font color=\"Red\">ناصرخسرو.</font><br>دانش من گواه عصمت اوست <br>بشنو آنچ این گواه میگوید.<br> <font color=\"Red\">خاقانی .</font><br>عقل و عصمت که مرا تاج فراغت دادند<br>بر سرمنصب دیوان شدنم نگذارند.<br> <font color=\"Red\">خاقانی .</font><br>عصمتیان در حرمش پردگی <br>عصمت از او یافته پروردگی .<br> <font color=\"Red\">نظامی .</font><br>پشت دار جمله عصمتهای من <br>گوئیا هستند خود اجزای من .<br> <font color=\"Red\">مولوی .</font><br>چون طهارت نبود کعبه و بتخانه یکیست <br>نبود خیر در آن خانه که عصمت نبود.<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">زن باعصمت </span> ؛ زن پاکدامن که دامن آن به هیچگونه فسق و فجور و معصیتی آلوده نشده باشد. (ناظم الاطباء).<br>- <span class=\"hlight\">بی عصمت </span> ؛ بی ناموس . بدکار.<br>- <span class=\"hlight\">بی عصمتی </span> ؛ گناهکار بودن . نداشتن عصمت . زشتکاری .<br>- <span class=\"hlight\">عصمت کبری </span> ؛ لقب فاطمه ٔ زهراء سلام اﷲ علیها. (ناظم الاطباء).<br>- <span class=\"hlight\">عصمت مقومه، عصمت مؤثمه </span> . رجوع به عصمةالمقومة و عصمةالمؤثمة در ترکیبات عصمة شود.<br> <BR><font color=\"Blue\">◄</font> نگهداری . نگهبانی . محافظت <span class=\"hlight\">:</span> بخشاینده ای که تار عنکبوت را سد عصمت دوستان کرد. (کلیله و دمنه ).<br>اعتمادی دارد اوبر عصمت بخت آنچنانک <br>هر سلاحی در خزانه ٔ او بیابی جز سپر.<br> <font color=\"Red\">سنائی .</font><br>گفتی این مرسوم هر سالست اینک سال شد<br>ظن مبر کز دادن مرسوم اندر عصمتی .<br> <font color=\"Red\">سوزنی .</font><br>نه از بادیه بل ز طوفان نوح <br>به کشتی ّ عصمت درون آمدیم .<br> <font color=\"Red\">خاقانی .</font><br> <BR><font color=\"Blue\">◄</font> پیوستگی . استحکام . پناه <span class=\"hlight\">:</span> <br>بنده ز بی دولتی نیست به حضرت مقیم <br>دیو ز بی عصمتی نیست به جنت مکین .<br> <font color=\"Red\">خاقانی .</font><br>عقده ٔ الفت و عصمت مستحکم شد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٣٣</span>). <BR><font color=\"Blue\">◄</font> در نزد اشاعره، اینست که خداوند گناهی را در بنده نیافریند، چه آنان تمام اشیاء را ازابتدا به فاعل مختار اسناد میدهند، و نیز آنان گویند عصمت عبارت از آفریدن قدرت اطاعت است در بشر، که شامل «لطف » میشود. (از کشاف اصطلاحات الفنون ). و رجوع به لطف شود. <BR><font color=\"Blue\">◄</font> در نزد حکما، ملکه ای است نفسانی که صاحب خود را از ارتکاب فسق و فجور و گناهان بازمیدارد، و آن بسبب اعتقاد آنها است به ایجاب و قائل بودن به استعداد قوابل . (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> (اصطلاح حقوق جزا) مانند اصطلاح «هتک ناموس » در جرائم راجع به مواقعه استعمال میشود، بر خلاف اصطلاح «منافیات عفت » که در اعم از مواقعه و غیر آن استعمال شده است . (از فرهنگ حقوقی ).<br></font></div>'),
(183931, 'عصمت آباد', '<span class=\"hlight\">عصمت آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ]</font></b> (اِخ ) دهی از دهستان حومه ٔ بخش مهریز شهرستان یزد. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٠٤٦</span> تن . آب آن از قنات . محصول آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(183932, 'عصمت آباد', '<span class=\"hlight\">عصمت آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ]</font></b>(اِخ ) دهی از دهستان اسحاق آباد، بخش قدمگاه شهرستان نیشابور. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٥٦٤</span> تن . آب آن از قنات . محصول آن غلات و پنبه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(183933, 'عصمت آباد', '<span class=\"hlight\">عصمت آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ]</font></b> (اِخ ) دهی از دهستان زهرا از بخش بوئین شهرستان قزوین . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٤٤٣</span> تن . آب آن از قنات . محصول آن غلات و چغندرقند و ینجه است . مزارع اکبرآباد، کوشکک، باقرآباد، عنایت آباد، شریف آباد، قدیم آباد، رحمان آباد، فتح آباد، باقرآبادجزء این ده است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(183934, 'عصمت سرا', '<span class=\"hlight\">عصمت سرا.</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ س َ ]</font></b> (اِ مرکب ) حرمخانه ٔ باعصمت . حرمسرایی که همه ٔ پردگیان آن باعصمت باشند <span class=\"hlight\">:</span> <br>جهان پادشا را چنین است کام <br>به عصمت سرائی چنین نیکنام .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(183935, 'عصمتکده', '<span class=\"hlight\">عصمتکده .</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) محل عبادت . عبادت خانه . حجره ٔ عزلتیان . <BR><font color=\"Blue\">◄</font> محل ملائکه . <BR><font color=\"Blue\">◄</font> خانه ٔ حضرت مریم <span class=\"hlight\">:</span> <br>چون مریم از عصمتکده رفته مسیحش آمده <br>نخل کهن زو نو شده وز نخل خرما ریخته .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(183936, 'عصمتی', '<span class=\"hlight\">عصمتی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دختر قاضی سمرقند. از زنان شاعر فارس بود و اشعار نیکویی بزبان فارسی دارد. (از اعلام النساء از مشاهیر النساء محمد ذهنی ).<br></font></div>'),
(183937, 'عصمتی', '<span class=\"hlight\">عصمتی .</span> <font color=\"DarkGreen\"><b>[ ع ِم َ ]</font></b> (ص نسبی ) منسوب به عصمة و عصمت . باعصمت . دارای عصمت و حفاظ. رجوع به عصمت و عصمة و عصمتیان شود.<br></font></div>'),
(183938, 'عصمتیان', '<span class=\"hlight\">عصمتیان .</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ]</font></b> (اِ مرکب ) ج ِ عصمتی، منسوب به عصمت . کنایه از انبیا و اولیا و ملائکه و اهل عزلت و خلوت نشینان و مخدرات باشد. (برهان ) (آنندراج ) <span class=\"hlight\">:</span> <br>عصمتیان در حرمش پردگی <br>عصمت از او یافته پروردگی .<br> <font color=\"Red\">نظامی .</font><br><BR><font color=\"Blue\">◄</font> (اِخ ) کنایه از مریم، مادر عیسی علیه السلام است .(برهان ) (آنندراج ).<br></font></div>'),
(183939, 'عصمنلیة', '<span class=\"hlight\">عصمنلیة.</span> <font color=\"DarkGreen\"><b>[ ع ُ م َ لی ی َ ]</font></b> (ع اِ) نوعی از سکه های طلائی رایج در شرق اردن بوده است مشهور به مخمسیةعصمنلیة، و ارزش آن سابقاً <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> غرش ترکی بود و اکنون <span class=\"hlight\" dir=\"rtl\">٩٠٠</span> غرش فلسطینی است . (از النقود العربیة ص <span class=\"hlight\" dir=\"rtl\">٩٧</span>).<br></font></div>'),
(183940, 'عصمور', '<span class=\"hlight\">عصمور.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) چرخ چاه، یا دلو آن . (منتهی الارب ) (از اقرب الموارد).کوزه ٔ دولاب . (دهار). ج، عَصامیر. (اقرب الموارد).<br></font></div>'),
(183941, 'عصمی', '<span class=\"hlight\">عصمی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b>(اِخ ) محمدبن عباس بن احمدبن محمدبن عصم بن بلال عصمی هروی . از رؤسا و دانشمندان و محدثان بود. بسال <span class=\"hlight\" dir=\"rtl\">٢٩٤</span> هَ .ق . متولد شد و در نهم صفر سال <span class=\"hlight\" dir=\"rtl\">٣٧٨</span> هَ .ق . درگذشت . حدیث را نزد ابوالحسن محمد مخلدی و ابوعمرو حیری ودیگران آموخته بود. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(183942, 'عصنصر', '<span class=\"hlight\">عصنصر.</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ص َ ]</font></b> (اِخ ) نام آبی است، و برخی آن را کوهی دانند. (از معجم البلدان ). کوهی است . (منتهی الارب ).<br></font></div>'),
(183943, 'عصنصی', '<span class=\"hlight\">عصنصی .</span> <font color=\"DarkGreen\"><b>[ ع َص َ صا ]</font></b> (ع اِمص ) سست و نرم . (منتهی الارب ). ضعف و سستی، و نون و الف آن زائد است . (از اقرب الموارد).<br></font></div>'),
(183944, 'عصو', '<span class=\"hlight\">عصو.</span> <font color=\"DarkGreen\"><b>[ ع َص ْوْ ]</font></b> (ع مص ) زدن کسی را به چوب دستی . (از منتهی الارب ) (از اقرب الموارد). به عصا زدن . (تاج المصادر بیهقی ) (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> بستن جرح را. (از منتهی الارب ). ببستن جراحت . (تاج المصادر بیهقی ): عصا الجرح ؛ جراحت را بست . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> فراهم آوردن قوم را، بر نیک باشد یا بد. (از منتهی الارب ): عصا القوم ؛ قوم را جمع کرد و گرد آورد، بر شر یا خیر. (از اقرب الموارد).<br></font></div>'),
(183945, 'عصواد', '<span class=\"hlight\">عصواد.</span> <font color=\"DarkGreen\"><b>[ ع ِص ْ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُص ْ ]</font></b> (ع ص ) رجل عصواد؛ مرد سخت دشوارخوی، و نیز امراءة عصواد. (منتهی الارب ).مرد بدخوی و سخت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> صاحب بدی و شر. (منتهی الارب ): امراءة عصواد؛ زن بسیارشر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زن کم گوشت . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> ورد عصواد؛ ورد مانده وهلاک کننده ٔ شتران . (منتهی الارب ). ورد دشوار و با تعب و رنج . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ) وقعوا فی عصواد؛ یعنی در امر بزرگ و سخت افتادند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ازدحام و اختلاط در زدن یا دشمنی . <BR><font color=\"Blue\">◄</font> عصواد الظلام ؛ اختلاط یا انبوهی تاریکی . <BR><font color=\"Blue\">◄</font> ترکتهم فی عصواد؛ آنان را در شری ترک گفتم که ناشی از قتل یا دشنام یا خصومت بوده است . (از اقرب الموارد). ج، عَصاوید. (منتهی الارب ) (از اقرب الموارد). و رجوع به عصاوید شود.<br></font></div>'),
(183946, 'عصوان', '<span class=\"hlight\">عصوان .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ ]</font></b> (ع اِ) مثنای عَصا در حالت رفع. (از منتهی الارب ) (از اقرب الموارد). رجوع به عصا و عصوین شود.<br></font></div>'),
(183947, 'عصوب', '<span class=\"hlight\">عصوب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) زن زشت صورت، یا زن سبک سرین . (منتهی الارب ). زن رسحاء یا زلاء. (از اقرب الموارد). و رجوع به رسحاء و زلاء شود. <BR><font color=\"Blue\">◄</font> ناقه ای که بی پا بستن دوشیده نشود. (منتهی الارب ): ناقة عصوب ؛ ماده شتری که تا رانهای او را نبندند شیر ندهد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) چرکناکی دندان از غبار و جز آن . (منتهی الارب ).<br></font></div>'),
(183948, 'عصوب', '<span class=\"hlight\">عصوب .</span> <font color=\"DarkGreen\"><b>[ع ُ ]</font></b> (ع مص ) مصدر عَصب است به معنی چرکناک شدن دندان از غبار. (از ناظم الاطباء). و رجوع به عَصْب شود.<br></font></div>'),
(183949, 'عصوبة', '<span class=\"hlight\">عصوبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع مص ) آن را مصدر عَصَبة به حساب آورده اند. (از اقرب الموارد). رجوع به عَصَبة شود.<br></font></div>'),
(183950, 'عصود', '<span class=\"hlight\">عصود.</span> <font color=\"DarkGreen\"><b>[ ع ِ ص َوْ وَ ]</font></b> (ع ص ) زن باریک اندام . <BR><font color=\"Blue\">◄</font> (اِ) رکب فلان عصوده ؛ یعنی او بر سر خود رفت . (از منتهی الارب ). یعنی او به رای و نظر خود عمل کرد. (از اقرب الموارد).<br></font></div>'),
(183951, 'عصود', '<span class=\"hlight\">عصود.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) بمردن . (تاج المصادر بیهقی ): عصدت الابل ؛ بمردند شتران . (منتهی الارب ). عصد الرجل ؛ آن مرد بمرد. عصد البعیر عنقه ؛ آن شتر گردن خود رابسمت کتف پیچاند ازبرای مردن . (از اقرب الموارد).<br></font></div>'),
(183952, 'عصود', '<span class=\"hlight\">عصود.</span> <font color=\"DarkGreen\"><b>[ ع َ ص َوْ وَ ]</font></b> (ع ص ) روز دراز. (منتهی الارب ): یوم عصود؛ روز طویل و دراز. (از اقرب الموارد).<br></font></div>'),
(183953, 'عصور', '<span class=\"hlight\">عصور.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عصر <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ص ُ ]</font></b> . (منتهی الارب ) (از اقرب الموارد). رجوع به عصر شود.<br></font></div>'),
(183954, 'عصوف', '<span class=\"hlight\">عصوف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) سخت وزیدن باد. (منتهی الارب ) (ترجمان القرآن جرجانی ) (دهار). باد سخت جستن . (تاج المصادر بیهقی ). سخت جستن باد. (المصادر زوزنی ). سخت شدن باد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کسب کردن جهت عیال . <BR><font color=\"Blue\">◄</font> بردن و هلاک کردن جنگ گروهی را. <BR><font color=\"Blue\">◄</font> بشتافتن و سرعت نمودن . (از منتهی الارب ) (از اقرب الموارد). عَصف . و رجوع به عصف شود.<br></font></div>'),
(183955, 'عصوف', '<span class=\"hlight\">عصوف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِمص ) تیرگی . (منتهی الارب ). کدّ و رنج، و برخی آن را «کدر» و تیرگی نوشته اند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) می . (منتهی الارب ). خُمور، و ظاهراً مفرد آن عَصف است . (از (اقرب الموارد).<br></font></div>'),
(183956, 'عصوف', '<span class=\"hlight\">عصوف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) باد تند.(منتهی الارب ). باد سخت . (دهار). <BR><font color=\"Blue\">◄</font> ناقة عصوف و نعامة عصوف ؛ شتر ماده و شترمرغ شتاب رو، که تشبیه به باد شده اند. (از منتهی الارب ) (از اقرب الموارد). شتر تیزرو. (دهار). ج، عُصُف . (اقرب الموارد).<br></font></div>'),
(183957, 'عصوم', '<span class=\"hlight\">عصوم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) بسیار خورنده . (منتهی الارب ). اکول . (اقرب الموارد). عَیصوم . و رجوع به عیصوم شود.<br></font></div>'),
(183958, 'عصوی', '<span class=\"hlight\">عصوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ وی ی ]</font></b> (ع ص نسبی ) منسوب به عصا، به معنی چوبدست . (از ناظم الاطباء). رجوع به عصا شود.<br></font></div>'),
(183959, 'عصوین', '<span class=\"hlight\">عصوین .</span> <font color=\"DarkGreen\"><b>[ ع َ ص َ وَ ]</font></b> (ع اِ) مثنای عَصا در حالت نصب و جر. رجوع به عَصا و عَصَوان شود.<br></font></div>'),
(183960, 'عصی', '<span class=\"hlight\">عصی .</span> <font color=\"DarkGreen\"><b>[ ع ُ صی ی ]</font></b> (ع اِ) ج ِ عَصا. (منتهی الارب ) (اقرب الموارد). رجوع به عصا شود.<br></font></div>'),
(183961, 'عصی', '<span class=\"hlight\">عصی .</span> <font color=\"DarkGreen\"><b>[ ع َص ْی ْ ]</font></b> (ع مص ) نافرمانی نمودن . (از منتهی الارب ). نافرمانی کردن . (تاج المصادر بیهقی ). خروج از طاعت و مخالفت کردن با امرکسی و عناد کردن . (از اقرب الموارد). از آن جمله است حدیث : «من لم یجب الدعوة فقد عصی »، که منظور دعوت عروسی و نکاح است یعنی هر کس دعوت عروسی را نپذیرد عصیان کرده است زیرا بسبب اعلان نکاح که در آن میشود، اجابت دعوت واجب است . و گویند وجوب حضور در آن است، اما خوردن اگر دعوت شونده روزه دار نباشد، مستحب است . (از منتهی الارب ). مَعصیة. و رجوع به معصیة شود. <BR><font color=\"Blue\">◄</font> پرواز کردن : عصی الطائر؛ آن پرنده پرواز کرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خشک نشدن خون : عصی العِرْق ؛ خون آن رگ خشک نشد. (از اقرب الموارد).<br></font></div>'),
(183962, 'عصی', '<span class=\"hlight\">عصی .</span> <font color=\"DarkGreen\"><b>[ ع َ صا <span class=\"hlight\" dir=\"rtl\">/</span> ع َ صَن ْ ]</font></b> (ع مص ) به چوبدستی زدن . (از ناظم الاطباء). بشمشیر بزدن . (المصادر زوزنی ). عَصا. رجوع به عصا شود.<br></font></div>'),
(183963, 'عصی', '<span class=\"hlight\">عصی .</span> <font color=\"DarkGreen\"><b>[ ع َ صا ]</font></b> (ع فعل، اِ) صیغه ٔ ماضی از مصدر عَصْی که با در نظر گرفتن آیه ٔ کریمه ٔ «و عصی آدم ربه فغوی » (قرآن <span class=\"hlight\" dir=\"rtl\">١٢١/٢٠</span>) یعنی آدم ابوالبشر بر خدای خود عصیان کرد و سرپیچی نمود پس گمراه شد، در فارسی بعنوان اسم بکار رفته است <span class=\"hlight\">:</span> <br>زلف زمین در بر عالم فکند<br>خال عصی بر رخ آدم فکند.<br> <font color=\"Red\">نظامی .</font><br>دامن او گیر کو دارد عصا<br>درنگر آدم چه ها دید از عصی .<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(183964, 'عصی', '<span class=\"hlight\">عصی .</span> <font color=\"DarkGreen\"><b>[ ع ِ صی ی ]</font></b> (ع اِ) ج عَصا. (منتهی الارب ) (از اقرب الموارد). رجوع به عصا شود. <BR><font color=\"Blue\">◄</font> استخوانهای بال . (منتهی الارب ). استخوانها که در جناح و بال است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اصطلاح نجوم ) ذوذنبهایی بشکل عصا و مستقیم، بخلاف ذوذنبهایی که ذنب آنها مایل است . (فرهنگ فارسی معین ).<br></font></div>'),
(183965, 'عصی', '<span class=\"hlight\">عصی .</span> <font color=\"DarkGreen\"><b>[ ع َ صی ی ]</font></b> (ع ص ) نافرمان . (منتهی الارب ). بی فرمان . (زمخشری ). خروج کننده از اطاعت ومخالفت کننده با امر دیگری و عنادکننده . عاصی . عاص .عَصّاء. ج، عَصیّون، أعصیاء. (از اقرب الموارد).<br></font></div>'),
(183966, 'عصی الراعی', '<span class=\"hlight\">عصی الراعی .</span> <font color=\"DarkGreen\"><b>[ ع َ صَرْ را ]</font></b> (ع اِ مرکب ) عصاالراعی . درخت بطباط. رجوع به عصاالراعی شود.<br></font></div>'),
(183967, 'عصی هرمس', '<span class=\"hlight\">عصی هرمس .</span> <font color=\"DarkGreen\"><b>[ ع َ صا هَُ م ُ]</font></b> (اِ مرکب ) حلبوب است . (فهرست مخزن الادویة) (تحفه ٔحکیم مؤمن ). خصی هرمس . جربوب . رجوع به حلبوب شود.<br></font></div>'),
(183968, 'عصیان', '<span class=\"hlight\">عصیان .</span> <font color=\"DarkGreen\"><b>[ ع ِص ْ ]</font></b> (ع اِمص ) نافرمانی و بیفرمانی کردن . خلاف طاعت . (منتهی الارب ). خلاف طاعت، و ترک گفتن انقیاد و فرمانبرداری . (از اقرب الموارد). نافرمانی کردن . (تاج المصادر بیهقی ) (ترجمان القرآن جرجانی ) (غیاث اللغات ) (آنندراج ). نافرمان برداری کردن و بی فرمانی . (دهار). نافرمانی و نافرمانبرداری . (المصادر زوزنی ). نافرمانی . (مهذب الاسماء). ترک انقیاد. (تعریفات جرجانی ). در اصل لغت معنی آن سخت شدن است، پس گناه را عصیان از آن نام کردند که آدمی از گناه سخت دل میشود، و نافرمانی کردن . (از غیاث اللغات ) (از آنندراج ). سرکشی . سر کشیدن <span class=\"hlight\">:</span> <br>دلت همانا زنگار معصیت دارد<br>به آب توبه ٔ خالص بشویش از عصیان .<br> <font color=\"Red\">خسروانی .</font><br>چون در او عصیان و خذلان تو ای شه راه یافت <br>کاخها شد جای کوف و باغها شد جای خار.<br> <font color=\"Red\">فرخی .</font><br>وقت نماز خطبه بر رسم رفته کردند و هیچ چیز اظهار نکردند که به عصیان ماند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٢٨</span>). سپاه سالار گفت او را چه زهره ٔ عصیان ؟ (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤١١</span>). هارون پسر خوارزمشاه آلتونتاش عصیان خود را آشکار کرد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٠٣</span>). برادر شهرک را به شاپور بردند و عصیان آغازیدند. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١١٦</span>). هوای عصیان بر سر او بادخان ساخت . (کلیله و دمنه ).<br>که خواند تخته ٔ عصیان تو که درنفتاد<br>ز تخت پنجه پایه به چاه پنجه باز.<br> <font color=\"Red\">سوزنی .</font><br>این دو صادق، خرد و رای که میزان دلند<br>بر پی عقرب عصیان شدنم نگذارند.<br> <font color=\"Red\">خاقانی .</font><br>ابوعلی بن سیمجور چون عصیان بر ملک نوح آغاز کرد خواست تا ناحیت غرشستان را به تدبیرخویش کرد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٣٨</span>). و رای تقاعدو تکاسل پیش گرفت تا عصیان او ظاهر شد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٤١</span>). اندیشید که عصیان بر ولی نعمت خویش عاقبتی وخیم دارد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٩</span>). <BR><font color=\"Blue\">◄</font> گناه . ذنب . اثم . بزه . جرم . جناح . مأثم . خطا. معصیت . گناه را عصیان از آن نام کردند که آدمی از گناه سخت دل می شود، چه اصل معنای عصیان سخت شدن است . (از غیاث اللغات ) (از آنندراج ). سرکشی کردن در اوامرالهی <span class=\"hlight\">:</span> و کره اًلیکم الکفر و الفسوق و العصیان (قرآن <span class=\"hlight\" dir=\"rtl\">٧/٤٩</span>)؛ و کفر و فسق و عصیان را بر شما ناپسند گردانید.<br>مبتلای درد عصیانی به طاعت بازگرد<br>درد عصیان را جز از طاعت نیابد کس دوا.<br> <font color=\"Red\">ناصرخسرو.</font><br>تو را نفس کلی چو بشناسی او را<br>نگه دارد از جهل و عصیان و نسیان .<br> <font color=\"Red\">ناصرخسرو.</font><br>طاعت و علم راه جنت اوست <br>جهل و عصیانْت رهبر ناراست .<br> <font color=\"Red\">ناصرخسرو.</font><br>از معرض عصیان و موقف کفران تجافی جست . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٤٣</span>). مادح وی اجتناب از هوی و عصیان . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٤٧</span>).<br>بوقبیس آرامگاه انبیا بوده مقیم <br>باز عضبان گاه اهل بغی و عصیان آمده .<br> <font color=\"Red\">خاقانی .</font><br>نزد یزدان دین و احسان نیست خرد<br>وای ِ آنکو مرد و عصیانش نمرد.<br> <font color=\"Red\">مولوی .</font><br>به عصیان در رزق بر کس نبست .<br> <font color=\"Red\">(گلستان ).</font><br>چون قوت احصانش نباشد به عصیان مبتلی گردد. (گلستان ).<br>نماند به عصیان کسی در گرو<br>که دارد چنین سیدی پیشرو.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(183969, 'عصیان آوردن', '<span class=\"hlight\">عصیان آوردن .</span> <font color=\"DarkGreen\"><b>[ ع ِص ْ وَ دَ ]</font></b> (مص مرکب ) سرپیچی کردن . عصیان کردن <span class=\"hlight\">:</span> <br>که یارد آمد پیش تو از ملوک به جنگ <br>که یارد آورد اندر تو ای ملک عصیان .<br> <font color=\"Red\">فرخی .</font><br>هرکه برتافت عنان از تو و عصیان آورد<br>از در خانه ٔ او دولت برتافت عنان .<br><font color=\"Red\">فرخی (از آنندراج ).</font><br></font></div>'),
(183970, 'عصیان نمودن', '<span class=\"hlight\">عصیان نمودن .</span> <font color=\"DarkGreen\"><b>[ ع ِص ْ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ دَ ]</font></b> (مص مرکب ) عصیان کردن . سرکشی نمودن . عاصی شدن <span class=\"hlight\">:</span> <br>به تیغ او سپه آرای نیست خواهد شد<br>هر آن کسی که نماید درین ملک عصیان .<br><font color=\"Red\">فرخی (از آنندراج ).</font><br>آنکس که تو را نداشت طاعت <br>در عصبه ٔ تو نمود عصیان .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(183971, 'عصیان کده', '<span class=\"hlight\">عصیان کده .</span> <font color=\"DarkGreen\"><b>[ ع ِص ْ ک َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) جای معصیت و گناهکاری . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>داده به عساکر شفاعت <br>عصیان کده ها همه به غارت .<br><font color=\"Red\">درویش واله هروی (از آنندراج ).</font><br></font></div>'),
(183972, 'عصیان کردن', '<span class=\"hlight\">عصیان کردن .</span> <font color=\"DarkGreen\"><b>[ ع ِص ْ ک َ دَ ]</font></b> (مص مرکب ) طغیان کردن . سرکشی کردن . عصیان ورزیدن . عاصی شدن <span class=\"hlight\">:</span> <br>خویشتن را چون فریبی چون نپرهیزی ز دیو<br>چون نهی چون خود کنی عصیان بهانه برقضا.<br> <font color=\"Red\">ناصرخسرو.</font><br>بسا شها که بگشت او ز دوستی ّ ملک <br>بسا امیر که با رای شاه عصیان کرد.<br><font color=\"Red\">مسعودسعد.</font><br></font></div>'),
(183973, 'عصیان گر', '<span class=\"hlight\">عصیان گر.</span> <font color=\"DarkGreen\"><b>[ ع ِص ْ گ َ ]</font></b> (ص مرکب ) یاغی . گردنکش . سرکش . عاصی . <BR><font color=\"Blue\">◄</font> گناهکار. (ناظم الاطباء).<br></font></div>'),
(183974, 'عصیب', '<span class=\"hlight\">عصیب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ص َ ]</font></b> (اِخ ) جائی است به بلاد مزینه . (منتهی الارب ) (از معجم البلدان ).<br></font></div>'),
(183975, 'عصیب', '<span class=\"hlight\">عصیب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) سخت دشوار. (ترجمان القرآن جرجانی ). سخت و دشوار. (دهار): یوم عصیب ؛ روز سخت گرم یا روز سخت . (منتهی الارب ) (اقرب الموارد). و نیز گویند: لیلة عصیب، و عصیبة بکار نرود. (از اقرب الموارد) <span class=\"hlight\">:</span> و لما جأت رسلنا لوطاً سی ٔ بهم و ضاق بهم ذرعاً و قال هذا یوم عصیب (قرآن <span class=\"hlight\" dir=\"rtl\">٧٧/١١</span>)؛ و چون رسولان ما بر لوط آمدند، بدانان محزون شد و طاقت او تنگ شد و گفت این روزی است سخت و دشوار. <BR><font color=\"Blue\">◄</font> شُش با روده ها درپیچیده و بریان کرده . (منتهی الارب ). ریه و جگر سفید که با روده پیچیده شود و بریان کنند. (از اقرب الموارد). یک نوع طعام که از روده ٔ آکنده از شش و دل ترتیب دهند. (ناظم الاطباء). جگرآکند. (دهار). زویج . زونج . ج، عُصُب، أعِصبة. (منتهی الارب ) (اقرب الموارد) <span class=\"hlight\">:</span> <br>عصیب و گرده برون کن وز او زونج نورد <br>جگر بیاژن و آگنج را بسامان کن .<br><font color=\"Red\">کسائی .</font><br></font></div>'),
(183976, 'عصیة', '<span class=\"hlight\">عصیة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ص َی ْ ی َ ]</font></b> (ع اِ مصغر) مصغر عَصا. چوبدستی کوچک و خرد. (از ناظم الاطباء). رجوع به عصا شود.<br></font></div>'),
(183977, 'عصیة', '<span class=\"hlight\">عصیة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ص َی ْ ی َ ]</font></b> (اِخ ) ابن خُفاف بن امری ءالقیس بن بهثة، از بنی سُلیم بن منصور. جدی است جاهلی و فرزندانش بطنی از سلیم از قیس عیلان از عدنانیه را تشکیل میدهند.و خنساء شاعره و أبوالعاج کثیربن عبداﷲبن بردة از والیان بصره، و نیز جماعتی از صحابه از این بطن بوده اند. و حدیث «عصیة عصت اﷲ و رسوله » درباره ٔ گروهی ازآنان است، چه آنها پیمان خود را با پیامبر اسلام (ص )نقض کردند و اصحاب «بئر معونة» را بقتل رساند. (از الاعلام زرکلی از فتح الباری و کتاب المناقب و امتاع الاسماع و جمهرة الانساب ). و رجوع به منتهی الارب شود.<br></font></div>'),
(183978, 'عصیة', '<span class=\"hlight\">عصیة.</span> <font color=\"DarkGreen\"><b>[ ع ُص َی ْ ی َ ]</font></b> (اِخ ) مادر اسب حذیمة است، و از آن است مثل «العصا من العصیة»، که منظور این است که کارها بهم مربوط است . (از منتهی الارب ). و رجوع به عصا شود.<br></font></div>'),
(183979, 'عصید', '<span class=\"hlight\">عصید.</span> <font color=\"DarkGreen\"><b>[ ع ِص ْ ی َ ]</font></b> (ع ص ) متهم به شر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ابنه زده و مأبون، یعنی آنکه علت مشایخ دارد. (از منتهی الارب ) (از آنندراج ) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِخ ) لقب حذیفةبن بدر، یا لقب حصن بن حذیفه . (منتهی الارب ).<br></font></div>'),
(183980, 'عصید', '<span class=\"hlight\">عصید.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) چیز پیچیده شده . معصود. (از اقرب الموارد). و رجوع به عُصود شود.<br></font></div>'),
(183981, 'عصیده', '<span class=\"hlight\">عصیده .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ازع، اِ) عصیدة. نوعی حلوا که از آرد و روغن ساخته شود. رجوع به عصیدة شود <span class=\"hlight\">:</span> بتدریج بابونه و بیخ خطمی و بیخ سوسن و بنفشه و خبازا بوستانی درافزایند و بپزند تا چون عصیده شود. (ذخیره ٔ خوارزمشاهی ).<br>هر زن که به دست زور خواهد<br>نان خشک عصیده شور خواهد.<br><font color=\"Red\">نظامی .</font><br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(183982, 'عصیر', '<span class=\"hlight\">عصیر.</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (ع ص ) شلپیده . (منتهی الارب ). معصور و فشرده شده . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) آنچه که به فشاردن بیرون آید از آب و مایع و نحو آن . (منتهی الارب ). آنچه به فشاردن و عَصر بیرون آید. (از اقرب الموارد). شیره . (دستور اللغة) (نصاب ). شیره ٔ انگور و جزآن . (دهار) (از غیاث اللغات ). آب افشرده از نباتات که منجمد نشده باشد. (مخزن الادویة). افشره . فشرده .<br>- <span class=\"hlight\">عصیر امعاء</span> ؛ عصیر روده . عصیر معوی . (فرهنگ فارسی معین ). رجوع به عصیر روده شود.<br>- <span class=\"hlight\">عصیر انگور</span> ؛ شراب . عصیر. رجوع به عصیر شود <span class=\"hlight\">:</span> <br>این بر آن وزن و قافیت گفتم <br>روزگار عصیر انگور است .<br> <font color=\"Red\">مسعودسعد.</font><br>- <span class=\"hlight\">عصیر روده </span> ؛ شیره ٔ روده، و در اصطلاح پزشکی مخلوطی است از تراوشهای غده های روده .این غده ها عبارتند از غده های برونر و غده های لیبرکون و سلولهای مخاطی اپی تلیوم روده . غده های خوشه ای برونر فقط در اثناعشر موجودند ولی غده های لوله ای لیبرکون تمام سطح مخاط روده ٔ باریک را می پوشانند و سلولهای مخاطی هم در سطح مخاط و هم در عمق غده ها پراکنده اند. عصیر روده مایعی است زردرنگ که بواسطه ٔ حرارت منعقد میشود و واکنش آن قلیائی و <span class=\"hlight\" dir=\"rtl\">PH</span> آن برابر <span class=\"hlight\" dir=\"rtl\">٨/٣</span> است . این شیره دارای دو درصد مواد جامد است . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصیر عِنَبی </span> ؛ شیره ٔ انگور. آب انگور. فشرده ٔ انگور. و در شرع اسلام قبل از ذهاب ثلثین از آن حرام است، یعنی هرگاه آب انگور را در دیگ ریزند و بجوشانند قبل از آنکه دوسِوُم آن کسر شود حرام است و نجس، و بعد از ذهاب ثلثین طاهر شود و شیره گردد. و اگر قبل از آنکه دوسِوُم آن تبخیر شود بماند تا سرکه شود باز طاهر شود. (فرهنگ علوم عقلی از شرح لمعه و الفقه علی ). و رجوع به عصیر شود.<br>- <span class=\"hlight\">عصیر معدنی </span> ؛ کائنات و موجودات . (ناظم الاطباء).<br>- <span class=\"hlight\">عصیر معدی </span> ؛ (اصطلاح پزشکی ) مایعی است بیرنگ و لزج و دارای واکنش اسیدی که شامل نودونه درصد آب و یک درصد مواد معدنی و دیاستازها است . شیره ٔ معده از پرده ٔ مخاطی سطح داخلی معده که دارای غدد مترشحه ای در عمق پرزهای معده است ترشح میشود. مهمترین ماده ٔ معدنی عصیر معدی اسید کلریدریک و املاح قلیایی آن است . و بعلاوه عصیر معدی دارای سه دیاستاز پپسین و پرزور و لیپاز میباشد. مقدار اسیدکلریدریک عصیر معدی در حدود دو درصد و مقدار دیاستازهایش در حدود چهار درصد است . شیره ٔ معدی . رطوبت معده . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عصیر معوی </span> ؛ عصیر امعاء. عصیر روده . (فرهنگ فارسی معین ). رجوع به عصیر روده شود.<br> <BR><font color=\"Blue\">◄</font> شراب انگوری . (غیاث اللغات ) (ناظم الاطباء). شراب حدیث، و آن شرابی باشد که کمتر از شش ماه بر او گذشته است . (یادداشت مرحوم دهخدا). و گویند که آن خاص رطب است نه خرما و تمر، چه آن را نبیذ گویند که غیر از عصیر است . (از اقرب الموارد). عصیر عنبی و عصیر انگور. و رجوع به عصیر عنبی و عصیر انگور شود <span class=\"hlight\">:</span> <br>همه وادیج پرانگور و همه جای عصیر<br>زآنچ ورزید کنون بر بخورد برزگرا.<br> <font color=\"Red\">شاکر بخاری .</font><br>دوستان وقت عصیر است و کباب <br>راه را گرد نشانده ست سحاب .<br> <font color=\"Red\">منوچهری .</font><br>نیم جوشیده عصیر از سر خم <br>بکشیدن، که چنین است صواب .<br> <font color=\"Red\">منوچهری .</font><br>رادمردان را هنگام عصیر<br>شاید ار می نبود صافی و ناب .<br> <font color=\"Red\">منوچهری .</font><br>تو ز خوشه عصیرچون یابی <br>تا نگیرد ز تاک خوشه عصیر.<br> <font color=\"Red\">ناصرخسرو.</font><br>به خوشه ٔ قُران در ببین دانه را<br>به انگور دین در رها کن عصیر.<br> <font color=\"Red\">ناصرخسرو.</font><br>چون خر بسبزه رفته بنوروز درخزان <br>در زیر رَز خزان شده با کوزه ٔ عصیر.<br> <font color=\"Red\">ناصرخسرو.</font><br>رَز انگور باشد بی اندازه چنانک قیمتی نگیرد و آن را بعضی عصیر سازند و بعلاقه کنند. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١٣٩</span>).<br>ناهید رودساز به امیّد بزم تو<br>دارد به دست جام عصیر اندر آسمان .<br> <font color=\"Red\">سوزنی .</font><br>علم اندرکش و با ریش مگس ران کردار<br>حمله کن بر مگسان سر خمهای عصیر.<br> <font color=\"Red\">سوزنی .</font><br>عید است و آن عصیر عروسی است صرع دار<br>کف بر لب آوریده و آلوده معجرش .<br> <font color=\"Red\">خاقانی .</font><br>انگور فلان باغ در وجه فلان عصیر نهادم . (سعدی ).<br><BR><font color=\"Blue\">◄</font> اصل و نسب : رجل کریم العصیر؛ شخص کریم النسب . (از اقرب الموارد).<br></font></div>'),
(183983, 'عصیرالدب', '<span class=\"hlight\">عصیرالدب .</span> <font color=\"DarkGreen\"><b>[ ع َ رُدْ دُب ب ]</font></b> (ع اِ مرکب ) شماری . (فهرست مخزن الادویة).حناء احمر. قطلب . رجوع به شماری و حناء احمر شود.<br></font></div>'),
(183984, 'عصیفة', '<span class=\"hlight\">عصیفة.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع اِ) برگ فراهم و مجتمعشده که در میان وی خوشه باشد. (منتهی الارب ). برگی که از روی میوه شکافد، و آن همان برگهای مجتمعی اس-ت که سنبل و خوشه در آنها باشد. (از اقرب الموارد).<br></font></div>'),
(183985, 'عصیفر', '<span class=\"hlight\">عصیفر.</span><font color=\"DarkGreen\"><b>[ ع ُ ص َ ف ِ ]</font></b> (ع اِ مصغر) مصغر عُصفور. گنجشک کوچک .گنجشک خرد. (از ناظم الاطباء). رجوع به عصفور شود.<br></font></div>'),
(183986, 'عصیفیر', '<span class=\"hlight\">عصیفیر.</span> <font color=\"DarkGreen\"><b>[ ع ُص َ ]</font></b> (ع اِ مصغر) مصغر عُصفور. گنجشک کوچک . گنجشک خرد. (از ناظم الاطباء). رجوع به عصفور و عصیفر شود.<br></font></div>'),
(183987, 'عصیم', '<span class=\"hlight\">عصیم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) خوی . (منتهی الارب ). عرق . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> چرک و کمیز که بر ران شتر خشک گردد. (منتهی الارب ). وسخ و بول خشک شده بر ران شتر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> موی سیاه که زیر پشم شتر بعدِ ریخته شدنش برآید. <BR><font color=\"Blue\">◄</font> بقیه ٔ هر چیزی . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> باقی ماندن اثر حنا و قطران و خضاب و جز آن بر دست . (منتهی الارب ). اثر خضاب و از آن قبیل . (از اقرب الموارد).<br></font></div>'),
(183988, 'عصیم', '<span class=\"hlight\">عصیم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ص َ ]</font></b> (اِخ ) از اعلام است . (منتهی الارب ).<br></font></div>'),
(183989, 'عصیمة', '<span class=\"hlight\">عصیمة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ص َ م َ ]</font></b> (اِخ ) دختر زید نهدی . از زنان شاعر عرب بود و با مردی از قوم خود بنام ابوالسمیدع سعیدبن سالم ازدواج کرد. و چون عصیمه بر او خشم گرفت شعری در مورد او سرایید که در اعلام النساء نقل شده است . رجوع به اعلام النساء و بلاغات النساء طیفور شود.<br></font></div>'),
(183990, 'عض', '<span class=\"hlight\">عض .</span> <font color=\"DarkGreen\"><b>[ ع ِض ض ]</font></b> (ع ص، اِ) بدخوی . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> فصیح سخنور و زشت . (منتهی الارب ). بلیغ منکر و زیرک . (از تاج العروس ) (از اقرب الموارد).  <BR><font color=\"Blue\">◄</font> حریف . (منتهی الارب ). قِرن و همتا و قرین . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> توانا بر چیزی : فلان عض سفر؛ سخت ورزنده و توانا بر سفر. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نیکودارنده ٔ مال . (منتهی الارب ). قیم برای مال . (از اقرب الموارد): فلان عض مال ؛ نیکودارنده و اداره کننده ٔمال . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زُفت . (منتهی الارب ). بخیل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد سخت . (منتهی الارب ). رجل شدید. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> زیرک . (منتهی الارب ). داهیة. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> رسا. (منتهی الارب ). ج، عُضوض (منتهی الارب ) (اقرب الموارد)، و أعضاض . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> اسم جنس هر درخت کوچک خاردار، و گویند اسم نوعی از خار است . (مخزن الادویة). درخت خار خرد، و گویند درخت طلح و عوسج و سَلَم و سیال وسَرح  و عرفط و سَمُر و شَبَهان  و کَنَهبَل . (از منتهی الارب ) (از اقرب الموارد). عُض ّ. و رجوع به عُض ّشود. <BR><font color=\"Blue\">◄</font> کلیدان که گشاده نشود. (منتهی الارب ). آنچه گشوده نشود از اغالیق و قفل ها. (از اقرب الموارد). ج، أعضاض . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(183991, 'عض', '<span class=\"hlight\">عض .</span> <font color=\"DarkGreen\"><b>[ ع ُض ض ]</font></b> (ع اِ) خمیر که شتر را بدان خورش دهند. (منتهی الارب ). عجین که شترآن را تعلیف کند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سپست . (منتهی الارب ). قَت ّ. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> جو. (منتهی الارب ). شعیر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گندم بی آمیغ. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خسته ٔ شکسته . (منتهی الارب ). هسته که چیزی با آن مخلوط نباشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درخت سطبر باقی مانده در زمین . (منتهی الارب ). درخت سطبر که در زمین باقی ماند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خمیر. (منتهی الارب ). عجین . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> هیزم خشک کلان فراهم آورده . (منتهی الارب ). چوب بزرگ که جمع شود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گیاه خشک . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نوعی از علف ستور چون دانه ٔ خرما کوفته و کنجاره و جز آن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> عِض ّ است در معنی درخت خار خرد یا درخت طلح و... (از منتهی الارب ) (از اقرب الموارد). رجوع به عِض ّ شود.<br></font></div>'),
(183992, 'عض', '<span class=\"hlight\">عض .</span> <font color=\"DarkGreen\"><b>[ ع َض ض ]</font></b> (ع اِ) گزیدگی دندان . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> سختی، گویند: عض الزمان یا عض الحرب ؛ یعنی سختی روزگار یا سختی جنگ . و آن را عظ به ظاء نیز نوشته اند. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183993, 'عض', '<span class=\"hlight\">عض .</span><font color=\"DarkGreen\"><b>[ ع َض ض ]</font></b> (ع مص ) گَزیدن . (از منتهی الارب ) (ترجمان القرآن جرجانی ). به دندان گزیدن . (غیاث اللغات ). به دندان گرفتن . (المصادر زوزنی ) (دهار) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> به زبان گرفتن . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زیرک و داهی شدن . (ازمنتهی الارب ). عِض ّ شدن شخص . (از اقرب الموارد). و رجوع به عِض ّ شود. <BR><font color=\"Blue\">◄</font> سخت شدن زمان بر کسی .(از اقرب الموارد). <BR><font color=\"Blue\">◄</font> لازم گرفتن چیزی را. <BR><font color=\"Blue\">◄</font> چسبیدن و ملتصق شدن وتر کمان به کبد آن . و برخی عض را به معنی گزیدن به دندان با «ض » و به سایر معانی با «ظ» دانسته اند. (از اقرب الموارد).<br></font></div>'),
(183994, 'عضاب', '<span class=\"hlight\">عضاب .</span> <font color=\"DarkGreen\"><b>[ ع َض ْ ضا ]</font></b> (ع ص ) مرد نیک دشنام دهنده . (منتهی الارب ). شتام و بسیار ناسزاگوینده . (از اقرب الموارد).<br></font></div>'),
(183995, 'عضاب', '<span class=\"hlight\">عضاب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) رد کردن . معاضبة. (از ناظم الاطباء). رجوع به معاضبة شود.<br></font></div>'),
(183996, 'عضات', '<span class=\"hlight\">عضات .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) هر درخت خاردار را گویند مطلقاً. (برهان ). عضاة. رجوع به عضاة شود.<br></font></div>'),
(183997, 'عضاد', '<span class=\"hlight\">عضاد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) به معنی مصدر مُعاضدة است . (از ناظم الاطباء). رجوع به معاضدة شود.<br></font></div>'),
(183998, 'عضاد', '<span class=\"hlight\">عضاد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) بازوبند. (منتهی الارب ). دملج . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آهنی سرکج مانند داس که شبان بدان شاخ درخت را بر شتر فروکشد. <BR><font color=\"Blue\">◄</font> داغ بازوی شتر. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(183999, 'عضاد', '<span class=\"hlight\">عضاد.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) غلام عضاد؛ کوتاه قامت میانه خلقت . <BR><font color=\"Blue\">◄</font> امراءة عضاد؛ به اضافه و نعت، زن زشت و درشت بازو. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184000, 'عضاد', '<span class=\"hlight\">عضاد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) کوتاه بالا از مرد و زن . <BR><font color=\"Blue\">◄</font> سطبربازو. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184001, 'عضادات', '<span class=\"hlight\">عضادات .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ عِضادة. جوانب هر چیز. رجوع به عضادة شود <span class=\"hlight\">:</span> پیش مسند سلطان طارمی زده و الواح و عضادات آن به مسامیر و شفشهای زر استوار کرده . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٣٤</span>).<br></font></div>'),
(184002, 'عضادتان', '<span class=\"hlight\">عضادتان .</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ ]</font></b> (ع اِ) تثنیه ٔ عِضادة (در حال رفع). عضادتین . رجوع به عضادة شود.<br>- <span class=\"hlight\">عضادتاالابزیم </span> ؛ دو جانب زبانه ٔ کمربند. (از اقرب الموارد).<br>- <span class=\"hlight\">عضادتاالباب </span> ؛ دو بازوی در. (منتهی الارب ). دو چوب دراز دو طرف آن . (از اقرب الموارد). دو چوب بر شکل دو مسطره ازدو جانب در. (از کشاف اصطلاحات الفنون ).<br></font></div>'),
(184003, 'عضادتین', '<span class=\"hlight\">عضادتین .</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ ت َ ]</font></b> (ع اِ) تثنیه ٔ عضادة (در حال نصب و جر). دو بازوی در. دو دالان در. (یادداشت مرحوم دهخدا). رجوع به عضادة و عضادتان شود.<br></font></div>'),
(184004, 'عضادی', '<span class=\"hlight\">عضادی .</span> <font color=\"DarkGreen\"><b>[ ع َ دی ی <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ دی ی <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ دی ی ]</font></b> (ع ص نسبی ) رجل عضادی ؛ مرد بزرگ و سطبر بازو. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184005, 'عضارس', '<span class=\"hlight\">عضارس .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (ع اِ) ج ِ عُضارِس . (منتهی الارب ) (اقرب الموارد). رجوع به عضارس شود. <BR><font color=\"Blue\">◄</font> ج ِ عَضْرَس . (اقرب الموارد). رجوع به عَضْرَس شود.<br></font></div>'),
(184006, 'عضارس', '<span class=\"hlight\">عضارس .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (ع اِ) عَضرَس است در تمام معانی . (از منتهی الارب ) (از اقرب الموارد). ج، عَضارِس . رجوع به عَضرس شود.<br></font></div>'),
(184007, 'عضارط', '<span class=\"hlight\">عضارط.</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (ع اِ) ج ِ عُضرُط. (منتهی الارب ) (اقرب الموارد). رجوع به عضرط شود. <BR><font color=\"Blue\">◄</font> ج ِ عُضارِط. (اقرب الموارد). رجوع به عُضارط شود.<br></font></div>'),
(184008, 'عضارط', '<span class=\"hlight\">عضارط.</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (ع ص ) نوکر که فقط با طعام شکم خدمت کند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مزدور. (منتهی الارب ). اجیر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> لئیم . (اقرب الموارد). عُضرُط. و رجوع به عضرط شود. ج، عَضارط، عَضارطة. (اقرب الموارد).<br></font></div>'),
(184009, 'عضارطی', '<span class=\"hlight\">عضارطی .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ طی ی ]</font></b> (ع ص، اِ) شرمگاه زن که سست و نرم باشد. <BR><font color=\"Blue\">◄</font> کون و اِست . (از منتهی الارب ).<br></font></div>'),
(184010, 'عضارف', '<span class=\"hlight\">عضارف .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (ع اِ) ج ِ عَضْرَفوط. (منتهی الارب ) (اقرب الموارد). رجوع به عضرفوط شود.<br></font></div>'),
(184011, 'عضاریط', '<span class=\"hlight\">عضاریط.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عُضرُط. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ج ِ عُضروط. (اقرب الموارد). رگهای میان دو گوشت پاره ٔ بغل . (ناظم الاطباء). رجوع به عضرط و عضروط شود.<br></font></div>'),
(184012, 'عضاض', '<span class=\"hlight\">عضاض .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) همدیگر را گزیدن . (از منتهی الارب ) (از اقرب الموارد). یکدیگر را بدندان گرفتن . (المصادر زوزنی ) (تاج المصادر بیهقی ). مُعاضّة. و رجوع به معاضة شود.<br></font></div>'),
(184013, 'عضاض', '<span class=\"hlight\">عضاض .</span> <font color=\"DarkGreen\"><b>[ ع َض ْ ضا ]</font></b> (ع ص ) بسیار گزنده و گازگیرنده . عَضوض . (از اقرب الموارد). و رجوع به عضوض شود.<br></font></div>'),
(184014, 'عضاض', '<span class=\"hlight\">عضاض .</span> <font color=\"DarkGreen\"><b>[ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُض ْ ضا ]</font></b> (ع اِ) بن بینی نزدیک ابرو. (منتهی الارب ). عرنین بینی . (از اقرب الموارد).<br></font></div>'),
(184015, 'عضاض', '<span class=\"hlight\">عضاض .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) گزیدن اسب و گزیدگی . (منتهی الارب ). گزیدگی اسب . (دهار). گزیدگی دابه و چهارپا. (از اقرب الموارد): برئت الیک من عضاض هذه الدابة؛ از گزیدن این چارپا مردم را به تو پناه میبرم . <BR><font color=\"Blue\">◄</font> هو عضاض عیش ؛ او نیک شکیبا بر سختی زندگانی است . <BR><font color=\"Blue\">◄</font> زندگانی وعیش : عاض القوم العیش منذ العام فاشتد عضاضهم ؛ زندگی آنان سخت شد. <BR><font color=\"Blue\">◄</font> (ص، اِ) ج ِ عَضوض . (از منتهی الارب ) (از اقرب الموارد). رجوع به عضوض شود.<br></font></div>'),
(184016, 'عضاض', '<span class=\"hlight\">عضاض .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) آنچه گزیده و خورده شود در خوردنی، و از آن جمله است : ما عندنا عضاض ؛ یعنی آنچه قابل خوردن باشد نزد ما نیست . (از منتهی الارب ). آنچه گزیده شود آنگاه خورده شود، چنانکه گویند: لم یذق عضاضاً. (ازاقرب الموارد). <BR><font color=\"Blue\">◄</font> درخت گنده . (منتهی الارب ). آنچه سطبر باشد از درختان . (از اقرب الموارد).<br></font></div>'),
(184017, 'عضاضی', '<span class=\"hlight\">عضاضی .</span> <font color=\"DarkGreen\"><b>[ ع ُضی ی ]</font></b> (ع ص ) مرد نازک و نرم . (منتهی الارب ). مرد ریزه و نرم، و آن از عُضاض است یعنی قسمت نرم بینی . (ازاقرب الموارد). <BR><font color=\"Blue\">◄</font> شتر علف خورده ٔ فربه . (منتهی الارب ). شتر فربه و سمین . (از اقرب الموارد).<br></font></div>'),
(184018, 'عضافج', '<span class=\"hlight\">عضافج .</span> <font color=\"DarkGreen\"><b>[ ع ُ ف ِ ]</font></b> (ع ص ) سخت درشت . (منتهی الارب ). سخت و شدید از شتر و اسب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سطبر پرگوشت . (منتهی الارب ). ضخم و فربه . (از اقرب الموارد).<br></font></div>'),
(184019, 'عضال', '<span class=\"hlight\">عضال .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) شدید وسخت : داء عضال ؛ بیماری سخت و عاجزکننده ٔ اطبا و غالب بر ایشان . (از منتهی الارب ). بیماری سخت و خسته کننده و چیره شونده . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> حلقة عضال ؛ حلقه ٔ سخت و استوار. (از منتهی الارب ). حلقه ٔسخت که ضعف و سستی در آن نباشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> امر عضال ؛ کار دشوار. (منتهی الارب ).<br></font></div>'),
(184020, 'عضام', '<span class=\"hlight\">عضام .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) بن دنب اسب و شتر. (منتهی الارب ). عسیب اسب و شتر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ج ِ عَضم . (منتهی الارب ) (اقرب الموارد). رجوع به عضم شود.<br></font></div>'),
(184021, 'عضامین', '<span class=\"hlight\">عضامین .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ)ج ِ عَیضَمون . (ناظم الاطباء). رجوع به عیضمون شود.<br></font></div>'),
(184022, 'عضان', '<span class=\"hlight\">عضان .</span> <font color=\"DarkGreen\"><b>[ ع ِض ْ ضا ]</font></b> (ع اِ) تثنیه ٔ عِض ّ. رجوع به عِض ّ شود. <BR><font color=\"Blue\">◄</font> (اِخ ) زید و دغفل که دو تن از عالمان عرب در حکمت ها و ایام و جنگهای ایشان بوده اند، و آنان زیدبن حارث بن حارثةبن زیدمناةبن هلال نمری مشهور به کیس نسابة، و دغفل بن حنظلةبن یزیدبن عبداﷲبن ربیعةبن عمروبن شیبان بن ذهل ذهلی نسابة هستند. (از تاج العروس ) (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184023, 'عضاه', '<span class=\"hlight\">عضاه .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) هر درخت عظیم خاردار است، و آن بر دو قسم است خالص و غیرخالص، و درخت ام غیلان را نیز نامند. (مخزن الادویة). اسم جنس اشجار کوچک خاردار است . (تحفه ٔ حکیم مؤمن ). اسمی است که واقع شده است بر هر درختی که از درختهای خارناک باشد مانند عوسج و قتاد و قرظ و سدر و امثال آن . (اختیارات بدیعی ). هر درختی که بزرگ شود و خاردار باشد، و درخت خاردار کوچک را عِض ّ گویند، و درختان خاردار که نه عض هستند نه عضاه، عبارتند از شُکاعی ̍ و حُلاوی ̍ و حاذ و کب و سُلَّج . یک دانه ٔ آن عضاهة و عضة. (از اقرب الموارد). و رجوع به عضاهة شود.<br></font></div>'),
(184024, 'عضاهی', '<span class=\"hlight\">عضاهی .</span> <font color=\"DarkGreen\"><b>[ ع ِ هی ی ]</font></b> (ع ص نسبی ) بعیر عضاهی ؛ شتر عضاه خوار. (منتهی الارب ). آنکه عضاه چرد. (از اقرب الموارد). عضهی . رجوع به عضاهة و عضهی شود.<br></font></div>'),
(184025, 'عضاهیة', '<span class=\"hlight\">عضاهیة.</span> <font color=\"DarkGreen\"><b>[ ع ِ هی ی َ ]</font></b> (ع ص نسبی ) تأنیث عضاهی، منسوب به عضاهة. (از منتهی الارب ). و رجوع به عضاهی شود.<br></font></div>'),
(184026, 'عضایات', '<span class=\"hlight\">عضایات .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) اسم جانوران گزنده است . (تحفه ٔ حکیم مؤمن ). و رجوع به عضایت و عضایه شود.<br></font></div>'),
(184027, 'عضایة', '<span class=\"hlight\">عضایة.</span> <font color=\"DarkGreen\"><b>[ ع َ ی َ ]</font></b> (ع اِ) ضّب است . (از اختیارات بدیعی ) (الفاظ الادویة) (تحفه ٔ حکیم مؤمن ). و رجوع به عضایت شود.<br></font></div>'),
(184028, 'عضایت', '<span class=\"hlight\">عضایت .</span> <font color=\"DarkGreen\"><b>[ ع َ ی َ ]</font></b> (ع اِ) نوعی از سوسمار است و به عربی ضب ّ خوانند. سرگین آن سفیدی که در چشم افتاده باشد ببرد. و آن را عضا هم میگویند به حذف تحتانی و ها. (برهان ). و رجوع به عضایة شود.<br></font></div>'),
(184029, 'عضب', '<span class=\"hlight\">عضب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) بریدن . (منتهی الارب ). قطع کردن .(از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دشنام دادن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گرفتن و زدن و طعن کردن . (منتهی الارب ): عضبه بالعصا؛ با چوبدست وی را زد. عضبه بالرمح ؛ با نیزه وی را طعن کرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ضعیف کردن . (منتهی الارب ):عضب المرض فلاناً؛ بیماری او دیرینه شد و وی را از حرکت بازداشت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بازگشتن . (منتهی الارب ). رجوع . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کهنه گردیدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ناقه وگوسپند را عضباء کردن . (منتهی الارب ) (از اقرب الموارد). رجوع به عضباء شود. <BR><font color=\"Blue\">◄</font> جلوگیری کردن وحبس کردن کسی را از حاجت خود. (از اقرب الموارد).<br></font></div>'),
(184030, 'عضب', '<span class=\"hlight\">عضب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) شمشیر، یا شمشیر برّان . (منتهی الارب ). شمشیر قاطع و برّان، و آن وصف به مصدر است، گویند: سیف عضب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد تیزسخن چرب زبان . <BR><font color=\"Blue\">◄</font> کودک خردسر. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گوساله ٔ شاخ برآورده . (منتهی الارب ). بچه ٔ بقره هرگاه شاخ برآورد، و یا هرگاه شاخ آن به دست گرفته شود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اصطلاح عروض ) حذف میم مفاعلتن است تا فاعلتن بماند و به مفتعلن بدل شود، و آن را معضوب نامند. (از تعریفات جرجانی ). خَرْم مفاعلتن است که سالم باشد، و خَرْم افکندن وتد مجموع باشد، و برخی گویند خَرْم اسقاط اولین متحرک از وتد مجموع است در صورتی که در صدر بیت واقع شده باشد. (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> (اِخ ) نام شمشیر پیغامبر اسلام (ص ). (از اقرب الموارد).<br></font></div>'),
(184031, 'عضب', '<span class=\"hlight\">عضب .</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ ]</font></b> (ع مص ) شکسته گردیدن شاخ و شکافته گوش شدن . (از منتهی الارب ). اعضب شدن قوچ و ناقه . (از اقرب الموارد). و رجوع به اعضب شود.<br></font></div>'),
(184032, 'عضبا', '<span class=\"hlight\">عضبا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) تلفظی است از عضباء در تداول فارسی زبانان، و آن نام ناقه ٔ رسول اﷲ (ص ) است <span class=\"hlight\">:</span> <br>فخرت به سخن باید زیرا که بدو کرد<br>فخر آنکه بکرد از پس او ناقه ٔ عضبا.<br><font color=\"Red\">ناصرخسرو.</font><br>و رجوع به عضباء شود.<br></font></div>'),
(184033, 'عضبار', '<span class=\"hlight\">عضبار.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b>(ع اِ) به معانی عضبارة است . رجوع به عضبارة شود.<br></font></div>'),
(184034, 'عضبل', '<span class=\"hlight\">عضبل .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع ص ) سخت و رست . (منتهی الارب ). صلب و شدید. (از اقرب الموارد). گویا آن تصحیف عِضْیَل ّ باشد. (از تاج العروس ).<br></font></div>'),
(184035, 'عضبیت', '<span class=\"hlight\">عضبیت .</span> <font color=\"DarkGreen\"><b>[ ع َ بی ی َ ]</font></b> (ع مص جعلی، اِمص ) تیززبانی . (غیاث اللغات ) (آنندراج ).<br></font></div>'),
(184036, 'عضد', '<span class=\"hlight\">عضد.</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ ]</font></b> (ع اِ) بازو. (منتهی الارب ). عَضُد. رجوع به عضُد شود. <BR><font color=\"Blue\">◄</font> درخت بریده . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بیماریی است در بازوی شتر و در بازوی ستور. (منتهی الارب ). بیماریی در بازوهای شتر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه از ساختمان و غیره اطراف هر چیز باشد. (از اقرب الموارد). عَضُد. رجوع به عَضُد شود.<br></font></div>'),
(184037, 'عضد', '<span class=\"hlight\">عضد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) بازو. (منتهی الارب ) (دهار) (از اقرب الموارد). عَضُد. رجوع به عَضُد شود. <BR><font color=\"Blue\">◄</font> ناحیه و کرانه . (منتهی الارب ). ناحیه . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> یاریگر و مددکار و ناصر. (منتهی الارب ). ناصر و معین . (از اقرب الموارد). ج، أعضاد. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> رسته ٔ خرمابن . (منتهی الارب ). طریقة از نخل . (از اقرب الموارد).ج، عِضدان . (منتهی الارب ). أعضاد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه از درخت بریده شود. (منتهی الارب ).<br></font></div>'),
(184038, 'عضد', '<span class=\"hlight\">عضد.</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ]</font></b> (ع مص ) دردمندبازو گردیدن شتران . (از منتهی الارب ).بیماری «عَضَد» رسیدن شتر را. (از اقرب الموارد).<br></font></div>'),
(184039, 'عضد', '<span class=\"hlight\">عضد.</span> <font color=\"DarkGreen\"><b>[ ع َ ض ِ ]</font></b> (ع اِ) بازو. (منتهی الارب ) (از اقرب الموارد). عَضُد. رجوع به عَضُد شود. <BR><font color=\"Blue\">◄</font> آنکه نزدیک دو بازوی حوض باشد. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) دردمندبازو. (منتهی الارب ). کسی که از بازوی خود شکایت داشته باشد، و چنین بازویی را عَضِدة گویند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خر نر که مادگان را از اطراف و جوانب فراهم آورده باشد. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184040, 'عضد', '<span class=\"hlight\">عضد.</span> <font color=\"DarkGreen\"><b>[ ع َض ُ ]</font></b> (ع اِ) بازو که میان مرفق و کتف باشد. (منتهی الارب ). بازو. (دهار) (ترجمان القرآن جرجانی ). ساعد، وآن از مرفق و آرنج است تا کتف . و بنی تمیم آن را مذکر دارند و تهامه مؤنث . (از اقرب الموارد). قسمتی ازدست مابین شانه و آرنج . (فرهنگ فارسی معین ). عَضِد.عُضُد. (منتهی الارب ) (اقرب الموارد). عَضد. عَضَد. عِضد. (منتهی الارب ). ج، أعضاد، أعضُد. (اقرب الموارد) <span class=\"hlight\">:</span> قال سنشد عضدک بأخیک و نجعل لکما سلطانا. (قرآن <span class=\"hlight\" dir=\"rtl\">٣٥/٢٨</span>)؛ گفت بازوی ترا به برادرت خواهیم بست و برای شما قدرتی قرار خواهیم داد. <BR><font color=\"Blue\">◄</font> یار و یاریگر. (دهار). یار. (ترجمان القرآن جرجانی ):فَت ّ فی عضده ؛ شکست همراهی اعوان او را و جدا گردانید او را از ایشان . (از منتهی الارب ) (از اقرب الموارد) <span class=\"hlight\">:</span> و ما کنت متخذالمضلین عضدا. (قرآن <span class=\"hlight\" dir=\"rtl\">٥١/١٨</span>)؛ و گمراه کنندگان را مددکار و یاور نگرفته بودم .<br>خواب بیداریت آن دان ای عضد<br>که ببیند خفته کو در خواب شد.<br> <font color=\"Red\">مولوی .</font><br>که من این را بس شنیدم کهنه شد<br>چیز دیگر گو بجز آن ای عضد.<br> <font color=\"Red\">مولوی .</font><br><BR><font color=\"Blue\">◄</font> آنچه از ساختمان و غیره اطراف هر چیز باشد، مانند تخته سنگهایی که در اطراف کناره ٔ حوض نصب میشود. (از اقرب الموارد). عَضَد. و رجوع به عضد شود. <BR><font color=\"Blue\">◄</font> عضد الطریق ؛ کناره و ناحیه ٔ راه . (از اقرب الموارد).<br></font></div>'),
(184041, 'عضد', '<span class=\"hlight\">عضد.</span> <font color=\"DarkGreen\"><b>[ ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ض ُ ]</font></b> (ع اِ) بازو. (منتهی الارب ). عَضُد. رجوع به عَضُد شود.<br></font></div>'),
(184042, 'عضد', '<span class=\"hlight\">عضد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) یاری کردن کسی را و مدد کردن . (از منتهی الارب ) (از اقرب الموارد). یاری کردن . (المصادر زوزنی ) (تاج المصادر بیهقی ) (دهار). <BR><font color=\"Blue\">◄</font> بر بازوی کسی زدن . (از منتهی الارب ) (از اقرب الموارد). بر بازو زدن . (المصادر زوزنی ) (تاج المصادر بیهقی ) (دهار). <BR><font color=\"Blue\">◄</font> دردناک گردیدن بازوی کسی . فعل آن مجهول بکار رود. (از منتهی الارب ) (از اقرب الموارد). دردمند شدن بازو. (المصادرزوزنی ) (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> خسته کردن پالان بازوی شتر را. (از منتهی الارب ). گزیدن «قتب » شتر را و زخم کردن وی را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آمدن رکائب را از جانب اعضاد آنها و گرد کردن آن را. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بر بازو بستن چیزی را. (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> سخت و قوی بازو شدن . <BR><font color=\"Blue\">◄</font> بازو گرفته نشاندن گشن ماده را. <BR><font color=\"Blue\">◄</font> بریدن درخت را. (از منتهی الارب ). درخت از بن بریدن . (المصادر زوزنی ). درخت بریدن . (تاج المصادر بیهقی ) (دهار). عضد الشجرة؛ درخت را به وسیله ٔ معضد قطع کرد. (از اقرب الموارد). و چنین درختی را شجر معضود گویند. (از منتهی الارب ).<br></font></div>'),
(184043, 'عضدالدولة', '<span class=\"hlight\">عضدالدولة.</span> <font color=\"DarkGreen\"><b>[ ع َ ض ُ دُدْ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُو ل َ ]</font></b> (ع اِ مرکب )بازوی دولت . یاور دولت . و آن را لقب بزرگان نهند.<br></font></div>'),
(184044, 'عضدالدوله', '<span class=\"hlight\">عضدالدوله .</span> <font color=\"DarkGreen\"><b>[ ع َ ض ُ دُدْ دَ<span class=\"hlight\" dir=\"rtl\">/</span> دُو ل َ ]</font></b> (اِخ ) احمد میرزابن فتحعلی شاه قاجار، شاهزاده ٔ قاجاری و از رجال قرن سیزدهم هجری در ایران . وی پدر سپهسالار وجیه الدوله میرزا و مؤلف «تاریخ عضدی » است . (از فرهنگ فارسی معین ).<br></font></div>'),
(184045, 'عضدالدین', '<span class=\"hlight\">عضدالدین .</span> <font color=\"DarkGreen\"><b>[ ع َ ض ُ دُدْ دی ]</font></b> (ع اِ مرکب ) بازوی دین . یار و یاور دین . و آن را لقب بزرگان نهند.<br></font></div>'),
(184046, 'عضدالدین ایجی', '<span class=\"hlight\">عضدالدین ایجی .</span> <font color=\"DarkGreen\"><b>[ ع َ ض ُ دُدْ دی ن ِ ]</font></b> (اِخ ) عبدالرحمان بن احمد (مولانا...) دانشمند ایرانی قرن هشتم هجری . تولد او درقصبه ٔ ایج (فارس ) پایتخت قدیم ولایت شبانکاره بود. واو به یک واسطه شاگرد ناصرالدین بیضاوی محسوب می شود. وی از جمله پنج تنی است که خواجه حافظ گوید فارس در عهد شاه شیخ ابواسحاق اینجو به وجود آنان مزین بود. عضدالدین دارای مشرب تصوف بود و در حکمت و کلام و مذهب و اخلاق مهارت داشت . برای شرح بیشتر رجوع به تاریخ مغول، عباس اقبال ص <span class=\"hlight\" dir=\"rtl\">٥١٠</span> و نیز به عبدالرحمان (ابن احمد...) در همین لغت نامه و فرهنگ فارسی معین شود.<br></font></div>'),
(184047, 'عضدالدین سلجوقی', '<span class=\"hlight\">عضدالدین سلجوقی .</span> <font color=\"DarkGreen\"><b>[ ع َ ض ُ دُدْ دی ن ِ س َ ]</font></b> (اِخ ) الب ارسلان فرزند چغری بیک . رجوع به آلب ارسلان (محمدبن داود) شود.<br></font></div>'),
(184048, 'عضدالملک', '<span class=\"hlight\">عضدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ ض ُ دُل ْ م ُ ]</font></b> (ع اِ مرکب ) بازوی پادشاهی . یار و یاور سلطنت . و آن را لقب بزرگان نهند.<br></font></div>'),
(184049, 'عضدالملک', '<span class=\"hlight\">عضدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ ض ُ دُل ْ م ُ ]</font></b> (اِخ ) میرزا محمدحسین قزوینی فرزند میرزا فضل اﷲ، متولی باشی آستانه ٔ قدس رضوی بود که به سال <span class=\"hlight\" dir=\"rtl\">١٢٨٥</span> هَ . ق . درگذشت . (فرهنگ فارسی معین ).<br></font></div>'),
(184050, 'عضدالملک', '<span class=\"hlight\">عضدالملک .</span> <font color=\"DarkGreen\"><b>[ ع َ ض ُدُل ْ م ُ ]</font></b> (اِخ ) علی رضا قاجار. رئیس ایل قاجار و ازرجال اواخر دوره ٔ قاجاریه . پس از خلع محمدعلی شاه قاجار، پسر دوازده ساله اش احمدمیرزا از طرف ملیون به سلطنت رسید و عضدالملک به نیابت سلطنت تعیین شد، و پس از فوت او در رمضان سال <span class=\"hlight\" dir=\"rtl\">١٣٢٨</span> هَ . ق . ابوالقاسم خان ناصرالملک نایب السلطنه گردید. (فرهنگ فارسی معین ).<br></font></div>'),
(184051, 'عضدان', '<span class=\"hlight\">عضدان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ عَضید.(منتهی الارب ) (اقرب الموارد). رجوع به عضید شود. <BR><font color=\"Blue\">◄</font> ج ِ عَضد. (منتهی الارب ). رجوع به عضد شود.<br></font></div>'),
(184052, 'عضدان', '<span class=\"hlight\">عضدان .</span> <font color=\"DarkGreen\"><b>[ ع َ ض ُ ]</font></b> (ع اِ) تثنیه ٔ عَضد (در حالت رفع). دو بازو. (ناظم الاطباء). رجوع به عَضُد شود.<br></font></div>'),
(184053, 'عضدی', '<span class=\"hlight\">عضدی .</span> <font color=\"DarkGreen\"><b>[ ع َ ض ُ دی ی ]</font></b> (ص نسبی ) منسوب به عضدالدوله ٔ دیلمی . رجوع به عضدالدوله ٔ دیلمی شود.<br>- <span class=\"hlight\">بند عضدی </span> ؛ بندی است در حوالی شیرازکه در زمان عضدالدوله ٔ دیلمی برای مشروب کردن اراضی کربال علیا و سفلی ساخته شد و به بند امیر شهرت دارد <span class=\"hlight\">:</span> بند عضدی که در جهان مثل آن عمارت نیست از محکمی و نیکوئی ولایت کربال علیا را آب می دهد. (نزهة القلوب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٩</span>). از یزدخواست راه زمستان به بند عضدی رود بدست چپ و راه تابستان بدست راست به کوشک زرد. (نزهة القلوب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٥</span>). رجوع به بند امیر شود.<br>- <span class=\"hlight\">سقلاطون عضدی </span> ؛ سقلاطون نوعی جامه و یا ماهوت دورواست، و در ترجمه ٔ تاریخ یمینی آن را با نسبت به عضدی ذکر کرده است و در حاشیه ٔ کتاب نویسد بهتر از همه قسم سقلاطون آن بود که عضدالدوله اختیار کرده بود <span class=\"hlight\">:</span> و پنجاه تخت جامه ملون از جامه های تستری و سقلاطون عضدی حله های فخری ... (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٨١</span>).<br></font></div>'),
(184054, 'عضدی مشکانی', '<span class=\"hlight\">عضدی مشکانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ض ُ ی ِ م ُ ]</font></b> (اِخ ) در کتاب اسکندرنامه، نظم کردن داستان عشقی «اهراوستودن » به وی نسبت داده شده است . (از یادداشت مؤلف ). و رجوع به سبک شناسی بهار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٩</span> و <span class=\"hlight\" dir=\"rtl\">١٣٠</span> شود.<br></font></div>'),
(184055, 'عضدیة', '<span class=\"hlight\">عضدیة.</span> <font color=\"DarkGreen\"><b>[ ع َ ض ُ دی ی َ ]</font></b> (اِخ ) آبی است شرقی فید. (منتهی الارب ). آبی است در سمت مغرب فیدا ومغیشة در طریق الحاج بسوی مکه . (از معجم البلدان ).<br></font></div>'),
(184056, 'عضر', '<span class=\"hlight\">عضر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) آشکار کردن و بر زبان آوردن کلمه . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184057, 'عضر', '<span class=\"hlight\">عضر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) بطنی است از یمن . (منتهی الارب ).<br></font></div>'),
(184058, 'عضرس', '<span class=\"hlight\">عضرس .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) گورخر. (منتهی الارب ). حمارالوحش . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سرما. (از منتهی الارب ). بَرْد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> یخچه . (منتهی الارب ). بَرَد. تگرگ . ژاله . (از اقرب الموارد).<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">ابرد من عضرس </span> . (از منتهی الارب ) (اقرب الموارد).<br><BR><font color=\"Blue\">◄</font> آب سرد و شیرین . (منتهی الارب ). آب سرد وگوارا. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> برف . (منتهی الارب ). ثلج . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> برگ که صبح بر آن تری باشد، و برگ چسبیده بر سنگریزه در زیر آب . (منتهی الارب ). برگ درخت که بر آن ژاله باشد، وگویند سبزیی است که بر سنگ چسبیده باشد و در آب خیس شده باشد. (از اقرب الموارد). عُضارِس . و رجوع به عضارس شود. <BR><font color=\"Blue\">◄</font> گیاهی  است که سبزی آن به سپیدی زند و سخت بردارد تری را. (منتهی الارب ). عشب و گیاهی است اشهب که به سبزی زند، و ژاله و «ندی » را بسیار برمی دارد. (از اقرب الموارد). عُضارس . عِضرِس . ج، عُضارس . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184059, 'عضرس', '<span class=\"hlight\">عضرس .</span> <font color=\"DarkGreen\"><b>[ ع ِ رِ ]</font></b> (ع اِ) عَضرَس است در معنی گیاهی که سبزی آن به سپیدی زند و... (منتهی الارب ) (از اقرب الموارد). رجوع به عَضرَس شود. <BR><font color=\"Blue\">◄</font> درخت خطمی . (منتهی الارب ) (از اقرب الموارد). خطمی بری . (الفاظ الادویة) (تحقه ٔ حکیم مؤمن ). خطمی بری است که به یونانی بادر و به عربی شحم المرج نامند. (مخزن الادویه ). خطمی صحرائی به یونانی البا و به عربی شحم المرج خوانند، و طبیخ آن رااگر با سرکه و زیت بر اعضا مالند منع مضرت گزندگان کند. (برهان ). یک دانه ٔ آن را عضرسة گویند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آب ایستاده . (منتهی الارب ).<br></font></div>'),
(184060, 'عضرسة', '<span class=\"hlight\">عضرسة.</span> <font color=\"DarkGreen\"><b>[ ع ِ رِ س َ ]</font></b> (ع اِ)یکی عضرس . (از اقرب الموارد). رجوع به عضِرس شود.<br></font></div>'),
(184061, 'عضرط', '<span class=\"hlight\">عضرط.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ رِ ]</font></b> (ع اِ) میان دو خصیه و دبر. <BR><font color=\"Blue\">◄</font> حلقه ٔ دبر. <BR><font color=\"Blue\">◄</font> سرین، یا استخوان برآمده ٔ بالای دبر. <BR><font color=\"Blue\">◄</font> خط که از ذکر تا دبر است . فلان أهلب العضرط؛ بر عضرط او موی بسیار است . (از منتهی الارب ).<br></font></div>'),
(184062, 'عضرط', '<span class=\"hlight\">عضرط.</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ]</font></b> (ع ص ) نوکر که فقط با طعام شکم خدمت کند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مزدور. (منتهی الارب ). اجیر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناکس . (منتهی الارب ). لئیم . (اقرب الموارد). عُضارط و رجوع به عضارط شود. ج، عَضارط. (منتهی الارب ) (اقرب الموارد)، عَضاریط، عَضارِطَة. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خادم و به دنبال کسی دونده . ج، عَضاریط. (منتهی الارب ).<br></font></div>'),
(184063, 'عضرفوط', '<span class=\"hlight\">عضرفوط.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) کرمکی است سپید نازک، که بدان انگشتان زنان را تشبیه دهند. یا گربه ٔ نر که از دواب دیوان است . (منتهی الارب ). به فارسی آن را کرباسو گویند، و گویند جانوری است سفید و نرم که انگشت دختران را بدان تشبیه کنند. (غیاث اللغات ) (آنندراج ). جانوری است که به فارسی مارمولک و به هندی بهمنی نامند. (مخزن الادویه ). عذفوط، و گویند آن نر«عظاء» است، و گویند آن از دواب و رکائب جن است . (از اقرب الموارد). تصغیر آن عُضَیرف و عُضَیریف است . ج، عَضارف، عضرفوطات . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(184064, 'عضرفوطات', '<span class=\"hlight\">عضرفوطات .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) ج ِ عَضرفوط.(منتهی الارب ) (اقرب الموارد). رجوع به عضرفوط شود.<br></font></div>'),
(184065, 'عضرم', '<span class=\"hlight\">عضرم .</span> <font color=\"DarkGreen\"><b>[ ع ِ رِ ]</font></b> (ع اِ) گیاهی است که در نان کنند. (یادداشت بخط مرحوم دهخدا).<br></font></div>'),
(184066, 'عضرن', '<span class=\"hlight\">عضرن .</span> <font color=\"DarkGreen\"><b>[ ع ِ رِ ]</font></b> (ع اِ) برزق است . (مخزن الادویه ). رجوع به برزق شود.<br></font></div>'),
(184067, 'عضروط', '<span class=\"hlight\">عضروط.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) گلو، و آن سر معده است چسبیده به حلقوم دراز سرخ سپید شکم . (منتهی الارب ). مری و سرخ روده . (ناظم الاطباء). مری ءالحلق ؛ و آن سر معده باشد که به حلقوم متصل و چسبیده است و سرخ و مستطیل است و داخل آن سفید. (از اقرب الموارد)(از تاج العروس ). <BR><font color=\"Blue\">◄</font> مزدور. (منتهی الارب ).اجیر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خادم و بدنبال کس رونده . (منتهی الارب ). عُضارط. (اقرب الموارد). و رجوع به عضارط شود. ج، عَضاریط. (از اقرب الموارد).<br></font></div>'),
(184068, 'عضز', '<span class=\"hlight\">عضز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) بازداشتن . <BR><font color=\"Blue\">◄</font> خائیدن . (منتهی الارب ). وآن لغتی است مستنکر به جهت اجتماع ضاد و زاء، و بصریان آن را نشناسند. (منتهی الارب ) (از ناظم الاطباء).<br></font></div>'),
(184069, 'عضض', '<span class=\"hlight\">عضض .</span> <font color=\"DarkGreen\"><b>[ ع ُ ض َ ]</font></b>(ع اِ) ج ِ عَضوض . (منتهی الارب ). رجوع به عضوض شود.<br></font></div>'),
(184070, 'عضط', '<span class=\"hlight\">عضط.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) حدث کردن وقت جماع . (منتهی الارب ).<br></font></div>'),
(184071, 'عضعض', '<span class=\"hlight\">عضعض .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (ع ص ) سخت بدخلق و عِض ّ، و برخی آن را خاص مذکر دانند. (از اقرب الموارد).<br></font></div>'),
(184072, 'عضفوط', '<span class=\"hlight\">عضفوط.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) به معنی عضرفوط است . (منتهی الارب ) (از اقرب الموارد). رجوع به عضرفوط شود.<br></font></div>'),
(184073, 'عضل', '<span class=\"hlight\">عضل .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) مرد زیرک . (منتهی الارب ). داهیة. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سخت درشت .(منتهی الارب ). سخت زشت و قبیح . (از اقرب الموارد).<br></font></div>'),
(184074, 'عضل', '<span class=\"hlight\">عضل .</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ ]</font></b> (ع مص ) عضله ناک گردیدن، یا سطبر شدن پی ساق کسی . (منتهی الارب ). بسیار عَضَل شدن یا ضخیم شدن عضله ٔ ساق شخص . (اقرب الموارد). بسیار عضله شدن . (تاج المصادر بیهقی ).<br></font></div>'),
(184075, 'عضل', '<span class=\"hlight\">عضل .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) به ستم بازداشتن زن را از شوی کردن . (از منتهی الارب ) (از اقرب الموارد). عَضْل . رجوع به عَضل شود.<br></font></div>'),
(184076, 'عضل', '<span class=\"hlight\">عضل .</span> <font color=\"DarkGreen\"><b>[ ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ]</font></b> (ع اِ) ج ِ عَضَل . (منتهی الارب ) (اقرب الموارد). رجوع به عَضل شود.<br></font></div>'),
(184077, 'عضل', '<span class=\"hlight\">عضل .</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ ]</font></b> (اِخ ) جایگاهی است در بادیه . (از معجم البلدان ). جایی است در بادیه نیستان ناک، و آن را به سکون دوم نیز خوانده اند. (منتهی الارب ).<br></font></div>'),
(184078, 'عضل', '<span class=\"hlight\">عضل .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (ع مص ) تنگ نمودن بر کسی . (از منتهی الارب ). تنگ کردن بر کسی و حبس کردن و منع کردن وی را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دشوار گردیدن بر کسی کار. (از منتهی الارب ): عضل به الامر؛ کار بر او سخت شد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> به ستم بازداشتن زنی را ازشوی کردن . (از منتهی الارب ). زن را از شوی کردن بازداشتن . (المصادر زوزنی ) (دهار) (ترجمان القرآن جرجانی ). بازداشتن از شوی کردن . (تاج المصادر بیهقی ): عضل المراءة عن الزواج ؛ زن را از ازدواج حبس کرد و بازداشت . (از اقرب الموارد). عِضل . عِضلان . و رجوع به عضل و عضلان شود. <BR><font color=\"Blue\">◄</font> بد زیستن با زن خویش تا خود رابه کاوین بازخرد. (المصادر زوزنی ). بد زیستن با زن تا خود را بازخرد. (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> عضل الرجل ؛ آن مرد را بیوه کرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بر عضله ٔ کسی زدن . (از اقرب الموارد از تاج ). <BR><font color=\"Blue\">◄</font> خسته شدن شتر از حرکت و سواری و از هر کاری . (از اقرب الموارد به نقل از لسان ).<br></font></div>'),
(184079, 'عضل', '<span class=\"hlight\">عضل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) جایی است در بادیه . عَضَل . (از منتهی الارب ). رجوع به عَضَل شود.<br></font></div>'),
(184080, 'عضل', '<span class=\"hlight\">عضل .</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ ]</font></b> (اِخ ) ابن هون بن خزیمةبن مدرکة، از کنانه از مضر. جدی است جاهلی و فرزندانش با برادرزاده ٔ او به نام دیش درهم آمیختند و بنام «قارة» خوانده شدند. و قاره در عهد جاهلیت در تیراندازی شهرت داشتند و آنان هم پیمان بنی زهرة بودند و عبدالرحمان بن عبدالقاری و عبداﷲبن عثمان بن خشیم قاری از آنان است . (از الاعلام زرکلی به نقل از نهایة الارب و جمهرة الانساب و الاغانی و مجمع الامثال ).<br></font></div>'),
(184081, 'عضل', '<span class=\"hlight\">عضل .</span> <font color=\"DarkGreen\"><b>[ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ض َ ]</font></b> (ع اِ) ج ِ عُضلة. (منتهی الارب ) (اقرب الموارد). رجوع به عُضلة شود.<br></font></div>'),
(184082, 'عضل', '<span class=\"hlight\">عضل .</span> <font color=\"DarkGreen\"><b>[ ع َ ض ِ <span class=\"hlight\" dir=\"rtl\">/</span> ض ُ ]</font></b> (ع ص ) عضله ناک . (منتهی الارب ).آنکه پر عَضل َ باشد یا عضله ٔ ساق او سطبر و ضخیم باشد. (از اقرب الموارد). ج، أعضال . (ناظم الاطباء).<br></font></div>'),
(184083, 'عضل', '<span class=\"hlight\">عضل .</span> <font color=\"DarkGreen\"><b>[ ع َض َ ]</font></b> (ع اِ) کلاکموش . (منتهی الارب ). جُرَذ. (اقرب الموارد). به لغت اهل یمن جرذ است . (مخزن الادویه ). ج، عِضلان و عُضلان . <BR><font color=\"Blue\">◄</font> ج ِ عَضَله . (منتهی الارب ) (اقرب الموارد). گوشت پاره ها با پی ها مرکب، واحدش عضلة. (غیاث اللغات ) <span class=\"hlight\">:</span> فاضلترین گوشت مواشی و نیکوترین عضله است که به شیرازی مشکک خوانند و زودترهضم شود. (از اختیارات بدیعی ). رجوع به عضله شود.<br></font></div>'),
(184084, 'عضلات', '<span class=\"hlight\">عضلات .</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ ]</font></b> (ع اِ) ج ِ عَضَلة. (منتهی الارب ) (اقرب الموارد). ماهیچه ها و گوشتهای بدن . (فرهنگ فارسی معین ). رجوع به عَضلة شود.<br></font></div>'),
(184085, 'عضلان', '<span class=\"hlight\">عضلان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) به معنی مصدر عَضل و عِضل است . (از منتهی الارب ) (از اقرب الموارد). رجوع به عضل شود.<br></font></div>'),
(184086, 'عضلانی', '<span class=\"hlight\">عضلانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ ]</font></b> (ع ص نسبی ) منسوب به عضلة. (فرهنگ فارسی معین ). رجوع به عضلة شود: قوه ٔ عضلانی . این دارو قابل تزریق از طریق عضلانی است . (مقابل طریق وریدی ). (یادداشت به خط مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> صاحب عضله های محکم و بزرگ . آنکه عضلات کلان و سخت دارد. عضله ناک . پیچیده . (یادداشت بخط مرحوم دهخدا). گوشتدار. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">احساسات عضلانی </span> ؛ در اصطلاح روانشناسی، هرگاه بر احساسات وضعی، حس فشار افزوده شود (مانند موقعی که وزنه ای را بلند می کنیم ) و کشش در کار باشد آنها را احساسات عضلانی می نامیم . (فرهنگ فارسی معین ). و رجوع به روانشناسی تربیتی دکتر سیاسی ص <span class=\"hlight\" dir=\"rtl\">٨٤</span> شود.<br>- <span class=\"hlight\">بافت عضلانی </span> ؛ در اصطلاح پزشکی، نسج عضلانی . (از فرهنگ فارسی معین ). رجوع به نسج عضلانی در همین ترکیبات شود.<br>- <span class=\"hlight\">سلول عضلانی </span> ؛ سلول ماهیچه ای . (از فرهنگ فارسی معین ). رجوع به سلول و ماهیچه و نیام شود.<br>- <span class=\"hlight\">غلاف عضلانی </span> ؛ در اصطلاح پزشکی نیام ماهیچه . (فرهنگ فارسی معین ). رجوع به ماهیچه و نیام شود.<br>- <span class=\"hlight\">نسج عضلانی </span> ؛ در اصطلاح پزشکی، بافتی است که از سلولهای ماهیچه ای درست شده و تشکیل عضلات بدن را می دهد. بافت عضلانی . بافت ماهیچه ای . (فرهنگ فارسی معین ).<br></font></div>'),
(184087, 'عضلة', '<span class=\"hlight\">عضلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ ل َ ]</font></b> (ع اِ) پی یا گوشت درشت، و گوشت بازو و ساق، و هر گوشت که پر و مجتمع باشد در پی . (منتهی الارب ). گوشت ساق و گوشت بازو. (دهار). هر عصبی که با آن گوشت بسیار و مجتمع و انباشته همراه باشد. (از اقرب الموارد). ماهیچه ٔ ساق و هرگوشتی که مجتمع در جوف غلافی بود و هر گوشتی که با پی همراه بود. و در اصطلاح تشریح، آلتی لحم و لیفی که متشکل می سازد گوشت بدن انسان و دیگر حیوانات را و چون متقلص گردد حاصل می نماید حرکات بدن را. (ناظم الاطباء). هر عضوی را نامند که گوشت با آن باشد، و یا عضوی است مرکب از عصب و از جسمی مانند عصب که در اطراف استخوانها روئیده می شود و آن را <font color=\"DarkGreen\"><b>[ جسم مانند عصب را ]</font></b> رباط گویند، و گویند عضله جسمی است مرکب از عصب و رباط و گوشت سرخ و غشاء. صاحب ذخیره گوید غدد عضلات بدن آدمی به قول اصح پانصدوپانزده است و شیخ گوید که پانصدوبیست ونه است . (کشاف اصطلاحات الفنون ). نسج فیبری و قابل تحریک که از الیاف ماهیچه ای ساخته شده و مجموعاً گوشتهای بدن را تشکیل می دهند و حرکات بدن را سبب می شوند. در بدن انسان دو نوع عضله موجود است، عضلات مخطط که عمل آنها در اختیار انسان است مثل عضلات دست و پا و دیگر عضلات صاف  که عمل آنها در اختیار آدمی نیست مثل عضلات احشاء درونی (به استثنای عضله ٔ قلب که با اینکه از عضلات مخطط است ولی در اختیار انسان نیست ). تعداد عضلات بدن در حدود چهارصد است . وزن عضلات در حدود نصف وزن بدن است . هرعضله مرکب از سه قسمت می باشد: <span class=\"hlight\" dir=\"rtl\">١</span>- شکم یا اندام عضله که در وسط قرار گرفته است . <span class=\"hlight\" dir=\"rtl\">٢</span>- وتر عضله که دو طرف آن واقع است و به اعضای مجاور یا استخوانهای نزدیک می چسبد. <span class=\"hlight\" dir=\"rtl\">٣</span> - غلاف  یا نیام که روی عضله را می پوشاند.<br>در ساختمان عضلات مخطط یک عده الیاف ماهیچه ای وجود دارند که بوسیله ٔ یک غلاف به نام غلاف فیبری احاطه شده اند. یک فیبر ماهیچه ای عبارت از رشته ٔ درازی است که در انسان ممکن است تا صدوبیست هزار میکرن (صدوبیست میلیمتر) طول داشته باشد در حالیکه قطرش بین بیست تا صد میکرن بیشتر نیست . در هر فیبر ماهیچه ای تعدادزیادی هسته در قسمت محیطی فیبر موجود است . یک فیبر ماهیچه ای را می توانیم یک سلول ماهیچه ای بنامیم . عضلات صاف از سلولهای دوکی شکل که شامل یک هسته هستند درست شده اند. (فرهنگ فارسی معین ). ماهیچه . مایچه . موشک . موش گوشت  ج، عَضَل و عَضَلات . (منتهی الارب ) (اقرب الموارد).<br>- <span class=\"hlight\">دو عضله ٔ ظهریا پشت </span> ؛ دو عضله است که پشت را به جانب خلف دو تا می کند. (از بحر الجواهر) (از کشاف اصطلاحات الفنون ).<br>- <span class=\"hlight\">دو عضله ٔ عریضه </span> ؛ دوعضله است بر رخساره از هر جانب یکی و بعضی از حرکتهای لب به این دو عضله است . (از بحر الجواهر) (از کشاف اصطلاحات الفنون ).<br>- <span class=\"hlight\">عضله ٔ مکرره </span> ؛ دو عضله ٔ کج هستند که به آن دهان گشاده شود. (از کشاف اصطلاحات الفنون ).<br><BR><font color=\"Blue\">◄</font> درختچه ای است مانند دفلی . (از اقرب الموارد).<br></font></div>'),
(184088, 'عضلة', '<span class=\"hlight\">عضلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ض ِ ل َ ]</font></b> (ع ص ) زن پرگوشت و سمج و زشت . (از اقرب الموارد از لسان ).<br></font></div>'),
(184089, 'عضلة', '<span class=\"hlight\">عضلة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ]</font></b>(ع اِ) بلا و سختی . (منتهی الارب ). داهیة. (اقرب الموارد). انه لَعضلة من العضل ؛ آن بلائی است از بلاها. ج، عُضْل و عُضَل . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(184090, 'عضلت', '<span class=\"hlight\">عضلت .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ]</font></b> (ع اِ) عضلة. بلا. سختی . (یادداشت به خط مرحوم دهخدا). رجوع به عُضْلة شود.<br></font></div>'),
(184091, 'عضلم', '<span class=\"hlight\">عضلم .</span> <font color=\"DarkGreen\"><b>[ ع ِ ل َ ]</font></b> (ع اِ) درخت نیل . (آنندراج ).<br></font></div>'),
(184092, 'عضله ناک', '<span class=\"hlight\">عضله ناک .</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ض ُ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (ص مرکب ) گوشتی و دارای ماهیچه . (ناظم الاطباء). عضلانی . و رجوع به عضلانی شود.<br></font></div>'),
(184093, 'عضم', '<span class=\"hlight\">عضم .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (ع اِ) قبضه ٔ کمان . (منتهی الارب ). مقبض قوس . (اقرب الموارد). ج، عِضام . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سرآماج و بیل گندم پاک کن که به صورت انگشتان سازند. (منتهی الارب ). چوبی دارای انگشتان که گندم را بدان به باد دهند. (از اقرب الموارد). سراماج و افشون . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> دمغزه ٔ شتر و اسب و بز کوهی نر. (منتهی الارب ). عسیب اسب و شتر و بز کوهی . (از اقرب الموارد). ج، اءَعضِمة. عُضم . <BR><font color=\"Blue\">◄</font> تخته ٔ فدان که بر سرش آهن باشد. <BR><font color=\"Blue\">◄</font> خطی در کوه که رنگش مخالف رنگ کوه باشد. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184094, 'عضم', '<span class=\"hlight\">عضم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عَضم . (منتهی الارب ) (از اقرب الموارد). رجوع به عَضم شود.<br></font></div>'),
(184095, 'عضمر', '<span class=\"hlight\">عضمر.</span> <font color=\"DarkGreen\"><b>[ ع َ ض َم ْ م َ ]</font></b> (ع ص ) بخیل تنگدل و بدخوی . (منتهی الارب ). بخیل . ضیق . (اقرب الموارد).<br></font></div>'),
(184096, 'عضمز', '<span class=\"hlight\">عضمز.</span> <font color=\"DarkGreen\"><b>[ ع َ ض َم ْ م َ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ). اسد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) درشت از هر چیزی . (منتهی الارب ). شدید و سخت از هر چیز. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زفت . (منتهی الارب ). بخیل . (اقرب الموارد).<br></font></div>'),
(184097, 'عضمور', '<span class=\"hlight\">عضمور.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) چرخ چاه . (منتهی الارب ). دولاب . (اقرب الموارد). و آن تصحیف عصمور نیست . (از منتهی الارب ).<br></font></div>'),
(184098, 'عضنک', '<span class=\"hlight\">عضنک .</span> <font color=\"DarkGreen\"><b>[ ع َ ض َن ْ ن َ ]</font></b>(ع ص ) سطبر درشت . (منتهی الارب ). غلیظ و شدید. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شرم زن بزرگ پرگوشت . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> زن لفاء و بزرگ ران که به فربهی و بزرگی وی ملتقای ران او تنگ باشد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> زن کلان فرج بزرگ سرین . (از منتهی الارب ).<br></font></div>'),
(184099, 'عضه', '<span class=\"hlight\">عضه .</span> <font color=\"DarkGreen\"><b>[ ع َض ِه ْ ]</font></b> (ع ص ) مکان عضه ؛ جایی که عضاه فراوان داشته باشد. و رجوع به عضاه شود. <BR><font color=\"Blue\">◄</font> شتر که عضاه چرد. (از اقرب الموارد). شتر عضاه خوار. (منتهی الارب ).<br></font></div>'),
(184100, 'عضه', '<span class=\"hlight\">عضه .</span> <font color=\"DarkGreen\"><b>[ ع َض َه ْ ]</font></b> (ع مص ) بیمار گردیدن شتران از خوردن عضاه، و یا چریدن آن را. (از منتهی الارب ): عضه البعیر؛ آن شتر ازچریدن عضاه شکایت کرد و گویند به معنی عضاه را چریده باشد. (اقرب الموارد). عضاه چریدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> دروغ گفتن . <BR><font color=\"Blue\">◄</font> سخن چینی نمودن . (از اقرب الموارد) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> افسون کردن . (از منتهی الارب ). ساحری . (اقرب الموارد). عَضه . رجوع به عضه شود. <BR><font color=\"Blue\">◄</font> تهمت نمودن و دروغ بربستن بر کسی . (از منتهی الارب ). افک و بهتان آوردن . (از اقرب الموارد). بد گفتن (المصادر زوزنی ). <BR><font color=\"Blue\">◄</font> بریدن عضاه را. (از منتهی الارب ).<br></font></div>'),
(184101, 'عضه', '<span class=\"hlight\">عضه .</span> <font color=\"DarkGreen\"><b>[ ع َض ْه ْ ]</font></b> (ع مص ) دروغ گفتن . (از منتهی الارب ). کذب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سخن چینی نمودن . (از منتهی الارب ). نمامی کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> افسون کردن . (از منتهی الارب ). سحر کردن . (از اقرب الموارد). عَضَه . عِضهه . عَضیهة. و رجوع به عضه و عضهة و عضیهة شود. <BR><font color=\"Blue\">◄</font> خوردن شتر عضاه را. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> قطع کردن، گویند: عضه العضاه ؛ یعنی عضاه را قطع کرد و برید. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بهتان زدن به کسی ؛ یعنی در باره ٔ او چیزی گفتن که در وی نیست . (از اقرب الموارد).<br></font></div>'),
(184102, 'عضهة', '<span class=\"hlight\">عضهة.</span><font color=\"DarkGreen\"><b>[ ع ِ هََ ]</font></b> (ع مص ) دروغ گفتن . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سخن چینی نمودن . (از منتهی الارب ). نمامی کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> افسون کردن . (از منتهی الارب ). سحر کردن . (از اقرب الموارد). عَضْه . عَضَه . عَضیَهة. رجوع به عضه شود.<br></font></div>'),
(184103, 'عضهة', '<span class=\"hlight\">عضهة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ض َ هََ ]</font></b> (ع اِ) درخت خاردار بزرگ و دراز. یکدانه عضاه . (از منتهی الارب ). رجوع به عضاه و عَضِه شود.<br></font></div>'),
(184104, 'عضهة', '<span class=\"hlight\">عضهة.</span> <font color=\"DarkGreen\"><b>[ ع َ ض ِ هََ ]</font></b> (ع ص ) مؤنث عَضِه : أرض عضهة؛ زمین عضاه ناک . (منتهی الارب ). زمین بسیارعضاه . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناقه و ماده شترعضاه خوار. (از اقرب الموارد). رجوع به عَضِه شود.<br></font></div>'),
(184105, 'عضهلة', '<span class=\"hlight\">عضهلة.</span> <font color=\"DarkGreen\"><b>[ ع َ هََ ل َ ]</font></b> (ع مص ) بستن سر قاروره و بطری را. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184106, 'عضهی', '<span class=\"hlight\">عضهی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ض َ هی ی ]</font></b> (ص نسبی ) شتر که عضاه خوار باشد. (از منتهی الارب ) (از اقرب الموارد). عضاهی . عضوی . و رجوع به عضاهی و عضوی شود.<br></font></div>'),
(184107, 'عضو', '<span class=\"hlight\">عضو.</span> <font color=\"DarkGreen\"><b>[ ع ُ ض ُوو ]</font></b> (ع مص ) با لباس و نیکوحال و خوش روزگذار بودن . (منتهی الارب ). بودن شخص، پوشیده لباس و طعام دار وبه اندازه ٔ کفایت دارنده و آن را کمال رفاهیت است و«عاضی » از این لغت مشتق باشد. (از اقرب الموارد).<br></font></div>'),
(184108, 'عضو', '<span class=\"hlight\">عضو.</span> <font color=\"DarkGreen\"><b>[ ع ُض ْوْ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِض ْوْ ]</font></b> (ع اِ) اندام و هرگوشت فراهم آمده در استخوان . (منتهی الارب ). اندام . (مهذب الاسماء) (دهار) (غیاث اللغات ). اجزای کثیفه ٔ بدن حیوان متولد از منی و کثیف اخلاط است . و آن یا مفرد است مانند استخوان و غضروف و عصب و رباط و عروق و لحم و شحم و سمن و یا مرکب ترکیب اولی مانند عضل و یا ثانوی مانند عین و یا ثالثی مانند وجه و یا رابعی مانند رأس . (از مخزن الادویه ). هر گوشت که با استخوان خود فراهم آمده باشد، و گویند هر استخوانی از جسد که با گوشت خود فراهم آمده باشد، و گویند آن جزئی است از مجموع جسد مانند دست و پا و گوش و غیره . (از اقرب الموارد). جزوی از بدن مثل دست و پا و سر. و در اصطلاح پزشکی، مجموعه ٔ بافتهایی است از بدن یک موجود زنده پرسلول که وظیفه ای مشترک را بعهده دارند مانند قلب و ریه و معده که هریک از چند بافت ساخته شده است . (فرهنگ فارسی معین ). جارحة. پاره . پاره ٔ تن . ارب . جرموز. عاهن . کحف . کردوس . ورب .ج، اعضاء. (منتهی الارب ) (اقرب الموارد) <span class=\"hlight\">:</span> <br>عضوی زتو گر دوست شود با دشمن <br>دشمن دو شمر تیغ دو کش زخم دو زن .<br> <font color=\"Red\">رونی .</font><br>هر یکی را به لمس هر عضوی <br>اطلاع اوفتاد بر جزوی .<br> <font color=\"Red\">سنایی .</font><br>غذی از جگر پذیرد همه عضوها و لکن <br>غذی از دهان بیک ره بسوی جگر نیاید.<br> <font color=\"Red\">خاقانی .</font><br>ورم غدر کند رویت سرخ <br>سرخی عضو دلیل ورم است .<br> <font color=\"Red\">خاقانی .</font><br>زانکه بی لذت نروید هیچ جزو<br>بلکه لاغر گردد از هر پیچ عضو.<br> <font color=\"Red\">مولوی .</font><br>چو عضوی بدرد آورد روزگار<br>دگر عضوها را نماند قرار.<br> <font color=\"Red\">سعدی .</font><br>نخواهد که بیند خردمند ریش <br>نه بر عضو مردم نه بر عضو خویش .<br> <font color=\"Red\">سعدی .</font><br>گر ز هفت آسمان گزند آید<br>همه بر عضو دردمند آید.<br> <font color=\"Red\">سعدی .</font><br>یار چو تیغ کین کشد فرصتش از خدا طلب <br>عضو به عضو خویش را زخم جداجداطلب .<br> <font color=\"Red\">محشری نیشابوری (از آنندراج ).</font><br>- <span class=\"hlight\">عضو بارد</span> ؛ در اصطلاح فلسفه و پزشکی قدیم، دماغ و مغز است . (از فرهنگ علوم عقلی به نقل از اسفار و شفا). و رجوع به عضو حار شود.<br>- <span class=\"hlight\">عضو بسیط</span> ؛ هر یک از دماغ و قلب و کبد است . (از فرهنگ علوم عقلی به نقل از اسفار).<br>- <span class=\"hlight\">عضو حار</span> ؛ در اصطلاح فلسفه و پزشکی قدیم، قلب و دل است . و شیخ الرئیس در بیان اعضای حاره و بارده گوید: نزدیکی به توازن و اعتدال مزاج بواسطه ٔ تکافؤ اعضای حاره مانند قلب و بارده مانند دماغ و رطبه مانند کبد و یابسه مانند استخوان حاصل می شود. (از فرهنگ علوم عقلی به نقل از شفا و اسفار).<br>- <span class=\"hlight\">عضو رطب </span> ؛ کبداست . (فرهنگ علوم عقلی، از اسفار و شفا). و رجوع به عضو حار شود.<br>- <span class=\"hlight\">عضوهای رئیسه </span> ؛ اعضایی هستند که مبداء قوه و نیرو باشند و برای بقای شخص لازم می باشند مانند قلب و دماغ و کبد. (از کشاف اصطلاحات الفنون ) <span class=\"hlight\">:</span> <br>گفتم که عضوهای رئیسه دل است و مغز<br>گفتا سپرز و گرده و زهره است و پس جگر.<br> <font color=\"Red\">ناصرخسرو.</font><br>- <span class=\"hlight\">عضو یابس </span> ؛ استخوان است . (فرهنگ علوم عقلی به نقل از اسفار و شفا). و رجوع به عضو حار شود.<br>- <span class=\"hlight\">هفت عضو</span> ؛ هفت اندام، یعنی سر و سینه و شکم و دو دست و دو پا و یا به عقیده ٔ برخی دو پهلو و دو پا و دو دست و سر. (از برهان ). و رجوع به هفت اندام شود <span class=\"hlight\">:</span> <br>گفتم که هفت عضو کدام است تنت را<br>گفتا که پهلویست و دوپا و دو دست و سر.<br> <font color=\"Red\">ناصرخسرو.</font><br>این نامه هفت عضو مرا هفت هیکل است <br>کایمن کند ز هول سباع و شر هوام .<br> <font color=\"Red\">خاقانی .</font><br>هفت اندام ماهی از سیم است <br>هفت عضو صدف ز سنگ چراست .<br> <font color=\"Red\">خاقانی .</font><br>خط بر جهان زدی وز خال سپید ظلم <br>بر هفت عضو ملک نشان چو گذاشتی .<br> <font color=\"Red\">خاقانی .</font><br>- <BR><font color=\"Blue\">◄</font> مجازاً، به معنی پرده ٔ چشم . (از آنندراج ) <span class=\"hlight\">:</span> <br>هفت عضو دیده را می بایدت شستن به آب <br>بعداز آنت طالب دیدار می باید شدن .<br> <font color=\"Red\">خواجه جمال الدین سلمان (از آنندراج ).</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">ماده به عضو ضعیف می ریزد</span>، نظیر: هر جا سنگ است به پای لنگ است . (امثال و حکم دهخدا).<br><BR><font color=\"Blue\">◄</font> یک فرد از جماعت، یا یک تن از جمعیتی . (از اقرب الموارد). کارمند یک اداره یا مؤسسه ٔ دولتی یا ملی . (فرهنگ فارسی معین ).<br></font></div>'),
(184109, 'عضو', '<span class=\"hlight\">عضو.</span> <font color=\"DarkGreen\"><b>[ ع َض ْوْ ]</font></b>(ع مص ) اندام اندام کردن . (منتهی الارب ). جزٔجزء کردن گوسفند را. (اقرب الموارد). قطعه قطعه کردن و جزٔجزء نمودن . (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> جدا ساختن . (منتهی الارب ). تفریق و جدا کردن . (از اقرب الموارد).<br></font></div>'),
(184110, 'عضوات', '<span class=\"hlight\">عضوات .</span> <font color=\"DarkGreen\"><b>[ ع ِ ض َ ]</font></b> (ع اِ) ج ِ عِضاهَة. (منتهی الارب ) (اقرب الموارد). رجوع به عضاهة شود. <BR><font color=\"Blue\">◄</font> ج ِ عِضة. (ناظم الاطباء). رجوع به عضة شود.<br></font></div>'),
(184111, 'عضوب', '<span class=\"hlight\">عضوب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) چرب زبان گردیدن . (از منتهی الارب ). عضب شدن . (از اقرب الموارد). و رجوع به عضب شود. <BR><font color=\"Blue\">◄</font> تیز گشتن شمشیر. (از منتهی الارب ).<br></font></div>'),
(184112, 'عضوبة', '<span class=\"hlight\">عضوبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع مص ) به معنی مصدر عُضوب است . (از منتهی الارب ) (از اقرب الموارد). بران شدن . (تاج المصادر بیهقی ). رجوع به عضوب شود.<br></font></div>'),
(184113, 'عضوبر', '<span class=\"hlight\">عضوبر.</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ ب َ ]</font></b> (ع ص ) ستبر کلان و تنومند. <BR><font color=\"Blue\">◄</font> (اِ) سنگ کلانی که سنگهای دیگر را بدان می شکنند. <BR><font color=\"Blue\">◄</font> گرگ نر. (ناظم الاطباء) (از اقرب الموارد).<br></font></div>'),
(184114, 'عضوض', '<span class=\"hlight\">عضوض .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) چیزی که گزیده شود و خوردنی، ازآن جمله است : ماعندنا عضوض . (از منتهی الارب ). آنچه گاز گرفته شود و خورده شود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گزنده . (منتهی الارب ). بسیارگزنده . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> فرس عضوض ؛ اسب گزنده . (منتهی الارب ) (دهار). از آن جمله است حدیث ابوبکر، و سترون بعدی ملکا عضوضا؛ یعنی پس از من پادشاهی خواهید دید که بر شما سخت می گیرد و شما را نحیف می کند. (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> کمان که زهش به قبضه چسبیده باشد. (منتهی الارب ). قوس که وتر آن به کبدش ملتصق باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زن تنگ شرم . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> بلا و زیرک . (منتهی الارب ). داهیة. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> زمانه ٔ سخت . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ملک ظلم و ستم رسیده . (منتهی الارب ). مُلک عضوض ؛ سرزمین که در آن سختی و جبر و ظلم باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مَلِک و شاهی که ستم و ظلم در او باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چاه دورتک تنگ سر، یا چاه بسیارآب . (منتهی الارب ). چاه تنگ که انتهای آن دور باشد و بوسیله ٔ ساقیة و دلو از آن آب کشند، و گویند چاه بسیارآب . (از اقرب الموارد). ج، عُضُض  و عِضاض . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(184115, 'عضوض', '<span class=\"hlight\">عضوض .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عِض ّ. (منتهی الارب ) (اقرب الموارد). رجوع به عِض شود.<br></font></div>'),
(184116, 'عضوم', '<span class=\"hlight\">عضوم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) شتر ماده ٔ درشت اندام . (منتهی الارب ). ناقه ٔ صلب و سخت . (از اقرب الموارد).<br></font></div>'),
(184117, 'عضون', '<span class=\"hlight\">عضون .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ عِضة در حال رفع. (منتهی الارب ) (از اقرب الموارد). رجوع به عضة و عضین شود. <BR><font color=\"Blue\">◄</font> ج ِ عِضاهة. (ناظم الاطباء). رجوع به عضاهة شود.<br></font></div>'),
(184118, 'عضوی', '<span class=\"hlight\">عضوی .</span> <font color=\"DarkGreen\"><b>[ ع ُ وی ی ]</font></b> (ص نسبی ) منسوب به عضو. (فرهنگ فارسی معین ). رجوع به عضو شود.<br></font></div>'),
(184119, 'عضوی', '<span class=\"hlight\">عضوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ وی ی ]</font></b> (ع ص نسبی ) منسوب به عضاهة. (از اقرب الموارد) (از منتهی الارب ). عِضاهی ّ.رجوع به عضاه و عضاهة شود. <BR><font color=\"Blue\">◄</font> آنکه عضاه چرد. (از اقرب الموارد). عِضهی . رجوع به عضهی شود.<br></font></div>'),
(184120, 'عضویة', '<span class=\"hlight\">عضویة.</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ وی ی َ ]</font></b> (ع ص نسبی ) تأنیث عضوی، منسوب به عِضاه . (از منتهی الارب ) (از اقرب الموارد). رجوع به عضاه و عضاهة و عضوی و عضاهی شود.<br></font></div>'),
(184121, 'عضویت', '<span class=\"hlight\">عضویت .</span> <font color=\"DarkGreen\"><b>[ ع ُ وی ی َ ]</font></b> (ع مص جعلی، اِمص ) عضو بودن . کارمند بودن . (فرهنگ فارسی معین ). رجوع به عضو شود.<br></font></div>'),
(184122, 'عضویت یافتن', '<span class=\"hlight\">عضویت یافتن .</span> <font color=\"DarkGreen\"><b>[ ع ُ وی ی َ ت َ ]</font></b> (مص مرکب ) کارمند اداره یا وزراتخانه یا بنگاه یا انجمن و یا حزبی شدن . عضو شدن . (فرهنگ فارسی معین ). و رجوع به عضویت شود.<br></font></div>'),
(184123, 'عضید', '<span class=\"hlight\">عضید.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) رسته ٔ خرمابن . (منتهی الارب ). طریقة از نخل . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خرمابن که دست به وی رسد. (منتهی الارب ). نخلی که دارای شاخه های در دسترس باشد، و هرگاه شاخه های آن از دسترس خارج شود آن را جبارة گویند. (از اقرب الموارد). ج، عِضدان . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه از درخت بریده باشند. (از اقرب الموارد).<br></font></div>'),
(184124, 'عضیرف', '<span class=\"hlight\">عضیرف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ض َ رِ ]</font></b> (ع اِ مصغر) مصغر عَضرَفوط، بحذف خامس . (از منتهی الارب ) (از اقرب الموارد). رجوع به عضرفوط شود.<br></font></div>'),
(184125, 'عضیریف', '<span class=\"hlight\">عضیریف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ض َ ]</font></b> (ع اِ مصغر) مصغر عَضرَفوط. (منتهی الارب ) (از اقرب الموارد). رجوع به عضر فوط شود.<br></font></div>'),
(184126, 'عضیض', '<span class=\"hlight\">عضیض .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) گزیدن . (از منتهی الارب ). به دندان گرفتن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> به زبان گرفتن . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> لازم گرفتن . (از منتهی الارب ). ملازم گشتن . (از اقرب الموارد). عَض ّ رجوع به عض شود.<br></font></div>'),
(184127, 'عضیض', '<span class=\"hlight\">عضیض .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) سخت گزیدن . (منتهی الارب ). گزیدگی سخت و شدید. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> قرین و همسال مرد. (منتهی الارب ). قرین . (اقرب الموارد).<br></font></div>'),
(184128, 'عضیل', '<span class=\"hlight\">عضیل .</span> <font color=\"DarkGreen\"><b>[ ع ِ ی َل ل ]</font></b> (ع ص ) ناکس دشوارخوی . (منتهی الارب ). لئیم و پست و تنگ خوی . (از اقرب الموارد).<br></font></div>'),
(184129, 'عضیلة', '<span class=\"hlight\">عضیلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع اِ) پی یا هر گوشت درشت . (منتهی الارب ). عضلة.ج، عَضائل . (اقرب الموارد). و رجوع به عَضلة شود.<br></font></div>'),
(184130, 'عضین', '<span class=\"hlight\">عضین .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ عِضة در حال نصب وجر. عضون . پاره ها. (ترجمان القرآن جرجانی ). پاره پاره . و یا سحر و کهانت <span class=\"hlight\">:</span> الذین جعلوا القرآن عضین . (قرآن <span class=\"hlight\" dir=\"rtl\">٩١/١٥</span>)؛ آنانکه ساختند قرآن را پاره پاره یعنی بخش کردند قرآن را به چندین وصف باز نمودند ازسحر و شعر و کهانت . (آنندراج ). رجوع به عِضة شود.<br>عضیوط<font color=\"DarkGreen\"><b>[ ع ِ ی َ ]</font></b> (ع ص ) آنکه وقت جماع حدث کند و گه اندازد، یا اینکه قبل از دخول انزال آیدش . (از منتهی الارب ). رجوع به عظیوط شود.<br></font></div>'),
(184131, 'عضیهة', '<span class=\"hlight\">عضیهة.</span> <font color=\"DarkGreen\"><b>[ ع َ هََ ]</font></b> (ع مص ) بریدن عضاه را. <BR><font color=\"Blue\">◄</font> دروغ گفتن . (از منتهی الارب ). کذب . (ازاقرب الموارد). <BR><font color=\"Blue\">◄</font> سخن چینی نمودن . (از منتهی الارب ). نمامی کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> افسون کردن . (از منتهی الارب ). سحر کردن . (از اقرب الموارد). عَضْه . عَضَه . عِضهة. رجوع به عضه شود.<br></font></div>'),
(184132, 'عضیهة', '<span class=\"hlight\">عضیهة.</span> <font color=\"DarkGreen\"><b>[ ع َ هََ ]</font></b> (ع اِ) دروغ وبهتان . (منتهی الارب ). افک و بهتان و کلام زشت، از آن جمله است که در استغاثه گویند یا للعضیهة. (از اقرب الموارد). ج، عَضائه . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) أرض عضیهة؛ زمین عضاه ناک . (از منتهی الارب ). زمین که عضاه بسیار داشته باشد. (از اقرب الموارد).<br></font></div>'),
(184133, 'عط', '<span class=\"hlight\">عط.</span> <font color=\"DarkGreen\"><b>[ ع َطط ]</font></b> (ع مص ) به درازا شکافتن جامه را بی جدا کردن، یا عام است . (از منتهی الارب ). بریدن به درازا. (تاج المصادر بیهقی ). به درازا شکافتن جامه را بدون از هم جدا کردن . (ناظم الاطباء): عطّ الثوب ؛ جامه را از درازا یا پهنا شکافتن بی آنکه از هم جدا شود. (از اقرب الموارد). و آیه ٔ <span class=\"hlight\" dir=\"rtl\">٢٨</span> سوره یوسف چنین نیز خوانده شده است : فلما رأی قمیصه عُطَّ من دُبر... (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> بر زمین افکندن کسی را. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چیره شدن بر کسی . (از منتهی الارب ). غلبه کردن برکسی در گفتار و در کردار، و گویند عَت ّ غلبه کردن در گفتار است و عط، غلبه کردن در کردار. (ازاقرب الموارد). <BR><font color=\"Blue\">◄</font> به تازیانه زدن . <BR><font color=\"Blue\">◄</font> بازداشتن . <BR><font color=\"Blue\">◄</font> گرم شدن روز. (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> گران شدن نرخ . (المصادر زوزنی ).<br></font></div>'),
(184134, 'عطا', '<span class=\"hlight\">عطا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِمص، اِ) عطاء. دهش . (منتهی الارب ). دادن بخشش را. (از اقرب الموارد). ضد منع. انعام . بذل . حِباء. حَبوة. داشن . دهش . دهشت . دهشته سَیب صفد. طلف . عطیت . عطیة. مَن ّ. ندی . نوال . هن . و رجوع به عطاء شود <span class=\"hlight\">:</span> <br>بشتر راد خوانمت پرگست <br>او چو تو کی بود به گاه عطا.<br> <font color=\"Red\">دقیقی .</font><br>ای شده مدهوش و بیهش پند حجت را بدار<br>کز عطای پند برتر نیست در عالم عطا.<br> <font color=\"Red\">ناصرخسرو.</font><br>محال باشد اگر با عطای عقل عظیم <br>چو این سگانت قصد عظام باید کرد.<br> <font color=\"Red\">ناصرخسرو.</font><br>خرم از جود او بهار عطا<br>روشن از عدل او جهان هنر.<br> <font color=\"Red\">مسعودسعد.</font><br>گر جهانی به یک عطا بدهد<br>از کف خویش نشمرد به سخا.<br> <font color=\"Red\">مسعودسعد.</font><br>عنان عطا مگیر. (کلیله و دمنه ).<br>کریمانه بخشی و منت نخواهی <br>عطای کریمان بود غیرممنون .<br> <font color=\"Red\">سوزنی .</font><br>گر همه کس ز منع بگریزد<br>منم آن کز عطا گریخته ام .<br> <font color=\"Red\">خاقانی .</font><br>این همه گفتم به رایگان نه بر آن طمع<br>کافسر زر یابم از عطای صفاهان .<br> <font color=\"Red\">خاقانی .</font><br>از عطایش بحر و کان در زلزله <br>سوی جودش قافله بر قافله .<br> <font color=\"Red\">مولوی .</font><br>هم عجم هم روم و هم ترک و عرب <br>مانده از جود و عطایش در عجب .<br> <font color=\"Red\">مولوی .</font><br>جوانمرد را دست عطا بسته بود. (گلستان ). <BR><font color=\"Blue\">◄</font> بخشودگی . عفو. بخشایش <span class=\"hlight\">:</span> <br>گر ما مقصریم تو دریای رحمتی <br>جرمی که می رود به امید عطای تست .<br> <font color=\"Red\">سعدی .</font><br>جادی ؛ خواهنده ٔ عطا. لهیة؛ عطای سترگ و بهتر. وهاص ؛ بسیارعطا. (از منتهی الارب ).<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عطایش را به لقایش بخشیدم </span>، نظیر: فوت الحاجة خیر من طلبها الی غیر أهلها. (امثال و حکم دهخدا) <span class=\"hlight\">:</span> درویشی را ضرورتی پیش آمد، کسی گفت فلان نعمتی دارد... دستش گرفت تا به منزل آن شخص درآورد. یکی را دید لب فروهشته ... برگشت ... گفت عطای او را به لقای او بخشیدم . (گلستان ).<br> <BR><font color=\"Blue\">◄</font> آنچه بخشیده شود. (منتهی الارب ) (از اقرب الموارد). جائزة. جدا. جدآء. داد. داشاد. صله . عارض . عارفة. عائدة. لُهوَة. معروف . نائل . نائلة. نولة. و رجوع به عطاء شود <span class=\"hlight\">:</span> <br>عطات باد چو باران دل موافق خوید<br>نهیبت آتش و جان مخالفان پده باد.<br> <font color=\"Red\">شهید بلخی .</font><br>بچاه سیصد باز اندرم من از غم او<br>عطای میر رسن ساختم ز سیصد باز.<br> <font color=\"Red\">شاکر بخاری .</font><br>خوی نیکو بزرگتر عطاههای خدایست . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٣٩</span>).<br>عقل عطایست ترا از خدای <br>بر تن تو واجب دین زین عطاست .<br> <font color=\"Red\">ناصرخسرو.</font><br>چون بروی تو عطاش با تو نیاید<br>پس تو چه بردی ازین عطای خدائی .<br> <font color=\"Red\">ناصرخسرو.</font><br>و آنها که زین عطا نه همی یابند<br>بینی که مانده اند بدین خواری .<br> <font color=\"Red\">ناصرخسرو.</font><br>هر چه از تو عطا به بنده آید<br>از بنده بتو ثناست پاداش .<br> <font color=\"Red\">سوزنی .</font><br>من که خاقانیم به منت شاه <br>پشت خم کرده ام ز بار عطا.<br> <font color=\"Red\">خاقانی .</font><br>نیاز عطا داشتم تا به اکنون <br>نیازم نماند از عطا می گریزم .<br><font color=\"Red\">خاقانی .</font><br>آن عطا کز ملوک یافته ام <br>عشر آن وقت اهتزاز فرست .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عطای بزرگان ایران زمین </span> <br>دو تا بارک اﷲ است یک آفرین <br>نظیر: از بارک اﷲ قبای کسی رنگین نشود. (امثال و حکم ).<br> <span class=\"hlight\">عطای بزرگان چو ابر بهار</span> <br>به جائی ببارد که ناید بکار.<br><font color=\"Red\">؟ (امثال و حکم دهخدا).</font><br>- <span class=\"hlight\">عطای روحانی </span> ؛ بخشش واقدار معجزه و خوارق عادت است که به توسط روح القدس اول بر مؤمنین مسیح افاضه شد. (قاموس کتاب مقدس ).<br>- <span class=\"hlight\">عطای کبری </span> ؛ کنایه از عمر طبیعی که یکصدوبیست سال باشد. (از برهان قاطع) (غیاث اللغات ) (آنندراج ).<br></font></div>'),
(184135, 'عطا', '<span class=\"hlight\">عطا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) تخلص ادیب السلطنه حسین سمیعی از ادبا و رجال دوره ٔ معاصر است . وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٩٣</span> هَ .ق . در رشت تولد یافت و دوران طفولیت را در کرمانشاه و تهران بسر برد و بعد از پدرش به مشاغل دولتی پرداخت و به وزارت کشور و وزارت خارجه منصوب شد و به وکالت مجلس شوری و سناتوری نیز رسید. و به سال <span class=\"hlight\" dir=\"rtl\">١٣٧٣</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">/</span> <span class=\"hlight\" dir=\"rtl\">١٣٢٢</span> هَ .ش . درگذشت . وی شاعر بود و دیوانی دارد و مدتی انجمن ادبی تهران تحت سرپرستی او اداره می شد. از تألیفات او رساله ٔ «جان کلام » و دیگر رساله ای است در دستور زبان فارسی . (از فرهنگ فارسی معین ).<br></font></div>'),
(184136, 'عطا', '<span class=\"hlight\">عطا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یزید لیثی . محدث . و رجوع به ابویزید (عطاء...) شود.<br></font></div>'),
(184137, 'عطا آباد', '<span class=\"hlight\">عطا آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است از دهستان سمیرم پائین، بخش حومه ٔ شهرستان شهرضا. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٨٤٥</span> تن . آب آنجا از قنات و محصول آن غلات، پنبه، انگور و خشکبار است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(184138, 'عطا حریة', '<span class=\"hlight\">عطا حریة.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام فرقه ای از فرق میان عیسی و محمد صلوات اﷲ علیهما. (یادداشت به خط مرحوم دهخدا).<br></font></div>'),
(184139, 'عطا خواستن', '<span class=\"hlight\">عطا خواستن .</span> <font color=\"DarkGreen\"><b>[ ع َخوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ت َ ]</font></b> (مص مرکب ) بخشش خواستن . طلب دهش و عطا کردن . اجتداء. استجازة. استجداء. استعطاء. استماحة. استمناح . استهناء. تعطی . جدی . مجاداة <span class=\"hlight\">:</span> <br>خوشی طلب کنی از خلق، ساده دل مردی <br>که از زکات ستانان زکات خواست عطا.<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(184140, 'عطا دادن', '<span class=\"hlight\">عطا دادن .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (مص مرکب ) بخشش . بخشیدن . بخشش دادن . اجداء، اشبار. اصفار. اعطاء. افراض . امتناح . انالة. اوس . تنویل . حباء. حبوة. رفد. زبد. شبر. صلة. فرض . مناولة. نحل . نصر. نفح . نوال . نول . وصل . هزر. هناء <span class=\"hlight\">:</span> <br>ز بس عطاکه دهد هر که زو عطا بستد<br>گمان بری که مر او را شریک و برخوار است .<br> <font color=\"Red\">فرخی .</font><br>آنچه در طلب آن بودم عطا داد. (تاریخ بیهقی ). ایزد... سبکتکین را... مسلمانی عطا داد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٩٣</span>). هر بنده که خدای ... او را خردی روشن عطا داد... بتواند دانست که نیکوکاری چیست . (تاریخ بیهقی ).<br>ایزد عطاش داد محمد را<br>نامش علی شناس و لقب کوثر.<br> <font color=\"Red\">ناصرخسرو.</font><br>ایزدش عطا داد به پیغمبر ازیراک <br>اویست حقیقت یکی از سبع مثانیش .<br> <font color=\"Red\">ناصرخسرو.</font><br>آنکه چنین داند دادن عطا<br>هیچ قیاسی نپذیرد سخاش .<br> <font color=\"Red\">ناصرخسرو.</font><br>عطا برسم در حد اعتدال و اندازه ٔ اقتصاد میده . (کلیله و دمنه ).<br>از عافیت مپرس که کس را نداده اند<br>در عاریت سرای جهان عافیت عطا.<br> <font color=\"Red\">خاقانی .</font><br>کرده بهنگام حال حله ٔ نه چرخ چاک <br>داده بوقت نوال نقد دو عالم عطا.<br> <font color=\"Red\">خاقانی .</font><br>در همه ملک فلک نان دو و خوشه یکی است <br>داده کف و کلک تو خوشه عطا نان به سلم .<br> <font color=\"Red\">خاقانی .</font><br>خداوندا تو ایمان و شهادت <br>عطا دادی به فضل خویش ما را.<br> <font color=\"Red\">سعدی .</font><br>سال نو فرخ و فرخنده شد از آنک <br>ملک العرش عطا داد ملک را پسری .<br> <font color=\"Red\">میرمعزی (از آنندراج ).</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عطا گرچه اندک دهد پادشاه </span> <br>به بسیاریش کرد باید نگاه .<br>نظیر: هر چه از دوست میرسد نیکوست و اسب پیش کشی را بدندانش نگاه نمی کنند و دوست مرا یاد کند یک هل پوچ . (امثال و حکم دهخدا).<br></font></div>'),
(184141, 'عطا کردن', '<span class=\"hlight\">عطا کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ دَ ]</font></b> (مص مرکب ) دادن و بخشیدن و انعام کردن . (ناظم الاطباء). اهدا کردن . ارزانی داشتن . اجداء. اشبار. اعطاء. انالة. جدو. عطاء. مَیح . معاطاة <span class=\"hlight\">:</span> <br>جان و دل منی و دل و جان دریغ نیست <br>گر من ترا که هم دل و جانی عطا کنم .<br> <font color=\"Red\">مسعودسعد.</font><br>بوسیم عطا کردی زان کرده پشیمانی <br>دانی که خطا کردی دیگر نکنی دانم .<br> <font color=\"Red\">خاقانی .</font><br>در عدم کی بود ما را خود طلب <br>بی سبب کردی عطاهای عجب .<br> <font color=\"Red\">مولوی .</font><br>گفت از باغ خدا بنده ٔ خدا<br>گر خورد خرما که حق کردش عطا.<br> <font color=\"Red\">مولوی .</font><br>اًسهاب ؛ بسیار عطا کردن . مکاهنة؛ عطا کردن بی پاداش .<br></font></div>'),
(184142, 'عطا یافتن', '<span class=\"hlight\">عطا یافتن .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ]</font></b> (مص مرکب ) بخشش یافتن . اکتداش . (از منتهی الارب ).<br></font></div>'),
(184143, 'عطاء', '<span class=\"hlight\">عطاء.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِمص، اِ) عطا. دهش . (منتهی الارب ). دادن بخشش را. (از اقرب الموارد). رجوع به عطا شود. <BR><font color=\"Blue\">◄</font> آنچه بخشیده شود. (منتهی الارب ).آنچه داده شود. (از اقرب الموارد). ج، أعطیة و جج، أعطیات . (منتهی الارب ) (اقرب الموارد). اصل آن واوی است یعنی «عطاو» و عرب واو و یاء پس از الف را به همزه تبدیل کنند، و هر گاه با تاء وحدت بیاید برخی آن را به صورت عطاءة خوانند و برخی بنا بر اصل، عطاوة گویند و تثنیه ٔ آن را نیز عطأان و عطاوان خوانده اند و مصغر آن عُطَی ّ شود به حذف لام الفعل . (از منتهی الارب ) (از اقرب الموارد). رجوع به عطا شود <span class=\"hlight\">:</span> وهؤلاء من عطاء ربک و ماکان عطاء ربک محظورا. (قرآن <span class=\"hlight\" dir=\"rtl\">٢٠/١٧</span>)؛ و اینها از بخشش پروردگار تو است و بخشش پروردگارت بازداشته نیست . و أما الذین سعدوا ففی الجنةخالدین فیها... عطاء غیر مجذوذ. (قرآن <span class=\"hlight\" dir=\"rtl\">١٠٨/١١</span>)؛ و کسانی که نیک بخت شدند پس در بهشت هستند جاودانه ... بخششی است غیر منقطع، جزاء من ربک عطاء حسابا. (قرآن <span class=\"hlight\" dir=\"rtl\">٣٦/٧٨</span>)؛ پاداشی است از پروردگارت و بخششی است کافی . هذا عطاؤنا فامنن أو أمسک بغیر حساب . (قرآن <span class=\"hlight\" dir=\"rtl\">٣٨/٣٨</span>)؛ این است بخشش ما پس عطا کن یا بدون شمار منع کن .<br>- <span class=\"hlight\">ام العطاء</span> ؛ دادنی . (دهار).<br><BR><font color=\"Blue\">◄</font> در اصطلاح فقهی، با معنی رزق نزدیکی دارد جز آنکه فقها بین این دو کلمه فرقی نهاده می گویند آنچه از بیت المال برای لشکریان بیرون آید در هر ماه مثلاً، آن رزق باشد و آنچه به نام لشکریان یک نوبت یا دو نوبت در سال صادر شود آن را عطاء نامند. و برخی گویند عطاء چیزی است که در هر سال یا در هرماه صادر شود، و رزق مزد روزانه است . و نیز گویند عطاء فریضه ٔ جنگجویان باشد و رزق مقرری فقراء مسلمانان است در صورتی که در زمره ٔ جنگجویان داخل نباشند. ونیز گفته اند رزق بخشش جاری دنیوی یا دینی است و یا نصیب و بهره ای است که برای کسی تعیین شده باشد و مخصوص است بدانچه اندرون بدن انسان از آن استفاده می کندو بدان تغذیه می شود و گویند عطاء فریضه ای است که برای مردم از بیت المال می رسد نه به عنوان آنکه نیازمندی مردم از آن تأمین گردد، اما رزق آن چیزی است که برای مردم به عنوان تأمین احتیاجات و معیشت آنان تعیین شود به قدری که بدان احتیاج دارند، و کفایة عبارت است از شهریه یا مزد روزانه به میزانی که هر فردی را بسنده و کافی باشد. و عطیه را با عطاء مرادف دانسته اند و گفته اند عطیه فریضه ای است که برای جنگجویان تعیین می شود و رزق برای فقراء مسلمانان است . پس اگر رزق و عطیه با هم برای کسی معین گردید، دیه را از عطیه خواهند گرفت نه از رزق . (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> در اصطلاح عرفان، آنچه از ناحیه ٔ حق برعبد فائض شود. و آن یا ارزاق عباد است یا امور دیگرمادی و معنوی و قریب المعنی با رزق . (از فرهنگ مصطلحات عرفاء).<br></font></div>'),
(184144, 'عطابة', '<span class=\"hlight\">عطابة.</span> <font color=\"DarkGreen\"><b>[ ع َ طْ طا ب َ ]</font></b> (اِخ ) نام مادر جعفر برمکی بود. (از حبیب السیر چ طهران ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨١</span>).<br></font></div>'),
(184145, 'عطابخش', '<span class=\"hlight\">عطابخش .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (نف مرکب ) بخشنده ٔ عطا. جوانمرد. سخی . گشاده دست . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>مردیست سخاپیشه و مردیست عطابخش <br>با خلق نکوکار بکردار و به گفتار.<br> <font color=\"Red\">فرخی .</font><br>ای عطابخش پذیرنده و خواهنده سپاس <br>رأی تو خوبی و آئین تو فضل و احسان .<br> <font color=\"Red\">فرخی .</font><br>من ثناگوی بزرگانم و مداح ملوک <br>خاصه مدحتگر آن راد عطابخش کریم .<br> <font color=\"Red\">فرخی .</font><br>چو خط دست عطابخش تو به زیبایی <br>کدام جعد مسلسل کدام زلف وغیش .<br> <font color=\"Red\">اسدی .</font><br>ثنانیوش و عطابخش باش از پی آنک <br>ثنانیوش و عطابخش راست طول بقا.<br> <font color=\"Red\">سوزنی .</font><br>پیشت آرم ذات یزدان را شفیع<br>کش عطابخش و توانا دیده ام .<br> <font color=\"Red\">خاقانی .</font><br>عدل او چون فضل و فضلش چون ربیع<br>این عطابخش آن خطابخشای باد.<br> <font color=\"Red\">خاقانی .</font><br>عمر خسرو طلب ار نفع جهان می طلبی <br>که وجودیست عطابخش و کریم ونفاع .<br> <font color=\"Red\">حافظ.</font><br>پیر دردی کش ما گرچه ندارد زرو زور<br>خوش عطابخش و خطاپوش خدائی دارد.<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(184146, 'عطابل', '<span class=\"hlight\">عطابل .</span> <font color=\"DarkGreen\"><b>[ ع َ ب ِ ]</font></b> (ع ص، اِ) ج ِ عُطْبُل . (منتهی الارب ). (اقرب الموارد). رجوع به عطبل شود.<br></font></div>'),
(184147, 'عطابیل', '<span class=\"hlight\">عطابیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) ج ِ عُطْبُل . (منتهی الارب ) (اقرب الموارد). رجوع به عطبل شود.<br></font></div>'),
(184148, 'عطاده', '<span class=\"hlight\">عطاده .</span> <font color=\"DarkGreen\"><b>[ ع َ دِه ْ ]</font></b> (نف مرکب ) عطادهنده . بخشنده ٔ عطا <span class=\"hlight\">:</span> <br>از عطای کف عطاده تو<br>یک جهان شاکرند و تو مشکور.<br> <font color=\"Red\">سوزنی .</font><br>بجای کف سخاگسترو عطاده او<br>سحاب سفله بود کان بخیل و بحر لئیم .<br> <font color=\"Red\">سوزنی .</font><br>پیش کف عطاده تو محیط<br>همچو پیش محیط جوی رود.<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(184149, 'عطادهنده', '<span class=\"hlight\">عطادهنده .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ هََ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف مرکب ) بخشنده . دهش کننده . باذل . معطی . مناح . نائل .<br></font></div>'),
(184150, 'عطادهی', '<span class=\"hlight\">عطادهی .</span> <font color=\"DarkGreen\"><b>[ ع َ دِ ]</font></b> (حامص مرکب ) عطا دادن . بخشندگی <span class=\"hlight\">:</span> <br>در هیچ روزگار نباشد چو تو کریم <br>کاندر عطادهی نبرد هیچ روزگار.<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(184151, 'عطار', '<span class=\"hlight\">عطار.</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) حسن بن احمدبن حسین بن سهل عطار، مکنی به ابوالعلاء. شیخ همدان و امام عراقیان در قرأات در قرن ششم هجری . رجوع به ابوالعلاء (حسن بن ...) در همین لغت نامه و مأخذ ذیل شود: الاعلام زرکلی . طبقات الحفاظ سیوطی . غایة النهایة. التبیان <br></font></div>'),
(184152, 'عطار', '<span class=\"hlight\">عطار.</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (ع ص ) خوشبوی فروش و صاحب عطر. (منتهی الارب ) (آنندراج ). آنکه بوی خوش فروشد. (دهار). فروشنده ٔ عطر. (از اقرب الموارد). بوی خوش فروش . (مهذب الاسماء). بوی فروش . صیدلانی . صیقبانی : عطارها، سازندگان و فروشندگان عطریات و دهنیات معطره می باشند. (از قاموس کتاب مقدس ) <span class=\"hlight\">:</span> <br>از بوی و خصال تو ز خاک و گل میمند<br>بی رنج همه عطر خوش آمیزد عطار.<br> <font color=\"Red\">فرخی .</font><br>ابرشد نقاش چین و باد شد عطار روم <br>باغ شد ایوان نور و راغ شد دریای گنگ .<br> <font color=\"Red\">منوچهری .</font><br>گویی به مثل بیضه ٔ کافور ریاحی <br>بر بیرم حمرا بپراکنده ست عطار.<br> <font color=\"Red\">منوچهری .</font><br>چه سود چون همی ز تو گند آید<br>گر تو به نام احمد عطاری .<br> <font color=\"Red\">ناصرخسرو.</font><br>صبا را ندانی ز عطار تبت <br>زمین را ندانی ز دیبای ششتر.<br> <font color=\"Red\">ناصرخسرو.</font><br>نه غواص گوهر نه عطار عنبر<br>به نزدیک نرگس چه مقدار دارد.<br> <font color=\"Red\">ناصرخسرو.</font><br>و نسیم آن گرد از کلبه ٔ عطار بر آرد. (کلیله و دمنه ).<br>پارسا را چه لذت از عشرت <br>خنفسا را چه نسبت از عطار.<br> <font color=\"Red\">خاقانی .</font><br>خوش عطاری است باد شبگیر<br>تا زلف تو مشکسای دارد.<br> <font color=\"Red\">خاقانی .</font><br>صدف بود گفتی مگر ماه چرخ <br>درو غالیه سوده عطار کرخ .<br> <font color=\"Red\">نظامی .</font><br>عقل و طبیعت که ترا یار شد<br>قصه ٔ آهنگر و عطار شد.<br> <font color=\"Red\">نظامی .</font><br>گرفتم خود که عطار وجودی <br>تو نیز آخر بسوزی گرچه عودی .<br> <font color=\"Red\">نظامی .</font><br>برون آمد ز دکان مرد عطار<br>گلاب و عود پیش آورد بسیار.<br> <font color=\"Red\">عطار.</font><br>باد بوی سمن آورد و گل و سنبل و بید<br>دردکان به چه رونق بگشاید عطار.<br> <font color=\"Red\">سعدی .</font><br>آمد گه آن که بوی گلزار<br>منسوخ کند گلاب عطار.<br> <font color=\"Red\">سعدی .</font><br>باد خاکی ز مقام تو بیاورد و ببرد<br>آب هر طیب که در کلبه ٔ عطاری هست .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">طبل عطار و طبله ٔ عطار</span> ؛ صندوقچه ٔ عطرفروشان . قوطی و جعبه ٔ عطار که در آن بوی خوش نگاه دارد <span class=\"hlight\">:</span> <br>گفت بر پرنیان ریشیده <br>طبل عطار شد پریشیده .<br> <font color=\"Red\">عنصری .</font><br>به کلبه ٔ چمن از رنگ و بوی باز کنند<br>هزارطبله ٔ عطار و تخت بازرگان .<br> <font color=\"Red\">سعدی .</font><br>دانا چو طبله ٔ عطار است خاموش و هنرنمای . (گلستان ).<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">مشک آن است که خود ببوید نه آنکه عطار بگوید</span> . (گلستان ).<br> <span class=\"hlight\">هنر نمودن اگر نیز هست لایق نیست </span> <br>که خود عبیر بگوید چه حاجت عطار.<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> بسیار عطرزننده . آنکه بوی خوش بسیار بکار برده باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> در محاوره ٔ مردم، دوافروش، و این خالی از کراهیت نیست . (غیاث اللغات ) (آنندراج ). دوافروش . داروفروش . پیلوا. بیلوا. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> در این زمان، عطار مفردات فروشد و قند و چای و ابازیر. (یادداشت مرحوم دهخدا).کسی که قند و شکر و چای وادویه و غیره فروشد. (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> (اِخ ) نام اسب سالم بن رابضه است . (از منتهی الارب ).<br></font></div>'),
(184153, 'عطار', '<span class=\"hlight\">عطار.</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) (ابوحمزه ٔ...) تابعی است . و رجوع به ابوحمزه ٔ عطار در همین لغت نامه و اللباب فی تهذیب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٤١</span> شود.<br></font></div>'),
(184154, 'عطار', '<span class=\"hlight\">عطار.</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) لقب عبدالرحمان بن احمدبن محمد، از فاضلان قرن ششم هجری است . رجوع به عبدالرحمان (ابن احمد...) شود.<br></font></div>'),
(184155, 'عطار', '<span class=\"hlight\">عطار.</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) (علی ...) ابن ابراهیم بن داودبن سلمان دمشقی . محدث و فقیه قرن هشتم هجری . رجوع به علی عطار شود.<br></font></div>'),
(184156, 'عطار', '<span class=\"hlight\">عطار.</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) احمدبن عثمان بن علی جمال عطار احمدی، مکنی به ابوالخیر. محدث و عالم به رجال . اصل او از هند است و به سال <span class=\"hlight\" dir=\"rtl\">١٢٧٧</span> هَ . ق . در مکه ٔ مکرمه متولد شد و در حدود سال <span class=\"hlight\" dir=\"rtl\">١٣٣٥</span> هَ .ق . درگذشت . او راست : در السحابة فی صحة سماع الحسن البصری من جماعة من الصحابة. و حصول المنی باصول الالقاب والکنی . و اتحاف الاخوان . (از اعلام زرکلی به نقل از فهرس الفهارس ).<br></font></div>'),
(184157, 'عطار', '<span class=\"hlight\">عطار.</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ )احمدبن محمدبن علی حسنی بغدادی عطار. از فقیهان امامیه ٔ بغداد بود سپس به نجف اشرف منتقل شد و به سال <span class=\"hlight\" dir=\"rtl\">١٢١٥</span> هَ . ق . درگذشت . او راست : التحقیق، در اصول فقه، در دو مجلد. ریاض الجنان فی اعمال شهر رمضان . دیوان شعر، در مدح ائمه . الرائق که برگزیده ای است از اشعار عرب . (از الاعلام زرکلی به نقل از أحسن الودیعة).<br></font></div>'),
(184158, 'عطار', '<span class=\"hlight\">عطار.</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) اسماعیل بن عمربن نعمة، مکنی به ابوطاهر و مشهور به ابن شیب عطار. از ادیبان مصر متولد به سال <span class=\"hlight\" dir=\"rtl\">٥٥١</span> هَ. ق . وی در شناخت عقاقیر دست داشت تألیفات ادبی نیز داشت که از آن جمله است کتاب مائة جاریة و مائة غلام . عطار به سال <span class=\"hlight\" dir=\"rtl\">٦٠٦</span> هَ . ق . در قاهره درگذشت . (از الاعلام زرکلی به نقل از المقصد الارشد و شذرات الذهب ).<br></font></div>'),
(184159, 'عطار', '<span class=\"hlight\">عطار.</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) حسن بن محمدبن محمود عطار. از دانشمندان مصر در قرن <span class=\"hlight\" dir=\"rtl\">١٣</span> هجری . وی به سال <span class=\"hlight\" dir=\"rtl\">١١٩٠</span> هَ . ق . در قاهره متولد شد ومدتی در آلبانی سکونت گزید سپس به مصر بازگشت و نوشتن روزنامه ٔ «الوقائع المصریة» را به عهده گرفت سپس به سال <span class=\"hlight\" dir=\"rtl\">١٢٤٦</span> هَ . ق . عهده دار مشیخه ٔ ازهر شد. و در سال <span class=\"hlight\" dir=\"rtl\">١٢٥٠</span> هَ . ق . درگذشت . او راست . رساله ٔ کیفیة العمل بالاسطرلاب و الربعین المقنطر و المجیب و البسائط. وکتاب الانشاء و المراسلات . و دیوان شعر. (از الاعلام زرکلی به نقل از تاریخ الازهر و الخزانة التیموریة و خطط مبارک و تاریخ آداب اللغة العربیه ٔ جرجی زیدان ).<br></font></div>'),
(184160, 'عطار', '<span class=\"hlight\">عطار.</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) لقب عبدالجباربن علأبن عبدالجبار عطار مکی، مکنی به ابوبکر است . محدث و اصل او از بصره بود از ابن عیینه روایت دارد. عطار به سال <span class=\"hlight\" dir=\"rtl\">٢٤٨</span> هَ . ق . درگذشت . (از اللباب فی تهذیب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(184161, 'عطار', '<span class=\"hlight\">عطار.</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) لقب عمربن طه بن شهاب احمد عطار، از فقیهان شافعی دمشق است . وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٤٢</span> هَ . ق . در دمشق متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">١٣٠٨</span> هَ .ق . درگذشت . او راست : أین الاسلام . و الفتح المبین فی رد الاعتراض علی محیی الدین . و تحقیق معنی الوجود. و شرح فصوص الحکم . و شرح الایساغوجی فی المنطق . و شرح الاظهار. (از الاعلام زرکلی از منتخبات التواریخ لدمشق ).<br></font></div>'),
(184162, 'عطار', '<span class=\"hlight\">عطار.</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) لقب فریدالدین ابوحامد محمدبن ابی بکر ابراهیم بن اسحاق عطار نیشابوری، شاعر و عارف مشهور ایرانی در قرن ششم و آغاز قرن هفتم هجری است . وی به سال <span class=\"hlight\" dir=\"rtl\">٥٤٠</span> هَ . ق . متولد شد. و گویند پدر او عطار (بوی فروش ) و داروفروش بود و فریدالدین کار او را دنبال کرد و در داروخانه ٔ خود سرگرم طبابت بود. وی را در همان اوان انقلابی باطنی دست داد و چون سرمایه ای بزرگ از ادب و شعر اندوخته بود اندیشه های عرفانی خود را به نظم درآورد. عطار را مرید مجدالدین بغدادی و رکن الدین اسحاق و قطب حیدر دانسته اند. به هرحال عطار قسمتی از عمر خود را بر رسم سالکان طریقت در سفر گذراند و از مکه تا ماوراءالنهر بسیاری از مشایخ را زیارت کرد و در همین سفرها و ملاقاتها بود که به خدمت مجدالدین بغدادی نیز رسید و سرانجام به سال <span class=\"hlight\" dir=\"rtl\">٦١٨</span> هَ . ق . درگذشت . وی آثار زیاد بوجود آورده که از آن جمله است : تذکرةاولالیا، به نثر. دیوان اشعار. منطق الطیر. اسرارنامه . الهی نامه . مصیبت نامه . خسرونامه . گفته اند وی به دست مغولی کافر کشته شد. مقبره ٔ عطار در نزدیکی شهر نیشابور باقی است . سخن عطار باسوز و شوق و عشق همراه است و برای بیان معانی عالی عرفانی سخنان بی پیرایه و روان را برگزیده که در عین حال به فصاحت و بلاغت و انسجام متصف است . (فرهنگ فارسی معین ). و رجوع به مآخذ ذیل شود: تاریخ ادبیات در ایران دکتر صفا ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٥٨</span>. نفحات الانس جامی . تذکرة الشعراء دولتشاه سمرقندی . لباب الالباب . ریاض العارفین .مجمعالفصحاء. کشف الظنون . تاریخ گزیده ٔ حمداﷲ مستوفی . مجالس المؤمنین قاضی نوراﷲ. جستجو در احوال و آثار فریدالدین عطار به قلم سعید نفیسی . غالب شاعران بزرگ پس از عطار، او را به بزرگی یاد کرده و مقام عرفانی او را ستوده اند. ابیات ذیل نمونه ای از آنهاست :<br>من آن مولای رومی ام که از نطقم شکر ریزد<br>ولیکن در سخن گفتن غلام شیخ عطارم .<br> <font color=\"Red\">مولوی .</font><br>آنچه گفتم از حقیقت ای عزیز<br>آن شنیدستم هم از عطار نیز.<br> <font color=\"Red\">مولوی .</font><br>هفت شهر عشق را عطار گشت <br>ما هنوز اندر خم یک کوچه ایم .<br> <font color=\"Red\">مولوی .</font><br>عطار شیخ ما و سنائیست پیشرو<br>ما از پس سنائی و عطار آمدیم .<br> <font color=\"Red\">مولوی .</font><br>مرا از شاعری خود عار ناید<br>که در صد قرن یک عطار ناید.<br> <font color=\"Red\">شیخ شبستری .</font><br>روز خاور گو سیه شو کآفتاب خاوری <br>رفت تا صبح قیامت خاوران عطار شد؟<br> <font color=\"Red\">سلمان ساوجی .</font><br>یار چون بشنید گفتارت کمال <br>گفت حق گوئی تو چون عطار ما.<br> <font color=\"Red\">کمال خجندی .</font><br>بوی مشک گفته ٔ عطار عالم را گرفت <br>خواجه مزکوم است از آن منکر شود عطار را.<br> <font color=\"Red\">عبدالرحمان جامی .</font><br>گمان کج مبر بشنو ز عطار<br>هر آن کو در خدا گم شد خدا نیست .<br> <font color=\"Red\">نعمةاﷲ ولی .</font><br>از صورت و نقش بگذر اسرار بجو<br>میراث رسول و نقد اخیار بجو<br>در قصه و معرکه چه معجون گیری <br>رو داروی درد را ز عطار بجو.<br> <font color=\"Red\">خواجه ابوالوفای خوارزمی .</font><br>گر چو عطار از گلستان نشابورم ولیک <br>خار صحرای نشابورم من و عطارگل .<br> <font color=\"Red\">کاتبی نشابوری .</font><br>خاموشی به ز درس و تکرار مرا<br>تجرید به از خلوت و ادوار مرا.<br>کشاف و هدایه هر که خواهد او را<br>یک بیت ز گفته های عطار مرا.<br> <font color=\"Red\">کمال الدین حسین خوارزمی .</font><br>از دم عطار گشتم زنده دل <br>پاک کردم همچو گل قالب ز گل .<br> <font color=\"Red\">امیرحسینی .</font><br>آن را که به درگاه خدا یار بود<br>ایمن ز عذاب دوزخ و نار بود<br>تاج سر سروران عالم گردد<br>گر خاک ره حضرت عطار بود.<br> <font color=\"Red\">سیدمحمدنوربخش .</font><br>از این شربت که قاسم کرد ترکیب <br>مگر در کلبه ٔ عطار باشد.<br> <font color=\"Red\">قاسم انوار.</font><br>آن کتابی که پر ز اسرار است <br>منطق الطیر شیخ عطار است .<br><font color=\"Red\">نسیمی .</font><br></font></div>'),
(184163, 'عطار', '<span class=\"hlight\">عطار.</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) لقب محمدبن حسن بن مقسم بن یعقوب عطار، از قراء مدینة السلام در قرن چهارم هجری است . رجوع به ابن مقسم در همین لغت نامه و مآخذ ذیل شود: الاعلام زرکلی . بغیةالوعاة. غایةالنهایة. تاریخ بغداد. ارشادالاریب .<br></font></div>'),
(184164, 'عطار', '<span class=\"hlight\">عطار.</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) لقب محمدبن حسین عطار حلبی دمشقی، ریاضیدان قرن سیزدهم هجری است . وی به سال <span class=\"hlight\" dir=\"rtl\">١١٧٧</span> هَ . ق . در دمشق متولد شد. سپس به ازهر رفت و به سال <span class=\"hlight\" dir=\"rtl\">١٢٤٣</span> هَ . ق . به مرض طاعون در دمشق درگذشت . او را لقب «ممرس » بود و در علوم ستاره شناسی و حساب و ریاضیات دست داشت . از جمله ٔ آثار اوست : رساله ٔ حساب المیاه . رساله ٔ الرمی بالقنبرة و الطوب .رساله ٔ فن القبان . (ازالاعلام زرکلی از روض البشر).<br></font></div>'),
(184165, 'عطارا', '<span class=\"hlight\">عطارا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) به سریانی کراث است . (مخزن الادویه ). و رجوع به کراث شود.<br></font></div>'),
(184166, 'عطاران', '<span class=\"hlight\">عطاران .</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) (دروازه ٔ...) یکی از هفت دروازه ٔ شهر بخارا بود. و چون قتیبةبن مسلم بدانجا راه یافت، از دروازه ٔ عطاران تا دروازه ٔ نون را به قبایل ربیعه و مضر و باقی مردم یمن داد. رجوع به شرح آثار و احوال رودکی، سعید نفیسی ص <span class=\"hlight\" dir=\"rtl\">٨٢</span>، <span class=\"hlight\" dir=\"rtl\">٨٤</span> و <span class=\"hlight\" dir=\"rtl\">٢٨٦</span> شود.<br></font></div>'),
(184167, 'عطارباشی', '<span class=\"hlight\">عطارباشی .</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِ مرکب ) داروفروش <span class=\"hlight\">:</span> و عطارباشی سرکار خاصه ٔ شریفه ... به معظم الیه <font color=\"DarkGreen\"><b>[ حکیم باشی ]</font></b> متعلق است . (تذکرةالملوک چ دبیرسیاقی ص <span class=\"hlight\" dir=\"rtl\">٢٠</span>).<br></font></div>'),
(184168, 'عطارخانه', '<span class=\"hlight\">عطارخانه .</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) محلی که عطار در آن به کار پردازد. داروخانه، و این از متداولات عهد صفویه است . (از فرهنگ فارسی معین ). و رجوع به عطار شود <span class=\"hlight\">:</span> صاحب جمع عطارخانه مبلغ ده تومان مواجب و از ابتیاع و انفاذ به دستور سایر بیوتات رسوم داشته . (تذکرةالملوک چ دبیرسیاقی ص <span class=\"hlight\" dir=\"rtl\">٧٢</span>). <BR><font color=\"Blue\">◄</font> اجتماع عطاران . صنف عطار.<br></font></div>'),
(184169, 'عطارد', '<span class=\"hlight\">عطارد.</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (اِخ ) ابن حاجب بن زراره ٔ تمیمی . وی خطیب و از بزرگان بنی تمیم بود. گویند در عهد جاهلیت او بنزد کسری رفت و کمان پدر خویش را از وی خواست . کسری آن کمان را به وی باز پس داد و حله ای از دیبا بر وی پوشاند. پس از ظهور اسلام به سال نهم هجرت به پیغمبر اسلام (ص )گروید و خطیب وی گشت و پیغمبر (ص ) او را بر صدقات بنی تمیم گماشت . پس از وفات پیامبر عطارد مرتد شد و به سجاح گروید و پس از اندکی دیگر بار اسلام آورد و در حدود سال <span class=\"hlight\" dir=\"rtl\">٢٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی به نقل از الاصابة و البیان و التبیین و الاَّمدی ). و رجوع به منتهی الارب شود.<br></font></div>'),
(184170, 'عطارد', '<span class=\"hlight\">عطارد.</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (اِخ ) ابن بکر. تابعی است . رجوع به ابوالعشراء شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(184171, 'عطارد', '<span class=\"hlight\">عطارد.</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (اِخ ) ابن قُرّان از بنی صدی بن مالک . شاعری نیکوپرداز و اندک شعر بود و از صعالیک بشمار می رفت . وی مدتی در نجران و حجر زندانی بود و اشعاری در این مورد دارد. عطارد معاصر جریر بود و آن دو یکدیگر را هجو کرده اند. وی در حدود سال <span class=\"hlight\" dir=\"rtl\">١٠٠</span> هَ . ق . درگذشته است . (از الاعلام زرکلی از المرزبانی و سمط اللالی ).<br></font></div>'),
(184172, 'عطارد', '<span class=\"hlight\">عطارد.</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (ع اِ) نام دوائی که آن را سنبل رومی گویند. (غیاث اللغات ). و آن بیخی باشد به رنگ شبیه مامیران و به شکل مانند عصارون . (آنندراج ). سنبل رومی است، و آن بیخی باشد به رنگ شبیه مامیران و به شکل مانند اسارون . (برهان قاطع). سنبل رومی . (مخزن الادویة) (تذکره ٔ ضریر انطاکی ). نوعی سنبل الطیب . سنبل اقلیطی . <BR><font color=\"Blue\">◄</font> عطری که از سنبل اقلیطی به دست آید. <BR><font color=\"Blue\">◄</font> جوشانده ٔ سنبل اقلیطی که در طب قدیم مصرف می شد. (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> به اصطلاح کیمیاگران، جمست است که یکی از فلزات باشد. (از غیاث اللغات ) (آنندراج ). به لغت اکسیریان، روح توتیا است و بعضی زیبق را به این اسم می خوانند. (تحفه ٔ حکیم مؤمن ). در اصطلاح کیمیاگران کنایه از خارصینی است . (از مفاتیح العلوم خوارزمی ). به اصطلاح اهل صنعت زیبق است به اعتبار مناسبت طبیعت آن به طبیعت عطارد، که با هر کوکبی به مناسبت آن تأثیر می نماید و همچنین زیبق با هر فلزی و دوائی به مناسبت آن تأثیر می کند. (مخزن الادویه ). سیماب . جیوه . (یادداشت مرحوم دهخدا). جمست . (فرهنگ فارسی معین ). رجوع به جمست شود.<br></font></div>'),
(184173, 'عطارد', '<span class=\"hlight\">عطارد.</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (اِخ ) ستاره ای است از ستاره های خنس در آسمان دوم . (منتهی الارب ). ستاره ای است از خنس در آسمان ششم . و آن هم به صورت منصرف و هم غیرمنصرف بکار رفته است . (از اقرب الموارد). ستاره ای معروف که بر فلک دوم تابد و آن را دبیر فلک گویند. علم و عقل بدو تعلق دارد. و شرف او در سنبله و وبال او در قوس . (غیاث اللغات ) (آنندراج ). نام ستاره ای است از سیارات که اورا دبیر فلک و تیر فلک گویند و جای او در دوم آسمان است . (دهار). ستاره ای است از کواکب سبعه ٔ سیاره، معنای آن «نافذ در امور» می باشد، لذا دبیر و کاتب را بدان نامیده اند. و آن در فلک دوم است پس از فلک قمر. و دور قرص آن <span class=\"hlight\" dir=\"rtl\">٧٢٠</span> میل است . عطارد یک بیست ودوم زمین است . (از صبح الاعشی ). اولین سیاره ٔ شمسی است و بیست بار از زمین کوچکتر است و دوری آن از خورشید <span class=\"hlight\" dir=\"rtl\">٨٥</span> میلیون کیلومتر و مدت مدار آن گرد خورشید <span class=\"hlight\" dir=\"rtl\">٨٨</span> شبانه روز و مدت دوره ٔ محوری آن <span class=\"hlight\" dir=\"rtl\">٢٤</span> ساعت و پنج دقیقه است و آن از سیارات داخله است و خانه و بیت او دو برج جوزا و سنبله است و شرف آن در پانزدهمین درجه ٔ سنبله است . آن را ذوجسدین نیز نامند و بلاد روم بدان منسوب است و در علم احکام نجوم، رب روز چهارشنبه است . (یادداشت به خط مرحوم دهخدا). خدای موهومی بت پرستان قدیم و قاصد ملأ اعلی و خدائی که همواره معاون علم و تجارت بود و یونانیان وی را هرمیس، یعنی مفسر اراده ٔ خدایان می نامیدند. (از قاموس کتاب مقدس ). عطارد به موجب افسانه ٔیونانی پیامبر یا قاصد خدایان و حامی قاصدان و بازرگانان بوده است . تیر. زادوس . زادوش . زاودش . (ناظم الاطباء). کوچکترین سیاره ٔ منظومه شمسی است . قطر آن <span class=\"hlight\" dir=\"rtl\">٣٠٣٠</span> میل و یک برابر ونیم ماه می باشد. عین عملی را که ماه نسبت به زمین انجام می دهد عطارد با خورشید می کند.دوری آن از خورشید <span class=\"hlight\" dir=\"rtl\">٣٦</span> میلیون میل است . از آنجا که این ستاره بسیار کوچک است در حرکت انتقالیش به دور خورشید فقط یک بار به دور خود می چرخد. مدت حرکت انتقالی آن <span class=\"hlight\" dir=\"rtl\">٨٨</span> روز است . همیشه یک طرف ستاره ٔ مذکور به طرف خورشید است و یک سال و یک روز آن با هم مساوی هستند.سمتی که به طرف خورشید است بسیار داغ است بطوری که سرب و قلع آن به صورت مذاب می باشد. سمت دیگر آن بسیار سرد است بطوری که <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> الی <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> درجه زیر صفر فارنهایت است . این ستاره دارای اتمسفر یا هوای محاطی نیست و بدین جهت قابل سکونت نمی باشد. عطارد در نزد یونانیان رب النوع سخنوری و بازرگانی بوده است . و قدما عطارد را سیاره ای می دانستند که در فلک دوم (فلک عطارد) قرار داشت و آن را دبیر فلک می نامیدند. (از فرهنگ فارسی معین ). و رجوع به التفهیم ص <span class=\"hlight\" dir=\"rtl\">١٣٠</span> شود <span class=\"hlight\">:</span> <br>همان تیر و کیوان برابر شده ست <br>عطارد به برج دو پیکر شده ست .<br> <font color=\"Red\">فردوسی .</font><br>تو آسمانی و هنر تو عطارد است <br>و آن بی قرین لقای تو چون ماه آسمان .<br> <font color=\"Red\">منوچهری .</font><br>سیماب دختر است عطارد را<br>کیوان چو مادر است و سُرُب دختر.<br> <font color=\"Red\">ناصرخسرو.</font><br>دبیری ورای وزیری است یعنی <br>عطارد ورای قمر یافت مأوی .<br> <font color=\"Red\">خاقانی .</font><br>جوزا گریست خون که عطارد ببست نطق <br>عنقا بریخت پر که سلیمان گذاشت تخت .<br> <font color=\"Red\">خاقانی .</font><br>مرا اگر تو ندانی عطاردم داند<br>که من کیم ز سر کلک من چه کار آید.<br> <font color=\"Red\">خاقانی .</font><br>عطارد تلمیذ افادت او بود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٥٥</span>).<br>عطارد را قلم مسمار کردی <br>پرند زهره برتن خار کردی .<br> <font color=\"Red\">نظامی .</font><br>ثریا بر ندیمی خاص گشته <br>عطارد بر افق رقاص گشته .<br> <font color=\"Red\">نظامی .</font><br>عطارد کرده زاول خط جوزا<br>سوی مریخ شیرافکن تماشا.<br> <font color=\"Red\">نظامی .</font><br>چرخ گردان را قضا گمره کند<br>صد عطارد را قضا ابله کند.<br> <font color=\"Red\">مولوی .</font><br>عطارد مشتری باید متاع آسمانی را.<br><font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">عطاردحشمت </span> ؛ دارای حشمت و جاه و جلال بسیار. به حشمت عطارد <span class=\"hlight\">:</span> ناهید بهجت سپهر احتشام عطارد حشمت بهرام انتقام . (حبیب السیر چ طهران ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١</span>).<br>- <span class=\"hlight\">عطاردضمیر</span> ؛ تیزفهم <span class=\"hlight\">:</span> مشتری رأی عطاردضمیر. (حبیب السیر چ طهران ج <span class=\"hlight\" dir=\"rtl\">٣</span> جزوه <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٢</span>).<br>- <span class=\"hlight\">عطاردفطنه </span> ؛ زیرک و بافراست و تیزفهم . (ناظم الاطباء).<br></font></div>'),
(184174, 'عطارد', '<span class=\"hlight\">عطارد.</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (اِخ ) ابن عوف بن کعب . جدی است جاهلی از تمیم از عدنانیه . وکرب بن صفوان و بکیربن وساج از نسل او بشمار آیند. (از الاعلام زرکلی به نقل از جمهرة الانساب و اللباب ).<br></font></div>'),
(184175, 'عطارد', '<span class=\"hlight\">عطارد.</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ]</font></b> (اِخ ) ابن محمد. حاسب و منجم . او راست : کتاب الجفر الهندی . العمل بالاسطرلاب . العمل بذات الحلق . ترکیب الافلاک . المرایا المحرقة. (از الفهرست ابن الندیم ).<br></font></div>'),
(184176, 'عطاردمنش', '<span class=\"hlight\">عطاردمنش .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ م َ ن ِ ]</font></b> (ص مرکب ) کنایه از ذکی و تیزطبع است . (از آنندراج ). زیرک و بافراست و تیزفهم . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>دبیر عطاردمنش را نشاند<br>که بر مشتری زهره داند فشاند.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(184177, 'عطاردنصاب', '<span class=\"hlight\">عطاردنصاب .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ن ِ ]</font></b>(ص مرکب ) دارای رتبه و مقام عالی . (ناظم الاطباء).<br></font></div>'),
(184178, 'عطاردی', '<span class=\"hlight\">عطاردی .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (حامص ) عطارد بودن . <BR><font color=\"Blue\">◄</font> کنایه از دبیر بودن . دبیری کردن . منشیگری کردن، به مناسبت آنکه عطارد را دبیر فلک خوانند <span class=\"hlight\">:</span> <br>چو آفتاب ضمیرم عطاردی چه کنم <br>کلاه عاریتی را چرا سپارم سر.<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(184179, 'عطاردی', '<span class=\"hlight\">عطاردی .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (ص نسبی ) منسوب به عطارد. رجوع به عطارد شود.<br></font></div>'),
(184180, 'عطاردی', '<span class=\"hlight\">عطاردی .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (اِخ ) احمدبن عبدالجباربن محمدبن عمیربن عطارد تمیمی عطاردی، مکنی به ابوبکر. از فاضلان کوفه است که به سال <span class=\"hlight\" dir=\"rtl\">١٧٧</span> هَ . ق . در این شهر متولد شد و در بغداد حدیث گفت و مغازی ابن اسحاق را روایت می کرد، و ابن اثیر مورخ آن را از وی شنیده است . عطاردی به سال <span class=\"hlight\" dir=\"rtl\">٢٧٢</span> هَ . ق . در کوفه درگذشت . (از الاعلام زرکلی از تاریخ بغداد). و رجوع به اللباب فی تهذیب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span> شود.<br></font></div>'),
(184181, 'عطاردی', '<span class=\"hlight\">عطاردی .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (اِخ ) احمدبن محمدبن غالب عطاردی، مکنی به ابوالسعادات . از اهالی کرخ بغداد بود و از محدثان و شاعران فاضل بشمار می رفت و او را میلی به تشیع بوده است . (از اللباب فی تهذیب الانساب ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(184182, 'عطاردی', '<span class=\"hlight\">عطاردی .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (اِخ ) طریف بن سفیان سعدی عطاردی، مکنی به ابوسفیان . محدث است و از ابونضره و حسن روایت دارد. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(184183, 'عطاردی', '<span class=\"hlight\">عطاردی .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ ]</font></b> (اِخ ) عبدالرحمان بن محمد عطاردی، مکنی به ابوعبداﷲ. از مادحان یمین الدوله سبکتکین بود و دو بیت زیر از اوست :<br>ملک قلاده است و او میان قلاده <br>زین نگیرد قلاده جز به میانه <br>حشمت او بر دهان دهر دهانه است <br>فضل نیارد لگام جز به دهانه .<br><font color=\"Red\">(از لباب الالباب عوفی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٧</span>).</font><br></font></div>'),
(184184, 'عطاره', '<span class=\"hlight\">عطاره .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِ) اسم نبطی سنبل رومی . (تحفه حکیم مؤمن ) (از مخزن الادویه ).<br></font></div>'),
(184185, 'عطاروت', '<span class=\"hlight\">عطاروت .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) (به معنی تاجها). و آن نام دو شهر است یک در قسمت و حدود جاد در طرف شرقی اردن . دیگری در قسمت افرائیم . (از قاموس کتاب مقدس ).<br></font></div>'),
(184186, 'عطاری', '<span class=\"hlight\">عطاری .</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (حامص ) شغل و عمل عطار. (فرهنگ فارسی معین ). شغل و پیشه ٔ دوافروش . (ناظم الاطباء). عِطارة. (از منتهی الارب ). رجوع به عطار و عطارة شود. <BR><font color=\"Blue\">◄</font> (اِ) دکان عطار. محل کسب عطار.(فرهنگ فارسی معین ). عطارخانه . رجوع به عطار شود.<br></font></div>'),
(184187, 'عطاس', '<span class=\"hlight\">عطاس .</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) (علی ...) ابن حسن بن عبداﷲ حضرمی . ادیب و شاعر قرن دوازدهم هجری . رجوع به علی عطاس شود.<br></font></div>'),
(184188, 'عطاس', '<span class=\"hlight\">عطاس .</span> <font color=\"DarkGreen\"><b>[ ع َطْطا ]</font></b> (اِخ ) احمدبن حسن عطاس . از بزرگان علویان در حضرموت . به سال <span class=\"hlight\" dir=\"rtl\">١٢٥٧</span> هَ . ق . در شهر حریضه متولد شد واز کودکی نابینا بود. و به سال <span class=\"hlight\" dir=\"rtl\">١٣٣٤</span> هَ . ق . درگذشت . او راست : وصایا، و اجازات و رساله ای در قبایل حضرموت . (از الاعلام زرکلی از تاریخ الشعراء الحضرمیین ).<br></font></div>'),
(184189, 'عطاس', '<span class=\"hlight\">عطاس .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) عطسه . (منتهی الارب ) (دهار) (از غیاث اللغات ). هوایی است که با فشار از بینی خارج می شود به همراه صدائی که شنیده می شود. (از اقرب الموارد). صبر. اشنوشه . شنوشه . خفه . و در حدیث است که پیغمبر (ص ) کان یحب العطاس و یکره التثاؤب ؛ یعنی عطسه را می پسندید و از خمیازه اکراه داشت، زیرا عطسه دلالت بر نشاطو سبکی بدن می کند و آنچه از ابخره در دماغ مختنق شده است خارج می سازد، لذا پس از عطسه امر به حمد خداوند کرده است . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> عارضه ای که از آن عطسه آید. عارضه ای که عطسه آرد. (غیاث اللغات ). تحریکی است در غشاء داخلی بینی، که آن را برای عطسه زدن آماده می کند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> صبح . (منتهی الارب ) (اقرب الموارد): جاء قبل طلوع العطاس ؛ پیش از طلوع بامداد آمد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نام سنگی است . (نزهة القلوب مستوفی ).<br></font></div>'),
(184190, 'عطاس', '<span class=\"hlight\">عطاس .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) عطسه دادن . (از منتهی الارب ) (المصادر زوزنی ) (تاج المصادر بیهقی ). عطسه آمدن کسی را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دمیدن صبح . (منتهی الارب ). دمیدن و روشن شدن صبح . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مردن . (از منتهی الارب ) (از اقرب الموارد). عَطس . رجوع به عَطس شود.<br></font></div>'),
(184191, 'عطاس', '<span class=\"hlight\">عطاس .</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (ع ص ) عطسه دهنده . (منتهی الارب ) (آنندراج ).<br></font></div>'),
(184192, 'عطاش', '<span class=\"hlight\">عطاش .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص، اِ) ج ِ عَطشان . (منتهی الارب )(از اقرب الموارد). رجوع به عطشان شود. <BR><font color=\"Blue\">◄</font> ج ِ عَطشی . (از اقرب الموارد). رجوع به عطشی شود.<br></font></div>'),
(184193, 'عطاش', '<span class=\"hlight\">عطاش .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) علت تشنگی که صاحبش سیرآب نشود، و شدت تشنگی . (منتهی الارب ). علتی که تشنگی آرد. (دهار). بیماری تشنگی که هر چند آب خورده شود تشنگی نرود. (غیاث اللغات ) (آنندراج ). بیماریی است که به انسان دست می دهد و در نتیجه ٔ آن هرچند آب خورد سیر نشود. (از اقرب الموارد).<br></font></div>'),
(184194, 'عطاش', '<span class=\"hlight\">عطاش .</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) احمدبن عبدالملک عطاش . از مشاهیر دعات اسماعیلیه در ناحیه ٔ عراق . به سال <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> هَ . ق . عطاش به امر سلطان محمد سلجوقی دستگیر شد و نخست او را بر اشتری نشاندند و به اصفهان بردند هزاران تن از مردم به دنبال او راه افتادند و سرودگویان این حراره و تصنیف را می خواندند:<br>عطاش عالی، جان من، عطاش عالی، میان سرهلالی، ترا باد زچکارو!<br>آنگاه مدت هفت روز او را آویختند و تیرباران کردند سپس جسدش را سوزاندند. رجوع به احمدبن عبدالملک عطاش، و ابن عطاش و تاریخ ادبیات در ایران صفا ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٧</span> شود.<br></font></div>'),
(184195, 'عطاشی', '<span class=\"hlight\">عطاشی .</span> <font color=\"DarkGreen\"><b>[ ع َ شا <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ شا ]</font></b> (ع ص، اِ) ج ِ عَطشان . (منتهی الارب ) (اقرب الموارد). رجوع به عطشان شود.<br></font></div>'),
(184196, 'عطاط', '<span class=\"hlight\">عطاط.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) مرد دلاور و تندار. (از منتهی الارب ). شجاع و جسیم . (اقرب الموارد). و آن را غطاطنیز نقل کرده اند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) شیر بیشه . (منتهی الارب ). اسد. (اقرب الموارد).<br></font></div>'),
(184197, 'عطاف', '<span class=\"hlight\">عطاف .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) شمشیر. (منتهی الارب ). سیف . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> چادر. (منتهی الارب ). ازار. <BR><font color=\"Blue\">◄</font> رداء. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نام سگی . (منتهی الارب ). ج، عُطُف . (اقرب الموارد) (منتهی الارب ). و اعطفة. (اقرب الموارد).<br></font></div>'),
(184198, 'عطاف', '<span class=\"hlight\">عطاف .</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (ع اِ) مصیدة یا چوب کج . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> تیر قمار که بر تیرها مائل باشد و فائز المرام برآید، یا تیر بی فایده و بی نقصان، یا تیر که خمانیده شود بر مأخذ تیرها و جدا باشد. (منتهی الارب ). قدح و تیر قمار که نه غریمت در آن باشد و نه غنیمت . و گویند تیر قمار که بر مأخذ تیرهای دیگر خم شود و جدا گردد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) نام اسب عمروبن معدیکرب است . (از منتهی الارب ).<br></font></div>'),
(184199, 'عطاف', '<span class=\"hlight\">عطاف .</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) ابن نعیم لخمی، از نسل نعمان بن منذر. رجوع به ابوالقاسم (محمد المعتمد...) شود.<br></font></div>'),
(184200, 'عطاف', '<span class=\"hlight\">عطاف .</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) ابن محمدبن علی اُلوسی یا آلُسی مکنی به ابوسعید و ملقب به مؤید. شاعر و غزل سرای قرن ششم هجری . وی به سال <span class=\"hlight\" dir=\"rtl\">٤٩٤</span> هَ . ق .در قریه ٔ آلس یا الوس در حدیثة عانه واقع بر شط فرات متولد شد و در دجیل پرورش یافت سپس به بغداد رفت ودر عهد المسترشد باﷲ عباسی سمت «چاوشی » یافت و ثروتی بهم زد. و به سبب هجو المقتفی عباسی مدت ده سال زندانی گشت و در زندان بینایی خویش را از دست بداد و سرانجام در روزگار المستنجد از زندان رهایی یافت و روانه ٔ موصل شد و به سال <span class=\"hlight\" dir=\"rtl\">٥٥٧</span> هَ . ق . در آنجا درگذشت . (از الاعلام زرکلی از وفیات الاعیان و فوات الوفیات ).<br></font></div>'),
(184201, 'عطاف', '<span class=\"hlight\">عطاف .</span> <font color=\"DarkGreen\"><b>[ ع َطْ طا ]</font></b> (اِخ ) ابن خالد. محدث است . (منتهی الارب ). و رجوع به ابوصفوان (عطاف ...) شود.<br></font></div>'),
(184202, 'عطالة', '<span class=\"hlight\">عطالة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع مص ) باطل شدن و بیکار شدن . (از اقرب الموارد). بیکاری و معطلی . (از آنندراج ). عطالت . و رجوع به عطالت شود.<br></font></div>'),
(184203, 'عطالة', '<span class=\"hlight\">عطالة.</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل َ ]</font></b> (اِخ ) کوهی است مر بنی تمیم را. (منتهی الارب ). کوهی است بزرگ در دیار بنی سعد. و گویند کوهی است از آن بنی تمیم . و برخی آن را کوهی بلند در بحرین دانسته اند. (از معجم البلدان ).<br></font></div>'),
(184204, 'عطالت', '<span class=\"hlight\">عطالت .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع اِمص ) عطالة. بیکاری و معطلی . (از غیاث اللغات ). بیکاری . بطالت . تعطل .عطلت . (یادداشت مرحوم دهخدا). رجوع به عطالة شود.<br>- <span class=\"hlight\">عطالت و بطالت </span> ؛ بیکاری و بیعاری . (یادداشت مرحوم دهخدا).<br></font></div>'),
(184205, 'عطامس', '<span class=\"hlight\">عطامس .</span> <font color=\"DarkGreen\"><b>[ ع َ م ِ ]</font></b> (ع اِ) ج ِ عَیطَموس . (منتهی الارب ). رجوع به عیطموس شود.<br></font></div>'),
(184206, 'عطاملک جوینی', '<span class=\"hlight\">عطاملک جوینی .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ل ِ ک ِ ج ُ وَ ]</font></b> (اِخ ) ملقب به علاءالدین بن بهاءالدین محمد بردار شمس الدین محمدصاحب دیوان . از رجال و مورخان معروف اوایل دوره ٔ مغول . وی به سال <span class=\"hlight\" dir=\"rtl\">٦٢٣</span> هَ .ق . در جوین متولد شد و از آغاز جوانی وارد کارهای دیوانی گشت و از عمال امیرارغون آقا حکمران خراسان گردید. عطاملک چند بار در خدمت امیرارغون به قراقروم پایتخت مغولستان سفر کرد و در ضمن همین سفرها درباره ٔ احوال مغولها و یورتهای اصلی ایشان اطلاع کافی بدست آورد و برای نوشتن تاریخ خود مواد لازم فراهم کرد. وی در سال <span class=\"hlight\" dir=\"rtl\">٦٥٤</span> هَ . ق . بتوسط امیر ارغون به هلاکو معرفی شد و نزد او تقرب یافت . پس از فوت هلاکو وی و برادرش صاحب دیوان سبب رونق دولت اباقا بودند و عطاملک حکومت بغداد و عراق یافت . مجدالملک مکرر از عطاملک نزد خان مغول سعایت میکرد و موجب مزاحمت او و دیگر افراد خاندان جوینی را فراهم می ساخت و در نتیجه عطاملک به حبس افتاد ولی با وساطت شاهزادگان و خوانین مغول در <span class=\"hlight\" dir=\"rtl\">٦٨٠</span> هَ . ق . از حبس نجات یافت و مورد نوازش اباقاقرار گرفت . دشمنان خاندان جوینی باز از پای ننشستندولی نتیجه نبردند. چون تکودار به سلطنت رسید، حکومت بغداد و عراق را کمافی السابق به عطاملک واگذاشت . وی مؤلف تاریخ «جهانگشای جوینی » است . عطاملک این تاریخ را در سال <span class=\"hlight\" dir=\"rtl\">٦٥٥</span> هَ . ق . یعنی مقارن تاریخ فتح قلاع اسماعیلیه بدست هلاکو به انجام رسانید. غالب وقایعی راکه جوینی راجع به دوره ٔ چنگیزی در کتاب خود آورده است از معمرانی که با آن ایام همعصر بوده اند شنیده و ضبط نموده است . و از معتبران مغول نیز کسب اطلاع می کرد و گویا از بعضی از نوشته های مغول نیز استفاده کرده است . تاریخ جهانگشا چنانکه خود مؤلف تقسیم کرده شامل سه جلد است : جلد اول تاریخ شروع کار چنگیزخان و یاساهای چنگیزی و تاریخ قوم اویغور و فتوحات چنگیز درماوراءالنهر و خراسان و انقراض سلسله ٔ خوارزمشاهیان و سلطنت اگتای و گیوگ و احوال جوجی و جغتای . جلد دوم در تاریخ سلاطین خوارزمشاهی و قراختائیان و حکام مغول ایران . جلد سوم در تاریخ منکوقاآن و اردوکشی هلاکوبه ایران و شرح تاریخ اسماعیلیه تا سال <span class=\"hlight\" dir=\"rtl\">٦٥٥</span>، که بیشتر قسمت اخیر مقتبس از کتاب «سرگذشت سیدنا» است و شرحی که در باب فتح بغداد منسوب به خواجه نصیرالدین طوسی است غالباً به عنوان ذیل جلد سوم به آخر نسخه های جهانگشا الحاق شده است . انشاء کتاب مزبور بلیغ و از لحاظ احتوا بر اطلاعات نفیس کم نظیر است . درگذشت عطاملک به سال <span class=\"hlight\" dir=\"rtl\">٦٨١</span> هَ . ق . رخ داد. (فرهنگ فارسی معین ).<br></font></div>'),
(184207, 'عطامیس', '<span class=\"hlight\">عطامیس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عَیطَموس . (منتهی الارب ). رجوع به عیطموس شود.<br></font></div>'),
(184208, 'عطان', '<span class=\"hlight\">عطان .</span> <font color=\"DarkGreen\"><b>[ ع ُطْ طا ]</font></b> (ع ص، اِ) ج ِ عاطِن . (اقرب الموارد). رجوع به عاطن شود. <BR><font color=\"Blue\">◄</font> قوم عطان ؛ قوم که شتران را بر «عطن » فرود آورند. (منتهی الارب ). قومی که در اعطان و مأواهای شتران فرود آیند. (از اقرب الموارد). عُطون . عَطَنة. و رجوع به عطون و عطنة شود.<br></font></div>'),
(184209, 'عطان', '<span class=\"hlight\">عطان .</span><font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) سرگین یا نمک که بر پوست پاشند تا بدبوی و تباه نگردد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184210, 'عطاوان', '<span class=\"hlight\">عطاوان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) مثنای عَطاء. (از اقرب الموارد) (منتهی الارب ). رجوع به عطاء شود.<br></font></div>'),
(184211, 'عطاپاش', '<span class=\"hlight\">عطاپاش .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (نف مرکب ) افشاننده ٔ عطا. عطابخش <span class=\"hlight\">:</span> <br>گر رحمت حق هست عطاپاش و خطاپوش <br>تو رحمت حق بر همه آفاق عطائی .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(184212, 'عطاپذیر', '<span class=\"hlight\">عطاپذیر.</span> <font color=\"DarkGreen\"><b>[ ع َ پ َ ]</font></b> (نف مرکب ) عطاپذیرنده . قبول کننده ٔ دهش و بخشش <span class=\"hlight\">:</span> <br>آنکه عطا و عطاپذیر مر او راست <br>معدن فضل است و اصل بار خدائی .<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(184213, 'عطایا', '<span class=\"hlight\">عطایا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عطیّه . (منتهی الارب ) (اقرب الموارد). دهشها و بخشیده شده ها. (از آنندراج ). رجوع به عطیة شود <span class=\"hlight\">:</span> از صلت و عطایاء او به حظی وافر و نصیبی کامل متحظی شد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢١٤</span>).<br></font></div>'),
(184214, 'عطب', '<span class=\"hlight\">عطب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) نرم و نازک شدن پنبه . (منتهی الارب ). عطب القطن ؛ پنبه نرم شد. (از اقرب الموارد). عُطوب . رجوع به عطوب شود.<br></font></div>'),
(184215, 'عطب', '<span class=\"hlight\">عطب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) نرمی و نازکی پنبه . (از منتهی الارب ) (از اقرب الموارد). قطن نرم . (مخزن الادویه ).<br></font></div>'),
(184216, 'عطب', '<span class=\"hlight\">عطب .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (ع مص )هلاک گردیدن . (از منتهی الارب ). هلاک شدن، خواه برای انسان باشد و خواه غیرانسان . (از اقرب الموارد). هلاک شدن . (المصادر زوزنی ) (تاج المصادر بیهقی ). هلاک، که به عرف آن را هلاکی گویند. (غیاث اللغات ) <span class=\"hlight\">:</span> <br>نیست خود از مرغ پران این عجب <br>کو نبیند دام و افتد در عطب .<br> <font color=\"Red\">مولوی .</font><br>هم ز عزرائیل با قهر و عطب <br>تو بهی چون سبق رحمت بر غضب .<br> <font color=\"Red\">مولوی .</font><br> <BR><font color=\"Blue\">◄</font> شکسته شدن و عاجز و مانده گردیدن شتر و اسب از رفتن . (از منتهی الارب ). شکسته شدن شتر و فرس . <BR><font color=\"Blue\">◄</font> به شدت خشمگین شدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) رنج و مشقت <span class=\"hlight\">:</span> <br>از پس پیغمبر و حیدر بدین در ره مده <br>یک رمه بیگانگان را تات نفزاید عطب .<br> <font color=\"Red\">ناصرخسرو.</font><br>تا بزیر چرخ ناری چون حطب <br>می نسوزم در عنا و در عطب .<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(184217, 'عطب', '<span class=\"hlight\">عطب .</span> <font color=\"DarkGreen\"><b>[ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ طُ ]</font></b> (ع اِ) پنبه . (منتهی الارب ) (الفاظ الادویة). قطن . (اقرب الموارد) (اختیارات بدیعی ) (تحفه ٔ حکیم مؤمن ). پنبه، که آن را قطن هم خوانند و دود آن زکام را نافع است . (از برهان ). قطن . جمع آن عطاب است و قطعه ای از آن را عطبة گویند. (از مخزن الادویه ).<br></font></div>'),
(184218, 'عطبة', '<span class=\"hlight\">عطبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع اِ) پاره ای از پنبه . (منتهی الارب ). قطعه ای از عطب . (از اقرب الموارد). رجوع به عُطب شود. <BR><font color=\"Blue\">◄</font> لته ای که از آن آتش برگیرند. (منتهی الارب ). خرقه که بدان آتش گیرند. (از اقرب الموارد). أجد ریح عطبة؛ بوی پنبه یا کهنه ٔسوخته می شنوم . (از اقرب الموارد) (از منتهی الارب ).<br></font></div>'),
(184219, 'عطبل', '<span class=\"hlight\">عطبل .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب ُ ]</font></b> (ع ص ) زن جوان خوب صورت تمام خلقت نیکواندام پرگوشت درازگردن . (منتهی الارب ). زن جوان زیبای پرگوشت گردن دراز. (از اقرب الموارد). ج، عَطابل، عَطابیل . (منتهی الارب ) (اقرب الموارد). عُطبول . عُطبولة.عَیطَبول . رجوع به عطبول و عطبولة و عیطِبول شود.<br></font></div>'),
(184220, 'عطبول', '<span class=\"hlight\">عطبول .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) به معنی عُطبل است . (از منتهی الارب ). به معنی عطبل است، و گویند عطبول زن درازقامت و تمام خلقت است . (از اقرب الموارد). و در صفت پیغمبر (ص ) گفته اند که لم یکن یعطبول و لاقصیر؛ که منظور از عطبل، درازقامت و درازگردن است و گویند درازصلب . (از منتهی الارب ). عُطبُل . عُطبولة. عَیطبول . رجوع به عطبل شود.<br></font></div>'),
(184221, 'عطبولة', '<span class=\"hlight\">عطبولة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ]</font></b> (ع ص ) به معنی عُطبول است . (از منتهی الارب ) (از اقرب الموارد). عُطبول . عَیطَبول . رجوع به عطبل شود.<br></font></div>'),
(184222, 'عطر', '<span class=\"hlight\">عطر.</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (ع مص ) خوشبوی شدن . (از منتهی الارب ) (از اقرب الموارد) (دهار) (تاج المصادر بیهقی ) (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> خوشبوی کردن به عطر. (المصادر زوزنی ) (از غیاث اللغات ).<br></font></div>'),
(184223, 'عطر', '<span class=\"hlight\">عطر.</span> <font color=\"DarkGreen\"><b>[ ع َ طِ ]</font></b> (ع ص ) مرد خوشبوی مالیده . مؤنث : عطرة. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنکه پیوسته عطر و خوشبوی بکار برد. (از اقرب الموارد).<br></font></div>'),
(184224, 'عطر', '<span class=\"hlight\">عطر.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) بوی خوش . (منتهی الارب ) (دهار). خوشبو و بوی خوش . (غیاث اللغات ). ماده ٔ خوشبوی نباتی یا حیوانی و روغنی شکلی است که دراندامهای مختلف غالب گیاهان وجود دارد. (فرهنگ فارسی معین ). ج، عُطور. (اقرب الموارد) (منتهی الارب ). خوشبوی و خوشبوئی و بوی خوش از هر چیز که برآید. (از ناظم الاطباء). معروف است در ایام و حالیه، عطریات در مشرق زمین بسیار متداول و مستعمل بوده و هست و به اشخاص و به لباس و رختخواب و غیره پاشیده می شد. (قاموس کتاب مقدس ). تطیب و عطر زدن نزد اعراب جاهلی از دلایل ثروت و نجیب زادگی بوده است . (از تاریخ تمدن اسلام جرجی زیدان ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٨٣</span>). بوی خوش و چیزی که آن را بخور کنند چون لبان، و این مجاز است . و با لفظ سودن و پیچیدن و افشاندن و در عطر کشیدن و به عطر مالیدن مستعمل است . (آنندراج ). عطرهای قدیم عبارت است از: مشک . عنبر. ند. غالیه . زباد. لادن . گلاب . عود. بان . عبیر. کافور. صندل . اظفارالطیب . اشنه (دواله ). زهری . (یادداشت به خط مرحوم دهخدا). میعة. مائعة. معتقة <span class=\"hlight\">:</span> خداوند زیاده چه فرماید از جامه و جواهر و عطر و رسول را معلوم است که چه دهند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٩٦</span>).<br>تابدین دلق ای برادر در سنائی ننگری <br>عطر از عود آنگهی آید که بر آذر نهیم .<br> <font color=\"Red\">سنائی .</font><br>و راست آن را ماند که عطر برآتش نهند. (کلیله و دمنه ).<br>با عطرهای روضه ٔ پاکش عجب مدار<br>گر طوبی بهشت برآرد گیای خاک .<br> <font color=\"Red\">خاقانی .</font><br>مشرق به عود سوخته دندان سپید کرد<br>چون بوی عطر عید برآمد ز مجمرش .<br> <font color=\"Red\">خاقانی .</font><br>سر چو آه عاشقان برکرد صبح <br>عطر آتش زای زان برکرد صبح .<br> <font color=\"Red\">خاقانی .</font><br>عطرها در اصطلاح گیاه شناسی موادی هستند غالباً دارای بوی مطبوع و مخلوطی از چند ماده ٔ شیمیائی که در اکثر گیاهان به صورت قطرات کوچک داخل سلولهای گیاهی (خصوصاً سلولهای بشره ) وجود دارند و چون نور رابیشتر از مواد دیگر سیتوپلاسم منکسر می کنند به خوبی قابل تشخیصند. مواد عطری در اندامهای مختلف اکثر گیاهان از قبیل برگ و پوسته و گل میوه و دانه وجود دارند ترکیب شیمیائی عطرها اختلاطی از چند ماده است که مهمترین آنها عبارتند از: هیدروکربورهای ترپنی  به فرمول عمومی «<span class=\"hlight\" dir=\"rtl\">H٨</span> <span class=\"hlight\" dir=\"rtl\">C٥</span>» و الکلهای مختلف و اسیدها و ستن های مختلف و گاهی هم برخی ترکیبات گوگردی . عطرها در آب کمی حل می شوند ولی در اتر و بنزین و کلروفرم و الکل به خوبی حل می گردند اما برخلاف چربیها با قلیاها تولید صابون نمی کنند و بعلاوه در حرارتهای <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تا <span class=\"hlight\" dir=\"rtl\">١١٠</span> درجه در بافتها تبخیر می شوند و از بین می روند، از این رو می توان آنها را در مجاورت بخار آب تقطیر کرد و به حالت مایع به دست آورد. (طریقه ٔ استخراج عطرها). اسانس ها. روغن های عطری . مواد معطره . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">برگ عطر</span> ؛ شمعدانی عطری که نوعی گیاه است . (از فرهنگ فارسی معین ). و رجوع به شمعدانی شود.<br>- <span class=\"hlight\">عطرالامة</span> ؛ ذفراء که گیاهی است . رجوع به ذفراء شود.<br>- <span class=\"hlight\">عطر بهارنارنج </span> ؛ در اصطلاح گیاه شناسی و پزشکی عطری را گویند که از شکوفه ها و گلهای درخت نارنج گیرند. (از فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عطر جهانگیری </span> ؛ عطری که از گلاب گیرند، چون این عطر سابق نبود نورجهان بیگم در عهد جهانگیری ایجاد نمود لهذا به عطر جهانگیری موسوم شده است . (غیاث اللغات ) (از آنندراج ) <span class=\"hlight\">:</span> <br>رنگ خامی را بدل کردم به بوی پختگی <br>تا جهانگیری  کنم عطر گلابم کرده اند.<br><font color=\"Red\">سالک یزدی (از آنندراج ).</font><br>و عود مشام انبساط از بس بوی پالکیش به عطر جهانگیری رسید. (ملاطغرا، در انوار المشارق به نقل از آنندراج ).<br>- <span class=\"hlight\">عطر رازقی </span> ؛ در اصطلاح گیاه شناسی عطری را گویند که از گل رازقی به دست آورند. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عطر گل </span> ؛ عطر گل سرخ . عطر گل گلاب  در اصطلاح گیاه شناسی عطری را گویند که از گل سرخ به دست آورند. (گل گلاب ). وآن به علت بوی بسیار مطبوعش مورد توجه است . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عطر مثلث </span> ؛ عطر مرکب از عود و عنبر و صندل است و بهتر از آن عطر مرکب از عطر گلاب و عطر عودو عنبر است . (مخزن الادویه ). و رجوع به عطر مثلثی و مثلث شود.<br>- <span class=\"hlight\">عطر مثلثی </span> ؛ خوشبویی که از عنبر و مشک و دیگر عطریات سازند و آن را به عربی غالیة و به هندی ارگجه خوانند. (آنندراج ) (از برهان ). و رجوع به عطر مثلث و مثلث شود.<br>- <span class=\"hlight\">عطر مَنشِم </span> ؛ حب دهن منشم است . (مخزن الادویه ). حب المنشم است . (تحفه ٔ حکیم مؤمن ). رجوع به منشم شود.<br>- <span class=\"hlight\">مثلث عطر</span> ؛ عطر مثلث . عطر مثلثی . غالیة <span class=\"hlight\">:</span> <br>روحانیان مثلث عطری بسوخته <br>از عطرها مسدس عالم شده ملا.<br> <font color=\"Red\">خاقانی .</font><br>رجوع به عطر مثلث و عطر مثلثی شود.<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">لا عطر بعد عروس . رجوع به عروس شود</span> .<br><BR><font color=\"Blue\">◄</font> گیاهی است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> به اصطلاح بعضی عامه ٔ چرسیان، شبنمی است که بر درخت قنب نشیند و منعقد گردد که چرس اعلی و خالص نامند. (مخزن الادویه ).<br></font></div>'),
(184225, 'عطر', '<span class=\"hlight\">عطر.</span> <font color=\"DarkGreen\"><b>[ ع ُ طُ ]</font></b> (ع ص، اِ) ج ِ عاطِر. (منتهی الارب ) (اقرب الموارد). رجوع به عاطر شود.<br></font></div>'),
(184226, 'عطر آلودن', '<span class=\"hlight\">عطر آلودن .</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ]</font></b> (مص مرکب ) آمیختن به عطر. عطر آمیختن . عطر زدن : استعطار و تعطر؛ خود را عطر آلودن . (از منتهی الارب ).<br></font></div>'),
(184227, 'عطر آمیختن', '<span class=\"hlight\">عطر آمیختن .</span> <font color=\"DarkGreen\"><b>[ ع ِ ت َ ]</font></b> (مص مرکب ) عطرآلودن . عطر زدن . خوشبو کردن .<br></font></div>'),
(184228, 'عطر سودن', '<span class=\"hlight\">عطر سودن .</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ ]</font></b> (مص مرکب ) سودن عطر تا بوی آن منتشر شود. پراکندن خوشبوی <span class=\"hlight\">:</span> <br>بوستان عطار گشت و عطرها ساید همی .<br><font color=\"Red\">میرمعزی (از آنندراج ).</font><br></font></div>'),
(184229, 'عطر فشاندن', '<span class=\"hlight\">عطر فشاندن .</span> <font color=\"DarkGreen\"><b>[ ع ِ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ دَ ]</font></b> (مص مرکب ) عطر پراکندن . افشاندن بوی خوش . پاشیدن خوشبوی بر چیزی <span class=\"hlight\">:</span> <br>درودی شهشنه بر آن غار خواند<br>برون رفت و عطری بر آتش فشاند.<br> <font color=\"Red\">نظامی (از آنندراج ).</font><br>عطر بر گلشن فشاندی خاک ریحان دوست گشت <br>ناز بر گلشن دمیدی گل نسیم آزار شد.<br><font color=\"Red\">طالب آملی (از آنندراج ).</font><br></font></div>'),
(184230, 'عطر مالیدن', '<span class=\"hlight\">عطر مالیدن .</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ ]</font></b> (مص مرکب ) عطر زدن . عطر آلودن .<br></font></div>'),
(184231, 'عطر پاشیدن', '<span class=\"hlight\">عطر پاشیدن .</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ ]</font></b> (مص مرکب ) کنایه از پاشیدن گلاب و عنبر باشد، و الا پاشیدن دیگر عطرها مرسوم نیست و در هندوستان عطر مالیدن شهرت دارد. (آنندراج ). عطر پراکندن <span class=\"hlight\">:</span> <br>حسن خلقت نیست از بهر خدا چون شاهدان <br>بر خوداین عطر از برای دیگران پاشیده ای .<br><font color=\"Red\">شفیع اثر (از آنندراج ).</font><br></font></div>'),
(184232, 'عطر پیچیدن', '<span class=\"hlight\">عطر پیچیدن .</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ ]</font></b> (مص مرکب ) پراکنده شدن عطر. افشانده شدن عطر. منتشر شدن بوی خوش در فضا <span class=\"hlight\">:</span> <br>عطر آن گل پیرهن تا در هوا پیچیده است <br>بوی گل دودی است در مغز صبا پیچیده است .<br><font color=\"Red\">طالب آملی (از آنندراج ).</font><br></font></div>'),
(184233, 'عطرآمیز', '<span class=\"hlight\">عطرآمیز.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ن مف مرکب ) عطرآمیخته . خوشبو. معطر. (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>از بسی بویهای عطرآمیز<br>معتدل گشته باد برف انگیز.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(184234, 'عطرآمیزی', '<span class=\"hlight\">عطرآمیزی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b>(حامص مرکب ) خوشبویی . معطری . (فرهنگ فارسی معین ).<br></font></div>'),
(184235, 'عطرآگین', '<span class=\"hlight\">عطرآگین .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ص مرکب ) آمیخته به عطر. عطرآمیخته .<br></font></div>'),
(184236, 'عطرات', '<span class=\"hlight\">عطرات .</span> <font color=\"DarkGreen\"><b>[ ع َ طِ ]</font></b> (ع ص، اِ) ج ِ عَطِرة. (منتهی الارب ) (اقرب الموارد). رجوع به عطرة شود.<br></font></div>'),
(184237, 'عطرافشان', '<span class=\"hlight\">عطرافشان .</span> <font color=\"DarkGreen\"><b>[ ع ِ اَ ]</font></b> (نف مرکب ) عطرپراکننده . <BR><font color=\"Blue\">◄</font> (حامص مرکب ) افشاندن عطر. بوی خوش پراکنی . عطرافشانی . عطر پراکندن . (از آنندراج ). عطر افشاندن <span class=\"hlight\">:</span> <br>ز عطرافشان این باکوره ٔ غیب <br>معنبر شد جهان را دامن و جیب .<br><font color=\"Red\">میرخسرو (از آنندراج ).</font><br></font></div>'),
(184238, 'عطران', '<span class=\"hlight\">عطران .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) به سریانی قطران است . (فهرست مخزن الادویه ).<br></font></div>'),
(184239, 'عطربیز', '<span class=\"hlight\">عطربیز.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (نف مرکب ) عطربیزنده . عطرپاش . (فرهنگ فارسی معین ). عطرافشان .<br></font></div>'),
(184240, 'عطربیزی', '<span class=\"hlight\">عطربیزی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (حامص مرکب ) عطرپاشی . (فرهنگ فارسی معین ). عطر افشاندن .<br></font></div>'),
(184241, 'عطرد', '<span class=\"hlight\">عطرد.</span> <font color=\"DarkGreen\"><b>[ ع َ طَرْ رَ ]</font></b> (ع ص ) درشت و دشوار. (از منتهی الارب ). شدید و شاق . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سیر شتاب . (منتهی الارب ). سیر سریع. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> راه روشن . (منتهی الارب ). طریق آشکار و فراخ که در آن از هر جا بخواهند بروند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد گزیده . (منتهی الارب ). شخص نجیب . (ازاقرب الموارد). <BR><font color=\"Blue\">◄</font> رسن  دراز و ایام دراز. (منتهی الارب ). کوهها و روزهای دراز و طولانی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نیزه ٔ تیز. (منتهی الارب ). سنان و سرنیزه ٔ مذلق و تیز. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سال تمام . (منتهی الارب ) (از اقرب الموارد). عَطَوَّد. رجوع به عطود شود.<br></font></div>'),
(184242, 'عطردان', '<span class=\"hlight\">عطردان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِ مرکب ) قوطی که در آن عطر و خوشبوی ریزند. (ناظم الاطباء). ظرفی که در آن عطر ریزند. (فرهنگ فارسی معین ). جای عطر. بویدان . جؤنة. طبله . قسیمة. لطیمة. مسوف <span class=\"hlight\">:</span> <br>غنچه ٔ گل عطردان سنبل موی تو است <br>آفتاب از دور گردان سر موی تو است .<br><font color=\"Red\">حسین خالص (از آنندراج ).</font><br></font></div>'),
(184243, 'عطرریز', '<span class=\"hlight\">عطرریز.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (نف مرکب ) عطرریزنده . عطرپاش <span class=\"hlight\">:</span> <br>نباشد صراحی چرا عطرریز<br>که کام و زبان گشت خمیازه خیز.<br><font color=\"Red\">نورالدین ظهوری (از آنندراج ).</font><br></font></div>'),
(184244, 'عطرزدن', '<span class=\"hlight\">عطرزدن .</span> <font color=\"DarkGreen\"><b>[ ع ِ زَ دَ ]</font></b> (مص مرکب ) به عطری خود را معطر ساختن . تعطیر کردن . تطییب کردن .<br></font></div>'),
(184245, 'عطرسا', '<span class=\"hlight\">عطرسا.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (نف مرکب ) عطرسای . عطرساینده . <BR><font color=\"Blue\">◄</font> معطرکننده . خوشبوسازنده . (فرهنگ فارسی معین ). رجوع به عطرسای شود. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) سنگی که به روی آن عطر می سایند. (ناظم الاطباء).<br></font></div>'),
(184246, 'عطرسازی', '<span class=\"hlight\">عطرسازی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (حامص مرکب ) عِطارة. (از منتهی الارب ). ساختن عطر. عطر و خوشبوی ساختن و با آن دمسازی کردن <span class=\"hlight\">:</span> <br>تا شب آنجا نشاط و بازی کرد<br>عودسوزی و عطرسازی کرد.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(184247, 'عطرسای', '<span class=\"hlight\">عطرسای .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (نف مرکب ) عطرسا. عطرساینده . <BR><font color=\"Blue\">◄</font> معطرکننده . خوشبوسازنده . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>چون گل از کام خود برآر نفس <br>کام تو عطرسای کام تو بس .<br> <font color=\"Red\">نظامی .</font><br>ز بس صاف پالوده عطرسای <br>بسا مغز پالوده کآمد بجای .<br> <font color=\"Red\">نظامی .</font><br>نقل دهن غزلسرایان <br>ریحانی مغز عطرسایان .<br> <font color=\"Red\">نظامی .</font><br>کی عطرسای مجلس روحانیان شدی <br>گل را اگر نه بوی تو کردی رعایتی .<br> <font color=\"Red\">حافظ.</font><br>چو عطرسای شود زلف سنبل از دم باد<br>تو قیمتش به سر زلف عنبری بشکن .<br> <font color=\"Red\">حافظ.</font><br>رجوع به عطرسا شود.<br>- <span class=\"hlight\">عطرسایان شب </span> ؛ کنایه از ستارگان است <span class=\"hlight\">:</span><br>عطرسایان شب به کار تواند<br>سبزپوشان در انتظار تواند.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(184248, 'عطرسایی', '<span class=\"hlight\">عطرسایی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (حامص مرکب ) عمل و کیفیت عطرسای . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>شب از ناف خود عطرسایی گشاد<br>جهان زیور روشنایی نهاد.<br> <font color=\"Red\">نظامی .</font><br>چو آمد زلف شب در عطرسایی <br>به تاریکی فروشد روشنایی .<br> <font color=\"Red\">نظامی .</font><br>رجوع به عطرسای شود.<br></font></div>'),
(184249, 'عطرسوز', '<span class=\"hlight\">عطرسوز.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (نف مرکب ) عطر سوزنده .آنکه یا آنچه عطر را می سوزاند. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) بوی سوز. عودسوز. مجمر. (یادداشت مرحوم دهخدا).<br></font></div>'),
(184250, 'عطرسوزی', '<span class=\"hlight\">عطرسوزی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (حامص مرکب ) سوزاندن عطر تا بوی آن برآید و پراکنده شود. پراکندن عطر <span class=\"hlight\">:</span> <br>و آن تنگ دهان تنگ روزی <br>چون عود و شکر به عطرسوزی .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(184251, 'عطرفروش', '<span class=\"hlight\">عطرفروش .</span> <font color=\"DarkGreen\"><b>[ ع ِ ف ُ ]</font></b> (نف مرکب ) عطرفروشنده . بوفروش . وآن را در عرف هند گندهی خوانند. (آنندراج ). کسی که خوشبو می فروشد. (ناظم الاطباء). و رجوع به عطر شود.<br></font></div>'),
(184252, 'عطرفزا', '<span class=\"hlight\">عطرفزا.</span> <font color=\"DarkGreen\"><b>[ ع ِ ف َ ]</font></b> (نف مرکب ) عطرفزای . عطرفزاینده . رجوع به عطرفزای شود.<br></font></div>'),
(184253, 'عطرفزای', '<span class=\"hlight\">عطرفزای .</span> <font color=\"DarkGreen\"><b>[ ع ِ ف َ ]</font></b> (نف مرکب )عطرفزا. عطرفزاینده . افزاینده ٔ خوشبوی <span class=\"hlight\">:</span> <br>بید بسوز و باده کن راوق و لعل و باده را<br>چون دم مشک و بید عطرفزای تازه بین .<br><font color=\"Red\">خاقانی (دیوان چ سجادی ص <span class=\"hlight\" dir=\"rtl\">٤٥٨</span>).</font><br></font></div>'),
(184254, 'عطرق', '<span class=\"hlight\">عطرق .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) از اعلام است . (از منتهی الارب ).<br></font></div>'),
(184255, 'عطرم', '<span class=\"hlight\">عطرم .</span><font color=\"DarkGreen\"><b>[ ع ِ رِ ]</font></b> (ع اِ) فضله ٔ شیر بیشه . (ناظم الاطباء).<br></font></div>'),
(184256, 'عطرود', '<span class=\"hlight\">عطرود.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ساز و برگ یا نوید ساز و برگ . (منتهی الارب ). جماعت از مردم، و یا ساز و برگ و تجهیزات . (از اقرب الموارد). رجوع به عطردة شود.<br></font></div>'),
(184257, 'عطرپاش', '<span class=\"hlight\">عطرپاش .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (نف مرکب ) عطرپاشنده . آنکه یا آنچه عطر پاشد. عطربیز. (فرهنگ فارسی معین ). عطرافشان . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) ظرفی غالباً بلورین، دارای دهانه ای منحنی که در آن گویی لاستیکی میان تهی تعبیه کرده اند، و چون گوی را بفشارند فشار هوا قطرات عطر را از دهانه براند و پاشان سازد. (از فرهنگ فارسی معین ).<br></font></div>'),
(184258, 'عطرپاشی', '<span class=\"hlight\">عطرپاشی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (حامص مرکب ) عمل عطرپاش . عطربیزی . عطر افشاندن . (از فرهنگ فارسی معین ).<br></font></div>'),
(184259, 'عطرپرور', '<span class=\"hlight\">عطرپرور.</span> <font color=\"DarkGreen\"><b>[ ع ِ پ َرْ وَ ]</font></b> (نف مرکب ) عطرپرورنده <span class=\"hlight\">:</span> <br>بخندان از لب آن غنچه باغم <br>وزان گل عطرپرور کن دماغم .<br><font color=\"Red\">جامی (از آنندراج ).</font><br></font></div>'),
(184260, 'عطرپیما', '<span class=\"hlight\">عطرپیما.</span> <font color=\"DarkGreen\"><b>[ ع ِ پ َ <span class=\"hlight\" dir=\"rtl\">/</span> پ ِ ]</font></b> (نف مرکب ) عطر پیماینده . که بر عطر گذر دارد <span class=\"hlight\">:</span> <br>بسیار نسیم عطرپیماست <br>برتارک گل مگر سوار است .<br><font color=\"Red\">علی خراسانی (از آنندراج ).</font><br></font></div>'),
(184261, 'عطرگردان', '<span class=\"hlight\">عطرگردان .</span> <font color=\"DarkGreen\"><b>[ ع ِ گ َ ]</font></b> (نف مرکب ) گرداننده ٔ عطر. آنکه یا آنچه عطر را بگرداند. آنچه عطر را در پراکند.که خوشبوی را به هر سوی برد و نشر دهد <span class=\"hlight\">:</span> <br>شراب ارغوانی را گلاب اندر قدح ریزیم <br>نسیم عطرگردان را شکر در مجمر اندازیم .<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(184262, 'عطری', '<span class=\"hlight\">عطری .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ص نسبی ) منسوب به عطر. معطر و دارای بوی خوش . (ناظم الاطباء). رجوع به عطر شود.<br>- <span class=\"hlight\">شمعدانی عطری </span> ؛ در اصطلاح گیاه شناسی نوعی شمعدانی که دارای برگهای بسیار معطر است و این بوی مطبوع عطر مخصوصاً با لمس برگها بیشتر استشمام می شود. (از فرهنگ فارسی معین ). رجوع به شمعدانی شود.<br></font></div>'),
(184263, 'عطریات', '<span class=\"hlight\">عطریات .</span> <font color=\"DarkGreen\"><b>[ ع ِ ری یا ]</font></b> (ع اِ مرکب ) ج ِ عطریة. بویهای خوش . خوشبویها. (ناظم الاطباء). مشک، عنبر، عبیر، غالیه، کافور، ند، مشک، زباد و گلاب . (یادداشت به خط مرحوم دهخدا). و رجوع به عطریة شود.<br></font></div>'),
(184264, 'عطریة', '<span class=\"hlight\">عطریة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ری ی َ ]</font></b> (ع ص نسبی ) مؤنث عِطری . خوشبو. ج، عطریّات . (فرهنگ فارسی معین ). رجوع به عطریات شود. <BR><font color=\"Blue\">◄</font> (اِمص ) خوشبویی : و له رائحة فیها عطریة. (ابن البیطار).<br></font></div>'),
(184265, 'عطس', '<span class=\"hlight\">عطس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) عطسه دادن . (منتهی الارب ). عطسه آمدن کسی را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دمیدن صبح . (از منتهی الارب ). عطس الصبح ؛ صبح آشکار شد و روشن شد. و گویند عطس أنف الصبح ؛ یعنی آغاز صبح آشکار شد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مردن . (از منتهی الارب ) (از اقرب الموارد). عُطاس . رجوع به عطاس شود.<br></font></div>'),
(184266, 'عطسة', '<span class=\"hlight\">عطسة.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ ]</font></b> (ع اِ) اسم المرة است از مصدر عطس و عطاس . (از اقرب الموارد). یک دفعه عطسه زدن . رجوع به عطس و عطاس شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(184267, 'عطسه', '<span class=\"hlight\">عطسه .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ]</font></b> (اِ) عطسة. از ع، معروف است که به هندی چهینک نامند. (منتهی الارب ). هوایی است که به شدت و همراه آواز از بینی خارج می گردد. (از اقرب الموارد). حرکتی که بر اثر آن هوا به شدت و با صدا از دهان و تجاویف بینی خارج شود. (فرهنگ فارسی معین ) (ناظم الاطباء). شنواسه و با لفظ دادن و زدن و پیچیدن و ریختن مستعمل است . (آنندراج ).اشنوسه . سنوسه . شنوشه . عطاس و معمول است که عطسه زننده را «یرحمک اﷲ» و «عافیت باشد» گویند <span class=\"hlight\">:</span> <br>تو بر آن عطسه هم بخوان الحمد<br>کاهل سنت چنینت فرماید.<br> <font color=\"Red\">خاقانی .</font><br>لیک غماز اوست نطق چنانک <br>عطسه ٔ دزدو سرفه ٔ طرار.<br> <font color=\"Red\">خاقانی .</font><br>رجوع به عطاس شود.<br>- <span class=\"hlight\">عطسه ٔ ستور</span> ؛ کداس . کدسة. نثیر. (از منتهی الارب ).<br> <BR><font color=\"Blue\">◄</font> گویند: فلان عطسة فلان ؛ یعنی شبیه و مانان اوست در خلق و خلق . (منتهی الارب ) (از اقرب الموارد).<br>- <span class=\"hlight\">عطسه ٔ کسی بودن </span> ؛ سخت به او شبیه بودن . خلفاً و خلقاً مانند او بودن . (یادداشت به خط مرحوم دهخدا). چنانکه گویند گربه از عطسه ٔ شیر زاده است . (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> در معنی سالاری این احمد مردی شهم بود و او را عطسه ٔ امیرمحمود گفتندی و بدو نیک بمانستی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٠٨</span>).<br>زاده ٔ طبع منند اینان که خصمان منند<br>آری آری گربه هست ازعطسه ٔ شیر ژیان .<br> <font color=\"Red\">خاقانی .</font><br>چرخ به هر سان که هست زاده شمشیر اوست <br>گربه به هر حال هست عطسه ٔ شیر عرین .<br> <font color=\"Red\">خاقانی .</font><br>اگر شیر بر جا نماند رواست <br>ولی عطسه ٔ شیر ماند بجای .<br><font color=\"Red\">خاقانی .</font><br>بر حسودت که عطسه ٔ دیو است <br>صبحدم خنده ٔ بلارک تست .<br> <font color=\"Red\">خاقانی .</font><br> <BR><font color=\"Blue\">◄</font> کنایه از نتیجه و محصول . (فرهنگ فارسی معین ).<br>دیر زی ای بحر کف که عطسه ٔ جودت <br>چشمه ٔ مهر است کز غمام برآمد.<br> <font color=\"Red\">خاقانی .</font><br>عطسه ٔ تست آفتاب دیر زی ای ظل حق <br>مسندتست آسمان تکیه زن ای محترم .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عطسه ٔ آدم </span> ؛ زاده و نتیجه ٔ آدم . کنایه از حضرت مسیح <span class=\"hlight\">:</span> <br>می عطسه ٔ آدم شده یعنی که عیسی دم شده <br>داروی جام جم شده در دیر دارا داشته .<br> <font color=\"Red\">خاقانی .</font><br>عطسه ٔ او آدم است عطسه ٔ آدم مسیح <br>اینت خلف کز شرف عطسه ٔ او بود باب .<br> <font color=\"Red\">خاقانی .</font><br>گیسوی حوا شناس پرچم منجوق او<br>عطسه ٔ آدم شناس شیهه ٔ یکران او.<br> <font color=\"Red\">خاقانی .</font><br>بسِّر عطسه ٔ آدم بسنّت الحوا<br>بهیکلش که یداﷲ سرشت از آب و تراب .<br> <font color=\"Red\">خاقانی (دیوان ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>).</font><br>خطبه دولت به فصیحی رسد<br>عطسه ٔ آدم به مسیحی رسد.<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">عطسه ٔ آفتاب </span> ؛ کنایه از سپیده ٔ صبح <span class=\"hlight\">:</span> <br>دگر روز کز عطسه ٔ آفتاب <br>دمیدند کافور بر مشک ناب .<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">عطسه ٔ تیغ</span> ؛ کنایه از آوازی است که هنگام زدن تیغ برمی آید.(آنندراج ). کنایه از صدای شمشیر <span class=\"hlight\">:</span> <br>ز بس عطسه ٔ تیغ بر خون و خاک <br>دماغ هوا پر شد از جان پاک .<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">عطسه ٔ چاه </span> ؛ کنایه از صدائی باشد که از چاه بر می آید به سبب بانگ کردن در آن . (برهان ) (از انجمن آرا). صدای چاه، یعنی آوازی که چون بر چاه زنند از چاه برگردد. (آنندراج ).<br>- <span class=\"hlight\">عطسه ٔ روز</span> ؛ نتیجه و همانند روزدر روشنی و تابندگی <span class=\"hlight\">:</span> <br>خوش عطسه ٔ روزاست می ریحان نوروزاست می <br>دُرِّ شب افروز است می زان دُرّ شبستان تازه کن .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عطسه ٔ شب </span> ؛ کنایه از صبح صادق باشد. (برهان ). کنایه از صبح . (آنندراج ) (انجمن آرا).<br>جبهه زرین نمود طره ٔ صبح از نقاب <br>عطسه ٔ شب گشت صبح خنده ٔ صبح آفتاب .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عطسه ٔ شیشه </span> ؛ صدایی که هنگام ریختن شراب در ساغر و جز آن از شیشه برآید. (آنندراج ) <span class=\"hlight\">:</span> عطسه ٔ شیشه را نشئه ٔ صدای سلسبیل و صیحه ٔ بطک را تره ندای جبرئیل . (ملاطغرا، در انوار المشارق به نقل از آنندراج ).<br>- <span class=\"hlight\">عطسه ٔ صبح </span> ؛ کنایه از آفتاب عالمتاب است . (برهان ) (آنندراج ) (از انجمن آرا).<br>- <span class=\"hlight\">عطسه ٔ عنبرین </span> ؛ کنایه از بوی خوش است خواه از گل باشد خواه از چیزهای دیگر. (برهان ) (آنندراج ) <span class=\"hlight\">:</span> <br>چون ز دهان بلبله در گلوی قدح چکد<br>عطسه ٔ عنبرین دهد مغز زمانه از تری .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عطسه ٔ کمان </span> ؛ کنایه از تیر است . (آنندراج ) <span class=\"hlight\">:</span> <br>هر عطسه که از مغز کمان تو بر آید<br>ریزد به گریبان بقا خون عدم را.<br> <font color=\"Red\">عرفی (از آنندراج ).</font><br>- <span class=\"hlight\">عطسه ٔ گرز</span> ؛ کنایه از آواز پی هم زدن گرز است . (آنندراج ) <span class=\"hlight\">:</span> <br>چو عطسه باعث صحت بود چرا گردد<br>به نیم عطسه ٔ گرزت دماغ خصم سقیم .<br> <font color=\"Red\">مسیح کاشی (از آنندراج ).</font><br><BR><font color=\"Blue\">◄</font> کنایه از تربیت شده و مربی . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> اما ایاز... هرچند عطسه ٔ پدر ماست و از سرای دور نبوده است و گرم و سرد نچشیده و هیچ تجربتی نیفتاده است . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٦٥</span>). <BR><font color=\"Blue\">◄</font> در تداول عوام، نشانه ای است برای صبر کردن . (یادداشت مرحوم دهخدا).<br></font></div>'),
(184268, 'عطسه آور', '<span class=\"hlight\">عطسه آور.</span> <font color=\"DarkGreen\"><b>[ ع َ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ وَ]</font></b> (نف مرکب ) عطسه آورنده . آنچه باعث عطسه زدن شود.<br></font></div>'),
(184269, 'عطسه دادن', '<span class=\"hlight\">عطسه دادن .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ دَ ]</font></b> (مص مرکب ) عارض شدن و پدید گشتن عطسه و زفرافیدن . (ناظم الاطباء). عطسه کردن . عطسه زدن . عَطس . عُطاس . کداس . کدسة. کدسان . (از منتهی الارب ) <span class=\"hlight\">:</span> <br>شاخ چو آدم ز باد زنده شد و عطسه داد<br>فاخته الحمد خواند گفت که جاوید مان .<br> <font color=\"Red\">خاقانی .</font><br>از جگر جیش خان خاک زند جوش خون <br>عطسه ٔ خونین دهد بینی شیران ز شم .<br> <font color=\"Red\">خاقانی .</font><br>که آن مهربان ماه خسروپرست <br>به اقبال شه عطسه ای داد و رست .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(184270, 'عطسه دهنده', '<span class=\"hlight\">عطسه دهنده .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ دَ هََ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (نف مرکب ) عاطِس . (از منتهی الارب ). آنکه عطسه عارض او شود. رجوع به عطسه دادن شود.<br></font></div>'),
(184271, 'عطسه ریختن', '<span class=\"hlight\">عطسه ریختن .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ت َ ]</font></b> (مص مرکب ) عطسه تولید کردن <span class=\"hlight\">:</span> <br>هوا تا عطسه در مغز غزالان ختن ریزد<br>به دامان نسیم صبح زلف مشکسا بگشا.<br><font color=\"Red\">حزین (از آنندراج ).</font><br></font></div>'),
(184272, 'عطسه زدن', '<span class=\"hlight\">عطسه زدن .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ زَ دَ ]</font></b> (مص مرکب ) عطسه دادن . عطسه کردن <span class=\"hlight\">:</span> <br>گر تو از بوی مشک عطسه زنی <br>هر که حاضر دعات بسراید.<br> <font color=\"Red\">خاقانی .</font><br>یرحمک اﷲ زد آسمان که دم صبح <br>عطسه ٔ مشکین زد از صبای صفاهان .<br> <font color=\"Red\">خاقانی .</font><br>هر دم هزار عطسه ٔ مشکین زد از تری <br>مغز جهان ز رایحه ٔ عنبر سخاش .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عطسه زدن صبح </span>؛ کنایه از برآمدن آفتاب <span class=\"hlight\">:</span> <br>چون نافه ٔ مشک شب بسوزد<br>بس عطسه که آن زمان زند صبح .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(184273, 'عطسه کردن', '<span class=\"hlight\">عطسه کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ ک َ دَ ]</font></b> (مص مرکب ) عارض شدن عطسه . (فرهنگ فارسی معین ). عطسه دادن . عطسه زدن . خفیدن . زفرافیدن .<br></font></div>'),
(184274, 'عطش', '<span class=\"hlight\">عطش .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص )چیره گردیدن بر کسی در معاطشت . (از منتهی الارب ). چیره گردیدن بر کسی در نبرد در تشنگی . (ناظم الاطباء).<br></font></div>'),
(184275, 'عطش', '<span class=\"hlight\">عطش .</span> <font color=\"DarkGreen\"><b>[ ع َ طِ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ طُ ]</font></b> (ع ص ) تشنه . (منتهی الارب ). ج، عَطِشون <span class=\"hlight\" dir=\"rtl\">/</span> عَطُشون . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مکان عطش . جای کم آب . (منتهی الارب ). جای بی آب و یا کم آب . (از اقرب الموارد).<br></font></div>'),
(184276, 'عطش', '<span class=\"hlight\">عطش .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (اِخ ) (سوق الَ ...) از بزرگترین محله های بغداد، در جانب شرقی بین رصافه و نهر معلی بود. آن را سعید حرشی برای مهدی عباسی ساخت و بازرگانان را بدانجا منتقل کرد تا کرخ را ویران کند. (از معجم البلدان ). و رجوع به سوق العطش شود.<br></font></div>'),
(184277, 'عطش', '<span class=\"hlight\">عطش .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (ع مص ) تشنه گردیدن . (منتهی الارب ). تشنه شدن . (المصادر زوزنی ) (تاج المصادر بیهقی ) (دهار). ضد سیراب شدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اشتیاق یافتن . (از اقرب الموارد).<br></font></div>'),
(184278, 'عطش', '<span class=\"hlight\">عطش .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (ع اِمص ) تشنگی . (منتهی الارب ) (دهار) (غیاث اللغات ) (آنندراج ). ضد سیرابی، و یا آن دردی است که از عدم آشامیدن در گلو پدید آید. (از اقرب الموارد). احتیاج مفرط طبیعت به سردی و تری . (یادداشت مرحوم دهخدا). وِرد. (از المنجد) <span class=\"hlight\">:</span> <br>از تبش گشته غدیرش همچو چشم اعمشان <br>وز عطش گشته مسیلش چون گلوی اهرمن .<br> <font color=\"Red\">منوچهری .</font><br>هر که را از تف کینش عطشی داد قضا<br>جگرش ترنکند چرخ جز از آب حسام .<br> <font color=\"Red\">اوحدالدین انوری (از آنندراج ).</font><br>باش همراه من اندر روز و شب <br>تانبیند از عطش لشکر تعب .<br> <font color=\"Red\">مولوی .</font><br>هر چند ذکر آب عطش را مفید نیست <br>خوشتر ز وصف آتش در دفع التهاب .<br><font color=\"Red\">قاآنی .</font><br>- <span class=\"hlight\">عطش آوردن </span> ؛ تشنه کردن .<br>- <span class=\"hlight\">عطش داشتن </span>؛ تشنه بودن .<br>- <span class=\"hlight\">عطش را تسکین دادن </span> ؛ تشنگی را از بین بردن .<br>- <span class=\"hlight\">عطش را فرونشاندن </span> ؛ تشنگی را برطرف کردن .<br>- <span class=\"hlight\">عطش را منطفی کردن </span> ؛تشنگی را از بین بردن .<br>- <span class=\"hlight\">عطش را نشاندن </span> ؛ برطرف کردن تشنگی . مشروب کردن .<br>- <span class=\"hlight\">عطش سوزان </span>؛ التهاب .<br>- <span class=\"hlight\">عطش مفرط</span> ؛ التهاب .<br><BR><font color=\"Blue\">◄</font> در اصطلاح عرفان، کنایت از غلبت ولع به آرزوی خود و لقاء محبوب است و آن را سه درجه است :<br><span class=\"hlight\" dir=\"rtl\">١</span> - عطش مرید بسوی شاهدی که او را سیراب کند. <span class=\"hlight\" dir=\"rtl\">٢</span> - عطش سالک برای قطع صفتی از صفات نفس که او را از توجه به خدا محجوب کرده است و عطش او به روزی که در آن روز سیراب شود بواسطه ٔ نیل به مطلوب و محبوب . <span class=\"hlight\" dir=\"rtl\">٣</span> - عطش سالک به آنچه در محب است و محب عطشان است به آنچه بالاتر از آن است و در حقیقت عطش او به کشف حجاب و جلوه ای ازمحبوب است . (فرهنگ مصطلحات عرفانی از شرح منازل ).<br></font></div>'),
(184279, 'عطشات', '<span class=\"hlight\">عطشات .</span> <font color=\"DarkGreen\"><b>[ ع َ طِ ]</font></b> (ع ص، اِ) ج ِ عَطِشة. (منتهی الارب ). رجوع به عطشة شود.<br></font></div>'),
(184280, 'عطشان', '<span class=\"hlight\">عطشان .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (اِ) نوعی از خار است که آن را به تازی خس الکلب خوانند. (برهان ). نباتی است که به یونانی دیناقوس گویند. (اختیارات بدیعی ). نباتی است که آن را به یونانی دیناقوس نامند و به عربی خس الکلب و طرسک نامند. (مخزن الادویه ). دیفساقوس . (ابن البیطار). رجوع به دیفساقوس شود.<br></font></div>'),
(184281, 'عطشان', '<span class=\"hlight\">عطشان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ مص ) تشنه . (منتهی الارب ) (برهان ) (دهار) (غیاث اللغات ). دارای عطش، و مؤنث آن عَطشی ̍ و عطشانة آید. (از اقرب الموارد). ج، عِطاش و عَطشی ̍. عَطاشی ̍.عُطاشی ̍. (منتهی الارب ) (از اقرب الموارد). و اصل آن را عطشاء دانسته اند. رجوع به عطشاء شود <span class=\"hlight\">:</span> <br>به طمعجاه به نزدیک او نهادم روی <br>چنانکه روی به آب روان نهد عطشان .<br> <font color=\"Red\">فرخی .</font><br>خوان پیش تو است لیکن از جهل <br>تو گرسنه ای بر او و عطشان .<br> <font color=\"Red\">ناصرخسرو.</font><br>گر مرا چشمه ایست هر چشمی <br>لب خشکم چرا چو عطشانیست .<br> <font color=\"Red\">مسعودسعد.</font><br>جز تشنگی خنجر خونخوار تو گیتی <br>همکاسه کجا دید فنای عطشان را.<br> <font color=\"Red\">انوری (از آنندراج ).</font><br>سالکان را که چو دریا همه سرمستانند<br>چون صدف غرفه ٔ عطشان به خراسان یابم .<br> <font color=\"Red\">خاقانی .</font><br>نان تو چو قطره ٔ ربیع است <br>و احرار صدف مثال عطشان .<br> <font color=\"Red\">خاقانی .</font><br>جمله در غرقاب اشک و کرده هم سیراب از اشک <br>خاک غرقاب مصحف را که عطشان دیده اند.<br> <font color=\"Red\">خاقانی .</font><br>امیدم هست اگر عطشان نمیرد<br>که بازآید به جوی رفته آبی .<br> <font color=\"Red\">سعدی .</font><br>- عطشان نطشان ؛ از اتباع است . (منتهی الارب ) (از اقرب الموارد). بسیار تشنه . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آزمند چیزی . (منتهی الارب ). مشتاق . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> تشنگی . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> (اِخ ) نام شمشیر عبدالمطلب بن هاشم است . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184282, 'عطشانات', '<span class=\"hlight\">عطشانات .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) ج ِ عَطشانة.(منتهی الارب ) (اقرب الموارد). رجوع به عطشانة شود.<br></font></div>'),
(184283, 'عطشانة', '<span class=\"hlight\">عطشانة.</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ ]</font></b> (ع ص ) مؤنث عطشان . (منتهی الارب ) (اقرب الموارد).زن تشنه . (ناظم الاطباء). عَطشی ̍. ج، عطشانات . (منتهی الارب ) (اقرب الموارد). رجوع به عطشان و عطشی شود.<br></font></div>'),
(184284, 'عطشانی', '<span class=\"hlight\">عطشانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (حامص ) تشنگی . (فرهنگ فارسی معین ).<br></font></div>'),
(184285, 'عطشی', '<span class=\"hlight\">عطشی .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (اِخ ) احمدبن عبیداﷲبن محمدبن حمزه ٔ عطشی بغدادی، مکنی به ابوبکر. محدث بود و از ابوسعید اعرابی و دیگران روایت کرده است . و ابوالحسن محمدبن احمد جوالیقی کوفی به سال <span class=\"hlight\" dir=\"rtl\">٣٥٩</span> هَ .ق . نزد او حدیث آموخته است . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(184286, 'عطشی', '<span class=\"hlight\">عطشی .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (ص نسبی ) منسوب به سوق العطش بغداد که برخی از محدثان به آنجا نسبت دارند. (از اللباب فی تهذیب الانساب ). رجوع به عطش (سوق العطش ) شود.<br></font></div>'),
(184287, 'عطشی', '<span class=\"hlight\">عطشی .</span> <font color=\"DarkGreen\"><b>[ ع َ شا ]</font></b> (ع ص ) مؤنث عَطشان . (منتهی الارب ) (از اقرب الموارد). عطشانة. زن تشنه . ج، عِطاش . (اقرب الموارد).<br></font></div>'),
(184288, 'عطط', '<span class=\"hlight\">عطط.</span> <font color=\"DarkGreen\"><b>[ ع ُ طُ ]</font></b> (ع اِ) چادرهای شکافته و مقطوع . (منتهی الارب ). چادرهای گشاده و مقطوع و ملحفه های مقطع. (ناظم الاطباء). ملحفه هایی که از طول یا از عرض بریده باشد. (از اقرب الموارد).<br></font></div>'),
(184289, 'عطعط', '<span class=\"hlight\">عطعط.</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (ع اِ) بچه ٔ یک ساله ٔ گوسپند یا بزغاله ٔ نر یا خرکره . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184290, 'عطف', '<span class=\"hlight\">عطف .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ)کرانه و جانب . (از منتهی الارب ). جانب هر چیز. (از اقرب الموارد). یک سوی گردن و یک سوی مردم . (دهار). جانب . (ترجمان القرآن جرجانی ). عطفاالرجل ؛ دو جانب شخص . (از منتهی الارب ). دو جانب و دو سوی شخص از سر و تارک . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بغل . (منتهی الارب ). اِبط. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> عطف القوس ؛ گوشه ٔ کمان . (منتهی الارب ). «سیة» در کمان . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تعرج الفرس فی عطفیه ؛ آن اسب به چپ و راست خود خم شد. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عطف الطریق ؛ بر سوی راه . (منتهی الارب ). «قارعة» و میان راه . (از اقرب الموارد)، تنَّح عن عطف الطریق ؛ از میان راه دور شو. (از منتهی الارب ) (از اقرب الموارد). عَطف . و رجوع به عَطف شود. <BR><font color=\"Blue\">◄</font> هو ینظر فی عطفیه ؛ یعنی او معجب و خودپسند است . (از اقرب الموارد). و آن اشاره است به اعجاب او، یعنی او در شگفت است به نفس یا به لباس خویش . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> جاء ثانی عطفه ؛ بیامد با فراخی حال یا گردن پیچان یا متکبرانه و اعراض کنان . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ثنی عنی عطفه ؛ روی گردانید و بازگشت . (از منتهی الارب ). اعراض کرد و جفا نمود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> هر چه از جسد و بدن که خم شود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دوش . (مهذب الاسماء). ج، أعطاف و عِطاف و عُطوف . (اقرب الموارد).<br></font></div>'),
(184291, 'عطف', '<span class=\"hlight\">عطف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) میل کردن . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مهربانی کردن بر کسی . (از منتهی الارب ) (المصادر زوزنی ) (تاج المصادر بیهقی ) (دهار) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دوتا کردن . (از منتهی الارب ). به دو درآوردن . (المصادر زوزنی ) (دهار) تاکردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> حمله نمودن برکسی و بازگشتن . (از منتهی الارب ). حمله کردن . (المصادر زوزنی ) (از تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> خم دادن چوب . (از منتهی الارب ). برگردانیدن چوب و جز آن . (تاج المصادر بیهقی ). برگردانیدن . (دهار). بگردانیدن .(المصادر زوزنی ). <BR><font color=\"Blue\">◄</font> پیچیدن جامه . (از منتهی الارب ). پیچیدن . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> بازگشتن و منصرف شدن . (از اقرب الموارد). برگردیدن . (تاج المصادر بیهقی ) (دهار). <BR><font color=\"Blue\">◄</font> بگردانیدن . (المصادر زوزنی ). <BR><font color=\"Blue\">◄</font> بازداشتن و دور کردن ازحاجت، گویند: عطف فلاناً عن حاجته . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> برگرداندن سر شتر را بسوی خود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مهربان و رحیم کردن : عطف اﷲ بقلب السلطان علی رعیته . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> در اصطلاح نحو سخن را بر سخن بازگردانیدن، اولی را معطوف علیه و دوم را معطوف گویند. (از منتهی الارب ). کلمه ای را تابع کلمه ٔ دیگر کردن بوسیله ٔ حروف عطف . (از اقرب الموارد). سخنی را به سخنی دیگر بازگردانیدن . (یادداشت مرحوم دهخدا). سخن را با سخن بازگردانیدن . (آنندراج ). تالی قرار دادن کلمه را بر کلمه ٔ دیگر بوسیله ٔ حرف عطف . (از اقرب الموارد). هر گاه کلمه یا جمله ای به ماقبل خود ربط داده شود آن را عطف گویند. و این عطف چون بوسیله ٔ یکی از حروف دهگانه ٔ عطف صورت گیرد آن را عطف نسق نیز نامند زیرا با متبوع خود بر یک نسق و روش است ماقبل حرف عطف را معطوف علیه و مابعد حرف عطف را معطوف نامند. و معطوف تابعی است که در حکم معطوف علیه است و آن ممکن است عطف لاحق بر سابق باشد مانند: و لقد أرسلنا نوحا و ابراهیم، و یا عطف سابق بر لاحق است مانند: و کذلک یوحی الیک والذین من قبلک، و یا عطف مصاحب بر مصاحب است مانند: فنجّیناه و أصحاب السفینة. توضیح اینکه عطف کردن بر ضمیر منفصل و ضمیر متصل منصوب، مانند سایر اسماء ظاهر، جایز است، ولی عطف کردن بر ضمیر متصل مرفوع یا ضمیر مستتر جایز نیست جز اینکه میان آنها فاصله اندازند. این فاصله ممکن است ضمیر منفصل باشد چون : کنتم انتم و آباؤکم و «اسکن انت و زوجک الجنة» و یا غیر ضمیر باشد مانند: «ما أشرکنا و لا آباؤنا» (از کشاف اصطلاحات الفنون و فرهنگ علوم نقلی، به نقل از مغنی و هدایة و سیوطی و مختصر المعانی ). و رجوع به حروف عطف در ترکیبات عطف شود.<br>- <span class=\"hlight\">حروف عطف </span> ؛ حروفی که کلمه ای را به کلمه ٔماقبل ربط دهند مانند «و» در «حسن و حسین آمدند». (فرهنگ فارسی معین ). و آن را در تداول فارسی غالباً حروف ربط نامند. رجوع به حرف ربط شود.<br>- <BR><font color=\"Blue\">◄</font> در اصطلاح صرف عربی، حروفی است که بوسیله ٔ آن کلمه یا جمله ای را بر ماقبل عطف دهند و آنها ده حرف هستند: وَ (و)، ف َ (پس )، ثم ّ (سپس )، حتّی (حتی )، أو (یا)، أم (یا)، أما (اما)، لا (نه )، بل (بلکه )، لکْن (ولی ). «الا» نیز گاهی از حروف عطف بشمار آید. (از کشاف اصطلاحات الفنون ).<br></font></div>'),
(184292, 'عطف', '<span class=\"hlight\">عطف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) عطف الطریق ؛ بر سوی راه . گویند تنح عن عطف الطریق ؛ یعنی از میانه ٔ راه دور شو. (از منتهی الارب ) (از اقرب الموارد). عِطف . و رجوع به عِطف شود. <BR><font color=\"Blue\">◄</font> کژی و انحناء. گویند فی الطریق عطف . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) میل . (ناظم الاطباء). تمایل . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> مهربانی . (دهار) (غیاث اللغات ) (ناظم الاطباء). محبت . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> پیچیدگی و برگشتگی . (ناظم الاطباء) (فرهنگ فارسی معین ). خمیدگی <span class=\"hlight\">:</span> <br>نه به دستش در، خم و نه به پایش در، عطف <br>نه به پشتش در، پیچ و نه به پهلو در، ماز.<br> <font color=\"Red\">منوچهری .</font><br>چو بدر از جیب گردون سر برآورد<br>زمین عطف هلالی بر سر آورد.<br> <font color=\"Red\">نظامی .</font><br>چو خورشید پوشد جمال از جهان <br>پس عطف آن آب گردد نهان .<br> <font color=\"Red\">نظامی .</font><br>سرانجام کان ره به پایان رسید<br>دگر باره شدعطف دریاپدید.<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">عطف به چیزی </span> ؛ بازگرداندن و بازگشت دادن به آن، چنانکه در نامه های جوابی نویسند آن گاه که سخن را به موضوع نامه ٔ واصله برگردانند. رجوع به عطف کردن شود.<br>- <span class=\"hlight\">عطف بماسبق </span> ؛ بازگرداندن به چیزی که گذشته است .<br>- <span class=\"hlight\">عطف بماسبق نمودن قانون </span> ؛ تأثیر قانون نسبت بماقبل تاریخ انتشار خود که بصورت اصل «عدم عطف قانون بماسبق » مشهور است چه نفوذ قانون محدود به تاریخ انتشار تا روز نسخ آن است ونسبت به ایام ماقبل انتشار تأثیری ندارد مگر اینکه نص قانون آن را استثناء کند. و در اصطلاح حقوق یک عنصری، حق حاکمیت ملت مقتضی است که قانونگزار با رعایت اصل عدم محرومیت اکثر، وضع قانون نماید، خواه این قانون عطف به گذشته بکند یا نه، بنابراین عدم عطف قانون بماسبق استثناء بر حق حاکمیت ملت است . نهایت اینکه این استثناء بقدری دامنه ٔ وسیع دارد که خود بصورت یک قاعده ٔ حقوقی درآمده است . (از فرهنگ حقوقی ).<br>- <span class=\"hlight\">عطف دامن </span> ؛ فرود دامن . فراویز جامه . (آنندراج ). سجاف دامن . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>حجاب نبود تیغ ترا به خصم تو در<br>ز گوی مغفر تا عطف دامن جوشن .<br> <font color=\"Red\">سوزنی .</font><br>جیب من بر صدره ٔخارا عتابی شد ز اشک <br>کوه خارا زیر عطف دامن خارای من .<br> <font color=\"Red\">خاقانی .</font><br>سر زلف در عطف دامن کشان <br>ز چهره گل از خنده شکرفشان .<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">عطف قَبا</span> ؛ عطف دامن . فرود قبا <span class=\"hlight\">:</span> <br>در کمر چست کرد عطف قبا<br>در دم شیر شد چو باد صبا.<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> (اِ) سجاف دامن جامه . (غیاث اللغات ). سجاف جامه . (ناظم الاطباء). و رجوع به ترکیب عطف دامن شود. <BR><font color=\"Blue\">◄</font> در اصطلاح صحافی، چرم یا کاغذ یا جامه ای که از بن سوی دو دفه ٔ کتاب را بهم پیوندد. (یادداشت مرحوم دهخدا). قسمت زیرین جلد کتاب که دو رویه ٔ جلد را به یکدیگر متصل می سازد. (فرهنگ فارسی معین ). و رجوع به عطف و گوشه در ترکیبات عطف شود.<br>- <span class=\"hlight\">عطف و گوشه </span> ؛ یکی از روشهای صحافی است بدین طریق که پوشش روی شیرازه ٔ کتاب و زاویه های جلد کتاب را از تیماج (و غالباً به رنگی جز رنگ جلد) سازند استواری بیشتر را، و جلد کتاب را از مقوای ساده یا کالینگر می سازند. (فرهنگ فارسی معین ).<br></font></div>'),
(184293, 'عطف', '<span class=\"hlight\">عطف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) (ذوالَ ...) جایگاهی است در نجد و نام آن در شعر یزیدبن طثریة آمده است . (از معجم البلدان ).<br></font></div>'),
(184294, 'عطف', '<span class=\"hlight\">عطف .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (ع اِمص ) درازی پلک . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) گیاهی است که بر درخت پیچد و آن را برگ نباشد، یکی آن عطفة است . و برخی آن را همان لبلاب دانسته اند. (از اقرب الموارد). رجوع به عَطَفَة شود.<br></font></div>'),
(184295, 'عطف', '<span class=\"hlight\">عطف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ عَطوف . (منتهی الارب ). رجوع به عطوف شود. <BR><font color=\"Blue\">◄</font> ج ِ عاطف . (منتهی الارب ) (اقرب الموارد). رجوع به عاطف شود. <BR><font color=\"Blue\">◄</font> ج ِ عِطاف . (منتهی الارب ) (اقرب الموارد). رجوع به عِطاف شود.<br></font></div>'),
(184296, 'عطف بیان', '<span class=\"hlight\">عطف بیان .</span> <font color=\"DarkGreen\"><b>[ ع َ ف ِ ب َ ]</font></b> (ترکیب اضافی، اِ مرکب ) در اصطلاح نحو، تابعی است غیر از صفت که متبوع خود را توضیح دهد، چون ابوحفص عمر، که عمر عطف بیان است ابو را. (از تعریفات جرجانی ). چیزی است که متبوع را واضح و روشن کند و فرقش با صفت آن است که صفت مشتق باشد و عطف بیان مشتق یا مؤول به مشتق نباشد. و حق عطف بیان آن است که زیادتی توضیح را برای متبوع خود افاده کند مانند «ذکرت اﷲ فی الواد المقدس طُوی » و آنچه صالح است که بدل شود تواند که عطف بیان شود مانند قدم صدیقک خالد. و گاهی در لفظبا بدل اشتباه شود هر چند آن را با بدل فرقهایی است که در کتب صرف مذکور است . (از کشاف اصطلاحات الفنون و فرهنگ علوم نقلی، به نقل از مغنی و سیوطی و مختصر المعانی ). <BR><font color=\"Blue\">◄</font> در اصطلاح دستور زبان فارسی، چون دو لفظ در یک جمله بی حرف عطف با هم آیند و لفظ دوم در انتساب چیزی تابع اول، و مقصود اصلی در انتساب، لفظ اول باشد و ذکر دوم فقط برای افاده ٔ تفسیر و بیان بود، لفظ دوم را عطف بیان و اول را مبین نامند وحرف آخرش ساکن بود. عطف بیان مشابه به صفت است یعنی چنانکه صفت موصوف را واضح گرداند عطف بیان نیز متبوع را توضیح دهد اما صفت برای تعریف یا تخصیص آید و عطف بیان فقط برای تفسیر و بیان آید. مثال از سعدی :<br>و گر به چشم ارادت نگه کند بر دیو<br>فرشته اش بنماید به چشم کروبی .<br>که در عبارت فوق «کروبی » عطف بیان است برای «فرشته ». (فرهنگ فارسی معین ).<br></font></div>'),
(184297, 'عطف نسق', '<span class=\"hlight\">عطف نسق .</span> <font color=\"DarkGreen\"><b>[ ع َ ف ِ ن َ س َ ]</font></b> (ترکیب اضافی، اِ مرکب ) در اصطلاح علم نحو، عبارت است از عطف به حرف . (کشاف اصطلاحات الفنون ). رجوع به عطف (در معنی مصدری ) شود.<br></font></div>'),
(184298, 'عطف کردن', '<span class=\"hlight\">عطف کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ دَ ]</font></b> (مص مرکب ) روی برگردانیدن . برگشتن . از سویی گشتن و سوی دیگر روی کردن <span class=\"hlight\">:</span> بر آن بود که عطفی کند بر جانب کالف تا راه آموی گیرد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٣٢</span>).<br>- <span class=\"hlight\">عطف زمام کردن و عطف عنان کردن </span> ؛ سر ستور را برگردانیدن و برگشتن . (ناظم الاطباء) (فرهنگ فارسی معین ).<br> <BR><font color=\"Blue\">◄</font> سخن را به سخنی بازگردانیدن . سخنی را به سخنی بستن با حرفی چون واو و امثال آن . (یادداشت به خط مرحوم دهخدا). رجوع به عطف (مص ) شود. <BR><font color=\"Blue\">◄</font> کنایه از روی برگردانیدن باشد، خواه به خشم و ناز و خواه به قهر و غضب . (برهان ). کنایه از یک طرف شدن . (آنندراج ). کنایه از رو برگردانیدن است به خشم و قهر. (انجمن آرا) <span class=\"hlight\">:</span> <br>عطف کنم لیک از بیم کس <br>از پی تعظیم شکوه تو بس .<br><font color=\"Red\">میرخسرو (از آنندراج ).</font><br></font></div>'),
(184299, 'عطفان', '<span class=\"hlight\">عطفان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) تثنیه ٔ عِطف . رجوع به عِطف شود.<br></font></div>'),
(184300, 'عطفة', '<span class=\"hlight\">عطفة.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع اِ) اسم المرة است از مصدر عطف . رجوع به عطَف شود. <BR><font color=\"Blue\">◄</font> در فن تربیت اسب این کلمه به معنی نوعی بازگردانیدن ناگهانی اسب، به هنگام دوانیدن آن، مصطلح بوده است <span class=\"hlight\">:</span> مهترپیلبانان را مثال داد تا او را ریاضت دهد و آداب کرّ و فرّ و حرکت و سکون و ناورد و جولان و عطفه و حمله در وی آموزد. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٥٧</span>). بداند که عطفه ها چه باشد که دل به سوار دهد. (از آداب الحرب و الشجاعةچ سهیلی ص <span class=\"hlight\" dir=\"rtl\">٢١٤</span>). اگر شمشیر را تازد هر دوپای او نرم تر کند و عطفه بر او تنگتر کند. (همان متن ص <span class=\"hlight\" dir=\"rtl\">٢١٥</span>).<br>- <span class=\"hlight\">عطفه کردن </span> ؛ در تداول جنگهای قدیم، ناگهان بازگشتن سوار و یا کژ بر دشمن تاختن <span class=\"hlight\">:</span> لشکر سلطان عطفه کردند و همه را مضاجع قتل در خواب نوشین بخوابانیدند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٩٥</span>). طاهر عطفه کرد و به ضربه او را از مرکب بینداخت . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٩٩</span>). نزدیک بود که فتحی برآید اما ابوعلی و فایق عطفه کردند و تقدیر باری تعالی موافق مراد ایشان آمد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١١٧</span>). مصاف دادند لشکر مغول عطفه کردند و با بشریه آمدند از ناحیه ٔ دجیل . (جامع التواریخ رشیدی ).<br><BR><font color=\"Blue\">◄</font> مهره ای است افسون را که بدان زنان مردان را بند کنند از زنان دیگر. (از منتهی الارب ). مهره ای است که زنان بوسیله ٔ آن مردان را متمایل می کنند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درختی است که بدان شاخ انگور آویخته باشد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184301, 'عطفة', '<span class=\"hlight\">عطفة.</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ف َ ]</font></b> (ع اِ) گیاهی است بی شاخ و برگ که بر درخت می پیچد و گاوان می خورند آنرا، و برخی از ریشه های آن را چون بر زن «فارک » و دشمن دارنده ٔ شوی بپاشند، زوج خود را دوست خواهد داشت . (از منتهی الارب ). یک دانه ٔ عَطَف گویند، همان لبلاب است . (از اقرب الموارد). و رجوع به عَطَف شود. گیاهی است از تیره ٔ پنیرکیان که بعضی انواع آن بصورت درختچه و برخی بصورت درخت می باشند. برگهایش کامل و آرایش گلها بصورت آرایش گرزن است . در حدود <span class=\"hlight\" dir=\"rtl\">٣٠</span> نوع از این گیاه شناخته شده است . گشت برگشت . برگشت . کست بر کست . سوادالهند. سوادالسند. سوادالاکراد. (فرهنگ فارسی معین ).<br></font></div>'),
(184302, 'عطفة', '<span class=\"hlight\">عطفة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ف َ ]</font></b> (ع ص ) اسم النوع است ازمصدر عطف . (از اقرب الموارد). رجوع به عطف شود. <BR><font color=\"Blue\">◄</font> به معنی عَطفة است . (از منتهی الارب ). رجوع به عَطفة شود. <BR><font color=\"Blue\">◄</font> شاخه های انگور که بر آن درخت آویخته باشد. (منتهی الارب ). اطراف مو که آویخته باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درخت عَصبة. (منتهی الارب ) (از اقرب الموارد). رجوع به عصبة شود.<br></font></div>'),
(184303, 'عطفل', '<span class=\"hlight\">عطفل .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (اِ) بیدمشک . (الفاظ الادویة).بهرامج . (تحفه ٔ حکیم مؤمن ). بیدمشک را گویند و آن بهار درخت نوعی از بید باشد. (برهان ). گفته اند صغوفراست و گفته اند بهرامج است که خلاف بلخی، و به فارسی بیدمشک نامند. (مخزن الادویه ). رجوع به بیدمشک شود.<br></font></div>'),
(184304, 'عطفگاه', '<span class=\"hlight\">عطفگاه .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِ مرکب ) محل پیچیدن . جای پیچیدگی .<br>- <span class=\"hlight\">عطفگاه زمین </span> ؛ کنایه از منتهای زمین که دریای محیط متصل آن است . (آنندراج ). کناره ٔ زمین و حوالی قطب <span class=\"hlight\">:</span> <br>سوی عطفگاه زمین تاختند<br>در آن سایبان رایت افراختند.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(184305, 'عطفی', '<span class=\"hlight\">عطفی .</span> <font color=\"DarkGreen\"><b>[ ع َ فا ]</font></b> (ع ص ) خمیده و معطوف . قوس عطفی یعنی کمان خمیده و معطوف . (از اقرب الموارد).<br></font></div>'),
(184306, 'عطل', '<span class=\"hlight\">عطل .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (ع اِمص ) خالی بودن اززیور و حلی، و گاهی در مطلق خالی بودن از هر چیزی به کار رود. (از اقرب الموارد). خالی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) کالبد. (منتهی الارب ). شخص . (اقرب الموارد). گویند: ما أحسن عطله ؛ یعنی قامت او و اعتدال و درازی آن چه نیکوست . (از منتهی الارب ) (از اقرب الموارد). طَلل َ. و رجوع به طلل شود. <BR><font color=\"Blue\">◄</font> گردن . (منتهی الارب ). عنق . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> خوشه ٔ خرما. (منتهی الارب ). «شمراخ » در نخل . (از اقرب الموارد). ج، أعطال . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(184307, 'عطل', '<span class=\"hlight\">عطل .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (ع مص ) بی پیرایه ماندن زن . (از منتهی الارب ). بی پیرایه شدن . (المصادر زوزنی ). خالی شدن زن از زیور. (تاج المصادر بیهقی ) (دهار): عطلت المراءة؛ بر آن زن زیور نبوده است . (از اقرب الموارد). عُطول . و رجوع به عطول شود. <BR><font color=\"Blue\">◄</font> خالی شدن از مال و ادب . (از منتهی الارب ) (تاج المصادر بیهقی ) (دهار): عطل من المال والادب ؛ از مال و ادب خالی و تهی شد، و نیز عطل القوس من الوتر و الخیل من الارسان و الدلو من الاوذام ؛ کمان از وتر و اسب از افسار و دلو از بند و تسمه خالی گشت . (از اقرب الموارد). بنابراین عطل، در خالی بودن از هر چیز به کار رود هر چند اصل آن در موردزیور و حلی است . <BR><font color=\"Blue\">◄</font> فربه گردیدن . (از منتهی الارب ). بزرگ و عظیم شدن بدن . (از اقرب الموارد).<br></font></div>'),
(184308, 'عطل', '<span class=\"hlight\">عطل .</span> <font color=\"DarkGreen\"><b>[ ع َ طِ ]</font></b> (ع ص ) نیکو جسم و تن، از شتران . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زن بی پیرایه . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> حرف بی نقطه مثل دال و سین و لام و میم . (غیاث اللغات ).<br></font></div>'),
(184309, 'عطل', '<span class=\"hlight\">عطل .</span> <font color=\"DarkGreen\"><b>[ ع ُ<span class=\"hlight\" dir=\"rtl\">/</span> ع ُ طُ ]</font></b> (ع ص ) زن بی پیرایه ٔ بی زیور. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اسب و شتر بی گردن بند و بی رسن و بی داغ و نشان . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد بی ساز و سلاح . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خالی از مال . <BR><font color=\"Blue\">◄</font> بی ادب . <BR><font color=\"Blue\">◄</font> قوس عطل ؛ کمان بی زه . (منتهی الارب ) (از اقرب الموارد). ج، أعطال . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(184310, 'عطل', '<span class=\"hlight\">عطل .</span> <font color=\"DarkGreen\"><b>[ ع ُطْ طَ ]</font></b> (ع ص، اِ) ج ِ عاطِل . (منتهی الارب ) (اقرب الموارد). رجوع به عاطل شود.<br></font></div>'),
(184311, 'عطلات', '<span class=\"hlight\">عطلات .</span> <font color=\"DarkGreen\"><b>[ ع َ طِ ]</font></b> (ع ص، اِ) ج ِ عَطِلَة. (منتهی الارب ). رجوع به عَطلة شود.<br></font></div>'),
(184312, 'عطلب', '<span class=\"hlight\">عطلب .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) قاتل ابیه است . (فهرست مخزن الادویه ). عطوب . و رجوع به عطوب شود.<br></font></div>'),
(184313, 'عطلة', '<span class=\"hlight\">عطلة.</span> <font color=\"DarkGreen\"><b>[ ع َ طِ ل َ ]</font></b> (ع ص ) شتر نیکواندام . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شترماده ٔ گزیده . (منتهی الارب ). ناقه ٔ صفی ّ و برگزیده . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گوسپند بسیارشیر. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دلو دوال بریده ٔ گوشه شکسته . (منتهی الارب ). دلوی که «وذم » و تسمه ٔ آن بریده باشد. (از اقرب الموارد).<br></font></div>'),
(184314, 'عطلة', '<span class=\"hlight\">عطلة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ]</font></b> (ع اِمص ) بیکاری، اسم است تعطل را. (منتهی الارب ). بیکاری . (دهار). باقی ماندن بدون عمل و کار. (از اقرب الموارد). عطلت . رجوع به عطلت شود. <BR><font color=\"Blue\">◄</font> بی پیرایگی زن . (منتهی الارب ).<br></font></div>'),
(184315, 'عطلت', '<span class=\"hlight\">عطلت .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ]</font></b> (ع اِمص ) عطلة. بیکاری . (غیاث اللغات ). عطالت . بطالت . بیکاری .تعطل . (یادداشت به خط مرحوم دهخدا) <span class=\"hlight\">:</span> اتفاق خوب چنین افتاد... که خواجه ابوسعید... مرا در این بیغوله ٔ عطلت بازجست . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٧١</span>). طاهر از چشم امیر بیفتاد و آبش تیره شد چنانکه ... در عطلت گذشته شد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٤٩</span>). و رجوع به عطلة شود.<br>- <span class=\"hlight\">در عطلت ماندن </span> ؛ بیکار ماندن . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> چون مدتی سخت دراز در عطلت ماند پایمردان خاستند... تا دل مأمون را نرم کردند بر وی .(تاریخ بیهقی ).<br></font></div>'),
(184316, 'عطلس', '<span class=\"hlight\">عطلس .</span> <font color=\"DarkGreen\"><b>[ ع َ طَل ْ ل َ ]</font></b> (ع ص ) درازبالا. (منتهی الارب ). طویل . (اقرب الموارد).<br></font></div>'),
(184317, 'عطم', '<span class=\"hlight\">عطم .</span> <font color=\"DarkGreen\"><b>[ ع ُ طُ ]</font></b> (ع ص ) هلاک شدگان . واحد آن عطیم و عاطم است . (از منتهی الارب ) (اقرب الموارد). و رجوع به عاطم و عطیم شود.<br></font></div>'),
(184318, 'عطم', '<span class=\"hlight\">عطم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) پشم رنگین زده . (منتهی الارب ). پشم زده شده . (از اقرب الموارد) (از مخزن الادویه ). <BR><font color=\"Blue\">◄</font> (اِخ ) نام جایگاهی است . (از معجم البلدان ) (از منتهی الارب ).<br></font></div>'),
(184319, 'عطموس', '<span class=\"hlight\">عطموس .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) زن نیکوصورت . زن خوب شکل درازبالا پرگوشت نازاینده . (منتهی الارب ) (از اقرب الموارد). عَیطَموس . و رجوع به عیطموس شود. <BR><font color=\"Blue\">◄</font> زن تمام اندام . <BR><font color=\"Blue\">◄</font> شتر قوی هیکل تمام خلقت . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) حمار الوحش . (مخزن الادویه ). اسم عربی حمار وحشی است . (تحفه ٔ حکیم مؤمن ).<br></font></div>'),
(184320, 'عطن', '<span class=\"hlight\">عطن .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (ع اِ) خوابگاه شتران بر حوض، و آن جز بر آب نباشد. (از منتهی الارب ). جای آب خوردن شتران . (غیاث اللغات ). آرامگاه ستوران در کنار آب . (فرهنگ فارسی معین ). «مناخ » و استراحتگاه شتران در اطراف «ورد» و نوبت آب و اگر در جایی دیگر باشد آن را مراح و مأوی گویند. (از اقرب الموارد) <span class=\"hlight\">:</span> <br>از عدل او آرام یابد همی <br>با شیرشرزه اشتر اندر عطن .<br> <font color=\"Red\">فرخی .</font><br>مجلس اوستاد تو چون آتش افروخته است <br>تو چنان چون اشتر بی خواستار اندر عطن .<br> <font color=\"Red\">منوچهری .</font><br> <BR><font color=\"Blue\">◄</font> خوابگاه . مأوی <span class=\"hlight\">:</span> تا نماز شام که پیل از گرسنگی فتور پذیرفت و به علف محتاج گشت، روی به عطن معهود ووطن مألوف نهاد. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>)<br>در کف او نرمه جاروئی که من <br>خانه را میروفتم بهر عطن .<br> <font color=\"Red\">مولوی .</font><br> <BR><font color=\"Blue\">◄</font> آغل گوسپندان نزدیک آب . (منتهی الارب ). آرامگاه گوسپندان نزدیک آب . (غیاث اللغات ). آغل و «مربض » گوسفندان در اطراف آب، تا پس از تشنگی دوباره آب خورند، و هرگاه به اندازه ٔ کافی آب برگرفتند به چراگاههاو «ظم ء» باز گردانده می شوند. (از اقرب الموارد). ج، أعطان . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> رجل رحب العطن و البلد؛ مرد بسیار شتر فراخ دست و توانگر. (از منتهی الارب ) (از اقرب الموارد). مقابل رجل ضیق العطن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ضربوا بعطن ؛ یعنی سیراب گردیده جای گرفتند بر آب . (منتهی الارب ). آنان سیراب شدند سپس نزدیک آب اقامت کردند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دامن کوه . (لغت فرس اسدی ) <span class=\"hlight\">:</span> <br>چون با دو چون آب روان، دردشت و در وادی دوان <br>چون آتش وخاک گران، در کوهسار و در عطن .<br><font color=\"Red\">معزی .</font><br></font></div>'),
(184321, 'عطن', '<span class=\"hlight\">عطن .</span> <font color=\"DarkGreen\"><b>[ ع َ طِ ]</font></b> (ع ص ) پوستی که در دباغ قرار داده شده و تباه و بدبوی گردیده است . (از اقرب الموارد). عَطین . رجوع به عَطَن (مص ) و عطین شود.<br></font></div>'),
(184322, 'عطن', '<span class=\"hlight\">عطن .</span> <font color=\"DarkGreen\"><b>[ ع َطَ ]</font></b> (ع مص ) انداخته شدن پوست در دباغ تا گنده و بدبوی گردیدن و تباه شدن، و یا آب پاشیده دفن گردیده شدن تا پشم نرم گردد و برکنده شود. (از منتهی الارب ): عطن الجلد؛ پوست در دباغ قرار داده شد و باقی گذاشته شد تا تباه گردد و بدبوی شود، و گویند آب بر آن پاشیده آن را دفن کرد تا مویش نرم شود و برکنده شود، و چنین پوستی را عَطِن گویند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گنده شدن پوست در پیراستن . (از منتهی الارب ). پوسیده شدن پوست در پیراستن . (تاج المصادر بیهقی ).<br></font></div>'),
(184323, 'عطن', '<span class=\"hlight\">عطن .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) در دباغ نهادن پوست را جهت دباغت، یا ترکرده دفن نمودن تا موی از وی بریزد. (از منتهی الارب ): عطن الجلدَ؛ پوست را در غلقة، که گیاهی است، و یا در سرگین و نمک انداخت و روی آن را پوشاند تا پشم آن بریزد و نرم شود، سپس آن را در دباغ نهاد و چنین پوستی را عطین و معطون گویند. (از اقرب الموارد).<br></font></div>'),
(184324, 'عطنة', '<span class=\"hlight\">عطنة.</span> <font color=\"DarkGreen\"><b>[ ع َ طِ ن َ ]</font></b> (ع ص ) پوستی که در دباغ قرار داده شده و تباه و بدبوی گردیده است . (از اقرب الموارد). رجوع به عَطَن (مص ) شود.<br>- <span class=\"hlight\">امثال </span> :<br><span class=\"hlight\">ما هو الا عطنة</span> ؛ آن را در مورد شخص پلید گویند از نظر بدبویی وی . (از اقرب الموارد). رجوع به عَطینة شود.<br></font></div>'),
(184325, 'عطنة', '<span class=\"hlight\">عطنة.</span> <font color=\"DarkGreen\"><b>[ ع َ طَن َ ]</font></b> (ع اِمص ) اسم مصدر است اعطان را، به معنی گذاشتن شتران در عَطَن . (منتهی الارب ) (از اقرب الموارد). و رجوع به اعطان شود. <BR><font color=\"Blue\">◄</font> (ص ) قوم عطنة؛ گروهی که شتران را در عطن آورده باشند. (منتهی الارب ).<br></font></div>'),
(184326, 'عطو', '<span class=\"hlight\">عطو.</span> <font color=\"DarkGreen\"><b>[ ع َطْوْ ]</font></b> (ع مص ) گرفتن به دست . (از منتهی الارب ). گرفتن : هو طویل لاتعطوه الأیدی ؛ او دراز است و دستها او را نمی گیرد. (از اقرب الموارد). فرا گرفتن .(تاج المصادربیهقی ). <BR><font color=\"Blue\">◄</font> سر و دست برداشتن .(از منتهی الارب ): عطا الیه رأسه ویدیه ؛ سر و دو دست خود را به سوی او بلند کرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چیره شدن در تعاطی . (از منتهی الارب ). غلبه کردن کسی را به خوض در کاری . (تاج المصادر بیهقی ).<br></font></div>'),
(184327, 'عطو', '<span class=\"hlight\">عطو.</span> <font color=\"DarkGreen\"><b>[ ع َطْوْ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِطْوْ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُطْوْ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ طُوو ]</font></b> (ع اِ) آهو که به سوی درخت گردن دراز کند تا بخورد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184328, 'عطوب', '<span class=\"hlight\">عطوب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) نرم و نازک گردیدن پنبه . (از منتهی الارب ) (از اقرب الموارد). عَطب . و رجوع به عطب شود.<br></font></div>'),
(184329, 'عطوب', '<span class=\"hlight\">عطوب .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) قاتل ابیه است . (از فهرست مخزن الادویه ). عطلب . و رجوع به عطلب شود.<br></font></div>'),
(184330, 'عطود', '<span class=\"hlight\">عطود.</span> <font color=\"DarkGreen\"><b>[ ع َ طَوْ وَ ]</font></b> (ع ص ) درشت و دشوار از هر چیزی . (منتهی الارب ). شدید شاق . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سیر شتاب با مشقت . (منتهی الارب ). سیرسریع. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> راه روشن که در آن به هرجا که خواهد رود. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد نجیب و نیکو. (منتهی الارب ). مرد نجیب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> دراز از کوه و روزها. (منتهی الارب ). دراز از جبال و ایام . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نیزه ٔ تیز. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سال تمام و کامل . (منتهی الارب ) (از اقرب الموارد). عَطَیَّد. رجوع به عطید شود.<br></font></div>'),
(184331, 'عطور', '<span class=\"hlight\">عطور.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عطر. (منتهی الارب ) (اقرب الموارد). رجوع به عطر شود.<br></font></div>'),
(184332, 'عطوس', '<span class=\"hlight\">عطوس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) عطسه کننده . <BR><font color=\"Blue\">◄</font> اللُجَم العطوس ؛ مرگ . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دارویی باشد که عطسه آرد. (ذخیره ٔ خوارزمشاهی ). داروهایی که در بینی دمند تا انسان را به عطسه وادارد. (از بحر الجواهر). دوائی که در بینی دمند تا عطسه آورد. (مخزن الادویه ). انفیه . (یادداشت به خط مرحوم دهخدا). ج، عطوسات . رجوع به عطوسی شود.<br></font></div>'),
(184333, 'عطوسات', '<span class=\"hlight\">عطوسات .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عَطوس . (بحر الجواهر) (مخزن الادویه ). رجوع به عطوس شود.<br></font></div>'),
(184334, 'عطوسی', '<span class=\"hlight\">عطوسی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِ) سعوطی که در منخرین کنند تا آب دماغ بیرون چکد و در عرف هند آن را سونگهنی و ناس خوانند. (آنندراج ). نشوق و آنچه به بینی کشند. (ناظم الاطباء). عطوس و رجوع به عطوس شود.<br></font></div>'),
(184335, 'عطوط', '<span class=\"hlight\">عطوط.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) طائری است که آن را عطیطوی نامند. (فهرست مخزن الادویه ).<br></font></div>'),
(184336, 'عطوف', '<span class=\"hlight\">عطوف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) عَطف است در تمام معانی . (از اقرب الموارد). رجوع به عَطف شود.<br></font></div>'),
(184337, 'عطوف', '<span class=\"hlight\">عطوف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) مهربان . عاطف . رؤوف . مشفق . گویند: رجل عطوف ؛ یعنی شخص شفوق و نیکوخلق و نیکوکار. (از اقرب الموارد). مهربان . (دهار). <BR><font color=\"Blue\">◄</font> قوس عطوف ؛ کمان که یکی از دو سر آن بر دیگری برگشته باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) نامی از نامهای خدای تعالی . (یادداشت به خط مرحوم دهخدا).<br></font></div>'),
(184338, 'عطوف', '<span class=\"hlight\">عطوف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) شتر ماده ای که بر پوست شتربچه ٔ پر از کاه مهربانی کند و بر آن شیر دوشند. <BR><font color=\"Blue\">◄</font> مصیده ای که چوب کج داشته باشد. <BR><font color=\"Blue\">◄</font> تیر قمار که مایل باشد بر همه ٔ تیرها و فائزالمرام برآید، و یا تیر بی فایده و بی نقصان، و یا تیر که قمار بار بار رد کنند یا مرة بعد اخری اندازند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چادر. ج، عُطف . (منتهی الارب ).<br></font></div>'),
(184339, 'عطوفة', '<span class=\"hlight\">عطوفة.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع ص ) مؤنث عَطوف . زن مهربان . (غیاث اللغات ). رجوع به عَطوف شود.<br></font></div>'),
(184340, 'عطوفت', '<span class=\"hlight\">عطوفت .</span> <font color=\"DarkGreen\"><b>[ ع ُ ف َ ]</font></b> (از ع، اِمص )عُطوف . محبت و دوستی و مهربانی و توجه . (ناظم الاطباء). شفقت . رحم . نیکخواهی . مهر. رحمت . بستگی . تعلق .<br>- <span class=\"hlight\">عطوفت پدری </span> ؛ مهربانی پدر به فرزند. (ناظم الاطباء).<br></font></div>'),
(184341, 'عطوفی', '<span class=\"hlight\">عطوفی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) محمدبن علی بن وهیب بن وهب بن واقدبن هرثمه ٔ عطوفی بغدادی، مکنی به ابوبکر، محدث بود و از محمدبن ابی شیبه و جعفر فریابی و دیگران روایت کرده است . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(184342, 'عطول', '<span class=\"hlight\">عطول .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) بی پیرایه ماندن زن . (از منتهی الارب ) (از اقرب الموارد).عَطَل . رجوع به عطل شود.<br></font></div>'),
(184343, 'عطون', '<span class=\"hlight\">عطون .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) شتر خوابیده در عَطَن .تذکیر و تأنیث در آن یکسان است . (از منتهی الارب ).<br></font></div>'),
(184344, 'عطون', '<span class=\"hlight\">عطون .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) سیراب گردیده فروخفتن شتران در «عطن ». (از منتهی الارب ) (از اقرب الموارد). بخفتن شتر در کنار آب . (المصادر زوزنی ). سیر آب خوردن شتر و بر لب آب فروخفتن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> به عطن بازگشتن شتر ماده بعد خوردن آب و باز بر آب آوردن آنرا. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184345, 'عطون', '<span class=\"hlight\">عطون .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ عاطِن . (اقرب الموارد). رجوع به عاطن شود. <BR><font color=\"Blue\">◄</font> ج ِ عاطنة. (منتهی الارب ) (اقرب الموارد). رجوع به عاطنة شود. <BR><font color=\"Blue\">◄</font> قوم عطون ؛ قوم که شتران را بر «عطن » فرود آورند. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184346, 'عطوی', '<span class=\"hlight\">عطوی .</span> <font color=\"DarkGreen\"><b>[ ع َ طْ وا ]</font></b> (ع ص ) قوس عطوی ؛ کمان نرم . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184347, 'عطوی', '<span class=\"hlight\">عطوی .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (ص نسبی ) منسوب به عطیة که نام جد عبدالرحمان محمدبن عبدالرحمان بن عطیه ٔ عطوی شاعر است . و گویند او محمدبن عطیه ٔ بصری مولای بنی لیث است که معتزلی مذهب و نیکوشعر بود و شعر او را برخی نقل کرده اند. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(184348, 'عطوی', '<span class=\"hlight\">عطوی .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (اِخ ) محمدبن عبدالرحمان بن ابی عطیه، مکنی به ابوعبدالرحمان . از موالی بنی لیث بن بکر از کنانة. از شاعران دولت بنی عباس بود. زادگاه وی بصره بود و از متکلمان معتزله بشمار می رفت و بر مذهب حسین بن محمد نجار می بود. در روزگار متوکل شهرت یافت و با ابن ابی داود ارتباط داشت و از او بهره ها گرفت . عطوی در شرب نبیذ افراط می کرد و در مورد آن و نیز درباره ٔ فتوح اشعاری بسیار دارد. درگذشت او در حدود سال <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> هَ . ق . رخ داد. (از الاعلام زرکلی به نقل از سمط اللاَّلی و المرزبانی و لسان المیزان ). رجوع به فهرست ابن الندیم شود.<br></font></div>'),
(184349, 'عطویة', '<span class=\"hlight\">عطویة.</span> <font color=\"DarkGreen\"><b>[ ع َ طَ وی ی َ ]</font></b> (اِخ ) گروهی از خوارج هستند که به عطیةبن اسود یمامی حنفی نسبت دارند و پیرو عقیده ٔ او هستند. (از اللباب فی تهذیب الانساب ). رجوع به عطیة (ابن اسود...) شود.<br></font></div>'),
(184350, 'عطی', '<span class=\"hlight\">عطی .</span> <font color=\"DarkGreen\"><b>[ ع ُ طَی ی ]</font></b> (ع اِ مصغر) مصغر عَطاء. (منتهی الارب ) (از اقرب الموارد). عطای کوچک و بخشش کم . (ناظم الاطباء). رجوع به عطاء شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(184351, 'عطیات', '<span class=\"hlight\">عطیات .</span> <font color=\"DarkGreen\"><b>[ ع َ طی یا ]</font></b> (ع اِ) ج ِ عَطیة.(اقرب الموارد). عطایا. رجوع به عطیة و عطیت شود.<br></font></div>'),
(184352, 'عطیبه', '<span class=\"hlight\">عطیبه .</span> <font color=\"DarkGreen\"><b>[ ع َطَ ب َ ]</font></b> (اِخ ) دهی از دهستان شبانکاره، بخش برازجان، شهرستان بوشهر. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> تن . آب آن از چاه و محصول آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(184353, 'عطیة', '<span class=\"hlight\">عطیة.</span> <font color=\"DarkGreen\"><b>[ ع َ طی ی َ ]</font></b> (اِخ ) ابن ابی جمیلة، مکنی به ابوهزان . تابعی است . رجوع به ابوهزان (عطیة...) شود.<br></font></div>'),
(184354, 'عطیة', '<span class=\"hlight\">عطیة.</span> <font color=\"DarkGreen\"><b>[ ع َ طی ی َ ]</font></b> (اِخ ) ابن سعدبن جناده ٔ عوفی جدلی قیسی کوفی، مکنی به ابوالحسن . از رجال حدیث و از شیعه ٔ کوفه بود و با ابن اشعث خروج کرد. لذا حجاج به محمدبن قاسم ثقفی فرمان داد تا عطیه را فراخواند و اگر علی بن ابی طالب (ع ) را سب نکرد چهارصد ضربه تازیانه بدو بزند و موی سر و ریش او را بتراشد. و چون عطیة از انجام دادن این امر خودداری کرد فرمان حجاج در مورد او اجرا شد. آنگاه او به فارس پناه برد و در خراسان اقامت گزید. وچون عمربن هبیرةبه ولایت عراق رسید او را اجازه داد تا به کوفه بازگردد و به سال <span class=\"hlight\" dir=\"rtl\">١١١</span> هَ . ق . در این شهر درگذشت . (از الاعلام زرکلی به نقل از ذیل المذیل و تهذیب التهذیب ).<br></font></div>'),
(184355, 'عطیة', '<span class=\"hlight\">عطیة.</span> <font color=\"DarkGreen\"><b>[ ع َ طی ی َ ]</font></b> (اِخ ) (علی ...) مشهور به غمرینی . قاری قرن دوازدهم هجری . رجوع به علی غمرینی شود.<br></font></div>'),
(184356, 'عطیة', '<span class=\"hlight\">عطیة.</span> <font color=\"DarkGreen\"><b>[ ع َ طی ی َ ]</font></b> (اِخ ) ابن صالح بن مرداس، مکنی به ابوذؤابة و ملقب به اسدالدولة، از بنی کلاب بن عامربن صعصعة. وی از امیران مرداس بشمار می رفت و حلب نیز در تصرف او بود که به سال <span class=\"hlight\" dir=\"rtl\">٤٥٤</span> هَ .ق . بر آنجا دست یافت . و پس از حوادثی شرف الدوله مسلم بن قریش به سال <span class=\"hlight\" dir=\"rtl\">٤٦٣</span> هَ . ق . بر آنجا دست یافت و عطیه به کشور روم رفت و در قسطنطنیه به سال <span class=\"hlight\" dir=\"rtl\">٤٦٥</span> هَ . ق . درگذشت . (از اعلام زرکلی از ابن الاثیر و زبدة الحلب ). رجوع به ابوذؤابة شود.<br></font></div>'),
(184357, 'عطیة', '<span class=\"hlight\">عطیة.</span> <font color=\"DarkGreen\"><b>[ ع َ طی ی َ ]</font></b> (اِخ ) ابن سعیدبن عبداﷲ اندلسی قفصی، مکنی به ابومحمد. از عالمان حدیث و متصوف قرن چهارم هجری بشمار می رفت . او به سیاحتی طولانی در مشرق پرداخت و به ماوراءالنهر رسید و مدتی در نیشابور اقامت گزید و به سال <span class=\"hlight\" dir=\"rtl\">٤٠٧</span> هَ .ق . در مکه درگذشت . او راست : کتابی در تجویز سماع و کتابی در حدیث . (از الاعلام زرکلی به نقل از بغیة الملتمس و الصلة).<br></font></div>'),
(184358, 'عطیة', '<span class=\"hlight\">عطیة.</span> <font color=\"DarkGreen\"><b>[ ع َ طی ی َ ]</font></b> (اِخ )ابن اسود کلبی . از موالی بنی کلب . وی شاعر و از اهالی شام بود و در عصر بنی امیه میزیست . و چون در ابیاتی مروان بن محمد را هجو کرده بود و یمانی ها را به شورش تشویق نموده بود مروان او را در حدود سال <span class=\"hlight\" dir=\"rtl\">١٣٠</span> هَ . ق . به قتل رسانید. (از الاعلام زرکلی از المرزبانی ).<br></font></div>'),
(184359, 'عطیة', '<span class=\"hlight\">عطیة.</span> <font color=\"DarkGreen\"><b>[ ع َ طی ی َ ]</font></b>(اِخ ) ابن اسود یمامی حنفی، از بنی حنیفة. وی از عالمان و امیران خوارج بود. او در روزگار نافعبن ازرق می زیست و چون نافع «قعدة» را تکفیر کرد وی به همراهی برخی دیگر به نجدةبن عامر پیوستند و با وی بیعت کردند. و چون نجدة جهل در شریعت را معذور می دانست عطیة از وی نیز روی گردان شد و با ابی فدیک (عبداﷲبن ثور) ازنجدة جدا شدند و پس از اندکی از ابی فدیک نیز جدا گشت و از آن موقع خوارج به دو گروه تقسیم شدند یکی فدیکیة که پیروان فدیک بودند و دیگر عطویة که پیروان عطیةبن اسود بوده اند. عطیة سپس به سیستان رفت و در حدود سال <span class=\"hlight\" dir=\"rtl\">٧٥</span> هَ . ق . درگذشت . خوارج سیستان و خراسان و کرمان و قهستان همگی عطویة بوده اند. (از الاعلام زرکلی به نقل از الحور العین و اللباب و الملل و النحل ).<br></font></div>'),
(184360, 'عطیة', '<span class=\"hlight\">عطیة.</span> <font color=\"DarkGreen\"><b>[ ع َ طی ی َ ]</font></b> (اِخ ) ابن اسید، مکنی به ابوالمرقال . راجز عرب . رجوع به ابوالمرقال (عطیة...) شود.<br></font></div>'),
(184361, 'عطیة', '<span class=\"hlight\">عطیة.</span> <font color=\"DarkGreen\"><b>[ ع َ طی ی َ ]</font></b> (اِخ ) مکنی به ابووهب و مشهور به عطیه ٔواسطی . تابعی است . رجوع به ابووهب (عطیة...) شود.<br></font></div>'),
(184362, 'عطیة', '<span class=\"hlight\">عطیة.</span> <font color=\"DarkGreen\"><b>[ ع َ طی ی َ]</font></b> (ع اِ) عطیه . دهش . بخشیده شده . (منتهی الارب ). آنچه داده شود. (از اقرب الموارد). دادنی . (دهار). داد. داده . عطیت . جائزة. عَصْر. عَصَر. عطا. عُنَّه . لُهوَة. نافلة. نُبلة. نَحل . نِضاض . نَفحة. نَفل . (از منتهی الارب ). ج، عَطایا. (منتهی الارب ) (اقرب الموارد). و عطیّات . (اقرب الموارد). رجوع به عطیت و عطیه شود.<br></font></div>'),
(184363, 'عطیة', '<span class=\"hlight\">عطیة.</span><font color=\"DarkGreen\"><b>[ ع َ طی ی َ ]</font></b> (اِخ ) مکنی به ابوعبدالکریم . از روات حدیث است . و رجوع به ابوعبدالکریم (عطیة ...) شود.<br></font></div>'),
(184364, 'عطیة', '<span class=\"hlight\">عطیة.</span> <font color=\"DarkGreen\"><b>[ ع َطی ی َ ]</font></b> (اِخ ) مکنی به ابومعزل و مشهور به عطیة الطفاوی . محدث بود. و رجوع به ابومعزل (عطیة...) شود.<br></font></div>'),
(184365, 'عطیة', '<span class=\"hlight\">عطیة.</span> <font color=\"DarkGreen\"><b>[ ع َ طی ی َ ]</font></b> (اِخ ) ابن بسر. صحابی است . (از منتهی الارب ).<br></font></div>'),
(184366, 'عطیة', '<span class=\"hlight\">عطیة.</span> <font color=\"DarkGreen\"><b>[ ع َ طی ی َ ]</font></b> (اِخ ) ابن رافع، مکنی به ابوهزان، تابعی است . رجوع به ابوهزان (عطیة...) شود.<br></font></div>'),
(184367, 'عطیت', '<span class=\"hlight\">عطیت .</span> <font color=\"DarkGreen\"><b>[ ع َ طی ی َ ]</font></b> (ع اِ) عطیة. چیزی که به کسی عطا کنند. بخشش . (فرهنگ فارسی معین ). دهش <span class=\"hlight\">:</span> <br>نیل دهنده توئی به گاه عطیت <br>پیل دمنده تو به گاه کینه گزاری .<br> <font color=\"Red\">رودکی .</font><br>ای طالبان نعمت و سائلان عطیت چگونه رود حال شما. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٥٣</span>). رجوع به عطیة و عطیه شود.<br>- <span class=\"hlight\">عطیت الهی </span> ؛ بخشش خداوندی . فیض الهی . (فرهنگ فارسی معین ).<br></font></div>'),
(184368, 'عطید', '<span class=\"hlight\">عطید.</span> <font color=\"DarkGreen\"><b>[ ع َ طَی ْ ی َ ]</font></b> (ع ص ) عطوَّد است در تمام معانی . (از منتهی الارب ). رجوع به عطوّد شود.<br></font></div>'),
(184369, 'عطیر', '<span class=\"hlight\">عطیر.</span> <font color=\"DarkGreen\"><b>[ ع ُ طَ ]</font></b> (اِخ ) از اعلام است . (از منتهی الارب ).<br></font></div>'),
(184370, 'عطیف', '<span class=\"hlight\">عطیف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) زن نرم خوی فرمانبربی کبر و نخوت . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184371, 'عطیف', '<span class=\"hlight\">عطیف .</span> <font color=\"DarkGreen\"><b>[ ع ُ طَ ]</font></b> (اِخ ) از اعلام است . (منتهی الارب ).<br></font></div>'),
(184372, 'عطیفة', '<span class=\"hlight\">عطیفة.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع اِ) قوس و کمان . ج، عَطائف . (از اقرب الموارد).<br></font></div>'),
(184373, 'عطیفة', '<span class=\"hlight\">عطیفة.</span> <font color=\"DarkGreen\"><b>[ ع ُ طَ ف َ ]</font></b> (اِخ ) (شریف ...) ابن ابی نمی محمدبن حسن بن علی حسنی . از امیران مکه در قرن هشتم هجری . وی به سال <span class=\"hlight\" dir=\"rtl\">٧٠١</span> هَ . ق . از جانب بیبرس جاشنگیر به ولایت مکه گماشته شد و به سال <span class=\"hlight\" dir=\"rtl\">٧٠٤</span> هَ . ق . معزول گشت . و بار دیگر در سال <span class=\"hlight\" dir=\"rtl\">٧١٩</span> هَ .ق . به منصب خود بازگشت و در سال <span class=\"hlight\" dir=\"rtl\">٧٣٨</span> هَ . ق . دستگیر شد و به مصر برده شد و در اسکندریه زندانی گشت و در سال <span class=\"hlight\" dir=\"rtl\">٧٤٣</span> هَ . ق . درگذشت . (از الاعلام زرکلی از الدررالکامنة و الجداول المرضیة و خلاصة الکلام ).<br></font></div>'),
(184374, 'عطیل', '<span class=\"hlight\">عطیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) خوشه ٔ طلع خرمابن نر. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184375, 'عطیم', '<span class=\"hlight\">عطیم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) هلاک شده و آن واحد عُطُم است به معنی هلاک شدگان . (از منتهی الارب ) (از اقرب الموارد). عاطِم . رجوع به عطم و عاطم شود.<br></font></div>'),
(184376, 'عطین', '<span class=\"hlight\">عطین .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) پوست که از جهت دباغت در دباغ گذارند و نرم سازند. (از منتهی الارب ) (از اقرب الموارد). و رجوع به عَطن (مص ) شود. <BR><font color=\"Blue\">◄</font> پوست بوی بد گرفته . (منتهی الارب ). و رجوع به عَطِن شود. <BR><font color=\"Blue\">◄</font> رجل عطین ؛ مرد که اندامش بوی بد دارد. (از منتهی الارب ). عطینة. رجوع عطینة شود.<br></font></div>'),
(184377, 'عطینة', '<span class=\"hlight\">عطینة.</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ ]</font></b> (ع ص ) رجل عطینة؛ مرد که اندامش بوی بد دارد. (منتهی الارب ). عَطین . عَطِنة. رجوع به عطین و عطنة شود.<br></font></div>'),
(184378, 'عطیه', '<span class=\"hlight\">عطیه .</span> <font color=\"DarkGreen\"><b>[ ع َ طی ی َ ]</font></b> (ع اِ) عطیة. عطیت . جایزه . انعام . بخشش <span class=\"hlight\">:</span> و برخوردار گردانادامیرالمؤمنین را از تو و از آن نعمت بزرگ و عطیه ٔ وافر و موهبت نفیس که ترا داد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٠٧</span>). رحمت و برکتهای ایزدی و برکت بنده اش امیرالمؤمنین به تو باد و به آن نعمت بزرگ و عطیه ٔ کلان ... که تو داری . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣١٤</span>).<br>تو آن معطی مکرم کز تو هرگز<br>نباشد کف رادت بی عطیه .<br> <font color=\"Red\">سوزنی .</font><br>عقل با جان عطیه ٔ احدیست <br>جان با عقل زنده ٔ ابدیست .<br> <font color=\"Red\">نظامی .</font><br>مردمان با آبروی پریشان را صدقات فرماید و عطیه دهد. (مجالس سعدی ). استمناح ؛ عطیه خواستن . امتلاذ؛ عطیه گرفتن از کسی . عصر؛ عطیه دادن . (از منتهی الارب ).<br>- <span class=\"hlight\">ظفر عطیه </span> ؛ ظفربخش . ظفرده <span class=\"hlight\">:</span> پادشاه سلیمان مکان از چمینه الویه ٔ ظفر عطیه بجانب خوی برافراشت . (حبیب السیر، ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٢</span>).<br><BR><font color=\"Blue\">◄</font> در اصطلاح فقهی، به اعتبار جنس، چهار نوع است :<span class=\"hlight\" dir=\"rtl\">١</span> - صدقه، و آن عقدی است که نیاز به ایجاب و قبول وقبض دارد. <span class=\"hlight\" dir=\"rtl\">٢</span> - هبه، که محتاج به ایجاب و قبول و قبض است و در آن قصد قربت شرط نیست . <span class=\"hlight\" dir=\"rtl\">٣</span> - سکنی و عمری و رقبی، که در آنها نیز ایجاب و قبول و قبض الزامی است . <span class=\"hlight\" dir=\"rtl\">٤</span> - تحبیس یا حبس، که در اعتبار قبض و تقید بمدت مانند سکنی است . (از فرهنگ علوم عقلی، به نقلاز شرح لمعه ). در حدیث است : لایحل للرجل یعطی العطیة فیرجع فیها اًلا الوالد فیما أعطی ولده . و شافعی گوید: یجوز له أن یرجع صغیرا کان الولد أو کبیرا. (از منتهی الارب ). و رجوع به صدقة و هبة و سکنی و حبس شود. <BR><font color=\"Blue\">◄</font> در اصطلاح نجومی، بخشی که جهت تعیین عمر مولودبه هر کوکب دهند. عطیه بر حسب بودن کدخدا در وتد و مایل وتد یا زایل وتد قسمت می شود به عطیه ٔ بزرگ (عظمی و کبری ) و میانه (وسطی ) و خرد (صغری ). عطیه اصلاً برای استخراج مدت عمر مولود است مثلاً عطیه ٔ کبرای شمس <span class=\"hlight\" dir=\"rtl\">١٢٠</span> است . (از فرهنگ فارسی معین ). و رجوع به التفهیم ص <span class=\"hlight\" dir=\"rtl\">٥٢١</span> شود.<br></font></div>'),
(184379, 'عطیه', '<span class=\"hlight\">عطیه .</span> <font color=\"DarkGreen\"><b>[ ع َ طی ی َ ]</font></b> (اِخ ) نام راوی شعر سنائی است . (یادداشت به خط مرحوم دهخدا) <span class=\"hlight\">:</span> <br>اند بار از تو و دیوانه عطیه کل و کور<br>کل تر و کورتر و غرتر و دیوانه تریم .<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(184380, 'عطیه', '<span class=\"hlight\">عطیه .</span> <font color=\"DarkGreen\"><b>[ ع َ طی ی َ ]</font></b> (اِخ ) ابن حارث همدانی، مکنی به ابوروق . محدث است . رجوع به ابوروق (عطیة...) شود.<br></font></div>'),
(184381, 'عظ', '<span class=\"hlight\">عظ.</span> <font color=\"DarkGreen\"><b>[ ع َ ظِن ْ ]</font></b> (ع ص ) نعت است از عَظا. (از منتهی الارب ) (از اقرب الموارد). رجوع به عظا و عظی شود.<br></font></div>'),
(184382, 'عظ', '<span class=\"hlight\">عظ.</span> <font color=\"DarkGreen\"><b>[ ع َظظ ]</font></b> (ع مص ) سختی رسانیدن حرب کسی را. (از منتهی الارب ): عظّته الحرب ؛ مانند عَض ّ است، و گویند عض، در مورد گزیدن و زیان رساندن به دندان است و عظ در غیردندان . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بر زمین چسفانیدن کسی را. (از منتهی الارب ): عظّ فلاناًبالارض ؛ او را بر زمین چسباند. (از اقرب الموارد).<br></font></div>'),
(184383, 'عظا', '<span class=\"hlight\">عظا.</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ظِن ْ ]</font></b> (ع مص ) آماسیدن شکم شتر از خوردن گیاه عنظوان . (از منتهی الارب ). عَظی ̍. (از اقرب الموارد). رجوع به عظی شود.<br></font></div>'),
(184384, 'عظا', '<span class=\"hlight\">عظا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) نوعی از صدف است . (تحفه ٔ حکیم مؤمن ) (مخزن الادویه ).<br></font></div>'),
(184385, 'عظاء', '<span class=\"hlight\">عظاء.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عظاءة. (اقرب الموارد). جانورکی است چون چلپاسه، بزرگتر از وزغه . (یادداشت به خط مرحوم دهخدا). سلامندرا. (مخزن الادویه ). سالامندرا. رجوع به عظاءة شود. <BR><font color=\"Blue\">◄</font> ج ِ عَظایة. (منتهی الارب ) (اقرب الموارد). رجوع به عظایة شود.<br></font></div>'),
(184386, 'عظاء', '<span class=\"hlight\">عظاء.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ عَظاة. (اقرب الموارد) (منتهی الارب ). رجوع به عظایة شود.<br></font></div>'),
(184387, 'عظات', '<span class=\"hlight\">عظات .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ عِظة. (اقرب الموارد).نصیحتها. پندها. اندرزها. رجوع به عظة و عظت شود:<br>اندوه من به روی تو بودی گسارده <br>و آرام یافتی دل من از عظات تو.<br> <font color=\"Red\">مسعودسعد.</font><br>بهر این بو گفت احمد در عظات <br>دائما قرة عینی فی الصلاة.<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(184388, 'عظار', '<span class=\"hlight\">عظار.</span><font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِمص ) امتلاء و پری از شراب . (از اقرب الموارد به نقل از لسان و تاج ). و رجوع به عظارة شود.<br></font></div>'),
(184389, 'عظاری', '<span class=\"hlight\">عظاری .</span> <font color=\"DarkGreen\"><b>[ ع َ ری ی ]</font></b> (ع اِ) ملخهای نر. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184390, 'عظاظ', '<span class=\"hlight\">عظاظ.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) دشنام آشکار. <BR><font color=\"Blue\">◄</font> شدت مشقت . <BR><font color=\"Blue\">◄</font> سختی جنگ . (از منتهی الارب ). مُعاظّة. رجوع به معاظة شود.<br></font></div>'),
(184391, 'عظاظ', '<span class=\"hlight\">عظاظ.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) همدیگر را گزیدن . (منتهی الارب ). به معنی عضاض است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> با هم سختی کردن . (منتهی الارب ). سخت گردیدن در جنگ : عاظّ القوم ؛ در جنگ سخت شدند و بسختی جنگیدند. (از اقرب الموارد). مُعاظّة. و رجوع به معاظة شود.<br></font></div>'),
(184392, 'عظال', '<span class=\"hlight\">عظال .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) به گشنی در پی ماده بر زبر یکدیگر رفتن سگها و ملخها و جز آن . (منتهی الارب ). رجوع به عَظل شود. <BR><font color=\"Blue\">◄</font> سوار شدن بر چیزی : عاظل الشی ٔ. <BR><font color=\"Blue\">◄</font> عاظل الشاعر فی القافیة؛ شاعر در قافیه تضمین کرد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عاظل الکلام ؛ سخن را پیچیده ساخت و آن را بدنبال یکدیگر آورد و تکرار کرد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> عاظل بالکلام ؛ «رجیع» و سخنی آورد که به صاحب خود بازگردد.(از اقرب الموارد). مُعاظلة. رجوع به معاظلة شود.<br></font></div>'),
(184393, 'عظال', '<span class=\"hlight\">عظال .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِمص ) تکریر است در قوافی . (از منتهی الارب ). تضمین است در قوافی . (از اقرب الموارد).<br></font></div>'),
(184394, 'عظالی', '<span class=\"hlight\">عظالی .</span> <font color=\"DarkGreen\"><b>[ ع ُ لا ]</font></b> (اِخ ) (یوم الَ ...) روزی است مر عربان را. (از منتهی الارب ). وجه تسمیه ٔ آن این است که برخی از مردم بر برخی سوار شدند، و یا اینکه به جهت اجتماع و اشتباک و درگیری و «تعاظل » آنها بر ریاست بوده است، و یا اینکه چون هر دو یا سه تن از آنها بر یک دابه سوار بودند و این آخرین جنگ بین بکربن وائل و تمیم، در جاهلیت بوده است . (از مجمع الامثال میدانی ).<br></font></div>'),
(184395, 'عظام', '<span class=\"hlight\">عظام .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ عَظم . (منتهی الارب ) (اقرب الموارد). استخوانها. رجوع به عظم شود. و در مورد «فواید عظام » در عقیده ٔ پزشکی قدیم، رجوع به اختیارات بدیعی شود <span class=\"hlight\">:</span> انظر الی العظام کیف ننشزها ثم نکسوها لحماً. (قرآن <span class=\"hlight\" dir=\"rtl\">٢٥٩/٢</span>)؛ و استخوانها را بنگرکه چگونه آنها را از جای برداریم سپس با گوشت می پوشانیم . و قالوا أاًذاکنا عظاما و رفاتا أاًنا لمبعوثون خلقا جدیدا. (قرآن <span class=\"hlight\" dir=\"rtl\">٤٩/١٧</span> و <span class=\"hlight\" dir=\"rtl\">٩٨</span>). و گفتند آیا اگر استخوان و ریزه ریزه باشیم به صورت آفرینشی تازه برانگیخته خواهیم بود. فخلقنا المضغة عظاما فکسونا العظام لحما. (قرآن <span class=\"hlight\" dir=\"rtl\">١٤/٢٣</span>). پس «مضغه » را استخوانهایی گرداندیم و استخوانها را با گوشت پوشانیدیم . أاًذاکنا عظاما نخرة. (قرآن <span class=\"hlight\" dir=\"rtl\">١١/٧٩</span>)؛ آیا اگر استخوانهای پوسیده ای بودیم . أاًذامتنا و کنا تُراباً و عظاما أاًنا لمبعوثون . (قرآن <span class=\"hlight\" dir=\"rtl\">٤٧/٥٦</span>). آیا اگر بمیریم و استخوانهایی شویم، آیا باز هم برانگیخته خواهیم بود.<br>بیندازی عظام و لحم و شحمم <br>رگ و پی همچنان و جلد منشور.<br> <font color=\"Red\">منوچهری .</font><br>محال باشد اگر با عطای عقل عظیم <br>چون این سگانت قصد عظام باید کرد.<br> <font color=\"Red\">ناصرخسرو.</font><br>شنیدم که روزی زمینی بکافت <br>عظام زنخدان پوسیده یافت .<br> <font color=\"Red\">سعدی .</font><br>اگر زبان مرا روزگار دربندد<br>به عشق در سخن آیند ریزه های عظام .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">عظام رمیم </span> ؛ استخوانهای پوسیده و ریزیده . (دهار): اشاره است به آیه ٔ کریمه ٔ <span class=\"hlight\">:</span> و ضرب لنا مثلاً و نسی خلقه، قال من یحیی العظام و هی رمیم . (قرآن <span class=\"hlight\" dir=\"rtl\">٧٨/٣٦</span>)؛ و برای ما مثلی زد و آفرینش خود را فراموش کرد، گفت چه کسی استخوانها را زنده می گرداند و حال آنکه آنها پوسیده است .<br>مرده از خاک لحد رقص کنان برخیزد<br>گر توبالای عظامش گذری و هی رمیم .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">عظام ناخرة و عظام نخرة</span> ؛ استخوانهای پوسیده و ریزیده . (دهار).<br>- <span class=\"hlight\">علم عظام </span> ؛ در اصطلاح پزشکی، استخوان شناسی . (فرهنگ فارسی معین ). رجوع به استخوان شناسی شود.<br> <BR><font color=\"Blue\">◄</font> (ص ) ج ِ عَظیم . (اقرب الموارد). بزرگان و کلانان . (آنندراج ). رجوع به عظیم شود.<br>- <span class=\"hlight\">آقایان عظام </span> ؛ مردمان بزرگ . (ناظم الاطباء).<br>- <span class=\"hlight\">امرای عظام </span> ؛ فرماندهان بزرگ <span class=\"hlight\">:</span> مشارالیه <font color=\"DarkGreen\"><b>[ مستوفی الممالک ]</font></b> از جمله امراء عظام، و شغل و عمل مشارالیه عظیم است . (تذکرةالملوک چ دبیرسیاقی ص <span class=\"hlight\" dir=\"rtl\">١٦</span>).<br></font></div>'),
(184396, 'عظام', '<span class=\"hlight\">عظام .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) موضعی است به شام . (منتهی الارب ) (از معجم البلدان ).<br></font></div>'),
(184397, 'عظام', '<span class=\"hlight\">عظام .</span> <font color=\"DarkGreen\"><b>[ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُظْ ظا ]</font></b> (ع ص ) بزرگ و کلان . (منتهی الارب ) (از اقرب الموارد). عَظیم . رجوع به عظیم شود.<br></font></div>'),
(184398, 'عظامة', '<span class=\"hlight\">عظامة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ظْ ظا م َ ]</font></b> (ع ص ) بزرگ و کلان . مؤنث عُظّام . (از اقرب الموارد). و رجوع به عظام شود. <BR><font color=\"Blue\">◄</font> (اِمص ) بزرگی و بزرگ منشی . (منتهی الارب ). کبر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نخوت . (منتهی الارب )(اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناز و گردن کشی . (منتهی الارب ). زهو. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) بالشچه ٔ زنان که بر سرین بندند جهت کلان نمودن . (منتهی الارب ). عِظامة. (اقرب الموارد). رجوع به عِظامة شود.<br></font></div>'),
(184399, 'عظامة', '<span class=\"hlight\">عظامة.</span> <font color=\"DarkGreen\"><b>[ ع ُ م َ ]</font></b> (ع ص ) بزرگ و کلان، مؤنث عُظام . (از اقرب الموارد). رجوع به عُظام شود.<br></font></div>'),
(184400, 'عظامة', '<span class=\"hlight\">عظامة.</span> <font color=\"DarkGreen\"><b>[ ع ِم َ ]</font></b> (ع اِ) بالشچه ای که زنان بر سرین بندند تا کلان نماید. (منتهی الارب ). جامه ای است چون وساده و بالش که زنان بوسیله ٔ آن «عجیز» خود را بزرگ نشان می دهند. (از اقرب الموارد). عُظمة. و رجوع به عظمة شود. <BR><font color=\"Blue\">◄</font> ج ِ عَظم، و هاء آن برای تأنیث جمع است . (از منتهی الارب ) (از اقرب الموارد). رجوع به عظم شود.<br></font></div>'),
(184401, 'عظامة', '<span class=\"hlight\">عظامة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع مص ) بزرگ و کلان شدن . (از منتهی الارب ) (از اقرب الموارد). عِظَم . رجوع به عظم شود.<br></font></div>'),
(184402, 'عظامی', '<span class=\"hlight\">عظامی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b>(ص نسبی ) منسوب به عظام . آنکه به استخوانهای پوسیده یعنی مفاخر پدران بالد. (یادداشت به خط مرحوم دهخدا). مقابل عصامی <span class=\"hlight\">:</span> اگر به آن نفس و خرد و همت اصل بودی نیکوتر بودی که عظامی و عصامی بس نیکو باشد ولیکن عظامی به یک پشیز نیرزد چون فضل و ادب و درس ندارد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤١٥</span>). رجوع به عصامی شود.<br></font></div>'),
(184403, 'عظایات', '<span class=\"hlight\">عظایات .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عَظایة. (اقرب الموارد). رجوع به عَظایة شود.<br></font></div>'),
(184404, 'عظایة', '<span class=\"hlight\">عظایة.</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ی َ ]</font></b> (ع اِ) دابه ای است مانند کربسه، و کربسه . (منتهی الارب ). حیوانی است مانند سام ابرص، گویند نر او را دو ذکر است و ماده ٔ او را دو فرج . (الفاظ الادویة). حیوانی است که با کرفش مشابهت دارد و از کرفش مقداری بزرگتر باشد، و هم چون عظاست . (از تذکره ٔ ضریر انطاکی ). کرباسه . (السامی ). سلامندرا. (تحفه ٔ حکیم مؤمن ). سالامندرا. (مخزن الادویه ). دویبه ای است نرم و تابان که بسیار دونده و جست وخیز کننده است و شباهت به سام ابرص دارد و آن را شحمة الارض و شحمة الرمل نیز نامند. آن را انواع بسیاری است که همگی را خالها و نقطه های سیاه باشد. و از طبیعت آن حرکت بسیار سریع و توقف ناگهانی است . (از اقرب الموارد). ج، عَظایا و عَظایات . (اقرب الموارد). عظاءة. رجوع به عظاءة شود.<br></font></div>'),
(184405, 'عظب', '<span class=\"hlight\">عظب .</span> <font color=\"DarkGreen\"><b>[ ع َ ظِ ]</font></b> (ع ص ) در جای خشک فرودآینده . (منتهی الارب ). آنکه در فلات و جاهای خشک فرود آید. عاظب . (از اقرب الموارد).<br></font></div>'),
(184406, 'عظب', '<span class=\"hlight\">عظب .</span> <font color=\"DarkGreen\"><b>[ ع َ ظَ ]</font></b> (ع مص ) لازم گرفتن و صبر گزیدن بر کسی . <BR><font color=\"Blue\">◄</font> فربه گشتن . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184407, 'عظب', '<span class=\"hlight\">عظب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) به سرعت جنبانیدن پرنده دمغزه را. (از منتهی الارب ): عظب الطائر؛ آن پرنده «زمکاء» و دم خود را بسرعت حرکت داد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> لازم گرفتن کسی را و شکیب کردن . عُظوب .و رجوع به عظوب شود. <BR><font color=\"Blue\">◄</font> قیام نمودن بر مال خود. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خشک گردیدن جلد. (از منتهی الارب ): عظب جلده ؛ پوست او خشک گردید. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درشت گردیدن دست از کار کردن . (از منتهی الارب ): عظبت یده ؛ دست او از کار کردن درشت شد. (از اقرب الموارد).<br></font></div>'),
(184408, 'عظت', '<span class=\"hlight\">عظت .</span> <font color=\"DarkGreen\"><b>[ ع ِ ظَ ]</font></b> (ع اِمص، اِ) عظة. نصیحت . پند. اندرز <span class=\"hlight\">:</span> چنانک دیگر متعدیان ناحفاظ را عبرت و عظت باشد. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٧٧</span>). رجوع به عظة و عظات شود.<br></font></div>'),
(184409, 'عظر', '<span class=\"hlight\">عظر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) ناپسند داشتن چیزی را. <BR><font color=\"Blue\">◄</font> پر کردن مشک را. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184410, 'عظر', '<span class=\"hlight\">عظر.</span> <font color=\"DarkGreen\"><b>[ ع َ ظَ ]</font></b> (ع اِ) بار آبستنی . (منتهی الارب ). بارداری و آبستنی . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> جنین . (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> عرق العظر؛ رگ که به سبب آن شترمادگان باردار نشوند، و چون آن را قطع کنند باردار گردند. (از منتهی الارب ) (ناظم الاطباء).<br></font></div>'),
(184411, 'عظر', '<span class=\"hlight\">عظر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ظُ ]</font></b> (ع ص، اِ) ج ِ عَظور. (منتهی الارب ) (اقرب الموارد). رجوع به عَظور شود.<br></font></div>'),
(184412, 'عظر', '<span class=\"hlight\">عظر.</span> <font color=\"DarkGreen\"><b>[ ع َ ظِ ]</font></b> (ع ص ) ناپسند و مکروه . (ناظم الاطباء).<br></font></div>'),
(184413, 'عظرب', '<span class=\"hlight\">عظرب .</span> <font color=\"DarkGreen\"><b>[ ع ِ رِ ]</font></b> (ع اِ) مار خرد. (منتهی الارب ). افعی کوچک . (مخزن الادویه ) (از اقرب الموارد).<br></font></div>'),
(184414, 'عظرم', '<span class=\"hlight\">عظرم .</span> <font color=\"DarkGreen\"><b>[ ع ِ رِ ]</font></b> (ع اِ) سرگین شیر بیشه . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184415, 'عظعاظ', '<span class=\"hlight\">عظعاظ.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) مصدر عَظعظة است در تمام معانی . (از منتهی الارب ). رجوع به عظعظة شود.<br></font></div>'),
(184416, 'عظل', '<span class=\"hlight\">عظل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) بر یکدیگر سوار گردیدن سگان به گشنی . (از منتهی الارب ): عظلت الکلاب ؛ سگان بر یکدیگر سوار شدند. (از اقرب الموارد).عظلت الکلاب او الجراد؛ سگان یا ملخها بر یکدیگر سوار شدند برای سفاد و گشنی . (از تاج المصادر بیهقی ).<br></font></div>'),
(184417, 'عظل', '<span class=\"hlight\">عظل .</span> <font color=\"DarkGreen\"><b>[ ع ُ ظُ ]</font></b> (ع ص، اِ) ج ِ عاظِل . (ناظم الاطباء). ابنه زدگان و متهمان به شر. (منتهی الارب ). رجوع به عاظل شود.<br></font></div>'),
(184418, 'عظلام', '<span class=\"hlight\">عظلام .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) گرد و غبار. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184419, 'عظلم', '<span class=\"hlight\">عظلم .</span> <font color=\"DarkGreen\"><b>[ ع ِ ل ِ ]</font></b> (ع اِ) شیره ٔ درخت، یا گیاهی است که بدان رنگ کنند، یا آن وسمه است و نیل . (منتهی الارب ). نیل . (مهذب الاسماء). درخت نیل . (الفاظ الادویة). عصاره ٔ درختی است که لون او سبز تیره رنگ بود، و گویند وسمه ٔ تر است و در زمین عرب بسیار باشد و از او نیل سازند. (تذکره ٔ ضریر انطاکی ). درخت نیل است و نیل عصاره ٔ وی است و آن را وسمه خوانند و کتم نیز گویند.(اختیارات بدیعی ). درخت نیل را گویند و نیل عصاره ٔ آن است و وسمه که زنان بر ابرو می نهند برگ آن است . (برهان ). گیاه وسمه است که به فارسی نیل نامند و گفته اند قطلب است . (مخزن الادویه ) (از تحفه ٔ حکیم مؤمن ). گیاهی است که بدان رنگ کنند. (از اقرب الموارد). وگویند آن خطمی است و برخی آن را رنگی سرخ دانند. (از اقرب الموارد به نقل از تاج ). <BR><font color=\"Blue\">◄</font> شب تاریک . (منتهی الارب ) (مهذب الاسماء) (از اقرب الموارد). وآن تشبیه به «عظلم » گیاه است . (از اقرب الموارد).<br></font></div>'),
(184420, 'عظلمة', '<span class=\"hlight\">عظلمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ م َ ]</font></b> (ع اِ) تاریکی . (منتهی الارب ). ظلمت . (اقرب الموارد).<br></font></div>'),
(184421, 'عظلی', '<span class=\"hlight\">عظلی .</span> <font color=\"DarkGreen\"><b>[ ع َ لا ]</font></b> (ع ص ) جراد عظلی ؛ ملخ دو سه بر هم نشسته . (منتهی الارب ). به معنی عاظل است . (از اقرب الموارد). ج ِ عاظل . (ناظم الاطباء). رجوع به عاظل شود.<br></font></div>'),
(184422, 'عظم', '<span class=\"hlight\">عظم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) استخوان . (منتهی الارب ) (دهار). استخوان و به هندوی هاد گویند. (از تذکره ٔ ضریر انطاکی ). به فارسی استخوان و به ترکی سموک نامند. (از تحفه ٔ حکیم مؤمن ). تعریف آن در کتب پزشکی بدین نحو بیان شده که استخوان عضوی است بسیط و سختی آن به اندازه ای می باشد که دوپاره ساختن آن غیرممکن است . (از کشاف اصطلاحات الفنون ). «قصب » حیوان که گوشت برآن است .(از اقرب الموارد). و برای اطلاع از خواص عظم نزد قدما رجوع به تذکره ٔ ضریر انطاکی و تحفه ٔ حکیم مؤمن شود. ج، أعظُم و عِظام و عِظامة. (منتهی الارب ) (اقرب الموارد). و رجوع به استخوان شود <span class=\"hlight\">:</span> قال رب اًنی وهن العظم منی و اشتعل الرأس شیبا. (قرآن <span class=\"hlight\" dir=\"rtl\">٤/١٩</span>)؛ گفت پروردگارا مرا استخوان سست شد و سر را پیری فراگرفت . و علی الذین هادوا حرمنا کل ذی ظفر و من البقر و الغنم حرمنا علیهم شحومَهُمِا الا... ما اختلطَ بعظم . (قرآن <span class=\"hlight\" dir=\"rtl\">١٤٦/٦</span>)؛ و بر کسانی که یهود شدند هر ناخن داری را حرام گردانیدیم و از گاو و گوسفند پیه های آن را حرام کردیم جز... آنچه به استخوان مخلوط باشد.<br>- <span class=\"hlight\">اثر انکسار عظم </span> ؛ در اصطلاح پزشکی، کال . (فرهنگ فارسی معین ). رجوع به کال شود.<br>- <span class=\"hlight\">عظم الاوسط (الَ ...)</span> ؛ استخوانی است در فک اعلای انسان و گوته شاعر معروف آلمان آن را کشف کرده است . (یادداشت به خط مرحوم دهخدا).<br>- <span class=\"hlight\">عظم جبهه </span> .رجوع به اکلیلی شود.<br>- <span class=\"hlight\">عظم حجری </span> ؛ رجوع به حجری شود.<br>- <span class=\"hlight\">عظم خاصره </span> ؛ رجوع به خاصره شود.<br>- <span class=\"hlight\">عظم دمعه </span> ؛ استخوان ناخنی . (فرهنگ فارسی معین ). رجوع به ناخنی شود.<br>- <span class=\"hlight\">عظم رکابی </span> ؛ یکی از خرده استخوانهای گوش . رجوع به ناخنی شود.<br>- <span class=\"hlight\">عظم رمیم </span> ؛ استخوان پوسیده <span class=\"hlight\">:</span> <br>بعد صد سال اگر بر سر خاکم گذری <br>سر برآرد ز گلم رقص کنان عظم رمیم .<br> <font color=\"Red\">حافظ.</font><br>سایه قد تو بر قالبم ای عیسی دم <br>عکس روحیست که بر عظم رمیم افتاده ست .<br> <font color=\"Red\">حافظ.</font><br>و رجوع به ترکیب عظام رمیم شود.<br>- <span class=\"hlight\">عظم صدغ </span> . رجوع به صدغ شود.<br>- <span class=\"hlight\">عظم عضد</span> ؛ استخوان بازو.<br>- <span class=\"hlight\">عظم عقب </span> ؛ استخوان پاشنه . پاشنه . اشتالنگ . و رجوع به عقب شود.<br>- <span class=\"hlight\">عظم قحف </span> . رجوع به قحف شود.<br>- <span class=\"hlight\">عظم قَص ّ</span> ؛ جناغ . رجوع به قص شود.<br>- <span class=\"hlight\">عظم قمحدودة</span> . رجوع به قمحدوده شود.<br>- <span class=\"hlight\">عظم کعب </span> ؛ اشتالنگ . رجوع به کعب و اشتالنگ شود.<br>- <span class=\"hlight\">عظم لامی </span> ؛ استخوان بن زبان . عظم لسانی . رجوع به لامی شود.<br>- <span class=\"hlight\">عظم لسانی </span>؛ استخوان بن زبان . عظم لامی . رجوع به لامی شود.<br>- <span class=\"hlight\">عظم مصفات </span> . رجوع به مصفات شود.<br>- <span class=\"hlight\">عظم وتدی </span> . رجوع به وتدی شود.<br><BR><font color=\"Blue\">◄</font> عظم وضاح ؛ بازیی است مر عربان را. (منتهی الارب ) (از تاج العروس ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عظم الرحل ؛ چوب پالان بی دوال و ادات . <BR><font color=\"Blue\">◄</font> عظم الفدان ؛ تخته ٔ پهن فدان . <BR><font color=\"Blue\">◄</font> عظم الامر؛ معظم کار. (منتهی الارب ) (از اقرب الموارد). عُظم . رجوع به عُظم شود.<br></font></div>'),
(184423, 'عظم', '<span class=\"hlight\">عظم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) اسعدبن اسماعیل بن ابراهیم، ملقب به عظم . تولد و وفات او در دمشق بود (<span class=\"hlight\" dir=\"rtl\">١١١٣</span>-<span class=\"hlight\" dir=\"rtl\">١١٧١</span> هَ . ق .) از طرف دولت عثمانی والی دمشق بود و لقب وزارت نیز یافت و مدت <span class=\"hlight\" dir=\"rtl\">١٤</span> سال در این منصب باقی بود. وی زبانهای سه گانه یعنی فارسی و عربی و ترکی را به خوبی می دانست . (از الاعلام زرکلی ).<br></font></div>'),
(184424, 'عظم', '<span class=\"hlight\">عظم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) استخوان خورانیدن . (از منتهی الارب ): عظم الکلب ؛ سگ را استخوان خورانید. (از اقرب الموارد).<br></font></div>'),
(184425, 'عظم', '<span class=\"hlight\">عظم .</span> <font color=\"DarkGreen\"><b>[ ع َظَ ]</font></b> (ع اِ) عظم الطریق ؛ میانه ٔ راه، و گشاده و فراخ آن . (منتهی الارب ). جاده ٔ راه . (از اقرب الموارد).<br></font></div>'),
(184426, 'عظم', '<span class=\"hlight\">عظم .</span> <font color=\"DarkGreen\"><b>[ ع ِ ظَ ]</font></b> (ع مص ) بزرگ و کلان شدن . (از منتهی الارب ). بزرگ شدن، مقابل صِغر. (از اقرب الموارد). بزرگ شدن . (المصادر زوزنی ) (تاج المصادر بیهقی ). عَظامة. و رجوع به عظامة شود. <BR><font color=\"Blue\">◄</font> سخت شدن کار: عظم الامرعلی فلان ؛ کار بر او سخت و شاق شد. (از اقرب الموارد).<br></font></div>'),
(184427, 'عظم', '<span class=\"hlight\">عظم .</span> <font color=\"DarkGreen\"><b>[ ع ِ ظَ ]</font></b> (ع اِمص ) بزرگی و کلانی، خلاف صِغر.(منتهی الارب ). بزرگی و بزرگواری . (السامی ). بزرگی . (مهذب الاسماء). مقابل صغر. (از اقرب الموارد). حشمت وعظمت و جسامت و هنگفتی و پری . (ناظم الاطباء) <span class=\"hlight\">:</span> لعظمک فی النفوس تبیت ترعی بحفاظ و حراس ثقات . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٩٢</span>). عرصه ٔ آن ولایت از عظم شرف و علو همت خویش تنگ یافت . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٣٢</span>).<br></font></div>'),
(184428, 'عظم', '<span class=\"hlight\">عظم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِمص ) بزرگی و کلانی وبیشتری . (منتهی الارب ). بزرگی . (دهار). کلانی و بزرگی و عظمت و اهمیت و تکبر و بزرگ منشی . (ناظم الاطباء).<br>- <span class=\"hlight\">عظم نهادن </span> ؛ اهمیت دادن . بزرگ شمردن <span class=\"hlight\">:</span> به عاجل الحال جواب نامه ٔ صاحب برید باز باید نبشت و این کار قائد را عظمی ننهاد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٢٥</span>). نانی که وی و کسان وی خورده بودند در مدت صاحبدیوانی و مشاهره که استده اند آن را جمع کردند و عظمی نهادند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٧٠</span>).<br><BR><font color=\"Blue\">◄</font> (اِ) جماعت کثیر: عظم الامر؛ معظم آن کار. عظم الشی ؛ اکثر آن . (از منتهی الارب ). عَظم . و رجوع به عظم شود. ج، أعظام . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> عُظْم َ البطن بطنک ؛ چه کلان شکمی است شکم تو، در تعجب بکار رود و به معنی عَظُم َ که حرکت اول آن حذف شده و حرکت دوم بجای آن قرار گرفته است . و این امر فقط در موردی جایز است که بر روش نعم وبئس از افعال مدح و ذم باشد چنانکه می توان گفت حُسْن َ وجهک . (از اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> در اصطلاح نجوم، بر قدری از اقدار متزایده اطلاق شود. (از کشاف اصطلاحات الفنون ). بطلمیوس نه کوکب خردتراز قدر ششم را عظم خواند. (جهان دانش ص <span class=\"hlight\" dir=\"rtl\">١٠٥</span>). هر یک از مراتب خردی و کلانی ستاره ها، پس به معنی قدر است :عظم اول، قدر اول . قلب الاسد، از ستارگان عظم اول است . و علمای احکام نجوم بجای قدر و عظم شرف گویند. (یادداشت به خط مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> در اصطلاح هندسه، قسمتی است از کمیت متصله، و در پاره ای از حواشی تحریر اقلیدس آورده اند که برای اقسام کمیت متصله از خط و سطح و جسم و مکان و زمان اعظام گویند، چون پاره ای از اعظام را به پاره ای نسبت دهند و پاره ای را به پاره ای دیگر اندازه گیرند آنها را مقادیر نامند. (از کشاف اصطلاحات الفنون ).<br></font></div>'),
(184429, 'عظم', '<span class=\"hlight\">عظم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ظُ ]</font></b> (ع ص، اِ) ج ِعَظیم . (از ذیل اقرب الموارد). رجوع به عظیم شود.<br></font></div>'),
(184430, 'عظم', '<span class=\"hlight\">عظم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) (ذو...) عُرضی است از اعراض خیبر که در آنجا چشمه های جاری و نخلهای پربار است، و آن را به فتح اول نیز خوانده اند. (از معجم البلدان ). عَظم ؛ موضعی است . (منتهی الارب ).<br></font></div>'),
(184431, 'عظم', '<span class=\"hlight\">عظم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) جمیل بن مصطفی بن محمد حافظبن عبداﷲ، ملقب به عظم . از ادیبان دمشق و از اعضای المجمع العلمی العربی بود. وی به سال <span class=\"hlight\" dir=\"rtl\">١٢٩٠</span> هَ . ق . در اسلامبول متولد شد و در پنج سالگی پدر خود را از دست داد و با خانواده ٔ خود به دمشق آمد و زبان فارسی و ترکی را آموخت . او خطی زیبا داشت و نوشته های نظم و نثر او نیکو بود و مدتی روزنامه نگاری می کرد. عظم به سال <span class=\"hlight\" dir=\"rtl\">١٣٥٢</span> هَ . ق . در دمشق درگذشت . از جمله آثاراوست : تفریج الشدة فی تشطیر البردة. عثمان باشا الغازی . اتحاف الحبیب باوصاف الطیب، و غیره . (از الاعلام زرکلی به نقل از دلیل الاعارب و مخطوطات الظاهریة).<br></font></div>'),
(184432, 'عظما', '<span class=\"hlight\">عظما.</span> <font color=\"DarkGreen\"><b>[ ع ُ ظَ ]</font></b> (ع ص، اِ) عظماء. ج ِ عظیم . بزرگان . (از غیاث اللغات ). رجوع به عظماء شود.<br></font></div>'),
(184433, 'عظمات', '<span class=\"hlight\">عظمات .</span> <font color=\"DarkGreen\"><b>[ ع َ ظَ]</font></b> (ع اِ) ج ِ عَظَمة. (اقرب الموارد) (از منتهی الارب ). رجوع به عظمة شود. <BR><font color=\"Blue\">◄</font> عظمات القوم ؛ سرداران و مهتران قوم . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184434, 'عظمة', '<span class=\"hlight\">عظمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ظَ م َ ]</font></b> (ع اِمص ) بزرگی و کبر. (منتهی الارب ) (دهار). بزرگ شدن . (المصادر زوزنی ) (تاج المصادر بیهقی ) (دهار). کبر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناز و گردنکشی و نخوت . (منتهی الارب ). تکبر. (دهار). نخوت و زهو. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> عظمة اﷲ؛ بزرگواری خداوند متعال . (از ناظم الاطباء). استقلال و استغنای خداوند است از غیر، و آن در مورد عبد و مخلوق، ذم است . (از اقرب الموارد). به عظمةاﷲ چیزی وصف نگردد و هرگاه بنده و عبد بدان وصف شود ذم است .و گویند قول «عظمة اﷲ» سوگند است و برخی گویند هرگاه قصد سوگند شود، سوگند خواهد بود (از منتهی الارب ).<br>- <span class=\"hlight\">جلّت عظمته </span> ؛ بزرگ است عظمت او. آن را پس از ذکر خداوند متعال آرند <span class=\"hlight\">:</span> به نفس و همت و تقدیر ایزدی جلت عظمته ملک یافت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٨٧</span>).<br>- <span class=\"hlight\">عظمة الذراع </span> ؛ سطبری بازو. (از منتهی الارب ). ج، عَظَمات . (از اقرب الموارد) (از منتهی الارب ). رجوع به عظمات شود.<br>- <span class=\"hlight\">عظمة الساعد</span> ؛ آنچه از ساعد متصل آرنج است و عضله ناک باشد. (از منتهی الارب ) (ازاقرب الموارد) (از بحر الجواهر). سطبری در میان دست . (از دهار). ساعد به دو نیم شود، نیمی که متصل به آرنج است و عضله در آن است «عظمة» نامیده می شود و نیم دیگر را که متصل به کف است اسلة خوانند. (از اقرب الموارد) (از منتهی الارب ).<br>- <span class=\"hlight\">عظمة اللسان </span> ؛ آنچه سطبرباشد از زبان . (منتهی الارب ) (از اقرب الموارد) (از بحر الجواهر).<br></font></div>'),
(184435, 'عظمة', '<span class=\"hlight\">عظمة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع مص ) یک قطعه استخوان . (از اقرب الموارد). رجوع به عَظم شود.<br></font></div>'),
(184436, 'عظمة', '<span class=\"hlight\">عظمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ظِ م َ ]</font></b> (ع ص ) زن آزمند نره ٔ بزرگ . (منتهی الارب ). زنی که آزمند نره ٔ بزرگ و حریص بر آن باشد. (ناظم الاطباء) (از اقرب الموارد به نقل از تاج ).<br></font></div>'),
(184437, 'عظمة', '<span class=\"hlight\">عظمة.</span> <font color=\"DarkGreen\"><b>[ ع ُ م َ ]</font></b> (ع اِ) بالشچه ای که زنان بر سرین بندند تا کلان نماید. (منتهی الارب ). به معنی عِظامة است . (از اقرب الموارد). رجوع به عظامة شود.<br></font></div>'),
(184438, 'عظمة', '<span class=\"hlight\">عظمة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (اِخ ) یوسف بن ابراهیم بن عبدالرحمان، ملقب به عظمة. از شهیدان استقلال سوریه . به سال <span class=\"hlight\" dir=\"rtl\">١٣٠١</span> هَ .ق . در دمشق متولد شد و فنون جنگ را در آستانه آموخت و با رتبه ٔ «یوزباشی » فارغ التحصیل گشت . پس از جنگ بین المللی اول از همراهان امیر فیصل گشت و به سال <span class=\"hlight\" dir=\"rtl\">١٩٢٠</span>م . از طرف او وزیر جنگ سوریه شد و ارتشی ملی شامل ده هزار سرباز تشکیل داد. و در جنگی که بین ملیون سوریه با ارتش فرانسه به سال <span class=\"hlight\" dir=\"rtl\">١٣٣٨</span>هَ . ق . رخ داد شهید گشت و در همانجا دفن شد مقبره ٔ او رمز و نشانه ٔ فداکاری و وطن خواهی است . رجوع به الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٩</span> شود.<br></font></div>'),
(184439, 'عظمة', '<span class=\"hlight\">عظمة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع مص ) زدن استخوان را. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184440, 'عظمت', '<span class=\"hlight\">عظمت .</span> <font color=\"DarkGreen\"><b>[ ع َ ظَ م َ ]</font></b> (ع اِمص ) عظمة. بزرگی . (غیاث اللغات ). بزرگی و کلانی . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> بزرگواری و جاه و جلال و شوکت و حشمت و ابهت و شکوه . (ناظم الاطباء). قدر. (غیاث اللغات ). بزرگی قدر و مرتبه و بزرگواری . (فرهنگ فارسی معین ). ملک . جبروت . ملکوت . علو، تعالی . علاء. علی . اعتلاء. عز. عزت <span class=\"hlight\">:</span> کمال عظمت باری جل جلاله نشناسد. (کلیله و دمنه ).<br>پرتو نور از سرادقات جلالش <br>از عظمت ماورای فکرت دانا.<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> کبر و نخوت . (فرهنگ فارسی معین ).رجوع به عظمة شود.<br></font></div>'),
(184441, 'عظمت فروختن', '<span class=\"hlight\">عظمت فروختن .</span> <font color=\"DarkGreen\"><b>[ ع َ ظَ م َ ف ُ ت َ ]</font></b> (مص مرکب ) تکبر نمودن . نخوت فروختن . (فرهنگ فارسی معین ). رجوع به عظمت شود.<br></font></div>'),
(184442, 'عظمت قدرته', '<span class=\"hlight\">عظمت قدرته .</span> <font color=\"DarkGreen\"><b>[ ع َ ظُ م َ ق ُ رَ ت ُه ْ ]</font></b> (ع جمله ٔ فعلیه دعایی ) قدرت او بزرگ باد!: خدای عظمت قدرته . (یادداشت مرحوم دهخدا).<br></font></div>'),
(184443, 'عظموت', '<span class=\"hlight\">عظموت .</span> <font color=\"DarkGreen\"><b>[ ع َ ظَ]</font></b> (ع اِمص ) بزرگی و خودنمائی و ناز و گردن کشی و بزرگ منشی و نخوت . (منتهی الارب ). کبر و نخوت و زهو، و واوو تاء آن زائد است مبالغه را. (از اقرب الموارد).<br></font></div>'),
(184444, 'عظمی', '<span class=\"hlight\">عظمی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب به عظم . استخوانی . رجوع به عظم شود. <BR><font color=\"Blue\">◄</font> کبوتر که رنگش مایل به سپیدی باشد. (منتهی الارب ) (از اقرب الموارد). <br></font></div>'),
(184445, 'عظمی', '<span class=\"hlight\">عظمی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ما ]</font></b> (ع ن تف ) مؤنث اعظم . بزرگ و بزرگتر. (آنندراج ) (ناظم الاطباء). مصیبت عظمی . موهبت عظمی <span class=\"hlight\">:</span> در آن عرصه ٔ عظمی و انجمن کبری اول خطابی کند، سؤال از ایشان کند.(کشف الاسرار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٢٨</span>). عرض کرامت فرماید مشایخ کبار و سادات ابرار را در این مصیبت عظمی و داهیه ٔ کبری . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٦٠</span>). رجوع به اعظم شود.<br>- <span class=\"hlight\">وزارت عظمی </span>؛ مقام بزرگترین وزیران و مقام وزیر اول و صدر بزرگ . (ناظم الاطباء).<br></font></div>'),
(184446, 'عظو', '<span class=\"hlight\">عظو.</span> <font color=\"DarkGreen\"><b>[ ع َظْوْ ]</font></b> (ع مص ) زشت کردن . <BR><font color=\"Blue\">◄</font> هلاک نمودن به زهر خورانیدن . (از منتهی الارب ). بدی کردن به کسی و سؤقصد کردن به او و سم خورانیدن وی را. (از اقرب الموارد): لقاه اﷲ ماعظاه ؛ خداوند او را روبرو کند با آنچه بدی رساند او را. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> باز گردانیدن از نیکی . (از منتهی الارب ). منصرف کردن کسی را از خیر و نیکی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> غیبت کردن یا به زبان گرفتن کسی را و بد گفتن . (از منتهی الارب ). غیبت کردن یا به زبان گرفتن . (اقرب الموارد): لقی فلان ماعظاه و ما عجاه ؛ با سختی وشدت روبرو شد. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184447, 'عظوب', '<span class=\"hlight\">عظوب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) لازم گرفتن کسی را و شکیبائی کردن بر او. <BR><font color=\"Blue\">◄</font> قیام نمودن بر مال خود. <BR><font color=\"Blue\">◄</font> خشک شدن پوست . <BR><font color=\"Blue\">◄</font> درشت گردیدن دست از کار کردن . (از منتهی الارب ) (از اقرب الموارد). عَظب . رجوع به عظب شود.<br></font></div>'),
(184448, 'عظور', '<span class=\"hlight\">عظور.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) پرشکم از هر شراب که باشد. ج، عُظُر. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184449, 'عظوم', '<span class=\"hlight\">عظوم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) (ذات الَ ...) جایگاهی است در شعر حصین بن حمام . (از معجم البلدان ).<br></font></div>'),
(184450, 'عظی', '<span class=\"hlight\">عظی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) شتر آماسیده شکم از خوردن گیاه عنظوان . (از اقرب الموارد) (از منتهی الارب ). عَظ. عَظیان . و رجوع به عظ و عظیان شود.<br></font></div>'),
(184451, 'عظی', '<span class=\"hlight\">عظی .</span> <font color=\"DarkGreen\"><b>[ ع َ ظا <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ظَن ْ ]</font></b> (ع مص ) آماسیدن شکم شتر از خوردن گیاه عنظوان . (از اقرب الموارد). عَظا. (منتهی الارب ). رجوع به عظا شود.<br></font></div>'),
(184452, 'عظیان', '<span class=\"hlight\">عظیان .</span> <font color=\"DarkGreen\"><b>[ ع َ ظْ ]</font></b> (ع ص ) شتر آماسیده شکم از خوردن گیاه عنظوان . (منتهی الارب ) (از اقرب الموارد). عَظی . عَظ. و رجوع به عظ و عظی شود.<br></font></div>'),
(184453, 'عظیب', '<span class=\"hlight\">عظیب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ی َب ب ]</font></b> (ع ص ) عظیب الخَلق ؛ مرد بزرگ جثه . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عظیب الخُلق ؛ مرد بدخوی . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184454, 'عظیر', '<span class=\"hlight\">عظیر.</span> <font color=\"DarkGreen\"><b>[ ع ِظْ ی َرریا ع ِظْ ی َ ]</font></b> (ع ص ) کوتاه بالا. (منتهی الارب ). قصیر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> درشت اندام . (منتهی الارب ). قوی و سطبر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تند و ترنجیده . (منتهی الارب ). کَزّ. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بدخوی . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184455, 'عظیر', '<span class=\"hlight\">عظیر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ظَ ]</font></b> (اِخ ) چاههایی است از آن ضباب . و آبی است گوارا در سرزمین رمث بین قنة، که آن را عناقة گویند. (از معجم البلدان ).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(184456, 'عظیم', '<span class=\"hlight\">عظیم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) بزرگ و کلان و فربه . (منتهی الارب ). سترگ و بزرگ، خلاف صغیر. (از اقرب الموارد). در تداول فارسی به معانی کثیرو مهم و سخت و انبوه و بسیار و هنگفت و فراوان نیز بکار می رود. و هر گاه بر سر صفتی دیگر درآید حالت قید مقدار و کیفیت بخود میگیرد <span class=\"hlight\">:</span> اندر وی <font color=\"DarkGreen\"><b>[ اندر خوزستان ]</font></b> رودهای عظیم و آبهای روان است . (حدود العالم ). اندر وی پیلانند عظیم قوت . (حدود العالم ).<br>چگونه راهی راهی درازناک عظیم <br>همه سراسر سیلاب کند و خارا خار.<br> <font color=\"Red\">بهرامی .</font><br>باسرشک سخای تو کس را ننماید عظیم رود فرب .<br> <font color=\"Red\">عسجدی .</font><br>صحرای عظیمی بود، میان این دو تل امیر پیادگان را فروفرستاده با نیزه های دراز. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٨٧</span>). نصر احمد سامانی ... فرمانهای عظیم می داد از سر خشم . (تاریخ بیهقی ). خواجه بوالقاسم کثیر هر چند معزول بود اماجاهی و جلالی عظیم داشت . (تاریخ بیهقی ). رسول را آوردند و بگذرانیدند بر این تکلفهای عظیم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٩٠</span>). آن حدیث که دیروز گفتی عظیم بر دل ما اثر کرده است . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٢٦</span>).<br>جز به علمی نرهد مردم از این بند عظیم <br>کان نهفته است به تنزیل درون زیر حجاب .<br> <font color=\"Red\">ناصرخسرو.</font><br>و این زنگی عظیم بی ادب بود. (اسکندرنامه، نسخه ٔ سعید نفیسی ). پسر این شابه برموده نام بیامد با لشکری عظیم . (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٩٨</span>). وزیران این سخن عظیم بپسندیدند. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٦٧</span>). به تعجیل عظیم براند چنانک شابه آنگاه خبر یافت کی بهرام به بادغیس رسیده بود. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٩٨</span>). مرغزار کمه و سروات ... چهارپا را عظیم سود دارد. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١٥٥</span>). بر کار عمارت عظیم حریص بودندی . (نوروزنامه ). از بهر درد و آماس رحم پنبه بدان تر کنند و برگیرند، عظیم سود کند. (نوروزنامه ). کسری و حاضران شگفتی نمودند عظیم . (کلیله و دمنه ). کسری را به مشاهدت اثر رنجی که در بشره ٔ برزویه هر چند پیداتر بود رقتی عظیم آمد. (کلیله و دمنه ). از مشاهدات این حال در شگفتی عظیم افتادم . (کلیله و دمنه ). تعبد و تعفف در دفع شر جوشنی عظیم است . (کلیله و دمنه ). چه بزرگ غبنی و عظیم عیبی باشد. (کلیله و دمنه ).<br>ری نیک بد ولیک صدورش عظیم نیک <br>من شاکر صدور و شکایت فزای ری .<br> <font color=\"Red\">خاقانی .</font><br>آن طعن دشمن است ترا دوستی عظیم <br>کو نردبان تست به بام کمال بر.<br> <font color=\"Red\">خاقانی .</font><br>برفهای عظیم افتاد و کوه هامون را بینباشت . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٤٩</span>). از پس پشت میسره ٔ ابوعلی گردی عظیم برخاست . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٢١</span>). از سنگهای عظیم دیوار آن را برآورده . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤١٢</span>). این جمله رودهای عظیم است که سنگهای گران بگرداند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٠٩</span>). کس را اختیار کند که حق آن شغل عظیم و کارجسیم بشناسد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٧٩</span>).<br>آن کس که بیافت دولتی یافت عظیم <br>و آن کس که نیافت درد نایافت بس است .<br> <font color=\"Red\">شیخ مجدالدین بغدادی (از تاریخ گزیده ).</font><br>من کسی را دیدم در شبی که عظیم گرسنه بود لقمه ای پیش آوردند مگر شبهت آلود بود، ترک کرد. (تذکرةالاولیاء). بوتراب نخشبی رحمة اﷲ علیه مریدی داشت عظیم گرم و صاحب وجد. (تذکرةالاولیاء). حاکم این سخن را عظیم پسندید. (گلستان ). گوگرد پارسی به چین خواهم بردن که شنیده ام قیمتی عظیم دارد. (گلستان ). مطابق این سخن پادشاهی را مهمی عظیم پیش آمد.(گلستان ).<br>گرفت آتش خشم در وی عظیم <br>سرش خواست کردن چو جوزا دو نیم .<br> <font color=\"Red\">سعدی .</font><br>همچو گرد این تن خاکی نتواند برخاست <br>از سر کوی تو زان رو که عظیم افتاده ست .<br> <font color=\"Red\">حافظ.</font><br> <BR><font color=\"Blue\">◄</font> بزرگوار. (دهار). بزرگ قدر. والامقام . (فرهنگ فارسی معین ). بزرگ و بزرگوار. (مهذب الاسماء). ضد صغیر، و چه بسا که بر مقابل حقیر اطلاق شود. عظیم مافوق کبیر است چه عظیم، حقیر نمیتواند باشد زیرا از اضدادند اما کبیر ممکن است حقیر باشد چنانکه عظیم می تواند صغیر باشد زیرا ضد یکدیگر نیستند. عظیم بر قرب دلالت می کند و«علی » بر بعد و دوری . و فرق عظیم و کثیر را چنین گفته اند که «عظم » در ذات است «کثرة» از مفهوم عدد سخن میگوید. (از اقرب الموارد). ج، عِظام و عُظَماء. (دهار) (اقرب الموارد). و عُظُم . (از اقرب الموارد) <span class=\"hlight\">:</span> و لقد آتیناک سبعا من المثانی و القرآن العظیم . (قرآن <span class=\"hlight\" dir=\"rtl\">٨٧/١٥</span>). و دادیم ترا هفت آیه از مثانی و قرآن بزرگ را. هرگز مباد آنکه نخواهدت عظیم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٩١</span>). <BR><font color=\"Blue\">◄</font> صفتی از صفات باری تعالی و آن چنان است که قدر او از حد عقلها درگذرد آن سان که حقیقت و کنه وی به تصور نیاید. (از منتهی الارب ). نامی از نامهای خدای تعالی . (مهذب الاسماء) <span class=\"hlight\">:</span> سبحان ربی العظیم و بحمده ؛ منزه است خدای من او را می ستایم . حجاج پرسید که این عجوز چه می کند؟ گفتار و صبوری وی باز نمودند.. گفت سبحان اﷲ العظیم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٨٩</span>).<br>جمله بر خود حرام کرده بدی <br>هر چه مادون کردگار عظیم .<br> <font color=\"Red\">ناصرخسرو.</font><br>گفتا به عزت عظیم و صحبت قدیم که دم برنیارم و قدم برندارم . (گلستان سعدی ).<br>دست در دامن عفوت زنم و باک ندارم <br>که کریمی و حکیمی و عظیمی و قدیری .<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> (اِ) امیر و حاکم . (منتهی الارب ) <span class=\"hlight\">:</span> به مستقر زعیم و عظیم ایشان که به ابن سوری معروف بود راه وصول آسان کرد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٩٤</span>). <BR><font color=\"Blue\">◄</font> (ص ) قسمی از نبض، و آن وقتی است که نبض طویل و عریض و شاهق باشد. (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> حرکت چشم میل بسوی بیرون دارد و نبض عظیم باشد. (ذخیره ٔ خوارزمشاهی ). رجوع به عظیمی شود.<br></font></div>'),
(184457, 'عظیم', '<span class=\"hlight\">عظیم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ظَ ]</font></b> (ع اِ مصغر) مصغر عَظم . استخوان کوچک و خرد. رجوع به عظم شود. <BR><font color=\"Blue\">◄</font> عظیم وضاح یا عظم وضاح، بازیی است مر عربان را. (از منتهی الارب ) (ازتاج العروس ) (از اقرب الموارد). رجوع به عظم شود.<br></font></div>'),
(184458, 'عظیم', '<span class=\"hlight\">عظیم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان دیزمار باختری بخش ورزقان شهرستان اهر. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٣٥٤</span> تن است . آب آن از چشمه و محصول آن غلات وسردرختی و حبوب است . این ده محل ییلاق ایل اینانلو وحاجی علی لو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(184459, 'عظیم', '<span class=\"hlight\">عظیم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان شاه ولی شهرستان شوشتر. این ده مشهور به غضبان است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>). رجوع به غضبان شود.<br></font></div>'),
(184460, 'عظیم آباد', '<span class=\"hlight\">عظیم آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان فارسینج بخش اسدآباد شهرستان همدان . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٢٤</span> تن است . آب آن از قنات و محصول آن غلات، لبنیات، عسل و توتون است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(184461, 'عظیم آباد', '<span class=\"hlight\">عظیم آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان بیلوار بخش کامیاران شهرستان سنندج .دارای <span class=\"hlight\" dir=\"rtl\">١٩٦</span> تن سکنه . آب از چشمه و محصول آن غلات و لبنیات و توتون است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(184462, 'عظیم آباد', '<span class=\"hlight\">عظیم آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از دهستان شهسوار بخش میناب شهرستان بندرعباس . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> تن است . آب آن از رودخانه و محصول آن خرما و مرکبات . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(184463, 'عظیم آباد', '<span class=\"hlight\">عظیم آباد.</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام شهری است مشهور در هند که آن را پتنه هم خوانند. (آنندراج ). نام شهر پاتنا که پایتخت ایالت بهار از ممالک هندوستان است . (ناظم الاطباء).<br></font></div>'),
(184464, 'عظیم آباد حاجی محمود', '<span class=\"hlight\">عظیم آباد حاجی محمود.</span> <font color=\"DarkGreen\"><b>[ ع َ دِ م َ ]</font></b> (اِخ ) دهی جزء دهستان غار بخش ری شهرستان تهران . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢٣٣</span> تن است . آب آن از قنات و محصول آن غلات و صیفی و چغندر قند است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(184465, 'عظیم آباد معین الملک', '<span class=\"hlight\">عظیم آباد معین الملک .</span> <font color=\"DarkGreen\"><b>[ ع َ دِ م ُ نُل ْ م ُ ]</font></b> (اِخ ) دهی جزء دهستان غار بخش ری شهرستان تهران . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٠٢</span> تن است . آب آن از قنات و محصول آن غلات و صیفی و چغندرقند است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(184466, 'عظیم الترک و التبت', '<span class=\"hlight\">عظیم الترک و التبت .</span> <font color=\"DarkGreen\"><b>[ ع َ مُت ْ ت ُ ک ِ وَت ْ ت ُب ْب َ ]</font></b> (اِخ ) لقب ملک ختن بوده است . (حدود العالم ).<br></font></div>'),
(184467, 'عظیم کندی', '<span class=\"hlight\">عظیم کندی .</span><font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) دهی از دهستان ساری سوباسار بخش پلدشت شهرستان ماکو. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢٤٩</span> تن است . آب آن از ساری سو و زنکمار و محصول آن غلات، پنبه، توتون، کرچک، کنجد و حبوبات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>.)<br></font></div>'),
(184468, 'عظیمة', '<span class=\"hlight\">عظیمة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع ص ) مؤنث عظیم . بزرگ . و رجوع به عظیم شود. <BR><font color=\"Blue\">◄</font> کبیره . (اقرب الموارد). گناه بزرگ . <BR><font color=\"Blue\">◄</font> (اِ) سختی و بلای سخت . (منتهی الارب ) (از اقرب الموارد). ج، عَظائم . (اقرب الموارد).<br></font></div>'),
(184469, 'عظیمی', '<span class=\"hlight\">عظیمی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (حامص ) عظیم بودن .بزرگ بودن . <BR><font color=\"Blue\">◄</font> کلانی . <BR><font color=\"Blue\">◄</font> بسیاری . <BR><font color=\"Blue\">◄</font> عظیم بودن نبض <span class=\"hlight\">:</span> از بهر آنکه طبیعت جویان مراد باشد و نبض هم بدین سبب میل به عظیمی دارد. (ذخیره ٔ خوارزمشاهی ). رجوع به عظیم شود.<br></font></div>'),
(184470, 'عظیمی', '<span class=\"hlight\">عظیمی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) (<span class=\"hlight\" dir=\"rtl\">٤٨٣</span> - <span class=\"hlight\" dir=\"rtl\">٥٥٦</span> هَ .ق .) محمدبن علی بن محمدبن احمدبن نزار تنوخی جلی، مکنی به ابوعبداﷲ ومشهور به عظیمی . از فاضلان حلب و مدرسان آنجا بود. وبا ابن عساکر و سمعانی صحبتی داشت . او راست : تاریخ العظیمی، که ابن خلکان از آن استفاده کرده است . (از الاعلام زرکلی به نقل از کشف الظنون و اعلام النبلاء).<br></font></div>'),
(184471, 'عظیوط', '<span class=\"hlight\">عظیوط.</span> <font color=\"DarkGreen\"><b>[ ع ِظْ ی َ ]</font></b> (ع ص ) آنکه وقت جماع حدث کند. یا آنکه قبل از دخول انزال آیدش . (منتهی الارب ) (آنندراج ).<br></font></div>'),
(184472, 'عف', '<span class=\"hlight\">عف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِ صوت ) آواز سگ . (آنندراج ). عفعف . عفف . رجوع به عفعف و عفف شود.<br>- <span class=\"hlight\">عف کردن </span> ؛ عفعف کردن . آواز سگ کردن <span class=\"hlight\">:</span> <br>مژده ٔ عفو برای دل خود خواهد یافت <br>عاشقت را چو سگ کوی تو عف خواهد کرد.<br> <font color=\"Red\">ابونصر نصیرای بدخشانی (از آنندراج ).</font><br>گر چه که سگ عربده خندان کند<br>خنده و عف از بن دندان کند.<br><font color=\"Red\">میرخسرو (از آنندراج ).</font><br></font></div>'),
(184473, 'عف', '<span class=\"hlight\">عف .</span> <font color=\"DarkGreen\"><b>[ ع َف ف ]</font></b> (ع مص ) بازایستادن از حرام و پارسائی نمودن . (از منتهی الارب ). بازایستادن از زشتی . (تاج المصادر بیهقی ). خودداری و امتناع کردن از آنچه جایز و نیکو نباشد، خواه در گفتار خواه در کردار. (از اقرب الموارد). عَفاف . عَفافة. عِفّة. و رجوع به عفاف و عفافة شود. <BR><font color=\"Blue\">◄</font> فراهم آمدن شیر در پستان، یا باقی ماندن در آن . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184474, 'عف', '<span class=\"hlight\">عف .</span> <font color=\"DarkGreen\"><b>[ ع َف ف ]</font></b> (ع ص ) پارسا. (منتهی الارب ). خودداری کننده از انجام آنچه جایز و نیکو نباشد، خواه در کردار و خواه در گفتار. (از اقرب الموارد). عَفیف . ج، عَفَفة (منتهی الارب )، عَفّون، أعِفّة، اَعِفّاء. (اقرب الموارد).<br></font></div>'),
(184475, 'عفا', '<span class=\"hlight\">عفا.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) خرکره . (از اقرب الموارد). رجوع به عَفا شود.<br></font></div>'),
(184476, 'عفا', '<span class=\"hlight\">عفا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(ع اِ) زمین و شهر غفل که در وی پی کسی نیامده باشد. (منتهی الارب ). شهری که اثری از ملک برای کسی در آن نباشد. (از اقرب الموارد). زمینی که کسی در آن نرفته و آثار آبادی در وی نبود. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> خرکره . (منتهی الارب ). بچه ٔ حمیر را نامند و گفته اند یرنعام است . (فهرست مخزن الادویه ). ولد حمار. و آن را به کسر اول نیز خوانده اند. (از اقرب الموارد).<br>- <span class=\"hlight\">ابوالعفا</span> ؛ کنیه ٔ خر. (ناظم الاطباء). و رجوع به ابوالعفاء در ترکیبات عفاء شود.<br></font></div>'),
(184477, 'عفاا', '<span class=\"hlight\">عفاا.</span> <font color=\"DarkGreen\"><b>[ ع َ فَل ْ لاه ]</font></b> (ع جمله ٔ فعلیه ٔ دعایی، صوت مرکب ) مخفف عفااﷲ عنک، یا عفااﷲ عنه . خدا ببخشایاد! و آن در تداول فارسی در مورد تحسین بکار رود، و گاهی با «از» و«ز» همراه است . (از فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>اگر ماند ایدر ز تو نام زشت <br>نیابی عفااﷲ خرم بهشت .<br> <font color=\"Red\">فردوسی .</font><br>گرفتم درد دل بینی و جان دارو نفرمائی <br>عفااﷲ پرسشی فرمای کای بیمار من چونی .<br> <font color=\"Red\">خاقانی .</font><br>جهان سرای غرور است و دیو نفس هوا<br>عفااﷲ آنکه سبکبار و بیگناه برست .<br> <font color=\"Red\">سعدی .</font><br>عفااﷲ چین ابرویش اگر چه ناتوانم کرد<br>به عشوه هم پیامی بر سر بیمار می آورد.<br> <font color=\"Red\">حافظ.</font><br>هم عفااﷲ ز صبا کز تو پیامی می داد<br>ورنه در کس نرسیدیم که از کوی تو بود.<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">ای عفااﷲ</span> ؛ ای کسی که خداوند او راببخشاید! چون پدربیامرز. (از فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>معنی دعوت بسی بنموده ما را در حضور<br>ای عفااﷲ دعوی دعوات در غیبت چرا؟<br> <font color=\"Red\">سنائی .</font><br>ای عفااﷲ خواجگانی کز سر صفرای جاه <br>خوانده اند امروز اباداﷲ بر خضرای من .<br> <font color=\"Red\">خاقانی .</font><br>ناله ها کردم چنان کز چرخ بانگ آمد که بس <br>ای عفااﷲ در تو گوئی ذره ای زان درگرفت .<br> <font color=\"Red\">خاقانی .</font><br>آن زمان کز بهر دونان عشق او خلعت برید<br>ای عفااﷲ خود نصیب من کله واری نماند.<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عفااﷲ عما سلف </span> ؛ خداوند آنچه را گذشته است بخشید، و آن مقتبس از آیه ٔ <span class=\"hlight\" dir=\"rtl\">٩٦</span> سوره ٔ <span class=\"hlight\" dir=\"rtl\">٥</span> (المائدة) از قرآن کریم است، و در تداول فارسی زبانان به عنوان مثل به کار رود، نظیر: مضی مامضی، و بر گذشته ها صلوات . (از امثال و حکم دهخدا).<br>- <span class=\"hlight\">عفااﷲ عنک </span> ؛ خدا از گناهانت درگذرد! (فرهنگ فارسی معین ).<br>- <BR><font color=\"Blue\">◄</font> خدا ترا اصلاح کند و عزیز گرداند! (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عفااﷲ عنه </span> ؛ خداوند از او (مذکر) در گذرد. خدا گناهان او را ببخشایاد! (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عفااﷲ عنها</span> ؛ خداوند از او <font color=\"DarkGreen\"><b>[ مؤنث ]</font></b>، آنها <font color=\"DarkGreen\"><b>[ جمع ]</font></b> درگذرد. (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> دواعی انتقام ... باعث و محرض آمد بر آنک مواد فساد ملک ناصرالدین قباجه - عفااﷲ عنها- به کلی قطع کند. (جوامع الحکایات ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(184478, 'عفات', '<span class=\"hlight\">عفات .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) عفاة. ج ِ عافی . بخشندگان . آمرزندگان . رجوع به عافی و عفاة شود <span class=\"hlight\">:</span> <br>تو ناامید گشتی از عمر خویشتن <br>نومید شد به هر جااز تو عفات تو.<br><font color=\"Red\">مسعودسعد.</font><br></font></div>'),
(184479, 'عفادارمون', '<span class=\"hlight\">عفادارمون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) به یونانی حب القلقل است . (فهرست مخزن الادویه ).<br></font></div>'),
(184480, 'عفادله', '<span class=\"hlight\">عفادله .</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ ل َ ]</font></b> (اِخ ) دهی از دهستان مینوحی بخش قصبه معمره ٔ شهرستان آبادان . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن است . آب آن از شطالعرب و لوله کشی خسروآباد و محصول آن خرما و انگور است . ساکنان این ده از طایفه ٔ آل ابومصرف هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(184481, 'عفار', '<span class=\"hlight\">عفار.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) درخت که از وی آتش گیرند. (منتهی الارب ). بید سرخ ؛ ای درختی که از او آتش زنند. (دهار). درختی است که از آن زناد گیرند، واحد آن عفارة است . (از اقرب الموارد). در مثل گویند: کل ّ شجر نار استمجد المرخ و العفار؛ یعنی هر درختی آتش است اما مرخ و عفار بیشتر است، زیرا آتش زنه ٔ این دو درخت زودتر از دیگر درختان آتش را شعله ور می کند، و آن را در برتری دادن چیزی بر دیگری مثل زنند. (از اقرب الموارد) (از منتهی الارب ) <span class=\"hlight\">:</span> <br>زان بر فروز کامشب اندر حصار باشد<br>دور حصار میرا مرخ و عفار باشد.<br> <font color=\"Red\">منوچهری .</font><br>فاما همچو درخت مرغ و عفار هیچ درختی نیست که به اندک حرت از آن آتش می بارد. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٩</span>). <BR><font color=\"Blue\">◄</font> ثمر قاتل ابیه است . (مخزن الادویه ). <BR><font color=\"Blue\">◄</font> قطب . (تحفه ٔ حکیم مؤمن ) (مخزن الادویه ). <BR><font color=\"Blue\">◄</font> نان بی نانخورش . (از منتهی الارب ) (دهار) (از اقرب الموارد). نان تهی . قفار. (یادداشت مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> (مص ) گشن دادن و پیراستن خرمابنان را. (منتهی الارب ). تلقیح نخل و اصلاح آن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) پِست شورانیده بی شیرینی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِخ ) موضعی است میان مکه و طائف . (منتهی الارب ) (از معجم البلدان ).<br></font></div>'),
(184482, 'عفار', '<span class=\"hlight\">عفار.</span> <font color=\"DarkGreen\"><b>[ ع َف ْ فا ]</font></b> (ع ص ) گشنی دهنده ٔ خرمابنان . (منتهی الارب ).<br></font></div>'),
(184483, 'عفار', '<span class=\"hlight\">عفار.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ عُفر. (منتهی الارب ) (اقرب الموارد). رجوع به عُفر شود.<br></font></div>'),
(184484, 'عفاری', '<span class=\"hlight\">عفاری .</span> <font color=\"DarkGreen\"><b>[ ع َ را ]</font></b> (ع اِ) ج ِ عفریة. (ناظم الاطباء). رجوع به عفریة شود.<br></font></div>'),
(184485, 'عفاری', '<span class=\"hlight\">عفاری .</span> <font color=\"DarkGreen\"><b>[ ع ُ ی ی ]</font></b> (ع ص ) نیکو: نصل عفاری ؛ پیکان نیکو. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(184486, 'عفاریات', '<span class=\"hlight\">عفاریات .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) بندهای آب است در سواد عقیق . (منتهی الارب ) (از تاج العروس ) (از اقرب الموارد) (از معجم البلدان ).<br></font></div>'),
(184487, 'عفاریة', '<span class=\"hlight\">عفاریة.</span> <font color=\"DarkGreen\"><b>[ ع َ ی َ ]</font></b> (ع اِ) ج ِ عفریة. (منتهی الارب ) (اقرب الموارد). رجوع به عفریة و عفریت شود.<br></font></div>'),
(184488, 'عفاریة', '<span class=\"hlight\">عفاریة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ی َ ]</font></b> (ع ص ) مرد سخت پلید. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اسد عفاریة؛ شیر درشت خلقت توانا. (منتهی الارب ). شیر سخت و شدید. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) کوهی است سرخ فام در سیالة. (از معجم البلدان ).<br></font></div>'),
(184489, 'عفاریت', '<span class=\"hlight\">عفاریت .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عفریت . (منتهی الارب ) (اقرب الموارد). دیوان . اهریمنان . رجوع به عفریت شود <span class=\"hlight\">:</span> عفاریت گفتنداندیشه مدار که ایزدتعالی آدمی را به هفت طبقه آفرید. (تاریخ سیستان ص <span class=\"hlight\" dir=\"rtl\">٥٩</span>). رجاله ٔ دیلم و عفاریت افغانیان بر ایشان آغالید. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٥٠</span>).<br>- <span class=\"hlight\">عفاریت آثار</span> ؛ کسانی که کردارشان مانند دیو بود. (ناظم الاطباء).<br></font></div>'),
(184490, 'عفارین', '<span class=\"hlight\">عفارین .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عِفرین . (اقرب الموارد). رجوع به عفرین شود.<br></font></div>'),
(184491, 'عفاز', '<span class=\"hlight\">عفاز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) چهار مغز مأکول . (منتهی الارب ). گردو. (ناظم الاطباء). جوز و گردوی خوردنی، یک دانه ٔ آن عفازة باشد. (از اقرب الموارد).<br></font></div>'),
(184492, 'عفاس', '<span class=\"hlight\">عفاس .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) فساد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِخ ) نام ماده شتری «راعی » شاعر را. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184493, 'عفاش', '<span class=\"hlight\">عفاش .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) مرد وافر و انبوه ریش . (از منتهی الارب ).<br></font></div>'),
(184494, 'عفاص', '<span class=\"hlight\">عفاص .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) پوست پاره ای که سر خنور بدان بندند و خنور و جز آن از چرم باشد، یا از غیر آن که در آن نفقه نهند. (منتهی الارب ). وعاء و ظرفی که نفقه در آن باشد، از پوست یا از پارچه . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> غلاف قاروره . (منتهی الارب ). غلاف قارورة و گویند آن پوستی است که قاروره را بدان سرپوش نهند، اما آنچه در دهانه ٔقاروره وارد می شود، صمام است . (از اقرب الموارد).<br></font></div>'),
(184495, 'عفاضج', '<span class=\"hlight\">عفاضج .</span> <font color=\"DarkGreen\"><b>[ ع ُ ض ِ ]</font></b> (ع ص ) فربه سست گوشت . (منتهی الارب ). ضخم و فربه و سست . (از اقرب الموارد). عَفضَج . عِفضاج . رجوع به عفضاج و عفضج شود.<br></font></div>'),
(184496, 'عفاط', '<span class=\"hlight\">عفاط.</span> <font color=\"DarkGreen\"><b>[ ع َ ف ف ]</font></b> (ع ص ) درمانده به سخن . (منتهی الارب ). الکن . (اقرب الموارد).<br></font></div>'),
(184497, 'عفاطی', '<span class=\"hlight\">عفاطی .</span> <font color=\"DarkGreen\"><b>[ ع ِ طی ی ]</font></b> (ع ص ) درمانده به سخن . (منتهی الارب ).الکن . (اقرب الموارد). عَفّاط. رجوع به عفاط شود.<br></font></div>'),
(184498, 'عفاف', '<span class=\"hlight\">عفاف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) باز ایستادن از حرام و پارسائی نمودن . (از منتهی الارب ). خودداری و امتناع از آنچه جایز و نیکو نباشد، خواه در گفتار باشد خواه در کردار. (از اقرب الموارد). باز ایستادن . (آنندراج ). نهفتگی کردن . (المصادر زوزنی ). باز ایستادن از زشتی . (دهار). عَف ّ. عَفافة. عِفّة. و رجوع به عف و عفافة و عفة شود. <BR><font color=\"Blue\">◄</font> باد سخت آمدن . (المصادر زوزنی ). <BR><font color=\"Blue\">◄</font> تیز دادن . (بحر الجواهر).<br></font></div>'),
(184499, 'عفاف', '<span class=\"hlight\">عفاف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِمص ) پارسائی و پرهیزگاری . (غیاث اللغات ). نهفتگی . (دهار). پاکدامنی . خویشتن داری . عفت . تعفف <span class=\"hlight\">:</span> <br>ز مجد گوید چون عابد از عفاف سخن <br>ز ظلم جوید چون عاشق از فراق فرار.<br> <font color=\"Red\">ابوحنیفه ٔ اسکافی (از تاریخ بیهقی ).</font><br>رفیق خویش صلاح و عفاف را ساختم . (کلیله و دمنه ). پسندیده تر سیرتها آن است که به تقوی و عفاف کشد. (کلیله و دمنه ). عفاف و تقوی ... که ذات شریف او بدان ممتازبود هیچکس را از امراء بنی العباس مجتمع نبود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٨٠</span>). راه صلاح و عفاف پیش گرفتند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٣٨</span>). راه اصلاح و عفاف پیش گرفتند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٣٨</span>). مشغول کفاف از دولت عفاف محروم است . (گلستان سعدی ).<br></font></div>'),
(184500, 'عفاف', '<span class=\"hlight\">عفاف .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b>(ع اِ) دارو. (منتهی الارب ). دواء. (اقرب الموارد).<br></font></div>'),
(184501, 'عفاف', '<span class=\"hlight\">عفاف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دختر احمدبن محمدبن اخوة. از زنان محدث بود و از ابوعبداﷲبن طلحة نعالی و دیگران حدیث آموخت و به سال <span class=\"hlight\" dir=\"rtl\">٥٤٤</span> هَ . ق . درگذشت . (از اعلام النساء از التحبیر سمعانی ).<br></font></div>'),
(184502, 'عفافة', '<span class=\"hlight\">عفافة.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع مص ) به معنی مصدر عَف ّ و عَفاف است . (از منتهی الارب ) (از اقرب الموارد). بازایستادن از زشتی . (تاج المصادر بیهقی ) (دهار). بازایستادن . (آنندراج ). رجوع به عف و عفاف شود.<br></font></div>'),
(184503, 'عفافة', '<span class=\"hlight\">عفافة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ف َ ]</font></b> (ع اِ) اسم است مصدر عَف ّ را به معنی فراهم آمدن و گرد آمدن شیر در پستان، و گویند باقی ماندن آن است در پستان . (از اقرب الموارد). و رجوع به عَف ّ شود. <BR><font color=\"Blue\">◄</font> شیر فراهم آمده . باقی مانده ٔ شیر در پستان . (منتهی الارب ). باقیمانده ٔ شیر در پستان پس از آنکه اکثر آن نوشیده شده باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) آبی است بنی نمیر را. (از معجم البلدان ).<br></font></div>'),
(184504, 'عفاق', '<span class=\"hlight\">عفاق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) ابن مری . شخصی است که احدب بن عمرو باهلی در خشک سالی او را گرفته بریان کرد و بخورد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184505, 'عفاق', '<span class=\"hlight\">عفاق .</span> <font color=\"DarkGreen\"><b>[ ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ]</font></b> (ع مص ) بسیار دوشیدن ناقه . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتاب رفتن . (منتهی الارب ). بسرعت رفتن . (از اقرب الموارد).<br></font></div>'),
(184506, 'عفال', '<span class=\"hlight\">عفال .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ ]</font></b> (ع اِ) دشنام است مر زنان را. (منتهی الارب ). شتم است زن را و آن خاص نداست . گویند: یا عفال . (از اقرب الموارد).<br></font></div>'),
(184507, 'عفان', '<span class=\"hlight\">عفان .</span> <font color=\"DarkGreen\"><b>[ ع َف ْ فا ]</font></b> (اِخ ) ابن مسلم بن عبداﷲ صفار، مکنی به ابوعثمان . از حافظان حدیث و مورد اعتماد بود. وی از اهالی بصره بود به سال <span class=\"hlight\" dir=\"rtl\">١٣٤</span> هَ . ق .متولد شد و ساکن بغداد گشت . هنگامی که مأمون خلیفه ٔعباسی قول به خلق قرآن را اظهار داشت، گفت تا از عفان نیز در این مورد سؤال شود و اگر آن را نپذیرد مقرری او را که پانصد درهم در ماه بود قطع کنند. عفان چون این بشنید در جواب گفت «و فی السماء رزقکم و ما توعدون » و از پذیرفتن عقیده ٔ مأمون خودداری کرد و گویند وی نخستین کسی است که در این راه صدمه دید. او را از مشایخ اسلام و ائمه ٔاعلام به حساب آورده اند و وی به سال <span class=\"hlight\" dir=\"rtl\">٢٢٠</span> هَ . ق . در بغداد درگذشت . (از الاعلام زرکلی به نقل از تهذیب التهذیب ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> و میزان الاعتدال ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٢</span> و تاریخ بغداد ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٩</span>). رجوع به صفوة الصفوة ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣</span> شود.<br></font></div>'),
(184508, 'عفان', '<span class=\"hlight\">عفان .</span> <font color=\"DarkGreen\"><b>[ ع َف ْ فا ]</font></b> (اِخ ) ابن ابی العاص . نام پدر عثمان خلیفه ٔ سوم است . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184509, 'عفان', '<span class=\"hlight\">عفان .</span> <font color=\"DarkGreen\"><b>[ ع ِف ْ فا ]</font></b> (ع اِ) عفان الشی ٔ، وقت آن چیز. گویند جاء علی عفانه ؛یعنی در وقت آن آمد. (از منتهی الارب ) (از اقرب الموارد). و آن لغتی است در «افان ». (از اقرب الموارد).<br></font></div>'),
(184510, 'عفان', '<span class=\"hlight\">عفان .</span> <font color=\"DarkGreen\"><b>[ ع َف ْ فا ]</font></b> (اِخ ) از اعلام است، منصرف و غیرمنصرف . (از منتهی الارب ). اگر آن را وزن فعلان از ریشه ٔعف بدانیم مالاینصرف خواهد بود به سبب زیادت نون، و اگر آن را وزن فعال از ریشه عفن فرض کنیم، منصرف خواهد بود به سبب اصلی بودن نون . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) چشمه ای است در سند. (منتهی الارب ).<br></font></div>'),
(184511, 'عفانش', '<span class=\"hlight\">عفانش .</span> <font color=\"DarkGreen\"><b>[ ع ُ ن ِ ]</font></b>(ع ص ) عفانش اللحیة؛ سطبر و بسیارموی ریش . (منتهی الارب ) (از اقرب الموارد). عُفنّش . رجوع به عفنش شود.<br></font></div>'),
(184512, 'عفاهم', '<span class=\"hlight\">عفاهم .</span> <font color=\"DarkGreen\"><b>[ ع ُ هَِ ]</font></b> (ع ص ) شتر ماده ٔ توانای چست و تیزرو. <BR><font color=\"Blue\">◄</font> فراخی عیش . <BR><font color=\"Blue\">◄</font> دویدگی سخت . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184513, 'عفاهن', '<span class=\"hlight\">عفاهن .</span> <font color=\"DarkGreen\"><b>[ ع ُهَِ ]</font></b> (ع ص ) شتر ماده ٔ زورمند چست و چالاک . (منتهی الارب ) (از اقرب الموارد). عفاهم . رجوع به عفاهم شود.<br></font></div>'),
(184514, 'عفاهیة', '<span class=\"hlight\">عفاهیة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ی َ ]</font></b> (ع ص ) سطبر دفزک . (منتهی الارب ). ضخم . (اقرب الموارد).<br></font></div>'),
(184515, 'عفاک ا', '<span class=\"hlight\">عفاک ا.</span> <font color=\"DarkGreen\"><b>[ ع َ کَل ْ لاه ]</font></b> (ع جمله ٔ فعلیه ٔ دعایی، صوت مرکب ) خداوند ترا ببخشایاد! و آن در موقع دعاو تحسین بکار رود. (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>هلاکم کردی از تیمارخواری <br>عفاک اﷲ زهی تیمارداری .<br> <font color=\"Red\">نظامی .</font><br>بدم گفتی و خرسندم عفاک اﷲ نکو گفتی <br>سگم خواندی وخشنودم جزاک اﷲ کرم کردی . <br> <font color=\"Red\">سعدی .</font><br>چه شکر گویمت ای خیل غم عفاک اﷲ<br>که روز بی کسی آخر نمی روی ز سرم .<br><font color=\"Red\">حافظ.</font><br></font></div>'),
(184516, 'عفاید', '<span class=\"hlight\">عفاید.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) به سریانی مغاث است . (فهرست مخزن الادویه ).<br></font></div>'),
(184517, 'عفة', '<span class=\"hlight\">عفة.</span> <font color=\"DarkGreen\"><b>[ ع ُف ْف َ ]</font></b> (ع اِ) باقی شیر در پستان . (منتهی الارب ). باقی شیر در پستان چهارپایان پس از اینکه بچه ٔ آنها غالب آن را مکیده باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گنده پیر. (منتهی الارب ). عجوز. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ماهیی است بی پشیز کوچک سپیدرنگ، مطبوخ آن به ذائقه ٔ برنج ماند. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184518, 'عفة', '<span class=\"hlight\">عفة.</span> <font color=\"DarkGreen\"><b>[ ع َف ْ ف َ ]</font></b> (ع ص ) مؤنث عَف ّ. (منتهی الارب ) (از اقرب الموارد). زن پارسا. (ناظم الاطباء). ج، عَفّات . (اقرب الموارد). رجوع به عَف ّ شود.<br></font></div>'),
(184519, 'عفة', '<span class=\"hlight\">عفة.</span> <font color=\"DarkGreen\"><b>[ ع ِف ْ ف َ ]</font></b> (ع مص ) به معنی مصدر عَفاف است . (از منتهی الارب ) (از اقرب الموارد). از حرام بازاستادن و پرهیزگاری کردن . (مقدمة اللغةمیر سیدشریف جرجانی ). نهفتگی کردن . (المصادر زوزنی ). بازایستادن از زشتی . (دهار). رجوع به عَفاف شود.<br></font></div>'),
(184520, 'عفة', '<span class=\"hlight\">عفة.</span> <font color=\"DarkGreen\"><b>[ ع ِف ْ ف َ ]</font></b> (ع اِمص ) عفت . ترک شهوات در هر چیز، و در بین نصرانیان بیشتر بر ترک شهوات بدنی و پاکیزگی جسد و «تبتل » اطلاق شود. (از اقرب الموارد). پارسائی و احتراز از محرمات خصوصاً از شهوات حرام . (از آنندراج ). پارسائی و نهفتگی . (دهار). هیئتی است قوه ٔ شهویه را متوسط بین فجور، که افراط در آن قوه است و خمود، که تفریط آن است . (از تعریفات جرجانی ). رجوع به عفّت شود.<br></font></div>'),
(184521, 'عفت', '<span class=\"hlight\">عفت .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) برتافتن . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> شکستن بی متفرق و جدا ساختن .(از منتهی الارب ). پیچاندن . و شکاندن چیزی را. شکاندن بدون از هم جدا ساختن . (از اقرب الموارد). برنجانیدن دست تا بشکند. (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> دست برتافتن کسی را. <BR><font color=\"Blue\">◄</font> شکسته گفتن سخن رااز لکنت زبان . و تکلف نمودن در عربیت . (از منتهی الارب ). شکستن از لکنت . (تاج المصادر بیهقی ). تکلف کردن در عربیت و فصیح نشدن، و گویند پیچاندن سخن را از راه خود و شکستن آن به جهت لکنت . (از اقرب الموارد).<br></font></div>'),
(184522, 'عفت', '<span class=\"hlight\">عفت .</span> <font color=\"DarkGreen\"><b>[ ع ِف ْ ف َ ]</font></b> (ع اِمص ) عفة. نهفتگی و پاکدامنی . (مهذب الاسماء). پرهیزگاری و پارسائی . و احتراز از محرمات خصوصاً از شهوات حرام . (از غیاث اللغات ). یکی از فضایل اربعه نزد قدما (حکمت، شجاعت، عفت، عدالت ). هیئتی که مر نیروی شهوت راست و واسطه ٔ بین فجور و خموراست و گفته اند که عفت ترک شهوت است نسبت به هر چیزی که تصور رود از امور و مشتهیات نفسانی در این جهان .(از کشاف اصطلاحات الفنون ). یکی از کیفیات نفسانیه است و از اقسام خلقیات می باشد، و آن خلقی است که افعال متوسط بین فجور و خمود از آن صادر می شود، و خمود وفجور و طرف لذت اند و از رذائل اند. و گویند عفت آن است که قوت شهوت مطیع نفس ناطقه باشد تا تصرف او به اقتضای رأی او بود و اثر خیریت در او ظاهر شود و از تعبد هوای نفس و استخدام لذات فارغ . (از فرهنگ علوم عقلی از اسفار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨</span> و اخلاق ناصری ص <span class=\"hlight\" dir=\"rtl\">٧٤</span>). اعتدال در قوه ٔ شهویه . پاکی . طهارت . زهد. تقوی . حیا. شرمساری . عفاف . کف نفس . تعفف . و رجوع به عفة شود <span class=\"hlight\">:</span> <br>با چهره ماه و طینت زهره <br>با زهره شیر و عفت زهرا.<br> <font color=\"Red\">منوچهری .</font><br>نگاه باید کرد تا احوال ایشان بر چه جمله رفته است و میرود در عدل و خوبی سیرت و عفت و دیانت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٩٤</span>). هرچند در ثمرات عفت تأمل بیش کردم رغبت من در اکتساب آن زیادت گشت . (کلیله و دمنه ).<br>- <span class=\"hlight\">باعفت </span> ؛ پارسا و زاهد و پاکدامن و با شرم و حیا وپرهیزکار. (ناظم الاطباء).<br>- <span class=\"hlight\">بی عفت </span> ؛ بی شرم و حیا.<br>- <span class=\"hlight\">بی عفتی </span> ؛ بی شرمی . بی حیایی .<br></font></div>'),
(184523, 'عفتان', '<span class=\"hlight\">عفتان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) به معنی عِفِتّان است . (از اقرب الموارد). رجوع به عفتان شود.<br></font></div>'),
(184524, 'عفتان', '<span class=\"hlight\">عفتان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ف ِت ْ تا ]</font></b> (ع ص ) مرد توانا فربه و پرگوشت و گرداندام . درشت خلقت زورمند. (از منتهی الارب ). بر وزن و معنی صفتان است، و آن را با یاء نسبت نیز بکار برند مبالغه را وعِفتّانی گویند. و برخی آن را بصورت عِفْتان خوانده اند به معنی سخت و قوی و چابک . (از اقرب الموارد).<br></font></div>'),
(184525, 'عفتانی', '<span class=\"hlight\">عفتانی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ف ِت ْ تا نی ی ]</font></b> (ع ص ) به معنی عفتّان است . (منتهی الارب ) (از اقرب الموارد). رجوع به عِفتّان شود.<br></font></div>'),
(184526, 'عفج', '<span class=\"hlight\">عفج .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) زدن . (از منتهی الارب ) (از اقرب الموارد). عصا زدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> گائیدن . (از منتهی الارب ). جماع کردن . (المصادر زوزنی ) (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> زدن جامه را معفاج . (از منتهی الارب ). و رجوع به معفاج شود. <BR><font color=\"Blue\">◄</font> فعل قوم لوط کردن . (از منتهی الارب ).<br></font></div>'),
(184527, 'عفج', '<span class=\"hlight\">عفج .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع مص ) بزرگ وفربه شدن روده ٔ کسی . (منتهی الارب ) (از اقرب الموارد). و چنین شخصی را عَفِج گویند. (از اقرب الموارد).<br></font></div>'),
(184528, 'عفج', '<span class=\"hlight\">عفج .</span> <font color=\"DarkGreen\"><b>[ ع َ ف ِ ]</font></b> (ع ص ) آنکه روده های او بزرگ و فراخ باشد. (از اقرب الموارد). و رجوع به عَفَج شود. <BR><font color=\"Blue\">◄</font> (اِ) به معنی عِفج است . رجوع به عِفج شود.<br></font></div>'),
(184529, 'عفج', '<span class=\"hlight\">عفج .</span> <font color=\"DarkGreen\"><b>[ ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ف ِ ]</font></b> (ع اِ) روده ٔ مردم و اسب و سباع که طعام از معده بدان نقل کند، و آن مصارین است برای سم داران و سپل داران . (از منتهی الارب ).رودگان فراخ . (زمخشری ). هزارخانه و رودگانی . (دهار). رودگان و معی، و گویند آن گوشتی است در نزدیکی روده در طبقه ٔ داخلی روده ٔ راست . (از بحر الجواهر). آنچه طعام بدان منتقل می شود پس از معده، و آن برای انسان و تمام سباع به منزله ٔ روده ها است برای سم داران و سپل داران که به کرش می پیوندند. (از اقرب الموارد). آن روده که طعام از معده در آن داخل می گردد. (ناظم الاطباء). ج، أعفاج . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184530, 'عفد', '<span class=\"hlight\">عفد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) هر دوپای فراهم آورده برجستن . (از منتهی الارب ).دو پای را در کنار هم قرار دادن و جهیدن بدون دویدن . (از اقرب الموارد). عَفَدان . رجوع به عفدان شود.<br></font></div>'),
(184531, 'عفد', '<span class=\"hlight\">عفد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) کبوتر، یا مرغی است شبیه کبوتر. (منتهی الارب ) (از اقرب الموارد) (از فهرست مخزن الادویه ).<br></font></div>'),
(184532, 'عفدان', '<span class=\"hlight\">عفدان .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع مص ) به معنی مصدر عَفد است .(منتهی الارب ) (از اقرب الموارد). رجوع به عفد شود.<br></font></div>'),
(184533, 'عفر', '<span class=\"hlight\">عفر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) شب هفتم و هشتم و نهم ماه . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) مرد دلیر چست و شاطر. (منتهی الارب ). شجاع و جلد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سطبر درشت اندام و توانا. (منتهی الارب ). غلیظ و شدید. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بازار کاسد. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خوک نر، یا عام است و یا بچه ٔ خوک . (از اقرب الموارد).ج، أعف-ار و عِفار. (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(184534, 'عفر', '<span class=\"hlight\">عفر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) ریگها است در بادیه به بلاد قیس . (منتهی الارب ). رمالی است در بادیه در بلاد قیس . و گویند نجد عفر، جایگاهی است در نزدیکی مکه . (از معجم البلدان ).<br></font></div>'),
(184535, 'عفر', '<span class=\"hlight\">عفر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ف ُ ]</font></b> (ع اِ) روزگار، و هنگام، و ماه . (منتهی الارب ). حین، و گویند ماه . (از اقرب الموارد).<br></font></div>'),
(184536, 'عفر', '<span class=\"hlight\">عفر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) خاک . (منتهی الارب ). تراب . (فهرست مخزن الادویه ). روی خاک . ظاهر و روی خاک . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دشواری و سختی : کلام لاعفر فیه ؛ سخنی که پیچیدگی و دشواری در آن نباشد. (از اقرب الموارد). عَفَر. (منتهی الارب ). رجوع به عَفَر شود.<br></font></div>'),
(184537, 'عفر', '<span class=\"hlight\">عفر.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع اِ) خاک، و روی خاک . (منتهی الارب ). رویه و سطح زمین : ماعلی عفرالارض مثله و خاک را نیز گویند. (از اقرب الموارد). ج، أعفار. <BR><font color=\"Blue\">◄</font> اول آب که کشت را دهند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تیرها که مخاطالشیطان نامند آنرا. (منتهی الارب ). «سهام » و تار عنکبوت که آن رامخاطالشیطان نامند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سختگی و اشکال : کلام لاعفر فیه ؛ سخنی که عویص و اشکال در آن نباشد. (از منتهی الارب ). عَفر. (اقرب الموارد). و رجوع به عَفر شود.<br></font></div>'),
(184538, 'عفر', '<span class=\"hlight\">عفر.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع مص ) سپید سرخی مایل گردیدن آهو، یاسرخ پشت و سپیدشکم گشتن آن . (از منتهی الارب ). «أعفر»شدن آهو، و گویند رنگ او شبیه رنگ «عفر» و خاک شدن .(از اقرب الموارد). و رجوع به أعفر و عَفَر شود.<br></font></div>'),
(184539, 'عفر', '<span class=\"hlight\">عفر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) در خاک مالیدن . (المصادر زوزنی ) (تاج المصادر بیهقی ). در خاک غلطانیدن و خاک آلوده کردن . <BR><font color=\"Blue\">◄</font> زیر خاک دفن نمودن و پنهان کردن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بر زمین زدن چیزی را. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کشت را برای بار اول آب دادن، گویند عفرالزرع . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آسوده شدن از لقاح نخل . (از اقرب الموارد). گشن دادن خرما. (المصادر زوزنی ) (تاج المصادر بیهقی ).<br></font></div>'),
(184540, 'عفر', '<span class=\"hlight\">عفر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ عَفراء. (منتهی الارب ). رجوع به عفراء شود. <BR><font color=\"Blue\">◄</font> ج ِ أعفَر. (ناظم الاطباء). رجوع به اعفر شود.<br></font></div>'),
(184541, 'عفر', '<span class=\"hlight\">عفر.</span> <font color=\"DarkGreen\"><b>[ ع ِ ف ِرر ]</font></b> (ع ص ) مردپلید. (منتهی الارب ). خبیث و منکر. (اقرب الموارد).<br></font></div>'),
(184542, 'عفر', '<span class=\"hlight\">عفر.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) مرد نیک خبیث کربز. (منتهی الارب ). خبیث و منکر. (اقرب الموارد).مردم سخت بد. (دهار). <BR><font color=\"Blue\">◄</font> اسد عفر؛ شیر درشت . (منتهی الارب ). شیر سخت و شدید. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) خوک نر، یا عام است، یا بچه ٔ خوک . (منتهی الارب ) (از اقرب الموارد). خوک، و مؤنث آن عفرة است . (از دهار). خنزیر. (فهرست مخزن الادویه ).<br></font></div>'),
(184543, 'عفرا', '<span class=\"hlight\">عفرا.</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) عفراء. نام معشوقه ٔ عروه است . (غیاث اللغات ) (برهان ). رجوع به عفراء (دختر مهاصر...) شود.<br></font></div>'),
(184544, 'عفراس', '<span class=\"hlight\">عفراس .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) شیر بیشه ٔ قوی و توانا. (منتهی الارب ). اسد. (اقرب الموارد).<br></font></div>'),
(184545, 'عفربلا', '<span class=\"hlight\">عفربلا.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب َ ]</font></b> (اِخ ) شهری است در غور اردن در نزدیکی بیسان و طبریه . (از معجم البلدان ).<br></font></div>'),
(184546, 'عفرجع', '<span class=\"hlight\">عفرجع.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ج َ ]</font></b> (ع ص ) مرد بدخوی زشت سیرت . (منتهی الارب ). سیّی ءالخلق . (اقرب الموارد).<br></font></div>'),
(184547, 'عفرزان', '<span class=\"hlight\">عفرزان .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َرْ رَ ]</font></b> (اِخ ) نام مخنثی است در بصره . (از منتهی الارب ).<br></font></div>'),
(184548, 'عفرس', '<span class=\"hlight\">عفرس .</span> <font color=\"DarkGreen\"><b>[ ع ِ رِ ]</font></b> (ع اِ) شیر بیشه ٔ قوی و توانا. (منتهی الارب ). اسد. (از اقرب الموارد).<br></font></div>'),
(184549, 'عفرسة', '<span class=\"hlight\">عفرسة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ س َ ]</font></b> (ع مص ) بر زمین افکندن کسی را. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چیره شدن بر کسی . (از منتهی الارب ). غالب شدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دریدن شیر کسی را. (از منتهی الارب ).<br></font></div>'),
(184550, 'عفرن', '<span class=\"hlight\">عفرن .</span> <font color=\"DarkGreen\"><b>[ ع ِ ف َ ]</font></b> (ع اِ) شیر بیشه . (منتهی الارب ). اسد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) پلید. (منتهی الارب ).<br></font></div>'),
(184551, 'عفرنس', '<span class=\"hlight\">عفرنس .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ن َ ]</font></b> (ع ص، اِ) شیر سخت و توانا. (منتهی الارب ). اسد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتردرشت و سطبرگردن . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184552, 'عفرنون', '<span class=\"hlight\">عفرنون .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ن َ ]</font></b> (ع ص، اِ) ج ِ عَفَرنی ̍. (اقرب الموارد). رجوع به عفرنی ̍ شود.<br></font></div>'),
(184553, 'عفرنی', '<span class=\"hlight\">عفرنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ نا ]</font></b> (ع اِ) اسد و شیر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) شیر درشت اندام . (منتهی الارب ). اسد عفرنی ؛ شیر شدید و سخت . (از اقرب الموارد). لبوة عفرنی ؛ ماده شیر استوارخلقت . (منتهی الارب ). ماده شیر شدید و سخت . (از اقرب الموارد). نون و الف آن زائد است الحاق را. (از منتهی الارب ) (از اقرب الموارد). ج، عَفَرنَون . (اقرب الموارد).<br></font></div>'),
(184554, 'عفرنیات', '<span class=\"hlight\">عفرنیات .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ن َ ]</font></b> (ع ص، اِ) ج ِ عَفَرناة. (اقرب الموارد). رجوع به عفرناة شود.<br></font></div>'),
(184555, 'عفرنیة', '<span class=\"hlight\">عفرنیة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ف َ ی َ ]</font></b> (ع ص ) مرد خبیث کربز. (منتهی الارب ). خبیث منکر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) موی میانه ٔ سر. (منتهی الارب ). تک مویهایی که در وسط سر روئیده باشد. (از اقرب الموارد).<br></font></div>'),
(184556, 'عفرودیت', '<span class=\"hlight\">عفرودیت .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) معرب آفردیت رب النوع زیبایی در یونان باستان . ونوس . (از فرهنگ فارسی معین ). رجوع به آفرودیت و ونوس شود.<br></font></div>'),
(184557, 'عفروس', '<span class=\"hlight\">عفروس .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) شیر بیشه ٔ قوی و توانا. (منتهی الارب ). اسد. (اقرب الموارد).<br></font></div>'),
(184558, 'عفری', '<span class=\"hlight\">عفری .</span> <font color=\"DarkGreen\"><b>[ ع ِ ری ی ]</font></b> (ع ص ) مرد نیک خبیث کربز. (منتهی الارب ). خبیث منکر. (اقرب الموارد).<br></font></div>'),
(184559, 'عفری', '<span class=\"hlight\">عفری .</span> <font color=\"DarkGreen\"><b>[ ع َ را ]</font></b> (ع اِ) موی گردن خروس . <BR><font color=\"Blue\">◄</font> موی قفای مردم . (از منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> پشم پیشانی ستور. (منتهی الارب ). موی پیشانی و ناصیه ٔ دابه . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مویهای میانه ٔ سر. (منتهی الارب ). تک مویهایی که در وسط سر انسان روئیده باشد. (از اقرب الموارد).<br></font></div>'),
(184560, 'عفری', '<span class=\"hlight\">عفری .</span> <font color=\"DarkGreen\"><b>[ ع ِ را ]</font></b> (اِخ ) نام آبی است در سرزمین فلسطین . (از معجم البلدان ).<br></font></div>'),
(184561, 'عفریة', '<span class=\"hlight\">عفریة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ی َ ]</font></b> (ع ص ) اسد عفریة؛ شیر درشت خلقت . (منتهی الارب ). شیر شدید و سخت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شیطان عفریة؛ دیو ستنبه . (منتهی الارب ). استنبه از آدمی و پری . (دهار). <BR><font color=\"Blue\">◄</font> مرد پلید کربز.(منتهی الارب ). داهیه ٔ بسیار دهاء. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مبالغه کننده در هر چیز. <BR><font color=\"Blue\">◄</font> ستمکار. (منتهی الارب ). خبیث منکر. (اقرب الموارد).<br>- <span class=\"hlight\">عفریة نفریة</span> ؛ از اتباع است، از آن جمله است حدیث «ان اﷲ یبغض العفریة النفریة». (از منتهی الارب ) (از اقرب الموارد).<br><BR><font color=\"Blue\">◄</font> (اِ) موی گردن شیر و خروس . (منتهی الارب ). تاج خروس . (دهار). عفریةالدیک ؛ پر گردن خروس . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> موی قفای مردم . <BR><font color=\"Blue\">◄</font> پشم پیشانی ستور. <BR><font color=\"Blue\">◄</font> موی میانه ٔ سر. جاء فلان نافشا عفریته ؛ خشمگین و در حال غضب آمد. (از منتهی الارب ) (از اقرب الموارد). یاءدر عفریة زائد است الحاق را و تاء آن برای مبالغه است . ج، عَفارِیَة. (از اقرب الموارد). ج، عَفاری ̍. (ناظم الاطباء).<br></font></div>'),
(184562, 'عفریت', '<span class=\"hlight\">عفریت .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) اسد عفریت ؛ شیر توانای درشت خلقت . (منتهی الارب ). سخت و شدید. (از اقرب الموارد).<br>- <span class=\"hlight\">عفریت نفریت </span> ؛ از اتباع است . (منتهی الارب ) (از اقرب الموارد). یعنی ظالم و ستمکار. (از ناظم الاطباء).<br> <BR><font color=\"Blue\">◄</font> به غایت رساننده هر چیزی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مرد درگذرنده در امور و رسا و مبالغه کننده در آن و زیرک . <BR><font color=\"Blue\">◄</font> مرد سخت خبیث کربز. (منتهی الارب ) (از اقرب الموارد). عَفریت . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) جانوری که در خاک نرم و در بن دیوار می باشد. <BR><font color=\"Blue\">◄</font> جانوری مانند کربسه که بر سوار پیش می آید و به دنب او را می زند. (ناظم الاطباء). و رجوع به عِفرّین شود. <BR><font color=\"Blue\">◄</font> دیو ستنبه . (منتهی الارب ) (ترجمان القرآن جرجانی ) (دهار). دیو. (غیاث اللغات ). دیو و اهریمن . (فرهنگ فارسی معین ). مهتر پریان . (دهار). عفریت از انس و جن و شیاطین، چیره شونده و مهتر آنان است، و گویند نفوذکننده در امور و مبالغه کننده در آن از خبث و زیرکی است .(از اقرب الموارد). تاء آن زائد است الحاق را، اگر یاء را متحرک بخوانیم تاء بدل به هاء شود: عِفرِیَه .ج، عَفاریت که آن را نیز می توان بصورت عَفارِیَة خواند. (از منتهی الارب ) (از اقرب الموارد) <span class=\"hlight\">:</span> قال عفریت من الجن أنا آتیک به قبل أن تقوم من مقامک . (قرآن <span class=\"hlight\" dir=\"rtl\">٣٩/٢٧</span>)؛ دیوی از جن گفت من آن را برایت می آورم پیش از آنکه از جای خود برخیزی .<br>جادو نباشد از تو به تنبل سوارتر<br>عفریت کرده کار ز تو کرده کارتر.<br> <font color=\"Red\">دقیقی .</font><br>نشستم از برش چون عرش بلقیس <br>بجست او چون یکی عفریت هایل .<br> <font color=\"Red\">منوچهری .</font><br>عفریت دوستار تو و دستیار تست <br>جبریل دستیار من و دوستار من .<br> <font color=\"Red\">ناصرخسرو.</font><br>سپه کرده عفریت بر زهره گردون <br>از انجم کشیده براو خشت و خنجر.<br> <font color=\"Red\">ناصرخسرو.</font><br>مگر ناگه کمین آورد برعفریت سیاره <br>مگر در شب شبیخون کرد بر مریخ اهریمن .<br> <font color=\"Red\">امیر معزی .</font><br>گرچه عفریت آورد عرش سبائی نزد جم <br>دیدنش جمشید والا بر نتابد بیش از این .<br> <font color=\"Red\">خاقانی .</font><br>گفت عفریتی که تختش را به فن <br>حاضر آرم تا تو زین بیرون شدن .<br> <font color=\"Red\">مولوی .</font><br>در پذیرم جمله زشتیت را<br>چون ملک پاکی دهم عفریت را.<br> <font color=\"Red\">مولوی .</font><br>تو گفتی که عفریت و بلقیس بود<br>قرین حور زادی به ابلیس بود.<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> آدمی و پری گردن کش . (دهار). <BR><font color=\"Blue\">◄</font> غول . <BR><font color=\"Blue\">◄</font> هر صورت مهیب و هولناکی که به تصور درآید و یا مشاهده گردد. (فرهنگ فارسی معین ).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(184563, 'عفریت', '<span class=\"hlight\">عفریت .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) مرد سخت خبیث کربز. (منتهی الارب ). عِفریت . رجوع به عِفریت شود.<br></font></div>'),
(184564, 'عفریت', '<span class=\"hlight\">عفریت .</span> <font color=\"DarkGreen\"><b>[ ع ِ ف ِرْ ری ]</font></b> (ع ص ) به غایت رساننده هر چیزی . <BR><font color=\"Blue\">◄</font> مرد درگذرنده در امور و رسا و مبالغه کننده در آن و زیرک . (منتهی الارب ). عِفریت . رجوع به عِفریت شود.<br></font></div>'),
(184565, 'عفریت دل', '<span class=\"hlight\">عفریت دل .</span> <font color=\"DarkGreen\"><b>[ ع ِ دِ ]</font></b> (ص مرکب ) آنکه دلی چون دل دیو دارد <span class=\"hlight\">:</span> آهن سم، فولادرگ، صاعقه انگیز، صرصر تک، عفریت دل . (در وصف اسب ). (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٢٥٢</span>).<br></font></div>'),
(184566, 'عفریت دیدار', '<span class=\"hlight\">عفریت دیدار.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ص مرکب ) زشت و هولناک و بدمنظر. (ناظم الاطباء).<br></font></div>'),
(184567, 'عفریت روی', '<span class=\"hlight\">عفریت روی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ص مرکب ) آن که رویی چون روی دیو و عفریت دارد <span class=\"hlight\">:</span> <br>آن کل عفریت روی با همه زشتی <br>قالی بافد همی و ایضاً محفور.<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(184568, 'عفریتة', '<span class=\"hlight\">عفریتة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ت َ ]</font></b> (ع ص، اِ) مؤنث عفریت . (منتهی الارب ) (از اقرب الموارد). رجوع به عفریت شود.<br></font></div>'),
(184569, 'عفریس', '<span class=\"hlight\">عفریس .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) شیر بیشه ٔ قوی و توانا. (منتهی الارب ). اسد. (اقرب الموارد).<br></font></div>'),
(184570, 'عفرین', '<span class=\"hlight\">عفرین .</span> <font color=\"DarkGreen\"><b>[ ع ِ ف ِرْ ری ]</font></b> (ع ص، اِ) شیر ماده ٔ درشت خلقت . <BR><font color=\"Blue\">◄</font> لیث عفرین ؛ شیر بیشه و بیشه شیر. (منتهی الارب ). اسد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> جانورکی است که در خاک نرم بن دیوار می باشد، یا جانورکی است مانند کربسه و بر سوار پیش آید و به دنب می زند. (منتهی الارب ) (اقرب الموارد). گوش خزک . (یادداشت دهخدا). <BR><font color=\"Blue\">◄</font> مرد تمام اندام ضابط توانا. (منتهی الارب ). مرد کامل ضابط قوی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زیرک و رسا و بغایت رساننده ٔ هر چیزی . (منتهی الارب ). نافذ در کارها و مبالغه کننده در آن با زیرکی . <BR><font color=\"Blue\">◄</font> هر ضابط قوی . <BR><font color=\"Blue\">◄</font> مرد کامل پنجاه ساله . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) نام شهری است . (منتهی الارب ) (از معجم البلدان ). مأسده و جای شیرناکی است، و یا شهری است . (از اقرب الموارد).<br></font></div>'),
(184571, 'عفرین', '<span class=\"hlight\">عفرین .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) نام نهری است در نواحی مصیصه، که بسوی اعمال نواحی حلب جاری است . و در اخبار نام آن آمده است . (از معجم البلدان ).<br></font></div>'),
(184572, 'عفرین', '<span class=\"hlight\">عفرین .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) مرد مبالغه کننده در امور با زیرکی و فطانت و درگذرنده در امور و رسا. (ناظم الاطباء). عفریت . (اقرب الموارد). و رجوع به عفریت شود. ج، عَفارین . (اقرب الموارد).<br></font></div>'),
(184573, 'عفز', '<span class=\"hlight\">عفز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(ع مص ) بازی کردن مرد با اهل خود. <BR><font color=\"Blue\">◄</font> خوابانیدن شتر را. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184574, 'عفز', '<span class=\"hlight\">عفز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) چهار مغز مأکول که خورده شود. (از منتهی الارب ) (از آنندراج ). جوز و گردو. (ناظم الاطباء). عَفاز. (اقرب الموارد). رجوع به عفاز شود.<br></font></div>'),
(184575, 'عفزر', '<span class=\"hlight\">عفزر.</span> <font color=\"DarkGreen\"><b>[ ع َزَ ]</font></b> (ع ص ) سابق شتاب . (منتهی الارب ). سائق سریع و شتابنده . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد بسیار شور و غوغا در باطل . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184576, 'عفس', '<span class=\"hlight\">عفس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) بازداشتن . (منتهی الارب ). حبس . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خوار و حقیر ساختن . (منتهی الارب ). خوار داشتن . (المصادر زوزنی ). <BR><font color=\"Blue\">◄</font> سخت راندن .(منتهی الارب ). عفس الابل ؛ شتران را به شدت راند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پوست مالیدن . (منتهی الارب ). مالیدن پوست را در دباغی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زدن بپای بر سرین کسی . <BR><font color=\"Blue\">◄</font> کشیدن بسوی زمین با فشارش سخت . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ابتذال ؛ بکار بردن جامه را، روزهای بسیار. <BR><font color=\"Blue\">◄</font> بازگرداندن چوپان گوسفندان خود را، و فرو نگذاشتن آنها را تا براه خود بروند. <BR><font color=\"Blue\">◄</font> بازگرداندن کسی را از حاجت خود. <BR><font color=\"Blue\">◄</font> حبس کردن ستور و ماشیه را بدون چراگاه و علف . <BR><font color=\"Blue\">◄</font> به خاک چسباندن . <BR><font color=\"Blue\">◄</font> صرع و به زمین افکندن . <BR><font color=\"Blue\">◄</font> گام نهادن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> رام کردن . <BR><font color=\"Blue\">◄</font> خوان کردن . <BR><font color=\"Blue\">◄</font> به دندان کردن . (المصادر زوزنی ).<br></font></div>'),
(184577, 'عفش', '<span class=\"hlight\">عفش .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص )گرد آوردن . (منتهی الارب ). جمع. (از اقرب الموارد).<br></font></div>'),
(184578, 'عفشال', '<span class=\"hlight\">عفشال .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) رجل عفشال ؛ مرد شوخ کم باک . (منتهی الارب ). مرد اندک بیم . (از اقرب الموارد).<br></font></div>'),
(184579, 'عفشج', '<span class=\"hlight\">عفشج .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b>(ع ص ) دراز سطبر. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184580, 'عفشل', '<span class=\"hlight\">عفشل .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (ع ص ) مرد گران جان ثقیل . (منتهی الارب ). مرد سنگین و انبوه . (از اقرب الموارد). عَفَنشل . رجوع به عفنشل شود.<br></font></div>'),
(184581, 'عفشلیل', '<span class=\"hlight\">عفشلیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ش َ ]</font></b> (ع ص ) مرد ثقیل و گران . (منتهی الارب ). مرد سنگین و انبوه .(از اقرب الموارد). عَفشل . و رجوع به عفشل شود. <BR><font color=\"Blue\">◄</font> درشت خوی . (منتهی الارب ). جافی و ثقیل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گنده پیر فروهشته گوشت . (منتهی الارب ). عجوز سست گوشت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گلیم بسیارپشم . (منتهی الارب ). کساء سطبر و خشک وبسیارپشم . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) کفتار، یا کفتار نر. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184582, 'عفص', '<span class=\"hlight\">عفص .</span> <font color=\"DarkGreen\"><b>[ع َ ف ِ ]</font></b> (ع ص ) تندمزه و گویند طعام عفص ؛ یعنی طعامی که در آن قبض باشد. (از منتهی الارب ). «عفوصة»دار. (از اقرب الموارد). هر چیز که مزه ٔ آن تلخ و ترش با گرفتگی دهن باشد. (غیاث اللغات ). طعمی است که خارج و داخل زبان را قبض می کند. (از بحر الجواهر). طعم زمخت که زبان را درشت سازد و اجزاء او را به سبب برودت بهم آورد و فعل او تبرید و تکثیف و تصلیب و خشونت و ردع است . (تحفه ٔ حکیم مؤمن ). زکش . سکوک . شکوک . قابض . گس . گلوگیر <span class=\"hlight\">:</span> و اگر طعمی عفص و قابض همی یابد <font color=\"DarkGreen\"><b>[ زفان ]</font></b> دلیل سودا باشد. (ذخیره ٔ خوارزمشاهی ).<br></font></div>'),
(184583, 'عفص', '<span class=\"hlight\">عفص .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) مازو که از آن سیاهی سازند، مولد است یا عربی . (منتهی الارب ). بار درخت بلوط، واحد آن «عفصة» است و آن مولد می باشد و ازکلام اهل بادیه نیست . (از اقرب الموارد). مازو. (دهار) (زمخشری ) (الفاظ الادویة) (فرهنگ فارسی معین ). دوائی است که آن را مازو گویند. (غیاث اللغات ). ثمر درخت بلوط، و عفص مُدبّر آن است که سوخته باشد و با سرکه خاموش شده باشد، نیکوترین آن سبز و خام و سخت است .(از بحر الجواهر). به پارسی مازو گویند و به یونانی فقس، و بهترین آن بود که سبز بود و سوراخ نداشته باشد و آن را بقاقالیس خوانند و آن غوره بود، و آنچه رسیده بود سرخ رنگ و سست و بزرگ بود. (از اختیارات بدیعی ). به فارسی مازو نامند، درخت او مثل درخت بلوط است و در بعضی بلاد یک سال بلوط بار می دهد و یک سال مازو. (از تحفه ٔ حکیم مؤمن ). برآمدگی که بر بعضی اشجارو اثمار پیدا آید و آن جای نیش قسمی از حشرات است که در آنجا تخم گذارد، و بالخاصه برآمدگی های درخت بلوط را عفص گویند که همان مازو است . (یادداشت مرحوم دهخدا). و رجوع به مازو شود <span class=\"hlight\">:</span> بعضی داروها قابض است، چون عفص و هلیله و شحم انار. (ذخیره خوارزمشاهی ). <BR><font color=\"Blue\">◄</font> درختی است از بلوط که یک سال بلوط بار دهد و یک سال مازو، قابض است و مجفف مواد ریخته شده و اعضای نرم و سست را سخت و قوی گرداند و نقوع آن در سرکه موی را سیاه کند و مسحوق آن به آب در ناشتا درد شکم را دفع کند و اسهال و قروح امعاء را نفعبخشد. (منتهی الارب ). درخت بلوط، و آن داروئی است قابض و مجفف و گاهی از آن مرکب گیرند و بدان رنگ کنند. (از اقرب الموارد). بلوط مازو که یکی از گونه های بلوط است و تولید مازو می کند. <BR><font color=\"Blue\">◄</font> نوعی سرو که به سرو خمره ای موسوم است . (از فرهنگ فارسی معین ). رجوع به سرو خمره ای شود.<br></font></div>'),
(184584, 'عفص', '<span class=\"hlight\">عفص .</span> <font color=\"DarkGreen\"><b>[ ع َف َ ]</font></b> (ع اِمص ) پیچیدگی بینی و گرفتگی آن . (منتهی الارب ). التواء و پیچیدگی در بینی . (از اقرب الموارد).<br></font></div>'),
(184585, 'عفص', '<span class=\"hlight\">عفص .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) برکندن . (منتهی الارب ). قلع. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> غالب آمدن در کشتی و سست گردانیدن . <BR><font color=\"Blue\">◄</font> پیچ دادن کسی را. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> جماع کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> «عفاص » بستن بر سر شیشه . (از منتهی الارب ) (از اقرب الموارد). پوست بر شیشه بستن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> سربند ساختن شیشه را. (منتهی الارب ). قرار دادن «عفاص » را در سرقاروره . (از اقرب الموارد). و رجوع به عفاص شود. <BR><font color=\"Blue\">◄</font> دوتا کردن و پامال گردانیدن چیزی را. (ازمنتهی الارب ). خم کردن چیزی را. (از اقرب الموارد).<br></font></div>'),
(184586, 'عفصی', '<span class=\"hlight\">عفصی .</span> <font color=\"DarkGreen\"><b>[ ع َ ی ی ]</font></b> (ص نسبی ) منسوب به عفص . آنچه طعم و مزه ٔ «عفص » داشته باشد یا به رنگ آن بود. و رجوع به عفص شود. <BR><font color=\"Blue\">◄</font> (اِ) باشق و باز، و گویند پرنده ای است کوچکتر از آن . (از اقرب الموارد).<br></font></div>'),
(184587, 'عفصی', '<span class=\"hlight\">عفصی .</span> <font color=\"DarkGreen\"><b>[ ع َ ف ِ ]</font></b> (حامص ) دندی . گسی . عفوصت . قبض . (یادداشت مرحوم دهخدا). رجوع به عَفِص شود.<br></font></div>'),
(184588, 'عفصی', '<span class=\"hlight\">عفصی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) احمدبن محمدبن بالویه عفصی مکنی به ابوحامدمحدث بود و حدیث را نزد ابوعبداﷲ بوشنجی در نیشابور، و محمدبن ایوب در ری، و بشربن موسی و عبداﷲبن احمدبن حنبل در بغداد فراگرفت . عفصی در جمادی الاولای سال <span class=\"hlight\" dir=\"rtl\">٣٤٣</span> هَ . ق . درگذشت . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(184589, 'عفصیح', '<span class=\"hlight\">عفصیح .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) نوعی از بلوط است . (تحفه ٔ حکیم مؤمن ) (مخزن الادویه ).<br></font></div>'),
(184590, 'عفضاج', '<span class=\"hlight\">عفضاج .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) فربه سست گوشت . (منتهی الارب ) (اقرب الموارد). عفضج . رجوع به عفضج شود.<br></font></div>'),
(184591, 'عفضج', '<span class=\"hlight\">عفضج .</span> <font color=\"DarkGreen\"><b>[ ع َ ض َ ]</font></b> (ع ص ) فربه سست گوشت . (منتهی الارب ) (از اقرب الموارد). عفضاج عُفاضِج . ورجوع به عفاضج و عفضاج شود. <BR><font color=\"Blue\">◄</font> سخت درشت گوشت . (منتهی الارب ). صلب و شدید. (از اقرب الموارد).<br></font></div>'),
(184592, 'عفط', '<span class=\"hlight\">عفط.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) تیز دادن بز. (از منتهی الارب ) (از اقرب الموارد). ضرط. (المصادر زوزنی ). <BR><font color=\"Blue\">◄</font> بینی افشاندن میش چون بینی افشاندن خر. (از اقرب الموارد). عَفیط. و رجوع به عفیط شود. <BR><font color=\"Blue\">◄</font> درماندن به سخن . (از منتهی الارب ). سخن گفتن به لکنت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تیز دادن به هر دو لب . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خواندن گوسپندان را و بینی افشاندن آن . <BR><font color=\"Blue\">◄</font> راندن شبان گوسپندان را به همان روش که عطسه دهند. (از منتهی الارب ). زجر کردن شبان گوسفندان را به صورتی که شبیه «عفط» آنها باشد. (از اقرب الموارد).<br></font></div>'),
(184593, 'عفط', '<span class=\"hlight\">عفط.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ)نخامه ٔ بینی میش . (منتهی الارب ). آب بینی میش . (ناظم الاطباء). عفطة. (اقرب الموارد). رجوع به عفطة شود.<br></font></div>'),
(184594, 'عفط', '<span class=\"hlight\">عفط.</span> <font color=\"DarkGreen\"><b>[ ع َ ف ِ ]</font></b> (ع ص ) رجل عفط؛ مرد تیزدهنده . (منتهی الارب ). ضروط. (اقرب الموارد).<br></font></div>'),
(184595, 'عفطان', '<span class=\"hlight\">عفطان .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع مص ) تیز دادن بز. (از منتهی الارب ) (از اقرب الموارد). عَفط. رجوع به عفط شود.<br></font></div>'),
(184596, 'عفطلة', '<span class=\"hlight\">عفطلة.</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ل َ ]</font></b> (ع مص ) آمیختن چیزی را به چیزی و خلط کردن . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184597, 'عفطی', '<span class=\"hlight\">عفطی .</span> <font color=\"DarkGreen\"><b>[ ع ِ طی ی ]</font></b> (ع ص ) درمانده به سخن . (منتهی الارب ). الکن . (اقرب الموارد). عِفاطی . عَفّاط. رجوع به عفاط و عفاطی شود.<br></font></div>'),
(184598, 'عفعف', '<span class=\"hlight\">عفعف .</span><font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (اِ صوت ) آواز سگ . (غیاث اللغات ) (آنندراج ). حکایت آواز سگ . بانگ سگ . پارس . عوعو. نباح . واغ واغ . وعوع . وغواغ . وغوغ . هاف هاف . هفهف <span class=\"hlight\">:</span> <br>سگ عفعفک کند چو بدو نانکی دهی <br>دم لابگک کند بنشیند پس درک .<br> <font color=\"Red\">خاقانی .</font><br>از عفعف جحد برنگردی زنهار<br>کاو از سگان نشانه ٔ آبادی است .<br> <font color=\"Red\">درویشی یوسف (از آنندراج ذیل عف ).</font><br> <BR><font color=\"Blue\">◄</font> عفعف، بتشدید فاء؛ به معنی آواز شتر، مجاز است . (آنندراج ) <span class=\"hlight\">:</span> <br>عفعف تاکی زنی همچون شتر در ملک عقل <br>چند سازی خویش را از تیغ هشیاری فگار.<br><font color=\"Red\">ملافوقی یزدی (از آنندراج ).</font><br></font></div>'),
(184599, 'عفعف', '<span class=\"hlight\">عفعف .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (ع اِ) بار درخت موز. (منتهی الارب ). ثمر و بار طلح . (از اقرب الموارد).<br></font></div>'),
(184600, 'عفعفة', '<span class=\"hlight\">عفعفة.</span> <font color=\"DarkGreen\"><b>[ ع َ ع َف َ ]</font></b> (ع مص ) خوردن بار موز را. (از منتهی الارب ). خوردن عفعف را. (از اقرب الموارد). رجوع به عفعف شود.<br></font></div>'),
(184601, 'عفف', '<span class=\"hlight\">عفف .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (اِ صوت ) آواز سگ . (آنندراج ). عفعف . عف . رجوع به عف و عفعف شود <span class=\"hlight\">:</span> <br>ز معاملات جهان کد، تو برآ کزین همه دام و دد<br>عفف سگی به سگی خورد لگد خری به خری رسد.<br><font color=\"Red\">میرزا بیدل (از آنندراج ذیل عف ).</font><br></font></div>'),
(184602, 'عففة', '<span class=\"hlight\">عففة.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ف َ ]</font></b> (ع اِ) ج ِ عَف ّ. (منتهی الارب ). رجوع به عف شود.<br></font></div>'),
(184603, 'عفق', '<span class=\"hlight\">عفق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) غائب گردیدن بر سر خود سپس آن بازآمدن . (از منتهی الارب ). غایب شدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بسیار زدن کسی را به تازیانه . (از منتهی الارب ) (از اقرب الموارد).به تازیانه زدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> عصا زدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> بند نمودن از کاری و بازداشتن کسی را از اراده ٔ وی . (از منتهی الارب ). حبس کردن و منع نمودن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پریشان و متفرق شدن شتران در چراگاه بعد گذاشتن در آن و بر سر خود رفتن . (از منتهی الارب ). فرستاده شدن شتران به چراگاه و به راه خود رفتن آنها. (از اقرب الموارد). عُفوق . و رجوع به عفوق شود. <BR><font color=\"Blue\">◄</font> اندک خوابیده بیدار شدن . (از منتهی الارب ).خفتن اندک، سپس بیدار شدن و دیگر بار خفتن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تیز دادن . <BR><font color=\"Blue\">◄</font> استوار ناکردن کار را. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بسیار گشنی کردن خر. (منتهی الارب ). بسیار گشنی کردن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> آمد و رفت کردن بسیار اشتران بر آب . <BR><font color=\"Blue\">◄</font> بسیار رجوع کردن . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> فراهم آوردن چیزی را. (از منتهی الارب ). جمع کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زدن و پراکنده کردن باد چیزی را. (منتهی الارب ). زدن باد چیزی را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بسیار دوشیدن ناقه . (منتهی الارب ) (از اقرب الموارد). عِفاق یا عَفاق . و رجوع به عفاق شود. <BR><font color=\"Blue\">◄</font> شتاب رفتن . (منتهی الارب ). رفتن به سرعت و شتاب . (از اقرب الموارد).<br></font></div>'),
(184604, 'عفق', '<span class=\"hlight\">عفق .</span> <font color=\"DarkGreen\"><b>[ ع ُف ُ ]</font></b> (ع اِ) مگس . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> گرگهایی که نمی خوابند و نمی خوابانند. (از اقرب الموارد).<br></font></div>'),
(184605, 'عفق', '<span class=\"hlight\">عفق .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع اِمص ) آمد و شد شتران بر آبخور. (منتهی الارب ).<br></font></div>'),
(184606, 'عفقسة', '<span class=\"hlight\">عفقسة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ س َ ]</font></b> (ع مص ) بد کردن خلق کسی را پس از آنکه نیکو بوده است . (از اقرب الموارد). تباه ساختن و بد کردن . (ناظم الاطباء): ما عَفقَسه ُ؛ چه بدخلق است او بعد آنکه نیکوخوی بود. (منتهی الارب ).<br></font></div>'),
(184607, 'عفقل', '<span class=\"hlight\">عفقل .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع ص ) مرد کلان روی . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184608, 'عفل', '<span class=\"hlight\">عفل .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع مص ) عفله زده گردیدن زن . (از منتهی الارب ). رجوع به عفله شود.<br></font></div>'),
(184609, 'عفل', '<span class=\"hlight\">عفل .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ]</font></b> (ع اِ) فنج ماده، و آن چیزی است که از شرم زن و شترماده برآید مانند ادره و فتق که درخایه ٔ مردان باشد. (از منتهی الارب ). در اصطلاح فقها، چیزی است شبیه به گوشت که در عضو تناسلی زن پیدا می شود و مانع جماع می گردد. و گاهی هم استخوانی در آن محل مانع جماع می شود که این را اصطلاحاً قَرَن نامند. (فرهنگ حقوقی ). عَفَله . و رجوع به عفلة شود. <BR><font color=\"Blue\">◄</font> بسیاری پیه در مابین پای تکه و گاو نر، و اکثر استعمال او در خصی می کنند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خط میان دبر و شرم مرد. (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> پیه هر دو خایه ٔ قچقار و گرداگرد آن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> جای دست زدن در قچقار و گوسپند جهت دانستن فربهی وگرانی و سبکی وی . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184610, 'عفلان', '<span class=\"hlight\">عفلان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام کوهی است از آن ابوبکربن کلاب، در نجد. (از معجم البلدان ) (از منتهی الارب ).<br></font></div>'),
(184611, 'عفلانة', '<span class=\"hlight\">عفلانة.</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ ]</font></b> (اِخ ) آبی است دیرینه نزدیک کوه عفلان . (از منتهی الارب ). نام چند آب است . رجوع به معجم البلدان شود.<br></font></div>'),
(184612, 'عفلة', '<span class=\"hlight\">عفلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ل َ ]</font></b> (ع اِ) فنج ماده و آن چیزی است که از شرم زن و شترماده برآید، مانند ادره که در خایه ٔ مردان باشد. (از منتهی الارب ). عفل . رجوع به عفل شود.<br></font></div>'),
(184613, 'عفلط', '<span class=\"hlight\">عفلط.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َل ْ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ل ِ ]</font></b> (ع ص ) گول . (منتهی الارب ).احمق . (اقرب الموارد). عفلیط. رجوع به عفلیط شود.<br></font></div>'),
(184614, 'عفلق', '<span class=\"hlight\">عفلق .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ف َل ْ ل َ ]</font></b> (ع ص ) شرم زن فراخ و سست و پرگوشت . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> زن گول بدزبان بدکردار. (منتهی الارب ) (از اقرب الموارد). و لام آن را زائد دانسته اند. (از اقرب الموارد).<br></font></div>'),
(184615, 'عفله', '<span class=\"hlight\">عفله .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع اِ) چیزی شبیه به گوشت زائد که از فرج زن و شتر ماده برآید، وفتق رحم . (ناظم الاطباء). رجوع به عفل و عفلة شود.<br></font></div>'),
(184616, 'عفله زده', '<span class=\"hlight\">عفله زده .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ زَ دَ<span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) زنی که مبتلی به بیماری عفله باشد. (ناظم الاطباء). رجوع به عفله و عفلة و عفل شود.<br></font></div>'),
(184617, 'عفلوق', '<span class=\"hlight\">عفلوق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص )گول و کم خرد. (منتهی الارب ). احمق . (اقرب الموارد).<br></font></div>'),
(184618, 'عفلیط', '<span class=\"hlight\">عفلیط.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) گول . (منتهی الارب ). احمق . (اقرب الموارد). عفلط. رجوع به عفلط شود.<br></font></div>'),
(184619, 'عفن', '<span class=\"hlight\">عفن .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) برآمدن بر کوه . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> برگردانیدن مزه و رنگ گوشت را. (از منتهی الارب ). تغییردادن بوی گوشت را. (از اقرب الموارد).<br></font></div>'),
(184620, 'عفن', '<span class=\"hlight\">عفن .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع مص ) پوسیده شدن هر چیزی و تباه گردیدن چندانکه ریزه ریزه برآید وقت گرفتن . (از منتهی الارب ) (از اقرب الموارد). پوسیده شدن در نم . (المصادر زوزنی ) (تاج المصادر بیهقی ) (دهار). <BR><font color=\"Blue\">◄</font> تغییر یافتن بوی گوشت . (از اقرب الموارد). گنده شدن هوا و گوشت و جز آن . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> پوسیده شدن ریسمان از آب . (از اقرب الموارد) (از منتهی الارب ). عُفونة. رجوع به عفونة شود.<br></font></div>'),
(184621, 'عفن', '<span class=\"hlight\">عفن .</span> <font color=\"DarkGreen\"><b>[ ع َ ف ِ ]</font></b> (ع ص ) گوشت بر گردیده بوی و مزه و پوسیده . هرچیز پوسیده و تباه شده از آب که ریزه ریزه جدا گردد. (منتهی الارب ). ریسمان پوسیده از آب . (از اقرب الموارد). گنده و بدبو. (غیاث اللغات ). گندیده . متعفن . منتن . بوی ناک <span class=\"hlight\">:</span> جهت شمال آن بسته است از این جهت بیمارناک و عفن است <font color=\"DarkGreen\"><b>[ شاپور ]</font></b> . (فارسنامه ٔ بلخی ص <span class=\"hlight\" dir=\"rtl\">١٤٢</span>). شرابی که آفتاب پرورده باشد... خون را بزودی عفن گرداند. (نوروزنامه ). اگر اندر تن رطوبتها وخلطها فزونی باشد آن را عفن کند یعنی پوسیده کند و پوسیدن خلط آن باشد که گنده و تباه گردد. (ذخیره ٔ خوارزمشاهی ). خون اندر مفاصل او <font color=\"DarkGreen\"><b>[ هر که را علت جذام پدید آید ]</font></b> بفسرد و عفن گردد. (ذخیره ٔ خوارزمشاهی ).<br>این عالمی است جافی و ز جیفه موج زن <br>صحرای جان طلب که عفن شد هوای خاک .<br><font color=\"Red\">خاقانی .</font><br>این هوا با روح آمد مقترن <br>چون قضا آید وبا گشت و عفن <br> <font color=\"Red\">مولوی .</font><br>الاشق ؛ صمغة تأکل لحم العفن . (ابن البیطار).<br></font></div>'),
(184622, 'عفنة', '<span class=\"hlight\">عفنة.</span> <font color=\"DarkGreen\"><b>[ ع َ ف ِ ن َ ]</font></b> (ع ص ) تأنیث عَفِن . گنده . گندیده : قروح عفنة. رجوع به عفن شود.<br></font></div>'),
(184623, 'عفنجج', '<span class=\"hlight\">عفنجج .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ج َ ]</font></b> (ع ص ) گول سطبر. (منتهی الارب ). شخص نادان بدخوی که برای کاری براه نمی آید. و گویند شخص نادان و احمق . و گویند شخص تنومند احمق . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناقه ٔ شتاب رو. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناقه ٔ مسن . (از اقرب الموارد). عثنجج . رجوع به عثنجج شود.<br></font></div>'),
(184624, 'عفنجش', '<span class=\"hlight\">عفنجش .</span> <font color=\"DarkGreen\"><b>[ع َ ف َ ج َ ]</font></b> (ع ص ) مرد درشت و بدخوی . (منتهی الارب ).<br></font></div>'),
(184625, 'عفنجل', '<span class=\"hlight\">عفنجل .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ج َ ]</font></b> (ع ص ) ثقیل گرانجان و بدخوی که صحبت وی را ناخوش دارند و مرد بسیار هرزه گوی و فضول . (از منتهی الارب ). ثقیل و بسیار فضول در سخن و در هر چیزی . (از اقرب الموارد).<br></font></div>'),
(184626, 'عفنش', '<span class=\"hlight\">عفنش .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َن ْ ن َ ]</font></b> (ع ص ) پیر بزرگ سال . <BR><font color=\"Blue\">◄</font> انه لعفنش اللحیة؛ او سطبر و بسیارموی ریش است . عَفانَش . و رجوع به عفانش شود. <BR><font color=\"Blue\">◄</font> عفنش العینین ؛ سطبر ابرو. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184627, 'عفنشل', '<span class=\"hlight\">عفنشل .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ش َ ]</font></b> (ع ص ) مرد گرانجان ثقیل . (منتهی الارب ). مرد تخمه زده ٔ سنگین . (ناظم الاطباء). به معنی عَفشَل است . (از اقرب الموارد). رجوع به عفشل شود.<br></font></div>'),
(184628, 'عفنط', '<span class=\"hlight\">عفنط.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َن ْ ن َ ]</font></b> (ع ص ) ناکس زشت خوی . (منتهی الارب ). لئیم و سیّی ٔالخلق . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) دابةالارض ؛ که حیوانی است . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184629, 'عفنقس', '<span class=\"hlight\">عفنقس .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ق َ ]</font></b> (ع ص ) دشوارخوی و ناکس . (منتهی الارب ). سخت خوی و لئیم . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خلق عفنقس ؛ خوی دشوار. (منتهی الارب ).<br></font></div>'),
(184630, 'عفنک', '<span class=\"hlight\">عفنک .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َن ْ ن َ ]</font></b> (ع ص ) بسیار احمق و نادان . (از اقرب الموارد). عَفیک . رجوع به عفیک شود.<br></font></div>'),
(184631, 'عفنی', '<span class=\"hlight\">عفنی .</span><font color=\"DarkGreen\"><b>[ ع َ ف ِ ]</font></b> (حامص ) عفن بودن . گنده بودن <span class=\"hlight\">:</span> <br>خصم نخستین قدری زهر ساخت <br>کز عفنی سنگ سیه را گداخت .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(184632, 'عفنی', '<span class=\"hlight\">عفنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) (به معنی متعفن ) شهری است در حدود بن یامین که همان جفنه ٔ یوسیفوس است و همان جفنه ٔ حالیه باشد. (قاموس کتاب مقدس ).<br></font></div>'),
(184633, 'عفه', '<span class=\"hlight\">عفه .</span> <font color=\"DarkGreen\"><b>[ ع ُف ْ ف َ ]</font></b> (اِ) پوستین پوست بره که موی آن بغایت نرم باشد. (برهان ) (آنندراج ). پوستین از پوست بره که مویکی نرم دارد. (صحاح الفرس ) <span class=\"hlight\">:</span> <br>روی هر یک چون دو هفته گرد ماه <br>جامه شان عفه سموریشان کلاه .<br><font color=\"Red\">رودکی .</font><br></font></div>'),
(184634, 'عفو', '<span class=\"hlight\">عفو.</span> <font color=\"DarkGreen\"><b>[ ع َف ْوْ ]</font></b> (ع مص ) آمرزیدن و درگذشتن از گناه و عقوبت ناکردن مستحق عذاب را. (از منتهی الارب ). گذشت کردن بر کسی و ترک کردن مجازاتی را که شایسته ٔ آن است و خودداری از مؤاخذه او. (از اقرب الموارد). گناه از کسی در گذاشتن . (ترجمان القرآن جرجانی ). جرم از کسی فروگذاشتن . (المصادر زوزنی ). جرم از کسی درگذاشتن .(تاج المصادر بیهقی ) (دهار). <BR><font color=\"Blue\">◄</font> محو کردن خداوند گناهان کسی را. <BR><font color=\"Blue\">◄</font> حق را ساقط کردن چنانکه گوئی آن را از کسی که بر اوست محو کنند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پاک کردن نبشته را و محو ساختن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خودداری کردن از چیزی و طلب نکردن آنرا. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناگرفتن زکات را. <BR><font color=\"Blue\">◄</font> معروف و احسان خواستن . (منتهی الارب ). آمدن به طلب معروف و احسان . (از اقرب الموارد). نزدیک کسی شدن برای احسانی . (المصادر زوزنی ) نزدیک کسی شدن به امید احسان . (تاج المصادر بیهقی ) (دهار). <BR><font color=\"Blue\">◄</font> نیکو شدن حال کسی . <BR><font color=\"Blue\">◄</font> فربه گردیدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بسیار شدن . (المصادر زوزنی ) (تاج المصادر بیهقی ). فراوان شدن و کثرت . <BR><font color=\"Blue\">◄</font> افزون شدن بر کسی در علم . <BR><font color=\"Blue\">◄</font> فراوان کردن و افزون نمودن چیزی، و از آن است «احفوا الشوارب و اعفوا اللحی ». (از اقرب الموارد). بسیار گردانیدن . (المصادر زوزنی ) (تاج المصادر بیهقی ). بسیار کردن و افزونی . (دهار). <BR><font color=\"Blue\">◄</font> داخل نشدن چیزی که آب را تیره سازد به آن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نزدیک گرفتن شتر چراگاه را. <BR><font color=\"Blue\">◄</font> بسیار شدن پشم شتر و دراز گردیدن چندانکه بپوشد سرین وی را. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> انبوه گردانیدن علف و جزآن را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> محو شدن و از بین رفتن اثر. (از اقرب الموارد). ناپیدا شدن . (المصادرزوزنی ). <BR><font color=\"Blue\">◄</font> ناپدید گردیدن خانه . (از منتهی الارب ). کهنه و مندرس شدن خانه . (از اقرب الموارد). عُفّو. عَفاء. و رجوع به عفو و عفاء شود. <BR><font color=\"Blue\">◄</font> پوشیدن باد خانه را به خاک . (از منتهی الارب ). کهنه کردن و محو کردن باد خانه را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناپیدا کردن اثر. (المصادر زوزنی ). ناپدید گردانیدن اثر. (تاج المصادر بیهقی ) (از دهار). <BR><font color=\"Blue\">◄</font> ناپدید کردن باد نشان چیزی را. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بریدن پشم را. <BR><font color=\"Blue\">◄</font> ترک گفتن چیزی را. <BR><font color=\"Blue\">◄</font> ابتدا پیمانه کردن شوربا را برای کسی و آن را به وی رساندن . <BR><font color=\"Blue\">◄</font> باقی گذاشتن «عفاوة» را در انتهای دیگ . و رجوع به عفاوة شود. <BR><font color=\"Blue\">◄</font> پوشاندن گیاه زمین را. <BR><font color=\"Blue\">◄</font> باقی ماندن مقداری از چیزی . (از اقرب الموارد).<br></font></div>'),
(184635, 'عفو', '<span class=\"hlight\">عفو.</span> <font color=\"DarkGreen\"><b>[ ع ُ ف ُوو ]</font></b> (ع مص ) ناپدید گردیدن خانه . (از منتهی الارب ). کهنه و مندرس شدن خانه . (از اقرب الموارد). عَفْو. رجوع به عفو شود.<br></font></div>'),
(184636, 'عفو', '<span class=\"hlight\">عفو.</span> <font color=\"DarkGreen\"><b>[ ع ِف ْوْ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ف ْوْ ]</font></b> (ع اِ) خرکره . (منتهی الارب ). جحش . (اقرب الموارد). عَفْو. رجوع به عَفو شود.<br></font></div>'),
(184637, 'عفو', '<span class=\"hlight\">عفو.</span> <font color=\"DarkGreen\"><b>[ ع َ ف ُوو ]</font></b> (ع ص ) مردبسیار عفوکننده و درگذرنده از گناه . (منتهی الارب ). عافی و بسیار عفوکننده، و آن فعول به معنی فاعل است . (از اقرب الموارد). درگذارنده و پوشنده ٔ گناهان . (مهذب الاسماء). پوشنده ٔ گناه . (السامی ). بسیار درگذرنده از گناه کسی . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> صفتی از صفات باری تعالی، به معنی کثیرالعفو. (از منتهی الارب ).نامی از نامهای خدای تعالی . (مهذب الاسماء) <span class=\"hlight\">:</span> اًن اﷲ لعفو غفور. (قرآن <span class=\"hlight\" dir=\"rtl\">٥٩/٢٢</span> و <span class=\"hlight\" dir=\"rtl\">٣/٥٨</span>)؛ همانا خداوند درگذرنده و آمرزنده است . فان اﷲ کان عفوا قدیرا. (قرآن <span class=\"hlight\" dir=\"rtl\">١٤٨/٤</span>)؛ همانا خداوند درگذرنده و توانا است .<br></font></div>'),
(184638, 'عفو', '<span class=\"hlight\">عفو.</span> <font color=\"DarkGreen\"><b>[ ع َف ْوْ ]</font></b> (ع اِمص ) ساقط کردن عذاب . و مغفرت پوشاندن جرم است برای محافظت از عذاب شرمزدگی و رسوائی، و عفو را صفت کسی قرار می دهند که توانائی انجام دادن عمل مقابل آن را داشته باشد. (از اقرب الموارد). ترک عقوبت گناهکار. آمرزش . بخشش .گذشت . (ناظم الاطباء). ترک کردن عقوبت گناه در حالت قدرت، و این مقابل انتقام است . (آنندراج ). عبارت است از آنکه بر نفس ترک مجازات بدی یا طلب مکافات به نیکی با حصول قدرت و تمکن از آن آسان بود. (از نفائس الفنون از حکمت مدنی ). آسان بودن بر نفس ترک مجازات به بدی یا طلب مکافات به نیکی با حصول تمکن از آن و قدرت بر آن . (فرهنگ علوم عقلی از اخلاق ناصری ص <span class=\"hlight\" dir=\"rtl\">٧٩</span>). عفو آن است که از بدی درگذری و در ازای بدی بدی نکنی و عفو و بخشش کنی به حکم «والکاظمین الغیظ و العافین عن الناس ». (فرهنگ مصطلحات عرفاء از مصباح الهدایة). بخشایش . گذشت . آمرزش . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> خذ العفو وأمُرْ بالعُرف و أعرض عن الجاهلین . (قرآن <span class=\"hlight\" dir=\"rtl\">١٩٨/٧</span>)؛ عفو را بگیر و به امر شایسته امر کن واز نادانان روی بگردان . بزرگان ... بغنیمت داشته اند عفو چون توانستند که به انتقام مشغول شوند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٦٤</span>). اگر به این قسم که خوردم وفا نکنم ... محروم گرداند مرا از عافیت در دنیا و از عفو در آخرت .(تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣١٩</span>). ترا گناهی است بزرگ و الا توبه کنی و به دین اجداد و آباء خویش بازآیی تا عفو یابی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٤٠</span>). هیچ مشاطه ای جمال عفو... مهتران را چون زشتی جرم ... کمتر نیست . (کلیله و دمنه )<br>وگر رنگ عفوش پذیرد بیابان <br>چو دریاش نیلوفرستان نماید.<br> <font color=\"Red\">خاقانی .</font><br>گر بد دارد و گر نکو او داند<br>گر جرم کند و گر عفو او داند.<br> <font color=\"Red\">خاقانی .</font><br>وزفراوان ابر رحمت ریخته باران فضل <br>رانده ای را بر امید عفو شادان دیده اند.<br> <font color=\"Red\">خاقانی .</font><br>مرا عفو کن زانکه نزدیک تو من <br>بجز عفو تو عذرخواهی ندارم .<br> <font color=\"Red\">عطار.</font><br>که به عفو از گناه پاک شوی . (گلستان ).<br>برفت سایه ٔ درویش و سترپوش غریب <br>بپوش بار خدایا به عفو ستارش .<br> <font color=\"Red\">سعدی .</font><br>خطای بندگان باید به هرحال <br>که تا پیدا شود عفو بزرگان .<br> <font color=\"Red\">جوهری هروی .</font><br>چون گنه کاری که هر ساعت از او عفوی  برند<br>چرخ سنگین دل ز من هردم کند یاری جدا.<br> <font color=\"Red\">میرزا صائب (از آنندراج ).</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">العفو عند القدرة</span> ؛ عفو و گذشت هنگام قدرت داشتن بر انتقام نیکو است <span class=\"hlight\">:</span> چه نیکو است العفو عندالقدرة. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٢٦</span>). بزرگان گفته اند العفو عند القدرة. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٦٤</span>). مرد آن است که گفته اند العفو عند القدرة به کار تواند آورد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٧٧</span>).<br> <span class=\"hlight\">در عفو لذتی است که در انتقام نیست </span> .<br>- <span class=\"hlight\">رقم عفو یا قلم عفو کشیدن </span> ؛ از گناه کسی درگذشتن . بخشودن . (از فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>عدل است اگر عقوبت ما بی گنه کنی <br>لطف است اگر کشی قلم عفو بر خطا.<br> <font color=\"Red\">سعدی .</font><br>من نگویم که طاعتم بپذیر، قلم عفو بر گناهم کش . (گلستان ).<br>- <span class=\"hlight\">عفو خصوصی </span> ؛ عبارت است از عدم اجرای تمام یا قسمتی از مجازات که به دستور رئیس دولت برای تعدیل احکام شدید جزائی یا تشویق محکومینی که در دوره ٔ اجراء مجازات حسن سلوک داشته اند، واقع می شود. این عفو دارای مشخصات ذیل است : الف - حکم قطعی محکومیت باید صادر شده باشد، بهمین جهت محکومین غیابی نمی توانند مشمول این قسم عفو قرار گیرند. ب - قانون خاصی برای این عفو لازم نیست، بلکه قوانین عادی و جاری کشور آن را پیش بینی نموده است . ج - این قسم عفو تمام آثار جرم را از بین نمی برد، یعنی محکومیت مزبور می تواند باعث تحقق «تکرار جرم » شود و نیز محرومیت از حقوق اجتماعی را از بین نمی برد. (از فرهنگ حقوقی ).<br>- <span class=\"hlight\">عفو عمومی </span> ؛ درگذشتن ازگناه همگان، و آن وسیله ای است که معمولاً پس از وقوع انقلابات سیاسی و بحرانهای اجتماعی و اتفاقات غیرعادی (که عده ٔ زیادی در مقاصد معینی شرکت داشته اند) برای خاموش کردن محرکین آن و محو آثار انقلاب بعمل می آید، و ممکن است کلی بوده و یا ناظر به جرائم سیاسی، مطبوعاتی، مالی، نظامی و غیره باشد. این قسم از عفو دارای مشخصات زیر است : الف - عفو عمومی ممکن است قبل از محاکمه و صدور حکم قطعی و بعد از آن صادر شود (به خلاف عفو خصوصی ). ب - برای عفو عمومی قانون خاصی در یک یک موارد آن لازم است (به خلاف عفو خصوصی ). ج - در عفوعمومی معافیت از مجازات بطور قطعی است نه به طور مشروط. د- عفو عمومی تمام آثار جرم را از بین می برد (یعنی جنبه ٔ غیرقانونی و جرم بودن را سلب میکند، به خلاف عفو خصوصی ). هَ - متهم در مورد عفو عمومی حق نداردبرای اثبات بی تقصیری خود دعوی را (بعد از صدور فرمان عفو عمومی ) تعقیب نماید. و- اگر حکم محکومیت قطعی و قسمتی از آن اجرا شود، عفو عمومی قسمت باقیمانده را تعطیل می کند. اگر مجازات غرامت باشد به عقیده ٔ عده ای از حقوقدانان باید به محکوم علیه مسترد شود. ز - حکم محکومیت در موارد عفو عمومی مانع استفاده ٔ محکوم علیه از تعلیق مجازات نیست . ولی عفو عمومی به حقوق اشخاص ثالث ضرر وارد نمی کند و محکوم علیه بوسیله ٔ مجنی علیه یا ورثه ٔ او تعقیب می شود. (فرهنگ حقوقی ).<br><BR><font color=\"Blue\">◄</font> شهادت بی خواهش مدعی : فانه أقر له عفوا أنه رسول ابن الفرات اًلی ابن ابی الساج . (یاقوت ) (معجم الادباء). <BR><font color=\"Blue\">◄</font> أعطیته عفوا؛ بی سؤال و بی خواست او را دادم . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) پاک ترین مال . و معظم آن . (منتهی الارب ). حلال ترین و پاکترین مال . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> برگزیده و أجود هر چیزی . (منتهی الارب )(از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نیکوئی و احسان . (منتهی الارب ). معروف . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> چراگاه نیکو. <BR><font color=\"Blue\">◄</font> باقی مانده ٔ آب بعد نوشیدن . (منتهی الارب ). آبی که از «شاربة» و صاحبان آب نهر، باقی بماند و بدون مزاحمت و تکلف گرفته شود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شهری که در آن علامت ملک احدی نباشد. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> جائی که پاسپر کسی نشده . (منتهی الارب ). زمین «غفل » و موات که گامی در آن ننهاده باشند و آثاری در آن نباشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خرکره . (منتهی الارب ). جحش . (اقرب الموارد). عِفو یا عُفو. ج، عَفوةو عِفاء. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آسان و سهل از هر چیزی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> فضل و باقیمانده . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> باقیمانده ٔ مال از نفقه و خرجی، که بخشیدن آن سبب تنگدستی صاحبش نمی گردد. (از اقرب الموارد). آنچه از هزینه افزون آید. (کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> در اصطلاح شرع، آنچه از حد نصاب زائد آید. (کشاف اصطلاحات الفنون ) <span class=\"hlight\">:</span> و یسألونک ماذا ینفقون، قل العفو... (قرآن <span class=\"hlight\" dir=\"rtl\">٢١٦/٢</span> و <span class=\"hlight\" dir=\"rtl\">٢١٩</span>). از تو می پرسند چه چیز انفاق کنند. بگو «عفو» و فاضل از قوت را.<br></font></div>'),
(184639, 'عفو خواستن', '<span class=\"hlight\">عفو خواستن .</span> <font color=\"DarkGreen\"><b>[ ع َف ْوْ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ت َ ]</font></b> (مص مرکب ) طلب عفو، آمرزش و بخشایش خواستن . اعتفاء <span class=\"hlight\">:</span> عذرها خواستند به جنگی که رفت و عفو خواسته . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٧١</span>).<br></font></div>'),
(184640, 'عفو کردن', '<span class=\"hlight\">عفو کردن .</span> <font color=\"DarkGreen\"><b>[ ع َف ْوْ ک َ دَ ]</font></b> (مص مرکب ) آمرزیدن و بخشیدن . معذور داشتن . پوزش پذیرفتن . معاف کردن . درگذشتن . (ناظم الاطباء). از گناه کسی درگذشتن . بخشودن . (فرهنگ فارسی معین ). رجوع به عفو شود <span class=\"hlight\">:</span> <br>بکن عفو یارب گناه ورا<br>بیفزای در حشر جاه ورا.<br> <font color=\"Red\">فردوسی .</font><br>صد گنه کردم و او کرد عفو وین نه عجب <br>که خوی خواجه کریم است و دل خواجه رحیم .<br> <font color=\"Red\">فرخی .</font><br>پس از نماز دگر روزگار آدینه <br>نبید خور که گناهان عفو کند ایزد.<br> <font color=\"Red\">منوچهری .</font><br>اگر زلت نبودی کهتران را<br>عفو کردن نبودی مهتران را.<br> <font color=\"Red\">(ویس و رامین ).</font><br>دگر ره شاه رامین را عفو کرد<br>دریده بخت رامین را رفو کرد.<br> <font color=\"Red\">(ویس و رامین ).</font><br>این یک بار عفو کردم و این غلام را به تو بخشیدم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٥٤</span>). او را عفو کرد و ضیاع گوزکانان به وی ارزانی داشت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٦٤</span>). اگر رأی عالی بیند وی را عفو کرده آید تا به رباطی نشیند. (تاریخ بیهقی ).<br>مرا عفو کن زانکه نزدیک تو من <br>بجز عفو تو عذرخواهی ندارم .<br> <font color=\"Red\">عطار.</font><br>باز آمد کای محمد عفو کن <br>ای ترا الطاف علم من لدن .<br> <font color=\"Red\">مولوی .</font><br>آن کو بغیر سابقه چندین نواخت کرد<br>ممکن بود که عفو کند گر خطا کنیم .<br> <font color=\"Red\">سعدی .</font><br>خبر داد پیغمر از حال مرد<br>که داور گناهان او عفو کرد.<br> <font color=\"Red\">سعدی .</font><br>گنه عفو کرد آل یعقوب را<br>که معنی بود صورت خوب را.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عفو کردن ظالمان جور است برمظلومان </span> . (گلستان ).<br>- <span class=\"hlight\">عفو کردن خون </span> ؛ بحل کردن خون . (آنندراج ) <span class=\"hlight\">:</span> <br>نامش ار گاه خطا بر لب قاتل گذرد<br>خون خود عفو کند روز جزا کشته ٔ دار.<br> <font color=\"Red\">علی قلی بیگ علی خراسانی (از آنندراج ).</font><br>ولی خون را باشد که عفو کند. (تفسیر ابوالفتوح رازی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٢</span>).<br></font></div>'),
(184641, 'عفواندوز', '<span class=\"hlight\">عفواندوز.</span> <font color=\"DarkGreen\"><b>[ ع َف ْوْ اَ ]</font></b> (نف مرکب ) عفواندوزنده . ذخیره کننده ٔ عفو. که عفو بسیار کند <span class=\"hlight\">:</span> <br>گنه بخشا و عفواندوز می باش <br>به خوشخوئی چو روشن روز می باش .<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(184642, 'عفوس', '<span class=\"hlight\">عفوس .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) خطمی بری . (اختیارات بدیعی ). رجوع به خطمی شود.<br></font></div>'),
(184643, 'عفوصت', '<span class=\"hlight\">عفوصت .</span> <font color=\"DarkGreen\"><b>[ ع ُ ص َ ]</font></b> (ع اِمص ) دهان فراز هم کشیدن . (ذخیره ٔ خوارزمشاهی ). عفوصة. گسی . تلخی . زمختی . مزه ٔ هر چیز زمخت و قابض . (ناظم الاطباء). قبض . بشاعت . دندی . عفصی <span class=\"hlight\">:</span> درحلق عفوصتی بیاید چنانکه گوئی مازو خورده است . (ذخیره ٔ خوارزمشاهی ). رجوع به عفص و عفصی و عفوصة شود.<br></font></div>'),
(184644, 'عفوق', '<span class=\"hlight\">عفوق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) پریشان و متفرق شدن شتران در چراگاه بعد گذاشتن در آن و بر سر خود رفتن آنها. (از منتهی الارب ) (از اقرب الموارد). عَفق . رجوع به عفق شود.<br></font></div>'),
(184645, 'عفونات', '<span class=\"hlight\">عفونات .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عفونت . (فرهنگ فارسی معین ). رجوع به عفونت و عفونة شود.<br></font></div>'),
(184646, 'عفونة', '<span class=\"hlight\">عفونة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ن َ ]</font></b> (ع مص ) پوسیده شدن در نم . (تاج المصادر بیهقی ) گنده شدن و پوسیده شدن در نم . (دهار). بدبوی و گنده شدن چیزی . (آنندراج ). عَفَن .(اقرب الموارد) (منتهی الارب ). رجوع به عفن و عفونت شود. <BR><font color=\"Blue\">◄</font> (اِمص ) دلگیری هوا. (منتهی الارب ).<br></font></div>'),
(184647, 'عفونت', '<span class=\"hlight\">عفونت .</span> <font color=\"DarkGreen\"><b>[ ع ُ ن َ ]</font></b> (ع اِمص ) عفونة.بدبوئی . گنده بوئی . تعفن . گندیدگی . (ناظم الاطباء). بدبوئی و گنده شدن چیزی . (غیاث اللغات ). پارسی عفونت پوسیدن است یعنی رطوبتی تباه شده و از حال خویش بگردیده . (ذخیره ٔ خوارزمشاهی ). بویناکی . دفر. تعفن . نتن .گندگی . گندائی <span class=\"hlight\">:</span> و لشکرهای ما به عفونت این هوا مستأذی شوند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١١٤</span>). <BR><font color=\"Blue\">◄</font> در اصطلاح پزشکی، گندیدگی و آلودگی و چرکینی زخمها و ورمها و دیگر ضایعات اندامهای داخلی و یا خارجی بدن، و آن بر اثر تهاجم و غلبه ٔ میکربهای مختلف در انساج مختلف حاصل می شود. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">رفع عفونت کردن </span> ؛ ضدعفونی کردن . (فرهنگ فارسی معین ).<br></font></div>'),
(184648, 'عفونی', '<span class=\"hlight\">عفونی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص نسبی ) منسوب به عفونة و عفونت . دارای عفونت <span class=\"hlight\">:</span> قانون علاج تبهای عفونی ... بکار باید داشت . (ذخیره ٔ خوارزمشاهی ). رجوع به عفونت و عفونة و تب عفونی شود.<br>- <span class=\"hlight\">ضدعفونی </span> ؛ آنکه عفونتش زایل شده است . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">ضدعفونی شده </span> ؛ در اصطلاح پزشکی، پاک شده از پلیدی و ناپاکی و میکرب . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">ضدعفونی کردن </span> ؛ در اصطلاح پزشکی، از ناپاکی و عفونت زدودن . محل یا موضعی را که قبلاً آلودگی داشته و یا مشکوک به ناپاکی بوده است از میکرب و مواد آلوده کننده پاک کردن . گندزدایی . پلشت بری . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">ضدعفونی کننده </span> ؛ در اصطلاح پزشکی، موادی که برای ضد عفونی کردن بکار روند. وسایل و داروها و اجسام و عناصری که آلودگیها را پاک کنند و میکربها را از بین ببرند. گندزدا. پلشت بر. (فرهنگ فارسی معین ).<br></font></div>'),
(184649, 'عفونی شدن', '<span class=\"hlight\">عفونی شدن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش ُ دَ ]</font></b> (مص مرکب ) بدبو و گندیده شدن .مقابل ضدعفونی شدن : جراحت وی و ترس از عفونی شدن آن لزوم عمل جراحی را قطعی کرد. (فرهنگ فارسی معین ).<br></font></div>'),
(184650, 'عفوه', '<span class=\"hlight\">عفوه .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) برابر و موافق نمودن . (از منتهی الارب ). تطبیق . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تمامه ٔ چیزی گرفتن . (از منتهی الارب ).<br></font></div>'),
(184651, 'عفوپیشه', '<span class=\"hlight\">عفوپیشه .</span> <font color=\"DarkGreen\"><b>[ ع َف ْوْ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص مرکب ) آمرزش کننده و رحیم دل . (آنندراج ). بخشایشگر و رحیم و شفیق و آمرزنده و در گذرنده از عقوبت . (ناظم الاطباء). آنکه عفو را شعار خود قرار دهد. (فرهنگ فارسی معین ).<br></font></div>'),
(184652, 'عفوگاه', '<span class=\"hlight\">عفوگاه .</span> <font color=\"DarkGreen\"><b>[ ع َف ْوْ ]</font></b> (اِ مرکب ) عفوگه . جایی که آمرزش گنهکاران در آن کنند. (آنندراج ) <span class=\"hlight\">:</span> <br>چون فیض ازل در آن مکان ماند<br>هم چون گنهم به عفوگه خواند.<br><font color=\"Red\">(آنندراج ).</font><br></font></div>'),
(184653, 'عفک', '<span class=\"hlight\">عفک .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ عَفکاء. (اقرب الموارد). رجوع به عفکاء شود.<br></font></div>'),
(184654, 'عفک', '<span class=\"hlight\">عفک .</span> <font color=\"DarkGreen\"><b>[ ع َ ف ِ ]</font></b> (ع ص ) گول . (منتهی الارب ).<br></font></div>'),
(184655, 'عفک', '<span class=\"hlight\">عفک .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع مص ) سخت گول گردیدن . (از منتهی الارب ). بسیار احمق شدن . (از اقرب الموارد). عَفک . رجوع به عفک شود.<br></font></div>'),
(184656, 'عفک', '<span class=\"hlight\">عفک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) استوار نکردن سخن را و ناسره گفتن آنرا. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بازداشتن از حاجت . <BR><font color=\"Blue\">◄</font> مماطلت کردن حق کسی را. <BR><font color=\"Blue\">◄</font> سخت گول گردیدن . (از منتهی الارب ). بسیار احمق شدن . (از اقرب الموارد). عَفَک . رجوع به عفک شود.<br></font></div>'),
(184657, 'عفکل', '<span class=\"hlight\">عفکل .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ]</font></b> (ع ص ) گول . (منتهی الارب ). احمق . (اقرب الموارد).<br></font></div>'),
(184658, 'عفی', '<span class=\"hlight\">عفی .</span> <font color=\"DarkGreen\"><b>[ ع ُ فی ی ]</font></b> (ع ص، اِ) ج ِ عافی . (منتهی الارب ) (اقرب الموارد). رجوع به عافی شود.<br></font></div>'),
(184659, 'عفی عنه', '<span class=\"hlight\">عفی عنه .</span> <font color=\"DarkGreen\"><b>[ ع ُ ی َ ع َ ه ْ ]</font></b> (ع جمله ٔ فعلیه ٔ دعایی ) بخشوده باد! (فرهنگ فارسی معین ).<br></font></div>'),
(184660, 'عفیتة', '<span class=\"hlight\">عفیتة.</span> <font color=\"DarkGreen\"><b>[ع َ ت َ ]</font></b> (ع اِ) بتابة، که نوعی از حلوا است . (منتهی الارب ). عصیده . (اقرب الموارد). رجوع به عصیدة شود.<br></font></div>'),
(184661, 'عفیدن', '<span class=\"hlight\">عفیدن .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (مص جعلی ) آواز کردن سگ . (آنندراج ). عف عف کردن و فریاد کردن سگ . (ناظم الاطباء).<br></font></div>'),
(184662, 'عفیر', '<span class=\"hlight\">عفیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) گوشت به آفتاب خشک کرده بر ریگ تفسان . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پست شورانیده بی شیرینی، یا پِست ناشورانیده . (منتهی الارب ). «سویق » و قاووت که با «ادام » مخلوط نباشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نان بی نان خورش . (منتهی الارب ). خبز عفیر؛ نان بدون ادام . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زنی که به همسایه چیزی ندهد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184663, 'عفیر', '<span class=\"hlight\">عفیر.</span><font color=\"DarkGreen\"><b>[ ع ُ ف َ ]</font></b> (اِخ ) نام خر پیغمبر (ص ) مانند یعفور. <BR><font color=\"Blue\">◄</font> اسبی است مر جهینه را. (از منتهی الارب ).<br></font></div>'),
(184664, 'عفیر', '<span class=\"hlight\">عفیر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ف َ ]</font></b> (اِخ ) ابن عدی بن حارث، از کهلان از قحطانیه . جدی است جاهلی و او پدر قبیله ٔ مشهور «کندة» می باشد. (از الاعلام زرکلی به نقل از نهایةالارب ص <span class=\"hlight\" dir=\"rtl\">٢٩٦</span> و جمهرةالانساب ص <span class=\"hlight\" dir=\"rtl\">٣٩٩</span>).<br></font></div>'),
(184665, 'عفیر', '<span class=\"hlight\">عفیر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ف َ ]</font></b> (اِخ ) ابن معدان، تابعی است . رجوع به ابوعائذ (عفیر...) شود.<br></font></div>'),
(184666, 'عفیصا', '<span class=\"hlight\">عفیصا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ف َ ]</font></b> (اِخ ) نام آبی است در نزدیکی طفخه ٔ غربی . (از معجم البلدان ).<br></font></div>'),
(184667, 'عفیط', '<span class=\"hlight\">عفیط.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) تیز دادن بز. (از منتهی الارب ) (از اقرب الموارد). عَفط. عَفَطان . و رجوع به عفط و عفطان شود. <BR><font color=\"Blue\">◄</font> بینی افشاندن میش، بسان خر. (از اقرب الموارد). عَفط. و رجوع به عفط شود. <BR><font color=\"Blue\">◄</font> (اِ) آب بینی میش . (از منتهی الارب ). عفطة. رجوع به عفطة شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(184668, 'عفیف', '<span class=\"hlight\">عفیف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) پارسا. (منتهی الارب ). مرد پارسا و پرهیزگار از حرام . (غیاث اللغات ) (آنندراج ). پارسا و پرهیزگار. (دهار). کسی که عفت پیشه دارد. (فرهنگ فارسی معین ) (از اقرب الموارد). پاکدامن . (دستور اللغة). خویشتن دار. خوددار. آبرومند.باعفت . عَف ّ ج، أعفّاء. (منتهی الارب ) (اقرب الموارد) <span class=\"hlight\">:</span> به کمتر زله ای عقوبات عفیف  کردی . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٦٨</span>).<br>- <span class=\"hlight\">عفیف الطعمه </span> ؛ حلال خوار. (یادداشت به خط دهخدا).<br></font></div>'),
(184669, 'عفیف', '<span class=\"hlight\">عفیف .</span><font color=\"DarkGreen\"><b>[ ع ُ ف َ ی ی ِ ]</font></b> (ع ص مصغر) مصغر عَفیف است و آن نام چند تن باشد. (از منتهی الارب ). رجوع به عَفیف شود.<br></font></div>'),
(184670, 'عفیف', '<span class=\"hlight\">عفیف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ف َ ]</font></b> (اِخ ) از اعلام است . (از منتهی الارب ).<br></font></div>'),
(184671, 'عفیف آباد', '<span class=\"hlight\">عفیف آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی از بخش حومه شهرستان نائین . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٣١٩</span> تن . آب آنجا از قنات و محصولات آن غلات است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(184672, 'عفیف الدین', '<span class=\"hlight\">عفیف الدین .</span> <font color=\"DarkGreen\"><b>[ ع َ فُدْ دی ]</font></b> (اِخ ) سلیمان بن علی بن عبداﷲ تلمسانی . شاعر قرن هفتم . رجوع به عفیف تلمسانی شود.<br></font></div>'),
(184673, 'عفیف الدین', '<span class=\"hlight\">عفیف الدین .</span> <font color=\"DarkGreen\"><b>[ ع َ فُدْ دی ]</font></b> (اِخ ) لقب عبداﷲبن اسعد تمیمی یافعی . از کبار مشایخ قرن هشتم هجری . رجوع به ابوالسادات (عبداﷲ...) شود.<br></font></div>'),
(184674, 'عفیف تلمسانی', '<span class=\"hlight\">عفیف تلمسانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ف ِ ت ِ م ِ ]</font></b> (اِخ ) سلیمان بن علی بن عبداﷲبن علی کومی تلمسانی، ملقب به عفیف الدین . شاعر قرن هفتم هجری . اصل او از قبیله ٔ کومه است، به سال <span class=\"hlight\" dir=\"rtl\">٦١٠</span> هَ . ق . متولد شد و در بلاد روم سیاحت کرد سپس ساکن دمشق شد. او صوفی مذهب و بر روش ابن العربی بود. و به سال <span class=\"hlight\" dir=\"rtl\">٦٩٠</span> هَ. ق . در دمشق درگذشت . او را کتب بسیاری است که از آن جمله است : شرح مواقف نفزی، شرح الفصوص ابن عربی، کتابی در عروض . و نیز دیوان شعری دارد. (از الاعلام زرکلی به نقل از النجوم الزاهرة و البدایة والنهایة و آداب اللغة العربیة و شذرات الذهب و فوات الوفیات ).<br></font></div>'),
(184675, 'عفیفات', '<span class=\"hlight\">عفیفات .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) ج ِ عَفیفة. (منتهی الارب ) (اقرب الموارد). رجوع به عفیفة شود.<br></font></div>'),
(184676, 'عفیفة', '<span class=\"hlight\">عفیفة.</span> <font color=\"DarkGreen\"><b>[ ع َ فی ف َ ]</font></b> (اِخ ) لیلی دختر لُکَیزبن مرةبن اسد. از زنان شاعر عرب در عهد جاهلیت . رجوع به لیلی (بنت لکیز...) شود.<br></font></div>'),
(184677, 'عفیفة', '<span class=\"hlight\">عفیفة.</span> <font color=\"DarkGreen\"><b>[ ع َ فی ف َ ]</font></b> (اِخ ) دختر یوسف میخائیل صالح کرم . از زنان نویسنده و ادیب معاصر در لبنان بود. (<span class=\"hlight\" dir=\"rtl\">١٨٨٣</span>- <span class=\"hlight\" dir=\"rtl\">١٩٢٤</span>م .) برای شرح او رجوع به اعلام النساء ج <span class=\"hlight\" dir=\"rtl\">٣</span> شود.<br></font></div>'),
(184678, 'عفیفة', '<span class=\"hlight\">عفیفة.</span> <font color=\"DarkGreen\"><b>[ ع َ فی ف َ ]</font></b> (اِخ ) دختر محمدبن محمد نویری مکی . از زنان محدث بود. در جمادی الاولای سال <span class=\"hlight\" dir=\"rtl\">٨٤٦</span> هَ . ق . متولد شد و حدیث را نزد ابوالفتح مراغی آموخت . وی در ذی حجه ٔ سال <span class=\"hlight\" dir=\"rtl\">٨٨٥</span> هَ . ق . درگذشت و در معلاة دفن شد. (از اعلام النساء از الضوء اللامع).<br></font></div>'),
(184679, 'عفیفة', '<span class=\"hlight\">عفیفة.</span> <font color=\"DarkGreen\"><b>[ ع َ فی ف َ ]</font></b> (اِخ ) دختر سعید شرتونی (<span class=\"hlight\" dir=\"rtl\">١٨٨٦</span> - <span class=\"hlight\" dir=\"rtl\">١٩٠٦</span> م .) از زنان ادیب و نویسنده ٔ معاصر لبنان . برای شرح حال او به اعلام النساء ج <span class=\"hlight\" dir=\"rtl\">٣</span> رجوع شود.<br></font></div>'),
(184680, 'عفیفة', '<span class=\"hlight\">عفیفة.</span> <font color=\"DarkGreen\"><b>[ ع َ فی ف َ ]</font></b> (اِخ ) دختر احمدبن عبداﷲ فارقانی اصفهانی . از زنان فاضل و محدث و فقیه بود. به سال <span class=\"hlight\" dir=\"rtl\">٥١٦</span> هَ . ق . متولد شد. و او آخرین کسی است که از عبدالواحد صاحب ابی نعیم روایت کرده است . او را اجازاتی عالی از اهالی اصفهان وبغداد بود که گویند بالغ بر پانصد شیخ می شد. عفیفه به سال <span class=\"hlight\" dir=\"rtl\">٦٠٦</span>هَ . ق . درگذشت . (از الاعلام زرکلی از شذرات الذهب ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٩</span>). و رجوع به اعلام النساء ج <span class=\"hlight\" dir=\"rtl\">٥</span> شود.<br></font></div>'),
(184681, 'عفیفة', '<span class=\"hlight\">عفیفة.</span> <font color=\"DarkGreen\"><b>[ ع َ فی ف َ ]</font></b> (ع ص )مؤنث عفیف . (منتهی الارب ) (از اقرب الموارد). زن پارسا؛ أی پاکدامن . (دهار). زن پارسا و پرهیزگار از حرام . (غیاث اللغات ) (آنندراج ). ذاتی را نامند که او را صفت چیرگی بر شهوت و تملک نفس بغایت باشد. به عبارت دیگر زن سخت پاکدامن را عفیفه گویند. و شرعاً زنی را نامند که از وطی حرام بری و از تهمت چنین نسبتی به او معصوم باشد. و این چنین زن است که اگر بسوی او افترا و تهمتی روا دارند، درباره ٔ مفتری لعان واجب گردد. (از کشاف اصطلاحات الفنون ). ج، عَفیفات و عَفائف . (منتهی الارب ) (اقرب الموارد). رجوع به عفیفه شود.<br></font></div>'),
(184682, 'عفیفه', '<span class=\"hlight\">عفیفه .</span> <font color=\"DarkGreen\"><b>[ ع َ فی ف َ ]</font></b> (ع ص ) عفیفة. زن پارسا و باعصمت و باحیا و باشرم و متدین و پاکدامن .ج، عفیفگان . (ناظم الاطباء). و رجوع به عفیفة شود.<br>توئی که جز تو نپنداشت با بصارت خویش <br>عفیفه مریم مرپور خویش را پدری .<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(184683, 'عفیفگان', '<span class=\"hlight\">عفیفگان .</span> <font color=\"DarkGreen\"><b>[ ع َ فی ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ]</font></b> (اِ) ج ِ عفیفه . (ناظم الاطباء). رجوع به عفیفه شود.<br></font></div>'),
(184684, 'عفیفی', '<span class=\"hlight\">عفیفی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) (عبداﷲ...) از ادیبان و شاعران معاصر. وی ابتدا در دانشگاه ازهر و دارالعلوم قاهره تحصیل کرد سپس به تعلیم زبان عربی در مدارس آنجا پرداخت و به عنوان «محرر» در دیوان سلطنت بکار پرداخت و به سال <span class=\"hlight\" dir=\"rtl\">١٣٦٣</span> هَ . ق . درگذشت . او راست : تفسیر سوره ٔ الفتح و بیان ما اتصل بها من الفتوح الاسلامیة و السیرة النبویة المولد النبوی المختار. المراءة العربیة فی جاهلیتها و اسلامها، در سه جلد. الهادی، که داستانی است مربوط به هادی عباسی . منهج الادب . زهرات منشورة فی الادب العربی . (از الاعلام زرکلی ).<br></font></div>'),
(184685, 'عفیفی', '<span class=\"hlight\">عفیفی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (حامص ) پاکدامنی . پارسائی . عصمت . حیا. شرم . (ناظم الاطباء). عفت .عفة. عفاف . رجوع به عفیف و عفة و عفت و عفاف شود.<br></font></div>'),
(184686, 'عفیق', '<span class=\"hlight\">عفیق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ف َ ]</font></b> (اِخ ) از اعلام است . (از منتهی الارب ).<br></font></div>'),
(184687, 'عفیقان', '<span class=\"hlight\">عفیقان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) گیاهی است مانند عرفج . (از منتهی الارب ). گیاهی است خاردار. (از ناظم الاطباء). عیفقان . (اقرب الموارد). رجوع به عَیفَقان شود.<br></font></div>'),
(184688, 'عفین', '<span class=\"hlight\">عفین .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) عَفِن . با عفونت <span class=\"hlight\">:</span> هوای جرجان وبی و عفین است و لشکرهای ما به عفونت این هوا مستأذی شوند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١١٤</span>).<br></font></div>'),
(184689, 'عفیک', '<span class=\"hlight\">عفیک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) نیک گول . (منتهی الارب ). بسیار احمق . (از اقرب الموارد). عَفنَّک . رجوع به عفنک شود.<br></font></div>'),
(184690, 'عق', '<span class=\"hlight\">عق .</span> <font color=\"DarkGreen\"><b>[ ع َق ق ]</font></b> (ع مص ) شکافتن جامه . (منتهی الارب ) (از اقرب الموارد). شکافتن . (المصادر زوزنی ) (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> قربان کردن در هفته ٔ نخست مولود. (از منتهی الارب ). ذبح کردن برای نوزاد در روز هفتم، و نیز تراشیدن «عقیقه ٔ» او را. (از اقرب الموارد). کشتن گوسفند در وقت راندن فرزند، و موی باز کردن او. (المصادر زوزنی ). گوسفند کشتن از فرزندروز هفتم و موی وی باز کردن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> نیزه بسوی آسمان انداختن . (از منتهی الارب ). پرتاب کردن نیزه را بسوی آسمان . و چنین نیزه ای را عقیق نامند. (از اقرب الموارد). تیر سوی آسمان انداختن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> فروریختن باد از ابر باران دار، باران را. (از اقرب الموارد).<br></font></div>'),
(184691, 'عق', '<span class=\"hlight\">عق .</span> <font color=\"DarkGreen\"><b>[ ع ِق ق ]</font></b> (ع اِ) گو دورتک در زمین . (منتهی الارب ).<br></font></div>'),
(184692, 'عق', '<span class=\"hlight\">عق .</span> <font color=\"DarkGreen\"><b>[ ع َق ق ]</font></b> (ع ص ) نافرمان پدر ومادر و آزارده آنها را. (منتهی الارب ). عاق ّ. (اقرب الموارد). و رجوع به عاق شود. <BR><font color=\"Blue\">◄</font> (اِ) شکاف . (منتهی الارب ). هر شکافی که در ریگ و غیره باشد. <BR><font color=\"Blue\">◄</font> حفره ٔ عمیق در زمین . (از اقرب الموارد).<br></font></div>'),
(184693, 'عق', '<span class=\"hlight\">عق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِ صوت ) حال قی . غثیان . (فرهنگ فارسی معین ). و رجوع به عق زدن و عق شدن و عق گرفتن و عق نشستن شود.<br>- <span class=\"hlight\">عق وپق راه انداختن </span> ؛ در تداول عامه، قی کردن . استفراغ کردن . (فرهنگ فارسی معین ).<br></font></div>'),
(184694, 'عق', '<span class=\"hlight\">عق .</span> <font color=\"DarkGreen\"><b>[ ع ُق ق ]</font></b> (ع ص ) ماء عق ؛ آب تلخ . (منتهی الارب ) (از اقرب الموارد). قُعّ. رجوع به قع شود.<br></font></div>'),
(184695, 'عق زدن', '<span class=\"hlight\">عق زدن .</span> <font color=\"DarkGreen\"><b>[ ع ُ زَ دَ ]</font></b> (مص مرکب ) به دل آشوبه مبتلی شدن . استفراغ کردن . حال تهوع یافتن یا حال استفراغ داشتن . اشکوفه افتادن بر کسی . <BR><font color=\"Blue\">◄</font> گاهی زنان برای نشان دادن انزجار و نفرت خود از چیزی گویند:عق زدم یا داشتم عق میزدم . (از فرهنگ لغات عامیانه ). رجوع به عق و عق شدن و عق گرفتن و عق نشستن شود.<br></font></div>'),
(184696, 'عق شدن', '<span class=\"hlight\">عق شدن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش ُ دَ ]</font></b> (مص مرکب ) حال قی به کسی دست دادن . (از فرهنگ فارسی معین ). اشکوفه افتادن کسی را<span class=\"hlight\">:</span> به سبب بیماری اگر در گلوی تو چیزی بگیرد از ورخجی بیرون شو کن که خسکی در گلوی من فرورفته است عق ام میشود از آن سوتر روم . (معارف بهأولد ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>). و رجوع به عق و عق زدن و عق گرفتن و عق نشستن شود.<br></font></div>'),
(184697, 'عق نشستن', '<span class=\"hlight\">عق نشستن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ن ِ ش َ ت َ ]</font></b> (مص مرکب ) حال قی به کسی دست دادن . و غالباً به معنی مجازی برای نشان دادن نفرت و انزجار استعمال شود. (از فرهنگ لغات عامیانه ). و رجوع به عق و عق زدن و عق شدن و عق گرفتن شود.<br></font></div>'),
(184698, 'عق گرفتن', '<span class=\"hlight\">عق گرفتن .</span> <font color=\"DarkGreen\"><b>[ ع ُ گ ِ رِ ت َ ]</font></b> (مص مرکب ) حال قی به کسی دست دادن . (از فرهنگ فارسی معین ). تهوع دست دادن . اشکوفه افتادن . <BR><font color=\"Blue\">◄</font> غالباً به معنی مجازی و برای نشان دادن نفرت و انزجار استعمال میشود. (از فرهنگ لغات عامیانه ). و رجوع به عق و عق زدن و عق شدن و عق نشستن شود.<br></font></div>'),
(184699, 'عقاب', '<span class=\"hlight\">عقاب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) مرغی است و عقاب تیزچنگال . (منتهی الارب ). مرغ شکاری سیاه . (غیاث اللغات ) (ناظم الاطباء). پرنده ای است از جوارح و چنگال داران که عرب آن را کاسر نامد. و گویند عقاب «سیّد» پرندگان است و نسر «عریف » آنها. عقاب را «خداریة» نیز نامند و او را چشمانی تیزبین است، لذا در مثل گویند أبصر من عقاب . ماده ٔ آن را «لقوة» گویند، و برخی لقوه را عقاب تیزپر دانند. عقاب را «عنقاء مغرب » نیز دانند زیرا از اماکن دور دست می آید. و برخی عقاب را بر نر و ماده اطلاق کنند. (از اقرب الموارد).یک نوع مرغ شکاری که اُلْه و اُلَّه و یا ججا نیز گویند و قسم سیاه آن را دال و دالمن گویند. (ناظم الاطباء). طایر سبعی معروف است و به فارسی الوه و به ترکی قراقوش نامند. (تحفه ٔ حکیم مؤمن ). مرغی شکاری و ناپاک است و کوچکترین آن را رخم یا مرغ فرعون نامند، و اشتباهاً آن را لاشخور نامیده اند. (قاموس کتاب مقدس ).عقاب به صورت مؤنث بکار رود و مذکر نباشد و از بزرگترین جوارح است رنگ اصلی آن سیاه باشد. و گویند نر آن را «غرن » نامند و برخی نر آن را از جنسی دیگر غیراز عقاب دانسته اند. عقاب، آهو و روباه و خرگوش و گاهی گورخر را نیز شکار می کند. برای شکار گورخر، عقاب خود را به آب می زند سپس در خاک می غلطد و به پرواز درمی آید و چون به گورخر رسید بالهای خود را تکان می دهدتا خاکهای آن به چشم گور رود و از حرکت بازایستد و شکارچی آن را شکار کند. عقاب عادةً خود در پی شکار نمی رود، بلکه بر بلندی می ایستد و چون پرنده ای را ببیند که شکاری کرده است به سمت او می رود و آن پرنده از بیم جان شکار خود را رها می کند. و می گریزد و عقاب آن شکار را برمی دارد عقاب جوجه های خود را بیش از دیگر پرندگان مخفی می دارد. و گویند نخستین کسانی که عقاب را شناختند و آن را به بازی گرفتند اهل مغرب و رومیان بوده اند. انواع مختلف عقاب در کوهها و صحراها و جنگلها و اطراف شهرها مسکن می کنند. و رنگ آنها سیاه، سیاه مایل به سرخی، شفتالوئی، سفید و بور است . در شرع اسلام خوردن آن حرام است چون از پرندگان چنگال دار می باشد و کشتن آن را برخی مستحب دانند و برخی استحباب و کراهت آنرا، نفی کرده اند. (از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٣</span> و <span class=\"hlight\" dir=\"rtl\">٦٥</span>). پرنده ای است از راسته ٔ شکاریان و از دسته ٔ شکاریان روزانه که دارای جثه ای نسبتاً بزرگ و پنجه و منقاری بسیار قوی است . این پرنده بسیار جسور و پرجرأت است و نسبت به دیگر پرندگان شکاری قدرت و شجاعتی مخصوص دارد، بطوری که برخی خلبانان گزارش داده اند عقاب حتی به هواپیماهای کوچک حمله می کند و گاهی نیز موجب خطراتی می گردد. به همین جهت عقاب را به نام «سلطان پرندگان » می نامند. در یونان قدیم عقاب نشانه ٔ ژوپیتر بود و رومیان عقاب را نماینده ٔ قدرت خارق العاده می دانستند و روی چوبه های درفش ملی خود مجسمه ٔ او را به عنوان یک قدرت شکست ناپذیر نصب می کردند. ایرانیان باستان نیز آن را شعار و مظهر قدرت خویش قرار داده بودند. پرواز این پرنده به قدری زیاد است که ساعتهای متمادی می تواند به پرواز خود ادامه دهد و مسافات طولانی را به سهولت طی کند و تا ارتفاع بسیار زیاد اوج بگیرد. منقار عقاب بسیار قوی و برنده است و دارای پنجه هایی پرقدرت و ناخنهایی بسیار تیز و خمیده است . عضلات پنجه و پای وی به قدری نیرومند و پرقدرت است که می تواند حیوانات قوی جثه از قبیل روباه و بچه گوزن و بره های نسبةً بزرگ را به سهولت و سادگی از زمین برباید. در گرسنگی پرطاقت است و تا چند روز می تواند تحمل گرسنگی کند. قدرت دید این پرنده نیز بسیار است و از مسافات بسیار بعید کوچکترین حرکت از نظرش پوشیده نمی ماند. عقاب دارای کبر و غرور خاصی است و برای اینکه همواره به شکار خود تسلط داشته باشد عموماً در ارتفاعات زیاد پرواز می کند. در محوطه ٔ پرواز او دیگر پرندگان شکاری قدرت پریدن و تعقیب شکار را از دست می دهند و به مجرد دیدن عقاب شکار خود را رها کرده به منظور حفظ جان خود به گوشه ای پناه می برند. عقاب دارای انواع مختلف است که از نظر رنگ و بزرگی و کوچکی و شجاعت و دلاوری با هم تفاوت دارند، از قبیل عقاب شاهی  که از عقابهای دیگر قوی تر و شجاعتر و چابکتر و بلندپروازتر است و در قلل مرتفع آلپ وپیرنه بومی است . دیگر عقاب پیگارگ  که در سواحل دریاها می زید و به همین جهت به نام عقاب دریا نیز موسوم است . دیگر عقاب هلیااتوس لوکوسفالوس  که به نام عقاب آمریکایی نیز مشهور است، که این نوع آن در سال <span class=\"hlight\" dir=\"rtl\">١٨٧٢</span>م . طی قانونی در دومین کنگره ٔ آمریکا، به عنوان علامت رسمی دولت آمریکا شناخته شده است . (از فرهنگ فارسی معین ). کلمه ٔ عقاب مؤنث است . جمع قله ٔ آن أعقُب وجمع کثرت آن عِقبان و عقبان است . (از منتهی الارب ) (اقرب الموارد). ج، عَقابین . (از اقرب الموارد). اَلُه . (مهذب الاسماء). ابوالاشیم . ابوالحجاج . ابوحسبان . ابوالدهر. (مرصع). ابوقرة. ابوالهیثم . (دهار). اَلُه . ام الحوار. ام الشفوة. ام طلبة. ام کیح . ام لوح . ام الهیثم . (مرصع). أنوق . جَجا. حُباشیّة. خُدارّیة. (منتهی الارب ). دالمَن . ذولقوَة. سَتَل . سَهوک . شَفواء. (دهار). صومعة. عُبر. عُثر. عَزیبَة. عَزیزَة. عَنس . غَرَن . کاسِر. کَفَر. (منتهی الارب ). لَقوَة. (بحر الجواهر). لقیة. (دهار). کمّاعَة. (منتهی الارب ). مردارخوار. (زمخشری ). نُساریّة. (منتهی الارب ). تُلَج و تُلد، چوزه ٔ عقاب . خاتیة؛ عقاب که بر صید فرود آید. دَلوف ؛ عقاب تیزپرواز. شَقذاء و شَقَدی ̍؛ عقاب سخت گرسنه . عَبَنقاء و عَبَنقاة؛ عقاب تیزچنگل . عَجزاء؛ عقاب کوتاه دم و عقابی که در دم او پر سپید باشد. عَقَنباة؛ عقاب تیز چنگل . عَنز؛ ماده عقاب . فتخاء؛ عقاب فروهشته بال . قَیعَلة؛ عقاب که بر سر کوه جای گیرد. لَخواء؛ عقاب که منقار بالایش از زیرین بزرگ باشد. لَقوة؛ عقاب ماده . هَیثم ؛ چوزه ٔ عقاب . (منتهی الارب ) <span class=\"hlight\">:</span> <br>بر که و بالا چوچه، همچون عقاب اندر هوا<br>بر تریوه راه چون چه، همچو در صحرا شمال .<br> <font color=\"Red\">شهید <font color=\"DarkGreen\"><b>[در صفت اسب ]</font></b>.</font><br>از آن کردار کو مردم رباید<br>عقاب تیز نرباید خشین سار.<br> <font color=\"Red\">دقیقی .</font><br>چنین گفت با گیو جنگی تژاو<br>که تو چون عقابی و من چون چکاو.<br> <font color=\"Red\">فردوسی .</font><br>نپرید بر گرد ایشان عقاب <br>یکی را سر اندر نیامد به خواب .<br> <font color=\"Red\">فردوسی .</font><br>پلنگ از بر سنگ و ماهی در آب <br>هم اندر هوا ابر و پران عقاب .<br> <font color=\"Red\">فردوسی .</font><br>ز شاهین و از باز و پران عقاب <br>ز شیر و پلنگ و نهنگ اندر آب .<br> <font color=\"Red\">فردوسی .</font><br>سیه شد ز گرد سپه آفتاب <br>ز پیکان پولاد و پرِّعقاب .<br> <font color=\"Red\">فردوسی .</font><br>تو گفتی که دریا به موج اندراست <br>عقاب اجل سوی اوج اندراست .<br> <font color=\"Red\">فردوسی .</font><br>ای عوض آفتاب روز و شبان تاب تاب <br>تو به مثل چون عقاب حاسد ملعونت خاد.<br> <font color=\"Red\">منوچهری .</font><br>بیش بین چون کرکس و جولان کننده چون عقاب <br>راهوار ایدون چو کبک و راست رو همچون کلنگ .<br> <font color=\"Red\">منوچهری .</font><br>همیشه در فزع از وی سپاههای ملوک <br>چنان کجا به نواحی عقاب بر خرچال .<br> <font color=\"Red\">زینبی .</font><br>که ملکت شکاری است ... و عقاب پرنده و شیر ژیانی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٩٢</span>).<br>روزی ز سر سنگ عقابی به هوا خاست <br>از بهر طمع بال و پر خویش بیاراست .<br> <font color=\"Red\">ناصرخسرو.</font><br>سپس دین درون شو ای خرگوش <br>که به پرواز برشده ست عقاب .<br> <font color=\"Red\">ناصرخسرو.</font><br>جز شکار مردم هشیار هیچ <br>نیست چیزی کار این پران عقاب .<br> <font color=\"Red\">ناصرخسرو.</font><br>زمین شده همه چون چشم کبک و روی تذرو<br>هوا شده همه چون دم باز و پرعقاب .<br> <font color=\"Red\">مسعودسعد.</font><br>ز نوک رمح تو کندی گرفت چنگ هزبر<br>ز سم رخش تو کندی نمود پر عقاب .<br> <font color=\"Red\">مسعودسعد.</font><br>ز عدل تو بکند رنگ ناخنان هزبر<br>ز امن تو بکند کبک دیدهای عقاب .<br> <font color=\"Red\">مسعودسعد (دیوان چ رشیدیاسمی ص <span class=\"hlight\" dir=\"rtl\">٣٣</span>).</font><br>عقاب از وی <font color=\"DarkGreen\"><b>[ از باز ]</font></b> بزرگتر است ولیکن وی را آن حشمت نیستی که باز را. (نوروزنامه ).<br>وین ناوک ضمیر مرا پر جبرئیل <br>کرده ست بی نیاز ز پر عقابشان .<br> <font color=\"Red\">خاقانی .</font><br>نهنگ مرگ دید دهن بازکرده و عقاب اجل پر و بال گشاده و چنگال تیزکرده . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٧٢</span>). عقاب را در مراقی آن عقاب بال گسسته گشتی . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٣٨</span>).<br>چو طاووس عقابی باز بسته <br>تذروی بر لب کوثر نشسته .<br> <font color=\"Red\">نظامی .</font><br>به ذره آفتابی را که گیرد<br>به گنجشکی عقابی را که گیرد.<br> <font color=\"Red\">نظامی .</font><br>زلفت چو عقاب در عقب بود<br>بربود و کشیدش در عقابین .<br> <font color=\"Red\">عطار.</font><br>بیابان نوردی چو کشتی بر آب <br>که بالای سیرش نپرد عقاب .<br> <font color=\"Red\">سعدی .</font><br>هلاک خویشتن می خواهد آن مور<br>که خواهد پنجه کردن با عقابی .<br> <font color=\"Red\">سعدی .</font><br>عقابان تیزچنگالند و بازان آهنین پنجه <br>ترا باری چنین بهتر که با عصفور بنشینی .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">با سینه ٔ من چه کینه گردون را</span> <br>با پشه عقاب را چه ناورد است .<br> <font color=\"Red\">خاقانی .</font><br> <span class=\"hlight\">جائی که عقاب پر بریزد</span> <br>از پشه ٔ لاغری چه خیزد.<br> <font color=\"Red\">(امثال و حکم دهخدا).</font><br> <span class=\"hlight\">چشم من است واسطه ٔ چشم زخم من </span> <br>بال عقاب شد سبب آفت عقاب .<br> <font color=\"Red\">سلمان ساوجی .</font><br> <span class=\"hlight\">دل من نه مرد آن است که با غمش برآید</span> <br>مگسی کجا تواند که بیفکند عقابی .<br> <font color=\"Red\">سعدی .</font><br> <span class=\"hlight\">رنج حسد هلاک کند حاسد ترا</span> <br>آری پر عقاب بود آفت عقاب .<br> <font color=\"Red\">فخرالدین اوحد.</font><br> <span class=\"hlight\">کار جهان وبال جهان دان که بر خدنگ </span> <br>پر عقاب آفت جان عقاب شد.<br> <font color=\"Red\">خاقانی .</font><br> <span class=\"hlight\">نرسم در خیال تو چه عجب </span> <br>که مگس در عقاب می نرسد.<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">حجرالعقاب </span> ؛ حجر و سنگی است شبیه به تمر هندی . (از اقرب الموارد). رجوع به حجر شود.<br>- <span class=\"hlight\">عقاب آسمان </span> ؛ چند ستاره است به صورت عقاب و آن را نسر طائر نیز گویند. (غیاث اللغات ) (آنندراج ). رجوع به عقاب و نسر طائر شود.<br>- <span class=\"hlight\">عقاب آهنین منقار</span> ؛ کنایه از تیر پیکان دار است . (برهان ) (انجمن آرا) (از آنندراج ).<br>- <span class=\"hlight\">عقاب الجور</span> ؛ در بیت ذیل از خاقانی با نسخه بدل «عقاب الجود» و «عقاب الجو» آمده است و شاید اشاره به عقاب (درمعنی صورت فلکی ) باشد <span class=\"hlight\">:</span> <br>چون عقاب الجور آرنده ٔ جور<br>چون غراب البین آرنده ٔ بیم .<br>- <span class=\"hlight\">عقاب چهارپر</span> ؛ کنایه از تیر است که چهار پردارد. (انجمن آرا) <span class=\"hlight\">:</span> <br>عقاب چارپر یعنی مرا تیر<br>نهنگی در میان یعنی که شمشیر.<br> <font color=\"Red\">نظامی (انجمن آرا).</font><br>- <span class=\"hlight\">عقاب عَبَنقاء و عَبَنقاة و عَقَنباة وعَنقاة</span> ؛ عقاب تیزچنگل . (از منتهی الارب ) (از اقرب الموارد).<br>- <span class=\"hlight\">عقاب قَبعَلة</span> ؛ عقاب برآینده بر کوه، و عقاب کوه باش . (منتهی الارب ).<br>- <span class=\"hlight\">عقاب قَعَنباة</span>؛ عقاب تیزچنگال . (منتهی الارب ).<br>- <span class=\"hlight\">عقاب قَوعَلة</span> ؛ عقاب کوه باش و عقاب برآینده بر کوه . (از منتهی الارب ).<br>- <span class=\"hlight\">عقاب مَلارِع </span> ؛ عقاب موشخوار که کوچک باشد و کلاکموش را شکار کند. (منتهی الارب ).<br> <BR><font color=\"Blue\">◄</font> در اصطلاح عرفانی، قلم است که عقل اول باشد. و آن به سبب این است که عقل اول بالاترین چیزی است که در عالم قدس یافت شده است و چون عقاب بالاروترین پرندگان است در جو، لذا بدین نام خوانده شده است . (از تعریفات جرجانی ). کنایت ازعقل اول است و گاه از طبیعت کلیه تعبیر به عقاب می شود. (فرهنگ علوم عقلی از اصطلاحات شاه نعمةاﷲ ص <span class=\"hlight\" dir=\"rtl\">٥٤</span>). <BR><font color=\"Blue\">◄</font> به اصطلاح کیمیاگران، نوشادر است . (از غیاث اللغات ). به اصطلاح اکسیریان، نوشادر است . (تحفه ٔحکیم مؤمن ). <BR><font color=\"Blue\">◄</font> (اِخ ) در اصطلاح نجوم، یکی از صور فلکی در شمال برج قوس . ستاره ٔ روشن آن النسرالطائر است . (یادداشت به خط مرحوم دهخدا). نام صورتی از صور فلکیه از ناحیه ٔ شمالی و آن را بر مثال آلهی توهم کرده اند و آن نه کوکب است و خارج از صورت شش کوکب است . و ستاره ٔ روشن در این صورت است که آن را ذنب العقاب نامند. (یادداشت به خط مرحوم دهخدا). عقاب و سهم ؛ نام صورت دهم از صور نوزده گانه ٔ شمالی فلکی قدما است و آن را نسر طائر نیز گویند. (از مفاتیح العلوم ). یکی از صورتهای فلکی شمالی (دو صورت عقاب و سهم را توأما نسر طایر خوانند). (فرهنگ فارسی معین ).عقاب آسمان . رجوع به ترکیب عقاب آسمان و نسر طائر وذنب العقاب شود. <BR><font color=\"Blue\">◄</font> (ع اِ) مجازاً، اسب <span class=\"hlight\">:</span> <br>ناهید چون عقاب ترا دید روز جنگ <br>گفتا درست هاروت از بند رسته شد.<br> <font color=\"Red\">دقیقی .</font><br>عقاب تکاور برانگیختم <br>چو آتش برو تیر می ریختم .<br> <font color=\"Red\">فردوسی .</font><br>تورگ دلاور نشد هیچ کند<br>عقاب نبردی برانگیخت تند.<br> <font color=\"Red\">اسدی .</font><br> <BR><font color=\"Blue\">◄</font> سنگ میان چاه که دلو را دراند. (منتهی الارب ). سنگی که در میان چاه برآید و باعث شکافتن دلو گردد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سنگ بزرگ بیرون جسته از کوه مانند پایه ٔ نردبان . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سنگ در نورد چاه که بر آن آبکش ایستد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سنگ که بر آن ساقی بایستد. (دهار) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شبیه لوز که در پای ستور برآید. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> رشته ٔ خرد که در سوراخ حلقه ٔ گوشواره باشد. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> رشته ٔ کوچک که در سوراخ گوش کشندبرای گوشواره . (غیاث اللغات ). و رجوع به عقاب افکن شود. <BR><font color=\"Blue\">◄</font> آبراهه به سوی حوض . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پشته . (منتهی الارب ). رابیة. (اقرب الموارد) <span class=\"hlight\">:</span> <br>نگاه کردم از دور من تلی دیدم <br>که چاه ژرف نماید از آن بلند عقاب .<br> <font color=\"Red\">مسعودسعد.</font><br>چون زلف تو هواش ظلام از پس ظلام <br>چون کار من زمینش عقاب ازپس عقاب .<br> <font color=\"Red\">مسعودسعد.</font><br>دیده نه ای روز بدر کان شه دین بدروار<br>راند سپه در سپه سوی نشیب و عقاب .<br> <font color=\"Red\">خاقانی .</font><br>عقاب را در مراقی آن عقاب بال گسسته گشتی . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٣٨</span>). <BR><font color=\"Blue\">◄</font> هر بلندی زمین که بسیار دراز نباشد. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عَلم بزرگ . (منتهی الارب ) (دهار).رایت . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) نام چند اسب است عرب را. <BR><font color=\"Blue\">◄</font> نام ماده سگی است . (از منتهی الارب ).<br></font></div>'),
(184700, 'عقاب', '<span class=\"hlight\">عقاب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) شکنجه کردن . (از منتهی الارب ). مؤاخذه کردن کسی را بر گناه، و اسم آن «عقوبة» می شود. (از اقرب الموارد). عقوبت کردن . (دهار). جزای گناه و عمل بد کسی را دادن . (فرهنگ فارسی معین ). عذاب نمودن و شکنجه کردن . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> در پی کردن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> از پی کسی درآمدن . (دهار). <BR><font color=\"Blue\">◄</font> خواستن از اسب دویدن پس از دویدن را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> به نوبت کاری کردن . (دهار). <BR><font color=\"Blue\">◄</font> غنیمت یافتن . (دهار).<br></font></div>'),
(184701, 'عقاب', '<span class=\"hlight\">عقاب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) شهرکی است <font color=\"DarkGreen\"><b>[ به عربستان ]</font></b> با نعمت و مردم بسیار. (حدود العالم ).<br></font></div>'),
(184702, 'عقاب', '<span class=\"hlight\">عقاب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) (وقعه ٔ...) نام جنگی است که میان محمدبن یعقوب و فرنگ روی داد. (یادداشت به خط مرحوم دهخدا). واقعه ای است که در اندلس اتفاق افتاد و در آن آلفونس پادشاه قشتاله لشکریان موحدین را منهزم ساخت (<span class=\"hlight\" dir=\"rtl\">١٢١٢</span> م .) (فرهنگ فارسی معین ).<br></font></div>'),
(184703, 'عقاب', '<span class=\"hlight\">عقاب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) (تبق الَ ...) موضعی است به جحفه . (منتهی الارب ).<br></font></div>'),
(184704, 'عقاب', '<span class=\"hlight\">عقاب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) (ثنیة الَ ...) پشته ای است به دمشق . (منتهی الارب ). «فرجه »ای است در کوهی که بر غوطه ٔ دمشق مشرف است از ناحیه ٔ حمص . و قافله هایی که از شرق به غرب به سوی دمشق می آیند آن را قطع می کنند. (از معجم البلدان ). رجوع به ثنیةالعقاب شود.<br></font></div>'),
(184705, 'عقاب', '<span class=\"hlight\">عقاب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) نام رایت پیغمبر اسلام (ص ). (منتهی الارب ) (از اقرب الموارد). نام رایت و علم قریش بود، و آن از مصالح کعبه پیش از اسلام بشمار می آمد. هنگام جنگ آن را خارج می کردند و هر گاه بر کسی اتفاق نظر می یافتند آن را به وی تسلیم می کردند و در غیر اینصورت به صاحبش می دادند که یک بار از بنی امیه بود و یکبار از بنی عبدالدار. و ظاهراً این نام را از رومیان اقتباس کرده اند زیرا عقاب یا شاهین علامت رومیان بود که آن را بر رایتها و ساختمانهای خود نقش می کردند. (ازتاریخ التمدن الاسلامی جرجی زیدان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠</span> و <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br></font></div>'),
(184706, 'عقاب', '<span class=\"hlight\">عقاب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِمص، اِ) عذاب و شکنجه و پاداش بدی . (دهار). جزای بدی، و آن در پی گناه باشد، و گویند آن محنت و عذابی است که به دنبال ارتکاب گناه، در آخرت دامنگیر انسان می شود. (از اقرب الموارد). تنبیه و سیاست . (ناظم الاطباء). ضد ثواب . (اساس الاقتباس طوسی ). عقوبت . (مهذب الاسماء). آنچه به آدمی رسد بر اثر ارتکاب گناه در این جهان از رنج در جهان دیگر، اما همان رنجی را که ممکن است در نتیجه ٔ گناه در این جهان به آدمی رسد نام آن عقوبت باشد. (کشاف اصطلاحات الفنون ) <span class=\"hlight\">:</span> و لقد استهزی ٔ برسل من قبلک فأملیت للذین کفروا ثم أخذتهم فکیف کان عقاب ِ. (قرآن <span class=\"hlight\" dir=\"rtl\">٣٢/١٣</span>)؛ و همانا بر رسولانی پیش از تو استهزاء شد و به کسانی که کفر کردند مهلت دادم سپس آنها را گرفتم پس عقوبت من چگونه باشد. اًن کل الاّکذّب الرسل فحق ّ عقاب ِ. (قرآن <span class=\"hlight\" dir=\"rtl\">١٣/٣٨</span>)؛ همگی نبودند جز که رسولان را تکذیب کردند پس مجازات من لازم آمد. ان ربک لذومغفرة و ذوعقاب ألیم . (قرآن <span class=\"hlight\" dir=\"rtl\">٤٣/٤١</span>)؛ همانا پروردگار تو صاحب مغفرت و صاحب عقوبت دردناکی است . و هرچ بدان جهان باشد ثواب و عقاب جاوید باشد و هیچ بسر نیاید. (ترجمه ٔ تفسیر طبری ). حشر و قیامت خواهد بود و سؤال و جواب و ثواب و عقاب . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٣٩</span>). مردم را که ایزد... این دو نعمت عطا داده است لاجرم از بهایم جداست و به ثواب و عقاب می رسد. (تاریخ بیهقی ).<br>زادن ایشان ز تو ای گنده پیر<br>هست شگفتی چو ثواب از عقاب .<br> <font color=\"Red\">ناصرخسرو.</font><br>مرغ درویش بی گناه مگیر<br>که بگیرد ترا عقاب عقاب .<br> <font color=\"Red\">ناصرخسرو.</font><br>مگر که خدمت تو طاعت خدای شده ست <br>که هست بسته درو خلق را ثواب و عقاب .<br> <font color=\"Red\">مسعودسعد.</font><br>آنکه بی خدمتی ثواب دهیش <br>دید بایدش بی گناه عقاب .<br> <font color=\"Red\">مسعودسعد.</font><br>در معنی بعث و قیامت و ثواب و عقاب هیچ چیز نگفتم . (کلیله و دمنه ).<br>باج ستان ملوک، تاج ده انبیا<br>کز در او یافت عقل خط امان از عقاب .<br> <font color=\"Red\">خاقانی .</font><br>شاه را سوره ٔ فتوح رسید<br>خصم را آیت عقاب رساد.<br> <font color=\"Red\">خاقانی .</font><br>که گفته است فلان می گریزد از پی آن <br>که شاه بشنود و بازداردم به عقاب .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عقاب بلابیان </span> ؛ مجازات بدون بیان و توضیح قبلی . و «قبح عقاب بلابیان » از اصطلاحات فقهی است که مفاد آن این است که هر حکمی که بر بندگان بیان نشده باشد خدا نتواند عبد را بر آن مؤاخذه کند به حکم «ما حجب اﷲ علمه عن العباد فهو موضوع عنهم » چون تکلیف به مجهول محال و زشت است . (از فرهنگ علوم نقلی به نقل از وسائل ص <span class=\"hlight\" dir=\"rtl\">١٩٩</span> و کفایة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٩</span>).<br><BR><font color=\"Blue\">◄</font> ج ِ عَقَبة. (منتهی الارب ) (اقرب الموارد). رجوع به عقبة شود. <BR><font color=\"Blue\">◄</font> ج ِ عَقب . (اقرب الموارد). رجوع به عقب شود.<br></font></div>'),
(184707, 'عقاب افکن', '<span class=\"hlight\">عقاب افکن .</span> <font color=\"DarkGreen\"><b>[ ع ُ اَ ک َ ]</font></b> (نف مرکب ) عقاب افکننده . آنکه یا آنچه عقاب را بیندازد <span class=\"hlight\">:</span> <br>ز پرهای تیر عقاب افکنش <br>عقابان فزونند پیرامنش .<br> <font color=\"Red\">نظامی .</font><br>بسی خون گرو کرده در گردنش <br>عقابین چنگ عقاب افکنش .<br> <font color=\"Red\">نظامی .</font><br><BR><font color=\"Blue\">◄</font> کنایه از حلقه بگوش یعنی مطیع و غلام، چه عقاب بمعنی رشته است که در سوراخ گوش کشند برای انداختن حلقه . (غیاث اللغات ) (آنندراج ). رجوع به عقاب شود.<br></font></div>'),
(184708, 'عقاب بینی', '<span class=\"hlight\">عقاب بینی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ص مرکب ) که نوک بینی بسوی انسی برگشته دارد. (یادداشت به خط مرحوم دهخدا).<br></font></div>'),
(184709, 'عقاب شدن', '<span class=\"hlight\">عقاب شدن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ش ُ دَ ]</font></b> (مص مرکب ) کنایه از طالب شدن به چیزی . (برهان ) (انجمن آرا) (آنندراج ).<br></font></div>'),
(184710, 'عقاب پیشانی', '<span class=\"hlight\">عقاب پیشانی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ص مرکب ) با پیشانی پهن و گشاده . (یادداشت به خط مرحوم دهخدا).<br></font></div>'),
(184711, 'عقاب کردن', '<span class=\"hlight\">عقاب کردن .</span> <font color=\"DarkGreen\"><b>[ع ِ ک َ دَ ]</font></b> (مص مرکب ) شکنجه کردن . عذاب دادن . (فرهنگ فارسی معین ). معاقبة. عِقاب . رجوع به عِقاب شود.<br></font></div>'),
(184712, 'عقاب کینه', '<span class=\"hlight\">عقاب کینه .</span> <font color=\"DarkGreen\"><b>[ ع ُ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص مرکب ) که کینه ای چون کینه ٔ عقاب دارد. که آسان از مقصود بازنگردد <span class=\"hlight\">:</span> صیادی سگی معلّم داشت، ازین پهن بری ... ببرسینه ای عقاب کینه ای . (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٢٠٠</span>).<br></font></div>'),
(184713, 'عقابان', '<span class=\"hlight\">عقابان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) تثنیه ٔ عقاب، در حال رفع. عقابین . رجوع به عقابین شود.<br></font></div>'),
(184714, 'عقابة', '<span class=\"hlight\">عقابة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) بطنی است از حضرموت و نسبت بدان عُقابی شود. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(184715, 'عقابی', '<span class=\"hlight\">عقابی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (حامص ) عقاب بودن . عقاب شدن . کنایه از بلندپروازی . شعر ذیل از نظامی در وصف معراج رسول اکرم است و گویای اینکه رسول اکرم چون به قصد پرواز به اوج افلاک بر براق نشست، براق تیزپر از جای جهید <span class=\"hlight\">:</span> <br>چون درآورد در عقابی پای <br>کبک علوی خرام جست ز جای .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(184716, 'عقابی', '<span class=\"hlight\">عقابی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) منسوب به عقابة، و از آنان اواب بن عبداﷲبن محمد حضرمی عقابی شهرت دارد که محدث بود و از ابن بکیر و ابن عفیر روایت کرده است . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(184717, 'عقابیس', '<span class=\"hlight\">عقابیس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) بلاها و آفتها و داهیه ها. (ناظم الاطباء). دواهی . (اقرب الموارد).<br></font></div>'),
(184718, 'عقابیل', '<span class=\"hlight\">عقابیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عُقبول و عُقبولَة. (اقرب الموارد) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> شدائد و سختی ها. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> باقی مانده از بقیه و پسین چیزها.(منتهی الارب ). بقایای بیماری و دشمنی و عشق . (از اقرب الموارد) <span class=\"hlight\">:</span> مرض بها <font color=\"DarkGreen\"><b>[ امام فخرالدین محمدبن عمرالرازی بهرات ]</font></b> و توفی فی عقابیله ببلدة هرات .(عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦</span>). <BR><font color=\"Blue\">◄</font> آنچه از پس تب بر لب برآید. (از اقرب الموارد). تبخال . <BR><font color=\"Blue\">◄</font> هو ذو عقابیل ؛ او بسیار شریر است . (از منتهی الارب ) (از اقرب الموارد). رجوع به عقبول و عقبولة شود.<br></font></div>'),
(184719, 'عقابین', '<span class=\"hlight\">عقابین .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع اِ) تثنیه ٔ عقاب (در حال نصب و جر، و در تداول فارسی رعایت این قاعده نشود). عقابان . <BR><font color=\"Blue\">◄</font> دو چوب است که پوست را میان آن کشند. (از لسان العرب ). دو چوب بلند که مجرمان را بدان بندند. (غیاث اللغات ). دو چوب بلندی که وزیر نوشیروان برپا کرده حمزه را در پوست گاو کشیده بر بالای آن بسته بود. (آنندراج ). آلتی بوده است که مجرم را بر آن می بستند تازیانه می زدند و چون بر بالای آن صورت دو عقاب می کردند آن را عقابین می خواندند. (یادداشت مرحوم دهخدا به نقل از ادیب پیشاوری ). عمل به چارچوب کشیدن گناهکار و تازیانه زدن بر پشت او. (یادداشت مرحوم دهخدا). دو چوب که مقصر را بر آنها بدار می کشیدند، یا بر آنها بسته چوب می زدند، و ظاهراً سر آن دو چوب بشکل عقاب بوده است . (فرهنگ فارسی معین ). العِرفاص ؛ تازیانه ٔ عقابین . (السامی فی الاسامی ) (مهذب الاسماء) <span class=\"hlight\">:</span> چنانکه بفرمود تا عقابین و تازیانه و جلاد آوردند و خواسته بود تا بزنند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٦٧</span>). مستخرج و عقابین و تازیانه و شکنجها آورده و جلاد آمده .(تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٦٨</span>). آخر آن بود که بوالمظفر را هزار تازیانه به عقابین بزدند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٤٩</span>).<br>زین به نبود مذهبی که گیری <br>از بیم عقابین و تازیانه .<br> <font color=\"Red\">ناصرخسرو.</font><br>عقابین پولاد در چنگ او<br>عقابان سیه جامه ز آهنگ او.<br><font color=\"Red\">نظامی .</font><br>یکی هفته در آن کوه و بیابان <br>نرستنداز عقابینش عقابان .<br> <font color=\"Red\">نظامی .</font><br>در آشیانه ٔ خود بر سر عقابین است <br>ز نیم بیضه که دارد بروی خان نرگس .<br> <font color=\"Red\">کاتبی .</font><br>دفتر زهد ز اندیشه ٔ نم وانشود<br>حرف ناصح به عقابین نقاب است امروز.<br> <font color=\"Red\">اشرف (از آنندراج ).</font><br>- <span class=\"hlight\">حمزه در عقابین بودن </span> ؛ کنایه از بودن کسی در کلفت شدید. (از آنندراج ) <span class=\"hlight\">:</span> اما حمزه اینجا در عقابین است که ادای شکر التفات به چه زبان بیان توان نمود. (جلالای طباطبا از آنندراج ).<br>- <span class=\"hlight\">در عقابین کشیدن و بر عقابین کشیدن و به عقابین کشیدن </span> ؛مقصر را به چوب عقابین کشیدن . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> با عبداﷲ برو و هر دو را بگوی تا بر عقابین کشند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٦٣</span>). رو به عبداﷲ پارسی کردو گفت بر عقابین نکشیدند ایشان را؟ (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٦٣</span>). می فرمایم تا به عقابینش کشند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٦٨</span>).<br>کشیده در عقابین سیاهی <br>پر و منقار مرغ صبحگاهی .<br> <font color=\"Red\">نظامی .</font><br>زلفت چو عقاب در عقب بود<br>بربود و کشیدش در عقابین .<br> <font color=\"Red\">عطار.</font><br>و او <font color=\"DarkGreen\"><b>[ احمد حنبل ]</font></b> پیر و ضعیف بود بر عقابین کشیدند و هزار تازیانه بزدند. (تذکرةالاولیاء عطار). یکی را به عقابین کشیده و گفتند اگریک ذره تقصیر کنی خصمت بت بزرگ باد. (تذکرة الاولیاء).<br>- <span class=\"hlight\">عقابین کَنان </span> ؛ عقابین کَنی . رسم و جشنی در قهوه خانه چون سخنور به قسمت عقابین کنی رسد. (یادداشت مرحوم دهخدا).<br></font></div>'),
(184720, 'عقابین', '<span class=\"hlight\">عقابین .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِ) خارهای آهنین . (غیاث اللغات ) (آنندراج ).<br></font></div>'),
(184721, 'عقاد', '<span class=\"hlight\">عقاد.</span> <font color=\"DarkGreen\"><b>[ ع َق قا ]</font></b> (ع ص ) مبالغه است عاقد را. رجوع به عاقد شود. <BR><font color=\"Blue\">◄</font> سازنده و فروشنده ٔ نخها و تکمه ها. (از اقرب الموارد). علاقه بند.<br></font></div>'),
(184722, 'عقاد', '<span class=\"hlight\">عقاد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) نخی است که در آن مهره هایی باشد و به گردن کودک آویخته گردد. (از اقرب الموارد).<br></font></div>'),
(184723, 'عقار', '<span class=\"hlight\">عقار.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) برگزیده ٔ رخت و اسباب که جز در عید و نحو آن استعمال نکنند. (از منتهی الارب ) (از اقرب الموارد). عَقار. و رجوع به عَقار شود. <BR><font color=\"Blue\">◄</font> نوعی از جامه ٔ رنگین . (منتهی الارب ). نوعی از لباسها که سرخ رنگ است . (از اقرب الموارد). نوعی از جامه های سرخ . (دهار). <BR><font color=\"Blue\">◄</font> برگزیده ٔ مال و علف و گیاه . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> می، بدان جهت که پیوسته در خنور باشد، یا بدان جهت که بازدارد نوشنده را از رفتار. (منتهی الارب ). خمر، به جهت ملازمت آن «دن » را. (از اقرب الموارد). می . (دهار). خمر. (تحفه ٔ حکیم مؤمن ) (اختیارات بدیعی ) (مخزن الادویه ). شراب و خمر. (الفاظ الادویة). باده . راح . قهوه . قرقف . مدام . مل . نبیذ <span class=\"hlight\">:</span> <br>خجسته بادش نوروز وهمچنان همه روز<br>به شادکامی بر کف گرفته همی به جام عقار.<br> <font color=\"Red\">فرخی .</font><br>به غزو کوشد و شاهان همی بجستن کام <br>به جنگ یازد و شاهان همی به جام عقار.<br> <font color=\"Red\">فرخی .</font><br>مرغ در باغ چو معشوقه ٔ سرکش گشته ست <br>که ملک را سر آن شد که زند جام عقار.<br> <font color=\"Red\">منوچهری .</font><br>چرخ است ولیکن نه درو طالع نحس است <br>خلد است ولیکن نه درو جوی عقار است .<br> <font color=\"Red\">منوچهری .</font><br>سرو از عقیق باشد، کوه از عقار باشد<br>این مستعیر باشد، آن مستعار باشد.<br> <font color=\"Red\">منوچهری .</font><br>دشت گلگون شد گوئی که پرندستی <br>آب میگون شد گوئی که عقارستی .<br> <font color=\"Red\">ناصرخسرو.</font><br>سوی گلبن زرد استام زرد<br>سوی لاله ٔ سرخ جام عقار.<br> <font color=\"Red\">ناصرخسرو.</font><br>عقار خواه خوش و لعل جام با ممزوج <br>که سست گردد طبع عقار از آتش و آب .<br> <font color=\"Red\">مسعودسعد.</font><br>پنداشتند که این مقدار از فعل عقار باشد. (جهانگشای جوینی ).<br>رزق ما از کاس زرین شد عقار<br>وان سگان را آب تتماج از تغار.<br> <font color=\"Red\">مولوی .</font><br>با خودآمد او ز مستی عقار<br>زان گنه گشته سرش خانه ٔ خمار.<br> <font color=\"Red\">مولوی .</font><br>گفت ای رندان چه حال است این چکار<br>هیچ خمی در نمی بینم عقار.<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(184724, 'عقار', '<span class=\"hlight\">عقار.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) نازاینده شدن زن . (از منتهی الارب ) (از اقرب الموارد). عَقر. عُقر. عَقارة. عُقارة.<br></font></div>'),
(184725, 'عقار', '<span class=\"hlight\">عقار.</span> <font color=\"DarkGreen\"><b>[ ع ُق ْ قا ]</font></b> (ع ص ) کلأ عقار؛ گیاه که خسته و مجروح کند ستور را. <BR><font color=\"Blue\">◄</font> (اِ)گیاهی است تر. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184726, 'عقار', '<span class=\"hlight\">عقار.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) (یوم الَ ...) نام جنگی است که با بنی تمیم کرده اند، و در آن سوار آنان شهاب بن عبدقیس به دست سیاربن عبید حنفی به قتل رسید. (از معجم البلدان ).<br></font></div>'),
(184727, 'عقار', '<span class=\"hlight\">عقار.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) (غب الَ ...) جایگاهی است بحری، نزدیک بلاد مهرة. (از معجم البلدان ).<br></font></div>'),
(184728, 'عقار', '<span class=\"hlight\">عقار.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِ) طائری است که از پر او جیغه و کلغی سازند و اکثر پرهای سیاه دارد و لیکن معلوم نیست که لغت کجاست . (آنندراج ) <span class=\"hlight\">:</span> <br>بسکه رو گردانی از من ای نگار گلعذار<br>پیش چشمم کاکلت زلف است مانند عقار.<br><font color=\"Red\">میرزاطاهر وحید (از آنندراج ).</font><br></font></div>'),
(184729, 'عقار', '<span class=\"hlight\">عقار.</span> <font color=\"DarkGreen\"><b>[ ع َق ْ قا ]</font></b> (اِخ ) نام مردی از همدان که گویند در جنگ سی اسب را کشته است . (از منتهی الارب ).<br></font></div>'),
(184730, 'عقار', '<span class=\"hlight\">عقار.</span> <font color=\"DarkGreen\"><b>[ ع َق ْ قا ]</font></b> (ع ص ) مبالغه است مصدر عَقر را. (از اقرب الموارد). رجوع به عَقر شود. <BR><font color=\"Blue\">◄</font> (اِ) گیاه که بدان تداوی نمایند و یا اصل داروها. (منتهی الارب ). دارو، و یا گیاه ویا ریشه های گیاه که بدان درمان کنند. و گویند عقاقیر اصل و ریشه ٔ داروها است . (از اقرب الموارد). ج، عَقاقیر. (منتهی الارب ) (اقرب الموارد). آمیزهاء دارو. (دهار). اسم مطلق دوا. (تحفه ٔ حکیم مؤمن ). و هو <font color=\"DarkGreen\"><b>[ ای خولنجان ]</font></b> فی الاصل اسم عقار هندی . (معجم البلدان ).<br>- <span class=\"hlight\">عقار ارصنیثا</span> ؛ اسم سریانی آذربو است . (فهرست مخزن الادویه ).<br>- <span class=\"hlight\">عقار اسوسالی </span> ؛ اسم سریانی ایرسا است . (تحفه ٔ حکیم مؤمن ).<br>- <span class=\"hlight\">عقار اعرطنیثا</span> ؛ اسم سریانی آذربو است . (تحفه ٔ حکیم مؤمن ).<br>- <span class=\"hlight\">عقار اعرون </span> ؛ اسم سریانی اشرس یا اشروس است . (از تحفه ٔ حکیم مؤمن ) (از فهرست مخزن الادویه ).<br>- <span class=\"hlight\">عقار سوصنیائی </span> ؛ اسم سریانی ایرسا است . (فهرست مخزن الادویه ).<br><BR><font color=\"Blue\">◄</font> درخت . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184731, 'عقار', '<span class=\"hlight\">عقار.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام چند جایگاه است از آن جمله : ریگستانی است قریب دهناء. (منتهی الارب ) (از معجم البلدان ). <BR><font color=\"Blue\">◄</font> زمینی است مر باهله را. (منتهی الارب ). جایگاهی است در دیار باهله در اطراف یمامة. (از معجم البلدان ). <BR><font color=\"Blue\">◄</font> ریگستانی است در قریتین . (از معجم البلدان ). <BR><font color=\"Blue\">◄</font> زمینی است مر بنی ضبة را. <BR><font color=\"Blue\">◄</font> قلعه ای است به یمن . (منتهی الارب ) (از معجم البلدان ).<br></font></div>'),
(184732, 'عقار', '<span class=\"hlight\">عقار.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(ع اِ) زمین و آب و مانند آن . (منتهی الارب ). زمین . (دهار) (از اقرب الموارد). آب و زمین و زراعت و اراضی و ملک و قریه و خزائن . (آنندراج ). زمین و آب و درخت . (مهذب الاسماء). زمین و درخت و کالا، از این رو شامل منقول نیز می باشد. (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> ضیعه و آبادی . (از اقرب الموارد). ضیاع . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> منزل . (منتهی الارب ) (اقرب الموارد). سرای . (دهار). <BR><font color=\"Blue\">◄</font> رخت و اسباب خانه . (منتهی الارب ). متاع البیت . (اقرب الموارد). متاع خانه . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> برگزیده ٔ رخت و اسباب که جز در عید و نحو آن استعمال نکنند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عُقار. رجوع به عُقار شود. <BR><font color=\"Blue\">◄</font> آنچه اصل و قرار باشد آن راچون زمین و خانه . (از تعریفات جرجانی ) (از اقرب الموارد). هر ملک ثابت و پابرجایی مانند خانه و خرمابن .(ناظم الاطباء). ج، عَقارات . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> در اصطلاح شرعی، زمین، خواه دارای بناء باشد وخواه نباشد. (از کشاف اصطلاحات الفنون ) <span class=\"hlight\">:</span> <br>این همی گوید گشتم به غلام و به ستور<br>و آن همی گوید گشتم به ضیاع و به عقار.<br> <font color=\"Red\">فرخی .</font><br>چون که به من بنگری ز کبر و سیاست <br>من چه کنم گر ترا ضیاع و عقار است .<br><font color=\"Red\">ناصرخسرو.</font><br>مر مرا گر پس دانش نشدستی دل <br>همچو تو اسب و غلامان و عقارستی .<br> <font color=\"Red\">ناصرخسرو.</font><br>ایا گردنت بسته بر در شاه <br>ضیاعی یا عقاری یا عقالی .<br> <font color=\"Red\">ناصرخسرو.</font><br>سازم از جود تو ضیاع و عقار<br>گیرم از مدح تو رفیق و قرین .<br> <font color=\"Red\">مسعودسعد.</font><br>از داده ٔ تو اکنون چندانکه بنده راست <br>کس رایسار و مال و ضیاع و عقار نیست .<br> <font color=\"Red\">مسعودسعد.</font><br>ضیاع و عقار فراوان بر آن وقف فرمود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٤١</span>). مستظهر به مال بسیار و عقار بیشمار. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٤٠</span>). در جملگی دیار خراسان از اشراف سادات به مکنت و یسار و کثرت عقار... درگذشته . (تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٥٠</span>).<br>از زر و زن وز عقارم صبر هست <br>این تکلف نیست بی تزویری است .<br> <font color=\"Red\">مولوی .</font><br><BR><font color=\"Blue\">◄</font> اسم است مصدر عقر را به معنی قطع کردن سر خرمابن تا خشک شود. (از اقرب الموارد). و رجوع به عَقر شود. <BR><font color=\"Blue\">◄</font> بهترین گیاه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> درخت خرما. (دهار) (منتهی الارب ). نخل . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> رنگ سرخ . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> هر چیز خشک . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> یبیس . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) کلأ عقار؛ گیاه که مواشی را خسته و مجروح گرداند. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184733, 'عقار آدم', '<span class=\"hlight\">عقار آدم .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ دَ ]</font></b> (ترکیب اضافی، اِ مرکب ) نباتی باشد دوائی سفید و به زردی مایل، گویند بیخ درخت انار صحرائی است . ضماد کردن آن کوفتگی و شکستگی را نافع است و تخم آن قوت باه دهد. (برهان ) (آنندراج ). مغاث . (الفاظ الادویة) (اختیارات بدیعی ).<br></font></div>'),
(184734, 'عقار کوهان', '<span class=\"hlight\">عقار کوهان .</span> <font color=\"DarkGreen\"><b>[ ع ُ رِ]</font></b> (ترکیب اضافی، اِ مرکب ) دوائی است، آن را به لفظ دیگر عاقرقرحا خوانند و به عربی عودالفرج گویند. عقرکوهان . (برهان ) (آنندراج ). عاقرقرحا. (الفاظ الادویة) (اختیارات بدیعی ) (تحفه ٔ حکیم مؤمن ). رأس کهن .<br></font></div>'),
(184735, 'عقارات', '<span class=\"hlight\">عقارات .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ)ج ِ عَقار. (از اقرب الموارد). رجوع به عَقار شود.<br></font></div>'),
(184736, 'عقارالملح', '<span class=\"hlight\">عقارالملح .</span> <font color=\"DarkGreen\"><b>[ ع َ رُل ْ م ِ ]</font></b> (اِخ ) از آبهای بنی قشیر است . (از معجم البلدان ). عقار، موضعی به دیار بنی قشیر. (منتهی الارب ).<br></font></div>'),
(184737, 'عقارب', '<span class=\"hlight\">عقارب .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (ع اِ) ج ِ عَقرب . (منتهی الارب ) (از اقرب الموارد). رجوع به عقرب شود <span class=\"hlight\">:</span> دبیب عقارب بلا و صریر جنادب هوا بیفتاد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٣٦</span>). به ضیافتخانه ٔ عقارب نواهس و حیات لواحس شتافت . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤٥٦</span>). <BR><font color=\"Blue\">◄</font> سخن چینیها. (منتهی الارب ). نمائم . (اقرب الموارد): اًنه لتدب ّ عقاربه ؛ او میدرد ناموس مردم را و سخن چینیها می نماید و اذیتها می رساند. و چنانکه گویند اقاربک عقاربک . <BR><font color=\"Blue\">◄</font> سختی ها. (منتهی الارب ). شدائد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> عقارب الشتاه ؛ سختی سرمای زمستان . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> منت، بر تشبیه، چنانکه گویند: لفلان علی ّ آیاد لیست بذات عقارب ؛ یعنی او را بر من نعمتهایی است گوارا و نیکو و بدون منت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بدی و خشونت، گویند: عیش ذوعقارب ؛ یعنی زندگی بد و سخت و خشن . (از اقرب الموارد).<br></font></div>'),
(184738, 'عقارب', '<span class=\"hlight\">عقارب .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ]</font></b> (اِخ ) قبیله ای است که در قسمت جنوب جزیرةالعرب نزدیک عدن، سکونت دارند. (فرهنگ فارسی معین ).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(184739, 'عقارت', '<span class=\"hlight\">عقارت .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع مص ) عقارة. نازاینده شدن . نازایی . عقر. رجوع به عقارة و عقر شود.<br></font></div>'),
(184740, 'عقاری', '<span class=\"hlight\">عقاری .</span> <font color=\"DarkGreen\"><b>[ ع َرا ]</font></b> (ع ص ) خیل عقاری ؛ اسبان پی زده . (منتهی الارب ).<br></font></div>'),
(184741, 'عقاص', '<span class=\"hlight\">عقاص .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) بیماریی است گوسپندان را. (منتهی الارب ).<br></font></div>'),
(184742, 'عقاص', '<span class=\"hlight\">عقاص .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) رشته که بدان گیسو بندند. (منتهی الارب ). نخی که بوسیله ٔ آن اطراف ذؤابه را بندند. ج، عُقُص . (از اقرب الموارد). موی بند. (ملخص اللغات حسن خطیب کرمانی ). جل گیس . گیسوبند. گیس باف . <BR><font color=\"Blue\">◄</font> «دوارة» و شکنبه که در شکم گوسپند است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ج ِ عَقیصة. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ج ِ عَقصة. (اقرب الموارد).<br></font></div>'),
(184743, 'عقاف', '<span class=\"hlight\">عقاف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) علتی است در قوائم و پاهای گوسپند، که بدان پایش خمیده گردد. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184744, 'عقافة', '<span class=\"hlight\">عقافة.</span> <font color=\"DarkGreen\"><b>[ ع ُق ْ قا ف َ ]</font></b> (ع اِ)چوبی است سرکج که بدان چیزی را می کشند. چوگان . (منتهی الارب ). چوبی است که در سر آن خمیدگی باشد و اشیاء را بدان پیش می کشند چون چوگان . (از اقرب الموارد).<br></font></div>'),
(184745, 'عقاق', '<span class=\"hlight\">عقاق .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ]</font></b> (ع اِ) اسم است عقوق را. نافرمانی و آزار پدر ومادر. آزار پدر و مادر. (از منتهی الارب ). اسم است «عقوق » را از والدین، و آن مبنی بر کسر باشد. (از اقرب الموارد). و رجوع به عقوق شود. <BR><font color=\"Blue\">◄</font> بار شکم ناقه . (منتهی الارب ). حمل . (اقرب الموارد). عِقاق .<br></font></div>'),
(184746, 'عقاق', '<span class=\"hlight\">عقاق .</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ]</font></b> (ع مص ) باردار گردیدن شتر ماده . (از منتهی الارب ). باردار گردیدن مادیان، یا باردار نشدن او، از اضداد است . (از اقرب الموارد). عَقَق .<br></font></div>'),
(184747, 'عقاق', '<span class=\"hlight\">عقاق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) بار شکم ناقه . (منتهی الارب ). حمل . (اقرب الموارد). عَقاق . و رجوع به عَقاق شود. <BR><font color=\"Blue\">◄</font> ج ِ عُقُق که آن نیز جمع عَقوق است . (منتهی الارب ) (از اقرب الموارد). رجوع به عقوق و عقق شود.<br></font></div>'),
(184748, 'عقاق', '<span class=\"hlight\">عقاق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) ماء عقاق ؛ آب تلخ و شور. (منتهی الارب ). آب تلخ . (از اقرب الموارد).<br></font></div>'),
(184749, 'عقاقل', '<span class=\"hlight\">عقاقل .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ]</font></b> (ع اِ) ج ِ عَقَنقَل . (منتهی الارب ) (اقرب الموارد). رجوع به عقنقل شود.<br></font></div>'),
(184750, 'عقاقیر', '<span class=\"hlight\">عقاقیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عَقّار. (منتهی الارب ) (از اقرب الموارد). اسم جنس ادویه است . (تحفه ٔ حکیم مؤمن ) (مخزن الادویه ). هر گیاه که بدان تداوی کنند. مفردات طب . (یادداشت مرحوم دهخدا). ادویه که از قسم بیخ نباتات است . (غیاث اللغات ) (آنندراج ). دواهای نباتی . گیاهان داروئی . (فرهنگ فارسی معین ). رجوع به عَقّار شود <span class=\"hlight\">:</span> آن طبیبان را داروها و عقاقیرهاست که از هندوستان و از هر جا آرند. (تاریخ بیهقی ).<br>گهی الوان احوال عقاقیر<br>که چه گرم است از آن چه خشک و چه تر.<br> <font color=\"Red\">ناصرخسرو.</font><br>هر عقاقیر که داروکده ٔ بابل راست <br>حاضرآرید و بها بدره ٔ زر باز دهید.<br> <font color=\"Red\">خاقانی .</font><br>نه پیش من دواوین است و دفتر<br>نه عیسی را عقاقیر است و هاون .<br><font color=\"Red\">خاقانی .</font><br>ازین و آن دوا مطلب چون مسیح هست <br>زیرا اجل گیاست عقاقیر این و آن .<br> <font color=\"Red\">خاقانی .</font><br>از این دو عقاقیر صحرای دلها<br>در این هفت دکان گیائی نیابی .<br> <font color=\"Red\">خاقانی .</font><br>هر چه بدان ماند از ظروف و اوانی و...عقاقیر و اخلاط و توابل که هر چیز از آن از عالمی به عالمی می برند. (ترجمه ٔ محاسن اصفهان، در وصف بازار اصفهان ). بر آن کوه عقاقیر بسیار است از اطراف اهل فارس بدان کوه آینده و عقاقیر چینند و جمع کنند. (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">٨٧</span>). آنچه اجناس که متعلق به شربتخانه است که تحویل او شود، ظروف طلا و نقره و... شکر و قند و عقاقیر و قهوه و... (تذکرة الملوک چ دبیرسیاقی ص <span class=\"hlight\" dir=\"rtl\">٣٣</span>). <BR><font color=\"Blue\">◄</font> حدید جدید العقاقیر؛ آهن اصل و نیکو. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ج ِ عِقّیر. (ناظم الاطباء). رجوع به عقّیر شود.<br></font></div>'),
(184751, 'عقاقیری', '<span class=\"hlight\">عقاقیری .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب به عقاقیر. رجوع به عقاقیر شود. <BR><font color=\"Blue\">◄</font> عقاقیرفروش . صیدلانی . دوافروش . عطار. پیله ور. پیلور. (یادداشت مرحوم دهخدا).<br></font></div>'),
(184752, 'عقال', '<span class=\"hlight\">عقال .</span> <font color=\"DarkGreen\"><b>[ ع َق ْ قا ]</font></b> (اِخ ) ابن شیة، مکنی به ابوشیطم . محدث است . (از منتهی الارب ).<br></font></div>'),
(184753, 'عقال', '<span class=\"hlight\">عقال .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) شتر ماده ٔ نوجوان . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زکات یک سال از شتران و گوسپندان . (از منتهی الارب ) (از اقرب الموارد): أدیت ُ عقال السنة؛ صدقه ٔ سال را پرداختم و «مصدق » هرگاه عین شتر را بگیرد گویند «أخذ عقالا» و اگر بهای آنها را بستاند، گویند «أخذ نقداً». (از اقرب الموارد). و رجوع به عقالان شود. <BR><font color=\"Blue\">◄</font> رسن که بدان ساق و وظیف شتر را بهم بندند. (منتهی الارب ). ریسمانی که شتر را از میان «ذراع » وی بدان بندند. (از اقرب الموارد). زانوبند شتر. (دهار). رسنی که بدان ساق شتر بندند و یا پای دیگر ستوران بندند. (غیاث اللغات ) (از آنندراج ). ج، عُقُل . (منتهی الارب ) (از اقرب الموارد) <span class=\"hlight\">:</span> <br>ایا گردنت بسته بر در شاه <br>ضیاعی یا عقاری یا عقالی .<br> <font color=\"Red\">ناصرخسرو.</font><br>تاجم سر پرمغز را ولیکن <br>مر پای تهی مغز را عقالم .<br> <font color=\"Red\">ناصرخسرو.</font><br>ای کرده ترا بسته ٔ مطواع فلان میر<br>آن پنج کسش ساز و دو سه اسب عقالش .<br> <font color=\"Red\">ناصرخسرو.</font><br>عقل تا با خود منی دارد عقالش دان نه عقل <br>چون منی زو دور گشت آنگه دوا خوانش نه دا.<br> <font color=\"Red\">خاقانی .</font><br>دریا ز شرم جودش بگریختی چو زیبق <br>اما چهار میخ است اینک زمین عقالش .<br> <font color=\"Red\">خاقانی .</font><br>سلطان شیطان غیرت را به عقال شریعت ببست . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٧٦</span>). بر حسب خبث فعال هر یک عقال نکال آن کشیدند. (جهانگشای جوینی ). اکنون که عقل که عقال جنون جوانان است روی نمود. (جهانگشای جوینی ).<br>تا رهی از فکر و وسواس و حیل <br>بی عقال عقل در رقص الجمل .<br> <font color=\"Red\">مولوی .</font><br>پس بکوشی و به آخر از کلال <br>خودبخود گوئی که العقل عقال .<br> <font color=\"Red\">مولوی .</font><br>امر تو مرکبان زمین را کند روان <br>نهی تو بختیان فلک را نهد عقال .<br> <font color=\"Red\">خواجه جمال الدین سلمان (از آنندراج ).</font><br>تعقیل ؛ عقال بسیار بر پای شتر بستن . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> رشته ای که تازیان دور سر بندند. (فرهنگ فارسی معین ). ریسمان مانندی که مرد بدور سر خود بندد، و آن مأخوذ از معنی زانوبند شتر است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عقال المئین ؛ مرد شریف که هرگاه اسیر و بندی شود فدیه ٔ او چند شتر باشد. (منتهی الارب ). نزد عرب بر شریفی اطلاق میشد که هنگام اسارت به صدها شتر فدیه داده شود. ج، عُقل . عُقُل . (از اقرب الموارد).<br></font></div>'),
(184754, 'عقال', '<span class=\"hlight\">عقال .</span> <font color=\"DarkGreen\"><b>[ ع ُق قا ]</font></b> (ع ص، اِ) ج ِ عاقِل .(منتهی الارب ) (اقرب الموارد). خردمندان <span class=\"hlight\">:</span> <br>دل ای حکیم بر این معبر هلاک مبند<br>که اعتمادنکردند بر جهان عقال .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(184755, 'عقال', '<span class=\"hlight\">عقال .</span> <font color=\"DarkGreen\"><b>[ ع ُق ْ قا ]</font></b> (اِخ ) نام اسب حوطبن ابی جابر است، و آن را «ذوعقال » نیز نوشته اند. (از منتهی الارب ).<br></font></div>'),
(184756, 'عقام', '<span class=\"hlight\">عقام .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) مرد که فرزند نشود او را. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زن نازاینده . ج، عُقماء. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> حرب عقام ؛جنگ سخت . <BR><font color=\"Blue\">◄</font> رجل عقام ؛ مرد زشتخو. <BR><font color=\"Blue\">◄</font> داء عقام ؛ بیماری دشوار که به نشود، و به ضم افصح است . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناقه ٔ عقام ؛ ناقه ٔ دندان نیش برآورده ٔ استواراندام . (منتهی الارب ). ناقة «بازل » و استوار و سخت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) ماهیی است . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ماری است که در بحر می ماند، و گویند «أسود» از خشکی می آید و بر ساحل دریا سوت میکشد و عقام از دریا به سوی او می آید و درهم می پیچند آنگاه از هم جدا شده هر یک به مأوای خود میرود. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184757, 'عقام', '<span class=\"hlight\">عقام .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص، اِ) ج ِ عَقیم . (منتهی الارب ) (اقرب الموارد). رجوع به عقیم شود.<br></font></div>'),
(184758, 'عقام', '<span class=\"hlight\">عقام .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) داء عقام ؛بیماری که به نشود. (منتهی الارب ) (از اقرب الموارد).علت بی دارو. (زمخشری ). عَقام . و رجوع به عَقام شود. <BR><font color=\"Blue\">◄</font> یوم عقام ؛ روز سخت . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> رجل عقام ؛ مرد بدخوی . <BR><font color=\"Blue\">◄</font> جنگ شدید. (منتهی الارب ). جنگ سخت که در آن کسی را بر دیگری ترجیح نباشد. (از اقرب الموارد).<br></font></div>'),
(184759, 'عقامة', '<span class=\"hlight\">عقامة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (اِخ ) از اعلام است . (از منتهی الارب ).<br></font></div>'),
(184760, 'عقان', '<span class=\"hlight\">عقان .</span> <font color=\"DarkGreen\"><b>[ ع ِق ْ قا ]</font></b> (ع اِ) عقان النخیل ؛ آنچه از بن خرمابن برزند و برآید. عقان الکرم نیز چنین است . (از منتهی الارب ).<br></font></div>'),
(184761, 'عقب', '<span class=\"hlight\">عقب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) روش و تک ستور که بعد از تک نخستین آرد. (منتهی الارب ). «جری » و دویدن که پس از دویدن اول آید. ج، عِقاب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پسر. (منتهی الارب ). ولد. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> پسر پسر. (منتهی الارب ). ولد ولد.(اقرب الموارد). <BR><font color=\"Blue\">◄</font> پاشنه، در لغت تمیم . (منتهی الارب ). مؤخر قدم . عَقِب . ج، أعقاب . <BR><font color=\"Blue\">◄</font> هر چه پس از چیز دیگری آید. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> جهت، چنانکه به کسی که می آید گویند «من أین عقبک » یعنی از کجا آمده ای . (از منتهی الارب ). ورجوع به عَقِب شود. <BR><font color=\"Blue\">◄</font> جاء فی عقبه ؛ بر اثر او آمد. (از اقرب الموارد). رجوع به عَقِب شود.<br></font></div>'),
(184762, 'عقب', '<span class=\"hlight\">عقب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) پی پیچیدن بر کمان . (از منتهی الارب ). «عَقَب » و پی پیچیدن بر کمان و تیر و نیزه، وآنها را در این صورت «معقوب » گویند. (از اقرب الموارد). پی بر جای پیچیدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> بر پاشنه ٔ کسی زدن . (از منتهی الارب ) (از اقرب الموارد). بر پاشنه زدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> خلیفه ٔ کسی شدن . (از منتهی الارب ). جانشین کسی شدن و پس از او آمدن . (از اقرب الموارد). از پی درآمدن . (المصادر زوزنی ) (تاج المصادر بیهقی ). عُقوب . عاقبة. و رجوع به عقوب و عاقبة شود. <BR><font color=\"Blue\">◄</font> نکاح کردن بعد مردن، یا طلاق کسی . <BR><font color=\"Blue\">◄</font> برگ سبز برآوردن بعد برگ خشک . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> عقب زیدا فی أهله ؛ زید را ستمکار دید و جانشین او شدبر خانواده اش . (از اقرب الموارد) (از منتهی الارب ).<br></font></div>'),
(184763, 'عقب', '<span class=\"hlight\">عقب .</span> <font color=\"DarkGreen\"><b>[ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ق ُ ]</font></b> (ع اِ) پایان کار. (منتهی الارب ). عاقبت . (اقرب الموارد). سرانجام . (دهار) (ترجمان القرآن جرجانی ). و از آن جمله است <span class=\"hlight\">:</span> آیه ٔ کریمه ٔ هوخیر ثوابا و خیر عقبا. (قرآن <span class=\"hlight\" dir=\"rtl\">٤٢/١٨</span>).که عاصم و حمزه آن را به سکون قاف و سایر قراء به ضم آن خوانده اند. (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> جئت فی عقب الشهر؛ پس از تمام شدن ماه آمدم . (از منتهی الارب ) (از اقرب الموارد). عُقبان . رجوع به عقبان شود.<br></font></div>'),
(184764, 'عقب', '<span class=\"hlight\">عقب .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ]</font></b> (اِخ ) بطنی است از کنانة. (از اللباب فی تهذیب الانساب ). رجوع به عَقِبی شود.<br></font></div>'),
(184765, 'عقب', '<span class=\"hlight\">عقب .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ]</font></b> (ع اِ) پسر. (منتهی الارب ). ولد. (اقرب الموارد). فرزند. (غیاث اللغات ) <span class=\"hlight\">:</span> از محمدبن علی ابوحمزه و او را عقب نبوده است و ابوالقاسم و او را ایضاً عقب نبوده است ... در وجود آمدند و مجموع وفات یافتند و ایشان را عقب نبود. (تاریخ قم <span class=\"hlight\" dir=\"rtl\">٢٣٤</span>). <BR><font color=\"Blue\">◄</font> پسر پسر. (منتهی الارب ). ولد ولد. (اقرب الموارد). فرزند فرزند. (دهار). نواسه . (مهذب الاسماء) (دستور اللغة). فرزندزاده . (غیاث اللغات ). وجعلها کلمة باقیة فی عقبه لعلهم یرجعون . (قرآن <span class=\"hlight\" dir=\"rtl\">٢٧/٤٣</span>)؛ و آن را کلمه ای جاویدان قرارداد در عقبش، باشد که آنان بازگشت کنند. <BR><font color=\"Blue\">◄</font> پاشنه، و آن مؤنث است . (از منتهی الارب ) (دهار). مؤخر قدم . (از اقرب الموارد). پاشنه . (مهذب الاسماء) (ترجمان القرآن جرجانی ). ج، أعقاب . (منتهی الارب ) (اقرب الموارد) <span class=\"hlight\">:</span> <br>سفرجل به است و عقب پاشنه .<br> <font color=\"Red\">ابونصر فراهی (نصاب ).</font><br>- <span class=\"hlight\">استخوان عقب، یا عظم عقب </span> ؛ یکی از هفت استخوان رسغ است و بزرگتر از جمیع آن استخوانها، و آن دارای شش سطح است : تحتانی، فوقانی، وحشی، انسی، قدامی و خلفی . (از جواهر التشریح میرزاعلی ). رجوع به بحر الجواهر شود.<br> <BR><font color=\"Blue\">◄</font> عقب الشیطان ؛ نوعی از نشستن که به نشست سگ ماند. (ناظم الاطباء). عقب الشیطان فی الصلاة؛ آن است که نمازگزار بین دو سجده، دو سرین خود را بر پاشنه های خویش قرار دهد، و آن همان است که برخی از مردم آن را «اًقعاء» گویند. (از اقرب الموارد). و رجوع به اقعاء و عَقَبة شود. <BR><font color=\"Blue\">◄</font> جاء فی عقب الشهر؛ یعنی آمد در اندک باقی مانده ٔ ماه . (منتهی الارب ). سافر فی عقب الشهر؛ یعنی در آخر ماه مسافرت کرد، یا در هنگامی که اندکی از ماه مانده بود. <BR><font color=\"Blue\">◄</font> جهت، گویند: من أیْن کان عقبک ؛ یعنی از کجا آمده ای، و آن را برای شخصی که می آید گویند. (از اقرب الموارد). و رجوع به عَقب شود. <BR><font color=\"Blue\">◄</font> سپس چیزی . (دهار): فلان یسقی عقب بنی فلان ؛ او پس از آنها چارپایان خود را آب میدهد. <BR><font color=\"Blue\">◄</font> خلف فلان بعقبی ؛ او پس از من اقامت کرد. <BR><font color=\"Blue\">◄</font> جاءفی عقبه ؛ بر اثر او آمد. و اصل جمله چنین بوده است :جاء زید یطاء عقب عمرو؛ یعنی عمرو هر قدمی که بر میداشت زید قدم خود را بر جای آن میگذاشت، و برای تخفیف آن را بصورت «جاء عقبه » نیز گفته اند و به سکون قاف نیز خوانده شده است . <BR><font color=\"Blue\">◄</font> رجع فلان علی عقبه ؛ یعنی او بر راهی که در عقب و پشت سر او بود به سرعت بازگشت . <BR><font color=\"Blue\">◄</font> هو فی عقب المرض ؛ او از بیماری شفا یافت در حالی که اندکی از اثر بیماری در او مانده است . <BR><font color=\"Blue\">◄</font> فلان موطاء العقب ؛ او بسیار اتباع است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (از ع، ق، اِ) پس چیزی . دنبال پشت سر. مقابل پیش، امام، روبرو، جلو، مقابل . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>کز عقبش ذکر خیرزنده کند نام را.<br> <font color=\"Red\">سعدی (گلستان ).</font><br>- <span class=\"hlight\">از عقب </span> ؛ از پی . در پی . بر پی . از دنبال <span class=\"hlight\">:</span> هر که را رنجی به دل رسانیدی اگر از عقب آن صد راحت رسانی از پاداش آن یک رنج ایمن مباش . (گلستان سعدی ).<br>آفتاب اینهمه شمع از پی و مشعل در پیش <br>دست بر سینه زنندش که به پروانه درآی .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">از عقب دشمن گریخته نباید رفت </span> . (جامع التمثیل ).<br>- <span class=\"hlight\">بر عقب </span> ؛ در پی . پس از <span class=\"hlight\">:</span> بر عقب این فتح طغان خان را عمر به آخر رسید. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٩٥</span>).<br>- <span class=\"hlight\">به عقب </span> ؛ به پس . به دنبال . از پی . در پی . (ناظم الاطباء).<br>- <span class=\"hlight\">در عقب </span> ؛ در پس . در پی . بدنبال . از پی . (ناظم الاطباء) <span class=\"hlight\">:</span> همچنان در باب مرکبان خاصه که بداشته بودند در عقب این . (تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٧٧</span>).<br>رنج ز فریاد بری ساحت است <br>در عقب رنج بسی راحت است .<br> <font color=\"Red\">نظامی .</font><br>آن اًنا را لعنةاﷲ در عقب <br>این انا را رحمةاﷲ ای محب .<br> <font color=\"Red\">مولوی .</font><br>رمز ننسخ آیه أو ننسها<br>نأت خیرا در عقب میدان مها.<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">عقب چیزی رفتن </span> ؛ بدنبال آن رفتن .<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عقب یک شپش تا مورچه خورت میرود</span> ؛ سخت خسیس است و به مال خود دلبستگی دارد. (فرهنگ عوام ).<br>- <span class=\"hlight\">عقب عقبکی </span> ؛ گام برداشتن به طرف پشت سر بدون نگاه کردن به سمت عقب . (فرهنگ لغات عامیانه ).<br>- <span class=\"hlight\">عقب کسی فرستادن </span> ؛ پی او فرستادن . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">عقب کسی کردن </span> ؛ و عقب سر کسی کردن ؛ برای گرفتن کسی به دنبال او دویدن . (فرهنگ لغات عامیانه ): مگر عقب سرت کرده اند!<br>- <span class=\"hlight\">عقب گذاشتن کسی را</span> ؛ از کسی یا کسانی در مسابقه یا در کار یا زندگی پیش افتادن . (فرهنگ لغات عامیانه ).<br><BR><font color=\"Blue\">◄</font> دبر. پس .<br></font></div>'),
(184766, 'عقب', '<span class=\"hlight\">عقب .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع اِ) ج ِ عَقَبة. (منتهی الارب ) (از اقرب الموارد). رجوع به عقبة شود. <BR><font color=\"Blue\">◄</font> پی که از آن چله ٔ کمان سازند. (غیاث اللغات ) (آنندراج ). پی سفید و پی کمان . (السامی ) (مهذب الاسماء). پی سپید. (حبیش ). عصب و پی که از آن «وتر» و زه کمان سازند و آن پی های سپیدرنگ مفاصل است و گاهی گوشوار را نیز بدان بندند تا از جای خود منحرف نشود. ج، أعقاب . (از اقرب الموارد) (مهذب الاسماء).<br></font></div>'),
(184767, 'عقب افتادن', '<span class=\"hlight\">عقب افتادن .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ اُ دَ ]</font></b> (مص مرکب ) پس ماندن : عقب افتادن از قافله . <BR><font color=\"Blue\">◄</font> تأخیر کردن درادای چیزی : عقب افتادن مواجب . عقب افتادن مالیات .<br></font></div>'),
(184768, 'عقب افتاده', '<span class=\"hlight\">عقب افتاده .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ اُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) آنکه در کارها از دیگران عقب مانده باشد. دنبال افتاده . (فرهنگ فارسی معین ).<br></font></div>'),
(184769, 'عقب انداختن', '<span class=\"hlight\">عقب انداختن .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ اَ ت َ ]</font></b> (مص مرکب ) تعویق انداختن . تعلل کردن . دفعالوقت کردن . سر دواندن .<br></font></div>'),
(184770, 'عقب باز', '<span class=\"hlight\">عقب باز.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ]</font></b> (نف مرکب ) بیت ذیل به شاهد این ترکیب در آنندراج از نادم گیلانی آمده است بی شرح و معنائی <span class=\"hlight\">:</span> <br>ما عقب بازیم نزد ما عقب دارد حریف <br>خاطر ما جمع باشد از پریشان باختن .<br></font></div>'),
(184771, 'عقب رفتن', '<span class=\"hlight\">عقب رفتن .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ رَ ت َ ]</font></b> (مص مرکب ) پس رفتن . قدم باز پس نهادن . پس کشیدن . <BR><font color=\"Blue\">◄</font> مجازاً، تنزل کردن، مقابل جلو رفتن، ترقی کردن .<br></font></div>'),
(184772, 'عقب زدن', '<span class=\"hlight\">عقب زدن .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ زَ دَ ]</font></b> (مص مرکب ) به پس راندن : عقب زدن اتومبیل و درشکه و غیره . <BR><font color=\"Blue\">◄</font> در اصطلاح عامیانه، منصرف شدن از معامله و فسخ تصمیم کردن . توزدن . (فرهنگ لغات عامیانه ).<br></font></div>'),
(184773, 'عقب ماندن', '<span class=\"hlight\">عقب ماندن .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ دَ ]</font></b> (مص مرکب ) عقب افتادن . پس ماندن .<br></font></div>'),
(184774, 'عقب مانده', '<span class=\"hlight\">عقب مانده .</span> <font color=\"DarkGreen\"><b>[ع َ ق َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) عقب افتاده . پس افتاده .<br></font></div>'),
(184775, 'عقب ماندگی', '<span class=\"hlight\">عقب ماندگی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (حامص مرکب ) عقب افتادگی . پس ماندگی . دنبال افتادگی . (فرهنگ فارسی معین ). کندسیری و توقف در مسیر به کمال .<br></font></div>'),
(184776, 'عقب نشستن', '<span class=\"hlight\">عقب نشستن .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ن ِ ش َ ت َ]</font></b> (مص مرکب ) به پس رفتن . به قهقرا رفتن . بازگشتن .<br></font></div>'),
(184777, 'عقب نشینی', '<span class=\"hlight\">عقب نشینی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َن ِ ]</font></b> (حامص مرکب ) در اصطلاح نظامی، ترک مواضع خود کردن و به عقب رفتن . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> به قهقرا رفتن . عقب گرد کردن . (فرهنگ فارسی معین ).<br></font></div>'),
(184778, 'عقب کشیدن', '<span class=\"hlight\">عقب کشیدن .</span> <font color=\"DarkGreen\"><b>[ع َ ق َ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ ]</font></b> (مص مرکب ) عقب رفتن . پس رفتن . قدم باز پس نهادن . <BR><font color=\"Blue\">◄</font> عقب بردن . پس بردن .<br></font></div>'),
(184779, 'عقب گرد', '<span class=\"hlight\">عقب گرد.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ گ َ ]</font></b> (حامص مرکب ) در اصطلاح نظامی و ورزش، برگشت به عقب، و آن چنان است که شخص روی پنجه ٔ پای چپ نیم دایره ای به سمت چپ بچرخد سپس پای راست را به پای چپ بپیوندد. (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> بازگشت به قهقرا. <BR><font color=\"Blue\">◄</font> عقب افتادن . (فرهنگ فارسی معین ).<br></font></div>'),
(184780, 'عقبات', '<span class=\"hlight\">عقبات .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع اِ) ج ِ عَقَبة. (منتهی الارب ) (اقرب الموارد). راههای دشوار. (غیاث اللغات ) <span class=\"hlight\">:</span> <br>هیچ کسم نیز نبیند دگر<br>کز عقبات تن و جان کم شدم .<br><font color=\"Red\">عطار.</font><br></font></div>'),
(184781, 'عقبان', '<span class=\"hlight\">عقبان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) پایان کار. (منتهی الارب ). عاقبت و سرانجام . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آخر هر چیز: جاء فی عقبان الشهر؛ او وقتی آمد که همه ٔ ماه گذشته بود. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ج ِ عُقاب . (منتهی الارب ) (غیاث اللغات ) (آنندراج ). رجوع به عقاب شود.<br></font></div>'),
(184782, 'عقبانی', '<span class=\"hlight\">عقبانی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) (<span class=\"hlight\" dir=\"rtl\">٧٢٠</span>-<span class=\"hlight\" dir=\"rtl\">٨١١</span> هَ .ق .) سعیدبن محمد تجیبی تلمسانی عقبانی . قاضی و فقیه مالکی و از اهالی تلمسان بود و مدتی عهده دار قضاء در بجایه و مراکش بوده است . او راست : شرح جمل خونجی . العقیدة البرهانیة. شرح الحوفیة. (از الاعلام زرکلی ).<br></font></div>'),
(184783, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ب َ ]</font></b> (اِخ )نام چند ناحیه است، از آن جمله محله ای است در ماوراء نهر عیسی نزدیک دجله ٔ بغداد. (از معجم البلدان ).<br>- <span class=\"hlight\">عقبةالرکاب </span> ؛ عقبه ای است در نزدیکی نهاوند. و وجه تسمیه ٔ آن این است که سپاه اسلام چون آهنگ نهاوند کرد در این عقبه سواران آن ازدحام کردند. (از معجم البلدان ).<br>- <span class=\"hlight\">عقبةالسیر</span> ؛ عقبه ای است تنگ و طویل در ثغور در نزدیکی حدث . (از معجم البلدان ).<br>- <span class=\"hlight\">عقبة الطین </span> ؛ موضعی است در فارس . (از معجم البلدان ).<br></font></div>'),
(184784, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن ابان بن ذکوان بن امیةبن عبدشمس، مکنی به ابوالولید و مشهور به ابن ابی مُعَیط. از پیشروان قریش در جاهلیت . در آغاز ظهور اسلام، مسلمانان را آزار بسیار رساند و در غزوه ٔ بدر بدست مسلمین اسیر گشت و به دار آویخته شد. و وی نخستین تنی است در اسلام که به دار آویخته شده است . (از الاعلام زرکلی به نقل از الروض الانف و ابن الاثیر).<br></font></div>'),
(184785, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُب َ ]</font></b> (اِخ ) جدی است جاهلی و فرزندان او بطنی از هلال بن عامر از عدنانیه را تشکیل میدهند. و طائفه ای از آنان در اصفون و اسنا، در صعید مصر میزیستند. (از الاعلام زرکلی به نقل از نهایةالارب و البیان و الاعراب ).<br></font></div>'),
(184786, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع اِ) نوبت : تمّت عقبتک . <BR><font color=\"Blue\">◄</font> بدل : أخذت من اسیری عقبة. <BR><font color=\"Blue\">◄</font> شب وروز، بدان جهت که همدیگر را تعاقب می کنند. (از منتهی الارب ) (از اقرب الموارد). ج، عُقَب . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه از خوردنی در بن دیگ عاریتی به خداوند دیگ فرستند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> باقی مانده ٔ هر چیزی . (منتهی الارب ): فلان عقبة بنی فلان ؛ او آخرین بازمانده ٔ آنان است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نشان و اثر: علیه عقبةالجَمال . <BR><font color=\"Blue\">◄</font> عقبة الطائر؛ مسافت ما بین ارتفاع و انحطاط پرنده، و گویند آن دو فرسخ است . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عقبةالشیطان ؛ نوعی از نشست که به نشست سگ ماند. (منتهی الارب ). عَقِب الشیطان . رجوع به عَقِب شود. <BR><font color=\"Blue\">◄</font> آنچه از شیرینی، پس از طعام خورند. دسر. <BR><font color=\"Blue\">◄</font> عقبة الضبع؛ سختی و شدت ؛ لقیت منه عقبة الضبع و اِست الکلب ؛ از او سختی و شدت دیدم . (از اقرب الموارد).<br>- <span class=\"hlight\">ابوعقبة</span> ؛ کنیه ٔ خنزیر و خوک . (از اقرب الموارد).<br></font></div>'),
(184787, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ب َ ]</font></b> (ع اِ) جامه های نگارین هودج . (منتهی الارب ). عَقَبة. و رجوع به عقبة شود. <BR><font color=\"Blue\">◄</font> در ماه یک مرتبه کردن کاری را، گویند مایفعل ذلک اًلا عقبة؛ یعنی هر ماه یک بار آن کار را می کند. (از منتهی الارب ) (از اقرب الموارد). ج، عِقَب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> اثر: عقبة الجَمال ؛ اثر و نشان و هیئت زیبایی . (از اقرب الموارد) (از منتهی الارب ). عُقبة. و رجوع به عُقبة شود.<br></font></div>'),
(184788, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ب َ ]</font></b> (اِخ )خلیج باریکی است در شمال بحر احمر و جنوب شرقی شبه جزیره ٔ سینا، که در انتهای آن یعنی شمالی ترین نقطه ٔ آن بندر کوچک عقبه قرار دارد و آن امروز جزو کشور هاشمی اردن است . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> نام بندری کوچک در انتهای خلیج عقبه به شمال بحر احمر.<br></font></div>'),
(184789, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن ابی الصهباء باهلی . تابعی است . رجوع به ابوخریم شود.<br></font></div>'),
(184790, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ب َ ]</font></b> (اِخ ) پز منی . (منتهی الارب ). عقبه ای است بین منی و مکه و فاصله ٔ آن تا مکه در حدود دو میل است . در آنجا مسجدی است که از آن رمی جمره ٔ عقبه میشود. در سال یازدهم بعثت، پیغمبر اسلام (ص ) در این عقبه با شش تن از قبیله ٔ «اوس » برخورد نمود و آنان را به دین اسلام فراخواند. این شش تن عبارت بودند از: اسعدبن زرارة، قطبةبن عامربن حدیدة، معاذبن عفراء، جابربن عبداﷲبن رئاب، عوف بن عفراء و عقبةبن عامر.این بیعت مشهور به بیعةالعقبة الاولی است . و این شش تن به مدینه بازگشتند و به تبلیغ اسلام پرداختند و درسالهای بعد تعداد بیشتری از اوس و خزرج در این عقبةاسلام آوردند. تعداد بیعت کنندگان را در بیعت دوم هفتاد تن و برخی هفتاد و سه تن نوشته اند. بیعت عقبه نخستین بیعت در اسلام بود و از میان انصار آنکه لقب عَقَبی دارد، در این ناحیه با پیامبر اسلام (ص ) بیعت کرده است . و از آن جمله است «و لقد شهدت لیلة العقبة و ما احب بدراً بدلها» زیرا بیعه ٔ عقبه نخستین بیعت در اسلام بوده است . (از معجم البلدان ) (از منتهی الارب ).<br></font></div>'),
(184791, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ب َ ]</font></b> (ع اِ) واحد عَقَب . (از اقرب الموارد). پی که از آن زه سازند و ریسمان تابند. ج، عَقَب . (منتهی الارب ). و رجوع به عَقَب شود. <BR><font color=\"Blue\">◄</font> جای دشوار برآمدن بر کوه . (منتهی الارب ) (از اقرب الموارد). راه دشوار در کوه . (غیاث اللغات ). گریوه . (تفلیسی ). گریوه ؛ یعنی بلندی بلند وسخت . (ترجمان القرآن جرجانی ). یُقّوش (در تداول ترکی ). <BR><font color=\"Blue\">◄</font> پز و کتل . (منتهی الارب ). جای دشوار.(غیاث اللغات ). راهی که در قسمتهای بالای کوه باشد. (از اقرب الموارد). گردنه . (فرهنگ فارسی معین ). پژ. ج، عِقاب . (منتهی الارب ) (اقرب الموارد). و عَقبات . (اقرب الموارد) عقبه ِ <span class=\"hlight\">:</span> میان این شهر و تبت مقدار پنج روزه راه است اندر عقبه های سخت . (حدود العالم ). و نزدیک وی <font color=\"DarkGreen\"><b>[ ده سنگس ]</font></b> عقبه ای است که او را عقبه ٔ سنگس خوانند. (حدود العالم ). اگر مقام نتوانند کرد عقبه ٔ کلار را گذاره کنند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٦٣</span>).<br>عقبه ای  زین صعبتر درراه نیست <br>ای خنک آن کش حسد همراه نیست .<br> <font color=\"Red\">مولوی .</font><br>هر روش هر ره که آن محمود نیست <br>عقبه ای و مانعی و رهزنی است .<br> <font color=\"Red\">مولوی .</font><br>این تردد عقبه ٔ راه حق است <br>ای خنک آن را که پایش مطلق است .<br> <font color=\"Red\">مولوی .</font><br>گر کنی قطع عقبه را این جایگاه <br>راه روشن گرددت تا پیشگاه .<br> <font color=\"Red\">عطار.</font><br>کیست کو را عقبه ای در راه نیست .<br> <font color=\"Red\">عطار.</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">ستوررا به پای عقبه جو دهند سود ندارد</span> (امثال و حکم دهخدا).<br><BR><font color=\"Blue\">◄</font> کنایه از امر سخت و عظیم . (از غیاث اللغات ). امری سخت و دشوار. (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> فلا أقتحم العقبة، و ما أدراک ما العقبة. (قرآن <span class=\"hlight\" dir=\"rtl\">١٢/٩٠</span>). عقبة در قرآن کریم را منزلی از «صراط» دانسته اند و برخی گویند آن هفتاد منزل از «پل صراط» است . رجوع به تفسیر ابوالفتوح رازی ج <span class=\"hlight\" dir=\"rtl\">١٠</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٤</span> و تفسیر کشف الاسرار ج <span class=\"hlight\" dir=\"rtl\">١٠</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩٩</span> شود.<br></font></div>'),
(184792, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ]</font></b> (ع اِ) برگ سبز که پس برگ خشک برآید. <BR><font color=\"Blue\">◄</font> نوعی از جامه های نگارین هودج . (منتهی الارب ) عِقْبة. رجوع به عِقبة شود.<br></font></div>'),
(184793, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن ابی معیط. صحابی . رجوع به ابووهب (عقبةبن ...) شود.<br></font></div>'),
(184794, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن وهب بن عقبة. محدث . رجوع به ابونعیم (عقبةبن ...) شود.<br></font></div>'),
(184795, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن نافعبن عبدالقیس اموی قرشی فهری . از فاتحان و فرماندهان بزرگ در صدر اسلام وی در سال یکم پیش از هجرت متولد شد و او را با پیامبر اسلام (ص ) صحبتی نبود. او پسرخاله ٔ عمروبن عاص بود و از جانب وی به سال <span class=\"hlight\" dir=\"rtl\">٤٢</span> هَ . ق . والی افریقیة شد و او در راه خویش بسیار از شهرها و استانهای سودان را فتح کرد. و به سال <span class=\"hlight\" dir=\"rtl\">٥٠</span> هَ .ق . از جانب معاویه والی مستقل افریقیه شد. عقبة سپس تا وادی قیروان پیش رفت و در آنجا مسجدی بنا نهاد که تا امروز به نام جامع عقبة شهرت دارد. به سال <span class=\"hlight\" dir=\"rtl\">٥٥</span> هَ . ق . معاویه او را عزل کرد سپس به سال <span class=\"hlight\" dir=\"rtl\">٦٢</span> هَ . ق . یزید او را والی بر مغرب نمود و وی دیگر بار قصد قیروان کرد. و سرانجام به سال <span class=\"hlight\" dir=\"rtl\">٦٣</span> هَ . ق . فرنگی ها وی رادر تهودة، از سرزمینهای زاب غافلگیر کردند و به قتل رساندند و در آنجا دفن شد. (از الاعلام زرکلی به نقل از الاستقصاء و البیان المغرب و فتح العرب للمغرب ).<br></font></div>'),
(184796, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن مغیره ٔ شیبانی راوی حدیث . رجوع به ابوالعلاء (عقبةبن ...) شود.<br></font></div>'),
(184797, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن عیسی . یکی از امرای آل ایوب است و او در یکی از جنگها اسیر نصاری گشت و وی را به اسارت به بیت المقدس بردند و در بندملک نصاری ماری بن ایوب بماند تا به مرضی صعب دچار شد و او را از زندان بیرون کردند و پس از معالجه وی را رها کردند تا به مصر شد. (یادداشت مرحوم دهخدا).<br></font></div>'),
(184798, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن عمروبن ثعلبه ٔ انصاری بدری، مکنی به ابومسعود. صحابی و از قبیله ٔخزرج بود. وی در غزوه ٔ عقبه و احد و مابعد آنها شرکت داشت . عقبة در کوفه سکنی گزید و از یاران علی (ع ) بوده است و مدتی ولایت کوفه را بعهده داشت و به سال <span class=\"hlight\" dir=\"rtl\">٤٠</span> هَ . ق . در آنجا درگذشت . (از الاعلام زرکلی از کشف النقاب و الاصابة). رجوع به ابومسعود (عقبة...) شود.<br></font></div>'),
(184799, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن علقه ٔ بیرونی . محدث . رجوع به ابویوسف (عقبةبن ...) شود.<br></font></div>'),
(184800, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن علقمه ٔ بیرونی . محدث . رجوع به ابوعبدالرحمان (عقبةبن ...) شود.<br></font></div>'),
(184801, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن عبدالغافر ازدی عوذی، مکنی به ابونهار. وی به سال <span class=\"hlight\" dir=\"rtl\">٨٣</span> هَ . ق . در جماجم درگذشت . رجوع به تاج العروس ذیل ماده ٔ «ج م م » شود.<br></font></div>'),
(184802, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن عامربن عبس بن مالک جهنی مکنی به ابوخماد، امیر و از صحابه ٔ پیغمبر اسلام (ص ) بوده است . وی «ردیف » پیامبر (ص ) بود و در جنگ صفین با معاویه شرکت داشت و در فتح مصر همراه عمروبن عاص بود. به سال <span class=\"hlight\" dir=\"rtl\">٤٤</span>هَ . ق . معزول شد و به سال <span class=\"hlight\" dir=\"rtl\">٥٨</span>هَ . ق . در مصر درگذشت . مردی شجاع و فقیه و قاری و شاعر بود و از تیراندازان بشمار میرفت . عقبة از جمله گردآورندگان قرآن کریم است و «ابن یونس » گوید مصحف او تاکنون (تا زمان ابن یونس ) در مصر است و آن با مصحف عثمان اختلاف دارد و در انتهای آن جمله ٔ «کتبه عقبةبن عامربیده » نگاشته است . عقبة را <span class=\"hlight\" dir=\"rtl\">٥٥</span> حدیث است و در قاهره «مسجدعقبةبن عامر» در کنار قبر اوست . (از الاعلام زرکلی به نقل از دول الاسلام ذهبی و الاصابة و جمهرة الانساب ).<br></font></div>'),
(184803, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن ضمره ٔحمصی . محدث . رجوع به ابوالولید (عقبةابن ...) شود.<br></font></div>'),
(184804, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُب َ ]</font></b> (اِخ ) ابن سَکون بن أشرس . جدی است جاهلی از کندة از قحطانیة. و از جمله فرزندان او عیاض و ثعلبة بوده اند. (از الاعلام زرکلی از نهایةالارب و السبائک ).<br></font></div>'),
(184805, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن خالد سکونی، مشهور به مجدر. تابعی است . رجوع به ابومسعود (عقبةبن ...) شود.<br></font></div>'),
(184806, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن حرام، جدی است جاهلی از جذام از قحطانیة. فرزندان او در روزگار ابن خلدون (<span class=\"hlight\" dir=\"rtl\">٧٣٢</span> - <span class=\"hlight\" dir=\"rtl\">٨٠٨</span> هَ . ق .) در بلاد کرک میزیستند و حفاظت راه مابین مصر و مدینه ٔ منوره را تا حوالی غزة از بلاد شام، بعهده داشتند. (از الاعلام زرکلی از نهایةالارب و ابن خلدون ).<br></font></div>'),
(184807, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن حجاج سلولی . امیر و از اشراف بنی سلول بود. به سال <span class=\"hlight\" dir=\"rtl\">١١٦</span> یا <span class=\"hlight\" dir=\"rtl\">١١٧</span> هَ . ق . از جانب عبیداﷲبن حجاب امیر مصر در عهد هشام بن عبدالملک، به ولایت اندلس گماشته شد و او آن نواحی را تا اربونه  و جلیقیة و پنپلونة فتح کرد و بیش از هزار تن بر دست وی اسلام آوردند. و گویند به سال <span class=\"hlight\" dir=\"rtl\">١٢٣</span>هَ . ق . اهالی اندلس به تحریک عبدالملک بن قطن بر او شوریدند و وی را خلع کردند و اندکی بعد در قرطبه درگذشت . (از الاعلام زرکلی از نفح الطیب و ابن الاثیر و البیان المغرب ).<br></font></div>'),
(184808, 'عقبة', '<span class=\"hlight\">عقبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن حارث بن عامر. صحابی است . رجوع به ابوسروعة شود.<br></font></div>'),
(184809, 'عقبدار', '<span class=\"hlight\">عقبدار.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (نف مرکب ) عقب دارنده . <BR><font color=\"Blue\">◄</font> در اصطلاح نظامی، قسمتی از واحد نظامی که از عقب عمده ٔ قوی حرکت می کند و محافظ عقب است . (فرهنگ فارسی معین ). مؤخرةالجیش . <BR><font color=\"Blue\">◄</font> دم دار. ساقه .<br></font></div>'),
(184810, 'عقبلة', '<span class=\"hlight\">عقبلة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ب ِ ل َ ]</font></b> (ع ص ) پی رو و پس آینده، گویند هو عقبلة فلان ؛ یعنی او پس آینده ٔ اوست . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184811, 'عقبول', '<span class=\"hlight\">عقبول .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b>(ع اِ) باقی مانده ٔ بیماری و بقیه ٔ دشمنی و پس مانده ٔعشق . <BR><font color=\"Blue\">◄</font> تبخاله که بعد از تب برآید. <BR><font color=\"Blue\">◄</font> سختی . عُقبولة. ج، عَقابیل . (از منتهی الارب )(از اقرب الموارد). رجوع به عقبولة و عقابیل شود.<br></font></div>'),
(184812, 'عقبولة', '<span class=\"hlight\">عقبولة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ]</font></b> (ع اِ) عُقبول است در تمام معانی . (از منتهی الارب ) (از اقرب الموارد). رجوع به عقبول و عقابیل شود.<br></font></div>'),
(184813, 'عقبی', '<span class=\"hlight\">عقبی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) رضوان بن محمدبن یوسف عقبی شافعی مصری، مکنی به ابونعیم . از حافظان حدیث بود و به سال <span class=\"hlight\" dir=\"rtl\">٧٦٩</span> هَ . ق . در منیه ٔ عقبه در جیزة متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">٨٥٢</span> هَ . ق . در قاهره درگذشت . او راست : الاربعون المتباینه . المنتقی من طبقات الفقهاء. (از الاعلام زرکلی از الضوءاللامع).<br></font></div>'),
(184814, 'عقبی', '<span class=\"hlight\">عقبی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) حمزةبن محمدبن عباس بن فضل بن حرث دهقان عقبی، مکنی به ابواحمد. محدث و از اهالی عقبه ٔ بغداد بود و در ذیقعده ٔ سال <span class=\"hlight\" dir=\"rtl\">٣٤٧</span> هَ . ق . درگذشت . (از اللباب فی تهذیب الانساب ) (از معجم البلدان ).<br></font></div>'),
(184815, 'عقبی', '<span class=\"hlight\">عقبی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ]</font></b> (ص نسبی ) منسوب به عقب، در تداول فارسی، آنکه یا آنچه مؤخر باشد. مقابل جلوئی . رجوع به عَقِب شود.<br></font></div>'),
(184816, 'عقبی', '<span class=\"hlight\">عقبی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ص نسبی ) منسوب به عقبة، که پیش از هجرت، انصار با پیامبر اسلام (ص ) در آنجا بیعت کردند، و هریک از کسانی را که در آنجا حضور داشتند «عقبی » نامند. (از اللباب فی تهذیب الانساب ). و رجوع به عقبة شود. <BR><font color=\"Blue\">◄</font> منسوب به عقبة، که در ماورای نهر عیسی در نزدیکی دجله ٔ بغداد قرار دارد. (از اللباب فی تهذیب الانساب ). رجوع به عقبة شود.<br></font></div>'),
(184817, 'عقبی', '<span class=\"hlight\">عقبی .</span> <font color=\"DarkGreen\"><b>[ ع َق ِ ]</font></b> (ص نسبی ) منسوب به عقب که گویا بطنی از کنانه باشد و ابوالعافیة فضل بن عمیربن راشدبن عبداﷲ کنانی عقبی مصری بدانجا منسوب است . وی محدث بود و به سال <span class=\"hlight\" dir=\"rtl\">١٩٧</span> هَ . ق . درگذشت . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(184818, 'عقبی', '<span class=\"hlight\">عقبی .</span> <font color=\"DarkGreen\"><b>[ ع ُ با ]</font></b> (ع اِ) پاداش کار و حق . (منتهی الارب ). پاداش کار. (دهار) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بدل چیزی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آخر کار. (دهار). آخر هر چیزی . (از اقرب الموارد). سرانجام . (ترجمان القرآن جرجانی ) <span class=\"hlight\">:</span> والذین صبروا ابتغاء وجه ربهم ... اولئک لهم عقبی الدار. (قرآن <span class=\"hlight\" dir=\"rtl\">٢٢/١٣</span>)؛ و آنانکه برای بدست آوردن وجه خدایشان شکیبائی کردند... آنان را سرانجام آن سرای است . سلام علیکم بما صبرتم فنعم عقبی الدار. (قرآن <span class=\"hlight\" dir=\"rtl\">٢٤/١٣</span>)؛ درود بر شما به سبب صبری که کردید، پس چه خوب است سرانجام آن سرای . مثل الجنة التی وعد المتقون ... تلک عقبی الذین اتقوا، و عقبی الکافرین النار. (قرآن <span class=\"hlight\" dir=\"rtl\">٣٥/١٣</span>)؛ مثل بهشتی که پرهیزکاران را وعده دادند... آن سرانجام کسانی است که پرهیز کردند، و سرانجام کافران آتش است . و لایخاف عقباها. (قرآن <span class=\"hlight\" dir=\"rtl\">١٦/٩١</span>)؛ و از سرانجام آن بیم ندارد. <BR><font color=\"Blue\">◄</font> آخرت . (اقرب الموارد). آن دنیا. آن سرای . آن جهان . آن گیتی . اخری . سرای دیگر. جهان باقی <span class=\"hlight\">:</span> <br>نه امید عقبی نه دنیا بدست <br>ز هر دو رسیده بجانم شکست .<br> <font color=\"Red\">فردوسی .</font><br>آن کسی که اعتقاد وی بر این جمله باشد... توان دانست که در دنیا و عقبی نصیب خود را از سعادت تمام یافته باشد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٣٣</span>).<br>دنیا بجملگی همه امروز است <br>فردا شمرد باید عقبی را.<br> <font color=\"Red\">ناصرخسرو.</font><br>جز زاد و ساختن را از بهر راه عقبی <br>هشیار وپیش بین را هرگز بکار نائی .<br> <font color=\"Red\">ناصرخسرو.</font><br>عمر تو نبینی که یکی راه دراز است <br>دنیات بر این سر بر و عقبات بر آن سر.<br> <font color=\"Red\">ناصرخسرو.</font><br>به ملازمت آن سیرت نصیب دنیا هر چه کاملتر بیابد و رستگاری عقبی مدخر گردد. (کلیله و دمنه ). هر که طاعت را شعار و دثار خویش کند از ثمرات دنیا و عقبی بهره ور گردد. (کلیله و دمنه ).<br>گر رانده ای سعادت عقباش رد مکن <br>ور داده ای مؤونت دنیاش واستان .<br> <font color=\"Red\">خاقانی .</font><br>سفله را اقطاع دنیا بهتر از عقبی بود<br>خود جعل را بوی سرگین به ز عود و عنبراست . <br> <font color=\"Red\">عطار.</font><br>انبیا در کار دنیا جبریند<br>کافران در کار عقبی جبریند.<br> <font color=\"Red\">مولوی .</font><br>چو ما را به دنیا تو کردی عزیز<br>به عقبی همین چشم داریم نیز.<br> <font color=\"Red\">سعدی .</font><br>کسی گوی دولت ز دنیا ببرد<br>که با خود نصیبی به عقبی ببرد.<br> <font color=\"Red\">سعدی .</font><br>هر که به تأدیب دنیا راه صواب نگیرد، به تعذیب عقبی گرفتار آید. (گلستان ).<br>در تلفظ فارسی، این کلمه گاه به صورت ممال آید و عُقبی تلفظ شود <span class=\"hlight\">:</span> <br>بروی پاک و رای نیک و فعل خوب و کار خوش <br>نظیر او ندانم کس، چه در دنیی چه در عقبی .<br> <font color=\"Red\">منوچهری .</font><br>صبا به سبزه بیاراست روی دنیی را<br>نمونه گشت جهان مرغزار عقبی را.<br> <font color=\"Red\">انوری .</font><br>اگر عنایت لطف تو نیستی که از اوست <br>نعیم نامتناهی ریاض عقبی را.<br> <font color=\"Red\">ظهیر فاریابی .</font><br>- <span class=\"hlight\">دار عقبی </span> ؛ خانه ٔ آخرت . سرای باقی <span class=\"hlight\">:</span> درشهور سنه ٔ احدی و اربعمائة از دار دنیا به دار عقبی تحویل کرد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٧٦</span>).<br>- <span class=\"hlight\">عالم عقبی </span> ؛ جهان دیگر. آخرت . (ناظم الاطباء).<br></font></div>'),
(184819, 'عقد', '<span class=\"hlight\">عقد.</span> <font color=\"DarkGreen\"><b>[ ع ِ]</font></b> (ع اِ) گردن بند و حمیل و رشته ٔ مروارید. (منتهی الارب ). قلاده . (اقرب الموارد). گردن بند زنان، و یکدانه .(دهار). یکدانه . (السامی فی الاسامی ). سلک مروارید وگلوبند که آن را به هندی هار گویند. (غیاث اللغات ).ج، عُقود. (منتهی الارب ) (اقرب الموارد) <span class=\"hlight\">:</span> <br>چو بگسلد به نثار تو عقد گریه ٔ من <br>سرشک رشک به چشم گهر بگردانم .<br> <font color=\"Red\">نورالدین ظهوری (از آنندراج ).</font><br>خوشه چون عقد درو برگ چو زر<br>باده همچون عقیق و آب چو زنگ .<br> <font color=\"Red\">عماره .</font><br>از فتح و ظفر بینم بر نیزه ٔ تو عقد<br>وز فر و هنر بینم بر دیزه ٔ تو یون .<br> <font color=\"Red\">عنصری .</font><br>عقدی گوهر که گفتند هزار دینار قیمت آن بود از آستین بیرون گرفت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٨٠</span>). زمین بوسه داد و عقدی گوهر پیش سلطان نهاد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٩٨</span>). بیست عقد گوهر سخت قیمتی ... (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٢٥</span>).<br>گه زالماس او چو عقد گهر<br>نظم دولت همه بسامان باد.<br><font color=\"Red\">مسعودسعد.</font><br>شب عقد عنبرینه ٔ گردون فروگسست <br>تا دست صبح غالیه سازد ز عنبرش .<br> <font color=\"Red\">خاقانی .</font><br>اینک عروس روز پس حجله معتکف <br>گردون نثار ساخته صد عقد گوهرش .<br> <font color=\"Red\">خاقانی .</font><br>دانم که دگر باره گهر دزدد از این عقد<br>آن طفل دبستان من آن مردک کذاب .<br> <font color=\"Red\">خاقانی .</font><br>چون گهر عقد فلک دانه کرد<br>جعدشب از گرد عدم شانه کرد.<br> <font color=\"Red\">نظامی .</font><br>همی گفت این سخن وز نرگس مست <br>ز لؤلؤ عقدها بر ماه می بست .<br> <font color=\"Red\">نظامی .</font><br>فلک در عقد شاهی بند کردش <br>به یاقوتی دگر پیوند کردش .<br> <font color=\"Red\">نظامی .</font><br>همچنانکه عقد در در و شبه <br>مختلط چون میهمان یک شبه .<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">عقد پروین </span> ؛ ثریا. پروین . و رجوع به عقد ثریا در همین ترکیبات شود <span class=\"hlight\">:</span> <br>لؤلؤافشان توئی به مدحت شاه <br>عقد پروین بهای لؤلؤی تست .<br> <font color=\"Red\">خاقانی .</font><br>گر دل خطی بنگاشتی زلف و لبش پنداشتی <br>هم عقد پروین داشتی هم طوق جوزا یافتی .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عقدالجمان </span> ؛ سلک مروارید. (ناظم الاطباء).<br>- <span class=\"hlight\">عقد الخیطین </span> ؛ نام ستاره ای است . (از اقرب الموارد).<br>- <span class=\"hlight\">عقد ثریا</span> ؛ ثریا. پروین . و آن به مناسبت شباهت ثریا است به گردن بند. (از فرهنگ فارسی معین ). و رجوع به عقد پروین در همین ترکیبات و ثریا و پروین شود <span class=\"hlight\">:</span> <br>سعدیاعقد ثریا مگر امشب بگسیخت <br>ورنه هر شب به گریبان افق برمیشد.<br> <font color=\"Red\">سعدی .</font><br>عقد ثریا بر تاکش آویخته . (گلستان ).<br>- <span class=\"hlight\">عقد جمان </span> ؛ عقدالجمان <span class=\"hlight\">:</span> <br>در رکابش هفت گیسودار و شش خاتون ردیف <br>بر سرش هر هفت و شش عقد جمان افشانده اند.<br> <font color=\"Red\">خاقانی .</font><br>- - <span class=\"hlight\">عقد دوپیکر</span> ؛ کنایه ازجوزا <span class=\"hlight\">:</span> <br>نافه ٔ آهو شده ست ناف زمین از صبا<br>عقد دوپیکر شده ست پیکر باغ از هوا.<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عقد شب افروز</span> ؛ کنایه از ثوابت و سیاره باشد، یعنی زحل و مشتری و مریخ و آفتاب و زهره و عطارد و ماه و باقی ستاره های آسمانی که ثوابت اند. (برهان قاطع) (آنندراج ).<br>- <span class=\"hlight\">عقد شب و روز</span> ؛ کنایه از ماه و آفتاب است . (برهان ) (آنندراج ) (انجمن آرا).<br>- <BR><font color=\"Blue\">◄</font> کنایه از دنیا و روزگار. (برهان ) (آنندراج ).<br>- <span class=\"hlight\">عقد گوشه ٔ دستار</span> ؛ مراد گرهی است که مفلسان چیزی را بر گوشه ٔ دستار بسته بر آن گره بزنند. (آنندراج ).<br>- <span class=\"hlight\">واسطةالعِقْد</span> ؛ واسطه ٔ عقد. بزرگترین و درشت ترین مروارید و یا گوهر و یا مهره ای که در گلوبند یا دست بند باشد. میانگک . (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> سپاس و حمد و ثنا و شکر مر آفریدگار را عز اسمه که خطه ٔ اسلام و واسطه ٔ عقد عالم را به جمال عدل و رأفت ... آراسته گردانیده است . (کلیله و دمنه ). چنین آورده اند که نصربن احمد که واسطه ٔ عقد آل سامان بود... (چهارمقاله ٔ عروضی چ معین ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>). و رجوع به واسطةالعقد شود.<br>- <span class=\"hlight\">هم عقد</span> ؛ هم سلک . هم رشته <span class=\"hlight\">:</span> <br>گذشتند و ما نیز هم بگذریم <br>که چون مهره هم عقد یکدیگریم .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(184820, 'عقد', '<span class=\"hlight\">عقد.</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ]</font></b> (ع ص ) بسته زبان در سخن . (منتهی الارب ). آنکه در زبانش «عقده » باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتر نر کوتاه بالا نیک شکیبا بر کار و درشت پشت . (منتهی الارب ). جمل قصیر وصبور بر کار. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ)ریگ توده ٔ برهم نشسته . (منتهی الارب ). آنچه از رمل و ریگ که در هم پیچیده و متراکم باشد. واحد آن عقدة است .(از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درختی است که برگش زخم را پرگوشت نماید. (منتهی الارب ). درختی است که برگش زخم و جراحت را التیام دهد. (از اقرب الموارد).<br></font></div>'),
(184821, 'عقد', '<span class=\"hlight\">عقد.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) قبیله ای است از بجیلة یا از یمن، بشربن معاذ و ابوعامر عبدالملک بن عمرو از این قبیله اند. (منتهی الارب ).<br></font></div>'),
(184822, 'عقد', '<span class=\"hlight\">عقد.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع اِ) ریگ توده ٔ بسته و برهم نشسته . (منتهی الارب ). ریگ و رمل برهم پیچیده و متراکم . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گره زبان . (منتهی الارب ) «عقده »ای است در زبان . <BR><font color=\"Blue\">◄</font> پیچیدگی در دنب گوسفند که مانند عقده و گره است . <BR><font color=\"Blue\">◄</font> نوعی از خرما. (از اقرب الموارد).<br></font></div>'),
(184823, 'عقد', '<span class=\"hlight\">عقد.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع مص ) گره گرفتن زبان . (از منتهی الارب ). حبس شدن و بند آمدن زبان . <BR><font color=\"Blue\">◄</font> بودن «عقده » در زبان شخص . (از اقرب الموارد). رجوع به عقدة شود. <BR><font color=\"Blue\">◄</font> گرفتن فرج ماده سگ سر نره ٔ نر را. (ناظم الاطباء). رجوع به عَقد شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(184824, 'عقد', '<span class=\"hlight\">عقد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِمص، اِ) پذرفتاری و پیمان . (منتهی الارب ). پیمان و زینهار. (مهذب الاسماء). قرارداد <span class=\"hlight\">:</span> پسندیده تر آن است که میان ما دو دوست عهدی باشد و عقدی بدان پیوسته گردد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢١٠</span>). چنگ درزده ام در بیعت او به وفای عهد و بری ساختن ذمه و عقد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣١٥</span>). با قدرخان سخن عقد و عهد گفته آمده است . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٨٤</span>). ابوالقاسم فقیه برفت و جانب ایشان به دست آورده و با هر یک عقد ومیثاقی از سر گرفت . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١١٩</span>). مرا به رسالت از برای عقد بیعت پیش شار فرستادند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٣٩</span>). <BR><font color=\"Blue\">◄</font> رای و فکر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اصطلاح فقهی ) در اصطلاح فقهی و شرعی، ایجاب و قبول است با ارتباط معتبر از حیث شرع . بنابراین عقد شامل سه امر باشد: ایجاب، قبول، ارتباط. (از کشاف اصطلاحات الفنون ). ربط دادن اجزاء تصرف است شرعاً به ایجاب و قبول . (از تعریفات جرجانی ).<br>در فقه سه معنی برای عقدگفته شد: <span class=\"hlight\" dir=\"rtl\">١</span>- عقد به معنی عهد. <span class=\"hlight\" dir=\"rtl\">٢</span>- عقد بمعنی پیمان مؤکد. <span class=\"hlight\" dir=\"rtl\">٣</span>- عقد عبارت است از صیغه ٔ ایجاب و قبول . بنابراین تعریف در هر عقدی لفظ لازم است و با اشاره و کتابت و معاطات عقد واقع نمیشود و به عبارت دیگر همه ٔ عقود تشریفاتی خواهد بود. تعریف اول و دوم صرفاً یک تفسیر لغوی است نه یک تفسیر حقوقی، لذا فاقد ارزش است . و تفسیر سوم هم سند قوی در منابع حقوقی اسلامی (قرآن کریم و احادیث ) ندارد به همین جهت اصل تشریفاتی بودن عقود از نظر منابع حقوق اسلامی مسلم نیست . (از فرهنگ حقوقی ). <BR><font color=\"Blue\">◄</font> (اصطلاح حقوق ) در اصطلاح حقوقی، عقد عبارت است از اینکه یک یا چند نفر در مقابل یک یا چند نفر دیگر «تعهد»بر امری نمایند و مورد قبول آنها باشد (ماده ٔ <span class=\"hlight\" dir=\"rtl\">١٨٣</span> قانون مدنی ایران ) این تعریف عقد به معنی اخص است و فقط شامل «عقد عهدی » میشود. و نیز عبارت است از توافق اراده ٔ دو یا چند نفر بر «ایجاد» یک رابطه ٔ الزامی، اعم از اینکه به منظور انتقال مال و یا حقی باشد یابه منظور تعهد بر فعل و یا ترک عملی . تمایل در تألیفات مؤلفین «حقوق جدید» بر این است که کلمه ٔ عقد در این معنی استعمال شود و این معنی مأخوذ از ماده ٔ <span class=\"hlight\" dir=\"rtl\">١١٠١</span> قانون مدنی فرانسه است . در هر صورت این تعریف «عقد به معنی خاص » است . و یا عبارت است از توافق اراده ٔ دو یا چند نفر به منظور «ایجاد» یا «انتفاء» یک حق . این تعریف «عقد به معنی عام » است که در این صورت غالباً در اصطلاحات فرانسه آن را «کُنوانسیون » و در اصطلاحات حقوق جدید آن را «قرارداد» نامند. «لفظ کنترات » به فرانسه در هر سه معنی بالا استعمال شده اگر چه غالباً در معنی دوم استعمال میشود و در معنی سوم غالباً لفظ «کنونشن » بکار میرود. (از فرهنگ حقوقی ). <BR><font color=\"Blue\">◄</font> در اصطلاح حقوق یک عنصری، عقد عبارت است از تراضی طرفین بر نفی محرومیت . بنابراین تعریف عقد سه قسم است : <span class=\"hlight\" dir=\"rtl\">١</span> - عقد عهدی . <span class=\"hlight\" dir=\"rtl\">٢</span> - عقد تملیکی . <span class=\"hlight\" dir=\"rtl\">٣</span> - عقد غیرعهدی و غیر تملیکی، مانند مقاربت به تراضی نه بقصد ازدواج . اثر ابتکار این تئوری در مورد «اطفال طبیعی » ظاهر میشود چه بنابراین نظر در مورد این اطفال هم مانند «اطفال قانونی » عقدی بین ابوین صورت گرفته است، و ایجاد نابرابری حقوقی بین دو دسته از اطفال صرفاً به طرز فکر مقنن در رعایت صلاح جامعه بستگی دارد. (از فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد احتمالی </span> ؛ عقد مغابنه . عقد غرر. رجوع به عقد مغابنه در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد اذعان </span> ؛ عقد تصویبی . عقد انضمام . رجوع به عقد تصویبی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد اصلی </span> ؛ عقدی است که وجود مستقل و اصیل داشته باشد مانند عقد بیع و اغلب معاملات معاطاتی، در مقابل اصطلاح بالا اصطلاح «عقدتبعی » قرار میگیرد و آن عقدی است که به تبع عقد دیگری منعقد میشود مانند عقد رهن که به تبع عقد دیگری منعقد میشود. اگر عقد اصلی مضمحل شود عقد تبعی هم مضمحل خواهد شد ولی عکس قضیه درست نیست . (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد اکتساب </span> ؛ عقدی است که هدف از آن انتقال مال جدیدی در ملکیت متعاقدین (یا یکی از آنان ) باشد. در مقابل این اصطلاح، اصطلاح «عقد ضمان » قرار میگیرد و آن عقدی است که هدف از آن تثبیت ذمه ای به حال خود باشد مانند ضمان عقدی و کفالت . (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد انضمام </span> ؛ عقد تصویبی . عقد اذعان . رجوع به عقد تصویبی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد با تقابل استفاده </span> ؛ در اصطلاح حقوق یک عنصری، عقدی است که طرفین (و یا قائم مقام آنها) متقابلاً از عقد استفاده ببرند. این عقد دو قسم است : <span class=\"hlight\" dir=\"rtl\">١</span>- عقد معوض مانند بیع. <span class=\"hlight\" dir=\"rtl\">٢</span>- عقد غیر معوض مانند نکاح . اصطلاح بالا را گاهی بصورت «عقد مبتنی بر تقابل منافع» تعبیر می کنند. رجوع به عقد معوض و عقد بی تقابل استفاده در همین ترکیبات شود. (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد باطل، یا عقد غیرصحیح، یا عقد غیرنافذ</span>؛ عقدی که نافذ شرایط صحت عقد باشد، و آن را «عقد غیرصحیح » نیز نامند. رجوع به فرهنگ حقوقی شود.<br>- <span class=\"hlight\">عقد به معنی اخص </span> . رجوع به عقد شود.<br>- <span class=\"hlight\">عقد به معنی خاص </span> . رجوع به عقد شود.<br>- <span class=\"hlight\">عقد به معنی عام </span> . رجوع به عقد شود.<br>- <span class=\"hlight\">عقدبی تقابل استفاده </span> ؛ در اصطلاح حقوق یک عنصری، عقدی است که در آن فقط یکی از طرفین استفاده ٔ حقوقی می برد. مانند «هبه ٔ معوضه » و «عقد وکالت مجانی ». عقد غیر معوض دو قسم است : <span class=\"hlight\" dir=\"rtl\">١</span>- عقد بی تقابل استفاده، مانندوکالت مجانی . <span class=\"hlight\" dir=\"rtl\">٢</span>- عقد با تقابل استفاده مانند عقد نکاح . (فرهنگ حقوقی ). رجوع به عقد معوض در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد بیع</span> ؛ اجرای صیغه ٔ بیع. (ناظم الاطباء). بستن پیمان خرید و فروش <span class=\"hlight\">:</span> در عقد بیع سرائی متردد بودم . (گلستان ).<br>- <span class=\"hlight\">عقد بیمه </span> ؛ عقدی است که به موجب آن یک طرف تعهد میکند که در ازاء پرداخت وجهی از طرف دیگر در صورت وقوع یا بروز حادثه، خسارت وارد بر او را جبران نماید و یا وجه معینی بپردازد. (فرهنگ حقوقی ). رجوع به بیمه شود.<br>- <span class=\"hlight\">عقد تبرع </span> ؛ عقد غیرمعوض . رجوع به عقد غیرمعوض در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد تبعی </span> ؛ عقدی که به تبع عقد دیگری منعقد میشود. رجوع به عقد اصلی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد تجاری </span> ؛ عقدی که موضوعش یک عمل تجاری باشد. رجوع به عقد مدنی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد تدریجی </span> ؛ عقدی است که احد طرفین آن عقد (یا هر دو طرف ) یک امر تدریجی الحصول را تعهد کنند، مانند عقد اجاره، عقد کار و غیره .در مقابل این اصطلاح «عقد غیرتدریجی » قرار میگیرد که طرفین عقد موضوع غیرتدریجی الحصول را مورد عقد قرار دهند، مانند بیع. عقد تدریجی را عقد ممتد و عقد مستمر نیز نامند. و در مقابل آن عقد غیرتدریجی یا عقد فوری است . (از فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد تشریفاتی </span> ؛ عقدی را گویند که علاوه بر اجتماع جمیع شرایط اساسی صحت عقد، تشریفات صوری مخصوص (مانند تلفظ به صیغه ٔ خاص یا به لغت خاص یا ثبت در دفتر اسناد رسمی یا کتبی بودن عقد <font color=\"DarkGreen\"><b>[ مانند عقد بیمه ]</font></b> ) لازم داشته باشد. اصل در عقود، غیر تشریفاتی بودن است و تشریفاتی بودن استثناء. عقد غیر تشریفاتی را «عقد رضائی » گویند چه بصرف تراضی طرفین و بدون هیچگونه تشریفات عقد واقع میشود. (ماده ٔ <span class=\"hlight\" dir=\"rtl\">١٩١</span> قانون مدنی ایران ). عقد تشریفاتی را عقد صوری و عقد شکلی و عقد رسمی نیز نامند. (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد تصویبی </span> ؛ عقدی است که شرایط اصلی عقد را یکی از طرفین عقد که از لحاظ قدرت اقتصادی ابتکار عمل را در دست دارد معین میکند و طرف دیگر فقط حق اعلان قبول (یا تصویب شرایط پیشنهادی طرف مقابل ) رادارد. در اصطلاحات دیگر آن را «عقد اذعان » و «عقد انضمام » نامند. در مقابل این اصطلاح «عقد غیرتصویبی » قرار دارد که طرفین عقد با تبادل نظر خود آزادانه شرایط عقد را معین میکنند و در اصطلاح دیگر آن را «عقد مساومة» و «عقد مفاوضة» می نامند. و در مقابل آن عقد غیر تصویبی است . (از فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد تملیکی </span> ؛ عقدی است که به وسیله ٔ آن انتقال مالکیت حاصل میگردد یعنی مورد معامله از ملکیت ناقل به ملکیت منتقل الیه میرود. (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد جائز</span> ؛ عقدی است که هر یک از طرفین (اگر عقد جائزالطرفین باشد) و یا یکی از طرفین (اگرعقد از یک طرف جایز باشد مانند رهن در فقه اسلام ) بتواند هر وقت که بخواهد آن را فسخ کند. (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد جزیه </span> . رجوع به جزیه و عقد ذمة در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد جمعی </span> ؛ در مقابل عقد فردی . رجوع به فرهنگ حقوقی شود.<br>- <span class=\"hlight\">عقد حقیقی </span> ؛ در اصطلاح حقوق یک عنصری . رجوع به عقد حکمی در همین ترکیبات و فرهنگ حقوقی شود.<br>- <span class=\"hlight\">عقد حکمی </span> ؛ در اصطلاح حقوق یک عنصری، هرگاه دو طرف متصدی انعقاد عقدی شوند و لااقل یک طرف عقد فاقد «رضای کامل » باشد از نظر حقوق یک عنصری، عقد بوجود نمی آید ولی اگر رعایت صلاح جامعه اقتضا کند که بر چنین عملی آثار حقوقی مترتب شود اصطلاحاً ازآن عمل به «عقد حکمی » تعبیر میشود مانند عقد بیعی که شخص محتکر به اجبار حاکم انجام میدهد که با وجود فقد «رضای کامل » آثار بیع قانوناً بر عمل او مترتب است . (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد حمل </span> ؛ در اصطلاح منطق، ثبوت محمول برای موضوع است . توضیح آنکه میان مصادیق موضوع و مفهوم آن ارتباطی است و میان موضوع و مصادیق موضوع با محمول نیز ارتباط است . مثلاً در قضیه ٔ «انسان کاتب است » اولاً این قضیه منحل به دو جزء میشود یکی کلمه ٔ انسان و دیگر کلمه ٔ کاتب . کلمات انسان و کاتب دو لفظاند که دال بردو معنی میباشند و از نظر منطق غیر از مقصود دلالتی خود آن دو لفظ چیزی مورد نظر نمی باشد و آنچه مورد نظر است مفهوم انسان و مفهوم کاتب است و میدانیم که مفهوم انسان و کاتب را نیز مصادیقی است که هر یک از دومفهوم با مصادیق خود ارتباط دارند نوع ارتباط کلی با افراد خود. و میدانیم مصادیق انسان در قضیه ٔ فوق همان مصادیق کاتب است پس افرادی مانند زید و عمرو و بکر را در قضیه ٔ فوق دو ارتباط است یکی ارتباط آنها با مفهوم انسان و یکی دیگر ارتباط آنها با مفهوم کاتب و کتابت . ارتباط میان مصادیق را با انسان عقد وضع گویند و ارتباط آنها را با مفهوم کاتب عقد حمل گویند.(فرهنگ علوم عقلی به نقل از کشاف ص <span class=\"hlight\" dir=\"rtl\">٩٥٣</span> و دستور ج <span class=\"hlight\" dir=\"rtl\">٢</span>ص <span class=\"hlight\" dir=\"rtl\">٣٣٢</span>).<br>- <span class=\"hlight\">عقد خیاری </span> ؛ عقدی است که برای طرفین یا یکی از آنها یا برای ثالث اختیار فسخ باشد و آن نوعی از عقد لازم است که اثر عقد جائز را دارد. (بیع شرط هم از مصادیق عقد خیاری است ). (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد داوری </span> . رجوع به فرهنگ حقوقی شود.<br>- <span class=\"hlight\">عقد دوجانبه </span> . رجوع به عقد یک جانبه در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد ذمه </span> ؛ در اصطلاح قانون حرب اسلام، عقدی است که بین حاکم کل جامعه ٔاسلامی، یا نماینده ٔ قانونی او، و اجانبی که متدین به یکی از ادیان موسوی، عیسوی، زردشتی می باشند منعقد میشود. رجوع به فرهنگ حقوقی شود.<br>- <span class=\"hlight\">عقد رسمی </span> ؛ عقدتشریفاتی . عقد شکلی . عقد صوری . رجوع به عقد تشریفاتی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقدرضائی </span> ؛ عقد غیرتشریفاتی . رجوع به عقد تشریفاتی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد شانس </span> ؛ عقد مغابنه . عقد احتمالی .رجوع به عقد مغابنه در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد شرکت </span>؛ توافق دو یا چند نفر برای کسب منافع بوسیله ٔ سرمایه و یا خدماتی که در بین میگذارند، و آن یا شرکت تجارتی است یا شرکت مدنی . این اصطلاح را به صورت «شرکت اختیاری » نیز نامند. (فرهنگ حقوقی ). رجوع به شرکت شود.<br>- <span class=\"hlight\">عقد شکلی </span> ؛ عقد تشریفاتی . عقد صوری . عقد رسمی . رجوع به عقد تشریفاتی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد صحیح </span> ؛ عقدی است که اولاً علل بطلان عقد را نداشته باشد. ثانیاً رضای کامل متعاقدین در آن فراهم شود. با فقدان این شرط آن عقد «غیرنافذ» خواهد بود. (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد صوری </span> ؛ عقد رسمی . عقد تشریفاتی . عقد شکلی . رجوع به عقد تشریفاتی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد ضمان </span> ؛ در اصطلاح حقوق مدنی، عقدی است که به موجب آن شخصی مالی را که بر ذمه ٔ دیگری است به عهده بگیرد. در این صورت دین با تمام مشخصات خود به ذمه ٔ ضامن منتقل میشود مگر اینکه شرط خلاف آن شود. مقصود از اصطلاح «ضمان عقدی » هم همین معنی است . و نقطه ٔمقابل ضمان عقدی «ضمان قهری » است . (فرهنگ حقوقی ). ورجوع به ضمان شود. عقد ضمان در معنی اعمی هم استعمال میشود و در این صورت در مقابل «عقد اکتساب » قرار گیرد. (فرهنگ حقوقی ). رجوع به عقد اکتساب در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد ضمان جریره </span> ؛ هرگاه شخصی که وارث نباشد جرائم شخصی را ضمانت نماید به این شرط که از او میراث ببرد، بعد از فوت او، از وی ارث خواهد برد. این عقد را «عقد ضمان جریره » نامند و موجب این ارث بردن را اصطلاحاً «ولاء ضمان جریره » نامیده اند و شخص ضامن را «ضامن جریره » و این ضمان را «ضامن جریره » می نامند. (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد عهدی </span> ؛ عقدی است که ایجاد حق دین و تعهدبرای یک طرف در مقابل طرف دیگری یا برای هر یک از طرفین در مقابل طرف دیگر می نماید. مانند بیع سلم و بیع کالی بکالی . (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد عینی </span> ؛ عقد واقعی، رجوع به عقد واقعی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد غرر</span> ؛ عقد مغابنه . عقد احتمالی . رجوع به عقد مغابنه در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد غیرعهدی وغیرتملیکی </span> . رجوع به عقد شود.<br>- <span class=\"hlight\">عقد غیرمالی </span> ؛ در اصطلاح حقوق یک عنصری، هر عقدی که موضوع آن مال نباشد مانند عقد نکاح . (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد غیرمعوض </span> ؛هرگاه در عقدی انتقال مال و یا تعهد فقط از یک طرف به نفع طرف دیگر مقرر شود اصطلاحاً آن را «عقد غیرمعوض » نامند. در اصطلاح دیگر از آن به «عقد تبرع » تعبیر شود. (فرهنگ حقوقی ). و رجوع به عقد بی تقابل استفاده در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد غیرمعین </span> ؛ هر عقدی است که عنوان خاص و مقررات مخصوص به خود در بین سایر عقود نداشته باشد. مانند عقد معلق که ممکن است به شکل بیع، اجاره، رهن و غیره باشد. اگر عقدی دارای عنوان خاص باشد اصطلاحاً آن را «عقد معین » نامند. (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد غیرمغابنه </span> . رجوع به فرهنگ حقوقی و عقد مغابنه در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد فردی </span> ؛ در مقابل عقد جمعی . رجوع به فرهنگ حقوقی شود.<br>- <span class=\"hlight\">عقد فضولی </span> ؛ در اصطلاح فقهی، آن است که شخصی که خود مالک متاعی نیست از طرف صاحبش بفروشد و همینطور دختری رابدون اذن او نکاح کند. در این که عقد فضولی بنفسه منشاء اثر نیست شکی نمی باشد بدین معنی که نفس عقد فضولی را اثری نیست چون یکی از ارکان معامله، مالک بودن متاع است . لکن اگر پس از وقوع عقد، مالک آن امضا کرد گویند معامله صحیح است و آثار لازم بر آن مترتب است به ویژه در نکاح که اتفاقی است که پس از تنفیذ و امضا، عقد کامل و درست میشود. آنان که گویند عقد فضولی پس از اجازه و امضا درست است اختلاف کرده اند که آیا اجازه ٔ مالک کاشف است یا ناقل، یعنی کاشف از سبق ملک است یا همان اجازه ناقل ملک است . البته فوایدی چند بر هریک از دو قول مترتب است . باید دانست که روایت اصلی در مورد نکاح است و به تنقیح مناط به معاملات دیگر جریان دهند. (فرهنگ علوم نقلی ).<br>- <span class=\"hlight\">عقد فوری </span> ؛ عقد غیرتدریجی . رجوع به عقد تدریجی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد قابل فسخ </span> ؛ عقد صحیح دو قسم است :<br><span class=\"hlight\" dir=\"rtl\">١</span> - عقد قابل فسخ . <span class=\"hlight\" dir=\"rtl\">٢</span> - عقد غیرقابل فسخ . شق اول نیز دو قسم است : الف - عقد لازم قابل فسخ، مانند عقد خیاری . ب - عقد جائز.<br>بنابراین عقد قابل فسخ عقدی است جایز یا لازم که قانوناً یکی از طرفین یا هر دو طرف اختیار انحلال آن را نداشته باشد مگر در موارد معین شده در قانون . (فرهنگ حقوقی ).و رجوع به عقد جایز در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد لازم </span> ؛ عقدی است که هیچ یک از طرفین معامله حق فسخ آن را نداشته باشد مگر در موارد معین شده در قانون . (فرهنگ حقوقی ). و رجوع به عقد جایز در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد مالی </span> ؛ در اصطلاح حقوق یک عنصری، هر عقدی است که موضوع آن مال بطور اعم باشد مانند اجاره و بیع و غیره . و آن دو قسم است : اول - «عقد معاملی » که عوض و معوض در آن عرفاً برابر و متعادل است مانند بیع معمولی و غیره . اصطلاح «معامله » به معنی حقیقی خود منصرف به معنی «عقد معاملی » است . دوم - «عقد معوض غیرمعاملی » و آن عقدی است که عوضین آن تعادل عرفی ندارد مانند «معامله ٔ محاباتی ». (از فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد مبتنی بر تقابل منافع</span> ؛ عقدی که طرفین متقابلاً از عقد استفاده برند. رجوع به «عقد با تقابل استفاده » در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد محقق </span> ؛ عقد غیرمغابنه . رجوع به عقد غیرمغابنه و عقد مغابنه در همین ترکیبات و فرهنگ حقوقی شود.<br>- <span class=\"hlight\">عقد مدنی </span> ؛ عقدی است که موضوعش یک عمل مدنی باشد و اگر موضوع عقد یک عمل تجاری باشد آن را عقد تجاری نامند. (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد مساومة</span> ؛ عقد غیرتصویبی . رجوع به عقد تصویبی و عقد غیرتصویبی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد مستمر</span> ؛ عقد ممتد. عقد تدریجی . رجوع به عقد تدریجی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد مشروط</span> ؛ عقدی است که یکی از شروط (شرط نتیجه - شرط فعل - شرط صفت ) در آن قید شده باشد. هر عقد معلقی مشروط است ولی هر عقد مشروطی معلق نیست . (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد مطلق </span> ؛ عقدی است خالی از شرط و تعلق، مانند غالب موارد بیع معاطاة. (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد معاملی </span> ؛ عقد مالی . رجوع به عقد مالی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد معاوضه </span> ؛ عقد معوض . رجوع به عقد معوض در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد معلق </span> ؛ در مقابل عقد منجز. رجوع به عقد منجز در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد معوض </span> ؛ عقدی است که بین طرفین آن انتقال مال و یاتعهد بطور متقابل صورت گیرد. و آن دو قسم است : اول - عقد معوض معاملی یا «عقد معامله » یا «معامله ». دوم عقد معوض غیرمعاملی . عقد معوض را «عقد معاوضه » نیز نامند. (فرهنگ حقوقی ). رجوع به عقد مالی و عقد بی تقابل استفاده در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد معوض غیرمعاملی </span> . رجوع به عقد مالی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد معین </span> ؛ عقدی که دارای عنوان خاص باشد. رجوع به عقد غیرمعین در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد مغابنه </span> ؛ یا عقد شانس، عقدی است که طرفین آن (مانند بازی قمار و شرطبندی ) و یا یک طرف (مانند لاتار) بر یکی از دو امر ذیل توافق نمایند: <span class=\"hlight\" dir=\"rtl\">١</span>- شانس حصول یک منفعت . <span class=\"hlight\" dir=\"rtl\">٢</span>- تضمین در مقابل شانس از دست دادن چیزی . و در مقابل آن عقد غیرمغابنه قراردارد. (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد مفاوضه </span> ؛ عقد غیرتصویبی . عقد مساومة.رجوع به عقد غیرتصویبی و عقد تصویبی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد ملزم دوطرف </span> ؛ عقد دوجانبه . رجوع به عقد یک جانبه در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد ملزم یک طرف </span> ؛ عقد یک جانبه . رجوع به عقد یک جانبه در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد ممتد</span> ؛ عقد تدریجی . عقد مستمر. رجوع به عقد تدریجی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد منجز</span> ؛ عقدی است که تأثیر آن بر حسب انشاء موقوف به امر دیگری نباشد وگرنه آن را عقد معلق گویند. (ماده ٔ <span class=\"hlight\" dir=\"rtl\">١٨٩</span> قانون مدنی ایران ) (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد واقعی </span> ؛ عقدی است که وجود آن بسته به تسلیم مال موضوع عقد است مانند عاریه و ودیعه . و گاهی آن را عقد عینی نیز گویند. (فرهنگ حقوقی ).<br>- <span class=\"hlight\">عقد وضع</span> ؛ در اصطلاح منطقیان، توصیف صاحب موضوع است به وصف عنوانی خود، و آن ترکیب تقلیدی است . (کشاف اصطلاحات الفنون ). اتصاف موضوع است به عنوان . (فرهنگ علوم نقلی ). رجوع به عقد حمل در همین ترکیبات شود.<br>- <span class=\"hlight\">عقد یک جانبه </span> ؛ عقد را نسبت به تعهد ناشی از آن دو قسم نموده اند: <span class=\"hlight\" dir=\"rtl\">١</span>- تعهد فقط از یک طرف عقد باشد، بدون اینکه طرف دیگر تعهدی داشته باشد. <span class=\"hlight\" dir=\"rtl\">٢</span>- تعهد از دو طرف باشد مانند اغلب معاملات معمولی . اولی را اصطلاحاً«عقد یک جانبه » و «عقد ملزم یک طرف » و دومی را «عقد دوجانبه » و «عقد ملزم دوطرف » گویند. در عقد یک جانبه اراده ٔ متعاقدین و توافق آنان لازم است و به همین جهت نباید آن را با ایقاع اشتباه نمود زیرا در ایقاع اراده ٔ یک طرف کافی است . (از فرهنگ حقوقی ).<br> <BR><font color=\"Blue\">◄</font> گره و بند. (ناظم الاطباء) <span class=\"hlight\">:</span> <br>عجز فلک را به فلک وانمای <br>عقد جهان راز جهان واگشای .<br> <font color=\"Red\">نظامی .</font><br>ور گشادی عقد او را عقلها<br>انبیا را کی فرستادی خدا.<br> <font color=\"Red\">مولوی .</font><br> <BR><font color=\"Blue\">◄</font> نکاح و زناشوئی و ازدواج . (ناظم الاطباء) <span class=\"hlight\">:</span><br>میان ما نه عقدی نه نکاحی <br>نه آیین عروسی بود و نه سور.<br> <font color=\"Red\">منوچهری .</font><br>- <span class=\"hlight\">به عقد نکاح درآوردن </span> ؛ به زنی گرفتن . به زن کردن . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">در عقد کسی بودن </span> ؛ همسر او بودن <span class=\"hlight\">:</span> هر زنی که در عقد من است یا بعد از این در عقد من خواهد آمد مطلقه است به سه طلاق به این که رجعت در او نگنجد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣١٨</span>).<br>- <span class=\"hlight\">عقد ازدواج </span> ؛ صیغه ٔ ازدواج .عقد زناشوئی . اًملاک . مَلاک . مِلاک . (از منتهی الارب ).<br>- <span class=\"hlight\">عقد کابین </span> ؛ قرارداد مهر<span class=\"hlight\">:</span> <br>بود عقد کابین او اینکه تو<br>کنی سجده ٔ شکر، چون شاکری .<br> <font color=\"Red\">منوچهری .</font><br>- <span class=\"hlight\">عقد نکاح </span> ؛ صیغه ٔ ازدواج . بُضع <span class=\"hlight\">:</span> در عقد نکاح و عروسی وی <font color=\"DarkGreen\"><b>[ طغرل ]</font></b> تکلف هاء بی محل نمود. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٥٤</span>). و رجوع به عقد بستن و عقد کردن شود.<br>- <span class=\"hlight\">مجلس عقد</span> ؛ مجلس ضیافت زناشوئی . (ناظم الاطباء) <span class=\"hlight\">:</span> چون ازمجلس عقد بازگردی نثارها و هدیه ها که با تو فرستاده آمده است، بفرمای خازنان را که با تواند ببرند و تسلیم کنند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢١٢</span>).<br> <BR><font color=\"Blue\">◄</font> در اصطلاح بلاغت، به نظم درآوردن عبارت منثور است، خواه از آیات قرآن و یا احادیث و خواه از امثال و غیره باشد، اما نه به طریق اقتباس . رجوع به کشاف اصطلاحات الفنون شود. <BR><font color=\"Blue\">◄</font> در حساب عقود انگشتان، عقد انامل، یکی از طرق علم عقد. شمارش اعداد بوسیله ٔ باز کردن و بستن انگشتان دست <span class=\"hlight\">:</span> <br>عقد جود او همه پنجه بود<br>خود به دست چپ بود هر پنجهی .<br> <font color=\"Red\">منوچهری .</font><br>رجوع به عقد انامل شود.<br><BR><font color=\"Blue\">◄</font> شتر نر قوی پشت . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد بسته زبان . <BR><font color=\"Blue\">◄</font> طاق بنا. (منتهی الارب ). آنچه از بنا، که بهم برآورده باشی . (از اقرب الموارد). ج، أعقاد. (منتهی الارب ) (اقرب الموارد) و عُقود. (اقرب الموارد).<br></font></div>'),
(184825, 'عقد', '<span class=\"hlight\">عقد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) پناه بردن به کسی . (از منتهی الارب ): عقد عنقه اًلیه ؛ به وی پناه برد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بستن ریسمان و بیع. (از منتهی الارب ). محکم کردن و بستن ریسمان و بیع و پیمان و سوگند و از قبیل آن، و آن در مقابل «حَل ّ» و گشودن است . (از اقرب الموارد). گره زدن و پیمان کردن . (المصادر زوزنی ). گره بستن و پیمان کردن و بیع بستن . (تاج المصادر بیهقی ). بستن گره و پیمان . (ترجمان القرآن جرجانی ). پیمان و نکاح وبیع کردن . (غیاث اللغات ): فلان لایعقدالحبل ؛ او بر گره بستن ریسمان توانایی ندارد، آن را در مورد شخص بی بضاعت و کم ثروت گویند. (از اقرب الموارد) <span class=\"hlight\">:</span> <br>قطره ٔ این و ذره ٔ آنرا<br>در حساب آورد به عقد حساب .<br> <font color=\"Red\">سوزنی .</font><br>- <span class=\"hlight\">اهل حل و عقد</span> ؛ کسی که محل اعتماد مردمان باشد. (ناظم الاطباء): هو أهل الحل و العقد؛ او معتمد مردمان است . (منتهی الارب ).<br>- <span class=\"hlight\">حل و عقد</span> ؛ گشودن و بستن، و آن کنایه از انجام دادن امور است . رتق و فتق . گشاد و بست کارها. سررشته کردن و سروسامان دادن <span class=\"hlight\">:</span> تو به کدخدائی قیام کنی، چنانکه حل و عقد و خفض و رفع و امر و نهی بتو باشد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٩٨</span>).<br>تأثیر حل و عقدش در قبض و بسط ملک <br>بر آب نقش گشت و بر آتش نشان گرفت .<br> <font color=\"Red\">مسعودسعد.</font><br>شبها و روزهای تو در حل و عقد ملک <br>از حکمهای دور سپهر اختیار باد.<br> <font color=\"Red\">مسعودسعد.</font><br>ملک ... دست او را در...حل و عقد گشاده و مطلق داشت . (کلیله و دمنه ). دست او را در حل و عقد و حبس و اطلاق روان کرد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٦٤</span>).<br>پس محمد صد قیامت بود نقد<br>زانکه حل شد در فنأش حل و عقد.<br> <font color=\"Red\">مولوی .</font><br><BR><font color=\"Blue\">◄</font> آماده ٔ بدی شدن . (از منتهی الارب ): عقد ناصیته ؛ خشمگین شدو برای شر و بدی آماده گشت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شمار کردن . (منتهی الارب ). حساب کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سطبر شدن مایع، گویند عقدالرب . (از منتهی الارب ). ستبر شدن انگبین و جز آن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> سطبر کردن، لازم و متعدی است . <BR><font color=\"Blue\">◄</font> گره کردن ناقه دنب را جهت لقاح . <BR><font color=\"Blue\">◄</font> سوگند دادن بدون لغو و استثنا. (ازمنتهی الارب ). سوگند بقصد خوردن . (تاج المصادر بیهقی ). بقصد سوگند خوردن . (ترجمان القرآن جرجانی ). سوگند بقصد خوردن . (المصادر زوزنی ). <BR><font color=\"Blue\">◄</font> لغو کردن . <BR><font color=\"Blue\">◄</font> پیچان کردن ریش را، و از آن جمله است حدیث «من عقد لحیته فان محمداً بری ٔ منه » و گویند اعراب جاهلیت در جنگها ریش خود را پیچان میکردند و می بافتند و آن نشانه ای از عجب و تکبر بود لذا پیامبر (ص ) امر به ارسال لحیه کرد. <BR><font color=\"Blue\">◄</font> گرفتن فرج ماده سگ سر نره ٔ نر را. (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> ضمانت کردن . <BR><font color=\"Blue\">◄</font> گره قرار دادن در نخ، و اطراف آن را گرد آوردن . (از اقرب الموارد). گره دادن . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> چسباندن : عقد البناء بالجَص ّ؛ ساختمان را با گچ بهم آورد و چسباند. <BR><font color=\"Blue\">◄</font> ساختن « عقد» و طاق بنا را. (از اقرب الموارد).<br></font></div>'),
(184826, 'عقد', '<span class=\"hlight\">عقد.</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (ع اِ) ج ِ عُقدة.(منتهی الارب ) (اقرب الموارد). گره ها. رجوع به عقدة شود <span class=\"hlight\">:</span> و من شر النفاثات فی العقد. (قرآن <span class=\"hlight\" dir=\"rtl\">٤/١١٣</span>)؛ و از شر زنان دمنده ٔ افسون در عقده ها و گره ها:<br>فغان من همه زان زلف بی تکلف اوست <br>فکنده طبع بر او بر هزار گونه عقد.<br> <font color=\"Red\">منجیک .</font><br>سنبل بسان زلفی با پیچ و با عقود<br>زلف آن نکو بود که بدو در عقد بود.<br> <font color=\"Red\">منوچهری .</font><br>قل اعوذت خواند باید کای صمد<br>هین ز نفاثات افغان وز عقد.<br> <font color=\"Red\">مولوی .</font><br><BR><font color=\"Blue\">◄</font> تحللت عقده ؛ خشم و غضب وی فرونشست و آرام گرفت . (از اقرب الموارد) (از منتهی الارب ).<br></font></div>'),
(184827, 'عقد', '<span class=\"hlight\">عقد.</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ق ِ ]</font></b> (اِخ ) موضعی است میان بصره و ضربة. (منتهی الارب ) (از معجم البلدان ).<br></font></div>'),
(184828, 'عقد امان', '<span class=\"hlight\">عقد امان .</span> <font color=\"DarkGreen\"><b>[ ع َ دِ اَ ]</font></b> (ترکیب اضافی، اِ مرکب ) امان نامه . ج، عقود امان . (فرهنگ فارسی معین ).<br></font></div>'),
(184829, 'عقد انامل', '<span class=\"hlight\">عقد انامل .</span> <font color=\"DarkGreen\"><b>[ ع َ دِ اَ م ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) عقد الانامل . یکی از طرق علم عقود، و آن شمارش اعداد است بوسیله ٔ باز کردن و بستن انگشتان دست . (فرهنگ فارسی معین ). نوعی از شمار اعداد که با بندهای انگشتان دستها معمول میدارند. (ناظم الاطباء).نوعی از اسباب شمار مسنون که به اشکال بستن و گشادن انگشتان دست اسماء اعداد ملحوظ دارند و تفصیلش این است که برای واحد، خنصر دست راست باید گرفت، و جهت دو، بنصر را با خنصر ضم کردن، و برای سه، وسطی را نیز، چنانکه در عدد اشیاء بین الناس معهود و متعارف است .ولیکن در این سه عقد باید که رؤوس انامل بسیار نزدیک به اصول اصابع باشد. و برای چهار، خنصر را رفع باید کرد و بنصر و وسطی را معقود گذاشتن، و برای پنج، بنصر را نیز رفع کردن، و بجهت شش، وسطی را رفع کرده فقط بنصر را فرو باید گرفت، چنانکه سر انمله ٔ آن بر وسط کف باشد. و برای هفت، بنصر را هم برداشته خنصر تنها را عقد باید گرفت، چنانکه سرانگشت نیک مایل باشدبجانب نرمه ٔ دست یعنی قریب به منتهای کف به سوی ساعد. و برای هشت، با بنصر همان باید کرد. و برای نه، با وسطی نیز همان باید کرد، باید که در این عقود ثلاثه ٔ اخیر سرهای انگشتان بر طرف کف باشد تا به عقود ثلاثه ٔ اول مشتبه نگردد. و برای ده، سر ناخن سبابه ٔ دست راست را باطن بر مفصل اول انمله ٔ ابهام یعنی نر انگشت باید نهاد، چنانکه فرجه میان این دو انگشت به حلقه ٔ مدور مشابه باشد. و برای بیست، طرف عقد زیرین سبابه که متصل وسطی است بر پشت ناخن ابهام باید نهاد چنانچه پنداری انمله ٔ ابهام را در میان اصول سبابه و وسطی گرفته اند، لیکن وسطی را در دلالت عدد بیست دخلی نباشد، چه اوضاع او برای عقود آحاد متغیر و مبدل گردد و اتصال ناخن ابهام بطرف عقد زیرین سبابه به حال خوددلالت بر بیست کند. و برای سی، ابهام را قائم داشته سر انمله ٔ سبابه بر طرف ناخن او باید نهاد چنانکه وضع سبابه با ابهام شبیه باشد به صورت قوس و روده ٔ آن .و برای چهل، ناخن انمله ٔ ابهام را بر ظهر عقد زیرین سبابه باید نهاد چنانکه میان ابهام و طرف کف هیچ فرجه نماند. و برای پنجاه، سبابه را قائم داشته ابهام را تمام خم باید کرد و بر کف باید نهاد محاذی سبابه .برای شصت، ابهام را خم داده باطن عقده دوم سبابه رابر پشت ناخن ابهام باید نهاد. و برای هفتاد، ابهام را قائم داشته باطن عقده ٔ اول با دوم سبابه بر پشت ناخن ابهام باید نهاد چنانکه پشت ناخن ابهام تمام مکشوف باشد. و برای هشتاد، ابهام را منتصب گذاشته طرف انمله سبابه را بر پشت مفصل انمله ٔ اولی باید نهاد. وبرای نود، سر ناخن سبابه را بر باطن مفصل عقده ٔ دوم ابهام باید نهاد. و باید دانست آنچه در دست راست دلالت بر عقدی از عقود آحاد کند از یکی تا نه، در دست چپ دلالت بر همان عقدی از عقود الوف کند از یکهزار تا نه هزار، و همچنین آنچه در دست راست دلالت بر عقدی از عقود نه گانه ٔ عشرات کند از ده تا نود، در دست چپ دلالت بر همان عقدی از عقود مئات کند از یکصد تا نه صد. بدانکه به اصابع هر دو دست بدان عدد هژده گانه ٔ مذکورةالصدر از یکی تا نه هزارونهصدونودونه ضبط توان کرد، و برای عقد ده هزار، طرف انمله ٔ ابهام را متصل باید ساخت به طرف تمام انمله ٔ سبابه چنانکه سر ناخن ابهام برابر باشد و طرفش به طرف او. (از غیاث اللغات ) (از آنندراج ). در حساب عقود انگشتان، آحاد و عشرات به دست راست و مئات و الوف به دست چپ اختصاص دارد، و این طریقه خاص مردم مشرق زمین است و طریقه ٔ اروپائی عکس آن می باشد یعنی مئات و الوف را بدست راست و آحاد و عشرات را به دست چپ می شمرند. (از تعلیقات دیوان منوچهری چ دبیرسیاقی ص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span>). و رجوع به عقد و عقود شود.<br></font></div>'),
(184830, 'عقد بستن', '<span class=\"hlight\">عقد بستن .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ت َ ]</font></b> (مص مرکب ) گره زدن . (ناظم الاطباء). ورجوع به عقد شود. <BR><font color=\"Blue\">◄</font> صیغه ٔ شرعی خواندن، در معاملات . (فرهنگ فارسی معین ). قرارداد بستن . پیمان بستن <span class=\"hlight\">:</span> قاضی ابوطاهر... با وی ضم کرده شد تا چون نشاط افتد که عهد و عقد بسته آید... قاضی شرایط آن را به تمامی بجای آرد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٠٩</span>).<br>با چنین یار که ما عقد محبت بستیم <br>گر همه مایه زیان می کند انبازی به .<br> <font color=\"Red\">سعدی .</font><br>فکیف مرا که در صدر مروت نشسته و عقد فتوت بسته . (گلستان ). <BR><font color=\"Blue\">◄</font> ازدواج کردن و اجرای صیغه ٔ نکاح کردن . (ناظم الاطباء). پیمان ازدواج بستن . قرارداد زناشویی را منعقد کردن . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>چند گوئی عقد بخت او که بست <br>عقد بختش آسمان بست آسمان .<br> <font color=\"Red\">خاقانی .</font><br>باجوانی چو لعبتی سیمین <br>عقد بستش به مبلغی کابین .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عقد دختر عمو و پسر عمو را در آسمان بسته اند</span> ؛ کابین و بند بستن پسرعم و دختر عم رسمی جاری و نیکوست . (امثال و حکم دهخدا). چون سابقاً معتقد بودند که وصلت باید بین اقوام نزدیک و افراد یک خاندان انجام گیرد و پسر عمو و دختر عمو از تمامی اقوام به یکدیگر نزدیک تر هستند از آنجا این مثل پیدا شد. (فرهنگ عوام ).<br>- <span class=\"hlight\">عقد بر کسی بستن </span> ؛ به صله ٔ بر، به معنی نکاح کردن زن با کسی . (آنندراج ) <span class=\"hlight\">:</span> <br>یکماه روزه داشت پس از اتفاق عید<br>بستند عقد بر همه آفاق یک سرش .<br> <font color=\"Red\">خاقانی .</font><br>گنجهای بکر سر پوشیده را<br>عقد بر صدر جهان بست آسمان .<br> <font color=\"Red\">خاقانی .</font><br>روز را بکر چون برون آید<br>عقد بر شهریار بندد صبح .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عقد فروبستن </span> ؛ عهد بستن . پیمان بستن .<br>- <BR><font color=\"Blue\">◄</font> پیمان ازدواج بستن <span class=\"hlight\">:</span> <br>فتح و ظفر با بقاش عهد فروبسته اند<br>دولت دوشیزه را عقد فروبسته اند.<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">عقد نکاح بستن </span> ؛ صیغه ٔ ازدواج و زناشوئی خواندن . ازدواج کردن <span class=\"hlight\">:</span> فی الجمله به حکم ضرورت با ضریری عقد نکاحش بستند. (گلستان ). چون مدت عدت بسر آمد عقد نکاحش بستند. (گلستان ).<br></font></div>'),
(184831, 'عقد رو', '<span class=\"hlight\">عقد رو.</span> <font color=\"DarkGreen\"><b>[ ع ِ دِ ]</font></b> (ترکیب اضافی، اِ مرکب ) زیب و زیوری چون حلقه ای از گل یا زر و جواهر بر گرد روی . (یادداشت مرحوم دهخدا).<br></font></div>'),
(184832, 'عقد روان', '<span class=\"hlight\">عقد روان .</span> <font color=\"DarkGreen\"><b>[ ع َ دِ رَ ]</font></b> (ترکیب وصفی، اِ مرکب ) نکاح متعه . (غیاث اللغات ). متعه که به مذهب اهل تشیع جایز است، به خلاف اهل سنت و جماعت . عقد نمکین . (آنندراج ) <span class=\"hlight\">:</span> <br>ای شیشه می عقد دهن بسته نشینی <br>با جام مکن عقد روان دختر رز را.<br><font color=\"Red\">میرزا صائب (از آنندراج ).</font><br></font></div>'),
(184833, 'عقد زفاف', '<span class=\"hlight\">عقد زفاف .</span> <font color=\"DarkGreen\"><b>[ ع َ دِ زَ ]</font></b> (ترکیب اضافی، اِ مرکب ) نکاح . (آنندراج ) (غیاث اللغات ) <span class=\"hlight\">:</span> <br>نه ترا عقد زفاف است در این پرده ضرور<br>نه مرا صبر و سکون داده دراین دار خدای .<br><font color=\"Red\">محمد عرفی (از آنندراج ).</font><br></font></div>'),
(184834, 'عقد شدن', '<span class=\"hlight\">عقد شدن .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ُ دَ ]</font></b> (مص مرکب ) به ازدواج کسی درآمدن . به شوی رفتن دختر یا زن .<br></font></div>'),
(184835, 'عقد نماز', '<span class=\"hlight\">عقد نماز.</span> <font color=\"DarkGreen\"><b>[ ع َ دِ ن َ]</font></b> (ترکیب اضافی، اِ مرکب ) تکبیر افتتاح . (شعوری ).<br>- <span class=\"hlight\">عقد نماز بردن </span> ؛ تکبیر افتتاح کردن <span class=\"hlight\">:</span> <br>ز ابرویت چو روآرم به محراب <br>سر زلفت برد عقد نمازم .<br> <font color=\"Red\">کمال خجند (ازآنندراج ).</font><br>- <span class=\"hlight\">عقد نماز بستن </span> ؛ تکبیر افتتاح گفتن <span class=\"hlight\">:</span> <br>شب چو عقد نماز می بندم <br>چه خورد بامداد فرزندم .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(184836, 'عقد نمکین', '<span class=\"hlight\">عقد نمکین .</span> <font color=\"DarkGreen\"><b>[ ع َ دِ ن َ م َ ]</font></b> (ترکیب وصفی، اِ مرکب ) نکاح متعه . (غیاث اللغات ). متعه . (از آنندراج ). عقد روان . و رجوع به عقد روان شود <span class=\"hlight\">:</span> <br>دختر رز که بود چون زن بی مهر حرام <br>من به عقد نمکین از چه حلالش نکنم .<br><font color=\"Red\">ملاطغرا (از آنندراج ).</font><br></font></div>'),
(184837, 'عقد کردن', '<span class=\"hlight\">عقد کردن .</span> <font color=\"DarkGreen\"><b>[ ع َک َ دَ ]</font></b> (مص مرکب ) منعقد کردن <span class=\"hlight\">:</span> بنده از ملامت ترسید و از ایشان محضری خواست، عقد کردند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٤</span>). <BR><font color=\"Blue\">◄</font> ازدواج کردن و زناشوئی نمودن . (ناظم الاطباء). این ترکیب در تداول فارسی زبانان به معنی اجرای صیغه ٔ مزاوجت و نکاح است، و ظاهراًدر اصل، عقد نکاح بوده که در تصرف فارسی زبانان مضاف الیه آن حذف شده است <span class=\"hlight\">:</span> دختر وی را که عقد ونکاح کرده شده باید آورد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٨٣</span>). دختری از آن قدرخان به نام امیر محمد عقد و نکاح کردند.(تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٩٣</span>). چون امیر محمد در بند افتاد وممکن نگشت آن دختر را آوردن و عقد و نکاح تازه می بایست کرد به نام سلطان مسعود. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٩٤</span>).<br>- <span class=\"hlight\">عقد نکاح کردن </span> ؛ صیغه ٔ ازدواج و زناشوئی خواندن . (ناظم الاطباء) <span class=\"hlight\">:</span> این نارسیده را <font color=\"DarkGreen\"><b>[ از دختران امیر یوسف ]</font></b> به نام امیر مسعود کرد <font color=\"DarkGreen\"><b>[ محمود ]</font></b> تا نیازارد و عقد نکاح نکردند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٤٩</span>).<br></font></div>'),
(184838, 'عقدا', '<span class=\"hlight\">عقدا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) یکی از دهستانهای سه گانه ٔ بخش اردکان شهرستان یزد، که محدود است ازشمال به شهرستان نائین، از جنوب به دهستان ندوشن بخش خضرآباد، از مشرق به دهستان اردکان، از مغرب به بخش نائین و خضرآباد. آب مزروعی قراء از قنوات تأمین میشود و محصول عمده ٔ آن غلات و انار است . این دهستان از بیست آبادی بزرگ و کوچک تشکیل شده و جمعیت آن <span class=\"hlight\" dir=\"rtl\">٥٠٥٠</span> تن است . قرای مهم این دهستان عبارتند از: عقدا، مزرعه نو - هفتادر. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(184839, 'عقدالانامل', '<span class=\"hlight\">عقدالانامل .</span> <font color=\"DarkGreen\"><b>[ ع َ دُل ْ اَ م ِ ]</font></b> (ع اِ مرکب ) عقد انامل . (فرهنگ فارسی معین ). رجوع به عقد انامل شود.<br></font></div>'),
(184840, 'عقدان', '<span class=\"hlight\">عقدان .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع اِ) خرمائی است . (منتهی الارب ). نوعی خرما و تمر است . (از اقرب الموارد).<br></font></div>'),
(184841, 'عقدان', '<span class=\"hlight\">عقدان .</span> <font color=\"DarkGreen\"><b>[ ع ُ]</font></b> (اِخ ) لقب فرزدق، بدان جهت که کوتاه قامت بود. (منتهی الارب ) (از اقرب الموارد). و رجوع به فرزدق شود.<br></font></div>'),
(184842, 'عقدانه', '<span class=\"hlight\">عقدانه .</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص نسبی ) منسوب به عقد. (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ مرکب ) هدیه ای که در مجلس عقد به کسی دهند. (ناظم الاطباء).<br></font></div>'),
(184843, 'عقدبستگی', '<span class=\"hlight\">عقدبستگی .</span> <font color=\"DarkGreen\"><b>[ ع َ ب َ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص مرکب ) نُکح . نِکح . (از منتهی الارب ).<br></font></div>'),
(184844, 'عقدبند', '<span class=\"hlight\">عقدبند.</span> <font color=\"DarkGreen\"><b>[ع َ ب َ ]</font></b> (نف مرکب ) که عقد بندد. رجوع به عقد شود.<br></font></div>'),
(184845, 'عقدبند', '<span class=\"hlight\">عقدبند.</span> <font color=\"DarkGreen\"><b>[ ع ِ ب َ ]</font></b> (نف مرکب ) که گلوبند و گردن بند سازد. جواهرساز. گوهری <span class=\"hlight\">:</span> <br>گشته از مشک و لعل اوهمه جای <br>مملکت عقدبند و غالیه سای .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(184846, 'عقدت', '<span class=\"hlight\">عقدت .</span> <font color=\"DarkGreen\"><b>[ ع ُ دَ ]</font></b> (ع اِ) عقدة. عقده . گره . هر چیز مشکل و دشوار. (ناظم الاطباء). رجوع به عقدة و عقده شود.<br></font></div>'),
(184847, 'عقدت گشا', '<span class=\"hlight\">عقدت گشا.</span> <font color=\"DarkGreen\"><b>[ ع ُ دَ گ ُ ]</font></b> (نف مرکب ) عقدت گشاینده . مشکل گشا. عقده گشا. (ناظم الاطباء). و رجوع به عقده گشا شود.<br></font></div>'),
(184848, 'عقدتان', '<span class=\"hlight\">عقدتان .</span> <font color=\"DarkGreen\"><b>[ ع ُ دَ ]</font></b> (ع اِ) تثنیه ٔ عقدة (در حال رفع، و رعایت این قاعده درزبان فارسی نشود). عقدتین . و رجوع به عقدتین شود.<br></font></div>'),
(184849, 'عقدتین', '<span class=\"hlight\">عقدتین .</span> <font color=\"DarkGreen\"><b>[ ع ُ دَ ت َ ]</font></b> (ع اِ) تثنیه ٔ عقدة (در حالت نصب و جر، و در زبان فارسی این قاعده رعایت نشود). عقدتان . و رجوع به عقدة شود. <BR><font color=\"Blue\">◄</font> (اصطلاح نجومی )، عقدة الرأس و عقدة الذنب است . جوزهرتین . دو جوزهر. (یادداشت مرحوم دهخدا). سرو دنب اژدها. (ناظم الاطباء). و رجوع به عقدة شود.<br></font></div>'),
(184850, 'عقدساز', '<span class=\"hlight\">عقدساز.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (نف مرکب ) عقدسازنده . جواهری . (ناظم الاطباء).<br></font></div>'),
(184851, 'عقدنامجه', '<span class=\"hlight\">عقدنامجه .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ <span class=\"hlight\" dir=\"rtl\">/</span> ج ِ ]</font></b> (اِ مرکب ) معرب عقدنامه، و به غلط «عقدنامچه » خوانده شود. (از فرهنگ فارسی معین ). رجوع به عقدنامه و عقدنامچه شود.<br></font></div>'),
(184852, 'عقدنامه', '<span class=\"hlight\">عقدنامه .</span> <font color=\"DarkGreen\"><b>[ع َ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ مرکب ) پیمان نامه . عهدنامه <span class=\"hlight\">:</span> برین قیاس بریشان عقد نامه ها مینوشتند و می نهادند و بر آن گواه میگرفتند، و من از عقدنامه ها نسخه ای یافتم در بعضی از دفاتر قدیمه ٔ عتیقه و آن این است : هذا کتاب لعبداﷲبن جعفرالامام المقتدر باﷲ... (تاریخ قم ص <span class=\"hlight\" dir=\"rtl\">١٤٩</span>). <BR><font color=\"Blue\">◄</font> نامه و قباله ٔ زناشوئی . (ناظم الاطباء). دفتر یا ورقه ای که در آن پیمان ازدواج با مشخصات کامل آن درج میگردد. (فرهنگ فارسی معین ).<br></font></div>'),
(184853, 'عقدنامچه', '<span class=\"hlight\">عقدنامچه .</span> <font color=\"DarkGreen\"><b>[ ع َ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِ مرکب ) عقدنامه وصحیح آن عقدنامجه است که معرب عقدنامه باشد. (از فرهنگ فارسی معین ). رجوع به عقدنامه و عقدنامجه شود.<br></font></div>'),
(184854, 'عقده', '<span class=\"hlight\">عقده .</span> <font color=\"DarkGreen\"><b>[ ع ُ دَ ]</font></b> (ع اِ) عقدة. گره . (ناظم الاطباء) (فرهنگ فارسی معین ). دژک . و رجوع به عقدة شود <span class=\"hlight\">:</span> عقده ٔ الفت و عصمت مستحکم شد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٣٣</span>). عقده ٔ آن مناکحت به استحکام رسانید. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٩٥</span>). آنچه به شمشیر نتوان برید عقده ٔ خویشی است . (مرزبان نامه ).<br>عقده را بگشاده گیر ای منتهی <br>عقده ٔ سخت است بر کیسه ٔ تهی .<br> <font color=\"Red\">مولوی .</font><br>فتادند در عقده ٔ پیچ پیچ <br>که در حل آن ره نبردند هیچ .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">عقده اش ترکید</span> ؛نتوانست دلتنگی خود را پنهان کند. همانند: بغضش ترکیدن . (فرهنگ عوام ).<br>- <span class=\"hlight\">عقده بر ابرو بودن </span> ؛ کنایه از خشمگین بودن، گره بر ابرو زدن <span class=\"hlight\">:</span> <br>آن شاهدی و خشم گرفتن بینش <br>وان عقده بر ابروی ترش شیرینش .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">عقده بر رشته زدن </span> ؛ گره دادن رشته را. (آنندراج ) <span class=\"hlight\">:</span> <br>از تمنا گرهی رشته ٔ عمر تو نداشت <br>تو بر این رشته دو صد عقده ٔ مشکل زده ای .<br> <font color=\"Red\">میرزاصائب (از آنندراج ).</font><br>- <span class=\"hlight\">عقده در کار افتادن و شدن </span> ؛ کنایه از بند شدن کار. (آنندراج ) <span class=\"hlight\">:</span> <br>چنین گر عقده ای در کارم از افلاک خواهد شد<br>سرپا رشته ٔ عمرم گره چون تاک خواهد شد.<br> <font color=\"Red\">ملا مفید بلخی (از آنندراج ).</font><br>- <span class=\"hlight\">عقده در کار زدن </span> ؛ کنایه از بند کردن کار. (آنندراج ) <span class=\"hlight\">:</span> <br>این عقده ٔ مشکل که زد ابروی او در کار من <br>بسیار خواهد کردنی در ناخن تدبیرها.<br> <font color=\"Red\">میرزا صائب (از آنندراج ).</font><br>- <span class=\"hlight\">عقده ٔ دل </span> ؛ غم دل . غصه ٔ درونی . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عقده ٔ دل باز شدن </span> ؛ بر اثر بیان درد دل و گفتن راز درون، آرامش خاطر یافتن . (فرهنگ عوام ).<br> <BR><font color=\"Blue\">◄</font> کنایه از هر چیز مشکل و دشوار. (ناظم الاطباء) (از فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> در اصطلاح پزشکی  توده ٔ سلولی کروی یا بیضوی و یا لوبیایی شکل که در مسیر عروق لنفی یارشته های عصبی قرار دارد. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عقده ٔ عصبی </span> ؛ توده های عصبی کم و بیش بزرگ و کوچک که در مسیر رشته های عصبی به اشکال مختلف هلالی، بیضوی، دوکی شکل و کروی قرار دارند. این عقده ها تجمعی از نورونها می باشند، به همین جهت مراکز کوچک عصبی را در نقاط مختلف از قبیل طرفین ستون فقرات، در مجاورت صفاق و غیره تشکیل میدهند. و چون در امور غیرارادی واردند به آنها عقده های سمپاتیک نیز گویند. (فرهنگ فارس معین ).<br>- <span class=\"hlight\">عقده ٔ گاسر</span> ؛ عقده ای است عصبی و هلالی شکل که الیاف حسی عصب سه قلو از آن مبداء میگیرند. این عقده در روی سطح قدامی فوقانی استخوان خاره در یک فرورفتگی به نام فضای مکل قرار دارد. سطح فوقانی عقده ٔ مذکور مجاور ام الغلیظ (سخت شامه ) و سطح تحتانیش روی استخوان خاره تکیه دارد. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عقده ٔ لنفی </span> ؛ توده های سلولی به اندازه های یک ماش تا یک بادام که در مسیر رگهای لنفی قرار دارند و گاهی هم تبدیل به اعضای بزرگی در درون بدن میشوند مانند طحال . عقده های لنفی اکثر دارای ترشح داخلی نیز میباشند و از این لحاظ به غده های مترشح داخلی شباهت می یابند مانند لوزه ها و طحال . کار اصلی غده های لنفی ساختن گلبولهای سفید یک هسته ای کوچک به نام لنفوسیت یا یک هسته ایهای بزرگ است . دیگر از کارهای عقده های لنفی نگه داشتن میکربها و مواد خارجی است و از این رو به عنوان اعضای دفاعی بدن بشمار میروند. به همین مناسبت است که در صورت شدت عمل و غلبه ٔ میکربها این غده ها متورم و چرکی میشوند و تولید دملهای دردناک داخلی و یا جلدی میکند. غده ٔ لنفی . (فرهنگ فارسی معین ).<br> <BR><font color=\"Blue\">◄</font> (اصطلاح طبی ) در اصطلاح پزشکی  ناراحتیهای روانی و فکری و تألم و رنجهای حاصل از امیال سرکوفته . (فرهنگ فارسی معین ). و رجوع به عقده ٔ روانی در ترکیبات ذیل شود.<br>- <span class=\"hlight\">عقده ٔ حقارت </span> ؛ ناراحتیهای روحی و رنجهایی که بر اثر لطمه خوردنهای متوالی به شخصیت افراد، و مورد حقارت و سخت گیری واقع شدن آنها عارض میگردد. اشخاصی که در طفولیت مورد حقارت و سختگیری واقع شوند در بلوغ ممکن است کسانی کینه توز و یا خجل و گریزان از مردم باشند. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عقده ٔ روانی </span> ؛ ناراحتیها و رنجهای شدید و درونی را گویند که بر اثر عدم ارضای امیال سرکوفته وانجام نشدن آرزوها بر انسان عارض میشوند. (فرهنگ فارسی معین ).<br> <BR><font color=\"Blue\">◄</font> در اصطلاح شعر، بیتی است که بعد هر قسمتی از ترجیع می آید. (کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> (اِخ ) در اصطلاح نجوم و هیئت، محل تقاطع فلک حامل و مایل قمر است . رجوع به عقدةو عقدتین و عقده ٔ ذنب و عقده ٔ رأس شود <span class=\"hlight\">:</span> چون آفتاب وزارت او در عقده ٔ عزلت منکسف شد. (ترجمه ٔتاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٦٤</span>). خورشید رای او در عقده ٔ وساوس به درجه ٔ کسوف رسید. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٠٤</span>).<br>که نتوان راه خسرو را گرفتن <br>نه در عقده مه نو را گرفتن .<br> <font color=\"Red\">نظامی .</font><br>هر عقده ٔ جوزهر که مه راست <br>رمحش به سر سنان گشاید.<br> <font color=\"Red\">خاقانی .</font><br>ای ماه گرفته نور دانش <br>در عقده ٔ اژدهات جویم .<br> <font color=\"Red\">خاقانی .</font><br>شبه در عقده یاقوتی کشیده <br>فرنگی زنگیی را سر بریده .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(184855, 'عقده برداشتن', '<span class=\"hlight\">عقده برداشتن .</span> <font color=\"DarkGreen\"><b>[ ع ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ب َ ت َ ]</font></b> (مص مرکب ) غم یا عقده ٔدل برداشتن . غم و غصه ٔ دل از بین بردن <span class=\"hlight\">:</span> <br>دوشم از خاک لب او به تبسم برداشت <br>یک به یک عقده ام از دل به تکلم برداشت .<br><font color=\"Red\">سنجر کاشی (از آنندراج ).</font><br></font></div>'),
(184856, 'عقده بستن', '<span class=\"hlight\">عقده بستن .</span> <font color=\"DarkGreen\"><b>[ ع ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ب َ ت َ ]</font></b> (مص مرکب ) گره بستن <span class=\"hlight\">:</span> <br>هر عقده که روزگار بندد<br>دست شه کامران گشاید.<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(184857, 'عقده واکردن', '<span class=\"hlight\">عقده واکردن .</span> <font color=\"DarkGreen\"><b>[ ع ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ک َ دَ ]</font></b> (مص مرکب )گشودن گره . <BR><font color=\"Blue\">◄</font> حل مشکل کردن <span class=\"hlight\">:</span> <br>ز هر جانب دل محفل صدا کرد<br>شکست جام عقده ناله واکرد.<br><font color=\"Red\">میرزا محمدزمان راسخ (از آنندراج ).</font><br></font></div>'),
(184858, 'عقده گشا', '<span class=\"hlight\">عقده گشا.</span> <font color=\"DarkGreen\"><b>[ ع ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ گ ُ ]</font></b> (نف مرکب ) عقده گشای . عقده گشاینده . آنکه یا آنچه گرهی را بگشاید. (فرهنگ فارسی معین ). چیزی که بدان عقده گشاده شود، چون ناخن و نوک کارد و مانند آن . (آنندراج ) <span class=\"hlight\">:</span> <br>در عقده کار دل افتد ز روزگار<br>تا از ابروی تو عقده گشا میتوان گرفت .<br> <font color=\"Red\">طالب آملی (از آنندراج ).</font><br><BR><font color=\"Blue\">◄</font> مشکل گشا. (ناظم الاطباء). آنکه مشکلی را حل کند. (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> (اِ مرکب ) در اصطلاح موسیقی، یکی از گوشه های دستگاه شور. (فرهنگ فارسی معین ).<br></font></div>'),
(184859, 'عقده گشادن', '<span class=\"hlight\">عقده گشادن .</span> <font color=\"DarkGreen\"><b>[ ع ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ گ ُ دَ ]</font></b> (مص مرکب ) باز کردن گره . گشودن گره <span class=\"hlight\">:</span> <br>براق برق تک رازین نهادند<br>ز پایش عقده ٔ پروین گشادند.<br> <font color=\"Red\">حکیم زلالی (از آنندراج ).</font><br> <BR><font color=\"Blue\">◄</font> گشادن مشکل <span class=\"hlight\">:</span> <br>عقده ٔ بابلیان را بتوانید گشاد<br>نتوانید که اشکال قدر بگشائید.<br> <font color=\"Red\">خاقانی .</font><br>تا گشاید عقده ٔ اشکال را<br>در حدث کرده ست زرین بال را.<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(184860, 'عقده گشای', '<span class=\"hlight\">عقده گشای .</span> <font color=\"DarkGreen\"><b>[ ع ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ گ ُ ]</font></b> (نف مرکب ) عقده گشا. عقده گشاینده . گشاینده ٔ گره . <BR><font color=\"Blue\">◄</font> مشکل گشا. و رجوع به عقده گشا شود <span class=\"hlight\">:</span> <br>چون دم صبح گشت عقده گشای <br>عود را سوخت خاک صندل سای .<br> <font color=\"Red\">نظامی .</font><br>قسام بهشت و دوزخ آن عقده گشای <br>ما را نگذارد که درآئیم ز پای .<br><font color=\"Red\">حافظ.</font><br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(184861, 'عقده گشایی', '<span class=\"hlight\">عقده گشایی .</span> <font color=\"DarkGreen\"><b>[ ع ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ گ ُ ]</font></b> (حامص مرکب ) گشودن گره . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> حل مشکلات و آشکار نمودن کار مشکل و دشوار. (ناظم الاطباء). مشکل گشائی . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>خاری که در این بادیه بیکار نماید<br>از آبله ٔپای طلب عقده گشائی است .<br><font color=\"Red\">میرزا صائب (از آنندراج ).</font><br></font></div>'),
(184862, 'عقده گشودن', '<span class=\"hlight\">عقده گشودن .</span> <font color=\"DarkGreen\"><b>[ ع ُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ گ ُ دَ ]</font></b> (مص مرکب ) گشودن گره . <BR><font color=\"Blue\">◄</font> مشکل گشودن . حل معضل کردن <span class=\"hlight\">:</span> <br>گر به دل آزاد بودمی چه غمستی <br>عقده ٔ سودا گشودمی چه غمستی .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(184863, 'عقدکنان', '<span class=\"hlight\">عقدکنان .</span> <font color=\"DarkGreen\"><b>[ ع َ ک ُ ]</font></b> (اِ مرکب ) رسم و مجلس خطبه کردن عروسی . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">مجلس عقدکنان </span> ؛ محفل و انجمنی که آنجا عقد نکاح کنند و صیغه ٔ عقد جاری سازند.<br></font></div>'),
(184864, 'عقدی', '<span class=\"hlight\">عقدی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب به عَقد. رجوع به عقد شود. <BR><font color=\"Blue\">◄</font> مقابل صیغه و منقطعه و متعه . (یادداشت مرحوم دهخدا). زن عقدی، در مقابل زن صیغه .<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">مگر شما از عقدی هستید ما از صیغه </span> ؛ دلیلی بر استعلا و برتری جستن بر ما ندارید. (امثال و حکم دهخدا).<br><BR><font color=\"Blue\">◄</font> فرزند که از زن عقدی بود. مقابل فرزند که از صیغه باشد.<br></font></div>'),
(184865, 'عقدی', '<span class=\"hlight\">عقدی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ص نسبی ) منسوب به عقد که بطنی از بجیلة است و گویند آن از قیس بوده است . ابوعامر عبدالملک بن عمرو عقدی بدین نسبت شهرت دارد که محدث بود واز شعبة نقل میکرد. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(184866, 'عقدی', '<span class=\"hlight\">عقدی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ص نسبی ) منسوب به عقدة که آن نام زنی است . و طرماح بن جهم طائی عقدی شاعر بدین نسبت شهرت دارد. و نیز بنی عمروبن سنبس بن معاویةبن جرول بن ثعل بن عمروبن غوث بن طی ٔ، چون مادرشان عقدة دختر مغتربن بولان بوده است بدین نسبت شهرت دارند. (از اللباب فی تهذیب الانساب ). رجوع به عقدة (اِخ ) شود.<br></font></div>'),
(184867, 'عقدی', '<span class=\"hlight\">عقدی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق ُ ]</font></b> (ص نسبی ) منسوب به عقدة که آن لقب پدر ابوالعباس احمدبن محمدبن سعیدبن عبدالرحمان، مشهور به ابن عقده است . وی محدث بود و در محرم سال <span class=\"hlight\" dir=\"rtl\">٢٤٩</span> هَ .ق . متولد شد و در ذیقعده ٔ <span class=\"hlight\" dir=\"rtl\">٣٣٢</span>هَ .ق . درگذشت . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(184868, 'عقدیون', '<span class=\"hlight\">عقدیون .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ دی یو ]</font></b> (اِخ ) منسوبند به دختر مغتربن بولان که نام وی عقدة است و از آن است طرماح . (از منتهی الارب ). رجوع به عقدة و عقدی شود.<br></font></div>'),
(184869, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) از اقلیم چهارم است، کیکاوس کیانی ساخت و بر پشته موضوع است و مصنوع انگور بسیار دارد و شراب بد باشد حقوق دیوانیش بیست وهفت هزاروچهارصد دینار است . (نزهة القلوب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٥</span>). <br></font></div>'),
(184870, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) قلعه ای است به موصل . (از منتهی الارب ). قلعه ای است محکم در کوههای موصل . اهالی آنجا از کردان هستند و آن در شرق موصل قرار دارد و به عقرالحُمَیدیة نیز شهرت دارد. (از معجم البلدان ).<br></font></div>'),
(184871, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ عَقراء. (اقرب الموارد). رجوع به عقراء شود.<br></font></div>'),
(184872, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) قریه ای است در راه بغداد به دسکرة. (از معجم البلدان ).<br></font></div>'),
(184873, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span>ع ُ ]</font></b> (اِخ ) زمینی است به بلاد قیس . (منتهی الارب ). سرزمینی است در عالیة در بلاد قیس . (از معجم البلدان ).<br></font></div>'),
(184874, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) (یوم الَ ...) از ایام عرب است بین مسلمةبن الملک و یزیدبن مهلب، که یزید در این واقعه به قتل رسید. و این عقر، موضعی است در بابل . (از مجمع الامثال میدانی ) (از اقرب الموارد).<br></font></div>'),
(184875, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع مص ) ناگهان ترسناک گشتن، پس قدرت حرکت نماندن . متحیر و سرگشته گردیدن و لرزیدن پای . (از منتهی الارب ). مدهوش شدن . (المصادر زوزنی ) (تاج المصادر بیهقی ). غافلگیر کردن ترس کسی را، و از دست دادن قدرت پس و پیش رفتن، و گویند مبهوت و مدهوش شدن . (از اقرب الموارد).<br></font></div>'),
(184876, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع اِ) آفت و حادثه . (ناظم الاطباء).<br></font></div>'),
(184877, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) قریه ای است از قرای رملة. (از معجم البلدان ).<br></font></div>'),
(184878, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ]</font></b> (ع ص ) مرغ که پرش از آفتی که رسیده نروید. (از اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(184879, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) نازاینده شدن زن . (از منتهی الارب ). عاقر شدن زن . (از اقرب الموارد). عَقر. عَقارة.عِقارة. <BR><font color=\"Blue\">◄</font> زن را به ترک جماع امتحان کردن، که دوشیزه است یا غیر آن . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> برکندن پوست خرمابن و برگرفتن پیه آن را. (ازمنتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سودمندنشدن آخر کار. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184880, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِمص ) عدم حمل . (اقرب الموارد). نازایی . گویند لقحت الناقة عن عقر؛ یعنی پس از نازایندگی آبستن شد. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) کوشک . (منتهی الارب ). قصر. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> فرودگاه قوم . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دنباله ٔ حوض، یا جای آب خوردن ستور از آن . (منتهی الارب ). مؤخر و قسمت انتهایی حوض، آنجا که محل ایستادن شتران است چون بر آب وارد شوند، و گویند محل ایستادن شارب و آب خورنده . (از اقرب الموارد). ج، أعقار. (منتهی الارب ) (اقرب الموارد).<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">اًنما یهدم الحوض من عقره </span>، منظور این است که هر کاری را فقط از راهش باید انجام داد. (از اقرب الموارد).<br> <BR><font color=\"Blue\">◄</font> میانه و معظم آتش و فرودآمدنگاه آن . عُقُر. و رجوع به عُقُر شود. <BR><font color=\"Blue\">◄</font> میان سرای و اصل آن . (منتهی الارب ) (از اقرب الموارد). و «عقر دارالاسلام الشام » را به این معنی دانسته اند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خورش . (منتهی الارب ). طعمه . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> برگزیده و بهترین گیاه . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شکاف میان دو چیزی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> نیکوترین ابیات قصیده . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نیکوترین محل و موضع در خانه . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد که فرزند نشده باشد آن را و بی فرزند. (منتهی الارب ). ابتر، که او رافرزندی نباشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> در اصطلاح فقهی، کابین که به شبهه ٔ وطی یا به وطی غصب واجب شود. و کابین زن . (منتهی الارب ). کابین زن به شبهه ٔفرازآمده . (دهار). صداق زن . (از اقرب الموارد). کابین که به شبهه ٔ وطی واجب شود. و گویند عقر وقتی در مورد زنان آزاد بکار برده شود، منظور مهرالمثل است، وچون درباره ٔ کنیزان استعمال گردد عبارت از عشر قیمت مهرالمثل باشد در صورتی که بکر باشند، و اگر ثیب بوند نیمی از عشر قیمت مهرالمثل منظور دارند. و برخی عقر را مقدار مهرالمثل دانند. و برخی آن را مقدار بدل اجاره دانند زن را برای وطی، اگر استیجار مباح باشد. (از کشاف اصطلاحات الفنون ). و رجوع به تعریفات جرجانی شود.<br>- <span class=\"hlight\">بیضةالعقر</span>؛ بیضه که بدان دوشیزه را بیازمایند وقت دوشیزگی بردن . (منتهی الارب ).<br>- <BR><font color=\"Blue\">◄</font> اول تخم ماکیان ؛ یا تخم پسین آن، یا تخم خروس که در سال یک مرتبه نهد. و نیز این لفظ را در هر چه که نادر بود و عطیه و تحفه که یک بار اتفاق افتد از جایی که امید نداشته باشند و مانند آن استعمال کنند. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184881, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) قریه ای است بین تکریت و موصل، و آن منزلگاه قافله ها است . عقر نخستین محل از حدوداعمال موصل است از جانب عراق . (از معجم البلدان ).<br></font></div>'),
(184882, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) نشانی است مانند شکاف در پای اسب و شتر. <BR><font color=\"Blue\">◄</font> بنیان و اصل هر چیزی . (منتهی الارب ). اصل و اساس خانه . (از اقرب الموارد). بنیاد سرای . (دهار). <BR><font color=\"Blue\">◄</font> فرودآمدنگاه قوم . <BR><font color=\"Blue\">◄</font> هر شکاف مابین دو چیز. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> گشادگی مابین پایهای برجهنده . (منتهی الارب ). گشادگی و فاصله ما بین پایه های مائده و میز غذا. (از اقرب الموارد). گشادگی میان هردو چیز، و برخی آن را خاص فاصله ٔ بین پایه های مائده و میز غذا دانند. (از تاج العروس ). <BR><font color=\"Blue\">◄</font> منزل . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> کوشک و قصر یا کوشک ویران . <BR><font color=\"Blue\">◄</font> ابر پاره ٔ سپید، یا ابر که از پیش آفتاب پیدا شود و بپوشاند چشمه ٔ آفتاب و گرداگرد آنرا، یا ابر که از کرانه ٔ آسمان خیزدو از دور بانگ تندر آن شنیده شود و نمایان نگردد. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بنای بلند. (منتهی الارب ) (از اقرب الموارد) (دهار). <BR><font color=\"Blue\">◄</font> سپید هر چه باشد. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> میان سرای و اصل آن . (منتهی الارب ).<br></font></div>'),
(184883, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) در پی شکار افتادن . <BR><font color=\"Blue\">◄</font> خوردن گیاه را. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نازاینده شدن زن . (از منتهی الارب ). نازاینده شدن . (المصادر زوزنی ) (دهار) (ترجمان القرآن جرجانی ). عاقر و عقیم شدن . (از اقرب الموارد). عُقر. عَقار. عقارة <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ]</font></b> . <BR><font color=\"Blue\">◄</font> خسته کردن . (از منتهی الارب ). ریش کردن . (المصادر زوزنی ) (از تاج المصادر بیهقی ) (ترجمان القرآن جرجانی ).مجروح ساختن . (از اقرب الموارد). و از آن جمله است که در ناسزا گویند «جدعاً له و عقراً». (از منتهی الارب ): جدعاً له و عقراً و حلقاً؛ خداوند مجروح کند تن او را و بدرد آورد گلوی وی را. (از اقرب الموارد).<br>- <span class=\"hlight\">عقراً حلقاً</span> ؛ خداوند او را درد حلق دهاد و تن او ریش و خسته کناد. (یادداشت مرحوم دهخدا).<br> <BR><font color=\"Blue\">◄</font> پی زدن ستور. (از منتهی الارب ). پی کردن . (المصادر زوزنی ) (تاج المصادر بیهقی ) (دهار). پی بریدن . (ترجمان القرآن جرجانی ). قطع کردن چهار دست و پای سگ و اسب و شتر را به شمشیر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بر گور کشتن شتر را. (از منتهی الارب ). شتر کشتن . (المصادر زوزنی ). نحر کردن . (از اقرب الموارد). واز آن جمله است حدیث «لاعقر فی الاسلام ». (از منتهی الارب ).<br>زانکه شیطانش بترساند ز فقر<br>بارگیر صبر را بکشد به عقر.<br> <font color=\"Red\">مولوی .</font><br><BR><font color=\"Blue\">◄</font> سر درخت خرما بریدن . (از منتهی الارب ) (تاج المصادر بیهقی ). قطع کردن همگی سر نخل به وسیله ٔ «جمار» و خشک شدن آن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پشت ریش کردن ستور را. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بریدن درخت هر چه باشد. (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> بریدن و از بین بردن چراگاهها: بنو فلان عقروا مراعی القوم . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بازداشتن از رفتن، گویی پی شتر کسی را بریدن و مانع حرکت او شدن . (از منتهی الارب )(از اقرب الموارد).<br></font></div>'),
(184884, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (ع ص ) سرج عقر؛ زین پشت ریش کن ستور. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> رجل عقر؛مرد خسته کن شتران به مانده کردن . (از منتهی الارب ).<br></font></div>'),
(184885, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ق ق َ ]</font></b> (ع ص، اِ) ج ِ عاقِر. (منتهی الارب ) (اقرب الموارد). رجوع به عاقر شود.<br></font></div>'),
(184886, 'عقر', '<span class=\"hlight\">عقر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ق ُ ]</font></b> (ع ص، اِ) ج ِ عَقور. رجوع به عقور شود. <BR><font color=\"Blue\">◄</font> (اِ) میانه و معظم آتش و فرودآمدنگاه آن . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> جمر و اخگر. (از اقرب الموارد).<br></font></div>'),
(184887, 'عقرالسدن', '<span class=\"hlight\">عقرالسدن .</span> <font color=\"DarkGreen\"><b>[ ع َ رُس ْ س َ دَ ]</font></b> (اِخ ) قریه ای است از قرای شوطة مابین واسط و بصره . و سنان داعی اسماعیلیه از این قریه بوده است . (از معجم البلدان ).<br></font></div>'),
(184888, 'عقران', '<span class=\"hlight\">عقران .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) از اعلام است . (از منتهی الارب ).<br></font></div>'),
(184889, 'عقرب', '<span class=\"hlight\">عقرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ع اِ) کژدم . (منتهی الارب ) (دهار). جانورکی است از هوام، زهردار و انواع آن بسیار است . کنیه ٔ وی ام عِریَط و ام ساهرة است . عقرب بر نر و ماده ٔ آن اطلاق میشود ولی غالباً در ماده بکار میرود و نر آن را عقربان گویند. و ماده را نیز گاهی عقربة نامند. (از اقرب الموارد). به عربی اسم کژدم، و آن شیّاله و جرّاره و الوان می باشد، و آنچه در حین حرکت دنباله را بلند دارد شیاله نامند و آنچه دنباله را کشدجراره، و او از شیاله کوچکتر می باشد. و زبون ترین اقسام او سیاه و پردار است، و بهترین او در مداوا زرد شیاله است . (از تحفه ٔ حکیم مؤمن ). به پارسی کژدم خوانند و به یونانی سقرنیوس . بهترین وی نر بود و نشانه ٔ نر آن بود که ضعیف و لاغر بود و نیش وی سطبر بود، وماده ٔ وی فربه و بزرگ بود و نیش وی باریک بود. (از اختیارات بدیعی ). به پارسی کژدم را گویند و هندوی پنچهو گوید. (از تذکره ٔ ضریر انطاکی ). کژدم . کزدم . کج دم . دم کژ. شبوة. دم کج . رُشک . (لغت محلی شوشتر). ابوفصعل . ام فصعل . ام ساهرة. ام العریط. ام عسان . عتاق الارض . ابونمیلة. ابوعنجل . (مرصع). ج، عَقارب . (اقرب الموارد) (از منتهی الارب ). و رجوع به کژدم شود <span class=\"hlight\">:</span> <br>گرینده بر تو جانوران تا بحد آنک <br>عقرب ز راه نیش و زبانا گریسته .<br> <font color=\"Red\">خاقانی .</font><br>این دو صادق، خرد و رای که میزان دلند<br>بر پی عقرب عصیان شدنم نگذارند. <br> <font color=\"Red\">خاقانی .</font><br>گویند پر ز عقرب طاس زر است حاشا<br>کز حرمتش فلک را عقرب فکند نشتر.<br> <font color=\"Red\">خاقانی .</font><br>چو عقرب دشمنان داری و من با تو چو میزانم <br>برای دشمنان ما ز عقرب سوی میزان آی .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">رقعه ٔ عقرب </span> ؛ یا رقیه ٔ عقرب، رقعه ٔ کژدم . رقعه ای که مغان در اولین روز از پنج روز آخر اسفندماه می نوشتند. رجوع به رقعه ٔ کژدم در ترکیبات رقعه شود.<br>- <span class=\"hlight\">عقرب پریشان </span> ؛ برقعی که خانمها بر روی اندازند. (ناظم الاطباء).<br>- <span class=\"hlight\">عقرب زلف </span> ؛ زلفی چون دم عقرب، شکسته <span class=\"hlight\">:</span> <br>عقرب زلف کجت با قمر قرین است <br>تا قمر درعقرب است کار ما همین است .<br> <font color=\"Red\">شیدا.</font><br>- <span class=\"hlight\">عقرب مه دزد</span> ؛ کنایه از زلف که ماه رخسار خوبان را از نظرها در نقاب دارد <span class=\"hlight\">:</span> <br>عقرب مه دزدشان چشم فلک را به سحر<br>داس سر سنبله در بصر انداخته .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عقرب زده را کرفس دادن </span> !<br> <font color=\"Red\">خاقانی .</font><br> <span class=\"hlight\">نیش عقرب نه از ره کین است </span> <br>اقتضای طبیعتش این است .<br> <font color=\"Red\">سعدی .</font><br> <span class=\"hlight\">من خود از کید عدو باک ندارم لیکن </span> <br>عقرب از خبث طبیعت بزند سنگ به نیش .<br> <font color=\"Red\">سعدی .</font><br> <span class=\"hlight\">در جهنم عقربی هست که از آن پناه به مار میبرند</span> . (امثال و حکم دهخدا).<br> <BR><font color=\"Blue\">◄</font> (اِخ ) در اصطلاح نجومی  برجی از بروج آسمان . (دهار). برجی است در آسمان که قمر درآن فرود آید. (از اقرب الموارد). نام برج هشتم از بروج آسمان، و آن به صورت کژدم است . (غیاث اللغات ). یکی از دو خانه ٔ مریخ است، و خانه ٔ دیگر آن حمل است . (از مفاتیح العلوم ). نام صورتی از صور بروج دوازده گانه ٔ فلکیه و آن برج هشتم است میان میزان و قوس، و اورا بیست ویک کوکب است وخارج از صورت سه کوکب است و از کواکب او قلب العقرب است از قدر اول . (جهان دانش ). صورت و برج هشتمین از صور منطقةالبروج که میان میزان و قوس جای دارد، و مشکل از چهل وچهار ستاره می باشد. یکی از قدر اول (قلب العقرب ) و اکلیل همچنانکه در میزان در این صورت قراردارد. و شولة نیز از ستاره های این صورت است . و بودن آفتاب در این برج به ماه آبان باشد. (یادداشت مرحوم دهخدا).<br>صورت عقرب و کژدمی است در میان آسمان، سر آن در مغرب و دم آن در مشرق و یکی از دو پایش در جنوب و دیگری در شمال است . «غفر» بر سر اوست، و دو «زبانی » که دو کفه ٔ میزان باشند، دو شاخک وی به حساب آیند. دو چشم او دو کوکب خفی است مابین آن و «اکلیل ». «اکلیل » بر صدر اوست، و «قلب » قلب او بشمار آید و «نیاط» قلب دو ستاره ٔ خفی هستند که قلب در وسط آنها است، و خود خارج از آنها به سوی شمال است، «شولة» دم اوست و ستارگانی که در کنار آن است، جبهه ٔ وی میباشد. و «ابرة» و نوک او «لطخه » مستطیلی است بین شولة و «نعائم صادرة». و در آن پنج منزل از منازل قمر است : غفر، زبانین، اکلیل، قلب، شولة. آشکارترین وقتی که صورت عقرب بنظر آید بر «انف » است هنگام غروب، و سه منزل از منازل قمر در آن است : اکلیل، قلب، شولة. (از صبح الاعشی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٤</span>).<br>صورتی است از منطقةالبروج، واقع بین میزان و قوس . اطراف و حوالی عقرب از لحاظ وجود ستارگان خوشه ای و ستارگان ابری شکل مخصوصاً قابل مطالعه است . بر طبق افسانه های یونانی برج عقرب، عقربی بوده که جبار را از قوزک پا گزیده است . جبار صیاد آسمان بوده، که بعد از گزیده شدن مرده است . وقتی که صورت جبار در پاییز نمودار میشود برج عقرب ناپدید میگردد و موقعی که عقرب در اوایل تابستان طلوع می کند جبار قبلاً در زیر قرار گرفته است . بعد از برج عقرب ستون جنوبی کهکشان به چشم میخورد که پهلوی آن برج قوس قرار دارد. این برج از این لحاظ جالب توجه است که در نزدیکی آن دسته های فراوان ستاره های خوشه ای شکل و سحابی قرار گرفته است . اهمیت دیگر آن این است که به عقیده ٔ بعضی از ستاره شناسان زمین، کهکشان و منظومه ٔ شمسی جزو یکی از مجموعه های سحابی شکل اند که محور آن از پهلوی برج قوس میگذرد. مجموعه ٔ ستارگانی که برج قوس را نشان میدهند به شکل کفگیر وارونه ای است و همین علامت مشخص برج قوس است . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>یک رخ تو ماه و آن دگر رخ زهره <br>زهره به عقرب  نهفته ماه به خرچنگ .<br> <font color=\"Red\">ابوطاهر.</font><br>گوشوارش به پناه خم زلف <br>خوشه در سایه ٔ عقرب چه خوش است .<br> <font color=\"Red\">خاقانی .</font><br>عقرب نهند طالع ری من ندانم آن <br>دانم که عقرب تن من شد لقای ری .<br> <font color=\"Red\">خاقانی .</font><br>تا خط نو دمیدش بگریزم از غم او<br>کآنگه سفر نشاید چون مه به عقرب آید.<br> <font color=\"Red\">خاقانی .</font><br>عقرب را برآسمان دل بسوخت . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">١٥٥</span>).<br>فلک را قلب در عقرب دریده <br>اسد را دست برجبهت کشیده .<br> <font color=\"Red\">نظامی .</font><br>اکلیل به قلب تاج داده <br>عقرب به کمان خراج داده .<br> <font color=\"Red\">نظامی .</font><br>نسبت عقربی است با قوسی <br>بخل محمود و بذل فردوسی .<br> <font color=\"Red\">نظامی .</font><br>چو عقرب دشمنان داری و من با تو چو میزانم <br>برای دشمنان ما ز عقرب سوی میزان آی .<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> نام ماه هشتم از ماههای شمسی عرب، و آن ماه دوم خزان است مطابق آبان ماه فارسی و تشرین اول سریانی، و اکتبر فرانسوی . و عقرب سی روز است . (یادداشت مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> (ع اِ) به اصطلاح اکسیریان، اسم گوگرد است .(تحفه ٔ حکیم مؤمن ). <BR><font color=\"Blue\">◄</font> مجازاً به معنی منحوس . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> دوالی است نعل را. (منتهی الارب ). تسمه ای است برای نعل . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دوال که بدان پاردم ستور با زین بندند. (منتهی الارب ) (از اقرب الموارد). پاردم بند. (دهار). <BR><font color=\"Blue\">◄</font> عقربه ٔ ساعت، و آن دو عدد است، عقرب الساعات و عقرب الدقائق . این نام را از جهت تشبیه بر آن گذارده اند. (از اقرب الموارد). و رجوع به عقربه و عقربک شود. <BR><font color=\"Blue\">◄</font> نام نوعی منجنیق باستانی که با وی سنگهای گران افکندندی . (یادداشت مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> (اِخ ) نام اسب عتبةبن رخصة است . (از منتهی الارب ).<br></font></div>'),
(184890, 'عقرب بحری', '<span class=\"hlight\">عقرب بحری .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِ ب َ ]</font></b> (ترکیب وصفی، اِ مرکب ) کژدم دریائی است و آن ماهیی است که بر سر وی خاری بود که بدان بزند و بگزد، و به هندی سینگی مچهلی نامیده میشود. (از الفاظ الادویه ). ماهی صدفی خاردار است و سرش بزرگ و خالی سفید بر آن رسته و نیش آن حیوان است، و گزیدن او باعث سوزش عظیم میگردد. (ازتحفه ٔ حکیم مؤمن ). کژدم دریایی، و آن چون ماهی کوچکی است تیره رنگ که به سرخی زند و بر سر وی خالی سفید بود که بدان میزند و جسم وی خارناک بود و سر وی بزرگتر از بدن وی بود. (از اختیارات بدیعی ). معادل آن اسقوربینوس است به یونانی . (یادداشت مرحوم دهخدا).<br></font></div>'),
(184891, 'عقرب زده', '<span class=\"hlight\">عقرب زده .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ زَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) آنکه عقرب او را گزیده باشد <span class=\"hlight\">:</span> <br>چو از تاب انجم شب تب زده <br>بپیچید چون مار عقرب زده .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(184892, 'عقرب ساعت', '<span class=\"hlight\">عقرب ساعت .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِ ع َ ]</font></b> (ترکیب اضافی، اِ مرکب ) صورت عقربی است که بر آلت نشان دهنده ٔ وقت و ساعت تعبیه کنند. (از آنندراج ) <span class=\"hlight\">:</span> <br>از توکل ز بدان نیست مرا بیم گزند<br>ساعت عقرب من عقرب ساعت باشد.<br><font color=\"Red\">محسن تأثیر (از آنندراج ).</font><br></font></div>'),
(184893, 'عقرب سلیمانی', '<span class=\"hlight\">عقرب سلیمانی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِ س ُ ل َ ]</font></b> (ترکیب وصفی، اِ مرکب ) این ترکیب در آنندراج بدون شرحی آمده وبیت ذیل نیز برای شاهد آن ذکر شده است <span class=\"hlight\">:</span> <br>نعوذ باﷲ از آن افعی زمردفام <br>که طعنه ها زده بر عقرب سلیمانی .<br><font color=\"Red\">طالب آملی (در تعریف تیغ).</font><br></font></div>'),
(184894, 'عقرب نیلوفری', '<span class=\"hlight\">عقرب نیلوفری .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب ِف َ ]</font></b> (اِخ ) کنایه از برج عقرب است و آن برج هشتم باشد از بروج فلکی . (برهان ). کنایه از برج عقرب که خانه ٔ مریخ است . (آنندراج ) (از انجمن آرا) <span class=\"hlight\">:</span> <br>ریخته نوش از دم سیسنبری <br>بر دم این عقرب نیلوفری .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(184895, 'عقربابل', '<span class=\"hlight\">عقربابل .</span> <font color=\"DarkGreen\"><b>[ ع َ رِ ب ِ ]</font></b> (اِخ ) عقر، موضعی است نزدیک کوفه . (منتهی الارب ). قریه ای است در نزدیکی کربلاء از کوفه . و گویند حسین بن علی (ع ) چون به کربلاء رسید و در محاصره ٔ سواران عبیداﷲبن زیاد قرار گرفت نام این قریه را پرسید گفتند آن «عقر» است و او جواب گفت «نعوذباﷲ من العقر». سپس نام سرزمینی را که در آن بودند جویا شد گفتند «کربلاء» است و او در جواب گفت این سرزمین «کرب » و «بلا» باشد. (از معجم البلدان ).<br></font></div>'),
(184896, 'عقربان', '<span class=\"hlight\">عقربان .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِ) دوائی است که آن را حشیةالطحال خوانند. و بعضی گویند دوائی است که آن را به شیرازی زنگی دارو خوانند. و بعضی دیگر گویند بیخ محبر کَبَر رومی است . (برهان ). به لغت اندلس اسقولوفندریون است . (تحفه ٔ حکیم مؤمن ) (فهرست مخزن الادویه ). اسقولوفندریون . (اختیارات بدیعی ). اسقولوفندریون و زنگی دارو. (از الفاظ الادویه ). و رجوع به سقولوفندریون شود.<br></font></div>'),
(184897, 'عقربان', '<span class=\"hlight\">عقربان .</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ رُب ْ با ]</font></b> (ع اِ) کژدم، یا کژدم نر. (منتهی الارب ). عقرب، و گویند نر آن است . و برخی گویند «عقرب » بر نر و ماده اطلاق شود و چون تأکید در تذکیر را خواهند «عقربان » گویند. و برخی عقربان را جانوری دیگر دانند که او را پایهای دراز است و دم او چون دم عقرب نمی باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کرمکی است که در گوش درآید. (منتهی الارب ). جانورکی است که در گوش فرومیرود و آن دراز و زردرنگ است و پایهای بسیاری دارد. (از اقرب الموارد). هزارپا. گوش خزک .<br></font></div>'),
(184898, 'عقربانة', '<span class=\"hlight\">عقربانة.</span> <font color=\"DarkGreen\"><b>[ ع ُ رُ ن َ ]</font></b> (ع اِ) واحد عقربان . یک دانه عقربان . رجوع به عقربان شود. <BR><font color=\"Blue\">◄</font> انه ذوعقربانة؛ او دارای پایداری و ثبات است که مغلوب نمی شود. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> رجل ذوعقربانة؛ مردی با تصوری منیع. (از اقرب الموارد).<br></font></div>'),
(184899, 'عقربة', '<span class=\"hlight\">عقربة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب َ ]</font></b> (ع اِ) مؤنث عقرب . (منتهی الارب ). ماده عقرب . (از اقرب الموارد). رجوع به عقرب شود. <BR><font color=\"Blue\">◄</font> کنیزک نیکوخدمت دانشمند. (منتهی الارب ). کنیز بسیار خدمت کننده و عاقل . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آهنی است مانند کلاب که در زین آویزند. (منتهی الارب ) (از اقرب الموارد). زبانه ٔ لگام . <BR><font color=\"Blue\">◄</font> بند دوال نعلین بر پشت پای . (دهار) دوالی است نعل را. <BR><font color=\"Blue\">◄</font> دوالی که بدان پاردم ستور با زین بندند. (آنندراج ).<br></font></div>'),
(184900, 'عقربة', '<span class=\"hlight\">عقربة.</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب َ ]</font></b> (اِخ ) رمال و ریگهایی است در شرق خریمیة. و آن را آبی از آن بنی اسد نیز دانسته اند. (از معجم البلدان ).<br></font></div>'),
(184901, 'عقربخانه', '<span class=\"hlight\">عقربخانه .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) کنایه از انگشتدان . (از برهان ). کنایه از منقل . (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از سوزن دان . (برهان ). کنایه از کیسه ای که در آن سوزن و امثال آن نگه دارند. (آنندراج ).<br></font></div>'),
(184902, 'عقربه', '<span class=\"hlight\">عقربه .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (از ع، اِ) عقربة. عقربه ٔ ساعت . هر یک از میله های فلزی باریک گردان متصل به چرخها و دستگاههای ساعت که گردش آنها در روی صفحه ٔ ساعت نشان دهنده ٔ ثانیه و دقیقه و ساعت باشد. هر یک از دو میله ٔ باریک بر صفحه ٔ ساعت که یکی دقیقه و دیگری ساعت را نشان می دهد. (یادداشت مرحوم دهخدا). هر یک از میله های باریک فلزی که روی صفحه ٔ ساعت نصب میشودو بدانها ساعتها و دقیقه ها و ثانیه ها را می شمارند، و در معنی عربی «عقرب الساعة» به کار رود. (فرهنگ فارسی معین ). عقربک . عقرب . رجوع به عقرب و عقربک شود.<br>- <span class=\"hlight\">عقربه ٔ ثانیه شمار</span> ؛ عقربه ای که ثانیه ها را نشان می دهد. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عقربه ٔ دقیقه شمار</span> ؛ عقربه ای که دقیقه ها را نشان می دهد. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عقربه ٔ ساعت شمار</span> ؛ عقربه ای که ساعتها را نشان میدهد. (فرهنگ فارسی معین ).<br></font></div>'),
(184903, 'عقربک', '<span class=\"hlight\">عقربک .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ب َ ]</font></b> (اِ مصغر) مصغر عقرب . عقرب خرد. و رجوع به عقرب شود. <BR><font color=\"Blue\">◄</font> قرحه ٔ سخت دردناک که در گوشه ٔ ناخن پدید آید. مرضی در گوشه ٔ ناخن . (یادداشت مرحوم دهخدا). کرمیک . (مهذب الاسماء). کژدمه . کژدمک . گوشه . داحوس . داحس . ناخن پال . ناخن خواره . درد ناخن . خوی درد. نوعی زخم چرکی و عفونی است که دارای ریشه ای سخت و دردناک می باشد. این زخم در سر انگشتان ایجاد میشود و ظاهراً باید ریشه ٔ آن رابه وسیله ٔ عمل جراحی بیرون آورد. پیروان مذهب شیعه معتقدند هر کس در روز عید غدیرخم خیاطی کند شست یا انگشت دیگرش عقربک خواهد شد. (فرهنگ لغات عامیانه ).<br>- <span class=\"hlight\">عقربک شدن </span> ؛ و عقربک درآوردن، مبتلی شدن به عقربک . (فرهنگ لغات عامیانه ).<br><BR><font color=\"Blue\">◄</font> هر یک از سوزن گونه ها که بر سطح صفحه ٔ ساعت است و از حرکت آن، ساعات و دقایق پیدا میشود. (یادداشت مرحوم دهخدا). عقربه . عقرب . و رجوع به عقربه و عقرب شود.<br></font></div>'),
(184904, 'عقربی', '<span class=\"hlight\">عقربی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (ص نسبی ) منسوب به عقرب . رجوع به عقرب شود. <BR><font color=\"Blue\">◄</font> نوعی از لعل، که جوهر مشهور است . (آنندراج ) (غیاث اللغات ).<br></font></div>'),
(184905, 'عقرس', '<span class=\"hlight\">عقرس .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) قبیله ای است به یمن . (منتهی الارب ).<br></font></div>'),
(184906, 'عقرطل', '<span class=\"hlight\">عقرطل .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ طَ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ق ِ طِ ]</font></b>(ع اِ) پیل ماده . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184907, 'عقرقرحا', '<span class=\"hlight\">عقرقرحا.</span><font color=\"DarkGreen\"><b>[ ع َ ق َ ق َ ]</font></b> (معرب، اِ) همان عاقرقرحا است که دارویی است بادافزا. (آنندراج ). رجوع به عاقرقرحا شود.<br></font></div>'),
(184908, 'عقرقس', '<span class=\"hlight\">عقرقس .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ق َ ]</font></b> (اِخ ) وادیی است در بلاد روم، و نام آن در شعر ابوتمام و بحتری آمده است . (از معجم البلدان ).<br></font></div>'),
(184909, 'عقرقوف', '<span class=\"hlight\">عقرقوف .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) اسم مرکب مزجی است از: عقر + قوف . وآن نام قریه ای است از نواحی دجیل و با بغداد چهار فرسنگ فاصله دارد. در کنار آن تلی است خاکی که از پنج فرسنگی چون قلعه ای به نظر می آید و برخی عقیده دارندکه آنجا مقبره ٔ پادشاهان کیانی است . (از معجم البلدان ). و در زمین بابل بنائی عظیم بلند فرمود. <font color=\"DarkGreen\"><b>[ کیکاوس ]</font></b> و آن بنا تل عقرقوف است . (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٤١</span>). تل عقرقوف را کی کاوس ساخت . بعضی او را نمرود شمارند. آن را به سبب آن ساخت که چون ابراهیم (ع ) رادر آتش انداخته بود آنجا بررفت و او را اختیار کرد.از بغداد تا تل عقرقوف سه فرسنگ، آن تل پشته ای سخت بلند است چنانکه در بیابان از پانزده فرسنگ پدید است . از او تا شهر انبار هشت فرسنگ، از آنجا براه بیابان سموات به دمشق به ده روزه میروند، کی بیش صد فرسنگ باشد. (نزهةالقلوب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٩</span> و <span class=\"hlight\" dir=\"rtl\">١٧٢</span>). خرابه هایی است واقع در مغرب بغداد که جغرافی دانان عرب آن را یاد کرده اند و آن را «تل نمرود» نیز نامند. مؤسس آن «کیریگزلو» یکی از پادشاهان بابل است (بین <span class=\"hlight\" dir=\"rtl\">١٥٠٠</span> تا <span class=\"hlight\" dir=\"rtl\">١٠٠٠</span> ق . م .) و آن شهر در قدیم به نام خود آن پادشاه موسوم بوده است . (فرهنگ فارسی معین ). و رجوع به عقر شود.<br></font></div>'),
(184910, 'عقرقوفی', '<span class=\"hlight\">عقرقوفی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ص نسبی ) منسوب به عقرقوف که قریه ای است قدیمی در بغداد. سعدبن زیدبن ودیعةبن عمروبن قیس انصاری خزرجی عقرقوفی بدین نسبت شهرت دارد. وی در عصر خلیفه ٔ دوم به عراق وارد شد و در عقرقوف سکنی گزید. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(184911, 'عقرما', '<span class=\"hlight\">عقرما.</span><font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) عقرماء. (منتهی الارب ). جایگاهی است در یمن . (از معجم البلدان ) (از منتهی الارب ). عقرمی .<br></font></div>'),
(184912, 'عقرمی', '<span class=\"hlight\">عقرمی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ می ی ]</font></b> (اِخ ) موضعی است به یمن . (منتهی الارب ). عقرما. و رجوع به عقرما شود.<br></font></div>'),
(184913, 'عقری', '<span class=\"hlight\">عقری .</span> <font color=\"DarkGreen\"><b>[ ع َ را <span class=\"hlight\" dir=\"rtl\">/</span> ع َ رَن ْ ]</font></b> (ع ص ) زن حایض . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> المراة عقری حلقی ؛یعنی خداوند جسم او را مجروح کند و در گلوی وی درد ایجاد کند، و یا اینکه با بدی خویش قوم خود را زخم میرساند و در گلوی آنها درد ایجاد می کند. آن را مصدر «عقر» و «حلق » دانسته اند لذا صحیح آن را منّون ضبط کرده اند، و برخی آن را صفت دانسته اند و الف آن را برای تأنیث چون سَکری . و نیز رفع آن جایز است بنا بر خبریت برای مبتدای محذوف (هی عقری حلقی ) و نصب آن نیزجایز است بنابر مصدریت . <BR><font color=\"Blue\">◄</font> ج ِ عَقیر. (ازمنتهی الارب ) (از اقرب الموارد). رجوع به عقیر شود.<br></font></div>'),
(184914, 'عقری', '<span class=\"hlight\">عقری .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ص نسبی ) منسوب به عقر که گویا قریه ای است از قرای رملة.ابوجعفر محمدبن احمدبن ابراهیم عقری رملی بدین نسبت شهرت دارد. او محدث بود، و پس از سال <span class=\"hlight\" dir=\"rtl\">٣١٠</span> هَ .ق . درقید حیات بوده است . (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(184915, 'عقری', '<span class=\"hlight\">عقری .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب به عقر که آن قریه ای است بر راه بغداد به دسکرة. ابوالدر لؤلؤبن ابی الکرم بن لؤلؤبن فارس عقری بدین نسبت شهرت دارد. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(184916, 'عقری', '<span class=\"hlight\">عقری .</span> <font color=\"DarkGreen\"><b>[ ع ُ را ]</font></b> (ع اِ) زمین و آب و مانند آن . (منتهی الارب ). ضیعه، چون عَقار. (از اقرب الموارد).<br></font></div>'),
(184917, 'عقز', '<span class=\"hlight\">عقز.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) همدیگر نزدیک رفتن مورچه و مانند آن و با هم نزدیکی آن در رفتار، و فعل آن بکار نرود. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184918, 'عقش', '<span class=\"hlight\">عقش .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) خم دادن چوب را. <BR><font color=\"Blue\">◄</font> فراهم آوردن شتران را. (از اقرب الموارد) (از منتهی الارب ).<br></font></div>'),
(184919, 'عقش', '<span class=\"hlight\">عقش .</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span>ع َ ق َ ]</font></b> (ع اِ) تره ای است . (منتهی الارب ). بقله ای است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سرشاخه های انگور.(منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بار پیلو. (منتهی الارب ). میوه ٔ اراک . (از اقرب الموارد).<br></font></div>'),
(184920, 'عقص', '<span class=\"hlight\">عقص .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص )بافتن موی را و تاب دادن، و از آن جمله است «الخیر معقوص بنواصی الخیل »؛ یعنی نیکی گره خورده و بافته است در پیشانی اسبان . (از منتهی الارب ). تافتن موی . (المصادر زوزنی ) (تاج المصادر بیهقی ). بافتن موی را، و یا تاب دادن آن، و یا پیچاندن آن بر سر. <BR><font color=\"Blue\">◄</font> بستن زن موی خود را در قفای خویش . <BR><font color=\"Blue\">◄</font> پیچاندن و مشوب کردن کار کسی را. (از اقرب الموارد).<br></font></div>'),
(184921, 'عقص', '<span class=\"hlight\">عقص .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع مص ) بدخوی شدن . (از منتهی الارب ). بخیل شدن و بدخوی گشتن . (از اقرب الموارد). بخیلی کردن و بدخو شدن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> پیچان گردانیدن شاخ گوسپند. (منتهی الارب ). «اعقص » بودن تکه و «تیس ». (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> حرون و سرکش شدن چهارپا بر کسی . (از اقرب الموارد).<br></font></div>'),
(184922, 'عقص', '<span class=\"hlight\">عقص .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع مص ) در اصطلاح عروض خرم کردن مفاعلتن معصوب در بحر وافر. (از اقرب الموارد). افکندن میم مفاعلتن بعد ساکن نمودن لامش در بحر وافر. (از منتهی الارب ). اجتماع خرم و عصب و کف باشد، یا بعبارة اخری جمع شدن خرم و نقص است . و نقص عبارت ازکف بعد از عصب می باشد، پس مفاعلتن به عمل نقص مفاعیل گردد، و به عمل خرم فاعیل شود، و چون فاعیل مستعمل نیست بجای او مفعول نهند. (کشاف اصطلاحات الفنون ).<br></font></div>'),
(184923, 'عقص', '<span class=\"hlight\">عقص .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ]</font></b> (ع ص، اِ) ریگ توده ای است برهم نشسته سخت که راه ندارد. <BR><font color=\"Blue\">◄</font> مرد بخیل . <BR><font color=\"Blue\">◄</font> زشتخوی . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گردن شکنبه . (از اقرب الموارد).<br></font></div>'),
(184924, 'عقص', '<span class=\"hlight\">عقص .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ عَقصاء. (اقرب الموارد) (ناظم الاطباء). رجوع به عَقصاء شود. <BR><font color=\"Blue\">◄</font> ج ِ أعقص . (ناظم الاطباء). رجوع به اعقص شود.<br></font></div>'),
(184925, 'عقص', '<span class=\"hlight\">عقص .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق َ ]</font></b> (ع اِ) ج عِقصة. (منتهی الارب ) (اقرب الموارد). رجوع به عقصة شود.<br></font></div>'),
(184926, 'عقص', '<span class=\"hlight\">عقص .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (ع اِ) ج ِ عُقصة. (اقرب الموارد). رجوع به عُقصة شود.<br></font></div>'),
(184927, 'عقص', '<span class=\"hlight\">عقص .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق ُ ]</font></b> (ع اِ) شکنبه . <BR><font color=\"Blue\">◄</font> (ص ) مرد زفت . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) ج ِ عِقاص . (اقرب الموارد). رجوع به عِقاص شود.<br></font></div>'),
(184928, 'عقط', '<span class=\"hlight\">عقط.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) سخت بستن دستار را. (ازمنتهی الارب ). بستن عمامه را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) سخت بستگی دستار. (از منتهی الارب ).<br></font></div>'),
(184929, 'عقعق', '<span class=\"hlight\">عقعق .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (ع اِ) مرغی است ابلق از نوع غراب، آوازش عین قاف است، به فارسی عکه نامندش . حرام است در صحیح مانند غراب . و اگر دماغ آن را بر پنبه طلا کنند و بر زخم تیرنهند پیکان تیر به آسانی بیرون آید. (منتهی الارب ). طائری است سیاه و تیزپرواز، و گویند مرغی است سیاه و سفید که آن را عکه و زاغ دشتی گویند. (غیاث اللغات ).صلصل گویند و عکه نیز خوانند و در پارسی کالنجه گویند. و به شیرازی قالنجه و به پارسی کالیجه گویند. (از اختیارات بدیعی ). به فارسی قالجه و به هندی موکا گویند و آن از طیور معروفه است و از کلاغ ابلق کوچکتر و خوش منظرتر. (از الفاظ الادویة). از طیور معروفه و از کلاغ ابلق کوچکتر و مطبوع تر و به ترکی صعصقان، و دراصفهان غلاجاره ای نامند. (از تحفه ٔ حکیم مؤمن ). پرنده ای است به اندازه ٔ کبوتر و بر شکل غراب، آن را قعقع نیز نامند و عامه ٔ عرب قعق نیز گویند عرب آن را بدیمن میدانند و در سرقت و خیانت و خباثت بدو مثل زنند. (از اقرب الموارد). پرنده ای است از راسته ٔ سبکبالان جزو دسته ٔ دندانی نوکان از تیره ٔ کلاغها، که در اکثر نقاط کره ٔ زمین یافت میشود. این پرنده دارای جثه ٔ متوسط است (تقریباً به اندازه ٔ یک کبوتر) و دمی دراز دارد. رنگ پرهایش سیاه و سفید است . پرهای سیاهش متمایل به بنفش و ارغوانی است و پرنده ای چابک و موذی و مزور و خوراکش دانه و میوه و حشرات و گوشت و تخم مرغان دیگر است . زیر سینه ٔ ماده ٔ آن سفید رنگ است . عقعق بطور کلی پرنده ای است مضر، زیرا تخم پرندگان مفید دیگر را میخورد و نسل آنها را کم می کند. بنابراین از ازدیاد نسل این پرنده باید جلوگیری کرد. بهترین طرز دفع آن شکار با تفنگ یا مسموم کردن طعمه های گوشتی این جانور است . نوک او نسبةً طویل ولی کاملاً قوی است . پنجه هایش بلند و منتهی به ناخن های خمیده است . لانه اش راروی درختان بزرگ نزدیک آبادیها بنا می کند. بسیار زود با انسان مأنوس میشود و زبان صاحبش را درک می کند و گاهی هم برخی صداها را تقلید می کند. (فرهنگ فارسی معین ). شک . کلاژه . کلاچ . (مهذب الاسماء). شمشیر دنبه . (دستوراللغة). کندش . کلاغ پیسه . غلبه . غلپه . کلاچه . قالنجه . کلاغ زاغی . زاغی . زاغچه . کشک . کسک . کندش . کندس . عکعک . کشکرک . قشقره . زاغ پیسه . زاغ دورنگ . زاغ سیاه سفید. کراک . جنگلاهی . (سروری ). چنگلاهی . (سروری ). ج، عَقائق . (دهار) <span class=\"hlight\">:</span> <br>گوشم نشنود لحن بلبل <br>چون گشت سرم به رنگ عقعق .<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(184930, 'عقف', '<span class=\"hlight\">عقف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(ع مص ) خم دادن . (از منتهی الارب ). منعطف ساختن . (از اقرب الموارد). بدو درآوردن . (تاج المصادر بیهقی ).<br></font></div>'),
(184931, 'عقف', '<span class=\"hlight\">عقف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) روباه . (منتهی الارب ). ثعلب . (اقرب الموارد).<br></font></div>'),
(184932, 'عقف', '<span class=\"hlight\">عقف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص، اِ) ج ِ عَقفاء. (از اقرب الموارد). رجوع به عقفاء شود.<br></font></div>'),
(184933, 'عقفان', '<span class=\"hlight\">عقفان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) جد مورچه های سرخ، و جد مورچه های سیاه فارِز باشد. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184934, 'عقفان', '<span class=\"hlight\">عقفان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) جایگاهی است در حجاز. (از معجم البلدان ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> قبیله ای است از خزاعة. (از منتهی الارب ).<br></font></div>'),
(184935, 'عقفانی', '<span class=\"hlight\">عقفانی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ص نسبی ) منسوب به عقفان و آن جایگاهی است در حجاز. حزیمةبن سحوه ٔ عقفانی محدث، از بنی سامةبن لؤی بدین نسبت شهرت دارد. و نیز آن را منسوب به عقفان بن سویدبن خالدبن اسامةبن عنبر که بطنی از یربوع هستند و در کوفه فرود آمدند، دانسته اند. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(184936, 'عقفسة', '<span class=\"hlight\">عقفسة.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ س َ ]</font></b> (ع مص ) بدخوی کردن سپس نیک خویی، گویند ما عقفسه ؛ یعنی کدام چیز است که بد کرد او را سپس نیک خوئی . (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184937, 'عقق', '<span class=\"hlight\">عقق .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع مص ) باردار گردیدن، و باردار نگردیدن، از اضداد است . (از اقرب الموارد) (از منتهی الارب ). عَقاق . عِقاق . رجوع به عقاق شود. <BR><font color=\"Blue\">◄</font> شکافته شدن . (از اقرب الموارد). کفته شدن . (منتهی الارب ).<br></font></div>'),
(184938, 'عقق', '<span class=\"hlight\">عقق .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع اِ) آزارده پدر و مادر. <BR><font color=\"Blue\">◄</font> بار شکم . (منتهی الارب ). حمل . (اقرب الموارد). عَقاق . و رجوع به عقاق شود. <BR><font color=\"Blue\">◄</font> (اِمص ) نافرمانی . <BR><font color=\"Blue\">◄</font> کفتگی . (منتهی الارب ).<br></font></div>'),
(184939, 'عقق', '<span class=\"hlight\">عقق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق َ ]</font></b> (ع اِ) ج ِ عِقّة. (منتهی الارب ) (اقرب الموارد). رجوع به عِقة شود.<br></font></div>'),
(184940, 'عقق', '<span class=\"hlight\">عقق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (ع اِ) برق که میان ابر درخشد. (منتهی الارب ). آنچه از شعاع برق در ابر بماند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آزاردهنده پدر و مادر را و نافرمان . (منتهی الارب ): ولد عقق ؛ به معنی عاق است یعنی فرزندی که نافرمانی پدر خود کند و شفقت و احسان را بر او ترک کند و او را خوار سازد. (از اقرب الموارد): ذُق عقق ؛ جزای کار خود را بچش ؛ ای عاق . (از اقرب الموارد). و رجوع به منتهی الارب شود.<br></font></div>'),
(184941, 'عقق', '<span class=\"hlight\">عقق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق ُ ]</font></b> (ع ص، اِ) ناقه ٔ باردار. ج، عِقاق . <BR><font color=\"Blue\">◄</font> ج ِ عَقوق . (منتهی الارب ). ج ِ عقوق، و جمع آن عِقاق است .(از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بمعنی عُقَق و عاق . رجوع به عُقَق شود. <BR><font color=\"Blue\">◄</font> دشمنان دور. <BR><font color=\"Blue\">◄</font> قطعکنندگان صله ٔ رحم . (از اقرب الموارد).<br></font></div>'),
(184942, 'عقل', '<span class=\"hlight\">عقل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) بندکردن دوا شکم را. (از منتهی الارب ) (از اقرب الموارد). و چنین دارویی را عَقول و شکم را معقول گویند. (ازاقرب الموارد). قبض آوردن دارو شکم را. (دهار) (المصادر زوزنی ). بستن شکم به دارو و جز آن . بند آمدن .<br>- <span class=\"hlight\">عقل بطن </span> ؛ ببستن شکم . بندآوردن اسهال . بند آمدن شکم . حبس بطن . قبض بطن . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">عقل طبیعت </span> ؛ بست کردن شکم . بندآوردن اسهال . (یادداشت مرحوم دهخدا).<br><BR><font color=\"Blue\">◄</font> دریافتن و دانستن، نقیض جهل . (از منتهی الارب ). ادراک . (از اقرب الموارد). خردمند شدن و دریافتن . (المصادرزوزنی ) (دهار) (ترجمان القرآن جرجانی ). مَعقول . و رجوع به معقول شود. <BR><font color=\"Blue\">◄</font> فهمیدن . (از منتهی الارب ). فهمیدن و تدبیر کردن کاری را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> غلبه کردن کسی به عقل . (دهار) (از تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> بستن وظیف و ساق شتر را. (از منتهی الارب ). خم کردن وظیف و ذراع شتر را و بستن آنها را به وسیله ٔ«عقال ». (از اقرب الموارد). بستن زانوی شتر، و لنگ شتر با دست بستن . (دهار). زانوی اشتر ببستن . (المصادر زوزنی ). <BR><font color=\"Blue\">◄</font> دیت بدادن کشته را. (از منتهی الارب ) (از اقرب الموارد). دیه دادن . (دهار). دیت بدادن . (المصادر زوزنی ). <BR><font color=\"Blue\">◄</font> دیت و تاوان پذیرفتن بر خیانت، پس ادا کردن . (از منتهی الارب ). دیت رااز جانب کسی پذیرفتن و آن را پرداختن، در این صورت فعل آن با «عن » متعدی میشود. (از اقرب الموارد). دیه از کسی دادن . (دهار). <BR><font color=\"Blue\">◄</font> ماندن و ترک دادن قصاص را از جهت دیت . (از منتهی الارب ) (از اقرب الموارد). از قصاص دست بداشتن از بهر دیه . (دهار). <BR><font color=\"Blue\">◄</font> پذیرفتن نخل گشنی را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بر کوه برآمدن آهو، پناه جستن به آن . (ازمنتهی الارب ) (از اقرب الموارد). عُقول . و رجوع به عقول شود. <BR><font color=\"Blue\">◄</font> قائم شدن سایه وقت نصف نهار. <BR><font color=\"Blue\">◄</font> پناه جستن به کسی . <BR><font color=\"Blue\">◄</font> خوردن شتر گیاه عاقول را. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> به بند «شغزبیه » بر زمین افکندن کسی را در کشتی . <BR><font color=\"Blue\">◄</font> شانه کردن زن موی را. (از منتهی الارب ) (از اقرب الموارد). عُقول . و رجوع به عقول شود. موی به شانه کردن . (دهار). <BR><font color=\"Blue\">◄</font> دیت را بر همدیگر قسمت نمودن . (از منتهی الارب ).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(184943, 'عقل', '<span class=\"hlight\">عقل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ)خرد و دانش و دریافت یا دریافت صفات اشیاء از حسن وقبح و کمال و نقصان و خیر و شر، یا علم به مطلق امور به سبب قولی که ممیز قبیح از حسن است، یا بسبب معانی و علوم مجتمعه در ذهن که بدان اغراض و مصالح انجام پذیر است، یا به جهت هیئت نیکو در حرکات و کلام که حاصل است انسان را، یا عقل جوهری است لطیف و نوری است روحانی که بدان نفس درک می کند علوم ضروریه و نظریه را و ابتدای وجود آن نور نزدیک اختتان کودک است سپس آن پیوسته تزاید می پذیرد تا آن که به کمال میرسد وقت بلوغ کودک . (منتهی الارب ). نوری است روحانی که نفس به وسیله ٔ آن علوم ضروری و نظری را درمی یابد و گویند آن غریزه ای است که انسان را آماده ٔ فهم خطاب می کند، وآن از عقال و پای بند شتر مأخوذ است . (از اقرب الموارد). خرد و دانش، و آن قوتی است نفس انسان را که بدان تمییز دقایق اشیا کند و آن را نفس ناطقه نیز گویند. و گویند در اصل لغت مصدر است به معنی بند در پا بستن، چون خرد و دانش مانع رفتن طبیعت میشود بسوی افعال ذمیمه لهذا خرد و دانش را عقل گویند. (غیاث اللغات ) (از آنندراج ). جای عقل را قدما در آخر متوسط بطن دماغ دانند، و معانی کلی بدان ادراک شود. (یادداشت مرحوم دهخدا). خرد و دانش و فهم و شعور و دانائی و ادراک و دریافت و هوش و فراست و تدبیر و تمییز و قوه ٔ ممیزه . (ناظم الاطباء). مأخوذ از عقال شتر است و آن ذوی العقول را از عدول از راه راست باز میدارد، و صحیح آن است که عقل جوهری است مجرد که غائبات را به وسیله ٔ وسائط و محسوسات را به وسیله ٔ مشاهده درک می کند، و گویند چیزی است که حقایق اشیاء را دریابد. و جای آن را برخی سر و برخی قلب دانند. (از تعریفات جرجانی ). دوراندیش، بیدار، مصلحت بین، گره گشای، ذوفنون، حیله گر، رنگ آمیز، متین، تمام شیشه، دل، خام، سبک، خام طینت، ناقص، تیره، روشن بین، بلندبازو، از صفات اوست، و با لفظ گسستن مستعمل است . (آنندراج ). ج، عُقول . (منتهی الارب ) (دهار). أحوَر. اُکل . اُکُل . بُذم . جول . حِجا. حِجر. حِجی ̍. خرد. خردمندی . رِداء. رَوبة. روع . زَبر. زَوره . زور. زیر. صَفَر. طَعم . ظرافت . فرزانگی . فهم . کیس . کیاسة. لُب ّ. نباهت . نُهیة <span class=\"hlight\">:</span> <br>نباشد بسر مر ترا عقل و هوش <br>از آن روی کردم ترا ماردوش .<br><font color=\"Red\">فردوسی .</font><br>بیامد از آنجای گوهرفروش <br>ز بیمش روان رفته و عقل و هوش .<br> <font color=\"Red\">فردوسی .</font><br>ندانی ای به عقل اندر خرد کبجه به نادانی <br>که با نرشیر برناید سترون گاو ترخانی .<br> <font color=\"Red\">غضائری رازی .</font><br>عقل و دین آمرت گشت و گشت مأمورت هوا<br>عقل و دین مأمور گردد چون هوا آمرشود.<br> <font color=\"Red\">منوچهری .</font><br>چون از خلیفه این بشنودم عقل ازمن زائل شد. (تاریخ بیهقی ).<br>گر براه این جهان خورشیدمان رهبر شده ست <br>سوی یزدانمان همی مر عقل را رهبر کنی .<br> <font color=\"Red\">ناصرخسرو.</font><br>با عقل نشین و صحبت او کن <br>از عقل کجا جدا شود عاقل .<br> <font color=\"Red\">ناصرخسرو.</font><br>گفتم به حس و عقل توان دید هست را<br>گفتا ز عقل نیست مراندیشه را گذر.<br> <font color=\"Red\">ناصرخسرو.</font><br>عقل چون حلقه از برون در است <br>از صفات خدای بی خبر است .<br> <font color=\"Red\">سنائی .</font><br>عقل در دست یک رمه خودرای <br>چون چراغ است در طهارت جای .<br> <font color=\"Red\">سنائی .</font><br>عقل راهر که با بدی آمیخت <br>لاجرم عقل جست و او آویخت .<br> <font color=\"Red\">سنائی .</font><br>هر که رای ضعیف و عقل سخیف دارد از درجتی عالی به رتبتی خامل گراید. (کلیله و دمنه ). شنیدم آنچه بیان کردی، لیکن به عقل خود رجوع کن . (کلیله و دمنه ). مرد هنرمند... به عقل و مروت خویش پیدا آید. (کلیله و دمنه ).<br>ذات ترا زمانه هم بازشناسد از کسان <br>عقل دم مسیح را فرق کندز دم خر.<br> <font color=\"Red\">مجیر بیلقانی .</font><br>تا کی در چشم عقل خار مغیلان زدن <br>تا کی در راه نفس باغ ارم ساختن .<br> <font color=\"Red\">خاقانی .</font><br>ازعقل همه هوات خواهم <br>وز نفس همه ثنات جویم .<br> <font color=\"Red\">خاقانی .</font><br>زهد را بند آهنین برنه <br>عقل را میل آتشین درکش .<br> <font color=\"Red\">خاقانی .</font><br>عقل با نقش نگاران پریروی چگل <br>نسخه از صورت گرمابه چرا برگیرد.<br> <font color=\"Red\">سیف اسفرنگ .</font><br>عقل باید نورده چون آفتاب <br>تا زند تیغی که نبود جز صواب .<br> <font color=\"Red\">مولوی .</font><br>عقل گوید شش جهت حد است و بیرون راه نیست <br>عشق گوید راه هست و رفته ام من بارها.<br> <font color=\"Red\">مولوی .</font><br>ای که عقلت بر عطارد دق کند<br>عقل و عاقل را قضا احمق کند.<br> <font color=\"Red\">مولوی .</font><br>گر از بسیط زمین عقل منعدم گردد<br>بخود گمان نبرد هیچ کس که نادانم .<br> <font color=\"Red\">سعدی .</font><br>عقل و دولت قرین یکدگر است <br>هر که را عقل نیست دولت نیست .<br> <font color=\"Red\">سعدی .</font><br>عقل دل را به علم بنگارد<br>علم جان را به آسمان آرد.<br> <font color=\"Red\">اوحدی .</font><br>عقل شمع است و علم بیداری <br>نفس خواب و هوس شب تاری .<br> <font color=\"Red\">اوحدی .</font><br>گر سروپیش قد تو سر میکشد مرنج <br>عقل طویل را نبود هیچ اعتبار.<br> <font color=\"Red\">حافظ.</font><br>عقل من بگسست از عشقت، بلی <br>هر چه نامحکم ز محکم بگسلد.<br> <font color=\"Red\">میرحسن دهلوی (از آنندراج ).</font><br>عقل کو جادوگری را دستخوش نابوده به <br>بودنش ننگ گرانی بر رجال و بر نساست .<br> <font color=\"Red\">مرحوم ادیب .</font><br>عقل کو پرورده شد ز میده ٔ هارون <br>کاسه نلیسد ز نیم خورده ٔ هامان .<br> <font color=\"Red\">حاج سیدنصراﷲ تقوی .</font><br>عقل که سراب شد ز مشرع ابلیس <br>زو نترابد زلال چشمه ٔ حیوان .<br> <font color=\"Red\">حاج سیدنصراﷲ تقوی .</font><br>نیک و بد هرکاری سنجیده به میزانیست <br>عقل و هنر و عزمست در ملک مهین میزان .<br> <font color=\"Red\">حاج سید نصراﷲ تقوی .</font><br>عقل و همت را نمیدانم کدامین بهتر است <br>اینقدر دانم که همت هر چه کرد از پیش برد.<br> <font color=\"Red\">(امثال و حکم دهخدا).</font><br>اسهاب، عقل بشولیده شدن از گزند مار. (تاج المصادر بیهقی ).<br>- <span class=\"hlight\">از عقل کردن </span> ؛ با تعقل انجام دادن . از روی تعقل و تفکر کار کردن <span class=\"hlight\">:</span> <br>مریدی به شیخ این سخن نقل کرد<br>اگر راست پرسی نه از عقل کرد.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">باعقل </span> ؛ باخرد. دانا.<br>- <span class=\"hlight\">به عقل ناقص من ...</span> ؛ آن را در مقام فروتنی گویند، یعنی به عقل من . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">بی عقل </span> ؛ دیوانه و نادان . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>آنانکه به دیدار چنین میل ندارند<br>سوگند توان خورد که بی عقل خسانند.<br> <font color=\"Red\">سعدی .</font><br>یکی گفتش ای پیر بی عقل و هوش <br>عجب رستی از قتل، گفتا خموش .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">پریشیده عقل </span> ؛ مدهوش . متحیر <span class=\"hlight\">:</span> <br>پریشیده عقل و پراکنده هوش <br>ز قول نصیحت گر آکنده گوش .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">خلاف عقل </span> ؛ بیهود و بی معنی و خلاف تدبیر. (ناظم الاطباء).<br>- <span class=\"hlight\">در عقل گنجیدن </span> ؛ با عقل تطبیق کردن . با خرد و دانش وفق دادن ؛ در عقل نگنجیدن، با خرد و دانش جور و موافق نبودن <span class=\"hlight\">:</span> <br>در عقل نمی گنجد در وهم نمی آید<br>کز تخم بنی آدم فرزند پری زاید.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">دندان عقل </span> ؛ هر یک از چهار دندان آخر دهان پس از دندانهای آسیا که پس از بلوغ روید و آن را نواجذ نیز گویند. (یادداشت مرحوم دهخدا). سومین آسیای بزرگ که در دوره ٔ پس از بلوغ در فکین میروید. (فرهنگ فارسی معین ). ضرس الحلم . اضراس الحلم . خِرَد دندان . و رجوع به دندان شود.<br>- <span class=\"hlight\">کم عقل </span> ؛ ناقص عقل . کم خرد. نادان .<br>- <span class=\"hlight\">ناقص عقل </span> ؛ کم خرد. نادان <span class=\"hlight\">:</span> <br>پسران وزیر ناقص عقل <br>به گدائی به روستا رفتند.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">برو عقلت را آب بکش </span> ؛ به معنی برو عقلت را عوض کن می باشد. (از فرهنگ عوام ). رجوع به برو عقلت را عوض کن شود.<br> <span class=\"hlight\">برو عقلت را عوض کن </span> ؛ هیچ ندانی . (از امثال و حکم دهخدا). موقعی که کسی موضوعی را بیان کند یا اندرزی دهد که از روی فهم و اطلاع و شعور نباشد بر سبیل استهزاء این اصطلاح مثلی گفته میشود. و گاهی هم گویند برو عقلت را آب بکش . (فرهنگ عوام ).<br> <span class=\"hlight\">خدایا آنکه را عقل دادی چه ندادی </span> ؛ و آنکه را<br> <span class=\"hlight\">عقل ندادی چه دادی </span> . (منسوب به خواجه عبداﷲ انصاری و بزرجمهر).<br> <span class=\"hlight\">عقل آدمیزاد از عقب سرش می آید</span> ؛ نظیر، <br> <span class=\"hlight\">روستائی را عقل از پس میرسد</span> . (امثال و حکم دهخدا از جامع التمثیل ). پس از آنکه در نتیجه ٔ اشتباه یا اشتباهات متعدد زیان دید، آنگاه متوجه غفلت خود می شود و تازه متوجه میشود که بدون تعقل کار کرده است . (از فرهنگ عوام ).<br> <span class=\"hlight\">عقل از سر کسی پریدن </span> ؛ عقل خود را از دست دادن . از شدت تحیر حال جنون پیدا کردن . (از فرهنگ عوام ). و رجوع به ترکیب عقل پریدن در ردیف خود شود.<br> <span class=\"hlight\">عقل از عقل دیگر قوت گیرد</span> .<br> <span class=\"hlight\">عقل قوت گیرد از عقل دگر</span> <br> <span class=\"hlight\">پیشه گر کامل شود از پیشه گر</span> .<br> <font color=\"Red\">مولوی .</font><br> <span class=\"hlight\">عقل به کوچکی و بزرگی نیست </span> ؛ مراد از کوچکی و بزرگی، کمی یا زیادتی سن است . (فرهنگ عوام ).<br> <span class=\"hlight\">عقل ِ جن دارد</span> ؛ بسیار عاقل و تیزهوش و دراک است . (فرهنگ عوام ).<br> <span class=\"hlight\">عقل جن هم به این کار نمی رسد</span> ؛ مشکل لاینحلی است ؛ وقتی کسی مشکل مهمی را حل کند در آن صورت بر سبیل ستایش گویند<br> <span class=\"hlight\">عقل جن هم به آن نمیرسد</span>، و تنها او بود که گره از مشکل این کار گشود. (فرهنگ عوام ).<br> <span class=\"hlight\">عقل چیز دگر و مدرسه چیزی دگر است </span> . (امثال و حکم دهخدا، از مجموعه ٔ امثال فارسی چ هند).<br> <span class=\"hlight\">عقل خودت که این باشه وای به عقل بچه هات </span> ؛ به مزاح، بسی نادانی .(امثال و حکم دهخدا).<br> <span class=\"hlight\">عقل را پیرو لفظ نکنند</span> . (امثال وحکم دهخدا از جامع التمثیل ).<br> <span class=\"hlight\">عقل روستائی از پس میرسد</span> ؛ مانند عقل آدمیزاد از عقب سرش می آید. (فرهنگ عوام ).<br> <span class=\"hlight\">عقلش از پاشنه درآمدن </span> ؛ همانند عقل از سر کسی پریدن . (فرهنگ عوام ). رجوع به عقل از سر کسی پریدن شود.<br> <span class=\"hlight\">عقلش به چشم است </span> ؛ تا به چشم نبیند نداند. (امثال و حکم دهخدا). تا به چشم خودش نبیند درنمی یابد. (فرهنگ عوام ). چشمش هر چه را ببیند پیروی می کند. (فرهنگ عوام ). و رجوع به عقل مردم در چشم آنهاست شود.<br> <span class=\"hlight\">عقلش به کارش میرسد</span> ؛ قادر به انجام و اجرای کار خود هست . (فرهنگ عوام ).<br> <span class=\"hlight\">عقلش پارسنگ میبرد</span> ؛ به مزاح، دیوانه بودن . (از امثال و حکم دهخدا). پارسنگ در اصطلاح اهالی اصفهان، سنگ یا وزنه ٔ دیگری است که وقتی دو کفه ٔ ترازو با هم میزان نباشد در کفه ٔ سبکتر گذارند تا هم سطح شوند، و در اصطلاح عوام به معنی کم عقل بودن یا ناقص بودن عقل کسی است . (فرهنگ عوام ).<br> <span class=\"hlight\">عقلش تا ظهر است </span> ؛ به مزاح و به منظور اینکه کم عقل است گفته میشود. (فرهنگ عوام ).<br> <span class=\"hlight\">عقلش قد ندادن </span> ؛ از حل مشکلی عاجز بودن . (از فرهنگ عوام ).<br> <span class=\"hlight\">عقلش کروی است </span> ؛ به معنی عقلش گرد است . (فرهنگ عوام ). رجوع به عقلش گرد است و<br> <span class=\"hlight\">عقلش پارسنگ میبرد شود</span> .<br> <span class=\"hlight\">عقلش گرد است </span> ؛ سبک عقل و سفیه است . (فرهنگ عوام ). نظیر: عقلش پارسنگ میبرد. (امثال و حکم دهخدا). و رجوع به عقلش پارسنگ میبرد شود.<br> <span class=\"hlight\">عقلش مدور است </span>، نظیر: عقلش گرد است . (امثال و حکم دهخدا). و رجوع به عقلش گرد است و عقلش پارسنگ میبرد شود.<br> <span class=\"hlight\">عقل عقل ترا یاری دهد </span> <span class=\"hlight\">:</span> <br>مشورت ادراک و هشیاری دهد<br>عقلها را عقلها یاری دهد.<br> <font color=\"Red\">مولوی .</font><br> <span class=\"hlight\">عقل کسی را دزدیدن </span> ؛ کسی را فریفتن و تحت نفوذ خود درآوردن . (از فرهنگ عوام ).<br> <span class=\"hlight\">عقل که به چهل روز نیامد به چهل سال هم نمی آید</span> . (فرهنگ عوام ).<br> <span class=\"hlight\">عقل که نیست جان در عذاب است </span> ؛ نادان راه آسان کارها نداند و خود را به سختی اندازد. (امثال و حکم دهخدا).<br> <span class=\"hlight\">عقل مردم در چشم آنهاست </span> ؛ همانند عقلش به چشم است . (فرهنگ عوام ). غالباً مردمان آنچه را ببینند تقلید کنند، یا محاسن چیزی را تا به چشم نبینند درنیابند. (امثال و حکم دهخدا). و رجوع به عقلش به چشم است شود.<br> <span class=\"hlight\">عقل و گهش داخل هم شده </span> ؛ یا مخلوط شده است، در کار خود سخت حیران و سرگردان مانده است . (از فرهنگ عوام ).<br> <span class=\"hlight\">عقل هر چیز بهتر از آدمیزاد است </span> ؛ به مزاح، شما یا او نیک دریافتید، یا خوب رأی دادید. (امثال و حکم دهخدا). به شوخی به کسی گفته میشود که موضوعی را خوب بفهمد و دریابد در حالی که شوخی کننده خوب درنیافته باشد. (فرهنگ عوام ).<br> <span class=\"hlight\">همه کس را عقل خود به کمال نماید و فرزند بجمال </span> . (سعدی ).<br> <BR><font color=\"Blue\">◄</font> در اصطلاحات حکما، به معنی ملک است یعنی یک فرشته از ده فرشتگان که نزد ایشان معین هستند. (از غیاث اللغات ) (از آنندراج ). ملک و فرشته . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> در اصطلاح فلسفی، همان نفس است که در مراتب مختلف به نامهایی مانند عقل بالقوه و بالملکة و بالفعل و بالمستفاد خوانده میشود. (از فرهنگ علوم عقلی ). <BR><font color=\"Blue\">◄</font> در اصطلاح فلسفی، جوهر مستقل بالذات و بالفعل که اساس و پایه ٔ جهان ماوراء طبیعت وعالم روحانیت است، و همان است که در تعریف آن گویندهر جوهر مجرد مستقلی ذاتاً و فعلاً عقل است، و چنین موجودی که ذاتاً و فعلاً مستقل باشد همان عقل به معنی صادر اول و دوم و... است . (از فرهنگ علوم عقلی ). جوهری است مجرد از مادیات که متعلق نباشد به اجسام به تعلق تدبیر و تصرف در آن . (نفائس الفنون ). جوهر مفارقی که متصرف نباشد به تصرف مدبر در اقسام ثلاثه ٔ جوهر، بر خلاف نفس که جوهر مفارق متصرف است در اقسام ثلاثه ٔ جوهر به تصرف مدبر. (یادداشت مرحوم دهخدا). جوهری است مجرد از ماده در ذات خود و مقارن آن، و گویند عقل جوهری است روحانی که خداوند تعالی آن را خاص بدن انسان آفریده است، و گویند عقل نوری است در قلب که حق و باطل را می شناسد، و گویند آن جوهری است مجرد از ماده و متعلق به بدن به تعلق تدبیر و تصرف، و گویند عقل قوه ای است برای نفس ناطقه، و گویند عقل و نفس و ذهن واحد است، جز آنکه عقل را به سبب مدرک بودنش نفس گفته اند و ذهن به جهت استعداد ادراکش، ذهن خوانده شده است . (از تعریفات جرجانی ).<br>- <span class=\"hlight\">عقل اعلی </span> ؛ عقل اول . (فرهنگ علوم عقلی ). رجوع به عقل اول در ردیف خود شود.<br>- <span class=\"hlight\">عقل الهی </span> ؛ مراد ذات حق است . (فرهنگ علوم عقلی ).<br>- <span class=\"hlight\">عقل انسانی </span> ؛ قوه ای است از قوای نفسانی انسان که فعلش تفکر وتدبر و نطق و تمییز و ایجاد صنایع و جز آن است . (فرهنگ فارسی معین ). برای اطلاع از عقیده و نظر فلاسفه ٔ مختلف درباره ٔ عقل انسان رجوع به فرهنگ علوم عقلی شود.<br>- <span class=\"hlight\">عقل اول </span> ؛ نخستین چیزی که از ذات حق تعالی صادر شده است، به اصطلاح مشائیان عقل اول و به اصطلاح اشراقیان نور اول و نور اقرب نامیده میشود. عقل اول باید که بسیط وواحد باشد و آن جوهری است بسیط و روحانی، که صور موجودات در آن گرد آمده است بدون تراکم و تزاحم . (از فرهنگ علوم عقلی، از مجموعه ٔ دوم مصنفات و رسائل اخوان الصفا). و برای اطلاع از عقاید فلاسفه در این مورد به فرهنگ علوم عقلی رجوع شود. و رجوع به ترکیب «عقل اول » ذیل معنی عقل در تصوف شود.<br>- <span class=\"hlight\">عقل بالفعل </span> ؛ عقل بفعل، مرحله ٔ سوم از عقل نظری است و آن از مرحله ٔ هیولانی و بالملکه گذشته، و علاوه بر حصول اولیات نظریات هم برای آن حاصل شده باشد. (از فرهنگ علوم عقلی ). مرحله ای است که نظر به سبب تکرار اکتساب، در قوه ٔ عاقله مخزون شود، آنچنانکه هر گاه اراده کند، ملکه ٔ استحضار برای آن حاصل شود بدون احتیاج به کسب جدید، ولی آن بالفعل مشاهده نشود. (از تعریفات جرجانی ). و رجوع به عقل نظری در همین ترکیبات شود.<br>- <span class=\"hlight\">عقل بالقوة</span> ؛ عقل بقوت، عقل هیولانی است که مرحله ٔ نخست از عقل نظری باشد. رجوع به عقل نظری درهمین ترکیبات شود.<br>- <span class=\"hlight\">عقل بالمستفاد</span> ؛ عقل مستفاد، مرحله ٔ چهارم عقل نظری است که مرتبت حصول تمام علوم نظری و اکتسابی است . رجوع به عقل نظری و عقل مستفاد در همین ترکیبات شود.<br>- <span class=\"hlight\">عقل بالملکه </span> ؛ دومین مرحله از عقل نظری، که از مرحله ٔ هیولانی گذشته باشد. و آن علم است به ضروریات و استعداد نفس به وسیله ٔ آن برای اکتساب نظریات . (از تعریفات جرجانی ). رجوع به عقل نظری در همین ترکیبات شود.<br>- <span class=\"hlight\">عقل بفعل </span> ؛ عقل بالفعل، مرحله ٔ سوم از عقل نظری . رجوع به عقل نظری و عقل بالفعل در همین ترکیبات شود.<br>- <span class=\"hlight\">عقل بقوت </span>؛ عقل بالقوة، عقل هیولانی است که مرحله ٔ نخست از عقل نظری باشد. رجوع به عقل نظری و عقل بالقوة در همین ترکیبات شود.<br>- <span class=\"hlight\">عقل جزوی </span> ؛ غیر از عقل اول، عقول دیگر را جزوی نامند. عقول انسانی را نیز جزوی نامند. (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>عقل جزوی آفتش وهم است و ظن <br>زآنکه در ظلمات شد او را وطن .<br> <font color=\"Red\">مولوی .</font><br>عقل جزوی عقل استخراج نیست <br>جز پذیرای فن و محتاج نیست .<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">عقل خالص </span> ؛عقل غیرمشوب با خیالات و اوهام و قیود مادی است، و آن مرحله ٔ کمال نفس انسانی است که عقل مستفاد است . (از فرهنگ علوم عقلی ). رجوع به عقل نظری در همین ترکیبات شود.<br>- <span class=\"hlight\">عقل دهم </span> ؛ مراد عقل فعال است . رجوع به عقل فعال در ردیف خود شود.<br>- <span class=\"hlight\">عقل عملی </span> ؛ قوه ٔ محرکه ٔ عمل است در انسان و حیوان، در مقابل عقل نظری . عقل عملی دارای مراتبی است که عبارت از تجلیه و تخلیه و فناء فی اﷲ باشد. (از فرهنگ علوم عقلی از دستورالعلماء).<br>- <span class=\"hlight\">عقل غریزی </span> ؛ عقل انسانی است در بدو آفرینش، یعنی قوت تفکر و تعمق و استدلال، و عقل مکتسب مراحل کمال بعدی آن است، و آن را در مقابل عقل مکتسب آرند. (از فرهنگ علوم عقلی از جامع الحکمتین ).<br>- <span class=\"hlight\">عقل فاعل </span> ؛ همان عقل مجرد فعال، و عقل فیاض است که عقول منفعله ٔ انسانی از او استفاضه میکنند. و آن جوهری است منفصل از انسان و غیرقابل فنا و امتزاج با ماده، و تمام عقول از آن مستمد شده اند. (از فرهنگ علوم عقلی از ابن رشد).<br>- <span class=\"hlight\">عقل فعال </span> ؛ قوه ٔالهی که بدان هدایت فرماید هر چیز را در عالم علوی و سفلی از افلاک و کواکب و جماد و حیوان . (از مفاتیح العلوم ). عقل عاشر که فرشته ٔ دهم است، و نزد حکما همه افراد عالم را همون پیدا کرده است، و جبرئیل علیه السلام همین عقل فعال است . (غیاث اللغات ). عقلی که دون آن هیچ دیگر عقل نباشد. (یادداشت مرحوم دهخدا). عقل دهم را فلاسفه عقل فعال نامیده اند، و در زبان شرع روح القدس و جبرئیل نامیده میشود، و آن عقل فعال فیاض است و عقول و نفوس انسانی را از قوت به فعل آرد و واهب الصور و واسطه در فیض است به موجودات عالم کون و فساد. و آن را جوهری بسیط و روحانی و نور محض در غایت تمام و کمال و فضائل دانند، و صور جمیع اشیاء در آن است . عقل فعال عقل دهم و آخرین عقل در سلسله ٔ طولیه است . و آن را عقل فعال نامند از جهت آنکه فائض است بر عالم ناسوت و حاکم بر جهان سفلی است . بنابراین عقل دهم از نظر ما و نسبت به جهان ما عقل فعال است و موجب خروج نفوس و دیگر امور از قوت به فعل است . و برخی عقیده دارند آن را از آن جهت فعال گویند که اولاً ایجادکننده ٔ نفوس بشری و خارج کننده ٔ آنهاست از قوت به فعل . ثانیاً خود از تمام وجوه بالفعل است . ثالثاً موجد و مکون این عالم است و مفیض صور است بر عالم محسوس و دیگر اینکه عقل فعال آخرین مفارقات عقلیه است وآخرین مرتبت کمال نفس ناطقه اتصال به عقل فعال است .و در واقع عقل فعال عقل دهم و کدخدای زمین و عقل منفصل است . (از فرهنگ علوم عقلی ) <span class=\"hlight\">:</span> <br>غواص چه چیز عقل فعال <br>شاینده بعقل یک پیمبر.<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">عقل فیاض </span>؛ همان عقل فعال است که فائض صور موجودات و نفوس جزئیه ٔ انسانیه است و تمام عقول در مرتبه ٔ خود نیز فیاض اند لکن عقل فیاض نسبت به جهان ما همان عقل فعال است . (از فرهنگ علوم عقلی ). و رجوع به عقل فعال در ردیف خود شود.<br>- <span class=\"hlight\">عقل کل </span> ؛ عقل اول . رجوع به عقل کل و عقل اول در ردیف خود شود.<br>- <span class=\"hlight\">عقل کلی </span> ؛ عقل کل . عقل اول . رجوع به عقل کل و عقل کلی و عقل اول در ردیف خود شود.<br>- <span class=\"hlight\">عقل متأثر</span> ؛ مراد عقل منفعل است . رجوع به عقل منفعل در همین ترکیبات شود.<br>- <span class=\"hlight\">عقل متوسط</span> ؛ عقلی که در طرفین او عقل باشد، یعنی همه ٔ عقول عشره به استثنای عقل اول و عقل عاشر. (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">عقل مجرد</span> ؛ یکی از عقول عشره است . (غیاث اللغات ) (آنندراج ). رجوع به عقول عشرة شود.<br>- <span class=\"hlight\">عقل مستفاد</span> ؛ عقل بالمستفاد، مرحله ٔ چهارم نفس انسانی است که مرتبت حصول تمام علوم نظری و اکتسابی است . (از فرهنگ علوم عقلی ). عقلی است که نظریاتی که آنها را درک کرده است نزد او حاضر باشد و از او غایب نشود. (از تعریفات جرجانی ). چون عقل هیولانی از قوه به فعل آید آن را عقل مستفاد نامند. (از مفاتیح العلوم ). و رجوع به عقل نظری در همین ترکیبات شود<span class=\"hlight\">:</span> <br>کون بی تجربت فساد بود<br>تجربت عقل مستفاد بود.<br> <font color=\"Red\">سنائی .</font><br>- <span class=\"hlight\">عقل مضاعف </span> ؛ عقل بالمستفاد را عقل مضاعف هم نامیده اند زیرا هم از ناحیه ٔ عقل فعال کسب فیض می کند و هم از مادون خود یعنی عقل هیولانی و بالملکه و بالفعل و بالاخره حواس ظاهر و باطنه . (از فرهنگ علوم عقلی ).<br>- <span class=\"hlight\">عقل مفارق </span> ؛ مراد از عقل مفارق بطور اطلاق، عقل اول است، و عقول مفارقه عقول طولیه و صوادر اولند و حتی بعضی گویند اسم عقل بطور مطلق اطلاق بر عقول مفارقه شده است . (فرهنگ علوم عقلی از تهافت التهافت ).<br>- <span class=\"hlight\">عقل مکتسب </span> ؛ عقلی است که از راه تعلیم موجود شود، در مقابل عقل غریزی . رجوع به عقل غریزی در همین ترکیبات شود.<br>- <span class=\"hlight\">عقل منفصل </span> ؛ عقل فعال است . رجوع به عقل فعال در ردیف خودشود.<br>- <span class=\"hlight\">عقل منفعل </span> ؛ مراد عقل انسانی است که عقل متأثر نیز نامیده میشود. و آن از عقل عام فاعل مستمد است . (از فرهنگ علوم عقلی ). و رجوع به عقل فاعل در همین ترکیبات شود.<br>- <span class=\"hlight\">عقل نظری </span> ؛ قوه ٔ عالمه است در انسان و آن یکی از دو قوه ٔ اوست، در برابر عقل عملی . و کسانی که نفس را جسمانیةالحدوث و روحانیة البقاء می دانند، عقل نظری را به سه مرحله تقسیم کرده اند: الف - مرحله ٔ عقل هیولانی، که مرحله ٔ قوت محض است، و در آن مرحله قوت عاقله از هر صورت فعلی خالی و عاری است و در همین حال قابل برای ادراکات ممکن است، این مرتبت را عقل هیولانی گویند از جهت تشبه آن به هیولای اولی که قابل برای تلبس و قبول تمام صور است . ب - مرحله ٔ عقل بالملکه، و آن در صورتی است که از مرتبت هیولانی و بالقوه گذشته و بطور کلی از مدرکات عاری نبوده و مدرکاتی برای آن حاصل شده باشد، و او را قدرت و ملکه ٔ انتقال به نشأت عقل بالفعل باشد. ج - مرحله ٔ عقل بالفعل که از مرحله ٔ هیولانی و بالملکه عبور کرده کمال یافته باشد. و علاوه بر حصول اولیات نظریات هم برای آن حاصل شده باشد ولکن آن نظریات کلاً حاضر نزد او نباشد و هر گاه بخواهد به مجرد التفات حاضر شوند. مرحله ٔ دیگری نیز به این سه مرحله افزوده اند و آن مرحله ٔ عقل بالمستفاد است، و آن مرحله ای است که از مرحله ٔ هیولانی و ملکه و فعلی گذشته و به مرحله ای رسیده باشد که برای حصول و حضور معلومات و بالجمله استحضار امور نیازی به توجه و التفات نداشته باشد بلکه تمام نظریات بالفعل نزد او حاصل باشد. عقل مستفاد مرحله ٔ کامل و تام عقل هیولانی است که بر اثر اتصالش به عقل فعال صور تمام اشیاء و موجودات برای او حاضر و حاصل است . (از فرهنگ علوم عقلی ).<br>- <span class=\"hlight\">عقلهای دهگانه </span> ؛ عقول عشرة. رجوع به عقول عشرة شود.<br>- <span class=\"hlight\">عقلهای عالیه </span> ؛ عقول عالیه . عقول طولیه . عقول عشرة. رجوع به عقول عشرة و عقول عالیه شود.<br>- <span class=\"hlight\">عقل هیولانی </span> ؛ مرتبت استعداد محض نفس را برای ادراک معقولات عقل هیولانی می نامندکه قوت محض و عاری از هر نوع فضیلتی است . (فرهنگ علوم عقلی از شرح منظومه ). استعداد محض برای ادراک معقولات، و آن قوه ای است محض و خالی از فعل، آنچنانکه دراطفال است . و علت نسبتش به هیولی این است که نفس دراین مرتبت شباهت به هیولای اولی دارد که در حد ذات خود از جمیع صور خالی است . (از تعریفات جرجانی ). و رجوع به عقل نظری در همین ترکیبات شود.<br> <BR><font color=\"Blue\">◄</font> در اصطلاح عرفا، عقل «ما عبد به الرحمان و اکتسب به الجنان » است، و برخی آن را «آلة العبودیة» دانند، و برخی عقل را «سراج العبودیة» دانند که بدان حق از باطل امتیاز گذارده شود و طاعت از معصیت جدا شود و علم از جهل ممتاز شود. و گویند روح انسان را از جهت تعقل ذات و موجدخود و تعین آن به تعین خاص و مقید کردن آنچه ادراک کند عقل گویند. و بعضی گفته اند «العقل آلة التمییز» که مراد عقل معاش است نه آن مرتبت که فوق قلب است . وبعضی گفته اند «انتهاء العقل الی الحیرة و انتهاء الحیرة الی السکر» که به شهود ربوبیت، سالک عقل خود راگم کند و متحیر شود. و عقل را دو قسم کرده اند، یکی عقل معاش که محل آن سر است و دیگر عقل معاد که محل آن دل است . (از فرهنگ مصطلحات عرفا از اسرار القلوب وشرح گلشن راز و اسرارالتوحید و شرح قیصری و شرح کلمات باباطاهر).<br>- <span class=\"hlight\">عقل اول </span> ؛ کنایه از نور حضرت رسالت پناه محمدی صلوات اﷲعلیه و آله، و کنایه از جبرئیل علیه السلام و روح اعظم و عرش و فلک اول باشد. (برهان ).جبرئیل علیه السلام و عرش را نیز نامند، و نیز اصل و حقیقت انسان را گویند از آن جهت که مفیض و واسطه ٔ ظهور نفس کل است آن را به چهار نام نامیده اند: عقل کل، قلم اول، روح اعظم، ام الکتاب . و از روی حقیقت، آدم صورت عقل کل است و حوا صورت نفس کل . (از آنندراج ). فرشته ٔ اول که از نه فرشته ٔ دیگر پیدا شده و جوهر اول نیز آن را گویند. (از غیاث اللغات ). عقلی که میان او و ذات حق تعالی واسطه ای نباشد. (یادداشت مرحوم دهخدا). مرتبت وحدت است و برخی آن را نور محمدی دانند، وبرخی گویند جبرئیل است و اصل و حقیقت انسان را نیز عقل اول گویند. و آنچه را اهل نظر عقل اول گویند اهل اﷲ روح نامند و از این جهت است که روح القدس بر آن اطلاق شده است . و نسبت عقل اول به عالم کبیر عیناً نسبت روح انسانی است به بدن و قوای او و نفس کلیه قلب عالم کبیر است . (فرهنگ مصطلحات عرفاء به نقل از شرح قیصری و کشاف ) <span class=\"hlight\">:</span> <br>عقل اول راند بر عقل دوم <br>ماهی از سر گنده گردد نی ز دم .<br> <font color=\"Red\">مولوی .</font><br>و رجوع به ترکیب «عقل اول »ذیل عقل در معنی فلسفی آن شود.<br>- <span class=\"hlight\">عقل ایمانی </span> ؛ در اصطلاح تصوف، نیرویی که انسان را از مناهی و معاصی باز میدارد. (فرهنگ فارسی معین ).<br><BR><font color=\"Blue\">◄</font> در اصطلاح علم رمل، باد است، و باد اول را عقل اول نامند تا باد عتمه ٔ داخل را عقل هفتم نامند به ترتیب وضع جدول ادوار در طالب و مطلوب . (از کشاف اصطلاحات الفنون ). <BR><font color=\"Blue\">◄</font> (مص ) در اصطلاح عروض، نوعی از تصرفات شعر، و آن افکندن یای مفاعیلن باشد. (منتهی الارب ). حذف حرف پنجم «مفاعلتن » که لام باشد، و آن را در این صورت «معقول » گویند. (از اقرب الموارد). حذف حرف پنجم متحرک مفاعلتن که لام باشد، در نتیجه مفاعتن می ماند و به مفاعلن تبدیل میشود و آن را در این صورت معقول گویند. (از تعریفات جرجانی ). اسقاط حرف پنجم است پس از عصب، و گویند عقل ساقط کردن تاء است از مفاعلتن . (از کشاف اصطلاحات الفنون ). این تصرّف مخصوص بحر وافر است . <BR><font color=\"Blue\">◄</font> (اِ) دیت . (منتهی الارب ) (اقرب الموارد). خون بها. (دهار). <BR><font color=\"Blue\">◄</font> پناه . (منتهی الارب ). پناهگاه .(دهار). <BR><font color=\"Blue\">◄</font> قلعه . <BR><font color=\"Blue\">◄</font> دل . (منتهی الارب ). قلب . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> جای پناه . <BR><font color=\"Blue\">◄</font> جامه ٔ سرخ که بر هودج اندازند، یا نوعی از نگار جامه، و گویند آن است که نقش آن در طول و درازا باشد. (از منتهی الارب ). جامه ای است سرخ رنگ که بر هودج افکنند، و یا نوعی از نگار جامه است که نقش آن در طول باشد، و آنچه نقش آن مستدیر باشد «رقم » است . و گویند آنها دو نوع از بُرد هستند. (از اقرب الموارد). جامه ٔ سرخ . (دهار). <BR><font color=\"Blue\">◄</font> انقلاب رحم، که علتی است در رحم . (از ذخیره ٔ خوارزمشاهی ). رجوع به انقلاب رحم شود.<br></font></div>'),
(184944, 'عقل', '<span class=\"hlight\">عقل .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع مص ) «أعقل » بودن شتر. (از اقرب الموارد). رجوع به اعقل و عَقَل در معنی اسمی شود.<br></font></div>'),
(184945, 'عقل', '<span class=\"hlight\">عقل .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع اِمص ) برتافتگی پای شتر و بر همدیگر خوردن زانوی آن . (از منتهی الارب ). اصطکاک دو زانو، یا پیچیدگی در پای، و گشادگی عرقوب بزرگ و آن ناپسند است . (از اقرب الموارد).<br></font></div>'),
(184946, 'عقل', '<span class=\"hlight\">عقل .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق ُ ]</font></b> (ع اِ) ج ِ عِقال . (منتهی الارب ) (اقرب الموارد). رجوع به عقال شود.<br></font></div>'),
(184947, 'عقل', '<span class=\"hlight\">عقل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام کوهی است . (منتهی الارب ). نام قلعه ای است در تهامة. (از معجم البلدان ).<br></font></div>'),
(184948, 'عقل', '<span class=\"hlight\">عقل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) لقب سعیدبن فاضل بن بشارة. به سال <span class=\"hlight\" dir=\"rtl\">١٣٠٦</span> هَ . ق . در دامور (لبنان ) متولد شد و به هیجده سالگی به مکزیک رفت و روزنامه ٔ «صدی المکسیک » را انتشار داد. آنگاه به بیروت بازگشت و روزنامه ٔ «البیرق » را منتشر ساخت سپس در نوشتن مطالب روزنامه های الاحوال و لسان الحال و الاصلاح و الاتحاد العثمانی که همگی از روزنامه های مهم بیروت بشمار می آیند شرکت نمود. وی در جنگ جهانی اول به اتهام کوشش برای تشکیل دولت مستقل عربی بازداشت شد و به سال <span class=\"hlight\" dir=\"rtl\">١٣٣٤</span>هَ . ق . در بیروت اعدام گردید. (از الاعلام زرکلی ).<br></font></div>'),
(184949, 'عقل', '<span class=\"hlight\">عقل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) لقب ودیعبن سدیدبن بشاره ٔ فاضل . از روزنامه نگاران و شاعران معاصر لبنان (<span class=\"hlight\" dir=\"rtl\">١٢٩٩</span>- <span class=\"hlight\" dir=\"rtl\">١٣٥٢</span> هَ .ق .). رجوع به الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٩</span> شود.<br></font></div>'),
(184950, 'عقل افزا', '<span class=\"hlight\">عقل افزا.</span> <font color=\"DarkGreen\"><b>[ ع َ اَ ]</font></b> (نف مرکب ) عقل افزاینده . افزاینده ٔ خرد و هوش <span class=\"hlight\">:</span> <br>ای بخاراعقل افزا بوده ای <br>لیکن از من عقل و دین بربوده ای .<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(184951, 'عقل اول', '<span class=\"hlight\">عقل اول .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ اَوْ وَ ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به ترکیب «عقل اول » در معنی فلسفی و در معنی تصوف عقل شود.<br></font></div>'),
(184952, 'عقل حادی عشر', '<span class=\"hlight\">عقل حادی عشر.</span><font color=\"DarkGreen\"><b>[ ع َ ل ِ ع َ ش َ ]</font></b> (ترکیب وصفی، اِ مرکب ) عقل یازدهم . <BR><font color=\"Blue\">◄</font> (اِخ ) و آن لقبی است که حکما به خواجه نصیرالدین طوسی داده اند. و رجوع به حادی عشر شود.<br></font></div>'),
(184953, 'عقل داشتن', '<span class=\"hlight\">عقل داشتن .</span> <font color=\"DarkGreen\"><b>[ ع َ ت َ ]</font></b> (مص مرکب ) خردمند بودن . بهوش بودن . عاقل بودن <span class=\"hlight\">:</span> <br>تا عقل داشتم نگرفتم طریق عشق <br>جایی دلم برفت که حیران شود عقول .<br> <font color=\"Red\">سعدی .</font><br>یکی گفت هیچ این پسر عقل و هوش <br>ندارد، بمالش به تعلیم گوش .<br> <font color=\"Red\">سعدی .</font><br>متحیر نه در جمال توام <br>عقل دارم بقدر خود قدری .<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(184954, 'عقل دزد', '<span class=\"hlight\">عقل دزد.</span> <font color=\"DarkGreen\"><b>[ ع َ دُ ]</font></b> (نف مرکب ) آنکه عقل را دزدد. آنکه یا آنچه خرد را برباید. عقل ربا <span class=\"hlight\">:</span> <br>وان می عقل دزد هم نقب زند سرای غم <br>لاجرمش صفیر خوش چنگ سرای نو زند.<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(184955, 'عقل ربا', '<span class=\"hlight\">عقل ربا.</span> <font color=\"DarkGreen\"><b>[ ع َ رُ ]</font></b> (نف مرکب ) عقل رباینده . زداینده ٔ عقل . مُذهب العقول .<br></font></div>'),
(184956, 'عقل رس', '<span class=\"hlight\">عقل رس .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (نف مرکب ) عقل رسنده . به سن تمییز رسیده .<br>- <span class=\"hlight\">عقل رس شدن </span> ؛ در تداول خانگی، به سنی که تمییز نیک از بد توان کردن رسیدن . به سنی بالغ شدن که عقل بر او حکومت کند. به درجه ٔ مردی یا زنی رسیدن . به سن رشد و تمییز رسیدن . رشد و تمییز بواسطه ٔ مراهقت یا بلوغ یافتن . (یادداشت مرحوم دهخدا).<br></font></div>'),
(184957, 'عقل رفته', '<span class=\"hlight\">عقل رفته .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف مرکب ) بی خرد و بی عقل . (ناظم الاطباء). سَباه . ممتله العقل . مهتلس . مهلوس . منتخب . نخیب . (از منتهی الارب ).<br></font></div>'),
(184958, 'عقل رفتگی', '<span class=\"hlight\">عقل رفتگی .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (حامص مرکب ) خرافت و بی عقلی . (ناظم الاطباء): کلاب ؛ عقل رفتگی از دیوانگی . (منتهی الارب ).<br></font></div>'),
(184959, 'عقل فعال', '<span class=\"hlight\">عقل فعال .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ ف َع ْ عا ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به ترکیب «عقل فعال » ذیل عقل شود.<br></font></div>'),
(184960, 'عقل معاش', '<span class=\"hlight\">عقل معاش .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ م َ ]</font></b> (ترکیب اضافی، اِ مرکب ) قوه ٔ تدبیر زندگانی . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>دام دیوانگی فروکرده <br>تا بدام اوفتاده عقل معاش .<br><font color=\"Red\">عطار.</font><br></font></div>'),
(184961, 'عقل پذیر', '<span class=\"hlight\">عقل پذیر.</span> <font color=\"DarkGreen\"><b>[ ع َ پ َ ]</font></b> (ن مف مرکب ) عقل پذیرنده . آنچه عقل آن را بپذیرد <span class=\"hlight\">:</span> این معنی عقل پذیر نیست، یعنی عقل از قبول معنی آن ابا دارد. (یادداشت مرحوم دهخدا).<br></font></div>'),
(184962, 'عقل پریدن', '<span class=\"hlight\">عقل پریدن .</span> <font color=\"DarkGreen\"><b>[ ع َ پ َ دَ ]</font></b> (مص مرکب ) زایل شدن عقل . از بین رفتن خرد <span class=\"hlight\">:</span> <br>اینقدر عقلی که داری گم شود<br>سر که عقل از وی بپرد دم شود.<br> <font color=\"Red\">مولوی .</font><br>و رجوع به مثل «عقل از سر کسی پریدن » در ذیل عقل شود.<br></font></div>'),
(184963, 'عقل کاژ', '<span class=\"hlight\">عقل کاژ.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص مرکب ) کژعقل . که کژبین باشد <span class=\"hlight\">:</span> <br>آن خبیث از شیخ می لائید ژاژ<br>کژنگر باشد همیشه عقل کاژ.<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(184964, 'عقل کل', '<span class=\"hlight\">عقل کل .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ ک ُل ل ]</font></b> (ترکیب اضافی، اِ مرکب ) به معنی عقل اول است که کنایه از نور محمدی و جبرئیل و روح و عرش عظیم باشد. (برهان ) (غیاث ). عقل اول از عقول عشره ٔ مشائیین . علت اولی . (یادداشت مرحوم دهخدا). رجوع به عقل اول شود <span class=\"hlight\">:</span> <br>ای سایه ٔ حق که عقل کل را<br>زاخلاق تو دایگان ببینم .<br> <font color=\"Red\">خاقانی .</font><br>این سخن هائی کی از عقل کل است <br>بوی آن گلزار و سروسنبل است .<br> <font color=\"Red\">مولوی .</font><br>عقل کل را آبگینه ریزه در پای اوفتاد<br>بس که سنگ تجربت بر طاق مینائی زدم .<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> در اصطلاح علم رمل، عقل کل و عقل فقط به معنی طریق است که آن نیز از مصطلحات رمل است . (از کشاف اصطلاحات الفنون ). و رجوع به طریق شود.<br></font></div>'),
(184965, 'عقل کلی', '<span class=\"hlight\">عقل کلی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ ک ُل ْ لی ]</font></b> (ترکیب وصفی، اِ مرکب ) عقل کل . (غیاث اللغات ) (آنندراج ). رجوع به عقل کل و عقل اول شود <span class=\"hlight\">:</span> <br>عقل کلی که از تو یافته راه <br>هم ز هیبت نکرده در تو نگاه .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(184966, 'عقل گداز', '<span class=\"hlight\">عقل گداز.</span> <font color=\"DarkGreen\"><b>[ ع َ گ ُ ]</font></b> (نف مرکب ) عقل گدازنده . گدازنده ٔ خرد. عقل ربا <span class=\"hlight\">:</span> <br>به غمزه عقل گدازی، به چنگ چنگ نوازی <br>به وعده روبه بازی، به عشوه شیرشکاری .<br><font color=\"Red\">ابوالفرج رونی .</font><br></font></div>'),
(184967, 'عقل گزین', '<span class=\"hlight\">عقل گزین .</span> <font color=\"DarkGreen\"><b>[ ع َ گ ُ ]</font></b> (ن مف مرکب )چیزی که پسندیده ٔ عقل باشد. (آنندراج ) <span class=\"hlight\">:</span> <br>خدایگان صفتی کش خدای داد بهم <br>سه چیز روح فزا و سه چیز عقل گزین .<br><font color=\"Red\">میرمعزی (از آنندراج ).</font><br></font></div>'),
(184968, 'عقلا', '<span class=\"hlight\">عقلا.</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (ع ص، اِ) عقلاء. ج ِ عاقل . خردمندان . مردمان عاقل و خردمند و هوشیار. (ناظم الاطباء). رجوع به عقلاء و عاقل شود <span class=\"hlight\">:</span> <br>سخن رسول دل و جان تست اگرخوب است <br>خبر دهد عقلا را که جانت محترم است .<br> <font color=\"Red\">ناصرخسرو.</font><br>موسی زمان راتو یکی شهره عصائی <br>بشناسند آنانکه عصای عقلااند.<br> <font color=\"Red\">ناصرخسرو.</font><br>من آن نیم که پذیرم نصیحت عقلا<br>پدر بگوی که من بی حساب فرزندم .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">عقلای سبعه </span> ؛ حکمای سبعه . خردمندان هفتگانه . نام هفت تن خردمند معروف یونان باستان . رجوع به حکمای سبعه شود.<br></font></div>'),
(184969, 'عقلانه', '<span class=\"hlight\">عقلانه .</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص نسبی، ق مرکب ) از روی عقل و خردمندی و هوشیاری . (ناظم الاطباء).<br></font></div>'),
(184970, 'عقلانی', '<span class=\"hlight\">عقلانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب به عقل . عقلی <span class=\"hlight\">:</span> <br>شخص انسان را ز حق یک نور عقلانی عطاست <br>روح ده دانست که اعضا برنتابد بیش از این .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(184971, 'عقلة', '<span class=\"hlight\">عقلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع اِمص ) بند آمدن زبان از سخن . (از اقرب الموارد).<br></font></div>'),
(184972, 'عقلة', '<span class=\"hlight\">عقلة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ]</font></b> (ع اِ) شکلی است از اشکال رمل . (از کشاف اصطلاحات الفنون ) (از منتهی الارب ). شکلی است منحوس از اشکال رمل . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> بندی است از بندهای کشتی . (منتهی الارب ):لفلان عقلة یعقل بها الناس ؛ هرگاه با مردم کشتی میگیرد پایهای آنان را می بندد و آن همان شغزبیه است . (ازاقرب الموارد) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> آنچه بدان بسته شود چون قید یا عقال . (از اقرب الموارد).<br></font></div>'),
(184973, 'عقلمند', '<span class=\"hlight\">عقلمند.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ص مرکب ) در تداول خانگی، صاحب عقل .(یادداشت مرحوم دهخدا). خردمند و هوشمند و دانا و عاقل . (ناظم الاطباء) <span class=\"hlight\">:</span> بچه وقتی عقلمند شد باید او را به مکتب فرستاد. (یادداشت مرحوم دهخدا).<br></font></div>'),
(184974, 'عقلمندی', '<span class=\"hlight\">عقلمندی .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (حامص مرکب ) خردمندی . (از آنندراج ). و رجوع به عقلمند شود.<br></font></div>'),
(184975, 'عقلی', '<span class=\"hlight\">عقلی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب به عقل . هر امری که حس باطن را در آن مدخلیتی نباشد، آن را عقلی نامند، و این معنی بنا بر قول مشهور باشد. و گاه اطلاق شود بر چیزی که آن چیز و یا ماده ٔ آن به تمامی به یکی از حواس ظاهره ادراک نشود خواه جزئی از ماده ٔ آن چیز ادراک شده یا نشده باشد. (از کشاف اصطلاحات الفنون ). مقابل حسی . و رجوع به عقل شود <span class=\"hlight\">:</span> <br>نظر تیره در این راه نداند سر خویش <br>ورچه رهبر بسوی عالم عقلی نظر است .<br> <font color=\"Red\">ناصرخسرو.</font><br>بحث عقلی گر در و مرجان بود<br>آن دگر باشد که بحث جان بود.<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">دلیل و حجت عقلی </span> ؛ برهانی که مبنای آن بر استدلال عقلی باشد، در مقابل دلیل نقلی . (از فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>ظاهری راحجت از ظاهر برم <br>پیش عاقل حجت عقلی برم .<br><font color=\"Red\">ناصرخسرو.</font><br></font></div>'),
(184976, 'عقلیات', '<span class=\"hlight\">عقلیات .</span> <font color=\"DarkGreen\"><b>[ ع َ لی یا ]</font></b> (ع اِ مرکب ) ج ِ عقلیّة. رجوع به عقلیة شود. <BR><font color=\"Blue\">◄</font> علوم عقلیه . (فرهنگ فارسی معین ). در مقابل سمعیات است و در مقابل شرعیات نقلیه است مانند اعتقاد به عدل، توحید، نبوت، و بالجمله اصول دین و مسائل فلسفی و کلامی . (فرهنگ علوم نقلی از خزائن ص <span class=\"hlight\" dir=\"rtl\">٥</span> و موافقات ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٠</span>).<br></font></div>'),
(184977, 'عقلیة', '<span class=\"hlight\">عقلیة.</span> <font color=\"DarkGreen\"><b>[ ع َ لی ی َ ]</font></b> (ع ص نسبی ) مؤنث عقلی . منسوب به عقل . رجوع به عقل و عقلی شود. <BR><font color=\"Blue\">◄</font> علوم عقلیه . (فرهنگ فارسی معین ).<br></font></div>'),
(184978, 'عقم', '<span class=\"hlight\">عقم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) خشک گردیدن پیوندها. (از منتهی الارب ). خشک شدن مفاصل .و فعل آن مجهول بکار رود. (از اقرب الموارد). حدیث تعقم اصلاب المشرکین، به همین معنی است . <BR><font color=\"Blue\">◄</font> (اِمص ) نازاینده شدن زن و قبول نکردن رحمش آب مرد را. (از منتهی الارب ). نازاینده شدن . (المصادر زوزنی ) (تاج المصادر بیهقی ) (دهار). سترون شدن . عقیم شدن رحم . عُقم . عَقَم . <BR><font color=\"Blue\">◄</font> عقیم کردن خداوند رحم را. <BR><font color=\"Blue\">◄</font> سکوت کردن و خاموش شدن . (از اقرب الموارد). عَقَم . (منتهی الارب ). و رجوع به عَقَم شود.<br></font></div>'),
(184979, 'عقم', '<span class=\"hlight\">عقم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) گلیم سرخ، یا هر جامه ٔ سرخ . و نوعی از رنگ و نگار. (منتهی الارب ). نوعی از نگار، و گویندگلیم سرخ است و گویند هر لباس سرخ رنگ . (از اقرب الموارد). عِقم . و رجوع به عِقم شود. <BR><font color=\"Blue\">◄</font> حاجزمیان دو چیز. (منتهی الارب ). اصل معنای عقم، سد و منعو قطع است و باقی معانی آن مجازی باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) نازایندگی، و شکستگی است در زهدان که به سبب آن آبستن نشود. (منتهی الارب ).<br></font></div>'),
(184980, 'عقم', '<span class=\"hlight\">عقم .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ]</font></b> (ع مص ) خاموش گردیدن . (منتهی الارب ). عَقم . (اقرب الموارد). و رجوع به عَقم شود. <BR><font color=\"Blue\">◄</font> نازاینده شدن زن و قبول نکردن رحمش آب مرد را. (از منتهی الارب ). عَقم . عُقم . و رجوع به عَقم شود. سترون شدن زن .<br></font></div>'),
(184981, 'عقم', '<span class=\"hlight\">عقم .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) نوعی از رنگ و نگار. (منتهی الارب ). عَقم . و رجوع به عَقم شود.<br></font></div>'),
(184982, 'عقم', '<span class=\"hlight\">عقم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق ُ ]</font></b> (ع ص، اِ) ج ِ عَقیم . (منتهی الارب ) (اقرب الموارد). رجوع به عقیم شود.<br></font></div>'),
(184983, 'عقم', '<span class=\"hlight\">عقم .</span><font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِمص ) نازایندگی، و شکستگی است در زهدان که به سبب آن آبستن نشود. (منتهی الارب ). سترونی . عَقم . و رجوع به عَقم شود. <BR><font color=\"Blue\">◄</font> (ص، اِ) ج ِ عَقیم . (منتهی الارب ) (اقرب الموارد). رجوع به عقیم شود.<br></font></div>'),
(184984, 'عقم', '<span class=\"hlight\">عقم .</span><font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) نازاینده شدن زن و قبول نکردن آب مردرا. (از منتهی الارب ). عقیم بودن رحم . (از اقرب الموارد). سترون شدن . عَقم . عَقَم . و رجوع به عَقم شود.<br></font></div>'),
(184985, 'عقمة', '<span class=\"hlight\">عقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع اِ) نوعی از رنگ و نگار، ورنگ . (منتهی الارب ). گلیم سرخ، و گویند هر لباس سرخ رنگ . (از اقرب الموارد). عِقمة. و رجوع به عقمة شود.<br></font></div>'),
(184986, 'عقمة', '<span class=\"hlight\">عقمة.</span> <font color=\"DarkGreen\"><b>[ ع َق َ م َ ]</font></b> (ع اِ) عقمةالقمر؛ بازآمدن ماه . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) نام رودباری است . (از منتهی الارب ).<br></font></div>'),
(184987, 'عقمة', '<span class=\"hlight\">عقمة.</span> <font color=\"DarkGreen\"><b>[ ع ِ م َ ]</font></b> (ع اِ)اسم النوع است مصدر عقم را. <BR><font color=\"Blue\">◄</font> نگار. (ازاقرب الموارد). <BR><font color=\"Blue\">◄</font> نوعی از رنگ و نگار، ورنگ . (منتهی الارب ). گلیم سرخ، و گویند هر لباس سرخ رنگ . (از اقرب الموارد). عَقمة. و رجوع به عقمة شود.<br></font></div>'),
(184988, 'عقمة', '<span class=\"hlight\">عقمة.</span> <font color=\"DarkGreen\"><b>[ ع ُ م َ ]</font></b> (اِخ ) جایگاهی است در شعر حطیئة.آن را عُقیة نیز ضبط کرده اند. (از معجم البلدان ).<br></font></div>'),
(184989, 'عقمی', '<span class=\"hlight\">عقمی .</span> <font color=\"DarkGreen\"><b>[ ع َ ما ]</font></b> (ع ص، اِ) ج ِ عَقیم . (منتهی الارب ) (اقرب الموارد). نازایندگان و عقیمان <span class=\"hlight\">:</span> <br>وانچه گرفته است پیش ازین پسرانش <br>عقمی آیند و دخترانش سترون .<br><font color=\"Red\">فرخی .</font><br></font></div>'),
(184990, 'عقمی', '<span class=\"hlight\">عقمی .</span> <font color=\"DarkGreen\"><b>[ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ]</font></b> (ع ص ) مرد بزرگ قدر به شرف آبائی و جوانمرد. (از منتهی الارب ). مرد قدیم و اصیل در شرف و کرم . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سخن پوشیده و غریب و مشتبه . (منتهی الارب ). سخن غریب و غامض . (از اقرب الموارد).<br></font></div>'),
(184991, 'عقنبس', '<span class=\"hlight\">عقنبس .</span> <font color=\"DarkGreen\"><b>[ ع َ قَم ْ ب َ ]</font></b> (ع ص ) بدخلق . (از اقرب الموارد).<br></font></div>'),
(184992, 'عقنة', '<span class=\"hlight\">عقنة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ن َ ]</font></b> (اِخ ) قلعه ای است به اران . (منتهی الارب ). نام قلعه ای است در اَرّان از نواحی جَنْزة (گنجه ). (از معجم البلدان ).<br></font></div>'),
(184993, 'عقنفس', '<span class=\"hlight\">عقنفس .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ف َ ]</font></b>(ع ص ) رجل عقنفس ؛ مرد دشوارخوی . (منتهی الارب ). سخت خوی . <BR><font color=\"Blue\">◄</font> لئیم و فرومایه . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خلق عقنفس ؛ خوی دشوار. (منتهی الارب ).<br></font></div>'),
(184994, 'عقنقل', '<span class=\"hlight\">عقنقل .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ق َ ]</font></b> (ع اِ) رودبار بزرگ فراخ . (منتهی الارب ). وادی بزرگ و گشاده . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ریگ توده ٔ برهم نشسته . <BR><font color=\"Blue\">◄</font> روده ٔ سوسمار. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کاسه ٔ بزرگ . (منتهی الارب ). قدح . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شمشیر. (منتهی الارب ). سیف . (اقرب الموارد). نون و قاف آن زائد است برای الحاق به «سفرجل ». ج، عَقاقل . (از اقرب الموارد) (از منتهی الارب ).<br></font></div>'),
(184995, 'عقو', '<span class=\"hlight\">عقو.</span> <font color=\"DarkGreen\"><b>[ ع َق ْوْ ]</font></b> (ع مص ) کندن چاه را پس از جانبش به آب رسیدن، یا از چپ و راست کندن چاه را به جهت آب . (از منتهی الارب ). کندن چاه را و از کنار آن به آب رسیدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بلند شدن درفش . <BR><font color=\"Blue\">◄</font> ناپسند کردن و مکروه داشتن امر را. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بازداشتن . (از منتهی الارب ). به معنی عوق است و مقلوب آن باشد. (از اقرب الموارد). قلب العوق . (تاج المصادر بیهقی ).<br></font></div>'),
(184996, 'عقوب', '<span class=\"hlight\">عقوب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) آنکه نائب پیشین خود باشد در امور خیر. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(184997, 'عقوب', '<span class=\"hlight\">عقوب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) برگ سبز برآوردن بعد برگ خشک . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> نکاح کردن بعد مردن یا طلاق آن . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> بر پاشنه زدن . (دهار). <BR><font color=\"Blue\">◄</font> خلیفه ٔ کسی شدن . (از منتهی الارب ). از پی درآمدن . (دهار) (تاج المصادر بیهقی ). جانشین کسی شدن و پس از او آمدن . (از اقرب الموارد). عَقب . عاقبة. و رجوع به عقب و عاقبة شود.<br></font></div>'),
(184998, 'عقوبات', '<span class=\"hlight\">عقوبات .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عقوبة. (اقرب الموارد). رجوع به عقوبة و عقوبت شود.<br></font></div>'),
(184999, 'عقوبان', '<span class=\"hlight\">عقوبان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام دو جایگاه است در شعر ابوزیاد. (از معجم البلدان ).<br></font></div>'),
(185000, 'عقوبة', '<span class=\"hlight\">عقوبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع اِ) عقوبت . عذاب و سزای گناه . (آنندراج ). پاداش بدی و شکنجه . (دهار). جزاء، و گویند عقوبة محنتی است که در دنیا به سبب گناه به انسان میرسد و گاهی آن را خاص تعزیر می دانند، و نیز عقوبات بر احکام شرعی متعلق به امور دنیا، به اعتبار مدنیت اطلاق شود. ج، عُقوبات . (از اقرب الموارد). و رجوع به عقوبت شود.<br></font></div>'),
(185001, 'عقوبت', '<span class=\"hlight\">عقوبت .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع اِ) عقوبة. شکنجه و عذاب و جزای کار بد و گناه . سیاست . تنبیه . (فرهنگ فارسی معین ). بادآفراه . بادافراه . بادافره . پادآفراه . پادافره . پادافره . تِباعة. تَبِعة. رِجس . عِقاب . کیفر.مُثلَة. مَثُلَة. مِحال . نفس نقمة. نِکال . و رجوع به عقوبة شود <span class=\"hlight\">:</span> پس گفت <font color=\"DarkGreen\"><b>[ حسنک ]</font></b> من خطا کرده ام و مستوجب هر عقوبت هستم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٨٢</span>). هر چه در خشم فرمان دهم آن را امضا نکنند تا... اگر آن خشم را... به ناحق گرفته باشم باطل کنم آن عقوبت را.(تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٠٢</span>). و دیگر عقوبت بر مقتضای شریعت باشد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٠٢</span>). آفت ملک شش چیز است، حرمان ... و غلو در عقوبت و سیاست و غیره . (کلیله و دمنه ). اصحاب حزم گناه ظاهر را عقوبت مستور... جایز نشمرند. (کلیله و دمنه ). قاضی به قصاص و عقوبت او حکم کرد. (کلیله و دمنه ). مرا در ملامت این جهان و عقوبت آن جهان می افگندی . (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٣٢٣</span>). عواقب آن عقوبت به بصر بصیرت مشاهده کردم . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٥٩</span>). اگر هر آینه مستوجب عقوبتم، به قیامتم نابینا برانگیز. (گلستان ). ملک را طرفی از ذمائم اخلاق او به قرائن معلوم شد... در شکنجه کشید و به انواع عقوبت بکشت . (گلستان ). <BR><font color=\"Blue\">◄</font> در اصطلاح شرعی، رنجی را که ممکن است در نتیجه ٔ گناه در این جهان به آدمی رسد نام آن عقوبت باشد، و گاه عقوبت را به تعزیر و تأدیب زنهاریان تخصیص دهند. و لفظ عقوبات اطلاق شود براحکام شرعیه که وابسته به امور دنیا و از طریق سیاست باشد و آن یکی از ارکان مباحث فقهیه است . (از کشاف اصطلاحات الفنون، ذیل عقاب ). و رجوع به عقوبة شود.<br>- <span class=\"hlight\">عقوبت باره </span> ؛ دژ و قلعه ٔ سخت بر کنار از جهان که گویی برای عقوبت و شکنجه ٔ ساکنان آن بنا شده است <span class=\"hlight\">:</span> <br>چو سر در قصر شیرین کرد شاپور<br>عقوبت باره ای دید از جهان دور.<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">عقوبت بردن </span> ؛ رنج بردن . عذاب بردن <span class=\"hlight\">:</span> <br>مسلط مکن چون منی بر سرم <br>ز دست تو به گر عقوبت برم .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">عقوبت کشیدن </span> ؛ رنج بردن . عذاب کشیدن <span class=\"hlight\">:</span> <br>بناها در ازل محکم تو کردی <br>عقوبت در رهت باید کشیدن .<br> <font color=\"Red\">ناصرخسرو.</font><br>- <span class=\"hlight\">موکلان عقوبت </span> ؛ مأموران شکنجه و تعذیب <span class=\"hlight\">:</span> موکلان عقوبت در او آویختند. (گلستان ).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(185002, 'عقوبت کردن', '<span class=\"hlight\">عقوبت کردن .</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ک َ دَ ]</font></b> (مص مرکب ) بعمل آوردن عقوبت بر کسی . (آنندراج ). مجازات کردن . تنبیه کردن . سیاست کردن . انهاک . تمثیل . تنکیل . تنهکة. معاقبة <span class=\"hlight\">:</span> هارون پوشیده کسان گماشته بود تا هر کس زیردار جعفر گشتی و تندمی و توجعی نمودی ... نزدیک وی آوردندی و عقوبت کردندی . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٩٠</span>).<br>خشمت نکرد کس را الا به حق عقوبت <br>عفوت نکرد کس راالا به حق محابا.<br> <font color=\"Red\">میرمعزی (از آنندراج ).</font><br>عقوبت مکن عذرخواه آمدم <br>به نزدیک تو روسیاه آمدم .<br> <font color=\"Red\">نظامی (از آنندراج ).</font><br>عدل است اگر عقوبت ما بیگنه کنی <br>لطف است اگر کشی قلم عفو بر خطا.<br> <font color=\"Red\">سعدی .</font><br>حرکتی از او در نظر سلطان ناپسند آمد، مصادره فرمود و عقوبت کرد. (گلستان ). بنده را دست و پا بسته عقوبت همی کرد. (گلستان ). عفو؛ عقوبت ناکردن مستحق عذاب را. (منتهی الارب ).<br></font></div>'),
(185003, 'عقود', '<span class=\"hlight\">عقود.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b>(ع اِ) ج ِ عَقد. (منتهی الارب ) (اقرب الموارد). رجوع به عَقد شود. عهدها. (ترجمان القرآن جرجانی ). پیمان ها <span class=\"hlight\">:</span> عقود و عهود پیوستند. (تاریخ بیهقی ).<br>- <span class=\"hlight\">عقود امان </span> ؛ ج ِ عقد امان . (فرهنگ فارسی معین ). رجوع به عقد امان در ترکیبات عقد شود.<br> <BR><font color=\"Blue\">◄</font> در اصطلاح شرعی و فقهی، قسمتی از اقسام اربعه ٔ فقه، و سه قسمت دیگر، عبادات و ایقاعات و احکام است . (یادداشت مرحوم دهخدا). آنچه غرض مهم از آن دنیا باشد و دو طرفی باشد یعنی نیاز به ایجاب و قبول داشته باشد عقودنامند. و عبارت از اسبابی هستند که مترتب میشود بر آنها احکام شرعیه از وجوب، ندب، کراهت، تحریم و اباحه . چنانکه هر یک از عقود متصف به این اوصاف میشوند، در مقابل ایقاعات و احکام به معنی خاص و عام . (فرهنگ علوم نقلی از قواعد شهید ص <span class=\"hlight\" dir=\"rtl\">٢</span> و <span class=\"hlight\" dir=\"rtl\">٤</span>).<br>- <span class=\"hlight\">العقود تابعة للقصود</span> ؛ اصطلاحی است فقهی و مراد آن است که آثار مترتبه بر عقود تابع قصد و انشاء است . حال اگر قصد کند شرطی راکه فاسد باشد و باطل، ناچار عقد هم باطل است . (فرهنگ علوم نقلی از عوایدالایام ص <span class=\"hlight\" dir=\"rtl\">٥٣</span>).<br>- <span class=\"hlight\">عقود ابنیه (علم ...)</span> ؛ علمی است که به وسیله ٔ آن احوال و اوضاع ابنیه و چگونگی ایجاد و حفر نهرها و پاک کردن قناتها و بستن منافذ و سوراخها و تنضید و بر هم نهادن مساکن شناخته میشود و در ساختن شهرها و قلعه ها و منازل و نیز در کشاورزی سودی سرشار دارد. (از کشاف اصطلاحات الفنون ).<br>- <span class=\"hlight\">عقود لاحقه </span> ؛ معاملاتی که پس ازمعامله ٔ اول انجام شده است مثلاً در اعمال حق شفعه اگر خریدار ملک، خود به دیگری فروخت و آن دیگر هم به دیگری فروخت و چند عقد بر ملک واقع شد باز هم شفیع تواند به خریدار آخری مراجعه کند و مبیع را مسترد دارد در ازاء عوض آن . یا در مورد بیع فاسد اگر عقودی برآن واقع شد باز هم همان حکم را دارد که عقد اول داشته و دارد یا نه . (فرهنگ علوم نقلی ).<br><BR><font color=\"Blue\">◄</font> در اعداد، اول آن عشر است و آخر آن تسعون، و واحد آن عَقد است . (از اقرب الموارد). در اعداد عربی از عشرون (<span class=\"hlight\" dir=\"rtl\">٢٠</span>) تا تسعون (<span class=\"hlight\" dir=\"rtl\">٩٠</span>) را عقود نامند که از نظر صرف عربی ملحق به جمع مذکر سالم هستند یعنی در حال رفع با واو و در حال نصب و جر با یاء آیند <span class=\"hlight\">:</span> <br>همیشه تا ز عدد در عقود هست نشان <br>همیشه تا ز طمع برطبایع است رقم .<br> <font color=\"Red\">مسعودسعد.</font><br>- <span class=\"hlight\">علم عقود</span> ؛ حساب با انگشتان دست و یا با بندها و مفاصل انگشتان . عملاً حساب عقود به سه طریقه انجام میشود: الف - در زیر پارچه و مستور از نظر حضار بعمل می آید، چنانکه امروزه در جزایر بحرین هم معمول است که درموقع معامله ٔ مروارید طرفین روبروی هم نشینند و دست راست یکدیگر را گرفته با دست چپ دامن قبا یا دستمالی را روی آن گذارند و معامله و چانه زدن را به وسیله ٔ لمس و فشار انگشتان طرف معمول میدارند بطوری که جریان معامله بکلی بر حاضران مجهول ماند. ب - شمارش به وسیله ٔ بندهای انگشتان، چنانکه در هندوستان و مخصوصاً در بنگاله هنوز مرسوم است . ج - عبارت است از صور واشکال که به وسیله ٔ تا کردن انگشتان دست راست یا چپ و الصاق سرانگشت سبابه به انگشت ابهام (بعضی موارد)حاصل میگردد. و هر یک از آن صور و اشکال دلالت دارد بر عددی از اعداد از یک تا ده هزار (بر طبق اسناد شرقی ) و از یک تا یک میلیون (بر طبق اسناد اروپائی ). (از فرهنگ فارسی معین ). و رجوع به مقاله ٔ جمال زاده در فردوسی نامه ٔ مهر ص <span class=\"hlight\" dir=\"rtl\">٢٥</span> به بعد شود. و نیز رجوع به عقدانامل شود.<br><BR><font color=\"Blue\">◄</font> ج ِ عِقد. (منتهی الارب ) (اقرب الموارد). گردن بندها. رشته ها. رجوع به عِقد شود. <BR><font color=\"Blue\">◄</font> گره ها و بندها. ج، عقودات . (ناظم الاطباء).<br></font></div>'),
(185004, 'عقودات', '<span class=\"hlight\">عقودات .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (از ع، اِ) ج ِ عُقود. (ناظم الاطباء). رجوع به عقود شود.<br></font></div>'),
(185005, 'عقور', '<span class=\"hlight\">عقور.</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (ع ص ) سگ گزنده . (منتهی الارب ). حیوانی که بگزد.(از اقرب الموارد). ضد انوس . ج، عُقُر <span class=\"hlight\">:</span> <br>دهر بی منفعت خری است پلید<br>چرخ بی عافیت سگی است عقور.<br> <font color=\"Red\">مسعودسعد.</font><br>در عمارتها سگانند و عقور<br>در خرابیهاست کنج عزّ و نور.<br> <font color=\"Red\">مولوی .</font><br><BR><font color=\"Blue\">◄</font> گزنده ٔ ذی روح است و بس . (منتهی الارب ). گویند عقور برای هر حیوانی بکار رود و برای غیر جان دار عُقَرة گویند. (از اقرب الموارد).<br></font></div>'),
(185006, 'عقور', '<span class=\"hlight\">عقور.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِخ ) نام جایگاهی است . (از معجم البلدان ) (از منتهی الارب ).<br></font></div>'),
(185007, 'عقوف', '<span class=\"hlight\">عقوف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) پستان ماده گاو که شیر آن وقت دوشیدن راست نرود. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185008, 'عقوق', '<span class=\"hlight\">عقوق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) باردار گردیدن شتر ماده .عقاق . و رجوع به عقاق شود. <BR><font color=\"Blue\">◄</font> آزردن پدر را. (از منتهی الارب ). نافرمانی کردن کسی را که حق او بر تو واجب باشد. (المصادر زوزنی ) (از تاج المصادر بیهقی ). نافرمانبرداری کردن مادر و پدر را و کسی را که حق او بر تو واجب باشد. (دهار). سرپیچی کردن از پدر و ترک شفقت و احسان بر او و سبک داشتن او را، و ضدآن «بر» و برور است، و چنین شخصی را عاق و عُقَق و عُقُق و اَعق ّ گویند. و گویند اصل معنای عقوق، قطع کردن است، بنابراین اختصاص به والدین ندارد. (از اقرب الموارد). اسأه به والدین . تضییع حقوق ابوین . (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> جزای این عقوق و پاداش این حقوق و باذافراه این نفاق و شقاق ... تقدیم افتد. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٧٠</span>). از عقوق و تمرد پسر مستغاث شد و از حرکات و سکنات او تبرا نمود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٤٣</span>). منوچهر در سر کس به پدر فرستاد و از معرض عقوق و اهمال حقوق تفادی نمود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٢٦</span>). از معرض عقوق مادر برخاست و هوای نفس در طاعت او مقهور گردانید. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٨٤</span>).<br>لیک محبوسی برای آن حقوق <br>اندک اندک عذر میخواه از عقوق .<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(185009, 'عقوق', '<span class=\"hlight\">عقوق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) اسب ماده ٔ باردار، و اسب ماده ٔ ناباردار، ازاضداد است، یا باردار به طریق تفاؤل است . (منتهی الارب ). باردار از اسبان، یا حائل و غیر باردار، و گویند آن را بر تفاؤل به اسب غیر باردار گویند چنانکه مار گزیده را سلیم نامند. (از اقرب الموارد). مادیان آبستن و ناآبستن . (دهار). ج، عُقُق، و جج، عِقاق . (اقرب الموارد) (منتهی الارب ) (دهار). و از آن جمله است مثل «طلب الابلق العقوق » یعنی طلب کرد محال را. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نوی العقوق ؛ خسته ٔ خرمای نرم که علف شتران است . (منتهی الارب ).هسته ای است نرم که جویدن آن آسان است که پیرزنان آن را میخورند یا میجوند، و ماده شتر آن را میخورد لذابه «عقوق » اضافه شده است . و آن از کلام اهل بصره است و اعراب بادیه آن را نشناسند. (از اقرب الموارد).<br></font></div>'),
(185010, 'عقوقس', '<span class=\"hlight\">عقوقس .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ق َ ]</font></b> (اِخ ) نام جایگاهی است . و آن را عَقَرقَس نیز ضبط کرده اند. (از معجم البلدان ).<br></font></div>'),
(185011, 'عقول', '<span class=\"hlight\">عقول .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) خردمند و فهم کننده چیزی را. (منتهی الارب ). درک کننده و دریابنده امور را. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> داروی قابض . (منتهی الارب ) (از اقرب الموارد). هر دارو که شکم ببندد. داروی که شکم فروبندد. ج، عَقولات . (یادداشت مرحوم دهخدا). و هو <font color=\"DarkGreen\"><b>[ ینبوت ]</font></b> عقول للبطن یتداوی به . (ذخیره ٔ خوارزمشاهی ).<br></font></div>'),
(185012, 'عقول', '<span class=\"hlight\">عقول .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) بر کوه برآمدن آهو و پناه جستن به آن . عَقل . و رجوع به عقل شود. <BR><font color=\"Blue\">◄</font> پناه جستن به کسی . (از منتهی الارب ) (از اقرب الموارد). و رجوع به عَقل شود.<br></font></div>'),
(185013, 'عقول', '<span class=\"hlight\">عقول .</span> <font color=\"DarkGreen\"><b>[ع ُ ]</font></b> (ع اِ) ج ِ عَقل . (منتهی الارب ) (اقرب الموارد). خردها. دانشها. هوشها. رجوع به عقل شود <span class=\"hlight\">:</span> <br>گفتم محاط باشد معقول عین او<br>گفتا بر او محیط نباشد عقول اگر.<br> <font color=\"Red\">ناصرخسرو.</font><br>لفظی ز تو وز عقول یک خیل <br>رمزی ز تو وز فحول یک رم .<br> <font color=\"Red\">خاقانی .</font><br>عقول حکایت آن معقول و مقبول ندارد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٤١٢</span>).<br>خویشتن را مسخ کردی زین سفول <br>زآن وجودی که بد آن رشک عقول .<br> <font color=\"Red\">مولوی .</font><br>تا عقل داشتم نگرفتم طریق عشق <br>جائی دلم برفت که حیران شود عقول .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">ارباب عقول </span> ؛ مردمان صاحب عقل و دانش . (ناظم الاطباء).<br>- <span class=\"hlight\">اهل عقول </span> ؛ عاقلان . خردمندان . (فرهنگ فارسی معین ).<br>- <BR><font color=\"Blue\">◄</font> فیلسوفان . حکما. (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">ناقص عقول </span> ؛ ناقص خرد <span class=\"hlight\">:</span> <br>که پیش صنم پیر ناقص عقول <br>بسی گفت وقولش نیامد قبول .<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> در اصطلاح فلاسفه، فرشتگان و ملکها، چه نزد حکما مقرر است که حق تعالی اول یک فرشته پیدا کرد، پس آن فرشته یک فرشته ٔ دیگر و یک آسمان پیدا کرد. و بهمین ترتیب ده فرشته و نه آسمان پیدا شدند که آنان را عقول عشره گویند. (از غیاث اللغات ) (از آنندراج ).رجوع به عقول عشرة شود.<br>- <span class=\"hlight\">عقول زواهر</span> ؛ در اصطلاح اشراقیان، عقول طولیه است . (از فرهنگ علوم عقلی ). رجوع به عقول عشرة در ردیف خود شود.<br>- <span class=\"hlight\">عقول ساذجة</span> ؛ عقول ابلهان و اطفال . (فرهنگ علوم عقلی ).<br>- <span class=\"hlight\">عقول عالیه </span> ؛ عقول طولیه است . (فرهنگ علوم عقلی ). رجوع به عقول عشرة در ردیف خود شود.<br>- <span class=\"hlight\">عقول فعاله </span> ؛ صدرالدین شیرازی گوید تمام عقول فعالند و اشعه ٔنور الهی اند. بنابراین کلمه ٔ عقل فعال کلمه ٔ عامی است که شامل تمام عقول طولیه میشود لکن از نظر جهان جسمانی عقل فعال عقل دهم است که مستقیماً به جهان کون و فساد و عقول و نفوس انسانی فیض دهد. (فرهنگ علوم عقلی از رسائل صدرا).<br>- <span class=\"hlight\">عقول قادسه و قدسیه در اصطلاح فلسفه ٔ اشراق </span> ؛ عقول مجرده و قاهره است . (از فرهنگ علوم عقلی ).<br>- <span class=\"hlight\">عقول متکافئة</span> ؛ درعرض عقول طولیه ٔ مترتبه، عقولی دیگر پدید آمده اند که آنها را عقول عرضیه ٔ متکافئه نامند از آن جهت که ترتب علی و معلولی میان آنها برقرار نیست و گمان کرده اند که مراد افلاطون از ارباب انواع همان عقول متکافئه ٔ عرضیه است . (از فرهنگ علوم عقلی ). و رجوع به انوار عرضیه و انوار متکافئه شود.<br></font></div>'),
(185014, 'عقول اولی', '<span class=\"hlight\">عقول اولی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل ِ لا ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از عقول عشره که حق تعالی اول از همه عالم آن ده فرشتگان را پیدا ساخت، و این قول حکمای هند است . (از غیاث اللغات ) (از آنندراج ). رجوع به عقول عشرة شود <span class=\"hlight\">:</span> <br>ترا شرایط تقدیم جمع باد چنان <br>که ابتدا به تو باشد عقول اولی را.<br><font color=\"Red\">ظهیر فاریابی (ازآنندراج ).</font><br></font></div>'),
(185015, 'عقولات', '<span class=\"hlight\">عقولات .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) ج ِ عَقول . (یادداشت مرحوم دهخدا). رجوع به عَقول شود.<br></font></div>'),
(185016, 'عقی', '<span class=\"hlight\">عقی .</span> <font color=\"DarkGreen\"><b>[ ع َق ْی ْ ]</font></b> (ع مص ) ناپسند داشتن . عَقْو. <BR><font color=\"Blue\">◄</font> خورانیدن بچه را چیزی که «عقی » برآرد از آن . (از منتهی الارب ) (از اقرب الموارد). گویند هل عقیتم صبیکم ؛ یعنی آیا او را عسل خورانیدید تا «عقی » او را بیرون آرد. (از اقرب الموارد). و رجوع به عقی در معنی اسمی شود. <BR><font color=\"Blue\">◄</font> حدث کردن کودک . (منتهی الارب ). حدث کردن کودک برای نخستین بار، و نیز تا وقتی که صغیر است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آمدن : من أین عُقیت (بصیغه ٔ مجهول )؛ از کجا آمدی . (از منتهی الارب ).<br></font></div>'),
(185017, 'عقی', '<span class=\"hlight\">عقی .</span> <font color=\"DarkGreen\"><b>[ ع ِق ْی ْ ]</font></b> (ع اِ) آنچه نخستین از کودک نوزاده برآید ازکمیز و پلیدی . (از منتهی الارب ). چیزی است که از شکم نوزاد هنگام تولد و پیش از آنکه چیزی بخورد، خارج میگردد و آن سیاه رنگ و لزج است مانند سریشم، و آن مانند «ردج » است در بزغاله و اسب کره . (از اقرب الموارد). ج، أعقاء. (منتهی الارب ) (اقرب الموارد). مامیزه .<br>- <span class=\"hlight\">امثال </span> :<br><span class=\"hlight\">هو أحرص من کلب علی عقی صبی </span> . (منتهی الارب ) (اقرب الموارد).<br></font></div>'),
(185018, 'عقیان', '<span class=\"hlight\">عقیان .</span> <font color=\"DarkGreen\"><b>[ ع ِق ْ ]</font></b> (ع اِ) زر خالص که در زمین پیدا گردد. (منتهی الارب ). ذهب خالص . (تحفه ٔ حکیم مؤمن ) (مخزن الادویه ). زر که از زمین برآید. (دهار). زر خالص، و گویند آن زری است که در زمین باشد نه آنچه از سنگ استخراج شود. (از اقرب الموارد). زر ردیا. سام . تبر. عسجد. عین . نضر <span class=\"hlight\">:</span> <br>هر آینه که ز دیدار آفتاب شود<br>به کوه سنگ عقیق و به دشت گل عقیان .<br> <font color=\"Red\">فرخی .</font><br>- <span class=\"hlight\">امثال </span> :<br><span class=\"hlight\">هو له عقیان و لا شی ٔ من عقیان </span> ؛ یعنی او دو طفل دارد در حالی که فقیر است . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) اطمی است نزدیک مدینه مر بنی بیاضیه را. (منتهی الارب ).<br></font></div>'),
(185019, 'عقیب', '<span class=\"hlight\">عقیب .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص، اِ) در پی کننده، و پس دیگری آینده . (منتهی الارب ). پیرو و آنچه پس باشد. (غیاث اللغات ) (آنندراج ). دنبال . دنباله . (فرهنگ فارسی معین ). معاقب ؛ یعنی در پس آینده و به دنبال آینده . و گفته ٔ فقها «یفعل ذلک عقیب الصلاة» بتقدیر محذوف است یعنی «فی وقت عقیب وقت الصلاة». (از اقرب الموارد) <span class=\"hlight\">:</span> بعد از آن عقیب آن نصیحت خالص از ریا و صادقانه . (ترجمه ٔمحاسن اصفهان ص <span class=\"hlight\" dir=\"rtl\">٩٤</span>). بیشتر علما گفتند مراد تکبیر عید است عقیب چهار نماز شام و خفتن و بامداد و نماز عید در عید فطر. (تفسیر ابوالفتوح رازی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٥</span>).<br></font></div>'),
(185020, 'عقیب', '<span class=\"hlight\">عقیب .</span><font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (اِخ ) از صحابیان است . (از منتهی الارب ).<br></font></div>'),
(185021, 'عقیب', '<span class=\"hlight\">عقیب .</span> <font color=\"DarkGreen\"><b>[ ع ُق ْ ق َ ]</font></b>(ع اِ) مرغی است . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) نام موضعی است . (از منتهی الارب ).<br></font></div>'),
(185022, 'عقیب', '<span class=\"hlight\">عقیب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َی ْ ی ِ ]</font></b> (ع اِ مصغر) مصغر عُقاب ؛ یعنی عقاب کوچک . (ناظم الاطباء). و رجوع به عقاب شود.<br></font></div>'),
(185023, 'عقیبة', '<span class=\"hlight\">عقیبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ب َ ]</font></b> (اِخ ) ابن هُبیَرة اسدی . از شعرای جاهلیت عرب است و درک اسلام نیز کرد. او اشعار مشهوری خطاب به معاویه دارد که چنین آغاز میشود <span class=\"hlight\">:</span> <br>معاوی اننا بشر، فاسجح <br>فلسنا بالجبال و لاالحدید.<br>عقیبة در حدود سال <span class=\"hlight\" dir=\"rtl\">٥٠</span> هَ . ق . در گذشت . (از الاعلام زرکلی به نقل از خزانةالبغدادی و سمط اللآلی ).<br></font></div>'),
(185024, 'عقید', '<span class=\"hlight\">عقید.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) پیمان نماینده . (منتهی الارب ). هم عهد. (دهار). آنکه با تو عهد بسته بود. (مهذب الاسماء). معاقد و معاهد. (اقرب الموارد): هو عقید الکرم و اللؤم ؛ او درطبع کریم یا لئیم است . (از اقرب الموارد) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> مایع دفزک و سطبر: عسل عقید؛ شهد بسته و سطبر. (منتهی الارب ). غلیظ، از رب و غیره . (از اقرب الموارد). مجسمه . آب بعضی میوه ها چون بهی و سیب و انار و آلبالو که جوشانند تا بقوام لرزانک و راحةالحلقوم و هم زفت تر آید. (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">عقیدالسفرجل </span> ؛ مجسمه ٔ به . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">عقیدالعنب </span> ؛ میپختج گویند، و رب العنب نیز عقیدالعنب خوانند و به شیرازی دوشاب خوانند و مثلث نیز نوعی از آن است . (اختیارات بدیعی ). میفختج . (تحفه ٔ حکیم مؤمن ) (مخزن الادویه ). دوشاب انگور. (الفاظ الادویة). دبس . مجسمه ٔ انگور. رب انگور. طیلا. می پخته . (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> بگیرند تخم بنگ، افیون، میعه بارزد...همه را بکوبند و به عقیدالعنب یعنی دوشاب بسرشند. (ذخیره ٔ خوارزمشاهی ).<br><BR><font color=\"Blue\">◄</font> (اِ) در تداول امروزین عرب زبانان، سرهنگ و کلنل، که درجه ای است در ارتش .<br></font></div>'),
(185025, 'عقید هندی', '<span class=\"hlight\">عقیدهندی .</span> <font color=\"DarkGreen\"><b>[ ع َ دِ هَِ ]</font></b> (ترکیب وصفی، اِ مرکب ) زردچوبه . (فرهنگ فارسی معین ). رجوع به زردچوبه شود.<br></font></div>'),
(185026, 'عقیدت', '<span class=\"hlight\">عقیدت .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ ]</font></b> (ع اِ) عقیدة. عقیده . عقیده و پنداشتی .(ناظم الاطباء). آنچه انسان بدان اعتقاد و یقین دارد. (فرهنگ فارسی معین ). رجوع به عقیدة و عقیده شود <span class=\"hlight\">:</span> اگر بهتر نگریسته بود خبث عقیدت او... مشاهدت افتد. (کلیله و دمنه ). لاجرم به میامن این نیتهای نیکو و عقیدتهای صافی شعار پادشاهی ... جاوید و مخلد گشته است . (کلیله و دمنه ). و هر کجا که عقیدتها به مودت آراسته گشت اگر در مال و جان با یکدیگر مواسات رود... هنوز از وجوب آن قاصر باشد. (کلیله و دمنه ).<br>سر نهادند پیش او بر خاک <br>کآفرین بر چنان عقیدت پاک .<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(185027, 'عقیدت منش', '<span class=\"hlight\">عقیدت منش .</span> <font color=\"DarkGreen\"><b>[ ع َ دَم َ ن ِ ]</font></b> (ص مرکب ) متدین و دیندار. (ناظم الاطباء).<br></font></div>'),
(185028, 'عقیده', '<span class=\"hlight\">عقیده .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ع اِ) عقیدة. عقیدت . هر چیز که شخص بدان اعتقاد دارد و یقین بر آن دارد و نمشته و پنداشتی . (ناظم الاطباء). آنچه بدان گروند و تصدیق کنند. آنچه بدان باور دارند. آنچه بدان گرویده اند. ج، عَقاید. (یادداشت مرحوم دهخدا). و رجوع به عقیدت و عقیدة شود.<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">عقیده آزاد است </span> ؛ مثلی است کهن و باستانی که نزد عوام و خواص ایرانی متداول است، و از آن اصل آزادی اندیشه و دین را اراده می کنند. (امثال و حکم دهخدا).<br>- <span class=\"hlight\">باعقیده </span> ؛ عقیده دار. عقیده مند.<br>- <span class=\"hlight\">بدعقیده </span> ؛ آنکه عقیده اش ناپسند باشد.<br>- <span class=\"hlight\">بی عقیده </span> ؛ بدون عقیده . غیر معتقد.<br>- <span class=\"hlight\">خوش عقیده </span> ؛ آنکه عقیده اش پسندیده باشد.<br>- <span class=\"hlight\">عقیده ٔ حقوق مطلقه </span> ؛ خلاصه ٔ این عقیده چنین است که شخص میتواند حقوق فردی را بدون قید و حد به معرض اجرا بگذارد اگر چه از اجرای حق او دیگری متضرر شود، این عقیده ٔ دیون بوده و هست . این عقیده اساساً با تحلیل ماهیت حق و طرز پیدایش آن منافات دارد زیرا پیدایش حق بر اساس تصادم محرومیتها است و رفع تصادم محرومیتها (که منجر به پیدایش حقوق شده است ) ایجاب میکندحقوق مطلقه ای وجود پیدا نکند. عقیده ٔ مقابل عقیده ٔ مزبور را تحت عنوان «اصل محدود بودن حق » یاد میکنند.(فرهنگ حقوقی ).<br>- <span class=\"hlight\">هم عقیده </span> ؛ دو طرف که عقیده شان مانند هم باشد.<br></font></div>'),
(185029, 'عقیده داشتن', '<span class=\"hlight\">عقیده داشتن .</span> <font color=\"DarkGreen\"><b>[ ع َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ت َ ]</font></b> (مص مرکب ) انگاشتن . باور داشتن . معتقد بودن . رجوع به عقیده شود.<br></font></div>'),
(185030, 'عقیده مند', '<span class=\"hlight\">عقیده مند.</span> <font color=\"DarkGreen\"><b>[ ع َ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِم َ ]</font></b> (ص مرکب ) صاحب عقیده . (یادداشت مرحوم دهخدا).<br></font></div>'),
(185031, 'عقیر', '<span class=\"hlight\">عقیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) مرد که او را فرزندنشود. (منتهی الارب ) (از اقرب الموارد). نازاینده و ناامید. (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> خسته و مجروح . <BR><font color=\"Blue\">◄</font> ستور پی زده . (منتهی الارب ). معقور. (اقرب الموارد). ج، عَقری ̍. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنکه از ترس ناگهانی طاقت جنبش نباشد اورا، یا سرگشته و متحیر. (منتهی الارب ) (از اقرب الموارد). و رجوع به عَقر در معنی مصدری شود <span class=\"hlight\">:</span> <br>این سخن پایان ندارد آن فقیر<br>گشته است از تاب درویشی عقیر.<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(185032, 'عقیر', '<span class=\"hlight\">عقیر.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام فلاتی است که در آن آبهای شوری است، و آن را عُقَیر نیز ضبط کرده اند. (از معجم البلدان ).<br></font></div>'),
(185033, 'عقیر', '<span class=\"hlight\">عقیر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (اِخ ) قریه ای است در ساحل دریا در کنار هجر. و نیز نخلی است در یمامة از آن بنی ذهل بن دئل . و نیز نخلی است از آن بنی عامربن حنیفة در یمامه . (از معجم البلدان ) (از منتهی الارب ).<br></font></div>'),
(185034, 'عقیر', '<span class=\"hlight\">عقیر.</span> <font color=\"DarkGreen\"><b>[ ع ِق ْ قی ]</font></b> (ع اِ) گیاه که بدان تداوی نمایند، یا اصل داروها. <BR><font color=\"Blue\">◄</font> درخت . (منتهی الارب ). ج، عَقاقیر. (ناظم الاطباء).<br></font></div>'),
(185035, 'عقیرب', '<span class=\"hlight\">عقیرب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ رِ ]</font></b> (ع اِ مصغر) مصغر عقرب . عقرب و کژدم خرد. (ناظم الاطباء). و رجوع به عقرب شود.<br></font></div>'),
(185036, 'عقیربة', '<span class=\"hlight\">عقیربة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ رَ ب َ ]</font></b> (ع اِ) درونج که گیاهی است به هیئت عقرب . رجوع به درونج شود.<br></font></div>'),
(185037, 'عقیص', '<span class=\"hlight\">عقیص .</span> <font color=\"DarkGreen\"><b>[ ع ِق ْ قی ]</font></b> (ع ص ) بخیل . (اقرب الموارد). عُقُص . و رجوع به عقص شود. <BR><font color=\"Blue\">◄</font> شکنبه . (منتهی الارب ). و رجوع به عقص شود.<br></font></div>'),
(185038, 'عقیصر', '<span class=\"hlight\">عقیصر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ص ِ ]</font></b> (ع اِ) دابه ای است صحرائی . (منتهی الارب ). عقیصیر. (اقرب الموارد). و رجوع به عقیصیر شود.<br></font></div>'),
(185039, 'عقیصی', '<span class=\"hlight\">عقیصی .</span> <font color=\"DarkGreen\"><b>[ ع َ صا ]</font></b> (اِخ ) لقب ابی سعد تمیمی تابعی است . (منتهی الارب ).<br></font></div>'),
(185040, 'عقیصیر', '<span class=\"hlight\">عقیصیر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (ع اِ) دابه ای است . (از اقرب الموارد). عقیصر. (منتهی الارب ). و رجوع به عقیصر شود.<br></font></div>'),
(185041, 'عقیفان', '<span class=\"hlight\">عقیفان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (ع اِ) مورچه های درازپا که در مقابر و خرابه باشد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185042, 'عقیق', '<span class=\"hlight\">عقیق .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) مهره ای است سرخ رنگ که در یمن یافته شود، و جنسی است از آن که در سواحل دریای روم خیزد، تیره رنگ مانند آب که از گوشت نمکزده رود و در آن خطوط سپید خفی می باشد. (از منتهی الارب ) (از اقرب الموارد). سنگ سرخ، و نوعی از نگینهای لعل . (دهار). سنگی است مشهور. (الفاظ الادویة). اجناس آن بسیار است در بلاد یمن و ساحل بحر روم و نیکوترین آن بود که بغایت سرخ و شفاف بود. (از اختیارات بدیعی ). بهترین او سرخ و زرد و سفید است . (از تحفه ٔحکیم مؤمن ). بر چند نوع است و سرخ آن که صفای لون بیشتر دارد به بود و آن در ملک یمن بیشتر است . (نزهةالقلوب ). معروف است و آن را نوعهای بسیار است لکن مخصوصاً باید در سنگ قرمز معروف استعمال شود، ولی عقیق سفید مقصودشان الماس نبوده زیرا قدما علم تراش آن را نداشتند و بعید نیست که مقصود از بلور بوده و یکی از سنگهای گرانبها و حکاکی شده است که بر سینه بند کاهن اعظم، و هم یکی از سنگهای اساس اورشلیم بوده . (ازقاموس کتاب مقدس ). قسمی از بلور معدنی که به رنگهای مختلف متلون است . (ناظم الاطباء). سنگی است سیلیسی وآبدار که از کانیهای مجاور کوآرتز است، و آن سیلیس خالص است که دارای <span class=\"hlight\" dir=\"rtl\">n</span> مولکول آب است و این <span class=\"hlight\" dir=\"rtl\">n</span> ممکن است تا <span class=\"hlight\" dir=\"rtl\">١٨</span> مولکول هم برسد و نسبت به انواع مختلف عقیق مقدار مولکولهای آب فرق می کند. بطور کلی فرمول عقیق را میتوانم بصورت <span class=\"hlight\" dir=\"rtl\">nh٢o</span> و <span class=\"hlight\" dir=\"rtl\">sio٢</span> بنویسم . به علت وجود همین مولکولهای آب است که اگر عقیق خرد شده را روی آتش بریزند مثل خرده های نمک تک تک می کند و آبش را از دست میدهد. عقیق بر خلاف کوارتز بی شکل - یعنی آمورف - است و خاصیت ژلاتینی و کلوئیدی دارد، بطوری که گاهی منظره ٔ صمغ را پیدا می کند و سبک وزن است . عقیق در طبیعت به رنگهای مختلف بسیار زیاد است این سنگ در قلیائیات مثل پتاس و سود حل میشود و وزن مخصوصش بین <span class=\"hlight\" dir=\"rtl\">١/٩</span> تا <span class=\"hlight\" dir=\"rtl\">٢/٣</span> متغیر است، و گاه آنقدر سبک میشود که ممکن است روی آب بایستد. سختی این کانی نیز از کوآرتز کمتر است و بین <span class=\"hlight\" dir=\"rtl\">٥/٥</span> و <span class=\"hlight\" dir=\"rtl\">٦</span> می باشد. عقیق اقسام بسیار مختلف دارد و اگر مخصوصاً رنگ سرخ آتشی داشته باشد بسیار جالب است و در زینت به عنوان یکی از احجار کریمه مصرف میشود. قسم دیگر عقیق سنگی است به نام دلربا که در داخل آن ذرات میکا فراوان است و برق این ذرات جلوه ٔ مخصوصی به سنگ میدهد (وجه تسمیه ٔ دلربا به همین مناسبت است ). عقیق در نتیجه ٔ جریانهای آب در سنگهای سیلیسی یا سنگهای سیلیکات دار و یا در نتیجه ٔ برخاستن گازهای اسید از درون زمین ایجاد میشود و در خلال سنگهای دیگر بوجود می آید مخصوصاً در بین سنگهای آذرین سطحی که ساختمان سماکی دارد. (فرهنگ فارسی معین ). سنگی است شفاف به الوان، و از آن نگین انگشتری کنند. و چون برنگ عقیق گویند مراد سرخ باشد. (یادداشت مرحوم دهخدا). واحد آن عَقَیقة است . (از اقرب الموارد) (دهار). ج، عَقائق . (منتهی الارب ). و رجوع به الجماهر بیرونی صص <span class=\"hlight\" dir=\"rtl\">١٧٢</span> - <span class=\"hlight\" dir=\"rtl\">١٧٤</span> شود <span class=\"hlight\">:</span> <br>یک لخت خون بچه ٔ تاکم فرست از آنک <br>هم بوی مشک دارد و هم گونه ٔ عقیق .<br> <font color=\"Red\">رودکی .</font><br> <br>زان عقیقین میی که هر که بدید<br>از عقیق گداخته نشناخت .<br> <font color=\"Red\">رودکی .</font><br>میان ما دو تن آمیخته دو گونه سرشک <br>چو لؤلؤی که کنی با عقیق سرخ همال .<br> <font color=\"Red\">آغاجی .</font><br>ای سرخ گل تو بسد و زر و زمردی <br>ای لاله ٔ شکفته عقیق و خماهنی .<br> <font color=\"Red\">خسروی .</font><br>زمرد اندر تاکم عقیقم اندر شرب <br>سهیلم اندر خم آفتابم اندر جام .<br> <font color=\"Red\">ابوالعلاء ششتری .</font><br>خوشه چون عقد در و برگ چو زر<br>باد همچون عقیق و آب چو زنگ .<br> <font color=\"Red\">عماره .</font><br>دوگویا عقیق گهرپوش را<br>که بنده بدش چشمه ٔ نوش را.<br> <font color=\"Red\">فردوسی .</font><br>عقیق و زبرجد فروریختند<br>می و مشک و عنبر برآمیختند.<br> <font color=\"Red\">فردوسی .</font><br>عقیق و زبرجد بر او برنگار<br>میان اندرون گوهر شاهوار.<br> <font color=\"Red\">فردوسی .</font><br>به یک تختشان شاد بنشاندند<br>عقیق و زبرجد برافشاندند.<br> <font color=\"Red\">فردوسی .</font><br>در گردنش از عقیق تعویذ<br>بر سرش کلاه ارغوانی .<br> <font color=\"Red\">ناصرخسرو.</font><br>سالها باید که تا یک سنگ اصلی زآفتاب <br>لعل گردد در بدخشان یا عقیق اندر یمن .<br> <font color=\"Red\">سنائی .</font><br>دل او هست سنگین پس چه معنی <br>که عشق او عقیق از اشک من ساخت .<br> <font color=\"Red\">خاقانی .</font><br>دروغ است آنکه گویند اینکه درسنگ <br>فروغ خورعقیق اندر یمن ساخت .<br> <font color=\"Red\">خاقانی .</font><br>رواقی جداگانه دید از عقیق <br>ز بنیاد تا سر به گوهر غریق .<br> <font color=\"Red\">نظامی .</font><br>بخور مجلسش از ناله های دودآمیز<br>عقیق زیورش از دیده های خون پالای .<br> <font color=\"Red\">سعدی .</font><br>ز برگ پان لب جانان عقیق پیما شد<br>حنای عید می از بهر بوسه پیدا شد.<br> <font color=\"Red\">میرزا صائب (از آنندراج ).</font><br>- <span class=\"hlight\">عقیق ابلق </span> . رجوع به همین ترکیب در ردیف خود شود.<br>- <span class=\"hlight\">عقیق احمر</span> ؛ عقیق سرخ . عقیق قرمز، که نوعی عقیق است . یَنَع. رجوع به عقیق سرخ در همین ترکیبات شود.<br>- <span class=\"hlight\">عقیق اسود</span> ؛ عقیق سیاه . رجوع به عقیق سیاه در همین ترکیبات شود.<br>- <span class=\"hlight\">عقیق جگری </span> . رجوع به همین ترکیب در ردیف خود شود.<br>- <span class=\"hlight\">عقیق چشم بلبلی </span> ؛ نوعی عقیق شجری است که دارای دوایر متحدالمرکز کوچکتری است . زمینه ٔ این کانی به رنگ صورتی کم رنگ است . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عقیق دلربا</span> ؛ نوعی عقیق براق با جلوه ای زیاد. رجوع به عقیق شود.<br>- <span class=\"hlight\">عقیق رُطَبی </span> ؛ عقیقی است سرخ تیره و خطوطی سفید و نازک در آن هست . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">عقیق سرخ </span> ؛ عقیق احمر. نوعی عقیق که دارای رنگ سرخ آتشی است و در جواهرسازی مصرف میشود (فرهنگ فارسی معین ).<br>- <BR><font color=\"Blue\">◄</font> نوعی مهر سلیمان سرخ رنگ، که در جواهرسازی مصرف میگردد. (از فرهنگ فارسی معین ). رجوع به مهر سلیمان شود.<br>- <span class=\"hlight\">عقیق سیاه </span> ؛ عقیق اسود. نوعی سنگ آذرین شیشه ای شکل تیره از دسته ٔ سنگهای آتشفشانی قلیایی که شبیه شیشه های سیاه یا سبز (مثل شیشه ٔ ته بطریهای شکسته ) می باشد، به همین جهت به آن شیشه ٔ آتشفشانی نیز گویند. این سنگ چون دارای سختی و برندگی بالنسبه جالب است انسانهای نخستین وسایل دفاعی خود را (از قبیل سرنیزه و کارد و سوزن و غیره ) از این سنگ میساخته اند. ساختمان این سنگ در زیر میکرسکپ اغلب به صورت توده های بی شکل است و ندرةً دارای بلورهای فلدسپات می باشد. حجرالمینا. عقیق اسود. البسیدین . شیشه ٔ آتشفشانی . شیشه ٔ معدنی . (فرهنگ فارسی معین ).<br>- <span class=\"hlight\">عقیق ِ لَب </span> ؛ کنایه از لب از جهت تشبیه آن به عقیق در رنگ از اسمای محبوب است . (آنندراج ) <span class=\"hlight\">:</span> <br>به یکدست گیرد رخ شهرناز<br>به دیگر عقیق لب ارنواز.<br> <font color=\"Red\">فردوسی .</font><br>عقیق لب صنما تا جدایم از بر تو<br>همی حسدبرد از اشک من عقیق مذاب .<br> <font color=\"Red\">ادیب صابر (از آنندراج ).</font><br>- <span class=\"hlight\">عقیق ْ لَب </span> ؛ که لبی چون عقیق دارد <span class=\"hlight\">:</span> <br>کنار من ز عقیق آن زمان تهی گردد<br>که آن عقیق لبم در بر و کنار بود.<br> <font color=\"Red\">امیرمعزی (از آنندراج ).</font><br>- <span class=\"hlight\">عقیق مذاب </span> ؛ کنایه از شراب . رجوع به عقیق مذاب در ردیف خود شود.<br>- <span class=\"hlight\">عقیق یمان </span> ؛ عقیق یمن . عقیق یمنی . عقیق سرخ رنگ . رجوع به عقیق شود <span class=\"hlight\">:</span> <br>دُرّ یتیم گوهر یکدانه را ز اشک <br>جزع دو دیده پر زعقیق یمان شود.<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">عقیق یمن </span> ؛ عقیق یمانی . عقیق یمنی . عقیق که از یمن آرند و سرخ رنگ باشد. رجوع به عقیق شود<span class=\"hlight\">:</span> <br>می اندر قدح چون عقیق یمن <br>به پیش اندرون دسته ٔ نسترن .<br> <font color=\"Red\">فردوسی .</font><br>- <span class=\"hlight\">عقیق یمنی </span> ؛ عقیق یمن . عقیق یمان . عقیق که از یمن آرند و سرخ رنگ باشد <span class=\"hlight\">:</span> عقیق در یمن معدن نیک و عقیق یمنی مشهور است و آن معدن را قساس می خوانند. (نزهةالقلوب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span>).<br> <BR><font color=\"Blue\">◄</font> به مجاز لب معشوق . (از آنندراج ). کنایه از لب است به مناسبت رنگ <span class=\"hlight\">:</span> <br>آتش چو نبات و سنگ حیوان <br>دارش چو عقیق تو سخنور.<br> <font color=\"Red\">ناصرخسرو.</font><br>عتابش گرچه میزد شیشه بر سنگ <br>عقیقش نرخ میبرید در جنگ .<br> <font color=\"Red\">نظامی .</font><br>وزین پس برعقیق الماس میداشت <br>زمرد را به افعی پاس میداشت .<br> <font color=\"Red\">نظامی .</font><br> <BR><font color=\"Blue\">◄</font> کنایه از هر چیز سرخ و به رنگ عقیق است <span class=\"hlight\">:</span> <br>بر آن عقیق من سپه آورد زعفران <br>تا ساخت با الف من چو دال ذال .<br> <font color=\"Red\">ناصرخسرو.</font><br>تا چهره ٔ عقیق کند احمر از شعاع <br>بر اوج گنبد فلک اخضر آفتاب .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">مثل عقیق </span> ؛ مثل عقیق یمن : لبی سرخ . ماهی یا سیب زمینی یا پیازی خوب برشته شده . (امثال و حکم دهخدا).<br><BR><font color=\"Blue\">◄</font> وادی و دره . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> هرچه سیل بشکافد از زمین . (منتهی الارب ). هر مسیلی که آب سیل، از پیش آن را شکافته باشد و وسیع شده باشد. گویند«سال العقیق » که مجاز است در معنی «سال الماء فی العقیق » ج، أعِقّة. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> موی همزاد کودک . (منتهی الارب ). موی هر نوزادی از انسان و بهائم . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پشم شتر بچه . <BR><font color=\"Blue\">◄</font> موی شکمی هر چه از ستور باشد. (منتهی الارب ).<br></font></div>'),
(185043, 'عقیق', '<span class=\"hlight\">عقیق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) قریه ای است در نزدیکی سواکن از ساحل بحر، در بلاد بجاه . محصول آن تمر هندی است .و بر این لغت «ال » داخل نشود. (از معجم البلدان ).<br></font></div>'),
(185044, 'عقیق', '<span class=\"hlight\">عقیق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )آبی است از آن بنی جعده و بنی جرم . در زمان پیامبر (ص ) بر سر این آب بین این دو قبیله اختلاف رخ داد و پیغمبرحکم داد که از آن بنی جرم است . (از معجم البلدان ).<br></font></div>'),
(185045, 'عقیق', '<span class=\"hlight\">عقیق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) وادیی است نزدیک مدینه . وموضعی است به مدینه و به یمامة و به طائف و به تهامة و به نجد و شش موضع دیگر. ج، أعقّة. (از منتهی الارب ). نام چند وادی است در بلاد عرب، از آن جمله است : عقیق عارض یمامة، که وادی وسیعی است و چشمه های گوارایی دارد. و نیز در ناحیه ٔ مدینه عقیقی است دارای چشمه ها و نخلها، و برخی آن را دو عقیق دانند به نام عقیق اکبر و عقیق اصغر. و دیگر عقیق البصرة است و آن وادیی است به دنبال سفوان . و عقیق دیگری است که سیل آن در غور تهامه جاری میشود. و عقیق تمرة در نزدیکی تبالة و بیشه است و برخی آن را همان عقیق یمامة دانند. دیگر وادیی است از آن بنی کلاب . نام عقیق در اشعار شاعران عرب بسیار آمده است که غالباً تشخیص اینکه کدام یک از این عقیقها است مشکل است . (از معجم البلدان ).<br></font></div>'),
(185046, 'عقیق آمود', '<span class=\"hlight\">عقیق آمود.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ن مف مرکب ) به عقیق آمیخته . آمیخته به عقیق <span class=\"hlight\">:</span> <br>در گنجینه را گرفتم زود<br>تا کنم لعل را عقیق آمود.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(185047, 'عقیق آگین', '<span class=\"hlight\">عقیق آگین .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص مرکب ) عقیق نشان . آکنده از عقیق <span class=\"hlight\">:</span> <br>تا بدان وقتی که همچون گوی سیمین گشت سیب <br>نار همچون حقه ٔ گرد عقیق آگین شود.<br><font color=\"Red\">فرخی .</font><br></font></div>'),
(185048, 'عقیق ابلق', '<span class=\"hlight\">عقیق ابلق .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ اَ ل َ]</font></b> (ترکیب وصفی ) عقیق دورنگ . (آنندراج ) <span class=\"hlight\">:</span> <br>کم شد از گریه بسکه خون جگر<br>شد عقیق سرشک من ابلق .<br><font color=\"Red\">شفیع اثر (از آنندراج ).</font><br></font></div>'),
(185049, 'عقیق جگری', '<span class=\"hlight\">عقیق جگری .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ج ِ گ َ ]</font></b> (ترکیب وصفی ) نوعی از عقیق قیمتی که به رنگ جگر می باشد. (آنندراج ) <span class=\"hlight\">:</span> <br>نشان آتش لعل تو میدهد بنظر<br>گران بهاست عقیق سرشک ماجگر است .<br> <font color=\"Red\">ارادتخان واضح (از آنندراج ).</font><br>ز خون دیده ٔ خود خوشدلم که از جگرست <br>عقیق چون جگری باشد از یمن باشد.<br><font color=\"Red\">باقر کاشی (از آنندراج ).</font><br></font></div>'),
(185050, 'عقیق رنگ', '<span class=\"hlight\">عقیق رنگ .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b>(ص مرکب ) آنچه برنگ عقیق بود. سرخ رنگ <span class=\"hlight\">:</span> <br>ز بس که زان دو سپاه بزرگ کافر کشت <br>عقیق رنگ شد اندر دیار هند گیاه .<br> <font color=\"Red\">فرخی .</font><br>عقیق رنگ  شده ست این زمین ز بس کز خون <br>به روی دشت و بیابان فروشده ست آغار.<br> <font color=\"Red\">عنصری .</font><br>وان نقاب  عقیق رنگ ترا<br>کرد خوش خوش به زر ناب خضاب .<br> <font color=\"Red\">ناصرخسرو.</font><br>ابراز شعاع خنجر تو شد عقیق رنگ <br>کوه از نهیب گرز گران تو یافت کوس .<br> <font color=\"Red\">شهاب الدین محمدبن همام (از لباب ).</font><br>چو بخنده بازیابم اثر دهان تنگش <br>صدف گهر نماید شکر عقیق رنگش .<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(185051, 'عقیق رومی', '<span class=\"hlight\">عقیق رومی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) عقیقی که در روم به دست آید و آن تیره رنگ است و در وی خطهای سفیدخفی باشد. (فرهنگ فارسی معین ). رجوع به عقیق شود.<br></font></div>'),
(185052, 'عقیق روی', '<span class=\"hlight\">عقیق روی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص مرکب )که رویی چون عقیق دارد. گلفام و گلگون <span class=\"hlight\">:</span> <br>تذرو عقیق روی کلنگ سپیدرخ <br>گوزن سیاه چشم پلنگ ستیزه کار.<br><font color=\"Red\">فرخی .</font><br></font></div>'),
(185053, 'عقیق مذاب', '<span class=\"hlight\">عقیق مذاب .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ م ُ ]</font></b>(ترکیب وصفی، اِ مرکب ) کنایه از اشک خونین باشد. (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از می سرخ <span class=\"hlight\">:</span> <br>هوای مشرق تارتر از سیاه شبه <br>هوای مغرب رنگین تر از عقیق مذاب .<br> <font color=\"Red\">عمعق .</font><br>عقیق لب صنما تا جدایم از بر تو<br>همی حسد برد از اشک من عقیق مذاب .<br><font color=\"Red\">ادیب صابر (از آنندراج ).</font><br></font></div>'),
(185054, 'عقیق ناب', '<span class=\"hlight\">عقیق ناب .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از لب معشوق . (برهان ) (آنندراج ) (انجمن آرا). <BR><font color=\"Blue\">◄</font> کنایه از شراب انگوری . (برهان ) (آنندراج ). کنایه از شراب سرخ . (انجمن آرا). <BR><font color=\"Blue\">◄</font> کنایه از اشک خونین عاشق . (برهان ) (از آنندراج ).<br></font></div>'),
(185055, 'عقیق وار', '<span class=\"hlight\">عقیق وار.</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص مرکب ) چون عقیق . مانند عقیق <span class=\"hlight\">:</span> <br>عقیق وار شده ست آن زمین ز بس که ز خون <br>به روی دشت و بیابان فروشده است آغار.<br><font color=\"Red\">عنصری .</font><br></font></div>'),
(185056, 'عقیق گونه', '<span class=\"hlight\">عقیق گونه .</span> <font color=\"DarkGreen\"><b>[ ع َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص مرکب ) چون عقیق <span class=\"hlight\">:</span> <br>شهدی که عقیق گونه باشد<br>او را بمزی چه گونه باشد.<br><font color=\"Red\">نظامی .</font><br></font></div>'),
(185057, 'عقیقی', '<span class=\"hlight\">عقیقی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) علی بن احمدبن علی . از علمای امامیه در قرن سوم هجری . رجوع به علی عقیقی شود.<br></font></div>'),
(185058, 'عقیقی', '<span class=\"hlight\">عقیقی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب به عقیق . عقیقین . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> <br>خود هنوزت پسته ٔ خندان عقیقی نقطه ای است <br>باش تا گردش قضا پرگار مینائی کشد.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(185059, 'عقیقین', '<span class=\"hlight\">عقیقین .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب به عقیق . عقیقی . (فرهنگ فارسی معین ). از عقیق . به رنگ عقیق یعنی سرخ . (یادداشت مرحوم دهخدا) <span class=\"hlight\">:</span> <br>زان عقیقین میی که هر که بدید<br>از عقیق گداخته نشناخت .<br> <font color=\"Red\">رودکی .</font><br>گرفته سوی کبک شاهین شتاب <br>ز خون کرده چنگل عقیقین عقاب .<br> <font color=\"Red\">فردوسی .</font><br>بشکفت لاله ها چو عقیقین پیاله ها<br>وانگه پیاله ها همه آکنده مشک و بان .<br> <font color=\"Red\">منوچهری .</font><br>لاله تو گویی چو طفلک است دهن باز<br>لبش عقیقین و قعر کامش اسود.<br><font color=\"Red\">منوچهری .</font><br>بر سپهر لاجوردی صورت سعدالسعود<br>چون یکی چاه عقیقین در یکی نیلی ذقن .<br> <font color=\"Red\">منوچهری .</font><br>گل سرخ بر سرنهاد و ببست <br>عقیقین کلاه و پرندین ازار.<br> <font color=\"Red\">ناصرخسرو.</font><br>در فصل ربیع کلاله ٔ لاله از قلال جبال و یفاع تلال او چون قندیل عقیقین از صوامع رهابین نمایان . (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">١٢٠</span>).<br>گنجیست درج در عقیقین آن پسر<br>بالای گنج حلقه زده مار بنگرید.<br><font color=\"Red\">سعدی .</font><br></font></div>'),
(185060, 'عقیل', '<span class=\"hlight\">عقیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شداد سلولی . از اشراف شجاع در عهد مروان، و از همراهان حجاج در عراق . وی به سال <span class=\"hlight\" dir=\"rtl\">٧٦</span> هَ . ق . به قتل رسید. (از الاعلام زرکلی از تاریخ ابن الاثیر).<br></font></div>'),
(185061, 'عقیل', '<span class=\"hlight\">عقیل .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (اِخ ) جدی است جاهلی و فرزندان او بطنی از خزیمه، از عدنانیه را تشکیل میدهند و آنان را در سرزمین عراق و الجزیرة حکومتی بود و در عهد سلاطین سلجوقی کار آنان بالا گرفت . (از الاعلام زرکلی به نقل از نهایة الارب ).<br></font></div>'),
(185062, 'عقیل', '<span class=\"hlight\">عقیل .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ابن بلال بن جریر. نبه ٔ جریر شاعر معروف، شاعری مقل ّ (کم شعر) است . (از الفهرست ابن الندیم ).<br></font></div>'),
(185063, 'عقیل', '<span class=\"hlight\">عقیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی طالب عبدمناف بن عبدالمطلب هاشمی قرشی، مکنی به ابویزید. برادر بزرگتر علی بن ابی طالب (ع ). وی در جاهلیت شهرتی بسیار داشت و یکی از چهار تنی بود که قریش در منافرات و منازعات خود برای حکمیت بدانها رجوع میکرد. (سه تن دیگر مخرمة، و حویطب، و ابوجهم بوده اند). عقیل تا غزوه ٔ بدر در شرک باقی بود و در این غزوه قریش او را وادار ساختند تا با مسلمانان بجنگد و چون به اسارت مسلمین درآمد، با فدیه ٔ عباس بن عبدالمطلب آزاد شد و به مکه بازگشت و پس از واقعه ٔ حدیبیة اسلام آورد، و به سال هشتم هجری به مدینه مهاجرت کرد و در غزوه ٔمؤتة همراه مسلمین شرکت جست . هنگامی که برادرش علی (ع ) به خلافت رسید از وی جدا شد و به معاویه پیوست، و در اواخر عمر بینایی خویش را از دست داد. عقیل در زمان خود آگاهترین قریش در شناختن ایام و انساب آنان بود. و مردم در مسجد مدینه انساب و اخبار را از او میگرفتند. عقیل به سال <span class=\"hlight\" dir=\"rtl\">٦٠</span> هَ .ق . در ابتدای خلافت یزید درگذشت و برخی درگذشت او را در ایام معاویه میدانند. در حلب و نواحی آن گروهی میزیستند که به او نسبت داشتند و به بنی عقیل شهرت داشتند. (از الاعلام زرکلی به نقل از الاصابة و البیان و التبیین و نکت الطالبیین و طبقات ابن سعد و تاج العروس و مقاتل الطالبیین ).<br></font></div>'),
(185064, 'عقیل', '<span class=\"hlight\">عقیل .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (اِخ ) موضعی است به حوران . (منتهی الارب ). قریه ای است از قرای حوران از ناحیه ٔ لوی از اعمال دمشق . (از معجم البلدان ).<br></font></div>'),
(185065, 'عقیل', '<span class=\"hlight\">عقیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن موسی الکاظم (ع ). یکی از فرزندان امام موسی کاظم (ع ) است . (از حبیب السیر چ کتابخانه ٔ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨١</span>).<br></font></div>'),
(185066, 'عقیل', '<span class=\"hlight\">عقیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) مرد زیرک و بسیار دانا. (غیاث اللغات ) (آنندراج ). معقول . (اقرب الموارد). خردمند و بزرگوار. عاقل و گرامی . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> (اِ) زانوبند شتر. (غیاث اللغات ) (آنندراج ).<br></font></div>'),
(185067, 'عقیل', '<span class=\"hlight\">عقیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مقرن . صحابی است . (منتهی الارب ).<br></font></div>'),
(185068, 'عقیل', '<span class=\"hlight\">عقیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مرةبن موهوب بن مالک، از بنی زیدبن حرام، از جذام، از قحطانیه . جدی است جاهلی . و عقیلیون یا بنی عقیل که از ساکنان «حوف » می باشند بدو نسبت دارند. (از الاعلام زرکلی از نهایةالارب ).<br></font></div>'),
(185069, 'عقیل', '<span class=\"hlight\">عقیل .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) مالک و عقیل، دو ندیم جذیمةالابرش، که دوستی و وفای دو تن را بدان دو مثل زنند. (یادداشت مرحوم دهخدا).<br></font></div>'),
(185070, 'عقیل', '<span class=\"hlight\">عقیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد عُکبَری، مکنی به ابوالحسن و ملقب به احنف . شاعر و ادیب و از اهالی عکبرا بوده است و به سال <span class=\"hlight\" dir=\"rtl\">٣٨٥</span> هَ . ق . درگذشته است .رجوع به الاعلام زرکلی و المنتظم و یتیمةالدهر شود.<br></font></div>'),
(185071, 'عقیل', '<span class=\"hlight\">عقیل .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (اِخ ) ابن کعب بن ربیعةبن عامربن صعصعة، از عدنان . جدی است جاهلی . وبرخی از فرزندان او امارت کوفه و شهرهای فرات را داشتند و بر موصل نیز دست یافتند. و چون سلجوقیان این شهرها را تسخیر کردند آنان به بحرین که زادگاه اصلی آنان بود، کوچ کردند. قبیله ٔ بنی ربیعةبن عقیل که از قبایل توانای جاهلیت بود، از این نسل بشمار می آیند. توبةبن الحمیر و مجنون لیلی الاخیلیة از شاعران این قبیله اند، و بشاربن برد شاعر از موالی ایشان است . (از الاعلام زرکلی ) (از فرهنگ فارسی معین ). و رجوع به مآخذذیل شود: ابن خلدون ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٤</span>، نهایةالارب قلقشندی، ابن خلکان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٤</span>، الذریعة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٤</span>، الرجل نجاشی .<br></font></div>'),
(185072, 'عقیل', '<span class=\"hlight\">عقیل .</span> <font color=\"DarkGreen\"><b>[ ع ُق َ ]</font></b> (اِخ ) ابن خالدبن عَقیل ایلی، مکنی به ابوخالد، از موالی بنی امیه . وی از حافظان حدیث بود و از «شرطیان » مدینه بشمار می آمد. عقیل به سال <span class=\"hlight\" dir=\"rtl\">١٤١</span> هَ . ق . در مصر درگذشت . (از الاعلام زرکلی از تهذیب التهذیب ).<br></font></div>'),
(185073, 'عقیل', '<span class=\"hlight\">عقیل .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عُلَّفةبن حارث بن معاویه ٔ یربوعی مری ضبابی ذبیانی، مکنی به ابوالعمیس . از شاعران دولت بنی امیه . وی از اشراف قوم خود بود و دخترش «جرباء» زوجه ٔ یزیدبن عبدالملک بوده است . عقیل در حدود سال <span class=\"hlight\" dir=\"rtl\">١٠٠</span> هَ . ق .درگذشته است . (از الاعلام زرکلی از الاغانی و سمط اللاَّلی و خزانه ٔ بغدادی و رغبة الاَّمل و جمهرة الانساب ).<br></font></div>'),
(185074, 'عقیل آباد', '<span class=\"hlight\">عقیل آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است از دهستان قره کهریز، بخش سربند، شهرستان اراک . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٨٩٥</span> تن است . آب آن از قنات و در فصل بهار از رود محلی و محصول آن غلات و صیفی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(185075, 'عقیلا', '<span class=\"hlight\">عقیلا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) اسم عربی غوره است . (تحفه ٔ حکیم مؤمن ) (فهرست مخزن الادویه ).<br></font></div>'),
(185076, 'عقیلة', '<span class=\"hlight\">عقیلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دختر عقیل بن ابی طالب . از زنان شاعر عرب بود و او را با عذری و عزة و احوص داستانی است . و نیز اشعاری در مرثیه ٔ شهیدان کربلا دارد.و برخی او را همسر یکی از پسران عقیل بن ابی طالب دانند. رجوع به اعلام النساء ج <span class=\"hlight\" dir=\"rtl\">٣</span> و تاریخ طبری و الموشح مرزبانی و الاغانی و مروج الذهب و العقد الفرید شود.<br></font></div>'),
(185077, 'عقیلة', '<span class=\"hlight\">عقیلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع ص ) مؤنث عَقیل . رجوع به عقیل شود. <BR><font color=\"Blue\">◄</font> زن کریمه ٔ مخدره ٔ گرامی قبیله . (منتهی الارب ). کریمه ٔ مخدره . (اقرب الموارد) <span class=\"hlight\">:</span> در عهد ایلک خان عقیله ای از مخدرات اولاد او از بهر امیر جلیل ابوسعید مسعود نامزدکرده بود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٣٩٥</span>). <BR><font color=\"Blue\">◄</font> مهتر قوم . <BR><font color=\"Blue\">◄</font> شتر گرامی . <BR><font color=\"Blue\">◄</font> گرامی از هر چیزی . (منتهی الارب ) (از اقرب الموارد). چیزی گرامی . (دهار). بهترین هر چیز و برگزیده ترین . (غیاث اللغات ). ج، عَقائل . (اقرب الموارد) <span class=\"hlight\">:</span> <br>گرد دیوانگان عشق مگرد<br>که به عقل عقیله مشهوری .<br> <font color=\"Red\">حافظ.</font><br>- <span class=\"hlight\">عقیلةالبحر</span> ؛ در و مروارید. (از اقرب الموارد).<br> <BR><font color=\"Blue\">◄</font> (اِ) در تداول امروزین عرب زبانان، همسر و زوجه ٔ شخص . <BR><font color=\"Blue\">◄</font> تعهد و پیمان . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> پای بند و رسن . (غیاث اللغات ). ریسمانی که بدان ساق و وظیف شتر را بندند. <BR><font color=\"Blue\">◄</font> مایه ٔ گرفتاری . (فرهنگ فارسی معین ) <span class=\"hlight\">:</span> سلطان ماضی مردی بود مستبدرای خویش، و آن خطا بکرد و چندان عقیله پیدا آمد تا ایشان را قفا بدریدند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٦٧</span>).<br>با بهان رای زن ز بهر بهی <br>کز دو عقل از عقیله ای برهی .<br> <font color=\"Red\">سنائی .</font><br>قدم صدق یافت نقل از وی <br>وز عقیله برست عقل از وی .<br> <font color=\"Red\">سنائی .</font><br>دین حق را بحق توئی برهان <br>مر مرا زین عقیله ها برهان .<br> <font color=\"Red\">سنائی .</font><br>در هفت دوزخ از چه کنی چارمیخشان <br>ویل لهم عقیله ٔ من بس  عقابشان .<br> <font color=\"Red\">خاقانی .</font><br>در علقه ٔ آن اعلاق و عقیله ٔ آن عقایل فرومانده بود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٦٤</span>).<br>چون که عقل تو عقیله ٔ مردم است <br>آن نه عقل است آن که مار و کژدم است .<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(185078, 'عقیلة', '<span class=\"hlight\">عقیلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) از موالی بنی فزارة. از زنان محدث بود. عقیلة از سلامة دختر حر روایت دارد. و طلحة ام غراب از او روایت کرده است . (از اعلام النساء به نقل از العقدالفرید و نهایة الارب ).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(185079, 'عقیلة', '<span class=\"hlight\">عقیلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) از زنان مغنی و آوازه خوان بود. وی معاصر معبد، مغنی مشهور بوده است . (از اعلام النساء به نقل از العقدالفرید و نهایة الارب ).<br></font></div>'),
(185080, 'عقیلة', '<span class=\"hlight\">عقیلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دختراسمربن مضرس . از زنان محدث بود و حدیث را از پدرش روایت کرده است و دخترش سویدة دختر جابر، از او روایت دارد. (از اعلام النساء به نقل از تهذیب التهذیب ).<br></font></div>'),
(185081, 'عقیلة', '<span class=\"hlight\">عقیلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دختر ضحاک بن عمروبن محرق بن منذربن ماءالسماء. از زنان شاعر عرب بود و او را با فرزدق شاعر داستانی است . و گویند وی در عشق پسر عمش عمروبن کعب بن محرق درگذشت . رجوع به اعلام النساء ج <span class=\"hlight\" dir=\"rtl\">٣</span> و الاغانی شود.<br></font></div>'),
(185082, 'عقیلة', '<span class=\"hlight\">عقیلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دختر عبیدبن حارث عتواریة؛ از زنان مهاجر بود که با پیامبر اسلام (ص ) بیعت کرد. و دخترش حجة دختر قریط، از او روایت دارد. (از اعلام النساء از الاستیعاب ).<br></font></div>'),
(185083, 'عقیلة', '<span class=\"hlight\">عقیلة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) (محمد...) ابن احمدبن سعید حنفی مکی، ملقب به شمس الدین . از مورخان و محدثان قرن دوازدهم هجری بود و به سال <span class=\"hlight\" dir=\"rtl\">١١٥٠</span> هَ . ق . در مکه درگذشت . او راست : لسان الزمان، درتاریخ . الفوائد الجلیلة در حدیث . المواهب الجزیلة. هدایةالخلاق الی الصوفیة فی سائرالافاق . عقد الجواهر فی سلاسل الاکابر و سایر تألیفات . (از اعلام زرکلی به نقل از سلک الدرر و الرسالة المستطرفة و نظم الدرر).<br></font></div>'),
(185084, 'عقیلی', '<span class=\"hlight\">عقیلی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ص نسبی ) منسوب به عقیل بن ابی طالب است . قاسم بن محمدبن عبداﷲبن محمدبن عتیل بن ابی طالب عقیلی محدث، بدین نسبت شهرت دارد. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(185085, 'عقیلی', '<span class=\"hlight\">عقیلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (اِخ ) ظالم بن مرهوب عقیلی . از فرماندهان قرن چهارم هجری . وی دو بار بر دمشق استیلا یافت یکی به سال <span class=\"hlight\" dir=\"rtl\">٣٥٧</span> هَ . ق . و دیگر به سال <span class=\"hlight\" dir=\"rtl\">٣٥٨</span> هَ . ق . و به سال <span class=\"hlight\" dir=\"rtl\">٣٦٣</span> هَ . ق . از جانب المعز العبیدی صاحب مصر، والی آنجا گشت و بعلبک را نیز تصرف کرد. عقیلی به سال <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> هَ . ق . از دمشق رانده شد و از آن پس شرحی از زندگی وی در دست نیست . (از الاعلام زرکلی به نقل از تهذیب ابن عساکر و النجوم الزاهرة و الکامل ابن الاثیر).<br></font></div>'),
(185086, 'عقیلی', '<span class=\"hlight\">عقیلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (اِخ ) بدران بن مقلد عقیلی . از امیران قرن پنجم هجری . وی به سال <span class=\"hlight\" dir=\"rtl\">٤١٩</span> هَ . ق . بر نصیبین استیلا یافت و در آن زمان نصیبین از آن نصرالدولةبن مروان بود. و پس از چند زد و خورد، به اتفاق هم بر این شهر حکومت کردند. بدران عقیلی به سال <span class=\"hlight\" dir=\"rtl\">٤٢٥</span> هَ . ق . در این شهر درگذشت . (از الاعلام زرکلی به نقل از الکامل ابن الاثیر).<br></font></div>'),
(185087, 'عقیلی', '<span class=\"hlight\">عقیلی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) علی بن حسین بن حیدرة.از شاعران قرن پنجم هجری . رجوع به علی عقیلی شود.<br></font></div>'),
(185088, 'عقیلی', '<span class=\"hlight\">عقیلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (اِخ ) احمدبن یحیی بن زهیر، مکنی به ابوالحسن . از قاضیان حنفی در قرن پنجم هجری . وی به سال <span class=\"hlight\" dir=\"rtl\">٣٨٠</span> هَ .ق . در حلب متولد شد سپس سمت قضاوت آنجا را به عهده گرفت . کمال الدین ابن العدیم از نوادگان وی بشمار آید. درگذشت عقیلی به سال <span class=\"hlight\" dir=\"rtl\">٤٢٤</span> هَ . ق . رخ داد. او راست : الخلاف بین ابی حنیفه و اصحابه و ما انفرد به عنهم . (از الاعلام زرکلی از الجواهرالمضیة).<br></font></div>'),
(185089, 'عقیلی', '<span class=\"hlight\">عقیلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (اِخ ) ابراهیم بن قریش بن بدران عقیلی . امیر بنی عقیل و صاحب موصل در قرن پنجم هجری .وی در عهد حکومت برادرش مسلم بن قریش در زندان بود وبه سال <span class=\"hlight\" dir=\"rtl\">٤٧٨</span> هَ .ق . پس از کشته شدن مسلم از زندان آزاد شد و پس از دو سال به حکومت موصل گماشته شد. به سال <span class=\"hlight\" dir=\"rtl\">٤٨٢</span> هَ . ق . سلطان ملکشاه او را دستگیر ساخت و پس از درگذشت ملکشاه دیگر بار به حکومت موصل رسید و درسال <span class=\"hlight\" dir=\"rtl\">٤٨٦</span> هَ . ق . به دست تتش ارسلان والی شام دستگیر شد و به قتل رسید. (از الاعلام زرکلی از ابن خلدون ).<br></font></div>'),
(185090, 'عقیلی', '<span class=\"hlight\">عقیلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (ص نسبی ) منسوب به عقیل بن کعب بن ربیعةبن عامربن صعصعةبن معاویةبن بکر. ابوعبدالرحمان عبداﷲبن شقیق عقیلی بصری بدین نسبت شهرت دارد و او تابعی بود. (از اللباب فی تهذیب الانساب ).<br></font></div>'),
(185091, 'عقیلی', '<span class=\"hlight\">عقیلی .</span> <font color=\"DarkGreen\"><b>[ ع ُق ْ ق َ لا ]</font></b> (ع اِ) غوره ٔ خرما. (منتهی الارب ). حصرم و غوره، و وجه تسمیه ٔ آن گویا بجهت «عقل » و بند آوردن شکم خورنده ٔ آن است . (از اقرب الموارد).<br></font></div>'),
(185092, 'عقیلی', '<span class=\"hlight\">عقیلی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) یکی از بخش ها و نیز از دهستانهای شهرستان شوشتر. این بخش محدود است از شمال خاوری به شوشتر از مشرق به دهستان گتوند. مرکز دهستان و بخش عقیلی سماله میباشد. این بخش از دهستان عقیلی تشکیل شده است و دارای <span class=\"hlight\" dir=\"rtl\">١٩</span> قریه ٔ بزرگ و کوچک است . جمعیت آن در حدود <span class=\"hlight\" dir=\"rtl\">٨</span>هزار تن است . آب مصرفی اهالی از نهر و چشمه و چاه تأمین میشود و محصول عمده ٔ آن غلات است . ساکنان آن اغلب بختیاری هستند و قرای مهم این بخش عبارتند از: ترکاکلی که <span class=\"hlight\" dir=\"rtl\">١٢٠٠</span> تن جمعیت دارد، وارک با <span class=\"hlight\" dir=\"rtl\">١١٠٠</span> تن سکنه . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(185093, 'عقیلی', '<span class=\"hlight\">عقیلی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) علی بن عبداﷲبن محمدبن عبدالباقی . از فاضلان قرن پنجم هجری . رجوع به علی عقیلی شود.<br></font></div>'),
(185094, 'عقیلی', '<span class=\"hlight\">عقیلی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) علی بن مسلم . آخرین تن از حکام بنی عقیل در قرن پنجم هجری . رجوع به علی عقیلی شود.<br></font></div>'),
(185095, 'عقیلی', '<span class=\"hlight\">عقیلی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) عمربن محمدبن عمر، مکنی به ابوحفص و ملقب به شرف الدین . وی از نسل عقیل بن ابی طالب و از اهالی بخاری بود و به حدیث اشتغال داشت . او راست الهادی، در علم کلام - و منهاج الفتاوی، در فقه .عقیلی به سال <span class=\"hlight\" dir=\"rtl\">٥٧٦</span> هَ .ق . درگذشت . (از الاعلام زرکلی از الفوائد البهیة و الجواهر المضیة و کشف الظنون ).<br></font></div>'),
(185096, 'عقیلی', '<span class=\"hlight\">عقیلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (اِخ ) قُحَیف بن خمیربن سلیم عقیلی . از شاعران عرب اوایل قرن دوم هجری . او را از طبقه ٔ دهم اسلامیین بشمار آورده اند. قحیف معاصر ذی الرمة بود و او را تشبیبی است در مورد معشوقه اش «خرقاء». درگذشت او در حدود سال <span class=\"hlight\" dir=\"rtl\">١٣٠</span> هَ . ق . رخ داد. و از او دیوان کوچکی در دست است . (از الاعلام زرکلی از خزانةالادب بغدادی ).<br></font></div>'),
(185097, 'عقیلی', '<span class=\"hlight\">عقیلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (اِخ ) محمدبن عمروبن موسی بن حمادعقیلی مکی، مکنی به ابوجعفر. از محدثان قرن سوم و چهارم هجری . وی در حرمین سکنی داشت و به سال <span class=\"hlight\" dir=\"rtl\">٣٢٢</span> هَ .ق . در مکه درگذشت . او راست : الضعفاء. (از الاعلام زرکلی به نقل از تذکرةالحفاظ والتبیان و شذرات الذهب ).<br></font></div>'),
(185098, 'عقیلی', '<span class=\"hlight\">عقیلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (اِخ ) محمدبن یوسف عقیلی حورانی، مکنی به ابوعبداﷲ. فقیه و از اصحاب ابوحنیفه بود و مدتی مدرس جامع قلعه در دمشق بوده است .وی به سال <span class=\"hlight\" dir=\"rtl\">٥٦٤</span> هَ .ق . درگذشت . (از معجم البلدان ).<br></font></div>'),
(185099, 'عقیلی', '<span class=\"hlight\">عقیلی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ]</font></b> (اِخ ) مزاحم بن حارث، یا مزاحم بن عمروبن مرةبن حارث از بنی عقیل بن کعب، از عامربن صعصعة. از شاعران عرب اوایل قرن دوم هجری و معاصر جریر و فرزدق . جریر و فرزدق و ذی الرمة به برتری مزاحم در شعر غزل اقرار داشتند. وی در حدود سال <span class=\"hlight\" dir=\"rtl\">١٢٠</span> هَ . ق . درگذشت . (از الاعلام زرکلی از خزانةالادب بغدادی و طبقات فحول الشعراء و الاغانی ).<br></font></div>'),
(185100, 'عقیلی نژاد', '<span class=\"hlight\">عقیلی نژاد.</span> <font color=\"DarkGreen\"><b>[ ع ُ ق َ ن ِ ]</font></b> (ص مرکب ) صاحب سندبادنامه (ص <span class=\"hlight\" dir=\"rtl\">٢٥١</span>) آن را صفت اسب آورده است، منسوب به سرزمینی یا شخصی <span class=\"hlight\">:</span> و در زیر ران آورد اغری محجلی عقیلی نژاد از نسل اعوج و لاحق، ماه جبهتی، مشتری طلعتی، صخره گذاری، صحرانوردی، کوه پیکری، زمین هیکلی، ابر رفتاری، رعد آوازی ...<br></font></div>'),
(185101, 'عقیم', '<span class=\"hlight\">عقیم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) رجل عقیم ؛ مرد که فرزند نشود او را. ج، عُقَماء و عِقام و عَقْمی ̍. (از منتهی الارب ) (از اقرب الموارد). نازاینده، خواه مرد باشد خواه زن، در این لفظ مذکر و مؤنث برابر است ؛ و مرد عقیم آن است که نطفه ٔ او قابل زرع نباشد. (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> امراءة عقیم ؛ زن نازاینده . (منتهی الارب ) (دهار). عُقم دار بودن ؛ یعنی زن که نزاید. (از اقرب الموارد). نازاینده . (ترجمان القرآن جرجانی ). سترون . (صحاح الفرس ). ج، عَقائم و عُقُم . عُقْم . (منتهی الارب ) (اقرب الموارد) <span class=\"hlight\">:</span> فأقبلت امرأته فی صرة فصکت وجهها و قالت عجوز عقیم . (قرآن <span class=\"hlight\" dir=\"rtl\">٢٩/٥١</span>)؛ پس زنش بفریاد پرداخت و به روی خود زد و گفت پیرزنی نازا هستم . أو یزوجهم ذکرانا و اناثا و یجعل من یشاء عقیما. (قرآن <span class=\"hlight\" dir=\"rtl\">٤٩/٤٢</span>). و یا هر دو را به ایشان میدهد هم نر و هم ماده، و هر کس را بخواهد عقیم و نازا کند.<br>زاده و زاینده چون گوید که کیست <br>هر دو بنده ٔ تست زاینده و عقیم .<br> <font color=\"Red\">ناصرخسرو.</font><br>سوی فرزند کسی شو که به فرمان خدای <br>مادروحی و رسالات بدو گشت عقیم .<br> <font color=\"Red\">ناصرخسرو.</font><br>شده گیتی به چون تو راد بخیل <br>گشته گردون به چون تو مرد عقیم .<br> <font color=\"Red\">مسعودسعد.</font><br>زمانه مادر اقبال گشت و زاد ترا<br>نظیر تو نتواند که شد عجوز و عقیم .<br> <font color=\"Red\">سوزنی .</font><br>دهر است پیرمردی زال عقیم دنیا<br>چون بادریسه یک چشم این زال بدفعالش .<br> <font color=\"Red\">خاقانی .</font><br>ز یک نفخه ٔ روح عدلش چو مریم <br>عقیم خزان بکر نیسان نماید.<br><font color=\"Red\">خاقانی .</font><br>بر آستانه ٔ وحدت سقیم خوشتردل <br>به پالکانه ٔ جنت عقیم به حورا .<br> <font color=\"Red\">خاقانی .</font><br>ای به حسن تو صنم چشم فلک نادیده <br>ای ز مثل تو ولد مادر ایام عقیم .<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> رحم عقیم ؛ زهدان که قبول آبستن نکند. (منتهی الارب ). رحم که قبول فرزند نکند. (از اقرب الموارد). عقیمة. و رجوع به عقیمة شود. <BR><font color=\"Blue\">◄</font> مجازاً، بیحاصل . بی ثمر. (فرهنگ فارسی معین ): رنج عقیم ؛ زحمت بی فایده و محنت بیهوده . (ناظم الاطباء)<span class=\"hlight\">:</span> <br>جنبش اختر نیاید جز عقیم <br>برندارد جز که آن لطف عمیم .<br> <font color=\"Red\">مولوی .</font><br> <BR><font color=\"Blue\">◄</font> ریح عقیم ؛ باد که نه ابر آورد و نه باردار کند درخت را. (منتهی الارب ) (از اقرب الموارد). باد بی منفعت . (ترجمان القرآن جرجانی ). باد بی منفعت که ابر نیارد و درخت را آبستن نکند. (دهار). باد بی هنر. (دستوراللغة) <span class=\"hlight\">:</span> و فی عاد اًذ أرسلنا علیهم الریح العقیم . (قرآن <span class=\"hlight\" dir=\"rtl\">٤١/٥١</span>)؛ و در عاد، آنگاه که باد بی نفع را برایشان فرستادیم .<br>آنجا که عقیم خشم تو آذر<br>آنجا که نسیم صلح تو نیسان .<br> <font color=\"Red\">منجیک .</font><br>طفل مشیمه ٔ رزان بکر مشاطه ٔ خزان <br>حامله ٔ بهار از آن باد عقیم آذری .<br> <font color=\"Red\">خاقانی .</font><br> <BR><font color=\"Blue\">◄</font> حرب عقیم ؛ جنگ سخت . <BR><font color=\"Blue\">◄</font> عقل عقیم ؛ خرد که صاحب خود را نفع نبخشد. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> الملک عقیم ؛ یعنی در ملک و سلطنت، نسب سودی ندارد چه در طلب آن، پدر و برادر و عم و فرزند به قتل میرسد، و وجه تسمیه ٔ آن قطعصله ٔ رحم است هنگام نزاع بر آن . (از اقرب الموارد) (از منتهی الارب ) <span class=\"hlight\">:</span> <br>چون دهد ملک خدا باز هم او بستاند<br>پس چرا گویند اندرمثل الملک عقیم .<br> <font color=\"Red\">بوحنیفه ٔ اسکافی .</font><br>تیغ برگیر و می ز دست بنه <br>گر شنیدی که هست ملک عقیم .<br> <font color=\"Red\">بوحنیفه ٔ اسکافی (از تایخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٨٨</span>).</font><br>پس چرا گویند اندر مثل الملک عقیم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٩٠</span>).<br>ملک عقیم گشته ز آل یزید گفتا<br>کز نفس دین طراز توبه حیدری ندارم .<br> <font color=\"Red\">خاقانی .</font><br>آن شنیدستی که الملک عقیم <br>ترک خویشی جست ملکت جو ز بیم .<br> <font color=\"Red\">مولوی .</font><br><BR><font color=\"Blue\">◄</font> روز قیامت، بدان جهت که بعد آن روزی نیست، این جهان که صاحب خود را نیکی نرساند. (منتهی الارب ). گویند یوم القیامة یوم عقیم، زیرا خیر در آن قطع میگردد و پس از آن روزی نیست . (از اقرب الموارد). روز بی خیر. (دهار) <span class=\"hlight\">:</span> و لایزال الذین کفروا فی مریة منه حتی تأتیهم الساعة بغتة أو یأتیهم عذاب یوم عقیم . (قرآن <span class=\"hlight\" dir=\"rtl\">٥٤/٢٢</span>)؛ و آنان که کفر کردند، پیوسته از آن در شک هستند تا ناگهان قیامت بر ایشان بیاید یا عذاب روزی بی خیر ایشان را دریابد. <BR><font color=\"Blue\">◄</font> یوم عقیم ؛ روز بدر. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> در اصطلاح منطق، هر قیاسی است که نتیجه ندهد، مقابل منتج . (یادداشت مرحوم دهخدا).<br></font></div>'),
(185102, 'عقیم', '<span class=\"hlight\">عقیم .</span> <font color=\"DarkGreen\"><b>[ع ُ ق َ ]</font></b> (اِخ ) ابن زیاد. تابعی است . (منتهی الارب ).<br></font></div>'),
(185103, 'عقیم شدن', '<span class=\"hlight\">عقیم شدن .</span> <font color=\"DarkGreen\"><b>[ ع َ ش ُ دَ ]</font></b> (مص مرکب ) نازا شدن . سترون شدن . و رجوع به عقیم شود.<br></font></div>'),
(185104, 'عقیم کردن', '<span class=\"hlight\">عقیم کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ دَ ]</font></b> (مص مرکب ) نازا کردن . سترون کردن . <BR><font color=\"Blue\">◄</font> اخته کردن . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> بی حاصل کردن . بی ثمر ساختن . (فرهنگ فارسی معین ). <BR><font color=\"Blue\">◄</font> در اصطلاح پزشکی، عاری از میکرب ساختن . (فرهنگ فارسی معین ). و رجوع به عقیم شود.<br></font></div>'),
(185105, 'عقیم گذاشتن', '<span class=\"hlight\">عقیم گذاشتن .</span> <font color=\"DarkGreen\"><b>[ ع َ گ ُ ت َ ]</font></b> (مص مرکب ) بی نتیجه کردن . بی ثمر قرار دادن . رجوع به عقیم شود.<br></font></div>'),
(185106, 'عقیمة', '<span class=\"hlight\">عقیمة.</span> <font color=\"DarkGreen\"><b>[ ع َم َ ]</font></b> (ع ص ) مؤنث عقیم . رجوع به عقیم شود. <BR><font color=\"Blue\">◄</font> رحم عقیمة؛ زهدان که قبول آبستن نکند. (منتهی الارب ) (از اقرب الموارد). عقیم . و رجوع به عقیم شود.<br></font></div>'),
(185107, 'عقینی', '<span class=\"hlight\">عقینی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) علی بن محمد، مفسر و نحوی قرن یازدهم هجری . رجوع به علی عقینی شود.<br></font></div>'),
(185108, 'عقیون', '<span class=\"hlight\">عقیون .</span> <font color=\"DarkGreen\"><b>[ ع ِ ی َ ]</font></b> (اِخ ) دریایی است از باد زیر عرش، و در آن ملائکه ای است از باد و با آنان نیزه هایی است از باد، و به عرش مینگرند و تسبیح آنان «سبحانه ربناالاعلی » می باشد. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185109, 'عل', '<span class=\"hlight\">عل .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ل ]</font></b> (ع مص ) دوباره آب خوراندن . (منتهی الارب ) (اقرب الموارد). دیگرباره شراب دادن . (تاج المصادر) (مصادر زوزنی ). <BR><font color=\"Blue\">◄</font> نیک رنگ دادن چرم را. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیاپی زدن . (تاج المصادر) (اقرب الموارد). سئل تابعی عمن ضرب رجلاً فقتله، فقال اذا عله ضرباً ففیه القود. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتران را پیش از سیراب شدن بازگرداندن . <BR><font color=\"Blue\">◄</font> ماده شتر را صبح وظهر و شب دوشیدن . (ذیل اقرب الموارد). <BR><font color=\"Blue\">◄</font> دوباره آب خوردن . دوباره آشامیدن . (منتهی الارب ) (اقرب الموارد). دیگرباره شراب خوردن . (تاج المصادر) (مصادر زوزنی ). <BR><font color=\"Blue\">◄</font> بیمار شدن . (منتهی الارب ).<br></font></div>'),
(185110, 'عل', '<span class=\"hlight\">عل .</span> <font color=\"DarkGreen\"><b>[ ع َل ل ]</font></b> (ع ص، اِ) کنه ٔ لاغر. <BR><font color=\"Blue\">◄</font> کنه ٔ فربه . از اضداد است . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد کلان سال و حقیر و نزار. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ریزه اندام از هر چیزی . <BR><font color=\"Blue\">◄</font> تکه ٔ بزرگ جثه . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد که صحبت زنان، و محادثت با آنها را دوست دارد. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آنکه زنان را بسیار دیدار کند. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنکه پوستش از بیماری ترنجیده باشد. (منتهی الارب ) (اقرب الموارد). ج، أعلال . <BR><font color=\"Blue\">◄</font> آنکه نیکی و خوبی ندارد. (ذیل اقرب الموارد).<br></font></div>'),
(185111, 'عل', '<span class=\"hlight\">عل .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ع َل ْ ل ِ ]</font></b> (ع حرف ) از حروف مشبهة بالفعل بمعنای لعل ّ است . و بعضی بر آنند که اصل و ریشه ٔ لعل همین عل است، و لام آن زائد است . مانند «لاتهین الفقیر علک أن ترکع یوماً، و الدهر قد رفعه ». عل و لعل در معنی مانند عسی، و در عمل مانند ان مشبهة بالفعل اند، اما قبیله ٔ عقیل آن دو را حرف جر دانند. و کوفیان منصوب ساختن جواب آن دو را جائز شمرند بر اساس قرائت حفص : «لعلی أبلغ الاسباب اسباب السماوات فاطلع». ابن مالک مجزوم شدن فعل بعد از لعل را جائز داند در صورتی که فاء آن حذف شده باشد:<br>لعل التفاتاً منک نحوی مقدر<br>یمل بک من بعد القساوة للرحم .<br><font color=\"Red\">(از مغنی اللبیب ).</font><br></font></div>'),
(185112, 'عل', '<span class=\"hlight\">عل .</span> <font color=\"DarkGreen\"><b>[ ع ُل ل <span class=\"hlight\" dir=\"rtl\">/</span> ع ِل ل ]</font></b> (ع اِ) ج ِ عُلعُل . (لسان العرب و شرح قاموس از ذیل اقرب الموارد). اما ازهری گوید جمع علعل، عُلُل و عَلاعل است . (ذیل اقرب الموارد).<br></font></div>'),
(185113, 'علا', '<span class=\"hlight\">علا.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا ]</font></b> (اِخ ) قصبه ٔ مرکز دهستان علاء از بخش مرکزی شهرستان سمنان واقع در <span class=\"hlight\" dir=\"rtl\">٩</span>هزارگزی جنوب خاوری سمنان و <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی شمال راه شوسه ٔ سمنان به دامغان و <span class=\"hlight\" dir=\"rtl\">٢</span> هزار و پانصد گزی ایستگاه میان دره . سکنه ٔ آن در حدود هزار تن . آب آن از قنات تأمین میشود. محصولات آن غلات و پنبه و پسته و میوه و صیفی است . یک مناره از آثار قدیم دارد. شغل مردان زراعت و هیزم فروشی است . صنایع دستی زنان کرباس بافی میباشد. دارای راه فرعی و دبستان است . مزارع تقی آباد و حسین آباد که هر یک چند تن سکنه دارد و نیز مزارع غیرمسکونی بنام غیاث آباد و محمدآباد و احمدآباد و نوکلاته جزء این قصبه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(185114, 'علا', '<span class=\"hlight\">علا.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا ]</font></b> (اِخ ) یکی از دهستانهای بخش مرکزی شهرستان سمنان واقع در قسمت جنوب باختری سمنان . دارای آب و هوای معتدل و خشک . آب قراء آن از قنوات تأمین میشود و محصولات عمده ٔ آن غلات وپنبه و تنباکو و صیفی است . راه شوسه ٔ سمنان به دامغان تقریباً از شمال دهستان و راه آهن از وسط دهستان میگذرد. و ایستگاههای میان دره، گرم آب، گراب در طول دهستان واقع است . این دهستان از <span class=\"hlight\" dir=\"rtl\">١٥</span> آبادی بزرگ و کوچک، و در حدود <span class=\"hlight\" dir=\"rtl\">٤٨</span> مزرعه تشکیل شده است . جمع سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٤٨٠٠</span> تن است . مرکز دهستان قصبه ٔ علا، و قراء مهم آن جام، رکن آباد، خیرآباد و دوزهیر است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>). علاّء. (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٢١٠</span>).<br></font></div>'),
(185115, 'علا', '<span class=\"hlight\">علا.</span> <font color=\"DarkGreen\"><b>[ ع ُ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ]</font></b> (ع اِمص ) بلندی و بزرگی . (غیاث از صراح ) <span class=\"hlight\">:</span> <br>دولتت دولت علائی را<br>مایه و پایه ٔ علا باشد.<br> <font color=\"Red\">مسعودسعد.</font><br>اقبال شاه چون ز علا وسنا شده ست <br>من جمله آفرین علا و سنا کنم .<br> <font color=\"Red\">مسعودسعد.</font><br>بر تن حشمت باقیش لباس از شرفت <br>بر سر دولت پاینده ٔ او تاج علاست .<br> <font color=\"Red\">مسعودسعد.</font><br>و رجوع به علاء شود.<br></font></div>'),
(185116, 'علاء', '<span class=\"hlight\">علاء.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِمص ) بزرگواری . (دستوراللغة). بزرگوار شدن در شرف و بلندی و بزرگواری . (دستورالاخوان ). <BR><font color=\"Blue\">◄</font> برتری . (دستور اللغة). رجوع به علا شود.<br></font></div>'),
(185117, 'علاب', '<span class=\"hlight\">علاب .</span> <font color=\"DarkGreen\"><b>[ ع ُل ْ لا ]</font></b> (ع اِ) ارزیز. (دستورالاخوان ).<br></font></div>'),
(185118, 'علاب', '<span class=\"hlight\">علاب .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) نشانی است در درازای گردن . (قطر المحیط) (منتهی الارب ) (اقرب الموارد). رجوع به علاط شود.<br></font></div>'),
(185119, 'علابط', '<span class=\"hlight\">علابط.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب ِ ]</font></b> (ع ص ) ستبر. (ناظم الاطباء) (اقرب الموارد). چهارشانه . (ذیل اقرب الموارد). <BR><font color=\"Blue\">◄</font> شیر غلیظ، و هر چیز غلیظ. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) گله ٔ گوسفند از پنجاه تا هر قدر که باشد. (ناظم الاطباء) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سنگینی شخص : ألقی علیه علابطه ؛ أی ثقله و نفسه . (اقرب الموارد). ج، عَلابط، عَلابیط. (قطر المحیط) (ناظم الاطباء).<br></font></div>'),
(185120, 'علابی', '<span class=\"hlight\">علابی .</span> <font color=\"DarkGreen\"><b>[ ع َ بی ی ]</font></b> (ع اِ) سرب، و یا جنسی از آن . (قطرالمحیط). ج ِ علباء است بمعنی شتر، و برخلاف آنچه برخی پندارند بر سرب اطلاق نمیشود. (از اقرب الموارد).<br></font></div>'),
(185121, 'علابیط', '<span class=\"hlight\">علابیط.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ علابط. (ناظم الاطباء).<br></font></div>'),
(185122, 'علات', '<span class=\"hlight\">علات .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) رجوع به علاة شود.<br></font></div>'),
(185123, 'علات', '<span class=\"hlight\">علات .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ لا ]</font></b> (ع اِ) ج ِ عِلة. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> حالات گوناگون . (اقرب الموارد) (المنجد) <span class=\"hlight\">:</span> در ایام امن و فراغت گوسفندان با شیر و پشم و منافعبسیار در حالات و علات یأس و نوش از مباینت و مخالفت نفوس فارغ باشند <font color=\"DarkGreen\"><b>[ لشکریان ]</font></b> . (جهانگشای جوینی ).<br></font></div>'),
(185124, 'علات', '<span class=\"hlight\">علات .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا ]</font></b> (ع اِ) ج ِ عَلّة. (اقرب الموارد) (ناظم الاطباء).<br>- <span class=\"hlight\">بنوالعلات </span> ؛ فرزندان مرد از مادران جداگانه . (ناظم الاطباء).<br></font></div>'),
(185125, 'علات', '<span class=\"hlight\">علات .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) سندان که بر آن آهن را نهاده می کوبند، و بهندی آن را اهرن گویند. (غیاث از شرح نصاب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سنگی که به روی آن پنیرو کشک خشک کنند. <BR><font color=\"Blue\">◄</font> قدحی ستبر که بر دور آن سرگین ریخته و در آن شیر دوشند. <BR><font color=\"Blue\">◄</font> (ص )ماده شتر بلندبالای استوار. (اقرب الموارد) (ناظم الاطباء). ج، عَلا، علوات . (اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(185126, 'علاث', '<span class=\"hlight\">علاث .</span><font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) آتش ندادن آتش زنه . (اقرب الموارد).<br></font></div>'),
(185127, 'علاج', '<span class=\"hlight\">علاج .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص، اِمص ) درمان . (اقرب الموارد) (ناظم الاطباء) <span class=\"hlight\">:</span> در کتب طب آورده اند که فاضلترین ِ اطباء آن است که بر علاج ازجهت ثواب آخرت مواظبت نماید. (کلیله ص <span class=\"hlight\" dir=\"rtl\">٨٥١</span>). به رغبتی صادق ... روی بعلاج بیماران آوردم . (کلیله ص <span class=\"hlight\" dir=\"rtl\">٥٩</span>). رنج مبر در معالجت چیزی که علاج نپذیرد. (کلیله ص <span class=\"hlight\" dir=\"rtl\">٣٢٢</span>).<br>پتیاره ٔ ظلمی بلای بخلی <br>درمان نیازی علاج آزی .<br> <font color=\"Red\">مسعودسعد.</font><br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">علاج واقعه پیش از وقوع باید کرد</span> .<br> <font color=\"Red\">سعدی .</font><br> <BR><font color=\"Blue\">◄</font> تدبیر و چاره و گزیر. (ناظم الاطباء) <span class=\"hlight\">:</span> <br>چون نمک خود تبه شودچه علاج <br>چاره چه غرقه را ز رود برک ؟<br> <font color=\"Red\">خسروی .</font><br>علاجی بکن کز دلم خون نیاید.<br> <font color=\"Red\">والهی .</font><br><BR><font color=\"Blue\">◄</font> کار و عمل . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> مزاولت نمودن چیزی . (منتهی الارب ) (ناظم الاطباء) (اقرب الموارد). زدن کسی را به شمشیر. <BR><font color=\"Blue\">◄</font> شدت دیدن از کسی . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ) دارو. (اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185128, 'علاج دادن', '<span class=\"hlight\">علاج دادن .</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ ]</font></b> (مص مرکب ) شفا دادن . (ناظم الاطباء).<br></font></div>'),
(185129, 'علاج شدن', '<span class=\"hlight\">علاج شدن .</span> <font color=\"DarkGreen\"><b>[ ع ِ ش ُدَ ]</font></b> (مص مرکب ) درمان شدن . صحت یافتن . شفا یافتن .<br></font></div>'),
(185130, 'علاج پذیر', '<span class=\"hlight\">علاج پذیر.</span> <font color=\"DarkGreen\"><b>[ ع ِ پ َ ]</font></b> (نف مرکب )قابل مداوا. درمان پذیر و چاره پذیر. (ناظم الاطباء).<br></font></div>'),
(185131, 'علاج کردن', '<span class=\"hlight\">علاج کردن .</span> <font color=\"DarkGreen\"><b>[ ع ِ ک َ دَ ]</font></b> (مص مرکب ) تیمار کردن و مروسیدن . <BR><font color=\"Blue\">◄</font> مداوا نمودن و معالجه کردن . <BR><font color=\"Blue\">◄</font> چاره نمودن و تدبیر کردن . (ناظم الاطباء). رجوع به علاج شود.<br></font></div>'),
(185132, 'علاجیم', '<span class=\"hlight\">علاجیم .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (ع اِ) ج ِ علجوم . (اقرب الموارد) (آنندراج ).<br></font></div>'),
(185133, 'علادی', '<span class=\"hlight\">علادی .</span> <font color=\"DarkGreen\"><b>[ ع ُ دا ]</font></b> (ع ص )شتر قوی . <BR><font color=\"Blue\">◄</font> ج ِ علندی . (اقرب الموارد).<br></font></div>'),
(185134, 'علارود', '<span class=\"hlight\">علارود.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است جزء دهستان طارم بالا از بخش سیردان شهرستان زنجان واقع در <span class=\"hlight\" dir=\"rtl\">٦٨</span> هزارگزی شمال باختری سیردان و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی راه عمومی . منطقه ای است کوهستانی و سردسیر. دارای <span class=\"hlight\" dir=\"rtl\">٢١٢</span> تن سکنه است و زبان اهالی آن ترکی است . آب آن از چشمه سار تأمین میشود. محصولات آن عبارت از غلات وپنبه است . شغل اهالی زراعت است . دارای راه مالرو و صعب العبور می باشد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(185135, 'علاس', '<span class=\"hlight\">علاس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) طعام . (اقرب الموارد) (المنجد).<br></font></div>'),
(185136, 'علاص', '<span class=\"hlight\">علاص .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) مال به کسی دادن به مشارکت . (منتهی الارب ) (ناظم الاطباء).<br></font></div>'),
(185137, 'علاط', '<span class=\"hlight\">علاط.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) خصومت کردن . (قطر المحیط) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) نشانی بر پهنای گردن شتر. (اقرب الموارد) (ناظم الاطباء). رجوع به علاب شود. <BR><font color=\"Blue\">◄</font> صفحه ٔ گردن . <BR><font color=\"Blue\">◄</font> رشته ٔ سوزن . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شعاع آفتاب . (اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185138, 'علاطان', '<span class=\"hlight\">علاطان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) دو صفحه ٔ گردن . (قطرالمحیط) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> طوق سیاه هر دو صفحه ٔ گردن کبوتر. (اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(185139, 'علاف', '<span class=\"hlight\">علاف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) وادیی است در یمن . (منتهی الارب ).<br></font></div>'),
(185140, 'علاف', '<span class=\"hlight\">علاف .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا ]</font></b> (ع ص ) علف فروش . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> کسی که جو و گندم و کاه و هیزم و یونجه و علف میفروشد. (ناظم الاطباء).<br></font></div>'),
(185141, 'علاف', '<span class=\"hlight\">علاف .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا ]</font></b> (اِخ ) اسحاق بن وهب . رجوع به اسحاق ... شود.<br></font></div>'),
(185142, 'علاف', '<span class=\"hlight\">علاف .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا]</font></b> (اِخ ) رجوع به ابوالهذیل (محمدبن هذیل ...) شود.<br></font></div>'),
(185143, 'علاف', '<span class=\"hlight\">علاف .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ علف . (اقرب الموارد).<br></font></div>'),
(185144, 'علاف', '<span class=\"hlight\">علاف .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) ابن طواریابن حلوان بن عمرو، از قضاعة. و رحلهای (پالان ها) علافیة بدو منسوب است، زیرااو اولین کسی است که آنها را بساخت . (منتهی الارب ).<br></font></div>'),
(185145, 'علافی', '<span class=\"hlight\">علافی .</span> <font color=\"DarkGreen\"><b>[ ع َ فی ی <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ فی ی ]</font></b> (ع اِ) بزرگترین پالانهای شتر. (اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185146, 'علافی', '<span class=\"hlight\">علافی .</span><font color=\"DarkGreen\"><b>[ ع َل ْ لا ]</font></b> (حامص ) شغل و کسب علاف . (ناظم الاطباء).<br></font></div>'),
(185147, 'علاق', '<span class=\"hlight\">علاق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) دوستی . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> نظر و نگاه . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> علف و قوت و خورش روزگذار ستور: ما لنا من علاق ؛ أی من مرتع. (منتهی الارب ) (اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ناشتاشکن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ماترک الحالب بالناقة علاقاً؛ أی لم یدع فی ضرعها شیئاً. (اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> راه . <BR><font color=\"Blue\">◄</font> چوب که از آن چرخ چاه آویزند. <BR><font color=\"Blue\">◄</font> چرخ چاه . <BR><font color=\"Blue\">◄</font> رسن دلو. <BR><font color=\"Blue\">◄</font> دلو بزرگ . <BR><font color=\"Blue\">◄</font> چرخ دلو. <BR><font color=\"Blue\">◄</font> رسن آویخته در بکره . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> گوشت پاره . (منتهی الارب ) (ناظم الاطباء).<br></font></div>'),
(185148, 'علاق', '<span class=\"hlight\">علاق .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ ]</font></b> (ع اِ فعل ) در دستور زبان عرب اسم فعل است بمعنی فعل امر، یعنی بیاویز و چنگ بزن . (قطر المحیط) (منتهی الارب ) (اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185149, 'علاق', '<span class=\"hlight\">علاق .</span> <font color=\"DarkGreen\"><b>[ ع ُل ْ لا ]</font></b> (ع اِ) یک نوع گیاه . (ناظم الاطباء).<br></font></div>'),
(185150, 'علاقات', '<span class=\"hlight\">علاقات .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ علاقه .<br></font></div>'),
(185151, 'علاقبند', '<span class=\"hlight\">علاقبند.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ب َ ]</font></b> (نف مرکب ) رجوع به علاقه بند شود.<br></font></div>'),
(185152, 'علاقمند', '<span class=\"hlight\">علاقمند.</span><font color=\"DarkGreen\"><b>[ ع َ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ م َ ]</font></b> (ص مرکب ) رجوع به علاقه مند شود.<br></font></div>'),
(185153, 'علاقمه', '<span class=\"hlight\">علاقمه .</span> <font color=\"DarkGreen\"><b>[ ع َ ق ِ م َ ]</font></b> (اِخ ) شهرکی است در قسمت شرقی سرزمین مصر، پایین بلبیس . و در آن بازارهائی است که برای عرب ها تشکیل میشود. (از معجم البلدان ).<br></font></div>'),
(185154, 'علاقه', '<span class=\"hlight\">علاقه .</span> <font color=\"DarkGreen\"><b>[ ع ِ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ]</font></b> (از ع، اِ) بند کمان و تازیانه و شمشیر و جز آن که بدان آنها را شخص بر خود می آویزد. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> هر چیز که بدان چیزی را آویزند. (منتهی الارب ) (ذیل اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه از میوه به درختان آویزان باشد. (اقرب الموارد). ج، علائق، عُلاقی ̍. <BR><font color=\"Blue\">◄</font> دنباله .<br>- <span class=\"hlight\">علاقه ٔ دستار</span> ؛ طره ٔ آن . (از غیاث اللغات )(از آنندراج ). شمله . (برهان ).<br></font></div>'),
(185155, 'علاقه', '<span class=\"hlight\">علاقه .</span><font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) دهی است از دهستان بالارخ بخش کدکن شهرستان تربت حیدریه واقع در <span class=\"hlight\" dir=\"rtl\">٤٦</span> هزارگزی شمال خاوری کدکن و <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی باختر جاده ٔ شوسه ٔ مشهد به زاهدان .آب و هوای آن معتدل و دارای <span class=\"hlight\" dir=\"rtl\">٥١٨</span> تن سکنه است . آب آن از قنات تأمین میشود. محصولات آن غلات و بنشن و زعفران . شغل اهالی زراعت و گله داری و کرباس بافی است . راه آن مالرو میباشد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(185156, 'علاقه', '<span class=\"hlight\">علاقه .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ<span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ]</font></b> (از ع، اِمص ) به دل دوست داشتن . (اقرب الموارد). دوست داشتن و خواهش آن نمودن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کشتن . (اقرب الموارد) (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِمص ) آویزش . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آویزش دل . (غیاث ). دوستی . (اقرب الموارد). دوستی لازم قلبی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> بستگی و ارتباط.<br>- <span class=\"hlight\">علاقه ٔ قرابت </span> ؛ بستگی و ارتباط خویشاوندی . (از ناظم الاطباء).<br>- <span class=\"hlight\">علاقه ٔ محبت </span> ؛ بستگی و دوستی . دوستی قلبی و حقیقی . (از ناظم الاطباء).<br><BR><font color=\"Blue\">◄</font> دشمنی .از اضداد است . (اقرب الموارد). خصومت . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> (اِ) آنچه جهت زندگانی کافی و بسنده باشد. (منتهی الارب ) (اقرب الموارد). آنچه بدان روز گذارند. <BR><font color=\"Blue\">◄</font> علف و خورش و روزگذار. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آنچه لازم گیرد آن را مرد از پیشه و جز آن . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه متعلق بمرد باشد از زن و فرزند و مال . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مَهر و کابین که بر ذمه ٔ ناکح لازم نمایند. (منتهی الارب ) (اقرب الموارد). ج، عَلائق . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مرگ . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتر که جهت خواربار همراه قوم فرستند. (منتهی الارب ) (اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> راه . (منتهی الارب ) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آنچه بر آن چرخ چاه آویزند. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> چرخ چاه . <BR><font color=\"Blue\">◄</font> رسن دلو. <BR><font color=\"Blue\">◄</font> دلو بزرگ . <BR><font color=\"Blue\">◄</font> چرخ دلو. <BR><font color=\"Blue\">◄</font> رسن آویخته در بکره . (منتهی الارب )(آنندراج ). <BR><font color=\"Blue\">◄</font> بهترین مال . (منتهی الارب ) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> مال قیمتی . (منتهی الارب ) (آنندراج ). ج، علائق .<br></font></div>'),
(185157, 'علاقه بند', '<span class=\"hlight\">علاقه بند.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ب َ ]</font></b> (اِخ ) دهی است جزء دهستان برغان بخش کرج شهرستان تهران واقع در <span class=\"hlight\" dir=\"rtl\">٣٣</span>هزارگزی شمال باختری کرج و <span class=\"hlight\" dir=\"rtl\">١٦</span> هزارگزی شمال راه شوسه ٔ کرج به قزوین . منطقه ایست کوهستانی و سردسیر دارای <span class=\"hlight\" dir=\"rtl\">٧٢</span> تن سکنه . آب آن از رودخانه ٔ برغان تأمین میشود.محصولات آن غلات و لبنیات و میوه است . شغل اهالی زراعت و گله داری است . راه آن مالرو است و از طریق کردان ماشین میتوان برد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(185158, 'علاقه بند', '<span class=\"hlight\">علاقه بند.</span> <font color=\"DarkGreen\"><b>[ ع ِق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ب َ ]</font></b> (نف مرکب ) آنکه ابریشم بافد و رشته و غیره از ابریشم سازد. و بهندی پطوه گویند. (آنندراج ). <BR><font color=\"Blue\">◄</font> سازنده ٔ نوار و قیطان . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> کسی که ابریشم تابیده و نوار و قیطان فروشد. (ناظم الاطباء).<br></font></div>'),
(185159, 'علاقه بندی', '<span class=\"hlight\">علاقه بندی .</span> <font color=\"DarkGreen\"><b>[ ع ِ <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ب َ ]</font></b> (حامص مرکب ) شغل علاقه بند. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ مرکب ) محل علاقه بند. دکان علاقه بندی .<br></font></div>'),
(185160, 'علاقه جنبان', '<span class=\"hlight\">علاقه جنبان .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ جُم ْ]</font></b> (اِخ ) دهی است از دهستان کهنه فرود بخش حومه ٔ شهرستان قوچان واقع در <span class=\"hlight\" dir=\"rtl\">٩</span> هزارگزی جنوب باختری قوچان و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی باختر راه شوسه ٔ عمومی مشهد به قوچان . سرزمین آن جلگه است و دارای آب و هوای معتدل . جمعیت آن <span class=\"hlight\" dir=\"rtl\">١٥٧</span> تن است . آب آن از قنات تأمین میشود. محصول آن غلات است . شغل اهالی زراعت و مالداری و قالیچه بافی است . راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(185161, 'علاقه دار', '<span class=\"hlight\">علاقه دار.</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ]</font></b> (نف مرکب ) دارنده ٔ علاقه . علاقمند. کسی که تعلق خاطر دارد. کسی که دوست دارد. رجوع به علاقه شود. <BR><font color=\"Blue\">◄</font> مرتبط. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> منسوب . <BR><font color=\"Blue\">◄</font> متعلق . <BR><font color=\"Blue\">◄</font> کسی که مسؤول مالیات محل ویا ده باشد. (ناظم الاطباء). رجوع به علاقه مند شود.<br></font></div>'),
(185162, 'علاقه مند', '<span class=\"hlight\">علاقه مند.</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span>ع ِ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ م َ ]</font></b> (ص مرکب ) محب دوستار. خواستار. به دل دوست دارنده . دارای علاقه . علاقه دار. <BR><font color=\"Blue\">◄</font> مرتبط. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> منسوب . <BR><font color=\"Blue\">◄</font> متعلق . <BR><font color=\"Blue\">◄</font> کسی که مسؤول مالیات محل ویا ده باشد. (ناظم الاطباء). رجوع به علاقه دار شود.<br></font></div>'),
(185163, 'علاقی', '<span class=\"hlight\">علاقی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا ]</font></b> (اِخ ) حصاری است در بلادبجه در جنوب سرزمین مصر، و در آن معدن طلا وجود دارد. شخص میتواند در آن حفاری کند و اگر چیزی به دست آورد قسمتی را خود برمیدارد و قسمت دیگر ازآن ِ سلطان علاقی خواهد بود، و او از بنی حنیفه باشد. فاصله ٔ بین علاقی و عبدان هشت منزل است . (از معجم البلدان ).<br></font></div>'),
(185164, 'علاقی', '<span class=\"hlight\">علاقی .</span> <font color=\"DarkGreen\"><b>[ ع ُ قا ]</font></b> (ع اِ)ج ِ علاقیة. <BR><font color=\"Blue\">◄</font> ج ِ عِلاقة. (ناظم الاطباء).<br></font></div>'),
(185165, 'علاقی', '<span class=\"hlight\">علاقی .</span> <font color=\"DarkGreen\"><b>[ ع َ قا ]</font></b> (ع اِ) ج ِ علاقیة. (اقرب الموارد). رجوع به علاقیة شود.<br></font></div>'),
(185166, 'علاقیة', '<span class=\"hlight\">علاقیة.</span> <font color=\"DarkGreen\"><b>[ ع َ ی َ ]</font></b> (ع اِ) پاژنامه و لقب . ج، عَلاقی ̍. (اقرب الموارد) (آنندراج ). <BR><font color=\"Blue\">◄</font> کسی که وقتی به چیزی چنگ زند، دست از آن نکشد. (اقرب الموارد) (آنندراج ). <BR><font color=\"Blue\">◄</font> آنچه از شکار که ریسمان به پای او بندند. ما علّق الحبل برجل الصید. (از اقرب الموارد).<br></font></div>'),
(185167, 'علال', '<span class=\"hlight\">علال .</span> <font color=\"DarkGreen\"><b>[ ع ِ]</font></b> (ع اِمص ) دوشیدن شتر در میانه ٔ روز. (اقرب الموارد) (ناظم الاطباء). اسم است معالة را. (منتهی الارب ).<br></font></div>'),
(185168, 'علالا', '<span class=\"hlight\">علالا.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِ صوت ) بانگ و شور و غوغا. (برهان ) (ناظم الاطباء). علالوش . هیابانگ <span class=\"hlight\">:</span> <br>بجه از جو، سوی ما آ، که تماشاست در این سو<br>ستر اﷲ علینا، چه علالاست در این کو.<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">علالای سگ </span> ؛ پارس کردن او. بانگ او <span class=\"hlight\">:</span> <br>زین همه بانگ و علالای سگان <br>هیچ واماند ز راهی کاروان ؟<br> <font color=\"Red\">مولوی .</font><br><BR><font color=\"Blue\">◄</font> تشنیع. <BR><font color=\"Blue\">◄</font> کنایه و حرف پهلودار. (برهان ) (ناظم الاطباء).<br></font></div>'),
(185169, 'علالة', '<span class=\"hlight\">علالة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ]</font></b> (ع مص ) دوشیدگی شتر در میانه ٔ روز. (منتهی الارب ). دوشیدن شتر در میانه ٔ روز. (آنندراج ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نیزه زدن در پی هم <span class=\"hlight\">:</span> <br>و لولا علالة أرماحنا<br>لظلت نساؤهُم ُ تحلب .<br> <font color=\"Red\">(از ذیل اقرب الموارد).</font><br><BR><font color=\"Blue\">◄</font> پیاپی دویدن . (ذیل اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) آنچه به وی بهانه کنند وعذر آرند: ما هی الا علالة. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> شتر که بعدِ دوشیدن فیقه ٔ نخستین دوشند. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بقیه ٔ شیر در پستان . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> باقی هرچیزی . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بقیه ٔ قوت پیر. (منتهی الارب ) (لسان العرب ). <BR><font color=\"Blue\">◄</font> شخص تحصیل کرده . <BR><font color=\"Blue\">◄</font> معلم مدرسه . (ناظم الاطباء).<br></font></div>'),
(185170, 'علالی', '<span class=\"hlight\">علالی .</span> <font color=\"DarkGreen\"><b>[ ع َ لی ی ]</font></b> (ع اِ) ج ِ علیّة. (اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(185171, 'علام', '<span class=\"hlight\">علام .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) ج ِ عَلَم . (اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(185172, 'علام', '<span class=\"hlight\">علام .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع حرف جر + اسم ) مرکب از «علی » حرف جر، و «ما»ی استفهامی، الف «ما» بواسطه ٔ داخل شدن حرف جر بر آن، حذف شده است . (اقرب الموارد). مخفف «علی ما»، یعنی بر چه و بر کدام . (ناظم الاطباء).<br></font></div>'),
(185173, 'علام', '<span class=\"hlight\">علام .</span> <font color=\"DarkGreen\"><b>[ ع ُل ْلا ]</font></b> (ع ص ) بسیار دانا. (اقرب الموارد). نیک دانا. <BR><font color=\"Blue\">◄</font> عارف نسب . (منتهی الارب ). عارف به انساب مردمان . نسابه . <BR><font color=\"Blue\">◄</font> (اِ) صقر. (اقرب الموارد). چرخ . باشه . عُلام . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> حنا که بدان رنگ کنند. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مغز هسته ٔ کُنار. (ذیل اقرب الموارد). <BR><font color=\"Blue\">◄</font> ج ِ عالِم . (اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185174, 'علام', '<span class=\"hlight\">علام .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ لا ]</font></b> (ع مص ) آموزاندن . (اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آگاهانیدن (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> متصف به شجاعت نمودن . <BR><font color=\"Blue\">◄</font> نشان گذاردن شناسائی را. (اقرب الموارد).<br></font></div>'),
(185175, 'علام', '<span class=\"hlight\">علام .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا ]</font></b> (ع ص ) بسیار دانا. (اقرب الموارد). نیک دانا. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کسی که دانا به انساب مردمان باشد. نسابه . (اقرب الموارد). آنکه از نسبت مردم آگاه باشد. (منتهی الارب ).<br></font></div>'),
(185176, 'علام', '<span class=\"hlight\">علام .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) چرخ . چرغ . (منتهی الارب ). صقر. (اقرب الموارد). باشه . باشق . واشه . عُلاّم . (منتهی الارب ).<br></font></div>'),
(185177, 'علام', '<span class=\"hlight\">علام .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عَلامة. (اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(185178, 'علامات', '<span class=\"hlight\">علامات .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ عَلامة. (اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185179, 'علامات آسمانی', '<span class=\"hlight\">علامات آسمانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ت ِ س ْ <span class=\"hlight\" dir=\"rtl\">/</span> س ِ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به کائنات الجو شود.<br></font></div>'),
(185180, 'علامة', '<span class=\"hlight\">علامة.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ]</font></b> (اِخ ) احمدبن کمال پاشا. رجوع به احمد... شود.<br></font></div>'),
(185181, 'علامة', '<span class=\"hlight\">علامة.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ]</font></b> (اِخ ) احمدبن عمربن محمد زبیدی . رجوع به علامه ٔ زبیدی شود.<br></font></div>'),
(185182, 'علامة', '<span class=\"hlight\">علامة.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ]</font></b> (اِخ ) ابن حاجب عثمان بن عمر. رجوع به ابن حاجب و ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٢</span>، روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٦٨</span>، تاریخ ابن خلکان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٠</span>، هدیة الاحباب ص <span class=\"hlight\" dir=\"rtl\">٤٥</span>، لغات تاریخیه و جغرافیة احمد رفعت ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١</span>، قاموس الاعلام ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦١٦</span> شود.<br></font></div>'),
(185183, 'علامة', '<span class=\"hlight\">علامة.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ]</font></b> (اِخ ) احمدبن حسین، بدیعالزمان همدانی . رجوع به احمد (ابن حسین بن یحیی ) شود.<br></font></div>'),
(185184, 'علامة', '<span class=\"hlight\">علامة.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ]</font></b> (اِخ )ابن هشام، محمدبن یحیی . رجوع به ابن هشام و ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٣</span>، کشف الظنون، روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٧٢٧</span> شود.<br></font></div>'),
(185185, 'علامة', '<span class=\"hlight\">علامة.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ]</font></b> (اِخ ) ابن هشام، عبداﷲبن یوسف . رجوع به ابن هشام و ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٩</span>، کشف الظنون، روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٥٥</span>، الدرر الکامنة ج <span class=\"hlight\" dir=\"rtl\">٢</span>ص <span class=\"hlight\" dir=\"rtl\">٣٠٨</span>، هدیة الاحباب ص <span class=\"hlight\" dir=\"rtl\">٩٥</span>، قاموس الاعلام ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٧٩</span> شود.<br></font></div>'),
(185186, 'علامة', '<span class=\"hlight\">علامة.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ]</font></b> (اِخ ) ابن جماعه ٔ شافعی، محمدبن ابی بکر. رجوع به ابن جماعه و ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٠</span>، هدیة الاحباب ص <span class=\"hlight\" dir=\"rtl\">٤٢</span>، روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٧٤٨</span> شود.<br></font></div>'),
(185187, 'علامة', '<span class=\"hlight\">علامة.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ]</font></b> (اِخ ) ابن اثیر. مبارک بن ابی کرم جزری .رجوع به ابن اثیر و مآخذ ذیل شود: ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٣</span>، کشف الظنون، روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٦٨٥</span>، تاریخ ابن خلکان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢</span>، معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">١٧</span> ص <span class=\"hlight\" dir=\"rtl\">٧١</span>، قاموس الاعلام ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٩٩</span>.<br></font></div>'),
(185188, 'علامة', '<span class=\"hlight\">علامة.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (از ع، ص ) نیک دانا و بسیار دانا. (اقرب الموارد) (ناظم الاطباء) (غیاث ) (منتهی الارب ).و تاء آن برای مبالغه است و مذکر و مؤنث در آن یکسان می باشد <span class=\"hlight\">:</span> دو امیرزاده در مصر بودند، یکی علم آموخت و آن دگر مال اندوخت، عاقبةالامر آن یکی علامه ٔ عصر شد وین دگر عزیز مصر گشت . (گلستان سعدی ).<br>صاحبدل و نیک سیرت و علامه <br>گو کفش دریده باش و خلقان جامه .<br> <font color=\"Red\">سعدی .</font><br><BR><font color=\"Blue\">◄</font> آگاه به انساب مردمان . (اقرب الموارد). عارف به نسب مردم . (منتهی الارب ).<br></font></div>'),
(185189, 'علامة', '<span class=\"hlight\">علامة.</span> <font color=\"DarkGreen\"><b>[ع ُل ْ لا م َ ]</font></b> (ع اِ) آنچه بدان بر چیزی راه یابند و بر آن استدلال کنند. (اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185190, 'علامة', '<span class=\"hlight\">علامة.</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع اِ) رجوع به علامت شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(185191, 'علامت', '<span class=\"hlight\">علامت .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (ع اِ) علامة. نشان . (اقرب الموارد) (منتهی الارب ). ج، عَلام، علامات . و در تداول فارسی زبانان به علائم (علایم ) نیز جمع بسته شود. <BR><font color=\"Blue\">◄</font> نشانی که در راه برای رهنمونی برپا سازند.(اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> داغ . (ناظم الاطباء). نشان . <BR><font color=\"Blue\">◄</font> حد فاصل میان دو زمین . (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> علم و رایت . (ناظم الاطباء). درفش . (لغت فرس اسدی ) <span class=\"hlight\">:</span> حسن فرمود تا علامت بزرگ را پیش تر بردند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٩</span>). من بجای خود بایستادم، ابوالفضل و علامت وچتر سلطان پیش آمد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span>). امیر علامت را میفرمود تا پیشتر می بردند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">١١٣</span>). سرهنگان را خلعت دادند و علامت . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٠١</span>).<br>در جنگ و در سفر زد و سایه جدا مباد<br>از سایه ٔ علامت و از سایه ٔ همای .<br> <font color=\"Red\">فرخی .</font><br><BR><font color=\"Blue\">◄</font> صلیب مانندی که بر چوب یا آهن افقی آن از سوی پائین شالهای ترمه آویزند و از سوی زبر لاله وتندیس هائی از مرغ و جز آن نصب کنند. و در میانه زبانه ای از فلز طویل دارد و بر نوک آن فلز، پر یا گلوله ای از شیشه ٔ الوان نصب کنند، و این زبانه های فلزی که به «تیغ» مشهور است سه یا پنج باشد. و در مراسم عزاداری محرم پیشاپیش دسته ها به حرکت آرند، و حامل آن را «علامت کش » گویند.<br></font></div>'),
(185192, 'علامت کش', '<span class=\"hlight\">علامت کش .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب ) علم بردار. (آنندراج ). علمدار <span class=\"hlight\">:</span> <br>علامت کش به گوش نیزه منجوق اندرآویزد<br>برآید تیره گون ابری که بر گل زعفران بیزد.<br> <font color=\"Red\">فرخی .</font><br><BR><font color=\"Blue\">◄</font> حامل علامت . رجوع به علامت شود.<br></font></div>'),
(185193, 'علامرودشت', '<span class=\"hlight\">علامرودشت .</span> <font color=\"DarkGreen\"><b>[ ع َ م َرْوْ دَ ]</font></b> (اِخ ) ده مرکز دهستان علامرودشت بخش کنگان شهرستان بوشهر واقع در <span class=\"hlight\" dir=\"rtl\">٩٣</span> هزارگزی خاور کنگان و کنار راه عمومی اشکنان به پس رودک . دارای <span class=\"hlight\" dir=\"rtl\">٢٥</span> تن جمعیت . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(185194, 'علامرودشت', '<span class=\"hlight\">علامرودشت .</span> <font color=\"DarkGreen\"><b>[ ع َ م َرْوْ دَ ]</font></b> (اِخ ) یکی از دهستانهای نه گانه ٔ بخش کنگان شهرستان بوشهر است که حدود آن بدینقرار است : از شمال دهستان افرز و شهرستان فیروزآباد، از خاور دهستان خنج لار، از باختر دهستانهای جم و گله دار، از جنوب دهستانهای وراوی و گله دار. زمین آن جلگه و دامنه است . هوای آن گرم و مالاریایی است . آب مشروب و زراعتی آن از چاه و چشمه و قنات تأمین میشود. محصولات آن عبارتست از غلات، خرما، تنباکو و پیاز. شغل اهالی زراعت است . این ده از <span class=\"hlight\" dir=\"rtl\">١٦</span> آبادی تشکیل یافته و دارای <span class=\"hlight\" dir=\"rtl\">٢٤٠٠</span> تن جمعیت است و قراء مهم آن عبارتند از چاه عینی، کهنو، کمالی و انجیربند. راه ارتباطی آن با اطراف مالرو است . (فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(185195, 'علامرودشت', '<span class=\"hlight\">علامرودشت .</span> <font color=\"DarkGreen\"><b>[ ع َ م َرْوْ دَ ]</font></b> (اِخ ) نام رودی است به فارس . آبش شور و ناگوار است و به کار زراعت نرود. از نزدیک قریه ٔ چارطاق ناحیه ٔ ینجه ٔ احشام لارستان نشر آبی پیدا شده، کم کم زیاد گشته تا نزدیکی قصبه ٔ علامرودشت رودخانه ٔ علامرودشت شود. پس چون به قریه ٔ دادالمیزان اسیر رسد آن را رودخانه ٔ دادالمیزان گویند و در دزگاه به رودخانه ٔ دزگاه بیامیزد. (از فارسنامه ٔ ناصری گفتار دوم، رودخانه های فارس ص <span class=\"hlight\" dir=\"rtl\">٣٢٨</span>).<br></font></div>'),
(185196, 'علامه', '<span class=\"hlight\">علامه .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ]</font></b> (اِخ ) تقی الدین راصد محمد (متوفی در سال <span class=\"hlight\" dir=\"rtl\">٩٩٣</span> هَ . ق .). او راست : الطرق السنیة فی الاَّلات الروحانیة. (کشف الظنون ).<br></font></div>'),
(185197, 'علامه', '<span class=\"hlight\">علامه .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ]</font></b> (اِخ ) حسن بن یوسف . رجوع به علامه حلی شود.<br></font></div>'),
(185198, 'علامه بحرالعلوم', '<span class=\"hlight\">علامه بحرالعلوم .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ب َ رُل ْ ع ُ ]</font></b> (اِخ ) سیدمحمدمهدی طباطبائی بروجردی . رجوع به بحرالعلوم شود.<br></font></div>'),
(185199, 'علامه بهبهانی', '<span class=\"hlight\">علامه بهبهانی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ب ِ ب َ ]</font></b> (اِخ ) محمدباقربن محمداکمل . رجوع به علامه ٔ ثانی شود.<br></font></div>'),
(185200, 'علامه تفتازانی', '<span class=\"hlight\">علامه تفتازانی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ت َ ]</font></b> (اِخ ) سعدالدین مسعودبن عمر. حاشیه ای بر کشاف زمخشری نوشته است، ولی آن را تمام نکرده و فقط تا سوره ٔ فتح نگاشته است (متوفی در سال <span class=\"hlight\" dir=\"rtl\">٧٩٢</span> هَ . ق .). (کشف الظنون ). ونیز او را آثار دیگری است . رجوع به تفتازانی شود.<br></font></div>'),
(185201, 'علامه توبلی', '<span class=\"hlight\">علامه توبلی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ت َ ب َ ]</font></b> (اِخ ) سیدهاشم بن سلیمان . رجوع به علامه ٔ بحرانی شود.<br></font></div>'),
(185202, 'علامه حصیری', '<span class=\"hlight\">علامه حصیری .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ح َ ]</font></b> (اِخ ) محمودبن محمد بخاری ملقب به جمال الدین . از اکابر فقهای حنفیه که ریاست مذهبی این سلسله بدو منتهی بوده . وی تألیفات محمدبن حسن شیبانی را روایت نموده و کتاب التحریر فی شرح الجامع الکبیر از اوست . وفات او در سال <span class=\"hlight\" dir=\"rtl\">٦٣٦</span> هَ . ق . اتفاق افتاد. (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٠</span> از تذکرة النوادر).<br></font></div>'),
(185203, 'علامه حلی', '<span class=\"hlight\">علامه حلی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ح ِل ْلی ]</font></b> (اِخ ) حسن بن سدیدالدین یوسف بن زین الدین علی بن مطهر حلی، مکنی به ابومنصور و ابن مطهر، و ملقب به آیةاﷲ و جمال الدین و فاضل، و معروف به علامه و علامةالدهر. از علمای شیعه ٔ امامیه، فقیه و اصولی و محدث و رجالی و ادیب و ریاضی و حکیم و متکلم و مفسر بود. تولد او در <span class=\"hlight\" dir=\"rtl\">٢٩</span> رمضان سال <span class=\"hlight\" dir=\"rtl\">٦٤٨</span> هَ . ق . در حلّه ٔ سیفیه، از منازل بین نجف اشرف و کربلا، در طرف شرقی فرات بود.و در یازدهم یا بیست ویکم محرم سال <span class=\"hlight\" dir=\"rtl\">٧٢٦</span> وفات یافت و جنازه ٔ وی به نجف حمل و دفن گردید. وی از کودکی به زیادی هوش و فراست مشهور بود و حکمت و معقول را نزد خواجه نصیرالدین طوسی و کاتبی قزوینی و حکیم منطقی شافعی خواند. کلام و فقه و اصول و ریاضیات و ادبیات و علوم عربی و دیگر علوم متداول را نزد خال خود محقق حلی و پدر خود شیخ سدیدالدین یوسف و نزد سیداحمدبن طاوس و سیدعلی بن طاوس و ابن میثم بحرانی و پسرعم مادرش شیخ نجیب الدین یحیی و شیخ تقی الدین عبداﷲبن جعفربن علی صباغ حنفی و شیخ عزالدین فاروقی واسطی و دیگر علمای بزرگ امامیه و عامه فراگرفت . وی علاوه بر اساتید خود، از شیخ مفیدالدین بن جهم فقیه اسدی، و شیخ نجیب الدین محمدبن نمای حلی، و سیدعبدالکریم بن طاوس و علی بن عیسی اربلی روایت میکند. او در عهد اولجایتو با پسرخود فخرالمحققین به سلطانیه آمد و به اشاعه ٔ مذهب تشیع پرداخت . اما علت آمدن وی به سلطانیه چنین بود که روزی سلطان الجایتو مغولی مشهور به شاه خدابنده از روی غضب زن خود را سه طلاقه کرد و بعد پشیمان شد و تمام علمای مذاهب اربعه را جمع کرد و در حکم شرعی طلاق فتوائی موافق خود خواست، اما آنها متفقاً به وقوع سه طلاق و عدم امکان رجوع زوجیت بدون محلل حکم کردند. یکی از وزرا گفت در شهر حله عالمی است که این طلاق را باطل میداند. پس نامه ای به علامه نوشته و کسی را به احضار وی فرستاد. علمای حاضر در مجلس شاه گفتند که سزاوار نباشد برای احضار مردی رافضی خفیف العقل باطل مذهب کسی از بستگان شاه روانه شود. اما محمد خدابنده گفت تا حاضر شود و ببینم چه خواهد شد. پس شاه مجلسی از علمای اربعه تشکیل داد و علامه در موقع ورود بدان انجمن کفش ها را در بغل کرده و بعد از سلام نزد سلطان که خالی بود نشست . حاضرین ازین امر ناراحت شده به وی گفتند چرا برای سلطان سجده نکردی و ترک ادب نمودی ؟ گفت که حضرت رسول اﷲ (ص ) سلطان السلاطین بود و باز هم مردم سلامش میدادند، و در آیه ٔ شریفه هم هست «فاذا دخلتم بیوتاً فسلموا علی أنفسکم تحیة من عند اﷲ مبارکة »، و علاوه در میان ما و شما خلافی نیست در اینکه سجده مخصوص ذات اقدس الهی بوده، و بجز برای خدای تعالی سجده کردن روا نباشد. گفتند چرا نزد سلطان نشسته و حریم نگذاشتی ؟ جواب داد چون غیر از آنجا جای خالی دیگر نبود، و حدیث نبوی است که در حین ورود مجلس هر جا که خالی شد بنشین . سپس گفتند مگر نعلین چه ارزشی داشت که آن را بمجلس سلطان آوردی و این کار زشت مناسب هیچ عاقلی نمی باشد. گفت ترسیدم که حنفی مذهب کفش مرا بدزدد، چنانچه رئیس ایشان کفش حضرت رسول اﷲ (ص ) را دزدید. حنفی ها بانگ برآوردند که ابوحنیفه در زمان آن حضرت وجود نداشته و مدتها پس ازوفات آن حضرت تولد یافته . علامه گفت فراموشم شد، گویا دزد کفش آن حضرت، مالک بوده . پس مالکی مذهب ها بهمان روش جواب دادند و علامه گفت شاید دزد کفش آن حضرت احمدبن حنبل بوده . و حنبلی ها نیز بهمان طریق جواب دادند. سپس علامه رو بسلطان کرده و گفت حالا معلوم گردید که هیچ یک از رؤسای مذاهب اربعه در عهد حضرت رسالت (ص ) و در زمان اصحاب وجود نداشته و اقوال و آراء ایشان فقط رأی و نظر و اجتهاد خودشان است . اما فرقه ٔ شیعه تابع حضرت امیرالمؤمنین (ع ) میباشند که وصی و برادر آن حضرت بود. و بعد به اصل مطلب که همان قضیه ٔ طلاق زن سلطان بود پرداخت و پرسید آیا این طلاق با حضور عدلین وقوع یافته ؟ سلطان گفت در تنهائی بود. علاّمه گفت پس این طلاق باطل است و همان زن هنوز در زوجیت سلطان باقی است . و پس از آن مناظرات زیادی راجع به اموردینی بین علامه حلی و سایر علمای حاضر در مجلس درگرفت که در همه ٔ آنها علم و درایت علامه آشکار گشت و سلطان خدابنده بعد از این جریانات مذهب تشیع را قبول کرد و به اطراف بلاد فرمان داد که بنام دوازده امام خطبه خوانده و سکه زدند و اسامی مقدسه ٔ ایشان را در اطراف مساجد و مشاهد ثبت نمایند. علامه نیز کتاب الفین وکتاب منهاج الکرامة را بنام آن پادشاه نگاشت و در نزد شاه تقرب زیاد یافت و بر قاضی بیضاوی و قاضی ایجی و محمدبن محمود آملی صاحب نفایس الفنون و دیگر مقربین دربار تفوق جست، بحدی که شاه در سفر و حضر راضی بمفارقت وی نمیشد و امر کرد که برای علامه و طلابی که دردرس وی حاضر میشدند مدرسه ای سیار که دارای حجره های کرباسی بوده ترتیب دادند و همواره با اردوی شاهی نقل و در هر منزل نصب شده و مجلس تدریس منعقد میشد. در آخر بعضی از کتب علامه نیز قید شده که «از تألیف آن در شهر کرمانشاه در مدرسه ٔ سیاره فراغت یافته ». و ازبرخی تواریخ عامه نیز نقل است که از وقایع سال <span class=\"hlight\" dir=\"rtl\">٧٠٧</span> هَ . ق . اظهار و اعلان تشیع شاه خدابنده است که به اضلال ابن مطهر شعار تشیع را اعلان و انتشار داده است .<br>او را مصنفات زیادی در علوم معقول و منقول و کلام و حکمت و ریاضی و غیره است . و در مجمع البحرین از بعض از فضلا نقل شده که بخط خود علامه پانصد نسخه از مصنفاتش را دیده غیر از نسخه هائی که بخط دیگران بوده است، و خود در خطبه ٔ کتاب منتهی گوید که پیش از بیست وشش سالگی از مصنفات کلام و حکمت فراغت یافته و بتحریر فقه پرداخته است . برخی از مصنفات وی عبارتست از: <span class=\"hlight\" dir=\"rtl\">١</span>- الابحاث المفیدة فی تحصیل العقیدة. <span class=\"hlight\" dir=\"rtl\">٢</span>- ابطال الجبر. <span class=\"hlight\" dir=\"rtl\">٣</span>- اثبات الرجعة. <span class=\"hlight\" dir=\"rtl\">٤</span>- اجوبة المسائل المهنائیة الاولی، که جواب سوءالات سیدمهنابن سنان بن عبدالوهاب جعفری حسینی مدنی عبدلی است . <span class=\"hlight\" dir=\"rtl\">٥</span>- اجوبة المسائل المهنائیة، که باز هم جواب سوءالات سیدمهنای مذکور است .<span class=\"hlight\" dir=\"rtl\">٦</span>- الادعیة الفاخرة المأثورة عن العترة الطاهرة. <span class=\"hlight\" dir=\"rtl\">٧</span>-الاربعون مسألة فی اصول الدین . <span class=\"hlight\" dir=\"rtl\">٨</span>- ارشاد الاذهان الی احکام الایمان، که حاوی تمام ابواب فقه بوده و بتصریح بعضی از اجله دارای پانزده هزار مسأله است، و نسخه ٔ خطی آن در اغلب کتابخانه های عمومی و خصوصی موجود است . <span class=\"hlight\" dir=\"rtl\">٩</span>- استقصاء الاعتبار فی تحریر معانی الاخبار، که خود علامه در خلاصة الاقوال گوید که این کتاب استقصاء بی مانند بوده و در آن هر خبری را که بنظرش رسیده نقل کرده و در صحت و ضعف سند و کیفیت دلالت آنها مطالبی نگاشته است . <span class=\"hlight\" dir=\"rtl\">١٠</span>- استقصاء البحث و النظر فی مسائل القضاء و القدر، و یا استقصاء النظر فی القضاء و القدر. که آن را در جواب سؤال شاه خدابنده راجع بدلیل مختاربودن انسان و مجبور نبودن او در افعال خود، نوشته است . <span class=\"hlight\" dir=\"rtl\">١١</span>- الاسرار، در امامت . <span class=\"hlight\" dir=\"rtl\">١٢</span>- الاسرار الخفیة فی العلوم العقلیة من الحکمیة و الکلامیة و المنطقیة، که نسخه ٔ اصلی آن بخط خود علامه در خزانه ٔ غرویه موجود است و صاحب الذریعه آن را دیده است . <span class=\"hlight\" dir=\"rtl\">١٣</span>- الاشارات الی معانی الامارات، و یا الاشارات الی معنی الاشارات، که شرح اشارات و تنبیهات ابوعلی سینا است . <span class=\"hlight\" dir=\"rtl\">١٤</span>- الفین، یا کتاب الالفین الفارق بین الصدق و المین، که دارای یک مقدمه و دو مقاله و یک خاتمه است . در مقاله ٔ اول هزاردلیل به امامت حضرت علی بن ابی طالب (ع ) اقامه کرده ودر مقاله ٔ دوم نیز هزار دلیل در ابطال شبهات مخالفین نوشته است . ولی در چاپی که در ایران شده است از هزار دلیل دوم فقط بیست و چند دلیل مذکور است، و گویا بقیه کتاب دستخوش حوادث گردیده است . <span class=\"hlight\" dir=\"rtl\">١٥</span>- انوار الملکوت فی شرح الیاقوت، که شرح کتاب یاقوت نام ابواسحاق ابراهیم نوبختی از قدمای متکلمین امامیه است . <span class=\"hlight\" dir=\"rtl\">١٦</span>- ایضاح الاشتباه فی ضبط تراجم الرجال (بنقل الذریعه )، یا فی ضبط الفاظ اسامی الرجال (بنقل روضات ). <span class=\"hlight\" dir=\"rtl\">١٧</span>- ایضاح التلبیس من کلام الرئیس و بیان سهوه و الرد علیه (از الخلاصه ٔ خود علامه )، و یا کشف التلبیس و بیان سیرة الرئیس (از محمدبن خاتون )، که در رد و اعتراضات وارد بر شیخ الرئیس ابوعلی سینا است . <span class=\"hlight\" dir=\"rtl\">١٨</span>- ایضاح السبل فی شرح منتهی السؤال و الامل، در اصول فقه . و نام اصلی آن غایة الوصول الی علم الاصول است . <span class=\"hlight\" dir=\"rtl\">١٩</span>- ایضاح مخالفة السنة، در تفسیر، حاوی رد دینی مطالبی است که مخالف کتاب و سنت نبوی است . <span class=\"hlight\" dir=\"rtl\">٢٠</span>- ایضاح المعضلات من شرح الاشارات، که شرح اشارات خواجه نصیر طوسی است . <span class=\"hlight\" dir=\"rtl\">٢١</span>- ایضاح المقاصد من حکمة عین القواعد، که شرح حکمة العین کاتبی قزوینی است و در <span class=\"hlight\" dir=\"rtl\">١٣٣٧</span> هَ .ش . با مقدمه و فهارس در تهران چاپ شده است . <span class=\"hlight\" dir=\"rtl\">٢٢</span>- بسط الاشارات، و آن شرح دیگری است بر اشارات و تنبیهات ابوعلی سینا. <span class=\"hlight\" dir=\"rtl\">٢٣</span>- بسط الکافیة، که مختصر شرح الکافیة در نحو است . <span class=\"hlight\" dir=\"rtl\">٢٤</span>- تبصرة المتعلمین فی احکام الدین، که بارها در ایران چاپ شده و شروح بسیاری بر آن نوشته اند. <span class=\"hlight\" dir=\"rtl\">٢٥</span>- تحریر الاحکام الشرعیة علی مذهب الامامیة، که شامل تمام ابواب فقه است بدون استدلال . و بتصدیق بعضی از اهل فن دارای چهل هزارمسأله میباشد. <span class=\"hlight\" dir=\"rtl\">٢٦</span>- تحصیل الملخص . <span class=\"hlight\" dir=\"rtl\">٢٧</span>- التحفة، در علم هیئت . <span class=\"hlight\" dir=\"rtl\">٢٨</span>- تذکرة الفقهاء، در فقه استدلالی امامیه و مذاهب متداول عامه، و در ایران در دو جلد چاپ شده و به تذکره ٔ علامه مشهور است . <span class=\"hlight\" dir=\"rtl\">٢٩</span>- تسبیل الاذهان الی احکام الایمان، در فقه، و در یک مجلد است . <span class=\"hlight\" dir=\"rtl\">٣٠</span>- تسلیک الافهام فی معرفة الاحکام . <span class=\"hlight\" dir=\"rtl\">٣١</span>- تسلیک النفس الی حظیرة القدس، در نکات و دقایق علم کلام . <span class=\"hlight\" dir=\"rtl\">٣٢</span>- التعلیم التام فی الحکمة و الکلام . <span class=\"hlight\" dir=\"rtl\">٣٣</span>- التعلیم الثانی، که چندین مجلد بوده و ظاهراً غیر از کتاب مقاومات اوست که شامل مباحثه با تمام حکما است . <span class=\"hlight\" dir=\"rtl\">٣٤</span>- تلخیص الاحکام، که ظاهراً همان تلخیص المرام است . <span class=\"hlight\" dir=\"rtl\">٣٥</span>- تلخیص الکشاف، که تفسیر قرآن مجید بوده و ظاهراً غیر از سر وجیز و قول وجیز و نهج ایمان است که آنها نیز تفسیرهای علامه است، وشاید هم یکی از آنها باشد. <span class=\"hlight\" dir=\"rtl\">٣٦</span>- تلخیص المرام فی معرفة الاحکام و قواعد الفقه و مسائله الدقیقة علی سبیل الاختصار، که دو نسخه از آن در کتابخانه ٔ رضویه موجوداست . <span class=\"hlight\" dir=\"rtl\">٣٧</span>- التناسب بین الفرق الاشعریة و السوفسطائیة.<span class=\"hlight\" dir=\"rtl\">٣٨</span>- تنقیح الابحاث فی العلوم الثلاثة، در علوم منطق وطبیعی و الهی . <span class=\"hlight\" dir=\"rtl\">٣٩</span>- تنقیح القواعد، یا تنقیح قواعد الدین المأخوذة من آل یس . <span class=\"hlight\" dir=\"rtl\">٤٠</span>- تهذیب الاصول، که نام اصلی آن تهذیب طریق الوصول الی علم الاصول است . و گاهی آن را بتخفیف، تهذیب الوصول الی علم الاصول، و گاهی نیز تهذیب الاصول نامند. <span class=\"hlight\" dir=\"rtl\">٤١</span>- تهذیب النفس فی معرفة المذاهب الخمس . <span class=\"hlight\" dir=\"rtl\">٤٢</span>- التیسیر الوجیز فی تفسیر کتاب اﷲ العزیز، که در بعضی نسخ خلاصه ٔ علامه، بهمین نام ذکر شده و در برخی نسخ بنام السر الوجیز، و در بعضی دیگر بنام القول الوجیز ذکر شده است . <span class=\"hlight\" dir=\"rtl\">٤٣</span>- جامع الاخبار، و یا مجامع الاخبار، که ظاهراً تصحیف همان جامع الاخبار است . <span class=\"hlight\" dir=\"rtl\">٤٤</span>- الجبر و الاختیار، که ظاهراً غیر از ابطال الجبر است . <span class=\"hlight\" dir=\"rtl\">٤٥</span>- جواب السؤال عن حکمة النسخ فی الاحکام الالهیة، که در جواب سؤال شاه خدابنده است، و نام آن وجیزه است . <span class=\"hlight\" dir=\"rtl\">٤٦</span>- جوابات المسائل المهنائیة، که همان أجوبة المسائل است . <span class=\"hlight\" dir=\"rtl\">٤٧</span>- جواهر المطالب فی فضائل امیرالمؤمنین علی بن ابی طالب (ع ). <span class=\"hlight\" dir=\"rtl\">٤٨</span>- الجوهر النضید فی شرح منطق التجرید. <span class=\"hlight\" dir=\"rtl\">٤٩</span>- حاشیه ٔ تلخیص الاحکام، که خود تلخیص الاحکام و حاشیه ٔ آن در نزد صاحب معالم بوده و او در مسأله ٔ جواز طهارت با آب مضاف از آنها نقل میکند. <span class=\"hlight\" dir=\"rtl\">٥٠</span>- حل المشکلات من کتاب التلویحات، که شرح کتاب تلویحات شیخ شهاب الدین سهروردی است . <span class=\"hlight\" dir=\"rtl\">٥١</span>- خلاصة الاقوال فی علم معرفة حال الرجال، یا فی علم الرجال . <span class=\"hlight\" dir=\"rtl\">٥٢</span>- خلق الاعمال . <span class=\"hlight\" dir=\"rtl\">٥٣</span>- الدر المکنون فی علم القانون، در منطق . <span class=\"hlight\" dir=\"rtl\">٥٤</span>- الدر و المرجان فی الاحادیث الصحاح و الاحسان . <span class=\"hlight\" dir=\"rtl\">٥٥</span>- الدلائل و البرهان فی تصحیح الحضرة الغرویة. <span class=\"hlight\" dir=\"rtl\">٥٦</span>- الرسالة السعدیة. <span class=\"hlight\" dir=\"rtl\">٥٧</span>- شرح ارشاد الاذهان خود علامه . <span class=\"hlight\" dir=\"rtl\">٥٨</span>-شرح الاشارات . در مجمع البحرین از شیخ بهائی نقل شده که شرح اشارات علامه با خط خودش نزد او موجود بوده است . و شاید این کتاب همان کتاب الاشارات است که خود شرح اشارات ابوعلی سینا است . <span class=\"hlight\" dir=\"rtl\">٥٩</span>- شرح تجرید خواجه نصیر طوسی، که بنام کشف المراد است . <span class=\"hlight\" dir=\"rtl\">٦٠</span>- شرح حکمة العین که همان ایضاح المقاصد است . <span class=\"hlight\" dir=\"rtl\">٦١</span>- شرح شفای ابوعلی سینا، در دو مجلد. <span class=\"hlight\" dir=\"rtl\">٦٢</span>- شرح قواعد خود علامه . <span class=\"hlight\" dir=\"rtl\">٦٣</span>- شرح مختصر ابن حاجب . <span class=\"hlight\" dir=\"rtl\">٦٤</span>- شرح نهج البلاغه، و یا مختصر شرح نهج البلاغه، که ملخص شرح نهج البلاغه ٔ استاد خود ابن میثم بحرانی است . <span class=\"hlight\" dir=\"rtl\">٦٥</span>- غایة الاحکام فی تصحیح تلخیص المرام، که شرح او بر کتاب تلخیص المرام خود است . <span class=\"hlight\" dir=\"rtl\">٦٦</span>- غایةالوصول الی علم الاصول، که همان ایضاح السبل است . <span class=\"hlight\" dir=\"rtl\">٦٧</span>- قواعد الاحکام فی معرفة الحلال و الحرام، که به قواعد علامه معروف است و چندین مرتبه در تهران چاپ شده و محل توجه اکابر فقها بوده و شروح بسیاری بر آن نوشته شده است . <span class=\"hlight\" dir=\"rtl\">٦٨</span>- القول الوجیز فی تفسیر کتاب اﷲ العزیز، که ظاهراً همان التیسیر الوجیز است . <span class=\"hlight\" dir=\"rtl\">٦٩</span>- کاشف الاستار فی شرح کشف الاسرار. <span class=\"hlight\" dir=\"rtl\">٧٠</span>- کشف الحق و نهج الصدق، که در مناظره ٔ سید موصلی است . <span class=\"hlight\" dir=\"rtl\">٧١</span>- کشف الخفاء من کتاب الشفاء، در حکمت . <span class=\"hlight\" dir=\"rtl\">٧٢</span>- کشف الفوائد فی شرح قواعد العقائد، در کلام که شرح کتاب قواعد العقائد خواجه نصیر طوسی است و در تهران به چاپ رسیده است . <span class=\"hlight\" dir=\"rtl\">٧٣</span>- کشف المرادفی شرح تجرید الاعتقاد، در کلام که شرح تجرید خواجه نصیر طوسی است، و بارها در بمبئی و ایران چاپ شده، و بتصدیق ارباب تحقیق اگر این شرح علامه نبود، مطالب کتاب تجرید خواجه نصیر با آن همه شروح بسیاری که دارد در بوته ٔ اجمال میماند. <span class=\"hlight\" dir=\"rtl\">٧٤</span>- کشف المقال فی احوال الرجال، که کتاب رجال کبیر علامه است . و خلاصة الاقوال ملخص همین کتاب است . <span class=\"hlight\" dir=\"rtl\">٧٥</span>- کشف المکنون من کتاب القانون، در نحو، که مختصر شرح جزولیة است . <span class=\"hlight\" dir=\"rtl\">٧٦</span>- کشف الیقین فی فضائل امیرالمؤمنین (ع ). <span class=\"hlight\" dir=\"rtl\">٧٧</span>- الکشکول فی ما جری علی آل الرسول (ص ) که برخی آن را ازآن ِ سیدحیدربن علی حسینی عبیدلی میدانند. <span class=\"hlight\" dir=\"rtl\">٧٨</span>- المباحثات السنیة و المعارضات النصیریة. <span class=\"hlight\" dir=\"rtl\">٧٩</span>- مبادی ٔ الوصول الی علم الاصول . <span class=\"hlight\" dir=\"rtl\">٨٠</span>- مجامع الاخبار (از روضات )، که همان جامع الاخبار است . <span class=\"hlight\" dir=\"rtl\">٨١</span>- المحاکمات بین شراح الاشارات، در سه مجلد. <span class=\"hlight\" dir=\"rtl\">٨٢</span>- مختلف الشیعة فی احکام الشریعة، که شامل مسائل فقهیه ٔ خلافیه ٔ شیعه از اول فقه تا آخر آن با ادله ٔ هر یک ازاقوال مختلف و رد و قبول آنها است، و در تهران به چاپ رسیده است . <span class=\"hlight\" dir=\"rtl\">٨٣</span>- مدارک الاحکام، در فقه . و به نوشته ٔ روضات، فقط در طهارت است . <span class=\"hlight\" dir=\"rtl\">٨٤</span>- مراصد التوفیق و مقاصد التحقیق، در منطق و علم طبیعی و الهی . <span class=\"hlight\" dir=\"rtl\">٨٥</span>- مصابیح الانوار، در حدیث . طبق گفته ٔ خود علامه، این کتاب محتوی تمام احادیث امامیه است و هر حدیثی در باب متعلق به فن مربوط بدان حدیث ذکر شده . و هر فنی را بترتیب حضرات معصومین بچندین باب مبوب نموده است، مثلاً در باب اول هر فن، احادیث مربوط به آن فن را که از پیغمبر (ص ) رسیده نگاشته است و بهمین ترتیب تا آخر ائمه ٔ اطهار (ع ). <span class=\"hlight\" dir=\"rtl\">٨٦</span>- المطالب العلیة فی علم العربیة. <span class=\"hlight\" dir=\"rtl\">٨٧</span>- معارج الفهم فی شرح النظم . <span class=\"hlight\" dir=\"rtl\">٨٨</span>- المعتمد، در فقه . <span class=\"hlight\" dir=\"rtl\">٨٩</span>-المقاصد الوافیة بفوائد القانون و الکافیة، که حاوی مطالب کافیة و جزولیة است . <span class=\"hlight\" dir=\"rtl\">٩٠</span>- المقاومات، در حکمت، که حاوی مباحثه با حکمای سابقین است . <span class=\"hlight\" dir=\"rtl\">٩١</span>- مقصد الواصلین، در اصول دین . <span class=\"hlight\" dir=\"rtl\">٩٢</span>- مناهج الیقین فی اصول دین، که بنام منهاج الیقین نیز ذکر شد. <span class=\"hlight\" dir=\"rtl\">٩٣</span>- منتهی المطلب فی تحقیق المذهب، در فقه استدلالی، که از طهارت تا آخرباب جهاد و مقدار قلیلی از باب تجارت در دو جلد در تبریز چاپ شده است . در این کتاب آراء و مذاهب تمام مسلمین که در احکام فقهیه دارند ذکر شده، و مؤلف بعداز رد ادله ٔ مخالفین رأی و نظر خود را موافق ادله ٔشرعی ذکر میکند. <span class=\"hlight\" dir=\"rtl\">٩٤</span>- منتهی الوصول الی علمَی الکلام و الاصول . <span class=\"hlight\" dir=\"rtl\">٩٥</span>- منهاج الاستقامة، که ابن تیمیة در رد آن چند جلد کتاب نوشته است . <span class=\"hlight\" dir=\"rtl\">٩٦</span>- منهاج الصلاح فی مختصر المصباح، که مصباح شیخ طوسی را ملخص کرده و یک باب هم در اصول عقاید به ده باب آن افزوده است که بین علما و محصلین دایر و به باب حادی عشر معروف بوده و شروح بسیاری بر آن نوشته اند. <span class=\"hlight\" dir=\"rtl\">٩٧</span>- المنهاج فی مناسک الحج .<span class=\"hlight\" dir=\"rtl\">٩٨</span>- منهاج الکرامة فی الامامة، که برای شاه خدابنده تألیف کرده و در ایران چاپ شده است . <span class=\"hlight\" dir=\"rtl\">٩٩</span>- منهاج الهدایة و معراج الدرایة فی علم الکلام . <span class=\"hlight\" dir=\"rtl\">١٠٠</span>- منهاج الیقین، که همان مناهج الیقین است . <span class=\"hlight\" dir=\"rtl\">١٠١</span>- نظم البراهین فی اصول الدین . <span class=\"hlight\" dir=\"rtl\">١٠٢</span>- النکت البدیعة فی تحریر الذریعة فی اصول الدین . <span class=\"hlight\" dir=\"rtl\">١٠٣</span>- نهایة الاحکام فی معرفة الاحکام، که بقول روضات فقط درباب طهارت و صلاة است . <span class=\"hlight\" dir=\"rtl\">١٠٤</span>- نهایة المرام فی علم الکلام . <span class=\"hlight\" dir=\"rtl\">١٠٥</span>- نهایة الوصول الی علم الاصول . <span class=\"hlight\" dir=\"rtl\">١٠٦</span>- نهج الایمان فی تفسیر القرآن، که به گفته ٔ خود علامه ملخص کشاف و تبیان و غیر آنهاست . <span class=\"hlight\" dir=\"rtl\">١٠٧</span>- نهج الحق و کشف الصدق، که فضل بن روزبهان ردّی بر آن نوشته است . <span class=\"hlight\" dir=\"rtl\">١٠٨</span>- نهج العرفان فی علم المیزان . <span class=\"hlight\" dir=\"rtl\">١٠٩</span>- نهج المسترشدین فی اصول الدین، که فاضل مقداد شرحی بر آن نوشته و آن شرح را «ارشاد الطالبین الی نهج المسترشدین » نامیده، و متن و شرح هر دو در بمبئی یک جا چاپ شده است . <span class=\"hlight\" dir=\"rtl\">١١٠</span>- نهج الوصول الی علم الاصول . <span class=\"hlight\" dir=\"rtl\">١١١</span>- النهج الوضاح فی الاحادیث الصحاح . <span class=\"hlight\" dir=\"rtl\">١١٢</span>- واجب الاعتقاد. <span class=\"hlight\" dir=\"rtl\">١١٣</span>- الوجیزه فی جواب سؤال الشاه خدابنده، که در جواب السؤال ذکر شد. (از تاریخ مفصل ایران، مغول ص <span class=\"hlight\" dir=\"rtl\">٥٠٧</span>) (کشف الظنون ) (ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٦</span> از أمل الامل ) (روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">١٧١</span>) (هدیة الاحباب ص <span class=\"hlight\" dir=\"rtl\">٢٠٢</span>) (مستدرک الوسائل ص <span class=\"hlight\" dir=\"rtl\">٤٩٥</span>) (الذریعة).<br></font></div>'),
(185204, 'علامه دهلوی', '<span class=\"hlight\">علامه دهلوی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ دِ ل َ ]</font></b> (اِخ ) ابن عنایت احمدخان متخلص به «کامل ». از علمای امامیه ٔ اوایل قرن <span class=\"hlight\" dir=\"rtl\">١٣</span> هجری هندوستان که در سال <span class=\"hlight\" dir=\"rtl\">١٢٣٥</span> هَ . ق . وفات کرد. او راست : تنبیه اهل الکمال و الانصاف علی اختلال رجال اهل الخلاف، که در آن اسامی رواتی را که کذاب و جعال و ضعیف و مجهول الحال و از خوارج و مانند آنها بوده و در صحاح سته ٔ اهل سنت نیز از ایشان روایت میکنند، از کتاب تقریب ابن حجر استخراج کرده است . و نیز او راست النزهة الاثناعشریة. (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١١٤</span>. از الذریعة ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤١</span>).<br></font></div>'),
(185205, 'علامه دوانی', '<span class=\"hlight\">علامه دوانی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ دَ ]</font></b> (اِخ ) نام او بصورتهای مختلف ابن اسعد، ابن سعد، سعدالدین اسعد کازرونی دوانی صدیقی، آمده است . ولی شهرت وی همه جا به علامه دوانی است . نسب او به ابوبکر خلیفه میرسد و از احفاد محمدبن ابوبکر است . وی حکیمی بود کامل و متکلم و محقق و شاعر و منطقی که در تمام علوم متداول زمان خود خصوصاًدر عقلیات وارد و مرجع استفاده ٔ افاضل روم و خراسان و ترکستان بود. وی در عهد سلطان ابوسعید تیموری مدتی قضاوت فارس را به عهده داشت . وی در ابتدا شافعی مذهب بوده و عاقبت به شیعه گرویده است . وفات او را به اختلاف بین سالهای <span class=\"hlight\" dir=\"rtl\">٩٠٢</span> و <span class=\"hlight\" dir=\"rtl\">٩٢٨</span> هَ . ق . ذکر کرده اند که <span class=\"hlight\" dir=\"rtl\">٩٠٧</span> یا <span class=\"hlight\" dir=\"rtl\">٩٠٨</span> به یقین نزدیک تر است . تألیفات وی را از صد متجاوز دانسته اند که برخی از آنها بدینقرار است : <span class=\"hlight\" dir=\"rtl\">١</span>- اثبات الواجب الجدید. <span class=\"hlight\" dir=\"rtl\">٢</span>- اثبات الواجب القدیم، که آن را بنام سلطان محمد فاتح (متوفی در <span class=\"hlight\" dir=\"rtl\">٨٨٦</span>) تألیف کرده است . <span class=\"hlight\" dir=\"rtl\">٣</span>- اخلاق جلالی، که نام آن لوامع الاشراف فی مکارم الاخلاق است . <span class=\"hlight\" dir=\"rtl\">٤</span>- استکاکات الحروف و طبایعها و اعدادها و ما یتعلق باعداد الحروف من المسائل الموسومة «ارثماطیقی ». <span class=\"hlight\" dir=\"rtl\">٥</span>- افعال العباد، که در سال <span class=\"hlight\" dir=\"rtl\">١٣١٥</span> هَ . ق . در ضمن مجموعه ای بنام کلمات المحققین چاپ شده است . <span class=\"hlight\" dir=\"rtl\">٦</span>- افعال اﷲ تعالی . <span class=\"hlight\" dir=\"rtl\">٧</span>- انموذج العلوم، که حاوی تحقیقاتی در بعضی از مسائل حدیث و فقه و اصول و طب و تفسیر و کلام و هیئت و هندسه و منطق و ارثماطیقی و بعضی خلافیات است . <span class=\"hlight\" dir=\"rtl\">٨</span>- الانوار الشافیة. <span class=\"hlight\" dir=\"rtl\">٩</span>- تحفه ٔ روحانی، در علم حروف و خواص و اسرار آنها. <span class=\"hlight\" dir=\"rtl\">١٠</span>- التصوف و العرفان . <span class=\"hlight\" dir=\"rtl\">١١</span>- تفسیر آیه ٔ کلوا و اشربوا و لاتسرفوا، که آیه ٔ <span class=\"hlight\" dir=\"rtl\">٢٩</span> از سوره ٔ اعراف (<span class=\"hlight\" dir=\"rtl\">٧</span>) است . <span class=\"hlight\" dir=\"rtl\">١٢</span>- تفسیر سوره ٔ اخلاص .<span class=\"hlight\" dir=\"rtl\">١٣</span>- تفسیر سوره ٔ جحد (قل یا أیها الکافرون ). <span class=\"hlight\" dir=\"rtl\">١٤</span>- تنویر المطالع جدید، که حاشیه ای است بر حاشیه ٔ جدید میر صدرالدین دشتکی بر شرح مطالع قطب الدین رازی . <span class=\"hlight\" dir=\"rtl\">١٥</span>- تنویر المطالع قدیم، و آن حاشیه ای است بر حاشیه ٔ قدیم دشتکی بر شرح مطالع رازی . <span class=\"hlight\" dir=\"rtl\">١٦</span>- التوحید. <span class=\"hlight\" dir=\"rtl\">١٧</span>- الجبر و الاختیار. <span class=\"hlight\" dir=\"rtl\">١٨</span>- حاشیه ٔ تحریر القواعد المنطقیة فی شرح الشمسیة. و این کتاب تحریر، همان شرح قطب الدین رازی بر شمسیه ٔ نجم الدین کاتبی است . <span class=\"hlight\" dir=\"rtl\">١٩</span>- حاشیه ٔ أجدّ بر شرح تجرید قوشچی . <span class=\"hlight\" dir=\"rtl\">٢٠</span>- حاشیه ٔ جدید بر شرح تجرید قوشچی . <span class=\"hlight\" dir=\"rtl\">٢١</span>- حاشیه ٔ قدیم بر شرح تجرید قوشچی . در الذریعة آرد که دو شرح جدید و أجدّ در کتابخانه ٔ رضویه موجود است . و در معجم المطبوعات گوید که حاشیه ٔ شرح قوشچی در اسلامبول چاپ سنگی شده، ولی معلوم نیست که کدام یک از این سه شرح است . <span class=\"hlight\" dir=\"rtl\">٢٢</span>- زوراء، در حکمت، که در قاهره به چاپ رسیده است . <span class=\"hlight\" dir=\"rtl\">٢٣</span>- شرح تهذیب المنطق، که نام آن العجالة است و در لکنهور با چند رساله ٔ دیگر یک جا چاپ شده است . <span class=\"hlight\" dir=\"rtl\">٢٤</span>- شرح العقائد العضدیة، که در اسلامبول پترزبورغ چاپ شده است . <span class=\"hlight\" dir=\"rtl\">٢٥</span>- شرح هیاکل النور شهاب الدین یحیی سهروردی . <span class=\"hlight\" dir=\"rtl\">٢٦</span>- نور الهدایة. (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦</span> از روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">١٦٢</span> و هدیة الاحباب ص <span class=\"hlight\" dir=\"rtl\">١٣٦</span> و قاموس الاعلام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٢٤</span> و لغات تاریخیة و جغرافیةاحمد رفعت ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٨</span> و مجالس المؤمنین ص <span class=\"hlight\" dir=\"rtl\">١٦٧</span> و نور سافر ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span> و آثار عجم ص <span class=\"hlight\" dir=\"rtl\">٣٠٩</span> و الذریعة). شیخ علی دوانی قمی نیز کتابی در احوال وی تألیف و چاپ کرده است .<br></font></div>'),
(185206, 'علامه رازی', '<span class=\"hlight\">علامه رازی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ]</font></b> (اِخ ) محمدبن محمدبن ابوجعفر بویهی، مکنی به ابوجعفر و ملقب به قطب الدین وقطب المحققین . وی اهل ورامین از توابع ری بوده و نسبش به آل بویه میرسد. وی از شاگردان علامه ٔ حلی بود و قواعد علامه را با خط خود نوشته است . در طبقه ٔ فوقانی مدرسه ای که وی تحصیل میکرد شخص دیگری با لقب قطب میزیست لذا علامه رازی به قطب تحتانی و آن دیگری به قطب فوقانی شهرت داشتند. در امامی بودن وی شک و شبهه ای نیست اما در روضات الجنات سعی شده است که تسنن وی ثابت گردد. از جمله تألیفات اوست : <span class=\"hlight\" dir=\"rtl\">١</span>- بحر الاصداف، که حاشیه و شرح کشاف است . <span class=\"hlight\" dir=\"rtl\">٢</span>- تحریر القواعد المنطقیة فی شرح الشمسیة. <span class=\"hlight\" dir=\"rtl\">٣</span>- تحفة الاشراف فی شرح الکشاف، که بزرگتر از بحر الاصداف است . <span class=\"hlight\" dir=\"rtl\">٤</span>- تقسیم العلم . <span class=\"hlight\" dir=\"rtl\">٥</span>- حاشیه ٔ قطبیه، که شرح قواعد علامه حلی است . وفات او را <span class=\"hlight\" dir=\"rtl\">٧٦٦</span> هَ . ق . نقل کرده اند، اما شهید اول آن را <span class=\"hlight\" dir=\"rtl\">٧٧٦</span> گفته است .(از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٣</span> از منهج المقال و روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٥٣٠</span> و هدیةالحباب ص <span class=\"hlight\" dir=\"rtl\">٢١٧</span> و مجالس المؤمنین ص <span class=\"hlight\" dir=\"rtl\">١٦٥</span>و مستدرک الوسائل ص <span class=\"hlight\" dir=\"rtl\">٤٤٧</span> و طبقات الشافعیة ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣١</span> و قاموس الاعلام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٤١</span>). و نیز رجوع به ابوجعفر شود.<br></font></div>'),
(185207, 'علامه زبیدی', '<span class=\"hlight\">علامه زبیدی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ زُ ب َ ]</font></b> (اِخ ) احمدبن عمربن محمدبن عبدالرحمان بن قاضی یوسف، مکنی به ابوسرور و ملقب به شهاب الدین و صفی الدین . وی از بزرگان فقهای شافعی است که شیخ الاسلام زمان خویش بود. و دارای قریحه ٔ شاعری نیز بوده و گویند که روزی هشتاد بیت با رعایت تمام شرایط عروض میگفت . تولد و مسکن و مدفن او در زبیدیة از شهرهای یمن بود و مدتی نیز سمت قاضی القضاتی آن شهر را عهده دار بود. وفات وی در ربیعالثانی <span class=\"hlight\" dir=\"rtl\">٩٣٠</span> هَ . ق . اتفاق افتاد. او راست : تجرید الزوائد و تقریب الفرائد، تحفة الطلاب، العباب المحیط بمعظم نصوص الشافعی و الاصحاب، در فقه، منظومة الارشاد، که شامل پنجهزاروهشتصدوچهل بیت است . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٦</span> از النور السافر ص <span class=\"hlight\" dir=\"rtl\">١٣٧</span>).<br></font></div>'),
(185208, 'علامه زمخشری', '<span class=\"hlight\">علامه زمخشری .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ زَ م َ ش َ ]</font></b> (اِخ ) محمودبن عمربن احمد خوارزمی، مکنی به ابوالقاسم و ملقب به جاراﷲ. رجوع به زمخشری شود.<br></font></div>'),
(185209, 'علامه سکاکی', '<span class=\"hlight\">علامه سکاکی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لام َ س َک ْ کا ]</font></b> (اِخ ) محمودبن ابوبکر خوارزمی، مکنی به ابویعقوب و ملقب به سراج الدین . رجوع به ابویعقوب سکاکی، و یوسف بن ابوبکر و مآخذ ذیل شود: ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span>، هدیة الحباب ص <span class=\"hlight\" dir=\"rtl\">١٥٠</span>، روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٧٧٧</span>، معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨</span>، لغات تاریخیة و جغرافیه ٔ احمد رفعت ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٦</span>، قاموس الاعلام ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٨٦</span>، فوائد البهیة ص <span class=\"hlight\" dir=\"rtl\">٢٣١</span>.<br></font></div>'),
(185210, 'علامه شیرازی', '<span class=\"hlight\">علامه شیرازی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ]</font></b> (اِخ ) محمودبن مسعودبن مصلح فارسی شیرازی کازرونی، ملقب به قطب الدین و مکنی به ابوالثناء. رجوع به قطب الدین و ابوالثناء شود. و نیز رجوع به ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٨</span> و هدیة الاحباب ص <span class=\"hlight\" dir=\"rtl\">٢١٩</span> و طبقات الشافعیه ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٨</span> و روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٥٣٢</span> و قاموس الاعلام ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٩٦</span> و ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦٧٣</span> شود.<br></font></div>'),
(185211, 'علامه قیسی', '<span class=\"hlight\">علامه قیسی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َق َ ]</font></b> (اِخ ) ابراهیم بن محمدبن ابراهیم قیسی مالکی سفاقسی، مکنی به ابواسحاق و ملقب به برهان الدین و موصوف به علامه . از اکابر نحویین و از تلامذه ٔ زینب بنت الکمال . او راست : اعراب القرآن یا ترکیب القرآن المجید فی اعراب القرآن المجید. او در سال <span class=\"hlight\" dir=\"rtl\">٧٤٢</span> هَ . ق . در حدود <span class=\"hlight\" dir=\"rtl\">٤٤</span>سالگی درگذشت . (ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٨</span> از کشف الظنون و الدرر الکامنة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٥</span> و روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٨</span>).<br></font></div>'),
(185212, 'علامه لیثی', '<span class=\"hlight\">علامه لیثی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ل َ ]</font></b> (اِخ ) ابوالقاسم . وی حاشیه ای بر«شرح طوالع الانوار» شمس الدین محمود اصفهانی نگاشته است . (کشف الظنون ). و رجوع به ابوالقاسم لیثی شود.<br></font></div>'),
(185213, 'علامه مجلسی', '<span class=\"hlight\">علامه مجلسی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ م َ ل ِ ]</font></b> (اِخ ) محمدباقربن محمدتقی . رجوع به مجلسی شود.<br></font></div>'),
(185214, 'علامه مقدسی', '<span class=\"hlight\">علامه مقدسی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ م َ دِ ]</font></b> (اِخ ) عبداﷲبن ابی الوحش برّی بن عبدالجباربن برّی مصری، مکنی به ابومحمد و مشهور به ابن برّی . از مشاهیر ادبای قرن ششم هجری، و بخصوص در علم لغت بسیار توانا بود. وی در شب شنبه <span class=\"hlight\" dir=\"rtl\">٢٧</span>شوال <span class=\"hlight\" dir=\"rtl\">٥٨٢</span> یا <span class=\"hlight\" dir=\"rtl\">٥٨٦</span> هَ . ق . در سن هشتادسالگی درگذشت . از جمله تألیفات اوست : <span class=\"hlight\" dir=\"rtl\">١</span>- التنبیه و الایضاح عما وقعمن الوهم فی کتاب الصحاح، که شامل تصحیحات صحاح جوهری بود و اضافاتی بر آن افزود. <span class=\"hlight\" dir=\"rtl\">٢</span>- حاشیه ٔ درّة الغواص حریری . <span class=\"hlight\" dir=\"rtl\">٣</span>- غلط الضعفاء من الفقهاء، که حاوی اغلاطی است که از فقها در استعمال الفاظ صادر گردیده است . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦</span> از روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٥٢</span> و تاریخ ابن خلکان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩١</span> و معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٦</span> و قاموس الاعلام ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣٦٢</span>). و رجوع به ابن بری و ابومحمد شود.<br></font></div>'),
(185215, 'علامه همدانی', '<span class=\"hlight\">علامه همدانی .</span> <font color=\"DarkGreen\"><b>[ع َل ْ لا م َ هََ م َ ]</font></b> (اِخ ) احمدبن حسین، مشهور به بدیعالزمان همدانی . رجوع به احمدبن حسین بن بحیی شود.<br></font></div>'),
(185216, 'علامه چلبی بیگ', '<span class=\"hlight\">علامه چلبی بیگ .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ چ َ ل َ بی ب َ ]</font></b> (اِخ ) پسر میرزاعلی بیگ و از اهالی تبریز بوده که در ایام جوانی برای تحصیل به شیراز رفت و مدتی در حوزه ٔ درس ملا میرزاجان (متوفی در سال <span class=\"hlight\" dir=\"rtl\">٩٩٤</span> یا <span class=\"hlight\" dir=\"rtl\">٩٩٨</span> هَ . ق .) حاضر شد. عاقبت بجهت تهمت شرب خمر به قزوین رفته و بواسطه ٔ شهرت و صیت کمالاتی که داشته بهندوستان رفته و در دربار ملوک وقت هند تقرب یافته، و براثر سوء سریره کتابی در رد انبیا نوشت و درنتیجه ٔ این کردار ناشایست خود بمرض آکله مبتلی و بدنش سوراخ سوراخ شده و عازم مقر خود گردید. او به شعر گفتن نیز رغبت داشت و در اوایل به «شیدا» و در اواخر به «فارغ » تخلص میکرد. پدرش میرزا علی بیک در زمان شاه طهماسب صفوی کلانتر تبریز بود. (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٥</span> از تذکره ٔ نصرآبادی ). و نیز رجوع به فارغ تبریزی شود.<br></font></div>'),
(185217, 'علامه کتکانی', '<span class=\"hlight\">علامه کتکانی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َ ک َ ]</font></b> (اِخ ) سیدهاشم بن سلیمان . رجوع به علامه بحرانی شود.<br></font></div>'),
(185218, 'علامه کرمانی', '<span class=\"hlight\">علامه کرمانی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا م َک ِ ]</font></b> (اِخ ) از فضلای زمان سلطان محمد خوارزمشاه است که در نظم شعر ماهر بود. وی موقعی که از جانب خوارزمشاه به رسم رسالت بنزد سلطان محمود غوری رفت، قصیده ای در مدح سلطان غوری سرود که دو بیت آن نقل میشود:<br>شاهی که هست بر همه شاهان شرق زین <br>کشورگشای گیتی و دستور عالمین <br>سلطان مشرقین و شهنشاه مغربین <br>محمودبن محمدبن سام بن حسین .<br><font color=\"Red\">(از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥٣</span>).</font><br></font></div>'),
(185219, 'علاموت', '<span class=\"hlight\">علاموت .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِ) دوشیزگان لفظی موسیقی، و محتمل است که بمناسبت معنایش قصد ازین باشد که با صدای دوشیزگان خوانده شود. رجوع شود به الاموت . (از قاموس کتاب مقدس ).<br></font></div>'),
(185220, 'علامی', '<span class=\"hlight\">علامی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا ]</font></b> (اِخ ) ابوالفضل بن شیخ مبارک بن شیخ خضر. رجوع به ابوالفضل ناگری شود. و نیز رجوع به ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٨</span> و اعیان الشیعه ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">٩٩</span> و ریاض العارفین ص <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> و تذکره ٔ علمای هند ص <span class=\"hlight\" dir=\"rtl\">٤</span> و <span class=\"hlight\" dir=\"rtl\">٧٤</span>و نامه ٔ دانشوران ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٣٩</span> و مرآت الخیال ص <span class=\"hlight\" dir=\"rtl\">٧٩</span> شود.<br></font></div>'),
(185221, 'علامی', '<span class=\"hlight\">علامی .</span> <font color=\"DarkGreen\"><b>[ ع ُ می ی ]</font></b> (ع ص ) سبک روح تیزفهم . (اقرب الموارد) (ناظم الاطباء). تیزفهم . (از منتهی الارب ).<br></font></div>'),
(185222, 'علامی', '<span class=\"hlight\">علامی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا ]</font></b> (از ع، ص ) مرد دانا و بسیار باهوش . (ناظم الاطباء) (غیاث اللغات ).<br></font></div>'),
(185223, 'علامید', '<span class=\"hlight\">علامید.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ علماد و علمادة. (اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(185224, 'علان', '<span class=\"hlight\">علان .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ لا ]</font></b> (اِخ ) نام مردی درستکار و صناع . (غیاث اللغات ). رجوع به ماده ٔ قبل شود.<br></font></div>'),
(185225, 'علان', '<span class=\"hlight\">علان .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا]</font></b> (اِ) نخل بندی که از موم نخلها سازد. (حاشیه ٔ دیوان خاقانی چ عبدالرسولی، از شرح خاقانی ) <span class=\"hlight\">:</span> <br>بلی نخل خرمای مریم بخندد<br>بر آن نخل مومین که علان نماید.<br><font color=\"Red\">خاقانی .</font><br></font></div>'),
(185226, 'علان', '<span class=\"hlight\">علان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) با هم آشکاراو هویدا نمودن . (منتهی الارب ) (اقرب الموارد). معالنة. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> اظهار ساختن . (منتهی الارب ) (از اقرب الموارد). اظهار کردن . (ناظم الاطباء).<br></font></div>'),
(185227, 'علان', '<span class=\"hlight\">علان .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا ]</font></b> (ع ص ) مرد نادان . (ناظم الاطباء) (ذیل اقرب الموارد).<br></font></div>'),
(185228, 'علان', '<span class=\"hlight\">علان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) قلعه ای است نزدیک صنعاء یمن . (از معجم البلدان ) (منتهی الارب ).<br></font></div>'),
(185229, 'علان شعوبی', '<span class=\"hlight\">علان شعوبی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا ن ِ ش ُ ]</font></b> (اِخ ) علان ورّاق . وی اصلاً ایرانی است . راویه و عارف به انساب و مثالب و منافرات بود. وی از خواص برامکه بوده و ناسخ بیت الحکمة برای رشید و مأمون و برامکه است . او راست : کتاب المیدان، در مثالب عرب و هتک و تفضیح آنان . وی در این کتاب، مثالب قبایل عرب را جمع کرده و جداجدا درباره ٔ آن بحث کرده است . و نیز او راست کتاب الحلیة، که آن را تمام نکرد، و کتاب فضائل کنانة، و کتاب نمربن قاسط وکتاب نسب تغلب بن وائل، و کتاب فضائل ربیعة، و کتاب منافرة. (از معجم الادباء چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦</span>). ابن الندیم نیز در الفهرست چند کتاب از او نام برده است .<br></font></div>'),
(185230, 'علان وراق', '<span class=\"hlight\">علان وراق .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا ن ِ وَرْ را ]</font></b> (اِخ ) رجوع به علان شعوبی شود.<br></font></div>'),
(185231, 'علان کلینی', '<span class=\"hlight\">علان کلینی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا ن ِ ک ُ ل َ ]</font></b> (ا خ ) علی بن محمدبن ابراهیم بن علان، مکنی به ابوالحسن . از محدثین امامیه ٔ زمان غیبت صغری . وی دائی محمدبن یعقوب کلینی است . او راست : اخبار القائم (ع ). (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١١٥</span>).<br></font></div>'),
(185232, 'علانة', '<span class=\"hlight\">علانة.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا ن َ ]</font></b> (اِخ ) شهر یا قلعه ای است در نواحی ذمار در یمن . (معجم البلدان ).<br></font></div>'),
(185233, 'علاند', '<span class=\"hlight\">علاند.</span> <font color=\"DarkGreen\"><b>[ ع َ ن ِ ]</font></b> (ع اِ) ج ِ عَلَندی ̍. (ناظم الاطباء).<br></font></div>'),
(185234, 'علانشیه', '<span class=\"hlight\">علانشیه .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام فرقه ای از فِرَق میان عیسی و محمد علیهماالسلام . (الفهرست ابن الندیم ).<br></font></div>'),
(185235, 'علانون', '<span class=\"hlight\">علانون .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) ج ِ علانیه . (اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185236, 'علانی', '<span class=\"hlight\">علانی .</span> <font color=\"DarkGreen\"><b>[ ع َ نی ی ]</font></b> (ع ص ) مرد مشهور کار. (آنندراج ): رجل علانی ؛ أی ظاهر أمره . ج، علانیون . (اقرب الموارد). رجل علانیة. (منتهی الارب ).<br></font></div>'),
(185237, 'علانی', '<span class=\"hlight\">علانی .</span> <font color=\"DarkGreen\"><b>[ ع ِ نی ی ]</font></b> (ع ص نسبی ) منسوب به علان . (اقرب الموارد).<br></font></div>'),
(185238, 'علانیة', '<span class=\"hlight\">علانیة.</span> <font color=\"DarkGreen\"><b>[ ع َ ی َ ]</font></b> (ع مص، اِمص ) ظاهر و هویدا شدن و انتشار یافتن . (از اقرب الموارد). آشکارگی . خلاف سرّ. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> آشکارا و هویدا. (ناظم الاطباء) <span class=\"hlight\">:</span> <br>در سر و در علانیه کردم گناه و داشت <br>از سرّ و از علانیه ٔ من خبر خبیر.<br> <font color=\"Red\">سوزنی .</font><br><BR><font color=\"Blue\">◄</font> (ص ) رجل علانیة؛ مرد معروف و مشهور کار. ج، علانین . (منتهی الارب ). ج، علانون . (ناظم الاطباء). رجل علانی . (اقرب الموارد).<br></font></div>'),
(185239, 'علانیه کردن', '<span class=\"hlight\">علانیه کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ک َ دَ ]</font></b> (مص مرکب ) ظاهرو آشکار کردن . کاری را برملا کردن . (ناظم الاطباء).<br></font></div>'),
(185240, 'علاه', '<span class=\"hlight\">علاه .</span> <font color=\"DarkGreen\"><b>[ ع ِ]</font></b> (ع ص، اِ) ج ِ عَلهی ̍. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ج ِ عَلهان . (آنندراج ) (منتهی الارب ).<br></font></div>'),
(185241, 'علاهم', '<span class=\"hlight\">علاهم .</span> <font color=\"DarkGreen\"><b>[ ع ُ هَِ ]</font></b> (ع ص ) شتر درشت بزرگ جثه . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185242, 'علاهی', '<span class=\"hlight\">علاهی .</span> <font color=\"DarkGreen\"><b>[ ع َ ها ]</font></b> (ع اِ) ج ِ عَلهی ̍. (اقرب الموارد) (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ج ِ عَلهان . (آنندراج ) (ناظم الاطباء).<br></font></div>'),
(185243, 'علاوه کردن', '<span class=\"hlight\">علاوه کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ک َ دَ ]</font></b> (مص مرکب ) افزودن . جمع کردن .<br></font></div>'),
(185244, 'علاوی', '<span class=\"hlight\">علاوی .</span> <font color=\"DarkGreen\"><b>[ ع َ وا <span class=\"hlight\" dir=\"rtl\">/</span> ع َ ]</font></b> (ع اِ) ج ِ عِلاوه . (اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185245, 'علاک', '<span class=\"hlight\">علاک .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لا ]</font></b> (ع ص ) صمغفروش . (اقرب الموارد) (آنندراج ).<br></font></div>'),
(185246, 'علاک', '<span class=\"hlight\">علاک .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) چیزی که اندک خاییده شود. (ذیل اقرب الموارد) (آنندراج ).<br></font></div>'),
(185247, 'علاک', '<span class=\"hlight\">علاک .</span> <font color=\"DarkGreen\"><b>[ ع َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ]</font></b> (ع اِ) درختی است حجازی . (اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185248, 'علاک', '<span class=\"hlight\">علاک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) آنچه خاییده شود. (اقرب الموارد) (ناظم الاطباء): ماذاق علاکاً؛ نچشیده است چیزی . (ناظم الاطباء) (آنندراج ).<br></font></div>'),
(185249, 'علاکد', '<span class=\"hlight\">علاکد.</span> <font color=\"DarkGreen\"><b>[ ع ُک ِ ]</font></b> (ع ص ) ستبر. (اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> شیر دفزک شده . (ناظم الاطباء) (آنندراج ).<br></font></div>'),
(185250, 'علاکد', '<span class=\"hlight\">علاکد.</span> <font color=\"DarkGreen\"><b>[ ع َ ک ِ ]</font></b> (ع ص، اِ) ج ِ عَلکد. شتران قوی . (ذیل اقرب الموارد).<br></font></div>'),
(185251, 'علاکم', '<span class=\"hlight\">علاکم .</span> <font color=\"DarkGreen\"><b>[ ع َ ک ِ ]</font></b> (ع اِ) ج ِ عُلاکم . (اقرب الموارد) (منتهی الارب ).<br></font></div>'),
(185252, 'علاکم', '<span class=\"hlight\">علاکم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ک ِ ]</font></b> (ع ص ) عُلکوم . (منتهی الارب ). استواراندام و قوی از شتر و جز آن . مذکر و مؤنث در آن یکسان است . (منتهی الارب ) (اقرب الموارد). ج، عَلاکم .<br></font></div>'),
(185253, 'علایة', '<span class=\"hlight\">علایة.</span> <font color=\"DarkGreen\"><b>[ ع َ ی َ ]</font></b> (ع اِ) هر جای بلند. (منتهی الارب ) (از اقرب الموارد).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(185254, 'علایق', '<span class=\"hlight\">علایق .</span> <font color=\"DarkGreen\"><b>[ ع َ ی ِ ]</font></b> (ع اِ) رجوع به علائق شود.<br>- <span class=\"hlight\">علایق ِ روزگار</span> ؛ گرفتاری و بستگی به امور معیشت . (ناظم الاطباء) <span class=\"hlight\">:</span> بسبب نوازل محن و عوارض فتن و عوایق ایام و علایق روزگار تیر تمنی ایشان بهدف مراد نمیرسید. (ترجمه ٔ تاریخ یمینی ).<br></font></div>'),
(185255, 'علایم', '<span class=\"hlight\">علایم .</span> <font color=\"DarkGreen\"><b>[ ع َ ی ِ ]</font></b> (از ع، اِ) ج ِ علامت . این لفظ در عربی استعمال نشده بلکه در فارسی به قانون عربی ساخته شده است . (فرهنگ نظام ).<br></font></div>'),
(185256, 'علب', '<span class=\"hlight\">علب .</span> <font color=\"DarkGreen\"><b>[ع َ ل ِ ]</font></b> (ع ص ) هر چیز سخت و رست . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> جای سخت که در آن چیزی نروید. (از ذیل اقرب الموارد). <BR><font color=\"Blue\">◄</font> بز کوهی درشت و بزرگ . (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بز کوهی کلانسال . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> سوسمار سالخورده . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185257, 'علب', '<span class=\"hlight\">علب .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع مص ) سخت و رست شدن . (منتهی الارب ) (از اقرب الموارد). عَلْب . <BR><font color=\"Blue\">◄</font> خشک شدن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> تغییر کردن بوی گوشت پس از سختی . <BR><font color=\"Blue\">◄</font> پریدن و شکستن و رخنه دار شدن لبه ٔ شمشیر و از قبیل آن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مبتلی شدن به بیماری عَلَب . (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِمص ) سختی . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> درشتی . <BR><font color=\"Blue\">◄</font> گرفتگی . <BR><font color=\"Blue\">◄</font> بیماریی است که در پی گردن شتر عارض میشود. (منتهی الارب ) (ناظم الاطباء).<br></font></div>'),
(185258, 'علب', '<span class=\"hlight\">علب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) جای درشت وسخت که هرچه باران بر آن ببارد باز هم هیچ نرویاند.(منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد خشک و خشن . (از ذیل اقرب الموارد). <BR><font color=\"Blue\">◄</font> مردی که هرچه دارد کسی نمیتواند در آن طمع کند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سوسمار سالخورده . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ) روییدنگاه درخت کُنار. (منتهی الارب ) (از اقرب الموارد). ج، عُلوب .<br></font></div>'),
(185259, 'علب', '<span class=\"hlight\">علب .</span> <font color=\"DarkGreen\"><b>[ ع ِ ل َ ]</font></b> (ع اِ) ج ِ عِلبة. (اقرب الموارد).<br></font></div>'),
(185260, 'علب', '<span class=\"hlight\">علب .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) نشان کردن . <BR><font color=\"Blue\">◄</font> خراشیدن . <BR><font color=\"Blue\">◄</font> اثر گذاشتن . <BR><font color=\"Blue\">◄</font> بریدن . <BR><font color=\"Blue\">◄</font> استوار بستن قبضه ٔ شمشیر و از قبیل آن، بر گردن شتر. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سخت و رست شدن . (اقرب الموارد). عَلَب . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خشک شدن . <BR><font color=\"Blue\">◄</font> بوی گوشت و از قبیل آن پس از اشتداد، تغییر کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) نشان و اثر. <BR><font color=\"Blue\">◄</font> جای درشت . <BR><font color=\"Blue\">◄</font> هر چیز سخت و رست . <BR><font color=\"Blue\">◄</font> زمینی که اگر مدتها بر آن باران بارد باز هم هیچ نرویاند. (منتهی الارب ) (از اقرب الموارد). ج، عُلوب .<br></font></div>'),
(185261, 'علب', '<span class=\"hlight\">علب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) سوسمار. (از اقرب الموارد). سوسمار سالخورده . (ناظم الاطباء).<br></font></div>'),
(185262, 'علب', '<span class=\"hlight\">علب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ]</font></b> (ع اِ) ج ِ عُلبة. (از اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185263, 'علباوان', '<span class=\"hlight\">علباوان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) علبأان . تثنیه ٔ علباء. دو پی گردن . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185264, 'علبة', '<span class=\"hlight\">علبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (اِخ ) ابن زیدبن عمروبن زیدبن جشم بن حارثةبن حرث بن خزرج بن عمروبن مالک بن أوس انصاری أوسی . از جمله ٔ بکائین در غزوه ٔ تبوک است . (از الاصابة ج <span class=\"hlight\" dir=\"rtl\">٤</span> قسم اول ص <span class=\"hlight\" dir=\"rtl\">٢٦١</span>).<br></font></div>'),
(185265, 'علبة', '<span class=\"hlight\">علبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع اِ) نخل دراز. <BR><font color=\"Blue\">◄</font> شیردوشه ٔ چرمین یا چوبین . (منتهی الارب ) (از اقرب الموارد). عِلبة. ج، عُلب، عِلاب .<br></font></div>'),
(185266, 'علبة', '<span class=\"hlight\">علبة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ب َ ]</font></b> (ع اِ) گره درشت از درخت که از آن کنده ٔ پای مجرمان و زندانیان و بندیان سازند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شیردوشه ٔ چرمین . (منتهی الارب ). عُلبة. ج، عِلب .<br></font></div>'),
(185267, 'علبط', '<span class=\"hlight\">علبط.</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ب ِ ]</font></b> (ع ص ) هر چیز درشت و ستبر. <BR><font color=\"Blue\">◄</font> شیر خفته ٔ دفزک شده . <BR><font color=\"Blue\">◄</font> (اِ) سنگینی و ثقل تن . <BR><font color=\"Blue\">◄</font> گله ٔ گوسفند از پنجاه تا هر قدر که باشد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185268, 'علبط', '<span class=\"hlight\">علبط.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب ِ ]</font></b> (ع ص ) عریض و پهن . (از اقرب الموارد).<br></font></div>'),
(185269, 'علبوبة', '<span class=\"hlight\">علبوبة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ب َ ]</font></b> (ع اِ) برگزیده و مهتر قوم . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185270, 'علبیة', '<span class=\"hlight\">علبیة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ی َ ]</font></b> (اِخ ) آبکی است در داث . (از معجم البلدان ) (از اقرب الموارد).<br></font></div>'),
(185271, 'علبیة', '<span class=\"hlight\">علبیة.</span> <font color=\"DarkGreen\"><b>[ ع ِ ی َ ]</font></b>(ع ص ) ماده شتر چرکین . (منتهی الارب ) (ناظم الاطباء).<br></font></div>'),
(185272, 'علة', '<span class=\"hlight\">علة.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ل َ ]</font></b> (ع اِ) رجوع به عَلّت شود.<br></font></div>'),
(185273, 'علة', '<span class=\"hlight\">علة.</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ]</font></b> (ع اِ) رجوع به عِلّت شود.<br>- <span class=\"hlight\">حروف عله </span> ؛ در عربی، الف و واو و یاء است . (از اقرب الموارد). رجوع به «حرف عله » شود.<br></font></div>'),
(185274, 'علت', '<span class=\"hlight\">علت .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ل َ ]</font></b> (ع اِ) هوو. ضرّة. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه بدان بهانه کنند. (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> نیاز و حاجت . <BR><font color=\"Blue\">◄</font> سختی حال . (منتهی الارب ) (ناظم الاطباء). ج، عَلات .<br></font></div>'),
(185275, 'علت', '<span class=\"hlight\">علت .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ]</font></b>(ع اِ) بیماری . (منتهی الارب ) (از اقرب الموارد) <span class=\"hlight\">:</span> بسیار طبیبانند که میگویند فلان چیز نباید خوردن، که از وی چنین علّت به حاصل آید. و آنگاه خود ازآن بسیار بخورند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٩٣</span>). دو سه علت متضاد دشوار است علاج آن . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٧٠</span>).<br>علت پوشیده مدار از طبیب <br>بر در او خواهش و زنهار کن .<br> <font color=\"Red\">ناصرخسرو.</font><br>بیماری که اشارت طبیب را سبک دارد... هر لحظه ناتوانی بر وی مستولی گردد و علت مزمن تر شود. (کلیله ص <span class=\"hlight\" dir=\"rtl\">١٩٢</span>). به علتهای مزمن و دردهای مهلک گرفتار گشته . (کلیله ص <span class=\"hlight\" dir=\"rtl\">٢٤</span>). بر عقب آن تاش به علتی صعب مبتلی گشت و عمر او در آن غربت به آخر رسید. (ترجمه ٔ تاریخ یمینی ). هیچ علت نیست که نه آن را داروییست، مگر مرگ را. (کیمیای سعادت ). حکیمان گفته اند اگر آب حیات فروشند فی المثل به آبروی، دانا نخرد که مردن به علت به که زندگانی به مذلت . (گلستان سعدی ).<br>چو حلوا خام باشد علت آرد.<br> <font color=\"Red\">جامی .</font><br>- <span class=\"hlight\">بی علت </span> ؛ بی مرض . (ناظم الاطباء).<br> <BR><font color=\"Blue\">◄</font> سستی و ناتوانی . <BR><font color=\"Blue\">◄</font> آفت و آسیب . <BR><font color=\"Blue\">◄</font> عیب . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> کار نو که شخص را از اراده ای که داشت بازدارد. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> اتفاق . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آنچه بدان بهانه کنند. (منتهی الارب ) (آنندراج ). عذر و بهانه . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> سبب و جهت . (منتهی الارب ) (از اقرب الموارد) <span class=\"hlight\">:</span> اهل تمییز از لحوم و شحوم بازار تنفر و تحرز نمودند، چه بیشتر با اجزاء و اعضاء بشر بر هم میگداختند و در بازارها میفروختند. و جمعی را بدین علت بگرفتندو در خانه های ایشان استخوانهای آدمی یافتند و همه را به هلاک آوردند. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٩٧</span>). یکی رازنی صاحب جمال جوان درگذشت و مادرزن فرتوت به علت کابین در خانه متمکن بماند. (گلستان سعدی ).<br>- <span class=\"hlight\">بی علت </span> ؛ بی جهت . بی سبب . (ناظم الاطباء) <span class=\"hlight\">:</span> <br>بی زلت و بی گناه محبوسم <br>بی علت و بی سبب گرفتارم .<br> <font color=\"Red\">مسعودسعد.</font><br> <BR><font color=\"Blue\">◄</font> مکر و حیله . <BR><font color=\"Blue\">◄</font> سرگذشت . (ناظم الاطباء).<br>- <span class=\"hlight\">امثال </span> :<br><span class=\"hlight\">علت برود و عادت نرود</span> .<br> <span class=\"hlight\">علت برود ولیک عادت نرود</span> ؛ العادة طبیعة. (امثال و حکم دهخدا).<br> <span class=\"hlight\">علت پوشیده مدار از طبیب </span> .<br> <font color=\"Red\">ناصرخسرو.</font><br> <span class=\"hlight\">علت عاشق ز علتها جداست </span> .<br> <font color=\"Red\">مولوی .</font><br> <BR><font color=\"Blue\">◄</font> (اصطلاح عروض ) تغییراتی است که در عروض ها (یعنی جزء آخر ازمصراع اول ) و ضرب ها به سبب ها و وتدها ملحق میشود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اصطلاح فلسفه ) چیزی است که چیز دیگری بر آن متوقف باشد، و از وجود آن وجود امری دیگر لازم آید، و از عدم آن عدم امری دیگر لازم شود. یعنی هرگاه میان دو امری بستگیی وجود داشته باشد آن را که محتاج الیه است علت نامند و دیگری را که محتاج است معلول گویند. و بر اثر عدم علت، معلول ممتنع میشود. ولی بر اثر وجود علت، وجود معلول واجب نمیشود. و از رفع علت و عدم آن، عدم معلول لازم میشود واز رفع معلول و عدم آن، عدم علت کشف میگردد. (از فرهنگ اصطلاحات فلسفی ).<br>علت بر چهار قسم است : «مامنه » یا فاعلی، «ماله » یا غائی، «مافیه » یا مادی، «مابه » یا صوری . از این علل چهارگانه دو علت فاعلی و غائی، علل وجودند، و دو علت مادی و صوری، علل ماهیت اند. و کلیه ٔ این علتها گاه صناعی هستند مانند علل تخت از نجار و چوب و صورت تختی و جلوس بر وی . و گاه طبیعی اند مانند طبیعت، که علت فاعلی حرکت و سکون در اجسام طبیعی است . و گاه نفسانی اند مانند نفوس و اجرام نباتی و حیوانی و فلکی، و صورو غایات افعال اینها. و این علل چهارگانه را، بحسب قرب و بعد از معلول، و بالذات یا بالعرض بودن، و بالفعل یا بالقوه بودن، و اینکه خاص یا عام یا مساوی باشد، و جزوی یا کلی بودن، و بسیط یا مرکب بودن، احوال و اقسام مختلفی است که در جدول صفحه ٔ مقابل ملاحظه میگردد. (از اساس الاقتباس ص <span class=\"hlight\" dir=\"rtl\">٣٥٤</span>).<br></font></div>'),
(185276, 'علت آفتاب', '<span class=\"hlight\">علت آفتاب .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) یرقان . (غیاث اللغات ) (آنندراج ).<br></font></div>'),
(185277, 'علت اصل', '<span class=\"hlight\">علت اصل .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِ اَ ]</font></b> (ترکیب اضافی، اِ مرکب ) عقل اول . (غیاث اللغات ) (آنندراج ).<br></font></div>'),
(185278, 'علت اولی', '<span class=\"hlight\">علت اولی .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِ لا ]</font></b> (ترکیب وصفی، اِ مرکب ) عقل اول و ذات خدای تعالی . (فرهنگ اصطلاحات فلسفی ) (غیاث اللغات ) (آنندراج ) (ناظم الاطباء) <span class=\"hlight\">:</span> <br>بسان علت اولی سخن ران ای سنائی زآن <br>که تا چون زاده ٔ ثانی بقای جاودان بینی .<br><font color=\"Red\">سنائی .</font><br></font></div>'),
(185279, 'علت بالذات', '<span class=\"hlight\">علت بالذات .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِ بِذْ ذا ]</font></b> (ترکیب وصفی، اِ مرکب ) امری است که مستقیماً و بلاواسطه علت چیزی باشد. (از فرهنگ اصطلاحات فلسفی ). و رجوع به علت شود.<br></font></div>'),
(185280, 'علت تامه', '<span class=\"hlight\">علت تامه .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِ تام ْ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) سبب کامل . امری که خود مستقلاً وجود چیزی را ایجاب کند. (از فرهنگ اصطلاحات فلسفی ) (غیاث اللغات ) (آنندراج ) (ناظم الاطباء).<br></font></div>'),
(185281, 'علت دانه', '<span class=\"hlight\">علت دانه .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) آبله ٔ خرد. (ناظم الاطباء).<br></font></div>'),
(185282, 'علت سرخ', '<span class=\"hlight\">علت سرخ .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِ س ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) آفتی که در کشت گندم افتد و برگها را سرخ گرداند و از آن هیچ حاصل به دست نیاید. (آنندراج ). <BR><font color=\"Blue\">◄</font> سرخ باده . بیماریی که در آن خون و صفرا بهم میرسد. (از آنندراج ).<br></font></div>'),
(185283, 'علت صوری', '<span class=\"hlight\">علت صوری .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) شکل و صورتی که صانع، چیزی را بدان ترکیب میسازد. (ناظم الاطباء). و رجوع به علت شود.<br></font></div>'),
(185284, 'علت عادی', '<span class=\"hlight\">علت عادی .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) امری که برحسب عادت، مؤثر در چیزی باشد، هرچند که از لحاظ حکم عقلی نتوان رابطه ٔ علیّت میان آن دو برقرار کرد. (از فرهنگ اصطلاحات فلسفی ).<br></font></div>'),
(185285, 'علت عالم', '<span class=\"hlight\">علت عالم .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِ ل َ ]</font></b> (ترکیب اضافی، اِ مرکب ) عقل اول . (غیاث اللغات ) (آنندراج ).<br></font></div>'),
(185286, 'علت فاعلی', '<span class=\"hlight\">علت فاعلی .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِ ع ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) صانع و سازنده ٔ هر چیز. (از ناظم الاطباء). امری که مفید وجود شی ٔ باشد و خارج از ذات معلول است . (از فرهنگ اصطلاحات فلسفی ). و رجوع به علت شود.<br></font></div>'),
(185287, 'علت قابلی', '<span class=\"hlight\">علت قابلی .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِ ب ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به علت مادی شود. (فرهنگ اصطلاحات فلسفی ).<br></font></div>'),
(185288, 'علت قریب', '<span class=\"hlight\">علت قریب .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِ ق َ ]</font></b> (ترکیب وصفی، اِ مرکب ) امری که خود بلاواسطه و بدون فاصله در وجود معلول مؤثر باشد. (از فرهنگ اصطلاحات فلسفی ). و رجوع به علت شود.<br></font></div>'),
(185289, 'علت قمی', '<span class=\"hlight\">علت قمی .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِق ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) وبا و طاعون، که اکثر اوقات در قم واقع میشود. <BR><font color=\"Blue\">◄</font> علت ابنه، بسبب نسبت مردم آن ناحیت . <BR><font color=\"Blue\">◄</font> هر چیز لاینحل ؛ فلان کتاب علتهای قمی بسیار دارد. (آنندراج ) (ناظم الاطباء). و رجوع به میخ قمی در امثال و حکم دهخدا شود.<br></font></div>'),
(185290, 'علت مادی', '<span class=\"hlight\">علت مادی .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِ مادْ دی ]</font></b> (ترکیب وصفی، اِ مرکب ) ماده ای که صنعت صانع بر آن تعلق میگیرد. (ناظم الاطباء). و آن جزء مقوم شی ٔ، و محل استقرار قوه، یعنی حامل قوه است . (از فرهنگ اصطلاحات فلسفی ). و رجوع به علت شود.<br></font></div>'),
(185291, 'علت مبقیه', '<span class=\"hlight\">علت مبقیه .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِ م ُ ی َ <span class=\"hlight\" dir=\"rtl\">/</span>ی ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) علتی که باعث بقای موجودات بعد از حدوث میشود. (از فرهنگ اصطلاحات فلسفی ).<br></font></div>'),
(185292, 'علت مشایخ', '<span class=\"hlight\">علت مشایخ .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِ م َ ی ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) خارشی که در مقعد بروز کند. (ناظم الاطباء). بیماریی است که از یبوست سوداوی در مقعد بعضی پیران خارشی پیدا میشود. (غیاث اللغات ) (آنندراج ). <BR><font color=\"Blue\">◄</font> بیماری ابنه . (ناظم الاطباء). داءالمشایخ . علت پشت .<br></font></div>'),
(185293, 'علت ناقصه', '<span class=\"hlight\">علت ناقصه .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْل َ ت ِ ق ِ ص َ <span class=\"hlight\" dir=\"rtl\">/</span> ص ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) علتی که خود بتنهائی و مستقلاً موجب وجود چیزی نگردد، یعنی معلول به وجود آن، واجب نشود. و هر یک از علل چهارگانه بتنهائی علت ناقصه اند. (از فرهنگ اصطلاحات فلسفی ).<br></font></div>'),
(185294, 'علت پشت', '<span class=\"hlight\">علت پشت .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت ِ پ ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) بیماری ابنه . (ناظم الاطباء). داءالمشایخ . علت مشایخ .<br></font></div>'),
(185295, 'علتین', '<span class=\"hlight\">علتین .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ت َ ]</font></b> (ع اِ) تثنیه ٔ علت . در مثنوی بمعنی نکال الاَّخرة و الاولی است . (غیاث از لطائف ) (آنندراج ).<br></font></div>'),
(185296, 'علث', '<span class=\"hlight\">علث .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) آنچه بر غیر عادت و اختیار خورده شود. <BR><font color=\"Blue\">◄</font> پاره ای از چوب آتش زنه . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> گیاه خشک . (منتهی الارب ) (ناظم الاطباء). ج، أعلاث . <BR><font color=\"Blue\">◄</font> نوعی از کاسنی صحرائی که دارای صمغی است مانند مصطکی . (برهان ) (آنندراج ).<br></font></div>'),
(185297, 'علث', '<span class=\"hlight\">علث .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) مخلوط کردن و آمیختن . <BR><font color=\"Blue\">◄</font> گردآوردن و جمع کردن . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> دباغی کردن و پیراستن مشک و از قبیل آن . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء) (آنندراج ). <BR><font color=\"Blue\">◄</font> آتش ندادن آتش زنه . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ) درخت گز. رجوع به طَرفاء شود. <BR><font color=\"Blue\">◄</font> درخت شور گز. رجوع به اثل شود. <BR><font color=\"Blue\">◄</font> گیاه خارداری که از آن ترنجبین گیرند. رجوع به حاج شود. <BR><font color=\"Blue\">◄</font> درخت خشخاش . رجوع به ینبوت شود. <BR><font color=\"Blue\">◄</font> گیاهی است ترش که در ریشه ٔ درخت خرما میروید و آن را میکشد. رجوع به عِکرش شود. (از ذیل اقرب الموارد). ج، أعلاث .<br></font></div>'),
(185298, 'علث', '<span class=\"hlight\">علث .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع مص ) بسختی جنگیدن و کارزار کردن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ملازمت بر کارزار. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گرفتن برای از هم دریدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) سختی کارزار. (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آنچه با گندم و جو مخلوط شده است و باید آن را بیرون افکند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گندمی که با جو مخلوط شده باشد. (از المنجد). <BR><font color=\"Blue\">◄</font> طعامی که با جو مخلوط باشد. (از ذیل اقرب الموارد).<br></font></div>'),
(185299, 'علث', '<span class=\"hlight\">علث .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ ]</font></b> (ع ص ) سخت جنگ . کسی که در جنگ پایدار باشد.(از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آنکه به غیر پدر خود منسوب باشد. (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> لازم گیرنده کسی را برای گرفتن حق خود. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تیر و سهم بی فایده . (از المنجد).<br></font></div>'),
(185300, 'علث', '<span class=\"hlight\">علث .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است در ساحل شرقی دجله بین عُکبَرا و سامراء، و آن وقف بر علویهاست . (از معجم البلدان ).<br></font></div>'),
(185301, 'علج', '<span class=\"hlight\">علج .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ]</font></b> (ع ص ) سخت و قوی . <BR><font color=\"Blue\">◄</font> افکننده . <BR><font color=\"Blue\">◄</font> نیکوکننده ٔ کارها. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185302, 'علج', '<span class=\"hlight\">علج .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ ]</font></b> (ع ص ) سخت و قوی . (منتهی الارب ) (از ذیل اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> نیکوکننده ٔ کارها. (منتهی الارب ) (ناظم الاطباء).<br></font></div>'),
(185303, 'علج', '<span class=\"hlight\">علج .</span> <font color=\"DarkGreen\"><b>[ ع ُل ْ ل َ ]</font></b> (ع ص ) سخت و قوی . <BR><font color=\"Blue\">◄</font> افکننده <BR><font color=\"Blue\">◄</font> نیکوکننده ٔ کارها. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185304, 'علج', '<span class=\"hlight\">علج .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع مص ) سخت و قوی شدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) درختان کوچک خرما. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185305, 'علج', '<span class=\"hlight\">علج .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) چیره شدن در معالجه . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> پریشان شدن . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (ص ) سخت و قوی . <BR><font color=\"Blue\">◄</font> افکننده . <BR><font color=\"Blue\">◄</font> نیکوکننده ٔ کارها. (از اقرب الموارد).<br></font></div>'),
(185306, 'علج', '<span class=\"hlight\">علج .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) قیّم و نیکودارنده . <BR><font color=\"Blue\">◄</font> درشت و قوی . <BR><font color=\"Blue\">◄</font> غیرعرب کافر. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کافر و بی دین، خواه عرب باشد یا غیر آن . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> مردی که موی صورتش روئیده باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) خر. <BR><font color=\"Blue\">◄</font> خر وحشی فربه و توانا. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> نان گرده ٔ درشت کرانه . (منتهی الارب ). گرده نان درشت کرانه . (از اقرب الموارد). ج، عُلوج، أعلاج، عِلَجة.<br></font></div>'),
(185307, 'علجان', '<span class=\"hlight\">علجان .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) درختان خاردار. (منتهی الارب ) (از اقرب الموارد) (آنندراج ) (ناظم الاطباء).<br></font></div>'),
(185308, 'علجان', '<span class=\"hlight\">علجان .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع اِمص ) اضطراب و پریشانی ماده شتر. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) گیاهی که از آن مسواک سازند. (منتهی الارب ) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> گیاهی که بدان دست شویند، و آن را «کاه مکه » نیز گویند.(برهان ) (ناظم الاطباء). اذخر و غسول . (از برهان ).<br></font></div>'),
(185309, 'علجان', '<span class=\"hlight\">علجان .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) نام جائی است، و در شعر ابودؤاد ایادی آمده است <span class=\"hlight\">:</span> <br>بالبطن من علجان حَل ّ به <br>دان فُوَیْق الارض اذ وَدقت .<br><font color=\"Red\">(از معجم البلدان ).</font><br></font></div>'),
(185310, 'علجانة', '<span class=\"hlight\">علجانة.</span><font color=\"DarkGreen\"><b>[ ع َ ل َ ن َ ]</font></b> (ع اِ) خاکی که باد در بن درخت گرد آورد. (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185311, 'علجانة', '<span class=\"hlight\">علجانة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ن َ ]</font></b> (اِخ ) نام موضعی است، و در شعر حبیب هذلی آمده است <span class=\"hlight\">:</span> <br>فجبال أیلة فالمحصب دوننا<br>فاُلات ذی علجانة فذهاب .<br><font color=\"Red\">(از معجم البلدان ).</font><br></font></div>'),
(185312, 'علجم', '<span class=\"hlight\">علجم .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ع ص ) درازبالا. طویل . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرداب بسیارآب . (از ذیل اقرب الموارد).<br></font></div>'),
(185313, 'علجم', '<span class=\"hlight\">علجم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ج ُ ]</font></b> (ع ص ) سیاه پررنگ . (از ذیل اقرب الموارد).<br></font></div>'),
(185314, 'علجن', '<span class=\"hlight\">علجن .</span> <font color=\"DarkGreen\"><b>[ ع َ ج َ ]</font></b> (ع ص ) ماده شتر پرگوشت . <BR><font color=\"Blue\">◄</font> زن شوخ و بی باک . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185315, 'علجوم', '<span class=\"hlight\">علجوم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) تاریکی شب . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> سیاه پررنگ . (از ذیل اقرب الموارد). <BR><font color=\"Blue\">◄</font> باغ بسیاردرخت . (منتهی الارب ) (آنندراج )(ناظم الاطباء). <BR><font color=\"Blue\">◄</font> باغی که درختان خرما بسیار داشته باشد. (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بیشه و نیزار. (از ذیل اقرب الموارد) (از المنجد). <BR><font color=\"Blue\">◄</font> موج دریا. (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آب بسیار. <BR><font color=\"Blue\">◄</font> غوک و قورباغه ٔ نر. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کنه . <BR><font color=\"Blue\">◄</font> آهوی گندم گون . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ماده آهوی خواستار گشنی . (از ذیل اقرب الموارد). <BR><font color=\"Blue\">◄</font> شترمرغ نر. <BR><font color=\"Blue\">◄</font> بط نر. (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> قوچ . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بز کوهی . <BR><font color=\"Blue\">◄</font> گاو نر کلان سال . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ماده الاغ بسیارگوشت . <BR><font color=\"Blue\">◄</font> ماده شتر کلانسال . (از ذیل اقرب الموارد). <BR><font color=\"Blue\">◄</font> شتر سخت و توانا. <BR><font color=\"Blue\">◄</font> شتر برگزیده . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> نام مرغی سپید. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> جماعت مردم . (از ذیل اقرب الموارد) (از المنجد). ج، عَلاجیم .<br></font></div>'),
(185316, 'علجون', '<span class=\"hlight\">علجون .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) شتر بسیارگوشت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ماده شتر سخت و توانا. (منتهی الارب ) (ناظم الاطباء).<br></font></div>'),
(185317, 'علد', '<span class=\"hlight\">علد.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) سخت و صلب گشتن . <BR><font color=\"Blue\">◄</font> (ص ) سخت و شدید. <BR><font color=\"Blue\">◄</font> (اِ) عصب و پی گردن . (منتهی الارب ) (از اقرب الموارد). ج، أعلاد.<br></font></div>'),
(185318, 'علذمی', '<span class=\"hlight\">علذمی .</span> <font color=\"DarkGreen\"><b>[ ع َ ذَ می ی ]</font></b> (ع ص ) حریص . کسی که هرچه بیابد بخورد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185319, 'علز', '<span class=\"hlight\">علز.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع مص ) بی آرام گردیدن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چیره شدن سبکی بر شخص . (از منتهی الارب ) (از اقرب الموارد) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> چیره شدن قَلَق و تفتگی بر شخص . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خروش کردن . فریاد برآوردن . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> متمایل شدن . اشتیاق پیدا کردن . <BR><font color=\"Blue\">◄</font> مریض شدن . <BR><font color=\"Blue\">◄</font> (اِ) خروش و اضطراب شدیدی که بر اثر ادامه یافتن مرض یا شدت حرص و غم و اندوه به انسان دست میدهد. (از اقرب الموارد).<br></font></div>'),
(185320, 'علز', '<span class=\"hlight\">علز.</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ ]</font></b> (ع ص ) دردناک بی آرام که خواب نکند. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185321, 'علزان', '<span class=\"hlight\">علزان .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع مص )عَلَز است در همه ٔ معانی . (از ذیل اقرب الموارد).<br></font></div>'),
(185322, 'علس', '<span class=\"hlight\">علس .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع اِ) کنه ٔ بزرگ . <BR><font color=\"Blue\">◄</font> نوعی از مورچه . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> نوعی از گندم که دو یا سه دانه در یک غلاف دارد که گویند از «صنعاء» است . (منتهی الارب ) (از اقرب المواد). <BR><font color=\"Blue\">◄</font> گندم مکه . (منتهی الارب ) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> دانه ای سیاه که در هنگام خشک سالی خورده شود. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> عدس . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185323, 'علس', '<span class=\"hlight\">علس .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) ابن اسود کندی . از کسانی است که بر پیغمبر (ص ) وارد شده است . (از الاصابة ج <span class=\"hlight\" dir=\"rtl\">٤</span> قسم اول ص <span class=\"hlight\" dir=\"rtl\">٢٦٢</span>).<br></font></div>'),
(185324, 'علس', '<span class=\"hlight\">علس .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) ابن نعمان بن عمروبن عرفجةبن فاتک بن امری ءالقیس کندی . از کسانی است که بر پیغمبر (ص ) وارد شده است . (از الاصابة ج <span class=\"hlight\" dir=\"rtl\">٤</span> قسم اول ص <span class=\"hlight\" dir=\"rtl\">٢٦٢</span>).<br></font></div>'),
(185325, 'علس', '<span class=\"hlight\">علس .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (ع مص ) آشامیدن . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> خوردن . (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> یافتن چیزی برای خوردن . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ) آشامیدنی . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سیاهی شب . (از اقرب الموارد).<br></font></div>'),
(185326, 'علسة', '<span class=\"hlight\">علسة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ س َ ]</font></b> (ع اِ) حیوان کوچکی است شبیه به مورچه . (از اقرب الموارد).<br></font></div>'),
(185327, 'علسة', '<span class=\"hlight\">علسة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ س َ ]</font></b> (اِخ ) ابن عدی بلوی . از کسانی است که در «تحت الشجرة» بیعت کرد، و در فتح مصر نیز حاضر بود. (از الاصابة ج <span class=\"hlight\" dir=\"rtl\">٤</span> قسم اول ص <span class=\"hlight\" dir=\"rtl\">٢٥٢</span>).<br></font></div>'),
(185328, 'علسی', '<span class=\"hlight\">علسی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ سی ی ]</font></b> (ع ص ) مرد و یا شتر قوی و استوارخلقت . <BR><font color=\"Blue\">◄</font> (اِ) گیاهی است که شکوفه ٔ آن به سوسن ماند. (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185329, 'علش', '<span class=\"hlight\">علش .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِمص ) سبکی . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آزمندی و حرص . (ناظم الاطباء) (از فرهنگ جانسن ).<br></font></div>'),
(185330, 'علشط', '<span class=\"hlight\">علشط.</span><font color=\"DarkGreen\"><b>[ ع َ ل َش ْ ش َ ]</font></b> (ع ص ) بدخو. و در صحت این کلمه شک است . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185331, 'علض', '<span class=\"hlight\">علض .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) جنبانیدن میخ و از قبیل آن برای برکندن آن . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185332, 'علط', '<span class=\"hlight\">علط.</span> <font color=\"DarkGreen\"><b>[ ع ُل َ ]</font></b> (ع ص ) بی مهار. (منتهی الارب ) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ج ِ عُلطة. (از اقرب الموارد).<br></font></div>'),
(185333, 'علط', '<span class=\"hlight\">علط.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) کسی را به بدی یاد کردن . <BR><font color=\"Blue\">◄</font> گردن شتر را داغ کردن . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> علامت گذاشتن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> تیرزدن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) سیاهیی که زنان برای زینت به رخسار خود میکشند.(منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> اثر داغ بر گردن شتر. (از اقرب الموارد).<br></font></div>'),
(185334, 'علط', '<span class=\"hlight\">علط.</span> <font color=\"DarkGreen\"><b>[ ع ُ ل ُ ]</font></b> (ع ص، اِ) بی مهار. <BR><font color=\"Blue\">◄</font> بی گردن بند. <BR><font color=\"Blue\">◄</font> بی نشان و داغ . <BR><font color=\"Blue\">◄</font> خر کوتاه . <BR><font color=\"Blue\">◄</font> ماده شتر درازبالا. (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). ج، أعلاط. <BR><font color=\"Blue\">◄</font> ج ِ عِلاط. (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185335, 'علطبیس', '<span class=\"hlight\">علطبیس .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (ع ص ) لغزان و براق . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185336, 'علطتان', '<span class=\"hlight\">علطتان .</span> <font color=\"DarkGreen\"><b>[ ع ُ طَ ]</font></b> (ع اِ) دو طوقی که در گردن قمری و برخی پرندگان دیگر است . (از اقرب الموارد). رجوع به علاطان شود. <BR><font color=\"Blue\">◄</font> دو مهره ای که بر گردن برخی کودکان آویزند. (از اقرب الموارد).<br></font></div>'),
(185337, 'علطسة', '<span class=\"hlight\">علطسة.</span> <font color=\"DarkGreen\"><b>[ ع َ طَ س َ ]</font></b> (ع مص )در بیراهه دویدن . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185338, 'علطمیس', '<span class=\"hlight\">علطمیس .</span> <font color=\"DarkGreen\"><b>[ ع َ طَ ]</font></b> (ع ص ) بسیار خورنده و بلعکننده . (منتهی الارب ) (از اقرب الموارد) <BR><font color=\"Blue\">◄</font> درشت اندام و قوی . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دختر پرگوشت نیکوقامت . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> سر سطبر بی موی . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ماده شتر درشت اندام بلندقامت . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185339, 'علطوس', '<span class=\"hlight\">علطوس .</span> <font color=\"DarkGreen\"><b>[ ع ِ طَ ]</font></b> (ع ص ) مرد بلندبالا. (منتهی الارب ) (ازاقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ماده شتربرگزیده ٔ هوشیار. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185340, 'علطوش', '<span class=\"hlight\">علطوش .</span> <font color=\"DarkGreen\"><b>[ ع ِ طَ ]</font></b> (ع ص ) زن زیبا و نیکو. (از ذیل اقرب الموارد).<br></font></div>'),
(185341, 'علع', '<span class=\"hlight\">علع.</span><font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع اِ صوت ) کلمه ایست که بدان گوسفند و شتر را رانند. (منتهی الارب ) (آنندراج ) (ناظم الاطباء).<br></font></div>'),
(185342, 'علعال', '<span class=\"hlight\">علعال .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) کوهی است در شام، مشرف بر بثینة، بین غور و جبال سراة. (از معجم البلدان ).<br></font></div>'),
(185343, 'علعال', '<span class=\"hlight\">علعال .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) چکاوک نر. (از تاج العروس ) (ناظم الاطباء). علعل .<br></font></div>'),
(185344, 'علعل', '<span class=\"hlight\">علعل .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َ ]</font></b> (ع اِ) نره . <BR><font color=\"Blue\">◄</font> نره ٔ نرم . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> استخوانی که مانند زبان بر شکم آید. (از تاج العروس ) (ناظم الاطباء). و به اصطلاح تشریح آن را «عظم خنجری » نامند. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> چکاوک نر. (از تاج العروس ) (ناظم الاطباء). علعال . <BR><font color=\"Blue\">◄</font> کلمه ای که بدان گوسفند و شتر را خوانند. (از تاج العروس ) (منتهی الارب ) (ناظم الاطباء).<br></font></div>'),
(185345, 'علعل', '<span class=\"hlight\">علعل .</span> <font color=\"DarkGreen\"><b>[ ع ُ ع ُ ]</font></b> (ع اِ) نره . <BR><font color=\"Blue\">◄</font> نره ٔ نرم . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> استخوانی که مانند زبان بر شکم آید. (از تاج العروس ) (ناظم الاطباء). و به اصطلاح تشریح آن را «عظم خنجری » گویند. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> چکاوک نر. (از تاج العروس ) (ناظم الاطباء). علعال .<br></font></div>'),
(185346, 'علعل', '<span class=\"hlight\">علعل .</span> <font color=\"DarkGreen\"><b>[ ع َ ع َل ْ ل َ ]</font></b> (ع حرف ) بمعنی لعل ّ است . (ناظم الاطباء).<br></font></div>'),
(185347, 'علعلان', '<span class=\"hlight\">علعلان .</span> <font color=\"DarkGreen\"><b>[ع َ ع َ ]</font></b> (ع اِ) درختی است کلان که برگهای آن مانند برگ درخت قُرم است . (از تاج العروس ) (ناظم الاطباء).<br></font></div>'),
(185348, 'علعول', '<span class=\"hlight\">علعول .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) بدی دائم و پیوسته . <BR><font color=\"Blue\">◄</font> اضطراب و بی قراری و بی ثباتی . <BR><font color=\"Blue\">◄</font> پیکار و جدال . (از تاج العروس ) (ناظم الاطباء).<br></font></div>'),
(185349, 'علف', '<span class=\"hlight\">علف .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) خوراک دادن به ستور. <BR><font color=\"Blue\">◄</font> بسیار آشامیدن . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185350, 'علف', '<span class=\"hlight\">علف .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) بسیار خورنده . (از اقرب الموارد) (ناظم الاطباء). نیک خورنده . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) درختی است در یمن که برگش مانند برگ انگور بوده آن را خشک میکنند و به عوض سرکه با گوشت می پزند. (منتهی الارب ) (از اقرب الموارد). رجوع به عُلف شود.<br></font></div>'),
(185351, 'علف', '<span class=\"hlight\">علف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) درختی است در یمن که برگش مانند برگ انگور بوده آن را خشک میکنند و به عوض سرکه با گوشت میپزند. (منتهی الارب ) (از اقرب الموارد). رجوع به عِلف شود. <BR><font color=\"Blue\">◄</font> ج ِ عَلوفة. (منتهی الارب ) (آنندراج ).<br></font></div>'),
(185352, 'علف', '<span class=\"hlight\">علف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل ُ ]</font></b> (ع اِ) ج ِ عَلوفه . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185353, 'علف', '<span class=\"hlight\">علف .</span> <font color=\"DarkGreen\"><b>[ ع ُل ْ ل َ ]</font></b> (ع اِ) میوه ٔ طلح که شبیه باقلای تازه است و شتر آن را خورد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185354, 'علف', '<span class=\"hlight\">علف .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع اِ) گیاه . <BR><font color=\"Blue\">◄</font> هر گیاه سبز. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> خورش ستور و جز آن . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). ج، عُلوفه، أعلاف، عِلاف <span class=\"hlight\">:</span> حال علف چنان شد که اشتر تا دامغان ببردند و از آنجا علف آوردند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٦٢٢</span>). میگویند ده من گندم به درمی است و پانزده من جو به درمی . آنجای رویم و آن علف به رایگان خورده آید. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٥٢</span>). اما کاه که علف ستور است خود بتبع حاصل آید. (کلیله ص <span class=\"hlight\" dir=\"rtl\">٨٦٨</span>).<br>- <span class=\"hlight\">امثال </span> :<br> <span class=\"hlight\">علف بدی نیست اسفناج </span> .<br><span class=\"hlight\">علف به دهان بزی شیرین می آید</span>، نظیر: آب دهن هر کس به دهن خودش مزه میدهد. (امثال و حکم دهخدا).<br> <span class=\"hlight\">علف خرس نیست </span>، نظیر: پول علف خرس نیست . (امثال و حکم دهخدا).<br> <span class=\"hlight\">علف درب آغل تلخ است </span> .<br> <BR><font color=\"Blue\">◄</font> آذوقه . توشه . ارزاق <span class=\"hlight\">:</span> حال علف چنان شد که یک روز دیدم ...امیر نشسته بود... و تا نماز پیشین روزگار شد تا پنج روزه علف راست کردند که غلامان را نان و گوشت و اسبان را کاه و جو نبود. (تاریخ بیهقی چ فیاض ص <span class=\"hlight\" dir=\"rtl\">٦٠٩</span>).<br>- <span class=\"hlight\">بی علفی </span> ؛ بی آذوقگی <span class=\"hlight\">:</span> مردم و ستور بسیار از بی علفی بمرد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٦١٢</span>).<br><BR><font color=\"Blue\">◄</font> گاهی قصد از مطلق روییدنی است . (قاموس مقدس ). <BR><font color=\"Blue\">◄</font> گیاهی است که آن را به فارسی اسپست و به عربی فصفصه گویند. (برهان قاطع). یونجه . (مخزن الادویه ). <BR><font color=\"Blue\">◄</font> کاه . (آنندراج ). <BR><font color=\"Blue\">◄</font> قصیل . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اصطلاح عرفان ) شهوت و آرزوهای نفس، و آنچه نفس را در آن حظی باشد. (از فرهنگ مصطلحات عرفا و شعرا).<br></font></div>'),
(185355, 'علف آستانه', '<span class=\"hlight\">علف آستانه .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ن َ ]</font></b>(اِخ ) دهی است از دهستان خاوه ٔ بخش دلفان شهرستان خرم آباد واقع در <span class=\"hlight\" dir=\"rtl\">١٥</span> هزارگزی جنوب خاوری نورآباد و <span class=\"hlight\" dir=\"rtl\">١٥</span> هزارگزی جنوب خاوری راه اتومبیل رو خرم آباد به کرمانشاه . منطقه ایست کوهستانی و سردسیر و مالاریایی دارای <span class=\"hlight\" dir=\"rtl\">٢٤٠</span> تن سکنه . آب آن از سراب گیو و سراب زلزله تأمین میشود. محصول آن غلات و لبنیات است . شغل اهالی زراعت و گله داری است . دارای راه مالرو است . ساکنین آن از طایفه ٔ خاوه هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(185356, 'علف بر', '<span class=\"hlight\">علف بر.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ب ُ ]</font></b> (اِ مرکب ) ابزاری است از نوع داس، که در طویله بوسیله ٔ آن یونجه و امثال آن را بریده به چهارپایان میدهند. اره ٔ کمان شکل که بر پایه ای نصب کنند و بدان دسته های یونجه و علف را به قطعات کوچک بُرند و به ستور دهند.<br></font></div>'),
(185357, 'علف ترانگبین', '<span class=\"hlight\">علف ترانگبین .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ف ِ ت َ اَ گ َ ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به ترانگبین و ترنجبین شود.<br></font></div>'),
(185358, 'علف ترنجبین', '<span class=\"hlight\">علف ترنجبین .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ف ِ ت َ رَ ج َ ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به ترنجبین شود.<br></font></div>'),
(185359, 'علف خانه', '<span class=\"hlight\">علف خانه .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) خانه ای که در آن کاه انبار کنند. (بهار عجم ) (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از دنیا و عالم کون و فساد است . (برهان ) (ناظم الاطباء) (آنندراج ).<br></font></div>'),
(185360, 'علف خشک', '<span class=\"hlight\">علف خشک .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ف ِ خ ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) گیاه خشک . (ناظم الاطباء).<br></font></div>'),
(185361, 'علف خوار', '<span class=\"hlight\">علف خوار.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) هرکه علف خورد. علف چر. گیاهخوار. علف خواره . <BR><font color=\"Blue\">◄</font> (اِ مرکب ) چراگاه و علف زار. (ناظم الاطباء). علف چر <span class=\"hlight\">:</span> علفخوار و مرغزارها قوریغ کردند و از چرانیدن چهارپایان محفوظ گردانید. (جهانگشای جوینی ). از چرانیدن چهارپایان محفوظ گردانید تا علفخوار نگردد. (جهانگشای جوینی ). رسول بدو فرستاد که ما را علفخوار معین کنی . (جهانگشای جوینی ).<br></font></div>'),
(185362, 'علف خواره', '<span class=\"hlight\">علف خواره .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (نف مرکب ) علفخوار. علفچر. که علف خورد. <BR><font color=\"Blue\">◄</font> (اصطلاح طبیعی ) حیوانی که از علف و دیگر مواد نباتی تغذیه میکند. ج، علف خوارگان . (ناظم الاطباء).<br></font></div>'),
(185363, 'علف خوارگان', '<span class=\"hlight\">علف خوارگان .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خارَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) ج ِ علف خواره . (ناظم الاطباء).<br></font></div>'),
(185364, 'علف خور', '<span class=\"hlight\">علف خور.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ ]</font></b> (نف مرکب ) مخفف علف خوار. هر حیوانی که بر آخور بسته شده و درآن خوراک خورد، مانند اسب و خر و استر. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> شکم پرست و پرخور. (ناظم الاطباء).<br></font></div>'),
(185365, 'علف دان', '<span class=\"hlight\">علف دان .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِ مرکب ) انبار علف و کاه و غله . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> مخلاة. توبره . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> معده ٔ علف خوارگان . (ناظم الاطباء).<br></font></div>'),
(185366, 'علف دان', '<span class=\"hlight\">علف دان .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دهی است از دهستان عبیدلی بخش لنگه ٔ شهرستان لار واقع در <span class=\"hlight\" dir=\"rtl\">١٥٠</span> هزارگزی باختر لنگه و <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی راه فرعی بندرلنگه به مقام .در دامنه ٔ کوه قرار دارد و هوای آن گرمسیر و مرطوب و مالاریائی است . دارای <span class=\"hlight\" dir=\"rtl\">٨٩</span> تن سکنه . آب آن از چاه و باران به دست می آید. محصول آن غلات و خرما است . شغل اهالی آن زراعت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(185367, 'علف زار', '<span class=\"hlight\">علف زار.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِ مرکب ) چراگاه . مرغزار. زمینی که علف بسیار دارد. (از ناظم الاطباء) (آنندراج ) <span class=\"hlight\">:</span> <br>کجا بد علفزار و آب روان <br>فرودآمد آن جایگه پهلوان .<br> <font color=\"Red\">فردوسی .</font><br>ندیدستی که گاوی در علفزار<br>بیالاید همه گاوان ده را.<br><font color=\"Red\">سعدی (گلستان ).</font><br></font></div>'),
(185368, 'علف سبز', '<span class=\"hlight\">علف سبز.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ف ِ س َ ]</font></b> (ترکیب وصفی، اِ مرکب ) گیاه تر و تازه . (ناظم الاطباء).<br></font></div>'),
(185369, 'علف فروش', '<span class=\"hlight\">علف فروش .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ف ُ ]</font></b> (نف مرکب ) کسی که شغلش علف فروشی است . آنکه علف فروشد.آنکه کاه و یونجه فروشد. علاّف . رجوع به علاّف شود.<br></font></div>'),
(185370, 'علف من', '<span class=\"hlight\">علف من .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ف ِ م َن ن ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به ترنجبین شود.<br></font></div>'),
(185371, 'علف هفت بند', '<span class=\"hlight\">علف هفت بند.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ف ِ هََب َ ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به هفت بند شود.<br></font></div>'),
(185372, 'علف چای', '<span class=\"hlight\">علف چای .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ف ِ]</font></b> (ترکیب اضافی، اِ مرکب ) رجوع به هوفاریقون شود.<br></font></div>'),
(185373, 'علف چر', '<span class=\"hlight\">علف چر.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ چ َ ]</font></b> (نف مرکب ) چرنده ٔ علف . گیاه خوار. علفخوار. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) مقدار علفی که برای یک دسته ستور صرف شود: علف چر مالهای ما روزی یک خروار است . <BR><font color=\"Blue\">◄</font> مرتع.زمینی که برای چریدن گاو و گوسفند و جز آن رها کنند. زمین گیاهناک، چریدن گاو و گوسفند و امثال آنرا.<br>- <span class=\"hlight\">حق علف چر</span> ؛ بهای چرانیدن علف زمین که به مالک آن دهند.<br></font></div>'),
(185374, 'علف چین', '<span class=\"hlight\">علف چین .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (نف مرکب ) آنکه علف چیند. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) ابزاری است داس مانند که بوسیله ٔ آن علف و یونجه را می چینند. <BR><font color=\"Blue\">◄</font> (اِمص مرکب ) در تداول عامه با اندک مسامحه بجای علف چینی بکار رود.<br>- <span class=\"hlight\">موسم علف چین </span> ؛ فصل چیدن علف .<br></font></div>'),
(185375, 'علفة', '<span class=\"hlight\">علفة.</span> <font color=\"DarkGreen\"><b>[ ع ُل ْ ل َ ف َ ]</font></b> (ع اِ) یک دانه از میوه ٔ علّف که میوه ٔ طلح است . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185376, 'علفتانی', '<span class=\"hlight\">علفتانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ نی ی ]</font></b> (ع ص ) مرد گول و احمق که بی پروا سخن گوید و خیال صواب و خطای آن را نکند. (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء).<br></font></div>'),
(185377, 'علفطه', '<span class=\"hlight\">علفطه .</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ طَ ]</font></b> (ع مص ) مخلوط کردن و آمیختن . (منتهی الارب ) (از اقرب الموارد) (آنندراج ).<br></font></div>'),
(185378, 'علفناک', '<span class=\"hlight\">علفناک .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ص مرکب ) چراگاه و زمینی که دارای علف بسیار باشد. (ناظم الاطباء).<br></font></div>'),
(185379, 'علفه', '<span class=\"hlight\">علفه .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ]</font></b> (از ع، اِ) آنچه پادشاهان برای پذیرائی سُفَرا و لوازم نگاه داشت ایشان و ملازمان و اتباع و دواب ایشان به مصرف رسانند. (حاشیه ٔ چهارمقاله ٔ عروضی ص <span class=\"hlight\" dir=\"rtl\">١٩</span> از ذیل قوامیس عرب از دزی ) <span class=\"hlight\">:</span> خوارزمشاه خواجه حسین میکال را بجای نیک فرودآورد و علفه ٔ شگرف فرمود. (چهارمقاله ص <span class=\"hlight\" dir=\"rtl\">١١٩</span>).<br></font></div>'),
(185380, 'علفوت', '<span class=\"hlight\">علفوت .</span> <font color=\"DarkGreen\"><b>[ ع ِ ف َ ]</font></b> (ع ص ) مرد گول و احمق که بی پروا سخن گوید و خیال صواب و خطای آن را نکند. (منتهی الارب ) (از اقرب الموارد). رجوع به علفتانی شود.<br></font></div>'),
(185381, 'علفوت', '<span class=\"hlight\">علفوت .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) مرد گول و احمق که بی پروا سخن گوید و خیال صواب و خطای آن را نکند. (منتهی الارب ) (از اقرب الموارد). رجوع به علفتانی شود.<br></font></div>'),
(185382, 'علفوف', '<span class=\"hlight\">علفوف .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) مرد بدخوی کلان سال . <BR><font color=\"Blue\">◄</font> پیر آکنده گوشت بسیارموی . <BR><font color=\"Blue\">◄</font> پیره زال . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> اسب نر استواراندام سطبر. <BR><font color=\"Blue\">◄</font> ناقة علفوف السنام ؛ ماده شتر پیچیده سنام، که گوئی آن کوهان را به پارچه ای پیچیده اند. (منتهی الارب ) (از اقرب الموارد).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(185383, 'علفی', '<span class=\"hlight\">علفی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ]</font></b> (ص نسبی ) از علف . <BR><font color=\"Blue\">◄</font> نوعی پارچه است .<br>- <span class=\"hlight\">ابریشم علفی </span> ؛ پارچه ای که از ابریشم مصنوعی (غیرطبیعی ) ساخته شده باشد.<br></font></div>'),
(185384, 'علق', '<span class=\"hlight\">علق .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) دانستن و آگاه شدن و دریافتن . <BR><font color=\"Blue\">◄</font> به دل دوست داشتن . <BR><font color=\"Blue\">◄</font> کشتن و به قتل رساندن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خصومت کردن . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> درآویختن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> باردار شدن . <BR><font color=\"Blue\">◄</font> چسبیدن زالو در دهان ستور به وقت آب خوردن . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> شروع کردن . <BR><font color=\"Blue\">◄</font> (ص، اِ) دوست دارنده . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> پیرو. <BR><font color=\"Blue\">◄</font> گرانمایه از هر چیز. <BR><font color=\"Blue\">◄</font> انبان . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خنور. (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> می . (منتهی الارب ) (از اقرب الموارد)(ناظم الاطباء). <BR><font color=\"Blue\">◄</font> می کهنه . <BR><font color=\"Blue\">◄</font> جامه ٔ نیکو. <BR><font color=\"Blue\">◄</font> سپر. <BR><font color=\"Blue\">◄</font> شمشیر.(منتهی الارب ) (از اقرب الموارد). ج، أعلاق، عُلوق .<br></font></div>'),
(185385, 'علق', '<span class=\"hlight\">علق .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) نام سوره ٔ <span class=\"hlight\" dir=\"rtl\">٩٦</span> از قرآن کریم، مکی است و دارای <span class=\"hlight\" dir=\"rtl\">١٩</span> آیت .<br></font></div>'),
(185386, 'علق', '<span class=\"hlight\">علق .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) (ذو...) کوهی است از بنی اسد (ازاقرب الموارد) (منتهی الارب )، که در آن یومی (جنگی ) بزرگ دارند. (از معجم البلدان ) (منتهی الارب ). و بر بالای آن تخته سنگی سیاه قرار دارد. (از معجم البلدان ).<br></font></div>'),
(185387, 'علق', '<span class=\"hlight\">علق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ]</font></b> (ع اِ) بلا و سختی . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> گروه بسیار. <BR><font color=\"Blue\">◄</font> مرگ ها. <BR><font color=\"Blue\">◄</font> کارها. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> ج ِ عُلقة. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185388, 'علق', '<span class=\"hlight\">علق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) مخلاف و ناحیه ایست در یمن . (معجم البلدان ).<br></font></div>'),
(185389, 'علق', '<span class=\"hlight\">علق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل ُ ]</font></b> (ع اِ) مرگ ها. <BR><font color=\"Blue\">◄</font> کارها. <BR><font color=\"Blue\">◄</font> گروه بسیار. (از اقرب الموارد).<br></font></div>'),
(185390, 'علق', '<span class=\"hlight\">علق .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع مص ) به دل دوست داشتن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کشتن . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> خصومت کردن . <BR><font color=\"Blue\">◄</font> درآویختن . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آویختن . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> باردار گردیدن . <BR><font color=\"Blue\">◄</font> چسبیدن زالو در دهان ستور به وقت آب خوردن . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> چریدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شروع کردن . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِمص ) خصومت و دشمنی همیشگی . <BR><font color=\"Blue\">◄</font> عشق و محبت دائمی . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> حب ّ و دوستی . <BR><font color=\"Blue\">◄</font> (اِ) خون . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> خون بسیار سرخ . <BR><font color=\"Blue\">◄</font> خون سطبر و غلیظ. <BR><font color=\"Blue\">◄</font> خون بسته . <BR><font color=\"Blue\">◄</font> زالو. <BR><font color=\"Blue\">◄</font> هر چیز که آویخته شود. <BR><font color=\"Blue\">◄</font> گلی که به دست چسبد. <BR><font color=\"Blue\">◄</font> آنقدر از درخت و علف که روزگذار ستور باشد. <BR><font color=\"Blue\">◄</font> معظم و بیشتر راه . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> میانه ٔ راه . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> چوبی که بدان چرخ چاه آویزند. <BR><font color=\"Blue\">◄</font> چرخ چاه . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ریسمان دلو. (منتهی الارب ) (از ذیل اقرب الموارد) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> ریسمان به چرخ آویخته . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دلو بزرگ . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> باقی مانده ٔ روغن در دلو، که برای چرب کردن بدان مالیده اند. (از ذیل اقرب الموارد). <BR><font color=\"Blue\">◄</font> گوشه ای که بکره ٔ چاه را بدان آویزند. (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> محور جمیعا. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> أصاب ثَوبَه ُ علق ؛ به جامه ٔ او چیزی چسبید که آن را شکافت . <BR><font color=\"Blue\">◄</font> نظرة من ذی علق ؛ نگاهی از شخص دوست دارنده و عاشق . (از منتهی الارب ) (از اقرب الموارد) (از ناظم الاطباء).<br></font></div>'),
(185391, 'علق', '<span class=\"hlight\">علق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) دشنام و ناسزا دادن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آزردن به زبان . <BR><font color=\"Blue\">◄</font> چریدن شتر سرهای درختان را. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مکیدن انگشت . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> چسبیدن زالو در حلق شخص (فعل آن مجهول بکار میرود). (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) بهترین هر چیزی . <BR><font color=\"Blue\">◄</font> انبان . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> خنور. (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> درختی که بدان پوست پیرایند. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> دشنام . (منتهی الارب ) (آنندراج ). <BR><font color=\"Blue\">◄</font> شکافی که از جالباسی و امثال آن در لباس پیدا میشود. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185392, 'علقات', '<span class=\"hlight\">علقات .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع اِ) بیخ و بن : استأصل اﷲ علقاتهم ؛ برکناد خدای بیخ و بن ایشان را. رجوع به عرقات شود. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185393, 'علقم', '<span class=\"hlight\">علقم .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (ع اِ) هر چیز تلخ . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> حنظل . (منتهی الارب ) (از اقرب الموارد). کبست . زهرگیاه . <BR><font color=\"Blue\">◄</font> حنظل، در صورتی که بسیار تلخ باشد. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> کُنار تلخ . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خیار دشتی، که داروئی است مسهل، و آن را قثاءالحمار نیز گویند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) آب سخت تلخ . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185394, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن رِمثة. رجوع به علقمه ٔ بلوی شود.<br></font></div>'),
(185395, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َم َ ]</font></b> (اِخ ) ابن حویرث . رجوع به علقمه ٔ غفاری شود.<br></font></div>'),
(185396, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن خالدبن حرث بن ابی اسدبن رفاعةبن ثعلبةبن هوازن بن اسلم . رجوع به علقمه ٔ اسلمی شود.<br></font></div>'),
(185397, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن ربیعةبن اعوربن أهیب بن حذافةبن جمح . رجوع به علقمه ٔ جمحی شود.<br></font></div>'),
(185398, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َق َ م َ ]</font></b> (اِخ ) نهری است از فرات . و عباس بن علی بن ابی طالب بر کنار آن شهید شد. (یادداشت مرحوم دهخدا).<br></font></div>'),
(185399, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن حوشب . رجوع به علقمه ٔ غفاری شود.<br></font></div>'),
(185400, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b>(اِخ ) ابن حکیم فراسی . رجوع به علقمه ٔ فراسی شود.<br></font></div>'),
(185401, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن حجر. صحابی است، و غالباً او را همان علقمةبن وائل بن حجر دانند. (از الاصابة ج <span class=\"hlight\" dir=\"rtl\">٥</span> قسم چهارم ص <span class=\"hlight\" dir=\"rtl\">١٧٢</span>).<br></font></div>'),
(185402, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن حاجب بن زرارةبن عدس . رجوع به علقمه ٔ تمیمی شود.<br></font></div>'),
(185403, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن جنادةبن عبداﷲبن قیس . رجوع به علقمه ٔ ازدی شود.<br></font></div>'),
(185404, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن أعور. رجوع به علقمه ٔ سلمی شود.<br></font></div>'),
(185405, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن اسلم بن مرثدبن زیدبن اعلس بن علقمةبن ذی حدن اکبر، مشهور به مطموس . رجوع به علقمه ٔ نواحه شود.<br></font></div>'),
(185406, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن فغواء (یا ابی فغواء)بن عبیدبن عمروبن مازن بن عدی بن ربیعة. رجوع به علقمه ٔ خزاعی شود.<br></font></div>'),
(185407, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) نام طایفه ایست ساکن حیره . از جمله دیرهای آنان دیر حنظلةبن عبدالمسیح بن علقمةبن مالک بن رُبّی بن نُمارةبن لَخم بوده است . (از معجم قبائل العرب ).<br></font></div>'),
(185408, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) شهری است در ساحل جزیره ٔ صقلیه (سیسیل ). (از معجم البلدان ).<br></font></div>'),
(185409, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (ع مص ) انداختن چیز تلخ در طعام و تلخ کردن آن . <BR><font color=\"Blue\">◄</font> تلخ شدن . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) تلخی . (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ) واحد علقم، یعنی یک دانه حنظل یا یک دانه کُنار تلخ . (ناظم الاطباء).<br></font></div>'),
(185410, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن یزیدبن عمروبن سلمةبن منبه بن ذهل بن عطیف مرادی . رجوع به علقمه ٔ عطیفی شود.<br></font></div>'),
(185411, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن یزید. رجوع به علقمه ٔ عقبی شود.<br></font></div>'),
(185412, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن هوذةبن شماس بن باباتمیمی . رجوع به علقمه ٔ یربوعی شود.<br></font></div>'),
(185413, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن وقاص بن محصن بن کلدةبن عبد (یا لیل )بن طریف بن عتوارةبن عامربن مالک بن لبث بن بکربن عبدمناةبن کنانة. رجوع به علقمه ٔ لیثی شود.<br></font></div>'),
(185414, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن نضر. وی در پیشروی اهل کوفه بود وقتی که در جنگ بر أحنف بن قیس خشم گرفتند. (از الاصابة ج <span class=\"hlight\" dir=\"rtl\">٤</span> قسم اول ص <span class=\"hlight\" dir=\"rtl\">٢٦٨</span>).<br></font></div>'),
(185415, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن ناجیةبن حرث بن مصطلق . رجوع به علقمه ٔ خزاعی شود.<br></font></div>'),
(185416, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ع َ ق َ م َ ]</font></b> (اِخ ) ابن مجزّزبن أعوربن جعدةبن معاذبن عتوارةبن عمربن مدلج . رجوع به علقمه ٔ مدلجی شود.<br></font></div>'),
(185417, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن مالک . نام طایفه ایست ظاهراً منسوب به علقمةبن مالک از قحطانیه ساکن صَبَر، از شهرهای خَولان در صَعدة. (از معجم قبائل العرب ).<br></font></div>'),
(185418, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن قیس بن عبداﷲبن مالک بن علقمةبن سلامان، مکنی به ابوشبل کوفی . رجوع به علقمه ٔ نخعی شود.<br></font></div>'),
(185419, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن زید. از کسانی است که پیغمبر (ص ) را درک کرده است . (از الاصابة ج <span class=\"hlight\" dir=\"rtl\">٥</span> قسم سوم ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br></font></div>'),
(185420, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن علاثةبن عوف بن أحوص بن جعفربن کلاب بن ربیعةبن عامربن صعصعة. رجوع به علقمه ٔ عامری شود.<br></font></div>'),
(185421, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ )ابن عبدةبن ناشرةبن قیس . رجوع به علقمه ٔ فحل شود.<br></font></div>'),
(185422, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن طلحةبن ابی طلحة. رجوع به علقمه ٔ عبدری شود.<br></font></div>'),
(185423, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن سهیل . رجوع به علقمه ٔ ثقفی شود.<br></font></div>'),
(185424, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن سمی . رجوع به علقمه ٔ خولانی شود.<br></font></div>'),
(185425, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن سفیان . رجوع به علقمه ٔ ثقفی شود.<br></font></div>'),
(185426, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن سعیدبن عاصی بن امیة. وی در فتوحات شام شرکت داشته است . (از الاصابة ج <span class=\"hlight\" dir=\"rtl\">٤</span> قسم اول ص <span class=\"hlight\" dir=\"rtl\">٢٦٣</span>).<br></font></div>'),
(185427, 'علقمة', '<span class=\"hlight\">علقمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ م َ ]</font></b> (اِخ ) ابن سعدبن معاذ انصاری بن سید اوس . رجوع به علقمه ٔ انصاری شود.<br></font></div>'),
(185428, 'علقمی', '<span class=\"hlight\">علقمی .</span> <font color=\"DarkGreen\"><b>[ ع َق َ ]</font></b> (اِخ ) شمس الدین محمدبن عبدالرحمان بن علی بن ابی بکر. از فقهای شافعی مذهب قاهره به شمار میرفت . جلال سیوطی استاد او بود و خود از مدرسان ازهر مصر بود. تولد او در <span class=\"hlight\" dir=\"rtl\">٨٩٧</span> و وفاتش در <span class=\"hlight\" dir=\"rtl\">٩٦٩</span> هَ . ق . اتفاق افتاده . او راست : الکوکب المنیر بشرح الجامع الصغیر، در سه جلد که در سال <span class=\"hlight\" dir=\"rtl\">٩٦٨</span> از تألیف آن فارغ شد. و ملتقی البحرین فی الجمع بین کلام الشیخین . (از الاعلام زرکلی ).<br></font></div>'),
(185429, 'علقمی', '<span class=\"hlight\">علقمی .</span> <font color=\"DarkGreen\"><b>[ ع َ ق َ ]</font></b> (اِخ ) ابوطالب مؤیدالدین محمدبن محمد. آخرین وزیر خلفای عباسی . رجوع به ابن علقمی و نیز دستورالوزراء ص <span class=\"hlight\" dir=\"rtl\">٩٨</span> شود.<br></font></div>'),
(185430, 'علقی', '<span class=\"hlight\">علقی .</span> <font color=\"DarkGreen\"><b>[ ع َ قا ]</font></b> (اِ) گیاهی است که از آن جاروب سازند. (ناظم الاطباء).<br></font></div>'),
(185431, 'علل', '<span class=\"hlight\">علل .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b>(ع مص ) عَل ّ است در همه ٔ معانی . رجوع به عل ّ شود.<br></font></div>'),
(185432, 'علل', '<span class=\"hlight\">علل .</span> <font color=\"DarkGreen\"><b>[ ع ِل َ ]</font></b> (ع اِ) ج ِ علّت . رجوع به علت شود <span class=\"hlight\">:</span> <br>آن عللهائی که در طب گفته اند<br>دور باشد از تنت ای ارجمند.<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">علل اربعه </span> ؛ عبارتست از علت صوری، علت مادی، علت فاعلی و علت غائی . رجوع به علت شود.<br>- <span class=\"hlight\">علل خارجی </span> ؛ اموری است که خارج از ذات اشیاء بوده ودر عین حال در حصول و تحقق آنها دخالت داشته باشند، مانند علت غائی و فاعلی که هر دو از علل خارجیه اند، یعنی خارج از ذات معلول میباشند. (از فرهنگ اصطلاحات فلسفی ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span>).<br>- <span class=\"hlight\">علل داخلی </span> ؛ اموری است که داخل در ذات معلول بوده و ازمقومات ماهوی آن میباشند، مانند ماده و صورت که علت مادی و صوری هستند و داخل در ذات و از مقومات اشیاءهستند. (از فرهنگ اصطلاحات فلسفی ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span>).<br>- <span class=\"hlight\">علل دریا و مکان </span> ؛کنایه از آفتاب است . (ناظم الاطباء).<br>- <span class=\"hlight\">علل عالیه، مبادی اولیه ٔ مجرده </span> . (از فرهنگ اصطلاحات فلسفی ).<br>- <span class=\"hlight\">علل ماهیت </span> ؛ اموری است که قوام ماهیت اشیاء باآنها است . در مقابل علل وجود. مقومات و ذاتیات هر شی ٔ، علل ماهوی آن شی ٔاند. (از فرهنگ اصطلاحات فلسفی ).<br>- <span class=\"hlight\">علل مُعِدّه </span>؛ اموری است که هر یک بتنهائی مؤثر در وجود معلول نیستند، و لکن موجب نزدیک شدن صدور معلول از علت مؤثره اند. بعبارت دیگر مجموع اموری که معلول را مهیای صدور از علت مؤثره مینمایند، علل مُعِدّه نامند. و آن را علل مقربه نیز نامند از آن جهت که سبب نزدیک شدن صدور معلول از علت میشوند، و معلول را به مرتبه ٔ صدور از علت مؤثره میرسانند، و یا علت مؤثره را به مرحله ای میرسانند که موجب صدور معلول از آن شود. بعضی گویند هر یک از علل معدّه علت ناقصه اند، و مجموعاً علت مؤثره . ولکن محققان فلاسفه گویند که علل معدّه اصولاً مشمول عنوان علیت نمیشوند، نه ناقص و نه تام، بلکه معداتی میباشند که سبب مهیا شدن علت برای ایجاد و صدور معلولند. (از فرهنگ اصطلاحات فلسفی ).<br>- <span class=\"hlight\">علل مقربه </span> . رجوع به علل معدّه شود.<br></font></div>'),
(185433, 'عللا', '<span class=\"hlight\">عللا.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِ صوت ) بانگ و شور و غوغا. هلالوش . هیابانگ . رجوع به علالا شود <span class=\"hlight\">:</span> <br>گر چو ما گیتی مجبور قضا و قدر است <br>پس چرا از ما برگیتی چندین عللاست ؟<br><font color=\"Red\">مسعودسعد.</font><br></font></div>'),
(185434, 'عللان', '<span class=\"hlight\">عللان .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b>(اِخ ) نام آبی است در حِسمی ̍. (از معجم البلدان ).<br></font></div>'),
(185435, 'علم', '<span class=\"hlight\">علم .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع مص ) کفیده لب گردیدن . (منتهی الارب ) (از ناظم الاطباء). شکافته شدن لب بالا، یا یکی از دو طرف آن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص ) شکافتگی در لب بالایین و یا در یکی از دو طرف آن . (از منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء) لب شکری . <BR><font color=\"Blue\">◄</font> (اِ) حد فاصل میان دو زمین . (منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> نشانی که در راه برای شناختن برپا سازند.(منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> منار. (ذیل اقرب الموارد). <BR><font color=\"Blue\">◄</font> کوه، یا کوه دراز. (منتهی الارب ) (ناظم الاطباء) (از اقرب الموارد). ج، أعلام، عِلام . (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> نشان . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> نشان لشکر. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> پرچم . (منتهی الارب ). آنچه به سر نیزه بندند. (از اقرب الموارد). رجوع به پرچم شود. <BR><font color=\"Blue\">◄</font> درفش .(منتهی الارب ). رایة. (اقرب الموارد). بیرق . این لفظ از دو کلمه ٔ عبرانی ترجمه شده است، یکی «نس » که بمعنی چوبی است که بر زیر آن مشعلی باشد، و دیگری «دجل » است که بمعنی علم یا بیرق میباشد که از قماش ترتیب یافته صورت بر آن نگارند. بعضی از علمای یهود گویند که بر علم بنی یهودا صورت شیر، بر علم بنی رأوبین صورت مرد، و بر علم بنی افرائیم صورت گاو، و بر علم دان صورت کرکس منقوش بود. (از قاموس مقدس ص <span class=\"hlight\" dir=\"rtl\">٦١٨</span>). امیر فرمود تا خلعت احمد راست کردند طبل و علم و کوس و آنچه به آن رود که سالاران را دهند. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٧٠</span>).<br>- <span class=\"hlight\">علم افکندن </span> ؛ کنایه از عاجز شدن و گریختن و شکست خوردن . (آنندراج ). و رجوع به علم انداختن شود.<br>- <span class=\"hlight\">علم انداختن </span> ؛ سپر انداختن . عاجز شدن . رو گرداندن . (ناظم الاطباء) (از آنندراج ) (از برهان ).<br>- <BR><font color=\"Blue\">◄</font> غافل شدن . (از برهان قاطع) (ناظم الاطباء).<br>- <span class=\"hlight\">علم بر بام زدن </span> ؛ فاش کردن امری را <span class=\"hlight\">:</span> <br>چون بپوشیم راز کآوردیم <br>طبل در کوچه وعلم بر بام .<br> <font color=\"Red\">اوحدی (از امثال و حکم دهخدا).</font><br>- <span class=\"hlight\">علم برپا شدن </span> ؛ فعل لازم از علم برپاکردن است، که مراد علم زدن است . (از آنندراج ).<br>- <span class=\"hlight\">علم بزرگ </span> ؛ علمی که نشانه ٔ تمام لشکریان بود <span class=\"hlight\">:</span> حجاج و طارق بن عمرو با معظم لشکر بر مروه بایستاد و علم بزرگ را آنجای بداشتند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٨٨</span>).<br>- <span class=\"hlight\">علم به خون تازه کردن </span> . رجوع به علم به خون چرب کردن شود <span class=\"hlight\">:</span> <br>علم به خون مسیحا و خضر تازه کند<br>چو از نیام کشد تیغ حسن بی باکش .<br> <font color=\"Red\">صائب (از آنندراج ).</font><br>- <span class=\"hlight\">علم چرب کردن (به خون چرب کردن )</span>؛ در هنگام صف آرائی سبقت کرده یک دوئی را از لشکر غنیم به دست آوردن، و در پای علم خود گردن زده از خون او علم چرب کردن . این را شگون ظفر دانند. (آنندراج )<span class=\"hlight\">:</span> <br>به خون خویش علم چرب کرده ایم چو شمع<br>که خود نخست ز خصمان به خود اسیر شدیم .<br> <font color=\"Red\">محمدقلی بیک سلیم (از آنندراج ).</font><br>نیست در دامن این دشت شکاری صائب <br>که علم چرب کند آه سحرگاهی ما.<br> <font color=\"Red\">صائب (از آنندراج ).</font><br>- <span class=\"hlight\">علم روز</span> ؛ صبح . (ناظم الاطباء).<br>- <BR><font color=\"Blue\">◄</font> آفتاب . (ناظم الاطباء).<br>- <span class=\"hlight\">علمهای روز</span> ؛ صبح صادق . (از برهان ).<br>- <BR><font color=\"Blue\">◄</font> صبح کاذب . (از برهان ).<br>- <BR><font color=\"Blue\">◄</font> ستاره ٔ صبح . (از برهان ).<br>- <BR><font color=\"Blue\">◄</font> آفتاب . (برهان ).<br>- <span class=\"hlight\">علم زدن </span> ؛ کنایه از نصب کردن علم است . (آنندراج ) <span class=\"hlight\">:</span> <br>علم بر فلک زن که عالم تو راست <br>به دولت درآویز کآن هم تو راست .<br> <font color=\"Red\">نظامی (از آنندراج ).</font><br>سحر چون خسرو خاور علم بر کوهساران زد <br>به دست مرحمت یارم درِ امّیدواران زد.<br> <font color=\"Red\">حافظ (از آنندراج ).</font><br>- <span class=\"hlight\">علم سیاه </span> ؛ علمی است که تا قبل از زمان مأمون در لشکر اسلام متداول بود <span class=\"hlight\">:</span> پس از آن آشکارا گردید کار رضا (ع ) و مأمون وی را ولیعهد کرد و علمهای سیاه برانداخت . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٣٧</span>).<br>- <span class=\"hlight\">علم صبح </span> ؛ روشنایی صبح صادق . (ناظم الاطباء). روشنایی صبح دوم . (از برهان قاطع) (از آنندراج ).<br>- <BR><font color=\"Blue\">◄</font> روشنایی صبح کاذب . (ناظم الاطباء). روشنایی صبح اول . (از برهان ) (از آنندراج ).<br>- <span class=\"hlight\">علم کائنات </span> ؛ کنایه از آسمان . (آنندراج ) (از ناظم الاطباء).<br>- <span class=\"hlight\">علم کاویان </span> ؛ درفش کاویان <span class=\"hlight\">:</span> <br>کوت فریدون و کجا کیقباد<br>کوت خجسته علم کاویان ؟<br> <font color=\"Red\">ناصرخسرو.</font><br>رجوع به «ماده ٔ درفش کاویان » شود.<br>- <span class=\"hlight\">علم کشیدن </span> ؛ از غلاف بیرون کشیدن . (ناظم الاطباء). کنایه از نصب کردن علم است . (آنندراج ) <span class=\"hlight\">:</span> <br>آنکه علم بر سر مغرب کشید<br>پایش ازین پایه به منصب رسید.<br> <font color=\"Red\">میرخسرو (از آنندراج ).</font><br>- <span class=\"hlight\">علم معکوس </span> ؛ رنگارنگ و صاحب رنگهای مختلف . (ناظم الاطباء).<br>- <span class=\"hlight\">علم همایون </span> ؛ درفش پادشاهی . (ناظم الاطباء).<br>- <span class=\"hlight\">میر علم </span> ؛ حاکم ناحیه ٔ کوچک . (ناظم الاطباء).<br> <BR><font color=\"Blue\">◄</font> نخل . چوب بسیار بلند، همانند درخت تبریزی متوسط که در تعزیه خوانی پیشاپیش دسته ها برند، و بر سر آن گاه شکل پنجه ای از فلز باشد، وگاه پارچه ٔ سیاه بر آن پوشانند.<br>- <span class=\"hlight\">علم باز</span> ؛مردی که علم را در تکایا بر پیشانی و زنخ و دندان نگاه میداشت .<br>- <span class=\"hlight\">علم بازی </span> ؛ جماعتی اند که در معرکه و هنگامه علم بازی کنند، و آن چنانست که علمهای گران بر دوش کشیده به زور و قوت بازو بهوا اندازند و نگذارند که بر زمین رسد. (آنندراج ) <span class=\"hlight\">:</span> <br>بر خاک عاشقان نه شگفت است شاخ گل <br>گلگل ز خون کشته علمهای تربت است .<br> <font color=\"Red\">خواجه آصفی (از آنندراج ).</font><br>- <span class=\"hlight\">علم عید</span> ؛ علمی که روز عید، علم بازان بدان بازی کنند. (آنندراج ) <span class=\"hlight\">:</span> <br>هر طرف سروقدان چون علم عیدروان <br>جای درعیدگه آن سر کو می طلبند.<br> <font color=\"Red\">کمال خجندی (از آنندراج ).</font><br>- <span class=\"hlight\">علم ماتم </span> ؛ علمی که پیشاپیش تابوت برند. (ناظم الاطباء) (از آنندراج ).<br>- <span class=\"hlight\">علم مرده </span> ؛ علمی که پیش پیش تابوت برند. رجوع به علم ماتم شود. (آنندراج ) <span class=\"hlight\">:</span> <br>گذشتن از جهان گر خسروی نیست <br>علم پس پیش پیش مردگان چیست .<br> <font color=\"Red\">محسن تأثیر (از آنندراج ).</font><br>- <span class=\"hlight\">زیر علم کسی سینه زدن </span> ؛ از او حمایت کردن . بدو تعلق خاطر و دلبستگی داشتن .<br> <BR><font color=\"Blue\">◄</font> (ص ) مشهور و معروف . (ناظم الاطباء). انگشت نما. نامی <span class=\"hlight\">:</span> <br>هم برادی عَلَمی و هم به مردی علمی <br>هم به حرّی سمری، هم به کریمی سمری .<br> <font color=\"Red\">فرخی .</font><br>خواجه بوطاهر، ای سپهر کرم <br>کرمت درجهان چو عِلم عَلَم .<br> <font color=\"Red\">مسعودسعد.</font><br>چون تو در عالم نیامد صاحبی با داد و دین <br>گشته ای از داد و دین اندر همه عالم علم .<br> <font color=\"Red\">مسعودسعد.</font><br> <BR><font color=\"Blue\">◄</font> (اِ) مهتر قوم . <BR><font color=\"Blue\">◄</font> نشان جامه و نگار و روگاه آن . (منتهی الارب ) (از اقرب الموارد) (از ناظم الاطباء). نقش و نگار <span class=\"hlight\">:</span> از وی <font color=\"DarkGreen\"><b>[ دامغان ]</font></b> دستارهای شراب خیزد با علمهای نیکو. (حدود العالم ).<br>کرد رخ آفتاب زرد قواره نهان <br>بر فلک از ماه نو شد ره سیمین علم .<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">علم آستین </span> ؛ طراز آستین . (آنندراج ) <span class=\"hlight\">:</span> <br>پیرایه ٔ گلو بود از دست دوست تیغ<br>وآن خون کزو چکد علم آستین بود.<br> <font color=\"Red\">میرخسرو (از آنندراج ).</font><br> <BR><font color=\"Blue\">◄</font> (اصطلاح اکسیریان ) زرنیخ . (مخزن الادویة). رجوع به زرنیخ شود. <BR><font color=\"Blue\">◄</font> نامی که شخص بدان معروف باشد. (از منتهی الارب ) (ناظم الاطباء) <span class=\"hlight\">:</span> <br>نیست اینها بر خدا اسم علم <br>که سیه، کافور دارد نام هم .<br> <font color=\"Red\">مولوی .</font><br> <BR><font color=\"Blue\">◄</font> (اصطلاح دستور زبان ) علم یا اسم خاص، آن است که بر فردی مخصوص و معین دلالت کند، مانند حسن، اسفندیار، تبریز... رجوع به اسم خاص شود. (از دستور زبان فارسی پنج استاد). <BR><font color=\"Blue\">◄</font> (اصطلاح صرف عربی ) اسم علم آن است که دلالت بر یک فرد از بین افراد جنس خود کند، و آن بر دو قسم است : <span class=\"hlight\" dir=\"rtl\">١</span>- علم مفرد، مانند سلیم . <span class=\"hlight\" dir=\"rtl\">٢</span>- علم مرکب، که خودبر سه قسم است : مرکب اضافی مانند «عبداﷲ»، مرکب مزجی مانند «بیت لحم »، مرکب اسنادی مانند «تأبط شرّاً».<br>و از جهت دیگر، اسم علم بر دو قسم میشود: <span class=\"hlight\" dir=\"rtl\">١</span>- کنیه، و آن اسمی است که با «أب » یا «أم » شروع شود، مانند أبویوسف و أم عامر. <span class=\"hlight\" dir=\"rtl\">٢</span>- لقب، و آن اسمی است که متضمن معنای مدح یا ذم باشد، مانند «رشید» که لقب هارون خلیفه ٔ عباسی است .<br>- <span class=\"hlight\">علم جنس </span> ؛ علمی است که بر تمام یک جنس اطلاق میشود، مانند «اسامة» برای اسد، و «ثعالة» برای روباه .<br></font></div>'),
(185436, 'علم', '<span class=\"hlight\">علم .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) چیره شدن در نبرد. معالمة.(از منتهی الارب ) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> نشان کردن . <BR><font color=\"Blue\">◄</font> شکافتن لب و امثال آن . (از منتهی الارب ) (از اقرب الموارد) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اِ) آفرینش . (منتهی الارب ) (ناظم الاطباء) (آنندراج ). <BR><font color=\"Blue\">◄</font> آنچه در احاطه ٔ آسمان است . (منتهی الارب ) (آنندراج ). عالَم . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه بدان بر چیزی راه یابند. (ناظم الاطباء).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(185437, 'علم', '<span class=\"hlight\">علم .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع مص ) دانستن . <BR><font color=\"Blue\">◄</font> یقین کردن . (از منتهی الارب ) (از اقرب الموارد) (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> دریافتن . (منتهی الارب ). ادراک . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> استوار کردن . (از منتهی الارب ). اتقان . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِمص، اِ) یقین . <BR><font color=\"Blue\">◄</font> فضل . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> معرفت دقیق و با دلیل بر کیفیات معینه و یا حضور معلوم در نزد عالم . (ناظم الاطباء). دانست . (منتهی الارب ). معرفت و هر چیز دانسته . دانش و آگاهی و معرفت و شناسایی . (ناظم الاطباء). ج، عُلوم <span class=\"hlight\">:</span> ما را از علم خویش بهره دادی و هیچ چیز دریغ نداشتی تا دانا شدیم . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٣٨</span>). بی اجری و مشاهره درس ادب و علم دارد <font color=\"DarkGreen\"><b>[ بوحنیفه ]</font></b> . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٧٧</span>). ما را صحبت افتادبا استاد بوحنیفه ٔ اسکافی و شنوده بودم فضل و ادب وعلم وی سخت بسیار. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٧٦</span>). طلب علم و ساختن توشه ٔ آخرت از مهماتست . (کلیله و دمنه ). بر مردمان لازم است که در کسب علم کوشند. (کلیله و دمنه ).<br>امثال و شواهد ذیل در کتاب امثال و حکم دهخدا جزء حکم و امثال آمده است که عیناً نقل می شود:<br>- <span class=\"hlight\">امثال </span>:<br> <span class=\"hlight\">ولیکن پا به دانش نِه درین راه </span> <br>که علم آمد فراوان عمر کوتاه .<br> <font color=\"Red\">جامی .</font><br> <span class=\"hlight\">علم ازبهر دین پروردن است نه ازبهر دنیا خوردن </span> . (سعدی ).<br> <span class=\"hlight\">علم است کیمیای بزرگیها</span> <br>شکّر کُنَدْت گر همه هپیونی <br>مردم ز علم و فضل شرف یابد<br>نه ز سیم و زرّ و از خز طارونی <br>از علم یافت نامور افلاطون <br>تا روز حشر نام فلاطونی .<br> <font color=\"Red\">ناصرخسرو.</font><br> <span class=\"hlight\">علم اگر قالبیست گر جانیست </span> <br>هرچه دانی تو به ز نادانیست .<br> <font color=\"Red\">اوحدی .</font><br> <span class=\"hlight\">علم بال است مرغ جانت را</span> <br>بر سپهر او برد روانت را.<br> <font color=\"Red\">اوحدی .</font><br> <span class=\"hlight\">علم به ارزانی و ناارزانی بباید داد، که علم خویشتن دارتر از آن است که با ناارزانیان قرار کند</span>. (عبداﷲ طاهر، از زین الاخبار).<br> <span class=\"hlight\">علم به تقلید نیست علم به تحقیق </span> <br>علم نخیزد مگر ز حجت وبرهان .<br><font color=\"Red\">حاج سیدنصراﷲ تقوی .</font><br> <span class=\"hlight\">علم بر سر تاج است و مال بر گردن غل </span> . (خواجه عبداﷲ انصاری ).<br>نظیر: علم تاج سر است و مال غل گردن .<br> <span class=\"hlight\">علم بهر کمال باید خواند</span> <br>نه به سودای مال بایدخواند.<br> <font color=\"Red\">اوحدی .</font><br> <span class=\"hlight\">علم بی بحث، و مال بی تجارت، و ملک بی سیاست را بقائی نباشد</span> . (؟).<br> <span class=\"hlight\">علم بی حلم خاک کوی بود</span> <br>علم باحلم آبروی بود.<br> <font color=\"Red\">سنائی .</font><br> <span class=\"hlight\">علم بی حلم شمعبی نور است </span> <br>هر دو با هم چو شهد زنبور است .<br> <font color=\"Red\">سنائی .</font><br>نظیر: ما جمع شی ٔ اًلی شی ٔ أفضل من علم اًلی حلم . (حدیث ).<br> <span class=\"hlight\">علم چون بر دل زند، یاری شود</span> <br>علم چون بر تن زند، باری شود.<br> <font color=\"Red\">مولوی .</font><br> <span class=\"hlight\">علم چه بْوَد فرق دانستن حقی از باطلی </span> <br>نی کتاب زرق شیطان جمله از بر داشتن .<br> <font color=\"Red\">سنائی .</font><br> <span class=\"hlight\">بندگی طاعت بود پندار نی </span> <br>علم، دانستن بود گفتار نی .<br> <font color=\"Red\">امیر حسینی سادات .</font><br> <span class=\"hlight\">علم در دست یک رمه رعنا</span> <br>همچو شمع است پیش نابینا.<br> <font color=\"Red\">سنائی .</font><br> <span class=\"hlight\">علم دگر دان و باز گربزی و فن </span> <br>چیز دگر دان مباش فتنه ٔ نادان .<br> <font color=\"Red\">حاج سیدنصراﷲ تقوی .</font><br> <span class=\"hlight\">علم دل تیره را فروغ دهد</span> <br>کُنْد زبان را چو ذوالفقار کند.<br> <font color=\"Red\">ناصرخسرو.</font><br> <span class=\"hlight\">علم را چند چیز می باید</span> <br>اگر آن بشنوی ز من شاید<br>طلبی صادق و ضمیری پاک <br>مدد کوکبی ازین افلاک <br>اوستادی شفیق و نفسی حر<br>روزگاری دراز و مالی پر<br>با کسی چون شد این معالی جمع<br>به جهان روشنی دهد چون شمع.<br> <font color=\"Red\">اوحدی .</font><br> <span class=\"hlight\">علم را چون تو خوانی از بازیش </span> <br>آلت جاه و ساز ره سازیش .<br> <font color=\"Red\">سنائی .</font><br> <span class=\"hlight\">علم را دام مال و جاه مساز</span> <br>بر ره خود ز حرص چاه مساز.<br> <font color=\"Red\">اوحدی .</font><br> <span class=\"hlight\">علم را دزد برد نتواند</span> <br>به اجل نیز مُرد نتواند<br>نه به میل زمان خراب شود<br>نه بسیل زمین در آب شود.<br> <font color=\"Red\">اوحدی .</font><br> <span class=\"hlight\">علم روی تو را به راه آرد</span> <br>با چراغت به پیشگاه آرد.<br> <font color=\"Red\">اوحدی .</font><br> <span class=\"hlight\">چون تو را دیدند صدق و عدل بوبکر و عمر</span> <br>مر تو را علم علی و حلم عثمان آمدند.<br> <font color=\"Red\">ادیب صابر.</font><br> <span class=\"hlight\">آنکه او را خدای عزوجل </span> <br>داد علم علی و عدل عمر.<br> <font color=\"Red\">مسعودسعد.</font><br> <span class=\"hlight\">علم کز بهر باغ و راغ بود</span> <br>همچو مر دزد را چراغ بود.<br> <font color=\"Red\">سنائی .</font><br><span class=\"hlight\">علم کز بهر حشمت آموزی </span> <br>حاصلش رنج دان و بدروزی .<br> <font color=\"Red\">سنائی .</font><br> <span class=\"hlight\">علم کز تو تو را بنستاند</span> <br>جهل ازآن علم به بود بسیار.<br> <font color=\"Red\">سنائی .</font><br> <span class=\"hlight\">علم کشتی کند بر آب روان </span> <br>وآنکه کشتی کند به علم توان <br>چون تو با علم آشنا گشتی <br>بگذری زآب نیز بی کشتی .<br> <font color=\"Red\">اوحدی .</font><br> <span class=\"hlight\">علم کل ّ شی ٔ خیر من جهله </span> .<br> <span class=\"hlight\">علم مرغ وحشی است </span> . (از مجموعه ٔ مختصر امثال فارسی چ هند).<br> <span class=\"hlight\">علم نور است و جهل تاریکی </span> <br>علم راهت برد به باریکی .<br> <font color=\"Red\">اوحدی .</font><br> <span class=\"hlight\">علم نیرو دهد کمالت را</span> <br>عقل اجابت کند سوءالت را.<br> <font color=\"Red\">اوحدی .</font><br><span class=\"hlight\">علم و مال و منصب و جاه و قران </span> <br>فتنه آرد در کف بدگوهران .<br> <font color=\"Red\">مولوی .</font><br> <span class=\"hlight\">سعدی بشوی لوح دل از نقش غیر دوست </span> <br>علمی که ره بحق ننماید ضلالت است .<br> <font color=\"Red\">سعدی .</font><br>- <span class=\"hlight\">اهل علم </span> ؛ عالم و دانا. (ناظم الاطباء). مرد روحانی . در تداول عامه، معمم .<br>- <span class=\"hlight\">بی علم </span> ؛ بی دانش . نادان . رجوع به علم شود <span class=\"hlight\">:</span> <br>علم دل بجای جان باشد<br>سر بی علم بدگمان باشد.<br> <font color=\"Red\">اوحدی .</font><br>- <span class=\"hlight\">طالب علم </span> ؛ محصل . کسی که تحصیل علم و دانش میکند. (ناظم الاطباء) <span class=\"hlight\">:</span> <br>کبک چون طالب علم است و درین نیست شکی <br>مسأله خواند تا بگذرد از شب سیکی .<br> <font color=\"Red\">منوچهری .</font><br>- <span class=\"hlight\">علم آموختن </span> ؛ تعلیم دادن دانش، یا دادن علم به دیگران <span class=\"hlight\">:</span> مردمان را رایگان علم آموزد <font color=\"DarkGreen\"><b>[ بوحنیفه ]</font></b> . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٢٧٧</span>).<br>- <BR><font color=\"Blue\">◄</font> فراگرفتن دانش . یاد گرفتن علم (لازم و متعدی است ).<br>چو علم آموختی از حرص آنگه ترس، کاندر شب <br>چو دزدی با چراغ آید، گزیده تر برد کالا.<br> <font color=\"Red\">سنائی .</font><br>- <span class=\"hlight\">علم احجار</span> ؛ سنگ شناسی . رجوع به سنگ شناسی شود.<br>- <span class=\"hlight\">علم اخلاق </span> ؛ دانش بد و نیک خویها که یکی از سه بخش فلسفه ٔ عملی است . و آن تدبیر انسان است نفس خود را یا یک تن خاص را. رجوع به اخلاق شود.<br>- <span class=\"hlight\">علم ادب </span> ؛ علمی که بدان خود را از خلل در کلام نگاه دارند. و آن بر چند فن است . رجوع به ادب شود.<br>- <span class=\"hlight\">علم ادیان </span>؛ دانش شناختن دین ها. دانستن احکام دین ها. رجوع به ادیان و دین شود <span class=\"hlight\">:</span> <br>پیغمبر گفت علم علمان <br>علم الابدان و علم الادیان .<br> <font color=\"Red\">نظامی .</font><br>- <span class=\"hlight\">علم استخراج </span> ؛ علم بیان احکام بواسطه ٔ قواعد نجومی یا رملی . (ناظم الاطباء). رجوع به استخراج شود.<br>- <span class=\"hlight\">علم اندازه </span> ؛ علم هندسه . (ناظم الاطباء).<br>- <span class=\"hlight\">علم انشاء</span> ؛ علمی که بدان مطالب را نیکو و فصیح نویسند. (ناظم الاطباء). رجوع به انشاء شود.<br>- <span class=\"hlight\">علم باکار</span> . رجوع به ترکیب علم و عمل شود <span class=\"hlight\">:</span> <br>علم باکار سودمند بود<br>علم بی کار پای بند بود.<br> <font color=\"Red\">سنایی .</font><br>- <span class=\"hlight\">علم بدیع</span> ؛ علم آرایش سخن . علمی است که محسنات سخن بلیغ بدان وسیله شناخته میشود. (از کتاب بدیع وقافیه و عروض ). رجوع به بدیع شود.<br>- <span class=\"hlight\">علم بلاغت </span> ؛ دانش رسائی سخن و فصاحت در کلام و چیره زبانی، و آن شامل معانی و بیان و بدیع و عروض و قافیه است . (از کتاب بدیع و قافیه و عروض ). رجوع به بلاغت شود.<br>- <span class=\"hlight\">علم بیان </span> ؛ قواعد و قوانینی که بوسیله ٔ آن آوردن یک معنی به راههای گوناگون شناخته شود. وبحث از اقسام تشبیه و مجاز و استعاره و کنایه و مانند آنها از وظایف این علم است . (از کتاب بدیع و قافیه و عروض ). رجوع به بیان شود.<br>- <span class=\"hlight\">علم تشریح </span> ؛ علمی که در آن از حقیقت انتساج آلات بحث میکنند. (ناظم الاطباء). کالبدشکافی .<br>- <span class=\"hlight\">علم تصریف </span> ؛ علم به اشتقاق کلمات . (ناظم الاطباء).<br>- <span class=\"hlight\">علم تصوف </span> ؛ از علوم شرعی جدید در ملت اسلام است . و اصل آن، روی آوردن به عبادت و توجه بسوی خدای تعالی و اعراض از زخارف و زیورهای دنیوی و پرهیز از چیزهایی است که عامه ٔ مردم به آنها روی می آورند، مانند لذت و مال و جاه، و دوری از خلق و پناه بردن به کنج خلوت برای عبادت است . (ازترجمه ٔ مقدمه ٔ ابن خلدون ). رجوع به تصوف شود.<br>- <span class=\"hlight\">علم تعطیل </span> ؛ علمی که اصحاب آن منکر صفات باری باشند، و آنان را معطلون گویند <span class=\"hlight\">:</span> <br>علم تعطیل مشنوید از غیر<br>سرّ توحید را خلل منهید.<br> <font color=\"Red\">خاقانی .</font><br>- <span class=\"hlight\">علم تعلیمی </span> ؛ عبارت از علم ریاضی است . (از کشاف اصطلاحات الفنون ).<br>- <span class=\"hlight\">علم چل صباح </span> . رجوع به علم چهل صباح شود. (از ناظم الاطباء).<br>- <span class=\"hlight\">علم چهل صباح </span> ؛ کنایه از علم چهل روزاست که تخمیر خاک آدم علیه السلام میشد. (برهان قاطع)(آنندراج ).<br>- <span class=\"hlight\">علم حدیث </span> ؛ دانش آگاهی به گفته های رسول (ص ) و حکایت گفتار و کردار وی باشد. رجوع به حدیث شود.<br>- <span class=\"hlight\">علم حرکات </span> ؛ جنبش شناسی . رجوع به جنبش و حرکات شود.<br>- <span class=\"hlight\">علم داشتن </span> ؛ داشتن دانش . دانا بودن . عالم بودن . رجوع به علم شود <span class=\"hlight\">:</span> <br>علم داری به حلم باش چوکوه <br>مشو از نائبات چرخ ستوه .<br> <font color=\"Red\">سنایی (از امثال و حکم دهخدا).</font><br>علم داری ز کس مدار دریغ<br>بر دل تشنگان ببار چو میغ.<br> <font color=\"Red\">اوحدی (از امثال و حکم دهخدا).</font><br>- <span class=\"hlight\">علم در سینه بودن </span> ؛ کنایه از در یاد داشتن علم . از بر دانستن دانش : علم در سینه باید نه در سفینه . (از مجموعه ٔ امثال فارسی چ هند).<br>- <span class=\"hlight\">علم رسمی </span> ؛ علوم متداول . علوم کسبی . در برابر علوم عرفانی <span class=\"hlight\">:</span> <br>علم رسمی سربسر قیل است و قال <br>نه از او کیفیتی حاصل نه حال .<br> <font color=\"Red\">شیخ بهائی .</font><br>- <span class=\"hlight\">علم ریاضی </span> ؛ علمی است که از اموری بحث میکندکه فقط در وجود خارجی محتاج به ماده باشند، چنانچه مقدار اعداد خاص که موجود در مادیات است . و اصول این علم چهار است : علم هندسه و علم عدد و علم نجوم و علم موسیقی . و فروع آن چون علم مناظر و مرایا و علم جبر و مقابله و علم جراثقال . (از غیاث اللغات ) (از آنندراج ). علم اندازه و ترتیب . علم خواص کمیت بطور مطلق . رجوع به ریاضی شود.<br>- <span class=\"hlight\">علم زمین </span> ؛ علم جغرافی . (ناظم الاطباء). رجوع به جغرافی شود.<br>- <span class=\"hlight\">علم ستاره </span> ؛ علم نجوم . (ناظم الاطباء). رجوع به نجوم و ستاره شناسی شود.<br>- <span class=\"hlight\">علم سِحر (ساحری )</span> ؛ افسونگری و جادویی . (ناظم الاطباء). آگاهی به چگونگی استعدادهایی که نفوس بشری بوسیله ٔ آنها بر تأثیر کردن در عالم عناصر توانا میشوند، خواه مستقیم و بیواسطه باشد و خواه بوسیله ٔ یاریگری از امور آسمانی . نوع اول را ساحری گویند و نوع دوم را طلسمات . (از ترجمه ٔ مقدمه ٔ ابن خلدون ج <span class=\"hlight\" dir=\"rtl\">٢</span>). رجوع به سحر و ساحری و جادویی شود.<br>- <span class=\"hlight\">علم سماء و عالَم </span> ؛ علمی است از انواع علوم طبیعی . (کشاف اصطلاحات الفنون ). رجوع به طبیعی شود.<br>- <span class=\"hlight\">علم شریعت </span> ؛ دانش به احکام خدا و دستورهای دینی و شرعی . رجوع به شریعت شود.<br>- <span class=\"hlight\">علم عروض </span> ؛ میزان سخن منظوم، یا فنی است که از وزن اشعار بحث میکند. (از کتاب بدیع و قافیه و عروض ). رجوع به عَروض شود.<br>- <span class=\"hlight\">علم فقه </span> ؛ علمی است که از احکام فروع دین اسلام گفتگو میکند، و آن را سه رکن است : کتاب و سنت و اجماع . ابن خلدون در مقدمه ٔ خود راجع به علم فقه گوید که آن شناسایی احکام خدای تعالی درباره ٔ افعال کسانی است که مکلف میباشند، بدینسان که دانسته شود کدام فعل آنان واجب یا حرام و کدام مستحب یا مکروه یامباح است . و این احکام را از کتاب و سنت و ادله ای که شارع برای شناختن احکام مقرر داشته فرامیگیرند، بنابراین هرگاه احکام از ادله ٔ مزبور استنباط شود چنین احکامی را فقه گویند. و رجوع به فقه شود.<br>- <span class=\"hlight\">علم قافیه </span> ؛ شناختن احوال انواع قوافی است .(از کتاب بدیع و قافیه و عروض ). رجوع به قافیه شود.<br>- <span class=\"hlight\">علم کلام </span> ؛ علمی است که در آن مقدمات نقلی را بدلایل عقلی ثابت کنند. و صاحبان این علم را متکلمین گویند. (از غیاث اللغات ) (از آنندراج ). ابن خلدون در مقدمه ٔ خود راجع به این علم گوید که آن دانشی است متضمن اثبات عقاید ایمانی بوسیله ٔ ادله ٔ عقلی و رد بر بدعت گذارانی که از اعتقادات مذاهب سلف و اهل سنت منحرف شده اند. و رمز این عقاید ایمانی، توحید است . و رجوع به کلام شود.<br>- <span class=\"hlight\">علم کیمیا</span> ؛ دانشی است که در آن از ماده ای گفتگو میشود که بوسیله ٔ آن زر و سیم به روش مصنوعی به وجود می آید، و عملی که به این نتیجه منتهی میگردد تشریح میشود. (از ترجمه ٔ مقدمه ٔ ابن خلدون ج <span class=\"hlight\" dir=\"rtl\">٢</span>). رجوع به کیمیا شود.<br>- <span class=\"hlight\">علم لغت </span> ؛ عبارت از بیان وضع کلمات و مسائل لغوی است . (از ترجمه ٔ مقدمه ٔ ابن خلدون ). رجوع به لغت شود.<br>- <span class=\"hlight\">علم معانی </span> ؛علم به اصول و قواعدی است که به یاری آنها کیفیت مطابقه ٔ کلام با مقتضای حال و مقام شناخته شود. و موضوعاتی از قبیل اسناد و قصر و انشاء و وصل و فصل و ایجاز و اطناب و مساوات در آن مورد بحث قرار میگیرد. (ازکتاب بدیع و قافیه و عروض ). رجوع به معانی شود.<br>- <span class=\"hlight\">علم منطق </span> ؛ قوانینی است که بدان میتوان در حدودی که تعریفات معرف ماهیت ها هستند، ودر حجت ها که تصدیق ها را افاده میکنند، درست و صحیح را از غلط و ناصحیح بازشناخت . (از ترجمه ٔ مقدمه ٔ ابن خلدون ). رجوع به منطق شود.<br>- <span class=\"hlight\">علم نحو</span> ؛ دانشی است که بوسیله ٔ آن اصول مقاصد از راه دلالت الفاظ آشکار میگردد، و فاعل از مفعول و مبتدا از خبر بازشناخته میشود. و اگر این دانش نمی بود اصل افاده ٔ سخن، نامعلوم میماند. و این علم مهمترین رکن از ارکان چهارگانه ٔ زبان عرب (لغت، نحو، بیان و ادب ) است . (از ترجمه ٔ مقدمه ٔ ابن خلدون ). رجوع به نحو شود.<br>- <span class=\"hlight\">علم و عمل، علم باکار و علم بی کار</span> ؛ دانش و به کار بردن آن، که بیشتر در علوم دینی بکار رود. و در آموزش و پرورش جدید نیز علم و عمل بسیار مورد بحث است <span class=\"hlight\">:</span> <br>علم را جز که عمل بند ندیده ست حکیم <br>علم را کس نتواند که ببندد به طناب .<br> <font color=\"Red\">ناصرخسرو.</font><br>ظاهر من به علم و عمل آراسته گردد. (کلیله و دمنه ).<br>علم باکار سودمند بود<br>علم بی کار پای بند بود<br> <font color=\"Red\">سنایی .</font><br>علم چندان که بیشتر خوانی <br>چون عمل در تو نیست، نادانی .<br> <font color=\"Red\">سعدی .</font><br>بار درخت علم نباشد مگر عمل <br>با علم اگرعمل نکنی، شاخ بی بری .<br> <font color=\"Red\">سعدی .</font><br>علم چو سوزن، عمل چو رشته، نیابد<br>چاک رفو، تا جداست رشته ز سوزن .<br> <font color=\"Red\">حاج سیدنصراﷲ تقوی .</font><br>علم چون حاصل کنی آنگه عمل خالص شود.<br> <font color=\"Red\">؟</font><br>- <span class=\"hlight\">علم هیئت </span> ؛ دانشی که درباره ٔ ستارگان ثابت و سیاره بحث میکند. و از کیفیات این حرکات، بر اشکال واوضاع مخصوص افلاک استدلال میشود. (از ترجمه ٔ مقدمه ٔ ابن خلدون ). رجوع به هیئت شود.<br>- <span class=\"hlight\">علم یقین </span> ؛ دانستن چیزی به کمال یقین که هیچ شبهه وشکی در آن نبود. (ناظم الاطباء). رجوع به یقین شود. و نیز از حیث تصوف رجوع به «علم » در تصوف شود.<br> <BR><font color=\"Blue\">◄</font> هنر. <BR><font color=\"Blue\">◄</font> صنعت و پیشه . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (اصطلاح تصوف ) علم نوری است مقتبس از مشکاة نبوت در دل بنده ٔ مؤمن که بواسطه ٔ آن به خدای راه یابد. و فرق آن با عقل آن است که عقل فطری است، ولی علم خاص مؤمن است . علمای اصول میان علم و معرفت فرقی نمیگذارند. اما مشایخ و متصوفه گویند علمی که حکایت از احوال کند و مقرون با حال باشد، معرفت است . وآنچه را از معنی مجرد باشد و از معاملت با خدا خالی، علم خوانند. ابوعلی ثقفی در تعریف علم گوید: «العلم حیاة القلب من الجهل، و نور العین من الظلمة». در شرح کلمات باباطاهر است که «العلم ُ دلیل »، که دلیل معرفت و حکمت است . و در خبر است که علم عبارتست از «آیة محکمة، و سنة قائمة، و فریضة عادلة».<br>علم را ازنظری به سه قسمت کرده اند: <span class=\"hlight\" dir=\"rtl\">١</span>- علم توحید. <span class=\"hlight\" dir=\"rtl\">٢</span>- علم معرفت خدای متعال، از ایجاد و اعدام و تقرب و اِبعاد و احیا و اماته و نشر و حشر و ثواب و عقاب و غیره . <span class=\"hlight\" dir=\"rtl\">٣</span>- علم احکام شریعت، از اوامر و نواهی . و هر یک ازین مسالک سه گانه را سالکی است جداگانه، سالک مسالک اول را«عالم ربانی »، و سالک مسالک دوم را «عالم اخروی »، وسالک مسالک سوم را «عالم دنیوی » دانند.<br>و باز علم رااز نظر دیگر به سه قسمت کرده اند: <span class=\"hlight\" dir=\"rtl\">١</span>- علم طبیعی . <span class=\"hlight\" dir=\"rtl\">٢</span>- علم ریاضی . <span class=\"hlight\" dir=\"rtl\">٣</span>- علم الهی . بلخی گوید «العلوم ُ ثلاثة: علم من اﷲ، و علم مع اﷲ، و علم باﷲ». در شرح منازل آمده است که علم را سه درجه است : <span class=\"hlight\" dir=\"rtl\">١</span>- علم جلی، که به عیان واقع شود. <span class=\"hlight\" dir=\"rtl\">٢</span>- علم خفی، که علم اسرار است، و از علوم الهی و مواهب ربانی است . <span class=\"hlight\" dir=\"rtl\">٣</span>- علم لدنی .<br>در شرح رساله ٔ قشیریه گوید علم بر دو قسم است : یکی علم کسبی، که بواسطه ٔ تعلم حاصل میشود، و دیگری علم ذوقی، که نتیجه ٔ عمل است بطریق اشراق انوار الهیه که علوم رحمانیه بر آنها مترتب است . (از فرهنگ مصطلحات عرفا، از مصباح الهدایة ص <span class=\"hlight\" dir=\"rtl\">٣٤</span> و کشف المحجوب ص <span class=\"hlight\" dir=\"rtl\">١٩</span> و <span class=\"hlight\" dir=\"rtl\">٤٩٨</span> و الهدایة الی فرائض القلوب ص <span class=\"hlight\" dir=\"rtl\">٤</span> و شرح کلمات باباطاهر ص <span class=\"hlight\" dir=\"rtl\">٩</span> و شرح منازل ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span>).<br>- <span class=\"hlight\">علم آخرت </span> ؛ علمی است که به فساد بدن فاسد نشود، و آن علم به تأمین سعادت اخروی است . (فرهنگ مصطلحات عرفا، از اکسیر العارفین ص <span class=\"hlight\" dir=\"rtl\">٢٨٢</span>).<br>- <span class=\"hlight\">علم اخلاص </span> ؛ اخراج خلق است از معامله ٔ با خدا، یعنی طاعات خود را فقط برای خدا انجام دهد. رجوع به اخلاص شود.<br>- <span class=\"hlight\">علم اخلاق </span> ؛ عبارت از علم سلوک است، و از انواع حکمت عملی است، که آن را تهذیب اخلاق نیز گویند، و حکمت خلقیه هم گفته میشود. (از فرهنگ مصطلحات عرفا، از کشاف ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٨</span>).<br>- <span class=\"hlight\">علم باﷲ</span>؛ همان علم معرفت است، که همه ٔ اولیأاﷲ او را بدو دانسته اند و تا تعریف و تعرف وی نبود ایشان وی را ندانستند، (از فرهنگ مصطلحات عرفا).<br>- <span class=\"hlight\">علم حال </span> ؛ از جمله علوم خاصه ٔ متصوفه است، و آن عبارتست از دوام ملاحظه ٔ دل و مطالعه ٔ سرّ صورت آن حال که میان بنده و خداوند وجود دارد، و وقوف بر کمیت و کیفیت آن در جمیع احوال و اوقات، تا بحسب هر وقت به مراعات حقوق و محافظت آداب آن قیام نماید. (از فرهنگ مصطلحات عرفا، از مصباح الهدایة ص <span class=\"hlight\" dir=\"rtl\">٤٦</span>).<br>- <span class=\"hlight\">علم حقایق </span> ؛ عبارت از علم به حق است، از جهت ارتباط آن به خلق و انشاء عالم از او، بحسب طاقت بشری . و مبادی آن امهات حقایق است که لازمه ٔ وجود حق است . (از فرهنگ مصطلحات عرفا، از مصباح الانس ص <span class=\"hlight\" dir=\"rtl\">١٣</span>).<br>- <span class=\"hlight\">علم خواطر</span> ؛ حصول معنی خاص است در دل که با سرعت زایل شود و خاطر دیگری جایگزین آن گردد. ابوالقاسم قشیری گوید: خواطر خطابی است که بر ضمایر وارد میشود. و گاه به القاء ملک است و گاه به القاء شیطان که احادیث نفس است . و زمانی که از قبل و القاء ملک باشد، الهام است . و موقعی که از قبل نفس باشد، هواجس است . و هرگاه از قبل و به القاء شیطان باشد، وسواس است . و هرگاه از قبل و القای حق باشد، خاطر حق است . و هرگاه از قبل شیطان باشد داعی بر معصیت است . و اگر از قبل نفس باشد داعی بر پیروی از شهوت است . (از فرهنگ مصطلحات عرفا، از رساله ٔ قشیری ص <span class=\"hlight\" dir=\"rtl\">٤٢</span> و تاریخ تصوف ص <span class=\"hlight\" dir=\"rtl\">٦٤٥</span>).<br>- <span class=\"hlight\">علم دراست </span> ؛ علمی است که تا اول آن را نخواند، نداند و عمل کردن نتواند. و این علم مقدمه ٔ عمل است، و علم وراثت نتیجه ٔ آن . (از فرهنگ مصطلحات عرفا، ازمصباح الهدایة ص <span class=\"hlight\" dir=\"rtl\">٤٢</span>).<br>- <span class=\"hlight\">علم سعت </span> ؛ هرگاه اخلاق نفس مبدل شد، و دیو طبیعت مسلمان گشت، و بجای متابعت هوی در مطاوعت خدا پدید آمد، بعضی از حظوظ او حقوق گردد و او رااز مضیق ضرورت به فضای سعت راه دهد. متصوفه این مقام را مقام سعت خوانند. و در این مقام نکاح و مشارب ومآکل جایز شود، و این مقام را علم سعت خوانند. (از فرهنگ مصطلحات عرفا، از مصباح الهدایة ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>).<br>- <span class=\"hlight\">علم ضار</span> ؛ علمی است که ازآن زیان خیزد. و علامت آن کبر و تفاخر و غرور و طلب دنیاست . (از فرهنگ مصطلحات عرفا، از مصباح الهدایة ص <span class=\"hlight\" dir=\"rtl\">٣٧</span>).<br>- <span class=\"hlight\">علم ضرورت </span> ؛ معنای ضرورت، مالابد است، یعنی هرچه آدمی را از آن چاره نیست، ضرورت است . و علم ضرورت عبارت از ادراک حد مالابد نفس است در حرکات و سکنات و اقوال و افعال . و مالابد آن است که نفس را نتوان از آن منع کرد، ومنع آن موجب خلل در عبادات شود. و آنچه از ضرورت بگذرد حظ نفس است . (از فرهنگ مصطلحات عرفا، از مصباح الهدایة ص <span class=\"hlight\" dir=\"rtl\">٧١٠</span>).<br>- <span class=\"hlight\">علم قیام </span> ؛ مراد آن است که بنده در تمام حرکات و سکنات ظاهر و باطن خود، حق تعالی را بر خود قائم و مطلع بیند. و در تمام احوال و اقوال و افعال او را رقیب خود داند. (از فرهنگ مصطلحات عرفا، از مصباح الهدایة ص <span class=\"hlight\" dir=\"rtl\">٤٥</span>).<br>- <span class=\"hlight\">علم لدنی </span> ؛ علمی است که بنده، بدون واسطه ٔ ملک و یا پیغمبر، بحکم «و آتیناه من لدنّا علماً» از خداوند آموزد. و آن برای اهل قرب، بوسیله ٔ تعلیم الهی و تفهیم ربانی معلوم و مفهوم شود، نه به دلایل عقلی و شواهد نقلی . فرق علم لدنی با علم یقین آن است که علم یقین ادراک نور ذات و صفات الهی است . و علم لدنی ادراک معانی و کلمات از حق است بی واسطه ٔ بشر، و آن سه قسم است، وحی و الهام و فراست . (از فرهنگ مصطلحات عرفا، از مصباح الهدایة ص <span class=\"hlight\" dir=\"rtl\">٧٦</span> و کشاف ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٦٦</span>).<br>- <span class=\"hlight\">علم معاﷲ</span> ؛ عبارت از علم مقامات طریق حق و بیان درجات اولیاء است . (از فرهنگ مصطلحات عرفا).<br>- <span class=\"hlight\">علم من اﷲ</span> ؛ علم شریعت است .<br>- <span class=\"hlight\">علم نافع</span> ؛ در مقابل علم ضار است . و علامت آن این است که در نفس، تقوی وتواضع و نیستی زیادت کند. (از فرهنگ مصطلحات عرفا، از مصباح الهدایة ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>).<br>- <span class=\"hlight\">علم وراثت </span> ؛ درمقابل علم دراست است، و تا به مقتضای علم دراست عمل نشود، علم وراثت حاصل نگردد. زیرا «مَن عمل بما علم، ورثه اﷲ علم ما لایعلم ». علم دراست مقدمه ٔ عمل است و علم وراثت نتیجه ٔ آن . (از فرهنگ مصطلحات عرفا، از مصباح الهدایة ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>).<br>- <span class=\"hlight\">علم یقین </span> ؛ عبارتست از ظهور نور حقیقت در حالت کشف استتار بشریت، بشهادت وجد و ذوق نه به دلالت عقل و نقل . و مادام که از ورای حجاب نماید آن را نور ایمان خوانند، و چون از حجاب مکشوف گردد آن را نور یقین خوانند. ابوالقاسم قشیری درباره ٔ آن گوید: یقین عبارت از علمی است که صاحب آن را در آن شکی نباشد. و علم یقین عبارت از یقین است . و عین الیقین، نفس یقین است . و علم الیقین علمی است که به شرط برهان بود، و عین الیقین بحکم بیان، و حق الیقین بنعت العیان . و لذا علم الیقین برای ارباب عقول است، و عین الیقین برای اصحاب معارف . کاشانی گوید: علم الیقین مثل آنکه شخص از مشاهده ٔ شعاع و ادراک حرارت، در وجود آفتاب یقین کند. و عین الیقین آن است که به مشاهده ٔ جرم آفتاب، در وجود آن یقین کند. و حق الیقین آنست که به تلاشی و اضمحلال نور بصر در نور آفتاب، به وجود آن یقین کند. بنابراین به عقیده ٔ متصوفه، دانستن معنوی بر سه گونه است : علم الیقین و عین الیقین و حق الیقین . در حالت اول شخص به استدلال عقلی معلوم را دریابد. و در حالت دوم یقین و معلوم را مشاهده کند. و در حالت سوم به حقیقت برسد. بعضی گویند مراد صوفیان از علم الیقین علم معاملات دنیا است، و از عین الیقین، حال نزع و وقت بیرون رفتن از دنیا است، و از حق الیقین علم به کشف رؤیت در بهشت است . (از فرهنگ مصطلحات عرفا، از کشف المحجوب ص <span class=\"hlight\" dir=\"rtl\">٤٩٧</span> و مقدمه ٔ گلشن ص <span class=\"hlight\" dir=\"rtl\">١٠٦</span> و مصباح الهدایة ص <span class=\"hlight\" dir=\"rtl\">٥٢</span> و رساله ٔ قشیریة ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>). و رجوع به ترکیب علم لدنی شود.<br> <BR><font color=\"Blue\">◄</font> (اصطلاح فلسفه ) بمعنی دانش است و گاه اطلاق به آنچه مبداء انکشاف معلوم است، میشود.<br>مسأله ٔ علم و معرفت هم از نظر ماهوی و هم از لحاظ وجودی و چگونگی حصول آن از قدیمترین ازمنه ٔ تاریخ مورد توجه فلاسفه بوده است . و از لحاظ ارزش و حدودآن نیز مورد توجه قرار گرفته و آن را با دقت خاصی بررسی کرده اند. سقراط تنها راه معارف را علم دانسته وبرای آن ارزشی نامحدود قائل بود. و حقیقت علم را مدرکات عقلانی پنداشته، و کلیه ٔ اعمال نیک را مبتنی بر علم میدانست . افلاطون نیز مانند استاد خود سقراط، حصول علم مطلق را ممکن دانسته و علم حقیقی را عبارت از علم به مثل و حقایق اشیاء میدانست . ارسطو باآنکه توجهی به ماده داشته است، معذلک عقل را اصیل و مُدْرَکات آن را دارای ارزش بی پایان میدانسته است . و عقل را تنها راه و منشاء مدرکات و علوم درست میدانست . فلوطین نیز پیرو مذهب اصالت عقل بوده و مدرکات عقلی را اصل میدانسته است . وی گوید همانطور که ماده و مادیات پرتوی از عوالم روحانی و معنوی است، علمی که از راه حواس حاصل میشود علم حقیقی نبوده، و تنها علم حقیقی مخصوص به مدرکات عقل است که بر اثر اتصال آن با عقل فعال، حقایق عالم را دریابد. سوفسطائیان برای علم ارزشی قائل نبوده و آن را نسبی میدانستند، و نتیجه ٔ حواس ظاهری میپنداشتند. شکاکان باآنکه از جهتی با سوفسطائیان وجه مشترک دارند و حسی مذهب اند، لکن برخلاف سوفسطائیان که منکر حصول علم مطلق بودند نه علم نسبی، اینان بطور مطلق منکر حصول علم اند، و اصولاً حصول علم را ناممکن میدانند. ملاصدرا گوید اولین کسی که درباب علم قائل به اتحاد عالم و معلوم است، فرفوریوس میباشدکه درباره ٔ علم حق به اشیاء نظر به اشکالاتی که واردشده است، قائل به اتحاد عالم و معلوم گردیده است . درباره ٔ اینکه آیا علم قابل تعریف و شناسائی هست یا نه، و اینکه از امور بدیهی است یا از امور نظری و اکتسابی، میان فلاسفه اختلاف نظر هست .<br>غزالی علم را از امور اکتسابی و نظری میداند و برای آن دو تعریف کرده است . امام رازی علم را از امور بدیهی داند، زیرا آنچه غیر علم است به علم شناخته میشود. و بعقیده ٔ وی اگر بخواهیم علم را تعریف کنیم دور محال لازم می آید. وی گوید هر کس به ضرورت و وجدان به وجود خود عالم است، و علم هر کس به وجود خود علم خاص بدیهی است، و بداهت خاص مستلزم بداهت عام است . اما کسانی که علم را قابل تعریف میدانند، برای آن تعاریف مختلف کرده اند.<br>متکلمان علم را از صفتی میدانند که موجب تمییز اشیاء از یکدیگر میشود، و بعقیده ٔ آنان علم واجب الوجود عبارت از صفتی ازلی است که تعلق آن به امور، موجب انکشاف میشود، و بعبارت دیگر موجب کشف حقایق است و بلکه عین اشیاء است . اما در نزد حکمای مشاء علم شامل شک و وهم و یقین میشود. آنان گویند که علم عبارت از ادراک مطلق یا حصول صور اشیاء نزد عقل است، و آن اعم است از صور یقینی یا وهمی و شکی، در حالی که علم در نظر متکلمان فقط شامل یقینیات است .<br>برخی از حکما را عقیده بر آن است که علم عبارت از صور حاصله از اشیاء نزد عقل است، چه آنکه نفس معلوم باشد که علم حضوری است، و یا بواسطه ٔ معلوم باشد که علم حصولی است، خواه یقینی باشد یا وهمی و شکی و خواه علم به کنه باشد یا به وجه .<br>میر سیدشریف آرد که علم در لغت بمعنای دانستن است و بر دو قسم میباشد: علم قدیم و علم حادث . علم قدیم همان علم قائم به ذات است و شباهتی به علوم حادث ندارد و خاص ذات باری تعالی است . علم حادث یا محدث هم یابدیهی است یا اکتسابی و نظری .<br>ارسطو بحث از علم را مقدم برسایر مباحث قرار داده و چنین آغاز کرده است که علم انسان از چه راه و به چه نحو حاصل میگردد. (از فرهنگ لغات و اصطلاحات فلسفی ص <span class=\"hlight\" dir=\"rtl\">٢٠٥</span> و <span class=\"hlight\" dir=\"rtl\">٢١٢</span>، از دستور العلماءج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٩</span> و <span class=\"hlight\" dir=\"rtl\">٣٤٥</span> و اسفار ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٣</span> و تعریفات سیدشریف ص <span class=\"hlight\" dir=\"rtl\">١٠٤</span>). و نیز رجوع به ترجمه ٔ مقدمه ٔ ابن خلدون ج <span class=\"hlight\" dir=\"rtl\">٢</span> شود.<br>- <span class=\"hlight\">علم اجمالی </span> ؛ علم به اشیاء را در مقام اجمال، علم اجمالی مینامند. قطب الدین گوید علم یا تفصیلی است یا اجمالی . علم تفصیلی آنست که اشیاء را بداند، متمایز در عقل و منفصل بعضی از بعضی . و اما اجمالی مانند آنست که کسی مسأله ای را میدانست و بعد از آن غافل شد. و آنگاه که او را درباره ٔ آن مسأله سؤال کنند، جواب در ذهن وی حاضر میشود. و این جواب به قوه ٔ محض نیست زیرا نزد وی حالتی بسیط وجود دارد که مبداء تفاصیل آن معلومات است . پس آن علم از نظری به فعل باشد و از وجهی به قوت . فلاسفه درباب علم حق تعالی گویند چون علم خدای متعال به ذات خود، عین وجود نظام جملی جهان است، از این جهت علم خدا به ذات خود، علم به کلیات بوده، و بواسطه ٔ کلیات علم به جزئیات موجودات یعنی موجودات جزئی هم هست . زیرا ذات حق علت العلل تمام کائنات است، و بالنتیجه از آن جهت که مستقیماً عالم به ذات خود میباشد، علم او نسبت به موجودات اجمالی است . و در عین حال علم اوست که سبب تکوین تمام موجودات جهان است . پس علم تفصیلی بمعنای کون و وجود موجودات هم هست . و همین است معنای گفتار فلاسفه که میگویند علم خدا به اشیاء، علم اجمالی است در عین کشف تفصیلی . اشراقیان گویند که علم حق به اشیاء به نحو اضافه ٔ اشراقی است . (از فرهنگ لغات و اصطلاحات فلسفی، از اسفار ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span> و <span class=\"hlight\" dir=\"rtl\">٤٦</span> و <span class=\"hlight\" dir=\"rtl\">٥٢</span> و درةالتاج بخش <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٨٧</span> و شرح قیصری بر فصوص ص <span class=\"hlight\" dir=\"rtl\">١٥</span>).<br>- <span class=\"hlight\">علم أدنی ̍</span> ؛ علمی است که در آن بحث از اموری میشود که هم در وجود خارجی و هم در وجود ذهنی محتاج به ماده اند. (فرهنگ لغات و اصطلاحات فلسفی ).<br>- <span class=\"hlight\">علم الهی </span>؛ علمی است که در آن بحث از احوال و صفات و آثار موجوداتی میشود که در وجود احتیاجی به ماده نداشته باشند. و آن را علم اعلی و فلسفه ٔ اولی و علم کلی هم مینامند. و میتوان گفت که موضوع علم الهی بمعنای اعم، موجود مطلق و مطلق الوجود است . و موضوع علم الهی بمعنای اخص، اموری است که در وجود احتیاجی به ماده نداشته باشند. مانند بحث از ذات و صفات و اسماء حق تعالی . (از فرهنگ لغات و اصطلاحات فلسفی، از اسفار ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٨</span>).<br>- <span class=\"hlight\">علم انفعالی </span> ؛ علمی است که مستفاد از خارج باشد. رجوع به علم فعلی شود. (ازفرهنگ لغات و اصطلاحات فلسفی ).<br>- <span class=\"hlight\">علم أوسط</span> ؛ علمی است که از اموری بحث میکند که در وجود خارج احتیاج به ماده دارند، و در وجود عقلی احتیاجی به ماده ندارند، و آن بحث از ریاضیات است . (از فرهنگ لغات و اصطلاحات فلسفی، از شفا ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٣</span>).<br>- <span class=\"hlight\">علم بالذات </span> ؛ علم به موجودات خارجی عبارتست از حصول و مثول صور آنها نزد عقل . و علم به آن صور، علم بالذات است .<br>درباب علم حق به اشیاء، شیخ الرئیس گوید که علم او بالذات است، یعنی به حضور ذات خود نزد خود اوست . پس علم و عالم ومعلوم یکی هستند در عین وعدت و بساطت . اما در مورد علم مفارقات و مجردات اختلافی نیست که نحوه ٔ علم آنهابه ذات خود، نحوه ٔ اتحاد است . یعنی عاقل و معقول، وعالم و معلوم یکی است . آنچه مورد بحث و اختلاف فلاسفه است، اتحاد عاقل و معقول در غیر علم مجردات است به ذات خود، که ملاصدرا آن را ثابت کرده است . (از فرهنگ لغات و اصطلاحات فلسفی، از اسفار ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٩</span>).<br>- <span class=\"hlight\">علم برهان </span> ؛ مراد همان علم منطق است که طریقه ٔ استدلال و برهان را می آموزد.<br>- <span class=\"hlight\">علم بسیط</span> ؛عبارت از ادراک شی ٔ است با غفلت از آن ادراک و با غفلت از تصدیق به اینکه مُدرک چیست . در مقابل علم مرکب . علم بسیط بر علم خدا هم اطلاق شده است از آن جهت که محل ارتسام صور مختلف نیست، بلکه به خود مبداء و منشاء فیضان صور است و عین ذات اوست . و همانطور که ذات او از هر جهت بسیطالحقیقه است، علم او هم که عین ذات اوست علم بسیط است . (از فرهنگ لغات و اصطلاحات فلسفی ).<br>- <span class=\"hlight\">علم جزئی </span> ؛ مراد از آن گاه علم طبیعی است در مقابل علم کلی که علم الهی است و گاه نیز بر تصورات و مفاهیم جزئی، علم جزئی اطلاق میکنند، در مقابل کلیات . (از فرهنگ لغات و اصطلاحات فلسفی ).<br>- <span class=\"hlight\">علم حصولی </span> ؛ صوری که از اشیاء عینی خارجی در ذهن حاصل میشود، معلوم بالذات هستند (رجوع به ترکیب علم بالذات شود)، و اشیاء خارجی و عینی که محکی عنه آن صور هستند، معلوم بالعرض اند. و نحوه ٔ علم به اشیاء را که بواسطه ٔ حصول صورتی از معلوم عینی حاصل شود، علم حصولی نامند، و آن را علم انطباعی نیز گویند. (از فرهنگ لغات و اصطلاحات فلسفی ).<br>- <span class=\"hlight\">علم حضوری </span> ؛ علم مجردات را به ذات خود، علم حضوری نامند. و گاه صور علمی در صورتی که عین امر خارجی باشند، و معلوم بعینه و نفسه و بذاته نزد مُدرک حاضر باشد، آن را علم حضوری می نامند.<br>علم حضوری بر دو قسم است : یکی علم عالم به ذات خود مانند علم مجردات به ذات خود، و دیگری علم علت به معلولات خود، که به نفس حضور معلولات نزد علت است . زیرا علت در مرتبه ٔ علیت واجد جمیع کمالات و مراتب و وجودات معلولات خودمی باشد. (از فرهنگ لغات و اصطلاحات فلسفی، از شرح منظومه ص <span class=\"hlight\" dir=\"rtl\">١٣٧</span> و دستور العلماء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٨</span> و تعریفات سید شریف ص <span class=\"hlight\" dir=\"rtl\">١٠٤</span>).<br>- <span class=\"hlight\">علم طبیعی </span> ؛ علمی است که بحث از جسم میکند از آن جهت که معروض حرکت وسکون است . به عبارت دیگر بحث از اجسام را از آن جهت که در معرض کون و فساد و سکون و حرکت اند، علم طبیعی نامند. (فرهنگ لغات و اصطلاحات فلسفی ).<br>- <span class=\"hlight\">علم فعلی </span> ؛ علمی است که وجود خارجی، مستفاد از آن باشد. در مقابل علم انفعالی که مستفاد از خارج است . میر سیدشریف گوید علم فعلی علمی است که از غیر گرفته نشده باشد. و علم انفعالی به عکس آن میباشد.<br>صاحب دستورالعلما آرد: علم فعلی علمی است که وجود خارجی مستفاد از آن باشد. و علم انفعالی به عکس آن باشد. ملاصدرا گوید علم حق تعالی به ذات خود، علم فعلی است . وعلم انفعالی مانند علم انسان است به اشیائی که به ارتسام آنها در نفس حاصل میشود. (از فرهنگ لغات و اصطلاحات فلسفی، از اسفار ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٩</span> و تعریفات ص <span class=\"hlight\" dir=\"rtl\">١٠٤</span> و دستورالعلماء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦٩</span>).<br>- <span class=\"hlight\">علم مرکب </span> ؛ عبارت از ادراک و شعور با ادراک است، یعنی با علم به مُدرک . در مقابل علم بسیط که عبارت از ادراک شی ٔ است با غفلت از آن ادراک . (از فرهنگ لغات و اصطلاحات فلسفی ).<br></font></div>'),
(185438, 'علم', '<span class=\"hlight\">علم .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b>(اِخ ) دهی است از دهستان کولیوند بخش سلسله ٔ شهرستان خرم آباد واقع در <span class=\"hlight\" dir=\"rtl\">٣٣</span> هزارگزی جنوب باختری الشتر و <span class=\"hlight\" dir=\"rtl\">٢١</span> هزارگزی باختر راه اتومبیل رو خرم آباد به کرمانشاه .منطقه ایست جلگه ای و سردسیر و مالاریایی . <span class=\"hlight\" dir=\"rtl\">٣٠٠</span> تن سکنه دارد. آب آن از رود تیمورسوری تأمین میشود. محصولات آن غلات و لبنیات و حبوبات است . شغل اهالی زراعت و گله داری است . راه آن مالرو میباشد. ساکنان آن از طایفه ٔ کولیوند هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(185439, 'علم', '<span class=\"hlight\">علم .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) کوه فردیست در مشرق حاجر و موسوم به أبان است و دارای نخل و وادی است . (از معجم البلدان ).<br></font></div>'),
(185440, 'علم آباد', '<span class=\"hlight\">علم آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) دهی است از دهستان ایل تیمور بخش حومه ٔ شهرستان مهاباد واقع در <span class=\"hlight\" dir=\"rtl\">٣٢</span> هزارگزی جنوب خاوری مهاباد و <span class=\"hlight\" dir=\"rtl\">٢٦</span> هزارگزی باختر راه شوسه ٔ بوکان به میاندوآب . ناحیه ایست کوهستانی و دارای آب و هوای معتدل و سالم . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢٧١</span> تن است . آب آن از چشمه تأمین میشود. محصول آن غلات و توتون و حبوبات است . اهالی به زراعت و گله داری اشتغال دارند. صنایع دستی آنان جاجیم بافی است . دارای راه مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(185441, 'علم آباد', '<span class=\"hlight\">علم آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ خاوری شهرستان رفسنجان واقع در <span class=\"hlight\" dir=\"rtl\">٩</span> هزارگزی شمال رفسنجان و <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی شمال راه شوسه ٔ رفسنجان به کرمان .ناحیه ایست جلگه ای و سردسیر، دارای <span class=\"hlight\" dir=\"rtl\">٣٥٥</span> تن سکنه . آب آن از قنات تأمین میشود. محصولات آن غلات و پسته و پنبه و لبنیات است . شغل اهالی زراعت و گله داری است . دارای راه فرعی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(185442, 'علم آباد', '<span class=\"hlight\">علم آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دهی است از دهستان میربیگ بخش دلفان شهرستان خرم آباد واقع در <span class=\"hlight\" dir=\"rtl\">٢٩</span> هزارگزی باختر نورآباد و <span class=\"hlight\" dir=\"rtl\">١٩</span> هزارگزی باختر راه اتومبیل رو خرم آباد به کرمانشاه . در دامنه ٔ کوه واقع شده . ناحیه ایست سردسیر و مالاریایی، دارای <span class=\"hlight\" dir=\"rtl\">٦٠٠</span> تن سکنه . آب آن از چشمه ٔ بازگیر تأمین میشود. محصول آن غلات و لبنیات وپشم است . شغل اهالی زراعت و گله داری است . صنایع دستی زنان، سیاه چادر و قالی بافی است . دارای راه مالرو بوده و ساکنین آن از طایفه ٔ باولی هستند که در زمستان به قشلاق میروند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(185443, 'علم آباد', '<span class=\"hlight\">علم آباد.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دهی است از دهستان مؤمن آباد بخش درمیان شهرستان بیرجند واقع در <span class=\"hlight\" dir=\"rtl\">٣٨</span> هزارگزی جنوب درمیان و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی شمال راه شوسه ٔ بیرجند به درح . در دامنه ٔ کوه واقع شده و دارای آب و هوای معتدل است . دارای <span class=\"hlight\" dir=\"rtl\">١٧</span> تن سکنه است . آب آن از قنات تأمین میشود. محصول آن غلات و لبنیات . و شغل اهالی زراعت است . راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(185444, 'علم آباد', '<span class=\"hlight\">علم آباد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِخ ) دهی است کوچک ازدهستان نگار بخش مشیز شهرستان سیرجان واقع در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی جنوب مشیز، در سر راه فرعی بافت به نگار. دارای <span class=\"hlight\" dir=\"rtl\">٣٥</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br></font></div>'),
(185445, 'علم برداشتن', '<span class=\"hlight\">علم برداشتن .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ب َ ت َ ]</font></b> (مص مرکب ) حمل علم . برگرفتن علم . <BR><font color=\"Blue\">◄</font> میدان گرفتن . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> کنایه از عزاداری و سوگواری . (آنندراج ) <span class=\"hlight\">:</span> <br>پیش از آن دم که بسوزد ز وفاداریها<br>شمع در ماتم پروانه علم بردارد.<br><font color=\"Red\">سالک یزدی (از آنندراج ).</font><br></font></div>'),
(185446, 'علم بردن', '<span class=\"hlight\">علم بردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ب ُ دَ ]</font></b> (مص مرکب ) حمل علم . نقل علم از جائی به جای دیگر. <BR><font color=\"Blue\">◄</font> رجوع به علم بستن شود. (از آنندراج ).<br></font></div>'),
(185447, 'علم بستن', '<span class=\"hlight\">علم بستن .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ب َ ت َ ]</font></b> (مص مرکب )کنایه از نصب کردن علم است . (آنندراج ) <span class=\"hlight\">:</span> <br>ز زیر چتر سیاه آید آفتاب بلند<br>علم به کنگر نیلی حصار بربندد.<br><font color=\"Red\">میرخسرو (از آنندراج ).</font><br></font></div>'),
(185448, 'علم بنی الصادر', '<span class=\"hlight\">علم بنی الصادر.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ م ُ ب َ نِص ْ صا دِ ]</font></b> (اِخ ) کوهی است روبروی قیروان در مقابل حاجر. (از معجم البلدان ).<br></font></div>'),
(185449, 'علم حاجی باقر', '<span class=\"hlight\">علم حاجی باقر.</span> <font color=\"DarkGreen\"><b>[ ع َل َ م ِ ق ِ ]</font></b> (اِخ ) دهی است کوچک از بخش انارک شهرستان نائین واقع در <span class=\"hlight\" dir=\"rtl\">٢٨</span> هزارگزی شمال انارک . ناحیه ایست جلگه ای و گرمسیر دارای <span class=\"hlight\" dir=\"rtl\">٢٨</span> تن سکنه . آب آن از قنات تأمین میشود و محصول آن غلات است . شغل اهالی زراعت . دارای راه فرعی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(185450, 'علم شدن', '<span class=\"hlight\">علم شدن .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ش ُ دَ ]</font></b> (مص مرکب ) مشهور و معروف گشتن . (ناظم الاطباء) (از آنندراج ). سرشناس شدن <span class=\"hlight\">:</span> <br>دوات و قلم مظهر دانشند<br>به دانش توان شد به عالم علم .<br> <font color=\"Red\">لبیبی .</font><br>هرکه علم شدبه سخا و کرم <br>بند نشاید که نهد بر درم .<br> <font color=\"Red\">سعدی (گلستان ).</font><br>به یُمن دولت منصور شاهی <br>علم شد حافظ اندرنظم اشعار.<br> <font color=\"Red\">حافظ.</font><br>میان جوانان علم شوی ؛ ممتاز گردی . <BR><font color=\"Blue\">◄</font> ظاهر شدن . (غیاث اللغات ) (ناظم الاطباء).<br></font></div>'),
(185451, 'علم غیب', '<span class=\"hlight\">علم غیب .</span> <font color=\"DarkGreen\"><b>[ ع ِ م ِ غ َ <span class=\"hlight\" dir=\"rtl\">/</span> غ ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) غیب دانی . غیب گویی . دانش و آگاهی بر پنهانی ها و آنچه ناپدید از مردم باشد. آگاهی به مغیبات <span class=\"hlight\">:</span> ایزد عزّوجل ّ علم غیب به کس ندهد، چون قضا بود که خراسان از دست ما بشود و کار این قوم بدین منزلت رسید که رسید. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٥٤٦</span>). درعلم غیب چنان بود که سلجوقیان بدین محل خواهند رسید. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٩٧</span>). آفریدگار جل جلاله عالم اسرار است ... و در علم غیب وی رفته است که در جهان در فلان بقعت مردی پیدا خواهد شد که ... (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٩٢</span>).<br>حاجت موری به علم غیب بداند<br>در بن چاهی به زیر صخره ٔ صمّا.<br> <font color=\"Red\">سعدی .</font><br>و رجوع به غیب شود.<br></font></div>'),
(185452, 'علم غیبی', '<span class=\"hlight\">علم غیبی .</span> <font color=\"DarkGreen\"><b>[ ع ِ م ِ غ َ <span class=\"hlight\" dir=\"rtl\">/</span> غ ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) رجوع به علم غیب شود: علم غیبی نمیداند بجز پروردگار.<br></font></div>'),
(185453, 'علم نمودن', '<span class=\"hlight\">علم نمودن .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ن ُ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ <span class=\"hlight\" dir=\"rtl\">/</span> ن َ دَ ]</font></b> (مص مرکب ) علم کردن . آماده کردن . <BR><font color=\"Blue\">◄</font> برافراشتن . <BR><font color=\"Blue\">◄</font> بادبان کشیدن . (ناظم الاطباء). رجوع به علم کردن شود.<br></font></div>'),
(185454, 'علم کردن', '<span class=\"hlight\">علم کردن .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ک َ دَ ]</font></b> (مص مرکب ) برکشیدن تیغ و مانند آن . (آنندراج ) <span class=\"hlight\">:</span> <br>زین ایمنم که تیغ جدایی علم کنی <br>هر قطره خونم از تو جداگانه پر شده ست .<br> <font color=\"Red\">نورالدین ظهوری (از آنندراج ).</font><br> <BR><font color=\"Blue\">◄</font> مشهور کردن . سرشناس کردن . از میان جمع برآوردن . بر سر زبانها افکندن . <BR><font color=\"Blue\">◄</font> راست کردن . افراشتن . برافراشتن . علم نمودن .<br>- <span class=\"hlight\">اوستا علم کردن (در لباس )</span> ؛ از سرو ته آن زدن .<br>- <span class=\"hlight\">دم علم کردن </span> ؛ دم برافراشتن .<br>- <span class=\"hlight\">قد علم کردن </span> ؛ قد برافراشتن .<br></font></div>'),
(185455, 'علماد', '<span class=\"hlight\">علماد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) گروهه ٔ ریسمان . (منتهی الارب ). کلابه . (ناظم الاطباء).آنچه بافته را بر آن گروهه کنند. (از اقرب الموارد). علمادة. ج، عَلامدة، عَلامید. رجوع به علمادة شود.<br></font></div>'),
(185456, 'علمبه', '<span class=\"hlight\">علمبه .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ) چوب بلند. چوب باریک و بسیار بلند.<br>- <span class=\"hlight\">درازعلمبه </span> ؛ بسیار طویل بی اندام . در تداول مردم تهران «درازاَلنگه » گفته شود.<br></font></div>'),
(185457, 'علمة', '<span class=\"hlight\">علمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ م َ ]</font></b> (ع اِ) بمعنای عُلمة است . (از اقرب الموارد) (از ناظم الاطباء).<br></font></div>'),
(185458, 'علمة', '<span class=\"hlight\">علمة.</span> <font color=\"DarkGreen\"><b>[ ع ُ م َ ]</font></b> (ع اِ) شکافی است در لب زیرین یا در یکی از دو جانب آن . (منتهی الارب ). کفیدگی در لب بالایین یا در طرف آن . (ناظم الاطباء) (از اقرب الموارد).<br></font></div>'),
(185459, 'علمت', '<span class=\"hlight\">علمت .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) (پوشش ) شهری است منسوب به سبط لاوی، که در قسمت بن یامین بود. این لغت در یوش، بصورت علمون خوانده شده است . و بعضی بر آنند که علمت همان علمیت جدید است که بفاصله ٔ چهار میل از شمال شرقی قدس ویک میل از عناتا واقع است . (از قاموس کتاب مقدس ).<br></font></div>'),
(185460, 'علمدار', '<span class=\"hlight\">علمدار.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دهی است از دهستان سامن شهرستان ملایر واقع در <span class=\"hlight\" dir=\"rtl\">١٥</span> هزارگزی خاور راه شوسه ٔ ملایر به بروجرد. ناحیه ایست کوهستانی دارای آب و هوای معتدل و مالاریایی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٢٠٠</span> تن است . آب آن از چشمه تأمین میشود. محصول آن غلات و صیفی و لبنیات است . شغل اهالی زراعت و گله داری است . راه آن مالرو است . این ده به علمدار بالا و علمدار پائین قسمت میشود، که فاصله ٔ آنها <span class=\"hlight\" dir=\"rtl\">٣</span> هزار گز است . و سکنه ٔ علمدار بالا <span class=\"hlight\" dir=\"rtl\">٦٦٥</span> تن است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(185461, 'علمدار', '<span class=\"hlight\">علمدار.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دهی است از دهستان مشکین باختری بخش مرکزی شهرستان خیاو واقع در <span class=\"hlight\" dir=\"rtl\">٢٢</span> هزارگزی باختر خیاو و <span class=\"hlight\" dir=\"rtl\">١٠</span> هزارگزی راه شوسه ٔ خیاو به اهر. ناحیه ایست جلگه ای دارای آب و هوای معتدل . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢٣٥</span> تن است .آب آن از مشکین چائی تأمین میشود. محصول آن غلات و حبوبات است . اهالی به زراعت و گله داری اشتغال دارند. راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(185462, 'علمدار', '<span class=\"hlight\">علمدار.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دهی است از دهستان علمدارگرگر بخش جلفا از شهرستان مرند. این ده مرکز بخش است . واقع در <span class=\"hlight\" dir=\"rtl\">٧٥</span> هزارگزی شمال مرند، و <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی راه شوسه و خط آهن جلفا به تبریز. ناحیه ایست جلگه و دارای آب و هوای گرم ومعتدل . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٤٦٢٢</span> تن است . آب آن از چشمه و قنات تأمین میشود. محصولات آن غلات و پنبه و خربوزه است . شغل اهالی زراعت و گله داری است . راه آن شوسه است . دارای اداره ٔ شهربانی و ژاندارمری و پست و تلگراف و نماینده ٔ فرهنگ است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(185463, 'علمدار', '<span class=\"hlight\">علمدار.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (نف مرکب ) کسی که در میان سپاه علم و رایت در دست وی باشد. (ناظم الاطباء). دارنده ٔ علم . حافظ علم . نگهبان درفش و اختر <span class=\"hlight\">:</span> <br>گه علمداران پیش تو علم باز کنند<br>کوس کوبان تو از کوس برآرند آواز.<br> <font color=\"Red\">فرخی .</font><br>به رزمی که مینا علمدار اوست <br>به فوجی که قتل ورع کار اوست .<br> <font color=\"Red\">ملاطغرا (از آنندراج ).</font><br>ای سروردو کون و علمدار روز حشر<br>بخشایش کریم به تو دارد افتخار.<br> <font color=\"Red\">ارادتخان واضح (از آنندراج ).</font><br><BR><font color=\"Blue\">◄</font> نیزه دار. (آنندراج ).<br></font></div>'),
(185464, 'علمدار', '<span class=\"hlight\">علمدار.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دهی است از دهستان سراجو از بخش مرکزی شهرستان مراغه واقع در <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی جنوب خاوری مراغه در مسیر راه ارابه رو مراغه به قره آغاج . ناحیه ایست جلگه ای دارای آب و هوای معتدل و سالم . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١١٠</span> تن است . آب آن از رودخانه ٔ چکان تأمین میشود. محصولات آن غلات و چغندر و توتون و نخود است . شغل اهالی زراعت میباشد. صنایع دستی آنان کرباس بافی است . دارای راه مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(185465, 'علمدار', '<span class=\"hlight\">علمدار.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دهی است از دهستان پائین نهاوند واقع در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی شمال باختری نهاوند و <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی جنوب راه شوسه ٔ نهاوند به کرمانشاه . ناحیه ایست دشت و سردسیر. دارای <span class=\"hlight\" dir=\"rtl\">١٨٥</span> تن سکنه . آب آن از رودخانه ٔ گاوماسیاب تأمین میشود. محصول آن غلات و توتون و حبوبات و انگور و لبنیات است . شغل اهالی زراعت و گله داری است . راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(185466, 'علمدار', '<span class=\"hlight\">علمدار.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دهی است از دهستان مرکزی بخش حومه ٔ شهرستان بهبهان واقع در <span class=\"hlight\" dir=\"rtl\">١٥</span> هزارگزی شمال خاوری بهبهان و <span class=\"hlight\" dir=\"rtl\">١٥</span> هزارگزی شمال خاوری راه اتومبیل رو بهبهان به اهواز. ناحیه ایست دشت و گرمسیر مالاریایی . دارای <span class=\"hlight\" dir=\"rtl\">١٠١</span> تن سکنه . آب آن از چشمه تأمین میشود. محصولات آن غلات و کنجد و حبوبات و پشم و لبنیات است . شغل اهالی زراعت و گله داری است . دارای راه مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(185467, 'علمدار', '<span class=\"hlight\">علمدار.</span> <font color=\"DarkGreen\"><b>[ ع َل َ ]</font></b> (اِخ ) دهی است از دهستان زاوه ٔ بخش حومه ٔ شهرستان تربت حیدریه واقع در <span class=\"hlight\" dir=\"rtl\">٦٠</span> هزارگزی جنوب خاوری تربت حیدریه و در سر راه شوسه ٔ عمومی باخرز. ناحیه ایست دامنه دارای آب و هوای معتدل . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٠٦</span> تن است . آب آن از قنات تأمین میشود. محصول آن غلات و بنشن . شغل اهالی زراعت و گله داری و قالیچه و چادر بافی است . راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br></font></div>'),
(185468, 'علمدارده', '<span class=\"hlight\">علمدارده .</span> <font color=\"DarkGreen\"><b>[ ع َل َ دِه ْ ]</font></b> (اِخ ) دهی از دهستان بیشه ٔ بخش مرکزی شهرستان بابل واقع در <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی جنوب خاوری بابل و یکهزار گزی خاور راه شوسه ٔ بابل به گنج افروز. ناحیه ایست دشت و دارای آب و هوای معتدل و مرطوب و مالاریایی . دارای <span class=\"hlight\" dir=\"rtl\">٦٥٥</span> تن سکنه . آب آن از رود سریجه که از شعب بابل است تأمین میشود. محصول آن برنج و پنبه و صیفی و مختصری کنف و غلات است . اهالی به زراعت اشتغال دارند. راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(185469, 'علمدارده', '<span class=\"hlight\">علمدارده .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ دِه ْ ]</font></b> (اِخ ) دهی است از دهستان درکاسعید بخش چهاردانگه ٔ شهرستان ساری واقع در <span class=\"hlight\" dir=\"rtl\">٣٦</span> هزارگزی شمال راه عمومی کیاسر به ساری . ناحیه ایست کوهستانی جنگلی، دارای آب و هوای مرطوب و مالاریایی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٢١٠</span> تن است .آب آن از چشمه سار و رودخانه ٔ گرم آب تأمین میشود. محصول آن برنج و غلات و لبنیات است . شغل اهالی زراعت وگله داری است . صنایع دستی زنان کرباس و شال بافی است . راه مالرو دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(185470, 'علمدارمحله', '<span class=\"hlight\">علمدارمحله .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ م َ ح َل ْ ل َ ]</font></b> (اِخ ) دهی است از دهستان پنج هزار بخش بهشهر شهرستان ساری واقع در <span class=\"hlight\" dir=\"rtl\">٨</span>هزارگزی خاور بهشهر و یک هزارگزی جنوب راه شوسه ٔ بهشهر به گرگان . ناحیه ایست دشت و دارای آب و هوای معتدل مرطوب مالاریایی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٣٥٠</span> تن است . آب آن از چشمه تأمین میشود. محصول آن برنج و غلات و پنبه و ابریشم و مرکبات و صیفی است . شغل اهالی زراعت، و صنایع دستی زنان کرباس بافی است . یک راه فرعی دارد که به راه شوسه متصل میشود. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(185471, 'علمدارگرگر', '<span class=\"hlight\">علمدارگرگر.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ گ َ گ َ ]</font></b> (اِخ ) نام دهستان تابع از بخش جلفا از شهرستان مرند است، واقع در شمال مرند و کنار رود ارس . محدود است از شمال به رودخانه ٔ ارس و از جنوب به بخش زنوز، و ازخاور به دهستان دیزمار باختری و از باختر به شهرستان خوی . آبادیهای این دهستان قسمتی در جلگه و کنار رود ارس واقع است، که تقریباً در مسیر راه شوسه و خط آهن جلفا میباشند، و یا بواسطه ٔ واقع شدن در جلگه دارای راه شوسه یا ارابه رو هستند. ولی قسمت دیگر قراء آن در کوهستان واقع است و دارای راه مالرو هستند. هوای قرای جلگه معتدل مایل به گرمی و مالاریایی است، ولی قسمت کوهستانی آن ییلاقی و سالم است . این دهستان از <span class=\"hlight\" dir=\"rtl\">٢٨</span> آبادی بزرگ و کوچک تشکیل شده و جمعیت آن <span class=\"hlight\" dir=\"rtl\">٣٢٤٩٠</span> تن است، و قراء مهم آن عبارتست از علمدار (که مرکز دهستان است )، و گرگر. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(185472, 'علمداری', '<span class=\"hlight\">علمداری .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دهی است از دهستان جهانگیری بخش مسجدسلیمان شهرستان اهواز واقع در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی شمال باختری مسجدسلیمان و <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی خاور راه اتومبیل رو مسجدسلیمان به لالی . ناحیه ایست کوهستانی و دارای آب و هوای گرمسیر و مالاریایی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٢٠</span> تن است . آب آن از چشمه تأمین میشود. محصولات آن غلات و لبنیات است . شغل اهالی کارگری شرکت نفت و زراعت و گله داری است . صنایع دستی آنها قالیچه بافی است . دارای راه مالرو است . ساکنین آن از طایفه ٔ هفت لنگ بختیاری هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(185473, 'علمدان', '<span class=\"hlight\">علمدان .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (نف مرکب ) دانا. خردمند. عاقل . (ناظم الاطباء). داننده ٔ علم . دانای به دانش <span class=\"hlight\">:</span> <br>علم خوان همچو علم دان نبود<br>زآنکه جان آفرین چو جان نبود.<br> <font color=\"Red\">سنائی .</font><br>علم دان خاصه ٔ خدای بود<br>علم خوان شوخ و نرگدای بود.<br><font color=\"Red\">سنائی .</font><br></font></div>'),
(185474, 'علمده', '<span class=\"hlight\">علمده .</span> <font color=\"DarkGreen\"><b>[ ع َل َ دِه ْ ]</font></b> (اِخ ) دهی است از دهستان هرازپی بخش مرکزی شهرستان آمل واقع در <span class=\"hlight\" dir=\"rtl\">٢١</span> هزارگزی شمال آمل و یک هزارگزی جنوب راه شوسه ٔ کناره . ناحیه ایست دشت و دارای آب و هوای معتدل و مرطوب مالاریایی و دارای <span class=\"hlight\" dir=\"rtl\">١٧٥</span> تن سکنه است . آب آن از رودخانه ٔ هراز تأمین میشود. محصول آن برنج و غلات و پنبه و حبوبات است . شغل اهالی زراعت است . راه آن مالرو است . این ده از دو محله ٔ بالا و پائین تشکیل میشود. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(185475, 'علمشاه', '<span class=\"hlight\">علمشاه .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ]</font></b> (اِخ ) عبدالرحمان بن صاچلی امیر (متوفی در <span class=\"hlight\" dir=\"rtl\">٩٨٧</span> هَ . ق .). او راست : تحفة الغرائب، به فارسی در خواص اشیاء و انواع حیل مشتمل بر <span class=\"hlight\" dir=\"rtl\">٣٥</span> باب . و نیز تعلیقی بر شرح وقایه ٔ صدرالشریعه ٔ ثانی دارد. (از کشف الظنون ).<br></font></div>'),
(185476, 'علمص', '<span class=\"hlight\">علمص .</span> <font color=\"DarkGreen\"><b>[ع ُ ل َ م ِ ]</font></b> (ع ص ) چیز شگفت که بدان تعجب کنند. (منتهی الارب ). آنچه از آن تعجب شود. (از اقرب الموارد).<br></font></div>'),
(185477, 'علمون', '<span class=\"hlight\">علمون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) همان علمت است که در یوش بدین صورت آمده است . رجوع به علمت شود. (از قاموس کتاب مقدس ).<br></font></div>'),
(185478, 'علمون دبلتایم', '<span class=\"hlight\">علمون دبلتایم .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) (سرپوش دو قطعه ٔ انجیر) یکی از منازل بنی اسرائیل که در نزدیکی نهر ارنون بود. و امکان دارد که همان بیت دبلاتایم باشد. (قاموس کتاب مقدس ).<br></font></div>'),
(185479, 'علمی', '<span class=\"hlight\">علمی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص نسبی ) منسوب به علم . (ناظم الاطباء). رجوع به علم شود. <BR><font color=\"Blue\">◄</font> مقابل عملی .<br></font></div>'),
(185480, 'علمی زاده', '<span class=\"hlight\">علمی زاده .</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ ]</font></b> (اِخ ) شریف عبری . از او چهل وپنج بیت در «زبدة الشعراء» آمده است . (از کشف الظنون ). رجوع به صبری (شریف ...) شود.<br></font></div>'),
(185481, 'علمیة', '<span class=\"hlight\">علمیة.</span> <font color=\"DarkGreen\"><b>[ ع ِ می ی َ]</font></b> (ع ص نسبی ) منسوب به علم . (ناظم الاطباء). علمی .<br>- <span class=\"hlight\">حوزه ٔ علمیه </span> ؛ آنجا که به آموختن علوم مختص است . محل اجتماع علما و طالب علمان، مانند حوزه ٔ علمیه ٔقم یا نجف یا خراسان ...<br></font></div>'),
(185482, 'علمیص', '<span class=\"hlight\">علمیص .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) قَرَب علمیص ؛ منزل سخت که مانده کند مسافر را. (منتهی الارب ).سخت و مانده کننده . (از اقرب الموارد). و آن را عِمْلیص نیز گویند. (از منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185483, 'علمین', '<span class=\"hlight\">علمین .</span> <font color=\"DarkGreen\"><b>[ع َ ل َ م َ ]</font></b> (ع اِ) تثنیه ٔ عَلم در حالت نصب و جر.<br></font></div>'),
(185484, 'علمین', '<span class=\"hlight\">علمین .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ م َ ]</font></b> (اِخ ) (الَ ...) جایی است در شمال افریقا در ساحل غربی اسکندریه . و در سال <span class=\"hlight\" dir=\"rtl\">١٩٤٢</span> م . (جنگ جهانی دوم )، ژنرال «مونتگمری » بریتانیایی، لشکر ژنرال «رومل » آلمانی را درین منطقه شکست داد. (از المنجد، اعلام ).<br></font></div>'),
(185485, 'علن', '<span class=\"hlight\">علن .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ ]</font></b> (ع ص ) آشکار و هویدا. (ناظم الاطباء). ظاهر و منتشر و خلاف مخفی . (از اقرب الموارد).و متداول فارسی زبانان، عَلَن . رجوع به عَلَن شود.<br></font></div>'),
(185486, 'علن', '<span class=\"hlight\">علن .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع مص ) پیدا گردانیدن . (از منتهی الارب ). پیدا و آشکار کردن . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آشکار گردیدن .(منتهی الارب ). پدید آمدن و پخش شدن (خلاف نهان شدن ). (از اقرب الموارد). و رجوع به عَلانیة و عُلون شود.<br></font></div>'),
(185487, 'علن', '<span class=\"hlight\">علن .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) وادیی است در دیار بنی تمیم . (از معجم البلدان ).<br></font></div>'),
(185488, 'علن', '<span class=\"hlight\">علن .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (از ع، ص، اِ) مأخوذ از عربی، با تغییر حرکت لام از کسره به فتحه . آشکارا. ضد سرّ. (غیاث اللغات و آنندراج از صراح و شرح نصاب ). و رجوع به عَلِن شود <span class=\"hlight\">:</span> <br>سیر جان هر کس نبیند جان من <br>لیک سیر جسم باشد در علن .<br><font color=\"Red\">مولوی .</font><br>دست سوی خاک برد آن مؤتمن <br>خاک خودرا درکشید از وی علن .<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">سرّ و علن </span> ؛ نهان و آشکارا <span class=\"hlight\">:</span> <br>ایا سپهر معالی و صدر آل رسول <br>تو راست خلق و خصال علی به سرّ و علن .<br> <font color=\"Red\">سوزنی .</font><br>زآنکه در سرّ و علن داری سخندان را عزیز<br>گردد اندر مدح تو سرّ سخندانان علن .<br><font color=\"Red\">سوزنی .</font><br>گفت نتوانم بدین افسون که من <br>رو بتابم زَامر او سر و علن .<br><font color=\"Red\">مولوی .</font><br></font></div>'),
(185489, 'علنة', '<span class=\"hlight\">علنة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ن َ ]</font></b> (ع ص ) آنکه راز را نپوشد. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185490, 'علندد', '<span class=\"hlight\">علندد.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ دَ ]</font></b>(ع ص ) اسب قوی . <BR><font color=\"Blue\">◄</font> (اِ) چاره، یقال : ما لی عنه علندد و معلندد؛ ای بدّ. (از اقرب الموارد).<br></font></div>'),
(185491, 'علندس', '<span class=\"hlight\">علندس .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ دَ ]</font></b> (ع ص ) سخت شدید. <BR><font color=\"Blue\">◄</font> شیر سخت و توانا. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185492, 'علندسة', '<span class=\"hlight\">علندسة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ دَ س َ ]</font></b> (ع ص ) مؤنث علندس . (منتهی الارب ) (از اقرب الموارد). رجوع به علندس شود.<br></font></div>'),
(185493, 'علندی', '<span class=\"hlight\">علندی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َدا ]</font></b> (ع ص ) سطبر از هر چیزی . (منتهی الارب ). غلیظ از هر چیزی . و یا شتر و اسب ستبر و طویل و سخت . (از اقرب الموارد). علندی <font color=\"DarkGreen\"><b>[ ع ُ ل َ دا <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ل ُ دا ]</font></b> . <BR><font color=\"Blue\">◄</font> (اِ) درختی است خاردار. (منتهی الارب ). نوعی ازغضاة که دارای خار است . (ناظم الاطباء). نوعی از درخت رمل که آن را خار است . (از اقرب الموارد). علنداة؛یکی علندی . ج، عَلاند، عُلادی ̍. (از اقرب الموارد).<br></font></div>'),
(185494, 'علندی', '<span class=\"hlight\">علندی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ دا ]</font></b> (اِخ ) جایگاهی است، و در شعر ذیل از راعی آمده است <span class=\"hlight\">:</span> <br>تحملن َ حتی قلت لسن َ بوارحا<br>بذات العلندی حیث نام المفاخر.<br><font color=\"Red\">(از معجم البلدان ).</font><br></font></div>'),
(185495, 'علندی', '<span class=\"hlight\">علندی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ دا ]</font></b> (ع ص ) سطبر از هر چیزی . علندی <font color=\"DarkGreen\"><b>[ ع َ ل َ دا <span class=\"hlight\" dir=\"rtl\">/</span> ع ُ ل ُ دا ]</font></b> . (منتهی الارب ) (ناظم الاطباء). و رجوع به عَل-ندی ̍ شود.<br></font></div>'),
(185496, 'علندی', '<span class=\"hlight\">علندی .</span> <font color=\"DarkGreen\"><b>[ ع ُل ُ دا ]</font></b> (ع ص ) ستبر از هر چیزی . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> شتر قوی آکنده گوشت . عُلادی . (منتهی الارب ).<br></font></div>'),
(185497, 'علنکد', '<span class=\"hlight\">علنکد.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ک َ ]</font></b> (ع ص ) درشت و رست و سخت . (منتهی الارب ) (از اقرب الموارد). نون آن زائد است . (از اقرب الموارد).<br></font></div>'),
(185498, 'علنکز', '<span class=\"hlight\">علنکز.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ک َ ]</font></b> (ع ص ) مرد درشت اندام سطبر و سخت و پرگوشت بزرگ جثه . (منتهی الارب ). مرد سخت و بزرگ . و نون آن زائد است . (از اقرب الموارد). عَلکز. و رجوع به عَلکز شود.<br></font></div>'),
(185499, 'علنکس', '<span class=\"hlight\">علنکس .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َک َ ]</font></b> (ع ص ) بسیار و انبوه : شَعر علنکس ؛ کثیر متراکب . (از اقرب الموارد). عِلّکس . و رجوع به علکس شود.<br></font></div>'),
(185500, 'علنی', '<span class=\"hlight\">علنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (از ع، ص نسبی، ق ) مأخوذ از عربی ِ عَلِن . عَلَن . آشکارا. آشکار. علناً.<br>- <span class=\"hlight\">علنی شدن </span> ؛ ظاهر شدن . فاش شدن . آشکار شدن . رجوع به علنی شود.<br>- <span class=\"hlight\">علنی کردن </span> ؛ ظاهر کردن . فاش کردن . اظهار کردن . آشکار کردن . رجوع به علنی شود.<br></font></div>'),
(185501, 'عله', '<span class=\"hlight\">عله .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِه ْ ]</font></b> (ع ص ) صفت از مصدر عَلَه در تمام معانی . (از لسان العرب ). سرگشته و حیران . (از لسان العرب ) (تاج العروس ) (ذیل اقرب الموارد) (متن اللغة). <BR><font color=\"Blue\">◄</font> آنکه نفسش وی را وادار به چیزی یابه بدی کند. (از تاج العروس ) (ذیل اقرب الموارد).<br></font></div>'),
(185502, 'عله', '<span class=\"hlight\">عله .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ل َ ]</font></b> (اِخ ) دهی است از دهستان میان آب بخش مرکزی شهرستان شوشتر واقع در <span class=\"hlight\" dir=\"rtl\">٤٧</span> هزارگزی جنوب شوشتر و در کنار راه تابستانی شوشتر به بندقیر و کنار خاوری رود شطیط. ناحیه ایست دشت و گرمسیر. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٦٠</span> تن است . آب آن از رودخانه ٔ شطیط تأمین میشود. این آبادی از دو محل بنام عله ٔ <span class=\"hlight\" dir=\"rtl\">١</span> و عله ٔ<span class=\"hlight\" dir=\"rtl\">٢</span> تشکیل شده است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(185503, 'عله', '<span class=\"hlight\">عله .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َه ْ ]</font></b> (ع مص ) در ملامت افتادن . (منتهی الارب ) (از لسان العرب ) (از تاج العروس ) (از اقرب الموارد) (متن اللغة). <BR><font color=\"Blue\">◄</font> وقوع در حالت خمار و زحمت آن . (ناظم الاطباء). از خمار زحمت یافتن . (منتهی الارب ). در زحمت خمار افتادن . (از لسان العرب ) (اقرب الموارد) (از متن اللغة). گرسنه شدن . (منتهی الارب ) (از لسان العرب ) (تاج العروس ) (اقرب الموارد) (متن اللغة). <BR><font color=\"Blue\">◄</font> ستهیدن . (منتهی الارب ). ستیزه کردن . لجاجت کردن . تندخوئی . حدت و انهماک . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> سرگشته و متحیر گردیدن و دهشت خوردن . (منتهی الارب ) (از لسان العرب ) (اقرب الموارد) (متن اللغة). <BR><font color=\"Blue\">◄</font> آمدوشد نمودن از ترس . (منتهی الارب ). رفت وآمد از فزع . (از لسان العرب ) (تاج العروس ) (اقرب الموارد) (متن اللغة). <BR><font color=\"Blue\">◄</font> پلیدنفس گردیدن . (منتهی الارب ) (از اقرب الموارد). پلید و ضعیف نفس گردیدن . (از لسان العرب ) (تاج العروس ) (متن اللغة). <BR><font color=\"Blue\">◄</font> شادمانی کردن اسب در لگام . (از منتهی الارب ). نشاط و تندی کردن اسب در لجام . (از اقرب الموارد). نشاط و جست وخیز کردن اسب در لجام . (از تاج العروس ) (متن اللغة). <BR><font color=\"Blue\">◄</font> وادار کردن نفس، انسان را به بدی یا بهر چیزی دیگر. (از متن اللغة). <BR><font color=\"Blue\">◄</font> (اِ) حرص و شره و آزمندی . <BR><font color=\"Blue\">◄</font> غم و اندوه و حزن . (از لسان العرب )(تاج العروس ) (از متن اللغة) (ذیل اقرب الموارد).<br></font></div>'),
(185504, 'علهاص', '<span class=\"hlight\">علهاص .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ)سربند شیشه . (منتهی الارب ). در شیشه و بطری . (از لسان العرب ) (تاج العروس ) (اقرب الموارد) (متن اللغة).<br></font></div>'),
(185505, 'علهان', '<span class=\"hlight\">علهان .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) نام اسب أبومُلَیل  عبداﷲبن حرب . (از لسان العرب ) (از تاج العروس ).<br></font></div>'),
(185506, 'علهان', '<span class=\"hlight\">علهان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام مردی که گویند از اشراف بنی تمیم بود. (از لسان العرب ) (تاج العروس ).<br></font></div>'),
(185507, 'علهان', '<span class=\"hlight\">علهان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع ص ) صفت از مصدر عَلَه در تمام معانی . (از متن اللغة). اسب که در لگام شادمانی نماید. (منتهی الارب ). اسب که در لجام نشاط وجست وخیز کند. (از تاج العروس ) (متن اللغة). اسب که در لجام شادمانی و تندی کند. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد گرسنه . (منتهی الارب ) (از لسان العرب ) (از تاج العروس ) (اقرب الموارد). مرد بسیار گرسنه . (از تاج العروس از صحاح ). مرد ناشکیبا و زاری کننده و گرسنه . (از متن اللغة). <BR><font color=\"Blue\">◄</font> مرد ناشکیبا و زاری کننده . (از لسان العرب ) (از تاج العروس ). <BR><font color=\"Blue\">◄</font> مردی که نفسش او را به بدی یا بهر چیز دیگر وادار کند. (از لسان العرب ) (از تاج العروس ) (اقرب الموارد). رجوع به عَلِه شود. ج، عِلاه، عُلاهی ̍ . (منتهی الارب ) (تاج العروس ). <BR><font color=\"Blue\">◄</font> (اِ) شترمرغ نر. (منتهی الارب ) (از لسان العرب ) (تاج العروس ) (اقرب الموارد) (متن اللغة). ظلیم .<br></font></div>'),
(185508, 'علهب', '<span class=\"hlight\">علهب .</span> <font color=\"DarkGreen\"><b>[ ع َ هََ ]</font></b> (ع ص، اِ) تکه ٔ درازشاخ . (منتهی الارب ). آهوی نر درازشاخ، خواه وحشی باشد و خواه اهلی . (از لسان العرب ). آهوی نر درازشاخ . (از تاج العروس ) (از اقرب الموارد) (از متن اللغة). گاو وحشی . (منتهی الارب ) (از تاج العروس ) (اقرب الموارد) (متن اللغة). گاو و آهوی وحشی . (از لسان العرب ). ج، عَلاهبة. (لسان العرب ) (تاج العروس ) (متن اللغة). <BR><font color=\"Blue\">◄</font> مرد بلندبالا. (منتهی الارب ) (از اقرب الموارد). مرد بلندبالا، و یا کهنسال از مردم و آهوان . (از لسان العرب ) (تاج العروس ) (متن اللغة) (ذیل اقرب الموارد).<br></font></div>'),
(185509, 'علهبة', '<span class=\"hlight\">علهبة.</span> <font color=\"DarkGreen\"><b>[ ع َ هََ ب َ ]</font></b> (ع ص ) مؤنث علهب . رجوع به عَلهب شود. (از منتهی الارب ) (از لسان العرب ) (از تاج العروس ) (از اقرب الموارد) (از متن اللغة).<br></font></div>'),
(185510, 'علهج', '<span class=\"hlight\">علهج .</span> <font color=\"DarkGreen\"><b>[ ع َ هََ ]</font></b> (ع اِ) نام درختی است . (منتهی الارب ) (از تاج العروس ) (اقرب الموارد) (متن اللغة).<br></font></div>'),
(185511, 'علهز', '<span class=\"hlight\">علهز.</span> <font color=\"DarkGreen\"><b>[ ع ِ هَِ ]</font></b> (ع اِ)کنه ٔ کلان . (منتهی الارب ). کنه ٔ بزرگ . (از لسان العرب )(تاج العروس ) (اقرب الموارد) (متن اللغة). <BR><font color=\"Blue\">◄</font> نوعی از خوردنی که از خون و پشم در تنگ سال سازند. (منتهی الارب ) (از تاج العروس ) (اقرب الموارد) (متن اللغة). پشم شتر که با خون کنه مخلوط باشد. (از لسان العرب ) (تاج العروس ). خون خشک که پشم شتر در آن کوبیده میشد و در قحطسالیها خورده میشد. (از لسان العرب ) (متن اللغة). <BR><font color=\"Blue\">◄</font> ماده شتر کلانسال که در آن اندکی قوّه باشد. (منتهی الارب ) (از لسان العرب ) (تاج العروس ) (اقرب الموارد) (متن اللغة). <BR><font color=\"Blue\">◄</font> گیاهی است که به بلاد بنی سُلَیم روید. (منتهی الارب ) (از تاج العروس ) (اقرب الموارد) (متن اللغة). در لسان العرب آمده است : چیزی است که به بلاد بنی سلیم روید.و آن را ریشه ایست مانند ریشه ٔ گیاه بَردی . (از لسان العرب ) (تاج العروس ) (اقرب الموارد) (متن اللغة).<br></font></div>'),
(185512, 'علهسة', '<span class=\"hlight\">علهسة.</span> <font color=\"DarkGreen\"><b>[ ع َ هََ س َ ]</font></b> (ع مص ) سخت مروسیدن چیزی را. (از منتهی الارب ). بسختی ممارست کردن چیزی را (از تاج العروس ) (اقرب الموارد) (متن اللغة).<br></font></div>'),
(185513, 'علهم', '<span class=\"hlight\">علهم .</span> <font color=\"DarkGreen\"><b>[ ع ِ هََ م م <span class=\"hlight\" dir=\"rtl\">/</span> ع ِل ْ ل َ ]</font></b> (ع ص ) شتر درشت بزرگ جثه . (منتهی الارب ) (از اقرب الموارد). درشت و بزرگ از شتر و غیره . (از لسان العرب ) (تاج العروس ) (متن اللغة). و نیز رجوع به عُلاهم شود.<br></font></div>'),
(185514, 'علهی', '<span class=\"hlight\">علهی .</span> <font color=\"DarkGreen\"><b>[ ع َ ها ]</font></b> (ع ص ) مؤنث عَلهان . رجوع به علهان شود.<br></font></div>'),
(185515, 'علو', '<span class=\"hlight\">علو.</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است از دهستان دشت سر بخش مرکزی شهرستان آمل واقع در <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی خاور آمل . ناحیه ایست دشت و دارای آب و هوای مرطوب و مالاریایی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٩٥</span> تن است . آب آن از رودخانه ٔ هراز تأمین می شود. محصول آن برنج و صیفی و حبوبات است . شغل اهالی زراعت . راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(185516, 'علو', '<span class=\"hlight\">علو.</span> <font color=\"DarkGreen\"><b>[ ع َل ْوْ ]</font></b> (ع اِ) بلندترین چیز. (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بهترین چیز. (منتهی الارب ). رجوع به عُلْو و عِلْو شود. <BR><font color=\"Blue\">◄</font> جای بلند: أتیته من علو؛ آمدم او را از جای بلند. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ستم و درشتی، یقال : أخذه علواً؛ بستم ودرشتی گرفت آنرا. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185517, 'علو', '<span class=\"hlight\">علو.</span> <font color=\"DarkGreen\"><b>[ ع ُل ْوْ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِل ْوْ ]</font></b> (ع اِ) بلندترین چیز. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بهترین چیز. (منتهی الارب ). رجوع به عَلْو و عِلْو شود. <BR><font color=\"Blue\">◄</font> بالا: علو الدار؛ بالای خانه، خلاف سفل . (منتهی الارب ).<br></font></div>'),
(185518, 'علو', '<span class=\"hlight\">علو.</span> <font color=\"DarkGreen\"><b>[ ع ُ ل ُوو ]</font></b> (ع مص ) سوار شدن بر چهارپا و امثال آن . (از منتهی الارب ) (از اقرب الموارد): علا الدابة. <BR><font color=\"Blue\">◄</font> غلبه کردن و مقهور ساختن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> زدن . (منتهی الارب ) (اقرب الموارد). یقال : علا فلاناً بالسیف . <BR><font color=\"Blue\">◄</font> بالا رفتن و صعود کردن . (از اقرب الموارد): علا المکان، و علابه . <BR><font color=\"Blue\">◄</font> بلند گردیدن برای جای و جز آن . (از منتهی الارب ). بلند گردیدن و مرتفع شدن . (از اقرب الموارد): علا النهار؛ بلند گردید روز. <BR><font color=\"Blue\">◄</font> بلندقدر گردیدن : علا فی المکارم ؛ ای شرف . <BR><font color=\"Blue\">◄</font> بلند گردانیدن . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بزرگ منشی نمودن : علا فی الارض . (از منتهی الارب ). تکبر و تجَبﱡر کردن : علا فلان فی الارض ؛ تکبر و تجبر. (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مطلع شدن : علا بالامر؛ أی اطلع و استقل . <BR><font color=\"Blue\">◄</font> (اِمص ) بلندی و بزرگی قدر. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> عظمت و تجبر، و از آن جمله است «... نجعلها للذین لایریدون علواً فی الارض و لا فساداً...» . (از ذیل اقرب الموارد از لسان ). تکبر <span class=\"hlight\">:</span> <br>علو فی الحیات و فی الممات <br>لحق أنت احدی المعجزات .<br> <font color=\"Red\">(از تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">١٩١</span>).</font><br>بنده به شرح بازنمود تا رای عالی زاده اﷲ علواً بر آن واقف گردد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٣٢٤</span>).<br>همیشه تا نبود خاک را فروغ اثیر<br>همیشه تا نبود ماه را علو زحل .<br> <font color=\"Red\">مسعودسعد.</font><br>می بیاموزد مرا وصف رسول <br>بر علوّم می رساند زین سفول .<br> <font color=\"Red\">مولوی .</font><br> <BR><font color=\"Blue\">◄</font> بلندی <span class=\"hlight\">:</span> <br>قرب بی چونست عقلت را به تو<br>نیست از پیش و پس و سفل و علو.<br> <font color=\"Red\">مولوی .</font><br>- <span class=\"hlight\">علو پیدا کردن </span> ؛ بالا رفتن . استعلا جستن . عالی شدن .<br>- <span class=\"hlight\">علو همت </span> ؛ بلندی همت <span class=\"hlight\">:</span> دوست و دشمن به علو همت و کمال سیاست آن خسرو دیندار... اعتراف آوردند. (کلیله و دمنه ). حال علو همت و کمال بسطت ملک او از آن شایعتر است که در شرح آن به اشباع حاجت افتد. (کلیله و دمنه ). با آنچه مالک عادل انوشیروان کسری بن قباد سعادت ذات ... وعلو همت حاصل است می بینم که کارهای زمانه میل به ادبار دارد. (کلیله و دمنه ). عرصه ٔ آن ولایت از عظم شرف و علو همت خویش تنگ یافت . (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٣٢</span>). آل میکال در علو همت و کمال منقبت چنان بوده اند که ابوالطمحان گوید. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٤٤</span>). تحف و مَبارّ فراوان چنانک لایق علو همت و شرف ابوّت او بود به حضرت سلطان فرستاد. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٩٢</span>).<br></font></div>'),
(185519, 'علوا', '<span class=\"hlight\">علوا.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِ) صبر و نبات اوست . (تحفه ٔ حکیم مؤمن ).<br></font></div>'),
(185520, 'علوان', '<span class=\"hlight\">علوان .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ]</font></b> (ع مص ) عنوان کردن کتاب، و دیباچه نوشتن بر آن . (از ناظم الاطباء): علونت ُ الکتاب بر کتاب عنوان گذاردم . (از لسان العرب ).<br></font></div>'),
(185521, 'علوان', '<span class=\"hlight\">علوان .</span> <font color=\"DarkGreen\"><b>[ ع ُل ْ ]</font></b> (ع اِ) علوان الکتاب ؛ سرنامه . (منتهی الارب ). عنوان آن . (از لسان العرب ) (از اقرب الموارد).عنوان کتاب و دیباچه و مقدمه ٔ آن . (ناظم الاطباء).<br></font></div>'),
(185522, 'علوان', '<span class=\"hlight\">علوان .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ]</font></b> (اِخ ) نام پدر ضحاک است که عجمان وی را مرداس میگفتند. وی از ملوک عرب و برادر شدادبن عاد بود. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٠</span>). صاحب مجمل التواریخ و القصص (ص <span class=\"hlight\" dir=\"rtl\">٢٦</span>) علوان را فرزند عبیدبن عویج ذکر کرده است .<br></font></div>'),
(185523, 'علوان', '<span class=\"hlight\">علوان .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ]</font></b> (اِخ ) ابن حسین، مکنی به ابوالیسیر. محدث است . رجوع به ابوالیسیر شود.<br></font></div>'),
(185524, 'علوان', '<span class=\"hlight\">علوان .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ]</font></b> (اِخ ) ابن عاشق پاشا (شیخ ...). رجوع به علوان چلبی شود.<br></font></div>'),
(185525, 'علوان', '<span class=\"hlight\">علوان .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ]</font></b> (اِخ ) ابن عطیةبن حسن بن محمدبن حداد هیتی حموی . رجوع به علوان حموی شود.<br></font></div>'),
(185526, 'علوان', '<span class=\"hlight\">علوان .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ]</font></b> (اِخ ) قیصربن یوسف جبران . قس (کشیش ) (متولد در <span class=\"hlight\" dir=\"rtl\">١٢٨٧</span> هَ . ق .). وی را تصانیف بسیاری است که از آنجمله است : <span class=\"hlight\" dir=\"rtl\">١</span>- تاریخ کتاب مقدس . <span class=\"hlight\" dir=\"rtl\">٢</span>- خلاصة الصرف و النحو. <span class=\"hlight\" dir=\"rtl\">٣</span>- فرائد المجانی لصفی الخطابة و المعانی . <span class=\"hlight\" dir=\"rtl\">٤</span>- المثال الصحیح لکاهن المسیح . <span class=\"hlight\" dir=\"rtl\">٥</span>- موجز بحث المطالب . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٦</span> از تقویم بکفیا).<br></font></div>'),
(185527, 'علوان', '<span class=\"hlight\">علوان .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ]</font></b> (اِخ ) یوسف لعازاری . قس (کشیش ). وی تا پیش از سال <span class=\"hlight\" dir=\"rtl\">١٣٢٨</span>هَ . ق . زنده بود. از جمله آثار اوست : <span class=\"hlight\" dir=\"rtl\">١</span>- أرج الوطنیة فی حیاة الطوباویة جان دارک الباسلة الفرنسیة، که در سال <span class=\"hlight\" dir=\"rtl\">١٩١٠</span> م . در بیروت چاپ شده است . <span class=\"hlight\" dir=\"rtl\">٢</span>- مرقاة المترجم للصفوف العالیة فی اللغتین الفرنسیة و العربیة.(از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">١٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٧</span> از فهرس المؤلفین ).<br></font></div>'),
(185528, 'علوان آق شهری', '<span class=\"hlight\">علوان آق شهری .</span> <font color=\"DarkGreen\"><b>[ع َل ْ ن ِ ش َ ]</font></b> (اِخ ) بابا نعمةاﷲ. از خواجگان طریقت نقشبندیه . رجوع به بابا نعمةاﷲ محمود نخجوانی شود.<br></font></div>'),
(185529, 'علوان الاقشهری', '<span class=\"hlight\">علوان الاقشهری .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ نُل ْ اَ ش َ ]</font></b> (اِخ ) بابا نعمةاﷲ محمود نخجوانی . از خواجگان طریقت نقشبندیه . رجوع به بابا نعمةاﷲ... شود.<br></font></div>'),
(185530, 'علوان حموی', '<span class=\"hlight\">علوان حموی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ن ِ ح َ م َ وی ی ]</font></b> (اِخ ) (شیخ ...) علی بن عطیةبن محمدبن حداد هیتی حموی شافعی شاذلی . صوفی، واعظ، ناظم، فقیه و اصولی است . متولد در <span class=\"hlight\" dir=\"rtl\">٨٧٣</span> هَ . ق . و متوفی در جمادی الاولای <span class=\"hlight\" dir=\"rtl\">٩٣٦</span> هَ . ق . وی را تصنیفات بسیاری است که از آن جمله است : <span class=\"hlight\" dir=\"rtl\">١</span>- بیان المعانی فی شرح عقیدة الشیبانی . <span class=\"hlight\" dir=\"rtl\">٢</span>- الجوهر المحبوک فی علم السلوک، که منظومه ایست میمی . <span class=\"hlight\" dir=\"rtl\">٣</span>- فتح اللطیف فی اسرار التصریف که رساله ایست مشتمل بر اسرار مسائل نحوی از اجرومیة. <span class=\"hlight\" dir=\"rtl\">٤</span>- کشف الرین و نزح الشین و نورالعین، که آن شرح قصیده ٔ تائیه ٔ شیخ عبدالقادربن حبیب، موسوم به «سلک العین لاذهاب الغین » است . <span class=\"hlight\" dir=\"rtl\">٥</span>- مفتاح الدرایة، در فقه . <span class=\"hlight\" dir=\"rtl\">٦</span>- منهاج العابد المتقی و معراج السالک المرتقی . <span class=\"hlight\" dir=\"rtl\">٧</span>- النصائح المهمة للملوک و الائمة. <span class=\"hlight\" dir=\"rtl\">٨</span>- النفحات القدسیة فی شرح ابیات الشبستریة. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٠</span> از فهرس المؤلفین و الکواکب السائرة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٦</span> و <span class=\"hlight\" dir=\"rtl\">٢١٣</span> و شذرات الذهب ج <span class=\"hlight\" dir=\"rtl\">٨</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> و کشف الظنون و ایضاح المکنون ). و نیز رجوع به کشف الظنون شود.<br></font></div>'),
(185531, 'علوان شاذلی', '<span class=\"hlight\">علوان شاذلی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ن ِ ذِ ]</font></b> (اِخ ) علی بن عطیةبن حسن بن محمدبن حداد هیتی حموی شافعی . رجوع به علوان حموی شود.<br></font></div>'),
(185532, 'علوان شافعی', '<span class=\"hlight\">علوان شافعی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ن ِ ف ِ ]</font></b> (اِخ ) علی بن عطیةبن حسن بن محمدبن حداد هیتی حموی شاذلی . رجوع به علوان حموی شود.<br></font></div>'),
(185533, 'علوان هیتی', '<span class=\"hlight\">علوان هیتی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ن ِ هََ ]</font></b> (اِخ ) علی بن عطیةبن حسن بن محمدبن حداد حموی شافعی شاذلی . رجوع به علوان حموی شود.<br></font></div>'),
(185534, 'علوان چلبی', '<span class=\"hlight\">علوان چلبی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ن ِ چ َ ل َ ]</font></b> (اِخ ) (شیخ ...) ابن عاشق علی پاشابن شیخ مخلص پاشابن بابا الیاس رومی زاهد (متوفی در اماسیه در حدود سال <span class=\"hlight\" dir=\"rtl\">٧٧٠</span> هَ . ق .). او را دیوان شعری است به ترکی که در موضوع اطوار سلوک و تصوف است . (از هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(185535, 'علوانی', '<span class=\"hlight\">علوانی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ]</font></b> (اِخ ) محمدبن ابوبکربن داودبن عبدالرحمان بن عبدالخالق بن عبدالرحمان حموی دمشقی حنفی (محب الدین ابوالفضل ). وی در تفسیر، فقه، نحو، معانی، بیان، فرائض، حساب، منطق، حکمت و غیره عالم و استاد بود. او در حماة در ماه رمضان سال <span class=\"hlight\" dir=\"rtl\">٩٤٩</span> هَ . ق . به جهان آمد و در دمشق در <span class=\"hlight\" dir=\"rtl\">٢٣</span> شوال سال <span class=\"hlight\" dir=\"rtl\">١٠١٦</span> هَ . ق . درگذشت . وی امر قضاوت را در مصر و حمص و حصن الاکراد و معرةالنعمان و معرة نسرین و کلس و اعزاز عهده دار بود و سپس به دمشق رفت . از جمله آثار اوست : <span class=\"hlight\" dir=\"rtl\">١</span>- تنزیل الاَّیات علی الشواهد من الابیات، که شرح شواهد کشاف است . <span class=\"hlight\" dir=\"rtl\">٢</span>- حاشیه بر تفسیر بیضاوی . <span class=\"hlight\" dir=\"rtl\">٣</span>- حاشیه بر الهدایة و الدرر و الغرر، در فقه . <span class=\"hlight\" dir=\"rtl\">٤</span>- الرحلة المصریة. <span class=\"hlight\" dir=\"rtl\">٥</span>- شرح شواهد الکشاف، که به نام تنزیل الاَّیات ... است . <span class=\"hlight\" dir=\"rtl\">٦</span>- شرح منظومه ٔ محب الدین بن شحنة، در معانی و بیان . <span class=\"hlight\" dir=\"rtl\">٧</span>- منظومه ٔ عمدة الحکام و شرح آن . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٩</span> از عرف البشام فیمن ولی فتوی دمشق الشام و خلاصة الاثر ج <span class=\"hlight\" dir=\"rtl\">٣</span> و فهرس التیموریة ج <span class=\"hlight\" dir=\"rtl\">٣</span> و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">١</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(185536, 'علوانی', '<span class=\"hlight\">علوانی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ]</font></b> (اِخ ) احمدبن عمر حمامی علوانی خلوتی شافعی . ساکن حلب بود و در <span class=\"hlight\" dir=\"rtl\">١٠١٧</span> هَ . ق . درگذشت . او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- الاصول العلوانیة فی الاَّداب و الاخلاق الصوفیة. <span class=\"hlight\" dir=\"rtl\">٢</span>- أعذب المشارب فی السلوک . <span class=\"hlight\" dir=\"rtl\">٣</span>- المناقب، در تصوف . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠</span> از خلاصةالاثر ج <span class=\"hlight\" dir=\"rtl\">١</span> و هدیة العارفین و فهرست الخدیویة ج <span class=\"hlight\" dir=\"rtl\">٢</span> و الکشاف و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(185537, 'علوانیه', '<span class=\"hlight\">علوانیه .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ نی ی َ ]</font></b> (اِخ )قریه ای است کوچک جزء آبادی «رضاگاهی » که دهی از دهستان جزیره ٔ صلبوخ بخش مرکزی شهرستان آبادان است . رجوع به رضاگاهی شود. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br></font></div>'),
(185538, 'علوب', '<span class=\"hlight\">علوب .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عَلب . <BR><font color=\"Blue\">◄</font> ج ِ عِلب . رجوع به عَلْب و عِلْب شود.<br></font></div>'),
(185539, 'علوج', '<span class=\"hlight\">علوج .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) پیغام . (منتهی الارب ). پیغام و رسالت . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> پیغامبر. (منتهی الارب ). رسول . (اقرب الموارد) (ناظم الاطباء). الوک . (اقرب الموارد): هذا علوج ُ صدق و ألوک صدق، به یک معنی (از اقرب الموارد) (منتهی الارب )؛ یعنی این رسول امین و صادقی است . (ناظم الاطباء).<br></font></div>'),
(185540, 'علوج', '<span class=\"hlight\">علوج .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عِلج . رجوع به علج شود.<br></font></div>'),
(185541, 'علوجنی', '<span class=\"hlight\">علوجنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ج ِ ]</font></b> (اِخ ) دهی است از دهستان آواجیق بخش حومه ٔ شهرستان ماکو واقع در <span class=\"hlight\" dir=\"rtl\">٢٩</span> هزارگزی شمال باختری ماکو و <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی شمال خاوری کلیساکندی . ناحیه ایست جلگه و سردسیر دارای <span class=\"hlight\" dir=\"rtl\">٢٦٩</span> تن سکنه . آب آن از نهر گلی سوئی تأمین میشود. محصول آن غلات است . اهالی به زراعت و گله داری اشتغال دارند و صنایع دستی آنان جاجیم بافی است . راه آن ارابه رو است . این ده در دو محل به فاصله ٔ هزار گز قرار دارد که مشهور به علی جنی بالا و علی جنی پائین است و سکنه ٔ علی جنی بالا <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن است . اسم این ده را در اصل علی جنی میگویند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(185542, 'علود', '<span class=\"hlight\">علود.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ وَدد ]</font></b> (ع ص ) مسن و سخت، و یا غلیظ و ضخیم . (از لسان العرب ). رجوع به عِلودّ شود.<br></font></div>'),
(185543, 'علود', '<span class=\"hlight\">علود.</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ وَدد ]</font></b> (ع ص ) دراز و بزرگ . (منتهی الارب ) (ناظم الاطباء). کبیر. (از اقرب الموارد): رجل علودالعنق ؛ مرد درازگردن . (منتهی الارب ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> رجل علود؛ سخت و قسی . <BR><font color=\"Blue\">◄</font> مسن و سخت، و یا غلیظ و ضخیم . رجوع به عَلود شود. <BR><font color=\"Blue\">◄</font> بزرگ و سالخورده . (از لسان العرب ). <BR><font color=\"Blue\">◄</font> مهتر استواررای باوقار. (منتهی الارب ). مهتر رزین و باوقار. (از اقرب الموارد). مهتر رزین و بزرگ و ثخین . (از لسان العرب ).<br></font></div>'),
(185544, 'علوز', '<span class=\"hlight\">علوز.</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ]</font></b> (ع اِ) درد شکم . (منتهی الارب ) (از اقرب الموارد). قولنج . (ناظم الاطباء). علّوص . علّوس . دردی در شکم که آن را لِوی ̍ (پیچش ) گویند. (از لسان العرب ). <BR><font color=\"Blue\">◄</font> دیوانگی . (منتهی الارب ). جنون . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرگ . (از لسان العرب ). مرگ زود و سریع. (از منتهی الارب ) (از اقرب الموارد) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> تلاق درشت . (منتهی الارب ).<br></font></div>'),
(185545, 'علوس', '<span class=\"hlight\">علوس .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) چیزی از طعام . (آنندراج ). چیزی از آنچه خورده میشود: ما علسنا علوساً؛ نچشیدیم چیزی . (از اقرب الموارد). نوعی از طعام . (منتهی الارب ).<br></font></div>'),
(185546, 'علوس', '<span class=\"hlight\">علوس .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ]</font></b> (ع اِ) قولنج و درد شکم . (ناظم الاطباء). علّوز. علّوص .<br></font></div>'),
(185547, 'علوس', '<span class=\"hlight\">علوس .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لو ]</font></b> (اِخ ) از قلعه های بختیةالاکراد است از ناحیه ٔ ارزن . (از معجم البلدان ). قلعه ایست اکراد را. (از منتهی الارب ).<br></font></div>'),
(185548, 'علوس', '<span class=\"hlight\">علوس .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) نام قریه ای است . (از معجم البلدان ).<br></font></div>'),
(185549, 'علوش', '<span class=\"hlight\">علوش .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ]</font></b> (ع اِ) از «علش » مشتق، و در کلام عرب شین بعد از لام نیامده است مگر در همین کلمه و نیز در کلمات «لش » و «لشلشة» و «لشلاش ». (از اقرب الموارد) (منتهی الارب ) (لسان العرب ). شغال و گرگ .(منتهی الارب ). گرگ (لغت حمیری است )، و یا شغال . (از لسان العرب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> دابه ایست کوچک . <BR><font color=\"Blue\">◄</font> نوعی از ددان . <BR><font color=\"Blue\">◄</font> مرد سبک حریص و آزمند. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185550, 'علوص', '<span class=\"hlight\">علوص .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ]</font></b> (ع اِ) تخمه . (اقرب الموارد). ناگوارد. (منتهی الارب ). ناگوارد و تخمه . (ناظم الاطباء). تخمه و بشم . (لسان العرب ). <BR><font color=\"Blue\">◄</font> درد شکم . (منتهی الارب ) (از اقرب الموارد). علّوز و یا پیچیدن و لوی . (از اقرب الموارد) (لسان العرب ).و رجوع به علّوز شود. <BR><font color=\"Blue\">◄</font> گرگ . (از لسان العرب ) (از اقرب الموارد). این لغت گاه بصورت صفت نیزبه کار میرود و گفته میشود «رجل علوص »، بنابراین هم اسم است هم صفت . (از لسان العرب ) (اقرب الموارد).<br></font></div>'),
(185551, 'علوض', '<span class=\"hlight\">علوض .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ]</font></b> (ع اِ) شغال (لغت حمیری است ). (منتهی الارب ) (از لسان العرب ) (از اقرب الموارد).<br></font></div>'),
(185552, 'علوف', '<span class=\"hlight\">علوف .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع ص ) شیخ علوف ؛ پیر کلان سال . (منتهی الارب ). این کلمه در منتهی الارب بصورت عِلّوف و در تاج العروس، عِلْوَف ّ بر وزن جِرْدَحْل آمده و گوید: شیخ علوف ؛ أی کبیرالسن . در متن اللغه نیز بر همین وزن آمده است . و در اقرب الموارد، عِلوف ضبط شده است .<br></font></div>'),
(185553, 'علوفات', '<span class=\"hlight\">علوفات .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عُلوفة. آنچه ستوران خورند. <BR><font color=\"Blue\">◄</font> آذوقه وتوشه و ارزاق <span class=\"hlight\">:</span> امیر بفرمود بتعجیل کسان رفتند و بر روستای بیهق علوفات راست کردند. (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٣٧٥</span>). خواجه حسین وکیل شغل بساخت و بیستم این ماه سوری برفت تا مثال دهد علوفات بتمامی ساختن، چنانکه هیچ بینوایی نباشد. (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٥٠</span>).<br></font></div>'),
(185554, 'علوفة', '<span class=\"hlight\">علوفة.</span> <font color=\"DarkGreen\"><b>[ ع َ ف َ ]</font></b> (ع اِ) هرچه ستور بخورد آنرا. (منتهی الارب ) (از اقرب الموارد). آنچه از علف خورند. (ازلسان العرب ). ج، عُلَف (اقرب الموارد)، عُلْف (منتهی الارب )، عَلائف . (لسان العرب ). عُلوفه (در تداول فارسی زبانان ). <BR><font color=\"Blue\">◄</font> (ص ) ناقه و گوسپند که علوفه به خوردن دهی آن را و به چرا نگذاری . (منتهی الارب ) (از اقرب الموارد). شتر ماده یا گوسفندی که برای فربه شدن، علف داده شود و به چرا فرستاده نشود. (از لسان العرب ). این لغت برای مفرد و جمع به کار میرود. (از اقرب الموارد). رجوع به عَلیفة و مُعلّفة شود. گوسفند پرواری . <BR><font color=\"Blue\">◄</font> شتر طلح خوار. (منتهی الارب ).<br></font></div>'),
(185555, 'علوفة', '<span class=\"hlight\">علوفة.</span> <font color=\"DarkGreen\"><b>[ ع ُ ف َ ]</font></b> (ع اِ) ج ِ عَلَف . رجوع به علف و نیز رجوع به أعلاف و عِلاف شود. و در تداول فارسی زبانان جمع آن علوفات آید. خوراک ستور از کاه و جو و علف و یونجه و جز آن که چرام و چرامین و چرایین و واش نیز گویند. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> خوردنی و خوراک . (غیاث ). ارزاق و توشه و آذوقه خاصه در مورد ستور <span class=\"hlight\">:</span> سعید بیامدو به در درقان فرودآمد، او را بسیار نزل و علوفه آوردند و دوهزار مرد از ایشان با او ایستادند و از آنجا بر پی خزریان رفتند. (ترجمه ٔ تاریخ طبری بلعمی ).<br>فراوان گرفتند و انداختند<br>علوفه چهل روزه برساختند.<br> <font color=\"Red\">فردوسی .</font><br>چون امیر اسماعیل خبر یافت که عمرولیث تدارک حرب میسازد، وی سپاه خویش را گرد کرد و علوفه ٔ ایشان داد.(تاریخ بخارا). در یک روز امیر اسماعیل سپاه عمرولیث را بنواخت و علوفه داد و همه را نزدیک عمرولیث فرستاد. (تاریخ بخارا). حالی کوچ کرد و به بلخ رفت تا ماده ٔ طمع ایشان از آن نواحی منقطع گردد و راه زاد و علوفه بر ایشان بسته شود. (ترجمه ٔ تاریخ یمینی ص <span class=\"hlight\" dir=\"rtl\">٢٦٦</span>).<br></font></div>'),
(185556, 'علوفس', '<span class=\"hlight\">علوفس .</span> <font color=\"DarkGreen\"><b>[ ع َ ف ِ ]</font></b> (ع اِ) خبازی است . رجوع به خبازی شود. (ازمخزن الادویة) (الفاظ الادویة) (تحفه ٔ حکیم مؤمن ).<br></font></div>'),
(185557, 'علوفن', '<span class=\"hlight\">علوفن .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (معرب، اِ) کلمه ٔ یونانی مَیفُختَج است که آن آب انگور است در شرایط و حالتی خاص . رجوع به میفختج شود. (از مخزن الادویة).<br></font></div>'),
(185558, 'علوفچی', '<span class=\"hlight\">علوفچی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ]</font></b> (ص مرکب، اِ مرکب ) کسی که علوفه ٔ حیوانات به وی سپرده است . (ناظم الاطباء).<br></font></div>'),
(185559, 'علوق', '<span class=\"hlight\">علوق .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع اِ) مرگ . (منتهی الارب ) (از تاج العروس ) (اقرب الموارد). عَلاّقة.(لسان العرب ). <BR><font color=\"Blue\">◄</font> غول . (منتهی الارب ) (از تاج المصادر) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> بلا و سختی . (منتهی الارب ). داهیة. (لسان العرب ) (تاج العروس ). <BR><font color=\"Blue\">◄</font> آنچه شتر بچرد آنرا. (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درختی که شتر ماده ٔ باردار بخورد آنرا. (منتهی الارب ). درختی که شتران ده ماهه آبستن آن را میخورند. (از تاج العروس ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنچه به مردم درآویزد. (منتهی الارب ) (از لسان العرب ) (تاج العروس ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص ) ناقه ای که بر بچه ٔ غیر مهربان شود و بوی کند و شیر ندهد. (منتهی الارب ) (از تاج العروس ) (از اقرب الموارد). ماده شتری که می بوید و شیر نمیدهد. (از لسان العرب ) (تاج العروس ). <BR><font color=\"Blue\">◄</font> در مثل گویند: عاملنا معاملة العلوق، در حق شخصی که بگوید و نکند. (از منتهی الارب ) (لسان العرب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> ناقه ای که بر گشن خوی گر نگردد و هم بر بچه مهربانی نکند. (منتهی الارب ). ماده شتری که با نر انس نگیرد و بر بچه مهربانی نکند. (از لسان العرب ) (تاج العروس ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> زن که بر غیر شوهر خود مهربان باشد. (منتهی الارب ). زنی که شوهر خود را دوست ندارد. (از لسان العرب ). فَروک . (اقرب الموارد از اساس ). <BR><font color=\"Blue\">◄</font> زنی که جز شوهر خود، کسی را دوست نداشته باشد . <BR><font color=\"Blue\">◄</font> (اِ) زنی که بچه ٔ غیر را شیر دهد. (از تاج العروس ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِ) شیر اندک : ما بالناقة علوق ؛ أی شی ٔ من اللبن . (از لسان العرب ) (منتهی الارب ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> چهارپا و دابة. <BR><font color=\"Blue\">◄</font> هرچیز گرانبها و فرد، غیر از معنویات . عِلق . <BR><font color=\"Blue\">◄</font> آب نر. ماءالفحل . ج، عُلُق . (از لسان العرب ).<br></font></div>'),
(185560, 'علوق', '<span class=\"hlight\">علوق .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) دوست داشتن و خواهش نمودن . (از منتهی الارب ). دوست داشتن . (از لسان العرب ) (تاج العروس ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> کشتن : علق فلان دم َ فلان ؛ یعنی کشت .(از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> شروع کردن . (از منتهی الارب ) (از تاج العروس ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> باردار گردیدن . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> بسته شدن خون زن در رحم با نطفه ٔ مرد در ابتدای ایام حمل . (غیاث اللغات ). <BR><font color=\"Blue\">◄</font> چسبیدن زلوک (زالو) در دهان ستور وقت آب خوردن . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> خصومت کردن و درآویختن . (از منتهی الارب ) (از ناظم الاطباء). درآویختن . (از لسان العرب ) (از اقرب الموارد). یقال : علق الخصم بخصمه . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> درآویختن آهو در دام : علق الظبی . (از منتهی الارب ). <BR><font color=\"Blue\">◄</font> علوق جامه از درخت ؛ آویخته ماندن آن . (از لسان العرب ). نیز رجوع به عِلق و عَلاقة شود. <BR><font color=\"Blue\">◄</font> (اِ) گرانمایه ترین مال . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> ج ِ عِلق . رجوع به علق شود.<br></font></div>'),
(185561, 'علولو', '<span class=\"hlight\">علولو.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ لو لو ]</font></b> (اِخ ) دهی است جزء دهستان گرمادوز بخش کلیبر شهرستان اهر واقع در <span class=\"hlight\" dir=\"rtl\">٤٠</span> هزارگزی شمال خاوری کلیبر و <span class=\"hlight\" dir=\"rtl\">٤٠</span> هزارگزی راه شوسه ٔ اهر به کلیبر. ناحیه ایست کوهستانی و دارای آب و هوای معتدل مایل به گرمی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٥٦</span> تن است . آب آن از چشمه تأمین میشود. محصول آن غلات است . اهالی به زراعت و گله داری اشتغال دارند. راه آن مالرو است . این ده محل قشلاق ایل چلیپانلو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(185562, 'علوم', '<span class=\"hlight\">علوم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عِلم . دانشها. رجوع به علم شود <span class=\"hlight\">:</span> <br>علوم عالم دانم ولیکن اندر عصر<br>اگر دو مردم دانم بدان که نادانم .<br> <font color=\"Red\">مسعودسعد.</font><br>- <span class=\"hlight\">علوم آثار علوی </span> ؛ علم به افلاک و حرکات فلکی و آثار آنها، و امور و حوادث جوی و نجوم است . (فرهنگ علوم عقلی ص <span class=\"hlight\" dir=\"rtl\">٤١١</span>، از مصنفات باباافضل کاشانی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣</span> رساله ٔ <span class=\"hlight\" dir=\"rtl\">٥</span>).<br>- <span class=\"hlight\">علوم ابداعی </span> ؛ صور علمیه ٔ حق است، و جواهر مفارقه اند که صور علمیه ٔ خدایند. (فرهنگ علوم عقلی از رسائل ملاصدرا ص <span class=\"hlight\" dir=\"rtl\">٢٤٢</span>).<br>- <span class=\"hlight\">علوم جزئیه </span> ؛ علومی است که موضوعات آنها أخص از موضوع علوم دیگر باشد، چنانکه موضوع طب از موضوع طبیعی . (یادداشت مرحوم دهخدا).<br>- <span class=\"hlight\">علوم زبان عربی </span> ؛ دارای چهار رکن است و عبارتند از لغت، نحو، بیان و ادب . و شناختن آنها برای اهل شریعت ضروریست زیرا مأخذ کلیه ٔ احکام شرعی از کتاب و سنت است که به زبان عرب میباشد. رجوع به هر یک از این علوم شود. (از ترجمه ٔ مقدمه ٔ ابن خلدون ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٦١</span>).<br>- <span class=\"hlight\">علوم صوفیه </span> ؛ علوم احوال است، و احوال مواریث اعمال است . و تا کسی را معاملات ظاهر باک نباشد احوال باطن درست نباشد. (فرهنگ مصطلحات عرفا، از شرح تعرف ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٧١</span>).<br>- <span class=\"hlight\">علوم عقلی </span> ؛ مسائلی است که برای انسان طبیعی است ازاینرو که وی دارای اندیشه است . و بنابراین دانشهای مزبور اختصاص به ملت معینی ندارد، و در نوع بشر از آغاز اجتماع و عمران طبیعی وجود داشته است و آنها را به نام علوم فلسفه و حکمت میخوانند ومشتمل بر چهار دانش است : نخست دانش منطق، و آن علمی است که ذهن را از لغزش در فراگرفتن مطالب مجهول از امور حاصل معلوم، محافظت میکند. دوم دانش طبیعی (فیزیک )، که بحث در محسوسات است، مانند اجسام عنصری و موالید آنها از قبیل کان و گیاه و جانور و اجسام آسمانی و حرکات طبیعی یا نفسی و جز اینها. سوم علوم الهی (متافیزیک )، که بحث در امور ماورای طبیعت است، مانندروحانیات . چهارم تعالیم (ریاضیات )، که بحث در مقادیر است، و خود مشتمل بر چهار علم است : هندسه، ارثماطیقی، موسیقی، هیئت . (از ترجمه ٔ مقدمه ٔ ابن خلدون ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٠٧</span>). رجوع به هر یک از این علوم شود.<br>- <span class=\"hlight\">علوم متعارفه </span> ؛ مقدمات علوم مدونه است که به نفس خود ظاهر و آشکار باشد. (ازکشاف اصطلاحات الفنون ). مبادی تصدیقیه ای که بدیهی هستند.<br>- <span class=\"hlight\">علوم مدونه </span> ؛ علومی رانامند که قواعد آن در کتابی تدوین و جمعآوری شده است . (از کشاف اصطلاحات الفنون ). و آنها عبارتند از: علم اخلاق، ادب، اصطرلاب، اصول، انشاء، بتانیک، بیان، تاریخ طبیعی، تراپوتیک، تشریح، تصوف، تعبیر، تعویذات، تفسیر، تواریخ، جبر و مقابله، جراثقال، جغرافیا، جفر، حدیث، حجاری، حساب، حقوق، حکمت، دواسازی، رسم الخط، رَمْل، شیمی (کیمیا)، صرف، طب، طلسمات، عدد، عروض، فرائض، فقه، فلاحت، فیزیک، فیزیولوژی، قافیه، قرائت، قیافه، کلام، کیمیا، محاضرات (که آن لطیفه گوئی و حاضرجوابی است )، مساحت، معانی، معما، مناظر و مرایا، منطق، موسیقی، نجوم، نحو، نقاشی، هندسه، هیئت . (از غیاث اللغات ) (آنندراج ) (ناظم الاطباء). و رجوع به هر یک ازین علوم شود.<br>- <BR><font color=\"Blue\">◄</font> (اصطلاح تصوف ) علوم مدونه در مقابل علوم غیرمدونه است، و مراد علوم ذوقی و حالی و دریافتی است نه علوم بافتی . (فرهنگ مصطلحات عرفا ص <span class=\"hlight\" dir=\"rtl\">٢٨٦</span>).<br></font></div>'),
(185563, 'علون', '<span class=\"hlight\">علون .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع مص ) آشکارا شدن . (تاج المصادر بیهقی ) (مصادرزوزنی ) (از منتهی الارب ). ظاهر شدن و منتشر شدن . خلاف مخفی شدن . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیدا گردانیدن : علنته ؛ پیدا گردانیدم آنرا. لازم و متعدی است .(از منتهی الارب ). و نیز رجوع به عَلن و علانیة شود.<br></font></div>'),
(185564, 'علون آباد', '<span class=\"hlight\">علون آباد.</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b>(اِخ ) دهی است از دهستان حومه ٔ بخش کوهپایه ٔ شهرستان اصفهان واقع در <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی شمال کوهپایه و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی شمال راه شوسه ٔ اصفهان به یزد. ناحیه ایست کوهستانی و دارای آب و هوای معتدل . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٧٢٠</span> تن است . آب آن از قنات تأمین میشود. محصول آن غلات است . اهالی به زراعت اشتغال دارند. راه آن ماشین رو است . این ده دارای دبستان است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(185565, 'علونة', '<span class=\"hlight\">علونة.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ وَ ن َ ]</font></b> (ع مص ) عنوان کردن کتاب و دیباچه نوشتن بر آن . (از ناظم الاطباء). رجوع به عِلوان شود: علونت الکتاب ؛ بر کتاب عنوان گذاردم . (از لسان العرب ).<br></font></div>'),
(185566, 'علونی', '<span class=\"hlight\">علونی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) محمدبن احمدبن علی بن یحیی بن علی بن محمدبن قاسم بن حمود حسنی تلمسانی مالکی، مکنی به ابوعبداﷲ. فقیه و متکلم و اصولی بود که در تلمسان متولد شد و همراه سلطان ابوعنان به فاس رفت . سپس به تلمسان بازگشت و در مدرسه ای در آنجا به تدریس پرداخت . تولد او در سال <span class=\"hlight\" dir=\"rtl\">٧١٠</span> و وفاتش در <span class=\"hlight\" dir=\"rtl\">٧٧١</span> هَ . ق .بوده است . و «علونی » نسبت به قریه ای است از قرای تلمسان . او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- شرح جمل خونجی . <span class=\"hlight\" dir=\"rtl\">٢</span>- کتابی در قضا وقدر. <span class=\"hlight\" dir=\"rtl\">٣</span>- المفتاح فی اصول الفقه . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠١</span> از البستان و نیل الابتهاج و اعلام زرکلی ).<br></font></div>'),
(185567, 'علوک', '<span class=\"hlight\">علوک .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع اِ) ج ِ عِلک . رجوع به علک و نیز أعلاک شود.<br></font></div>'),
(185568, 'علوکندی', '<span class=\"hlight\">علوکندی .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) دهی است از دهستان سراجو از بخش مرکزی شهرستان مراغه واقع در چهارده هزاروپانصدگزی جنوب خاوری مراغه و <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی جنوب راه ارابه رو مراغه به قره آغاج . ناحیه ایست کوهستانی و دارای آب و هوای معتدل . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٨٠</span> تن است . آب آن از چشمه سارها تأمین میشود. محصول آن غلات و کرچک و نخود است و اهالی آنجا به زراعت اشتغال دارند. صنایع دستی آنان جاجیم بافی است . راه آن مالرو است . نام این ده را در اصل «علی کندی » میگویند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(185569, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) عبدالسلام الضریربن سلطان محمدبن عبداﷲبن اسماعیل علوی حسنی . رجوع به علوی حسنی شود.<br></font></div>'),
(185570, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) علی بن حسن (یا حسین )، مکنی به ابوالقاسم . از منجمان و ریاضی دانان مشهور قرن چهارم هجری بود. رجوع به ابن أعلم در همین لغت نامه و نیز به ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٢</span> و قاموس الاعلام ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٠٣</span> ونامه ٔ دانشوران ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦١٢</span> و أخبارالعلما ص <span class=\"hlight\" dir=\"rtl\">١٥٧</span> شود.<br></font></div>'),
(185571, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) عبیداﷲبن علی بن ابراهیم بن حسن بن عبیداﷲبن عباس علوی . وی فقیه بود و ابتدا در بغداد میزیست، سپس به مصر رفت و در سال <span class=\"hlight\" dir=\"rtl\">٣١٢</span> هَ . ق . در آنجادرگذشت . او راست : الجعفریة فی فقه اهل البیت . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٠</span> از اعیان الشیعة ج <span class=\"hlight\" dir=\"rtl\">٣٩</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span>).<br></font></div>'),
(185572, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) عبداﷲبن علی بن ابی المحاسن بن سعدبن مهدی علوی محمدی . رجوع به علوی محمدی شود.<br></font></div>'),
(185573, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) عبدالصمدبن عبداﷲ علوی دامغانی، ملقب به شمس الدین . رجوع به علوی دامغانی شود.<br></font></div>'),
(185574, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) علی بن عبداﷲبن احمد علوی حنفی . ادیب مصری . رجوع به علوی حنفی شود.<br></font></div>'),
(185575, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ع َ ل َ ]</font></b> (اِخ ) علی بن عبداﷲبن علی بن عمر علوی طولقی جزائری حسنی خلوتی مالکی . رجوع به علوی طولقی شود.<br></font></div>'),
(185576, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) عمربن علی بن ابی بکر علوی یمنی حنفی، مکنی به ابوالخطاب . رجوع به علوی یمنی شود.<br></font></div>'),
(185577, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) قاسم بن محمدبن هشام (یا هاشم ) مدائنی . از علمای ریاضی قرن سوم و چهارم هجری . رجوع به قاسم بن محمدبن هشام شود.<br></font></div>'),
(185578, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) محمدبن احمدبن عمربن یحیی . لغوی و نحوی . رجوع به علوی حضرمی شود.<br></font></div>'),
(185579, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) عبدالرحمان بن ابراهیم بن اسماعیل بن عبداﷲبن عبدالرحمان بن محمدبن یوسف علوی یمانی زبیدی . رجوع به علوی زبیدی شود.<br></font></div>'),
(185580, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) محمدبن حسین بن عبیداﷲبن حسین علوی شریف، مکنی به ابوعبداﷲ. رجوع به علوی شریف شود.<br></font></div>'),
(185581, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) محمدبن ظفربن محمدبن احمد علوی حسینی، مکنی به ابوالحسن . رجوع به علوی حسینی شود.<br></font></div>'),
(185582, 'علوی', '<span class=\"hlight\">علوی .</span><font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) محمدبن علی بن عبدالرحمان، مکنی به ابوعبداﷲ. از فضلای قرن پنجم هجری بود. او راست : التعازی . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢</span> از اعلام الشیعة).<br></font></div>'),
(185583, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) محمدطیب بن محمدصالح بن محمد عبداﷲ علوی مکی . رجوع به علوی مکی شود.<br></font></div>'),
(185584, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) محمدمهدی . از مورخان بود که به سال <span class=\"hlight\" dir=\"rtl\">١٣١٥</span> هَ . ق . درگذشت . او راست : تاریخ طوس، یا مشهد رضوی . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨</span> از فهرس دارالکتب المصریة ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">٦٣</span>).<br></font></div>'),
(185585, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع ُل ْ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِل ْ <span class=\"hlight\" dir=\"rtl\">/</span> ع َل ْ ]</font></b> (از ع، ص نسبی ) منسوب به «علو» خلاف سفل . (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> ملک و فرشته . (برهان )(غیاث اللغات ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> کوکب . (غیاث ) (برهان ). سیاره . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بالا. بالاتر. (دزی از چهارمقاله حاشیه ٔ ص <span class=\"hlight\" dir=\"rtl\">١١</span>). بلندی وسمائی ضد سفلی، که منو نیز گویند. (ناظم الاطباء).<br>- <span class=\"hlight\">علوی گهر</span> ؛ آسمانی اصل . بلندقدر. اصیل . بلندپایه <span class=\"hlight\">:</span> <br>بچگانْمان همه ماننده ٔ شمس و قمرند...<br>تابناکند از آنروی که علوی گهرند.<br> <font color=\"Red\">منوچهری .</font><br>- <span class=\"hlight\">آباء علوی </span> ؛ نه فلک یاهفت ستاره . (غیاث ). و رجوع به آباء شود <span class=\"hlight\">:</span> اما چون این عالم کمال یافت و اثر آباء عالم علوی در امهات عالم سفلی تأثیر کرد... (چهارمقاله ص <span class=\"hlight\" dir=\"rtl\">١١</span>).<br></font></div>'),
(185586, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) یحیی بن قاسم بن عمربن علی علوی حسنی یمانی صنعانی، ملقب به عزالدین . رجوع به علوی یمانی شود.<br></font></div>'),
(185587, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) یحیی بن عبداﷲ علوی، ملقب به ناصرالدین . عالم در علوم نقلی و عقلی . وی از امرا بود و مدتی نیابت قضا را در شیراز عهده دار بود. او در قرن هشتم هجری میزیست، و در فقه کتابهای بسیاری تألیف کرد. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">١٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٨</span> از شدالازار شیرازی ص <span class=\"hlight\" dir=\"rtl\">٣٢٩</span>).<br></font></div>'),
(185588, 'علوی', '<span class=\"hlight\">علوی .</span><font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) ناصربن رضابن محمدبن عبداﷲ علوی حسینی، مکنی به ابوابراهیم . رجوع به علوی حسینی شود.<br></font></div>'),
(185589, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) میر محمدطاهر. شاعر. رجوع به علوی کاشانی شود.<br></font></div>'),
(185590, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) میرزا حسین بن میرزا محسن . رجوع به علوی سبزواری شود.<br></font></div>'),
(185591, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) احمدبن زین بن علوی بن احمد. از متصوفه ٔ حضرموت . رجوع به علوی حبشی شود.<br></font></div>'),
(185592, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع ُ وی ی ]</font></b> (ص نسبی ) منسوب به «عالیه ٔ» نجد (برخلاف قیاس ). رجوع به «عالیة» و عالی شود. و در شعر مراربن منقذ فقعسی آمده است <span class=\"hlight\">:</span> <br>اًذا هب علوی الریاح وجدتنی <br>کأنی لعلوی الریاح نسیب .<br> <font color=\"Red\">(از معجم البلدان ).</font><br>و نیز رجوع به منتهی الارب واقرب الموارد شود.<br></font></div>'),
(185593, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع ُل ْ ]</font></b> (اِخ ) مصطفی . وی از فضلای مصر است که در سال <span class=\"hlight\" dir=\"rtl\">١٢٦٧</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٣٠٢</span> هَ . ق . در سن سی وپنج سالگی درگذشت . او راست : الثمرة الوافیة، در علم جغرافی . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٥</span> از هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٩</span> و معجم المطبوعات ص <span class=\"hlight\" dir=\"rtl\">١٧٥٤</span> و فهرست الخدیویة ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨</span> و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٧</span> و فهرس دارالکتب المصریة ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٩</span>).<br></font></div>'),
(185594, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْ وا ]</font></b> (اِخ ) نام اسبی است . (منتهی الارب ).<br></font></div>'),
(185595, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ص نسبی ) منسوب به علی . رجوع به علی شود. کسی که از اولاد علی بن ابی طالب (ع ) باشد. (ناظم الاطباء). مصطلح آن است که کسی را که از اولاد علی و فاطمه (ع ) باشد علوی گویند. (از غیاث اللغات ) (آنندراج ) <span class=\"hlight\">:</span> چون کار آل برمک بالا گرفت ... مردی علوی یحیی بن عبداﷲبن حسن مثنی بن الامام حسن المجتبی بن امیرالمؤمنین ... علی بن ابی طالب (ع )... خروج کرد و گرگان و طبرستان بگرفت . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٢١</span>). جز فرمانبرداری روی نیست که دشمنان بسیار داریم و متهم به علویانیم . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٢٢</span>). شیادی گیسوان بافت بصورت علویان و با قافله ٔحجاج به شهری درآمد در هیئت حاجیان . (گلستان سعدی ).<BR><font color=\"Blue\">◄</font> مقابل عثمانی . کسانی را گویند که پس از قتل عثمان، علی را به قتل عثمان تهمت نکردند و به عایشه و معاویه نپیوستند. و پیروان این طریقت را نیزعلوی گویند هرچند درک زمان علی و معاویه نکرده باشند. و میان رواة از تابعین و جز آنان را با صفت «و کان علویاً» نام میبرند، مقابل عثمانی . و ناصرخسرو قبادیانی را که علوی میگفتند ازین قبیل است، نه اینکه از ذریه ٔ طاهره ٔ رسول باشد. (یادداشت مرحوم دهخدا).<br></font></div>'),
(185596, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) متوفی در سال <span class=\"hlight\" dir=\"rtl\">٩٩٣</span> هَ . ق . او را دیوانی است به ترکی . و در کتاب زبدة الاشعار، <span class=\"hlight\" dir=\"rtl\">٦٨</span> بیت از وی نقل شده است .<br></font></div>'),
(185597, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دهی است از دهستان مشهد اردهار بخش قمصر شهرستان کاشان واقع در <span class=\"hlight\" dir=\"rtl\">٥٨</span> هزارگزی شمال باختری قمصر، درسر راه فرعی کاشان به مشهد اردهار. ناحیه ایست کوهستانی و سردسیر. سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> تن است . آب آن از دو رشته قنات تأمین میشود. محصول آن غلات و حبوبات و میوه است . این ده دارای معصومزاده و چناری کهنسال است . اهالی به زراعت و گله داری اشتغال دارند و صنایع دستی زنان قالی بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(185598, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دهی است از دهستان تُرک شهرستان ملایر واقع در <span class=\"hlight\" dir=\"rtl\">٣٣</span> هزارگزی شمال خاوری شهر ملایر و <span class=\"hlight\" dir=\"rtl\">٢١</span> هزارگزی خاور راه شوسه ٔ ملایر به همدان . ناحیه ایست جلگه، و دارای آب و هوای معتدل و مالاریایی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٠٨٨</span> تن است . آب آن از قنات تأمین میشود. محصول آن غلات، انگور و صیفی است . اهالی به زراعت اشتغال دارند. صنایع دستی زنان قالی بافی است . راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br></font></div>'),
(185599, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) ده مخروبه ایست از بخش سمیرم بالا از شهرستان شهرضا. (فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(185600, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) ابن سیداحمدبن عبدالرحمان سقاف شافعی . رجوع به علوی سقاف شود.<br></font></div>'),
(185601, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) احمدبن ابوبکربن سمیط. از متصوفه است و او راست : منهل الورّاد من فیض الامداد بشرح ابیات القطب عبداﷲبن علوی الحداد.(از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٦</span> از فهرس التصوف ص <span class=\"hlight\" dir=\"rtl\">٤٨</span>).<br></font></div>'),
(185602, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) عبدالسلام بن عمر علوی حسنی . رجوع به علوی حسنی شود.<br></font></div>'),
(185603, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) احمدبن زین العابدین . او راست : مناهج الاخبار فی شرح الاستبصار، که درسال <span class=\"hlight\" dir=\"rtl\">١٠٣٩</span> هَ . ق . آن را به پایان رسانده است . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span> از اعیان الشیعة ج <span class=\"hlight\" dir=\"rtl\">٣٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤١٠</span>).<br></font></div>'),
(185604, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) جعفربن محمدبن جعفربن حسن بن جعفربن حسن بن حسن بن علی بن ابی طالب . رجوع به علوی بغدادی شود.<br></font></div>'),
(185605, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) حسن بن حمزةبن علی بن عبداﷲبن محمدبن حسن بن حسین علوی طبری مرعشی . رجوع به علوی مرعشی شود.<br></font></div>'),
(185606, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) حسن بن علی بن داودعلوی صنعانی مؤیدی زیدی . رجوع به علوی زیدی شود.<br></font></div>'),
(185607, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) حسن بن محمدبن احمدبن یحیی زیدی . رجوع به علوی یمنی شود.<br></font></div>'),
(185608, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) حسن بن محمدبن یحیی بن حسن بن جعفر حسینی . رجوع به علوی بغدادی شود.<br></font></div>'),
(185609, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) حسین بن محمدبن عبداﷲ مکنی به ابوعلی . رجوع به حسین حسنی شود.<br></font></div>'),
(185610, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) سلیمان بن ابراهیم بن عمر علوی تعزی یمنی، مکنی به ابوالربیع، و ملقب به نفیس الدین . رجوع به علوی تعزی شود.<br></font></div>'),
(185611, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) طاهربن حسین ابن طاهربن محمد. رجوع به علوی حسینی شود.<br></font></div>'),
(185612, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) عباس بن سلطان عبدالرحمان علوی، مکنی به ابوالفضل . او را مجموعه ایست . وفات وی در سال <span class=\"hlight\" dir=\"rtl\">١٢٩٦</span> هَ . ق . بود. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٦٠</span>).<br></font></div>'),
(185613, 'علوی', '<span class=\"hlight\">علوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) عبدالرحمان بن محمد یوسف بن عمربن علی بن ابی بکر علوی زبیدی یمانی حنفی، ملقب به وجیه الدین . رجوع به علوی زبیدی شود.<br></font></div>'),
(185614, 'علوی برسوی', '<span class=\"hlight\">علوی برسوی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ب ُ ]</font></b> (اِخ ) از شعرای مرادخان غازی . او را دیوانی است به ترکی . و در کتاب زبدةالاشعار یک بیت از وی نقل شده است .<br></font></div>'),
(185615, 'علوی برسی', '<span class=\"hlight\">علوی برسی .</span> <font color=\"DarkGreen\"><b>[ع َ ل َ ب ُ ]</font></b> (اِخ ) قاسم بن ابراهیم بن ... صاحب صعدة <font color=\"DarkGreen\"><b>[ کذا ]</font></b>، از علما و متکلمین زیدیه . و زیدیه ٔ قاسمیه بدو منسوبند. او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- کتاب الاشربة. <span class=\"hlight\" dir=\"rtl\">٢</span>- کتاب الامامة. <span class=\"hlight\" dir=\"rtl\">٣</span>- کتاب الایمان و النذور. <span class=\"hlight\" dir=\"rtl\">٤</span>- کتاب الرد علی الرافضة. <span class=\"hlight\" dir=\"rtl\">٥</span>- کتاب سیاسة النفس . (از الفهرست ابن الندیم ).<br></font></div>'),
(185616, 'علوی برقعی', '<span class=\"hlight\">علوی برقعی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ب ُ ق َ ]</font></b> (اِخ ) کسی بود که ازبصره خروج کرد. (از حدود العالم چ دانشگاه ص <span class=\"hlight\" dir=\"rtl\">١٥٢</span>).<br></font></div>'),
(185617, 'علوی بغدادی', '<span class=\"hlight\">علوی بغدادی .</span> <font color=\"DarkGreen\"><b>[ع َ ل َ ی ِ ب َ ]</font></b> (اِخ ) حسن بن محمدبن یحیی بن حسن بن جعفر حسینی . شیعی و مشهور به ابن اخی ابی طاهر، مکنی به ابوعلی . وی نسابة بود و در سال <span class=\"hlight\" dir=\"rtl\">٣٥٨</span> هَ . ق . وفات کرد. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٢</span> از المیزان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٢</span> و تاریخ بغداد ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢١</span> و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٧</span> و تنقیح المقال ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٩</span> و اعیان الشیعة ج <span class=\"hlight\" dir=\"rtl\">٢٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٧</span> و <span class=\"hlight\" dir=\"rtl\">٢٦٣</span>).<br></font></div>'),
(185618, 'علوی بغدادی', '<span class=\"hlight\">علوی بغدادی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ب َ ]</font></b> (اِخ ) جعفربن محمدبن جعفربن حسن بن جعفربن حسن بن حسن بن علی بن ابی طالب، مکنی به ابوعبداﷲ. در سال <span class=\"hlight\" dir=\"rtl\">٢٢٤</span> هَ . ق . در سامره متولد شده و در ذی قعده ٔ <span class=\"hlight\" dir=\"rtl\">٣٠٨</span> وفات کرد. وی از تاریخ نویسان است و او راست : التاریخ العلوی و الصخرة و البئر. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span> از اعیان الشیعة ج <span class=\"hlight\" dir=\"rtl\">١٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٥</span> و <span class=\"hlight\" dir=\"rtl\">١٢٧</span> و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٩</span>).<br></font></div>'),
(185619, 'علوی تعزی', '<span class=\"hlight\">علوی تعزی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِت َ ع ِزْ زی ]</font></b> (اِخ ) سلیمان بن ابراهیم بن عمر علوی تعزی یمنی، مکنی به ابوالربیع و ملقب به نفیس الدین . وی محدث و صوفی است که در سال <span class=\"hlight\" dir=\"rtl\">٨٢٥</span> هَ . ق . در تعز از شهرهای یمن فوت کرد (در ایضاح المکنون سال وفات وی <span class=\"hlight\" dir=\"rtl\">٨١٥</span> ذکر شده است ). او راست : کتاب اربعین، در حدیث و ارشادالسالکین، در تصوف . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٢</span> از فهرست الفهارس ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٧</span> و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦١</span>).<br></font></div>'),
(185620, 'علوی حبشی', '<span class=\"hlight\">علوی حبشی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ح َ ب َ ]</font></b> (اِخ ) احمدبن زین بن علوی بن احمد. وی از متصوفه ٔ حضرموت است که در سال <span class=\"hlight\" dir=\"rtl\">١٠٦٩</span> هَ . ق . در شهر غرفة متولد شد. سپس در دیگر بلاد حضرموت شروع به سیر و سیاحت کرد تا در سال <span class=\"hlight\" dir=\"rtl\">١١٤٥</span> هَ . ق . در ناحیه ٔ راشد درگذشت . او راست : السفینة الکبری، در بیست مجلد. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٨</span> از اعلام زرکلی و فهرست الخدیویه ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٨</span> و معجم المطبوعات ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٤</span> و <span class=\"hlight\" dir=\"rtl\">١١٥</span>).<br></font></div>'),
(185621, 'علوی حسنی', '<span class=\"hlight\">علوی حسنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ح َ س َ ]</font></b> (اِخ ) حسین بن محمدبن عبداﷲ، مکنی به ابوعلی . رجوع به حسین حسنی شود.<br></font></div>'),
(185622, 'علوی حسنی', '<span class=\"hlight\">علوی حسنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َی ِ ح َ س َ ]</font></b> (اِخ ) عبدالسلام بن عمر، مکنی به ابومحمد (متوفی در <span class=\"hlight\" dir=\"rtl\">١٣٥٠</span> هَ . ق .). او را فهرستی است . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span> از دلیل مؤرخ المغرب ص <span class=\"hlight\" dir=\"rtl\">٣٦٧</span>).<br></font></div>'),
(185623, 'علوی حسنی', '<span class=\"hlight\">علوی حسنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ح َ س َ ]</font></b> (اِخ ) عبدالسلام الضریربن سلطان محمدبن عبداﷲبن اسماعیل علوی حسنی، مکنی به ابومحمد (متوفی در <span class=\"hlight\" dir=\"rtl\">١٢٢٨</span> هَ . ق .). او راست : درة السلوک و اقتطاف الازهار من حدائق الافکار. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> از اخبار مکناس ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٧</span> و دلیل مؤرخ المغرب ص <span class=\"hlight\" dir=\"rtl\">١٥٦</span>).<br></font></div>'),
(185624, 'علوی حسنی', '<span class=\"hlight\">علوی حسنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ح َ س َ ]</font></b> (اِخ ) علی بن عمر علوی طولقی جزائری حسنی خلوتی مالکی . رجوع به علوی طولقی شود.<br></font></div>'),
(185625, 'علوی حسنی', '<span class=\"hlight\">علوی حسنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ح َ س َ ]</font></b> (اِخ ) یحیی بن قاسم بن عمربن علی علوی حسنی یمانی صنعانی، ملقب به عزالدین . رجوع به علوی یمانی شود.<br></font></div>'),
(185626, 'علوی حسنی', '<span class=\"hlight\">علوی حسنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ح َ س َ ]</font></b> (اِخ ) قریه ای است درراه سلطان آباد به اصفهان . (یادداشت مرحوم دهخدا).<br></font></div>'),
(185627, 'علوی حسینی', '<span class=\"hlight\">علوی حسینی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ح ُ س َ ]</font></b> (اِخ ) ناصربن رضابن محمدبن عبداﷲ علوی حسینی، مکنی به ابوابراهیم . فقیه و محدث شیعی در قرن پنجم هجری بود. او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- کتابی در ادعیه ٔ زین العابدین . <span class=\"hlight\" dir=\"rtl\">٢</span>- کتابی شامل مکاتبات وی با یکی از فضلا. <span class=\"hlight\" dir=\"rtl\">٣</span>- کتابی در مناقب آل رسول . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">١٣</span> ص <span class=\"hlight\" dir=\"rtl\">٧٠</span> از اعلام الشیعة و روضات الجنات ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٨</span> و فوائد الرضویة ص <span class=\"hlight\" dir=\"rtl\">٦٩١</span>). و نیز رجوع به ابوابراهیم شود.<br></font></div>'),
(185628, 'علوی حسینی', '<span class=\"hlight\">علوی حسینی .</span> <font color=\"DarkGreen\"><b>[ع َ ل َ ی ِ ح ُ س َ ]</font></b> (اِخ ) حسن بن محمدبن یحیی بن حسن بن جعفر. نسابة. رجوع به علوی بغدادی (حسن بن ...) شود.<br></font></div>'),
(185629, 'علوی حسینی', '<span class=\"hlight\">علوی حسینی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ح ُ س َ ]</font></b> (اِخ ) طاهربن حسین بن طاهربن محمد حسینی علوی . وی فقیه بود و در دولت کثیریة در حضرموت منصب امامت داشت . در شهر تریم در<span class=\"hlight\" dir=\"rtl\">٤</span> شعبان سال <span class=\"hlight\" dir=\"rtl\">١١٨٤</span> هَ . ق . متولد شد و در شهر مسیلة بسال <span class=\"hlight\" dir=\"rtl\">١٢٤١</span> هَ . ق . درگذشت و در سال <span class=\"hlight\" dir=\"rtl\">١٢٢٠</span> هَ . ق . با وی برای امامت بیعت شد. او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- اتحاف النبیل بشرح حدیث جبریل . <span class=\"hlight\" dir=\"rtl\">٢</span>- کفایة الخایض فی علم الفرائض . <span class=\"hlight\" dir=\"rtl\">٣</span>- مجموعه ٔ فتاوی . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤</span> از تاریخ دولت کثیریة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span> و <span class=\"hlight\" dir=\"rtl\">١٥١</span> و اعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٩</span>).<br></font></div>'),
(185630, 'علوی حسینی', '<span class=\"hlight\">علوی حسینی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ح ُ س َ ]</font></b> (اِخ ) محمدبن ظفربن محمدبن احمد علوی حسینی، مکنی به ابوالحسن . ادیب و نحوی و فقیه و متکلم و محدث . وی رحالة نیز بود. در <span class=\"hlight\" dir=\"rtl\">٤٠٣</span> هَ . ق . درگذشت . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">١٠</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span> از بغیة الوعاة سیوطی ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>).<br></font></div>'),
(185631, 'علوی حضرمی', '<span class=\"hlight\">علوی حضرمی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ح َ رَ ]</font></b> (اِخ ) محمدبن احمدبن عمربن یحیی . لغوی و نحوی . وی از اهل حضرموت بود که به مصر نیز سفر کرد. به سال <span class=\"hlight\" dir=\"rtl\">١٣٥٥</span> هَ . ق . درگذشت . او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- الجموع قیاسیتها و سماعیتها. <span class=\"hlight\" dir=\"rtl\">٢</span>- الدخیل . <span class=\"hlight\" dir=\"rtl\">٣</span>- شرح مغنی اللبیب، در چهار مجلد. <span class=\"hlight\" dir=\"rtl\">٤</span>- الفصیح من الفاظ العامة. <span class=\"hlight\" dir=\"rtl\">٥</span>- المترادفات . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٥</span> از اعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٨</span>).<br></font></div>'),
(185632, 'علوی حنفی', '<span class=\"hlight\">علوی حنفی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ح َ ن َ ]</font></b> (اِخ ) عبدالرحمان بن محمدبن یوسف بن عمربن علی بن ابی بکر علوی زبیدی یمانی حنفی، ملقب به وجیه الدین . رجوع به علوی زبیدی شود.<br></font></div>'),
(185633, 'علوی حنفی', '<span class=\"hlight\">علوی حنفی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ح َ ن َ ]</font></b> (اِخ ) علی بن عبداﷲبن احمد علوی حنفی . وی ادیب بود و در سال <span class=\"hlight\" dir=\"rtl\">١١٧٣</span> هَ . ق . در مصر متولد شد و به سال <span class=\"hlight\" dir=\"rtl\">١١٩٨</span> هَ . ق . درگذشت .او راست : اشارات التحقیق الفیضیة الی خبایا القصیدةالزریقیة، در شرح قصیده ٔ ابن زریق کاتب بغدادی . (ازمعجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٩</span> از عجائب الاَّثار ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩٦</span>).<br></font></div>'),
(185634, 'علوی حنفی', '<span class=\"hlight\">علوی حنفی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ح َ ن َ ]</font></b> (اِخ ) عمربن علی بن ابی بکر علوی یمنی حنفی . رجوع به علی یمنی شود.<br></font></div>'),
(185635, 'علوی خلوتی', '<span class=\"hlight\">علوی خلوتی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ خ َل ْ وَ ]</font></b> (اِخ ) علی بن عثمان بن علی بن عمر علوی طولقی جزائری حسنی خلوتی مالکی . رجوع به علوی طولقی شود.<br></font></div>'),
(185636, 'علوی دامغانی', '<span class=\"hlight\">علوی دامغانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ]</font></b> (اِخ ) عبدالصمدبن عبداﷲ علوی دامغانی، ملقب به شمس الدین . از متکلمین بود. او راست : الجوهرة الخالصة عن الشوائب فی العقائدالمتقدمة علی جمیع المذاهب، که در سال <span class=\"hlight\" dir=\"rtl\">٩٦٧</span> هَ . ق . آن را تمام کرده است . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٥</span> ازایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨٥</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٧٤</span>).<br></font></div>'),
(185637, 'علوی دیری', '<span class=\"hlight\">علوی دیری .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ دَ ]</font></b> (اِخ ) منجمی است از اهالی دیرالبلاص که یکی از قرای صعید مصر است . وی در دیرالبلاص مسکن داشت و به استخراج تقویم و تسییر موالید مشغول بود. وفاتش را ابن قفطی در حدود سال <span class=\"hlight\" dir=\"rtl\">٥٩٥</span> هَ . ق . ذکر کرده است . (از گاهنامه ٔ سیدجلال الدین طهرانی، سال <span class=\"hlight\" dir=\"rtl\">١٣١٠</span> هَ . ش . ص <span class=\"hlight\" dir=\"rtl\">٧٧</span>). و نیز رجوع به تاریخ الحکماء قفطی چ لایپزیک ص <span class=\"hlight\" dir=\"rtl\">٢٥١</span> شود.<br></font></div>'),
(185638, 'علوی زبیدی', '<span class=\"hlight\">علوی زبیدی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ زَ ]</font></b> (اِخ ) عبدالرحمان بن ابراهیم بن اسماعیل بن عبداﷲبن عبدالرحمان بن محمدبن یوسف علوی یمانی زبیدی، ملقب به وجیه الدین . وی شاعری بود که در سال <span class=\"hlight\" dir=\"rtl\">٨٦٠</span> هَ . ق . متولد شد و در حدود <span class=\"hlight\" dir=\"rtl\">٩٢٠</span> درگذشت . او راست : الجواهر الرفیع و وجه المعانی فی معرفة انواع البدیع. و نیز دیوان شعری دارد. (ازمعجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span> از هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٤٤</span>).<br></font></div>'),
(185639, 'علوی زبیدی', '<span class=\"hlight\">علوی زبیدی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َی ِ زَ ]</font></b> (اِخ ) عبدالرحمان بن محمدبن محمدبن یوسف بن عمربن علی بن ابی بکر علوی زبیدی یمانی حنفی، ملقب به وجیه الدین . وی فقیه و ادیب بود و در نظم و نثر نیز دست داشت . در خدمات سلطانی ترقی کرد و زمانی نیز در عدن بازداشت شد و پس از رهایی، مدرسه ای در زبید بساخت .او در <span class=\"hlight\" dir=\"rtl\">٧٤٨</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">٨٠٣</span> یا <span class=\"hlight\" dir=\"rtl\">٨٠٤</span> درگذشت . او راست : بدیعیة، و شرح آن . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٥</span>ص <span class=\"hlight\" dir=\"rtl\">١٩٣</span> از الضوء اللامع ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٣</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٢٣٤</span>).<br></font></div>'),
(185640, 'علوی زیدی', '<span class=\"hlight\">علوی زیدی .</span> <font color=\"DarkGreen\"><b>[ ع َ ی ِ زَ ]</font></b> (اِخ ) حسن بن علی بن داود علوی صنعانی مؤیدی زیدی، ملقب به الناصر لدین اﷲ. وی از علمای زیدیه بود که در سال <span class=\"hlight\" dir=\"rtl\">١٠٢٤</span> هَ . ق . درگذشت : او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- أسنی العقائد فی أشرف المطالب وأزلف المقاصد. <span class=\"hlight\" dir=\"rtl\">٢</span>- ریاضة الافکار و نزهة الابصار فی کشف معانی مقدمة الازهار. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٤</span> از البدرالطالع ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩١</span>).<br></font></div>'),
(185641, 'علوی زیدی', '<span class=\"hlight\">علوی زیدی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ زَ ]</font></b> (اِخ ) حسن بن محمدبن احمدبن یحیی یمنی . رجوع به علوی یمنی شود.<br></font></div>'),
(185642, 'علوی سبزواری', '<span class=\"hlight\">علوی سبزواری .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ س َ زِ ]</font></b> (اِخ ) میرزا حسین بن میرزا محسن . فقیه و محدث و متکلم و شاعر. از شاگردان فاضل اردکانی و میرزا محمدحسن شیرازی بود. و معقول را نزد حاج ملا هادی سبزواری آموخت . و در <span class=\"hlight\" dir=\"rtl\">٢٣</span> شوال سال <span class=\"hlight\" dir=\"rtl\">١٣٢٥</span> هَ . ق . در سن <span class=\"hlight\" dir=\"rtl\">٨٤</span> سالگی درگذشت . او راست : الارجوزة فی الفلسفة العالیة، که مطلع آن چنین است :<br>سبحان من ألهم أسرار الحکم <br>لنفس الانسان وأبدع العلم .<br>(از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span> از الذریعة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩١</span>).<br></font></div>'),
(185643, 'علوی سقاف', '<span class=\"hlight\">علوی سقاف .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ س َق ْ قا ]</font></b> (اِخ ) ابن سیداحمدبن عبدالرحمان سقاف شافعی، بزرگ سادات مکه (متوفی به سال <span class=\"hlight\" dir=\"rtl\">١٠٨٠</span> هَ . ق .). او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- علاج الامراض الردیة بشرح الوصیة الحدادیة. <span class=\"hlight\" dir=\"rtl\">٢</span>- فتح العلوم باحکام السلام . <span class=\"hlight\" dir=\"rtl\">٣</span>- الفوائد المکیة فیما یحتاجه طلبة الشافعیة. <span class=\"hlight\" dir=\"rtl\">٤</span>-قمع الشهوة عن تناول التنباک و الکفتة و القاة و القهوة. <span class=\"hlight\" dir=\"rtl\">٥</span>- القوافل الملیة فی الفوائد الکلیة. <span class=\"hlight\" dir=\"rtl\">٦</span>- القول الجامع المتین فی بعض المهم من حقوق اخواننا المسلمین . <span class=\"hlight\" dir=\"rtl\">٧</span>- القول الجامع النجیح فی احکام صلاة التسابیح .<span class=\"hlight\" dir=\"rtl\">٨</span>- الکواکب الاجوج بأحکام الملائکة و الجن و الشیاطین و یأجوج و مأجوج . (از هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦٧</span>).<br></font></div>'),
(185644, 'علوی شافعی', '<span class=\"hlight\">علوی شافعی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ف ِ ]</font></b> (اِخ ) علوی بن سیداحمدبن عبدالرحمان سقاف شافعی . رجوع به علوی سقاف شود.<br></font></div>'),
(185645, 'علوی شریف', '<span class=\"hlight\">علوی شریف .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ش َ ]</font></b> (اِخ ) محمدبن حسین بن عبیداﷲبن حسین علوی شریف، مکنی به ابوعبداﷲ. وی ادیب و شاعر و خطیب بود که در جمادی الاَّخره ٔ <span class=\"hlight\" dir=\"rtl\">٤٠٨</span> هَ . ق . درگذشت . در دمشق عهده دار امر قضاء و نیز نقابت اشراف بود. وی را دیوان شعری است . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٤</span> از الوافی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٧</span> و قضاة دمشق ص <span class=\"hlight\" dir=\"rtl\">٣٩</span>).<br></font></div>'),
(185646, 'علوی صنعانی', '<span class=\"hlight\">علوی صنعانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ص َ ]</font></b> (اِخ ) یحیی بن قاسم بن عمربن علی علوی حسنی یمانی صنعانی، ملقب به عزالدین . رجوع به علوی یمانی شود.<br></font></div>'),
(185647, 'علوی صنعانی', '<span class=\"hlight\">علوی صنعانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ص َ ]</font></b> (اِخ ) حسن بن علی بن داود مؤیدی زیدی، ملقب به الناصر لدین اﷲ. رجوع به علوی زیدی شود.<br></font></div>'),
(185648, 'علوی طبری', '<span class=\"hlight\">علوی طبری .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َی ِ طَ ب َ ]</font></b> (اِخ ) حسن بن حمزةبن علی بن عبداﷲبن محمدبن حسن بن حسین علوی مرعشی . رجوع به علوی مرعشی شود.<br></font></div>'),
(185649, 'علوی طولقی', '<span class=\"hlight\">علوی طولقی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ طَ ل َ ]</font></b> (اِخ ) علی بن عثمان بن علی بن عمر علوی طولقی جزائری حسنی خلوتی مالکی . وی از متصوفه بود و بسال <span class=\"hlight\" dir=\"rtl\">١٣١٦</span> هَ . ق . درگذشت . او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- منهج الحقیقة فی الزهد و التزوّد. <span class=\"hlight\" dir=\"rtl\">٢</span>- النبذة المنیفة. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٧</span> ازهدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٧٨</span> و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦١٨</span>).<br></font></div>'),
(185650, 'علوی مالکی', '<span class=\"hlight\">علوی مالکی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َی ِ ل ِ ]</font></b> (اِخ ) علی بن عثمان بن علی بن عمر علوی طولقی جزائری حسنی خلوتی مالکی . رجوع به علوی طولقی شود.<br></font></div>'),
(185651, 'علوی محمدی', '<span class=\"hlight\">علوی محمدی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ م ُ ح َم ْ م َ ]</font></b> (اِخ ) عبداﷲبن علی بن ابی المحاسن بن سعدبن مهدی علوی محمدی، ملقب به اصیل الدین . وی محدث بود و در <span class=\"hlight\" dir=\"rtl\">٧٨٥</span> هَ . ق . درگذشت . او راست : مفاتیح المهدی، در احکام و حدیث . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٩٢</span> از شدالازار ص <span class=\"hlight\" dir=\"rtl\">٣٢٥</span> و <span class=\"hlight\" dir=\"rtl\">٣٢٩</span>).<br></font></div>'),
(185652, 'علوی مدنی', '<span class=\"hlight\">علوی مدنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ م َ دَ ]</font></b> (اِخ ) یکی از مردم مدینه به عهد الحاکم بامر اﷲ اسماعیلی، ششمین خلیفه ٔ بنی فاطمه ٔ مغرب بود. و داستان او در تاریخ گزیده چنین آمده است : قاضی احمد دامغانی در کتاب «استظهار» آورده است که حاکم جمعی را از مصر بفرستاد و علوی مدنی را بفریفت، تا در خانه ٔ او به شب نقب میزدند تا روضه ٔ رسول اﷲ صلی اﷲ علیه و سلم، و میخواستند که ابوبکر و عمر رضی اﷲ عنهما از روضه ٔ حضرت رسول بیرون آورند. در آن روزها در مدینه گردی و تاریکیی و باد و صاعقه ای عظیم پیدا شد. همه ٔ خلق بترسیدند و در توبه و انابت کوشیدند، و در حرم رسول علیه الصلاة و السلام گریختند. ساکن نمیشد. علوی مدنی این حال با حاکم مدینه بگفت . حاکم مدینه آن جماعت را بگرفت و سیاست کرد. آن هوا خوش شد. و این حال از کرامات ابوبکر و عمراست بعدِ چهارصد سال . (تاریخ گزیده چ لندن ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥١٢</span>). و نیز رجوع به نزهة القلوب چ دبیرسیاقی ص <span class=\"hlight\" dir=\"rtl\">١٤</span> شود.<br></font></div>'),
(185653, 'علوی مدنی', '<span class=\"hlight\">علوی مدنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ م َ دَ ]</font></b> (اِخ ) شخص نابینائی بود که به نوشته ٔ تاریخ گزیده در عهد سلطان ملکشاه، وقتی احمدبن عبدالملک عطاش اسماعیلی طغیان کرد، وی در اصفهان به کمک ملاحده مردم را می ربود، و سرانجام نقشه ٔ اوفاش شد و به دست مردم کشته شد. رجوع به تاریخ گزیده چ لندن ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥٥</span> و حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠٥</span> شود.<br></font></div>'),
(185654, 'علوی مرعشی', '<span class=\"hlight\">علوی مرعشی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َی ِ م ُ رَع ْ ع َ ]</font></b> (اِخ ) حسن بن حمزةبن علی بن عبداﷲبن محمدبن حسن بن حسین علوی طبری مرعشی، مکنی به ابومحمد. وی ادیب و فقیهی بود که به سال <span class=\"hlight\" dir=\"rtl\">٣٥٨</span> هَ . ق . درگذشت . نسبت او به جدش مرعّشی است و ربطی به مَرعش ندارد.او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- تباشیر الشریعة. <span class=\"hlight\" dir=\"rtl\">٢</span>- کتاب الدر. <span class=\"hlight\" dir=\"rtl\">٣</span>- کتاب المفتخر. <span class=\"hlight\" dir=\"rtl\">٤</span>- المبسوط فی عمل الیوم و اللیلة. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢١</span> از الفهرست طوسی ص <span class=\"hlight\" dir=\"rtl\">٥٢</span> و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">١</span> و <span class=\"hlight\" dir=\"rtl\">٢</span> و منهج المقال ص <span class=\"hlight\" dir=\"rtl\">٩٨</span> و اعیان الشیعة).<br></font></div>'),
(185655, 'علوی مهدی', '<span class=\"hlight\">علوی مهدی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِم َ ]</font></b> (اِخ ) حاکم قلعه ٔ الموت از جانب سلطان ملکشاه .داستان وی با حسن صباح در جامع التواریخ چنین آمده است : ... بدان ایام امیر الموت علوی مهدی نام داشت از قبل سلطان ملکشاه، و حسین قاینی، علوی را دعوت میکرد. قومی در الموت دعوت او قبول کردند. و علوی به زبان میگفت قبول کردم، اما دلش با زبان راست نبود. و خواست با کسانی که دعوت قبول کرده بودند خیانت کند. رفیقان به زیر میفرستاد و به آخر در دز دربست، و گفت این ازآن ِ سلطان است . تا بعد از گفت وگوی بسیار ایشان را در دز راه داد. و بعد از آن به سخن او به شیب نمیرفتند. و سیدنا، ابوالقاسم را به شاه کوه فرستاد، و دهخدای خسروشاه از جناشک هم بیامد. و سیدنا از قزوین به راه بیره و انبه به دیلمان آمد و از سلسلکویه اشکور به اندجرود که متصل الموت است در رجب سنه ٔ ثلاث وثمانین و اربعمائة (<span class=\"hlight\" dir=\"rtl\">٤٨٣</span>)، و یکچند آنجا مقام کرد، واز وفور زهد و تقوی خلقی انبوه صید او شدند و دعوت او قبول کردند. تا شب چهارشنبه ٔ ششم رجب سنه ٔ ثلاث و ثمانین و اربعمائة (<span class=\"hlight\" dir=\"rtl\">٤٨٣</span>) بر در الموت آمد و نام خود به دهخدا منسوب کرده، پوشیده به آنجا رفت . و آنجا رابه ایام متقدم «اله اموت » گفتندی یعنی آشیانه ٔ عقاب .و از نوادر اتفاقات عجیب و غریب، حروف اله اموت به حساب هند، تاریخ سال صعود اوست بر الموت، که نهان او را به قلعه بردند. چون مهدی علوی بر حال او وقوف یافت و اختیاری به دست نداشت او را اجازت دادند برود، وبهای قلعه سه هزار دینار زر به حاکم گردکوه و دامغان، رئیس مظفر مستوفی نوشت که در خفیه دعوت او قبول کرده بود. و حسن از غایت زهد و تقوی رقعه های نیک موجز و مختصر نوشتی بر این جمله که نسخه ٔ این برات است . وسطور مدور نوشتی که «رئیس مظفر حفظه اﷲ مبلغ سه هزاردینار بهای الموت به مهدی علوی رساند، علی النبی المصطفی و آله السلام و حسبنا اﷲ و نعم الوکیل ». علوی برات بستد و این اندیشید که رئیس مظفر مردی بزرگست، نایب امیرداد حبشی ابن آلتوق تاق، به رقعه ٔ این مرد خامل چگونه چیزی به من دهد.بعد از مدتی مقل الحال به دامغان افتاد، آن برات امتحان را پیش رئیس مظفر برد، درحال برات بستد و خط ببوسید و زر داد. (فصلی از جامع التواریخ چ دبیرسیاقی ص <span class=\"hlight\" dir=\"rtl\">٩</span>). و نیز رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٦٥</span> شود.<br></font></div>'),
(185656, 'علوی مکی', '<span class=\"hlight\">علوی مکی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ م َک ْ کی ]</font></b> (اِخ ) محمدطیب بن محمدصالح بن محمد عبداﷲ علوی مکی . وی در مکه متولد شد و سپس به شهر «لامو» در مشرق افریقای انگلستان سفر کرد و آنگاه به قصد تجارت به مسقط رفت . و پس از آن به مکه بازگشت و نزد پدر خود صرف و نحو و بلاغت و ادب آموخت، بهند رفت و در شهر بمبئی به تجارت پرداخت . سپس به شهر رامفور سفر کرد و در آنجا در مدرسه ٔعالی دولتی به تدریس پرداخت . و در همین شهر در <span class=\"hlight\" dir=\"rtl\">٨</span> ذیقعده ٔ <span class=\"hlight\" dir=\"rtl\">١٣٣٤</span> هَ . ق . درگذشت . او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- الاحاجی الحامدیة، در نحو. <span class=\"hlight\" dir=\"rtl\">٢</span>- حاشیه بر شمسیة، در منطق . <span class=\"hlight\" dir=\"rtl\">٣</span>- حاشیه بر مفصل زمخشری . <span class=\"hlight\" dir=\"rtl\">٤</span>- شرح لامیةالعرب . <span class=\"hlight\" dir=\"rtl\">٥</span>- المکالمة فی اللغة العربیة الدارجة بمکة المکرمة. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">١٠</span> ص <span class=\"hlight\" dir=\"rtl\">١١٠</span> از الحج عبدالوهاب دهلوی ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٢١</span>).<br></font></div>'),
(185657, 'علوی وردی', '<span class=\"hlight\">علوی وردی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ؟ ]</font></b> (اِخ ) از ادیبان متقدم در اصفهان بود. (از محاسن اصفهان مافروخی ص <span class=\"hlight\" dir=\"rtl\">٣٢</span>).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(185658, 'علوی کاشانی', '<span class=\"hlight\">علوی کاشانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ]</font></b> (اِخ ) میر محمدطاهر. از شعرای ایران در عهد شاه سلیمان صفوی است . وی ابتدا در اصفهان میزیست و سپس به کشمیر رفت و در سال <span class=\"hlight\" dir=\"rtl\">١١٣٦</span> هَ .ق . در آنجا درگذشت . منظومه ای بنام «حداد و حلاج »، و نیز دیوانی مرتب دارد. و ظاهراً «علوی » تخلص اوست . (از ریحانة الادب ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span> از قاموس الاعلام ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٧٥</span>).<br></font></div>'),
(185659, 'علوی کلا', '<span class=\"hlight\">علوی کلا.</span> <font color=\"DarkGreen\"><b>[ ع ُل ْ ک َ ]</font></b> (اِخ ) دهی است از دهستان دابو از بخش مرکزی شهرستان آمل واقع در <span class=\"hlight\" dir=\"rtl\">٩</span> هزارگزی شمال آمل و در کنار رودخانه ٔ هراز. ناحیه ایست دشت و دارای آب و هوای معتدل مرطوب مالاریایی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٥٠٥</span> تن است . آب آن از رودخانه ٔ هراز تأمین میشود. محصول آن برنج، کنف، مختصر نیشکر و صیفی است . اهالی آن به زراعت اشتغال دارند. این ده دارای دبستان و دو باب دکان است . راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(185660, 'علوی کلا', '<span class=\"hlight\">علوی کلا.</span> <font color=\"DarkGreen\"><b>[ ع ُل ْ ک َ ]</font></b> (اِخ ) دهی است از دهستان قشلاق کلارستان بخش چالوس شهرستان نوشهر واقع در <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی باختر چالوس و یک هزارگزی باختر راه شوسه ٔ چالوس به شهسوار. ناحیه ایست دشت و دارای آب و هوای معتدل مرطوب مالاریائی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن است . آب آن از رودخانه ٔ چالوس تأمین میشود. محصول آن برنج و مختصر مرکبات و لبنیات است . اهالی به زراعت اشتغال دارند. راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(185661, 'علوی کلا', '<span class=\"hlight\">علوی کلا.</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ک َ ]</font></b> (اِخ ) دهی است از دهستان علوی کلا از بخش مرکزی شهرستان نوشهر واقعدر <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی باختر المده و یک هزارگزی جنوب راه شوسه ٔ المده به نوشهر. ناحیه ایست دشت و دارای آب و هوای معتدل مرطوب مالاریائی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٨٠</span> تن است . آب آن از رودخانه ٔ کچرود تأمین میشود. محصول آن برنج و مختصر غلات و صیفی است . اهالی به زراعت اشتغال دارند. راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(185662, 'علوی کلا', '<span class=\"hlight\">علوی کلا.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ک َ ]</font></b> (اِخ ) یکی از دهستانهای دوازده گانه ٔ کجور شهرستان نوشهر است، واقع در ساحل دریا، بین دهستانهای کچرود و گل رودپی . این دهستان از <span class=\"hlight\" dir=\"rtl\">٩</span> آبادی تشکیل شده و جمعیت آن در حدود <span class=\"hlight\" dir=\"rtl\">١٨٠٠</span> تن است . قرای مهم قشلاقی آن علوی کلا و منوچهرکلا میباشد. محصول آن برنج است . آب آن از رودخانه ٔ کچرود تأمین میشود. دو آبادی فیروزکلای بالا و پائین در حدود کجور، محل ییلاقی این دهستان محسوب میشود. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>). در جغرافیای سیاسی کیهان (ص <span class=\"hlight\" dir=\"rtl\">٣٠٠</span>) چنین آمده است : علوی کلا از بلوکات ناحیه ٔ کجور در مازندران، مرکز آن عُلویکلا دارای <span class=\"hlight\" dir=\"rtl\">٩</span> قریه و <span class=\"hlight\" dir=\"rtl\">٧٢٠</span> تن جمعیت .<br></font></div>'),
(185663, 'علوی کلا', '<span class=\"hlight\">علوی کلا.</span> <font color=\"DarkGreen\"><b>[ ع َل ْ ک َ ]</font></b> (اِخ ) دهی است از دهستان کلیجان رستاق بخش مرکزی شهرستان ساری واقع در <span class=\"hlight\" dir=\"rtl\">١٧</span> هزارگزی جنوب خاوری ساری مقابل هولار. ناحیه ای است کوهستانی و جنگلی دارای آب و هوای معتدل و مرطوب و مالاریایی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٢٥</span> تن است . آب آن از رودخانه ٔ تجن تأمین میشود. محصول آن برنج و غلات است . اهالی به زراعت اشتغال دارند. راه آن مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br></font></div>'),
(185664, 'علوی یمانی', '<span class=\"hlight\">علوی یمانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ی َ ]</font></b> (اِخ ) عبدالرحمان بن محمدبن یوسف بن عمربن علی بن ابی بکر علوی زبیدی یمانی حنفی، ملقب به وجیه الدین . رجوع به علوی زبیدی شود.<br></font></div>'),
(185665, 'علوی یمانی', '<span class=\"hlight\">علوی یمانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ی َ ]</font></b> (اِخ ) عبدالرحمان بن ابراهیم بن اسماعیل بن عبداﷲبن عبدالرحمان بن محمدبن یوسف علوی یمانی زبیدی . رجوع به علوی زبیدی شود.<br></font></div>'),
(185666, 'علوی یمانی', '<span class=\"hlight\">علوی یمانی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِی َ ]</font></b> (اِخ ) یحیی بن قاسم بن عمر بن علوی حسنی یمانی صنعانی، ملقب به عزالدین . نحوی و مفسر است که در سال <span class=\"hlight\" dir=\"rtl\">٦٨٠</span> هَ . ق . متولد شد. وی به بغداد و شام و خراسان سفر کرد و در سال <span class=\"hlight\" dir=\"rtl\">٧٥٠</span> درگذشت . او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- تحفة الاشراف فی کشف غوامض الکشاف، درتفسیر. <span class=\"hlight\" dir=\"rtl\">٢</span>- دررالاصداف فی حل عقد الکشاف . <span class=\"hlight\" dir=\"rtl\">٣</span>- شرح لباب تاج الدین اسفرایینی، در نحو. و نیز او را اشعاری است . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">١٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٩</span> از بغیة الوغاة سیوطی ص <span class=\"hlight\" dir=\"rtl\">٤١٤</span> و البدر الطالع شوکانی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٠</span> و کشف الظنون و فهرست الخدیویة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٧</span> و نور عثمانیة کتبخانه ص <span class=\"hlight\" dir=\"rtl\">٣٣</span>و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٢٧</span> و الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span>).<br></font></div>'),
(185667, 'علوی یمنی', '<span class=\"hlight\">علوی یمنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ی َ م َ ]</font></b> (اِخ ) عمربن علی بن ابی بکر علوی یمنی حنفی، مکنی به ابوالخطاب . فقیه و ادیب و شاعر بود که در سال <span class=\"hlight\" dir=\"rtl\">٦٦٤</span> هَ . ق . متولد شد و در حدود <span class=\"hlight\" dir=\"rtl\">٧٠٣</span> در زبید درگذشت . او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- منتخب الفنون، درهفت مجلد. <span class=\"hlight\" dir=\"rtl\">٢</span>- نزهة الحضار و انس النظار، در ادب . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٩</span> از العقود اللؤلؤیة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٦</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">١٨٤٨</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٨٨</span>).<br></font></div>'),
(185668, 'علوی یمنی', '<span class=\"hlight\">علوی یمنی .</span> <font color=\"DarkGreen\"><b>[ع َ ل َ ی ِ ی َ م َ ]</font></b> (اِخ ) سلیمان بن ابراهیم بن عمر علوی تعزی یمنی . محدث و صوفی . رجوع به علوی تعزی شود.<br></font></div>'),
(185669, 'علوی یمنی', '<span class=\"hlight\">علوی یمنی .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ی ِ ی َم َ ]</font></b> (اِخ ) حسن بن محمدبن احمدبن یحیی یمنی زیدی . ازتاریخ نویسان بود که در سال <span class=\"hlight\" dir=\"rtl\">٦٧٠</span> هَ . ق . وفات کرد. او راست : انوار الیقین فی فضائل امیرالمؤمنین . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٥</span> از ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٧</span>).<br></font></div>'),
(185670, 'علویات', '<span class=\"hlight\">علویات .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ وی یا ]</font></b> (ع اِ) ج ِ علویة. رجوع به علویة شود.<br></font></div>'),
(185671, 'علویان', '<span class=\"hlight\">علویان .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) جمع فارسی عَلَوی . رجوع به علوی شود. سادات . (برهان قاطع) <span class=\"hlight\">:</span> امیر خواجه علی میکائیل را بخواند و گفت : رسولی می آید بساز با کوکبه ٔ بزرگ از اشراف علویان و قضاة و علما وفقها به استقبال روی . (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٢٨٨</span>). خلافت عباسیان را خللی که آید آن است که در زمین طبرستان ناجمی پیدا آید از علویان . (تاریخ بیهقی ص <span class=\"hlight\" dir=\"rtl\">٤٢٢</span>).<br></font></div>'),
(185672, 'علویان', '<span class=\"hlight\">علویان .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دهی است از دهستان سراجو از بخش مرکزی شهرستان مراغه واقع در <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی شمال خاوری راه شوسه ٔ مراغه به دهخوارقان . ناحیه ایست دامنه و دارای آب و هوای معتدل سالم . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٧٦٣</span> تن است . آب آن از صوفی چای تأمین میشود. محصول آن غلات، پنبه، چغندر، کشمش، نخود، زردآلو و بادام است . اهالی به زراعت اشتغال دارند و صنایع دستی آنها جاجیم بافی است . دارای راه ارابه رو است . (از فرهنگ جغرافیای ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(185673, 'علویان', '<span class=\"hlight\">علویان .</span> <font color=\"DarkGreen\"><b>[ ع ُل ْ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِل ْ ]</font></b> (اِ مرکب ) ج ِ عُلْوی و عِلْوی . رجوع به علوی شود. <BR><font color=\"Blue\">◄</font> کنایه از ملائکه و فرشتگان است . (برهان قاطع). ملایک . (غیاث ). <BR><font color=\"Blue\">◄</font> (اِخ ) سیارات، که زحل و مشتری و مریخ و آفتاب و زهره و عطارد و ماه است . (برهان ). کواکب . (غیاث اللغات ).<br></font></div>'),
(185674, 'علویان طبرستان', '<span class=\"hlight\">علویان طبرستان .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ن ِ طَ ب َ رِ ]</font></b> (اِخ ) نام شعبه ایست از ائمه ٔ علوی یا زیدی که در سعده ٔ یمن حکومت می کرده اند و خود را از فرزندان امام حسن (ع ) یا امام حسین (ع ) می دانستند. مدتها در شهرهای ساحلی بحر خزر یعنی دیلم و گیلان و طبرستان در ادعای امامت باقی ماندند و مدعی خلفای عباسی بغداد بودند، تا اینکه در سال <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> هَ . ق . موفق به تصرف طبرستان و تشکیل دولت و ضرب سکه شدند. و در حدود <span class=\"hlight\" dir=\"rtl\">٦٤</span> سال بر آنجا حکومت کردند و سرانجام به دست سامانیان و آل زیار منقرض شدند. کسانی که از علویان بر طبرستان حکومت کردند بترتیب عبارتند از: <span class=\"hlight\" dir=\"rtl\">١</span>- حسن بن زید، از <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> تا <span class=\"hlight\" dir=\"rtl\">٢٧٠</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">٢</span>- محمدبن زید، از <span class=\"hlight\" dir=\"rtl\">٢٧٠</span> تا <span class=\"hlight\" dir=\"rtl\">٢٨٧</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">٣</span>- حسن بن علی اطروش الناصر، از <span class=\"hlight\" dir=\"rtl\">٣٠١</span> تا <span class=\"hlight\" dir=\"rtl\">٣٠٤</span> هَ . ق . <span class=\"hlight\" dir=\"rtl\">٤</span>- حسن بن قاسم از <span class=\"hlight\" dir=\"rtl\">٣٠٤</span> تا <span class=\"hlight\" dir=\"rtl\">٣١٦</span> هَ . ق . و در بین سالهای <span class=\"hlight\" dir=\"rtl\">٢٨٧</span> تا <span class=\"hlight\" dir=\"rtl\">٣٠١</span> نیز حکومت سامانی بر این سرزمین مسلط بود. بعد از انقراض علویان، چند خاندان از آنها که رقیب یکدیگر نیز بودند تا مدتی در گیلان و دیلم حکومت داشتند. و یکی ازآنان که ابوالفضل جعفر الثائر فی اﷲ (؟) نام داشت بنام خود سکه نیز زد. (از طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">١١٤</span>). ونیز رجوع به تاریخ طبرستان ابن اسفندیار ص <span class=\"hlight\" dir=\"rtl\">٩٤</span> شود.<br></font></div>'),
(185675, 'علویة', '<span class=\"hlight\">علویة.</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ وی ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (از ع، ص نسبی ) تأنیث عِلوی . رجوع به عِلوی و عَلویة و عِلویین شود.<br>- <span class=\"hlight\">علم آثار علویه </span> ؛ علم به امطار و ریاح و رعود و بروق و شهب و نیازک و امثال آن، و آن یکی از اقسام علوم طبیعیه ٔ قدما باشد. (یادداشت مرحوم دهخدا).<br></font></div>'),
(185676, 'علویة', '<span class=\"hlight\">علویة.</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ وی ی َ ]</font></b> (ع ص نسبی ) مؤنث علوی ّ. (اقرب الموارد). رجوع به علوی شود. زنی که از اولادعلی بن ابی طالب (ع ) باشد. (از ناظم الاطباء). سیدة.<br></font></div>'),
(185677, 'علویجه', '<span class=\"hlight\">علویجه .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ج َ ]</font></b> (اِخ ) قصبه ایست از دهستان دهق بخش نجف آباد شهرستان اصفهان واقع در <span class=\"hlight\" dir=\"rtl\">٤٦</span> هزارگزی شمال باختری نجف آباد و متصل براه ماشین رو علویجه به تیران . ناحیه ایست جلگه و دارای آب و هوای معتدل و <span class=\"hlight\" dir=\"rtl\">٦٣٨٨</span> تن سکنه است . آب آن از قنات تأمین می شود. محصول آن غلات، حبوبات، انگور، سیب زمینی، هلو، توت، لبنیات، پشم، روغن، پنبه، بادام، کتیرا، گردو، زردآلو، صیفی و سیب است . اهالی آن به زراعت و گله داری اشتغال دارند. صنایع دستی زنان کرباس، کیش و قالی بافی است . راه آن اتومبیل رو است . دارای دبستان، پاسگاه ژاندارمری، زیارتگاه، گاراژ، و در حدود <span class=\"hlight\" dir=\"rtl\">٥٠</span> باب دکان است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(185678, 'علویحصب', '<span class=\"hlight\">علویحصب .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ وُ ی َ ص ِ ]</font></b> (اِخ ) روستاییست در یمن، که فاصله ٔ بین آن و قصر سموأل هشت فرسخ است . رجوع به یحصب شود. (از معجم البلدان ).<br></font></div>'),
(185679, 'علویق', '<span class=\"hlight\">علویق .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دهی است جزء دهستان کلیبر بخش کلیبر شهرستان اهر واقع در <span class=\"hlight\" dir=\"rtl\">٢١</span> هزارگزی جنوب کلیبر و <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی راه شوسه ٔ اهر به کلیبر. ناحیه ایست کوهستانی و دارای آب و هوای معتدل .سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">١٣٦</span> تن است . آب آن از چشمه تأمین میشود. محصول آن غلات است . اهالی به زراعت و گله داری اشتغال دارند و صنایع دستی آنها جاجیم بافی و گلیم بافی است . دارای راه مالرو است . (فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(185680, 'علویق', '<span class=\"hlight\">علویق .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) دهی است جزء دهستان اوزومدل بخش ورزقان شهرستان اهر واقع در <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی شمال باختری ورزقان و <span class=\"hlight\" dir=\"rtl\">٤</span> هزار و پانصد گزی راه ارابه رو تبریز به اهر. ناحیه ایست جلگه و دارای آب و هوای معتدل . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٧٧٤</span> تن است . آب آن از قنات تأمین میشود. محصول آن غلات و سیب زمینی است . اهالی به کشاورزی و گله داری اشتغال دارند و صنایع دستی زنان جاجیم بافی است . دارای راه مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br></font></div>'),
(185681, 'علویه', '<span class=\"hlight\">علویه .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ وی ی َ ]</font></b> (اِخ ) دهی است کوچک از دهستان ندوشن بخش خضرآباد شهرستان یزد واقع در <span class=\"hlight\" dir=\"rtl\">١٩</span> هزارگزی جنوب باختری خضرآباد و هزار و پانصدگزی راه ندوشن . ناحیه ایست کوهستانی دارای آب و هوای معتدل و مالاریائی . سکنه ٔ آن <span class=\"hlight\" dir=\"rtl\">٧٥</span> تن است . آب آن از قنات تأمین میشود. محصول آن غلات و شغل اهالی زراعت است . صنایع دستی زنان کرباس بافی است . راه آن فرعی میباشد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br></font></div>'),
(185682, 'علویه', '<span class=\"hlight\">علویه .</span> <font color=\"DarkGreen\"><b>[ ع ُل ْ وی ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (از ع، ص نسبی ) مونث عُلوی . رجوع به علوی شود.<br>- <span class=\"hlight\">جواهر علویه </span> ؛ ستارگان . (ناظم الاطباء).<br></font></div>'),
(185683, 'علویه', '<span class=\"hlight\">علویه .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ وی ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (ص نسبی ) مؤنث علوی، منسوب به علی، بمعنای لغوی کلمه که بلند و برتر است .<br>- <span class=\"hlight\">کواکب علویه </span> ؛ زحل و مشتری و مریخ . (از اقرب الموارد). اما در تداول فارسی زبانان ضبط کلمه، عِلْویة تأنیث عِلوی است . و کواکب عِلویه زحل و مشتری و مریخ دانسته شده اند. (ازیادداشت مرحوم دهخدا). و رجوع به کشاف اصطلاحات الفنون، و نیز رجوع به عِلویة و عِلویین شود.<br></font></div>'),
(185684, 'علویین', '<span class=\"hlight\">علویین .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ وی یی ]</font></b> (ص نسبی، اِ) ج ِ عِلوی . رجوع به علوی شود. <BR><font color=\"Blue\">◄</font> (اِخ ) زحل و مشتری و مریخ، ازآنرو که فلک این سه بالای آفتاب است . و رجوع به سفلیین شود.(یادداشت مرحوم دهخدا). و نیز رجوع به علویة شود.<br></font></div>'),
(185685, 'علویین', '<span class=\"hlight\">علویین .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ وی ی َی ْ ]</font></b> (ع ص نسبی، اِ) مثنای علوی ّ. رجوع به علوی شود. <BR><font color=\"Blue\">◄</font> (اِخ ) دو ستاره ٔ زحل و مشتری . (ازاقرب الموارد). عِلویَّین . (یادداشت مرحوم دهخدا).<br></font></div>'),
(185686, 'علویین', '<span class=\"hlight\">علویین .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ وی ی َی ْ ]</font></b> (ع ص نسبی، اِ) مثنای عِلوی . رجوع به علوی شود. <BR><font color=\"Blue\">◄</font> (اِخ ) زحل و مشتری . عَلَویین . (اقرب الموارد).<br>- <span class=\"hlight\">قران علویین </span> ؛ قران زحل و مشتری که بهر بیست سال یک بار باشد. (یادداشت مرحوم دهخدا، از مقدمه ٔ ابن خلدون ).<br></font></div>'),
(185687, 'علک', '<span class=\"hlight\">علک .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (ع مص ) خاییدن . (منتهی الارب ) (از اقرب الموارد). عِلک خاییدن . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> دندان ساییدن بر هم چندان که بانگ برآورد. گویند: علک نابیه . (منتهی الارب ) (از اقرب الموارد). دندان بر هم ساییدن .<br></font></div>'),
(185688, 'علک', '<span class=\"hlight\">علک .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (ع اِ) درختی است حجازی .(از اقرب الموارد). درختی است حجازی که شیر سطبر دارد، و گویند که آن را در زهر آمیزند. (منتهی الارب ).<br></font></div>'),
(185689, 'علک', '<span class=\"hlight\">علک .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (ع اِ) هر صمغی را گویند که آن را توان خایید، و بهترین وی علک رومی است که مصطکی باشد. (برهان ). هر صمغی که خاییده شود و سیلان نکند. (ناظم الاطباء) (از اقرب الموارد). چیزی است که قابل مضغ باشد و از هم نپاشد، مانند سقز و مصطکی . (مخزن الادویه ). صمغ صنوبر و ارزة و پسته و سرو و ینبوت و بطم . (منتهی الارب ). ج، أعلاک، و عُلوک <span class=\"hlight\">:</span> <br>صفرای مرا سود ندارد نلکا<br>درد سر من کجا نشاند علکا.<br> <font color=\"Red\">ابوالمؤید بلخی .</font><br>آبم که مرا هر خسی بیابد<br>علکم که مرا هر کسی بخاید.<br> <font color=\"Red\">مسعودسعد.</font><br>در میان خلایق چو علک، خاییده ٔ دهان ملامت شویم . (جهانگشای جوینی ).<br></font></div>'),
(185690, 'علک', '<span class=\"hlight\">علک .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ ]</font></b> (ع ص ) خوردنیی که در خاییدن سخت باشد. <BR><font color=\"Blue\">◄</font> لزج . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185691, 'علک الانباط', '<span class=\"hlight\">علک الانباط.</span> <font color=\"DarkGreen\"><b>[ ع ِ کُل ْ اَم ْ ]</font></b> (ع اِ مرکب ) رجوع به علک البطم شود. (مخزن الادویه ).<br></font></div>'),
(185692, 'علک البطم', '<span class=\"hlight\">علک البطم .</span> <font color=\"DarkGreen\"><b>[ ع ِ کُل ْ ب ُ ]</font></b> (ع اِ مرکب ) به فارسی سقز و به اصفهانی قندرون نامند. و آن صمغ درخت بطم است . در آخر دوم گرم و خشک و محلّل و ملطف و مدرّ بول و مقوی هاضمه، و به اتفاق حکمای یونان و روم در جمیع افعال بهتر از مصطکی است . و خوردن آن با عسل جهت زخمهای باطنی، و با سندروس و زرده ٔ تخم مرغ نیم برشته جهت شکستگی اعضاء بهتر از مومیایی است . و چون یک وقیه از آن را با دو وقیه پیه گرده ٔ بز مخلوط کرده و دو سه شب وقت خواب بخورند جهت خفقان و سرفه ٔ رطبی مفید است . و ضماد آن برای کجی ناخن و درد اعضا و شقاق مزمن مفید است، مخصوصاً اگر با قدری شنجرف آمیخته باشد.و تضمید علک البطم جهت تنقیه ٔ زخمها و گوشت آوردن و جذب خار و پیکان و رطوبات غایره از بدن، و با روغن زیتون جهت تحلیل ورمها و شکاف عضل و قوی کردن عصب نافع است . و خاییدن آن جهت بلغم دماغی و تحلیل رطوبت معده و پاک کردن حلق از اخلاط لزج مفید است . اما برای محرورین و گرم مزاجان مضر است، و دوای آن سکنجبین است .و گویند اعصاب را نیز مضر است و مصلح آن عسل است . (از تحفه ٔ حکیم مؤمن ) و نیز رجوع به صمغالبطم شود.<br></font></div>'),
(185693, 'علک خای', '<span class=\"hlight\">علک خای .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (نف مرکب ) آنکه علک خاید. <BR><font color=\"Blue\">◄</font> ژاژخا و هرزه لا. <BR><font color=\"Blue\">◄</font> ماده خر دندان بهم ساینده در دیدن خر نر <span class=\"hlight\">:</span> <br>ز خرسپوزی من علک خای گردد خر<br>نه کَه ْ خورد نه سبوس و نه جو نه آب و گیا.<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(185694, 'علک خاییدن', '<span class=\"hlight\">علک خاییدن .</span> <font color=\"DarkGreen\"><b>[ ع ِ دَ ]</font></b> (مص مرکب ) عَلک . (منتهی الارب ). صمغ خاییدن . <BR><font color=\"Blue\">◄</font> بیهوده گفتن . ژاژ خاییدن . هرزه لائیدن . هرزه دراییدن . رجوع به ژاژ خاییدن شود. <BR><font color=\"Blue\">◄</font> دندان بهم ساییدن خر ماده در دیدن خر نر <span class=\"hlight\">:</span> <br>گوید که علک خایم، خاید بلی چنانک <br>خایند علک ماده خران از خران غنگ .<br> <font color=\"Red\">سوزنی .</font><br>شعر ژاژیدن لهاشم توست <br>علک خاییدن لهاشم خر.<br><font color=\"Red\">سوزنی .</font><br></font></div>'),
(185695, 'علک رومی', '<span class=\"hlight\">علک رومی .</span> <font color=\"DarkGreen\"><b>[ ع ِ ک ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) همان مصطکی است . (مخزن الادویه ). رجوع به مصطکی شود.<br></font></div>'),
(185696, 'علک یابس', '<span class=\"hlight\">علک یابس .</span> <font color=\"DarkGreen\"><b>[ ع ِ ک ِ ب ِ ]</font></b> (ترکیب وصفی، اِ مرکب ) همان قلفونیا است . (مخزن الادویه ). رجوع به قلفونیا شود.<br></font></div>'),
(185697, 'علکات', '<span class=\"hlight\">علکات .</span> <font color=\"DarkGreen\"><b>[ ع َ ل ِ ]</font></b> (ع اِ) ج ِ عَلکة. (اقرب الموارد). دندانهای درشت و سخت . (منتهی الارب ).<br></font></div>'),
(185698, 'علکد', '<span class=\"hlight\">علکد.</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ]</font></b> (ع ص )شتر سخت که دارای گردن و پشت قوی باشد. سخت و قوی، و مذکر و مؤنث در آن یکسان است . <BR><font color=\"Blue\">◄</font> پیرزن با بانگ و فریاد و کم خیر. (از ذیل اقرب الموارد).<br></font></div>'),
(185699, 'علکد', '<span class=\"hlight\">علکد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ک ِ ]</font></b> (ع ص ) درشت و سطبر. (منتهی الارب ). غلیظ. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> پیره زن نیک زیرک . <BR><font color=\"Blue\">◄</font> زن کوتاه بالای آکنده گوشت خوار کم خیر. (از منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد درشت اندام سطبر. (منتهی الارب ).<br></font></div>'),
(185700, 'علکد', '<span class=\"hlight\">علکد.</span> <font color=\"DarkGreen\"><b>[ ع ِ ک َدد]</font></b> (ع اِ) پیه . (منتهی الارب ). شحم . (اقرب الموارد).<br></font></div>'),
(185701, 'علکد', '<span class=\"hlight\">علکد.</span> <font color=\"DarkGreen\"><b>[ ع ُ ک ُ ]</font></b> (ع ص )درشت و سطبر. (منتهی الارب ). غلیظ. (اقرب الموارد).<br></font></div>'),
(185702, 'علکد', '<span class=\"hlight\">علکد.</span> <font color=\"DarkGreen\"><b>[ ع ُ ل َ ک ِ ]</font></b> (ع ص ) غلیظ و سطبر. (ناظم الاطباء). غلیظ. (اقرب الموارد). <BR><font color=\"Blue\">◄</font> شیر دفزک شده و سطبر. (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185703, 'علکد', '<span class=\"hlight\">علکد.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (ع ص )درشت و سطبر. (منتهی الارب ). غلیظ. (اقرب الموارد).<br></font></div>'),
(185704, 'علکز', '<span class=\"hlight\">علکز.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ع ِ ک ِ ]</font></b> (ع ص ) مرد درشت اندام و سطبر و سخت . (منتهی الارب ) (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> مرد پرگوشت بزرگ جثه . (منتهی الارب ).<br></font></div>'),
(185705, 'علکس', '<span class=\"hlight\">علکس .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْ ل َ ]</font></b> (ع ص ) انبوه و بهم پیچیده : شَعر علکس ؛ کثیر متراکب . (اقرب الموارد).<br></font></div>'),
(185706, 'علکس', '<span class=\"hlight\">علکس .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (اِخ ) مردی است یمنی . (منتهی الارب ).<br></font></div>'),
(185707, 'علکسة', '<span class=\"hlight\">علکسة.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ س َ ]</font></b> (ع مص )جمع شدن : علکس البیض ؛ اجتمع. (ذیل اقرب الموارد).<br></font></div>'),
(185708, 'علکم', '<span class=\"hlight\">علکم .</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ ]</font></b> (ع ص ) درشت خلقت از شترو جز آن . (منتهی الارب ) (از اقرب الموارد). ج، عَلاکم . <BR><font color=\"Blue\">◄</font> مرد تنومند. (از ذیل اقرب الموارد).<br></font></div>'),
(185709, 'علکم', '<span class=\"hlight\">علکم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ک ُ ]</font></b> (ع ص ) قوی و سخت از شتر و امثال آن . (از ذیل اقرب الموارد).<br></font></div>'),
(185710, 'علکمة', '<span class=\"hlight\">علکمة.</span> <font color=\"DarkGreen\"><b>[ ع َ ک َ م َ ]</font></b> (ع اِمص ) بزرگی کوهان . (منتهی الارب ) (از اقرب الموارد).<br></font></div>'),
(185711, 'علکوم', '<span class=\"hlight\">علکوم .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (ع ص ) استواراندام از شتر و جز آن . مذکر و مؤنث در آن یکسان است . (منتهی الارب ) (از اقرب الموارد). ج، عَلاکیم . (اقرب الموارد).<br></font></div>'),
(185712, 'علکیت', '<span class=\"hlight\">علکیت .</span> <font color=\"DarkGreen\"><b>[ ع َ کی ی َ]</font></b> (ع مص جعلی، اِمص ) لزوجتی با نوعی سختی و صلابت .<br></font></div>'),
(185713, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حموش بن محمدبن مختار قیروانی اندلسی قرطبی . رجوع به علی قیروانی شود.<br></font></div>'),
(185714, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن حمودبن محمدبن سعیدبن سلطان بوسعیدی . از سلاطین زنگبار. وی در سال <span class=\"hlight\" dir=\"rtl\">١٢٩٨</span> هَ . ق . متولد شد و در سال <span class=\"hlight\" dir=\"rtl\">١٣١٦</span> هَ . ق . بعد از درگذشت پدرش به سلطنت زنگبار رسید ولی دولت انگلستان به بهانه ٔ خردسالی وی، خود عهده دار اداره ٔ امور آنجا شد تا اینکه در سال <span class=\"hlight\" dir=\"rtl\">١٣٢٢</span> هَ . ق . بعضی اختیارات داخلی به وی واگذار شد اما بسبب بسیاری اختلافات با نماینده ٔ انگلستان، در سال <span class=\"hlight\" dir=\"rtl\">١٣٢٩</span> هَ . ق . به کناره گیری از سلطنت مجبور گشت و به پاریس رفت و در آنجا اقامت گزید و در سال <span class=\"hlight\" dir=\"rtl\">١٣٣٦</span> هَ . ق . درگذشت . (از اعلام زرکلی از عشر سنوات حول العالم ص <span class=\"hlight\" dir=\"rtl\">٤٦٢</span>).<br></font></div>'),
(185715, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حمودبن میمون بن احمد ادریسی حسنی علوی حمودی، ملقب به الناصر لدین اﷲ. نخستین سلطان حمودیة در قرطبة و مالقة. رجوع به علی حمودی شود.<br></font></div>'),
(185716, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حمزة، مکنی به ابوالحسن . وی ادیب بود و به دمشق رفت و ابوالفتح صالح بن اسد کاتب را در آنجا مدح کرد.علی بن عبدالسلام صوری از وی روایت میکند. او در سال <span class=\"hlight\" dir=\"rtl\">٤٣٠</span> هَ . ق . در طرابلس درگذشت . او راست : رسالة الحماریة. (از معجم المؤلفین از الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٥</span>).<br></font></div>'),
(185717, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حمشادبن سختویه، مکنی به ابوالحسن (نام او را بصورت علی بن محمدبن سختویه بن حمشاد نیز ضبط کرده اند). وی محدث و حافظ و اهل نیشابور بود و در سال <span class=\"hlight\" dir=\"rtl\">٢٥٨</span> هَ . ق . تولد یافته و به شهرهای مختلفی سفر کرد و نزد اشخاص بسیاری تحصیل کرد. و در <span class=\"hlight\" dir=\"rtl\">١٤</span> شوال سال <span class=\"hlight\" dir=\"rtl\">٣٣٨</span> درگذشت . او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- الانوار، در دویست وشصت جلد. <span class=\"hlight\" dir=\"rtl\">٢</span>- التفسیر، در دویست وسی جلد. <span class=\"hlight\" dir=\"rtl\">٣</span>- المسندالکبیر، در چهارصد جلد. (از معجم المؤلفین از سیرالنبلاء ذهبی ج <span class=\"hlight\" dir=\"rtl\">١٠</span> ص <span class=\"hlight\" dir=\"rtl\">٩٨</span> و الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٦</span> وعیون التواریخ ابن شاکر کتی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٢</span> و المنتظم ابن جوزی ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦٤</span> و شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٨</span> و البدایه ٔ ابن کثیر ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٢</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٧٩</span>).<br></font></div>'),
(185718, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حمزه ٔ بصری . رجوع به علی بصری شود.<br></font></div>'),
(185719, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حمزه ٔ اصفهانی . رجوع به علی اصفهانی (ابن حمزه ) شود.<br></font></div>'),
(185720, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حمزةبن عمارةبن حمزةبن یساربن عثمان اصبهانی، مکنی به ابوالحسن . رجوع به علی اصفهانی شود.<br></font></div>'),
(185721, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حمزةبن علی طلحةبن علی رازی بغدادی، مکنی به ابوالحسین و مشهور به ابن بقشلان و ملقب به علم الدین . رجوع به علی رازی (ابن حمزةبن ...) شود.<br></font></div>'),
(185722, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حمزةبن عبداﷲبن عثمان اسدی کوفی، مشهور به کسائی و مکنی به ابوالحسن . مقری و تجویددان و لغوی و نحوی و شاعر. رجوع به کسائی شود.<br></font></div>'),
(185723, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حمزه، نام او علی بن حمیدصعیدی، مکنی به ابوالحسن و مشهور به ابن حمزه یا ابن صباغ است . رجوع به علی صعیدی (ابن حمید...) شود.<br></font></div>'),
(185724, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن موسی بن جعفربن محمدبن احمدبن طاووس علوی فاطمی، حسینی حلی، مشهور به ابن طاووس ومکنّی به ابوالقاسم یا ابوالحسن یا ابوموسی و ملقّب به رضی الدین . (<span class=\"hlight\" dir=\"rtl\">٥٨٩</span> - <span class=\"hlight\" dir=\"rtl\">٦٦٤</span> هَ . ق .) رجوع به ابن طاوس و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٨</span>. روضات الجنات خوانساری ص <span class=\"hlight\" dir=\"rtl\">٣٩٢</span>. فوائدالرضویة عباس قمی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٠</span>. تذکرةالمتبحرین ص <span class=\"hlight\" dir=\"rtl\">٤٩٠</span>. هدیةالعارفین بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧١٠</span>. کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span> و سایر صفحات . ایضاح المکنون بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٦</span> و سایر صفحات و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦</span> و سایر صفحات . ریحانةالادب ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٦٠</span>. مصنفی علم الرجال ص <span class=\"hlight\" dir=\"rtl\">٢٩٧</span>.<br></font></div>'),
(185725, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن منصوربن مضرس بن قیس غنوی جزری، مشهور به ابن غدیر. رجوع به علی جزری شود.<br></font></div>'),
(185726, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن هندو بغدادی، مکنی به ابوالفرج و مشهور به ابن هندو. رجوع به ابن هندو و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٨٢</span> و عیون الانباء ابن ابی اصیبعة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٣</span> و تاریخ حکماء اسلام بیهقی ص <span class=\"hlight\" dir=\"rtl\">٩٣</span> و فوات الوفیات ابن شاکر کتی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥</span> و ایضاح المکنون بغدادی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٩</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">١٧٦٢</span> و کنوز الاجداد محمد کردعلی ص <span class=\"hlight\" dir=\"rtl\">٢١٣</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨٦</span>.<br></font></div>'),
(185727, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن موسی بن ابراهیم رومی قوچ حصاری، ملقّب به علاءالدین . رجوع به علی قوچ حصاری شود.<br></font></div>'),
(185728, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حیدربن علی قمی، ملقب به نورالدین . رجوع به علی قمی شود.<br></font></div>'),
(185729, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن موسی (شیخ خواجه ...)، از متصوفه ٔعهد صفویه . رجوع به علی (ابن صدرالدین موسی ) شود.<br></font></div>'),
(185730, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن منیر. علی بن محمدبن منصوربن ابی القاسم بن مختاربن ابی بکربن علی جذامی اسکندری، مکنّی به ابوالحسن و ملقّب به زین الدین و مشهور به ابن منیر. رجوع به علی اسکندری (ابن محمدبن منصوربن ...) شود.<br></font></div>'),
(185731, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن منقی . علی بن خلیفةبن علی نحوی، مشهور به ابن منقی و مکنّی به ابوالحسن . رجوع به علی (ابن خلیفةبن علی نحوی ) شود.<br></font></div>'),
(185732, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن منصور فاسی مالکی، مکنّی به ابوالحسن . رجوع به علی فاسی شود.<br></font></div>'),
(185733, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن منصوربن ناصر مقدسی حنفی، ملقّب به علاءالدین . رجوع به علی مقدسی شود.<br></font></div>'),
(185734, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حمویه . وی فرزند حمویه حاکم نیشابور در عهد امیر نصر سامانی بود و خود در بارگاه امیر نصر میزیست . و او را با حسین بن علی گفتگوئی است که در تاریخ حبیب السیر نقل شده است . (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٨</span>).<br></font></div>'),
(185735, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن منصوربن محمدبن ابی المعالی بن احمد حسینی کازرانی الاصل حائری المولد، مشهور به علی الکبیر. رجوع به علی کبیر شود.<br></font></div>'),
(185736, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن منصوربن عزیزبن معز فاطمی عبیدی، مکنّی به ابوالحسن و ملقّب به الظاهرالاعزاز دین اﷲ، از پادشاهان دولت فاطمی مصر. رجوع به علی فاطمی (ابن منصوربن ...) شود.<br></font></div>'),
(185737, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حوشب فزاری، مکنی به ابوسلیمان . محدث بود و ولیدبن مسلم از او روایت کرد. و نیز رجوع به ابوسلیمان (علی بن ...) شود.<br></font></div>'),
(185738, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حنظلة، مکنی به ابوطلق . از تابعیان بود. و رجوع به ابوطلق شود.<br></font></div>'),
(185739, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حنا، علی بن محمدبن سلیم مصری، ملقب به بهاءالدین و مشهور به ابن حنا. وزیر الظاهر فاطمی . رجوع به علی مصری (ابن محمدبن سلیم ...) شود.<br></font></div>'),
(185740, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حمید سعیدی، مکنی به ابوالحسن و مشهور به ابن صباغ یا ابن حمزه . رجوع به علی سعیدی (ابن حمید...) شود.<br></font></div>'),
(185741, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حمیدبن احمدبن جعفربن ولید قرشی . رجوع به علی قرشی شود.<br></font></div>'),
(185742, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین طریحی نجفی . رجوع به علی طریحی شود.<br></font></div>'),
(185743, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن دریهم، علی بن محمدبن عبدالعزیزبن فتوح بن ابراهیم تغلبی موصلی دمشقی شافعی، مشهور به ابن دریهم و ملقب به تاج الدین . رجوع به ابن دریهم و علی بن محمدبن ... شود.<br></font></div>'),
(185744, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن یحیی . فقیه و عالم علم فرایض (متوفی در حدود سال <span class=\"hlight\" dir=\"rtl\">٦٦٠</span> هَ . ق .). او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- الدر فی الفرائض .<span class=\"hlight\" dir=\"rtl\">٢</span>- القمر المنیر فی حل عقود التحریر. <span class=\"hlight\" dir=\"rtl\">٣</span>- اللمع.(از معجم المؤلفین از تراجم الرجال جنداری ص <span class=\"hlight\" dir=\"rtl\">٢٤</span>).<br></font></div>'),
(185745, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین اردکانی شیرازی (علی رضا...)، مشهور به تجلی . رجوع به علی رضا (ابن حسین ...) و تجلی شود.<br></font></div>'),
(185746, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین اصابی قطیعی یمنی شافعی . رجوع به اصابی و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٧٢</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧١٠</span> و اعلام زرکلی چ <span class=\"hlight\" dir=\"rtl\">٢</span> ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٩٠</span> و العقود اللؤلؤیة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٨</span>.<br></font></div>'),
(185747, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن حسین أماسی . رجوع به علی اماسی شود.<br></font></div>'),
(185748, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن حسین انصاری، مشهور به حاجی زینل عطار. از دانشمندان قرن هشتم هجری . رجوع به حاجی زینل عطار شود.<br></font></div>'),
(185749, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بدلیسی حنفی، ملقب به حسام الدین . رجوع به علی بدلیسی شود.<br></font></div>'),
(185750, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بیاعی . محدث . رجوع به علی بیاعی شود.<br></font></div>'),
(185751, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین جوری (یا حوری )، مکنی به ابوالحسن . رجوع به علی جوری شود.<br></font></div>'),
(185752, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین خلیعی شاعر، مکنی به ابوالحسین . رجوع به علی خلیعی (ابن حسین ...) شود.<br></font></div>'),
(185753, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین حسینی مرعشی . رجوع به علی مرعشی شود.<br></font></div>'),
(185754, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین خیقانی حلی نجفی . رجوع به علی خیقانی شود.<br></font></div>'),
(185755, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین داوودی، مکنی به ابوالقاسم . رجوع به علی داوودی شود.<br></font></div>'),
(185756, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین شاکر جرکسی پارسی . رجوع به علی شاکر شود.<br></font></div>'),
(185757, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حمدون بن سماک بن مسعودبن منصور جذامی، مشهور به ابن اندلسی . رجوع به علی جذامی (ابن حمدون بن ...) شود.<br></font></div>'),
(185758, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین قدامه ٔ موسوی، مکنی به ابوجعفر. ممدوح ادیب صابر ترمذی . رجوع به علی موسوی (ابن حسین ...) شود.<br></font></div>'),
(185759, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین قرشی . رجوع به علی قرشی (ابن حسین ...) شود.<br></font></div>'),
(185760, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین قمی شیعی، ملقب به نورالدین . رجوع به علی قمی شود.<br></font></div>'),
(185761, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین قهستانی، شاعر، مکنی به ابوبکر. رجوع به علی قهستانی (ابن حسین ...) شود.<br></font></div>'),
(185762, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن حسین کاکی . رجوع به علی کاکی شود.<br></font></div>'),
(185763, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین مروزی حنفی، ملقب به علاءالدین . رجوع به علی مروزی شود.<br></font></div>'),
(185764, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین مسرعی، مشهور به بولاقی . رجوع به علی بولاقی شود.<br></font></div>'),
(185765, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین مغربی کاتب، مکنی به ابوالحسن . رجوع به علی مغربی شود.<br></font></div>'),
(185766, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حصین بن مالک بن خشخاش عنبری تمیمی، مکنی به ابوالحر. رجوع به علی عنبری شود.<br></font></div>'),
(185767, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حکم بنانی، مکنی به ابوالحکم . محدث بود و ابوالاشهب از او روایت کند. رجوع به ابوالحکم (علی بن ...) شود.<br></font></div>'),
(185768, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حکم سلمی، برادر معاویةبن حکم . رجوع به علی سلمی شود.<br></font></div>'),
(185769, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حکیم ازدی، مکنی به ابوالحسن . تابعی . رجوع به ابوالحسن (علی بن ...) شود.<br></font></div>'),
(185770, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حمدان، مکنی به ابوالحسن و ملقب به سیف الدوله . رجوع به سیف الدوله و الاَّثار الباقیه ٔ بیرونی ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span> شود.<br></font></div>'),
(185771, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن داوود. او افسانه ها از زبان حیوان می کرده است . (از الفهرست ابن الندیم ).<br></font></div>'),
(185772, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خلف بن عبدالمطلب بن حیدربن محمدبن فلاح موسوی حسینی مشعشعی حویزی . محدث و مفسر و ادیب . رجوع به علی حویزی شود.<br></font></div>'),
(185773, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خلف بن عبدالملک بن بطال بکری قرطبی مالکی، مشهور به ابن لجام و مکنی به ابوالحسن . رجوع به علی قرطبی شود.<br></font></div>'),
(185774, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خلف بن عبدالوهاب کاتب، مکنی به ابوالحسن . او راست : موارد البیان . (از کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">١٨٨٨</span>).<br></font></div>'),
(185775, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خلیفةبن علی نحوی، مشهور به ابن منقی و مکنی به ابوالحسن . وی اهل موصل بود و در ادب تبحر داشت و در مسجد نبی (ص ) در موصل می نشست . در معجم الادباء قطعاتی ازاشعار او نقل شده است . او در ربیعالاول سال <span class=\"hlight\" dir=\"rtl\">٥٦٢</span> هَ .ق . درگذشت . (از معجم الادباء چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٦</span>).<br></font></div>'),
(185776, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خلیفةبن یونس بن ابی القاسم بن خلیفه ٔ خزرجی، مشهور به ابن ابی اصیبعة و ملقب به رشیدالدین و مکنی به ابوالحسن . متولد در سال <span class=\"hlight\" dir=\"rtl\">٥٧٩</span> هَ . ق . در حلب و متوفی در سال <span class=\"hlight\" dir=\"rtl\">٦١٦</span>، و جسد او در بیرون باب الفرادیس مدفون است . او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- تعالیق من مجربات فی الطب . <span class=\"hlight\" dir=\"rtl\">٢</span>- کتاب طب السوق .<span class=\"hlight\" dir=\"rtl\">٣</span>- کتاب المساحة. <span class=\"hlight\" dir=\"rtl\">٤</span>- مقالة فی السبب خلقت الجبال . <span class=\"hlight\" dir=\"rtl\">٥</span>- مقالة فی نسبة النبض و موازنته الی الحرکات الموسیقاریة. <span class=\"hlight\" dir=\"rtl\">٦</span>- الموجز المفید فی علم الحساب . (از معجم المؤلفین از الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٧</span> و عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٦</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">١٨٩٩</span> و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٧</span> و روضات الجنات ص <span class=\"hlight\" dir=\"rtl\">٤٨٧</span>). نیز رجوع به ابن ابی اصیبعة شود.<br></font></div>'),
(185777, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خلیفه ٔ حسینی مالکی . رجوع به علی حسینی شود.<br></font></div>'),
(185778, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خلیفه ٔ موصلی . رجوع به علی موصلی شود.<br></font></div>'),
(185779, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن خلیل بن ابراهیم بن محمدعلی رازی طهرانی نجفی . رجوع به علی تهرانی (ابن خلیل بن ...) شود.<br></font></div>'),
(185780, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خلیل بن احمدبن سالم شافعی، ملقب به علاءالدین . رجوع به علی شافعی شود.<br></font></div>'),
(185781, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خلیل بن علی بن حسین دمشقی، مشهور به ابن قاضی عسکر و مکنی به ابوالحسن . رجوع به علی دمشقی شود.<br></font></div>'),
(185782, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خلیل حنفی طرابلسی . رجوع به علاءالدین طرابلسی شود.<br></font></div>'),
(185783, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خلیل شاعر. یکی از رؤسای متکلمان زنادقة (مانویه ) بود که خود را مسلمان می نمود. او را صد ورقه شعر بوده است . (از الفهرست ابن الندیم ). و رجوع به ثمار القلوب ثعالبی ص <span class=\"hlight\" dir=\"rtl\">١٣٨</span> شود.<br></font></div>'),
(185784, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خلیل مرصفی (یا مرصفاوی ) مصری مدنی شافعی، مکنی به ابوالحسن و ملقب به نورالدین . رجوع به علی مرصفی شود.<br></font></div>'),
(185785, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خواجه بهاءالدین محمد جوینی، نواده ٔ خواجه شمس الدین محمد صاحبدیوان . رجوع به علی جوینی (ابن بهاءالدین محمد...) شود.<br></font></div>'),
(185786, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خلف بن خلیل بن عطأاﷲ غزی شافعی، ملقب به علاءالدین . رجوع به علی غزی شود.<br></font></div>'),
(185787, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن داوود. کلیله و دمنه را به شعر کرده است . (از الفهرست ابن الندیم ).<br></font></div>'),
(185788, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن داوود. منجم فاضل و مقدم . او راست : کتاب الامطار. (از الفهرست ابن الندیم ).<br></font></div>'),
(185789, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن داوود (یا داوودبن داوود)، مکنی به ابوالمتوکل و ملقب به ناجی . محدث است . و نیز رجوع به ابوالمتوکل شود.<br></font></div>'),
(185790, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن داوودبن ابراهیم جوهری، مشهور به ابن صیرفی . رجوع به علی جوهری شود.<br></font></div>'),
(185791, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن داوودبن جراح، مکنی به ابوالحسن . وزیر و کاتب المقتدرباﷲ عباسی بود. (از مجمل التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">٣٧٧</span>).<br></font></div>'),
(185792, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن داوودبن سلیمان اصفهانی، ملقب به صائن الدین . رجوع به علی اصفهانی شود.<br></font></div>'),
(185793, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن داوودبن سلیمان جوهری مصری شافعی، ملقب به نورالدین . رجوع به علی جوهری شود.<br></font></div>'),
(185794, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن داوودبن یحیی بن کامل بن یحیی بن جباره ٔ زبیری قرشی اسدی، ملقب به نجم الدین و مکنی به ابوالحسن . رجوع به علی زبیری شود.<br></font></div>'),
(185795, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن داوودبن یوسف رسولی، مشهور به مجاهد رسولی . رجوع به علی رسولی (ابن داوود مؤید...) شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(185796, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن داوود بغدادی . کاتب زبیدة بنت جعفر. رجوع به علی بغدادی (ابن داوود...) شود.<br></font></div>'),
(185797, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن داوود خطیب جوهری، مشهور به ابن صیرفی .رجوع به علی جوهری (ابن داوودبن ابراهیم ...) شود.<br></font></div>'),
(185798, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن دبیس بن صدقةبن منصور اسدی مزیدی . اسدی بود. رجوع به علی مزیدی شود.<br></font></div>'),
(185799, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسام الدین بن عبدالملک جونفوری هندی، مشهور به متقی و ملقب به علاءالدین . رجوع به علی متقی شود.<br></font></div>'),
(185800, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مهزیار اهوازی دورقی شیعی، مکنّی به ابوالحسن . رجوع به علی اهوازی شود.<br></font></div>'),
(185801, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن موسی بن شفیعبن رفیع تبریزی، ملقّب به ثقةالاسلام . رجوع به علی تبریزی شود.<br></font></div>'),
(185802, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن موسی بن عبدالملک بن سعید عنسی اندلسی غرناطی مغربی، مکنّی به ابوالحسن و مشهور به ابن سعید. او را علاوه بر کتابهائی که در «ابن سعید» آورده شده است، تألیفات ذیل می باشد:<span class=\"hlight\" dir=\"rtl\">١</span> - ریحانةالادب . <span class=\"hlight\" dir=\"rtl\">٢</span> - الشهب الثاقبة فی الانصاف بین المشارقة و المغاربة. <span class=\"hlight\" dir=\"rtl\">٣</span> - لذة الاحلام فی تاریخ امم الاعجام، در حدود دو جلد. <span class=\"hlight\" dir=\"rtl\">٤</span> - نتائج القرائح فی مختار المرائی و المدائح . او را دیوان شعری نیز می باشد. رجوع به ابن سعید و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٩</span>. الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٦</span>. معجم الادباء یاقوت ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">٥</span>. فوات الوفیات ابن شاکر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٩</span>. بغیةالوعاة سیوطی ص <span class=\"hlight\" dir=\"rtl\">٣٥٧</span>. الدیباج ابن فرحون ص <span class=\"hlight\" dir=\"rtl\">٢٠٨</span>. حسن المحاضره ٔ سیوطی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٠</span>. کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">٢٧٩</span> و سایر صفحات . تاریخ علماء بغداد ابن رافع. ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span>. ایضاح المکنون بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٨٥</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٠</span> و سایر صفحات . هدیةالعارفین بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧١٤</span>. فهرس المخطوطات المصوره ٔ لطفی عبدالبدیع ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٢</span>. فهرس المخطوطات المصوره ٔ سید ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٢</span>.<br></font></div>'),
(185803, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن موسی بن عبداﷲ لخمی بسطی، مشهور به قرباقی . رجوع به علی لخمی شود.<br></font></div>'),
(185804, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن موسی بن علی بن موسی بن محمدبن خلف انصاری سالمی اندلسی جیانی، مشهور به ابن ارفع راس و مکنّی به ابوالحسن . رجوع به علی انعماری شود.<br></font></div>'),
(185805, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن موسی بن محمد شفیعبن محمدبن جعفربن میرزا محمدرفیعبن محمد شفیع مستوفی الممالک، خراسانی تبریزی، ملقب به ثقةالاسلام . رجوع به علی خراسانی شود.<br></font></div>'),
(185806, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن موسی بن یزداد (یا یزید) قمی نیشابوری حنفی، مکنّی به ابوالحسن . رجوع به علی قمی شود.<br></font></div>'),
(185807, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن موسی الرضا علیهماالسلام . هشتمین امام از ائمه ٔ شیعه ٔ اثنا عشریة. رجوع به ابوالحسن . (علی الرضابن موسی ...) شود.<br></font></div>'),
(185808, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن موسی لشکری، مکنّی به ابوالحسن . ممدوح قطران شاعر. رجوع به علی لشکری شود.<br></font></div>'),
(185809, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن موفق عابد، مکنّی به ابوالحسن . وی از محدثان و زهاد بود و در سال <span class=\"hlight\" dir=\"rtl\">٢٦٥</span> هَ . ق . درگذشت . در صفةالصفوة حکایات بسیاری درباره ٔ کرامات او نقل شده است . رجوع به صفوةالصفوه ٔ ابوالفرج بن جوزی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٨</span> شود.<br></font></div>'),
(185810, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن مؤمل بن علی بن غسان مصری، مکنّی به ابوالحسن و مشهور به ابن غسان . رجوع به علی مصری شود.<br></font></div>'),
(185811, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مؤمن بن محمدبن علی حضرمی اشبیلی، مشهور به ابن عصفور و مکنّی به ابوالحسن . فقیه و نحوی و لغوی بود که در سال <span class=\"hlight\" dir=\"rtl\">٦٦٣</span> یا <span class=\"hlight\" dir=\"rtl\">٦٦٩</span> هَ . ق . در تونس درگذشت . مولد او در سال <span class=\"hlight\" dir=\"rtl\">٥٩٧</span> هَ . ق . بود. بجز کتبی که در «ابن عصفور» از وی ذکر شده او راست : <span class=\"hlight\" dir=\"rtl\">١</span> - شرح جمل زجاجی، در نحو. <span class=\"hlight\" dir=\"rtl\">٢</span> - شرح دیوان متنبی . <span class=\"hlight\" dir=\"rtl\">٣</span> - شرح معرب در نحو، که کامل نیست . <span class=\"hlight\" dir=\"rtl\">٤</span> - الممتع فی التصریف . (از معجم المؤلفین بنقل از الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٨</span>. فوات الوفیات ابن شاکر. ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩٣</span>. شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٠</span>. بغیة الوعاة سیوطی ص <span class=\"hlight\" dir=\"rtl\">٣٥٧</span>. مفتاح السعاده ٔ طاش کبری ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٨</span>. عنوان الدرایه ٔ غبرینی ص <span class=\"hlight\" dir=\"rtl\">١٨٨</span>. کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">٥٢٧</span> و سایر صفحات . ایضاح المکنون بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٢٧</span>. روضات الجنات خوانساری ص <span class=\"hlight\" dir=\"rtl\">٤١٣</span>. هدیةالعارفین بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧١٢</span>). و نیز رجوع به ابن عصفور شود.<br></font></div>'),
(185812, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن موهب . علی بن عبداﷲبن محمدبن سعیدبن موهب جذامی اندلسی، مکنّی به ابوالحسن و مشهور به ابن موهب . رجوع به علی اندلسی (ابن عبداﷲ محمدبن ...) شود.<br></font></div>'),
(185813, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن مهدی بن علی بن مهدی کسروی اصفهانی بغدادی شافعی، مکنّی به ابوالحسن . رجوع به علی کسروی شود.<br></font></div>'),
(185814, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مهدی بن محمدبن علی بن داوودبن محمدبن عبداﷲبن محمدبن احمدبن عبدالقاهربن عبداﷲبن اغلب بن ابی الفوارس بن میمون حمیری رعینی زبیدی، مکنّی به ابوالحسن . اولین تن از خوارج بنی مهدی در زبید. رجوع به علی رعینی (ابن مهدی بن ...) شود.<br></font></div>'),
(185815, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن موسی بن جعفربن محمدبن علی بن حسین بن علی بن ابی طالب علیهم السلام . هشتمین امام از ائمه ٔ شیعه اثناعشریة. رجوع به ابوالحسن (علی الرضابن موسی ...) شود.<br></font></div>'),
(185816, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حیدربن محمدبن احمد هاشمی حسنی تهامی . رجوع به علی تهامی شود.<br></font></div>'),
(185817, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حیدرة. او راست : شرح تلخیص اعمال الحساب ابن بناء. (از کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">٤٧٢</span>).<br></font></div>'),
(185818, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حیون، علی بن نعمان بن محمدبن حیون، مکنی به ابوالحسن و مشهوربه ابن حیون . رجوع به علی بن نعمان بن محمد... شود.<br></font></div>'),
(185819, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خاتون، علی بن احمدبن خاتون عاملی، مشهور به ابن خاتون . رجوع به علی عاملی (ابن احمدبن خاتون ) شود.<br></font></div>'),
(185820, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خدیعکرمانی . وی پس از اینکه پدرش «کرمانی » به دست یکی از چاکران نصربن سیار در مرو کشته شد، در سال <span class=\"hlight\" dir=\"rtl\">٣٣٠</span> هَ . ق . نزد ابومسلم خراسانی آمد و چند روزی در خدمت اوبود اما از وی روی گردان شد و به خدمت نصربن سیار شتافت . در این هنگام سلیمان بن کثیر به وی پیغام داد که این غایت بی حمیتی توست که از کسی متابعت میکنی که پدر تو را به خدعه به قتل رسانده است . این سخن در علی بن خدیع مؤثر افتاد و با نصر به مخالفت برخاست و قبیله ٔ ربیعه را با خود همداستان ساخت . درین هنگام هر یک ازین دو تن پیغام نزد ابومسلم فرستادند و از او یاری خواستند. ابومسلم پس از مشورت با شیعه ٔ عباسیه جانب ابن کرمانی را گرفت . پس از چندی ابن کرمانی به مرو حمله کرد و نصف شهر را از چنگ نصر بدرآورد. در این هنگام ابومسلم خراسانی به کمک وی شتافت و با کمک قبیله ٔ ربیعه، مرو را تسخیر کرد و از یاران نصر و مروانیه هرکه را یافت به قتل رساند و ابن کرمانی را نیزچند روزی در سلک چاکران خود جای داد، اما او را نیزپس از چندی به قتل رساند و تمامی ملک خراسان را به تصرف خود درآورد. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٥</span>).<br></font></div>'),
(185821, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خراسان، علی بن احمدبن عبدالعزیزبن عبدالحق بن خراسان، مشهور به ابن خراسان . آخرین تن از امرای آل خراسان در تونس . رجوع به علی بن احمدبن عبدالعزیزبن ... شود.<br></font></div>'),
(185822, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خروف، علی بن محمدبن علی بن محمد حضرمی رندی اشبیلی اندلسی، مشهور به ابن خروف و مکنی به ابوالحسن . رجوع به علی اشبیلی (ابن محمدبن علی بن ...) شود.<br></font></div>'),
(185823, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خروف، علی بن محمدبن یوسف بن مسعود قیسی قرطبی، شاعر، ملقب به نظام الدین و مکنی به ابوالحسن و مشهور به ابن خروف . رجوع به ابن خروف (ضیأالدین ابوالحسن ...) و علی بن محمدبن یوسف بن ... شود.<br></font></div>'),
(185824, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خسرو ازنیقی (علی چلبی ...). رجوع به علی چلبی شود.<br></font></div>'),
(185825, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خشرم . از محدثان بود. (منتهی الارب ).<br></font></div>'),
(185826, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خضربن احمد عمروسی مالکی . رجوع به علی عمروسی شود.<br></font></div>'),
(185827, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خضربن حسن عثمانی دمشقی، مکنی به ابوالحسن . رجوع به علی عثمانی شود.<br></font></div>'),
(185828, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن خطیب الناصریة، علی بن محمدبن سعدبن محمدبن علی بن عثمان بن اسماعیل بن ابراهیم جبرینی حلبی طائی شافعی، مشهور به ابن خطیب ناصریة و مکنی به ابوالحسن و ملقب به علاءالدین . رجوع به علی حلبی (ابن محمدبن سعدبن ...) شود.<br></font></div>'),
(185829, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن حسن بن فضال . از علمای شیعه بود و اوراست کتاب فضائل القرآن . (از الفهرست ابن الندیم ).<br></font></div>'),
(185830, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن علی بن ابی طالب باخرزی سخنی شافعی، مکنی به ابوالحسن . رجوع به ابوالحسن باخرزی و ابوالحسن علی بن حسن ... و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥</span> و وفیات الاعیان ابن خلکان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥٤</span> و معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">١٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣</span> و طبقات الشافعیه ٔ سبکی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٨</span> و النجوم الزاهره ٔ ابن تغری بردی ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٩٩</span> و شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٧</span> و البدایه ٔ ابن کثیر ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span> و مفتاح السعاده ٔ طاش کبری ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٣</span> و مرآةالجنان یافعی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٩٥</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٧٦١</span>و سایر صفحات و المخطوطات العربیه ٔ کورکیس عواد ص <span class=\"hlight\" dir=\"rtl\">٥٦</span>و مخطوطات الموصل جلی ص <span class=\"hlight\" dir=\"rtl\">٥٣</span> و مکتبةالمجلس النیابی ص <span class=\"hlight\" dir=\"rtl\">٢٢</span> و فهرس المخطوطات المصورة سید ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٢</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٢٩</span> و سیرالنبلاء ذهبی ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span> و الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦</span> و ذیل تاریخ بغداد ابن نجار ج <span class=\"hlight\" dir=\"rtl\">١٠</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span> و طبقات الشافعیه ٔ اسنوی ص <span class=\"hlight\" dir=\"rtl\">٤١</span> و فهرس المؤلفین بالظاهریةو مناقب الشافعی و طبقات اصحابه من تاریخ الذهبی .<br></font></div>'),
(185831, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن علی بن اسحاق، مکنی به ابوالمظفر و ملقب به فخرالملک . وی بزرگترین فرزند نظام الملک بود. در سال <span class=\"hlight\" dir=\"rtl\">٤٣٤</span> هَ . ق . متولد شد ودر سال <span class=\"hlight\" dir=\"rtl\">٤٨٨</span> وزارت برکیارق را به عهده گرفت . سپس به نیشابور رفت و وزارت سنجر را عهده دار شد و در سال <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> در آنجا به دست یکی از فدائیان اسماعیلیه به قتل رسید. (از اعلام زرکلی از کامل ابن اثیر ج <span class=\"hlight\" dir=\"rtl\">١٠</span> ص <span class=\"hlight\" dir=\"rtl\">٤٨٨</span> و النجوم الزاهرة ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٥</span> و تاریخ دولة آل سلجوق ص <span class=\"hlight\" dir=\"rtl\">٧٩</span>).<br></font></div>'),
(185832, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن علی بن سلیمان بن احمد آل حاجی بلادی . رجوع به علی حاجی شود.<br></font></div>'),
(185833, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن حسن بن علی بن صدقه، مکنی به ابوالحسن و ملقب به شرف الدوله . پدر او وزیر المسترشد بود و نخستین کس از بنی صدقه بود که به وزارت رسید و لقب جلال الدوله داشت . این علی بن حسن همیشه نایب پدر خود در وزارت بود و هیچگاه بالاستقلال وزیر نشد. او را خطی خوش بود و در اواخر عمر رباطی بر ساحل دجله بنام «رباطالدرجة» ساخت و با عده ای از فقرا در آنجا عزلت گزید. تولد او در محرم سال <span class=\"hlight\" dir=\"rtl\">٤٩٩</span> هَ . ق . و وفاتش در هفتم صفر سال <span class=\"hlight\" dir=\"rtl\">٥٥٤</span> بوده است . (از معجم الادباء چ مصر ج <span class=\"hlight\" dir=\"rtl\">١٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>).<br></font></div>'),
(185834, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن علی بن فضال بن عمربن أیمن کوفی، مکنی به ابوالحسن . رجوع به علی کوفی شود.<br></font></div>'),
(185835, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن علی بن فضل، مشهور به صردرو مکنی به ابومنصور. رجوع به صردر و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦</span> و وفیات الاعیان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥٣</span> و شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٢</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٧٧٣</span> فهرست المخطوطات المصورة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٦١</span> و فهرست الخدیویة ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٨</span>.<br></font></div>'),
(185836, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن علی بن لطف اﷲ حسینی قنوجی بخاری، مشهور به صدیق حسن . رجوع به علی قنوجی شود.<br></font></div>'),
(185837, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن علی بن محمد حر عاملی . رجوع به علی حر شود.<br></font></div>'),
(185838, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن علی بن میمون ربعی دمشقی، مشهور به ابن ابی زروان . رجوع به علی ربعی شود.<br></font></div>'),
(185839, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن علی اسنوی مصری شافعی، ملقب به بدرالدین . رجوع به علی اسنوی شود.<br></font></div>'),
(185840, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن علی زمیلی بغدادی، شافعی، مکنی به ابوالحسن . رجوع به علی بغدادی شود.<br></font></div>'),
(185841, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن علی لیثی مصری . رجوع به علی لیثی شود.<br></font></div>'),
(185842, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن علی نیشابوری صندیلی حنفی، مکنی به ابوالحسن . رجوع به علی نیشابوری شود.<br></font></div>'),
(185843, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن عنتربن ثابت حلی، مشهور به شمیم و ملقب به مهذب الدین و مکنی به ابوالحسن . رجوع به علی شمیم شود.<br></font></div>'),
(185844, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن حسن بن علی بن ابی حسین حسنی کلبی، مکنی به ابوالقاسم . رجوع به علی کلبی (ابن حسن بن ...) شود.<br></font></div>'),
(185845, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن فضیل بن مروان . وی فارسی الاصل بود و ابن الندیم گوید که او را کتاب «الاصنام و ما کانت العرب و العجم تعبد من دون اﷲ عز و جل » بوده است . (از معجم الادباء چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>).<br></font></div>'),
(185846, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن محمدبن اسماعیل خزرجی زبیدی یمنی، مشهور به ابن وهاس و ملقب به موفق الدین و مکنی به ابوالحسن . رجوع به علی یمنی شود.<br></font></div>'),
(185847, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن محمدبن حسن بن عبدالرحمان بن یحیی بن عیسی نعمی حسنی یمنی . رجوع به علی نعمی شود.<br></font></div>'),
(185848, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن محمدبن علی طباطبایی حایری (علینقی ...). رجوع به علینقی شود.<br></font></div>'),
(185849, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن محمدبن حسن بن قاسم حسنی فاطمی علوی، مشهور به شریف . رجوع به علی شریف شود.<br></font></div>'),
(185850, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن محمدبن فهر فهری مصری مالکی، مکنی به ابوالحسن . رجوع به علی فهری شود.<br></font></div>'),
(185851, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن محمدبن یحیی، مشهور به علان مصری . ابوبکر زبیدی نام وی را آورده و گوید که او از علمای نحو بود و در شوال سال <span class=\"hlight\" dir=\"rtl\">٣٣٧</span> هَ .ق . درگذشت . (از معجم الادباء چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١١٥</span>).<br></font></div>'),
(185852, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن محمد طایی حرمی کوفی، مشهور به طاطری و مکنی به ابوالحسن . رجوع به علی طاطری شود.<br></font></div>'),
(185853, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن محمد همدانی مسعودی، مشهور به ابن شهاب . رجوع به علی مسعودی شود.<br></font></div>'),
(185854, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن وحشی نحوی موصلی، مکنی به ابوالفتح . رجوع به علی موصلی (ابن حسن بن ...) شود.<br></font></div>'),
(185855, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن هبةاﷲبن عبداﷲبن حسین دمشقی شافعی، مشهور به ابن عساکر و ملقب به ثقةالدین و مکنی به ابوالقاسم . رجوع به ابن عساکر و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٦٩</span> و وفیات اعیان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٢</span> و طبقات الشافعیه ٔ سبکی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٣</span> و معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">١٣</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣</span> و النجوم الزاهره ٔ ابن تغری بردی ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٧٧</span> و تذکرة الحفاظ ذهبی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١١٨</span> و شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٩</span> و البدایه ٔ ابن کثیر ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٤</span> و الدارس نعیمی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٠</span> و المختصر فی اخبار البشر ابوالفداء ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٦٢</span> و مختصر دول الاسلام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٢</span> و مفتاح السعاده ٔ طاش کبری ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٦</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١١</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٥٤</span> و سایر صفحات، و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٤</span> و کنوزالاجداد محمد کردعلی ص <span class=\"hlight\" dir=\"rtl\">٣٠٦</span> و فهرست الخدیویة ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥</span> و مقدمه ٔ تاریخ ابن عساکر از صلاح الدین منجد و فهرس مخطوطات المصوره ٔ سید ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩</span> و فهرس مخطوطات الظاهریه ٔ یوسف عش ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٩</span> و جولة فی دور الکتب الامیرکیه ٔ کورکیس عواد ص <span class=\"hlight\" dir=\"rtl\">٨٩</span> و فهرس المخطوطات المصوره ٔ لطفی عبدالبدیع ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦</span> و هدیةالعارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٠١</span> و سیرالنبلاء ذهبی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٨</span> و التذکره ٔ طاهر جزائری ص <span class=\"hlight\" dir=\"rtl\">٢٤</span> و فهرس المؤلفین بالظاهریة و الزیارات عدوی ص <span class=\"hlight\" dir=\"rtl\">٢٠</span> و الاعلام بوفیات الاعلام ذهبی ص <span class=\"hlight\" dir=\"rtl\">٢١٠</span> والوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥</span> و حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٧</span>.<br></font></div>'),
(185856, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن أحمر. رجوع به علی أحمر شود.<br></font></div>'),
(185857, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن أکوع صنعانی . رجوع به علی أکوع شود.<br></font></div>'),
(185858, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن ببای حنفی . رجوع به علی ببای شود.<br></font></div>'),
(185859, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن بَل ّ بغدادی . محدث است . (از منتهی الارب ).<br></font></div>'),
(185860, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی حسن سندی مدنی، ملقب به نورالدین . رجوع به علی سندی شود.<br></font></div>'),
(185861, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسام الدین اکبرآبادی هندی، مشهور به آرزو و ملقب به سراج الدین . رجوع به آرزو و به علی شاه بن حسام الدین ... شود.<br></font></div>'),
(185862, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن . وی کاتب محمدبن محمود سبکتکین بود، و او ذواللسانین بوده است و در هر دو زبان عربی و فارسی شعر می گفت . (یادداشت بخط مرحوم دهخدا). ونیز رجوع به لباب الالباب عوفی چ لیدن ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦</span> شود.<br></font></div>'),
(185863, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن، مکنی به ابوالحسن و مشهور به ابن طرخان . از استادان موسیقی و غناء. رجوع به ابن طرخان (ابوالحسن علی ...) شود.<br></font></div>'),
(185864, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن، مشهور به ابن ماشطة و مکنی به ابوالحسن . رجوع به ابن ماشطة، و کتب ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨</span> و الفهرست ابن الندیم ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٥</span> و معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">١٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٤</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨٠</span> و ذیل تاریخ بغداد ابن نجار ج <span class=\"hlight\" dir=\"rtl\">١٠</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٣</span>.<br></font></div>'),
(185865, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن، ملقب به ابوالفرج . موسیقی دان متوفی در سال <span class=\"hlight\" dir=\"rtl\">٧٢١</span> هَ. ق .). او را کتابی است در موسیقی . (از معجم المؤلفین از تاریخ الموسیقی العربیه ٔ جول رووانیت ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>).<br></font></div>'),
(185866, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن ابراهیم انکوری مصری، مشهور به درویش . رجوع به علی یمنی شود.<br></font></div>'),
(185867, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن ابی بکربن حسن بن علی خزرجی زبیدی یمنی، مشهور به ابن وهاس و ملقب به موفق الدین و مکنی به ابوالحسن . رجوع به علی درویش شود.<br></font></div>'),
(185868, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن ابی فرج احمد، مکنی به ابوالقاسم و مشهور به رئیس الرؤساء ابن مسلمة. از وزرای عادل و دانشمند بود. وی در سال <span class=\"hlight\" dir=\"rtl\">٣٩٧</span> هَ . ق . متولد شد و در سال <span class=\"hlight\" dir=\"rtl\">٤٣٧</span> به سمت وزارت القائم بامر اﷲ خلیفه ٔ عباسی منصوب گشت و خلیفه لقب جمال الدین، شرف الوزراء، رئیس الرؤساء به وی داد. او وزیری صاحب رأی و خرد بود، و برخی از مورخین را عقیده بر این است که وی با پیش گرفتن سیاست نزدیکی به ترکان، توانست نقشه ٔ فاطمی ها را برای برانداختن خلافت عباسی خنثی کند. وی همچنان در منصب وزارت باقی بود تا سال <span class=\"hlight\" dir=\"rtl\">٤٥٠</span> که در این سال به دست ارسلان بن عبداﷲ بساسیری دستگیر شد و به قتل رسید و جسد او را مثله مثله کردند.عمر او پنجاه ودو سال و پنج ماه و وزارتش دوازده سال و یک ماه بود. (از الاعلام زرکلی از البدایة و النهایة ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٠</span> و تاریخ بغداد ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٩١</span> و سیرالنبلاء ج <span class=\"hlight\" dir=\"rtl\">١٥</span> ودائرة المعارف الاسلامیة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٨</span> و کامل التواریخ ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٢</span> و النجوم الزاهرة ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٦</span> و ابن خلدون ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥٧</span>).<br></font></div>'),
(185869, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن احمدبن حسین بن علی بن یحیی بن محمد شبیبی ذماری . رجوع به علی شبیبی شود.<br></font></div>'),
(185870, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن احمدواسطی، مکنی به ابوالحسن . رجوع به علی واسطی شود.<br></font></div>'),
(185871, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن حسن بن أذین . نام محدثی است . (از منتهی الارب ).<br></font></div>'),
(185872, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن اسماعیل بن احمدبن جعفربن محمدبن صالح بن حسان بن حصن عبدری، مشهور به ابن مقلة و مکنی به ابوالحسن . رجوع به علی عبدری شود.<br></font></div>'),
(185873, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن ایوب . وی زعیم قوم رامانیان بود و ذکر او در فارسنامه ٔ ابن بلخی چنین آمده است : «رامانیان، این قوم قبیله ٔ فضلویه بودند و زعیم ایشان پدر فضلویه بود نام او علی بن الحسن بن ایوب، و همگان شبانی کردندی ...». (از فارسنامه ٔ ابن البلخی چ کمبریج ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span>).<br></font></div>'),
(185874, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن برزنجی مدنی شافعی . رجوع به علی برزنجی شود.<br></font></div>'),
(185875, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن بویه دیلمی، ملقب به فخرالدوله . رجوع به فخرالدوله ٔ دیلمی شود.<br></font></div>'),
(185876, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن حبیب صقلی، مکنی به ابوالحسن . رجوع به علی صقلی (ابن حسن بن ...) شود.<br></font></div>'),
(185877, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن حسول، مکنی به ابوالقاسم . رقعه ای از وی که به صاحب بن عباد نوشته، در معجم الادباء نقل شده است . رجوع به معجم الادباء چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١١٥</span> شود.<br></font></div>'),
(185878, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن حسین بن محمد موصلی مصری شافعی خلعی، مکنی به ابوالحسن . رجوع به علی خلعی شود.<br></font></div>'),
(185879, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن خاطر جزیری مالکی . رجوع به علی جزیری شود.<br></font></div>'),
(185880, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن صالح نجار طائفی . رجوع به علی نجار شود.<br></font></div>'),
(185881, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن صدقه ٔ مصری یمانی حنفی، مشهور به امام بیرم پاشا. رجوع به علی بیرم شود.<br></font></div>'),
(185882, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن طوبی، مکنی به ابوالحسن . رجوع به علی طوبی شود.<br></font></div>'),
(185883, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن عبدالرحمان مقری، محمدبن جعفر تمیمی، مشهور به ابن النجار. صاحب «تاریخ کوفه » از وی یاد کند و گوید که در حلقه ٔ درس او بیش از هزار تن حاضر می شدند که برای آنها قرآن تدریس می کرد و بسیاری از قاریان بزرگ شاگرد وی بودند. (از معجم الادباء چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١١٣</span>).<br></font></div>'),
(185884, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن حسن، نام او علی بن عبداﷲبن محمدبن حسن جذامی مالقی نباهی، مشهور به ابن حسن و مکنی به ابوالحسن است . رجوع به علی مالقی (ابن عبداﷲبن محمدبن ...) شود.<br></font></div>'),
(185885, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن عبداﷲ عطاس حضرمی باعلوی . رجوع به علی عطاس شود.<br></font></div>'),
(185886, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن عجلان بن رمیثه ٔ حسنی حجازی، مکنی به ابوالقاسم . رجوع به علی حجازی (ابن حسن بن ...) شود.<br></font></div>'),
(185887, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن بن علان بن عبدالرحمان، مکنی به ابوالحسن . محدث و حافظ و مورخ . وی در سال <span class=\"hlight\" dir=\"rtl\">٣٥٢</span> هَ . ق . از دمشق به حلب سفر کرد. و در «اعلام زرکلی » سال وفات او <span class=\"hlight\" dir=\"rtl\">٣٥٥</span> ذکر شده است .او راست : تاریخ الجزیرة. (از معجم المؤلفین از تاریخ دمشق ابن عساکر ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩</span> و الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤</span>).<br></font></div>'),
(185888, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن علی کاشفی . رجوع به علی کاشفی شود.<br></font></div>'),
(185889, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن عروة مشرقی دمشقی حنبلی، مشهور به ابن زکنون و مکنی به ابوالحسن . رجوع به علی مشرقی شود.<br></font></div>'),
(185890, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن حسین بن عزالدین بن حسن بن محمدبن صلاح بن حسن بن جبریل حسنی یمنی شامی . رجوع به علی شامی شود.<br></font></div>'),
(185891, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن علی بن ابی بکربن محمد موصلی حنبلی، ملقب به عزالدین . رجوع به علی موصلی شود.<br></font></div>'),
(185892, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن علی بن ابی طالب علیهم السلام، مکنی به ابوالحسن و ابومحمد و ابوالقاسم و ابوبکر، و ملقب به سیدالعابدین و زین العابدین و زکی و امین و سجاد. امام چهارم از ائمه ٔ شیعه ٔ اثناعشریة. رجوع به ابوالحسن علی بن الحسین بن علی بن ...(ع ) و حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦١</span> و سایر صفحات شود.<br></font></div>'),
(185893, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن علی بن حسین بن خلف بن محمد ارموی، مشهور به ابن قاضی عسکر و ملقب به شرف الدین و مکنی به ابوالحسن . رجوع به علی ارموی شود.<br></font></div>'),
(185894, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن علی بن علان بن عبدالرحمان، مشهور به ابن حرانی و مکنی به ابوالحسن . رجوع به حرانی شود.<br></font></div>'),
(185895, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن علی بن محمدبن عبدالمعین بن عون هاشمی . آخرین ملک هاشمی در حجاز. رجوع به علی هاشمی (ابن حسین بن ...) شود.<br></font></div>'),
(185896, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن علی بن محمد بغدادی حائری، مشهور به درویش . رجوع به علی بغدادی شود.<br></font></div>'),
(185897, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن علی اصفهانی باقولی ضریر، مشهور به جامع و مکنی به ابوالحسن . نحوی بود. او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- کشف المشکلات و ایضاح المعضلات فی علل القرآن . <span class=\"hlight\" dir=\"rtl\">٢</span>- المجمل . رجوع به ابوالحسن (علی بن حسین ...) و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٧٥</span> و معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">١٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٤</span> و انباء الرواة قفطی ج <span class=\"hlight\" dir=\"rtl\">٢٨</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤</span> و بغیة الوعاة سیوطی ص <span class=\"hlight\" dir=\"rtl\">٣٣٥</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٢٦٣</span> و روضات الجنات خوانساری ص <span class=\"hlight\" dir=\"rtl\">٤٨٥</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٩٧</span>.<br></font></div>'),
(185898, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن حسین بن علی بیهقی حنفی، ملقب به علأالدین و مکنی به ابوالحسن . رجوع به علی بیهقی شود.<br></font></div>'),
(185899, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن حسین بن علی ترکی (علی بای ...)، مکنی به ابوالحسن . امیر تونس . رجوع به علی بای اول شود.<br></font></div>'),
(185900, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن علی عیسی، مشهور به ابن کوچک وراق . رجوع به علی عیسی شود.<br></font></div>'),
(185901, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن علی عیسی فراء، مکنی به ابوالحسن . رجوع به علی فراء شود.<br></font></div>'),
(185902, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن علی عوض مزیدی اسدی حلی . رجوع به علی عوض شود.<br></font></div>'),
(185903, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن عبدالعالی کرکی عاملی، مشهور به محقق ثانی و محقق کرکی و شخی علایی و مولی مروج . رجوع به علی کرکی شود.<br></font></div>'),
(185904, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن علی کرمانی . رجوع به علی کرمانی شود.<br></font></div>'),
(185905, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن علی مسعودی، مکنی به ابوالحسن . صاحب مروج الذهب . رجوع به مسعودی شود.<br></font></div>'),
(185906, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن قاسم بن منصوربن علی مصولی شافعی، مشهور به ابن شیخ عوینة و ملقب به زین الدین و مکنی به ابوالحسن . رجوع به علی موصلی شود.<br></font></div>'),
(185907, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن محمدبن احمدبن هیثم بن عبدالرحمان بن مروان بن عبداﷲبن مروان بن محمد (آخرین خلیفه ٔ اموی ) اصفهانی صاحب کتاب أغانی، مکنی به ابوالفرج . رجوع به ابوالفرج (علی بن ...) و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٧٨</span> و الفهرست طوسی ص <span class=\"hlight\" dir=\"rtl\">١٩٢</span> و وفیات الاعیان ابن خلکان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢١</span> و معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">١٣</span> ص <span class=\"hlight\" dir=\"rtl\">٩٤</span> و تاریخ بغداد خطیب بغدادی ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٩٨</span> و الفهرست ابن الندیم ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٥</span> و یتیمة الدهر ثعالبی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٩٦</span> و انباء الرواة قفطی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥١</span> و النجوم الزاهره ٔ ابن تغری ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٥</span> و میزان الاعتدال ذهبی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٣</span> و مرآةالجنان یافعی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٩</span> و المنتظم ابن جوزی ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٧١</span> و لسان المیزان ابن حجر ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢١</span> و الهدایه ٔ ابن کثیر ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٣</span> و شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٩</span> و المختصر فی اخبار البشر ابوالفداء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٤</span> و مفتاح السعاده ٔ طاش کبری ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٤</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٢٦</span> و <span class=\"hlight\" dir=\"rtl\">٤٣</span> و سایر صفحات، و کنوزالاجداد محمد کردعلی ص <span class=\"hlight\" dir=\"rtl\">١٥٩</span> و دراسة الاغانی شفیق جبری و معجم الاطباء احمد عیسی ص <span class=\"hlight\" dir=\"rtl\">٣٠٤</span> و مقدمه ٔ کتاب اغانی از شفیق جبری و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨١</span> و الذریعه ٔ آغابزرگ ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٤</span> و کتاب صاحب الاغانی ابوالفرج اصفهانی، ابن محمد احمد خلف اﷲ و فهرست الخدیویة ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span> و فهرست کتابخانه ٔ رضوی ص <span class=\"hlight\" dir=\"rtl\">١٠٩</span> و روضات الجنات خوانساری ص <span class=\"hlight\" dir=\"rtl\">٤٧٨</span> و فوائد الرضویه ٔ عباس قمی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٨</span> و سیرالنبلاء ذهبی ج <span class=\"hlight\" dir=\"rtl\">١٠</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٦</span> و الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span> و عیون التواریخ ابن شاکر کتبی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٦</span> و فهرس المؤلفین بالظاهریة.<br></font></div>'),
(185908, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن محمدبن عمر، مشهور به ابن مسلمة و ملقب به رئیس الرؤساء. وزیر القائم بامر اﷲ عباسی . رجوع به رئیس الرؤساء، و تجارب السلف نخجوانی ص <span class=\"hlight\" dir=\"rtl\">٢٥٦</span> شود.<br></font></div>'),
(185909, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن محمدبن محمد حسینی عاملی جزینی، مشهور به صائغ. رجوع به علی صائغ شود.<br></font></div>'),
(185910, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن محمد زینبی، مکنی به ابوالقاسم . رجوع به علی زینبی شود.<br></font></div>'),
(185911, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن محمد سغدی حنفی . رجوع به علی سغدی شود.<br></font></div>'),
(185912, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن محمودبن محمد رشید (علی بای ...)، مکنی به ابوالحسن . امیر تونس . رجوع به «علی بای دوم » شود.<br></font></div>'),
(185913, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن مکرم، مکنی به ابوالقاسم، و ملقب به ناصرالدین و مؤیدالدولة، و مشهور به ابن مکرم . وی فرزند ناصرالدوله و از ملوک عمان بود. شخصی کریم و بخشنده به شمار می رفت و مهیار دیلمی وی را مدح کرده . وی در سال <span class=\"hlight\" dir=\"rtl\">٤٢٨</span> هَ . ق . درگذشت . (از اعلام زرکلی از ابن خلدون ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٩٣</span> و دیوان مهیار دیلمی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥</span>).<br></font></div>'),
(185914, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن منصور حریری، مکنی به ابوالحسن . رجوع به علی حریری (ابن حسین بن ...) شود.<br></font></div>'),
(185915, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن حسین بن موسی بن بابویه قمی، مکنی به ابوالحسن و مشهور به ابن بابویه . رجوع به ابن بابویه و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٨١</span> و الفهرست طوسی ص <span class=\"hlight\" dir=\"rtl\">٩٣</span> و الفهرست ابن الندیم ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٦</span> و کتاب الرجال نجاشی ص <span class=\"hlight\" dir=\"rtl\">١٨٤</span> و فوائد الرضویه ٔ عباس قمی ص <span class=\"hlight\" dir=\"rtl\">٢٢٢</span> و روضات الجنات خوانساری ص <span class=\"hlight\" dir=\"rtl\">٣٧٧</span> و منتهی المقال ابوعلی ص <span class=\"hlight\" dir=\"rtl\">٢١٣</span> و منهاج المقال میرزا محمد ص <span class=\"hlight\" dir=\"rtl\">٢٣١</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٧٨</span>.<br></font></div>'),
(185916, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن موسی بن محمدبن موسی بن ابراهیم بن موسی کاظم بن جعفر الصادق بن محمد باقربن علی زین العابدین بن حسین بن علی بن ابی طالب علیهم السلام، مشهور به شریف مرتضی و علم الهدی، و مکنی به ابوالقاسم . رجوع به علم الهدی موسوی شود.<br></font></div>'),
(185917, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین، ملقب به غیاث الدین . رجوع به غیاث الدین علی بن کمال الدین حسین کاشانی شود.<br></font></div>'),
(185918, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن ذهلی أفطس، مکنی به ابوالحسن . رجوع به علی أفطس شود.<br></font></div>'),
(185919, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن رندی (امیر امام جلال الدین ...). رجوع به علی رندی شود.<br></font></div>'),
(185920, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن سنهوری شافعی، ملقب به نورالدین . رجوع به علی سنهوری شود.<br></font></div>'),
(185921, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن سیازی، رجوع به علی سیازی شود.<br></font></div>'),
(185922, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن شافعی، مشهور به بیهقی . رجوع به علی بیهقی (ابن حسن ...) شود.<br></font></div>'),
(185923, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن شقیق خراسانی، مکنی به ابوعبدالرحمان . از روات حدیث بود. و نیز رجوع به ابوعبدالرحمان (علی بن ...) شود.<br></font></div>'),
(185924, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن صقلی قزوینی . رجوع به علی صقلی شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(185925, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن (یا حسین ) علوی بغدادی، مکنی به ابوالقاسم و مشهور به ابن أعلم . ریاضی دان و منجم مشهور قرن چهارم هجری . رجوع به ابن اعلم و علوی (علی بن حسن ...) و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٦٤</span> و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٢١</span> و اعیان الشیعة ج <span class=\"hlight\" dir=\"rtl\">٤١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥</span> و الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٨٠</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨٢</span>.<br></font></div>'),
(185926, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن قهستانی، مکنی به ابوبکر و ملقب به عمیدالملک . عارض سپاه محمود غزنوی و از بزرگان فضلا و ادبای خراسان و نیز رئیس دارالانشاء و ندیم محمدبن محمود غزنوی و ممدوح فرخی شاعر است و چهار قصیده در دیوان حاضر فرخی (ص <span class=\"hlight\" dir=\"rtl\">١٦٩</span>، <span class=\"hlight\" dir=\"rtl\">١٩٥</span>، <span class=\"hlight\" dir=\"rtl\">٣١٧</span>، <span class=\"hlight\" dir=\"rtl\">٣٢٣</span> چ دبیرسیاقی ) در مدح او آمده است . علی قهستانی بعدها به خدمت سلاجقه پیوست و در سال <span class=\"hlight\" dir=\"rtl\">٤٣١</span> هَ . ق . در آن دولت به مقامات جلیله رسید. سوزنی در حق فرخی و این ممدوح گوید:<br>فرخی هندی غلامی از قهستانی بخواست <br>که غلام ترک دادش خوش لقا و خوش کلام .<br>رجوع به ابوبکر (علی بن حسن ...) و معجم الادباء چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١١٦</span>، و دیوان فرخی چ محمددبیرسیاقی شود.<br></font></div>'),
(185927, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن کاتب . از شعرای مصر بودو دیوان او سی ورقه است . (از الفهرست ابن الندیم ).<br></font></div>'),
(185928, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن کوفی، مکنی به ابوالشعثاء. محدث بود و از حفص بن غیاث روایت کرد. و رجوع به ابوالشعثاء (علی بن ...) شود.<br></font></div>'),
(185929, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن همدانی، مشهور به ابن فاکهی و مکنی به ابوالفضل . رجوع به علی فاکهی شود.<br></font></div>'),
(185930, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسن هنائی، مشهور به کراع النمل و دوسی، و مکنی به ابوالحسن . رجوع به علی کراع النمل شود.<br></font></div>'),
(185931, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن حسین . یکی از علمای فقه از مردم سَکَلکندبود، و آن شهری است به طخارستان . (از منتهی الارب ).<br></font></div>'),
(185932, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن وافد، مکنی به ابوالحسن . از تابعیان . رجوع به ابوالحسن (علی بن ...) شود.<br></font></div>'),
(185933, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین آمدی نحوی، مکنی به ابوالحسن . رجوع به علی آمدی (ابن حسین ...) شود.<br></font></div>'),
(185934, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن احمدبن ابراهیم عکبری، مشهور به ابن جدا و مکنی به ابوالحسن . رجوع به علی عکبری شود.<br></font></div>'),
(185935, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن احمدبن حسن بن قاسم بن حسن بن علی همدانی، مشهور به فلکی و مکنی به ابوالفضل . رجوع به علی فلکی شود.<br></font></div>'),
(185936, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن جنید رازی، مشهور به مالکی و مکنی به ابوالحسن . رجوع به علی رازی شود.<br></font></div>'),
(185937, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن حرب، مکنی به ابوعبید. فقیه و مجتهد. وی در سال <span class=\"hlight\" dir=\"rtl\">٢٣٢</span> هَ . ق . در بغداد متولد شد. سپس به مصر رفت و امر قضاوت را در آنجا عهده دار گشت، ولی پس از مدتی از این منصب معزول شد و به بغداد بازگشت و در سال <span class=\"hlight\" dir=\"rtl\">٣١٩</span> درگذشت . او را تصانیفی است . (از معجم المؤلفین از اعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٨٧</span>). و نیز رجوع به ابوعبید (علی بن ...) شود.<br></font></div>'),
(185938, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن حسان بن باقی قرشی . رجوع به علی قرشی شود.<br></font></div>'),
(185939, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن حمویه بن زید، مکنی به ابوالحسین . از صوفیان بود و در سال <span class=\"hlight\" dir=\"rtl\">٣٨٤</span> هَ . ق . متولد شد. او راست : بهجة الاسرار در تصوف . (از معجم المؤلفین از کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٢٥٧</span>).<br></font></div>'),
(185940, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن حیدر رضا عاملی رکینی . رجوع به علی رکینی شود.<br></font></div>'),
(185941, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن حیدرةبن محمدبن عبداﷲبن محمد، مکنی به ابوالحسن . از فرزندان عقیل بن ابی طالب . رجوع به علی عقیلی شود.<br></font></div>'),
(185942, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن سلام شرغی . رجوع به علی شرغی شود.<br></font></div>'),
(185943, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن سلیمان اسپارته ای رومی حنفی (علی رضا...)، مشهور به وصفی . رجوع به علی رضابن حسین ... شود.<br></font></div>'),
(185944, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن صلاح بن بدرالدین حسنی صنعانی مؤیدی، ملقب به جمال الدین . رجوع به علی مؤیدی شود.<br></font></div>'),
(185945, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسین بن طریف کوفی، مکنی به ابومنذر. رجوع به علی کوفی شود.<br></font></div>'),
(185946, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صوفی .علی بن محمدبن علی بن محمد علوی عمری شجری، ملقّب به نجم الدین و مکنّی به ابوالحسن و مشهور به ابن صوفی . رجوع به علی شجری (ابن محمدبن علی بن محمد...) شود.<br></font></div>'),
(185947, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صدری قونوی، ملقّب به بدرالدین . رجوع به علی قونوی شود.<br></font></div>'),
(185948, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صدقه، ملقّب به مؤتمن الدوله . وی از خاندانی بزرگ و مردی نیکوسیرت و نیکوخلق و متعبد و متدین بود و با وجودی که از قوانین وزارت هیچ نمی دانست، المقتفی باﷲ خلیفه ٔ عباسی پس از علی بن طراد زینبی، وزارت را به او داد. و بعد از او ابن هبیرة وزیر شد. (از تجارب السلف نخجوانی ص <span class=\"hlight\" dir=\"rtl\">٣٠٦</span>).<br></font></div>'),
(185949, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صدقة. نام او علی بن احمد مصری شامی شافعی اشعری، و مشهور به ابن صدقة است . رجوع به علی مصری (ابن احمد مصری ...) شود.<br></font></div>'),
(185950, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صدقةبن علی بانقوسی حلبی مصری شافعی، ملقّب به علاءالدین . رجوع به علی بانقوسی شود.<br></font></div>'),
(185951, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صدقةبن منصور سرمینی، مکنّی به ابوالفتح . رجوع به علی سرمینی شود.<br></font></div>'),
(185952, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صعب بن بکر. جد جاهلی . رجوع به علی بن بکربن وائل شود.<br></font></div>'),
(185953, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صفار. علی بن یوسف بن شیبان ماردینی، مشهور به ابن صفار و ملقّب به جلال الدین . رجوع به ابن صفار و نیز به علی بن یوسف بن شیبان ... شود.<br></font></div>'),
(185954, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صُفدان علی بن محمدبن موسی بن سعیدبن مهدی انباری مکنّی به ابوالقاسم و ملقّب به حُسنُس و مشهور به ابن صفدان . رجوع به علی حسنس شود.<br></font></div>'),
(185955, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صفدربن صالح رضوی قمی کشمیری . رجوع به علی رضوی شود.<br></font></div>'),
(185956, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صلاح ... نام او علی بن محمد (صلاح الدین الناصر)بن علی (المهدی )بن محمد حجاج بن یوسف زیدی، و مکنّی به ابوالحسن و ملقّب به نجاح الدین و المنصور، و مشهور به ابن صلاح است . وی امیر یمن بود. رجوع به علی زیدی (ابن محمدبن علی بن ...) شود.<br></font></div>'),
(185957, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صلاح بن علی بن محمدبن عبداﷲ صعدی یمانی زیدی . رجوع به علی صعدی شود.<br></font></div>'),
(185958, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صلاح الدین بن علی بن صلاح الدین حسنی کوکبانی، ملقّب به جمال الدین . رجوع به علی کوکبانی شود.<br></font></div>'),
(185959, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صلاح الدین سخومی . رجوع به علی سخومی شود.<br></font></div>'),
(185960, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صلاح الدین یوسف ایوبی، مشهور به ملک افضل نورالدین . رجوع به علی ایوبی شود.<br></font></div>'),
(185961, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صدرالدین موسی (شیخ خواجه ...) وی از صوفیان سلسله ٔ صفویه است که پس از پدرش صدرالدین موسی، به ارشاد طبقه ٔ صوفیه منصوب گشت . و در اواخر عمر به قصد حج به زیارت کعبه رفت و فرزندش شیخ ابراهیم را به جانشینی خویش گماشت و در بازگشت از حج، در راه مریض شد و درگذشت . (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢٣</span>). و رجوع به علی سیاه پوش شود.<br></font></div>'),
(185962, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صیرفی . علی بن داوودبن ابراهیم جوهری، مشهور به ابن صیرفی .رجوع به علی جوهری (ابن داوودبن ابراهیم ...) شود.<br></font></div>'),
(185963, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صیرفی . علی بن عثمان بن عمربن صالح دمشقی شافعی، مشهور به ابن صیرفی و ملقّب به علاءالدین و مکنّی به ابوالحسن . رجوع به علی صیرفی (ابن عثمان بن عمربن ...) شود.<br></font></div>'),
(185964, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ضائع. علی بن محمدبن علی بن یوسف اشبیلی، مشهور به ابن ضائع و مکنّی به ابوالحسن . رجوع به علی اشبیلی (ابن محمدبن علی بن ...) شود.<br></font></div>'),
(185965, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن طالب هندی پیشاوری (علی رضا...). رجوع به علی رضابن طالب ... شود.<br></font></div>'),
(185966, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن طاووس . علی بن موسی بن جعفربن محمدبن احمدبن طاووس علوی فاطمی، مشهور به ابن طاووس و مکنّی به ابوالقاسم وملقب به رضی الدین . رجوع به ابن طاووس و نیز به علی بن موسی بن جعفربن ... شود.<br></font></div>'),
(185967, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن طاهر، مشهور به سیدمرتضی علم الهدی . برادر سیدرضی .رجوع به علم المهدی موسوی (علی بن ابی احمد...) شود.<br></font></div>'),
(185968, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن طاهربن جعفر سلمی، مکنّی به ابوالحسن . رجوع به علی سلمی (ابن طاهر...) شود.<br></font></div>'),
(185969, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن طاهربن معوضةبن تاج الدین قرشی اموی، مکنّی به ابوالحسن و ملقب به الملک المجاهد. یکی از مؤسسین دولت بنی طاهر در یمن . رجوع به علی طاهری (ابن طاهربن معوضة...) شود.<br></font></div>'),
(185970, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن طبیب . علی بن نصر، مشهور به ابن طبیب و مکنّی به ابوالحسن . رجوع به علی بن نصر شود.<br></font></div>'),
(185971, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن طرادبن دبیس اسدی، مکنّی به ابوالحسن . رجوع به علی اسدی (ابن طراد...) شود.<br></font></div>'),
(185972, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن طرادبن محمد زینبی، مکنّی به ابوالقاسم و ملقّب به شرف الدین . رجوع به علی زینبی شود.<br></font></div>'),
(185973, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن طرخان . علی بن حسن، مکنّی به ابوالحسن و مشهور به ابن طرخان . از استادان موسیقی و غناء. رجوع به ابن طرخان (ابوالحسن علی ...) شود.<br></font></div>'),
(185974, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن طلحة، مکنّی به ابوالحسن . تابعی است . و نیز رجوع به ابوالحسن (علی بن ...) شود.<br></font></div>'),
(185975, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن طلحةبن طاهر ذوالیمینین . وی پس از اینکه پدرش طلحة در سال <span class=\"hlight\" dir=\"rtl\">٢١٣</span> هَ . ق . در خراسان درگذشت، قائم مقام وی شد و در نواحی نیشابور با جمعی از خوارج جنگید و شهید گشت . (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٤</span>).<br></font></div>'),
(185976, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شیخ بن محمدبن علی سقاف علوی، مشهور به ابن شهاب الدین . رجوع به علی سقاف شود.<br></font></div>'),
(185977, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن شبیه . علی بن عبداﷲبن علی بن حسین بن زیدبن علی بن حسین بن زیدبن علی بن حسین بن علی بن ابی طالب علیهم السلام، علوی، مکنّی به ابوالقاسم و مشهور به الشبیه یا شبیه . رجوع به علی علوی (ابن عبداﷲبن علی بن ...) شود.<br></font></div>'),
(185978, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شجاع مصقلی . رجوع به علی مصقلی شود.<br></font></div>'),
(185979, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شداد، مکنّی به ابوکردوس . محدث است . رجوع به ابوکردوس شود.<br></font></div>'),
(185980, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شعبان (الملک الاشرف ).ابن حسین بن محمدبن قلاوون، ملقّب به الملک المنصور. از سلاطین دولت قلاوونیة در مصر و شام . رجوع به علی قلاوونی شود.<br></font></div>'),
(185981, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شعبان اقسرائی رومی حنفی . رجوع به علی اقسرائی شود.<br></font></div>'),
(185982, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شعیب سقا. از مشایخ تصوف . رجوع به علی سقا شود.<br></font></div>'),
(185983, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شفیعبن اکبر موسوی جابلقی بروجردی (علی اصغر...). رجوع به علی اصغر بروجردی شود.<br></font></div>'),
(185984, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شلبی شبینی شافعی . رجوع به علی شبینی شود.<br></font></div>'),
(185985, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شلویة. وی ازمشایخ متصوفه بود و بیشتر در کوهها و صحراها می گشت و شیخ ابوعبداﷲ خفیف درباره ٔ او حکایتهائی دارد که در نفحات الانس آمده است . (از نفحات الانس جامی ص <span class=\"hlight\" dir=\"rtl\">٢٤٤</span>).<br></font></div>'),
(185986, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن شمس الدین بن محمدبن زهران بن علی شافعی رشیدی، مشهور به خضری . رجوع به علی خضری شود.<br></font></div>'),
(185987, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شمعة. علی بن محمدبن عثمان بن محمدبن رجب بن علاءالدین دمشقی شافعی، مشهور به ابن شمعة. رجوع به علی دمشقی (ابن محمدبن عثمان بن ...) شود.<br></font></div>'),
(185988, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شوکانی . علی بن محمدبن علی بن محمدبن علی بن عبداﷲ یمنی صنعانی حنبلی، مشهور به ابن شوکانی . رجوع به علی شوکانی (ابن محمد بن علی بن محمدبن ...) شود.<br></font></div>'),
(185989, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شهاب . علی بن شهاب بن حسن بن محمد همدانی مسعودی، مشهور به ابن شهاب . رجوع به علی مسعودی (ابن شهاب بن حسن بن محمد...) شود.<br></font></div>'),
(185990, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شیبان بن محرزبن عمروبن عبداﷲبن عمروبن عبدالعزیزبن سحیم حنفی سحیمی یمامی، مکنّی به ابویحیی . رجوع به علی سحیمی شود.<br></font></div>'),
(185991, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن طلحةبن کردان واسطی، مکنّی به ابوالقاسم . رجوع به علی واسطی شود.<br></font></div>'),
(185992, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شیخ عوینة. علی بن حسین بن قاسم بن منصوربن علی موصلی شافعی، مشهور به ابن شیخ عوینة و ملقّب به زین الدین و مکنّی به ابوالحسن . رجوع به علی موصلی (ابن حسین بن قاسم بن ...) شود.<br></font></div>'),
(185993, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شیران همدانی (علی اکبر...)، ملقّب به صدرالاسلام . رجوع به علی اکبر همدانی شود.<br></font></div>'),
(185994, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صادق بن محمدبن ابراهیم بن حسین بن محمد داغستانی شماخی حنفی . رجوع به علی شماخی شود.<br></font></div>'),
(185995, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صالح بن ابی لیث بن أسعدبن فرج بن یوسف طرطوشی دانی، مشهور به ابن عزالناس و مکنّی به ابوالحسن . رجوع به علی دانی شود.<br></font></div>'),
(185996, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صالح بن حی . وی از متکلمین زیدیه و برادر حسن بن صالح است . (از الفهرست ابن الندیم ).<br></font></div>'),
(185997, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صالح بن صالح بن حی، مکنّی به ابومحمد. تابعی است . و نیز رجوع به ابومحمد (علی بن ...) شود.<br></font></div>'),
(185998, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن صالح بن عبدالفتاح جارم . رجوع به علی جارم شود<br></font></div>'),
(185999, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صالح بن محمدبن علی بن ابی الرجال صنعانی . رجوع به علی صنعانی شود.<br></font></div>'),
(186000, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صالح جرجانی . رجوع به علی جرجانی (ابن صالح ...) شود.<br></font></div>'),
(186001, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صالح رومی، ملقّب به عبدالواسع علیسی . رجوع به علی علیسی شود.<br></font></div>'),
(186002, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صباغ . علی بن حمید صعیدی، مکنّی به ابوالحسن و مشهور به ابن صباغ یا ابن حمزه . رجوع به علی صعیدی (ابن حمید...) شود.<br></font></div>'),
(186003, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صباغ . علی بن محمدبن احمد، ملقّب به نورالدین و مشهور به ابن صباغ . رجوع به علی بن محمدبن ... و نیز به ابن صباغ (شیخ نورالدین علی بن ...) شود.<br></font></div>'),
(186004, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن صدرالدین بن عصام الدین . او راست : حاشیه بر شرح جد خود عصام الدین بر رساله ٔ استعاره ٔ ابوالقاسم لیثی سمرقندی . (از کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">٨٤٥</span>).<br></font></div>'),
(186005, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان بن هارون بن عیسی بن هارون بغدادی شافعی، مکنّی به ابوالخطاب . رجوع به علی بغدادی شود.<br></font></div>'),
(186006, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالحمیدبن فخاربن معد موسوی حلی، مشهور به مرتضی . رجوع به علی مرتضی شود.<br></font></div>'),
(186007, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالحمید مغربی . رجوع به علی مغربی شود.<br></font></div>'),
(186008, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن عبدالرحمان . تابعی است . (منتهی الارب ).<br></font></div>'),
(186009, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان بن احمدبن یونس بن عبدالاعلی صدفی مصری، مکنّی به ابوالحسن . منجم مشهور قرن چهارم هجری است که درشوال سال <span class=\"hlight\" dir=\"rtl\">٣٩٩</span> هَ . ق . در مصر درگذشت . او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- تاریخ اعیان مصر. <span class=\"hlight\" dir=\"rtl\">٢</span> - زیج ابن یونس، در چهار مجلد، که آن را برای العزیزباﷲ نوشته است . <span class=\"hlight\" dir=\"rtl\">٣</span>- العقود والسعود فی اوصاف العود. <span class=\"hlight\" dir=\"rtl\">٤</span> - غایةالانتفاع فی معرفة الدائر و السمت قبل الارتفاع . و نیز او را اشعاری است . رجوع به ابن یونس (ابوالحسن علی بن ...) و نیز به کتب ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١١٨</span>. سیرالنبلاء ذهبی ج <span class=\"hlight\" dir=\"rtl\">١١</span>ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>. الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩٥</span>. فهرس مخطوطات الظاهریة. وفیات الاعیان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٧٤</span>. تاریخ الحکماء قفطی ص <span class=\"hlight\" dir=\"rtl\">٢٣٠</span>. میزان الاعتدال ذهبی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٧</span>. المختصر فی اخبارالبشر ابوالفداء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span>. شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٦</span> . لسان المیزان ابن حجر ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٢</span>. مرآةالجنان یافعی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥١</span>. حسن المحاضره ٔ سیوطی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٣</span>. کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٣٠٤</span> و سایر صفحات . ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٨</span>. هدیةالعارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨٤</span>.<br></font></div>'),
(186010, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان بن بَرنی . محدث است . (از منتهی الارب ) (از تاج العروس ).<br></font></div>'),
(186011, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان بن تمیم طنجی مکناسی . رجوع به علی طنجی شود.<br></font></div>'),
(186012, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان بن حسین عثمانی صفدی شافعی، ملقّب به علاءالدین . رجوع به علی صفدی شود.<br></font></div>'),
(186013, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن عبدالرحمان بن شبیب بن حمدان بن شبیب حنبلی حرانی، ملقّب به نورالدین . رجوع به علی حرانی شود.<br></font></div>'),
(186014, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان بن عیسی بن عروةبن جراح قنائی، مکنّی به ابوالحسن . رجوع به علی قنائی شود.<br></font></div>'),
(186015, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان بن محمدبن محمدبن اسماعیل شلقامی قاهری شافعی، ملقب به نورالدین و مکنّی به ابوالحسن . رجوع به علی قاهری شود.<br></font></div>'),
(186016, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان بن محمدخطیب شربینی مصری شافعی، مکنّی به ابوالحسن . رجوع به علی شربینی شود.<br></font></div>'),
(186017, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان بن محمد خفاف مالکی جزائری . رجوع به علی جزائری شود.<br></font></div>'),
(186018, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان بن محمد نظاری، امیر یمن . رجوع به علی نظاری شود.<br></font></div>'),
(186019, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان بن مهدی بن عمران اشبیلی، مکنّی به ابوالحسن و مشهور به ابن اخضر. رجوع به علی اشبیلی شود.<br></font></div>'),
(186020, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالحمید آلوسی . ملقّب به علاءالدین . رجوع به علی آلوسی شود.<br></font></div>'),
(186021, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان بن یوسف انصاری طلیطلی، مشهور به ابن لونقة و مکنّی به ابوالحسن . رجوع به علی طلیطلی شود.<br></font></div>'),
(186022, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان بن یونس بن عبدالاعلی مصری، مکنّی به ابوالحسن و مشهور به ابن یونس . منجم قرن چهارم هجری . رجوع به ابن یونس و نیز به علی بن عبدالرحمان بن احمدبن یونس ... شود.<br></font></div>'),
(186023, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان اندلسی، مشهور به ابن هذیل . رجوع به علی اندلسی شود.<br></font></div>'),
(186024, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان تلمسانی . رجوع به علی تلمسانی شود.<br></font></div>'),
(186025, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان خزاز شوشی، مکنّی به ابوالعلاء. رجوع به علی خزاز شود.<br></font></div>'),
(186026, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان سعدی، مشهور به ابن قطاع و مکنّی به ابوالقاسم . رجوع به ابن قطاع (ابوالقاسم علی بن جعفر...) و معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١١٩</span> و الخریده ٔ عماد ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">٢١</span> شود.<br></font></div>'),
(186027, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحمان صانع. رجوع به علی صانع شود.<br></font></div>'),
(186028, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحیم بن حسن بن عبدالملک بن ابراهیم سلمی عباسی رقی بغدادی، مشهور به ابن عصار و مکنّی به ابوالحسن . رجوع به علی عباسی شود.<br></font></div>'),
(186029, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحیم بن محمد کندی، آل باکثیر. رجوع به علی کندی شود.<br></font></div>'),
(186030, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالرحیم سلمی، مکنّی به ابوالحسن و مشهور به ابن قصار. ادیب و لغوی و خطّاط. رجوع به ابن قصار (ابوالحسن علی بن ...) شود.<br></font></div>'),
(186031, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن عبدالستار قوصی . رجوع به علی قوصی شود.<br></font></div>'),
(186032, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالسلام تسولی مالکی، مکنّی به ابوالحسن . رجوع به علی تسولی شود.<br></font></div>'),
(186033, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالصادق بن احمدبن عبدالصادق بن محمدبن عبداﷲ عیادی مالکی، مکنّی به ابوالحسن . رجوع به علی عیادی شود.<br></font></div>'),
(186034, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عباس بن حسین زیدی، ملقب به المنصور باﷲ. امام زیدی یمن . رجوع به علی زیدی (ابن عباس بن ...) شود.<br></font></div>'),
(186035, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن طلق بن منذربن قیس بن عمربن عبداﷲبن عمربن عبدالعزی بن سحیم حنفی سحیمی یمامی . رجوع به علی سحیمی شود.<br></font></div>'),
(186036, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن طیب بن عبدالرحمان شرفی اندلسی، مکنّی به ابوالحسن . رجوع به علی اندلسی شود.<br></font></div>'),
(186037, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ظافربن حسین أزدی مصری مالکی، مکنّی به ابوالحسن و ملقّب به جمال الدین . رجوع به علی أزدی شود.<br></font></div>'),
(186038, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ظاهر مطیری اسدی حلی . رجوع به علی حلی شود.<br></font></div>'),
(186039, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ظاهر وتری حسنی مدنی، ملقّب به نورالدین و مکنّی به ابوالحسن . رجوع به علی مدنی شود.<br></font></div>'),
(186040, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ظبیان، مکنّی به ابوالحسن، تابعی است . و رجوع به ابوالحسن (علی بن ...) شود.<br></font></div>'),
(186041, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ظهیربن شهاب مصری، مشهور به ابن کفتی و ملقّب به نورالدین، مکنّی به ابوالحسن . رجوع به علی مصری شود.<br></font></div>'),
(186042, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ظهیرالدین ابی منصور فرامرزبن علاءالدوله ابی جعفرمحمد، معروف به کاکویه . یکی از دیالمه ٔ کاکویه . رجوع به علی بن فرامرزبن علاءالدوله ... شود.<br></font></div>'),
(186043, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ظهیرة. علی بن جاراﷲ بن محمدبن أبی الیمن بن ابی بکربن علی بن محمدبن محمدبن حسین بن احمد قرشی محزومی حنفی، مشهور به ابن ظهیرة.رجوع به علی مخزومی (ابن جاراﷲبن محمدبن ...) شود.<br></font></div>'),
(186044, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عاصم بن صهیب واسطی، مکنّی به ابوالحسن . رجوع به علی واسطی (ابن عاصم ...) شود.<br></font></div>'),
(186045, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن عباد. علی بن محمدبن ابراهیم بن عبداﷲبن مالک بن عباد نفری رندی مالکی، مشهور به ابن عباد.رجوع به علی نفری (ابن محمدبن ابراهیم بن ...) شود.<br></font></div>'),
(186046, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عباس بن ابراهیم بن علی بن عبدالرحمان بن قاسم بن حسن بن علی بن أبی طالب، مکنّی به ابوالحسن . فقیه و اصولی بود و در حدود سال <span class=\"hlight\" dir=\"rtl\">٣٤٠</span> هَ . ق . درگذشت . او راست : <span class=\"hlight\" dir=\"rtl\">١</span> - اختلاف اهل البیت . <span class=\"hlight\" dir=\"rtl\">٢</span> - مایجب أن یعمله المجتهد. (ازمعجم المؤلفین بنقل از تراجم الرجال جنداری ص <span class=\"hlight\" dir=\"rtl\">٢٤</span>).<br></font></div>'),
(186047, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عباس بن اسماعیل بن ابی سهل بن نوبخت نوبختی، مکنّی به ابوالحسین . رجوع به علی نوبختی (ابن عباس بن ...) شود.<br></font></div>'),
(186048, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عباس بن جریح بغدادی، مشهور به ابن رومی و مکنّی به ابوالحسن . شاعر رومی الاصل . متولد در رجب سال <span class=\"hlight\" dir=\"rtl\">٢٢١</span> هَ . ق . در بغداد، و متوفی در جمادی الاولای <span class=\"hlight\" dir=\"rtl\">٢٨٣</span> یا <span class=\"hlight\" dir=\"rtl\">٢٨٤</span> یا <span class=\"hlight\" dir=\"rtl\">٢٨٦</span> هَ . ق . رجوع به ابن رومی و نیز به مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١١٤</span>. سیرالنبلاء ذهبی ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">١١٧</span>. الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٠</span> فهرس المؤلفین بالظاهریة. الفهرست ابن الندیم ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٥</span>. تاریخ بغداد خطیب بغدادی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>. العمده ٔ ابن رشیق ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٤</span>. الکامل ابن أثیر ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٩</span>. البدایه ٔ ابن کثیر. ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٤</span>. اللباب ابن اثیر ج <span class=\"hlight\" dir=\"rtl\">١</span>ص <span class=\"hlight\" dir=\"rtl\">٤٨</span>. المختصر فی اخبارالبشر ابوالفداء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٠</span>. کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">٧٦٦</span>. ابن الرومی نوشته ٔ عباس عقاد. امراءالشعرالعربی انیس مقدسی ص <span class=\"hlight\" dir=\"rtl\">٢٧٢</span>. اعیان الشیعة ج <span class=\"hlight\" dir=\"rtl\">٤١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨١</span>. ابن الرومی نوشته ٔ محمد عبدالغنی حسن . ابن الرومی نوشته ٔ عمر فروخ . فهرس المخطوطات المصوره ٔ سید ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥١</span>. فهرس الخدیویة ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٣</span>. رسالةالتشبیه فی شعر ابن المعتز و ابن الرومی . مراجعات فی الاداب و الفنون عباس عقاد ص <span class=\"hlight\" dir=\"rtl\">١٥٩</span>. الحیاة الادبیة فی العصر العباسی نگارش محمد عبدالمنعم خفاجی ص <span class=\"hlight\" dir=\"rtl\">١٩٩</span>. روضات الجنات خوانساری ص <span class=\"hlight\" dir=\"rtl\">٤٧٣</span>. ساعات بین الکتب عباس عقاد ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٩</span>. تاریخ الشعرالعربی بهیتی ص <span class=\"hlight\" dir=\"rtl\">٥١٧</span>. حصادالهشیم ابراهیم مازنی ص <span class=\"hlight\" dir=\"rtl\">٢٩٨</span>.<br></font></div>'),
(186049, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شاه مظفربن مبارزالدین (شاه ...) رجوع به علی بن مظفربن مبارزالدین شود.<br></font></div>'),
(186050, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عباس بن راضی بن حسن أبوطبیخ . ادیب و شاعر، متولد در سال <span class=\"hlight\" dir=\"rtl\">١٣١١</span> هَ . ق . در نجف . وی در شوال سال <span class=\"hlight\" dir=\"rtl\">١٣٦١</span> هَ . ق . درگذشت در حالی که سن او پنجاه سال و اندی بود. او را دیوان شعری است . (از معجم المؤلفین بنقل از اعیان الشیعة ج <span class=\"hlight\" dir=\"rtl\">٤١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٤</span>).<br></font></div>'),
(186051, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عباس مجوسی، مشهور به ابن مجوس . رجوع به ابن المجوس و به علی مجوسی شود.<br></font></div>'),
(186052, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالاعلی، مکنّی به ابوالحسن . تابعی است و زهیر از او روایت کند. رجوع به ابوالحسن (علی بن ...) شود.<br></font></div>'),
(186053, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالباقی بن احمد رومی حنفی، مشهور به ظریفی . رجوع به علی ظریفی شود.<br></font></div>'),
(186054, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ناصربن محمدبن احمد بلیسی مکی شافعی حجازی، ملقّب به علاءالدین و مکنّی به ابوالحسن و مشهور به ابن ناصر. رجوع به علی حجازی شود.<br></font></div>'),
(186055, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ناصرالدین بن احمد طرابلسی دمشقی حنفی . رجوع به علی طرابلسی شود.<br></font></div>'),
(186056, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالباقی بن قاضی خان، ملقّب به علأالدین . او راست : کنزاللاَّلی فی شرح بدءالامالی، که در سال <span class=\"hlight\" dir=\"rtl\">٩٧٩</span> هَ . ق . در مدینه از تألیف آن فراغت یافت . (از معجم المؤلفین بنقل از ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨٧</span>).<br></font></div>'),
(186057, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالبر حسنی شافعی . مشهور به ونائی و ملقّب به جمال الدین . رجوع به علی ونائی شود.<br></font></div>'),
(186058, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالجباربن سلامه ٔ هذلی توسنی، مکنّی به ابوالحسن . رجوع به علی هذلی شود.<br></font></div>'),
(186059, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالجلیل بیاضی . رجوع به علی بیاضی شود.<br></font></div>'),
(186060, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالحسین بن سلطان موسوی حسینی . رجوع به علی موسوی شود.<br></font></div>'),
(186061, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالحسین بن علی اصغر حائری ایروانی . رجوع به علی حائری شود.<br></font></div>'),
(186062, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالحق حجاجی مالکی قوصی . رجوع به علی قوصی شود.<br></font></div>'),
(186063, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ساعاتی، علی بن رستم بن هردوز، مشهور به ابن ساعاتی و ملقب به بهاءالدین و مکنی به ابوالحسن . رجوع به ابن ساعاتی و علی بن رستم بن ... شود.<br></font></div>'),
(186064, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن زکریابن مسعود حنفی (متوفی در سال <span class=\"hlight\" dir=\"rtl\">٦٨٦</span> هَ . ق . در قدس ). او راست : شرح معانی الاَّثار طحاوی . (از معجم المؤلفین از ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠٥</span>).<br></font></div>'),
(186065, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن زکریا مسبحی . رجوع به علی مسبحی شود.<br></font></div>'),
(186066, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زکریا نیشابوری، مکنی به ابوالحسن . رجوع به علی نیشابوری شود.<br></font></div>'),
(186067, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زکی بوسنوی رومی حنفی . رجوع به علی بوسنوی شود.<br></font></div>'),
(186068, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زیاد اسکندری، مشهور به محتسب و مکنی به ابوالحسن . رجوع به علی محتسب شود.<br></font></div>'),
(186069, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زیاد تمیمی، مکنی به ابوالحسن . یکی از نقله ٔ کتب فارسی به عربی است . رجوع به ابوالحسن (علی بن زیاد...) شود.<br></font></div>'),
(186070, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زیاد تونسی، مکنی به ابوالحسن . رجوع به علی تونسی شود.<br></font></div>'),
(186071, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زیدبن ابی ملیکة زهیربن عبداﷲبن جدعان، مکنی به ابوالحسن و مشهور به ابن جدعان . وی فقیه و نابینا بود و روایت حدیث می کرد ولی از محدثان موثوق نبود. اصل او از بصره است و در سال <span class=\"hlight\" dir=\"rtl\">١٢٩</span> هَ . ق . درگذشت . (از الاعلام زرکلی از خلاصة تذهیب الکمال ص <span class=\"hlight\" dir=\"rtl\">٢٣٢</span> و التبیان و تاریخ الاسلام الذهبی ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٣</span>).<br></font></div>'),
(186072, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زیدبن حسن شظبی صریمی صنعانی . رجوع به علی صنعانی شود.<br></font></div>'),
(186073, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زیدبن محمدبن حسین بن سلیمان بن أیوب انصاری أوسی خزیمی بیهقی شافعی، مکنی به ابوالحسن . رجوع به علی بیهقی و ظهیرالدین (ابوالحسن علی بن ...) شود.<br></font></div>'),
(186074, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زیل، مکنی به ابوالحسن، علی بن سهل طبری . کاتب مازیاربن قارن است . وی چون به دست خلیفه مسلمانی گرفت، مقرب شد و فضل او پیدا گشت و متوکل او را در جمله ٔ ندماء درآورد. او راست : کتاب فردوس الحکمة و تحفة الملوک، و کناش الحضرة، و منافع الاطعمة و الاشربة و العقاقیر (از الفهرست ابن الندیم ). اما این مرد همان علی بن ربن طبری است که ابن الندیم در اینجا اشتباهاً نام پدر او را «زیل » نوشته است . و کلمه ٔ ربن همان «ربنا» است در زبان یهود. (یادداشت مرحوم دهخدا). رجوع به ابن ربن شود.<br></font></div>'),
(186075, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زین . در عجایب البلدان خاطره ای از وی درباره ٔ کوه دماوند ذکرشده است . رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٦٧٤</span> شود.<br></font></div>'),
(186076, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زین العابدین بن هاشم عراقی حسینی فاسی، مکنی به ابوالحسن . رجوع به علی عراقی شود.<br></font></div>'),
(186077, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زین نصرانی . او راست : کتاب الاَّداب و الامثال علی مذاهب الفرس و الروم و العرب . (از الفهرست ابن الندیم ). اما احتمال دارد که این مرد همان علی بن ربن الطبری باشد. رجوع به ابن ربن شود.<br></font></div>'),
(186078, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زکرون، علی بن احمدبن زکریا، مشهور به ابن زکرون و مکنی به ابوالحسن . رجوع به علی بن احمدبن زکریا شود.<br></font></div>'),
(186079, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ساعی، علی بن أنجب بن عثمان بن عبداﷲبن عبیداﷲبن عبدالرحیم بغدادی خازن شافعی، مشهور به ابن ساعی و ملقب به تاج الدین و مکنی به ابوطالب . رجوع به ابن ساعی و علی بن أنجب بن ... شود.<br></font></div>'),
(186080, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سالم، نام او علی بن خلیل بن احمدبن سالم شافعی، و ملقب به علاءالدین است . رجوع به علی شافعی (ابن خلیل بن احمدبن ...) شود.<br></font></div>'),
(186081, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سالم بن عبدالناصر غزی شافعی . رجوع به علی غزی شود.<br></font></div>'),
(186082, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سالم بن مخارق والبی، مولای عباس بن عبدالمطلب . رجوع به علی والبی شود.<br></font></div>'),
(186083, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سختویه بیهقی خسروجردی . رجوع به علی بیهقی شود.<br></font></div>'),
(186084, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سدیر، علی بن محمدبن عبداﷲ، مکنی به ابوالحسن و مشهور به ابن سدیر. رجوع به علی بن محمدبن عبداﷲ شود.<br></font></div>'),
(186085, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سراج بن عبداﷲ مصری، مکنی به ابوالحسن . رجوع به علی مصری شود.<br></font></div>'),
(186086, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سری بن صقربن حمل . محدث بود. (منتهی الارب ) (تاج العروس ).<br></font></div>'),
(186087, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعدبن عبداﷲعسکری، مکنی به ابوالحسن . رجوع به علی عسکری شود.<br></font></div>'),
(186088, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعدبن علی، مکنی به ابوالحسن . وی یکی از امرای بنی نصر بود که از سال <span class=\"hlight\" dir=\"rtl\">٦٢٩</span> تا <span class=\"hlight\" dir=\"rtl\">٨٩٧</span> هَ . ق . در غرناطه حکومت کردند. او دو بار حکومت را به دست گرفت، یکی از سال <span class=\"hlight\" dir=\"rtl\">٨٦٦</span> تا <span class=\"hlight\" dir=\"rtl\">٨٨٧</span> و یک بار از <span class=\"hlight\" dir=\"rtl\">٨٨٨</span> تا <span class=\"hlight\" dir=\"rtl\">٨٩٠</span>. (از طبقات سلاطین اسلام ص <span class=\"hlight\" dir=\"rtl\">٢٥</span>) (از معجم الانساب زامباور ص <span class=\"hlight\" dir=\"rtl\">٩٤</span>).<br></font></div>'),
(186089, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعدبن علی بن عبدالواحدبن عبدالقاهربن أحمدبن مسهر موصلی، مکنی به ابوالحسن و ملقب به مهذب الدین و مشهور به ابن ابی الوفاء. رجوع به علی موصلی شود.<br></font></div>'),
(186090, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن سعدبن علی بن یوسف الغنی باﷲبن محمدبن أحمر، مکنی به ابوالحسن و ملقب به الغالب باﷲ، نام او بصورت «علی بن سعدبن محمد...» و «علی بن نصربن سعدبن سلطان ابی عبداﷲ محمدبن سلطان ابی الحسن » نیز آمده است . وی از ملوک بنی الاحمر در اندلس بود. و پس از حوادث بسیاری توانست به سلطنت برسد، و با اسپانیا جنگهای بسیاری کرد که به صلح انجامید. او در بصره به مرضی شبیه صرع مبتلی گشت لذا از پادشاهی معزول شد و به شهر«منکب » منتقل گشت و در سال <span class=\"hlight\" dir=\"rtl\">٨٩٠</span> هَ . ق . در آنجا درگذشت . (از اعلام زرکلی از نفح الطیب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٦٠</span> و بدائع الزهور ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> و اخبارالعصر فی انقضاء دولة بنی نصر، که در انتهای کتاب «آخر بنی سراج » چاپ شده است ).<br></font></div>'),
(186091, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعدبن محمد، مکنی به ابوالحسن و ملقب به الغالب باﷲ. از ملوک بنی الاحمر اندلس . رجوع به علی بن سعدبن علی بن یوسف الغنی باﷲ... شود.<br></font></div>'),
(186092, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رضوان بن علی بن جعفر مصری، مکنی به ابوالحسن و مشهور به ابن رضوان . رجوع به علی مصری (ابن رضوان بن ...) و ابن رضوان شود.<br></font></div>'),
(186093, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن دلدار علی لکهنوئی هندی . رجوع به علی لکهنوئی شود.<br></font></div>'),
(186094, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ذری حضرمی . رجوع به علی حضرمی شود.<br></font></div>'),
(186095, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رافع. مولای پیغمبر (ص ).وی در عهد پیغمبر (ص ) متولد شد و پیغمبر اکرم وی را«علی » نام نهاد. (از الاصابه ٔ ابن حجر ج <span class=\"hlight\" dir=\"rtl\">٥</span>، قسم <span class=\"hlight\" dir=\"rtl\">٢</span>).<br></font></div>'),
(186096, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن راهبة. وی طبیب المتقی خلیفه ٔ عباسی بود و نزد او احترام و اکرامی خاص داشت . او بهمراهی بختیشوع و أتوش و ثابت بن سنان بن ثابت، طبابت المتقی را عهده دار بود. (از تاریخ الحکماء قفطی ص <span class=\"hlight\" dir=\"rtl\">٢٣٥</span>).<br></font></div>'),
(186097, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رباح . از محدثان بود. (منتهی الارب ).<br></font></div>'),
(186098, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن ربن، علی بن سهل طبری، مکنی به ابوالحسن . رجوع به ابن ربن و علی بن سهل بن ربن طبری شود.<br></font></div>'),
(186099, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ربیعة، مکنی به ابوالمغیرة. وی تابعی بود و از علی علیه السلام روایت کرد. و سلمةبن کهیل از او روایت دارد. و نیز رجوع به ابومغیره (علی بن ...) شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(186100, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رجاء، ملقب به شرف الدین . وی در سلک وزیران طغرل بن محمدبن ملکشاه به شمار می رفت و چون مردی نالایق بود طغرل عزم عزل او کرد. اما پیش از عزل کردن وی روزگار سلطنتش به سر آمد و شرف الدین علی به آذربایجان رفت و جزء ملازمان سلطان داوودبن محمود گردید. و هنگامی که خوارزمشاه به عراق لشکر کشید وی کشته شد. (از دستورالوزراء خوندمیر ص <span class=\"hlight\" dir=\"rtl\">٢٠٩</span>) (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٢١</span>).<br></font></div>'),
(186101, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رجب علی دیزجی (علی اکبر...). رجوع به علی اکبر دیزجی شود.<br></font></div>'),
(186102, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رزین بن سلیمان . از بنی مروان بن ابی حفصة بود و شعر می گفت . او را دیوانی بود که نزدیک پنجاه ورق داشت . (از الفهرست ابن الندیم ).<br></font></div>'),
(186103, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رزین ترمذی خراسانی، مکنی به ابوالحسن . رجوع به علی ترمذی (ابن رزین ...) شود.<br></font></div>'),
(186104, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رستم بن هردوز، مشهور به ابن ساعاتی و ملقب به بهاءالدین و مکنی به ابوالحسن .نام وی را بصورت علی بن محمدبن رستم بن هردوز نیز آورده اند. وی در سال <span class=\"hlight\" dir=\"rtl\">٥٥٣</span> هَ . ق . متولد شد و در سال <span class=\"hlight\" dir=\"rtl\">٦٠٤</span>در قاهره درگذشت . او را دیوان شعری است در دو مجلد، و نیز دیوانی به بنام «مقطعات النیل » دارد. رجوع به ابن ساعاتی و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٩٢</span> و وفیات الاعیان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥٨</span> و شذرات الذهب ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٣</span> و مرآةالجنان یافعی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٤</span> و کتاب فی التراجم ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٦١٦</span>.<br></font></div>'),
(186105, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رسول رسولی . رجوع به علی رسولی شود.<br></font></div>'),
(186106, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رضابن محمدمهدی بحرالعلوم طباطبائی . رجوع به علی طباطبائی شود.<br></font></div>'),
(186107, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعدالدین مسعودبن علی ابهری، ملقب به صدرالدین . وزیر سلطان علاءالدین تکش . رجوع به صدرالدین علی ... شود.<br></font></div>'),
(186108, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رضی الدین بن علی بن احمدبن محیی الدین جامعی عاملی . رجوع به علی جامعی شود.<br></font></div>'),
(186109, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رفاعه ٔ قرظی . رجوع به علی قرظی شود.<br></font></div>'),
(186110, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رکانة. برخی او را از صحابه دانسته اند، ولی ابن مندة گوید که صحابی بودن اومورد تردید است . (از الاصابه ٔ ابن حجر ج <span class=\"hlight\" dir=\"rtl\">٤</span>، قسم <span class=\"hlight\" dir=\"rtl\">١</span>).<br></font></div>'),
(186111, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رکن الدوله حسن بن بویه دیلمی، ملقب به فخرالدوله . رجوع به فخرالدوله ٔ دیلمی شود.<br></font></div>'),
(186112, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن روزبهان بن محمد خنجی، ملقب به زین الدین . رجوع به علی خنجی شود.<br></font></div>'),
(186113, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن روزبه شیبانی، ملقب به اختیارالدین . از امرا و ملوک جبال . رجوع به اختیارالدین (علی بن ...) شود.<br></font></div>'),
(186114, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رومی، علی بن عباس بن جریج بغدادی، مشهور به ابن رومی و مکنی به ابوالحسن . شاعر رومی الاصل . رجوع به ابن رومی به علی بن عباس بن جریج ... شود.<br></font></div>'),
(186115, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رؤیم کوفی . رجوع به علی کوفی (ابن رؤیم ) شود.<br></font></div>'),
(186116, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن رئاب . وی از مشایخ شیعه و راوی فقه از ائمه بود. (از الفهرست ابن الندیم ).<br></font></div>'),
(186117, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زاهدة، علی بن مبارک، مشهور به ابن زاهدة و مکنی به ابوالحسن . رجوع به علی بن مبارک شود.<br></font></div>'),
(186118, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زریق بغدادی، مکنی به ابوالحسن . رجوع به علی بغدادی شود.<br></font></div>'),
(186119, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زقاق، علی بن عطیةبن مطرف بن سلمه ٔ لخمی بلنسی، مشهور به ابن زقاق و مکنی به ابوالحسن . رجوع به علی لخمی (ابن عطیةبن مطرف ابن ...) و ابن زقاق شود.<br></font></div>'),
(186120, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن زقاق، علی بن قاسم بن یونش اشبیلی، مشهور به ابن زقاق و مکنی به ابوالحسن . رجوع به علی اشبیلی (ابن قاسم بن یونش ...) شود.<br></font></div>'),
(186121, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سهروردی . علی بن مسلم بن محمدبن علی سلمی دمشقی شافعی خلوتی، مشهور به ابن سهروردی و مکنّی به ابوالحسن و ملقّب به جمال الاسلام .رجوع به علی سهروردی (ابن مسلم بن محمدبن ...) شود.<br></font></div>'),
(186122, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلیمان بن عبداﷲ منصوری مصری . رجوع به علی منصوری شود.<br></font></div>'),
(186123, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلیمان بن علی بن عبداﷲبن عباس هاشمی عباسی، مکنی به ابوالحسن . رجوع به علی هاشمی (ابن سلیمان بن علی بن ...) شود.<br></font></div>'),
(186124, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلیمان بن فضل بغدادی، مکنی به ابوالحسن و مشهور به أخفش صغیر (یا أخفش أصغر). نحوی و اخباری و لغوی معروف . وی شاگرد مبرد و ثعلب بن یحیی بود و در سال <span class=\"hlight\" dir=\"rtl\">٣١٥</span> هَ . ق . در بغداد در حدود هشتادسالگی درگذشت . رجوع به أخفش صغیر و مآخذ زیر شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٤</span> و الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣</span> و طبقات النحاة و اللغویین ابن شهبة ص <span class=\"hlight\" dir=\"rtl\">٤٢٣</span> وتاریخ دمشق ابن عساکر ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٤</span> و الفهرست ابن الندیم ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٨٣</span> و معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">١٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٦</span> و بغیة الوعاة سیوطی ص <span class=\"hlight\" dir=\"rtl\">٣٣٨</span> و مرآةالجنان یافعی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦١</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">١٤٢٧</span> و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٤</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٧٦</span>.<br></font></div>'),
(186125, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلیمان بحرانی، مکنی به ابوالحسن و ملقب به جمال الدین یا کمال الدین ). رجوع به علی بحرانی شود.<br></font></div>'),
(186126, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلیمان دمنتی بوجمعوی مغربی مالکی، مکنی به ابوالحسن . رجوع به علی دمنتی شود.<br></font></div>'),
(186127, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلیمان زهراوی، مکنی به ابوالحسن . رجوع به علی زهراوی شود.<br></font></div>'),
(186128, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلیمان کلبی، مکنی به ابونوفل . محدث است و از ولیدبن مسلم بن نوفل بن ابی عقرب روایت کند. نیز رجوع به ابونوفل شود.<br></font></div>'),
(186129, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلیمان یمنی . رجوع به علی یمنی شود.<br></font></div>'),
(186130, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلیمان یمنی بکیلی تمیمی زیدی اسماعیلی، ملقّب به حیدرة. رجوع به علی بکیلی شود.<br></font></div>'),
(186131, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلیم بن ربیعه ٔ اذرعی، مکنّی به ابوالحسن و ملقّب به ضیاءالدین . رجوع به علی اذرعی شود.<br></font></div>'),
(186132, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سماقة. علی بن احمد سماقه ٔ عاملی مشغری . رجوع به علی سماقة (ابن احمد...) شود.<br></font></div>'),
(186133, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سنجر بغدادی حنفی، مشهور به ابن سماک (یا ابن سباک ) و ملقّب به تاج الدین و مکنّی به ابوالحسن . رجوع به علی بغدادی شود.<br></font></div>'),
(186134, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سندبن علی بن سلیمان لواتی الاصل ابیاری شافعی مصری . رجوع به علی ابیاری شود.<br></font></div>'),
(186135, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سودون یشبغاوی قاهری دمشقی حنفی، مکنّی به ابوالحسن . شاعر بود ودر سال <span class=\"hlight\" dir=\"rtl\">٨١٠</span> هَ . ق . در قاهره متولد شد و در نیمه ٔ رجب سال <span class=\"hlight\" dir=\"rtl\">٨٦٨</span>هَ . ق . در دمشق درگذشت و در مقبره ٔ فرادیس دفن شد. رجوع به ابن سودون و نیز به مآخذ ذیل شود:معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٦</span>. الضوءاللامع سخاوی ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span>. شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٧</span>. کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٨٠٣</span>.فهرست الخدیویة ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩١</span>. هدیةالعارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣٤</span>.<br></font></div>'),
(186136, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلیمان بن درویش بن حاتم بحرانی قدمی، ملقب به زین الدین . رجوع به علی بحرانی شود.<br></font></div>'),
(186137, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سهل . تابعی است . (منتهی الارب ).<br></font></div>'),
(186138, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سهل بن ازهر اصفهانی، مکنّی به ابوالحسن . از مشایخ صوفیه و معاصر جنید. رجوع به ابوالحسن (علی بن سهل ...) و نیز به اصفهانی شود.<br></font></div>'),
(186139, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سهل بن ربن طبری، مکنّی به ابوالحسن . طبیب و مطلع در طبیعیات و در انجیل . وی در طبرستان متولد شد و سپس نزد خلیفه المعتصم عباسی اسلام آورد و المتوکل او راجزء ندیمان خویش قرار داد. وی پیش از سال <span class=\"hlight\" dir=\"rtl\">٢٢٨</span> هَ . ق . می زیست و برخی وفات او را در سال <span class=\"hlight\" dir=\"rtl\">٢٤٧</span> هَ . ق . نگاشته اند. رجوع به ابن ربن و نیز به کتب ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٦</span>. الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>. عیون الانباء ابن ابی اصیبعه ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٩</span>. تاریخ الحکمای قفطی ص <span class=\"hlight\" dir=\"rtl\">٢٣١</span>. الفهرست ابن الندیم ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٦</span>. تاریخ حکماءالاسلام بیهقی ج <span class=\"hlight\" dir=\"rtl\">٢٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>. کنوزالاجداد محمد کردعلی ص <span class=\"hlight\" dir=\"rtl\">٧١</span>. المخطوطات العربیه ٔ شیخو ص <span class=\"hlight\" dir=\"rtl\">١٤٨</span>. هدیةالعارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦٩</span>.<br></font></div>'),
(186140, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سهل بن عباس بن سهل نیشابوری، مکنّی به ابوالحسن . رجوع به علی نیشابوری شود.<br></font></div>'),
(186141, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سهل اصفهانی، مکنّی به ابوالحسن (علی بن سهل ...) و نیز به اصفهانی شود.<br></font></div>'),
(186142, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سهل فوشنجی (شیخ ...) مکنّی به ابوالحسن . رجوع به ابوالحسن فوشنجی و نیز به علی بن احمدبن سهل فوشنجی شود.<br></font></div>'),
(186143, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سیدکمال الدین بن سیدقوام الدین مرعشی آملی (سید...). رجوع به علی آملی شود.<br></font></div>'),
(186144, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سیدة. علی بن اسماعیل اندلسی مرسی ضریر، مشهوربه ابن سیدة و مکنّی به ابوالحسن . متولد در سال <span class=\"hlight\" dir=\"rtl\">٣٩٨</span>هَ . ق . در مرسیة. رجوع به ابن سیدة و نیز به کتب ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>. بغیةالوعاة سیوطی ص <span class=\"hlight\" dir=\"rtl\">٣٢٧</span>. کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٦٩١</span> و <span class=\"hlight\" dir=\"rtl\">٨١٢</span> و سایر صفحات . هدیةالعارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٩١</span>. الصله ٔ ابن بشکوال ص <span class=\"hlight\" dir=\"rtl\">٤١٠</span>. انباءالرواة قفطی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٥</span>. لسان المیزان ابن حجر ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٥</span>. البدایه ٔ ابن کثیر ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩٥</span>. مرآةالجنان یافعی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٨٢</span> . مطمح الانفس ص <span class=\"hlight\" dir=\"rtl\">٦٠</span> . بغیةالملتمس ص <span class=\"hlight\" dir=\"rtl\">٤٠٥</span>. الدیباج ابن فرحون ص <span class=\"hlight\" dir=\"rtl\">٢٠٤</span>. شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٥</span>. المختصر فی أخبارالبشر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٥</span>. مفتاح السعاده ٔ طاش کبری ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٩٩</span>. مختصر دول الاسلام ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span>. فهرست الخدیویة ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٤</span>. سیرالنبلاء ذهبی ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٠</span>. طبقات النحاة و اللغویین ص <span class=\"hlight\" dir=\"rtl\">٤٠٩</span>. التذکره ٔ طاهر جزائری . ص <span class=\"hlight\" dir=\"rtl\">٦</span>.<br></font></div>'),
(186145, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شاطر. علی بن ابراهیم بن محمد همام بن محمدبن ابراهیم بن حسن انصاری دمشقی، مشهور به ابن شاطر و مطعم، و ملقّب به علاءالدین و مکنّی به ابوالحسن . وی منجم بود و در جامع اموی دمشق عهده دار توقیت بود. تولدش در <span class=\"hlight\" dir=\"rtl\">٧٠٤</span> هَ . ق . و وفاتش در <span class=\"hlight\" dir=\"rtl\">٧٧٧</span> هَ . ق . بوده است . او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- الاشعةاللامعة فی العمل بالالةالجامعة. <span class=\"hlight\" dir=\"rtl\">٢</span>- الثمارالیانعة من قطوف الالة الجامعة. <span class=\"hlight\" dir=\"rtl\">٣</span>- کشف المغیب فی الحساب بالربع المجیب . <span class=\"hlight\" dir=\"rtl\">٤</span>- نزهةالسامعفی العمل بالربع الجامع. <span class=\"hlight\" dir=\"rtl\">٥</span>- النفع العام فی العمل بالربع التام لمواقیت الاسلام . (از معجم المؤلفین بنقل از فهرس مخطوطات الفلک بالظاهریة. و شذرات الذهب ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٢</span>. و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">١٠٥</span> و <span class=\"hlight\" dir=\"rtl\">٣٦٦</span>. و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٧</span>، و ج <span class=\"hlight\" dir=\"rtl\">٢</span>، ص <span class=\"hlight\" dir=\"rtl\">٣٦٨</span>. و تراث العرب العلمی ص <span class=\"hlight\" dir=\"rtl\">٣٨٨</span>. و هدیةالعارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٢٥</span>). و نیز رجوع به ابن شاطر شود.<br></font></div>'),
(186146, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شاکر موستاری، مشهور به جابی زاده . رجوع به علی جابی زاده شود.<br></font></div>'),
(186147, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شاهک عصار ضریر بیهقی . رجوع به علی بیهقی (ابن شاهک ...) شود.<br></font></div>'),
(186148, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شاه محمود بافقی . رجوع به علی بافقی شود.<br></font></div>'),
(186149, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن شاهمرادبن اسدبن جلال الدین بن حسن طباطبائی حسنی نجفی . رجوع به علی طباطبائی شود.<br></font></div>'),
(186150, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سکون، علی بن محمدبن محمدبن علی بن سکون حلی، مشهور به ابن سکون و مکنی به ابوالحسن . رجوع به علی حلی (ابن محمدبن محمدبن علی بن ...) شود.<br></font></div>'),
(186151, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعدالدین مسعود ابهری، ملقب به صدرالدین . وزیر تکش . رجوع به علی انصاری شود.<br></font></div>'),
(186152, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن سعد انصاری . رجوع به علی انصاری شود.<br></font></div>'),
(186153, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعد بیوسی احمدی شافعی أشعری . رجوع به علی احمدی شود.<br></font></div>'),
(186154, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعید. نام او علی بن موسی بن عبدالملک بن سعید عبسی اندلسی غرناطی مغربی و مکنی به ابوالحسن و مشهور به ابن سعید است . رجوع به ابن سعید و علی بن موسی بن عبدالملک بن ... شود.<br></font></div>'),
(186155, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعیدبن احمدبن یحیی مزیدی حلی، مکنی به ابوالحسن و ملقب به ملک الادبا و استاد شهید. شاگرد علامه . رجوع به ابوالحسن (علی بن سعید...) شود.<br></font></div>'),
(186156, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعیدبن حمامه ٔ صنهاجی (شیخ ...). رجوع به علی صنهاجی شود.<br></font></div>'),
(186157, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعیدبن سعدبن زیدبن محسن حسینی طالبی . از اشراف مکه . رجوع به علی طالبی شود.<br></font></div>'),
(186158, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعیدبن عبدالرحمان بن محرزعبدری، مکنی به ابوالحسن . رجوع به علی عبدری شود.<br></font></div>'),
(186159, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعیدبن عثمان بن سعید مصری، مکنی به ابوعلی . رجوع به علی مصری شود.<br></font></div>'),
(186160, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعیدبن محمدبن احمدبن محمدبن حسن بن محمدبن علی بن محمدبن حسین بن عبدالسلام بن عبدالمطلب حر عاملی جبعی . رجوع به علی حر شود.<br></font></div>'),
(186161, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعید اصطخری . رجوع به علی اصطخری شود.<br></font></div>'),
(186162, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعید رستغفنی حنفی، مکنی به ابوالحسن . رجوع به علی رستغفنی شود.<br></font></div>'),
(186163, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سعید عسکری .محدث اواخر قرن سوم هجری . رجوع به علی عسکری شود.<br></font></div>'),
(186164, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سکن معافری، مکنی به ابوالحسن . رجوع به علی معافری شود.<br></font></div>'),
(186165, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن دقیق العید، علی بن محمدبن علی بن وهب بن مطیع قشیری شافعی، ملقب به محب الدین و مشهور به ابن دقیق العید. رجوع به علی قشیری (ابن محمدبن علی بن ...) شود.<br></font></div>'),
(186166, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن میمون بن ابی بکربن علی بن میمون بن ابی بکربن یوسف بن اسماعیل بن ابی بکر هاشمی قرشی مغربی غماری فاسی، مکنّی به ابوالحسن . رجوع به علی هاشمی شود.<br></font></div>'),
(186167, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ناصربن علی حسینی، ملقّب به صدرالدین و مکنّی به ابوالحسن . رجوع به علی حسینی شود.<br></font></div>'),
(186168, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سگزی . گور وی در رباط دهستان است . و دهستان شهری است از ناحیت دیلمان . (از حدود العالم چ دانشگاه ص <span class=\"hlight\" dir=\"rtl\">١٤٣</span>).<br></font></div>'),
(186169, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلار، ملقب به الملک العادل سیف الدین و مشهور به ابن سلار. وزیر ظافر عبیدی است، صاحب مصر. رجوع به ابن سلار شود.<br></font></div>'),
(186170, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلطان العلماء مرعشی (علی نواب ...). رجوع به علی مرعشی شود.<br></font></div>'),
(186171, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن سلطان اویس ایلکانی (شاهزاده شیخ ...). وی برادر سلطان حسین بن سلطان اویس بود، و سلطان حسین بر آذربایجان سلطنت می کرد، در سال <span class=\"hlight\" dir=\"rtl\">٧٧٨</span> هَ . ق . شاهزاده شیخ علی که از قدرت امیر اسماعیل بن امیر زکریا حکمران بغداد خشنود نبود عده ای از اوباش بغداد را تحریک کرد و امیر وجیه الدین اسماعیل و امیر مسعود رشیدی عم امیر اسماعیل را کشتند. و سلطان حسین بجای ملامت برادر، او را به حکومت بغداد منصوب ساخت . و شیخ علی چون لیاقت اداره ٔ امور را نداشت، پیرعلی بادک را که از جانب شاه شجاع در شوشتر حکومت می کرد به بغداد خواند و اداره ٔ امور را به او سپرد و پس از مدتی این شیخ علی و پیرعلی، طاغی شدند و از اطاعت سلطان حسین سرپیچیدند. در سال <span class=\"hlight\" dir=\"rtl\">٧٨٢</span> سلطان حسین به بغداد لشکر کشیدو مخالفان او به شوشتر فرار کردند و شیخ علی از در اطاعت درآمد و به حکومت شوشتر قناعت کرد. اما پس از مدتی توانست به بغداد بازگردد و اداره ٔ امور را در دست گیرد. در صفر سال <span class=\"hlight\" dir=\"rtl\">٧٨٤</span> سلطان حسین که در تبریز بودبه دست برادر خود سلطان احمد به قتل رسید. پس از این واقعه شیخ علی و خواجه علی بادک از بغداد به تبریزلشکر کشیدند و سلطان احمد از طریق خوی به نخجوان گریخت و از قرامحمد ترکمان استمداد جست، و قرامحمد با شرایطی پنج هزار سوار به کمک او فرستاد و ترکمانان دراین جنگ شیخ علی و خواجه علی را به قتل رساندند. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٣</span> - <span class=\"hlight\" dir=\"rtl\">٢٤٥</span> و <span class=\"hlight\" dir=\"rtl\">٢٤٧</span>) (از تاریخ مفصل ایران، مغول تألیف عباس اقبال ص <span class=\"hlight\" dir=\"rtl\">٤٦٠</span> و <span class=\"hlight\" dir=\"rtl\">٤٦٢</span>).<br></font></div>'),
(186172, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلطان حیدر صفوی (سلطان ...). رجوع به علی صفوی شود.<br></font></div>'),
(186173, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلطان محمد هروی قاری حنفی، مکنی به نورالدین . رجوع به علی قاری شود.<br></font></div>'),
(186174, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلطان محمودمیرزا (سلطان ...). از شاهزادگان تیموری . رجوع به علی میرزابن سلطان محمود... شود.<br></font></div>'),
(186175, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلیم، مکنی به ابوسلیم . تابعی بود و از انس بن مالک روایت کرد. و اسرائیل بن یونس از وی روایت دارد. و نیز رجوع به ابوسلیم شود.<br></font></div>'),
(186176, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن سلیمان . وی طبیب و حکیم و ریاضی دان و فلکی و از مردم مصر بود. و در روزگار العزیز باﷲ و فرزندش الحاکم می زیست و زمان الظاهر لاعزار دین اﷲ فرزند الحاکم را نیز درک کرد. او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- اختصار کتاب الحاوی، در طب . <span class=\"hlight\" dir=\"rtl\">٢</span>- الامثلة و التجارب و الاخبار و النکت والخواص الطبیة المنتزعة من کتب ابقراط و جالینوس و غیرهما. <span class=\"hlight\" dir=\"rtl\">٣</span>- التعالیق الفلسفیة، که در سال <span class=\"hlight\" dir=\"rtl\">٤١١</span> هَ . ق . در حلب شروع به نگاشتن آن کرد. <span class=\"hlight\" dir=\"rtl\">٤</span>- مقالة أرسطوطالیس فی الابصار و تعدید شکوک فی کواکب الذنب . <span class=\"hlight\" dir=\"rtl\">٥</span>- مقالةفی أن قبول الجسم التجزؤ لایقف و لایتنهی . (از معجم المؤلفین از عیون الانباء ابن ابی اصیبعه ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩٠</span>).<br></font></div>'),
(186177, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن سلیمان بن احمدبن سلیمان أنصاری قرطبی عباسی، مکنی به ابوالحسن . رجوع به علی انصاری شود.<br></font></div>'),
(186178, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن سلیمان بن احمدبن محمد سعدی صالحی حنبلی مرداوی، مکنی به ابوالحسن و ملقب به علاءالدین . رجوع به علی مرداوی شود.<br></font></div>'),
(186179, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن بکری، مکنی به ابوالحسن . نام او رابصورت «علی بن عمربن احمدبن عبدالباقی بن بکری » نیز آورده اند. وی کتابدار کتابخانه ٔ نظامیه و از مردم باب الازج بود و در هجدهم رمضان سال <span class=\"hlight\" dir=\"rtl\">٥٧٥</span> هَ . ق . درگذشت ودر «وردیه » دفن گردید. او نحو را نزد ابوالسعادات بن شجری و لغت را نزد ابومنصور جوالیقی فراگرفت . او راخطی نیکو بود و تعداد بسیاری از کتب را به خط خویش نگاشته است . (از معجم الادباء چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٤</span>).<br></font></div>'),
(186180, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اثردی، علی بن هبةاﷲبن علی بن اثردی، مکنی به ابوالحسن و مشهور به ابن اثردی . رجوع به علی بن هبة اﷲبن ... شود.<br></font></div>'),
(186181, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن أثیر، علی بن محمدبن محمدبن عبدالکریم بن عبدالواحد شیبانی موصلی، مشهور به ابن اثیر جزری و ملقب به عزالدین و مکنی به ابوالحسن . رجوع به ابن اثیر و علی بن محمدبن محمدبن ... شود.<br></font></div>'),
(186182, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد. وی از اهالی قزوین بود و از جمله وکیلانی بشمار می رفت که صاحب کشف الغمة بنقل از اعلام الوری تألیف طبرسی، گوید که آنها حضرت صاحب الامر (ع ) را رؤیت کرده اند. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٠</span>).<br></font></div>'),
(186183, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد، مکنی به ابوالفتح . وی وزیر ملک اهواز بود و به روزگار ناصرخسرو در بصره میزیست . مردی اهل و صاحب فضل و دانای شعرو ادب بود با کرمی تمام . (از سفرنامه ٔ ناصرخسرو).<br></font></div>'),
(186184, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد، ملقب به علاءالدین (متوفی در سال <span class=\"hlight\" dir=\"rtl\">٧٠٦</span> هَ . ق .). وی از قاریان بود. او راست : شرح الشاطبیة فی القراآت . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٩</span> از کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٥٤٨</span>).<br></font></div>'),
(186185, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد، مکنی به ابوالفتوح . از حقوقدانان بود و در سال <span class=\"hlight\" dir=\"rtl\">١٢٨٩</span> هَ . ق . در استان غربی مصر متولد شد. و در دانشکده ٔ منپلیه ٔ فرانسه تحصیل علم حقوق کرد و به مصر بازگشت و چندین مدرسه ٔ مختلف تأسیس کرد و در سال <span class=\"hlight\" dir=\"rtl\">١٣٣١</span> هَ . ق . در قاهره درگذشت . او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- خواطر فی القضاء و الاقتصاد و الاجتماع . <span class=\"hlight\" dir=\"rtl\">٢</span>- سیاحة مصری فی اروبا سنة <span class=\"hlight\" dir=\"rtl\">١٩٠٠</span> م . <span class=\"hlight\" dir=\"rtl\">٣</span>- الشریعة الاسلامیة و القوانین الوضعیة. <span class=\"hlight\" dir=\"rtl\">٤</span>- المذهب الاجتماعی فی التشریع الجنائی . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢</span> از فهرس المؤلفین بالظاهریة و معجم المطبوعات ص <span class=\"hlight\" dir=\"rtl\">٣٢٢</span> و فهرس الازهریة ج <span class=\"hlight\" dir=\"rtl\">٦</span>ص <span class=\"hlight\" dir=\"rtl\">٢١</span> و مرآة العصر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٣</span> و الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٦٧</span>).<br></font></div>'),
(186186, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد (دهقان ...)، ملقب به اختیارالدین . وی ممدوح سوزنی بود، و او را در قصیده ای مدح کرده است که چند بیت از آن نقل میشود <span class=\"hlight\">:</span> <br>کآمد به فرخی ز سفر اختیار دین <br>کز مدح او کند شرف و افتخار دل <br>دهقان علی که همچو علی بدسگال را<br>در سینه بگسلد به سر ذوالفقار دل .<br><font color=\"Red\">(از دیوان حکیم سوزنی سمرقندی ص <span class=\"hlight\" dir=\"rtl\">٢٤٥</span>).</font><br></font></div>'),
(186187, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن ابراهیم بن اسماعیل مهائمی دکنی هندی حنفی، ملقب به علاءالدین . رجوع به علی مهائمی شود.<br></font></div>'),
(186188, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن ابراهیم بن زبیر عنانی فسوی شافعی، ملقب به رشید و مکنی به ابوالحسن . رجوع به علی فسوی شود.<br></font></div>'),
(186189, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن ابی دجانه ٔ مصری، مکنی به ابوالحسن . خطاط و نویسنده ٔ قرن چهارم هجری . رجوع به علی مصری (ابن احمدبن ...) شود.<br></font></div>'),
(186190, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن ابی هیجاء هکاری، مکنی به ابوالحسن و ملقب به سیف الدین و مشهور به مشطوب . رجوع به علی مشطوب شود.<br></font></div>'),
(186191, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن احمدبن محمدبن یوسف بلصفوری ازهری مالکی . رجوع به علی یوسف شود.<br></font></div>'),
(186192, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن احمد قلقشندی مصری شافعی . نسابه ٔ قرن هشتم هجری . رجوع به علی قلقشندی شود.<br></font></div>'),
(186193, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن اسعدبن ابی بکربن محمدبن عمربن ابی الفتوح بن علی بن ابی الفتوح بن علی بن صبح اصبحی یمنی، ملقب به ضیاءالدین و مکنی به ابوالحسن . رجوع به أصبحی شود.<br></font></div>'),
(186194, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی هیجاء، ملقب به سیف الدوله . وی از آل حمدان بود که در زمان عباسیان بر موصل و شام حکومت می کردند. سیف الدوله علی در سال <span class=\"hlight\" dir=\"rtl\">٣٠٣</span> هَ . ق . متولد شد و در عهد خلافت المقتدرعباسی، در شام حکومت می کرد و دربار او مرکز تجمع علما و شعرا و ادبا و فضلا بود و خود نیز طبع شعر داشت و گاهی شعر می گفت . در سال <span class=\"hlight\" dir=\"rtl\">٣٣٣</span> هَ . ق . «اخشید» والی مصر به جانب حلب لشکر کشید ولی از سیف الدوله شکست خورد و به طبریة رفت و پس از مدت کمی دوباره به جنگ سیف الدوله آمد و حلب را تصرف کرد، و این جنگ وستیز در سال <span class=\"hlight\" dir=\"rtl\">٣٣٤</span> هَ . ق . به مصالحه انجامید و حلب و حمص و انطاکیه به سیف الدوله تعلق یافت و سایر بلاد شام ازآن ِ اخشید گشت . ولی در همان سال اخشید درگذشت و تمام بلاد شام به تصرف سیف الدوله درآمد تا اینکه وی نیز در ماه صفر سال <span class=\"hlight\" dir=\"rtl\">٣٥٦</span> هَ . ق . درگذشت و جسد او را در میافارقین به خاک سپردند. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٤٧</span>).<br></font></div>'),
(186195, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن تقی بن صالح، مشهور به ابن حجة و شهید ثانی (<span class=\"hlight\" dir=\"rtl\">٩١١</span> - <span class=\"hlight\" dir=\"rtl\">٩٥٧</span> هَ . ق .). فقیه و اصولی و محدث و متکلم بود و در مکه اقامت داشت . او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- البدایة فی الدرایة. <span class=\"hlight\" dir=\"rtl\">٢</span>- روض الجنان فی شرح الارشاد، در فقه شیعه . <span class=\"hlight\" dir=\"rtl\">٣</span>- غنیة القاصدین فی اصطلاحات المحدثین . <span class=\"hlight\" dir=\"rtl\">٤</span>- کتاب الرجال و النسب و تحقیق الایمان و الاسلام . <span class=\"hlight\" dir=\"rtl\">٥</span>- المسالک، در هفت مجلد. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٢</span> از هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٤٧</span>).<br></font></div>'),
(186196, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن تقی الدین بخاری مکی شافعی، مشهور به قبانی . رجوع به علی بخاری شود.<br></font></div>'),
(186197, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن حرب . محدث است . (منتهی الارب ).<br></font></div>'),
(186198, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن حرب سمیرمی، مکنی به ابوطالب و ملقب به کمال الدین . رجوع به علی سمیرمی شود.<br></font></div>'),
(186199, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن حسن بن ابراهیم تجیبی اندلسی مالکی، مشهور به حرالی . رجوع به علی حرالی شود.<br></font></div>'),
(186200, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن حسن مذحجی، مشهور به بحدة و مکنی به ابوالحسن . رجوع به علی مذحجی شد.<br></font></div>'),
(186201, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن حسن یمانی، مشهور به ابن علیف . وی شاعر بود و در سال <span class=\"hlight\" dir=\"rtl\">٨٥٥</span> هَ . ق . درگذشت . او را دیوان شعری است . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٤</span> از هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣٢</span>).<br></font></div>'),
(186202, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن حسین بن احمدبن حسین بن محمویه یزدی شافعی، مکنی به ابوالحسن . رجوع به علی یزدی شود.<br></font></div>'),
(186203, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن حسین حسینی علوی آملی، ملقب به ممتازالعلماء و مکنی به ابوالحسن . رجوع به علی آملی شود.<br></font></div>'),
(186204, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن حسین قطیفی . رجوع به علی قطیفی شود.<br></font></div>'),
(186205, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن حمدون اندلسی حمیری، مکنی به ابوالحسن و ملقب به نورالدین . نحوی ولغوی قرن هفتم هجری . رجوع به ابوالحسن حمیری شود.<br></font></div>'),
(186206, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن حِنّی . محدث است . (منتهی الارب ).<br></font></div>'),
(186207, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن خاتون عاملی . فقیه و ادیب قرن دهم هجری . رجوع به علی عاملی شود.<br></font></div>'),
(186208, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن خلف بن محمد باذش انصاری غرناطی، مشهور به ابن باذش و مکنی به ابوالحسن . رجوع به ابن باذش و غرناطی و علی باذش شود.<br></font></div>'),
(186209, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی فضل بن عمید، مکنی به ابوالفتح و ملقب به ذوالکفایتین، فرزند ابن عمید. رجوع به علی ذوالکفایتین شود.<br></font></div>'),
(186210, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن ابی سعید عبدالرحمان بن احمدبن یونس بن عبدالاعلی صدفی یمنی مصری، مکنی به ابوالحسن . رجوع به ابن یونس (ابوالحسن علی بن ...) و علی بن عبدالرحمان بن ... شود.<br></font></div>'),
(186211, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی طالب بن عبدالمطلب حسینی همدانی نجفی . رجوع به علی همدانی شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(186212, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی طالب بن عبدمناف بن عبدالمطلب بن هاشم بن نضربن کنان بن خزیمةبن مدرک بن الیاس بن مضربن نزاربن معدبن عدنان هاشمی قرشی علیه السلام، مکنی به ابوالحسن، ابوتراب (بوتراب ) و ابوالهیجاء (بوالهیجاء)، و ملقب به مرتضی، أسداﷲ، حیدر، حیدر کرار، شاه مردان، شاه ولایت، امیرالمؤمنین  و مولای متقیان . وی پسرعم و داماد پیغمبر اکرم و از عشره ٔ مبشره و خلیفه ٔ چهارم مسلمانان و امام اول نزد مسلمانان شیعی مذهب است . او نخستین کس از بین مردان بود که اسلام آورد. و مادرش فاطمة بنت اسدبن هاشم بن عبدمناف است . سی سال پس از عام الفیل در کعبه متولد شد و بهنگام تولدش پیغمبراکرم سی ساله بود، و روز تولد او در روایت شیعیان سیزدهم رجب است . ابتدا مادرش وی را «حیدرة» که بمعنای شیر است نام نهاد اما پیغمبر اسلام او را «علی » نامیدو ابوتراب کنیه داد. وی مردی شجاع و خطیب و بلیغ و عالم بود و از کودکی در خانه ٔ پیغمبر (ص ) میزیست و در غالب غزوات حضرت رسول شرکت داشت و رایت مسلمانان را حمل می کرد. از جمله ٔ این غزوات غزوه ٔ حنین است که عباس وی را ملقب به ذوالبرقة کرد. آنگاه که پیغمبر اکرم (ص ) مسلمانان مهاجر و انصار را به برادری و دوستی فرمان داد، خود آن حضرت، علی بن ابی طالب (ع ) را به برادری برگزید و آنگاه دختر خویش فاطمه (ع ) را به تزویج او درآورد. به عقیده ٔ شیعیان، پیغمبر اسلام در سال حجةالوداع در روز هیجدهم ذی حجه در محلی بنام «غدیرخم » علی بن ابی طالب را به جانشینی خود برگزید و فرمود «مَن کنت مولاه، فهذا علی مولاه ». اما پس از رحلت پیغمبر، مسلمانان در مسأله ٔ جانشینی اختلاف کردند و ابوبکر را به خلافت برگزیدند و پس از او عمر سپس عثمان به خلافت رسید تا اینکه پس از قتل عثمان مسلمانان در بیست وپنجم ذی حجه ٔ سال <span class=\"hlight\" dir=\"rtl\">٣٥</span> هَ . ق . با علی علیه السلام بیعت کردند. و بسبب مخالفت و عناد برخی از کسان با علی (ع ) در دوران خلافت وی جنگهایی بدین شرح روی داد:<br>جنگ جمل : نخستین کسی که با امیرالمؤمنین علی (ع ) بیعت کرد طلحه و پس از او زبیر بود اما بعلت اینکه آنها متوقع حکومت بصره و حکومت کوفه بودند و امام این توقعآنها را برنیاورد شروع به مخالفت با وی کردند. و ازسوی دیگر ام المؤمنین عائشه دختر ابوبکر و زوجه ٔ پیغمبر اکرم که از دیرباز اختلافاتی با امیرالمؤمنین داشت به صف مخالفان پیوست و همگی این مخالفان که پیشوای آنها مروان بن حکم بود به بهانه ٔ خونخواهی عثمان به جنگ با علی بن ابی طالب برخاستند و در سال <span class=\"hlight\" dir=\"rtl\">٣٦</span> هَ . ق . بصره را به پیشوایی عائشه فتح کردند و در جنگی که بین آنها و سپاه امیرالمؤمنین رخ داد طلحه و زبیر مقتول و عائشه اسیر گردید و درنتیجه علی بن ابی طالب برتمام بلاد اسلام (بجز شام که در دست معاویه بود) مستولی گشت . و این جنگ «جَمل » مشهور گشت .<br>جنگ صِفّین : پس از واقعه ٔ جمل علی بن ابی طالب، معاویه را از حکومت شام عزل کرد اما معاویه زیر بار این عزل نرفت و درنتیجه در سال <span class=\"hlight\" dir=\"rtl\">٣٧</span> هَ . ق . بین سپاه امیرالمؤمنین و سپاه معاویه جنگی در ناحیه ٔ «صفّین » که بین عراق و شام در ساحل فرات بود، درگرفت (رجوع به صفین شود) و یکصدوده روز به طول انجامید و به قبول حکمیت ابوموسی اشعری (از جانب علی بن ابی طالب «ع ») و عَمروبن عاص (از جانب معاویه ) منجر گشت، در این حکمیت عمروبن عاص نیرنگی بکار برد و امیرالمؤمنین را از خلافت عزل کرد و معاویه را به جایش بنشاند. درنتیجه ٔ این خدعه میان مسلمانان اختلاف رخ داد و به سه دسته تقسیم شدند: یک دسته که اهل شام بودند بر بیعت خود با معاویه باقی ماندند و دسته ٔ دیگر که اهل کوفه بودند بر بیعت خود با علی بن ابی طالب (ع ) استوار ماندند. اما دسته ای دیگر بودند که عقیده بر عزل هر دو (امیرالمؤمنین علی، و معاویة) داشتند و آنان را «خَوارج » خواندند و آنها در محلی بنام «نهروان » گرد آمدند.<br>واقعه ٔ نهروان : در سال <span class=\"hlight\" dir=\"rtl\">٣٨</span> هَ . ق . علی بن ابی طالب خوارج را به بازگشت به بیعت و دست کشیدن از عقیده ٔ خویش مکلف ساخت و چون نپذیرفتند به سرکوبی آنان پرداخت و با وجودی که تعداد بسیاری از آنان راکشت از عقیده ٔ خود دست برنداشتند و در بلاد مختلف پراکنده گشتند و سالهای متمادی با خلفا مخالفت میکردند. پس از فراغت از کار خوارج، امیرالمؤمنین علی (ع ) در دارالخلافه ٔ خویش یعنی کوفه اقامت گزید و برخی از شیعیان وی را بدرجه ٔ الوهیت بالا بردند و علی (ع ) آنان را نصیحت کرد و بترک این عقیده ٔ باطل دستور فرمود.<br>شهادت : درین مدت سه تن از خوارج بنام برک (یا مبارک )بن عبداﷲ و عمروبن بکر و عبدالرحمان بن ملجم مرادی با یکدیگر هم قسم شدند تا بزعم خویش برای رهایی ملل اسلام از اختلافات داخلی، در یک شب امیرالمؤنین علی (ع ) و معاویه حاکم شام و عمروبن عاص حاکم مصر را به قتل رسانند. و ازین سه تن تنها عبدالرحمان بن ملجم مرادی که مأمور کشتن علی (ع ) بود بهدف خود رسید و در شب نوزدهم رمضان سال <span class=\"hlight\" dir=\"rtl\">٤٠</span> هَ . ق . ضربتی با شمشیر بر سر امیرالمؤمنین زد که درنتیجه ٔ این ضربت دو روز بعد یعنی بیست ویکم رمضان حضرت در سن شصت وسه سالگی به شهادت رسید و در کوفه در محلی بنام القری (یا الغری ) که امروز به «نجف » مشهور است دفن گردید.<br>فرزندان : امیرالمؤمنین علی (ع ) نخستین بار با فاطمه (ع ) دختر پیغمبر اکرم (ص ) ازدواج کرد و تا وقتی که او در قید حیات بود همسر دیگری اختیار نکرد. او را مجموعاً بیست وهشت فرزند بود که یازده تن ذکور و هفده تن اناث بودند. و برخی نوشته اند که او را پانزده پسر و هجده دختر بود. اما دربعضی مآخذ از جمله «تجارب السلف » تعداد فرزندان او را چهل وهشت تن نوشته اند که شامل بیست پسر و بیست وهشت دختر میشود. از پسران وی پنج تن نسل و عقب داشتند که نسب تمام علویان روی زمین به این پنج تن میرسد، و آنان عبارتند از: حسن، حسین، محمدبن حنفیة، عمرأطرف و عباس . و سایر پسران وی از همسران مختلف میباشند ونام آنها در کتب مختلف مذکور است . اما از جمله دختران آن حضرت، زینب و ام کلثوم از فاطمه ٔ زهراء (ع ) هستند که زینب را به عبداﷲبن جعفر طیّار و ام کلثوم را به عمربن خطاب به زنی داد و زیدبن عمر از اوست . و سایر دختران وی که از همسران مختلف هستند نام آنها در کتابهای گوناگون ذکر شده است .<br>سخنان : کلمات قصار و خطب آن حضرت که همگی پر از پند و حکمت و اندرزهای عالی میباشند بصورتهای گوناگون نقل شده است که از همه مهمتر مجموعه ای است که شریف رضی در قرن چهارم هجری گردآوری کرد و آن را «نَهج البلاغه » نامید. این کتاب مشتمل بر سه فصل است : اول در خطبه ها و فرمان ها، دوم در نامه ها و رسائل، سوم در پند و حکمت و مواعظ. ولی در صحت انتساب برخی از قطعات آن شک و تردید است . و نیز اشعاری به وی نسبت میدهند که غالب دانشمندان صحت بیشتر آنها را رد میکنند.<br>صفات عالیه : علی بن ابی طالب علیه السلام فرزند اولین خانواده ٔ هاشمی است که پدر و مادر او دو فرزندان هاشمند و از کودکی در دامان بزرگترین معلم و مربی بشریت یعنی پیغمبر اکرم (ص ) رشدونموکرد و محبت متقابل این دو عموزاده و ایثار و فداکاری علی (ع ) تا آنجا رسید که شب هجرت پیغمبر (ص ) علی به آسانی درصدد جانبازی برآمد و با خفتن در بستر پیغمبر جان خود را وقایه ٔ جان رسول اﷲ قرار داد. حدت ذهن وقوت فهم و ادراک علی (ع ) تا آنجا بود که در سن شش هفت سالگی دعوت رسول خدا را بسیار بیش از آنچه در این سن میتوان تمییز داد دریافت و به رسول اﷲ (ص ) و دین جدید او ایمان آورد. شجاعت وی در بدایت عمر در حجاز چنان ولوله ای انداخت که وقتی عمروبن عبدود قهرمان نامی عرب را در نبرد تن به تن (در غزوه ٔ خندق ) به خاک انداخت، خواهر عمرو در مقام رثاء بر مرگ برادر، شجاعت قاتل را تنها مایه ٔ تسلی خود خواند و گفت اگر جز به دست این پهلوان نوجوان کشته شده بودی مادام العمر بر مرگ تو میگریستم . قوت جسم و نیروی بازوی علی (ع ) از عجایب است و حال آنکه دوست و دشمن و مورخان مسلمان ومسیحی همه بر این امر اتفاق دارند که خوراک امیرالمؤمنین ساده ترین و فقیرانه ترین خوارکی بود که امکان دارد با آن زندگی کرد. وی با همه ٔ توانائی و نیرومندی و با آن بازوی جنگ آوری که دنیا نظیر آن را کم دیده است، هیچگاه بر دشمن پیش دستی نکرد، مثلاً به فرزندش حسن (ع ) توصیه میکرد که هرگز کسی را به مبارزه مطلب، ولی اگر دشمن تو را به جنگ خواند روی مگردان زیرا جنگ طلب متعدی است و متعدی مغلوب .<br>بعد از واقعه ٔحکمیت وقتی خوارج نهروان از سپاه او جدا شدند، علی (ع ) می دانست خوارج جنگ با او را تدارک می بینند، حتی چند تن از سرداران مصلحت دیدند قبل از اینکه آنها دست به کار شوند، امیرالمؤمنین فرمان حمله بدهد. امام فرمود: «در عین حال که اطمینان دارم بزودی دست به تیغخواهند برد، مادام که آنها شروع به جنگ نکرده اند هرگز شمشیر به روی آنها نخواهم کشید». و از این قبیل شواهدی که دلالت صریح بر شجاعت بی نظیر علی علیه السلام می کند بسیار است . او در عین حال در مروت و جوانمردی نیز کم نظیر بود چنانکه در مواردی سپاهیان وی درصدد انتقام از جنایات دشمن بودند و او فرمود: «هرگز آنها را که پشت به میدان نبرد کرده و گریخته اند و آنها را که زخم خورده اند به قتل نرسانید، پرده ٔ ناموس دشمنان را ندرید، اموال دشمن را به غنیمت مبرید». پاک دلی وصفای ضمیر و عفو و اغماض امیرالمؤمنین نسبت به دشمنان به حدی بود که به جرأت میتوان گفت - و تمام مورخان مسیحی و مسلمان از شیعی و سنی بر آن اتفاق دارند- که نظیر آن از هیچ سردار جنگی و هیچ قائد و پیشوائی در هیچ زمانی دیده نشده است . شواهد تاریخی بر این خلق وخوی آسمانی و خاصه ٔ ملکوتی فراوان دیده می شود، چنانکه مورد اتفاق تمام مورخان است که در جنگ جمل برمرگ طلحه و زبیر گریست . و به محمدبن ابی بکر پسرخوانده ٔ خود فرمان داد تا خواهرش عایشه را پس از شکست و پراکنده شدن نگهبانان شتر - که بمنزله ٔ پرچم بصریان بود - به خانه ٔ مطمئنی منتقل کند و سه روز بعد علی (ع ) به دیدن عایشه رفت و بجای ملامت و ناسزا او را اکرام کرد و دستور داد با منتهای حرمت او را روانه ٔ مدینه کنند تا در خانه ٔ خود بماند، و شخصاً موقع حرکت به گرمی با او وداع کرد.<br>شاید در سراسر تاریخ جهان جز از دهان علی بن ابی طالب (ع ) کسی نشنیده است که درباره ٔ قاتل با قساوت و ناپاک خود سفارش کند «به این مردی که در بند شماست از همان شیری که من مینوشم بنوشانید، اگر جان بدربردم خود می دانم، و اگر از ضربت او به سرای دیگر رفتم و خواستید قصاص کنید او را با یک ضربت بکشید. مبادا او را مثله کنید که از رسول خدا (ص ) شنیدم که از مثله بپرهیزید ولو نسبت به سگ گزنده ». بهرحال خصوصیات اخلاقی و صفات کم نظیر او به حدی است که درین مختصر نمیتوان شرح داد. و همین خصال باعث شد که بسیاری از فِرَق غُلاة وی را به خدائی بپرستند و هرچند خود علی (ع ) این دسته از مردم گمراه را به سختی تنبیه می کرد دست از اعتقاد خویش برنمیداشتند (راجع به غُلاة و فِرَق مختلف و عقاید آنان رجوع به «غُلاة» و «غالیة» شود). محبوبیت علی علیه السلام نزدتمام مسلمانان بخصوص نزد ایرانیان بی نظیر است . و سبب آن علاوه بر صفاتی که خاص وی است، روشی بود که مطابق قوانین اسلام و تأکیدات پیغمبر اکرم (ص ) درباره ٔ برابر شمردن عرب و عجم در اسلام پیش گرفته بود، چنانکه مثلاً عبیداﷲ فرزند خلیفه ٔ دوم به گمان اینکه هرمزان (حاکم خوزستان که در جنگ با مسلمانان اسیر و پناهنده و سپس مسلمان شده بود) در کشتن پدرش دست داشته بیدرنگ و بدون رسیدگی و حکم حاکم او را کشت، و علی (ع ) هرچند که حکومتی در دست نداشت مجازات عبیداﷲ و قصاص خون هرمزان را به اصرار از خلیفه ٔ سوم طلب کرد. اما عثمان بنابه اشاره ٔ اشراف مدینه و به بهانه ٔ اینکه بر مسلمانان مشکل است خانواده ٔ خلیفه ٔ دوم که داغدار مرگ خلیفه اند داغ تازه ای ببینند، از اجرای مقررات اسلام درباره ٔ قصاص شانه خالی کرد. و درحقیقت نمی خواست که یک تن عرب را به خاطر قتل یک عجم نومسلمان به قتل رساند. اما علی علیه السلام از اولین روز حکومت خود در جستجوی عبیداﷲ بود تا او را مجازات کند و می فرمود «اگر بر این فاسق دست یابم او را به قصاص خون هرمزان خواهم کشت »، تا سرانجام در میدان صفین به دست یاران امیرالمؤمنین (ع ) کشته شد. علاوه بر اینها اشتراک علویان و ایرانیان در مخالفت با خلفای اموی که به سختی از تبعیض نژادی پیروی می کردند و نیز عادت ایرانیان به سلطنت موروثی و از این قبیل امور باعث شد که ایرانیان غالباً علاقه ای خاص نسبت به علی بن ابی طالب (ع ) وفرزندان و خاندان او پیدا کنند، چنانکه کتابهای بسیاری در فضایل و کرامات وی نوشته اند و برخی از ایرانیان شرح حال آن حضرت و وقایع زندگی او را به نظم آورده اند که از آن جمله است نظم «حمله ٔ حیدری » تألیف ملابمان علی، و «خاورنامه » تألیف محمدبن حسام الدین (متوفی در <span class=\"hlight\" dir=\"rtl\">٨٩٢</span> هَ . ق .). (از تجارب السلف نخجوانی صص <span class=\"hlight\" dir=\"rtl\">٣٦</span> - <span class=\"hlight\" dir=\"rtl\">٥٢</span> اعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٧</span> از کامل التواریخ ابن اثیر و تاریخ طبری ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٨</span> و صفة الصفوة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١١٨</span> و مقاتل الطالبیین ص <span class=\"hlight\" dir=\"rtl\">١٤</span> و حلیة الاولیاء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦١</span> و سایر مآخذ، و از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١١٢</span> از تاریخ دمشق ابن عساکر ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٦</span> و الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٦</span> و کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">٦٠٦</span> و <span class=\"hlight\" dir=\"rtl\">٧١٥</span> و <span class=\"hlight\" dir=\"rtl\">٨٠٢</span> و سایر مآخذ و از حبیب السیر چ طهران ص <span class=\"hlight\" dir=\"rtl\">١٨٣</span> و شرح نهج البلاغه ٔ ابن ابی الحدید و مرد نامتناهی تألیف حسن صدر و سایر مآخذ).<br></font></div>'),
(186213, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی طلحه ٔ شامی، مکنی به ابوطلحة. از روات حدیث بود. رجوع به ابوطلحة (علی بن ...) شود.<br></font></div>'),
(186214, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی طیب، علی بن عبداﷲبن احمد نیشابوری، مکنی به ابوالحسن و مشهور به ابن ابی الطیب .رجوع به علی نیشابوری (ابن عبداﷲبن احمد...) شود.<br></font></div>'),
(186215, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی عاص . وی فرزند ابوالعاص و زینب بنت خدیجة (ع ) است که نزدیک به بلوغ درگذشت . (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣٠</span>).<br></font></div>'),
(186216, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی عاص بن ربیعبن عبدالعزی بن عبدشمس بن امیه ٔ قرشی عبشمی . رجوع به علی عبشمی شود.<br></font></div>'),
(186217, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی عبداﷲ هارون بن علی بن یحیی بن ابی منصور، مکنی به ابوالحسن و مشهور به ابن منجم . رجوع به علی بن هارون بن علی بن ... شود.<br></font></div>'),
(186218, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن أبی عزبن عبداﷲ باجسرای حنبلی، مکنی به ابوالحسن . رجوع به علی باجسرای شود.<br></font></div>'),
(186219, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن أبی علی بن محمدبن سالم تغلبی آمدی حنبلی شافعی، ملقب به سیف الدین . رجوع به علی آمدی شود.<br></font></div>'),
(186220, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی علی محمدبن مقلة، مکنی به ابوالحسین . وی در روزگار المتقی عباسی به وزارت رسید و هنگامی که متقی از خلافت خلع شد، این ابوالحسین علی هنوز وزیر بود. (از تجارب السلف نخجوانی ص <span class=\"hlight\" dir=\"rtl\">٢٢١</span>).<br></font></div>'),
(186221, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی فتح کاتب، مشهور به مطوق . رجوع به علی مطوق شود.<br></font></div>'),
(186222, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی فرج بن حسن بصری، مکنی به ابوالحسن و ملقب به صدرالدین . رجوع به علی بصری شود.<br></font></div>'),
(186223, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن أبی فرج زمزمی (علی خلیفه ...). رجوع به علی خلیفة شود.<br></font></div>'),
(186224, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن زکریا، مشهور به ابن زکرون و مکنی به ابوالحسن . فقیه و عالم علم فرائض و محدث و صوفی از اهل طرابلس بود که در سال <span class=\"hlight\" dir=\"rtl\">٣٧٠</span> هَ . ق . درگذشت . او را مؤلفات بسیاری است . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٥</span> از الدیباج ابن فرحون ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠١</span>).<br></font></div>'),
(186225, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی فضل، حسن بن ابی المجد حلبی، مکنی به ابوالحسن . رجوع به علاءالدین حلبی شود.<br></font></div>'),
(186226, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن ابی قاسم خوانساری . رجوع به علی خوانساری شود.<br></font></div>'),
(186227, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی قاسم عبداﷲبن اماجور منجم، مکنی به ابوالحسن . رجوع به ابوالحسن (علی بن ابی القاسم ...) و به ابن اماجور شود.<br></font></div>'),
(186228, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی قرة، علی بن احمد ابیوردی شیعی، مکنی به ابوالحسن و مشهور به ابن ابی قرة. رجوع به علی ابیوردی (ابن احمد...) شود.<br></font></div>'),
(186229, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی قصیبة. علی بن محمدبن علی غزالی، مشهور به ابن ابی قصیبة. رجوع به علی غزالی (ابن محمدبن علی ...) شود.<br></font></div>'),
(186230, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی کثیر، مملوک . او را پنجاه ورقه شعر است . (از الفهرست ابن الندیم ).<br></font></div>'),
(186231, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی کرم محمدبن محمدبن عبدالکریم بن عبدالواحد شیبانی جزری موصلی، مشهور به ابن اثیر جزری و ملقب به عزالدین و مکنی به ابوالحسن . رجوع به ابن اثیر و علی بن محمدبن محمدبن عبدالکریم بن ... شود.<br></font></div>'),
(186232, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن ابی لطف . علی بن محمدبن علی بن ابی اللطف مقدسی شافعی، مکنی به ابوالفضل و مشهور به ابن ابی اللطف . رجوع به علی مقدسی (ابن محمدبن علی بن ...) شود.<br></font></div>'),
(186233, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی مجدبن شرف بن احمد حمصی دمشقی . رجوع به علی حمصی شود.<br></font></div>'),
(186234, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی محمدبن ابی سعدبن عبداﷲ واسطی، مشهور به دیوانی و مکنی به ابوالحسن . رجوع به علی دیوانی شود.<br></font></div>'),
(186235, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی محمدبن عبداﷲبن علی بن زکریا زبحی جرجانی، مکنی به ابوالحسن . رجوع به علی زبحی (ابن محمدبن ...) شود.<br></font></div>'),
(186236, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی محمدحسن بن هبةاﷲبن عبداﷲبن حسین دمشقی شافعی، مشهور به ابن عساکر و مکنی به ابوالقاسم و ملقب به ثقةالدین . رجوع به ابن عساکر و علی بن حسن بن هبة اﷲبن ... شود.<br></font></div>'),
(186237, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی وفاء، علی بن سعدبن علی بن عبدالواحدبن عبدالقاهربن احمدبن مسهر موصلی، مکنی به ابوالحسن و ملقب به مهذب الدین و مشهور به ابن ابی الوفاء. رجوع به علی موصلی (ابن سعدبن علی بن ...) شود.<br></font></div>'),
(186238, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمد جمالی حنفی رومی زنبیلی، ملقب به علاءالدین . رجوع به علی جمالی شود.<br></font></div>'),
(186239, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمدبن ابراهیم حسینی مشهدی أحسائی، ملقب به جمال الدین . رجوع به علی أحسائی شود.<br></font></div>'),
(186240, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمدبن ابراهیم عزیزی بولاقی شافعی، ملقب به نورالدین . رجوع به علی عزیزی شود.<br></font></div>'),
(186241, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمدبن احمدبن عبدالقادربن عثمان منوفی جوفی . رجوع به علی منوفی شود.<br></font></div>'),
(186242, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمدبن اسحاق بن احمدبن حسن حسنی یمنی صنعانی . رجوع به علی صنعانی شود.<br></font></div>'),
(186243, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمدبن داوود رزاز. رجوع به علی رزاز شود.<br></font></div>'),
(186244, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمدبن سلیمان بن حمزه ٔ مقدسی سالحی حنبلی، ملقب به فخرالدین . رجوع به علی مقدسی شود.<br></font></div>'),
(186245, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمدبن طرطوسی حرمی، مکنی به ابوبکر. از علمای قرن چهارم هجری . رجوع به علی حرمی شود.<br></font></div>'),
(186246, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمدبن علی واحدی نیشابوری شافعی، مکنی به ابوالحسن . رجوع به ابوالحسن (علی بن احمد ابن ...)، و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦</span> و سیرالنبلاء ذهبی ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٤</span> و طبقات الشافعیه ٔ اسنوی ص <span class=\"hlight\" dir=\"rtl\">١٨٢</span> و اسماء الرجال الناقلین عن الشافعی و المنسوبین الیه تألیف ابن هدایة ص <span class=\"hlight\" dir=\"rtl\">٦١</span> و مناقب الشافعی و طبقات اصحابه من تاریخ الذهبی ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span> و فهرس المؤلفین بالظاهریة وفیات الاعیان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤١٩</span> و طبقات الشافعیة ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٩</span> و معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٧</span> و کامل التواریخ ابن اثیر ج <span class=\"hlight\" dir=\"rtl\">١٠</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥</span> و البدایه ٔ ابن کثیرج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١١٤</span> و طبقات القراء ابن جزری ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٢٣</span> و انباء الرواة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٣</span> و طبقات الشافعیه ٔ ابن هدایة ص <span class=\"hlight\" dir=\"rtl\">٥٨</span> و شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٠</span> و مختصر دول الاسلام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣</span> و بغیةالوعاة سیوطی ص <span class=\"hlight\" dir=\"rtl\">٣٢٧</span> و النجوم الزاهرة ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٤</span>و مرآةالجنان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٩٦</span> و المختصر فی اخبار البشر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠١</span> و مفتاح السعادة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٠٢</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٧٦</span> و <span class=\"hlight\" dir=\"rtl\">١٢٥</span>و سایر صفحات و روضات الجنات خوانساری ص <span class=\"hlight\" dir=\"rtl\">٤٨٤</span> و فهرست الخدیویة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span> و <span class=\"hlight\" dir=\"rtl\">٢٢١</span> و ایضاح المکنون ص <span class=\"hlight\" dir=\"rtl\">٦٧٣</span> و فهرس المخطوطات المصورة ص <span class=\"hlight\" dir=\"rtl\">٥٠</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٩٢</span>.<br></font></div>'),
(186247, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمدبن عمربن سالم بن عبیداﷲبن حسن علوی حسینی زیدی شافعی، مکنی به ابوالحسن . رجوع به علی زیدی شود.<br></font></div>'),
(186248, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمدبن غزال نیشابوری، مکنی به ابوالحسن . رجوع به ابوالحسن (علی بن احمدبن ...)، و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧</span> و معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٢</span> و التحبیر سمعانی ص <span class=\"hlight\" dir=\"rtl\">٦٣</span>.<br></font></div>'),
(186249, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمدبن کوثر محاربی غرناطی، مکنی به ابوالحسن . رجوع به علی محاربی شود.<br></font></div>'),
(186250, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمدبن معصوم بن نصیرالدین بن ابراهیم بن سلام اﷲبن مسعودبن محمدبن منصور حسنی حسینی، مشهور به ابن معصوم . ادیب و شاعر قرن یازدهم هجری . رجوع به سیدعلی خان شود.<br></font></div>'),
(186251, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمدبن یوسف بن مروان بن عمرغسانی، مکنی به ابوالحسن . رجوع به علی غسانی شود.<br></font></div>'),
(186252, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمد بنا دمیاطی . رجوع به علی بنا شود.<br></font></div>'),
(186253, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن قاسم بن موسی، مشهور به مصباح زرویلی . رجوع به علی زرویلی شود.<br></font></div>'),
(186254, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمد دیبلی شافعی . رجوع به علی دیبلی شود.<br></font></div>'),
(186255, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمدرتبلی، مکنی به ابوالحسن . رجوع به علی رتبلی شود.<br></font></div>'),
(186256, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن احمدبن محمد رسموکی . رجوع به علی رسموکی شود.<br></font></div>'),
(186257, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمد شیرازی مکی شافعی، ملقب به علاءالدین . رجوع به علی شیرازی شود.<br></font></div>'),
(186258, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمد فنجکردی نیشابوری، ملقب به شیخ الافاضل و مکنی به ابوالحسن . رجوع به علی فنجکردی شود.<br></font></div>'),
(186259, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن محمد کیزاوانی حموی شاذلی، مکنی به ابوالحسن . رجوع به علی حموی شود.<br></font></div>'),
(186260, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن مکابر شظبی یمنی . رجوع به علی یمنی شود.<br></font></div>'),
(186261, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن مکرم اﷲ صعیدی عدوی مالکی ازهری . رجوع به علی صعیدی شود.<br></font></div>'),
(186262, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن احمدبن مکی رازی، ملقب به حسام الدین و مشهور به ابن مکی . فقیه و ساکن دمشق بود و به حلب نیز سفر کرد، و در سال <span class=\"hlight\" dir=\"rtl\">٥٩٣</span> یا <span class=\"hlight\" dir=\"rtl\">٥٩٨</span> هَ . ق . در دمشق درگذشت و در خارج باب فرادیس دفن شد. او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- خلاصة الدلائل فی تنقیح المسائل، در فروع فقه حنفی، و آن شرح قدوری است . <span class=\"hlight\" dir=\"rtl\">٢</span>- سلوة الهموم . <span class=\"hlight\" dir=\"rtl\">٣</span>- فتاوی . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠</span> از فهرست مخطوطات الفقه الحنفی بالظاهریة و مفتاح السعادة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٢</span> و تاج التراجم ص <span class=\"hlight\" dir=\"rtl\">٣١</span> و الجواهر المضیة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٣</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٩٩٩</span> و سایر صفحات، و الفوائد البهیة ص <span class=\"hlight\" dir=\"rtl\">١١٨</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٠٣</span>).<br></font></div>'),
(186263, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن منصور بسام، مشهور به بسامی و ابن بسام . رجوع به علی بسامی و ابن بسام شود.<br></font></div>'),
(186264, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن موسی بن امام محمد تقی علیه السلام، مکنی به ابوالقاسم . محدث و فقیه و از غُلات شیعه میباشد که در سال <span class=\"hlight\" dir=\"rtl\">٣٥٢</span> هَ . ق . در یکی از قراء فارس درگذشت . او راست : الاغاثة فی الثلاثة.<br></font></div>'),
(186265, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن موسی بن علی جلاد راکبی نخلی حنفی . رجوع به علی جلاد شود.<br></font></div>'),
(186266, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن موسی بن محمد تقی علیه السلام، مکنی به ابوالقاسم . رجوع به علی بن احمدبن موسی بن امام محمد تقی شود.<br></font></div>'),
(186267, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن عرام بن احمد ربعی اسوانی . رجوع به علی ربعی شود.<br></font></div>'),
(186268, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن زین الدین بحری (علی تقی ...). رجوع به علی بحری شود.<br></font></div>'),
(186269, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن سعیدبن حزم بن غالب بن صالح بن خلف بن سفیان بن یزید فارسی اندلسی قرطبی یزیدی، مکنی به ابومحمد و مشهور به ابن حزم . فقیه و ادیب قرن پنجم هجری . رجوع به ابن حزم و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٦</span> و سیر النبلاء ذهبی ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٨</span> و فهرس المؤلفین بالظاهریةو وفیات الاعیان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢٨</span> و الصلة ص <span class=\"hlight\" dir=\"rtl\">٤٠٨</span> و جذوةالمقتبس ص <span class=\"hlight\" dir=\"rtl\">٢٩٠</span> و مطمح الانفس ص <span class=\"hlight\" dir=\"rtl\">٥٥</span> و معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٥</span> و تذکرة الحفاظ ذهبی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢١</span> و البدایة ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩١</span> و تاریخ الحکماء ص <span class=\"hlight\" dir=\"rtl\">٢٣٢</span> و لسان المیزان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٨</span> و النجوم الزاهرة ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٧٥</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٢١</span> و <span class=\"hlight\" dir=\"rtl\">١١٨</span> و سائر صفحات و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٩</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٢</span> و <span class=\"hlight\" dir=\"rtl\">٢٧٢</span> و سائر صفحات ونفح الطیب ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٢</span> و مرآة الجنان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٧٩</span> و بغیة الملتمس ص <span class=\"hlight\" dir=\"rtl\">٤٠٣</span> و مختصر دول الاسلام ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span> و ظهرالاسلام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٥٣</span> و المتجددون فی الاسلام ص <span class=\"hlight\" dir=\"rtl\">١٩٠</span> و ابن حزم نوشته ٔ محمد ابوزهرة و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٩٠</span> و ابن حزم نوشته ٔطه حاجری و تاریخ الفکر الاندلسی ص <span class=\"hlight\" dir=\"rtl\">٧٤</span> و فهرست المخطوطات المصوره ٔ سید ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٤</span> و برکلمن ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> و غیره .<br></font></div>'),
(186270, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن سلک فالی، مکنی به ابوالحسن و مشهوربه مؤدب . رجوع به علی فالی (ابن احمدبن ...) شود.<br></font></div>'),
(186271, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن سهل فوشنجی هروی، مکنی به ابوالحسن . از عرفای نیمه ٔ اول قرن چهارم هجری . رجوع به ابوالحسن فوشنجی و نامه ٔ دانشوران ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥</span> و حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٤</span> شود.<br></font></div>'),
(186272, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن طالب معدل . رجوع به علی معدل شود.<br></font></div>'),
(186273, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن عباس اندآنی، مکنی به ابوالحسن . والی اصفهان . رجوع به علی اندآنی شود.<br></font></div>'),
(186274, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن عبدالرحمان بن احمدبن عبدالرحمان بن یعیش زهری باجی، مکنی به ابوالحسن . رجوع به علی باجی شود.<br></font></div>'),
(186275, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن عبدالعزیزبن عبدالحق بن خراسان، مشهور به ابن خراسان . آخرین تن از امرای آل خراسان در تونس بود. وی در سال <span class=\"hlight\" dir=\"rtl\">٥٥٣</span> هَ . ق . پس از درگذشت عمش عبداﷲبن عبدالعزیز به حکومت رسید ولی در سال <span class=\"hlight\" dir=\"rtl\">٥٥٤</span> هَ . ق . بر اثر فشار عبدالمؤمن کومی، ناچار شد که از تونس به مراکش رود، اما قبل از رسیدن به مراکش در سال <span class=\"hlight\" dir=\"rtl\">٥٥٥</span> هَ .ق . درگذشت و بدین ترتیب حکومت آل خراسان نیز منقرض گشت . (از الاعلام زرکلی از الخلاصة النقیة ص <span class=\"hlight\" dir=\"rtl\">٥٤</span> و البیان المغرب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٦</span> و دائرة المعارف الاسلامیة ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٨</span>).<br></font></div>'),
(186276, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن عبدالعزیز میوروقی، مکنی به ابوالحسن . رجوع به علی میوروقی شود.<br></font></div>'),
(186277, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن عبداﷲ بغدادی، مکنی به ابوخطاب . رجوع به علی بغدادی شود.<br></font></div>'),
(186278, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن عبدالمؤمن زواوی مغربی مالکی . رجوع به علی زواوی شود.<br></font></div>'),
(186279, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن عبدالنبی بن محمد طسوجی . رجوع به علی طسوجی شود.<br></font></div>'),
(186280, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن عبدالواحد مقدسی حنبلی، مشهور به ابن بخاری و ملقب به فخرالدین و مکنی به ابوالحسن . رجوع به علی بخاری شود.<br></font></div>'),
(186281, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن عثمان بن محمدبن اسحاق سلمی مناوی قاهری شافعی . رجوع به علی مناوی شود.<br></font></div>'),
(186282, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی سعدبن أبی الفرج خیاط، مکنی به ابوالحسن . رجوع به علی خیاط شود.<br></font></div>'),
(186283, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن علی بن احمد ارموی حنبلی، ملقب به زین الدین . رجوع به علی ارموی شود.<br></font></div>'),
(186284, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن علی بن بندار یزدی حنفی، مکنی به ابوالقاسم . رجوع به علی یزدی شود.<br></font></div>'),
(186285, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن علی بن سلیمان فالی، مکنی به ابوالحسن . رجوع به علی فالی شود.<br></font></div>'),
(186286, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن علی بن عبدالمنعم، مشهور به ابن هبل و خلاطی، و ملقب به مهذب الدین، و مکنی به ابوالحسن . رجوع به ابن هبل و علی خلاطی شود.<br></font></div>'),
(186287, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن علی بن محمدبن جعفربن عبداﷲبن حسین بن علی بن ابی طالب، مکنی به ابوالحسن . رجوع به علی عقیقی شود.<br></font></div>'),
(186288, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن علی بن محمدبن دواس القنا الواسطی، مکنی به ابوالحسن و مشهور به ابن واسطی . از معاریف علمای نجوم . رجوع به ابوالحسن (علی بن احمدبن ...) و تاریخ الحکماء قفطی ص <span class=\"hlight\" dir=\"rtl\">٢٤٠</span> شود.<br></font></div>'),
(186289, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن احمدبن علی جندی یمنی . رجوع به علی جندی شود.<br></font></div>'),
(186290, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن علی شریشی، مشهور به ابن لبال و مکنی به ابوالحسن . رجوع به علی شریشی شود.<br></font></div>'),
(186291, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن علی عرشانی یمنی . رجوع به علی عرشانی شود.<br></font></div>'),
(186292, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن علی کزبری، ملقب به علأالدین و مکنی به ابوالحسن . رجوع به علی کزبری شود.<br></font></div>'),
(186293, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن عمربن محمدبن احمد بوشی انصاری، ملقب به نورالدین و مکنی به ابوالحسن . رجوع به علی بوشی شود.<br></font></div>'),
(186294, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن فضل أربکی . رجوع به علی أربکی شود.<br></font></div>'),
(186295, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن قاسم بن محمد حسنی یمنی، مشهور به داعی . رجوع به داعی شود.<br></font></div>'),
(186296, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن ابی بکر انصاری شافعی، مشهور به کلبشی و کلبشاوی . رجوع به علی انصاری شود.<br></font></div>'),
(186297, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع ُ لا ]</font></b> (اِخ ) شهری است به سواد وادی القری . (منتهی الارب ) (از متن اللغة).علا. (معجم البلدان ) (متن اللغة). موضعی است از ناحیه ٔ وادی القری، که بین آن و شام واقع شده و پیغمبر (ص ) در راه خویش بسوی تبوک در آنجا فرودآمد، و در محلی که نماز گزارد مسجدی ساخته شد. (از معجم البدان ).<br></font></div>'),
(186298, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع ُ لا ]</font></b> (اِخ ) موضعی است به دیار غطفان . (منتهی الارب ). علا. (معجم البلدان ) (متنن اللغة).<br></font></div>'),
(186299, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع ُ لا ]</font></b> (اِخ ) چند چاه است به دیار کلاب . (منتهی الارب ). چاههایی است نزدیک حصا از دیار کلاب . (از معجم البلدان ). چاههایی به دیار بنی کلاب .(از متن اللغة). علا. (معجم البلدان ) (متن اللغة).<br></font></div>'),
(186300, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع ُ لا ]</font></b> (اِخ ) موضعی است به دیار بنی تمیم . (از متن اللغة). علا. (متن اللغة).<br></font></div>'),
(186301, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع ُ ]</font></b> (اِ) ممال عُلی ̍ در فارسی . رجوع به عُلی ̍ شود <span class=\"hlight\">:</span> <br>جمال حسن معالی ابوالحسن طاهر<br>که از ثری اثر قدر اوست تا به علی .<br><font color=\"Red\">ادیب صابر.</font><br></font></div>'),
(186302, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع ِ لی ی ]</font></b>(ع اِمص ) بلندی . (از تاج العروس ) (اقرب الموارد).<br></font></div>'),
(186303, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع ِل ْ لی ی ]</font></b> (ع اِ) مکان بلند. (یادداشت مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> آسمان هفتم . (یادداشت مرحوم دهخدا). <BR><font color=\"Blue\">◄</font> دیوان خیر که در آن أعمال صلحا نوشته میشود. (یادداشت مرحوم دهخدا). منزلی در آسمان هفتم که در آن ارواح مؤمنان میباشد. (ناظم الاطباء). ج، عِلّیّین، عِلّیّون . <BR><font color=\"Blue\">◄</font> اشراف و أجلّه ٔمردم . (ناظم الاطباء) (از اقرب الموارد). عُلّیة. عِلّیة. عُلّی . (اقرب الموارد). <BR><font color=\"Blue\">◄</font> (ص نسبی )منسوب به علة که بطنی است از قضاعة. (از سمعانی ).<br></font></div>'),
(186304, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع ُل ْ لی ی ]</font></b> (ع اِ) اشراف و اجله ٔ مردم . (ناظم الاطباء) (از اقرب الموارد). عِلّی . عِلّیة. عُلّیة.<br></font></div>'),
(186305, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ لی ی ]</font></b> (ع ص ) بلند. (منتهی الارب ) (از لسان العرب ) (تاج العروس ) (اقرب الموارد). بلندبرآمده و درشت . <BR><font color=\"Blue\">◄</font> بزرگ و بلندقدر و شریف . (منتهی الارب ). شریف . (لسان العرب ). شریف و بزرگ . (از اقرب الموارد). <BR><font color=\"Blue\">◄</font> آنکه بالاتر از او چیزی نیست . (از لسان العرب ) (از متن اللغة). بزرگوار و برتر از همه ٔ خلق . (مهذب الاسماء). <BR><font color=\"Blue\">◄</font> توانا و کلان . (منتهی الارب ). سخت و صلب . (از لسان العرب ). سخت و قوی . (از اقرب الموارد). سخت و قوی و صلب . (از متن اللغة). <BR><font color=\"Blue\">◄</font> کسی که در مقابل زنان نرم باشد. (از لسان العرب ) (تاج العروس ) (ذیل اقرب الموارد). <BR><font color=\"Blue\">◄</font> (اِخ ) نامی از نامهای خدای تعالی . (مهذب الاسماء).از اسماء حسنی است . (از اقرب الموارد) <span class=\"hlight\">:</span> <br>این علی را از نژاد بوعلی اندر جهان <br>نیست همتای تو فرزندی فواﷲ العلی .<br> <font color=\"Red\">سوزنی .</font><br>ج، عِلْیة (منتهی الارب ) (لسان العرب ) (اقرب الموارد)، عَلیّون، عَلیّین . (از اقرب الموارد).<br></font></div>'),
(186306, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن آیبک بن عبداﷲ تقصادی ناصری دمشقی، ملقب به علاءالدین . رجوع به علی دمشقی شود.<br></font></div>'),
(186307, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن آیبک بن ترکمانی صالحی، ملقب به نورالدین و منصور. دومین تن از ممالیک بحری در مصر و شام . رجوع به علی بحری (ابن آیبک ...) شود.<br></font></div>'),
(186308, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن أبان مهلبی . رجوع به علی مهلبی (ابن أبان ...) شود.<br></font></div>'),
(186309, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم . از فضلای اواخر قرن <span class=\"hlight\" dir=\"rtl\">١٢</span> و اوایل قرن <span class=\"hlight\" dir=\"rtl\">١٣</span> هجری بود. وی در سال <span class=\"hlight\" dir=\"rtl\">١١٤١</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">١٢١٣</span> هَ . ق . درگذشت . او راست : سر المصون فی نکتة الاظهار و الاضمار. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٣</span> از حلیة البشر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥٩</span>).<br></font></div>'),
(186310, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم، ملقب به بوش . محدث است . (از منتهی الارب ). و مؤلف تاج العروس لقب او را «بوشی » ذکر کرده است و می نویسد که او را محمدبن عبدالرحمان حضرمی روایت میکند.<br></font></div>'),
(186311, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع ُ لا ]</font></b> (ع اِمص ) بزرگی و بلندی قدر و بلندی در منزلت . (منتهی الارب ). بزرگی و شرف . (از اقرب الموارد). رجوع به علا شود. <BR><font color=\"Blue\">◄</font> (ص، اِ) ج ِ عُلیا.(اقرب الموارد) (ناظم الاطباء). رجوع به علیا شود.<br></font></div>'),
(186312, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن احمدبن علی بن عمر حلبی قاهری شافعی، ملقب به نورالدین و مکنی به ابوالحسن . رجوع به علی حلبی شود.<br></font></div>'),
(186313, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن اسماعیل غزنوی حنفی، ملقب به ناصرالدین . رجوع به علی غزنوی شود.<br></font></div>'),
(186314, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن بختیشوع کفرطابی . پزشک و کحال قرن پنجم هجری . رجوع به علی کفرطابی شود.<br></font></div>'),
(186315, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن بکش، مکنی به ابوالحسن . وی طبیب بود، و در <span class=\"hlight\" dir=\"rtl\">٢٥</span> یا <span class=\"hlight\" dir=\"rtl\">٢٦</span> ذی القعده ٔ سال <span class=\"hlight\" dir=\"rtl\">٣٩٤</span> هَ . ق . درگذشت . او را مقالاتی کوتاه است . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٤</span> از تاریخ الحکماء قفطی ص <span class=\"hlight\" dir=\"rtl\">٢٣٥</span>). و نیز رجوع به ابوالحسن (علی بن ابراهیم بن بکوس ) شود.<br></font></div>'),
(186316, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن بکوس، مکنی به ابوالحسن . رجوع به ابوالحسن (علی بن ...) و نیز به علی بن ابراهیم بن بکش شود.<br></font></div>'),
(186317, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن سلمان بن سلیمان عطار دمشقی شافعی، ملقب به علاءالدین و مکنی به ابوالحسن . رجوع به علی عطار شود.<br></font></div>'),
(186318, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن سعیدبن یوسف حوفی مصری، مکنی به ابوالحسن . رجوع به علی حوفی شود.<br></font></div>'),
(186319, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن سلمةبن بحر قطان قزوینی، مکنی به ابوالحسن . رجوع به علی قطان شود.<br></font></div>'),
(186320, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن شاطر. عالم ریاضی دمشق (متوفی در سال <span class=\"hlight\" dir=\"rtl\">٧٧٧</span>هَ . ق .). رجوع به علی بن شاطر و به ابن شاطر شود.<br></font></div>'),
(186321, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن عباس حسینی علوی، مکنی به ابوالقاسم و مشهور به نسیب . رجوع به علی نسیب شود.<br></font></div>'),
(186322, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن عبدالرحمان عمادی . رجوع به علی عمادی شود.<br></font></div>'),
(186323, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن علی بن ابراهیم جذامی، مشهور به ابن قفاص . رجوع به علی قفاص شود.<br></font></div>'),
(186324, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن علی بن عبدالرحمان امیمی شریشی . رجوع به علی امیمی شود.<br></font></div>'),
(186325, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن علی بن معتوق واسطی، مشهور به ابن ثردة. رجوع به علی واسطی (ابن ابراهیم بن ...) شود.<br></font></div>'),
(186326, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مصطفی موستاری سکتواری، ملقّب به علاءالدین و مشهور به علی دده و به شیخ التربة. رجوع به علی دده شود.<br></font></div>'),
(186327, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مصیصی، مکنّی به ابوالحسن . رجوع به مصیصی شود.<br></font></div>'),
(186328, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مُطلِب برقی . محدث بود. (منتهی الارب ) (از تاج العروس ).<br></font></div>'),
(186329, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مطیر. علی بن محمدبن ابی بکربن ابراهیم بن ابی القاسم بن عمربن احمدبن ابراهیم بن محمدبن عیسی بن مطیر حکمی یمنی شافعی، مشهور به ابن مطیر. رجوع به علی حکمی (ابن محمدبن ابی بکربن ...) شود.<br></font></div>'),
(186330, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مطیر. علی بن محمدبن ابی بکربن مطیر، مشهور به ابن مطیر. رجوع به علی بن محمدبن ابی بکربن ... شود.<br></font></div>'),
(186331, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مظفربن ابراهیم . و یا هدیةبن عمربن یزید کندی اسکندرانی وداعی دمشقی . متوفی در <span class=\"hlight\" dir=\"rtl\">٧١٦</span> هَ . ق . رجوع به علاءالدین (ابن مظفر) شود.<br></font></div>'),
(186332, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مظفربن علی بن حسن بن مسلمة، مکنّی به ابوالقاسم . ادیب و شاعر و نویسنده بود (<span class=\"hlight\" dir=\"rtl\">٤٥٥</span> تا <span class=\"hlight\" dir=\"rtl\">٤٩٣</span> هَ . ق .) او را رسائلی است . (از معجم المؤلفین بنقل از الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٣</span>).<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(186333, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مظفربن مبارزالدین (شاه ...). وی یکی از چهار پسر شاه شرف الدین مظفر حاکم شیراز، و برادر کوچکتر شاه یحیی بود. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٧</span>) (تاریخ مفصل ایران، مغول چ عباس اقبال ص <span class=\"hlight\" dir=\"rtl\">٤٢٦</span>).<br></font></div>'),
(186334, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن معاویةبن احمد ازدی مهلبی بصری شیعی (علی بلال ...)، مکنّی به ابوالحسن . رجوع به علی مهلبی شود.<br></font></div>'),
(186335, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن معتضد، ملقّب به المکتفی باﷲ و مکنّی به ابومحمد. هفدهمین خلیفه ٔ عباسی . رجوع به علی عباسی (ابن احمد معتضدبن موفق ...) شود.<br></font></div>'),
(186336, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن معصوم . علی بن احمدبن محمدبن معصوم بن نصیرالدین بن ابراهیم بن سلام اﷲبن مسعودبن محمدبن منصور حسنی حسینی، مشهوربه ابن معصوم (علی خان ...) رجوع به سیدعلی خان شود.<br></font></div>'),
(186337, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن معقل، مکنّی به ابوالحسن . «حبال » صاحب کتاب الوفیات از وی یاد کرده و او را صاحب ابوعلی فارسی دانسته و سال وفات وی را ربیعالاول <span class=\"hlight\" dir=\"rtl\">٤٣٣</span> هَ . ق . آورده است . (از معجم الادباء یاقوت، چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢١</span>).<br></font></div>'),
(186338, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن عمربن خلیل بغدادی، مشهور به خازن و ملقب به علاءالدین . رجوع به خازن شود.<br></font></div>'),
(186339, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ لا ]</font></b> (ع جرف جر) بر. (ناظم الاطباء). برای استعلا بکار رود. (از منتهی الارب ) (از لسان العرب ) (تاج العروس ) (مغنی اللبیب ). مانند« <span class=\"hlight\">:</span> و علیها و علی الفلک تحملون ». (قرآن <span class=\"hlight\" dir=\"rtl\">٢٢/٢٣</span>). (منتهی الارب ). برای استعلا آید، خواه حقیقی باشد مانند «علی الفلک تحملون » وخواه معنوی باشد مانند «فضلنا بعضهم علی بعض ». (از مغنی اللبیب ) (از اقرب الموارد). بمعنای استعلا آید، خواه حقیقی باشد چون «حملته علی رأسی »، و خواه مجازی مانند «له علی ّ حق ». (از متن اللغة). <BR><font color=\"Blue\">◄</font> با. مع. برای مصاحبت آید. (از منتهی الارب ) (از مغنی اللبیب ) (از لسان العرب ) (اقرب الموارد) (متن اللغة). مانند <span class=\"hlight\">:</span> «... آتی المال علی حبّه ...» (قرآن <span class=\"hlight\" dir=\"rtl\">١٧٧/٢</span>). (منتهی الارب ) (تاج العروس ) (متن اللغة). <BR><font color=\"Blue\">◄</font> از. عن . برای مجاوزت . (منتهی الارب ) (از مغنی اللبیب ) (از تاج العروس ) (اقرب الموارد) (متن اللغة). مانند <span class=\"hlight\">:</span> <br>اًذا رضیت ْ علی ّ بنوقُشیر<br>لعمر اﷲ أعجنبی رضاها. تحیف عقیلی . (ازتاج العروس ) (از منتهی الارب ) (مغنی اللبیب ) (اقرب الموارد).<br><BR><font color=\"Blue\">◄</font> ازبرای . ل ِ. برای تعلیل . (منتهی الارب ) (از مغنی اللبیب ) (از تاج العروس ) (اقرب الموارد) (متن اللغة). مانند <span class=\"hlight\">:</span> «... لتکبروا اﷲ علی ماهداکم ...». (قرآن <span class=\"hlight\" dir=\"rtl\">٣٧/٢٢</span>). (منتهی الارب ) (مغنی اللبیب ) (تاج العروس ) (متن اللغة). <BR><font color=\"Blue\">◄</font> در. فی . برای ظرفیت . (منتهی الارب ) (از مغنی اللبیب ) (تاج العروس )(اقرب الموارد) (متن اللغة). مانند <span class=\"hlight\">:</span> «و دخل المدینة علی حین غفلة من أهلها...». (قرآن <span class=\"hlight\" dir=\"rtl\">١٥/٢٨</span>). (منتهی الارب ) (مغنی اللبیب ) (تاج العروس ) (اقرب الموارد) (متن اللغة). <BR><font color=\"Blue\">◄</font> از. مِن . (منتهی الارب ) (از مغنی اللبیب ) (تاج العروس ) (اقرب الموارد). مانند <span class=\"hlight\">:</span> «الذین اًذا اکتالوا علی الناس یستوفون ». (قرآن <span class=\"hlight\" dir=\"rtl\">٢/٨٣</span>). (منتهی الارب ) (مغنی اللبیب ) (تاج العروس ) (اقرب الموارد). <BR><font color=\"Blue\">◄</font> به . ب ِ. با.(منتهی الارب ) (از مغنی اللبیب ) (تاج العروس ) (اقرب الموارد) (متن اللغة). مانند <span class=\"hlight\">:</span> «حقیق علی ان لاأقول علی اﷲ اًلا الحق ...». (قرآن <span class=\"hlight\" dir=\"rtl\">١٠٥/٧</span>). (از منتهی الارب ) (مغنی اللبیب ) (تاج العروس ). و مانند: «ارکب علی اسم اﷲ»؛ أی باسم اﷲ. (مغنی اللبیب ) (اقرب الموارد) (متن اللغة). <BR><font color=\"Blue\">◄</font> برای استدراک آید.(از منتهی الارب ) (متن اللغة). ولی . بمعنای «لکن ». (از تاج العروس ). برای استدراک و اضراب آید. (از مغنی اللبیب ) (اقرب الموارد). مانند: «فلان جهنمی، علی أنه لاییأس من رحمة اﷲ». (منتهی الارب ) (تاج العروس ) (متن اللغة). <BR><font color=\"Blue\">◄</font> گاهی زائد آید بعوض چیزی . (منتهی الارب ) (از تاج العروس ) (اقرب الموارد) (متن اللغة). مانند:<br>اًن الکریم و أبیک یعتمل <br>اًن لم یجد یوماً علی من یتّکل .<br>که بوده است ... من یتکل علیه، و «علیه » حذف شده و «علی » پیش از «من » موصول بجای آن آمده است . (از منتهی الارب ) (تاج العروس ) (اقرب الموارد) (متن اللغة). و گاهی زائد آید بی آنکه جانشین چیزی باشد. مانند: لاأحلف علی یمین ؛ أی یمیناً. (از تاج العروس ) (متن اللغة). <BR><font color=\"Blue\">◄</font> و گاهی اسم، بمعنی «فوق » شمارند آنرا، یقال : أتیته من علی ؛ أی فَوق الدار. (منتهی الارب ). و حرف جر بر آن داخل شود. مانند غَدت مِن علیه بعدما تم ّ ظمؤها؛ أی غدت مِن فوقه . (منتهی الارب ) (از تاج العروس ). و گاهی اسم آید بمعنی «فوق »، و آن در صورتی است که بعد از «مِن » واقع شود، مانند: «نزل مِن علی جَناح الهیکل ». (از اقرب الموارد). گاهی اسم آید، و در این صورت حتماً ظرف است، مانند این بیت مزاحم عُقَیلی :<br>غدت ْ من علیه بعدما تم ّ ظمؤها<br>تَصل ّ وعن قیض ِ بزیزاء مَجهل <br>که بمعنای «عند» میباشد. (از لسان العرب ) (متن اللغة). <BR><font color=\"Blue\">◄</font> و گاه «اسم فعل » آید بمعنای گرفتن و ملازم بودن، مانند «علیک زیداً و علیک بزید»؛ أی الزمه و خذه . (از منتهی الارب ) (تاج العروس ) (اقرب الموارد) (متن اللغة). و هرچند اصل آن از ارتفاع و بلندی است ولی گاه بسبب کثرت استعمال بمعنای هَلم ّ (بیا، بیاور) بکار رود. (از منتهی الارب ) (تاج العروس ). مانند «علی ّ زیداً و علی ّ بزید»؛ یعنی زید را بمن بده یا او را برایم بیاور. (از منتهی الارب ) (اقرب الموارد) (متن اللغة). الف «علی »، هرچند در اصل واو بوده است، در هنگام اتصال به ضمایر، قلب به یاء شود، مانند: علیه و علیک و علینا. ولی بعضی از عرب، الف آن را به حال خود باقی گذارند، مانند: «طاروا علاهن ّ فطر علاها»، أی علیهن و علیها. و این لهجه ٔ حارث بن کعب باشد. (از منتهی الارب ) (اقرب الموارد) (متن اللغة). گاهی لام و الف آن حذف میشود و فقط عین باقی میماندو همچون «علی » مابعد خود را جر میدهد، مانند: عَلماءِ بنوفلان ؛ أی علی الماء. (از متن اللغة).<br></font></div>'),
(186340, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع ُل ْی ْ ]</font></b> (ع اِ) بزرگان و اشراف و أجله . (از متن اللغة).<br></font></div>'),
(186341, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع ِل ْی ْ ]</font></b> (ع مص ) بالای سقف برآمدن . (از منتهی الارب ). بالا رفتن و صعود کردن . (از تاج العروس ) (متن اللغة). عَلْی . عُلی ّ. رجوع به عَلْی وعُلی ّ شود. <BR><font color=\"Blue\">◄</font> (اِ) اشراف و اجله . (از ناظم الاطباء) (از اقرب الموارد). رجوع به عِلیة شود.<br></font></div>'),
(186342, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْی ْ ]</font></b> (اِخ ) موضعی است در جبال هذیل . و در شعر امیةبن ابی عائذ آمده است <span class=\"hlight\">:</span> <br>لمن الخیام بعلی فالاحراص <br>فالسودتَین فمجمع الابواص .<br><font color=\"Red\">(از معجم البلدان ).</font><br></font></div>'),
(186343, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َل ْی ْ ]</font></b> (ع مص ) بالای سقف برآمدن . (از منتهی الارب ). بالا رفتن و صعود کردن . (از تاج العروس ) (اقرب الموارد) (متن اللغة). عِلْی . عُلی ّ. رجوع به عِلْی و عُلی ّ شود. <BR><font color=\"Blue\">◄</font> (اِ) هر جای بلند. (ناظم الاطباء) (از اقرب الموارد) (متن اللغة).<br></font></div>'),
(186344, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مکرم . علی بن حسین بن مکرم، مکنّی به ابوالقاسم و ملقّب به ناصرالدین و مؤیدالدولة و مشهور به ابن مکرم . از ملوک عمان . رجوع به علی (ابن حسین بن مکرم ...) شود.<br></font></div>'),
(186345, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی بکربن عبدالرحمان سقاف علوی، ملقب به نورالدین . رجوع به علی سقاف شود.<br></font></div>'),
(186346, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی بکربن علی بن ابی بکربن عمربن احمدبن عبدالرحمان بن محمد خزرجی انصاری مکی شافعی، مشهور به ابن جمال مصری . رجوع به علی مصری شود.<br></font></div>'),
(186347, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی بکربن علی بن محمدبن أبی بکربن عبداﷲبن عمربن عبدالرحمان بن عبداﷲ یمانی زبیدی شافعی، مشهور به ناشری و ملقب به موفق الدین . رجوع به علی ناشری شود.<br></font></div>'),
(186348, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی بکربن علی هروی موصلی، ساکن حلب، مکنی به ابوالحسن . رحالة و خطیب بودکه به علم سیما و چهره آشنایی داشت . اصل وی از هرات بود و در موصل متولد شد و در بسیاری از شهرها گردش کرد. و در دهه ٔ دوم رمضان سال <span class=\"hlight\" dir=\"rtl\">٦١١</span> هَ . ق . درگذشت . او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- الاشارات الی معرفة الزیارات من صحیح الروایات . <span class=\"hlight\" dir=\"rtl\">٢</span>- الخطب الهرویة. <span class=\"hlight\" dir=\"rtl\">٣</span>- منازل الارض ذات الطول و العرض . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٤٧</span> از کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٩٦</span>و <span class=\"hlight\" dir=\"rtl\">٥١٧</span> و سایر صفحات و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٠٥</span> و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٨</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠١</span> و وفیات الاعیان ابن خلکان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣٧</span> و شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span> و فهرست الخدیویة ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨</span> و الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣</span> و فهرس المؤلفین بالظاهریة). و نیز رجوع به ابوالحسن سیاح شود.<br></font></div>'),
(186349, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مغلی . علی بن محمودبن ابی بکر حموی مصری حنبلی، مشهور به ابن مغلی و ملقّب به علاءالدین . رجوع به علی حموی (ابن محمودبن ابی بکر...) شود.<br></font></div>'),
(186350, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مغیره ٔ اثرم بغدادی، مکنّی به ابوالحسن . رجوع به اثرم (علی بن ...)، و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٤</span>. تاریخ دمشق ابن عساکر ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٦</span>. الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٨</span>. الفهرست ابن الندیم ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٦</span>. معجم الادباء یاقوت ج <span class=\"hlight\" dir=\"rtl\">١٥</span> ص <span class=\"hlight\" dir=\"rtl\">٧٧</span>. النجوم الزاهره ٔ ابن تغری بردی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٣</span>. ایضاح المکنون بغدادی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٦</span>. الاعلام زرکلی چ <span class=\"hlight\" dir=\"rtl\">٢</span> ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٥</span>. ارشادالاریب ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢١</span>. نزهةالالباس ص <span class=\"hlight\" dir=\"rtl\">٢١٨</span>. انباه الرواة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٩</span>.<br></font></div>'),
(186351, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مفضل بن علی بن مفرج بن حاتم بن حسن بن جعفر لخمی مقدسی اسکندرانی مالکی، مکنّی به ابوالحسن و ملقّب به شرف الدین . رجوع به علی مقدسی شود.<br></font></div>'),
(186352, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن مفید، مکنّی به ابوالقاسم . از فضلای قرن پنجم هجری، او راست : نزهةالناظر و تنبیه الخاطر فی کلمات النبی و الائمة. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٥</span>).<br></font></div>'),
(186353, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مقاتل بن عبدالخالق حموی . رجوع به علی حموی شود.<br></font></div>'),
(186354, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مقرب بن منصوربن مقرب بن حسن بن عزیزبن ضبار ربعی عیونی، مکنّی به ابوعبداﷲ و ملقّب به جمال الدین . رجوع به علی ربعی شود.<br></font></div>'),
(186355, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مقرب احسائی . رجوع به علی احسائی شود.<br></font></div>'),
(186356, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن مقلدبن نصربن منقذ کنانی، مکنّی به ابوالحسن و ملقّب به سدیدالملک . رجوع به علی کنانی شود.<br></font></div>'),
(186357, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مقلد ندیم، مکنّی به ابوالحسن . وی موسیقیدان بود و در غناء و آهنگ های مختلف دستی داشت و مدتی ندیم المستظهر و المسترشد بوده است و در سال <span class=\"hlight\" dir=\"rtl\">٥١٧</span> هَ . ق . درگذشت . او را کتابی است در اغانی و نیز منظومه هائی به او نسبت می دهند. (از معجم المؤلفین بنقل از الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٩</span>).<br></font></div>'),
(186358, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مقلة. علی بن حسن بن اسماعیل بن احمدبن جعفربن محمدبن صالح بن حسان بن حصن عبدری، مشهور به ابن مقلة و مکنّی به ابوالحسن .رجوع به علی عبدری (ابن حسن بن اسماعیل بن ...) شود.<br></font></div>'),
(186359, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن معلی بزاز. وی محدث و از مردم سینیز(دهی به فارس ) بود. (منتهی الارب ) (از تاج العروس ).<br></font></div>'),
(186360, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مکی . علی بن احمدبن مکی رازی، ملقّب به حسام الدین و مشهور به ابن مکی . رجوع به علی (ابن احمدبن مکی ...) شود.<br></font></div>'),
(186361, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی بکربن محمدبن علی بن محمدبن شراد برعی أبیاری زبیدی یمنی شافعی، مکنی به ابوالحسن . رجوع به علی برعی شود.<br></font></div>'),
(186362, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی حزم قرشی دمشقی مصری شافعی، مشهور به ابن نفیس و ملقب به علاءالدین . طبیب و دانشمند مشهور قرن هفتم هجری . رجوع به ابن نفیس و کتب ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٥٨</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٤٦٣</span> و <span class=\"hlight\" dir=\"rtl\">١٠٢٤</span> و سایر صفحات و ایضاح المکنون بغدادی ص <span class=\"hlight\" dir=\"rtl\">١٨٨</span> و النجوم الزاهره ٔ ابن تغری ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٧</span> و طبقات الشافعیة سبکی ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٩</span> و البدایه ٔ ابن کثیر ج <span class=\"hlight\" dir=\"rtl\">١٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٣</span> و شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٤٠١</span> و مختصر دول الاسلام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span> و الدارس نعیمی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣١</span> و حسن المحاضره ٔسیوطی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٣</span> مفتاح السعاده ٔ طاش کبری ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٩</span> و مرآة الجنان یافعی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٧</span> و فهرست الخدیویة ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠</span> وفهرس الطب، المکتبة البلدیة ص <span class=\"hlight\" dir=\"rtl\">٢٢</span> و فهرس مخطوطات الموصل ص <span class=\"hlight\" dir=\"rtl\">٢١٧</span> و روضات الجنات خوانساری ص <span class=\"hlight\" dir=\"rtl\">٤٩٦</span> و فهرست کتابخانه ٔ دانشگاه تهران ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٨١١</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧١٤</span> و تلخیص مجمع الاَّداب ابن فوطی ص <span class=\"hlight\" dir=\"rtl\">١١٧</span> و تاریخ الاسلام ذهبی جزء آخر ص <span class=\"hlight\" dir=\"rtl\">٧٢</span> و طبقات الشافعیه ٔ اسنوی ص <span class=\"hlight\" dir=\"rtl\">١٧٦</span> و فهرس مخطوطات الطب بالظاهریة و الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١</span>.<br></font></div>'),
(186363, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی حزین، ملقب به علاءالدین . رجوع به ابن نفیس و علی بن ابی حزم قرشی ... شود.<br></font></div>'),
(186364, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن عبدالملک بن عباس قزوینی نحوی، مکنّی به ابوطالب . رجوع به علی قزوینی (ابن عبدالملک ...) شود.<br></font></div>'),
(186365, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی حسن فضلوی . پدر او ابوالحسن فضلوی رئیس کردانی بود که در سال <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> هَ . ق . از جبل السماق شام به لرستان آمدند. و علی را واقعه ای در شکار اتفاق افتاده است که در تاریخ حبیب السیر مذکور میباشند، بدانجا مراجعه شود. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٥</span>).<br></font></div>'),
(186366, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی حسین عبدالرحیم سلمی، مکنی به ابوالحسن و مشهور به ابن قصار. ادیب و لغوی وخطاط. رجوع به ابن قصار (ابوالحسن علی بن ...) شود.<br></font></div>'),
(186367, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی حمزة. وی را سفری به حج در معیت امام جعفر الصادق (ع ) دست داده بود و از آن امام درین راه معجزاتی دیده است که تفصیل آن در تاریخ حبیب السیر آمده است . (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣</span>).<br></font></div>'),
(186368, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی حمله، مکنی به ابونصر. محدث بود. و نیز رجوع به ابونصر علی شود.<br></font></div>'),
(186369, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن أبی رافع، علی بن عبداﷲ بغدادی، مکنی به ابوالحسن و مشهور به ابن ابی رافع. رجوع به ابن ابی رافع و علی بغدادی (ابن عبداﷲ...) شود.<br></font></div>'),
(186370, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی رجال، علی شیبانی مغربی، مشهور به ابن ابی الرجال و مکنی به ابوالحسن منجم است (<span class=\"hlight\" dir=\"rtl\">٤٠٦</span> - <span class=\"hlight\" dir=\"rtl\">٤٥٤</span> هَ . ق .). او راست : البارع فی أحکام النجوم و الطوالع. رجوع به ابن ابی الرجال ونیز به کتب ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٩٢</span> و فهرس المؤلفین بالظاهریة و کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">٢١٧</span>.<br></font></div>'),
(186371, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن أبی زهران، علی بن یعقوب بن شجاع بن علی بن ابراهیم بن محمدبن ابی زهران موصلی شافعی، ملقب به عمادالدین و مکنی به ابوالحسن و مشهور به ابن ابی زهران . رجوع به علی موصلی (ابن یعقوب بن شجاع بن ...) شود.<br></font></div>'),
(186372, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی زید محمدبن علی نحوی استرابادی، ملقب به فصیحی و مکنی به ابوالحسن . رجوع به ابوالحسن (علی بن ابی زید...) شود.<br></font></div>'),
(186373, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم خزاعی، مکنی به ابوالحسن . رجوع به علی خزاعی شود.<br></font></div>'),
(186374, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن محمدبن اسحاق کاتب . رجوع به علی کاتب شود.<br></font></div>'),
(186375, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن محمدبن اسماعیل بن صلاح حسنی یمانی صنعانی . رجوع به علی صنعانی شود.<br></font></div>'),
(186376, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن ابراهیم بن محمدبن عیسی بن سعدالخیر انصاری بلنسی، مکنی به ابوالحسن . رجوع به علی بلنسی شود.<br></font></div>'),
(186377, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن محمدبن همام بن محمدبن ابراهیم بن حسن انصاری دمشقی، مشهور به ابن شاطر و مطعم و ملقب به علاءالدین و مکنی به ابوالحسن . عالم فلکی . رجوع به علی (ابن شاطر) شود.<br></font></div>'),
(186378, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن محمد حسینی جویمی شیرازی شافعی، ملقب به نورالدین . رجوع به علی جویمی شود.<br></font></div>'),
(186379, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن محمد دهکی رازی، مکنی به ابوالقاسم . رجوع به علی دهکی شود.<br></font></div>'),
(186380, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن محمد زهری شروانی مدنی نقشبندی حنفی، ملقب به کمال الدین . رجوع به علی شروانی شود.<br></font></div>'),
(186381, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن معلی . از مشایخ شیعه و راوی فقه، از ائمه بود. (از الفهرست ابن الندیم ).<br></font></div>'),
(186382, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن موسی بن جعفر الصادق (ع ). فرزند او «محمد» روایت کند که با پدرخود «علی » در وقتی که سخت محتاج بودند بنزد امام حسن عسکری (ع ) رفتند و آن امام از عالم غیب به حاجت آنان پی برد و بدانها کمک کرد. تفصیل واقعه در تاریخ حبیب السیر آمده است (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩٩</span>).<br></font></div>'),
(186383, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن هاشم . از علماء و فقهای شیعه است و کتاب المناقب و کتاب اختیار القرآن و کتاب قرب الاسناد و کتاب نوادر القرآن از اوست . (از الفهرست ابن الندیم ). اما در همان کتاب الفهرست کتاب المناقب و کتاب اختیار القرآن و کتاب قرب السناد از علی بن هاشم دانسته شده است .<br></font></div>'),
(186384, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بن هاشم قمی، مکنی به ابوالحسن . رجوع به علی قمی شود.<br></font></div>'),
(186385, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم انباری شیعی . از فضلای قرن دهم هجری . رجوع به علی انباری شود.<br></font></div>'),
(186386, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم بحری مصری مالکی، ملقب به نورالدین و مکنی به ابوالحسن . از قضات قرن نهم هجری . رجوع به علی مصری شود.<br></font></div>'),
(186387, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن ابراهیم حصری، مکنی به ابوالحسین . از عرفای قرن چهارم هجری . رجوع به ابوالحسین حصری شود.<br></font></div>'),
(186388, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن موسی بن محمد دیری جوبری دمشقی شافعی، ملقب به علاءالدین و مکنی به ابوالحسن . رجوع به علی دیری شود.<br></font></div>'),
(186389, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم درویش، ساکن حلب . رجوع به علی درویش شود.<br></font></div>'),
(186390, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم رامزبن ابراهیم حسن . از اطبای قاهره است . رجوع به علی رامز شود.<br></font></div>'),
(186391, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم قمی . از فقهای قرن <span class=\"hlight\" dir=\"rtl\">١٤</span> هجری . رجوع به علی قمی شود.<br></font></div>'),
(186392, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم کنانی فیجاطی، مکنی به ابوالحسن . رجوع به علی کنانی شود.<br></font></div>'),
(186393, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابراهیم مغنیساوی رومی حنفی (علی رضا...)، مشهور به اولیازاده . رجوع به علی رضابن ابراهیم ... شود.<br></font></div>'),
(186394, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن ابی احمد حسین طاهربن موسی بن محمدبن موسی ابراهیم بن امام موسی بن جعفر الصادق (ع )، ملقب به علم الهدی و ثمانینی و ذوالثمانین و ذوالمجدین و سیدمرتضی و شریف مرتضی . رجوع به علم الهدی موسوی شود.<br></font></div>'),
(186395, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی اصیبعة علی بن خلیفةبن یونس بن ابی القاسم بن خلیفه ٔ خزرجی، مشهور به ابن ابی اصیبعة و ملقب به رشیدالدین و مکنی به ابوالحسن . رجوع به علی بن خلیفةبن یونس بن ... و ابن ابی اصیبعة شود.<br></font></div>'),
(186396, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی بکربن حمیر یمنی همدانی، ملقب به سراج الدین و مکنی به ابوالحسن . رجوع به علی همدانی شود.<br></font></div>'),
(186397, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی بکربن خلیفه ٔ همدانی حسینی یمانی شافعی، مشهور به ابن أزرق و ملقب به موفق الدین و نورالدین و مکنی به ابوالحسن . رجوع به علی أزرق شود.<br></font></div>'),
(186398, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی بکربن سلیمان هیثمی شافعی، ملقب به نورالدین و مکنی به ابوالحسن . رجوع به علی هیثمی شود.<br></font></div>'),
(186399, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی بکربن عبدالجلیل فرغانی مرغینانی حنفی، ملقب به برهان الدین و مکنی به ابوالحسن . رجوع به علی مرغینانی شود.<br></font></div>'),
(186400, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن معلی .وی کلانتر قطیف بود و در سال <span class=\"hlight\" dir=\"rtl\">٢٨١</span> هَ . ق . یکی از بزرگان قرمطی به نام یحیی بن ذکرویه بن مهرویه به منزل اورفت و به نام اینکه وی از جانب امام محمد مهدی (ع ) آمده است از آنجا آغاز تبلیغ اهالی قطیف و بحرین به مذهب قرامطه کرد. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٥</span>).<br></font></div>'),
(186401, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ابی بکربن عبدالرحمان بن محمد باعلوی . رجوع به علی سقاف شود.<br></font></div>'),
(186402, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جاراﷲبن محمدبن ابی الیمن بن ابی بکربن علی بن محمدبن محمدبن حسین بن احمد قرشی مخزومی حنفی، مشهور به ابن ظهیرة. رجوع به علی مخزومی شود.<br></font></div>'),
(186403, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بهرام بن اسکندر روزافزون، صاحب مازندران . رجوع به علی روزافزون شود.<br></font></div>'),
(186404, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بُهَیش . محدث است . (منتهی الارب ).<br></font></div>'),
(186405, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بیان فارسی، مشهور به عیان . رجوع به علی عیان شود.<br></font></div>'),
(186406, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن پیرک پادشاه طغاتیموری (سلطان ...). آخرین پادشاه سلسله ٔ طغاتیموری . رجوع به علی طغاتیموری شود.<br></font></div>'),
(186407, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن تاج الدین سنجاری مکی حنفی . رجوع به علی سنجاری شود.<br></font></div>'),
(186408, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ترکمانی، علی بن عثمان بن ابراهیم بن مصطفی بن سلیمان ماردینی حنفی ترکمانی، ملقب به علاءالدین و مشهور به ابن الترکمانی . رجوع به علی ترکمانی (ابن عثمان بن ...) شود.<br></font></div>'),
(186409, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن تکین (امیر...). نام شاعری است، و محمدبن عمر رادویانی در ترجمان البلاغه قطعاتی از وی نقل کرده است که از آن جمله قطعه ٔ ذیل در لغز فرزند می باشد:<br>پذیره م آمد آن دلربای بر در کاخ <br>سیاه خفتان پوشیده و کلاه بشاخ <br>به من به شرم نگه کرد و راه را برتافت <br>غزال هرگز بر یوز کی بود گستاخ <br>بگفتم او را ای بت متاب روی و مرو<br>که من به روی تو بینم همی جهان فراخ <br>وگر خوهی که بدانی مرا بچه از جای <br>برو بتازی بگریخت گیر با چخماخ .<br><font color=\"Red\">(از ترجمان البلاغه ٔ رادیاونی ص <span class=\"hlight\" dir=\"rtl\">١٠١</span>).</font><br></font></div>'),
(186410, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ثابت بن سعیدبن علی بن محمدبن علی بن سعید تلمسانی قرشی اموی . رجوع به علی تلمسانی شود.<br></font></div>'),
(186411, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ثابت شاعر. وی از رؤسای متکلمین زنادقه (مانویه ) بود که خود را مسلمان می نموده است . (از الفهرست ابن الندیم ).<br></font></div>'),
(186412, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ثردة، علی بن ابراهیم بن علی بن معتوق واسطی، مشهور به ابن ثردة. رجوع به علی واسطی (ابن ابراهیم بن ...) شود.<br></font></div>'),
(186413, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ثروان بن حسن کندی، مکنی به ابوالحسن . رجوع به علی کندی شود.<br></font></div>'),
(186414, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ثمال خفاجی، امیر بنی خفاجة. رجوع به علی خفاجی شود.<br></font></div>'),
(186415, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن تُمامة علی بن نوح بن محمدبن احمدبن ثمامة. رجوع به علی بن نوح بن محمدبن ... شود.<br></font></div>'),
(186416, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جابربن عامر مالکی وفائی . رجوع به علی وفائی شود.<br></font></div>'),
(186417, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بهاءالدین محمد جوینی، نواده ٔ خواجه شمس الدین محمد صاحبدیوان . رجوع به علی جوینی (ابن بهاءالدین ...) شود.<br></font></div>'),
(186418, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن جاسم بن محمد اسدی حلی . رجوع به علی اسدی شود.<br></font></div>'),
(186419, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جباب، علی بن محمدبن سلیمان بن علی بن سلیمان بن حسن انصاری غرناطی، مشهور به ابن جباب و مکنی به ابوالحسن . رجوع به علی انصاری (ابن محمدبن سلیمان بن ...) شود.<br></font></div>'),
(186420, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جبارة، علی بن اسماعیل بن ابراهیم بن جباره ٔ کندی محلی سخاوی مالکی، ملقب به شرف الدین و مکنی به ابوالحسن و مشهور به ابن جبارة. رجوع به علی بن اسماعیل بن ابراهیم بن ... شود.<br></font></div>'),
(186421, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جباره ٔ هذلی بسکری، مکنی به ابوالقاسم . رجوع به علی بسکری شود.<br></font></div>'),
(186422, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جبلةبن مسلم بن عبدالرحمان ابناوی، مکنی به ابوالحسن و مشهور به عکوک . رجوع به علی عکوک شود.<br></font></div>'),
(186423, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جبله ٔ کوفی، مکنی به ابوالحسن ... تابعی است . و نیز رجوع به ابوالحسن (علی بن ...) شود.<br></font></div>'),
(186424, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جدا، علی بن حسین بن احمدبن ابراهیم عکبری، مشهور به ابن جدا و مکنی به ابوالحسن . رجوع به علی عکبری (ابن حسین بن احمدبن ...) شود.<br></font></div>'),
(186425, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جدعان، علی بن زیدبن أبی ملیکةزهیربن عبداﷲبن جدعان، مکنی به ابوالحسن و مشهور به ابن جدعان . رجوع به علی بن زیدبن ابی ملیکة... شود.<br></font></div>'),
(186426, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مکی . علی بن محمدبن مکی بن عیسی بن حسن بن عیسی شامی عاملی جیلی، ملقّب به نجیب الدین و مشهور به ابن مکی . رجوع به علی شامی (ابن محمدبن مکی بن ...) شود.<br></font></div>'),
(186427, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مکی کاظمی . رجوع به علی کاظمی شود.<br></font></div>'),
(186428, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ملک معز، ملقّب به ملک منصور. وی از غلام زادگانی بود که بر مصر سلطنت می کردند. پدر او ملک معز الترکی الصالحی در سال <span class=\"hlight\" dir=\"rtl\">٦٥٥</span> هَ . ق . دختر حاکم موصل را به زنی گرفت و این امر باعث رشک همسر دیگرش شجرةالدر مکنّی به ام خلیل گردید، لذا به توطئه ٔ او ملک معز را در حمام کشتند. پس از او به استصواب امرا و ارکان دولت، پسرش ملک منصورعلی، بر تخت سلطنت نشست و اوام خلیل را به قتل رساند و دو سال بر مصر پادشاهی کرد. در این هنگام غلامان او را خلع کردند و سیف الدین را که اتابک علی بود بر تخت نشاندند و او را به نام ملک مظفر خواندند. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٢</span>).<br></font></div>'),
(186429, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ملمش ترکی، مکنّی به ابوالحسن وملقّب به فخرالدین . نام او را «علی بن بکمش » نیز گفته اند. رجوع به علی ترکی (ابن بکمش بن مزان ...) شود.<br></font></div>'),
(186430, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن منتصر. علی بن محمدبن منتصر طرابلسی، مکنّی به ابوالحسن و مشهور به ابن منتصر. رجوع به علی طرابلسی (ابن محمدبن منتصر...) شود.<br></font></div>'),
(186431, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن منجب بن سلیمان صیرفی مصری، مکنّی به ابوالقاسم . رجوع به علی صیرفی شود.<br></font></div>'),
(186432, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بسام شنترینی اندلسی، مکنی به ابوالحسن (<span class=\"hlight\" dir=\"rtl\">٤٧٧</span> - <span class=\"hlight\" dir=\"rtl\">٥٤٢</span> هَ . ق .). ادیب و شاعر و مورخ رجوع به ابن بسام و به کتب ذیل شود. معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span>ص <span class=\"hlight\" dir=\"rtl\">٤٣</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٨٢٥</span> و معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٥</span> و تاریخ الفکر الاندلسی ص <span class=\"hlight\" dir=\"rtl\">٢٨٨</span> و المخطوطات التاریخیة و ص <span class=\"hlight\" dir=\"rtl\">٥٦</span>و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٠٢</span> و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٤١</span> والوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٣</span> و فهرس المؤلفین بالظاهریة.<br></font></div>'),
(186433, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن باکو، علی بن محمدبن عبداﷲ، مکنی به ابوعبداﷲ و مشهور به ابن باکو. از عرفای نیمه ٔ اول قرن پنجم هجری . رجوع به علی بن محمدبن عبداﷲ شود.<br></font></div>'),
(186434, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بایدوخان . وی یکی از سه پسر بایدوخان است که هیچ یک از ایشان به سلطنت نرسید. (حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span>).<br></font></div>'),
(186435, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بتنونی، علی بن عمربن علی بن حسام الدین ابوصیری حنفی شاذلی، مشهور به ابن بتنونی . رجوع به علی بتنونی (ابن عمربن علی بن ...) شود.<br></font></div>'),
(186436, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بحربن بَرّی . محدث است . (از منتهی الارب ) (از تاج العروس ).<br></font></div>'),
(186437, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بُحَیر تابعی است . (از منتهی الارب ).<br></font></div>'),
(186438, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بُخار. محدث است . (منتهی الارب ) (از تاج العروس ).<br></font></div>'),
(186439, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بخاری، علی بن احمدبن عبدالواحد مقدسی حنبلی، مشهور به ابن بخاری و ملقب به فخرالدین و مکنی به ابوالحسن . رجوع به علی بخاری (ابن احمدبن عبدالواحد...) شود.<br></font></div>'),
(186440, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بدربن خورشیدبن ابی بکر (امیر...). رجوع به علی لر شود.<br></font></div>'),
(186441, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بدربن شجاع الدین خورشیدبن ابی بکر (امیر...). رجوع به علی لر شود.<br></font></div>'),
(186442, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بذیمة. محدث است . (از منتهی الارب ) (از تاج العروس ).<br></font></div>'),
(186443, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بُرَید ابودعامه ٔ قیسی، مکنی به ابوالحسن . رجوع به علی قیسی شود.<br></font></div>'),
(186444, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بری، نام او علی بن محمدبن علی بن محمدبن حسین رباطی مغربی مالکی، مشهور به ابن بری و مکنی به ابوالحسن است . رجوع به ابن بری و علی بن محمدبن علی بن ... شود.<br></font></div>'),
(186445, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن بری سودانی . رجوع به علی سودانی شود.<br></font></div>'),
(186446, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بسام، نام او علی بن محمدبن نصربن منصوربن بسام عبرتائی بغدادی، مکنی به ابوالحسن و مشهور به ابن بسام است . رجوع به ابن بسام و علی بن محمدبن نصربن ... شود.<br></font></div>'),
(186447, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن منجم . علی بن هارون بن علی بن یحیی بن ابی منصور، مکنّی به ابوالحسن و مشهور به ابن منجم . رجوع به علی (ابن هارون بن علی بن ...) شود.<br></font></div>'),
(186448, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بطال، علی بن خلف بن عبدالملک بن بطال بکری قرطبی مالکی، مشهور به ابن لجام و ابن بطال، و مکنی به ابوالحسن . رجوع به علی قرطبی (ابن خلف بن عبدالملک ...) شود.<br></font></div>'),
(186449, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بقال، علی بن یوسف، مکنی به ابوالحسن و مشهور به ابن بقال . رجوع به علی بن یوسف شود.<br></font></div>'),
(186450, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بکار، مکنی به ابوالحسن . وی از مشایخ است و با ابراهیم بن ادهم صحبت داشته است . و از او برخی کرامات نقل کنند. (از نفحات الانس جامی چ توحیدی پور ص <span class=\"hlight\" dir=\"rtl\">١١٩</span>).<br></font></div>'),
(186451, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بکربن وائل . وی جدی است جاهلی و از عدنانیة. او را فرزندی بنام «صعب » بود که نسل وی از اوست . نام او در نهایةالارب قلقشندی بصورت «علی بن صعب بن بکر» آمده است . (از جمهرةالانساب ص <span class=\"hlight\" dir=\"rtl\">٢٩١</span> و سبائک الذهب ص <span class=\"hlight\" dir=\"rtl\">٥</span> و نهایةالارب قلقشندی ص <span class=\"hlight\" dir=\"rtl\">٣٠٠</span>).<br></font></div>'),
(186452, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بکمش بن مزان بن عبداﷲ ترکی، ملقب به فخرالدین و مکنی به ابوالحسن . رجوع به علی ترکی شود.<br></font></div>'),
(186453, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) بلبان بن عبداﷲ فارسی مصری حنفی، ملقب به علاءالدین و مکنی به ابوالحسن . رجوع به علی مصری شود.<br></font></div>'),
(186454, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بلبل الوزیر. وی به بغداد بود و خواهرزاده ای داشت که دچار سکته شده بود و توسط صاعدبن بشر معالجه گردید که شرح آن واقعه در عیون الانباء آمده است . (از عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٢</span>).<br></font></div>'),
(186455, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بلیق حاجب . وی در اوایل خلافت القاهر باﷲ عباسی منصب حجابت او را عهده دار بود، ولی پس از مدتی چون برخی از بزرگان که علی و پدرش بلیق بن مقلة نیز جزء آنان بودند، شروع به مخالفت با القاهر باﷲ کردند. القاهر نیز آنان را به قتل رساند. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٦</span>).<br></font></div>'),
(186456, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بندار رازی حنفی، مکنی به ابوالقاسم . رجوع به علی رازی (ابن بندار...) شود.<br></font></div>'),
(186457, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بندار مؤدب . مافروخی در «محاسن اصفهان » نام او را جزء دانشمندان متقدم عصر خود (قرن پنجم هجری ) آورده است، و ظاهراً وی همان علی بن بندار رازی حنفی است . رجوع به علی رازی (ابن بندار...) شود. (از محاسن اصفهان مافروخی ص <span class=\"hlight\" dir=\"rtl\">٣٢</span>) (از ترجمه ٔ محاسن اصفهان آوی ص <span class=\"hlight\" dir=\"rtl\">١٢٤</span>).<br></font></div>'),
(186458, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بواب، علی بن هلال بغدادی، مشهور به ابن بواب و مکنی به ابوالحسن . رجوع به ابن بواب و علی بن هلال ... شود.<br></font></div>'),
(186459, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بویه بن فناخسرو دیلمی، ملقب به عمادالدوله و مکنی به ابوالحسن . رجوع به عمادالدوله ٔ دیلمی شود.<br></font></div>'),
(186460, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بهاءالدین سام بن شمس الدین محمدبن فخرالدین مسعود، ملقب به ملک جلال الدین . وی از ملوک بامیان است که پس از فوت پدرش بهأالدین سام، مدت هفت سال در بامیان حکومت کرد و در آن سال سلطان محمد خوارزمشاه که در ماوراءالنهر بود، به بامیان حمله کرد و ملک جلال الدین علی را کشت و قلمرواو را تسخیر کرد. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٠٩</span>).<br></font></div>'),
(186461, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حَبْشی بن قونی، مکنی به ابوالقاسم . تلعکبری از وی روایت کرده و در سال <span class=\"hlight\" dir=\"rtl\">٣٣٢</span> هَ . ق . وی را دیده است . او راست : کتاب الهدایا. (از معجم المؤلفین از الفهرست طوسی ص <span class=\"hlight\" dir=\"rtl\">٩٨</span>).<br></font></div>'),
(186462, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن جَنَد. محدث است . (از منتهی الارب ).<br></font></div>'),
(186463, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جُندُب (متوفی در سال <span class=\"hlight\" dir=\"rtl\">٢٦٨</span> هَ . ق .). او راست : کتاب النوادر. (از معجم المؤلفین از الفهرست طوسی ص <span class=\"hlight\" dir=\"rtl\">٩٤</span> و منتهی المقال ابوعلی ص <span class=\"hlight\" dir=\"rtl\">٢٠٩</span> و تنقیح المقال مامقانی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٤</span>).<br></font></div>'),
(186464, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جولوغ سیستانی، مکنی به ابوالحسن و متخلص به فرخی . شاعر مشهور. رجوع به فرخی سیستانی شود.<br></font></div>'),
(186465, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جهضم، علی بن عبداﷲبن حسن بن جهضم همدانی مکی، مکنی به ابوالحسن و مشهور به ابن جهضم . رجوع به علی همدانی (ابن عبداﷲبن حسن بن ...) شود.<br></font></div>'),
(186466, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جهم بن بدربن جهم بن سعود قرشی شامی، مکنی به ابوالحسن و مشهور به ابن جهم (<span class=\"hlight\" dir=\"rtl\">١٨٨</span> تا <span class=\"hlight\" dir=\"rtl\">٢٤٩</span> هَ . ق .). شاعر دربار المتوکل عباسی . رجوع به ابن جهم و نیز به کتب ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٥٤</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٨٠٣</span> و تاریخ بغداد ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦٧</span> و طبقات الشعراء ابن معتز ص <span class=\"hlight\" dir=\"rtl\">١٥١</span> و الموشح مرزبانی ص <span class=\"hlight\" dir=\"rtl\">٣٤٤</span> و الاغانی ج <span class=\"hlight\" dir=\"rtl\">١٠</span> و ص <span class=\"hlight\" dir=\"rtl\">٢٠</span> و کامل التواریخ ابن اثیر ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٩</span> و طبقات الحنابلة ص <span class=\"hlight\" dir=\"rtl\">١٦٤</span> و دیوان ابن جهم تألیف خلیل مردم .<br></font></div>'),
(186467, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جهیر، علی بن محمدبن محمدبن جهیر، مکنی به ابوالقاسم و ملقب به زعیم الدین (یا زعیم الروسا) و مشهور به ابن جهیر. وزیر المستظهر عباسی . رجوع به علی بن محمدبن محمدبن جهیر شود.<br></font></div>'),
(186468, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن چلبی شبینی . ازعلمای اواخر قرن <span class=\"hlight\" dir=\"rtl\">١٣</span> هجری . رجوع به علی شبینی شود.<br></font></div>'),
(186469, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حاتم بن احمد یامی (علی الوحید...). آخرین تن از بنی حمدان یمن . رجوع به علی حمدانی (ابن حاتم ...) شود.<br></font></div>'),
(186470, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حاتم قزوینی، مکنی به ابوالحسن . رجوع به علی قزوینی شود.<br></font></div>'),
(186471, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حاجب النعمان، علی بن عبدالعزیزبن ابراهیم، مکنی به ابوالحسن و مشهور به ابن حاجب النعمان . رجوع به ابن حاجب النعمان (ابوالحسن علی بن ...) و علی بن عبدالعزیزبن ... شود.<br></font></div>'),
(186472, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حازم لحیانی . رجوع به علی لحیانی شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(186473, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حاکم بامر اﷲ، مکنی به ابوالحسن و ملقب به الظاهر لدین اﷲ. وی هفتمین خلیفه ٔ فاطمی مصر است که پس از قتل پدر به سلطنت رسید و در ابتدای کار امیرالجیوش را صاحب منصب ساخت و چون تمکنی پیدا کرد وی را با عمّه ٔ خود به قتل رساند. در سال <span class=\"hlight\" dir=\"rtl\">٤١٥</span> هَ . ق . در عهد این خلیفه در مصر قحط و غلائی عظیم اتفاق افتاد و مدت دو سال ادامه داشت . و در سال <span class=\"hlight\" dir=\"rtl\">٤٢٠</span> او رافرزندی پیدا شد که «سعد» نام نهادش و لقب «المستنصرباﷲ» به او داد. در سال <span class=\"hlight\" dir=\"rtl\">٤٢١</span> قیصر روم با ششصدهزار سپاهی بسوی شام متوجه گشت ولی در حدود حلب تارومار و منهزم گشتند. و در نیمه ٔ شوال سال <span class=\"hlight\" dir=\"rtl\">٤٢٧</span> الظاهر لدین اﷲ در سن سی سالگی بر اثر مرض استسقا درگذشت . مدت خلافتش شانزده سال بود. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥٥</span>). و نیز رجوع به ظاهر (ابن ابی منصور الحاکم )... شود.<br></font></div>'),
(186474, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حامد کحال . وی از کحالین مشهور در دمشق بود. و فرزندش مهذب الدین عبدالرحیم نیز شهرت بسزائی درین علم داشت . (از عیون الانباء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٩</span>).<br></font></div>'),
(186475, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حَبَشون . محدث است . (از منتهی الارب ).<br></font></div>'),
(186476, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جمیل . وی از بنی حبیب بن عبیدة است . و «هجری » گوید که وی در روز فتح در مقدمه ٔ پیغمبر (ص ) بوده است . (از الاصابه ج <span class=\"hlight\" dir=\"rtl\">٤</span> قسم اول ).<br></font></div>'),
(186477, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حبیب اﷲبن محمدبن نوراﷲبن ابی اللطف شافعی قدسی . رجوع به علی قدسی شود.<br></font></div>'),
(186478, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حجازی بن محمد بیومی حسنی ادریسی شاذلی شافعی خلوتی دمرداشی احمدی . رجوع به علی بیومی شود.<br></font></div>'),
(186479, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حجربن ایاس سعدی مروزی . رجوع به علی سعدی شود.<br></font></div>'),
(186480, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حجر، علی بن محمدبن محمدبن علی بن احمدبن حجر عسقلانی مصری کنانی شافعی، مشهور به ابن حجر. رجوع به علی عسقلانی (ابن محمدبن علی بن ...) شود.<br></font></div>'),
(186481, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حجة، علی بن عبداﷲبن حجّة حموی حنفی، ملقب به تقی الدین و مکنی به ابوبکر و مشهور به ابن حجة. رجوع به ابن حجة (ابوالمحاسن تقی الدین ابوبکربن علی ...) و علی بن عبداﷲبن حجة... شود.<br></font></div>'),
(186482, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حجةاﷲبن علی بن عبداﷲبن حسین بن محمدبن عبدالملک طباطبائی شولستانی نجفی، ملقب به شرف الدین . رجوع به علی طباطبائی شود.<br></font></div>'),
(186483, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حداد، علی بن عمربن محمدبن فارس انباری، مشهوربه ابن حداد و ملقب به قوام الدین و مکنی به ابوالفرج . رجوع به علی انباری (ابن عمربن محمدبن ...) شود.<br></font></div>'),
(186484, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حَرازة. عباس دوری از وی روایت دارد. (از منتهی الارب ).<br></font></div>'),
(186485, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حرانی، علی بن حسین بن علی بن علان بن عبدالرحمان، مشهور به ابن حرانی و مکنی به ابوالحسن . رجوع به علی حرانی (ابن حسین بن علی بن ...) شود.<br></font></div>'),
(186486, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حربن یزید ریاحی . وی فرزند حربن یزید است که در واقعه ٔ کربلا پس از پدرش همراه با برادر خود مصعب و غلام پدرش غره، با دشمنان امام حسین (ع ) جنگیدند و به درجه ٔ شهادت رسیدند. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٢</span>).<br></font></div>'),
(186487, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حرب بن محمدبن علی طائی موصلی، مکنی به ابوالحسن . رجوع به علی موصلی شود.<br></font></div>'),
(186488, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حزم، علی بن احمدبن سعیدبن حزم بن غالب بن صالح بن خلف بن سفیان بن یزید فارسی اندلسی قرطبی یزیدی، مکنی به ابومحمد و مشهور به ابن حزم . رجوع به ابن حزم و علی بن احمدبن سعیدبن ... شود.<br></font></div>'),
(186489, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حزمون اندلسی . رجوع به علی اندلسی (ابن حزمون ) شود.<br></font></div>'),
(186490, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جعفربن حسین قدامه ٔ موسوی، مکنی به ابوالقاسم . ممدوح ادیب صابر ترمذی . رجوع به علی موسوی (ابن حسین قدامه ٔ...) شود.<br></font></div>'),
(186491, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن منذر. از محدثان بود. (منتهی الارب ).<br></font></div>'),
(186492, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن منصوربن امیرحاجی خراسانی (امیر...) وی یکی از سه فرزند منصوربن حاجی خراسانی است و او را فرزندی نبود. و برادر کهترش امیر مظفر که نزد اتابک یوسف شاه تربیت یافت، جد افراد سلسله ٔ «آل مظفر» می باشد. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٣</span>).<br></font></div>'),
(186493, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن منصوربن طالب حلبی، ملقب به دوخلة و مشهور به ابن قارح و مکنّی به ابوالحسن . رجوع به علی حلبی (ابن منصوربن ...) شود.<br></font></div>'),
(186494, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن منصوربن عبیداﷲ خطیبی اصفهانی بغدادی، مکنّی به ابوعلی و مشهور به اجل لغوی . رجوع به علی خطبیی شود.<br></font></div>'),
(186495, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جدید، علی بن محمدبن احمدبن جدیدبن علی بن محمدبن جدید حضرمی تریمی شافعی، مشهور به ابن جدید. رجوع به علی حضرمی (ابن محمدبن احمدبن ...) شود.<br></font></div>'),
(186496, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جراح، علی بن عیسی بن داوودبن جراح بغدادی، مکنی به ابوالحسن و مشهور به ابن جراح . رجوع به ابوالحسن (علی بن عیسی ...) و ابن جراح و علی بن عیسی بن داوودبن ... شود.<br></font></div>'),
(186497, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جروی، علی بن عبدالعزیزبن وزیر جَرَوی، مشهور به ابن جروی . رجوع به علی بن عبدالعزیزبن وزیر جروی شود.<br></font></div>'),
(186498, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جزار مصری حنفی، ملقب به نورالدین و مکنی به ابوالحسن . رجوع به علی مصری شود.<br></font></div>'),
(186499, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جزلة، علی بن عیسی بن جزله ٔ بغدادی، مکنی به ابوالحسن و مشهور به ابن جزلة. رجوع به ابن جزلة شود.<br></font></div>'),
(186500, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جعدبن عبید هاشمی جوهری بغدادی، مکنی به ابوالحسن . رجوع به علی جوهری شود.<br></font></div>'),
(186501, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جعد جوهری، مکنی به ابوالحسن . رجوع به علی جوهری (ابن جعد...) شود.<br></font></div>'),
(186502, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جعفر، مکنی به ابوالقاسم . وی وزیر ابوکالنجار مرزبان بود. اصل او از آذربایجان و مردی دبیر و زیرک و کاردان بود. وی از زمان یوسف بن ابی الساج عهده دار دریافت خراج و مالیات آذربایجان و اران و ارمنستان بود. و اخیراً سمت وزیری دیسم را داشت . در سال <span class=\"hlight\" dir=\"rtl\">٣٣٠</span> هَ . ق . روابط میان دیسم و علی بن جعفر تیره شد و و وی به تارم گریخته به ابوکالنجار مرزبان پیوست و چون هر دو کیش باطنی داشتند بزودی با هم دوست و مهربان شدند و مرزبان وی را به وزیری برگزید. مرزبان به تحریک علی بن جعفر به تبریز حمله کرده دیسم را از آنجا براند. و در آذربایجان نیز وزارت مرزبان با ابن علی بن جعفر بود. اما بواسطه ٔ سعایت برخی از مخالفین وی نزدمرزبان، او به جان خویش بیمناک گشته دوباره به دیسم که در ارمنستان بود پیوست و در جنگی که دوباره بین مرزبان و دیسم روی داد و به شکست دیسم خاتمه یافت . علی مورد عفو قرار گرفته دیگر بار امر وزارت را یافت .(از شهریاران گمنام تألیف احمد کسروی ص <span class=\"hlight\" dir=\"rtl\">٥٩</span> و <span class=\"hlight\" dir=\"rtl\">٦٢</span>).<br></font></div>'),
(186503, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جعفر، مشهور به سیدبن طاووس و مکنی به ابوالقاسم یا ابوالحسن یا ابوموسی . رجوع به ابن طاووس وعلی بن موسی بن جعفربن محمدبن احمدبن طاووس ... شود.<br></font></div>'),
(186504, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جعفربن حسن بن عبیداﷲبن علی بن حسین بن حسن بن علی بن احمد حقینی . رجوع به علی حقینی شود.<br></font></div>'),
(186505, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن باجی، مکنی به ابوالحسن . تابعی است و ابن ابی عروبة از او نقل کند. و نیز رجوع به ابوالحسن (علی بن باجی ) شود.<br></font></div>'),
(186506, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جعفربن خضر مالکی جناجی نجفی . رجوع به علی مالکی شود.<br></font></div>'),
(186507, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جعفربن سعید سعیدی رازی حذاء، مکنی به ابوالحسن . رجوع به علی حذاء شود.<br></font></div>'),
(186508, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جعفربن عبداﷲبن حسین بن احمدبن محمدبن سعدی صقلی، مشهور به ابن قطاع و مکنی به ابوالقاسم . رجوع به ابن قطاع و علی بن جعفربن علی سعدی شود.<br></font></div>'),
(186509, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جعفربن علی سعدی صقلی، مشهور به ابن قطاع و مکنی به ابوالقاسم . در کتاب وافی، نام او بصورت علی بن جعفربن عبداﷲبن حسین بن احمدبن محمد آمده است . رجوع به ابن قطاع و نیز به کتب ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٥٢</span> و کشف الظنون ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span> و <span class=\"hlight\" dir=\"rtl\">١٠٢٣</span> و سایر صفحات و روضات الجنات خوانساری ص <span class=\"hlight\" dir=\"rtl\">٤٨٤</span> و معجم الادباء ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٩</span> و وفیات الاعیان ابن خلکان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢٧</span> و هدیةالعارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٩٥</span> و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٤</span> و المکتبة الصقلیة ص <span class=\"hlight\" dir=\"rtl\">٦٤٦</span> و البدایه ٔ ابن کثیر ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٨</span> و شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥</span> و المختصر فی اخبار البشر ابوالفداء ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٧</span> و مرآة الجنان یافعی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٢</span> و لسان المیزان ابن حجر ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٩</span> وبغیةالوعاة سیوطی ص <span class=\"hlight\" dir=\"rtl\">٣٣١</span> و مفتاح السعاده ٔ طاش کبری ج <span class=\"hlight\" dir=\"rtl\">١</span>ص <span class=\"hlight\" dir=\"rtl\">١٧٧</span> و حسن المحاضره ٔ سیوطی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٧</span> و فهرس المخطوطات المصوره ٔ سید ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> و سیرالنبلاء ذهبی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٢</span> ووافی الصفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٨</span> و فهرس المؤلفین بالظاهریة.<br></font></div>'),
(186510, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جعفربن فلاح کتامی، مکنی به ابوالحسن و مشهور به ابن فلاح .از وزرای دولت فاطمی مصر. رجوع به علی کتامی شود.<br></font></div>'),
(186511, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جعفربن محمدبن علی بن حسین بن علی بن ابی طالب مدنی . رجوع به علی مدنی شود.<br></font></div>'),
(186512, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جعفربن محمدبن علی الصادق علیهم السلام . یکی از شش فرزند ذکور امام جعفر الصادق (ع ) است . (از معجم التواریخ و القصص ص <span class=\"hlight\" dir=\"rtl\">٤٥٦</span>) (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٥</span>). وی برادر اسماعیل رئیس فرقه ٔ اسماعیله است و به شام و بلاد مغرب هجرت کرد.<br></font></div>'),
(186513, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جعفر (یا علی بن احمد) خرقانی، مکنی به ابوالحسن . از بزرگترین مشایخ صوفیه ٔ اواخر قرن چهارم و اوایل قرن پنجم هجری . رجوع به ابوالحسن علی بن جعفر و ابوالحسن خرقانی شود.<br></font></div>'),
(186514, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جعفر سعدی، مشهور به ابن قطاع و مکنی به ابوالقاسم . رجوع به ابن قطاع (ابوالقاسم علی بن ...) و علی بن عبدالرحمان سعدی شود.<br></font></div>'),
(186515, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جعفر کاتب، مکنی به ابوالحسن فارسی . وی ساکن نیشابور، و درادب و علم توانا بود. و حاکم در کتاب نیشابور از وی نقل می کند. (از معجم الادباء چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٦</span>).<br></font></div>'),
(186516, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جمال الدین بن محمدابراهیم بن شمس الدین بن مجدالمعالی قوام الدین مرعشی مدارسی . رجوع به علی مرعشی شود.<br></font></div>'),
(186517, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جمال، علی بن ابی بکربن علی بن ابی بکر عمربن احمدبن عبدالرحمان بن محمد خزرجی انصاری مکی مصری شافعی، مشهور به ابن جمال . رجوع به علی مکی (ابن ابی بکربن علی بن ...) شود.<br></font></div>'),
(186518, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن جمشید نوری مازندرانی اصفهانی شیعی . رجوع به علی نوری شود.<br></font></div>'),
(186519, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد کریدی حنفی، ملقب به شکری . رجوع به علی کریدی شود.<br></font></div>'),
(186520, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدراسبی، مکنی به ابوالحسن . رجوع به علی راسبی شود.<br></font></div>'),
(186521, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدزنبیر، مکنی به ابوالحسن . رجوع به علی زنبیر شود.<br></font></div>'),
(186522, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد سماقه ٔ عاملی مشغری . رجوع به علی سماقة شود.<br></font></div>'),
(186523, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد سهیلی اسفرایینی، مکنی به ابوالحسن . رجوع به علی اسفرایینی شود.<br></font></div>'),
(186524, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد شامی خزرجی، مکنی به ابوالحسن . رجوع به علی شامی شود.<br></font></div>'),
(186525, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد شبامی عاملی زیدی، ملقب به زین الدین . رجوع به علی عاملی شود.<br></font></div>'),
(186526, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد صرصری نجری، مکنی به ابوالحسن . رجوع به علی صرصری شود.<br></font></div>'),
(186527, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد طائی سموقی، مکنی به ابوالحسن و ملقب به بهاءالدین . رجوع به علی سموقی شود.<br></font></div>'),
(186528, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد طوسی، مکنی به ابومنصور و متخلص به اسدی . شاعر مشهور. رجوع به اسدی طوسی شود.<br></font></div>'),
(186529, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد عادلی عاملی مشهدی غروی . رجوع به علی عادلی شود.<br></font></div>'),
(186530, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد عمرانی موصلی . رجوع به علی عمرانی شود.<br></font></div>'),
(186531, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد فقیه عاملی . رجوع به علی فقیه شود.<br></font></div>'),
(186532, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدقرافی انصاری مصری شافعی . رجوع به علی قرافی شود.<br></font></div>'),
(186533, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد کاتب، ملقب به منتجب الدین بدیع اتابک جوینی . منشی معروف سلطان سنجر سلجوقی . رجوع به علی جوینی (ابن احمد...) شود.<br></font></div>'),
(186534, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمددریدی، مکنی به ابوالحسن . رجوع به علی دریدی شود.<br></font></div>'),
(186535, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد کوفی علوی، مکنی به ابوالقاسم . رجوع به علی کوفی شود.<br></font></div>'),
(186536, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد مجتبی انطاکی، مکنی به ابوالقاسم . رجوع به علی انطاکی شود.<br></font></div>'),
(186537, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد مصری شامی شافعی اشعری، مشهور به ابن صدقة. رجوع به علی مصری شود.<br></font></div>'),
(186538, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد معتضدبن موفق بن متوکل عباسی، مکنی به ابومحمد و ملقب به المکتفی باﷲ. هفدهمین خلیفه ٔ عباسی . رجوع به علی عباسی (ابن احمد معتضد...) شود.<br></font></div>'),
(186539, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد مغربی یشرطی شاذلی . رجوع به علی یشرطی شود.<br></font></div>'),
(186540, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن احمد مقری . رجوع به علی مقری شود.<br></font></div>'),
(186541, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد نجاری شعرانی شافعی . رجوع به علی شعرانی شود.<br></font></div>'),
(186542, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد مهلبی لغوی، مکنی به ابوالحسن . رجوع به علی مهلبی شود.<br></font></div>'),
(186543, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن احمد میمندی، مکنی به ابوالحسن . وزیر سلطان محمودبن سبکتکین . رجوع به علی میمندی شود.<br></font></div>'),
(186544, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد نسوی، مکنی به ابوالحسن . رجوع به علی نسوی شود.<br></font></div>'),
(186545, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن احمد هیتی . رجوع به علی هیتی شود.<br></font></div>'),
(186546, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اخشید، مکنی به ابوالحسن . سومین تن از سلاطین آل اخشید در مصر و شام بود که از <span class=\"hlight\" dir=\"rtl\">٣٤٩</span> تا <span class=\"hlight\" dir=\"rtl\">٣٥٥</span> هَ . ق . سلطنت کرد. رجوع به «آل اخشید» شود.<br></font></div>'),
(186547, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن أخضر، علی بن عبدالرحمان بن مهدی بن عمران اشبیلی، مکنی به ابوالحسن و مشهور به ابن اخضر. رجوع به علی اشبیلی (ابن عبدالرحمان بن مهدی بن ...) شود.<br></font></div>'),
(186548, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد بستجی . فقیه بود. رجوع به علی بستجی شود.<br></font></div>'),
(186549, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن موسی جزائری، مکنی به ابوالحسن . رجوع به علی جزائری شود.<br></font></div>'),
(186550, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن موسی عاملی نباطی . رجوع به علی نباطی شود.<br></font></div>'),
(186551, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن موفق بن متوکل، مکنی به ابومحمد و ملقب به المکتفی باﷲ. هفدهمین خلیفه ٔ عباسی . رجوع به علی عباسی (ابن احمد معتضدبن موفق بن ...) شود.<br></font></div>'),
(186552, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن نوبخت، مکنی به ابوالحسن و مشهور به ابن نوبخت . وی در سال <span class=\"hlight\" dir=\"rtl\">٤١٦</span> هَ . ق . در مصر درگذشت . رجوع به ابوالحسن علی ... و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٣١</span> و وفات الاعیان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥٢</span> و کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">٧٦٩</span>.<br></font></div>'),
(186553, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن احمدبن هبل تبریزی بغدادی موصلی، مکنی به ابوالحسن و ملقب به مهذب الدین . رجوع به علی تبریزی شود.<br></font></div>'),
(186554, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن یوسف بن خضر آمدی حنبلی، ملقب به زین الدین . رجوع به علی آمدی شود.<br></font></div>'),
(186555, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن یوسف وادی آشی، مکنی به ابوالحسن . رجوع به علی وادی آشی شود.<br></font></div>'),
(186556, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدبن یونس (الشیخ الامام ...)، مکنی به ابوالحسن (متوفی در سال <span class=\"hlight\" dir=\"rtl\">٣٩٩</span> هَ . ق .). او راست : الزیج الکبیر الحاکمی، در دو مجلد بزرگ . (از کشف الظنون حاجی خلیفه ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩٧١</span>).<br></font></div>'),
(186557, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد ابیوردی شیعی، مکنی به ابوالحسن و مشهور به ابن ابی قرة. متکلم قرن دهم هجری . رجوع به علی ابیوردی شود.<br></font></div>'),
(186558, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن أحمد أزرق، مشهور به ابن ازرق و ملقب به موفق الدین و نورالدین، و مکنی به ابوالحسن . رجوع به علی أزرق شود.<br></font></div>'),
(186559, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد اسدی طوسی، مکنی به ابونصر. شاعر مشهور. رجوع به اسدی (علی بن احمد...) شود.<br></font></div>'),
(186560, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد أنصاری . فقیه حنفی . رجوع به علی انصاری شود.<br></font></div>'),
(186561, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد أنطاکی، مکنی به ابوالقاسم . رجوع به علی أنطاکی شود.<br></font></div>'),
(186562, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد باسفری . شاعر. رجوع به علی باسفری شود.<br></font></div>'),
(186563, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ادریس بن علی قصاره ٔ حمیری . رجوع به علی قصارة شود.<br></font></div>'),
(186564, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد بستیفی نیشابوری . محدث است . (منتهی الارب ) (از تاج العروس ).<br></font></div>'),
(186565, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد بغدادی، مکنی به ابوالحسن و مشهور به ابن قصار. رجوع به علی قصار شود.<br></font></div>'),
(186566, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن احمد بغدادی شافعی، مکنی به ابوالحسن و مشهور به ابن مرزبان . رجوع به علی بغدادی شود.<br></font></div>'),
(186567, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد بلخی، مکنی به ابوالقاسم . ازعلمای نجوم . رجوع به علی بلخی (ابن احمد...) شود.<br></font></div>'),
(186568, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد تستری . رجوع به علی تستری (ابن احمد...) شود.<br></font></div>'),
(186569, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد جرجانی، مکنی به ابوالقاسم . رجوع به علی جرجانی شود.<br></font></div>'),
(186570, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد جرجرایی، مکنی به ابوالقاسم و ملقب به نجیب الدولة. رجوع به علی جرجرایی شود.<br></font></div>'),
(186571, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمدجشوبی، مکنی به ابوالحسن . رجوع به علی جشوبی شود.<br></font></div>'),
(186572, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد حریشی فاسی مالکی، مکنی به ابوالحسن . رجوع به علی حریشی شود.<br></font></div>'),
(186573, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد حسینی عاملی، ملقب به تاج الدین . رجوع به علی عاملی شود.<br></font></div>'),
(186574, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد خرد یمانی . فقیه قرن دهم هجری . رجوع به علی خرد شود.<br></font></div>'),
(186575, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد خرقانی (یا علی بن جعفر)، مکنی به ابوالحسن . از بزرگترین مشایخ صوفیه ٔ اواخر قرن چهارم و اوایل قرن پنجم هجری . رجوع به ابوالحسن علی بن جعفر... و ابوالحسن خرقانی شود.<br></font></div>'),
(186576, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن احمد خیالی بن ابراهیم گلشنی، مشهور به صفوتی . رجوع به علی صفوتی شود.<br></font></div>'),
(186577, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن امیر مؤیدارلات . وی در هنگام لشکرکشی دوم امیر تیمور گورکانی به خراسان، همراه او بود. و امیر تیمور درین جنگ قلعه ٔ قهقهه را که در برابر دروازه ٔ کلات بود تعمیر کرد و حاجی خواجه را کوتوال آن حصار ساخت و امیرزاده ٔ علی بن امیر مؤید ارلات را با شیخ علی بهادر در آن قلعه گذاشت تا راه ها را مضبوط کنند و نگذارند کسی به کلات آمد و رفت کند. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣٣</span>).<br></font></div>'),
(186578, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن أعلم، علی بن حسن علوی بغدادی، مشهور به ابن أعلم و مکنی به ابوالقاسم . ریاضی دان و منجم مشهور قرن چهارم هجری . رجوع به ابن اعلم و علوی (علی بن حسن ...) و علی بن حسن ... شود.<br></font></div>'),
(186579, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن أعمی، علی بن محمدبن مبارک، ملقب به کمال الدین و مشهور به ابن أعمی . شاعر مصری . رجوع به علی بن محمدبن مبارک شود.<br></font></div>'),
(186580, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن افراسیاب جلابی (کیا...). رجوع به علی جلابی شود.<br></font></div>'),
(186581, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن أفلج بن محمد عبسی، مکنی به ابوالقاسم . رجوع به عبسی شود.<br></font></div>'),
(186582, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن أقبرس، علی بن محمدبن أقبرس قاهری شافعی، مشهور به ابن أقبرس و ملقب به علاءالدین . رجوع به علی قاهری (ابن محمدبن أقبرس ...) شود.<br></font></div>'),
(186583, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن التمش، ملقب به جلال الدین . وی حاکم قنوج بود و در ماه شعبان سال <span class=\"hlight\" dir=\"rtl\">٦٤٥</span> هَ . ق .هنگامی که برادرش سلطان ناصرالدین محمودبن شمس الدین التمش به فتح ولایت میان دوآب مبادرت کرد همراه وی بود و پس از پایان جنگ و جدال، ناصرالدین محمود ایالت کهتل را به برادر خود جلال الدین علی تفویض کرد، ولی جلال الدین علی بر اثر برخی توهمات از راه کوهستان بجانب لاهور فرار کرد. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٢٤</span>).<br></font></div>'),
(186584, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن الیاس (امیر...). در سال <span class=\"hlight\" dir=\"rtl\">٣٢٢</span> هَ . ق . که معزالدوله به اشاره ٔ برادر بزرگتر خود عمادالدوله به قصد تسخیر کرمان روان شد، این علی بن الیاس (در روضةالصفا نام او محمد ذکر شده است ) حاکم کرمان بود و در آنجا متحصن شد و روزها لباس رزم میپوشید و به جنگ معزالدوله میرفت اما شبها وسایل پذیرائی و خوراک برای معزالدوله می فرستاد. و چون معزالدوله علت این تناقض را از وی پرسید، جواب گفت که روزها مطابق وظیفه ٔ خود با تو که دشمن ولایت من هستی میجنگم ولی شبهاوظیفه ٔ دیگر خود را نسبت به تو که در ولایت ما مهمان هستی انجام میدهم . معزالدوله ازین جواب منفعل گشت وموقتاً از تسخیر کرمان صرف نظر کرد، تا اینکه پس از علی پسرش الیسع به حکومت رسید و معزالدوله توانست کرمان را تصرف کند. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢٥</span>).<br></font></div>'),
(186585, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن الیاس آغاجی بخاری، مکنی به ابوالحسن . رجوع به علی آغاجی شود.<br></font></div>'),
(186586, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اماجور، علی بن ابی قاسم عبداﷲبن اماجور منجم، مکنی به ابوالحسن . رجوع به ابوالحسن (علی بن ابی القاسم ...) و به ابن اماجور شود.<br></font></div>'),
(186587, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن امراﷲحنائی . رجوع به علی حناوی زاده (ابن محمد...) شود.<br></font></div>'),
(186588, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ام ولد، علی بن عبدالعزیز، بن حسام بن حامد رومی، مشهور به ابن ام ولد و ولدزاده ٔ رومی . رجوع به علی رومی (ابن عبدالعزیزبن حسام بن ...) شود.<br></font></div>'),
(186589, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن امیر ارغونشاه جونی قربانی (علی بیک ...). پدر او امیر ارغونشاه جونی قربانی حاکم نیشابور بود، و خود علی بیک بر حدود مرو و ماخان مستوفی بود و بعداً حاکم ابیورد و حدود آن شد. در سال <span class=\"hlight\" dir=\"rtl\">٧٨٤</span> هَ . ق . به امیر تیمور گورکانی خبر رسید که این علی بیک جونی قربانی با امیر ولی متحد شده قصد سبزوار را دارند، لذا امیر تیمور با سپاهی به قصد او رفت و در حوالی قلعه ٔ کلات، علی بیک شکست خورده تسلیم شد و مورد عفو امیر تیمور قرار گرفت . اما بار دیگر پس از بازگشت به قلعه ٔ خود آغاز مخالفت کرد و امیر تیمور عده ای را مأمور محاصره ٔ آن قلعه ساخت و خود بجانب مازندران رفت . و پس از مدتی علی بیک دوباره تسلیم شد و مورد عفو امیر تیمور قرار گرفت . ولی چون بار دیگر با برخی از امیران آغاز شورش کرد به دستور امیر تیمور او و ملک غیاث الدین پیرعلی و برادرش ملک محمد و جمعی دیگر به یاسا رسیدند. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">٤٣١</span> - <span class=\"hlight\" dir=\"rtl\">٤٣٤</span>).<br></font></div>'),
(186590, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن امیر علی قوشچی (امیر شیخ ...). وی از امرای سلطان ابوسعید بود. و ابوسعید در سال <span class=\"hlight\" dir=\"rtl\">٧٣٠</span> هَ. ق . وی را بهمراهی خواجه علاءالدین محمد، به خراستان فرستاد و حکومت خراسان را به دست امیر شیخ علی سپرد تا خرابی هائی را که بعد از قتل امیر چوپان در آن سرزمین بروز کرده بود ترمیم نماید. پس از مدتی امیر علی جعفر که برای مخالفت با محمدخان در اوجان، به خراسان رفته بود با جمعی از امرا و از جمله این امیر شیخ علی ملاقات کرده و آنان را با خود همراه ساخت . و این عده در شعبان سال <span class=\"hlight\" dir=\"rtl\">٧٣٧</span> هَ . ق . سلطانیه را تصرف کردند. ولی امیر شیخ علی بعداً به دست طغاتیمورخان به قتل رسید. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٦</span>). (از تاریخ مفصل ایران، مغول تألیف عباس اقبال ص <span class=\"hlight\" dir=\"rtl\">٣٤٣</span> و <span class=\"hlight\" dir=\"rtl\">٣٤٤</span>).<br></font></div>'),
(186591, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن امیر محمد برندق برلاس (میرزا علی بیک ...). از شاهزادگان تیموری . رجوع به علی بیک بن امیر محمد... شود.<br></font></div>'),
(186592, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن أضحی، علی بن عمربن محمدبن مشرف بن احمد همدانی، مکنی به ابوالحسن و مشهور به ابن اضحی . رجوع به علی همدانی (ابن عمربن محمدبن ...) شود.<br></font></div>'),
(186593, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن أمین جزائری . رجوع به علی جزائری شود.<br></font></div>'),
(186594, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن امیةبن خلف . از کفار قریش بود که در غزوه ٔ بدر، عبدالرحمان بن عوف وی و پدرش امیة را اسیر ساخت و بلال حبشی که در مکه از آنها متضرر شده بود انصار را تشویق به قتل آنان کرد و بالاخره هر دو با شمشیر حبیب بن یصاف انصاری و حباب بن منذر کشته شدند. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٠</span>) (از امتاع الاسماع مقریزی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٩٠</span>).<br></font></div>'),
(186595, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن أنجب بن عثمان بن عبداﷲبن عبدالرحیم بغدادی خازن شافعی، مشهور به ابن ساعی و مکنی به ابوطالب و ملقب به تاج الدین (<span class=\"hlight\" dir=\"rtl\">٥٩٣</span> - <span class=\"hlight\" dir=\"rtl\">٦٧٤</span> هَ . ق .). او را علاوه بر کتبی که در «ابن ساعی » نقل شده است کتابهای زیر میباشد: <span class=\"hlight\" dir=\"rtl\">١</span>- الاحادیث الثمانیة العالیة. <span class=\"hlight\" dir=\"rtl\">٢</span>- اخبارالادباء. <span class=\"hlight\" dir=\"rtl\">٣</span>- اخبارالخلفاء. <span class=\"hlight\" dir=\"rtl\">٤</span>- الایناس بمناقب عباس . <span class=\"hlight\" dir=\"rtl\">٥</span>- الحث علی طلب الوالد. <span class=\"hlight\" dir=\"rtl\">٦</span>- ذیل بر کامل التواریخ ابن اثیر، در پنج مجلد. <span class=\"hlight\" dir=\"rtl\">٧</span>- ذیل بر مختصر طبقات الشافعیه ٔ ابراهیم بن علی شیرازی، در هفت مجلد. <span class=\"hlight\" dir=\"rtl\">٨</span>- سیرة المستنصر. <span class=\"hlight\" dir=\"rtl\">٩</span>- شرح بر مقامات حریری، در بیست وپنج مجلد. <span class=\"hlight\" dir=\"rtl\">١٠</span>- غررالمحاضرة و دررالمکاثرة، در تاریخ . <span class=\"hlight\" dir=\"rtl\">١١</span>- غزل الطرف، در دو جلد. <span class=\"hlight\" dir=\"rtl\">١٢</span>- مشیخة علی بن انجب . <span class=\"hlight\" dir=\"rtl\">١٣</span>- المعلم الاتابکی . <span class=\"hlight\" dir=\"rtl\">١٤</span>- مفاتیح الجنان و مصابیح الجنان . <span class=\"hlight\" dir=\"rtl\">١٥</span>- مناقب الخلفاء الاربعة، در سه جلد. <span class=\"hlight\" dir=\"rtl\">١٦</span>- نزهة الابصار. <span class=\"hlight\" dir=\"rtl\">١٧</span>- نساء الخلفاء من الاحرار و الاماء. رجوع به ابن ساعی و به کتب زیرشود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٤١</span> کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">١٤</span> و <span class=\"hlight\" dir=\"rtl\">٢٥</span> و سایر صفحات هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧١٢</span> و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢</span> و أعیان الشیعة ج <span class=\"hlight\" dir=\"rtl\">٤١</span> ص <span class=\"hlight\" dir=\"rtl\">٩٨</span> و تاریخ علماء بغدادابن رافع سلامی ص <span class=\"hlight\" dir=\"rtl\">١٣٧</span> و البدایه ٔ ابن کثیر ج <span class=\"hlight\" dir=\"rtl\">١٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٠</span> والحوادث الجامعه ٔ ابن فوطی ص <span class=\"hlight\" dir=\"rtl\">٣٨٦</span> و شذرات الذهب ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤٣</span> و تذکرة الحفاظ ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> و التعریف بالمؤرخین عزاوی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٩٢</span> و المخطوطات التاریخیة ص <span class=\"hlight\" dir=\"rtl\">٥٢</span> و حمیدیة کتبخانه ص <span class=\"hlight\" dir=\"rtl\">٦٣</span> و التذکره ٔ طاهر جزائری شماره ٔ <span class=\"hlight\" dir=\"rtl\">١٢٧</span> و فهرس المؤلفین بالظاهریة و طبقات الشافعیه ٔ اسنوی ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span> و الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢</span> و حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١١٧</span>.<br></font></div>'),
(186596, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن انجب ابی المکارم المفضل بن ابی الحسن علی بن ابی الغیث مفرج بن حاتم بن حسن بن جعفربن ابراهیم بن حسن لخمی مقدسی اسکندرانی مالکی، مکنی به ابوالحسن . رجوع به علی مقدسی شود.<br></font></div>'),
(186597, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اندلسی، علی بن حمدون بن سماک بن مسعودبن منصور جذامی، مشهور به ابن اندلسی . رجوع به علی جذامی (ابن حمدون بن سماک بن ...) شود.<br></font></div>'),
(186598, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اوچ قرابهادر (شیخ ...). وی از امیرزادگان بود، و در ذی حجه ٔ سال <span class=\"hlight\" dir=\"rtl\">٨٠٨</span> هَ. ق . امیر سیدخواجه، با او و برادرانش و تیمور ملک دولدای هم پیمان شده میخواستند علیه میرزا شاهرخ قیام کنند، ولی میرزا شاهرخ بموقع ازین نقشه آگاه شده آنها را تنبیه کرد. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٥٥٩</span>).<br></font></div>'),
(186599, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اویس ایلکانی (شاهزاده شیخ ...). رجوع به علی بن سلطان اویس ایلکانی شود.<br></font></div>'),
(186600, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اَیدُغدی . فقیه حنبلی، اهل دمشق و ترکی الاصل . او را فرهنگی است در شرح حال شیوخ خود. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢</span> از الاعلام زرکلی ).<br></font></div>'),
(186601, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن ایدمربن علی جلدکی، ملقب به عزیزالدین . رجوع به علی جلدکی (ابن محمدبن ایدمر...) شود.<br></font></div>'),
(186602, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ایرنجین (امیر شیخ ...). پدر او امیر ایرنجین، پدر یکی از زنان سلطان ابوسعید بهادرخان بود، و چون با ابوسعید از در مخالفت درآمد، در جنگی که در جمادی الاولای سال <span class=\"hlight\" dir=\"rtl\">٧١٩</span> هَ . ق . در حدود آذربایجان در ساحل سفیدرود بین آن دو روی داد، فرزند امیر ایرنجین یعنی امیر شیخ علی، توسط سپاهیان سلطان ابوسعید کشته شد. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٦</span>) (از تاریخ مفصل ایران، مغول تألیف عباس اقبال ص <span class=\"hlight\" dir=\"rtl\">٣٣٣</span>).<br></font></div>'),
(186603, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ایل ارسلان قریب، معروف به حاجب بزرگ . از بزرگان امرای سلطان محمود غزنوی . رجوع به حاجب (علی بن قریب ...) شود.<br></font></div>'),
(186604, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ایوب قدسی شافعی، ملقب به علاءالدین . رجوع به علی قدسی شود.<br></font></div>'),
(186605, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن بابویه، علی بن حسین بن موسی بن بابویه قمی، مکنی به ابوالحسن و مشهور به ابن بابویه . رجوع به ابن بابویه و علی بن حسین بن ... شود.<br></font></div>'),
(186606, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسرافیل قنالی زاده (مولی ...). رجوع به علی قنالی شود.<br></font></div>'),
(186607, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن ادریس مأمون بن یعقوب منصور، مکنی به ابوالحسن سعید و ملقب به المعتضد باﷲ. از خلفای موحدین (بنی عبدالمؤمن ) در مراکش . رجوع به علی مؤمنی (ابن ادریس ...) شود.<br></font></div>'),
(186608, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن أدمی، علی بن محمدبن محمد، مکنی به ابوالحسن و مشهور به ابن أدمی و ملقب به صدرالدین . رجوع به علی بن محمدبن محمد شود.<br></font></div>'),
(186609, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسباطبن سالم کوفی شیعی، مکنی به ابوالحسن . رجوع به علی کوفی شود.<br></font></div>'),
(186610, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن استجی، علی بن عبداﷲبن علی بن محمدبن یوسف بن سلیمان بن عمر ازدی، مشهور به ابن استجی . رجوع به علی ازدی (ابن عبداﷲبن علی بن ...) شود.<br></font></div>'),
(186611, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسحاق، معروف به ابن سلار و ملقب به الملک العادل سیف الدین . وزیر ظافر عبیدی صاحب مصر. رجوع به ابن سلار شود.<br></font></div>'),
(186612, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسحاق بن ابراهیم حنظلی سمرقندی . رجوع به علی سمرقندی شود.<br></font></div>'),
(186613, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسحاق بن ابی سهل بن نوبخت نوبختی، سرسلسله ٔ یک شعبه از خاندان نوبختی بود. رجوع به علی نوبختی (ابن اسحاق بن ...) شود.<br></font></div>'),
(186614, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسحاق بن خلف زاهی بغدادی، مکنی به ابوالقاسم . رجوع به علی زاهی شود.<br></font></div>'),
(186615, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسحاق بن محمدبن غانیة، مشهور به ابن غانیة. وی امیر جزایر بالیار و نواحی آن در شرق اندلس بود. که در سال <span class=\"hlight\" dir=\"rtl\">٥٧٩</span> هَ . ق . پس ازدرگذشت پدرش حکومت را به دست گرفت و از مشغولیت بنی عبدالمؤمن (موحدین ) در اندلس استفاده کرد و در سال <span class=\"hlight\" dir=\"rtl\">٥٨٦</span> بر ساحل بجایة در الجزائر دست یافت و برخی از مخالفان موحدین به وی پیوستند و او را لقب «امیرالمسلمین » دادند. سپس در جنگی که بین او و یعقوب بن یوسف مؤمنی درگرفت وی شکست خورد و فرار کرد و در سال <span class=\"hlight\" dir=\"rtl\">٥٨٥</span> در خیمه ٔ یک پیرزال عرب درگذشت . (از الاعلام زرکلی چ <span class=\"hlight\" dir=\"rtl\">٢</span> ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨</span> از المعجب ص <span class=\"hlight\" dir=\"rtl\">٢٧٠</span> و وصفة جزیرة الاندلس ص <span class=\"hlight\" dir=\"rtl\">١٨٩</span>).<br></font></div>'),
(186616, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسحاق أبیوردی خاورانی، ملقب به اوحدالدین . رجوع به علی أبیوردی شود.<br></font></div>'),
(186617, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن اسحاق برمکی . رجوع به علی برمکی شود.<br></font></div>'),
(186618, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسحاق طوسی . وی پدر خواجه نظام الملک بود. رجوع به علی طوسی شود.<br></font></div>'),
(186619, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسحاق مروزی، مکنی به ابوالحسن . تابعی بود. نیز رجوع به ابوالحسن علی ... شود.<br></font></div>'),
(186620, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسد، مکنی به ابوالمعالی . امیربدخشان و معاصر ناصرخسرو بود. ابیات ذیل از اوست :<br>فخر دانا به دانش و ادب است <br>فخر نادان به جامه و سلب است <br>ادب و دانش از ادیب اکنون <br>خوار، ورچند مزد باادب است <br>ناکسان پیشگاه و کامروا<br>فاضلان دورمانده، وین عجب است <br>سبب این همه نداند کس <br>جز همان کو مسبب سبب است <br>علی بن اسد چنین گوید<br>کاین جهان سربسر غم وتعب است .<br><font color=\"Red\">(ازیادداشت مرحوم دهخدا).</font><br></font></div>'),
(186621, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن حسام الدوله . از سلاطین آل باوند. رجوع به علاءالدوله ٔ باوندی شود.<br></font></div>'),
(186622, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسماعیل بن ابراهیم بن جباره ٔکندی محلی سخاوی مالکی، ملقب به شرف الدین و مکنی به ابوالحسن و مشهور به ابن جبارة (<span class=\"hlight\" dir=\"rtl\">٥٥٤</span> - <span class=\"hlight\" dir=\"rtl\">٦٣٢</span> هَ . ق .). وی ادیب و نحوی و شاعر بود. و در قاهره درگذشت . اوراست : نظم الدر فی نقدالشعر. و نیز او را دیوان شعری است . (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤</span> از کشف الظنون ص <span class=\"hlight\" dir=\"rtl\">١٩٦١</span> و هدیة العارفین ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٠٧</span> و الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦</span> و بغیة الوعاة سیوطی ص <span class=\"hlight\" dir=\"rtl\">٣٢٩</span> و ایضاح المکنون ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠٧</span>).<br></font></div>'),
(186623, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسماعیل بن ابراهیم بن محمدبن عربشاه اسفرایینی شافعی مکی، مشهور به عصامی و حفید. رجوع به علی عصامی شود.<br></font></div>'),
(186624, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسماعیل بن اسحاق بن سالم بن اسماعیل بن عبداﷲبن موسی بن بلال بن عامربن ابی موسی عبداﷲبن قیس اشعری یمانی بصری، مکنی به ابوالحسن . پیشوای اشعریان . رجوع به ابوالحسن اشعری و علی اشعری شود.<br></font></div>'),
(186625, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسماعیل بن خلیل خراسانی (علی اکبر نواب ...). رجوع به علی اکبر خراسانی شود.<br></font></div>'),
(186626, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسماعیل بن شریف حسنی، مکنی به ابوالحسن و ملقب به أعرج . از پادشاهان دولت سجلماسة در مغرب . رجوع به علی سجلماسی شود.<br></font></div>'),
(186627, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسماعیل بن شعیب بن میثم بن یحیی تمار اسدی کوفی بصری میثمی، مکنی به ابوالحسن . رجوع به میثمی شود.<br></font></div>'),
(186628, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسماعیل بن علی بن حسن بن عطیه ٔ ابیاری، مکنی به ابوالحسن و ملقب به شمس الدین . رجوع به علی ابیاری شود.<br></font></div>'),
(186629, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسماعیل بن قاسم بن محمد حسنی، مکنی به ابوالحسن . رجوع به علی حسنی شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(186630, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسماعیل بن موسی بن علی بن حسن بن محمد دمشقی شافعی، مشهور به ابن عمادالدین و ابن وِس ّ، و ملقب به علاءالدین . متولد در سال <span class=\"hlight\" dir=\"rtl\">٩١٧</span> هَ . ق . وی در <span class=\"hlight\" dir=\"rtl\">٩٧١</span> هَ . ق . در دمشق درگذشت . او را حواشیی بر شرح ابن مصنف بر ألفیة میباشد. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧</span> از شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦٣</span>).<br></font></div>'),
(186631, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسماعیل بن یوسف قونوی تبریزی شافعی، ملقب به علأالدین و مکنی به ابوالحسن . رجوع به علی قونوی شود.<br></font></div>'),
(186632, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسماعیل اندلسی مرسی ضریر، مشهور به ابن سیدة و مکنی به ابوالحسن . رجوع به ابن سیدة و علی بن سیدة شود.<br></font></div>'),
(186633, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اسماعیل بغدادی، ملقب به علم الدین و مشهور به رکاب سالار. رجوع به علم الدین جوهری شود.<br></font></div>'),
(186634, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن اصیل بن مسعودبن محمودبن محمد حنفی برمائی، مکنی به ابومحمد. رجوع به علی برمائی شود.<br></font></div>'),
(186635, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن محمودبن ابی العزبن احمدبن اسحاق بن ابراهیم کازرونی بغدادی شافعی، ملقّب به ظهیرالدین . رجوع به علی کازرونی شود.<br></font></div>'),
(186636, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن محمدبن علی بن سکون حلی، مکنّی به ابوالحسن و مشهور به ابن السکون . رجوع به علی حلی شود.<br></font></div>'),
(186637, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن محمدبن علی قرشی بسطی اندلسی مالکی، مشهور به قلصادی و ملقّب به نورالدین و مکنّی به ابوالحسن . رجوع به علی قلصادی شود.<br></font></div>'),
(186638, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن محمدبن محمدبن خلف بن جبریل منوفی مصری شاذلی، ملقّب به نورالدین و مکنّی به ابوالحسن . رجوع به علی منوفی شود.<br></font></div>'),
(186639, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن محمدبن محمدبن محمدبن وضاح بن محمدبن وضاح شهرابانی، مکنّی به ابوالحسن و ملقّب به کمال الدین و مشهور به ابن وضاح . رجوع به علی شهرابانی شود.<br></font></div>'),
(186640, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن نصر اسفرایینی مکی، مکنّی به ابوالحسن . رجوع به علی اسفرایینی شود.<br></font></div>'),
(186641, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن محمدبن نضر. ادیب و نحوی و شاعر بود که پیش از سال <span class=\"hlight\" dir=\"rtl\">٧٤٨</span> هَ . ق . میزیست . او را دیوان شعری است . (از معجم المؤلفین بنقل از الطالع السعید ادفوی ص <span class=\"hlight\" dir=\"rtl\">٢٢٠</span>).<br></font></div>'),
(186642, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن محمدبن وفا قرشی انصاری سکندری شاذلی مالکی، مشهور به ابن وفا و مکنّی به ابوالحسن . رجوع به علی قرشی شود.<br></font></div>'),
(186643, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن محمدبن هبةاﷲبن محمدبن علی بن مطلب، ملقّب به مجدالدین و تاج الدین و مکنّی به ابوالمکارم . وی ادیب و نویسنده و نحوی و لغوی بود که به شام سفر کرد و مقاماتی را نیز عهده دار شد و به قاهره نیز سفری کرد و در سال <span class=\"hlight\" dir=\"rtl\">٥٦١</span> هَ . ق . درگذشت . او راست : <span class=\"hlight\" dir=\"rtl\">١</span> - مختصر اصلاح المنطق ابن سکیت . <span class=\"hlight\" dir=\"rtl\">٢</span> - مختصر غریبین . (از معجم المؤلفین بنقل از الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٨</span>، بغیةالوعاة سیوطی ص <span class=\"hlight\" dir=\"rtl\">٣٥٣</span>، کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">١٠٨</span> و هدیةالعارفین بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٩٩</span>).<br></font></div>'),
(186644, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن محمد ترکه ٔ اصفهانی، ملقّب به صائن الدین . رجوع به صائن اصفهانی شود.<br></font></div>'),
(186645, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن نصراﷲ همدانی . رجوع به علی همدانی شود.<br></font></div>'),
(186646, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن نصر نصرانی، مشهور به ابن طبیب و مکنّی به ابوالحسن . وی ادیب و نویسنده بود در سال <span class=\"hlight\" dir=\"rtl\">٣٧٧</span> هَ . ق . درگذشت . او راست : <span class=\"hlight\" dir=\"rtl\">١</span> - اصلاح الاخلاق، که در حدود یکهزاروپانصد ورق است . <span class=\"hlight\" dir=\"rtl\">٢</span> - البراعة. <span class=\"hlight\" dir=\"rtl\">٣</span> - صحبةالسلطان، که بیش از یکهزار ورق است . (از معجم المؤلفین بنقل از معجم الادباء یاقوت ج <span class=\"hlight\" dir=\"rtl\">١٥</span> ص <span class=\"hlight\" dir=\"rtl\">٩٦</span>. الفهرست ابن الندیم ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٣١</span>. هدیةالعارفین بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨٢</span>).<br></font></div>'),
(186647, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن محمدبن محمدتقی بن محمدرضابن مهدی بحرالعلوم طباطبائی نجفی . رجوع به علی طباطبائی شود.<br></font></div>'),
(186648, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن محمد علی آبادی ملقّب به بدرالدین . رجوع به علی علی آبادی شود.<br></font></div>'),
(186649, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن محمدبن علی بن احمدبن حجر عسقلانی مصری کنانی شافعی مشهور به ابن حجر. رجوع به علی عسقلانی شود.<br></font></div>'),
(186650, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن مرادبن علی بخاری الاصل دمشقی حنفی نقشبندی مشهور به مرادی . رجوع به علی شود.<br></font></div>'),
(186651, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن مزین، مکنّی به ابوالحسین . از عرفای اواخر قرن سوم و اوایل قرن چهارم هجری بود. صاحب نفحات الانس بنقل از کتاب خواجه عبداﷲ انصاری گوید که : «ابوالحسین مزین » دو تن بوده اند یکی کبیر ودیگری صغیر و گویا با هم پسرخاله بودند.مولد و منشاء ابوالحسین مزین کبیر در بغداد بود و با جنید و سهل صحبت داشت، اما ابوالحسین مزین صغیر درمکه مجاور بود. وفات علی بن محمد کبیر در سال <span class=\"hlight\" dir=\"rtl\">٣٢٧</span> یا<span class=\"hlight\" dir=\"rtl\">٣٢٨</span> هَ . ق . اتفاق افتاد و در بغداد دفن گردید. اماعلی بن محمد صغیر در مکه درگذشت و در همانجا دفن شد.در نامه ٔ دانشوران بسیاری از سخنان و کرامات این دوذکر شده است . رجوع به نامه ٔ دانشوران ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٩٠</span> شود.<br></font></div>'),
(186652, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن نصیرالدین محمودبن مظفر خوارزمی، ملقّب به شمس الدین . پدر او نصیرالدین محمود سمت وزارت و نیز اشراف مطبخ و اسطبل سلطان سنجر را داشت . و بواسطه ٔ بی کفایتی از وزارت کنار رفت و منصب اشراف را به پسرش شمس الدین علی واگذاشت . و پس از مدتی مقرب الدین جوهر خادم، شمس الدین علی را نزد سلطان سنجر متهم به داشتن روابط با برخی از حرمسرایان سلطان ساخت لذا با پدرش به زندان افکندند و در همان زندان درگذشتند. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥١٥</span>) (دستور الوزراء خوندمیر ص <span class=\"hlight\" dir=\"rtl\">١٩٩</span> و <span class=\"hlight\" dir=\"rtl\">٢٠٣</span>).<br></font></div>'),
(186653, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن نضر، مکنّی به ابوالحسن و مشهور به ادیب . وی قاضی از اهالی صعید اعلی بود. او را در علوم اوائل و ادب مقامی ارجمند بود و ابوالصلت در رساله ٔ خود وی را بسیار می ستاید. (از تاریخ الحکماء قفطی ص <span class=\"hlight\" dir=\"rtl\">٢٣٧</span>).<br></font></div>'),
(186654, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن مقلة، مکنّی به ابوالحسین . وزیر المتقی عباسی . رجوع به علی بن ابی علی محمدبن مقله شود.<br></font></div>'),
(186655, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن مکی بن عیسی بن حسن بن عیسی شامی عاملی جبلی، ملقب به نجیب الدین و مشهور به ابن مکی . رجوع به علی شامی شود.<br></font></div>'),
(186656, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن مکی عاملی جزینی، ملقّب به ضیاءالدین و حسام الدین و رضی الدین و مکنّی به ابوالقاسم . رجوع به علی جزینی شود.<br></font></div>'),
(186657, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن منتصر طرابلسی، مکنّی به ابوالحسن و مشهور به ابن منتصر. رجوع به علی طرابلسی شود.<br></font></div>'),
(186658, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن منصوربن ابی القاسم بن مختاربن ابی بکربن علی جذامی اسکندری، مشهور به ابن منیر و مکنّی به ابوالحسن و ملقّب به زین الدین . رجوع به علی اسکندری شود.<br></font></div>'),
(186659, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن موسی بن حسن بن فرات نهروانی، مکنّی به ابوالحسن و مشهور به ابن فرات . وزیر المقتدر باﷲ عباسی . رجوع به ابن فرات (ابوالحسن علی ...) و مآخذ ذیل شود: دستورالوزراء خوندمیر ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>. الاعلام زرکلی چ <span class=\"hlight\" dir=\"rtl\">٢</span> ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٤١</span>. الوزراء صابی . سیرالنبلاء عریب ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>. ابن خلکان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٢</span>.<br></font></div>'),
(186660, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن موسی بن سعیدبن مهدی انباری مکنّی به ابوالقاسم و ملقب به حُسنُس و مشهور به ابن صفدان . رجوع به علی حسنس شود.<br></font></div>'),
(186661, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن مهدی طبری اشعری، مکنّی به ابوالحسن . رجوع به علی طبری شود.<br></font></div>'),
(186662, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن نصر، مکنّی به ابوالحسن . وی از کاتبان واسط بود و در سال <span class=\"hlight\" dir=\"rtl\">٤٣٧</span> هَ ق . درگذشت . او را رسائلی است . (از معجم المؤلفین بنقل از کامل التواریخ ابن اثیر ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٣</span>).<br></font></div>'),
(186663, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عیسی دمشقی محلی نمراوی شافعی، مشهور به قطبی و ملقب به علاءالدین . رجوع به علی قطبی شود.<br></font></div>'),
(186664, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی صلیحی، مکنّی به ابوالحسن . رجوع به علی صلیحی شود.<br></font></div>'),
(186665, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی کاشی مشهور به حلی و ملقّب به نصیرالدین، رجوع به علی کاشی (ابن محمد...) شود.<br></font></div>'),
(186666, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی کیاهراسی طبرستانی شافعی، ملقّب به عمادالدین و مکنّی به ابوالحسن . رجوع به علی کیاهراسی شود.<br></font></div>'),
(186667, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی مغربی، مشهور به سقاط و مکنّی به ابوالحسن . رجوع به علی سقاط شود.<br></font></div>'),
(186668, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی مقری فیومی . رجوع به علی فیومی شود.<br></font></div>'),
(186669, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی منذری . رجوع به علی منذری شود.<br></font></div>'),
(186670, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی نحوی استرآبادی فصیحی، مکنّی به ابوالحسن . رجوع به ابوالحسن (علی بن ابی زید محمدبن ...) شود.<br></font></div>'),
(186671, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی نیریزی، ملقب به ارشدالدین و مکنّی به ابوالحسن . رجوع به علی نیریزی شود.<br></font></div>'),
(186672, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی واسطی رفاعی، مکنّی به ابوالحسن . رجوع به علی واسطی شود.<br></font></div>'),
(186673, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عمر تحیوی، ملقب به موفق الدین و مشهور به صاحب . رجوع به علی تحیوی شود.<br></font></div>'),
(186674, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عمید، مکنّی به ابوالفتح . رجوع به ابن عمید (ابوالفتح ...) و حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢٥</span> شود.<br></font></div>'),
(186675, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عمیر نحوی کنانی، مکنّی به ابوالحسن . رجوع به علی کنانی (ابن محمدبن ...) شود.<br></font></div>'),
(186676, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن محمدبن عیسی بن محمد اشمونی الاصل قاهری شافعی، ملقّب به نورالدین . رجوع به علی اشمونی شود.<br></font></div>'),
(186677, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن نصربن منصوربن بسام عبرتائی بغدادی، مکنّی به ابوالحسن و مشهور به ابن بسام . وی شاعر بود و در سال <span class=\"hlight\" dir=\"rtl\">٢٣٠</span> هَ . ق . متولد شد و در <span class=\"hlight\" dir=\"rtl\">٣٠٢</span>هَ . ق . درگذشت . رجوع به ابن بسام و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٦</span>. الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٢</span>. سیرالنبلاء ذهبی ج <span class=\"hlight\" dir=\"rtl\">٩</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٨</span>. الفهرست ابن الندیم ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٠</span>. معجم الادباء یاقوت ج <span class=\"hlight\" dir=\"rtl\">١٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٩</span>. فوات الوفیات ابن شاکر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٣</span>. کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">٢٥</span> و سایر صفحات . ایضاح المکنون بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٩</span>. اعیان الشیعه ٔ عاملی ج <span class=\"hlight\" dir=\"rtl\">٤٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤</span>.<br></font></div>'),
(186678, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن محمدبن غالب عامری، مشهور به مجدالعرب و مکنّی به ابوفراس . رجوع به علی مجدالعرب شود.<br></font></div>'),
(186679, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن فرحون قیسی، مکنّی به ابوالحسن و مشهور به ابن فرحون . رجوع به علی قیسی شود.<br></font></div>'),
(186680, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن فلاح، مشهور به ابن مشعشع. وی از نوادگان امام موسی کاظم (ع ) و از امرای دولت مشعشعی در اهواز و حویزه بود. ابن مشعشع با پدر خود در بسیاری از جنگهای او با ترکمانان که به عراق مسلط بودند، شرکت داشت و در اواخر عمر پدر، زمام امور را به دست گرفت و ابتدا ادعا کرد که روح امام علی (ع ) در او حلول کرده است، سپس ادعای الوهیت کرد و بر اماکن مقدس عراق حمله برد و آنها را غارت کرد و در سال <span class=\"hlight\" dir=\"rtl\">٨٥٧</span> هَ . ق . متعرض حجاج شد و به اموال آنان دستبرد زد و به الحاد و ستم خود ادامه داد. سرانجام در سال <span class=\"hlight\" dir=\"rtl\">٨٦٣</span> هَ . ق . به تیر یکی از ترکان در کوه کیلویه واقع در بهبهان به قتل رسید در حالیکه پدرش هنوز در قید حیات بود. (از الاعلام زرکلی بنقل از تاریخ العراق ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٩</span> و الضوءاللامع ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٧</span>).<br></font></div>'),
(186681, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن فهد تهامی، مکنّی به ابوالحسن . رجوع به علی تهامی شود.<br></font></div>'),
(186682, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن قطان فاسی، مکنّی به ابوالحسن . رجوع به علی فاسی (ابن محمدبن ...) شود.<br></font></div>'),
(186683, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن لؤلؤ. محدث بود و در سال <span class=\"hlight\" dir=\"rtl\">٤٣٧</span> هَ . ق . نزد طوسی تحصیل علم میکرد. او را کتابی است در نفی رؤیت . (از معجم المؤلفین بنقل از لسان المیزان ابن حجر ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٦</span>).<br></font></div>'),
(186684, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن مبارک، ملقّب به کمال الدین و مشهور به ابن اعمی . وی شاعر و از اهالی قاهره بود و قصیده ٔ مشهوری در مذمت خانه ٔ خویش دارد. او در سال <span class=\"hlight\" dir=\"rtl\">٦٩٢</span> هَ . ق . درگذشت . (از الاعلام زرکلی بنقل از فوات الوفیات ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨١</span>).<br></font></div>'),
(186685, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن محمد، مکنّی به ابوالحسن و مشهور به ابن ادمی و ملقّب به صدرالدین . وی از شعرا و نویسندگان و مترسلان دمشق بود. در سال <span class=\"hlight\" dir=\"rtl\">٧٦٨</span>هَ . ق . متولد شد. و چون از خواص دولت المؤید بود بارها مورد شکنجه و اذیت و آزار واقع شد و در سال <span class=\"hlight\" dir=\"rtl\">٨١٦</span> هَ . ق . در دمشق درگذشت . (از الاعلام زرکلی بنقل از الضوءاللامع ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٨</span> و مطالعالبدور ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥٤</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٨٤</span>).<br></font></div>'),
(186686, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن محمدبن ابراهیم خزرجی فاسی، مشهور به حصار و مکنّی به ابوالحسن . رجوع به علی حصار شود.<br></font></div>'),
(186687, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن محمدبن جهیر، مکنّی به ابوالقاسم و ملقّب به زعیم الدین یا زعیم الرؤساء و مشهور به ابن جهیر. وی در عهد القائم باﷲ عباسی نیز پس از المتقدی باﷲ عهده دار کتابت دیوان زمام بود. و دو بار وزارت المستظهر را نیز به عهده گرفت که مجموعاً در حدود ده سال بطول انجامید. و سرانجام در سال <span class=\"hlight\" dir=\"rtl\">٥٠٨</span> هَ . ق . درگذشت . (از الاعلام زرکلی بنقل از مرآةالزمان ج <span class=\"hlight\" dir=\"rtl\">٨</span> ص <span class=\"hlight\" dir=\"rtl\">٥٥</span> و النجوم الزاهرة ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٦</span>).<br></font></div>'),
(186688, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن محمدبن دلدارعلی نقوی نصیرآبادی . رجوع به علی نقوی شود.<br></font></div>'),
(186689, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن نصربن هارون بن ابی القاسم حسینی یا موسوی تبریزی، ملقّب به معین الدین یا صفی الدین و متخلص به قاسم و مشهور به قاسمی و شاه قاسم . عارف مشهور قرن نهم هجری . رجوع به قاسم انوار شود.<br></font></div>'),
(186690, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن محمدبن عبدالکریم بن عبدالواحد شیبانی موصلی، مشهور به ابن اثیر جزری و ملقّب به عزالدین و مکنّی به ابوالحسن . مورخ و محدث و ادیب و حافظ و لغوی و بیانی و نسابه بود که در جمادی الاولی سال <span class=\"hlight\" dir=\"rtl\">٥٥٥</span> هَ . ق . در جزیره ٔ ابن عمر متولد شد و درآنجا پرورش یافت آنگاه ساکن موصل گشت و سپس به شام سفر کرد. و در بیست وپنجم شعبان سال <span class=\"hlight\" dir=\"rtl\">٦٣٠</span> هَ . ق . درگذشت . او را بجز کتاب کامل و اللباب و اسدالغابة، کتب ذیل نیز هست : <span class=\"hlight\" dir=\"rtl\">١</span> - الجامعالکبیر فی علم البیان . <span class=\"hlight\" dir=\"rtl\">٢</span>- کتاب الجهاد. (از معجم المؤلفین بنقل از الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٨</span>. سیرالنبلاء ذهبی ج <span class=\"hlight\" dir=\"rtl\">١٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٨</span>. فهرس المؤلفین بالظاهریة تلخیص مجمعالاداب ابن فوطی ص <span class=\"hlight\" dir=\"rtl\">١٣</span>. وفیات الاعیان ابن خلکان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣٨</span>. البدایه ٔ ابن کثیر ج <span class=\"hlight\" dir=\"rtl\">١٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٩</span>. طبقات الشافعیه ٔ سبکی ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٧</span>. الذیل علی الروضتین ص <span class=\"hlight\" dir=\"rtl\">١٦٢</span>. تذکرةالحافظ ذهبی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٥</span>. شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٥</span>ص <span class=\"hlight\" dir=\"rtl\">١٣٧</span>. مختصر دول الاسلام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٢</span>. مرآةالجنان یافعی ج <span class=\"hlight\" dir=\"rtl\">٤</span>ص <span class=\"hlight\" dir=\"rtl\">٧</span>. کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">٨٢</span> و سایر صفحات . فهرس مخطوطات الظاهریة ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٣</span>. التعریف بالمؤرخین عزاوی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤</span>. هدیةالعارفین بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٠٦</span>. فهرس مخطوطات المصوره ٔ سید ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٥</span> و فهرس الخدیویة ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١١٥</span>). رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٤</span> و «ابن اثیر» شود.<br></font></div>'),
(186691, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدجعفر استرآبادی تهرانی . رجوع به علی استرآبادی شود.<br></font></div>'),
(186692, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد برکه ٔ تطوانی مغربی، مکنّی به ابوالحسن . رجوع به علی تطوانی شود.<br></font></div>'),
(186693, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد بستی شافعی، مکنّی به ابوالفتح . رجوع به ابوالفتح بستی و علی بستی شود.<br></font></div>'),
(186694, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد بسطامی، ملقّب به علاءالدین . رجوع به علی مصنفک شود.<br></font></div>'),
(186695, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد بغدادی، ملقّب به علاءالدین . رجوع به علی بغدادی شود.<br></font></div>'),
(186696, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد بکری . رجوع به علی بکری (ابن محمد...) شود.<br></font></div>'),
(186697, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد بناکتی (سیدنظام الدین ...). عارف نیمه ٔ دوم قرن هفتم هجری . رجوع به علی بناکتی شود.<br></font></div>'),
(186698, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد بیاعی . رجوع به علی بیاعی شود.<br></font></div>'),
(186699, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد ترمذی، مکنّی به ابوالحسن و مشهور به منجیک . شاعر مشهور. رجوع به منجیک ترمذی شود.<br></font></div>'),
(186700, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد تمیمی مغربی اشعری قسنطینی، مکنّی به ابوالحسن . رجوع به علی تمیمی شود.<br></font></div>'),
(186701, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد تهرانی . رجوع به علی کنی (تهرانی ) شود.<br></font></div>'),
(186702, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد تیتلاوی . رجوع به علی تیتلاوی شود.<br></font></div>'),
(186703, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد جرجانی ادریسی . او راست : تاریخ جرجان . و نیز رجوع به ادریسی (علی بن محمدبن ...) و جرجانی شود.<br></font></div>'),
(186704, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد جزار، مکنّی به ابوالحسن و ملقّب به نورالدین . رجوع به علی جزار شود.<br></font></div>'),
(186705, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد برزج کوفی شیعی، مکنّی به ابوالحسن . رجوع به علی برزج شود.<br></font></div>'),
(186706, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدجعفر حسنی حسینی یزدی (علی اکبر...). رجوع به علی اکبر یزدی شود.<br></font></div>'),
(186707, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد جمالی حنفی . رجوع به علی جمالی شود.<br></font></div>'),
(186708, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدجوادبن علی بن موسی الرضا علیهم السلام، ملقّب به نقی . دهمین امام از ائمه ٔ شیعه ٔ اثناعشریه . رجوع به ابوالحسن (علی النقی ) شود.<br></font></div>'),
(186709, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد چتالجه وی رومی حنبلی . رجوع به علی چتالجه وی شود.<br></font></div>'),
(186710, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد حجازی قاینی . رجوع به علی حجازی شود.<br></font></div>'),
(186711, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد حداد نصری، مکنّی به ابوالحسن . رجوع به علی حداد و طبسی (علی بن محمد...) شود.<br></font></div>'),
(186712, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد حر عاملی کرکی . رجوع به علی حر شود.<br></font></div>'),
(186713, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد حزوری آمدی شافعی . رجوع به علی آمدی شود.<br></font></div>'),
(186714, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدحسین بن زین العابدین، مشهور به زین التمیمی کاظمی . رجوع به علی تمیمی شود.<br></font></div>'),
(186715, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدحسین بن محمدعلی بن محمدحسین بن محمدعلی حسینی مرعشی . رجوع به علی مرعشی شود.<br></font></div>'),
(186716, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدحسین زنجانی . رجوع به علی زنجانی شود.<br></font></div>'),
(186717, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدحسین شهرستانی حائری . رجوع به علی شهرستانی شود.<br></font></div>'),
(186718, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد حسینی، مشهور به حکیم . رجوع به علی حکیم شود.<br></font></div>'),
(186719, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن نظام الدین حسنی حسینی، ملقّب به صدرالدین . رجوع به علی حسنی شود.<br></font></div>'),
(186720, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن ولید، ملقّب به والدالجمیع. رجوع به علی والدالجمیع شود.<br></font></div>'),
(186721, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن وهب مسعری . رجوع به علی مسعری شود.<br></font></div>'),
(186722, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن هلال جزائری عراقی شیعی، مشهور به ابن هلال . رجوع به علی جزائری شود.<br></font></div>'),
(186723, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن یحیی بن احمدبن عمادالدین قادری حموی، ملقّب به علاءالدین . رجوع به علی حموی شود.<br></font></div>'),
(186724, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن یحیی درینی انباری، مکنّی به ابوالحسن و ملقّب به ثقةالدولة. رجوع به علی انباری (ابن محمدبن ...) شود.<br></font></div>'),
(186725, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن یحیی سلامه ٔ صنعانی . رجوع به علی سلامة شود.<br></font></div>'),
(186726, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن یحیی سلمی سمیساطی، مکنّی به ابوالقاسم . رجوع به علی سمیساطی شود.<br></font></div>'),
(186727, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن یوسف بن مسعود قیسی قرطبی شاعر، مکنّی به ابوالحسن و مشهور به ابن خروف و ملقّب به نظام الدین . وی از اهالی قرطبه و از شعرای اندلس بود که به مشرق رفت و در حلب ساکن گشت و با قاضی آنجا (ابن شداد) مربوط شد. و در سال <span class=\"hlight\" dir=\"rtl\">٦٠٤</span> هَ . ق . در حلب درگذشت . (از الاعلام زرکلی بنقل از وفیات الاعیان ج <span class=\"hlight\" dir=\"rtl\">٢</span>ص <span class=\"hlight\" dir=\"rtl\">٣٥٨</span>، زادالمسافر ص <span class=\"hlight\" dir=\"rtl\">٢٠</span>، نفح الطیب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥٦</span>، المغرب فی حلی المغرب ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٦</span>، التکمله ٔ ابن ابار ص <span class=\"hlight\" dir=\"rtl\">٦٧٨</span>). و نیز رجوع به ابن خروف (ضیاءالدین ابوالحسن ...) شود.<br></font></div>'),
(186728, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن یوسف خروفه ٔ اندلسی رندی نحوی . رجوع به علی اشبیلی (ابن محمدبن علی بن محمدبن ... مشهور به ابن خروف ) شود.<br></font></div>'),
(186729, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن یوسف قزوینی شیعی (علی اصغر...). رجوع به علی اصغر قزوینی شود.<br></font></div>'),
(186730, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن یونس، مکنّی به ابوالفرج . مافروخی دو بیت شعر عربی از وی در «محاسن اصفهان » نقل کرده است . رجوع به محاسن اصفهان مافروخی ص <span class=\"hlight\" dir=\"rtl\">٧٣</span> شود.<br></font></div>'),
(186731, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد اخفش نحوی . رجوع به علی اخفش (ابن محمد...) شود.<br></font></div>'),
(186732, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد ادرنه وی رومی حنفی، ملقّب به مدحی و مشهور به اسکیجی زاده . رجوع به علی اسکیجی زاده شود.<br></font></div>'),
(186733, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی شربینی . رجوع به علی شربینی شود.<br></font></div>'),
(186734, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن نظام الملک سعدالدین مسعودبن علی ابهری، ملقّب به صدرالدین . وزیر سلطان علاءالدین تکش . رجوع به صدرالدین علی شود.<br></font></div>'),
(186735, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن نعمان بن محمدبن حیون، مکنّی به ابوالحسن و مشهور به ابن حیون . وی از قضات مصر و فقیهی عادل و ادیب بود و نزد خلفای فاطمی احترامی بسیار داشت . او در سال <span class=\"hlight\" dir=\"rtl\">٣٢٨</span> هَ . ق . متولد شد و با «المعز» از مغرب به مصرسفر کرد و در سال <span class=\"hlight\" dir=\"rtl\">٣٦٦</span> هَ . ق . عهده دار امر قضاوت گردید و نخستین کسی است که در مصر ملقّب به قاضی القضاة شد. او را اشعاری نیکو بود و در سال <span class=\"hlight\" dir=\"rtl\">٣٧٤</span> هَ . ق . درگذشت . (از الاعلام زرکلی بنقل از وفیات الاعیان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٧</span> و الولاة و القضاة ص <span class=\"hlight\" dir=\"rtl\">٤٩٥</span>).<br></font></div>'),
(186736, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد اسبیجابی، مکنّی به ابوالحسن و ملقّب به قطب الدین . رجوع به علی اسبیجابی شود.<br></font></div>'),
(186737, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد اسکافی نیشابوری، مکنّی به ابوالقاسم . رجوع به ابوالقاسم اسکافی شود.<br></font></div>'),
(186738, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد اشمونی شافعی، ملقب به نورالدین و مکنّی به ابوالحسن . رجوع به اشمونی و به علی اشمونی شود.<br></font></div>'),
(186739, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد امین بن موسی بن حیدربن احمد. رجوع به علی امین شود.<br></font></div>'),
(186740, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد اهوازی نحوی، مکنّی به ابوالحسن . رجوع به علی اهوازی (ابن محمد...) شود.<br></font></div>'),
(186741, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن باقر ایجی اصفهانی شیعی (علی اکبر...). رجوع به علی اکبر ایجی شود.<br></font></div>'),
(186742, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد بتارکانی طوسی حنفی، ملقّب به علاءالدین . رجوع به علی طوسی شود.<br></font></div>'),
(186743, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد بحاثی . رجوع به علی بحاثی شود.<br></font></div>'),
(186744, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن بخاری، ملقّب به علاءالدین . رجوع به علی بخاری شود.<br></font></div>'),
(186745, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد بدیهی، مکنّی به ابوالحسن، شاعر بغدادی . رجوع به علی بدیهی شود.<br></font></div>'),
(186746, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد برجی جذامی . رجوع به علی برجی شود.<br></font></div>'),
(186747, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عباس توحیدی، مکنّی به ابوحیان . صوفی و متکلم و حکیم و ادیب و لغوی و نحوی قرن چهارم هجری . رجوع به ابوحیان توحیدی و نیز به مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٥</span>. طبقات الشافعیه ٔ اسنوی ص <span class=\"hlight\" dir=\"rtl\">٥٢</span>. مناقب الشافعی و طبقات اصحابه من تاریخ الذهبی ص <span class=\"hlight\" dir=\"rtl\">٩٩</span>. اسماءالرجال الناقلین عن الشافعی و المنسوبین الیه، نوشته ٔ ابن هدایة ص <span class=\"hlight\" dir=\"rtl\">٥٧</span>. عیون التواریخ ابن شاکر کتبی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٦</span>. تاریخ ابن عدسة ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥٤</span>. التذکره ٔ طاهر جزائری . ص <span class=\"hlight\" dir=\"rtl\">٦</span>. فهرس المؤلفین بالظاهریة. الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٨</span>. سیرالنبلاء ذهبی ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦</span>. معجم الادباء یاقوت ج <span class=\"hlight\" dir=\"rtl\">١٥</span> ص <span class=\"hlight\" dir=\"rtl\">٥</span>. وفیات الاعیان ابن خلکان ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٩</span>. طبقات الشافعیه ٔ سبکی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢</span>. تهذیب الاسماء و اللغات نووی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٣</span>. طبقات الشافعیه ٔ ابن هدایة ص <span class=\"hlight\" dir=\"rtl\">٣٨</span>. شدالازار شیرازی ص <span class=\"hlight\" dir=\"rtl\">٥٣</span>. بغیةالوعاة سیوطی ص <span class=\"hlight\" dir=\"rtl\">٣٤٨</span>.مفتاح السعاده ٔ طاش کبری ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٨</span>. کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">١٤٠</span> و سایر صفحات . ایضاح المکنون بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٠٢</span> وج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>. ابوحیان توحیدی، نوشته ٔ عبدالرزاق محیی الدین . ابوحیان التوحیدی، نگاشته ٔ ابراهیم گیلانی . هدیةالاحباب عباس قمی ص <span class=\"hlight\" dir=\"rtl\">١٤</span>. امراءالبیان محمد کردعلی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٨</span>. کنوزالاجداد محمد کردعلی ص <span class=\"hlight\" dir=\"rtl\">٢٢١</span>. هدیةالعارفین بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨٤</span>. فهرس المخطوطات المصوره ٔ سید ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢٧</span>.<br></font></div>'),
(186748, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن محمدبن سلیمان نوفلی . رجوع به علی نوفلی شود.<br></font></div>'),
(186749, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن سلیم مصری، ملقب به بهاءالدین و مشهور به ابن حنا، وزیر الظاهرباﷲ فاطمی . رجوع به علی مصری (ابن محمدبن ...) شود.<br></font></div>'),
(186750, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن سلیم نوری، مکنّی ومشهور به ابوالحسن سفاقسی . رجوع به علی نوری شود.<br></font></div>'),
(186751, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن سهل صائغ دینوری، مکنّی به ابوالحسن . رجوع به علی صائغ شود.<br></font></div>'),
(186752, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن محمدبن سید نحوی بطلیوسی، مکنّی به ابوالحسن و مشهور به خیطال . رجوع به علی بطلیوسی شود.<br></font></div>'),
(186753, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن سیرماذیانی . کاتب بود و به عربی شعر هم می گفت و دیوان او پنجاه ورقه است . (از الفهرست ابن الندیم ).<br></font></div>'),
(186754, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن شاکر مؤدب لیثی واسطی . رجوع به علی مؤدب شود.<br></font></div>'),
(186755, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن شاه ظاهری بغدادی، مکنّی به ابوالقاسم . رجوع به ابن الشاه الظاهری و نیز به علی بن محمدبن الشاه الظاهری ... شود.<br></font></div>'),
(186756, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن صافی بن شجاع ربعی مالکی، مکنّی به ابوالحسن . رجوع به علی ربعی شود.<br></font></div>'),
(186757, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن صائغ کنانی . رجوع به علی کنانی شود.<br></font></div>'),
(186758, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن طیب جلابی، مکنّی به ابوالحسن . رجوع به علی جلابی شود.<br></font></div>'),
(186759, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عامر نجار مصری شافعی . رجوع به علی نجار شود.<br></font></div>'),
(186760, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عباس بن شیبان دمشقی حنبلی، مشهور به ابن اللحام و ملقّب به علأالدین و مکنّی به ابوالحسن . رجوع به علی دمشقی شود.<br></font></div>'),
(186761, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن سلیمان بن علی بن سلیمان بن حسن انصاری غرناطی، مشهور به ابن الجباب و مکنّی به ابوالحسن . رجوع به علی انصاری شود.<br></font></div>'),
(186762, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبدالحق زرویلی، مشهور به صغیر و مکنّی به ابوالحسن . رجوع به علی صغیر شود.<br></font></div>'),
(186763, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبدالحمید هیتی بغدادی دمشقی صالحی . رجوع به علی هیتی شود.<br></font></div>'),
(186764, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبدالرحمان بن احمدبن محمد بکری صدیقی مصری شافعی، مکنّی به ابوالحسن . رجوع به علی بکری شود.<br></font></div>'),
(186765, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبدالرحمان بن خطاب مغربی مصری باجی شافعی، ملقّب به علأالدین و مکنّی به ابوالحسن . رجوع به علی باجی شود.<br></font></div>'),
(186766, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبدالرحمان اجهوری مصری مالکی، مکنّی به ابوالارشاد و ملقّب به نورالدین . رجوع به علی اجهوری شود.<br></font></div>'),
(186767, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبدالرحمان اقاوی، مشهور به مراکشی . رجوع به علی مراکشی شود.<br></font></div>'),
(186768, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن محمدبن عبدالرحمان بغدادی حنفی، مشهور به آمدی و مکنّی به ابوالحسن . رجوع به علی آمدی شود.<br></font></div>'),
(186769, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبدالکریم بن دینار بصری واسطی کاتب، مکنّی به ابوالحسین . رجوع به علی بصری (ابن محمدبن ...) شود.<br></font></div>'),
(186770, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبدالرحیم بن محب الدین بن ایوب مکی شافعی، مشهور به ایوبی . رجوع به علی ایوبی شود.<br></font></div>'),
(186771, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبدالصمدبن عبدالاحدبن عبدالغالب همدانی مضری سخاوی، ملقّب به علم الدین و مکنّی به ابوالحسن . رجوع به علم الدین سخاوی شود.<br></font></div>'),
(186772, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبدالعزیزبن فتوح بن ابراهیم تغلبی موصلی دمشقی شافعی، ملقّب به تاج الدین و مشهور به ابن دریهم (<span class=\"hlight\" dir=\"rtl\">٧١٢</span> -<span class=\"hlight\" dir=\"rtl\">٧٦٢</span> هَ . ق .). او راست : <span class=\"hlight\" dir=\"rtl\">١</span> - الانصاف بالدلیل فی اوصاف النیل . <span class=\"hlight\" dir=\"rtl\">٢</span> - تصاریف الدهر فی تعاریف الاجر. <span class=\"hlight\" dir=\"rtl\">٣</span> - التصریف وحلة التعریف . <span class=\"hlight\" dir=\"rtl\">٤</span> - غایةالاعجاز فی الاحاجی و الالغاز. <span class=\"hlight\" dir=\"rtl\">٥</span>- مفتاح الکنوز فی حل الرموز. (از معجم المؤلفین بنقل از فهرس المؤلفین بالظاهریة. کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">٢٠٩</span> و سایر صفحات . هدیةالعارفین بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٢٣</span> و الاعلام زرکلی ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٨</span>). و نیز رجوع به ابن دریهم شود.<br></font></div>'),
(186773, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبداﷲ، مکنّی به ابوالحسن و مشهور به ابن سدیر. وی از اطبای قرن ششم هجری و معاصر الناصرلدین اﷲ عباسی است . مولد و منشاء وی در مداین بود و نزد اطبای بغداد تحصیل طب نموده در مداین به معالجه و مداوای مریضان پرداخت . وی در صناعت شعر نیز ماهر بود. و در دهه ٔ سوم رمضان سال <span class=\"hlight\" dir=\"rtl\">٦٠٦</span> هَ . ق . بطور ناگهانی درگذشت . «سدیر» لقب پدر اوست . (از نامه ٔ دانشوران ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤٨</span>) (از عیون الانباء ابن ابی اصیبعة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٤</span>).<br></font></div>'),
(186774, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبداﷲ، مکنّی به ابوعبداﷲ و مشهور به ابن باکو، از عرفای نیمه ٔ اول قرن پنجم هجری و معاصر القادر و القائم عباسی بود. وی از اهالی شیراز است سپس به نیشابور رفته و با امام قشیری و شیخ ابوسعید ابوالخیر و دیگر متصوفه ٔ بزرگ ملاقات کرد و او را با آنها داستانهای بسیاری است که تفصیل آن در نامه ٔ دانشوران مذکور است . وی در اواخر عمر به شیراز بازگشت و در کوهی از نواحی شیراز انزوا اختیار کرد و در سال <span class=\"hlight\" dir=\"rtl\">٤٤٢</span> هَ. ق . درگذشت . رجوع به نامه ٔ دانشوران ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٧٠</span> شود.<br></font></div>'),
(186775, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن خلف معافری مالکی، مشهور به ابن قابسی و مکنّی به ابوالحسن . محدث و حافظ و اصولی و فقیه و متکلم قرن چهارم هجری . او راست : <span class=\"hlight\" dir=\"rtl\">١</span> - الرسالة المفصلة لاحوال المتعلمین و احکام المعلمین و المتعلمین . <span class=\"hlight\" dir=\"rtl\">٢</span> - ملخص الموطأ. <span class=\"hlight\" dir=\"rtl\">٣</span>- الممهد فی الفقه و احکام الدیانة. <span class=\"hlight\" dir=\"rtl\">٤</span> - المنبه للفطن من غوائل الفتن . <span class=\"hlight\" dir=\"rtl\">٥</span> - المنقذ من شبه التأویل . رجوع به ابن قابسی (ابوالحسن ...) و نیز رجوع به مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٤</span>. سیرالنبلاءذهبی ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦</span>. الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٦</span>. فهرس المؤلفین بالظاهریة. وفیات الاعیان ابن خلکان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢٧</span>. تذکرةالحفاظ ذهبی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٤</span>. النجوم الزاهره ٔ ابن تغری بردی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٣</span>. البدایه ٔ ابن کثیر ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥١</span>. شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٨</span>. الدیباج ابن فرحون ص <span class=\"hlight\" dir=\"rtl\">١٩٩</span>. کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">١٩٠٨</span>. ایضاح المکنون بغدادی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٥٦٦</span>. مختصر دول الاسلام ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٨</span>. هدیةالعارفین بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨٥</span>.<br></font></div>'),
(186776, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن حسن بن زین الدین شهید ثانی عاملی جبعی اصفهانی، مشهور به صغیر. رجوع به علی صغیر شود.<br></font></div>'),
(186777, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن حسن بن محسن بن حسن المرتضی اعرجی کاظمی . رجوع به علی کاظمی شود.<br></font></div>'),
(186778, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن محمدبن حسن بن یوسف بن یحیی مصری، ملقّب به کمال الدین و مشهور به ابن النبیه . رجوع به علی مصری شود.<br></font></div>'),
(186779, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن حسن خلاطی حنفی، ملقّب به قادوسی و مشهور به رکابی . رجوع به علی قادوسی شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(186780, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن محمدبن حسن عبدی، مکنّی به ابوتمام و مشهور به ابن یزداد. رجوع به علی عبدی (ابن محمدبن ...) شود.<br></font></div>'),
(186781, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن حسین بن عبدالکریم بن موسی بن عیسی بن مجاهد بزودی، مکنّی به ابوالحسن و ملقّب به فخرالاسلام . رجوع به علی بزودی شود.<br></font></div>'),
(186782, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن حسین بن عبداﷲ حبشی . رجوع به علی حبشی شود.<br></font></div>'),
(186783, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن محمدبن حسین بن عبدوس کوفی، مکنّی به ابوالحسن . رجوع به علی کوفی (ابن محمدبن ...) شود.<br></font></div>'),
(186784, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن حسین بن محمدبن عمید، مکنّی به ابوالفتح و ملقّب به ذوالکفایتین . فرزند ابن عمید. رجوع به علی ذوالکفایتین شود.<br></font></div>'),
(186785, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن محمدبن حسین بن یوسف بن محمدبن عبدالعزیز بستی، مکنّی به ابوالفتح و ملقّب به نظام الدین، شاعر شهیر قرن چهارم هجری . رجوع به ابوالفتح بستی و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٨٦</span>. الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٦</span>. یتیمةالدهر ثعالبی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٤</span>. البدایه ٔ ابن کثیر ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٨</span>. کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">٧٧٢</span> و سایر صفحات . فهرس المخطوطات المصوره ٔ سید ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥٥</span>. روضات الجنات خوانساری ص <span class=\"hlight\" dir=\"rtl\">٤٨٢</span>. هدیةالعارفین بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٨٥</span>. الاعلام زرکلی چ <span class=\"hlight\" dir=\"rtl\">٢</span> ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٤</span>. وفیات الاعیان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٨</span>. ارشادالاریب ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٤٠٧</span>.<br></font></div>'),
(186786, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن خالد بلاطنسی شامی شافعی . رجوع به علی شامی شود.<br></font></div>'),
(186787, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن خلال، مکنّی به ابوالحسن . ادیب و ناسخ و دارای خطی شیوا و صحیح بود. وی در سال <span class=\"hlight\" dir=\"rtl\">٣٨١</span> هَ . ق . درگذشت . (از معجم الادباء یاقوت، چ مرگلیوث ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٧</span>).<br></font></div>'),
(186788, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن خلف اوسی قرطبی مالکی، مکنّی به ابوالحسن . رجوع به علی قرطبی شود.<br></font></div>'),
(186789, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبداﷲبن ابی سیف بصری مدائنی، مکنّی به ابوالحسن . مؤرخ و اخباری و راویه ٔ شعر. رجوع به ابوالحسن مدائنی و نیز به علی بن محمدبن ... شود.<br></font></div>'),
(186790, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن خلف نیرمانی، مکنّی به ابوسعد. رجوع به ابوسعد نیرمانی و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span>ص <span class=\"hlight\" dir=\"rtl\">١٩٥</span>. عیون التواریخ ابن شاکر کتبی ج <span class=\"hlight\" dir=\"rtl\">١٣</span> ص <span class=\"hlight\" dir=\"rtl\">٥٩</span>. الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٥</span>. فوات الوفیات ابن شاکر کتبی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٥</span>.<br></font></div>'),
(186791, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن خلیل بن محمدبن ابراهیم بن موسی حنفی، مشهور به ابن غانم مقدسی و ملقّب به نورالدین . نام او در هدیةالعارفین به صورت «علی بن محمدبن علی، مشهور به ابن غانم مقدسی » آمده است . او راست : <span class=\"hlight\" dir=\"rtl\">١</span> - اوضح رمز فی شرح نظم کنزالدقائق، در فروع فقه حنفی . <span class=\"hlight\" dir=\"rtl\">٢</span> - بغیة المرتاد لتصحیح الضاد.<span class=\"hlight\" dir=\"rtl\">٣</span> - تعلیق بر الاشباه و النظائر ابن نجیم، در فروع فقه . <span class=\"hlight\" dir=\"rtl\">٤</span> - حاشیه بر القاموس فیروزآبادی، که پسرش آن را مدوّن کرده است . <span class=\"hlight\" dir=\"rtl\">٥</span> - ردالراغب عن صلاة الرغائب . <span class=\"hlight\" dir=\"rtl\">٦</span> - رساله ای در ضاد که ظاهراً همان بغیةالمرتاد است . <span class=\"hlight\" dir=\"rtl\">٧</span> - رساله ای در وقف . رجوع به ابن غانم (نورالدین علی بن ...) و نیز به مآخذ ذیل شود:معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٥</span>. ریحانةالالبای خفاجی ص <span class=\"hlight\" dir=\"rtl\">٢٤٤</span>. هدیةالعارفین بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧٥٠</span>. کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">٩٩</span> و سایر صفحات . ایضاح المکنون بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٣</span> و ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٦٤٥</span>. فهرس الخدیویة ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٢</span>. فهرس الازهریة ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٥</span>.<br></font></div>'),
(186792, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن داوودبن ابراهیم تنوخی، مکنّی به ابوالقاسم . فقیه و اصولی ومحدث و نحوی و منطقی و متکلم و منجم و ادیب و شاعر است که در ذی حجه ٔ سال <span class=\"hlight\" dir=\"rtl\">٢٧٨</span> هَ . ق . در انطاکیه متولد شد و در ربیعالاول سال <span class=\"hlight\" dir=\"rtl\">٣٤٢</span> هَ . ق . در بصره درگذشت . او راست : <span class=\"hlight\" dir=\"rtl\">١</span>- دیوان شعر. <span class=\"hlight\" dir=\"rtl\">٢</span> - الفرج بعدالشدة. <span class=\"hlight\" dir=\"rtl\">٣</span> - کتابی در علم عروض . <span class=\"hlight\" dir=\"rtl\">٤</span> - کتابی در علم قافیه . <span class=\"hlight\" dir=\"rtl\">٥</span> - کتابی در فقه و حدیث . رجوع به ابوالقاسم تنوخی و نیز به مآخد ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٦</span>. سیرالنبلاء ذهبی ج <span class=\"hlight\" dir=\"rtl\">١٠</span> ص <span class=\"hlight\" dir=\"rtl\">١٢٤</span>. الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٦</span>. معجم الادباء یاقوت ج <span class=\"hlight\" dir=\"rtl\">١٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٦٢</span>. تاریخ بغداد خطیب بغدادی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٧</span>. النجوم الزاهره ٔ ابن تغری بردی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣١٠</span>. لسان المیزان ابن حجر ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٦</span>. بغیةالوعاة سیوطی ص <span class=\"hlight\" dir=\"rtl\">٣٤٧</span>. شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٦٢</span>. تاج التراجم ابن قطلوبغا ص <span class=\"hlight\" dir=\"rtl\">٣٣</span>. مرآة الجنان یافعی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣٤</span>. کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">٧٨١</span>. روضات الجنات خوانساری ص <span class=\"hlight\" dir=\"rtl\">٤٧٧</span>. الجواهرالمضیه ٔ قرشی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٧٢</span>.<br></font></div>'),
(186793, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن دقماق حسینی، ملقّب به زین الدین . رجوع به علی حسینی شود.<br></font></div>'),
(186794, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن رستم بن هردوز، مشهور به ابن ساعاتی و ملقّب به بهاءالدین و مکنّی به ابوالحسن . رجوع به ابن ساعاتی و علی بن رستم بن هردوز شود.<br></font></div>'),
(186795, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن رضابن محمدبن حمزه ٔ حسینی موسوی طوسی مکنّی به ابوالحسن و مشهور به ابن دفترخوان . رجوع به علی طوسی شود.<br></font></div>'),
(186796, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن رضابزاز شیرازی، موسس فرقه ٔ بابیه . رجوع به باب شود.<br></font></div>'),
(186797, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن زهران بن علی رشیدی مصری شافعی، مشهور به خضری . رجوع به علی خضری شود.<br></font></div>'),
(186798, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن سالم تغلبی آمدی حنبلی شافعی، ملقّب به سیف الدین . رجوع به علی آمدی (ابن ابی علی بن محمد....) شود.<br></font></div>'),
(186799, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن سالم طندتائی ازهری . رجوع به علی طندتائی شود.<br></font></div>'),
(186800, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن سختویه بن حمشاد، مکنّی به ابوالحسن . رجوع به علی بن حمشادبن سختویه شود.<br></font></div>'),
(186801, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن سعدبن محمدبن علی بن عثمان بن اسماعیل بن ابراهیم جبرینی حلبی طائی شافعی، مشهور به ابن خطیب الناصریة و مکنّی به ابوالحسن و ملقّب به علاءالدین . رجوع به علی حلبی شود.<br></font></div>'),
(186802, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن سلامه ٔ روحانی مقری رحبی، مکنّی به ابوالحسن . محدث و مقری بود. رجوع به علی روحانی شود.<br></font></div>'),
(186803, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن منصور المهدی لدین اﷲ. رجوع به علی مهدی شود.<br></font></div>'),
(186804, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن حسین بن علی بن ابی طالب علیهم السلام . وی به روایت شیخ مفید، یکی از هفت فرزند امام محمدباقر علیه السلام است و والده ٔ او ام ولد بود. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٧٠</span>).<br></font></div>'),
(186805, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن سکون حلی، مکنّی به ابوالحسن و مشهور به ابن سکون .رجوع به علی حلی (ابن محمدبن محمدبن علی ...) شود.<br></font></div>'),
(186806, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن سلیم دمشقی صالحی شافعی سلیمی، مکنّی به ابوالحسن و ملقّب به علاءالدین . رجوع به علی سلیمی شود.<br></font></div>'),
(186807, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن عبدالرحمان بن عراق شامی حجازی شافعی، ملقب به سعدالدین و مشهور به ابن عراق . رجوع به علی حجازی شود.<br></font></div>'),
(186808, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن فارس، مشهور به خیاط بغدادی و مکنّی به ابوالحسن . رجوع به علی خیاط شود.<br></font></div>'),
(186809, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن محمدبن حسین رباطی مغربی مالکی، مشهور به ابن بری و مکنّی به ابوالحسن . رجوع به ابن بری و نیز به مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٠</span>. ایضاح المکنون بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٦٨</span>. هدیةالعارفین بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٧١٦</span>. او را کتابی بنام «الکافی فی علم القوافی » نیز می باشد.<br></font></div>'),
(186810, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن محمدبن علی بن عبداﷲ یمنی صنعانی حنبلی، مشهور به ابن شوکانی . رجوع به علی شوکانی شود.<br></font></div>'),
(186811, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن نصربن محمدبن عبدالصمد فندروجی اسفرایینی، مکنّی به ابوالحسن . رجوع به علی قندروجی شود.<br></font></div>'),
(186812, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن محمدبن یونس بیاضی عاملی، ملقّب به زین الدین و مکنّی به ابومحمد. رجوع به علی بیاضی شود.<br></font></div>'),
(186813, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد (صلاح الدین الناصر). ابن علی (المهدی ). ابن محمد حجاج بن یوسف زیدی، مکنّی به ابوالحسن و ملقّب به نجاح الدین و المنصور، و مشهور به ابن صلاح امیر یمن . رجوع به علی زیدی (ابن محمدبن علی بن ...) شود.<br></font></div>'),
(186814, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن محمد حضرمی رندی اشبیلی اندلسی، مشهور به ابن خروف و مکنّی به ابوالحسن . رجوع به علی اشبیلی شود.<br></font></div>'),
(186815, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن محمد علوی عمری شجری، ملقّب به نجم الدین و مکنّی به ابوالحسن و مشهور به ابن صوفی . رجوع به علی شجری شود.<br></font></div>'),
(186816, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن محمد مجروتی، مکنّی به ابوالحسن . رجوع به علی مجروتی شود.<br></font></div>'),
(186817, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن محمدبن علی بن حسین بن عبدالصمد تمیمی نیشابوری سبزواری مکنّی به ابوالحسن . رجوع به علی تمیمی شود.<br></font></div>'),
(186818, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن منصور حوری، مکنّی به ابوالحسن . رجوع به علی حوری شود.<br></font></div>'),
(186819, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی ابن وهب بن مطیع قشیری شافعی، ملقّب به محی الدین و مشهور به ابن دقیق العید. رجوع به علی قشیری شود.<br></font></div>'),
(186820, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن محمدبن علی بن هبةاﷲبن احمد اسنائی مصری شافعی، ملقّب به نورالدین . رجوع به علی اسنائی شود.<br></font></div>'),
(186821, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن یوسف اشبیلی، مشهور به ابن ضائع و مکنّی به ابوالحسن . رجوع به علی اشبیلی شود.<br></font></div>'),
(186822, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن یوسف همدانی . رجوع به علی همدانی شود.<br></font></div>'),
(186823, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی ازجی ضریر، مکنّی به ابوالحسن . رجوع به علی ازجی شود.<br></font></div>'),
(186824, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی الرضاعلیهم السلام، ملقّب به نقی . دهمین امام از ائمه ٔ شیعه ٔ اثناعشری . رجوع به ابوالحسن (علی النقی ...) شود.<br></font></div>'),
(186825, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی جرجانی حسین حنفی، مشهور به سیدشریف و مکنّی به ابوالحسن . رجوع به علی جرجانی شود.<br></font></div>'),
(186826, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی جوینی، مکنّی به ابوالحسن و ملقّب به عمادالدین . رجوع به علی جوینی شود.<br></font></div>'),
(186827, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی خزاز رازی قمی، مکنّی به ابوالقاسم . رجوع به علی خزاز شود.<br></font></div>'),
(186828, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی رامشی بخاری ضریر، ملقّب به حمیدالدین . رجوع به علی رامشی شود.<br></font></div>'),
(186829, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی رضوی تبریزی نجفی، مشهور به سیدعلی داماد. رجوع به علی داماد شود.<br></font></div>'),
(186830, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی زهری شروانی مدنی حنفی . رجوع به علی شروانی شود.<br></font></div>'),
(186831, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن محمدبن عبیدبن زبیر اسدی، مشهور به ابن کوفی و مکنّی به ابوالحسن . رجوع به علی اسدی شود.<br></font></div>'),
(186832, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبداﷲبن احمد بحرانی . رجوع به علی بحرانی شود.<br></font></div>'),
(186833, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبداﷲبن عبدالظاهربن نشوان جذامی مصری سعدی، ملقب به علاءالدین . رجوع به علی سعدی شود.<br></font></div>'),
(186834, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبداﷲبن علی بن زکریا زبحی جرجانی، مکنّی به ابوالحسن . رجوع به علی زبحی شود.<br></font></div>'),
(186835, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبداﷲ افزری . رجوع به علی افزری شود.<br></font></div>'),
(186836, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبداﷲ بهرمسی محلی شافعی، ملقّب به نورالدین و مکنّی به ابومحمد. رجوع به علی محلی شود.<br></font></div>'),
(186837, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبداﷲ حموی، مشهور به ابن ملیک . از شعرای عرب . رجوع به علاءالدین بن ملیک شود.<br></font></div>'),
(186838, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبداﷲ طبیب . متوفی در سال <span class=\"hlight\" dir=\"rtl\">٨١٥</span> هَ . ق . او راست : مختصرالابزری، در طب که شامل علم ابدان و ادیان است . (از کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">١٦٢٥</span>).<br></font></div>'),
(186839, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبداﷲ فخری . رجوع به علی فخری شود.<br></font></div>'),
(186840, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبداﷲ قزوینی، مکنّی به ابوالحسن . رجوع به علی قزوینی شود.<br></font></div>'),
(186841, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبدالمحسن بن محمدبن سالم قلعی مکی حنفی . رجوع به علی قلعی شود.<br></font></div>'),
(186842, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبدالملک بن یحیی بن ابراهیم بن یحیی کتامی، مشهور به ابن قطان و مکنّی به ابوالحسن . رجوع به علی کتامی شود.<br></font></div>'),
(186843, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبدالودود مربیطری، مکنّی به ابوعیسی . رجوع به علی مربیطری شود.<br></font></div>'),
(186844, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عبدوس کوفی نحوی، مشهور به ابن عبدوس . رجوع به ابن عبدوس شود.<br></font></div>'),
(186845, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن محمد حلابی . رجوع به علی حلابی شود.<br></font></div>'),
(186846, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عثمان بن محمدبن رجب بن علاءالدین دمشقی شافعی، مشهور به ابن شمعة. رجوع به علی دمشقی شود.<br></font></div>'),
(186847, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عز اذرعی دمشقی حنفی . ملقّب به صدرالدین . رجوع به علی اذرعی شود.<br></font></div>'),
(186848, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن عقیل حنبلی عالمی بغدادی، مکنّی به ابوالفاء. رجوع به علی ظفری (ابن عقیل بن محمد...) و به ابوالفاء (علی بن ...) شود.<br></font></div>'),
(186849, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علاءالدین دواداری، مشهور به ابن کلاس . رجوع به علی دواداری و ابن کلاس شود.<br></font></div>'),
(186850, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی . نحوی و ساکن شهر تونس بود. وی در سال <span class=\"hlight\" dir=\"rtl\">١١٣٩</span> هَ . ق . درقید حیات بوده است . او راست : دفع الملم عن قراءة التسهیل بجلب المهم مما یقع به التحصیل، که شرح تسهیل الفوائد ابن مالک است . (از معجم المؤلفین بنقل از فهرس الخدیویة ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٢</span> و ایضاح المکنون بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٧٤</span>).<br></font></div>'),
(186851, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی، مشهور به ابن ابی قصیبه ٔ غزالی . رجوع به علی غزالی شود.<br></font></div>'),
(186852, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی، مشهور به ابن غانم مقدسی و ملقّب به نورالدین . رجوع به ابن غانم (نورالدین علی ) و نیز به علی بن محمدبن خلیل بن محمد... شود.<br></font></div>'),
(186853, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن ابی بکربن علی نسفی بیکندی . رجوع به علی نسفی شود.<br></font></div>'),
(186854, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن ابی لطف مقدسی شافعی، مکنّی به ابوالفضل . رجوع به علی مقدسی شود.<br></font></div>'),
(186855, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن ابی المعالی الصغیربن ابی المعالی الکبیر طباطبائی اصفهانی کاظمی حائری شیعی امامی . رجوع به علی طباطبائی شود.<br></font></div>'),
(186856, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن احمدبن مروان عمرانی خوارزمی، مکنّی به ابوالحسن . رجوع به ابوالحسن عمرانی و علی عمرانی شود.<br></font></div>'),
(186857, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدبن علی بن اسماعیل بن محمدبن علی بن احمدبن هاشم بن علوی بن حسین غریقی موسوی بحرانی . رجوع به علی موسوی شود.<br></font></div>'),
(186858, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یزید دمشقی صاحب القاسم، مکنّی به ابوعبدالملک . از روات حدیث بود و نیز رجوع به ابوعبدالملک (علی بن ...) شود.<br></font></div>'),
(186859, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یحیی بن تمیم بن معز صنهاجی، امیر افریقیه . رجوع به علی صنهاجی (ابن یحیی بن تمیم بن ...) شود.<br></font></div>'),
(186860, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یحیی بن راشد وشلی زیدی یمنی . رجوع به علی وشلی شود.<br></font></div>'),
(186861, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یحیی بن قاسم صنهاجی جزیری، مکنّی به ابوالحسن . رجوع به علی جزیری شود.<br></font></div>'),
(186862, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یحیی بن محمد بناء زیدی . رجوع به علی بناء شود.<br></font></div>'),
(186863, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یحیی بن نصربن احمد سامانی . رجوع به علی سامانی شود.<br></font></div>'),
(186864, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یحیی ارمنی، مکنّی به ابوالحسن . از فرماندهان عصر عباسی . رجوع به علی ارمنی شود.<br></font></div>'),
(186865, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن یحیی خیوانی صنعانی . رجوع به علی خیوانی شود.<br></font></div>'),
(186866, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یحیی زیادی مصری شافعی، ملقّب به نورالدین . رجوع به علی زیادی شود.<br></font></div>'),
(186867, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن یحیی زیری . رجوع به علی زیری شود.<br></font></div>'),
(186868, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یحیی سمرقندی قرمانی حنفی، ملقّب به علاءالدین . رجوع به علی سمرقندی شود.<br></font></div>'),
(186869, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یحیی عنسی، ملقّب به شمس الدین .شاعر یمانی . رجوع به علی عنسی (ابن یحیی ...) شود.<br></font></div>'),
(186870, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یحیی مخرمی، ملقّب به جمال الدین و مکنّی به ابوالحسن . رجوع به علی مخرمی شود.<br></font></div>'),
(186871, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یزداد. علی بن محمدبن حسن عبدی، مکنّی به ابوتمام و مشهور به ابن یزداد. رجوع به علی عبدی (ابن محمدبن حسن ...) شود.<br></font></div>'),
(186872, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یحیی بن احمدبن مضمون صنعانی . رجوع به علی صنعانی شود.<br></font></div>'),
(186873, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یعقوب بن جبریل بن عبدالمحسن بکری مصری شافعی، ملقّب به نورالدین مکنّی به ابوالحسن . رجوع به علی بکری شود.<br></font></div>'),
(186874, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یعقوب بن داوودبن طهمان . وی فرزند یعقوب بن داوود بودکه وقتی ابراهیم بن عبداﷲ بر ابوجعفر دوانیقی خروج کرد همراه او بوده است . این علی حکایتی درباره ٔ سبب گرفتاری و حبس پدر خود بدست مهدی خلیفه نقل کرده است که در تاریخ حبیب السیر آمده است . رجوع به حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٣</span> و دستورالوزراء خوندمیر ص <span class=\"hlight\" dir=\"rtl\">٣٠</span> شود.<br></font></div>'),
(186875, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یعقوب بن شجاع بن علی بن ابراهیم بن محمدبن ابی زهران موصلی شافعی . مکنّی به ابوالحسن و ملقّب به عمادالدین . رجوع به علی موصلی شود.<br></font></div>'),
(186876, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یعقوب طرابزونی (علی رضا...). رجوع به علی رضا (ابن یعقوب ...) شود.<br></font></div>'),
(186877, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یعیش . علی بن احمدبن عبدالرحمان بن احمدبن عبدالرحمان بن یعیش زهری باجی، مکنّی به ابوالحسن و مشهور به ابن یعیش . رجوع به علی باجی (ابن احمدبن عبدالرحمان بن ...) شود.<br></font></div>'),
(186878, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یقطین بن موسی کوفی بغدادی . رجوع به علی کوفی شود.<br></font></div>'),
(186879, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یقظان سبتی . رجوع به علی سبتی (ابن یقظان ...) شود.<br></font></div>'),
(186880, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف، مشهور به ابن بقّال و مکنّی به ابوالحسن . وی از اهالی بغداد و مدتها با مهلبی همراه بود. شاعری قوی بشمار می رفت و در علم کلام نیز دستی توانا داشت و با اینکه دارای ثروت فراوانی بود، بخل و امساک داشت . گویند مردی متکبر بود و با هیچ یک از شعرا آمدوشد نداشت و خود را برتراز همه ٔ شاعران می دانست . وفات او در عهد شرف الدولةبن عضدالدوله روی داد. یاقوت حموی بسیاری از اشعار اورا در معجم الادباء آورده است . رجوع به معجم الادباء یاقوت چ قاهره ج <span class=\"hlight\" dir=\"rtl\">١٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span> و چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠٧</span> شود.<br></font></div>'),
(186881, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف بن ابراهیم بن عبدالواحدبن موسی بن احمدبن محمدبن اسحاق شیبانی قفطی، مشهور به قاضی اکرم و مکنّی به ابوالحسن و ملقّب به جمال الدین . رجوع به علی قفطی و ابن قفطی (جمال الدین ابوالحسن علی ...) شود.<br></font></div>'),
(186882, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف بن احمد رومی حنفی فناری، ملقّب به علاءالدین . رجوع به علی فناری شود.<br></font></div>'),
(186883, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف بن احمد مصری مکی یمنی شافعی، مشهور به غزولی . رجوع به علی غزولی شود.<br></font></div>'),
(186884, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف (صلاح الدین ) ابن ایوب ایوبی، مشهور به الملک الافضل نورالدین . رجوع به علی ایوبی (ابن صلاح الدین یوسف ...) شود.<br></font></div>'),
(186885, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابن یوسف بن بالی بن محمدبن حمزه ٔ فناری . رجوع به علی فناری (این یوسف بن احمد رومی ...) شود.<br></font></div>'),
(186886, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هلال . نام او علی بن محمدبن هلال جزائری عراقی شیعی، مکنّی به ابوالحسن و مشهوربه ابن هلال است . رجوع به ابوالحسن (زین الدین علی بن هلال ...) و به علی جزائری (ابن محمدبن هلال ...) شود.<br></font></div>'),
(186887, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هارون زنجانی، مکنّی به ابوالحسن . رجوع به علی زنجانی شود.<br></font></div>'),
(186888, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هاشم بن علی رضوی موسوی بغدادی نجفی . رجوع به علی رضوی شود.<br></font></div>'),
(186889, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هاشم عراقی حسنی، مکنّی به ابوالحسن و ملقّب به زین العابدین . رجوع به علی عراقی شود.<br></font></div>'),
(186890, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هباربن اسودبن مطلب بن اسدبن عبدالعزی قرشی اسدی . رجوع به علی اسدی شود.<br></font></div>'),
(186891, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هبل . علی بن احمدبن علی بن عبدالمنعم، مشهور به ابن هبل و به خلاطی و ملقّب به مهذب الدین و مکنّی به ابوالحسن . رجوع به ابن هبل و به علی خلاطی (ابن احمدبن علی بن ...) شود.<br></font></div>'),
(186892, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هبةاﷲبن عثمان بن احمدبن ابراهیم بن رائقه ٔ موصلی، محدّث شیعی، مکنّی به ابوالحسن . رجوع به ابوالحسن (علی بن هبةاﷲبن ...) شود.<br></font></div>'),
(186893, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن هبةاﷲبن اثردی مکنّی به ابوالحسن و مشهوربه ابن اثردی . وی طبیب و از اهالی بغداد بود. او راست : شرح کتاب دعوةالاطباء ابن بطلان، که در سال <span class=\"hlight\" dir=\"rtl\">٥٠٧</span> هَ. ق . این شرح را نگاشته است . (از معجم المؤلفین بنقل از عیون الانباء ابن ابی اصیبعة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٩</span>. المخطوطات العربیه ٔ شیخو ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٤</span>. کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">٧٥٦</span>).<br></font></div>'),
(186894, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هبةاﷲبن علی بن هبةاﷲبن جعفر عجلی جرباذقانی (گلپایگانی ) بغدادی، مشهور به ابن ماکولا و ملقّب به سعدالملک و مکنّی به ابونصر. او راست : <span class=\"hlight\" dir=\"rtl\">١</span> - الاکمال فی المؤتلف و المختلف من اسمأالرجال . <span class=\"hlight\" dir=\"rtl\">٢</span> - تهذیب مستمرالاوهام علی ذوی التمنی و الاحلام . <span class=\"hlight\" dir=\"rtl\">٣</span> - مفاخرةالقلم و السیف و الدینار. رجوع به ابن ماکولا (ابونصرعلی بن ...) و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٧</span>. تاریخ دمشق ابن عساکر ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨٠</span>. سیرالنبلاء ذهبی ج <span class=\"hlight\" dir=\"rtl\">١١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٨</span>. وفیات الاعیان ابن خلکان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢٠</span>. معجم الادباء یاقوت ج <span class=\"hlight\" dir=\"rtl\">١٥</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٢</span>. المنتظم ابن جوزی ج <span class=\"hlight\" dir=\"rtl\">٩</span>ص <span class=\"hlight\" dir=\"rtl\">٥</span>. الکامل ابن اثیر ج <span class=\"hlight\" dir=\"rtl\">١٠</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣</span>. تذکرةالحفاظ ذهبی ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٢</span>. البدایه ٔ ابن کثیر ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٥</span>. النجوم الزاهره ٔ ابن تغری بردی ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">١١٥</span>. فوات الوفیات ابن شاکر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩٣</span>. شذرات الذهب ابن عماد ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٨١</span>. مرآةالجنان یافعی ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٣</span>. کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">١٦٣٧</span>. هدیةالعارفین بغدادی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٦٩٣</span>. فهرس المخطوطات المصوره ٔ لطفی عبدالبدیع ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠</span>. فهرس المخطوطات المصوره ٔ سید ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥</span>.<br></font></div>'),
(186895, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هبةاﷲ بخاری، ملقّب به جلال الدین . وزیر الناصرلدین اﷲ. رجوع به علی بخاری شود.<br></font></div>'),
(186896, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هبةاﷲ دستاوی شافعی، ملقب به نورالدین . رجوع به علی دستاوی شود.<br></font></div>'),
(186897, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هذیل . علی بن عبدالرحمان اندلسی، مشهور به ابن هذیل . رجوع به علی اندلسی (ابن عبدالرحمان اندلسی ...) شود.<br></font></div>'),
(186898, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هشام . او را پنجاه ورقه شعر است . (از الفهرست ابن الندیم ).<br></font></div>'),
(186899, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ )ابن هطیل . علی بن محمد نجری یمانی زیدی، مشهور به ابن هطیل . رجوع به علی نجری (ابن محمد نجری ...) شود.<br></font></div>'),
(186900, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف بن تاشفین لمتونی، مکنّی به ابوالحسن . دومین تن از ملوک نقابدار مرابطان در مراکش . رجوع به علی لمتونی شود.<br></font></div>'),
(186901, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هلال بغدادی، مشهور به ابن بواب و مکنّی به ابوالحسن . او را قصیده ای است رائیه که ادوات کتابت را در آن جمعآوری کرده است . رجوع به ابن بواب و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٥٨</span>. الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣</span>. کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">١٣٣٩</span>. مفتاح السعاده ٔ طاش کبری ج <span class=\"hlight\" dir=\"rtl\">١</span>ص <span class=\"hlight\" dir=\"rtl\">٧٦</span>. الخطاط البغدادی علی بن هلال المشهور به ابن البواب نوشته ٔ سهیل انور. حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠٩</span>.<br></font></div>'),
(186902, 'علی', '<span class=\"hlight\">علی .</span><font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هلال جزائری عراقی، مکنّی به ابوالحسن و ملقّب به زین الدین . رجوع به علی جزائری شود.<br></font></div>'),
(186903, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هلال کرکی . رجوع به علی کرکی شود.<br></font></div>'),
(186904, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هند قرشی، مکنّی به ابوالحسن . از مشایخ طریقت به فارس در اواخر قرن سوم و اوایل قرن چهارم هجری است . رجوع به ابوالحسن (علی بن هند) و نامه ٔ دانشوران ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤</span> شود.<br></font></div>'),
(186905, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هندو. علی بن حسین بن هندو بغدادی، مکنّی به ابوالحسن و مشهور به ابن هندو. رجوع به ابن هندو و به علی (ابن حسین بن ...) شود.<br></font></div>'),
(186906, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هیثم کاتب، مشهور به جونقا. رجوع به علی جونقا شود.<br></font></div>'),
(186907, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هیصم . علی بن عبداﷲبن محمدبن هیصم هروی، مشهور به ابن هیصم . رجوع به علی هروی (ابن عبداﷲبن محمدبن ...) شود.<br></font></div>'),
(186908, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یاسین رفیش نجفی، از آل عنوز. رجوع به علی رفیش شود.<br></font></div>'),
(186909, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یاسین طرابلسی، ملقّب به نورالدین . رجوع به علی طرابلسی (ابن یاسین ...) شود.<br></font></div>'),
(186910, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یحیی، مشهور به ابن فویره و مکنّی به ابوالحسن و ملقّب به علأالدین . فقیه حنفی بود و سالها امر قضا را به عهده داشت و در سال <span class=\"hlight\" dir=\"rtl\">٧٥٤</span> هَ . ق . درگذشت . (از معجم المؤلفین بنقل از النجوم الزاهره ٔ ابن تغری بردی ج <span class=\"hlight\" dir=\"rtl\">١٠</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩١</span>).<br></font></div>'),
(186911, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یحیی آیدینی رومی حنفی . رجوع به علی آیدینی شود.<br></font></div>'),
(186912, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یحیی بن ابی منصور منجم، مکنّی به ابوالحسن . رجوع به علی منجم شود.<br></font></div>'),
(186913, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یحیی بن احمدبن علی بن احمدبن قاسم گیلانی قادری حموی . رجوع به علی گیلانی شود.<br></font></div>'),
(186914, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مسلم بن جناب، مکنّی به ابوالحسن . تابعی بود. (منتهی الارب ).<br></font></div>'),
(186915, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مدینی . علی بن عبداﷲبن جعفربن نجیح سعدی بصری، مشهور به ابن مدینی و مکنّی به ابوالحسن . رجوع به علی بصری (ابن عبداﷲبن جعفربن ...) شود.<br></font></div>'),
(186916, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مراد. مفسر بود و در سال <span class=\"hlight\" dir=\"rtl\">١٠٨٣</span> هَ . ق .در قید حیات بوده است . او راست : انوارالقرآن فی مصباح الایمان، در تفسیر. (از معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤١</span>).<br></font></div>'),
(186917, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مراد عمری موصلی شافعی، ملقّب به نورالدین و مکنّی به ابوالفضل . رجوع به علی عمری شود.<br></font></div>'),
(186918, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مراد کاشی، ملقّب به علاءالدین . رجوع به علی کاشی (ابن مراد...) شود.<br></font></div>'),
(186919, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مرزبان . علی بن احمد بغدادی شافعی، مکنّی به ابوالحسن و مشهور به ابن مرزبان . رجوع به علی بغدادی (ابن احمد بغدادی ...) شود.<br></font></div>'),
(186920, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مره ٔ بغدادی، مکنّی به ابوالحسن . رجوع به نقاش شود.<br></font></div>'),
(186921, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن مزید اسدی، مکنّی به ابوالحسن . نخستین حکمران حله از بنی مزید اسدی . رجوع به علی مزیدی شود.<br></font></div>'),
(186922, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مسافر عدوی . رجوع به علی عدوی شود.<br></font></div>'),
(186923, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مسعده ٔ باهلی، مکنّی به ابوحبیب . تابعی بود. رجوع به علی باهلی شود.<br></font></div>'),
(186924, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مسعودبن حسین، مکنّی به ابوالحسن و ملقّب به حسام الدین . فرزند کهتر ملک فخرالدین مسعود، نخستین تن از ملوک بامیان، و مخدوم خاص نظامی عروضی مؤلف چهارمقاله . رجوع به علی (ابن فخرالدین مسعودبن عزالدین حسین ...) شود.<br></font></div>'),
(186925, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مسعودبن محمود غزنوی . ملقّب به بهاءالدولة. رجوع به علی غزنوی شود.<br></font></div>'),
(186926, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مسعود ابهری، ملقّب به صدرالدین .وزیر تکش . رجوع به علی به صدرالدین (علی ...) شود.<br></font></div>'),
(186927, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مسعود فرغانی، مکنّی به ابوسعد و ملقّب به کمال الدین . رجوع به علی فرغانی (ابن مسعود...) شود.<br></font></div>'),
(186928, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مدرک، مکنّی به ابومدرکة. راوی بود. رجوع به ابومدرکة شود.<br></font></div>'),
(186929, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مسلم بن محمدبن علی سلمی دمشقی شافعی خلوتی، مشهور به ابن سهروردی و مکنّی به ابوالحسن و ملقّب به جمال الاسلام . رجوع به علی سهروردی شود.<br></font></div>'),
(186930, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مسلم عقیلی . هفتمین تن از حکام بنی عقیل در عراق و موصل . رجوع به علی عقیلی شود.<br></font></div>'),
(186931, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مسلمة. علی بن حسن بن ابی الفرج احمد، مکنّی به ابوالقاسم و مشهور به رئیس الرؤسا. ابن مسلمة. وزیر القائم بامراﷲ عباسی . رجوع به علی (ابن حسن بن ...) شود.<br></font></div>'),
(186932, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مسهر شاعر.وی شاعر بود و ابوالمؤید محمدبن صائغ جزری مشهور به عنتری، او را درقصیده ای هجو کرده و آن ابیات در عیون الانباء آمده است . رجوع به عیون الانباء ابن ابی اصیبعة ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٩٦</span> شود.<br></font></div>'),
(186933, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مسهر کوفی، مکنّی به ابوالحسن . رجوع به علی کوفی (ابن مسهر...) شود.<br></font></div>'),
(186934, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مشاطة، مکنّی به ابوالحسن . او راست : اخبارالوزراء. (از کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>).<br></font></div>'),
(186935, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مشعشع. علی بن محمدبن فلاح، مشهور به ابن مشعشع. از نوادگان امام موسی کاظم (ع ) و از امرای دولت مشعشعی در اهواز و حویزه . رجوع به علی (ابن محمدبن فلاح ) شود.<br></font></div>'),
(186936, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مصطفی بن ابی لطف طرابلسی حنفی، مشهور به ابن کرامة. رجوع به علی طرابلسی شود.<br></font></div>'),
(186937, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مصطفی بن پیرمحمد کوتاهیه وی رومی حنفی، ملقّب به جبری و مشهور به بلبل زاده . رجوع به علی بلبل زاده شود.<br></font></div>'),
(186938, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مصطفی بن عطیةبن جعفربن احمدبن عطیه ٔ مشرفة. رجوع به علی مشرفة شود.<br></font></div>'),
(186939, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مصطفی دباغ حلمی شافعی، مشهور به میقاتی و مکنّی به ابوالفتوح . رجوع به علی میقاتی شود.<br></font></div>'),
(186940, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مصطفی قیصری رومی حنفی، مشهور به فردی . رجوع به علی فردی شود.<br></font></div>'),
(186941, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یونس بن عبداﷲ لهواری تونسی، ملقّب به نورالدین و مکنّی به ابوالحسن . رجوع به علی لهواری شود.<br></font></div>'),
(186942, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف بن حریز (یا جریر)بن فضل بن معضادبن فضل لخمی شطنوفی شافعی، ملقّب به نورالدین و مکنّی به ابوالحسن . رجوع به علی شطنوفی شود.<br></font></div>'),
(186943, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف بن حسن زرندی انصاری، ملقّب به نورالدین و مکنّی به ابوالحسن . رجوع به علی زرندی شود.<br></font></div>'),
(186944, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن یوسف بن حیدرةبن حسن رجبی، ملقّب به شرف الدین و مکنّی به ابوالحسن . رجوع به علی رجبی شود.<br></font></div>'),
(186945, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف بن رمضان موصلی حنفی، ملقّب به علاءالدین . رجوع به علی موصلی شود.<br></font></div>'),
(186946, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف بن زیان وطاسی، مکنّی به ابوحسون . وزیر عبدالحق بن عثمان در فاس . رجوع به علی وطاسی (ابن یوسف بن ...) شود.<br></font></div>'),
(186947, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف بن شیبان ماردینی، مشهور به ابن صفّار وملقّب به جلال الدین . وی در سال <span class=\"hlight\" dir=\"rtl\">٥٧٥</span> هَ . ق . در ماردین متولد شد. رجوع به ابن صفّار و مآخذ ذیل شود: معجم المؤلفین ج <span class=\"hlight\" dir=\"rtl\">٧</span> ص <span class=\"hlight\" dir=\"rtl\">٢٦٥</span>. الوافی صفدی ج <span class=\"hlight\" dir=\"rtl\">١٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٣٠</span>. فوات الوفیات ابن شاکر ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٩٧</span>. کشف الظنون حاجی خلیفه ص <span class=\"hlight\" dir=\"rtl\">١٩٩</span>.<br></font></div>'),
(186948, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف بن عبدالجلیل نیلی، ملقّب به ظهیرالدین . رجوع به علی نیلی شود.<br></font></div>'),
(186949, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف بن عبداﷲبن یوسف جوینی، مکنّی به ابوالحسن . رجوع به علی جوینی شود.<br></font></div>'),
(186950, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف بن علی بن مطهر حلی، ملقّب به رضی الدین . رجوع به علی حلی شود.<br></font></div>'),
(186951, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف ایوبی، مشهور به ملک افضل نورالدین . رجوع به علی ایوبی شود.<br></font></div>'),
(186952, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف بصری، مکنّی به ابوالحسن . رجوع به علی بصری (ابن یوسف ...) شود.<br></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(186953, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یوسف مرابطی . رجوع به علی مرابطی شود.<br></font></div>'),
(186954, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یونس . نام او علی بن عبدالرحمان بن احمدبن یونس بن عبدالاعلی صدفی مصری، مکنّی به ابوالحسن است . رجوع به ابن یونس (ابوالحسن علی بن ...) و نیز رجوع به علی (ابن عبدالرحمان بن احمدبن ...) شود.<br></font></div>'),
(186955, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن هارون الرشید عباسی . وی یکی از فرزندان هارون الرشید و مادر او امةالعزیز بود. (از حبیب السیر چ خیام ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤٦</span>).<br></font></div>'),
(186956, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن یونس عاملی نباطی بیاضی، مکنّی به ابومحمد و ملقّب به زین الدین . رجوع به علی بیاضی شود.<br></font></div>'),
(186957, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ع َ ]</font></b> (اِخ ) ابواسحاق . تابعی بود. (از منتهی الارب ).<br></font></div>'),
(186958, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b>(اِخ ) ابن محمود ریماوی . رجوع به علی ریماوی شود.<br></font></div>'),
(186959, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمود عاملی مشغرائی . رجوع به علی مشغرائی شود.<br></font></div>'),
(186960, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمود کرمانی شافعی، ملقب به ضیاءالدین . رجوع به علی کرمانی شود.<br></font></div>'),
(186961, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمودبن کعبی، مکنّی به ابوالقاسم . رجوع به علی کعبی شود.<br></font></div>'),
(186962, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ]</font></b> (اِخ ) ابن محمودمیرزا (سلطان ...) از شاهزادگان تیموری . رجوع به علی میرزا (ابن سلطان محمود...) شود.<br></font></div>'),
(186963, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمود نجفی شروانی شماخی (علی اکبر...). رجوع به علی اکبر شروانی شود.<br></font></div>'),
(186964, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محیا. علی بن محمد عباسی، مشهور به ابن محیا و ملقّب به عمادالدین . رجوع به علی عباسی (ابن محمد...) شود.<br></font></div>'),
(186965, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محیی الدین جامعی عاملی . رجوع به علی جامعی شود.<br></font></div>'),
(186966, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مخلص بابا، مشهوربه عاشق پاشای قیرشهری . رجوع به علی قیرشهری شود.<br></font></div>'),
(186967, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن مخلوف . علی بن عبداﷲبن مخلوف طرابلسی مغربی، مکنّی به ابوالحسن و مشهور به ابن مخلوف .رجوع به علی طرابلسی (ابن عبداﷲبن مخلوف ...) شود.<br></font></div>'),
(186968, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن نعمان بن محمود آلوسی بغدادی، ملقّب به علاءالدین . رجوع به علی آلوسی شود.<br></font></div>'),
(186969, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد شرنقاشی، خطیب شافعی . رجوع به علی شرنقاشی شود.<br></font></div>'),
(186970, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد شریف بکری . رجوع به علی بکری (ابن محمد...) شود.<br></font></div>'),
(186971, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد شمشاطی عدوی، مکنّی به ابوالحسن . رجوع به علی شمشاطی شود.<br></font></div>'),
(186972, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد شیرازی حنفی، ملقب به علاءالدین . رجوع به علی شیرازی شود.<br></font></div>'),
(186973, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد شیرازی عمری شافعی، ملقّب به مظفرالدین . رجوع به علی شیرازی شود.<br></font></div>'),
(186974, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمدطاهربن عبدالحمیدبن موسی بن علی بن معتوق عاملی نباطی اصفهانی، مکنّی به ابوالحسن . رجوع به علی عاملی شود.<br></font></div>'),
(186975, 'علی', '<span class=\"hlight\">علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ابن محمد طرابلسی بن ناصرالدین . امام جامع اموی دمشق . رجوع به علاءالدین (ابن ناصرالدین ) شود.<br></font></div>'),
